nce","content.159.7096":"Dark Presence","content.159.7097":"Dark Presence","content.159.7098":"Dark Presence","content.159.7099":"Dark Presence","content.159.7122":"Percedal","content.159.7125":"Percedal","content.159.7130":"Percedal","content.159.7204":"Aguabrial","content.159.7205":"Otomai","content.159.7206":"Otomai","content.159.7207":"Otomai","content.159.7208":"Otomai","content.159.7209":"Otomai","content.159.7210":"Aguabrial","content.159.7211":"Otomai","content.159.7212":"Otomai","content.159.7213":"Otomai","content.159.7214":"Otomai","content.159.7222":"Aguabrial","content.159.7249":"Old Amnesiac","content.159.7250":"Old Amnesiac","content.159.7255":"Old Amnesiac","content.159.7256":"Old Amnesiac","content.159.7279":"Kabrok","content.159.7281":"Kabrok","content.159.7283":"Kabrok","content.159.7293":"Kabrok","content.159.7294":"Kabrok","content.159.7385":"Aligias","content.159.7386":"Aligias","content.159.7387":"Aligias","content.159.7388":"Aligias","content.159.7389":"Aligias","content.159.7390":"Aligias","content.159.7391":"Aligias","content.159.7392":"Aligias","content.159.7393":"Aligias","content.159.7394":"Aligias","content.159.7395":"Aligias","content.159.7396":"Aligias","content.159.7397":"Aligias","content.159.7413":"Old Amnesiac","content.159.7415":"Old Amnesiac","content.159.7417":"Old Amnesiac","content.159.7418":"Old Amnesiac"},"es":{"content.7.1":"Jalató","content.7.2":"Jalatín negro","content.7.3":"Jefe de guerra jalató","content.7.4":"Tofu","content.7.5":"Tofona","content.7.6":"Bebé tofu","content.7.39":"Jalatín blanco","content.7.41":"Jalalínea","content.7.42":"Magmog, el Jálrog","content.7.44":"Jalató Real","content.7.87":"Pío rojo","content.7.88":"Pío azul","content.7.90":"Pío verde","content.7.94":"Diente de león diabólico","content.7.95":"Rosa demoníaca","content.7.123":"Larva azul","content.7.124":"Larva naranja","content.7.125":"Larva verde","content.7.135":"Mala semilla de girasol","content.7.138":"Diente de león pelón","content.7.182"