2_19004","event__1932_19005","event__1932_17408","event__1932_17411","event__1932_17386","event__1932_17385","event__1932_20274","event__1932_24141","reward__1932_2933"],"quest_calls":[],"dialogue_calls":[]},"scenario/-1933.lua":{"source":"bubbleNotificationId = 0\r\nNOTIFICATION_INTERVAL = 20000\r\nnotifications = {}\r\n\r\nfunction onNotificationClosed()\r\n\tif (bubbleNotificationId ~= nil  and bubbleNotificationId ~= 0) then bubbleNotificationId = 0 end\r\nend\r\n\r\nfunction pushNotification(textKey, ...)\r\n\tlocal textInfo = {textKey = textKey, textParam = unpack(arg)}\r\n    table.insert(notifications, textInfo)\r\nend\r\n\r\nfunction pushNotificationPosition(pos, textKey, ...)\r\n\tlocal textInfo = {position = pos, textKey = textKey, textParam = unpack(arg)}\r\n    table.insert(notifications, textInfo)\r\nend\r\n\r\nfunction updateNotification()\r\n\tlocal textInfo = notifications[1]\r\n\t\r\n\tif (textInfo == nil) then return end\r\n\t\r\n\tif (bubbleNotificationId == 0) then\r\n\t\tbubbleNotificationId = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_EAST\", -45, -55, false, NOTIFICATION_INTERVAL - 500, true, \"interactiveBubbleDialog4\", 30000, 25000, \"onNotificationClosed\")\r\n\tend\r\n\t\r\n\tBubbleText.setText(bubbleNotificationId, textInfo.textKey, textInfo.textParam)\r\n\t\r\n\tlocal pos = textInfo.position\r\n\tif (pos ~= nil) then\r\n\t\tlocal x, y, z = longToPosition(pos)\r\n\t\tBubbleText.addButton(bubbleNotificationId, \"compass\", \"UI.addCompass\", \"battleground.01.general.fight\", x, y, z)\r\n\tend\r\n\t\r\n\tBubbleText.show(bubbleNotificationId)\r\n\ttable.remove(notifications, 1)\r\nend\r\n\r\nfunction notifyPortalPosition(position)\r\n\tlocal x,y,z = longToPosition(position)\r\n\r\n\tUI.writeInChatPipe(3, \"offrande.portal.spawned\")\r\n\tpushNotificationPosition(portalPosition, \"offrande.portal.spawned\")\r\n\tupdateNotification()\r\n\r\n\tUI.addLandMarkNote(\"offrande.portal.poi\", 125, x, y, z, true)\r\nend\r\n\r\nfunction refreshPortalLandMarks(positionList)\r\n\tfor i=#positionList, 1, -1 do\r\n\t\tlocal pos = positionList[i]\r\n\t\t\r\n\t\tif (i > 0) then\r\n\t\t\t\tlocal x,y,z = longToPosition(positionList[i])\r\n\t\t\t\tUI.addLandMarkNote(\"offrande.portal.poi\", 125, x, y, z, true)\r\n\t\tend\r\n\tend\r\nend\n\n-- [INIT] Variables globales\n-- \nfunction event__1933_20478()\n    \nend\n\n-- [INIT] Variables locales - Inscription du Joueur\n-- Se déclenche quand un joueur est inscrit pour la première fois au challenge :\r\n-- Si c'est le main on initialite la valeur de variable à 0 avec l'action en dessous\r\n-- Si c'est un héros on ne fait rien\nfunction event__1933_20487()\n    \nend\n\n-- [INFO] Mise à jour du suivi de quête\n-- \nfunction event__1933_20493()\n    \nend\n\n-- [FRAG] Arrivée dans la zone - Applique le bonus\n-- \nfunction event__1933_20510()\n    \nend\n\n-- [FRAG] Sortie de la zone - Désapplique le bonus\n-- /!\\ Ecoute sur Instance\nfunction event__1933_20511()\n    UI.removeLandMarkNote(-1)\nend\n\n-- [INIT] Reload des landmarks\n-- \nfunction event__1933_20605(portalPos1, portalPos2, portalPos3, portalPos4)\n    UI.removeLandMarkNote(-1)\r\n    \r\n    local positionList = {portalPos1, portalPos2, portalPos3, portalPos4}\r\n    refreshPortalLandMarks(positionList)\nend\n\n-- [FRAG] Respawn cyclique des fragments\n-- \nfunction event__1933_20494()\n    \nend\n\n-- [FRAG] Interaction avec un fragment - Mise à jour variables locales\n-- \nfunction event__1933_20495()\n    \nend\n\n-- [FRAG] Interaction avec un fragment - Mise à jour variables globales\n-- \nfunction event__1933_20496()\n    \nend\n\n-- [FRAG] Début du combat - On applique le bonus\n-- \nfunction event__1933_20512()\n    \nend\n\n-- [MOB] Un trash est tué - Mise à jour variables locales\n-- \nfunction event__1933_20599()\n    \nend\n\n-- [MOB] Un trash est tué - Mise à jour variables globales\n-- \nfunction event__1933_20600()\n    \nend\n\n-- [MOB][PORTAL] Un stack de trash est tué - Spawn du portail 1\n-- \nfunction event__1933_20601(portalPos1)\n    notifyPortalPosition(portalPos1)\nend\n\n-- [MOB][PORTAL] Un stack de trash est tué - Spawn du portail 2\n-- \nfunction event__1933_20602(portalPos2)\n    notifyPortalPosition(portalPos2)\nend\n\n-- [MOB][PORTAL] Un stack de trash est tué - Spawn du portail 3\n-- \nfunction event__1933_20603(portalPos3)\n    notifyPortalPosition(portalPos3)\nend\n\n-- [MOB][PORTAL] Un stack de trash est tué - Spawn du portail 4\n-- \nfunction event__1933_20604(portalPos4)\n    notifyPortalPosition(portalPos4)\nend\n\n-- [MOB] Spawn cyclique des trash\n-- \nfunction event__1933_20486()\n    \nend\n\n-- [PORTAL] Activation d'un portail - Trick pour pas trigger 6 fois le spawn du portail\n-- \nfunction event__1933_20501()\n    \nend\n\n-- [PORTAL] Activation d'un portail - Spawn une horde de monstres\n-- \nfunction event__1933_20598(hordePosition, hordeMobId)\n    local x,y,z = longToPosition(hordePosition)\r\n    \r\n    UI.writeInChatPipe(3, \"offrande.horde.spawned\")\r\n    pushNotificationPosition(hordePosition, \"offrande.horde.spawned\")\r\n    updateNotification()\nend\n\n-- [GROUP] Une horde est tuée - Mise à jour variables locales\n-- \nfunction event__1933_20491()\n    \nend\n\n-- [GROUP] Une horde est tuée - Mise à jour variables globales\n-- \nfunction event__1933_20492()\n    \nend\n\n-- [GROUP][BOSS] Un stack de hordes tuées - Spawn des Boss\n-- \nfunction event__1933_20504(bossPosition, bossId)\n    UI.openRewardsDialog(\"offrande.reward.description\")\r\n    UI.addReward(27283)\r\n    \r\n    UI.writeInChatPipe(3, \"offrande.boss.spawned\")\r\n    pushNotification(\"offrande.boss.spawned\")\r\n    updateNotification()\nend\n\n-- [BOSS] Un Boss est vaincu - Mise à jour variables locales\n-- \nfunction event__1933_20502()\n    \nend\n\n-- [BOSS] Un Boss est vaincu - Mise à jour variables globales\n-- \nfunction event__1933_20503()\n    \nend\n\n-- False - [BOSS] Tous les Boss tués - Termine le challenge\n-- \nfunction event__1933_20505()\n    UI.removeLandMarkNote(-1)\nend\n\n-- [BOSS] Début du combat - Applique le bonus\n-- \nfunction event__1933_20519()\n    \nend\n\n-- \n-- \nfunction reward__1933_2936()\n    \nend\n\n-- \n-- \nfunction reward__1933_2935()\n    \nend\n\n-- \n-- \nfunction reward__1933_2934()\n    \nend\n\n-- \n-- \nfunction reward__1933_2938()\n    \nend\n\n","functions":["onNotificationClosed","pushNotification","pushNotificationPosition","updateNotification","notifyPortalPosition","refreshPortalLandMarks","event__1933_20478","event__1933_20487","event__1933_20493","event__1933_20510","event__1933_20511","event__1933_20605","event__1933_20494","event__1933_20495","event__1933_20496","event__1933_20512","event__1933_20599","event__1933_20600","event__1933_20601","event__1933_20602","event__1933_20603","event__1933_20604","event__1933_20486","event__1933_20501","event__1933_20598","event__1933_20491","event__1933_20492","event__1933_20504","event__1933_20502","event__1933_20503","event__1933_20505","event__1933_20519","reward__1933_2936","reward__1933_2935","reward__1933_2934","reward__1933_2938"],"quest_calls":["UI.openRewardsDialog(\"offrande.reward.description\")\r"],"dialogue_calls":[]},"scenario/-1934.lua":{"source":"\n\n-- [INIT] Initialisation - Spawn des monstres\n-- \nfunction event__1934_17391()\n    \nend\n\n","functions":["event__1934_17391"],"quest_calls":[],"dialogue_calls":[]},"scenario/-1935.lua":{"source":"\n\n-- [INIT] Initialisation - Spawn des monstres\n-- \nfunction event__1935_17391()\n    \nend\n\n","functions":["event__1935_17391"],"quest_calls":[],"dialogue_calls":[]},"scenario/-1936.lua":{"source":"\n\n-- [INIT] Initialisation - Spawn des monstres\n-- \nfunction event__1936_17391()\n    \nend\n\n","functions":["event__1936_17391"],"quest_calls":[],"dialogue_calls":[]},"scenario/-1937.lua":{"source":"\n\n-- [INIT] Variables globales + Spawn des monstres\n-- \nfunction event__1937_17382()\n    \nend\n\n-- [INIT] Variables locales - I