  BubbleText.showText(playerId, \"nation.prison.jail.finish\", 0, 60, false)\nend\n\n","functions":["event_1000_6608","event_1000_6703"],"quest_calls":[],"dialogue_calls":[]},"scenario/1001.lua":{"source":"\n\n-- Déclaration variables locales\n-- \nfunction event_1001_6612()\n    \nend\n\n-- Utilisation des limes\n-- \nfunction event_1001_6614()\n    \nend\n\n","functions":["event_1001_6612","event_1001_6614"],"quest_calls":[],"dialogue_calls":[]},"scenario/1043.lua":{"source":"playerId = Context.getPlayer()\r\npetId = Context.getPlayerPetId()\r\n\r\n\r\nfunction gobgobIdPlayInit(gobgobId, snouffleAId, snouffleBId)\n\tMobile.setMobilePosition(gobgobId, 7, 0, -24)\r\n\tMobile.setMobilePosition(snouffleAId, 11, 2, -24)\r\n\tMobile.setMobilePosition(snouffleBId, 9, 4, -24)\r\nend\r\n\n\n-- [INIT] Variables globales\n-- \nfunction event_1043_21817()\n    \nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_1043_7182(gobgobId, snouffleAId, snouffleBId)\n    --Mobile.addMobileCreationCallback(gobgobId, \"gobgobIdPlayInit\", gobgobId, snouffleAId, snouffleBId)\r\n    Mobile.setMobileDirection(playerId, 3)\r\n    \r\n    \r\n    Mobile.setMobileAnimation(playerId, \"AnimStatique\")\nend\n\n-- USER_GROUP_KILLED - Salle 01\n-- \nfunction event_1043_21818(room)\n    \nend\n\n-- USER_GROUP_KILLED - Salle 02\n-- \nfunction event_1043_21819(room)\n    \nend\n\n-- USER_GROUP_KILLED - Salle 03\n-- \nfunction event_1043_21820()\n    \nend\n\n-- Déplace le joueur vers la salle suivante\n-- \nfunction event_1043_21821()\n    \nend\n\n-- [ARCHI] Apparition de l'Archimonstre\n-- \nfunction event_1043_23956()\n    \nend\n\n","functions":["gobgobIdPlayInit","event_1043_21817","event_1043_7182","event_1043_21818","event_1043_21819","event_1043_21820","event_1043_21821","event_1043_23956"],"quest_calls":[],"dialogue_calls":[]},"scenario/1044.lua":{"source":"\n\n-- [EVENT] Le joueur a été capturé - Application Capturé + Démarrage procédure prison\n-- \nfunction event_1044_7175()\n    \nend