, -99, 0, 0)\nend\n\n-- Victoire Boss - Apparition du coffre et du TP\n-- \nfunction event_1051_7607()\n    Particle.addParticleSystem(800181, 20, -97, 0)\r\nend\n\n-- [TP] Salle 1 --> 2\n-- \nfunction event_1051_7234(fightTwoVictory)\n    if (toLong(fightTwoVictory) > 0) then\n    \tParticle.addParticleSystem(800181, 122, 5, 4)\n    \tParticle.addParticleSystem(800181, 123, 5, 4)\n    end\n    \n    Mobile.setMobileDirection(playerId, 1)\nend\n\n-- [TP] Salle 2 --> 3\n-- \nfunction event_1051_7235(fightThreeVictory)\n    if (toLong(fightThreeVictory) > 0) then\n    \tParticle.addParticleSystem(800181, 111, -98, 14)\n    \tParticle.addParticleSystem(800181, 112, -98, 14)\n    end\n    \n    Mobile.setMobileDirection(playerId, 5)\nend\n\n-- [TP] Salle 3 --> 4\n-- \nfunction event_1051_7236(lelaId, closetOne, closetTwo, closetThree, lelaCatch)\n    inBossRoom = 1\r\n    Mobile.setMobileDirection(playerId, 7)\r\n    Mobile.setMobileDirection(lelaId, 3)\r\n    Mobile.setMobileDirection(closetOne, 3)\r\n    Mobile.setMobileDirection(closetTwo, 1)\r\n    Mobile.setMobileDirection(closetThree, 3)\r\n    \r\n    if(toLong(lelaCatch) == 0) then\r\n    \tMobile.setMobileAnimationSuffix(lelaId, \"-1\")\r\n    end\nend\n\n-- [TP] Salle 4 --> 3\n-- \nfunction event_1051_7237()\n    Particle.addParticleSystem(800181, 111, -98, 14)\r\n    Particle.addParticleSystem(800181, 112, -98, 14)\r\n    \r\n    Mobile.setMobileDirection(playerId, 3)\nend\n\n-- [TP] Salle 3 --> 2\n-- \nfunction event_1051_7238()\n    Particle.addParticleSystem(800181, 122, 5, 4)\r\n    Particle.addParticleSystem(800181, 123, 5, 4)\r\n    \r\n    Mobile.setMobileDirection(playerId, 3)\nend\n\n-- [TP] Salle 2 --> 1\n-- \nfunction event_1051_7239()\n    Particle.addParticleSystem(800181, -10, -1, 18)\r\n    Particle.addParticleSystem(800181, -9, -1, 18)\r\n    \r\n    Mobile.setMobileDirection(playerId, 1)\nend\n\n-- Trigger Anim Lela\n-- \nfunction event_1051_7244()\n    function ringLightOne()\n        ringParticleOne = Particle.addParticleSystem(800188, 4, -96, 0)\n        ringLightOne = Light.addPointLight(4, -96, 0, 0.4, 0.4, 0.4, 2)\n    \tCamera.setWorldTarget(4, -96, 0)\n        invoke(1000, 1, \"ringLightTwo\")\n    end\n    \t\n    function ringLightTwo()\n        Camera.setWorldTarget(10, -103, 2)\n    \tringParticleTwo = Particle.addParticleSystem(800188, 6, -104, 0)\n        ringLightTwo = Light.addPointLight(6, -104, 0, 0.4, 0.4, 0.4, 2)\n        invoke(1000, 1, \"ringLightThree\")\n    end\n    \t\n    function ringLightThree()\n    \tringParticleThree = Particle.addParticleSystem(800188, 14, -104, 0)\n        ringLightThree = Light.addPointLight(14, -104, 0, 0.4, 0.4, 0.4, 2)\n        invoke(1000, 1, \"ringLightLela\")\n    end\n    \r\n    function ringLightLela()\r\n    \tringParticleLela = Particle.addParticleSystem(800188, 10, -101, 2)\n        ringLightLela = Light.addPointLight(10, -101, 2, 0.6, 0.6, 0.6, 2)\n    --    invoke(2000, 1, \"apsRing\")\n    \tinvoke(6500, 1, \"resetCamera\")\n    end\n    \n    \n    function resetCamera()\n    \tCamera.attachCameraToMobile(playerId)\n    --\tServer.triggerEvent(7253)\n    end\n    \n    if(inBossRoom > 0) then\r\n    \tglobalLight = Light.addGlobalLight(-0.8,  -0.8, -0.6)\n    \tSound.playSound(70500002,70)\n    \tinvoke(1000,1,\"ringLightOne\")\n    end\nend\n\n-- Désapplication de l'état de Lela\n-- \nfunction event_1051_7508(lelaId)\n    function resetLights()\r\n    \tLight.removePointLight(ringLightOne)\r\n    \tLight.removePointLight(ringLightTwo)\r\n    \tLight.removePointLight(ringLightThree)\r\n    \tLight.removePointLight(ringLightLela)\r\n    \t\r\n    \tLight.removeGlobalLight(globalLight)\r\n    \t\r\n    \tParticle.removeParticleSystem(ringParticleOne)\r\n    \tParticle.removeParticleSystem(ringParticleTwo)\r\n    \tParticle.removeParticleSystem(ringParticleThree)\r\n    \tParticle.removeParticleSystem(ringParticleLela)\r\n    end\r\n    \r\n    function apsRing()\r\n    \tParticle.addParticleSystem(APS_Apparition_Lela, 13, -100, 2)\r\n    \tParticle.addParticleSystem(APS_Apparition_Lela, 13, -104, 2)\r\n    \tParticle.addParticleSystem(APS_Apparition_Lela, 7, -100, 2)\r\n    \tParticle.addParticleSystem(APS_Apparition_Lela, 7, -104, 2)\r\n    \tresetLights()\r\n    end\r\n    \r\n    if(inBossRoom > 0) then\r\n    \tinvoke(3000, 1, \"apsRing\")\r\n    \tMobile.setMobileAnimationSuffix(lelaId, \"\")\r\n    \tMobile.setMobileAnimation(lelaId, \"AnimComp-Combat-1\")\r\n    end\nend\n\n-- Activation du comportement de Lela\n-- \nfunction event_1051_7511()\n    \nend\n\n-- Désinscription à la sortie de l'instance\n-- \nfunction event_1051_7608()\n    inBossRoom = 0\nend\n\n","functions":["event_1051_7243","event_1051_7221","event_1051_7240","event_1051_7241","event_1051_7242","event_1051_7252","event_1051_7607","event_1051_7234","event_1051_7235","event_1051_7236","event_1051_7237","event_1051_7238","event_1051_7239","event_1051_7244","ringLightOne","ringLightTwo","ringLightThree","ringLightLela","resetCamera","event_1051_7508","resetLights","apsRing","event_1051_7511","event_1051_7608"],"quest_calls":[],"dialogue_calls":[]},"scenario/1071.lua":{"source":"playerId = Context.getPlayer()\r\n\r\n\r\n\n\n-- INITIALISATION\n-- \nfunction event_1071_7762()\n    \nend\n\n-- [MDC] Fin du combat\n-- \nfunction event_1071_7622()\n    \nend\n\n-- [MDC] Arrivé au waypoint\n-- \nfunction event_1071_7623()\n    \nend\n\n-- [MONDE] Le joueur creuse pour le warp de la carte\n-- \nfunction event_1071_11364()\n    \nend\n\n-- [MONDE] Le joueur creuse pour le warp du Péroucan\n-- \nfunction event_1071_11365()\n    \nend\n\n-- [Quête Peroucan] On retire l'ancien Peroucan ayant perdu la flamme au joueur\n-- \nfunction event_1071_19104()\n    \nend\n\n","functions":["event_1071_7762","event_1071_7622","event_1071_7623","event_1071_11364","event_1071_11365","event_1071_19104"],"quest_calls":[],"dialogue_calls":[]},"scenario/1098.lua":{"source":"\n\n-- [INIT] Variables Globales\