playerId , \"AnimEmote-Huss-Boucle\")\r\n    Particle.addParticleSystemToTarget(APS_application, playerId)\r\nend\n\n-- [SOURCE STASIS] Cristal - Le joueur choppe l'état level 02\n-- \nfunction event_1182_8498()\n    Mobile.setMobileAnimation(playerId , \"AnimEmote-Huss-Boucle\")\r\n    Particle.addParticleSystemToTarget(APS_application, playerId)\r\nend\n\n-- [SOURCE STASIS] Cristal - Le joueur choppe l'état level 03\n-- \nfunction event_1182_8499()\n    Mobile.setMobileAnimation(playerId , \"AnimEmote-Huss-Boucle\")\r\n    Particle.addParticleSystemToTarget(APS_application, playerId)\r\nend\n\n","functions":["doorAManager","doorBManager","doorCManager","doorDManager","doorEManager","doorFManager","cristalManager","event_1182_8488","event_1182_8489","event_1182_8491","event_1182_8492","event_1182_8493","event_1182_8494","event_1182_8495","event_1182_8496","event_1182_8504","event_1182_8505","event_1182_8497","event_1182_8498","event_1182_8499"],"quest_calls":[],"dialogue_calls":[]},"scenario/1206.lua":{"source":"playerId = Context.getPlayer()\n\n-- [COFFRE] Passage de Oiram - Le joueur a le champignon\n-- \nfunction event_1206_8777()\n    InteractiveElement.setAnimation(10809,\"AnimTrans_1_3_1\")\r\n    UI.writeLocalisedInChat(\"incarnam.intro.itemAlreadyAquired\")\nend\n\n-- [COFFRE] Passage de Oiram - Le joueur n'a pas le champignon\n-- \nfunction event_1206_8778()\n    InteractiveElement.setAnimation(10809,\"AnimTrans_1_3_1\")\r\n    Particle.addParticleSystem(800120, 252,121, 0)\r\n    path = Pixmap.getItemPath(10360)\r\n    invoke(500, 1, \"Flying.addFlyingImageIE\", 10809, path)\nend\n\n-- [COFFRE] Grotte Hépaite - Le joueur a le champignon\n-- \nfunction event_1206_8779()\n    InteractiveElement.setAnimation(20811,\"AnimTrans_1_3_1\")\r\n    UI.writeLocalisedInChat(\"incarnam.intro.itemAlreadyAquired\")\nend\n\n-- [COFFRE] Grotte Hépaite - Le joueur n'a pas le champignon\n-- \nfunction event_1206_8780()\n    InteractiveElement.setAnimation(10811,\"AnimTrans_1_3_1\")\r\n    Particle.addParticleSystem(800120, 242,41, 0)\r\n    path = Pixmap.getItemPath(10307)\r\n    invoke(500, 1, \"Flying.addFlyingImageIE\", 10811, path)\nend\n\n","functions":["event_1206_8777","event_1206_8778","event_1206_8779","event_1206_8780"],"quest_calls":[],"dialogue_calls":[]},"scenario/1224.lua":{"source":"\n\n-- [INITIALISATION] Serveur\n-- \nfunction event_1224_8947()\n    \nend\n\n-- [INITIALISATION] Joueur\n-- \nfunction event_1224_8948(callbackPasserelle, callbackChest)\n    passerelle = toLong(callbackPasserelle)\r\n    chest=toLong(callbackChest)\r\n    \r\n    if passerelle==0 then\r\n    \tWorld.setPictoAlpha(24, 16, 0, 0, 1)\r\n    \tWorld.setPictoAlpha(24, 15, 0, 0, 1)\r\n    \tWorld.setPictoAlpha(24, 14, 0, 0, 1)\r\n    \tWorld.setPictoAlpha(32, 6, 0, 0, 1)\r\n    \tWorld.setPictoAlpha(33, 6, 0, 0, 1)\r\n    \tWorld.setPictoAlpha(34, 6, 0, 0, 1)\r\n    \tWorld.setPictoAlpha(35, 6, 0, 0, 1)\r\n    \tWorld.setPictoAlpha(52, -4, 0, 0, 1)\r\n    \tWorld.setPictoAlpha(52, -5, 0, 0, 1)\r\n    \tWorld.setPictoAlpha(53, -4, 0, 0, 1)\r\n    \tWorld.setPictoAlpha(53, -5, 0, 0, 1)\r\n    \tWorld.setPictoAlpha(44, -36, 4, 0, 1)\r\n    \tWorld.setPictoAlpha(43, -36, 4, 0, 1)\r\n    \tWorld.setPictoAlpha(44, -35, 4, 0, 1)\r\n    \tWorld.setPictoAlpha(43, -35, 4, 0, 1)\r\n    elseif passerelle==1 then\r\n    \tWorld.setPictoAlpha(24, 16, 0, 1, 1)\r\n    \tWorld.setPictoAlpha(24, 15, 0, 1, 1)\r\n    \tWorld.setPictoAlpha(24, 14, 0, 1, 1)\r\n    \tWorld.setPictoAlpha(32, 6, 0, 0, 1)\r\n    \tWorld.setPictoAlpha(33, 6, 0, 0, 1)\r\n    \tWorld.setPictoAlpha(34, 6, 0, 0, 1)\r\n    \tWorld.setPictoAlpha(35, 6, 0, 0, 1)\r\n    \tWorld.setPictoAlpha(52, -4, 0, 0, 1)\r\n    \tWorld.setPictoAlpha(52, -5, 0, 0, 1)\r\n    \tWorld.setPictoAlpha(53, -4, 0, 0, 1)\r\n    \tWorld.setPictoAlpha(53, -5, 0, 0, 1)\r\n    \tWorld.setPictoAlpha(44, -36, 4, 0, 1)\r\n    \tWorld.setPictoAlpha(43, -36, 4, 0, 1)\r\n    \tWorld.setPictoAlpha(44, -35, 4, 0, 1)\r\n    \tWorld.setPictoAlpha(43, -35, 4, 0, 1)\r\n    elseif passerelle==2 then\r\n    \tWorld.setPictoAlpha(24, 16, 0, 1, 1)\r\n    \tWorld.setPictoAlpha(24, 15, 0, 1, 1)\r\n    \tWorld.setPictoAlpha(24, 14, 0, 1, 1)\r\n    \tWorld.setPictoAlpha(32, 6, 0, 1, 1)\r\n    \tWorld.setPictoAlpha(33, 6, 0, 1, 1)\r\n    \tWorld.setPictoAlpha(34, 6, 0, 1, 1)\r\n    \tWorld.setPictoAlpha(35, 6, 0, 1, 1)\r\n    \tWorld.setPictoAlpha(52, -4, 0, 0, 1)\r\n    \tWorld.setPictoAlpha(52, -5, 0, 0, 1)\r\n    \tWorld.setPictoAlpha(53, -4, 0, 0, 1)\r\n    \tWorld.setPictoAlpha(53, -5, 0, 0, 1)\r\n    \tWorld.setPictoAlpha(44, -36, 4, 0, 1)\r\n    \tWorld.setPictoAlpha(43, -36, 4, 0, 1)\r\n    \tWorld.setPictoAlpha(44, -35, 4, 0, 1)\r\n    \tWorld.setPictoAlpha(43, -35, 4, 0, 1)\r\n    elseif passerelle==3 then\r\n    \tWorld.setPictoAlpha(24, 16, 0, 1, 1)\r\n    \tWorld.setPictoAlpha(24, 15, 0, 1, 1)\r\n    \tWorld.setPictoAlpha(24, 14, 0, 1, 1)\r\n    \tWorld.setPictoAlpha(32, 6, 0, 1, 1)\r\n    \tWorld.setPictoAlpha(33, 6, 0, 1, 1)\r\n    \tWorld.setPictoAlpha(34, 6, 0, 1, 1)\r\n    \tWorld.setPictoAlpha(35, 6, 0, 1, 1)\r\n    \tWorld.setPictoAlpha(52, -4, 0, 1, 1)\r\n    \tWorld.setPictoAlpha(52, -5, 0, 1, 1)\r\n    \tWorld.setPictoAlpha(53, -4, 0, 1, 1)\r\n    \tWorld.setPictoAlpha(53, -5, 0, 1, 1)\r\n    \tWorld.setPictoAlpha(44, -36, 4, 0, 1)\r\n    \tWorld.setPictoAlpha(43, -36, 4, 0, 1)\r\n    \tWorld.setPictoAlpha(44, -35, 4, 0, 1)\r\n    \tWorld.setPictoAlpha(43, -35, 4, 0, 1)\r\n    elseif passerelle==4 then\r\n    \tWorld.setPictoAlpha(24, 16, 0, 1, 1)\r\n    \tWorld.setPictoAlpha(24, 15, 0, 1, 1)\r\n    \tWorld.setPictoAlpha(24, 14, 0, 1, 1)\r\n    \tWorld.setPictoAlpha(32, 6, 0, 1, 1)\r\n    \tWorld.setPictoAlpha(33, 6, 0, 1, 1)\r\n    \tWorld.setPictoAlpha(34, 6, 0, 1, 1)\r\n    \tWorld.setPictoAlpha(35, 6, 0, 1, 1)\r\n    \tWorld.setPictoAlpha(52, -4, 0, 1, 1)\r\n    \tWorld.setPictoAlpha(52, -5, 0, 1, 1)\r\n    \tWorld.setPictoAlpha(53, -4, 0, 1, 1)\r\n    \tWorld.setPictoAlpha(53, -5, 0, 1, 1)\r\n    \tWorld.setPictoAlpha(44, -36, 4, 1, 1)\r\n    \tWorld.setPictoAlpha(43, -36, 4, 1, 1)\r\n    \tWorld.setPictoAlpha(44, -35, 4, 1, 1)\r\n    \tWorld.setPictoAlpha(43, -35, 4, 1, 1)\r\n    end\r\n    \r\n    if chest==0 then\r\n    \tWorld.setPictoAlpha(60, 0, -3, 0, 1)\r\n    \tWorld.setPictoAlpha(60, -1, -3, 0, 1)\r\n    \tWorld.setPictoAlpha(60, -2, -3, 0, 1)\r\n    \tWorld.setPictoAlpha(60, -3, -3, 0, 1)\r\n    \tWorld.setPictoAlpha(61, 0, -3, 0, 1)\r\n    \tWorld.setPictoAlpha(61, -1, -3, 0, 1)\r\n    \tWorld.setPictoAlpha(61, -2, -3, 0, 1)\r\n    \tWorld.setPictoAlpha(61, -3, -3, 0, 1)\r\n    end\nend\n\n-- [COMBAT] Victoire Salle 1\n-- \nfunction event_1224_8961()\n    \nend\n\n-- [COMBAT] Victoire Salle 1 - On déverouille la porte\n-- \nfunction event_1224_8962()\n    \tWorld.setPictoAlpha(24, 16, 0, 1, 1000)\r\n    \tWorld.setPictoAlpha(24, 15, 0, 1, 1000)\r\n    \tWorld.setPictoAlpha(24, 14, 0, 1, 1000)\nend\n\n-- [COMBAT] Victoire Salle 2\n-- \nfunction event_1224_8963()\n    \nend\n\n-- [COMBAT] Victoire Salle 2 - On déverouille la porte\n-- \nfunction event_1224_8964()\n    World.setPictoAlpha(32, 6, 0, 1, 1000)\r\n    World.setPictoAlpha(33, 6, 0, 1, 1000)\r\n    World.setPictoAlpha(34, 6, 0, 1, 1000)\r\n    World.setPictoAlpha(35, 6, 0, 1, 1000)\r\nend\n\n-- [COMBAT] Victoire Salle 3\n-- \nfunction event_1224_8965()\n    \nend\n\n-- [COMBAT] Victoire Salle 3 - On déverouille la porte\n-- \nfunction event_1224_8966()\n    World.setPictoAlpha(52, -4, 0, 1, 1000)\r\n    World.setPictoAlpha(52, -5, 0, 1, 1000)\r\n    World.setPictoAlpha(53, -4, 0, 1, 1000)\r\n    World.setPictoAlpha(53, -5, 0, 1, 1000)\r\nend\n\n-- [COMBAT] Victoire Salle 4 - BOSS\n-- \nfunction event_1224_9454()\n    \nend\n\n-- [COMBAT] Victoire Salle 4 - On active le TP et le coffre\n-- \nfunction event_1224_9455()\n    Particle.addParticleSystem(800181, 15, -26, 20, 0)\nend\n\n-- [LEVIER] Levier 1\n-- \nfunction event_1224_9458()\n    \nend\n\n-- [LEVIER] Levier 2\n-- \nfunction event_1224_9459()\n    \nend\n\n-- [LEVIER] Levier 3\n-- \nfunction event_1224_9460()\n    \nend\n\n-- [LEVIER] Apparition du spot d'archimonstre\n-- \nfunction event_1224_9461()\n    World.setPictoAlpha(60, 0, -3, 1, 1000)\r\n    World.setPictoAlpha(60, -1, -3, 1, 1000)\r\n    World.setPictoAlpha(60, -2, -3, 1, 1000)\r\n    World.setPictoAlpha(60, -3, -3, 1, 1000)\r\n    World.setPictoAlpha(61, 0, -3, 1, 1000)\r\n    World.setPictoAlpha(61, -1, -3, 1, 1000)\r\n    World.setPictoAlpha(61, -2, -3, 1, 1000)\r\n    World.setPictoAlpha(61, -3, -3, 1, 1000)\nend\n\n-- [SPECIAL] Apparition de l'archimonstre\n-- \nfunction event_1224_9462(archiId, archiTeamOne, archiTeamTwo)\n    Mobile.setMobileVisible(archiTeamOne, false)\r\n    Mobile.setMobileVisible(archiTeamTwo, false)\r\n    Mobile.setMobileAnimation(archiId, \"AnimGerbedEau\", \"animArchi\", archiId,archiTeamOne,archiTeamTwo)\r\n    \r\n    function animArchi(archiId,archiTeamOne,archiTeamTwo)\n    \tMobile.setMobileAnimation(archiId, \"AnimApparition\", \"archiTeam\", archiId, archiTeamOne,archiTeamTwo)\n    end\r\n    \r\n    function archiTeam(archiId,archiTeamOne,archiTeamTwo)\n    \tMobile.setMobileVisible(archiId, true)\r\n    \tMobile.setMobileVisible(archiTeamOne, true)\r\n    \tMobile.setMobileVisible(archiTeamTwo, true)\n    end\nend\n\n-- Lancement du combat de la salle 02\n-- \nfunction event_1224_9464()\n    \nend\n\n-- Lancement du combat de la salle 03\n-- \nfunction event_1224_9465()\n    \nend\n\n-- Lancement du combat de la salle 04\n-- \nfunction event_1224_9466()\n    \nend\n\n","functions":["event_1224_8947","event_1224_8948","event_1224_8961","event_1224_8962","event_1224_8963","event_1224_8964","event_1224_8965","event_1224_8966","event_1224_9454","event_1224_9455","event_1224_9458","event_1224_9459","event_1224_9460","event_1224_9461","event_1224_9462","animArchi","archiTeam","event_1224_9464","event_1224_9465","event_1224_9466"],"quest_calls":[],"dialogue_calls":[]},"scenario/1229.lua":{"source":"\n\n-- Enregistrement des Evènements : Début\n-- \nfunction event_1229_9006()\n    \nend\n\n-- Enregistrement des Evènements : Fin\n-- \nfunction event_1229_17876()\n    \nend\n\n-- Enregistrement des Evènements Cyclique : Spawn de monstres\n-- Toutes les X min, on spawn les groupes de monstres\nfunction event_1229_17859()\n    \nend\n\n","functions":["event_1229_9006","event_1229_17876","event_1229_17859"],"quest_calls":[],"dialogue_calls":[]},"scenario/1230.lua":{"source":"\n\n-- [INIT] Active les IE liés à l'Event\n-- Les IE doivent être initialement non utilisable pour que ce soit cohérent\nfunction event_1230_9007()\n    \nend\n\n-- [INIT] Initialise les Monstres NPC liés à l'Event\n-- Les Groupes doivent être initialement non spawn\nfunction event_1230_17879()\n    \nend\n\n","functions":["event_1230_9007","event_1230_17879"],"quest_calls":[],"dialogue_calls":[]},"scenario/1234.lua":{"source":"\n\n-- [INIT] Désactive les IE liés à l'Event\n-- Les IE doivent être initialement non utilisable pour que ce soit cohérent\nfunction event_1234_9015()\n    \nend\n\n-- [INIT] Despawn les Monstres NPC liés à l'Event\n-- Les Groupes doivent être initialement non spawn\nfunction event_1234_17875()\n    \nend\n\n-- [INIT] Despawn les Monstres Cyclique liés à l'Event\n-- \nfunction event_1234_17880()\n    \nend\n\n","functions":["event_1234_9015","event_1234_17875","event_1234_17880"],"quest_calls":[],"dialogue_calls":[]},"scenario/1277.lua":{"source":"playerId = Context.getPlayer()\r\n\r\n\r\n--== FONCTIONS ==--\r\nfunction scenarioMode()\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\t\t\t\t\t\t\t\t\t\t\t\t-- Ferme l'inventaire\r\n\tUI.setShortcutEnabled(false)\t\t\t\t\t\t-- désactive les shortcuts\r\n    UI.manageFrame(\"World\",false) \t\t\t\t\t-- Désactive le déplacement\r\n\tUI.setUIVisible(false)\r\n    Camera.setZoomFactor(1)\r\nend\r\n\r\nfunction scenarioModeEnd()\r\n\tCamera.setUserZoomLocked(false)\r\n\tUI.setShortcutEnabled(true)\t\t\t\t\t\t\r\n    UI.manageFrame(\"World\",true) \t\t\t\t\t\r\n\tUI.setUIVisible(true)\r\nend\r\n\r\nfunction ogrestPlayInit(ogrestId)\r\n\tMobile.setMobileAnimation(ogrestId, \"AnimStatiqueAssis\")\r\nend\r\n\r\nfunction ulluPlayInit(telocheId)\r\n\tMobile.setMobileAnimationStaticKey(telocheId, \"AnimStatique-Zinit\")\r\nend\r\n\r\nfunction hibossPlayInit(hibossId)\r\n\tMobile.setMobileAnimationStaticKey(hibossId, \"AnimStatique-Zinit\")\r\nend\r\n\r\nfunction initStorm()\r\n\ttimerOne=(math.random(3)+1)*1000\r\n\ttimerTwo=(math.random(3)+1)*1000\r\n\tinvoke(timerOne, 1, \"Particle.addParticleSystem\",7277001, -7, 28, 40, 0)\t\r\n\tinvoke(timerTwo, 1, \"Particle.addParticleSystem\",7277001, 14, -25, 40, 0)\t\r\n\tinvoke(timerOne, 1, \"Effect.createCameraShakeEffect\",70,7)\r\n\tinvoke(timerTwo, 1, \"Effect.createCameraShakeEffect\",70,7)\r\n\tinstanceId = Context.getPlayerInstanceId()\t\r\n\tif instanceId==277 then\r\n\t\tinvoke(6000, 1, \"initStorm\")\r\n\tend\r\nend\n\n-- Récupération des ids\n-- \nfunction event_1277_9370()\n    \nend\n\n-- Arrivée du joueur dans l'instance (première fois)\n-- \nfunction event_1277_9356(hibossId, ogrestId, ulluId, telocheId)\n    \r\n    Mobile.setMobileVisible(hibossId, false)\r\n    Mobile.setMobileDirection(playerId, 7)\r\n    Mobile.addMobileCreationCallback(ogrestId, \"ogrestPlayInit\", ogrestId)\r\n    Mobile.addMobileCreationCallback(telocheId, \"ulluPlayInit\", telocheId)\r\n    Mobile.addMobileCreationCallback(hibossId, \"hibossPlayInit\", hibossId)\r\n    initStorm()\nend\n\n-- Arrivée du joueur dans l'instance (le joueur est déjà venu)\n-- \nfunction event_1277_9867(hibossId, ogrestId, ulluId, telocheId)\n    Mobile.setMobileVisible(ogrestId, false)\r\n    Mobile.setMobileDirection(hibossId, 1)\r\n    Mobile.setMobileDirection(playerId, 7)\r\n    Mobile.addMobileCreationCallback(telocheId, \"ulluPlayInit\", telocheId)\r\n    Mobile.addMobileCreationCallback(hibossId, \"hibossPlayInit\", hibossId)\r\n    initStorm()\nend\n\n-- Lancement du dial de Téloche\n-- \nfunction event_1277_9359()\n    \nend\n\n-- Le joueur annule le dialogue\n-- \nfunction event_1277_9360()\n    \nend\n\n-- Fin du dialogue d'intro\n-- \nfunction event_1277_9369(telocheId, hibossId)\n    scenarioMode()\r\n    telocheDialId = 0\r\n    hibossDialId = 0\r\n    invoke(500, 1, \"apparitionHiboss\")\r\n    \r\n    function apparitionHiboss()\r\n    \tMobile.setMobileVisible(hibossId, true)\r\n    \tMobile.setMobileDirection(playerId, 5)\r\n    \tMobile.setMobileDirection(hibossId, 3)\r\n    \tMobile.setMobileAnimation(playerId, \"AnimEmote-GratteGratte\")\t\r\n    \tMobile.setMobileAnimation(hibossId, \"AnimAtterissage\")\r\n    \tinvoke(1500, 1, \"dialHibossOne\")\n    end\r\n    \r\n    function dialHibossOne()\r\n    \tMobile.setMobileAnimation(hibossId, \"AnimComp07\")\r\n    \thibossDialId = BubbleText.setCharacterSpeak(hibossId, \"zinit.intro.hiboss.dial1\")\r\n    --\tinvoke(1000, 1, \"BubbleText.close\", telocheDialId)\n    \tinvoke(3000, 1, \"dialTelocheTwo\")\r\n    end\r\n    \r\n    function dialTelocheTwo()\r\n    \tMobile.setMobileAnimation(telocheId, \"AnimComp-Non\")\r\n    \tMobile.setMobileDirection(playerId, 7)\r\n    \ttelocheDialId = BubbleText.setCharacterSpeak(telocheId, \"zinit.intro.teloche.dial2\")\r\n    --\tinvoke(1000, 1, \"BubbleText.close\", hibossDialId)\n    \tinvoke(3000, 1, \"dialHibossTwo\")\r\n    end\r\n    \r\n    function dialHibossTwo()\r\n    \tMobile.setMobileAnimation(hibossId, \"AnimComp05\")\r\n    \thibossDialId = BubbleText.setCharacterSpeak(hibossId, \"zinit.intro.hiboss.dial2\")\r\n    --\tinvoke(1000, 1, \"BubbleText.close\", telocheDialId)\n    \tinvoke(3000, 1, \"dialTelocheThree\")\r\n    end\r\n    \r\n    function dialTelocheThree()\r\n    \tMobile.setMobileAnimation(telocheId, \"AnimComp-Ataaaque\")\r\n    \tMobile.setMobileAnimation(playerId, \"AnimEmote-DormirDebout-Debut\")\t\r\n    \ttelocheDialId = BubbleText.setCharacterSpeak(telocheId, \"zinit.intro.teloche.dial3\")\r\n    --\tinvoke(1000, 1, \"BubbleText.close\", hibossDialId)\n    \tinvoke(3000, 1, \"dialTelocheFour\")\r\n    end\r\n    \r\n    function dialTelocheFour()\t\r\n    \tMobile.setMobileAnimation(hibossId, \"AnimComp03\")\r\n    \tMobile.setMobileAnimation(playerId, \"AnimEmote-DormirDebout-Fin\")\t\n    \tinvoke(2000, 1, \"scenarioModeEnd\")\r\n    end\nend\n\n-- Le joueur choisi Hiboss\n-- \nfunction event_1277_9374()\n    \nend\n\n-- Le joueur choisi Teloche\n-- \nfunction event_1277_9375(ogrestId)\n    scenarioMode()\r\n    Mobile.onPathEnded(playerId, \"playerPathEnded\")\r\n    \r\n    function playerPathEnded()\r\n    \tCamera.setWorldTarget(3, -24, 40)\r\n    \tMobile.setMobileDirection(playerId, 7)\r\n    \tMobile.setMobileAnimation(playerId, \"AnimStatique03-Debut-219\")\r\n    \tBubbleText.setCharacterSpeak(playerId, \"zinit.intro.player.dialOgrest\")\r\n    \tinvoke(3000, 1, \"dialOgrest\")\r\n    end\r\n    \r\n    function dialOgrest()\r\n    \tBubbleText.setCharacterSpeak(ogrestId, \"zinit.intro.ogrest.dial1\")\r\n    \tinvoke(3000, 1, \"playerTeleport\")\r\n    end\r\n    \r\n    function playerTeleport()\r\n    \tServer.triggerEvent(8691)\r\n    end\nend\n\n-- Le joueur arrive en haut du Mont\n-- \nfunction event_1277_9413(ogrestId)\n    scenarioMode()\r\n    Mobile.onPathEnded(playerId, \"Camera.setWorldTarget\",3, -32, 61)\r\n    invoke(1200, 1, \"pathEnded\",ogrestId)\r\n    Camera.setZoomFactor(0.5)\r\n    Camera.setUserZoomLocked(true)\r\n    \r\n    \r\n    function pathEnded(ogrestId)\r\n    \tMobile.setMobileDirection(playerId, 7)\r\n    \tMobile.setMobileAnimation(playerId, \"AnimStatique03-Debut-219\")\r\n    \tinvoke(3000, 1, \"dialOgrest\")\r\n    \tMobile.setMobileAnimation(ogrestId, \"AnimComp-Sanglot\",\t\"ogrestOne\",ogrestId)\r\n    end\r\n    \r\n    function ogrestOne(ogrestId)\r\n    \tMobile.setMobileAnimation(ogrestId, \"AnimComp-EssuiNez\", \"ogrestTwo\",ogrestId)\r\n    end\r\n    \r\n    function ogrestTwo(ogrestId)\r\n    \tMobile.setMobileAnimation(ogrestId, \"AnimComp-Sanglot2\", \"ogrestThree\",ogrestId)\r\n    end\r\n    \r\n    function ogrestThree(ogrestId)\r\n    \tMobile.setMobileAnimation(ogrestId, \"AnimApparition\", \"playerTeleport\")\r\n    \tinvoke(2500, 1, \"shakeCam\")\r\n    \tinvoke(2000, 1, \"Camera.setWorldTarget\", 2, -24, 40)\r\n    end\r\n    \r\n    function shakeCam()\r\n    \tshakeEffectId = Effect.createCameraShakeEffect(1000, 3500, 1000, 6)\r\n    \tinvoke(1500, 1, \"Effect.stopEffect\", shakeEffectId)\r\n    end\r\n    \r\n    function dialOgrest()\r\n    \tinvoke(3000, 1, \"playerTeleport\")\r\n    end\r\n    \r\n    function playerTeleport()\r\n    \tServer.triggerEvent(8691)\r\n    end\nend\n\n-- Le joueur quitte l'instance\n-- \nfunction event_1277_9358()\n    \nend\n\n-- Le combat se déclenche contre Ogrest\n-- \nfunction event_1277_9387()\n    scenarioModeEnd()\nend\n\n-- Ogrest finit son tour\n-- \nfunction event_1277_9809()\n    FightEvent.addFightEndCallback(\"endFightOgrest\")\r\n    \r\n    function endFightOgrest()\r\n    \tServer.triggerEvent(9809)\r\n    end\nend\n\n-- On téléporte le joueur\n-- \nfunction event_1277_9807()\n    \nend\n\n","functions":["scenarioMode","scenarioModeEnd","ogrestPlayInit","ulluPlayInit","hibossPlayInit","initStorm","event_1277_9370","event_1277_9356","event_1277_9867","event_1277_9359","event_1277_9360","event_1277_9369","apparitionHiboss","dialHibossOne","dialTelocheTwo","dialHibossTwo","dialTelocheThree","dialTelocheFour","event_1277_9374","event_1277_9375","playerPathEnded","dialOgrest","playerTeleport","event_1277_9413","pathEnded","ogrestOne","ogrestTwo","ogrestThree","shakeCam","dialOgrest","playerTeleport","event_1277_9358","event_1277_9387","event_1277_9809","endFightOgrest","event_1277_9807"],"quest_calls":[],"dialogue_calls":[]},"scenario/1279.lua":{"source":"playerId = Context.getPlayer()\n\n-- Arrivée du joueur dans l'instance\n-- \nfunction event_1279_9402()\n    Mobile.setMobileDirection(playerId, 7)\nend\n\n-- Ouverture du dialogue de Hiboss\n-- \nfunction event_1279_9403()\n    \nend\n\n","functions":["event_1279_9402","event_1279_9403"],"quest_calls":[],"dialogue_calls":[]},"scenario/1280.lua":{"source":"playerId = Context.getPlayer()\r\n\r\n\r\nmatouA = Mobile.generateClientMobileId()\r\nmatouB = Mobile.generateClientMobileId()\r\nmatouC = Mobile.generateClientMobileId()\r\nmatouD = Mobile.generateClientMobileId()\r\nmatouE = Mobile.generateClientMobileId()\r\n\r\n--== FONCTIONS ==--\r\n\r\nfunction initMatouleaux(matouA,matouB,matouC,matouD,matouE)\r\n\tActor.createActor(matouA, 1300059, -17, -7, 12, 4)\r\n\tActor.createActor(matouB, 1300059, -12, -9, 7, 4)\r\n\tActor.createActor(matouC, 1300059, -11, -1, 8, 4)\r\n\tActor.createActor(matouD, 1300059, -8, -1, 0, 4)\r\n\tActor.createActor(matouE, 1300057, -3, 1, 0, 4)\r\n\tMobile.setMobileDirection(matouA, 1)\r\n\tMobile.setMobileDirection(matouB, 3)\r\n\tMobile.setMobileDirection(matouC, 1)\r\n\tMobile.setMobileDirection(matouD, 3)\r\n\tMobile.setMobileDirection(matouE, 1)\r\nend\r\n\r\n\r\nfunction scenarioMode()\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\t\t\t\t\t\t\t\t\t\t\t\t-- Ferme l'inventaire\r\n\tUI.setShortcutEnabled(false)\t\t\t\t\t\t-- désactive les shortcuts\r\n    UI.manageFrame(\"World\",false) \t\t\t\t\t-- Désactive le déplacement\r\n\tUI.setUIVisible(false)\r\n    Camera.setZoomFactor(1)\r\nend\r\n\r\nfunction scenarioModeEnd()\r\n\tCamera.setUserZoomLocked(false)\r\n\tUI.setShortcutEnabled(true)\t\t\t\t\t\t\r\n    UI.manageFrame(\"World\",true) \t\t\t\t\t\r\n\tUI.setUIVisible(true)\r\nend\r\n\r\nfunction dialMatouleauxOne(matouA,matouB)\r\n\tmatouADialId = BubbleText.showText(matouA, \"zinit.plage.matouleaux.01\",0,60,false)\r\n\tinvoke(2500, 1, \"dialMatouleauxTwo\", matouADialId,matouA,matouB)\r\nend\r\n\r\nfunction dialMatouleauxTwo(matouADialId,matouA,matouB)\r\n\tBubbleText.close(matouADialId)\r\n\tmatouBDialId = BubbleText.showText(matouB, \"zinit.plage.matouleaux.02\",0,60,false)\r\n\tinvoke(2500, 1, \"dialMatouleauxThree\", matouBDialId,matouA,matouB)\r\nend\r\n\r\nfunction dialMatouleauxThree(matouADialId,matouA,matouB)\r\n\tBubbleText.close(matouBDialId)\r\n\tmatouCDialId = BubbleText.showText(matouA, \"zinit.plage.matouleaux.03\",0,60,false)\r\n\tinvoke(2500, 1, \"dialMatouleauxFour\", matouCDialId,matouA,matouB)\r\nend\r\n\r\nfunction dialMatouleauxFour(matouADialId,matouA,matouB)\r\n\tBubbleText.close(matouCDialId)\r\n\tmatouDDialId = BubbleText.showText(matouB, \"zinit.plage.matouleaux.04\",0,60,false)\r\n\tinvoke(2500, 1, \"dialMatouleauxFive\", matouDDialId,matouA,matouB)\r\nend\r\n\r\nfunction dialMatouleauxFive(matouADialId,matouA,matouB)\r\n\tBubbleText.close(matouDDialId)\r\n\tmatouEDialId = BubbleText.showText(matouA, \"zinit.plage.matouleaux.05\",0,60,false)\r\n\tinvoke(2500, 1, \"dialMatouleauxSix\", matouEDialId,matouA,matouB)\r\nend\r\n\r\nfunction dialMatouleauxSix(matouADialId,matouA,matouB)\r\n\tBubbleText.close(matouEDialId)\r\n\tmatouFDialId = BubbleText.showText(matouB, \"zinit.plage.matouleaux.06\",0,60,false)\r\n\tinvoke(2500, 1, \"BubbleText.close\",matouFDialId)\r\nend\r\n\r\nfunction soundOgrest()\r\n\tinstanceId = Context.getPlayerInstanceId()\t\r\n\tif instanceId==282 then\r\n\t\tSound.playSound(70500006, 25)\r\n\t\tshakeEffectId = Effect.createCameraShakeEffect(500, 800, 1000, 6)\r\n\t\tinvoke(900000, 1, \"soundOgrest\")\r\n\t\ttrace(\"L'OGRE HURLE\")\r\n\tend\r\nend\n\n-- On choppe les Ids\n-- \nfunction event_1280_9725()\n    \nend\n\n-- Arrivée du joueur\n-- \nfunction event_1280_9406()\n    initMatouleaux(matouA,matouB,matouC,matouD,matouE)\r\n    Mobile.setMobileDirection(playerId, 5)\r\n    invoke(4000, 1, \"dialMatouleauxOne\",matouA,matouB)\r\n    Particle.addParticleSystem(800181, -2, -141, 2, 0)\r\n    invoke(3000, 1, \"soundOgrest\")\nend\n\n-- Arrivée du joueur - La cascade est fermée\n-- \nfunction event_1280_9726()\n    \nend\n\n-- Ouverture de la cascade - Timer\n-- \nfunction event_1280_9412(moozeId)\n    scenarioMode()\r\n    invoke(500, 1, \"moozeOne\")\r\n    Mobile.setMobileDirection(playerId, 5)\r\n    \r\n    function moozeOne()\r\n    \tMobile.setMobileAnimation(moozeId, \"AnimComp05\", \"moozeTwo\")\r\n    end\r\n    \r\n    function moozeTwo()\r\n    \tMobile.setMobileAnimation(moozeId, \"AnimComp05-Loop\", \"moozeThree\")\r\n    end\r\n    \r\n    function moozeThree()\r\n    \tMobile.setMobileAnimation(moozeId, \"AnimComp05-Fin\", \"moozeFour\")\r\n    end\r\n    \r\n    function moozeFour()\r\n    \tMobile.setMobileAnimation(moozeId, \"AnimComp04\", \"moozeFive\")\r\n    \tmoozeDialId = BubbleText.setCharacterSpeak(moozeId, \"zinit.mooze.01\")\r\n    end\r\n    \r\n    function moozeFive()\r\n    \tMobile.setMobileAnimation(moozeId, \"AnimComp03\", \"moozeSix\")\r\n    end\r\n    \r\n    function moozeSix()\r\n    \tMobile.setMobileDirection(playerId, 3)\r\n    \tMobile.setMobileAnimation(playerId, \"AnimEmote-CacherYeux-Debut\")\r\n    \tMobile.setMobileAnimation(moozeId, \"AnimComp02\", \"moozeSeven\")\r\n    \tmoozeDialId = BubbleText.setCharacterSpeak(moozeId, \"zinit.mooze.02\")\r\n    end\r\n    \r\n    function moozeSeven()\r\n    \tServer.triggerEvent(9412)\r\n    \tMobile.setMobileDirection(playerId, 7)\r\n    \tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    \tMobile.setMobileAnimation(moozeId, \"AnimComp07\", \"moozeEight\")\r\n    \tmoozeDialId = BubbleText.setCharacterSpeak(moozeId, \"zinit.mooze.03\")\r\n    end\r\n    \r\n    function moozeEight()\r\n    \tinvoke(500, 1, \"scenarioModeEnd\")\r\n    end\nend\n\n-- Ouverture de la cascade\n-- \nfunction event_1280_9724()\n    trace(\"LA CASCADE EST OUVERTE\")\r\n    Particle.addParticleSystem(800181, -2, -141, 2, 0)\r\n    scenarioModeEnd()\nend\n\n-- Arrivée du joueur - Morceaux = 0\n-- \nfunction event_1280_9797()\n    \nend\n\n-- Arrivée du joueur - Morceaux = 1\n-- \nfunction event_1280_9798()\n    \nend\n\n-- Arrivée du joueur - Morceaux = 2\n-- \nfunction event_1280_9799()\n    \nend\n\n-- Arrivée du joueur - Morceaux = 3\n-- \nfunction event_1280_9800()\n    \nend\n\n-- Arrivée du joueur - Panier = 1\n-- \nfunction event_1280_9896()\n    \nend\n\n-- Le joueur accepte la quête - Pop des Crabes\n-- \nfunction event_1280_11014()\n    \nend\n\n","functions":["initMatouleaux","scenarioMode","scenarioModeEnd","dialMatouleauxOne","dialMatouleauxTwo","dialMatouleauxThree","dialMatouleauxFour","dialMatouleauxFive","dialMatouleauxSix","soundOgrest","event_1280_9725","event_1280_9406","event_1280_9726","event_1280_9412","moozeOne","moozeTwo","moozeThree","moozeFour","moozeFive","moozeSix","moozeSeven","moozeEight","event_1280_9724","event_1280_9797","event_1280_9798","event_1280_9799","event_1280_9800","event_1280_9896","event_1280_11014"],"quest_calls":[],"dialogue_calls":[]},"scenario/1283.lua":{"source":"function displayChest(room)\r\n\r\n\tlocal room = toLong(room)\r\n\r\n\tif room == 2 then\r\n\t\tlocal apsX = -47\r\n\t\tlocal apsY = -7\r\n\t\tlocal apsZ = 0\r\n\r\n\telseif room == 3 then\r\n\t\tlocal apsX = -49\r\n\t\tlocal apsY = 17\r\n\t\tlocal apsZ = -16\r\n\r\n\telseif room == 4 then\r\n\t\tlocal apsX = -49\r\n\t\tlocal apsY = 18\r\n\t\tlocal apsZ = -34\r\n\t\t\r\n\tend\r\n\r\n\tUI.displaySplashText(\"defi.donjon.win\")\r\n\tParticle.addParticleSystem(800202, apsX, apsY, apsZ)\r\n\r\nend\r\n\r\n\r\n\r\nfunction displaySceneryMob(mobId)\r\n\r\n\tlocal sceneryMob = toLong(mobId)\r\n\tinvoke_custom(1000, 1, \"Mobile.moveMobile\", sceneryMob, 8, -81, 1)\r\n\r\nend\r\n\r\n\r\n-- les fonctions où on cache\r\nfunction hideMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, false)\r\nend\r\n\r\nfunction hidePart(monsterMobileId, partName)\r\n\tMobile.setPartVisible(monsterMobileId, false, partName)\r\nend\r\n\r\n-- les fonctions où on rend visible (à nouveau\r\nfunction showMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, true)\r\nend\r\n\r\nfunction showPart(monsterMobileId, partName)\r\n\tMobile.setPartVisible(monsterMobileId, true, partName)\r\nend\n\n-- [INIT] Variables Globales\n-- \nfunction event_1283_20125()\n    \nend\n\n-- [INIT] Inscription du joueur + Variables Locales\n-- \nfunction event_1283_20126(bossId)\n    Mobile.addMobileCreationCallback(bossId, \"hideMonster\", bossId)\nend\n\n-- USER_GROUP_KILLED - Salle 01\n-- \nfunction event_1283_20127()\n    \nend\n\n-- USER_GROUP_KILLED - Côté Mine - Salle 01\n-- \nfunction event_1283_20149(mobId)\n    displaySceneryMob(mobId)\nend\n\n-- USER_GROUP_KILLED - Salle 02\n-- \nfunction event_1283_20128()\n    \nend\n\n-- USER_GROUP_KILLED - Côté Mine - Salle 02\n-- \nfunction event_1283_20150()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 03\n-- \nfunction event_1283_20129()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 04 - BOSS\n-- \nfunction event_1283_20130(mobId)\n    \nend\n\n-- Déplace le joueur vers la salle suivante\n-- \nfunction event_1283_20131()\n    \nend\n\n-- [DEFI] Combat 01 - Lancement\n-- \nfunction event_1283_20132()\n    UI.openRewardsDialog(\"defi.donjon.chafer.01\")\r\n    UI.addReward(11417)\nend\n\n-- [DEFI] Combat 02 - Lancement\n-- \nfunction event_1283_20133()\n    UI.openRewardsDialog(\"defi.donjon.chafer.01\")\r\n    UI.addReward(11418)\nend\n\n-- [DEFI] Combat 03 - Lancement\n-- \nfunction event_1283_20134()\n    UI.openRewardsDialog(\"defi.donjon.chafer.01\")\r\n    UI.addReward(11419)\nend\n\n-- [DEFI] Combat 01 - Un des joueurs échoue\n-- \nfunction event_1283_20135()\n    UI.displaySplashText(\"defi.donjon.lost\")\nend\n\n-- [DEFI] Combat - Le défi est remporté\n-- \nfunction event_1283_20138(room)\n    displayChest()\nend\n\n-- [DEFI] Coffre A\n-- \nfunction event_1283_20141()\n    InteractiveElement.setAnimation(13561,\"AnimTrans_1_3_1\")\nend\n\n-- [DEFI] Coffre B\n-- \nfunction event_1283_20142()\n    InteractiveElement.setAnimation(13562,\"AnimTrans_1_3_1\")\nend\n\n-- [DEFI] Coffre C\n-- \nfunction event_1283_20143()\n    InteractiveElement.setAnimation(13563,\"AnimTrans_1_3_1\")\nend\n\n-- [EVENT] Combat 02 - Côté Mine - Lancement - On applique le buff aux Chafers\n-- \nfunction event_1283_20152()\n    \nend\n\n-- [ETAT] Le joueur sort de l'instance\n-- \nfunction event_1283_20144()\n    \nend\n\n-- [SPECIAL] Apparition du spot d'archimonstre\n-- \nfunction event_1283_20145()\n    \nend\n\n-- [EVENT] Combat perdu - on replace les membres du groupe du boss\n-- \nfunction event_1283_20153()\n    \nend\n\n-- [EXPLOIT] Combat gagné - on incrémente le compteur \"win\" de 1\n-- \nfunction event_1283_20154()\n    \nend\n\n-- [EXPLOIT] Validation (ACH 4378)\n-- \nfunction event_1283_21913(dungeonStarted)\n    \nend\n\n-- [EVENT] On rend les monstres de la salle du boss inattaquables\n-- Cela nous permet d'éviter d'avoir la mauvaise bulle de combat sur le combat du boss\nfunction event_1283_20517()\n    \nend\n\n-- Un joueur entre dans la salle du boss, on réinitialise l'apparition\n-- \nfunction event_1283_22413()\n    \nend\n\n-- [EVENT] On marche sur le PositionTrigger, le boss apparaît\n-- Cela nous permet d'éviter d'avoir la mauvaise bulle de combat sur le combat du boss\nfunction event_1283_20518(tombeId, bossId)\n    hideMonster(tombeId)\r\n    showMonster(bossId)\r\n    Mobile.setMobileAnimation(bossId, \"AnimApparition\")\nend\n\n","functions":["displayChest","displaySceneryMob","hideMonster","hidePart","showMonster","showPart","event_1283_20125","event_1283_20126","event_1283_20127","event_1283_20149","event_1283_20128","event_1283_20150","event_1283_20129","event_1283_20130","event_1283_20131","event_1283_20132","event_1283_20133","event_1283_20134","event_1283_20135","event_1283_20138","event_1283_20141","event_1283_20142","event_1283_20143","event_1283_20152","event_1283_20144","event_1283_20145","event_1283_20153","event_1283_20154","event_1283_21913","event_1283_20517","event_1283_22413","event_1283_20518"],"quest_calls":["UI.openRewardsDialog(\"defi.donjon.chafer.01\")\r","UI.openRewardsDialog(\"defi.donjon.chafer.01\")\r","UI.openRewardsDialog(\"defi.donjon.chafer.01\")\r"],"dialogue_calls":[]},"scenario/1284.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\n\n-- [INIT] Variables Globales\n-- \nfunction event_1284_20325()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_1284_20326()\n    \nend\n\n-- [CLEAN] Un joueur entre ou sort de l'instance - Destruction des bulletins de vote\n-- \nfunction event_1284_20327()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 01\n-- \nfunction event_1284_20328()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 02\n-- \nfunction event_1284_20329()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 03\n-- \nfunction event_1284_20330()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 04 - BOSS\n-- \nfunction event_1284_20331(mobId)\n    \nend\n\n-- Déplace le joueur vers la salle suivante\n-- \nfunction event_1284_20332()\n    \nend\n\n-- [URNE] Un joueur vote pour le coffre\n-- \nfunction event_1284_20333()\n    UI.writeLocalisedInChat(\"desc.mru.kokokolantha.bulletin\")\nend\n\n-- [URNE] Un joueur vote pour l'archimonstre\n-- \nfunction event_1284_20334()\n    UI.writeLocalisedInChat(\"desc.mru.kokokolantha.bulletin\")\nend\n\n-- [URNE] Vote remporté pour le coffre - Ouverture de la porte\n-- \nfunction event_1284_20335()\n    UI.writeLocalisedInChat(\"desc.mru.kokokolantha.bulletin.chest\")\r\n    UI.displaySplashText(\"desc.mru.kokokolantha.bulletin.chest\")\nend\n\n-- [URNE] Vote remporté pour l'archimonstre - Ouverture de la porte\n-- \nfunction event_1284_20336()\n    UI.writeLocalisedInChat(\"desc.mru.kokokolantha.bulletin.archi\")\r\n    UI.displaySplashText(\"desc.mru.kokokolantha.bulletin.archi\")\nend\n\n-- [DEFI] Combat 01 à 03 démarre - display Reward UI + save du fightId + reset défi\n-- \nfunction event_1284_20337()\n    UI.openRewardsDialog(\"defi.donjon.kokoko.01\")\r\n    UI.addReward(11423, \"defi.donjon.kokoko.reward\")\nend\n\n-- [DEFI] Un joueur échoue le défi - display Fail msg + loose défi\n-- \nfunction event_1284_20338()\n    UI.displaySplashText(\"defi.donjon.lost\")\nend\n\n-- [DEFI] Combat 01 à 03 se termine avec succè du défi - display Success msg + Rend coffre à bulletin utilisable\n-- \nfunction event_1284_20339(room, chestId)\n    local room = toLong(room)\r\n    local chestId = toLong(chestId)\r\n    \t\r\n    trace(\"room\", room, \"chestId\", chestId)\r\n    \r\n    UI.displaySplashText(\"defi.donjon.win\")\nend\n\n-- [DEFI] Un joueur ouvre un des coffres à bulletin - Vérouillage du coffre\n-- \nfunction event_1284_20340(chestVoteId)\n    local ie = toLong(chestVoteId)\r\n    InteractiveElement.setAnimation(ie,\"AnimTrans_1_2\", \"InteractiveElement.setState\", ie, 2)\nend\n\n-- [INIT] Si le joueur fait la quête dans l'équipe Rouge, ajoute bandana\n-- \nfunction event_1284_20223(equipeJoueur)\n    \nend\n\n-- [INIT] Si le joueur fait la quête dans l'équipe Jaune, ajoute bandana\n-- \nfunction event_1284_20224(equipeJoueur)\n    \nend\n\n-- [COMBAT] Victoire Salle 1\n-- \nfunction event_1284_20225(equipeJoueur)\n    \tlocal equipeJoueurId = toLong(equipeJoueur)\r\n    \r\n    \tif (equipeJoueurId == 1) then\r\n    \r\n    \t\tlocal equipierRougeUn = createActor(110, -10, 1, 0, 8, 1, 6)\r\n    \r\n    \t\tActor.equip(equipierRougeUn, \"201100003\", \"CHEVEUXCUSTOM\")\r\n    \t\tActor.equip(equipierRougeUn, \"211100002\", \"VETEMENTCUSTOM\")\r\n    \t\tActor.equip(equipierRougeUn, \"13426350\", \"Chapeau\")\r\n    \t\tMobile.setPartColor(equipierRougeUn, \"Pupille\", 0.18, 0.49, 0.95, 1)\r\n    \t\tMobile.setPartColor(equipierRougeUn, \"Peau\", 0.90, 0.71, 0.58, 1)\r\n    \t\tMobile.setPartColor(equipierRougeUn, \"Cheveux\", 0.78, 0.58, 0.13, 1)\r\n    \r\n    \t\tinvoke_custom(100, 1, \"Mobile.setMobileAnimation\", equipierRougeUn, \"AnimKO-Debut\")\r\n    \t\tinvoke_custom(2000, 1, \"bubble\", equipierRougeUn, \"quest.sufokia.mercenary.kokoko.01.01\")\r\n    \r\n    \telse\r\n    \r\n    \t\tlocal equipierJauneUn = createActor(100, -9, 1, 0, 8, 1, 6)\r\n    \r\n    \t\tActor.equip(equipierJauneUn, \"201000003\", \"CHEVEUXCUSTOM\")\r\n    \t\tActor.equip(equipierJauneUn, \"211000003\", \"VETEMENTCUSTOM\")\r\n    \t\tActor.equip(equipierJauneUn, \"13426351\", \"Chapeau\")\r\n    \t\tMobile.setPartColor(equipierJauneUn, \"Pupille\", 0.03, 0.53, 0.66, 1)\r\n    \t\tMobile.setPartColor(equipierJauneUn, \"Peau\", 1.00, 0.64, 0.39, 1)\r\n    \t\tMobile.setPartColor(equipierJauneUn, \"Cheveux\", 0.46, 0.50, 0.47, 1)\r\n    \r\n    \t\tinvoke_custom(100, 1, \"Mobile.setMobileAnimation\", equipierJauneUn, \"AnimKO-Debut\")\r\n    \t\tinvoke_custom(2000, 1, \"bubble\", equipierJauneUn, \"quest.sufokia.mercenary.kokoko.01.01\")\r\n    \r\n    \tend\nend\n\n-- [COMBAT] Victoire Salle 2\n-- \nfunction event_1284_20226(equipeJoueur)\n    \tlocal equipeJoueurId = toLong(equipeJoueur)\r\n    \r\n    \tif (equipeJoueurId == 1) then\r\n    \t\r\n    \t\tlocal equipierRougeDeux = createActor(111, -28, -4, 0, 8, 3, 6)\r\n    \r\n    \t\tActor.equip(equipierRougeDeux, \"201110003\", \"CHEVEUXCUSTOM\")\r\n    \t\tActor.equip(equipierRougeDeux, \"211110001\", \"VETEMENTCUSTOM\")\r\n    \t\tActor.equip(equipierRougeDeux, \"13426350\", \"Chapeau\")\r\n    \t\tMobile.setPartColor(equipierRougeDeux, \"Pupille\", 0.08, 0.08, 0.08, 1)\r\n    \t\tMobile.setPartColor(equipierRougeDeux, \"Peau\", 0.88, 0.67, 0.35, 1)\r\n    \t\tMobile.setPartColor(equipierRougeDeux, \"Cheveux\", 0.88, 0.65, 0.16, 1)\r\n    \r\n    \t\tinvoke_custom(100, 1, \"Mobile.setMobileAnimation\", equipierRougeDeux, \"AnimKO-Debut\")\r\n    \t\tinvoke_custom(2000, 1, \"bubble\", equipierRougeDeux, \"quest.sufokia.mercenary.kokoko.01.02\")\r\n    \r\n    \r\n    \telse\r\n    \t\t\r\n    \t\tlocal equipierJauneDeux = createActor(100, -28, -4, 0, 8, 3, 6)\r\n    \r\n    \t\tActor.equip(equipierJauneDeux, \"201000001\", \"CHEVEUXCUSTOM\")\r\n    \t\tActor.equip(equipierJauneDeux, \"211000003\", \"VETEMENTCUSTOM\")\r\n    \t\tActor.equip(equipierJauneDeux, \"13426351\", \"Chapeau\")\r\n    \t\tMobile.setPartColor(equipierJauneDeux, \"Pupille\", 0.08, 0.08, 0.08, 1)\r\n    \t\tMobile.setPartColor(equipierJauneDeux, \"Peau\", 0.71, 0.39, 0.18, 1)\r\n    \t\tMobile.setPartColor(equipierJauneDeux, \"Cheveux\", 0.38, 0.28, 0.07, 1)\r\n    \r\n    \t\tinvoke_custom(100, 1, \"Mobile.setMobileAnimation\", equipierJauneDeux, \"AnimKO-Debut\")\r\n    \t\tinvoke_custom(2000, 1, \"bubble\", equipierJauneDeux, \"quest.sufokia.mercenary.kokoko.01.02\")\r\n    \r\n    \tend\nend\n\n-- [COMBAT] Victoire Salle 3 \n-- \nfunction event_1284_20227(equipeJoueur)\n    local equipeJoueurId = toLong(equipeJoueur)\r\n    \r\n    \tif (equipeJoueurId == 1) then\r\n    \t\r\n    \t\tlocal equipierRougeTrois = createActor(110, -42, -26, 0, 8, 1, 6)\r\n    \r\n    \t\tActor.equip(equipierRougeTrois, \"201100003\", \"CHEVEUXCUSTOM\")\r\n    \t\tActor.equip(equipierRougeTrois, \"211100002\", \"VETEMENTCUSTOM\")\r\n    \t\tActor.equip(equipierRougeTrois, \"13426350\", \"Chapeau\")\r\n    \t\tMobile.setPartColor(equipierRougeTrois, \"Pupille\", 0.08, 0.08, 0.08, 1)\r\n    \t\tMobile.setPartColor(equipierRougeTrois, \"Peau\", 0.81, 0.57, 0.33, 1)\r\n    \t\tMobile.setPartColor(equipierRougeTrois, \"Cheveux\", 0.21, 0.07, 0.04, 1)\r\n    \r\n    \t\tinvoke_custom(100, 1, \"Mobile.setMobileAnimation\", equipierRougeTrois, \"AnimKO-Debut\")\r\n    \t\tinvoke_custom(2000, 1, \"bubble\", equipierRougeTrois, \"quest.sufokia.mercenary.kokoko.01.03\")\r\n    \r\n    \telse\r\n    \r\n    \t\tlocal equipierJauneTrois = createActor(101, -42, -26, 0, 8, 1, 6)\r\n    \r\n    \t\tActor.equip(equipierJauneTrois, \"201010001\", \"CHEVEUXCUSTOM\")\r\n    \t\tActor.equip(equipierJauneTrois, \"211010005\", \"VETEMENTCUSTOM\")\r\n    \t\tActor.equip(equipierJauneTrois, \"13426351\", \"Chapeau\")\r\n    \t\tMobile.setPartColor(equipierJauneTrois, \"Pupille\", 0.08, 0.08, 0.08, 1)\r\n    \t\tMobile.setPartColor(equipierJauneTrois, \"Peau\", 0.43, 0.24, 0.11, 1)\r\n    \t\tMobile.setPartColor(equipierJauneTrois, \"Cheveux\", 0.08, 0.06, 0.02, 1)\r\n    \r\n    \t\tinvoke_custom(100, 1, \"Mobile.setMobileAnimation\", equipierJauneTrois, \"AnimKO-Debut\")\r\n    \t\tinvoke_custom(2000, 1, \"bubble\", equipierJauneTrois, \"quest.sufokia.mercenary.kokoko.01.03\")\r\n    \r\n    \r\n    \tend\nend\n\n-- [EVENT] Victoire - BOSS - Cinématique Mercenaire\n-- \nfunction event_1284_20229(equipeJoueur)\n    \t----------------------------- RECUPERATIONS DES INFOS JOUEUR --------------------------\r\n        \r\n        \tlocal playerId = Context.getLeaderId()\r\n        \tlocal playerX, playerY, playerZ = Mobile.getMobilePosition(playerId)\r\n        \r\n        \r\n        \t----------------------------- INITIALISATION DES PNJ --------------------------\r\n        \r\n        \tlocal grokokolantha = createActor(135501703, -80, -30, 0, 8, 1, 1)\r\n        \tlocal nodkoko = createActor(179403878, -79, -30, 0, 8, 1, 1)\r\n        \tlocal totem = c