le\", playerId)\r\n    invoke_custom(122750, 1, \"Camera.setZoomSpeedFactor\", 2)\r\n    invoke_custom(122750, 1, \"Camera.setZoomFactor\", 1.4)\r\n    \r\n    -- Joueur : Les Encapuchonnés ! (x2)\r\n    invoke_custom(123000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmoteMarket-LeverMain\")\r\n    invoke_custom(123000, 1, \"Mobile.setMobileAnimation\", amnesiqueId, \"AnimEmote-Applaudir\")\r\n    invoke_custom(123000, 1, \"bubble\", playerId, \"quest.crimson.riktus.00.43\")\r\n    invoke_custom(123000, 1, \"bubble\", amnesiqueId, \"quest.crimson.riktus.00.43\")\r\n    invoke_custom(125000, 1, \"clearBubbles\", playerId)\r\n    invoke_custom(125000, 1, \"clearBubbles\", amnesiqueId)\r\n    \r\n    invoke_custom(125250, 1, \"Camera.attachCameraToMobile\", riktusId)\r\n    invoke_custom(125250, 1, \"Camera.setZoomFactor\", 1.6)\r\n    \r\n    -- Riktus : La grotte est un de leurs anciens repaires.\r\n    invoke_custom(124950, 1, \"Mobile.setMobileAnimation\", riktusId, \"AnimSort-Invocation\")\r\n    invoke_custom(125500, 1, \"bubble\", riktusId, \"quest.crimson.riktus.00.44\")\r\n    invoke_custom(128000, 1, \"clearBubbles\", riktusId)\r\n    \r\n    -- Riktus : Cette maison est la seule à encore porter leur emblème.\r\n    invoke_custom(128500, 1, \"bubble\", riktusId, \"quest.crimson.riktus.00.45\")\r\n    invoke_custom(132000, 1, \"clearBubbles\", riktusId)\r\n    \r\n    -- Riktus : La grotte d'Aligias se trouve à côté.\r\n    invoke_custom(132500, 1, \"bubble\", riktusId, \"quest.crimson.riktus.00.46\")\r\n    invoke_custom(135000, 1, \"clearBubbles\", riktusId)\r\n    \r\n    invoke_custom(135250, 1, \"Camera.attachCameraToMobile\", playerId)\r\n    invoke_custom(135250, 1, \"Camera.setZoomSpeedFactor\", 0.4)\r\n    \r\n    -- Joueur : Allons-y !\r\n    invoke_custom(135500, 1, \"bubble\", playerId, \"quest.crimson.riktus.00.47\")\r\n    invoke_custom(135500, 1, \"Mobile.setMobileDirection\", amnesiqueId, 5)\r\n    invoke_custom(135500, 1, \"Mobile.moveMobile\", playerId, -1, -54, 0)\r\n    invoke_custom(135600, 1, \"Mobile.setMobileDirection\", amnesiqueId, 3)\r\n    invoke_custom(136000, 1, \"Mobile.moveMobile\", amnesiqueId, 0, -55, 0)\r\n    invoke_custom(137000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(138000, 1, \"customSkip\")\nend\n\n-- [EVENT] Fin de la cinématique - Validation ACH 5716 OBJ 11704\n-- \nfunction event_1298_24466()\n    \nend\n\n-- [INTERVENTION] INTERACTIVE_ELEMENT_ACTIVATION - Le joueur examine la Stèle d'intervention\n-- \nfunction event_1298_24496()\n    UI.openRewardsDialog(\"stele.intervention.description.4\")\r\n    \r\n    UI.addReward(33390)\r\n    UI.addReward(33400)\r\n    \r\n    local stateInfoId = \"stele.intervention.ignemikhal.description\" \r\n    \r\n    updateInterventionInfo(stateInfoId, true)\nend\n\n-- [INTERVENTION] GENERIC_ACTIVABLE_ACTION - Activation Stèle d'intervention\n-- \nfunction event_1298_24497(mobTwo)\n    UI.openRewardsDialog(\"stele.intervention.description.4\")\r\n    \r\n    UI.addReward(33390)\r\n    UI.addReward(33400)\r\n    \r\n    local stateInfoId = \"stele.intervention.ignemikhal.description\" \r\n    \r\n    updateInterventionInfo(stateInfoId, true)\r\n    \r\n    local bossId = toLong(mobTwo)\r\n    \r\n    invoke(1, 1, \"Mobile.setMobileAnimation\", bossId, \"AnimSort-4-Boucle\")\r\n    invoke(480, 1, \"Mobile.setMobileAnimation\", bossId, \"AnimSort-4-Fin\")\r\n    \r\n    Effect.createCameraShakeEffect(100, 500, 100, 5, 100, \"BOTH\")\r\nend\n\n-- [INTERVENTION] FIGHT_STARTED - On cache la stèle\n-- \nfunction event_1298_24505()\n    \nend\n\n-- [INTERVENTION] FIGHT_ENDED - On rend la stèle utilisable en cas de défaite\n-- \nfunction event_1298_24506()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","sta