Animation(matouE, \"AnimComp-Steamboat\")\r\nend\n\n-- Arrivée du joueur dans l'instance\n-- \nfunction event_1301_9669()\n    function dialMatou(matouE)\r\n    \tmatouBubble = BubbleText.showText(matouE, \"zinit.barquette.04\", 0, 70, false)\r\n    end\r\n    \r\n    function dialMatouD(matouD)\r\n    \tmatouBubbleD = BubbleText.showText(matouD, \"zinit.barquette.05\", 115, 200, false)\r\n    end\r\n    \r\n    function seaEffect()\r\n    \tinstanceId = Context.getPlayerInstanceId()\t\r\n    \tif instanceId==290 then\r\n    \t\tEffect.createCameraSeaSicknessEffect()\r\n    \tend\r\n    end\r\n    \r\n    \r\n    Mobile.setMobileDirection(playerId, 5)\r\n    Mobile.setMobileAnimation(playerId, \"AnimEmote-Chercher\")\r\n    seaEffect()\r\n    initMatouleaux(matouA,matouB,matouC,matouD,matouE)\r\n    Camera.setCamera(1.0, 2, -3, 8)\r\n    Camera.setUserZoomLocked(true)\r\n    \r\n    invoke(2500, 1, \"dialMatou\", matouE)\r\n    invoke(3500, 1, \"dialMatouD\", matouD)\r\n    \r\nend\n\n-- Ouverture du dialogue de Hiboss\n-- \nfunction event_1301_9670(mobId, mobTwoId)\n    Mobile.setMobileAnimation(mobId, \"AnimApparition\")\r\n    Mobile.setMobileAnimation(mobTwoId, \"AnimApparition\")\r\n    invoke(500, 1, \"dialMatou\", matouB)\r\n    \r\n    function dialMatou(matouB)\r\n    \tmatouBubble = BubbleText.showText(matouB, \"zinit.barquette.06\", 50, 70, false)\r\n    end\nend\n\n-- Fin du combat\n-- \nfunction event_1301_9680()\n    invoke(1500, 1, \"dialMatou\", matouB)\r\n    invoke(3000, 1, \"dialMatouC\", matouC)\r\n    \r\n    function dialMatou(matouB)\r\n    \tmatouBubble = BubbleText.showText(matouB, \"zinit.barquette.07\", 50, 70, false)\r\n    end\r\n    \r\n    function dialMatouC(matouC)\r\n    \tmatouBubbleC = BubbleText.showText(matouC, \"zinit.barquette.08\", 20, 330, false)\r\n    end\nend\n\n-- Téléportation dans la zone suivante\n-- \nfunction event_1301_9685()\n    \nend\n\n","functions":["initMatouleaux","event_1301_9669","dialMatou","dialMatouD","