 du dialogue de Hiboss\n-- \nfunction event_1302_9672(mobId, mobTwoId)\n    function dialMatou(matouB)\r\n    \tmatouBubble = BubbleText.showText(matouB, \"zinit.barquette.10\", 50, 70, false)\r\n    end\r\n    \r\n    \r\n    Mobile.setMobileAnimation(mobId, \"AnimApparition\")\r\n    Mobile.setMobileAnimation(mobTwoId, \"AnimApparition\")\r\n    \r\n    invoke(500, 1, \"dialMatou\", matouB)\r\n    \r\nend\n\n-- Fin du combat\n-- \nfunction event_1302_9679()\n    function dialMatou(matouC)\r\n    \tmatouBubbleC = BubbleText.showText(matouC, \"zinit.barquette.11\", 115, 200, false)\r\n    end\r\n    \r\n    invoke(1500, 1, \"dialMatouC\", matouC)\r\n    \r\nend\n\n-- Téléportation dans la zone suivante\n-- \nfunction event_1302_9686()\n    \nend\n\n","functions":["initMatouleaux","event_1302_9671","dialMatou","seaEffect","event_1302_9672","dialMatou","event_1302_9679","dialMatou","event_1302_9686"],"quest_calls":[],"dialogue_calls":[]},"scenario/1303.lua":{"source":"playerId = Context.getPlayer()\r\n\r\nmatouA = Mobile.generateClientMobileId()\r\nmatouB = Mobile.generateClientMobileId()\r\nmatouC = Mobile.generateClientMobileId()\r\nmatouD = Mobile.generateClientMobileId()\r\nmatouE = Mobile.generateClientMobileId()\r\n\r\nfunction initMatouleaux(matouA,matouB,matouC,matouD,matouE)\r\n\tActor.createActor(matouA, 1300059, -5, -1, 17, 4)\r\n\tActor.createActor(matouB, 1300059, -5, -1, 13, 4)\r\n\tActor.createActor(matouC, 1300059, 0, -1, 8, 4)\r\n\tActor.createActor(matouD, 1300059, 1, -5, 9, 4)\r\n\tActor.createActor(matouE, 1300057, 5, -2, 11, 4)\r\n\tMobile.setMobileDirection(matouA, 5)\r\n\tMobile.setMobileDirection(matouB, 1)\r\n\tMobile.setMobileDirection(matouC, 5)\r\n\tMobile.setMobileDirection(matouD, 5)\r\n\tMobile.setMobileDirection(matouE, 5)\r\n\tMobile.setMobileAnimation(matouA, \"AnimStatique-Proue\")\r\n\tMobile.setMobileAnimation(matouB, \"AnimStatique-Caisse\")\r\n\tMobile.setMobileAnimation(matouC, \"AnimStatique-Mat02\")\r\n\tMobile.setMobileAnimation(matouD, \"AnimStatique-Velo\")\r\n\tMobile.setMobileAnimation(matouE, \"AnimComp-Steamboat\")\r\nend\r\n\r\nfunction initStorm()\r\n\tinstanceId = Context.getPlayerInstanceId()\t\r\n\tif instanceId==304 then\r\n\t\ttimerOne=(math.random(3)+1)*1000\r\n\t\ttimerTwo=(math.random(3)+1)*1000\r\n\t\ttimerThree=(math.random(3)+1)*1000\r\n\t\tinvoke(timerOne, 1, \"Particle.addParticleSystem\",7290009, -15, 14, 0, 0)\t\r\n\t\tinvoke(timerTwo, 1, \"Particle.addParticleSystem\",7290009, -5, 6, 0, 0)\t\r\n\t\tinvoke(timerThree, 1, \"Particle.addParticleSystem\",7290009, 12, 0, 0, 0)\t\r\n\t\tinvoke(timerOne, 1, \"Effect.createCameraShakeEffect\",60,2)\r\n\t\tinvoke(timerTwo, 1, \"Effect.createCameraShakeEffect\",60,2)\t\r\n\t\tinvoke(timerThree, 1, \"Effect.createCameraShakeEffect\",60,2)\t\r\n\t\tinvoke(6000, 1, \"initStorm\")\r\n\tend\r\nend\n\n-- Arrivée du joueur dans l'instance\n-- \nfunction event_1303_9675()\n    function dialMatou(matouB)\r\n    \tmatouBubble = BubbleText.showText(matouB, \"zinit.barquette.01\", 50, 70, false)\r\n    end\r\n    \r\n    function dialMatouE(matouE)\r\n    \tmatouBubbleE = BubbleText.showText(matouE, \"zinit.barquette.12\", 0, 60, false)\r\n    end\r\n    \r\n    function seaEffect()\r\n    \tinstanceId = Context.getPlayerInstanceId()\t\r\n    \tif instanceId==304 then\r\n    \t\tEffect.createCameraSeaSicknessEffect()\r\n    \tend\r\n    end\r\n    \r\n    Mobile.setMobileDirection(playerId, 3)\r\n    Mobile.setMobileAnimation(playerId, \"AnimEmote-Vomis\")\r\n    seaEffect()\r\n    initMatouleaux(matouA,matouB,matouC,matouD,matouE)\r\n    Camera.setCamera(1.0, 2, -3, 8)\r\n    Camera.setUserZoomLocked(true)\r\n    initStorm()\r\n    \r\n    invoke(2500, 1, \"dialMatou\", matouB)\r\n    invoke(3000, 1, \"dialMatouE\", matouE)\r\n    \r\nend\n\n-- Ouverture du dialogue de Hiboss\n-- \nfunction event_1303_9676(mobId, mobTwoId, mobThreeId)\n    Mobile.setMobileAnimation(mobId, \"AnimApparition\")\r\n    Mobile.setMobileAnimation(mobTwoId, \"AnimApparition\")\r\n    Mobile.setMobileAnimation(mobThreeId, \"AnimApparition\")\nend\n\n-- Fin du combat\n-- \nfunction event_1303_9678()\n    function dialMatou(matouB)\r\n    \tmatouBubble = BubbleText.showText(matouB, \"zinit.barquette.13\", 50, 70, false)\r\n    end\r\n    \r\n    invoke(1500, 1, \"dialMatou\", matouB)\r\n    \r\nend\n\n-- Téléportation dans la zone suivante\n-- \nfunction event_1303_9687()\n    \nend\n\n-- Lancement du combat de la salle 01\n-- \nfunction event_1303_9851()\n    \nend\n\n","functions":["initMatouleaux","initStorm","event_1303_9675","dialMatou","dialMatouE","seaEffect","event_1303_9676","event_1303_9678","dialMatou","event_1303_9687","event_1303_9851"],"quest_calls":[],"dialogue_calls":[]},"scenario/1304.lua":{"source":"playerId = Context.getPlayer()\r\n\r\nmatouA = Mobile.generateClientMobileId()\r\nmatouB = Mobile.generateClientMobileId()\r\nmatouC = Mobile.generateClientMobileId()\r\nmatouD = Mobile.generateClientMobileId()\r\nmatouE = Mobile.generateClientMobileId()\r\n\r\nfunction initMatouleaux(matouA,matouB,matouC,matouD,matouE)\r\n\tActor.createActor(matouA, 1300059, -5, -1, 17, 4)\r\n\tActor.createActor(matouB, 1300059, -5, -1, 13, 4)\r\n\tActor.createActor(matouC, 1300059, 0, -1, 8, 4)\r\n\tActor.createActor(matouD, 1300059, 1, -5, 9, 4)\r\n\tActor.createActor(matouE, 1300057, 5, -2, 11, 4)\r\n\tMobile.setMobileDirection(matouA, 5)\r\n\tMobile.setMobileDirection(matouB, 1)\r\n\tMobile.setMobileDirection(matouC, 5)\r\n\tMobile.setMobileDirection(matouD, 5)\r\n\tMobile.setMobileDirection(matouE, 5)\r\n\tMobile.setMobileAnimation(matouA, \"AnimStatique-Proue\")\r\n\tMobile.setMobileAnimation(matouB, \"AnimStatique-Caisse\")\r\n\tMobile.setMobileAnimation(matouC, \"AnimStatique-Mat02\")\r\n\tMobile.setMobileAnimation(matouD, \"AnimStatique-Velo\")\r\n\tMobile.setMobileAnimation(matouE, \"AnimComp-Steamboat\")\r\nend\n\n-- Arrivée du joueur dans l'instance\n-- \nfunction event_1304_9681()\n    function dialMatou(matouA)\r\n    \tSound.playLocalSound(12, 320001300059009, 45, -4, -2, 13)\r\n    \tmatouBubble = BubbleText.showText(matouA, \"zinit.barquette.03\", -40, 80, false)\r\n    end\r\n    \r\n    function seaEffect()\r\n    \tinstanceId = Context.getPlayerInstanceId()\t\r\n    \tif instanceId==305 then\r\n    \t\tEffect.createCameraSeaSicknessEffect()\r\n    \tend\r\n    end\r\n    \r\n    \r\n    Mobile.setMobileDirection(playerId, 7)\r\n    seaEffect()\r\n    initMatouleaux(matouA,matouB,matouC,matouD,matouE)\r\n    Camera.setCamera(1.0, 2, -3, 8)\r\n    Camera.setUserZoomLocked(true)\r\n    \r\n    invoke(2500, 1, \"dialMatou\", matouA)\r\n    \r\nend\n\n-- Téléportation dans la zone suivante\n-- \nfunction event_1304_9684()\n    \nend\n\n","functions":["initMatouleaux","event_1304_9681","dialMatou","seaEffect","event_1304_9684"],"quest_calls":[],"dialogue_calls":[]},"scenario/1305.lua":{"source":"boussoleOne = 0\r\nplayerId = Context.getPlayer()\r\n\r\nfunction removeBoussole(boussoleId)\r\n\tUI.removeCompass(boussoleId)\r\nend\r\n\r\nfunction campUnPlayInit(campUnOne,campUnTwo,campUnThree)\n\nend\r\n\r\nfunction campDeuxPlayInit(campDeuxOne,campDeuxTwo,campDeuxThree)\r\n\r\nend\r\n\r\nfunction campTroisPlayInit(campTroisOne,campTroisTwo,campTroisThree)\r\n\r\nend\r\n\r\nfunction soundOgrest()\r\n\tinstanceId = Context.getPlayerInstanceId()\t\r\n\tif instanceId==283 then\r\n\t\tSound.playSound(70500006, 35)\r\n\t\tshakeEffectId = Effect.createCameraShakeEffect(500, 800, 1000, 6)\r\n\t\tinvoke(900000, 1, \"soundOgrest\")\r\n\t\ttrace(\"L'OGRE HURLE\")\r\n\tend\r\nend\n\n-- (INITIALISATION) Joueur\n-- \nfunction event_1305_9723(campUnOne, campUnTwo, campUnThree, campDeuxOne, campDeuxTwo, campDeuxThree, campTroisOne, campTroisTwo, campTroisThree)\n    Mobile.addMobileCreationCallback(campUnOne, \"campUnPlayInit\", campUnOne,campUnTwo,campUnThree)\r\n    \r\n    Mobile.addMobileCreationCallback(campDeuxOne, \"campDeuxPlayInit\", campDeuxOne,campDeuxTwo,campDeuxThree)\r\n    \r\n    Mobile.addMobileCreationCallback(campTroisOne, \"campTroisPlayInit\", campTroisOne,campTroisTwo,campTroisThree)\r\n    \r\n    invoke(3000, 1, \"soundOgrest\")\nend\n\n-- (INITIALISATION) Serveur\n-- \nfunction event_1305_9732()\n    \nend\n\n-- (INITIALISATION) Joueur (exploit effectué)\n-- \nfunction event_1305_9792(folletId)\n    \nend\n\n-- (INITIALISATION) Joueur (exploit non-effectué)\n-- \nfunction event_1305_9861()\n    trace(\"FOLLET EST LA\")\nend\n\n-- (INITIALISATION) Joueur (exploit Gluto effectué)\n-- \nfunction event_1305_10769(folletId)\n    \nend\n\n-- Le joueur réveille le Gloutovore Royal - Il n'a pas le bâton\n-- \nfunction event_1305_9736(glutoId)\n    --invoke(500, 1, \"UI.pushPetMessage\",0, \"gelutin.zinit.sourcier.nok\", false)\t\nend\n\n-- Le joueur réveille le Gloutovore Royal\n-- \nfunction event_1305_9727(glutoId)\n    Mobile.setMobileDirection(glutoId, 1)\r\n    Mobile.setMobileVisible(glutoId, false)\r\n    Mobile.setMobileAnimation(playerId, \"AnimInteraction-Sourcier\")\r\n    invoke(1000, 1, \"Mobile.setMobileVisible\",glutoId, true)\r\n    invoke(1000, 1, \"Mobile.setMobileAnimation\", glutoId, \"AnimApparition\")\nend\n\n-- Le joueur réveille le Gloutovore Royal - Combat\n-- \nfunction event_1305_9734(glutoId)\n    \nend\n\n-- Apparition du coffre 01\n-- \nfunction event_1305_9728()\n    Particle.addParticleSystem(800202, -50, -177, 0)\nend\n\n-- Apparition du coffre 02\n-- \nfunction event_1305_9729()\n    Particle.addParticleSystem(800202, -3, -180, 0)\nend\n\n-- Apparition du coffre 03\n-- \nfunction event_1305_9730()\n    Particle.addParticleSystem(800202, -32, -151, 0)\nend\n\n-- Le joueur arrose le Feu Follet\n-- \nfunction event_1305_9731(folletId)\n    Mobile.setMobileDirection(playerId, 7)\r\n    Mobile.setMobileAnimation(playerId, \"AnimReproduction-Debut\",\"semenceLoop\",folletId)\r\n    \r\n    function semenceLoop(mobileId,lightId)\r\n    \tMobile.setMobileAnimation(playerId, \"AnimReproduction-Boucle\",\"endSemence\",folletId)\r\n    end\r\n    \r\n    function endSemence(mobileId)\r\n    \tlightId = Particle.addParticleSystem(7162001, 43, -232, 0, 0)\r\n    \tMobile.setMobileAnimation(playerId, \"AnimReproduction-Fin\",\"endDial\",folletId,lightId)\r\n    end\r\n    \r\n    function endDial(mobileId,lightId)\r\n    \tfolletDialId = BubbleText.setCharacterSpeak(folletId, \"zinit.follet.01\")\r\n    \t--invoke(2500, 1, \"Server.triggerEvent\",9731)\r\n    \tinvoke(2500, 1, \"Particle.removeParticleSystem\",lightId)\r\n    \tinvoke(2500, 1, \"BubbleText.close\", folletDialId)\r\n    end\r\n    \r\n    \r\nend\n\n-- Le joueur arrose le Feu Follet - Disparition\n-- \nfunction event_1305_9735(folletId)\n    Mobile.setMobileAnimation(folletId, \"AnimEnvol\",\"Mobile.setMobileVisible\",folletId,false)\nend\n\n-- Arrivée du joueur - Morceaux = 0\n-- \nfunction event_1305_9803()\n    \nend\n\n-- Arrivée du joueur - Morceaux = 1\n-- \nfunction event_1305_9804()\n    \nend\n\n-- Arrivée du joueur - Morceaux = 2\n-- \nfunction event_1305_9805()\n    \nend\n\n-- Ouverture d'un coffre de fragment d'Agua\n-- \nfunction event_1305_9880()\n    \nend\n\n-- Arrivée du joueur - Fragment = 1\n-- \nfunction event_1305_9881()\n    \nend\n\n-- Arrivée du joueur - Fragment = 2\n-- \nfunction event_1305_9882()\n    \nend\n\n-- Arrivée du joueur - Fragment = 3\n-- \nfunction event_1305_9883()\n    \nend\n\n-- Arrivée du joueur - Fragment = 4\n-- \nfunction event_1305_9884()\n    \nend\n\n-- Arrivée du joueur - Glouto = Spawn\n-- \nfunction event_1305_9903()\n    \nend\n\n-- Le joueur bat le Gloutovore Royal\n-- \nfunction event_1305_11917()\n    \nend\n\n","functions":["removeBoussole","campUnPlayInit","campDeuxPlayInit","campTroisPlayInit","soundOgrest","event_1305_9723","event_1305_9732","event_1305_9792","event_1305_9861","event_1305_10769","event_1305_9736","event_1305_9727","event_1305_9734","event_1305_9728","event_1305_9729","event_1305_9730","event_1305_9731","semenceLoop","endSemence","e