\n    \tWorld.setPictoAlpha(43, -270, 0, 1, 1)\r\n    \tWorld.setPictoAlpha(43, -271, 0, 1, 1)\r\n    \tWorld.setPictoAlpha(43, -272, 0, 1, 1)\r\n    \tWorld.setPictoAlpha(43, -273, 0, 1, 1)\r\n    \tWorld.setPictoAlpha(42, -290, 0, 0, 1)\r\n    \tWorld.setPictoAlpha(42, -291, 0, 0, 1)\r\n    \tWorld.setPictoAlpha(42, -292, 0, 0, 1)\r\n    elseif passerelle==3 then\r\n    \tWorld.setPictoAlpha(44, -251, 0, 1, 1)\r\n    \tWorld.setPictoAlpha(44, -252, 0, 1, 1)\r\n    \tWorld.setPictoAlpha(44, -253, 0, 1, 1)\r\n    \tWorld.setPictoAlpha(43, -270, 0, 1, 1)\r\n    \tWorld.setPictoAlpha(43, -271, 0, 1, 1)\r\n    \tWorld.setPictoAlpha(43, -272, 0, 1, 1)\r\n    \tWorld.setPictoAlpha(43, -273, 0, 1, 1)\r\n    \tWorld.setPictoAlpha(42, -290, 0, 1, 1)\r\n    \tWorld.setPictoAlpha(42, -291, 0, 1, 1)\r\n    \tWorld.setPictoAlpha(42, -292, 0, 1, 1)\r\n    end\nend\n\n-- [COMBAT] Victoire Salle 1\n-- \nfunction event_1306_9697()\n    \nend\n\n-- [COMBAT] Victoire Salle 1 - On déverouille la porte\n-- \nfunction event_1306_9698()\n    \tWorld.setPictoAlpha(44, -251, 0, 1, 1000)\r\n    \tWorld.setPictoAlpha(44, -252, 0, 1, 1000)\r\n    \tWorld.setPictoAlpha(44, -253, 0, 1, 1000)\r\nend\n\n-- [COMBAT] Victoire Salle 2\n-- \nfunction event_1306_9699()\n    \nend\n\n-- [COMBAT] Victoire Salle 2 - On déverouille la porte\n-- \nfunction event_1306_9700()\n    \tWorld.setPictoAlpha(43, -270, 0, 1, 1000)\r\n    \tWorld.setPictoAlpha(43, -271, 0, 1, 1000)\r\n    \tWorld.setPictoAlpha(43, -272, 0, 1, 1000)\r\n    \tWorld.setPictoAlpha(43, -273, 0, 1, 1000)\r\nend\n\n-- [COMBAT] Victoire Salle 3\n-- \nfunction event_1306_9701()\n    \nend\n\n-- [COMBAT] Victoire Salle 3 - On active le TP et le coffre\n-- \nfunction event_1306_9702()\n    \tWorld.setPictoAlpha(42, -290, 0, 1, 1000)\r\n    \tWorld.setPictoAlpha(42, -291, 0, 1, 1000)\r\n    \tWorld.setPictoAlpha(42, -292, 0, 1, 1000)\r\nend\n\n-- [SCENE] Entrée du joueur\n-- \nfunction event_1306_9737(aguaId)\n    Mobile.setMobileAnimation(aguaId, \"AnimApparition\", \"Camera.attachCameraToMobile\", playerId)\r\n    invoke(200, 1, \"shakeCam\")\r\n    Camera.setCamera(1, 42, -301, 0)\r\n    \r\n    function shakeCam()\r\n    \tshakeEffectId = Effect.createCameraShakeEffect(500, 1800, 1000, 6)\r\n    \tinvoke(1500, 1, \"Effect.stopEffect\", shakeEffectId)\r\n    end\nend\n\n-- [SCENE] Dialogue avec Aguabrial\n-- \nfunction event_1306_9739(aguaId)\n    \nend\n\n-- [COMBAT] Déclenchement (le joueur a perdu)\n-- \nfunction event_1306_9878(aguaId)\n    \nend\n\n-- [COMBAT] Déclenchement\n-- \nfunction event_1306_9738(aguaId)\n    \nend\n\n-- [COMBAT] Victoire Salle 4 - C'est le joueur qui gagne\n-- \nfunction event_1306_9863(aguaId)\n    \nend\n\n-- [COMBAT] Victoire Salle 4\n-- \nfunction event_1306_9704(aguaId)\n    \nend\n\n-- [COMBAT] Victoire Salle 4 - On déverouille la porte\n-- \nfunction event_1306_9808(aguaId)\n    \nend\n\n-- [COMBAT] Victoire Salle 4 - Le joueur a répondu à Aguabrial\n-- \nfunction event_1306_9811(aguaId)\n    invoke(1500, 1, \"aguaEnd\", aguaId)\r\n    \r\n    function aguaEnd(aguaId)\r\n    \taguaDialId = BubbleText.setCharacterSpeak(aguaId, \"zinit.aguabrial.01\")\r\n    \tinvoke(2500, 1, \"BubbleText.close\", aguaDialId)\r\n    \tinvoke(2500, 1, \"Mobile.setMobileAnimation\",aguaId,\"AnimMort\")\r\n    end\r\nend\n\n-- [INITIALISATION] Joueur - Achievement OK\n-- \nfunction event_1306_9812()\n    \nend\n\n-- Le joueur annule le dialogue\n-- \nfunction event_1306_9865()\n    \nend\n\n-- Le joueur annule le dialogue\n-- \nfunction event_1306_9866()\n    \nend\n\n","functions":["soundOgrest","event_1306_9695","event_1306_9696","event_1306_9697","event_1306_9698","event_1306_9699","event_1306_9700","event_1306_9701","event_1306_9702","event_1306_9737","shakeCam","event_1306_9739","event_1306_9878","event_1306_9738","event_1306_9863","event_1306_9704","event_1306_9808","event_1306_9811","aguaEnd","event_1306_9812","event_1306_9865","event_1306_9866"],"quest_calls":[],"dialogue_calls":[]},"scenario/1336.lua":{"source":"\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_1336_9950()\n    \nend\n\n-- [INIT] Variables Globales\n-- \nfunction event_1336_18618()\n    \nend\n\n-- Lancement d'un combat - Application Silence Divin sur les joueurs\n-- \nfunction event_1336_10190()\n    \nend\n\n-- Lancement d'un combat - Application des états sur les monstres\n-- \nfunction event_1336_21944()\n    \nend\n\n-- *[OLD][COMBAT] Salle 01\n-- \nfunction event_1336_9951()\n    \nend\n\n-- *[OLD][COMBAT] Salle 02\n-- \nfunction event_1336_9952()\n    \nend\n\n-- [COMBAT] Salle 01\n-- \nfunction event_1336_9953()\n    \nend\n\n-- [COMBAT] Salle 02 (BOSS)\n-- \nfunction event_1336_9954()\n    \nend\n\n-- [Bibliothèque] Initialisation des variables\n-- \nfunction event_1336_10948()\n    \nend\n\n-- [Bibliothèque] Lettre A - Incrémentation\n-- \nfunction event_1336_10950()\n    Sound.playLocalSound(10, 70500004, 90, 143, -58 , 0)\nend\n\n-- [Bibliothèque] Lettre A - Décrémentation\n-- \nfunction event_1336_10951()\n    Sound.playLocalSound(10, 70500005, 90, 143, -58 , 0)\nend\n\n-- [Bibliothèque] Lettre M - Incrémentation\n-- \nfunction event_1336_10952()\n    Sound.playLocalSound(10, 70500004, 90, 144, -61 , 0)\nend\n\n-- [Bibliothèque] Lettre M - Décrémentation\n-- \nfunction event_1336_10953()\n    Sound.playLocalSound(10, 70500005, 90, 144, -61 , 0)\nend\n\n-- [Bibliothèque] Lettre E - Incrémentation\n-- \nfunction event_1336_10954()\n    Sound.playLocalSound(10, 70500004, 90, 145, -59 , 0)\nend\n\n-- [Bibliothèque] Lettre E - Décrémentation\n-- \nfunction event_1336_10955()\n    Sound.playLocalSound(10, 70500005, 90, 145, -59 , 0)\nend\n\n-- [Bibliothèque] Lettre N - Incrémentation\n-- \nfunction event_1336_10956()\n    Sound.playLocalSound(10, 70500004, 90, 146, -61 , 0)\nend\n\n-- [Bibliothèque] Lettre N - Décrémentation\n-- \nfunction event_1336_10957()\n    Sound.playLocalSound(10, 70500005, 90, 146, -61 , 0)\nend\n\n-- [Bibliothèque] Activation du Levier - Valide\n-- \nfunction event_1336_10958()\n    Particle.addParticleSystem(800202, 141, -59, 1, 0)\nend\n\n-- [Bibliothèque] Activation du Levier - Invalide\n-- \nfunction event_1336_10967()\n    UI.writeLocalisedInChat(\"quest.boufrog.sliptorium.badAnswer\")\nend\n\n-- [Bibliothèque] Le joueur interagit avec une dalle\n-- \nfunction event_1336_21464()\n    \nend\n\n-- [Bibliothèque] Le joueur interagit avec un livre\n-- \nfunction event_1336_21466()\n    \nend\n\n-- [Bibliothèque] Le joueur prend un livre\n-- \nfunction event_1336_21465()\n    \nend\n\n-- Déplace le joueur vers la salle suivante\n-- \nfunction event_1336_18619()\n    \nend\n\n-- [ARCHI] Apparition de l'Archimonstre\n-- \nfunction event_1336_23962()\n    \nend\n\n","functions":["event_1336_9950","event_1336_18618","event_1336_10190","event_1336_21944","event_1336_9951","event_1336_9952","event_1336_9953","event_1336_9954","event_1336_10948","event_1336_10950","event_1336_10951","event_1336_10952","event_1336_10953","event_1336_10954","event_1336_10955","event_1336_10956","event_1336_10957","event_1336_10958","event_1336_10967","event_1336_21464","event_1336_21466","event_1336_21465","event_1336_18619","event_1336_23962"],"quest_calls":[],"dialogue_calls":[]},"scenario/1340.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\nfamilier_bubbleId = 0\r\ngelutinId = Mobile.generateClientMobileId()\r\n\r\nfunction chachaBehaviour(mobileid, direction, animation)\r\n\tMobile.setMobileDirection(mobileid, direction)\r\n\tMobile.setMobileAnimation(mobileid, animation)\r\nend\r\n\r\n--Création et affichage d'une bulle de texte avec 2 choix\r\nfunction showBubble(blablah, buttonA, buttonB, endfunctionA, paramA, endfunctionB, paramB)\r\n    BubbleText.close(m_bubbleId)    \r\n    m_bubbleId = BubbleText.prepareFloating(\"CENTER\",0,0,false)\r\n    BubbleText.setText(m_bubbleId, blablah, param)\r\n    BubbleText.setOffset(m_bubbleId,0,60)\r\n    if buttonA then\r\n        butA = buttonA\r\n    else\r\n        butA = \"dialog.continue\"\r\n    end\r\n    if buttonB then\r\n        butB = buttonB\r\n    else\r\n        butB = \"dialog.continue\"\r\n    end\r\n    if endfunctionA then\r\n        BubbleText.addButton(m_bubbleId, butA, endfunctionA, paramA) \r\n    end\r\n    if endfunctionB then\r\n        BubbleText.addButton(m_bubbleId, butB, endfunctionB, paramB) \r\n    end\r\n    BubbleText.show(m_bubbleId)\r\nend\r\n\r\n-- Création et affichage d'une bulle de texte au dessus du familier et affichage dans le chat\r\nfunction showFamilierBubble(text)\r\n\tBubbleText.close(familier_bubbleId)   \r\n\tfamilier_bubbleId = BubbleText.showText(gelutinId, text, 0, 20, false)\r\nend\r\n\r\n-- Fermeture de la bulle de texte\r\nfunction closeBubble()\r\n    BubbleText.close(m_bubbleId)    \r\nend\r\n\r\n-- Dialogue Gelutin\r\nfunction randomGelutinBubble()\r\ntexts = {\"incarnam.intro.familierRandomTalk1\", \"incarnam.intro.familierRandomTalk2\", \"incarnam.intro.familierRandomTalk3\", \"incarnam.intro.familierRandomTalk4\", \"incarnam.intro.familierRandomTalk5\", \"incarnam.intro.familierRandomTalk6\"}\r\ntextId = random(1, 7)\r\ntextRandom = texts[textId]\r\n\tif (not Context.isInFight()) then\r\n\t\tshowFamilierBubble(textRandom)\r\n\t\tinvoke(10000, 1, \"randomGelutinBubble\")\r\n\tend\r\nend\r\n\r\nfunction gelutinAnim()\r\n\tinvoke(5000, 1, \"Mobile.setMobileAnimation\", gelutinId, \"AnimComp-incarnam\", \"gelutinAnim\")\r\nend\n\n-- [INIT] Variables Globales\n-- \nfunction event_1340_10028()\n    \nend\n\n-- ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_1340_10021(catOne, catTwo, catThree, catFour, catFive, catSix, catSeven, catEight, catNine, catTen, catEleven, catBoss)\n    Mobile.addMobileCreationCallback(catOne, \"chachaBehaviour\", catOne, 1, \"AnimDonjon05\")\r\n    Mobile.addMobileCreationCallback(catTwo, \"chachaBehaviour\", catTwo, 3, \"AnimDonjon-Dormir-Boucle\")\r\n    Mobile.addMobileCreationCallback(catThree, \"chachaBehaviour\", catThree, 3, \"AnimDonjon-Dormir-Boucle\")\r\n    Mobile.addMobileCreationCallback(catFour, \"chachaBehaviour\", catFour, 5, \"AnimDonjon03\")\r\n    Mobile.addMobileCreationCallback(catFive, \"chachaBehaviour\", catFive, 5,\"AnimDonjon03\")\r\n    Mobile.addMobileCreationCallback(catSix, \"chachaBehaviour\", catSix, 1, \"AnimDonjon-Dormir-Boucle\")\r\n    Mobile.addMobileCreationCallback(catSeven, \"chachaBehaviour\", catSeven, 3, \"AnimDonjon-Dormir-Boucle\")\r\n    Mobile.addMobileCreationCallback(catNine, \"chachaBehaviour\", catNine, 1, \"AnimDonjon-Dormir-Boucle\")\r\n    \r\n    --Gelutin\r\n    Actor.createActor(gelutinId, 117102139, 21, -10, -9, 4)\r\n    Actor.setActorHeight(gelutinId, 4)\r\n    Mobile.setMobileDirection(gelutinId, 3)\r\n    \r\n    invoke(5000, 1, \"randomGelutinBubble\")\r\n    \r\n    gelutinAnim()\nend\n\n-- ENTER_INSTANCE - Quête - Cinématique Tristepin\n-- \nfunction event_1340_23920()\n    local tristepin = createActor(192404687, 0, 1, 0, 4, 1, 5)\r\n    local playerId = Context.getLeaderId()\r\n    Mobile.hideOtherPlayerMobile(true)\r\n    \r\n    fullScreen(0, 1000, 1000)\r\n    \r\n    startCinematicContext(1.7, playerId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 23920)\r\n    \r\n    -- \"Pouah, ça sent le Chacha à plein nez !\"\r\n    invoke_custom(03000, 1, \"bubble\", tristepin, \"quest.astrub.chacha.01\")\r\n    invoke_custom(03000, 1, \"Mobile.setMobileAnimation\", tristepin, \"AnimComp-Essoufle\")\r\n    invoke_custom(04000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Vomis\")\r\n    invoke_custom(06000, 1, \"clearBubbles\", tristepin)\r\n    \r\n    invoke_custom(06250, 1, \"Mobile.setMobileDirection\", playerId, 3)\r\n    \r\n    -- \"Reste derrière, petit. Je m'occupe de tout...\"\r\n    invoke_custom(06500, 1, \"bubble\", playerId, \"quest.astrub.chacha.02\")\r\n    invoke_custom(06500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Calmer\")\r\n    invoke_custom(09500, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(06250, 1, \"Mobile.setMobileDirection\", tristepin, 7)\r\n    \r\n    -- \"Quoi ? Pas question. Je participe au combat également !\"\r\n    invoke_custom(10000, 1, \"Sound.playSound\", 320192404687001, true, 50)\r\n    invoke_custom(10000, 1, \"bubble\", tristepin, \"quest.astrub.chacha.03\")\r\n    invoke_custom(13500, 1, \"clearBubbles\", tristepin)\r\n    \r\n    invoke_custom(14000, 1, \"skipCinematic\", 23920)\nend\n\n-- CLIENT_TRIGGERED_EVENT - Quête - Fin Cinématique Tristepin\n-- \nfunction event_1340_23921()\n    UI.loadGuideDialog(170)\nend\n\n-- FIGHT_STARTED - Salle 01 - On ajoute Tristepin\n-- \nfunction event_1340_23904()\n    skipCinematic(23920)\nend\n\n-- USER_GROUP_KILLED - Salle 01\n-- \nfunction event_1340_10015()\n    \nend\n\n-- FIGHT_ENDED_IN_CLIENT_EVENT - Quête - Cinématique Tristepin 2\n-- \nfunction event_1340_23922()\n    local tristepin = createActor(192404687, 8, 1, 0, 4, 5,