tepin\n-- \nfunction event_1340_23905()\n    skipCinematic(23922)\nend\n\n-- USER_GROUP_KILLED - Salle 02\n-- \nfunction event_1340_10017()\n    \nend\n\n-- FIGHT_ENDED_IN_CLIENT_EVENT - Quête - Cinématique Tristepin 3\n-- \nfunction event_1340_23924(catTen, catEleven, catBoss)\n    local tristepin = createActor(192404687, 14, -8, 0, 4, 1, 5)\r\n    local gelutin = createActor(117102139, 21, -10, -9, 4, 3, 4)\r\n    local playerId = Context.getLeaderId()\r\n    \r\n    local catTen = toLong(catTen)\r\n    local catEleven = toLong(catEleven)\r\n    local catBoss = toLong(catBoss)\r\n    \r\n    Mobile.hideOtherPlayerMobile(true)\r\n    Mobile.setMobilePosition(playerId, 15, -8, 0)\r\n    Mobile.setMobileDirection(playerId, 5)\r\n    Mobile.setMobileVisible(gelutinId, false)\r\n    Mobile.setMobileDirection(catTen, 1)\r\n    Mobile.setMobileDirection(catEleven, 5)\r\n    Mobile.setMobileDirection(catBoss, 7)\r\n    \r\n    function customSkip()\r\n        Mobile.setMobileVisible(gelutinId, true)\r\n        skipCinematic(23924)\r\n    end\r\n    \r\n    fullScreen(0, 1000, 1000)\r\n    \r\n    startCinematicContext(1.7, playerId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"customSkip\")\r\n    \r\n    -- \"On s'en sort pas mal, pour l'instant !\"\r\n    invoke_custom(03000, 1, \"bubble\", playerId, \"quest.astrub.chacha.07\")\r\n    invoke_custom(03000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Victoire\")\r\n    invoke_custom(06000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(06250, 1, \"Camera.attachCameraToMobile\", tristepin)\r\n    \r\n    -- \"Continuons ! Je sens que le boss n'est plus trop loin !\"\r\n    invoke_custom(06500, 1, \"Sound.playSound\", 320192404687003, true, 50)\r\n    invoke_custom(06500, 1, \"bubble\", tristepin, \"quest.astrub.chacha.08\")\r\n    invoke_custom(10000, 1, \"clearBubbles\", tristepin)\r\n    \r\n    invoke_custom(10250, 1, \"Mobile.moveMobile\", tristepin, 20, -4, -11, \"Mobile.setMobileDirection\", tristepin, 7)\r\n    invoke_custom(10250, 1, \"Mobile.moveMobile\", playerId, 22, -4, -11, \"Mobile.setMobileDirection\", playerId, 7)\r\n    \r\n    invoke_custom(12250, 1, \"Camera.attachCameraToMobile\", gelutin)\r\n    \r\n    -- \"Au secours ! Aidez-moi ! Les Chachas veulent me manger !\"\r\n    invoke_custom(12500, 1, \"bubble\", gelutin, \"quest.astrub.chacha.09\")\r\n    invoke_custom(12500, 1, \"Mobile.setMobileAnimation\", gelutin, \"AnimComp-incarnam\")\r\n    invoke_custom(16000, 1, \"clearBubbles\", gelutin)\r\n    \r\n    invoke_custom(16250, 1, \"Camera.attachCameraToMobile\", tristepin)\r\n    \r\n    -- \"Ça alors ! C'est incroyable ! On dirait un...\"\r\n    invoke_custom(16500, 1, \"Sound.playSound\", 320192404687004, true, 50)\r\n    invoke_custom(16500, 1, \"bubble\", tristepin, \"quest.astrub.chacha.10\")\r\n    invoke_custom(19500, 1, \"clearBubbles\", tristepin)\r\n    \r\n    invoke_custom(19750, 1, \"Camera.attachCameraToMobile\", playerId)\r\n    invoke_custom(19750, 1, \"Mobile.setMobileDirection\", playerId, 5)\r\n    \r\n    -- \"On dirait un...?\"\r\n    invoke_custom(20000, 1, \"bubble\", playerId, \"quest.astrub.chacha.11\")\r\n    invoke_custom(20000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(22500, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(22750, 1, \"Camera.attachCameraToMobile\", tristepin)\r\n    invoke_custom(22750, 1, \"Camera.setZoomFactor\", 2.0)\r\n    \r\n    -- \"C'est...\"\r\n    invoke_custom(23000, 1, \"Sound.playSound\", 320192404687002, true, 50)\r\n    invoke_custom(23000, 1, \"bubble\", tristepin, \"quest.astrub.chacha.12\")\r\n    invoke_custom(25000, 1, \"clearBubbles\", tristepin)\r\n    \r\n    invoke_custom(29000, 1, \"Camera.setZoomSpeedFactor\", 0.02)\r\n    invoke_custom(29000, 1, \"Camera.setZoomFactor\", 1.6)\r\n    \r\n    -- \"Je sais pas ce que c'est.\"\r\n    invoke_custom(28000,