e)\r\n\tMobile.setMobileDirection(mobileId, 1)\r\nend\r\n\r\nfunction deleteActor(mobileId)\r\n\tActor.deleteActor(mobileId)\r\nend\r\n\r\nfunction animActor(mobileId, anim)\r\n\tMobile.setMobileAnimation(mobileId, anim)\r\nend\r\n\r\nfunction weshTurn(mobileId, Scene)\r\n\tif Scene==0 then\r\n\t\tMobile.setMobileDirection(mobileId, 3)\r\n\t\tMobile.setMobileVisible(mobileId, false)\r\n\tend\r\nend\r\n\r\nfunction weshApp()\r\n\t--weshActor=Mobile.generateClientMobileId()\r\n\tActor.createActor(weshActor, 80, 8, -10, 0, 4)\r\n\tActor.equip(weshActor, \"210300001\", \"VETEMENTCUSTOM\")\r\n\tActor.equip(weshActor, \"200300001\", \"CHEVEUXCUSTOM\")\r\n\tActor.equip(weshActor, \"11910531\", \"PiedHabit01\", \"PiedHabit02\")\r\n\tActor.equip(weshActor, \"13611025\", \"CorpsHabit\")\r\n\tActor.equip(weshActor, \"13410175\", \"Chapeau\")\r\n\tActor.equip(weshActor, \"13811022\", \"Epaulette-D\", \"Epaulette-G\")\r\n\tMobile.setPartColor(weshActor, \"Peau\", 0.83, 0.67, 0.67, 1)\r\n\tMobile.setPartColor(weshActor, \"Cheveux\", 0.21, 0.20, 0.20, 1)\t\t\r\n\tMobile.setMobileAnimation(weshActor, \"AnimSort-Bond-Fin\")\r\n\tMobile.setMobileDirection(weshActor, 3)\r\nend\r\n\r\nfunction jelassieTurn(mobileId, Scene)\r\n\tif Scene==0 then\r\n\t\tMobile.setMobileDirection(mobileId, 3)\r\n\t\tMobile.setMobileVisible(mobileId, false)\r\n\tend\r\nend\r\n\r\nfunction jelassieApp()\r\n\t--jelassieActor=Mobile.generateClientMobileId()\r\n\tActor.createActor(jelassieActor, 80, 9, -13, 0, 4)\r\n\tActor.equip(jelassieActor, \"210310001\", \"VETEMENTCUSTOM\")\r\n\tActor.equip(jelassieActor, \"200310003\", \"CHEVEUXCUSTOM\")\r\n\tActor.equip(jelassieActor, \"11910531\", \"PiedHabit01\", \"PiedHabit02\")\r\n\tActor.equip(jelassieActor, \"13611025\", \"CorpsHabit\")\r\n\tActor.equip(jelassieActor, \"13410175\", \"Chapeau\")\r\n\tActor.equip(jelassieActor, \"13811022\", \"Epaulette-D\", \"Epaulette-G\")\r\n\tMobile.setPartColor(jelassieActor, \"Peau\", 0.93, 0.73, 0.63, 1)\r\n\tMobile.setPartColor(jelassieActor, \"Cheveux\", 0.80, 0.37, 0.19, 1)\t\t\r\n\tMobile.setMobileAnimation(jelassieActor, \"AnimSort-Bond-Fin\")\r\n\tMobile.setMobileDirection(jelassieActor, 3)\r\nend\r\n\r\nfunction biffTurn(mobileId, Scene)\r\n\tif Scene==0 then\r\n\t\tMobile.setMobileDirection(mobileId, 5)\r\n\t\tMobile.setMobileVisible(mobileId, false)\r\n\tend\r\nend\r\n\r\nfunction biffApp()\r\n\t--biffActor=Mobile.generateClientMobileId()\r\n\tActor.createActor(biffActor, 80, 14, -11, 0, 4)\r\n\tActor.equip(biffActor, \"210300001\", \"VETEMENTCUSTOM\")\r\n\tActor.equip(biffActor, \"200300001\", \"CHEVEUXCUSTOM\")\r\n\tActor.equip(biffActor, \"11910531\", \"PiedHabit01\", \"PiedHabit02\")\r\n\tActor.equip(biffActor, \"13611025\", \"CorpsHabit\")\r\n\tActor.equip(biffActor, \"13410175\", \"Chapeau\")\r\n\tActor.equip(biffActor, \"13811022\", \"Epaulette-D\", \"Epaulette-G\")\r\n\tMobile.setPartColor(biffActor, \"Peau\", 0.83, 0.74, 0.74, 1)\r\n\tMobile.setPartColor(biffActor, \"Cheveux\", 0.51, 0.38, 0.18, 1)\t\r\n\tMobile.setMobileAnimation(biffActor, \"AnimIncarnam-Chute-Fin\", \"Mobile.setMobileDirection\", biffActor, 3)\t\r\n\tMobile.setMobileDirection(biffActor, 5)\r\nend\r\n\r\nfunction grisApp()\r\n\t--biffActor=Mobile.generateClientMobileId()\r\n\tActor.createActor(grisActor, 117901841, 11, -11, 0, 4)\r\n\tMobile.setMobileAnimation(grisActor, \"AnimApparition\")\t\r\n\tMobile.setMobileDirection(grisActor, 7)\r\n\tActor.setActorHeight(grisActor,4)\r\n\tinvoke(500,1,\"UI.displaySmiley\",17917,grisActor,0)\r\nend\r\n\r\nfunction gardApp(mobileId,x,y,z,dir)\r\n\tdelay=(math.random(1200)+400)\r\n\tActor.createActor(mobileId, 140001810, x, y, z, 4)\r\n\tMobile.setMobileDirection(mobileId, dir)\r\n\tMobile.setMobileVisible(mobileId, false)\r\n\tinvoke(delay, 1, \"Mobile.setMobileVisible\",mobileId, true)\r\n\tinvoke(delay, 1, \"Mobile.setMobileAnimation\",mobileId, \"AnimApparition\")\t\r\nend\n\n-- [INITIALISATION] Variables\n-- \nfunction event_1346_10081()\n    \nend\n\n-- [INITIALISATION] Inscription des joueurs\n-- \nfunction event_1346_10082(rabetId, weshId, jelassieId, biffId, rabetScene)\n    Scene = toLong(rabetScene)\r\n    \r\n    Mobile.addMobileCreationCallback(rabetId, \"rabetTurn\", rabetId, Scene)\r\n    Mobile.addMobileCreationCallback(weshId, \"weshTurn\", weshId, Scene)\r\n    Mobile.addMobileCreationCallback(jelassieId, \"jelassieTurn\", jelassieId, Scene)\r\n    Mobile.addMobileCreationCallback(biffId, \"biffTurn\", biffId, Scene)\r\n    \r\nend\n\n-- [SCENE] Le joueur arrive devant Rabet\n-- \nfunction event_1346_10087(rabetId, weshId, jelassieId, biffId)\n    function rabetStart(rabetId,weshId,jelassieId,biffId)\r\n    \tBubbleText.setCharacterSpeak(rabetId, \"zinit.C2.P3.rabet01\")\r\n    \tinvoke(4000, 1, \"rabetSuite\",rabetId,weshId,jelassieId,biffId)\r\n    \tMobile.setMobileDirection(rabetId, 3)\r\n    end\r\n    \r\n    function rabetSuite(rabetId,weshId,jelassieId,biffId)\r\n    \tBubbleText.setCharacterSpeak(rabetId, \"zinit.C2.P3.rabet02\")\r\n    \tMobile.setMobileAnimation(rabetId, \"AnimSort-CoupDePression\")\r\n    \tinvoke(1000, 1, \"animActor\", grisActor, \"AnimHit\")\r\n    \tinvoke(1800, 1, \"grisHide\")\r\n    \tinvoke(5000, 1, \"opulenceStart\",rabetId,weshId,jelassieId,biffId)\r\n    end\r\n    \r\n    function opulenceStart(rabetId,weshId,jelassieId,biffId)\n    \tinvoke(2000, 1, \"weshApp\")\r\n    \tinvoke(4000, 1, \"jelassieApp\")\r\n    \tinvoke(5000, 1, \"biffApp\")\n    \tBubbleText.setCharacterSpeak(rabetId, \"zinit.C2.P3.rabet03\")\r\n    \tMobile.setMobileAnimation(rabetId, \"AnimSort-ChargeDeStasili\")\r\n    \tinvoke(7000, 1, \"rabetEnd\",rabetId,weshId,jelassieId,biffId)\r\n    end\r\n    \r\n    function rabetEnd(rabetId,weshId,jelassieId,biffId)\r\n    \tBubbleText.setCharacterSpeak(rabetId, \"zinit.C2.P3.rabet04\")\r\n    end\r\n    \r\n    function grisHide()\n    \tMobile.moveMobile(grisActor, 17, -11, 0, \"Mobile.setMobileAnimation\",grisActor,\"AnimMort\")\r\n    end\r\n    \r\n    Camera.setWorldTarget(16, -11, 0)\r\n    invoke(750, 1, \"grisApp\")\r\n    invoke(1500, 1, \"rabetStart\",rabetId,weshId,jelassieId,biffId)\nend\n\n-- [SCENE] Début du combat\n-- \nfunction event_1346_10088()\n    \nend\n\n-- [SCENE] Début du combat - Client\n-- \nfunction event_1346_11673()\n    function fightEnuStart()\r\n    \tdeleteActor(weshActor)\r\n    \tdeleteActor(jelassieActor)\r\n    \tdeleteActor(biffActor)\r\n    \tCamera.attachCameraToMobile(playerId)\r\n    end\r\n    \r\n    FightEvent.addPlacementStartCallback(\"fightEnuStart\")\nend\n\n-- [SCENE] Victoire des joueurs\n-- \nfunction event_1346_10105()\n    \nend\n\n-- [VAISSEAU] Forage\n-- \nfunction event_1346_10083(playerTriggerer)\n    \nend\n\n-- [VAISSEAU] Forage - On rapproche les joueurs\n-- \nfunction event_1346_10343(playerTriggerer)\n    function forageStart(playerTriggerer)\r\n    \tMobile.setMobileDirection(playerTriggerer, 7)\r\n    \tMobile.setMobileAnimation(playerTriggerer, \"AnimInteraction-Minage-Debut\", \"forageBoucle\",playerTriggerer)\r\n    end\r\n    \r\n    function forageBoucle(playerTriggerer)\r\n    \tshakeEffectId = Effect.createCameraShakeEffect(500, 3800, 1000, 6)\r\n    \tinvoke(4500, 1, \"Effect.stopEffect\", shakeEffectId)\r\n    \tMobile.setMobileAnimation(playerTriggerer, \"AnimInteraction-Minage-Boucle\")\r\n    end\r\n    \r\n    function brigadeApp()\r\n    \tgardApp(gardA,130,-32,0,1)\r\n    \tgardApp(gardB,128,-30,0,1)\r\n    \tgardApp(gardC,130,-28,0,1)\r\n    \tgardApp(gardD,132,-34,0,3)\r\n    \tgardApp(gardE,135,-34,0,3)\r\n    \tgardApp(gardF,132,-28,0,7)\r\n    \tgardApp(gardG,136,-32,0,5)\r\n    \t--gardApp(gardH,130,-32,0,1,math.random(1000))\r\n    \tgardApp(gardI,128,-33,0,1)\r\n    \tgardApp(gardJ,134,-30,0,7)\r\n    \tgardApp(gardK,132,-26,0,7)\r\n    \tMobile.setMobileAnimation(playerTriggerer, \"AnimInteraction-Minage-Fin\")\r\n    end\r\n    \r\n    forageStart(playerTriggerer)\r\n    invoke(5200, 1, \"brigadeApp\")\nend\n\n-- [VAISSEAU] Forage - Téléportation\n-- \nfunction event_1346_10192()\n    \nend\n\n-- [SCENE] Le joueur déclenche le premier combat Slek\n-- \nfunction event_1346_10340(longAA, longAB, longAC, longAD)\n    function slekFirstApp(longAA,longAB,longAC,longAD)\r\n    \tMobile.setMobileDirection(longAA, 1)\r\n    \tMobile.setMobileDirection(longAB, 1)\r\n    \tMobile.setMobileDirection(longAC, 5)\r\n    \tMobile.setMobileDirection(longAD, 5)\t\r\n    \tMobile.setMobileAnimation(longAA, \"AnimApparition\")\r\n    \tMobile.setMobileAnimation(longAB, \"AnimApparition\")\r\n    \tMobile.setMobileAnimation(longAC, \"AnimApparition\")\r\n    \tMobile.setMobileAnimation(longAD, \"AnimApparition\")\r\n    end\r\n    \r\n    shakeEffectId = Effect.createCameraShakeEffect(500, 1700, 1000, 6)\r\n    invoke(2000, 1, \"Effect.stopEffect\", shakeEffectId)\r\n    \r\n    invoke(1000,1,\"slekFirstApp\",longAA,longAB,longAC,longAD)\r\nend\n\n-- [SCENE] Le joueur déclenche le premier combat Slek - Début du combat\n-- \nfunction event_1346_10341(longAA, longAB, longAC, longAD)\n    \nend\n\n","functions":["rabetTurn","deleteActor","animActor","weshTurn","weshApp","jelassieTurn","jelassieApp","biffTurn","biffApp","grisApp","gardApp","event_1346_10081","event_1346_10082","event_1346_10087","rabetStart","rabetSuite","opulenceStart","rabetEnd","grisHide","event_1346_10088","event_1346_11673","fightEnuStart","event_1346_10105","event_1346_10083","event_1346_10343","forageStart","forageBoucle","brigadeApp","event_1346_10192","event_1346_10340","slekFirstApp","event_1346_10341"],"quest_calls":[],"dialogue_calls":[]},"scenario/1347.lua":{"source":"grisActor=Mobile.generateClientMobileId()\r\n\r\nplayerId=Context.getPlayer()\r\n\r\nfunction grisApp()\r\n\tActor.createActor(grisActor, 117901807, -1, -9, 9, 4)\r\n\tMobile.setMobileAnimation(grisActor, \"AnimApparition\")\t\r\n\tMobile.setMobileDirection(grisActor, 3)\r\n\tActor.setActorHeight(grisActor,4)\r\n\tinvoke(500,1,\"UI.displaySmiley\",17917,grisActor,0)\r\nend\r\n\r\nfunction prisonnerPlayInit(prisonnerId)\n\tMobile.setMobileAnimationStaticKey(prisonnerId, \"AnimStatique03\")\r\nend\n\n-- [INITALISATION] Variables\n-- \nfunction event_1347_10084()\n    \nend\n\n-- [INITALISATION] Inscription des joueurs - Porte fermée\n-- \nfunction event_1347_10085(prisonnerId)\n    Mobile.addMobileCreationCallback(prisonnerId, \"prisonnerPlayInit\", prisonnerId)\r\n    UI.displaySplashText(\"zinit.penitenslek.entree\")\r\n    \r\n    \r\nend\n\n-- [INITALISATION] Inscription des joueurs - Porte ouverte\n-- \nfunction event_1347_10858(prisonnerId)\n    Mobile.addMobileCreationCallback(prisonnerId, \"prisonnerPlayInit\", prisonnerId)\r\n    UI.displaySplashText(\"zinit.penitenslek.entree\")\nend\n\n-- [SCENE] Gris XIII apparaît\n-- \nfunction event_1347_10195()\n    function grisWarp()\r\n    \tMobile.setMobileDirection(grisActor, 7)\r\n    \tMobile.setMobileAnimation(grisActor, \"AnimMort\")\r\n    end\r\n    \r\n    function grisWarpTwo()\r\n    \tMobile.setMobilePosition(grisActor, 5, -8, 20)\r\n    \tMobile.setMobileAnimation(grisActor, \"AnimApparition\")\r\n    \tMobile.setMobileDirection(grisActor, 5)\r\n    end\r\n    \r\n    function grisWarpThree()\r\n    \tMobile.setMobileDirection(grisActor, 1)\r\n    \tMobile.moveMobile(grisActor, 16, -8, 7, \"grisWarp\")\r\n    \tCamera.attachCameraToMobile(playerId)\r\n    end\r\n    \r\n    Camera.setWorldTarget(-1, -9, 9)\r\n    invoke(1000,1,\"grisApp\")\r\n    invoke(5000,1,\"grisWarp\")\r\n    invoke(6000, 1, \"grisWarpTwo\")\r\n    invoke(7000, 1, \"grisWarpThree\")\nend\n\n-- [SCENE] Le warp s'ouvre\n-- \nfunction event_1347_10196()\n    \nend\n\n-- [01][SCENE] Le joueur arrive dans la salle 01\n-- \nfunction event_1347_10205(longAA, longAB, longAC)\n    function fightOneApp(longAA,longAB,longAC)\r\n    \tMobile.setMobileAnimation(longAA, \"AnimApparition\")\r\n    \tMobile.setMobileAnimation(longAB, \"AnimApparition\")\r\n    \tMobile.setMobileAnimation(longAC, \"AnimApparition\")\r\n    \tMobile.setMobileDirection(longAA, 5)\r\n    \tMobile.setMobileDirection(longAB, 5)\r\n    \tMobile.setMobileDirection(longAC, 5)\r\n    end\r\n    \r\n    fightOneApp(longAA,longAB,longAC)\nend\n\n-- [01][SCENE] Début du combat\n-- \nfunction event_1347_10206()\n    UI.openRewardsDialog(\"defi.donjon.penitenslek.01\")\nend\n\n-- [01][COMBAT] Lancement du combat de la salle 01\n-- \nfunction event_1347_10197()\n    \nend\n\n-- [01][COMBAT] Victoire salle 01\n-- \nfunction event_1347_10199()\n    \nend\n\n-- [02][SCENE] Le joueur arrive dans la salle 02\n-- \nfunction event_1347_10207(longBA, longBB, longBC, mageAA)\n    function fightOneApp(longBA,longBB,longBC,mageAA)\r\n    \tMobile.setMobileAnimation(longBA, \"AnimApparition\")\r\n    \tMobile.setMobileAnimation(longBB, \"AnimApparition\")\r\n    \tMobile.setMobileAnimation(longBC, \"AnimApparition\")\r\n    \tMobile.setMobileAnimation(mageAA, \"AnimApparition\")\r\n    \tMobile.setMobileDirection(longBA, 7)\r\n    \tMobile.setMobileDirection(longBB, 7)\r\n    \tMobile.setMobileDirection(longBC, 7)\r\n    \tMobile.setMobileDirection(mageAA, 7)\r\n    end\r\n    \r\n    fightOneApp(longBA,longBB,longBC,mageAA)\nend\n\n-- [02][SCENE] Début du combat\n-- \nfunction event_1347_10208()\n    UI.openRewardsDialog(\"defi.donjon.penitenslek.01\")\r\nend\n\n-- [02][COMBAT] Lancement du combat de la salle 02\n-- \nfunction event_1347_10198()\n    \nend\n\n-- [02][COMBAT] Victoire salle 02\n-- \nfunction event_1347_10200()\n    \nend\n\n-- [02][COMBAT] Ouverture de la porte\n-- \nfunction event_1347_10209()\n    function grisAppSecond()\r\n    \tMobile.setMobilePosition(grisActor, 25, 22, -10)\r\n    \tMobile.setMobileDirection(grisActor, 5)\r\n    \tMobile.setMobileAnimation(grisActor, \"AnimApparition\",\"grisDisappSecond\")\r\n    end\r\n    \r\n    function grisDisappSecond()\r\n    \tMobile.setMobileAnimation(grisActor, \"AnimMort\")\r\n    end\r\n    \r\n    invoke(400,1,\"grisAppSecond\")\nend\n\n-- [03][SCENE] - Le joueur arrive\n-- \nfunction event_1347_10243()\n    function grisAppApp()\r\n    \tMobile.setMobilePosition(grisActor, 5, 28, 0)\r\n    \tMobile.setMobileDirection(grisActor, 1)\r\n    \tMobile.setMobileAnimation(grisActor, \"AnimApparition\")\r\n    \tinvoke(500,1,\"UI.displaySmiley\",17,grisActor,0)\r\n    end\r\n    \r\n    invoke(400,1,\"grisAppApp\")\r\n    \r\n    UI.openRewardsDialog(\"defi.donjon.penitenslek.02\")\nend\n\n-- [03][SCENE] - Le joueur récupère son stuff\n-- \nfunction event_1347_10210()\n    \nend\n\n-- [03][SCENE] - La porte s'ouvre - timer\n-- \nfunction event_1347_10217()\n    Mobile.setMobileAnimation(grisActor, \"AnimMort\")\r\nend\n\n-- [03][SCENE] - La porte s'ouvre\n-- \nfunction event_1347_10244()\n    function grisAppFirst()\r\n    \tMobile.setMobilePosition(grisActor, 5, 24, 0)\r\n    \tMobile.setMobileDirection(grisActor, 5)\r\n    \tMobile.setMobileAnimation(grisActor, \"AnimApparition\",\"grisDisappFirst\")\r\n    end\r\n    \r\n    function grisDisappFirst()\r\n    \tMobile.setMobileAnimation(grisActor, \"AnimMort\")\r\n    end\r\n    \r\n    invoke(400,1,\"grisAppFirst\")\nend\n\n-- [04][SCENE] Le joueur arrive dans la dernière salle\n-- \nfunction event_1347_10201()\n    Camera.setWorldTarget(-14, 21, 20)\nend\n\n-- [04][SCENE] Le phorreur se fait dévorer\n-- \nfunction event_1347_10203(prisonnerId)\n    function grisAppFinal()\r\n    \tMobile.setMobilePosition(grisActor, -14, 21, 20)\r\n    \tMobile.setMobileAnimation(grisActor, \"AnimApparition\")\r\n    \tMobile.setMobileDirection(grisActor, 5)\r\n    end\r\n    \r\n    function prisonnerEat(prisonnerId)\r\n    \tMobile.setMobileAnimation(prisonnerId, \"AnimDevoration\")\r\n    \tMobile.setMobileVisible(grisActor, false)\r\n    end\r\n    \r\n    function lookPlayer()\r\n    \tMobile.setMobileAnimationStaticKey(prisonnerId, \"AnimStatique\")\r\n    \tCamera.attachCameraToMobile(playerId)\r\n    end\r\n    \r\n    invoke(400,1,\"grisAppFinal\")\r\n    invoke(1400,1,\"prisonnerEat\",prisonnerId)\r\n    invoke(3500,1,\"lookPlayer\")\nend\n\n-- [04][SCENE] Le combat contre le prisonnier commence\n-- \nfunction event_1347_10204(prisonnerId)\n    \nend\n\n-- [04][COMBAT] Victoire salle 03\n-- \nfunction event_1347_10202()\n    \nend\n\n-- [00][COMBAT] Défaite - Message box\n-- \nfunction event_1347_10239()\n    UI.displaySplashText(\"defi.donjon.vampyro.lost\")\nend\n\n-- [00][COMBAT] Réapplication de l'état\n-- \nfunction event_1347_10240()\n    \nend\n\n-- [00] Lancement d'un combat\n-- \nfunction event_1347_10241()\n    \nend\n\n","functions":["grisApp","prisonnerPlayInit","event_1347_10084","event_1347_10085","event_1347_10858","event_1347_10195","grisWarp","grisWarpTwo","grisWarpThree","event_1347_10196","event_1347_10205","fightOneApp","event_1347_10206","event_1347_10197","event_1347_10199","event_1347_10207","fightOneApp","event_1347_10208","event_1347_10198","event_1347_10200","event_1347_10209","grisAppSecond","grisDisappSecond","event_1347_10243","grisAppApp","event_1347_10210","event_1347_10217","event_1347_10244","grisAppFirst","grisDisappFirst","event_1347_10201","event_1347_10203","grisAppFinal","prisonnerEat","lookPlayer","event_1347_10204","event_1347_10202","event_1347_10239","event_1347_10240","event_1347_10241"],"quest_calls":["UI.openRewardsDialog(\"defi.donjon.penitenslek.01\")","UI.openRewardsDialog(\"defi.donjon.penitenslek.01\")\r","UI.openRewardsDialog(\"defi.donjon.penitenslek.02\")"],"dialogue_calls":[]},"scenario/1349.lua":{"source":"playerId=Context.getPlayer()\r\n\r\nfunction gouleTurn(mobileId, direction)\r\n\tMobile.setMobileDirection(mobileId, direction)\r\nend\r\n\r\nfunction gouleVisible(mobileId, bool)\r\n\tMobile.setMobileVisible(mobileId, bool)\r\nend\r\n\r\nfunction goulePouf(mobileId)\r\n\tMobile.setMobileAnimation(mobileId, \"AnimSort-Teleportation-Fin\")\r\nend\n\n-- [INITIALISATION] Variables\n-- \nfunction event_1349_10176()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au 