n(gouleTwo, \"AnimSort-Teleportation-Fin\")\r\n    \tMobile.setMobileAnimation(gouleThree, \"AnimSort-Teleportation-Fin\")\r\n    \tMobile.setMobileAnimation(gouleFour, \"AnimSort-Teleportation-Fin\")\r\n    \tMobile.setMobileAnimation(gouleFive, \"AnimSort-Teleportation-Fin\")\r\n    \tMobile.setMobileAnimation(gouleSix, \"AnimSort-Teleportation-Fin\")\r\n    \tMobile.setMobileAnimation(gouleSeven, \"AnimSort-Teleportation-Fin\")\r\n    end\r\n    \r\n    \r\n    trace(\"LE TRIGGER DE LA SALLE 01 EST ACTIVE\")\r\n    gouleStart(gouleOne,gouleTwo,gouleThree,gouleFour,gouleFive,gouleSix,gouleSeven)\nend\n\n-- [01][SCENE] Déclenchement du Combat\n-- \nfunction event_1349_10161(gouleOne, gouleTwo, gouleThree, gouleFour, gouleFive, gouleSix)\n    \nend\n\n-- [01][DEFI] Lancement\n-- \nfunction event_1349_10152()\n    UI.openRewardsDialog(\"defi.donjon.vampyro.01\")\r\n    trace(\"LE PREMIER COMBAT EST LANCE\")\nend\n\n-- [01][DEFI] Un des joueurs échoue\n-- \nfunction event_1349_10155()\n    trace(\"LE PREMIER COMBAT EST PERDU\")\nend\n\n-- [01][DEFI] Combat gagné\n-- \nfunction event_1349_10187()\n    trace(\"LE PREMIER COMBAT EST GAGNE\")\nend\n\n-- [01][DEFI] Un des joueurs échoue - Résolution NO\n-- \nfunction event_1349_10181(defi, fightA)\n    UI.displaySplashText(\"defi.donjon.vampyro.lost\")\r\n    trace(\"DEFI =\", defi)\r\n    trace(\"fightA = \", fightA)\nend\n\n-- [01][DEFI] Résolution OK\n-- \nfunction event_1349_10184(defi, fightA)\n    UI.displaySplashText(\"defi.donjon.win\")\nend\n\n-- [02][DEFI] Lancement\n-- \nfunction event_1349_10153()\n    UI.openRewardsDialog(\"defi.donjon.vampyro.01\")\nend\n\n-- [02][DEFI] Un des joueurs échoue\n-- \nfunction event_1349_10156()\n    \nend\n\n-- [02][DEFI] Combat gagné\n-- \nfunction event_1349_10188()\n    \nend\n\n-- [02][DEFI] Un des joueurs échoue - Résolution NO\n-- \nfunction event_1349_10182()\n    UI.displaySplashText(\"defi.donjon.vampyro.lost\")\nend\n\n-- [02][DEFI] Résolution OK\n-- \nfunction event_1