 \"gouleVisible\", gouleDD, false)\r\n    \tMobile.addMobileCreationCallback(gouleDE, \"gouleVisible\", gouleDE, false)\r\n    \tMobile.addMobileCreationCallback(gouleDF, \"gouleVisible\", gouleDF, false)\r\n    \tMobile.addMobileCreationCallback(vampyro, \"gouleVisible\", vampyro, false)\r\n    \tinvoke(1300, 1, \"vampyroStart\",gouleDA,gouleDB,gouleDC,gouleDD,gouleDE,gouleDF,vampyro)\r\n    end\r\n    \r\n    function vampyroStart(gouleDA,gouleDB,gouleDC,gouleDD,gouleDE,gouleDF,vampyro)\r\n    \tMobile.addMobileCreationCallback(vampyro, \"gouleVisible\", vampyro, true)\r\n    \tMobile.setMobileAnimation(vampyro, \"AnimApparition\", \"Mobile.setMobileAnimation\", vampyro, \"AnimSort-VampyroStyle\")\r\n    \tinvoke(2300, 1, \"GouleApp\",gouleDA,gouleDB,gouleDC,gouleDD,gouleDE,gouleDF,vampyro)\r\n    end\r\n    \r\n    function GouleApp(gouleDA,gouleDB,gouleDC,gouleDD,gouleDE,gouleDF,vampyro)\r\n    \tMobile.addMobileCreationCallback(gouleDA, \"gouleVisible\", gouleDA, true)\r\n    \tMobile.addMobileCreationCallback(gouleDB, \"gouleVisible\", gouleDB, true)\r\n    \tMobile.addMobileCreationCallback(gouleDC, \"gouleVisible\", gouleDC, true)\r\n    \tMobile.addMobileCreationCallback(gouleDD, \"gouleVisible\", gouleDD, true)\r\n    \tMobile.addMobileCreationCallback(gouleDE, \"gouleVisible\", gouleDE, true)\r\n    \tMobile.addMobileCreationCallback(gouleDF, \"gouleVisible\", gouleDF, true)\r\n    \tMobile.addMobileCreationCallback(gouleDA, \"goulePouf\", gouleDA)\r\n    \tMobile.addMobileCreationCallback(gouleDB, \"goulePouf\", gouleDB)\r\n    \tMobile.addMobileCreationCallback(gouleDC, \"goulePouf\", gouleDC)\r\n    \tMobile.addMobileCreationCallback(gouleDD, \"goulePouf\", gouleDD)\r\n    \tMobile.addMobileCreationCallback(gouleDE, \"goulePouf\", gouleDE)\r\n    \tMobile.addMobileCreationCallback(gouleDF, \"goulePouf\", gouleDF)\r\n    \tCamera.attachCameraToMobile(playerId)\r\n    end\r\n    \r\n    gouleStart(gouleDA,gouleDB,gouleDC,gouleDD,gouleDE,gouleDF,vampyro)\