e)\r\n    Mobile.addMobileCreationCallback(gardAA, \"gardPlayInit\", gardAA,1,true)\r\n    Mobile.addMobileCreationCallback(gardAB, \"gardPlayInit\", gardAB,1,true)\r\n    Mobile.addMobileCreationCallback(magiBA, \"gardPlayInit\", magiBA,3,true)\r\n    Mobile.addMobileCreationCallback(magiBB, \"gardPlayInit\", magiBB,3,true)\r\n    Mobile.addMobileCreationCallback(reineCA, \"gardPlayInit\", reineCA,3,true)\r\n    Mobile.addMobileCreationCallback(gardCA, \"gardPlayInit\", gardCA,3,true)\r\n    Mobile.addMobileCreationCallback(gardCB, \"gardPlayInit\", gardCB,3,true)\nend\n\n-- [COMBAT] Salle 01\n-- \nfunction event_1350_10124()\n    World.setPictoAlpha(-10, -20, 0, 1, 1000)\r\n    World.setPictoAlpha(-11, -20, 0, 1, 1000)\nend\n\n-- [COMBAT] Salle 02\n-- \nfunction event_1350_10125()\n    \nend\n\n-- [COMBAT] Salle 03\n-- \nfunction event_1350_10126()\n    \nend\n\n-- [COMBAT] Salle 03 - Victoire\n-- \nfunction event_1350_10214()\n    \nend\n\n-- [COMBAT] Salle 03 - Scène\n-- \nfunction event_1350_10245()\n    invoke(2500,1,\"Sound.playSound\",70500007,  50)\r\n    blackScreen = Effect.createFullScreenSprite(1500,8000,0,0,0,0)\r\n    invoke(8500, 1, \"Effect.stopEffect\",blackScreen)\r\nend\n\n-- [COMBAT] Salle 03 - Téléportation\n-- \nfunction event_1350_10191()\n    \nend\n\n-- [03][SCENE] Arrivée dans la salle du trône\n-- \nfunction event_1350_10242()\n    Camera.setWorldTarget(-27, -65, 20)\r\n    invoke(3000, 1, \"Camera.attachCameraToMobile\",playerId)\nend\n\n-- [01][COMBAT] Le combat démarre\n-- \nfunction event_1350_10246(gardAC, gardAD)\n    Mobile.setMobileVisible(gardAC, true)\r\n    Mobile.setMobileVisible(gardAD, true)\r\n    Mobile.setMobileAnimation(gardAC, \"AnimApparition\")\r\n    Mobile.setMobileAnimation(gardAD, \"AnimApparition\")\nend\n\n-- [02][COMBAT] Le combat démarre\n-- \nfunction event_1350_10247(gardBA, gardBB, gardBC)\n    Mobile.setMobileVisible(gardBA, true)\r\n    Mobile.setMobileVisible(gardBB, true)\r\n    Mobile.setMobileVisible(gardBC, true)\r\n    Mobile.setMobileAnimation(gardBA, \"AnimApparition\")\r\n    Mobile.setMobileAnimation(gardBB, \"AnimApparition\")\r\n    Mobile.setMobileAnimation(gardBC, \"AnimApparition\")\nend\n\n","functions":["gardPlayInit","event_1350_10211","event_1350_10123","event_1350_10124","event_1350_10125","event_1350_10126","event_1350_10214","event_1350_10245","event_1350_10191","event_1350_10242","event_1350_10246","event_1350_10247"],"quest_calls":[],"dialogue_calls":[]},"scenario/1358.lua":{"source":"\n\n-- [INITIALISATION] Inscription du joueur\n-- \nfunction event_1358_10253()\n    \nend\n\n-- [SORTIE] Mort et sortie de l'instance\n-- \nfunction event_1358_10263()\n    \nend\n\n","functions":["event_1358_10253","event_1358_10263"],"quest_calls":[],"dialogue_calls":[]},"scenario/1364.lua":{"source":"function fighterAttack(fighterId, targetId, animFighter, delay)\r\n\tinvoke(delay, 1, \"Mobile.setMobileAnimation\", fighterId, animFighter)\r\n\tinvoke(delay+750, 1, \"Mobile.setMobileAnimation\", targetId, \"AnimHit\")\r\nend\r\n\r\nplayerId = Context.getPlayer()\n\n-- [INITIALISATION] Variables\n-- \nfunction event_1364_10275()\n    \nend\n\n-- [INITIALISATION] Inscription du joueur\n-- \nfunction event_1364_10276(grisDate)\n    date=toLong(grisDate)\r\n    UI.startCountdown(60,date)\nend\n\n-- [PARCOURS] Waypoint 0 - Arrivée\n-- \nfunction event_1364_10277(pikotAA, tatorAA, patteAA, fightA, grisId, wayStep)\n    trace(\"JE SUIS ARRIVE AU POINT\", wayStep)\nend\n\n-- [PARCOURS] Waypoint 0 - Départ\n-- \nfunction event_1364_10278(wayStep, playerTriggerer, grisId)\n    trace(\"ETAPE =\", wayStep)\r\n    UI.displaySplashText(\"zinit.chap02.palier02.gris.quest.01\")\r\n    invoke(500,1,\"UI.displaySmiley\",17,grisId)\r\n    Mobile.setMobileAnimation(playerTriggerer, \"AnimEmote-AppelChat\")\r\n    x,y=Mobile.getMobilePosition(playerTriggerer)\r\n    Mobile.setMobileLookAt(grisId,x,y,false)\nend\n\n-- [PARCOURS] Waypoint 1 - Arrivée - Les mobs sont vivants\n-- \nfunction event_1364_10279(pikotAA, tatorAA, patteAA, fightA, grisId, fightStart, wayStep)\n    function grisFightA(pikotAA, tatorAA, patteAA, grisId,fightStart)\r\n    \tMobile.setMobileAnimationStaticKey(pikotAA, \"AnimStatique02\")\r\n    \tMobile.setMobileAnimationStaticKey(tatorAA, \"AnimStatique02\")\r\n    \tMobile.setMobileAnimationStaticKey(patteAA, \"AnimStatique02\")\r\n    end\r\n    \r\n    --UI.openRewardsDialog(\"zinit.c2.p2.gris.attacked\")\r\n    trace(\"JE SUIS ARRIVE AU POINT\", wayStep)\r\n    UI.displaySplashText(\"zinit.c2.p2.gris.attacked\")\r\n    UI.startCountdown(60)\r\n    Mobile.setMobileDirection(grisId, 3)\r\n    Mobile.setMobileAnimation(grisId, \"AnimComp-Peur-Debut\", \"Mobile.setMobileAnimation\",grisId,\"AnimComp-Peur-Boucle\")\r\n    grisFightA(pikotAA, tatorAA, patteAA,grisId,fightStart)\r\nend\n\n-- [PARCOURS] Waypoint 1 - Départ\n-- \nfunction event_1364_10281(wayStep, playerTriggerer, grisId)\n    UI.stopCountdown()\r\n    \r\n    Mobile.setMobileAnimation(playerTriggerer, \"AnimEmote-AppelChat\")\r\n    x,y=Mobile.getMobilePosition(playerTriggerer)\r\n    Mobile.setMobileLookAt(grisId,x,y,false)\r\n    \tinvoke(500,1,\"UI.displaySmiley\",17917,grisActor,0)\r\n    \r\nend\n\n-- [PARCOURS] Waypoint 2 - Standart\n-- \nfunction event_1364_10282(wayStep)\n    trace(\"JE SUIS ARRIVE AU POINT\", wayStep)\nend\n\n-- [PARCOURS] Waypoint 3 - Arrivée - Les mobs sont vivants\n-- \nfunction event_1364_10283(fightB, grisId, pikotBA, tatorBA, patteBA, wayStep)\n    --UI.openRewardsDialog(\"zinit.c2.p2.gris.attacked\")\r\n    trace(\"JE SUIS ARRIVE AU POINT\", wayStep)\r\n    UI.displaySplashText(\"zinit.c2.p2.gris.attacked\")\r\n    UI.startCountdown(60)\r\n    Mobile.setMobileDirection(grisId, 3)\r\n    Mobile.setMobileAnimation(grisId, \"AnimComp-Peur-Debut\", \"Mobile.setMobileAnimation\",grisId,\"AnimComp-Peur-Boucle\")\r\n    \r\n    function grisFightA(pikotBA, tatorBA, patteBA, grisId)\r\n    \t--if fightB ==0 then\r\n    \t\tMobile.setMobileDirection(pikotBA, 1)\r\n    \t\tMobile.setMobileDirection(tatorBA, 7)\r\n    \t\tMobile.setMobileDirection(patteBA, 3)\r\n    \t\t\r\n    \t\tfighterAttack(pikotBA, grisId, \"AnimSort-Patapikot\", 1)\r\n    \t\tfighterAttack(tatorBA, grisId, \"AnimSort-Patats\", 2500)\r\n    \t\tinvoke(4000, 1, \"grisFightA\", pikotBA, tatorBA, patteBA,grisId)\r\n    \t--end\r\n    end\r\n    \r\n    --grisFightA(pikotBA, tatorBA, patteBA,grisId)\r\nend\n\n-- [PARCOURS] Waypoint 3 - Départ\n-- \nfunction event_1364_10285(wayStep, grisId, playerTriggerer)\n    UI.stopCountdown()\r\n    trace(\"ETAPE =\", wayStep)\r\n    Mobile.setMobileAnimation(playerTriggerer, \"AnimEmote-AppelChat\")\r\n    x,y=Mobile.getMobilePosition(playerTriggerer)\r\n    Mobile.setMobileLookAt(grisId,x,y,false)\r\n    \tinvoke(500,1,\"UI.displaySmiley\",17917,grisActor,0)\r\n    \r\nend\n\n-- [PARCOURS] Waypoint 4 - Standart\n-- \nfunction event_1364_10286(wayStep)\n    trace(\"JE SUIS ARRIVE AU POINT\", wayStep)\nend\n\n-- [PARCOURS] Waypoint 5 - Arrivée - Les mobs sont vivants\n-- \nfunction event_1364_10287(fightC, grisId, pikotCA, pikotCB, tatorCA, patteCA, wayStep)\n    --UI.openRewardsDialog(\"zinit.c2.p2.gris.attacked\")\r\n    trace(\"JE SUIS ARRIVE AU POINT\", wayStep)\r\n    UI.displaySplashText(\"zinit.c2.p2.gris.attacked\")\r\n    UI.startCountdown(60)\r\n    Mobile.setMobileDirection(grisId, 3)\r\n    Mobile.setMobileAnimation(grisId, \"AnimComp-Peur-Debut\", \"Mobile.setMobileAnimation\",grisId,\"AnimComp-Peur-Boucle\")\r\n    \r\n    function grisFightC(pikotCA, tatorCA, patteCA,grisId,pikotCB)\r\n    \t--if fightC ==0 then\r\n    \t\tMobile.setMobileDirection(pikotCA, 1)\r\n    \t\tMobile.setMobileDirection(tatorCA, 3)\r\n    \t\tMobile.setMobileDirection(patteCA, 5)\r\n    \t\tMobile.setMobileDirection(pikotCB, 7)\r\n    \t\t\r\n    \t\tfighterAttack(pikotCA, grisId, \"AnimSort-Patapikot\", 1)\r\n    \t\tfighterAttack(tatorCA, grisId, \"AnimSort-Patats\", 2500)\r\n    \t\tinvoke(4000, 1, \"grisFightC\", pikotCA, tatorCA, patteCA,grisId,pikotCB)\r\n    \t--end\r\n    end\r\n    \r\n    --grisFightC(pikotCA, tatorCA, patteCA,grisId,pikotCB)\r\nend\n\n-- [PARCOURS] Waypoint 5 - Départ\n-- \nfunction event_1364_10289(playerTriggerer, grisId)\n    UI.stopCountdown()\r\n    Mobile.setMobileAnimation(playerTriggerer, \"AnimEmote-AppelChat\")\r\n    x,y=Mobile.getMobilePosition(playerTriggerer)\r\n    Mobile.setMobileLookAt(grisId,x,y,false)\r\n    \tinvoke(500,1,\"UI.displaySmiley\",17917,grisActor,0)\r\n    \r\nend\n\n-- [PARCOURS] Waypoint 6 - Standart\n-- \nfunction event_1364_10290(wayStep)\n    trace(\"JE SUIS ARRIVE AU POINT\", wayStep)\nend\n\n-- [PARCOURS] Waypoint 7 - Arrivée - Les mobs sont vivants\n-- \nfunction event_1364_10291(fightD, grisId, pikotDA, tatorDA, patteDA, tatorDB, wayStep)\n    --UI.openRewardsDialog(\"zinit.c2.p2.gris.attacked\")\r\n    trace(\"JE SUIS ARRIVE AU POINT\", wayStep)\r\n    UI.displaySplashText(\"zinit.c2.p2.gris.attacked\")\r\n    UI.startCountdown(60)\r\n    Mobile.setMobileDirection(grisId, 3)\r\n    Mobile.setMobileAnimation(grisId, \"AnimComp-Peur-Debut\", \"Mobile.setMobileAnimation\",grisId,\"AnimComp-Peur-Boucle\")\r\n    \r\n    function grisFightD(pikotDA, tatorDA, patteDA,grisId,tatorDB)\r\n    \t--if fightD ==0 then\r\n    \t\tMobile.setMobileDirection(pikotDA, 1)\r\n    \t\tMobile.setMobileDirection(tatorDA, 3)\r\n    \t\tMobile.setMobileDirection(patteDA, 5)\r\n    \t\tMobile.setMobileDirection(tatorDB, 7)\r\n    \t\t\r\n    \t\tfighterAttack(pikotDA, grisId, \"AnimSort-Patapikot\", 1)\r\n    \t\tfighterAttack(tatorDA, grisId, \"AnimSort-Patats\", 2500)\r\n    \t\tinvoke(4000, 1, \"grisFightD\", pikotDA, tatorDA, patteDA,grisId,tatorDB)\r\n    \t--end\r\n    end\r\n    \r\n    --grisFightD(pikotDA, tatorDA, patteDA,grisId,tatorDB)\r\nend\n\n-- [PARCOURS] Waypoint 7 - Départ\n-- \nfunction event_1364_10293(playerTriggerer, grisId)\n    UI.stopCountdown()\r\n    Mobile.setMobileAnimation(playerTriggerer, \"AnimEmote-AppelChat\")\r\n    x,y=Mobile.getMobilePosition(playerTriggerer)\r\n    Mobile.setMobileLookAt(grisId,x,y,false)\r\n    \tinvoke(500,1,\"UI.displaySmiley\",17917,grisActor,0)\r\n    \r\nend\n\n-- [PARCOURS] Waypoint 8 - Standart\n-- \nfunction event_1364_10294(wayStep)\n    trace(\"JE SUIS ARRIVE AU POINT\", wayStep)\nend\n\n-- [PARCOURS] Waypoint 9 - Arrivée - Les mobs sont vivants\n-- \nfunction event_1364_10295(fightE, grisId, pikotEA, tatorEA, patteEA, patteEB, wayStep)\n    --UI.openRewardsDialog(\"zinit.c2.p2.gris.attacked\")\r\n    trace(\"JE SUIS ARRIVE AU POINT\", wayStep)\r\n    UI.displaySplashText(\"zinit.c2.p2.gris.attacked\")\r\n    UI.startCountdown(60)\r\n    Mobile.setMobileDirection(grisId, 3)\r\n    Mobile.setMobileAnimation(grisId, \"AnimComp-Peur-Debut\", \"Mobile.setMobileAnimation\",grisId,\"AnimComp-Peur-Boucle\")\r\n    \r\n    function grisFightE(pikotEA, tatorEA, patteEA,grisId,patteEB)\r\n    \t--if fightE ==0 then\r\n    \t\tMobile.setMobileDirection(pikotEA, 1)\r\n    \t\tMobile.setMobileDirection(tatorEA, 3)\r\n    \t\tMobile.setMobileDirection(patteEA, 5)\r\n    \t\tMobile.setMobileDirection(patteEB, 7)\r\n    \t\t\r\n    \t\tfighterAttack(pikotEA, grisId, \"AnimSort-Patapikot\", 1)\r\n    \t\tfighterAttack(tatorEA, grisId, \"AnimSort-Patats\", 2500)\r\n    \t\tinvoke(4000, 1, \"grisFightE\", pikotEA, tatorEA, patteEA,grisId,patteEB)\r\n    \t--end\r\n    end\r\n    \r\n    --grisFightE(pikotEA, tatorEA, patteEA,grisId,patteEB)\r\nend\n\n-- [PARCOURS] Waypoint 9 - Départ\n-- \nfunction event_1364_10297(playerTriggerer, grisId)\n    UI.stopCountdown()\r\n    Mobile.setMobileAnimation(playerTriggerer, \"AnimEmote-AppelChat\")\r\n    x,y=Mobile.getMobilePosition(playerTriggerer)\r\n    Mobile.setMobileLookAt(grisId,x,y,false)\r\n    \tinvoke(500,1,\"UI.displaySmiley\",17917,grisActor,0)\r\n    \r\n    \r\nend\n\n-- [PARCOURS] Waypoint 10 - Standart\n-- \nfunction event_1364_10298(wayStep)\n    trace(\"JE SUIS ARRIVE AU POINT\", wayStep)\nend\n\n-- [PARCOURS] Waypoint 11 - Standart\n-- \nfunction event_1364_10299(wayStep)\n    trace(\"JE SUIS ARRIVE AU POINT\", wayStep)\nend\n\n-- [PARCOURS] Waypoint 12 - Standart\n-- \nfunction event_1364_10300(wayStep)\n    trace(\"JE SUIS ARRIVE AU POINT\", wayStep)\nend\n\n-- [PARCOURS] Waypoint 13 - Arrivée - Les mobs sont vivants\n-- \nfunction event_1364_10301(wayStep)\n    trace(\"JE SUIS ARRIVE AU POINT\", wayStep)\nend\n\n-- [PARCOURS] Waypoint 13 - Départ\n-- \nfunction event_1364_10302(grisId, playerTriggerer)\n    UI.stopCountdown()\r\n    Mobile.setMobileAnimation(playerTriggerer, \"AnimEmote-AppelChat\")\n    x,y=Mobile.getMobilePosition(playerTriggerer)\n    Mobile.setMobileLookAt(grisId,x,y,false)\n    \r\n    function grisExit(grisId)\r\n    \tMobile.setMobileDirection(grisId, 7)\r\n    \tMobile.setMobileAnimation(grisId, \"AnimMort\")\r\n    end\r\n    \r\n    invoke(1500,1,\"grisExit\",grisId)\r\n    \tinvoke(2000,1,\"UI.displaySmiley\",17917,grisActor,0)\r\nend\n\n-- [PARCOURS] Waypoint 13 - Destruction des blocs\n-- \nfunction event_1364_10303()\n    \nend\n\n-- [COMBAT A] Gris XIII meurt\n-- \nfunction event_1364_10304(grisId, wayStep)\n    UI.displaySplashText(\"zinit.c2.p2.gris.fail\")\r\n    UI.stopCountdown()\nend\n\n-- [COMBAT A] Les joueurs gagnent\n-- \nfunction event_1364_10305()\n    UI.stopCountdown()\nend\n\n-- [COMBAT B] Gris XIII meurt\n-- \nfunction event_1364_10306(grisId, wayStep)\n    UI.displaySplashText(\"zinit.c2.p2.gris.fail\")\r\n    UI.stopCountdown()\nend\n\n-- [COMBAT B] Les joueurs gagnent\n-- \nfunction event_1364_10307()\n    UI.stopCountdown()\nend\n\n-- [COMBAT C] Gris XIII meurt\n-- \nfunction event_1364_10308(grisId, wayStep)\n    UI.displaySplashText(\"zinit.c2.p2.gris.fail\")\r\n    UI.stopCountdown()\nend\n\n-- [COMBAT C] Les joueurs gagnent\n-- \nfunction event_1364_10309()\n    UI.stopCountdown()\nend\n\n-- [COMBAT D] Gris XIII meurt\n-- \nfunction event_1364_10310(grisId, wayStep)\n    UI.displaySplashText(\"zinit.c2.p2.gris.fail\")\r\n    UI.stopCountdown()\nend\n\n-- [COMBAT D] Les joueurs gagnent\n-- \nfunction event_1364_10311()\n    UI.stopCountdown()\nend\n\n-- [COMBAT E] Gris XIII meurt\n-- \nfunction event_1364_10312(grisId, wayStep)\n    UI.displaySplashText(\"zinit.c2.p2.gris.fail\")\r\n    UI.stopCountdown()\nend\n\n-- [COMBAT E] Les joueurs gagnent\n-- \nfunction event_1364_10313()\n    UI.stopCountdown()\nend\n\n-- [GENERAL] Les joueurs lancent un combat\n-- \nfunction event_1364_10314()\n    UI.stopCountdown()\nend\n\n-- [SORTIE] Le joueur quitte l'instance\n-- \nfunction event_1364_10315()\n    UI.stopCountdown()\nend\n\n-- [PARCOURS] Waypoint all - Départ de Gris XIII\n-- \nfunction event_1364_10316(wayNextStep)\n    trace(\"PROCHAINE ETAPE DE ROUTE =\",wayNextStep)\nend\n\n","functions":["fighterAttack","event_1364_10275","event_1364_10276","event_1364_10277","event_1364_10278","event_1364_10279","grisFightA","event_1364_10281","event_1364_10282","event_1364_10283","grisFightA","event_1364_10285","event_1364_10286","event_1364_10287","grisFightC","event_1364_10289","event_1364_10290","event_1364_10291","grisFightD","event_1364_10293","event_1364_10294","event_1364_10295","grisFightE","event_1364_10297","event_1364_10298","event_1364_10299","event_1364_10300","event_1364_10301","event_1364_10302","grisExit","event_1364_10303","event_1364_10304","event_1364_10305","event_1364_10306","event_1364_10307","event_1364_10308","event_1364_10309","event_1364_10310","event_1364_10311","event_1364_10312","event_1364_10313","event_1364_10314","event_1364_10315","event_1364_10316"],"quest_calls":["UI.openRewardsDialog(\"zinit.c2.p2.gris.attacked\")\r","UI.openRewardsDialog(\"zinit.c2.p2.gris.attacked\")\r","UI.openRewardsDialog(\"zinit.c2.p2.gris.attacked\")\r","UI.openRewardsDialog(\"zinit.c2.p2.gris.attacked\")\r","UI.openRewardsDialog(\"zinit.c2.p2.gris.attacked\")\r"],"dialogue_calls":[]},"scenario/1366.lua":{"source":"playerId = Context.getPlayer()\r\npetId = Context.getPlayerPetId()\r\nshakeEffectId = 0\r\n\r\nmagicien=Mobile.generateClientMobileId()\r\nassistante=Mobile.generateClientMobileId()\r\npublicOne=Mobile.generateClientMobileId()\r\npublicTwo=Mobile.generateClientMobileId()\r\npublicThree=Mobile.generateClientMobileId()\r\npuppetOne=Mobile.generateClientMobileId()\r\npuppetTwo=Mobile.generateClientMobileId()\r\ndresseur=Mobile.generateClientMobileId()\r\nsteak=Mobile.generateClientMobileId()\r\nmili=Mobile.generateClientMobileId()\r\nmiliTwo=Mobile.generateClientMobileId()\r\nmulou=Mobile.generateClientMobileId()\r\ngobgob=Mobile.generateClientMobileId()\r\n\r\n\r\n\r\nfunction scenarioModeOn(mobileId)\r\n\tsetPlayerVisible(mobileId,false)\r\n\tif toLong(mobileId) == playerId then\r\n\t\tCamera.setUserZoomLocked(true)\r\n\t\tUI.setShortcutEnabled(false)\t\t\t\t\t\t\r\n    \tUI.setUIVisible(false)\r\n   \t\tUI.manageFrame(\"World\",false)\r\n    end\r\nend\r\n\r\nfunction scenarioModeOff(mobileId)\r\n\tsetPlayerVisible(mobileId,true)\r\n\tif toLong(mobileId) == playerId then\r\n\t\tCamera.setUserZoomLocked(false)\r\n\t\tUI.setShortcutEnabled(true)\t\t\t\t\t\t\n    \tUI.setUIVisible(true)\n\t\tUI.manageFrame(\"World\",true)\r\n\tend\nend\r\n\r\nfunction setPlayerVisible(mobileId,visible)\r\n\tMobile.setMobileVisible(mobileId, visible)\r\n\tif(petId ~= 0) then\r\n\t    Mobile.setMobileVisible(petId, visible)\r\n\tend\r\nend\r\n\r\nfunction cameraShake()\r\n\tshakeEffectId = Effect.createCameraShakeEffect(250, 500, 250, 3)\r\n\tinvoke(1000, 1, \"Effect.stopEffect\", shakeEffectId)\r\nend\r\n\r\nfunction setCanonAnimation(mobileId)\r\n\tscenarioModeOn(mobileId)\r\n\tinvoke(1200, 1, \"cameraShake\")\r\n\tInteractiveElement.setAnimation(15224, \"AnimTrans_2\")\r\nend\n\n-- [INITIALISATION] Variables\n-- \nfunction event_1366_10320()\n    pyrotechnie()\nend\n\n-- [INITIALISATION] Interaction avec le Canoon\n-- \nfunction event_1366_10474(playerTriggerer)\n    setCanonAnimation(playerTriggerer)\nend\n\n-- Activation du Canoon (1)\n-- \nfunction event_1366_10475(playerTriggerer)\n    function animChute(playerTriggerer)\r\n    \tMobile.setMobileVisible(playerTriggerer, true)\r\n    \tMobile.setMobileDirection(playerTriggerer, 7)\r\n    \tMobile.setMobileAnimation(playerTriggerer, \"AnimIncarnam-Chute-Fin\",\"scenarioModeOff\", playerTriggerer)\r\n    end\r\n    \r\n    animChute(playerTriggerer)\nend\n\n-- Activation du Canoon (2)\n-- \nfunction event_1366_10476(playerTriggerer)\n    function animChute(playerTriggerer)\r\n    \tMobile.setMobileVisible(playerTriggerer, true)\r\n    \tMobile.setMobileDirection(playerTriggerer, 7)\r\n    \tMobile.setMobileAnimation(playerTriggerer, \"AnimIncarnam-Chute-Fin\",\"scenarioModeOff\", playerTriggerer)\r\n    end\r\n    \r\n    animChute(playerTriggerer)\nend\n\n-- Activation du Canoon (3)\n-- \nfunction event_1366_10477(playerTriggerer)\n    function animChute(playerTriggerer)\r\n    \tMobile.setMobileVisible(playerTriggerer, true)\r\n    \tMobile.setMobileDirection(playerTriggerer, 7)\r\n    \tMobile.setMobileAnimation(playerTriggerer, \"AnimIncarnam-Chute-Fin\",\"scenarioModeOff\", playerTriggerer)\r\n    end\r\n    \r\n    animChute(playerTriggerer)\nend\n\n-- Activation du Canoon (4)\n-- \nfunction event_1366_10478(playerTriggerer)\n    function animChute(playerTriggerer)\r\n    \tMobile.setMobileVisible(playerTriggerer, true)\r\n    \tMobile.setMobileDirection(playerTriggerer, 7)\r\n    \tMobile.setMobileAnimation(playerTriggerer, \"AnimIncarnam-Chute-Fin\",\"scenarioModeOff\", playerTriggerer)\r\n    end\r\n    \r\n    animChute(playerTriggerer)\nend\n\n-- Activation du Canoon (5)\n-- \nfunction event_1366_10479(playerTriggerer)\n    function animChute(playerTriggerer)\r\n    \tMobile.setMobileVisible(playerTriggerer, true)\r\n    \tMobile.setMobileDirection(playerTriggerer, 7)\r\n    \tMobile.setMobileAnimation(playerTriggerer, \"AnimIncarnam-Chute-Fin\",\"scenarioModeOff\", playerTriggerer)\r\n    end\r\n    \r\n    animChute(playerTriggerer)\nend\n\n-- [PORTE] Ouverture de la porte 01\n-- \nfunction event_1366_10686()\n    \nend\n\n-- [PORTE] Fermeture de la porte 01 (30 sec)\n-- \nfunction event_1366_10687()\n    \nend\n\n","functions":["scenarioModeOn","scenarioModeOff","setPlayerVisible","cameraShake","setCanonAnimation","event_1366_10320","event_1366_10474","event_1366_10475","animChute","event_1366_10476","animChute","event_1366_10477","animChute","event_1366_10478","animChute","event_1366_10479","animChute","event_1366_10686","event_1366_10687"],"quest_calls":[],"dialogue_calls":[]},"scenario/1367.lua":{"source":"playerId = Context.getPlayer()\n\n-- [INITIALISATION] Initialisation du Chronomètre\n-- \nfunction event_1367_10332()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_1367_10326()\n    function particleA()\r\n    \tpartA=Particle.addParticleSystem(800278, 3,3,0,35)\r\n    \tinvoke(11000,1,\"Particle.removeParticleSystem\",partA)\r\n    end\r\n    \r\n    function particleB()\r\n    \tpartB=Particle.addParticleSystem(800279, 3,3,0,10)\r\n    \tinvoke(10000,1,\"Particle.removeParticleSystem\",partB)\r\n    end\r\n    \r\n    invoke(5000,1,\"particleA\")\r\n    invoke(7000,1,\"particleB\")\r\nend\n\n-- [SCENE] Le joueur active l'interrupteur\n-- \nfunction event_1367_10327()\n    \nend\n\n-- [SORTIE] Le chronomètre arrive à terme\n-- \nfunction event_1367_10333()\n    \nend\n\n-- [SCENE] Un joueur monte sur l'interrupteur - Incrémentation\n-- \nfunction event_1367_10360()\n    Sound.playLocalSound(10, 70500004, 90, 78, 71 , 0)\nend\n\n-- [SCENE] Un joueur monte sur l'interrupteur - Emote possédée\n-- \nfunction event_1367_10361()\n    Mobile.setMobileDirection(playerId, 1)\r\n    Mobile.setMobileAnimation(playerId,\"AnimEmote-Harpe-Debut\")\nend\n\n-- [SCENE] Un joueur monte sur l'interrupteur - Décrémentation\n-- \nfunction event_1367_10362()\n    Sound.playLocalSound(10, 70500004, 90, 78, 71, 0)\nend\n\n-- [SCENE] Activation du monstre\n-- \nfunction event_1367_10363()\n    \nend\n\n-- [EVENT] Le joueur gagne le combat\n-- \nfunction event_1367_22943()\n    \nend\n\n","functions":["event_1367_10332","event_1367_10326","particleA","particleB","event_1367_10327","event_1367_10333","event_1367_10360","event_1367_10361","event_1367_10362","event_1367_10363","event_1367_22943"],"quest_calls":[],"dialogue_calls":[]},"scenario/1369.lua":{"source":"\nplayerId = Context.getPlayer()\n\n-- Sortie - Ok\n-- \nfunction event_1369_10338()\n    function verifOk()\r\n    \tInteractiveElement.setAnimation(15142, \"AnimTrans_2\")\r\n    \tParticle.addParticleSystem(800174, 42, -221, 0, 0)\r\n    end\r\n    \r\n    invoke(600, 1, \"verifOk\")\nend\n\n-- Sortie - Ok - Téléportation\n-- \nfunction event_1369_10339()\n    function spawnChestDone()\r\n    \tinvoke(1000, 1, \"Mobile.setMobileVisible\", playerId, true)\r\n    \tParticle.addParticleSystem(800174, 47, -218, 0, 0)\r\n    \tMobile.setMobileDirection(playerId, 1)\r\n    end\r\n    \r\n    spawnChestDone()\nend\n\n","functions":["event_1369_10338","verifOk","event_1369_10339","spawnChestDone"],"quest_calls":[],"dialogue_calls":[]},"scenario/1373.lua":{"source":"playerId = Context.getPlayer()\r\n\r\ntaikoSound = Mobile.generateClientMobileId()\r\n\r\nfunction masterLost(mobileId,combOne)\r\n\tinvoke(1000,1,\"UI.displaySmiley\",combOne,mobileId,0)\r\nend\r\n\r\nfunction taikoGauchePlayInit(taikoGauche)\r\n\tMobile.setMobileVisible(taikoGauche, false)\r\n\tMobile.setMobileDirection(taikoGauche, 7)\r\n\ttaikoGaucheStart(taikoGauche)\r\nend\r\n\r\nfunction taikoGaucheStart(taikoGauche)\r\n\tMobile.setMobileAnimation(taikoGauche, \"AnimIncarnam-Taiko01\", \"taikoGaucheStart\", taikoGauche)\r\nend\r\n\r\nfunction taikoDroitePlayInit(taikoDroite)\t\r\n\tMobile.setMobileVisible(taikoDroite, false)\r\n\tMobile.setMobileDirection(taikoDroite, 7)\r\n\ttaikoDroiteStart(taikoDroite)\r\nend\r\n\r\nfunction taikoDroiteStart(taikoDroite)\r\n\tMobile.setMobileAnimation(taikoDroite, \"AnimIncarnam-Taiko01\", \"taikoDroiteStart\", taikoDroite)\r\nend\n\n-- [INITIALISATION] Variables\n-- \nfunction event_1373_10374()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_1373_10375(taikoGauche, taikoDroite, masterOne)\n    Mobile.setMobileVisible(masterOne, false)\r\n    invoke(2300,1,\"Mobile.setMobileVisible\",masterOne, true)\r\n    invoke(2300,1,\"Particle.addParticleSystem\",800174, 0, -2, 1, 0)\r\n    \r\n    Mobile.addMobileCreationCallback(taikoGauche, \"taikoGauchePlayInit\", taikoGauche)\r\n    Mobile.addMobileCreationCallback(taikoDroite, \"taikoDroitePlayInit\", taikoDroite)\r\n    \r\n    invoke(2700,1,\"UI.openRewardsDialog\",\"defi.foire.shifumi\")\r\n    invoke(2700,1,\"UI.addReward\",13656)\nend\n\n-- [FOIRE DU TROOL] Le joueur fait Shi\n-- \nfunction event_1373_10382(masterOne)\n    \nend\n\n-- [FOIRE DU TROOL] Le joueur fait Shi - Boss\n-- \nfunction event_1373_10425(masterOne)\n    \nend\n\n-- [FOIRE DU TROOL] Le joueur fait Shi - Gagné\n-- \nfunction event_1373_10385(masterOne, duel)\n    if toLong(duel)==5 then\r\n    \tMobile.setMobileAnimation(masterOne, \"AnimEmote-ChiFouMi3\")\r\n    else\r\n    \tinvoke(1000,1,\"UI.displaySmiley\",22,masterOne,0)\r\n    end\r\nend\n\n-- [FOIRE DU TROOL] Le joueur fait Shi - Perdu\n-- \nfunction event_1373_10386(masterOne, duel)\n    anim=math.random(1,5)\r\n    \r\n    if toLong(duel)==5 then\r\n    \tif anim==1 then\r\n    \t\tMobile.setMobileAnimation(masterOne, \"AnimEmote-ChiFouMi2\")\r\n    \telse\r\n    \t\tMobile.setMobileAnimation(masterOne, \"AnimEmote-ChiFouMi4\")\t\r\n    \tend\r\n    else\r\n    \tmasterLost(masterOne,21)\r\n    end\r\nend\n\n-- [FOIRE DU TROOL] Le joueur fait Shi - Egalité\n-- \nfunction event_1373_10421(masterOne, duel)\n    if toLong(duel)==5 then\r\n    \tMobile.setMobileAnimation(masterOne, \"AnimEmote-ChiFouMi1\")\r\n    else\r\n    \tinvoke(1000,1,\"UI.displaySmiley\",20,masterOne,0)\r\n    end\nend\n\n-- [FOIRE DU TROOL] Le joueur fait Fu\n-- \nfunction event_1373_10383(masterOne)\n    \nend\n\n-- [FOIRE DU TROOL] Le joueur fait Fu - Boss\n-- \nfunction event_1373_10426(masterOne)\n    \nend\n\n-- [FOIRE DU TROOL] Le joueur fait Fu - Gagné\n-- \nfunction event_1373_10387(masterOne, duel)\n    if toLong(duel)==5 then\r\n    \tMobile.setMobileAnimation(masterOne, \"AnimEmote-ChiFouMi2\")\r\n    else\r\n    \tinvoke(1000,1,\"UI.displaySmiley\",21,masterOne,0)\r\n    end\nend\n\n-- [FOIRE DU TROOL] Le joueur fait Fu - Perdu\n-- \nfunction event_1373_10388(duel, masterOne)\n    anim=math.random(1,5)\r\n    \r\n    if toLong(duel)==5 then\r\n    \tif anim==1 then\r\n    \t\tMobile.setMobileAnimation(masterOne, \"AnimEmote-ChiFouMi1\")\r\n    \telse\r\n    \t\tMobile.setMobileAnimation(masterOne, \"AnimEmote-ChiFouMi4\")\t\r\n    \tend\r\n    else\r\n    \tmasterLost(masterOne,20)\r\n    end\nend\n\n-- [FOIRE DU TROOL] Le joueur fait Fu - Egalité\n-- \nfunction event_1373_10422(duel, masterOne)\n    if toLong(duel)==5 then\r\n    \tMobile.setMobileAnimation(masterOne, \"AnimEmote-ChiFouMi3\")\r\n    else\r\n    \tinvoke(1000,1,\"UI.displaySmiley\",22,masterOne,0)\r\n    end\nend\n\n-- [FOIRE DU TROOL] Le joueur fait Mi\n-- \nfunction event_1373_10384()\n    \nend\n\n-- [FOIRE DU TROOL] Le joueur fait Mi - Boss\n-- \nfunction event_1373_10427()\n    \nend\n\n-- [FOIRE DU TROOL] Le joueur fait Mi - Gagné\n-- \nfunction event_1373_10389(masterOne, duel)\n    if toLong(duel)==5 then\r\n    \tMobile.setMobileAnimation(masterOne, \"AnimEmote-ChiFouMi1\")\r\n    else\r\n    \tinvoke(1000,1,\"UI.displaySmiley\",20,masterOne,0)\r\n    end\nend\n\n-- [FOIRE DU TROOL] Le joueur fait Mi - Perdu\n-- \nfunction event_1373_10390(duel, masterOne)\n    anim=math.random(1,5)\r\n    \r\n    if toLong(duel)==5 then\r\n    \tif anim==1 then\r\n    \t\tMobile.setMobileAnimation(masterOne, \"AnimEmote-ChiFouMi3\")\r\n    \telse\n    \t\tMobile.setMobileAnimation(masterOne, \"AnimEmote-ChiFouMi4\")\t\n    \tend\r\n    else\r\n    \ttrace(\"DUEL=\",toLong(duel))\n    \tmasterLost(masterOne,22)\n    end\r\nend\n\n-- [FOIRE DU TROOL] Le joueur fait Mi - Egalité\n-- \nfunction event_1373_10423(duel, masterOne)\n    if toLong(duel)==5 then\r\n    \tMobile.setMobileAnimation(masterOne, \"AnimEmote-ChiFouMi2\")\r\n    else\r\n    \tinvoke(1000,1,\"UI.displaySmiley\",21,masterOne,0)\r\n    end\r\nend\n\n-- [SCENE] Victoire au duel 5 - Affichage\n-- \nfunction event_1373_10415(masterOne)\n    Mobile.setMobileVisible(masterOne,false)\r\n    Particle.addParticleSystem(800174, 0, -2, 1, 0)\r\n    UI.displaySplashText(\"defi.donjon.win\")\r\n    Mobile.setMobileAnimation(playerId, \"AnimEmote-Victoire\")\r\n    \r\n    ax,ay,az=Mobile.getMobilePosition(playerId)\r\n    invoke(1000,1,\"Particle.addParticleSystem\",1001,ax-2,ay+2,az)\r\n    invoke(1000,1,\"Particle.addParticleSystem\",1001,ax+2,ay-2,az)\r\n    invoke(1500,1,\"Particle.addParticleSystem\",1002,ax-2,ay,az)\r\n    invoke(1500,1,\"Particle.addParticleSystem\",1002,ax,ay-2,az)\r\n    invoke(2000,1,\"Particle.addParticleSystem\",1005,ax-2,ay-2,az)\r\nend\n\n-- [SCENE] Victoire au duel 4 - Affichage\n-- \nfunction event_1373_10414(masterOne, taikoGauche, taikoDroite)\n    function bossApp()\r\n    \tActor.changeSkin(masterOne,61,\"bossVisu\")\r\n    \tMobile.setMobileAnimation(masterOne, \"AnimResurection\",\"bossPres\")\r\n    \tActor.equip(masterOne, \"210610002\", \"VETEMENTCUSTOM\")\r\n    \tActor.equip(masterOne, \"200610003\", \"CHEVEUXCUSTOM\")\r\n    \tActor.equip(masterOne, \"13412816\", \"Chapeau\")\r\n    \tMobile.setPartColor(masterOne, \"Peau\", 0, 0, 0, 1)\r\n    end\r\n    \r\n    function taikoSoundApp()\r\n    \tActor.createActor(taikoSound, 1017, 0, -3, 1, 4)\r\n    \tMobile.setMobileAnimation(taikoSound, \"AnimIncarnam-Taiko01\", \"soundTaikoStart\", taikoSound)\r\n    end\r\n    \r\n    function soundTaikoStart(taikoSound)\r\n    \tMobile.setMobileAnimation(taikoSound, \"AnimIncarnam-Taiko01\", \"soundTaikoStart\", taikoSound)\r\n    end\r\n    \r\n    function bossPres()\r\n    \tMobile.setMobileAnimation(masterOne, \"AnimEmote-Coucou\",\"Mobile.setMobileAnimation\",masterOne,\"AnimStatique02\")\r\n    end\r\n    \t\r\n    function bossVisu()\r\n    \tMobile.setMobileVisible(masterOne,true)\r\n    end\r\n    \r\n    Mobile.setMobileVisible(masterOne,false)\r\n    Mobile.setMobileVisible(taikoGauche, true)\r\n    Mobile.setMobileVisible(taikoDroite, true)\r\n    Particle.addParticleSystem(800174, 0, -2, 1, 0)\r\n    Particle.addParticleSystem(800174, -3, -4, 1, 0)\r\n    Particle.addParticleSystem(800174, 3, -4, 1, 0)\r\n    Mobile.setMobileAnimation(playerId, \"AnimEmote-Victoire\")\r\n    taikoSoundApp()\r\n    invoke(2000,1,\"bossApp\")\r\nend\n\n-- [SCENE] Victoire au duel 3 - Affichage\n-- \nfunction event_1373_10413(masterOne)\n    Mobile.setMobileVisible(masterOne,false)\r\n    Particle.addParticleSystem(800276, 0, -2, 1, 0)\r\n    Mobile.setMobileVisible(masterOne,true)\r\n    Actor.changeSkin(masterOne,117601816,\"Mobile.setMobileAnimation\",masterOne,\"AnimStatique02\")\r\n    Mobile.setMobileAnimation(playerId, \"AnimEmote-Victoire\")\r\n    trace(\"DUEL 3 GAGNE\")\nend\n\n-- [SCENE] Victoire au duel 2 - Affichage\n-- \nfunction event_1373_10412(masterOne)\n    Mobile.setMobileVisible(masterOne,false)\r\n    Particle.addParticleSystem(800174, 0, -2, 1, 0)\r\n    Mobile.setMobileVisible(masterOne,true)\r\n    Actor.changeSkin(masterOne,1300057,\"Mobile.setMobileAnimation\",masterOne,\"AnimStatique02\")\r\n    Mobile.setMobileAnimation(playerId, \"AnimEmote-Victoire\")\r\n    trace(\"DUEL 2 GAGNE\")\nend\n\n-- [SCENE] Victoire au duel 1 - Affichage\n-- \nfunction event_1373_10411(masterOne)\n    Mobile.setMobileVisible(masterOne,false)\r\n    Particle.addParticleSystem(800174, 0, -2, 1, 0)\r\n    Mobile.setMobileVisible(masterOne,true)\r\n    Actor.changeSkin(masterOne,1300059,\"Mobile.setMobileAnimation\",masterOne,\"AnimStatique02\")\r\n    Mobile.setMobileAnimation(playerId, \"AnimEmote-Victoire\")\nend\n\n-- [FOIRE DU TROOL] Message - Perdu\n-- \nfunction event_1373_10400()\n    UI.displaySplashText(\"defi.donjon.lost\")\r\n    Mobile.setMobileAnimation(playerId , \"AnimEmote-Defaite\")\nend\n\n-- [FOIRE DU TROOL] Message - Perdu - Téléportation\n-- \nfunction event_1373_10424(ecaFoire)\n    \nend\n\n","functions":["masterLost","taikoGauchePlayInit","taikoGaucheStart","taikoDroitePlayInit","taikoDroiteStart","event_1373_10374","event_1373_10375","event_1373_10382","event_1373_10425","event_1373_10385","event_1373_10386","event_1373_10421","event_1373_10383","event_1373_10426","event_1373_10387","event_1373_10388","event_1373_10422","event_1373_10384","event_1373_10427","event_1373_10389","event_1373_10390","event_1373_10423","event_1373_10415","event_1373_10414","bossApp","taikoSoundApp","soundTaikoStart","bossPres","bossVisu","event_1373_10413","event_1373_10412","event_1373_10411","event_1373_10400","event_1373_10424"],"quest_calls":[],"dialogue_calls":[]},"scenario/1374.lua":{"source":"\nplayerId = Context.getPlayer()\n\n-- Sortie - Ok - Téléportation\n-- \nfunction event_1374_10392()\n    \nend\n\n","functions":["event_1374_10392"],"quest_calls":[],"dialogue_calls":[]},"scenario/1375.lua":{"source":"\nplayerId = Context.getPlayer()\n\n-- Sortie - Ok - Téléportation\n-- \nfunction event_1375_10394()\n    \nend\n\n","functions":["event_1375_10394"],"quest_calls":[],"dialogue_calls":[]},"scenario/1376.lua":{"source":"playerId = Context.getPlayer()\n\n-- [INITIALISATION] Initialisation\n-- \nfunction event_1376_10401()\n    \nend\n\n-- [INITIALISATION] Apparition du Dark Vlad\n-- \nfunction event_1376_10442()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_1376_10402()\n    --invoke(1500,1,\"UI.openRewardsDialog\",\"foire.trool.defi.dark.vlad\")\r\n    --invoke(1500,1,\"UI.addReward\",13582)\nend\n\n-- [INITIALISATION] Ouverture de la porte\n-- \nfunction event_1