eAnimation(dopeulTarget, \"AnimEmote-Danse-Vagues-Debut\")\r\n    elseif anim==2 then\r\n    \tMobile.setMobileAnimation(dopeulTarget, \"AnimEmote-Danse-RonddeJambe-Debut\")\r\n    elseif anim==3 then\r\n    \tMobile.setMobileAnimation(dopeulTarget, \"AnimEmote-Danse-Regard-Debut\")\r\n    end\r\n    \r\n    thescore=toLong(score)\r\n    \r\n    if (thescore >= 0) then\r\n    \tUI.displaySplashText(\"foire.dopeul.score.generic\", thescore)\r\n    end\r\n    \r\n    \r\nend\n\n-- [FOIRE DU TROOL] Le joueur fait \"Danse du Slevtar\"\n-- \nfunction event_1380_10531(masterOne)\n    \nend\n\n-- [FOIRE DU TROOL] Le joueur fait \"Danse du Slevtar\" - Gagné\n-- \nfunction event_1380_10532(dopeulTarget, duel, score)\n    Mobile.setMobileAnimation(dopeulTarget, \"AnimEmote-Danse-Vagues-Debut\")\r\n    --thescore=toLong(score)\n    --UI.displaySplashText(\"foire.dopeul.score.generic\", thescore)\nend\n\n-- [FOIRE DU TROOL] Le joueur fait \"Danse du Slevtar\" - Perdu\n-- \nfunction event_1380_10533(dopeulTarget, duel, score)\n    anim=math.random(1,3)\r\n    \r\n    if anim==1 then\r\n    \tMobile.setMobileAnimation(dopeulTarget, \"AnimEmote-Danse-Plonge-Debut\")\r\n    elseif anim==2 then\r\n    \tMobile.setMobileAnimation(dopeulTarget, \"AnimEmote-Danse-RonddeJambe-Debut\")\r\n    elseif anim==3 then\r\n    \tMobile.setMobileAnimation(dopeulTarget, \"AnimEmote-Danse-Regard-Debut\")\r\n    end\r\n    \r\n    thescore=toLong(score)\r\n    \r\n    if (thescore >= 0) then\r\n    \tUI.displaySplashText(\"foire.dopeul.score.generic\", thescore)\r\n    end\r\nend\n\n-- [FOIRE DU TROOL] Le joueur fait \"Danse du Roublard\" \n-- \nfunction event_1380_10535(masterOne)\n    \nend\n\n-- [FOIRE DU TROOL] Le joueur fait \"Danse du Roublard\" - Gagné\n-- \nfunction event_1380_10536(dopeulTarget, duel, score)\n    Mobile.setMobileAnimation(dopeulTarget, \"AnimEmote-Danse-Regard-Debut\")\r\n    --thescore=toLong(score)\n    --UI.displaySplashText(\"foire.dopeul.score.generic\", thescore)\nend