mation(dopeulWinFour, \"AnimEmote-Danse-Plonge-Debut\")\t\t\r\n    end\r\n    \r\n    function particleVictory()\r\n    \tParticle.addParticleSystem(800278, -31, -19, 3, 100)\r\n    \tParticle.addParticleSystem(800278, -32, -26, 3, 100)\r\n    \tParticle.addParticleSystem(800278, -22, -26, 3, 100)\r\n    \tParticle.addParticleSystem(800278, -23, -19, 3, 100)\r\n    end\r\n    \r\n    Mobile.setMobileAnimation(playerId, \"AnimEmote-Danse-Plonge-Debut\")\r\n    invoke(4700,1,\"particleVictory\")\r\n    invoke(3000,1,\"victory\",dopeulOne)\r\n    invoke(5200,1,\"danseVictory\",dopeulOne)\r\nend\n\n-- [FOIRE DU TROOL] On tire la récompense 2\n-- \nfunction event_1380_10534(dopeulOne, duel)\n    function victory(mobileId)\r\n    \tMobile.setMobileAnimation(mobileId, \"AnimEmote-Applaudir\")\r\n    \tMobile.setMobileDirection(playerId, 3)\r\n    \tMobile.setMobileAnimation(playerId, \"AnimEmote-Victoire\")\r\n    end\r\n    \r\n    function danseVictory(mobileId)\r\n    \tdopeulWinOne=Mobile.generateClientMobileId()\r\n    \tdopeulWinTwo=Mobile.generateClientMobileId()\r\n    \tdopeulWinThree=Mobile.generateClientMobileId()\r\n    \tdopeulWinFour=Mobile.generateClientMobileId()\r\n    \tParticle.addParticleSystem(800174, -31, -19, 3, 0)\r\n    \tParticle.addParticleSystem(800174, -32, -26, 3, 0)\r\n    \tParticle.addParticleSystem(800174, -22, -26, 3, 0)\r\n    \tParticle.addParticleSystem(800174, -23, -19, 3, 0)\r\n    \tActor.createActor(dopeulWinOne, 10, -31, -19, 3, 4)\r\n    \tActor.createActor(dopeulWinTwo, 10, -32, -26, 3, 4)\r\n    \tActor.createActor(dopeulWinThree, 10, -22, -26, 3, 4)\r\n    \tActor.createActor(dopeulWinFour, 10, -23, -19, 3, 4)\r\n    \tMobile.setMobileDirection(dopeulWinOne, 1)\r\n    \tMobile.setMobileDirection(dopeulWinTwo, 1)\r\n    \tMobile.setMobileDirection(dopeulWinThree, 5)\r\n    \tMobile.setMobileDirection(dopeulWinFour, 5)\r\n    \tActor.copyActorFrom(playerId, dopeulWinOne)\t\r\n    \tActor.copyActorFrom(playerId, dopeulWinTwo)\r\n