MobileAnimation(playerId, \"AnimEmote-Victoire\")\r\n    end\r\n    \r\n    function danseVictory(mobileId)\r\n    \tdopeulWinOne=Mobile.generateClientMobileId()\r\n    \tdopeulWinTwo=Mobile.generateClientMobileId()\r\n    \tdopeulWinThree=Mobile.generateClientMobileId()\r\n    \tdopeulWinFour=Mobile.generateClientMobileId()\r\n    \tParticle.addParticleSystem(800174, -31, -19, 3, 0)\r\n    \tParticle.addParticleSystem(800174, -32, -26, 3, 0)\r\n    \tParticle.addParticleSystem(800174, -22, -26, 3, 0)\r\n    \tParticle.addParticleSystem(800174, -23, -19, 3, 0)\r\n    \tActor.createActor(dopeulWinOne, 10, -31, -19, 3, 4)\r\n    \tActor.createActor(dopeulWinTwo, 10, -32, -26, 3, 4)\r\n    \tActor.createActor(dopeulWinThree, 10, -22, -26, 3, 4)\r\n    \tActor.createActor(dopeulWinFour, 10, -23, -19, 3, 4)\r\n    \tMobile.setMobileDirection(dopeulWinOne, 1)\r\n    \tMobile.setMobileDirection(dopeulWinTwo, 1)\r\n    \tMobile.setMobileDirection(dopeulWinThree, 5)\r\n    \tMobile.setMobileDirection(dopeulWinFour, 5)\r\n    \tActor.copyActorFrom(playerId, dopeulWinOne)\t\r\n    \tActor.copyActorFrom(playerId, dopeulWinTwo)\r\n    \tActor.copyActorFrom(playerId, dopeulWinThree)\t\r\n    \tActor.copyActorFrom(playerId, dopeulWinFour)\r\n    \tMobile.setMobileAnimation(playerId, \"AnimEmote-Danse-RonddeJambe-Debut\")\t\r\n    \tMobile.setMobileAnimation(dopeulOne, \"AnimEmote-Danse-RonddeJambe-Debut\")\t\r\n    \tMobile.setMobileAnimation(dopeulWinOne, \"AnimEmote-Danse-RonddeJambe-Debut\")\t\r\n    \tMobile.setMobileAnimation(dopeulWinTwo, \"AnimEmote-Danse-RonddeJambe-Debut\")\t\r\n    \tMobile.setMobileAnimation(dopeulWinThree, \"AnimEmote-Danse-RonddeJambe-Debut\")\t\r\n    \tMobile.setMobileAnimation(dopeulWinFour, \"AnimEmote-Danse-RonddeJambe-Debut\")\t\t\r\n    end\r\n    \r\n    function particleVictory()\r\n    \tParticle.addParticleSystem(800278, -31, -19, 3, 100)\r\n    \tParticle.addParticleSystem(800278, -32, -26, 3, 100)\r\n    \tParticle.addParticleSystem(800278, -22, -26, 3, 100)\r\n    \tParticle.addParticleSystem(800278, -23, -19, 3, 100)\r\n    end\r\n    \r\n    Mobile.setMobileAnimation(playerId, \"AnimEmote-Danse-RonddeJambe-Debut\")\r\n    invoke(3000,1,\"victory\",dopeulOne)\r\n    invoke(4700,1,\"particleVictory\")\r\n    invoke(5200,1,\"danseVictory\",dopeulOne)\r\n    \r\nend\n\n-- [FOIRE DU TROOL] Récompense\n-- \nfunction event_1380_10502(dopeulOne)\n    \nend\n\n-- [FOIRE DU TROOL] Message - Perdu\n-- \nfunction event_1380_10472()\n    UI.displaySplashText(\"defi.donjon.lost\")\r\n    Mobile.setMobileAnimation(playerId , \"AnimEmote-Defaite\")\nend\n\n-- [FOIRE DU TROOL] Message - Perdu - Téléportation\n-- \nfunction event_1380_10473(ecaFoire)\n    \nend\n\n","functions":["dopeulOnePlayInit","event_1380_10451","event_1380_10452","event_1380_10508","event_1380_10510","event_1380_10511","event_1380_10531","event_1380_10532","event_1380_10533","event_1380_10535","event_1380_10536","event_1380_10537","event_1380_10539","event_1380_10540","event_1380_10541","event_1380_10544","event_1380_10803","event_1380_10528","victory","danseVictory","particleVictory","event_1380_10534","victory","danseVictory","particleVictory","event_1380_10538","victory","danseVictory","particleVictory","event_1380_10542","victory","danseVictory","particleVictory","event_1380_10502","event_1380_10472","event_1380_10473"],"quest_calls":[],"dialogue_calls":[]},"scenario/1382.lua":{"source":"playerId = Context.getPlayer()\r\n\r\ngoule = Mobile.generateClientMobileId()\n\n-- [INITIALISATION] Variables\n-- \nfunction event_1382_10546()\n    \nend\n\n-- [SCENE] Un joueur joue Requinou\n-- \nfunction event_1382_10547()\n    trace(\"EMOTE UNE\")\nend\n\n-- [SCENE] Un joueur joue Slevtar\n-- \nfunction event_1382_10677()\n    trace(\"EMOTE UNE\")\nend\n\n-- [SCENE] Un joueur joue Roublard\n-- \nfunction event_1382_10678()\n    trace(\"EMOTE UNE\")\nend\n\n-- [SCENE] Un joueur joue Travlota\n-- \nfunction event_1382_10679()\n    trace(\"EMOTE UNE\")\nend\n\n-- [SCENE] Tous les joueurs sont sur les dalles\n-- \nfunction event_1382_10566()\n    \nend\n\n-- [SCENE] Début de la danse\n-- \nfunction event_1382_10680()\n    function gouleApp()\r\n    \tActor.createActor(goule, 140501827, -63, -252, 5, 4)\r\n    \tMobile.setMobileDirection(goule, 3)\r\n    \tMobile.setMobileAnimation(goule,\"AnimEmote-Danse-RonddeJambe\")\r\n    end\r\n    \r\n    Particle.addParticleSystem(800174, -63, -252, 5, 1)\r\n    invoke(800,1,\"gouleApp\")\nend\n\n-- [SCENE] Fin de la danse\n-- \nfunction event_1382_10567()\n    Particle.addParticleSystem(800174, -63, -252, 5, 1)\r\n    invoke(400,1,\"Actor.deleteActor\",goule)\nend\n\n","functions":["event_1382_10546","event_1382_10547","event_1382_10677","event_1382_10678","event_1382_10679","event_1382_10566","event_1382_10680","gouleApp","event_1382_10567"],"quest_calls":[],"dialogue_calls":[]},"scenario/1383.lua":{"source":"playerId = Context.getPlayer()\r\npetId = Context.getPlayerPetId()\r\nshakeEffectId = 0\r\n\r\nmagicien=Mobile.generateClientMobileId()\r\nassistante=Mobile.generateClientMobileId()\r\npublicOne=Mobile.generateClientMobileId()\r\npublicTwo=Mobile.generateClientMobileId()\r\npublicThree=Mobile.generateClientMobileId()\r\npuppetOne=Mobile.generateClientMobileId()\r\npuppetTwo=Mobile.generateClientMobileId()\r\ndresseur=Mobile.generateClientMobileId()\r\nsteak=Mobile.generateClientMobileId()\r\nmili=Mobile.generateClientMobileId()\r\nmiliTwo=Mobile.generateClientMobileId()\r\nmulou=Mobile.generateClientMobileId()\r\ngobgob=Mobile.generateClientMobileId()\r\n\r\n\r\n\r\nfunction scenarioModeOn(mobileId)\r\n\tsetPlayerVisible(mobileId,false)\r\n\tif mobileId==playerId then\r\n\t\tCamera.setUserZoomLocked(true)\r\n\t\tUI.setShortcutEnabled(false)\t\t\t\t\t\t\r\n    \tUI.setUIVisible(false)\r\n    end\r\nend\r\n\r\nfunction scenarioModeOff(mobileId)\r\n\tsetPlayerVisible(mobileId,true)\r\n\tCamera.setUserZoomLocked(false)\r\n\tif mobileId==playerId then\r\n\t\tUI.setShortcutEnabled(true)\t\t\t\t\t\t\n    \tUI.setUIVisible(true)\n\t\tUI.manageFrame(\"World\",true)\r\n\tend\nend\r\n\r\nfunction setPlayerVisible(mobileId,visible)\r\n\tMobile.setMobileVisible(mobileId, visible)\r\n\tMobile.setMobileVisible(petId, visible)\r\nend\r\n\r\nfunction cameraShake()\r\n\tshakeEffectId = Effect.createCameraShakeEffect(250, 500, 250, 3)\r\n\tinvoke(1000, 1, \"Effect.stopEffect\", shakeEffectId)\r\nend\r\n\r\nfunction setCanonAnimation(mobileId)\r\n\tscenarioModeOn(mobileId)\r\n\tinvoke(1200, 1, \"cameraShake\")\r\n\tInteractiveElement.setAnimation(15224, \"AnimTrans_2\")\r\nend\r\n\r\n--SPECTACLE DE MAGIE\r\n\r\nfunction initMagicien()\r\n\tActor.createActor(magicien, 100, -69, -191, -1, 4)\r\n\tMobile.setMobileDirection(magicien, 3)\r\n\tActor.equip(magicien, \"201000001\", \"CHEVEUXCUSTOM\")\r\n\tActor.equip(magicien, \"211000003\", \"VETEMENTCUSTOM\")\r\n\tMobile.setPartColor(magicien, \"Peau\", 0.85, 0.69, 0.43, 1)\r\n\tMobile.setPartColor(magicien, \"Cheveux\", 0.88, 0.40, 0.12, 1)\r\nend\r\n\r\nfunction initAssistante()\r\n\tActor.createActor(assistante, 81, -67, -191, -1, 4)\r\n\tMobile.setMobileDirection(assistante, 3)\r\n\tActor.equip(assistante, \"200810002\", \"CHEVEUXCUSTOM\")\r\n\tActor.equip(assistante, \"210810003\", \"VETEMENTCUSTOM\")\r\n\tMobile.setPartColor(assistante, \"Peau\", 0.85, 0.69, 0.43, 1)\r\n\tMobile.setPartColor(assistante, \"Cheveux\", 0.88, 0.40, 0.12, 1)\r\nend\r\n\r\nfunction initAssistanteApp()\t\r\n\tActor.createActor(assistante, 81, -68, -193, -1, 4)\r\n\tMobile.setMobileDirection(assistante, 3)\r\n\tActor.equip(assistante, \"200810002\", \"CHEVEUXCUSTOM\")\r\n\tActor.equip(assistante, \"210810003\", \"VETEMENTCUSTOM\")\r\n\tMobile.setPartColor(assistante, \"Peau\", 0.85, 0.69, 0.43, 1)\r\n\tMobile.setPartColor(assistante, \"Cheveux\", 0.88, 0.40, 0.12, 1)\r\n\tMobile.setMobileAnimation(assistante, \"AnimEmote-Vomis\")\r\nend\r\n\r\nfunction initBloqueuse()\r\n\tMobile.setMobileAnimation(magicien, \"AnimEmote-Applaudir\")\r\n\tinvoke(1000,1,\"Mobile.setMobilePosition\",assistante, -68, -193, -1)\r\n\tinvoke(1000,1,\"Mobile.setMobileVisible\",assistante, true)\r\n\tinvoke(1000,1,\"Mobile.setMobileAnimation\",assistante, \"AnimApparition\")\r\nend\r\n\r\nfunction initPublicOne()\r\n\tActor.createActor(publicOne, 60, -73, -193, -1, 4)\r\n\tActor.equip(publicOne, \"200600001\", \"CHEVEUXCUSTOM\")\r\n\tActor.equip(publicOne, \"210600003\", \"VETEMENTCUSTOM\")\r\n\tMobile.setPartColor(publicOne, \"Peau\", 0.85, 0.69, 0.43, 1)\r\n\tMobile.setPartColor(publicOne, \"Cheveux\", 0.88, 0.40, 0.12, 1)\r\n\t--Mobile.setMobileDirection(publicOne, 1)\r\n\tMobile.setMobileDirection(publicOne, 5)\r\n\tMobile.setMobileAnimationStaticKey(publicOne, \"AnimStatique-Banc-Assis\")\n\tMobile.setMobileAnimation(publicOne, \"AnimStatique-Banc-Assis\")\nend\r\n\r\nfunction initPuppet()\r\n\tActor.createActor(puppetOne, 100500193, -70, -197, -1, 4)\r\n\tMobile.setMobileDirection(puppetOne, 3)\r\n\tActor.createActor(puppetTwo, 100500193, -68, -197, -1, 4)\r\n\tMobile.setMobileDirection(puppetTwo, 3)\r\nend\r\n\r\n\r\n--CIRQUE\r\n\r\nfunction initDresseur()\r\n\tActor.createActor(dresseur, 20, 13, -251, -1, 4)\r\n\tMobile.setMobileDirection(dresseur, 3)\r\n\tActor.equip(dresseur, \"200200001\", \"CHEVEUXCUSTOM\")\r\n\tActor.equip(dresseur, \"210200003\", \"VETEMENTCUSTOM\")\r\n\tMobile.setPartColor(dresseur, \"Peau\", 0.85, 0.69, 0.43, 1)\r\n\tMobile.setPartColor(dresseur, \"Cheveux\", 0.88, 0.40, 0.12, 1)\r\nend\r\n\r\nfunction initSteak()\r\n\tActor.createActor(steak, 20, 13, -245, -1, 4)\r\n\tMobile.setMobileDirection(steak, 3)\r\nend\r\n\r\nfunction initMili()\r\n\tActor.createActor(mili, 105501435, 13, -251, -1, 4)\r\n\tMobile.setMobileDirection(mili, 1)\r\nend\r\n\r\nfunction initMiliTwo()\r\n\tActor.createActor(miliTwo, 105501435, 13, -251, -1, 4)\r\n\tMobile.setMobileDirection(miliTwo, 1)\r\nend\r\n\r\nfunction initMulou()\r\n\tActor.createActor(mulou, 105501433, 13, -251, -1, 4)\r\n\tMobile.setMobileDirection(mulou, 1)\r\nend\r\n\r\nfunction gobgob()\r\n\tActor.createActor(gobgob, 20, 13, -245, -1, 4)\r\n\tMobile.setMobileDirection(gobgob,3)\r\n\tMobile.setMobileAnimation(gobgob,\"AnimTarget-Gobage\")\r\n\tinvoke(1100,1,\"Particle.addParticleSystem\",800174, 13,-245,-1,0)\r\n\tinvoke(1100,1,\"Actor.deleteActor\",gobgob)\r\nend\n\n-- [INITIALISATION] Variables\n-- \nfunction event_1383_10570()\n    \nend\n\n-- [ZOO] Mandhal\n-- \nfunction event_1383_10589(mandhal)\n    local playerId = Context.getLeaderId()\r\n    \r\n    function mandhalOne(mobileId)\r\n        Mobile.setMobileAnimation(mobileId, \"AnimComp04\")\r\n    end\r\n    \r\n    function mandhalTwo(mobileId)\r\n        Mobile.setMobileAnimation(mobileId, \"AnimComp-Poing\")\r\n        invoke(700, 1, \"Effect.createCameraShakeEffect\", 100, 800, 1000, 6)\r\n    end\r\n    \r\n    function mandhalThree(mobileId)\r\n        Mobile.setMobileAnimation(mobileId, \"AnimSort-Cri\")\r\n    end\r\n    \r\n    function mandhalFour(mobileId)\r\n        Mobile.setMobileAnimation(mobileId, \"AnimSort-Transistaure\")\r\n    \r\n        invoke(900, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Effrayee\")\r\n    \r\n        invoke(1500, 1, \"Mobile.setMobileAnimation\", mobileId, \"AnimComp03\")\r\n    end\r\n    \r\n    function getAnimToPlay(randomNb)\r\n        if randomNb == 1 then\r\n            return \"mandhalOne\"\r\n        elseif randomNb == 2 then\r\n            return \"mandhalTwo\"\r\n        elseif randomNb == 3 then\r\n            return \"mandhalThree\"\r\n        else\r\n            return \"mandhalFour\"\r\n        end\r\n    end\r\n    \r\n    invoke(1000, 1, getAnimToPlay(math.random(1, 4)), mandhal)\nend\n\n-- [ZOO] Mandhal - Cooldown\n-- \nfunction event_1383_10590()\n    \nend\n\n-- [ZOO] Moogrr\n-- \nfunction event_1383_10591(moogrr)\n    function moogrrOne(mobileId)\r\n    \tMobile.setMobileAnimation(mobileId, \"AnimComp-Parler\")\r\n    \tinvoke(500,1,\"UI.displaySmiley\",17