lse)\r\n\tif mobileId==playerId then\r\n\t\tUI.setShortcutEnabled(true)\t\t\t\t\t\t\n    \tUI.setUIVisible(true)\n\t\tUI.manageFrame(\"World\",true)\r\n\tend\nend\r\n\r\nfunction setPlayerVisible(mobileId,visible)\r\n\tMobile.setMobileVisible(mobileId, visible)\r\n\tMobile.setMobileVisible(petId, visible)\r\nend\r\n\r\nfunction cameraShake()\r\n\tshakeEffectId = Effect.createCameraShakeEffect(250, 500, 250, 3)\r\n\tinvoke(1000, 1, \"Effect.stopEffect\", shakeEffectId)\r\nend\r\n\r\nfunction setCanonAnimation(mobileId)\r\n\tscenarioModeOn(mobileId)\r\n\tinvoke(1200, 1, \"cameraShake\")\r\n\tInteractiveElement.setAnimation(15224, \"AnimTrans_2\")\r\nend\r\n\r\n--CIRQUE\r\n\r\nfunction initDresseur()\r\n\tActor.createActor(dresseur, 20, 13, -251, -1, 4)\r\n\tMobile.setMobileDirection(dresseur, 3)\r\n\tActor.equip(dresseur, \"200200001\", \"CHEVEUXCUSTOM\")\r\n\tActor.equip(dresseur, \"210200003\", \"VETEMENTCUSTOM\")\r\n\tMobile.setPartColor(dresseur, \"Peau\", 0.85, 0.69, 0.43, 1)\r\n\tMobile.setPartColor(dresseur, \"Cheveux\", 0.88, 0.40, 0.12, 1)\r\nend\r\n\r\nfunction initSteak()\r\n\tActor.createActor(steak, 20, 13, -245, -1, 4)\r\n\tMobile.setMobileDirection(steak, 3)\r\nend\r\n\r\nfunction initMili()\r\n\tActor.createActor(mili, 105501435, 13, -251, -1, 4)\r\n\tMobile.setMobileDirection(mili, 1)\r\nend\r\n\r\nfunction initMiliTwo()\r\n\tActor.createActor(miliTwo, 105501435, 13, -251, -1, 4)\r\n\tMobile.setMobileDirection(miliTwo, 1)\r\nend\r\n\r\nfunction initMulou()\r\n\tActor.createActor(mulou, 105501433, 13, -251, -1, 4)\r\n\tMobile.setMobileDirection(mulou, 1)\r\nend\r\n\r\nfunction startGobgob()\r\n\tActor.createActor(gobgob, 20, 13, -245, -1, 4)\r\n\tMobile.setMobileDirection(gobgob,3)\r\n\tMobile.setMobileAnimation(gobgob,\"AnimTarget-Gobage\")\r\n\tinvoke(300,1,\"Actor.deleteActor\",mulou)\r\n\tinvoke(1100,1,\"endGobgob\")\r\nend\r\n\r\nfunction endGobgob()\r\n\tParticle.addParticleSystem(800174, 13,-245,-1,0)\r\n\tActor.deleteActor(gobgob)\r\nend\n\n-- 