, \"AnimSort-Fouet\")\n    \tend\n    end\n    \n    function patrolFive(mobileId)\n    \tMobile.moveMobile(mobileId, 16, -246, -1)\n    \tMobile.onPathEnded(mobileId, \"patrolFinal\",mobileId)\n    \tif mobileId==mili then\n    \t\tMobile.setMobileDirection(dresseur, 1)\n    \t\tMobile.setMobileAnimation(dresseur, \"AnimSort-Fouet\")\n    \tend\n    end\n    \n    function patrolFinal(mobileId)\n    \tif mobileId==mili then\n    \t\tMobile.moveMobile(mobileId, 11, -246, -1)\n    \telseif mobileId==mulou then\n    \t\tMobile.moveMobile(mobileId, 13, -246, -1)\n    \telseif mobileId==miliTwo then\n    \t\tMobile.moveMobile(mobileId, 15, -246, -1)\t\n    \tend\n    \tMobile.onPathEnded(mobileId, \"Mobile.setMobileDirection\",mobileId,3)\n    \tif mobileId==mili then\n    \t\tMobile.setMobileDirection(dresseur, 7)\n    \t\tMobile.setMobileAnimation(dresseur, \"AnimSort-Fouet\")\n    \tend\n    end\n    \n    --PREMIER NUMERO\n    \n    function moveSommeil()\n    \tMobile.moveMobile(dresseur, 11, -245, -1)\n    \tMobile.onPathEnded(dresseur, \"startSommeil\")\n    end\n    \n    function startSommeil()\n    \tMobile.setMobileDirection(dresseur, 7)\n    \tMobile.setMobileAnimation(dresseur, \"AnimEmote-Applaudir\")\n    \tinvoke(2000,1,\"Mobile.setMobileAnimation\",dresseur, \"AnimEmote-Bailler\")\n    \tinvoke(3200,1,\"miliSommeil\")\n    \tinvoke(5000,1,\"presentTwo\")\n    end\n    \n    function miliSommeil()\n    \tMobile.setMobileAnimation(mili, \"AnimComp-Dormir-Debut\",\"Mobile.setMobileAnimation\",mili,\"AnimComp-Dormir-Boucle\")\n    end\n    \n    function present()\n    \tMobile.setMobileDirection(dresseur, 3)\n    \tMobile.setMobileAnimation(dresseur, \"AnimEmote-Presenter\")\n    \tSound.playLocalSound(35, 70500010, 90, 13,-244,-1)\n    end\n    \n    function presentTwo()\n    \tMobile.setMobileDirection(dresseur, 3)\n    \tMobile.setMobileAnimation(dresseur, \"AnimEmote-Presenter\")\n    end\n    \n    --DEUXIEME NUMERO\n    \n    function moveGrogne()\n