lou,\"AnimSort-Morsure\")\n    \tinvoke(4700,1,\"Actor.deleteActor\",steak)\n    \tinvoke(5500,1,\"startRepas\")\t\n    end\n    \n    function startRepas()\n    \tActor.changeSkin(mulou,105511433,\"transGarou\")\n    end\n    \n    function transGarou()\n    \tMobile.setMobileAnimation(mulou, \"AnimTransEffect-Debut\")\n    \tinvoke(2000,1,\"Mobile.setMobileAnimation\",dresseur, \"AnimEmote-Help\")\n    \tinvoke(3000,1,\"fuiteThree\",mili)\n    \tinvoke(3000,1,\"fuiteThree\",miliTwo)\n    \tinvoke(3000,1,\"Mobile.setMobileAnimation\",dresseur, \"AnimSort-Fouet\")\n    \tinvoke(3500,1,\"Mobile.setMobileAnimation\",mulou, \"AnimSort-Hurle\")\n    \tinvoke(5000,1,\"Mobile.setMobileAnimation\",dresseur, \"AnimEmote-Supplie-Debut\")\n    \tinvoke(5000,1,\"Mobile.moveMobile\",mulou,13,-245,-1)\t\n    \tinvoke(6500,1,\"startGobgob\")\n    end\n    \n    function endCirque()\n    \tSound.playLocalSound(35, 70500015, 90, 13,-244,-1)\n    \tMobile.setMobileDirection(dresseur, 3)\n    \tMobile.setMobileAnimation(dresseur, \"AnimEmote-BrandirArme3\")\n    \tinvoke(7000,1,\"fuiteThree\",dresseur)\n    end\n    \n    function fuiteThree(mobileId)\n    \tMobile.moveMobile(mobileId, 13, -252, -1)\n    \tMobile.onPathEnded(mobileId, \"Mobile.setMobileVisible\",mobileId,false)\n    end\n    \n    \n    --Camera.setWorldTarget(13, -244, -1)\n    --Sound.playLocalSound(35, 70500015, 90, 13,-244,-1)\n    --invoke(6000,1,\"Sound.playLocalSound\",35, 70500012, 90, 13,-244,-1)\n    invoke(8000,1,\"startCirque\")\n    invoke(20000,1,\"patrol\",mili)\n    invoke(22000,1,\"patrol\",mulou)\n    invoke(24000,1,\"patrol\",miliTwo)\n    invoke(35000,1,\"present\")\n    invoke(37000,1,\"moveSommeil\")\n    invoke(47000,1,\"moveGrogne\")\n    invoke(56000,1,\"boucleGrogne\")\n    invoke(64000,1,\"moveGarou\")\n    invoke(67000,1,\"boucleGarou\")\n    invoke(82000,1,\"endCirque\")\n    --invoke(79000,1,\"Camera.attachCameraToMobile\",playerId)\nend\n\n-- [CIRQUE] Réinitialisation du Zone trigger\n-