pha(-27, 0, 0, 1, 1)\r\n    \tWorld.setPictoAlpha(-41, 8, 0, 0, 1)\r\n    elseif passerelle==2 then\r\n    \tWorld.setPictoAlpha(-27, 0, 0, 1, 1)\r\n    \tWorld.setPictoAlpha(-41, 8, 0, 1, 1)\r\n    end\nend\n\n-- [COMBAT] Victoire Salle 1\n-- \nfunction event_1404_10824()\n    \nend\n\n-- [COMBAT] Victoire Salle 1 - On déverouille la porte\n-- \nfunction event_1404_10825()\n    World.setPictoAlpha(-27, 0, 0, 1, 1000)\nend\n\n-- [COMBAT] Victoire Salle 2\n-- \nfunction event_1404_10826()\n    \nend\n\n-- [COMBAT] Victoire Salle 2 - On déverouille la porte\n-- \nfunction event_1404_10827()\n    World.setPictoAlpha(-41, 8, 0, 1, 1000)\r\nend\n\n-- [COMBAT] Victoire Salle 3 - BOSS\n-- \nfunction event_1404_10834()\n    \nend\n\n-- [COMBAT] Victoire Salle 3 - On active le TP et le coffre\n-- \nfunction event_1404_10835()\n    \nend\n\n","functions":["event_1404_10822","event_1404_10823","event_1404_10824","event_1404_10825","event_1404_10826","event_1404_10827","event_1404_10834","event_1404_10835"],"quest_calls":[],"dialogue_calls":[]},"scenario/1407.lua":{"source":"--=== VARIABLES ===--\r\nplayerId = Context.getPlayer()\r\npetId = Context.getPlayerPetId()\r\nplayerX = 0\r\nplayerY = 0\r\nplayerZ = 0\r\n\r\nfunction cameraClear()\r\n\tCamera.attachCameraToMobile(playerId)\r\nend\r\n\r\napsId = -1090061181\r\n\r\nfunction displayDoor()\r\n\tapsOneId = Particle.addParticleSystem(apsId, 0, -5, 20)\r\nend\r\n\r\nfunction hideDoor()\r\n\tParticle.removeParticleSystem(apsOneId)\r\nend\n\n-- [INIT] Variables\n-- \nfunction event_1407_10875()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_1407_10873(firstFightFInished, miniBoufrog)\n    displayDoor()\r\n    \r\n    if (firstFightFinished == 1) then\r\n    Mobile.setMobileVisible(miniBoufrog, false)\r\n    else\r\n    end\nend\n\n-- (COMBAT) Victoire salle 01\n-- \nfunction event_1407_10874(miniBoufrog)\n    trace(\"COMBAT 01 TERMINE\")\r\n    \r\n    function miniBoufrogOut()\r\n    \tMobile.moveMobile(miniBoufrog, -1, -31, 20, \"miniBoufrogDive\")\r\n    end\r\n    \r\n    function miniBoufrogDive()\r\n    \tMobile.setMobileAnimation( miniBoufrog,\"AnimComp-Lave\")\r\n    \tinvoke(500, 1,\"Particle.addParticleSystem\",800310, -1, -32, 18)\r\n    \tinvoke(500, 1,\"Mobile.setMobileVisible\", miniBoufrog, false)\r\n    end\r\n    \r\n    function boufrogIn()\r\n    \tParticle.addParticleSystem(800311, -1, -32, 18)\r\n    \r\n    \tboufrogId = Mobile.generateClientMobileId()\r\n    \tActor.createActor(boufrogId , \"100200042\", -1, -25, 20)\r\n    \tMobile.setMobileDirection(boufrogId,  3)\r\n    \tMobile.setMobileRadius(boufrogId, 1)\r\n    \tMobile.setMobileAnimation(boufrogId, \"AnimApparition\")\r\n    \r\n    \tEffect.createCameraShakeEffect(1000,1500,500,5,50,\"Both\")\r\n    \t\r\n    \tinvoke(2050, 1, \"Actor.deleteActor\",boufrogId)\r\n    end\r\n    \r\n    invoke(4000, 1, \"miniBoufrogOut\")\r\n    invoke(7000, 1, \"boufrogIn\")\nend\n\n-- Apparition du Boufrog\n-- \nfunction event_1407_10877()\n    \nend\n\n-- FIGHT_STARTED - Application des états\n-- \nfunction event_1407_21950()\n    \nend\n\n-- GENERIC_ACTIVABLE_ACTION - Ouverture de la porte\n-- \nfunction event_1407_22008()\n    hideDoor()\nend\n\n-- [COMBAT][Achievement] Magmog possède \"Cataclysme\" au niveau 3 mini\n-- \nfunction event_1407_22020()\n    \nend\n\n-- [COMBAT][Achievement] Magmog possède \"Cataclysme\" au niveau 3 mini + Victoire des joueurs\n-- \nfunction event_1407_22021()\n    \nend\n\n-- [COMBAT][Achievement] Un boufrog a été tué par un joueur\n-- \nfunction event_1407_22026()\n    \nend\n\n-- [COMBAT][Achievement] Aucun boufrog a été tué par des joueurs + Victoire des joueurs\n-- \nfunction event_1407_22027()\n    \nend\n\n","functions":["cameraClear","displayDoor","hideDoor","event_1407_10875","event_1407_10873","event_1407_10874","miniBoufrogOut","miniBoufrogDive","boufrogIn","event_1407_10877","event_1407_21950","event_1407_22008","event_1407_22020","event_1407_22021","event_1407_22026","event_1407_22027"],"quest_calls":[],"dialogue_calls":[]},"scenario/1421.lua":{"source":"\n\n-- [INIT] Variables\n-- \nfunction event_1421_12245()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_1421_11964(doorOpened, bossId)\n    local door = toLong(doorOpened)\r\n    local meulou = toLong(bossId)\r\n    \r\n    if (door == 0) then\r\n    Mobile.setMobileAnimation(bossId, \"AnimComp-Dormir-Boucle\")\r\n    else\r\n    end\nend\n\n-- MONSTER_ACTION_EVENT - Lancement du combat\n-- \nfunction event_1421_22003(bossId)\n    Mobile.setMobileAnimation(bossId, \"AnimComp-Dormir-Fin\")\nend\n\n-- MONSTER_ACTION_EVENT - Examiner Milkar\n-- \nfunction event_1421_22004()\n     local playerId = Context.getLeaderId()\r\n    BubbleText.closeBubbleAttachedTo(playerId)\r\n    BubbleText.showText(playerId, \"milkar.dialog.examination\", 0, 60)\r\n    UI.writeLocalisedInChat(\"milkar.dialog.examination\")\nend\n\n-- [COMBAT] Milkar lance \"Vengeance\"\n-- \nfunction event_1421_12244()\n    \nend\n\n-- [COMBAT] Milkar meurt en étant pas Garou\n-- \nfunction event_1421_12247()\n    \nend\n\n-- [COMBAT] Milkar lance \"Vengeance\" + Victoire des joueurs\n-- \nfunction event_1421_12246()\n    \nend\n\n-- [COMBAT] Milkar meurt en étant pas Garou + Victoire des joueurs\n-- \nfunction event_1421_12248()\n    \nend\n\n-- FIGHT_STARTED - Actions de début de combat\n-- \nfunction event_1421_21949()\n    \nend\n\n-- [COMBAT][Achievement] Milkar possède \"Instinct du chasseur\" au niveau 3 mini\n-- \nfunction event_1421_22018()\n    \nend\n\n-- [COMBAT][Achievement] Milkar possède \"Instinct du chasseur\" au niveau 3 mini + Victoire des joueurs\n-- \nfunction event_1421_22019()\n    \nend\n\n","functions":["event_1421_12245","event_1421_11964","event_1421_22003","event_1421_22004","event_1421_12244","event_1421_12247","event_1421_12246","event_1421_12248","event_1421_21949","event_1421_22018","event_1421_22019"],"quest_calls":[],"dialogue_calls":[]},"scenario/1423.lua":{"source":"playerId=Context.getPlayer()\n\n-- Application de l'état\n-- \nfunction event_1423_10936()\n    \nend\n\n-- Désapplication de l'état\n-- \nfunction event_1423_16386()\n    \nend\n\n","functions":["event_1423_10936","event_1423_16386"],"quest_calls":[],"dialogue_calls":[]},"scenario/1432.lua":{"source":"apsId = 800406\r\n\r\nfunction displayDoor()\r\n\tapsOneId = Particle.addParticleSystem(apsId, -4, -6, 0)\r\n\tapsTwoId = Particle.addParticleSystem(apsId, -4, -5, 0)\r\n\tapsThreeId = Particle.addParticleSystem(apsId, -4, -4, 0)\r\n\tapsFourId = Particle.addParticleSystem(apsId, -4, -3, 0)\r\n\tapsFiveId = Particle.addParticleSystem(apsId, -5, -3, 0)\r\n\tapsSixId = Particle.addParticleSystem(apsId, -6, -3, 0)\r\nend\r\n\r\nfunction hideDoor()\r\n\tParticle.removeParticleSystem(apsOneId)\r\n\tParticle.removeParticleSystem(apsTwoId)\r\n\tParticle.removeParticleSystem(apsThreeId)\r\n\tParticle.removeParticleSystem(apsFourId)\r\n\tParticle.removeParticleSystem(apsFiveId)\r\n\tParticle.removeParticleSystem(apsSixId)\r\nend\n\n-- [INIT] Variables\n-- \nfunction event_1432_22006()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_1432_11986()\n    displayDoor()\nend\n\n-- FIGHT_STARTED - Actions de début de combat\n-- \nfunction event_1432_21938()\n    \nend\n\n-- GENERIC_ACTIVABLE_ACTION - Ouverture de la porte\n-- \nfunction event_1432_22007()\n    local playerId = Context.getLeaderId()\r\n    hideDoor()\r\n    \r\n    Mobile.setMobileAnimation(playerId, \"AnimEmote-Boire\")\nend\n\n","functions":["displayDoor","hideDoor","event_1432_22006","event_1432_11986","event_1432_21938","event_1432_22007"],"quest_calls":[],"dialogue_calls":[]},"scenario/1434.lua":{"source":"\n\n-- [INITIALISATION] Variables\n-- \nfunction event_1434_10973()\n    \nend\n\n-- [SCENE] Le joueur paie la coupelle 1\n-- \nfunction event_1434_10976()\n    \nend\n\n-- [SCENE] Le joueur paie la coupelle 2\n-- \nfunction event_1434_10977()\n    \nend\n\n-- [SCENE] Le joueur paie la coupelle 3\n-- \nfunction event_1434_10978()\n    \nend\n\n-- [SCENE] La coupette 1 est remplie\n-- \nfunction event_1434_10979(popoOneId)\n    Mobile.setMobileDirection(popoOneId, 1)\r\n    Mobile.setMobileAnimation(popoOneId, \"AnimEmote-Piece-Debut\")\r\n    Mobile.setMobileAnimationStaticKey(popoOneId, \"AnimEmote-Piece-Debut\")\nend\n\n-- [SCENE] La coupette 2 est remplie\n-- \nfunction event_1434_10980(popoTwoId)\n    Mobile.setMobileDirection(popoTwoId, 1)\r\n    Mobile.setMobileAnimation(popoTwoId, \"AnimEmote-Piece-Debut\")\r\n    Mobile.setMobileAnimationStaticKey(popoTwoId, \"AnimEmote-Piece-Debut\")\nend\n\n-- [SCENE] La coupette 3 est remplie\n-- \nfunction event_1434_10981(popoThreeId)\n    Mobile.setMobileDirection(popoThreeId, 1)\r\n    Mobile.setMobileAnimation(popoThreeId, \"AnimEmote-Piece-Debut\")\r\n    Mobile.setMobileAnimationStaticKey(popoThreeId, \"AnimEmote-Piece-Debut\")\nend\n\n-- [SCENE] Mort de Madame Popo 1\n-- \nfunction event_1434_10982()\n    \nend\n\n-- [SCENE] Mort de Madame Popo 2\n-- \nfunction event_1434_10983()\n    \nend\n\n-- [SCENE] Mort de Madame Popo 3\n-- \nfunction event_1434_10984()\n    \nend\n\n-- [SCENE] Fin du combat Popo 1\n-- \nfunction event_1434_10985()\n    \nend\n\n-- [SCENE] Fin du combat Popo 2\n-- \nfunction event_1434_10986()\n    \nend\n\n-- [SCENE] Fin du combat Popo 3\n-- \nfunction event_1434_10987()\n    \nend\n\n-- [SCENE] Démarrage du spactacle de magie\n-- \nfunction event_1434_10988()\n    \nend\n\n","functions":["event_1434_10973","event_1434_10976","event_1434_10977","event_1434_10978","event_1434_10979","event_1434_10980","event_1434_10981","event_1434_10982","event_1434_10983","event_1434_10984","event_1434_10985","event_1434_10986","event_1434_10987","event_1434_10988"],"quest_calls":[],"dialogue_calls":[]},"scenario/1435.lua":{"source":"\n\n-- [INITIALISATION] Variables\n-- \nfunction event_1435_11001()\n    \nend\n\n-- [ENTARTEUSE] Interaction avec l'entarteuse\n-- \nfunction event_1435_11002(playerTriggererTarte)\n    trace(\"DEPART DE LA TARTE\")\r\n    Mobile.setMobileDirection(playerTriggererTarte, 5)\r\n    Mobile.setMobileAnimation(playerTriggererTarte, \"AnimEmote-TarteAttraction\")\nend\n\n-- [ENTARTEUSE] Interaction avec l'entarteuse - Défaite\n-- \nfunction event_1435_11003(playerTriggerer)\n    animTarte=math.random(1,4)\r\n    \r\n    if animTarte==1 then\r\n    \tInteractiveElement.setAnimation(15476, \"AnimFail01\")\r\n    elseif animTarte==2 then\r\n    \tInteractiveElement.setAnimation(15476, \"AnimFail02\")\r\n    elseif animTarte==3 then\r\n    \tInteractiveElement.setAnimation(15476, \"AnimFail03\")\r\n    else\r\n    \tInteractiveElement.setAnimation(15476, \"AnimFail04\")\r\n    end\nend\n\n-- [ENTARTEUSE] Interaction avec l'entarteuse - Victoire\n-- \nfunction event_1435_11004(playerTriggerer)\n    InteractiveElement.setAnimation(15476, \"AnimWin\")\r\nend\n\n-- [ENTARTEUSE] Réinitialisation\n-- \nfunction event_1435_11005()\n    \nend\n\n-- [ENTARTEUSE] Récompense\n-- \nfunction event_1435_11006()\n    \nend\n\n","functions":["event_1435_11001","event_1435_11002","event_1435_11003","event_1435_11004","event_1435_11005","event_1435_11006"],"quest_calls":[],"dialogue_calls":[]},"scenario/1439.lua":{"source":"\n\n-- [INIT] ENTER_INSTANCE - PRINTEMPS\n-- \nfunction event_1439_11026()\n    --Particle.addParticleSystemToIe(7437004, 27245)\r\n    --Particle.addParticleSystemToIe(7437002, 27246)\r\n    --Particle.addParticleSystemToIe(7437003, 27247)\r\n    --Particle.addParticleSystemToIe(7437001, 27248)\r\nend\n\n-- [INIT] ENTER_INSTANCE - ÉTÉ\n-- \nfunction event_1439_11031()\n    --Particle.addParticleSystemToIe(7437004, 27245)\r\n    --Particle.addParticleSystemToIe(7437002, 27246)\r\n    --Particle.addParticleSystemToIe(7437003, 27247)\r\n    --Particle.addParticleSystemToIe(7437001, 27248)\r\nend\n\n-- [INIT] ENTER_INSTANCE - AUTOMNE\n-- \nfunction event_1439_11032()\n    --Particle.addParticleSystemToIe(7437004, 27245)\r\n    --Particle.addParticleSystemToIe(7437002, 27246)\r\n    --Particle.addParticleSystemToIe(7437003, 27247)\r\n    --Particle.addParticleSystemToIe(7437001, 27248)\r\nend\n\n-- [INIT] ENTER_INSTANCE - HIVER\n-- \nfunction event_1439_11033()\n    --Particle.addParticleSystemToIe(7437004, 27245)\r\n    --Particle.addParticleSystemToIe(7437002, 27246)\r\n    --Particle.addParticleSystemToIe(7437003, 27247)\r\n    --Particle.addParticleSystemToIe(7437001, 27248)\r\nend\n\n","functions":["event_1439_11026","event_1439_11031","event_1439_11032","event_1439_11033"],"quest_calls":[],"dialogue_calls":[]},"scenario/1448.lua":{"source":"\n\n-- [INIT] Variables Globales\n-- \nfunction event_1448_18454()\n    \nend\n\n-- [INIT] Inscription du joueur\n-- \nfunction event_1448_18455()\n    \nend\n\n-- [EMOTE] Accès à la dernière salle\n-- \nfunction event_1448_11186()\n    \nend\n\n-- [EMOTE] Accès à la première salle\n-- \nfunction event_1448_11241()\n    \nend\n\n-- [COFFRE] Le joueur a les ordres du roi\n-- \nfunction event_1448_11271()\n    UI.writeLocalisedInChat(\"quest.chuchoteur.kingorders\")\nend\n\n-- [COFFRE] Le joueur n'a pas les ordres du roi\n-- \nfunction event_1448_11272()\n    InteractiveElement.setAnimation(16272,\"AnimTrans_1_3_1\")\r\n    \r\n    path = Pixmap.getItemPath(14543)\r\n    invoke(500, 1, \"Flying.addFlyingImageIE\", 16272, path)\nend\n\n-- USER_GROUP_KILLED - Salle 01\n-- \nfunction event_1448_18456()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 02\n-- \nfunction event_1448_18457()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 03\n-- \nfunction event_1448_18458()\n    \nend\n\n-- Lancement d'un combat\n-- \nfunction event_1448_11228()\n    \nend\n\n-- Déplace le joueur vers la salle suivante\n-- \nfunction event_1448_18459()\n    \nend\n\n","functions":["event_1448_18454","event_1448_18455","event_1448_11186","event_1448_11241","event_1448_11271","event_1448_11272","event_1448_18456","event_1448_18457","event_1448_18458","event_1448_11228","event_1448_18459"],"quest_calls":[],"dialogue_calls":[]},"scenario/1450.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\n--Initialisation des paramètres\r\nplayerId = Context.getPlayer()\n\n-- [INIT] Serveur\n-- \nfunction event_1450_11084()\n    \nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_1450_11085()\n    \nend\n\n-- [EVENT] Ouverture Salle 4 - Le joueur a la clef (Quête)\n-- \nfunction event_1450_11198()\n    \nend\n\n-- [EVENT] Ouverture Salle 4 - Le joueur n'a pas la clef (Quête)\n-- \nfunction event_1450_11274()\n    UI.writeLocalisedInChat(\"quest.chuchoteur.cachot.noKey\")\nend\n\n-- [EVENT] Victoire Salle 4 (Quête)\n-- \nfunction event_1450_11189()\n    \nend\n\n-- [EVENT] Libération des prisonniers (Quête)\n-- \nfunction event_1450_11215(prisonnierOne, prisonnierTwo, prisonnierThree, prisonnierFour)\n    xa,ya,za=Mobile.getMobilePosition(prisonnierOne)\r\n    xb,yb,zb=Mobile.getMobilePosition(prisonnierTwo)\r\n    xc,yc,zc=Mobile.getMobilePosition(prisonnierThree)\r\n    xd,yd,zd=Mobile.getMobilePosition(prisonnierFour)\r\n    \r\n    invoke(1000,1,\"prisonnerTalk\",prisonnierOne,\"quest.chuchoteur.prisonnier1\",xa)\r\n    invoke(4000,1,\"prisonnerTalk\",prisonnierTwo,\"quest.chuchoteur.prisonnier2\",xb)\r\n    invoke(7000,1,\"prisonnerTalk\",prisonnierThree,\"quest.chuchoteur.prisonnier3\",xc)\r\n    invoke(10000,1,\"prisonnerTalk\",prisonnierFour,\"quest.chuchoteur.prisonnier4\",xd)\r\n    invoke(13000,1,\"prisonnerLastTalk\",prisonnierOne,\"quest.chuchoteur.prisonnier1.2\",xa)\r\n    \r\n    function prisonnerTalk(mobileId,text,x)\r\n    \tMobile.setMobileAnimation(mobileId, \"AnimSort-Soin\")\r\n    \r\n    \tBubbleText.closeBubbleAttachedTo(mobileId)\r\n    \ttetext = BubbleText.prepareWakfuBubble(mobileId, x, 14)\r\n    \tBubbleText.setText(tetext, text)\r\n    \tBubbleText.show(tetext)\r\n    \t\r\n    \tinvoke(3000,1,\"BubbleText.close\",tetext)\r\n    end\r\n    \r\n    function prisonnerLastTalk(mobileId,text,x)\r\n    \tMobile.setMobileDirection(mobileId, 5)\r\n    \tMobile.setMobileAnimation(mobileId, \"AnimSort-Soin\")\r\n    \r\n    \tBubbleText.closeBubbleAttachedTo(mobileId)\r\n    \ttetext = BubbleText.prepareWakfuBubble(mobileId, x, 14)\r\n    \tBubbleText.setText(tetext, text)\r\n    \tBubbleText.show(tetext)\r\n    \t\r\n    \tinvoke(5000,1,\"BubbleText.close\",tetext)\r\n    end\nend\n\n-- [EVENT] Le joueur rentre - Cinématique avec le Roi Chuchoku\n-- \nfunction event_1450_21249(mobA, mobB, mobC, mobD, mobE, mobF, mobG, mobH, prisonnierOne, prisonnierTwo, prisonnierThree, prisonnierFour)\n    local playerId = Context.getLeaderId()\r\n    local chuchokuId = createActor(145102081, -19, 0, 0, 8, 5, 6)\r\n    local mobAId = toLong(mobA)\r\n    local mobBId = toLong(mobB)\r\n    local mobCId = toLong(mobC)\r\n    local mobDId = toLong(mobD)\r\n    local mobEId = toLong(mobE)\r\n    local mobFId = toLong(mobF)\r\n    local mobGId = toLong(mobG)\r\n    local prisonnierOneId = toLong(prisonnierOne)\r\n    local prisonnierTwoId = toLong(prisonnierTwo)\r\n    local prisonnierThreeId = toLong(prisonnierThree)\r\n    local prisonnierFourId = toLong(prisonnierFour)\r\n    \r\n    startCinematicContext(1.2, chuchokuId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 21249)\r\n    \r\n    invoke_custom(00001, 1, \"Mobile.setMobileVisible\", mobAId, false)\r\n    invoke_custom(00001, 1, \"Mobile.setPartColor\", chuchokuId, \"Peau\", 0.41,0.35,0.32,1)\r\n    invoke_custom(00001, 1, \"Mobile.setMobileVisible\", mobBId, false)\r\n    invoke_custom(00001, 1, \"Mobile.setMobileVisible\", mobCId, false)\r\n    invoke_custom(00001, 1, \"Mobile.setMobileVisible\", mobDId, false)\r\n    invoke_custom(00001, 1, \"Mobile.setMobileVisible\", mobEId, false)\r\n    invoke_custom(00001, 1, \"Mobile.setMobileVisible\", mobFId, false)\r\n    invoke_custom(00001, 1, \"Mobile.setMobileVisible\", mobGId, false)\r\n    invoke_custom(00001, 1, \"Mobile.setMobileVisible\", mobHId, false)\r\n    invoke_custom(00001, 1, \"Mobile.setMobileVisible\", prisonnierOneId, false)\r\n    invoke_custom(00001, 1, \"Mobile.setMobileVisible\", prisonnierTwo, false)\r\n    invoke_custom(00001, 1, \"Mobile.setMobileVisible\", prisonnierThree, false)\r\n    invoke_custom(00001, 1, \"Mobile.setMobileVisible\", prisonnierFour, false)\r\n    \r\n    invoke_custom(00100, 1, \"Mobile.setMobilePosition\", playerId, -11, 0, 0)\r\n    invoke_custom(00100, 1, \"Mobile.moveMobile\", playerId, -14, 0, 0, \"Mobile.setMobileDirection\", playerId, 5)\r\n    \r\n    -- \"Hmpf, vous revoilà… Laissez-moi deviner, vous venez vous moquer de moi ?\"\r\n    invoke_custom(02000, 1, \"bubble\", chuchokuId, \"quest.chuchoku.01.01\")\r\n    invoke_custom(07000, 1, \"clearBubbles\", chuchokuId)\r\n    \r\n    -- \"Pas vraiment.\"\r\n    invoke_custom(07500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Non\")\r\n    invoke_custom(07500, 1, \"bubble\", playerId, \"quest.chuchoku.01.02\")\r\n    invoke_custom(09000, 1, \"clearBubbles\", playerId)\r\n    \r\n    --\"J’ai des questions pour vous, Chuchoku.\"\r\n    invoke_custom(09500, 1, \"bubble\", playerId, \"quest.chuchoku.01.03\")\r\n    invoke_custom(09500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Calmer\")\r\n    invoke_custom(12000, 1, \"clearBubbles\", playerId)\r\n    \r\n    --\"Vous étiez à la recherche de la mélodie des Chuchoteurs, pas vrai ?\"\r\n    invoke_custom(12500, 1, \"bubble\", playerId, \"quest.chuchoku.01.04\")\r\n    invoke_custom(12500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Calmer\")\r\n    invoke_custom(16000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(16000, 1, \"Mobile.setMobileDirection\", chuchokuId, 1)\r\n    \r\n    -- \"Par votre seule et unique faute, notre peuple est condamné à l’exil.\"\r\n    invoke_custom(16500, 1, \"bubble\", chuchokuId, \"quest.chuchoku.01.05\")\r\n    invoke_custom(20000, 1, \"clearBubbles\", chuchokuId)\r\n    \r\n    -- \"L’histoire ne retiendra rien de notre passage sur ce Monde.\"\r\n    invoke_custom(20500, 1, \"bubble\", chuchokuId, \"quest.chuchoku.01.06\")\r\n    invoke_custom(24000, 1, \"clearBubbles\", chuchokuId)\r\n    \r\n    -- \"Pourquoi devrais-je vous livrer le secret le plus important de notre peuple ?\"\r\n    invoke_custom(24500, 1, \"bubble\", chuchokuId, \"quest.chuchoku.01.07\")\r\n    invoke_custom(29000, 1, \"clearBubbles\", chuchokuId)\r\n    \r\n    -- \"Je sais que vous vous sentez seul, à gouverner votre royaume et votre peuple.\"\r\n    invoke_custom(29500, 1, \"bubble\", playerId, \"quest.chuchoku.01.08\")\r\n    invoke_custom(29500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Calmer\")\r\n    invoke_custom(34000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Vous êtes responsable de l’avenir de tous vos semblables.\"\r\n    invoke_custom(34500, 1, \"bubble\", playerId, \"quest.chuchoku.01.09\")\r\n    invoke_custom(38000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Mais ce n’est pas une raison pour faire tout ce que vous avez fait.\"\r\n    invoke_custom(38500, 1, \"bubble\", playerId, \"quest.chuchoku.01.10\")\r\n    invoke_custom(42000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"J’ai connu beaucoup de gouverneurs.\"\r\n    invoke_custom(42500, 1, \"bubble\", playerId, \"quest.chuchoku.01.11\")\r\n    invoke_custom(45000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Certains avec de bonnes idées, d’autres avec de mauvaises…\"\r\n    invoke_custom(45500, 1, \"bubble\", playerId, \"quest.chuchoku.01.12\")\r\n    invoke_custom(45500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Presenter\")\r\n    invoke_custom(49000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Il faut comprendre que ce ne sont pas vos idées qui comptent, mais celles de vos citoyens.\"\r\n    invoke_custom(49500, 1, \"bubble\", playerId, \"quest.chuchoku.01.13\")\r\n    invoke_custom(49500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Non\")\r\n    invoke_custom(56500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Votre rôle est de choisir, pas de décider.\"\r\n    invoke_custom(57000, 1, \"bubble\", playerId, \"quest.chuchoku.01.14\")\r\n    invoke_custom(60500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Peut-être que les Chuchoteurs sont capables de vivre en harmonie avec les Craqueleurs.\"\r\n    invoke_custom(61000, 1, \"bubble\", playerId, \"quest.chuchoku.01.15\")\r\n    invoke_custom(67500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Vous devez unifier votre peuple.\"\r\n    invoke_custom(68000, 1, \"bubble\", playerId, \"quest.chuchoku.01.16\")\r\n    invoke_custom(68000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Pouce\")\r\n    invoke_custom(71000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Ainsi vous n’aurez pas à vous sentir seul.\"\r\n    invoke_custom(71000, 1, \"bubble\", playerId, \"quest.chuchoku.01.17\")\r\n    invoke_custom(74000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Voilà de belles paroles venant d’un humain qui nous piétine du matin au soir !\"\r\n    invoke_custom(74500, 1, \"bubble\", chuchokuId, \"quest.chuchoku.01.18\")\r\n    invoke_custom(79000, 1, \"clearBubbles\", chuchokuId)\r\n    \r\n    -- \"Décider du destin d’un peuple n’est pas donné à tout le monde.\"\r\n    invoke_custom(79500, 1, \"bubble\", chuchokuId, \"quest.chuchoku.01.19\")\r\n    invoke_custom(84000, 1, \"clearBubbles\", chuchokuId)\r\n    \r\n    -- \"Je sais que vous aviez de bonnes intentions…\"\r\n    invoke_custom(84500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Calmer\")\r\n    invoke_custom(84500, 1, \"bubble\", playerId, \"quest.chuchoku.01.20\")\r\n    invoke_custom(88000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Je vous demande de ne pas rompre le dialogue avec vos semblables.\"\r\n    invoke_custom(88500, 1, \"bubble\", playerId, \"quest.chuchoku.01.21\")\r\n    invoke_custom(93000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Votre rôle est de rassembler, et de bâtir un endroit où vivre, pour tous.\"\r\n    invoke_custom(93500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Presenter\")\r\n    invoke_custom(93500, 1, \"bubble\", playerId, \"quest.chuchoku.01.22\")\r\n    invoke_custom(97000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Pas de poursuivre une guerre inutile.\"\r\n    invoke_custom(97500, 1, \"bubble\", playerId, \"quest.chuchoku.01.23\")\r\n    invoke_custom(101000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Je vous en supplie, j’ai vraiment besoin de cette mélodie.\"\r\n    invoke_custom(101500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Presenter\")\r\n    invoke_custom(101500, 1, \"bubble\", playerId, \"quest.chuchoku.01.24\")\r\n    invoke_custom(106000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Sinon, il n’y aura plus de chuchoteur, plus de douzien, plus de flaqueux, plus de terre…\"\r\n    invoke_custom(106500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Non\")\r\n    invoke_custom(106500, 1, \"bubble\", playerId, \"quest.chuchoku.01.25\")\r\n    invoke_custom(113000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"...\"\r\n    invoke_custom(113500, 1, \"bubble\", chuchokuId, \"quest.chuchoku.01.26\")\r\n    invoke_custom(115000, 1, \"clearBubbles\", chuchokuId)\r\n    \r\n    -- \"Je vois.\"\r\n    invoke_custom(115500, 1, \"bubble\", chuchokuId, \"quest.chuchoku.01.27\")\r\n    invoke_custom(117000, 1, \"clearBubbles\", chuchokuId)\r\n    \r\n    -- \"Je l’ai cachée au plus profond de la caverne des Carapattes…\"\r\n    invoke_custom(117500, 1, \"bubble\", chuchokuId, \"quest.chuchoku.01.28\")\r\n    invoke_custom(121000, 1, \"clearBubbles\", chuchokuId)\r\n    \r\n    -- \"Et j’ai scellé l’accès à la partition.\"\r\n    invoke_custom(121500, 1, \"bubble\", chuchokuId, \"quest.chuchoku.01.29\")\r\n    invoke_custom(124000, 1, \"clearBubbles\", chuchokuId)\r\n    \r\n    -- \"Je ne vous dirai rien de plus.\"\r\n    invoke_custom(124500, 1, \"bubble\", chuchokuId, \"quest.chuchoku.01.30\")\r\n    invoke_custom(127000, 1, \"clearBubbles\", chuchokuId)\r\n    \r\n    -- \"Merci, votre majesté. À bientôt !\"\r\n    invoke_custom(127500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Victoire\")\r\n    invoke_custom(127500, 1, \"bubble\", playerId, \"quest.chuchoku.01.31\")\r\n    invoke_custom(131000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(131500, 1, \"skipCinematic\", 21249)\nend\n\n-- [EVENT] Fin de la cinématique - ACH 4826 OBJ 9969\n-- \nfunction event_1450_21250()\n    \nend\n\n-- [EVENT] 2 - Le joueur rentre - Cinématique avec le Roi Chuchoku\n-- \nfunction event_1450_21392(mobA, mobB, mobC, mobD, mobE, mobF, mobG, mobH, prisonnierOne, prisonnierTwo, prisonnierThree, prisonnierFour)\n    local playerId = Context.getLeaderId()\r\n    local chuchokuId = createActor(145102081, -19, 0, 0, 8, 1, 6)\r\n    local mobAId = toLong(mobA)\r\n    local mobBId = toLong(mobB)\r\n    local mobCId = toLong(mobC)\r\n    local mobDId = toLong(mobD)\r\n    local mobEId = toLong(mobE)\r\n    local mobFId = toLong(mobF)\r\n    local mobGId = toLong(mobG)\r\n    local prisonnierOneId = toLong(prisonnierOne)\r\n    local prisonnierTwoId = toLong(prisonnierTwo)\r\n    local prisonnierThreeId = toLong(prisonnierThree)\r\n    local prisonnierFourId = toLong(prisonnierFour)\r\n    \r\n    startCinematicContext(1.2, chuchokuId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 21392)\r\n    \r\n    invoke_custom(00001, 1, \"Mobile.setMobileVisible\", mobAId, false)\r\n    invoke_custom(00001, 1, \"Mobile.setPartColor\", chuchokuId, \"Peau\", 0.41,0.35,0.32,1)\r\n    invoke_custom(00001, 1, \"Mobile.setMobileVisible\", mobBId, false)\r\n    invoke_custom(00001, 1, \"Mobile.setMobileVisible\", mobCId, false)\r\n    invoke_custom(00001, 1, \"Mobile.setMobileVisible\", mobDId, false)\r\n    invoke_custom(00001, 1, \"Mobile.setMobileVisible\", mobEId, false)\r\n    invoke_custom(00001, 1, \"Mobile.setMobileVisible\", mobFId, false)\r\n    invoke_custom(00001, 1, \"Mobile.setMobileVisible\", mobGId, false)\r\n    invoke_custom(00001, 1, \"Mobile.setMobileVisible\", mobHId, false)\r\n    invoke_custom(00001, 1, \"Mobile.setMobileVisible\", prisonnierOneId, false)\r\n    invoke_custom(00001, 1, \"Mobile.setMobileVisible\", prisonnierTwo, false)\r\n    invoke_custom(00001, 1, \"Mobile.setMobileVisible\", prisonnierThree, false)\r\n    invoke_custom(00001, 1, \"Mobile.setMobileVisible\", prisonnierFour, false)\r\n    \r\n    invoke_custom(00100, 1, \"Mobile.setMobilePosition\", playerId, -11, 0, 0)\r\n    invoke_custom(00100, 1, \"Mobile.moveMobile\", playerId, -14, 0, 0, \"Mobile.setMobileDirection\", playerId, 5)\r\n    \r\n    -- \"Salut. Je voulais encore vous remercier pour la mélodie. Je l’ai enfin réunie.\"\r\n    invoke_custom(02000, 1, \"bubble\", playerId, \"quest.chuchoku.08.01\")\r\n    invoke_custom(07000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Ça m’a bien aidé{[1*]?e:}… J’ai obtenu un Dofus Turquoise grâce à ça.\"\r\n    invoke_custom(07500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(07500, 1, \"bubble\", playerId, \"quest.chuchoku.08.02\")\r\n    invoke_custom(12500, 1, \"clearBubbles\", playerId)\r\n    \r\n    --\"Vous semblez troublé{[1*]?e:}, aventuri{[1*]?ère:er}.\"\r\n    invoke_custom(13000, 1, \"bubble\", chuchokuId, \"quest.chuchoku.08.03\")\r\n    invoke_custom(16000, 1, \"clearBubbles\", chuchokuId)\r\n    \r\n    --\"Oui… Je dois bientôt partir, très loin.\"\r\n    invoke_custom(16500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(16500, 1, \"bubble\", playerId, \"quest.chuchoku.08.04\")\r\n    invoke_custom(20000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Et pendant très longtemps.\"\r\n    invoke_custom(21500, 1, \"bubble\", playerId, \"quest.chuchoku.08.05\")\r\n    invoke_custom(23500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Il est probable que nous ne nous revoyons plus.\"\r\n    invoke_custom(24000, 1, \"bubble\", playerId, \"quest.chuchoku.08.06\")\r\n    invoke_custom(27500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Vous savez... Je n'ignore pas ce que vous essayez de combattre.\"\r\n    invoke_custom(28000, 1, \"bubble\", chuchokuId, \"quest.chuchoku.08.07\")\r\n    invoke_custom(32500, 1, \"clearBubbles\", chuchokuId)\r\n    \r\n    -- \"Je sais que cette île contient un mal innommable.\"\r\n    invoke_custom(33000, 1, \"bubble\", chuchokuId, \"quest.chuchoku.08.08\")\r\n    invoke_custom(37500, 1, \"clearBubbles\", chuchokuId)\r\n    \r\n    -- \"Je me suis déjà rendu au sommet de la montagne par le passé…\"\r\n    invoke_custom(38000, 1, \"bubble\", chuchokuId, \"quest.chuchoku.08.09\")\r\n    invoke_custom(43000, 1, \"clearBubbles\", chuchokuId)\r\n    \r\n    -- \"J’ai vu quelque chose qui ne devrait pas être ici.\"\r\n    invoke_custom(43500, 1, \"bubble\", chuchokuId, \"quest.chuchoku.08.10\")\r\n    invoke_custom(47000, 1, \"clearBubbles\", chuchokuId)\r\n    \r\n    -- \"Si quelqu’un peut changer les choses, c’est vous.\"\r\n    invoke_custom(47500, 1, \"bubble\", chuchokuId, \"quest.chuchoku.08.11\")\r\n    invoke_custom(51000, 1, \"clearBubbles\", chuchokuId)\r\n    \r\n    -- \"… Vous avez bien changé ma perception des choses, après tout.\"\r\n    invoke_custom(52000, 1, \"bubble\", chuchokuId, \"quest.chuchoku.08.12\")\r\n    invoke_custom(55500, 1, \"clearBubbles\", chuchokuId)\r\n    \r\n    -- \"Adieu.\"\r\n    invoke_custom(56000, 1, \"bubble\", chuchokuId, \"quest.chuchoku.08.13\")\r\n    invoke_custom(58000, 1, \"clearBubbles\", chuchokuId)\r\n    \r\n    -- \"Adieu, Chuchoku.\"\r\n    invoke_custom(58500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Coucou\")\r\n    invoke_custom(58500, 1, \"bubble\", playerId, \"quest.chuchoku.08.14\")\r\n    invoke_custom(61000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(62000, 1, \"skipCinematic\", 21392)\nend\n\n-- [EVENT] 2 - Fin de la cinématique - ACH 4830 OBJ 9997\n-- \nfunction event_1450_21393()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_1450_11084","event_1450_11085","event_1450_11198","event_1450_11274","event_1450_11189","event_1450_11215","prisonnerTalk","prisonnerLastTalk","event_1450_21249","event_1450_21250","event_1450_21392","event_1450_21393"],"quest_calls":[],"dialogue_calls":[]},"scenario/1451.lua":{"source":"playerId = Context.getPlayer()\r\n\r\nfunction craquapultePlayInit(mobileId, craquapultage)\r\nlongCraquapultage = toLong(craquapultage)\r\ntrace(\"CRAQUA =\", longCraquapultage)\r\n\tif longCraquapultage==1 then\r\n\t\tMobile.setMobileAnimation(mobileId, \"AnimComp-Sortie-Fin\")\r\n\t\t--Mobile.setMobileToStaticAnimation(mobileId, \"AnimComp-Catapultage-Fin\")\r\n\tend\r\nend\n\n-- [INITIALISATION] Variables\n-- \nfunction event_1451_11195()\n    \nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_1451_11095(craquapultage, craquapulteId)\n    trace(\"HOP DE HOP\")\r\n    Mobile.addMobileCreationCallback(craquapulteId, \"craquapultePlayInit\", craquapulteId, craquapultage)\r\nend\n\n-- [COMBAT] Victoire Salle 1\n-- \nfunction event_1451_11096()\n    \nend\n\n-- [COMBAT] Victoire Salle 1 - On déverouille la porte\n-- \nfunction event_1451_11097()\n    \nend\n\n-- [COMBAT] Victoire Salle 2\n-- \nfunction event_1451_11098()\n    \nend\n\n-- [COMBAT] Victoire Salle 2 - On déverouille la porte\n-- \nfunction event_1451_11099()\n    \nend\n\n-- [COMBAT] Victoire Salle 3\n-- \nfunction event_1451_11100()\n    \nend\n\n-- [COMBAT] Victoire Salle 3 - On active le 2e groupe de monstres\n-- \nfunction event_1451_11101()\n    \nend\n\n-- [COMBAT] Victoire Salle 3-B\n-- \nfunction event_1451_11196()\n    \nend\n\n-- [COMBAT] Victoire Salle 3-B - On active le TP et le coffre\n-- \nfunction event_1451_11197()\n    \nend\n\n-- [03][SCENE] Arrivée dans la salle de la Craquapulte - Premier joueur\n-- \nfunction event_1451_11218(craquapulteId)\n    function craquapulte(craquapulteId)\r\n    \tMobile.setMobileAnimation(craquapulteId, \"AnimComp-Catapultage\")\r\n    end\r\n    \r\n    Camera.setWorldTarget(-15, -57, 0)\r\n    invoke(2000, 1, \"craquapulte\",craquapulteId)\r\n    invoke(8500, 1, \"Camera.attachCameraToMobile\",playerId)\r\n    invoke(8500, 1, \"Mobile.setMobileAnimation\",craquapulteId, \"AnimComp-Sortie-Fin\")\r\n    \r\n    \t\t\nend\n\n-- [03][SCENE] Arrivée dans la salle de la Craquapulte - Autres joueurs\n-- \nfunction event_1451_11277(craquapulteId)\n    Mobile.setMobileAnimation(craquapulteId, \"AnimComp-Sortie-Fin\")\r\n    \r\n    \t\t\nend\n\n-- [03][SCENE] Fin du Craquapultage\n-- \nfunction event_1451_11270(craquapulteId)\n    \nend\n\n-- [Quête] Initialisation des variables\n-- \nfunction event_1451_11203()\n    \nend\n\n-- [Quête] Activation du premier trigger pour la destruction de l'arme ultime\n-- \nfunction event_1451_11204(triggerChuchair, chuchokuKilled)\n    trace(\"trigger chuchair : \", triggerChuchair)\nend\n\n-- [Quête] Décrément du premier trigger pour la destruction de l'arme ultime\n-- \nfunction event_1451_11205(triggerChuchair)\n    \nend\n\n-- [Quête] Activation du deuxième trigger pour la destruction de l'arme ultime\n-- \nfunction event_1451_11206(triggerChucheau, chuchokuKilled)\n    \nend\n\n-- [Quête] Décrément du deuxième trigger pour la destruction de l'arme ultime\n-- \nfunction event_1451_11207(triggerChucheau)\n    \nend\n\n-- [Quête] Activation du troisième trigger pour la destruction de l'arme ultime\n-- \nfunction event_1451_11208(triggerChuchfeu, chuchokuKilled)\n    \nend\n\n-- [Quête] Décrément du troisième trigger pour la destruction de l'arme ultime\n-- \nfunction event_1451_11209(triggerChuchfeu)\n    \nend\n\n-- [Quête] Activation du quatrième trigger pour la destruction de l'arme ultime\n-- \nfunction event_1451_11210(triggerChuchterre, chuchokuKilled)\n    \nend\n\n-- [Quête] Décrément du troisième trigger pour la destruction de l'arme ultime\n-- \nfunction event_1451_11211(triggerChuchterre)\n    \nend\n\n-- [Quête] Destruction de l'arme ultime\n-- \nfunction event_1451_11212(triggerChuchterre, triggerChuchair, triggerChucheau, triggerChuchfeu)\n    Effect.createCameraShakeEffect(1500,2500,1000,5,50,\"Both\")\r\n    \r\n    invoke(0500, 1, \"Particle.addParticleSystem\", 7448001, -1, -96, 26)\r\n    invoke(0750, 1, \"Particle.addParticleSystem\", 7448002, 3, -96, 29)\r\n    invoke(1000, 1, \"Particle.addParticleSystem\", 7448003, 2, -96, 36)\r\n    \r\n    invoke(1250, 1, \"Particle.addParticleSystem\", 7448004, -2, -94, 22)\r\n    invoke(1500, 1, \"Particle.addParticleSystem\", 7448005, 4, -94, 23)\r\n    invoke(1750, 1, \"Particle.addParticleSystem\", 7448004, 2, -96, 36)\r\n    \r\n    invoke(2000, 1, \"Particle.addParticleSystem\", 7448003, 0, -97, 34)\r\n    invoke(2250, 1, \"Particle.addParticleSystem\", 7448005, -1, -96, 27)\r\n    invoke(2500, 1, \"Particle.addParticleSystem\", 7448001, -2, -94, 20)\r\n    \r\n    invoke(2750, 1, \"Particle.addParticleSystem\", 7448002, 4, -94, 22)\r\n    invoke(3000, 1, \"Particle.addParticleSystem\", 7448001, 3, -96, 25)\r\n    invoke(3250, 1, \"Particle.addParticleSystem\", 7448004, 2, -94, 20)\r\n    \r\n    invoke(3500, 1, \"Particle.addParticleSystem\", 7448003, 3, -96, 30)\r\n    invoke(3750, 1, \"Particle.addParticleSystem\", 7448005, 4, -94, 23)\r\n    invoke(4000, 1, \"Particle.addParticleSystem\", 7448002, 0, -94, 20)\r\n    \r\n    trace(\"destruction triggerChuchterre=\",triggerChuchterre)\r\n    trace(\"destruction triggerChuchair=\",triggerChuchair)\r\n    trace(\"destruction triggerChucheau=\",triggerChucheau)\r\n    trace(\"destruction triggerChuchfeu=\",triggerChuchfeu)\r\nend\n\n-- [Quête] Mort de Chuchoku\n-- \nfunction event_1451_11249(chuchokuKilled)\n    \nend\n\n-- [Quête] Aggro de Chuchoku si le joueur joue le chuchair\n-- \nfunction event_1451_11250(chuchokuKilled)\n    \nend\n\n-- [Quête] Aggro de Chuchoku si le joueur joue le chucheau\n-- \nfunction event_1451_11251(chuchokuKilled)\n    \nend\n\n-- [Quête] Aggro de Chuchoku si le joueur joue le chuchfeu\n-- \nfunction event_1451_11252(chuchokuKilled)\n    \nend\n\n-- [Quête] Aggro de Chuchoku si le joueur joue le chuchterre\n-- \nfunction event_1451_11253(chuchokuKilled)\n    \nend\n\n-- [ARCHI] Apparition de l'Archimonstre\n-- \nfunction event_1451_23970()\n    \nend\n\n"