me cible\n-- \nfunction event_1454_11185()\n    \nend\n\n-- [INITIALISATION] Peinture de la troisième cible\n-- \nfunction event_1454_11183()\n    \nend\n\n-- [COMBAT] Victoire Salle 1\n-- \nfunction event_1454_11154()\n    \nend\n\n-- [COMBAT] Victoire Salle 1 - On déverouille la porte\n-- \nfunction event_1454_11155()\n    \nend\n\n-- [COMBAT] Victoire Salle 2\n-- \nfunction event_1454_11156()\n    \nend\n\n-- [COMBAT] Victoire Salle 2 - On déverouille la porte\n-- \nfunction event_1454_11157()\n    \nend\n\n-- [COMBAT] Victoire Salle 3\n-- \nfunction event_1454_11158()\n    \nend\n\n-- [COMBAT] Victoire Salle 3 - On active le TP\n-- \nfunction event_1454_11159()\n    \nend\n\n-- Lancement du combat de la salle 01\n-- \nfunction event_1454_11163()\n    \nend\n\n-- Lancement du combat de la salle 02\n-- \nfunction event_1454_11164()\n    \nend\n\n-- Lancement du combat de la salle 03\n-- \nfunction event_1454_11165()\n    \nend\n\n-- [EMOTE] Accès à la dernière salle\n-- \nfunction event_1454_11219()\n    \nend\n\n-- [EMOTE] Accès à la première salle\n-- \nfunction event_1454_11242()\n    \nend\n\n-- [EVENT] Le joueur efface un spot de peinture (variable nbChuchoteurPaintErased)\n-- \nfunction event_1454_20398()\n    \nend\n\n","functions":["event_1454_11153","event_1454_11181","event_1454_11185","event_1454_11183","event_1454_11154","event_1454_11155","event_1454_11156","event_1454_11157","event_1454_11158","event_1454_11159","event_1454_11163","event_1454_11164","event_1454_11165","event_1454_11219","event_1454_11242","event_1454_20398"],"quest_calls":[],"dialogue_calls":[]},"scenario/1455.lua":{"source":" --Initialisation des paramètres\r\nplayerId = Context.getPlayer()\r\n\n\n-- [INITIALISATION] Variable\n-- \nfunction event_1455_11191()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_1455_11169()\n    \nend\n\n-- [COMBAT] Déclenchement du combat 0\n-- \nfunction event_1455_11170()\n    \nend\n\n-- [COMBAT] Pré-Lancement du combat 0\n-- \nfunction event_1455_11273()\n    \nend\n\n-- [COMBAT] Lancement du combat 0\n-- \nfunction event_1455_11160()\n    \nend\n\n-- [COMBAT] Fin du combat 0\n-- \nfunction event_1455_11162()\n    \nend\n\n-- [SCENE] Le joueur marche sur le trigger\n-- \nfunction event_1455_11248(witchId, playerTriggerer)\n    function cameraMove()\r\n    \tCamera.attachCameraToMobile(witchId)\r\n    \tinvoke(1000, 1, \"playerSighted\")\r\n    end\r\n    \r\n    function playerSighted()\r\n    \tapsPandaId = Particle.addParticleSystemToTarget(APS_EXCLAMATION, pandaId)\r\n    \tinvoke(500, 1, \"witchSpeechOne\")\r\n    end\r\n    \r\n    function witchSpeechOne()\r\n    \tMobile.setMobileAnimation(witchId, \"AnimEmote-Colere\")\r\n    \tBubbleText.setCharacterSpeak(witchId, \"donjon.halouine.dialWitch1\", false)\r\n    \tinvoke(3000,1,\"witchSpeechTwo\")\r\n    end\r\n    \r\n    function witchSpeechTwo()\r\n    \tMobile.setMobileAnimation(witchId, \"AnimEmote-Pointer\")\r\n    \tBubbleText.setCharacterSpeak(witchId, \"donjon.halouine.dialWitch2\")\r\n    \tinvoke(3000,1,\"witchSpeechThree\")\r\n    end\r\n    \r\n    function witchSpeechThree()\r\n    \tBubbleText.setCharacterSpeak(witchId, \"donjon.halouine.dialWitch3\")\r\n    \tinvoke(3000,1,\"witchSpeechFour\")\r\n    end\r\n    \r\n    function witchSpeechFour()\r\n    \tCamera.attachCameraToMobile(playerId)\r\n    end\r\n    \r\n    trace(\"PLAYER TRIGGERER\", playerTriggerer)\r\n    cameraMove()\r\nend\n\n-- [COMBAT] Déclenchement du combat 2\n-- \nfunction event_1455_11213()\n    \nend\n\n-- [COMBAT] Pré-Lancement du combat 2\n-- \nfunction event_1455_11161()\n    \nend\n\n-- [COMBAT] Lancement du combat 2\n-- \nfunction event_1455_11214()\n    \nend\n\n-- [COMBAT] Check des tours de la Sorcière\n-- \nfunction event_1455_11190(bossTurn)\n    turn=toLong(bossTurn)\r\n    if turn==0 then\r\n    \t--UI.displaySplashText(\"shukrute.wave.last\")\r\n    else\r\n    \tUI.displaySplashText(\"halouine.witch.generic\", turn)\r\n    end\nend\n\n-- [COMBAT] Check des tours de la Sorcière - Défaite\n-- \nfunction event_1455_11192(bossTurn)\n    turn=toLong(bossTurn)\r\n    UI.displaySplashText(\"halouine.witch.player.lost\")\r\nend\n\n-- [COMBAT] Fin du combat 2\n-- \nfunction event_1455_11397()\n    \nend\n\n-- Compteur sur Fight_Join\n-- \nfunction event_1455_11400()\n    \nend\n\n","functions":["event_1455_11191","event_1455_11169","event_1455_11170","event_1455_11273","event_1455_11160","event_1455_11162","event_1455_11248","cameraMove","playerSighted","witchSpeechOne","witchSpeechTwo","witchSpeechThree","witchSpeechFour","event_1455_11213","event_1455_11161","event_1455_11214","event_1455_11190","event_1455_11192","event_1455_11397","event_1455_11400"],"quest_calls":[],"dialogue_calls":[]},"scenario/1456.lua":{"source":"\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_1456_11167()\n    \nend\n\n-- [INITIALISATION] Déclenchement du combat\n-- \nfunction event_1456_11173()\n    \nend\n\n-- Défaite contre les fantassins\n-- \nfunction event_1456_11168(fantassins)\n    xa,ya,za=Mobile.getMobilePosition(fantassins)\r\n    \r\n    BubbleText.closeBubbleAttachedTo(fantassins)\r\n    tetext = BubbleText.prepareWakfuBubble(fantassins, xa, 14)\r\n    BubbleText.setText(tetext, \"quest.chuchoteur.completed.fantassins\")\r\n    BubbleText.show(tetext)\nend\n\n-- Chuchotement pour les arbalètriers\n-- \nfunction event_1456_11171(arbaletriers1)\n    xa,ya,za=Mobile.getMobilePosition(arbaletriers1)\r\n    invoke(1000,1,\"arbaShoot\")\r\n    invoke(5000,1,\"arbaSpeak\")\r\n    \r\n    function arbaShoot()\r\n    \tMobile.setMobileAnimation(arbaletriers1, \"AnimSort-Flechoteuse\")\r\n    end\r\n    \r\n    function arbaSpeak()\r\n    \tBubbleText.closeBubbleAttachedTo(arbaletriers1)\r\n    \ttetext = BubbleText.prepareWakfuBubble(arbaletriers1, xa, 14)\r\n    \tBubbleText.setText(tetext, \"quest.chuchoteur.completed.arbaletriers\")\r\n    \tBubbleText.show(tetext)\r\n    end\nend\n\n","functions":["event_1456_11167","event_1456_11173","event_1456_11168","event_1456_11171","arbaShoot","arbaSpeak"],"quest_calls":[],"dialogue_calls":[]},"scenario/1458.lua":{"source":"\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_1458_11220()\n    \nend\n\n-- [COMBAT] Le joueur marche sur le trigger\n-- \nfunction event_1458_11227()\n    \nend\n\n-- [COMBAT] Lancement du combat 02\n-- \nfunction event_1458_11229()\n    \nend\n\n-- [COMBAT] Le joueur perd le combat et la dent\n-- \nfunction event_1458_11275()\n    \nend\n\n","functions":["event_1458_11220","event_1458_11227","event_1458_11229","event_1458_11275"],"quest_calls":[],"dialogue_calls":[]},"scenario/1471.lua":{"source":"playerId = Context.getPlayer()\r\nparticleId = 7504010\r\n\r\n\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_1471_11367()\n    \nend\n\n-- [INITIALISATION] Variables\n-- \nfunction event_1471_11372()\n    \nend\n\n-- [SCENE] Un joueur est sur la dalle A\n-- \nfunction event_1471_11373()\n    Sound.playLocalSound(10, 70500004, 90, -1, -4 , 0)\r\n    Particle.addParticleSystem(particleId,-1,-4,0)\nend\n\n-- [SCENE] Un joueur est sur la dalle B\n-- \nfunction event_1471_11375()\n    Sound.playLocalSound(10, 70500004, 90, 1, -4 , 0)\r\n    Particle.addParticleSystem(particleId,1,-4,0)\nend\n\n-- [SCENE] Un joueur active le levier - Timer\n-- \nfunction event_1471_11377()\n    Mobile.setMobileDirection(playerId, 7)\r\n    Mobile.setMobileAnimation(playerId, \"AnimInteraction-Levier\")\r\n    InteractiveElement.setAnimation(16834, \"AnimTrans_1\")\nend\n\n-- [SCENE] Un joueur active le levier - la porte s'ouvre\n-- \nfunction event_1471_11421()\n    \nend\n\n","functions":["event_1471_11367","event_1471_11372","event_1471_11373","event_1471_11375","event_1471_11377","event_1471_11421"],"quest_calls":[],"dialogue_calls":[]},"scenario/1472.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\nparticleId = 7504010\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_1472_11379()\n    \nend\n\n-- [INITIALISATION] Variables\n-- \nfunction event_1472_11380()\n    \nend\n\n-- [SCENE] Un joueur est sur la dalle A\n-- \nfunction event_1472_11381()\n    Sound.playLocalSound(10, 70500004, 90, 16, -1 , 0)\r\n    Particle.addParticleSystem(particleId, 16, -1, 0)\nend\n\n-- [SCENE] Un joueur est sur la dalle B\n-- \nfunction event_1472_11383()\n    Sound.playLocalSound(10, 70500004, 90, 18, -1 , 0)\r\n    Particle.addParticleSystem(particleId,18,-1,0)\nend\n\n-- [SCENE] Un joueur est sur la dalle C\n-- \nfunction event_1472_11386()\n    Sound.playLocalSound(10, 70500004, 90, 20, -1 , 0)\r\n    Particle.addParticleSystem(particleId,20,-1,0)\nend\n\n-- [SCENE] Un joueur est sur la dalle D\n-- \nfunction event_1472_11388()\n    Sound.playLocalSound(10, 70500004, 90, 16, 2 , 0)\r\n    Particle.addParticleSystem(particleId,16,2,0)\nend\n\n-- [SCENE] Un joueur est sur la dalle E\n-- \nfunction event_1472_11390()\n    Sound.playLocalSound(10, 70500004, 90, 18, 2 , 0)\r\n    Particle.addParticleSystem(particleId,18,2,0)\nend\n\n-- [SCENE] Un joueur est sur la dalle F\n-- \nfunction event_1472_11392()\n    Sound.playLocalSound(10, 70500004, 90, 20, 2 , 0)\r\n    Particle.addParticleSystem(particleId,20,2,0)\nend\n\n-- [SCENE] Les 6 dalles sont actives - La porte s'ouvre\n-- \nfunction event_1472_11394()\n    \nend\n\n-- FIGHT_ENDED_IN_CLIENT_EVENT - Cinématique\n-- \nfunction event_1472_11463()\n    local playerId = Context.getLeaderId()\r\n    local peroucanOne = createActor(990015, 19, -76, 0, 4, 3, 4)\r\n    local peroucanTwo = createActor(990015, 21, -76, 0, 4, 3, 4)\r\n    \r\n    Mobile.setPartColor(peroucanOne, \"Peau\", 0.70, 0.86, 0.16, 1)\r\n    Mobile.setPartColor(peroucanOne, \"Cheveux\", 0.14, 0.95, 0.68, 1)\r\n    Mobile.setPartColor(peroucanOne, \"Pupille\", 0.93, 0.42, 0.08, 1)\r\n    \r\n    Mobile.setPartColor(peroucanTwo, \"Peau\", 0.70, 0.86, 0.16, 1)\r\n    Mobile.setPartColor(peroucanTwo, \"Cheveux\", 0.14, 0.95, 0.68, 1)\r\n    Mobile.setPartColor(peroucanTwo, \"Pupille\", 0.93, 0.42, 0.08, 1)\r\n    Mobile.setMobilePosition(playerId, 20, -73, 0)\r\n    Mobile.setMobileDirection(playerId, 7)\r\n    \r\n    startCinematicContext(1.2, playerId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 11463)\r\n    \r\n    -- \"Ce doit être Azozu !\"\r\n    invoke_custom(00500, 1, \"bubble\", playerId, \"quest.ereboria.zone.01.09\")\r\n    invoke_custom(01500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Pointer\")\r\n    invoke_custom(04500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Et il est avec une amie...\"\r\n    invoke_custom(04500, 1, \"bubble\", playerId, \"quest.ereboria.zone.01.10\")\r\n    invoke_custom(05500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(07500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Venez, je vais vous ramener voir Nao.\"\r\n    invoke_custom(08000, 1, \"bubble\", playerId, \"quest.ereboria.zone.01.11\")\r\n    invoke_custom(08500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Calmer\")\r\n    invoke_custom(12000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(12500, 1, \"skipCinematic\", 11463)\nend\n\n-- Fin de la cinématique\n-- \nfunction event_1472_22261()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_1472_11379","event_1472_11380","event_1472_11381","event_1472_11383","event_1472_11386","event_1472_11388","event_1472_11390","event_1472_11392","event_1472_11394","event_1472_11463","event_1472_22261"],"quest_calls":[],"dialogue_calls":[]},"scenario/1474.lua":{"source":"function chachaTurn(id, turn)\r\n\tMobile.setMobileDirection(id, turn)\r\nend\n\n-- INITIALISATION\n-- \nfunction event_1474_11401()\n    \nend\n\n-- [INITIALISATION] Inscription du joueur\n-- \nfunction event_1474_11402()\n    \nend\n\n-- [SALLE 01] Victoire - On déverouille la porte\n-- \nfunction event_1474_11403()\n    \nend\n\n-- [SALLE 01] Victoire - La porte est ouverte\n-- \nfunction event_1474_11404()\n    \nend\n\n-- [SALLE 02] Victoire - On déverouille la porte\n-- \nfunction event_1474_11405()\n    \nend\n\n-- [SALLE 02] Victoire - La porte est ouverte\n-- \nfunction event_1474_11406()\n    \nend\n\n-- [SALLE 03] Victoire - On déverouille la porte\n-- \nfunction event_1474_11407(bossId)\n    \nend\n\n-- [SALLE 03] Victoire - La porte est ouverte\n-- \nfunction event_1474_11408(bossId)\n    \nend\n\n-- [SALLE 04] Victoire - On active le tp\n-- \nfunction event_1474_11433(bossId)\n    \nend\n\n","functions":["chachaTurn","event_1474_11401","event_1474_11402","event_1474_11403","event_1474_11404","event_1474_11405","event_1474_11406","event_1474_11407","event_1474_11408","event_1474_11433"],"quest_calls":[],"dialogue_calls":[]},"scenario/1476.lua":{"source":"\n\n-- [INIT] Variables Globales\n-- \nfunction event_1476_20200()\n    \nend\n\n-- [INIT] Inscription du joueur + Variables Locales\n-- \nfunction event_1476_20201()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 01\n-- \nfunction event_1476_20203()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 02\n-- \nfunction event_1476_20204()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 03 - BOSS\n-- \nfunction event_1476_20205()\n    World.setPictoAlpha(-18, -42, -10, 0, 500)\r\n    World.setPictoAlpha(-18, -42, -12, 0, 500)\r\n    World.setPictoAlpha(-18, -42, -34, 0, 500)\r\n    World.setPictoAlpha(-18, -42, -41, 0, 500)\r\n    World.setPictoAlpha(-18, -43, -4, 0, 500)\r\n    World.setPictoAlpha(-18, -43, -19, 0, 500)\r\n    World.setPictoAlpha(-18, -43, -33, 0, 500)\r\n    World.setPictoAlpha(-18, -44, -41, 0, 500)\r\n    World.setPictoAlpha(-18, -45, -41, 0, 500)\r\n    World.setPictoAlpha(-18, -44, -17, 0, 500)\r\n    World.setPictoAlpha(-18, -44, -31, 0, 500)\r\n    \r\n    World.setPictoAlpha(-18, -43, -5, 0, 500)\r\n    World.setPictoAlpha(-17, -44, -41, 0, 500)\r\n    World.setPictoAlpha(-18, -42, -34, 0, 500)\r\n    World.setPictoAlpha(-18, -42, -41, 0, 500)\nend\n\n-- Déplace le joueur vers la salle suivante\n-- \nfunction event_1476_20206()\n    \nend\n\n-- [EVENT] Lancement du combat du Boss\n-- On rend les ***** de portes walkable\nfunction event_1476_20235()\n    \nend\n\n-- [EVENT] Lancement du combat du Boss - Spawn des glyphes invoc\n-- \nfunction event_1476_20232()\n    \nend\n\n-- [EVENT] Lancement du combat du Boss - On remet les portes bloquantes\n-- \nfunction event_1476_20234()\n    \nend\n\n-- [STELE] FIGHT_STARTED - On applique les difficultés stèles\n-- \nfunction event_1476_22846()\n    \nend\n\n-- [STELE] FIGHT_ENTER_ACTION_PHASE - On applique les bonus sur les joueurs\n-- \nfunction event_1476_22847()\n    \nend\n\n-- [STELE] FIGHT_ENDED - On rend la stèle utilisable en cas de défaite\n-- \nfunction event_1476_22873()\n    \nend\n\n-- [ARCHI] Apparition de l'Archimonstre\n-- \nfunction event_1476_24317()\n    \nend\n\n","functions":["event_1476_20200","event_1476_20201","event_1476_20203","event_1476_20204","event_1476_20205","event_1476_20206","event_1476_20235","event_1476_20232","event_1476_20234","event_1476_22846","event_1476_22847","event_1476_22873","event_1476_24317"],"quest_calls":[],"dialogue_calls":[]},"scenario/1477.lua":{"source":"function mobilePlayInit(mobileId,direction,anim)\r\n\tMobile.setMobileDirection(mobileId, direction)\r\n\tMobile.setMobileAnimation(mobileId, anim)\r\nend\r\n\r\n\n\n-- [INITIALISATION] Variables\n-- \nfunction event_1477_11456()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_1477_11434(SalbaCA, QuartierCA, MousseCA, MousseCB, MousseCC, MousseCD)\n    Mobile.addMobileCreationCallback(MousseCA, \"mobilePlayInit\", MousseCA,1,\"AnimEmote1Des6Assis-Debut\")\r\n    Mobile.addMobileCreationCallback(MousseCB, \"mobilePlayInit\", MousseCB,3,\"AnimEmote1Des6Assis-Debut\")\r\n    Mobile.addMobileCreationCallback(MousseCC, \"mobilePlayInit\", MousseCC,5,\"AnimEmote1Des6Assis-Debut\")\r\n    Mobile.addMobileCreationCallback(MousseCD, \"mobilePlayInit\", MousseCD,7,\"AnimEmote1Des6Assis-Debut\")\r\nend\n\n-- [COMBAT] Salle 01\n-- \nfunction event_1477_11435()\n    \nend\n\n-- [COMBAT] Salle 02\n-- \nfunction event_1477_11436()\n    \nend\n\n-- [COMBAT] Salle 03\n-- \nfunction event_1477_11437()\n    \nend\n\n-- [COMBAT] Salle 04 (BOSS)\n-- \nfunction event_1477_11438()\n    \nend\n\n-- [COFFRE MAUDIT] Le joueur choppe la malédiction\n-- \nfunction event_1477_11452()\n    \nend\n\n-- Lancement du combat de la salle 02\n-- \nfunction event_1477_11453()\n    \nend\n\n-- Lancement du combat de la salle 03\n-- \nfunction event_1477_11454()\n    \nend\n\n-- Lancement du combat de la salle 04\n-- \nfunction event_1477_11455()\n    \nend\n\n-- [COMBAT] Combat Final - Exploit réussi\n-- \nfunction event_1477_11460(nbFighters)\n    \nend\n\n","functions":["mobilePlayInit","event_1477_11456","event_1477_11434","event_1477_11435","event_1477_11436","event_1477_11437","event_1477_11438","event_1477_11452","event_1477_11453","event_1477_11454","event_1477_11455","event_1477_11460"],"quest_calls":[],"dialogue_calls":[]},"scenario/1478.lua":{"source":"\n\n-- [INITIALISATION] Joueur\n-- \nfunction event_1478_11465()\n    \nend\n\n-- [COMBAT] Victoire Salle 1\n-- \nfunction event_1478_11466()\n    \nend\n\n-- [COMBAT] Victoire Salle 1 - On déverouille la porte\n-- \nfunction event_1478_11467()\n    \nend\n\n-- [COMBAT] Victoire Salle 2\n-- \nfunction event_1478_11468()\n    \nend\n\n-- [COMBAT] Victoire Salle 2 - On déverouille la porte\n-- \nfunction event_1478_11469()\n    \nend\n\n-- [COMBAT] Victoire Salle 3\n-- \nfunction event_1478_11470()\n    \nend\n\n-- [COMBAT] Victoire Salle 3 - On active le TP et le coffre\n-- \nfunction event_1478_11471()\n    \nend\n\n-- [COMBAT] Victoire Salle 4\n-- \nfunction event_1478_11472()\n    \nend\n\n-- [COMBAT] Victoire Salle 4 - On déverouille la porte\n-- \nfunction event_1478_11473()\n    \nend\n\n","functions":["event_1478_11465","event_1478_11466","event_1478_11467","event_1478_11468","event_1478_11469","event_1478_11470","event_1478_11471","event_1478_11472","event_1478_11473"],"quest_calls":[],"dialogue_calls":[]},"scenario/1479.lua":{"source":"\n\n-- [INIT] Variables Globales\n-- \nfunction event_1479_19070()\n    \nend\n\n-- [INIT] Inscription du joueur\n-- \nfunction event_1479_19071(catOne, catTwo, catThree, catFour, catFive, catSix, catSeven, catEight, catNine, catTen, catEleven, catBoss)\n    Mobile.addMobileCreationCallback(catOne, \"chachaBehaviour\", catOne, 1, \"AnimDonjon05\")\r\n    Mobile.addMobileCreationCallback(catTwo, \"chachaBehaviour\", catTwo, 3, \"AnimDonjon-Dormir-Boucle\")\r\n    Mobile.addMobileCreationCallback(catThree, \"chachaBehaviour\", catThree, 3, \"AnimDonjon-Dormir-Boucle\")\r\n    Mobile.addMobileCreationCallback(catFour, \"chachaBehaviour\", catFour, 5, \"AnimDonjon03\")\r\n    Mobile.addMobileCreationCallback(catFive, \"chachaBehaviour\", catFive, 5,\"AnimDonjon03\")\r\n    Mobile.addMobileCreationCallback(catSix, \"chachaBehaviour\", catSix, 1, \"AnimDonjon-Dormir-Boucle\")\r\n    Mobile.addMobileCreationCallback(catSeven, \"chachaBehaviour\", catSeven, 3, \"AnimDonjon-Dormir-Boucle\")\r\n    Mobile.addMobileCreationCallback(catNine, \"chachaBehaviour\", catNine, 1, \"AnimDonjon-Dormir-Boucle\")\r\n    Mobile.addMobileCreationCallback(catTen, \"chachaBehaviour\", catTen, 1, \"AnimDonjon-Dormir-Boucle\")\r\n    Mobile.addMobileCreationCallback(catEleven, \"chachaBehaviour\", catEleven, 7, \"AnimDonjon-Dormir-Boucle\")\r\n    Mobile.addMobileCreationCallback(catBoss, \"chachaBehaviour\", catBoss, 3, \"AnimDonjon-Dormir-Boucle\")\nend\n\n-- USER_GROUP_KILLED - Salle 01\n-- \nfunction event_1479_19072()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 02\n-- \nfunction event_1479_19073()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 03\n-- \nfunction event_1479_19076()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 04 - BOSS\n-- \nfunction event_1479_19074()\n    \nend\n\n-- Déplace le joueur vers la salle suivante\n-- \nfunction event_1479_19075()\n    \nend\n\n","functions":["event_1479_19070","event_1479_19071","event_1479_19072","event_1479_19073","event_1479_19076","event_1479_19074","event_1479_19075"],"quest_calls":[],"dialogue_calls":[]},"scenario/1481.lua":{"source":"playerId = Context.getPlayer()\n\n-- Initialisation de la variable de test de reussite\n-- \nfunction event_1481_11489()\n    \nend\n\n-- Echec (on arrête le scénario)\n-- \nfunction event_1481_11492(itemId)\n    \tUI.writeLocalisedInChat(\"chat.lime\")\r\n    \tMobile.setMobileAnimation(playerId, \"AnimInteraction-Fin02\")\nend\n\n-- Réussite (on démarre le scénario)\n-- \nfunction event_1481_11494()\n    Mobile.setMobileAnimation(playerId, \"AnimInteraction-Fin01\")\nend\n\n","functions":["event_1481_11489","event_1481_11492","event_1481_11494"],"quest_calls":[],"dialogue_calls":[]},"scenario/1482.lua":{"source":"function chachaTurn(id, turn)\r\n\tMobile.setMobileDirection(id, turn)\r\nend\n\n-- INITIALISATION\n-- \nfunction event_1482_11498()\n    \nend\n\n-- [INITIALISATION] Inscription du joueur\n-- \nfunction event_1482_11499(callbackPasserelle, callbackPasserelleDeux, callbackPasserelleTrois)\n    passerelle = toLong(callbackPasserelle)\r\n    passerelleDeux = toLong(callbackPasserelleDeux)\r\n    passerelleTrois = toLong(callbackPasserelleTrois)\r\n    trace(\"passerelle : \",passerelle)\r\n    trace(\"passerelleDeux : \",passerelleDeux)\r\n    trace(\"passerelleTrois : \",passerelleTrois)\r\n    if passerelle==0 then\r\n    \tWorld.setPictoAlpha(-7, 18, 0, 0, 1)\r\n    \tWorld.setPictoAlpha(-8, 18, 0, 0, 1)\r\n    \tWorld.setPictoAlpha(-9, 18, 0, 0, 1)\r\n    \tWorld.setPictoAlpha(-10, 18, 0, 0, 1)\t\r\n    \tWorld.setPictoAlpha(-11, 18, 0, 0, 1)\r\n    elseif passerelle==1 then\r\n    \tWorld.setPictoAlpha(-7, 18, 0, 1, 1)\r\n    \tWorld.setPictoAlpha(-8, 18, 0, 1, 1)\r\n    \tWorld.setPictoAlpha(-9, 18, 0, 1, 1)\r\n    \tWorld.setPictoAlpha(-10, 18, 0, 1, 1)\t\r\n    \tWorld.setPictoAlpha(-11, 18, 0, 1, 1)\t\r\n    end\r\n    \r\n    if passerelleDeux==0 then\r\n    \tWorld.setPictoAlpha(-22, 8, 0, 0, 1)\r\n    \tWorld.setPictoAlpha(-22, 9, 0, 0, 1)\r\n    \tWorld.setPictoAlpha(-22, 10, 0, 0, 1)\r\n    \tWorld.setPictoAlpha(-22, 11, 0, 0, 1)\r\n    \tWorld.setPictoAlpha(-22, 12, 0, 0, 1)\t\r\n    elseif passerelle==1 then\r\n    \tWorld.setPictoAlpha(-22, 8, 0, 1, 1)\r\n    \tWorld.setPictoAlpha(-22, 9, 0, 1, 1)\r\n    \tWorld.setPictoAlpha(-22, 10, 0, 1, 1)\r\n    \tWorld.setPictoAlpha(-22, 11, 0, 1, 1)\r\n    \tWorld.setPictoAlpha(-22, 12, 0, 1, 1)\r\n    end\r\n    \r\n    if passerelleTrois==0 then\r\n    \tWorld.setPictoAlpha(-36, -11, -1, 0, 1)\r\n    \tWorld.setPictoAlpha(-37, -11, 3, 0, 1)\r\n    \tWorld.setPictoAlpha(-36, -11, 1, 0, 1)\r\n    \tWorld.setPictoAlpha(-37, -11, 5, 0, 1)\r\n    elseif passerelle==1 then\r\n    \tWorld.setPictoAlpha(-36, -11, -1, 1, 1)\r\n    \tWorld.setPictoAlpha(-37, -11, 3, 1, 1)\r\n    \tWorld.setPictoAlpha(-36, -11, 1, 1, 1)\r\n    \tWorld.setPictoAlpha(-37, -11, 5, 1, 1)\r\n    end\nend\n\n-- [SALLE 01] Victoire - On déverouille la porte\n-- \nfunction event_1482_11500()\n    \nend\n\n-- [SALLE 01] Victoire - La porte est ouverte\n-- \nfunction event_1482_11501()\n    \tWorld.setPictoAlpha(-7, 18, 0, 1, 1000)\r\n    \tWorld.setPictoAlpha(-8, 18, 0, 1, 1000)\r\n    \tWorld.setPictoAlpha(-9, 18, 0, 1, 1000)\r\n    \tWorld.setPictoAlpha(-10, 18, 0, 1, 1000)\t\r\n    \tWorld.setPictoAlpha(-11, 18, 0, 1, 1000)\t\nend\n\n-- [SALLE 02] Victoire - On déverouille la porte\n-- \nfunction event_1482_11502()\n    \nend\n\n-- [SALLE 02] Victoire - La porte est ouverte\n-- \nfunction event_1482_11503()\n    \tWorld.setPictoAlpha(-22, 8, 0, 1, 1000)\r\n    \tWorld.setPictoAlpha(-22, 9, 0, 1, 1000)\r\n    \tWorld.setPictoAlpha(-22, 10, 0, 1, 1000)\r\n    \tWorld.setPictoAlpha(-22, 11, 0, 1, 1000)\r\n    \tWorld.setPictoAlpha(-22, 12, 0, 1, 1000)\nend\n\n-- [SALLE 03] Victoire - On déverouille la porte\n-- \nfunction event_1482_11506(bossId)\n    \nend\n\n-- [SALLE 03] Victoire - La porte est ouverte\n-- \nfunction event_1482_11507()\n    World.setPictoAlpha(-36, -11, -1, 1, 1000)\r\n    World.setPictoAlpha(-37, -11, 3, 1, 1000)\r\n    World.setPictoAlpha(-38, -11, 6, 1, 1000)\t\r\n    World.setPictoAlpha(-36, -11, 1, 1, 1000)\r\n    World.setPictoAlpha(-37, -11, 5, 1, 1000)\r\n    World.setPictoAlpha(-38, -11, 8, 1, 1000)\t\nend\n\n-- [SALLE 04] Victoire - On déverouille le tp\n-- \nfunction event_1482_11511(bossId)\n    \nend\n\n","functions":["chachaTurn","event_1482_11498","event_1482_11499","event_1482_11500","event_1482_11501","event_1482_11502","event_1482_11503","event_1482_11506","event_1482_11507","event_1482_11511"],"quest_calls":[],"dialogue_calls":[]},"scenario/1483.lua":{"source":"function chachaTurn(id, turn)\r\n\tMobile.setMobileDirection(id, turn)\r\nend\n\n-- INITIALISATION\n-- \nfunction event_1483_11512()\n    \nend\n\n-- [INITIALISATION] Inscription du joueur\n-- \nfunction event_1483_11513(callbackPasserelle, callbackPasserelleDeux, callbackPasserelleTrois)\n    passerelle = toLong(callbackPasserelle)\r\n    passerelleDeux = toLong(callbackPasserelleDeux)\r\n    passerelleTrois = toLong(callbackPasserelleTrois)\r\n    \r\n    if passerelle==0 then\r\n    \tWorld.setPictoAlpha(-7, 18, 0, 0, 1)\r\n    \tWorld.setPictoAlpha(-8, 18, 0, 0, 1)\r\n    \tWorld.setPictoAlpha(-9, 18, 0, 0, 1)\r\n    \tWorld.setPictoAlpha(-10, 18, 0, 0, 1)\t\r\n    \tWorld.setPictoAlpha(-11, 18, 0, 0, 1)\r\n    elseif passerelle==1 then\r\n    \tWorld.setPictoAlpha(-7, 18, 0, 1, 1)\r\n    \tWorld.setPictoAlpha(-8, 18, 0, 1, 1)\r\n    \tWorld.setPictoAlpha(-9, 18, 0, 1, 1)\r\n    \tWorld.setPictoAlpha(-10, 18, 0, 1, 1)\t\r\n    \tWorld.setPictoAlpha(-11, 18, 0, 1, 1)\t\r\n    end\r\n    \r\n    if passerelleDeux==0 then\r\n    \tWorld.setPictoAlpha(-22, 8, 0, 0, 1)\r\n    \tWorld.setPictoAlpha(-22, 9, 0, 0, 1)\r\n    \tWorld.setPictoAlpha(-22, 10, 0, 0, 1)\r\n    \tWorld.setPictoAlpha(-22, 11, 0, 0, 1)\r\n    \tWorld.setPictoAlpha(-22, 12, 0, 0, 1)\t\r\n    elseif passerelle==1 then\r\n    \tWorld.setPictoAlpha(-22, 8, 0, 1, 1)\r\n    \tWorld.setPictoAlpha(-22, 9, 0, 1, 1)\r\n    \tWorld.setPictoAlpha(-22, 10, 0, 1, 1)\r\n    \tWorld.setPictoAlpha(-22, 11, 0, 1, 1)\r\n    \tWorld.setPictoAlpha(-22, 12, 0, 1, 1)\r\n    end\r\n    \r\n    if passerelleTrois==0 then\r\n    \tWorld.setPictoAlpha(-36, -11, -1, 0, 1)\r\n    \tWorld.setPictoAlpha(-37, -11, 3, 0, 1)\r\n    \tWorld.setPictoAlpha(-36, -11, 1, 0, 1)\r\n    \tWorld.setPictoAlpha(-37, -11, 5, 0, 1)\r\n    elseif passerelle==1 then\r\n    \tWorld.setPictoAlpha(-36, -11, -1, 1, 1)\r\n    \tWorld.setPictoAlpha(-37, -11, 3, 1, 1)\r\n    \tWorld.setPictoAlpha(-36, -11, 1, 1, 1)\r\n    \tWorld.setPictoAlpha(-37, -11, 5, 1, 1)\r\n    end\nend\n\n-- [SALLE 01] Victoire - On déverouille la porte\n-- \nfunction event_1483_11514()\n    \nend\n\n-- [SALLE 01] Victoire - La porte est ouverte\n-- \nfunction event_1483_11515()\n    \tWorld.setPictoAlpha(-7, 18, 0, 1, 1000)\r\n    \tWorld.setPictoAlpha(-8, 18, 0, 1, 1000)\r\n    \tWorld.setPictoAlpha(-9, 18, 0, 1, 1000)\r\n    \tWorld.setPictoAlpha(-10, 18, 0, 1, 1000)\t\r\n    \tWorld.setPictoAlpha(-11, 18, 0, 1, 1000)\t\nend\n\n-- [SALLE 02] Victoire - On déverouille la porte\n-- \nfunction event_1483_11516()\n    \nend\n\n-- [SALLE 02] Victoire - La porte est ouverte\n-- \nfunction event_1483_11517()\n    \tWorld.setPictoAlpha(-22, 8, 0, 1, 1000)\r\n    \tWorld.setPictoAlpha(-22, 9, 0, 1, 1000)\r\n    \tWorld.setPictoAlpha(-22, 10, 0, 1, 1000)\r\n    \tWorld.setPictoAlpha(-22, 11, 0, 1, 1000)\r\n    \tWorld.setPictoAlpha(-22, 12, 0, 1, 1000)\nend\n\n-- [SALLE 03] Victoire - On déverouille la porte\n-- \nfunction event_1483_11518(bossId)\n    \nend\n\n-- [SALLE 03] Victoire - La porte est ouverte\n-- \nfunction event_1483_11519()\n    World.setPictoAlpha(-36, -11, -1, 1, 1000)\r\n    World.setPictoAlpha(-37, -11, 3, 1, 1000)\r\n    World.setPictoAlpha(-38, -11, 6, 1, 1000)\t\r\n    World.setPictoAlpha(-36, -11, 1, 1, 1000)\r\n    World.setPictoAlpha(-37, -11, 5, 1, 1000)\r\n    World.setPictoAlpha(-38, -11, 8, 1, 1000)\t\nend\n\n-- [SALLE 04] Victoire - On déverouille le tp\n-- \nfunction event_1483_11521(bossId)\n    \nend\n\n","functions":["chachaTurn","event_1483_11512","event_1483_11513","event_1483_11514","event_1483_11515","event_1483_11516","event_1483_11517","event_1483_11518","event_1483_11519","event_1483_11521"],"quest_calls":[],"dialogue_calls":[]},"scenario/1484.lua":{"source":"\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_1484_11522()\n    --On Active l'APS de fumée de la cheminée\r\n    particuleCheminee = Particle.addParticleSystem(7474007,-30,0,2)\nend\n\n-- [EVENT] Utilisation Cheminée\n-- \nfunction event_1484_11523()\n    --On Désactive les APS de fumée de la cheminée\r\n    Particle.removeParticleSystem(particuleCheminee)\r\n    \r\n    --Variables - Création des Pandas\r\n    pandaOne = Mobile.generateClientMobileId()\r\n    pandaTwo = Mobile.generateClientMobileId()\r\n    pandaThree = Mobile.generateClientMobileId()\r\n    pandaFour = Mobile.generateClientMobileId()\r\n    pandaFive = Mobile.generateClientMobileId()\r\n    pandaSix = Mobile.generateClientMobileId()\r\n    \r\n    pandas = {pandaOne,pandaTwo,pandaThree,pandaFour,pandaFive,pandaSix}\r\n    pos = {{-31,-106,8},{-30,-103,8},{-31,-100,8},{-35,-106,8},{-34,-103,8},{-34,-100,8}}\r\n    \r\n    --Création des Pandas\r\n    for i=1,#pandas do\r\n    \t\tActor.createActor(pandas[i], 120, pos[i][1], pos[i][2], pos[i][3], 4)\r\n    \t\tActor.equip(pandas[i], \"211200005\", \"VETEMENTCUSTOM\")\r\n        \tActor.equip(pandas[i], \"13613953\", \"CorpsHabit\")\r\n    \t\tActor.equip(pandas[i], \"13410280\", \"Chapeau\")\r\n    \t\tActor.equip(pandas[i], \"11910971\", \"PiedHabit01\")\r\n    \t\tActor.equip(pandas[i], \"11910971\", \"PiedHabit02\")\r\n    \t\tMobile.setMobileDirection(pandas[i], 7)\r\n    \t\tMobile.setMobileAnimation(pandas[i], \"AnimCraft-Tricoter-Boucle\")\r\n    end\r\n    \t\t\t\r\nend\n\n-- [COMBAT] Victoire Salle 1 - Ouverture Porte\n-- \nfunction event_1484_11525()\n    \nend\n\n-- [COMBAT] Victoire Salle 2 - Validation Quête\n-- \nfunction event_1484_11526()\n    \nend\n\n-- [COMBAT] Victoire Salle 3 - Validation Quête\n-- \nfunction event_1484_13266()\n    \nend\n\n","functions":["event_1484_11522","event_1484_11523","event_1484_11525","event_1484_11526","event_1484_13266"],"quest_calls":[],"dialogue_calls":[]},"scenario/1485.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\nAPS_EXCLAMATION = 800173\r\nAPS_POUF=800174\r\n\r\n--=== FONCTIONS ===--\r\nfunction mobPlayInit(mobileId,direction,animation,visible)\r\n\tMobile.setMobileDirection(mobileId,direction)\r\n\tMobile.setMobileAnimation(mobileId, animation)\r\n\tMobile.setMobileVisible(mobileId, visible)\r\nend\r\n\r\n-- Infos stèle d'intervention\r\nfunction updateInterventionInfo(stateInfoId, forceDisplayUI)\r\n\r\n\tif (bubbleSteleInfoId == 0) then\r\n\t\tbubbleSteleInfoId = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_WEST\", 0, -60, false, 2147483647, true, \"interactiveBubbleDialog5\", 30000, 25000, \"onSteleInfoClosed\")\r\n\tend\r\n\r\n\tBubbleText.setText(bubbleSteleInfoId, stateInfoId)\r\n\t\r\n\tif (forceDisplayUI) then BubbleText.show(bubbleSteleInfoId) end\r\nend\n\n-- [INITIALISATION] Variables\n-- \nfunction event_1485_11550()\n    \nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_1485_11528(bossSiege, mobCA, mobCB, mobCC, mobCD, mobCE, mobCF, mobCG, mobCH, bossD, mobDA, mobDB, mobDC, mobDD, mobDE, mobDF, mobDG)\n    --Boss sur son siège\r\n    \r\n    Mobile.addMobileCreationCallback(mobCA, \"mobPlayInit\", mobCA,7,\"AnimEmote-Casino-Boucle\",true)\r\n    Mobile.addMobileCreationCallback(mobCB, \"mobPlayInit\", mobCB,7,\"AnimEmote-Casino-Boucle\",true)\r\n    Mobile.addMobileCreationCallback(mobCC, \"mobPlayInit\", mobCC,7,\"AnimEmote-Casino-Boucle\",true)\r\n    Mobile.addMobileCreationCallback(mobCD, \"mobPlayInit\", mobCD,7,\"AnimEmote-Lire-Boucle\",true)\r\n    Mobile.addMobileCreationCallback(mobCE, \"mobPlayInit\", mobCE,7,\"AnimEmote-Casino-Boucle\",true)\r\n    Mobile.addMobileCreationCallback(mobCF, \"mobPlayInit\", mobCF,1,\"AnimEmote-Chercher\",true)\r\n    Mobile.addMobileCreationCallback(mobCG, \"mobPlayInit\", mobCG,1,\"AnimEmote-Chercher\",true)\r\n    Mobile.addMobileCreationCallback(mobCG, \"mobPlayInit\", mobCH,1,\"AnimEmote-Chercher\",true)\r\n    \r\n    Mobile.addMobileCreationCallback(bossD, \"mobPlayInit\", bossD,1,\"AnimCueillette-Debut\",true)\r\n    \r\n    Mobile.addMobileCreationCallback(mobDA, \"mobPlayInit\", mobDA,1,\"AnimStatique\",false)\r\n    Mobile.addMobileCreationCallback(mobDB, \"mobPlayInit\", mobDB,1,\"AnimStatique\",false)\r\n    Mobile.addMobileCreationCallback(mobDC, \"mobPlayInit\", mobDC,1,\"AnimStatique\",false)\r\n    Mobile.addMobileCreationCallback(mobDD, \"mobPlayInit\", mobDD,1,\"AnimStatique\",false)\r\n    Mobile.addMobileCreationCallback(mobDF, \"mobPlayInit\", mobDF,1,\"AnimStatique\",false)\r\n    Mobile.addMobileCreationCallback(mobDG, \"mobPlayInit\", mobDG,1,\"AnimStatique\",false)\r\n    Mobile.addMobileCreationCallback(mobDE, \"mobPlayInit\", mobDE,1,\"AnimStatique\",false)\r\n    \r\nend\n\n-- (GLOBAL) Victoire salle 01\n-- \nfunction event_1485_11529()\n    \nend\n\n-- (GLOBAL) Victoire salle 01 - Ouverture accès salle 02A + Retour\n-- \nfunction event_1485_11533()\n    InteractiveElement.setAnimation(17358, \"AnimComp-Arrivee\")\nend\n\n-- (GLOBAL) Victoire salle 01 - Ouverture accès salle 02B + Retour\n-- \nfunction event_1485_11534()\n    InteractiveElement.setAnimation(17358, \"AnimComp-Arrivee\")\nend\n\n-- (GLOBAL) Victoire salle 03\n-- \nfunction event_1485_11530()\n    \nend\n\n-- (GLOBAL) Victoire salle 03 - Ouverture accès salle 04A + Retour\n-- \nfunction event_1485_11535()\n    InteractiveElement.setAnimation(17383, \"AnimComp-Arrivee\")\nend\n\n-- (GLOBAL) Victoire salle 03 - Ouverture accès salle 04B + Retour\n-- \nfunction event_1485_11536()\n    InteractiveElement.setAnimation(17383, \"AnimComp-Arrivee\")\nend\n\n-- (GLOBAL) Victoire salle 05 - Scène\n-- \nfunction event_1485_11531()\n    \nend\n\n-- (GLOBAL) Victoire salle 05 - Disparition du Boss\n-- \nfunction event_1485_11632(bossSiege)\n    \nend\n\n-- (GLOBAL) Victoire salle 05 - Le Boss monte à l'échelle\n-- \nfunction event_1485_11630(bossSiege)\n    --x,y,z=Mobile.getMobilePosition(bossSiege)\r\n    Particle.addParticleSystem(800174, -61, -152, 0, 1)\r\n    Mobile.setMobileVisible(bossSiege, true)\r\n    Mobile.setMobileAnimation(bossSiege, \"AnimComp-MonteEchelle\")\nend\n\n-- (GLOBAL) Victoire salle 05 - Ouverture de la porte\n-- \nfunction event_1485_11631()\n    \nend\n\n-- (GLOBAL) Victoire salle 06\n-- \nfunction event_1485_11537()\n    \nend\n\n-- OLD - (COMBAT) Combat 01 - Lancement\n-- \nfunction event_1485_11538()\n    \nend\n\n-- OLD - (COMBAT) Combat 01 - Compteur de tour\n-- \nfunction event_1485_11539(fightOneTurn)\n    trace(\"TOUR=\", fightOneTurn)\nend\n\n-- OLD - (COMBAT) Combat 01 - Fin - Quête réussie\n-- \nfunction event_1485_11540(fightOneTurn)\n    trace(\"VALEUR DU TOUR=\",fightOneTurn)\nend\n\n-- OLD - (COMBAT) Combat 01 - Fin - Quête échouée\n-- \nfunction event_1485_11541()\n    \nend\n\n-- (COMBAT) Combat 02 - Lancement\n-- \nfunction event_1485_11542()\n    trace(\"ETAPE01\")\nend\n\n-- (COMBAT) Combat 02 - Un des joueurs échoue\n-- \nfunction event_1485_11543()\n    trace(\"ETAPE02\")\nend\n\n-- (COMBAT) Combat 02 - Combat gagné\n-- \nfunction event_1485_11544()\n    trace(\"ETAPE03\")\nend\n\n-- (COMBAT) Combat 02 - Fin - Quête réussie\n-- \nfunction event_1485_11545()\n    trace(\"ETAPE04\")\nend\n\n-- (COMBAT) Combat 02 - Fin - Quête échouée\n-- \nfunction event_1485_11546()\n    trace(\"ETAPE05\")\nend\n\n-- (GLOBAL) Entrée dans la salle des commandes\n-- \nfunction event_1485_11638(bossSiege, fightCommande)\n    stateAnimBoss=toLong(fightCommande)\r\n    \r\n    if stateAnimBoss==0 then\r\n    \tMobile.addMobileCreationCallback(bossSiege, \"mobPlayInit\", bossSiege,1,\"AnimStatique-Commande\",true)\r\n    else\n    \tMobile.addMobileCreationCallback(bossSiege, \"mobPlayInit\", bossSiege,1,\"AnimStatique-Echelle\",true)\t\n    end\nend\n\n-- (GLOBAL) Déclenchement du combat de la salle des commandes\n-- \nfunction event_1485_11643(bossSiege, fightCommande, mobDA, mobDB, mobDC, mobDD, mobDE, mobDF, mobDG)\n    --x,y,z=Mobile.getMobilePosition(bossSiege)\r\n    Particle.addParticleSystem(800174, -54, -150, 2, 1)\r\n    Mobile.setMobileVisible(bossSiege, false)\nend\n\n-- (GLOBAL) Déclenchement du dernier combat\n-- \nfunction event_1485_11639(bossSiege, fightCommande, mobDA, mobDB, mobDC, mobDD, mobDE, mobDF, mobDG)\n    Mobile.setMobileVisible(mobDA, true)\r\n    Mobile.setMobileVisible(mobDB, true)\r\n    Mobile.setMobileVisible(mobDC, true)\r\n    Mobile.setMobileVisible(mobDD, true)\r\n    Mobile.setMobileVisible(mobDE, true)\r\n    Mobile.setMobileVisible(mobDF, true)\r\n    Mobile.setMobileVisible(mobDG, true)\r\n    \r\n    Particle.addParticleSystemToTarget(800174, mobDA, 1)\r\n    Particle.addParticleSystemToTarget(800174, mobDB, 1)\r\n    Particle.addParticleSystemToTarget(800174, mobDC, 1)\r\n    Particle.addParticleSystemToTarget(800174, mobDD, 1)\r\n    Particle.addParticleSystemToTarget(800174, mobDE, 1)\r\n    Particle.addParticleSystemToTarget(800174, mobDF, 1)\r\n    Particle.addParticleSystemToTarget(800174, mobDG, 1)\nend\n\n-- (GLOBAL) On décharge la quête de la salle 1\n-- \nfunction event_1485_11640()\n    \nend\n\n-- (GLOBAL) On décharge la quête de la salle 3\n-- \nfunction event_1485_11641()\n    \nend\n\n-- (GLOBAL) On décharge la quête de la salle 5\n-- \nfunction event_1485_11642()\n    \nend\n\n-- [EVENT] Lancement du combat du Boss - Spawn des glyphes invoc\n-- \nfunction event_1485_20244()\n    \nend\n\n-- [ARCHI] Apparition de l'Archimonstre\n-- \nfunction event_1485_23997()\n    \nend\n\n-- [EVENT] Quête Pourpre - Cinématique Javého\n-- \nfunction event_1485_24435()\n    -- \"Cinématique Javého\"\r\n    local playerId = Context.getLeaderId()\r\n    local javehoId = createActor(10, -59, -222, 7, 8, 3, 6)\r\n    local amnesiqueId = createActor(30, -58, -216, 7, 8, 7, 6)\r\n    Actor.equip(amnesiqueId, \"200300003\", \"CHEVEUXCUSTOM\")\r\n    Actor.equip(amnesiqueId, \"51314273\", \"VETEMENTCUSTOM\")\r\n    Actor.equip(amnesiqueId, \"13413954\", \"Chapeau\")\r\n    Actor.equip(amnesiqueId, \"11920941\", \"Bottes\")\r\n    Mobile.setPartColor(amnesiqueId, \"Pupille\", 0.09, 0.27, 0.33, 1)\r\n    Mobile.setPartColor(amnesiqueId, \"Peau\", 0.97, 0.78, 0.53, 1)\r\n    Mobile.setPartColor(amnesiqueId, \"Cheveux\", 0.58, 0.38, 0.09, 1)\r\n    \r\n    Actor.equip(javehoId, \"51315144\", \"VETEMENTCUSTOM\")\r\n    Mobile.setPartColor(javehoId, \"Peau\", 0.0, 0.0, 0.0, 1)\r\n    \r\n    function customSkip()\r\n        Mobile.hideOtherPlayerMobile(false)\r\n        UI.displayWideScreenBand(true, 25, 500)\r\n        skipCinematic(24435)\r\n    end\r\n    \r\n    Mobile.hideOtherPlayerMobile(true)\r\n    startCinematicContext(1.2, playerId)\r\n    \r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"customSkip\")\r\n    \r\n    Mobile.setMobilePosition(playerId, -60, -217, 7)\r\n    Mobile.setMobileDirection(playerId, 7)\r\n    Mobile.setMobileAnimation(javehoId, \"AnimKO-Boucle\")\r\n    Mobile.setMobileAnimation(playerId, \"AnimStatique02\")\r\n    \r\n    invoke_custom(01000, 1, \"Camera.setZoomSpeedFactor\", 0.05)\r\n    invoke_custom(01000, 1, \"Camera.setZoomFactor\", 1.6)\r\n    \r\n    invoke_custom(00001, 1, \"Mobile.setMobileMovementStyle\", playerId, \"WALK\", \"WALK\")\r\n    invoke_custom(00001, 1, \"Mobile.setMobileMovementStyle\", amnesiqueId, \"WALK\", \"WALK\")\r\n    invoke_custom(00001, 1, \"Mobile.setMobileMovementStyle\", javehoId, \"RUN\", \"RUN\")\r\n    invoke_custom(00001, 1, \"Mobile.setCustomWalkStyle\", javehoId, \"AnimCourse\", 300)\r\n    \r\n    invoke_custom(1000, 1, \"Mobile.moveMobile\", playerId, -60, -220, 7)\r\n    invoke_custom(1000, 1, \"Mobile.moveMobile\", amnesiqueId, -58, -220, 7)\r\n    \r\n    -- Javého : Comment osez-vous passer à tabac tout mon équipage ?\r\n    invoke_custom(02000, 1, \"bubble\", javehoId, \"quest.crimson.lampionaute.00.00\")\r\n    invoke_custom(03600, 1, \"Mobile.setMobileAnimation\", javehoId, \"AnimKO-SortieOK\")\r\n    invoke_custom(05000, 1, \"clearBubbles\", javehoId)\r\n    \r\n    -- Joueur : Nous sommes à la recherche d'informations !\r\n    invoke_custom(05500, 1, \"bubble\", playerId, \"quest.crimson.lampionaute.00.01\")\r\n    invoke_custom(05500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Presenter\")\r\n    invoke_custom(08500, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(08750, 1, \"Camera.attachCameraToMobile\", javehoId)\r\n    \r\n    -- Javého : Et ça vous donne le droit de tout casser chez moi ?\r\n    invoke_custom(09000, 1, \"bubble\", javehoId, \"quest.crimson.lampionaute.00.02\")\r\n    invoke_custom(09000, 1, \"Mobile.setMobileAnimation\", javehoId, \"AnimEmote-Colere\")\r\n    invoke_custom(12000, 1, \"clearBubbles\", javehoId)\r\n    \r\n    invoke_custom(12250, 1, \"Camera.attachCameraToMobile\", playerId)\r\n    \r\n    -- Joueur : Dites, c'est pas vous qui cassez tout chez les autres, plutôt ?\r\n    invoke_custom(12500, 1, \"bubble\", playerId, \"quest.crimson.lampionaute.00.03\")\r\n    invoke_custom(12500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Pointer\")\r\n    invoke_custom(12500, 1, \"Mobile.setMobileAnimation\", amnesiqueId, \"AnimEmote-Acquiescer\")\r\n    invoke_custom(15500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- Joueur : Et puis... Vous nous êtes tombés dessus quand nous avons frappé gentiment à la porte.\r\n    invoke_custom(16000, 1, \"bubble\", playerId, \"quest.crimson.lampionaute.00.04\")\r\n    invoke_custom(16000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmoteMarket-HausseEpaules\")\r\n    invoke_custom(19500, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(19750, 1, \"Mobile.setMobileDirection\", playerId, 1)\r\n    \r\n    -- Joueur : Alors ? Est-ce que tu t'es souvenu d'autre chose ?\r\n    invoke_custom(20000, 1, \"bubble\", playerId, \"quest.crimson.lampionaute.00.05\")\r\n    invoke_custom(20000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Calmer\")\r\n    invoke_custom(21500, 1, \"Mobile.setMobileDirection\", amnesiqueId, 5)\r\n    invoke_custom(23000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(19750, 1, \"Camera.setZoomFactor\", 1.8)\r\n    \r\n    -- Joueur : As-tu reconnu quelque chose ou quelqu'un ?\r\n    invoke_custom(23500, 1, \"bubble\", playerId, \"quest.crimson.lampionaute.00.06\")\r\n    invoke_custom(23500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Presenter\")\r\n    invoke_custom(26000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(26250, 1, \"Camera.attachCameraToMobile\", amnesiqueId)\r\n    \r\n    -- Vieil Amnésique : Non, ça ne me dit rien du tout.\r\n    invoke_custom(26500, 1, \"bubble\", amnesiqueId, \"quest.crimson.lampionaute.00.07\")\r\n    invoke_custom(26500, 1, \"Mobile.setMobileAnimation\", amnesiqueId, \"AnimEmoteMarket-HausseEpaules\")\r\n    invoke_custom(28500, 1, \"clearBubbles\", amnesiqueId)\r\n    \r\n    invoke_custom(28750, 1, \"Camera.attachCameraToMobile\", javehoId)\r\n    invoke_custom(28750, 1, \"Camera.setZoomSpeedFactor\", 0.2)\r\n    invoke_custom(28750, 1, \"Camera.setZoomFactor\", 1.4)\r\n    \r\n    -- Javého : Bien sûr que ça ne te dit rien du tout, on ne s'est jamais vu !\r\n    invoke_custom(29000, 1, \"bubble\", javehoId, \"quest.crimson.lampionaute.00.08\")\r\n    invoke_custom(29000, 1, \"Mobile.setMobileDirection\", playerId, 7)\r\n    invoke_custom(29000, 1, \"Mobile.setMobileDirection\", amnesiqueId, 7)\r\n    invoke_custom(29000, 1, \"Mobile.setMobileAnimation\", javehoId, \"AnimEmote-Colere\")\r\n    invoke_custom(29000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Peur\")\r\n    invoke_custom(29000, 1, \"Mobile.setMobileAnimation\", amnesiqueId, \"AnimEmote-Peur\")\r\n    invoke_custom(32000, 1, \"clearBubbles\", javehoId)\r\n    \r\n    -- Javého : Je ne sais même pas qui vous êtes.\r\n    invoke_custom(32500, 1, \"bubble\", javehoId, \"quest.crimson.lampionaute.00.09\")\r\n    invoke_custom(32500, 1, \"Mobile.setMobileAnimation\", javehoId, \"AnimEmote-Pointer\")\r\n    invoke_custom(35000, 1, \"clearBubbles\", javehoId)\r\n    \r\n    invoke_custom(33000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Siffler\")\r\n    \r\n    -- Fondu noir Vous expliquez la situation à Javého\r\n    invoke_custom(35500, 1, \"fullScreen\", 1000, 3000, 1000)\r\n    invoke_custom(35500, 1, \"text\", 1000, 3000, 1000, \"quest.crimson.lampionaute.00.10\")\r\n    \r\n    -- Javého : Notre emblème peut se retrouver partout, sur tous les fronts.\r\n    invoke_custom(41000, 1, \"bubble\", javehoId, \"quest.crimson.lampionaute.00.11\")\r\n    invoke_custom(41000, 1, \"Mobile.setMobileAnimation\", javehoId, \"AnimEmote-Presenter\")\r\n    invoke_custom(44000, 1, \"clearBubbles\", javehoId)\r\n    \r\n    -- Javého : Ce n'est pas parce que vous l'avez vu quelque part qu'on se connait.\r\n    invoke_custom(44500, 1, \"bubble\", javehoId, \"quest.crimson.lampionaute.00.12\")\r\n    invoke_custom(44500, 1, \"Mobile.setMobileAnimation\", javehoId, \"AnimEmote-Non\")\r\n    invoke_custom(48000, 1, \"clearBubbles\", javehoId)\r\n    \r\n    -- Javého : J'ai des desseins plus grands à accomplir que faire du babysitting d'amnésique !\r\n    invoke_custom(48500, 1, \"bubble\", javehoId, \"quest.crimson.lampionaute.00.13\")\r\n    invoke_custom(48500, 1, \"Mobile.setMobileAnimation\", javehoId, \"AnimEmote-Colere\")\r\n    invoke_custom(52500, 1, \"clearBubbles\", javehoId)\r\n    \r\n    invoke_custom(52750, 1, \"Camera.attachCameraToMobile\", playerId)\r\n    invoke_custom(52750, 1, \"Camera.setZoomSpeedFactor\", 2.1)\r\n    invoke_custom(52750, 1, \"Camera.setZoomFactor\", 1.8)\r\n    \r\n    -- Joueur : On verra bien si t'accompliras tes desseins...\r\n    invoke_custom(53000, 1, \"bubble\", playerId, \"quest.crimson.lampionaute.00.16\")\r\n    invoke_custom(53000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Bailler\")\r\n    invoke_custom(55500, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(55750, 1, \"Camera.attachCameraToMobile\", javehoId)\r\n    invoke_custom(55750, 1, \"Camera.setZoomSpeedFactor\", 2.1)\r\n    invoke_custom(55750, 1, \"Camera.setZoomFactor\", 1.6)\r\n    \r\n    -- Javého : On ne se connait pas, on ne s'est jamais vu et j'espère qu'on ne se reverra jamais.\r\n    invoke_custom(56000, 1, \"bubble\", javehoId, \"quest.crimson.lampionaute.00.14\")\r\n    invoke_custom(56000, 1, \"Mobile.setMobileAnimation\", javehoId, \"AnimEmote-Calmer\")\r\n    invoke_custom(60000, 1, \"clearBubbles\", javehoId)\r\n    invoke_custom(60500, 1, \"Mobile.setMobileAnimation\", javehoId, \"AnimEmote-DAB\")\r\n    \r\n    invoke_custom(61750, 1, \"Mobile.moveMobile\", javehoId, -62, -222, 7)\r\n    invoke_custom(62650, 1, \"Mobile.setMobileAnimation\", javehoId, \"AnimRelique-Saut\") --fin ciné + 350ms\r\n    \r\n    invoke_custom(62950, 1, \"customSkip\")\r\nend\n\n-- [EVENT] Fin de la cinématique - Validation ACH 5713 OBJ 11693\n-- \nfunction event_1485_24436()\n    \nend\n\n-- [INTERVENTION] INTERACTIVE_ELEMENT_ACTIVATION - Le joueur examine la Stèle d'intervention\n-- \nfunction event_1485_24498()\n    UI.openRewardsDialog(\"stele.intervention.description.4\")\r\n    \r\n    UI.addReward(33391)\r\n    UI.addReward(33403)\r\n    \r\n    local stateInfoId = \"stele.intervention.ignemikhal.description\" \r\n    \r\n    updateInterventionInfo(stateInfoId, true)\nend\n\n-- [INTERVENTION] GENERIC_ACTIVABLE_ACTION - Activation Stèle d'intervention\n-- \nfunction event_1485_24499(mobTwo)\n    UI.openRewardsDialog(\"stele.intervention.description.4\")\r\n    \r\n    UI.addReward(33391)\r\n    UI.addReward(33403)\r\n    \r\n    local stateInfoId = \"stele.intervention.ignemikhal.description\" \r\n    \r\n    updateInterventionInfo(stateInfoId, true)\r\n    \r\n    local bossId = toLong(mobTwo)\r\n    \r\n    invoke(1, 1, \"Mobile.setMobileAnimation\", bossId, \"AnimSort-4-Boucle\")\r\n    invoke(480, 1, \"Mobile.setMobileAnimation\", bossId, \"AnimSort-4-Fin\")\r\n    \r\n    Effect.createCameraShakeEffect(100, 500, 100, 5, 100, \"BOTH\")\r\nend\n\n-- [INTERVENTION] FIGHT_STARTED - On cache la stèle\n-- \nfunction event_1485_24507()\n    \nend\n\n-- [INTERVENTION] FIGHT_ENDED - On rend la stèle utilisable en cas de défaite\n-- \nfunction event_1485_24508()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","mobPlayInit","updateInterventionInfo","event_1485_11550","event_1485_11528","event_1485_11529","event_1485_11533","event_1485_11534","event_1485_11530","event_1485_11535","event_1485_11536","event_1485_11531","event_1485_11632","event_1485_11630","event_1485_11631","event_1485_11537","event_1485_1153