ction event_1501_11657()\n    \nend\n\n-- [COMBAT] Placement des glyphes - Point -2/2\n-- \nfunction event_1501_11658()\n    \nend\n\n-- [COMBAT] Placement des glyphes - Point -1/1\n-- \nfunction event_1501_11659()\n    \nend\n\n-- [COMBAT] Placement des glyphes - Point 0\n-- \nfunction event_1501_11660()\n    \nend\n\n-- [COMBAT] Fin du combat\n-- \nfunction event_1501_12420()\n    \nend\n\n-- [TIMER] Sortie de l'instance\n-- \nfunction event_1501_12437()\n    \nend\n\n-- [GENERAL] Sortie de l'instance\n-- \nfunction event_1501_12462()\n    UI.manageFrame(\"World\",true)\nend\n\n-- [INITIALISATION] Variables\n-- \nfunction event_1501_12552()\n    \nend\n\n-- [COMBAT] Le joueur tue une Gelée\n-- \nfunction event_1501_12553()\n    \nend\n\n-- [EXPLOIT] 8 Gelées sont vaincues - L'exploit est réussi\n-- \nfunction event_1501_12554()\n    \nend\n\n-- [EXPLOIT] 0 Gelées vaincues - Le joueur a réussi la totalité\n-- \nfunction event_1501_12555()\n    \nend\n\n-- [COMBAT] Le joueur a réussi la totalité\n-- \nfunction event_1501_12432()\n    UI.displaySplashText(\"shukrute.victory\")\nend\n\n","functions":["event_1501_11650","event_1501_11651","event_1501_11652","event_1501_11653","event_1501_11654","event_1501_11655","event_1501_11656","event_1501_11657","event_1501_11658","event_1501_11659","event_1501_11660","event_1501_12420","event_1501_12437","event_1501_12462","event_1501_12552","event_1501_12553","event_1501_12554","event_1501_12555","event_1501_12432"],"quest_calls":[],"dialogue_calls":[]},"scenario/1503.lua":{"source":"nbFight = 0\n\n-- [INIT] Inscription du Joueur\n-- \nfunction event_1503_11667()\n    --Salle 1\r\n    \t--Chute de Pierre\r\n    \tParticle.addParticleSystem(7478001,4,-9,13)\r\n    \tParticle.addParticleSystem(7478001,2,3,0)\r\n    \tParticle.addParticleSystem(7478001,13,-7,27)\r\n    \t-- Feuilles volantes\r\n    \tParticle.addParticleSystem(7478002,4,1,-2)\r\n    \t\r\n    --Salle 2\r\n    \t--Chute de Pierre\r\n    \tParticle.addParticleSystem(7478001,32,-7,3)\r\n    \tParticle.addParticleSystem(7478001,34,-12,3)\r\n    \tParticle.addParticleSystem(7478001,23,-4,-10)\r\n    \t-- Feuilles volantes\r\n    \tParticle.addParticleSystem(7478002,39,-5,-10)\r\n    \tParticle.addParticleSystem(7478002,33,-1,-10)\r\n    \t\t\r\n    --Salle 3\r\n    \t--Chute de Pierre\r\n    \tParticle.addParticleSystem(7478001,71,-34,10)\r\n    \tParticle.addParticleSystem(7478001,64,-26,-3)\r\n    \tParticle.addParticleSystem(7478001,78,-22,-10)\r\n    \t-- Feuilles volantes\r\n    \tParticle.addParticleSystem(7478002,70,-29,-10)\r\n    \t\r\n    --Salle 4\r\n    \t--Chute de Pierre\r\n    \tParticle.addParticleSystem(7478001,32,-29,6)\r\n    \tParticle.addParticleSystem(7478001,51,-32,30)\r\n    \tParticle.addParticleSystem(7478001,41,-34,8)\r\n    \t-- Feuilles volantes\r\n    \tParticle.addParticleSystem(7478002,46,-31,0)\r\n    \tParticle.addParticleSystem(7478002,36,-22,0)\nend\n\n-- [FIGHT] Any Fight Will Start + Hélice walkable\n-- \nfunction event_1503_11685()\n    \nend\n\n-- [FIGHT] Any Fight Started + Hélice non walkable\n-- \nfunction event_1503_11668()\n    \nend\n\n-- [EVENT] Salle 1 - Pose des AOE\n-- \nfunction event_1503_11669()\n    \nend\n\n-- [EVENT] Salle 1 - End\n-- \nfunction event_1503_11663()\n    \nend\n\n-- [EVENT] Salle 1 - Activation du TP vers Salle 2\n-- \nfunction event_1503_16387()\n    \nend\n\n-- [EVENT] Salle 2 - Pose des AOE\n-- \nfunction event_1503_11844()\n    \nend\n\n-- [EVENT] Salle 2 - End\n-- \nfunction event_1503_11670()\n    \nend\n\n-- [EVENT] Salle 2 - Activation du TP vers Salle 3\n-- \nfunction event_1503_16388()\n    \nend\n\n-- [EVENT] Salle 3 - Pose des AOE\n-- \nfunction event_1503_11845()\n    \nend\n\n-- [EVENT] Salle 3 - End\n-- \nfunction event_1503_11671()\n    \nend\n\n-- [EVENT] Salle 3 - Activation du TP vers Salle 4\n-- \nfunction event_1503_16389()\n    \nend\n\n-- [EVENT] Salle 4 - Pose des AOE\n-- \nfunction event_1503_11846()\n    \nend\n\n-- [EVENT] Salle 4 - End\n-- \nfunction event_1503_11672()\n    \nend\n\n-- [EVENT] Salle 4 - Activation du TP de sortie\n-- \nfunction event_1503_16390()\n    \nend\n\n","functions":["event_1503_11667","event_1503_11685","event_1503_11668","event_1503_11669","event_1503_11663","event_1503_16387","event_1503_11844","event_1503_11670","event_1503_16388","event_1503_11845","event_1503_11671","event_1503_16389","event_1503_11846","event_1503_11672","event_1503_16390"],"quest_calls":[],"dialogue_calls":[]},"scenario/1505.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\nfunction displayPath(room)\r\n\tlocal room = toLong(room)\r\n\t\r\n\tif ( room >= 1 or room == -1 ) then\r\n\tWorld.setPictoAlpha(-14, 0, 0, 0, 1000)\r\n\tWorld.setPictoAlpha(-15, 0, 0, 0, 1000)\r\n\tWorld.setPictoAlpha(-16, 0, 0, 0, 1000)\r\n\tWorld.setPictoAlpha(-31, 0, 0, 0, 1000)\r\n\tWorld.setPictoAlpha(-32, 0, 0, 0, 1000)\r\n\tWorld.setPictoAlpha(-33, 0, 0, 0, 1000)\r\n\tWorld.setPictoAlpha(-48, 0, 0, 0, 1000)\r\n\tWorld.setPictoAlpha(-49, 0, 0, 0, 1000)\r\n\tWorld.setPictoAlpha(-50, 0, 0, 0, 1000)\r\n\tend\r\n\t\r\n\tif ( room >= 2 or room == -1 ) then\r\n\tWorld.setPictoAlpha(-14, 0, 0, 1, 1000)\r\n\tWorld.setPictoAlpha(-15, 0, 0, 1, 1000)\r\n\tWorld.setPictoAlpha(-16, 0, 0, 1, 1000)\r\n\tWorld.setPictoAlpha(-31, 0, 0, 0, 1000)\r\n\tWorld.setPictoAlpha(-32, 0, 0, 0, 1000)\r\n\tWorld.setPictoAlpha(-33, 0, 0, 0, 1000)\r\n\tWorld.setPictoAlpha(-48, 0, 0, 0, 1000)\r\n\tWorld.setPictoAlpha(-49, 0, 0, 0, 1000)\r\n\tWorld.setPictoAlpha(-50, 0, 0, 0, 1000)\r\n\tend\r\n\t\r\n\tif ( room >= 3 or room == -1) then\r\n\tWorld.setPictoAlpha(-14, 0, 0, 1, 1000)\r\n\tWorld.setPictoAlpha(-15, 0, 0, 1, 1000)\r\n\tWorld.setPictoAlpha(-16, 0, 0, 1, 1000)\r\n\tWorld.setPictoAlpha(-31, 0, 0, 1, 1000)\r\n\tWorld.setPictoAlpha(-32, 0, 0, 1, 1000)\r\n\tWorld.setPictoAlpha(-33, 0, 0, 1, 1000)\r\n\tWorld.setPictoAlpha(-48, 0, 0, 0, 1000)\r\n\tWorld.setPictoAlpha(-49, 0, 0, 0, 1000)\r\n\tWorld.setPictoAlpha(-50, 0, 0, 0, 1000)\r\n\tend\r\n\t\r\n\tif ( room >= 4 or room == -1) then\r\n\tWorld.setPictoAlpha(-14, 0, 0, 1, 1000)\r\n\tWorld.setPictoAlpha(-15, 0, 0, 1, 1000)\r\n\tWorld.setPictoAlpha(-16, 0, 0, 1, 1000)\r\n\tWorld.setPictoAlpha(-31, 0, 0, 1, 1000)\r\n\tWorld.setPictoAlpha(-32, 0, 0, 1, 1000)\r\n\tWorld.setPictoAlpha(-33, 0, 0, 1, 1000)\r\n\tWorld.setPictoAlpha(-48, 0, 0, 1, 1000)\r\n\tWorld.setPictoAlpha(-49, 0, 0, 1, 1000)\r\n\tWorld.setPictoAlpha(-50, 0, 0, 1, 1000)\r\n\tend\r\nend\n\n-- [INIT] Variables Globales\n-- \nfunction event_1505_20038()\n    \nend\n\n-- [INIT] Inscription du joueur + Variables Locales\n-- \nfunction event_1505_20039(room)\n    displayPath(room)\nend\n\n-- USER_GROUP_KILLED - Salle 01\n-- \nfunction event_1505_20040(room)\n    displayPath(room)\nend\n\n-- USER_GROUP_KILLED - Salle 02\n-- \nfunction event_1505_20041(room)\n    displayPath(room)\nend\n\n-- USER_GROUP_KILLED - Salle 03\n-- \nfunction event_1505_20042(room)\n    displayPath(room)\nend\n\n-- USER_GROUP_KILLED - Salle 04 - BOSS\n-- \nfunction event_1505_20043(room)\n    displayPath(room)\nend\n\n-- Déplace le joueur vers la salle suivante\n-- \nfunction event_1505_20044()\n    \nend\n\n-- [EVENT] Victoire - BOSS - Cinématique Mercenaire\n-- \nfunction event_1505_19898()\n    \t----------------------------- RECUPERATIONS DES INFOS JOUEUR --------------------------\r\n    \r\n    \tlocal playerId = Context.getLeaderId()\r\n    \tlocal playerX, playerY, playerZ = Mobile.getMobilePosition(playerId)\r\n    \r\n    \r\n    \t----------------------------- INITIALISATION DES PNJ --------------------------\r\n    \r\n    \tlocal apsTransfo = -1478031420\r\n    \tlocal moogrrRoyale = createActor(121802271, -59, 0, 0, 8, 1, 7)\r\n    \r\n    \tlocal mobileMoorghueurite = createActor(121801221, -60, 0, 0, 8, 1, 7)\r\n    \r\n    \t----------------------------- DEBUT DE CINEMATIQUE --------------------------\r\n    \r\n    \tstartCinematicContext(1.3, playerId)\r\n    \tUI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 19898)\r\n    \r\n    \tinvoke_custom(2, 1, \"Mobile.setMobileVisible\", mobileMoorghueurite, false)\r\n    \r\n    \r\n    \t----------------------------- ACTIONS --------------------------\r\n    \r\n    \tinvoke_custom(100, 1, \"Mobile.moveMobile\", playerId, -55, 0, 0, \"Mobile.setMobileDirection\", playerId, 5)\r\n    \tinvoke_custom(1000, 1, \"Mobile.setMobileAnimation\", moogrrRoyale, \"AnimMort\")\r\n    \tinvoke_custom(2500, 1, \"Particle.addParticleSystem\", apsTransfo, -59, 0, 0)\r\n    \tinvoke_custom(2501, 1, \"Particle.addParticleSystem\", apsTransfo, -59, 0, 0)\r\n    \tinvoke_custom(2502, 1, \"Particle.addParticleSystem\", apsTransfo, -59, 0, 0)\r\n    \tinvoke_custom(2700, 1, \"Actor.deleteActor\", moogrrRoyale)\r\n    \tinvoke_custom(2800, 1, \"Mobile.setMobilePosition\", mobileMoorghueurite, -59, 0, 0)\r\n    \tinvoke_custom(3200, 1, \"Mobile.setMobileVisible\", mobileMoorghueurite, true)\r\n    \r\n    \tinvoke_custom(2500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Help\")\r\n    \r\n    \tinvoke_custom(7500, 1, \"Mobile.moveMobile\", mobileMoorghueurite, -56, 0, 0)\r\n    \tinvoke_custom(8500, 1, \"Mobile.moveMobile\", playerId, -55, 1, 0, \"Mobile.setMobileDirection\", playerId, 7)\r\n    \tinvoke_custom(10000, 1, \"Mobile.moveMobile\", mobileMoorghueurite, -40, 0, 0)\r\n    \tinvoke_custom(10000, 1, \"Mobile.setMobileDirection\", playerId, 1)\r\n    \r\n    \t----------------------------- DIALOGUES --------------------------\r\n    \r\n    \t-- ... Moorghueurite ?!\r\n    \tinvoke_custom(4500, 1, \"bubble\", playerId, \"quest.amakna.mercenary.moogrr.07.01\")\r\n    \tinvoke_custom(4500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    \r\n    \tinvoke_custom(6000, 1, \"Mobile.setMobileAnimation\", mobileMoorghueurite, \"AnimSort-CridAmoogr\")\r\n    \r\n    \tinvoke_custom(12000, 1, \"bubble\", playerId, \"quest.amakna.mercenary.moogrr.07.02\")\r\n    \tinvoke_custom(12000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmoteMarket-HausseEpaules\")\r\n    \r\n    \r\n    \t----------------------------- FIN DE CINEMATIQUE --------------------------\r\n    \r\n    \tinvoke_custom(15000, 1, \"Mobile.moveMobile\", playerId, playerX, playerY, playerZ)\r\n    \tinvoke_custom(15000, 1, \"Mobile.setMobileVisible\", mobileMoorghueurite, false)\r\n    \t\r\n    \tinvoke_custom(15050, 1, \"skipCinematic\", 19898)\nend\n\n-- [ARCHI] Apparition de l'Archimonstre\n-- \nfunction event_1505_24315()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","displayPath","event_1505_20038","event_1505_20039","event_1505_20040","event_1505_20041","event_1505_20042","event_1505_20043","event_1505_20044","event_1505_19898","event_1505_24315"],"quest_calls":[],"dialogue_calls":[]},"scenario/1506.lua":{"source":"\n\n-- [INIT] Variables Globales\n-- \nfunction event_1506_20186()\n    \nend\n\n-- [INIT] Inscription du joueur + Variables Locales\n-- \nfunction event_1506_20187()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 01\n-- \nfunction event_1506_20188()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 02\n-- \nfunction event_1506_20189()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 03\n-- \nfunction event_1506_20190()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 04 - BOSS\n-- \nfunction event_1506_20191()\n    \nend\n\n-- Déplace le joueur vers la salle suivante\n-- \nfunction event_1506_20192()\n    \nend\n\n-- [ARCHI] Apparition de l'Archimonstre\n-- \nfunction event_1506_23953()\n    \nend\n\n","functions":["event_1506_20186","event_1506_20187","event_1506_20188","event_1506_20189","event_1506_20190","event_1506_20191","event_1506_20192","event_1506_23953"],"quest_calls":[],"dialogue_calls":[]},"scenario/1507.lua":{"source":"\n\n-- [INITIALISATION] Joueur\n-- \nfunction event_1507_11709()\n    invoke(1500, 1, \"UI.openInfoDialog\",\"tooltip.Restat.PopUp.Title\", \"tooltip.Restat.PopUp\")\nend\n\n-- [INITIALISATION] Déclenchement du combat\n-- \nfunction event_1507_11710()\n    \nend\n\n-- [INITIALISATION] Déclenchement du combat contre mannequin agressif\n-- \nfunction event_1507_11843()\n    \nend\n\n-- [INITIALISATION]  combat contre mannequin agressif 100\n-- \nfunction event_1507_11849()\n    \nend\n\n-- [INITIALISATION]  combat contre mannequin agressif 200\n-- \nfunction event_1507_11850()\n    \nend\n\n-- [INITIALISATION]  combat contre mannequin agressif 300\n-- \nfunction event_1507_11851()\n    \nend\n\n-- [INITIALISATION]  combat contre mannequin agressif 400\n-- \nfunction event_1507_11852()\n    \nend\n\n","functions":["event_1507_11709","event_1507_11710","event_1507_11843","event_1507_11849","event_1507_11850","event_1507_11851","event_1507_11852"],"quest_calls":[],"dialogue_calls":[]},"scenario/1508.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\nfunction chachaTurn(id, turn)\r\n\tMobile.setMobileDirection(id, turn)\r\nend\r\n\r\n-- les fonctions où on cache\r\nfunction hideMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, false)\r\nend\r\n\r\nfunction hidePart(monsterMobileId, partName)\r\n\tMobile.setPartVisible(monsterMobileId, false, partName)\r\nend\r\n\n\n-- [INIT] Variables Globales\n-- \nfunction event_1508_20076()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_1508_11712()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 01\n-- \nfunction event_1508_20080()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 02 - BOSS\n-- \nfunction event_1508_20081()\n    \nend\n\n-- Déplace le joueur vers la salle suivante\n-- \nfunction event_1508_20082()\n    \nend\n\n-- [EVENT] Salle 01 - Pose des zones flag et application de l'état tonneaux\n-- \nfunction event_1508_20256()\n    \nend\n\n-- [EVENT] Salle 02 BOSS - Pose des zones flag\n-- \nfunction event_1508_20257()\n    \nend\n\n-- [EVENT][MERCENAIRE] ENTER_INSTANCE - Cinématique Flaqueux 1\n-- \nfunction event_1508_19780(groupMobOne, groupMobTwo, groupMobThree, groupMobFour, groupMobFive, groupMobSix, groupMobSeven, groupMobEight)\n    local playerId = Context.getLeaderId()\r\n    local bossId = createActor(122602272, -46, -24, 2, 8, 7, 4)\r\n    local flaqueuxId = createActor(122601633, -45, -10, 0, 8, 7, 4)\r\n    local apsDeferlante = -1949064181\r\n    \r\n    -- Position Player : -47, -10, 0\r\n    \r\n    Mobile.addMobileCreationCallback(groupMobOne, \"hideMonster\", groupMobOne)\r\n    Mobile.addMobileCreationCallback(groupMobTwo, \"hideMonster\", groupMobTwo)\r\n    Mobile.addMobileCreationCallback(groupMobThree, \"hideMonster\", groupMobThree)\r\n    Mobile.addMobileCreationCallback(groupMobFour, \"hideMonster\", groupMobFour)\r\n    Mobile.addMobileCreationCallback(groupMobFive, \"hideMonster\", groupMobFive)\r\n    Mobile.addMobileCreationCallback(groupMobSix, \"hideMonster\", groupMobSix)\r\n    Mobile.addMobileCreationCallback(groupMobSeven, \"hideMonster\", groupMobSeven)\r\n    Mobile.addMobileCreationCallback(groupMobEight, \"hideMonster\", groupMobEight)\r\n    \r\n    startCinematicContext(1.4, bossId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 19780)\r\n    \r\n    invoke_custom(0001, 1, \"Mobile.setMobileAnimation\", bossId, \"AnimComp-Dormir-Boucle\")\r\n    -- **Où nous mène la cruauté des Taures ? Quel espoir reste-t-il pour notre peuple ?\r\n    invoke_custom(1500, 1, \"bubble\", bossId, \"quest.sufokia.mercenary.flaqueux.05.01\")\r\n    invoke_custom(5500, 1, \"clearBubbles\", bossId)\r\n    \r\n    -- **Percimol, qu'aurais-tu fait ?\r\n    invoke_custom(6000, 1, \"bubble\", bossId, \"quest.sufokia.mercenary.flaqueux.05.02\")\r\n    \r\n    invoke_custom(9500, 1, \"clearBubbles\", bossId)\r\n    invoke_custom(9500, 1, \"Camera.attachCameraToMobile\", playerId)\r\n    invoke_custom(9500, 1, \"Mobile.moveMobile\", flaqueuxId, -45, -20, 0)\r\n    invoke_custom(9500, 1, \"Mobile.moveMobile\", playerId, -47, -19, 0)\r\n    invoke_custom(10500, 1, \"Mobile.setMobileAnimation\", bossId, \"AnimComp-Dormir-Fin\")\r\n    \r\n    -- Qui va là ?\r\n    invoke_custom(11500, 1, \"bubble\", bossId, \"quest.sufokia.mercenary.flaqueux.05.03\")\r\n    invoke_custom(11500, 1, \"Mobile.moveMobile\", bossId, -46, -23, 2)\r\n    \r\n    -- Flaque Royale ! Je dois te parler !\r\n    invoke_custom(12000, 1, \"bubble\", flaqueuxId, \"quest.sufokia.mercenary.flaqueux.05.04\")\r\n    invoke_custom(1400, 1, \"clearBubbles\", flaqueuxId)\r\n    \r\n    -- La tyrannie des Taures a suffisamment duré. Nous devons partir de Sufokia...\r\n    invoke_custom(14000, 1, \"bubble\", flaqueuxId, \"quest.sufokia.mercenary.flaqueux.05.05\")\r\n    invoke_custom(18000, 1, \"clearBubbles\", flaqueuxId)\r\n    \r\n    -- Je suis venu chercher ton aide, tu es notre plus vaillante guerrière !\r\n    invoke_custom(18500, 1, \"bubble\", flaqueuxId, \"quest.sufokia.mercenary.flaqueux.05.06\")\r\n    invoke_custom(21500, 1, \"clearBubbles\", flaqueuxId)\r\n    \r\n    -- Tu veux faire un exode et partir à l'inconnu ? C'est très dangereux, et puis, que feras-tu des représailles des Taures ?\r\n    invoke_custom(22000, 1, \"Camera.attachCameraToMobile\", bossId)\r\n    invoke_custom(22000, 1, \"Mobile.setMobileAnimation\", bossId, \"AnimComp01\")\r\n    invoke_custom(22000, 1, \"bubble\", bossId, \"quest.sufokia.mercenary.flaqueux.05.07\")\r\n    \r\n    -- Nous sommes un peuple pacifiste, et non un peuple de guerriers...\r\n    invoke_custom(26500, 1, \"bubble\", bossId, \"quest.sufokia.mercenary.flaqueux.05.08\")\r\n    invoke_custom(29500, 1, \"clearBubbles\", bossId)\r\n    \r\n    -- Les enfants, et les anciens... Nos familles ne savent pas se battre.\r\n    invoke_custom(30000, 1, \"bubble\", bossId, \"quest.sufokia.mercenary.flaqueux.05.09\")\r\n    invoke_custom(34000, 1, \"clearBubbles\", bossId)\r\n    \r\n    -- Doivent-ils être sacrifiés ? Pourras-tu tous les défendre face aux Taures ?\r\n    invoke_custom(34500, 1, \"bubble\", bossId, \"quest.sufokia.mercenary.flaqueux.05.10\")\r\n    invoke_custom(38000, 1, \"clearBubbles\", bossId)\r\n    \r\n    -- Nous ne pouvons pas rester les bras croisés à ne rien faire ! Et nous pouvons compter sur de l'aide extérieure...\r\n    invoke_custom(40000, 1, \"bubble\", flaqueuxId, \"quest.sufokia.mercenary.flaqueux.05.11\")\r\n    invoke_custom(45000, 1, \"clearBubbles\", flaqueuxId)\r\n    \r\n    -- Tu es beaucoup trop jeune. En tant que chef du village, je ne peux pas aller contre mes responsabilités.\r\n    invoke_custom(46500, 1, \"bubble\", bossId, \"quest.sufokia.mercenary.flaqueux.05.12\")\r\n    invoke_custom(50000, 1, \"clearBubbles\", bossId)\r\n    \r\n    -- Mon devoir est de protéger mon peuple.\r\n    invoke_custom(50500, 1, \"bubble\", bossId, \"quest.sufokia.mercenary.flaqueux.05.13\")\r\n    invoke_custom(53000, 1, \"clearBubbles\", bossId)\r\n    invoke_custom(53000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Non\")\r\n    \r\n    -- Même si cela implique de détrousser tous les aventuriers qui rentrent dans la Jungle ? Je croyais que vous étiez pacifistes.\r\n    invoke_custom(54000, 1, \"bubble\", playerId, \"quest.sufokia.mercenary.flaqueux.05.14\")\r\n    invoke_custom(56000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Pointer\")\r\n    invoke_custom(59000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- Le monde n'est pas tout blanc ou tout noir, aventuri{[1*]?ère:er}.\r\n    invoke_custom(59000, 1, \"bubble\", bossId, \"quest.sufokia.mercenary.flaqueux.05.15\")\r\n    invoke_custom(61500, 1, \"clearBubbles\", bossId)\r\n    \r\n    -- Tu penses pouvoir tout arranger avec la force brute ? Tu ne serais pas différent{[1*]?e:} des Taures !\r\n    invoke_custom(62000, 1, \"bubble\", bossId, \"quest.sufokia.mercenary.flaqueux.05.16\")\r\n    invoke_custom(65000, 1, \"clearBubbles\", bossId)\r\n    \r\n    -- Je vous aurai prévenus ! Si vous voulez mettre en péril le village, il faudra me passer sur le corps !\r\n    invoke_custom(66000, 1, \"bubble\", bossId, \"quest.sufokia.mercenary.flaqueux.05.17\")\r\n    invoke_custom(70000, 1, \"clearBubbles\", bossId)\r\n    \r\n    -- Mais...\r\n    invoke_custom(71000, 1, \"bubble\", flaqueuxId, \"quest.sufokia.mercenary.flaqueux.05.18\")\r\n    \r\n    -- Je ne veux plus entendre parler de cette histoire. La prochaine fois que nous nous verrons...\r\n    invoke_custom(72000, 1, \"bubble\", bossId, \"quest.sufokia.mercenary.flaqueux.05.19\")\r\n    invoke_custom(72000, 1, \"Mobile.setMobileAnimation\", bossId, \"AnimSort-GrosSort\")\r\n    invoke_custom(72500, 1, \"clearBubbles\", flaqueuxId)\r\n    invoke_custom(73000, 1, \"Effect.createCameraShakeEffect\", 1000, 500, 1000, 1)\r\n    -- (on invoque des APS autour de la petite plateforme du boss)\r\n    invoke_custom(73000, 1, \"Particle.addParticleSystem\", apsDeferlante, -48, -25, 0)\r\n    invoke_custom(73000, 1, \"Particle.addParticleSystem\", apsDeferlante, -44, -25, 0)\r\n    invoke_custom(73100, 1, \"Particle.addParticleSystem\", apsDeferlante, -48, -24, 0)\r\n    invoke_custom(73100, 1, \"Particle.addParticleSystem\", apsDeferlante, -44, -24, 0)\r\n    invoke_custom(73200, 1, \"Particle.addParticleSystem\", apsDeferlante, -48, -23, 0)\r\n    invoke_custom(73200, 1, \"Particle.addParticleSystem\", apsDeferlante, -44, -23, 0)\r\n    invoke_custom(73300, 1, \"Particle.addParticleSystem\", apsDeferlante, -48, -22, 0)\r\n    invoke_custom(73300, 1, \"Particle.addParticleSystem\", apsDeferlante, -44, -22, 0)\r\n    invoke_custom(73400, 1, \"Particle.addParticleSystem\", apsDeferlante, -45, -22, 0)\r\n    invoke_custom(73400, 1, \"Particle.addParticleSystem\", apsDeferlante, -46, -22, 0)\r\n    invoke_custom(73500, 1, \"Particle.addParticleSystem\", apsDeferlante, -47, -22, 0)\r\n    \r\n    -- ... l'affrontement sera inévitable.\r\n    invoke_custom(76000, 1, \"bubble\", playerId, \"quest.sufokia.mercenary.flaqueux.05.20\")\r\n    invoke_custom(76000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    \r\n    ----------------------------------\r\n    \r\n    invoke(79000, 1, \"skipCinematic\", 19780)\nend\n\n-- [EVENT][MERCENAIRE] Fin Cinématique Flaqueux 1 - TP devant le donjon + Validation (ACH 4234 OBJ 8744)\n-- \nfunction event_1508_19781()\n    \nend\n\n-- [EVENT][MERCENAIRE] ENTER_INSTANCE - Cinématique Flaqueux 2\n-- \nfunction event_1508_19793(groupMobOne, groupMobTwo, groupMobThree, groupMobFour, groupMobFive, groupMobSix, groupMobSeven, groupMobEight)\n    local playerId = Context.getLeaderId()\r\n    local bossId = createActor(122602272, -49, -17, 0, 8, 1, 4)\r\n    local apsDeferlante = -1949064151\r\n    local apsFinish = 1012321\r\n    \r\n    -- Position Player : -43 -17 0\r\n    \r\n    Mobile.addMobileCreationCallback(groupMobOne, \"hideMonster\", groupMobOne)\r\n    Mobile.addMobileCreationCallback(groupMobTwo, \"hideMonster\", groupMobTwo)\r\n    Mobile.addMobileCreationCallback(groupMobThree, \"hideMonster\", groupMobThree)\r\n    Mobile.addMobileCreationCallback(groupMobFour, \"hideMonster\", groupMobFour)\r\n    Mobile.addMobileCreationCallback(groupMobFive, \"hideMonster\", groupMobFive)\r\n    Mobile.addMobileCreationCallback(groupMobSix, \"hideMonster\", groupMobSix)\r\n    Mobile.addMobileCreationCallback(groupMobSeven, \"hideMonster\", groupMobSeven)\r\n    Mobile.addMobileCreationCallback(groupMobEight, \"hideMonster\", groupMobEight)\r\n    \r\n    startCinematicContext(1.4, bossId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 19793)\r\n    \r\n    invoke_custom(0001, 1, \"Mobile.moveMobile\", playerId, -44, -17, 0, \"Mobile.setMobileDirection\", playerId, 5)\r\n    invoke_custom(1500, 1, \"Mobile.setMobileAnimation\", bossId, \"AnimSort-GrosSort\")\r\n    invoke_custom(2500, 1, \"Effect.createCameraShakeEffect\", 1000, 3000, 1000, 1)\r\n    invoke_custom(2500, 1, \"Particle.addParticleSystem\", apsDeferlante, -47, -16, 0)\r\n    invoke_custom(3500, 1, \"Particle.addParticleSystem\", apsDeferlante, -46, -18, 0)\r\n    invoke_custom(4500, 1, \"Particle.addParticleSystem\", apsDeferlante, -45, -15,0)\r\n    invoke_custom(5000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimCombat-Entree\")\r\n    invoke_custom(5500, 1, \"Particle.addParticleSystem\", apsDeferlante, -44, -17, 0)\r\n    invoke_custom(5700, 1, \"Mobile.setMobileVisible\", playerId, false)\r\n    invoke_custom(5700, 1, \"Mobile.moveMobile\", playerId, -50, -17, 0, \"Mobile.setMobileDirection\", playerId, 1)\r\n    invoke_custom(6500, 1, \"Particle.addParticleSystem\", apsDeferlante, -44, -17, 0)\r\n    \r\n    invoke_custom(8200, 1, \"Mobile.setMobileVisible\", playerId, true)\r\n    invoke_custom(8200, 1, \"Mobile.setMobileDirection\", playerId, 1)\r\n    invoke_custom(8200, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimCombat-Sortie-Win\")\r\n    \r\n    invoke_custom(8500, 1, \"Mobile.setMobileDirection\", bossId, 5)\r\n    invoke_custom(8700, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimSort-Pousse\")\r\n    invoke_custom(9300, 1, \"Particle.addParticleSystem\", apsFinish, -49, -17, 0)\r\n    invoke_custom(9300, 1, \"Mobile.setMobileAnimation\", bossId, \"AnimMort\")\r\n    invoke_custom(10000, 1, \"Mobile.setMobileAnimation\", bossId, \"AnimStatique02-1\")\r\n    \r\n    \r\n    -- Hufff… Je reconnais ta force.\r\n    invoke_custom(10500, 1, \"bubble\", bossId, \"quest.sufokia.mercenary.flaqueux.06.02\")\r\n    invoke_custom(14500, 1, \"clearBubbles\", bossId)\r\n    \r\n    -- La magie des vagues Sufokiennes que je maîtrise n’a pas suffi…\r\n    invoke_custom(15500, 1, \"bubble\", bossId, \"quest.sufokia.mercenary.flaqueux.06.03\")\r\n    invoke_custom(20500, 1, \"clearBubbles\", bossId)\r\n    \r\n    -- La magie des vagues ?\r\n    invoke_custom(21000, 1, \"bubble\", playerId, \"quest.sufokia.mercenary.flaqueux.06.04\")\r\n    invoke_custom(24500, 1, \"clearBubbles\", playerId)\r\n    invoke_custom(25500, 1, \"Mobile.setMobileAnimation\", bossId, \"AnimSort-Resurrection-1\")\r\n    invoke_custom(26500, 1, \"Mobile.setMobileAnimation\", bossId, \"AnimStatique\")\r\n    \r\n    -- Je ne suis pas une Flaqueuse, mais une Flaque. Une sorte d’espèce cousine.\r\n    invoke_custom(28500, 1, \"bubble\", bossId, \"quest.sufokia.mercenary.flaqueux.06.05\")\r\n    invoke_custom(30000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Effrayee\")\r\n    invoke_custom(34000, 1, \"clearBubbles\", bossId)\r\n    \r\n    -- J’ai toujours vécu ici à Sufokia… Depuis des siècles.\r\n    invoke_custom(35000, 1, \"bubble\", bossId, \"quest.sufokia.mercenary.flaqueux.06.06\")\r\n    invoke_custom(40000, 1, \"clearBubbles\", bossId)\r\n    \r\n    -- Toute seule.\r\n    invoke_custom(40500, 1, \"bubble\", bossId, \"quest.sufokia.mercenary.flaqueux.06.07\")\r\n    invoke_custom(43000, 1, \"clearBubbles\", bossId)\r\n    \r\n    -- Je ne fais pas partie de la vraie tribu des Flaqueux.\r\n    invoke_custom(44000, 1, \"bubble\", bossId, \"quest.sufokia.mercenary.flaqueux.06.08\")\r\n    invoke_custom(49500, 1, \"clearBubbles\", bossId)\r\n    \r\n    -- La plupart des Flaqueux d’ici viennent d’Amakna…\r\n    invoke_custom(50000, 1, \"bubble\", bossId, \"quest.sufokia.mercenary.flaqueux.06.09\")\r\n    invoke_custom(55500, 1, \"clearBubbles\", bossId)\r\n    \r\n    -- Ils se sont dispersés à cause des récents combats contre Ogrest qui ont impacté Amakna, et beaucoup sont venus s'installer sur cette falaise.\r\n    invoke_custom(56000, 1, \"bubble\", bossId, \"quest.sufokia.mercenary.flaqueux.06.10\")\r\n    invoke_custom(64000, 1, \"clearBubbles\", bossId)\r\n    \r\n    -- Nous avons construits des bicoques, nous avons planté des pommiers ensemble…\r\n    invoke_custom(65000, 1, \"bubble\", bossId, \"quest.sufokia.mercenary.flaqueux.06.11\")\r\n    invoke_custom(71500, 1, \"clearBubbles\", bossId)\r\n    \r\n    -- Je ne fais pas partie de leur espèce, mais ils m’ont quand même acceptée.\r\n    invoke_custom(72000, 1, \"bubble\", bossId, \"quest.sufokia.mercenary.flaqueux.06.12\")\r\n    invoke_custom(78000, 1, \"clearBubbles\", bossId)\r\n    \r\n    -- C’est pourquoi je voulais les défendre à tout prix…\r\n    invoke_custom(78500, 1, \"bubble\", bossId, \"quest.sufokia.mercenary.flaqueux.06.13\")\r\n    invoke_custom(83500, 1, \"clearBubbles\", bossId)\r\n    \r\n    -- Je ne suis pas de nature peureuse comme les Flaqueux, mais je suis quand même terrifiée à l’idée de perdre mes premiers amis…\r\n    invoke_custom(84000, 1, \"bubble\", bossId, \"quest.sufokia.mercenary.flaqueux.06.14\")\r\n    invoke_custom(92000, 1, \"clearBubbles\", bossId)\r\n    \r\n    -- Vous êtes devenue largement assez puissante pour protéger votre peuple.\r\n    invoke_custom(93000, 1, \"bubble\", playerId, \"quest.sufokia.mercenary.flaqueux.06.15\")\r\n    invoke_custom(99000, 1, \"clearBubbles\", playerId)\r\n    invoke_custom(93000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmoteMarket-DoIt\")\r\n    \r\n    -- Boutez les Taures hors de Sufokia, ou demandez à des Mercenaires de s’en occuper.\r\n    invoke_custom(99500, 1, \"bubble\", playerId, \"quest.sufokia.mercenary.flaqueux.06.16\")\r\n    invoke_custom(104500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- C’est ici, chez vous, maintenant.\r\n    invoke_custom(105000, 1, \"bubble\", playerId, \"quest.sufokia.mercenary.flaqueux.06.17\")\r\n    invoke_custom(110000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- Il est temps pour vous de vous défendre par vous-mêmes.\r\n    invoke_custom(111000, 1, \"bubble\", playerId, \"quest.sufokia.mercenary.flaqueux.06.18\")\r\n    invoke_custom(111000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Pouce\")\r\n    invoke_custom(118500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- Tu… as peut-être raison.\r\n    invoke_custom(119000, 1, \"bubble\", bossId, \"quest.sufokia.mercenary.flaqueux.06.19\")\r\n    invoke_custom(123000, 1, \"clearBubbles\", bossId)\r\n    \r\n    -- Je souhaite que tu me rendes un service.\r\n    invoke_custom(124000, 1, \"bubble\", bossId, \"quest.sufokia.mercenary.flaqueux.06.20\")\r\n    invoke_custom(129500, 1, \"clearBubbles\", bossId)\r\n    invoke_custom(130000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Acquiescer\")\r\n    \r\n    -- Donne cette Pom d’or aux Flaqueux…\r\n    invoke_custom(132000, 1, \"bubble\", bossId, \"quest.sufokia.mercenary.flaqueux.06.21\")\r\n    invoke_custom(137000, 1, \"clearBubbles\", bossId)\r\n    \r\n    -- Elle amplifiait ma magie de la vague.\r\n    invoke_custom(137500, 1, \"bubble\", bossId, \"quest.sufokia.mercenary.flaqueux.06.22\")\r\n    invoke_custom(143000, 1, \"clearBubbles\", bossId)\r\n    \r\n    -- Mais je n’en aurai plus besoin.\r\n    invoke_custom(144000, 1, \"bubble\", bossId, \"quest.sufokia.mercenary.flaqueux.06.23\")\r\n    invoke_custom(148000, 1, \"clearBubbles\", bossId)\r\n    \r\n    -- Je veux miser sur l’avenir.\r\n    invoke_custom(149000, 1, \"bubble\", bossId, \"quest.sufokia.mercenary.flaqueux.06.24\")\r\n    invoke_custom(153000, 1, \"clearBubbles\", bossId)\r\n    \r\n    -- Ce qu'on ne t'a pas dit, c'est que beaucoup de Flaqueux sont venus de loin pour s’installer ici.\r\n    invoke_custom(154000, 1, \"bubble\", bossId, \"quest.sufokia.mercenary.flaqueux.06.25\")\r\n    invoke_custom(161000, 1, \"clearBubbles\", bossId)\r\n    \r\n    -- Et pour certains, c’est dorénavant leur maison ! Leur village à eux !\r\n    invoke_custom(162000, 1, \"bubble\", bossId, \"quest.sufokia.mercenary.flaqueux.06.26\")\r\n    invoke_custom(168000, 1, \"clearBubbles\", bossId)\r\n    \r\n    -- Mais je comprends ceux qui souhaitent partir.\r\n    invoke_custom(168500, 1, \"bubble\", bossId, \"quest.sufokia.mercenary.flaqueux.06.27\")\r\n    invoke_custom(172500, 1, \"clearBubbles\", bossId)\r\n    \r\n    -- C’est pourquoi je leur offre cette Pom d’or, en signe de notre amitié éternelle.\r\n    invoke_custom(173000, 1, \"bubble\", bossId, \"quest.sufokia.mercenary.flaqueux.06.28\")\r\n    invoke_custom(180000, 1, \"clearBubbles\", bossId)\r\n    \r\n    ----------------------------------\r\n    \r\n    invoke(180000, 1, \"skipCinematic\", 19793)\nend\n\n-- [EVENT][MERCENAIRE] Fin Cinématique Flaqueux 2 - TP au village + Validation (ACH 4234 OBJ 8761)\n-- \nfunction event_1508_19794()\n    \nend\n\n-- [ARCHI] Apparition de l'Archimonstre\n-- \nfunction event_1508_23974()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","chachaTurn","hideMonster","hidePart","event_1508_20076","event_1508_11712","event_1508_20080","event_1508_20081","event_1508_20082","event_1508_20256","event_1508_20257","event_1508_19780","event_1508_19781","event_1508_19793","event_1508_19794","event_1508_23974"],"quest_calls":[],"dialogue_calls":[]},"scenario/1509.lua":{"source":"m_playerId = Context.getPlayer()\r\nnationId = 0\n\n-- On déplace le joueur sur la trappe\n-- \nfunction event_1509_11722()\n    UI.manageFrame(\"World\", false)\n    Mobile.onCellTransition(m_playerId, -11, -2, true, \"pathEnded\")\n    --Mobile.onPathEnded(m_playerId, \"pathEnded\")\n    \n    \n    \n    function ouvertureTrappe()\n    \tMobile.setMobileDirection(m_playerId, 7)\n    \tInteractiveElement.setAnimation(17697, \"AnimTrans_0_1\")\n    \tinvoke(300, 1, \"chutePerso\")\n    end\n    \n    function chutePerso()\n    \tMobile.setMobileAnimation(m_playerId, \"AnimIncarnam-Chute-Debut\", \"Mobile.setMobileVisible\", m_playerId, false )\n    end\n    \n    function pathEnded()\n    \tMobile.setMobileDirection(m_playerId, 7)\n    \tinvoke(300, 1, \"ouvertureTrappe\")\n    \t-- Interface Famillier\n    \tUI.setWidgetEnabled(\"petDialogDialog\", \"petCheckBox\", true)\t\n    --\tUI.manageFrame(\"World\", true)\n    end\nend\n\n-- [SORTIE] Quitter Incarnam (téléportation dans Astrub)\n-- \nfunction event_1509_11723()\n    World.setLoading(\"AnimLoading_Chute\", 2900, 0, 800, 800) -- change le loading entre les 2 mondes\r\nend\n\n-- [SORTIE] Quitter Incarnam (téléportation dans Amakna)\n-- \nfunction event_1509_11731()\n    World.setLoading(\"AnimLoading_Chute\", 2900, 0, 800, 800) -- change le loading entre les 2 mondes\r\nend\n\n-- [SORTIE] Quitter Incarnam (téléportation dans Bonta)\n-- \nfunction event_1509_11729()\n    World.setLoading(\"AnimLoading_Chute\", 2900, 0, 800, 800) -- change le loading entre les 2 mondes\r\nend\n\n-- [SORTIE] Quitter Incarnam (téléportation dans Brakmar)\n-- \nfunction event_1509_11728()\n    World.setLoading(\"AnimLoading_Chute\", 2900, 0, 800, 800) -- change le loading entre les 2 mondes\r\nend\n\n-- [SORTIE] Quitter Incarnam (téléportation dans Sufokia)\n-- \nfunction event_1509_11730()\n    World.setLoading(\"AnimLoading_Chute\", 2900, 0, 800, 800) -- change le loading entre les 2 mondes\r\nend\n\n-- [SORTIE] Quitter Incarnam (téléportation dans Capitale Riktus)\n-- \nfunction event_1509_14456()\n    World.setLoading(\"AnimLoading_Chute\", 2900, 0, 800, 800) -- change le loading entre les 2 mondes\r\nend\n\n","functions":["event_1509_11722","ouvertureTrappe","chutePerso","pathEnded","event_1509_11723","event_1509_11731","event_1509_11729","event_1509_11728","event_1509_11730","event_1509_14456"],"quest_calls":[],"dialogue_calls":[]},"scenario/1512.lua":{"source":"\n\n-- [INIT] Variables Globales\n-- \nfunction event_1512_20115()\n    \nend\n\n-- [INIT] Inscription du joueur + Variables Locales\n-- \nfunction event_1512_20116()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 01\n-- \nfunction event_1512_20117()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 02\n-- \nfunction event_1512_20118()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 03\n-- \nfunction event_1512_20119()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 04 - BOSS\n-- \nfunction event_1512_20120()\n    \nend\n\n-- Déplace le joueur vers la salle suivante\n-- \nfunction event_1512_20121()\n    \nend\n\n-- [ACH] Début du combat BOSS - Initialisation de la variable\n-- \nfunction event_1512_20294()\n    \nend\n\n-- [ACH][EVENT] Un joueur tombe KO - FAIL\n-- \nfunction event_1512_20295()\n    \nend\n\n-- [ACH][NOTIF] Aucun joueur tombe KO + Victoire des joueurs\n-- \nfunction event_1512_20296()\n    \nend\n\n-- [ARCHI] Apparition de l'Archimonstre\n-- \nfunction event_1512_23957()\n    \nend\n\n","functions":["event_1512_20115","event_1512_20116","event_1512_20117","event_1512_20118","event_1512_20119","event_1512_20120","event_1512_20121","event_1512_20294","event_1512_20295","event_1512_20296","event_1512_23957"],"quest_calls":[],"dialogue_calls":[]},"scenario/1515.lua":{"source":"function chachaTurn(id, turn)\r\n\tMobile.setMobileDirection(id, turn)\r\nend\n\n-- INITIALISATION\n-- \nfunction event_1515_11792()\n    \nend\n\n-- [INITIALISATION] Inscription du joueur\n-- \nfunction event_1515_11793(callbackPasserelle, callbackPasserelleDeux, callbackPasserelleTrois)\n    passerelle = toLong(callbackPasserelle)\r\n    passerelleDeux = toLong(callbackPasserelleDeux)\r\n    passerelleTrois = toLong(callbackPasserelleTrois)\r\n    trace(\"passerelle : \",passerelle)\r\n    trace(\"passerelleDeux : \",passerelleDeux)\r\n    trace(\"passerelleTrois : \",passerelleTrois)\r\n    if passerelle==0 then\r\n    \tWorld.setPictoAlpha(0, -34, -3, 0, 1)\r\n    elseif passerelle==1 then\r\n    \tWorld.setPictoAlpha(0, -34, -3, 1, 1)\r\n    end\r\n    \r\n    if passerelleDeux==0 then\r\n    \tWorld.setPictoAlpha(-20, -47, 18, 0, 1)\r\n    \r\n    elseif passerelle==1 then\r\n    \tWorld.setPictoAlpha(-20, -47, 18, 1, 1)\r\n    end\r\n    \r\n    if passerelleTrois==0 then\r\n    \tWorld.setPictoAlpha(-27, -20, 23, 0, 1)\r\n    elseif passerelle==1 then\r\n    \tWorld.setPictoAlpha(-27, -20, 23, 1, 1)\r\n    end\nend\n\n-- [SALLE 01] Victoire - On déverouille la porte\n-- \nfunction event_1515_11794()\n    \nend\n\n-- [SALLE 01] Victoire - La porte est ouverte\n-- \nfunction event_1515_11795()\n    \tWorld.setPictoAlpha(0, -34, -3, 1, 1000)\nend\n\n-- [SALLE 02] Victoire - On déverouille la porte\n-- \nfunction event_1515_11796()\n    \nend\n\n-- [SALLE 02] Victoire - La porte est ouverte\n-- \nfunction event_1515_11797()\n    World.setPictoAlpha(-20, -47, 18, 1, 1000)\nend\n\n-- [SALLE 03] Victoire - On déverouille la porte\n-- \nfunction event_1515_11798(bossId)\n    \nend\n\n-- [SALLE 03] Victoire - La porte est ouverte\n-- \nfunction event_1515_11799()\n    World.setPictoAlpha(-27, -20, 23, 1, 1000)\nend\n\n-- [SALLE 04] Victoire - On déverouille le tp\n-- \nfunction event_1515_11801(bossId)\n    \nend\n\n","functions":["chachaTurn","event_1515_11792","event_1515_11793","event_1515_11794","event_1515_11795","event_1515_11796","event_1515_11797","event_1515_11798","event_1515_11799","event_1515_11801"],"quest_calls":[],"dialogue_calls":[]},"scenario/1517.lua":{"source":"m_playerId = Context.getPlayer()\r\nnationId = 0\n\n-- On change l'etat de la trappe\n-- \nfunction event_1517_11813()\n    \nend\n\n-- 1 - Fin du combat\n-- \nfunction event_1517_11892()\n    \nend\n\n-- 1 - Arrivée au waypoint\n-- \nfunction event_1517_11893()\n    \nend\n\n-- 2 - Fin du combat\n-- \nfunction event_1517_11894()\n    \nend\n\n-- 2 - Arrivée au waypoint\n-- \nfunction event_1517_11895()\n    \nend\n\n-- 3 - Fin du combat\n-- \nfunction event_1517_11896()\n    \nend\n\n-- 3 - Arrivée au waypoint\n-- \nfunction event_1517_11897()\n    \nend\n\n-- 4 - Fin du combat\n-- \nfunction event_1517_11898()\n    \nend\n\n-- 4 - Arrivée au waypoint\n-- \nfunction event_1517_11899()\n    \nend\n\n-- 5 - Fin du combat\n-- \nfunction event_1517_11900()\n    \nend\n\n-- 5 - Arrivée au waypoint\n-- \nfunction event_1517_11901()\n    \nend\n\n-- 6 - Fin du combat\n-- \nfunction event_1517_11902()\n    \nend\n\n-- 6 - Arrivée au waypoint\n-- \nfunction event_1517_11903()\n    \nend\n\n","functions":["event_1517_11813","event_1517_11892","event_1517_11893","event_1517_11894","event_1517_11895","event_1517_11896","event_1517_11897","event_1517_11898","event_1517_11899","event_1517_11900","event_1517_11901","event_1517_11902","event_1517_11903"],"quest_calls":[],"dialogue_calls":[]},"scenario/1527.lua":{"source":"bubbleSteleInfoId = 0\r\nbubbleFightInfoId = 0\r\n\r\nfunction closeFightInfo()\r\n\tif (bubbleFightInfoId ~= nil  and bubbleFightInfoId ~= 0) then BubbleText.close(bubbleFightInfoId) end\r\nend\r\n\r\nfunction onFightInfoClosed()\r\n\tif (bubbleFightInfoId ~= nil  and bubbleFightInfoId ~= 0) then bubbleFightInfoId = 0 end\r\nend\r\n\r\nfunction closeSteleInfo()\r\n\tif (bubbleSteleInfoId ~= nil  and bubbleSteleInfoId ~= 0) then BubbleText.close(bubbleSteleInfoId) end\r\nend\r\n\r\nfunction onSteleInfoClosed()\r\n\tif (bubbleSteleInfoId ~= nil  and bubbleSteleInfoId ~= 0) then bubbleSteleInfoId = 0 end\r\nend\r\n\r\nfunction updateSteleInfoOverride(stateInfoId, forceDisplayUI)\r\n    local stateInfoId = tostring(stateInfoId)\r\n\r\n    if (bubbleSteleInfoId == 0) then\r\n        bubbleSteleInfoId = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_WEST\", 0, -60, false, 2147483647, true, \"interactiveBubbleDialog5\", 30000, 25000, \"onSteleInfoClosed\")\r\n    end\r\n\r\n    BubbleText.setText(bubbleSteleInfoId, stateInfoId)\r\n\r\n    if (forceDisplayUI) then BubbleText.show(bubbleSteleInfoId) end\r\nend\r\n\r\nfunction updateFightInfo(steleIntervention, shiftOne, shiftTwo, shiftThree, forceDisplayUI)\r\n\tlocal steleIntervention = toLong(steleIntervention)\r\n\tlocal shiftOne = toLong(shiftOne)\r\n\tlocal shiftTwo = toLong(shiftTwo)\r\n\tlocal shiftThree = toLong(shiftThree)\r\n\r\n\tif (bubbleFightInfoId == 0) then\r\n\t\tbubbleFightInfoId = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_WEST\", 0, -110, false, 2147483647, true, \"interactiveBubbleDialog5\", 30000, 25000, \"onFightInfoClosed\")\r\n\tend\r\n\r\n\tBubbleText.setText(bubbleFightInfoId, \"confusionhoraire.fight.player.infos\", steleIntervention, shiftOne, shiftTwo, shiftThree)\r\n\r\n\tif (forceDisplayUI) then BubbleText.show(bubbleFightInfoId) end\r\nend\n\n-- [INIT] Variables Globales\n-- \nfunction event_1527_18628()\n    \nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_1527_12020(callbackPasserelle)\n    passerelle = toLong(callbackPasserelle)\r\n    \r\n    if passerelle==0 then\r\n    \tWorld.setPictoAlpha(-1,-17,8, 1, 1)\r\n    \tWorld.setPictoAlpha(8, -34, 8, 1, 1)\r\n    \tWorld.setPictoAlpha(26, -25, -3, 1, 1)\r\n    \t\r\n    elseif passerelle==1 then\r\n    \tWorld.setPictoAlpha(-1,-17,8, 0, 1)\r\n    \tWorld.setPictoAlpha(8, -34, 8, 1, 1)\r\n    \tWorld.setPictoAlpha(26, -25, -3, 1, 1)\r\n    \t\r\n    elseif passerelle==2 then\r\n    \tWorld.setPictoAlpha(-1,-17,8, 0, 1)\r\n    \tWorld.setPictoAlpha(8, -34, 8, 0, 1)\r\n    \tWorld.setPictoAlpha(26, -25, -3, 1, 1)\r\n    \r\n    elseif passerelle==3 then\r\n    \tWorld.setPictoAlpha(-1,-17,8, 0, 1)\r\n    \tWorld.setPictoAlpha(8, -34, 8, 0, 1)\r\n    \tWorld.setPictoAlpha(26, -25, -3, 0, 1)\r\n    \r\n    end\nend\n\n-- USER_GROUP_KILLED - Salle 01\n-- \nfunction event_1527_11923()\n    World.setPictoAlpha(-1, -17, 8, 0, 1000)\nend\n\n-- USER_GROUP_KILLED - Salle 02\n-- \nfunction event_1527_11925()\n    World.setPictoAlpha(8, -34, 8, 0, 1000)\nend\n\n-- USER_GROUP_KILLED - Salle 03\n-- \nfunction event_1527_11927()\n    World.setPictoAlpha(26, -25, -3, 0, 1000)\nend\n\n-- USER_GROUP_KILLED - Salle 04 - BOSS\n-- \nfunction event_1527_11929()\n    \nend\n\n-- Déplace le joueur vers la salle suivante\n-- \nfunction event_1527_18627()\n    \nend\n\n-- [EVENT] Le joueur examine la Stèle d'intervention\n-- \nfunction event_1527_23241()\n    local steleIntervention = toLong(steleIntervention)\r\n    \r\n    UI.openRewardsDialog(\"stele.frigostdungeon.description\")\r\n    \r\n    updateSteleInfoOverride(\"stele.intervention.confusionhoraire.description\", true)\nend\n\n-- [EVENT] Activation Stèle d'Intervention\n-- \nfunction event_1527_23242()\n    local steleIntervention = toLong(steleIntervention)\r\n    \r\n    UI.openRewardsDialog(\"stele.frigostdungeon.description\")\r\n    \r\n    updateSteleInfoOverride(\"stele.intervention.confusionhoraire.description\", true)\nend\n\n-- [EVENT] Démarrage du combat - Initialisation des variables\n-- \nfunction event_1527_23243()\n    \nend\n\n-- [EVENT] Notification Etat téléfrag et décalage - Mise à jour UI infos de combats\n-- \nfunction event_1527_23244(steleIntervention, shiftOne, shiftTwo, shiftThree)\n    updateFightInfo(steleIntervention, shiftOne, shiftTwo, shiftThree, true)\nend\n\n-- [EVENT] Démarrage du combat - application état Harebourg\n-- \nfunction event_1527_23245()\n    \nend\n\n-- [EVENT] DUNGEON_DIFFICULTY_CHANGED - On désactive les états stèles\n-- \nfunction event_1527_23246()\n    local bubble = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_EAST\", -75, -100, false, 10000, true, \"interactiveBubbleDialog4\")\r\n    \r\n    BubbleText.setText(bubble, \"stele.intervention.harebourg.no.drop\")\r\n    BubbleText.show(bubble)\nend\n\n-- [EVENT] FIGHT_ENDED_IN_CLIENT - Victoire du joueur - ACH 5476\n-- \nfunction event_1527_23287()\n    \nend\n\n","functions":["closeFightInfo","onFightInfoClosed","closeSteleInfo","onSteleInfoClosed","updateSteleInfoOverride","updateFightInfo","event_1527_18628","event_1527_12020","event_1527_11923","event_1527_11925","event_1527_11927","event_1527_11929","event_1527_18627","event_1527_23241","event_1527_23242","event_1527_23243","event_1527_23244","event_1527_23245","event_1527_23246","event_1527_23287"],"quest_calls":["UI.openRewardsDialog(\"stele.frigostdungeon.description\")\r","UI.openRewardsDialog(\"stele.frigostdungeon.description\")\r"],"dialogue_calls":[]},"scenario/1528.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\nnbFight = 0\r\n\r\nbubbleSteleInfoId = 0\r\nbubbleFightInfoId = 0\r\n\r\nfunction closeFightInfo()\r\n\tif (bubbleFightInfoId ~= nil  and bubbleFightInfoId ~= 0) then BubbleText.close(bubbleFightInfoId) end\r\nend\r\n\r\nfunction onFightInfoClosed()\r\n\tif (bubbleFightInfoId ~= nil  and bubbleFightInfoId ~= 0) then bubbleFightInfoId = 0 end\r\nend\r\n\r\nfunction closeSteleInfo()\r\n\tif (bubbleSteleInfoId ~= nil  and bubbleSteleInfoId ~= 0) then BubbleText.close(bubbleSteleInfoId) end\r\nend\r\n\r\nfunction onSteleInfoClosed()\r\n\tif (bubbleSteleInfoId ~= nil  and bubbleSteleInfoId ~= 0) then bubbleSteleInfoId = 0 end\r\nend\r\n\r\nfunction updateSteleInfoOverride(stateInfoId, forceDisplayUI)\r\n    local stateInfoId = tostring(stateInfoId)\r\n\r\n    if (bubbleSteleInfoId == 0) then\r\n        bubbleSteleInfoId = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_WEST\", 0, -60, false, 2147483647, true, \"interactiveBubbleDialog5\", 30000, 25000, \"onSteleInfoClosed\")\r\n    end\r\n\r\n    BubbleText.setText(bubbleSteleInfoId, stateInfoId)\r\n\r\n    if (forceDisplayUI) then BubbleText.show(bubbleSteleInfoId) end\r\nend\r\n\r\nfunction updateFightInfo(steleIntervention, shiftOne, shiftTwo, shiftThree, forceDisplayUI)\r\n\tlocal steleIntervention = toLong(steleIntervention)\r\n\tlocal shiftOne = toLong(shiftOne)\r\n\tlocal shiftTwo = toLong(shiftTwo)\r\n\tlocal shiftThree = toLong(shiftThree)\r\n\r\n\tif (bubbleFightInfoId == 0) then\r\n\t\tbubbleFightInfoId = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_WEST\", 0, -110, false, 2147483647, true, \"interactiveBubbleDialog5\", 30000, 25000, \"onFightInfoClosed\")\r\n\tend\r\n\r\n\tBubbleText.setText(bubbleFightInfoId, \"confusionhoraire.fight.player.infos\", steleIntervention, shiftOne, shiftTwo, shiftThree)\r\n\r\n\tif (forceDisplayUI) then BubbleText.show(bubbleFightInfoId) end\r\nend\n\n-- [INIT] Variables Globales\n-- \nfunction event_1528_23265()\n    \nend\n\n-- [INIT] initialisation serveur\n-- \nfunction event_1528_11930()\n    \nend\n\n-- *[OLD][EVENT] Salle 1 - Victoire\n-- \nfunction event_1528_11933()\n    \nend\n\n-- [EVENT] Salle 2 - Victoire\n-- \nfunction event_1528_11935()\n    \nend\n\n-- [EVENT] Salle 3 - Victoire\n-- \nfunction event_1528_11937()\n    \nend\n\n-- [EVENT] Salle 4 - Victoire\n-- \nfunction event_1528_11939()\n    \nend\n\n-- [EVENT] Le joueur trouve le bon livre - Lancement Cinématique\n-- \nfunction event_1528_20433()\n    local playerId = Context.getLeaderId()\r\n    \r\n    startCinematicContext(1.5, playerId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 20433)\r\n    \r\n    invoke_custom(01200, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Victoire\")\r\n    \r\n    -- \"J'ai trouvé le bon livre !\"\r\n    invoke_custom(01500, 1, \"bubble\", playerId, \"quest.pandalousie.02.01\")\r\n    invoke_custom(05000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"J'étais tellement occupé{[1*]?e:} que je n'ai pas vu les Mékas approcher...\"\r\n    invoke_custom(06000, 1, \"Mobile.setMobileDirection\", playerId, 3)\r\n    invoke_custom(06000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Efrayee\")\r\n    invoke_custom(06000, 1, \"bubble\", playerId, \"quest.pandalousie.02.02\")\r\n    invoke_custom(12000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(12500, 1, \"skipCinematic\", 20433)\nend\n\n-- [EVENT] Cinématique terminée - On lance le combat de monstres (Mékas optimisés)\n-- \nfunction event_1528_20434()\n    \nend\n\n-- [EVENT] Combat de monstres (Méka) - Début\n-- \nfunction event_1528_20435(local_meka_fight_id)\n    \nend\n\n-- [EVENT] Fin du combat - Cinématique et validation de la quête (ACH 4661 OBJ 9584)\n-- \nfunction event_1528_20436(local_meka_fight_id)\n    local playerId = Context.getLeaderId()\r\n    \r\n    startCinematicContext(1.5, playerId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 20436)\r\n    \r\n    invoke_custom(00100, 1, \"Mobile.setMobileDirection\", playerId, 3)\r\n    invoke_custom(01200, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Bailler\")\r\n    \r\n    -- \"Compliqué, ces combats-là...\"\r\n    invoke_custom(01500, 1, \"bubble\", playerId, \"quest.pandalousie.02.03\")\r\n    invoke_custom(05000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"J'ai trouvé le bon livre, au moins. Lisons ceci...\"\r\n    invoke_custom(06000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Lire-Debut\")\r\n    invoke_custom(06000, 1, \"bubble\", playerId, \"quest.pandalousie.02.04\")\r\n    invoke_custom(10000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"... Je vois. De la bave de Zespadon Noir...\"\r\n    invoke_custom(11000, 1, \"bubble\", playerId, \"quest.pandalousie.02.05\")\r\n    invoke_custom(14500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"... Mélangée à du sang de Tsar Tsu Tsu.\"\r\n    invoke_custom(14500, 1, \"bubble\", playerId, \"quest.pandalousie.02.06\")\r\n    invoke_custom(19000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"En route pour obtenir tout ça !\"\r\n    invoke_custom(19500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Lire-Fin\")\r\n    invoke_custom(19500, 1, \"bubble\", playerId, \"quest.pandalousie.02.07\")\r\n    invoke_custom(25000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(25500, 1, \"skipCinematic\", 20436)\nend\n\n-- [EVENT] Le joueur examine la Stèle d'intervention\n-- \nfunction event_1528_23266()\n    local steleIntervention = toLong(steleIntervention)\r\n    \r\n    UI.openRewardsDialog(\"stele.frigostdungeon.description\")\r\n    \r\n    updateSteleInfoOverride(\"stele.intervention.confusionhoraire.description\", true)\nend\n\n-- [EVENT] Activation Stèle d'Intervention\n-- \nfunction event_1528_23267()\n    local steleIntervention = toLong(steleIntervention)\r\n    \r\n    UI.openRewardsDialog(\"stele.frigostdungeon.description\")\r\n    \r\n    updateSteleInfoOverride(\"stele.intervention.confusionhoraire.description\", true)\nend\n\n-- [EVENT] Démarrage du combat - Initialisation des variables\n-- \nfunction event_1528_23268()\n    \nend\n\n-- [EVENT] Notification Etat téléfrag et décalage - Mise à jour UI infos de combats\n-- \nfunction event_1528_23269(steleIntervention, shiftOne, shiftTwo, shiftThree)\n    updateFightInfo(steleIntervention, shiftOne, shiftTwo, shiftThree, true)\nend\n\n-- [EVENT] Démarrage du combat - application état Harebourg\n-- \nfunction event_1528_23270()\n    \nend\n