eFightInfoId == 0) then\r\n\t\tbubbleFightInfoId = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_WEST\", 0, -110, false, 2147483647, true, \"interactiveBubbleDialog5\", 30000, 25000, \"onFightInfoClosed\")\r\n\tend\r\n\r\n\tBubbleText.setText(bubbleFightInfoId, \"confusionhoraire.fight.player.infos\", steleIntervention, shiftOne, shiftTwo, shiftThree)\r\n\r\n\tif (forceDisplayUI) then BubbleText.show(bubbleFightInfoId) end\r\nend\n\n-- [INIT] Variables Globales\n-- \nfunction event_1531_18447()\n    \nend\n\n-- [INIT] Inscription du joueur + Variables Locales\n-- \nfunction event_1531_18448(callbackPasserelle)\n    local state = toLong(callbackPasserelle)\r\n    \r\n    displayPath(state)\nend\n\n-- USER_GROUP_KILLED - Salle 01\n-- \nfunction event_1531_18451()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 02 - BOSS\n-- \nfunction event_1531_18452()\n    \nend\n\n-- Salle 01 - Application état\n-- \nfunction event_1531_21941()\n    \nend\n\n-- Salle 02 - Application état\n-- \nfunction event_1531_21942()\n    \nend\n\n-- Déplace le joueur vers la salle suivante\n-- \nfunction event_1531_18453()\n    \nend\n\n-- [EVENT] Le joueur examine la Stèle d'intervention\n-- \nfunction event_1531_23278()\n    local steleIntervention = toLong(steleIntervention)\r\n    \r\n    UI.openRewardsDialog(\"stele.frigostdungeon.description\")\r\n    \r\n    updateSteleInfoOverride(\"stele.intervention.confusionhoraire.description\", true)\nend\n\n-- [EVENT] Activation Stèle d'Intervention\n-- \nfunction event_1531_23279()\n    local steleIntervention = toLong(steleIntervention)\r\n    \r\n    UI.openRewardsDialog(\"stele.frigostdungeon.description\")\r\n    \r\n    updateSteleInfoOverride(\"stele.intervention.confusionhoraire.description\", true)\nend\n\n-- [EVENT] Démarrage du combat - Initialisation des variables\n-- \nfunction event_1531_23280()\n    \nend\n\n-- [EVENT] Notification Etat téléfrag et décalage - Mise à jour UI infos de combats\n-- \nfunction event_1531_23281(steleIntervention, shiftOne, shiftTwo, shiftThree)\n    updateFightInfo(steleIntervention, shiftOne, shiftTwo, shiftThree, true)\nend\n\n-- [EVENT] Démarrage du combat - application état Harebourg\n-- \nfunction event_1531_23282()\n    \nend\n\n-- [EVENT] DUNGEON_DIFFICULTY_CHANGED - On désactive les états stèles\n-- \nfunction event_1531_23283()\n    local bubble = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_EAST\", -75, -100, false, 10000, true, \"interactiveBubbleDialog4\")\r\n    \r\n    BubbleText.setText(bubble, \"stele.intervention.harebourg.no.drop\")\r\n    BubbleText.show(bubble)\nend\n\n-- [EVENT] FIGHT_ENDED_IN_CLIENT - Victoire du joueur - ACH 5476\n-- \nfunction event_1531_23290()\n    \nend\n\n-- [ARCHI] Apparition de l'Archimonstre\n-- \nfunction event_1531_23967()\n    \nend\n\n","functions":["closeFightInfo","onFightInfoClosed","closeSteleInfo","onSteleInfoClosed","updateSteleInfoOverride","updateFightInfo","event_1531_18447","event_1531_18448","event_1531_18451","event_1531_18452","event_1531_21941","event_1531_21942","event_1531_18453","event_1531_23278","event_1531_23279","event_1531_23280","event_1531_23281","event_1531_23282","event_1531_23283","event_1531_23290","event_1531_23967"],"quest_calls":["UI.openRewardsDialog(\"stele.frigostdungeon.description\")\r","UI.openRewardsDialog(\"stele.frigostdungeon.description\")\r"],"dialogue_calls":[]},"scenario/1536.lua":{"source":"bubbleSteleInfoId = 0\r\nbubbleFightInfoId = 0\r\n\r\nfunction closeFightInfo()\r\n\tif (bubbleFightInfoId ~= nil  and bubbleFightInfoId ~= 0) then BubbleText.close(bubbleFightInfoId) end\r\nend\r\n\r\nfunction onFightInfoClosed()\r\n\tif (bubbleFightInfoId ~= nil  and bubbleFightInfoId ~= 0) then bubbleFightInfoId = 0 end\r\nend\r\n\r\n\r\nfunction closeSteleInfo()\r\n\tif (bubbleSteleInfoId ~= nil  and bubbleSteleInfoId ~= 0) then BubbleText.close(bubbleSteleInfoId) end\r\nend\r\n\r\nfunction onSteleInfoClosed()\r\n\tif (bubbleSteleInfoId ~= nil  and bubbleSteleInfoId ~= 0) then bubbleSteleInfoId = 0 end\r\nend\r\n\r\nfunction updateSteleInfoOverride(stateInfoId, forceDisplayUI)\r\n    local stateInfoId = tostring(stateInfoId)\r\n\r\n    if (bubbleSteleInfoId == 0) then\r\n        bubbleSteleInfoId = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_WEST\", 0, -60, false, 2147483647, true, \"interactiveBubbleDialog5\", 30000, 25000, \"onSteleInfoClosed\")\r\n    end\r\n\r\n    BubbleText.setText(bubbleSteleInfoId, stateInfoId)\r\n\r\n    if (forceDisplayUI) then BubbleText.show(bubbleSteleInfoId) end\r\nend\r\n\r\nfunction updateFightInfo(steleIntervention, shiftOne, shiftTwo, shiftThree, forceDisplayUI)\r\n\tlocal steleIntervention = toLong(steleIntervention)\r\n\tlocal shiftOne = toLong(shiftOne)\r\n\tlocal shiftTwo = toLong(shiftTwo)\r\n\tlocal shiftThree = toLong(shiftThree)\r\n\r\n\tif (bubbleFightInfoId == 0) then\r\n\t\tbubbleFightInfoId = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_WEST\", 0, -110, false, 2147483647, true, \"interactiveBubbleDialog5\", 30000, 25000, \"onFightInfoClosed\")\r\n\tend\r\n\r\n\tBubbleText.setText(bubbleFightInfoId, \"confusionhoraire.fight.player.infos\", steleIntervention, shiftOne, shiftTwo, shiftThree)\r\n\r\n\tif (forceDisplayUI) then BubbleText.show(bubbleFightInfoId) end\r\nend\n\n-- [INIT] Variables Globales\n-- \nfunction event_1536_18499()\n    \nend\n\n-- [INIT] Inscription du joueur + Variables Locales\n-- \nfunction event_1536_18500(callbackPasserelle)\n    local state = toLong(callbackPasserelle)\r\n    \r\n    displayPath(state)\nend\n\n-- USER_GROUP_KILLED - Salle 01\n-- \nfunction event_1536_18501()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 02\n-- \nfunction event_1536_18502()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 03\n-- \nfunction event_1536_18503()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 04 - BOSS\n-- \nfunction event_1536_18504()\n    \nend\n\n-- Déplace le joueur vers la salle suivante\n-- \nfunction event_1536_18505()\n    \nend\n\n-- FIGHT_ENTER_ACTION_PHASE - Applique l'état \"Donjon\" (Salle 1)\n-- \nfunction event_1536_21923()\n    \nend\n\n-- [EVENT] Le joueur examine la Stèle d'intervention\n-- \nfunction event_1536_23259()\n    local steleIntervention = toLong(steleIntervention)\r\n    \r\n    UI.openRewardsDialog(\"stele.frigostdungeon.description\")\r\n    \r\n    updateSteleInfoOverride(\"stele.intervention.confusionhoraire.description\", true)\nend\n\n-- [EVENT] Activation Stèle d'Intervention\n-- \nfunction event_1536_23260()\n    local steleIntervention = toLong(steleIntervention)\r\n    \r\n    UI.openRewardsDialog(\"stele.frigostdungeon.description\")\r\n    \r\n    updateSteleInfoOverride(\"stele.intervention.confusionhoraire.description\", true)\nend\n\n-- [EVENT] Démarrage du combat - Initialisation des variables\n-- \nfunction event_1536_23261()\n    \nend\n\n-- [EVENT] Notification Etat téléfrag et décalage - Mise à jour UI infos de combats\n-- \nfunction event_1536_23262(steleIntervention, shiftOne, shiftTwo, shiftThree)\n    updateFightInfo(steleIntervention, shiftOne, shiftTwo, shiftThree, true)\nend\n\n-- [EVENT] Démarrage du combat - application état Harebourg\n-- \nfunction event_1536_23263()\n    \nend\n\n-- [EVENT] DUNGEON_DIFFICULTY_CHANGED - On désactive les états stèles\n-- \nfunction event_1536_23264()\n    local bubble = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_EAST\", -75, -100, false, 10000, true, \"interactiveBubbleDialog4\")\r\n    \r\n    BubbleText.setText(bubble, \"stele.intervention.harebourg.no.drop\")\r\n    BubbleText.show(bubble)\nend\n\n-- [EVENT] FIGHT_ENDED_IN_CLIENT - Victoire du joueur - ACH 5476\n-- \nfunction event_1536_23288()\n    \nend\n\n","functions":["closeFightInfo","onFightInfoClosed","closeSteleInfo","onSteleInfoClosed","updateSteleInfoOverride","updateFightInfo","event_1536_18499","event_1536_18500","event_1536_18501","event_1536_18502","event_1536_18503","event_1536_18504","event_1536_18505","event_1536_21923","event_1536_23259","event_1536_23260","event_1536_23261","event_1536_23262","event_1536_23263","event_1536_23264","event_1536_23288"],"quest_calls":["UI.openRewardsDialog(\"stele.frigostdungeon.description\")\r","UI.openRewardsDialog(\"stele.frigostdungeon.description\")\r"],"dialogue_calls":[]},"scenario/1537.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\nfunction hideMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, false)\r\nend\r\n\r\nfunction showMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, true)\r\nend\n\n-- [INIT] Variables\n-- \nfunction event_1537_12277()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_1537_11983(npcId, bossId, doorOpened)\n    local doorOpened = toLong(doorOpened)\r\n    \r\n    if (doorOpened == 1) then\r\n    \tMobile.addMobileCreationCallback(npcId, \"hideMonster\", npcId)\r\n    else\r\n    \tMobile.addMobileCreationCallback(bossId, \"hideMonster\", bossId)\r\n    end\nend\n\n-- FIGHT_ENTER_ACTION_PHASE - Pose des glyphes\n-- \nfunction event_1537_19740()\n    \nend\n\n-- FIGHT_STARTED - Actions de début de combat\n-- \nfunction event_1537_22005()\n    \nend\n\n-- DIALOG_EXECUTED - Apparition du vrai CN\n-- \nfunction event_1537_22009(bossId, npcId)\n    function customSkip()\r\n    \tUI.displayWideScreenBand(true, 25, 300)\r\n    \tMobile.setMobileVisible(npcId, false)\r\n    \tMobile.setMobileVisible(bossId, true)\r\n    \tskipCinematic()\r\n    end\r\n        \t\r\n    startCinematicContext(1.2, npcId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"customSkip\")\r\n    \r\n    -- \"Bougez pas, je reviens !\"\r\n    invoke_custom(00500, 1, \"Sound.playSound\", 310101101151303, true, 40)\r\n    invoke_custom(00500, 1, \"bubble\", npcId, \"black.crow.fight.02\")\r\n    invoke_custom(03000, 1, \"clearBubbles\", npcId)\r\n    \r\n    invoke_custom(03000, 1, \"UI.displayWideScreenBand\", true, 100, 300)\r\n    invoke_custom(05000, 1, \"Mobile.setMobileVisible\", npcId, false)\r\n    invoke_custom(05000, 1, \"Mobile.setMobileVisible\", bossId, true)\r\n    invoke_custom(05000, 1, \"Camera.attachCameraToMobile\", bossId)\r\n    \r\n    invoke_custom(05500, 1, \"UI.displayWideScreenBand\", true, 25, 300)\r\n    invoke_custom(05500, 1, \"Mobile.setMobileAnimation\", bossId, \"AnimSort-Envol-Fin\")\r\n    \r\n    -- \"Vous allez bientôt pouvoir rencontrer votre créateur...\"\r\n    invoke_custom(06000, 1, \"Sound.playSound\", 320001020007011, true, 40)\r\n    invoke_custom(06000, 1, \"bubble\", bossId, \"black.crow.fight.01\")\r\n    invoke_custom(09000, 1, \"clearBubbles\", bossId)\r\n    \r\n    invoke_custom(09000, 1, \"skipCinematic\")\nend\n\n-- CLIENT_TRIGGERED_EVENT - On skip chez tout le monde\n-- \nfunction event_1537_22011(npcId, bossId)\n    UI.displayWideScreenBand(true, 25, 300)\r\n    Mobile.setMobileVisible(npcId, false)\r\n    Mobile.setMobileVisible(bossId, true)\r\n    skipCinematic()\nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","hideMonster","showMonster","event_1537_12277","event_1537_11983","event_1537_19740","event_1537_22005","event_1537_22009","customSkip","event_1537_22011"],"quest_calls":[],"dialogue_calls":[]},"scenario/1539.lua":{"source":"\n\n-- [INITIALISATION] Serveur\n-- \nfunction event_1539_12003()\n    \nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_1539_11996()\n    \nend\n\n-- [INIT] Spawn de l'Assistant de Nileza\n-- \nfunction event_1539_12006()\n    \nend\n\n-- [SCENE] Quête 5 Activation - Spawn du Slimsis Poreux\n-- \nfunction event_1539_12007()\n    \nend\n\n-- [SCENE] Quête 5 Validation\n-- \nfunction event_1539_12008(poreuxID)\n    Particle.addParticleSystemToTarget(800174,poreuxID,0)\nend\n\n-- [SCENE] Ouverture du coffre 01\n-- \nfunction event_1539_11997()\n    \nend\n\n-- [SCENE] Ouverture du coffre 02\n-- \nfunction event_1539_11998()\n    \nend\n\n-- [SCENE] Ouverture du coffre 03\n-- \nfunction event_1539_11999()\n    \nend\n\n-- [SCENE] Ouverture du coffre\n-- \nfunction event_1539_12002()\n    \nend\n\n-- [TIMER] Diminution du Niveau du Scaphandre - Dans le monde\n-- \nfunction event_1539_12009()\n    \nend\n\n-- [TIMER] Téléportation - Dans le monde\n-- \nfunction event_1539_12010()\n    UI.displayTutorialMessage(\"quest.frigost.nileza.armor.off.title\",\"quest.frigost.nileza.armor.off\")\nend\n\n-- [TIMER] On relance le timer\n-- \nfunction event_1539_12011()\n    \nend\n\n","functions":["event_1539_12003","event_1539_11996","event_1539_12006","event_1539_12007","event_1539_12008","event_1539_11997","event_1539_11998","event_1539_11999","event_1539_12002","event_1539_12009","event_1539_12010","event_1539_12011"],"quest_calls":[],"dialogue_calls":[]},"scenario/1541.lua":{"source":"\n\n-- Initialisation serveur\n-- \nfunction event_1541_12012()\n    \nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_1541_12013()\n    \nend\n\n-- Combat 01 - Victoire\n-- \nfunction event_1541_12014()\n    \nend\n\n-- Combat 01 - Ouverture de la porte\n-- \nfunction event_1541_12015()\n    \nend\n\n-- Combat 02 - Victoire\n-- \nfunction event_1541_12016()\n    \nend\n\n-- Combat 02 - Fin de la quête\n-- \nfunction event_1541_12017()\n    \nend\n\n-- Combat 02 - Lancement\n-- \nfunction event_1541_12018(playerTriggerer)\n    trace(playerTriggerer)\nend\n\n","functions":["event_1541_12012","event_1541_12013","event_1541_12014","event_1541_12015","event_1541_12016","event_1541_12017","event_1541_12018"],"quest_calls":[],"dialogue_calls":[]},"scenario/1542.lua":{"source":"\n\n-- le joueur entre dans l'instance \n-- \nfunction event_1542_12165()\n    \nend\n\n","functions":["event_1542_12165"],"quest_calls":[],"dialogue_calls":[]},"scenario/1547.lua":{"source":"\n\n-- Variables globales\n-- \nfunction event_1547_12112()\n    \nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_1547_12053()\n    trace(\"JE SUIS INSCRIT\")\nend\n\n-- DIAL_1 recherche des informations par le joueur \n-- \nfunction event_1547_12055(Dial_1, frigostienThree)\n    trace(\"VAR 1 VALIDEE =\", Dial_1)\r\n    BubbleText.showText(frigostienThree, \"frigost.past.Frigostien.01\", 0, 60, false)\nend\n\n-- DIAL_2 recherche des informations par le joueur\n-- \nfunction event_1547_12056(Dial_2, frigostienOne)\n    trace(\"VAR 2 VALIDEE =\", Dial_2)\r\n    BubbleText.showText(frigostienOne, \"frigost.past.Frigostien.02\", 0, 60, false)\nend\n\n-- DIAL_3 recherche des informations par le joueur\n-- \nfunction event_1547_12057(Dial_3, frigostienTwo)\n    trace(\"VAR 3 VALIDEE =\", Dial_3)\r\n    BubbleText.showText(frigostienTwo, \"frigost.past.Frigostien.03\", 0, 60, false)\nend\n\n-- DIAL_4 recherche des informations par le joueur\n-- \nfunction event_1547_12058(Dial_4, frigostienFive)\n    trace(\"VAR 4 VALIDEE =\", Dial_4)\r\n    BubbleText.showText(frigostienFive, \"frigost.past.Frigostien.04\", 0, 60, false)\nend\n\n-- DIAL_5 recherche des informations par le joueur\n-- \nfunction event_1547_12059(Dial_5, frigostienFour)\n    trace(\"VAR 5 VALIDEE =\", Dial_5)\r\n    BubbleText.showText(frigostienFour, \"frigost.past.Frigostien.05\", 0, 60, false)\nend\n\n-- DIAL_6 recherche des informations par le joueur\n-- \nfunction event_1547_12060(Dial_6, frigostienSeven)\n    trace(\"VAR 6 VALIDEE =\", Dial_6)\r\n    BubbleText.showText(frigostienSeven, \"frigost.past.Frigostien.06\", 0, 60, false)\nend\n\n-- DIAL_7 recherche des informations par le joueur\n-- \nfunction event_1547_12061(Dial_7, frigostienEight)\n    trace(\"VAR 7 VALIDEE =\", Dial_7)\r\n    BubbleText.showText(frigostienEight, \"frigost.past.Frigostien.07\", 0, 60, false)\nend\n\n-- DIAL_8 recherche des informations par le joueur\n-- \nfunction event_1547_12062(Dial_8, frigostienNine)\n    trace(\"VAR 8 VALIDEE =\", Dial_8)\r\n    BubbleText.showText(frigostienNine, \"frigost.past.Frigostien.08\", 0, 60, false)\nend\n\n-- DIAL_9 recherche des informations par le joueur\n-- \nfunction event_1547_12063(Dial_9, frigostienSix)\n    trace(\"VAR 9 VALIDEE =\", Dial_9)\r\n    BubbleText.showText(frigostienSix, \"frigost.past.Frigostien.09\", 0, 60, false)\nend\n\n-- DIAL_10 recherche des informations par le joueur\n-- \nfunction event_1547_12064(Dial_10, frigostienTen)\n    trace(\"VAR 10 VALIDEE =\", Dial_10)\r\n    BubbleText.showText(frigostienTen, \"frigost.past.Frigostien.10\", 0, 60, false)\nend\n\n-- DIAL_Global recherche des informations par le joueur\n-- \nfunction event_1547_12065()\n    trace(\"QUETE VALIDEE\")\nend\n\n-- le joueur parle à père doby pour se faire téléporter dans le présent.\n-- \nfunction event_1547_12098()\n    \nend\n\n","functions":["event_1547_12112","event_1547_12053","event_1547_12055","event_1547_12056","event_1547_12057","event_1547_12058","event_1547_12059","event_1547_12060","event_1547_12061","event_1547_12062","event_1547_12063","event_1547_12064","event_1547_12065","event_1547_12098"],"quest_calls":[],"dialogue_calls":[]},"scenario/1548.lua":{"source":"function shakeCam()\r\n\tinstanceId = Context.getPlayerInstanceId()\t\r\n\tif instanceId==536 then\r\n\t\tshakeEffectId = Effect.createCameraShakeEffect(400, 600, 500, 6)\r\n\t\tinvoke(60000, 1, \"shakeCam\")\r\n\tend\r\nend\n\n-- Variables globales\n-- \nfunction event_1548_12096()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_1548_12066()\n    invoke(3000, 1, \"shakeCam\")\nend\n\n-- Déclenchement du combat contre Frizz\n-- \nfunction event_1548_12079(frizzId)\n    Particle.addParticleSystemToTarget(800174,frizzId,0)\r\n    Mobile.setMobileDirection(frizzId,5)\nend\n\n-- Missiz Frizz tue les joueurs\n-- \nfunction event_1548_12080()\n    \nend\n\n-- Le combat se termine\n-- \nfunction event_1548_12081()\n    FightEvent.addFightEndCallback(\"endFightFrizz\")\r\n    \r\n    function endFightFrizz()\r\n    \tServer.triggerEvent(12081)\r\n    end\nend\n\n-- On téléporte le joueur\n-- \nfunction event_1548_12144()\n    \nend\n\n-- Lancement du combat contre Frizz\n-- \nfunction event_1548_12095()\n    \nend\n\n","functions":["shakeCam","event_1548_12096","event_1548_12066","event_1548_12079","event_1548_12080","event_1548_12081","endFightFrizz","event_1548_12144","event_1548_12095"],"quest_calls":[],"dialogue_calls":[]},"scenario/1549.lua":{"source":"\n\n-- Retour dans le présent\n-- \nfunction event_1549_12082()\n    \nend\n\n","functions":["event_1549_12082"],"quest_calls":[],"dialogue_calls":[]},"scenario/1550.lua":{"source":"\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_1550_12083()\n    trace(\"JE SUIS INSCRIT\")\nend\n\n-- apparition du livre si quête ok \n-- \nfunction event_1550_12097()\n    trace(\"JE SUIS INSCRIT\")\nend\n\n","functions":["event_1550_12083","event_1550_12097"],"quest_calls":[],"dialogue_calls":[]},"scenario/1551.lua":{"source":"\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_1551_12100()\n    \nend\n\n-- INITIALISATION\n-- \nfunction event_1551_12109()\n    \nend\n\n-- [Combat] Lancement du Combat\n-- \nfunction event_1551_12151()\n    \nend\n\n-- [COMBAT] Check des vagues invoquées\n-- \nfunction event_1551_12108(bossTurn)\n    turn=toLong(bossTurn)\r\n    if turn==3 then\r\n    \tUI.displaySplashText(\"zeppelin.wave\", turn*100)\r\n    else\r\n    \tUI.displaySplashText(\"zeppelin.wave\", turn*100)\r\n    end\nend\n\n-- [COMBAT] Check des vagues invoquées\n-- \nfunction event_1551_12110(bossTurn)\n    turn=toLong(bossTurn)\r\n    if turn==3 then\r\n    \tUI.displaySplashText(\"zeppelin.wave\", turn*100)\r\n    else\r\n    \tUI.displaySplashText(\"zeppelin.wave\", turn*100)\r\n    end\nend\n\n-- [COMBAT] Check des vagues invoquées\n-- \nfunction event_1551_12111(bossTurn)\n    turn=toLong(bossTurn)\r\n    if turn==3 then\r\n    \tUI.displaySplashText(\"zeppelin.wave\", turn*100)\r\n    else\r\n    \tUI.displaySplashText(\"zeppelin.wave\", turn*100)\r\n    end\nend\n\n-- [COMBAT] - Victoire\n-- \nfunction event_1551_12101()\n    \nend\n\n-- [COMBAT] - Fin de la quête\n-- \nfunction event_1551_12102()\n    \nend\n\n","functions":["event_1551_12100","event_1551_12109","event_1551_12151","event_1551_12108","event_1551_12110","event_1551_12111","event_1551_12101","event_1551_12102"],"quest_calls":[],"dialogue_calls":[]},"scenario/1552.lua":{"source":"\n\n-- [INIT] Variables\n-- \nfunction event_1552_19801()\n    \nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_1552_12104()\n    \nend\n\n-- Combat Harebourg - Animation Spawn\n-- \nfunction event_1552_12107(harebourgId)\n    Mobile.setMobileAnimation(harebourgId,\"AnimApparition\")\nend\n\n-- Combat Harebourg - Lancement du combat\n-- \nfunction event_1552_12153()\n    \nend\n\n-- Combat Harebourg - Harebourg tue les joueurs : Quête Validée\n-- \nfunction event_1552_12145()\n    \nend\n\n-- Combat Harebourg - TP des joueurs à la fin du Combat\n-- \nfunction event_1552_12152(fightId)\n    \nend\n\n","functions":["event_1552_19801","event_1552_12104","event_1552_12107","event_1552_12153","event_1552_12145","event_1552_12152"],"quest_calls":[],"dialogue_calls":[]},"scenario/1553.lua":{"source":"particleId = 7504010\r\n\r\nparticleLevierAA = 0\r\nparticleLevierAB = 0\r\nparticleLevierAC = 0\r\n\r\nparticleLevierBA = 0\r\nparticleLevierBB = 0\r\nparticleLevierBC = 0\r\n\r\nparticleLevierCA = 0\r\nparticleLevierCB = 0\r\nparticleLevierCC = 0\r\n\r\nparticleLevierDA = 0\r\nparticleLevierDB = 0\r\nparticleLevierDC = 0\r\n\r\nparticleLevierEA = 0\r\nparticleLevierEB = 0\r\nparticleLevierEC = 0\r\n\r\nparticleLevierFA = 0\r\nparticleLevierFB = 0\r\nparticleLevierFC = 0\n\n-- Initialisation\n-- \nfunction event_1553_12115()\n    \nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_1553_12113()\n    \nend\n\n-- Activation - Levier 01\n-- \nfunction event_1553_12114()\n    \nend\n\n-- Affichage Particules - Levier 01\n-- \nfunction event_1553_12116()\n    particleLevierAA = Particle.addParticleSystem(particleId,-7,1,0)\r\n    particleLevierAB = Particle.addParticleSystem(particleId,-6,1,0)\r\n    particleLevierAC = Particle.addParticleSystem(particleId,-5,1,0)\nend\n\n-- Suppression Particules - Levier 01\n-- \nfunction event_1553_12117()\n    Particle.removeParticleSystem( particleLevierAA)\r\n    Particle.removeParticleSystem( particleLevierAB)\r\n    Particle.removeParticleSystem( particleLevierAC)\nend\n\n-- Activation - Levier 02\n-- \nfunction event_1553_12125()\n    \nend\n\n-- Affichage Particules - Levier 02\n-- \nfunction event_1553_12126()\n    particleLevierBA = Particle.addParticleSystem(particleId,-7,0,0)\r\n    particleLevierBB = Particle.addParticleSystem(particleId,-6,0,0)\r\n    particleLevierBC = Particle.addParticleSystem(particleId,-5,0,0)\nend\n\n-- Suppression Particules - Levier 02\n-- \nfunction event_1553_12127()\n    Particle.removeParticleSystem( particleLevierBA)\r\n    Particle.removeParticleSystem( particleLevierBB)\r\n    Particle.removeParticleSystem( particleLevierBC)\nend\n\n-- Activation - Levier 03\n-- \nfunction event_1553_12128()\n    \nend\n\n-- Affichage Particules - Levier 03\n-- \nfunction event_1553_12129()\n    particleLevierCA = Particle.addParticleSystem(particleId,-7,-1,0)\r\n    particleLevierCB = Particle.addParticleSystem(particleId,-6,-1,0)\r\n    particleLevierCC = Particle.addParticleSystem(particleId,-5,-1,0)\nend\n\n-- Suppression Particules - Levier 03\n-- \nfunction event_1553_12130()\n    Particle.removeParticleSystem( particleLevierCA)\r\n    Particle.removeParticleSystem( particleLevierCB)\r\n    Particle.removeParticleSystem( particleLevierCC)\nend\n\n-- Activation - Levier 04\n-- \nfunction event_1553_12122()\n    \nend\n\n-- Affichage Particules - Levier 04\n-- \nfunction event_1553_12123()\n    particleLevierDA = Particle.addParticleSystem(particleId,-7,-1,0)\r\n    particleLevierDB = Particle.addParticleSystem(particleId,-7,0,0)\r\n    particleLevierDC = Particle.addParticleSystem(particleId,-7,1,0)\nend\n\n-- Suppression Particules - Levier 04\n-- \nfunction event_1553_12124()\n    Particle.removeParticleSystem( particleLevierDA)\r\n    Particle.removeParticleSystem( particleLevierDB)\r\n    Particle.removeParticleSystem( particleLevierDC)\nend\n\n-- Activation - Levier 05\n-- \nfunction event_1553_12131()\n    \nend\n\n-- Affichage Particules - Levier 05\n-- \nfunction event_1553_12132()\n    particleLevierEA = Particle.addParticleSystem(particleId,-6,-1,0)\r\n    particleLevierEB = Particle.addParticleSystem(particleId,-6,0,0)\r\n    particleLevierEC = Particle.addParticleSystem(particleId,-6,1,0)\nend\n\n-- Suppression Particules - Levier 05\n-- \nfunction event_1553_12133()\n    Particle.removeParticleSystem( particleLevierEA)\r\n    Particle.removeParticleSystem( particleLevierEB)\r\n    Particle.removeParticleSystem( particleLevierEC)\nend\n\n-- Activation - Levier 06\n-- \nfunction event_1553_12134()\n    \nend\n\n-- Affichage Particules - Levier 06\n-- \nfunction event_1553_12135()\n    particleLevierFA = Particle.addParticleSystem(particleId,-5,-1,0)\r\n    particleLevierFB = Particle.addParticleSystem(particleId,-5,0,0)\r\n    particleLevierFC = Particle.addParticleSystem(particleId,-5,1,0)\nend\n\n-- Suppression Particules - Levier 06\n-- \nfunction event_1553_12136()\n    Particle.removeParticleSystem( particleLevierFA)\r\n    Particle.removeParticleSystem( particleLevierFB)\r\n    Particle.removeParticleSystem( particleLevierFC)\nend\n\n-- Ouverture de la porte\n-- \nfunction event_1553_12137()\n    \nend\n\n-- Fermeture de la porte\n-- \nfunction event_1553_12154()\n    \nend\n\n","functions":["event_1553_12115","event_1553_12113","event_1553_12114","event_1553_12116","event_1553_12117","event_1553_12125","event_1553_12126","event_1553_12127","event_1553_12128","event_1553_12129","event_1553_12130","event_1553_12122","event_1553_12123","event_1553_12124","event_1553_12131","event_1553_12132","event_1553_12133","event_1553_12134","event_1553_12135","event_1553_12136","event_1553_12137","event_1553_12154"],"quest_calls":[],"dialogue_calls":[]},"scenario/1554.lua":{"source":"playerId = Context.getPlayer()\r\n\r\nharebourgId=Mobile.generateClientMobileId()\r\n\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_1554_12118()\n    --On spawn le Comte\r\n    function harebourgCreate()\r\n    \tActor.createActor(harebourgId, 104702383, 0, 4, 4, 4)\r\n    \tMobile.setMobileDirection(harebourgId,3)\r\n    \tMobile.setMobileVisible(harebourgId,false)\r\n    end\r\n    \r\n    --On fait apparaître Harebourg\r\n    function harebourgApp()\r\n    \tMobile.setMobileVisible(harebourgId,true)\r\n    \tMobile.setMobileAnimation(harebourgId,\"AnimMouvementTeleport-Fin\")\t\r\n    end\r\n    \r\n    --On bloque les interactions du joueur\r\n    function playerInvisible()\r\n    \tMobile.setMobileVisible(playerId, false)\r\n    \tCamera.setUserZoomLocked(true)\r\n    \tCamera.setZoomFactor(1.5)\r\n    \tUI.closeMRU()\r\n    \tUI.closeAllBags()\t\t\t\t\t\t\t\t\t\t\t\t\r\n        UI.manageFrame(\"World\",false) \t\t\t\t\t\r\n    \tUI.setUIVisible(false)\t\r\n    end\r\n    \r\n    --Le Comte exulte\r\n    function harebourgTalk()\r\n    \tBubbleText.showText(harebourgId, \"frigost.harebourg.victory\", 0, 60, false)\r\n    \tinvoke(5000, 1, \"harebourgLevier\")\r\n    end\r\n    \r\n    --Il actionne des leviers\r\n    function harebourgLevier()\r\n    \tMobile.setMobileDirection(harebourgId,7)\r\n    \tMobile.setMobileAnimation(harebourgId,\"AnimSort-MiTemps\")\r\n    \tinvoke(6200,1,\"Mobile.setMobileAnimation\",harebourgId,\"AnimSort-AirDuTemps\")\r\n    \tinvoke(6200,1,\"cloudStart\")\r\n    \tinvoke(5000,1,\"shakeCam\")\r\n    \tinvoke(6200,1,\"cameraControl\")\r\n    end\r\n    \r\n    --Apparition des APS de nuage\r\n    function cloudStart()\r\n    \tParticle.addParticleSystem(7542003,-7,-9,0,0)\r\n    end\r\n    \r\n    --Tremblements de la caméra\r\n    function shakeCam()\r\n    \tinstanceId = Context.getPlayerInstanceId()\r\n    \tif instanceId==543 then\r\n    \t\tshakeEffectId = Effect.createCameraShakeEffect(400, 800, 400, 1)\r\n    \t\tSound.playSound(70500021, 60)\r\n    \tend\r\n    end\r\n    \r\n    --Traveling vers l'arrière\r\n    function cameraControl()\r\n    \tCamera.scrollTo(0,80,0)\r\n    \tCamera.setMoveSpeedFactor(0.01)\r\n    end\r\n    \r\n    harebourgCreate()\r\n    playerInvisible()\r\n    Sound.playSound(70500020, 50)\r\n    invoke(3000,1,\"harebourgApp\")\r\n    invoke(6000,1,\"harebourgTalk\")\nend\n\n-- Joueur sort de l'instance\n-- \nfunction event_1554_12139()\n    --On débloque les interactions du joueur\r\n    function configDefault()\r\n    \tCamera.setMoveSpeedFactor(1)\r\n    \tCamera.setZoomFactor(1)\r\n    \tCamera.setUserZoomLocked(false)\r\n    \tUI.manageFrame(\"World\",true) \t\t\t\t\t-- Réactive le déplacement\r\n    \tUI.setUIVisible(true)\r\n        UI.manageMRU(58, false)\t\t\t\t\t\t\t\t-- Blocage pack-unpack gelutin\r\n        --cameraClear()\t\t\t\t\t\t\t\t\t\t\t\t\t-- Appel de la fonction qui réinitialise la caméra\r\n    end\r\n    \r\n    configDefault()\nend\n\n-- Téléportation des joueurs hors de l'instance\n-- \nfunction event_1554_12141()\n    \nend\n\n","functions":["event_1554_12118","harebourgCreate","harebourgApp","playerInvisible","harebourgTalk","harebourgLevier","cloudStart","shakeCam","cameraControl","event_1554_12139","configDefault","event_1554_12141"],"quest_calls":[],"dialogue_calls":[]},"scenario/1555.lua":{"source":"soundId = 0\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_1555_12143()\n    \nend\n\n-- Réactivation des Machines\n-- \nfunction event_1555_12142()\n    Effect.createCameraShakeEffect(1000,1500,500,5,50,\"Both\")\r\n    \r\n    soundId = Sound.playSound(70500022,1,50,0)\r\n    trace(\"SoundId = \", soundId)\nend\n\n-- Combat 02 - Fin de la quête\n-- \nfunction event_1555_12148()\n    \nend\n\n-- Combat 02 - Fin de la quête\n-- \nfunction event_1555_12149()\n    \nend\n\n-- Combat 02 - Fin de la quête\n-- \nfunction event_1555_12150()\n    \nend\n\n-- Joueur quitte l'instance\n-- \nfunction event_1555_12204()\n    Sound.stopSound(soundId)\nend\n\n-- Joueur quitte l'instance\n-- \nfunction event_1555_12216()\n    Sound.stopSound(soundId)\nend\n\n","functions":["event_1555_12143","event_1555_12142","event_1555_12148","event_1555_12149","event_1555_12150","event_1555_12204","event_1555_12216"],"quest_calls":[],"dialogue_calls":[]},"scenario/1559.lua":{"source":"playerId=Context.getPlayer()\r\n\n\n-- [INITIALISATION] Variables\n-- \nfunction event_1559_12423()\n    \nend\n\n-- [INIT] Arrivée du joueur - Scène\n-- \nfunction event_1559_12181()\n    UI.manageFrame(\"World\",false)\nend\n\n-- [COMBAT] Déclenchement\n-- \nfunction event_1559_12394()\n    \nend\n\n-- [COMBAT] Placement des glyphes - Bonus\n-- \nfunction event_1559_12381()\n    invoke(200, 1, \"UI.openInfoDialog\",\"tooltip.Plant.Gelax.PopUp.Title\", \"tooltip.Plant.Gelax.PopUp\")\nend\n\n-- [COMBAT] Check des tours du boss\n-- \nfunction event_1559_12422(bossTurn)\n    turn=toLong(bossTurn)\r\n    if turn==19 then\r\n    \tUI.displaySplashText(\"shukrute.wave.last\")\r\n    else\r\n    \t--UI.displaySplashText(\"shukrute.wave.generic\", turn)\r\n    end\nend\n\n-- [COMBAT] Le joueur a réussi\n-- \nfunction event_1559_12433()\n    UI.displaySplashText(\"shukrute.victory\")\nend\n\n-- [COMBAT] Le joueur a échoué\n-- \nfunction event_1559_12441()\n    --UI.displaySplashText(\"shukrute.lost\")\r\nend\n\n-- [COMBAT] Fin du combat\n-- \nfunction event_1559_12419()\n    \nend\n\n-- [COMBAT] Placement des glyphes - Point 0\n-- \nfunction event_1559_12438()\n    \nend\n\n-- [GENERAL] Sortie de l'instance\n-- \nfunction event_1559_12461()\n    UI.manageFrame(\"World\",true)\nend\n\n-- [COMBAT] Lance-Pois invoqués\n-- \nfunction event_1559_12556()\n    \nend\n\n-- [COMBAT] Exploit - Lance-Pois invoqués\n-- \nfunction event_1559_12557()\n    \nend\n\n-- [COMBAT] Check des tours du joueur\n-- \nfunction event_1559_12558()\n    \nend\n\n","functions":["event_1559_12423","event_1559_12181","event_1559_12394","event_1559_12381","event_1559_12422","event_1559_12433","event_1559_12441","event_1559_12419","event_1559_12438","event_1559_12461","event_1559_12556","event_1559_12557","event_1559_12558"],"quest_calls":[],"dialogue_calls":[]},"scenario/1561.lua":{"source":"\n\n-- Initialisation serveur\n-- \nfunction event_1561_12183()\n    \nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_1561_12184()\n    \nend\n\n-- Combat Salle 1\n-- \nfunction event_1561_21863()\n    \nend\n\n-- Combat 01 - Victoire\n-- \nfunction event_1561_12185()\n    \nend\n\n-- Combat 01 - Ouverture de la porte\n-- \nfunction event_1561_12186()\n    \nend\n\n-- Combat 02 - Victoire\n-- \nfunction event_1561_12187()\n    \nend\n\n-- Combat 02 - Ouverture de la porte\n-- \nfunction event_1561_12188()\n    \nend\n\n-- Combat 03 - Victoire\n-- \nfunction event_1561_12189()\n    \nend\n\n-- Combat 03 - Ouverture de la porte\n-- \nfunction event_1561_12190()\n    \nend\n\n-- Combat Boss started\n-- \nfunction event_1561_12202()\n    \nend\n\n-- Combat 04 (Boss) - Victoire\n-- \nfunction event_1561_12193()\n    \nend\n\n-- Combat 04 (Boss) - Ouverture de la porte\n-- \nfunction event_1561_12194()\n    \nend\n\n-- Lancement d'un combat - Application du boost PV sur les rats\n-- \nfunction event_1561_21877()\n    \nend\n\n-- [ARCHI] Apparition de l'Archimonstre\n-- \nfunction event_1561_23954()\n    \nend\n\n","functions":["event_1561_12183","event_1561_12184","event_1561_21863","event_1561_12185","event_1561_12186","event_1561_12187","event_1561_12188","event_1561_12189","event_1561_12190","event_1561_12202","event_1561_12193","event_1561_12194","event_1561_21877","event_1561_23954"],"quest_calls":[],"dialogue_calls":[]},"scenario/1562.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\nfunction bossVisible(mobileId)\r\n\tMobile.setMobileVisible(mobileId, false)\r\nend\r\n\r\nbubbleSteleInfoId = 0\r\n\r\nfunction closeSteleInfo()\r\n\tif (bubbleSteleInfoId ~= nil  and bubbleSteleInfoId ~= 0) then BubbleText.close(bubbleSteleInfoId) end\r\nend\r\n\r\nfunction onSteleInfoClosed()\r\n\tif (bubbleSteleInfoId ~= nil  and bubbleSteleInfoId ~= 0) then bubbleSteleInfoId = 0 end\r\nend\r\n\r\nfunction updateSteleInfo(stateInfoId, forceDisplayUI)\r\n\r\n\tif (bubbleSteleInfoId == 0) then\r\n\t\tbubbleSteleInfoId = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_WEST\", 0, -60, false, 2147483647, true, \"interactiveBubbleDialog5\", 30000, 25000, \"onSteleInfoClosed\")\r\n\tend\r\n\r\n\tBubbleText.setText(bubbleSteleInfoId, stateInfoId)\r\n\t\r\n\tif (forceDisplayUI) then BubbleText.show(bubbleSteleInfoId) end\r\nend\r\n\r\nfunction openDoor()\r\nMobile.addMobileCreationCallback(boss, \"bossVisible\", boss)\r\nMobile.addMobileCreationCallback(mobA, \"bossVisible\", mobA)\r\nMobile.addMobileCreationCallback(mobB, \"bossVisible\", mobB)\r\nMobile.addMobileCreationCallback(mobD, \"bossVisible\", mobD)\r\nend\n\n-- [INIT] Variables & Constantes\n-- \nfunction event_1562_21787()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_1562_21788(boss, mobA, mobB, mobC)\n    local bossId = toLong(boss)\r\n    local mobAId = toLong(mobA)\r\n    local mobBId = toLong(mobB)\r\n    local mobCId = toLong(mobC)\r\n    \r\n    Mobile.setMobileVisible(bossId, false)\r\n    Mobile.setMobileVisible(mobAId, false)\r\n    Mobile.setMobileVisible(mobBId, false)\r\n    Mobile.setMobileVisible(mobCId, false)\nend\n\n-- INTERACTIVE_ELEMENT_ACTIVATION - Ouverture de la porte\n-- \nfunction event_1562_21789(boss, mobA, mobB, mobC)\n    trace(\"OUVERTURE DE LA PORTE\")\r\n    \r\n    local playerId = Context.getLeaderId()\r\n    local boss = toLong(boss)\r\n    local mobA = toLong(mobA)\r\n    local mobB = toLong(mobB)\r\n    local mobC = toLong(mobC)\r\n    \r\n    function customSkip()\r\n    \tMobile.setMobileVisible(boss, true)\r\n    \tMobile.setMobileVisible(mobA, true)\r\n    \tMobile.setMobileVisible(mobB, true)\r\n    \tMobile.setMobileVisible(mobC, true)\r\n    \tMobile.setMobilePosition(boss, -69, -74, 4)\r\n    \tMobile.setMobileDirection(boss, 1)\r\n    \tskipCinematic()\r\n    end\r\n    \r\n    startCinematicContext(1.5, mobA)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"customSkip\")\r\n    \r\n    invoke_custom(00001, 1, \"Mobile.setMobileDirection\", playerId, 3)\r\n    invoke_custom(00001, 1, \"Mobile.setMobileDirection\", boss, 5)\r\n    \r\n    invoke_custom(00500, 1, \"Mobile.setMobileVisible\", mobA, true)\r\n    invoke_custom(00500, 1, \"Mobile.setMobileAnimation\", mobA, \"AnimSort-SautDeLAnge-Fin\")\r\n    \r\n    invoke_custom(02500, 1, \"Mobile.setMobileVisible\", mobB, true)\r\n    invoke_custom(02500, 1, \"Mobile.setMobileAnimation\", mobB, \"AnimSort-SautDeLAnge-Fin\")\r\n    \r\n    invoke_custom(04500, 1, \"Mobile.setMobileVisible\", mobC, true)\r\n    invoke_custom(04500, 1, \"Mobile.setMobileAnimation\", mobC, \"AnimSort-SautDeLAnge-Fin\")\r\n    invoke_custom(05500, 1, \"Mobile.setMobileVisible\", boss, true)\r\n    invoke_custom(07500, 1, \"Mobile.moveMobile\", boss, -69, -74, 4, \"Mobile.setMobileDirection\", boss, 1)\r\n    \r\n    invoke_custom(06500, 1, \"Camera.attachCameraToMobile\", boss)\r\n    \r\n    invoke_custom(17000, 1, \"Camera.setZoomFactor\", 0.9)\r\n    invoke_custom(18000, 1, \"Particle.addParticleSystem\", 7483001, -77, -64, 0)\r\n    invoke_custom(18000, 1, \"Particle.addParticleSystem\", 7483001, -77, -74, 0)\r\n    invoke_custom(18250, 1, \"Particle.addParticleSystem\", 7483002, -70, -83, 0)\r\n    invoke_custom(18250, 1, \"Particle.addParticleSystem\", 7483002, -59, -82, 0)\r\n    invoke_custom(18750, 1, \"Particle.addParticleSystem\", 7483003, -69, -74, 4)\r\n    \r\n    ---\"ARE YOUUUUUUUUUU READY ??!!\"\r\n    invoke_custom(19500, 1, \"bubble\", boss, \"donjon.trool.boss.ready\")\r\n    invoke_custom(19500, 1, \"Mobile.setMobileAnimation\", boss, \"AnimSort-Ecrasement\")\r\n    invoke_custom(19500, 1, \"Effect.createCameraShakeEffect\", 500, 500, 500, 5, 50, \"Both\")\r\n    \r\n    invoke_custom(20000, 1, \"Mobile.setMobileAnimation\", boss, \"AnimStatique02-Debut\")\r\n    invoke_custom(21100, 1, \"Mobile.setMobileAnimationStaticKey\", boss, \"AnimStatique02\")\r\n    \r\n    invoke_custom(21500, 1, \"customSkip\")\nend\n\n-- MONSTER_ACTION_EVENT - Lancement du combat\n-- on skippe la cinématique pour tout le monde \nfunction event_1562_21790(boss, mobA, mobB, mobC)\n    local bossId = toLong(boss)\r\n    local mobAId = toLong(mobA)\r\n    local mobBId = toLong(mobB)\r\n    local mobCId = toLong(mobC)\r\n    \r\n    Mobile.setMobileVisible(bossId, true)\r\n    Mobile.setMobileVisible(mobAId, true)\r\n    Mobile.setMobileVisible(mobBId, true)\r\n    Mobile.setMobileVisible(mobCId, true)\r\n    \r\n    skipCinematic()\nend\n\n-- FIGHT_ENDED - Rend les monstres inattaquables\n-- \nfunction event_1562_21791()\n    \nend\n\n-- [FIGHT] Défaite du combat - Reset les stèles\n-- \nfunction event_1562_21792()\n    \nend\n\n-- [STELE] Le joueur examine une stèle\n-- \nfunction event_1562_21793(steleCount, steleStateId)\n    local steleCount = toLong(steleCount)\r\n    local steleStateId = toLong(steleStateId)\r\n    \r\n    if (steleCount == 0) then\r\n    UI.openRewardsDialog(\"stele.description.tour\")\r\n    UI.addReward(23398)\r\n    UI.addReward(23402)\r\n    UI.addReward(27083, \"stele.reward.stasis.21\")\r\n    \r\n    elseif (steleCount == 1) then\r\n    UI.openRewardsDialog(\"stele.description.tour\")\r\n    UI.addReward(29905)\r\n    UI.addReward(29912)\r\n    UI.addReward(27083, \"stele.reward.stasis.21\")\r\n    \r\n    elseif (steleCount == 2) then\r\n    UI.openRewardsDialog(\"stele.description.tour\")\r\n    UI.addReward(29906)\r\n    UI.addReward(29914)\r\n    UI.addReward(27083, \"stele.reward.stasis.21\")\r\n    \r\n    elseif (steleCount == 3) then\r\n    UI.openRewardsDialog(\"stele.description.tour\")\r\n    UI.addReward(29908)\r\n    UI.addReward(29910)\r\n    UI.addReward(27083, \"stele.reward.stasis.21\")\r\n    \r\n    else\r\n    \r\n    end\r\n    \r\n    local stateInfoId = \"stele.state.description.\" .. toString(steleStateId)\r\n    \r\n    updateSteleInfo(stateInfoId, true)\nend\n\n-- [STELE] Le joueur active une stèle\n-- \nfunction event_1562_21794(steleCount, steleStateId)\n    local steleCount = toLong(steleCount)\r\n    local steleStateId = toLong(steleStateId)\r\n    \r\n    if (steleCount == 1) then\r\n    UI.openRewardsDialog(\"stele.description.tour\")\r\n    UI.addReward(23398)\r\n    UI.addReward(23402)\r\n    UI.addReward(27083, \"stele.reward.stasis.21\")\r\n    \r\n    elseif (steleCount == 2) then\r\n    UI.openRewardsDialog(\"stele.description.tour\")\r\n    UI.addReward(29905)\r\n    UI.addReward(29912)\r\n    UI.addReward(27083, \"stele.reward.stasis.21\")\r\n    \r\n    elseif (steleCount == 3) then\r\n    UI.openRewardsDialog(\"stele.description.tour\")\r\n    UI.addReward(29906)\r\n    UI.addReward(29914)\r\n    UI.addReward(27083, \"stele.reward.stasis.21\")\r\n    \r\n    elseif (steleCount == 4) then\r\n    UI.openRewardsDialog(\"stele.description.tour\")\r\n    UI.addReward(29908)\r\n    UI.addReward(29910)\r\n    UI.addReward(27083, \"stele.reward.stasis.21\")\r\n    \r\n    else\r\n    \r\n    end\r\n    \r\n    local stateInfoId = \"stele.state.description.\" .. toString(steleStateId)\r\n    \r\n    updateSteleInfo(stateInfoId, true)\nend\n\n-- [STELE] Refresh des APS pour Stèles\n-- \nfunction event_1562_21795()\n    \nend\n\n-- [STASIS] DUNGEON_DIFFICULTY_CHANGED - Reset les stèles\n-- \nfunction event_1562_21796()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","bossVisible","closeSteleInfo","onSteleInfoClosed","updateSteleInfo","openDoor","event_1562_21787","event_1562_21788","event_1562_21789","customSkip","event_1562_21790","event_1562_21791","event_1562_21792","event_1562_21793","event_1562_21794","event_1562_21795","event_1562_21796"],"quest_calls":["UI.openRewardsDialog(\"stele.description.tour\")\r","UI.openRewardsDialog(\"stele.description.tour\")\r","UI.openRewardsDialog(\"stele.description.tour\")\r","UI.openRewardsDialog(\"stele.description.tour\")\r","UI.openRewardsDialog(\"stele.description.tour\")\r","UI.openRewardsDialog(\"stele.description.tour\")\r","UI.openRewardsDialog(\"stele.description.tour\")\r","UI.openRewardsDialog(\"stele.description.tour\")\r"],"dialogue_calls":[]},"scenario/1563.lua":{"source":"function displayPath(room)\r\n\tlocal passerelle = toLong(room)\r\n\r\n\tif passerelle==1 then\r\n\t\tWorld.setPictoAlpha(5, -8, 9, 1, 1000)\r\n\t\tWorld.setPictoAlpha(11, -18, 9, 1, 1000)\r\n\t\tWorld.setPictoAlpha(29, -19, -1, 1, 1000)\r\n\telseif passerelle==2 then\r\n\t\tWorld.setPictoAlpha(5, -8, 9, 0, 1000)\r\n\t\tWorld.setPictoAlpha(11, -18, 9, 1, 1000)\r\n\t\tWorld.setPictoAlpha(29, -19, -1, 1, 1000)\r\n\telseif passerelle==3 then\r\n\t\tWorld.setPictoAlpha(5, -8, 9, 0, 1000)\r\n\t\tWorld.setPictoAlpha(11, -18, 9, 0, 1000)\r\n\t\tWorld.setPictoAlpha(29, -19, -1, 1, 1000)\r\n\telseif passerelle==4 then\r\n\t\tWorld.setPictoAlpha(5, -8, 9, 0, 1000)\r\n\t\tWorld.setPictoAlpha(11, -18, 9, 0, 1000)\r\n\t\tWorld.setPictoAlpha(29, -19, -1, 0, 1000)\r\n\tend\r\nend\r\n\r\n-- Infos stèle d'intervention\r\nfunction updateInterventionInfo(stateInfoId, forceDisplayUI)\r\n\r\n\tif (bubbleSteleInfoId == 0) then\r\n\t\tbubbleSteleInfoId = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_WEST\", 0, -60, false, 2147483647, true, \"interactiveBubbleDialog5\", 30000, 25000, \"onSteleInfoClosed\")\r\n\tend\r\n\r\n\tBubbleText.setText(bubbleSteleInfoId, stateInfoId)\r\n\t\r\n\tif (forceDisplayUI) then BubbleText.show(bubbleSteleInfoId) end\r\nend\n\n-- [INIT] Variables Globales\n-- \nfunction event_1563_20298()\n    \nend\n\n-- [INIT] Inscription du joueur + Variables Locales\n-- \nfunction event_1563_20299(room)\n    displayPath(room)\nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_1563_22001()\n    \nend\n\n-- FIGHT_STARTED - Salle 01\n-- \nfunction event_1563_21999()\n    \nend\n\n-- FIGHT_ENTER_ACTION_PHASE - Salle 01\n-- \nfunction event_1563_22002()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 01\n-- \nfunction event_1563_20302(room)\n    displayPath(room)\nend\n\n-- USER_GROUP_KILLED - Salle 02 - BOSS\n-- \nfunction event_1563_20303()\n    \nend\n\n-- Déplace le joueur vers la salle suivante\n-- \nfunction event_1563_20304()\n    \nend\n\n-- [ARCHI] Apparition de l'Archimonstre\n-- \nfunction event_1563_23998()\n    \nend\n\n-- [POURPRE] Spawn vieil amnésique en fin de donjon\n-- \nfunction event_1563_24473()\n    \nend\n\n-- [INTERVENTION] INTERACTIVE_ELEMENT_ACTIVATION - Le joueur examine la Stèle d'intervention\n-- \nfunction event_1563_24500()\n    UI.openRewardsDialog(\"stele.intervention.description.4\")\r\n    \r\n    UI.addReward(33392)\r\n    UI.addReward(33406)\r\n    \r\n    local stateInfoId = \"stele.intervention.ignemikhal.description\" \r\n    \r\n    updateInterventionInfo(stateInfoId, true)\nend\n\n-- [INTERVENTION] GENERIC_ACTIVABLE_ACTION - Activation Stèle d'intervention\n-- \nfunction event_1563_24501(mobTwo)\n    UI.openRewardsDialog(\"stele.intervention.description.4\")\r\n    \r\n    UI.addReward(33392)\r\n    UI.addReward(33406)\r\n    \r\n    local stateInfoId = \"stele.intervention.ignemikhal.description\" \r\n    \r\n    updateInterventionInfo(stateInfoId, true)\r\n    \r\n    local bossId = toLong(mobTwo)\r\n    \r\n    invoke(1, 1, \"Mobile.setMobileAnimation\", bossId, \"AnimSort-4-Boucle\")\r\n    invoke(480, 1, \"Mobile.setMobileAnimation\", bossId, \"AnimSort-4-Fin\")\r\n    \r\n    Effect.createCameraShakeEffect(100, 500, 100, 5, 100, \"BOTH\")\r\nend\n\n-- [INTERVENTION] FIGHT_STARTED - On cache la stèle\n-- \nfunction event_1563_24509()\n    \nend\n\n-- [INTERVENTION] FIGHT_ENDED - On rend la stèle utilisable en cas de défaite\n-- \nfunction event_1563_24510()\n    \nend\n\n","functions":["displayPath","updateInterventionInfo","event_1563_20298","event_1563_20299","event_1563_22001","event_1563_21999","event_1563_22002","event_1563_20302","event_1563_20303","event_1563_20304","event_1563_23998","event_1563_24473","event_1563_24500","event_1563_24501","event_1563_24509","event_1563_24510"],"quest_calls":["UI.openRewardsDialog(\"stele.intervention.description.4\")\r","UI.openRewardsDialog(\"stele.intervention.description.4\")\r"],"dialogue_calls":[]},"scenario/1565.lua":{"source":"function mobileStart(mobileId)\r\n\tMobile.setMobileVisible(mobileId,false)\r\nend\n\n-- [INITIALISATION] Serveur\n-- \nfunction event_1565_12235()\n    \nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_1565_12226(DA, DB, DC, DD, DE, DF, DG)\n    mobileStart(DA)\r\n    mobileStart(DB)\r\n    mobileStart(DC)\r\n    mobileStart(DD)\r\n    mobileStart(DE)\r\n    mobileStart(DF)\r\n    mobileStart(DG)\r\n    invoke(1500, 1, \"UI.openInfoDialog\",\"Bilbiza.Fight.Explication.Title\", \"Bilbiza.Fight.Explication\")\nend\n\n-- 01 - Lancement du combat\n-- \nfunction event_1565_12237()\n    UI.displaySplashText(\"Bilbiza.FightTurn.2\")\nend\n\n-- 01 - Victoire\n-- \nfunction event_1565_12229()\n    \nend\n\n-- 02 - Lancement du combat\n-- \nfunction event_1565_12238()\n    UI.displaySplashText(\"Bilbiza.FightTurn.3\")\nend\n\n-- 02 - Victoire\n-- \nfunction event_1565_12231()\n    \nend\n\n-- 03 - Lancement du combat\n-- \nfunction event_1565_12239()\n    UI.displaySplashText(\"Bilbiza.FightTurn.4\")\nend\n\n-- 03 - Victoire\n-- \nfunction event_1565_12393()\n    \nend\n\n","functions":["mobileStart","event_1565_12235","event_1565_12226","event_1565_12237","event_1565_12229","event_1565_12238","event_1565_12231","event_1565_12239","event_1565_12393"],"quest_calls":[],"dialogue_calls":[]},"scenario/1569.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\n--=== VARIABLES ===--\r\nplayerId = Context.getPlayer()\r\npetId = Context.getPlayerPetId()\r\nplayerX = 0\r\nplayerY = 0\r\nplayerZ = 0\r\n\r\nfunction cameraClear()\r\n\tCamera.attachCameraToMobile(playerId)\r\nend\r\n\r\napsId = 1019933\r\n\r\nfunction displayDoor()\r\n\tapsOneId = Particle.addParticleSystem(apsId, -3, -32, 0)\r\n\tapsTwoId = Particle.addParticleSystem(apsId, -2, -32, 0)\r\n\tapsThreeId = Particle.addParticleSystem(apsId, -1, -32, 0)\r\n\tapsFourId = Particle.addParticleSystem(apsId, 0, -32, 0)\r\n\tapsFiveId = Particle.addParticleSystem(apsId, 1, -32, 0)\r\nend\r\n\r\nfunction hideDoor()\r\n\tParticle.removeParticleSystem(apsOneId)\r\n\tParticle.removeParticleSystem(apsTwoId)\r\n\tParticle.removeParticleSystem(apsThreeId)\r\n\tParticle.removeParticleSystem(apsFourId)\r\n\tParticle.removeParticleSystem(apsFiveId)\r\nend\n\n-- [INIT] Variables\n-- \nfunction event_1569_12249()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_1569_12250()\n    displayDoor()\nend\n\n-- [EVENT] Boss - Victoire\n-- \nfunction event_1569_12254()\n    \nend\n\n-- [COMBAT] Le Dragon Cochon possède \"Frénésie\" au niveau 14\n-- \nfunction event_1569_12269()\n    trace(\"LA FRENESIE EST A 14\")\nend\n\n-- [COMBAT] Un joueur a monté \"Provocation\" au niveau 500\n-- \nfunction event_1569_12270()\n    trace(\"LA PROVOCATION EST A 500\")\nend\n\n-- [COMBAT] Un joueur a monté \"Provocation\" au niveau 500 + Victoire des joueurs\n-- \nfunction event_1569_12271()\n    \nend\n\n-- [COMBAT] Le Dragon Cochon possède \"Frénésie\" au niveau 14 + Victoire des joueurs\n-- \nfunction event_1569_12272()\n    \nend\n\n-- GENERIC_ACTIVABLE_ACTION - Ouverture de la porte\n-- \nfunction event_1569_22013(bossId)\n    hideDoor()\r\n    \r\n    local dragonCochonId = toLong(bossId)\r\n    \r\n    function customSkip()\r\n    \tMobile.hideOtherPlayerMobile(false)\r\n    \tCamera.setMoveSpeedFactor(2.1)\r\n    \tskipCinematic(22013)\r\n    \tMobile.setMobileAnimation(dragonCochonId, \"AnimStatique-Combat\")\r\n    end\r\n    \r\n    Mobile.hideOtherPlayerMobile(true)\r\n    \r\n    startCinematicContext(1.8, dragonCochonId)\r\n    \r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"customSkip\")\r\n    \r\n    invoke_custom(00100, 1, \"Camera.setMoveSpeedFactor\", 0.2)\r\n    invoke_custom(00100, 1, \"Camera.setZoomSpeedFactor\", 0.2)\r\n    \r\n    invoke_custom(00200, 1, \"Mobile.setMobileMovementStyle\", dragonCochonId, \"WALK\", \"WALK\")\r\n    invoke_custom(00200, 1, \"Mobile.setCustomWalkStyle\", dragonCochonId, \"AnimMarche-HorsCombat\", 600)\r\n    \r\n    invoke_custom(03000, 1, \"Mobile.moveMobile\", dragonCochonId, -1, -45, 0)\r\n    \r\n    invoke_custom(06000, 1, \"Mobile.setMobileAnimation\", dragonCochonId, \"AnimCombat-Debut\")\r\n    \r\n    invoke_custom(10000, 1, \"customSkip\")\nend\n\n-- CLIENT_TRIGGERED_EVENT - On skip chez tout le monde\n-- \nfunction event_1569_22690(bossId)\n    local dragonCochonId = toLong(bossId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n    Camera.setMoveSpeedFactor(2.1)\r\n    skipCinematic()\r\n    Mobile.setMobileAnimation(dragonCochonId, \"AnimStatique-Combat\")\nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","cameraClear","displayDoor","hideDoor","event_1569_12249","event_1569_12250","event_1569_12254","event_1569_12269","event_1569_12270","event_1569_12271","event_1569_12272","event_1569_22013","customSkip","event_1569_22690"],"quest_calls":[],"dialogue_calls":[]},"scenario/1572.lua":{"source":"function displayPath(room)\r\n\tlocal room = toLong(room)\r\n\t\r\n\tif ( room == -1) then\r\n\t\tWorld.setPictoAlpha(5, -4, 3, 0, 1000)\r\n\tend\r\nend\n\n-- [INIT] Variables Globales\n-- \nfunction event_1572_18426()\n    \nend\n\n-- [INIT] Inscription du joueur + Variables Locales\n-- \nfunction event_1572_18427(room)\n    displayPath(room)\nend\n\n-- USER_GROUP_KILLED - Salle 01\n-- \nfunction event_1572_18428()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 02\n-- \nfunction event_1572_18429()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 03\n-- \nfunction event_1572_18430()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 04 - BOSS\n-- \nfunction event_1572_18431(room)\n    displayPath(room)\nend\n\n-- Déplace le joueur vers la salle suivante\n-- \nfunction event_1572_18432()\n    \nend\n\n-- [4] Démarrage du combat - Initialisation des variables\n-- \nfunction event_1572_20394()\n    \nend\n\n-- [4][EVENT] Bilbymoule Nacrée meurt alors qu'il n'y a aucun glyphe Perlouza\n-- \nfunction event_1572_20395()\n    \nend\n\n-- [4][NOTIF] On notifie la victoire dans un combat où l'exploit a été accompli\n-- \nfunction event_1572_20396()\n    \nend\n\n","functions":["displayPath","event_1572_18426","event_1572_18427","event_1572_18428","event_1572_18429","event_1572_18430","event_1572_18431","event_1572_18432","event_1572_20394","event_1572_20395","event_1572_20396"],"quest_calls":[],"dialogue_calls":[]},"scenario/1575.lua":{"source":"particleId = 7504010\r\n\r\nparticleStateOne = 0\r\nparticleStateTwo = 0\r\nparticleStateThree = 0\r\n\r\nplayerId = Context.getLeaderId()\r\n\r\n--On bloque les interactions du joueur\r\nfunction playerBlock()\r\n\tCamera.setUserZoomLocked(true)\r\n\tCamera.setZoomFactor(1)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\t\t\t\t\t\t\t\t\t\t\t\t\r\n    UI.manageFrame(\"World\",false) \t\t\t\t\t\r\n\tUI.setUIVisible(false)\t\r\nend\r\n\r\n--On débloque les interactions du joueur\r\nfunction configDefault()\r\n\tCamera.setMoveSpeedFactor(1)\r\n\tCamera.setZoomFactor(1)\r\n\tCamera.setUserZoomLocked(false)\r\n\tUI.manageFrame(\"World\",true) \t\t\t\t\t-- Réactive le déplacement\r\n\tUI.setUIVisible(true)\r\n    UI.manageMRU(58, false)\t\t\t\t\t\t\t\t-- Blocage pack-unpack gelutin\r\n    Camera.attachCameraToMobile(playerId)\r\nend\n\n-- Initialisation\n-- \nfunction event_1575_12346()\n    \nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_1575_12347(showId)\n    --Le Présentateur fait son show\r\n    function showTalkOneOne()\r\n    \tCamera.attachCameraToMobile(showId)\r\n    \tMobile.setMobileAnimation(showId,\"AnimEmote-Presenter\")\t\r\n    \tBubbleText.showText(showId, \"bilbiza.show.1_1\", 0, 60, false)\r\n    \tinvoke(4000,1,\"showTalkOneTwo\")\r\n    end\r\n    \r\n    function showTalkOneTwo()\r\n    \tBubbleText.closeBubbleAttachedTo(showId)\r\n    \tMobile.setMobileAnimation(showId,\"AnimEmote-Presenter\")\t\r\n    \tBubbleText.showText(showId, \"bilbiza.show.1_2\", 0, 60, false)\r\n    \tinvoke(4000,1,\"showTalkOneThree\")\r\n    end\r\n    \r\n    function showTalkOneThree()\r\n    \tBubbleText.closeBubbleAttachedTo(showId)\r\n    \tMobile.setMobileAnimation(showId,\"AnimEmote-Presenter\")\t\r\n    \tBubbleText.showText(showId, \"bilbiza.show.1_3\", 0, 60, false)\r\n    end\r\n    \r\n    playerBlock()\r\n    invoke(3000,1,\"showTalkOneOne\")\r\n    \r\n    invoke(16000,1,\"configDefault\")\nend\n\n-- [Epreuve 1] Joueur utilise la gelée 1 - Raté\n-- \nfunction event_1575_12352(GeleeCitron)\n    Sound.playSound(90010234,true,100,1)\r\n    GeleeCitronID = toLong(GeleeCitron)\r\n    Mobile.setMobileAnimation(GeleeCitronID,\"AnimHit\")\nend\n\n-- [Epreuve 1] Joueur utilise la gelée 2 - Raté\n-- \nfunction event_1575_12353(GeleeMenthe)\n    Sound.playSound(90010228,true,100,1)\r\n    GeleeMentheID = toLong(GeleeMenthe)\r\n    Mobile.setMobileAnimation(GeleeMentheID,\"AnimSort-Burp\")\nend\n\n-- [Epreuve 1] Joueur utilise la gelée 3 - Raté\n-- \nfunction event_1575_12354(GeleeFraise)\n    Sound.playSound(90010226,true,100,1)\r\n    GeleeFraiseID = toLong(GeleeFraise)\r\n    Mobile.setMobileAnimation(GeleeFraiseID,\"AnimSort-Pique\")\nend\n\n-- [Epreuve 1] Joueur utilise la gelée 3 - Gagné\n-- \nfunction event_1575_12351(showId, GeleeFraise)\n    particleStateThree = Particle.addParticleSystem(particleId,-3,4,1)\r\n    Sound.playSound(90010226,true,100,1)\r\n    GeleeFraiseID = toLong(GeleeFraise)\r\n    Mobile.setMobileAnimation(GeleeFraiseID,\"Animsort-Pique\")\r\n    \r\n    --Le Présentateur fait son show\r\n    function showTalkOneFour()\r\n    \tCamera.attachCameraToMobile(showId)\r\n    \tBubbleText.closeBubbleAttachedTo(showId)\r\n    \tMobile.setMobileAnimation(showId,\"AnimEmote-Presenter\")\t\t\r\n    \tBubbleText.showText(showId, \"bilbiza.show.1_4\", 0, 60, false)\r\n    \tinvoke(4000,1,\"showTalkOneFive\")\r\n    end\r\n    \r\n    function showTalkOneFive()\r\n    \tBubbleText.closeBubbleAttachedTo(showId)\r\n    \tMobile.setMobileAnimation(showId,\"AnimEmote-Presenter\")\t\r\n    \tBubbleText.showText(showId, \"bilbiza.show.1_5\", 0, 60, false)\r\n    \tinvoke(4000,1,\"Server.triggerEvent\", 12351)\t\r\n    end\r\n    \r\n    playerBlock()\r\n    invoke(1000,1,\"showTalkOneFour\")\nend\n\n-- [Epreuve 1] Joueur utilise la gelée 2 - Gagné\n-- \nfunction event_1575_12350(GeleeMenthe)\n    particleStateTwo = Particle.addParticleSystem(particleId,-5,4,1)\r\n    Sound.playSound(90010228,true, 100,1)\r\n    GeleeMentheID = toLong(GeleeMenthe)\r\n    Mobile.setMobileAnimation(GeleeMentheID,\"AnimSort-Burp\")\nend\n\n-- [Epreuve 1] Joueur utilise la gelée 1 - Gagné\n-- \nfunction event_1575_12349(GeleeCitron)\n    particleStateOne = Particle.addParticleSystem(particleId,-7,4,1)\r\n    --Sound.playSound(90010234,100,1)\r\n    Sound.playSound(90010234,true,100,1)\r\n    GeleeCitronID = toLong(GeleeCitron)\r\n    Mobile.setMobileAnimation(GeleeCitronID,\"AnimHit\")\nend\n\n-- [Epreuve 1] Joueur a échoué, on réinitialise\n-- \nfunction event_1575_12355()\n    Particle.removeParticleSystem( particleStateOne)\r\n    Particle.removeParticleSystem( particleStateTwo)\r\n    Particle.removeParticleSystem( particleStateThree)\nend\n\n-- [Epreuve 1] Fin de l'Epreuve\n-- \nfunction event_1575_12401()\n    \nend\n\n-- [Epreuve 2] Démarrage de l'épreuve\n-- \nfunction event_1575_12402(showIdTwo)\n    --Le Présentateur fait son show\r\n    function showTalkTwoOne()\r\n    \tCamera.attachCameraToMobile(showIdTwo)\r\n    \tMobile.setMobileAnimation(showIdTwo,\"AnimEmote-Presenter\")\t\r\n    \tBubbleText.showText(showIdTwo, \"bilbiza.show.2_1\", 0, 60, false)\r\n    \tinvoke(4000,1,\"showTalkTwoTwo\")\r\n    end\r\n    \r\n    function showTalkTwoTwo()\r\n    \tBubbleText.closeBubbleAttachedTo(showIdTwo)\r\n    \tMobile.setMobileAnimation(showIdTwo,\"AnimEmote-Presenter\")\t\r\n    \tBubbleText.showText(showIdTwo, \"bilbiza.show.2_2\", 0, 60, false)\r\n    \tinvoke(4000,1,\"showTalkTwoThree\")\r\n    end\r\n    \r\n    function showTalkTwoThree()\r\n    \tBubbleText.closeBubbleAttachedTo(showIdTwo)\r\n    \tMobile.setMobileAnimation(showIdTwo,\"AnimEmote-Presenter\")\t\r\n    \tBubbleText.showText(showIdTwo, \"bilbiza.show.2_3\", 0, 60, false)\r\n    \tinvoke(4000,1,\"configDefault\")\r\n    \tinvoke(5000,1,\"Server.triggerEvent\", 12402)\r\n    end\r\n    \r\n    playerBlock()\r\n    invoke(3000,1,\"showTalkTwoOne\")\nend\n\n-- [Epreuve 2] Arrivée des Bilbyboys\n-- \nfunction event_1575_12416()\n    \nend\n\n-- [Epreuve 2] Combat Gagné\n-- \nfunction event_1575_12425(showIdTwo)\n    --Le Présentateur fait son show\r\n    function showTalkTwoFour()\r\n    \tCamera.attachCameraToMobile(showIdTwo)\r\n    \tBubbleText.closeBubbleAttachedTo(showIdTwo)\r\n    \tMobile.setMobileAnimation(showIdTwo,\"AnimEmote-Presenter\")\t\t\r\n    \tBubbleText.showText(showIdTwo, \"bilbiza.show.2_4\", 0, 60, false)\r\n    \tinvoke(4000,1,\"showTalkTwoFive\")\r\n    end\r\n    \r\n    function showTalkTwoFive()\r\n    \tBubbleText.closeBubbleAttachedTo(showIdTwo)\r\n    \tMobile.setMobileAnimation(showIdTwo,\"AnimEmote-Presenter\")\t\r\n    \tBubbleText.showText(showIdTwo, \"bilbiza.show.2_5\", 0, 60, false)\r\n    \tinvoke(4000,1,\"Server.triggerEvent\", 12425)\r\n    end\r\n    \r\n    playerBlock()\r\n    invoke(1000,1,\"showTalkTwoFour\")\nend\n\n-- [Epreuve 2] Fin de l'Epreuve\n-- \nfunction event_1575_12426()\n    \nend\n\n-- [Epreuve 3] Démarrage de l'épreuve\n-- \nfunction event_1575_12427(showIdThree)\n    --Le Présentateur fait son show\r\n    function showTalkThreeOne()\r\n    \tCamera.attachCameraToMobile(showIdThree)\r\n