ileDirection(matouE, 5)\r\n\tMobile.setMobileAnimation(matouA, \"AnimStatique-Proue\")\r\n\tMobile.setMobileAnimation(matouB, \"AnimStatique-Caisse\")\r\n\tMobile.setMobileAnimation(matouC, \"AnimStatique-Mat02\")\r\n\tMobile.setMobileAnimation(matouD, \"AnimStatique-Velo\")\r\n\tMobile.setMobileAnimation(matouE, \"AnimComp-Steamboat\")\r\nend\n\n-- Arrivée du joueur dans l'instance\n-- \nfunction event_1587_12463()\n    function dialMatou(matouE)\r\n    \tmatouBubble = BubbleText.showText(matouE, \"zinit.barquette.04\", 0, 70, false)\r\n    end\r\n    \r\n    function dialMatouD(matouD)\r\n    \tmatouBubbleD = BubbleText.showText(matouD, \"zinit.barquette.05\", 115, 200, false)\r\n    end\r\n    \r\n    function seaEffect()\r\n    \tinstanceId = Context.getPlayerInstanceId()\t\r\n    \tif instanceId==290 then\r\n    \t\tEffect.createCameraSeaSicknessEffect()\r\n    \tend\r\n    end\r\n    \r\n    \r\n    Mobile.setMobileDirection(playerId, 5)\r\n    Mobile.setMobileAnimation(playerId, \"AnimEmote-Chercher\")\r\n    seaEffect()\r\n    initMatouleaux(matouA,matouB,matouC,matouD,matouE)\r\n    Camera.setCamera(1.0, 2, -3, 8)\r\n    Camera.setUserZoomLocked(true)\r\n    \r\n    invoke(2500, 1, \"dialMatou\", matouE)\r\n    invoke(3500, 1, \"dialMatouD\", matouD)\r\n    \r\nend\n\n-- Apparition des monstres + dialogue + création du combat\n-- \nfunction event_1587_12464(mobId, mobTwoId)\n    Mobile.setMobileAnimation(mobId, \"AnimApparition\")\r\n    Mobile.setMobileAnimation(mobTwoId, \"AnimApparition\")\r\n    invoke(500, 1, \"dialMatou\", matouB)\r\n    \r\n    function dialMatou(matouB)\r\n    \tmatouBubble = BubbleText.showText(matouB, \"zinit.barquette.06\", 50, 70, false)\r\n    end\nend\n\n-- Initialisation de la variable d'ID du combat\n-- \nfunction event_1587_13233()\n    \nend\n\n-- Fin du combat\n-- \nfunction event_1587_12465()\n    invoke(1500, 1, \"dialMatou\", matouB)\r\n    invoke(3000, 1, \"dialMatouC\", matouC)\r\n    \r\n    function dialMatou(matouB)\r\n    \tmatouBubble = BubbleText.showText(matouB, \"zinit.barquette.07\", 50, 70, false)\r\n    end\r\n    \r\n    function dialMatouC(matouC)\r\n    \tmatouBubbleC = BubbleText.showText(matouC, \"zinit.barquette.08\", 20, 330, false)\r\n    end\nend\n\n-- Transition post combat avant la Téléportation\n-- \nfunction event_1587_13230()\n    \nend\n\n-- Téléportation dans la zone suivante\n-- \nfunction event_1587_12466()\n    \nend\n\n","functions":["initMatouleaux","event_1587_12463","dialMatou","dialMatouD","seaEffect","event_1587_12464","dialMatou","event_1587_13233","event_1587_12465","dialMatou","dialMatouC","event_1587_13230","event_1587_12466"],"quest_calls":[],"dialogue_calls":[]},"scenario/1588.lua":{"source":"playerId = Context.getPlayer()\r\n\r\nmatouA = Mobile.generateClientMobileId()\r\nmatouB = Mobile.generateClientMobileId()\r\nmatouC = Mobile.generateClientMobileId()\r\nmatouD = Mobile.generateClientMobileId()\r\nmatouE = Mobile.generateClientMobileId()\r\n\r\nfunction initMatouleaux(matouA,matouB,matouC,matouD,matouE)\r\n\tActor.createActor(matouA, 1300059, -5, -1, 17, 4)\r\n\tActor.createActor(matouB, 1300059, -5, -1, 13, 4)\r\n\tActor.createActor(matouC, 1300059, 0, -1, 8, 4)\r\n\tActor.createActor(matouD, 1300059, 1, -5, 9, 4)\r\n\tActor.createActor(matouE, 1300057, 6, -2, 11, 4)\r\n\tMobile.setMobileDirection(matouA, 5)\r\n\tMobile.setMobileDirection(matouB, 1)\r\n\tMobile.setMobileDirection(matouC, 5)\r\n\tMobile.setMobileDirection(matouD, 5)\r\n\tMobile.setMobileDirection(matouE, 5)\r\n\tMobile.setMobileAnimation(matouA, \"AnimStatique-Proue\")\r\n\tMobile.setMobileAnimation(matouB, \"AnimStatique-Caisse\")\r\n\tMobile.setMobileAnimation(matouC, \"AnimStatique-Mat02\")\r\n\tMobile.setMobileAnimation(matouD, \"AnimStatique-Velo\")\r\n\tMobile.setMobileAnimation(matouE, \"AnimComp-Steamboat\")\r\nend\n\n-- Arrivée du joueur dans l'instance\n-- \nfunction event_1588_12467()\n    function dialMatou(matouA)\r\n    \tmatouBubble = BubbleText.show