60, false)\r\n    end\r\n    \r\n    function seaEffect()\r\n    \tinstanceId = Context.getPlayerInstanceId()\t\r\n    \tif instanceId==304 then\r\n    \t\tEffect.createCameraSeaSicknessEffect()\r\n    \tend\r\n    end\r\n    \r\n    Mobile.setMobileDirection(playerId, 3)\r\n    Mobile.setMobileAnimation(playerId, \"AnimEmote-Vomis\")\r\n    seaEffect()\r\n    initMatouleaux(matouA,matouB,matouC,matouD,matouE)\r\n    Camera.setCamera(1.0, 2, -3, 8)\r\n    Camera.setUserZoomLocked(true)\r\n    initStorm()\r\n    \r\n    invoke(2500, 1, \"dialMatou\", matouB)\r\n    invoke(3000, 1, \"dialMatouE\", matouE)\r\n    \r\nend\n\n-- Apparition des monstres + dialogue + création du combat\n-- \nfunction event_1589_12472(mobId, mobTwoId, mobThreeId)\n    Mobile.setMobileAnimation(mobId, \"AnimApparition\")\r\n    Mobile.setMobileAnimation(mobTwoId, \"AnimApparition\")\r\n    Mobile.setMobileAnimation(mobThreeId, \"AnimApparition\")\nend\n\n-- Initialisation de la variable d'ID du combat\n-- \nfunction event_1589_13237()\n    \nend\n\n-- Fin du combat\n-- \nfunction event_1589_12473()\n    function dialMatou(matouB)\r\n    \tmatouBubble = BubbleText.showText(matouB, \"zinit.barquette.13\", 50, 70, false)\r\n    end\r\n    \r\n    invoke(1500, 1, \"dialMatou\", matouB)\r\n    \r\nend\n\n-- Transition post combat avant la Téléportation\n-- \nfunction event_1589_13239()\n    \nend\n\n-- Téléportation dans la zone suivante\n-- \nfunction event_1589_12474()\n    \nend\n\n-- Lancement du combat de la salle 01\n-- \nfunction event_1589_12475()\n    \nend\n\n","functions":["initMatouleaux","initStorm","event_1589_12471","dialMatou","dialMatouE","seaEffect","event_1589_12472","event_1589_13237","event_1589_12473","dialMatou","event_1589_13239","event_1589_12474","event_1589_12475"],"quest_calls":[],"dialogue_calls":[]},"scenario/1590.lua":{"source":"playerId = Context.getPlayer()\r\n\r\nmatouA = Mobile.generateClientMobileId()\r\nmatouB = Mobile.generateClientMobileId()\r\nmatouC = Mobi