erId = Context.getPlayer()\r\n\r\n\r\nmatouA = Mobile.generateClientMobileId()\r\nmatouB = Mobile.generateClientMobileId()\r\nmatouC = Mobile.generateClientMobileId()\r\nmatouD = Mobile.generateClientMobileId()\r\nmatouE = Mobile.generateClientMobileId()\r\n\r\n--== FONCTIONS ==--\r\n\r\nfunction initMatouleaux(matouA,matouB,matouC,matouD,matouE)\r\n\tActor.createActor(matouA, 1300059, -17, -7, 12, 4)\r\n\tActor.createActor(matouB, 1300059, -12, -9, 7, 4)\r\n\tActor.createActor(matouC, 1300059, -11, -1, 8, 4)\r\n\tActor.createActor(matouD, 1300059, -8, -1, 0, 4)\r\n\tActor.createActor(matouE, 1300057, -3, 1, 0, 4)\r\n\tMobile.setMobileDirection(matouA, 1)\r\n\tMobile.setMobileDirection(matouB, 3)\r\n\tMobile.setMobileDirection(matouC, 1)\r\n\tMobile.setMobileDirection(matouD, 3)\r\n\tMobile.setMobileDirection(matouE, 1)\r\nend\r\n\r\n\r\nfunction scenarioMode()\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\t\t\t\t\t\t\t\t\t\t\t\t-- Ferme l'inventaire\r\n\tUI.setShortcutEnabled(false)\t\t\t\t\t\t-- désactive les shortcuts\r\n    UI.manageFrame(\"World\",false) \t\t\t\t\t-- Désactive le déplacement\r\n\tUI.setUIVisible(false)\r\n    Camera.setZoomFactor(1)\r\nend\r\n\r\nfunction scenarioModeEnd()\r\n\tCamera.setUserZoomLocked(false)\r\n\tUI.setShortcutEnabled(true)\t\t\t\t\t\t\r\n    UI.manageFrame(\"World\",true) \t\t\t\t\t\r\n\tUI.setUIVisible(true)\r\nend\r\n\r\nfunction dialMatouleauxOne(matouA,matouB)\r\n\tmatouADialId = BubbleText.showText(matouA, \"zinit.plage.matouleaux.01\",0,60,false)\r\n\tinvoke(2500, 1, \"dialMatouleauxTwo\", matouADialId,matouA,matouB)\r\nend\r\n\r\nfunction dialMatouleauxTwo(matouADialId,matouA,matouB)\r\n\tBubbleText.close(matouADialId)\r\n\tmatouBDialId = BubbleText.showText(matouB, \"zinit.plage.matouleaux.02\",0,60,false)\r\n\tinvoke(2500, 1, \"dialMatouleauxThree\", matouBDialId,matouA,matouB)\r\nend\r\n\r\nfunction dialMatouleauxThree(matouADialId,matouA,matouB)\r\n\tBubbleText.close(matouBDialId)\r\n\tmatouCDialId = BubbleText.showText(matouA, \"zinit.plage.matouleaux.03\",0,60,false)\r\n\tinvoke(2500, 1, \"dialMatouleauxFour\", matouCDialId,matouA,matouB)\r\nend\r\n\r\nfunction dialMatouleauxFour(matouADialId,matouA,matouB)\r\n\tBubbleText.close(matouCDialId)\r\n\tmatouDDialId = BubbleText.showText(matouB, \"zinit.plage.matouleaux.04\",0,60,false)\r\n\tinvoke(2500, 1, \"dialMatouleauxFive\", matouDDialId,matouA,matouB)\r\nend\r\n\r\nfunction dialMatouleauxFive(matouADialId,matouA,matouB)\r\n\tBubbleText.close(matouDDialId)\r\n\tmatouEDialId = BubbleText.showText(matouA, \"zinit.plage.matouleaux.05\",0,60,false)\r\n\tinvoke(2500, 1, \"dialMatouleauxSix\", matouEDialId,matouA,matouB)\r\nend\r\n\r\nfunction dialMatouleauxSix(matouADialId,matouA,matouB)\r\n\tBubbleText.close(matouEDialId)\r\n\tmatouFDialId = BubbleText.showText(matouB, \"zinit.plage.matouleaux.06\",0,60,false)\r\n\tinvoke(2500, 1, \"BubbleText.close\",matouFDialId)\r\nend\r\n\r\nfunction soundOgrest()\r\n\tinstanceId = Context.getPlayerInstanceId()\t\r\n\tif instanceId==282 then\r\n\t\tSound.playSound(70500006, 25)\r\n\t\tshakeEffectId = Effect.createCameraShakeEffect(500, 800, 1000, 6)\r\n\t\tinvoke(900000, 1, \"soundOgrest\")\r\n\t\ttrace(\"L'OGRE HURLE\")\r\n\tend\r\nend\n\n-- On choppe les Ids\n-- \nfunction event_1592_12479()\n    \nend\n\n-- Arrivée du joueur\n-- \nfunction event_1592_12480()\n    initMatouleaux(matouA,matouB,matouC,matouD,matouE)\r\n    Mobile.setMobileDirection(playerId, 5)\r\n    invoke(4000, 1, \"dialMatouleauxOne\",matouA,matouB)\r\n    Particle.addParticleSystem(800181, -2, -141, 2, 0)\r\n    invoke(3000, 1, \"soundOgrest\")\nend\n\n-- Arrivée du joueur - La cascade est fermée\n-- \nfunction event_1592_12481()\n    \nend\n\n-- Ouverture de la cascade - Timer\n-- \nfunction event_1592_12482(moozeId)\n    scenarioMode()\r\n    invoke(500, 1, \"moozeOne\")\r\n    Mobile.setMobileDirection(playerId, 5)\r\n    \r\n    function moozeOne()\r\n    \tMobile.setMobileAnimation(moozeId, \"AnimComp05\", \"moozeTwo\")\r\n    end\r\n    \r\n    function moozeTwo()\r\n    \tMobile.setMobileAnimation(moozeId, \"AnimComp05-Loop\", \"moozeThree\")\r\n    end\r\n    \r\n    function moozeThree()\r\n    \tMobile.setMobileAnimation(moozeId, \"AnimComp05-Fin\", \"moozeFour\")\r\n    end\r\n    \r\n    function moozeFour()\r\n    \tMobile.setMobileAnimation(moozeId, \"AnimComp04\", \"moozeFive\")\r\n    \tmoozeDialId = BubbleText.setCharacterSpeak(moozeId, \"zinit.mooze.01\")\r\n    end\r\n    \r\n    function moozeFive()\r\n    \tMobile.setMobileAnimation(moozeId, \"AnimComp03\", \"moozeSix\")\r\n    end\r\n    \r\n    function moozeSix()\r\n    \tMobile.setMobileDirection(playerId, 3)\r\n    \tMobile.setMobileAnimation(playerId, \"AnimEmote-CacherYeux-Debut\")\r\n    \tMobile.setMobileAnimation(moozeId, \"AnimComp02\", \"moozeSeven\")\r\n    \tmoozeDialId = BubbleText.setCharacterSpeak(moozeId, \"zinit.mooze.02\")\r\n    end\r\n    \r\n    function moozeSeven()\r\n    \tServer.triggerEvent(9412)\r\n    \tMobile.setMobileDirection(playerId, 7)\r\n    \tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    \tMobile.setMobileAnimation(moozeId, \"AnimComp07\", \"moozeEight\")\r\n    \tmoozeDialId = BubbleText.setCharacterSpeak(moozeId, \"zinit.mooze.03\")\r\n    end\r\n    \r\n    function moozeEight()\r\n    \tinvoke(500, 1, \"scenarioModeEnd\")\r\n    end\nend\n\n-- Ouverture de la cascade\n-- \nfunction event_1592_12483()\n    trace(\"LA CASCADE EST OUVERTE\")\r\n    Particle.addParticleSystem(800181, -2, -141, 2, 0)\r\n    scenarioModeEnd()\nend\n\n-- Arrivée du joueur - Morceaux = 0\n-- \nfunction event_1592_12484()\n    \nend\n\n-- Arrivée du joueur - Morceaux = 1\n-- \nfunction event_1592_12485()\n    \nend\n\n-- Arrivée du joueur - Morceaux = 2\n-- \nfunction event_1592_12486()\n    \nend\n\n-- Arrivée du joueur - Morceaux = 3\n-- \nfunction event_1592_12487()\n    \nend\n\n-- Arrivée du joueur - Panier = 1\n-- \nfunction event_1592_12488()\n    \nend\n\n-- Le joueur accepte la quête - Pop des Crabes\n-- \nfunction event_1592_12489()\n    \nend\n\n","functions":["initMatouleaux","scenarioMode","scenarioModeEnd","dialMatouleauxOne","dialMatouleauxTwo","dialMatouleauxThree","dialMatouleauxFour","dialMatouleauxFive","dialMatouleauxSix","soundOgrest","event_1592_12479","event_1592_12480","event_1592_12481","event_1592_12482","moozeOne","moozeTwo","moozeThree","moozeFour","moozeFive","moozeSix","moozeSeven","moozeEight","event_1592_12483","event_1592_12484","event_1592_12485","event_1592_12486","event_1592_12487","event_1592_12488","event_1592_12489"],"quest_calls":[],"dialogue_calls":[]},"scenario/1594.lua":{"source":"\n\n-- [INITIALISATION] Spawn du monstre\n-- \nfunction event_1594_12493()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_1594_13066()\n    \nend\n\n-- [COMBAT] Validation de la quête\n-- \nfunction event_1594_13067()\n    \nend\n\n","functions":["event_1594_12493","event_1594_13066","event_1594_13067"],"quest_calls":[],"dialogue_calls":[]},"scenario/1595.lua":{"source":"\n\n-- [INITIALISATION] Spawn du monstre\n-- \nfunction event_1595_12494()\n    \nend\n\n-- [INITIALISATION] Inscription du joueur\n-- \nfunction event_1595_13068()\n    \nend\n\n-- [COMBAT] Validation de la quête\n-- \nfunction event_1595_13069()\n    \nend\n\n","functions":["event_1595_12494","event_1595_13068","event_1595_13069"],"quest_calls":[],"dialogue_calls":[]},"scenario/1597.lua":{"source":"\n\n-- [INITIALISATION] Spawn du monstre\n-- \nfunction event_1597_12496()\n    \nend\n\n-- [INITIALISATION] Inscription du joueur\n-- \nfunction event_1597_13063()\n    \nend\n\n-- [COMBAT] Validation de la quête\n-- \nfunction event_1597_13064()\n    \nend\n\n-- [INITIALISATION][COMPAGNON] Appel à l'aide\n-- \nfunction event_1597_13272()\n    \r\n    function compBubbleStart(ieId)\r\n    \tboucle = math.random(1, 5)\r\n    \tBubbleText.closeBubbleAttachedTo(ieId);\r\n    \ttetext = BubbleText.prepareWakfuBubble(ieId, xa, 7)\r\n    \t\r\n    \tif boucle==1 then\r\n    \t\t\ttrace(\"LETS1\")\r\n    \t\t\tBubbleText.setText(tetext, \"quest.compagnon.astrubogrest.help01\")\r\n    \telseif boucle==2 then\r\n    \t\t\ttrace(\"LETS2\")\r\n    \t\t\tBubbleText.setText(tetext, \"quest.compagnon.astrubogrest.help02\")\r\n    \telseif boucle==3 then\r\n    \t\t\ttrace(\"LETS3\")\r\n    \t\t\tBubbleText.setText(tetext, \"quest.compagnon.astrubogrest.help03\")\r\n    \telseif boucle==4 then\r\n    \t\t\ttrace(\"LETS4\")\r\n    \t\t\tBubbleText.setText(tetext, \"quest.compagnon.astrubogrest.help04\")\r\n    \telseif boucle==5 then\r\n    \t\t\ttrace(\"LETS5\")\r\n    \t\t\tBubbleText.setText(tetext, \"quest.compagnon.astrubogrest.help05\")\r\n    \tend\r\n    \tBubbleText.show(tetext)\r\n    end\r\n    \r\n    cageComp = InteractiveElement.getElementId(21389)\r\n    xa,ya,za=InteractiveElement.getPosition(cageComp)\r\n    compBubbleStart(cageComp)\nend\n\n-- [QUËTE] Validation de la libération du Chevalier d'Astrub\n-- \nfunction event_1597_13273()\n    \nend\n\n-- [MORT] Le joueur est mort\n-- \nfunction event_1597_13672()\n    UI.loadTutorialDialog(\"tuto23\",\"tutorial.needtolevelup.title\",\"tutorial.needtolevelup.description\")\nend\n\n","functions":["event_1597_12496","event_1597_13063","event_1597_13064","event_1597_13272","compBubbleStart","event_1597_13273","event_1597_13672"],"quest_calls":[],"dialogue_calls":[]},"scenario/1601.lua":{"source":"nbFight = 0\n\n-- [INIT] Variables globales\n-- \nfunction event_1601_21825()\n    \nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_1601_21826()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 01\n-- \nfunction event_1601_21827(room)\n    \nend\n\n-- USER_GROUP_KILLED - Salle 02\n-- \nfunction event_1601_21828(room)\n    \nend\n\n-- USER_GROUP_KILLED - Salle 03\n-- \nfunction event_1601_21829()\n    \nend\n\n-- Déplace le joueur vers la salle suivante\n-- \nfunction event_1601_21830()\n    \nend\n\n","functions":["event_1601_21825","event_1601_21826","event_1601_21827","event_1601_21828","event_1601_21829","event_1601_21830"],"quest_calls":[],"dialogue_calls":[]},"scenario/1603.lua":{"source":"\n\n-- [INIT] Variables globales\n-- \nfunction event_1603_21843()\n    \nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_1603_21844()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 01\n-- \nfunction event_1603_21845(room)\n    \nend\n\n-- USER_GROUP_KILLED - Salle 02\n-- \nfunction event_1603_21846(room)\n    \nend\n\n-- USER_GROUP_KILLED - Salle 03\n-- \nfunction event_1603_21847()\n    \nend\n\n-- Déplace le joueur vers la salle suivante\n-- \nfunction event_1603_21848()\n    \nend\n\n","functions":["event_1603_21843","event_1603_21844","event_1603_21845","event_1603_21846","event_1603_21847","event_1603_21848"],"quest_calls":[],"dialogue_calls":[]},"scenario/1604.lua":{"source":"playerId = Context.getPlayer()\r\n\r\nfunction soundOgrest()\r\n\tinstanceId = Context.getPlayerInstanceId()\t\r\n\tif instanceId==284 then\r\n\t\tSound.playSound(70500006, 45)\r\n\t\tshakeEffectId = Effect.createCameraShakeEffect(500, 800, 1000, 6)\r\n\tend\r\nend\n\n-- [INITIALISATION] Serveur\n-- \nfunction event_1604_12532()\n    \nend\n\n-- [INITIALISATION] Joueur\n-- \nfunction event_1604_12533(callbackPasserelle)\n    passerelle = toLong(callbackPasserelle)\r\n    \r\n    invoke(3000, 1, \"soundOgrest\")\r\n    \r\n    if passerelle==0 then\r\n    \tWorld.setPictoAlpha(2, -12, 0, 0, 1)\r\n    \tWorld.setPictoAlpha(2, -13, 0, 0, 1)\r\n    \tWorld.setPictoAlpha(2, -14, 0, 0, 1)\r\n    \tWorld.setPictoAlpha(1, -31, 0, 0, 1)\r\n    \tWorld.setPictoAlpha(1, -32, 0, 0, 1)\r\n    \tWorld.setPictoAlpha(1, -33, 0, 0, 1)\r\n    \tWorld.setPictoAlpha(1, -34, 0, 0, 1)\r\n    \tWorld.setPictoAlpha(0, -51, 0, 0, 1)\r\n    \tWorld.setPictoAlpha(0, -52, 0, 0, 1)\r\n    \tWorld.setPictoAlpha(0, -53, 0, 0, 1)\r\n    elseif passerelle==1 then\r\n    \tWorld.setPictoAlpha(2, -12, 0, 1, 1)\r\n    \tWorld.setPictoAlpha(2, -13, 0, 1, 1)\r\n    \tWorld.setPictoAlpha(2, -14, 0, 1, 1)\r\n    \tWorld.setPictoAlpha(1, -31, 0, 0, 1)\r\n    \tWorld.setPictoAlpha(1, -32, 0, 0, 1)\r\n    \tWorld.setPictoAlpha(1, -33, 0, 0, 1)\r\n    \tWorld.setPictoAlpha(1, -34, 0, 0, 1)\r\n    \tWorld.setPictoAlpha(0, -51, 0, 0, 1)\r\n    \tWorld.setPictoAlpha(0, -52, 0, 0, 1)\r\n    \tWorld.setPictoAlpha(0, -53, 0, 0, 1)\r\n    elseif passerelle==2 then\r\n    \tWorld.setPictoAlpha(2, -12, 0, 1, 1)\r\n    \tWorld.setPictoAlpha(2, -13, 0, 1, 1)\r\n    \tWorld.setPictoAlpha(2, -14, 0, 1, 1)\r\n    \tWorld.setPictoAlpha(1, -31, 0, 1, 1)\r\n    \tWorld.setPictoAlpha(1, -32, 0, 1, 1)\r\n    \tWorld.setPictoAlpha(1, -33, 0, 1, 1)\r\n    \tWorld.setPictoAlpha(1, -34, 0, 1, 1)\r\n    \tWorld.setPictoAlpha(0, -51, 0, 0, 1)\r\n    \tWorld.setPictoAlpha(0, -52, 0, 0, 1)\r\n    \tWorld.setPictoAlpha(0, -53, 0, 0, 1)\r\n    elseif passerelle==3 then\r\n    \tWorld.setPictoAlpha(2, -12, 0, 1, 1)\r\n    \tWorld.setPictoAlpha(2, -13, 0, 1, 1)\r\n    \tWorld.setPictoAlpha(2, -14, 0, 1, 1)\r\n    \tWorld.setPictoAlpha(1, -31, 0, 1, 1)\r\n    \tWorld.setPictoAlpha(1, -32, 0, 1, 1)\r\n    \tWorld.setPictoAlpha(1, -33, 0, 1, 1)\r\n    \tWorld.setPictoAlpha(1, -34, 0, 1, 1)\r\n    \tWorld.setPictoAlpha(0, -51, 0, 1, 1)\r\n    \tWorld.setPictoAlpha(0, -52, 0, 1, 1)\r\n    \tWorld.setPictoAlpha(0, -53, 0, 1, 1)\r\n    end\nend\n\n-- [COMBAT] Victoire Salle 1\n-- \nfunction event_1604_12534()\n    \nend\n\n-- [COMBAT] Victoire Salle 1 - On déverouille la porte\n-- \nfunction event_1604_12535()\n    \tWorld.setPictoAlpha(2, -12, 0, 1, 1000)\r\n    \tWorld.setPictoAlpha(2, -13, 0, 1, 1000)\r\n    \tWorld.setPictoAlpha(2, -14, 0, 1, 1000)\r\nend\n\n-- [COMBAT] Victoire Salle 2\n-- \nfunction event_1604_12536()\n    \nend\n\n-- [COMBAT] Victoire Salle 2 - On déverouille la porte\n-- \nfunction event_1604_12537()\n    \tWorld.setPictoAlpha(1, -31, 0, 1, 1000)\r\n    \tWorld.setPictoAlpha(1, -32, 0, 1, 1000)\r\n    \tWorld.setPictoAlpha(1, -33, 0, 1, 1000)\r\n    \tWorld.setPictoAlpha(1, -34, 0, 1, 1000)\r\nend\n\n-- [COMBAT] Victoire Salle 3\n-- \nfunction event_1604_12538()\n    \nend\n\n-- [COMBAT] Victoire Salle 3 - On active le TP et le coffre\n-- \nfunction event_1604_12539()\n    \tWorld.setPictoAlpha(0, -51, 0, 1, 1000)\r\n    \tWorld.setPictoAlpha(0, -52, 0, 1, 1000)\r\n    \tWorld.setPictoAlpha(0, -53, 0, 1, 1000)\r\nend\n\n-- [SCENE] Entrée du joueur\n-- \nfunction event_1604_12540(aguaId)\n    Mobile.setMobileAnimation(aguaId, \"AnimApparition\", \"Camera.attachCameraToMobile\", playerId)\r\n    invoke(200, 1, \"shakeCam\")\r\n    Camera.setCamera(1, 0, -62, 0)\r\n    \r\n    function shakeCam()\r\n    \tshakeEffectId = Effect.createCameraShakeEffect(500, 1800, 1000, 6)\r\n    \tinvoke(1500, 1, \"Effect.stopEffect\", shakeEffectId)\r\n    end\nend\n\n-- [SCENE] Dialogue avec Aguabrial\n-- \nfunction event_1604_12541(aguaId)\n    \nend\n\n-- [COMBAT] Déclenchement (le joueur a perdu)\n-- \nfunction event_1604_12542(aguaId)\n    \nend\n\n-- [COMBAT] Déclenchement\n-- \nfunction event_1604_12543(aguaId)\n    \nend\n\n-- [COMBAT] Victoire Salle 4 - C'est le joueur qui gagne\n-- \nfunction event_1604_12545(aguaId)\n    \nend\n\n-- [COMBAT] Victoire Salle 4\n-- \nfunction event_1604_12546(aguaId)\n    \nend\n\n-- [COMBAT] Victoire Salle 4 - On déverouille la porte\n-- \nfunction event_1604_12547(aguaId)\n    \nend\n\n-- [COMBAT] Victoire Salle 4 - Le joueur a répondu à Aguabrial\n-- \nfunction event_1604_12548(aguaId)\n    invoke(1500, 1, \"aguaEnd\", aguaId)\r\n    \r\n    function aguaEnd(aguaId)\r\n    \taguaDialId = BubbleText.setCharacterSpeak(aguaId, \"zinit.aguabrial.01\")\r\n    \tinvoke(2500, 1, \"BubbleText.close\", aguaDialId)\r\n    \tinvoke(2500, 1, \"Mobile.setMobileAnimation\",aguaId,\"AnimMort\")\r\n    end\r\nend\n\n-- [INITIALISATION] Joueur - Achievement OK\n-- \nfunction event_1604_12549()\n    \nend\n\n-- Le joueur annule le dialogue\n-- \nfunction event_1604_12550()\n    \nend\n\n-- Le joueur annule le dialogue\n-- \nfunction event_1604_12551()\n    \nend\n\n","functions":["soundOgrest","event_1604_12532","event_1604_12533","event_1604_12534","event_1604_12535","event_1604_12536","event_1604_12537","event_1604_12538","event_1604_12539","event_1604_12540","shakeCam","event_1604_12541","event_1604_12542","event_1604_12543","event_1604_12545","event_1604_12546","event_1604_12547","event_1604_12548","aguaEnd","event_1604_12549","event_1604_12550","event_1604_12551"],"quest_calls":[],"dialogue_calls":[]},"scenario/1606.lua":{"source":"\n\n-- [ENTREE] Inscription au scenario du joueur\n-- \nfunction event_1606_12569()\n    \nend\n\n-- [ENTREE] Le joueur possède le déguisement\n-- \nfunction event_1606_12651()\n    \nend\n\n","functions":["event_1606_12569","event_1606_12651"],"quest_calls":[],"dialogue_calls":[]},"scenario/1607.lua":{"source":"\n\n-- Téléportation\n-- \nfunction event_1607_12589()\n    \nend\n\n","functions":["event_1607_12589"],"quest_calls":[],"dialogue_calls":[]},"scenario/1608.lua":{"source":"playerId=Context.getPlayer()\r\n\r\nfunction galdePlay(lenaldA,lenaldB,sentinelleA,sentinelleB)\r\n\tAPS_ID = {1112,1113,1114,1115,1116,1117}\r\n\r\n\tresultA=random(6)+1\r\n\tresultB=random(6)+1\r\n\tresultC=random(6)+1\r\n\tresultD=random(6)+1\r\n\t\r\n\ttimeA=random(5)*100\r\n\ttimeB=random(5)*100\r\n\ttimeC=random(5)*100\r\n\ttimeD=random(5)*100\r\n\r\n\tinvoke(timeA,1,\"Particle.addParticleSystemToTarget\",APS_ID[result], lenaldA, 1)\r\n\tinvoke(timeB,1,\"Particle.addParticleSystemToTarget\",APS_ID[result], lenaldB, 1)\r\n\tinvoke(timeC,1,\"Particle.addParticleSystemToTarget\",APS_ID[result], sentinelleA, 1)\r\n\tinvoke(timeD,1,\"Particle.addParticleSystemToTarget\",APS_ID[result], sentinelleB, 1)\r\n\t\r\n\tinvoke(5000,1,\"galdePlay\",lenaldA,lenaldB,sentinelleA,sentinelleB)\r\nend\n\n-- [INITIALISATION] Variables\n-- \nfunction event_1608_12723()\n    \nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_1608_12766(lenaldA)\n    --Mobile.addMobileCreationCallback(lenaldA, \"galdePlay\", lenaldA,lenaldB,sentinelleA,sentinelleB)\r\nend\n\n-- Le joueur sort de sa cellule\n-- \nfunction event_1608_12592()\n    \nend\n\n-- Le joueur sort de sa cellule - Cinématique\n-- \nfunction event_1608_12811(lenaldA, lenaldB, sentinelleA, sentinelleB)\n    function djangoBubbleStart(mob,text)\r\n    \tdjangoBubble=BubbleText.showText(mob, text, 0, 40, false)\r\n    \tinvoke(5000,1,\"BubbleText.close\",djangoBubble)\r\n    end\r\n    \r\n    invoke(2000,1,\"djangoBubbleStart\",lenaldB, \"quest.wabbit.sentinelle.lenald.01\")\r\n    \r\n    partLenaldA=Particle.addParticleSystemToTarget(15401, lenaldA)\r\n    partLenaldB=Particle.addParticleSystemToTarget(15401, lenaldB)\r\n    partSentinelleA=Particle.addParticleSystemToTarget(15401, sentinelleA)\r\n    partSentinelleB=Particle.addParticleSystemToTarget(15401, sentinelleB)\r\n    invoke(2000,1,\"Particle.removeParticleSystem\",partLenaldA)\r\n    invoke(2000,1,\"Particle.removeParticleSystem\",partLenaldB)\r\n    invoke(2000,1,\"Particle.removeParticleSystem\",partSentinelleA)\r\n    invoke(2000,1,\"Particle.removeParticleSystem\",partSentinelleB)\r\n    \r\n    Mobile.setMobileDirection(lenaldA, 7)\r\n    Mobile.setMobileDirection(lenaldB, 7)\r\n    \r\n    Camera.attachCameraToMobile(lenaldB)\r\n    UI.manageFrame(\"World\", false)\r\n    \r\nend\n\n-- Le joueur sort de sa cellule - Combat\n-- \nfunction event_1608_12820()\n    UI.manageFrame(\"World\", true)\nend\n\n-- Lancement du combat\n-- \nfunction event_1608_12593(djangoId)\n    Mobile.setMobileVisible(djangoId, false)\r\n    Camera.attachCameraToMobile(playerId)\r\nend\n\n-- Joueur tue les gardes\n-- \nfunction event_1608_12591(djangoId)\n    Mobile.setMobileVisible(djangoId, true)\r\n    \r\n    function djangoBubbleStart(mob,text)\r\n    \t--djangoBubble=BubbleText.showText(mob, text, 0, 40, false)\r\n    \tdjangoBubble=BubbleText.setCharacterSpeak(mob, text)\r\n    \tinvoke(5000,1,\"BubbleText.close\",djangoBubble)\r\n    end\r\n    \r\n    invoke(2000,1,\"djangoBubbleStart\",djangoId, \"quest.wabbit.django.02\")\r\n    invoke(8000,1,\"djangoBubbleStart\",djangoId, \"quest.wabbit.django.03\")\r\n    \r\n    invoke(2000, 1, \"UI.manageFrame\",\"World\", false)\nend\n\n-- Django se barre\n-- \nfunction event_1608_12752(djangoId)\n    UI.manageFrame(\"World\", true)\nend\n\n-- Django disparaît\n-- \nfunction event_1608_12753(djangoId)\n    \nend\n\n-- Le joueur parle à Django - Pose de la WP\n-- \nfunction event_1608_12756(djangoId)\n    BubbleText.showText(djangoId, \"quest.wabbit.django.01\", 0, 40, false)\r\nend\n\n-- Le joueur parle à Django - Retrait de la WP\n-- \nfunction event_1608_12757(djangoId)\n    \nend\n\n","functions":["galdePlay","event_1608_12723","event_1608_12766","event_1608_12592","event_1608_12811","djangoBubbleStart","event_1608_12820","event_1608_12593","event_1608_12591","djangoBubbleStart","event_1608_12752","event_1608_12753","event_1608_12756","event_1608_12757"],"quest_calls":[],"dialogue_calls":[]},"scenario/1609.lua":{"source":"playerId=Context.getPlayer()\r\n\r\nfunction wobotPlayInit(mob,anim)\r\n\tif anim==0 then\r\n\t\tMobile.setMobileAnimationSpeed(mob, 0)\r\n\telseif anim==1 then\r\n\t\tMobile.setMobileAnimationSpeed(mob, 1)\r\n\tend\r\nend\n\n-- [INTIALISATION] Variables\n-- \nfunction event_1609_12951()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_1609_12595(wobotA, wobotB, wobotC, wobotD, wobotE, wobotF, wobotAnim)\n    anim = toLong(wobotAnim)\r\n    \r\n    Mobile.addMobileCreationCallback(wobotA, \"wobotPlayInit\", wobotA, anim)\r\n    Mobile.addMobileCreationCallback(wobotB, \"wobotPlayInit\", wobotB, anim)\r\n    Mobile.addMobileCreationCallback(wobotC, \"wobotPlayInit\", wobotC, anim)\r\n    Mobile.addMobileCreationCallback(wobotD, \"wobotPlayInit\", wobotD, anim)\r\n    Mobile.addMobileCreationCallback(wobotE, \"wobotPlayInit\", wobotE, anim)\r\n    Mobile.addMobileCreationCallback(wobotF, \"wobotPlayInit\", wobotF, anim)\r\nend\n\n-- Le joueur monte dans un Wobot\n-- \nfunction event_1609_12596(playerX, playerY, playerZ)\n    Particle.addParticleSystemToTarget(800174, playerId, 1)\r\n    --x,y,z=Mobile.getMobilePosition(playerId)\r\n    --Mobile.setMobilePosition(playerId, x+1, y, z+2)\r\n    Mobile.setMobileDirection(playerId, 1)\r\n    trace(\"POSITION DU JOUEUR: \",playerX, playerY, playerZ)\nend\n\n-- La porte est ouverte\n-- \nfunction event_1609_12599()\n    \nend\n\n-- Lancement du combat\n-- \nfunction event_1609_12637()\n    \nend\n\n-- Début du combat\n-- \nfunction event_1609_12632()\n    \nend\n\n-- [SCENE] Le joueur marche sur le trigger\n-- \nfunction event_1609_12654(sylarghId)\n    --Particle.addParticleSystemToTarget(800174, sylarghId)\r\nend\n\n-- [SCENE] Sylargh Arrive au waypoint 0\n-- \nfunction event_1609_12655(sylarghId, wobotA, wobotB, wobotC, wobotD, wobotE, wobotF)\n    function mobBubbleStart(mob,text)\r\n    \tmobBubble=BubbleText.setCharacterSpeak(mob, text)\r\n    \tinvoke(5000,1,\"BubbleText.close\",mobBubble)\r\n    end\r\n    \r\n    Camera.attachCameraToMobile(sylarghId)\r\n    \r\n    invoke(500,1,\"mobBubbleStart\",sylarghId, \"quest.harebourg.wabbit.sylargh.01\")\r\n    invoke(5500,1,\"mobBubbleStart\",sylarghId, \"quest.harebourg.wabbit.sylargh.02\")\r\n    \r\n    --Sylargh boost les Wobots\r\n    invoke(5500, 1, \"Mobile.setMobileAnimation\", sylarghId, \"AnimSort-Charge\")\r\n    \r\n    invoke(5500,1,\"Particle.addParticleSystemToTarget\",-1504035711, sylarghId, 1)\r\n    invoke(5500,1,\"Effect.createFullScreenSprite\",500, 1800, 50, 0, 0, 0, 0.5)\r\n    \r\n    invoke(6200,1,\"Effect.createCameraShakeEffect\",100, 800, 300, 3)\r\n    \r\n    invoke(6200,1,\"Particle.addParticleSystem\",-1504035700, 1, -78, 8, 1)\r\n    invoke(6200,1,\"Particle.addParticleSystem\",-1504035700, 1, -87, 8, 1)\r\n    invoke(6200,1,\"Particle.addParticleSystem\",-1504035700, 10, -76, 8, 1)\r\n    inv