()\n    \nend\n\n","functions":["displayPath","event_1621_22029","event_1621_22030","event_1621_22031","event_1621_22032","event_1621_22033","event_1621_22034"],"quest_calls":[],"dialogue_calls":[]},"scenario/1622.lua":{"source":"\n\n-- [INITIALISATION] Variables\n-- \nfunction event_1622_12789()\n    \nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_1622_12772()\n    \nend\n\n-- Le joueur utilise la porte\n-- \nfunction event_1622_12776()\n    \nend\n\n","functions":["event_1622_12789","event_1622_12772","event_1622_12776"],"quest_calls":[],"dialogue_calls":[]},"scenario/1623.lua":{"source":"\n\n-- Variables\n-- \nfunction event_1623_12787()\n    \nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_1623_12778()\n    \nend\n\n-- [CHUTE]\n-- \nfunction event_1623_12782(playerPosition)\n    function startChute(id)\n    \tUI.manageFrame(\"World\", false)\n    \tMobile.setMobileNext4Direction(id)\n    \tMobile.setMobileAnimation(id, \"AnimIncarnam-Chute-Debut\", \"Server.triggerEvent\", 33360)\n    end\n    \n    local playerId = Context.getLeaderId()\n    \n    if (Mobile.isMoving(playerId)) then\n    \tMobile.onPathEnded(playerId, \"startChute\", playerId)\n    \tActor.stopMovingActor(playerId)\n    else\n    \tstartChute(playerId)\n    end\nend\n\n-- [SCENE] Le joueur tombe\n-- \nfunction event_1623_12783()\n    function endChute()\r\n    \tlocal playerId = Context.getLeaderId()\r\n    \t\r\n    \tMobile.setMobileNext4Direction(playerId)\r\n    \tMobile.setMobileAnimation(playerId, \"AnimIncarnam-Chute-Fin\", \"UI.manageFrame\", \"World\", true)\r\n    end\r\n    \r\n    --Juste histoire d'être sûr qu'on va pas broken le client du joueur\r\n    invoke(3000, 1, \"UI.manageFrame\", \"World\", true)\r\n    endChute()\nend\n\n-- [WA] Le Wa déclame son texte\n-- \nfunction event_1623_12788(waId)\n    function waBubbleStart(mob)\r\n    \tlocal boucle = math.random(1, 5)\r\n    \t\r\n    \tif boucle==1 then\r\n    \t\twaBubble=BubbleText.setCharacterSpeak(mob, \"quest.wabbit.wa.waccouwci.01\")\r\n    \telseif boucle==2 then\r\n    \t\twaBubble=BubbleText.setCharacterSpeak(mob, \"quest.wabbit.wa.waccouwci.02\")\t\r\n    \telseif boucle==3 then\r\n    \t\twaBubble=BubbleText.setCharacterSpeak(mob, \"quest.wabbit.wa.waccouwci.03\")\r\n    \telseif boucle==4 then\r\n    \t\twaBubble=BubbleText.setCharacterSpeak(mob, \"quest.wabbit.wa.waccouwci.04\")\r\n    \telseif boucle==5 then\r\n    \t\twaBubble=BubbleText.setCharacterSpeak(mob, \"quest.wabbit.wa.waccouwci.05\")\r\n    \tend\r\n    end\r\n    \r\n    waBubbleStart(waId)\nend\n\n-- \n-- \nfunction event_1623_19809()\n    \nend\n\n","functions":["event_1623_12787","event_1623_12778","event_1623_12782","startChute","event_1623_12783","endChute","event_1623_12788","waBubbleStart","event_1623_19809"],"quest_calls":[],"dialogue_calls":[]},"scenario/1624.lua":{"source":"\n\n-- [EVENT] Salle 04 (BOSS) - Démarrage du combat - Initialisation des variables\n-- \nfunction event_1624_12825()\n    \nend\n\n-- [EVENT] Salle 04 (BOSS) - Démarrage du combat - Pose du glyphe gameplay (590)\n-- \nfunction event_1624_12826()\n    \nend\n\n-- [INIT] Variables globales\n-- \nfunction event_1624_21837()\n    \nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_1624_21838()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 01\n-- \nfunction event_1624_21839(room)\n    \nend\n\n-- USER_GROUP_KILLED - Salle 02\n-- \nfunction event_1624_21840(room)\n    \nend\n\n-- USER_GROUP_KILLED - Salle 03\n-- \nfunction event_1624_21841()\n    \nend\n\n-- Déplace le joueur vers la salle suivante\n-- \nfunction event_1624_21842()\n    \nend\n\n","functions":["event_1624_12825","event_1624_12826","event_1624_21837","event_1624_21838","event_1624_21839","event_1624_21840","event_1624_21841","event_1624_21842"],"quest_calls":[],"dialogue_calls":[]},"scenario/1626.lua":{"source":"\n\n-- Variables\n-- \nfunction event_1626_12861()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_1626_12840(