ILLED - Salle 02\n-- \nfunction event_1628_21834(room)\n    \nend\n\n-- USER_GROUP_KILLED - Salle 03\n-- \nfunction event_1628_21835()\n    \nend\n\n-- Déplace le joueur vers la salle suivante\n-- \nfunction event_1628_21836()\n    \nend\n\n","functions":["event_1628_21831","event_1628_21832","event_1628_21833","event_1628_21834","event_1628_21835","event_1628_21836"],"quest_calls":[],"dialogue_calls":[]},"scenario/1632.lua":{"source":"\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_1632_12956()\n    \nend\n\n-- [INITIALISATION] Déclenchement du combat contre Bohowt si le joueur a la quête\n-- \nfunction event_1632_12958()\n    \nend\n\n","functions":["event_1632_12956","event_1632_12958"],"quest_calls":[],"dialogue_calls":[]},"scenario/1638.lua":{"source":"\n\n-- Téléportation chez Kralaman\n-- \nfunction event_1638_13030()\n    \nend\n\n","functions":["event_1638_13030"],"quest_calls":[],"dialogue_calls":[]},"scenario/1639.lua":{"source":"\n\n-- Téléportation chez Lardevil\n-- \nfunction event_1639_13031()\n    \nend\n\n","functions":["event_1639_13031"],"quest_calls":[],"dialogue_calls":[]},"scenario/1640.lua":{"source":"\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_1640_13160()\n    \nend\n\n-- [EVENT] Verrouillage de la Porte\n-- \nfunction event_1640_13161()\n    \nend\n\n","functions":["event_1640_13160","event_1640_13161"],"quest_calls":[],"dialogue_calls":[]},"scenario/1641.lua":{"source":"apsId = 71098002\r\napsOneId = 0\r\napsTwoId = 0\r\napsThreeId = 0\r\napsFourId = 0\r\n\r\nfunction displayDoor()\r\n\tapsOneId = Particle.addParticleSystem(apsId, 1, 1, 0)\r\n\tapsTwoId = Particle.addParticleSystem(apsId, 1, 1, 3)\r\n\tapsThreeId = Particle.addParticleSystem(apsId, 1, 1, 6)\r\n\tapsFourId = Particle.addParticleSystem(apsId, 1, 1, 9)\r\nend\r\n\r\nfunction hideDoor()\r\n\tParticle.removeParticleSystem(apsOneId)\r\n\tParticle.removeParticleSystem(apsTwoId)\r\n\tParticle.removeParticleSystem(apsThreeId)\r\n\tParticle.removeParticleSystem(apsFourId)\r\nend\r\n\r\nbubbleSteleInfoId = 0\r\n\r\nfunction closeSteleInfo()\r\n\tif (bubbleSteleInfoId ~= nil  and bubbleSteleInfoId ~= 0) then BubbleText.close(bubbleSteleInfoId) end\r\nend\r\n\r\nfunction onSteleInfoClosed()\r\n\tif (bubbleSteleInfoId ~= nil  and bubbleSteleInfoId ~= 0) then bubbleSteleInfoId = 0 end\r\nend\r\n\r\nfunction updateSteleInfo(stateInfoId, forceDisplayUI)\r\n\r\n\tif (bubbleSteleInfoId == 0) then\r\n\t\tbubbleSteleInfoId = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_WEST\", 0, -60, false, 2147483647, true, \"interactiveBubbleDialog5\", 30000, 25000, \"onSteleInfoClosed\")\r\n\tend\r\n\r\n\tBubbleText.setText(bubbleSteleInfoId, stateInfoId)\r\n\t\r\n\tif (forceDisplayUI) then BubbleText.show(bubbleSteleInfoId) end\r\nend\n\n-- [INIT] Variables & Constantes\n-- \nfunction event_1641_21757()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_1641_13162()\n    displayDoor()\nend\n\n-- INTERACTIVE_ELEMENT_ACTIVATION - Ouverture de la porte\n-- \nfunction event_1641_21756(door)\n    trace(\"OUVERTURE DE LA PORTE\")\r\n    \r\n    hideDoor()\nend\n\n-- MONSTER_ACTION_EVENT - Lancement du combat\n-- on skippe la cinématique pour tout le monde \nfunction event_1641_21748()\n    skipCinematic()\nend\n\n-- FIGHT_ENDED - Rend les monstres inattaquables\n-- \nfunction event_1641_21750()\n    \nend\n\n-- [FIGHT] Défaite du combat - Reset les stèles\n-- \nfunction event_1641_21751()\n    \nend\n\n-- [STELE] Le joueur examine une stèle\n-- \nfunction event_1641_21807(steleCount, steleStateId)\n    local steleCount = toLong(steleCount)\r\n    local steleStateId = toLong(steleStateId)\r\n    \r\n    if (steleCount == 0) then\r\n    UI.openRewardsDialog(\"stele.description.tour\")\r\n    UI.addReward(29864)\r\n    UI.addReward(29856, \"stele.reward.stasis.21\")\r\n    UI.addReward(27083, \"stele.reward.stasis.21\")\r\n    \r\n    elseif (steleCount == 1) then\r\n    UI.openRewardsDialog(\"stele.description.tour\")\r\n    UI.addReward(29861)\r\n    UI.addReward(29854, \"stele.reward.stasis.21\")\r\n    UI.addReward(27083, \"stele.reward.stasis.21\")\r\n    \r\n    elseif (steleCount == 2) then\r\n    UI.openRewardsDialog(\"stele.description.tour\")\r\n    UI.addReward(29852)\r\n    UI.addReward(29863, \"stele.reward.stasis.21\")\r\n    UI.addReward(27083, \"stele.reward.stasis.21\")\r\n    \r\n    elseif (steleCount == 3) then\r\n    UI.openRewardsDialog(\"stele.description.tour\")\r\n    UI.addReward(29858)\r\n    UI.addReward(29866, \"stele.reward.stasis.21\")\r\n    UI.addReward(27083, \"stele.reward.stasis.21\")\r\n    \r\n    else\r\n    \r\n    end\r\n    \r\n    local stateInfoId = \"stele.state.description.\" .. toString(steleStateId)\r\n    \r\n    updateSteleInfo(stateInfoId, true)\nend\n\n-- [STELE] Le joueur active une stèle\n-- \nfunction event_1641_21752(steleCount, steleStateId)\n    local steleCount = toLong(steleCount)\r\n    local steleStateId = toLong(steleStateId)\r\n    \r\n    if (steleCount == 1) then\r\n    UI.openRewardsDialog(\"stele.description.tour\")\r\n    UI.addReward(29864)\r\n    UI.addReward(29856, \"stele.reward.stasis.21\")\r\n    UI.addReward(27083, \"stele.reward.stasis.21\")\r\n    \r\n    elseif (steleCount == 2) then\r\n    UI.openRewardsDialog(\"stele.description.tour\")\r\n    UI.addReward(29861)\r\n    UI.addReward(29854, \"stele.reward.stasis.21\")\r\n    UI.addReward(27083, \"stele.reward.stasis.21\")\r\n    \r\n    elseif (steleCount == 3) then\r\n    UI.openRewardsDialog(\"stele.description.tour\")\r\n    UI.addReward(29852)\r\n    UI.addReward(29863, \"stele.reward.stasis.21\")\r\n    UI.addReward(27083, \"stele.reward.stasis.21\")\r\n    \r\n    elseif (steleCount == 4) then\r\n    UI.openRewardsDialog(\"stele.description.tour\")\r\n    UI.addReward(29858)\r\n    UI.addReward(29866, \"stele.reward.stasis.21\")\r\n    UI.addReward(27083, \"stele.reward.stasis.21\")\r\n    \r\n    else\r\n    \r\n    end\r\n    \r\n    local stateInfoId = \"stele.state.description.\" .. toString(steleStateId)\r\n    \r\n    updateSteleInfo(stateInfoId, true)\nend\n\n-- [STELE] Refresh des APS pour Stèles\n-- \nfunction event_1641_21753()\n    \nend\n\n-- [STASIS] DUNGEON_DIFFICULTY_CHANGED - Reset les stèles\n-- \nfunction event_1641_21754()\n    \nend\n\n","functions":["displayDoor","hideDoor","closeSteleInfo","onSteleInfoClosed","updateSteleInfo","event_1641_21757","event_1641_13162","event_1641_21756","event_1641_21748","event_1641_21750","event_1641_21751","event_1641_21807","event_1641_21752","event_1641_21753","event_1641_21754"],"quest_calls":["UI.openRewardsDialog(\"stele.description.tour\")\r","UI.openRewardsDialog(\"stele.description.tour\")\r","UI.openRewardsDialog(\"stele.description.tour\")\r","UI.openRewardsDialog(\"stele.description.tour\")\r","UI.openRewardsDialog(\"stele.description.tour\")\r","UI.openRewardsDialog(\"stele.description.tour\")\r","UI.openRewardsDialog(\"stele.description.tour\")\r","UI.openRewardsDialog(\"stele.description.tour\")\r"],"dialogue_calls":[]},"scenario/1645.lua":{"source":"\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_1645_13080()\n    \nend\n\n-- [Bworkball] Match Entraînement (Difficulté 0) - Lancement du match\n-- \nfunction event_1645_13081()\n    UI.loadTutorialDialog(\"tutoBworkballInitiation\",\"tutorial.bworkball.initiation.title\",\"tutorial.bworkball.initiation.description\")\nend\n\n-- [Bworkball] Match Difficulté 1 - Lancement du match\n-- \nfunction event_1645_13084()\n    \nend\n\n-- [Bworkball] Match Difficulté 1 - Lancement pas autorisé\n-- \nfunction event_1645_13252()\n    UI.writeLocalisedInChat(\"quest.bworkball.match0notcomplete\")\nend\n\n-- [Bworkball] Match Difficulté 2 - Lancement du match\n-- \nfunction event_1645_13085()\n    \nend\n\n-- [Bworkball] Match Difficulté 2 - Lancement pas autorisé\n-- \nfunction event_1645_13253()\n    UI.writeLocalisedInChat(\"quest.bworkball.match1notcomplete\")\nend\n\n-- [Bworkball] Combat Démarré - Pose des zones d'effets\n-- \nfunction event_1645_13083()\n    \nend\n\n-- [Bworkball][TUTO] Recrutement d'un Bloqueur\n-- \nfunction event_1645_13261()\n    UI.loadTutorialDialog(\"tutoBworkballBloqueur\",\"tutorial.bworkball.bloqueur.title\",\"tutorial.bworkball.bloqueur.description\")\nend\n\n-- [Bworkball][TUTO] Recrutement d'un Passeur\n-- \nfunction event_1645_13262()\n    UI.loadTutorialDialog(\"tutoBworkballPasseur\",\"tutorial.bworkball.passeur.title\",\"tutorial.bworkball.passeur.description\")\nend\n\n-- [Bworkball][TUTO] Recrutement d'un Receveur\n-- \nfunction event_1645_13263()\n    UI.loadTutorialDialog(\"tutoBworkballReceveur\",\"tutorial.bworkball.receveur.title\",\"tutorial.bworkball.receveur.description\")\nend\n\n-- Joueur quitte instance\n-- \nfunction event_1645_16383()\n    \nend\n\n","functions":["event_1645_13080","event_1645_13081","event_1645_13084","event_1645_13252","event_1645_13085","event_1645_13253","event_1645_13083","event_1645_13261","event_1645_13262","event_1645_13263","event_1645_16383"],"quest_calls":[],"dialogue_calls":[]},"scenario/1646.lua":{"source":"\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_1646_13086()\n    \nend\n\n-- Joueur clique sur le cadavre - Création combat 1\n-- \nfunction event_1646_13226()\n    \nend\n\n-- Joueur clique sur Éboulis du site de fouille - Création du combat 2\n-- \nfunction event_1646_13093()\n    \nend\n\n-- Joueur clique sur Corps du chef de chantier - Création du combat de fin\n-- \nfunction event_1646_13087()\n    \nend\n\n-- Victoire combat de fin\n-- \nfunction event_1646_13088()\n    \nend\n\n-- [destruction IE rocher solide] destruction de l'ie\n-- \nfunction event_1646_13089()\n    \nend\n\n","functions":["event_1646_13086","event_1646_13226","event_1646_13093","event_1646_13087","event_1646_13088","event_1646_13089"],"quest_calls":[],"dialogue_calls":[]},"scenario/1647.lua":{"source":"nbFight = 0\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_1647_13108()\n    \nend\n\n-- [EVENT] Salle 1 - Victoire\n-- \nfunction event_1647_13109()\n    \nend\n\n-- [EVENT] Salle 1 - Ouverture de la porte\n-- \nfunction event_1647_13110()\n    \nend\n\n-- [EVENT] Salle 2 - Victoire\n-- \nfunction event_1647_13111()\n    \nend\n\n-- [EVENT] Salle 2 - Ouverture de la porte\n-- \nfunction event_1647_13112()\n    \nend\n\n-- [EVENT] Salle 3 - Victoire\n-- \nfunction event_1647_13113()\n    \nend\n\n-- [EVENT] Salle 3 - Ouverture de la porte\n-- \nfunction event_1647_13114()\n    \nend\n\n-- [EVENT] Salle 4 - Victoire\n-- \nfunction event_1647_13115()\n    \nend\n\n-- [EVENT] Salle 4 - Activation du TP de sortie\n-- \nfunction event_1647_13116()\n    \nend\n\n","functions":["event_1647_13108","event_1647_13109","event_1647_13110","event_1647_13111","event_1647_13112","event_1647_13113","event_1647_13114","event_1647_13115","event_1647_13116"],"quest_calls":[],"dialogue_calls":[]},"scenario/1648.lua":{"source":"\n\n-- [INIT] Variables Globales\n-- \nfunction event_1648_21933()\n    \nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_1648_13117(room)\n    room = toLong(room)\r\n    \r\n    if (room == 2 or room < 0) then\r\n    \tWorld.setPictoAlpha(23, -59, -10, 0, 1000)\r\n    end\nend\n\n-- USER_GROUP_KILLED - Salle 01\n-- \nfunction event_1648_21934(room)\n    World.setPictoAlpha(23, -59, -10, 0, 1000)\nend\n\n-- USER_GROUP_KILLED - Salle 02 - BOSS\n-- \nfunction event_1648_21935()\n    \nend\n\n-- Déplace le joueur vers la salle suivante\n-- \nfunction event_1648_21936()\n    \nend\n\n-- FIGHT_ENTER_ACTION_PHASE - Applique l'état \"Donjon\" (Salle 1)\n-- \nfunction event_1648_21937()\n    \nend\n\n-- [ARCHI] Apparition de l'Archimonstre\n-- \nfunction event_1648_23949()\n    \nend\n\n","functions":["event_1648_21933","event_1648_13117","event_1648_21934","event_1648_21935","event_1648_21936","event_1648_21937","event_1648_23949"],"quest_calls":[],"dialogue_calls":[]},"scenario/1649.lua":{"source":"\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_1649_13126()\n    \nend\n\n","functions":["event_1649_13126"],"quest_calls":[],"dialogue_calls":[]},"scenario/1650.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\n\n-- [INIT] Variables\n-- \nfunction event_1650_19846()\n    \nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_1650_13127()\n    invoke(1500, 1, \"UI.openInfoDialog\",\"quest.DomaineSauvage.ExplicationLebbocqTitle\", \"quest.DomaineSauvage.ExplicationLebbocq\")\nend\n\n-- Le joueur active la maquette - ACH 1677 OBJ 3107\n-- \nfunction event_1650_13128()\n    \nend\n\n-- Le joueur active la maquette - Cinématique\n-- \nfunction event_1650_19851()\n    startCinematicContext(1)\r\n    \r\n    invoke_custom(100, 1, \"Camera.setWorldTarget\", 2, -24, 0)\r\n    \r\n    invoke_custom(1000, 1, \"Sound.playSound\", 600196,  50)\r\n    invoke_custom(1000, 1, \"Particle.addParticleSystemToIe\", 800398, 20428, 1)\r\n    invoke_custom(1000, 1, \"Particle.addParticleSystemToIe\", 7723002, 20430, 1)\r\n    \r\n    invoke_custom(5000, 1, \"Effect.createCameraShakeEffect\", 200, 300, 200, 3)\r\n    invoke_custom(5000, 1, \"Sound.playSound\", 502000002001,  40)\nend\n\n-- La porte s'ouvre\n-- \nfunction event_1650_13129(CdgSqueId)\n    \nend\n\n-- Arrivée du CDG Squelette au waypoint\n-- \nfunction event_1650_13132()\n    local playerId = Context.getLeaderId()\r\n    \r\n    stopCinematicContext(nil, playerId)\nend\n\n-- Victoire Combat CDG Squelette - Unlock la porte\n-- \nfunction event_1650_13251()\n    \nend\n\n-- Fin Combat CDG Squelette - Reset Variables\n-- \nfunction event_1650_19847()\n    \nend\n\n-- Lancement manuel du combat CDG Squelette (si le joueur a perdu)\n-- \nfunction event_1650_13131()\n    \nend\n\n-- Le joueur creuse et trouve le bâton Bwork - ACH 1677 OBJ 3105\n-- \nfunction event_1650_13164()\n    UI.writeLocalisedInChat(\"quest.DomaineSauvage.BatonBwork\")\nend\n\n-- Le joueur créer le bourdon Bwork - ACH 1677 OBJ 3108\n-- \nfunction event_1650_13165()\n    \nend\n\n-- Le joueur fusionne les parties du médaillon - ACH 1677 OBJ 3106\n-- \nfunction event_1650_19845()\n    \nend\n\n-- Le joueur lis la note de Sufokia - TP du joueur - ACH 1677 OBJ 3109\n-- \nfunction event_1650_13192()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_1650_19846","event_1650_13127","event_1650_13128","event_1650_19851","event_1650_13129","event_1650_13132","event_1650_13251","event_1650_19847","event_1650_13131","event_1650_13164","event_1650_13165","event_1650_19845","event_1650_13192"],"quest_calls":[],"dialogue_calls":[]},"scenario/1651.lua":{"source":"\r\nplayerId=Context.getPlayer()\r\n\r\nfunction shakeCam()\r\n\tinstanceId = Context.getPlayerInstanceId()\t\r\n\tif instanceId==715 then\r\n\t\tshakeEffectId = Effect.createCameraShakeEffect(400, 600, 500, 6)\r\n\t\tinvoke(60000, 1, \"shakeCam\")\r\n\tend\r\nend\n\n-- Variables globales\n-- \nfunction event_1651_13133()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_1651_13134()\n    invoke(3000, 1, \"shakeCam\")\nend\n\n-- Déclenchement du combat contre les excarnés\n-- \nfunction event_1651_13135(ExcarneSufokiaId)\n    Particle.addParticleSystemToTarget(800174,ExcarneSufokiaIdM,0)\r\n    Particle.addParticleSystemToTarget(800174,ExcarneSufokiaIdF,0)\r\n    Mobile.setMobileDirection(ExcarneSufokiaIdM,3)\r\n    Mobile.setMobileDirection(ExcarneSufokiaIdF,3)\nend\n\n-- Le combat se termine\n-- \nfunction event_1651_13137()\n    --FightEvent.addFightEndCallback(\"endFightFrizz\")\r\n    \r\n    --function endFightFrizz()\r\n    --\tServer.triggerEvent(12081)\r\n    --end\r\nend\n\n-- [COMBAT] Mort des excarnés\n-- \nfunction event_1651_13159()\n    \nend\n\n-- Lancement du combat contre Les excarnés\n-- \nfunction event_1651_13139()\n    \nend\n\n","functions":["shakeCam","event_1651_13133","event_1651_13134","event_1651_13135","event_1651_13137","endFightFrizz","event_1651_13159","event_1651_13139"],"quest_calls":[],"dialogue_calls":[]},"scenario/1653.lua":{"source":"nbFight = 0\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_1653_13166()\n    \nend\n\n-- [EVENT] Salle 1 - Victoire\n-- \nfunction event_1653_13167()\n    \nend\n\n-- [EVENT] Salle 1 - Ouverture de la porte\n-- \nfunction event_1653_13168()\n    World.setPictoAlpha(-16, 12, -6, 0, 1000)\nend\n\n-- [EVENT] Salle 2 - Victoire\n-- \nfunction event_1653_13169()\n    \nend\n\n-- [EVENT] Salle 2 - Ouverture de la porte\n-- \nfunction event_1653_13170()\n    World.setPictoAlpha(-4, 18, -18, 0, 1000)\nend\n\n-- [EVENT] Salle 3 - Victoire\n-- \nfunction event_1653_13171()\n    \nend\n\n-- [EVENT] Salle 3 - Ouverture Porte + Activation du TP de sortie\n-- \nfunction event_1653_13174()\n    \nend\n\n-- [Salle 1] Lancement du combat\n-- \nfunction event_1653_13244()\n    \nend\n\n-- [Salle 1] Combat Démarré\n-- \nfunction event_1653_13245()\n    \nend\n\n-- [Salle 2] Lancement du combat\n-- \nfunction event_1653_13246()\n    \nend\n\n-- [Salle 2] Combat Démarré\n-- \nfunction event_1653_13247()\n    \nend\n\n-- [Salle 3] Lancement du combat\n-- \nfunction event_1653_13248()\n    \nend\n\n-- [Salle 3] Combat Démarré\n-- \nfunction event_1653_13249()\n    \nend\n\n","functions":["event_1653_13166","event_1653_13167","event_1653_13168","event_1653_13169","event_1653_13170","event_1653_13171","event_1653_13174","event_1653_13244","event_1653_13245","event_1653_13246","event_1653_13247","event_1653_13248","event_1653_13249"],"quest_calls":[],"dialogue_calls":[]},"scenario/1654.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\n\n-- [INITIALISATION] Variables\n-- \nfunction event_1654_13175()\n    \nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_1654_13176()\n    \r\n    invoke(500, 1, \"UI.openInfoDialog\",\"tooltip.Temple.PopUp.Title\", \"tooltip.Temple.PopUp\")\r\n    \r\n    particleBossDoorOne = Particle.addParticleSystem(800406, -10, 23, 0, 0)\r\n    particleBossDoorTwo = Particle.addParticleSystem(800406, -11, 23, 0, 0)\r\n    particleBossDoorThree = Particle.addParticleSystem(800406, -12, 23, 0, 0)\r\n    \r\n    Particle.setRemoveWhenFar(particleBossDoorOne, false)\r\n    Particle.setRemoveWhenFar(particleBossDoorTwo, false)\r\n    Particle.setRemoveWhenFar(particleBossDoorThree, false)\r\n    \r\n    World.setPictoAlpha(29, 61, -21, 0, 1000)\nend\n\n-- [Mot de dieu] [CHUTE]\n-- \nfunction event_1654_13177()\n    function chuta(id)\r\n    \tMobile.setMobileVisible(id, false)\r\n    \tServer.triggerEvent(34427)\r\n    end\r\n    \r\n    function startChute(id)\r\n    \tUI.manageFrame(\"World\",false)\r\n    \tMobile.setMobileDirection(id, 7)\r\n    \tMobile.setMobileAnimation(id, \"AnimIncarnam-Chute-Debut\", \"chuta\", id)\r\n    end\r\n    \r\n    local playerId = Context.getLeaderId()\r\n    Actor.stopMovingActor(playerId)\r\n    startChute(playerId)\nend\n\n-- [Mot de dieu] [SCENE] Le joueur tombe\n-- \nfunction event_1654_13178()\n    function animChute(playerId)\r\n    \tMobile.setMobileVisible(playerId, true)\r\n    \tMobile.setMobileDirection(playerId, 7)\r\n    \tMobile.setMobileAnimation(playerId, \"AnimIncarnam-Chute-Fin\", \"animEnd\", playerId)\r\n    end\r\n    \r\n    function animEnd(playerId)\r\n    \tMobile.setMobileDirection(playerId, 7)\r\n    \tUI.manageFrame(\"World\",true)\r\n    end\r\n    \r\n    local playerId = Context.getLeaderId()\r\n    UI.manageFrame(\"World\", false)\r\n    Mobile.setMobileVisible(playerId, false)\r\n    invoke(2500, 1, \"animChute\", playerId)\r\n    invoke(5000, 1, \"Server.triggerEvent\", 34428)\nend\n\n-- [Mot de dieu] [SCENE] Le joueur tombe\n-- \nfunction event_1654_19488()\n    \nend\n\n-- [A1][EVENT] Victoire\n-- \nfunction event_1654_13195()\n    invoke(4000,1,\"Particle.addParticleSystem\",800202, 28, -18, 0, 0)\nend\n\n-- [A1][EVENT] Apparition du coffre\n-- \nfunction event_1654_13196()\n    \nend\n\n-- [A1][COFFRE] Obtention de la Clef\n-- \nfunction event_1654_13194()\n    local playerId = Context.getLeaderId()\r\n    Mobile.setMobileAnimation(playerId, \"AnimEmote-Victoire\")\nend\n\n-- [A2][PORTE] Ouverture de la porte\n-- \nfunction event_1654_13197()\n    \nend\n\n-- [A2][PNJ] Dialogue Archaologue Bonta - Autre Nation\n-- \nfunction event_1654_13208(archaBonta)\n    monster_bubbleId = BubbleText.prepareWakfuBubble(archaBonta, 0, 0)\r\n    BubbleText.setText(monster_bubbleId, \"quest.Domainesauvage.temple.archaologue.success\")\r\n    BubbleText.show(monster_bubbleId)\nend\n\n-- [A2][PNJ] Dialogue Archaologue Bonta - Meme Nation\n-- \nfunction event_1654_13209()\n    \nend\n\n-- [DB1][PORTE] Statue Gemme Amakna/Bonta - Activation Amakna\n-- \nfunction event_1654_13198()\n    local particleAmaknaId = 800405\r\n    particleAmakna = Particle.addParticleSystem(particleAmaknaId, -8, -19, 0, 0)\r\n    Particle.setRemoveWhenFar(particleAmakna, false)\nend\n\n-- [DB1][PORTE] Statue Gemme Amakna/Bonta - Activation Bonta\n-- \nfunction event_1654_13199()\n    local particleBontaID = 800403\r\n    particleBonta = Particle.addParticleSystem(particleBontaID, -8, -19, 0, 0)\r\n    Particle.setRemoveWhenFar(particleBonta, false)\nend\n\n-- [DB1][PORTE] Statue Gemme Brakmar/Sufokia - Activation Brakmar\n-- \nfunction event_1654_13200()\n    local particleBrakID = 800404\r\n    particleBrak = Particle.addParticleSystem(particleBrakID, -14, -19, 0, 0)\r\n    Particle.setRemoveWhenFar(particleBrak, false)\nend\n\n-- [DB1][PORTE] Statue Gemme Brakmar/Sufokia - Activation Sufokia\n-- \nfunction event_1654_13201()\n    local particleSufoID = 800402\r\n    particleSufo = Particle.addParticleSystem(800402, -14, -19, 0, 0)\r\n    Particle.setRemoveWhenFar(particleSufo, false)\nend\n\n-- [DB1][EVENT] Victoire\n-- \nfunction event_1654_13203()\n    invoke(4000,1,\"Particle.addParticleSystem\",800202, -14, -42, 12, 0)\nend\n\n-- [DB1][EVENT] Apparition du coffre\n-- \nfunction event_1654_13204()\n    \nend\n\n-- [DB1][COFFRE] Obtention de la Clef du Boss\n-- \nfunction event_1654_13205()\n    local playerId = Context.getLeaderId()\r\n    Mobile.setMobileAnimation(playerId, \"AnimEmote-Victoire\")\nend\n\n-- [BOSS1][PORTE] Ouverture de la porte du Boss\n-- \nfunction event_1654_13207()\n    Particle.removeParticleSystem(particleBossDoorOne,true)\r\n    Particle.removeParticleSystem(particleBossDoorTwo,true)\r\n    Particle.removeParticleSystem(particleBossDoorThree,true)\nend\n\n-- [B2][PNJ] Dialogue Archaologue Brakmar - Autre Nation\n-- \nfunction event_1654_13210(archaBrakmar)\n    monster_bubbleId = BubbleText.prepareWakfuBubble(archaBrakmar, 0, 0)\r\n    BubbleText.setText(monster_bubbleId, \"quest.Domainesauvage.temple.archaologue.success\")\r\n    BubbleText.show(monster_bubbleId)\nend\n\n-- [B2][PNJ] Dialogue Archaologue Brakmar - Meme Nation\n-- \nfunction event_1654_13211()\n    \nend\n\n-- [C4][PNJ] Dialogue Archaologue Amakna - Autre Nation\n-- \nfunction event_1654_13212(archaAmakna)\n    monster_bubbleId = BubbleText.prepareWakfuBubble(archaAmakna, 0, 0)\r\n    BubbleText.setText(monster_bubbleId, \"quest.Domainesauvage.temple.archaologue.success\")\r\n    BubbleText.show(monster_bubbleId)\nend\n\n-- [C4][PNJ] Dialogue Archaologue Amakna - Meme Nation\n-- \nfunction event_1654_13213()\n    \nend\n\n-- [C4][PNJ] Dialogue Archaologue Sufokia - Autre Nation\n-- \nfunction event_1654_13214(archaSufokia)\n    monster_bubbleId = BubbleText.prepareWakfuBubble(archaSufokia, 0, 0)\r\n    BubbleText.setText(monster_bubbleId, \"quest.Domainesauvage.temple.archaologue.success\")\r\n    BubbleText.show(monster_bubbleId)\nend\n\n-- [D1][PNJ] Dialogue Archaologue Sufokia - Meme Nation\n-- \nfunction event_1654_13215()\n    \nend\n\n-- [B2][PORTE] Ouverture de la porte\n-- \nfunction event_1654_