ration ou action phase)\n-- \nfunction event_1656_13351()\n    UI.openInfoDialog(\"donjon.shushu.rules.title\", \"donjon.shushu.rules.desc\")\nend\n\n-- [EVENT][SOFTCORE] Le joueur quitte l'instance - Pas de Combat en cours\n-- \nfunction event_1656_13350()\n    \nend\n\n-- [EVENT][HARDCORE] Le joueur quitte l'instance - Pas de Combat en cours\n-- \nfunction event_1656_13682()\n    \nend\n\n-- [EVENT] Variable - Début Phase Préparation\n-- \nfunction event_1656_13349()\n    \nend\n\n-- [EVENT] Variable - Fin Phase Préparation - Début Action Phase\n-- \nfunction event_1656_13352(fightId)\n    \nend\n\n-- [EVENT][SOFTCORE] Variable - Fin du combat\n-- \nfunction event_1656_13354()\n    \nend\n\n-- [EVENT]HARDCORE] Variable - Fin du combat\n-- \nfunction event_1656_13683()\n    \nend\n\n-- [EVENT] Fin du combat avec victoire des Joueurs - Validation Quête Journalière\n-- \nfunction event_1656_13355()\n    \nend\n\n-- [IE] Activation du hardcoreMode\n-- \nfunction event_1656_13679(mA, mB, mC, mD, mE, mF, mG, mH)\n    Particle.addParticleSystem(1016314, -2, -10, 4)\r\n    InteractiveElement.setAnimation(22294, \"AnimStatique_3\")\r\n    \r\n    Mobile.setMobileVisible(mA, false)\r\n    Mobile.setMobileVisible(mB, false)\r\n    Mobile.setMobileVisible(mC, false)\r\n    Mobile.setMobileVisible(mD, false)\r\n    Mobile.setMobileVisible(mE, false)\r\n    Mobile.setMobileVisible(mF, false)\r\n    Mobile.setMobileVisible(mG, false)\r\n    Mobile.setMobileVisible(mH, false)\nend\n\n-- [IE] Désactivation du hardcoreMode\n-- \nfunction event_1656_13680(mA, mB, mC, mD, mE, mF, mG, mH)\n    Particle.addParticleSystem(1016305, -2, -10, 3)\r\n    InteractiveElement.setAnimation(22294, \"AnimStatique_1\")\r\n    \r\n    Mobile.setMobileVisible(mA, false)\r\n    Mobile.setMobileVisible(mB, false)\r\n    Mobile.setMobileVisible(mC, false)\r\n    Mobile.setMobileVisible(mD, false)\r\n    Mobile.setMobileVisible(mE, false)\r\n    Mobile.setMobileVisible(mF, false)\r\n    Mobile.setMobileVisible(mG, false)\r\n    Mobile.setMobileVisible(mH, false)\nend\n\n-- [SYNCHRO][SOFTCORE] Le joueur entre dans l'instance - Le mode Softcore est actif\n-- \nfunction event_1656_13685(gA, gB, gC, gD, gE, gF, gG, gH)\n    InteractiveElement.setAnimation(22294, \"AnimStatique_1\")\r\n    \r\n    Mobile.addMobileCreationCallback(gA, \"hideMonster\", gA)\r\n    Mobile.addMobileCreationCallback(gB, \"hideMonster\", gB)\r\n    Mobile.addMobileCreationCallback(gC, \"hideMonster\", gC)\r\n    Mobile.addMobileCreationCallback(gD, \"hideMonster\", gD)\r\n    Mobile.addMobileCreationCallback(gE, \"hideMonster\", gE)\r\n    Mobile.addMobileCreationCallback(gF, \"hideMonster\", gF)\r\n    Mobile.addMobileCreationCallback(gG, \"hideMonster\", gG)\r\n    Mobile.addMobileCreationCallback(gH, \"hideMonster\", gH)\nend\n\n-- [SYNCHRO][HARDCORE] Le joueur entre dans l'instance - Le mode Hardcore est actif\n-- \nfunction event_1656_13684(gA, gB, gC, gD, gE, gF, gG, gH)\n    InteractiveElement.setAnimation(22294, \"AnimStatique_3\")\r\n    \r\n    Mobile.addMobileCreationCallback(gA, \"hideMonster\", gA)\r\n    Mobile.addMobileCreationCallback(gB, \"hideMonster\", gB)\r\n    Mobile.addMobileCreationCallback(gC, \"hideMonster\", gC)\r\n    Mobile.addMobileCreationCallback(gD, \"hideMonster\", gD)\r\n    Mobile.addMobileCreationCallback(gE, \"hideMonster\", gE)\r\n    Mobile.addMobileCreationCallback(gF, \"hideMonster\", gF)\r\n    Mobile.addMobileCreationCallback(gG, \"hideMonster\", gG)\r\n    Mobile.addMobileCreationCallback(gH, \"hideMonster\", gH)\nend\n\n","functions":["hideMonster","event_1656_13353","event_1656_13265","event_1656_13681","event_1656_13351","event_1656_13350","event_1656_13682","event_1656_13349","event_1656_13352","event_1656_13354","event_1656_13683","event_1656_13355","event_1656_13679","event_1656_13680","event_1656_13685","event_1656_13684"],"quest_calls":[],"dialogue_calls":[]},"scenario/1657.lua":{"source":"playerId = Context.getPlayer()\n\n-- [INIT] Variable