unction event_1665_13443(PNJ)\n    BubbleText.showText(PNJ, \"quest.saharach.petitpiedsHelp\", 0, 40, false)\nend\n\n-- Attaque des Cacterres\n-- \nfunction event_1665_13376(PNJ)\n    BubbleText.showText(PNJ, \"quest.saharach.petitpiedsHelp2\", 0, 40, false)\nend\n\n-- Lancement du Combat\n-- \nfunction event_1665_13444()\n    \nend\n\n","functions":["event_1665_13375","event_1665_13443","event_1665_13376","event_1665_13444"],"quest_calls":[],"dialogue_calls":[]},"scenario/1666.lua":{"source":"\n\n-- [INITIALISATION] Variables\n-- \nfunction event_1666_13486()\n    \nend\n\n-- [SPECIAL] Debut d'un combat - Application des sorts et des caractéristiques\n-- \nfunction event_1666_13400()\n    \nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_1666_13377()\n    Camera.setZoomFactor(0.6)\nend\n\n-- [TICK] Affichage Objectifs de Base\n-- \nfunction event_1666_13445()\n    UI.loadTutorialDialog(\"null\",\"quest.saharach.rules.title\",\"quest.saharach.rules.desc\")\nend\n\n-- [EVENT] Salle 1 - Trigger - Lancement combat\n-- \nfunction event_1666_13426()\n    \nend\n\n-- [EVENT] Salle 1 - Placement Glyphes - Affichage des Règles de Jeu\n-- \nfunction event_1666_13414()\n    UI.loadTutorialDialog(\"null\",\"quest.saharach.rules.title2\",\"quest.saharach.rules.desc2\")\nend\n\n-- [EVENT] Salle 1 - Victoire\n-- \nfunction event_1666_13378()\n    \nend\n\n-- [TICK] Salle 1 - Ouverture de la porte\n-- \nfunction event_1666_13379()\n    \nend\n\n-- [EVENT] Salle 1 - Défaite\n-- \nfunction event_1666_13438()\n    \nend\n\n-- [TICK] Salle 1 - Défaite - TP au début (avant le Trigger)\n-- \nfunction event_1666_13473()\n    \nend\n\n-- [EVENT] Salle 2 - Trigger - Affichage Bubble\n-- \nfunction event_1666_13439(Player)\n    BubbleText.showText(Player, \"quest.saharach.infiltration\", 0, 40, false)\nend\n\n-- [TICK] Salle 2 - Lancement combat\n-- \nfunction event_1666_13465()\n    \nend\n\n-- [EVENT] Salle 2 - Placement Glyphes - Affichage des challenges bonus\n-- \nfunction event_1666_13440()\n    UI.openRewardsDialog(\"defi.cimetiere.cacterre\")\r\n    UI.addReward(4266)\nend\n\n-- [EVENT] Salle 2 - Victoire\n-- \nfunction event_1666_13380()\n    \nend\n\n-- [TICK] Salle 2 - Ouverture de la porte\n-- \nfunction event_1666_13381()\n    \nend\n\n-- [EVENT] Salle 2 - Défaite\n-- \nfunction event_1666_13570()\n    \nend\n\n-- [TICK] Salle 2 - Défaite - TP au début (avant le Trigger)\n-- \nfunction event_1666_13571()\n    \nend\n\n-- [QP] Ouverture Porte - Clé non chargée\n-- \nfunction event_1666_13384(chef)\n    Camera.attachCameraToMobile(chef)\r\n    invoke(1000,1,\"BubbleText.showText\",chef,  \"quest.saharach.chefCacterre.cimetiere1\", 0, 40, false)\r\n    UI.manageFrame(\"World\", false)\r\n    invoke(5000,1,\"finCinematique\")\r\n    \r\n    function finCinematique()\r\n    \tUI.manageFrame(\"World\", true)\r\n    \tplayerId = Context.getPlayer()\r\n    \tCamera.attachCameraToMobile(playerId)\r\n    end\nend\n\n-- [QP] Invocation des esprits par le chef cacterre\n-- \nfunction event_1666_13484(chef)\n    Mobile.setMobileAnimation(chef, \"AnimComp-InvocEsprit\")\r\n    BubbleText.showText(chef,  \"quest.saharach.chefCacterre.cimetiere2\", 0, 40, false)\r\n    UI.manageFrame(\"World\", false)\r\n    \r\n    invoke(1500,1,\"invocation\")\r\n    \r\n    function invocation()\r\n    \tespritOneId = Mobile.generateClientMobileId()\r\n    \tespritTwoId = Mobile.generateClientMobileId()\r\n    \r\n    \tActor.createActor(espritOneId, 160802982, 31, 16, -32)\r\n    \tActor.createActor(espritTwoId, 160802982, 37, 16, -32)\r\n    \r\n    \tMobile.setMobileDirection(espritOneId, 1)\r\n    \tinvoke(500,1,\"Mobile.setMobileDirection\",espritTwoId, 5)\r\n    \t\r\n    \tMobile.setMobileAnimation(espritOneId, \"AnimSort-MultiTranche-Fin\")\r\n    \tinvoke(500, 1, \"Mobile.setMobileAnimation\",espritTwoId, \"AnimSort-MultiTranche-Fin\")\t\r\n    \r\n    \tinvoke(2000,1,\"BubbleText.showText\",chef,  \"quest.saharach.chefCacterre.cimetiere3\", 0, 40, false)\t\r\n    \tinvoke(3000,1,\"finCinematique\")\r\n    end\r\n    \r\n    function finCinematique()\r\n    \tUI.manageFrame(\"World\", true)\r\n    \tplayerId = Context.getPlayer()\r\n    \tCamera.attachCameraToMobile(playerId)\r\n    end\nend\n\n-- [QP] Invocation des esprits par le chef cacterre\n-- \nfunction event_1666_13485(chef)\n    --Mobile.setMobileAnimation(chef, \"AnimComp-InvocEsprit\")\r\n    BubbleText.showText(chef,  \"quest.saharach.chefCacterre.cimetiere3\", 0, 40, false)\r\n    --UI.manageFrame(\"World\", false)\r\n    \r\n    --invoke(1500,1,\"invocation\")\r\n    \r\n    function invocation()\r\n    \tplayerId = Context.getPlayer()\r\n    \tx,y,z = Mobile.getMobilePosition(playerId)\r\n    \t\r\n    \r\n    \r\n    \tActor.deleteActor(espritOneId)\r\n    \tActor.deleteActor(espritTwoId)\r\n    \t\r\n    \tespritOneId = Mobile.generateClientMobileId()\r\n    \tespritTwoId = Mobile.generateClientMobileId()\r\n    \tespritThreeId = Mobile.generateClientMobileId()\t\r\n    \r\n    \tActor.createActor(espritOneId, 160802982, x, y, z)\r\n    \tActor.createActor(espritTwoId, 160802982, x, y, z)\r\n    \tActor.createActor(espritThreeId, 160802982, x, y, z)\r\n    \r\n    \tMobile.setMobileDirection(espritOneId, 1)\r\n    \tinvoke(600,1,\"Mobile.setMobileDirection\",espritTwoId, 5)\r\n    \tinvoke(1200,1,\"Mobile.setMobileDirection\",espritThreeId, 5)\r\n    \t\r\n    \tMobile.setMobileAnimation(espritOneId, \"AnimSort-MultiTranche-Fin\")\r\n    \tinvoke(600, 1, \"Mobile.setMobileAnimation\",espritTwoId, \"AnimSort-MultiTranche-Fin\")\t\r\n    \tinvoke(1200, 1, \"Mobile.setMobileAnimation\",espritThreeId, \"AnimSort-MultiTranche-Fin\")\t\r\n    \r\n    \tinvoke(300,1,\"Actor.deleteActor\",espritOneId)\r\n    \tinvoke(900,1,\"Actor.deleteActor\",espritTwoId)\r\n    \tinvoke(1500,1,\"Actor.deleteActor\",espritThreeId)\r\n    \t\t\r\n    \tinvoke(2500,1,\"finCinematique\")\r\n    end\r\n    \r\n    function finCinematique()\r\n    \tUI.manageFrame(\"World\", true)\r\n    \tplayerId = Context.getPlayer()\r\n    end\nend\n\n-- [EXPLOIT] Salle 2 - Compteur de monstres tués\n-- \nfunction event_1666_13562(monsterKilled)\n    \nend\n\n-- [EXPLOIT] Salle 2 - Compteur de tour\n-- \nfunction event_1666_13566(turnCount)\n    \nend\n\n-- [EXPLOIT] Salle 2 - Victoire avec tous les monstres tués\n-- \nfunction event_1666_13564(monsterKilled)\n    \nend\n\n-- [EXPLOIT] Salle 2 - Victoire avec aucun monstre tué\n-- \nfunction event_1666_13565(monsterKilled)\n    \nend\n\n-- [EXPLOIT] Salle 2 - Victoire en moins de X tours\n-- \nfunction event_1666_13567(turnCount)\n    \nend\n\n-- [EVENT] Joueur quitte l'instance\n-- \nfunction event_1666_13585()\n    Camera.setZoomFactor(1)\nend\n\n","functions":["event_1666_13486","event_1666_13400","event_1666_13377","event_1666_13445","event_1666_13426","event_1666_13414","event_1666_13378","event_1666_13379","event_1666_13438","event_1666_13473","event_1666_13439","event_1666_13465","event_1666_13440","event_1666_13380","event_1666_13381","event_1666_13570","event_1666_13571","event_1666_13384","finCinematique","event_1666_13484","invocation","finCinematique","event_1666_13485","invocation","finCinematique","event_1666_13562","event_1666_13566","event_1666_13564","event_1666_13565","event_1666_13567","event_1666_13585"],"quest_calls":["UI.openRewardsDialog(\"defi.cimetiere.cacterre\")\r"],"dialogue_calls":[]},"scenario/1667.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\n\n-- [Enter instance] Initialisation des variables\n-- \nfunction event_1667_13539()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_1667_13386(PontUn, PontDeux)\n    passerelle = toLong(PontUn)\r\n    passerelleDeux = toLong(PontDeux)\r\n    local playerId = Context.getLeaderId()\r\n    \r\n    if passerelle==0 then\r\n    \tWorld.setPictoAlpha(-52, 23, -34, 0, 1)\r\n    \tWorld.setPictoAlpha(-53, 23, -34, 0, 1)\r\n    elseif passerelle==1 then\r\n    \tWorld.setPictoAlpha(-52, 23, -34, 1, 1)\r\n    \tWorld.setPictoAlpha(-53, 23, -34, 1, 1)\r\n    end\r\n    \r\n    if passerelleDeux==0 then\r\n    \tWorld.setPictoAlpha(-82, 27, -34, 0, 1)\r\n    \tWorld.setPictoAlpha(-83, 27, -34, 0, 1)\r\n    \r\n    elseif passerelleDeux==1 then\r\n    \tWorld.setPictoAlpha(-82, 27, -34, 1, 1)\r\n    \tWorld.setPictoAlpha(-83, 27, -34, 1, 1)\r\n    end\r\n    \r\n    -- **Ouuuuhlala... J'ai du manger un pichon pas frais moi..\r\n    BubbleText.showText(playerId, \"quest.saharach.hallucination.bubble0\", 0, 40, false)\nend\n\n-- [Trigger] Initialisation salle 1\n-- \nfunction event_1667_13492(CN, Milkar)\n    local cnId = toLong(CN)\r\n    local milkarId = toLong(Milkar)\r\n    local playerId = Context.getLeaderId()\r\n    \r\n    startCinematicContext(1.4, cnId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 13492)\r\n    \r\n    -- TU VAS PRENDRE CHER L'OGROUNET !!! HEHE !\r\n    invoke_custom(0001, 1, \"Mobile.setMobileVisible\", cnId, true)\r\n    invoke_custom(0001, 1, \"Mobile.setMobileVisible\", milkarId, true)\r\n    invoke_custom(500, 1, \"bubble\",  playerId, \"quest.saharach.hallucination.bubble1\")\r\n    invoke_custom(6000, 1, \"skipCinematic\", 13492)\nend\n\n-- [Timer] lancement salle 1\n-- \nfunction event_1667_13548()\n    \nend\n\n-- [Défaite] TP joueur (salle 1)\n-- \nfunction event_1667_13541(CN, Milkar)\n    Mobile.setMobileVisible(CN, false)\r\n    Mobile.setMobileVisible(Milkar, false)\nend\n\n-- [Victoire] Salle 1\n-- \nfunction event_1667_13495(fightBuOne)\n    local playerId = Context.getLeaderId()\r\n    \r\n    startCinematicContext(1.4, playerId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\")\r\n    \r\n    -- \r\n    invoke_custom(500, 1, \"bubble\",  playerId, \"quest.saharach.hallucination.bubble2\")\r\n    invoke_custom(5000, 1, \"skipCinematic\")\r\n    \r\n    \tWorld.setPictoAlpha(-52, 23, -34, 1, 1000)\r\n    \tWorld.setPictoAlpha(-53, 23, -34, 1, 1000)\nend\n\n-- [Trigger] Initialisation salle 2\n-- \nfunction event_1667_13493(Magmog, DC)\n    local magmogId = toLong(Magmog)\r\n    local dcId = toLong(DC)\r\n    local playerId = Context.getLeaderId()\r\n    \r\n    startCinematicContext(1.4, dcId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 13493)\r\n    \r\n    -- TU VAS PRENDRE CHER L'OGROUNET !!! HEHE !\r\n    invoke_custom(0001, 1, \"Mobile.setMobileVisible\", dcId, true)\r\n    invoke_custom(0001, 1, \"Mobile.setMobileVisible\", magmogId, true)\r\n    invoke_custom(0500, 1, \"bubble\",  playerId, \"quest.saharach.hallucination.bubble3\")\r\n    invoke_custom(6000, 1, \"skipCinematic\", 13493)\nend\n\n-- [Timer] Lancement salle 2\n-- \nfunction event_1667_13549()\n    \nend\n\n-- [Défaite] TP joueur (salle 2)\n-- \nfunction event_1667_13592(Magmog, DC)\n    Mobile.setMobileVisible(Magmog, false)\r\n    Mobile.setMobileVisible(DC, false)\nend\n\n-- [Victoire] Salle 2\n-- \nfunction event_1667_13496(fightBuTwo)\n    local playerId = Context.getLeaderId()\r\n    \r\n    startCinematicContext(1.4, playerId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\")\r\n    \r\n    -- \r\n    invoke_custom(500, 1, \"bubble\",  playerId, \"quest.saharach.hallucination.bubble4\")\r\n    invoke_custom(5000, 1, \"skipCinematic\")\r\n    \r\n    \tWorld.setPictoAlpha(-82, 27, -34, 1, 1000)\r\n    \tWorld.setPictoAlpha(-83, 27, -34, 1, 1000)\nend\n\n-- [Trigger] Initialisation salle 3\n-- \nfunction event_1667_13494(Ogrest)\n    local ogrest = toLong(Ogrest)\r\n    local playerId = Context.getLeaderId()\r\n    \r\n    startCinematicContext(1.4, ogrest)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 13494)\r\n    \r\n    -- Ha bah oui ! Manquait plus que lui tiens ! \r\n    -- TU VAS PRENDRE CHER L'OGROUNET !!! HEHE !\r\n    invoke_custom(500, 1, \"bubble\",  playerId, \"quest.saharach.hallucination.bubble5\")\r\n    invoke_custom(6000, 1, \"skipCinematic\", 13494)\nend\n\n-- [Timer] Lancement salle 3\n-- \nfunction event_1667_13550()\n    \nend\n\n-- [EVENT] Fin de combat 3\n-- \nfunction event_1667_19802(Ogrest, fightOgrest)\n    local ogrestId = toLong(Ogrest)\r\n    \r\n    startCinematicContext(1.4, ogrestId)\r\n    \r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 19802)\r\n    \r\n    ------------------------------\r\n    \r\n    -- MOUAHAHA !!!\r\n    invoke_custom(0500, 1, \"bubble\",  ogrestId, \"quest.saharach.hallucination.bubble6\")\r\n    invoke_custom(5000, 1, \"skipCinematic\", 19802)\nend\n\n-- [EVENT] Fin Cinématique combat 3 - TP les joueurs à la sortie\n-- \nfunction event_1667_19803()\n    \nend\n\n-- [SPECIAL] Application des sorts et des caractéristiques\n-- \nfunction event_1667_13547()\n    \nend\n\n-- [Fight Started] Invitation à consulter l'état\n-- \nfunction event_1667_13639()\n    UI.loadTutorialDialog(\"null\",\"quest.saharach.hallucination.tuto.title\",\"quest.saharach.hallucination.tuto.desc\")\nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_1667_13539","event_1667_13386","event_1667_13492","event_1667_13548","event_1667_13541","event_1667_13495","event_1667_13493","event_1667_13549","event_1667_13592","event_1667_13496","event_1667_13494","event_1667_13550","event_1667_19802","event_1667_19803","event_1667_13547","event_1667_13639"],"quest_calls":[],"dialogue_calls":[]},"scenario/1668.lua":{"source":"\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_1668_13388()\n    \nend\n\n-- Première Attaque des Noirespores\n-- \nfunction event_1668_13417(Bolet)\n    noireSporeOneId = Mobile.generateClientMobileId()\r\n    noireSporeTwoId = Mobile.generateClientMobileId()\r\n    noireSporeThreeId = Mobile.generateClientMobileId()\r\n    \r\n    boletOneId = Mobile.generateClientMobileId()\r\n    boletTwoId = Mobile.generateClientMobileId()\r\n    boletThreeId = Mobile.generateClientMobileId()\r\n    \r\n    Actor.createActor(noireSporeOneId, 161102974, 0, 10, -1)\r\n    Actor.createActor(noireSporeTwoId, 161102975, 0, 5, -1)\r\n    Actor.createActor(noireSporeThreeId, 161102973, 1, 7, -1)\r\n    \r\n    Mobile.setMobileDirection(noireSporeOneId, 5)\r\n    Mobile.setMobileDirection(noireSporeTwoId, 5)\r\n    Mobile.setMobileDirection(noireSporeThreeId, 5)\r\n    \r\n    invoke(1000, 1, \"BoletAttack\")\r\n    \r\n    function BoletAttack()\r\n    \tBubbleText.showText(Bolet, \"quest.saharach.Bolet1\", 0, 60, false)\r\n    \tinvoke(1500, 1, \"Mobile.setMobileAnimation\", Bolet, \"AnimSort-CoupFatal\")\r\n    \tinvoke(2500, 1, \"Mobile.setMobileVisible\", Bolet, false)\r\n    \r\n    \tinvoke(2800, 1, \"Actor.createActor\",boletOneId, 1300078, 0, 10, -1)\r\n    \tinvoke(2800, 1, \"Mobile.setMobileAnimation\",boletOneId, \"AnimSort-CoupFatal1\")\r\n    \tinvoke(2900, 1, \"Mobile.setMobileAnimation\",noireSporeOneId, \"AnimHit\")\r\n    \tinvoke(3300, 1, \"Actor.deleteActor\", boletOneId)\r\n    \tinvoke(3300, 1, \"Actor.deleteActor\", noireSporeOneId)\r\n    \r\n    \tinvoke(3500, 1,\t\"Actor.createActor\",boletTwoId, 1300078, 0, 5, -1)\r\n    \tinvoke(3500, 1, \"Mobile.setMobileAnimation\",boletTwoId, \"AnimSort-CoupFatal2\")\r\n    \tinvoke(3600, 1, \"Mobile.setMobileAnimation\",noireSporeTwoId, \"AnimHit\")\r\n    \tinvoke(4100, 1, \"Actor.deleteActor\", boletTwoId)\r\n    \tinvoke(4100, 1, \"Actor.deleteActor\", noireSporeTwoId)\r\n    \r\n    \tinvoke(4300, 1,\t\"Actor.createActor\",boletThreeId, 1300078, 1, 7, -1)\r\n    \tinvoke(4300, 1, \"Mobile.setMobileAnimation\",boletThreeId, \"AnimSort-CoupFatal3\")\r\n    \tinvoke(4400, 1, \"Mobile.setMobileAnimation\",noireSporeThreeId, \"AnimHit\")\r\n    \tinvoke(4900, 1, \"Actor.deleteActor\", boletThreeId)\r\n    \tinvoke(4900, 1, \"Actor.deleteActor\", noireSporeThreeId)\r\n    \t\r\n    \tinvoke(5100, 1, \"Mobile.setMobileVisible\", Bolet, true)\r\n    \tinvoke(5100, 1, \"Mobile.setMobileAnimation\",Bolet, \"AnimSort-CoupFatal-Fin\")\r\n    \t\r\n    \tinvoke(5500, 1, \"BubbleText.showText\", Bolet, \"quest.saharach.Bolet2\", 0, 60, false)\r\n    \tinvoke(8500, 1, \"Mobile.setMobileAnimation\", Bolet, \"AnimSort-CoupFatal\")\r\n    \tinvoke(9500, 1, \"Mobile.setMobileVisible\", Bolet, false)\r\n    end\r\n    \r\n    --invoke(delay_kill, 1, \"Actor.deleteActor\", id)\r\nend\n\n-- Deuxième Attaque des Noirespores\n-- \nfunction event_1668_13389(Bolet)\n    BubbleText.showText(Bolet, \"quest.saharach.Bolet1\", 0, 60, false)\nend\n\n-- Jardinage de Spores - Lancement du Combat\n-- \nfunction event_1668_13422()\n    UI.loadTutorialDialog(\"tutoReserveSpore\",\"tutorial.reserveSpore.title\",\"tutorial.reserveSpore.description\")\nend\n\n-- Jardinage de Spores - Fin du Combat\n-- \nfunction event_1668_13424(Bolet)\n    Mobile.setMobileAnimation(Bolet, \"AnimStatique\")\r\n    Mobile.setMobileVisible(Bolet, true)\nend\n\n-- Lancement d'un combat\n-- \nfunction event_1668_13609()\n    \nend\n\n-- On ramène l'inhibiteur\n-- \nfunction event_1668_13612()\n    \nend\n\n","functions":["event_1668_13388","event_1668_13417","BoletAttack","event_1668_13389","event_1668_13422","event_1668_13424","event_1668_13609","event_1668_13612"],"quest_calls":[],"dialogue_calls":[]},"scenario/1669.lua":{"source":"\n\n-- [EVENT] Activation - Recycleuses OLD\n-- \nfunction event_1669_13415()\n    trace(\"BETA : ACTIVATION DES RECYCLEUSES\")\nend\n\n-- [EVENT] Désactivation - Recycleuses OLD\n-- \nfunction event_1669_13416()\n    trace(\"BETA : DESACTIVATION DES RECYCLEUSES\")\nend\n\n-- [EVENT] Activation - Croupier Beta\n-- \nfunction event_1669_13392()\n    trace(\"BETA : ACTIVATION DU CROUPIER BETA\")\nend\n\n-- [EVENT] Désactivation - Croupier Beta\n-- \nfunction event_1669_13396()\n    trace(\"BETA : DESACTIVATION DU BETA\")\nend\n\n-- [EVENT] Activation - Croupier Beta PvP\n-- \nfunction event_1669_17560()\n    trace(\"BETA : ACTIVATION DU CROUPIER BETA PVP\")\nend\n\n-- [EVENT] Désactivation - Croupier Beta PvP\n-- \nfunction event_1669_17561()\n    trace(\"BETA : DESACTIVATION DU BETA PVP\")\nend\n\n-- [EVENT] Activation - Croupiers Herautopia\n-- \nfunction event_1669_13677()\n    trace(\"BETA : ACTIVATION DES CROUPIER HERAUT\")\nend\n\n-- [EVENT] Désactivation - Croupiers Herautopia\n-- \nfunction event_1669_13678()\n    trace(\"BETA : DESACTIVATION DES CROUPIER HERAUT\")\nend\n\n-- [EVENT] Activation - Croupier Beta - Tournoi 2018\n-- \nfunction event_1669_19899()\n    trace(\"BETA : ACTIVATION DU CROUPIER BETA TOURNOI 2018\")\nend\n\n-- [EVENT] Désactivation - Croupier Beta - Tournoi 2018\n-- \nfunction event_1669_19900()\n    trace(\"BETA : DESACTIVATION DU CROUPIER BETA TOURNOI 2018\")\nend\n\n-- [EVENT] Activation - Recycleuses\n-- \nfunction event_1669_20399()\n    trace(\"BETA : ACTIVATION DES RECYCLEUSES 2019\")\nend\n\n-- [EVENT] Désactivation - Recycleuses\n-- \nfunction event_1669_20400()\n    trace(\"BETA : DESACTIVATION DES RECYCLEUSES 2019\")\nend\n\n-- [EVENT] Activation - Items 230\n-- \nfunction event_1669_22114()\n    trace(\"BETA : ACTIVATION DU CROUPIER BETA TOURNOI 2022\")\nend\n\n-- [EVENT] Désactivation - items 230\n-- \nfunction event_1669_22115()\n    trace(\"BETA : DESACTIVATION DU CROUPIER BETA TOURNOI 2022\")\nend\n\n-- [EVENT] Activation - Nouveaux items\n-- \nfunction event_1669_22767()\n    trace(\"BETA : ACTIVATION DU CROUPIER DE LA PREVIEW DES NOUVEAUX OBJETS\")\nend\n\n-- [EVENT] Désactivation - Nouveaux items\n-- \nfunction event_1669_22768()\n    trace(\"BETA : DESACTIVATION DU CROUPIER DE LA PREVIEW DES NOUVEAUX OBJETS\")\nend\n\n-- [EVENT] Activation - Wakfu Warriors Ogrest's Chaos (partie 1)\n-- \nfunction event_1669_22973()\n    trace(\"BETA : ACTIVATION DES CROUPIERS DE LA PARTIE 1 DES WAKFU WARRIORS OGREST'S CHAOS\")\nend\n\n-- [EVENT] Désactivation - Wakfu Warriors Ogrest's Chaos (partie 1)\n-- \nfunction event_1669_22974()\n    trace(\"BETA : DESACTIVATION DES CROUPIERS DE LA PARTIE 1 DES WAKFU WARRIORS OGREST'S CHAOS\")\nend\n\n-- [EVENT] Activation - Wakfu Warriors Ogrest's Chaos (partie 2)\n-- \nfunction event_1669_22975()\n    trace(\"BETA : ACTIVATION DES CROUPIERS DE LA PARTIE 2 DES WAKFU WARRIORS OGREST'S CHAOS\")\nend\n\n-- [EVENT] Désactivation - Wakfu Warriors Ogrest's Chaos (partie 2)\n-- \nfunction event_1669_22976()\n    trace(\"BETA : DESACTIVATION DES CROUPIERS DE LA PARTIE 2 DES WAKFU WARRIORS OGREST'S CHAOS\")\nend\n\n-- Un joueur interagit avec un HDV\n-- \n