\n    switchChOmybBone = toLong(swChOmybBone)\r\n    switchChOmyb = toLong(swChOmybHALLone)\r\n    \r\n    switchChMatur = toLong(swChMaturHALLone)\r\n    \r\n    bossKilledTrue = toLong(bossKilled)\r\n    \r\n    -- check state switch 2 zone RESERVOIR B pour colonne 2 - 2 et 3 - 1 \r\n     if switchResBtwo ==1 then\r\n    -- World.setPictoAlpha(-43, 36, 0, 1, 1000)\r\n    -- World.setPictoAlpha(-43, 37, -2, 0, 1000)\r\n    -- World.setPictoAlpha(-42, 37, -2, 0, 1000)\r\n    -- World.setPictoAlpha(-43, 36, -2, 0, 1000)\r\n    -- World.setPictoAlpha(-43, 37, -1, 1, 1000)\r\n    -- World.setPictoAlpha(-42, 37, -1, 1, 1000)\r\n    -- World.setPictoAlpha(-43, 36, -1, 1, 1000)\r\n    World.setPictoAlpha(-43, 36, 0, 1, 1000)\r\n    World.setPictoAlpha(-42, 36, -2, 1, 1000)\r\n    World.setPictoAlpha(-42, 37, -2, 0, 1000)\r\n    \r\n    World.setPictoAlpha(-48, 30, 0, 1, 1000)\r\n    World.setPictoAlpha(-47, 30, -2, 1, 1000)\r\n    World.setPictoAlpha(-47, 31, -2, 0, 1000)\r\n    \r\n     elseif switchResBtwo == 0 then\r\n    World.setPictoAlpha(-43, 36, 0, 0, 1000)\r\n    World.setPictoAlpha(-42, 36, -2, 0, 1000)\r\n    World.setPictoAlpha(-42, 37, -2, 1, 1000)\r\n    \r\n    World.setPictoAlpha(-48, 30, 0, 0, 1000)\r\n    World.setPictoAlpha(-47, 30, -2, 0, 1000)\r\n    World.setPictoAlpha(-47, 31, -2, 1, 1000)\r\n    \r\n    -- World.setPictoAlpha(-43, 36, 0, 0, 1000)\r\n    -- World.setPictoAlpha(-43, 37, -2, 1, 1000)\r\n    -- World.setPictoAlpha(-42, 37, -2, 1, 1000)\r\n    -- World.setPictoAlpha(-43, 36, -2, 1, 1000)\r\n    -- World.setPictoAlpha(-43, 37, -1, 0, 1000)\r\n    -- World.setPictoAlpha(-42, 37, -1, 0, 1000)\r\n    -- World.setPictoAlpha(-43, 36, -1, 0, 1000)\r\n     end\r\n    -- check state switch zone RESERVOIR pour colonne 3 - 2 \r\n    if switchResCone == 1 then\r\n    World.setPictoAlpha(-48, 28, 0, 1, 1000)\r\n    World.setPictoAlpha(-47, 28, -2, 1, 1000)\r\n    World.setPictoAlpha(-47, 29, -2, 0, 1000)\r\n    elseif switchResCone == 0 then\r\n    World.setPictoAlpha(-48, 28, 0, 0, 1000)\r\n    World.setPictoAlpha(-47, 28, -2, 0, 1000)\r\n    World.setPictoAlpha(-47, 29, -2, 1, 1000)\r\n    end\r\n    \r\n    -- clean colonne 2 - 2 high water border if low water reservoir 2\r\n    if switchResBone == 1 and switchResBtwo == 1 then\r\n    World.setPictoAlpha(-42, 36, -2, 0, 1500)\r\n    end\r\n    \r\n    -- clean colonnes 3 - 1 and 3 - 2 high water border if low water reservoir 3\r\n    if switchResCone == 1 and switchResCtwo == 1 and switchResCthree == 1 then\r\n    World.setPictoAlpha(-47, 30, -2, 0, 1500)\r\n    end\r\n    if switchResCone == 1 and switchResCtwo == 1 and switchResCthree == 1 and switchResBtwo == 1 then\r\n    World.setPictoAlpha(-47, 28, -2, 0, 1500)\r\n    end\r\n    \r\n    -- check state switch zone RESERVOIR A pour passerelle 1\r\n    if switchResAone == 1  then\r\n    World.setPictoAlpha(-50, 47, 4, 0, 1000)\r\n    World.setPictoAlpha(-50, 46, 4, 0, 1000)\r\n    World.setPictoAlpha(-50, 45, 4, 0, 1000)\r\n    World.setPictoAlpha(-50, 44, 4, 0, 1000)\r\n    World.setPictoAlpha(-50, 43, 4, 0, 1000)\r\n    \r\n    World.setPictoAlpha(-50, 47, -2, 0, 1000)\r\n    World.setPictoAlpha(-50, 46, -2, 0, 1000)\r\n    World.setPictoAlpha(-50, 45, -2, 0, 1000)\r\n    World.setPictoAlpha(-50, 44, -2, 0, 1000)\r\n    World.setPictoAlpha(-50, 43, -2, 0, 1000)\r\n    \r\n    World.setPictoAlpha(-49, 47, -2, 0, 1000)\r\n    World.setPictoAlpha(-49, 46, -2, 0, 1000)\r\n    World.setPictoAlpha(-49, 45, -2, 0, 1000)\r\n    World.setPictoAlpha(-49, 44, -2, 0, 1000)\r\n    World.setPictoAlpha(-49, 43, -2, 0, 1000)\r\n    \r\n    World.setPictoAlpha(-48, 47, -2, 0, 1000)\r\n    World.setPictoAlpha(-48, 46, -2, 0, 1000)\r\n    World.setPictoAlpha(-48, 45, -2, 0, 1000)\r\n    World.setPictoAlpha(-48, 44, -2, 0, 1000)\r\n    World.setPictoAlpha(-48, 43, -2, 0, 1000)\r\n    \r\n    World.setPictoAlpha(-47, 47, -2, 0, 1000)\r\n    World.setPictoAlpha(-47, 46, -2, 0, 1000)\r\n    World.setPictoAlpha(-47, 45, -2, 0, 1000)\r\n    World.setPictoAlpha(-47, 44, -2, 0, 1000)\r\n    World.setPictoAlpha(-47, 43, -2, 0, 1000)\r\n    \r\n    World.setPictoAlpha(-46, 47, -2, 0, 1000)\r\n    World.setPictoAlpha(-46, 46, -2, 0, 1000)\r\n    World.setPictoAlpha(-46, 45, -2, 0, 1000)\r\n    World.setPictoAlpha(-46, 44, -2, 0, 1000)\r\n    World.setPictoAlpha(-46, 43, -2, 0, 1000)\r\n    \r\n    World.setPictoAlpha(-45, 47, -2, 0, 1000)\r\n    World.setPictoAlpha(-45, 46, -2, 0, 1000)\r\n    World.setPictoAlpha(-45, 45, -2, 0, 1000)\r\n    World.setPictoAlpha(-45, 44, -2, 0, 1000)\r\n    World.setPictoAlpha(-45, 43, -2, 0, 1000)\r\n    \r\n    World.setPictoAlpha(-44, 47, -2, 0, 1000)\r\n    World.setPictoAlpha(-44, 46, -2, 0, 1000)\r\n    World.setPictoAlpha(-44, 45, -2, 0, 1000)\r\n    World.setPictoAlpha(-44, 44, -2, 0, 1000)\r\n    World.setPictoAlpha(-44, 43, -2, 0, 1000)\r\n    \r\n    World.setPictoAlpha(-43, 47, -2, 0, 1000)\r\n    World.setPictoAlpha(-43, 46, -2, 0, 1000)\r\n    World.setPictoAlpha(-43, 45, -2, 0, 1000)\r\n    World.setPictoAlpha(-43, 44, -2, 0, 1000)\r\n    World.setPictoAlpha(-43, 43, -2, 0, 1000)\r\n    \r\n    World.setPictoAlpha(-42, 47, -2, 0, 1000)\r\n    World.setPictoAlpha(-42, 46, -2, 0, 1000)\r\n    World.setPictoAlpha(-42, 45, -2, 0, 1000)\r\n    World.setPictoAlpha(-42, 44, -2, 0, 1000)\r\n    World.setPictoAlpha(-42, 43, -2, 0, 1000)\r\n    \r\n    World.setPictoAlpha(-41, 47, -2, 0, 1000)\r\n    World.setPictoAlpha(-41, 46, -2, 0, 1000)\r\n    World.setPictoAlpha(-41, 45, -2, 0, 1000)\r\n    World.setPictoAlpha(-41, 44, -2, 0, 1000)\r\n    World.setPictoAlpha(-41, 43, -2, 0, 1000)\r\n    else\n    \t\n    end\r\n    \r\n    -- check state switchs zone RESERVOIR B pour passerelle 2\r\n    if switchResBone == 1 and switchResBtwo ==1 then\r\n    World.setPictoAlpha(-50, 39, 4, 0, 1000)\r\n    World.setPictoAlpha(-50, 38, 4, 0, 1000)\r\n    World.setPictoAlpha(-50, 37, 4, 0, 1000)\r\n    World.setPictoAlpha(-50, 36, 4, 0, 1000)\r\n    World.setPictoAlpha