)\r\n    invoke(4000, 1, \"Effect.createCameraShakeEffect\", 200, 1000, 200, 1)\nend\n\n-- [SECRET][LEVIER] ALL Activation - wall remove\n-- \nfunction event_1672_13623(swRes, swChOmyb, swMatur)\n    import(502000005003)\r\n    Sound.playLocalSound(11, 502000005003, 40, -2, 20, 0)\r\n    \r\n    World.setPictoAlpha(-2, 20, 14, 0, 1000)\r\n    World.setPictoAlpha(-2, 20, 28, 0, 1000)\nend\n\n","functions":["event_1672_13498","event_1672_13418","event_1672_13419","event_1672_13420","event_1672_13421","event_1672_13519","event_1672_13520","event_1672_13521","event_1672_13523","event_1672_13526","event_1672_13527","event_1672_13528","event_1672_13627","event_1672_13529","event_1672_13594","MindBubbleStart","event_1672_13595","event_1672_13559","event_1672_13597","MindBubbleStart","event_1672_13596","event_1672_13560","event_1672_13558","event_1672_13593","event_1672_13563","event_1672_13600","MindBubbleStart","event_1672_13602","event_1672_13598","event_1672_13601","MindBubbleStart","event_1672_13603","event_1672_13599","event_1672_13561","event_1672_13568","event_1672_13531","event_1672_13532","event_1672_13530","event_1672_13569","event_1672_13579","event_1672_13533","event_1672_13534","event_1672_13610","event_1672_13611","event_1672_13535","event_1672_13583","event_1672_13605","event_1672_13606","event_1672_13623"],"quest_calls":[],"dialogue_calls":[]},"scenario/1673.lua":{"source":"\n\n-- Initialisation\n-- \nfunction event_1673_13618()\n    \nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_1673_13428()\n    \nend\n\n-- Le noirespore fuit salle 3 - Début\n-- \nfunction event_1673_13589(mobIdSalleTrois)\n    Mobile.setMobileAnimation(mobIdSalleTrois, \"AnimComp-Enfouissement\")\nend\n\n-- Le noirespore fuit salle 3 - Fin\n-- \nfunction event_1673_13617()\n    \nend\n\n-- Le noirespore fuit salle 2 - Début\n-- \nfunction event_1673_13588(mobIdSalleDeux)\n    UI.loadTutorialDialog(\"tutoSaSTemple\",\"tutorial.SaSTemple.title\",\"tutorial.SaSTemple.description\")\