ueur découvre la Sentinelle de la Fontaine\n-- \nfunction event_1674_13453()\n    \nend\n\n-- [QUETE] Le joueur découvre la Sentinelle (suite)\n-- \nfunction event_1674_13454(sentinelleCacterre)\n    function sentinelleCacterreBubbleStart(mob,text)\r\n    \tsentinelleCacterreBubble=BubbleText.showText(mob, text, 0, 40, false)\r\n    \tinvoke(5000,1,\"BubbleText.close\",sentinelleCacterreBubble)\r\n    end\r\n    \r\n    function addParticlesToSentinelle()\r\n    partSC=Particle.addParticleSystemToTarget(15401, sentinelleCacterre)\r\n    \r\n    invoke(500,1,\"Particle.removeParticleSystem\",partSC)\r\n    end\r\n    \r\n    function turnSentinelle()\r\n    Mobile.setMobileDirection(sentinelleCacterre, 3)\r\n    end\r\n    \r\n    Camera.attachCameraToMobile(sentinelleCacterre)\r\n    invoke(500,1,\"addParticlesToSentinelle\")\r\n    invoke(100,1,\"turnSentinelle\")\r\n    invoke(1000,1,\"sentinelleCacterreBubbleStart\",sentinelleCacterre, \"quest.saharach.sentinelleCacterre.spotplayer\")\r\n    \r\n    UI.manageFrame(\"World\", false)\nend\n\n-- [QUETE] Le joueur découvre la Sentinelle (combat)\n-- \nfunction event_1674_13455()\n    UI.manageFrame(\"World\", true)\r\n    playerId = Context.getPlayer()\r\n    Camera.attachCameraToMobile(playerId)\nend\n\n-- [QUETE] Le joueur découvre la Sentinelle (FIN)\n-- \nfunction event_1674_13472()\n    function PlayerBubbleStart(mob,text)\r\n    \tPlayerBubble=BubbleText.showText(mob, text, 0, 40, false)\r\n    \tinvoke(15000,1,\"BubbleText.close\",PlayerBubble)\r\n    end\r\n    \r\n    playerId = Context.getPlayer()\r\n    \r\n    invoke(3000,1,\"PlayerBubbleStart\",playerId, \"quest.saharach.EpineEpineuse.get\")\r\n    \r\n    trace(\"poueetttt\")\nend\n\n-- [FIN QUETE 1755] Le joueur parle au Cacterre Sentinelle\n-- \nfunction event_1674_13475(sentinelleCacterre)\n    function sentinelleCacterreBubbleStart(mob,text)\r\n    \tsentinelleCacterreBubble=BubbleText.showText(mob, text, 0, 40, false)\r\n    \tinvoke(4000,1,\"BubbleText.close\",sentinelleCacterreBubble)\r\n    end\r\n    \r\n    invoke(200,1,\"sentinelleCacterreBubbleStart\",sentinelleCacterre, \"quest.saharach.sentinellefriendly.interaction\")\r\nend\n\n","functions":["event_1674_13446","event_1674_13447","event_1674_13453","event_1674_13454","sentinelleCacterreBubbleStart","addParticlesToSentinelle","turnSentinelle","event_1674_13455","event_1674_13472","PlayerBubbleStart","event_1674_13475","sentinelleCacterreBubbleStart"],"quest_calls":[],"dialogue_calls":[]},"scenario/1677.lua":{"source":"\n\n-- [INITIALISATION] Variables\n-- \nfunction event_1677_13502()\n    \nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_1677_13503()\n    \nend\n\n-- [QUETE] Salle Omybienne 1 - Verse l'Inhibiteur\n-- \nfunction event_1677_13545()\n     Effect.createCameraShakeEffect(100, 300, 100, 3)\r\n     Sound.playSound(502000002001,  10)\r\n    \tCamera.setUserZoomLocked(true)\r\n    \r\n    function PlayerBubbleStart(mob,text)\r\n    \tPlayerBubble=BubbleText.showText(mob, text, 0, 40, false)\r\n    \tinvoke(3000,1,\"BubbleText.close\",PlayerBubble)\r\n    end\r\n    \r\n    playerId = Context.getPlayer()\r\n    \r\n    invoke(1000,1,\"PlayerBubbleStart\",playerId, \"quest.Saharach.Inhibiteur1\")\nend\n\n-- [QUETE] Salle Omybienne 1 - Attaque Tentacule + Noirespores\n-- \nfunction event_1677_13522()\n    \nend\n\n-- [QUETE] Salle Omybienne 1 - Victoire\n-- \nfunction event_1677_13504()\n    \tCamera.setUserZoomLocked(true)\r\n    \r\n    function PlayerBubbleStart(mob,text)\r\n    \tPlayerBubble=BubbleText.showText(mob, text, 0, 40, false)\r\n    \tinvoke(16000,1,\"BubbleText.close\",PlayerBubble)\r\n    \tinvoke(16000,1,\"Camera.setUserZoomLocked\",false)\t\t\r\n    end\r\n    \r\n    playerId = Context.getPlayer()\r\n    \r\n    \r\n    invoke(4000,1,\"PlayerBubbleStart\",playerId, \"quest.Saharach.Omybe1\")\r\n    \r\n    invoke(11000,1,\"PlayerBubbleStart\",playerId, \"quest.Saharach.Omybe1suite\")\nend\n\n-- [QUETE] Salle Omybienne 2