pores\n-- \nfunction event_1677_13556()\n    \nend\n\n-- [QUETE] Salle Omybienne 3 - Victoire\n-- \nfunction event_1677_13557()\n    \tCamera.setUserZoomLocked(true)\r\n    \r\n    function PlayerBubbleStart(mob,text)\r\n    \tPlayerBubble=BubbleText.showText(mob, text, 0, 40, false)\r\n    \tinvoke(22000,1,\"BubbleText.close\",PlayerBubble)\r\n    \tinvoke(22000,1,\"Camera.setUserZoomLocked\",false)\t\t\r\n    end\r\n    \r\n    playerId = Context.getPlayer()\r\n    \r\n    invoke(4000,1,\"PlayerBubbleStart\",playerId, \"quest.Saharach.Omybe3\")\r\n    \r\n    invoke(17000,1,\"PlayerBubbleStart\",playerId, \"quest.Saharach.Omybe3suite\")\nend\n\n","functions":["event_1677_13502","event_1677_13503","event_1677_13545","PlayerBubbleStart","event_1677_13522","event_1677_13504","PlayerBubbleStart","event_1677_13552","PlayerBubbleStart","event_1677_13553","event_1677_13554","PlayerBubbleStart","event_1677_13555","PlayerBubbleStart","event_1677_13556","event_1677_13557","PlayerBubbleStart"],"quest_calls":[],"dialogue_calls":[]},"scenario/1678.lua":{"source":"\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_1678_13621()\n    player = Context.getPlayer()\r\n    \r\n    Mobile.setMobileVisible(player, false)\r\n    Camera.setUserZoomLocked(true)\r\n    UI.closeMRU()\r\n    UI.closeAllBags()\t\t\t\t\t\t\t\t\t\t\t\t\r\n    UI.manageFrame(\"World\",false) \t\t\t\t\t\r\n    UI.setUIVisible(false)\t\r\n    UI.unloadDialog(\"verticalFollowedAchievementsDialog\")\r\n    \r\n    Camera.setWorldTarget(-2, -27, -4)\r\n    UI.displayWideScreenBand(true)\nend\n\n-- [STEP 1] L'omybe se réfugie dans la fontaine\n-- \nfunction event_1678_13622()\n    omybe = Mobile.generateClientMobileId()\r\n    \r\n    Actor.createActor(omybe, 161503049, -2, -27, -4)\r\n    \r\n    Mobile.setMobileAnimation(omybe, \"AnimComp-Contamine\")\r\n    Particle.addParticleSystem(800424, -2, -27, -4)\nend\n\n-- [STEP 2] Le cactiflore vient chercher de l'eau\n-- \nfunction event_1678_13625()\n    cactiflore = Mobile.generateClientMobileId()\r\n    Actor.createActor(cactiflore, 160802969, 18, -19, 0)\r\n    Mobile.setMobileVisible(cactiflore, false)\r\n        \t\r\n    Camera.attachCameraToMobile(cactiflore)\r\n    Camera.setZoomFactor(1.5)\r\n    invoke(2000,1,\"apparition\")\r\n        \r\n    function apparition()\r\n    \tMobile.setMobileVisible(cactiflore, true)\r\n    \tMobile.setMobileAnimationSuffix(cactiflore, \"-Cine\")\r\n    \tMobile.setMobileDirection(cactiflore, 5)\r\n    \tMobile.moveMobile(cactiflore, 8, -19, 0, \"boire\")\r\n    end\r\n        \r\n    function boire()\r\n    \tinvoke(1500, 1, \"Mobile.setMobileAnimation\", cactiflore, \"AnimComp\")\r\n    \tinvoke(1500, 1, \"Particle.addParticleSystem\", 800425, 8, -19, 0)\r\n    \tinvoke(5780, 1, \"Mobile.setMobileAnimation\", cactiflore, \"AnimStatique-Fin\")\r\n    end\nend\n\n-- [STEP 3] Fin\n-- \nfunction event_1678_13626()\n    UI.displayWideScreenBand(false)\r\n    Camera.setUserZoomLocked(false)\t\t\t\t\t\t\t\t\t\t\t\t\r\n    UI.manageFrame(\"World\",true) \t\t\t\t\t\r\n    UI.setUIVisible(true)\t\r\n    UI.loadDialog(\"verticalFollowedAchievementsDialog\")\nend\n\n","functions":["event_1678_13621","event_1678_13622","event_1678_13625","apparition","boire","event_1678_13626"],"quest_calls":[],"dialogue_calls":[]},"scenario/1679.lua":{"source":"m_playerId = Context.getPlayer()\n\n-- Lancement Cinématique\n-- \nfunction event_1679_13624()\n    \nend\n\n","functions":["event_1679_13624"],"quest_calls":[],"dialogue_calls":[]},"scenario/1683.lua":{"source":"\n\n-- [INIT] Variables\n-- \nfunction event_1683_13687()\n    \nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_1683_13688()\n    \nend\n\n-- [EVENT]Cinématique d'arrivée\n-- \nfunction event_1683_13689(cineStartDone, VDCorniche)\n    playerId = Context.getPlayer()\r\n    VDCornicheID = toLong(VDCorniche)\r\n    cineStartDone = toLong(cineStartDone)\r\n    x, y, z = Mobile.getMobilePosition(playerId)\r\n    \r\n    function animChute()\r\n    \tMobile.setMobileVisible(playerId, true)\r\n    \tMobile.setMobileDirection(playerId, 5)\r\n    \tMobile.setMobileAnimation(playerId, \"AnimIncarnam-Chute-Fin\", \"animEnd\")\r\n    end\r\n    \r\n    function animEnd()\r\n    \tMobile.setMobileDirection(playerId, 1)\r\n    --\tUI.manageFrame(\"World\",true)\r\n    end\r\n    \r\n    \r\n    Mobile.setMobileVisible(playerId, false)\r\n    UI.manageFrame(\"World\",false)\r\n    invoke(3200, 1, \"animChute\")\r\n    if cineStartDone == 1 then\r\n    \tinvoke(4000, 1, \"UI.manageFrame\",\"World\",false)\r\n    end\r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    -- test cineatique locale only\r\n    function MindBubbleStart(mob,text)\r\n    \tMindBubble=BubbleText.showText(mob, text, 0, 40, false)\r\n    \tinvoke(4000,1,\"BubbleText.close\",MindBubble)\r\n    end\r\n    \r\n    UI.manageFrame(\"World\",false)\r\n    \r\n    invoke(1000,1, \"Camera.attachCameraToMobile\",VDCornicheID)\r\n    invoke(1500,1,\"Camera.setZoomFactor\", 1.5)\r\n    invoke(2000,1, \"Mobile.setMobileDirection\", VDCornicheID, 3)\r\n    \r\n    invoke(3000,1,\"MindBubbleStart\",VDCornicheID, \"quest.DDCH0.pandora.Corniche01\")\r\n    invoke(3000,1,\"Mobile.setMobileAnimation\",VDCornicheID, \"AnimEmote-Rire\")\r\n    invoke(7000,1,\"MindBubbleStart\",VDCornicheID, \"quest.DDCH0.pandora.Corniche02\")\r\n    invoke(11000,1,\"MindBubbleStart\",VDCornicheID, \"quest.DDCH0.pandora.Corniche03\")\r\n    invoke(15000,1,\"MindBubbleStart\",VDCornicheID, \"quest.DDCH0.pandora.Corniche04\")\r\n    invoke(15000,1,\"Mobile.setMobileAnimation\",VDCornicheID, \"AnimEmote-Rire\")\r\n    invoke(19000,1,\"MindBubbleStart\",VDCornicheID, \"quest.DDCH0.pandora.Corniche05\")\r\n    \r\n    invoke(23000, 1,\"UI.manageFrame\",\"World\",true)\r\n    invoke(23000,1, \"Camera.attachCameraToMobile\",playerId)\nend\n\n-- [EVENT]Cinématique Pandora\n-- \nfunction event_1683_13694(cineStartDone, VDCorniche)\n    VDCornicheID = toLong(VDCorniche)\r\n    playerId = Context.getPlayer()\r\n    \r\n    function MindBubbleStart(mob,text)\r\n    \tMindBubble=BubbleText.showText(mob, text, 0, 40, false)\r\n    \tinvoke(4000,1,\"BubbleText.close\",MindBubble)\r\n    end\r\n    \r\n    UI.manageFrame(\"World\",false)\r\n    zoomFactor = Camera.getZoomFactor()\r\n    \r\n    invoke(1000,1, \"Camera.attachCameraToMobile\",VDCornicheID)\r\n    invoke(1500,1,\"Camera.setZoomFactor\", 1.5)\r\n    invoke(2000,1, \"Mobile.setMobileDirection\", VDCornicheID, 3)\r\n    \r\n    invoke(3000,1,\"MindBubbleStart\",VDCornicheID, \"quest.DDCH0.pandora.Corniche01\")\r\n    invoke(3000,1,\"Mobile.setMobileAnimation\",VDCornicheID, \"AnimEmote-Rire\")\r\n    invoke(7000,1,\"MindBubbleStart\",VDCornicheID, \"quest.DDCH0.pandora.Corniche02\")\r\n    invoke(11000,1,\"MindBubbleStart\",VDCornicheID, \"quest.DDCH0.pandora.Corniche03\")\r\n    invoke(15000,1,\"MindBubbleStart\",VDCornicheID, \"quest.DDCH0.pandora.Corniche04\")\r\n    invoke(15000,1,\"Mobile.setMobileAnimation\",VDCornicheID, \"AnimEmote-Rire\")\r\n    invoke(19000,1,\"MindBubbleStart\",VDCornicheID, \"quest.DDCH0.pandora.Corniche05\")\r\n    \r\n    invoke(23000, 1,\"UI.manageFrame\",\"World\",true)\r\n    invoke(23000, 1,\"Camera.setZoomFactor\",zoomFactor)\r\n    invoke(23000,1, \"Camera.attachCameraToMobile\",playerId)\nend\n\n-- [EVENT] Activation TP\n-- \nfunction event_1683_13695()\n    \nend\n\n-- [EVENT] Dialogue - retour à Astrub\n-- \nfunction event_1683_13741()\n    \nend\n\n","functions":["event_1683_13687","event_1683_13688","event_1683_13689","animChute","animEnd","MindBubbleStart","event_1683_13694","MindBubbleStart","event_1683_13695","event_1683_13741"],"quest_calls":[],"dialogue_calls":[]},"scenario/1684.lua":{"source":"\n\n-- [INIT] Variables\n-- \nfunction event_1684_13690()\n    \nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_1684_13691()\n    \nend\n\n-- [EVENT] Activation combat\n-- \nfunction event_1684_13738(MobA, MobB, MobC, fightResAone)\n    function MindBubbleStart(mob,text)\r\n    \tMindBubble=BubbleText.showText(mob, text, 0, 40, false)\r\n    \tinvoke(5000,1,\"BubbleText.close\",MindBubble)\r\n    end\r\n    \r\n    playerId = Context.getPlayer()\r\n    mobOne = toLong(MobA)\r\n    mobTwo = toLong(MobB)\r\n    mobThree = toLong(MobC)\r\n    \r\n    invoke(4000,1,\"MindBubbleStart\",mobOne, \"quest.DDCH0.pandora.Couloirservice01\")\r\n    invoke(4500,1,\"MindBubbleStart\",mobTwo, \"quest.DDCH0.pandora.Couloirservice02\")\r\n    invoke(5000,1,\"MindBubbleStart\",mobThree, \"quest.DDCH0.pandora.Couloirservice01\")\nend\n\n-- [RESERVOIR][FIGHT] A1Combat gagné \n-- \nfunction event_1684_13739(fightResAone)\n    \nend\n\n-- [RESERVOIR][FIGHT] TP reveal\n-- \nfunction event_1684_13740(fightResAone)\n    \nend\n\n-- [COMBAT] placement des alliés\n-- \nfunction event_1684_13838(fightResAone)\n    trace(\"on place les alliés\")\nend\n\n","functions":["event_1684_13690","event_1684_13691","event_1684_13738","MindBubbleStart","event_1684_13739","event_1684_13740","event_1684_13838"],"quest_calls":[],"dialogue_calls":[]},"scenario/1685.lua":{"source":"\n\n-- [INIT] Variables\n-- \nfunction event_1685_13692(SylarghId, MekaIdA, MekaIdB, PandoraId)\n    \nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_1685_13693()\n    \nend\n\n-- [EVENT] Joueur check objet 1\n-- \nfunction event_1685_13703(PandoraId)\n    PandoraIdval = toLong(PandoraId)\r\n    PlayerId = Context.getPlayer()\r\n    \r\n    function PandoraBubbleStart(mob,text)\r\n    \tPandoraBubble=BubbleText.showText(mob, text, 0, 40, false)\r\n    \tinvoke(6000,1,\"BubbleText.close\",PandoraBubble)\r\n    end\r\n    \r\n    Camera.attachCameraToMobile(PandoraIdval)\r\n    UI.manageFrame(\"World\", false)\r\n    invoke(1000,1,\"PandoraBubbleStart\",PandoraIdval, \"quest.DDCH0.pandora.Collect.object01\")\r\n    invoke(5000,1,\"Camera.attachCameraToMobile\",PlayerId)\r\n    invoke(5200, 1, \"UI.manageFrame\", \"World\", true)\nend\n\n-- [EVENT] Joueur check objet 2\n-- \nfunction event_1685_13704(PandoraId)\n    PandoraIdval = toLong(PandoraId)\r\n    PlayerId = Context.getPlayer()\r\n    \r\n    function PandoraBubbleStart(mob,text)\r\n    \tPandoraBubble=BubbleText.showText(mob, text, 0, 40, false)\r\n    \tinvoke(6000,1,\"BubbleText.close\",PandoraBubble)\r\n    end\r\n    \r\n    Camera.attachCameraToMobile(PandoraIdval)\r\n    UI.manageFrame(\"World\", false)\r\n    invoke(1000,1,\"PandoraBubbleStart\",PandoraIdval, \"quest.DDCH0.pandora.Collect.object02\")\r\n    invoke(5000,1,\"Camera.attachCameraToMobile\",PlayerId)\r\n    invoke(5200, 1, \"UI.manageFrame\", \"World\", true)\nend\n\n-- [EVENT] Joueur check objet unidentified (3 4 5 6 7 )\n-- \nfunction event_1685_13705(PandoraId)\n    PandoraIdval = toLong(PandoraId)\r\n    PlayerId = Context.getPlayer()\r\n    \r\n    function PandoraBubbleStart(mob,text)\r\n    \tPandoraBubble=BubbleText.showText(mob, text, 0, 40, false)\r\n    \tinvoke(6000,1,\"BubbleText.close\",PandoraBubble)\r\n    end\r\n    \r\n    Camera.attachCameraToMobile(PandoraIdval)\r\n    UI.manageFrame(\"World\", false)\r\n    invoke(1000,1,\"PandoraBubbleStart\",PandoraIdval, \"quest.DDCH0.pandora.Collect.objectnogood\")\r\n    invoke(4000,1,\"Camera.attachCameraToMobile\",PlayerId)\r\n    invoke(4200, 1, \"UI.manageFrame\", \"World\", true)\nend\n\n-- [EVENT] Joueur check objet 8 (objectif quête) (check avancement)\n-- \nfunction event_1685_14138()\n    \nend\n\n-- [EVENT] Joueur check objet 8 (timer tick)\n-- \nfunction event_1685_13706(PandoraId, SylarghId, MekaIdA, MekaIdB)\n    PandoraIdval = toLong(PandoraId)\r\n    PlayerId = Context.getPlayer()\r\n    \r\n    function PandoraBubbleStart(mob,text,tDuration)\r\n    \tPandoraBubble=BubbleText.showText(mob, text, 0, 40, false)\r\n    \tinvoke(tDuration,1,\"BubbleText.close\",PandoraBubble)\r\n    end\r\n    \r\n    \r\n    Camera.attachCameraToMobile(PandoraIdval)\r\n    UI.manageFrame(\"World\", false)\r\n    invoke(1000,1,\"PandoraBubbleStart\",PandoraIdval, \"quest.DDCH0.pandora.Collect.object08ok01\",3000)\r\n    invoke(4000,1,\"PandoraBubbleStart\",PandoraIdval, \"quest.DDCH0.pandora.Collect.object08ok02\",4000)\r\n    invoke(8000,1,\"PandoraBubbleStart\",PandoraIdval, \"quest.DDCH0.pandora.Collect.object08exctact01\",3000)\r\n    invoke(11000,1,\"PandoraBubbleStart\",PandoraIdval, \"quest.DDCH0.pandora.Collect.object08exctact02\",5000)\r\n    invoke(16000,1,\"PandoraBubbleStart\",PandoraIdval, \"quest.DDCH0.pandora.Collect.object08exctact03\",5000)\r\n    \r\n    invoke(19999, 1, \"UI.manageFrame\", \"World\", true)\nend\n\n-- [EVENT] Arrivée de Sylargh\n-- \nfunction event_1685_13725(SylarghId, MekaIdA, MekaIdB, PandoraId)\n    PandoraIdval = toLong(PandoraId)\r\n    PlayerId = Context.getPlayer()\r\n    MekaIdAval = toLong(MekaIdA)\r\n    MekaIdBval = toLong(MekaIdB)\r\n    SylarghIdval = toLong(SylarghId)\r\n    \r\n    \r\n    function SylarghBubbleStart(mob,text,bubbleduration)\r\n    \tSylarghBubble=BubbleText.showText(mob, text, 0, 40, false)\r\n    \tinvoke(bubbleduration,1,\"BubbleText.close\",SylarghBubble)\r\n    end\r\n    \r\n    function RemiseAZero()\r\n    Camera.attachCameraToMobile(PlayerId)\r\n    Camera.setUserZoomLocked(false)\t\t\t\r\n    Camera.setZoomFactor(zoomFactor)\t\t\t\t\t\t\t\t\t\r\n    UI.manageFrame(\"World\",true) \t\t\t\t\t\r\n    UI.displayWideScreenBand(false)\r\n    UI.setUIVisible(true)\t\r\n    UI.activateFollowAchievement(true)\r\n    end\r\n    \r\n    zoomFactor = Camera.getZoomFactor()\r\n    Camera.setZoomFactor(1.5)\r\n    Camera.setUserZoomLocked(true)\r\n    UI.closeMRU()\r\n    UI.closeAllBags()\t\t\t\t\t\t\t\t\t\t\t\t\r\n    UI.manageFrame(\"World\",false) \t\t\t\t\t\r\n    UI.setUIVisible(false)\t\r\n    UI.activateFollowAchievement(false)\r\n    UI.displayWideScreenBand(true)\r\n    \r\n    Camera.attachCameraToMobile(SylarghIdval)\r\n    invoke(1000,1,\"SylarghBubbleStart\",SylarghIdval, \"quest.DDCH0.Sylargh.spot01\",4000)\r\n    invoke(1500,1,\"Mobile.moveMobile\",SylarghIdval, 0, -7, 14)\r\n    invoke(2000,1,\"Mobile.moveMobile\",MekaIdAval, -2, -10, 14)\r\n    invoke(2500,1,\"Mobile.moveMobile\",MekaIdBval, 2, -10, 14)\r\n    invoke(5000,1,\"SylarghBubbleStart\",SylarghIdval, \"quest.DDCH0.Sylargh.spot02\",4000)\r\n    invoke(6000,1,\"Mobile.moveMobile\",SylarghIdval, 0, -10, 14)\r\n    invoke(9000,1,\"SylarghBubbleStart\",SylarghIdval, \"quest.DDCH0.Sylargh.spot03\",4000)\r\n    invoke(13000,1,\"SylarghBubbleStart\",SylarghIdval, \"quest.DDCH0.Sylargh.spot04\",4000)\r\n    invoke(16500,1,\"SylarghBubbleStart\",MekaIdBval, \"quest.DDCH0.Meka.spot04\",2000)\r\n    invoke(17000,1,\"SylarghBubbleStart\",MekaIdAval, \"quest.DDCH0.Meka.spot04\",2000)\r\n    \r\n    invoke(17500,1, \"Camera.attachCameraToMobile\",PandoraIdval)\r\n    invoke(18000,1,\"SylarghBubbleStart\",PandoraIdval, \"quest.DDCH0.Pandora.spot04\",3000)\r\n    Mobile.setMobileMovementStyle(PandoraIdval, \"RUN\")\r\n    invoke(18500,1,\"Mobile.moveMobile\",PandoraIdval, 0, -13, 14,\"Mobile.moveMobile\",PandoraIdval,0,-17,16)\r\n    invoke (22000,1, \"RemiseAZero\")\nend\n\n-- [EVENT] Début du combat contre Sylargh\n-- \nfunction event_1685_13709(SylarghId, MekaIdA, MekaIdB)\n    \nend\n\n-- [COMBAT] Combat contre Sylargh - Ajout de Pandora\n-- \nfunction event_1685_13742()\n    \nend\n\n-- [COMBAT] Fin du Combat contre Sylargh - Fuite\n-- \nfunction event_1685_13743(PandoraId)\n    PandoraIdval = toLong(PandoraId)\r\n    PlayerId = Context.getPlayer()\r\n    \r\n    function startCinematic()\r\n    \tzoomFactor = Camera.getZoomFactor()\r\n    \tCamera.setUserZoomLocked(true)\r\n    \tUI.closeMRU()\r\n    \tUI.closeAllBags()\t\t\t\t\t\t\t\t\t\t\t\t\r\n    \tUI.manageFrame(\"World\",false) \t\t\t\t\t\r\n    \tUI.setUIVisible(false)\r\n    \tUI.activateFollowAchievement(false)\r\n    \r\n    \t--Camera.setWorldTarget(0,-16,14)\r\n    \tUI.displayWideScreenBand(true)\r\n    end\r\n    \r\n    function endCinematic()\r\n    \tCamera.setZoomFactor(zoomFactor)\r\n    \tCamera.setUserZoomLocked(false)\t\t\t\t\t\t\t\t\t\t\r\n    \tUI.manageFrame(\"World\",true) \t\t\t\t\t\r\n    \tUI.setUIVisible(true)\t\r\n    \tUI.activateFollowAchievement(true)\r\n    \r\n    \tCamera.attachCameraToMobile(PlayerId)\r\n    \tUI.displayWideScreenBand(false)\r\n    end\r\n    \r\n    function PandoraBubbleStart(mob,text)\r\n    \tBubbleText.closeBubbleAttachedTo(mob)\r\n    \tBubbleText.showText(mob, text, 0, 40, false)\r\n    end\r\n    \r\n    function ApparitionKrosmo()\r\n    \tPandoraBubbleStart(PandoraIdval, \"quest.DDCH0.pandora.extracting.1\")\r\n    \tkrosmo = Mobile.generateClientMobileId()\r\n    \tActor.createActor(krosmo,159303071,-1,-16,14)\r\n    \tMobile.setMobileAnimation(krosmo,\"AnimApparition\")\r\n    \tinvoke(2000,1,\"Portail\")\r\n    end\r\n    \r\n    function Portail() --2sec\r\n    \tMobile.setMobileDirection(PandoraIdval, 3)\r\n    \tMobile.setMobileAnimation(PandoraIdval, \"AnimComp-Portail\")\r\n    \tinvoke(1000,1,\"Particle.addParticleSystem\",800520, 0, -16, 14)\r\n    \tinvoke(2000,1,\"PandoraBubbleStart\", PandoraIdval, \"quest.DDCH0.pandora.extracting.2\")\r\n    \tinvoke(4000,1,\"PandoraJumpInPortal\")\r\n    end\r\n    \r\n    function PandoraJumpInPortal() --2sec\r\n    \tMobile.setMobileAnimation(PandoraIdval, \"AnimComp-PortailEntree\")\r\n    \tMobile.moveMobile(krosmo, 0,-16,14,\"Mobile.setMobileVisible\",false)\r\n    \tinvoke(1000,1,\"Mobile.setMobileVisible\",PandoraIdval,false)\r\n    \tinvoke(1000,1,\"Mobile.setMobileVisible\",krosmo,false)\r\n    \tinvoke(2000,1,\"PlayerJumpInPortal\")\t\r\n    end\r\n    \r\n    function PlayerJumpInPortal() --3sec\r\n    \tCamera.attachCameraToMobile(PlayerId)\r\n    \tif Mobile.getMobileStatus(PlayerId) ~= 2 then\r\n    \t\tMobile.setMobileMovementStyle(PlayerId, \"RUN\")\r\n    \t\tMobile.moveMobile(PlayerId,0,-16,14,\"PlayerJump\")\r\n    \telse\r\n    \t\tCamera.setZoomFactor(zoomFactor)\r\n    \t\tCamera.setUserZoomLocked(false)\t\t\t\t\t\t\t\t\t\t\r\n    \t\t--UI.manageFrame(\"World\",true) \t\t\t\t\t\r\n    \t\tUI.setUIVisible(true)\t\r\n    \t\tUI.activateFollowAchievement(true)\r\n    \r\n    \t\tCamera.attachCameraToMobile(PlayerId)\r\n    \t\tUI.displayWideScreenBand(false)\r\n    \tend\r\n    end\r\n    \r\n    function PlayerJump()\r\n    \tMobile.setMobileAnimation(PlayerId,\"AnimRelique-Saut\")\r\n    \tinvoke(500,1,\"Mobile.setMobileVisible\",PlayerId,false)\r\n    end\r\n    \r\n    -- Démarrage\r\n    startCinematic()\r\n    invoke(1500,1,\"Camera.attachCameraToMobile\",PandoraIdval)\r\n    invoke(1500,1,\"UI.manageFrame\",\"World\",false)\r\n    invoke(2000,1,\"Camera.attachCameraToMobile\",PandoraIdval)\r\n    invoke(2000,1,\"PandoraBubbleStart\",PandoraIdval, \"quest.DDCH0.pandora.extracting.0\")\r\n    invoke(2100,1,\"UI.manageFrame\",\"World\",false)\r\n    invoke(4000,1,\"ApparitionKrosmo\")\r\n    invoke(4100,1,\"UI.manageFrame\",\"World\",false)\r\n    --invoke(16000,1,\"endCinematic\")\r\nend\n\n-- [COMBAT] Fin du Combat contre Sylargh - Fuite\n-- \nfunction event_1685_13752()\n    \nend\n\n-- [EVENT] Joueur parle à pandora\n-- \nfunction event_1685_13809(PandoraId)\n    PlayerId = Context.getPlayer()\r\n    sramyIdVal = toLong(PandoraId)\r\n    dialChoice = random( 0, 5 )\r\n    tDuration = 4000\r\n    \r\n    function MindBubbleStart(mob,text,tDuration)\r\n    \tMindBubble=BubbleText.showText(mob, text, 0, 40, false)\r\n    \tinvoke(tDuration,1,\"BubbleText.close\",MindBubble)\r\n    end\r\n    \r\n    if dialChoice < 1 then\r\n    dialChoice = 1\r\n    end\r\n    \r\n    \r\n    if dialChoice == 1 then\r\n    MindBubbleStart (sramyIdVal, \"quest.DDCH0.pandora.Collect.common01\", 4000)\r\n    elseif dialChoice == 2 then\r\n    MindBubbleStart (sramyIdVal, \"quest.DDCH0.pandora.Collect.common02\",6000)\r\n    elseif dialChoice == 3 then\r\n    MindBubbleStart (sramyIdVal, \"quest.DDCH0.pandora.Collect.common03\",5000)\r\n    else\n    MindBubbleStart (sramyIdVal, \"quest.DDCH0.pandora.Collect.common04\",6000)\r\n    \t\n    end\nend\n\n-- [COMBAT] Combat contre Sylargh - tick du premier tour - validation quête\n-- \nfunction event_1685_13939(fightOne)\n    \nend\n\n","functions":["event_1685_13692","event_1685_13693","event_1685_13703","PandoraBubbleStart","event_1685_13704","PandoraBubbleStart","event_1685_13705","PandoraBubbleStart","event_1685_14138","event_1685_13706","PandoraBubbleStart","event_1685_13725","SylarghBubbleStart","RemiseAZero","event_1685_13709","event_1685_13742","event_1685_13743","startCinematic","endCinematic","PandoraBubbleStart","ApparitionKrosmo","Portail","PandoraJumpInPortal","PlayerJumpInPortal","PlayerJump","event_1685_13752","event_1685_13809","MindBubbleStart","event_1685_13939"],"quest_calls":["UI.activateFollowAchievement(true)\r","UI.activateFollowAchievement(false)\r","UI.activateFollowAchievement(false)\r","UI.activateFollowAchievement(true)\r","UI.activateFollowAchievement(true)\r"],"dialogue_calls":[]},"scenario/1686.lua":{"source":"-- les fonctions où on cache\r\nfunction hideMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, false)\r\nend\r\n\r\n-- les fonctions où on rend visible (à nouveau\r\nfunction showMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, true)\r\nend\n\n-- [INIT] Variables\n-- \nfunction event_1686_13696()\n    \nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_1686_13697()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - quête terminée\n-- \nfunction event_1686_13940()\n    Particle.addParticleSystem(800521, -10,3,5)\nend\n\n-- [CINE] Tentative d'activation du portail\n-- \nfunction event_1686_13726(PandoraId)\n    PandoraIdval = toLong(PandoraId)\r\n    PlayerId = Context.getPlayer()\r\n    import(502000002001)\r\n    \r\n    function startCinematic()\r\n    \tCamera.setUserZoomLocked(true)\r\n    \tzoomFactor = Camera.getZoomFactor()\r\n    \tUI.closeMRU()\r\n    \tUI.closeAllBags()\t\t\t\t\t\t\t\t\t\t\t\t\r\n    \tUI.manageFrame(\"World\",false) \t\t\t\t\t\r\n    \tUI.setUIVisible(false)\t\r\n    \tUI.activateFollowAchievement(false)\r\n    \r\n    \tCamera.attachCameraToMobile(PandoraIdval)\r\n    \tUI.displayWideScreenBand(true)\r\n    end\r\n    \r\n    function endCinematic()\r\n    \tCamera.setUserZoomLocked(false)\t\t\r\n    \tCamera.setZoomFactor(zoomFactor)\t\t\t\t\t\t\t\t\r\n    \tUI.manageFrame(\"World\",true) \t\t\t\t\t\r\n    \tUI.setUIVisible(true)\t\r\n    \tUI.activateFollowAchievement(true)\r\n    \tCamera.attachCameraToMobile(PlayerId)\r\n    \tUI.displayWideScreenBand(false)\r\n    end\r\n    \r\n    function PandoraBubbleStart(mob,text)\r\n    \tBubbleText.closeBubbleAttachedTo(mob)\r\n    \tBubbleText.showText(mob, text, 0, 40, false)\r\n    end\r\n    \r\n    function GoToMachine() --2sec\r\n    \tMobile.moveMobile(PandoraIdval,-9,6,0,\"ActivateMachine\")\t\r\n    end\r\n    \r\n    function ActivateMachine() --3sec\r\n    \tMobile.setMobileDirection(PandoraIdval, 5)\r\n    \tMobile.setMobileAnimation(PandoraIdval, \"AnimComp-Fouille\")\r\n    \t\r\n    \tPandoraBubbleStart(PandoraIdval, \"quest.DDCH0.pandora.activatingMachine.2\")\t\r\n    \tinvoke(3000,1,\"MachineStart\")\t\r\n    end\r\n    \r\n    function MachineStart() --3sec\r\n    \tMobile.setMobileDirection(PandoraIdval, 7)\r\n    \tMobile.setMobileAnimation(PandoraIdval, \"AnimComp-Reflexion\")\r\n    \tPandoraBubbleStart(PandoraIdval, \"quest.DDCH0.pandora.activatingMachine.3\")\r\n    \t\r\n    \tCamera.setWorldTarget(-10,3,5)\r\n    \tEffect.createCameraShakeEffect(1000, 3000, 1000, 3)\r\n    \tSound.playSound(502000002001, true, 50)\t\r\n    \tlocal apsId = Particle.addParticleSystem(800521, -10, 3, 5)\r\n    \tinvoke(4000,1,\"MachineDontWork\", apsId)\r\n    end\r\n    \r\n    function MachineDontWork(apsId) --3sec\r\n    \tParticle.removeParticleSystem(apsId)\r\n    \tPandoraBubbleStart(PandoraIdval, \"quest.DDCH0.pandora.activatingMachine.4\")\r\n    \tinvoke(3000,1,\"GoToInitialPosition\")\r\n    end\r\n    \r\n    function GoToInitialPosition() --2sec\r\n     \tCamera.attachCameraToMobile(PandoraIdval)\r\n    \tMobile.moveMobile(PandoraIdval,-5,4,0,\"PandoraBubbleStart\",PandoraIdval,\"quest.DDCH0.pandora.activatingMachine.5\")\r\n    \tinvoke(6000,1,\"PandoraBubbleStart\",PandoraIdval, \"quest.DDCH0.pandora.activatingMachine.6\")\t\r\n    \tinvoke(9000,1,\"PandoraBubbleStart\",PandoraIdval, \"quest.DDCH0.pandora.activatingMachine.7\")\r\n    end\r\n    \r\n    \r\n    startCinematic()\r\n    invoke(1000,1,\"PandoraBubbleStart\",PandoraIdval, \"quest.DDCH0.pandora.activatingMachine.1\")\r\n    invoke(3000,1,\"GoToMachine\")\r\n    invoke(30000,1,\"endCinematic\")\nend\n\n-- [EVENT] Tentative d'ouverture du portail - Fin (validation quête + give item)\n-- \nfunction event_1686_13938()\n    \nend\n\n-- [CINE] Deuxième Activation - Wakfu au Max\n-- \nfunction event_1686_13737(PandoraId)\n    PandoraIdval = toLong(PandoraId)\r\n    PlayerId = Context.getPlayer()\r\n    import(502000002001)\r\n    \r\n    function startCinematic()\r\n    \tCamera.setUserZoomLocked(true)\r\n    \tzoomFactor = Camera.getZoomFactor()\r\n    \tUI.closeMRU()\r\n    \tUI.closeAllBags()\t\t\t\t\t\t\t\t\t\t\t\t\r\n    \tUI.manageFrame(\"World\",false) \t\t\t\t\t\r\n    \tUI.setUIVisible(false)\t\r\n    \tUI.activateFollowAchievement(false)\r\n    \r\n    \tCamera.attachCameraToMobile(PandoraIdval)\r\n    \tUI.displayWideScreenBand(true)\r\n    end\r\n    \r\n    function endCinematic()\r\n    \tCamera.setUserZoomLocked(false)\t\t\t\r\n    \tCamera.setZoomFactor(zoomFactor)\t\t\t\t\t\t\t\r\n    \tUI.manageFrame(\"World\",true) \t\t\t\t\t\r\n    \tUI.setUIVisible(true)\t\r\n    \tUI.activateFollowAchievement(true)\r\n    \r\n    \tCamera.attachCameraToMobile(PlayerId)\r\n    \tUI.displayWideScreenBand(false)\r\n    end\r\n    \r\n    function PandoraBubbleStart(mob,text)\r\n    \tBubbleText.closeBubbleAttachedTo(mob)\r\n    \tBubbleText.showText(mob, text, 0, 40, false)\r\n    end\r\n    \r\n    function MachineStart()\r\n    \tCamera.setWorldTarget(-10,3,5)\r\n    \tEffect.createCameraShakeEffect(1000, 3000, 1000, 3)\t\r\n    \tSound.playSound(502000002001,true,50)\t\r\n    \tinvoke(1000,1,\"MachineAlmostWork\")\t\r\n    end\r\n    \r\n    function MachineAlmostWork()\r\n    \tParticle.addParticleSystem(800521, -10,3,5)\r\n    end\r\n    \r\n    startCinematic()\r\n    invoke(3000,1,\"MachineStart\")\r\n    invoke(6000,1,\"endCinematic\")\nend\n\n-- [CINE] Deuxième Activation - Wakfu au Max\n-- \nfunction event_1686_13872()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - On masque le PNJ Pandora \"prologue\"\n-- \nfunction event_1686_20915(PandoraId)\n    Mobile.addMobileCreationCallback(PandoraId, \"hideMonster\", PandoraId)\nend\n\n-- [INIT] ENTER_INSTANCE - On masque le PNJ Pandora \"futur\"\n-- \nfunction event_1686_20916(PandoraVeilleurId)\n    Mobile.addMobileCreationCallback(PandoraVeilleurId, \"hideMonster\", PandoraVeilleurId)\nend\n\n","functions":["hideMonster","showMonster","event_1686_13696","event_1686_13697","event_1686_13940","event_1686_13726","startCinematic","endCinematic","PandoraBubbleStart","GoToMachine","ActivateMachine","MachineStart","MachineDontWork","GoToInitialPosition","event_1686_13938","event_1686_13737","startCinematic","endCinematic","PandoraBubbleStart","MachineStart","MachineAlmostWork","event_1686_13872","event_1686_20915","event_1686_20916"],"quest_calls":["UI.activateFollowAchievement(false)\r","UI.activateFollowAchievement(true)\r","UI.activateFollowAchievement(false)\r","UI.activateFollowAchievement(true)\r"],"dialogue_calls":[]},"scenario/1687.lua":{"source":"-- les fonctions où on cache\r\nfunction hideMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, false)\r\nend\r\n\r\n-- les fonctions où on rend visible (à nouveau\r\nfunction showMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, true)\r\nend\n\n-- [INITIALISATION] Variables\n-- \nfunction event_1687_13707(PandoraId, PandoraDef)\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_1687_13708()\n    \nend\n\n-- [EVENT] Le joueur revient de Frigost victorieux\n-- \nfunction event_1687_13744(PandoraId)\n    PandoraIdVal = toLong(PandoraId)\r\n    PlayerId = Context.getPlayer()\r\n    \r\n    x, y, z = Mobile.getMobilePosition(PlayerId)\r\n    \r\n    function animChute()\r\n    \tMobile.setMobileVisible(PlayerId, true)\r\n    \tMobile.setMobileDirection(PlayerId, 5)\r\n    \tMobile.setMobileAnimation(PlayerId, \"AnimIncarnam-Chute-Fin\", \"animEnd\")\r\n    end\r\n    \r\n    function animEnd()\r\n    \tMobile.setMobileDirection(PlayerId, 1)\r\n    end\r\n    \r\n    function MindBubbleStart(mob,text,tDuration)\r\n    \tMindBubble=BubbleText.showText(mob, text, 0, 40, false)\r\n    \tinvoke(tDuration,1,\"BubbleText.close\",MindBubble)\r\n    end\r\n    \r\n    function RemiseAZero()\r\n    Camera.setUserZoomLocked(false)\t\r\n    Camera.setZoomFactor(zoomFactor)\t\t\t\t\t\t\t\t\r\n    UI.manageFrame(\"World\",true) \t\t\t\t\t\r\n    UI.setUIVisible(true)\t\r\n    Camera.attachCameraToMobile(PlayerId)\r\n    UI.displayWideScreenBand(false)\r\n    UI.activateFollowAchievement(true)\r\n    end\r\n    \r\n    UI.manageFrame(\"World\",false)\r\n    zoomFactor = Camera.getZoomFactor()\r\n    Camera.setUserZoomLocked(true)\r\n    UI.closeMRU()\r\n    UI.closeAllBags()\r\n    UI.setUIVisible(false)\r\n    UI.activateFollowAchievement(false)\r\n    UI.displayWideScreenBand(true)\r\n    \r\n    Mobile.setMobileVisible(PlayerId, false)\r\n    Mobile.setMobileDirection(PandoraIdVal,3)\r\n    invoke(3200, 1, \"animChute\")\r\n    invoke(3200, 1, \"UI.manageFrame\",\"World\",false)\r\n    invoke(4000,1,\"Camera.attachCameraToMobile\",PandoraIdVal)\r\n    invoke(4200,1,\"Camera.setZoomFactor\",1.5)\r\n    invoke(4500,1,\"MindBubbleStart\",PandoraIdVal, \"quest.DDCH0.pandora.retourfrigost01\",4000)\r\n    invoke(8500,1,\"MindBubbleStart\",PandoraIdVal, \"quest.DDCH0.pandora.retourfrigost02\",4000)\r\n    invoke(12500,1,\"MindBubbleStart\",PandoraIdVal, \"quest.DDCH0.pandora.retourfrigost03\",4000)\r\n    invoke(16500,1,\"MindBubbleStart\",PandoraIdVal, \"quest.DDCH0.pandora.retourfrigost04\",4000)\r\n    invoke(20500,1,\"MindBubbleStart\",PandoraIdVal, \"quest.DDCH0.pandora.retourfrigost05\",4000)\r\n    invoke(24500,1,\"RemiseAZero\")\nend\n\n-- [INITIALISATION] Le Joueur termine la discussion avec Pandora\n-- \nfunction event_1687_13699()\n    Camera.setUserZoomLocked(true)\r\n    zoomFactor = Camera.getZoomFactor()\r\n    UI.closeMRU()\r\n    UI.closeAllBags()\t\t\t\t\t\t\t\t\t\t\t\t\r\n    UI.manageFrame(\"World\",false) \t\t\t\t\t\r\n    UI.setUIVisible(false)\t\r\n    UI.activateFollowAchievement(false)\r\n    \r\n    Camera.setWorldTarget(-1, -4, 8)\r\n    UI.displayWideScreenBand(true)\nend\n\n-- [STEP 1] Pandora dit de regarder\n-- \nfunction event_1687_13700(PandoraId)\n    PandoraIdval = toLong(PandoraId)\r\n    PlayerId = Context.getPlayer()\r\n    \r\n    function PandoraBubbleStart(mob,text)\r\n    \tPandoraBubble=BubbleText.showText(mob, text, 0, 40, false)\r\n    \tinvoke(3000,1,\"BubbleText.close\",PandoraBubble)\r\n    end\r\n    \r\n    \r\n    Camera.attachCameraToMobile(PandoraIdval)\r\n    playerDir = Mobile.getMobileDirection(PlayerId)\r\n    if (playerDir == 5) then\r\n    \tMobile.setMobileDirection(PandoraIdval, 1)\r\n    elseif (playerDir == 7) then\r\n    \tMobile.setMobileDirection(PandoraIdval, 3)\r\n    elseif(PlayerDir == 1) then\r\n    \tMobile.setMobileDirection(PandoraIdval, 5)\r\n    end\r\n    invoke(1000,1,\"PandoraBubbleStart\",PandoraIdval, \"quest.DDCH0.pandora.tp1.spotplayer\")\r\n    invoke(4000,1,\"PandoraBubbleStart\",PandoraIdval, \"quest.DDCH0.pandora.tp2.spotplayer\")\r\nend\n\n-- [STEP 2] Pandora se TP\n-- \nfunction event_1687_13701(PandoraId)\n    PandoraIdval = toLong(PandoraId)\r\n    \r\n    \r\n    \r\n    function teleportationPandora()\r\n    \tMobile.setMobileDirection(PandoraIdval, 5)\r\n    \tinvoke(1000,1,\"Mobile.setMobileAnimation\",PandoraIdval, \"AnimComp-Portail\")\r\n    \tinvoke(1500,1,\"Particle.addParticleSystem\",800519, -2, -5, 8)\r\n    \tinvoke(3000,1,\"Mobile.setMobileAnimation\",PandoraIdval, \"AnimComp-PortailEntree\")\r\n    \tinvoke(4000,1,\"Mobile.setMobileVisible\",PandoraIdval, false)\r\n    end\r\n    \r\n    Camera.attachCameraToMobile(PandoraIdval)\r\n    Camera.setZoomFactor(1.5)\r\n    invoke(1000,1,\"teleportationPandora\")\nend\n\n-- [STEP 2 BIS] Pandora se TP\n-- \nfunction event_1687_13728(PandoraId)\n    PandoraIdval = toLong(PandoraId)\r\n    \r\n    function teleportationPandoraRetour()\r\n    \tParticle.addParticleSystem(800518, 1, -4, 0)\r\n    \tinvoke(200,1,\"Mobile.setMobileVisible\",PandoraIdval, true)\r\n    \tinvoke(200,1,\"Camera.attachCameraToMobile\",PandoraIdval)\r\n    \tinvoke(200,1,\"Mobile.setMobileAnimation\",PandoraIdval, \"AnimComp-PortailSortie\")\r\n    \tinvoke(2000,1,\"teleportationPandora\")\r\n    end\r\n    \r\n    function teleportationPandora()\r\n    \tMobile.setMobileDirection(PandoraIdval, 3)\r\n    \tMobile.setMobileAnimation(PandoraIdval, \"AnimComp-Portail\")\r\n    \tinvoke(500,1,\"Particle.addParticleSystem\",800519, 1, -2, 0)\r\n    \tinvoke(1000,1,\"Mobile.setMobileAnimation\",PandoraIdval, \"AnimComp-PortailEntree\")\r\n    \tinvoke(2000,1,\"Mobile.setMobileVisible\",PandoraIdval, false)\r\n    end\r\n    \r\n    \r\n    teleportationPandoraRetour()\r\nend\n\n-- [STEP 2 TER] Pandora se TP\n-- \nfunction event_1687_13745(PandoraId)\n    PandoraIdval = toLong(PandoraId)\r\n    \r\n    function teleportationPandoraRetour()\r\n    \tParticle.addParticleSystem(800518, -3, -3, 4)\r\n    \tinvoke(200,1,\"Mobile.setMobileVisible\",PandoraIdval, true)\r\n    \tinvoke(200,1,\"Camera.attachCameraToMobile\",PandoraIdval)\r\n    \tinvoke(200,1,\"Mobile.setMobileAnimation\",PandoraIdval, \"AnimComp-PortailSortie\")\r\n    \tinvoke(2000,1,\"teleportationPandora\")\r\n    end\r\n    \r\n    function teleportationPandora()\t\r\n    \tMobile.setMobileAnimation(PandoraIdval, \"AnimComp-Portail\")\r\n    \tinvoke(500,1,\"Particle.addParticleSystem\",800519, -3, -1, 4)\r\n    \tinvoke(1000,1,\"Mobile.setMobileAnimation\",PandoraIdval, \"AnimComp-PortailEntree\")\r\n    \tinvoke(2000,1,\"Mobile.setMobileVisible\",PandoraIdval, false)\r\n    end\r\n    \r\n    Camera.attachCameraToMobile(PandoraIdval)\r\n    teleportationPandoraRetour()\nend\n\n-- [STEP 3] Retour Pandora\n-- \nfunction event_1687_13702(PandoraId)\n    PandoraIdval = toLong(PandoraId)\r\n    \r\n    function teleportationPandoraRetour()\r\n    \tParticle.addParticleSystem(800518, -1, -5, 8)\r\n    \tinvoke(200,1,\"Mobile.setMobileVisible\",PandoraIdval, true)\r\n    \tinvoke(200,1,\"Camera.attachCameraToMobile\",PandoraIdval)\r\n    \tinvoke(200,1,\"Mobile.setMobileAnimation\",PandoraIdval, \"AnimComp-PortailSortie\")\r\n    \r\n    \tinvoke(3000,1,\"PandoraBubbleEnd\",PandoraIdval, \"quest.DDCH0.pandora.tp3.spotplayer\")\r\n    end\r\n    \r\n    function PandoraBubbleEnd(mob,text)\r\n    \tplayerDir = Mobile.getMobileDirection(PlayerId)\r\n    \tif (playerDir == 5) then\r\n    \t\tMobile.setMobileDirection(PandoraIdval, 1)\r\n    \telseif (playerDir == 7) then\r\n    \t\tMobile.setMobileDirection(PandoraIdval, 3)\r\n    \telseif(PlayerDir == 1) then\r\n    \t\tMobile.setMobileDirection(PandoraIdval, 5)\r\n    \tend\r\n    \t\r\n    \tPandoraBubble=BubbleText.showText(mob, text, 0, 40, false)\r\n    \tinvoke(5000,1,\"BubbleText.close\",PandoraBubble)\r\n    end\r\n    \r\n    Camera.attachCameraToMobile(PandoraIdval)\r\n    teleportationPandoraRetour()\r\nend\n\n-- [STEP 4] Fin\n-- \nfunction event_1687_13727()\n    playerID = Context.getPlayer()\r\n    \r\n    Camera.setUserZoomLocked(false)\t\t\r\n    Camera.setZoomFactor(zoomFactor)\t\t\t\t\t\t\t\r\n    UI.manageFrame(\"World\",true) \t\t\t\t\t\r\n    UI.setUIVisible(true)\t\r\n    Camera.attachCameraToMobile(playerID)\r\n    UI.displayWideScreenBand(false)\r\n    UI.activateFollowAchievement(true)\r\nend\n\n-- [INITIALISATION 2] Le Joueur termine la discussion avec Pandora\n-- \nfunction event_1687_13749()\n    UI.manageFrame(\"World\",false) \t\t\t\t\t\r\n    \r\n    Camera.setWorldTarget(-1, -5, 8)\nend\n\n-- [STEP 5] Invocation Portail Pandora\n-- \nfunction event_1687_13750(PandoraId)\n    PandoraIdval = toLong(PandoraId)\r\n    import(\"420800521001\") -- important sinon, pas de son dans le script !!\r\n    \r\n    function teleportationPandoraPortail()\r\n    \tMobile.setMobileAnimation(PandoraIdval, \"AnimComp-Activation\")\r\n    \tinvoke(1000,1,\"\tSound.playSound\",420800521001,true,50)\t\r\n    \tinvoke(1000,1,\"Particle.addParticleSystem\",800520, 2, -3, 0)\r\n    \tinvoke(1000,1,\"Sound.playLocalSound\",11, 420800521001, 35, 2, -3, 0)\r\n    \tinvoke(1000,1,\"Camera.setWorldTarget\",2,-3,0)\r\n    end\r\n    \r\n    function PandoraBubbleStart(mob,text)\r\n    \tPandoraBubble=BubbleText.showText(mob, text, 0, 40, false)\r\n    \tinvoke(2500,1,\"BubbleText.close\",PandoraBubble)\r\n    end\r\n    \r\n    function teleportationPandora()\r\n    \tMobile.setMobileDirection(PandoraIdval, 5)\r\n    \tMobile.setMobileAnimation(PandoraIdval, \"AnimComp-Portail\")\r\n    \tinvoke(500,1,\"Particle.addParticleSystem\",800519, -2, -5, 8)\r\n    \tinvoke(2000,1,\"Mobile.setMobileAnimation\",PandoraIdval, \"AnimComp-PortailEntree\")\r\n    \tinvoke(3000,1,\"Mobile.setMobileVisible\",PandoraIdval, false)\r\n    end\r\n    \r\n    teleportationPandoraPortail()\r\n    invoke(1000,1,\"PandoraBubbleStart\",PandoraIdval, \"quest.DDCH0.pandora.tp4.spotplayer\")\r\n    Camera.attachCameraToMobile(PandoraIdval)\r\n    invoke(4000,1,\"teleportationPandora\")\r\n    \r\n    \r\nend\n\n-- [STEP 6] Fin\n-- \nfunction event_1687_13751()\n    playerID = Context.getPlayer()\r\n    \t\t\t\t\t\t\t\t\r\n    UI.manageFrame(\"World\",true) \t\t\t\t\t\r\n    Camera.attachCameraToMobile(playerID)\nend\n\n-- [STEP 6] Fin\n-- \nfunction event_1687_13842()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_1687_13871()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - On masque le PNJ Pandora \"prologue\"\n-- \nfunction event_1687_20913(PandoraId)\n    Mobile.addMobileCreationCallback(PandoraId, \"hideMonster\", PandoraId)\nend\n\n-- [INIT] ENTER_INSTANCE - On masque le PNJ Pandora \"futur\"\n-- \nfunction event_1687_20914(PandoraVeilleurId)\n    Mobile.addMobileCreationCallback(PandoraVeilleurId, \"hideMonster\", PandoraVeilleurId)\nend\n\n","functions":["hideMonster","showMonster","event_1687_13707","event_1687_13708","event_1687_13744","animChute","animEnd","MindBubbleStart","RemiseAZero","event_1687_13699","event_1687_13700","PandoraBubbleStart","event_1687_13701","teleportationPandora","event_1687_13728","teleportationPandoraRetour","teleportationPandora","event_1687_13745","teleportationPandoraRetour","teleportationPandora","event_1687_13702","teleportationPandoraRetour","PandoraBubbleEnd","event_1687_13727","event_1687_13749","event_1687_13750","teleportationPandoraPortail","PandoraBubbleStart","teleportationPandora","event_1687_13751","event_1687_13842","event_1687_13871","event_1687_20913","event_1687_20914"],"quest_calls":["UI.activateFollowAchievement(true)\r","UI.activateFollowAchievement(false)\r","UI.activateFollowAchievement(false)\r","UI.activateFollowAchievement(true)\r"],"dialogue_calls":[]},"scenario/1688.lua":{"source":"function hideMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, false)\r\nend\r\n\r\nfunction setSwitchIEStateNormal(InteractiveElementId)\r\n\tParticle.addParticleSystem(1016305, -21, -1, 13)\r\n\tInteractiveElement.setAnimation(InteractiveElementId, \"AnimStatique_1\")\r\nend\r\n\r\nfunction setSwitchIEStateHardcore(InteractiveElementId)\r\n\tParticle.addParticleSystem(1016314, -21, -1, 14)\r\n\tInteractiveElement.setAnimation(InteractiveElementId, \"AnimStatique_3\")\r\nend\n\n-- Variable - Initialisation (seulement 1 execution)\n-- \nfunction event_1688_13710()\n    \nend\n\n-- [EVENT][SOFTCORE] Le joueur entre dans l'instance - Pas de combat en cours\n-- \nfunction event_1688_13711()\n    \nend\n\n-- [EVENT][HARDCORE] Le joueur entre dans l'instance - Pas de combat en cours\n-- \nfunction event_1688_13712()\n    \nend\n\n-- [EVENT] Le joueur entre dans l'instance - Combat en cours (préparation ou action phase)\n-- \nfunction event_1688_13713()\n    UI.openInfoDialog(\"donjon.shushu.rules.title\", \"donjon.shushu.rules.desc\")\nend\n\n-- [EVENT][SOFTCORE] Le joueur quitte l'instance - Pas de Combat en cours\n-- \nfunction event_1688_13714()\n    \nend\n\n-- [EVENT][HARDCORE] Le joueur quitte l'instance - Pas de Combat en cours\n-- \nfunction event_1688_13715()\n    \nend\n\n-- [EVENT] Variable - Début Phase Préparation\n-- \nfunction event_1688_13716()\n    \nend\n\n-- [EVENT] Variable - Fin Phase Préparation - Début Action Phase\n-- \nfunction event_1688_13717(fightId)\n    \nend\n\n-- [EVENT][SOFTCORE] Variable - Fin du combat\n-- \nfunction event_1688_13718()\n    \nend\n\n-- [EVENT]HARDCORE] Variable - Fin du combat\n-- \nfunction event_1688_13719()\n    \nend\n\n-- [EVENT] Fin du combat avec victoire des Joueurs - Validation Quête Journalière\n-- \nfunction event_1688_13720()\n    \nend\n\n-- [IE] Activation du hardcoreMode\n-- \nfunction event_1688_13721(mA, mB, mC, mD, mE, mF, mG, mH, switchIE)\n    setSwitchIEStateHardcore(toLong(switchIE))\r\n    \r\n    monstersList = {mA,mB,mC,mD,mE,mF,mG,mH}\r\n    for index = 1, #monstersList do\r\n      Mobile.setMobileVisible(monstersList[index], false)\r\n    end\nend\n\n-- [IE] Désactivation du hardcoreMode\n-- \nfunction event_1688_13722(mA, mB, mC, mD, mE, mF, mG, mH, switchIE)\n    setSwitchIEStateNormal(toLong(switchIE))\r\n    \r\n    monstersList = {mA,mB,mC,mD,mE,mF,mG,mH}\r\n    for index = 1, #monstersList do\r\n      Mobile.setMobileVisible(monstersList[index], false)\r\n    end\nend\n\n-- [SYNCHRO][SOFTCORE] Le joueur entre dans l'instance - Le mode Softcore est actif\n-- \nfunction event_1688_13723(gA, gB, gC, gD, gE, gF, gG, gH, switchIE)\n    InteractiveElement.addIECreationCallback(toLong(switchIE), \"setSwitchIEStateNormal\", switchIE)\r\n    \r\n    monstersList = {gA,gB,gC,gD,gE,gF,gG,gH}\r\n    for index = 1, #monstersList do\r\n    \tMobile.addMobileCreationCallback(monstersList[index], \"hideMonster\", monstersList[index])\r\n    end\nend\n\n-- [SYNCHRO][HARDCORE] Le joueur entre dans l'instance - Le mode Hardcore est actif\n-- \nfunction event_1688_13724(gA, gB, gC, gD, gE, gF, gG, gH, switchIE)\n    InteractiveElement.addIECreationCallback(toLong(switchIE), \"setSwitchIEStateHardcore\", switchIE)\r\n    \r\n    monstersList = {gA,gB,gC,gD,gE,gF,gG,gH}\r\n    for index = 1, #monstersList do\r\n    \tMobile.addMobileCreationCallback(monstersList[index], \"hideMonster\", monstersList[index])\r\n    end\nend\n\n","functions":["hideMonster","setSwitchIEStateNormal","setSwitchIEStateHardcore","event_1688_13710","event_1688_13711","event_1688_13712","event_1688_13713","event_1688_13714","event_1688_13715","event_1688_13716","event_1688_13717","event_1688_13718","event_1688_13719","event_1688_13720","event_1688_13721","event_1688_13722","event_1688_13723","event_1688_13724"],"quest_calls":[],"dialogue_calls":[]},"scenario/1691.lua":{"source":"nbFight = 0\n\n-- [EVENT] Un combat se lance - Phase de préparation terminée\n-- \nfunction event_1691_13953()\n    \nend\n\n-- [EVENT] Soin des joueurs en cas de victoire\n-- \nfunction event_1691_16858()\n    \nend\n\n-- [INIT] Variables Globales\n-- \nfunction event_1691_21908()\n    \nend\n\n-- [INIT] Inscription du joueur + Variables Locales\n-- \nfunction event_1691_21909(room)\n    \nend\n\n-- USER_GROUP_KILLED - Salle 01\n-- \nfunction event_1691_21910()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 02 - BOSS\n-- \nfunction event_1691_21911()\n    \nend\n\n-- Déplace le joueur vers la salle suivante\n-- \nfunction event_1691_21912