\n-- [ARCHI] Apparition de l'Archimonstre\n-- \nfunction event_1692_23983()\n    \nend\n\n","functions":["event_1692_21903","event_1692_21904","event_1692_21905","event_1692_21906","event_1692_22771","event_1692_22776","event_1692_22772","event_1692_21907","event_1692_22848","event_1692_22849","event_1692_22879","event_1692_23983"],"quest_calls":[],"dialogue_calls":[]},"scenario/1693.lua":{"source":"\n\n-- [INIT] Variables\n-- \nfunction event_1693_13772(questProgress, sramyId, scoutId, timerProgress, failQuest, randomQuest, timerMaxQuest)\n    scoutIdVal = toLong(scoutId)\r\n    --Mobile.setMobileVisible(ScenarioVar(\"scoutIdVal\"), false)\r\nend\n\n-- [INIT] Init timer base\n-- \nfunction event_1693_14092(timerProgress, randomQuest, timerMaxQuest)\n    \nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_1693_13773(timerProgress, randomQuest, timerMaxQuest)\n    randomQuestVal = toLong(randomQuest)\r\n    timerProgressVal = toLong(timerProgress)\r\n    timerMaxQuest = toLong(timerMaxQuest)\r\n    if timerProgressVal < (timerMaxQuest) then \r\n    TimerOnEnter = (((timerMaxQuest) - timerProgressVal)/1000)\r\n    --UI.displayCountdown(TimerOnEnter, 1)\r\n    UI.startCountdown(TimerOnEnter)\r\n    end\r\n    \r\n    --trace(\"============VALEUR DU RANDOM============        \", randomQuestVal)\r\nend\n\n-- [EVENT] Joueur check objet wrong hiding place - All Zones\n-- \nfunction event_1693_13776(questProgress)\n    PlayerId = Context.getLeaderId()\r\n    \r\n    function MindBubbleStart(mob,text)\r\n    \tMindBubble=BubbleText.showText(mob, text, 0, 40, false)\r\n    \tinvoke(5000,1,\"BubbleText.close\",MindBubble)\r\n    end\r\n    \r\n    \r\n    MindBubbleStart (PlayerId, \"quest.DDCH1.ruelle.nothingspecial\")\r\nend\n\n-- [EVENT] Joueur check hiding placeZ01 Not OK\n-- \nfunction event_1693_13785(questProgress, timerMaxQuest)\n    PlayerId = Context.getLeaderId()\r\n    \r\n    function MindBubbleStart(mob,text)\r\n    \tMindBubble=BubbleText.showText(mob, text, 