tesText = \" \"\r\n    timerSecondsText = \" \"\r\n    \r\n    function MindBubbleStart(mob,text,tDuration)\r\n    \tMindBubble=BubbleText.showText(mob, text, 0, 40, false)\r\n    \tinvoke(tDuration,1,\"BubbleText.close\",MindBubble)\r\n    end\r\n    \r\n    --function timerDisplay ()\r\n    timerSearch = (timerMaxQuest - (timerProgressVal))\r\n    --trace(\"value of variable timerSearch :::::\", timerSearch)\r\n    \r\n    \r\n    if timerSearch >0 then\r\n    \t--timerTable = os.date (\"*t\", timerSearch )\r\n    \t--timerMinutes = timerTable[\"min\"]\r\n    \t--trace(\"timerminutefromtable ::::: \", timerMinutes)\r\n    \t--trace(\"timerminutefromdatesystem ::::: \", os.date(\"%M\", timerSearch))\r\n    \t--timerSeconds = timerTable[\"sec\"]\r\n    \t--trace(\"timersecondsfromtable ::::: \", timerSeconds)\r\n    \t--trace(\"timersecondsfromdatesystem ::::: \", os.date(\"%S\", timerSearch))\r\n    \t--timerText =  timerMinutes .. \" : \".. timerSeconds\r\n    \t--trace(\"current time progress of quest is ::::: \", timerText)\r\n    \t--trace(\"Contenu de la table de time convertion ::::\", table.concat(timerTable, \";\"))\r\n    \t\r\n    \ttimerMinutesMin = math.floor((timerSearch /60000) - 0.5)\r\n    \ttimerMinutesMax = math.ceil((timerSearch /60000) + 0.5)\r\n    \tif timerMinutesMin < 0 then\r\n    \t\ttimerMinutesMin = 0\r\n    \tend\r\n    \ttimerMinutes = math.min(timerMinutesMin, timerMinutesMax)\r\n    \r\n    \ttimerSecondsMax = math.ceil(((timerSearch - (60000*timerMinutes))/1000)+0.5)\r\n    \ttimerSecondsMin = math.floor(((timerSearch - (60000*timerMinutes))/1000)-0.5)\r\n    \tif timerSecondsMin < 0 then\r\n    \t\ttimerSecondsMin = 0\r\n    \tend\r\n    \ttimerSeconds =math.max(timerSecondsMin, timerSecondsMax)\r\n    \t\r\n    \tif timerMinutes < 10 then\r\n    \t\ttimerMinutesText = \"0\"..timerMinutes\r\n    \telse\r\n    \t\ttimerMinutesText = toString(timerMinutes)\r\n    \tend\r\n    \tif timerSeconds < 10 then\r\n    \t\ttimerSecondsText= \"0\"..timerSeconds\r\n    \telse\r\n    \t\ttimerSecondsText = toString(timerSeconds)\r\n    \tend\r\n    \r\n    \ttimerText =  timerMinutesText .. \" : \".. timerSecondsText\t\r\n    \t--trace(\"current time progress of quest hand calculation ::::: \", timerText)\r\n    \t--MindBubbleStart(playerId, timerText ,1000)\r\n    end\r\n    \r\n    -- BubbleText.showText(playerId, timerMinutes +\" : \"+timerSeconds, 0, 40, false)\r\n    --end\r\n    \r\n    --tInterval(1000, timerDisplay) : refreshTimerDisplay\r\nend\n\n-- [EVENT] Echec de la poursuite (temps écoulé)\n-- \nfunction event_1693_13874(timerProgress, questProgress, failQuest, timerMaxQuest)\n    PlayerId = Context.getLeaderId()\r\n    \r\n    function startCineSrambadFirst()\r\n    \tUI.manageFrame(\"World\",false) \t\t\t\t\t\r\n    \tCamera.setUserZoomLocked(true)\r\n    \tUI.closeMRU()\r\n    \tUI.closeAllBags()\t\t\t\t\t\t\t\t\t\t\t\t\r\n    \tUI.manageFrame(\"World\",false) \t\t\t\t\t\r\n    \tUI.setUIVisible(false)\r\n    \tUI.displayWideScreenBand(true)\r\n    end\r\n    \r\n    function MindBubbleStart(mob,text,tDuration)\r\n    \tMindBubble=BubbleText.showText(mob, text, 0, 40, false)\r\n    \tinvoke(tDuration,1,\"BubbleText.close\",MindBubble)\r\n    end\r\n    \r\n    startCineSrambadFirst()\r\n    invoke(100,1,\"MindBubbleStart\",PlayerId, \"quest.DDCH1.scoutlosttrack\",3000)\r\n    UI.stopCountdown()\r\nend\n\n-- [EVENT] Echec de la poursuite (reset event)\n-- \nfunction event_1693_13875(timerProgress, failQuest, timerMaxQuest)\n    PlayerId = Context.getLeaderId()\r\n    \r\n    function endCineSrambadFirst()\r\n    \tCamera.attachCameraToMobile(PlayerId)\r\n    \tUI.displayWideScreenBand(false)\r\n    \tCamera.setUserZoomLocked(false)\t\t\t\t\t\t\t\t\t\t\t\t\r\n    \tUI.setUIVisible(true)\t\r\n    \tUI.manageFrame(\"World\",true)\r\n    --UI.startCountdown(TimerOnEnter)\r\n    end\r\n    \r\n    endCineSrambadFirst()\nend\n\n-- [EVENT] joueur quitte l'instance (avant fin du décompte)\n-- \nfunc