hedTo(mob)\r\n\tBubbleText.showText(mob, text, 0, 40, false)\r\nend\r\n\n\n-- [INIT] Variables\n-- \nfunction event_1694_13778()\n    \nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_1694_13779(fightStarted)\n    fightStartedval = toLong(fightStarted)\r\n    trace(\"value of fightStarted on enter instance :::::\", fightStartedval)\nend\n\n-- [COMBAT]] Combat contre les Srams - Apparition\n-- \nfunction event_1694_13782(SramIdOne, SramIdTwo, SramIdThree)\n    one = toLong(SramIdOne)\r\n    two = toLong(SramIdTwo)\r\n    three = toLong(SramIdThree)\r\n    \r\n    Mobile.setMobileAnimation(one,\"AnimSort-Apparition\")\r\n    Mobile.setMobileAnimation(two,\"AnimSort-Apparition\")\r\n    Mobile.setMobileAnimation(three,\"AnimSort-Apparition\")\r\n    Camera.attachCameraToMobile(one)\r\n    invoke(1000,1,\"Bubble\",one,\"quest.DDCH1.ingloriom.sramAttack.1\")\r\n    invoke(2500,1,\"Bubble\",two,\"quest.DDCH1.ingloriom.sramAttack.2\")\r\n    invoke(4900,1,\"Camera.attachCameraToMobile\",playerId)\nend\n\n-- [COMBAT]] Combat contre les Srams - Lancement du Combat\n-- \nfunction event_1694_13824(fightStarted)\n    fightStartedval = toLong(fightStarted)\r\n    --trace(\"value of fightStarted on Fight starting :::::\", fightStartedval)\r\nend\n\n-- [COMBAT]  Combat contre les Srams - début du combat - on ajoute Pandora\n-- \nfunction event_1694_13831(fightStarted)\n    fightStartedval = toLong(fightStarted)\r\n    --trace(\"value of fightStarted on Fight running :::::\", fightStartedval)\r\nend\n\n-- [CINE] Fuite du Sram - Fin de combat - Valide ACH 1973\n-- \nfunction event_1694_13783()\n    \nend\n\n-- [CINE] Fuite du Sram - Apparition\n-- \nfunction event_1694_13829(MentorId, PandoraId)\n    sram = Mobile.generateClientMobileId()\r\n    mentor = toLong(MentorId)\r\n    pandora = toLong(PandoraId)\r\n    \r\n    function mentorSpeach()\r\n    \tCamera.attachCameraToMobile(mentor)\r\n    \tBubble(mentor,\"quest.DDCH1.ingloriom.mentor.1\")\r\n    \tinvoke(2500,1,\"Bubble\",mentor,\"quest.DDCH1.ingloriom.mentor.2\")\r\n    \tinvoke(5000,1,\"Bubble\",mentor,\"quest.DDCH1.ingloriom.mentor.3\")\r\n    \tinvoke(7000,1,\"playerGoToSrambad\")\r\n    end\r\n    \r\n    function playerGoToSrambad()\r\n    \tCamera.attachCameraToMobile(playerId)\r\n    \tMobile.moveMobile(pandora, -22,-13, 28)\r\n    \tinvoke(500, 1, \"Mobile.moveMobile\", playerId, -23, -12, 28)\r\n    end\r\n    \r\n    --Démarrage cinématique\r\n    startCine()\r\n    Camera.setZoomFactor(1.5)\r\n    Sound.playForcedMusic(290039)\r\n    Actor.createActor(sram, 163403122, -21, -3, 19)\r\n    Camera.attachCameraToMobile(sram)\r\n    Mobile.setMobileAnimation(sram,\"AnimSort-Apparition\")\r\n    invoke(1000,1,\"Mobile.moveMobile\",sram, -21,-7,21,\"Mobile.setMobileAnimation\",sram,\"AnimSort-Disparition\")\r\n    \r\n    invoke(5000,1,\"mentorSpeach\")\nend\n\n-- [CINE] Fuite du Sram - Suite\n-- \nfunction event_1694_13784(PandoraId)\n    pandora = toLong(PandoraId)\r\n    \r\n    Mobile.setMobileAnimation(pandora,\"AnimComp-Activation\")\r\n    invoke(1500,1,\"Particle.addParticleSystem\",800522, -22,-14,28)\r\n    invoke(1500,1,\"Sound.playSound\",420800522001,true,50)\r\n    \r\n    \r\nend\n\n-- [CINE] Fuite du Sram - Fin\n-- \nfunction event_1694_13898()\n    \nend\n\n-- [DIAL] Le joueur parle à Pandora\n-- \nfunction event_1694_13830(PandoraId)\n    pandora = toLong(PandoraId)\r\n    \r\n    Bubble(pandora,\"quest.DDCH1.ingloriom.pandora\")\nend\n\n-- [COMBAT] Combat contre les Sram - Enregistrment de l'évènement\n-- \nfunction event_1694_14167(fightStarted)\n    \nend\n\n-- [INIT] ENTER_INSTANCE - combat en cours\n-- \nfunction event_1694_14168(fightStarted)\n    UI.loadTutorialDialog(\"null\",\"quest.running.title\",\"quest.dd.ch1.inglorium.running.desc\")\r\n    \r\n    fightStartedval = toLong(fightStarted)\r\n    trace(\"value of fightStarted on Fight running when entering Instance :::::\", fightStartedval)\nend\n\n","functions":["startCine","endCine","Bubble","event_1694_13778","event_1694_13779","event_1694_13782","event_1694_13824","event_1694_13831","event_1694_13783","event_1694_13829","mentorSpeach","playerGoToSrambad","event_1694_13784","event_1694_13898","event_1694_13830","event_1694_14167","event_1694_14168"],"quest_calls":[],"dialogue_calls":[]},"scenario/1695.lua":{"source":"\n\n-- [INIT] Variables\n-- \nfunction event_1695_13793()\n    \nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_1695_13794()\n    \nend\n\n-- [COMBAT] Combat contre les Srams\n-- \nfunction event_1695_13795()\n    \nend\n\n-- [COMBAT] Combat contre les Srams\n-- \nfunction event_1695_13839()\n    \nend\n\n-- [COMBAT] Lancement du combat\n-- \nfunction event_1695_13840()\n    \nend\n\n-- [COMBAT] Victoire - Récompense de quête\n-- \nfunction event_1695_13912()\n    \nend\n\n-- [EVENT] Défaite\n-- \nfunction event_1695_14165(mobOne, mobTwo, mobThree, mobFour, mobFive)\n    UI.manageFrame(\"World\",false) \nend\n\n-- [TICK] Défaite - TP hors de l'instance\n-- \nfunction event_1695_14166()\n    UI.manageFrame(\"World\",true) \nend\n\n","functions":["event_1695_13793","event_1695_13794","event_1695_13795","event_1695_13839","event_1695_13840","event_1695_13912","event_1695_14165","event_1695_14166"],"quest_calls":[],"dialogue_calls":[]},"scenario/1699.lua":{"source":"function startCinematicContext()\r\n    zoomFactor = Camera.getZoomFactor()\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\t\t\t\t\t\t\t\t\t\t\t\t\r\n\tUI.manageFrame(\"World\",false) \t\t\t\t\t\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\nend\r\n\r\nfunction endCinematicContext()\r\n\tlocal playerId = Context.getLeaderId()\r\n\t\r\n\tCamera.setUserZoomLocked(false)\t\t\t\t\t\t\t\t\t\r\n\tUI.manageFrame(\"World\",true) \t\t\t\t\t\r\n\tUI.setUIVisible(true)\t\r\n\tUI.activateFollowAchievement(true)\r\n\tCamera.attachCameraToMobile(playerId)\r\n\tUI.displayWideScreenBand(false)\r\n\tCamera.setZoomFactor(zoomFactor)\t\r\nend\r\n\r\nfunction MindBubbleStart(mob,text,tDuration)\r\n\tMindBubble=BubbleText.showText(mob, text, 0, 40, false)\r\n\tinvoke(tDuration,1,\"BubbleText.close\",MindBubble)\r\nend\n\n-- [INITIALISATION] Variables\n-- \nfunction event_1699_14009()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_1699_14010(PandoraId, ChadId, BanquierId)\n    local BanquierIdVal = toLong(BanquierId)\r\n    local PandoraIdval = toLong(PandoraId)\r\n    local ChadIdval = toLong(ChadId)\r\n    \r\n    invoke(100, 1, \"Mobile.setMobileVisible\", PandoraIdval, false)\t\r\n    invoke(100, 1, \"Mobile.setMobileVisible\", ChadIdval, false)\nend\n\n-- [EVENT] Arrivée dans l'instance - Cinématique Banquier 1\n-- \nfunction event_1699_14051(PandoraId, ChadId, BanquierId)\n    PlayerId = Context.getLeaderId()\r\n    BanquierIdVal = toLong(BanquierId)\r\n    PandoraIdval = toLong(PandoraId)\r\n    ChadIdval = toLong(ChadId)\r\n    ChadActorIdval = 0\r\n    PandoraActorIdval = 0\r\n    \r\n    function startCine()\r\n    \tstartCinematicContext()\r\n    \t\r\n    \tMobile.setMobileVisible(PandoraIdval, false)\t\r\n    \tMobile.setMobileVisible(ChadIdval, false)\t\t\r\n    \t\r\n    \tCamera.attachCameraToMobile(PlayerId)\r\n    \tCamera.setZoomFactor(1.6)\r\n    \t\r\n    \tPandoraActorIdval = Mobile.generateClientMobileId() \r\n    \tActor.createActor(PandoraActorIdval, 163503082, 1, 0, 0, 4)\r\n    \t\r\n    \tChadActorIdval = Mobile.generateClientMobileId() \r\n    \tActor.createActor(ChadActorIdval, 163503107, -1, -1,  0, 4)\r\n    end\r\n    \r\n    function apparitionPandoraChad()\r\n    \tMobile.setMobileDirection(PandoraActorIdval,3)\r\n    \tMobile.setMobileVisible(PandoraActorIdval, true)\t\r\n    \tMobile.setMobileAnimation(PandoraActorIdval,\"AnimComp-Fouille\")\r\n    \tMobile.setMobileDirection(ChadActorIdval,7)\r\n    \tMobile.setMobileVisible(ChadActorIdval, true)\r\n    \tMobile.setMobileDirection(PlayerId,3)\r\n    \tMobile.setMobileAnimation(PlayerId,\"AnimEmoteMarket-HausseEpaules\")\r\n    end\r\n    \r\n    function movePandoraChad()\r\n    \tMobile.setMobileDirection(PandoraActorIdval,7)\r\n    \tMobile.setMobileDirection(ChadActorIdval,7)\r\n    \tMobile.setMobileDirection(PlayerId,7)\r\n    \tinvoke(4200,1,\"Mobile.moveMobile\",ChadActorIdval, -1,-5,0)\r\n        invoke(4700,1,\"Mobile.moveMobile\",PandoraActorIdval, 1,-6,0)\r\n        invoke(5000,1,\"Mobile.moveMobile\",PlayerId, 0,-7,0)\r\n     end\r\n     \r\n     function endCine()\r\n    \tendCinematicContext()\r\n    \t\r\n    \tMobile.setMobileVisible(PandoraActorIdval, false)\t\r\n    \tMobile.setMobileVisible(ChadActorIdval, false)\t\t\r\n    \t\r\n    \tActor.deleteActor(PandoraActorIdval)\r\n    \tMobile.setMobileVisible(PandoraIdval, true)\r\n    \t\r\n    \tActor.deleteActor(ChadActorIdval)\r\n    \tMobile.setMobileVisible(ChadIdval, true)\r\n    \t\r\n    \tServer.triggerEvent(14051)\r\n    end\r\n    \r\n    startCine()\r\n    \t\r\n    invoke(00150,1,\"apparitionPandoraChad\")\r\n    \r\n    invoke(02500, 1, \"MindBubbleStart\", PandoraActorIdval, \"quest.DDCH2.banque.cine.1\", 4000)\r\n    invoke(06500, 1, \"MindBubbleStart\", PlayerId, \"quest.DDCH2.banque.cine.2\", 4000)\r\n    invoke(11000, 1, \"MindBubbleStart\", ChadActorIdval, \"quest.DDCH2.banque.cine.3\", 4000)\r\n    \r\n    invoke(13000, 1, \"movePandoraChad\")\r\n    invoke(14000, 1, \"MindBubbleStart\", PandoraActorIdval, \"quest.DDCH2.banque.cine.4\", 4000)\r\n    invoke(14000, 1, \"MindBubbleStart\" ,PlayerId, \"quest.DDCH2.banque.cine.4\", 4000)\r\n    \r\n    invoke(22000, 1, \"endCine\")\nend\n\n-- [EVENT] Fin Cinématique Banquier 1\n-- \nfunction event_1699_14061()\n    \nend\n\n-- [EVENT] Joueur parle au Banquier - Cinématique Banquier 2\n-- \nfunction event_1699_14047(BanquierId, PandoraId, ChadId)\n    PlayerId = Context.getLeaderId()\r\n    BanquierIdVal = toLong(BanquierId)\r\n    PandoraIdval = toLong(PandoraId)\r\n    ChadIdval = toLong(ChadId)\r\n    \r\n    --Cha