,PandoraIdval, \"quest.DDCH2.banque.parle.pandora\",4000)\nend\n\n-- [DIAL] en cours - Le joueur parle à Chad\n-- \nfunction event_1699_14059(ChadId)\n    local ChadIdval = toLong(ChadId)\r\n    \r\n    BubbleText.closeBubbleAttachedTo(ChadIdval)\r\n    invoke(100,1,\"MindBubbleStart\",ChadIdval, \"quest.DDCH2.banque.parle.chad\",4000)\nend\n\n-- [DIAL] fin - Le joueur parle à Pandora\n-- \nfunction event_1699_14078(PandoraId)\n    local PandoraIdval = toLong(PandoraId)\r\n    \r\n    BubbleText.closeBubbleAttachedTo(PandoraIdval)\r\n    invoke(100,1,\"MindBubbleStart\",PandoraIdval, \"quest.DDCH2.banque.parle.pandorafin\",4000)\r\n    Mobile.setMobileAnimation(PandoraIdval,\"AnimComp-Activation\")\nend\n\n-- [DIAL] fin - Le joueur parle à Chad\n-- \nfunction event_1699_14079(ChadId)\n    local ChadIdval = toLong(ChadId)\r\n    \r\n    BubbleText.closeBubbleAttachedTo(ChadIdval)\r\n    invoke(100,1,\"MindBubbleStart\",ChadIdval, \"quest.DDCH2.banque.parle.chadfin\",4000)\nend\n\n","functions":["startCinematicContext","endCinematicContext","MindBubbleStart","event_1699_14009","event_1699_14010","event_1699_14051","startCine","apparitionPandoraChad","movePandoraChad","endCine","event_1699_14061","event_1699_14047","event_1699_14014","event_1699_14058","event_1699_14059","event_1699_14078","event_1699_14079"],"quest_calls":["UI.activateFollowAchievement(true)\r"],"dialogue_calls":[]},"scenario/1700.lua":{"source":"function MindBubbleStart(mob,text,tDuration)\r\n\tMindBubble=BubbleText.showText(mob, text, 0, 40, false)\r\n\tinvoke(tDuration,1,\"BubbleText.close\",MindBubble)\r\nend\r\n\r\nfunction startCinematic()\r\n\tzoomFactor = Camera.getZoomFactor()\r\n\tUI.manageFrame(\"World\",false) \t\t\t\t\t\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\t\t\t\t\t\t\t\t\t\t\t\t\r\n\tUI.manageFrame(\"World\",false) \t\t\t\t\t\r\n\tUI.setUIVisible(false)\r\n\tUI.activateFollowAchievement(false)\r\n\tUI.displayWideScreenBand(true)\r\nend\r\n\r\nfunction endCinematic()\r\n\tlocal playerId = Context.getLeaderId()\r\n\t\r\n\tCamera.attachCameraToMobile(playerId)\r\n\tUI.displayWideScreenBand(false)\r\n\tCamera.setUserZoomLocked(false)\t\t\t\t\t\t\t\t\t\t\t\t\r\n\tUI.setUIVisible(true)\r\n\tUI.activateFollowAchievement(true)\r\n\tUI.manageFrame(\"World\", true) \t\t\t\t\t\r\n\tCamera.setZoomFactor(zoomFactor)\t\r\n\tUI.startCountdown(TimerOnEnter)\r\nend\r\n\r\nfunction displayFail(args)\n\tlocal playerId = Context.getLeaderId()\r\n\r\n\tUI.stopCountdown()\r\n\tstartCinematic()\r\n\tinvoke(100, 1, \"MindBubbleStart\", playerId, \"quest.DDCH2.bankfail\", 3000)\r\n\r\n\tinvoke(3400, 1, \"endCinematic\")\r\n\tinvoke(3500, 1, \"Server.triggerEvent\", 14052)\nend\n\n-- [EVENT] Variables\n-- \nfunction event_1700_13930(timerProgress, questProgress, failQuest, inFight, timerMaxQuest, fightOneDifficulty, fightTwoDifficulty, fightThreeDifficulty, mobAA, mobAB, mobAC, mobAD, mobAE, mobAF, mobAG, mobAH)\n    \nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_1700_13931()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Combat en cours\n-- \nfunction event_1700_14175()\n    UI.loadTutorialDialog(\"null\",\"quest.running.title\",\"quest.dd.ch1.inglorium.running.desc\")\nend\n\n-- [INIT] ENTER_INSTANCE - Quête en cours\n-- \nfunction event_1700_13962(timerProgress, timerMaxQuest)\n    local timerProgressVal = toLong(timerProgress)\r\n    local timerMaxQuestVal = toLong(timerMaxQuest)\r\n    \r\n    if timerProgressVal < timerMaxQuestVal then \r\n    \tTimerOnEnter = (((timerMaxQuestVal + 2000) - timerProgressVal)/1000)\r\n    \tUI.startCountdown(TimerOnEnter)\r\n    end\r\nend\n\n-- [EVENT] Quitte l'instance (avant fin du décompte)\n-- \nfunction event_1700_13936(timerProgress, questProgress, timerMaxQuest, fightOneDifficulty, fightTwoDifficulty, fightThreeDifficulty)\n    UI.stopCountdown()\nend\n\n-- [EVENT] CINE - Joueur arrive dans l'embuscade\n-- \nfunction event_1700_13932(questProgress, timerProgress, playerOne, playerTwo, playerThree, playerFour, playerFive, playerSix)\n    playerId = Context.getLeaderId()\r\n    x, y, z = Mobile.getMobilePosition(playerId)\r\n    playerOneId = toLong(playerOne)\r\n    playerTwoId = toLong(playerTwo)\r\n    playerThreeId = toLong(playerThree)\r\n    playerFourId = toLong(playerFour)\r\n    playerFiveId = toLong(playerFive)\r\n    playerSixId = toLong(playerSix)\r\n    boucleSramkill = 0\r\n    \r\n    \r\n    \r\n    trace(\"Player One ID ::::::::::::\", playerOneId)\r\n    trace(\"Player Two ID :::::::::::\", playerTwoId)\r\n    trace(\"Player Three ID :::::::::\", playerThreeId)\r\n    trace(\"Player Four ID :::::::::::\", playerFourId)\r\n    trace(\"Player Five ID ::::::::::::\", playerFiveId)\r\n    trace(\"Player Six ID ::::::::::::::\", playerSixId)\r\n    \r\n    \r\n    function apparition(mobileId)\r\n    \tMobile.setMobileVisible(mobileId, true)\r\n    \tMobile.setMobileDirection(mobileId, 3)\r\n    \tMobile.setMobileAnimation(mobileId, \"AnimApparition\")\r\n    end\r\n    function bodyapparition(mobileId)\r\n    \tMobile.setMobileVisible(mobileId, true)\r\n    \tMobile.setMobileDirection(mobileId, 3)\r\n    \tMobile.setMobileAnimation(mobileId, \"AnimSort-03-Fin\")\r\n    end\r\n    function scoutapparition(mobileId)\r\n         x, y, z = Mobile.getMobilePosition(mobileId)\r\n        Particle.addParticleSystem(800174, x, y, z)\r\n    \tMobile.setMobileVisible(mobileId, true)\r\n    \tMobile.setMobileDirection(mobileId, 3)\r\n    \tMobile.setMobileAnimation(mobileId, \"AnimSort-Apparition\")\r\n    end\r\n    \r\n    --avancée des gardes TODO\r\n    function ScoutsMove()\r\n    invoke(100,1,\"Mobile.moveMobile\",scoutG, -2, -16, 0 )\r\n    invoke(100,1,\"Mobile.moveMobile\",scoutH, 2, -16, 0 )\r\n    invoke(100,1,\"Mobile.moveMobile\",scoutI, 0, -16, 0 )\r\n    invoke(100,1,\"Mobile.moveMobile\",scoutD, -2, -17, 0 )\r\n    invoke(100,1,\"Mobile.moveMobile\",scoutE, 2, -17, 0 )\r\n    invoke(100,1,\"Mobile.moveMobile\",scoutF, 0, -17, 0 )\r