utDies\", scoutI)\r\n    \tinvoke(700,1,\"scoutDies\", scoutC)\r\n    \tinvoke(900,1,\"scoutDies\", scoutF)\r\n    \tinvoke(1000,1,\"scoutDies\", scoutG)\r\n    \tinvoke(1200,1,\"scoutDies\", scoutB)\r\n    \tinvoke(1500,1,\"scoutDies\", scoutE)\r\n    \tinvoke(1700,1,\"scoutDies\", scoutA)\r\n    \r\n    end\r\n    --Pandora flippe TODO\r\n    --Sramy entre en scène TODO dure ms\r\n    function AlliesReact()\r\n    \tinvoke(100,1,\"Camera.attachCameraToMobile\",pandora)\r\n    \tinvoke(100,1,\"MindBubbleStart\",pandora, \"quest.DDCH2.bank.pandora01\",4000)\r\n    \tinvoke(4100,1,\"MindBubbleStart\",sramy, \"quest.DDCH2.bank.chad01\",4000)\r\n    \tinvoke(8100,1,\"Mobile.setMobileAnimation\",sramy, \"AnimSort-01-Debut\")\r\n    \r\n    \tinvoke(8100,1,\"Camera.attachCameraToMobile\",sramy)\r\n    \tinvoke(8780,1,\"SramyKillsAll\", 1, -15, 0, scoutI, scoutH)\r\n    \tinvoke(11610,1,\"SramyKillsAll\", -1, -16, 0, scoutD, scoutF)\r\n    \tinvoke(14440,1,\"SramyKillsAll\", 1, -17, 0, scoutB, scoutC)\r\n    \tinvoke(17270,1,\"SramyKillsAll\", -1, -15, 0, scoutG, scoutI)\r\n    \tinvoke(20100,1,\"SramyKillsAll\", 1, -16, 0, scoutF, scoutE)\r\n    \tinvoke(22930,1,\"SramyKillsAll\", -1, -17, 0, scoutA, scoutB) --25760 ms\r\n    \tinvoke(24930,1,\"AllScoutsDie\")\r\n    \tinvoke(25760,1,\"MindBubbleStart\",sramy, \"quest.DDCH2.bank.chad02\",5000)\r\n    \tinvoke(30760,1,\"MindBubbleStart\",sramy, \"quest.DDCH2.bank.chad03\",5000)\r\n    \tinvoke(35760,1,\"Camera.setWorldTarget\", 0,-25, 0)\r\n    end\r\n    \r\n    --fin cinematique avant TP couloir 01\r\n    function EndBankCine()\r\n    \tActor.deleteActor(eminence)\r\n    \tActor.deleteActor(pandora)\r\n    \tActor.deleteActor(sramy)\r\n    \tActor.deleteActor(BodyguardA)\r\n    \tActor.deleteActor(BodyguardB)\r\n    \tActor.deleteActor(scoutA)\r\n    \tActor.deleteActor(scoutB)\r\n    \tActor.deleteActor(scoutC)\r\n    \tActor.deleteActor(scoutD)\r\n    \tActor.deleteActor(scoutE)\r\n    \tActor.deleteActor(scoutF)\r\n 