 \"0\"..timerMinutes\r\n    \telse\r\n    \t\ttimerMinutesText = toString(timerMinutes)\r\n    \tend\r\n    \tif timerSeconds < 10 then\r\n    \t\ttimerSecondsText= \"0\"..timerSeconds\r\n    \telse\r\n    \t\ttimerSecondsText = toString(timerSeconds)\r\n    \tend\r\n    \r\n    \ttimerText =  timerMinutesText .. \" : \".. timerSecondsText\t\r\n    \r\n    end\nend\n\n-- [EVENT] Echec de la fuite (temps écoulé)\n-- \nfunction event_1700_13934()\n    local playerId = Context.getLeaderId()\r\n    \r\n    startCinematic()\r\n    invoke(100,1,\"MindBubbleStart\",playerId, \"quest.DDCH2.bankfail\",3000)\r\n    UI.stopCountdown()\r\nend\n\n-- [EVENT] Echec de la fuite (reset event)\n-- \nfunction event_1700_13935()\n    endCinematic()\nend\n\n-- [EVENT] ETAGE 1 - Activation de la porte du Coffre-Fort - Lancement du combat\n-- \nfunction event_1700_14015()\n    \nend\n\n-- [EVENT] ETAGE 1 - Début du combat - Invocation de Chad et Pandora\n-- \nfunction event_1700_14049()\n    \nend\n\n-- [EVENT] ETAGE 1 - Activation Barricade 1 - good\n-- \nfunction event_1700_14050()\n    local playerId = Context.getLeaderId()\r\n    local dialChoice = random(1, 5)\r\n    \r\n    MindBubbleStart (playerId, \"quest.DDCH2.bankbarricadeactive0\" .. toString(dialChoice), 4000)\nend\n\n-- [EVENT] ETAGE 1 - Activation Barricade 2 - good\n-- \nfunction event_1700_14125()\n    local playerId = Context.getLeaderId()\r\n    local dialChoice = random(1, 5)\r\n    \r\n    MindBubbleStart (playerId, \"quest.DDCH2.bankbarricadeactive0\" .. toString(dialChoice), 4000)\nend\n\n-- [EVENT] ETAGE 1 - Activation Barricade 3 - good\n-- \nfunction event_1700_14126()\n    local playerId = Context.getLeaderId()\r\n    local dialChoice = random(1, 5)\r\n    \r\n    MindBubbleStart (playerId, \"quest.DDCH2.bankbarricadeactive0\" .. toString(dialChoice), 4000)\nend\n\n-- [EVENT] Combat perdu - Cinématique Défaite joueurs hors combat + Flag joueurs en combat\n-- \nfunction event_1700_14052()\n    displayFail()\nend\n\n-- [EVENT] Combat perdu - Cinématique Défaite joueurs Flag\n-- \nfunction event_1700_19829()\n    displayFail()\nend\n\n-- [EVENT] Combat perdu - TP des joueurs après Cinématique Défaite\n-- \nfunction event_1700_14054()\n    \nend\n\n-- [EVENT] ETAGE 1 - Fin du Combat - Succès (mob killed) - Fuite\n-- \nfunction event_1700_14127(PandoraId, questProgress, playerOne, playerTwo, playerThree, playerFour, playerFive, playerSix)\n    local PlayerId = Context.getLeaderId()\r\n    local playerOneId = toLong(playerOne)\r\n    local playerTwoId = toLong(playerTwo)\r\n    local playerThreeId = toLong(playerThree)\r\n    local playerFourId = toLong(playerFour)\r\n    local playerFiveId = toLong(playerFive)\r\n    local playerSixId = toLong(playerSix)\r\n    \r\n    -- Démarrage\r\n    startCinematic()\r\n    \r\n    local PandoraIdval = Mobile.generateClientMobileId() \r\n    Actor.createActor(PandoraIdval, 163503082, 104, 97, 0, 4)\r\n    Mobile.setMobileDirection(PandoraIdval,7)\r\n    \r\n    local ChadIdval = Mobile.generateClientMobileId() \r\n    Actor.createActor(ChadIdval, 163503107, 103, 95,  0, 4)\r\n    Mobile.setMobileDirection(ChadIdval,7)\r\n    Mobile.setMobileAnimation(ChadIdval,\"AnimKO-Boucle\")\r\n    \r\n    invoke(500,1,\"Mobile.moveMobile\",PandoraIdval, 104,95,0)\r\n    --invoke(500,1,\"Mobile.moveMobile\",PlayerId, 103, 96, 0)\r\n    invoke(500,1,\"Mobile.moveMobile\",playerOneId,  103, 96, 0)\r\n    invoke(500,1,\"Mobile.moveMobile\",playerTwoId,  102, 96, 0)\r\n    invoke(500,1,\"Mobile.moveMobile\",playerThreeId,  104, 96, 0)\r\n    invoke(500,1,\"Mobile.moveMobile\",playerFourId,  103, 98, 0)\r\n    invoke(500,1,\"Mobile.moveMobile\",playerFiveId, 102, 98, 0)\r\n    invoke(500,1,\"Mobile.moveMobile\",playerSix, 104, 98, 0)\r\n    \r\n    invoke(500,1,\"Mobile.setMobileAnimation\",ChadIdval,\"AnimKO-SortieOK\")\r\n    \r\n    invoke(2000,1,\"Mobile.setMobileDirection\",PandoraIdval,5)\r\n    invoke(4000,1,\"Mobile.setMobileDirection\",PlayerId,7)\r\n    \r\n    invoke(2000,1,\"Camera.attachCameraToMobile\",PandoraIdval)\r\n    invoke(2000,1,\"MindBubbleStart\",ChadIdval, \"quest.DDCH2.bank.chad.open01\",4000)\r\n    invoke(6000,1,\"MindBubbleStart\",ChadIdval, \"quest.DDCH2.bank.chad.open02\",5000)\r\n    invoke(11000,1,\"MindBubbleStart\",PandoraIdval, \"quest.DDCH2.bank.pandora.open01\",6000)\r\n    \r\n    invoke(17000,1,\"endCinematic\")\nend\n\n-- [EVENT] ETAGE 1 - Fin du Combat - Succès (10 rounds) - Fuite\n-- \nfunction event_1700_14080(PandoraId, questProgress, playerOne, playerTwo, playerThree, playerFour, playerFive, playerSix)\n    local PlayerId = Context.getLeaderId()\r\n    local playerOneId = toLong(playerOne)\r\n    local playerTwoId = toLong(playerTwo)\r\n    local playerThreeId = toLong(playerThree)\r\n    local playerFourId = toLong(playerFour)\r\n    local playerFiveId = toLong(playerFive)\r\n    local playerSixId = toLong(playerSix)\r\n    \r\n    -- Démarrage\r\n    startCinematic()\r\n    \r\n    local PandoraIdval = Mobile.generateClientMobileId() \r\n    Actor.createActor(PandoraIdval, 163503082, 104, 97, 0, 4)\r\n    Mobile.setMobileDirection(PandoraIdval,7)\r\n    \r\n    local ChadIdval = Mobile.generateClientMobileId() \r\n    Actor.createActor(ChadIdval, 163503107, 103, 95,  0, 4)\r\n    Mobile.setMobileDirection(ChadIdval,7)\r\n    Mobile.setMobileAnimation(ChadIdval,\"AnimKO-Boucle\")\r\n    \r\n    invoke(500,1,\"Mobile.moveMobile\",PandoraIdval, 104,95,0)\r\n    --invoke(500,1,\"Mobile.moveMobile\",PlayerId, 103, 96, 0)\r\n    invoke(500,1,\"Mobile.moveMobile\",playerOneId,  103, 96, 0)\r\n    invoke(500,1,\"Mobile.moveMobile\",playerTwoId,  102, 96, 0)\r\n    invoke(500,1,\"Mobile.moveMobile\",playerThreeId,  104, 96, 0)\r\n    invoke(500,1,\"Mobile.moveMobile\",playerFourId,  103, 98, 0)\r\n    invoke(500,1,\"Mobile.moveMobile\",playerFiveId, 102, 98, 0)\r\n    invoke(500,1,\"Mobile.moveMobile\",playerSix, 104, 98, 0)\r\n    \r\n    invoke(500,1,\"Mobile.setMobileAnimation\",ChadIdval,\"AnimKO-SortieOK\")\r\n    \r\n    invoke(2000,1,\"Mobile.setMobileDirection\",PandoraIdval,5)\r\n    invoke(4000,1,\"Mobile.setMobileDirection\",PlayerId,7)\r\n    \r\n    invoke(1500,1,\"UI.manageFrame\",\"World\",false)\r\n    invoke(2000,1,\"Camera.attachCameraToMobile\",PandoraIdval)\r\n    invoke(2000,1,\"MindBubbleStart\",ChadIdval, \"quest.DDCH2.bank.chad.open01\",4000)\r\n    invoke(6000,1,\"MindBubbleStart\",ChadIdval, \"quest.DDCH2.bank.chad.open02\",5000)\r\n    invoke(11000,1,\"MindBubbleStart\",PandoraIdval, \"quest.DDCH2.bank.pandora.open01\",6000)\r\n    invoke(2100,1,\"UI.manageFrame\",\"World\",false)\r\n    invoke(4100,1,\"UI.manageFrame\",\"World\",false)\r\n    invoke(6100,1,\"UI.manageFrame\",\"World\",false)\r\n    invoke(8100,1,\"UI.manageFrame\",\"World\",false)\r\n    \r\n    invoke(17000,1,\"endCinematic\")\nend\n\n-- [EVENT] ETAGE 1 - Fin du Combat - Succès - Fuite (changement d'étage)\n-- \nfunction event_1700_14081()\n    \nend\n\n","functions":["MindBubbleStart","startCinematic","endCinematic","displayFail","event_1700_13930","event_1700_13931","event_1700_14175","event_1700_13962","event_1700_13936","event_1700_13932","apparition","bodyapparition","scoutapparition","ScoutsMove","SramyKillsAll","scoutDies","AllScoutsDie","AlliesReact","EndBankCine","event_1700_14012","event_1700_13933","event_1700_13934","event_1700_13935","event_1700_14015","event_1700_14049","event_1700_14050","event_1700_14125","event_1700_14126","event_1700_14052","event_1700_19829","event_1700_14054","event_1700_14127","event_1700_14080","event_1700_14081"],"quest_calls":["UI.activateFollowAchievement(false)\r","UI.activateFollowAchievement(true)\r"],"dialogue_calls":[]},"scenario/1701.lua":{"source":"\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_1701_13837()\n    \nend\n\n-- [EVENT] QP7 Attaque de la milice - Lancement du combat\n-- \nfunction event_1701_13836()\n    \nend\n\n-- [EVENT] QP7 Attaque de la milice - Placement des alliés\n-- \nfunction event_1701_13835()\n    \nend\n\n-- [EVENT] QP7 Attaque de la milice - Groupe tué\n-- \nfunction event_1701_13834()\n    \nend\n\n-- [EVENT] QP7 Attaque de la milice - Défaite : TP des joueurs\n-- \nfunction event_1701_19489()\n    \nend\n\n-- [EVENT] QP7 Combat contre Milice - Tick du premier tour : Validation quête\n-- \nfunction event_1701_14091()\n    \nend\n\n","functions":["event_1701_13837","event_1701_13836","event_1701_13835","event_1701_13834","event_1701_19489","event_1701_14091"],"quest_calls":[],"dialogue_calls":[]},"scenario/1702.lua":{"source":"\n\n-- [INITIALISATION] Variables\n-- \nfunction event_1702_13843(mobOne, mobTwo, mobThree, mobFour, mobFive)\n    mobOne = toLong(mobOne)\r\n    mobTwo = toLong(mobTwo)\r\n    mobThree = toLong(mobThree)\r\n    mobFour = toLong(mobFour)\r\n    mobFive = toLong(mobFive)\r\n    \r\n    Mobile.setMobileDirection(mobOne, 3)\r\n    Mobile.setMobileDirection(mobTwo, 7)\r\n    Mobile.setMobileDirection(mobThree, 3)\r\n    Mobile.setMobileDirection(mobFour, 3)\r\n    Mobile.setMobileDirection(mobFive, 1)\r\nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_1702_13844()\n    Camera.setZoomFactor(0.9)\nend\n\n-- [SPECIAL] Debut d'un combat - Application des sorts et des caractéristiques\n-- \nfunction event_1702_13845()\n    \nend\n\n-- [EVENT] Trigger - Affichage Bubble\n-- \nfunction event_1702_13853(Player)\n    playerId = Context.getPlayer()\r\n    --BubbleText.showText(playerId, \"quest.saharach.infiltration\", 0, 40, false)\r\n    --UI.manageFrame(\"World\",false)\r\nend\n\n-- [TICK] Lancement combat\n-- \nfunction event_1702_13854()\n    \t--UI.manageFrame(\"World\",true)\r\n    \t\nend\n\n-- [EVENT] Placement Glyphes\n-- \nfunction event_1702_13855()\n    --UI.openRewardsDialog(\"defi.cimetiere.cacterre\")\r\n    --UI.addReward(4266)\r\nend\n\n-- [EVENT] Victoire\n-- \nfunction event_1702_13856()\n    \nend\n\n-- [TICK] Ouverture de la porte\n-- \nfunction event_1702_13857()\n    \nend\n\n-- [EVENT] Défaite\n-- \nfunction event_1702_13858(mobOne, mobTwo, mobThree, mobFour, mobFive)\n    \nend\n\n-- [TICK] Défaite - TP au début (avant le Trigger)\n-- \nfunction event_1702_13859()\n    \nend\n\n-- [EXPLOIT] Compteur de monstres tués\n-- \nfunction event_1702_13863(monsterKilled)\n    \nend\n\n-- [EXPLOIT] Compteur de tour\n-- \nfunction event_1702_13864(turnCount)\n    \nend\n\n-- [EXPLOIT] Victoire avec tous les monstres tués\n-- \nfunction event_1702_13865(monsterKilled)\n    \nend\n\n-- [EXPLOIT] Victoire avec aucun monstre tué\n-- \nfunction event_1702_13866(monsterKilled)\n    \nend\n\n-- [EXPLOIT] Victoire en moins de X tours\n-- \nfunction event_1702_13867(turnCount)\n    \nend\n\n-- [EVENT] Joueur quitte l'instance\n-- \nfunction event_1702_13868()\n    Camera.setZoomFactor(1)\nend\n\n-- [COMBAT] Victoire - Récompense de quête\n-- \nfunction event_1702_13905()\n    \nend\n\n","functions":["event_1702_13843","event_1702_13844","event_1702_13845","event_1702_13853","event_1702_13854","event_1702_13855","event_1702_13856","event_1702_13857","event_1702_13858","event_1702_13859","event_1702_13863","event_1702_13864","event_1702_13865","event_1702_13866","event_1702_13867","event_1702_13868","event_1702_13905"],"quest_calls":["UI.openRewardsDialog(\"defi.cimetiere.cacterre\")\r"],"dialogue_calls":[]},"scenario/1703.lua":{"source":"playerId = Context.getPlayer()\r\n\r\n\r\nfunction Bubble(mob,text)\r\n\tBubbleText.closeBubbleAttachedTo(mob)\r\n\tBubbleText.showText(mob, text, 0, 40, false)\r\nend\r\n\r\nfunction startCine()\r\n\tzoomFactor = Camera.getZoomFactor()\r\n\tUI.manageFrame(\"World\",false) \t\t\t\t\t\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\t\t\t\t\t\t\t\t\t\t\t\t\r\n\tUI.manageFrame(\"World\",false) \t\t\t\t\t\r\n\tUI.setUIVisible(false)\t\r\n\tUI.displayWideScreenBand(true)\r\nend\r\n\r\nfunction endCine()\r\n\tCamera.attachCameraToMobile(playerId)\r\n\tUI.displayWideScreenBand(false)\r\n\tCamera.setUserZoomLocked(false)\t\t\t\t\t\t\t\t\t\t\t\t\r\n\tUI.setUIVisible(true)\t\r\n\tUI.manageFrame(\"World\",true) \t\t\t\t\r\n\tCamera.setZoomFactor(zoomFactor)\t\r\nend\n\n-- [INIT] Variables\n-- \nfunction event_1703_13877()\n    \nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_1703_13878(conviveOne, conviveTwo, conviveThree, conviveFour, conviveFive)\n    UI.loadTutorialDialog(\"tutoddambassade01\",\"tutorial.ddch1.ambassade.title.01\",\"tutorial.ddch1.ambassade.description.01\")\r\n    \r\n    local conviveOneVar = toLong(conviveOne)\r\n    local conviveTwoVar = toLong(conviveTwo)\r\n    local conviveThreeVar = toLong(conviveThree)\r\n    local conviveFourVar = toLong(conviveFour)\r\n    local conviveFiveVar = toLong(conviveFive)\r\n    \r\n    Mobile.setMobileDirection(conviveOneVar,7)\r\n    Mobile.setMobileDirection(conviveTwoVar,1)\r\n    Mobile.setMobileDirection(conviveThreeVar,3)\r\n    Mobile.setMobileDirection(conviveFourVar,7)\r\n    Mobile.setMobileDirection(conviveFiveVar,3)\nend\n\n-- [Vol-Clef][INIT] Transformation du joueur en voleur\n-- \nfunction event_1703_13881()\n    \nend\n\n-- [Vol-Clef][COMBAT] Démarrage Combat\n-- \nfunction event_1703_13879()\n    \nend\n\n-- [Vol-Clef][COMBAT] Lancement du combat\n-- \nfunction event_1703_13880()\n    \nend\n\n-- [Vol-Clef][COMBAT] Victoire - Joueur récupère la clé\n-- \nfunction event_1703_13891()\n    local player = Context.getLeaderId()\r\n    invoke(1500, 1, \"Bubble\", player, \"quest.DDCH1.manoir.dial.clef.OK\")\nend\n\n-- [Reception][DIAL] Convives 1\n-- \nfunction event_1703_13882(conviveOne, conviveTwo, conviveThree)\n    local convOne = toLong(conviveOne)\r\n    local convTwo = toLong(conviveTwo)\r\n    local convThree = toLong(conviveThree)\r\n    \r\n    function closeBubblesOne()\r\n    \tBubbleText.closeBubbleAttachedTo(convOne)\r\n    \tBubbleText.closeBubbleAttachedTo(convTwo)\r\n    \tBubbleText.closeBubbleAttachedTo(convThree)\r\n    end\r\n    \r\n    function dialOne()\r\n    \tBubble(convOne,\"quest.DDCH1.manoir.dial1.0\")\r\n    \tinvoke(1500,1,\"BubbleText.closeBubbleAttachedTo\",convOne)\r\n    \tinvoke(1500,1,\"Bubble\",convTwo,\"quest.DDCH1.manoir.dial1.1\")\r\n    \tinvoke(3000,1,\"BubbleText.closeBubbleAttachedTo\",convTwo)\r\n    \tinvoke(3000,1,\"Bubble\",convThree,\"quest.DDCH1.manoir.dial1.2\")\r\n    end\r\n    \r\n    function dialTwo()\r\n    \tBubble(convOne,\"quest.DDCH1.manoir.dial1.3\")\r\n    \tinvoke(2500,1,\"BubbleText.closeBubbleAttachedTo\",convOne)\r\n    \tinvoke(2500,1,\"Bubble\",convTwo,\"quest.DDCH1.manoir.dial1.4\")\r\n    \tinvoke(5000,1,\"BubbleText.closeBubbleAttachedTo\",convTwo)\r\n    \tinvoke(5000,1,\"Bubble\",convOne,\"quest.DDCH1.manoir.dial1.5\")\r\n    end\r\n    \r\n    function dialThree()\r\n    \tBubble(convThree,\"quest.DDCH1.manoir.dial1.6\")\r\n    \tinvoke(2500,1,\"BubbleText.closeBubbleAttachedTo\",convThree)\r\n    \tinvoke(2500,1,\"Bubble\",convTwo,\"quest.DDCH1.manoir.dial1.7\")\r\n    end\r\n    \r\n    \r\n    local rand = math.random(1,3)\r\n    closeBubblesOne()\r\n    \r\n    if rand == 1 then\r\n    \tdialOne()\r\n    elseif rand == 2 then\r\n    \tdialTwo()\r\n    elseif rand == 3 then\r\n    \tdialThree()\r\n    end\r\nend\n\n-- [Reception][DIAL] Convives 1 - Bon Dial\n-- \nfunction event_1703_13883(conviveOne, conviveTwo, conviveThree)\n    local convOne = toLong(conviveOne)\r\n    local convTwo = toLong(conviveTwo)\r\n    local convThree = toLong(conviveThree)\r\n    local player = Context.getLeaderId()\r\n    \r\n    function dialOK()\r\n    \tBubble(convOne,\"quest.DDCH1.manoir.dialOK.0\")\r\n    \tinvoke(2500,1,\"BubbleText.closeBubbleAttachedTo\",convOne)\r\n    \tinvoke(2500,1,\"Bubble\",convTwo,\"quest.DDCH1.manoir.dialOK.1\")\r\n    \tinvoke(5000,1,\"BubbleText.closeBubbleAttachedTo\",convTwo)\r\n    \tinvoke(5000,1,\"Bubble\",player,\"quest.DDCH1.manoir.dialOK.2\")\r\n    end\r\n    \r\n    dialOK()\nend\n\n-- [Reception][DIAL] Garde 1\n-- \nfunction event_1703_13884(gardeOne)\n    local garde = toLong(gardeOne)\r\n    local rand = math.random(1,5)\r\n    \r\n    if rand == 1 then\r\n    \tBubble(garde,\"quest.DDCH1.manoir.dial.garde.0\")\r\n    elseif rand == 2 then\r\n    \tBubble(garde,\"quest.DDCH1.manoir.dial.garde.1\")\r\n    elseif rand == 3 then\r\n    \tBubble(garde,\"quest.DDCH1.manoir.dial.garde.2\")\r\n    elseif rand == 4 then\r\n    \tBubble(garde,\"quest.DDCH1.manoir.dial.garde.3\")\r\n    elseif rand == 5 then\r\n    \tBubble(garde,\"quest.DDCH1.manoir.dial.garde.4\")\r\n    end\nend\n\n-- [Reception][DIAL] Garde 2\n-- \nfunction event_1703_13907(gardeTwo)\n    local garde = toLong(gardeTwo)\r\n    local rand = math.random(1,5)\r\n    \r\n    if rand == 1 then\r\n    \tBubble(garde,\"quest.DDCH1.manoir.dial.garde.0\")\r\n    elseif rand == 2 then\r\n    \tBubble(garde,\"quest.DDCH1.manoir.dial.garde.1\")\r\n    elseif rand == 3 then\r\n    \tBubble(garde,\"quest.DDCH1.manoir.dial.garde.2\")\r\n    elseif rand == 4 then\r\n    \tBubble(garde,\"quest.DDCH1.manoir.dial.garde.3\")\r\n    elseif rand == 5 then\r\n    \tBubble(garde,\"quest.DDCH1.manoir.dial.garde.4\")\r\n    end\nend\n\n-- [Reception][DIAL] Garde 1 - Bon Dial\n-- \nfunction event_1703_13885(gardeOne)\n    local garde = toLong(gardeOne) \r\n    local player = Context.getLeaderId()\r\n    \r\n    Bubble(garde,\"quest.DDCH1.manoir.dial.garde.OK.0\")\r\n    invoke(1500,1,\"BubbleText.closeBubbleAttachedTo\",garde)\r\n    invoke(1500,1,\"Bubble\",player,\"quest.DDCH1.manoir.dial.garde.OK.1\")\nend\n\n-- [Reception][DIAL] Garde 2 - Bon Dial\n-- \nfunction event_1703_13908(gardeTwo)\n    local garde = toLong(gardeTwo) \r\n    local player = Context.getPlayer()\r\n    \r\n    Bubble(garde,\"quest.DDCH1.manoir.dial.garde.OK.0\")\r\n    invoke(1500,1,\"BubbleText.closeBubbleAttachedTo\",garde)\r\n    invoke(1500,1,\"Bubble\",player,\"quest.DDCH1.manoir.dial.garde.OK.1\")\nend\n\n-- [Reception][DIAL] Convives 2\n-- \nfunction event_1703_13886(conviveFour, conviveFive)\n    local convFour = toLong(conviveFour)\r\n    local convFive = toLong(conviveFive)\r\n    \r\n    function closeBubblesTwo()\r\n    \tBubbleText.closeBubbleAttachedTo(convFour)\r\n    \tBubbleText.closeBubbleAttachedTo(convFive)\r\n    end\r\n    \r\n    function dialOne()\r\n    \tBubble(convFour,\"quest.DDCH1.manoir.dial2.0\")\r\n    \tinvoke(2500,1,\"Bubble\",convFive,\"quest.DDCH1.manoir.dial2.1\")\r\n    end\r\n    \r\n    function dialTwo()\r\n    \tBubble(convFour,\"quest.DDCH1.manoir.dial2.0\")\r\n    \tinvoke(2500,1,\"Bubble\",convFive,\"quest.DDCH1.manoir.dial2.1\")\r\n    end\r\n    \r\n    function dialThree()\r\n    \tBubble(convFour,\"quest.DDCH1.manoir.dial2.0\")\r\n    \tinvoke(2500,1,\"Bubble\",convFive,\"quest.DDCH1.manoir.dial2.1\")\r\n    end\r\n    \r\n    function dialFour()\r\n    \tBubble(convFour,\"quest.DDCH1.manoir.dial2.0\")\r\n    \tinvoke(2500,1,\"Bubble\",convFive,\"quest.DDCH1.manoir.dial2.1\")\r\n    end\r\n    \r\n    function dialFive()\r\n    \tBubble(convFour,\"quest.DDCH1.manoir.dial2.0\")\r\n    \tinvoke(2500,1,\"Bubble\",convFive,\"quest.DDCH1.manoir.dial2.1\")\r\n    end\r\n    \r\n    local rand = math.random(1,5)\r\n    closeBubblesTwo()\r\n    \r\n    if rand == 1 then\r\n    \tdialOne()\r\n    elseif rand == 2 then\r\n    \tdialTwo()\r\n    elseif rand == 3 then\r\n    \tdialThree()\r\n    elseif rand == 4 then\r\n    \tdialFour()\r\n    elseif rand == 5 then\r\n    \tdialFive()\r\n    end\r\nend\n\n-- [Reception][ACTION] Manger Hors d'Oeuvres\n-- \nfunction event_1703_13887()\n    \nend\n\n-- [Reception][ACTION] Manger Hors d'Oeuvres - Apparition Serveur\n-- \nfunction event_1703_13888()\n    local serveur = Mobile.generateClientMobileId()\r\n    Actor.createActor(serveur, 104701127, 140, -8, 0,4)\r\n    \r\n    Mobile.moveMobile(serveur, 140, -6, 0)\r\n    invoke(3500,1,\"Mobile.moveMobile\",serveur, 140, -8, 0,\"Actor.deleteActor\",serveur)\nend\n\n-- [Reception][ACTION] Refill Hors d'oeuvre\n-- \nfunction event_1703_13889()\n    \nend\n\n-- [Reserve][ACTION] Manger Hors d'Oeuvres\n-- \nfunction event_1703_13892()\n    \nend\n\n-- [Reception][ACTION] On finit les derniers hors-d'oeuvre et on passe à la bière\n-- \nfunction event_1703_13893()\n    \nend\n\n-- [Reception][ACTION] Fin Hors d'oeuvres - Apparition Serveur\n-- \nfunction event_1703_13910(ambassadeur)\n    function noMoreFood()\r\n    \tBubble(serveur,\"quest.DDCH1.manoir.noMoreFood.01\")\r\n    \tinvoke(1500,1,\"Bubble\", amba, \"quest.DDCH1.manoir.noMoreFood.02\")\r\n    \tinvoke(3000,1,\"depart\")\r\n    end\r\n    \r\n    function depart()\r\n    \tMobile.setMobileDirection(serveur,7)\r\n    \tBubbleText.closeBubbleAttachedTo(serveur)\r\n    \tinvoke(500,1,\"Mobile.setMobileVisible\",serveur, false)\r\n    \tinvoke(1000,1,\"boisson\")\r\n    end\r\n    \r\n    function boisson()\r\n    \tMobile.setMobileVisible(serveur, true)\r\n    \tMobile.moveMobile(serveur, 139, -6, 0)\r\n    \tinvoke(3500,1,\"Mobile.moveMobile\",serveur, 140, -8, 0,\"Actor.deleteActor\",serveur)\r\n    end\r\n    \r\n    local amba = toLong(ambassadeur)\r\n    local serveur = Mobile.generateClientMobileId()\r\n    Actor.createActor(serveur, 104701127, 140, -8, 0,4)\r\n    Mobile.setMobileDirection(serveur, 3)\r\n    noMoreFood()\nend\n\n-- [Reception][ACTION] Apparition Boisson\n-- \nfunction event_1703_13911()\n    \nend\n\n-- [Reception][ACTION] On empoisonne la bouteille\n-- \nfunction event_1703_13894()\n    \nend\n\n-- [Reception][ACTION] On parle à l'ambassadeur\n-- \nfunction event_1703_13909(ambassadeur)\n    local amba = toLong(ambassadeur)\r\n    local rand = math.random(1,3)\r\n    \r\n    if rand == 1 then\r\n    \tBubble(amba,\"quest.DDCH1.manoir.dial.ambassadeur.0\")\r\n    elseif rand == 2 then\r\n    \tBubble(amba,\"quest.DDCH1.manoir.dial.ambassadeur.1\")\r\n    elseif rand == 3 then\r\n    \tBubble(amba,\"quest.DDCH1.manoir.dial.ambassadeur.2\")\r\n    end\nend\n\n-- [Reception][ACTION] On fait boire l'ambassadeur\n-- \nfunction event_1703_13895(ambassadeur, conviveOne, conviveTwo, conviveThree, conviveFour, conviveFive, gardeOne, gardeTwo, Pandora, Sramy)\n    local amba = toLong(ambassadeur)\r\n    local convOne = toLong(conviveOne)\r\n    local convTwo = toLong(conviveTwo)\r\n    local convThree = toLong(conviveThree)\r\n    local convFour = toLong(conviveFour)\r\n    local convFive = toLong(conviveFive)\r\n    local gardeOne = toLong(gardeOne)\r\n    local gardeTwo = toLong(gardeTwo)\r\n    local pandId = toLong(Pandora)\r\n    local chad = toLong(Sramy)\r\n    local player = Context.getLeaderId()\r\n    \r\n    function mortAmbassadeur()\r\n    \tMobile.moveMobile(amba, 139, -4, 0, \"Mobile.setMobileAnimation\", amba, \"AnimEmote-Boire\")\r\n    \tinvoke(4000, 1, \"Mobile.setMobileAnimation\", amba, \"AnimEmote-Vomis\")\r\n    \tinvoke(6000, 1, \"Mobile.setMobileAnimation\", amba, \"AnimMort\")\r\n    \tinvoke(9000, 1, \"panic\")\r\n    end\r\n    \r\n    function panic()\r\n    \tParticle.addParticleSystemToTarget(800435, convOne) \r\n    \tMobile.setMobileDirection(convOne,7)\r\n    \tParticle.addParticleSystemToTarget(15401, convTwo) \r\n    \tinvoke(100,1,\"Mobile.setMobileDirection\",convTwo,7)\r\n    \tParticle.addParticleSystemToTarget(800435, convThree) \r\n    \tinvoke(200,1,\"Mobile.setMobileDirection\",convThree,7)\t\r\n    \tParticle.addParticleSystemToTarget(800435, convFour) \r\n    \tinvoke(300,1,\"Mobile.setMobileDirection\",convFour,7)\r\n    \tParticle.addParticleSystemToTarget(15401, convFive) \r\n    \tMobile.setMobileDirection(convFive,7)\r\n    \tParticle.addParticleSystemToTarget(15401, gardeOne) \r\n    \tMobile.setMobileDirection(gardeOne,1)\r\n    \tParticle.addParticleSystemToTarget(800435, gardeTwo) \r\n    \tinvoke(100,1,\"Mobile.setMobileDirection\",gardeTwo,1)\r\n    \t\r\n    \tinvoke(1000,1,\"panicConvDial\")\r\n    \tinvoke(3000,1,\"panicConvFlee\")\r\n    \tinvoke(2000,1,\"panicGardeTwo\")\t\t\r\n    \r\n    \tinvoke(8000, 1, \"endAmbassade\")\r\n    end\r\n 