\r\n    \tCamera.setWorldTarget(1, -3, 0)\r\n    \t\r\n    \tBubble(sramy,\"quest.DDCH1.finchapitre.eminence.0\")\r\n    \t\r\n    \tinvoke(4500,1, \"BubbleText.closeBubbleAttachedTo\",sramy)\r\n    \tinvoke(4500,1, \"BubbleText.showText\",emin, \"quest.DDCH1.finchapitre.eminence.1\", 0, 60, false)\r\n    \tinvoke(4500,1, \"Mobile.setMobileAnimation\", emin, \"AnimComp-Rire\")\r\n    \t\r\n    \tinvoke(9000,1, \"BubbleText.closeBubbleAttachedTo\",emin)\r\n    \tinvoke(9000,1, \"Bubble\",sramy,\"quest.DDCH1.finchapitre.eminence.2\")\t\r\n    end\r\n    \r\n    invoke(4000,1,\"dial\")\nend\n\n-- [FIN][CH1] \n-- \nfunction event_1708_13960()\n    endCine()\nend\n\n-- [INIT][CH2] ENTER_INSTANCE\n-- \nfunction event_1708_14089(eminence, sram)\n    emin = toLong(eminence)\r\n    sramy = toLong(sram)\r\n    \r\n    startCine()\r\n    Mobile.setMobileDirection(emin,1)\r\n    \r\n    function move()\r\n    \tMobile.moveMobile(sramy, 1, -1, 0, \"dial\")\r\n    end\r\n    \r\n    function dial()\r\n    \tCamera.setWorldTarget(-1, -4, 2)\r\n    \t\r\n    \tBubble(sramy,\"quest.DDCH2.finchapitre.eminence.0\")\r\n    \t\r\n    \tinvoke(4500,1, \"BubbleText.closeBubbleAttachedTo\",sramy)\r\n    \tinvoke(4500,1, \"BubbleText.showText\",emin, \"quest.DDCH2.finchapitre.eminence.1\", 0, 60, false)\r\n    \t\r\n    \tinvoke(9000,1, \"Mobile.setMobileAnimation\", emin, \"AnimComp-Rire\")\r\n    \tinvoke(9000,1, \"BubbleText.closeBubbleAttachedTo\",emin)\r\n    \tinvoke(9000,1, \"BubbleText.showText\",emin, \"quest.DDCH2.finchapitre.eminence.2\", 0, 60, false)\r\n    end\r\n    \r\n    invoke(4000,1,\"move\")\nend\n\n-- [FIN][CH2] \n-- \nfunction event_1708_14090()\n    endCine()\nend\n\n-- [INIT][CH3] ENTER_INSTANCE\n-- \nfunction event_1708_14920(eminence, sram)\n    emin = toLong(eminence)\r\n    sramy = toLong(sram)\r\n    \r\n    startCine()\r\n    Mobile.setMobileDirection(emin,3)\r\n    \r\n    function move()\r\n    \tMobile.moveMobile(sramy, 3, -2, 0, \"dial\")\r\n    end\r\n    \r\n    function dial()\r\n    \tCamera.setWorldTarget(3, -4, 2)\r\n    \t\r\n    \tBubble(emin,\"quest.DDCH3.entrevue.eminence.0\")\r\n    \t\r\n    \tinvoke(4500,1, \"BubbleText.closeBubbleAttachedTo\",emin)\r\n    \tinvoke(4500,1, \"BubbleText.showText\",emin, \"quest.DDCH3.entrevue.eminence.1\", 0, 60, false)\r\n    \t\r\n    \tinvoke(9000,1, \"Mobile.setMobileAnimation\", emin, \"AnimComp-Menacer\")\r\n    \tinvoke(9000,1, \"BubbleText.closeBubbleAttachedTo\",emin)\r\n    \tinvoke(9000,1, \"BubbleText.showText\",sramy, \"quest.DDCH3.entrevue.eminence.2\", 0, 60, false)\r\n    \t\r\n    \tinvoke(13500,1, \"BubbleText.closeBubbleAttachedTo\",sramy)\r\n    \tinvoke(13500,1, \"BubbleText.showText\",emin, \"quest.DDCH3.entrevue.eminence.3\", 0, 60, false)\r\n    end\r\n    \r\n    invoke(4000,1,\"move\")\nend\n\n-- [FIN][CH3] \n-- \nfunction event_1708_14921()\n    endCine()\nend\n\n","functions":["startCine","endCine","Bubble","event_1708_13955","event_1708_13959","dial","event_1708_13960","event_1708_14089","move","dial","event_1708_14090","event_1708_14920","move","dial","event_1708_14921"],"quest_calls":[],"dialogue_calls":[]},"scenario/1712.lua":{"source":"m_playerId = Context.getPlayer()\n\n-- Lancement Cinématique\n-- \nfunction event_1712_14088()\n    \nend\n\n","functions":["event_1712_14088"],"quest_calls":[],"dialogue_calls":[]},"scenario/1713.lua":{"source":"\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_1713_14093()\n    \nend\n\n-- Entrée en Combat\n-- \nfunction event_1713_14094()\n    \nend\n\n","functions":["event_1713_14093","event_1713_14094"],"quest_calls":[],"dialogue_calls":[]},"scenario/1714.lua":{"source":"\n\n-- [INIT] Un joueur entre dans l'instance\n-- \nfunction event_1714_14106()\n    \nend\n\n-- [EVENT] Le joueur entre dans l'instance - Est un Prisonnier\n-- \nfunction event_1714_14107()\n    UI.openInfoDialog(\"moderation.jail.arrival.title\", \"moderation.jail.arrival.desc\")\nend\n\n-- [EVENT] Activation Levier - Est un Prisonnier - Feedback Chat\n-- \nfunction event_1714_14109()\n    UI.writeLocalisedInChat(\"moderation.jail.exit.disable\")\nend\n\n-- [EVENT] Activation Levier - N'est pas Prisonnier - TP en dehors de la cellule\n-- \nfunction event_1714_14110()\n    \nend\n\n","functions":["event_1714_14106","event_1714_14107","event_1714_14109","event_1714_14110"],"quest_calls":[],"dialogue_calls":[]},"scenario/1719.lua":{"source":"\n\n-- Initialisation des variables\n-- \nfunction event_1719_14411()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_1719_14162()\n    \nend\n\n-- [COMBAT] Lancement du combat\n-- \nfunction event_1719_14163()\n    \nend\n\n-- [ARCADE] Création du combat\n-- \nfunction event_1719_14315(arcade)\n    \nend\n\n-- [ARCADE] Transformation du joueur en pizz'larviolo\n-- \nfunction event_1719_14316()\n    \nend\n\n-- [QP] Création du combat\n-- \nfunction event_1719_14317()\n    \nend\n\n-- [QP][TUTO] Entrée en combat\n-- \nfunction event_1719_14916()\n    systPart   = UI.addParticle(\"systemBarDialog\",\"stateBarWindow\",\"6001057.xps\",0,0, \"NORTH_EAST\")\r\n    apsSpell = UI.addParticle(\"worldAndFightBarDialog\", \"shortcutBarList#0.borderContainer\", \"800177.xps\", 0, 30, \"NORTH\", 100)\r\n    invoke(5000,1,\"UI.removeParticle\",apsSpell)\r\n    \r\n    UI.loadTutorialDialog(\"TutoPizzlarve\",\"quest.astrub.pizzlarve.help.title\",\"quest.astrub.pizzlarve.help.desc\")\nend\n\n-- [QP][TUTO] Fin de Tour\n-- \nfunction event_1719_14917()\n    UI.removeParticle(systPart)\nend\n\n-- [QP] Transformation du joueur en pizz'larviolo\n-- \nfunction event_1719_14318()\n    \nend\n\n-- [QP] Victoire\n-- \nfunction event_1719_14354()\n    \nend\n\n-- [EVENT] Score arcade validé pour quête mercenaire 2149\n-- \nfunction event_1719_14412(arcade)\n    \nend\n\n-- [EVENT] Fin du combat - On notifie pour l'achievement 2149\n-- \nfunction event_1719_20821()\n    \nend\n\n","functions":["event_1719_14411","event_1719_14162","event_1719_14163","event_1719_14315","event_1719_14316","event_1719_14317","event_1719_14916","event_1719_14917","event_1719_14318","event_1719_14354","event_1719_14412","event_1719_20821"],"quest_calls":[],"dialogue_calls":[]},"scenario/1722.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\n\n-- [INIT] ENTER_INSTANCE - Variables\n-- \nfunction event_1722_14198()\n    \nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_1722_14199()\n    Event.runOnInstanceLoaded(\"UI.loadGuideDialog\", 173)\nend\n\n-- Apparition des Traverses\n-- \nfunction event_1722_14313()\n    \nend\n\n-- [Salle1][EVENT] COMBAT Victoire\n-- \nfunction event_1722_14203()\n    invoke(4000, 1, \"Particle.addParticleSystem\", 800202, -4, -8, 0, 0)\nend\n\n-- [Salle1][COFFRE] Apparition du coffre\n-- \nfunction event_1722_14204()\n    \nend\n\n-- [Salle1][COFFRE] Obtention de la Clef\n-- \nfunction event_1722_14205()\n    local playerId = Context.getLeaderId()\r\n    Mobile.setMobileAnimation(playerId, \"AnimEmote-Victoire\")\nend\n\n-- [Salle1][Porte] Ouverture Porte\n-- \nfunction event_1722_14243()\n    \nend\n\n-- [Salle2][EVENT] COMBAT Victoire\n-- \nfunction event_1722_14244()\n    local playerId = Context.getLeaderId()\r\n    \r\n    invoke(4000,1,\"Particle.addParticleSystem\",800202, -5, -25, 0, 0)\r\n    invoke(4000,1,\"Camera.setWorldTarget\",-5,-25,0)\r\n    invoke(6000,1,\"Camera.attachCameraToMobile\", playerId)\nend\n\n-- [Salle2][Porte] Ouverture Porte\n-- \nfunction event_1722_14245()\n    \nend\n\n-- [Salle3][COFFRE ARTEFACT] Coffre et Activation Artefact\n-- \nfunction event_1722_14254(CoffreArtefact, playerOne, playerTwo, playerThree, playerFour, playerFive, playerSix)\n    local playerId = Context.getPlayer()\r\n    local playerOneId = toLong(playerOne)\r\n    local playerTwoId = toLong(playerTwo)\r\n    local playerThreeId = toLong(playerThree)\r\n    local playerFourId = toLong(playerFour)\r\n    local playerFiveId = toLong(playerFive)\r\n    local playerSixId = toLong(playerSix)\r\n    \r\n    startCinematicContext(1, playerId)\r\n    \r\n    invoke_custom(1000,1,\"Mobile.moveMobile\",playerOneId, -15, -25, 0 )\r\n    invoke_custom(1000,1,\"Mobile.moveMobile\",playerTwoId, -15, -25, 0 )\r\n    invoke_custom(1000,1,\"Mobile.moveMobile\",playerThreeId, -15, -25, 0 )\r\n    invoke_custom(1000,1,\"Mobile.moveMobile\",playerFourId, -15, -25, 0 )\r\n    invoke_custom(1000,1,\"Mobile.moveMobile\",playerFiveId, -15, -25, 0 )\r\n    invoke_custom(1000,1,\"Mobile.moveMobile\",playerSixId, -15, -25, 0 )\r\n    invoke_custom(1120,1,\"Particle.addParticleSystem\", -1233040001, -16, -26, 0, 0)\r\n    invoke_custom(1520,1,\"Particle.addParticleSystem\", -1233040001, -16, -26, 0, 0)\r\n    invoke_custom(1920,1,\"Particle.addParticleSystem\", -1233040001, -16, -26, 0, 0)\r\n    invoke_custom(2320,1,\"Particle.addParticleSystem\", -1233040001, -16, -26, 0, 0)\r\n    invoke_custom(4000,1,\"Camera.setWorldTarget\",-5,-25,0)\r\n    invoke_custom(4200,1,\"Particle.addParticleSystem\", -1233040002, -6, -25, 0, 0)\r\n    invoke_custom(4400,1,\"Particle.addParticleSystem\", -1233040002, -5, -25, 0, 0)\r\n    invoke_custom(4200,1,\"Particle.addParticleSystem\", -1233040002, -14, -21, 0, 0)\r\n    invoke_custom(4400,1,\"Particle.addParticleSystem\", -1233040002, -13, -21, 0, 0)\r\n    invoke_custom(6200,1,\"Particle.addParticleSystem\", -1233040002, -6, -25, 0, 0)\r\n    invoke_custom(6400,1,\"Particle.addParticleSystem\", -1233040002, -5, -25, 0, 0)\r\n    invoke_custom(6200,1,\"Particle.addParticleSystem\", -1233040002, -14, -21, 0, 0)\r\n    invoke_custom(6400,1,\"Particle.addParticleSystem\", -1233040002, -13, -21, 0, 0)\r\n    invoke_custom(8000,1,\"Camera.setWorldTarget\",-16,-25,0)\r\n    \r\n    invoke(9000, 1, \"skipCinematic\")\nend\n\n-- [Salle3][Cinématique] Placement des joueurs sur le puzzle et déclenchement des pieux\n-- \nfunction event_1722_14255()\n    \nend\n\n-- [Salle3][LEVIER] Déblocage porte puzzle\n-- \nfunction event_1722_14246()\n    \nend\n\n-- [Salle3][LEVIER] Déblocage deuxième levier\n-- \nfunction event_1722_14247()\n    \nend\n\n-- [Salle3][Piège] Activation Piège (joueur déjà dessus)\n-- \nfunction event_1722_14250()\n    \nend\n\n-- [Salle3][Piège] Activation Piège\n-- \nfunction event_1722_14251()\n    local playerId = Context.getPlayer()\r\n    \r\n    function animChute(playerId)\r\n    \tMobile.setMobileVisible(playerId, true)\r\n    \tMobile.setMobileDirection(playerId, 1)\r\n    \tMobile.setMobileAnimation(playerId, \"AnimIncarnam-Chute-Fin\", \"animEnd\")\r\n    end\r\n    \r\n    function animEnd(playerId)\r\n    \tMobile.setMobileDirection(playerId, 3)\r\n    \tUI.manageFrame(\"World\",true)\r\n    end\r\n    \r\n    Mobile.setMobileVisible(playerId, false)\r\n    UI.manageFrame(\"World\",false)\r\n    invoke(1600, 1, \"animChute\", playerId)\nend\n\n-- [Salle3][Piège] Timer Piège Ouverture\n-- \nfunction event_1722_14252()\n    \nend\n\n-- [Salle3][Piège] Timer Piège Fermeture\n-- \nfunction event_1722_14253()\n    \nend\n\n-- [Salle4][EVENT] COMBAT Victoire\n-- \nfunction event_1722_14256()\n    invoke(7000,1,\"Particle.addParticleSystem\",800202, 17, -25, 0, 0)\nend\n\n-- [Salle4][COFFRE] Apparition du coffre\n-- \nfunction event_1722_14257()\n    \nend\n\n-- [Salle4][COFFRE] Obtention de la Clef BOSS\n-- \nfunction event_1722_14233()\n    local playerId = Context.getLeaderId()\r\n    Mobile.setMobileAnimation(playerId, \"AnimEmote-Victoire\")\nend\n\n-- [Salle5][Porte] Ouverture Porte\n-- \nfunction event_1722_14262()\n    \nend\n\n-- [Salle5][BOSS] Entrée Cinématique Boss\n-- \nfunction event_1722_14265(SchreddercheId, triggerTwo, playerOne, playerTwo, playerThree, playerFour, playerFive, playerSix)\n    local playerId = Context.getPlayer()\r\n    local playerOneId = toLong(playerOne)\r\n    local playerTwoId = toLong(playerTwo)\r\n    local playerThreeId = toLong(playerThree)\r\n    local playerFourId = toLong(playerFour)\r\n    local playerFiveId = toLong(playerFive)\r\n    local playerSixId = toLong(playerSix)\r\n    \r\n    local schreddercheId = createActor(165303234, 0, -62, 12, 4, 3)\r\n    Mobile.setMobileVisible(schreddercheId, false)\r\n    \r\n    startCinematicContext(1)\r\n    Camera.setWorldTarget(0, -60, 12)\r\n    \r\n    invoke_custom(110,1,\"Mobile.setMobileVisible\", schreddercheId, true)\r\n    \r\n    invoke_custom(150,1,\"Mobile.moveMobile\",playerOneId, 0, -56, 12 )\r\n    invoke_custom(150,1,\"Mobile.moveMobile\",playerTwoId, -1, -56, 12 )\r\n    invoke_custom(150,1,\"Mobile.moveMobile\",playerThreeId, 1, -56, 12 )\r\n    invoke_custom(150,1,\"Mobile.moveMobile\",playerFourId, 2, -56, 12 )\r\n    invoke_custom(150,1,\"Mobile.moveMobile\",playerFiveId, 0, -55, 12 )\r\n    invoke_custom(150,1,\"Mobile.moveMobile\",playerSixId, 1, -55, 12 )\r\n    \r\n    invoke_custom(1000,1,\"bubble\",schreddercheId, \"quest.Astrub.Temple.schredderche.1\")\r\n    invoke_custom(6500,1,\"bubble\",schreddercheId, \"quest.Astrub.Temple.schredderche.2\")\r\n    \r\n    invoke_custom(11000,1,\"Mobile.setMobileDirection\", schreddercheId, 3)\r\n    invoke_custom(11100,1,\"Mobile.moveMobile\",schreddercheId, 0,-57,12)\r\n    invoke_custom(13100,1,\"bubble\",schreddercheId, \"quest.Astrub.Temple.schredderche.3\")\r\n    \r\n    invoke(18000,1,\"skipCinematic\")\nend\n\n-- Déclenchement Combat Salle 5\n-- \nfunction event_1722_14288()\n    \nend\n\n-- BOSS Vaincu\n-- \nfunction event_1722_14269()\n    \nend\n\n-- BOSS Vaincu - Cinématique Apparition TP\n-- \nfunction event_1722_14289()\n    startCinematicContext(1)\r\n    Camera.setWorldTarget(0, -69, 12)\r\n    \r\n    invoke_custom(3000, 1, \"Camera.setWorldTarget\", 5, -59, 12)\r\n    invoke(10000, 1, \"skipCinematic\")\nend\n\n-- [Salle5][Chevalier d'Astrub][INITIALISATION][COMPAGNON] Appel à l'aide\n-- \nfunction event_1722_14272()\n    local rdm = math.random(1, 5)\r\n    local ieId = InteractiveElement.getElementId(8007, 5, -59)\r\n    local text = \"quest.compagnon.astrubogrest.help0\" .. toString(rdm)\r\n    \r\n    BubbleText.closeBubbleAttachedTo(ieId)\r\n    local bubbleId = BubbleText.prepareWakfuBubble(ieId, 0, 0, false)\r\n    BubbleText.setText(bubbleId, text)\r\n    BubbleText.show(bubbleId)\nend\n\n-- [Salle5][Chevalier d'Astrub][QUETE] Validation libération du chevalier\n-- \nfunction event_1722_14273()\n    \nend\n\n-- [EVENT] Entrée en Combat\n-- \nfunction event_1722_14350()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_1722_14198","event_1722_14199","event_1722_14313","event_1722_14203","event_1722_14204","event_1722_14205","event_1722_14243","event_1722_14244","event_1722_14245","event_1722_14254","event_1722_14255","event_1722_14246","event_1722_14247","event_1722_14250","event_1722_14251","animChute","animEnd","event_1722_14252","event_1722_14253","event_1722_14256","event_1722_14257","event_1722_14233","event_1722_14262","event_1722_14265","event_1722_14288","event_1722_14269","event_1722_14289","event_1722_14272","event_1722_14273","event_1722_14350"],"quest_calls":[],"dialogue_calls":[]},"scenario/1723.lua":{"source":"playerId = Context.getPlayer()\r\ngrouilleux = Mobile.generateClientMobileId()\r\nplanteOne = Mobile.generateClientMobileId()\r\nplanteTwo = Mobile.generateClientMobileId()\r\nzoomFactor = 1\r\n\r\nfunction startCine()\r\n\tzoomFactor = Camera.getZoomFactor()\r\n\tUI.manageFrame(\"World\",false) \t\t\t\t\t\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\t\t\t\t\t\t\t\t\t\t\t\t\r\n\tUI.manageFrame(\"World\",false) \t\t\t\t\t\r\n\tUI.setUIVisible(false)\t\r\n\tUI.displayWideScreenBand(true)\r\n\tUI.setShortcutEnabled(false)\r\nend\r\n\r\nfunction endCine()\r\n\tCamera.attachCameraToMobile(playerId)\r\n\tUI.displayWideScreenBand(false)\r\n\tCamera.setUserZoomLocked(false)\t\t\t\t\t\t\t\t\t\t\t\t\r\n\tUI.setUIVisible(true)\t\r\n\tUI.manageFrame(\"World\",true) \t\t\t\t\r\n\tUI.setShortcutEnabled(true)\r\n\t\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\t\r\n\tend\r\nend\r\n\r\nfunction cinematique_part_one()\r\n\t--On prépare le client pour la cinématique\r\n\tstartCine()\r\n\r\n\t--Apparition du Grouilleux\r\n\tActor.createActor(grouilleux, 165303236, 4, -5, 0, 4)\r\n\t\r\n\t--On déplace le Grouilleux une première fois, puis une seconde et enfin on lance l'apparition des plantes\r\n\tMobile.moveMobile(grouilleux, 8, -5 ,0, \"Mobile.moveMobile\", grouilleux, 7, 0, 0, \"cinematique_part_two\")\r\nend\r\n\r\nfunction cinematique_part_two()\r\n\t--On fait lancer une animation au Grouilleux (avec des particules)\r\n\tMobile.setMobileAnimation(grouilleux, \"AnimSort-Cast\")\r\n\tinvoke(500, 1, \"Particle.addParticleSystem\", 1010330, 5, 3, 0) \r\n\tinvoke(500, 1, \"Particle.addParticleSystem\", 1010330, 7, -2, 0) \r\n\r\n\t--Apparition des plantes\r\n\tinvoke(1500, 1, \"Actor.createActor\", planteOne, 101601274, 5, 3, 0)\r\n\tinvoke(1500, 1, \"Actor.createActor\", planteTwo,  101601274, 7, -2, 0)\r\n\t\r\n\t--On déplace le Grouilleux (il prend la fuite)\r\n\tinvoke(2000, 1, \"Mobile.moveMobile\", grouilleux, -1, 0, 0)\r\n\t\r\n\t--On remet ce qui va bien dans le client pour un retour en mode jeu\r\n\tinvoke(3000, 1, \"endCine\")\r\nend\r\n\r\nfunction cleanActors()\r\n\tActor.deleteActor(grouilleux)\r\n\tActor.deleteActor(planteOne)\r\n\tActor.deleteActor(planteTwo)\r\nend\n\n-- Init\n-- \nfunction event_1723_14383()\n    \nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_1723_14277()\n    \nend\n\n-- [EVENT] Activation IE\n-- \nfunction event_1723_14294()\n    cinematique_part_one()\nend\n\n-- [EVENT] Entrée en Combat\n-- \nfunction event_1723_14384()\n    cleanActors()\nend\n\n","functions":["startCine","endCine","cinematique_part_one","cinematique_part_two","cleanActors","event_1723_14383","event_1723_14277","event_1723_14294","event_1723_14384"],"quest_calls":[],"dialogue_calls":[]},"scenario/1724.lua":{"source":"function MindBubbleStart(mob,text,tDuration)\r\n\tMindBubble = BubbleText.showText(mob, text, 0, 40, false)\r\n\tinvoke(tDuration, 1, \"BubbleText.close\", MindBubble)\r\nend\r\n\r\nfunction startCine()\r\n\tUI.manageFrame(\"World\", false) \t\t\t\t\t\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\t\t\t\t\t\t\t\t\t\t\t\t\r\n\tUI.manageFrame(\"World\", false) \t\t\t\t\t\r\n\tUI.setUIVisible(false)\r\n\tUI.activateFollowAchievement(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tUI.setShortcutEnabled(false)\r\nend\r\n\r\nfunction endCine(zoom, player)\t\t\t\t\r\n\tUI.setUIVisible(true)\t\r\n\tUI.activateFollowAchievement(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setShortcutEnabled(true)\r\n\tCamera.setUserZoomLocked(false)\t\r\n\tUI.manageFrame(\"World\",true) \t\r\n\t\r\n\tCamera.attachCameraToMobile(player)\r\n\tCamera.setZoomFactor(zoom)\t\r\nend\n\n-- [INITIALISATION] Variables\n-- \nfunction event_1724_14357()\n    \nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_1724_14295()\n    \nend\n\n-- [EVENT] Lancement Salle 1 - Phase de préparation terminée\n-- \nfunction event_1724_14297()\n    \nend\n\n-- [SALLE 01] Victoire - On déverouille la porte\n-- \nfunction event_1724_14299()\n    \nend\n\n-- [SALLE 01] Victoire - La porte est ouverte\n-- \nfunction event_1724_14300()\n    \nend\n\n-- [SALLE 02] Lancement Salle 2 - Phase de préparation terminée\n-- \nfunction event_1724_14298()\n    \nend\n\n-- [SALLE 02] Victoire - On déverouille la porte\n-- \nfunction event_1724_14301()\n    \nend\n\n-- [SALLE 02] Victoire - La porte est ouverte\n-- \nfunction event_1724_14302()\n    \nend\n\n-- [SALLE 03] Lancement du combat Boss\n-- \nfunction event_1724_14321()\n    \nend\n\n-- [SALLE 03] Phase de placement Boss\n-- \nfunction event_1724_14320()\n    \nend\n\n-- [SALLE 03] Fin de Combat\n-- \nfunction event_1724_23934()\n    \nend\n\n-- OLD [SALLE 03] Fin de Combat - Cinématique\n-- \nfunction event_1724_14374()\n    GrouilleIdval = Mobile.generateClientMobileId()\r\n    zoomFactor = Camera.getZoomFactor()\r\n    playerId = Context.getLeaderId()\r\n    \r\n    startCine()\r\n    \r\n    Actor.createActor(GrouilleIdval, 165303249, 19, -9, 0, 4)\r\n    Mobile.setMobileDirection(GrouilleIdval, 7)\r\n    Mobile.setMobileVisible(GrouilleIdval, false)\r\n    \r\n    Camera.setZoomFactor(1)\r\n    Camera.attachCameraToMobile(GrouilleIdval)\r\n    \t\r\n    Mobile.setMobileVisible(GrouilleIdval, true)\r\n    \t\t\r\n    invoke(100, 1, \"MindBubbleStart\", GrouilleIdval, \"quest.Astrub.Grouilleux.Crypte.1\", 4000)\r\n    invoke(200, 1, \"Mobile.setMobileAnimation\", playerId, \" AnimEmote-Defaite\")\r\n    invoke(4100, 1, \"MindBubbleStart\", GrouilleIdval, \"quest.Astrub.Grouilleux.Crypte.2\", 4000)\r\n    invoke(8200, 1, \"Actor.deleteActor\", GrouilleIdval)\r\n    invoke(8300, 1, \"endCine\", zoomFactor, playerId)\r\n    invoke(8500, 1, \"Server.triggerEvent\", 14374)\nend\n\n-- OLD [SALLE 03] Cinématique - TP Joueur Egouts 896\n-- \nfunction event_1724_14358()\n    \nend\n\n-- MONSTER_ACTION_EVENT - Lancement du combat\n-- \nfunction event_1724_23518()\n    \nend\n\n-- FIGHT_ENDED - On rend les monstres inattaquables\n-- \nfunction event_1724_23519()\n    \nend\n\n","functions":["MindBubbleStart","startCine","endCine","event_1724_14357","event_1724_14295","event_1724_14297","event_1724_14299","event_1724_14300","event_1724_14298","event_1724_14301","event_1724_14302","event_1724_14321","event_1724_14320","event_1724_23934","event_1724_14374","event_1724_14358","event_1724_23518","event_1724_23519"],"quest_calls":["UI.activateFollowAchievement(false)\r","UI.activateFollowAchievement(true)\r"],"dialogue_calls":[]},"scenario/1726.lua":{"source":"\n\n-- [EVENT] Initialisation\n-- \nfunction event_1726_14323()\n    \nend\n\n-- [ACTION] Lancement du combat associé\n-- \nfunction event_1726_14325(GroupId, MobA, MobB, MobC, MobD, MobE, MobF, MobG, MobH, FightId, PlayerId)\n    PlayerId = toLong(PlayerId)\r\n    GroupId =toLong(GroupId)\r\n    FightId = toLong(FightId)\r\n    MobA = toLong(MobA)\r\n    MobB = toLong(MobB)\r\n    MobC = toLong(MobC)\r\n    MobD = toLong(MobD)\r\n    MobE = toLong(MobE)\r\n    MobF = toLong(MobF)\r\n    MobG = toLong(MobG)\r\n    MobH = toLong(MobH)\r\n    \r\n    trace(\"===Valeur de Player Id ======\", PlayerId)\r\n    trace(\"===Valeur de Group Id ======\", GroupId)\r\n    trace(\"===Valeur de Fight Id ======\", FightId)\r\n    trace(\"===Valeur de MobA Id ======\", MobA)\r\n    trace(\"===Valeur de MobB Id ======\", MobB)\r\n    trace(\"===Valeur de MobC Id ======\", MobC)\r\n    trace(\"===Valeur de MobD Id ======\", MobD)\r\n    trace(\"===Valeur de MobE Id ======\", MobE)\r\n    trace(\"===Valeur de MobF Id ======\", MobF)\r\n    trace(\"===Valeur de MobG Id ======\", MobG)\r\n    trace(\"===Valeur de MobH Id ======\", MobH)\nend\n\n-- [ACTION] Fin de combat gagnant\n-- \nfunction event_1726_14326(GroupId)\n    \nend\n\n-- [ACTION] Fin de combat gagnant - fin scenario\n-- \nfunction event_1726_14457(GroupId)\n    \nend\n\n-- [ACTION] Fin de combat perdant\n-- \nfunction event_1726_14327(GroupId, MobA)\n    \nend\n\n","functions":["event_1726_14323","event_1726_14325","event_1726_14326","event_1726_14457","event_1726_14327"],"quest_calls":[],"dialogue_calls":[]},"scenario/1727.lua":{"source":"\n\n-- [INITIALISATION] Inscription du joueur\n-- \nfunction event_1727_14328()\n    \nend\n\n-- [COMBAT] Déclenchement du combat 0\n-- \nfunction event_1727_14939()\n    \nend\n\n-- [COMBAT] Lancement du combat\n-- \nfunction event_1727_14329()\n    \nend\n\n-- [QP] Transformation du joueur en pizz'larviolo\n-- \nfunction event_1727_14333()\n    \nend\n\n-- [QP] Victoire\n-- \nfunction event_1727_14355()\n    \nend\n\n","functions":["event_1727_14328","event_1727_14939","event_1727_14329","event_1727_14333","event_1727_14355"],"quest_calls":[],"dialogue_calls":[]},"scenario/1729.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_1729_14382()\n    \nend\n\n-- [INIT] Le premier joueur entre dans l'instance\n-- \nfunction event_1729_14356(grouilleux)\n    function cinematic()\r\n    \r\n    local playerId = Context.getLeaderId()\r\n    local mobId = toLong(grouilleux)\r\n    \r\n    startCinematicContext(1.4, mobId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 14380)\r\n    \r\n    invoke_custom(01000, 1, \"Camera.setMoveSpeedFactor\", 0.2)\r\n    invoke_custom(01000, 1, \"Camera.setZoomSpeedFactor\", 0.1)\r\n    \r\n    invoke_custom(01000, 1, \"Mobile.setMobileMovementStyle\", playerId, \"WALK\", \"WALK\")\r\n    invoke_custom(01000, 1, \"Mobile.setCustomWalkStyle\", playerId, \"AnimMarche\", 600)\r\n    \r\n    invoke_custom(01500, 1, \"Mobile.moveMobile\", playerId, 1, -2, 0)\r\n    \r\n    -- \"Qu'est-ce que... Un intrus ?!\"\r\n    invoke_custom(02000, 1, \"Mobile.setMobileAnimation\", mobId, \"AnimSort-Boost\")\r\n    invoke_custom(01000, 1, \"bubble\", mobId, \"quest.astrub.grouilleux.vengeance.0\")\r\n    invoke_custom(03500, 1, \"clearBubbles\", mobId)\r\n    \r\n    invoke_custom(03750, 1, \"Camera.attachCameraToMobile\", playerId)\r\n    invoke_custom(03750, 1, \"Camera.setZoomFactor\", 1.7)\r\n    \r\n    -- \"Je suis à la recherche du Chevalier d'Astrub...\"\r\n    invoke_custom(04000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Presenter\")\r\n    invoke_custom(04000, 1, \"bubble\", playerId, \"quest.astrub.grouilleux.vengeance.1\")\r\n    invoke_custom(07000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(07250, 1, \"Camera.attachCameraToMobile\", mobId)\r\n    \r\n    -- \"C'gros nul ! On l'a capturé et on va l'exécuter... Comme toi !\"\r\n    invoke_custom(07500, 1, \"Mobile.setMobileAnimation\", mobId, \"AnimComp-Rire\")\t\r\n    invoke_custom(07500, 1, \"bubble\", mobId, \"quest.astrub.grouilleux.vengeance.2\")\r\n    invoke_custom(11000, 1, \"clearBubbles\", mobId)\r\n    \r\n    -- \"J'te laisserai pas déranger maître Schredderche ! C'est l'heure de sa sieste !\"\r\n    invoke_custom(11500, 1, \"Mobile.setMobileAnimation\", mobId, \"AnimSort-Boost\")\t\r\n    invoke_custom(11500, 1, \"bubble\", mobId, \"quest.astrub.grouilleux.vengeance.2\")\r\n    invoke_custom(15500, 1, \"clearBubbles\", mobId)\r\n    \r\n    invoke_custom(16000, 1, \"skipCinematic\", 14380)\r\n    \r\n    end\r\n    \r\n    Event.runOnInstanceLoaded(\"cinematic\")\nend\n\n-- Lancement Combat\n-- \nfunction event_1729_14381()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_1729_14382","event_1729_14356","cinematic","event_1729_14381"],"quest_calls":[],"dialogue_calls":[]},"scenario/1730.lua":{"source":"function MindBubbleStart(mob,text,tDuration)\r\n\tMindBubble=BubbleText.showText(mob, text, 0, 40, false)\r\n\tinvoke(tDuration,1,\"BubbleText.close\",MindBubble)\r\nend\n\n-- [INITIALISATION] Variables\n-- \nfunction event_1730_14359()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_1730_14375()\n    \nend\n\n-- [SALLE 04] Suite - Cinématique d'arrivée dans les égouts\n-- \nfunction event_1730_14372(DonnallangeloId, PlayerId)\n    PlayerId = Context.getPlayer()\r\n    DonnallangeloIdval = toLong(DonnallangeloId)\r\n    DonnallangeloIdval = 0\r\n    \r\n    function startCine()\r\n    zoomFactor = Camera.getZoomFactor()\r\n    \tUI.manageFrame(\"World\",false) \t\t\t\t\t\r\n    \tCamera.setUserZoomLocked(true)\r\n    \tUI.closeMRU()\r\n    \tUI.closeAllBags()\t\t\t\t\t\t\t\t\t\t\t\t\r\n    \tUI.manageFrame(\"World\",false) \t\t\t\t\t\r\n    \tUI.setUIVisible(false)\r\n    \tUI.activateFollowAchievement(false)\r\n    \tUI.displayWideScreenBand(true)\r\n    Camera.attachCameraToMobile(PlayerId)\r\n    Camera.setZoomFactor(1.3)\r\n    DonnallangeloIdval = Mobile.generateClientMobileId() \r\n    Actor.createActor(DonnallangeloIdval, 1300071, -5, -6, 3, 4)\r\n    Mobile.setMobileDirection(DonnallangeloIdval,3)\r\n    Mobile.setMobileVisible(DonnallangeloIdval, true)\r\n    UI.setShortcutEnabled(false)\r\n    end\r\n    \r\n    function blabla()\r\n    invoke(50,1,\"Mobile.setMobileAnimation\",PlayerId,\"AnimEmote-Toux\")\r\n    invoke(200,1,\"MindBubbleStart\",DonnallangeloIdval,\"quest.Astrub.Donnallangelo.1\",3000)\r\n    invoke(3000,1,\"Mobile.setMobileDirection\",PlayerId,7)\r\n    invoke(3100,1,\"MindBubbleStart\",DonnallangeloIdval,\"quest.Astrub.Donnallangelo.2\",3000)\r\n    invoke(8100,1,\"MindBubbleStart\",DonnallangeloIdval,\"quest.Astrub.Donnallangelo.2-2\",2000)\r\n    invoke(8200,1,\"Mobile.setMobileAnimation\",PlayerId,\"AnimEmote-Effrayee\")\r\n    invoke(10100,1,\"MindBubbleStart\",DonnallangeloIdval,\"quest.Astrub.Donnallangelo.3\",4000)\r\n    invoke(12500,1,\"Mobile.setMobileAnimation\",PlayerId,\"AnimEmote-Acquiescer\")\r\n    invoke(15000,1,\"MindBubbleStart\",DonnallangeloIdval,\"quest.Astrub.Donnallangelo.4\",4000)\r\n    invoke(21000,1,\"MindBubbleStart\",DonnallangeloIdval,\"quest.Astrub.Donnallangelo.5\",4000)\r\n    invoke(22500,1,\"Mobile.setMobileAnimation\",PlayerId,\"AnimEmoteMarket-RougirHonte\")\r\n    invoke(26000,1,\"MindBubbleStart\",DonnallangeloIdval,\"quest.Astrub.Donnallangelo.6\",4000)\r\n    invoke(30100,1,\"MindBubbleStart\",DonnallangeloIdval,\"quest.Astrub.Donnallangelo.7\",4000)\r\n    invoke(32000,1,\"Mobile.setMobileAnimation\",PlayerId,\"AnimEmote-Colere\")\r\n    invoke(34100,1,\"MindBubbleStart\",DonnallangeloIdval,\"quest.Astrub.Donnallangelo.8\",4000)\r\n    invoke(38100,1,\"MindBubbleStart\",DonnallangeloIdval,\"quest.Astrub.Donnallangelo.9\",4000)\r\n    invoke(45000,1,\"MindBubbleStart\",DonnallangeloIdval,\"quest.Astrub.Donnallangelo.10\",4000)\r\n    invoke(47000,1,\"Mobile.setMobileAnimation\",PlayerId,\"AnimEmote-Acquiescer\")\r\n    ---invoke(47100,1,\"MindBubbleStart\",DonnallangeloIdval,\"quest.Astrub.Donnallangelo.11\",4000)\r\n    invoke(52000,1,\"MindBubbleStart\",DonnallangeloIdval,\"quest.Astrub.Donnallangelo.12\",4000)\r\n    invoke(56100,1,\"Mobile.setMobileAnimation\",PlayerId,\"AnimEmote-Huss-Boucle\")\r\n    invoke(59000,1,\"endCine\")\r\n    end\r\n    \r\n    \r\n     function endCine()\r\n    \tCamera.setUserZoomLocked(false)\t\t\t\t\t\t\t\t\t\r\n    \tUI.manageFrame(\"World\",true) \t\t\t\t\t\r\n    \tUI.setUIVisible(true)\t\r\n    \tUI.activateFollowAchievement(true)\r\n    \tCamera.attachCameraToMobile(PlayerId)\r\n    \tUI.displayWideScreenBand(false)\r\n    \tCamera.setZoomFactor(zoomFactor)\t\r\n    \tMobile.setMobileVisible(DonnallangeloIdval, false)\r\n    \tActor.deleteActor(DonnallangeloIdval)\t\r\n    \tUI.setShortcutEnabled(true)\r\n    end\r\n    \r\n    \r\n    ---Démarrage cinématique----\r\n    \r\n    invoke(4200,1,\"startCine\")\r\n    invoke(5500,1,\"blabla\")\nend\n\n-- [SALLE 04] Téléportation en 546\n-- \nfunction event_1730_14376()\n    player = Context.getPlayer()\r\n    \r\n    isValidMobile = Mobile.isMobile(player)\r\n    \r\n    if (isValidMobile ~= nil and isValidMobile) then\r\n    \tMobile.setMobileDirection(player, 7)\r\n    end\r\n    \r\n    Camera.setUserZoomLocked(false)\t\t\t\t\t\t\t\t\t\r\n    UI.manageFrame(\"World\",true) \t\t\t\t\t\r\n    UI.setUIVisible(true)\t\r\n    UI.activateFollowAchievement(true)\r\n    Camera.attachCameraToMobile(player)\r\n    UI.displayWideScreenBand(false)\r\n    Camera.setZoomFactor(zoomFactor)\t\nend\n\n","functions":["MindBubbleStart","event_1730_14359","event_1730_14375","event_1730_14372","startCine","blabla","endCine","event_1730_14376"],"quest_calls":["UI.activateFollowAchievement(false)\r","UI.activateFollowAchievement(true)\r","UI.activateFollowAchievement(true)\r"],"dialogue_calls":[]},"scenario/1731.lua":{"source":"playerId = Context.getLeaderId()\r\n\r\nfunction startCine()\r\n\tzoomFactor = Camera.getZoomFactor()\r\n\tCamera.attachCameraToMobile(PlayerId)\r\n\tCamera.setZoomFactor(1.5)\r\n\tUI.manageFrame(\"World\",false) \t\t\t\t\t\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\t\t\t\t\t\t\t\t\t\t\t\t\r\n\tUI.manageFrame(\"World\",false) \t\t\t\t\t\r\n\tUI.setUIVisible(false)\t\r\n\tUI.displayWideScreenBand(true)\r\n\tUI.setShortcutEnabled(false)\r\nend\r\n\r\nfunction endCine()\r\n\tCamera.attachCameraToMobile(PlayerId)\r\n\tCamera.setZoomFactor(zoomFactor)\r\n\tUI.displayWideScreenBand(false)\r\n\tCamera.setUserZoomLocked(false)\t\t\t\t\t\t\t\t\t\t\t\t\r\n\tUI.setUIVisible(true)\t\r\n\tUI.manageFrame(\"World\",true) \t\t\t\t\r\n\tUI.setShortcutEnabled(true)\r\nend\r\n\r\nfunction MindBubbleStart(mob,text,tDuration)\r\n\tMindBubble=BubbleText.showText(mob, text, 0, 40, false)\r\n\tinvoke(tDuration,1,\"BubbleText.close\",MindBubble)\r\nend\n\n-- Cinématique Ullu\n-- \nfunction event_1731_14387(PlayerId)\n    Ullu = Mobile.generateClientMobileId()\r\n    playerId = Context.getLeaderId()\r\n    \r\n    function apparitionUllu()\r\n        Mobile.setMobileDirection(PlayerId,7)\r\n        invoke(1000,1,\"Mobile.setMobileAnimation\",PlayerId,\"AnimEmote-Chercher\")\r\n        invoke(2000,1,\"MindBubbleStart\",PlayerId,\"quest.CineUllu.Player.1\",3000)\r\n        invoke(5500,1,\"MindBubbleStart\",PlayerId,\"quest.CineUllu.Player.2\",3000)\r\n    \tinvoke(8000,1,\"ulluSpeach\")\r\n    end\r\n    \r\n    function ulluSpeach()\t\r\n        Particle.addParticleSystem(800202, 0, -2, 0, 0)\r\n    \tActor.createActor(Ullu,1300051,0,-2, 0)\r\n    \tCamera.attachCameraToMobile(Ullu)\r\n    \tMobile.setMobileDirection(Ullu,3)\r\n    \tMobile.setMobileAnimation(Ullu, \"AnimComp-Ataaaque\")\r\n    \tinvoke(500,1,\"Mobile.setMobileAnimation\",PlayerId,\"AnimEmote-Effrayee\")\r\n    \tinvoke(1000,1,\"MindBubbleStart\",Ullu,\"quest.astrub.ullu.1\",3000)\r\n    \tinvoke(4100,1,\"MindBubbleStart\",Ullu,\"quest.astrub.ullu.2\",3000)\r\n    \tinvoke(4200,1,\"Mobile.setMobileAnimation\",PlayerId,\"AnimEmote-Effrayee\")\r\n    \tinvoke(7200,1,\"MindBubbleStart\",Ullu,\"quest.astrub.ullu.3\",4000)\r\n    \tinvoke(11300,1,\"MindBubbleStart\",Ullu,\"quest.astrub.ullu.4.2\",4000)\r\n    \tinvoke(11500,1,\"Mobile.setMobileAnimation\",PlayerId,\"AnimEmote-GratteGratte\")\r\n    \tinvoke(15400,1,\"MindBubbleStart\",Ullu,\"quest.astrub.ullu.5\",4000)\r\n    \tinvoke(19500,1,\"MindBubbleStart\",Ullu,\"quest.astrub.ullu.6\",4000)\r\n    \tinvoke(19600,1,\"Mobile.setMobileAnimation\",PlayerId,\"AnimEmote-Effrayee\")\r\n    \tinvoke(23600,1,\"Mobile.setMobileAnimation\",Ullu, \"AnimComp-Ataaaque\")\r\n    \tinvoke(23600,1,\"MindBubbleStart\",Ullu,\"quest.astrub.ullu.7\",4000)\r\n    \tinvoke(27700,1,\"MindBubbleStart\",Ullu,\"quest.astrub.ullu.8\",4000)\r\n    \tinvoke(27500,1,\"Mobile.setMobileAnimation\",PlayerId,\"AnimEmote-Genoux-Debut\")\r\n    \tinvoke(30000,1,\"Particle.addParticleSystem\",800202, 0, 0, 0, 0)\r\n    \t\r\n    end\r\n    \r\n    startCine()\r\n    Particle.addParticleSystem(7034001, 0, 0, 0) \r\n    Sound.playForcedMusic(210079)\r\n    invoke(1000,1,\"apparitionUllu\")\nend\n\n-- Téléportation en 527\n-- \nfunction event_1731_14388()\n    player = Context.getPlayer()\r\n    \r\n    isValidMobile = Mobile.isMobile(player)\r\n    \r\n    if (isValidMobile ~= nil and isValidMobile) then\r\n    \tMobile.setMobileDirection(player, 7)\r\n    end\r\n    \r\n    endCine()\r\n    Sound.stopForcedMusic()\nend\n\n","functions":["startCine","endCine","MindBubbl