MobF)\r\n    MobG = toLong(MobG)\r\n    MobH = toLong(MobH)\r\n    \r\n    trace(\"===Valeur de Player Id ======\", PlayerId)\r\n    trace(\"===Valeur de Group Id ======\", GroupId)\r\n    trace(\"===Valeur de Fight Id ======\", FightId)\r\n    trace(\"===Valeur de MobA Id ======\", MobA)\r\n    trace(\"===Valeur de MobB Id ======\", MobB)\r\n    trace(\"===Valeur de MobC Id ======\", MobC)\r\n    trace(\"===Valeur de MobD Id ======\", MobD)\r\n    trace(\"===Valeur de MobE Id ======\", MobE)\r\n    trace(\"===Valeur de MobF Id ======\", MobF)\r\n    trace(\"===Valeur de MobG Id ======\", MobG)\r\n    trace(\"===Valeur de MobH Id ======\", MobH)\nend\n\n-- [ACTION] Fin de combat gagnant\n-- \nfunction event_1768_14556(GroupId)\n    \nend\n\n-- [ACTION] Fin de combat gagnant - fin scenario\n-- \nfunction event_1768_14557(GroupId)\n    \nend\n\n-- [ACTION] Fin de combat perdant\n-- \nfunction event_1768_14558(GroupId, MobA)\n    \nend\n\n","functions":["event_1768_14554","event_1768_14555","event_1768_14556","event_1768_14557","event_1768_14558"],"quest_calls":[],"dialogue_calls":[]},"scenario/1769.lua":{"source":"\n\n-- [EVENT] Initialisation\n-- \nfunction event_1769_14559()\n    \nend\n\n-- [ACTION] Activation IE\n-- \nfunction event_1769_14560(GroupId, MobA)\n    \nend\n\n","functions":["event_1769_14559","event_1769_14560"],"quest_calls":[],"dialogue_calls":[]},"scenario/1772.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\nif chest==0 then\r\n\tWorld.setPictoAlpha(28, 41, 0, 0, 1)\r\n\tWorld.setPictoAlpha(29, 41, 0, 0, 1)\r\nelseif chest==1 then\r\n\tWorld.setPictoAlpha(28, 41, 0, 1, 1)\r\n\tWorld.setPictoAlpha(29, 41, 0, 1, 1)\r\nend\r\n\r\nfunction displayPath(room)\r\n\tlocal room = toLong(room)\r\n\t\r\n\tif ( room >= 1 or room == -1 ) then\r\n\t\tWorld.setPictoAlpha(28, 41, 0, 0, 1000)\r\n\t\tWorld.setPictoAlpha(29, 41, 0, 0, 1000)\r\n\r\n\t\tWorld.setPictoAlpha(15, 44, 0, 0, 1000)\r\n\t\tWorld.setPictoAlpha(14, 44, 0, 0, 1000)\r\n\t\tWorld.setPictoAlpha(13, 44, 0, 0, 1000)\r\n\t\tWorld.setPictoAlpha(12, 44, 0, 0, 1000)\r\n\t\tWorld.setPictoAlpha(15, 45, 0, 0, 1000)\r\n\t\tWorld.setPictoAlpha(14, 45, 0, 0, 1000)\r\n\t\tWorld.setPictoAlpha(13, 45, 0, 0, 1000)\r\n\t\tWorld.setPictoAlpha(12, 45, 0, 0, 1000)\r\n\t\tWorld.setPictoAlpha(5, 52, 0, 0, 1000)\r\n\t\tWorld.setPictoAlpha(5, 53, 0, 0, 1000)\r\n\t\tWorld.setPictoAlpha(5, 54, 0, 0, 1000)\r\n\t\tWorld.setPictoAlpha(-7, 58, 0, 0, 1000)\r\n\t\tWorld.setPictoAlpha(-8, 58, 0, 0, 1000)\r\n\t\tWorld.setPictoAlpha(-9, 58, 0, 0, 1000)\r\n\t\tWorld.setPictoAlpha(-10, 58, 0, 0, 1000)\r\n\t\tWorld.setPictoAlpha(-11, 58, 0, 0, 1000)\r\n\tend\r\n\t\r\n\tif ( room >= 2 or room == -1 ) then\r\n\t\tWorld.setPictoAlpha(28, 41, 0, 0, 1000)\r\n\t\tWorld.setPictoAlpha(29, 41, 0, 0, 1000)\r\n\t\r\n\t\tWorld.setPictoAlpha(15, 44, 0, 1, 1000)\r\n\t\tWorld.setPictoAlpha(14, 44, 0, 1, 1000)\r\n\t\tWorld.setPictoAlpha(13, 44, 0, 1, 1000)\r\n\t\tWorld.setPictoAlpha(12, 44, 0, 1, 1000)\r\n\t\tWorld.setPictoAlpha(15, 45, 0, 1, 1000)\r\n\t\tWorld.setPictoAlpha(14, 45, 0, 1, 1000)\r\n\t\tWorld.setPictoAlpha(13, 45, 0, 1, 1000)\r\n\t\tWorld.setPictoAlpha(12, 45, 0, 1, 1000)\r\n\t\tWorld.setPictoAlpha(5, 52, 0, 0, 1000)\r\n\t\tWorld.setPictoAlpha(5, 53, 0, 0, 1000)\r\n\t\tWorld.setPictoAlpha(5, 54, 0, 0, 1000)\r\n\t\tWorld.setPictoAlpha(-7, 58, 0, 0, 1000)\r\n\t\tWorld.setPictoAlpha(-8, 58, 0, 0, 1000)\r\n\t\tWorld.setPictoAlpha(-9, 58, 0, 0, 1000)\r\n\t\tWorld.setPictoAlpha(-10, 58, 0, 0, 1000)\r\n\t\tWorld.setPictoAlpha(-11, 58, 0, 0, 1000)\r\n\tend\r\n\t\r\n\tif ( room >= 3 or room == -1) then\r\n\t\tWorld.setPictoAlpha(28, 41, 0, 0, 1000)\r\n\t\tWorld.setPictoAlpha(29, 41, 0, 0, 1000)\r\n\t\r\n\t\tWorld.setPictoAlpha(15, 44, 0, 1, 1000)\r\n\t\tWorld.setPictoAlpha(14, 44, 0, 1, 1000)\r\n\t\tWorld.setPictoAlpha(13, 44, 0, 1, 1000)\r\n\t\tWorld.setPictoAlpha(12, 44, 0, 1, 1000)\r\n\t\tWorld.setPictoAlpha(15, 45, 0, 1, 1000)\r\n\t\tWorld.setPictoAlpha(14, 45, 0, 1, 1000)\r\n\t\tWorld.setPictoAlpha(13, 45, 0, 1, 1000)\r\n\t\tWorld.setPictoAlpha(12, 45, 0, 1, 1000)\r\n\t\tWorld.setPictoAlpha(5, 52, 0, 1, 1000)\r\n\t\tWorld.setPictoAlpha(5, 53, 0, 1, 1000)\r\n\t\tWorld.setPictoAlpha(5, 54, 0, 1, 1000)\r\n\t\tWorld.setPictoAlpha(-7, 58, 0, 0, 1000)\r\n\t\tWorld.setPictoAlpha(-8, 58, 0, 0, 1000)\r\n\t\tWorld.setPictoAlpha(-9, 58, 0, 0, 1000)\r\n\t\tWorld.setPictoAlpha(-10, 58, 0, 0, 1000)\r\n\t\tWorld.setPictoAlpha(-11, 58, 0, 0, 1000)\r\n\tend\r\n\t\t\r\n\tif ( room == -1) then\r\n\t\tWorld.setPictoAlpha(28, 41, 0, 0, 1000)\r\n\t\tWorld.setPictoAlpha(29, 41, 0, 0, 1000)\r\n\t\t\r\n\t\tWorld.setPictoAlpha(15, 44, 0, 1, 1000)\r\n\t\tWorld.setPictoAlpha(14, 44, 0, 1, 1000)\r\n\t\tWorld.setPictoAlpha(13, 44, 0, 1, 1000)\r\n\t\tWorld.setPictoAlpha(12, 44, 0, 1, 1000)\r\n\t\tWorld.setPictoAlpha(15, 45, 0, 1, 1000)\r\n\t\tWorld.setPictoAlpha(14, 45, 0, 1, 1000)\r\n\t\tWorld.setPictoAlpha(13, 45, 0, 1, 1000)\r\n\t\tWorld.setPictoAlpha(12, 45, 0, 1, 1000)\r\n\t\tWorld.setPictoAlpha(5, 52, 0, 1, 1000)\r\n\t\tWorld.setPictoAlpha(5, 53, 0, 1, 1000)\r\n\t\tWorld.setPictoAlpha(5, 54, 0, 1, 1000)\r\n\t\tWorld.setPictoAlpha(-7, 58, 0, 1, 1000)\r\n\t\tWorld.setPictoAlpha(-8, 58, 0, 1, 1000)\r\n\t\tWorld.setPictoAlpha(-9, 58, 0, 1, 1000)\r\n\t\tWorld.setPictoAlpha(-10, 58, 0, 1, 1000)\r\n\t\tWorld.setPictoAlpha(-11, 58, 0, 1, 1000)\r\n\tend\r\nend\n\n-- [INIT] Variables Globales\n-- \nfunction event_1772_20045()\n    \nend\n\n-- [INIT] Inscription du joueur + Variables Locales\n-- \nfunction event_1772_20046(room)\n    displayPath(room)\nend\n\n-- *[OLD][1] Victoire - Déverrouille le passage vers S2\n-- \nfunction event_1772_20047(room)\n    displayPath(room)\nend\n\n-- USER_GROUP_KILLED - Salle 01\n-- \nfunction event_1772_20048(room)\n    displayPath(room)\nend\n\n-- USER_GROUP_KILLED - Salle 02\n-- \nfunction event_1772_20049(room)\n    displayPath(room)\nend\n\n-- USER_GROUP_KILLED - Salle 03 - BOSS\n-- \nfunction event_1772_20050(room)\n    displayPath(room)\nend\n\n-- Déplace le joueur vers la salle suivante\n-- \nfunction event_1772_20051()\n    \nend\n\n-- [EVENT] Salle Archimonstre - Le joueur sort de l'instance\n-- \nfunction event_1772_14615()\n    \nend\n\n-- [EVENT] Salle Archimonstre - Apparition de l'archimonstre\n-- \nfunction event_1772_14625()\n    \nend\n\n-- [EVENT] Salle Archimonstre - Timer - Retrait de l'item de l'inventaire\n-- \nfunction event_1772_16810()\n    \nend\n\n-- [EVENT] Salle Archimonstre - Victoire - On active le coffre mimic\n-- \nfunction event_1772_16874()\n    World.setPictoAlpha(28, 41, 0, 1, 1000)\r\n    World.setPictoAlpha(29, 41, 0, 1, 1000)\nend\n\n-- [EVENT] Quête Mercenaire - Victoire contre le BOSS - Cinématique\n-- \nfunction event_1772_19887(npcGlovis)\n            \t----------------------------- RECUPERATIONS DES INFOS JOUEUR --------------------------\r\n            \r\n            \tlocal playerId = Context.getLeaderId()\r\n            \tlocal playerX, playerY, playerZ = Mobile.getMobilePosition(playerId)\r\n            \r\n            \r\n            \t----------------------------- INITIALISATION DES PNJ --------------------------\r\n            \r\n            \tlocal npcGlovisId = toLong(npcGlovis)\r\n            \tlocal mobileGlovisId = createActor(30, -3, 59, 0, 8, 1, 7, npcGlovisId)\r\n            \tlocal planteCarnivore = createActor(101601726, -5, 59, 0, 8, 1, 7)\r\n            \r\n            \r\n            \t----------------------------- DEBUT DE CINEMATIQUE --------------------------\r\n            \r\n            \tstartCinematicContext(1.3, playerId)\r\n            \tUI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 19887)\r\n            \r\n            \r\n            \tinvoke_custom(1, 1, \"UI.displayWideScreenBand\", true, 100, 300)\r\n            \t\r\n            \tinvoke_custom(500, 1, \"Mobile.setMobileVisible\", npcGlovisId, false)\r\n            \tinvoke_custom(600, 1, \"Mobile.setMobileVisible\", mobileGlovisId, false)\r\n            \t\r\n            \t   invoke_custom(800, 1, \"UI.displayWideScreenBand\", true, 20, 500)\r\n            \r\n            \t----------------------------- DIALOGUES --------------------------\r\n            \r\n            \t-- Je suppose que tu es Glovis...\r\n            \tinvoke_custom(8000, 1, \"bubble\", playerId, \"quest.amakna.mercenary.plantes.02.01\")\r\n            \tinvoke_custom(8000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Rire\")\r\n            \r\n            \t-- Eurk... c'est bien moi, je vous souhaite de ne jamais vous faire bouloter par une plante géante, j'ai bien cru ma dernière heure arriver !\r\n    \t\t\tinvoke_custom(11800, 1, \"clearBubbles\", playerId)\r\n    \t\t\tinvoke_custom(12000, 1, \"bubble\", mobileGlovisId, \"quest.amakna.mercenary.plantes.02.02\")\r\n            \tinvoke_custom(12000, 1, \"Mobile.setMobileAnimation\", mobileGlovisId, \"AnimEmote-Fievre\")\r\n            \r\n            \t-- Merci pour le sauvetage d'ailleurs, vous êtes?\r\n    \t\t\tinvoke_custom(18800, 1, \"clearBubbles\", mobileGlovisId)\r\n            \tinvoke_custom(19000, 1, \"bubble\", mobileGlovisId, \"quest.amakna.mercenary.plantes.02.03\")\r\n            \tinvoke_custom(19000, 1, \"Mobile.setMobileAnimation\", mobileGlovisId, \"AnimEmote-Pouce\")\r\n            \r\n            \t-- [#name], aventuri{[1*]?ère:er}, je suis venu régler la pagaille que tu as mis, je pense qu'on a deux trois choses à se dire...\r\n        \t\tinvoke_custom(22800, 1, \"clearBubbles\", mobileGlovisId)\r\n            \tinvoke_custom(23000, 1, \"bubble\", playerId, \"quest.amakna.mercenary.plantes.02.04\")\r\n            \tinvoke_custom(23000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Non\")\r\n            \r\n            \t-- Je n'ai jamais voulu faire du mal à qui que ce soit !!!\r\n    \t\t\tinvoke_custom(27800, 1, \"clearBubbles\", playerId)\r\n            \tinvoke_custom(28000, 1, \"bubble\", mobileGlovisId, \"quest.amakna.mercenary.plantes.02.05\")\r\n            \tinvoke_custom(28000, 1, \"Mobile.setMobileAnimation\", mobileGlovisId, \"AnimEmote-Help\")\r\n            \r\n            \t-- C'est ce Steamer qui est venu me voir et m'a dit de pulvériser ce produit sur mes plantes !\r\n        \t\tinvoke_custom(31800, 1, \"clearBubbles\", mobileGlovisId)\r\n            \tinvoke_custom(32000, 1, \"bubble\", mobileGlovisId, \"quest.amakna.mercenary.plantes.02.06\")\r\n            \tinvoke_custom(32000, 1, \"Mobile.setMobileAnimation\", mobileGlovisId, \"AnimEmote-Calmer\")\r\n        \r\n        \t\t-- Et tu l'as fait sans te poser de questions ?\r\n    \t\t\tinvoke_custom(36800, 1, \"clearBubbles\", mobileGlovisId)\r\n        \t\tinvoke_custom(37000, 1, \"bubble\", playerId, \"quest.amakna.mercenary.plantes.02.07\")\r\n        \t\tinvoke_custom(37000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Non\")\r\n        \r\n        \t\t-- J'avais tout perdu, il m'offrait une solution miracle, je ne pouvais pas refuser...\r\n        \t\tinvoke_custom(40800, 1, \"clearBubbles\", playerId)\r\n        \t\tinvoke_custom(41000, 1, \"bubble\", mobileGlovisId, \"quest.amakna.mercenary.plantes.02.08\")\r\n        \t\tinvoke_custom(41000, 1, \"Mobile.setMobileAnimation\", mobileGlovisId, \"AnimEmote-Defaite\")\r\n        \r\n        \t\t-- Je comprends, quel genre de personne est-ce pour profiter du malheur des autres...\r\n    \t\t\tinvoke_custom(45800, 1, \"clearBubbles\", mobileGlovisId)\r\n        \t\tinvoke_custom(46000, 1, \"bubble\", playerId, \"quest.amakna.mercenary.plantes.02.09\")\r\n        \t\tinvoke_custom(46000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n        \r\n        \t\t-- Je suis navré, il ne m'a pas donné de nom mais je peux essayer de répondre à vos questions.\r\n    \t\t\tinvoke_custom(51800, 1, \"clearBubbles\", playerId)\r\n        \t\tinvoke_custom(52000, 1, \"bubble\", mobileGlovisId, \"quest.amakna.mercenary.plantes.02.10\")\r\n        \t\tinvoke_custom(52000, 1, \"Mobile.setMobileAnimation\", mobileGlovisId, \"AnimEmoteMarket-HausseEpaules\")\r\n            \r\n            \t----------------------------- ACTIONS --------------------------\r\n            \r\n            \tinvoke_custom(500, 1, \"Mobile.moveMobile\", playerId, -1, 59, 0, \"Mobile.setMobileDirection\", playerId, 5)\r\n            \tinvoke_custom(3000, 1, \"Mobile.setMobileAnimation\", planteCarnivore, \"AnimSort02-Invoc\")\r\n            \r\n            \tinvoke_custom(4000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Chercher\")\r\n            \tinvoke_custom(4200, 1, \"Mobile.setMobileAnimation\", planteCarnivore, \"AnimSort04-Crachouille\")\r\n            \tinvoke_custom(5200, 1, \"Mobile.setMobileAnimation\", planteCarnivore, \"AnimMort\")\r\n            \r\n            \tinvoke_custom(4600, 1, \"Mobile.setMobileAnimation\", mobileGlovisId, \"AnimApparition\")\r\n            \tinvoke_custom(4700, 1, \"Mobile.setMobileVisible\", mobileGlovisId, true)\r\n            \r\n            \tinvoke_custom(8400, 1, \"Mobile.setMobileAnimation\", mobileGlovisId, \"AnimEmote-Vomis\")\r\n        \r\n            \t----------------------------- FIN DE CINEMATIQUE --------------------------\r\n        \r\n        \t\tinvoke_custom(57000, 1, \"UI.displayWideScreenBand\", true, 100, 300)\r\n        \t\r\n            \tinvoke_custom(57500, 1, \"Mobile.moveMobile\", playerId, playerX, playerY, playerZ)\r\n            \tinvoke_custom(57800, 1, \"Mobile.setMobileVisible\", npcGlovisId, true)\r\n            \t\r\n            \tinvoke_custom(57999, 1, \"UI.displayWideScreenBand\", true, 25, 300)\r\n            \t\r\n            \tinvoke(58000, 1, \"skipCinematic\", 19887)\nend\n\n-- [ARCHI] Apparition de l'Archimonstre\n-- \nfunction event_1772_23948()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","displayPath","event_1772_20045","event_1772_20046","event_1772_20047","event_1772_20048","event_1772_20049","event_1772_20050","event_1772_20051","event_1772_14615","event_1772_14625","event_1772_16810","event_1772_16874","event_1772_19887","event_1772_23948"],"quest_calls":[],"dialogue_calls":[]},"scenario/1773.lua":{"source":"\n\n-- [EVENT] Initialisation\n-- \nfunction event_1773_14627()\n    \nend\n\n-- [ACTION] Lancement du combat associé\n-- \nfunction event_1773_14628(GroupId, MobA, MobB, MobC, MobD, MobE, MobF, MobG, MobH, FightId, PlayerId)\n    PlayerId = toLong(PlayerId)\r\n    GroupId =toLong(GroupId)\r\n    FightId = toLong(FightId)\r\n    MobA = toLong(MobA)\r\n    MobB = toLong(MobB)\r\n    MobC = toLong(MobC)\r\n    MobD = toLong(MobD)\r\n    MobE = toLong(MobE)\r\n    MobF = toLong(MobF)\r\n    MobG = toLong(MobG)\r\n    MobH = toLong(MobH)\r\n    \r\n    trace(\"===Valeur de Player Id ======\", PlayerId)\r\n    trace(\"===Valeur de Group Id ======\", GroupId)\r\n    trace(\"===Valeur de Fight Id ======\", FightId)\r\n    trace(\"===Valeur de MobA Id ======\", MobA)\r\n    trace(\"===Valeur de MobB Id ======\", MobB)\r\n    trace(\"===Valeur de MobC Id ======\", MobC)\r\n    trace(\"===Valeur de MobD Id ======\", MobD)\r\n    trace(\"===Valeur de MobE Id ======\", MobE)\r\n    trace(\"===Valeur de MobF Id ======\", MobF)\r\n    trace(\"===Valeur de MobG Id ======\", MobG)\r\n    trace(\"===Valeur de MobH Id ======\", MobH)\nend\n\n-- [ACTION] Fin de combat gagnant\n-- \nfunction event_1773_14629(GroupId)\n    \nend\n\n-- [ACTION] Fin de combat gagnant - fin scenario\n-- \nfunction event_1773_14630(GroupId)\n    \nend\n\n-- [ACTION] Fin de combat perdant\n-- \nfunction event_1773_14631(GroupId, MobA, MobB, MobC)\n    \nend\n\n","functions":["event_1773_14627","event_1773_14628","event_1773_14629","event_1773_14630","event_1773_14631"],"quest_calls":[],"dialogue_calls":[]},"scenario/1774.lua":{"source":"\n\n-- [EVENT] Initialisation\n-- \nfunction event_1774_14632()\n    \nend\n\n-- [ACTION] Activation IE\n-- \nfunction event_1774_14633(GroupId, MobA)\n    \nend\n\n","functions":["event_1774_14632","event_1774_14633"],"quest_calls":[],"dialogue_calls":[]},"scenario/1775.lua":{"source":"\n\n-- [EVENT] Initialisation\n-- \nfunction event_1775_14634()\n    \nend\n\n-- [ACTION] Lancement du combat associé\n-- \nfunction event_1775_14635(GroupId, MobA, MobB, MobC, MobD, MobE, MobF, MobG, MobH, FightId, PlayerId)\n    PlayerId = toLong(PlayerId)\r\n    GroupId =toLong(GroupId)\r\n    FightId = toLong(FightId)\r\n    MobA = toLong(MobA)\r\n    MobB = toLong(MobB)\r\n    MobC = toLong(MobC)\r\n    MobD = toLong(MobD)\r\n    MobE = toLong(MobE)\r\n    MobF = toLong(MobF)\r\n    MobG = toLong(MobG)\r\n    MobH = toLo