LLED - Salle 01\n-- \nfunction event_1784_20240(room)\n    displayPath(room)\nend\n\n-- USER_GROUP_KILLED - Salle 02\n-- \nfunction event_1784_20241(room)\n    displayPath(room)\nend\n\n-- USER_GROUP_KILLED - Salle 03\n-- \nfunction event_1784_20242()\n    \nend\n\n-- Déplace le joueur vers la salle suivante\n-- \nfunction event_1784_20243()\n    \nend\n\n-- [ARCHI] Apparition de l'Archimonstre\n-- \nfunction event_1784_23965()\n    \nend\n\n","functions":["displayPath","event_1784_20237","event_1784_20238","event_1784_20240","event_1784_20241","event_1784_20242","event_1784_20243","event_1784_23965"],"quest_calls":[],"dialogue_calls":[]},"scenario/1785.lua":{"source":"\n\n-- [INITIALISATION] Serveur\n-- \nfunction event_1785_14689()\n    \nend\n\n","functions":["event_1785_14689"],"quest_calls":[],"dialogue_calls":[]},"scenario/1786.lua":{"source":"\n\n-- [INIT] Variables Globales\n-- \nfunction event_1786_20193()\n    \nend\n\n-- [INIT] Inscription du joueur + Variables Locales\n-- \nfunction event_1786_20194()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 01\n-- \nfunction event_1786_20195()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 02\n-- \nfunction event_1786_20196()\n    invoke(4000, 1, \"Particle.addParticleSystem\", 800202, -21, 19, -24, 0)\nend\n\n-- USER_GROUP_KILLED - Salle 03\n-- \nfunction event_1786_20197()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 04 - BOSS\n-- \nfunction event_1786_20198()\n    \nend\n\n-- Déplace le joueur vers la salle suivante\n-- \nfunction event_1786_20199()\n    \nend\n\n-- [RECEPTACLE] Ouverture du warp\n-- \nfunction event_1786_14699()\n    invoke(0, 1, \"Particle.addParticleSystem\", 800202, -21, 19, -24, 0)\nend\n\n-- [EVENT] On rend les monstres de la salle du boss inattaquable\n-- Cela nous permet d'éviter d'avoir la mauvaise bulle de combat sur le combat du boss\nfunction event_1786_20268()\n    \nend\n\n-- [ARCHI] Apparition de l'Archimonstre\n-- \nfunction event_1786_24316()\n    \nend\n\n","functions":["event_1786_2019