,"event_1835_14873","event_1835_14874"],"quest_calls":[],"dialogue_calls":[]},"scenario/1836.lua":{"source":"\n\n-- [EVENT] Initialisation\n-- \nfunction event_1836_14875()\n    \nend\n\n-- [ACTION] Lancement du combat associé\n-- \nfunction event_1836_14876()\n    \nend\n\n-- [ACTION] Fin de combat gagnant\n-- \nfunction event_1836_14877(GroupId)\n    \nend\n\n-- [ACTION] Fin de combat gagnant - fin scenario\n-- \nfunction event_1836_14878(GroupId)\n    \nend\n\n-- [ACTION] Fin de combat perdant\n-- \nfunction event_1836_14879(GroupId, MobA)\n    \nend\n\n","functions":["event_1836_14875","event_1836_14876","event_1836_14877","event_1836_14878","event_1836_14879"],"quest_calls":[],"dialogue_calls":[]},"scenario/1837.lua":{"source":"\n\n-- [EVENT] Initialisation\n-- \nfunction event_1837_14880()\n    \nend\n\n-- [ACTION] Lancement du combat associé\n-- \nfunction event_1837_14881()\n    \nend\n\n-- [ACTION] Fin de combat gagnant\n-- \nfunction event_1837_14882(GroupId)\n    \nend\n\n-- [ACTION] Fin de combat gagnant - fin scenario\n-- \nfunction event_1837_14883(GroupId)\n    \nend\n\n-- [ACTION] Fin de combat perdant\n-- \nfunction event_1837_14884(GroupId, MobA)\n    \nend\n\n","functions":["event_1837_14880","event_1837_14881","event_1837_14882","event_1837_14883","event_1837_14884"],"quest_calls":[],"dialogue_calls":[]},"scenario/1838.lua":{"source":"\n\n-- [EVENT] Initialisation\n-- \nfunction event_1838_14885()\n    \nend\n\n-- [ACTION] Lancement du combat associé\n-- \nfunction event_1838_14886(GroupId, MobA, MobB, MobC, MobD, MobE, MobF, MobG, MobH, FightId, PlayerId)\n    PlayerId = toLong(PlayerId)\r\n    GroupId =toLong(GroupId)\r\n    FightId = toLong(FightId)\r\n    MobA = toLong(MobA)\r\n    MobB = toLong(MobB)\r\n    MobC = toLong(MobC)\r\n    MobD = toLong(MobD)\r\n    MobE = toLong(MobE)\r\n    MobF = toLong(MobF)\r\n    MobG = toLong(MobG)\r\n    MobH = toLong(MobH)\r\n    \r\n    trace(\"===Valeur de Player Id ======\", PlayerId)\r\n    trace(\"===Valeur de Group Id ======\", GroupId)\r\n    trace(\"===Valeur de Fight Id ======\", FightId)\r\n    trace(\"===Valeur de MobA Id ======\", MobA)\r\n    trace(\"===Valeur de MobB Id ======\", MobB)\r\n    trace(\"===Valeur de MobC Id ======\", MobC)\r\n    trace(\"===Valeur de MobD Id ======\", MobD)\r\n    trace(\"===Valeur de MobE Id ======\", MobE)\r\n    trace(\"===Valeur de MobF Id ======\", MobF)\r\n    trace(\"===Valeur de MobG Id ======\", MobG)\r\n    trace(\"===Valeur de MobH Id ======\", MobH)\nend\n\n-- [ACTION] Fin de combat gagnant\n-- \nfunction event_1838_14887(GroupId)\n    \nend\n\n-- [ACTION] Fin de combat gagnant - fin scenario\n-- \nfunction event_1838_14888(GroupId)\n    \nend\n\n-- [ACTION] Fin de combat perdant\n-- \nfunction event_1838_14889(GroupId, MobA, MobB, MobC)\n    \nend\n\n","functions":["event_1838_14885","event_1838_14886","event_1838_14887","event_1838_14888","event_1838_14889"],"quest_calls":[],"dialogue_calls":[]},"scenario/1842.lua":{"source":"\n\n-- [EVENT] Initialisation\n-- \nfunction event_1842_14896()\n    \nend\n\n-- [ACTION] Lancement du combat associé\n-- \nfunction event_1842_14897(GroupId, MobA, MobB, MobC, MobD, MobE, MobF, MobG, MobH, FightId, PlayerId)\n    PlayerId = toLong(PlayerId)\r\n    GroupId =toLong(GroupId)\r\n    FightId = toLong(FightId)\r\n    MobA = toLong(MobA)\r\n    MobB = toLong(MobB)\r\n    MobC = toLong(MobC)\r\n    MobD = toLong(MobD)\r\n    MobE = toLong(MobE)\r\n    MobF = toLong(MobF)\r\n    MobG = toLong(MobG)\r\n    MobH = toLong(MobH)\r\n    \r\n    trace(\"===Valeur de Player Id ======\", PlayerId)\r\n    trace(\"===Valeur de Group Id ======\", GroupId)\r\n    trace(\"===Valeur de Fight Id ======\", FightId)\r\n    trace(\"===Valeur de MobA Id ======\", MobA)\r\n    trace(\"===Valeur de MobB Id ======\", MobB)\r\n    trace(\"===Valeur de MobC Id ======\", MobC)\r\n    trace(\"===Valeur de MobD Id ======\", MobD)\r\n    trace(\"===Valeur de MobE Id ======\", MobE)\r\n    trace(\"===Valeur de MobF Id ======\", MobF)\r\n    trace(\"===Valeur de MobG Id ======\", MobG)\r\n    trace(\"===Valeur de MobH Id ======\", MobH)\nend\n\n-- [ACTION] Fin de combat gagnant\n-- \nfunction event_1842_14898(GroupId)\n    \nend\n\n-- [ACTION] Fin de combat gagnant - fin scenario\n-- \nfunction event_1842_14899(GroupId)\n    \nend\n\n-- [ACTION] Fin de combat perdant\n-- \nfunction event_1842_14900(GroupId, MobA)\n    \nend\n\n","functions":["event_1842_14896","event_1842_14897","event_1842_14898","event_1842_14899","event_1842_14900"],"quest_calls":[],"dialogue_calls":[]},"scenario/1843.lua":{"source":"\n\n-- [EVENT] Initialisation\n-- \nfunction event_1843_14901()\n    \nend\n\n-- [ACTION] Lancement du combat associé\n-- \nfunction event_1843_14902()\n    \nend\n\n-- [ACTION] Fin de combat gagnant\n-- \nfunction event_1843_14903(GroupId)\n    \nend\n\n-- [ACTION] Fin de combat gagnant - fin scenario\n-- \nfunction event_1843_14904(GroupId)\n    \nend\n\n-- [ACTION] Fin de combat perdant\n-- \nfunction event_1843_14905(GroupId, MobA)\n    \nend\n\n","functions":["event_1843_14901","event_1843_14902","event_1843_14903","event_1843_14904","event_1843_14905"],"quest_calls":[],"dialogue_calls":[]},"scenario/1844.lua":{"source":"playerId = Context.getPlayer()\r\n\r\nfunction startCine()\r\n\tzoomFactor = Camera.getZoomFactor()\r\n\tUI.manageFrame(\"World\",false) \t\t\t\t\t\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\t\t\t\t\t\t\t\t\t\t\t\t\r\n\tUI.manageFrame(\"World\",false) \t\t\t\t\t\r\n\tUI.setUIVisible(false)\t\r\n\tUI.displayWideScreenBand(true)\r\nend\r\n\r\nfunction endCine()\r\n\tCamera.attachCameraToMobile(playerId)\r\n\tUI.displayWideScreenBand(false)\r\n\tCamera.setUserZoomLocked(false)\t\t\t\t\t\t\t\t\t\t\t\t\r\n\tUI.setUIVisible(true)\t\r\n\tUI.manageFrame(\"World\",true) \t\t\t\t\r\n\tCamera.setZoomFactor(zoomFactor)\t\r\nend\r\n\r\nfunction Bubble(mob,text)\r\n\tBubbleText.closeBubbleAttachedTo(mob)\r\n\tBubbleText.showText(mob, text, 0, 40, false)\r\nend\r\n\n\n-- [INIT] Variables\n-- \nfunction event_1844_14922()\n    \nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_1844_14923()\n    Particle.addParticleSystem(800528, 0,-1,-38)\nend\n\n-- [COMBAT] Combat contre les Srams - Apparition\n-- \nfunction event_1844_14934(SramIdOne, SramIdTwo, SramIdThree, SramIdFour)\n    one = toLong(SramIdOne)\r\n    two = toLong(SramIdTwo)\r\n    three = toLong(SramIdThree)\r\n    four = toLong(SramIdFour)\r\n    \r\n    Mobile.setMobileDirection(one,7)\r\n    Mobile.setMobileDirection(two,7)\r\n    Mobile.setMobileDirection(three,7)\r\n    Mobile.setMobileDirection(four,7)\r\n    \r\n    Mobile.setMobileAnimation(one,\"AnimSort-Apparition\")\r\n    Mobile.setMobileAnimation(two,\"AnimSort-Apparition\")\r\n    Mobile.setMobileAnimation(three,\"AnimSort-Apparition\")\r\n    Mobile.setMobileAnimation(four,\"AnimSort-Apparition\")\r\n    \r\n    Camera.attachCameraToMobile(one)\r\n    \r\n    invoke(1000,1,\"Bubble\",one,\"quest.DDCH3.xelorium.sramAttack.1\")\r\n    invoke(2500,1,\"Bubble\",two,\"quest.DDCH3.xelorium.sramAttack.2\")\r\n    invoke(4000,1,\"Bubble\",three,\"quest.DDCH3.xelorium.sramAttack.3\")\r\n    \r\n    invoke(6000,1,\"Camera.attachCameraToMobile\",playerId)\nend\n\n-- [COMBAT] Combat contre les Srams - Lancement du Combat\n-- \nfunction event_1844_14935(fightStarted)\n    fightStartedval = toLong(fightStarted)\r\n    --trace(\"value of fightStarted on Fight starting :::::\", fightStartedval)\r\nend\n\n-- [COMBAT] Lancement du combat\n-- \nfunction event_1844_14936()\n    \nend\n\n-- [COMBAT] Combat contre les Srams - Arrivée de l'Explorancienne\n-- \nfunction event_1844_14940()\n    UI.loadTutorialDialog(\"tutoXelorEmbush\",\"tuto.xelor.embush.title\",\"tuto.xelor.embush.description\")\nend\n\n-- [COMBAT] Combat contre les Srams - Fuite\n-- \nfunction event_1844_15440(fightStarted)\n    fightStartedval = toLong(fightStarted)\r\n    --trace(\"value of fightStarted on Fight starting :::::\", fightStartedval)\r\nend\n\n-- [COMBAT] Fin - TP\n-- \nfunction event_1844_15522()\n    UI.unloadTutorialDialog()\nend\n\n-- [DIAL] Le joueur parle à Pandora\n-- \nfunction event_1844_15526(PandoraId)\n    pandora = toLong(PandoraId)\r\n    \r\n    Bubble(pandora,\"quest.DDCH3.xelorium.embuscade.pandora.1\")\nend\n\n-- [DIAL] Le joueur parle à Chad\n-- \nfunction event_1844_15527(SramId)\n    chad = toLong(SramId)\r\n    \r\n    Bubble(chad,\"quest.DDCH3.xelorium.embuscade.chad.1\")\nend\n\n","functions":["startCine","endCine","Bubble","event_1844_14922","event_1844_14923","event_1844_14934","event_1844_14935","event_1844_14936","event_1844_14940","event_1844_15440","event_1844_15522","event_1844_15526","event_1844_15527"],"quest_calls":[],"dialogue_calls":[]},"scenario/1846.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\nplayerId = Context.getPlayer()\r\n\r\nfunction startCine()\r\n\tzoomFactor = Camera.getZoomFactor()\r\n\tUI.manageFrame(\"World\",false) \t\t\t\t\t\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\t\t\t\t\t\t\t\t\t\t\t\t\r\n\tUI.manageFrame(\"World\",false) \t\t\t\t\t\r\n\tUI.setUIVisible(false)\t\r\n\tUI.displayWideScreenBand(true)\r\nend\r\n\r\nfunction endCine()\r\n\tCamera.attachCameraToMobile(playerId)\r\n\tUI.displayWideScreenBand(false)\r\n\tCamera.setUserZoomLocked(false)\t\t\t\t\t\t\t\t\t\t\t\t\r\n\tUI.setUIVisible(true)\t\r\n\tUI.manageFrame(\"World\",true) \t\t\t\t\r\n\tCamera.setZoomFactor(zoomFactor)\t\r\nend\r\n\r\nfunction Bubble(mob,text)\r\n\tBubbleText.closeBubbleAttachedTo(mob)\r\n\tBubbleText.showText(mob, text, 0, 40, false)\r\nend\r\n\r\n-- les fonctions où on cache\r\nfunction hideMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, false)\r\nend\r\n\r\n-- les fonctions où on rend visible (à nouveau\r\nfunction showMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, true)\r\nend\r\n\n\n-- [INIT] Variables\n-- \nfunction event_1846_14941()\n    \nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_1846_14942(PandoraNuitId)\n    pandora = toLong(PandoraNuitId)\r\n    \r\n    Mobile.setMobileAnimation(pandora, \"AnimComp-Evanouie\")\nend\n\n-- [CINE] entrée dans l'instance\n-- \nfunction event_1846_15528(SramJourId, PandoraJourId, ExploJourId)\n    function animChute()\r\n    \tMobile.setMobileVisible(playerId, true)\r\n    \tMobile.setMobileDirection(playerId, 5)\r\n    \tMobile.setMobileAnimation(playerId, \"AnimIncarnam-Chute-Fin\")\r\n    end\r\n    \r\n    function chadTalk()\r\n    \tBubble(chad,\"quest.DDCH3.xelorium.planque.chad.0\")\r\n     \tinvoke(2000,1,\"Mobile.setMobileAnimation\",chad,\"AnimKO-SortieOK\")\r\n    end\r\n    \r\n    function pandoraTalk()\r\n    \tBubble(pandora,\"quest.DDCH3.xelorium.planque.pandora.0\")\r\n    --\tMobile.setMobileAnimation(pandora,\"AnimKO-SortieOK\")\r\n    end\r\n    \r\n    function exploTalk()\r\n    --\tMobile.setMobileAnimation(explo,\"AnimKO-SortieOK\")\r\n    \tinvoke(4000,1,\"Bubble\",explo,\"quest.DDCH3.xelorium.planque.explo.0\")\r\n    end\r\n    \r\n    startCine()\r\n    \r\n    pandora = toLong(PandoraJourId)\r\n    chad = toLong(SramJourId)\r\n    explo = toLong(ExploJourId)\r\n    \r\n    Mobile.setMobileVisible(playerId,false)\r\n    Mobile.setMobileAnimation(chad,\"AnimKO-Boucle\")\r\n    --Mobile.setMobileAnimation(pandora,\"AnimKO-Boucle\")\r\n    --Mobile.setMobileAnimation(explo,\"AnimKO-Boucle\")\r\n    \r\n    invoke(5500,1,\"animChute\")\r\n    invoke(2000,1,\"chadTalk\")\r\n    invoke(3500,1,\"pandoraTalk\")\r\n    invoke(3000,1,\"exploTalk\")\r\n    \r\nend\n\n-- [CINE] entrée dans l'instance - Fin\n-- \nfunction event_1846_15529()\n    endCine()\nend\n\n-- [INIT] ENTER_INSTANCE - On masque le PNJ Pandora s'il a sauvé Chad\n-- \nfunction event_1846_19894(PandoraJourId)\n    Mobile.addMobileCreationCallback(PandoraJourId, \"hideMonster\", PandoraJourId)\nend\n\n-- [INIT] ENTER_INSTANCE - On masque le PNJ Chad s'il a sauvé Pandora\n-- \nfunction event_1846_19895(SramJourId)\n    Mobile.addMobileCreationCallback(SramJourId, \"hideMonster\", SramJourId)\nend\n\n-- [ACTION] Utilisation du lit\n-- \nfunction event_1846_15441(ExploNuitId)\n    explo = toLong(ExploNuitId)\r\n    \r\n    Bubble(chad,\"quest.DDCH3.xelorium.reveilplanque.explo.0\")\nend\n\n-- [COMBAT] Lancement du combat 1\n-- \nfunction event_1846_15523()\n    UI.loadTutorialDialog(\"tutoXelorPlanque\",\"tuto.xelor.planque.title\",\"tuto.xelor.planque.description\")\nend\n\n-- [ACTION] Fin premier combat\n-- \nfunction event_1846_15442()\n    \nend\n\n-- [COMBAT] Lancement du combat 1\n-- \nfunction event_1846_15524()\n    \nend\n\n-- [ACTION] Fin deuxième combat\n-- \nfunction event_1846_15443()\n    startCine()\r\n    Camera.setWorldTarget(163, -5, 4)\nend\n\n-- [DIAL] Le joueur parle à Pandora\n-- \nfunction event_1846_15530(PandoraJourId)\n    pandora = toLong(PandoraJourId)\r\n    \r\n    Bubble(pandora,\"quest.DDCH3.xelorium.planque.pandora.1\")\nend\n\n-- [DIAL] Le joueur parle à Chad\n-- \nfunction event_1846_15531(SramJourId)\n    chad = toLong(SramJourId)\r\n    \r\n    Bubble(chad,\"quest.DDCH3.xelorium.planque.chad.1\")\nend\n\n-- [DIAL][NUIT] Le joueur parle à Chad\n-- \nfunction event_1846_15532(SramNuitId)\n    local playerId = Context.getLeaderId()\r\n    local chad = toLong(SramNuitId)\r\n    \r\n    startCinematicContext(1.2, chad)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 15532)\r\n    \r\n    -- \"Chad !? Qu'est-ce que...\"\r\n    invoke_custom(00100, 1, \"bubble\", playerId, \"quest.DDCH3.xelorium.trahison.player.0\")\r\n    invoke_custom(02500, 1, \"clearBubbles\", playerId)\r\n    invoke_custom(00100, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Effrayee\")\r\n    \r\n    -- \"Reste en dehors de ça, j'ai rien cont' toi. J'suis fidèle à Sram c'tout.\"\r\n    invoke_custom(03000, 1, \"bubble\", chad, \"quest.DDCH3.xelorium.trahison.chad.0\")\r\n    invoke_custom(06500, 1, \"clearBubbles\", chad)\r\n    \r\n    -- \"Je ne te laisserai pas emmener Pandora !\"\r\n    invoke_custom(07000, 1, \"bubble\", playerId, \"quest.DDCH3.xelorium.trahison.player.1\")\r\n    invoke_custom(07000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Colere\")\r\n    invoke_custom(10000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Dommage... J'commençais à bien t'aimer...\"\r\n    invoke_custom(10500, 1, \"bubble\", chad, \"quest.DDCH3.xelorium.trahison.chad.1\")\r\n    invoke_custom(13500, 1, \"clearBubbles\", chad)\r\n    \r\n    invoke_custom(14000, 1, \"skipCinematic\", 15532)\nend\n\n-- [DIAL][NUIT] Le joueur parle à Chad - déclenche le combat\n-- \nfunction event_1846_15533()\n    \nend\n\n-- [CINE] Fin combat 2 - Fuite de Chad\n-- \nfunction event_1846_15534(ChadNuitId, PandoraNuitId, ExploNuitId)\n    function fuite()\r\n    \tMobile.setMobileAnimation(pandora, \"AnimComp-Disparition\")\r\n    \tMobile.setMobileAnimation(chad, \"AnimSort-01-Debut\")\r\n    \t\r\n    \r\n    end\r\n    \r\n    function exploRun()\r\n    \tMobile.moveMobile(explo, 163, -7, 0)\r\n    \tinvoke(500,1,\"Bubble\",explo,\"quest.DDCH3.xelorium.fuiteplanque.explo.0\")\r\n    end\r\n    \r\n    pandora = toLong(PandoraNuitId)\r\n    chad = toLong(ChadNuitId)\r\n    explo = toLong(ExploNuitId)\r\n    \r\n    Bubble(chad,\"quest.DDCH3.xelorium.fuiteplanque.chad.0\")\r\n    \r\n    invoke(1500,1,\"exploRun\")\r\n    invoke(2000,1,\"fuite\")\r\n    \r\n    invoke(5000,1,\"endCine\")\nend\n\n-- [CINE] Fin combat 2 - Fuite de Chad - Fin ciné\n-- \nfunction event_1846_15535(ExploNuitId)\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","startCine","endCine","Bubble","hideMonster","showMonster","event_1846_14941","event_1846_14942","event_1846_15528","animChute","chadTalk","pandoraTalk","exploTalk","event_1846_15529","event_1846_19894","event_1846_19895","event_1846_15441","event_1846_15523","event_1846_15442","event_1846_15524","event_1846_15443","event_1846_15530","event_1846_15531","event_1846_15532","event_1846_15533","event_1846_15534","fuite","exploRun","event_1846_15535"],"quest_calls":[],"dialogue_calls":[]},"scenario/1847.lua":{"source":"\n\n-- [EVENT] Initialisation\n-- \nfunction event_1847_14947()\n    \nend\n\n-- [ACTION] Lancement du combat associé\n-- \nfunction event_1847_14948(GroupId, MobA, MobB, MobC, MobD, MobE, MobF, MobG, MobH, FightId, PlayerId)\n    PlayerId = toLong(PlayerId)\r\n    GroupId =toLong(GroupId)\r\n    FightId = toLong(FightId)\r\n    MobA = toLong(MobA)\r\n    MobB = toLong(MobB)\r\n    MobC = toLong(MobC)\r\n    MobD = 