obB, MobC)\n    \nend\n\n","functions":["event_1934_15425","event_1934_15426","event_1934_15427","event_1934_15428","event_1934_15429"],"quest_calls":[],"dialogue_calls":[]},"scenario/1935.lua":{"source":"\n\n-- [EVENT] Initialisation\n-- \nfunction event_1935_15430()\n    \nend\n\n-- [ACTION] Lancement du combat associé\n-- \nfunction event_1935_15431(GroupId, MobA, MobB, MobC, MobD, MobE, MobF, MobG, MobH, FightId, PlayerId)\n    PlayerId = toLong(PlayerId)\r\n    GroupId =toLong(GroupId)\r\n    FightId = toLong(FightId)\r\n    MobA = toLong(MobA)\r\n    MobB = toLong(MobB)\r\n    MobC = toLong(MobC)\r\n    MobD = toLong(MobD)\r\n    MobE = toLong(MobE)\r\n    MobF = toLong(MobF)\r\n    MobG = toLong(MobG)\r\n    MobH = toLong(MobH)\r\n    \r\n    trace(\"===Valeur de Player Id ======\", PlayerId)\r\n    trace(\"===Valeur de Group Id ======\", GroupId)\r\n    trace(\"===Valeur de Fight Id ======\", FightId)\r\n    trace(\"===Valeur de MobA Id ======\", MobA)\r\n    trace(\"===Valeur de MobB Id ======\", MobB)\r\n    trace(\"===Valeur de MobC Id ======\", MobC)\r\n    trace(\"===Valeur de MobD Id ======\", MobD)\r\n    trace(\"===Valeur de MobE Id ======\", MobE)\r\n    trace(\"===Valeur de MobF Id ======\", MobF)\r\n    trace(\"===Valeur de MobG Id ======\", MobG)\r\n    trace(\"===Valeur de MobH Id ======\", MobH)\nend\n\n-- [ACTION] Fin de combat gagnant\n-- \nfunction event_1935_15432(GroupId)\n    \nend\n\n-- [ACTION] Fin de combat gagnant - fin scenario\n-- \nfunction event_1935_15433(GroupId)\n    \nend\n\n-- [ACTION] Fin de combat perdant\n-- \nfunction event_1935_15434(GroupId, MobA, MobB, MobC)\n    \nend\n\n","functions":["event_1935_15430","event_1935_15431","event_1935_15432","event_1935_15433","event_1935_15434"],"quest_calls":[],"dialogue_calls":[]},"scenario/1936.lua":{"source":"\n\n-- [EVENT] Initialisation\n-- \nfunction event_1936_15435()\n    \nend\n\n-- [ACTION] Lancement du combat associé\n-- \nfunction event_1936_15436(GroupId, MobA, MobB, MobC, MobD, MobE, MobF, MobG, MobH, FightId, PlayerId)\n    PlayerId = toLong(PlayerId)\r\n    GroupId =toLong(GroupId)\r\n    FightId = toLong(FightId)\r\n    MobA = toLong(MobA)\r\n    MobB = toLong(MobB)\r\n    MobC = toLong(MobC)\r\n    MobD = toLong(MobD)\r\n    MobE = toLong(MobE)\r\n    MobF = toLong(MobF)\r\n    MobG = toLong(MobG)\r\n    MobH = toLong(MobH)\r\n    \r\n    trace(\"===Valeur de Player Id ======\", PlayerId)\r\n    trace(\"===Valeur de Group Id ======\", GroupId)\r\n    trace(\"===Valeur de Fight Id ======\", FightId)\r\n    trace(\"===Valeur de MobA Id ======\", MobA)\r\n    trace(\"===Valeur de MobB Id ======\", MobB)\r\n    trace(\"===Valeur de MobC Id ======\", MobC)\r\n    trace(\"===Valeur de MobD Id ======\", MobD)\r\n    trace(\"===Valeur de MobE Id ======\", MobE)\r\n    trace(\"===Valeur de MobF Id ======\", MobF)\r\n    trace(\"===Valeur de MobG Id ======\", MobG)\r\n    trace(\"===Valeur de MobH Id ======\", MobH)\nend\n\n-- [ACTION] Fin de combat gagnant\n-- \nfunction event_1936_15437(GroupId)\n    \nend\n\n-- [ACTION] Fin de combat gagnant - fin scenario\n-- \nfunction event_1936_15438(GroupId)\n    \nend\n\n-- [ACTION] Fin de combat perdant\n-- \nfunction event_1936_15439(GroupId, MobA, MobB, MobC)\n    \nend\n\n","functions":["event_1936_15435","event_1936_15436","event_1936_15437","event_1936_15438","event_1936_15439"],"quest_calls":[],"dialogue_calls":[]},"scenario/1937.lua":{"source":"playerId = Context.getPlayer()\r\n\r\nfunction startCine()\r\n\tzoomFactor = Camera.getZoomFactor()\r\n\tUI.manageFrame(\"World\",false) \t\t\t\t\t\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\t\t\t\t\t\t\t\t\t\t\t\t\r\n\tUI.manageFrame(\"World\",false) \t\t\t\t\t\r\n\tUI.setUIVisible(false)\t\r\n\tUI.displayWideScreenBand(true)\r\nend\r\n\r\nfunction endCine()\r\n\tCamera.attachCameraToMobile(playerId)\r\n\tUI.displayWideScreenBand(false)\r\n\tCamera.setUserZoomLocked(false)\t\t\t\t\t\t\t\t\t\t\t\t\r\n\tUI.setUIVisible(true)\t\r\n\tUI.manageFrame(\"World\",true) \t\t\t\t\r\n\tCamera.setZoomFactor(zoomFactor)\t\r\nend\r\n\r\nfunction Bubble(mob,text)\r\n\tBubbleText.closeBubbleAttachedTo(mob)\r\n\tBubbleText.showText(mob, text, 0, 40, false)\r\nend\r\n\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_1937_15445()\n    \nend\n\n-- [EVENT] Lancement Premier Combat - Phase de préparation terminée\n-- \nfunction event_1937_15506()\n    \nend\n\n-- [ACTION] Fin premier combat\n-- \nfunction event_1937_15446()\n    \nend\n\n-- [EVENT] Lancement Deuxième Combat - Phase de préparation terminée\n-- \nfunction event_1937_15507()\n    \nend\n\n-- [ACTION] Fin deuxième combat\n-- \nfunction event_1937_15447()\n    \nend\n\n-- [EVENT] Lancement Troisième Combat - Phase de préparation terminée\n-- \nfunction event_1937_15508()\n    \nend\n\n-- [ACTION] Fin troisième combat\n-- \nfunction event_1937_15448()\n    \nend\n\n","functions":["startCine","endCine","Bubble","event_1937_15445","event_1937_15506","event_1937_15446","event_1937_15507","event_1937_15447","event_1937_15508","event_1937_15448"],"quest_calls":[],"dialogue_calls":[]},"scenario/1938.lua":{"source":"nbFight = 0\r\n\r\nfunction MindBubbleStart(mob,text,tDuration)\r\n\tMindBubble=BubbleText.showText(mob, text, 0, 40, false)\r\n\tinvoke(tDuration,1,\"BubbleText.close\",MindBubble)\r\nend\n\n-- [INITIALISATION] Variables\n-- \nfunction event_1938_15449()\n    \nend\n\n-- [INIT] Le joueur entre dans l'instance\n-- \nfunction event_1938_15450()\n    \nend\n\n-- [EVENT] Lancement Salle 1 - Phase de préparation terminée\n-- \nfunction event_1938_15451()\n    \nend\n\n-- [SALLE 01] Victoire - On déverouille la porte\n-- \nfunction event_1938_15452()\n    \nend\n\n-- [SALLE 01] Victoire - La porte est ouverte\n-- \nfunction event_1938_15453()\n    \nend\n\n-- [EVENT] Lancement Salle 2 - Phase de préparation terminée\n-- \nfunction event_1938_15454()\n    \nend\n\n-- [SALLE 02] Victoire - On déverouille la porte\n-- \nfunction event_1938_15455()\n    \nend\n\n-- [SALLE 02] Victoire - La porte est ouverte\n-- \nfunction event_1938_15456()\n    \nend\n\n-- [EVENT] Lancement Salle 3 - Phase de préparation terminée\n-- \nfunction event_1938_15457()\n    \nend\n\n-- [SALLE 03] Victoire - Validation Quête 2453 + Activation du TP\n-- \nfunction event_1938_15458()\n    \nend\n\n","functions":["MindBubbleStart","event_1938_15449","event_1938_15450","event_1938_15451","event_1938_15452","event_1938_15453","event_1938_15454","event_1938_15455","event_1938_15456","event_1938_15457","event_1938_15458"],"quest_calls":[],"dialogue_calls":[]},"scenario/1939.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\n-- les fonctions où on cache\r\nfunction hideMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, false)\r\nend\n\n-- [INIT] Variables\n-- \nfunction event_1939_15460()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - On enregiste le joueur au Scénario\n-- \nfunction event_1939_15461()\n    \nend\n\n-- [EVENT] Le joueur parle au Sage - Cinématique\n-- \nfunction event_1939_15463(SageXelorId)\n    playerId = Context.getLeaderId()\r\n    SageXelor = toLong(SageXelorId)\r\n    \r\n    startCinematicContext(1.2, playerId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 15463)\r\n    \r\n     -- Il ne va pas falloir que l'on traîne.\r\n    invoke_custom(2000, 1, \"bubble\", SageXelor, \"quest.DDCH4.Sage.1\")\r\n    invoke_custom(3000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(5000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Acquiescer\")\r\n    invoke_custom(7000, 1, \"skipCinematic\", 15463)\nend\n\n-- [EVENT] Fin Cinématique - On valide la quête 2425 ou 2526 et on lance la quête 2427\n-- \nfunction event_1939_15464()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - On masque le PNJ Sage s'il est mort\n-- \nfunction event_1939_15467(SageXelorId)\n    Mobile.addMobileCreationCallback(SageXelorId, \"hideMonster\", SageXelorId)\nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","hideMonster","event_1939_15460","event_1939_15461","event_1939_15463","event_1939_15464","event_1939_15467"],"quest_calls":[],"dialogue_calls":[]},"scenario/1940.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\n-- Boss Chest\r\nparticleBarriereUn = 0\r\nparticleBarriereDeux = 0\r\nparticleBarriereTrois = 0\r\nparticleBarriereQuatre = 0\r\nparticleBouclier = 0\r\n\r\nlocal aps1 = 7926001\r\nlocal aps2 = 7926002\r\nlocal aps3 = 7926003\r\nlocal aps4 = 7926004\r\nlocal aps5 = 7926005\r\nlocal aps6 = 7926006\r\nlocal aps7 = 7926007\r\nlocal aps8 = 7926008\r\nlocal aps9 = 7926009\r\nlocal aps10 = 7926010\r\nlocal aps11 = 7926011\r\n\r\nparticleBossKeyChest = {dir1 = 7926008, dir3 = 7926009, dir5 = 7926010, dir7 = 7926011, shield = 7926007}\r\n\r\nfunction refreshBossChestParticles(verrou)\r\n\tlocal lock = toLong(verrou)\r\n\r\n\tif lock >= 1 then\r\n\t\tparticleBarriereUn = addFarParticle(particleBossKeyChest.dir7, 0, -91, -22)\r\n\t\tparticleBouclier = addFarParticle(particleBossKeyChest.shield, 0, -88, -22)\r\n\tend\r\n\tif lock >= 2 then\tparticleBarriereDeux = addFarParticle(particleBossKeyChest.dir1, 3, -88, -22) end\r\n\tif lock >= 3 then\tparticleBarriereTrois = addFarParticle(particleBossKeyChest.dir3, 0, -85, -22)\tend\r\n\tif lock >= 4 then\tparticleBarriereQuatre = addFarParticle(particleBossKeyChest.dir5, -3, -88, -22) end\r\n\t\r\n\treturn true\r\nend\r\n\r\n-- Lasers\r\nparticleJauneA = 0\r\nparticleJauneB = 0\r\nparticleJauneC = 0\r\nparticleBleuA = 0\r\nparticleBleuB = 0\r\nparticleBleuC = 0\r\nparticleRougeA = 0\r\nparticleRougeB = 0\r\nparticleRougeC = 0\r\n\r\n\r\n\r\nparticleLaser = {yellow = {dir5 = 7926003, dir7 = 7926004}, blue = {dir5 = 7926001, dir7 = 7926002}, red = {dir5 = 7926005, dir7 = 7926006}}\r\n\r\nfunction refreshLaserParticles(jaune, bleu, rouge)\r\n\tif (jaune ~= nil) then\r\n\t\tlocal jaune = toLong(jaune)\r\n\t\r\n\t\tif (particleJauneA > 0) then Particle.removeParticleSystem(particleJauneA) end\r\n\t\tif (particleJauneB > 0) then Particle.removeParticleSystem(particleJauneB) end\r\n\t\tif (particleJauneC > 0) then Particle.removeParticleSystem(particleJauneC) end\r\n\r\n\t\tif (jaune == -1) then\r\n\t\t\tparticleJauneA = addFarParticle(particleLaser.yellow.dir7, -24, -86, -24)\r\n\t\t\tparticleJauneC = addFarParticle(particleLaser.yellow.dir5, 87, -70, 0)\r\n\t\telseif (jaune == 1) then\r\n\t\t\tparticleJauneB = addFarParticle(particleLaser.yellow.dir5, 127, -72, 0)\r\n\t\tend\r\n\tend\t\r\n\t\r\n\tif (bleu ~= nil) then\r\n\t\tlocal bleu = toLong(bleu)\r\n\t\t\r\n\t\tif (particleBleuA > 0) then Particle.removeParticleSystem(particleBleuA) end\r\n\t\tif (particleBleuB > 0) then Particle.removeParticleSystem(particleBleuB) end\r\n\t\tif (particleBleuC > 0) then Particle.removeParticleSystem(particleBleuC) end\r\n\r\n\t\tif (bleu == -1) then\r\n\t\t\tparticleBleuA = addFarParticle(particleLaser.blue.dir7, -4, -46, -24)\r\n\t\t\tparticleBleuC = addFarParticle(particleLaser.blue.dir5, 87, -69, 0)\r\n\t\telseif (bleu == 1) then\r\n\t\t\tparticleBleuB = addFarParticle(particleLaser.blue.dir7, 121, -35, 0)\r\n\t\tend\r\n\tend\r\n\t\r\n\tif (rouge ~= nil) then\r\n\t\tlocal rouge = toLong(rouge)\r\n\t\t\r\n\t\tif (particleRougeA > 0) then Particle.removeParticleSystem(particleRougeA) end\r\n\t\tif (particleRougeB > 0) then Particle.removeParticleSystem(particleRougeB) end\r\n\t\tif (particleRougeC > 0) then Particle.removeParticleSystem(particleRougeC) end\r\n\r\n\t\tif (rouge == -1) then\r\n\t\t\tparticleRougeB = addFarParticle(particleLaser.red.dir5, 145, -48, 0)\r\n\t\telseif (rouge == 1) then\r\n\t\t\tparticleRougeA = addFarParticle(particleLaser.red.dir7, 5, -87, -24)\r\n\t\t\tparticleRougeC = addFarParticle(particleLaser.red.dir5, 87, -68, 0)\r\n\t\tend\r\n\tend\r\n\t\r\n\treturn true\r\nend\r\n\r\nfunction addFarParticle(particleId, x , y , z) \r\n\tlocal systemId = Particle.addParticleSystem(particleId, x , y , z)\r\n\tParticle.setRemoveWhenFar(systemId, false)\r\n\treturn systemId\r\nend\n\n-- [INIT] Variables\n-- \nfunction event_1940_15469()\n    \nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_1940_15470(verrou, jaune, bleu, rouge)\n    refreshBossChestParticles(verrou)\r\n    refreshLaserParticles(jaune, bleu, rouge)\nend\n\n-- [LASER] Le joueur utilise le Jaune - Etat 1\n-- \nfunction event_1940_15472()\n    \nend\n\n-- [LASER] Le joueur utilise le Jaune - Etat -1\n-- \nfunction event_1940_15473()\n    \nend\n\n-- [LASER] Le joueur utilise le Jaune - Update variable d'état\n-- \nfunction event_1940_20357()\n    \nend\n\n-- [LASER] Le joueur utilise le Bleu - Etat 1\n-- \nfunction event_1940_15475()\n    \nend\n\n-- [LASER] Le joueur utilise le Bleu - Etat -1\n-- \nfunction event_1940_15476()\n    \nend\n\n-- [LASER] Le joueur utilise le Bleu - Update variable d'état\n-- \nfunction event_1940_20358()\n    \nend\n\n-- [LASER] Le joueur utilise le Rouge - Etat 1\n-- \nfunction event_1940_15478()\n    \nend\n\n-- [LASER] Le joueur utilise le Rouge - Etat -1\n-- \nfunction event_1940_15479()\n    \nend\n\n-- [LASER] Le joueur utilise le Rouge - Update variable d'état\n-- \nfunction event_1940_20359()\n    \nend\n\n-- [LASERS] Le joueur utilise un des Lasers - Update des APS\n-- \nfunction event_1940_15480(jaune, bleu, rouge)\n    refreshLaserParticles(jaune, bleu, rouge)\nend\n\n-- [CLE][PRESENT] Obtention de la Clef\n-- \nfunction event_1940_15481()\n    local playerId = Context.getLeaderId()\r\n    Mobile.setMobileAnimation(playerId, \"AnimEmote-Victoire\")\nend\n\n-- [CLE][PASSE] Obtention de la Clef\n-- \nfunction event_1940_15482()\n    local playerId = Context.getLeaderId()\r\n    Mobile.setMobileAnimation(playerId, \"AnimEmote-Victoire\")\nend\n\n-- [CLE][BOSS] Obtention de la Clef du Boss\n-- \nfunction event_1940_15483()\n    local playerId = Context.getLeaderId()\r\n    Mobile.setMobileAnimation(playerId, \"AnimEmote-Victoire\")\nend\n\n-- [PORTE][PRESENT] Ouverture de la porte\n-- \nfunction event_1940_15484()\n    \nend\n\n-- [PORTE][PASSE] Ouverture de la porte\n-- \nfunction event_1940_15485()\n    \nend\n\n-- [PORTE][BOSS] Ouverture de la porte du Boss\n-- \nfunction event_1940_15486()\n    \nend\n\n-- [VERROU] Le joueur utilise le Système de Sécurité 1\n-- \nfunction event_1940_15487(verrou)\n    Particle.removeParticleSystem(particleBarriereQuatre)\r\n    \r\n    if (toLong(verrou) <= 0) then\r\n    \tParticle.removeParticleSystem(particleBouclier)\r\n    end\nend\n\n-- [VERROU] Le joueur utilise le Système de Sécurité 2 - Lancement combat\n-- \nfunction event_1940_15488()\n    \nend\n\n-- [VERROU] Victoire combat Système de Sécurité 2\n-- \nfunction event_1940_20360(verrou)\n    Particle.removeParticleSystem(particleBarriereTrois)\r\n    \r\n    if (toLong(verrou) <= 0) then\r\n    \tParticle.removeParticleSystem(particleBouclier)\r\n    end\nend\n\n-- [VERROU] Notif Validation Système de Sécurité 2\n-- \nfunction event_1940_15491()\n    \nend\n\n-- [VERROU] Le joueur utilise le Système de Sécurité 3\n-- \nfunction event_1940_15489(verrou)\n    Particle.removeParticleSystem(particleBarriereDeux)\r\n    \r\n    if (toLong(verrou) <= 0) then\r\n    \tParticle.removeParticleSystem(particleBouclier)\r\n    end\nend\n\n-- [VERROU] Le joueur utilise le Système de Sécurité 4 - Lancement combat\n-- \nfunction event_1940_15490()\n    \nend\n\n-- [VERROU] Victoire combat Système de Sécurité 4\n-- \nfunction event_1940_20361(verrou)\n    Particle.removeParticleSystem(particleBarriereUn)\r\n    \r\n    if (toLong(verrou) <= 0) then\r\n    \tParticle.removeParticleSystem(particleBouclier)\r\n    end\nend\n\n-- [VERROU] Notif Validation Système de Sécurité 4\n-- \nfunction event_1940_15492()\n    \nend\n\n-- [EVENT] Victoire combat BOSS - Rend utilisable la Boîte Divine (Connaissance Divine)\n-- \nfunction event_1940_15514()\n    \nend\n\n-- [EVENT] Le joueur utilise la Boîte Divine - TP hors du temple\n-- \nfunction event_1940_15515()\n    \nend\n\n-- [COMBAT] Combat 1 - Victoire\n-- \nfunction event_1940_15518()\n    \nend\n\n-- [COMBAT] Combat 2 - Victoire\n-- \nfunction event_1940_15519()\n    \nend\n\n-- [COMBAT] Combat 1 et 2 - Victoires\n-- \nfunction event_1940_15520()\n    \nend\n\n-- [COMBAT] Phase de Préparation Combat 1\n-- \nfunction event_1940_15558()\n    \nend\n\n-- [COMBAT] Phase de Préparation Combat 2\n-- \nfunction event_1940_15628()\n    \nend\n\n-- [COMBAT] Phase de Préparation Combat 3\n-- \nfunction event_1940_15629()\n    \nend\n\n-- [COMBAT] Phase de Préparation Combat 4\n-- \nfunction event_1940_15630()\n    \nend\n\n-- [COMBAT] Phase de Préparation Combat 5\n-- \nfunction event_1940_15631()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","refreshBossChestParticles","refreshLaserParticles","addFarParticle","event_1940_15469","event_1940_15470","event_1940_15472","event_1940_15473","event_1940_20357","event_1940_15475","event_1940_15476","event_1940_20358","event_1940_15478","event_1940_15479","event_1940_20359","event_1940_15480","event_1940_15481","event_1940_15482","event_1940_15483","event_1940_15484","event_1940_15485","event_1940_15486","event_1940_15487","event_1940_15488","event_1940_20360","event_1940_15491","event_1940_15489","event_1940_15490","event_1940_20361","event_1940_15492","event_1940_15514","event_1940_15515","event_1940_15518","event_1940_15519","event_1940_15520","event_1940_15558","event_1940_15628","event_1940_15629","event_1940_15630","event_1940_15631"],"quest_calls":[],"dialogue_calls":[]},"scenario/1941.lua":{"source":"\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_1941_15493()\n    \nend\n\n-- (COMBAT) Victoire salle 01\n-- \nfunction event_1941_15494()\n    \nend\n\n-- (COMBAT) Victoire salle 02\n-- \nfunction event_1941_15495()\n    \nend\n\n-- (COMBAT) Victoire salle 03\n-- \nfunction event_1941_15496()\n    \nend\n\n","functions":["event_1941_15493","event_1941_15494","event_1941_15495","event_1941_15496"],"quest_calls":[],"dialogue_calls":[]},"scenario/1943.lua":{"source":"playerId = Context.getPlayer()\r\nsage = Mobile.generateClientMobileId()\r\n\r\nfunction startCine()\r\n\tzoomFactor = Camera.getZoomFactor()\r\n\tUI.manageFrame(\"World\",false) \t\t\t\t\t\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\t\t\t\t\t\t\t\t\t\t\t\t\r\n\tUI.manageFrame(\"World\",false) \t\t\t\t\t\r\n\tUI.setUIVisible(false)\t\r\n\tUI.displayWideScreenBand(true)\r\nend\r\n\r\nfunction endCine()\r\n\tCamera.attachCameraToMobile(playerId)\r\n\tUI.displayWideScreenBand(false)\r\n\tCamera.setUserZoomLocked(false)\t\t\t\t\t\t\t\t\t\t\t\t\r\n\tUI.setUIVisible(true)\t\r\n\tUI.manageFrame(\"World\",true) \t\t\t\t\r\n\tCamera.setZoomFactor(zoomFactor)\t\r\nend\r\n\r\nfunction Bubble(mob,text)\r\n\tBubbleText.closeBubbleAttachedTo(mob)\r\n\tBubbleText.showText(mob, text, 0, 40, false)\r\nend\n\n-- [INITIALISATION] Variables\n-- \nfunction event_1943_15509()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_1943_15510()\n    playerId = Context.getPlayer()\nend\n\n-- [ACTION] Sauvetage de Pandora\n-- \nfunction event_1943_15511(EminenceId, ChadId)\n    function killChad()\r\n    \tMobile.setMobilePosition(eminence, -18,-20,-25)\r\n    \tMobile.setMobileDirection(eminence,3)\r\n    \tMobile.setMobileAnimation(eminence,\"AnimApparition\")\r\n    \tinvoke(1500,1,\"Mobile.setMobileAnimation\",eminence,\"AnimSort-Eliminination\")\r\n    \tinvoke(2500,1,\"Particle.addParticleSystem\",800532, -18,-19,-25)\r\n    \tinvoke(2500,1,\"Mobile.setMobileAnimation\",chad,\"AnimMort\")\r\n    \tinvoke(3500,1,\"Mobile.setMobileAnimation\",eminence,\"AnimDisparition\")\r\n    \tinvoke(5000,1,\"returnToPosition\")\r\n    end\r\n    \r\n    function returnToPosition()\r\n    \tCamera.setWorldTarget(-23,-14,-17)\r\n    \tMobile.setMobilePosition(eminence, -23,-14,-17)\r\n    \tMobile.setMobileDirection(eminence,1)\r\n    \tMobile.setMobileAnimation(eminence,\"AnimApparition\")\r\n    end\r\n    \r\n    eminence = toLong(EminenceId)\r\n    chad = toLong(ChadId)\r\n    \r\n    startCine()\r\n    \r\n    Mobile.setMobileAnimation(eminence,\"AnimDisparition\")\r\n    \r\n    invoke(1500,1,\"killChad\")\r\nend\n\n-- [ACTION] Sauvetage de Chad\n-- \nfunction event_1943_15512(EminenceId, PandoraId)\n    function killChad()\r\n    \tMobile.setMobilePosition(eminence, -20,-15,-25)\r\n    \tMobile.setMobileDirection(eminence,3)\r\n    \tMobile.setMobileAnimation(eminence,\"AnimApparition\")\r\n    \tinvoke(1500,1,\"Mobile.setMobileAnimation\",eminence,\"AnimSort-Eliminination\")\r\n    \tinvoke(2500,1,\"Particle.addParticleSystem\",800532, -20,-14,-25)\r\n    \tinvoke(2500,1,\"Mobile.setMobileAnimation\",pandora,\"AnimComp-Disparition\")\r\n    \tinvoke(3500,1,\"Mobile.setMobileAnimation\",eminence,\"AnimDisparition\")\r\n    \tinvoke(5000,1,\"returnToPosition\")\r\n    end\r\n    \r\n    function returnToPosition()\r\n    \tCamera.setWorldTarget(-23,-14,-17)\r\n    \tMobile.setMobilePosition(eminence, -23,-14,-17)\r\n    \tMobile.setMobileDirection(eminence,1)\r\n    \tMobile.setMobileAnimation(eminence,\"AnimApparition\")\r\n    end\r\n    \r\n    eminence = toLong(EminenceId)\r\n    pandora = toLong(PandoraId)\r\n    \r\n    startCine()\r\n    \r\n    Mobile.setMobileAnimation(eminence,\"AnimDisparition\")\r\n    \r\n    invoke(1500,1,\"killChad\")\r\nend\n\n-- [ACTION] Validation QP\n-- \nfunction event_1943_15517()\n    \nend\n\n-- [CINE] Entrée dans l'instance\n-- \nfunction event_1943_15536(PandoraId)\n    startCine()\r\n    \r\n    pandora = toLong(PandoraId) \r\n    Mobile.setMobileAnimation(pandora, \"AnimComp-Evanouie\")\r\n    \r\n    Actor.createActor(sage, 163503509, -19,-16,-25)\r\n    Mobile.setMobileDirection(sage,3)\r\n    Camera.setWorldTarget(-19,-16,-25)\r\n    Bubble(sage,\"quest.DDCH4.xelorium.affrontement.sage.0\")\nend\n\n-- [CINE] Apparition Eminence + Chad\n-- \nfunction event_1943_15537(PandoraId, ChadId, EminenceId)\n    function chadApparition()\r\n    \tMobile.setMobileAnimation(chad, \"AnimApparition\")\r\n    end\r\n    \r\n    function eminenceApparition()\t\r\n    \tBubbleText.closeBubbleAttachedTo(sage)\r\n    \tMobile.setMobileAnimation(eminence, \"AnimApparition\")\r\n    end\r\n    \r\n    function eminenceKillSage()\r\n    \tMobile.setMobileAnimation(eminence, \"AnimSort-Eliminination\")\r\n    \tParticle.addParticleSystem(800533, -19,-16,-25)\r\n    \tinvoke(800,1,\"Particle.addParticleSystem\",800534, -19,-16,-25)\r\n    \tinvoke(1000,1,\"Mobile.setMobileAnimation\",sage,\"AnimMort\")\r\n    \tinvoke(5000,1,\"eminenceSpeach\")\r\n    end\r\n    \r\n    function eminenceSpeach()\r\n    \tMobile.setMobileDirection(eminence,1)\r\n    \tinvoke(200,1,\"Bubble\",eminence,\"quest.DDCH4.xelorium.affrontement.eminence.0\")\r\n    \tinvoke(3500,1,\"Bubble\",chad,\"quest.DDCH4.xelorium.affrontement.chad.0\")\r\n    \tinvoke(7000,1,\"Bubble\",eminence,\"quest.DDCH4.xelorium.affrontement.eminence.1\")\r\n    \tinvoke(10500,1,\"Bubble\",chad,\"quest.DDCH4.xelorium.affrontement.chad.1\")\r\n    \tinvoke(14000,1,\"chadAttack\")\r\n    end\r\n    \r\n    function chadAttack()\r\n    \tMobile.setMobileAnimation(chad,\"AnimSort-03\")\r\n    \tinvoke(750,1,\"Particle.addParticleSystem\",-1593043430, -19,-17,-25)\r\n    \tinvoke(750,1,\"Mobile.setMobileAnimation\",eminence, \"AnimKO-Debut\")\r\n    \tinvoke(3000,1,\"Mobile.setMobileAnimation\",eminence,\"AnimKO-Fin\")\t\r\n    \tinvoke(5000,1,\"Mobile.setMobileAnimation\",eminence,\"AnimComp-Rire\")\r\n    \tinvoke(7000,1,\"Bubble\",eminence,\"quest.DDCH4.xelorium.affrontement.eminence.2\")\r\n    \tinvoke(10500,1,\"Bubble\",chad,\"quest.DDCH4.xelorium.affrontement.chad.2\")\r\n    \tinvoke(14000,1,\"Bubble\",eminence,\"quest.DDCH4.xelorium.affrontement.eminence.3\")\r\n    \tinvoke(17500,1,\"eminenceCounterAttack\")\r\n    end\r\n    \r\n    function eminenceCounterAttack()\r\n    \tMobile.setMobileAnimation(eminence,\"AnimComp-Menacer\")\r\n    \tinvoke(750,1,\"Mobile.setMobileAnimation\",chad,\"AnimKO-Debut\")\r\n    \tinvoke(2000,1,\"eminenceChoice\")\r\n    end\r\n    \r\n    function eminenceChoice()\r\n    \tBubble(eminence,\"quest.DDCH4.xelorium.affrontement.eminence.4\")\r\n    \tinvoke(3500,1,\"Bubble\",eminence,\"quest.DDCH4.xelorium.affrontement.eminence.5\")\r\n    \tinvoke(7000,1,\"Bubble\",eminence,\"quest.DDCH4.xelorium.affrontement.eminence.6\")\r\n    \tinvoke(10000,1,\"endCine\")\r\n    end\r\n    \r\n    pandora = toLong(PandoraId)\r\n    eminence = toLong(EminenceId)\r\n    chad = toLong(ChadId)\r\n    \r\n    chadApparition()\r\n    eminenceApparition()\r\n    invoke(6000,1,\"eminenceKillSage\")\nend\n\n-- [ACTION] Parler à Pandora\n-- \nfunction event_1943_15559(PandoraId)\n    pandora = toLong(PandoraId)\r\n    \r\n    Bubble(pandora,\"quest.DDCH4.xelorium.affrontement.pandora.0\")\nend\n\n-- [ACTION] Parler à Chad\n-- \nfunction event_1943_15560(ChadId)\n    chad = toLong(ChadId)\r\n    \r\n    Bubble(chad,\"quest.DDCH4.xelorium.affrontement.chad.3\")\nend\n\n-- [ACTION] Attaquer Sram\n-- \nfunction event_1943_15561(EminenceId)\n    eminence = toLong(EminenceId)\r\n    \r\n    Mobile.setMobileAnimation(eminence, \"AnimSort-Eliminination\")\r\n    invoke(1000,1,\"Mobile.setMobileAnimation\",playerId,\"AnimKO-Debut\")\r\n    invoke(2000,1,\"Bubble\",eminence,\"quest.DDCH4.xelorium.affrontement.eminence.7\")\nend\n\n-- [CINE] Fin Eminence\n-- \nfunction event_1943_15562(EminenceId)\n    function portalAttack()\r\n    \tParticle.addParticleSystem(800522, -24,-14,-17)\r\n    \tMobile.setMobileAnimation(eminence,\"AnimEvacuation\")\r\n    \tinvoke(3000, 1, \"Mobile.setMobileVisible\", eminence, false)\r\n    \tinvoke(3100,1,\"endCine\")\r\n    end\r\n    \r\n    eminence = toLong(EminenceId)\r\n    \r\n    Particle.addParticleSystem(800528, -24,-14,-17)\r\n    Sound.playSound(420800521001,true,50)\t\r\n    Bubble(eminence,\"quest.DDCH4.xelorium.affrontement.eminence.8\")\r\n    Mobile.setMobileAnimation(eminence,\"AnimComp-Rire\")\r\n    invoke(1500,1,\"portalAttack\")\nend\n\n-- [TUTO] Chad Sauvé\n-- \nfunction event_1943_15563()\n    UI.loadTutorialDialog(\"tuto.DDCH4.Chad\",\"tutorial.ddch4.compagnon.chad.title\",\"tutorial.ddch4.compagnon.chad.description\")\nend\n\n-- [TUTO] Pandora Sauvée\n-- \nfunction event_1943_15564()\n    UI.loadTutorialDialog(\"tuto.DDCH4.Pandora\",\"tutorial.ddch4.compagnon.pandora.title\",\"tutorial.ddch4.compagnon.pandora.description\")\nend\n\n","functions":["startCine","endCine","Bubble","event_1943_15509","event_1943_15510","event_1943_15511","killChad","returnToPosition","event_1943_15512","killChad","returnToPosition","event_1943_15517","event_1943_15536","event_1943_15537","chadApparition","eminenceApparition","eminenceKillSage","eminenceSpeach","chadAttack","eminenceCounterAttack","eminenceChoice","event_1943_15559","event_1943_15560","event_1943_15561","event_1943_15562","portalAttack","event_1943_15563","event_1943_15564"],"quest_calls":[],"dialogue_calls":[]},"scenario/1944.lua":{"source":"m_playerId = Context.getPlayer()\n\n-- Lancement Cinématique\n-- \nfunction event_1944_15525()\n    \nend\n\n","functions":["event_1944_15525"],"quest_calls":[],"dial