tion event_1962_15665(CNoir, playerOne, playerTwo, playerThree, playerFour, playerFive, playerSix, Caisse)\n    --Init\r\n    playerId = Context.getPlayer()\r\n    CNoir = toLong(CNoir)\r\n    caisse= toLong(Caisse)\r\n    playerOneId = toLong(playerOne)\r\n    playerTwoId = toLong(playerTwo)\r\n    playerThreeId = toLong(playerThree)\r\n    playerFourId = toLong(playerFour)\r\n    playerFiveId = toLong(playerFive)\r\n    playerSixId = toLong(playerSix)\r\n    timeintro = 0\r\n    timegloat = 0 \r\n    timeunmout = 0\r\n    timetakepackage = 0\r\n    timeflyaway = 0\r\n    timetotal = 0\r\n    \r\n    -- functions\r\n    \r\n    function artefactaddfx()\r\n    \tparticleSecondDoorA = Particle.addParticleSystem(91004721, 579, -6, 0)\r\n    end\r\n    \r\n    function artefactremovefx()\r\n    \tParticle.removeParticleSystem(particleSecondDoorA)\r\n    end\r\n    \r\n    function CNintro()\r\n    \r\n    \tinvoke(10,1,\"Mobile.setMobileVisible\",CNoir, true)\r\n    \tinvoke(10,1,\"Actor.changeSkin\",CNoir, 101101150)\r\n    \tinvoke(10,1,\"Mobile.setMobileAnimation\",CNoir,\"AnimSort-Laceration-1\")\r\n    \t\r\n    \tinvoke(10,1,\"Mobile.setMobileAnimation\",playerOneId,\"AnimTarget-AllerRetour\")\r\n    \tinvoke(10,1,\"Mobile.setMobileAnimation\",playerTwoId,\"AnimTarget-AllerRetour\")\r\n    \tinvoke(10,1,\"Mobile.setMobileAnimation\",playerThreeId,\"AnimTarget-Retournee\")\r\n    \tinvoke(10,1,\"Mobile.setMobileAnimation\",playerFourId,\"AnimEmote-Effrayee\")\r\n    \tinvoke(10,1,\"Mobile.setMobileAnimation\",playerFiveId,\"AnimEmote-Effrayee\")\r\n    \tinvoke(10,1,\"Mobile.setMobileAnimation\",playerSixId,\"AnimEmote-Effrayee\")\r\n    \tinvoke(500,1,\"Effect.createCameraShakeEffect\",200, 600, 200, 2)\r\n    \t\r\n    \tinvoke(2000,1,\"Mobile.setMobileAnimation\",CNoir,\"AnimSort-Laceration-2\")\r\n    \tinvoke(2500,1,\"Effect.createCameraShakeEffect\",200, 600, 200, 1)\r\n    \t\r\n    \tinvoke(3000,1,\"Mobile.setMobileAnimation\",playerOneId,\"AnimEmote-Effrayee\")\r\n    \tinvoke(3000,1,\"Mobile.setMobileAnimation\",playerTwoId,\"AnimEmote-Effrayee\")\r\n    \tinvoke(3000,1,\"Mobile.setMobileAnimation\",playerThreeId,\"AnimEmote-Effrayee\")\r\n    \tinvoke(3000,1,\"Mobile.setMobileAnimation\",playerFourId,\"AnimTarget-Retournee\")\r\n    \tinvoke(3000,1,\"Mobile.setMobileAnimation\",playerFiveId,\"AnimTarget-Retournee\")\r\n    \tinvoke(3000,1,\"Mobile.setMobileAnimation\",playerSixId,\"AnimTarget-AllerRetour\")\r\n    \t\r\n    \tinvoke(4000,1,\"Mobile.setMobileAnimation\",CNoir,\"AnimSort-Laceration-2\")\r\n    \tinvoke(4500,1,\"Effect.createCameraShakeEffect\",200, 500, 200, 2)\r\n    \t\r\n    \t--AnimTarget-AllerRetour\r\n    \t--AnimTarget-Retournee\r\n    \t--AnimTarget-Uppercut + AnimIncarnam-Chute-Fin\r\n    \t-- AnimEmote-Genoux-Boucle\r\n    \tinvoke(5000,1,\"Mobile.setMobileAnimation\",playerOneId,\"AnimTarget-AllerRetour\")\r\n    \tinvoke(4100,1,\"Mobile.setMobileAnimation\",playerTwoId,\"AnimTarget-Uppercut\")\r\n    \tinvoke(4500,1,\"Mobile.setMobileAnimation\",playerThreeId,\"AnimTarget-Uppercut\")\r\n    \tinvoke(5200,1,\"Mobile.setMobileAnimation\",playerFourId,\"AnimTarget-AllerRetour\")\r\n    \tinvoke(5000,1,\"Mobile.setMobileAnimation\",playerFiveId,\"AnimTarget-Retournee\")\r\n    \tinvoke(4250,1,\"Mobile.setMobileAnimation\",playerSixId,\"AnimTarget-Uppercut\")\r\n    \t\r\n    \tinvoke(6100,1,\"Mobile.setMobileAnimation\",playerTwoId,\"AnimIncarnam-Chute-Fin\")\r\n    \tinvoke(6500,1,\"Mobile.setMobileAnimation\",playerThreeId,\"AnimIncarnam-Chute-Fin\")\r\n    \tinvoke(6250,1,\"Mobile.setMobileAnimation\",playerSixId,\"AnimIncarnam-Chute-Fin\")\r\n    \t\r\n    \tinvoke(6680,1,\"Mobile.setMobileAnimation\",playerOneId,\"AnimEmote-Genoux-Debut\")\r\n    \tinvoke(8580,1,\"Mobile.setMobileAnimation\",playerTwoId,\"AnimEmote-Genoux-Debut\")\r\n    \tinvoke(8980,1,\"Mobile.setMobileAnimation\",playerThreeId,\"AnimEmote-Genoux-Debut\")\r\n    \tinvoke(6880,1,\"Mobile.setMobileAnimation\",playerFourId,\"AnimEmote-Genoux-Debut\")\r\n    \tinvoke(7280,1,\"Mobile.setMobileAnimation\",playerFiveId,\"AnimEmote-Genoux-Debut\")\r\n    \tinvoke(8730,1,\"Mobile.setMobileAnimation\",playerSixId,\"AnimEmote-Genoux-Debut\")\r\n    \t\r\n    \r\n    \t\r\n    \tinvoke(6000,1,\"Mobile.setMobilePosition\",CNoir, 573,0,0)\r\n    \tinvoke(6000,1,\"Mobile.setMobileAnimation\",CNoir,\"AnimSort-Envol-Fin\")\r\n    \tinvoke(6500,1,\"Camera.attachCameraToMobile\",CNoir)\r\n    \tinvoke(6000,1,\"Actor.setActorHeight\",CNoir, 15)\r\n    \tinvoke(7000,1,\"Bubble\",CNoir, \"kelba.quest.convoicn.01\")\r\n    \tinvoke(10000,1,\"CNgloat\")\r\n    \ttimeintro = 10000\r\n    \ttimetotal = (timetotal + timeintro)\r\n    \ttrace(\"Total time post intro :::::::::::\", timetotal)\r\n    \t\r\n    \r\n    end\r\n    \r\n    function CNgloat()\r\n    \tinvoke(10,1,\"Actor.setActorHeight\",CNoir, 11)\r\n    \tinvoke(10,1,\"Bubble\",CNoir, \"kelba.quest.convoicn.02\")\r\n    \tinvoke(7000,1,\"Bubble\",CNoir, \"kelba.quest.convoicn.03\")\r\n    \tinvoke(11000,1,\"Bubble\",CNoir, \"kelba.quest.convoicn.04\")\r\n    \tinvoke(15000,1,\"Bubble\",CNoir, \"kelba.quest.convoicn.05\")\r\n    \tinvoke(19000,1,\"Bubble\",CNoir, \"kelba.quest.convoicn.06\")\r\n    \tinvoke(23000,1,\"CNunmount\")\r\n    \ttimegloat = 23000\r\n    \ttimetotal = (timetotal + timegloat)\r\n    \ttrace(\"Total time post gloat :::::::::::\", timetotal)\r\n    end\r\n    \r\n    function CNunmount()\r\n    \tMobile.setMobileAnimation(CNoir,\"AnimSort-Envol-Debut\")\r\n    \tinvoke(2000,1,\"Mobile.setMobilePosition\",CNoir, 578,0,0)\r\n    \tinvoke(2000,1,\"Actor.changeSkin\",CNoir, 101101151)\r\n    \tinvoke(2000,1,\"Mobile.setMobileAnimation\",CNoir,\"AnimApparition\")\r\n    \tinvoke(4000,1,\"Bubble\",CNoir, \"kelba.quest.convoicn.07\")\r\n    \tinvoke(6500,1,\"Mobile.setMobileAnimation\",CNoir,\"AnimComp02\")\r\n    \tinvoke(8000,1,\"CNtakepackage\")\r\n    \ttimeunmout = 8000\r\n    \ttimetotal = (timetotal + timeunmout)\r\n    \ttrace(\"Total time post unmount :::::::::::\", timetotal)\r\n    end\r\n    \r\n    function CNtakepackage()\r\n    \tinvoke(10,1,\"Mobile.moveMobile\",CNoir, 579, -5, 0 )\r\n    \tinvoke(1000,1,\"Bubble\",CNoir, \"kelba.quest.convoicn.08\")\r\n    \tinvoke(4000,1,\"Mobile.setMobileAnimation\",CNoir,\"AnimSort-Laceration\")\r\n    \tinvoke(6000,1,\"Mobile.setMobileAnimation\",Caisse,\"AnimMort\")\r\n    \tinvoke(8000,1,\"Mobile.setMobileAnimation\",CNoir,\"AnimMort\")\r\n    \tinvoke(8000,1,\"Bubble\",CNoir, \"kelba.quest.convoicn.09\")\r\n    \tinvoke(8500,1,\"artefactaddfx\")\r\n    \tinvoke(9500,1,\"Mobile.setMobileAnimation\",CNoir,\"AnimComp02\")\t\r\n    \tinvoke(9500,1,\"artefactremovefx\")\r\n    \tinvoke(12000,1,\"CNflyaway\")\r\n    \ttimetakepackage = 12000\r\n    \ttimetotal = (timetotal + timetakepackage)\r\n    \ttrace(\"Total time post package :::::::::::\", timetotal)\r\n    end\r\n    \r\n    function CNflyaway()\r\n    \tinvoke(10,1, \"Mobile.setMobileDirection\", CNoir,3)\r\n    \tinvoke(1000,1,\"Bubble\",CNoir, \"kelba.quest.convoicn.10\")\r\n    \tinvoke(1000,1,\"Mobile.setMobileAnimation\",CNoir,\"AnimComp02\")\t\r\n    \tinvoke(5000,1,\"Mobile.setMobileAnimation\",CNoir,\"AnimSort-Saut\")\t\r\n    \tinvoke(7000,1,\"Actor.changeSkin\",CNoir, 101101150)\r\n    \tinvoke(7000,1,\"Mobile.setMobileAnimation\",CNoir,\"AnimSort-Laceration-2\")\r\n    \tinvoke(9000,1,\"endCine\")\r\n    \ttimeflyaway = 9000\r\n    \ttimetotal = (timetotal + timeflyaway)\r\n    \ttrace(\"Total time post Panty and Stockings - flyawayNOW :::::::::::\", timetotal)\r\n    end\r\n    \r\n     -- Cine script\r\n    Mobile.setMobileVisible(CNoir, false)\r\n     startCine()\r\n    Mobile.setMobileVisible(playerId, true)\r\n    CNintro()\r\n    --invoke(3000,1,\"Bubble\",CNoir, \"kelba.quest.convoicn.02\")\r\n    --91004721\r\n    Mobile.setMobilePosition(Caisse, 579, -6, 0)\r\n    \r\n    Mobile.setMobilePosition(playerOneId, 578, 2, 0)\r\n    Mobile.setMobilePosition(playerTwoId, 578, -3, 0)\r\n    Mobile.setMobilePosition(playerThreeId, 579,3, 0)\r\n    Mobile.setMobilePosition(playerFourId, 580, -2, 0)\r\n    Mobile.setMobilePosition(playerFiveId, 580, 2, 0)\r\n    Mobile.setMobilePosition(playerSixId, 581, 0, 0)\r\n    \r\n     \nend\n\n-- [ACTION] Fin Combat Corbeau Noir\n-- \nfunction event_1962_15703()\n    endCine()\nend\n\n-- [INIT] ENTER_INSTANCE- ciné en cours ou done - Ejection\n-- \nfunction event_1962_15771(cineStartDone)\n    UI.loadTutorialDialog(\"null\",\"quest.running.title\",\"quest.dd.ch1.inglorium.running.desc\")\r\n    \r\n    cineStartDoneVal = toLong(cineStartDone)\r\n    trace(\"value of cineStartDone on cine running when entering Instance :::::\", cineStartDoneVal)\nend\n\n-- [SECU] Ejection de l'instance en cas de combat perdu\n-- \nfunction event_1962_15873()\n    \nend\n\n-- [SECU] Ejection de l'instance en cas de combat perdu\n-- \nfunction event_1962_15874()\n    \nend\n\n","functions":["startCine","endCine","Bubble","event_1962_15695","event_1962_15659","event_1962_15725","artefactaddfx","artefactremovefx","Riktusinit","Riktusintro","Riktusend","event_1962_15660","event_1962_15666","event_1962_15696","event_1962_15663","event_1962_15675","event_1962_15726","artefactaddfx","artefactremovefx","Piafinit","Piafintro","Piafend","event_1962_15661","event_1962_15667","event_1962_15697","event_1962_15664","event_1962_15676","event_1962_15665","artefactaddfx","artefactremovefx","CNintro","CNgloat","CNunmount","CNtakepackage","CNflyaway","event_1962_15703","event_1962_15771","event_1962_15873","event_1962_15874"],"quest_calls":[],"dialogue_calls":[]},"scenario/1963.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\nPortail = 0\n\n-- [INIT] Variables\n-- \nfunction event_1963_15669()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Cinématique Xélor (début)\n-- \nfunction event_1963_15671(cineStartDone, Xelor)\n    Particle.addParticleSystem(7208002, 0, -14, 0)\r\n    \r\n    local playerId = Context.getLeaderId()\r\n    local xelor = toLong(Xelor)\r\n    \r\n    function animChute(playerId)\r\n    \tMobile.setMobileVisible(playerId, true)\r\n    \tMobile.setMobileDirection(playerId, 5)\r\n    \tMobile.setMobileAnimation(playerId, \"AnimIncarnam-Chute-Fin\", \"Mobile.setMobileDirection\", playerId, 1)\r\n    \tEffect.createCameraShakeEffect(200, 600, 200, 2)\r\n    end\r\n    \r\n    function xelorPop(xelor, playerId)\r\n    \tMobile.setMobileVisible(xelor, true)\r\n    \tMobile.setMobileDirection(xelor, 1)\r\n    \tMobile.setMobileAnimation(xelor, \"AnimResurection\", \"Mobile.setMobileDirection\",playerId, 1)\r\n    \tEffect.createCameraShakeEffect(200, 600, 200, 2)\r\n    end\r\n    \r\n    startCinematicContext(1.5, playerId)\r\n    \r\n    invoke(0100,1, \"Mobile.setMobileVisible\",xelor, false)\r\n    invoke(0100,1, \"Mobile.setMobileAnimation\",xelor, \"AnimStatique_0\")\r\n    invoke(0100,1, \"Mobile.setMobileVisible\",playerId, false)\r\n    invoke(0100,1, \"Mobile.setMobilePosition\",playerId,0,0,0)\r\n    \r\n    invok