r\n    invoke(22500,1, \"bubble\",xelor, \"xelorium.end.cine.08\")\r\n    invoke(23500,1, \"Mobile.setMobileAnimation\",playerId,\"AnimEmote-Acquiescer\")\r\n    \r\n    invoke(25500,1,\"bubble\",xelor, \"xelorium.end.cine.09\")\r\n    invoke(28000,1,\"bubble\",xelor, \"xelorium.end.cine.10\")\r\n    invoke(29000,1,\"Mobile.setMobileAnimation\",playerId,\"AnimEmoteMarket-HausseEpaules\")\r\n    \r\n    invoke(32000,1,\"XelorPop\", xelor, playerId)\r\n    invoke(32000,1,\"Sound.playForcedMusic\",210079)\r\n    \r\n    invoke(34000,1,\"Mobile.setMobileAnimation\",playerId,\"AnimEmote-Effrayee\")\r\n    invoke(34000,1,\"Mobile.moveMobile\",xelor, -1, -7, 0 )\r\n    invoke(34000,1,\"bubble\",xelor, \"xelorium.end.cine.11\")\r\n    invoke(36000,1,\"bubble\",xelor, \"xelorium.end.cine.12\")\r\n    invoke(39000,1,\"bubble\",xelor, \"xelorium.end.cine.13\")\r\n    invoke(39500,1,\"Mobile.setMobileAnimation\",xelor,\"AnimEmote-Pointer\")\r\n    invoke(42000,1,\"bubble\",xelor, \"xelorium.end.cine.14\")\r\n    invoke(46000,1,\"bubble\",xelor, \"xelorium.end.cine.15\")\r\n    invoke(50000,1,\"bubble\",xelor, \"xelorium.end.cine.16\")\r\n    invoke(52000,1,\"Mobile.setMobileAnimation\",xelor,\"AnimEmote-Non\")\r\n    invoke(54000,1,\"bubble\",xelor, \"xelorium.end.cine.17\")\r\n    invoke(54000,1,\"setWorldParticleCell\",7085006, 1, -7, 0)\r\n    \r\n    invoke(55000, 1, \"Effect.createCameraShakeEffect\", 200, 1000, 200, 2)\r\n    \r\n    invoke(58000, 1, \"bubble\", xelor, \"xelorium.end.cine.18\")\r\n    \r\n    invoke(60000, 1, \"skipCinematic\")\nend\n\n-- [EVENT] Activation Livre (pendant ciné début)\n-- \nfunction event_1963_15673()\n    \nend\n\n-- [EVENT] Activation Livre par joueur (autorise dialogue Xelor)\n-- \nfunction event_1963_15677()\n    \nend\n\n-- [EVENT] Cinématique Xelor (fin) - script\n-- \nfunction event_1963_15672(cineStartDone, Xelor)\n    local xelor = toLong(Xelor)\r\n    local playerId = Context.getLeaderId()\r\n    \r\n    function DoorBlow(playerId)\r\n    \tinvoke(10,1,\"setWorldParticleCell\",7277001, 0, -14, 0)\r\n    \tinvoke(10,1,\"Effect.createCameraShakeEffect\",100, 500, 100, 1)\r\n    \tinvoke(2100,1,\"setWorldParticleCell\",7085006, 0, -14, 0)\r\n    \tinvoke(2100,1,\"setWorldParticleCell\", 7277001, 0, -14, 0)\r\n    \tinvoke(2100,1,\"Effect.createCameraShakeEffect\", 200, 1000, 200, 2)\r\n    \tinvoke(2500,1,\"Particle.removeParticleSystem\", Portail, true)\r\n    \tinvoke(3000,1,\"setWorldParticleCell\",7277001, 0, -14, 0)\r\n    \tinvoke(3000,1,\"Effect.createCameraShakeEffect\",100, 600, 100, 3)\r\n    \tinvoke(3000,1,\"setWorldParticleCell\",7000030, 0, -13, 0)\r\n    \tinvoke(3000,1,\"setWorldParticleCell\",7087012, 0, -14, 0)\r\n    \tinvoke(5000,1,\"Mobile.moveMobile\",playerId, 0, -13, 0 ,\"EnterDoor\", playerId)\r\n    end\r\n    \r\n    function EnterDoor(playerId)\r\n    \tinvoke(1000,1,\"Mobile.setMobileAnimation\",playerId, \"AnimSort-Portail-Saut-Debut\")\r\n    \tinvoke(3000,1,\"UI.displayWideScreenBand\", true, 100, 1000)\r\n    end\r\n    \r\n    startCinematicContext(1.8, xelor)\r\n    \r\n    invoke(150,1,\"Mobile.moveMobile\",playerId, 0, -7, 0 )\r\n    invoke(2000,1, \"Mobile.setMobileDirection\", playerId,5)\r\n    invoke(500,1,\"bubble\",xelor, \"xelorium.end.cine.bis.01\")\r\n    invoke(1000,1,\"Mobile.setMobileAnimation\",xelor, \"AnimEmote-Calmer\")\r\n    invoke(4500,1,\"bubble\",xelor, \"xelorium.end.cine.bis.02\")\r\n    invoke(5500,1,\"Mobile.setMobileAnimation\",xelor, \"AnimEmote-Pointer\")\r\n    invoke(8500,1,\"bubble\",xelor, \"xelorium.end.cine.bis.03\")\r\n    invoke(12500,1,\"bubble\",xelor, \"xelorium.end.cine.bis.04\")\r\n    invoke(13500,1,\"Mobile.setMobileAnimation\",xelor, \"AnimEmote-Presenter\")\r\n    invoke(16500,1,\"bubble\",xelor, \"xelorium.end.cine.bis.05\")\r\n    \r\n    invoke(20500,1,\"bubble\",xelor, \"xelorium.end.cine.bis.06\")\r\n    invoke(21500,1, \"Mobile.setMobileDirection\", xelor,1)\r\n    invoke(22500,1,\"Mobile.setMobileAnimation\",xelor, \"AnimEmote-Pointer\")\r\n    \r\n    invoke(24500,1,\"bubble\",xelor, \"xelorium.end.cine.bis.07\")\r\n    invoke(28500,1,\"bubble\",xelor, \"xelorium.end.cine.bis.08\")\r\n    invoke(29500,1,\"Mobile.setMobileAnimation\",xelor, \"AnimEmote-BrandirArme2\")\r\n    \r\n    invoke(32500,1,\"bubble\",xelor, \"xelorium.end.cine.bis.09\")\r\n    \r\n    invoke(36500,1,\"Camera.setWorldTarget\", 0, -14, 0, \"DoorBlow\", playerId)\r\n    \r\n    invoke(46500, 1, \"skipCinematic\", 15672)\nend\n\n-- [EVENT] Fin - TP Inglorium\n-- \nfunction event_1963_15797()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_1963_15669","event_1963_15671","animChute","xelorPop","event_1963_15673","event_1963_15677","event_1963_15672","DoorBlow","EnterDoor","event_1963_15797"],"quest_calls":[],"dialogue_calls":[]},"scenario/1966.lua":{"source":"playerId = Context.getLeaderId()\r\n\r\nfunction startCine()\r\n\tzoomFactor = Camera.getZoomFactor()\r\n\tUI.manageFrame(\"World\",false) \t\t\t\t\t\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\t\t\t\t\t\t\t\t\t\t\t\t\r\n\tUI.manageFrame(\"World\",false) \t\t\t\t\t\r\n\tUI.setUIVisible(false)\t\r\n\tUI.displayWideScreenBand(true)\r\n--\tMobile.setMobileVisible(playerId, false)\r\n\tUI.setShortcutEnabled(false)\r\nend\r\n\r\nfunction endCine()\r\n\tCamera.attachCameraToMobile(Context.getLeaderId())\r\n\tUI.displayWideScreenBand(false, 25)\r\n\tCamera.setUserZoomLocked(false)\t\t\t\t\t\t\t\t\t\t\t\t\r\n\tUI.setUIVisible(true)\t\r\n\tUI.manageFrame(\"World\",true) \t\t\t\t\r\n\tCamera.setZoomFactor(zoomFactor)\t\r\n\tMobile.setMobileVisible(playerId, true)\r\n\tUI.setShortcutEnabled(true)\r\nend\r\n\r\nfunction Bubble(mob,text)\r\n\tBubbleText.closeBubbleAttachedTo(mob)\r\n\tBubbleText.showText(mob, text, 0, 40, false)\r\nend\n\n-- [INIT] Variables\n-- \nfunction event_1966_15698()\n    \nend\n\n-- [INIT] ENTER_INSTANCE (QP2542 en cours)\n-- \nfunction event_1966_15692()\n    \nend\n\n-- [INIT] ENTER_INSTANCE (QP2542 terminée)\n-- \nfunction event_1966_15787()\n    \nend\n\n-- [EVENT] Activation combat\n-- \nfunction event_1966_15693()\n    \nend\n\n-- [EVENT] Combat - Préparation terminée\n-- \nfunction event_1966_15704()\n    \nend\n\n-- [EVENT] Victoire\n-- \nfunction event_1966_15694()\n    \nend\n\n-- [EVENT] Ciné Hadibal intervient - début\n-- \nfunction event_1966_15699(Hadibal)\n    --Init\r\n    playerId = Context.getLeaderId()\r\n    Hadibalcine = toLong(Hadibal)\r\n    -- functions\r\n    function CameraOn()\r\n    Camera.setWorldTarget(8, -2, 0)\r\n    end\r\n    \r\n    --Script\r\n    startCine()\r\n    Hadibal = Mobile.generateClientMobileId()\r\n    Actor.createActor(Hadibal, 1030008, 7, -17, 0, 4)\r\n    Mobile.setMobileDirection(Hadibal, 3)\r\n    Mobile.setMobileVisible(Hadibalcine, false)\r\n    invoke(500, 1, \"Camera.attachCameraToMobile\", Hadibal)\r\n    --invoke(1000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Chercher\")\r\n    invoke(500, 1, \"Mobile.setMobileAnimation\", Hadibal, \"AnimComp-Heler\")\r\n    invoke(1000, 1, \"Bubble\", Hadibal, \"kelba.quest.hadibalideout.01\")\r\n    --invoke(6000, 1, \"Mobile.moveMobile\", playerId, 9, 2, 0)\r\n    invoke(4000, 1, \"Bubble\", Hadibal, \"kelba.quest.hadibalideout.02\")\r\n    invoke(8000, 1, \"Bubble\", Hadibal, \"kelba.quest.hadibalideout.03\")\r\n    invoke(12000, 1, \"Bubble\", Hadibal, \"kelba.quest.hadibalideout.04\")\r\n    \r\n    invoke(16000, 1, \"UI.displayWideScreenBand\", true, 100, 1000)\r\n    invoke(17000, 1, \"Actor.deleteActor\", Hadibal)\r\n    invoke(17000, 1, \"CameraOn\")\r\n    invoke(17200, 1, \"Mobile.setMobileVisible\", Hadibalcine, true)\r\n    invoke(18000, 1, \"UI.displayWideScreenBand\", true, 50, 1000)\r\n    \r\n    invoke(19000, 1, \"Bubble\", Hadibalcine, \"kelba.quest.hadibalideout.05\")\r\n    invoke(19000, 1, \"Mobile.moveMobile\", playerId, 9, 2, 0)\r\n    invoke(19500, 1, \"Camera.attachCameraToMobile\", playerId)\r\nend\n\n-- [EVENT] Fin cine\n-- \nfunction event_1966_15700()\n    endCine()\nend\n\n-- [COMBAT] Combat contre les Riktus - Enregistrment de l'évènement\n-- \nfunction event_1966_15701(fightStarted)\n    \nend\n\n-- [INIT] ENTER_INSTANCE - combat en cours\n-- \nfunction event_1966_15702(fightStarted)\n    UI.loadTutorialDialog(\"null\",\"quest.running.title\",\"quest.dd.ch1.inglorium.running.desc\")\r\n    \r\n    fightStartedval = toLong(fightStarted)\r\n    trace(\"value of fightStarted on Fight running when entering Instance :::::\", fightStartedval)\nend\n\n","functions":["startCine","endCine","Bubble","event_1966_15698","event_1966_15692","event_1966_15787","event_1966_15693","event_1966_15704","event_1966_15694","event_1966_15699","CameraOn","event_1966_15700","event_1966_15701","event_1966_15702"],"quest_calls":[],"dialogue_calls":[]},"scenario/1967.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\n\n-- [INIT] Variables\n-- \nfunction event_1967_15705()\n    \nend\n\n-- [EVENT][CINE] ENTER_INSTANCE - Quête en cours\n-- \nfunction event_1967_15832(kabrokId)\n    local kabrok = toLong(kabrokId)\r\n    local playerId = Context.getLeaderId()\r\n    \r\n    Mobile.setMobileVisible(playerId, false)\r\n    \r\n    Actor.changeSkin(kabrok, 173603580)\r\n    Mobile.setMobileDirection(kabrok, 5)\r\n    Mobile.setMobileAnimationStaticKey(kabrok, \"AnimStatique-Nu\")\r\n    Mobile.setMobileToStaticAnimation(kabrok)\r\n    \r\n    startCinematicContext(1.6, kabrok)\r\n    \r\n    invoke_custom(2000, 1, \"bubble\", kabrok, \"kelba.quest.kabrokz2start.01\")\r\n    \r\n    invoke(6000, 1, \"Server.triggerEvent\", 15832)\nend\n\n-- [EVENT][CINE] Arrivée du joueur\n-- \nfunction event_1967_15833(kabrokId)\n    local playerId = Context.getLeaderId()\r\n    local kabrok = toLong(kabrokId)\r\n    \r\n    Mobile.setMobileVisible(playerId, true)\r\n    Mobile.setMobileDirection(playerId, 5)\r\n    \r\n    bubble(playerId, \"kelba.quest.kabrokz2start.02\")\r\n    invoke_custom(1000, 1, \"bubble\", kabrok, \"kelba.quest.kabrokz2start.03\")\r\n    invoke_custom(1500, 1, \"Mobile.setMobileAnimation\", kabrok, \"AnimComp-RetraitCasque-Nu\")\r\n    invoke_custom(2800, 1, \"Mobile.setMobileAnimation\", kabrok, \"AnimComp-Grille-Debut-Nu\")\r\n    invoke_custom(6000, 1, \"UI.displayWideScreenBand\", true, 100)\r\n    \r\n    invoke(7000, 1, \"Server.triggerEvent\", 15833)\nend\n\n-- [EVENT][CINE] Kabrok s'explique\n-- \nfunction event_1967_15834(kabrokId)\n    local playerId = Context.getLeaderId()\r\n    local kabrok = toLong(kabrokId)\r\n    \r\n    Mobile.setMobileDirection(kabrok, 1)\r\n    Mobile.setMobileAnimationStaticKey(kabrok, \"AnimStatique\")\r\n    Mobile.setMobileToStaticAnimation(kabrok)\r\n    Camera.attachCameraToMobile(playerId)\r\n    \r\n    UI.displayWideScreenBand(true, 25)\r\n    \r\n    --invoke_custom(500,1,\"Bubble\",kabrok, \"kelba.quest.kabrokz2start.01\")\r\n    --invoke_custom(4500,1,\"Camera.attachCameraToMobile\",playerId)\r\n    --invoke_custom(4500,1,\"Mobile.setMobileVisible\",playerId, true)\r\n    \r\n    --invoke_custom(5000,1,\"Mobile.setMobileAnimation\",playerId,\"AnimEmote-Chercher\")\r\n    --invoke_custom(6000,1,\"Bubble\",playerId, \"kelba.quest.kabrokz2start.02\")\r\n    --invoke_custom(9000,1,\"Mobile.setMobileDirection\", playerId, 5)\r\n    \r\n    --invoke_custom(12000,1,\"Bubble\",kabrok, \"kelba.quest.kabrokz2start.03\")\r\n    --invoke_custom(14000,1,\"Mobile.setMobileAnimation\",playerId,\"AnimEmote-Non\")\r\n    \r\n    -- \"On ne vous a donc jamais appris à vous annoncer avant d'entrer !!!\"\r\n    invoke_custom(01000,1,\"bubble\",kabrok, \"kelba.quest.kabrokz2start.04\")\r\n    invoke_custom(03000,1,\"Mobile.setMobileAnimation\",playerId,\"AnimEmote-Applaudir\")\r\n    \r\n    -- \"Bon, au moins vous êtes arrivé ici sain et sauf.\"\r\n    invoke_custom(06000,1,\"bubble\",kabrok, \"kelba.quest.kabrokz2start.05\")\r\n    invoke_custom(08000,1,\"Mobile.setMobileAnimation\",playerId,\"AnimEmote-Pouce\")\r\n    \r\n    -- \"Vous vous souvenez ce que vous avez à faire ?\"\r\n    invoke_custom(10000,1,\"bubble\",kabrok, \"kelba.quest.kabrokz2start.06\")\r\n    invoke_custom(12000,1,\"Mobile.setMobileAnimation\",playerId,\"AnimEmote-Chercher\")\r\n    \r\n    -- \"Hmmm... C'est très simple.\"\r\n    invoke_custom(15000,1,\"bubble\",kabrok, \"kelba.quest.kabrokz2start.07\")\r\n    invoke_custom(16000,1,\"Mobile.setMobileAnimation\",playerId,\"AnimEmote-Victoire\")\r\n    \r\n    -- \"Cherchez le chef des Kroapules...\"\r\n    invoke_custom(18000,1,\"bubble\",kabrok, \"kelba.quest.kabrokz2start.08\")\r\n    invoke_custom(20000,1,\"Mobile.setMobileAnimation\",playerId,\"AnimEmote-Chercher\")\r\n    \r\n    -- \"... Et récupérez des informations sur les pillards qui ont volé l'artefact.\"\r\n    invoke_custom(22000,1,\"bubble\",kabrok, \"kelba.quest.kabrokz2start.09\")\r\n    invoke_custom(24000,1,\"Mobile.setMobileAnimation\",playerId,\"AnimEmote-Chercher\")\r\n    \r\n    -- \"Parlez moi quand vous serez prêt à partir.\"\r\n    invoke_custom(27000,1,\"bubble\",kabrok, \"kelba.quest.kabrokz2start.10\")\r\n    invoke_custom(28000,1,\"Mobile.setMobileAnimation\",playerId,\"AnimEmote-Acquiescer\")\r\n    \r\n    invoke(31000, 1, \"skipCinematic\", 15834)\nend\n\n-- [EVENT] Fin Cinématique - Validation ACH 2547/8 OBJ 5046/7\n-- \nfunction event_1967_19799()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_1967_15705","event_1967_15832","event_1967_15833","event_1967_15834","event_1967_19799"],"quest_calls":[],"dialogue_calls":[]},"scenario/1968.lua":{"source":"\n\n-- [EVENT] Initialisation\n-- \nfunction event_1968_15707()\n    \nend\n\n-- [ACTION] Lancement du combat associé\n-- \nfunction event_1968_15708()\n    \nend\n\n-- [ACTION] Fin de combat gagnant\n-- \nfunction event_1968_15709(GroupId)\n    \nend\n\n-- [ACTION] Fin de combat gagnant - fin scenario\n-- \nfunction event_1968_15710(GroupId)\n    \nend\n\n-- [ACTION] Fin de combat perdant\n-- \nfunction event_1968_15711(GroupId, MobA)\n    \nend\n\n","functions":["event_1968_15707","event_1968_15708","event_1968_15709","event_1968_15710","event_1968_15711"],"quest_calls":[],"dialogue_calls":[]},"scenario/1970.lua":{"source":"playerId = Context.getPlayer()\r\nfightWon = 0\r\n\r\nfunction startCine()\r\n\tzoomFactor = Camera.getZoomFactor()\r\n\tUI.manageFrame(\"World\",false) \t\t\t\t\t\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\t\t\t\t\t\t\t\t\t\t\t\t\r\n\tUI.manageFrame(\"World\",false) \t\t\t\t\t\r\n\tUI.setUIVisible(false)\t\r\n\tUI.displayWideScreenBand(true)\r\n\tUI.setShortcutEnabled(false)\r\nend\r\n\r\nfunction endCine()\r\n\tCamera.attachCameraToMobile(playerId)\r\n\tUI.displayWideScreenBand(false)\r\n\tCamera.setUserZoomLocked(false)\t\t\t\t\t\t\t\t\t\t\t\t\r\n\tUI.setUIVisible(true)\t\r\n\tUI.manageFrame(\"World\",true) \t\t\t\t\r\n\tCamera.setZoomFactor(zoomFactor)\t\r\n\tUI.setShortcutEnabled(true)\r\nend\r\n\r\nfunction Bubble(mob,text)\r\n\tBubbleText.closeBubbleAttachedTo(mob)\r\n\tBubbleText.showText(mob, text, 0, 40, false)\r\nend\n\n-- [INIT] Variables\n-- \nfunction event_1970_15717()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Cinématique\n-- \nfunction event_1970_15718()\n    function createActors()\r\n    \tush = Mobile.generateClientMobileId()\r\n    \tkabrok = Mobile.generateClientMobileId()\r\n    \tActor.createActor(ush, 173803603, -8,1,0)\r\n    \tMobile.setMobileDirection(ush,5)\r\n    \tActor.createActor(kabrok, 101101151, -1,-1,0)\r\n    \tMobile.setMobileDirection(kabrok,5)\t\r\n    end\r\n    \r\n    function ushTalk()\r\n    \tBubble(ush,\"quest.kelba.entrepot.ush.0\")\r\n    end\r\n    \r\n    function ushFlee()\r\n    \tMobile.setMobileDirection(ush,1)\r\n    \tBubble(ush,\"quest.kelba.entrepot.ush.1\")\r\n    \tinvoke(3000,1,\"Mobile.setMobileAnimation\",ush,\"AnimSort-DoubleJeu-Debut\")\r\n    end\r\n    \r\n    function kabrokFollow()\r\n    \tCamera.setWorldTarget(0,0,0)\r\n    \tCamera.setZoomFactor(1)\r\n    \tBubble(kabrok,\"quest.kelba.entrepot.kabrok.0\")\r\n    \tinvoke(3000,1,\"Mobile.setMobileDirection\",kabrok,1)\r\n    \tinvoke(3000,1,\"Mobile.setMobileAnimation\",kabrok,\"AnimSort-Saut\")\r\n    end\r\n    \r\n    \r\n    startCine()\r\n    createActors()\r\n    \r\n    Camera.setWorldTarget(-8,1,0)\r\n    Camera.setZoomFactor(1.5)\r\n    \r\n    invoke(1000,1,\"ushTalk\")\r\n    \r\n    invoke(5000,1,\"ushFlee\")\r\n    \r\n    invoke(10000,1,\"kabrokFollow\")\r\n    \r\n    invoke(14000,1,\"Mobile.setMobileVisible\",ush,false)\r\n    invoke(14000,1,\"Mobile.setMobileVisible\",kabrok,false)\r\n    invoke(15000,1,\"endCine\")\nend\n\n-- [EVENT] Démarrage Combat Kroapule\n-- \nfunction event_1970_15782()\n    \nend\n\n-- [EVENT] Victoire Kroapule - Cinématique\n-- \nfunction event_1970_15816()\n    function kabrokComesBack()\r\n    \tCamera.setWorldTarget(0,0,0)\r\n    \tCamera.setZoomFactor(1.6)\r\n    \tMobile.setMobileAnimation(kabrok,\"AnimStatique\")\r\n    \tMobile.setMobileVisible(kabrok,true)\r\n    \tMobile.setMobileDirection(kabrok,5)\r\n    \tBubble(kabrok,\"quest.kelba.entrepot.kabrok.1\")\r\n    end\r\n    \r\n    function kabrokLeaves()\r\n    \tinvoke(1500,1,\"Mobile.setMobileDirection\",kabrok,1)\r\n    \tinvoke(1500,1,\"Mobile.setMobileAnimation\",kabrok,\"AnimSort-Saut\")\r\n    end\r\n    \r\n    startCine()\r\n    kabrokComesBack()\r\n    invoke(3000,1,\"kabrokLeaves\")\r\n    \r\n    invoke(6000,1,\"endCine\")\nend\n\n","functions":["startCine","endCine","Bubble","event_1970_15717","event_1970_15718","createActors","ushTalk","ushFlee","kabrokFollow","event_1970_15782","event_1970_15816","kabrokComesBack","kabrokLeaves"],"quest_calls":[],"dialogue_calls":[]},"scenario/1971.lua":{"source":"playerId = Context.getPlayer()\r\nxUsh = 0\r\nyUsh = 0\r\nzUsh = 0\r\n\r\nfunction startCine()\r\n\tzoomFactor = Camera.getZoomFactor()\r\n\tUI.manageFrame(\"World\",false) \t\t\t\t\t\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\t\t\t\t\t\t\t\t\t\t\t\t\r\n\tUI.manageFrame(\"World\",false) \t\t\t\t\t\r\n\tUI.setUIVisible(false)\t\r\n\tUI.displayWideScreenBand(true)\r\n\tUI.setShortcutEnabled(false)\r\nend\r\n\r\nfunction endCine()\r\n\tCamera.attachCameraToMobile(playerId)\r\n\tUI.displayWideScreenBand(false)\r\n\tCamera.setUserZoomLocked(false)\t\t\t\t\t\t\t\t\t\t\t\t\r\n\tUI.setUIVisible(true)\t\r\n\tUI.manageFrame(\"World\",true) \t\t\t\t\r\n\tCamera.setZoomFactor(zoomFactor)\t\r\n\tUI.setShortcutEnabled(true)\r\nend\r\n\r\nfunction Bubble(mob,text)\r\n\tBubbleText.closeBubbleAttachedTo(mob)\r\n\tBubbleText.showText(mob, text, 0, 40, false)\r\nend\n\n-- [INIT] Variables\n-- \nfunction event_1971_15719()\n    \nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_1971_15720()\n    \nend\n\n-- [CINE] Début\n-- \nfunction event_1971_15831(ushId)\n    function createMobile()\r\n    \tkabrok = Mobile.generateClientMobileId()\r\n    \tActor.createActor(kabrok,101101151,-1,0,0,4)\r\n    \tMobile.setMobileDirection(kabrok,5)\r\n    \tMobile.setMobileVisible(kabrok,true)\t\r\n    end\r\n    \r\n    function kabrokTalk()\r\n    \tMobile.moveMobile(kabrok,-14,0,0,\"Mobile.moveMobile\",kabrok,-16,-18,16)\r\n    \tBubble(kabrok,\"quest.kelba.end.kabrok.00\")\r\n    \t\r\n    \tinvoke(3000,1,\"Bubble\",kabrok,\"quest.kelba.end.kabrok.01\")\r\n    end\r\n    \r\n    function ushTalk()\r\n    \tCamera.setWorldTarget(-13,-28,18)\r\n    \tBubble(ush,\"quest.kelba.end.ush.10\")\r\n    end\r\n    \r\n    ush = toLong(ushId)\r\n    \r\n    startCine()\r\n    invoke(1500,1,\"createMobile\")\r\n    invoke(4000,1,\"kabrokTalk\")\r\n    invoke(13000,1,\"ushTalk\")\r\n    invoke(18000,1,\"endCine\")\r\nend\n\n-- [CINE] Début (move player delay)\n-- \nfunction event_1971_15875(ushId)\n    \nend\n\n-- [EVENT] Lancement du combat contre Hush\n-- \nfunction event_1971_15753()\n    --kabrok = toLong(kabrok)\r\n    Mobile.setMobileVisible(kabrok,false)\nend\n\n-- [EVENT] Victoire du Joueur - Fin du combat\n-- \nfunction event_1971_15755(ushId)\n    ushId = toLong(ushId)\r\n    xUsh,yUsh,zUsh = Mobile.getMobilePosition(ushId)\r\n    \r\n    trace(\"POSITION DE USH ::::::::::::::::::::::::::::::::::::: \", xUsh, yUsh, zUsh)\r\n    \r\nend\n\n-- [CINE] Fin\n-- \nfunction event_1971_15770()\n    -- ANIM USH\r\n    -- AnimSort-DoubleJeu-Debut\r\n    -- AnimSort-DoubleJeu-Fin\r\n    -- AnimSort-DoubleLame\r\n    -- AnimSort-LancerdeCarte\r\n    -- AnimSort-Tornade\r\n    -- AnimApparition\r\n    -- AnimTarget-CartePuce\r\n    \r\n    -- ANIM CN\r\n    -- AnimSort-CorbeauMissiles\r\n    -- AnimTarget-CorbeauMissiles\r\n    -- AnimSort-Explosion-De-Plumes\r\n    \r\n    trace(\"POSITION DE USH ::::::::::::::::::::::::::::::::::::: \", xUsh, yUsh, zUsh)\r\n    \r\n    \r\n    ----- definitions\r\n    \r\n    playerX,playerY,playerZ = Mobile.getMobilePosition(playerId)\r\n    \r\n    \r\n    \r\n    --- functions\r\n    function createMobile()\r\n    \tush = Mobile.generateClientMobileId()\r\n    \tkabrok = Mobile.generateClientMobileId()\r\n    \ttarget = Mobile.generateClientMobileId()\r\n    \ttargetCN = Mobile.generateClientMobileId()\r\n    \t\r\n    \tActor.createActor(ush,173803603,xUsh,yUsh,zUsh,4)\r\n    \tMobile.moveMobile(ush, -14,-26,16,\"Mobile.setMobileDirection\",ush,3)\r\n    \tBubble( ush, \"quest.kelba.end.ush.00\")\r\n    \t\r\n    \t--Actor.createActor(ush,173803603,-14,-26,16,4)\r\n    \tActor.createActor(kabrok,101101151,-10,-22,16,4)\r\n    \tActor.createActor(target,173803603,-10,-22,16,4)\r\n    \tActor.createActor(targetCN,101101151,playerX,playerY,playerZ,4)\r\n    \t\r\n    \tMobile.setMobileVisible(target,false);\r\n    \tMobile.setMobileVisible(targetCN,false);\r\n    \tMobile.setMobileVisible(ush, true)\r\n    \tMobile.setMobileAnimation(ush,\"AnimApparition\")\r\n    \tMobile.setMobileVisible(kabrok,true)\r\n    \tMobile.setMobileDirection(kabrok,5)\r\n    \tMobile.setMobileAnimation(kabrok,\"AnimStatique02\")\r\n    end\r\n    \r\n    \r\n    \r\n    function ushTalk()\r\n    \tBubble(ush,\"quest.kelba.end.ush.06\")\r\n    \t\r\n    invoke(8000,1,\"ushLeave\")\r\n    end\r\n    \r\n    function ushTalkBegin()\r\n    \tinvoke(4000,1,\"Bubble\", ush, \"quest.kelba.end.ush.01\")\r\n    \tinvoke(8000,1,\"Bubble\", ush, \"quest.kelba.end.ush.02\")\r\n    invoke(8000,1,\"ushCheat\")\r\n    end\r\n    \r\n    \r\n    function ushCheat()\r\n    \tMobile.setMobileAnimation(ush, \"AnimSort-LancerdeCarte\")\r\n    \tinvoke(1000,1,\"Mobile.setMobileVisible\",target,true)\r\n    \tinvoke(1000,1,\"Mobile.setMobileAnimation\",target,\"AnimTarget-CartePuce\",\"Mobile.setMobileVisible\",target,false)\r\n    \tinvoke(3500,1,\"Mobile.setMobileAnimation\",ush,\"AnimApparition\")\r\n    \tinvoke(4000,1,\"ushParticle\") \r\n    \tinvoke(4700,1,\"Mobile.setMobileAnimation\",ush,\"AnimStatique02\")\r\n    \tinvoke(5000,1,\"Bubble\", ush, \"quest.kelba.end.ush.03\")\r\n    \tinvoke(5000,1,\"cnAttack\")\r\n    end\r\n    \r\n    \r\n    function ushParticle()\r\n    \tptcle = Particle.addParticleSystemToTargetWithOffset(1006040, kabrok,1,6) \r\n    end\r\n    \r\n    \r\n    function cnAttack()\r\n    \tMobile.setMobileAnimation(kabrok,\"AnimSort-CorbeauMissiles\")\r\n    \r\n    \tinvoke(1000,1,\"Mobile.setMobileVisible\",targetCN,true)\t\r\n    \tinvoke(1000,1,\"Mobile.setMobileAnimation\",targetCN,\"AnimTarget-CorbeauMissiles\",\"Mobile.setMobileVisible\",targetCN,false)\t\r\n    \tinvoke(2000,1,\"Mobile.setMobileAnimation\",playerId,\"AnimKO-Debut\")\r\n    \tinvoke (2500,1,\"Bubble\", ush, \"quest.kelba.end.ush.04\")\r\n    \t\r\n    \tinvoke(4000,1,\"Mobile.setMobileAnimation\",kabrok,\"AnimSort-Explosion-De-Plumes\")\r\n    \r\n    --\tinvoke(5000,1,\"Particle.addParticleSystem\",-1436029430,-22,16,4) --particule combat ?\r\n    \tinvoke(5000,1,\"Particle.addParticleSystemToTarget\",-1436029430,kabrok,1)\r\n    \r\n     \tinvoke(6000,1,\"Mobile.setMobileDirection\",kabrok,3)\r\n    \tinvoke(6000,1,\"Mobile.setMobileAnimation\",kabrok,\"AnimKO-Debut\")\r\n    \tinvoke(6000,1,\"Bubble\", ush, \"quest.kelba.end.ush.05\")\r\n    \t\r\n    \tinvoke(8000,1,\"ushTalk\")\r\n    end\r\n    \r\n    \r\n    function ushLeave()\r\n    \tMobile.setMobileAnimation(ush,\"AnimSort-SautFinal\")\r\n        Particle.addParticleSystemToTarget(800556,ush,1)\r\n    \tParticle.removeParticleSystem(ptcle)\r\n    \tinvoke(5000,1,\"cnRecover\")\r\n    invoke(5000,1,\"Actor.deleteActor\",ush)\t\r\n    end\r\n    \r\n    function cnRecover()\r\n    \tMobile.setMobileAnimation(kabrok,\"AnimKO-SortieOK\")\r\n    \tinvoke(2000,1,\"Bubble\", kabrok, \"quest.kelba.end.kabrok.02\")\r\n    \tinvoke(2000,1,\"Mobile.setMobileDirection\",kabrok,5)\r\n    \tinvoke(4000,1,\"Mobile.setMobileAnimation\",playerId,\"AnimKO-SortieOK\")\r\n    \tinvoke(5500, 1, \"Mobile.moveMobile\",playerId, -14,-22,16,\"Mobile.setMobileDirection\",playerId,7)\r\n    \tinvoke(6000,1,\"Bubble\", kabrok, \"quest.kelba.end.kabrok.03\")\r\n    \tinvoke(6000, 1, \"Mobile.moveMobile\",kabrok, -14,-24,16,\"Mobile.setMobileDirection\",kabrok,3)\r\n    \tinvoke(8000,1,\"Mobile.setMobileAnimation\",playerId,\"AnimEmote-Toux\")\r\n    \t\r\n    \tinvoke(10000,1,\"Bubble\", kabrok, \"quest.kelba.end.kabrok.05\")\r\n    \tinvoke(10000,1,\"Mobile.setMobileAnimation\",kabrok,\"AnimComp02\")\r\n    \tinvoke(12000,1,\"Mobile.setMobileAnimation\",playerId,\"AnimEmote-Rire\")\r\n    \tinvoke(14000,1,\"Bubble\", kabrok, \"quest.kelba.end.kabrok.06\")\r\n    \tinvoke(20000,1,\"Bubble\", kabrok, \"quest.kelba.end.kabrok.07\")\r\n    \tinvoke(20000,1,\"Mobile.setMobileAnimation\",playerId,\"AnimEmote-Victoire\")\r\n    \t\r\n    \tinvoke(24000,1,\"Bubble\", kabrok, \"quest.kelba.end.kabrok.08\")\r\n    \tinvoke(24000,1,\"Mobile.setMobileAnimation\",kabrok,\"AnimSort-Explosion-De-Plumes\")\r\n    \tinvoke(26000,1,\"Mobile.setMobileAnimation\",kabrok,\"AnimSort-Saut\")\r\n    \tinvoke(26000,1,\"Mobile.setMobileAnimation\",playerId,\"AnimEmote-Coucou\")\r\n    \r\n    \tinvoke(28000,1,\"Actor.deleteActor\",kabrok)\r\n    \t\r\n    \tinvoke(30000,1,\"endCine\")\r\n    end\r\n    \r\n    \r\n    \r\n    ---- script\r\n    startCine()\r\n    Camera.setWorldTarget(-14,-26,16)\r\n    Camera.setZoomFactor(1.3)\r\n    createMobile()\r\n    ushTalkBegin()\r\nend\n\n-- [CINE] Fin (move player delay)\n-- \nfunction event_1971_15888(ushId)\n    \nend\n\n","functions":["startCine","endCine","Bubble","event_1971_15719","event_1971_15720","event_1971_15831","createMobile","kabrokTalk","ushTalk","event_1971_15875","event_1971_15753","event_1971_15755","event_1971_15770","createMobile","ushTalk","ushTalkBegin","ushCheat","ushParticle","cnAttack","ushLeave","cnRecover","event_1971_15888"],"quest_calls":[],"dialogue_calls":[]},"scenario/1973.lua":{"source":"\n\n-- [EVENT] Initialisation\n-- \nfunction event_1973_15727()\n    \nend\n\n-- [ACTION] Lancement du combat associé\n-- \nfunction event_1973_15728()\n    \nend\n\n-- [ACTION] Fin de combat gagnant\n-- \nfunction event_1973_15729(GroupId)\n    \nend\n\n-- [ACTION] Fin de combat gagnant - fin scenario\n-- \nfunction event_1973_15730(GroupId)\n    \nend\n\n-- [ACTION] Fin de combat perdant\n-- \nfunction event_1973_15731(GroupId, MobA)\n    \nend\n\n","functions":["event_1973_15727","event_1973_15728","event_1973_15729","event_1973_15730","event_1973_15731"],"quest_calls":[],"dialogue_calls":[]},"scenario/1974.lua":{"source":"\n\n-- [EVENT] Initialisation\n-- \nfunction event_1974_15737()\n    \nend\n\n-- [ACTION] Lancement du combat associé\n-- \nfunction event_1974_15738()\n    \nend\n\n-- [ACTION] Fin de combat gagnant\n-- \nfunction event_1974_15739(GroupId)\n    \nend\n\n-- [ACTION] Fin de combat gagnant - fin scenario\n-- \nfunction event_1974_15740(GroupId)\n    \nend\n\n-- [ACTION] Fin de combat perdant\n-- \nfunction event_1974_15741(GroupId, MobA)\n    \nend\n\n","functions":["event_1974_15737","event_1974_15738","event_1974_15739","event_1974_15740","event_1974_15741"],"quest_calls":[],"dialogue_calls":[]},"scenario/1975.lua":{"source":"\n\n-- [EVENT] Initialisation\n-- \nfunction event_1975_15742()\n    \nend\n\n-- [ACTION] Lancement du combat associé\n-- \nfunction event_1975_15743()\n    \nend\n\n-- [ACTION] Fin de combat gagnant\n-- \nfunction event_1975_15744(GroupId)\n    \nend\n\n-- [ACTION] Fin de combat gagnant - fin scenario\n-- \nfunction event_1975_15745(GroupId)\n    \nend\n\n-- [ACTION] Fin de combat perdant\n-- \nfunction event_1975_15746(GroupId, MobA)\n    \nend\n\n","functions":["event_1975_15742","event_1975_15743","event_1975_15744","event_1975_15745","event_1975_15746"],"quest_calls":[],"dialogue_calls":[]},"scenario/1976.lua":{"source":"\n\n-- [EVENT] Initialisation\n-- \nfunction event_1976_15747()\n    \nend\n\n-- [ACTION] Lancement du combat associé\n-- \nfunction event_1976_15748()\n    \nend\n\n-- [ACTION] Fin de combat gagnant\n-- \nfunction event_1976_15749(GroupId)\n    \nend\n\n-- [ACTION] Fin de combat gagnant - fin scenario\n-- \nfunction event_1976_15750(GroupId)\n    \nend\n\n-- [ACTION] Fin de combat perdant\n-- \nfunction event_1976_15751(GroupId, MobA)\n    \nend\n\n","functions":["event_1976_15747","event_1976_15748","event_1976_15749","event_1976_15750","event_1976_15751"],"quest_calls":[],"dialogue_calls":[]},"scenario/1977.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\n\n-- [INIT] Variables\n-- \nfunction event_1977_15757()\n    \nend\n\n-- [EVENT][CINE] ENTER_INSTANCE - Quête en cours\n-- \nfunction event_1977_15758(kabrokId)\n    local kabrok = toLong(kabrokId)\r\n    local playerId = Context.getLeaderId()\r\n    \r\n    Mobile.setMobileVisible(playerId, false)\r\n    \r\n    Actor.changeSkin(kabrok, 173603580)\r\n    Mobile.setMobileDirection(kabrok, 5)\r\n    Mobile.setMobileAnimationStaticKey(kabrok, \"AnimStatique-Nu\")\r\n    Mobile.setMobileToStaticAnimation(kabrok)\r\n    \r\n    startCinematicContext(1.3, kabrok)\r\n    \r\n    invoke(6000, 1, \"Server.triggerEvent\", 15876)\nend\n\n-- [EVENT][CINE] Arrivée du joueur\n-- \nfunction event_1977_15774(kabrokId)\n    local kabrok = toLong(kabrokId)\r\n    local playerId = Context.getLeaderId()\r\n    \r\n    Mobile.setMobileDirection(playerId, 5)\r\n    Mobile.setMobileVisible(playerId, true)\r\n    \r\n    invoke_custom(3000, 1, \"bubble\", playerId, \"quest.kelba.planquecn.player.01\")\r\n    invoke_custom(4000, 1, \"bubble\", kabrok, \"quest.kelba.planquecn.kabrok.01\")\r\n    \r\n    invoke_custom(5000, 1, \"Mobile.setMobileAnimation\", kabrok, \"AnimComp-RetraitCasque-Nu\")\r\n    invoke_custom(6300, 1, \"Mobile.setMobileAnimation\", kabrok, \"AnimComp-Grille-Debut-Nu\")\r\n    \t\r\n    invoke_custom(7900, 1, \"Mobile.setMobileDirection\", kabrok, 1)\r\n    invoke_custom(7900, 1, \"Mobile.setMobileAnimationStaticKey\", kabrok, \"AnimStatique\")\r\n    invoke_custom(7900, 1, \"Mobile.setMobileAnimation\", kabrok, \"AnimComp-Grille-Boucle-Nu\")\t\r\n    \t\r\n    invoke_custom(10000, 1, \"UI.displayWideScreenBand\", true, 100)\r\n    \r\n    invoke(11000, 1, \"Server.triggerEvent\", 15774)\nend\n\n-- [EVENT][CINE] Kabrok s'explique\n-- \nfunction event_1977_15759(kabrokId)\n    local kabrok = toLong(kabrokId)\r\n    local playerId = Context.getLeaderId()\r\n    \r\n    Mobile.setMobileDirection(kabrok, 3)\r\n    Mobile.setMobileDirection(playerId, 7)\r\n    Camera.attachCameraToMobile(playerId)\r\n    \r\n    UI.displayWideScreenBand(true, 25)\r\n    \r\n    -- \"Je peux tout expliquer...\"\r\n    invoke_custom(1000, 1, \"bubble\", kabrok, \"quest.kelba.planquecn.kabrok.02\")\r\n    invoke_custom(4000, 1, \"clearBubbles\", kabrok)\r\n    \r\n    -- \"Où est la marchandise ?\"\r\n    invoke_custom(4500, 1, \"bubble\", playerId, \"quest.kelba.planquecn.player.02\")\r\n    invoke_custom(7000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Hé bien... Je... Je ne l'ai plus. Je me suis fait plumer, dans mon propre repaire !\"\r\n    invoke_custom(7500, 1, \"bubble\", kabrok, \"quest.kelba.planquecn.kabrok.03\")\r\n    invoke_custom(12000, 1, \"clearBubbles\", kabrok)\r\n    \r\n    -- \"Mais ! C'est impossible !! Qui a bien pu commettre ce vol ?\"\r\n    invoke_custom(12500, 1, \"bubble\", playerId, \"quest.kelba.planquecn.player.03\")\r\n    invoke_custom(16500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"J'ai ma petite idée sur l'identité des malfrats... Pourtant... Il n'y a aucune raison qu'ils attaquent le nid d'un autre...\"\r\n    invoke_custom(17500, 1, \"bubble\", kabrok, \"quest.kelba.planquecn.kabrok.04\")\r\n    invoke_custom(23500, 1, \"clearBubbles\", kabrok)\r\n    \r\n    -- \"Attendez... Les Riktus sont hors du coup. Par contre, peu de temps avant que vous ne me voliez la marchandise, des sortes d'hommes-piafs s'en sont pris à nous...\"\r\n    invoke_custom(24500, 1, \"bubble\", playerId, \"quest.kelba.planquecn.player.04\")\r\n    invoke_custom(24500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(30500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Ca confirme mes soupçons. Par les cornes d'Osamodas, je vais les étriper ! Comment osent-ils s'attaquer au Corbeau Noir !?!\"\r\n    invoke_custom(31000, 1, \"bubble\", kabrok, \"quest.kelba.planquecn.kabrok.05\")\r\n    invoke_custom(37500, 1, \"clearBubbles\", kabrok)\r\n    \r\n    -- \"Calmez-vous. Je viens avec vous et on va s'occuper d'eux ensemble.\"\r\n    invoke_custom(38000, 1, \"bubble\", playerId, \"quest.kelba.planquecn.player.05\")\r\n    invoke_custom(39500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Calmer\")\r\n    invoke_custom(42000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Oui.. hem... OK. Le mieux c'est qu'on se retrouve dans une de mes planques dans les pics. De là, on ira voir mon contact chez les Kroapules.\"\r\n    invoke_custom(42500, 1, \"bubble\", kabrok, \"quest.kelba.planquecn.kabrok.06\")\r\n    \r\n    invoke(49000, 1, \"skipCinematic\", 15759)\nend\n\n-- [EVENT] Fin Cinématique - Validation ACH 2544 OBJ 5043\n-- \nfunction event_1977_19800()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_1977_15757","event_1977_15758","event_1977_15774","event_1977_15759","event_1977_19800"],"quest_calls":[],"dialogue_calls":[]},"scenario/1978.lua":{"source":"playerId = Context.getLeaderId()\r\n\r\nfunction startCine()\r\n\tzoomFactor = Camera.getZoomFactor()\r\n\tUI.manageFrame(\"World\",false) \t\t\t\t\t\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\t\t\t\t\t\t\t\t\t\t\t\t\r\n\tUI.manageFrame(\"World\",false) \t\t\t\t\t\r\n\tUI.setUIVisible(false)\t\r\n\tUI.displayWideScreenBand(true)\r\n\tMobile.setMobileVisible(playerId, false)\r\n\tUI.setShortcutEnabled(false)\r\nend\r\n\r\n--function endCine()\r\n--\tCamera.attachCameraToMobile(playerId)\r\n--\tUI.displayWideScreenBand(false)\r\n--\tCamera.setUserZoomLocked(false)\t\t\t\t\t\t\t\t\t\t\t\t\r\n--\tUI.setUIVisible(true)\t\r