 elseif (rand >= 20 and rand < 30) then\r\n    --    Mobile.setMobileAnimation(monsterId, \"AnimEmote-BrandirArme1\")\r\n        monster_bubbleId = BubbleText.showText(Mirandatrue, \"kelba.miranda.live.03\", 0, 80, false)\r\n      elseif (rand >= 30 and rand < 40) then\r\n    --    Mobile.setMobileAnimation(monsterId, \"AnimEmote-BrandirArme1\")\r\n        monster_bubbleId = BubbleText.showText(Mirandatrue, \"kelba.miranda.live.04\", 0, 80, false)\r\n      elseif (rand >= 40 and rand < 50) then\r\n    --    Mobile.setMobileAnimation(monsterId, \"AnimEmote-BrandirArme1\")\r\n        monster_bubbleId = BubbleText.showText(Mirandatrue, \"kelba.miranda.live.05\", 0, 80, false)\r\n    \telseif (rand >= 50 and rand < 60) then\r\n    --    Mobile.setMobileAnimation(monsterId, \"AnimEmote-BrandirArme1\")\r\n    \tmonster_bubbleId = BubbleText.showText(Mirandatrue, \"kelba.miranda.live.06\", 0, 80, false)\r\n    \telseif (rand >= 60 and rand < 70) then\r\n    --    Mobile.setMobileAnimation(monsterId, \"AnimEmote-BrandirArme1\")\r\n    \tmonster_bubbleId = BubbleText.showText(Mirandatrue, \"kelba.miranda.live.07\", 0, 80, false)\r\n          end\r\n    end\r\n    \r\n    \r\n    --script\r\n      PlayStartAnimation()\r\nend\n\n","functions":["startCine","endCine","Bubble","event_1978_15761","event_1978_15762","event_1978_15765","event_1978_15763","startMiranda","startKabrok","propalMiranda","tradeMiranda","reactKabrok","endMiranda","endCine","event_1978_15764","event_1978_15766","PlayStartAnimation"],"quest_calls":[],"dialogue_calls":[]},"scenario/1979.lua":{"source":"\n\n-- [INIT] Variables globales\n-- \nfunction event_1979_21855()\n    \nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_1979_21856()\n    \nend\n\n-- [1] Lancement Combat\n-- \nfunction event_1979_21861()\n    \nend\n\n-- [2] Lancement Combat\n-- \nfunction event_1979_21862()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 01\n-- \nfunction event_1979_21857(room)\n    \nend\n\n-- USER_GROUP_KILLED - Salle 02 - BOSS\n-- \nfunction event_1979_21859()\n    \nend\n\n-- Déplace le joueur vers la salle suivante\n-- \nfunction event_1979_21860()\n    \nend\n\n-- [ARCHI] Apparition de l'Archimonstre\n-- \nfunction event_1979_23955()\n    \nend\n\n","functions":["event_1979_21855","event_1979_21856","event_1979_21861","event_1979_21862","event_1979_21857","event_1979_21859","event_1979_21860","event_1979_23955"],"quest_calls":[],"dialogue_calls":[]},"scenario/1984.lua":{"source":"playerId = Context.getPlayer()\r\n\r\nfunction startCine()\r\n\tzoomFactor = Camera.getZoomFactor()\r\n\tUI.manageFrame(\"World\",false) \t\t\t\t\t\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\t\t\t\t\t\t\t\t\t\t\t\t\r\n\tUI.manageFrame(\"World\",false) \t\t\t\t\t\r\n\tUI.setUIVisible(false)\t\r\n\tUI.displayWideScreenBand(true)\r\n\tMobile.setMobileVisible(playerId, false)\r\n\tUI.setShortcutEnabled(false)\r\nend\r\n\r\nfunction endCine()\r\n\tCamera.attachCameraToMobile(playerId)\r\n\tUI.displayWideScreenBand(false, 25)\r\n\tCamera.setUserZoomLocked(false)\t\t\t\t\t\t\t\t\t\t\t\t\r\n\tUI.setUIVisible(true)\t\r\n\tUI.manageFrame(\"World\",true) \t\t\t\t\r\n\tCamera.setZoomFactor(zoomFactor)\t\r\n\tMobile.setMobileVisible(playerId, true)\r\n\tUI.setShortcutEnabled(true)\r\n\tServer.triggerEvent(15795)\r\nend\r\n\r\nfunction Bubble(mob,text)\r\n\tBubbleText.closeBubbleAttachedTo(mob)\r\n\tBubbleText.showText(mob, text, 0, 40, false)\r\nend\n\n-- [INIT] Variables\n-- \nfunction event_1984_15794(Kabrok)\n    \nend\n\n-- [INIT] entrée dans l'instance [CINE] début\n-- \nfunction event_1984_15795(KabrokId, PlayerId)\n    --Init\r\n    kabrok = toLong(KabrokId)\r\n    \r\n    -- functions\r\n    function kabrokChanging()\r\n    \tMobile.setMobileAnimation(kabrok,\"AnimStatique-Nu\") -- 1680\r\n    \tinvoke(1680,1,\"Mobile.setMobileAnimation\",kabrok,\"AnimComp-Lutte01-Nu\") -- 2800\r\n    \tinvoke(4480,1,\"Mobile.setMobileAnimation\",kabrok,\"AnimComp-Lutte02-Nu\") -- 1120\r\n    \tinvoke(5600,1,\"KorbaladApparition\")\r\n    \t\r\n    end\r\n    \r\n    function KorbaladApparition()\r\n    \tMobile.setMobileVisible(korbalad, true)\r\n    \tCamera.setWorldTarget(-5,-2,0)\r\n    \tinvoke(1000,1,\"Bubble\",korbalad,\"quest.kelba.planquecnpast.kabrok.01\")\r\n    \tinvoke(5000,1,\"kabrokChangingEnd\")\r\n    end\r\n    \r\n    function kabrokChangingEnd()\r\n    \tCamera.setWorldTarget(-12,2,0)\r\n    \tCamera.setZoomFactor(1)\r\n    \tinvoke(800,1,\"Bubble\",kabrok,\"quest.kelba.planquecnpast.kabrok.02\")\r\n    \r\n    \tinvoke(1500,1,\"Mobile.setMobileAnimation\",kabrok,\"AnimComp-RetraitCasque-Nu\") -- 1480\r\n    \t\t\r\n    \tinvoke(2980,1,\"Mobile.setMobileAnimation\",kabrok,\"AnimComp-Grille-Debut-Nu\") -- 1920\r\n    \t\r\n    \tinvoke(4900,1,\"Mobile.setMobileDirection\",kabrok,1)\r\n    \tinvoke(4900,1,\"Mobile.setMobileAnimation\",kabrok,\"AnimComp-Grille-Boucle-Nu\")\t\r\n    \tinvoke(7000,1,\"KorbaWifeApparition\")\r\n    end\r\n    \r\n    function KorbaWifeApparition()\r\n    \tMobile.setMobileVisible(korbaWife, true)\r\n    \tCamera.setWorldTarget(-1,0,0)\r\n    \r\n    \tinvoke(1000,1,\"Mobile.setMobileAnimation\",korbaWife,\"AnimSort-CaC02\")\r\n    \tinvoke(1000,1,\"Bubble\",korbaWife,\"quest.kelba.planquecnpast.kabrok.03\")\r\n    \tinvoke(5000,1,\"Mobile.setMobileAnimation\",korbaWife,\"AnimSort-Cast\")\r\n    \tinvoke(5000,1,\"Bubble\",korbaWife,\"quest.kelba.planquecnpast.kabrok.04\")\r\n    \tinvoke(9000,1,\"Mobile.setMobileAnimation\",korbaWife,\"AnimSort-CaC01\")\t\r\n    \tinvoke(9000,1,\"Bubble\",korbaWife,\"quest.kelba.planquecnpast.kabrok.05\")\r\n    \t\r\n    \tinvoke(12000,1,\"UI.displayWideScreenBand\",true,100)\r\n    \tinvoke(13000,1,\"Bubble\",korbalad,\"quest.kelba.planquecnpast.kabrok.06\")\r\n    \t\r\n    \tinvoke(17000,1,\"endCine\")\r\n    end\r\n    \r\n    --Script\r\n    korbalad = Mobile.generateClientMobileId()\r\n    Actor.createActor(korbalad, 145403592, -5, -2, 0)\r\n    Mobile.setMobileVisible(korbalad,false)\r\n    Mobile.setMobileDirection(korbalad, 3)\r\n    korbaWife = Mobile.generateClientMobileId()\r\n    Actor.createActor(korbaWife, 173803587, -1, 0, 0)\r\n    Mobile.setMobileVisible(korbaWife,false)\r\n    Mobile.setMobileDirection(korbaWife, 5)\r\n    \r\n    Actor.changeSkin(kabrok, 173603580)\r\n    Camera.setWorldTarget(-12,2,0)\r\n    Camera.setZoomFactor(1.6)\r\n    \r\n    startCine()\r\n    invoke(2000,1,\"kabrokChanging\")\r\nend\n\n-- [FIN] sortie instance\n-- \nfunction event_1984_15796(PlayerId)\n    \nend\n\n","functions":["startCine","endCine","Bubble","event_1984_15794","event_1984_15795","kabrokChanging","KorbaladApparition","kabrokChangingEnd","KorbaWifeApparition","event_1984_15796"],"quest_calls":[],"dialogue_calls":[]},"scenario/1986.lua":{"source":"\n\n-- [Init] Variables\n-- \nfunction event_1986_15803()\n    \nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_1986_15798()\n    \nend\n\n-- [INIT] Entrée dans l'instance - déjà démarré - on affiche le timer\n-- \nfunction event_1986_19067(timerProgress, timerMaxQuest, DongeonStarted)\n    timerProgressVal = toLong(timerProgress)\r\n    timerMaxQuestVal = toLong(timerMaxQuest)\r\n    \r\n    timerSearch = ((timerMaxQuestVal - timerProgressVal)/1000)\r\n    \r\n    if timerSearch >0 then\r\n    \tUI.startCountdown(timerSearch)\r\n    end\nend\n\n-- [Event] Activation IE\n-- \nfunction event_1986_15804(timerProgress, timerMaxQuest, DongeonStarted)\n    timerProgressVal = toLong(timerProgress)\r\n    timerMaxQuestVal = toLong(timerMaxQuest)\r\n    \r\n    if timerProgressVal < timerMaxQuestVal then \r\n    \tTimerOnEnter = (((timerMaxQuestVal) - timerProgressVal)/1000)\r\n    \tUI.startCountdown(TimerOnEnter)\r\n    end\nend\n\n-- [Event] Rafraichissement du timer (logique - invisible)\n-- \nfunction event_1986_15805(timerProgress, timerMaxQuest, DongeonStarted)\n    timerProgressVal = toLong(timerProgress)\r\n    timerMaxQuestVal = toLong(timerMaxQuest)\r\n    playerId = Context.getPlayer()\r\n    timerTable = {}\r\n    timerSearch = 0\r\n    timerText = \"a\"\r\n    timerMinutes = 0\r\n    timerSeconds = 0\r\n    timerMinutesText = \" \"\r\n    timerSecondsText = \" \"\r\n    \r\n    timerSearch = (timerMaxQuestVal -(timerProgressVal))\r\n    \r\n    if timerSearch >0 then\r\n    \t\r\n    \ttimerMinutesMin = math.floor((timerSearch /60000) - 0.5)\r\n    \ttimerMinutesMax = math.ceil((timerSearch /60000) + 0.5)\r\n    \tif timerMinutesMin < 0 then\r\n    \t\ttimerMinutesMin = 0\r\n    \tend\r\n    \ttimerMinutes = math.min(timerMinutesMin, timerMinutesMax)\r\n    \r\n    \ttimerSecondsMax = math.ceil(((timerSearch - (60000*timerMinutes))/1000)+0.5)\r\n    \ttimerSecondsMin = math.floor(((timerSearch - (60000*timerMinutes))/1000)-0.5)\r\n    \tif timerSecondsMin < 0 then\r\n    \t\ttimerSecondsMin = 0\r\n    \tend\r\n    \ttimerSeconds =math.max(timerSecondsMin, timerSecondsMax)\r\n    \t\r\n    \tif timerMinutes < 10 then\r\n    \t\ttimerMinutesText = \"0\"..timerMinutes\r\n    \telse\r\n    \t\ttimerMinutesText = toString(timerMinutes)\r\n    \tend\r\n    \tif timerSeconds < 10 then\r\n    \t\ttimerSecondsText= \"0\"..timerSeconds\r\n    \telse\r\n    \t\ttimerSecondsText = toString(timerSeconds)\r\n    \tend\r\n    \r\n    \ttimerText =  timerMinutesText .. \" : \".. timerSecondsText\t\r\n    \r\n    end\nend\n\n-- [Event] Joueur quitte l'instance (avant fin du décompte)\n-- \nfunction event_1986_15811()\n    UI.stopCountdown()\nend\n\n-- [Event] Joueur gagne (fin du décompte)\n-- \nfunction event_1986_15813()\n    UI.stopCountdown()\nend\n\n-- [Event] Salle 1 - Victoire\n-- \nfunction event_1986_15799()\n    \nend\n\n-- [Event] Salle 2 - Victoire\n-- \nfunction event_1986_15800()\n    \nend\n\n-- [Event] Salle 3 - Victoire\n-- \nfunction event_1986_15801()\n    \nend\n\n-- [Event] Salle 4 - Victoire\n-- \nfunction event_1986_15802()\n    \nend\n\n-- [Event] Echec du Run (temps écoulé - en combat)\n-- \nfunction event_1986_15806()\n    UI.stopCountdown()\r\n    UI.manageFrame(\"World\",false) \nend\n\n-- [Event] Echec du Run (temps écoulé - hors combat)\n-- \nfunction event_1986_16384()\n    UI.stopCountdown()\r\n    UI.manageFrame(\"World\",false) \nend\n\n-- Téléportation des joueurs perdant / abandonnant\n-- \nfunction event_1986_19066()\n    \nend\n\n","functions":["event_1986_15803","event_1986_15798","event_1986_19067","event_1986_15804","event_1986_15805","event_1986_15811","event_1986_15813","event_1986_15799","event_1986_15800","event_1986_15801","event_1986_15802","event_1986_15806","event_1986_16384","event_1986_19066"],"quest_calls":[],"dialogue_calls":[]},"scenario/1989.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\nfunction hideMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, false)\r\nend\r\n\r\nfunction showMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, true)\r\nend\n\n-- [INIT] Variables\n-- \nfunction event_1989_15818()\n    \nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_1989_15819(npcId, bossId, doorOpened)\n    local doorOpened = toLong(doorOpened)\r\n    \r\n    if (doorOpened == 1) then\r\n    \tMobile.addMobileCreationCallback(npcId, \"hideMonster\", npcId)\r\n    else\r\n    \tMobile.addMobileCreationCallback(bossId, \"hideMonster\", bossId)\r\n    end\nend\n\n-- [EVENT] ZoneTrigger - Le joueur marche dans le vide\n-- \nfunction event_1989_15828()\n    \nend\n\n-- [EVENT] ZoneTrigger - Le joueur est TP\n-- \nfunction event_1989_15896()\n    \nend\n\n-- [EVENT] Combat lancé - Désactivation de la ZoneTrigger\n-- \nfunction event_1989_15893()\n    \nend\n\n-- [EVENT] Placement terminé - Réactivation de la ZoneTrigger\n-- \nfunction event_1989_15894()\n    \nend\n\n-- [EVENT] Boss - Victoire\n-- \nfunction event_1989_15826()\n    \nend\n\n-- Défaite des Joueurs -  Stockage de l'ID des players\n-- \nfunction event_1989_15870()\n    \nend\n\n-- Abandon d'un joueur - Stockage de l'ID du player\n-- \nfunction event_1989_15871()\n    \nend\n\n-- [COMBAT][Achievement] Un joueur tombe KO\n-- \nfunction event_1989_15889()\n    \nend\n\n-- [COMBAT][Achievement] Aucun joueur tombe KO + Victoire des joueurs\n-- \nfunction event_1989_15890()\n    \nend\n\n-- DIALOG_EXECUTED - Apparition du Serre d'Acier\n-- \nfunction event_1989_22010(bossId, npcId)\n    function customSkip()\r\n    \tUI.displayWideScreenBand(true, 25, 300)\r\n    \tMobile.addMobileCreationCallback(npcId, \"hideMonster\", npcId)\r\n    \tMobile.addMobileCreationCallback(bossId, \"showMonster\", bossId)\r\n    \tskipCinematic(22010)\r\n    end\r\n    \r\n    ---------------------------------\r\n    \r\n    startCinematicContext(1.2, npcId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"customSkip\")\r\n    \r\n    -- \"Je compte sur vous !\"\r\n    invoke_custom(00500, 1, \"Sound.playSound\", 310101101151303, true, 40)\r\n    invoke_custom(00500, 1, \"bubble\", npcId, \"steel.beak.01\")\r\n    invoke_custom(02500, 1, \"Mobile.setMobileAnimation\", npcId, \"AnimSort-Saut\")\r\n    invoke_custom(03000, 1, \"clearBubbles\", npcId)\r\n    \r\n    invoke_custom(03300, 1, \"UI.displayWideScreenBand\", true, 100, 300)\r\n    invoke_custom(05000, 1, \"Mobile.addMobileCreationCallback\", npcId, \"hideMonster\", npcId)\r\n    invoke_custom(05000, 1, \"Mobile.addMobileCreationCallback\", bossId, \"showMonster\", bossId)\r\n    invoke_custom(05000, 1, \"Camera.attachCameraToMobile\", bossId)\r\n    \r\n    invoke_custom(05500, 1, \"UI.displayWideScreenBand\", true, 25, 300)\r\n    invoke_custom(05500, 1, \"Mobile.setMobileAnimation\", bossId, \"AnimSort-Envol-Fin\")\r\n    \r\n    -- \"Kabrok !!! Où es-tu, imposteur ? Viens te battre !\"\r\n    invoke_custom(06000, 1, \"Sound.playSound\", 320001020007011, true, 40)\r\n    invoke_custom(06000, 1, \"bubble\", bossId,\"steel.beak.02\")\r\n    invoke_custom(09000, 1, \"clearBubbles\", bossId)\r\n    \r\n    -- \"Je saccagerai Kelba jusqu'à te retrouver et me venger !\"\r\n    invoke_custom(09000, 1, \"Mobile.setMobileAnimation\", bossId, \"AnimSort-Rafale\")\r\n    invoke_custom(09500, 1, \"bubble\", bossId,\"steel.beak.03\")\r\n    invoke_custom(09800, 1, \"Particle.addParticleSystem\", -1436048528, -17, 3, 0)\r\n    invoke_custom(12500, 1, \"clearBubbles\", bossId)\r\n    \r\n     invoke_custom(12500, 1, \"skipCinematic\")\nend\n\n-- CLIENT_TRIGGERED_EVENT - On skip chez tout le monde\n-- \nfunction event_1989_22012(bossId, npcId)\n    UI.displayWideScreenBand(true, 25, 300)\r\n    Mobile.addMobileCreationCallback(npcId, \"hideMonster\", npcId)\r\n    Mobile.addMobileCreationCallback(bossId, \"showMonster\", bossId)\r\n    skipCinematic()\nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","hideMonster","showMonster","event_1989_15818","event_1989_15819","event_1989_15828","event_1989_15896","event_1989_15893","event_1989_15894","event_1989_15826","event_1989_15870","event_1989_15871","event_1989_15889","event_1989_15890","event_1989_22010","customSkip","event_1989_22012"],"quest_calls":[],"dialogue_calls":[]},"scenario/1990.lua":{"source":"\n\n-- [EVENT] Initialisation\n-- \nfunction event_1990_15835()\n    \nend\n\n-- [ACTION] Lancement du combat associé\n-- \nfunction event_1990_15836()\n    \nend\n\n-- [ACTION] Fin de combat gagnant\n-- \nfunction event_1990_15837(GroupId)\n    \nend\n\n-- [ACTION] Fin de combat gagnant - fin scenario\n-- \nfunction event_1990_15838(GroupId)\n    \nend\n\n-- [ACTION] Fin de combat perdant\n-- \nfunction event_1990_15839(GroupId, MobA)\n    \nend\n\n","functions":["event_1990_15835","event_1990_15836","event_1990_15837","event_1990_15838","event_1990_15839"],"quest_calls":[],"dialogue_calls":[]},"scenario/1991.lua":{"source":"\n\n-- [EVENT] Initialisation\n-- \nfunction event_1991_15840()\n    \nend\n\n-- [ACTION] Lancement du combat associé\n-- \nfunction event_1991_15841()\n    \nend\n\n-- [ACTION] Fin de combat gagnant\n-- \nfunction event_1991_15842(GroupId)\n    \nend\n\n-- [ACTION] Fin de combat gagnant - fin scenario\n-- \nfunction event_1991_15843(GroupId)\n    \nend\n\n-- [ACTION] Fin de combat perdant\n-- \nfunction event_1991_15844(GroupId, MobA)\n    \nend\n\n","functions":["event_1991_15840","event_1991_15841","event_1991_15842","event_1991_15843","event_1991_15844"],"quest_calls":[],"dialogue_calls":[]},"scenario/1992.lua":{"source":"\n\n-- [EVENT] Initialisation\n-- \nfunction event_1992_15845()\n    \nend\n\n-- [ACTION] Lancement du combat associé\n-- \nfunction event_1992_15846()\n    \nend\n\n-- [ACTION] Fin de combat gagnant\n-- \nfunction event_1992_15847(GroupId)\n    \nend\n\n-- [ACTION] Fin de combat gagnant - fin scenario\n-- \nfunction event_1992_15848(GroupId)\n    \nend\n\n-- [ACTION] Fin de combat perdant\n-- \nfunction event_1992_15849(GroupId, MobA)\n    \nend\n\n","functions":["event_1992_15845","event_1992_15846","event_1992_15847","event_1992_15848","event_1992_15849"],"quest_calls":[],"dialogue_calls":[]},"scenario/1993.lua":{"source":"\n\n-- [EVENT] Initialisation\n-- \nfunction event_1993_15850()\n    \nend\n\n-- [ACTION] Lancement du combat associé\n-- \nfunction event_1993_15851()\n    \nend\n\n-- [ACTION] Fin de combat gagnant\n-- \nfunction event_1993_15852(GroupId)\n    \nend\n\n-- [ACTION] Fin de combat gagnant - fin scenario\n-- \nfunction event_1993_15853(GroupId)\n    \nend\n\n-- [ACTION] Fin de combat perdant\n-- \nfunction event_1993_15854(GroupId, MobA)\n    \nend\n\n","functions":["event_1993_15850","event_1993_15851","event_1993_15852","event_1993_15853","event_1993_15854"],"quest_calls":[],"dialogue_calls":[]},"scenario/1994.lua":{"source":"\n\n-- [EVENT] Initialisation\n-- \nfunction event_1994_15855()\n    \nend\n\n-- [ACTION] Lancement du combat associé\n-- \nfunction event_1994_15856()\n    \nend\n\n-- [ACTION] Fin de combat gagnant\n-- \nfunction event_1994_15857(GroupId)\n    \nend\n\n-- [ACTION] Fin de combat gagnant - fin scenario\n-- \nfunction event_1994_15858(GroupId)\n    \nend\n\n-- [ACTION] Fin de combat perdant\n-- \nfunction event_1994_15859(GroupId, MobA)\n    \nend\n\n","functions":["event_1994_15855","event_1994_15856","event_1994_15857","event_1994_15858","event_1994_15859"],"quest_calls":[],"dialogue_calls":[]},"scenario/1995.lua":{"source":"\n\n-- [EVENT] Initialisation\n-- \nfunction event_1995_15860()\n    \nend\n\n-- [ACTION] Lancement du combat associé\n-- \nfunction event_1995_15861()\n    \nend\n\n-- [ACTION] Fin de combat gagnant\n-- \nfunction event_1995_15862(GroupId)\n    \nend\n\n-- [ACTION] Fin de combat gagnant - fin scenario\n-- \nfunction event_1995_15863(GroupId)\n    