upId)\n    \nend\n\n-- [ACTION] Fin de combat gagnant - fin scenario\n-- \nfunction event_2002_15909(GroupId)\n    \nend\n\n-- [ACTION] Fin de combat perdant\n-- \nfunction event_2002_15910(GroupId, MobA)\n    \nend\n\n","functions":["event_2002_15906","event_2002_15907","event_2002_15908","event_2002_15909","event_2002_15910"],"quest_calls":[],"dialogue_calls":[]},"scenario/2003.lua":{"source":"\n\n-- [EVENT] Initialisation\n-- \nfunction event_2003_15911()\n    \nend\n\n-- [ACTION] Lancement du combat associé\n-- \nfunction event_2003_15912()\n    \nend\n\n-- [ACTION] Fin de combat gagnant\n-- \nfunction event_2003_15913(GroupId)\n    \nend\n\n-- [ACTION] Fin de combat gagnant - fin scenario\n-- \nfunction event_2003_15914(GroupId)\n    \nend\n\n-- [ACTION] Fin de combat perdant\n-- \nfunction event_2003_15915(GroupId, MobA)\n    \nend\n\n","functions":["event_2003_15911","event_2003_15912","event_2003_15913","event_2003_15914","event_2003_15915"],"quest_calls":[],"dialogue_calls":[]},"scenario/2004.lua":{"source":"\n\n-- [EVENT] Initialisation\n-- \nfunction event_2004_15916()\n    \nend\n\n-- [ACTION] Lancement du combat associé\n-- \nfunction event_2004_15917()\n    \nend\n\n-- [ACTION] Fin de combat gagnant\n-- \nfunction event_2004_15918(GroupId)\n    \nend\n\n-- [ACTION] Fin de combat gagnant - fin scenario\n-- \nfunction event_2004_15919(GroupId)\n    \nend\n\n-- [ACTION] Fin de combat perdant\n-- \nfunction event_2004_15920(GroupId, MobA)\n    \nend\n\n","functions":["event_2004_15916","event_2004_15917","event_2004_15918","event_2004_15919","event_2004_15920"],"quest_calls":[],"dialogue_calls":[]},"scenario/2005.lua":{"source":"\n\n-- [EVENT] Initialisation\n-- \nfunction event_2005_15921()\n    \nend\n\n-- [ACTION] Lancement du combat associé\n-- \nfunction event_2005_15922()\n    \nend\n\n-- [ACTION] Fin de combat gagnant\n-- \nfunction event_2005_15923(GroupId)\n    \nend\n\n-- [ACTION] Fin de combat gagnant - fin scenario\n-- \nfunction event_2005_15924(GroupId)\n    \nend\n\n-- [ACTION] Fin de combat perdant\n-- \nfunction event_2005_15925(GroupId, MobA)\n    \nend\n\n","functions":["event_2005_15921","event_2005_15922","event_2005_15923","event_2005_15924","event_2005_15925"],"quest_calls":[],"dialogue_calls":[]},"scenario/2006.lua":{"source":"\n\n-- [EVENT] Initialisation\n-- \nfunction event_2006_15926()\n    \nend\n\n-- [ACTION] Lancement du combat associé\n-- \nfunction event_2006_15927()\n    \nend\n\n-- [ACTION] Fin de combat gagnant\n-- \nfunction event_2006_15928(GroupId)\n    \nend\n\n-- [ACTION] Fin de combat gagnant - fin scenario\n-- \nfunction event_2006_15929(GroupId)\n    \nend\n\n-- [ACTION] Fin de combat perdant\n-- \nfunction event_2006_15930(GroupId, MobA)\n    \nend\n\n","functions":["event_2006_15926","event_2006_15927","event_2006_15928","event_2006_15929","event_2006_15930"],"quest_calls":[],"dialogue_calls":[]},"scenario/2007.lua":{"source":"\n\n-- [EVENT] Initialisation\n-- \nfunction event_2007_15931()\n    \nend\n\n-- [ACTION] Lancement du combat associé\n-- \nfunction event_2007_15932()\n    \nend\n\n-- [ACTION] Fin de combat gagnant\n-- \nfunction event_2007_15933(GroupId)\n    \nend\n\n-- [ACTION] Fin de combat gagnant - fin scenario\n-- \nfunction event_2007_15934(GroupId)\n    \nend\n\n-- [ACTION] Fin de combat perdant\n-- \nfunction event_2007_15935(GroupId, MobA)\n    \nend\n\n","functions":["event_2007_15931","event_2007_15932","event_2007_15933","event_2007_15934","event_2007_15935"],"quest_calls":[],"dialogue_calls":[]},"scenario/2009.lua":{"source":"function displayPath(room)\r\n\tlocal room = toLong(room)\r\n\r\n\tWorld.setPictoAlpha(20, -28, 31, 0, 1000)\r\n\t\r\n\tif ( room >= 1 or room == -1 ) then\r\n\tend\r\n\t\r\n\tif ( room >= 2 or room == -1 ) then\r\n\t\tWorld.setPictoAlpha(26, -14, 7, 0, 1000)\r\n\t\tWorld.setPictoAlpha(27, -14, 7, 0, 1000)\r\n\tend\r\n\t\r\n\tif ( room >= 3 or room == -1) then\r\n\t\tWorld.setPictoAlpha(20, -28, 31, 1, 1000)\r\n\tend\r\nend\n\n-- [INIT] Variables Globales\n-- \nfunction event_2009_18433()\n    \nend\n\n-- [INIT] Inscription du joueur + Variables Locales\n-- \nfunction event_2009_18434(room)\n    displayPath(room)\nend\n\n-- *[OLD][1] Victoire - Déverouille le passage vers S2\n-- \nfunction event_2009_18435(room)\n    displayPath(room)\nend\n\n-- USER_GROUP_KILLED - Salle 01\n-- \nfunction event_2009_18436(room)\n    displayPath(room)\nend\n\n-- USER_GROUP_KILLED - Salle 02\n-- \nfunction event_2009_18437(room)\n    displayPath(room)\nend\n\n-- USER_GROUP_KILLED - Salle 03\n-- \nfunction event_2009_18438()\n    \nend\n\n-- Déplace le joueur vers la salle suivante\n-- \nfunction event_2009_18439()\n    \nend\n\n-- [ARCHI] Apparition de l'Archimonstre\n-- \nfunction event_2009_23963()\n    \nend\n\n","functions":["displayPath","event_2009_18433","event_2009_18434","event_2009_18435","event_2009_18436","event_2009_18437","event_2009_18438","event_2009_18439","event_2009_23963"],"quest_calls":[],"dialogue_calls":[]},"scenario/2010.lua":{"source":"\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2010_15955()\n    \nend\n\n-- Retrait de la propriété IN_ARENA_INSTANCE\n-- \nfunction event_2010_16050()\n    \nend\n\n-- Création du combat après acceptation de la requête\n-- \nfunction event_2010_16051()\n    \nend\n\n","functions":["event_2010_15955","event_2010_16050","event_2010_16051"],"quest_calls":[],"dialogue_calls":[]},"scenario/2014.lua":{"source":"\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2014_15983()\n    local playerId = Context.getLeaderId()\r\n    \r\n    function animChute(playerId)\r\n    \tMobile.setMobileVisible(playerId, true)\r\n    \tMobile.setMobileDirection(playerId, 7)\r\n    \tMobile.setMobileAnimation(playerId, \"AnimIncarnam-Chute-Fin\", \"animEnd\", playerId)\r\n    end\r\n    \r\n    function animEnd(playerId)\r\n    \tMobile.setMobileDirection(playerId, 1)\r\n    \tUI.manageFrame(\"World\",true)\r\n    end\r\n    \r\n    Mobile.setMobileVisible(playerId, false)\r\n    UI.manageFrame(\"World\",false)\r\n    invoke(3200, 1, \"animChute\", playerId)\nend\n\n-- [EVENT] Début du combat - Ajout des états de gameplay\n-- \nfunction event_2014_16053(ko)\n    \nend\n\n","functions":["event_2014_15983","animChute","animEnd","event_2014_16053"],"quest_calls":[],"dialogue_calls":[]},"scenario/2015.lua":{"source":"playerId = Context.getPlayer()\r\n\r\nmatouA = Mobile.generateClientMobileId()\r\nmatouB = Mobile.generateClientMobileId()\r\nmatouC = Mobile.generateClientMobileId()\r\nmatouD = Mobile.generateClientMobileId()\r\nmatouE = Mobile.generateClientMobileId()\r\n\r\nfunction initMatouleaux(matouA,matouB,matouC,matouD,matouE)\r\n\tActor.createActor(matouA, 1300059, -5, -1, 17, 4)\r\n\tActor.createActor(matouB, 1300059, -5, -1, 13, 4)\r\n\tActor.createActor(matouC, 1300059, 0, -1, 8, 4)\r\n\tActor.createActor(matouD, 1300059, 1, -5, 9, 4)\r\n\tActor.createActor(matouE, 1300057, 6, -2, 11, 4)\r\n\tMobile.setMobileDirection(matouA, 5)\r\n\tMobile.setMobileDirection(matouB, 1)\r\n\tMobile.setMobileDirection(matouC, 5)\r\n\tMobile.setMobileDirection(matouD, 5)\r\n\tMobile.setMobileDirection(matouE, 5)\r\n\tMobile.setMobileAnimation(matouA, \"AnimStatique-Proue\")\r\n\tMobile.setMobileAnimation(matouB, \"AnimStatique-Caisse\")\r\n\tMobile.setMobileAnimation(matouC, \"AnimStatique-Mat02\")\r\n\tMobile.setMobileAnimation(matouD, \"AnimStatique-Velo\")\r\n\tMobile.setMobileAnimation(matouE, \"AnimComp-Steamboat\")\r\nend\n\n-- [INIT] Variables\n-- \nfunction event_2015_16014()\n    \nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_2015_15992()\n    function dialMatou(matouE)\r\n    \tmatouBubble = BubbleText.showText(matouE, \"zinit.barquette.04\", 0, 70, false)\r\n    end\r\n    \r\n    function dialMatouD(matouD)\r\n    \tmatouBubbleD = BubbleText.showText(matouD, \"zinit.barquette.05\", 115, 200, false)\r\n    end\r\n    \r\n    function seaEffect()\r\n    \tinstanceId = Context.getPlayerInstanceId()\t\r\n    \tif instanceId==290 then\r\n    \t\tEffect.createCameraSeaSicknessEffect()\r\n    \tend\r\n    end\r\n    \r\n    \r\n    Mobile.setMobileDirection(playerId, 5)\r\n    Mobile.setMobileAnimation(playerId, \"AnimEmote-Chercher\")\r\n    seaEffect()\r\n    initMatouleaux(matouA,matouB,matouC,matouD,matouE)\r\n    Camera.setCamera(1.0, 2, -3, 8)\r\n    Camera.setUserZoomLocked(true)\r\n    \r\n    invoke(2500, 1, \"dialMatou\", matouE)\r\n    invoke(3500, 1, \"dialMatouD\", matouD)\r\n    \r\nend\n\n-- Apparition des monstres + dialogue + création du combat\n-- \nfunction event_2015_15993(mobId, mobTwoId)\n    Mobile.setMobileAnimation(mobId, \"AnimApparition\")\r\n    Mobile.setMobileAnimation(mobTwoId, \"AnimApparition\")\r\n    invoke(500, 1, \"dialMatou\", matouB)\r\n    \r\n    function dialMatou(matouB)\r\n    \tmatouBubble = BubbleText.showText(matouB, \"zinit.barquette.salbatroces\", 50, 70, false)\r\n    end\nend\n\n-- Initialisation de la variable d'ID du combat\n-- \nfunction event_2015_15994()\n    \nend\n\n-- Fin du combat\n-- \nfunction event_2015_15995()\n    invoke(1500, 1, \"dialMatou\", matouB)\r\n    invoke(3000, 1, \"dialMatouC\", matouC)\r\n    \r\n    function dialMatou(matouB)\r\n    \tmatouBubble = BubbleText.showText(matouB, \"zinit.barquette.07\", 50, 70, false)\r\n    end\r\n    \r\n    function dialMatouC(matouC)\r\n    \tmatouBubbleC = BubbleText.showText(matouC, \"zinit.barquette.08\", 20, 330, false)\r\n    end\nend\n\n-- Transition post combat avant la Téléportation\n-- \nfunction event_2015_15996()\n    \nend\n\n-- Téléportation dans la zone suivante\n-- \nfunction event_2015_15997()\n    \nend\n\n-- [COMBAT] Combat - Ajout du Matoulot\n-- \nfunction event_2015_16013()\n    \nend\n\n","functions":["initMatouleaux","event_2015_16014","event_2015_15992","dialMatou","dialMatouD","seaEffect","event_2015_15993","dialMatou","event_2015_15994","event_2015_15995","dialMatou","dialMatouC","event_2015_15996","event_2015_15997","event_2015_16013"],"quest_calls":[],"dialogue_calls":[]},"scenario/2016.lua":{"source":"playerId = Context.getPlayer()\r\n\r\nmatouA = Mobile.generateClientMobileId()\r\nmatouB = Mobile.generateClientMobileId()\r\nmatouC = Mobile.generateClientMobileId()\r\nmatouD = Mobile.generateClientMobileId()\r\nmatouE = Mobile.generateClientMobileId()\r\n\r\nfunction initMatouleaux(matouA,matouB,matouC,matouD,matouE)\r\n\tActor.createActor(matouA, 1300059, -5, -1, 17, 4)\r\n\tActor.createActor(matouB, 1300059, -5, -1, 13, 4)\r\n\tActor.createActor(matouC, 1300059, 0, -1, 8, 4)\r\n\tActor.createActor(matouD, 1300059, 1, -5, 9, 4)\r\n\tActor.createActor(matouE, 1300057, 6, -2, 11, 4)\r\n\tMobile.setMobileDirection(matouA, 5)\r\n\tMobile.setMobileDirection(matouB, 1)\r\n\tMobile.setMobileDirection(matouC, 5)\r\n\tMobile.setMobileDirection(matouD, 5)\r\n\tMobile.setMobileDirection(matouE, 5)\r\n\tMobile.setMobileAnimation(matouA, \"AnimStatique-Proue\")\r\n\tMobile.setMobileAnimation(matouB, \"AnimStatique-Caisse\")\r\n\tMobile.setMobileAnimation(matouC, \"AnimStatique-Mat02\")\r\n\tMobile.setMobileAnimation(matouD, \"AnimStatique-Velo\")\r\n\tMobile.setMobileAnimation(matouE, \"AnimComp-Steamboat\")\r\nend\r\n\r\nfunction initStorm()\r\n\tinstanceId = Context.getPlayerInstanceId()\t\r\n\tif instanceId==304 then\r\n\t\ttimerOne=(math.random(3)+1)*1000\r\n\t\ttimerTwo=(math.random(3)+1)*1000\r\n\t\ttimerThree=(math.random(3)+1)*1000\r\n\t\tinvoke(timerOne, 1, \"Particle.addParticleSystem\",7290009, -15, 14, 0, 0)\t\r\n\t\tinvoke(timerTwo, 1, \"Particle.addParticleSystem\",7290009, -5, 6, 0, 0)\t\r\n\t\tinvoke(timerThree, 1, \"Particle.addParticleSystem\",7290009, 12, 0, 0, 0)\t\r\n\t\tinvoke(timerOne, 1, \"Effect.createCameraShakeEffect\",60,2)\r\n\t\tinvoke(timerTwo, 1, \"Effect.createCameraShakeEffect\",60,2)\t\r\n\t\tinvoke(timerThree, 1, \"Effect.createCameraShakeEffect\",60,2)\t\r\n\t\tinvoke(6000, 1, \"initStorm\")\r\n\tend\r\nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_2016_15998()\n    function dialMatou(matouB)\r\n    \tmatouBubble = BubbleText.showText(matouB, \"zinit.barquette.01\", 50, 70, false)\r\n    end\r\n    \r\n    function dialMatouE(matouE)\r\n    \tmatouBubbleE = BubbleText.showText(matouE, \"zinit.barquette.12\", 0, 60, false)\r\n    end\r\n    \r\n    function seaEffect()\r\n    \tinstanceId = Context.getPlayerInstanceId()\t\r\n    \tif instanceId==304 then\r\n    \t\tEffect.createCameraSeaSicknessEffect()\r\n    \tend\r\n    end\r\n    \r\n    Mobile.setMobileDirection(playerId, 3)\r\n    Mobile.setMobileAnimation(playerId, \"AnimEmote-Vomis\")\r\n    seaEffect()\r\n    initMatouleaux(matouA,matouB,matouC,matouD,matouE)\r\n    Camera.setCamera(1.0, 2, -3, 8)\r\n    Camera.setUserZoomLocked(true)\r\n    initStorm()\r\n    Ambiance.setWeather(0, 3, 1)\r\n    \r\n    invoke(2500, 1, \"dialMatou\", matouB)\r\n    invoke(3000, 1, \"dialMatouE\", matouE)\r\n    \r\nend\n\n-- Apparition des monstres + dialogue + création du combat\n-- \nfunction event_2016_15999(mobId, mobTwoId, mobThreeId)\n    Mobile.setMobileAnimation(mobId, \"AnimApparition\")\r\n    Mobile.setMobileAnimation(mobTwoId, \"AnimApparition\")\r\n    Mobile.setMobileAnimation(mobThreeId, \"AnimApparition\")\nend\n\n-- Initialisation de la variable d'ID du combat\n-- \nfunction event_2016_16000()\n    \nend\n\n-- Fin du combat\n-- \nfunction event_2016_16001()\n    function dialMatou(matouB)\r\n    \tmatouBubble = BubbleText.showText(matouB, \"zinit.barquette.13\", 50, 70, false)\r\n    end\r\n    \r\n    invoke(1500, 1, \"dialMatou\", matouB)\r\n    \r\nend\n\n-- Transition post combat avant la Téléportation\n-- \nfunction event_2016_16002()\n    \nend\n\n-- Téléportation dans la zone suivante\n-- \nfunction event_2016_16003()\n    \nend\n\n-- Lancement du combat de la salle 01\n-- \nfunction event_2016_16004()\n    \nend\n\n","functions":["initMatouleaux","initStorm","event_2016_15998","dialMatou","dialMatouE","seaEffect","event_2016_15999","event_2016_16000","event_2016_16001","dialMatou","event_2016_16002","event_2016_16003","event_2016_16004"],"quest_calls":[],"dialogue_calls":[]},"scenario/2018.lua":{"source":"playerId = Context.getPlayer()\r\n\r\nmatouA = Mobile.generateClientMobileId()\r\nmatouB = Mobile.generateClientMobileId()\r\nmatouC = Mobile.generateClientMobileId()\r\nmatouD = Mobile.generateClientMobileId()\r\nmatouE = Mobile.generateClientMobileId()\r\n\r\nfunction initMatouleaux(matouA,matouB,matouC,matouD,matouE)\r\n\tActor.createActor(matouA, 1300059, -5, -1, 17, 4)\r\n\tActor.createActor(matouB, 1300059, -5, -1, 13, 4)\r\n\tActor.createActor(matouC, 1300059, 0, -1, 8, 4)\r\n\tActor.createActor(matouD, 1300059, 1, -5, 9, 4)\r\n\tActor.createActor(matouE, 1300057, 6, -2, 11, 4)\r\n\tMobile.setMobileDirection(matouA, 5)\r\n\tMobile.setMobileDirection(matouB, 1)\r\n\tMobile.setMobileDirection(matouC, 5)\r\n\tMobile.setMobileDirection(matouD, 5)\r\n\tMobile.setMobileDirection(matouE, 5)\r\n    Mobile.setMobileAnimation(matouA, \"AnimStatique-Proue\")\r\n\tMobile.setMobileAnimation(matouB, \"AnimStatique-Caisse\")\r\n\tMobile.setMobileAnimation(matouC, \"AnimStatique-Mat02\")\r\n\tMobile.setMobileAnimation(matouD, \"AnimStatique-Velo\")\r\n\tMobile.setMobileAnimation(matouE, \"AnimComp-Steamboat\")\r\nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_2018_16007()\n    function dialMatou(matouB)\r\n    \tmatouBubble = BubbleText.showText(matouB, \"zinit.barquette.pirate.1\", 55, 70, false)\r\n    end\r\n    \r\n    function seaEffect()\r\n    \tinstanceId = Context.getPlayerInstanceId()\t\r\n    \tif instanceId==303 then\r\n    \t\tEffect.createCameraSeaSicknessEffect()\r\n    \tend\r\n    end\r\n    \r\n    \r\n    Mobile.setMobileDirection(playerId, 7)\r\n    seaEffect()\r\n    initMatouleaux(matouA,matouB,matouC,matouD,matouE)\r\n    Camera.setCamera(0.2, 1, -4, 8)\r\n    Camera.setUserZoomLocked(true)\r\n    \r\n    invoke(2500, 1, \"dialMatou\", matouB)\r\n    \r\nend\n\n-- Apparition des monstres + dialogue + création du combat\n-- \nfunction event_2018_16008(mobId, mobTwoId)\n    function dialMatou(matouB)\r\n    \tmatouBubble = BubbleText.showText(matouB, \"zinit.barquette.pirate.2\", 55, 70, false)\r\n    end\r\n    \r\n    function dialMatouD(matouD)\r\n    \tmatouBubble = BubbleText.showText(matouD, \"zinit.barquette.pirate.velohelice\", 70, 200, false)\r\n    end\r\n    \r\n    Mobile.setMobileAnimation(mobId, \"AnimApparition\")\r\n    Mobile.setMobileAnimation(mobTwoId, \"AnimApparition\")\r\n    \r\n    invoke(2000, 1, \"dialMatou\", matouB)\r\n    invoke(10000,1,\"dialMatouD\", matouD)\r\n    \r\n    \r\n    \r\nend\n\n-- Initialisation de la variable d'ID du combat\n-- \nfunction event_2018_16009()\n    \nend\n\n-- Fin du combat\n-- \nfunction event_2018_16010()\n    function dialMatou(matouC)\r\n    \tmatouBubbleC = BubbleText.showText(matouC, \"zinit.barquette.11\", 115, 200, false)\r\n    end\r\n    \r\n    invoke(1500, 1, \"dialMatouC\", matouC)\r\n    \r\nend\n\n-- Transition post combat avant la Téléportation\n-- \nfunction event_2018_16011()\n    \nend\n\n-- Téléportation dans la zone suivante\n-- \nfunction event_2018_16012()\n    \nend\n\n","functions":["initMatouleaux","event_2018_16007","dialMatou","seaEffect","event_2018_16008","dialMatou","dialMatouD","event_2018_16009","event_2018_16010","dialMatou","event_2018_16011","event_2018_16012"],"quest_calls":[],"dialogue_calls":[]},"scenario/2019.lua":{"source":"playerId = Context.getPlayer()\r\n\r\n\r\nfunction startCine()\r\n\tzoomFactor = Camera.getZoomFactor()\r\n\tUI.manageFrame(\"World\",false) \t\t\t\t\t\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\t\t\t\t\t\t\t\t\t\t\t\t\r\n\tUI.manageFrame(\"World\",false) \t\t\t\t\t\r\n\tUI.setUIVisible(false)\t\r\n\tUI.displayWideScreenBand(true)\r\nend\r\n\r\nfunction endCine()\r\n\tCamera.attachCameraToMobile(playerId)\r\n\tUI.displayWideScreenBand(false)\r\n\tCamera.setUserZoomLocked(false)\t\t\t\t\t\t\t\t\t\t\t\t\r\n\tUI.setUIVisible(true)\t\r\n\tUI.manageFrame(\"World\",true) \t\t\t\t\r\n\tCamera.setZoomFactor(zoomFactor)\t\r\nend\r\n\r\nfunction MindBubbleStart(mob,text,tDuration)\r\n\tMindBubble=BubbleText.showText(mob, text, 0, 40, false)\r\n\tinvoke(tDuration,1,\"BubbleText.close\",MindBubble)\r\nend\r\n\r\nparticleDrill = 0\n\n-- [INITIALISATION] Serveur\n-- \nfunction event_2019_16016()\n    \nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_2019_16017(PorteA, DrillActive, BossFight)\n    PorteA = toLong(PorteA)\r\n    DrillActive= toLong(DrillActive)\r\n    BossFight = toLong(BossFight)\r\n    \r\n    if PorteA == 1 then\r\n    \tWorld.setPictoAlpha(37, -8, -1, 0, 1000)\r\n    \tWorld.setPictoAlpha(56, 5, -1, 0, 1000)\r\n    end\r\n    \r\n    if DrillActive == 1 and  BossFight == 0 then\r\n    \tparticleDrill = Particle.addParticleSystem(800557, 54, -24, -15)\r\n    \tParticle.setRemoveWhenFar(particleDrill, false)\r\n    end\r\nend\n\n-- [SALLE 01] Victoire - On déverouille la porte\n-- \nfunction event_2019_16019(PorteA)\n    \nend\n\n-- [SALLE 01] Victoire - La porte est ouverte\n-- \nfunction event_2019_16020()\n    \tWorld.setPictoAlpha(37, -8, -1, 0, 1000)\r\n    \tWorld.setPictoAlpha(56, 5, -1, 0, 1000)\nend\n\n-- [SALLE 02] Victoire - On diffère l'obtention de la clé de la foreuse après avoir tué le bon groue de mobs\n-- \nfunction event_2019_16021()\n    \nend\n\n-- [SALLE 02] Victoire - Obtention de la clef de la foreuse\n-- \nfunction event_2019_16022()\n    playerId = Context.getPlayer()\r\n    MindBubbleStart(playerId,\"quest.zinitplage.CineDungeon.FeedbackKey\",4000)\nend\n\n-- [SALLE 03] ACTIVATION Foreuse\n-- \nfunction event_2019_16038()\n    \nend\n\n-- [SALLE 03] Foreuse activée (cinématique) APPARITION BOSS\n-- \nfunction event_2019_16039(BossGroupId, BossId, BossAddOne, BossAddTwo, BossAddThree, BossAddFour, BossAddFive, BossAddSix)\n    --Initialisation\r\n    playerId = Context.getPlayer()\r\n    BossId = toLong(BossId)\r\n    BossAddOne = toLong(BossAddOne)\r\n    BossAddTwo = toLong(BossAddTwo)\r\n    BossAddThree = toLong(BossAddThree)\r\n    BossAddFour = toLong(BossAddFour)\r\n    BossAddFive = toLong(BossAddFive)\r\n    BossAddSix = toLong(BossAddSix)\r\n    \r\n    --Début de la ciné\r\n    startCine()\r\n    particleDrill = Particle.addParticleSystem(800557, 54, -24, -15)\r\n    Particle.setRemoveWhenFar(particleDrill, false)\r\n    Mobile.setMobilePosition(BossId, 47, -7, -7)\r\n    Mobile.setMobilePosition(BossAddOne, 46, -6, -7)\r\n    Mobile.setMobilePosition(BossAddTwo, 46, -8, -7)\r\n    Mobile.setMobilePosition(BossAddThree, 46, -7, -7)\r\n    Mobile.setMobilePosition(BossAddFour, 45, -7, -7)\r\n    Mobile.setMobilePosition(BossAddFive, 45, -6, -7)\r\n    Mobile.setMobilePosition(BossAddSix, 45, -8, -7)\r\n    Camera.attachCameraToMobile(BossId)\r\n    Mobile.moveMobile(BossId, 53, -7, -7)\r\n    Mobile.moveMobile(BossAddOne, 55, -5, -7)\r\n    Mobile.moveMobile(BossAddTwo, 55, -7, -7)\r\n    Mobile.moveMobile(BossAddThree, 55, -9, -7)\r\n    Mobile.moveMobile(BossAddFour, 53, -9, -7)\r\n    Mobile.moveMobile(BossAddFive, 53, -5, -7)\r\n    Mobile.moveMobile(BossAddSix, 51, -7, -7)\r\n    MindBubbleStart(BossId,\"quest.zinitplage.CineDungeon.boss.01\",5000)\r\n    invoke(5000, 1, \"endCine\" )\nend\n\n-- [SALLE 03] Victoire contre le BOSS\n-- \nfunction event_2019_16023()\n    \nend\n\n-- [SALLE 03] on ouvre le passage SORTIE (cinématique)\n-- \nfunction event_2019_16024(DrillActive)\n    --52/-27/-14\r\n    \tWorld.setPictoAlpha(52, -27, -2, 0, 1000)\r\n    \tWorld.setPictoAlpha(52, -27, 10, 0, 1000)\r\n    --53/-27/-14\r\n    \tWorld.setPictoAlpha(53, -27, -2, 0, 1000)\r\n    \tWorld.setPictoAlpha(53, -27, 10, 0, 1000)\r\n    --54/-27/-14\r\n    \tWorld.setPictoAlpha(54, -27, -2, 0, 1000)\r\n    \tWorld.setPictoAlpha(54, -27, 10, 0, 1000)\r\n    --55/-27/-14\r\n    \tWorld.setPictoAlpha(55, -27, -2, 0, 1000)\r\n    \tWorld.setPictoAlpha(55, -27, 10, 0, 1000)\r\n    --56/-27/-14\r\n    \tWorld.setPictoAlpha(56, -27, -2, 0, 1000)\r\n    \tWorld.setPictoAlpha(56, -27, 10, 0, 1000)\r\n    \t\r\n    startCine()\r\n    Camera.setCamera(1, 54, -27, -15)\r\n    \r\n    invoke(3000, 1, \"endCine\" )\r\n    invoke(3000, 1, \"Particle.removeParticleSystem\",particleDrill,true)\r\n    Effect.createCameraShakeEffect(200,1500, 200, 1)\nend\n\n","functions":["startCine","endCine","MindBubbleStart","event_2019_16016","event_2019_16017","event_2019_16019","event_2019_16020","event_2019_16021","event_2019_16022","event_2019_16038","event_2019_16039","event_2019_16023","event_2019_16024"],"quest_calls":[],"dialogue_calls":[]},"scenario/2021.lua":{"source":"playerId = Context.getPlayer()\r\n\r\n\r\nfunction startCine()\r\n\tzoomFactor = Camera.getZoomFactor()\r\n\tUI.manageFrame(\"World\",false) \t\t\t\t\t\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\t\t\t\t\t\t\t\t\t\t\t\t\r\n\tUI.manageFrame(\"World\",false) \t\t\t\t\t\r\n\tUI.setUIVisible(false)\t\r\n\tUI.displayWideScreenBand(true)\r\nend\r\n\r\nfunction endCine()\r\n\tCamera.attachCameraToMobile(playerId)\r\n\tUI.displayWideScreenBand(false)\r\n\tCamera.setUserZoomLocked(false)\t\t\t\t\t\t\t\t\t\t\t\t\r\n\tUI.setUIVisible(true)\t\r\n\tUI.manageFrame(\"World\",true) \t\t\t\t\r\n\tCamera.setZoomFactor(zoomFactor)\t\r\nend\r\n\r\nfunction MindBubbleStart(mob,text,tDuration)\r\n\tMindBubble=BubbleText.showText(mob, text, 0, 40, false)\r\n\tinvoke(tDuration,1,\"BubbleText.close\",MindBubble)\r\nend\n\n-- Initialisation serveur\n-- \nfunction event_2021_16045()\n    \nend\n\n-- [INIT] Inscription - Le joueur arrive via le bateau ou le TP astrub\n-- \nfunction event_2021_16046(Barrierebateau)\n    passerelle = toLong(Barrierebateau)\r\n    \r\n    \r\n    if passerelle==1 then\r\n    \tWorld.setPictoAlpha(0, 1, 3, 0, 500)\r\n    \r\n    end\nend\n\n-- [INIT] Inscription - Le joueur arrive par le portail de la plage du Zinit\n-- \nfunction event_2021_16093(Barrierebateau)\n    \tWorld.setPictoAlpha(0, 1, 3, 0, 500)\nend\n\n-- [EVENT] Cinématique d'arrivée sur les récifs\n-- \nfunction event_2021_16066(pnj)\n    --Initialisation\r\n    playerId = Context.getPlayer()\r\n    pnj = toLong(pnj)\r\n    \r\n    --Début de la ciné\r\n    startCine()\r\n    Camera.attachCameraToMobile(pnj)\r\n    MindBubbleStart(pnj,\"quest.Zinitrecif.Cinebateau.MatouMeuplet\",5000)\r\n    invoke(5000, 1, \"endCine\" )\nend\n\n-- [EVENT] Ouvre la porte du bateau\n-- \nfunction event_2021_16078(Barrierebateau)\n    passerelle = toLong(Barrierebateau)\r\n    \r\n    \tWorld.setPictoAlpha(0, 1, 3, 0, 500)\r\nend\n\n-- [EVENT] Salle 1 - End\n-- \nfunction event_2021_16047(fight1)\n    \nend\n\n-- [EVENT] Salle 2 - End\n-- \nfunction event_2021_16048(fight1)\n    \nend\n\n-- [EVENT] Salle 3 - End\n-- \nfunction event_2021_16049(fight1)\n    \nend\n\n-- [EVENT] TP vers Astrub\n-- \nfunction event_2021_16052()\n    \nend\n\n","functions":["startCine","endCine","MindBubbleStart","event_2021_16045","event_2021_16046","event_2021_16093","event_2021_16066","event_2021_16078","event_2021_16047","event_2021_16048","event_2021_16049","event_2021_16052"],"quest_calls":[],"dialogue_calls":[]},"scenario/2026.lua":{"source":"function startCine()\r\n\tzoomFactor = Camera.getZoomFactor()\r\n\tUI.manageFrame(\"World\",false) \t\t\t\t\t\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\t\t\t\t\t\t\t\t\t\t\t\t\r\n\tUI.manageFrame(\"World\",false) \t\t\t\t\t\r\n\tUI.setUIVisible(false)\t\r\n\tUI.displayWideScreenBand(true)\r\nend\r\n\r\nfunction endCine()\r\n\tlocal playerId = Context.getLeaderId()\r\n\t\r\n\tCamera.attachCameraToMobile(playerId)\r\n\tUI.displayWideScreenBand(false)\r\n\tCamera.setUserZoomLocked(false)\t\t\t\t\t\t\t\t\t\t\t\t\r\n\tUI.setUIVisible(true)\t\r\n\tUI.manageFrame(\"World\",true) \t\t\t\t\r\n\tCamera.setZoomFactor(zoomFactor)\t\r\n\tSound.stopForcedMusic()\r\nend\r\n\r\nfunction MindBubbleStart(mob,text,tDuration)\r\n\tMindBubble=BubbleText.showText(mob, text, 0, 40, false)\r\n\tinvoke(tDuration,1,\"BubbleText.close\",MindBubble)\r\nend\r\n\r\nfunction MindBubbleChef(mob,text,tDuration)\r\n\tMindBubble=BubbleText.showText(mob, text, 0, 80, false)\r\n\tinvoke(tDuration,1,\"BubbleText.close\",MindBubble)\r\nend\r\n\n\n-- [INIT] ENTER_INSTANCE - Cinématique Camp du Culte\n-- \nfunction event_2026_16079()\n    -- Définition variables et invocations\n    \n    playerId = Context.getLeaderId()\n    Chef = Mobile.generateClientMobileId()\n    Actor.createActor(Chef, 178603773, 1, -8, -1, 4)\n    DechiqueteurB = Mobile.generateClientMobileId()\n    Actor.createActor(DechiqueteurB, 178603778, 1, -10, 0, 4)\n    DechiqueteurA = Mobile.generateClientMobileId()\n    Actor.createActor(DechiqueteurA, 178603778, 1, -6, 0, 4)\n    GrouilleuxA = Mobile.generateClientMobileId()\n    Actor.createActor(GrouilleuxA, 165303235, 0, -13, 0, 4)\n    Mobile.setMobileDirection(GrouilleuxA, 3)\n    GrouilleuxB = Mobile.generateClientMobileId()\n    Actor.createActor(GrouilleuxB, 165303235, 1, -13, 0, 4)\n    Mobile.setMobileDirection(GrouilleuxB, 3)\n    GrouilleuxC = Mobile.generateClientMobileId()\n    Actor.createActor(GrouilleuxC, 165303235, 0, -14, 0, 4)\n    Mobile.setMobileDirection(GrouilleuxC, 3)\n    GrouilleuxD = Mobile.generateClientMobileId()\n    Actor.createActor(GrouilleuxD, 165303235, 1, -14, 0, 4)\n    Mobile.setMobileDirection(GrouilleuxD, 3)\n    \n    -- Fonctions\n    \n    function MovePlayer()\n    --Mobile.moveMobile(playerId, 22,-10, 0)\n    invoke(1000,1,\"MindBubbleChef\",playerId, \"quest.Zinitplage.Cineculte.playerId.01\",2500)\n    invoke(3500, 1, \"Camera.setWorldTarget\",-1, -9, 0)\n    invoke(5000, 1, \"Chefordres\")\n    end\n    \n    function Chefordres()\n    Mobile.setMobileAnimation(Chef, \"AnimComp-Dialogue-01\")\n    MindBubbleChef(Chef,\"quest.Zinitplage.Cineculte.Gankr.01\",4000)\n    invoke(4000, 1, \"GrouilleuxAbougeetparle\")\n    end\n    \n    function GrouilleuxAbougeetparle()\n    Mobile.moveMobile(GrouilleuxA, 2, -11, -0)\n    invoke(1000,1,\"Mobile.moveMobile\", GrouilleuxA, 2, -8, -1)\n    invoke(1000,1,\"MindBubbleStart\",GrouilleuxA, \"quest.Zinitplage.Cineculte.GrouilleuxA.01\",2000)\n    invoke(3000,1, \"Mobile.setMobileDirection\", GrouilleuxA, 5)\n    invoke(3000,1,\"MindBubbleStart\",GrouilleuxA, \"quest.Zinitplage.Cineculte.GrouilleuxA.02\",4000)\n    invoke(7000,1, \"Chefparleettue\")\n    end\n    \n    function Chefparleettue()\n    Mobile.setMobileAnimation(Chef, \"AnimComp-Dialogue-01\")\n    MindBubbleChef(Chef, \"quest.Zinitplage.Cineculte.Gankr.02\",1000)\n    invoke(1000,1,\"Mobile.setMobileAnimation\", Chef, \"AnimComp-03\")\n    invoke(1800,1,\"Particle.addParticleSystem\",1016314, 2, -8, -1)\n    invoke(2400,1,\"Mobile.setMobileAnimation\", GrouilleuxA, \"AnimMort\")\n    invoke(2500,1,\"Particle.addParticleSystem\",800090, 2, -8, -1)\n    invoke(4000,1,\"Mobile.setMobileVisible\",GrouilleuxA, false)\n    invoke(4000,1, \"Actor.deleteActor\", GrouilleuxA)\n    invoke(2800,1,\"Mobile.setMobileAnimation\", Chef, \"AnimComp-Dialogue-01\")\n    invoke(2800,1,\"MindBubbleChef\", Chef, \"quest.Zinitplage.Cineculte.Gankr.03\",3000)\n    invoke(6300,1, \"DechiqueteurAparle\")\n    end\n    \n    function DechiqueteurAparle()\n    Mobile.setMobileDirection(DechiqueteurA, 3)\n    invoke(2400,1,\"Mobile.setMobileDirection\",DechiqueteurA, 1)\n    invoke(2500,1,\"Mobile.setMobileDirection\",DechiqueteurA, 7)\n    invoke(3000,1,\"MindBubbleChef\",DechiqueteurA, \"quest.Zinitplage.Cineculte.DechiqueteurA.01\",5000)\n    invoke(6500,1,\"Mobile.setMobileDirection\",Chef, 3)\n    invoke(8000, 1, \"Chefparleetpart\")\n    end\n    \n    function Chefparleetpart()\n    Mobile.setMobileDirection(Chef, 1)\n    invoke(100,1,\"Mobile.setMobileDirection\", Chef, 7)\n    invoke(500,1,\"Mobile.setMobileAnimation\", Chef, \"AnimComp-Dialogue-01\")\n    invoke(500,1,\"MindBubbleChef\", Chef, \"quest.Zinitplage.Cineculte.Gankr.04\",3000)\n    invoke(3500,1,\"Mobile.setMobileAnimation\", Chef, \"AnimComp-Dialogue-01\")\n    invoke(3500,1,\"MindBubbleChef\", Chef, \"quest.Zinitplage.Cineculte.Gankr.05\",3000)\n    invoke(6000, 1, \"DechiqueteurBordres\")\n    end\n    \n    function DechiqueteurBordres()\n    Mobile.setMobileDirection(DechiqueteurB, 7)\n    invoke(400,1,\"Mobile.setMobileDirection\", DechiqueteurA, 1)\n    invoke(400,1,\"Mobile.setMobileDirection\", Chef, 1)\n    invoke(500,1,\"Mobile.moveMobile\",DechiqueteurA, -1, 2, 0)\n    invoke(500,1,\"Mobile.moveMobile\",Chef, -1, 2, 0)\n    invoke(500,1,\"MindBubbleChef\",DechiqueteurB, \"quest.Zinitplage.Cineculte.DechiqueteurB.01\",3500)\n    invoke(4000, 1, \"Tousdanslagrotte\")\n    end\n    \n    function Tousdanslagrotte()\n    World.setPictoAlpha(0, -15, 16, 0, 500)\n    invoke(500,1,\"Mobile.moveMobile\",GrouilleuxB, 0, -14, 0)\n    invoke(500,1,\"Mobile.moveMobile\",GrouilleuxC, 0, -14, 0)\n    invoke(500,1,\"Mobile.moveMobile\",GrouilleuxD, 0, -14, 0)\n    invoke(500,1,\"Mobile.moveMobile\",DechiqueteurB, 0, -14, 0)\n    invoke(1500,1,\"Mobile.setMobileVisible\",GrouilleuxB, false)\n    invoke(1500,1,\"Mobile.setMobileVisible\",GrouilleuxC, false)\n    invoke(1500,1,\"Mobile.setMobileVisible\",GrouilleuxD, false)\n    invoke(2000,1,\"Mobile.setMobileVisible\",DechiqueteurB, false)\n    invoke(1500,1, \"Actor.deleteActor\", GrouilleuxA)\n    invoke(1500,1, \"Actor.deleteActor\", GrouilleuxB)\n    invoke(1500,1, \"Actor.deleteActor\", GrouilleuxC)\n    invoke(2000,1, \"Actor.deleteActor\", DechiqueteurB)\n    invoke(3000,1,\"World.setPictoAlpha\",0, -15, 16, 100, 500)\n    invoke(4000, 1, \"endCine\" )\n    end\n    \n    startCine()\n    Sound.playForcedMusic(210024)\n    Camera.setZoomFactor(1.5)\n    \t\n    invoke(1000, 1, \"MovePlayer\")\nend\n\n-- [EVENT] Fin Cinématique - TP au Camp du Culte sur la Plage du Zinit\n-- \nfunction event_2026_16086()\n    \nend\n\n","functions":["startCine","endCine","MindBubbleStart","MindBubbleChef","event_2026_16079","MovePlayer","Chefordres","GrouilleuxAbougeetparle","Chefparleettue","DechiqueteurAparle","Chefparleetpart","DechiqueteurBordres","Tousdanslagrotte","event_2026_16086"],"quest_calls":[],"dialogue_calls":[]},"scenario/2028.lua":{"source":"function startCine()\r\n\tzoomFactor = Camera.getZoomFactor()\r\n\tUI.manageFrame(\"World\",false) \t\t\t\t\t\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\t\t\t\t\t\t\t\t\t\t\t\t\r\n\tUI.manageFrame(\"World\",false) \t\t\t\t\t\r\n\tUI.setUIVisible(false)\t\r\n\tUI.displayWideScreenBand(true)\r\nend\r\n\r\nfunction endCine()\r\n\tCamera.attachCameraToMobile(playerId)\r\n\tUI.displayWideScreenBand(false)\r\n\tCamera.setUserZoomLocked(false)\t\t\t\t\t\t\t\t\t\t\t\t\r\n\tUI.setUIVisible(true)\t\r\n\tUI.manageFrame(\"World\",true) \t\t\t\t\r\n\tCamera.setZoomFactor(zoomFactor)\t\r\nend\r\n\r\nfunction MindBubbleStart(mob,text,tDuration)\r\n\tMindBubble=BubbleText.showText(mob, text, 0, 40, false)\r\n\tinvoke(tDuration,1,\"BubbleText.close\",MindBubble)\r\nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2028_16084()\n    \nend\n\n-- [EVENT][NATIONS][CH1] ENTER_INSTANCE - ACH 2988/2989/2990 en cours\n-- \nfunction event_2028_16091()\n    playerId = Context.getLeaderId()\r\n    \r\n    MindBubbleStart(playerId, \"quest.zinitplage.PlageFirst.Player.02\", 4000)\nend\n\n-- [EVENT][NATIONS][CH1] POSITION_TRIGGER - TP vers Cinématique Camp du Culte\n-- \nfunction event_2028_16085()\n    \nend\n\n-- [EVENT][NATIONS][CH1] ENTER_INSTANCE - TP vers Cinématique Ullu (en sortant du Donjon)\n-- \nfunction event_2028_18335()\n    \nend\n\n","functions":["startCine","endCine","MindBubbleStart","event_2028_16084","event_2028_16091","event_2028_16085","event_2028_18335"],"quest_calls":[],"dialogue_calls":[]},"scenario/2029.lua":{"source":"function startCine()\r\n\tlocal playerId = Context.getLeaderId()\r\n\tzoomFactor = Camera.getZoomFactor()\r\n\tCamera.attachCameraToMobile(playerId)\r\n\tCamera.setZoomFactor(1.5)\r\n\tUI.manageFrame(\"World\",false) \t\t\t\t\t\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\t\t\t\t\t\t\t\t\t\t\t\t\r\n\tUI.manageFrame(\"World\",false) \t\t\t\t\t\r\n\tUI.setUIVisible(false)\t\r\n\tUI.displayWideScreenBand(true)\r\n\tUI.setShortcutEnabled(false)\r\nend\r\n\r\nfunction endCine()\r\n\tlocal playerId = Context.getLeaderId()\r\n\t\r\n\tCamera.attachCameraToMobile(playerId)\r\n\tCamera.setZoomFactor(zoomFactor)\r\n\tUI.displayWideScreenBand(false)\r\n\tCamera.setUserZoomLocked(false)\t\t\t\t\t\t\t\t\t\t\t\t\r\n\tUI.setUIVisible(true)\t\r\n\tUI.manageFrame(\"World\",true) \t\t\t\t\r\n\tUI.setShortcutEnabled(true)\r\nend\r\n\r\nfunction MindBubbleStart(mob,text,tDuration)\r\n\tMindBubble=BubbleText.showText(mob, text, 0, 40, false)\r\n\tinvoke(tDuration,1,\"BubbleText.close\",MindBubble)\r\nend\n\n-- [INIT] ENTER_INSTANCE - Cinématique Ullu\n-- \nfunction event_2029_16087()\n    Ullu = Mobile.generateClientMobileId()\r\n    PlayerId = Context.getLeaderId()\r\n    \r\n    function apparitionJoueur()\r\n        Mobile.setMobileDirection(PlayerId,1)\r\n        Mobile.setMobileVisible(PlayerId, true)\r\n       Mobile.setMobileAnimation(PlayerId,\"AnimIncarnam-Chute-Fin\")\r\n        invoke(500,1,\"MindBubbleStart\",PlayerId,\"quest.zinitplage.CineUllu.Player.1\",2000)\r\n        invoke(1800,1,\"Mobile.setMobileAnimation\",PlayerId,\"AnimEmote-Chercher\")\r\n        invoke(3000,1,\"MindBubbleStart\",PlayerId,\"quest.zinitplage.CineUllu.Player.2\",5500)\r\n    \tinvoke(3500,1,\"Mobile.moveMobile\",PlayerId,-6,-8,0)\t\r\n        invoke(7000,1,\"Mobile.setMobileDirection\",PlayerId,7)\t\r\n        invoke(7000,1,\"Mobile.setMobileAnimation\",PlayerId,\"AnimEmote-Chercher\")\r\n    \tinvoke(9000,1,\"ulluSpeach\")\r\n    end\r\n    \r\n    function ulluSpeach()\t\r\n        Particle.addParticleSystem(800202, -6, -9, 0, 0)\r\n    \tActor.createActor(Ullu,1300051,-6,-9, 0)\r\n    \tCamera.attachCameraToMobile(Ullu)\r\n    \tMobile.setMobileDirection(Ullu,3)\r\n    \tMobile.setMobileAnimation(Ullu, \"AnimComp-Ataaaque\")\r\n        \r\n        invoke(490,1,\"Mobile.setMobileDirection\",PlayerId,7)\r\n    \tinvoke(500,1,\"Mobile.setMobileAnimation\",PlayerId,\"AnimEmote-Effrayee\")\r\n    \tinvoke(1000,1,\"MindBubbleStart\",Ullu,\"quest.zinitplage.CineUllu.ullu.1\",3000)\r\n    \tinvoke(4100,1,\"MindBubbleStart\",Ullu,\"quest.zinitplage.CineUllu.ullu.2\",3000)\r\n        invoke(4490,1,\"Mobile.setMobileDirection\",PlayerId,7)\r\n    \tinvoke(4500,1,\"Mobile.setMobileAnimation\",PlayerId,\"AnimEmote-Rire\")\r\n    \tinvoke(7200,1,\"MindBubbleStart\",Ullu,\"quest.zinitplage.CineUllu.ullu.3\",4000)\r\n    \tinvoke(11300,1,\"MindBubbleStart\",Ullu,\"quest.zinitplage.CineUllu.ullu.4\",4000)\r\n    \tinvoke(12000,1,\"Mobile.setMobileAnimation\",Ullu, \"AnimComp-Regards\")\r\n    \tinvoke(11800,1,\"Mobile.setMobileAnimation\",PlayerId,\"AnimEmote-Non\")\r\n    \tinvoke(14000,1,\"Mobile.setMobileAnimation\",PlayerId,\"AnimEmote-Non\")\r\n    \tinvoke(15400,1,\"MindBubbleStart\",Ullu,\"quest.zinitplage.CineUllu.ullu.5\",4000)\r\n    \tinvoke(16500,1,\"Mobile.setMobileAnimation\",PlayerId,\"AnimEmote-Supplie-Debut\")\r\n    \tinvoke(19500,1,\"MindBubbleStart\",Ullu,\"quest.zinitplage.CineUllu.ullu.6\",4000)\r\n    \tinvoke(23600,1,\"Mobile.setMobileAnimation\",Ullu, \"AnimComp-Ataaaque\")\r\n    \tinvoke(23600,1,\"MindBubbleStart\",Ullu,\"quest.zinitplage.CineUllu.ullu.7\",4000)\r\n    \tinvoke(25000,1,\"Mobile.setMobileAnimation\",PlayerId,\"AnimEmote-Supplie-Fin\")\r\n    \tinvoke(26000,1,\"Mobile.setMobileAnimation\",PlayerId,\"AnimEmote-Acquiescer\")\r\n    \tinvoke(27700,1,\"MindBubbleStart\",Ullu,\"quest.zinitplage.CineUllu.ullu.8\",4000)\r\n    \tinvoke(28000,1,\"Mobile.setMobileAnimation\",PlayerId,\"AnimEmote-Effrayee\")\r\n    \tinvoke(29000,1,\"endCine\")\r\n    \r\n    end\r\n    \r\n    startCine()\r\n    --Particle.addParticleSystem(7034001, 0, 0, 0) \r\n    Mobile.setMobileVisible(PlayerId, false)\r\n    Sound.playForcedMusic(210082)\r\n    invoke(2500,1,\"apparitionJoueur\")\nend\n\n-- Fin Cinématique - TP sur la Plage du Zinit près de la crevasse\n-- \nfunction event_2029_16088()\n    \nend\n\n","functions":["startCine","endCine","MindBubbleStart","event_2029_16087","apparitionJoueur","ulluSpeach","event_2029_16088"],"quest_calls":[],"dialogue_calls":[]},"scenario/2031.lua":{"source":"\n\n-- Vieux parchemin des archives\n-- \nfunction event_2031_16090()\n    UI.displayBackground(327)\nend\n\n","functions":["event_2031_16090"],"quest_calls":[],"dialogue_calls":[]},"scenario/2032.lua":{"source":"\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2032_16094()\n    \nend\n\n-- Retrait de la propriété IN_ARENA_INSTANCE\n-- \nfunction event_2032_16095()\n    \nend\n\n-- Création du combat après acceptation de la requête\n-- \nfunction event_2032_16096()\n    \nend\n\n","functions":["event_2032_16094","event_2032_16095","event_2032_16096"],"quest_calls":[],"dialogue_calls":[]},"scenario/2033.lua":{"source":"\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2033_16097()\n    \nend\n\n-- Retrait de la propriété IN_ARENA_INSTANCE\n-- \nfunction event_2033_16098()\n    \nend\n\n-- Création du combat après acceptation de la requête\n-- \nfunction event_2033_16099()\n    \nend\n\n","functions":["event_2033_16097","event_2033_16098","event_2033_16099"],"quest_calls":[],"dialogue_calls":[]},"scenario/2034.lua":{"source":"\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2034_16100()\n    \nend\n\n-- Retrait de la propriété IN_ARENA_INSTANCE\n-- \nfunction event_2034_16101()\n    \nend\n\n-- Création du combat après acceptation de la requête\n-- \nfunction event_2034_16102()\n    \nend\n\n","functions":["event_2034_16100","event_2034_16101","event_2034_16102"],"quest_calls":[],"dialogue_calls":[]},"scenario/2035.lua":{"source":"\n