\tif (bubbleSteleInfoId ~= nil  and bubbleSteleInfoId ~= 0) then bubbleSteleInfoId = 0 end\r\nend\r\n\r\nfunction updateSteleInfo(stateInfoId, forceDisplayUI)\r\n\r\n\tif (bubbleSteleInfoId == 0) then\r\n\t\tbubbleSteleInfoId = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_WEST\", 0, -60, false, 2147483647, true, \"interactiveBubbleDialog5\", 30000, 25000, \"onSteleInfoClosed\")\r\n\tend\r\n\r\n\tBubbleText.setText(bubbleSteleInfoId, stateInfoId)\r\n\t\r\n\tif (forceDisplayUI) then BubbleText.show(bubbleSteleInfoId) end\r\nend\r\n\r\nnbFight = 0\r\n\r\n\r\nfunction displayPath(room)\r\n\tlocal room = toLong(room)\r\n\t\r\n\tif ( room >= 1 or room == -1 ) then\r\n\t\tWorld.setPictoAlpha(-68, 9, 13, 0, 2000)\r\n\t\tWorld.setPictoAlpha(-70, 9, 13, 0, 2000)\r\n\t\tWorld.setPictoAlpha(-72, 9, 13, 0, 2000)\t\r\n\tend\r\n\t\r\n\tif ( room >= 2 or room == -1 ) then\r\n\t\tWorld.setPictoAlpha(-9, -11, 6, 0, 2000)\r\n\tend\r\n\t\r\n\tif ( room >= 3 or room == -1) then\r\n\t\tWorld.setPictoAlpha(-29, -4, 14, 0, 2000)\r\n\tend\r\n\t\r\n\tif ( room >= 4 or room == -1) then\r\n\t\tWorld.setPictoAlpha(-54, 1, 6, 0, 2000)\r\n\tend\r\nend\n\n-- [INIT] Variables\n-- \nfunction event_2050_16305()\n    \nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_2050_16248()\n    \nend\n\n-- [EVENT][1] Victoire - Déverouille le passage vers S2\n-- \nfunction event_2050_16250(room)\n    displayPath(room)\nend\n\n-- [EVENT][2] Victoire - Déverouille le passage vers S3\n-- \nfunction event_2050_16252(room)\n    displayPath(room)\nend\n\n-- [EVENT][3] Victoire - Déverouille le passage vers S4\n-- \nfunction event_2050_16254(room)\n    displayPath(room)\nend\n\n-- [EVENT] Salle 4 - Activation du TP de sortie\n-- \nfunction event_2050_16306()\n    \nend\n\n-- [OLD][EVENT] Activation Stèle 1\n-- \nfunction event_2050_16259(steleCount)\n    local steleCount = toLong(steleCount)\r\n    if (steleCount == 1) then rewardId = 27161\r\n    elseif (steleCount == 2) then rewardId = 27145\r\n    elseif (steleCount == 3) then rewardId = 27137\r\n    else rewardId = 0\r\n    end\r\n    \r\n    UI.openRewardsDialog(\"stele.activation\")\r\n    UI.addReward(rewardId)\nend\n\n-- [OLD][EVENT] Activation Stèle 2\n-- \nfunction event_2050_16260(steleCount)\n    local steleCount = toLong(steleCount)\r\n    if (steleCount == 1) then rewardId = 27161\r\n    elseif (steleCount == 2) then rewardId = 27145\r\n    elseif (steleCount == 3) then rewardId = 27137\r\n    else rewardId = 0\r\n    end\r\n    \r\n    UI.openRewardsDialog(\"stele.activation\")\r\n    UI.addReward(rewardId)\nend\n\n-- [OLD][EVENT] Activation Stèle 3\n-- \nfunction event_2050_16261(steleCount)\n    local steleCount = toLong(steleCount)\r\n    if (steleCount == 1) then rewardId = 27161\r\n    elseif (steleCount == 2) then rewardId = 27145\r\n    elseif (steleCount == 3) then rewardId = 27137\r\n    else rewardId = 0\r\n    end\r\n    \r\n    UI.openRewardsDialog(\"stele.activation\")\r\n    UI.addReward(rewardId)\nend\n\n-- [OLD][EVENT] Le joueur examine la Stèle 1\n-- \nfunction event_2050_20577(steleCount)\n    local steleCount = toLong(steleCount)\r\n    if (steleCount == 0) then rewardId = 27161\r\n    elseif (steleCount == 1) then rewardId = 27145\r\n    elseif (steleCount == 2) then rewardId = 27137\r\n    else rewardId = 0\r\n    end\r\n    \r\n    UI.openRewardsDialog(\"stele.description\")\r\n    UI.addReward(rewardId)\r\n    \r\n    local stateInfoId = \"stele.state.description.4020\"\r\n    \r\n    updateSteleInfo(stateInfoId, true)\nend\n\n-- [OLD][EVENT] Le joueur examine la Stèle 2\n-- \nfunction event_2050_20578(steleCount)\n    local steleCount = toLong(steleCount)\r\n    if (steleCount == 0) then rewardId = 27161\r\n    elseif (steleCount == 1) then rewardId = 27145\r\n    elseif (steleCount == 2) then rewardId = 27137\r\n    else rewardId = 0\r\n    end\r\n    \r\n    UI.openRewardsDialog(\"stele.description\")\r\n    UI.addReward(rewardId)\r\n    \r\n    local stateInfoId = \"stele.state.description.4021\"\r\n    \r\n    updateSteleInfo(stateInfoId, true)\nend\n\n-- [OLD][EVENT] Le joueur examine la Stèle 3\n-- \nfunction event_2050_20579(steleCount)\n    local steleCount = toLong(steleCount)\r\n    if (steleCount == 0) then rewardId = 27161\r\n    elseif (steleCount == 1) then rewardId = 27145\r\n    elseif (steleCount == 2) then rewardId = 27137\r\n    else rewardId = 0\r\n    end\r\n    \r\n    UI.openRewardsDialog(\"stele.description\")\r\n    UI.addReward(rewardId)\r\n    \r\n    local stateInfoId = \"stele.state.description.4022\"\r\n    \r\n    updateSteleInfo(stateInfoId, true)\nend\n\n-- [OLD][EVENT] Salle 4 - Refresh des APS pour le porteur des états Stèle\n-- \nfunction event_2050_16262()\n    \nend\n\n-- [EVENT] Salle 4 - Récupère l'ID du combat\n-- \nfunction event_2050_16308()\n    \nend\n\n-- [EVENT] Salle 4 - Reset l'ID du combat\n-- \nfunction event_2050_16309()\n    \nend\n\n-- [EVENT] Fin du combat avec victoire des Joueurs (1 stèle) - Validation Quête\n-- \nfunction event_2050_16344()\n    \nend\n\n-- [EVENT] Fin du combat avec victoire des Joueurs (2 stèles) - Validation Quête\n-- \nfunction event_2050_16345()\n    \nend\n\n-- [EVENT] Fin du combat avec victoire des Joueurs (3 stèles) - Validation Quête\n-- \nfunction event_2050_16346()\n    \nend\n\n-- [EVENT] Fin Combat - Victoire Joueurs Stèles 1&2 - Validation Quête\n-- \nfunction event_2050_16916()\n    \nend\n\n-- [EVENT] Fin Combat - Victoire Joueurs Stèles 2&3 - Validation Quête\n-- \nfunction event_2050_16917()\n    \nend\n\n-- [EVENT] Fin Combat - Victoire Joueurs Stèles 1&3 - Validation Quête\n-- \nfunction event_2050_16918()\n    \nend\n\n-- Déplace le joueur vers la salle suivante\n-- \nfunction event_2050_18640()\n    \nend\n\n-- [OLD][EVENT] DUNGEON_DIFFICULTY_CHANGED - On désactive les états stèles\n-- \nfunction event_2050_20614()\n    \nend\n\n-- FIGHT_ENTER_ACTION_PHASE - Applique l'état \"Donjon\" (Salle 1)\n-- \nfunction event_2050_21921()\n    \nend\n\n-- [STELE] FIGHT_STARTED - On applique les difficultés sur le boss\n-- \nfunction event_2050_22801()\n    \nend\n\n-- [STELE] FIGHT_ENTER_ACTION_PHASE - On applique les bonus sur les joueurs\n-- \nfunction event_2050_22802()\n    \nend\n\n-- [STELE] FIGHT_ENDED - On rend la stèle utilisable en cas de défaite\n-- \nfunction event_2050_22886()\n    \nend\n\n","functions":["closeSteleInfo","onSteleInfoClosed","updateSteleInfo","displayPath","event_2050_16305","event_2050_16248","event_2050_16250","event_2050_16252","event_2050_16254","event_2050_16306","event_2050_16259","event_2050_16260","event_2050_16261","event_2050_20577","event_2050_20578","event_2050_20579","event_2050_16262","event_2050_16308","event_2050_16309","event_2050_16344","event_2050_16345","event_2050_16346","event_2050_16916","event_2050_16917","event_2050_16918","event_2050_18640","event_2050_20614","event_2050_21921","event_2050_22801","event_2050_22802","event_2050_22886"],"quest_calls":["UI.openRewardsDialog(\"stele.activation\")\r","UI.openRewardsDialog(\"stele.activation\")\r","UI.openRewardsDialog(\"stele.activation\")\r","UI.openRewardsDialog(\"stele.description\")\r","UI.openRewardsDialog(\"stele.description\")\r","UI.openRewardsDialog(\"stele.description\")\r"],"dialogue_calls":[]},"scenario/2051.lua":{"source":"m_playerId = Context.getLeaderId()\n\n-- [EVENT]Transport vers la zone du temple englouti à Sufokia\n-- \nfunction event_2051_16266()\n    \nend\n\n","functions":["event_2051_16266"],"quest_calls":[],"dialogue_calls":[]},"scenario/2054.lua":{"source":"\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_2054_16290(doorOpenKanni, startDate, playerDate)\n    local openDate = toLong(startDate)\r\n    local currentDate = toLong(playerDate)\r\n    local open = doorOpenKanni\r\n    \r\n    local total = 3600\r\n    local remaining = 0\r\n    local elapsed = 0\r\n    \r\n    if (openDate ~= nil and openDate > 0 and currentDate ~= nil and currentDate > 0) then\r\n    \r\n    \telapsed = math.floor((currentDate - openDate) / 1000)\r\n    \t\r\n    \tif (elapsed ~= nil  and elapsed > 0) then\r\n    \t\tremaining = total - elapsed\r\n    \tend\r\n    end\r\n    \r\n    UI.stopCountdown()\r\n    if (remaining > 0 and open) then\r\n    \tUI.startCountdown(remaining)\r\n    end\nend\n\n-- Collector Kanniboule - Initialisation\n-- \nfunction event_2054_16294()\n    \nend\n\n-- Collector Kanniboule - Ouverture\n-- \nfunction event_2054_16303()\n    UI.openRewardsDialog(\"moon.collector.kanni.start\")\r\n    UI.addReward(19801)\r\n    UI.stopCountdown()\r\n    UI.startCountdown(3600)\nend\n\n-- Collector Kanniboule - Fermeture\n-- \nfunction event_2054_16304()\n    UI.openInfoDialog(\"moon.collector.end.title\", \"moon.collector.kanni.end\" )\r\n    UI.stopCountdown()\nend\n\n-- Dialogue PNJ - Spawn du groupe + Lancement du combat\n-- \nfunction event_2054_16291()\n    \nend\n\n-- Le joueur quitte l'instance\n-- \nfunction event_2054_16292()\n    UI.stopCountdown()\nend\n\n-- [EVENT] Fin du combat avec victoire des Joueurs - Validation Quête\n-- \nfunction event_2054_16318()\n    \nend\n\n","functions":["event_2054_16290","event_2054_16294","event_2054_16303","event_2054_16304","event_2054_16291","event_2054_16292","event_2054_16318"],"quest_calls":["UI.openRewardsDialog(\"moon.collector.kanni.start\")\r"],"dialogue_calls":[]},"scenario/2055.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\nparticleObjective = 0\r\nartefactAnalysed = 0\n\n-- [INITIALISATION] Serveur\n-- \nfunction event_2055_16297(playerId)\n    \nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_2055_16298(ameliaSC)\n    ameliaId = toLong(ameliaSC)\r\n    \r\n    Mobile.setMobileAnimation(ameliaId,\"AnimComp-Statique\")\nend\n\n-- [EVENT] - achievement running 2701 - Examen porte CINE\n-- \nfunction event_2055_16299(laraCraft, jenryHones, renemilleLebbocq, miloTchach, ameliaSC)\n    playerId = Context.getLeaderId()\r\n    laraId = toLong(laraCraft)\r\n    jenryId = toLong(jenryHones)\r\n    lebbocqId = toLong(renemilleLebbocq)\r\n    miloId = toLong(miloTchach)\r\n    ameliaId = toLong(ameliaSC)\r\n    \r\n    startCinematicContext(2, playerId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 16299)\r\n    \r\n    -- **Comment vais-je ouvrir cette porte ?\r\n    invoke_custom(02000, 1, \"bubble\", playerId, \"quest.nation.portetempleokta.ch02.doorcine01\")\r\n    invoke_custom(02000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(06000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- Ne trouvez-vous pas cela fascinant ?\r\n    invoke_custom(06000, 1, \"bubble\", laraId, \"quest.nation.portetempleokta.ch02.doorcine02\")\r\n    invoke_custom(06000, 1, \"Camera.attachCameraToMobile\", laraId)\r\n    invoke_custom(09500, 1, \"clearBubbles\", laraId)\r\n    \r\n    -- D'après mes recherches, il nous faudrait trouver 3 Orichalques pour activer la porte.\r\n    invoke_custom(10000, 1, \"bubble\", laraId, \"quest.nation.portetempleokta.ch02.doorcine03\")\r\n    invoke_custom(15500, 1, \"clearBubbles\", laraId)\r\n    \r\n    -- Des Orichalques ? Fascinant ! Qu'est-ce donc ?\r\n    invoke_custom(16000, 1, \"bubble\", miloId, \"quest.nation.portetempleokta.ch02.doorcine04\")\r\n    invoke_custom(16000, 1, \"Camera.attachCameraToMobile\", miloId)\r\n    invoke_custom(19500, 1, \"clearBubbles\", miloId)\r\n    \r\n    -- Oh ! Les Orichalques sont des objets extrêments anciens et rares... Mais à quoi ressemblent-ils ?\r\n    invoke_custom(20000, 1, \"bubble\", jenryId, \"quest.nation.portetempleokta.ch02.doorcine05\")\r\n    invoke_custom(20000, 1, \"Camera.attachCameraToMobile\", jenryId)\r\n    invoke_custom(26500, 1, \"clearBubbles\", jenryId)\r\n    \r\n    -- Ce sont des billes de métal. Un métal jaune...\r\n    invoke_custom(27000, 1, \"bubble\", laraId, \"quest.nation.portetempleokta.ch02.doorcine06\")\r\n    invoke_custom(30500, 1, \"clearBubbles\", laraId)\r\n    \r\n    -- Oh ! Une bille de métal jaune...\r\n    invoke_custom(31000, 1, \"bubble\", jenryId, \"quest.nation.portetempleokta.ch02.doorcine07\")\r\n    invoke_custom(34500, 1, \"clearBubbles\", jenryId)\r\n    \r\n    -- Je... Hmmm... Heu... Où pourrait-on en trouver ?\r\n    invoke_custom(35000, 1, \"bubble\", lebbocqId, \"quest.nation.portetempleokta.ch02.doorcine08\")\r\n    invoke_custom(35000, 1, \"Camera.attachCameraToMobile\", lebbocqId)\r\n    invoke_custom(39500, 1, \"clearBubbles\", lebbocqId)\r\n    \r\n    -- Hé bien voyez-vous, elles sont extrêmement rares.\r\n    invoke_custom(40000, 1, \"bubble\", laraId, \"quest.nation.portetempleokta.ch02.doorcine09\")\r\n    invoke_custom(40000, 1, \"Camera.attachCameraToMobile\", laraId)\r\n    invoke_custom(44500, 1, \"clearBubbles\", laraId)\r\n    \r\n    -- Mais j'ai une petite idée... Venez me parler quand vous serez prêt à repartir à l'aventure !\r\n    invoke_custom(45000, 1, \"bubble\", laraId, \"quest.nation.portetempleokta.ch02.doorcine10\")\r\n    invoke_custom(51500, 1, \"clearBubbles\", laraId)\r\n    \r\n    invoke_custom(52000, 1, \"skipCinematic\", 16299)\nend\n\n-- [EVENT] - achievement running 2701 - Examen porte FIN\n-- \nfunction event_2055_16301()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_2055_16297","event_2055_16298","event_2055_16299","event_2055_16301"],"quest_calls":[],"dialogue_calls":[]},"scenario/2056.lua":{"source":"\n\n-- Event - Infos au joueur\n-- \nfunction event_2056_16310()\n    UI.openRewardsDialog(\"moon.collector.kanni.start\")\r\n    UI.addReward(19801)\nend\n\n","functions":["event_2056_16310"],"quest_calls":["UI.openRewardsDialog(\"moon.collector.kanni.start\")\r"],"dialogue_calls":[]},"scenario/2057.lua":{"source":"m_playerId = Context.getPlayer()\n\n-- Lancement Cinématique\n-- \nfunction event_2057_16313()\n    \nend\n\n","functions":["event_2057_16313"],"quest_calls":[],"dialogue_calls":[]},"scenario/2058.lua":{"source":"player = Context.getPlayer()\r\nfunction startCine()\r\n\tzoomFactor = Camera.getZoomFactor()\r\n\tUI.manageFrame(\"World\",false) \t\t\t\t\t\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\t\t\t\t\t\t\t\t\t\t\t\t\r\n\tUI.manageFrame(\"World\",false) \t\t\t\t\t\r\n\tUI.setUIVisible(false)\t\r\n\tUI.displayWideScreenBand(true)\r\nend\r\n\r\nfunction endCine()\r\n\tUI.displayWideScreenBand(false)\r\n\tCamera.setUserZoomLocked(false)\t\t\t\t\t\t\t\t\t\t\t\t\r\n\tUI.setUIVisible(true)\t\r\n\tUI.manageFrame(\"World\",true) \t\t\t\t\r\n\tCamera.setZoomFactor(zoomFactor)\t\r\nend\r\n\r\n\r\nfunction MindBubbleStart(mob,text,