ubble\", mobTwo, \"quest.huppermage.initiation.06\")\r\n    invoke(32000, 1, \"Camera.attachCameraToMobile\", playerId)\r\n    invoke(32000, 1, \"endCine\")\nend\n\n-- [EVENT] Lancement du combat\n-- \nfunction event_2067_16396()\n    UI.loadTutorialDialog(\"null\",\"quest.huppermage.initiation.tutorial.title\",\"quest.huppermage.initiation.tutorial.desc\")\nend\n\n-- [EVENT] Combat perdant\n-- \nfunction event_2067_16399()\n    \nend\n\n-- [EVENT] Combat gagnant\n-- \nfunction event_2067_16397()\n    \nend\n\n-- [EVENT] Téléportation des joueurs perdants\n-- \nfunction event_2067_16400()\n    \nend\n\n-- [EVENT] Téléportation des joueurs gagnants\n-- \nfunction event_2067_16401()\n    \nend\n\n","functions":["startCine","endCine","bubble","mobileVisible","event_2067_16402","event_2067_16393","event_2067_16395","mobStart","event_2067_16396","event_2067_16399","event_2067_16397","event_2067_16400","event_2067_16401"],"quest_calls":[],"dialogue_calls":[]},"scenario/2068.lua":{"source":"\n\n-- [EVENT] Activation - Croupier Compensation\n-- \nfunction event_2068_16403()\n    \nend\n\n-- [EVENT] Désactivation - Croupier Compensation\n-- \nfunction event_2068_16404()\n    \nend\n\n","functions":["event_2068_16403","event_2068_16404"],"quest_calls":[],"dialogue_calls":[]},"scenario/2069.lua":{"source":"--SERRE--\r\n--Creation des Paysans\r\n--NCP_serre_paysan_1 = Mobile.generateClientMobileId()\r\n--NCP_serre_paysan_2 = Mobile.generateClientMobileId()\r\n--NCP_serre_paysan_3 = Mobile.generateClientMobileId()\r\n\r\n--Creation des Plantes\r\nNCP_serre_plante_1 = Mobile.generateClientMobileId()\r\nNCP_serre_plante_2 = Mobile.generateClientMobileId()\r\nNCP_serre_plante_3 = Mobile.generateClientMobileId()\r\nNCP_serre_plante_4 = Mobile.generateClientMobileId()\r\nNCP_serre_plante_5 = Mobile.generateClientMobileId()\r\nNCP_serre_plante_6 = Mobile.generateClientMobileId()\r\nNCP_serre_plante_7 = Mobile.generateClientMobileId()\r\nNCP_serre_plante_8 = Mobile.generateClientMobileId()\r\n\r\n--Creation du Phorreur\r\nNCP_serre_phorreur_1 = Mobile.generateClientMobileId()\r\n\r\n--Creation de la Graine (quête)\r\nNCP_serre_graine_1 = Mobile.generateClientMobileId()\r\n\r\n--SALLE DE CLASSE--\r\n--Creation du professeur\r\nNCP_classe_prof_1 = Mobile.generateClientMobileId()\r\n\r\n--Creation des élèves\r\n--NCP_classe_eleve_1 = Mobile.generateClientMobileId()\r\n--NCP_classe_eleve_2 = Mobile.generateClientMobileId()\r\n--NCP_classe_eleve_3 = Mobile.generateClientMobileId()\r\n--NCP_classe_eleve_4 = Mobile.generateClientMobileId()\r\n\r\nfunction doBehavior(npc, animationName)\r\n\tif (animationName == \"AnimStatique\") then\r\n\t\tMobile.setMobileToStaticAnimation(npc)\r\n\telse\r\n\t\tMobile.setMobileAnimation(npc, animationName)\r\n\tend\t\r\nend\r\n\r\nfunction bubble(mob,text)\r\n\tBubbleText.closeBubbleAttachedTo(mob)\r\n\tBubbleText.showText(mob, text, 0, 40, false)\r\nend\n\n-- _INITILISATION - On lance le timer initial pour les comportements\n-- \nfunction event_2069_16407()\n    \nend\n\n-- ENTER INSTANCE - On créer les mobiles, particules et on place/oriente tout ça\n-- \nfunction event_2069_16406()\n    --SERRE--\r\n    \t--Actor.createActor(NCP_serre_paysan_1, 1300018, 32, -28, -14, 4)\r\n    \t--Mobile.setMobileDirection(NCP_serre_paysan_1, 1)\r\n    \t--Actor.createActor(NCP_serre_paysan_2, 1300048, 31, -40, -14, 4)\r\n    \t--Mobile.setMobileDirection(NCP_serre_paysan_2, 3)\r\n    \t--Actor.createActor(NCP_serre_paysan_3, 1300018, 38, -22, -14, 4)\r\n    \t--Mobile.setMobileDirection(NCP_serre_paysan_3, 3)\r\n    \t\r\n    \tActor.createActor(NCP_serre_phorreur_1, 100501380, 31, -31, -14, 4)\r\n    \tMobile.setMobileVisible(NCP_serre_phorreur_1, false)\r\n    \t\r\n    \tActor.createActor(NCP_serre_plante_1, 101600094, 38, -23, -14, 4)\r\n    \tActor.createActor(NCP_serre_plante_2, 101600095, 38, -21, -14, 4)\r\n    \tActor.createActor(NCP_serre_plante_3, 101600135, 38, -19, -14, 4)\r\n    \tActor.createActor(NCP_serre_plante_4, 101600144, 38, -17, -14, 4)\r\n    \t\r\n    \tActor.createActor(NCP_serre_plante_5, 101600094, 40, -17, -14, 4)\r\n    \tMobile.setMobileDirection(NCP_serre_plante_5, 5)\r\n    \tActor.createActor(NCP_serre_plante_6, 101600095, 40, -19, -14, 4)\r\n    \tMobile.setMobileDirection(NCP_serre_plante_6, 5)\r\n    \tActor.createActor(NCP_serre_plante_7, 101600135, 40, -21, -14, 4)\r\n    \tMobile.setMobileDirection(NCP_serre_plante_7, 5)\r\n    \tActor.createActor(NCP_serre_plante_8, 101600144, 40, -23, -14, 4)\r\n    \tMobile.setMobileDirection(NCP_serre_plante_8, 5)\r\n    \t\r\n    \tActor.createActor(NCP_serre_graine_1, 100502357, 31, -44, -14, 4)\r\n    \tParticle.addParticleSystemToTarget(7000046, NCP_serre_graine_1)\r\n    \t\r\n    \t--SALLE DE CLASSE--\r\n    \tActor.createActor(NCP_classe_prof_1, 177603951, -45, -8, 4, 4)\r\n    \t\r\n    \t--Actor.createActor(NCP_classe_eleve_1, 10, -38, -9, 0, 4)\r\n    \t--Mobile.setMobileDirection(NCP_classe_eleve_1, 5)\r\n    \t--doBehavior(NCP_classe_eleve_1, \"AnimStatique-Banc-Debut-Assis\")\r\n    \t\r\n    \t--Actor.createActor(NCP_classe_eleve_2, 21, -36, -9, 0, 4)\r\n    \t--Mobile.setMobileDirection(NCP_classe_eleve_2, 5)\r\n    \t--doBehavior(NCP_classe_eleve_2, \"AnimStatique-Banc-Debut-Assis\")\r\n    \t\r\n    \t--Actor.createActor(NCP_classe_eleve_3, 30, -38, -5, 0, 4)\r\n    \t--Mobile.setMobileDirection(NCP_classe_eleve_3, 5)\r\n    \t--doBehavior(NCP_classe_eleve_3, \"AnimStatique-Banc-Debut-Assis\")\r\n    \t\r\n    \t--Actor.createActor(NCP_classe_eleve_4, 41, -40, -7, 0, 4)\r\n    \t--Mobile.setMobileDirection(NCP_classe_eleve_4, 5)\r\n    \t--doBehavior(NCP_classe_eleve_4, \"AnimStatique-Banc-Debut-Assis\")\r\n    \t\r\n    \t\t\r\n    \t--On applique le GFX d'un equipement (item) sur le mobile\r\n    \t--Actor.equip(NCP_classe_eleve_4, \"51318324\", \"CorpsHabit\")\r\n    \t\r\n    \t--On applique le GFX d'un NPC (monstre) sur le mobile\r\n    \t--Actor.changeSkin(NCP_classe_eleve_4, \"100502357\")\r\n    \t\nend\n\n-- TIMER TICK - On joue un comportement et relance du timer\n-- \nfunction event_2069_16408(randomValue)\n    \tlocal rdm = toLong(randomValue) --On utilise un random global pour s'assurer que tous les joueurs voient la même chose\r\n    \t\r\n    \tlocal serre_plante_behavior = \"AnimStatique\" --Animation par defaut\r\n    \tlocal serre_phorreur_behavior = \"\" --Animation par defaut\r\n    \tlocal classe_prof_behavior = \"AnimStatique\" --Animation par defaut\r\n    \tlocal classe_eleve_behavior = \"AnimStatique\" --Animation par defaut\r\n    \t\r\n    \tlocal classe_prof_bubble = \"\" --Bubble par defaut\r\n    \r\n    \tif (rdm == 0) then\r\n    \t\tserre_phorreur_behavior = \"AnimSort-Fouille-Fin\"\r\n    \t\tclasse_prof_bubble = \"quest.huppermage.ambiance.01\"\r\n    \telseif (rdm == 1) then\r\n    \t\tserre_phorreur_behavior = \"AnimSort-Fouille-Fin\"\r\n    \t\tclasse_prof_bubble = \"quest.huppermage.ambiance.02\"\r\n    \telseif (rdm == 2) then\r\n    \t\tserre_plante_behavior = \"AnimSort-Epinade\"\r\n    \t\tclasse_prof_bubble = \"quest.huppermage.ambiance.03\"\r\n    \telseif (rdm == 3) then\r\n    \t\tserre_plante_behavior = \"AnimSort-Epinade\"\r\n    \t\tclasse_prof_bubble = \"quest.huppermage.ambiance.04\"\r\n    \tend\r\n    \t\r\n    \tif (classe_prof_bubble ~= \"\") then\r\n    \t\tbubble(NCP_classe_prof_1, classe_prof_bubble)\r\n    \tend\r\n    \t\r\n    \tif (serre_phorreur_behavior ~= \"\") then\r\n    \t\tdoBehavior(NCP_serre_phorreur_1, serre_phorreur_behavior)\r\n    \t\tinvoke(1600, 1, \"doBehavior\", NCP_serre_phorreur_1, \"AnimSort-Fusion\")\r\n    \t\tinvoke(4300, 1, \"doBehavior\", NCP_serre_phorreur_1, \"AnimSort-Fouille\")\r\n    \t\tinvoke(6000, 1, \"Mobile.setMobileVisible\", NCP_serre_phorreur_1, false)\r\n    \tend\r\n    \t\r\n    \tinvoke( 500, 1, \"doBehavior\" , NCP_serre_plante_1, serre_plante_behavior)\r\n    \tinvoke(1000, 1, \"doBehavior\" , NCP_serre_plante_2, serre_plante_behavior)\r\n    \tinvoke(1500, 1, \"doBehavior\" , NCP_serre_plante_3, serre_plante_behavior)\r\n    \tinvoke(2000, 1, \"doBehavior\" , NCP_serre_plante_4, serre_plante_behavior)\r\n    \tinvoke(2500, 1, \"doBehavior\" , NCP_serre_plante_5, serre_plante_behavior)\r\n    \tinvoke(3000, 1, \"doBehavior\" , NCP_serre_plante_6, serre_plante_behavior)\r\n    \tinvoke(3500, 1, \"doBehavior\" , NCP_serre_plante_7, serre_plante_behavior)\r\n    \tinvoke(4000, 1, \"doBehavior\" , NCP_serre_plante_8, serre_plante_behavior)\nend\n\n","functions":["doBehavior","bubble","event_2069_16407","event_2069_16406","event_2069_16408"],"quest_calls":[],"dialogue_calls":[]},"scenario/2070.lua":{"source":"function startCine(cineZoomFactor)\r\n\tzoomFactor = Camera.getZoomFactor()\r\n\tUI.manageFrame(\"World\", false)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tUI.setShortcutEnabled(false)\r\n\tCamera.setZoomFactor(cineZoomFactor)\r\nend\r\n\r\nfunction endCine()\r\n\tCamera.attachCameraToMobile(playerId)\r\n\tUI.displayWideScreenBand(false)\r\n\tCamera.setUserZoomLocked(false)\r\n\tUI.setUIVisible(true)\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.hideButton()\r\n\tUI.setShortcutEnabled(true)\r\n\t\r\n\tif (zoomFactor ~= nil and zoomFactor > 0) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\nend\r\n\r\nfunction bubble(mob,text)\r\n\tBubbleText.closeBubbleAttachedTo(mob)\r\n\tBubbleText.showText(mob, text, 0, 40, false)\r\nend\r\n\r\nfunction mobileVisible(mobId, booleen)\r\n\tMobile.setMobileVisible(mobId, booleen)\r\nend\n\n-- [INIT] Initialisation des variables\n-- \nfunction event_2070_16409()\n    \nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_2070_16410(playerId)\n    invoke(1000, 1, \"bubble\", playerId, \"quest.huppermage.dortoirs.01\")\nend\n\n-- [EVENT] Spawn des Zobals\n-- \nfunction event_2070_16411(mobOne, mobTwo, mobThree)\n    playerId = Context.getLeaderId()\r\n    \r\n    function mobStart(mobId, direction)\r\n    \tMobile.setMobileDirection(mobId, direction)\r\n    \tMobile.setMobileAnimation(mobId, \"AnimApparition\")\r\n    end\r\n    \r\n    function mobSetFightAnim(mobId)\r\n    \tMobile.setMobileAnimationStaticKey(mobId, \"AnimStatique02\")\r\n    \tMobile.setCustomWalkStyle(mobId, \"AnimMarche02\")\r\n    end\r\n    \r\n    startCine(2.0)\r\n    invoke(0, 1, \"mobileVisible\", mobOne, false)\r\n    invoke(0, 1, \"mobileVisible\", mobTwo, false)\r\n    invoke(0, 1, \"mobileVisible\", mobThree, false)\r\n    invoke(0, 1, \"Camera.attachCameraToMobile\", mobOne)\r\n    invoke(500, 1, \"mobileVisible\", mobOne, true)\r\n    invoke(500, 1, \"mobStart\", mobOne, 5)\r\n    invoke(1000, 1, \"mobSetFightAnim\", mobOne)\r\n    invoke(1500, 1, \"Camera.attachCameraToMobile\", mobTwo)\r\n    invoke(2000, 1, \"mobileVisible\", mobTwo, true)\r\n    invoke(2000, 1, \"mobStart\", mobTwo, 5)\r\n    invoke(2500, 1, \"mobSetFightAnim\", mobTwo)\r\n    invoke(3000, 1, \"Camera.attachCameraToMobile\", mobThree)\r\n    invoke(3500, 1, \"mobileVisible\", mobThree, true)\r\n    invoke(3500, 1, \"mobStart\", mobThree, 5)\r\n    invoke(4000, 1, \"mobSetFightAnim\", mobThree)\r\n    invoke(5200, 1, \"bubble\", mobThree, \"quest.huppermage.dortoirs.02\")\r\n    invoke(7000, 1, \"endCine\")\nend\n\n-- [EVENT] Lancement du combat\n-- \nfunction event_2070_16413()\n    UI.loadTutorialDialog(\"null\",\"quest.huppermage.dortoirs.tutorial.title\",\"quest.huppermage.dortoirs.tutorial.desc\")\nend\n\n-- [EVENT] Combat perdant\n-- \nfunction event_2070_16414()\n    \nend\n\n-- [EVENT] Combat gagnant\n-- \nfunction event_2070_16415()\n    \nend\n\n-- [EVENT] Téléportation des joueurs perdants\n-- \nfunction event_2070_16416()\n    \nend\n\n-- [EVENT] Le lit peut être utilisé pour finir la nuit\n-- \nfunction event_2070_16417(playerId)\n    invoke(2000, 1, \"bubble\", playerId, \"quest.huppermage.dortoirs.03\")\nend\n\n","functions":["startCine","endCine","bubble","mobileVisible","event_2070_16409","event_2070_16410","event_2070_16411","mobStart","mobSetFightAnim","event_2070_16413","event_2070_16414","event_2070_16415","event_2070_16416","event_2070_16417"],"quest_calls":[],"dialogue_calls":[]},"scenario/2071.lua":{"source":"function startTutorial()\r\n\tServer.triggerEvent(16429)\r\nend\n\n-- [INSCRIPTION] Le joueur entre dans l'instance\n-- \nfunction event_2071_16419()\n    \nend\n\n-- [INITIALISATION] Le joueur entre dans l'instance\n-- \nfunction event_2071_16476()\n    UI.displayButton(false, \"scenario.endKinematic.confirmEscape\", \"scenario.tutorial.display\", \"startTutorial\")\r\n    \r\n    --templates.bars\r\n    UI.setShortcutEnabled(false, \"shortcutCategory.interface\", \"contactList\")\r\n    UI.setShortcutEnabled(false, \"shortcutCategory.interface\", \"companionManagement\")\r\n    UI.setShortcutEnabled(false, \"shortcutCategory.interface\", \"guild\")\r\n    UI.setShortcutEnabled(false, \"shortcutCategory.interface\", \"craft\")\r\n    UI.setShortcutEnabled(false, \"shortcutCategory.interface\", \"dungeonList\")\r\n    UI.setShortcutEnabled(false, \"shortcutCategory.interface\", \"achievements\")\r\n    UI.setShortcutEnabled(false, \"shortcutCategory.interface\", \"quests\")\r\n    UI.setShortcutEnabled(false, \"shortcutCategory.interface\", \"emotes\")\r\n    UI.setShortcutEnabled(false, \"shortcutCategory.interface\", \"ecosystem\")\r\n    UI.setShortcutEnabled(false, \"shortcutCategory.interface\", \"climate\")\r\n    UI.setShortcutEnabled(false, \"shortcutCategory.interface\", \"nation\")\r\n    UI.setShortcutEnabled(false, \"shortcutCategory.interface\", \"partySearch\")\r\n    UI.setShortcutEnabled(false, \"shortcutCategory.interface\", \"passport\")\r\n    UI.setShortcutEnabled(false, \"shortcutCategory.interface\", \"almanax\")\r\n    UI.setShortcutEnabled(false, \"shortcutCategory.interface\", \"tutorialBook\")\r\n    UI.setShortcutEnabled(false, \"shortcutCategory.interface\", \"switchToDirectAttackCommand\")\r\n    \r\n    --shortcuts.xml\r\n    UI.setShortcutEnabled(false, \"shortcutCategory.interface\", \"map\")\r\n    UI.setShortcutEnabled(false, \"shortcutCategory.interface\", \"minimap\")\r\n    UI.setShortcutEnabled(false, \"shortcutCategory.interface\", \"spellsInventory\")\r\n    UI.setShortcutEnabled(false, \"shortcutCategory.interface\", \"inventory\")\r\n    UI.setShortcutEnabled(false, \"shortcutCategory.interface\", \"characterBook\")\r\n    UI.setShortcutEnabled(false, \"shortcutCategory.interface\", \"vault\")\r\n    UI.setShortcutEnabled(false, \"shortcutCategory.interface\", \"changeShortcutBarType\")\r\n    \r\n    --fightBarTemplate.xml & worldBarTemplate.xml\r\n    UI.setWidgetEnabled(\"worldAndFightBarDialog\",\"fightInfoBtn\",false)\r\n    UI.setWidgetEnabled(\"worldAndFightBarDialog\",\"spellButton\",false)\r\n    UI.setWidgetEnabled(\"worldAndFightBarDialog\",\"inventoryButton\",false)\r\n    UI.setWidgetEnabled(\"worldAndFightBarDialog\",\"craftButton\",false)\r\n    UI.setWidgetEnabled(\"worldAndFightBarDialog\",\"communityButton\",false)\r\n    UI.setWidgetEnabled(\"worldAndFightBarDialog\",\"achievementDrawerButton\",false)\r\n    UI.setWidgetEnabled(\"worldAndFightBarDialog\",\"companionsButton\",false)\r\n    UI.setWidgetEnabled(\"worldAndFightBarDialog\",\"mapButton\",false)\r\n    UI.setWidgetEnabled(\"worldAndFightBarDialog\",\"giveUpButton\",false)\r\n    UI.setWidgetEnabled(\"worldAndFightBarDialog\",\"hideFightersButton\",false)\r\n    UI.setWidgetEnabled(\"worldAndFightBarDialog\",\"reportCellBtn\",false)\r\n    UI.setWidgetEnabled(\"worldAndFightBarDialog\",\"lockFightBtn\",false)\r\n    UI.setWidgetEnabled(\"worldAndFightBarDialog\",\"callHelpBtn\",false)\nend\n\n-- 0 - Début du tutoriel - TUTORIAL_BUTTON_PRESSED\n-- \nfunction event_2071_16429(bouftouId, scaraId, tofuId)\n    --On affiche 'Comment lancer un combat'\r\n    UI.loadTutorialDialog(\"tuto2\",\"tutorial.start.fight.title\",\"tutorial.start.fight.description\")\r\n    \t\r\n    --On place une flèche au dessus du monstre\r\n    if Mobile.isMobile(bouftouId) then\r\n    \tapsBouftou = Particle.addParticleSystemToTargetWithOffset(800177, bouftouId, 1, 5)\r\n    end\r\n    \r\n    if Mobile.isMobile(scaraId) then\r\n    \tapsScara = Particle.addParticleSystemToTargetWithOffset(800177, scaraId, 1, 5)\r\n    end\r\n    \r\n    if Mobile.isMobile(tofuId) then\r\n    \tapsTofu = Particle.addParticleSystemToTargetWithOffset(800177, tofuId, 1, 5)\r\n    end\nend\n\n-- 1 - Comment se placer en phase de préparation - PLAYER_JOIN_FIGHT\n-- \nfunction event_2071_16424(bouftouId, scaraId, tofuId)\n    UI.unloadTutorialDialog()\r\n    \r\n    if Mobile.isMobile(bouftouId) then\r\n    \tParticle.clearParticleSystemOnMobile(bouftouId)\r\n    end\r\n    \r\n    if Mobile.isMobile(scaraId) then\r\n    \tParticle.clearParticleSystemOnMobile(scaraId)\r\n    end\r\n    \r\n    if Mobile.isMobile(tofuId) then\r\n    \tParticle.clearParticleSystemOnMobile(tofuId)\r\n    end\r\n    \r\n    if (apsBouftou ~= nil) then\r\n    \tParticle.removeParticleSystem(apsBouftou)\r\n    end\r\n    \r\n    if (apsScara ~= nil) then\r\n    \tParticle.removeParticleSystem(apsScara)\r\n    end\r\n    \r\n    if (apsTofu ~= nil) then\r\n    \tParticle.removeParticleSystem(apsTofu)\r\n    end\r\n    \r\n    --On affiche 'Comment se placer en phase de préparation'\r\n    UI.loadTutorialDialog(\"tuto9\",\"tutorial.placement.title\",\"tutorial.placement.description\")\r\n    \r\n    --On place la flèche pres du button PRET\r\n    local apsReady = UI.addParticle(\"worldAndFightBarDialog\", \"actionButtonsContainer\", \"800415.xps\", 25, 0, \"EAST\", 75)\nend\n\n-- 2 - Comment utiliser ses PM - FIGHTER_START_TURN\n-- \nfunction event_2071_16425()\n    UI.unloadTutorialDialog()\r\n    UI.clearParticles(\"worldAndFightBarDialog\", \"actionButtonsContainer\")\r\n    \r\n    --On affiche 'Comment utiliser ses PM'\r\n    UI.loadTutorialDialog(\"tuto7\",\"tutorial.move.fight.title\",\"tutorial.move.fight.description\")\r\n    \r\n    --On place une flèche près des PM\r\n    local apsMP = UI.addParticle(\"worldAndFightBarDialog\", \"mpwidget\", \"800415.xps\", 30, 0, \"EAST\", 75)\nend\n\n-- 3 - Comment lancer un sort - FIGHTER_MOVED\n-- \nfunction event_2071_16426()\n    UI.unloadTutorialDialog()\r\n    UI.clearParticles(\"worldAndFightBarDialog\", \"mpwidget\")\r\n    \r\n    --On affiche 'Comment attaquer avec un sort'\r\n    UI.loadTutorialDialog(\"tuto5\",\"tutorial.spell.title\",\"tutorial.spell.description\")\r\n    \r\n    --On place une flèche près du raccourci du sort à utiliser\r\n    local apsSpell = UI.addParticle(\"worldAndFightBarDialog\", \"shortcutBarList#0.borderContainer\", \"800177.xps\", 0, 30, \"NORTH\", 75)\nend\n\n-- 4 - Comment utiliser ses PA - SPELL_CAST\n-- \nfunction event_2071_16430()\n    UI.unloadTutorialDialog()\r\n    UI.clearParticles(\"worldAndFightBarDialog\", \"shortcutBarList#0.borderContainer\")\r\n    \r\n    --On affiche 'Comment utiliser ses PA'\r\n    UI.loadTutorialDialog(\"pa\",\"tutorial.pa.title\",\"tutorial.pa.description\")\r\n    \r\n    --On place une flèche près de passer son tour\r\n    local apsAP = UI.addParticle(\"worldAndFightBarDialog\", \"apwidget\", \"800177.xps\", 0, 30, \"NORTH\", 75)\nend\n\n-- 5 - Comment passer son tour - SPELL_CAST\n-- \nfunction event_2071_16427()\n    UI.unloadTutorialDialog()\r\n    UI.clearParticles(\"worldAndFightBarDialog\", \"apwidget\")\r\n    \r\n    --On affiche 'Comment passer son tour'\r\n    UI.loadTutorialDialog(\"tuto8\",\"tutorial.pass.title\",\"tutorial.pass.description\")\r\n    \r\n    --On place une flèche près de passer son tour\r\n    local apsEnd = UI.addParticle(\"worldAndFightBarDialog\", \"actionButtonsContainer\", \"800415.xps\", 20, 0, \"EAST\", 75)\nend\n\n-- 6 - Fin du tutoriel - FIGHTER_END_TURN\n-- \nfunction event_2071_16428()\n    UI.unloadTutorialDialog()\r\n    UI.clearParticles(\"worldAndFightBarDialog\", \"actionButtonsContainer\")\nend\n\n-- 99 - Fin d'un combat - On décharge tous les visuels du tutoriel\n-- \nfunction event_2071_16483(bouftouId, tofuId, scaraId)\n    UI.unloadTutorialDialog()\r\n    \r\n    if Mobile.isMobile(bouftouId) then\r\n    \tParticle.clearParticleSystemOnMobile(bouftouId)\r\n    end\r\n    \r\n    if Mobile.isMobile(scaraId) then\r\n    \tParticle.clearParticleSystemOnMobile(scaraId)\r\n    end\r\n    \r\n    if Mobile.isMobile(tofuId) then\r\n    \tParticle.clearParticleSystemOnMobile(tofuId)\r\n    end\r\n    \r\n    if (apsBouftou ~= nil) then\r\n    \tParticle.removeParticleSystem(apsBouftou)\r\n    end\r\n    \r\n    if (apsScara ~= nil) then\r\n    \tParticle.removeParticleSystem(apsScara)\r\n    end\r\n    \r\n    if (apsTofu ~= nil) then\r\n    \tParticle.removeParticleSystem(apsTofu)\r\n    end\r\n    \r\n    UI.clearParticles(\"worldAndFightBarDialog\", \"actionButtonsContainer\")\r\n    UI.clearParticles(\"worldAndFightBarDialog\", \"mpwidget\")\r\n    UI.clearParticles(\"worldAndFightBarDialog\", \"apwidget\")\r\n    UI.clearParticles(\"worldAndFightBarDialog\", \"shortcutBarList#0.borderContainer\")\r\n    \r\n    --On replace le bouton pour démarrer un tuto\r\n    --UI.hideButton()\r\n    UI.displayButton(false, \"scenario.endKinematic.confirmEscape\", \"scenario.tutorial.display\", \"startTutorial\")\r\nend\n\n-- Bouftou - Salle 1\n-- \nfunction event_2071_16420()\n    UI.displaySplashText(\"event.grand.place.player.finish.dungeon.room\", 5000)\nend\n\n-- Bouftou - S1 to S2\n-- \nfunction event_2071_16461()\n    \nend\n\n-- Bouftou - S2 to S1\n-- \nfunction event_2071_16462()\n    \nend\n\n-- Bouftou - Salle 2\n-- \nfunction event_2071_16421()\n    UI.displaySplashText(\"event.grand.place.player.finish.dungeon.room\", 5000)\nend\n\n-- Bouftou - S2 to S3\n-- \nfunction event_2071_16463()\n    \nend\n\n-- Bouftou - S3 to S2\n-- \nfunction event_2071_16464()\n    \nend\n\n-- Bouftou - Salle 3\n-- \nfunction event_2071_16422()\n    UI.displaySplas