h.dungeon.room\", 5000)\nend\n\n-- Scara - S3 to S4\n-- \nfunction event_2071_16488()\n    \nend\n\n-- Scara - S4 to S3\n-- \nfunction event_2071_16489()\n    \nend\n\n-- Scara - Salle Boss\n-- \nfunction event_2071_16455()\n    UI.displaySplashText(\"event.grand.place.player.finish.dungeon.boss\", 5000)\nend\n\n-- [INSCRIPTION] Le joueur quitte l'instance\n-- \nfunction event_2071_16608()\n    --templates.bars\r\n    UI.setShortcutEnabled(true, \"shortcutCategory.interface\", \"contactList\")\r\n    UI.setShortcutEnabled(true, \"shortcutCategory.interface\", \"companionManagement\")\r\n    UI.setShortcutEnabled(true, \"shortcutCategory.interface\", \"guild\")\r\n    UI.setShortcutEnabled(true, \"shortcutCategory.interface\", \"craft\")\r\n    UI.setShortcutEnabled(true, \"shortcutCategory.interface\", \"dungeonList\")\r\n    UI.setShortcutEnabled(true, \"shortcutCategory.interface\", \"achievements\")\r\n    UI.setShortcutEnabled(true, \"shortcutCategory.interface\", \"quests\")\r\n    UI.setShortcutEnabled(true, \"shortcutCategory.interface\", \"emotes\")\r\n    UI.setShortcutEnabled(true, \"shortcutCategory.interface\", \"ecosystem\")\r\n    UI.setShortcutEnabled(true, \"shortcutCategory.interface\", \"climate\")\r\n    UI.setShortcutEnabled(true, \"shortcutCategory.interface\", \"nation\")\r\n    UI.setShortcutEnabled(true, \"shortcutCategory.interface\", \"partySearch\")\r\n    UI.setShortcutEnabled(true, \"shortcutCategory.interface\", \"passport\")\r\n    UI.setShortcutEnabled(true, \"shortcutCategory.interface\", \"almanax\")\r\n    UI.setShortcutEnabled(true, \"shortcutCategory.interface\", \"tutorialBook\")\r\n    UI.setShortcutEnabled(true, \"shortcutCategory.interface\", \"switchToDirectAttackCommand\")\r\n    \r\n    --shortcuts.xml\r\n    UI.setShortcutEnabled(true, \"shortcutCategory.interface\", \"map\")\r\n    UI.setShortcutEnabled(true, \"shortcutCategory.interface\", \"minimap\")\r\n    UI.setShortcutEnabled(true, \"shortcutCategory.interface\", \"spellsInventory\")\r\n    UI.setShortcutEnabled(true, \"shortcutCategory.interface\", \"inventory\")\r\n    UI.setShortcutEnabled(true, \"shortcutCategory.interface\", \"characterBook\")\r\n    UI.setShortcutEnabled(true, \"shortcutCategory.interface\", \"vault\")\r\n    UI.setShortcutEnabled(true, \"shortcutCategory.interface\", \"changeShortcutBarType\")\r\n    \r\n    --fightBarTemplate.xml & worldBarTemplate.xml\r\n    UI.setWidgetEnabled(\"worldAndFightBarDialog\",\"fightInfoBtn\",true)\r\n    UI.setWidgetEnabled(\"worldAndFightBarDialog\",\"spellButton\",true)\r\n    UI.setWidgetEnabled(\"worldAndFightBarDialog\",\"inventoryButton\",true)\r\n    UI.setWidgetEnabled(\"worldAndFightBarDialog\",\"craftButton\",true)\r\n    UI.setWidgetEnabled(\"worldAndFightBarDialog\",\"communityButton\",true)\r\n    UI.setWidgetEnabled(\"worldAndFightBarDialog\",\"achievementDrawerButton\",true)\r\n    UI.setWidgetEnabled(\"worldAndFightBarDialog\",\"companionsButton\",true)\r\n    UI.setWidgetEnabled(\"worldAndFightBarDialog\",\"mapButton\",true)\r\n    UI.setWidgetEnabled(\"worldAndFightBarDialog\",\"giveUpButton\",true)\r\n    UI.setWidgetEnabled(\"worldAndFightBarDialog\",\"hideFightersButton\",true)\r\n    UI.setWidgetEnabled(\"worldAndFightBarDialog\",\"reportCellBtn\",true)\r\n    UI.setWidgetEnabled(\"worldAndFightBarDialog\",\"lockFightBtn\",true)\r\n    UI.setWidgetEnabled(\"worldAndFightBarDialog\",\"callHelpBtn\",true)\nend\n\n","functions":["startTutorial","event_2071_16419","event_2071_16476","event_2071_16429","event_2071_16424","event_2071_16425","event_2071_16426","event_2071_16430","event_2071_16427","event_2071_16428","event_2071_16483","event_2071_16420","event_2071_16461","event_2071_16462","event_2071_16421","event_2071_16463","event_2071_16464","event_2071_16422","event_2071_16465","event_2071_16466","event_2071_16423","event_2071_16457","event_2071_16477","event_2071_16478","event_2071_16458","event_2071_16479","event_2071_16480","event_2071_16459","event_2071_16481","event_2071_16482","event_2071_16460","event_2071_16452","event_2071_16484","event_2071_16485","event_2071_16453","event_2071_16486","event_2071_16487","event_2071_16454","event_2071_16488","event_2071_16489","event_2071_16455","event_2071_16608"],"quest_calls":[],"dialogue_calls":[]},"scenario/2072.lua":{"source":"\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_2072_16431()\n    \nend\n\n-- Lancement du combat\n-- \nfunction event_2072_16432()\n    UI.loadTutorialDialog(\"huppermageTaquin\",\"quest.huppermage.taquin.tutorial.title\",\"quest.huppermage.taquin.tutorial.desc\")\nend\n\n-- [Quête Branchie-Fleur] (2786) Le joueur marche sur la Zone Trigger\n-- \nfunction event_2072_16500()\n    playerId = Context.getLeaderId()\r\n    \r\n    function bubble(mob,text)\r\n    \tBubbleText.closeBubbleAttachedTo(mob)\r\n    \tBubbleText.showText(mob, text, 0, 40, false)\r\n    end\r\n    \r\n    bubble(playerId, \"quest.huppermage.salle.inondee.01\")\r\n    invoke(3500, 1, \"bubble\", playerId, \"quest.huppermage.salle.inondee.02\")\r\n    invoke(7000, 1, \"bubble\", playerId, \"quest.huppermage.salle.inondee.03\")\nend\n\n-- Feedback bulle - Le joueur marche sur le TP mais ne peut pas descendre\n-- \nfunction event_2072_16607()\n    playerId = Context.getLeaderId()\r\n    \r\n    function bubble(mob,text)\r\n    \tBubbleText.closeBubbleAttachedTo(mob)\r\n    \tBubbleText.showText(mob, text, 0, 40, false)\r\n    end\r\n    \r\n    bubble(playerId, \"quest.huppermage.salle.inondee.00\")\nend\n\n-- [Quête Taquiner la Grosse Epée] (2785) Le joueur gagne l'épreuve\n-- \nfunction event_2072_16603(npcStuff)\n    \tplayerId = Context.getLeaderId()\r\n    \r\n    invoke(2000, 1, \"BubbleText.showText\", playerId, \"quest.huppermage.taquin.01\", -25, 45, false)\r\n    invoke(5000, 1, \"BubbleText.showText\", npcStuff, \"quest.huppermage.taquin.02\", 0, 75, false)\nend\n\n","functions":["event_2072_16431","event_2072_16432","event_2072_16500","bubble","event_2072_16607","bubble","event_2072_16603"],"quest_calls":[],"dialogue_calls":[]},"scenario/2073.lua":{"source":"\n\n-- [INIT] Initialisation des variables\n-- \nfunction event_2073_16433()\n    \nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_2073_16434()\n    \nend\n\n-- [EVENT] Défi #1 (facile) - Lancement\n-- \nfunction event_2073_16734()\n    UI.loadTutorialDialog(\"null\",\"quest.huppermage.sokoban.tutorial.title\",\"quest.huppermage.sokoban.tutorial.desc\")\r\n    Mobile.setMobileAnimationStaticKey(Context.getLeaderId(), \"AnimStatique01\")\nend\n\n-- [EVENT] Défi #1 (facile) - Début\n-- \nfunction event_2073_16735()\n    \nend\n\n-- [EVENT] Défi #1 (facile) - Victoire - Validation Quête\n-- \nfunction event_2073_16736()\n    \nend\n\n-- [EVENT] Défi #2 (intermédiaire) - Lancement\n-- \nfunction event_2073_16737()\n    UI.loadTutorialDialog(\"null\",\"quest.huppermage.sokoban.tutorial.title\",\"quest.huppermage.sokoban.tutorial.desc\")\r\n    Mobile.setMobileAnimationStaticKey(Context.getLeaderId(), \"AnimStatique01\")\nend\n\n-- [EVENT] Défi #2 (intermédiaire) - Début\n-- \nfunction event_2073_16738()\n    \nend\n\n-- [EVENT] Défi #2 (intermédiaire) - Victoire - Validation Quête\n-- \nfunction event_2073_16739()\n    \nend\n\n-- [EVENT] Défi #3 (difficile) - Lancement\n-- \nfunction event_2073_16740()\n    UI.loadTutorialDialog(\"null\",\"quest.huppermage.sokoban.tutorial.title\",\"quest.huppermage.sokoban.tutorial.desc\")\r\n    Mobile.setMobileAnimationStaticKey(Context.getLeaderId(), \"AnimStatique01\")\nend\n\n-- [EVENT] Défi #3 (difficile) - Début\n-- \nfunction event_2073_16741()\n    \nend\n\n-- [EVENT] Défi #3 (difficile) - Victoire - Validation Quête\n-- \nfunction event_2073_16742()\n    \nend\n\n-- [IE] Ouverture du passage secret\n-- \nfunction event_2073_16440()\n    World.setPictoAlpha(48, -38, 28, 0, 1000)\nend\n\n-- [IE] Fermeture du passage secret\n-- \nfunction event_2073_16441()\n    World.setPictoAlpha(48, -38, 28, 1, 1000)\nend\n\n-- [EVENT] Fin de combat - On remet la variable à zéro\n-- \nfunction event_2073_16748()\n    \nend\n\n","functions":["event_2073_16433","event_2073_16434","event_2073_16734","event_2073_16735","event_2073_16736","event_2073_16737","event_2073_16738","event_2073_16739","event_2073_16740","event_2073_16741","event_2073_16742","event_2073_16440","event_2073_16441","event_2073_16748"],"quest_calls":[],"dialogue_calls":[]},"scenario/2074.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\n\n-- [EVENT] Initialisation\n-- \nfunction event_2074_16446(playerId)\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2074_16447()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - pas de combat en cours\n-- \nfunction event_2074_20857()\n    UI.loadTutorialDialog(\"null\",\"quest.nations.ch03.bibliofeustart.rules.title\",\"quest.nations.ch03.bibliofeustart.rules.desc\")\r\n    \r\n    local gankr = createActor(178603773, -18, 0, 0,4, 1, 8)\r\n    Mobile.setMobileVisible(gankr, false)\r\n    \r\n    startCinematicContext(1.5, gankr)\r\n    \r\n    invoke_custom(0100, 1, \"Mobile.setMobileVisible\", gankr, true)\r\n    invoke_custom(1000, 1, \"bubble\", gankr, \"quest.nationch3.bibliofire.gankr.01\")\r\n    invoke_custom(1000, 1, \"Mobile.setMobileAnimation\", gankr, \"AnimComp-Dialogue-01\")\r\n    invoke_custom(4200, 1, \"bubble\", gankr, \"quest.nationch3.bibliofire.gankr.02\")\r\n    invoke_custom(5000, 1, \"Mobile.setMobileAnimation\", gankr, \"AnimComp-01\")\r\n    invoke_custom(8000, 1, \"Mobile.setMobileDirection\", gankr, 5)\r\n    invoke_custom(8500, 1, \"bubble\", gankr, \"quest.nationch3.bibliofire.gankr.03\")\r\n    invoke_custom(9500, 1, \"Mobile.moveMobile\",gankr, -22, 4, 4)\r\n    invoke(12000, 1, \"skipCinematic\")\nend\n\n-- [INIT] ENTER_INSTANCE - combat en cours\n-- \nfunction event_2074_16451()\n    UI.loadTutorialDialog(\"null\",\"quest.running.title\",\"quest.dd.ch1.inglorium.running.desc\")\nend\n\n-- [COMBAT] Combat - Enregistrement de l'évènement\n-- \nfunction event_2074_16449()\n    \nend\n\n-- [ACTION] Fin de combat gagnant\n-- \nfunction event_2074_16450()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_2074_16446","event_2074_16447","event_2074_20857","event_2074_16451","event_2074_16449","event_2074_16450"],"quest_calls":[],"dialogue_calls":[]},"scenario/2075.lua":{"source":"light_info = {}\r\nlight_info[26163] = {-2 ,-1 ,0,nil}\r\nlight_info[26164] = {-21,-4 ,0,nil}\r\nlight_info[26165] = {-32,-4 ,0,nil}\r\nlight_info[26166] = {-7 ,-10,0,nil}\r\nlight_info[26167] = {-13,-30,0,nil}\r\nlight_info[26168] = {-25,-30,0,nil}\r\nlight_info[26169] = {-1 ,-18,0,nil}\n\n-- [INIT] Variable Globales\n-- \nfunction event_2075_16519()\n    \nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_2075_16499()\n    player_zoom_factor = Camera.getZoomFactor()\r\n    Camera.setUserZoomLocked(true)\r\n    Camera.setZoomFactor(2)\r\n    \r\n    UI.loadTutorialDialog(\"null\",\"quest.huppermage.labyrinthe.tutorial.title\",\"quest.huppermage.labyrinthe.tutorial.desc\")\nend\n\n-- Le joueur quitte l'instance\n-- \nfunction event_2075_16501()\n    UI.stopCountdown()\r\n    Camera.setUserZoomLocked(false)\r\n    \r\n    if (player_zoom_factor ~= nil) then\r\n    \tCamera.setZoomFactor(player_zoom_factor)\r\n    end\nend\n\n-- LIGHT - Interaction avec IE Lampe\n-- \nfunction event_2075_16492(extraTime, startDate, actualDate, isRunning, baseTime, lightId)\n    \tlocal openDate = toLong(startDate)\r\n    \tlocal currentDate = toLong(actualDate)\r\n    \tlocal extra = toLong(extraTime)\r\n    \tlocal base = toLong(baseTime)\r\n    \tlocal open = isRunning\r\n    \tlocal remaining = 0\r\n    \tlocal elapsed = 0\r\n    \r\n    \tif (openDate ~= nil and openDate > 0 and currentDate ~= nil and currentDate > 0) then\r\n    \r\n    \t\telapsed = currentDate - openDate\r\n    \t\t\r\n    \t\tif (elapsed ~= nil  and elapsed > 0) then\r\n    \t\t\tremaining =  math.floor((base + extra - elapsed) / 1000)\r\n    \t\tend\r\n    \tend\r\n    \r\n    \tUI.stopCountdown()\r\n    \tif (remaining > 0 and open) then\r\n    \t\tUI.startCountdown(remaining)\r\n    \tend\r\n    \r\n    \t--On retire la lumière sur l'IE et on save l'information comme quoi elle est éteinte\r\n    \tlocal elementId = toLong(lightId)\r\n    \tlocal light = light_info[elementId][4]\r\n    \t\r\n    \tif (light ~= nil) then\r\n    \t\tLight.removePointLight(light)\r\n    \tend\nend\n\n-- START - Le joueur active le levier qui démarre l'épreuve\n-- \nfunction event_2075_16495(baseTime)\n    --On démarre le timer de l'épreuve\r\n    local timing = toLong(baseTime)\r\n    UI.stopCountdown()\r\n    UI.startCountdown(timing/1000)\r\n    \r\n    --On va boucler sur tous les IE dont le callback de création à proc, pour montrer un peu à quoi ressemble le labyrinthe\r\n    local delay = 0\r\n    local lightId = 0\r\n    local x = 0\r\n    local y = 0\r\n    local z = 0\r\n    \r\n    for key, value in pairs(light_info) do\r\n    \t\tx = light_info[key][1] \r\n    \t\ty = light_info[key][2] \r\n    \t\tz = light_info[key][3] \r\n    \t\r\n    \t\tlightId = Light.addPointLight(x, y, z, 1, 0.9, 0.2, 2)\r\n    \t\tlight_info[key][4] = lightId\r\n    \r\n    \tif (key ~= 26167 and key ~= 26168 and key ~= 26163) then\r\n    \t\tinvoke(delay, 1, \"Camera.scrollTo\", x, y, z)\r\n    \t\tdelay = delay + 1000\r\n    \tend\r\n    end\r\n    \r\n    --On ajoute une lumière verte à la sortie\r\n    local finishLight = Light.addPointLight(-35, -8, 0, 0, 1, 0, 3)\r\n    \t\r\n    --On ramène la caméra sur le player\r\n    invoke(delay, 1, \"Camera.attachCameraToMobile\", Context.getLeaderId())\nend\n\n-- UPDATE - Relance du timer (1s)\n-- \nfunction event_2075_16498()\n    \nend\n\n-- END - Le joueur n'a plus de temps\n-- \nfunction event_2075_16497()\n    UI.stopCountdown()\nend\n\n-- WIN - Le joueur arrive à la sortie\n-- \nfunction event_2075_16515()\n    \nend\n\n-- FALL - Le joueur tombe dans un trou\n-- \nfunction event_2075_16496()\n    function fall()\r\n    \tlocal player = Context.getLeaderId()\r\n    \r\n    \tif (Mobile.isMoving(player)) then\r\n    \t\tMobile.onPathEnded(player, \"startChute\", player)\r\n    \telse\r\n    \t\tActor.stopMovingActor(player)\r\n    \t\tstartChute(player)\r\n    \tend\r\n    end\r\n    \r\n    function startChute(id)\r\n    \tMobile.setMobileNext4Direction(id)\r\n    \tlocal x,y,z = Mobile.getMobilePosition(id)\r\n    \tMobile.setMobileAnimation(id, \"AnimIncarnam-Chute-Fin\")\r\n    \r\n    \tParticle.addParticleSystem(800174, x,y,z)\r\n    end\r\n    \r\n    fall()\nend\n\n-- DOOR - Le joueur active le levier qui ouvre la porte 1\n-- \nfunction event_2075_16516()\n    local player = Context.getLeaderId()\r\n    BubbleText.closeBubbleAttachedTo(player)\r\n    BubbleText.showText(player, \"quest.huppermage.labyrinthe.01\", 0, 40, false)\nend\n\n-- DOOR - Le joueur active le levier qui ouvre la porte 2\n-- \nfunction event_2075_16556()\n    local player = Context.getLeaderId()\r\n    BubbleText.closeBubbleAttachedTo(player)\r\n    BubbleText.showText(player, \"quest.huppermage.labyrinthe.01\", 0, 40, false)\nend\n\n","functions":["event_2075_16519","event_2075_16499","event_2075_16501","event_2075_16492","event_2075_16495","event_2075_16498","event_2075_16497","event_2075_16515","event_2075_16496","fall","startChute","event_2075_16516","event_2075_16556"],"quest_calls":[],"dialogue_calls":[]},"scenario/2076.lua":{"source":"\n\n-- [INIT] Initialisation des variables\n-- \nfunction event_2076_16502()\n    \nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_2076_16503()\n    playerId = Context.getLeaderId()\r\n    \r\n    function bubble(mob,text)\r\n    \tBubbleText.closeBubbleAttachedTo(mob)\r\n    \tBubbleText.showText(mob, text, 0, 40, false)\r\n    end\r\n    \r\n    Camera.setZoomFactor(1.4)\r\n    bubble(playerId, \"quest.huppermage.salle.inondee.04\")\nend\n\n-- [EVENT] Aller - Spawn group + cam arrivée\n-- \nfunction event_2076_16504()\n    playerId = Context.getLeaderId()\r\n    \r\n    Camera.setMoveSpeedFactor(0.2)\r\n    Camera.setZoomFactor(1.4)\r\n    Camera.scrollTo(0, -35, 0, \"Camera.attachCameraToMobile\", playerId)\r\n    invoke(15000, 1, \"Camera.setMoveSpeedFactor\", 1)\r\n    local aps = Particle.addParticleSystem(800016, 0, -35, 0)\r\n    invoke(15000, 1, \"Particle.removeParticleSystem\", aps, false)\nend\n\n-- [EVENT] Aller - Lancement du combat + tuto\n-- \nfunction event_2076_16512()\n    UI.loadTutorialDialog(\"null\",\"quest.huppermage.salle.inondee.tutorial.title\",\"quest.huppermage.salle.inondee.tutorial.desc\")\nend\n\n-- [EVENT] Aller - Pose des glyphes et état sur le joueur\n-- \nfunction event_2076_16513()\n    \nend\n\n-- [EVENT] Combat gagnant - Le coffre peut être utilisé\n-- \nfunction event_2076_16509()\n    \nend\n\n-- [EVENT] Utilisation Coffre - Le trigger de retour est activé\n-- \nfunction event_2076_16511()\n    playerId = Context.getLeaderId()\r\n    \r\n    function bubble(mob,text)\r\n    \tBubbleText.closeBubbleAttachedTo(mob)\r\n    \tBubbleText.showText(mob, text, 0, 40, false)\r\n    end\r\n    \r\n    bubble(playerId, \"quest.huppermage.salle.inondee.05\")\r\n    invoke(3500, 1, \"bubble\", playerId, \"quest.huppermage.salle.inondee.06\")\nend\n\n-- [EVENT] Retour - Spawn group et lancement combat\n-- \nfunction event_2076_16510()\n    \nend\n\n-- [EVENT] Retour - Pose des glyphes et état sur le joueur\n-- \nfunction event_2076_16514()\n    \nend\n\n-- [EVENT] Combat perdant - MàJ variable\n-- \nfunction event_2076_16506()\n    \nend\n\n-- [EVENT] Combat gagnant - MàJ variable\n-- \nfunction event_2076_16507()\n    \nend\n\n-- [EVENT] Combat perdant - Tp / Rez des joueurs\n-- \nfunction event_2076_16508()\n    \nend\n\n","functions":["event_2076_16502","event_2076_16503","bubble","event_2076_16504","event_2076_16512","event_2076_16513","event_2076_16509","event_2076_16511","bubble","event_2076_16510","event_2076_16514","event_2076_16506","event_2076_16507","event_2076_16508"],"quest_calls":[],"dialogue_calls":[]},"scenario/2077.lua":{"source":"m_playerId = Context.getPlayer()\n\n-- Starter et Initiation inactifs - TP vers l'école\n-- \nfunction event_2077_16518()\n    \nend\n\n-- Starter ou Initiation actif - TP vers l'initiation\n-- \nfunction event_2077_16517()\n    \nend\n\n","functions":["event_2077_16518","event_2077_16517"],"quest_calls":[],"dialogue_calls":[]},"scenario/2078.lua":{"source":"function startCine(cineZoomFactor)\r\n\tzoomFactor = Camera.getZoomFactor()\r\n\tUI.manageFrame(\"World\", false)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tUI.setShortcutEnabled(false)\r\n\tCamera.setZoomFactor(cineZoomFactor)\r\nend\r\n\r\nfunction endCine()\r\n\tCamera.attachCameraToMobile(playerId)\r\n\tUI.displayWideScreenBand(false)\r\n\tCamera.setUserZoomLocked(false)\r\n\tUI.setUIVisible(true)\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.hideButton()\r\n\tUI.setShortcutEnabled(true)\r\n\t\r\n\tif (zoomFactor ~= nil and zoomFactor > 0) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\nend\r\n\r\nfunction bubble(mob,text)\r\n\tBubbleText.closeBubbleAttachedTo(mob)\r\n\tBubbleText.showText(mob, text, 0, 40, false)\r\nend\n\n-- [INIT] Initialisation des variables\n-- \nfunction event_2078_16750()\n    \nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_2078_16521()\n    \nend\n\n-- [EVENT] Le joueur inspecte le bon IE (validation objectif pour tout le monde)\n-- \nfunction event_2078_18704()\n    \nend\n\n-- [EVENT] Le joueur inspecte le bon IE\n-- \nfunction event_2078_16523(mobOne, mobTwo, mobThree, mobFour)\n    playerId = Context.getLeaderId()\r\n    \r\n    function mobStart(mobId, direction)\r\n    \tCamera.attachCameraToMobile(mobId)\r\n    \tinvoke(500, 1, \"Mobile.setMobileVisible\", mobId, true)\r\n    \tinvoke(500, 1, \"Mobile.setMobileDirection\", mobId, direction)\r\n    \tinvoke(500, 1, \"Mobile.setMobileAnimation\", mobId, \"AnimTransEffect-Fin-Fin\")\r\n    end\r\n    \r\n    Mobile.setMobileVisible(mobOne, false)\r\n    Mobile.setMobileVisible(mobTwo, false)\r\n    Mobile.setMobileVisible(mobThree, false)\r\n    Mobile.setMobileVisible(mobFour, false)\r\n    invoke(0, 1, \"bubble\", playerId, \"quest.huppermage.remise.01\")\r\n    invoke(1500, 1, \"startCine\", 1.0)\r\n    invoke(1500, 1, \"Camera.attachCameraToMobile\", playedId)\r\n    invoke(1500, 1, \"Camera.setZoomFactor\", 4.0)\r\n    invoke(4000, 1, \"bubble\", playerId, \"quest.huppermage.remise.02\")\r\n    invoke(10000, 1, \"Mobile.moveMobile\", playerId, -2, -12, 0)\r\n    invoke(12000, 1, \"bubble\", playerId, \"quest.huppermage.remise.03\")\r\n    invoke(15000, 1, \"Camera.zoomOn\", 4.0, 10000, 0, -1, 0)\r\n    invoke(15000, 1, \"mobStart\", mobOne, 7)\r\n    invoke(15300, 1, \"mobStart\", mobTwo, 7)\r\n    invoke(15500, 1, \"mobStart\", mobThree, 7)\r\n    invoke(15650, 1, \"mobStart\", mobFour, 7)\r\n    invoke(16300, 1, \"bubble\", mobTwo, \"quest.huppermage.remise.04\")\r\n    invoke(20000, 1, \"Mobile.moveMobile\", mobTwo, -1, -3, 0)\r\n    invoke(20150, 1, \"Mobile.moveMobile\", mobOne, 1, -3, 0)\r\n    invoke(20400, 1, \"Mobile.moveMobile\", mobFour, 2, -5, 0)\r\n    invoke(20600, 1, \"Mobile.moveMobile\", mobThree, -2, -5, 0)\r\n    invoke(22500, 1, \"bubble\", mobTwo, \"quest.huppermage.remise.05\")\r\n    invoke(25000, 1, \"endCine\")\nend\n\n-- [EVENT] Lancement du combat\n-- \nfunction event_2078_16524()\n    UI.loadTutorialDialog(\"null\",\"quest.huppermage.remise.tutorial.title\",\"quest.huppermage.remise.tutorial.desc\")\nend\n\n-- [EVENT] Combat perdant\n-- \nfunction event_2078_16549()\n    \nend\n\n-- [EVENT] Combat gagnant\n-- \nfunction event_2078_16550()\n    \nend\n\n-- [EVENT] Téléportation des joueurs perdants\n-- \nfunction event_2078_16551()\n    \nend\n\n","functions":["startCine","endCine","bubble","event_2078_16750","event_2078_16521","event_2078_18704","event_2078_16523","mobStart","event_2078_16524","event_2078_16549","event_2078_16550","event_2078_16551"],"quest_calls":[],"dialogue_calls":[]},"scenario/2079.lua":{"source":"m_playerId = Context.getPlayer()\n\n-- Starter et Initiation inactifs - TP vers l'école\n-- \nfunction event_2079_16529()\n    \nend\n\n","functions":["event_2079_16529"],"quest_calls":[],"dialogue_calls":[]},"scenario/2081.lua":{"source":"function addAmbianceParticle(apsId,x,y,z)\r\n\tlocal particle = Particle.addParticleSystem(apsId,x,y,z)\r\n\t\r\n\ttable.insert(ambiance_particles, particle)\r\nend\r\n\r\nfunction clearAmbianceParticles()\r\n\tfor key,value in pairs(ambiance_particles) do\r\n\t\tParticle.removeParticleSystem(value, true)\r\n\tend\r\nend\r\n\r\nfunction hideAll(xStart, xEnd, yStart, yEnd, zStart, zEnd, fadeDuration)\r\n\tfor x = xStart, xEnd, 1 do\r\n\t\tfor y = yStart, yEnd, 1 do\r\n\t\t\tfor z = zStart, zEnd, 1 do\r\n\t\t\t\tWorld.setPictoAlpha(x, y, z, 0, fadeDuration)\r\n\t\t\tend\r\n\t\tend\r\n\tend\r\nend\r\n\r\nfunction showAll(xStart, xEnd, yStart, yEnd, zStart, zEnd, fadeDuration)\r\n\tlocal delayx = 0\r\n\tlocal delayy = 0\r\n\tlocal delayz = 0\r\n\t\r\n\tlocal baseDelay = 100\r\n\t\r\n\tlocal xSize = abs(xStart-xEnd) \r\n\tlocal ySize = abs(yStart-yEnd)\r\n\tlocal xRatio = 1\r\n\tlocal yRatio = 1\r\n\t\r\n\tif (xSize <= ySize) then\r\n\t\txRatio = ySize / xSize\r\n\t\tyRatio = 1\r\n\telse\r\n\t\txRatio = 1\r\n\t\tyRatio = xSize / ySize\r\n\tend\r\n\t\r\n\tfor x = xStart, xEnd, 1 do\r\n\t\tfor y = yStart, yEnd, 1 do\r\n\t\t\tfor z = zStart, zEnd, 1 do\r\n\t\t\t\t invoke(delayx + delayy + delayz, 1, \"World.setPictoAlpha\", x, y, z, 255, fadeDuration)\r\n\t\t\t\t invoke(delayx + delayy + delayz + fadeDuration, 1, \"World.removePictoAlpha\", x, y, z)\r\n\t\t\t\t --delayz = delayz + 25\r\n\t\t\tend\r\n\t\t\tdelayz = 0\r\n\t\t\tdelayy = delayy + (baseDelay*yRatio)\r\n\t\tend\r\n\t\tdelayy = 0\r\n\t\tdelayx = delayx + (baseDelay*xRatio)\r\n\tend\r\nend\r\n\r\nfunction startCine(cineZoomFactor)\r\n\tUI.manageFrame(\"World\", false)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tUI.setShortcutEnabled(false)\r\n\tCamera.setZoomFactor(cineZoomFactor)\r\n\t\r\nend\r\n\r\nfunction endCine()\r\n\tUI.displayWideScreenBand(false)\r\n\tCamera.setUserZoomLocked(false)\r\n\tUI.setUIVisible(true)\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.hideButton()\r\n\tUI.setShortcutEnabled(true)\r\n\t\r\n\tif (zoomFactor ~= nil and zoomFactor > 0) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\nend\r\n\r\nfunction bubble(mob,text)\r\n\tBubbleText.closeBubbleAttachedTo(mob)\r\n\tif (text ~= \"\") then\r\n\t\tBubbleText.showText(mob, text, 0, 70, false)\r\n\tend\r\nend\r\n\r\nbossMobileId = Mobile.generateClientMobileId()\r\nboss_pos = {{0,-29,12}, {162,145,12}, {105,92,12}, {55,37,12}, {-53,-56,12}}\r\nambiance_particles = {}\r\n\r\npos = {{-4,-12,8}, {-4,-19,8}, {4,-19,8}, {-4,19,8}} -- AIR, EAU, TERRE, FEU\r\nteleporter_lights = {}\n\n-- [INITILISATION]\n-- \nfunction event_2081_16535()\n    \nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_2081_16531()\n    \nend\n\n-- Salle 0 - Base - Le joueur marche sur le trigger\n-- \nfunction event_2081_16532()\n    local x = boss_pos[1][1]\r\n    local y = boss_pos[1][2]\r\n    local z = boss_pos[1][3]\r\n    \r\n    --On prépare le mobile du boss\r\n    if not Mobile.isMobile(bossMobileId) then\r\n    \tActor.createActor(bossMobileId, 180103926, x, y, z)\r\n    \tMobile.setMobileVisible(bossMobileId, false)\r\n    \tMobile.setMobileDirection(bossMobileId, 3)\r\n    end\r\n    \r\n    --On démarre la ciné et on place la caméra au centre et on ajuste le zoom\r\n    startCine(0.7)\r\n    invoke(500, 1, \"Camera.scrollTo\", x, y + 5, z)\r\n    \r\n    --On joue l'apparition du Boss avec la particule qui va bien\r\n    invoke(1000, 1, \"Mobile.setMobileVisible\", bossMobileId, true)\r\n    invoke(1000, 1, \"Mobile.setMobileAnimation\", bossMobileId, \"AnimSort-05\")\r\n    invoke(1400, 1, \"Particle.addParticleSystemToTarget\", 4101370, bossMobileId)\r\n    \r\n    --On affiche les bulles de texte\r\n    invoke(3000, 1, \"bubble\", bossMobileId, \"quest.huppermage.dungeon.00.01\")\r\n    \r\n    invoke(6000, 1, \"Mobile.setMobileAnimation\", bossMobileId, \"AnimSort-01\")\r\n    invoke(7000, 1, \"bubble\", bossMobileId, \"quest.huppermage.dungeon.00.02\")\r\n    invoke(13000, 1, \"Mobile.setMobileAnimation\", bossMobileId, \"AnimSort-02\")\r\n    invoke(14000, 1, \"bubble\", bossMobileId, \"quest.huppermage.dungeon.00.03\")\r\n    \r\n    invoke(17000, 1, \"hideAll\", 150, 171, 137, 175, -6, 40, 0) --On masque la salle AIR\r\n    \r\n    --On déplace le Boss\r\n    invoke(19000, 1, \"Mobile.setMobilePosition\", bossMobileId, boss_pos[2][1], boss_pos[2][2], boss_pos[2][3])\nend\n\n-- Salle 0 - Base - TP dans la salle 1\n-- \nfunction event_2081_16534(dungeonProgress)\n    --On replace la caméra sur le joueur\r\n    Camera.attachCameraToMobile(Context.getLeaderId())\r\n    \r\n    local index = toLong(dungeonProgress)\r\n    local lightId = Particle.addParticleSystem(7088003, pos[index][1], pos[index][2], pos[index][3])\r\n    table.insert(teleporter_lights, lightId)\r\n    \r\n    showAll(150, 171, 137, 175, -6, 40, 0) --On affiche la salle AIR\r\n    \r\n    local targetApsId = 71017009\r\n    \r\n    invoke(7000, 1, \"addAmbianceParticle\", targetApsId, boss_pos[2][1], boss_pos[2][2]+10, 0) -- Particules de Vent\r\n    invoke(7000, 1, \"endCine\")\nend\n\n-- Salle 1 - Air - Le joueur marche sur le trigger\n-- \nfunction event_2081_16553()\n    \nend\n\n-- Salle 1 - Air - Début du combat\n-- \nfunction event_2081_16545()\n    clearAmbianceParticles()\nend\n\n-- Salle 1 - Air - Victoire des joueurs\n-- \nfunction event_2081_16743()\n    \nend\n\n-- Salle 1 - Air - Fin du combat (Victoire)\n-- \nfunction event_2081_16537()\n    local x = boss_pos[2][1]\r\n    local y = boss_pos[2][2]\r\n    local z = boss_pos[2][3]\r\n    \r\n    --On prépare le mobile du boss\r\n    if not Mobile.isMobile(bossMobileId) then\r\n    \tActor.createActor(bossMobileId, 180103926, x, y, z)\r\n    \tMobile.setMobileVisible(bossMobileId, false)\r\n    \tMobile.setMobileDirection(bossMobileId, 3)\r\n    end\r\n    \r\n    --On démarre la ciné et on place la caméra au centre et on ajuste le zoom\r\n    startCine(0.7)\r\n    Mobile.setMobileVisible(bossMobileId, true)\r\n    invoke(500, 1, \"Camera.scrollTo\", x, y + 5, z)\r\n    \r\n    --On affiche les bulles de texte\r\n    invoke(1000, 1, \"bubble\", bossMobileId, \"quest.huppermage.dungeon.01.01\")\r\n    invoke(4000, 1, \"Mobile.setMobileAnimation\", bossMobileId, \"AnimSort-01\")\r\n    invoke(5000, 1, \"bubble\", bossMobileId, \"quest.huppermage.dungeon.01.02\")\r\n    invoke(11000, 1, \"Mobile.setMobileAnimation\", bossMobileId, \"AnimSort-02\")\r\n    invoke(12000, 1, \"bubble\", bossMobileId, \"quest.huppermage.dungeon.01.03\")\r\n    \r\n    invoke(15000, 1, \"hideAll\", 90, 115, 84, 122, -6, 40, 0) --On masque la salle EAU\r\n    \r\n    --On déplace le Boss\r\n    invoke(17000, 1, \"Mobile.setMobilePosition\", bossMobileId, boss_pos[3][1], boss_pos[3][2], boss_pos[3][3])\nend\n\n-- Salle 1 - Air - TP dans la salle 2\n-- \nfunction event_2081_16536(dungeonProgress)\n    --On replace la caméra sur le joueur\r\n    Camera.attachCameraToMobile(Context.getLeaderId())\r\n    \r\n    local index = toLong(dungeonProgress)\r\n    local lightId = Particle.addParticleSystem(7088003, pos[index][1], pos[index][2], pos[index][3])\r\n    table.insert(teleporter_lights, lightId)\r\n    \r\n    showAll(90, 115, 84, 122, -6, 40, 0) --On affiche la salle EAU\r\n    \r\n    local targetApsId = 71017008\r\n    \r\n    invoke(7000, 1, \"addAmbianceParticle\", targetApsId, boss_pos[3][1], boss_pos[3][2], 0) -- Particules de Pluie\r\n    invoke(7000, 1, \"endCine\")\nend\n\n-- Salle 2 - Eau - Le joueur marche sur le trigger\n-- \nfunction event_2081_16554()\n    \nend\n\n-- Salle 2 - Eau - Début du combat\n-- \nfunction event_2081_16546()\n    clearAmbianceParticles()\nend\n\n-- Salle 2 - Eau - Victoire des joueurs\n-- \nfunction event_2081_16744()\n    \nend\n\n-- Salle 2 - Eau - Fin du combat (Victoire)\n-- \nfunction event_2081_16538()\n    local x = boss_pos[3][1]\r\n    local y = boss_pos[3][2]\r\n    local z = boss_pos[3][3]\r\n    \r\n    --On prépare le mobile du boss\r\n    if not Mobile.isMobile(bossMobileId) then\r\n    \tActor.createActor(bossMobileId, 180103926, x, y, z)\r\n    \tMobile.setMobileVisible(bossMobileId, false)\r\n    \tMobile.setMobileDirection(bossMobileId, 3)\r\n    end\r\n    \r\n    --On démarre la ciné et on place la caméra au centre et on ajuste le zoom\r\n    startCine(0.7)\r\n    Mobile.setMobileVisible(bossMobileId, true)\r\n    invoke(500, 1, \"Camera.scrollTo\", x, y + 5, z)\r\n    \r\n    --On affiche les bulles de texte\r\n    invoke(1000, 1, \"bubble\", bossMobileId, \"quest.huppermage.dungeon.02.01\")\r\n    invoke(4000, 1, \"Mobile.setMobileAnimation\", bossMobileId, \"AnimSort-01\")\r\n    invoke(5000, 1, \"bubble\", bossMobileId, \"quest.huppermage.dungeon.02.02\")\r\n    invoke(11000, 1, \"Mobile.setMobileAnimation\", bossMobileId, \"AnimSort-02\")\r\n    invoke(12000, 1, \"bubble\", bossMobileId, \"quest.huppermage.dungeon.02.03\")\r\n    \r\n    invoke(15000, 1, \"hideAll\", 45, 63, 29, 67, -6, 40, 0) --On masque la salle TERRE\r\n    \r\n    --On déplace le Boss\r\n    invoke(17000, 1, \"Mobile.setMobilePosition\", bossMobileId, boss_pos[4][1], boss_pos[4][2], boss_pos[4][3])\nend\n\n-- Salle 2 - Eau - TP dans la salle 3\n-- \nfunction event_2081_16539(dungeonProgress)\n    --On replace la caméra sur le joueur\r\n    Camera.attachCameraToMobile(Context.getLeaderId())\r\n    \r\n    local index = toLong(dungeonProgress)\r\n    local lightId = Particle.addParticleSystem(7088003, pos[index][1], pos[index][2], pos[index][3])\r\n    table.insert(teleporter_lights, lightId)\r\n    \r\n    showAll(45, 63, 29, 67, -6, 40, 0) --On affiche la salle TERRE\r\n    \r\n    local targetApsId = 70115001\r\n    invoke(7000, 1, \"addAmbianceParticle\", targetApsId, boss_pos[4][1], boss_pos[4][2] + 15, boss_pos[4][3]) -- Particules de Pétales\r\n    \r\n    local casterApsId = 7034005\r\n    invoke(7000, 1, \"addAmbianceParticle\", casterApsId, boss_pos[4][1], boss_pos[4][2] + 5, boss_pos[4][3]) -- Rayon vert\r\n    invoke(7000, 1, \"addAmbianceParticle\", casterApsId, boss_pos[4][1], boss_pos[4][2] + 10, boss_pos[4][3]) -- Rayon vert\r\n    invoke(7000, 1, \"addAmbianceParticle\", casterApsId, boss_pos[4][1], boss_pos[4][2] + 15, boss_pos[4][3]) -- Rayon vert\r\n    invoke(7000, 1, \"addAmbianceParticle\", casterApsId, boss_pos[4][1], boss_pos[4][2] + 20, boss_pos[4][3]) -- Rayon vert\r\n    \r\n    invoke(7000, 1, \"endCine\")\nend\n\n-- Salle 3 - Terre - Le joueur marche sur le trigger\n-- \nfunction event_2081_16555()\n    \nend\n\n-- Salle 3 - Terre - Début du combat\n-- \nfunction event_2081_16547()\n    clearAmbianceParticles()\nend\n\n-- Salle 3 - Terre - Victoire des joueurs\n-- \nfunction event_2081_16745()\n    \nend\n\n-- Salle 3 - Terre - Fin du combat (Victoire)\n-- \nfunction event_2081_16540()\n    local x = boss_pos[4][1]\r\n    local y = boss_pos[4][2]\r\n    local z = boss_pos[4][3]\r\n    \r\n    --On prépare le mobile du boss\r\n    if not Mobile.isMobile(bossMobileId) then\r\n    \tActor.createActor(bossMobileId, 180103926, x, y, z)\r\n    \tMobile.setMobileVisible(bossMobileId, false)\r\n    \tMobile.setMobileDirection(bossMobileId, 3)\r\n    end\r\n    \r\n    --On démarre la ciné et on place la caméra au centre et on ajuste le zoom\r\n    startCine(0.7)\r\n    Mobile.setMobileVisible(bossMobileId, true)\r\n    invoke(500, 1, \"Camera.scrollTo\", x, y + 5, z)\r\n    \r\n    --On affiche les bulles de texte\r\n    invoke(1000, 1, \"bubble\", bossMobileId, \"quest.huppermage.dungeon.03.01\")\r\n    invoke(4000, 1, \"Mobile.setMobileAnimation\", bossMobileId, \"AnimSort-01\")\r\n    invoke(5000, 1, \"bubble\", bossMobileId, \"quest.huppermage.dungeon.03.02\")\r\n    invoke(11000, 1, \"Mobile.setMobileAnimation\", bossMobileId, \"AnimSort-02\")\r\n    invoke(12000, 1, \"bubble\", bossMobileId, \"quest.huppermage.dungeon.03.03\")\r\n    \r\n    invoke(15000, 1, \"hideAll\", -63, -45, -64, -26, -6, 40, 0) --On masque la salle FEU\r\n    \r\n    --On déplace le Boss\r\n    invoke(17000, 1, \"Mobile.setMobilePosition\", bossMobileId, boss_pos[5][1], boss_pos[5][2], boss_pos[5][3])\nend\n\n-- Salle 3 - Terre - TP dans la salle 4\n-- \nfunction event_2081_16541(dungeonProgress)\n    local casterApsId = 7000090\r\n    local particleId = Particle.addParticleSystemToTarget(casterApsId, bossMobileId)  -- Particules de darkness\r\n    table.insert(ambiance_particles, particleId)\r\n    \r\n    local index = toLong(dungeonProgress)\r\n    local lightId = Particle.addParticleSystem(7088003, pos[index][1], pos[index][2], pos[index][3])\r\n    table.insert(teleporter_lights, lightId)\r\n    \r\n    --On replace la caméra sur le joueur\r\n    Camera.attachCameraToMobile(Context.getLeaderId())\r\n    \r\n    showAll(-63, -45, -64, -26, -6, 40, 0) --On affiche la salle FEU\r\n    \r\n    local targetApsId = 7034006\r\n    \r\n    invoke(7000, 1, \"addAmbianceParticle\", targetApsId, boss_pos[5][1], boss_pos[5][2] + 15, boss_pos[5][3]) -- Particules de Feu\r\n    invoke(7000, 1, \"endCine\")\nend\n\n-- Salle 4 - Feu - Le joueur marche sur le trigger\n-- \nfunction event_2081_16542(mobOne, mobTwo, mobThree, mobFour, mobFive, mobSix, mobSeven)\n    function setUsergroupVisibility(visible)\r\n    \tlocal mobs = {toLong(mobOne), toLong(mobTwo), toLong(mobThree), toLong(mobFour), toLong(mobFive), toLong(mobSix), toLong(mobSeven)}\r\n    \t\r\n    \tfor key,value in pairs(mobs) do\r\n    \t\tMobile.setMobileVisible(value, visible)\r\n    \tend\r\n    end\r\n    \r\n    function usergroupCine()\r\n    \tinvoke(500, 1, \"Mobile.setMobileAnimation\", bossMobileId, \"AnimSort-03\")\r\n    \t\r\n    \tinvoke(1700, 1, \"Particle.addParticleSystemToTarget\", 4101370, mobTwo)\r\n    \tinvoke(1700, 1, \"Particle.addParticleSystemToTarget\", 4101370, mobThree)\r\n    \tinvoke(1700, 1, \"Particle.addParticleSystemToTarget\", 4101370, mobFour)\r\n    \tinvoke(1700, 1, \"Particle.addParticleSystemToTarget\", 4101370, mobFive)\r\n    \tinvoke(1700, 1, \"Particle.addParticleSystemToTarget\", 4101370, mobSix)\r\n    \tinvoke(1700, 1, \"Particle.addParticleSystemToTarget\", 4101370, mobSeven)\r\n    \t\r\n    \tinvoke(1900, 1, \"setUsergroupVisibility\", true)\r\n    \tinvoke(2000, 1, \"Mobile.setMobileVisible\", bossMobileId, false)\r\n    \r\n    \tinvoke(2000, 1, \"Camera.attachCameraToMobile\", Context.getLeaderId())\r\n    \tinvoke(2000, 1, \"endCine\")\r\n    end\r\n    \r\n    local x = boss_pos[5][1]\r\n    local y = boss_pos[5][2]\r\n    local z = boss_pos[5][3]\r\n    \r\n    --On prépare le mobile du boss\r\n    if not Mobile.isMobile(bossMobileId) then\r\n    \tActor.createActor(bossMobileId, 180103926, x, y, z)\r\n    \tMobile.setMobileVisible(bossMobileId, false)\r\n    \tMobile.setMobileDirection(bossMobileId, 3)\r\n    end\r\n    \r\n    --On démarre la ciné et on place la caméra au centre et on ajuste le zoom\r\n    startCine(0.7)\r\n    setUsergroupVisibility(false)\r\n    Camera.scrollTo(x, y, z)\r\n    \r\n    invoke(1000, 1, \"Camera.attachCameraToMobile\", bossMobileId)\r\n    invoke(1500, 1, \"Mobile.moveMobile\", bossMobileId, -53, -52, 0, \"usergroupCine\")\nend\n\n-- Salle 4 - Feu - Début du combat\n-- \nfunction event_2081_16548()\n    clearAmbianceParticles()\nend\n\n-- Salle 4 - Feu - Victoire des joueurs\n-- \nfunction event_2081_16746()\n    \nend\n\n-- Salle 4 - Feu - Fin du combat (Victoire)\n-- \nfunction event_2081_16543()\n    local x = boss_pos[5][1]\r\n    local y = boss_pos[5][2]\r\n    local z = boss_pos[5][3]\r\n    \r\n    --On prépare le mobile du boss\r\n    if not Mobile.isMobile(bossMobileId) then\r\n    \tActor.createActor(bossMobileId, 180103926, x, y, z)\r\n    \tMobile.setMobileVisible(bossMobileId, false)\r\n    \tMobile.setMobileDirection(bossMobileId, 3)\r\n    end\r\n    \r\n    --On démarre la ciné et on place la caméra au centre et on ajuste le zoom\r\n    startCine(0.7)\r\n    Mobile.setMobileVisible(bossMobileId, true)\r\n    invoke(500, 1, \"Camera.scrollTo\", x, y + 5, z)\r\n    \r\n    --On joue l'apparition du Boss avec la particule qui va bien\r\n    invoke(500, 1, \"Mobile.setMobileVisible\", bossMobileId, false)\r\n    invoke(500, 1, \"Mobile.setMobilePosition\", bossMobileId, x, y, z)\r\n    invoke(500, 1, \"Mobile.setMobileAnimation\", bossMobileId, \"AnimComp-Agenouillee\")\r\n    invoke(500, 1, \"Mobile.setMobileVisible\", bossMobileId, true)\r\n    \r\n    --On affiche les bulles de texte\r\n    invoke(2000, 1, \"bubble\", bossMobileId, \"quest.huppermage.dungeon.04.01\")\r\n    invoke(7000, 1, \"bubble\", bossMobileId, \"quest.huppermage.dungeon.04.02\")\r\n    invoke(14000, 1, \"bubble\", bossMobileId, \"quest.huppermage.dungeon.04.03\")\r\n    invoke(19000, 1, \"bubble\", bossMobileId, \"\") --Pour fermer la bulle\r\n    \r\n    --On joue la disparition du Boss avec la particule qui va bien\r\n    invoke(19000, 1, \"Mobile.setMobileAnimation\", bossMobileId, \"AnimComp-Fuite\")\r\n    invoke(19000, 1, \"Particle.addParticleSystemToTarget\", 4101370, bossMobileId)\r\n    invoke(20500, 1, \"Actor.deleteActor\", bossMobileId)\r\n    \r\n    --On replace la caméra sur le joueur\r\n    invoke(21000, 1, \"Camera.attachCameraToMobile\", Context.getLeaderId())\r\n    invoke(21000, 1, \"endCine\")\nend\n\n-- Boss - Victoire - Push visible achievement méta 2797\n-- \nfunction event_2081_16552()\n    \nend\n\n-- Synchro - Repush des APS si le joueur utilise un TP ou arrive dans l'instance\n-- \nfunction event_2081_16747(dungeonProgress)\n    local progress = toLong(dungeonProgress)\r\n    \r\n    if (progress >= 1) then\r\n    \tfor index=1, progress, 1 do\r\n    \t\tlocal lightId = Particle.addParticleSystem(7088003, pos[index][1], pos[index][2], pos[index][3])\r\n    \t\ttable.insert(teleporter_lights, lightId)\r\n    \tend\r\n    end\nend\n\n","functions":["addAmbianceParticle","clearAmbianceParticles","hideAll","showAll","startCine","endCine","bubble","event_2081_16535","event_2081_16531","event_2081_16532","event_2081_16534","event_2081_16553","event_2081_16545","event_2081_16743","event_2081_16537","event_2081_16536","event_2081_16554","event_2081_16546","event_2081_16744","event_2081_16538","event_2081_16539","event_2081_16555","event_2081_16547","event_2081_16745","event_2081_16540","event_2081_16541","event_2081_16542","setUsergroupVisibility","usergroupCine","event_2081_16548","event_2081_16746","event_2081_16543","event_2081_16552","event_2081_16747"],"quest_calls":[],"dialogue_calls":[]},"scenario/2082.lua":{"source":"function startCine(cineZoomFactor)\r\n\tzoomFactor = Camera.getZoomFactor()\r\n\tUI.manageFrame(\"World\", false)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tUI.setShortcutEnabled(false)\r\n\tCamera.setZoomFactor(cineZoomFactor)\r\nend\r\n\r\nfunction endCine()\r\n\tCamera.attachCameraToMobile(playerId)\r\n\tUI.displayWideScreenBand(false)\r\n\tCamera.setUserZoomLocked(false)\r\n\tUI.setUIVisible(true)\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.hideButton()\r\n\tUI.setShortcutEnabled(true)\r\n\t\r\n\tif (zoomFactor ~= nil and zoomFactor > 0) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\nend\r\n\r\nfunction bubble(mob,text)\r\n\tBubbleText.closeBubbleAttachedTo(mob)\r\n\tBubbleText.showText(mob, text, 0, 40, false)\r\nend\r\n\r\nfunction mobileVisible(mobId, booleen)\r\n\tMobile.setMobileVisible(mobId, booleen)\r\nend\n\n-- [INIT] Initialisation des variables\n-- \nfunction event_2082_16583()\n    \nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_2082_16559()\n    \nend\n\n-- [EVENT] PositionTrigger - Ciné + Timer + Désactivation PositionTrigger\n-- \nfunction event_2082_16561(mobOne, mobTwo, mobThree, mobFour, mobFive)\n    function loopMoveMobOne(mobId, msPerStop, msPerCell)\r\n    \tMobile.setMobileMovementStyle(mobId, \"WALK\", \"WALK\", false)\r\n    \tMobile.setMobileDirection(mobId, 5)\r\n    \tMobile.setMobileVisible(mobId, true)\r\n    \tinvoke(1*msPerStop, 1, \"Mobile.moveMobile\", mobId, 6, -12, 0)\r\n    \tinvoke(1*msPerStop+2*msPerCell, 1, \"Mobile.setMobileDirection\", mobId, 3)\r\n    \tinvoke(1*msPerStop+2*msPerCell, 1, \"Mobile.setMobileAnimation\", mobId, \"AnimEmote-Chercher\")\r\n    \tinvoke(2*msPerStop+2*msPerCell, 1, \"Mobile.moveMobile\", mobId, 6, -9, 0)\r\n    \tinvoke(2*msPerStop+5*msPerCell, 1, \"Mobile.setMobileDirection\", mobId, 1)\r\n    \tinvoke(2*msPerStop+5*msPerCell, 1, \"Mobile.setMobileAnimation\", mobId, \"AnimEmote-Chercher\")\r\n    \tinvoke(3*msPerStop+5*msPerCell, 1, \"Mobile.moveMobile\", mobId, 9, -9, 0)\r\n    \tinvoke(3*msPerStop+8*msPerCell, 1, \"Mobile.setMobileDirection\", mobId, 7)\r\n    \tinvoke(4*msPerStop+8*msPerCell, 1, \"Mobile.moveMobile\", mobId, 9, -12, 0)\r\n    \tinvoke(4*msPerStop+11*msPerCell, 1, \"Mobile.setMobileDirection\", mobId, 5)\r\n    \tinvoke(5*msPerStop+11*msPerCell, 1, \"Mobile.moveMobile\", mobId, 8, -12, 0)\r\n    end\r\n    \r\n    function loopMoveMobTwo(mobId, msPerStop, msPerCell)\r\n    \tMobile.setMobileMovementStyle(mobId, \"WALK\", \"WALK\", false)\r\n    \tMobile.setMobileDirection(mobId, 1)\r\n    \tMobile.setMobileVisible(mobId, true)\r\n    \tMobile.setMobileAnimation(mobId, \"AnimEmote-Chercher\")\r\n    \tinvoke(1*msPerStop, 1, \"Mobile.moveMobile\", mobId, 9, -8, 0)\r\n    \tinvoke(1*msPerStop+2*msPerCell, 1, \"Mobile.setMobileDirection\", mobId, 3)\r\n    \tinvoke(1*msPerStop+2*msPerCell, 1, \"Mobile.setMobileAnimation\", mobId, \"AnimEmote-Chercher\")\r\n    \tinvoke(2*msPerStop+2*msPerCell, 1, \"Mobile.moveMobile\", mobId, 9, -5, 0)\r\n    \tinvoke(2*msPerStop+5*msPerCell, 1, \"Mobile.setMobileDirection\", mobId, 5)\r\n    \tinvoke(3*msPerStop+5*msPerCell, 1, \"Mobile.moveMobile\", mobId, 6, -5, 0)\r\n    \tinvoke(3*msPerStop+8*msPerCell, 1, \"Mobile.setMobileDirection\", mobId, 7)\r\n    \tinvoke(4*msPerStop+8*msPerCell, 1, \"Mobile.moveMobile\", mobId, 6, -8, 0)\r\n    \tinvoke(4*msPerStop+11*msPerCell, 1, \"Mobile.setMobileDirection\", mobId, 1)\r\n    \tinvoke(4*msPerStop+11*msPerCell, 1, \"Mobile.setMobileAnimation\", mobId, \"AnimEmote-Chercher\")\r\n    \tinvoke(5*msPerStop+11*msPerCell, 1, \"Mobile.moveMobile\", mobId, 7, -8, 0)\r\n    end\r\n    \r\n    function loopMoveMobThree(mobId, msPerStop, msPerCell)\r\n    \tMobile.setMobileMovementStyle(mobId, \"WALK\", \"WALK\", false)\r\n    \tMobile.setMobileDirection(mobId, 7)\r\n    \tMobile.setMobileVisible(mobId, true)\r\n    \tinvoke(1*msPerStop, 1, \"Mobile.moveMobile\", mobId, 5, -12, 0)\r\n    \tinvoke(1*msPerStop+2*msPerCell, 1, \"Mobile.setMobileDirection\", mobId, 5)\r\n    \tinvoke(2*msPerStop+2*msPerCell, 1, \"Mobile.moveMobile\", mobId, 2, -12, 0)\r\n    \tinvoke(2*msPerStop+5*msPerCell, 1, \"Mobile.setMobileDirection\", mobId, 3)\r\n    \tinvoke(2*msPerStop+5*msPerCell, 1, \"Mobile.setMobileAnimation\", mobId, \"AnimEmote-Chercher\")\r\n    \tinvoke(3*msPerStop+5*msPerCell, 1, \"Mobile.moveMobile\", mobId, 2, -7, 0)\r\n    \tinvoke(3*msPerStop+10*msPerCell, 1, \"Mobile.setMobileDirection\", mobId, 1)\r\n    \tinvoke(3*msPerStop+10*msPerCell, 1, \"Mobile.setMobileAnimation\", mobId, \"AnimEmote-Chercher\")\r\n    \tinvoke(4*msPerStop+10*msPerCell, 1, \"Mobile.moveMobile\", mobId, 5, -7, 0)\r\n    \tinvoke(4*msPerStop+13*msPerCell, 1, \"Mobile.setMobileDirection\", mobId, 7)\r\n    \tinvoke(5*msPerStop+13*msPerCell, 1, \"Mobile.moveMobile\", mobId, 5, -10, 0)\r\n    end\r\n    \r\n    function loopMoveMobFour(mobId, msPerStop, msPerCell)\r\n    \tMobile.setMobileMovementStyle(mobId, \"WALK\", \"WALK\", false)\r\n    \tMobile.setMobileDirection(mobId, 3)\r\n    \tMobile.setMobileVisible(mobId, true)\r\n    \tMobile.setMobileAnimation(mobId, \"AnimEmote-Chercher\")\r\n    \tinvoke(1*msPerStop, 1, \"Mobile.moveMobile\", mobId, -2, -7, 0)\r\n    \tinvoke(1*msPerStop+4*msPerCell, 1, \"Mobile.setMobileDirection\", mobId, 1)\r\n    \tinvoke(1*msPerStop+4*msPerCell, 1, \"Mobile.setMobileAnimation\", mobId, \"AnimEmote-Chercher\")\r\n    \tinvoke(2*msPerStop+4*msPerCell, 1, \"Mobile.moveMobile\", mobId, 1, -7, 0)\r\n    \tinvoke(2*msPerStop+5*msPerCell, 1, \"Mobile.setMobileDirection\", mobId, 7)\r\n    \tinvoke(3*msPerStop+5*msPerCell, 1, \"Mobile.moveMobile\", mobId, 1, -12, 0)\r\n    \tinvoke(3*msPerStop+10*msPerCell, 1, \"Mobile.setMobileDirection\", mobId, 5)\r\n    \tinvoke(4*msPerStop+10*msPerCell, 1, \"Mobile.moveMobile\", mobId, -2, -12, 0)\r\n    \tinvoke(4*msPerStop+11*msPerCell, 1, \"Mobile.setMobileDirection\", mobId, 3)\r\n    \tinvoke(4*msPerStop+11*msPerCell, 1, \"Mobile.setMobileAnimation\", mobId, \"AnimEmote-Chercher\")\r\n    \tinvoke(5*msPerStop+11*msPerCell, 1, \"Mobile.moveMobile\", mobId, -2, -11, 0)\r\n    end\r\n    \r\n    function loopMoveMobFive(mobId, msPerStop, msPerCell)\r\n    \tMobile.setMobileMovementStyle(mobId, \"WALK\", \"WALK\", false)\r\n    \tMobile.setMobileDirection(mobId, 3)\r\n    \tMobile.setMobileVisible(mobId, true)\r\n    \tMobile.setMobileAnimation(mobId, \"AnimEmote-Chercher\")\r\n    \tinvoke(1*msPerStop, 1, \"Mobile.moveMobile\", mobId, 7, -2, 0)\r\n    \tinvoke(1*msPerStop+1*msPerCell, 1, \"Mobile.setMobileDirection\", mobId, 5)\r\n    \tinvoke(2*msPerStop+1*msPerCell, 1, \"Mobile.moveMobile\", mobId, 1, -2, 0)\r\n    \tinvoke(2*msPerStop+7*msPerCell, 1, \"Mobile.setMobileDirection\", mobId, 7)\r\n    \tinvoke(3*msPerStop+7*msPerCell, 1, \"Mobile.moveMobile\", mobId, 1, -6, 0)\r\n    \tinvoke(3*msPerStop+11*msPerCell, 1, \"Mobile.setMobileDirection\", mobId, 1)\r\n    \tinvoke(3*msPerStop+11*msPerCell, 1, \"Mobile.setMobileAnimation\", mobId, \"AnimEmote-Chercher\")\r\n    \tinvoke(4*msPerStop+11*msPerCell, 1, \"Mobile.moveMobile\", mobId, 4, -6, 0)\r\n    \tinvoke(4*msPerStop+14*msPerCell, 1, \"Mobile.setMobileDirection\", mobId, 3)\r\n    \tinvoke(4*msPerStop+14*msPerCell, 1, \"Mobile.setMobileAnimation\", mobId, \"AnimEmote-Chercher\")\r\n    \tinvoke(5*msPerStop+14*msPerCell, 1, \"Mobile.moveMobile\", mobId, 4, -4, 0)\r\n    \tinvoke(5*msPerStop+16*msPerCell, 1, \"Mobile.setMobileDirection\", mobId, 1)\r\n    \tinvoke(5*msPerStop+16*msPerCell, 1, \"Mobile.setMobileAnimation\", mobId, \"AnimEmote-Chercher\")\r\n    \tinvoke(6*msPerStop+16*msPerCell, 1, \"Mobile.moveMobile\", mobId, 7, -4, 0)\r\n    \tinvoke(6*msPerStop+19*msPerCell, 1, \"Mobile.setMobileDirection\", mobId, 3)\r\n    \tinvoke(6*msPerStop+19*msPerCell, 1, \"Mobile.setMobileAnimation\", mobId, \"AnimEmote-Chercher\")\r\n    \tinvoke(7*msPerStop+19*msPerCell, 1, \"Mobile.moveMobile\", mobId, 7, -3, 0)\r\n    end\r\n    \r\n    \tplayerId = Context.getLeaderId()\r\n    \t\r\n    startCine(1.2)\r\n    Camera.zoomOn(1.2, 15000, 4, -7, 0)\r\n    loopMoveMobOne(mobOne, 2520, 700)\r\n    loopMoveMobTwo(mobTwo, 2520, 700)\r\n    loopMoveMobThree(mobThree, 2240, 700)\r\n    loopMoveMobFour(mobFour, 2520, 700)\r\n    loopMoveMobFive(mobFive, 1000, 700)\r\n    invoke(18000, 1, \"bubble\", playerId, \"quest.huppermage.infiltration.01\")\r\n    invoke(18000, 1, \"Camera.attachCameraToMobile\", playerId)\r\n    invoke(18000, 1, \"Camera.setZoomFactor\", 2.0)\r\n    invoke(22000, 1, \"endCine\")\nend\n\n-- [EVENT] Timer - Lancement combat\n-- \nfunction event_2082_16587()\n    \nend\n\n-- [EVENT] Combat lancé - Glyphes + Carac + Tuto\n-- \nfunction event_2082_16562()\n    UI.loadTutorialDialog(\"null\",\"quest.saharach.rules.title2\",\"quest.saharach.rules.desc2\")\nend\n\n-- [EVENT] Défaite - Init variable défaite\n-- \nfunction event_2082_16584()\n    \nend\n\n-- [EVENT] Défaite (client) - TP joueur + réactivation PositionTrigger\n-- \nfunction event_2082_16586()\n    \nend\n\n-- [EVENT] Victoire - Activation TP Sortie\n-- \nfunction event_2082_16563()\n    \nend\n\n","functions":["startCine","endCine","bubble","mobileVisible","event_2082_16583","event_2082_16559","event_2082_16561","loopMoveMobOne","loopMoveMobTwo","loopMoveMobThree","loopMoveMobFour","loopMoveMobFive","event_2082_16587","event_2082_16562","event_2082_16584","event_2082_16586","event_2082_16563"],"quest_calls":[],"dialogue_calls":[]},"scenario/2083.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\n\n-- [INITIALISATION] Serveur\n-- \nfunction event_2083_16588()\n    \nend\n\n-- [TIMER] Erruption du geyser\n-- \nfunction event_2083_16730()\n    invoke(100, 1, \"Particle.addParticleSystem\", 71033004, 6, -141, -33, 0)\r\n    import(4001012201001)\r\n    Sound.playLocalSound(11, 4001012201001, 40, 6, -141, -33)\nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_2083_16589(PorteA, PorteB, PorteC, PorteBoss)\n    local PorteA = toLong(PorteA)\r\n    local PorteB = toLong(PorteB)\r\n    local PorteC = toLong(PorteC)\r\n    local PorteBoss = toLong(PorteBoss)\r\n    \r\n    if PorteA == 1 then\r\n    \tWorld.setPictoAlpha(-23, -15, 9, 0, 1000)\r\n    end\r\n    \r\n    if PorteB == 1 then\r\n    \tWorld.setPictoAlpha(-23, -51, 9, 0, 1000)\r\n    end\r\n    \r\n    if PorteC == 1 then\r\n    \tWorld.setPictoAlpha(-26, -129, -15, 0, 1000)\r\n    end\r\n    \r\n    if PorteBoss == 1 then\r\n    \tWorld.setPictoAlpha(37, -8, -1, 0, 1000)\r\n    \tWorld.setPictoAlpha(56, 5, -1, 0, 1000)\r\n    end\nend\n\n-- [SALLE 01] Lancement du combat - Zones & états mécaniques\n-- \nfunction event_2083_16722()\n    \nend\n\n-- [SALLE 01] Victoire - On déverouille la porte\n-- \nfunction event_2083_16590()\n    World.setPictoAlpha(-23, -15, 9, 0, 1000)\r\n    Effect.createCameraShakeEffect(200,1500, 200, 1)\nend\n\n-- [SALLE 02] Lancement du combat - Zones & états mécaniques\n-- \nfunction event_2083_16721()\n    \nend\n\n-- [SALLE 02] Victoire - On déverouille la porte\n-- \nfunction event_2083_16599()\n    World.setPictoAlpha(-23, -51, 9, 0, 1000)\r\n    Effect.createCameraShakeEffect(200,1500, 200, 1)\nend\n\n-- [SALLE 03] Lancement du combat - Zones & états mécaniques\n-- \nfunction event_2083_16632()\n    \nend\n\n-- [SALLE 03] Victoire - On déverouille la porte\n-- \nfunction event_2083_16601()\n    World.setPictoAlpha(-26, -129, -15, 0, 1000)\r\n    World.setPictoAlpha(-26, -129, -16, 0, 1000)\r\n    Effect.createCameraShakeEffect(200, 1500, 200, 1)\nend\n\n-- [SALLE 03] Fin de combat - Validation OBJ 5672 ACH 2812\n-- \nfunction event_2083_22492()\n    \nend\n\n-- [SALLE 04] Lancement du combat - Zones & états mécaniques\n-- \nfunction event_2083_16633()\n    \nend\n\n-- [SALLE 04] Fin de combat - Validation OBJ 5671 ACH 2811\n-- \nfunction event_2083_22491()\n    \nend\n\n-- [SALLE 03] Fin de combat - Validation OBJ 5677 ACH 2812\n-- \nfunction event_2083_22493()\n    \nend\n\n-- [SALLE 04] Le joueur active la Coupe - Validation OBJ 5576 ACH 2768\n-- \nfunction event_2083_16594()\n    \nend\n\n-- [SALLE 04] Le joueur active la Coupe - Cinématique\n-- \nfunction event_2083_16595()\n    local playerId = Context.getLeaderId()\r\n    \r\n    local jenry = createActor(117903815, -28, -155, -19, 4, 5, 6)\r\n    local khan = createActor(112903915, -22, -156, -30, 4, 3, 6)\r\n    local youngKhan = createActor(112903893, -22, -152, -30, 4, 1, 6)\r\n    \r\n    Mobile.setMobileVisible(jenry, false)\r\n    Mobile.setMobileVisible(khan, false)\r\n    Mobile.setMobileVisible(youngKhan, false)\r\n    Mobile.hideOtherPlayerMobile(true)\r\n    \r\n    function customSkip()\r\n        Mobile.hideOtherPlayerMobile(false)\r\n        skipCinematic(16595)\r\n    end\r\n    \r\n    startCinematicContext(1.5, jenry)\r\n    \r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"customSkip\")\r\n    \r\n    invoke_custom(01000, 1, \"Mobile.moveMobile\", playerId, -20, -152, -30, \"Mobile.setMobileDirection\", playerId, 7)\r\n    invoke_custom(01000, 1, \"Mobile.setMobileVisible\", jenry, true)\r\n    invoke_custom(01000, 1, \"Mobile.moveMobile\", jenry, -19, -154, -30, \"Mobile.setMobileDirection\", Jenry, 7)\r\n    \r\n    -- \"Très bien ! Cette fois-ci c'est la bonne !\"\r\n    invoke_custom(05000, 1, \"bubble\", jenry, \"quest.nationch3.stadeintro.jenry.00\")\r\n    invoke_custom(05000, 1, \"Mobile.setMobileAnimation\", jenry, \"AnimDial-OK\")\r\n    invoke_custom(09500, 1, \"clearBubbles\", jenry)\r\n    \r\n    -- \"Je vois d'ici la bille d'orichalque qui brille...\"\r\n    invoke_custom(10000, 1, \"bubble\", jenry, \"quest.nationch3.stadeintro.jenry.01\")\r\n    invoke_custom(10000, 1, \"Mobile.setMobileAnimation\", jenry, \"AnimDial-Discute\")\r\n    invoke_custom(14000, 1, \"clearBubbles\", jenry)\r\n    \r\n    -- KHAN ARRIVE\r\n    invoke_custom(14000, 1, \"Mobile.setMobileVisible\", khan, true)\r\n    invoke_custom(14000, 1, \"Mobile.setMobileAnimation\", khan, \"AnimApparition\")\r\n    invoke_custom(14000, 1, \"Particle.addParticleSystem\", 800568, -22, -156, -30, 1)\r\n    invoke_custom(14000, 1, \"Camera.attachCameraToMobile\", khan)\r\n    invoke_custom(14000, 1, \"Effect.createCameraShakeEffect\", 200, 1500, 200, 1)\r\n    \r\n    -- \"Pas si vite, les gamins !!!\"\r\n    invoke_custom(14100, 1, \"bubble\", khan, \"quest.nationch3.stadeintro.khan.00\")\r\n    invoke_custom(16000, 1, \"Mobile.moveMobile\", khan, -22, -152, -30, \"Mobile.setMobileDirection\", Khan, 1)\r\n    invoke_custom(16500, 1, \"clearBubbles\", khan)\r\n    \r\n    -- \"Si vous voulez la coupe, il va falloir la gagner.\" \r\n    invoke_custom(17000, 1, \"bubble\", khan, \"quest.nationch3.stadeintro.khan.01\")\r\n    invoke_custom(17000, 1, \"Mobile.setMobileAnimation\", khan, \"AnimDial\")\r\n    invoke_custom(21000, 1, \"clearBubbles\", khan)\r\n    \r\n    -- \"Vous allez devoir m'affronter...\"\r\n    invoke_custom(21500, 1, \"bubble\", khan, \"quest.nationch3.stadeintro.khan.02\")\r\n    invoke_custom(17000, 1, \"Mobile.setMobileAnimation\", khan, \"AnimDial\")\r\n    invoke_custom(25500, 1, \"clearBubbles\", khan)\r\n    \r\n    -- KHAN TRANSFORMATION\r\n    invoke_custom(26000, 1, \"Effect.createCameraShakeEffect\", 200, 1500, 200, 1)\r\n    invoke_custom(26000, 1, \"Mobile.setMobileAnimation\", khan, \"AnimTransition\")\r\n    invoke_custom(26000, 1, \"Mobile.setMobileVisible\", youngKhan, true)\r\n    invoke_custom(26000, 1, \"Mobile.setMobileAnimation\", youngKhan, \"AnimApparition\")\r\n    \r\n    -- \"... dans un match de Boufbowl !!!\"\r\n    invoke_custom(26100, 1, \"bubble\", youngKhan, \"quest.nationch3.stadeintro.khan.03\")\r\n    invoke_custom(26500, 1, \"Particle.addParticleSystem\", 800568, -22, -152, -30, 1)\r\n    invoke_custom(29500, 1, \"clearBubbles\", youngKhan)\r\n    \r\n    -- \"Tous les coups sont permis.\"\r\n    invoke_custom(30000, 1, \"bubble\", youngKhan, \"quest.nationch3.stadeintro.khan.04\")\r\n    invoke_custom(30000, 1, \"Mobile.setMobileAnimation\", youngKhan, \"AnimSort-Ramassage\")\r\n    invoke_custom(33000, 1, \"clearBubbles\", youngKhan)\r\n    \r\n    -- \"Je ne vous ferai pas de cadeau !\"\r\n    invoke_custom(33500, 1, \"bubble\", youngKhan, \"quest.nationch3.stadeintro.khan.05\")\r\n    invoke_custom(33500, 1, \"Mobile.setMobileAnimation\", youngKhan, \"AnimSort-Lancer\")\r\n    invoke_custom(36500, 1, \"clearBubbles\", youngKhan)\r\n    \r\n    invoke_custom(36500, 1, \"Mobile.moveMobile\", youngKhan, -20, -144, -30, \"Mobile.setMobileDirection\", youngKhan, 1)\r\n    \r\n    invoke_custom(39000, 1, \"customSkip\")\nend\n\n-- [SALLE 04] Fin Cinématique - APPARITION Khan pour fight\n-- \nfunction event_2083_16606()\n    Mobile.hideOtherPlayerMobile(false)\r\n    skipCinematic()\nend\n\n-- [SALLE 04] Début du combat - Sauvegarde de l'ID du combat\n-- \nfunction event_2083_19886()\n    \nend\n\n-- [SALLE 04] Victoire - Cinématique + On déverouille le passage de sortie\n-- \nfunction event_2083_16596()\n    local playerId = Context.getLeaderId()\r\n    local Jenrybis = createActor(117903815, -19, -154, -30, 4, 5, 6)\r\n    local Khanbis = createActor(112903915, -22, -156, -30, 4, 3, 6)\r\n    Mobile.setMobileVisible(Khanbis, false)\r\n    \r\n    startCinematicContext(1.5)\r\n    Camera.setWorldTarget(-19, -153, -30)\r\n    \r\n    World.setPictoAlpha(-7, -157, -17, 0, 1000)\r\n    Effect.createCameraShakeEffect(200,1500, 200, 1)\r\n    \r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\")\r\n    \r\n    --RETOUR DE KHAN\r\n    invoke_custom(1000, 1, \"Mobile.setMobileVisible\", Khanbis, true)\r\n    invoke_custom(1000, 1, \"Mobile.setMobileAnimation\", Khanbis, \"AnimApparition\")\r\n    invoke_custom(1000, 1, \"Camera.attachCameraToMobile\", Khanbis)\r\n    invoke_custom(1000, 1, \"Particle.addParticleSystem\", 800568, -22, -156, -30, 1)\r\n    invoke_custom(1000, 1, \"Effect.createCameraShakeEffect\", 200,1500, 200, 1)\r\n    invoke_custom(3000, 1, \"Mobile.moveMobile\", Khanbis, -22, -152, -30, \"Mobile.setMobileDirection\", Khanbis, 1)\r\n    invoke_custom(4000, 1, \"bubble\", Khanbis, \"quest.nationch3.stadeend.khan.01\")\r\n    invoke_custom(4000, 1, \"Mobile.setMobileDirection\", Jenrybis,5)\r\n    invoke_custom(7000, 1, \"bubble\", Khanbis, \"quest.nationch3.stadeend.khan.02\")\r\n    \r\n    --DEPART DE KHAN\r\n    invoke_custom(10000, 1,\"Mobile.setMobileAnimation\", Khanbis, \"AnimDisparition\")\r\n    invoke_custom(10000, 1,\"Effect.createCameraShakeEffect\", 200,1500, 200, 1)\r\n    invoke_custom(12000, 1, \"Actor.deleteActor\", Khanbis)\r\n    invoke_custom(12000, 1, \"Camera.attachCameraToMobile\", Jenrybis)\r\n    invoke_custom(12000, 1, \"Mobile.setMobileDirection\", Jenrybis, 3)\r\n    invoke_custom(12000, 1, \"bubble\", Jenrybis, \"quest.nationch3.stadeend.jenry.01\")\r\n    invoke_custom(12000, 1, \"Mobile.setMobileAnimation\", Jenrybis, \"AnimDial-OK\")\r\n    invoke_custom(15000, 1, \"bubble\", Jenrybis, \"quest.nationch3.stadeend.jenry.02\")\r\n    invoke_custom(15000, 1, \"Mobile.setMobileAnimation\", Jenrybis, \"AnimDial-Discute\")\r\n    invoke_custom(19000, 1, \"bubble\", Jenrybis, \"quest.nationch3.stadeend.jenry.03\")\r\n    invoke_custom(20000, 1, \"Mobile.moveMobile\", Jenrybis, -4, -154, -30, \"Mobile.setMobileDirection\", Khanbis, 1)\r\n    \r\n    invoke_custom(24000, 1, \"skipCinematic\")\nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_2083_16588","event_2083_16730","event_2083_16589","event_2083_16722","event_2083_16590","event_2083_16721","event_2083_16599","event_2083_16632","event_2083_16601","event_2083_22492","event_2083_16633","event_2083_22491","event_2083_22493","event_2083_16594","event_2083_16595","customSkip","event_2083_16606","event_2083_19886","event_2083_16596"],"quest_calls":[],"dialogue_calls":[]},"scenario/2084.lua":{"source":"\n\n-- [EVENT] Initialisation\n-- \nfunction event_2084_16609()\n    \nend\n\n-- [ACTION] Lancement du combat associé\n-- \nfunction event_2084_16610()\n    \nend\n\n-- [ACTION] Fin de combat gagnant\n-- \nfunction event_2084_16611(GroupId)\n    \nend\n\n-- [ACTION] Fin de combat gagnant - fin scenario\n-- \nfunction event_2084_16612(GroupId)\n    \nend\n\n-- [ACTION] Fin de combat perdant\n-- \nfunction event_2084_16613(GroupId, MobA)\n    \nend\n\n","functions":["event_2084_16609","event_2084_16610","event_2084_16611","event_2084_16612","event_2084_16613"],"quest_calls":[],"dialogue_calls":[]},"scenario/2085.lua":{"source":"\n\n-- [EVENT] Initialisation\n-- \nfunction event_2085_16614()\n    \nend\n\n-- [ACTION] Lancement du combat associé\n-- \nfunction event_2085_16615()\n    \nend\n\n-- [ACTION] Fin de combat gagnant\n-- \nfunction event_2085_16616(GroupId)\n    \nend\n\n-- [ACTION] Fin de combat gagnant - fin scenario\n-- \nfunction event_2085_16617(GroupId)\n    \nend\n\n-- [ACTION] Fin de combat perdant\n-- \nfunction event_2085_16618(GroupId, MobA)\n    \nend\n\n","functions":["event_2085_16614","event_2085_16615","event_2085_16616","event_2085_16617","event_2085_16618"],"quest_calls":[],"dialogue_calls":[]},"scenario/2086.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\n\n-- [INIT] Initialisation\n-- \nfunction event_2086_16619(playerId)\n    \nend\n\n-- [TIMER] Erruption du geyser\n-- \nfunction event_2086_16720()\n    invoke(100,1,\"Particle.addParticleSystem\",71033004, 17,-42, -6, 0)\r\n    import(4001012201001)\r\n    Sound.playLocalSound(11, 4001012201001, 40, 16,-43, -6 )\r\nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_2086_16620(playerId, PorteBoss)\n    local column = toLong(PorteBoss) \r\n    \t\r\n    World.setPictoAlpha(3, -28, -8, 0, 1000)\r\n    World.setPictoAlpha(3, -29, -8, 0, 1000)\r\n    World.setPictoAlpha(3, -30, -8, 0, 1000)\r\n    World.setPictoAlpha(3, -31, -8, 0, 1000)\r\n    World.setPictoAlpha(3, -32, -8, 0, 1000)\r\n    World.setPictoAlpha(3, -33, -8, 0, 1000)\r\n    \t\r\n    if column ==1 then\r\n    \tWorld.setPictoAlpha(3, -27, 11, 0, 1000)\r\n    \tWorld.setPictoAlpha(3, -28, -8, 100, 1000)\r\n    \tWorld.setPictoAlpha(3, -29, -8, 100, 1000)\r\n    \tWorld.setPictoAlpha(3, -30, -8, 100, 1000)\r\n    \tWorld.setPictoAlpha(3, -31, -8, 100, 1000)\r\n    \tWorld.setPictoAlpha(3, -32, -8, 100, 1000)\r\n    \tWorld.setPictoAlpha(3, -33, -8, 100, 1000)\t\r\n    end\nend\n\n-- [EVENT] Le joueur passe sur le Trigger Entrée Stade - Validation OBJ 5573 ACH 2766\n-- \nfunction event_2086_16719()\n    \nend\n\n-- [EVENT] Le joueur active la Tombe de Khan - Validation OBJ 5570 ACH 2763\n-- \nfunction event_2086_16714()\n    \nend\n\n-- [EVENT] Le joueur active la Tombe de Khan - Cinématique\n-- \nfunction event_2086_19873(BossGroupId, BossId, BossAddOne, BossAddTwo, BossAddThree, BossAddFour, BossAddFive, BossAddSix, PlayerOne, PlayerTwo, PlayerThree, PlayerFour, PlayerFive, PlayerSix)\n    local playerId = Context.getLeaderId()\r\n    local PlayerOne = toLong(PlayerOne)\r\n    local PlayerTwo = toLong(PlayerTwo)\r\n    local PlayerThree = toLong(PlayerThree)\r\n    local PlayerFour = toLong(PlayerFour)\r\n    local PlayerFive = toLong(PlayerFive)\r\n    local PlayerSix = toLong(PlayerSix)\r\n    \r\n    local JemmyOne = creat