toAlpha(3, -31, -8, 100, 1000)\r\n    World.setPictoAlpha(3, -32, -8, 100, 1000)\r\n    World.setPictoAlpha(3, -33, -8, 100, 1000)\t\r\n    World.setPictoAlpha(3, -28, -7, 100, 1000)\r\n    World.setPictoAlpha(3, -29, -7, 100, 1000)\r\n    World.setPictoAlpha(3, -30, -7, 100, 1000)\r\n    World.setPictoAlpha(3, -31, -7, 100, 1000)\r\n    World.setPictoAlpha(3, -32, -7, 100, 1000)\r\n    World.setPictoAlpha(3, -33, -7, 100, 1000)\t\r\n    World.setPictoAlpha(3, -28, -9, 100, 1000)\r\n    World.setPictoAlpha(3, -29, -9, 100, 1000)\r\n    World.setPictoAlpha(3, -30, -9, 100, 1000)\r\n    World.setPictoAlpha(3, -31, -9, 100, 1000)\r\n    World.setPictoAlpha(3, -32, -9, 100, 1000)\r\n    World.setPictoAlpha(3, -33, -9, 100, 1000)\t\r\n    \t\r\n    Effect.createCameraShakeEffect(200,1500, 200, 1)\nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_2086_16619","event_2086_16720","event_2086_16620","event_2086_16719","event_2086_16714","event_2086_19873","event_2086_16716","event_2086_16622","event_2086_16723","event_2086_16718"],"quest_calls":[],"dialogue_calls":[]},"scenario/2088.lua":{"source":"\n\n-- [EVENT] Initialisation\n-- \nfunction event_2088_16634()\n    \nend\n\n-- [ACTION] Lancement du combat associé\n-- \nfunction event_2088_16635()\n    \nend\n\n-- [COMBAT] Combat - Enregistrement de l'évènement\n-- \nfunction event_2088_16733(fightStarted, FightId)\n    local FightId = toLong(FightId)\r\n    local fightStarted= toLong(fightStarted)\r\n    \r\n    trace(\"==== ID FIGHT ====  \" , FightId)\r\n    trace(\"==== ID STARTED ====  \" , fightStarted)\nend\n\n-- [ACTION] Fin de combat gagnant\n-- \nfunction event_2088_16636(GroupId, PlayerOne, PlayerTwo, PlayerThree, PlayerFour, PlayerFive, PlayerSix)\n    \nend\n\n-- [ACTION] Fin de combat gagnant - fin scenario\n-- \nfunction event_2088_16637(GroupId)\n    \nend\n\n-- [ACTION] Fin de combat perdant\n-- \nfunction event_2088_16638(GroupId, MobA)\n    \nend\n\n","functions":["event_2088_16634","event_2088_16635","event_2088_16733","event_2088_16636","event_2088_16637","event_2088_16638"],"quest_calls":[],"dialogue_calls":[]},"scenario/2089.lua":{"source":"\n\n-- [EVENT] Initialisation\n-- \nfunction event_2089_16639()\n    \nend\n\n-- [ACTION] Lancement du combat associé\n-- \nfunction event_2089_16640()\n    \nend\n\n-- [ACTION] Fin de combat gagnant\n-- \nfunction event_2089_16641(GroupId)\n    \nend\n\n-- [ACTION] Fin de combat gagnant - fin scenario\n-- \nfunction event_2089_16642(GroupId)\n    \nend\n\n-- [ACTION] Fin de combat perdant\n-- \nfunction event_2089_16643(GroupId, MobA)\n    \nend\n\n","functions":["event_2089_16639","event_2089_16640","event_2089_16641","event_2089_16642","event_2089_16643"],"quest_calls":[],"dialogue_calls":[]},"scenario/2090.lua":{"source":"playerId = Context.getLeaderId()\r\n\r\nfunction startCine()\r\n\tzoomFactor = Camera.getZoomFactor()\r\n\tUI.manageFrame(\"World\",false) \t\t\t\t\t\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\t\t\t\t\t\t\t\t\t\t\t\t\r\n\tUI.manageFrame(\"World\",false) \t\t\t\t\t\r\n\tUI.setUIVisible(false)\t\r\n\tUI.displayWideScreenBand(true)\r\nend\r\n\r\nfunction endCine()\r\n\tCamera.attachCameraToMobile(playerId)\r\n\tUI.displayWideScreenBand(false)\r\n\tCamera.setUserZoomLocked(false)\t\t\t\t\t\t\t\t\t\t\t\t\r\n\tUI.setUIVisible(true)\t\r\n\tUI.manageFrame(\"World\",true) \t\t\t\t\r\n\tCamera.setZoomFactor(zoomFactor)\t\r\n\tSound.stopForcedMusic()\r\nend\r\n\r\nfunction MindBubbleStart(mob,text,tDuration)\r\n\tMindBubble=BubbleText.showText(mob, text, 0, 40, false)\r\n\tinvoke(tDuration,1,\"BubbleText.close\",MindBubble)\r\nend\r\n\r\nfunction MindBubbleChef(mob,text,tDuration)\r\n\tMindBubble=BubbleText.showText(mob, text, 0, 80, false)\r\n\tinvoke(tDuration,1,\"BubbleText.close\",MindBubble)\r\nend\r\n\n\n-- [EVENT] Initialisation\n-- \nfunction event_2090_16645(playerId)\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2090_16646(playerId, GirlAA, GirlAB, GirlAC, GirlBA, GirlBB, GirlBC, BoyAA, BoyAB, BoyAC, BoyBA, BoyBB, BoyBC)\n    GirlAA = toLong(GirlAA)\r\n    GirlAB = toLong(GirlAB)\r\n    GirlAC = toLong(GirlAC)\r\n    BoyAA = toLong(BoyAA)\r\n    BoyAB = toLong(BoyAB)\r\n    BoyAC = toLong(BoyAC)\r\n    GirlBA = toLong(GirlBA)\r\n    GirlBB = toLong(GirlBB)\r\n    GirlBC = toLong(GirlBC)\r\n    BoyBA = toLong(BoyBA)\r\n    BoyBB = toLong(BoyBB)\r\n    BoyBC = toLong(BoyBC)\r\n    \r\n    Mobile.setMobileDirection(GirlAA, 1)\r\n    Mobile.setMobileDirection(GirlAB, 1)\r\n    Mobile.setMobileDirection(GirlAC, 1)\r\n    Mobile.setMobileDirection(GirlBA, 1)\r\n    Mobile.setMobileDirection(GirlBB, 1)\r\n    Mobile.setMobileDirection(GirlBC, 1)\r\n    Mobile.setMobileDirection(BoyAA, 1)\r\n    Mobile.setMobileDirection(BoyAB, 1)\r\n    Mobile.setMobileDirection(BoyAC, 1)\r\n    Mobile.setMobileDirection(BoyBA, 1)\r\n    Mobile.setMobileDirection(BoyBB, 1)\r\n    Mobile.setMobileDirection(BoyBC, 1)\r\n    \r\n    -- AnimStatique-Tabouret-Assis\r\n    -- AnimStatique-Banc-Assis\r\n    -- AnimStatique-Assis\r\n    \r\n    Mobile.setMobileAnimation(GirlAA, \"AnimStatique-Assis\")\r\n    Mobile.setMobileAnimation(GirlAB, \"AnimStatique-Assis\")\r\n    Mobile.setMobileAnimation(GirlAC, \"AnimStatique-Assis\")\r\n    Mobile.setMobileAnimation(BoyAA, \"AnimStatique-Assis\")\r\n    Mobile.setMobileAnimation(BoyAB, \"AnimStatique-Assis\")\r\n    Mobile.setMobileAnimation(BoyAC, \"AnimStatique-Assis\")\r\n    Mobile.setMobileAnimation(GirlBA, \"AnimStatique-Assis\")\r\n    Mobile.setMobileAnimation(GirlBB, \"AnimStatique-Assis\")\r\n    Mobile.setMobileAnimation(GirlBC, \"AnimStatique-Assis\")\r\n    Mobile.setMobileAnimation(BoyBA, \"AnimStatique-Assis\")\r\n    Mobile.setMobileAnimation(BoyBB, \"AnimStatique-Assis\")\r\n    Mobile.setMobileAnimation(BoyBC, \"AnimStatique-Assis\")\r\nend\n\n-- [ACTION] Le joueur essaye de rammasser le livre -> dialogue\n-- \nfunction event_2090_16649(GroupId, MobA)\n    \nend\n\n-- [ACTION] Début du Quizz - lancement Quizz série A\n-- \nfunction event_2090_16676(RandA)\n    \nend\n\n-- [ACTION] Début du Quizz - lancement Quizz série B\n-- \nfunction event_2090_16678(RandB)\n    \nend\n\n-- [ACTION] Début du Quizz - lancement Quizz série C\n-- \nfunction event_2090_16688(RandC)\n    \nend\n\n-- [ACTION] Début du Quizz - Timer question A - 1\n-- \nfunction event_2090_16677()\n    \nend\n\n-- [ACTION] Début du Quizz - Timer question A - 2\n-- \nfunction event_2090_16679()\n    \nend\n\n-- [ACTION] Début du Quizz - Timer question A - 3\n-- \nfunction event_2090_16680()\n    \nend\n\n-- [ACTION] Début du Quizz - Timer question A - 4\n-- \nfunction event_2090_16681()\n    \nend\n\n-- [ACTION] Début du Quizz - Timer question A - 5\n-- \nfunction event_2090_16682()\n    \nend\n\n-- [ACTION] Début du Quizz - Timer question B - 1\n-- \nfunction event_2090_16683()\n    \nend\n\n-- [ACTION] Début du Quizz - Timer question B - 2\n-- \nfunction event_2090_16684()\n    \nend\n\n-- [ACTION] Début du Quizz - Timer question B - 3\n-- \nfunction event_2090_16685()\n    \nend\n\n-- [ACTION] Début du Quizz - Timer question B - 4\n-- \nfunction event_2090_16686()\n    \nend\n\n-- [ACTION] Début du Quizz - Timer question B - 5\n-- \nfunction event_2090_16687()\n    \nend\n\n-- [ACTION] Début du Quizz - Timer question C - 1\n-- \nfunction event_2090_16689()\n    \nend\n\n-- [ACTION] Début du Quizz - Timer question C - 2\n-- \nfunction event_2090_16690()\n    \nend\n\n-- [ACTION] Début du Quizz - Timer question C - 3\n-- \nfunction event_2090_16691()\n    \nend\n\n-- [ACTION] Début du Quizz - Timer question C - 4\n-- \nfunction event_2090_16692()\n    \nend\n\n-- [ACTION] Début du Quizz - Timer question C - 5\n-- \nfunction event_2090_16693()\n    \nend\n\n-- [ACTION] Début du Quizz - lancement question A - 1\n-- \nfunction event_2090_16695()\n    \nend\n\n-- [ACTION] Début du Quizz - lancement question A - 2\n-- \nfunction event_2090_16696()\n    \nend\n\n-- [ACTION] Début du Quizz - lancement question A - 3\n-- \nfunction event_2090_16697()\n    \nend\n\n-- [ACTION] Début du Quizz - lancement question A - 4\n-- \nfunction event_2090_16698()\n    \nend\n\n-- [ACTION] Début du Quizz - lancement question A - 5\n-- \nfunction event_2090_16699()\n    \nend\n\n-- [ACTION] Début du Quizz - lancement question B - 1\n-- \nfunction event_2090_16700()\n    \nend\n\n-- [ACTION] Début du Quizz - lancement question B - 2\n-- \nfunction event_2090_16701()\n    \nend\n\n-- [ACTION] Début du Quizz - lancement question B - 3\n-- \nfunction event_2090_16702()\n    \nend\n\n-- [ACTION] Début du Quizz - lancement question B - 4\n-- \nfunction event_2090_16703()\n    \nend\n\n-- [ACTION] Début du Quizz - lancement question B - 5\n-- \nfunction event_2090_16704()\n    \nend\n\n-- [ACTION] Début du Quizz - lancement question C - 1\n-- \nfunction event_2090_16705()\n    \nend\n\n-- [ACTION] Début du Quizz - lancement question C - 2\n-- \nfunction event_2090_16706()\n    \nend\n\n-- [ACTION] Début du Quizz - lancement question C - 3\n-- \nfunction event_2090_16707()\n    \nend\n\n-- [ACTION] Début du Quizz - lancement question C - 4\n-- \nfunction event_2090_16708()\n    \nend\n\n-- [ACTION] Début du Quizz - lancement question C - 5\n-- \nfunction event_2090_16709()\n    \nend\n\n-- [EVENT]Comportement Prof Random\n-- \nfunction event_2090_16731(Prof)\n    monster_bubbleId = 0\r\n    rand = 0\r\n    randDial = 0\r\n    Perso = toLong(Prof)\r\n    \r\n    -- functions\r\n    function PlayStartAnimation()\r\n      rand = (math.random(1, 100))\r\n      randDial = (math.random(1, 100))\r\n      if (rand >= 0 and rand < 10) then\r\n    --    Mobile.setMobileAnimation(monsterId, \"AnimEmote-BrandirArme1\")\r\n        monster_bubbleId = BubbleText.showText(Perso, \"nations.ch03.prof.live.01\", 0, 80, false)\r\n      elseif (rand >= 10 and rand < 20) then\r\n    --    Mobile.setMobileAnimation(monsterId, \"AnimEmote-BrandirArme1\")\r\n        monster_bubbleId = BubbleText.showText(Perso, \"nations.ch03.prof.live.02\", 0, 80, false)\r\n        Mobile.setMobileDirection(Perso, 5)\r\n        invoke(10000, 1,\"Mobile.setMobileDirection\",Perso, 1)\r\n      elseif (rand >= 20 and rand < 30) then\r\n    --    Mobile.setMobileAnimation(monsterId, \"AnimEmote-BrandirArme1\")\r\n        monster_bubbleId = BubbleText.showText(Perso, \"nations.ch03.prof.live.03\", 0, 80, false)\r\n      elseif (rand >= 30 and rand < 40) then\r\n    --    Mobile.setMobileAnimation(monsterId, \"AnimEmote-BrandirArme1\")\r\n        monster_bubbleId = BubbleText.showText(Perso, \"nations.ch03.prof.live.04\", 0, 80, false)\r\n            Mobile.setMobileDirection(Perso, 5)\r\n        invoke(10000, 1,\"Mobile.setMobileDirection\",Perso, 1)\r\n      elseif (rand >= 40 and rand < 50) then\r\n    --    Mobile.setMobileAnimation(monsterId, \"AnimEmote-BrandirArme1\")\r\n        monster_bubbleId = BubbleText.showText(Perso, \"nations.ch03.prof.live.05\", 0, 80, false)\r\n    \telseif (rand >= 50 and rand < 60) then\r\n    --    Mobile.setMobileAnimation(monsterId, \"AnimEmote-BrandirArme1\")\r\n    \tmonster_bubbleId = BubbleText.showText(Perso, \"nations.ch03.prof.live.06\", 0, 80, false)\r\n    \t    Mobile.setMobileDirection(Perso, 5)\r\n        invoke(10000, 1,\"Mobile.setMobileDirection\",Perso, 1)\r\n    \telseif (rand >= 60 and rand < 70) then\r\n    --    Mobile.setMobileAnimation(monsterId, \"AnimEmote-BrandirArme1\")\r\n    \tmonster_bubbleId = BubbleText.showText(Perso, \"nations.ch03.prof.live.07\", 0, 80, false)\r\n    \tMobile.setMobileDirection(Perso, 5)\r\n        invoke(5000, 1,\"Mobile.setMobileDirection\",Perso, 3)\r\n        invoke(5150, 1,\"Mobile.setMobileDirection\",Perso, 5)\r\n        invoke(5300, 1,\"Mobile.setMobileDirection\",Perso, 7)\r\n        invoke(5450, 1,\"Mobile.setMobileDirection\",Perso, 5)\r\n        invoke(10000, 1,\"Mobile.setMobileDirection\",Perso, 1)\r\n        end\r\n    end\r\n    \r\n    \r\n    --script\r\n      PlayStartAnimation()\r\nend\n\n","functions":["startCine","endCine","MindBubbleStart","MindBubbleChef","event_2090_16645","event_2090_16646","event_2090_16649","event_2090_16676","event_2090_16678","event_2090_16688","event_2090_16677","event_2090_16679","event_2090_16680","event_2090_16681","event_2090_16682","event_2090_16683","event_2090_16684","event_2090_16685","event_2090_16686","event_2090_16687","event_2090_16689","event_2090_16690","event_2090_16691","event_2090_16692","event_2090_16693","event_2090_16695","event_2090_16696","event_2090_16697","event_2090_16698","event_2090_16699","event_2090_16700","event_2090_16701","event_2090_16702","event_2090_16703","event_2090_16704","event_2090_16705","event_2090_16706","event_2090_16707","event_2090_16708","event_2090_16709","event_2090_16731","PlayStartAnimation"],"quest_calls":[],"dialogue_calls":[]},"scenario/2094.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\n\n-- [INIT]\n-- \nfunction event_2094_19882()\n    \nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_2094_16710()\n    \nend\n\n-- [EVENT] ENTER_INSTANCE - Cinématique Arrivée\n-- \nfunction event_2094_19883()\n    local jenry = createActor(117903815, -1, 1, -2, 4, 3, 6)\r\n    \r\n    startCinematicContext(1.3, jenry)\r\n    \r\n    invoke_custom(1000, 1,\" bubble\", jenry, \"quest.nationch3.bibliooldbonta.Jenry.01\")\r\n    invoke_custom(1000, 1, \"Mobile.setMobileAnimation\", jenry, \"AnimDial-Discute\")\r\n    \r\n    invoke_custom(4200, 1, \"bubble\", jenry, \"quest.nationch3.bibliooldbonta.Jenry.03\")\r\n    invoke_custom(5000, 1, \"Mobile.setMobileAnimation\", jenry, \"AnimDial-OK\")\r\n    invoke_custom(7000, 1, \"Mobile.moveMobile\", jenry, -10, -8, 17)\r\n    invoke_custom(9000, 1, \"bubble\", jenry, \"quest.nationch3.bibliooldbonta.Jenry.02\")\r\n    \r\n    invoke(11000, 1, \"skipCinematic\", 19883)\nend\n\n-- [EVENT] Fin Cinématique Arrivée - Validation OBJ 5565 ACH 2759\n-- \nfunction event_2094_19884()\n    \nend\n\n-- [EVENT] Le joueur passe sur le Trigger Entrée Bibliothèque - Validation OBJ 5566 ACH 2760\n-- \nfunction event_2094_16713()\n    \nend\n\n-- [EVENT] Le Joueur active une pile de livres (BAD) - Spawn monstres + Création combat\n-- \nfunction event_2094_19878()\n    \nend\n\n-- [EVENT] Le Joueur active une pile de livres (GOOD) - Spawn monstres + Création combat\n-- \nfunction event_2094_19879()\n    \nend\n\n-- [EVENT] Début du Combat pile de livres (GOOD) - Pose des Zones d'Effets\n-- \nfunction event_2094_19880()\n    \nend\n\n-- [EVENT] Victoire du Combat pile de livres (GOOD) - Cinématique + Validation OBJ 5568 ACH 2762\n-- \nfunction event_2094_19881()\n    local playerId = Context.getLeaderId()\r\n    local jenry = createActor(117903815, -46, 22,-28, 4, 3, 6)\r\n    \r\n    startCinematicContext(1.5, jenry)\r\n    \r\n    invoke_custom(1000, 1, \"bubble\", jenry, \"quest.nationch3.bibliooldbook.jenry.01\")\r\n    invoke_custom(1000, 1, \"Mobile.setMobileAnimation\", jenry, \"AnimDial-Surprise\" )\r\n    invoke_custom(2500, 1, \"Mobile.setMobileAnimation\", jenry, \"AnimComp-Dialogue-01\")\r\n    invoke_custom(4000, 1, \"Mobile.moveMobile\", playerId, -46, 23, -28, \"Mobile.setMobileDirection\", playerId, 7)\r\n    invoke_custom(5000, 1, \"bubble\", jenry, \"quest.nationch3.bibliooldbook.jenry.02\")\r\n    invoke_custom(5000, 1, \"Mobile.setMobileAnimation\", jenry, \"AnimDial-Discute\" )\r\n    invoke_custom(7000, 1, \"Mobile.setMobileAnimation\", jenry, \"AnimComp-Carte\" )\r\n    \r\n    invoke_custom(10000, 1, \"bubble\", jenry, \"quest.nationch3.bibliooldbook.jenry.03\")\r\n    invoke_custom(10000, 1, \"Mobile.setMobileAnimation\", jenry, \"AnimDial-OK\" )\r\n    invoke_custom(11500, 1, \"Mobile.setMobileAnimation\", jenry, \"AnimDial-Discute\" )\r\n    invoke_custom(14000, 1, \"bubble\", jenry, \"quest.nationch3.bibliooldbook.jenry.04\")\r\n    invoke_custom(14000, 1, \"Mobile.setMobileAnimation\", jenry, \"AnimDial-Discute\" )\r\n    \r\n    invoke_custom(18000, 1, \"bubble\",  jenry, \"quest.nationch3.bibliooldbook.jenry.05\")\r\n    invoke_custom(19000, 1, \"Mobile.moveMobile\", jenry, -58, 26, -28)\r\n    invoke_custom(20000, 1, \"Mobile.setMobileDirection\", playerId, 7)\r\n    \r\n    invoke(24000, 1, \"skipCinematic\")\nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_2094_19882","event_2094_16710","event_2094_19883","event_2094_19884","event_2094_16713","event_2094_19878","event_2094_19879","event_2094_19880","event_2094_19881"],"quest_calls":[],"dialogue_calls":[]},"scenario/2095.lua":{"source":"m_playerId = Context.getPlayer()\n\n-- Lancement Cinématique\n-- \nfunction event_2095_16725()\n    \nend\n\n","functions":["event_2095_16725"],"quest_calls":[],"dialogue_calls":[]},"scenario/2096.lua":{"source":"bubbleSteleInfoId = 0\r\n\r\nfunction closeSteleInfo()\r\n\tif (bubbleSteleInfoId ~= nil  and bubbleSteleInfoId ~= 0) then BubbleText.close(bubbleSteleInfoId) end\r\nend\r\n\r\nfunction onSteleInfoClosed()\r\n\tif (bubbleSteleInfoId ~= nil  and bubbleSteleInfoId ~= 0) then bubbleSteleInfoId = 0 end\r\nend\r\n\r\nfunction updateSteleInfo(stateInfoId, forceDisplayUI)\r\n\r\n\tif (bubbleSteleInfoId == 0) then\r\n\t\tbubbleSteleInfoId = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_WEST\", 0, -60, false, 2147483647, true, \"interactiveBubbleDialog5\", 30000, 25000, \"onSteleInfoClosed\")\r\n\tend\r\n\r\n\tBubbleText.setText(bubbleSteleInfoId, stateInfoId)\r\n\t\r\n\tif (forceDisplayUI) then BubbleText.show(bubbleSteleInfoId) end\r\nend\n\n-- [INIT] Variables\n-- \nfunction event_2096_16752()\n    \nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_2096_16753()\n    \nend\n\n-- [EVENT][3] Victoire - Déverouille le passage vers S4\n-- \nfunction event_2096_16759()\n    \nend\n\n-- [EVENT] ZoneTrigger - Le joueur marche dans le vide\n-- \nfunction event_2096_16794()\n    local playerId = Context.getLeaderId()\r\n    invoke(350, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimMort-ChuteVide\")\r\nend\n\n-- [EVENT] ZoneTrigger - Le joueur est TP\n-- \nfunction event_2096_16795()\n    \nend\n\n-- [EVENT] Combat lancé - Désactivation de la ZoneTrigger\n-- \nfunction event_2096_16796()\n    \nend\n\n-- [EVENT] Salle 4 - Début de Combat\n-- \nfunction event_2096_16772()\n 