Long(steleCount)\r\n    if (steleCount == 0) then rewardId = 27158\r\n    elseif (steleCount == 1) then rewardId = 27139\r\n    elseif (steleCount == 2) then rewardId = 27135\r\n    else rewardId = 0\r\n    end\r\n    \r\n    UI.openRewardsDialog(\"stele.description\")\r\n    UI.addReward(rewardId)\r\n    \r\n    local stateInfoId = \"stele.state.description.4185\"\r\n    \r\n    updateSteleInfo(stateInfoId, true)\nend\n\n-- [OLD][EVENT] Le joueur examine la Stèle 3\n-- \nfunction event_2096_20582(steleCount)\n    local steleCount = toLong(steleCount)\r\n    if (steleCount == 0) then rewardId = 27158\r\n    elseif (steleCount == 1) then rewardId = 27139\r\n    elseif (steleCount == 2) then rewardId = 27135\r\n    else rewardId = 0\r\n    end\r\n    \r\n    UI.openRewardsDialog(\"stele.description\")\r\n    UI.addReward(rewardId)\r\n    \r\n    local stateInfoId = \"stele.state.description.4186\"\r\n    \r\n    updateSteleInfo(stateInfoId, true)\nend\n\n-- [OLD][EVENT] Salle 4 - Refresh des APS pour le porteur des états Stèle\n-- \nfunction event_2096_16764()\n    \nend\n\n-- [EVENT] Salle 4 - Récupère l'ID du combat\n-- \nfunction event_2096_16767()\n    \nend\n\n-- [EVENT] Salle 4 - Reset l'ID du combat\n-- \nfunction event_2096_16768()\n    \nend\n\n-- [EVENT] Fin du combat avec victoire des Joueurs (1 stèle) - Validation Quête\n-- \nfunction event_2096_16769()\n    \nend\n\n-- [EVENT] Fin du combat avec victoire des Joueurs (2 stèles) - Validation Quête\n-- \nfunction event_2096_16770()\n    \nend\n\n-- [EVENT] Fin du combat avec victoire des Joueurs (3 stèles) - Validation Quête\n-- \nfunction event_2096_16771()\n    \nend\n\n-- [EVENT] Fin Combat - Victoire Joueurs Stèles 1&2 - Validation Quête\n-- \nfunction event_2096_16919()\n    \nend\n\n-- [EVENT] Fin Combat - Victoire Joueurs Stèles 2&3 - Validation Quête\n-- \nfunction event_2096_16920()\n    \nend\n\n-- [EVENT] Fin Combat - Victoire Joueurs Stèles 1&3 - Validation Quête\n-- \nfunction event_2096_16921()