article.removeParticleSystem\",particleWakfuTree,true)\r\n      invoke_custom(4500, 1, \"Camera.setZoomSpeedFactor\", 2.2)\r\n      invoke_custom(4500, 1, \"Camera.setZoomFactor\", 1)\r\n    \r\n      --ANIMATION DES ARBRES AU SPAWN\r\n      invoke_custom(4800, 1, \"Mobile.setMobileAnimation\",2796, \"AnimIncarnation\")\r\n      invoke_custom(4800, 1, \"Mobile.setMobileAnimation\", 2805, \"AnimIncarnation\")\r\n      invoke_custom(4600, 1, \"Effect.createCameraShakeEffect\", 0, 500, 1500, 5)\r\n      invoke_custom(5400, 1, \"Mobile.setMobileAnimation\", player, \"AnimKO-Debut\")\r\n      invoke_custom(6500, 1, \"Camera.setZoomSpeedFactor\", 0.15)\r\n      invoke_custom(6500, 1, \"Camera.setZoomFactor\", 1.6)\r\n      invoke_custom(6500, 1, \"addWakfuTreeLeaves\")\r\n      invoke_custom(7200, 1, \"wipeMobs\")\r\n    end\r\n    \r\n    ---- Les mobs sont wipe par l'onde de Wakfu du spawn player.\r\n    ---- Le Boss est stun. Otomai est distrait.\r\n    function wipeMobs()\r\n      Camera.setMoveSpeedFactor(6)\r\n      --\tCamera.setZoomSpeedFactor(1)\r\n      --Particle.addParticleSystem(apsWave.wave, pos_apsWave[1], pos_apsWave[2], pos_apsWave[3])\r\n      invoke_custom(0100, 1, \"Camera.attachCameraToMobile\", otomaiMobileId)\r\n      invoke_custom(0100, 1, \"Camera.setZoomFactor\", 1.5)\r\n      invoke_custom(0200, 1, \"Particle.addParticleSystem\", apsWave.wave, 15, 1, -13)\r\n      invoke_custom(0700, 1, \"Mobile.setMobileAnimation\", otomaiMobileId, ANM_otomai.wave_hit)\r\n      invoke_custom(0500, 1, \"Mobile.setMobileAnimation\", NPC_meleeB, \"AnimHit\")\r\n      invoke_custom(0500, 1, \"Particle.addParticleSystem\", apsWave.hit, 13, 1, -13)\r\n    \r\n      invoke_custom(0700, 1, \"Mobile.setMobileAnimation\", NPC_boss, \"AnimHit\")\r\n      invoke_custom(0700, 1, \"Particle.addParticleSystem\", apsWave.hit, 14, -1, -13)\r\n      invoke_custom(0900, 1, \"Mobile.setMobileAnimation\", NPC_melee, \"AnimHit\")\r\n      invoke_custom(0900, 1, \"Particle.addParticl