pha(0.9)\r\n        --Focus.setPosition(fightResultX * -1, fightResultY * -1, screenWidth - fightResultX, screenHeight - fightResultY )\r\n        --Focus.display(true)\r\n    \r\n        --invoke_custom(100, 1, \"Focus.movePosition\", 1000, xpContainerX - fightResultX - 4, xpContainerY - fightResultY - 4, xpContainerX - fightResultX + xpContainerWidth + 5, xpContainerY - fightResultY + xpContainerHeight + 30)\r\n    \r\n        --BUTTON FOCUS\r\n        --invoke_custom(1100, 1, \"Focus.setButton\", \"skip\", \"onFightResultUnloaded\")\r\n        --PARTICLE BUTTON FOCUS\r\n        --invoke_custom(1100, 1, \"setUIParticle\", \"focusDialog\", \"button\", apsArrow[8] .. \".xps\", 0, 0, \"WEST\")\r\n    end\r\n    \r\n    --CODE\r\n    addDialogUnloadListener(\"fightResultDialog\", \"onFightResultUnloaded\")\r\n    addDialogLoadListener(\"fightResultDialog\", \"onFightResultLoaded\")\nend\n\n-- 3 - 0 - TRIG(3) + TRIG(1) ; Cinématique\n-- \nfunction event_2114_16948(otomaiMobileId, monsterId)\n    trace(\"CINEMATIQUE 3\")\r\n    clearALL()\r\n    \r\n    --CINEMATIQUE\r\n    local player = Context.getLeaderId()\r\n    local pos_melee_spawn = {19, -16, -12}\r\n    local pos_melee_dest = {a={20, -16, -12}, b={18, -15, -3}}\r\n    local otomaiX, otomaiY, otomaiZ = Mobile.getMobilePosition(otomaiMobileId)\r\n    \r\n    displayScreenEffect(true, 0, 1000, 500, 0, 0, 0, 1)\r\n    \r\n    Mobile.setMobileLookAt(player, otomaiX, otomaiY, false)\r\n    Mobile.setMobileVisible(monsterId, false)\r\n    Mobile.setMobilePosition(monsterId, pos_melee_spawn[1], pos_melee_spawn[2], pos_melee_spawn[3])\r\n    Mobile.setMobileDirection(monsterId, 1)\r\n    Mobile.setMobileVisible(monsterId, true)\r\n    \r\n    -- Skip admin\r\n    function customSkip()\r\n    Mobile.setMobileVisible(monsterId, true)\r\n    Mobile.setMobilePosition(monsterId, 18, -15, -3)\r\n    Mobile.setMobileDirection(monsterId, 5)\r\n    stopCinematicContext(1, player , true)\r\n    end\r\n    \r\n    startCinematicContext(1.5, monsterId)\r\n    if (_ADMIN) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"customSkip\") end\r\n    \r\n    invoke_custom(2000, 1, \"Mobile.moveMobile\", monsterId, pos_melee_dest.a[1], pos_melee_dest.a[2], pos_melee_dest.a[3], \"Mobile.setMobileAnimation\", monsterId, ANM_melee.roar)\r\n    \r\n    invoke_custom(5000, 1, \"Mobile.moveMobile\", monsterId, pos_melee_dest.b[1], pos_melee_dest.b[2], pos_melee_dest.b[3], \"otomaiReac\")\r\n    \r\n    \r\n    function otomaiReac()\r\n      \tinvoke_custom(0100, 1, \"Camera.attachCameraToMobile\", otomaiMobileId)\r\n       \tinvoke_custom(0500, 1, \"Mobile.setMobileDirection\", otomaiMobileId, 1)\r\n        invoke_custom(1000, 1, \"bubble\", otomaiMobileId, \"incarnam.cinematic.tuto2.6\", NPC_otomai_bubbleX, NPC_otomai_bubbleY, false)\r\n        invoke_custom(1000, 1, \"Mobile.setMobileAnimation\", otomaiMobileId, ANM_otomai.show)\r\n    \r\n    \tinvoke_custom(5000, 1, \"stopCinematicContext\", 1, player, true)\r\n    end\nend\n\n-- 3 - 1 - TRIG(2) ; Attaquer le monstre (Lancer un combat)\n-- \nfunction event_2114_16949(otomaiMobileId, monsterId)\n    trace(\"TUTO 3 - STEP 1\")\r\n    clearALL()\r\n    \r\n    --BUBBLE NPC\r\n    setInterval_custom(10000, \"bubble\", otomaiMobileId, \"incarnam.tuto.npc.start.fight3.0\", NPC_otomai_bubbleX, NPC_otomai_bubbleY, false)\r\n    \r\n    --SHORTCUTS des étapes précédentes\r\n    UI.setShortcutEnabled(true, \"shortcutCategory.fight\", \"endPlacementAndTurn\")\r\n    UI.setShortcutEnabled(true, \"shortcutCategory.fight\", \"closeCombatRight\")\r\n    UI.setShortcutEnabled(true, \"shortcutCategory.fight\", \"closeCombatLeft\")\r\n    prepareShortcuts(true, \"SHORTCUTBAR\")\r\n    UI.setShortcutEnabled(true, \"shortcutCategory.fight\", \"resetFightCamera\")\r\n    \r\n    --PARTICLE WORLD\r\n    setWorldParticleTarget(apsCell.red_arrow, monsterId, 0, NPC_melee_particleZ)\nend\n\n-- 3 - 2 - MONSTER ACTION ; Démarrage du combat\n-- \nfunction event_2114_16950(otomaiMobileId)\n    trace(\"TUTO 3 - STEP 2\")\r\n    clearALL()\nend\n\n-- 3 - 3 - FIGHTER_TURN_START ; Changer son orientation (Localisation dmg reçus)\n-- \nfunction event_2114_16981(otomaiMobileId, monsterId, fightId)\n    trace(\"TUTO 3 - STEP 3\")\r\n    clearALL()\r\n    \r\n    --TUTORIEL UI\r\n    UI.loadTutorialDialog(\"incarnam.tuto.ui.orientation\", \"incarnam.tuto.ui.orientation.title\", \"incarnam.tuto.ui.orientation.infos\")\r\n    --BUBBLE NPC\r\n    setInterval_custom(10000, \"bubble\", otomaiMobileId, \"incarnam.tuto.npc.orientation\", NPC_otomai_bubbleX, NPC_otomai_bubbleY, false)\r\n    \r\n    function onOrientationClicked()\r\n    \tif (ORIENTATION_STEP_COMPLETE) then return end\r\n    \t\r\n    \tORIENTATION_STEP_COMPLETE = true\r\n    \tclearALL()\r\n    \tclearListener()\r\n    \t\r\n    \tlocal playerId = Context.getLeaderId()\r\n    \t\r\n    \tEvent.removeFightTurnStartedListener(playerId)\r\n    \tMobile.removeOnPathEndedListener(playerId, pathEnded)\r\n    \r\n    \tServer.triggerEvent(4) --TRIGGER\r\n    end\r\n    \r\n    function getButtonToFaceMonster()\r\n    \tlocal playerId = Context.getLeaderId()\r\n    \tlocal playerX, playerY, playerZ = Mobile.getMobilePosition(playerId)\r\n    \tlocal monsterX, monsterY, monsterZ = Mobile.getMobilePosition(monsterId)\r\n    \tlocal dirToFaceMonster = Mobile.getDirectionTo(playerX, playerY, monsterX, monsterY)\r\n    \tlocal button = nil\r\n    \r\n    \tif (dirToFaceMonster == 1) then\r\n    \t\tbutton = {name=\"seButton\", aps=4, x=-5, y=8}\r\n    \telseif (dirToFaceMonster == 3) then\r\n    \t\tbutton = {name=\"swButton\", aps=8, x=5, y=8}\r\n    \telseif (dirToFaceMonster == 5) then\r\n    \t\tbutton = {name=\"nwButton\", aps=8, x=5, y=0}\r\n    \telseif (dirToFaceMonster == 7) then\r\n    \t\tbutton = {name=\"neButton\", aps=4, x=-5, y=0}\r\n    \tend\r\n    \t\r\n    \treturn button\r\n    end\r\n    \r\n    function init()\r\n    \tclearUI()\r\n    \tclearListener()\r\n    \t\t\t\r\n    \tlocal button = getButtonToFaceMonster()\r\n    \tif (not button) then return end\t  \t\r\n    \t\r\n    \taddDialogEventListener(\"worldAndFightBarDialog\", button.name, \"MOUSE_CLICKED\",  \"onOrientationClicked\")\t\r\n    \r\n    \t--UI PARTICLE\r\n    \tsetUIParticle(\"worldAndFightBarDialog\", button.name, apsArrow[button.aps] .. \".xps\", button.x, button.y, \"CENTER\")\t\t\r\n    end\r\n    \r\n    function onPathEnded()\r\n    \tif (ORIENTATION_STEP_COMPLETE) then return end\r\n    \t\r\n    \tlocal playerId = Context.getLeaderId()\r\n    \tpathEnded = Mobile.onPathEnded(playerId, \"onPathEnded\")\r\n    \t\r\n    \tinit()\r\n    end\r\n    \r\n    function onTurnStarted()\r\n    \tif (ORIENTATION_STEP_COMPLETE) then return end\r\n    \t\r\n    \tinit()\r\n    end  \r\n    \r\n    --CODE\r\n    local playerId = Context.getLeaderId()\r\n    ORIENTATION_STEP_COMPLETE = false\r\n    \r\n    pathEnded = Mobile.onPathEnded(playerId, \"onPathEnded\")\r\n    Event.setFightTurnStartedListener(playerId, \"onTurnStarted\")\r\n    \r\n    init()\nend\n\n-- 3 - 4 - TRIG(4) ; Ouvrir la fiche du monstre (Fiche combattant)\n-- \nfunction event_2114_16951(otomaiMobileId, monsterId)\n    trace(\"TUTO 3 - STEP 4\")\r\n    clearALL()\r\n    \r\n    --TUTORIEL UI\r\n    UI.loadTutorialDialog(\"incarnam.tuto.ui.fighter.infos\", \"incarnam.tuto.ui.fighter.infos.title\", \"incarnam.tuto.ui.fighter.infos.infos\")\r\n    \r\n    --BUBBLE NPC\r\n    setInterval_custom(10000, \"bubble\", otomaiMobileId, \"incarnam.tuto.npc.fighter.infos\", NPC_otomai_bubbleX, NPC_otomai_bubbleY, false)\r\n    \r\n    function onFighterDescriptionUnloaded(dialog)\r\n    \tclearALL()\r\n    \tclearListener()\r\n    \t\r\n    \tif UI.isDialogLoaded(dialog) then \r\n    \t\tUI.unloadDialog(dialog)\r\n    \tend\t\r\n    \t\r\n    \tServer.triggerEvent(5) --TRIGGER\r\n    end\r\n    \r\n    function onFighterDescriptionLoaded(dialog)\r\n    \taddDialogUnloadListener(dialog, \"onFighterDescriptionUnloaded\", dialog)\r\n    \t\r\n    \tlocal figtherDescriptionWidth, figtherDescriptionHeight = UI.getWindowSize(dialog)\r\n    \tlocal timelineX, timelineY = UI.getPosition(\"timePointBarDialog\", \"selectedFighterContainer\")\r\n    \t\t\t\r\n    \tUI.setPosition(dialog, timelineX - figtherDescriptionWidth, timelineY)\r\n    \t\r\n    \tinvoke_custom(200, 1, \"setFocus\", dialog, timelineX, timelineY, figtherDescriptionWidth, figtherDescriptionHeight)\r\n    \t\t\t\r\n    \tinvoke_custom(500, 1, \"Focus.movePosition\", 1000, 0, 0, figtherDescriptionWidth, figtherDescriptionHeight)\r\n    \t\r\n    \t--PARTICLE BUTTON FOCUS\r\n    \tinvoke_custom(1500, 1, \"setUIParticle\", \"focusDialog\", \"button\", apsArrow[8] .. \".xps\", 0, 0, \"WEST\")\r\n    \t\r\n    \t--PARTICLE UI\r\n    \tinvoke_custom(1500, 1, \"setUIParticleBorder\", dialog, \"stateContainer\", apsFollowBorder .. \".xps\", 0, 0, \"CENTER\", 1, 75)\r\n    end\r\n    \r\n    function setFocus(dialog, timelineX, timelineY, figtherDescriptionWidth, figtherDescriptionHeight)\r\n    \r\n    \tlocal screenWidth, screenHeight = UI.getWindowSize()\r\n    \t\r\n    \tFocus.reset()\r\n    \tFocus.setMouseBlocked(true)\r\n    \tFocus.setDialogGrip(dialog)\r\n    \tFocus.setAlpha(0.9)\r\n    \tFocus.setPosition((timelineX - figtherDescriptionWidth) * -1, timelineY * -1, screenWidth - (timelineX - figtherDescriptionWidth), screenHeight - timelineY)\r\n    \tFocus.setButton(\"skip\", \"onFighterDescriptionUnloaded\", dialog) \r\n    \tFocus.display(true)\t\r\n    end\r\n    \r\n    --CODE\r\n    local dialogName = \"fighterDescriptionDialog\" .. toString(monsterId)\r\n    \r\n    if not UI.isDialogLoaded(dialogName) then \r\n    \taddDialogLoadListener(dialogName, \"onFighterDescriptionLoaded\", dialogName)\r\n    \tUI.loadDialog(dialogName)\r\n    else\r\n    \tonFighterDescriptionLoaded(dialogName)\r\n    end\nend\n\n-- 3 - 5 - TRIG(5) ; Terminer le combat  (Localisation dmg infligés)\n-- \nfunction event_2114_16954(otomaiMobileId)\n    trace(\"TUTO 3 - STEP 5\")\r\n    clearALL()\r\n    \r\n    --TUTORIEL UI\r\n    UI.loadTutorialDialog(\"incarnam.tuto.ui.orientation2\", \"incarnam.tuto.ui.orientation2.title\", \"incarnam.tuto.ui.orientation2.infos\")\r\n    \r\n    --BUBBLE NPC\r\n    setInterval_custom(10000, \"bubble\", otomaiMobileId, \"incarnam.tuto.npc.orientation2\", NPC_otomai_bubbleX, NPC_otomai_bubbleY, false)\nend\n\n-- 3 - 6 - FIGHT_END_CLIENT ; Fin\n-- \nfunction event_2114_16968(otomaiMobileId)\n    trace(\"TUTO 3 - STEP 6\")\r\n    clearALL()\nend\n\n-- 4 - 0 - FIGHT_END_CLIENT +  TRIG(1) ; Cinématique\n-- \nfunction event_2114_16953(otomaiMobileId)\n    trace(\"CINEMATIQUE 4\")\r\n    clearALL()\r\n    \r\n    --CINEMATIQUE\r\n    local player = Context.getLeaderId()\r\n    local otomaiX, otomaiY, otomaiZ = Mobile.getMobilePosition(otomaiMobileId)\r\n    local pos_otomai_dest = {21, -12, -12}\r\n    \r\n    displayScreenEffect(true, 0, 1000, 500, 0, 0, 0, 1)\r\n    \r\n    Mobile.setMobileLookAt(player, otomaiX, otomaiY, false)\r\n    \r\n    -- Skip admin\r\n    function customSkip()\r\n    Mobile.setMobilePosition(otomaiMobileId, 21, -12, -12)\r\n    stopCinematicContext(1, player , true)\r\n    end\r\n    \r\n    startCinematicContext(1.3, player)\r\n    if (_ADMIN) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"customSkip\") end\r\n    \r\n    invoke_custom(2000, 1, \"Mobile.setMobileAnimation\", otomaiMobileId, ANM_otomai.talk)\r\n    invoke_custom(2000, 1, \"bubble\", otomaiMobileId, \"incarnam.cinematic.tuto4.0\", NPC_otomai_bubbleX, NPC_otomai_bubbleY, false)\r\n    invoke_custom(6000, 1, \"clearBubbles\")\r\n    invoke_custom(6000, 1, \"bubble\", otomaiMobileId, \"incarnam.cinematic.tuto4.1\", NPC_otomai_bubbleX, NPC_otomai_bubbleY, false)\r\n    \r\n    invoke_custom(9000, 1, \"Mobile.moveMobile\", otomaiMobileId, otomaiX, otomaiY+3, otomaiZ)\r\n    \r\n    invoke_custom(11000, 1, \"clearBubbles\")\r\n    invoke_custom(11000, 1, \"Mobile.moveMobile\", otomaiMobileId, pos_otomai_dest[1], pos_otomai_dest[2], pos_otomai_dest[3])\r\n    \r\n    invoke_custom(15000, 1, \"stopCinematicContext\", 1, player, false)\nend\n\n-- 4 - 1 - TRIG(2) ; Utiliser une emote Assoir (Emote)\n-- \nfunction event_2114_16955(otomaiMobileId)\n    trace(\"TUTO 4 - STEP 1\")\r\n    clearALL()\r\n    \r\n    --TUTORIEL UI\r\n    UI.loadTutorialDialog(\"incarnam.tuto.ui.emote.rest\", \"incarnam.tuto.ui.emote.rest.title\", \"incarnam.tuto.ui.emote.rest.infos\")\r\n    \r\n    --SHORTCUTS  des étapes précédentes\r\n    UI.setShortcutEnabled(true, \"shortcutCategory.fight\", \"endPlacementAndTurn\")\r\n    UI.setShortcutEnabled(true, \"shortcutCategory.fight\", \"closeCombatRight\")\r\n    UI.setShortcutEnabled(true, \"shortcutCategory.fight\", \"closeCombatLeft\")\r\n    prepareShortcuts(true, \"SHORTCUTBAR\")\r\n    UI.setShortcutEnabled(true, \"shortcutCategory.fight\", \"resetFightCamera\")\r\n    \r\n    --SHORTCUTS\r\n    if not UI.hasShortcut(20015, 2) then\r\n    \tUI.addEmoteShortcut(20015, 0)\r\n    end\r\n    \r\n    --PARTICLE UI\r\n    invoke_custom(500, 1, \"setUIParticle\", \"worldAndFightBarDialog\", \"shortcutBarList#0\", apsArrow[2] .. \".xps\", 0, 0, \"NORTH\")\nend\n\n-- 4 - 2 - REST ; Rejoindre Otomaï\n-- \nfunction event_2114_16956(otomaiMobileId)\n    trace(\"TUTO 4 - STEP 2\")\r\n    clearALL()\r\n    \r\n    --COMPASS WORLD\r\n    setCompass(21, -2, -33)\nend\n\n-- 4 - 3 - POSITION_TRIG ; Fin\n-- \nfunction event_2114_16957(otomaiMobileId)\n    trace(\"TUTO 4 - STEP 3\")\r\n    clearALL()\nend\n\n-- 5 - 0 - POSITION_TRIG + TRIG(1) ; Cinématique\n-- \nfunction event_2114_16958(otomaiMobileId, monsterMeleeId, monsterRangeId)\n    trace(\"CINEMATIQUE 5\")\r\n    clearALL()\r\n    \r\n    --CINEMATIQUE\r\n    local player = Context.getLeaderId()\r\n    local otomaiX, otomaiY, otomaiZ = Mobile.getMobilePosition(otomaiMobileId)\r\n    local pos_melee_spawn = {25, 5, -33}\r\n    local pos_melee_dest =  {25, -1, -33}\r\n    local pos_range_spawn =  {27, 5, -33}\r\n    local pos_range_dest =  {27, 1, -33}\r\n    \r\n    displayScreenEffect(true, 0, 1000, 500, 0, 0, 0, 1)\r\n    \r\n    Mobile.setMobileDirection(player, 3)\r\n    \r\n    Mobile.setMobileVisible(monsterMeleeId, false)\r\n    Mobile.setMobilePosition(monsterMeleeId, pos_melee_spawn[1], pos_melee_spawn[2], pos_melee_spawn[3])\r\n    Mobile.setMobileDirection(monsterMeleeId, 5)\r\n    Mobile.setMobileVisible(monsterMeleeId, true)\r\n    \r\n    Mobile.setMobileVisible(monsterRangeId, false)\r\n    Mobile.setMobilePosition(monsterRangeId, pos_range_spawn[1], pos_range_spawn[2], pos_range_spawn[3])\r\n    Mobile.setMobileDirection(monsterRangeId, 5)\r\n    Mobile.setMobileVisible(monsterRangeId, true)\r\n    \r\n    -- Skip admin\r\n    function customSkip()\r\n    Mobile.setMobilePosition(monsterMeleeId, 25, -1, -33)\r\n    Mobile.setMobilePosition(monsterRangeId, 27, 1, -33)\r\n    stopCinematicContext(1, player , true)\r\n    end\r\n    \r\n    startCinematicContext(1, otomaiMobileId)\r\n    if (_ADMIN) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"customSkip\") end\r\n    \r\n    invoke_custom(2000, 1, \"bubble\", otomaiMobileId, \"incarnam.cinematic.tuto3.0\", NPC_otomai_bubbleX, NPC_otomai_bubbleY, false)\r\n    invoke_custom(2000, 1, \"Mobile.setMobileAnimation\", otomaiMobileId, ANM_otomai.show)\r\n    \r\n    invoke_custom(4000, 1, \"Mobile.moveMobile\", monsterMeleeId, pos_melee_dest[1], pos_melee_dest[2], pos_melee_dest[3], \"endMoveMelee\")\r\n    \r\n    invoke_custom(6000, 1, \"Mobile.setMobileAnimation\", otomaiMobileId, ANM_otomai.talk)\r\n    invoke_custom(6000, 1, \"bubble\", otomaiMobileId, \"incarnam.cinematic.tuto3.1\", NPC_otomai_bubbleX, NPC_otomai_bubbleY, false)\r\n    \r\n    invoke_custom(4000, 1, \"Mobile.moveMobile\", monsterRangeId, pos_range_dest[1], pos_range_dest[2], pos_range_dest[3], \"endMoveRange\")\r\n    \r\n    invoke_custom(10000, 1, \"stopCinematicContext\", 1, player, false)\r\n    \r\n    function endMoveMelee()\r\n    \tMobile.setMobileAnimation(monsterMeleeId, ANM_melee.roar)\r\n    end\r\n    \r\n    function endMoveRange()\r\n    \tMobile.setMobileAnimation(monsterRangeId, ANM_range.glitch)\r\n    end\nend\n\n-- 5 - 1 - TRIG(2) ; Attaquer les monstres (Lancer un combat)\n-- \nfunction event_2114_16960(otomaiMobileId, monsterMeleeId, monsterRangeId)\n    trace(\"TUTO 5 - STEP 1\")\r\n    clearALL()\r\n    \r\n    --BUBBLE NPC\r\n    setInterval_custom(10000, \"bubble\", otomaiMobileId, \"incarnam.tuto.npc.start.fight4.0\", NPC_otomai_bubbleX, NPC_otomai_bubbleY, false)\r\n    \r\n    --SHORTCUTS  des étapes précédentes\r\n    UI.setShortcutEnabled(true, \"shortcutCategory.fight\", \"endPlacementAndTurn\")\r\n    UI.setShortcutEnabled(true, \"shortcutCategory.fight\", \"closeCombatRight\")\r\n    UI.setShortcutEnabled(true, \"shortcutCategory.fight\", \"closeCombatLeft\")\r\n    prepareShortcuts(true, \"SHORTCUTBAR\")\r\n    UI.setShortcutEnabled(true, \"shortcutCategory.fight\", \"resetFightCamera\")\r\n    \r\n    --PARTICLE WORLD\r\n    setWorldParticleTarget(apsCell.red_arrow, monsterMeleeId, 0, NPC_melee_particleZ)\r\n    setWorldParticleTarget(apsCell.red_arrow, monsterRangeId, 0, NPC_range_particleZ)\nend\n\n-- 5 - 2 - MONSTER_ACTION ; Démarrage du combat\n-- \nfunction event_2114_16961(otomaiMobileId)\n    trace(\"TUTO 5 - STEP 2a\")\r\n    clearALL()\nend\n\n-- 5 - 2 - FIGHT_ENTER_ACTION ; Ligne de vue\n-- \nfunction event_2114_16962(otomaiMobileId, fightId)\n    trace(\"TUTO 5 - STEP 2b\")\r\n    clearALL()\r\n    \r\n    --TUTORIEL UI\r\n    UI.loadTutorialDialog(\"incarnam.tuto.ui.line.of.sight\", \"incarnam.tuto.ui.line.of.sight.title\", \"incarnam.tuto.ui.line.of.sight.infos\")\r\n    \r\n    --BUBBLE NPC\r\n    setInterval_custom(10000, \"bubble\", otomaiMobileId, \"incarnam.tuto.npc.line.of.sight\", NPC_otomai_bubbleX, NPC_otomai_bubbleY, false)\nend\n\n-- 5 - 3 - FIGHT_END_CLIENT - UI fin combat (Level up)\n-- \nfunction event_2114_16963(otomaiMobileId)\n    trace(\"TUTO 5 - STEP 3\")\r\n    clearALL()\r\n    \r\n    --TUTORIEL UI\r\n    UI.loadTutorialDialog(\"incarnam.tuto.ui.level.up\", \"incarnam.tuto.ui.level.up.title\", \"incarnam.tuto.ui.level.up.infos\")\r\n    \r\n    --BUBBLE NPC\r\n    setInterval_custom(10000, \"bubble\", otomaiMobileId, \"incarnam.tuto.npc.level.up\", NPC_otomai_bubbleX, NPC_otomai_bubbleY, false)\r\n    \r\n    --FUNCTION\r\n    function onFightResultUnloaded()\r\n    \tclearALL()\r\n    \tclearListener()\r\n    \t\r\n    \t--TRIGGER\r\n    \tServer.triggerEvent(3)\r\n    end\r\n    \r\n    function onFightResultLoaded()\r\n    \r\n    end\r\n    \r\n    --CODE\r\n    addDialogLoadListener(\"fightResultDialog\", \"onFightResultLoaded\")\r\n    addDialogUnloadListener(\"fightResultDialog\", \"onFightResultUnloaded\")\r\n    setUIParticle(\"fightResultDialog\", \"closeFightResultDialog\", apsArrow[7] .. \".xps\", 5, 5, \"SOUTH_WEST\")\r\n    \r\n    if not UI.isDialogLoaded(\"fightResultDialog\") then onFightResultUnloaded() end\nend\n\n-- 6 - 0 - TRIG(1) + TRIG(3) ; Cinématique\n-- \nfunction event_2114_16969(otomaiMobileId)\n    trace(\"CINEMATIQUE 6\")\r\n    clearALL()\r\n    \r\n    --CINEMATIQUE\r\n    local player = Context.getLeaderId()\r\n    local pos_otomai_dest = {34, -2, -33}\r\n    \r\n    displayScreenEffect(true, 0, 1000, 500, 0, 0, 0, 1)\r\n    \r\n    -- Skip admin\r\n    function customSkip()\r\n    \tMobile.setMobilePosition(otomaiMobileId, 34, -2, -33)\r\n    \tstopCinematicContext(1, player , true)\r\n    end\r\n    \r\n    startCinematicContext(1, otomaiMobileId)\r\n    if (_ADMIN) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"customSkip\") end\r\n    \r\n    invoke_custom(2000, 1, \"Mobile.setMobileAnimation\", otomaiMobileId, ANM_otomai.nice)\r\n    invoke_custom(2000, 1, \"bubble\", otomaiMobileId, \"incarnam.cinematic.tuto6.0\", NPC_otomai_bubbleX, NPC_otomai_bubbleY, false)\r\n    \r\n    invoke_custom(6000, 1, \"Mobile.setMobileAnimation\", otomaiMobileId, ANM_otomai.talk)\r\n    invoke_custom(6000, 1, \"bubble\", otomaiMobileId, \"incarnam.cinematic.tuto6.1\", NPC_otomai_bubbleX, NPC_otomai_bubbleY, false)\r\n    \r\n    invoke_custom(10000, 1, \"clearBubbles\")\r\n    invoke_custom(10000, 1, \"Mobile.moveMobile\", otomaiMobileId, pos_otomai_dest[1], pos_otomai_dest[2], pos_otomai_dest[3], \"endMove\")\r\n    \r\n    function endMove()\r\n    \tstopCinematicContext(1, player, true)\r\n    end\nend\n\n-- 6 - 1 - TRIG(2) ; Répartir son point d'aptitude (Aptitude)\n-- \nfunction event_2114_16964(otomaiMobileId)\n    trace(\"TUTO 6 - STEP 1\")\r\n    clearALL()\r\n    \r\n    --TUTORIEL UI\r\n    UI.loadTutorialDialog(\"incarnam.tuto.ui.aptitude\", \"incarnam.tuto.ui.aptitude.title\", \"incarnam.tuto.ui.aptitude.infos\")\r\n    \r\n    --BUBBLE NPC\r\n    setInterval_custom(10000, \"bubble\", otomaiMobileId, \"incarnam.tuto.npc.aptitude\", NPC_otomai_bubbleX, NPC_otomai_bubbleY, false)\r\n    \r\n    --SHORTCUTS des étapes précédentes\r\n    UI.setShortcutEnabled(true, \"shortcutCategory.fight\", \"endPlacementAndTurn\")\r\n    UI.setShortcutEnabled(true, \"shortcutCategory.fight\", \"closeCombatRight\")\r\n    UI.setShortcutEnabled(true, \"shortcutCategory.fight\", \"closeCombatLeft\")\r\n    prepareShortcuts(true, \"SHORTCUTBAR\")\r\n    UI.setShortcutEnabled(true, \"shortcutCategory.fight\", \"resetFightCamera\")\r\n    \r\n    --FUNCTION\r\n    function onAptitudeBonusValidated()\r\n      clearALL()\r\n      clearListener()\r\n    \r\n      --TRIGGER\r\n      Server.triggerEvent(6)\r\n    end\r\n    \r\n    function onAptitudeBonusLoaded()\r\n    \tclearUI()\r\n    \tclearListener()\r\n    \r\n    \t--LISTENER\r\n    \taddDialogUnloadListener(\"characterSheetDialog\", \"init\")\r\n    \taddDialogUnloadListener(\"aptitudeBonusDialog\", \"onCharacterSheetLoaded\")\r\n    \taddDialogEventListener(\"aptitudeBonusDialog\", \"validateCommonAptitudePoints\", \"MOUSE_CLICKED\", \"onAptitudeBonusValidated\")\r\n    \r\n    \t--EVENT\r\n    \tUI.enableEvent(\"aptitudeBonusDialog\", \"bonusList#1.increaseBonusButton\", \"MOUSE_PRESSED\", false)\r\n    \tUI.enableEvent(\"aptitudeBonusDialog\", \"bonusList#2.increaseBonusButton\", \"MOUSE_PRESSED\", false)\r\n    \tUI.enableEvent(\"aptitudeBonusDialog\", \"bonusList#3.increaseBonusButton\", \"MOUSE_PRESSED\", false)\r\n    \tUI.enableEvent(\"aptitudeBonusDialog\", \"bonusList#4.increaseBonusButton\", \"MOUSE_PRESSED\", false)\r\n    \tUI.enableEvent(\"aptitudeBonusDialog\", \"bonusList#5.increaseBonusButton\", \"MOUSE_PRESSED\", false)\r\n    \r\n    \t--PARTICLE UI\r\n    \tsetUIParticle(\"aptitudeBonusDialog\", \"bonusList#0\", apsArrow[4] .. \".xps\", 0, 0, \"EAST\")\r\n    \tsetUIParticle(\"aptitudeBonusDialog\", \"validateCommonAptitudePoints\", apsArrow[4] .. \".xps\", 0, 0, \"EAST\")\r\n    end\r\n    \r\n    function onCharacterSheetLoaded()\r\n    \tclearUI()\r\n    \tclearListener()\r\n    \r\n    \t--LISTENER\r\n    \taddDialogUnloadListener(\"characterSheetDialog\", \"init\")\r\n    \taddDialogLoadListener(\"aptitudeBonusDialog\", \"onAptitudeBonusLoaded\")\r\n    \r\n    \t--PARTICLE UI\r\n    \tsetUIParticle(\"characterSheetDialog\", \"openAptitudesButton\", apsArrow[4] .. \".xps\", 0, 0, \"EAST\")\r\n    end\r\n    \r\n    function init()\r\n    \tclearUI()\r\n    \tclearListener()\r\n    \r\n    \t--LISTENER\r\n    \taddDialogLoadListener(\"characterSheetDialog\", \"onCharacterSheetLoaded\")\r\n    \r\n    \t--PARTICLE UI\r\n    \tsetUIParticle(\"worldAndFightBarDialog\", \"fightInfoBtn\", apsArrow[2] .. \".xps\", 0, 0, \"NORTH\")\r\n    end\r\n    \r\n    --SHORTCUTS\r\n    UI.setShortcutEnabled(true, \"shortcutCategory.interface\", \"characterBook\")\r\n    \r\n    --VISIBILITY UI\r\n    setWidgetVisible(\"worldAndFightBarDialog\", \"fightInfoBtn\", true)\r\n    \r\n    init()\nend\n\n-- 6 - 2 - TRIG(6) ; Fin\n-- \nfunction event_2114_16970(otomaiMobileId)\n    trace(\"TUTO 6 - STEP 2\")\r\n    clearALL()\r\n    clearListener()\nend\n\n-- 7 - 0 - TRIG(6) + TRIG(1) ; Parler à Otomaï\n-- \nfunction event_2114_16971(otomaiMobileId)\n    trace(\"TUTO 7 - STEP 0\")\r\n    clearALL()\r\n    \r\n    --SHORTCUTS des étapes précédentes\r\n    UI.setShortcutEnabled(true, \"shortcutCategory.fight\", \"endPlacementAndTurn\")\r\n    UI.setShortcutEnabled(true, \"shortcutCategory.fight\", \"closeCombatRight\")\r\n    UI.setShortcutEnabled(true, \"shortcutCategory.fight\", \"closeCombatLeft\")\r\n    UI.setShortcutEnabled(true, \"shortcutCategory.interface\", \"characterBook\")\r\n    prepareShortcuts(true, \"SHORTCUTBAR\")\r\n    UI.setShortcutEnabled(true, \"shortcutCategory.fight\", \"resetFightCamera\")\r\n    \r\n    --VISIBILITY UI des étapes précédentes\r\n    setWidgetVisible(\"worldAndFightBarDialog\", \"fightInfoBtn\", true)\r\n    \r\n    --COMPASS WORLD\r\n    local otomaiX, otomaiY, otomaiZ = Mobile.getMobilePosition(otomaiMobileId)\r\n    \r\n    setCompass(otomaiX, otomaiY, otomaiZ)\nend\n\n-- 7 - 1 - DIALOG_EXECUTED ; Utiliser le TP\n-- \nfunction event_2114_17011(otomaiMobileId)\n    trace(\"TUTO 7 - STEP 1\")\r\n    clearALL()\r\n    \r\n    --CINEMATIQUE\r\n    local player = Context.getLeaderId()\r\n    \r\n    displayScreenEffect(true, 0, 1000, 500, 0, 0, 0, 1)\r\n    \r\n    -- Skip admin\r\n    function customSkip()\r\n    \tMobile.setMobileVisible(otomaiMobileId, false)\r\n    \ttuto()\r\n    end\r\n    \r\n    startCinematicContext(0.8, player)\r\n    if (_ADMIN) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"customSkip\") end\r\n    \r\n    invoke_custom(2000, 1, \"otomaiFly\")\r\n    \r\n    function otomaiFly()\r\n    \tsetWorldParticleTarget(apsOtomai.transform, otomaiMobileId, 0, 0)\r\n    \tMobile.setMobileAnimationSuffix(otomaiMobileId, \"-Oiseau\")\r\n    \tMobile.setMobileMovementStyle(otomaiMobileId, \"TRAJECTORY\", \"TRAJECTORY\", false)\r\n    \r\n    \tinvoke_custom(1000, 1, \"Mobile.addCubicSplineTweenToMobile\", otomaiMobileId, 54, -1, -53, 3000, 0, 0, 10, 0, 0, -50)\r\n    \r\n    \tinvoke_custom(5000, 1, \"tuto\")\r\n    end\r\n    \r\n    function tuto()\r\n    \t--TUTORIEL UI\r\n    \tUI.loadTutorialDialog(\"incarnam.tuto.ui.ie.interaction\", \"incarnam.tuto.ui.ie.interaction.title\", \"incarnam.tuto.ui.ie.interaction.infos\")\r\n    \r\n    \t--COMPASS WORLD\r\n    \tsetCompass(34, 0, -33)\r\n    \r\n    \tstopCinematicContext(1, player, true)\r\n    end\r\n    \r\nend\n\n-- 7 - 2 - IE_ACTIVATED ; Fin\n-- \nfunction event_2114_17018(otomaiMobileId)\n    trace(\"TUTO 7 - STEP 2\")\r\n    clearALL()\nend\n\n-- [INIT] ENTER_INSTANCE (ADMIN)\n-- \nfunction event_2114_21461()\n    _ADMIN = true\nend\n\n","functions":["tContains","prepareChatUI","prepareFollowQuestUI","prepareUI","prepareShortcuts","setWidgetVisible","clearWidgetVisible","setWidgetEnable","clearWidgetEnable","setUIColorTween","clearUIColorTweens","setUIParticle","setUIParticleBorder","clearUIParticles","addDialogLoadListener","clearDialogLoadListener","addDialogUnloadListener","clearDialogUnloadListener","addDialogEventListener","clearDialogEventListener","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","bubble","clearBubbles","setCompass","clearCompasses","createActor","clearActors","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","startCinematicContext","skipCinematic","stopCinematicContext","displayScreenEffect","clearALL","clearUI","clearListener","onInstanceLoaded","event_2114_17253","event_2114_17031","event_2114_17259","clearTurnButtonParticle","event_2114_16938","event_2114_16934","event_2114_17234","onVideoEnd","event_2114_16942","customSkip","otomaiFightStasisFirst","otomaiFightStasisSecond","addWakfuTreeLeaves","playerSpawn","wipeMobs","otomaiPlayer","startTransition","event_2114_16928","event_2114_16930","tuto","event_2114_16932","tuto","event_2114_16935","event_2114_16936","event_2114_16937","onSpellSelected","event_2114_16939","event_2114_16940","event_2114_16941","customSkip","endMove","event_2114_16966","event_2114_16943","customSkip","monsterEggFall","monsterMove","monsterEatStasis","otomaiReaction","tuto","event_2114_16944","tuto","event_2114_16945","onFocusButtonClicked","event_2114_16946","onFightResultUnloaded","onFightResultLoaded","event_2114_16948","customSkip","otomaiReac","event_2114_16949","event_2114_16950","event_2114_16981","onOrientationClicked","getButtonToFaceMonster","init","onPathEnded","onTurnStarted","event_2114_16951","onFighterDescriptionUnloaded","onFighterDescriptionLoaded","setFocus","event_2114_16954","event_2114_16968","event_2114_16953","customSkip","event_2114_16955","event_2114_16956","event_2114_16957","event_2114_16958","customSkip","endMoveMelee","endMoveRange","event_2114_16960","event_2114_16961","event_2114_16962","event_2114_16963","onFightResultUnloaded","onFightResultLoaded","event_2114_16969","customSkip","endMove","event_2114_16964","onAptitudeBonusValidated","onAptitudeBonusLoaded","onCharacterSheetLoaded","init","event_2114_16970","event_2114_16971","event_2114_17011","customSkip","otomaiFly","tuto","event_2114_17018","event_2114_21461"],"quest_calls":[],"dialogue_calls":[]},"scenario/2115.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n-- TRIGGER CLIENT --\r\n-- 0 = Fin cinématique VIDEO | Déclenché par le callback Video.addVideoStopOrEndCallback\r\n-- 1 = Arrivée dans l'instance | Déclenché par onInstanceLoaded() callback par Event.runOnInstanceLoaded (cf code Global)\r\n-- 2 = Fin cinématique | Déclenché par stopCinematicContext() (cf code Global)\r\n-- 3 = Fermeture UI Fin de combat\r\n-- 4 = Clic sur le bon bouton de changement d'oriention (parmis les 4) dans UI worldAndFightBar pour s'orientation vers le monstre\r\n-- 5 = Fermeture UI Fiche combattant\r\n-- 6 = Clic sur le bouton de validation de la répartition dans UI Aptitudes\r\n-- 7 = Clic sur la boussole du bon objectif dans l'UI suivi de quête\r\n-- 8 = Fermeture UI Map Monde\r\n\r\n-- VARIABLE GLOBALE - SCRIPT --\r\n\r\nwidget_visible = {}\r\nwidget_enable = {}\r\nui_tweens = {}\r\nui_particles = {}\r\nui_listener_load = {}\r\nui_listener_unload = {}\r\nui_listener_event = {}\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\nscreenEffectId = nil\r\n\r\n-- VARIABLE GLOBALE - MOBILE CINEMATIQUE & TUTO --\r\n\r\nANM_otomai = {think=\"AnimComp-Special03\", talk=\"AnimComp-Special04-Debut\", show=\"AnimComp-Special05-Debut\", nice=\"AnimComp-Special07\", nope=\"AnimComp-Special08\", lol=\"AnimComp-Special09\", stop_it=\"AnimComp-Special10\", come_here=\"AnimComp-Special01\", wave_hit=\"AnimComp-Special02\", fly=\"AnimStatique-Oiseau\", cast=\"AnimSort-01\", supercast=\"AnimComp-Special11\", attack=\"AnimSort-Cast\", balance=\"AnimComp-Special06\"}\r\nANM_melee = {attack=\"AnimSort-Morsure\", glitch1=\"AnimComp-Glitch01\", glitch2=\"AnimComp-Glitch02\", glitch3=\"AnimComp-Glitch03\", roar=\"AnimComp-Agressif\"}\r\nANM_range = {attack=\"AnimSort-01\", glitch=\"AnimComp-Glitch\", dupli=\"AnimComp-Dupli\"}\r\nANM_boss = {attack1=\"AnimSort-Estoc\", attack2=\"AnimSort-Hrargh\", glitch=\"AnimComp-Glitch\", dupli=\"AnimComp-Dupli\", roar=\"AnimComp-Hurle\", ko = \"AnimKO-SortieOK\", death= \"AnimKO-SortieHS\"}\r\n\r\nNPC_otomai = Mobile.generateClientMobileId()\r\nNPC_otomai_gfx = 181404009\r\nNPC_otomai_particleZ = 10\r\nNPC_otomai_bubbleX = 10\r\nNPC_otomai_bubbleY = 70\r\n\r\nNPC_melee = Mobile.generateClientMobileId()\r\nNPC_meleeB = Mobile.generateClientMobileId()\r\nNPC_melee_gfx = 181404014\r\nNPC_melee_particleZ = 5\r\n\r\nNPC_range = Mobile.generateClientMobileId()\r\nNPC_range_gfx = 181404015\r\nNPC_range_particleZ = 3\r\n\r\nNPC_boss = Mobile.generateClientMobileId()\r\nNPC_boss_gfx = 181404012\r\nNPC_boss_particleZ = 8\r\n\r\nNPC_eni_wakfu = Mobile.generateClientMobileId()\r\nNPC_eni_wakfu_gfx = 181404034\r\nNPC_eni_wakfu_particleZ = 7\r\n\r\nNPC_eni_stasis = Mobile.generateClientMobileId()\r\nNPC_eni_stasis_gfx = 181404013\r\nNPC_eni_stasis_particleZ = 7\r\n\r\n_ACTOR_LIST = {NPC_otomai, NPC_melee, NPC_meleeB, NPC_range, NPC_boss, NPC_eni_wakfu, NPC_eni_stasis}\r\n\r\n-- VARIABLE GLOBALE - PARTICULE CINEMATIQUE & TUTO --\r\n\r\n-- UI TUTO\r\napsArrowBig = {6001069,6001070,6001071,6001072,6001073,6001074,6001075,6001076}\r\napsArrow = {6001061,6001062,6001063,6001064,6001065,6001066,6001067,6001068}\r\napsCenter = {ap=6001090, mp=6001091, wp=6001092, hp=6001093}\r\napsFollowBorder = -1548037644\r\n-- WORLD TUTO\r\napsCell = {white_border=800578, red_border=800579, white_arrow=800576, red_arrow=800577, white=800581, red=800582, show=78900}\r\n-- CINEMATIQUE\r\napsWave = {spawn=800573, wave=800574, hit=800575}\r\napsOtomai = {shield=-1814057071, transform=-1814057072, playershield = -1814057074}\r\napsCristal = {base=71071022, react=800580, shield=71071021}\r\napsBoss = {death=-1814057073}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n    for index, value in ipairs (tab) do\r\n\t\tif isEqual(value, val) then\r\n            return true\r\n        end\r\n    end\r\n\r\n    return false\t\r\nend\r\n\r\n-- FONCTION UI -- Replace le Chat en bas à gauche et le rend indéplaçable/déplaçable\r\nfunction prepareChatUI(movable, chatOffsetX)\r\n\tif not UI.isDialogLoaded(\"chatDialog0\") then return end\r\n\t\r\n\tif (not chatOffsetX) then chatOffsetX = 0 end\r\n\t\r\n\tUI.setPosition(\"chatDialog0\", chatOffsetX, 0)\r\n\tUI.setWindowMovable(\"chatDialog0\", movable)\r\nend\r\n\r\n-- FONCTION UI -- Replace le Suivi de Quête mi-hauteur à gauche et le rend indéplaçable/déplaçable\r\nfunction prepareFollowQuestUI(movable)\r\n    local dialogName = \"\"\r\n    if UI.isDialogLoaded(\"verticalFollowedAchievementsDialog\") then\r\n        dialogName = \"verticalFollowedAchievementsDialog\"\r\n    end\r\n    if UI.isDialogLoaded(\"followedAchievementsDialog\") then\r\n        dialogName = \"followedAchievementsDialog\"\r\n    end\r\n\r\n    if (dialogName == \"\") then\r\n        return\r\n    end\r\n\r\n    local screenH, screenW = UI.getWindowSize()\r\n    local x, y = UI.getPosition(dialogName)\r\n\r\n    UI.setPosition(dialogName, x, screenH / 4)\r\n    UI.setWindowMovable(dialogName, movable)\r\nend\r\n\r\n-- FONCTION UI -- Rend Visible/Invisible certains éléments des interfaces\r\nfunction prepareUI(visible)\r\n  --Interface Boutique & Cadeau\r\n  setWidgetVisible(\"topHudDialog\", \"optionShopButton\", visible)\r\n  setWidgetVisible(\"topHudDialog\", \"giftButton\", visible)\r\n\r\n  --UI sous le Coeur\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"wakfuStasisBar\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"xpBar\", visible)\r\n\r\n  --Boutons hors combat à droite du Coeur\r\n  setWidgetVisible(\"shortcutBarDialog\", \"previousButton\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"nextButton\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseShortcutBar1\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseShortcutBar2\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseShortcutBar3\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseShortcutBar4\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"shortcutBarItemButton\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"shortcutBarSpellButton\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseButtonContainerForTuto1\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseButtonContainerForTuto2\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseButtonContainerForTuto3\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseButtonContainerForTuto4\", visible)\r\n\r\n  --Boutons hors combat à gauche de l'écran - barre d'interfaces\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"firstInterfaceBarBackground\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"secondInterfaceBarBackground\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"extraInterfaceBarDrawerButton\", visible)\r\n\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"fightInfoBtn\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"inventoryButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"buildSheetSetButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"craftButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"questsButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"dungeonButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"cosmeticsButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"tutorialBookButton\", visible)\r\n\r\n  --Boutons hors combat à gauche de l'écran - barre d'interfaces (deuxième barre)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"contactListButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"guildButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"companionsButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"nationButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"battlegroundButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"passportButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"emoteButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"encyclopediaButton\", visible)\r\n\r\n  --Boutons hors combat \"actions rapides\"\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"OverWorldActionsBackground\", visible)\r\n\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"dimensionalBagButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"mapButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"rideMountButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"miniMapButton\", visible)\r\n\r\n  --Boutons en combat à gauche du Coeur\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"FightActionsBackground\", visible)\r\n\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"giveUpButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"hideFightersButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"tacticalModeBtn\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"reportCellBtn\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"fightMarkerBtn\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"lockFightBtn\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"resistanceOverheadBtn\", visible)\r\nend\r\n\r\n-- FONCTION SHORTCUT -- Rend Actif/Inactif certains raccourcis\r\nfunction prepareShortcuts(enabled, shortcutType)\r\n  if not shortcutType or shortcutType == \"WORLD\" then\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.world\", \"enterLeaveBag\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.world\", \"switchHero0\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.world\", \"switchHero1\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.world\", \"switchHero2\")\r\n  end\r\n  if not shortcutType or shortcutType == \"DISPLAY\" then\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"zoomIn\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"zoomOut\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"closeWindows\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"setLODLevel\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"setFightLODLevel\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"showHideNameOverheadsCommand\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"hideFightOccluders\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"alphaMask\")\r\n  end\r\n  if not shortcutType or shortcutType == \"CHAT\" then\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.chat\", \"chat\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.chat\", \"lastContact\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.chat\", \"firstContact\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.chat\", \"autoCompletePlayerName\")\r\n    for bind=1, 9, 1 do\r\n      UI.setShortcutEnabled(enabled, \"shortcutCategory.shortcutBar\", \"bind\" .. toString(bind))\r\n    end\r\n  end\r\n\r\n  if not shortcutType or shortcutType == \"FIGHT\" then\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"fighterTransparency\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"switchTacticalView\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"nextSelectedFighter\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"giveUp\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"lockFight\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"reportCell\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"callHelp\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"displayHpBar\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"resetFightCamera\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"endPlacementAndTurn\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"closeCombatRight\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"closeCombatLeft\")\r\n  end\r\n  if not shortcutType or shortcutType == \"INTERFACE\" then\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"minimap\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"contactList\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"companionManagement\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"guild\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"craft\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"dungeonList\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"achievements\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"quests\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"emotes\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"ecosystem\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"climate\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"nation\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"partySearch\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"passport\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"almanax\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"tutorialBook\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"switchToDirectAttackCommand\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"map\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"spellsInventory\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"inventory\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"characterBook\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"osamodasSymbiot\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"shortcutBar0\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"shortcutBar1\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"shortcutBar2\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"shortcutBar3\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"additionalShortcutBar0\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"additionalShortcutBar1\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"additionalShortcutBar2\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"additionalShortcutBar3\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"changeShortcutBarType\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"downscaling\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"rewards\")\r\n\tUI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"battlegroundList\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"aptitudes\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"presets\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"encyclopedia\")\r\n  end\r\n\r\n  -- On ne bloque pas les raccourcis de sorts finalement\r\n--   if not shortcutType or shortcutType == \"SHORTCUTBAR\" then\r\n--     for bar=0,3, 1 do\r\n--       for slot=0, 9, 1 do\r\n--         UI.setShortcutEnabled(enabled, \"shortcutCategory.shortcutBar\", \"shortcut\" .. toString(bar) .. toString(slot))\r\n--       end\r\n--     end\r\n--   end\r\nend\r\n\r\n-- FONCTION UI -- Rend Visible/Invisible un élément d'une interface\r\nfunction setWidgetVisible(dialogName, widgetName, visible)\r\n  if not UI.isDialogLoaded(dialogName) then return end\r\n\r\n  UI.setWidgetVisibility(dialogName, widgetName, visible)\r\n  table.insert(widget_visible, { name = dialogName, id = widgetName, state = visible })\r\nend\r\n\r\nfunction clearWidgetVisible()\r\n  local str = \"\"\r\n  for i=#widget_visible, 1, -1 do\r\n    str = str .. toString(widget_visible[i].name) .. \"@\" .. toString(widget_visible[i].id) .. \";\"\r\n    UI.setWidgetVisibility(widget_visible[i].name, widget_visible[i].id, true)\r\n  end\r\n\r\n  widget_visible = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearWidgetVisible\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Rend Actif/Inactif un élément d'une interface\r\nfunction setWidgetEnable(dialogName, widgetName, enable)\r\n  if not UI.isDialogLoaded(dialogName) then return end\r\n\r\n  UI.setWidgetEnabled(dialogName, widgetName, enable)\r\n  table.insert(widget_enable, {name = dialogName, id = widgetName, state = enable})\r\nend\r\n\r\nfunction clearWidgetEnable()\r\n  local str = \"\"\r\n  for i=#widget_enable, 1, -1 do\r\n    str = str .. toString(widget_enable[i].name) .. \"@\" .. toString(widget_enable[i].id) .. \";\"\r\n    UI.setWidgetEnabled(widget_enable[i].name, widget_enable[i].id, true)\r\n  end\r\n\r\n  widget_enable = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearWidgetEnable\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Ajoute/Retire une TweenParticle à un élément d'une interface\r\nfunction setUIColorTween(dialogName, widgetName, duration, loop, r1, g1, b1, a1, r2, g2, b2, a2)\r\n  if not UI.isDialogLoaded(dialogName) then return end\r\n\r\n  UI.addColorTween(dialogName, widgetName, duration, loop, r1, g1, b1, a1, r2, g2, b2, a2)\r\n  table.insert(ui_tweens, {name = dialogName, id = widgetName})\r\nend\r\n\r\nfunction clearUIColorTweens(dialogName, widgetName)\r\n  local str = \"\"\r\n  for i=#ui_tweens, 1, -1 do\r\n    if ((not dialogName) or (dialogName == ui_tweens[i].name)) and ((not widgetName) or (widgetName == ui_tweens[i].id)) then\r\n      str = str .. toString(ui_tweens[i].name) .. \"@\" .. toString(ui_tweens[i].id) .. \";\"\r\n      UI.removeColorTween(ui_tweens[i].name, ui_tweens[i].id)\r\n      table.remove(ui_tweens, i)\r\n    end\r\n  end\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearUIColorTweens\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Ajoute/Retire une Particle à un élément d'une interface\r\nfunction setUIParticle(dialogName, widgetName, apsFileName, x, y, alignment, level)\r\n  if not UI.isDialogLoaded(dialogName) then return end\r\n\r\n  local particleId = UI.addParticle(dialogName, widgetName, apsFileName, x, y, alignment, level)\r\n  table.insert(ui_particles, {name = dialogName, id = widgetName})\r\n\r\n  return particleId\r\nend\r\n\r\nfunction setUIParticleBorder(dialogName, widgetName, apsFileName, x, y, alignment, level, speed)\r\n  if not UI.isDialogLoaded(dialogName) then return end\r\n\r\n  local particleId = UI.addParticleToBorder(dialogName, widgetName, apsFileName, x, y, alignment, level, speed)\r\n  table.insert(ui_particles, {name = dialogName, id = widgetName})\r\n\r\n  return particleId\r\nend\r\n\r\nfunction clearUIParticles(dialogName, widgetName)\r\n  local str = \"\"\r\n  for i=#ui_particles, 1, -1 do\r\n    if ((not dialogName) or (dialogName == ui_particles[i].name)) and ((not widgetName) or (widgetName == ui_particles[i].id)) then\r\n      str = str .. toString(ui_particles[i].name) .. \"@\" .. toString(ui_particles[i].id) .. \";\"\r\n      UI.clearParticles(ui_particles[i].name, ui_particles[i].id)\r\n      table.remove(ui_particles, i)\r\n    end\r\n  end\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearUIParticles\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Enregistre/Supprime un callback à l'ouverture d'une interface\r\nfunction addDialogLoadListener(dialog, funcName, ...)\r\n  UI.addDialogLoadedListener(dialog, funcName, unpack(arg))\r\n  table.insert(ui_listener_load,  dialog)\r\nend\r\n\r\nfunction clearDialogLoadListener(dialogName)\r\n  local str = \"\"\r\n  for i=#ui_listener_load, 1, -1 do\r\n    if (not dialogName) or (dialogName == ui_listener_load[i]) then\r\n      str = str .. toString(ui_listener_load[i]) .. \";\"\r\n      UI.removeDialogLoadedListener(ui_listener_load[i])\r\n      table.remove(ui_listener_load, i)\r\n    end\r\n  end\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearDialogLoadListener\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Enregistre/Supprime un callback à la fermeture d'une interface\r\nfunction addDialogUnloadListener(dialog, funcName, ...)\r\n  UI.addDialogUnloadedListener(dialog, funcName, unpack(arg))\r\n  table.insert(ui_listener_unload, dialog)\r\nend\r\n\r\nfunction clearDialogUnloadListener(dialogName)\r\n  local str = \"\"\r\n  for i=#ui_listener_unload, 1, -1 do\r\n    if (not dialogName) or (dialogName == ui_listener_unload[i]) then\r\n      str = str .. toString(ui_listener_unload[i]) .. \";\"\r\n      UI.removeDialogUnloadedListener(ui_listener_unload[i])\r\n      table.remove(ui_listener_unload, i)\r\n    end\r\n  end\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearDialogUnloadListener\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Enregistre/Supprime un callback sur un élément d'une interface\r\nfunction addDialogEventListener(dialog, id, eventType, funcName, ...)\r\n  if not UI.isDialogLoaded(dialog) then return end\r\n\r\n  UI.addEventListener(dialog, id, eventType, funcName, unpack(arg))\r\n  table.insert(ui_listener_event, {dialog=dialog, id=id, eventType=eventType, funcName=funcName})\r\nend\r\n\r\nfunction clearDialogEventListener(dialogName)\r\n  local str = \"\"\r\n  for i=#ui_listener_event, 1, -1 do\r\n    if (not dialogName) or (dialogName == ui_listener_event[i].dialog) then\r\n      str = str .. toString(ui_listener_event[i].dialog) .. \"@\" .. toString(ui_listener_event[i].id) .. \";\"\r\n      UI.removeEventListener(ui_listener_event[i].dialog, ui_listener_event[i].id, ui_listener_event[i].eventType, ui_listener_event[i].funcName)\r\n      table.remove(ui_listener_event, i)\r\n    end\r\n  end\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearDialogEventListener\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y , z, ...)\r\n  local particleId = Particle.addParticleSystem(particleFileId, x, y , z, unpack(arg))\r\n  table.insert(world_particles, particleId)\r\n\r\n  return particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n  local particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n  table.insert(world_particles, particleId)\r\n\r\n  return particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n  local str = \"\"\r\n  for i=#world_particles, 1, -1 do\r\n    str = str .. toString(world_particles[i]) .. \";\"\r\n    Particle.removeParticleSystem(world_particles[i])\r\n  end\r\n\r\n  world_particles = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n  BubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n  if isLower(mobileId, 0) then\r\n    BubbleText.setCharacterSpeak(mobileId, text)\r\n  else\r\n    if (not offsetY) then\r\n      local height = Mobile.getMobileHeight(mobileId)\r\n      if (not height) then height = 6 end\r\n\r\n      offsetY = height * 10\r\n    end\r\n\r\n    if (not offsetX) then offsetX = 0 end\r\n    if (not infiniteDuration) then infiniteDuration = false end\r\n\r\n    BubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n    UI.writeLocalisedInChat(text)\r\n  end\r\n\r\n  if (not tContains(bubbles, mobileId)) then\r\n    table.insert(bubbles, mobileId)\r\n  end\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n  local str = \"\"\r\n  for i = #bubbles, 1, -1 do\r\n    if (not mobileId) then\r\n      str = str .. toString(bubbles[i]) .. \";\"\r\n      BubbleText.closeBubbleAttachedTo(bubbles[i])\r\n    elseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n      str = str .. toString(bubbles[i]) .. \";\"\r\n      BubbleText.closeBubbleAttachedTo(bubbles[i])\r\n      table.remove(bubbles, i)\r\n    end\r\n  end\r\n\r\n  if (not mobileId) then bubbles = {} end\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n  local compassId = UI.addCompass(\"compass\", x, y, z)\r\n  table.insert(compasses, compassId)\r\n\r\n  return compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n  local str = \"\"\r\n  for i=#compasses, 1, -1 do\r\n    str = str .. toString(compasses[i]) .. \";\"\r\n    UI.removeCompass(compasses[i])\r\n  end\r\n\r\n  compasses = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height)\r\n  local mobileId = Mobile.generateClientMobileId()\r\n  Actor.createActor(mobileId, spriteName, worldX, worldY, worldZ, availableDirection)\r\n\r\n  if (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n  if (height) then Actor.setActorHeight(mobileId, height) end\r\n\r\n  table.insert(actors, mobileId)\r\n\r\n  return mobileId\r\nend\r\n\r\nfunction clearActors()\r\n  local str = \"\"\r\n  for i = #actors, 1, -1 do\r\n    str = str .. toString(actors[i]) .. \";\"\r\n    Actor.deleteActor(actors[i])\r\n  end\r\n\r\n  actors = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n  local taskId = invoke(delay, count, funcName, unpack(arg))\r\n  table.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n  local str = \"\"\r\n  for i=#invoke_tasks, 1, -1 do\r\n    str = str .. toString(invoke_tasks[i]) .. \";\"\r\n    interrupt(invoke_tasks[i])\r\n    desinvoke(invoke_tasks[i])\r\n  end\r\n\r\n  invoke_tasks = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n  invoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n  local taskId = setInterval(delay, funcName, unpack(arg))\r\n  table.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n  local str = \"\"\r\n  for i=#interval_tasks, 1, -1 do\r\n    str = str .. toString(interval_tasks[i]) .. \";\"\r\n    interrupt(interval_tasks[i])\r\n    desinvoke(interval_tasks[i])\r\n  end\r\n\r\n  interval_tasks = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n  if (_DEBUG) then trace(\"startCinematicContext\") end\r\n\r\n  UI.manageFrame(\"World\", false)\r\n  UI.closeMRU()\r\n  UI.closeAllBags()\r\n  UI.setUIVisible(false)\r\n  UI.displayWideScreenBand(true)\r\n  Camera.setUserZoomLocked(true)\r\n\r\n  if (cameraMobileId ~= nil)  then\r\n    Camera.setMoveSpeedFactor(10000)\r\n    Camera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n  end\r\n\r\n  if (zoomFactor ~= nil)  then\r\n    Camera.setZoomFactor(zoomFactor)\r\n  end\r\n\r\n  if (musicId ~= nil)  then\r\n    Sound.playForcedMusic(musicId)\r\n  end\r\n\r\n  if (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\nfunction skipCinematic()\r\n  local player = Context.getLeaderId()\r\n\r\n  for x = 1, #_ACTOR_LIST do\r\n    Actor.deleteActor(_ACTOR_LIST[x])\r\n  end\r\n\r\n  UI.hideButton()\r\n  clearALL()\r\n  stopCinematicContext(1, player, true)\r\n  Mobile.setMobileVisible(player, true)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n  if (_DEBUG) then trace(\"stopCinematicContext\") end\r\n\r\n  UI.displayWideScreenBand(false)\r\n  UI.setUIVisible(true)\r\n  Camera.setUserZoomLocked(false)\r\n  UI.manageFrame(\"World\", true)\r\n\r\n  Camera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n  Camera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n  if (zoomFactor ~= nil) then\r\n    Camera.setZoomFactor(zoomFactor)\r\n  end\r\n\r\n  if (cameraMobileId ~= nil) then\r\n    Camera.attachCameraToMobile(cameraMobileId)\r\n  end\r\n\r\n  if (stopMusic) then\r\n    Sound.stopForcedMusic()\r\n  end\r\n\r\n  if (_DEBUG) then\r\n    UI.hideButton()\r\n  end\r\n\r\n  --TRIGGER\r\n  Server.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Affiche/Masque une texture à l'écran\r\nfunction displayScreenEffect(enable, fadeInDur, alphaDur, fadeOutDur, r, g, b, alpha)\r\n  if (_DEBUG) then trace(\"displayScreenEffect\") end\r\n\r\n  if not enable and screenEffectId ~= nil  then\r\n    --On retire le blackScreen\r\n    Effect.stopEffect(screenEffectId)\r\n  else\r\n    --On affiche un blackScreen à l'entrée dans l'instance le temps qu'elle soit complètement chargée\r\n    screenEffectId = Effect.createFullScreenSprite(fadeInDur, alphaDur, fadeOutDur, r, g, b, alpha)\r\n  end\r\nend\r\n\r\n-- FONCTION NETTOYAGE --\r\nfunction clearALL()\r\n  clearIntervalTasks()\r\n  clearInvokeTasks()\r\n  clearBubbles()\r\n  clearUIColorTweens()\r\n  clearUIParticles()\r\n  clearWorldParticles()\r\n  clearCompasses()\r\n  clearActors()\r\n\r\n  Focus.display(false)\r\n  UI.unloadTutorialDialog()\r\nend\r\n\r\n-- FONCTION NETTOYAGE --\r\nfunction clearUI(dialogName)\r\n  clearUIColorTweens(dialogName)\r\n  clearUIParticles(dialogName)\r\nend\r\n\r\n-- FONCTION NETTOYAGE --\r\nfunction clearListener(dialogName)\r\n  clearDialogLoadListener(dialogName)\r\n  clearDialogUnloadListener(dialogName)\r\n  clearDialogEventListener(dialogName)\r\nend\r\n\r\nUI.setPropertyBooleanValue(\"hideDownscaling\", true)\r\nsetWidgetVisible(\"systemBarDialog\", \"boosterPackContainer\", false)\n\n-- Le joueur quitte l'instance\n-- \nfunction event_2115_17067()\n    clearALL()\nend\n\n-- [INIT] ENTER_INSTANCE (ADMIN)\n-- \nfunction event_2115_21463()\n    _ADMIN = true\nend\n\n-- [INIT] Serveur\n-- \nfunction event_2115_17141()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2115_16974(PorteUn, PorteDeux, PorteTrois)\n    -- On récupère les ID des portes\r\n    DoorOne = toLong(PorteUn)\r\n    DoorTwo = toLong(PorteDeux)\r\n    DoorThree = toLong(PorteTrois)\r\n    -- On met les portes dans le bon état\r\n    \r\n    if DoorOne==0 then\r\n    \tWorld.setPictoAlpha(0, -18, 5, 1, 1)\r\n    \tWorld.setPictoAlpha(1, -18, 5, 1, 1)\r\n    \tWorld.setPictoAlpha(2, -18, 5, 1, 1)\r\n    elseif DoorOne==1 then\r\n    \tWorld.setPictoAlpha(0, -18, 5, 0, 1)\r\n    \tWorld.setPictoAlpha(1, -18, 5, 0, 1)\r\n    \tWorld.setPictoAlpha(2, -18, 5, 0, 1)\r\n    end\r\n    \r\n    if DoorTwo==0 then\r\n    \tWorld.setPictoAlpha(10, -36, 13, 1, 1)\r\n    \tWorld.setPictoAlpha(11, -36, 13, 1, 1)\r\n    \tWorld.setPictoAlpha(12, -36, 13, 1, 1)\r\n    elseif DoorTwo==1 then\r\n    \tWorld.setPictoAlpha(10, -36, 13, 0, 1)\r\n    \tWorld.setPictoAlpha(11, -36, 13, 0, 1)\r\n    \tWorld.setPictoAlpha(12, -36, 13, 0, 1)\r\n    end\r\n    \r\n    if DoorThree==0 then\r\n    \tWorld.setPictoAlpha(0, -57, 21, 1, 1)\r\n    \tWorld.setPictoAlpha(-1, -57, 21, 1, 1)\r\n    \tWorld.setPictoAlpha(-2, -57, 21, 1, 1)\r\n    elseif DoorThree==1 then\r\n    \tWorld.setPictoAlpha(0, -57, 21, 0, 1)\r\n    \tWorld.setPictoAlpha(-1, -57, 21, 0, 1)\r\n    \tWorld.setPictoAlpha(-2, -57, 21, 0, 1)\r\n    end\nend\n\n-- [CINE] 1 - Entrée dans l'instance\n-- On est obligé d'avoir un évènement qui proc après l'évènement qui inscrit le joueur au scénario pour pouvoir lui initaliser des variables locales\nfunction event_2115_17226(USER_GROUP_otomai_1)\n        clearALL()\r\n        \r\n        -- CINEMATIQUE\r\n        local playerId = Context.getLeaderId()\r\n        local playerX, playerY, playerZ = Mobile.getMobilePosition(playerId)\r\n        local pos_player_dest =  {0, -5, 0}\r\n        local pos_otomai_start = {0, -7, 0}\r\n        local pos_otomai_dest = {-2, -15, 0}\r\n        \r\n        function otomaiMovementEnd(direction)\r\n        \tMobile.setMobileDirection(NPC_otomai, direction)\r\n        \tActor.deleteActor(NPC_otomai)\r\n        \tMobile.setMobileVisible(USER_GROUP_otomai_1, true)\r\n        end\r\n        \r\n        function addVignette()\r\n        \tUI.loadTutorialDialog(\"incarnam.tuto.ui.dungeon\", \"incarnam.tuto.ui.dungeon.title\", \"incarnam.tuto.ui.dungeon.infos\")\r\n        end\r\n        \r\n        -- On rend invisible les vrais actors\r\n        Mobile.setMobileVisible(USER_GROUP_otomai_1, false)\r\n        \r\n        -- On crée les faux actors\r\n        Actor.createActor(NPC_otomai, NPC_otomai_gfx, pos_otomai_start[1], pos_otomai_start[2], pos_otomai_start[3], 4)\r\n        Mobile.setMobileLookAt(NPC_otomai, playerX, playerY, false)\r\n        \r\n    \t-- Skip admin\r\n    \tfunction customSkip()\r\n    \t\tclearALL()\r\n    \t\totomaiMovementEnd(3)\r\n    \t\tstopCinematicContext(1, player , true)\r\n    \t\taddVignette()\r\n    \tend\r\n    \r\n        startCinematicContext(1.4, NPC_otomai)\r\n    \tif (_ADMIN) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"customSkip\") end\r\n    \r\n        -- On lance la cinématique personnelle\r\n        invoke_custom(00500, 1, \"Mobile.setMobileAnimation\", NPC_otomai, ANM_otomai.nice)\r\n        invoke_custom(01300, 1, \"Mobile.moveMobile\", playerId, pos_player_dest[1], pos_player_dest[2], pos_player_dest[3])\r\n        invoke_custom(03700, 1, \"Mobile.setMobileAnimation\", NPC_otomai, ANM_otomai.talk)\r\n        invoke_custom(03800, 1, \"bubble\", NPC_otomai, \"incarnam.cinematic.donjon1.0\", NPC_otomai_bubbleX, NPC_otomai_bubbleY, false)\r\n        invoke_custom(06700, 1, \"Mobile.setMobileAnimation\", NPC_otomai, ANM_otomai.think)\r\n        invoke_custom(06800, 1, \"bubble\", NPC_otomai, \"incarnam.cinematic.donjon1.1\", NPC_otomai_bubbleX, NPC_otomai_bubbleY, false)\r\n    \tinvoke_custom(11500, 1, \"Mobile.setMobileAnimation\", NPC_otomai, ANM_otomai.nope)\r\n    \tinvoke_custom(11500, 1, \"bubble\", NPC_otomai, \"incarnam.cinematic.donjon1.2\", NPC_otomai_bubbleX, NPC_otomai_bubbleY, false)\r\n    \tinvoke_custom(15400, 1, \"Mobile.setMobileDirection\", NPC_otomai, 1)\r\n    \tinvoke_custom(15600, 1, \"Mobile.setMobileDirection\", NPC_otomai, 7)\r\n    \tinvoke_custom(15500, 1, \"Mobile.setMobileAnimation\", NPC_otomai, ANM_otomai.show)\r\n    \tinvoke_custom(15500, 1, \"bubble\", NPC_otomai, \"incarnam.cinematic.donjon1.3\", NPC_otomai_bubbleX, NPC_otomai_bubbleY, false)\r\n    \tinvoke_custom(18500, 1, \"Mobile.setMobileAnimation\", NPC_otomai, ANM_otomai.talk)\r\n    \tinvoke_custom(18500, 1, \"bubble\", NPC_otomai, \"incarnam.cinematic.donjon1.4\", NPC_otomai_bubbleX, NPC_otomai_bubbleY, false)\r\n    \tinvoke_custom(23500, 1, \"Mobile.setMobileDirection\", NPC_otomai, 1)\r\n    \tinvoke_custom(23700, 1, \"Mobile.setMobileDirection\", NPC_otomai, 3)\r\n    \tinvoke_custom(23600, 1, \"Mobile.setMobileAnimation\", NPC_otomai, ANM_otomai.show)\r\n    \tinvoke_custom(23500, 1, \"bubble\", NPC_otomai, \"incarnam.cinematic.donjon1.5\", NPC_otomai_bubbleX, NPC_otomai_bubbleY, false)\r\n    \tinvoke_custom(28000, 1, \"clearBubbles\")\r\n    \tinvoke_custom(28000, 1, \"donjonDebutClose\")\r\n    \r\n    \tfunction donjonDebutClose()\r\n    \t\tMobile.setMobileDirection(NPC_otomai, 1)\r\n        \tinvoke_custom(200, 1, \"Mobile.moveMob