nction event_2115_17064(USER_GROUP_otomai_3, USER_GROUP_otomai_4)\n    clearALL()\r\n    \r\n    --CINEMATIQUE\r\n    local playerId = Context.getLeaderId()\r\n    local playerX, playerY, playerZ = Mobile.getMobilePosition(playerId)\r\n    local otomaiX, otomaiY, otomaiZ = Mobile.getMobilePosition(USER_GROUP_otomai_3)\r\n    local pos_otomai_start = {5, -50, 16}\r\n    local pos_otomai_dest = {-3, -68, 23}\r\n    local pos_otomai_dest_cristal = {-3, -63, 23}\r\n    local pos_player_dest = {-2, -68, 23}\r\n    local pos_boss = {0, -50, 16}\r\n    \r\n    function otomaiMovementEnd(direction)\r\n    \tMobile.setMobileDirection(NPC_otomai, direction)\r\n    \tActor.deleteActor(NPC_otomai)\r\n    \tMobile.setMobileVisible(USER_GROUP_otomai_4, true)\r\n    end\r\n    \r\n    -- On rend invisible les vrais actors\r\n    Mobile.setMobileVisible(USER_GROUP_otomai_3, false)\r\n    Mobile.setMobileVisible(USER_GROUP_otomai_4, false)\r\n    \r\n    -- On crée les faux actors\r\n    Actor.createActor(NPC_otomai, NPC_otomai_gfx, pos_otomai_start[1], pos_otomai_start[2], pos_otomai_start[3], 4)\r\n    Actor.createActor(NPC_boss, NPC_boss_gfx, pos_boss[1], pos_boss[2], pos_boss[3], 4)\r\n    Mobile.setMobileLookAt(NPC_otomai, playerX, playerY, false)\r\n    Mobile.setMobileLookAt(NPC_boss, otomaiX, otomaiY, false)\r\n    \r\n    -- Skip admin\r\n    function customSkip()\r\n    Mobile.setMobilePosition(playerId, -2, -68, 23)\r\n    stopCinematicContext(1, player , true)\r\n    end\r\n    \r\n    startCinematicContext(1.4, NPC_boss, 210080 )\r\n    if (_ADMIN) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"customSkip\") end\r\n    \r\n    invoke_custom(100, 1, \"Camera.attachCameraToMobile\", NPC_boss)\r\n    -- Le boss vaincu joue une disparition\r\n    invoke_custom(1300, 1, \"Mobile.setMobileAnimation\", NPC_boss, ANM_boss.roar)\r\n    invoke_custom(1300, 1, \"bubble\", NPC_boss, \"incarnam.cinematic.donjon5.0\", NPC_otomai_bubb