57, -2, -20)\r\n    \tinvoke_custom(19000, 1, \"PlayerLeaveEnd\")\r\n    end\r\n    \r\n    function PlayerLeaveEnd()\r\n    \tinvoke_custom(00100, 1, \"Mobile.setMobileAnimation\", NPC_otomai, ANM_otomai.talk)\r\n    \tinvoke_custom(00100, 1, \"bubble\", NPC_otomai, \"incarnam.cinematic.zone2.6.otomai09\", 10, 70)\r\n    \tinvoke_custom(04100, 1, \"Mobile.setMobileAnimation\", NPC_otomai, ANM_otomai.show)\r\n    \tinvoke_custom(04100, 1, \"bubble\", NPC_otomai, \"incarnam.cinematic.zone2.6.otomai10\", 10, 70)\r\n    \tinvoke_custom(08000, 1, \"Mobile.setMobileAnimation\", NPC_otomai, ANM_otomai.talk)\r\n    \tinvoke_custom(08000, 1, \"bubble\", NPC_otomai, \"incarnam.cinematic.zone2.6.otomai11\", 10, 70)\r\n    \tinvoke_custom(08500, 1, \"Mobile.setMobileDirection\", NPC_otomai, 3)\r\n    \tinvoke_custom(12000, 1, \"bubble\", NPC_otomai, \"incarnam.cinematic.zone2.6.otomai12\", 10, 70)\r\n    \tinvoke_custom(12000, 1, \"Mobile.setMobileAnimation\", NPC_otomai, ANM_otomai.think)\r\n    \tinvoke_custom(15000, 1, \"bubble\", NPC_otomai, \"incarnam.cinematic.zone2.6.otomai13\", 10, 70)\r\n    \tinvoke_custom(15000, 1, \"Mobile.setMobileAnimation\", NPC_otomai, ANM_otomai.lol)\r\n    \tinvoke_custom(18900, 1, \"bubble\", NPC_otomai, \"incarnam.cinematic.zone2.6.otomai14\", 10, 70)\r\n    \tinvoke_custom(18900, 1, \"Particle.addParticleSystem\", apsOtomai.transform, 43, 0, -40)\r\n    \tinvoke_custom(19000, 1, \"Mobile.setMobileAnimationSuffix\", NPC_otomai, \"-Oiseau\")\r\n    \tinvoke_custom(20000, 1, \"Mobile.setMobileMovementStyle\", NPC_otomai, \"TRAJECTORY\", \"TRAJECTORY\", false)\r\n    \tinvoke_custom(20500, 1, \"Mobile.setMobileDirection\", NPC_otomai, 1)\r\n    \tinvoke_custom(21500, 1, \"Mobile.addCubicSplineTweenToMobile\", NPC_otomai, 46, 0, 80, 4000,1, 0, 0, 0, 1, 5)\t\t\r\n    \t\r\n    \tinvoke_custom(23000, 1, \"stopCinematicContext\", 1, player , true)\r\n    end\nend\n\n-- [Q] TRIG(2) - TP sur Astrub à la fin de la Cinématique Finale (Q2923 OBJ 6025)\