n event_2125_17170()\n    \nend\n\n-- [Creuser] Random : Agression du joueur par groupe B+C\n-- Le joueur a 4% de se faire aggro par le groupe B+C\nfunction event_2125_17171()\n    \nend\n\n-- [Creuser] Random : Le joueur récupère du sable fin\n-- Le joueur a 30% de récupérer du sable fin\nfunction event_2125_17172()\n    \nend\n\n-- [Creuser] Random : Obtention de la première Clef\n-- Le joueur a 10% de récupérer la clef, mais seulement s'il n'était pas déjà à cette étape de quête\nfunction event_2125_17089()\n    playerId = Context.getPlayer()\r\n    \r\n    Mobile.setMobileAnimation(playerId, \"AnimEmote-Victoire\")\nend\n\n-- [Salle 1-3] Le joueur ouvre une porte\n-- \nfunction event_2125_17115()\n    \nend\n\n-- [Salle 1] Victoire\n-- \nfunction event_2125_17119()\n    \nend\n\n-- [Salle 1] Victoire - Cinématique ouverture\n-- \nfunction event_2125_17174()\n    playerId = Context.getPlayer()\r\n    zoomFactor = Camera.getZoomFactor()\r\n    zoomDuration = 4000\r\n    zoomCine = 1.4\r\n    apsDelay = 1000\r\n    apsId = 800031\r\n    interactiveElementId = 26636\r\n    doorPosition = {x=10, y=-25, z=9}\r\n    \r\n    startCinematicContext()\r\n    InteractiveElement.setState(interactiveElementId, 1)\r\n    Camera.setCamera(zoomCine, doorPosition.x, doorPosition.y, doorPosition.z)\r\n    invoke(apsDelay, 1, \"Particle.addParticleSystem\", apsId, doorPosition.x, doorPosition.y, doorPosition.z)\r\n    invoke(apsDelay + 500, 1, \"InteractiveElement.setState\", interactiveElementId, 0)\r\n    invoke(zoomDuration, 1, \"Camera.attachCameraToMobile\", playerId)\r\n    invoke(zoomDuration, 1, \"Camera.setZoomFactor\", zoomFactor)\r\n    invoke(zoomDuration, 1, \"stopCinematicContext\")\nend\n\n-- [Salle 2] Victoire\n-- \nfunction event_2125_17177()\n    \nend\n\n-- [Salle 2] Victoire - Cinématique ouverture\n-- \nfunction event_2125_17175()\n    playerId = Context.getPlayer()\r\n    zoomFactor = Camera.getZoomFactor()\r\n    zoomDuration = 4000\r\n    zoomCine = 1.4\r\n    apsDelay = 1000\r\n    apsId = 800031\r\n    interactiveElementId = 26637\r\n    doorPosition = {x=10, y=-50, z=17}\r\n    \r\n    startCinematicContext()\r\n    InteractiveElement.setState(interactiveElementId, 1)\r\n    Camera.setCamera(zoomCine, doorPosition.x, doorPosition.y, doorPosition.z)\r\n    invoke(apsDelay, 1, \"Particle.addParticleSystem\", apsId, doorPosition.x, doorPosition.y, doorPosition.z)\r\n    invoke(apsDelay + 500, 1, \"InteractiveElement.setState\", interactiveElementId, 0)\r\n    invoke(zoomDuration, 1, \"Camera.attachCameraToMobile\", playerId)\r\n    invoke(zoomDuration, 1, \"Camera.setZoomFactor\", zoomFactor)\r\n    invoke(zoomDuration, 1, \"stopCinematicContext\")\nend\n\n-- [Salle 3] Victoire\n-- \nfunction event_2125_17178()\n    \nend\n\n-- [Salle 3] Victoire - Cinématique ouverture\n-- \nfunction event_2125_17176()\n    playerId = Context.getPlayer()\r\n    zoomFactor = Camera.getZoomFactor()\r\n    zoomDuration = 4000\r\n    zoomCine = 1.4\r\n    apsDelay = 1000\r\n    apsId = 800031\r\n    interactiveElementId = 26635\r\n    doorPosition = {x=-5, y=-25, z=9}\r\n    \r\n    startCinematicContext()\r\n    InteractiveElement.setState(interactiveElementId, 1)\r\n    Camera.setCamera(zoomCine, doorPosition.x, doorPosition.y, doorPosition.z)\r\n    invoke(apsDelay, 1, \"Particle.addParticleSystem\", apsId, doorPosition.x, doorPosition.y, doorPosition.z)\r\n    invoke(apsDelay + 500, 1, \"InteractiveElement.setState\", interactiveElementId, 0)\r\n    invoke(zoomDuration, 1, \"Camera.attachCameraToMobile\", playerId)\r\n    invoke(zoomDuration, 1, \"Camera.setZoomFactor\", zoomFactor)\r\n    invoke(zoomDuration, 1, \"stopCinematicContext\")\nend\n\n-- [Salle 1-3] Victoire des 3 salles\n-- \nfunction event_2125_17179()\n    \nend\n\n-- [Salle 1-3] Victoire des 3 salles - Cinématique ouverture\n-- \nfunction event_2125_17180()\n    playerId = Context.getPlayer()\r\n    zoomFactor = Camera.getZoomFactor()\r\n    zoomDuration = 4000\r\n    