03 - Un joueur réussit la quête répétable des sas\n-- \nfunction event_2148_17791()\n    \nend\n\n-- [EVENT] normalisation counter indice guards 3 sub\n-- \nfunction event_2148_17813(indicPayed, guardFactor, kamaFactor)\n    trace(\"===normalisation indic guard payed 3 sub===\",indicPayed, \" === guard :\", guardFactor, \"  === kamafactor : \",kamaFactor)\nend\n\n-- [EVENT] normalisation counter indice guards 4 sup\n-- \nfunction event_2148_17795(indicPayed, guardFactor, kamaFactor)\n    trace(\"===normalisation indic guard payed 4 sup===\",indicPayed, \" === guard :\", guardFactor, \"  === kamafactor : \",kamaFactor)\nend\n\n-- [EVENT] definition counter info croustillante\n-- \nfunction event_2148_17796()\n    trace(\"====passage dans info croustillante====\")\nend\n\n-- [EVENT] Money spent indic\n-- \nfunction event_2148_17797(nbKamasDial, baseKama, kamaFactor, guardFactor, factor)\n    local kamasyolo = toLong(nbKamasDial)\r\n    local normfactor = toLong(factor)\r\n    trace ( \"====== money spent =====\", kamasyolo, \" === facteur normalisé ===\",  normfactor)\nend\n\n-- [EVENT] Raklur - Last stand\n-- \nfunction event_2148_17888(monsterIdThree, sasRunning, raklurId)\n    local raklurId = toLong(raklurId)\r\n    local playerId = Context.getLeaderId() \r\n    x,y,z = Mobile.getMobilePosition(playerId)\r\n    \r\n    RaklurHit(raklurId,x, y, z)\nend\n\n-- [EVENT] Raklur - Last stand (finish)\n-- \nfunction event_2148_17889(monsterIdThree, sasRunning, raklurId)\n    \nend\n\n-- [BOUCLE][COMP] Comportement des PNJ\n-- \nfunction event_2148_17890(Pervers, Guard, Worker, Beggar, Rogue, WorkerOne, WorkerTwo, PerversTwo, WorkerThree)\n    local pos_Pervers_One = {-31, 11, 2}\r\n    local pos_Pervers_Two = {-31, 12, 0}\r\n    \r\n    local anims_voyeur = {\"AnimEmote-Lunette-Boucle01\", \"AnimEmote-Lunette-Boucle02\", \"AnimEmote-Lunette-Boucle03\"}\r\n    local anims_peur = {\"AnimEmote-Effrayee\", \"AnimEmote-Help\", \"AnimEmote-Defaite\", \"AnimEmote-Chercher\"}\r\n    local anims_fenetre = {\"AnimEmote-Effrayee\", \"AnimEmote-CacherYeux-Debut\", \"AnimEmote-Defaite\", \"AnimEmote-Vomis\"}\r\n    local rand_Dir = {1, 3, 5}\r\n    \r\n    \r\n    -- Pervers\r\n    \r\n    invoke(2000, 1, \"Mobile.moveMobile\", Pervers, pos_Pervers_Two[1], pos_Pervers_Two[2], pos_Pervers_Two[3], \"Mobile.setMobileDirection\", Pervers, 1)\r\n    invoke(3000, 1, \"Mobile.setMobileAnimation\", Pervers, \"AnimEmote-Lunette-Debut\")\r\n    invoke(4100, 1, \"Mobile.setMobileAnimation\", Pervers, anims_voyeur[random(1, 3)])\r\n    invoke(5300, 1, \"Mobile.setMobileAnimation\", Pervers, anims_voyeur[random(1, 4)])\r\n    invoke(6500, 1, \"Mobile.setMobileAnimation\", Pervers, \"AnimEmote-Lunette-Fin\")\r\n    invoke(7200, 1, \"Mobile.setMobileAnimation\", Pervers, \"AnimEmote-EncouragerFan-Debut\")\r\n    invoke(8400, 1, \"Mobile.setMobileAnimation\", Pervers, \"AnimEmote-EncouragerFan-Boucle\")\r\n    invoke(10000, 1, \"Mobile.setMobileAnimation\", Pervers, \"AnimEmote-EncouragerFan-Fin\")\r\n    invoke(10500, 1, \"Mobile.setMobileAnimation\", Pervers, \"AnimEmoteMarket-FiletBave\")\r\n    invoke(12500, 1, \"Mobile.moveMobile\", Pervers, pos_Pervers_One[1], pos_Pervers_One[2], pos_Pervers_One[3])\r\n    invoke(14000, 1, \"Mobile.setMobileAnimation\", Pervers, \"AnimEmoteMarket-Faim\")\r\n    \r\n    -- Guard, Worker\r\n    \r\n    invoke(1000, 1, \"Mobile.setMobileAnimation\", Worker, \"AnimEmote-Acquiescer\")\r\n    invoke(2500, 1, \"Mobile.setMobileAnimation\", Guard, \"AnimSort-LuciolesFlash\")\r\n    invoke(3000, 1, \"Mobile.setMobileAnimation\", Worker, \"AnimEmote-Effrayee\")\r\n    invoke(4500, 1, \"Mobile.setMobileAnimation\", Worker, \"AnimEmote-Non\")\r\n    invoke(5000, 1, \"Mobile.setMobileAnimation\", Guard, \"AnimSort-Fouille\")\r\n    invoke(5600, 1, \"Mobile.setMobileAnimation\", Worker, \"AnimHit\")\r\n    invoke(6500, 1, \"Mobile.setMobileAnimation\", Worker, \"AnimEmote-Calmer\")\r\n    invoke(8500, 1, \"Mobile.setMobileAnimation\", Worker, \"AnimEmote-Pouce\")\r\n    invoke(10000, 1, \"Mobile.setMobileAnimation\", Guard, \"AnimSort-LuciolesFlash\")\r\n    invoke(10500, 1, \"Mobile.setMobileAnimation\", Worker, \"AnimEmote-Effrayee\")\r\n    invoke(12000, 1, \"Mobile.setMobileAnimation\", Worker, \"AnimEmoteMarket-HausseEpaules\")\r\n    invoke(12500, 1, \"Mobile.setMobileAnimation\", Guard, \"AnimSort-Fouille\")\r\n    invoke(13100, 1, \"Mobile.setMobileAnimation\", Worker, \"AnimHit\")\r\n    invoke(14000, 1, \"Mobile.setMobileAnimation\", Worker, \"AnimEmote-Calmer\")\r\n    \r\n    -- Beggar\r\n    \r\n    invoke(1000, 1, \"Mobile.setMobileDirection\", Beggar, 3)\r\n    invoke(1000, 1, \"Mobile.setMobileAnimation\", Beggar, \"AnimEmote-Mendier-Debut\")\r\n    invoke(5600, 1, \"Mobile.setMobileAnimation\", Beggar, \"AnimEmote-Mendier-Boucle\")\r\n    invoke(11000, 1, \"Mobile.setMobileDirection\", Beggar, 5)\r\n    invoke(11000, 1, \"Mobile.setMobileAnimation\", Beggar, \"AnimEmote-Loupe\")\r\n    \r\n    -- Rogue\r\n    \r\n    invoke(2000, 1, \"Mobile.setMobileDirection\", Rogue, 7)\r\n    invoke(2000, 1, \"Mobile.setMobileAnimation\", Rogue, \"AnimInteraction-Debut\")\r\n    invoke(3000, 1, \"Mobile.setMobileAnimation\", Rogue, \"AnimInteraction-Boucle\")\r\n    invoke(4500, 1, \"Mobile.setMobileAnimation\", Rogue, \"AnimInteraction-Comp\")\r\n    invoke(7500, 1, \"Mobile.setMobileAnimation\", Rogue, \"AnimInteraction-Boucle\")\r\n    invoke(9000, 1, \"Mobile.setMobileAnimation\", Rogue, \"AnimInteraction-Fin02\")\r\n    invoke(11500, 1, \"Mobile.setMobileDirection\", Rogue, 3)\r\n    invoke(12000, 1, \"Mobile.setMobileAnimation\", Rogue, \"AnimEmote-Siffler\")\r\n    \r\n    -- WorkerOne, WorkerTwo\r\n    \r\n    invoke(500, 1, \"Mobile.setMobileDirection\", WorkerOne, 1)\r\n    invoke(1000, 1, \"Mobile.setMobileAnimation\", WorkerOne, \"AnimEmote-Piece-Debut\")\r\n    invoke(2400, 1, \"Mobile.setMobileAnimation\", WorkerOne, \"AnimEmote-Piece-Boucle\")\r\n    invoke(5200, 1, \"Mobile.se