ndom(1, 5)])\r\n    invoke(7000, 1, \"Mobile.setMobileDirection\", WorkerThree, rand_Dir[random(1, 4)])\r\n    invoke(7000, 1, \"Mobile.setMobileAnimation\", WorkerThree, anims_peur[random(1, 4)])\r\n    invoke(10000, 1, \"Mobile.setMobileDirection\", WorkerThree, rand_Dir[random(1, 4)])\r\n    invoke(10000, 1, \"Mobile.setMobileAnimation\", WorkerThree, anims_peur[random(1, 5)])\r\n    invoke(13000, 1, \"Mobile.setMobileDirection\", WorkerThree, rand_Dir[random(1, 4)])\r\n    invoke(13000, 1, \"Mobile.setMobileAnimation\", WorkerThree, anims_peur[random(1, 4)])\r\nend\n\n-- [BOUCLE][COMP] Déplacement des gardes\n-- \nfunction event_2148_17894(PatrolOne, PatrolTwo)\n    local pos_PatrolOne_One = {-18, -1, 0}\r\n    local pos_PatrolOne_Two = {-18, 12, 0}\r\n    local pos_PatrolTwo_One = {-16, 12, 0}\r\n    local pos_PatrolTwo_Two = {-16, -1, 0}\r\n    \r\n    -- PatrolOne, PatrolTwo\r\n    \r\n        Mobile.setMobileMovementStyle(PatrolOne, \"WALK\", \"WALK\", false)\r\n        Mobile.setMobileMovementStyle(PatrolTwo, \"WALK\", \"WALK\", false)\r\n        invoke(1000, 1, \"Mobile.moveMobile\", PatrolOne, pos_PatrolOne_Two[1], pos_PatrolOne_Two[2], pos_PatrolOne_Two[3], \"Mobile.setMobileDirection\", PatrolOne, 5)\r\n        invoke(1000, 1, \"Mobile.moveMobile\", PatrolTwo, pos_PatrolTwo_Two[1], pos_PatrolTwo_Two[2], pos_PatrolTwo_Two[3], \"Mobile.setMobileDirection\", PatrolTwo, 1)\r\n        invoke(14500, 1, \"Mobile.setMobileDirection\", PatrolOne, 7)\r\n        invoke(14500, 1, \"Mobile.setMobileDirection\", PatrolTwo, 3)\r\n        invoke(16000, 1, \"Mobile.moveMobile\", PatrolOne, pos_PatrolOne_One[1], pos_PatrolOne_One[2], pos_PatrolOne_One[3], \"Mobile.setMobileDirection\", PatrolOne, 1)\r\n        invoke(16000, 1, \"Mobile.moveMobile\", PatrolTwo, pos_PatrolTwo_One[1], pos_PatrolTwo_One[2], pos_PatrolTwo_One[3], \"Mobile.setMobileDirection\", PatrolTwo, 5)\r\n        invoke(29500, 1, \"Mobile.setMobileDirection\", PatrolOne, 3)\r\n        invoke(29500, 1, \"Mobile.setMobileDirection\", PatrolTwo, 7)\nend\n\n-- [EVENT] Un combat se termine\n-- \nfunction event_2148_20829()\n    \nend\n\n","functions":["tContains","prepareChatUI","prepareFollowQuestUI","prepareUI","prepareShortcuts","setWidgetVisible","clearWidgetVisible","setWidgetEnable","clearWidgetEnable","setUIColorTween","clearUIColorTweens","setUIParticle","setUIParticleBorder","clearUIParticles","addDialogLoadListener","clearDialogLoadListener","addDialogUnloadListener","clearDialogUnloadListener","addDialogEventListener","clearDialogEventListener","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","bubble","clearBubbles","setCompass","clearCompasses","createActor","clearActors","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","startCinematicContext","skipCinematic","stopCinematicContext","displayScreenEffect","clearALL","clearUI","clearListener","CreateGuard","GuardExclusion","SeductionFail","SeductionWin","InfiltrationFail","InfiltrationWin","EliminateFail","EliminateWin","CorruptFail","CorruptWin","MenaceFail","MenaceWin","RaklurHit","event_2148_17380","event_2148_17280","event_2148_17381","event_2148_17387","event_2148_17388","event_2148_17403","event_2148_17565","event_2148_17567","event_2148_17568","event_2148_17404","event_2148_17406","event_2148_17407","event_2148_17405","event_2148_17557","event_2148_17563","event_2148_17564","event_2148_17546","event_2148_17558","event_2148_17571","event_2148_17573","event_2148_17575","event_2148_17577","event_2148_17580","event_2148_17584","event_2148_17582","event_2148_17589","event_2148_17594","event_2148_17595","event_2148_17596","event_2148_17597","event_2148_17598","event_2148_17599","event_2148_17600","event_2148_17601","event_2148_17602","event_2148_17603","event_2148_17604","event_2148_17605","event_2148_17606","event_2148_17607","event_2148_17608","event_2148_17609","event_2148_17610","event_2148_17611","event_2148_17612","event_2148_17613","event_2148_17614","event_2148_17615","event_2148_17616","event_2148_17617","event_2148_17618","event_2148_17619","event_2148_17637","SpawnAddGuard","LebbocqBackup","event_2148_17700","event_2148_17710","event_2148_17711","event_2148_17690","event_2148_17691","event_2148_17692","event_2148_17780","event_2148_17781","event_2148_17782","event_2148_17783","event_2148_17784","event_2148_17785","event_2148_17786","event_2148_17764","event_2148_17765","event_2148_17766","event_2148_17767","event_2148_17768","event_2148_17769","event_2148_17770","event_2148_17771","event_2148_17772","event_2148_17773","event_2148_17774","event_2148_17775","event_2148_17776","event_2148_17777","event_2148_17778","event_2148_17779","event_2148_17701","event_2148_17702","event_2148_17733","event_2148_17734","event_2148_17735","event_2148_17736","event_2148_17737","event_2148_17738","event_2148_17739","event_2148_17740","event_2148_17741","event_2148_17742","event_2148_17743","event_2148_17744","event_2148_17745","event_2148_17746","event_2148_17747","event_2148_17748","event_2148_17749","event_2148_17750","event_2148_17751","event_2148_17752","event_2148_17753","event_2148_17754","event_2148_17755","event_2148_17756","event_2148_17757","event_2148_17758","event_2148_17759","event_2148_17760","event_2148_17790","event_2148_17791","event_2148_17813","event_2148_17795","event_2148_17796","event_2148_17797","event_2148_17888","event_2148_17889","event_2148_17890","event_2148_17894","event_2148_20829"],"quest_calls":[],"dialogue_calls":[]},"scenario/2158.lua":{"source":"--Creation des Monstres\r\nNPC_serpe = Mobile.generateClientMobileId()\r\nNPC_mamie = Mobile.generateClientMobileId()\r\nNPC_papy = Mobile.generateClientMobileId()\r\nNPC_serpeBis = Mobile.generateClientMobileId()\r\nNPC_mamieBis = Mobile.generateClientMobileId()\r\nNPC_papyBis = Mobile.generateClientMobileId()\r\nNPC_serpeTer = Mobile.generateClientMobileId()\r\nNPC_papyTer = Mobile.generateClientMobileId()\r\nNPC_boss = Mobile.generateClientMobileId()\r\nNPC_statue_one = Mobile.generateClientMobileId()\r\nNPC_statue_bis = Mobile.generateClientMobileId()\r\nNPC_boss_bis = Mobile.generateClientMobileId()\r\n\r\nfunction startCine(cineZoomFactor)\r\n\tUI.manageFrame(\"World\", false)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tUI.setShortcutEnabled(false)\r\n\tCamera.setZoomFactor(cineZoomFactor)\r\nend\r\n\r\nfunction endCine(eventId)\r\n\tUI.hideButton()\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\tUI.manageFrame(\"World\", true)\r\n\t\r\n\tif (zoomFactor and zoomFactor > 0) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\t\r\n\t--On replace la caméra sur le joueur\r\n\tCamera.attachCameraToMobile(Context.getLeaderId())\r\n\r\n\tclearBubbles()\r\n\t\r\n\tif (eventId and eventId > 0) then\r\n\t\tServer.triggerEvent(eventId)\r\n\tend\r\nend\r\n\r\nfunction skipCine(eventId)\r\n\tfor key,value in pairs(tasks) do\r\n\t\tinterrupt(value)\r\n\tend\r\n\t\r\n\tendCine(eventId)\r\nend\r\n\r\nfunction bubble(delay, mobile, text, offsetX, offsetY, infiniteDuration)\r\n\tif not Mobile.isMobile(mobile) then return end\r\n\r\n\tlocal delayClose = delay - 50\r\n\tif delayClose < 0 then delayClose = 0 end\r\n\r\n\tinvoke_custom(delayClose, 1, \"BubbleText.closeBubbleAttachedTo\", mobile)\r\n\t\r\n\tif (text and text ~= \"\") then\r\n\t\tinvoke_custom(delay, 1, \"BubbleText.showText\",  mobile, text, offsetX, offsetY, infiniteDuration)\r\n\tend\t\r\nend\r\n\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(tasks, taskId)\r\nend\r\n\r\nfunction clearBubbles()\r\nBubbleText.closeBubbleAttachedTo(NPC_boss)\r\nBubbleText.closeBubbleAttachedTo(NPC_serpe)\r\nBubbleText.closeBubbleAttachedTo(NPC_mamie)\r\nBubbleText.closeBubbleAttachedTo(NPC_papy)\r\nBubbleText.closeBubbleAttachedTo(NPC_serpeBis)\r\nBubbleText.closeBubbleAttachedTo(NPC_mamieBis)\r\nBubbleText.closeBubbleAttachedTo(NPC_papyBis)\r\nBubbleText.closeBubbleAttachedTo(NPC_serpeTer)\r\nBubbleText.closeBubbleAttachedTo(NPC_papyTer)\r\nend\r\n\r\nfunction hideMobile(mobileId)\r\n\tMobile.setMobileVisible(mobileId, false)\r\nend\r\n\r\ntasks = {}\r\nzoomFactor = Camera.getZoomFactor()\n\n-- [INITIALISATION] Serveur\n-- \nfunction event_2158_17313()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2158_17314()\n    \nend\n\n-- Salle 1 - Invocation des Sceptres\n-- \nfunction event_2158_17340()\n    \nend\n\n-- Salle 1 - Victoire\n-- \nfunction event_2158_17315()\n    \nend\n\n-- Salle 2 - Invocation des Sceptres\n-- \nfunction event_2158_17343()\n    \nend\n\n-- Salle 2 - Victoire\n-- \nfunction event_2158_17327()\n    \nend\n\n-- [COMP] Salle 3 : arrivée dans l'instance\n-- \nfunction event_2158_17542()\n    local pos_boss = {165, -151, 0}\r\n    local pos_mobUn = {169, -149, 0}\r\n    local pos_mobDeux = {161, -149, 0}\r\n    local pos_mobTrois = {169, -147, 0}\r\n    local pos_mobQuatre = {161, -147, 0}\r\n    local pos_mobCinq = {169, -145, 0}\r\n    local pos_mobSix = {161, -145, 0}\r\n    local pos_mobSept = {166, -143, 0}\r\n    local pos_mobHuit = {164, -143, 0}\r\n    \r\n    --PREPARE ACTORS\r\n    \r\n    Actor.createActor(NPC_mamie, 182204062, pos_mobUn[1], pos_mobUn[2], pos_mobUn[3], 4)\r\n    Mobile.setMobileDirection(NPC_mamie, 5)\r\n    \r\n    Actor.createActor(NPC_mamieBis, 182204062, pos_mobDeux[1], pos_mobDeux[2], pos_mobDeux[3], 4)\r\n    Mobile.setMobileDirection(NPC_mamieBis, 1)\r\n    \r\n    Actor.createActor(NPC_serpe, 182204064, pos_mobTrois[1], pos_mobTrois[2], pos_mobTrois[3], 4)\r\n    Mobile.setMobileDirection(NPC_serpe, 5)\r\n    \r\n    Actor.createActor(NPC_papy, 182204063, pos_mobQuatre[1], pos_mobQuatre[2], pos_mobQuatre[3], 4)\r\n    Mobile.setMobileDirection(NPC_papy, 1)\r\n    \r\n    Actor.createActor(NPC_papyBis, 182204063, pos_mobCinq[1], pos_mobCinq[2], pos_mobCinq[3], 4)\r\n    Mobile.setMobileDirection(NPC_papyBis, 5)\r\n    \r\n    Actor.createActor(NPC_serpeBis, 182204064, pos_mobSix[1], pos_mobSix[2], pos_mobSix[3], 4)\r\n    Mobile.setMobileDirection(NPC_serpeBis, 1)\r\n    \r\n    Actor.createActor(NPC_serpeTer, 182204064, pos_mobSept[1], pos_mobSept[2], pos_mobSept[3], 4)\r\n    Mobile.setMobileDirection(NPC_serpeTer, 7)\r\n    \r\n    Actor.createActor(NPC_papyTer, 182204063, pos_mobHuit[1], pos_mobHuit[2], pos_mobHuit[3], 4)\r\n    Mobile.setMobileDirection(NPC_papyTer, 7)\nend\n\n-- [COMP] Salle 3 : comportement des monstres\n-- \nfunction event_2158_17543(NPC_boss_cine, NPC_statue)\n    local animTalk = \"AnimCine-Psalmodie-2\"\r\n    local animLoop = \"AnimCine-Psalmodie-Boucle\"\r\n    local animShake = \"AnimCine-Tremblement\"\r\n    \r\n    local pos_statue = {165, -147, 3}\r\n    \r\n    -- COMPS\r\n    monster_bubbleId = 0\r\n    rand = 0\r\n    \r\n    -- functions\r\n    function PlayStartAnimation()\n    rand = random(1, 7)\r\n     \r\n    Mobile.setMobileAnimation(NPC_boss_cine,  animTalk)\r\n    BubbleText.closeBubbleAttachedTo(NPC_boss)\r\n    BubbleText.closeBubbleAttachedTo(NPC_serpe)\r\n    BubbleText.closeBubbleAttachedTo(NPC_mamie)\r\n    BubbleText.closeBubbleAttachedTo(NPC_papy)\r\n    BubbleText.closeBubbleAttachedTo(NPC_serpeBis)\r\n    BubbleText.closeBubbleAttachedTo(NPC_mamieBis)\r\n    BubbleText.closeBubbleAttachedTo(NPC_papyBis)\r\n    BubbleText.closeBubbleAttachedTo(NPC_serpeTer)\r\n    BubbleText.closeBubbleAttachedTo(NPC_papyTer)\r\n    -- pos à voir\r\n    monster_bubbleId = BubbleText.showText(NPC_boss_cine, \"Viticultist.Boss.live.0\" .. toString(rand), 10, 80, false)\r\n    invoke(2200, 1, \"BubbleText.showText\", NPC_mamie, \"Viticultist.Follower.live.0\" .. toString(rand), -10, 60, false)\r\n    invoke(2200, 1, \"BubbleText.showText\", NPC_mamieBis, \"Viticultist.Follower.live.0\" .. toString(rand), -10, 60, false)\r\n    invoke(2200, 1, \"BubbleText.showText\", NPC_serpe, \"Viticultist.Follower.live.0\" .. toString(rand), -10, 45, false)\r\n    invoke(2200, 1, \"BubbleText.showText\", NPC_papy, \"Viticultist.Follower.live.0\" .. toString(rand), -10, 45, false)\r\n    invoke(2200, 1, \"BubbleText.showText\", NPC_papyTer, \"Viticultist.Follower.live.0\" .. toString(rand), -10, 45, false)\r\n    invoke(2200, 1, \"BubbleText.showText\", NPC_serpeBis, \"Viticultist.Follower.live.0\" .. toString(rand), -10, 45, false)\r\n    invoke(2200, 1, \"BubbleText.showText\", NPC_serpeTer, \"Viticultist.Follower.live.0\" .. toString(rand), -10, 45, false)\r\n    invoke(2200, 1, \"Particle.addParticleSystem\", 4143691, pos_statue[1], pos_statue[2], pos_statue[3])\r\n    invoke(2200, 1, \"Mobile.setMobileAnimation\", NPC_statue, animShake)\r\n    invoke(1000, 1, \"BubbleText.showText\", NPC_papyBis, \"Viticultist.LateFollower.live.00\", -10, 45, false)\r\n    invoke(2000, 1, \"Mobile.setMobileAnimation\", NPC_boss_cine, animLoop)\r\n    invoke(2700, 1, \"BubbleText.closeBubbleAttachedTo\", NPC_boss_cine)\r\n    invoke(2700, 1, \"BubbleText.closeBubbleAttachedTo\", NPC_papyBis)\r\n    invoke(2800, 1, \"BubbleText.showText\", NPC_papyBis, \"Viticultist.LateFollower.live.0\" .. toString(rand), -10, 45, false)\r\n    \r\n    end\r\n    \r\n    --script\r\n     PlayStartAnimation()\nend\n\n-- [CINE] Salle 3 : TP des joueurs avant ciné\n-- \nfunction event_2158_17835()\n    \nend\n\n-- [CINE] Salle 3 : avant le combat\n-- \nfunction event_2158_17547(NPC_boss_cine)\n    local playerId = Context.getLeaderId()\r\n    local playerX, playerY, playerZ = Mobile.getMobilePosition(playerId)\r\n    local pos_boss = {165, -151, 0}\r\n    local pos_statue = {165, -147, 3}\r\n    \r\n    local animLoop = \"AnimCine-Psalmodie-Boucle\"\r\n    local animCommand = \"AnimCine-DonneOrdre\"\r\n    \r\n    Mobile.setMobileVisible(NPC_boss_cine, false)\r\n    \r\n    Actor.createActor(NPC_boss, 182204060, pos_boss[1], pos_boss[2], pos_boss[3], 4)\r\n    Mobile.setMobileDirection(NPC_boss, 3)\r\n    Actor.createActor(NPC_statue_one, 182204061, pos_statue[1], pos_statue[2], pos_statue[3], 4)\r\n    Mobile.setMobileDirection(NPC_statue_one, 3)\r\n    \r\n    --Début de la cinématique\r\n    Camera.setCamera(1.6, pos_boss[1], pos_boss[2], pos_boss[3])\r\n    startCine(1.6)\r\n    \r\n    --On supprime les anciennes bulles qui peuvent rester\r\n    clearBubbles()\r\n    \r\n    desinvoke()\r\n    \r\n    invoke(500, 1, \"Mobile.setMobileAnimation\", NPC_boss, animCommand)\r\n    invoke(1800, 1, \"BubbleText.showText\", NPC_boss, \"Viticultist.Boss.cinematic.01\", 10, 80, false)\r\n    invoke(3100, 1, \"BubbleText.closeBubbleAttachedTo\", NPC_boss)\n    invoke(4100, 1, \"BubbleText.showText\", NPC_boss, \"Viticultist.Boss.cinematic.02\", 10, 80, false)\r\n    invoke(5000, 1, \"Camera.setZoomFactor\", 1)\r\n    invoke(5500, 1, \"Mobile.setMobileLookAt\", NPC_serpe, playerX, playerY, false)\r\n    invoke(5500, 1, \"Mobile.setMobileLookAt\", NPC_mamie, playerX, playerY, false)\r\n    invoke(5500, 1, \"Mobile.setMobileLookAt\", NPC_papy, playerX, playerY, false)\r\n    invoke(5500, 1, \"Mobile.setMobileLookAt\", NPC_serpeBis, playerX, playerY, false)\r\n    invoke(5500, 1, \"Mobile.setMobileLookAt\", NPC_mamieBis, playerX, playerY, false)\r\n    invoke(5500, 1, \"Mobile.setMobileLookAt\", NPC_serpeTer, playerX, playerY, false)\r\n    invoke(5500, 1, \"Mobile.setMobileLookAt\", NPC_papyTer, playerX, playerY, false)\r\n    invoke(6000, 1, \"BubbleText.showText\", NPC_mamie, \"Viticultist.Follower.cinematic.01\", -10, 60, false)\r\n    invoke(6000, 1, \"BubbleText.showText\", NPC_mamieBis, \"Viticultist.Follower.cinematic.01\", -10, 60, false)\r\n    invoke(6000, 1, \"BubbleText.showText\", NPC_serpe, \"Viticultist.Follower.cinematic.01\", -10, 45, false)\r\n    invoke(6000, 1, \"BubbleText.showText\", NPC_papy, \"Viticultist.Follower.cinematic.01\", -10, 45, false)\r\n    invoke(6000, 1, \"BubbleText.showText\", NPC_papyTer, \"Viticultist.Follower.cinematic.01\", -10, 45, false)\r\n    invoke(6000, 1, \"BubbleText.showText\", NPC_serpeBis, \"Viticultist.Follower.cinematic.01\", -10, 45, false)\r\n    invoke(6000, 1, \"BubbleText.showText\", NPC_serpeTer, \"Viticultist.Follower.cinematic.01\", -10, 45, false)\r\n    invoke(6400, 1, \"BubbleText.showText\", NPC_papyBis, \"Viticultist.LateFollower.cinematic.01\", -10, 45, false)\r\n    invoke(6600, 1, \"Mobile.setMobileDirection\", NPC_papyBis, 7)\r\n    invoke(6800, 1, \"Mobile.setMobileDirection\", NPC_papyBis, 1)\r\n    invoke(7000, 1, \"Mobile.setMobileDirection\", NPC_papyBis, 3)\r\n    invoke(7000, 1, \"BubbleText.closeBubbleAttachedTo\", NPC_boss)\r\n    invoke(7200, 1, \"Mobile.setMobileDirection\", NPC_papyBis, 7)\r\n    invoke(7400, 1, \"Mobile.setMobileDirection\", NPC_papyBis, 5)\r\n    invoke(7700, 1, \"Mobile.setMobileLookAt\", NPC_papyBis, playerX, playerY, false)\r\n    invoke(7150, 1, \"Mobile.setMobileAnimation\", NPC_boss, animLoop)\r\n    invoke(8300, 1, \"BubbleText.showText\", NPC_papyBis, \"Viticultist.LateFollower.cinematic.02\", -10, 45, false)\r\n    \n    --Fin de la cinématique\r\n    invoke_custom(9000, 1, \"Actor.deleteActor\", NPC_boss)\r\n    invoke_custom(9000, 1, \"Mobile.setMobileVisible\", NPC_boss_cine, true)\r\n    invoke_custom(9000, 1, \"Actor.deleteActor\", NPC_statue_one)\r\n    invoke_custom(9000, 1, \"Mobile.setMobileVisible\", NPC_statue, true)\r\n    invoke_custom(9000, 1, \"Mobile.setMobileAnimation\", NPC_boss_cine, animLoop)\r\n    invoke_custom(9000, 1, \"Actor.deleteActor\", NPC_serpe)\r\n    invoke_custom(9000, 1, \"Actor.deleteActor\", NPC_mamie)\r\n    invoke_custom(9000, 1, \"Actor.deleteActor\", NPC_papy)\r\n    invoke_custom(9000, 1, \"Actor.deleteActor\", NPC_serpeBis)\r\n    invoke_custom(9000, 1, \"Actor.deleteActor\", NPC_mamieBis)\r\n    invoke_custom(9000, 1, \"Actor.deleteActor\", NPC_papyBis)\r\n    invoke_custom(9000, 1, \"Actor.deleteActor\", NPC_serpeTer)\r\n    invoke_custom(9000, 1, \"Actor.deleteActor\", NPC_papyTer)\r\n    invoke_custom(9000, 1, \"endCine\", 17548)\nend\n\n-- Salle 3 : lancement du combat\n-- \nfunction event_2158_17548()\n    \nend\n\n-- Salle 3 - Invocation des Sceptres, bloquage de la cellule de la statue\n-- \nfunction event_2158_17344()\n    \nend\n\n-- Salle 3 - Victoire - changements d'IE\n-- \nfunction event_2158_17328()\n    \nend\n\n-- [CINE] Salle 3 : TP des joueurs avant ciné 2\n-- \nfunction event_2158_17836()\n    \nend\n\n-- [CINE] Salle 3 - Transition avant TP\n-- \nfunction event_2158_17553(NPC_boss_cine)\n    local playerId = Context.getLeaderId()\r\n    \r\n    local pos_boss = {165, -151, 0}\r\n    \r\n    local animEnd = \"AnimCine-Psalmodie-Fin\"\r\n    local animTpstart = \"AnimCine-Psalmodie-Debut\"\r\n    local animTp = \"AnimCine-TransitionSalle\"\r\n    \r\n    local aps_transition = 800592\r\n    \r\n    Mobile.setMobileVisible(NPC_boss_cine, false)\r\n    \r\n    Actor.createActor(NPC_boss, 182204060, pos_boss[1], pos_boss[2], pos_boss[3], 4)\r\n    Mobile.setMobileDirection(NPC_boss, 3)\r\n    \r\n    --Début de la cinématique\r\n    Camera.setCamera(1.6, pos_boss[1], pos_boss[2], pos_boss[3])\r\n    startCine(1.6)\r\n    \r\n    --On supprime les anciennes bulles qui peuvent rester\r\n    clearBubbles()\r\n    \r\n    invoke(1000, 1, \"Mobile.setMobileAnimation\", NPC_boss, animEnd)\r\n    invoke(1200, 1, \"BubbleText.showText\", NPC_boss, \"Viticultist.Boss.cinematic.03\", 10, 80, false)\r\n    invoke(4900, 1, \"BubbleText.closeBubbleAttachedTo\", NPC_boss)\n    invoke(5000, 1, \"Mobile.setMobileAnimation\", NPC_boss, animTpstart)\r\n    invoke(5300, 1, \"BubbleText.showText\", NPC_boss, \"Viticultist.Boss.cinematic.04\", 10, 80, false)\r\n    invoke(6000, 1, \"Mobile.setMobileAnimation\", NPC_boss, animTp)\r\n    invoke(6000, 1, \"Particle.addParticleSystem\", aps_transition, 165, -151, 0)\r\n    invoke(8500, 1, \"BubbleText.closeBubbleAttachedTo\", NPC_boss)\r\n    \n    -- pas de \"end ciné\" ici pour ne pas avoir la fenêtre de fin de combat\r\n    invoke_custom(10000, 1, \"Actor.deleteActor\", NPC_boss)\r\n    --invoke_custom(9000, 1, \"Mobile.setMobileVisible\", NPC_boss_cine, true)\n    invoke_custom(10000, 1, \"Server.triggerEvent\", 17337)\nend\n\n-- [CINE] Salle 4 - TP des joueurs en Salle 4\n-- \nfunction event_2158_17337(USER_GROUP_sydonia_id, USER_GROUP_dranipoch_id, USER_GROUP_mamie_id, USER_GROUP_mamieBis_id, USER_GROUP_papy_id, USER_GROUP_papyBis_id, USER_GROUP_serpe_id, USER_GROUP_serpeBis_id)\n       local pos_camera = {265, -249, 0}\r\n        local pos_boss = {265, -267, 0}\r\n        local pos_mobUn = {269, -267, 0}\r\n        local pos_mobDeux = {261, -267, 0}\r\n        local pos_mobTrois = {263, -251, 0}\r\n        local pos_mobQuatre = {264, -251, 0}\r\n        local pos_mobCinq = {266, -251, 0}\r\n        local pos_mobSix = {267, -251, 0}\r\n        local pos_statue = {265, -263, 3}\r\n        \r\n        local playerId = Context.getLeaderId()\r\n          \r\n        local animCommand = \"AnimCine-DonneOrdre\"\r\n        local animLoop = \"AnimCine-Psalmodie-Boucle\"\r\n        \r\n        local aps_apparition = 800596\r\n        \r\n        Mobile.setMobileVisible(USER_GROUP_sydonia_id, false)\r\n        Mobile.setMobileVisible(USER_GROUP_dranipoch_id, false)\r\n        Mobile.setMobileVisible(USER_GROUP_mamie_id, false)\r\n        Mobile.setMobileVisible(USER_GROUP_mamieBis_id, false)\r\n        Mobile.setMobileVisible(USER_GROUP_serpe_id, false)\r\n        Mobile.setMobileVisible(USER_GROUP_papy_id, false)\r\n        Mobile.setMobileVisible(USER_GROUP_papyBis_id, false)\r\n        Mobile.setMobileVisible(USER_GROUP_serpeBis_id, false)\r\n        \r\n        Actor.createActor(NPC_boss_bis, 182204060, pos_boss[1], pos_boss[2], pos_boss[3], 4)\r\n        Mobile.setMobileDirection(NPC_boss_bis, 3)\r\n        Actor.createActor(NPC_statue_bis, 182204061, pos_statue[1], pos_statue[2], pos_statue[3], 4)\r\n        Mobile.setMobileDirection(NPC_statue_bis, 3)\r\n            \r\n        --Début de la cinématique, reprise de la ciné précédente\r\n    Camera.setMoveSpeedFactor(10000)\r\n    Camera.setCamera(1.6, pos_boss[1], pos_boss[2], pos_boss[3], \"Camera.setMoveSpeedFactor\", 2.1)\r\n    \r\n        invoke(1300, 1, \"Mobile.setMobileAnimation\", NPC_boss_bis, animCommand)\r\n        invoke(2800, 1, \"BubbleText.showText\", NPC_boss_bis, \"Viticultist.Boss.cinematic.05\", 10, 80, false)\r\n        invoke(5400, 1, \"BubbleText.closeBubbleAttachedTo\", NPC_boss_bis)\r\n        invoke(5600, 1, \"BubbleText.showText\", NPC_boss_bis, \"Viticultist.Boss.cinematic.08\", 10, 80, false)\r\n        invoke(7950, 1, \"Mobile.setMobileAnimation\", NPC_boss_bis, animLoop)\r\n        invoke(9400, 1, \"BubbleText.closeBubbleAttachedTo\", NPC_boss_bis)\r\n        invoke(9500, 1, \"Camera.setCamera\", 1.6, pos_mobUn[1], pos_mobUn[2], pos_mobUn[3])\r\n        invoke(9500, 1, \"Particle.addParticleSystem\", aps_apparition, pos_mobUn[1], pos_mobUn[2], pos_mobUn[3])\r\n        invoke(9800, 1, \"Actor.createActor\", NPC_mamie, 182204062, pos_mobUn[1], pos_mobUn[2], pos_mobUn[3], 4)\r\n        invoke(9800, 1, \"Mobile.setMobileDirection\", NPC_mamie, 3)\r\n        invoke(10100, 1, \"Camera.setCamera\", 1.6, pos_mobDeux[1], pos_mobDeux[2], pos_mobDeux[3])\r\n        invoke(10100, 1, \"Particle.addParticleSystem\", aps_apparition, pos_mobDeux[1], pos_mobDeux[2], pos_mobDeux[3])\r\n        invoke(10400, 1, \"Actor.createActor\", NPC_mamieBis, 182204062, pos_mobDeux[1], pos_mobDeux[2], pos_mobDeux[3], 4)\r\n        invoke(10400, 1, \"Mobile.setMobileDirection\", NPC_mamieBis, 3)\r\n        invoke(11000, 1, \"Camera.setCamera\", 1.6, pos_camera[1], pos_camera[2], pos_camera[3])\r\n        invoke(11500, 1, \"Particle.addParticleSystem\", aps_apparition, pos_mobTrois[1], pos_mobTrois[2], pos_mobTrois[3])\r\n        invoke(11800, 1, \"Actor.createActor\", NPC_serpe, 182204064, pos_mobTrois[1], pos_mobTrois[2], pos_mobTrois[3], 4)\r\n        invoke(11800, 1, \"Mobile.setMobileDirection\", NPC_serpe, 7)\r\n        invoke(11700, 1, \"Particle.addParticleSystem\", aps_apparition, pos_mobQuatre[1], pos_mobQuatre[2], pos_mobQuatre[3])\r\n        invoke(12000, 1, \"Actor.createActor\", NPC_papy, 182204063, pos_mobQuatre[1], pos_mobQuatre[2], pos_mobQuatre[3], 4)\r\n        invoke(12000, 1, \"Mobile.setMobileDirection\", NPC_papy, 7)\r\n        invoke(11900, 1, \"Particle.addParticleSystem\", aps_apparition, pos_mobCinq[1], pos_mobCinq[2], pos_mobCinq[3])\r\n        invoke(12200, 1, \"Actor.createActor\", NPC_papyBis, 182204063, pos_mobCinq[1], pos_mobCinq[2], pos_mobCinq[3], 4)\r\n        invoke(12200, 1, \"Mobile.setMobileDirection\", NPC_papyBis, 7)\r\n        invoke(12100, 1, \"Particle.addParticleSystem\", aps_apparition, pos_mobSix[1], pos_mobSix[2], pos_mobSix[3])\r\n        invoke(12400, 1, \"Actor.createActor\", NPC_serpeBis, 182204064, pos_mobSix[1], pos_mobSix[2], pos_mobSix[3], 4)\r\n        invoke(12400, 1, \"Mobile.setMobileDirection\", NPC_serpeBis, 7)\r\n        \r\n               --Fin de la cinématique\r\n        invoke_custom(13500, 1, \"Actor.deleteActor\", NPC_boss_bis)\r\n        invoke_custom(13500, 1, \"Mobile.setMobileVisible\", USER_GROUP_sydonia_id, true)\r\n        invoke_custom(13500, 1, \"Actor.deleteActor\", NPC_statue_bis)\r\n        invoke_custom(13500, 1, \"Mobile.setMobileVisible\", USER_GROUP_dranipoch_id, true)\r\n        invoke_custom(13500, 1, \"Actor.deleteActor\", NPC_mamie)\r\n        invoke_custom(13500, 1, \"Mobile.setMobileVisible\", USER_GROUP_mamie_id, true)\r\n        invoke_custom(13500, 1, \"Actor.deleteActor\", NPC_mamieBis)\r\n        invoke_custom(13500, 1, \"Mobile.setMobileVisible\", USER_GROUP_mamieBis_id, true)\r\n        invoke_custom(13500, 1, \"Actor.deleteActor\", NPC_serpe)\r\n        invoke_custom(13500, 1, \"Mobile.setMobileVisible\", USER_GROUP_serpe_id, true)\r\n        invoke_custom(13500, 1, \"Actor.deleteActor\", NPC_papy)\r\n        invoke_custom(13500, 1, \"Mobile.setMobileVisible\", USER_GROUP_papy_id, true)\r\n        invoke_custom(13500, 1, \"Actor.deleteActor\", NPC_papyBis)\r\n        invoke_custom(13500, 1, \"Mobile.setMobileVisible\", USER_GROUP_papyBis_id, true)\r\n        invoke_custom(13500, 1, \"Actor.deleteActor\", NPC_serpeBis)\r\n        invoke_custom(13500, 1, \"Mobile.setMobileVisible\", USER_GROUP_serpeBis_id, true)\r\n        invoke_custom(13500, 1, \"endCine\", 17570)\nend\n\n-- Salle 4 - Invocation des Sceptres\n-- \nfunction event_2158_17345()\n    \nend\n\n-- Salle 4 - Victoire - changements d'IE\n-- \nfunction event_2158_17329()\n    \nend\n\n-- [CINE] Salle 4 : TP des joueurs avant ciné fin\n-- \nfunction event_2158_17837()\n    \nend\n\n-- [CINE] Salle 4 (fin) -  TP des joueurs en Salle 3\n-- \nfunction event_2158_17338(NPC_boss_cine)\n    local pos_boss = {165, -151, 0}\r\n    local pos_camera_fin = {174, -152, 0}\r\n    \r\n    Actor.createActor(NPC_boss, 182204060, pos_boss[1], pos_boss[2], pos_boss[3], 4)\n    Mobile.setMobileDirection(NPC_boss, 3)\r\n    \r\n    Mobile.setMobileVisible(NPC_boss_cine, false)\n    \r\n    local animBoss = \"AnimCine-Mort\"\r\n    local aps_mort = 800591\r\n    \r\n    --Début de la cinématique\r\n    Camera.setCamera(1.6, pos_boss[1], pos_boss[2], pos_boss[3])\r\n    startCine(1.6)\r\n    \r\n    --On supprime les anciennes bulles qui peuvent rester\r\n    clearBubbles()\r\n    \r\n    invoke(1700, 1, \"BubbleText.showText\", NPC_boss, \"Viticultist.Boss.cinematic.06\", 10, 80, false)\r\n    invoke(4900, 1, \"BubbleText.closeBubbleAttachedTo\", NPC_boss)\r\n    invoke(5500, 1, \"Mobile.setMobileAnimation\", NPC_boss, animBoss)\r\n    invoke(5500, 1, \"Particle.addParticleSystem\", aps_mort, pos_boss[1], pos_boss[2], pos_boss[3])\r\n    invoke(5800, 1, \"BubbleText.showText\", NPC_boss, \"Viticultist.Boss.cinematic.07\", 10, 80, false)\r\n    invoke(9000, 1, \"BubbleText.closeBubbleAttachedTo\", NPC_boss)\r\n    invoke(9000, 1, \"Camera.setCamera\", 1.6, pos_camera_fin[1], pos_camera_fin[2], pos_camera_fin[3])\r\n    \r\n    \r\n    --Fin de la cinématique\r\n    invoke_custom(10500, 1, \"Actor.deleteActor\", NPC_boss)\r\n    invoke_custom(10500, 1, \"endCine\", 111)\nend\n\n-- [ACHIEVEMENT] Ecoute de l'effet pour 2949\n-- \nfunction event_2158_17504()\n    \nend\n\n-- [ACHIEVEMENT] Ecoute de l'effet pour 2950\n-- \nfunction event_2158_17503()\n    \nend\n\n-- [ACHIEVEMENT] Fin de combat avec check pour 2949\n-- \nfunction event_2158_17460()\n    \nend\n\n-- [ACHIEVEMENT] Fin de combat avec check pour 2950\n-- \nfunction event_2158_17461()\n    \nend\n\n-- Application état bonus - Résistances\n-- \nfunction event_2158_17579()\n    \nend\n\n-- Application état bonus - Zone\n-- \nfunction event_2158_17591()\n    \nend\n\n-- Application état bonus - Collision\n-- \nfunction event_2158_17592()\n    \nend\n\n-- Application état bonus - Monocible\n-- \nfunction event_2158_17593()\n    \nend\n\n-- [DEFAITE] - Salle 3 - Replacement des monstres\n-- \nfunction event_2158_17714()\n    \nend\n\n-- [DEFAITE] - Salle 4 - Replacement des monstres\n-- \nfunction event_2158_17716()\n    \nend\n\n-- POSITION_TRIGGER - Aller\n-- \nfunction event_2158_22951(positionTriggerId)\n    trace(\"ROOM 3\")\nend\n\n","functions":["startCine","endCine","skipCine","bubble","invoke_custom","clearBubbles","hideMobile","event_2158_17313","event_2158_17314","event_2158_17340","event_2158_17315","event_2158_17343","event_2158_17327","event_2158_17542","event_2158_17543","PlayStartAnimation","event_2158_17835","event_2158_17547","event_2158_17548","event_2158_17344","event_2158_17328","event_2158_17836","event_2158_17553","event_2158_17337","event_2158_17345","event_2158_17329","event_2158_17837","event_2158_17338","event_2158_17504","event_2158_17503","event_2158_17460","event_2158_17461","event_2158_17579","event_2158_17591","event_2158_17592","event_2158_17593","event_2158_17714","event_2158_17716","event_2158_22951"],"quest_calls":[],"dialogue_calls":[]},"scenario/2167.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n-- TRIGGER CLIENT --\r\n-- 0 = Fin cinématique VIDEO | Déclenché par le callback Video.addVideoStopOrEndCallback\r\n-- 1 = Arrivée dans l'instance | Déclenché par onInstanceLoaded() callback par Event.runOnInstanceLoaded (cf code Global)\r\n-- 2 = Fin cinématique | Déclenché par stopCinematicContext() (cf code Global)\r\n-- 3 = Fermeture UI Fin de combat\r\n-- 4 = Clic sur le bon bouton de changement d'oriention (parmis les 4) dans UI worldAndFightBar pour s'orientation vers le monstre\r\n-- 5 = Fermeture UI Fiche combattant\r\n-- 6 = Clic sur le bouton de validation de la répartition dans UI Aptitudes\r\n-- 7 = Clic sur la boussole du bon objectif dans l'UI suivi de quête\r\n-- 8 = Fermeture UI Map Monde\r\n\r\n-- VARIABLE GLOBALE - SCRIPT --\r\n\r\nwidget_visible = {}\r\nwidget_enable = {}\r\nui_tweens = {}\r\nui_particles = {}\r\nui_listener_load = {}\r\nui_listener_unload = {}\r\nui_listener_event = {}\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\nscreenEffectId = nil\r\n\r\n-- VARIABLE GLOBALE - MOBILE CINEMATIQUE & TUTO --\r\n\r\nANM_otomai = {think=\"AnimComp-Special03\", talk=\"AnimComp-Special04-Debut\", show=\"AnimComp-Special05-Debut\", nice=\"AnimComp-Special07\", nope=\"AnimComp-Special08\", lol=\"AnimComp-Special09\", stop_it=\"AnimComp-Special10\", come_here=\"AnimComp-Special01\", wave_hit=\"AnimComp-Special02\", fly=\"AnimStatique-Oiseau\", cast=\"AnimSort-01\", supercast=\"AnimComp-Special11\", attack=\"AnimSort-Cast\", balance=\"AnimComp-Special06\"}\r\nANM_melee = {attack=\"AnimSort-Morsure\", glitch1=\"AnimComp-Glitch01\", glitch2=\"AnimComp-Glitch02\", glitch3=\"AnimComp-Glitch03\", roar=\"AnimComp-Agressif\"}\r\nANM_range = {attack=\"AnimSort-01\", glitch=\"AnimComp-Glitch\", dupli=\"AnimComp-Dupli\"}\r\nANM_boss = {attack1=\"AnimSort-Estoc\", attack2=\"AnimSort-Hrargh\", glitch=\"AnimComp-Glitch\", dupli=\"AnimComp-Dupli\", roar=\"AnimComp-Hurle\", ko = \"AnimKO-SortieOK\", death= \"AnimKO-SortieHS\"}\r\n\r\nNPC_otomai = Mobile.generateClientMobileId()\r\nNPC_otomai_gfx = 181404009\r\nNPC_otomai_particleZ = 10\r\nNPC_otomai_bubbleX = 10\r\nNPC_otomai_bubbleY = 70\r\n\r\nNPC_melee = Mobile.generateClientMobileId()\r\nNPC_meleeB = Mobile.generateClientMobileId()\r\nNPC_melee_gfx = 181404014\r\nNPC_melee_particleZ = 5\r\n\r\nNPC_range = Mobile.generateClientMobileId()\r\nNPC_range_gfx = 181404015\r\nNPC_range_particleZ = 3\r\n\r\nNPC_boss = Mobile.generateClientMobileId()\r\nNPC_boss_gfx = 181404012\r\nNPC_boss_particleZ = 8\r\n\r\nNPC_eni_wakfu = Mobile.generateClientMobileId()\r\nNPC_eni_wakfu_gfx = 181404034\r\nNPC_eni_wakfu_particleZ = 7\r\n\r\nNPC_eni_stasis = Mobile.generateClientMobileId()\r\nNPC_eni_stasis_gfx = 181404013\r\nNPC_eni_stasis_particleZ = 7\r\n\r\n_ACTOR_LIST = {NPC_otomai, NPC_melee, NPC_meleeB, NPC_range, NPC_boss, NPC_eni_wakfu, NPC_eni_stasis}\r\n\r\n-- VARIABLE GLOBALE - PARTICULE CINEMATIQUE & TUTO --\r\n\r\n-- UI TUTO\r\napsArrowBig = {6001069,6001070,6001071,6001072,6001073,6001074,6001075,6001076}\r\napsArrow = {6001061,6001062,6001063,6001064,6001065,6001066,6001067,6001068}\r\napsCenter = {ap=6001090, mp=6001091, wp=6001092, hp=6001093}\r\napsFollowBorder = -1548037644\r\n-- WORLD TUTO\r\napsCell = {white_border=800578, red_border=800579, white_arrow=800576, red_arrow=800577, white=800581, red=800582, show=78900}\r\n-- CINEMATIQUE\r\napsWave = {spawn=800573, wave=800574, hit=800575}\r\napsOtomai = {shield=-1814057071, transform=-1814057072, playershield = -1814057074}\r\napsCristal = {base=71071022, react=800580, shield=71071021}\r\napsBoss = {death=-1814057073}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n    for index, value in ipairs (tab) do\r\n\t\tif isEqual(value, val) then\r\n            return true\r\n        end\r\n    end\r\n\r\n    return false\t\r\nend\r\n\r\n-- FONCTION UI -- Replace le Chat en bas à gauche et le rend indéplaçable/déplaçable\r\nfunction prepareChatUI(movable, chatOffsetX)\r\n\tif not UI.isDialogLoaded(\"chatDialog0\") then return end\r\n\t\r\n\tif (not chatOffsetX) then chatOffsetX = 0 end\r\n\t\r\n\tUI.setPosition(\"chatDialog0\", chatOffsetX, 0)\r\n\tUI.setWindowMovable(\"chatDialog0\", movable)\r\nend\r\n\r\n-- FONCTION UI -- Replace le Suivi de Quête mi-hauteur à gauche et le rend indéplaçable/déplaçable\r\nfunction prepareFollowQuestUI(movable)\r\n    local dialogName = \"\"\r\n    if UI.isDialogLoaded(\"verticalFollowedAchievementsDialog\") then\r\n        dialogName = \"verticalFollowedAchievementsDialog\"\r\n    end\r\n    if UI.isDialogLoaded(\"followedAchievementsDialog\") then\r\n        dialogName = \"followedAchievementsDialog\"\r\n    end\r\n\r\n    if (dialogName == \"\") then\r\n        return\r\n    end\r\n\r\n    local screenH, screenW = UI.getWindowSize()\r\n    local x, y = UI.getPosition(dialogName)\r\n\r\n    UI.setPosition(dialogName, x, screenH / 4)\r\n    UI.setWindowMovable(dialogName, movable)\r\nend\r\n\r\n-- FONCTION UI -- Rend Visible/Invisible certains éléments des interfaces\r\nfunction prepareUI(visible)\r\n  --Interface Boutique & Cadeau\r\n  setWidgetVisible(\"topHudDialog\", \"optionShopButton\", visible)\r\n  setWidgetVisible(\"topHudDialog\", \"giftButton\", visible)\r\n\r\n  --UI sous le Coeur\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"wakfuStasisBar\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"xpBar\", visible)\r\n\r\n  --Boutons hors combat à droite du Coeur\r\n  setWidgetVisible(\"shortcutBarDialog\", \"previousButton\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"nextButton\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseShortcutBar1\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseShortcutBar2\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseShortcutBar3\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseShortcutBar4\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"shortcutBarItemButton\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"shortcutBarSpellButton\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseButtonContainerForTuto1\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseButtonContainerForTuto2\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseButtonContainerForTuto3\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseButtonContainerForTuto4\", visible)\r\n\r\n  --Boutons hors combat à gauche de l'écran - barre d'interfaces\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"firstInterfaceBarBackground\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"secondInterfaceBarBackground\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"extraInterfaceBarDrawerButton\", visible)\r\n\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"fightInfoBtn\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"inventoryButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"buildSheetSetButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"craftButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"questsButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"dungeonButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"cosmeticsButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"tutorialBookButton\", visible)\r\n\r\n  --Boutons hors combat à gauche de l'écran - barre d'interfaces (deuxième barre)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"contactListButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"guildButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"companionsButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"nationButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"battlegroundButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"passportButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"emoteButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"encyclopediaButton\", visible)\r\n\r\n  --Boutons hors combat \"actions rapides\"\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"OverWorldActionsBackground\", visible)\r\n\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"dimensionalBagButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"mapButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"rideMountButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"miniMapButton\", visible)\r\n\r\n  --Boutons en combat à gauche du Coeur\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"FightActionsBackground\", visible)\r\n\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"giveUpButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"hideFightersButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"tacticalModeBtn\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"reportCellBtn\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"fightMarkerBtn\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"lockFightBtn\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"resistanceOverheadBtn\", visible)\r\nend\r\n\r\n-- FONCTION SHORTCUT -- Rend Actif/Inactif certains raccourcis\r\nfunction prepareShortcuts(enabled, shortcutType)\r\n  if not shortcutType or shortcutType == \"WORLD\" then\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.world\", \"enterLeaveBag\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.world\", \"switchHero0\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.world\", \"switchHero1\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.world\", \"switchHero2\")\r\n  end\r\n  if not shortcutType or shortcutType == \"DISPLAY\" then\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"zoomIn\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"zoomOut\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"closeWindows\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"setLODLevel\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"setFightLODLevel\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"showHideNameOverheadsCommand\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"hideFightOccluders\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"alphaMask\")\r\n  end\r\n  if not shortcutType or shortcutType == \"CHAT\" then\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.chat\", \"chat\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.chat\", \"lastContact\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.chat\", \"firstContact\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.chat\", \"autoCompletePlayerName\")\r\n    for bind=1, 9, 1 do\r\n      UI.setShortcutEnabled(enabled, \"shortcutCategory.shortcutBar\", \"bind\" .. toString(bind))\r\n    end\r\n  end\r\n\r\n  if not shortcutType or shortcutType == \"FIGHT\" then\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"fighterTransparency\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"switchTacticalView\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"nextSelectedFighter\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"giveUp\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"lockFight\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"reportCell\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"callHelp\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"displayHpBar\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"resetFightCamera\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"endPlacementAndTurn\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"closeCombatRight\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"closeCombatLeft\")\r\n  end\r\n  if not shortcutType or shortcutType == \"INTERFACE\" then\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"minimap\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"contactList\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"companionManagement\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"guild\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"craft\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"dungeonList\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"achievements\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"quests\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"emotes\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"ecosystem\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"climate\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"nation\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"partySearch\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"passport\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"almanax\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"tutorialBook\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"switchToDirectAttackCommand\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"map\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"spellsInventory\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"inventory\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"characterBook\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"osamodasSymbiot\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"shortcutBar0\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"shortcutBar1\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"shortcutBar2\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"shortcutBar3\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"additionalShortcutBar0\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"additionalShortcutBar1\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"additionalShortcutBar2\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"additionalShortcutBar3\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"changeShortcutBarType\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"downscaling\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"rewards\")\r\n\tUI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"battlegroundList\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"aptitudes\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"presets\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"encyclopedia\")\r\n  end\r\n\r\n  -- On ne bloque pas les raccourcis de sorts finalement\r\n--   if not shortcutType or shortcutType == \"SHORTCUTBAR\" then\r\n--     for bar=0,3, 1 do\r\n--       for slot=0, 9, 1 do\r\n--         UI.setShortcutEnabled(enabled, \"shortcutCategory.shortcutBar\", \"shortcut\" .. toString(bar) .. toString(slot))\r\n--       end\r\n--     end\r\n--   end\r\nend\r\n\r\n-- FONCTION UI -- Rend Visible/Invisible un élément d'une interface\r\nfunction setWidgetVisible(dialogName, widgetName, visible)\r\n  if not UI.isDialogLoaded(dialogName) then return end\r\n\r\n  UI.setWidgetVisibility(dialogName, widgetName, visible)\r\n  table.insert(widget_visible, { name = dialogName, id = widgetName, state = visible })\r\nend\r\n\r\nfunction clearWidgetVisible()\r\n  local str = \"\"\r\n  for i=#widget_visible, 1, -1 do\r\n    str = str .. toString(widget_visible[i].name) .. \"@\" .. toString(widget_visible[i].id) .. \";\"\r\n    UI.setWidgetVisibility(widget_visible[i].name, widget_visible[i].id, true)\r\n  end\r\n\r\n  widget_visible = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearWidgetVisible\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Rend Actif/Inactif un élément d'une interface\r\nfunction setWidgetEnable(dialogName, widgetName, enable)\r\n  if not UI.isDialogLoaded(dialogName) then return end\r\n\r\n  UI.setWidgetEnabled(dialogName, widgetName, enable)\r\n  table.insert(widget_enable, {name = dialogName, id = widgetName, state = enable})\r\nend\r\n\r\nfunction clearWidgetEnable()\r\n  local str = \"\"\r\n  for i=#widget_enable, 1, -1 do\r\n    str = str .. toString(widget_enable[i].name) .. \"@\" .. toString(widget_enable[i].id) .. \";\"\r\n    UI.setWidgetEnabled(widget_enable[i].name, widget_enable[i].id, true)\r\n  end\r\n\r\n  widget_enable = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearWidgetEnable\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Ajoute/Retire une TweenParticle à un élément d'une interface\r\nfunction setUIColorTween(dialogName, widgetName, duration, loop, r1, g1, b1, a1, r2, g2, b2, a2)\r\n  if not UI.isDialogLoaded(dialogName) then return end\r\n\r\n  UI.addColorTween(dialogName, widgetName, duration, loop, r1, g1, b1, a1, r2, g2, b2, a2)\r\n  table.insert(ui_tweens, {name = dialogName, id = widgetName})\r\nend\r\n\r\nfunction clearUIColorTweens(dialogName, widgetName)\r\n  local str = \"\"\r\n  for i=#ui_tweens, 1, -1 do\r\n    if ((not dialogName) or (dialogName == ui_tweens[i].name)) and ((not widgetName) or (widgetName == ui_tweens[i].id)) then\r\n      str = str .. toString(ui_tweens[i].name) .. \"@\" .. toString(ui_tweens[i].id) .. \";\"\r\n      UI.removeColorTween(ui_tweens[i].name, ui_tweens[i].id)\r\n      table.remove(ui_tweens, i)\r\n    end\r\n  end\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearUIColorTweens\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Ajoute/Retire une Particle à un élément d'une interface\r\nfunction setUIParticle(dialogName, widgetName, apsFileName, x, y, alignment, level)\r\n  if not UI.isDialogLoaded(dialogName) then return end\r\n\r\n  local particleId = UI.addParticle(dialogName, widgetName, apsFileName, x, y, alignment, level)\r\n  table.insert(ui_particles, {name = dialogName, id = widgetName})\r\n\r\n  return particleId\r\nend\r\n\r\nfunction setUIParticleBorder(dialogName, widgetName, apsFileName, x, y, alignment, level, speed)\r\n  if not UI.isDialogLoaded(dialogName) then return end\r\n\r\n  local particleId = UI.addParticleToBorder(dialogName, widgetName, apsFileName, x, y, alignment, level, speed)\r\n  table.insert(ui_particles, {name = dialogName, id = widgetName})\r\n\r\n  return particleId\r\nend\r\n\r\nfunction clearUIParticles(dialogName, widgetName)\r\n  local str = \"\"\r\n  for i=#ui_particles, 1, -1 do\r\n    if ((not dialogName) or (dialogName == ui_particles[i].name)) and ((not widgetName) or (widgetName == ui_particles[i].id)) then\r\n      str = str .. toString(ui_particles[i].name) .. \"@\" .. toString(ui_particles[i].id) .. \";\"\r\n      UI.clearParticles(ui_particles[i].name, ui_particles[i].id)\r\n      table.remove(ui_particles, i)\r\n    end\r\n  end\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearUIParticles\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Enregistre/Supprime un callback à l'ouverture d'une interface\r\nfunction addDialogLoadListener(dialog, funcName, ...)\r\n  UI.addDialogLoadedListener(dialog, funcName, unpack(arg))\r\n  table.insert(ui_listener_load,  dialog)\r\nend\r\n\r\nfunction clearDialogLoadListener(dialogName)\r\n  local str = \"\"\r\n  for i=#ui_listener_load, 1, -1 do\r\n    if (not dialogName) or (dialogName == ui_listener_load[i]) then\r\n      str = str .. toString(ui_listener_load[i]) .. \";\"\r\n      UI.removeDialogLoadedListener(ui_listener_load[i])\r\n      table.remove(ui_listener_load, i)\r\n    end\r\n  end\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearDialogLoadListener\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Enregistre/Supprime un callback à la fermeture d'une interface\r\nfunction addDialogUnloadListener(dialog, funcName, ...)\r\n  UI.addDialogUnloadedListener(dialog, funcName, unpack(arg))\r\n  table.insert(ui_listener_unload, dialog)\r\nend\r\n\r\nfunction clearDialogUnloadListener(dialogName)\r\n  local str = \"\"\r\n  for i=#ui_listener_unload, 1, -1 do\r\n    if (not dialogName) or (dialogName == ui_listener_unload[i]) then\r\n      str = str .. toString(ui_listener_unload[i]) .. \";\"\r\n      UI.removeDialogUnloadedListener(ui_listener_unload[i])\r\n      table.remove(ui_listener_unload, i)\r\n    end\r\n  end\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearDialogUnloadListener\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Enregistre/Supprime un callback sur un élément d'une interface\r\nfunction addDialogEventListener(dialog, id, eventType, funcName, ...)\r\n  if not UI.isDialogLoaded(dialog) then return end\r\n\r\n  UI.addEventListener(dialog, id, eventType, funcName, unpack(arg))\r\n  table.insert(ui_listener_event, {dialog=dialog, id=id, eventType=eventType, funcName=funcName})\r\nend\r\n\r\nfunction clearDialogEventListener(dialogName)\r\n  local str = \"\"\r\n  for i=#ui_listener_event, 1, -1 do\r\n    if (not dialogName) or (dialogName == ui_listener_event[i].dialog) then\r\n      str = str .. toString(ui_listener_event[i].dialog) .. \"@\" .. toString(ui_listener_event[i].id) .. \";\"\r\n      UI.removeEventListener(ui_listener_event[i].dialog, ui_listener_event[i].id, ui_listener_event[i].eventType, ui_listener_event[i].funcName)\r\n      table.remove(ui_listener_event, i)\r\n    end\r\n  end\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearDialogEventListener\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y , z, ...)\r\n  local particleId = Particle.addParticleSystem(particleFileId, x, y , z, unpack(arg))\r\n  table.insert(world_particles, particleId)\r\n\r\n  return particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n  local particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n  table.insert(world_particles, particleId)\r\n\r\n  return particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n  local str = \"\"\r\n  for i=#world_particles, 1, -1 do\r\n    str = str .. toString(world_particles[i]) .. \";\"\r\n    Particle.removeParticleSystem(world_particles[i])\r\n  end\r\n\r\n  world_particles = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n  BubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n  if isLower(mobileId, 0) then\r\n    BubbleText.setCharacterSpeak(mobileId, text)\r\n  else\r\n    if (not offsetY) then\r\n      local height = Mobile.getMobileHeight(mobileId)\r\n      if (not height) then height = 6 end\r\n\r\n      offsetY = height * 10\r\n    end\r\n\r\n    if (not offsetX) then offsetX = 0 end\r\n    if (not infiniteDuration) then infiniteDuration = false end\r\n\r\n    BubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n    UI.writeLocalisedInChat(text)\r\n  end\r\n\r\n  if (not tContains(bubbles, mobileId)) then\r\n    table.insert(bubbles, mobileId)\r\n  end\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n  local str = \"\"\r\n  for i = #bubbles, 1, -1 do\r\n    if (not mobileId) then\r\n      str = str .. toString(bubbles[i]) .. \";\"\r\n      BubbleText.closeBubbleAttachedTo(bubbles[i])\r\n    elseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n      str = str .. toString(bubbles[i]) .. \";\"\r\n      BubbleText.closeBubbleAttachedTo(bubbles[i])\r\n      table.remove(bubbles, i)\r\n    end\r\n  end\r\n\r\n  if (not mobileId) then bubbles = {} end\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n  local compassId = UI.addCompass(\"compass\", x, y, z)\r\n  table.insert(compasses, compassId)\r\n\r\n  return compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n  local str = \"\"\r\n  for i=#compasses, 1, -1 do\r\n    str = str .. toString(compasses[i]) .. \";\"\r\n    UI.removeCompass(compasses[i])\r\n  end\r\n\r\n  compasses = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height)\r\n  local mobileId = Mobile.generateClientMobileId()\r\n  Actor.createActor(mobileId, spriteName, worldX, worldY, worldZ, availableDirection)\r\n\r\n  if (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n  if (height) then Actor.setActorHeight(mobileId, height) end\r\n\r\n  table.insert(actors, mobileId)\r\n\r\n  return mobileId\r\nend\r\n\r\nfunction clearActors()\r\n  local str = \"\"\r\n  for i = #actors, 1, -1 do\r\n    str = str .. toString(actors[i]) .. \";\"\r\n    Actor.deleteActor(actors[i])\r\n  end\r\n\r\n  actors = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n  local taskId = invoke(delay, count, funcName, unpack(arg))\r\n  table.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n  local str = \"\"\r\n  for i=#invoke_tasks, 1, -1 do\r\n    str = str .. toString(invoke_tasks[i]) .. \";\"\r\n    interrupt(invoke_tasks[i])\r\n    desinvoke(invoke_tasks[i])\r\n  end\r\n\r\n  invoke_tasks = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n  invoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n  local taskId = setInterval(delay, funcName, unpack(arg))\r\n  table.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n  local str = \"\"\r\n  for i=#interval_tasks, 1, -1 do\r\n    str = str .. toString(interval_tasks[i]) .. \";\"\r\n    interrupt(interval_tasks[i])\r\n    desinvoke(interval_tasks[i])\r\n  end\r\n\r\n  interval_tasks = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n  if (_DEBUG) then trace(\"startCinematicContext\") end\r\n\r\n  UI.manageFrame(\"World\", false)\r\n  UI.closeMRU()\r\n  UI.closeAllBags()\r\n  UI.setUIVisible(false)\r\n  UI.displayWideScreenBand(true)\r\n  Camera.setUserZoomLocked(true)\r\n\r\n  if (cameraMobileId ~= nil)  then\r\n    Camera.setMoveSpeedFactor(10000)\r\n    Camera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n  end\r\n\r\n  if (zoomFactor ~= nil)  then\r\n    Camera.setZoomFactor(zoomFactor)\r\n  end\r\n\r\n  if (musicId ~= nil)  then\r\n    Sound.playForcedMusic(musicId)\r\n  end\r\n\r\n  if (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\nfunction skipCinematic()\r\n  local player = Context.getLeaderId()\r\n\r\n  for x = 1, #_ACTOR_LIST do\r\n    Actor.deleteActor(_ACTOR_LIST[x])\r\n  end\r\n\r\n  UI.hideButton()\r\n  clearALL()\r\n  stopCinematicContext(1, player, true)\r\n  Mobile.setMobileVisible(player, true)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n  if (_DEBUG) then trace(\"stopCinematicContext\") end\r\n\r\n  UI.displayWideScreenBand(false)\r\n  UI.setUIVisible(true)\r\n  Camera.setUserZoomLocked(false)\r\n  UI.manageFrame(\"World\", true)\r\n\r\n  Camera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n  Camera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n  if (zoomFactor ~= nil) then\r\n    Camera.setZoomFactor(zoomFactor)\r\n  end\r\n\r\n  if (cameraMobileId ~= nil) then\r\n    Camera.attachCameraToMobile(cameraMobileId)\r\n  end\r\n\r\n  if (stopMusic) then\r\n    Sound.stopForcedMusic()\r\n  end\r\n\r\n  if (_DEBUG) then\r\n    UI.hideButton()\r\n  end\r\n\r\n  --TRIGGER\r\n  Server.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Affiche/Masque une texture à l'écran\r\nfunction displayScreenEffect(enable, fadeInDur, alphaDur, fadeOutDur, r, g, b, alpha)\r\n  if (_DEBUG) then trace(\"displayScreenEffect\") end\r\n\r\n  if not enable and screenEffectId ~= nil  then\r\n    --On retire le blackScreen\r\n    Effect.stopEffect(screenEffectId)\r\n  else\r\n    --On affiche un blackScreen à l'entrée dans l'instance le temps qu'elle soit complètement chargée\r\n    screenEffectId = Effect.createFullScreenSprite(fadeInDur, alphaDur, fadeOutDur, r, g, b, alpha)\r\n  end\r\nend\r\n\r\n-- FONCTION NETTOYAGE --\r\nfunction clearALL()\r\n  clearIntervalTasks()\r\n  clearInvokeTasks()\r\n  clearBubbles()\r\n  clearUIColorTweens()\r\n  clearUIParticles()\r\n  clearWorldParticles()\r\n  clearCompasses()\r\n  clearActors()\r\n\r\n  Focus.display(false)\r\n  UI.unloadTutorialDialog()\r\nend\r\n\r\n-- FONCTION NETTOYAGE --\r\nfunction clearUI(dialogName)\r\n  clearUIColorTweens(dialogName)\r\n  clearUIParticles(dialogName)\r\nend\r\n\r\n-- FONCTION NETTOYAGE --\r\nfunction clearListener(dialogName)\r\n  clearDialogLoadListener(dialogName)\r\n  clearDialogUnloadListener(dialogName)\r\n  clearDialogEventListener(dialogName)\r\nend\r\n\r\nnbFight = 0\r\n\r\nmummyAA = Mobile.generateClientMobileId()\r\nmummyBA = Mobile.generateClientMobileId()\r\nmummyBB = Mobile.generateClientMobileId()\r\nmummyCA = Mobile.generateClientMobileId()\r\nmummyCB = Mobile.generateClientMobileId()\r\nmummyDA = Mobile.generateClientMobileId()\r\nmummyDB = Mobile.generateClientMobileId()\r\nmummyEA = Mobile.generateClientMobileId()\r\nmummyEB = Mobile.generateClientMobileId()\r\n\r\nmummyAD = Mobile.generateClientMobileId()\r\nmummyBC = Mobile.generateClientMobileId()\r\nmummyBD = Mobile.generateClientMobileId()\r\nmummyCC = Mobile.generateClientMobileId()\r\nmummyCD = Mobile.generateClientMobileId()\r\nmummyDC = Mobile.generateClientMobileId()\r\nmummyDD = Mobile.generateClientMobileId()\r\nmummyEC = Mobile.generateClientMobileId()\r\nmummyED = Mobile.generateClientMobileId()\r\n\r\ntableMummy = {mummyAA, mummyBA , mummyBB ,mummyCA ,mummyCB ,mummyDA ,mummyDB , mummyEA , mummyEB , mummyAD ,mummyBC ,mummyBD ,mummyCC ,mummyCD ,mummyDC ,mummyDD ,mummyEC ,mummyED }\r\n\r\nfunction generateMummies()\r\n--\r\n-- left  side\r\n--\r\nActor.createActor(mummyAA, 177704055, 25, -94, -44, 4)\r\nMobile.setMobileDirection(mummyAA, 3)\r\n\r\nActor.createActor(mummyBA, 177704055, 25, -91, -44, 4)\r\nMobile.setMobileDirection(mummyBA, 3)\r\nActor.createActor(mummyBB, 177704055, 27, -91, -44, 4)\r\nMobile.setMobileDirection(mummyBB, 3)\r\n\r\nActor.createActor(mummyCA, 177704055, 25, -88, -44, 4)\r\nMobile.setMobileDirection(mummyCA, 3)\r\nActor.createActor(mummyCB, 177704055, 27, -88, -44, 4)\r\nMobile.setMobileDirection(mummyCB, 3)\r\n\r\nActor.createActor(mummyDA, 177704055, 25, -85, -44, 4)\r\nMobile.setMobileDirection(mummyDA, 3)\r\nActor.createActor(mummyDB, 177704055, 27, -85, -44, 4)\r\nMobile.setMobileDirection(mummyDB, 3)\r\n\r\nActor.createActor(mummyEA, 177704055, 25, -82, -44, 4)\r\nMobile.setMobileDirection(mummyEA, 3)\r\nActor.createActor(mummyEB, 177704055, 27, -82, -44, 4)\r\nMobile.setMobileDirection(mummyEB, 3)\r\n--\r\n-- right side\r\n--\r\nActor.createActor(mummyAD, 177704055, 33, -94, -44, 4)\r\nMobile.setMobileDirection(mummyAD, 3)\r\n\r\nActor.createActor(mummyBC, 177704055, 31, -91, -44, 4)\r\nMobile.setMobileDirection(mummyBC, 3)\r\nActor.createActor(mummyBD, 177704055, 33, -91, -44, 4)\r\nMobile.setMobileDirection(mummyBD, 3)\r\n\r\nActor.createActor(mummyCC, 177704055, 31, -88, -44, 4)\r\nMobile.setMobileDirection(mummyCC, 3)\r\nActor.createActor(mummyCD, 177704055, 33, -88, -44, 4)\r\nMobile.setMobileDirection(mummyCD, 3)\r\n\r\nActor.createActor(mummyDC, 177704055, 31, -85, -44, 4)\r\nMobile.setMobileDirection(mummyDC, 3)\r\nActor.createActor(mummyDD, 177704055, 33, -85, -44, 4)\r\nMobile.setMobileDirection(mummyDD, 3)\r\n\r\nActor.createActor(mummyEC, 177704055, 31, -82, -44, 4)\r\nMobile.setMobileDirection(mummyEC, 3)\r\nActor.createActor(mummyED, 177704055, 33, -82, -44, 4)\r\nMobile.setMobileDirection(mummyED, 3)\r\nend\r\n\r\nfunction destroyMummies()\r\n\tindexVal = 1\r\n\tfor indexVal = 1, 18, 1 do\t\r\n\t\tMobile.setMobileAnimation(tableMummy[indexVal],\"AnimSort-Explosion\")\r\n\t\txa,ya,za = Mobile.getMobilePosition(tableMummy[indexVal])\r\n\t\tParticle.addParticleSystem(-1827057408, xa, ya, za, 1)\r\n\t\ttimeExp = 1200\r\n\t\tinvoke(timeExp, 1,\"Mobile.setMobileVisible\",tableMummy[indexVal],false)\r\n\t\tinvoke(timeExp, 1,\"Actor.deleteActor\",tableMummy[indexVal])\r\n\tend\r\nend\r\n\r\nfunction turnMummies(addMummyOne,addMummyTwo)\r\n\r\nplayerId = Context.getLeaderId()\r\nx,y,z = Mobile.getMobilePosition(playerId)\r\nMobile.setMobileLookAt(addMummyOne, x, y, false)\r\nMobile.setMobileLookAt(addMummyTwo, x, y, false)\r\n\r\n\tindexVal = 1\r\n\tfor indexVal = 1, 18, 1 do\t\r\n\t\tMobile.setMobileLookAt(tableMummy[indexVal], x, y, false)\r\n\tend\r\nend\r\n\r\nfunction resetMummies( addMummyOne, addMummyTwo, valDir)\r\nMobile.setMobileDirection(addMummyOne, valDir)\r\nMobile.setMobileDirection(addMummyTwo, valDir)\r\n\tindexVal = 1\r\n\tfor indexVal = 1, 9, 1 do\t\r\n\t\tMobile.setMobileDirection(tableMummy[indexVal], valDir)\r\n\tend\r\n\tfor indexVal = 10, 18, 1 do\t\r\n\t\tMobile.setMobileDirection(tableMummy[indexVal], valDir)\r\n\tend\r\n\r\nend\r\n\r\n---cinematique\r\n\r\nplayer = Context.getLeaderId()\r\nfunction startCine()\r\n\tzoomFactor = Camera.getZoomFactor()\r\n\tUI.manageFrame(\"World\",false) \t\t\t\t\t\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\t\t\t\t\t\t\t\t\t\t\t\t\r\n\tUI.manageFrame(\"World\",false) \t\t\t\t\t\r\n\tUI.setUIVisible(false)\t\r\n\tUI.displayWideScreenBand(true)\r\nend\r\n\r\nfunction endCine()\r\n\tCamera.attachCameraToMobile(player)\r\n\tUI.displayWideScreenBand(false,25)\r\n\tCamera.setUserZoomLocked(false)\t\t\t\t\t\t\t\t\t\t\t\t\r\n\tUI.setUIVisible(true)\t\r\n\tUI.manageFrame(\"World\",true) \t\t\t\t\r\n\tCamera.setZoomFactor(zoomFactor)\t\r\n\tMobile.setMobileVisible(mimi, false)\r\n\tMobile.setMobileVisible(lebbocq, false)\r\n\tMobile.setMobileVisible(mekamomie, false)\r\nend\r\n\r\n\r\n\r\nfunction MindBubbleStart(mob,text,tDuration)\r\n\tMindBubble=BubbleText.showText(mob, text, 0, 50, false)\r\n\tinvoke(tDuration,1,\"BubbleText.close\",MindBubble)\r\nend\r\n\r\nfunction MindBubbleChef(mob,text,tDuration)\r\n\tMindBubble=BubbleText.showText(mob, text, 0, 80, false)\r\n\tinvoke(tDuration,1,\"BubbleText.close\",MindBubble)\r\nend\r\n\n\n-- Initialisation serveur\n-- \nfunction event_2167_17392(addMummyOne, addMummyTwo)\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2167_17393(callbackPasserelle, addMummyOne, addMummyTwo, bossFight)\n    passerelle = toLong(callbackPasserelle)\r\n    bossOn = toLong(bossFight)\r\n    \r\n    if passerelle==1 then\r\n    \tWorld.setPictoAlpha(7, -27, -16, 0, 1)\r\n    elseif passerelle==2 then\r\n    \tWorld.setPictoAlpha(7, -27, -16, 0, 1)\r\n    \tWorld.setPictoAlpha(29, -33, -38, 0, 1)\r\n    elseif passerelle==3 then\r\n    \tWorld.setPictoAlpha(7, -27, -16, 0, 1)\r\n    \tWorld.setPictoAlpha(29, -33, -38, 0, 1)\r\n    \tWorld.setPictoAlpha(29, -63, -61, 0, 1)\r\n    end\r\n    \r\n    \r\n    if bossOn == 0 then\r\n    generateMummies()\r\n    end\r\nend\n\n-- [EVENT] Un combat se lance - ajout des états de gameplay\n-- \nfunction event_2167_17394(ko)\n    \nend\n\n-- [SALLE 01] Lancement du combat - Zones & états mécaniques\n-- \nfunction event_2167_17516()\n    \nend\n\n-- [EVENT] Salle 1 - End\n-- \nfunction event_2167_17395()\n    World.setPictoAlpha(7, -27, -16, 0, 1000)\nend\n\n-- [SALLE 02] Lancement du combat - Zones & états mécaniques\n-- \nfunction event_2167_17518()\n    \nend\n\n-- [EVENT] Salle 2 - End\n-- \nfunction event_2167_17396()\n    \tWorld.setPictoAlpha(29, -33, -38, 0, 1000)\nend\n\n-- [SALLE 03] Lancement du combat - Zones & états mécaniques\n-- \nfunction event_2167_17519()\n    \nend\n\n-- [EVENT] Salle 3 - End\n-- \nfunction event_2167_17397()\n    \tWorld.setPictoAlpha(29, -63, -61, 0, 1000)\nend\n\n-- [SALLE 04] Lancement du combat - retrait des momies déco\n-- \nfunction event_2167_17521(addMummyOne, addMummyTwo)\n    destroyMummies()\nend\n\n-- [SALLE 04] Lancement du combat - Zones & états mécaniques\n-- \nfunction event_2167_17520()\n    UI.loadTutorialDialog(\"quest.nations.ch04.boss.tutorial\", \"quest.nations.ch04.boss.tutorial.title\", \"quest.nations.ch04.boss.tutorial.desc\")\r\nend\n\n-- [EVENT] Salle 4 - End (player WIN)\n-- \nfunction event_2167_17398()\n    \nend\n\n-- [EVENT] Salle 4 - End (player LOOSE) - replacement mobs et momies déco\n-- \nfunction event_2167_17541(bossId, addGuardOne, addGuardTwo, addMekaOne, addMekaTwo, addMummyOne, addMummyTwo)\n    generateMummies()\nend\n\n-- [EVENT] activation Trigger turn Mummies\n-- \nfunction event_2167_17522(addMummyOne, addMummyTwo)\n    addMummyOne = toLong(addMummyOne)\r\n    addMummyTwo = toLong(addMummyTwo)\r\n    \r\n     turnMummies(addMummyOne,addMummyTwo)\r\n     \nend\n\n-- [EVENT] activation trigger Reset Mummies south\n-- \nfunction event_2167_17523(addMummyOne, addMummyTwo)\n    addMummyOne = toLong(addMummyOne)\r\n    addMummyTwo = toLong(addMummyTwo)\r\n    \r\n     resetMummies(addMummyOne, addMummyTwo, 3)\r\n     \r\n     Sound.playMusic(210024)\r\n     \nend\n\n-- [EVENT] activation trigger Reset Mummies North\n-- \nfunction event_2167_17540(addMummyOne, addMummyTwo)\n    addMummyOne = toLong(addMummyOne)\r\n    addMummyTwo = toLong(addMummyTwo)\r\n    \r\n     resetMummies(addMummyOne, addMummyTwo, 7)\r\n     \nend\n\n-- Cinématique Salle 1\n-- \nfunction event_2167_17824()\n    --init\r\n    \r\n    player = Context.getLeaderId()\r\n    \r\n    mimi = Mobile.generateClientMobileId()\r\n    Actor.createActor(mimi, 177703974, 0, -4, 0, 4)\r\n    Mobile.setMobileDirection(mimi, 7)\r\n    \r\n    lebbocq = Mobile.generateClientMobileId()\r\n    Actor.createActor(lebbocq, 117903816, -1, -1, 1, 4)\r\n    Mobile.setMobileDirection(lebbocq, 1)\r\n    \r\n    --\r\n    \r\n    Mobile.setMobileVisible(player, true)\r\n    \r\n    \r\n    --script\r\n    startCine()\r\n    Camera.setWorldTarget(0, -4, 0)\r\n    Camera.setZoomFactor(2)\r\n    Mobile.setMobileVisible(mimi, true)\r\n    Mobile.setMobileVisible(lebbocq, true)\r\n    Sound.playForcedMusic(210081)\r\n    MindBubbleStart(mimi, \"quest.nations.ch04.end.cine.makamomie.00\",4000)\r\n    invoke(2000,1,\"Mobile.setMobileAnimation\", mimi, \"AnimDial-Pointage\")\r\n    invoke(1000,1,\"Mobile.setMobileAnimation\", lebbocq, \"AnimComp-Carte-Debut\")\r\n    \r\n    invoke(6000, 1, \"MindBubbleStart\", mimi, \"quest.nations.ch04.end.cine.makamomie.01\", 3000)\r\n    invoke(6500,1,\"Mobile.setMobileAnimation\", mimi, \"AnimDial-Joie\")\r\n    invoke(7000,1,\"Mobile.setMobileAnimation\", lebbocq, \"AnimComp-Carte-1-Boucle\")\r\n    \r\n    invoke(10000, 1, \"MindBubbleStart\", mimi, \"quest.nations.ch04.end.cine.makamomie.02\", 3000)\r\n    invoke(10000,1,\"Mobile.setMobileAnimation\", player, \"AnimEmote-Chercher\")\r\n    invoke(10200,1,\"Mobile.setMobileAnimation\", mimi, \"AnimSort-Pokeball\")\r\n    invoke(13000,1,\"Mobile.setMobileAnimation\", lebbocq, \"AnimComp-Carte-Fin\")\r\n    \r\n    invoke(13500, 1, \"MindBubbleStart\", mimi, \"quest.nations.ch04.end.cine.makamomie.03\", 3000)\r\n    invoke(16000,1, \"Mobile.moveMobile\", mimi, 0, -31, -22, \"Mobile.setMobileDirection\", mimi, 7)\r\n    invoke(16000,1,\"Mobile.setMobileAnimation\", lebbocq, \"AnimStatique\")\r\n    \r\n    invoke(18000, 1, \"MindBubbleStart\", player, \"quest.nations.ch04.end.cine.makamomie.04\", 3000)\r\n    invoke(18000, 1, \"MindBubbleStart\", lebbocq, \"quest.nations.ch04.end.cine.makamomie.04\", 3000)\r\n    invoke(18000 ,1,\"Mobile.setMobileAnimation\", lebbocq, \"AnimComp-Casquette\")\r\n    invoke(18000, 1, \"Camera.attachCameraToMobile\", player)\r\n    \r\n    invoke(22000, 1, \"MindBubbleStart\", lebbocq, \"quest.nations.ch04.end.cine.makamomie.05\", 3000)\r\n    invoke(22100,1,\"Mobile.setMobileAnimation\", lebbocq, \"AnimComp-OuiMielleux\")\r\n    \r\n    invoke(26500, 1, \"MindBubbleStart\", player, \"quest.nations.ch04.end.cine.makam