, \"AnimEmote-Effrayee\")\r\n    \r\n    invoke(09000,1,\"Mobile.setMobileAnimation\", bossId, \"AnimCine-Statique-Fin1-Trone\")\r\n    invoke(10800,1,\"Mobile.setMobilePosition\",bossId, 29, -103, -35)\r\n    invoke(10800,1,\"Mobile.setMobileAnimation\", bossId, \"AnimCine-Statique-Fin2-Trone\")\r\n    invoke(12000,1,\"Mobile.setMobileAnimation\", bossId, \"AnimSort-Vengeance\")\r\n    invoke(12500,1,\"endCine\")\r\n    end\r\n    --script\r\n    \r\n    startCine()\r\n    Camera.setWorldTarget(27, -106, -40)\r\n    Camera.setZoomFactor(2)\r\n    Mobile.setMobilePosition(bossId, 29, -104, -35)\r\n    Mobile.setMobileAnimation(bossId,\"AnimCine-Statique-Trone\")\r\n    invoke(2000,1,\"cineGo\")\r\nend\n\n-- Cinématique FIN Boss CH4\n-- \nfunction event_2167_17838()\n    --init\r\n    \r\n    player = Context.getLeaderId()\r\n    \r\n    local mimi = Mobile.generateClientMobileId()\r\n    Actor.createActor(mimi, 177703974, 27, -93, -44, 4)\r\n    Mobile.setMobileDirection(mimi, 1)\r\n    \r\n    local lebbocq = Mobile.generateClientMobileId()\r\n    Actor.createActor(lebbocq, 117903816, 30, -93, -43, 4)\r\n    Mobile.setMobileDirection(lebbocq, 5)\r\n    \r\n    local mekaboss = Mobile.generateClientMobileId()\r\n    Actor.createActor(mekaboss, 177704054, 29, -93, -43, 4)\r\n    Mobile.setMobileDirection(mekaboss, 3)\r\n    \r\n    --\r\n    \r\n    Mobile.setMobileVisible(player, true)\r\n    \r\n    \r\n    \r\n    \r\n    --script\r\n    startCine()\r\n    Camera.setZoomFactor(2)\r\n    Mobile.setMobileVisible(mimi, true)\r\n    Mobile.setMobileVisible(lebbocq, true)\r\n    Mobile.setMobileVisible(mekaboss, true)\r\n    Mobile.setMobileAnimation(mekaboss, \"AnimComp-Activation05\")\r\n    invoke(1000,1, \"donjEndCine\")\r\n    \r\n    function donjEndCine()\r\n    Camera.attachCameraToMobile(mekaboss)\r\n    MindBubbleStart(mimi, \"quest.nations.ch04.end.cine.makamomie.08\",4000)\r\n    invoke(1000,1, \"Mobile.moveMobile\", player, 29, -91, -43, \"Mobile.setMobileDirection\", player, 7)\r\n    invoke(2000,1,\"Mobile.setMobileAnimation\", mimi, \"AnimDial-Pointage\")\r\n    invoke(6000, 1, \"MindBubbleStart\", lebbocq, \"quest.nations.ch04.end.cine.makamomie.09\", 3000)\r\n    invoke(6200,1,\"Mobile.setMobileAnimation\", lebbocq, \"AnimComp-OuiMielleux\")\r\n    invoke(10000, 1, \"MindBubbleStart\", player, \"quest.nations.ch04.end.cine.makamomie.10\", 3000)\r\n    invoke(6200,1,\"Mobile.setMobileAnimation\", player, \"AnimEmote-Acquiescer\")\r\n    invoke(13000, 1, \"MindBubbleStart\", lebbocq, \"quest.nations.ch04.end.cine.makamomie.11\", 3000)\r\n    invoke(16000, 1, \"MindBubbleStart\", mimi, \"quest.nations.ch04.end.cine.makamomie.12\", 3000)\r\n    invoke(16000,1, \"Mobile.moveMobile\", player, 29, -92, -43, \"Mobile.setMobileDirection\", player, 7)\r\n    invoke(16500,1,\"Mobile.setMobileAnimation\", mimi, \"AnimDial-hautain\")\r\n    invoke(18000,1,\"Mobile.setMobileAnimation\", player, \"AnimEmote-Pointer\")\r\n    \r\n    invoke(20000,1,\"Mobile.setMobileAnimation\", mekaboss, \"AnimComp-Activation06\")\r\n    invoke(20500,1,\"Mobile.setMobileAnimation\", player, \"AnimEmote-Effrayee\")\r\n    invoke(20500,1,\"Mobile.setMobileAnimation\", lebbocq, \"AnimComp-SurprisPeur\")\r\n    invoke(20500,1,\"Mobile.setMobileAnimation\", mimi, \"AnimComp-SurprisPeur\")\r\n    \r\n    invoke(23000, 1, \"MindBubbleStart\", mimi, \"quest.nations.ch04.end.cine.makamomie.13\", 3000)\r\n    invoke(23000,1,\"Mobile.setMobileAnimation\", mimi, \"AnimDial-PauseSexy\")\r\n    \r\n    invoke(26000,1, \"Mobile.moveMobile\", mekaboss, 29, -94, -43, \"Mobile.setMobileDirection\", mekaboss, 7)\r\n    \r\n    invoke(27000,1, \"Mobile.setMobileDirection\", mimi, 7)\r\n    invoke(27000,1, \"Mobile.setMobileDirection\", lebbocq, 7)\r\n    \r\n    invoke(31000,1, \"Mobile.moveMobile\", mekaboss, 29, -95, -43, \"Mobile.setMobileDirection\", mekaboss, 7)\r\n    invoke(32000, 1, \"MindBubbleStart\", mimi, \"quest.nations.ch04.end.cine.makamomie.14\", 2000)\r\n    invoke(32000, 1, \"MindBubbleStart\", lebbocq, \"quest.nations.ch04.end.cine.makamomie.14\", 2000)\r\n    invoke(32000, 1, \"MindBubbleStart\", player, \"quest.nations.ch04.end.cine.makamomie.14\", 2000)\r\n    invoke(32000,1,\"Mobile.setMobileAnimation\", mimi, \"AnimStatique\")\r\n    invoke(32000,1,\"Mobile.setMobileAnimation\", lebbocq, \"AnimStatique\")\r\n    invoke(35000,1, \"Mobile.moveMobile\", mekaboss, 29, -96, -43, \"Mobile.setMobileDirection\", player, 7)\r\n    invoke(37500,1,\"Mobile.setMobileAnimation\", mekaboss, \"AnimSort-Vengeance\")\r\n    invoke(37500,1, \"Effect.createCameraShakeEffect\",500, 1000, 200, 1)\r\n    \r\n    invoke(37500,1,\"Mobile.setMobileAnimation\", player, \"AnimEmote-Effrayee\")\r\n    invoke(37500,1,\"Mobile.setMobileAnimation\", lebbocq, \"AnimComp-SurprisPeur\")\r\n    invoke(37500,1,\"Mobile.setMobileAnimation\", mimi, \"AnimComp-SurprisPeur\")\r\n    \r\n    invoke(38000,1,\"Mobile.setMobileAnimation\", mekaboss, \"AnimMort\")\r\n    \r\n    invoke(40000,1, \"Camera.setWorldTarget\", 29, -94, -43)\r\n    invoke(40000,1, \"Camera.attachCameraToMobile\", player)\r\n    invoke(40000,1, \"Mobile.setMobileDirection\", mimi, 1)\r\n    invoke(40000,1, \"Mobile.setMobileDirection\", lebbocq, 5)\r\n    \r\n    invoke(41000, 1, \"MindBubbleStart\", mimi, \"quest.nations.ch04.end.cine.makamomie.15\", 3000)\r\n    invoke(41500,1,\"Mobile.setMobileAnimation\", mimi, \"AnimDial-Pointage\")\r\n    invoke(45000, 1, \"MindBubbleStart\", lebbocq, \"quest.nations.ch04.end.cine.makamomie.16\", 3000)\r\n    invoke(45500,1,\"Mobile.setMobileAnimation\", lebbocq, \"AnimComp-Parler\")\r\n    invoke(49000, 1, \"MindBubbleStart\", mimi, \"quest.nations.ch04.end.cine.makamomie.17\", 5000)\r\n    invoke(49500,1,\"Mobile.setMobileAnimation\", mimi, \"AnimDial-hautain\")\r\n    invoke(53500,1, \"Mobile.moveMobile\", mimi, 22, -101, -40, \"Mobile.setMobileDirection\", player, 7)\r\n    \r\n    invoke(54000, 1, \"MindBubbleStart\", lebbocq, \"quest.nations.ch04.end.cine.makamomie.18\", 3000)\r\n    invoke(54500,1,\"Mobile.setMobileAnimation\", lebbocq, \"AnimComp-Parler\")\r\n    invoke(57500, 1, \"MindBubbleStart\", player, \"quest.nations.ch04.end.cine.makamomie.19\", 5000)\r\n    invoke(57500,1,\"Mobile.setMobileAnimation\", player, \"AnimEmote-Acquiescer\")\r\n    invoke(61000,1, \"Mobile.moveMobile\", lebbocq, 22, -101, -40, \"Mobile.setMobileDirection\", player, 7)\r\n    \r\n    invoke(62500,1, \"Mobile.setMobileVisible\", mimi, false)\r\n    invoke(68000,1, \"Mobile.setMobileVisible\", lebbocq, false)\r\n    \r\n    invoke(68000,1, \"Actor.deleteActor\", mimi)\r\n    invoke(68000,1, \"Actor.deleteActor\", lebbocq)\r\n    \r\n    invoke(68200,1,\"endCine\")\r\n    \r\n    end\nend\n\n-- Téléporte le joueur -  après Cinématique FIN Boss CH4\n-- \nfunction event_2167_17848()\n    \nend\n\n-- [EVENT] activation trigger - Sit boss\n-- \nfunction event_2167_17891(bossId)\n    bossId = toLong(bossId)\r\n    addMummyTwo = toLong(addMummyTwo)\r\n    \r\n    Mobile.setMobilePosition(bossId, 29, -104, -35)\r\n    Mobile.setMobileAnimation(bossId,\"AnimCine-Statique-Trone\")\r\n     \nend\n\n","functions":["tContains","prepareChatUI","prepareFollowQuestUI","prepareUI","prepareShortcuts","setWidgetVisible","clearWidgetVisible","setWidgetEnable","clearWidgetEnable","setUIColorTween","clearUIColorTweens","setUIParticle","setUIParticleBorder","clearUIParticles","addDialogLoadListener","clearDialogLoadListener","addDialogUnloadListener","clearDialogUnloadListener","addDialogEventListener","clearDialogEventListener","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","bubble","clearBubbles","setCompass","clearCompasses","createActor","clearActors","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","startCinematicContext","skipCinematic","stopCinematicContext","displayScreenEffect","clearALL","clearUI","clearListener","generateMummies","destroyMummies","turnMummies","resetMummies","startCine","endCine","MindBubbleStart","MindBubbleChef","event_2167_17392","event_2167_17393","event_2167_17394","event_2167_17516","event_2167_17395","event_2167_17518","event_2167_17396","event_2167_17519","event_2167_17397","event_2167_17521","event_2167_17520","event_2167_17398","event_2167_17541","event_2167_17522","event_2167_17523","event_2167_17540","event_2167_17824","event_2167_17832","cineGo","event_2167_17838","donjEndCine","event_2167_17848","event_2167_17891"],"quest_calls":[],"dialogue_calls":[]},"scenario/2171.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\nfunction bubbleCA(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd,  ...)\r\n\r\n  if (not offsetX) then offsetX = 0 end\r\n  if (not offsetY) then offsetY = 0 end\r\n  if (not infiniteDuration) then infiniteDuration = false end\r\n\r\n  BubbleText.closeBubbleAttachedTo(mobileId)\r\n  BubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_2171_17501()\n    \nend\n\n-- [EVENT] ENTER_INSTANCE pour la première fois - Cinématique\n-- \nfunction event_2171_17825(charlesNPC, playerOne)\n    trace(\"=== CINE 1st TIME ===\")\r\n            \r\n           local bossId = toLong(charlesNPC)\r\n           local playerId = Context.getLeaderId()\r\n           x,y,z=Mobile.getMobilePosition(playerId)\r\n           local renemilleNPC = Mobile.generateClientMobileId()\r\n           Actor.createActor(renemilleNPC, 117903816, 0, 0, 0, 4)\r\n           Mobile.setMobileDirection(renemilleNPC, 1)\r\n           Mobile.setMobileVisible(renemilleNPC, false)\r\n            -- 117903816\r\n           \r\n            Mobile.setMobileDirection(playerId, 1)\r\n            startCinematicContext( 1.9, playerId, 210082 )\r\n            \tinvoke_custom(200,1,\"Mobile.setMobilePosition\", playerId, 0, 0, 0)\r\n            \tinvoke_custom( 02000, 1, \"Camera.attachCameraToMobile\", bossId)\r\n            \tinvoke_custom( 02500, 1, \"Particle.addParticleSystemToTarget\", 800435, bossId )\r\n            \tinvoke_custom( 00500, 1, \"Mobile.setMobileAnimation\", bossId, \"AnimHit\" )\r\n            \tinvoke_custom( 01000, 1, \"bubbleCA\",bossId, \"nationch04.cinematic.bureau.startercCA01\", 40, 100 , false)\r\n                invoke_custom( 04000, 1, \"Mobile.setMobileAnimation\", bossId, \"AnimComp-ParleNeutre\" )\r\n            \tinvoke_custom( 04000, 1, \"bubbleCA\", bossId, \"nationch04.cinematic.bureau.startercCA02\", 40, 100, false )\r\n                invoke_custom( 04000, 1, \"Mobile.moveMobile\",playerId, 5, 2, 0, \"Mobile.setMobileDirection\", playerId, 7)\r\n            \tinvoke_custom( 08000, 1, \"Mobile.setMobileAnimation\", bossId, \"AnimComp-ParleColere\" )\r\n            \tinvoke_custom( 08000, 1, \"bubbleCA\", bossId, \"nationch04.cinematic.bureau.startercCA03\", 40, 100, false )\r\n                \r\n            \tinvoke_custom( 12000, 1, \"Mobile.setMobileVisible\",renemilleNPC, true)\r\n            \tinvoke_custom( 12000, 1,\"Camera.attachCameraToMobile\",renemilleNPC)\r\n            \tinvoke_custom( 12200, 1, \"Mobile.setMobileAnimation\", renemilleNPC, \"AnimComp-SurprisPeur\" )\r\n            \tinvoke_custom( 13000, 1, \"bubble\", renemilleNPC, \"nationch04.cinematic.bureau.startercCA04\", 10, 70 )\r\n            \tinvoke_custom( 16000, 1, \"Mobile.setMobileAnimation\", renemilleNPC, \"AnimComp-OuiMielleux\" )\r\n            \tinvoke_custom( 16000, 1, \"bubble\", renemilleNPC, \"nationch04.cinematic.bureau.startercCA05\", 10, 70 )\r\n            \tinvoke_custom( 21000, 1, \"Mobile.setMobileAnimation\", renemilleNPC, \"AnimComp-Parler\" )\r\n            \tinvoke_custom( 21000, 1, \"bubble\", renemilleNPC, \"nationch04.cinematic.bureau.startercCA06\", 10, 70 )\r\n            \tinvoke_custom( 25000, 1, \"Mobile.setMobileAnimation\", renemilleNPC, \"AnimComp-NonHautain\" )\r\n            \tinvoke_custom( 25000, 1, \"bubble\", renemilleNPC, \"nationch04.cinematic.bureau.startercCA07\", 10, 70 )\r\n            \t\r\n            \tinvoke_custom( 32000, 1,\"Mobile.setMobileDirection\", renemilleNPC, 5)\r\n              \tinvoke_custom( 32000, 1,\"Camera.attachCameraToMobile\",bossId)\r\n                invoke_custom( 32000, 1, \"Mobile.setMobileAnimation\", bossId, \"AnimComp-ParleNeutre\" )\r\n            \tinvoke_custom( 32000, 1, \"bubbleCA\", bossId, \"nationch04.cinematic.bureau.startercCA08\", 40, 100, false )\r\n            \tinvoke_custom( 33000, 1, \"Mobile.setMobileVisible\", renemilleNPC, false)\r\n            \tinvoke_custom( 33500, 1, \"Actor.deleteActor\",renemilleNPC)\r\n            \tinvoke_custom(36000,1,\"Mobile.setMobilePosition\", playerId, 5, 2, 0)\r\n          \t\r\n            invoke_custom( 37000, 1, \"stopCinematicContext\", 1.2, playerId ,true)\nend\n\n-- [EVENT] Le joueur rend toutes les ressources - Cinématique\n-- \nfunction event_2171_17860(charlesNPC)\n    \r\n      local playerId = Context.getLeaderId()\r\n      x,y,z = Mobile.getMobilePosition(playerId)\r\n      local bossId = toLong(charlesNPC)\r\n      local renemilleNPC = Mobile.generateClientMobileId()\r\n      local mimiNPC = Mobile.generateClientMobileId()\r\n    \r\n      import(502000005002)\r\n    \r\n      Actor.createActor(renemilleNPC, 117903816, 0, 0, 0, 4)\r\n      Mobile.setMobileDirection(renemilleNPC, 1)\r\n      Mobile.setMobileVisible(renemilleNPC, false)\r\n      Actor.createActor(mimiNPC, 177703974, -1, 0, 0, 4)\r\n      Mobile.setMobileDirection(mimiNPC,1)\r\n      Mobile.setMobileVisible(mimiNPC, false)\r\n    \r\n      Mobile.setMobilePosition(playerId, x, y, z)\r\n      Mobile.setMobileDirection(playerId, 7)\r\n      \r\n      startCinematicContext( 1.9, bossId, 210080 )\r\n      UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 17860)\r\n      \r\n      invoke_custom( 00100, 1, \"Mobile.moveMobile\",playerId, 5, 2, 0, \"Mobile.setMobileDirection\", playerId, 7)\r\n      invoke_custom( 01000, 1, \"Mobile.setMobileAnimation\", bossId, \"AnimComp-ParleNeutre\" )\r\n      invoke_custom( 01000, 1, \"bubbleCA\", bossId, \"nationch04.cinematic.bureau.completeCA01\", 40, 100, false )\r\n      invoke_custom( 05000, 1, \"Mobile.setMobileAnimation\", bossId, \"AnimComp-ParleNeutre\" )\r\n      invoke_custom( 05000, 1, \"bubbleCA\", bossId, \"nationch04.cinematic.bureau.completeCA02\", 40, 100, false )\r\n      invoke_custom( 09000, 1, \"Mobile.setMobileAnimation\", bossId, \"AnimComp-ParleColere\" )\r\n      invoke_custom( 09000, 1, \"bubbleCA\", bossId, \"nationch04.cinematic.bureau.completeCA03\", 40, 100, false )\r\n      \r\n      invoke_custom( 13000, 1, \"Camera.attachCameraToMobile\", mimiNPC)\r\n      invoke_custom( 13100, 1, \"Mobile.setMobileVisible\",mimiNPC, true)\r\n      invoke_custom( 13100, 1, \"bubble\", mimiNPC, \"nationch04.cinematic.bureau.completeCA04\", 10, 50 )\r\n      invoke_custom( 17000, 1, \"Camera.attachCameraToMobile\", bossId)\r\n     