 bubble(delay, mobile, text, offsetX, offsetY, infiniteDuration)\r\n\tif not Mobile.isMobile(mobile) then return end\r\n\r\n\tlocal delayClose = delay - 50\r\n\tif delayClose < 0 then delayClose = 0 end\r\n\r\n\tinvoke_custom(delayClose, 1, \"BubbleText.closeBubbleAttachedTo\", mobile)\r\n\t\r\n\tif (text and text ~= \"\") then\r\n\t\tinvoke_custom(delay, 1, \"BubbleText.showText\",  mobile, text, offsetX, offsetY, infiniteDuration)\r\n\tend\t\r\nend\r\n\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(tasks, taskId)\r\nend\r\n\r\nfunction clearBubbles()\r\nBubbleText.closeBubbleAttachedTo(NPC_Krout)\r\nBubbleText.closeBubbleAttachedTo(NPC_Charles)\r\nend\r\n\r\nfunction hideMobile(mobileId)\r\n\tMobile.setMobileVisible(mobileId, false)\r\nend\r\n\r\nfunction setCompass(x, y, z)\r\n  local compassId = UI.addCompass(\"compass\", x, y, z)\r\n  table.insert(compasses, compassId)\r\nend\r\n\r\nfunction clearCompasses()\r\n  local str = \"\"\r\n  for i=#compasses, 1, -1 do\r\n    str = str .. toString(compasses[i]) .. \";\"\r\n    UI.removeCompass(compasses[i])\r\n  end\r\n\r\n  compasses = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n\r\ntasks = {}\r\nzoomFactor = Camera.getZoomFactor()\n\n-- [INIT] Initialisation des variables et des IE\n-- \nfunction event_2180_17672()\n    \nend\n\n-- [INIT][CINE] ENTER_INSTANCE\n-- \nfunction event_2180_17673(mobOneGroupOne)\n    local pos_Krout = {12, -10, 2}\r\n    local pos_Charles = {6, -11, -4}\r\n    \r\n    local anm_talk = \"AnimComp-ParleNeutre\"\r\n    local anm_scream = \"AnimComp-ParleColere\"\r\n    local anm_remote = \"AnimComp-Telecommande\"\r\n    local anm_Krout = \"AnimComp-Activation00\"\r\n    local anm_KroutBis = \"AnimComp-Activation01\"\r\n    \r\n    Actor.createActor(NPC_Charles, 117904039, pos_Charles[1], pos_Charles[2], pos_Charles[3], 4)\r\n    Mobile.setMobileDirection(