2216_18192","event_2216_18193","event_2216_18194","event_2216_18195","event_2216_18196","event_2216_18197","event_2216_18198","event_2216_18199","event_2216_18200","event_2216_18201","event_2216_18202","event_2216_18203","event_2216_18204","passerelleThree","event_2216_18205","event_2216_18206","event_2216_18207","event_2216_18208","event_2216_18209","event_2216_18210","bubble","stopThat","event_2216_18211","event_2216_18212"],"quest_calls":[],"dialogue_calls":[]},"scenario/2217.lua":{"source":"\n\n-- [INIT] Variables\n-- \nfunction event_2217_18213()\n    \nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_2217_18214()\n    \nend\n\n-- [INIT] Animations des Orbes\n-- \nfunction event_2217_18215()\n    InteractiveElement.setAnimation(27406, \"Animpose-Boucle\")\r\n    InteractiveElement.setAnimation(27407, \"Animpose-Boucle\")\nend\n\n","functions":["event_2217_18213","event_2217_18214","event_2217_18215"],"quest_calls":[],"dialogue_calls":[]},"scenario/2220.lua":{"source":"\n\n-- Enregistrement des Evènements : Début\n-- \nfunction event_2220_18254()\n    \nend\n\n-- Enregistrement des Evènements : Fin\n-- \nfunction event_2220_18255()\n    \nend\n\n-- Enregistrement des Evènements Cyclique : Spawn de monstres\n-- Toutes les X min, on spawn les groupes de monstres\nfunction event_2220_18256()\n    \nend\n\n","functions":["event_2220_18254","event_2220_18255","event_2220_18256"],"quest_calls":[],"dialogue_calls":[]},"scenario/2221.lua":{"source":"\n\n-- [INIT] Active les IE liés à l'Event\n-- Les IE doivent être initialement non utilisable pour que ce soit cohérent\nfunction event_2221_18257()\n    \nend\n\n-- [INIT] Initialise les Monstres NPC liés à l'Event\n-- Les Groupes doivent être initialement non spawn\nfunction event_2221_18258()\n    \nend\n\n","functions":["event_2221_18257","event_2221_18258"],"quest_calls":[],"dialogue_calls":[]},"scenario/2222.lua":{"source":"\n\n-- [INIT] Désactive les IE liés à l'Event\n-- Les IE doivent être initialement non util