Initialise les Monstres NPC liés à l'Event\n-- Les Groupes doivent être initialement non spawn\nfunction event_2229_18288()\n    \nend\n\n","functions":["event_2229_18287","event_2229_18288"],"quest_calls":[],"dialogue_calls":[]},"scenario/2230.lua":{"source":"\n\n-- [INIT] Désactive les IE liés à l'Event\n-- Les IE doivent être initialement non utilisable pour que ce soit cohérent\nfunction event_2230_18289()\n    \nend\n\n-- [INIT] Despawn les Monstres NPC liés à l'Event\n-- Les Groupes doivent être initialement non spawn\nfunction event_2230_18290()\n    \nend\n\n-- [INIT] Despawn les Monstres Cyclique liés à l'Event\n-- \nfunction event_2230_18291()\n    \nend\n\n","functions":["event_2230_18289","event_2230_18290","event_2230_18291"],"quest_calls":[],"dialogue_calls":[]},"scenario/2231.lua":{"source":"\n\n-- [INIT] Spawn Monstres - Montagnes\n-- \nfunction event_2231_18292()\n    \nend\n\n-- [INIT] Spawn Monstres - Champs\n-- \nfunction event_2231_18293()\n    \nend\n\n-- [INIT] Spawn Monstres - Plaines\n-- \nfunction event_2231_18294()\n    \nend\n\n-- [INIT] Spawn Monstres - Cimetière\n-- \nfunction event_2231_18295()\n    \nend\n\n-- [INIT] Spawn Monstres - Forêt\n-- \nfunction event_2231_18296()\n    \nend\n\n-- [INIT] Spawn Monstres - Tainela\n-- \nfunction event_2231_18297()\n    \nend\n\n","functions":["event_2231_18292","event_2231_18293","event_2231_18294","event_2231_18295","event_2231_18296","event_2231_18297"],"quest_calls":[],"dialogue_calls":[]},"scenario/2232.lua":{"source":"\n\n-- [INIT] Variables Globales\n-- \nfunction event_2232_18779()\n    \nend\n\n-- [INIT] Inscription du joueur + Variables Locales\n-- \nfunction event_2232_18780()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 01\n-- \nfunction event_2232_18781()\n    \nend\n\n-- [EVENT] Salle 2 - Début de Combat\n-- \nfunction event_2232_18737()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 02\n-- \nfunction event_2232_18782()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 03\n-- \nfunction event_2232_18783()\n    \nend\n\n-- [EVENT] Salle 4 - Début de Combat\n-- \nfunction event_2232_18684()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 04 - BOSS\n-- \nfunction event_2232_18786()\n    \nend\n\n-- Déplace le joueur vers la salle suivante\n-- \nfunction event_2232_18785()\n    \nend\n\n","functions":["event_2232_18779","event_2232_18780","event_2232_18781","event_2232_18737","event_2232_18782","event_2232_18783","event_2232_18684","event_2232_18786","event_2232_18785"],"quest_calls":[],"dialogue_calls":[]},"scenario/2233.lua":{"source":"\n\n-- [INIT] Inscription du joueur au scénario\n-- \nfunction event_2233_18306()\n    \nend\n\n-- [EVENT] Mauvaise Cellule\n-- \nfunction event_2233_18307()\n    local treasure_list = {\t{pos=35175647774247,world=527}, {pos=35157662653951,world=527}, {pos=35197122897407,world=527}, {pos=35136187894271,world=527}, {pos=35158736586239,world=527},\r\n    \t\t\t\t\t\t{pos=35164910016054,world=131}, {pos=35125718495763,world=131}, {pos=35188264227327,world=131}, {pos=35227455810047,world=131}, {pos=35223161029119,world=131},\r\n    \t\t\t\t\t\t{pos=35158468070831,world=208}, {pos=35268794821036,world=208}, {pos=35192558964162,world=208}, {pos=35146656530875,world=208},\t{pos=35211886019033,world=208},\r\n    \t\t\t\t\t\t{pos=35333487906318,world=159}, {pos=35271479571962,world=159}, {pos=35245709454847,world=159}, {pos=35148804425215,world=159}, {pos=35191216983546,world=159},\r\n    \t\t\t\t\t\t{pos=35205712542232,world=235}, {pos=35150146559500,world=235}, {pos=35208664955431,world=235}, {pos=35095922327044,world=235}, {pos=35140213859839,world=235}}\r\n    \r\n    -- Récupère la position, l'instance et la direction du joueur\r\n    local playerId = Context.getLeaderId()\r\n    local playerInstanceId = Context.getPlayerInstanceId()\r\n    local playerX, playerY, playerZ = Mobile.getMobilePosition(playerId)\r\n    local playerDirection = Mobile.getMobileDirection(playerId)\r\n    \r\n    -- Détermine la position de la cellule où le joueur a creusé\r\n    local startX = playerX\r\n    local startY = playerY\r\n    \r\n    if (playerDirection == 1) then startX = playerX + 1 end\r\n    if (playerDirection == 3) then startY = playerY + 1 end\r\n    if (playerDirection == 5) then startX = playerX - 1 end\r\n    if (playerDirection == 7) then startY = playerY - 1 end\r\n    \r\n    local startZ = Context.getZ(startX, startY, playerZ)\r\n    \r\n    -- Détermine la position du trésor le plus proche de la cellule où le joueur a creusé\r\n    local distance = 100000\r\n    local treasureX, treasureY\r\n    for k = 1, #treasure_list do\r\n    \tlocal tX, tY, tZ = longToPosition(treasure_list[k].pos)\r\n    \tlocal tInstanceId = treasure_list[k].world\r\n    \tlocal tDist = math.abs(tX - startX) + math.abs(tY - startY)\r\n    \t\r\n    \tif ((playerInstanceId == tInstanceId) and (tDist < distance)) then\r\n    \t\tdistance = tDist\r\n    \t\ttreasureX = tX\r\n    \t\ttreasureY = tY\r\n    \tend\r\n    end\r\n    \r\n    if ((treasureX == nil) or (treasureY == nil)) then return trace(\"NO TREASURE FOUND\") end\r\n    if ((distance == 0)) then return trace(\"ALREADY ON A TREASURE\") end\r\n    \r\n    -- Récupère la direction8 du trésor le plus proche par rapport à la cellule où le joueur a creusé\r\n    local direction8 = Mobile.getDirection8To(startX, startY, treasureX, treasureY)\r\n    \r\n    -- Détermine la direction4\r\n    local direction4 = direction8\r\n    local distX = math.abs(startX - treasureX)\r\n    local distY = math.abs(startY - treasureY)\r\n    \r\n    if (direction8 == 0) then\r\n    \tif (distX < distY) then direction4 = 7 end\r\n    \tif (distX > distY) then direction4 = 1 end\r\n    elseif (direction8 == 2) then\r\n    \tif (distX < distY) then direction4 = 3 end\r\n    \tif (distX > distY) then direction4 = 1 end\r\n    elseif (direction8 == 4) then\r\n    \tif (distX < distY) then direction4 = 3 end\r\n    \tif (distX > distY) then direction4 = 5 end\r\n    elseif (direction8 == 6) then\r\n    \tif (distX < distY) then direction4 = 7 end\r\n    \tif (distX > distY) then direction4 = 5 end\r\n    end\r\n    \r\n    function getDestinationCoordinates(direction, startX, startY, startZ)\r\n    \tlocal offsetX = 0\r\n    \tlocal offsetY = 0\r\n    \tlocal offsetZ = 0\r\n    \t\r\n    \tif (direction == 1) then\r\n    \t\toffsetX = 3\r\n    \telseif (direction == 2) then\r\n    \t\toffsetX = 2\r\n    \t\toffsetY = 2\r\n    \telseif (direction == 3) then\r\n    \t\toffsetY =  3\r\n    \telseif (direction == 4) then\r\n    \t\toffsetX = -2\r\n    \t\toffsetY = 2\r\n    \telseif (direction == 5) then\r\n    \t\toffsetX = -3\r\n    \telseif (direction == 6) then\r\n    \t\toffsetX = -2\r\n    \t\toffsetY = -2\r\n    \telseif (direction == 7) then\r\n    \t\toffsetY = -3\r\n    \telseif (direction == 0) then\r\n    \t\toffsetX = 2\r\n    \t\toffsetY = -2\r\n    \tend\r\n    \r\n    \treturn startX + offsetX, startY + offsetY, startZ + offsetZ\r\n    end\r\n    \r\n    -- Détermine le visuel de la particule en fonction de la distance\r\n    local particleFileId = -1548037644 -- Bleu\r\n    if (distance <= 10) then particleFileId = 1016204 end -- Rouge\r\n    \r\n    -- Détermine la vitesse de la particule en fonction de la distance\r\n    local arrowSpeed = math.max(0.05, (math.min(distance, 100) / 400))\r\n    \r\n    -- Affichage de la particule qui indique la direction8\r\n    local dest8X, dest8Y, dest8Z = getDestinationCoordinates(direction8, startX, startY, startZ)\r\n    local aps8Id, aps8Duration = Particle.addTweenParticleSystem(particleFileId, startX, startY, startZ + 2, dest8X, dest8Y, dest8Z + 2, 0, 1, arrowSpeed)\r\n    invoke(aps8Duration, 1, \"Particle.removeParticleSystem\", aps8Id)\r\n    \r\n    if (direction8 == direction4) then return end\r\n    \r\n    -- Affichage de la particule qui indique la direction4\r\n    local dest4X, dest4Y, dest4Z = getDestinationCoordinates(direction4, startX, startY, startZ)\r\n    local aps4Id, aps4Duration = Particle.addTweenParticleSystem(particleFileId, startX, startY, startZ + 2, dest4X, dest4Y, dest4Z + 2, 0, 1, arrowSpeed)\r\n    invoke(aps4Duration, 1, \"Particle.removeParticleSystem\", aps4Id)\nend\n\n-- [EVENT] Bonne Cellule\n-- \nfunction event_2233_18316()\n    trace(\"TREASURE FOUND\")\r\n    \r\n    local playerId = Context.getLeaderId()\r\n    local playerX, playerY, playerZ = Mobile.getMobilePosition(playerId)\r\n    \r\n    Particle.addParticleSystem(1016, playerX, playerY, playerZ)\r\n    Mobile.setMobileAnimation(playerId, \"AnimEmote-Victoire\")\nend\n\n","functions":["event_2233_18306","event_2233_18307","getDestinationCoordinates","event_2233_18316"],"quest_calls":[],"dialogue_calls":[]},"scenario/2235.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2235_18318()\n    \nend\n\n-- [EVENT] ENTER_INSTANCE - TP Cinématique Ogrest 1\n-- \nfunction event_2235_18336()\n    \nend\n\n-- [EVENT] ENTER_INSTANCE - Cinématique Rencontre Otomaï\n-- \nfunction event_2235_18319()\n    local playerId = Context.getLeaderId()\r\n    local otomai = createActor(181404009, -10, 4, 0, 4, 3, 7)\r\n    \r\n    startCinematicContext(1.5, playerId, 210063)\r\n    \r\n    invoke_custom(100,1, \"Effect.createCameraShakeEffect\", 500, 2000, 200, 4)\r\n    \r\n    ---\"Ouah ... quel tremblement...\"\r\n    invoke_custom(3000, 1, \"bubble\", playerId, \"quest.zinit.ch1.cine.rencontre.otomai.01\")\r\n    invoke_custom(3000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Effrayee\")\r\n    invoke_custom(3000, 1, \"Mobile.moveMobile\", otomai, -14, 8, 0)\r\n    ---\"Je ferais demi-tour si j'étais toi.\"\"\r\n    invoke_custom(7000, 1, \"bubble\", otomai, \"quest.zinit.ch1.cine.rencontre.otomai.02\")\r\n    invoke_custom(7000, 1, \"Mobile.setMobileAnimation\", otomai, \"AnimComp-Special10\")\r\n    ---\"Cet endroit est terriblement dangereux, foi d'Otomaï, sinon je ne mérite pas mon nom.\"\r\n    invoke_custom(10000, 1, \"bubble\", otomai, \"quest.zinit.ch1.cine.rencontre.otomai.03\")\r\n    invoke_custom(10000, 1, \"Mobile.setMobileAnimation\", otomai, \"AnimComp-Special10\")\r\n    ---\"Et si je refuse de faire demi-tour ?!\"\r\n    invoke_custom(14000, 1, \"clearBubbles\", otomai)\r\n    invoke_custom(14100, 1, \"bubble\", playerId, \"quest.zinit.ch1.cine.rencontre.otomai.04\")\r\n    invoke_custom(14100, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Colere\")\r\n    ---\"Mon fils... Ogrest...\"\r\n    invoke_custom(17100, 1, \"clearBubbles\", playerId)\r\n    invoke_custom(17200, 1, \"bubble\", otomai, \"quest.zinit.ch1.cine.rencontre.otomai.05\")\r\n    invoke_custom(17200, 1, \"Mobile.setMobileAnimation\", otomai, \"AnimComp-Special03\")\r\n    ---\"Il est consumé de chagrin, sa colère est immense depuis bien trop longtemps.\"\r\n    invoke_custom(20000, 1, \"bubble\", otomai, \"quest.zinit.ch1.cine.rencontre.otomai.06\")\r\n    invoke_custom(20000, 1, \"Mobile.setMobileAnimation\", otomai, \"AnimComp-Special04-Debut\")\r\n    ---\"Tu risques ta vie en allant au sommet.\"\r\n    invoke_custom(25100, 1, \"bubble\", otomai, \"quest.zinit.ch1.cine.rencontre.otomai.07\")\r\n    invoke_custom(25100, 1, \"Mobile.setMobileAnimation\", otomai, \"AnimComp-Special04-Boucle\")\r\n    ---\"Mais je suis le héros de la prophétie !!!\"\r\n    invoke_custom(28100, 1, \"clearBubbles\", otomai)\r\n    invoke_custom(28200, 1, \"bubble\", playerId, \"quest.zinit.ch1.cine.rencontre.otomai.08\")\r\n    invoke_custom(28200, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Pointer\")\r\n    ---\"Je ne pense pas que cette prophétie soit pour aujourd'hui.\"\r\n    invoke_custom(31400, 1, \"clearBubbles\", playerId)\r\n    invoke_custom(31500, 1, \"bubble\", otomai, \"quest.zinit.ch1.cine.rencontre.otomai.09\")\r\n    invoke_custom(31500, 1, \"Mobile.setMobileAnimation\", otomai, \"AnimComp-Special04-Boucle\")\r\n    ---\"Sincèrement tu n'es pas de taille face à mon fils !\"\r\n    invoke_custom(34600, 1, \"bubble\", otomai, \"quest.zinit.ch1.cine.rencontre.otomai.10\")\r\n    invoke_custom(34600, 1, \"Mobile.setMobileAnimation\", otomai, \"AnimComp-Special05-Boucle\")\r\n    ---\"Comment peux-tu l'affirmer, si je n'ai même pas encore essayé ?!\"\r\n    invoke_custom(37600, 1, \"clearBubbles\", otomai)\r\n    invoke_custom(37700, 1, \"bubble\", playerId, \"quest.zinit.ch1.cine.rencontre.otomai.11\")\r\n    invoke_custom(37700, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    ---\"Hmmm\"\r\n    invoke_custom(41900, 1, \"clearBubbles\", playerId)\r\n    invoke_custom(42000, 1, \"bubble\", otomai, \"quest.zinit.ch1.cine.rencontre.otomai.12\")\r\n    invoke_custom(42000, 1, \"Mobile.setMobileAnimation\", otomai, \"AnimComp-Special-Fin\" )\r\n    ---\"Sur ce point je ne peux pas te contredire.\"\r\n    invoke_custom(44000, 1, \"bubble\", otomai, \"quest.zinit.ch1.cine.rencontre.otomai.13\")\r\n    invoke_custom(44000, 1, \"Mobile.setMobileAnimation\", otomai, \"AnimComp-Special09\")\r\n    ---\"Mais écoute au moins ce conseil :\"\r\n    invoke_custom(47100, 1, \"bubble\", otomai, \"quest.zinit.ch1.cine.rencontre.otomai.14\")\r\n    invoke_custom(47100, 1, \"Mobile.setMobileAnimation\", otomai, \"AnimComp-Special05-Debut\")\r\n    ---\"Enregistre-toi sur l'étrange sphère que tu trouveras plus loin.\"\r\n    invoke_custom(50200, 1, \"bubble\", otomai, \"quest.zinit.ch1.cine.rencontre.otomai.15\")\r\n    invoke_custom(50200, 1, \"Mobile.setMobileAnimation\", otomai, \"AnimComp-Special05-Boucle\")\r\n    invoke_custom(51500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Acquiescer\")\r\n    ---\"Cette sphère s'appelle un Silo.\"\r\n    invoke_custom(54500, 1, \"bubble\", otomai, \"quest.zinit.ch1.cine.rencontre.otomai.16\")\r\n    invoke_custom(54500, 1, \"Mobile.setMobileAnimation\", otomai, \"AnimComp-Special04-Boucle\")\r\n    ---\"Pour faire court, c'est une espèce de Zaap qui fonctionne comme les Zaaps que tu connais.\"\r\n    invoke_custom(57600, 1, \"bubble\", otomai, \"quest.zinit.ch1.cine.rencontre.otomai.17\")\r\n    invoke_custom(57600, 1, \"Mobile.setMobileAnimation\", otomai, \"AnimComp-Special04-Boucle\")\r\n    ---\"Et surtout méfie-toi !\"\r\n    invoke_custom(62700, 1, \"bubble\", otomai, \"quest.zinit.ch1.cine.rencontre.otomai.18\")\r\n    invoke_custom(62700, 1, \"Mobile.setMobileAnimation\", otomai, \"AnimComp-Special05-Debut\")\r\n    ---\"J'ai cru appercevoir de vieilles connaissances.\"\r\n    invoke_custom(65800, 1, \"bubble\", otomai, \"quest.zinit.ch1.cine.rencontre.otomai.19\")\r\n    invoke_custom(65800, 1, \"Mobile.setMobileAnimation\", otomai, \"AnimComp-Special03\")\r\n    ---\"Cela ne présage rien de bon...\"\r\n    invoke_custom(69000, 1, \"bubble\", otomai, \"quest.zinit.ch1.cine.rencontre.otomai.20\")\r\n    invoke_custom(69000, 1, \"Mobile.setMobileAnimation\", otomai, \"AnimComp-Special08\")\r\n    invoke_custom(70000, 1, \"Mobile.setMobileAnimation\", playerId, \"