bile.setMobileAnimation\", playerId, \"AnimEmote-Effrayee\")\r\n    invoke_custom(5000, 1, \"Camera.attachCameraToMobile\", ullu)\r\n    invoke_custom(5000, 1, \"Mobile.setMobileAnimation\",ullu,\"AnimComp-Ataaaque\")\r\n    ---\"Jeune héros de la Prophétie, te voilà !\"\r\n    invoke_custom(5500, 1, \"bubble\", ullu, \"quest.zinit.ch1.cine.trous.ullu.01\")\r\n    ---\"Je vois que tu es tombé{[1*]?e:} sur des trous infranchissables ?!\"\r\n    invoke_custom(9000, 1, \"bubble\", ullu, \"quest.zinit.ch1.cine.trous.ullu.02\")\r\n    invoke_custom(13000, 1, \"clearBubbles\", ullu)\r\n    invoke_custom(13100, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Acquiescer\")\r\n    invoke_custom(16500, 1, \"Mobile.setMobileAnimation\",ullu, \"Anim-Comp-Parler03\")\r\n    ---\"Ne t'inquiète pas !\"\r\n    invoke_custom(17500, 1, \"bubble\", ullu, \"quest.zinit.ch1.cine.trous.ullu.03\")\r\n    invoke_custom(18000, 1, \"Mobile.setMobileAnimation\",ullu, \"AnimComp-Non\")\r\n    ---\"Il existe un artefact te permettant de franchir ces petits trous.\"\r\n    invoke_custom(19500, 1, \"bubble\", ullu, \"quest.zinit.ch1.cine.trous.ullu.04\")\r\n    invoke_custom(19500, 1, \"Mobile.setMobileAnimation\",ullu, \"AnimComp-Oui\")\r\n    ---\"Trouve cet artefact !!! \"\r\n    invoke_custom(23500, 1, \"bubble\", ullu, \"quest.zinit.ch1.cine.trous.ullu.05\")\r\n    invoke_custom(25000, 1, \"Mobile.setMobileAnimation\",ullu,\"Anim-Comp-Parler02\")\r\n    ---\"Car il te faut gravir ce Mont au plus vite.\"\r\n    invoke_custom(26000, 1, \"bubble\", ullu, \"quest.zinit.ch1.cine.trous.ullu.06\")\r\n    invoke_custom(29000, 1, \"Mobile.setMobileAnimation\",ullu,\"AnimComp-Ataaaque\")\r\n    invoke_custom(29000, 1, \"clearBubbles\", ullu)\r\n    ---\"Accomplir la Prophétie et sauver le monde...\"\r\n    invoke_custom(29500, 1, \"bubble\", ullu, \"quest.zinit.ch1.cine.trous.ullu.07\")\r\n    invoke_custom(32000, 1, \"clearBubbles\", ullu)\r\n    ---\"C'est TON devoir !!! \"\r\n    invoke_custom(32500, 1, \"bubble\", ullu, \"quest.zinit.ch1.cine.trous.ullu.08\")\r\n    invoke_custom(35500, 1, \"clearBubbles\", ullu)\r\n    ---\"M{[1*]?a:on} jeune sauveu{[1*]?se:r} !\"\r\n    invoke_custom(36000, 1, \"bubble\", ullu, \"quest.zinit.ch1.cine.trous.ullu.09\")\r\n    invoke_custom(36000, 1, \"Mobile.setMobileAnimation\",ullu,\"Anim-Comp-Parler01\")\r\n    invoke_custom(40000, 1, \"clearBubbles\", ullu)\r\n    invoke_custom(40000, 1, \"Mobile.setMobileAnimation\",ullu,\"AnimStatique\")\r\n    invoke_custom(40000, 1, \"setWorldParticleCell\", 800202, 7, -158, 1)\r\n    invoke_custom(40100, 1, \"Mobile.setMobileVisible\", ullu , false)\r\n    invoke_custom(41000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    ---\"Euh...Ullu ?! Reviens ??!!!\"\r\n    invoke_custom(44000, 1, \"bubble\", playerId, \"quest.zinit.ch1.cine.trous.ullu.10\")\r\n    invoke_custom(44000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Help\")\r\n    ---\"Tu ne m'as pas dit où trouver l'artefact...\"\r\n    invoke_custom(47000, 1, \"bubble\", playerId, \"quest.zinit.ch1.cine.trous.ullu.11\")\r\n    invoke_custom(47000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Defaite\")\r\n    invoke_custom(51000, 1, \"clearBubbles\", playerId)\r\n    ---\"...\"\r\n    invoke_custom(53000, 1, \"bubble\", playerId, \"quest.zinit.ch1.cine.trous.ullu.12\")\r\n    invoke_custom(55000, 1, \"clearBubbles\", playerId)\r\n    ---\"Bon, je n'ai qu'à aller voir Coqueline, elle sait peut-être quelque chose.\"\r\n    invoke_custom(56000, 1, \"bubble\", playerId, \"quest.zinit.ch1.cine.trous.ullu.13\")\r\n    invoke_custom(56000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmoteMarket-HausseEpaules\")\r\n    \r\n    ----------------------------------\r\n    \r\n    invoke_custom(60000, 1, \"skipCinematic\")\nend\n\n-- [EVENT] Fin Cinématique Trous Grotte Slek - Validation OBJ 6751 ACH 3228\n-- CET EVENT DOIT ETRE AVANT CEUX DE LA DECOUVERTE POUR NE PAS VALIDER LES 2 OBJECTIFS EN MEME TEMPS !!!\nfunction event_2235_18352()\n    \nend\n\n-- [EVENT] POSITION_TRIGGER - Découverte de la Grotte Slek - Cinématique Grotte Slek\n-- \nfunction event_2235_18348()\n    local playerId = Context.getLeaderId()\r\n    local slekone = createActor(140001810, -4, -153, 0, 4, 1, 7)\r\n    Mobile.setMobileVisible(slekone,  false)\r\n    local slektwo = createActor(140001809, -4, -154, 0, 4, 1, 7)\r\n    Mobile.setMobileVisible(slektwo, false)\r\n    \r\n    startCinematicContext(1.5, slekone, 210080)\r\n    \r\n    invoke_custom(100, 1, \"Mobile.moveMobile\", playerId, 0, -153, 0)\r\n    invoke_custom(2000, 1, \"Mobile.setMobileDirection\", playerId, 5)\r\n    ---\"Ah ! Je crois que c'est l'entrée de la grotte des Sleks !\"\r\n    invoke_custom(2000, 1, \"bubble\", playerId, \"quest.zinit.ch1.cine.rencontre.slek.01\")\r\n    ---\"Comment vais-je pouvoir passer dans cette chose...  immonde.\"\r\n    invoke_custom(5000, 1, \"bubble\", playerId, \"quest.zinit.ch1.cine.rencontre.slek.02\")\r\n    invoke_custom(5000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Chercher\")\r\n    invoke_custom(8000, 1, \"clearBubbles\", playerId)\r\n    invoke_custom(8000, 1,\"Mobile.setMobileVisible\", slekone , true)\r\n    invoke_custom(8000, 1, \"Mobile.setMobileAnimation\", slekone, \"AnimSort-OuSleck-Fin\")\r\n    invoke_custom(8500, 1, \"Mobile.setMobileDirection\", slekone, 1)\r\n    invoke_custom(9000, 1,\"Mobile.setMobileVisible\", slektwo , true)\r\n    invoke_custom(9000, 1, \"Mobile.setMobileAnimation\", slektwo, \"AnimApparition\")\r\n    invoke_custom(9500, 1, \"Mobile.setMobileDirection\", slektwo, 1)\r\n    ---\"MAIS, QUE !!! \"\r\n    invoke_custom(9500, 1, \"bubble\", playerId, \"quest.zinit.ch1.cine.rencontre.slek.03\")\r\n    invoke_custom(9500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Effrayee\")\r\n    invoke_custom(9500, 1, \"Mobile.setMobileAnimation\", slektwo, \"AnimSort01\")\r\n    ---\"Ils n'ont pas l'air très chaleureux.\"\r\n    invoke_custom(11000, 1, \"bubble\", playerId, \"quest.zinit.ch1.cine.rencontre.slek.04\")\r\n    invoke_custom(11000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Help\")\r\n    invoke_custom(11000, 1, \"Mobile.setMobileAnimation\", slekone, \"AnimSort-LongBrick\")\r\n    invoke_custom(13000, 1, \"Mobile.setMobileAnimation\", slektwo, \"AnimSort03\")\r\n    ---\"Je ferais bien de partir sur-le-champ !!! \"\r\n    invoke_custom(14000, 1, \"bubble\", playerId, \"quest.zinit.ch1.cine.rencontre.slek.05\")\r\n    invoke_custom(14000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Help\")\r\n    invoke_custom(14000, 1, \"Mobile.setMobileAnimation\", slekone, \"AnimSort-LongBrick\")\r\n    invoke_custom(15000, 1, \"Mobile.setMobileAnimation\", slektwo, \"AnimSort03\")\r\n    invoke_custom(17000, 1, \"Mobile.setMobileAnimation\", slekone, \"AnimSort-LongBrick\")\r\n    ---\"Il doit y avoir un autre passage ! \"\r\n    invoke_custom(17000, 1, \"bubble\", playerId, \"quest.zinit.ch1.cine.rencontre.slek.06\")\r\n    invoke_custom(17000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Chercher\")\r\n    invoke_custom(20000, 1, \"clearBubbles\", playerId)\r\n    invoke_custom(20000, 1, \"Mobile.moveMobile\", playerId, 3, -159, 0)\r\n    invoke_custom(22000, 1, \"Mobile.setMobileAnimation\", slektwo, \"AnimSort03\")\r\n    invoke_custom(22000, 1, \"Mobile.setMobileAnimation\", slekone, \"AnimSort-OuSleck-Debut\")\r\n    invoke_custom(23500, 1, \"Mobile.setMobileAnimation\", slektwo, \"AnimHit\")\r\n    invoke_custom(24500, 1, \"clearActors\")\r\n    \r\n    ----------------------------------\r\n    \r\n    invoke_custom(24500, 1, \"skipCinematic\")\nend\n\n-- [EVENT] Fin Cinématique Grotte Slek - Validation OBJ 6750 ACH 3228\n-- \nfunction event_2235_18350()\n    \nend\n\n-- DIALOG_EXECUTED - Cinématique Coqueline & Elante\n-- \nfunction event_2235_23646()\n    local playerId = Context.getLeaderId()\r\n    \r\n    function customSkip()\r\n        Mobile.hideOtherPlayerMobile(false)\r\n        skipCinematic(23646)\r\n        fullScreen(0, 0, 500)\r\n    end\r\n    \r\n    Mobile.hideOtherPlayerMobile(true)\r\n    \r\n    startCinematicContext(1.0, playerId)\r\n    \r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"customSkip\")\r\n    \r\n    invoke_custom(00050, 1, \"Sound.stopForcedMusic\")\r\n    invoke_custom(00100, 1, \"Sound.playForcedMusic\", 210002, 60)\r\n    \r\n    -- \"écran noir\"\r\n    invoke_custom(00000, 1, \"fullScreen\", 500, 26500, 1000)\r\n    \r\n    -- \"Vous voyagez avec Coqueline sur le dos d'un gigantesque oiseau blanc, et vous arrivez sur une île resplendissante entourée d'une légère brume.\"\r\n    -- \"Sur la plage, vous voyez une créature blanche et rose, dotée de trois yeux. Elle est accompagnée de sa gardienne.\"\r\n    invoke_custom(00000, 1, \"text\", 500, 10000, 500, \"quest.karn.03.00\")\r\n    \r\n    -- \"Vous êtes ému{[1*]?e:} aux larmes en voyant la magnifique créature : elle semble surréelle tant elle est douce et tant elle parait sage.\"\r\n    -- \"Vous vous sentez en paix et en sérénité.\"\r\n    invoke_custom(11000, 1, \"text\", 500, 7500, 500, \"quest.karn.03.01\")\r\n    \r\n    -- \"Après avoir joué quelques heures avec l'Elante, vous revenez sur la Plage Sauvage en compagnie de Coqueline.\"\r\n    -- \"Un souvenir impérissable et précieux est désormais tapi au fond de votre coeur.\"\r\n    invoke_custom(19500, 1, \"text\", 500, 7500, 500, \"quest.karn.03.02\")\r\n    \r\n    invoke_custom(28000, 1, \"customSkip\")\nend\n\n-- CLIENT_TRIGGERED_EVENT - Fin de la cinématique - ACH 5547 OBJ 11459\n-- \nfunction event_2235_23647()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_2235_18318","event_2235_18336","event_2235_18319","event_2235_18331","event_2235_18351","event_2235_18352","event_2235_18348","event_2235_18350","event_2235_23646","customSkip","event_2235_23647"],"quest_calls":[],"dialogue_calls":[]},"scenario/2238.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2238_18328()\n    \nend\n\n-- [EVENT][CH1] ENTER_INSTANCE - Cinématique Ogrest 1\n-- \nfunction event_2238_18329()\n    local playerId = Context.getLeaderId()\r\n    Mobile.setMobileVisible(playerId, false)\r\n    local ogrest = createActor(1300060, 1, -26, 40, 4, 3, 16)\r\n        \r\n    setWorldParticleTarget(5000, ogrest, 1)\r\n        \r\n    startCinematicContext(1, ogrest, 210079)\r\n    Camera.setWorldTarget(1, -26, 55)\r\n    invoke_custom(2500, 1, \"bubble\", ogrest, \"quest.zinit.ch1.cine.ogrest.01\", -30, 180)\r\n    invoke_custom(2500, 1, \"Mobile.setMobileAnimation\", ogrest, \"AnimSort-Hurle\")\r\n    invoke_custom(4500, 1, \"Effect.createCameraShakeEffect\", 1000, 500, 1000, 1)\r\n    invoke_custom(6000, 1, \"Mobile.setMobileAnimation\", ogrest, \"AnimSort-Tapesol\")\r\n    invoke_custom(7500, 1, \"Effect.createCameraShakeEffect\", 500, 3000, 200, 4)\r\n    \r\n    ----------------------------------\r\n    \r\n    invoke_custom(11000, 1, \"stopCinematicContext\", 1, ogrest, true)\nend\n\n-- [EVENT][CH1] Fin Cinématique Ogrest 1 - TP Plage Sauvage (Arrivée) + Validation OBJ 6448 ACH 3092\n-- \nfunction event_2238_18330()\n    \nend\n\n-- [EVENT][CH1] ENTER_INSTANCE - Cinématique Ogrest 2\n-- \nfunction event_2238_18338()\n    local playerId = Context.getLeaderId()\r\n    Mobile.setMobileVisible(playerId, false)\r\n    local ogrest = createActor(1300060, 1, -26, 40, 4, 3, 16)\r\n    \r\n    setWorldParticleTarget(5000, ogrest, 1)\r\n    \r\n    startCinematicContext(1, ogrest, 210079)\r\n    Camera.setWorldTarget(1, -26, 55)\r\n    invoke_custom(2000, 1, \"bubble\", ogrest, \"quest.zinit.ch1.cine.ogrest.01\", -30, 180)\r\n    invoke_custom(2500, 1, \"Mobile.setMobileAnimation\", ogrest, \"AnimSort-Hurle\")\r\n    invoke_custom(5000, 1, \"Effect.createCameraShakeEffect\", 1000, 500, 1000, 1)\r\n    \r\n    ----------------------------------\r\n    \r\n    invoke_custom(8000, 1, \"stopCinematicContext\", 1, ogrest, true)\nend\n\n-- [EVENT][CH1] Fin Cinématique Ogrest 2 - TP Grotte Sauvage (Gobgob) + Validation OBJ 6745 ACH 3224\n-- \nfunction event_2238_18339()\n    \nend\n\n-- [EVENT][CH1] ENTER_INSTANCE - Cinématique Ogrest 3\n-- \nfunction event_2238_18370()\n    local playerId = Context.getLeaderId()\r\n    Mobile.setMobileVisible(playerId, false)\r\n    local ogrest = createActor(1300060, 1, -26, 40, 4, 3, 16)\r\n    \r\n    setWorldParticleTarget(5000, ogrest, 1)\r\n    \r\n    startCinematicContext(1, ogrest, 210079)\r\n    Camera.setWorldTarget(1, -26, 55)\r\n    invoke_custom(2000, 1, \"Mobile.setMobileAnimation\", ogrest, \"AnimSort-PleurDevastateur\")\r\n    \r\n    ----------------------------------\r\n    \r\n    invoke_custom(6000, 1, \"stopCinematicContext\", 1, ogrest, true)\nend\n\n-- [EVENT][CH1] Fin Cinématique Ogrest 3 - TP Grotte Slek (Eau Luminescente) + Validation OBJ 6924 ACH 3093\n-- \nfunction event_2238_18371()\n    \nend\n\n-- [EVENT][CH1] ENTER_INSTANCE - Cinématique Ogrest 4\n-- \nfunction event_2238_18398()\n    local playerId = Context.getLeaderId()\r\n    Mobile.setMobileVisible(playerId, false)\r\n    local ogrest = createActor(1300060, 1, -26, 40, 4, 3, 16)\r\n    \r\n    setWorldParticleTarget(5000, ogrest, 1)\r\n    \r\n    startCinematicContext(1, ogrest, 210079)\r\n    Camera.setWorldTarget(1, -26, 55)\r\n    invoke_custom(2000, 1, \"Mobile.setMobileAnimation\", ogrest, \"AnimSort-Sanglot\")\r\n    invoke_custom(6000, 1, \"bubble\", ogrest, \"quest.zinit.ch1.cine.ogrest.02\", -30, 180)\r\n    invoke_custom(6000, 1, \"Mobile.setMobileAnimation\", ogrest, \"AnimSort-Tapesol\")\r\n    invoke_custom(7000, 1, \"Effect.createCameraShakeEffect\", 500, 3000, 200, 4)\r\n    \r\n    ----------------------------------\r\n    \r\n    invoke_custom(10500, 1, \"stopCinematicContext\", 1, ogrest, true)\nend\n\n-- [EVENT][CH1] Fin Cinématique Ogrest 4 - TP Bas Flanc (Antidote 2) + Validation OBJ 6768 ACH 3235\n-- \nfunction event_2238_18399()\n    \nend\n\n-- [EVENT][CH1] ENTER_INSTANCE - Cinématique Ogrest 5\n-- \nfunction event_2238_18415()\n    local playerId = Context.getLeaderId()\r\n    Mobile.setMobileVisible(playerId, false)\r\n    local ogrest = createActor(1300060, 1, -26, 40, 4, 3, 16)\r\n    \r\n    setWorldParticleTarget(5000, ogrest, 1)\r\n    \r\n    startCinematicContext(1, ogrest, 210079)\r\n    Camera.setWorldTarget(1, -26, 55)\r\n    invoke_custom(2000, 1, \"bubble\", ogrest, \"quest.zinit.ch1.cine.ogrest.01\", -30, 180)\r\n    invoke_custom(2000, 1, \"Mobile.setMobileAnimation\", ogrest, \"AnimSort-Hurle\")\r\n    invoke_custom(2500, 1, \"Effect.createCameraShakeEffect\", 1000, 500, 1000, 1)\r\n    invoke_custom(5000, 1, \"Mobile.setMobileAnimation\", ogrest, \"AnimSort-PleurDevastateur\")\r\n    \r\n    ----------------------------------\r\n    \r\n    invoke_custom(8000, 1, \"stopCinematicContext\", 1, ogrest, true)\nend\n\n-- [EVENT][CH1] Fin Cinématique Ogrest 5 - TP Bas Flanc (Paroi Lisse) + Validation OBJ 6943 ACH 3241\n-- \nfunction event_2238_18416()\n    \nend\n\n-- [EVENT][CH2] ENTER_INSTANCE - Cinématique Ogrest 6\n-- \nfunction event_2238_18764()\n    local playerId = Context.getLeaderId()\r\n    Mobile.setMobileVisible(playerId, false)\r\n    local ogrest = createActor(1300060, 1, -26, 40, 4, 3, 16)\r\n    \r\n    setWorldParticleTarget(5000, ogrest, 1)\r\n    \r\n    startCinematicContext(1, ogrest, 210079)\r\n    Camera.setWorldTarget(1, -26, 55)\r\n    invoke_custom(2000, 1, \"bubble\", ogrest, \"quest.zinit.ch1.cine.ogrest.01\", -30, 180)\r\n    invoke_custom(2000, 1, \"Mobile.setMobileAnimation\", ogrest, \"AnimSort-Hurle\")\r\n    invoke_custom(2500, 1, \"Effect.createCameraShakeEffect\", 1000, 500, 1000, 1)\r\n    invoke_custom(5000, 1, \"Mobile.setMobileAnimation\", ogrest, \"AnimSort-PleurDevastateur\")\r\n    \r\n    ----------------------------------\r\n    \r\n    invoke_custom(8000, 1, \"stopCinematicContext\", 1, ogrest, true)\nend\n\n-- [EVENT][CH2] Fin Cinématique Ogrest 6 - TP Haut Flanc (Sortie Vaisseau) + Validation OBJ 7404 ACH 3609\n-- \nfunction event_2238_18765()\n    \nend\n\n-- [EVENT][CH2] ENTER_INSTANCE - Cinématique Ogrest 7\n-- \nfunction event_2238_18774()\n    local playerId = Context.getLeaderId()\r\n    Mobile.setMobileVisible(playerId, false)\r\n    local ogrest = createActor(1300060, 1, -26, 40, 4, 3, 16)\r\n    \r\n    setWorldParticleTarget(5000, ogrest, 1)\r\n    \r\n    startCinematicContext(1, ogrest, 210079)\r\n    Camera.setWorldTarget(1, -26, 55)\r\n    invoke_custom(2000, 1, \"bubble\", ogrest, \"quest.zinit.ch1.cine.ogrest.01\", -30, 180)\r\n    invoke_custom(2000, 1, \"Mobile.setMobileAnimation\", ogrest, \"AnimSort-Hurle\")\r\n    invoke_custom(2500, 1, \"Effect.createCameraShakeEffect\", 1000, 500, 1000, 1)\r\n    invoke_custom(5000, 1, \"Mobile.setMobileAnimation\", ogrest, \"AnimSort-PleurDevastateur\")\r\n    \r\n    ----------------------------------\r\n    \r\n    invoke_custom(8000, 1, \"stopCinematicContext\", 1, ogrest, true)\nend\n\n-- [EVENT][CH2] Fin Cinématique Ogrest 7 - TP Haut Flanc (Très Haut Flanc) + Validation OBJ 7422 ACH 3616\n-- \nfunction event_2238_18775()\n    \nend\n\n-- [EVENT][CH3] ENTER_INSTANCE - Cinématique Ogrest 8\n-- \nfunction event_2238_18846()\n    local playerId = Context.getLeaderId()\r\n    Mobile.setMobileVisible(playerId, false)\r\n    local ogrest = createActor(1300060, 1, -26, 40, 4, 3, 16)\r\n    \r\n    setWorldParticleTarget(5000, ogrest, 1)\r\n    \r\n    startCinematicContext(1, ogrest, 210079)\r\n    Camera.setWorldTarget(1, -26, 55)\r\n    invoke_custom(2500, 1, \"bubble\", ogrest, \"quest.zinit.ch1.cine.ogrest.01\", -30, 180)\r\n    invoke_custom(2500, 1, \"Mobile.setMobileAnimation\", ogrest, \"AnimSort-Hurle\")\r\n    invoke_custom(4500, 1, \"Effect.createCameraShakeEffect\", 1000, 500, 1000, 1)\r\n    invoke_custom(6000, 1, \"Mobile.setMobileAnimation\", ogrest, \"AnimSort-Tapesol\")\r\n    invoke_custom(7500, 1, \"Effect.createCameraShakeEffect\", 500, 3000, 200, 4)\r\n    \r\n    ----------------------------------\r\n    \r\n    invoke_custom(11000, 1, \"stopCinematicContext\", 1, ogrest, true)\nend\n\n-- [EVENT][CH3] Fin Cinématique Ogrest 8 - TP Sommet (Arrivée) + Validation OBJ 7446 ACH 3620\n-- \nfunction event_2238_18847()\n    \nend\n\n-- [EVENT][CH3] ENTER_INSTANCE - Cinématique Ogrest 9\n-- \nfunction event_2238_18882()\n    local playerId = Context.getLeaderId()\r\n    Mobile.setMobileVisible(playerId, false)\r\n    local ogrest = createActor(1300060, 1, -26, 40, 4, 3, 16)\r\n    \r\n    setWorldParticleTarget(5000, ogrest, 1)\r\n    \r\n    startCinematicContext(1, ogrest, 210079)\r\n    Camera.setWorldTarget(1, -26, 55)\r\n    invoke_custom(2500, 1, \"bubble\", ogrest, \"quest.zinit.ch1.cine.ogrest.01\", -30, 180)\r\n    invoke_custom(2500, 1, \"Mobile.setMobileAnimation\", ogrest, \"AnimSort-Hurle\")\r\n    invoke_custom(4500, 1, \"Effect.createCameraShakeEffect\", 1000, 500, 1000, 1)\r\n    invoke_custom(6000, 1, \"Mobile.setMobileAnimation\", ogrest, \"AnimSort-Tapesol\")\r\n    invoke_custom(7500, 1, \"Effect.createCameraShakeEffect\", 500, 3000, 200, 4)\r\n    ----------------------------------\r\n    \r\n    invoke_custom(11000, 1, \"stopCinematicContext\", 1, ogrest, true)\nend\n\n-- [EVENT][CH3] Fin Cinématique Ogrest 9 - TP Sommet (Antre Ogrest) + Validation OBJ 7663 ACH 3696\n-- \nfunction event_2238_18883()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_2238_18328","event_2238_18329","event_2238_18330","event_2238_18338","event_2238_18339","event_2238_18370","event_2238_18371","event_2238_18398","event_2238_18399","event_2238_18415","event_2238_18416","event_2238_18764","event_2238_18765","event_2238_18774","event_2238_18775","event_2238_18846","event_2238_18847","event_2238_18882","event_2238_18883"],"quest_calls":[],"dialogue_calls":[]},"scenario/2239.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2239_18340()\n    \nend\n\n-- [EVENT] POSITION_TRIGGER - Exploration Grotte Sauvage - Cinématique Apparition du Gobgob\n-- \nfunction event_2239_18349(gobgobId)\n    local playerId = Context.getLeaderId()\r\n    \r\n    startCinematicContext(2, gobgobId, 210082)\r\n    Mobile.setMobileAnimation(gobgobId, \"AnimStatique\")\r\n    \r\n    invoke_custom(0500, 1, \"setWorldParticleCell\", 3100710, -3, -33, -13)\r\n    invoke_custom(6000, 1, \"setWorldParticleCell\", 15401, -3, -33, -18)\r\n    invoke_custom(6000, 1, \"Mobile.setMobileAnimation\", gobgobId, \"AnimHit\")\r\n    invoke_custom(8000, 1, \"clearWorldParticles\")\r\n    invoke_custom(8000, 1, \"Mobile.setMobileAnimation\", gobgobId, \"AnimSort-OndeDeChoc\")\r\n    \r\n    ----------------------------------\r\n    \r\n    invoke_custom(9200, 1, \"skipCinematic\")\nend\n\n-- [EVENT] Le joueur attaque le Gobgob - Lancement du combat\n-- \nfunction event_2239_18341()\n    \nend\n\n-- [EVENT] Victoire combat Gobgob - Cinématique Gobgob\n-- \nfunction event_2239_18342()\n    local playerId = Context.getLeaderId()\r\n    local gobgobfin = createActor(189504303, -2, -18, -11, 4, 3, 7)\r\n    \r\n    startCinematicContext(1.5, gobgobfin, 210082)\r\n    \r\n    invoke_custom(2000, 1, \"Mobile.setMobileAnimation\", gobgobfin, \"AnimSort-Gobage\")\r\n    invoke_custom(5000, 1, \"setWorldParticleCell\", 800027, -2, -18, -7)\r\n    invoke_custom(8400, 1, \"clearWorldParticles\")\r\n    invoke_custom(8500, 1, \"setWorldParticleCell\", 800270, -2, -18, -11)\r\n    invoke_custom(8500, 1, \"clearActors\")\r\n    invoke_custom(9500, 1, \"setWorldParticleCell\", 800275, -2, -18, -13)\r\n    invoke_custom(12000, 1, \"Camera.attachCameraToMobile\", playerId)\r\n    invoke_custom(12500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    \r\n    ----------------------------------\r\n    \r\n    invoke_custom(17000, 1, \"skipCinematic\")\nend\n\n-- [EVENT] Fin Cinématique Gobgob - TP Cinématique Ogrest 2\n-- \nfunction event_2239_18343()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Masque le Coquillage se déjà récupéré\n-- \nfunction event_2239_18645()\n    \nend\n\n-- [EVENT] Le joueur ramasse le Coquillage - Lancement du combat\n-- \nfunction event_2239_18344()\n    \nend\n\n-- [EVENT] Le joueur gagne le combat Coquillage - Donne le Coquillage + Validation OBJ 6748 ACH 3227\n-- \nfunction event_2239_18345()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_2239_18340","event_2239_18349","event_2239_18341","event_2239_18342","event_2239_18343","event_2239_18645","event_2239_18344","event_2239_18345"],"quest_calls":[],"dialogue_calls":[]},"scenario/2240.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2240_18353()\n    \nend\n\n-- [EVENT] ENTER_INSTANCE - Cinématique Gardes Slek\n-- \nfunction event_2240_18354()\n    local playerId = Context.getLeaderId()\r\n    local slekone = createActor(140001810, 41, -27, 14, 4, 1, 7)\r\n    local slektwo = createActor(140001809, 41, -29, 14, 4, 1, 7)\r\n    local coqueline = createActor(189304271, 44, -21, 16, 4, 1, 7)\r\n    \r\n    \r\n    startCinematicContext(1.5, playerId, 210063)\r\n    \r\n    invoke_custom(2000, 1, \"CoquelineCall\")\r\n    \r\n    function CoquelineCall()\r\n    invoke_custom(1000, 1, \"Mobile.setMobileDirection\", playerId, 5)\r\n    ---\"Quelle drôle de sensation d'utiliser cette baguette.\"\r\n    invoke_custom(1000, 1, \"bubble\", playerId, \"quest.zinit.ch1.cine.slek.grotte.01\")\r\n    invoke_custom(1000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmoteMarket-RougirPlaisir\")\r\n    invoke_custom(1500, 1, \"Mobile.moveMobile\", coqueline, 51, -27, 16)\r\n    invoke_custom(6000, 1, \"clearBubbles\", playerId)\r\n    invoke_custom(6500, 1, \"Mobile.setMobileDirection\", coqueline, 1)\r\n    ---\"MAIS COQUELINE !!! \"\r\n    invoke_custom(7000, 1, \"bubble\", playerId, \"quest.zinit.ch1.cine.slek.grotte.02\")\r\n    invoke_custom(7000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Effrayee\")\r\n    ---\"Comment as-tu fait pour entrer sans la baguette ? \"\r\n    invoke_custom(10000, 1, \"bubble\", playerId, \"quest.zinit.ch1.cine.slek.grotte.03\")\r\n    invoke_custom(10000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(14000, 1, \"clearBubbles\", playerId)\r\n    ---\"Je suis entrée, tout simplement ! \"\r\n    invoke_custom(14500, 1, \"bubble\", coqueline, \"quest.zinit.ch1.cine.slek.grotte.04\")\r\n    invoke_custom(14500, 1, \"Mobile.setMobileAnimation\", coqueline, \"AnimComp-Parler\")\r\n    invoke_custom(16000, 1, \"Mobile.moveMobile\", slekone, 49, -27, 16)\r\n    invoke_custom(16500, 1, \"Mobile.moveMobile\", slektwo, 49, -29, 16)\r\n    invoke_custom(18000, 1, \"clearBubbles\", coqueline)\r\n    ---\"Mais ???\"\r\n    invoke_custom(18100, 1, \"bubble\", playerId, \"quest.zinit.ch1.cine.slek.grotte.05\")\r\n    invoke_custom(18100, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Effrayee\")\r\n    invoke_custom(18500, 1, \"Mobile.setMobileDirection\", coqueline, 5)\r\n    invoke_custom(19000, 1, \"Mobile.setMobileAnimation\", slekone, \"AnimSort-LongBrick\")\r\n    invoke_custom(20000, 1, \"clearBubbles\", playerId)\r\n    invoke_custom(20000, 1, \"Mobile.setMobileAnimation\", slektwo, \"AnimSort03\")\r\n    ---\"~-__~_- !!!\"\r\n    invoke_custom(21000, 1, \"bubble\", slekone, \"quest.zinit.ch1.cine.slek.grotte.06\")\r\n    invoke_custom(21000, 1, \"Mobile.setMobileAnimation\", slekone, \"AnimSort-LongBrick\")\r\n    invoke_custom(23900, 1, \"clearBubbles\", slekone)\r\n    ---\"-~~____--~~~__- !!!\"\r\n    invoke_custom(24000, 1, \"bubble\", slektwo, \"quest.zinit.ch1.cine.slek.grotte.07\")\r\n    invoke_custom(24000, 1, \"Mobile.setMobileAnimation\", slektwo, \"AnimSort03\")\r\n    invoke_custom(28000, 1, \"clearBubbles\", slektwo)\r\n    \r\n    invoke_custom(28000, 1, \"Mobile.moveMobile\", slekone,  41, -27, 14)\r\n    invoke_custom(28500, 1, \"Mobile.moveMobile\", slektwo, 41, -29, 14)\r\n    \r\n    ---\"Que se passe-t-il ?\"\r\n    invoke_custom(29000, 1, \"bubble\", playerId, \"quest.zinit.ch1.cine.slek.grotte.08\")\r\n    invoke_custom(29000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Help\")\r\n    invoke_custom(30000, 1, \"Mobile.setMobileDirection\", coqueline, 1)\r\n    ---\"Pourquoi ne nous attaquent-t-ils pas ?\"\r\n    invoke_custom(31000, 1, \"bubble\", playerId, \"quest.zinit.ch1.cine.slek.grotte.09\")\r\n    invoke_custom(31000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(35000, 1, \"clearBubbles\", playerId)\r\n    ---\"Ils disent qu'il vont prévenir leur Reine de l'arrivée d'étranges créatures.\"\r\n    invoke_custom(35100, 1, \"bubble\", coqueline, \"quest.zinit.ch1.cine.slek.grotte.10\")\r\n    invoke_custom(35100, 1, \"Mobile.setMobileAnimation\", coqueline, \"AnimComp-Non\")\r\n    invoke_custom(40900, 1, \"clearBubbles\", coqueline)\r\n    ---\"Tu parles Slek ?\"\r\n    invoke_custom(41000, 1, \"bubble\", playerId, \"quest.zinit.ch1.cine.slek.grotte.11\")\r\n    invoke_custom(41000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Pointer\")\r\n    invoke_custom(44000, 1, \"clearBubbles\", playerId)\r\n    ---\"Hihihi !\"\r\n    invoke_custom(44100, 1, \"bubble\", coqueline, \"quest.zinit.ch1.cine.slek.grotte.12\")\r\n    invoke_custom(44100, 1, \"Mobile.setMobileAnimation\", coqueline, \"AnimComp-Rire\")\r\n    ---\"Je peux comprendre toutes les créatures vivantes en ce monde !\"\r\n    invoke_custom(46000, 1, \"bubble\", coqueline, \"quest.zinit.ch1.cine.slek.grotte.13\")\r\n    ---\"La preuve, je te comprends parfaitement !\"\r\n    invoke_custom(50000, 1, \"bubble\", coqueline, \"quest