ne.ullu.nage.24\")\r\n    invoke_custom(130000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Multimane-01\")\r\n    ---\"En route vers l'ascension du Mont Zinit !!!\"\r\n    invoke_custom(133000, 1, \"bubble\", playerId, \"quest.zinit.ch1.cine.ullu.nage.25\")\r\n    invoke_custom(133000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Multimane-02\")\r\n    invoke_custom(137000, 1, \"clearBubbles\", playerId)\r\n    ---\"Hihihi ! Bonne chance !\"\r\n    invoke_custom(137500, 1, \"bubble\", coqueline, \"quest.zinit.ch1.cine.ullu.nage.26\")\r\n    invoke_custom(137500, 1, \"Mobile.setMobileAnimation\", coqueline, \"AnimComp-Rire\")\r\n    invoke_custom(138000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Multimane-03\")\r\n    invoke_custom(141000, 1, \"clearBubbles\", coqueline)\r\n    invoke_custom(141000, 1, \"Mobile.moveMobile\", coqueline, -63, 2, 8)\r\n    ---\"Bilbyza, me voilà !!! \"\r\n    invoke_custom(144000, 1, \"bubble\", playerId, \"quest.zinit.ch1.cine.ullu.nage.27\")\r\n    invoke_custom(144000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-BrandirEpeeFlamme\")\r\n    \r\n    ----------------------------------\r\n    \r\n    invoke_custom(148000, 1, \"skipCinematic\")\nend\n\n-- [EVENT] Fin Cinématique Eau Luminescente - TP Cinématique Ogrest 3\n-- \nfunction event_2240_18369()\n    \nend\n\n-- [EVENT] POSITION_TRIGGER - Traverser l'Eau Luminescente - Validation OBJ 6758 ACH 3094\n-- \nfunction event_2240_18372()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_2240_18353","event_2240_18354","CoquelineCall","event_2240_18355","event_2240_18368","event_2240_18369","event_2240_18372"],"quest_calls":[],"dialogue_calls":[]},"scenario/2241.lua":{"source":"\n\n-- [EVENT] Initialisation\n-- \nfunction event_2241_18357()\n    \nend\n\n-- [ACTION] Lancement du combat associé\n-- \nfunction event_2241_18358(GroupId, MobA, MobB, MobC, MobD, MobE, MobF, MobG, MobH, FightId, PlayerId)\n    PlayerId = toLong(PlayerId)\r\n    GroupId =toLong(GroupId)\r\n    FightId = toLong(FightId)\r\n    MobA = toLong(MobA)\r\n    MobB = toLong(MobB)\r\n    MobC = toLong(MobC)\r\n    MobD = toLong(MobD)\r\n    MobE = toLong(MobE)\r\n    MobF = toLong(MobF)\r\n    MobG = toLong(MobG)\r\n    MobH = toLong(MobH)\r\n    \r\n    trace(\"===Valeur de Player Id ======\", PlayerId)\r\n    trace(\"===Valeur de Group Id ======\", GroupId)\r\n    trace(\"===Valeur de Fight Id ======\", FightId)\r\n    trace(\"===Valeur de MobA Id ======\", MobA)\r\n    trace(\"===Valeur de MobB Id ======\", MobB)\r\n    trace(\"===Valeur de MobC Id ======\", MobC)\r\n    trace(\"===Valeur de MobD Id ======\", MobD)\r\n    trace(\"===Valeur de MobE Id ======\", MobE)\r\n    trace(\"===Valeur de MobF Id ======\", MobF)\r\n    trace(\"===Valeur de MobG Id ======\", MobG)\r\n    trace(\"===Valeur de MobH Id ======\", MobH)\nend\n\n-- [ACTION] Fin de combat gagnant\n-- \nfunction event_2241_18359(GroupId)\n    \nend\n\n-- [ACTION] Fin de combat gagnant - fin scenario\n-- \nfunction event_2241_18360(GroupId)\n    \nend\n\n-- [ACTION] Fin de combat perdant\n-- \nfunction event_2241_18361(GroupId, MobA, MobB, MobC)\n    \nend\n\n","functions":["event_2241_18357","event_2241_18358","event_2241_18359","event_2241_18360","event_2241_18361"],"quest_calls":[],"dialogue_calls":[]},"scenario/2242.lua":{"source":"\n\n-- [EVENT] Initialisation\n-- \nfunction event_2242_18363()\n    \nend\n\n-- [ACTION] Lancement du combat associé\n-- \nfunction event_2242_18364(GroupId, MobA, MobB, MobC, MobD, MobE, MobF, MobG, MobH, FightId, PlayerId)\n    PlayerId = toLong(PlayerId)\r\n    GroupId =toLong(GroupId)\r\n    FightId = toLong(FightId)\r\n    MobA = toLong(MobA)\r\n    MobB = toLong(MobB)\r\n    MobC = toLong(MobC)\r\n    MobD = toLong(MobD)\r\n    MobE = toLong(MobE)\r\n    MobF = toLong(MobF)\r\n    MobG = toLong(MobG)\r\n    MobH = toLong(MobH)\r\n    \r\n    trace(\"===Valeur de Player Id ======\", PlayerId)\r\n    trace(\"===Valeur de Group Id ======\", GroupId)\r\n    trace(\"===Valeur de Fight Id ======\", FightId)\r\n    trace(\"===Valeur de MobA Id ======\", MobA)\r\n    trace(\"===Valeur de MobB Id ======\", MobB)\r\n    trace(\"===Valeur de MobC Id ======\", MobC)\r\n    trace(\"===Valeur de MobD Id ======\", MobD)\r\n    trace(\"===Valeur de MobE Id ======\", MobE)\r\n    trace(\"===Valeur de MobF Id ======\", MobF)\r\n    trace(\"===Valeur de MobG Id ======\", MobG)\r\n    trace(\"===Valeur de MobH Id ======\", MobH)\nend\n\n-- [ACTION] Fin de combat gagnant\n-- \nfunction event_2242_18365(GroupId)\n    \nend\n\n-- [ACTION] Fin de combat gagnant - fin scenario\n-- \nfunction event_2242_18366(GroupId)\n    \nend\n\n-- [ACTION] Fin de combat perdant\n-- \nfunction event_2242_18367(GroupId, MobA, MobB, MobC)\n    \nend\n\n","functions":["event_2242_18363","event_2242_18364","event_2242_18365","event_2242_18366","event_2242_18367"],"quest_calls":[],"dialogue_calls":[]},"scenario/2243.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2243_18373()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Application Miasme du Zinit\n-- \nfunction event_2243_18424()\n    \nend\n\n-- [EVENT] ENTER_INSTANCE - Cinématique Otomaï\n-- \nfunction event_2243_18374()\n    local playerId = Context.getLeaderId()\r\n    local otomai = createActor(181404009, 3, -17, 0, 4, 1, 7)\r\n    \r\n    startCinematicContext(1.5, playerId, 210063)\r\n    \r\n    invoke_custom(2000, 1, \"OtomaiCall\")\r\n    \r\n    function OtomaiCall()\r\n    ---\"Je vois que tu ne m'as pas écouté.\"\r\n    invoke_custom(2000, 1, \"bubble\", otomai, \"quest.zinit.ch1.cine.otomai.antidote.01\")\r\n    invoke_custom(2000, 1, \"Mobile.setMobileAnimation\", otomai, \"AnimComp-Special03\")\r\n    ---\"Et que tu es toujours de ce monde !\"\r\n    invoke_custom(6000, 1, \"bubble\", otomai, \"quest.zinit.ch1.cine.otomai.antidote.02\")\r\n    invoke_custom(6000, 1, \"Mobile.setMobileAnimation\", otomai, \"AnimComp-Special07\")\r\n    invoke_custom(10000, 1, \"clearBubbles\", otomai)\r\n    ---\"Je suis plus robuste que ce que vous pensez.\"\r\n    invoke_custom(11000, 1, \"bubble\", playerId, \"quest.zinit.ch1.cine.otomai.antidote.03\")\r\n    invoke_custom(11000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Colere\")\r\n    invoke_custom(15000, 1, \"clearBubbles\", playerId)\r\n    ---\"Je vois ça...\"\r\n    invoke_custom(16000, 1, \"bubble\", otomai, \"quest.zinit.ch1.cine.otomai.antidote.05\")\r\n    invoke_custom(16000, 1, \"Mobile.setMobileAnimation\", otomai, \"AnimComp-Special03\")\r\n    invoke_custom(18000, 1, \"clearBubbles\", otomai)\r\n    ---\"Je vois que tu cours vers une mort certaine.\"\r\n    invoke_custom(19000, 1, \"bubble\", otomai, \"quest.zinit.ch1.cine.otomai.antidote.06\")\r\n    invoke_custom(19000, 1, \"Mobile.setMobileAnimation\", otomai, \"AnimComp-Special04-Debut\")\r\n    ---\"Donc, j'ai pris la décision de te venir en aide.\"\r\n    invoke_custom(23000, 1, \"bubble\", otomai, \"quest.zinit.ch1.cine.otomai.antidote.07\")\r\n    invoke_custom(23000, 1, \"Mobile.setMobileAnimation\", otomai, \"AnimComp-Special07\")\r\n    invoke_custom(28000, 1, \"clearBubbles\", otomai)\r\n    ---\"Une bien sage décision !\"\r\n    invoke_custom(29000, 1, \"bubble\", playerId, \"quest.zinit.ch1.cine.otomai.antidote.08\")\r\n    invoke_custom(29000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Non\")\r\n    invoke_custom(32000, 1, \"clearBubbles\", playerId)\r\n    ---\"Sache qu'ici, les personnes comme toi...\"\r\n    invoke_custom(33000, 1, \"bubble\", otomai, \"quest.zinit.ch1.cine.otomai.antidote.09\")\r\n    invoke_custom(33000, 1, \"Mobile.setMobileAnimation\", otomai, \"AnimComp-Special04-Debut\")\r\n    invoke_custom(37500, 1, \"clearBubbles\", otomai)\r\n    ---\"Comme moi ?\"\r\n    invoke_custom(38500, 1, \"bubble\", playerId, \"quest.zinit.ch1.cine.otomai.antidote.10\")\r\n    invoke_custom(38500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(41500, 1, \"clearBubbles\", playerId)\r\n    ---\"Les personnes normales ne peuvent pas survivre sur le Mont Zinit bien longtemps.\"\r\n    invoke_custom(43000, 1, \"bubble\", otomai, \"quest.zinit.ch1.cine.otomai.antidote.11\")\r\n    invoke_custom(43000, 1, \"Mobile.setMobileAnimation\", otomai, \"AnimComp-Special05-Debut\")\r\n    ---\"Tu es même déjà atteint{[1*]?e:} par le miasme qui le recouvre, car tu y es resté{[1*]?e:} bien trop longtemps !\"\r\n    invoke_custom(49000, 1, \"bubble\", otomai, \"quest.zinit.ch1.cine.otomai.antidote.12\")\r\n    invoke_custom(49000, 1, \"Mobile.setMobileAnimation\", otomai, \"AnimComp-Special10\")\r\n    ---\"Tu risques irrémédiablement ta vie !\"\r\n    invoke_custom(55000, 1, \"bubble\", otomai, \"quest.zinit.ch1.cine.otomai.antidote.13\")\r\n    invoke_custom(55000, 1, \"Mobile.setMobileAnimation\", otomai, \"AnimComp-Special03\")\r\n    invoke_custom(59000, 1, \"clearBubbles\", otomai)\r\n    ---\"DE QUOI !!!\"\r\n    invoke_custom(60000, 1, \"bubble\", playerId, \"quest.zinit.ch1.cine.otomai.antidote.14\")\r\n    invoke_custom(60000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Effrayee\")\r\n    invoke_custom(62500, 1, \"clearBubbles\", playerId)\r\n    ---\"Quel miasme... non ça ne se peut pas !\"\r\n    invoke_custom(63000, 1, \"bubble\", playerId, \"quest.zinit.ch1.cine.otomai.antidote.15\")\r\n    invoke_custom(63000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimComp-Special10\")\r\n    ---\"Il est hors de question que je rebrousse chemin !\"\r\n    invoke_custom(67000, 1, \"bubble\", playerId, \"quest.zinit.ch1.cine.otomai.antidote.16\")\r\n    invoke_custom(67000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Non\")\r\n    invoke_custom(71000, 1, \"clearBubbles\", playerId)\r\n    ---\"Je vais t'aider !\"\r\n    invoke_custom(72000, 1, \"bubble\", otomai, \"quest.zinit.ch1.cine.otomai.antidote.17\")\r\n    invoke_custom(72000, 1, \"Mobile.setMobileAnimation\", otomai, \"AnimComp-Special07\")\r\n    invoke_custom(75000, 1, \"clearBubbles\", otomai)\r\n    ---\"Comment ? Comment me débarasser de ce poison !?!\"\r\n    invoke_custom(76000, 1, \"bubble\", playerId, \"quest.zinit.ch1.cine.otomai.antidote.18\")\r\n    invoke_custom(76000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-AvoirFroid-Boucle\")\r\n    invoke_custom(80000, 1, \"clearBubbles\", playerId)\r\n    ---\"En te fabriquant l'antidote pour t'immuniser contre le miasme !\"\r\n    invoke_custom(81000, 1, \"bubble\", otomai, \"quest.zinit.ch1.cine.otomai.antidote.19\")\r\n    invoke_custom(81000, 1, \"Mobile.setMobileAnimation\", otomai, \"AnimComp-Special04-Debut\")\r\n    invoke_custom(85000, 1, \"clearBubbles\", otomai)\r\n    ---\"Un antidote ?\"\r\n    invoke_custom(86000, 1, \"bubble\", playerId, \"quest.zinit.ch1.cine.otomai.antidote.20\")\r\n    invoke_custom(86000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(89000, 1, \"clearBubbles\", playerId)\r\n    ---\"Oui, un antidote !\"\r\n    invoke_custom(90000, 1, \"bubble\", otomai, \"quest.zinit.ch1.cine.otomai.antidote.21\")\r\n    invoke_custom(90000, 1, \"Mobile.setMobileAnimation\", otomai, \"AnimComp-Special04-Debut\")\r\n    ---\"Mais tu vas devoir récolter toi-même les ingrédients qu'il me faut pour la fabrication !\"\r\n    invoke_custom(93000, 1, \"bubble\", otomai, \"quest.zinit.ch1.cine.otomai.antidote.22\")\r\n    invoke_custom(93000, 1, \"Mobile.setMobileAnimation\", otomai, \"AnimComp-Special05-Debut\")\r\n    invoke_custom(99000, 1, \"clearBubbles\", otomai)\r\n    ---\"Et vous êtes sûr que ça va marcher ?!\"\r\n    invoke_custom(100000, 1, \"bubble\", playerId, \"quest.zinit.ch1.cine.otomai.antidote.23\")\r\n    invoke_custom(100000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmoteMarket-HausseEpaules\")\r\n    invoke_custom(104000, 1, \"clearBubbles\", playerId)\r\n    ---\"Tu mets en doute les capacités du plus célèbre alchimiste du Monde des Douze ?\"\r\n    invoke_custom(105000, 1, \"bubble\", otomai, \"quest.zinit.ch1.cine.otomai.antidote.24\")\r\n    invoke_custom(105000, 1, \"Mobile.setMobileAnimation\", otomai, \"AnimComp-Special06\")\r\n    invoke_custom(111000, 1, \"clearBubbles\", otomai)\r\n    ---\"Euh...non...non...\"\r\n    invoke_custom(112000, 1, \"bubble\", playerId, \"quest.zinit.ch1.cine.otomai.antidote.25\")\r\n    invoke_custom(112000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Calmer\")\r\n    invoke_custom(115000, 1, \"clearBubbles\", playerId)\r\n    ---\"Je dois vous ramener quoi ?\"\r\n    invoke_custom(116000, 1, \"bubble\", playerId, \"quest.zinit.ch1.cine.otomai.antidote.26\")\r\n    invoke_custom(116000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmoteMarket-RougirHonte\")\r\n    invoke_custom(120000, 1, \"clearBubbles\", playerId)\r\n    ---\"Les larmes de mon fils !\"\r\n    invoke_custom(121000, 1, \"bubble\", otomai, \"quest.zinit.ch1.cine.otomai.antidote.27\")\r\n    invoke_custom(121000, 1, \"Mobile.setMobileAnimation\", otomai, \"AnimComp-Special09\")\r\n    invoke_custom(124000, 1, \"clearBubbles\", otomai)\r\n    ---\"DES LARMES D'OGREST !!!\"\r\n    invoke_custom(125000, 1, \"bubble\", playerId, \"quest.zinit.ch1.cine.otomai.antidote.28\")\r\n    invoke_custom(125000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Effrayee\")\r\n    invoke_custom(128000, 1, \"clearBubbles\", playerId)\r\n    ---\"Ne t'inquiète pas, tu ne vas pas le rencontrer de suite.\"\r\n    invoke_custom(129000, 1, \"bubble\", otomai, \"quest.zinit.ch1.cine.otomai.antidote.29\")\r\n    invoke_custom(129000, 1, \"Mobile.setMobileAnimation\", otomai, \"AnimComp-Special10\")\r\n    ---\"Tu serais mort{[1*]?e:} bien avant d'atteindre le sommet.\"\r\n    invoke_custom(133000, 1, \"bubble\", otomai, \"quest.zinit.ch1.cine.otomai.antidote.30\")\r\n    invoke_custom(133000, 1, \"Mobile.setMobileAnimation\", otomai, \"AnimComp-Special03\")\r\n    invoke_custom(137000, 1, \"clearBubbles\", otomai)\r\n    ---\"Rassurant... Ce périple m'enchante...\"\r\n    invoke_custom(138000, 1, \"bubble\", playerId, \"quest.zinit.ch1.cine.otomai.antidote.31\")\r\n    invoke_custom(138000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Defaite\")\r\n    invoke_custom(142000, 1, \"clearBubbles\", playerId)\r\n    ---\"Tu vas pouvoir trouver des larmes sur l'Île Sberg.\"\r\n    invoke_custom(143000, 1, \"bubble\", otomai, \"quest.zinit.ch1.cine.otomai.antidote.32\")\r\n    invoke_custom(143000, 1, \"Mobile.setMobileAnimation\", otomai, \"AnimComp-Special05-Debut\")\r\n    ---\"Certaines fleurs et monstres ont absorbé une infime quantité des pleurs de mon fils. \"\r\n    invoke_custom(147000, 1, \"bubble\", otomai, \"quest.zinit.ch1.cine.otomai.antidote.33\")\r\n    invoke_custom(147000, 1, \"Mobile.setMobileAnimation\", otomai, \"AnimComp-Special04-Debut\")\r\n    invoke_custom(149000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Acquiescer\")\r\n    ---\"Mais ce sera bien suffisant pour fabriquer l'antidote. \"\r\n    invoke_custom(153000, 1, \"bubble\", otomai, \"quest.zinit.ch1.cine.otomai.antidote.34\")\r\n    invoke_custom(153000, 1, \"Mobile.setMobileAnimation\", otomai, \"AnimComp-Special04-Debut\")\r\n    invoke_custom(158000, 1, \"clearBubbles\", otomai)\r\n    ---\"Je ne peux pas prendre l'eau luminescente pour l'antidote ?!\"\r\n    invoke_custom(159000, 1, \"bubble\", playerId, \"quest.zinit.ch1.cine.otomai.antidote.35\")\r\n    invoke_custom(159000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmoteMarket-LeverMain\")\r\n    invoke_custom(164000, 1, \"clearBubbles\", playerId)\r\n    ---\"Non, cette eau là est impure et souillée, je ne peux pas la transmuter.\"\r\n    invoke_custom(165000, 1, \"bubble\", otomai, \"quest.zinit.ch1.cine.otomai.antidote.36\")\r\n    invoke_custom(165000, 1, \"Mobile.setMobileAnimation\", otomai, \"AnimComp-Special08\")\r\n    invoke_custom(171000, 1, \"clearBubbles\", otomai)\r\n    ---\"Il faut que tu trouves les \"Pensées de Dathura\" dans le village enseveli enseveli... \"\r\n    invoke_custom(172000, 1, \"bubble\", otomai, \"quest.zinit.ch1.cine.otomai.antidote.37\")\r\n    invoke_custom(172000, 1, \"Mobile.setMobileAnimation\", otomai, \"AnimComp-Special05-Debut\")\r\n    ---\"Ainsi que le \"Fossoyeur Nostalgique\" dans la tour du cimetière du Château de Harebourg...\"\r\n    invoke_custom(179000, 1, \"bubble\", otomai, \"quest.zinit.ch1.cine.otomai.antidote.38\")\r\n    invoke_custom(179000, 1, \"Mobile.setMobileAnimation\", otomai, \"AnimComp-Special03\")\r\n    ---\"Ils portent en eux des larmes d'Ogrest, pures !\"\r\n    invoke_custom(186000, 1, \"bubble\", otomai, \"quest.zinit.ch1.cine.otomai.antidote.39\")\r\n    invoke_custom(186000, 1, \"Mobile.setMobileAnimation\", otomai, \"AnimComp-Special04-Debut\")\r\n    invoke_custom(190000, 1, \"clearBubbles\", otomai)\r\n    ---\"D'accord, j'y vais de ce pas !\"\r\n    invoke_custom(191000, 1, \"bubble\", playerId, \"quest.zinit.ch1.cine.otomai.antidote.40\")\r\n    invoke_custom(191000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Acquiescer\")\r\n    invoke_custom(194000, 1, \"clearBubbles\", playerId)\r\n    ---\"C'est ta seule chance de pouvoir continuer !\"\r\n    invoke_custom(195000, 1, \"bubble\", otomai, \"quest.zinit.ch1.cine.otomai.antidote.41\")\r\n    invoke_custom(195000, 1, \"Mobile.setMobileAnimation\", otomai, \"AnimComp-Special07\")\r\n    invoke_custom(199000, 1, \"clearBubbles\", otomai)\r\n    ---\"Retrouve-moi ici, sur le bas flanc du Mont Zinit !\"\r\n    invoke_custom(200000, 1, \"bubble\", otomai, \"quest.zinit.ch1.cine.otomai.antidote.42\")\r\n    invoke_custom(200000, 1, \"Mobile.setMobileAnimation\", otomai, \"AnimComp-Special05-Debut\")\r\n    invoke_custom(204000, 1, \"clearBubbles\", otomai)\r\n    ---\"Sur ce !\"\r\n    invoke_custom(205000, 1, \"bubble\", otomai, \"quest.zinit.ch1.cine.otomai.antidote.43\")\r\n    invoke_custom(205000, 1, \"Mobile.setMobileAnimation\", otomai, \"AnimComp-Special09\")\r\n    invoke_custom(207000, 1, \"clearBubbles\", otomai)\r\n    invoke_custom(207000, 1, \"Mobile.moveMobile\", otomai, 5, 0, 0)\r\n    ---\"Allons trouver ces larmes d'Ogrest sur l'Île Sberg !!!\"\r\n    invoke_custom(210000, 1, \"bubble\", playerId, \"quest.zinit.ch1.cine.otomai.antidote.44\")\r\n    invoke_custom(210000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Pointer\")\r\n    invoke_custom(214000, 1, \"Actor.deleteActor\", otomai)\r\n    end\r\n    \r\n    ----------------------------------\r