r\n      local offset = {x=0, y=0}\r\n      if (direction == 1) then offset.x = 1 end\r\n      if (direction == 3) then offset.y = 1 end\r\n      if (direction == 5) then offset.x = -1 end\r\n      if (direction == 7) then offset.y = -1 end\r\n      return offset\r\n    end\r\n    function selectAps(apsIds, direction)\r\n      if (apsIds[1] ~= nil and direction == 1) then return apsIds[1] end\r\n      if (apsIds[2] ~= nil and direction == 3) then return apsIds[2] end\r\n      if (apsIds[3] ~= nil and direction == 5) then return apsIds[3] end\r\n      if (apsIds[4] ~= nil and direction == 7) then return apsIds[4] end\r\n      return 0\r\n    end\r\n    function register_invoke(delay, count, funcName, ...)\r\n      local taskId = invoke(delay, count, funcName, unpack(arg))\r\n      table.insert(tasks, taskId)\r\n    end\r\n    function register_aps(x, y, z)\r\n      local direction = Mobile.getMobileDirection(playerId)\r\n      local offset = getOffset(direction)\r\n      local particleFileId = selectAps(casterApsId, direction)\r\n      local particleId =  Particle.addParticleSystem(particleFileId, x + offset.x, y + offset.y, z)\r\n      table.insert(particles, particleId)\r\n    end\r\n    function kill()\r\n      for key,value in pairs(tasks) do\r\n        interrupt(value)\r\n      end\r\n      for key,value in pairs(particles) do\r\n        Particle.removeParticleSystem(value, true)\r\n      end\r\n    end\r\n    Particle.clearParticleSystemOnMobile(playerId)\r\n    displayCasterAnimation()\r\n    displayTargetAnimation()\r\n    Mobile.onCellTransition(playerId, casterX, casterY, false, \"kill\")\r\n    end\r\n    \r\n    -------------------\r\n    invoke_custom(34000, 1, \"AngeCall\")\r\n    ------------------------------------------------------------------\r\n    function AngeCall()\r\n    casterAnimName = \"AnimEmoteMarket-Angel\"\r\n    casterAnimDelay = 0\r\n    casterApsId = 1162\r\n    casterApsDelay = 0\r\n    targetAnimName = \"\"\r\n    targetAnimDelay = 0\r\n    tasks = {}\r\n    particles = {}\r\n    casterX, casterY, casterZ = Mobile.getMobilePosition(playerId)\r\n    function displayCasterAnimation()\r\n    \tif casterAnimName == \"\" then return end\r\n    \tregister_invoke(casterAnimDelay, 1, \"Mobile.setMobileNext4Direction\", playerId)\r\n    \tregister_invoke(casterAnimDelay, 1, \"Mobile.setMobileAnimation\", playerId, casterAnimName)\r\n    \tregister_invoke(casterApsDelay, 1, \"register_aps\", casterApsId, casterX, casterY, casterZ)\r\n    end\r\n    function displayTargetAnimation()\r\n    \tif targetAnimName == \"\" then return end\r\n    end\r\n    function register_invoke(delay, count, funcName, ...)\r\n    \tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n    \ttable.insert(tasks, taskId)\r\n    end\r\n    function register_aps(particleFileId, x, y, z)\r\n    \tlocal particleId =  Particle.addParticleSystem(particleFileId, x, y, z)\r\n    \ttable.insert(particles, particleId)\r\n    end\r\n    function kill()\r\n    \tfor key,value in pairs(tasks) do\r\n    \t\tinterrupt(value)\r\n    \tend\r\n    \tfor key,value in pairs(particles) do\r\n    \t\tParticle.removeParticleSystem(value, true)\r\n    \tend\r\n    end\r\n    Particle.clearParticleSystemOnMobile(playerId)\r\n    displayCasterAnimation()\r\n    displayTargetAnimation()\r\n    Mobile.onCellTransition(playerId, casterX, casterY, false, \"kill\")\r\n    end\r\n    \r\n    --------------------------------------------------------------------\r\n    \r\n    ---\"Te voilà débarrassé{[1*]?e:} du miasme !\"\r\n    invoke_custom(40000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Fievre\")\r\n    invoke_custom(40000, 1, \"bubble\", otomaiMdcId, \"quest.zinit.ch1.cine.otomai.miasme.deux.08\")\r\n    invoke_custom(40000, 1, \"Mobile.setMobileAnimation\", otomaiMdcId, \"AnimComp-Special04-Debut\")\r\n    invoke_custom(45000, 1, \"clearBubbles\", otomaiMdcId)\r\n    ---\"Tu vas pouvoir continuer ton ascension sans trop de dommages