Id)\n    PlayerId = toLong(PlayerId)\r\n    GroupId =toLong(GroupId)\r\n    FightId = toLong(FightId)\r\n    MobA = toLong(MobA)\r\n    MobB = toLong(MobB)\r\n    MobC = toLong(MobC)\r\n    MobD = toLong(MobD)\r\n    MobE = toLong(MobE)\r\n    MobF = toLong(MobF)\r\n    MobG = toLong(MobG)\r\n    MobH = toLong(MobH)\r\n    \r\n    trace(\"===Valeur de Player Id ======\", PlayerId)\r\n    trace(\"===Valeur de Group Id ======\", GroupId)\r\n    trace(\"===Valeur de Fight Id ======\", FightId)\r\n    trace(\"===Valeur de MobA Id ======\", MobA)\r\n    trace(\"===Valeur de MobB Id ======\", MobB)\r\n    trace(\"===Valeur de MobC Id ======\", MobC)\r\n    trace(\"===Valeur de MobD Id ======\", MobD)\r\n    trace(\"===Valeur de MobE Id ======\", MobE)\r\n    trace(\"===Valeur de MobF Id ======\", MobF)\r\n    trace(\"===Valeur de MobG Id ======\", MobG)\r\n    trace(\"===Valeur de MobH Id ======\", MobH)\nend\n\n-- [ACTION] Fin de combat gagnant\n-- \nfunction event_2273_18614(GroupId)\n    \nend\n\n-- [ACTION] Fin de combat gagnant - fin scenario\n-- \nfunction event_2273_18615(GroupId)\n    \nend\n\n-- [ACTION] Fin de combat perdant\n-- \nfunction event_2273_18616(GroupId, MobA, MobB, MobC)\n    \nend\n\n","functions":["event_2273_18612","event_2273_18613","event_2273_18614","event_2273_18615","event_2273_18616"],"quest_calls":[],"dialogue_calls":[]},"scenario/2274.lua":{"source":"\n\n-- [INIT] Variables Globales\n-- \nfunction event_2274_18633()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2274_18634()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 01\n-- \nfunction event_2274_18635()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 02\n-- \nfunction event_2274_18636()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 03\n-- \nfunction event_2274_18637()\n    \nend\n\n-- Déplace le joueur vers la salle suivante\n-- \nfunction event_2274_18638()\n    \nend\n\n-- [ARCHI] Apparition de l'Archimonstre\n-- \nfunction event_2274_23944()\n    \nend\n\n","functions":["event_2274_18633","event_2274_18634","event_2274_18635","event_2274_18636","event_2274_18637","event_2274_18638","event_2274_23944"],"quest_calls":[],"dialogue_calls":[]},"scenario/2276.lua":{"source":"\n\n-- [EVENT] Initialisation\n-- \nfunction event_2276_18658()\n    \nend\n\n-- [ACTION] Lancement du combat associé\n-- \nfunction event_2276_18659(GroupId, MobA, MobB, MobC, MobD, MobE, MobF, MobG, MobH, FightId, PlayerId)\n    PlayerId = toLong(PlayerId)\r\n    GroupId =toLong(GroupId)\r\n    FightId = toLong(FightId)\r\n    MobA = toLong(MobA)\r\n    MobB = toLong(MobB)\r\n    MobC = toLong(MobC)\r\n    MobD = toLong(MobD)\r\n    MobE = toLong(MobE)\r\n    MobF = toLong(MobF)\r\n    MobG = toLong(MobG)\r\n    MobH = toLong(MobH)\r\n    \r\n    trace(\"===Valeur de Player Id ======\", PlayerId)\r\n    trace(\"===Valeur de Group Id ======\", GroupId)\r\n    trace(\"===Valeur de Fight Id ======\", FightId)\r\n    trace(\"===Valeur de MobA Id ======\", MobA)\r\n    trace(\"===Valeur de MobB Id ======\", MobB)\r\n    trace(\"===Valeur de MobC Id ======\", MobC)\r\n    trace(\"===Valeur de MobD Id ======\", MobD)\r\n    trace(\"===Valeur de MobE Id ======\", MobE)\r\n    trace(\"===Valeur de MobF Id ======\", MobF)\r\n    trace(\"===Valeur de MobG Id ======\", MobG)\r\n    trace(\"===Valeur de MobH Id ======\", MobH)\nend\n\n-- [ACTION] Fin de combat gagnant\n-- \nfunction event_2276_18660(GroupId)\n    \nend\n\n-- [ACTION] Fin de combat gagnant - fin scenario\n-- \nfunction event_2276_18661(GroupId)\n    \nend\n\n-- [ACTION] Fin de combat perdant\n-- \nfunction event_2276_18662(GroupId, MobA, MobB, MobC)\n    \nend\n\n","functions":["event_2276_18658","event_2276_18659","event_2276_18660","event_2276_18661","event_2276_18662"],"quest_calls":[],"dialogue_calls":[]},"scenario/2277.lua":{"source":"bubbleSteleInfoId = 0\r\n\r\n-- Affichage du chemin\r\nfunction displayPath(room)\r\n\tlocal room = toLong(room)\r\n\t\r\n\tif ( room >= 1 or room == -1 ) then\r\n\t\tWorld.setPictoAlpha(-11, -58, 6, 0, 2000)\r\n\t\tWorld.setPictoAlpha(-11, -56, 6, 0, 2000)\r\n\t\tWorld.setPictoAlpha(-11, -54, 6, 0, 2000)\t\r\n\tend\r\nend\r\n\r\n-- A la fermeture d'une pop-up\r\nfunction closeSteleInfo()\r\n\tif (bubbleSteleInfoId ~= nil  and bubbleSteleInfoId ~= 0) then BubbleText.close(bubbleSteleInfoId) end\r\nend\r\n\r\nfunction onSteleInfoClosed()\r\n\tif (bubbleSteleInfoId ~= nil  and bubbleSteleInfoId ~= 0) then bubbleSteleInfoId = 0 end\r\nend\r\n\r\n-- Infos stèles classiques\r\nfunction updateSteleInfo(stateInfoId, forceDisplayUI)\r\n\tif (bubbleSteleInfoId == 0) then\r\n\t\tbubbleSteleInfoId = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_WEST\", 0, -60, false, 2147483647, true, \"interactiveBubbleDialog5\", 30000, 25000, \"onSteleInfoClosed\")\r\n\tend\r\n\r\n\tBubbleText.setText(bubbleSteleInfoId, stateInfoId)\r\n\t\r\n\tif (forceDisplayUI) then BubbleText.show(bubbleSteleInfoId) end\r\nend\r\n\r\n-- Infos stèle d'intervention\r\nfunction updateInterventionInfo(stateInfoId, steleIntervention, forceDisplayUI)\r\n\r\n\tlocal steleIntervention = toLong(steleIntervention)\r\n\r\n\tif (bubbleSteleInfoId == 0) then\r\n\t\tbubbleSteleInfoId = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_WEST\", 0, -60, false, 2147483647, true, \"interactiveBubbleDialog5\", 30000, 25000, \"onSteleInfoClosed\")\r\n\tend\r\n\r\n\tBubbleText.setText(bubbleSteleInfoId, stateInfoId, steleIntervention)\r\n\t\r\n\tif (forceDisplayUI) then BubbleText.show(bubbleSteleInfoId) end\r\nend\r\n\r\n-- Fonction affichage du niveau d'Ecailles à chaque tour\r\nfunction updateFightInfo(steleIntervention, scaleLevel, forceDisplayUI)\r\n\tlocal steleIntervention = toLong(steleIntervention)\r\n\tlocal scaleLevel = toLong(scaleLevel)\r\n\r\n\tif (bubbleFightInfoId == 0) then\r\n\t\tbubbleFightInfoId = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_WEST\", 0, -110, false, 2147483647, true, \"interactiveBubbleDialog5\", 30000, 25000, \"onFightInfoClosed\")\r\n\tend\r\n\r\n\tBubbleText.setText(bubbleFightInfoId, \"aguabrial.fight.player.infos\", steleIntervention, scaleLevel)\r\n\t\r\n\tif (forceDisplayUI) then BubbleText.show(bubbleFightInfoId) end\r\nend\n\n-- [INIT] Variables\n-- \nfunction event_2277_18663()\n    \nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_2277_18664(room)\n    displayPath(room)\nend\n\n-- [EVENT][1] Victoire - Déverouille le passage vers S2\n-- \nfunction event_2277_18665()\n    \nend\n\n-- [EVENT][1] Victoire - Déverouille le passage vers S3\n-- \nfunction event_2277_18666()\n    \nend\n\n-- [EVENT][3] Victoire - Déverouille le passage vers S4\n-- \nfunction event_2277_18667()\n    \nend\n\n-- [EVENT] Salle 4 - Activation du TP de sortie\n-- \nfunction event_2277_18668()\n    \nend\n\n-- [OLD][EVENT] Activation Stèle 1\n-- \nfunction event_2277_18669(steleCount)\n    local steleCount = toLong(steleCount)\r\n    if (steleCount == 1) then rewardId = 27150\r\n    elseif (steleCount == 2) then rewardId = 27125\r\n    elseif (steleCount == 3) then rewardId = 27153\r\n    else rewardId = 0\r\n    end\r\n    \r\n    UI.openRewardsDialog(\"stele.activation\")\r\n    UI.addReward(rewardId)\nend\n\n-- [OLD][EVENT] Activation Stèle 2\n-- \nfunction event_2277_18670(steleCount)\n    local steleCount = toLong(steleCount)\r\n    if (steleCount == 1) then rewardId = 27150\r\n    elseif (steleCount == 2) then rewardId = 27125\r\n    elseif (steleCount == 3) then rewardId = 27153\r\n    else rewardId = 0\r\n    end\r\n    \r\n    UI.openRewardsDialog(\"stele.activation\")\r\n    UI.addReward(rewardId)\nend\n\n-- [OLD][EVENT] Activation Stèle 3\n-- \nfunction event_2277_18671(steleCount)\n    local steleCount = toLong(steleCount)\r\n    if (steleCount == 1) then rewardId = 27150\r\n    elseif (steleCount == 2) then rewardId = 27125\r\n    elseif (steleCount == 3) then rewardId = 27153\r\n    else rewardId = 0\r\n    end\r\n    \r\n    UI.openRewardsDialog(\"stele.activation\")\r\n    UI.addReward(rewardId)\nend\n\n-- [EVENT] Activation Stèle d'intervention\n-- \nfunction event_2277_20831(steleIntervention)\n    local steleIntervention = toLong(steleIntervention)\r\n    \r\n    if (steleIntervention == 1) then\r\n    rewardId = 27126\r\n    rewardTwoId = 27927\r\n    elseif (steleIntervention == 2) then\r\n    rewardId = 27957\r\n    elseif (steleIntervention == 3) then\r\n    rewardId = 27923\r\n    else\r\n    rewardId = 0\r\n    end\r\n    \r\n    UI.openRewardsDialog(\"stele.intervention.description\")\r\n    \r\n    if (steleIntervention == 1) then\r\n    UI.addReward(rewardId)\r\n    UI.addReward(rewardTwoId)\r\n    elseif (steleIntervention == 3) then\r\n    UI.addReward(rewardId, \"stele.intervention.stasis.reward\")\r\n    else\r\n    UI.addReward(rewardId)\r\n    end\r\n    \r\n    local stateInfoId = \"stele.intervention.aguabrial.description\"\r\n    \r\n    updateInterventionInfo(stateInfoId, steleIntervention, true)\nend\n\n-- [OLD][EVENT] Le joueur examine la Stèle 1\n-- \nfunction event_2277_20586(steleCount)\n    local steleCount = toLong(steleCount)\r\n    if (steleCount == 0) then rewardId = 27150\r\n    elseif (steleCount == 1) then rewardId = 27125\r\n    elseif (steleCount == 2) then rewardId = 27153\r\n    else rewardId = 0\r\n    end\r\n    \r\n    UI.openRewardsDialog(\"stele.description\")\r\n    UI.addReward(rewardId)\r\n    \r\n    local stateInfoId = \"stele.state.description.4822\"\r\n    \r\n    updateSteleInfo(stateInfoId, true)\nend\n\n-- [OLD][EVENT] Le joueur examine la Stèle 2\n-- \nfunction event_2277_20587(steleCount)\n    local steleCount = toLong(steleCount)\r\n    if (steleCount == 0) then rewardId = 27150\r\n    elseif (steleCount == 1) then rewardId = 27125\r\n    elseif (steleCount == 2) then rewardId = 27153\r\n    else rewardId = 0\r\n    end\r\n    \r\n    UI.openRewardsDialog(\"stele.description\")\r\n    UI.addReward(rewardId)\r\n    \r\n    local stateInfoId = \"stele.state.description.4823\"\r\n    \r\n    updateSteleInfo(stateInfoId, true)\nend\n\n-- [OLD][EVENT] Le joueur examine la Stèle 3\n-- \nfunction event_2277_20588(steleCount)\n    local steleCount = toLong(steleCount)\r\n    if (steleCount == 0) then rewardId = 27150\r\n    elseif (steleCount == 1) then rewardId = 27125\r\n    elseif (steleCount == 2) then rewardId = 27153\r\n    else rewardId = 0\r\n    end\r\n    \r\n    UI.openRewardsDialog(\"stele.description\")\r\n    UI.addReward(rewardId)\r\n    \r\n    local stateInfoId = \"stele.state.description.4824\"\r\n    \r\n    updateSteleInfo(stateInfoId, true)\nend\n\n-- [EVENT] Le joueur examine la Stèle d'intervention\n-- \nfunction event_2277_20832(steleIntervention)\n    local steleIntervention = toLong(steleIntervention)\r\n    \r\n    if (steleIntervention == 0) then\r\n    rewardId = 27126\r\n    rewardTwoId = 27927\r\n    elseif (steleIntervention == 1) then\r\n    rewardId = 27957\r\n    elseif (steleIntervention == 2) then\r\n    rewardId = 27923\r\n    else\r\n    rewardId = 0\r\n    end\r\n    \r\n    UI.openRewardsDialog(\"stele.intervention.description\")\r\n    \r\n    if (steleIntervention == 0) then\r\n    UI.addReward(rewardId)\r\n    UI.addReward(rewardTwoId)\r\n    elseif (steleIntervention == 2) then\r\n    UI.addReward(rewardId, \"stele.intervention.stasis.reward\")\r\n    else\r\n    UI.addReward(rewardId)\r\n    end\r\n    \r\n    local stateInfoId = \"stele.intervention.aguabrial.description\"\r\n    \r\n    updateInterventionInfo(stateInfoId, steleIntervention, true)\nend\n\n-- [OLD][EVENT] Salle 4 - Refresh des APS pour le porteur des états Stèle\n-- \nfunction event_2277_18672()\n    \nend\n\n-- [EVENT] Salle 4 - Récupère l'ID du combat\n-- \nfunction event_2277_18675()\n    \nend\n\n-- [EVENT] Salle 4 - Reset l'ID du combat\n-- \nfunction event_2277_18676()\n    \nend\n\n-- [EVENT] Démarrage du combat (intervention) - Initialisation des variables\n-- \nfunction event_2277_20833()\n    \nend\n\n-- [EVENT] Démarrage du combat (intervention) - application état Aguabrial\n-- \nfunction event_2277_20835()\n    \nend\n\n-- [EVENT] Fin du combat avec victoire des Joueurs (1 stèle) - Validation Quête\n-- \nfunction event_2277_18677()\n    \nend\n\n-- [EVENT] Fin du combat avec victoire des Joueurs (2 stèles) - Validation Quête\n-- \nfunction event_2277_18678()\n    \nend\n\n-- [EVENT] Fin du combat avec victoire des Joueurs (3 stèles) - Validation Quête\n-- \nfunction event_2277_18679()\n    \nend\n\n-- [OLD][EVENT] DUNGEON_DIFFICULTY_CHANGED - On désactive les états stèles\n-- \nfunction event_2277_20617()\n    \nend\n\n-- [EVENT] Notification Etat Ecailles (intervention) - Mise à jour UI infos de combat\n-- \nfunction event_2277_20834(steleIntervention, scaleLevel)\n    updateFightInfo(steleIntervention, scaleLevel, true)\nend\n\n-- Déplace le joueur vers la salle suivante\n-- \nfunction event_2277_18683()\n    \nend\n\n-- FIGHT_STARTED - Applique l'état \"Salle 1\"\n-- \nfunction event_2277_21968()\n    \nend\n\n-- [STELE] FIGHT_STARTED - On applique les difficultés sur le boss\n-- \nfunction event_2277_22811()\n    \nend\n\n-- [STELE] FIGHT_ENTER_ACTION_PHASE - On applique les bonus sur les joueurs\n-- \nfunction event_2277_22812()\n    \nend\n\n-- [STELE] FIGHT_ENDED - On rend la stèle utilisable en cas de défaite\n-- \nfunction event_2277_22891()\n    \nend\n\n-- [ARCHI] Apparition de l'Archimonstre\n-- \nfunction event_2277_24003()\n    \nend\n\n","functions":["displayPath","closeSteleInfo","onSteleInfoClosed","updateSteleInfo","updateInterventionInfo","updateFightInfo","event_2277_18663","event_2277_18664","event_2277_18665","event_2277_18666","event_2277_18667","event_2277_18668","event_2277_18669","event_2277_18670","event_2277_18671","event_2277_20831","event_2277_20586","event_2277_20587","event_2277_20588","event_2277_20832","event_2277_18672","event_2277_18675","event_2277_18676","event_2277_20833","event_2277_20835","event_2277_18677","event_2277_18678","event_2277_18679","event_2277_20617","event_2277_20834","event_2277_18683","event_2277_21968","event_2277_22811","event_2277_22812","event_2277_22891","event_2277_24003"],"quest_calls":["UI.openRewardsDialog(\"stele.activation\")\r","UI.openRewardsDialog(\"stele.activation\")\r","UI.openRewardsDialog(\"stele.activation\")\r","UI.openRewardsDialog(\"stele.intervention.description\")\r","UI.openRewardsDialog(\"stele.description\")\r","UI.openRewardsDialog(\"stele.description\")\r","UI.openRewardsDialog(\"stele.description\")\r","UI.openRewardsDialog(\"stele.intervention.description\")\r"],"dialogue_calls":[]},"scenario/2278.lua":{"source":"\n\n-- [EVENT] Initialisation\n-- \nfunction event_2278_18685()\n    \nend\n\n-- [ACTION] Lancement du combat associé\n-- \nfunction event_2278_18686(GroupId, MobA, MobB, MobC, MobD, MobE, MobF, MobG, MobH, FightId, PlayerId)\n    PlayerId = toLong(PlayerId)\r\n    GroupId =toLong(GroupId)\r\n    FightId = toLong(FightId)\r\n    MobA = toLong(MobA)\r\n    MobB = toLong(MobB)\r\n    MobC = toLong(MobC)\r\n    MobD = toLong(MobD)\r\n    MobE = toLong(MobE)\r\n    MobF = toLong(MobF)\r\n    MobG = toLong(MobG)\r\n    MobH = toLong(MobH)\r\n    \r\n    trace(\"===Valeur de Player Id ======\", PlayerId)\r\n    trace(\"===Valeur de Group Id ======\", GroupId)\r\n    trace(\"===Valeur de Fight Id ======\", FightId)\r\n    trace(\"===Valeur de MobA Id ======\", MobA)\r\n    trace(\"===Valeur de MobB Id ======\", MobB)\r\n    trace(\"===Valeur de MobC Id ======\", MobC)\r\n    trace(\"===Valeur de MobD Id ======\", MobD)\r\n    trace(\"===Valeur de MobE Id ======\", MobE)\r\n    trace(\"===Valeur de MobF Id ======\", MobF)\r\n    trace(\"===Valeur de MobG Id ======\", MobG)\r\n    trace(\"===Valeur de MobH Id ======\", MobH)\nend\n\n-- [ACTION] Fin de combat gagnant\n-- \nfunction event_2278_18687(GroupId)\n    \nend\n\n-- [ACTION] Fin de combat gagnant - fin scenario\n-- \nfunction event_2278_18688(GroupId)\n    \nend\n\n-- [ACTION] Fin de combat perdant\n-- \nfunction event_2278_18689(GroupId, MobA, MobB, MobC)\n    \nend\n\n","functions":["event_2278_18685","event_2278_18686","event_2278_18687","event_2278_18688","event_2278_18689"],"quest_calls":[],"dialogue_calls":[]},"scenario/2279.lua":{"source":"\n\n-- [EVENT] Initialisation\n-- \nfunction event_2279_18690()\n    \nend\n\n-- [ACTION] Lancement du combat associé\n-- \nfunction event_2279_18691(GroupId, MobA, MobB, MobC, MobD, MobE, MobF, MobG, MobH, FightId, PlayerId)\n    PlayerId = toLong(PlayerId)\r\n    GroupId =toLong(GroupId)\r\n    FightId = toLong(FightId)\r\n    MobA = toLong(MobA)\r\n    MobB = toLong(MobB)\r\n    MobC = toLong(MobC)\r\n    MobD = toLong(MobD)\r\n    MobE = toLong(MobE)\r\n    MobF = toLong(MobF)\r\n    MobG = toLong(MobG)\r\n    MobH = toLong(MobH)\r\n    \r\n    trace(\"===Valeur de Player Id ======\", PlayerId)\r\n    trace(\"===Valeur de Group Id ======\", GroupId)\r\n    trace(\"===Valeur de Fight Id ======\", FightId)\r\n    trace(\"===Valeur de MobA Id ======\", MobA)\r\n    trace(\"===Valeur de MobB Id ======\", MobB)\r\n    trace(\"===Valeur de MobC Id ======\", MobC)\r\n    trace(\"===Valeur de MobD Id ======\", MobD)\r\n    trace(\"===Valeur de MobE Id ======\", MobE)\r\n    trace(\"===Valeur de MobF Id ======\", MobF)\r\n    trace(\"===Valeur de MobG Id ======\", MobG)\r\n    trace(\"===Valeur de MobH Id ======\", MobH)\nend\n\n-- [ACTION] Fin de combat gagnant\n-- \nfunction event_2279_18692(GroupId)\n    \nend\n\n-- [ACTION] Fin de combat gagnant - fin scenario\n-- \nfunction event_2279_18693(GroupId)\n    \nend\n\n-- [ACTION] Fin de combat perdant\n-- \nfunction event_2279_18694(GroupId, MobA, MobB, MobC)\n    \nend\n\n","functions":["event_2279_18690","event_2279_18691","event_2279_18692","event_2279_18693","event_2279_18694"],"quest_calls":[],"dialogue_calls":[]},"scenario/2280.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2280_18695()\n    \nend\n\n-- [EVENT][PRES] ENTER_INSTANCE - CINE Arrivée Vaisseau\n-- \nfunction event_2280_18696()\n     local playerId = Context.getLeaderId()\r\n        local ullu = createActor(1300051, -2, -2, 0, 4, 3, 7)\r\n        Mobile.setMobileVisible(ullu, false)\r\n                \r\n                function apparition()\r\n        \t\tCamera.attachCameraToMobile(playerId)\r\n        \t\tinvoke_custom(2000, 1, \"Particle.addParticleSystem\", 800450, -2, 0, 0, 0)\r\n        \t\tinvoke_custom(2400, 1, \"Mobile.setMobileVisible\", playerId, true)\r\n        \t\tinvoke_custom(2900, 1,\"Sound.stopForcedMusic\")\r\n        \t\tinvoke_custom(3000, 1,\"Sound.playForcedMusic\", 210064)\r\n        \t\tinvoke_custom(3000, 1, \"setWorldParticleCell\", 800202, -2, -2, 1)\r\n        \t\tinvoke_custom(3500, 1, \"Mobile.setMobileVisible\", ullu, true)\r\n        \t\t--Héros de la Prophétie, [#name] ! Bienvenue !\r\n        \t\tinvoke_custom(4000, 1, \"bubble\", ullu, \"quest.zinit.ch2.cine.ullu.vaisseau.01\")\r\n        \t\tinvoke_custom(4000, 1, \"Mobile.setMobileAnimation\", ullu, \"Anim-Comp-Parler01\")\r\n        \t\tinvoke_custom(7500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Coucou\")\r\n        \t\tinvoke_custom(8000, 1, \"clearBubbles\", ullu)\r\n        \t\t--Tu es presque parvenu jusqu'à moi ! Trouve la Salle des Ecrans, je t'y attends !\r\n        \t\tinvoke_custom(9000, 1, \"bubble\", ullu, \"quest.zinit.ch2.cine.ullu.vaisseau.02\")\r\n        \t\tinvoke_custom(9000, 1, \"Mobile.setMobileAnimation\", ullu, \"Anim-Comp-Parler03\")\r\n        \t\tinvoke_custom(13000, 1, \"clearBubbles\", ullu)\r\n    \t\t\tinvoke_custom(13500, 1, \"Mobile.setMobileAnimation\",ullu,\"AnimStatique\")\r\n        \t\tinvoke_custom(13500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmoteMarket-LeverMain\")\r\n        \t\tinvoke_custom(13500, 1, \"setWorldParticleCell\", 800202, -2, -2, 1)\r\n        \t\tinvoke_custom(14500, 1,\"Sound.stopForcedMusic\")\r\n        \t\tinvoke_custom(14600, 1, \"Mobile.setMobileVisible\", ullu , false)\r\n        \t\tinvoke_custom(14600, 1,\"Sound.playForcedMusic\", 210080)\r\n        \t\t end\r\n                \r\n                startCinematicContext(1.5, playerId, 210080)\r\n                Mobile.setMobileVisible(playerId, false)\r\n        \t\tCamera.setCamera(1.5, -3, -16, -4, \"Camera.setMoveSpeedFactor\", 0.3)\r\n            \tinvoke_custom(2500, 1, \"apparition\")\r\n        \r\n                ----------------------------------\r\n                \r\n                invoke_custom(18000, 1, \"skipCinematic\")\nend\n\n-- [EVENT][PRES] END_CINE - Arrivée Vaisseau - Validation OBJ 7498 ACH 3244\n-- \nfunction event_2280_18697()\n    \nend\n\n-- [EVENT][PRES] POS_TRIG - Arrivée Salle Ecrans - Validation OBJ 7499 ACH 3244\n-- \nfunction event_2280_18700()\n    \nend\n\n-- [RECO][PRES] Spawn Gloutovores 1 (Salle Ecrans)\n-- \nfunction event_2280_18701()\n    \nend\n\n-- [EVENT][PRES] DIALOG - Le joueur parle avec Ullu - CINE Rencontre Ullu\n-- \nfunction event_2280_18702(ul