_custom(22000, 1, \"Mobile.setMobileAnimation\", ulluId, \"AnimComp-Non\")\r\n    invoke_custom(26000, 1, \"clearBubbles\", ulluId)\r\n    --\tJ’aurais voulu te dire la vérité plus tôt, mais je n’étais pas certain que tu viendrais à mon secours.\r\n    invoke_custom(27000, 1, \"bubble\", ulluId, \"quest.zinit.ch2.cine.ullu.fin.07\")\r\n    invoke_custom(27000, 1, \"Mobile.setMobileAnimation\", ulluId, \"Anim-Comp-Parler02\")\r\n    invoke_custom(31000, 1, \"clearBubbles\", ulluId)\r\n    --N’en parlons plus.\r\n    invoke_custom(32000, 1, \"bubble\", playerId, \"quest.zinit.ch2.cine.ullu.fin.08\")\r\n    invoke_custom(32000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Calmer\")\r\n    invoke_custom(35000, 1, \"clearBubbles\", playerId)\r\n    --\tJe m’aperçois aujourd’hui que c’était idiot de ma part, tu es quelqu’un de valeureux.\r\n    invoke_custom(36000, 1, \"bubble\", ulluId, \"quest.zinit.ch2.cine.ullu.fin.09\")\r\n    invoke_custom(36000, 1, \"Mobile.setMobileAnimation\", ulluId, \"Anim-Comp-Parler03\")\r\n    invoke_custom(40000, 1, \"clearBubbles\", ulluId)\r\n    --\tMerci mais je voudrais sortir maintenant.\r\n    invoke_custom(41000, 1, \"bubble\", playerId, \"quest.zinit.ch2.cine.ullu.fin.10\")\r\n    invoke_custom(41000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-CroiserBras\")\r\n    invoke_custom(44000, 1, \"clearBubbles\", playerId)\r\n    --\tJ’ai observé tous tes exploits, je t’ai suivi{[1*] ?e :} dans toutes tes aventures !\r\n    invoke_custom(45000, 1, \"bubble\", ulluId, \"quest.zinit.ch2.cine.ullu.fin.11\")\r\n    invoke_custom(45000, 1, \"Mobile.setMobileAnimation\", ulluId, \"AnimComp-Ataaaque\")\r\n    invoke_custom(49000, 1, \"clearBubbles\", ulluId)\r\n    --\t**Même aux toilettes ?!!\r\n    invoke_custom(50000, 1, \"bubble\", playerId, \"quest.zinit.ch2.cine.ullu.fin.12\")\r\n    invoke_custom(50000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-FermerlaBouche-Debut\")\r\n    invoke_custom(53000, 1, \"clearBubbles\", playerId)\r\n    --\tJe n’ai jamais rencontré quelqu’un comme toi ! Tu viendras me rendre visite ?\r\n    invoke_custom(52000, 1, \"bubble\", ulluId, \"quest.zinit.ch2.cine.ullu.fin.13\")\r\n    invoke_custom(52000, 1, \"Mobile.setMobileAnimation\", ulluId, \"Anim-Comp-Parler01\")\r\n    invoke_custom(56000, 1, \"clearBubbles\", ulluId)\r\n    --\tD’accord, mais il faut que je te laisse maintenant !\r\n    invoke_custom(57000, 1, \"bubble\", playerId, \"quest.zinit.ch2.cine.ullu.fin.14\")\r\n    invoke_custom(57000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Presenter\")\r\n    invoke_custom(60000, 1, \"clearBubbles\", playerId)\r\n    --\t**Arrête de parler, s’il te plaît…\r\n    invoke_custom(61000, 1, \"bubble\", playerId, \"quest.zinit.ch2.cine.ullu.fin.15\")\r\n    --invoke_custom(61000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Colere\")\r\n    invoke_custom(64000, 1, \"clearBubbles\", playerId)\r\n    --\tFantastique ! J’ai hâte d’être à notre prochaine rencontre ! A bientôt !\r\n    invoke_custom(65000, 1, \"bubble\", ulluId, \"quest.zinit.ch2.cine.ullu.fin.16\")\r\n    invoke_custom(65000, 1, \"Mobile.setMobileAnimation\", ulluId, \"Anim-Comp-Parler03\")\r\n    invoke_custom(69000, 1, \"clearBubbles\", ulluId)\r\n    end\r\n    \r\n    Mobile.moveMobile(playerId, -11, -231, 0, \"ulluEnd\", ulluId, playerId)\r\n    ----------------------------------\r\n        \r\n    invoke_custom(70000, 1, \"skipCinematic\")\nend\n\n-- [EVENT][PRES] END_CINE Ullu SAS-12 - Validation OBJ 7403 ACH 3609\n-- \nfunction event_2280_18758()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_2280_18695","event_2280_18696","apparition","event_2280_18697","event_2280_18700","event_2280_18701","event_2280_18702","ulluMeet","event_2280_18703","event_2280_18706","event_2280_18707","event_2280_18708","event_2280_18709","event_2280_18710","event_2280_18711","event_2280_18712","event_2280_18734","event_2280_18735","event_2280_18749","event_2280_18751","event_2280_18753","event_2280_18752","event_2280_18759","event_2280_18754","event_2280_18755","event_2280_18756","event_2280_18757","ulluEnd","event_2280_18758"],"quest_calls":[],"dialogue_calls":[]},"scenario/2281.lua":{"source":"bubbleSteleInfoId = 0\r\n\r\nfunction displayPath(room)\r\n\tlocal room = toLong(room)\r\n\t\r\n\tif (room >= 2 or room == -1) then\r\n\t\tWorld.setPictoAlpha(-18, -35, 20, 1, 1000)\r\n\t\tWorld.setPictoAlpha(-19, -35, 20, 1, 1000)\r\n\tend\r\n\r\n\tif (room == -1) then\r\n\t\tWorld.setPictoAlpha(-43, -35, 40, 1, 1000)\r\n\t\tWorld.setPictoAlpha(-44, -35, 40, 1, 1000)\r\n\tend\t\r\nend\r\n\r\n-- A la fermeture d'une pop-up\r\nfunction closeSteleInfo()\r\n\tif (bubbleSteleInfoId ~= nil  and bubbleSteleInfoId ~= 0) then BubbleText.close(bubbleSteleInfoId) end\r\nend\r\n\r\nfunction onSteleInfoClosed()\r\n\tif (bubbleSteleInfoId ~= nil  and bubbleSteleInfoId ~= 0) then bubbleSteleInfoId = 0 end\r\nend\r\n\r\n-- Infos stèles classiques\r\nfunction updateSteleInfo(stateInfoId, forceDisplayUI)\r\n\tif (bubbleSteleInfoId == 0) then\r\n\t\tbubbleSteleInfoId = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_WEST\", 0, -60, false, 2147483647, true, \"interactiveBubbleDialog5\", 30000, 25000, \"onSteleInfoClosed\")\r\n\tend\r\n\r\n\tBubbleText.setText(bubbleSteleInfoId, stateInfoId)\r\n\t\r\n\tif (forceDisplayUI) then BubbleText.show(bubbleSteleInfoId) end\r\nend\r\n\r\n-- Infos stèle d'intervention\r\nfunction updateInterventionInfo(stateInfoId, steleIntervention, forceDisplayUI)\r\n\r\n\tlocal steleIntervention = toLong(steleIntervention)\r\n\r\n\tif (bubbleSteleInfoId == 0) then\r\n\t\tbubbleSteleInfoId = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_WEST\", 0, -60, false, 2147483647, true, \"interactiveBubbleDialog5\", 30000, 25000, \"onSteleInfoClosed\")\r\n\tend\r\n\r\n\tBubbleText.setText(bubbleSteleInfoId, stateInfoId, steleIntervention)\r\n\t\r\n\tif (forceDisplayUI) then BubbleText.show(bubbleSteleInfoId) end\r\nend\r\n\r\n-- Fonction affichage du niveau d'Ecailles à chaque tour\r\nfunction updateFightInfo(steleIntervention, scaleLevel, forceDisplayUI)\r\n\tlocal steleIntervention = toLong(steleIntervention)\r\n\tlocal scaleLevel = toLong(scaleLevel)\r\n\r\n\tif (bubbleFightInfoId == 0) then\r\n\t\tbubbleFightInfoId = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_WEST\", 0, -110, false, 2147483647, true, \"interactiveBubbleDialog5\", 30000, 25000, \"onFightInfoClosed\")\r\n\tend\r\n\r\n\tBubbleText.setText(bubbleFightInfoId, \"aguabrial.fight.player.infos\", steleIntervention, scaleLevel)\r\n\t\r\n\tif (forceDisplayUI) then BubbleText.show(bubbleFightInfoId) end\r\nend\n\n-- [INIT] Variables\n-- \nfunction event_2281_18713()\n    \nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_2281_18714(room)\n    displayPath(room)\nend\n\n-- USER_GROUP_KILLED - Salle 01\n-- \nfunction event_2281_18717()\n    displayPath(room)\nend\n\n-- USER_GROUP_KILLED - Salle 02 - BOSS\n-- \nfunction event_2281_18718()\n    displayPath(room)\nend\n\n-- [OLD][EVENT] Activation Stèle 1\n-- \nfunction event_2281_18719(steleCount)\n    local steleCount = toLong(steleCount)\r\n    if (steleCount == 1) then rewardId = 27121\r\n    elseif (steleCount == 2) then rewardId = 27133\r\n    elseif (steleCount == 3) then rewardId = 27113\r\n    else rewardId = 0\r\n    end\r\n    \r\n    UI.openRewardsDialog(\"stele.activation\")\r\n    UI.addReward(rewardId)\nend\n\n-- [OLD][EVENT] Activation Stèle 2\n-- \nfunction event_2281_18720(steleCount)\n    local steleCount = toLong(steleCount)\r\n    if (steleCount == 1) then rewardId = 27121\r\n    elseif (steleCount == 2) then rewardId = 27133\r\n    elseif (steleCount == 3) then rewardId = 27113\r\n    else rewardId = 0\r\n    end\r\n    \r\n    UI.openRewardsDialog(\"stele.activation\")\r\n    UI.addReward(rewardId)\nend\n\n-- [OLD][EVENT] Activation Stèle 3\n-- \nfunction event_2281_18721(steleCount)\n    local steleCount = toLong(steleCount)\r\n    if (steleCount == 1) then rewardId = 27121\r\n    elseif (steleCount == 2) then rewardId = 27133\r\n    elseif (steleCount == 3) then rewardId = 27113\r\n    else rewardId = 0\r\n    end\r\n    \r\n    UI.openRewardsDialog(\"stele.activation\")\r\n    UI.addReward(rewardId)\nend\n\n-- [EVENT] Activation Stèle d'intervention\n-- \nfunction event_2281_20836(steleIntervention)\n    local steleIntervention = toLong(steleIntervention)\r\n    \r\n    if (steleIntervention == 1) then\r\n    rewardId = 27126\r\n    rewardTwoId = 27927\r\n    elseif (steleIntervention == 2) then\r\n    rewardId = 27958\r\n    elseif (steleIntervention == 3) then\r\n    rewardId = 27924\r\n    else\r\n    rewardId = 0\r\n    end\r\n    \r\n    UI.openRewardsDialog(\"stele.intervention.description\")\r\n    \r\n    if (steleIntervention == 1) then\r\n    UI.addReward(rewardId)\r\n    UI.addReward(rewardTwoId)\r\n    elseif (steleIntervention == 3) then\r\n    UI.addReward(rewardId, \"stele.intervention.stasis.reward\")\r\n    else\r\n    UI.addReward(rewardId)\r\n    end\r\n    \r\n    local stateInfoId = \"stele.intervention.aguabrial.description\"\r\n    \r\n    updateInterventionInfo(stateInfoId, steleIntervention, true)\nend\n\n-- [OLD][EVENT] Le joueur examine la Stèle 1\n-- \nfunction event_2281_20589(steleCount)\n    local steleCount = toLong(steleCount)\r\n    if (steleCount == 0) then rewardId = 27121\r\n    elseif (steleCount == 1) then rewardId = 27133\r\n    elseif (steleCount == 2) then rewardId = 27113\r\n    else rewardId = 0\r\n    end\r\n    \r\n    UI.openRewardsDialog(\"stele.description\")\r\n    UI.addReward(rewardId)\r\n    \r\n    local stateInfoId = \"stele.state.description.4845\"\r\n    \r\n    updateSteleInfo(stateInfoId, true)\nend\n\n-- [OLD][EVENT] Le joueur examine la Stèle 2\n-- \nfunction event_2281_20590(steleCount)\n    local steleCount = toLong(steleCount)\r\n    if (steleCount == 0) then rewardId = 27121\r\n    elseif (steleCount == 1) then rewardId = 27133\r\n    elseif (steleCount == 2) then rewardId = 27113\r\n    else rewardId = 0\r\n    end\r\n    \r\n    UI.openRewardsDialog(\"stele.description\")\r\n    UI.addReward(rewardId)\r\n    local stateInfoId = \"stele.state.description.4846\"\r\n    \r\n    updateSteleInfo(stateInfoId, true)\nend\n\n-- [OLD][EVENT] Le joueur examine la Stèle 3\n-- \nfunction event_2281_20591(steleCount)\n    local steleCount = toLong(steleCount)\r\n    if (steleCount == 0) then rewardId = 27121\r\n    elseif (steleCount == 1) then rewardId = 27133\r\n    elseif (steleCount == 2) then rewardId = 27113\r\n    else rewardId = 0\r\n    end\r\n    \r\n    UI.openRewardsDialog(\"stele.description\")\r\n    UI.addReward(rewardId)\r\n    \r\n    local stateInfoId = \"stele.state.description.4847\"\r\n    \r\n    updateSteleInfo(stateInfoId, true)\nend\n\n-- [EVENT] Le joueur examine la Stèle d'intervention\n-- \nfunction event_2281_20837(steleIntervention)\n    local steleIntervention = toLong(steleIntervention)\r\n    \r\n    if (steleIntervention == 0) then\r\n    rewardId = 27126\r\n    rewardTwoId = 27927\r\n    elseif (steleIntervention == 1) then\r\n    rewardId = 27958\r\n    elseif (steleIntervention == 2) then\r\n    rewardId = 27924\r\n    else\r\n    rewardId = 0\r\n    end\r\n    \r\n    UI.openRewardsDialog(\"stele.intervention.description\")\r\n    \r\n    if (steleIntervention == 0) then\r\n    UI.addReward(rewardId)\r\n    UI.addReward(rewardTwoId)\r\n    elseif (steleIntervention == 2) then\r\n    UI.addReward(rewardId, \"stele.intervention.stasis.reward\")\r\n    else\r\n    UI.addReward(rewardId)\r\n    end\r\n    \r\n    local stateInfoId = \"stele.intervention.aguabrial.description\"\r\n    \r\n    updateInterventionInfo(stateInfoId, steleIntervention, true)\nend\n\n-- [OLD][EVENT] Salle 4 - Refresh des APS pour le porteur des états Stèle\n-- \nfunction event_2281_18722()\n    \nend\n\n-- [EVENT] Salle 4 - Récupère l'ID du combat\n-- \nfunction event_2281_18725()\n    \nend\n\n-- [EVENT] Salle 4 - Reset l'ID du combat\n-- \nfunction event_2281_18726()\n    \nend\n\n-- [EVENT] Démarrage du combat (intervention) - Initialisation des variables\n-- \nfunction event_2281_20838()\n    \nend\n\n-- [EVENT] Démarrage du combat (intervention) - application état Aguabrial\n-- \nfunction event_2281_20839()\n    \nend\n\n-- [EVENT] Démarrage du combat contre le boss - Initialisation des variables\n-- \nfunction event_2281_19996()\n    \nend\n\n-- [EVENT] Fin du combat avec victoire des Joueurs (1 stèle) - Validation Quête\n-- \nfunction event_2281_18727()\n    \nend\n\n-- [EVENT] Fin du combat avec victoire des Joueurs (2 stèles) - Validation Quête\n-- \nfunction event_2281_18728()\n    \nend\n\n-- [EVENT] Fin du combat avec victoire des Joueurs (3 stèles) - Validation Quête\n-- \nfunction event_2281_18729()\n    \nend\n\n-- [COMBAT] 75 cases de Lave sont présentes sur le terrain\n-- \nfunction event_2281_18912()\n    \nend\n\n-- [COMBAT] Victoire des joueurs : plus de 75 cases lave étaient présentes\n-- \nfunction event_2281_18913()\n    \nend\n\n-- [COMBAT] Sor'Hon a l'état Flamme Eternelle niveau 5\n-- \nfunction event_2281_18920()\n    \nend\n\n-- [COMBAT] Victoire des joueurs : Sor'Hon avait l'état niveau 5\n-- \nfunction event_2281_18921(state)\n    \nend\n\n-- Déplace le joueur vers la salle suivante\n-- \nfunction event_2281_18733()\n    \nend\n\n-- [OLD][EVENT] DUNGEON_DIFFICULTY_CHANGED - On désactive les états stèles\n-- \nfunction event_2281_20620()\n    \nend\n\n-- [EVENT] Notification Etat Ecailles (intervention) - Mise à jour UI infos de combat\n-- \nfunction event_2281_20840(steleIntervention, scaleLevel)\n    updateFightInfo(steleIntervention, scaleLevel, true)\nend\n\n-- Application de la mécanique Salle 1\n-- \nfunction event_2281_21918()\n    \nend\n\n-- [STELE] FIGHT_STARTED - On applique les difficultés sur le boss\n-- \nfunction event_2281_22805()\n    \nend\n\n-- [STELE] FIGHT_ENTER_ACTION_PHASE - On applique les bonus sur les joueurs\n-- \nfunction event_2281_22806()\n    \nend\n\n-- [STELE] FIGHT_ENDED - On rend la stèle utilisable en cas de défaite\n-- \nfunction event_2281_22888()\n    \nend\n\n-- [ARCHI] Apparition de l'Archimonstre\n-- \nfunction event_2281_24004()\n    \nend\n\n","functions":["displayPath","closeSteleInfo","onSteleInfoClosed","updateSteleInfo","updateInterventionInfo","updateFightInfo","event_2281_18713","event_2281_18714","event_2281_18717","event_2281_18718","event_2281_18719","event_2281_18720","event_2281_18721","event_2281_20836","event_2281_20589","event_2281_20590","event_2281_20591","event_2281_20837","event_2281_18722","event_2281_18725","event_2281_18726","event_2281_20838","event_2281_20839","event_2281_19996","event_2281_18727","event_2281_18728","event_2281_18729","event_2281_18912","event_2281_18913","event_2281_18920","event_2281_18921","event_2281_18733","event_2281_20620","event_2281_20840","event_2281_21918","event_2281_22805","event_2281_22806","event_2281_22888","event_2281_24004"],"quest_calls":["UI.openRewardsDialog(\"stele.activation\")\r","UI.openRewardsDialog(\"stele.activation\")\r","UI.openRewardsDialog(\"stele.activation\")\r","UI.openRewardsDialog(\"stele.intervention.description\")\r","UI.openRewardsDialog(\"stele.description\")\r","UI.openRewardsDialog(\"stele.description\")\r","UI.openRewardsDialog(\"stele.description\")\r","UI.openRewardsDialog(\"stele.intervention.description\")\r"],"dialogue_calls":[]},"scenario/2282.lua":{"source":"\n\n-- [INIT]\n-- \nfunction event_2282_18738()\n    \nend\n\n","functions":["event_2282_18738"],"quest_calls":[],"dialogue_calls":[]},"scenario/2283.lua":{"source":"\n\n-- [EVENT] Initialisation\n-- \nfunction event_2283_18739()\n    \nend\n\n-- [ACTION] Lancement du combat associé\n-- \nfunction event_2283_18740(GroupId, MobA, MobB, MobC, MobD, MobE, MobF, MobG, MobH, FightId, PlayerId)\n    PlayerId = toLong(PlayerId)\r\n    GroupId =toLong(GroupId)\r\n    FightId = toLong(FightId)\r\n    MobA = toLong(MobA)\r\n    MobB = toLong(MobB)\r\n    MobC = toLong(MobC)\r\n    MobD = toLong(MobD)\r\n    MobE = toLong(MobE)\r\n    MobF = toLong(MobF)\r\n    MobG = toLong(MobG)\r\n    MobH = toLong(MobH)\r\n    \r\n    trace(\"===Valeur de Player Id ======\", PlayerId)\r\n    trace(\"===Valeur de Group Id ======\", GroupId)\r\n    trace(\"===Valeur de Fight Id ======\", FightId)\r\n    trace(\"===Valeur de MobA Id ======\", MobA)\r\n    trace(\"===Valeur de MobB Id ======\", MobB)\r\n    trace(\"===Valeur de MobC Id ======\", MobC)\r\n    trace(\"===Valeur de MobD Id ======\", MobD)\r\n    trace(\"===Valeur de MobE Id ======\", MobE)\r\n    trace(\"===Valeur de MobF Id ======\", MobF)\r\n    trace(\"===Valeur de MobG Id ======\", MobG)\r\n    trace(\"===Valeur de MobH Id ======\", MobH)\nend\n\n-- [ACTION] Fin de combat gagnant\n-- \nfunction event_2283_18741(GroupId)\n    \nend\n\n-- [ACTION] Fin de combat gagnant - fin scenario\n-- \nfunction event_2283_18742(GroupId)\n    \nend\n\n-- [ACTION] Fin de combat perdant\n-- \nfunction event_2283_18743(GroupId, MobA, MobB, MobC)\n    \nend\n\n","functions":["event_2283_18739","event_2283_18740","event_2283_18741","event_2283_18742","event_2283_18743"],"quest_calls":[],"dialogue_calls":[]},"scenario/2284.lua":{"source":"\n\n-- [EVENT] Initialisation\n-- \nfunction event_2284_18744()\n    \nend\n\n-- [ACTION] Lancement du combat associé\n-- \nfunction event_2284_18745(GroupId, MobA, MobB, MobC, MobD, MobE, MobF, MobG, MobH, FightId, PlayerId)\n    PlayerId = toLong(PlayerId)\r\n    GroupId =toLong(GroupId)\r\n    FightId = toLong(FightId)\r\n    MobA = toLong(MobA)\r\n    MobB = toLong(MobB)\r\n    MobC = toLong(MobC)\r\n    MobD = toLong(MobD)\r\n    MobE = toLong(MobE)\r\n    MobF = toLong(MobF)\r\n    MobG = toLong(MobG)\r\n    MobH = toLong(MobH)\r\n    \r\n    trace(\"===Valeur de Player Id ======\", PlayerId)\r\n    trace(\"===Valeur de Group Id ======\", GroupId)\r\n    trace(\"===Valeur de Fight Id ======\", FightId)\r\n    trace(\"===Valeur de MobA Id ======\", MobA)\r\n    trace(\"===Valeur de MobB Id ======\", MobB)\r\n    trace(\"===Valeur de MobC Id ======\", MobC)\r\n    trace(\"===Valeur de MobD Id ======\", MobD)\r\n    trace(\"===Valeur de MobE Id ======\", MobE)\r\n    trace(\"===Valeur de MobF Id ======\", MobF)\r\n    trace(\"===Valeur de MobG Id ======\", MobG)\r\n    trace(\"===Valeur de MobH Id ======\", MobH)\nend\n\n-- [ACTION] Fin de combat gagnant\n-- \nfunction event_2284_18746(GroupId)\n    \nend\n\n-- [ACTION] Fin de combat gagnant - fin scenario\n-- \nfunction event_2284_18747(GroupId)\n    \nend\n\n-- [ACTION] Fin de combat perdant\n-- \nfunction event_2284_18748(GroupId, MobA, MobB, MobC)\n    \nend\n\n","functions":["event_2284_18744","event_2284_18745","event_2284_18746","event_2284_18747","event_2284_18748"],"quest_calls":[],"dialogue_calls":[]},"scenario/2285.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2285_18760()\n    \nend\n\n-- [EVENT] ENTER_INSTANCE - TP Cinématique Ogrest 6\n-- \nfunction event_2285_18761()\n    \nend\n\n-- [EVENT] Examiner la caisse de Silo - Cinématique Caisse Silo\n-- \nfunction event_2285_18766()\n    local playerId = Context.getLeaderId()\r\n        local sacrieur = createActor(187204232, -10, -17, 0, 4, 5, 7)\r\n    \tMobile.moveMobile(sacrieur, -15, -17, 0)\r\n        \r\n        startCinematicContext(1.5, playerId, 210081)\r\n        \r\n        invoke_custom(1000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimInteraction-CoupdePied\")\r\n        -- Qu'est-ce que c'est que ça encore ?\r\n        invoke_custom(3000, 1, \"bubble\", playerId, \"quest.zinit.ch2.cine.caisse.01\")\r\n        invoke_custom(3000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmoteMarket-HausseEpaules\")\r\n        invoke_custom(6000, 1, \"clearBubbles\", playerId)\r\n        -- Des Silos éteints ? Quelqu'un les récupère ?\r\n        invoke_custom(7000, 1, \"bubble\", playerId, \"quest.zinit.ch2.cine.caisse.02\")\r\n        invoke_custom(7000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n        invoke_custom(10000, 1, \"clearBubbles\", playerId)\r\n        invoke_custom(10000, 1, \"Mobile.setMobileLookAt\", playerId, -10, -17)\r\n        --invoke_custom(11000, 1, \"Mobile.moveMobile\", sacrieur, -21, -17, 0)\r\n        invoke_custom(11000, 1, \"Camera.attachCameraToMobile\", sacrieur)\r\n        -- Il faut que j'aille prévenir Maîtresse Kali !\r\n        invoke_custom(13000, 1, \"bubble\", sacrieur, \"quest.zinit.ch2.cine.caisse.03\")\r\n        invoke_custom(16000, 1, \"clearBubbles\", sacrieur)\r\n        invoke_custom(16000, 1, \"Mobile.moveMobile\", sacrieur, -1, -17, 0)\r\n        invoke_custom(20000, 1, \"Mobile.setMobileLookAt\", sacrieur, -10, -17)\r\n        invoke_custom(22000, 1, \"Camera.attachCameraToMobile\", playerId)\r\n        invoke_custom(20500, 1, \"Mobile.moveMobile\", sacrieur, 0, -33, 0, \"Actor.deleteActor\", sacrieur)\r\n        -- Il a bien dit \"Kali\" ? J'ai des comptes à lui rendre...\r\n        invoke_custom(23000, 1, \"bubble\", playerId, \"quest.zinit.ch2.cine.caisse.04\")\r\n        invoke_custom(23000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n        invoke_custom(26000, 1, \"clearBubbles\", playerId)\r\n        -- Je ferais bien de le suivre !\r\n        invoke_custom(27000, 1, \"bubble\", playerId, \"quest.zinit.ch2.cine.caisse.05\")\r\n        invoke_custom(27000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmoteMarket-Avant\")\r\n        invoke_custom(30000, 1, \"clearBubbles\", playerId)\r\n        \r\n        \r\n        ----------------------------------\r\n        \r\n        invoke_custom(31000, 1, \"skipCinematic\")\nend\n\n-- [EVENT] Fin Cinématique Caisse Silo - Validation OBJ 7405 ACH 3610\n-- \nfunction event_2285_18767()\n    \nend\n\n-- [EVENT] POS_TRIG - Suivre le Sacrieur en fuite - Validation OBJ 7406 ACH 3610\n-- \nfunction event_2285_18768()\n    \nend\n\n-- [EVENT] Le joueur entre dans la seconde partie du Haut Flanc - TP Cinématique Ogrest 7\n-- \nfunction event_2285_18773()\n    \nend\n\n-- [EVENT] POS_TRIGGER - Examiner l'entrée de la Grotte du Dor'Mor - Cinématique Grotte du Dor'Mor\n-- \nfunction event_2285_18787()\n    local playerId = Context.getLeaderId()\r\n    \r\n    startCinematicContext(1.5, playerId, 210080)\r\n    \r\n    -- Quelle chaleur infernale !\r\n    invoke_custom(2800, 1, \"Mobile.setMobileDirection\", playerId, 3)\r\n    invoke_custom(3000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-AvoirChaud-Debut\")\r\n    invoke_custom(4500, 1, \"bubble\", playerId, \"quest.zinit.ch2.cine.devant.grotte.01\")\r\n    invoke_custom(8000, 1, \"clearBubbles\", playerId)\r\n    -- Je devrais aller trouver ces capsules dont parlait Kali\r\n    invoke_custom(9000, 1, \"bubble\", playerId, \"quest.zinit.ch2.cine.devant.grotte.02\")\r\n    invoke_custom(12000, 1, \"clearBubbles\", playerId)\r\n    invoke_custom(12000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-AvoirChaud-Fin\")\r\n    \r\n    ----------------------------------\r\n    \r\n    invoke_custom(13000, 1, \"skipCinematic\")\nend\n\n-- [EVENT] Fin Cinématique Grotte du Dor'Mor - Validation OBJ 7428 ACH 3618\n-- \nfunction event_2285_18788()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_2285_18760","event_2285_18761","event_2285_18766","event_2285_18767","event_2285_18768","event_2285_18773","event_2285_18787","event_2285_18788"],"quest_calls":[],"dialogue_calls":[]},"scenario/2286.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2286_18769()\n    \nend\n\n-- [EVENT] ENTER_INSTANCE - Cinématique Passage Grottesque\n-- \nfunction event_2286_18776()\n    local playerId = Context.getLeaderId()\r\n       \r\n    startCinematicContext(1.5, playerId, 210082)\r\n    Camera.setCamera(1.5, 0, -5, 0)\r\n    \r\n    -- Alors voilà cette fameuse roche incassable !\r\n    invoke_custom(3000, 1, \"bubble\", playerId, \"quest.zinit.ch2.cine.grotte.01\")\r\n    invoke_custom(3000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Pointer\")\r\n    invoke_custom(6000, 1, \"clearBubbles\", playerId)\r\n    -- Voyons ce que vaut ce marteau !\r\n    invoke_custom(7000, 1, \"bubble\", playerId, \"quest.zinit.ch2.cine.grotte.02\")\r\n    invoke_custom(7000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-CroiserBras\")\r\n    invoke_custom(10000, 1, \"clearBubbles\", playerId)\r\n    ----------------------------------\r\n        \r\n    invoke_custom(11000, 1, \"skipCinematic\")\nend\n\n-- [EVENT] Fin Cinématique Passage Grottesque - Validation OBJ 7420 ACH 3616\n-- \nfunction event_2286_18777()\n    \nend\n\n-- [EVENT] Le joueur détruit la Roche 1\n-- \nfunction event_2286_18771()\n    InteractiveElement.setAnimation(28105, \"AnimTrans_1_2\")\nend\n\n-- [EVENT] Le joueur détruit la Roche 2\n-- \nfunction event_2286_18772()\n    InteractiveElement.setAnimation(28106, \"AnimTrans_1_2\")\nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_2286_18769","event_2286_18776","event_2286_18777","event_2286_18771","event_2286_18772"],"quest_calls":[],"dialogue_calls":[]},"scenario/2287.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2287_18789()\n    \nend\n\n-- [EVENT] ENTER_INSTANCE - Application Visuel Kit Refroidissement\n-- \nfunction event_2287_18792()\n    \nend\n\n-- [EVENT] ENTER_INSTANCE - Cinématique Arrivée Grotte du Dor'Mor\n-- \nfunction event_2287_18790()\n    local playerId = Context.getLeaderId()\r\n    local kali = createActor(187204217, 1, 0, -60, 4, 5, 7)\r\n    Mobile.setMobileVisible(kali, false)\r\n    \r\n    startCinematicContext(1.5, kali, 210079)\r\n    \r\n    invoke_custom(1000, 1, \"Mobile.setMobileVisible\", kali , true)\r\n    invoke_custom(1000, 1, \"Mobile.moveMobile\", kali, -4, 0, -60)\r\n    invoke_custom(1000, 1, \"Sound.stopForcedMusic\")\r\n    \r\n    invoke_custom(3000, 1, \"Mobile.setMobileDirection\", kali, 1)\r\n    \r\n    -- Hahaha ! Regarde ! Cet endroit est magnifique !\r\n    invoke_custom(4000, 1, \"bubble\", kali, \"quest.zinit.ch2.cine.magma.01\")\r\n    invoke_custom(4000, 1, \"Mobile.setMobileAnimation\", kali, \"AnimComp-Rire\")\r\n    invoke_custom(7000, 1, \"clearBubbles\", kali)\r\n    -- On peut mourir en moins de deux secondes si on fait pas attention !\r\n    invoke_custom(8000, 1, \"bubble\", kali, \"quest.zinit.ch2.cine.magma.02\")\r\n    invoke_custom(8000, 1, \"Mobile.setMobileAnimation\", kali, \"AnimComp-Parler01\")\r\n    invoke_custom(11500, 1, \"clearBubbles\", kali)\r\n    -- Tu trébuches, et PLOUF ! Dans la lave !\r\n    invoke_custom(12000, 1, \"bubble\", kali, \"quest.zinit.ch2.cine.magma.03\")\r\n    invoke_custom(12000, 1, \"Mobile.setMobileAnimation\", kali, \"AnimComp-Provoc\")\r\n    invoke_custom(15000, 1, \"clearBubbles\", kali)\r\n    -- Tout disparaît, il ne reste plus rien de toi !\r\n    invoke_custom(16000, 1, \"bubble\", kali, \"quest.zinit.ch2.cine.magma.04\")\r\n    invoke_custom(16000, 1, \"Mobile.setMobileAnimation\", kali, \"AnimComp-Parler02\")\r\n    invoke_custom(19000, 1, \"clearBubbles\", kali)\r\n    \r\n    invoke_custom(20000, 1, \"Mobile.setMobileDirection\", kali, 5)\r\n    invoke_custom(22000, 1, \"Mobile.setMobileDirection\", kali, 3)\r\n    invoke_custom(24000, 1, \"Mobile.setMobileDirection\", kali, 7)\r\n    invoke_custom(26000, 1, \"Mobile.setMobileDirection\", kali, 1)\r\n    \r\n    -- Bon, je vais m’installer là-bas, ces ruines ont du charme.\r\n    invoke_custom(26000, 1, \"bubble\", kali, \"quest.zinit.ch2.cine.magma.05\")\r\n    invoke_custom(26000, 1, \"Mobile.setMobileAnimation\", kali, \"AnimComp-Parler02\")\r\n    invoke_custom(29000, 1, \"clearBubbles\", kali)\r\n    -- Viens me voir, il faut qu’on discute.\r\n    invoke_custom(30000, 1, \"bubble\", kali, \"quest.zinit.ch2.cine.magma.06\")\r\n    invoke_custom(30000, 1, \"Mobile.setMobileAnimation\", kali, \"AnimComp-Parler01\")\r\n    invoke_custom(33000, 1, \"clearBubbles\", kali)\r\n    invoke_custom(33000, 1, \"Camera.attachCameraToMobile\", playerId)\r\n    \r\n    invoke_custom(33000, 1, \"Mobile.moveMobile\", kali, -4, -3, -60)\r\n    invoke_custom(33800, 1, \"Mobile.moveMobile\", kali, -7, -3, -60)\r\n    invoke_custom(34600, 1, \"Mobile.moveMobile\", kali, -7, -10, -57, \"Actor.deleteActor\", kali)\r\n    ----------------------------------\r\n        \r\n    invoke_custom(36500, 1, \"skipCinematic\")\nend\n\n-- [EVENT] Fin Cinématique Arrivée Grotte du Dor'Mor - Validation OBJ 7435 ACH 3618\n-- \nfunction event_2287_18791()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_2287_18789","event_2287_18792","event_2287_18790","event_2287_18791"],"quest_calls":[],"dialogue_calls":[]},"scenario/2288.lua":{"source":"bubbleSteleInfoId = 0\r\n\r\nfunction closeSteleInfo()\r\n\tif (bubbleSteleInfoId ~= nil  and bubbleSteleInfoId ~= 0) then BubbleText.close(bubbleSteleInfoId) end\r\nend\r\n\r\nfunction onSteleInfoClosed()\r\n\tif (bubbleSteleInfoId ~= nil  and bubbleSteleInfoId ~= 0) then bubbleSteleInfoId = 0 end\r\nend\r\n\r\nfunction updateSteleInfo(stateInfoId, forceDisplayUI)\r\n\r\n\tif (bubbleSteleInfoId == 0) then\r\n\t\tbubbleSteleInfoId = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_WEST\", 0, -60, false, 2147483647, true, \"interactiveBubbleDialog5\", 30000, 25000, \"onSteleInfoClosed\")\r\n\tend\r\n\r\n\tBubbleText.setText(bubbleSteleInfoId, stateInfoId)\r\n\t\r\n\tif (forceDisplayUI) then BubbleText.show(bubbleSteleInfoId) end\r\nend\r\n\r\n-- Fonctions cache / montre\r\nfunction hideMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, false)\r\nend\r\n\r\nfunction showMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, true)\r\nend\r\n\r\nfunction displayMobs(bossId, mobA, mobB, mobC, mobD, mobE, mobF, mobG, room)\r\n\tlocal bossId = toLong(bossId)\r\n\tlocal mobA = toLong(mobA)\r\n\tlocal mobB = toLong(mobB)\r\n\tlocal mobC = toLong(mobC)\r\n\tlocal mobD = toLong(mobD)\r\n\tlocal mobE = toLong(mobE)\r\n\tlocal mobF = toLong(mobF)\r\n\tlocal mobG = toLong(mobG)\r\n\tlocal room = toLong(room)\r\n\r\n\tif (room == 1) then\r\n\t\tMobile.addMobileCreationCallback(bossId, \"hideMonster\", bossId)\r\n\t\tMobile.addMobileCreationCallback(mobA, \"hideMonster\", mobA)\r\n\t\tMobile.addMobileCreationCallback(mobB, \"hideMonster\", mobB)\r\n\t\tMobile.addMobileCreationCallback(mobC, \"hideMonster\", mobC)\r\n\t\tMobile.addMobileCreationCallback(mobD, \"hideMonster\", mobD)\r\n\t\tMobile.addMobileCreationCallback(mobE, \"hideMonster\", mobE)\r\n\t\tMobile.addMobileCreationCallback(mobF, \"hideMonster\", mobF)\r\n\t\tMobile.addMobileCreationCallback(mobG, \"hideMonster\", mobG)\r\n\telse\r\n\t\tMobile.addMobileCreationCallback(bossId, \"showMonster\", bossId)\r\n\t\tMobile.addMobileCreationCallback(mobA, \"showMonster\", mobA)\r\n\t\tMobile.addMobileCreationCallback(mobB, \"showMonster\", mobB)\r\n\t\tMobile.addMobileCreationCallback(mobC, \"showMonster\", mobC)\r\n\t\tMobile.addMobileCreationCallback(mobD, \"showMonster\", mobD)\r\n\t\tMobile.addMobileCreationCallback(mobE, \"showMonster\", mobE)\r\n\t\tMobile.addMobileCreationCallback(mobF, \"showMonster\", mobF)\r\n\t\tMobile.addMobileCreationCallback(mobG, \"showMonster\", mobG)\r\n\tend\r\nend\t\r\n\r\nfunction displayPath(room)\r\n\tlocal room = toLong(room)\r\n\t\r\n\tif 