eleCount == 0) then rewardId = 27128\r\n    elseif (steleCount == 1) then rewardId = 27127\r\n    elseif (steleCount == 2) then rewardId = 27116\r\n    else rewardId = 0\r\n    end\r\n    \r\n    UI.openRewardsDialog(\"stele.description\")\r\n    UI.addReward(rewardId)\r\n    \r\n    local stateInfoId = \"stele.state.description.6078\"\r\n    \r\n    updateSteleInfo(stateInfoId, true)\nend\n\n-- [OLD][EVENT] Le joueur examine la Stèle 2\n-- \nfunction event_2288_20537(steleCount)\n    local steleCount = toLong(steleCount)\r\n    if (steleCount == 0) then rewardId = 27128\r\n    elseif (steleCount == 1) then rewardId = 27127\r\n    elseif (steleCount == 2) then rewardId = 27116\r\n    else rewardId = 0\r\n    end\r\n    \r\n    UI.openRewardsDialog(\"stele.description\")\r\n    UI.addReward(rewardId)\r\n    \r\n    local stateInfoId = \"stele.state.description.6079\"\r\n    \r\n    updateSteleInfo(stateInfoId, true)\nend\n\n-- [OLD][EVENT] Le joueur examine la Stèle 3\n-- \nfunction event_2288_20538(steleCount)\n    local steleCount = toLong(steleCount)\r\n    if (steleCount == 0) then rewardId = 27128\r\n    elseif (steleCount == 1) then rewardId = 27127\r\n    elseif (steleCount == 2) then rewardId = 27116\r\n    else rewardId = 0\r\n    end\r\n    \r\n    UI.openRewardsDialog(\"stele.description\")\r\n    UI.addReward(rewardId)\r\n    \r\n    local stateInfoId = \"stele.state.description.6080\"\r\n    \r\n    updateSteleInfo(stateInfoId, true)\nend\n\n-- [OLD][EVENT] Activation Stèle 1\n-- \nfunction event_2288_20522(steleCount)\n    local steleCount = toLong(steleCount)\r\n    if (steleCount == 1) then rewardId = 27128\r\n    elseif (steleCount == 2) then rewardId = 27127\r\n    elseif (steleCount == 3) then rewardId = 27116\r\n    else rewardId = 0\r\n    end\r\n    \r\n    UI.openRewardsDialog(\"stele.activation\")\r\n    UI.addReward(rewardId)\nend\n\n-- [OLD][EVENT] Activation Stèle 2\n-- \nfunction event_2288_20523(steleCount)\n    local steleCount = toLong(