teInfoId = \"stele.state.description.6084\"\r\n    \r\n    updateSteleInfo(stateInfoId, true)\nend\n\n-- [OLD][EVENT] Activation Stèle 1\n-- \nfunction event_2289_20530(steleCount)\n    local steleCount = toLong(steleCount)\r\n    if (steleCount == 1) then rewardId = 27118\r\n    elseif (steleCount == 2) then rewardId = 27163\r\n    elseif (steleCount == 3) then rewardId = 27159\r\n    else rewardId = 0\r\n    end\r\n    \r\n    UI.openRewardsDialog(\"stele.activation\")\r\n    UI.addReward(rewardId)\nend\n\n-- [OLD][EVENT] Activation Stèle 2\n-- \nfunction event_2289_20531(steleCount)\n    local steleCount = toLong(steleCount)\r\n    if (steleCount == 1) then rewardId = 27118\r\n    elseif (steleCount == 2) then rewardId = 27163\r\n    elseif (steleCount == 3) then rewardId = 27159\r\n    else rewardId = 0\r\n    end\r\n    \r\n    UI.openRewardsDialog(\"stele.activation\")\r\n    UI.addReward(rewardId)\nend\n\n-- [OLD][EVENT] Activation Stèle 3\n-- \nfunction event_2289_20532(steleCount)\n    local steleCount = toLong(steleCount)\r\n    if (steleCount == 1) then rewardId = 27118\r\n    elseif (steleCount == 2) then rewardId = 27163\r\n    elseif (steleCount == 3) then rewardId = 27159\r\n    else rewardId = 0\r\n    end\r\n    \r\n    UI.openRewardsDialog(\"stele.activation\")\r\n    UI.addReward(rewardId)\nend\n\n-- [OLD][EVENT] On lance un combat contre le boss - On rend invisibles les stèles\n-- \nfunction event_2289_20534(room)\n    \nend\n\n-- [OLD][EVENT] On termine un combat contre le boss - On rend visibles les stèles\n-- \nfunction event_2289_20535(room)\n    \nend\n\n-- [OLD][EVENT] DUNGEON_DIFFICULTY_CHANGED - On désactive les états stèles\n-- \nfunction event_2289_20621()\n    \nend\n\n-- FIGHT_ENTER_ACTION_PHASE - Applique l'état \"Donjon\" \n-- \nfunction event_2289_21927()\n    \nend\n\n-- [STELE] FIGHT_STARTED - On applique les difficultés sur le boss\n-- \nfunction event_2289_22793()\n    \nend\n\n-- [STELE] FIGHT_ENTER_ACTION_PHASE - On applique 