ervention, forceDisplayUI)\r\n\r\n\tlocal steleIntervention = toLong(steleIntervention)\r\n\r\n\tif (bubbleSteleInfoId == 0) then\r\n\t\tbubbleSteleInfoId = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_WEST\", 0, -60, false, 2147483647, true, \"interactiveBubbleDialog5\", 30000, 25000, \"onSteleInfoClosed\")\r\n\tend\r\n\r\n\tBubbleText.setText(bubbleSteleInfoId, stateInfoId, steleIntervention)\r\n\t\r\n\tif (forceDisplayUI) then BubbleText.show(bubbleSteleInfoId) end\r\nend\r\n\r\n-- Fonction affichage du niveau d'Ecailles à chaque tour\r\nfunction updateFightInfo(steleIntervention, scaleLevel, forceDisplayUI)\r\n\tlocal steleIntervention = toLong(steleIntervention)\r\n\tlocal scaleLevel = toLong(scaleLevel)\r\n\r\n\tif (bubbleFightInfoId == 0) then\r\n\t\tbubbleFightInfoId = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_WEST\", 0, -110, false, 2147483647, true, \"interactiveBubbleDialog5\", 30000, 25000, \"onFightInfoClosed\")\r\n\tend\r\n\r\n\tBubbleText.setText(bubbleFightInfoId, \"aguabrial.fight.player.infos\", steleIntervention, scaleLevel)\r\n\t\r\n\tif (forceDisplayUI) then BubbleText.show(bubbleFightInfoId) end\r\nend\n\n-- [INIT] Variables\n-- \nfunction event_2290_18816()\n    \nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_2290_18817()\n    \nend\n\n-- Salle 01 - Apparition des Fumerelles\n-- \nfunction event_2290_18820()\n    \nend\n\n-- Salle 02 - Apparition des Fumerelles\n-- \nfunction event_2290_18821()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 01\n-- \nfunction event_2290_18861()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 02 - BOSS\n-- \nfunction event_2290_18869()\n    \nend\n\n-- [OLD][EVENT] Activation Stèle 1\n-- \nfunction event_2290_18856(steleCount)\n    local steleCount = toLong(steleCount)\r\n    if (steleCount == 1) then rewardId = 27164\r\n    elseif (steleCount == 2) then rewardId = 27129\r\n    elseif (steleCount == 3) then rewardId = 27114\r\n    else rewardId = 0\r\n    end\r\n    \r\n    UI.openRewardsDialog(\"stele.activation\")\r\n    UI.addReward(rewardId)\nend\n\n-- [OLD][EVENT] Activation Stèle 2\n-- \nfunction event_2290_18857(steleCount)\n    local steleCount = toLong(steleCount)\r\n    if (steleCount == 1) then rewardId = 27164\r\n    elseif (steleCount == 2) then rewardId = 27129\r\n    elseif (steleCount == 3) then rewardId = 27114\r\n    else rewardId = 1\r\n    end\r\n    \r\n    UI.openRewardsDialog(\"stele.activation\")\r\n    UI.addReward(rewardId)\nend\n\n-- [OLD][EVENT] Activation Stèle 3\n-- \nfunction event_2290_18858(steleCount)\n    local steleCount = toLong(steleCount)\r\n    if (steleCount == 1) then rewardId = 27164\r\n    elseif (steleCount == 2) then rewardId = 27129\r\n    elseif (steleCount == 3) then rewardId = 27114\r\n    else rewardId = 0\r\n    end\r\n    \r\n    UI.openRewardsDialog(\"stele.activation\")\r\n    UI.addReward(rewardId)\nend\n\n-- [EVENT] Activation Stèle d'intervention\n-- \nfunction event_2290_20848(steleIntervention)\n    local steleIntervention = toLong(steleIntervention)\r\n    \r\n    if (steleIntervention == 1) then\r\n    rewardId = 27126\r\n    rewardTwoId = 27927\r\n    elseif (steleIntervention == 2) then\r\n    rewardId = 27960\r\n    elseif (steleIntervention == 3) then\r\n    rewardId = 27926\r\n    else\r\n    rewardId = 0\r\n    end\r\n    \r\n    UI.openRewardsDialog(\"stele.intervention.description\")\r\n    \r\n    if (steleIntervention == 1) then\r\n    UI.addReward(rewardId)\r\n    UI.addReward(rewardTwoId)\r\n    elseif (steleIntervention == 3) then\r\n    UI.addReward(rewardId, \"stele.intervention.stasis.reward\")\r\n    else\r\n    UI.addReward(rewardId)\r\n    end\r\n    \r\n    local stateInfoId = \"stele.intervention.aguabrial.description\"\r\n    \r\n    updateInterventionInfo(stateInfoId, steleIntervention, true)\nend\n\n-- [OLD][EVENT] Le joueur examine la Stèle 1\n-- \nfunction event_2290_20595(steleCount)\n    local steleCount = toLong(steleCount)\r\n    if (steleCount == 0) then rewardId = 27164\r\n    elseif (steleCount == 1) then rewardId = 27129\r\n    elseif (steleCount == 2) then rewardId = 27114\r\n    else rewardId = 0\r\n    end\r\n    \r\n    UI.openRewardsDialog(\"stele.description\")\r\n    UI.addReward(rewardId)\r\n    \r\n    local stateInfoId = \"stele.state.description.4793\"\r\n    \r\n    updateSteleInfo(stateInfoId, true)\nend\n\n-- [OLD][EVENT] Le joueur examine la Stèle 2\n-- \nfunction event_2290_20596(steleCount)\n    local steleCount = toLong(steleCount)\r\n    if (steleCount == 0) then rewardId = 27164\r\n    elseif (steleCount == 1) then rewardId = 27129\r\n    elseif (steleCount == 2) then rewardId = 27114\r\n    else rewardId = 0\r\n    end\r\n    \r\n    UI.openRewardsDialog(\"stele.description\")\r\n    UI.addReward(rewardId)\r\n    \r\n    local stateInfoId = \"stele.state.description.4794\"\r\n    \r\n    updateSteleInfo(stateInfoId, true)\nend\n\n-- [OLD][EVENT] Le joueur examine la Stèle 3\n-- \nfunction event_2290_20597(steleCount)\n    local steleCount = toLong(steleCount)\r\n    if (steleCount == 0) then rewardId = 27164\r\n    elseif (steleCount == 1) then rewardId = 27129\r\n    elseif (steleCount == 2) then rewardId = 27114\r\n    else rewardId = 0\r\n    end\r\n    \r\n    UI.openRewardsDialog(\"stele.description\")\r\n    UI.addReward(rewardId)\r\n    \r\n    local stateInfoId = \"stele.state.description.4795\"\r\n    \r\n    updateSteleInfo(stateInfoId, true)\nend\n\n-- [EVENT] Le joueur examine la Stèle d'intervention\n-- \nfunction event_2290_20849(steleIntervention)\n    local steleIntervention = toLong(steleIntervention)\r\n    \r\n    if (steleIntervention == 0) then\r\n    rewardId = 27126\r\n    rewardTwoId = 27927\r\n    elseif (steleIntervention == 1) then\r\n    rewardId = 27960\r\n    elseif (steleIntervention == 2) then\r\n    rewardId = 27926\r\n    else\r\n    rewardId = 0\r\n    end\r\n    \r\n    UI.openRewardsDialog(\"stele.intervention.description\")\r\n    \r\n    if (steleIntervention == 0) then\r\n    UI.addReward(rewardId)\r\n    UI.addReward(rewardTwoId)\r\n    elseif (steleIntervention == 2) then\r\n    UI.addReward(rewardId, \"stele.intervention.stasis.reward\")\r\n    else\r\n    UI.addReward(rewardId)\r\n    end\r\n    \r\n    local stateInfoId = \"stele.intervention.aguabrial.description\"\r\n    \r\n    updateInterventionInfo(stateInfoId, steleIntervention, true)\nend\n\n-- [OLD][EVENT] Salle 4 - Refresh des APS pour le porteur des états Stèle\n-- \nfunction event_2290_18862()\n    \nend\n\n-- [EVENT] Salle 4 - Récupère l'ID du combat\n-- \nfunction event_2290_18872()\n    \nend\n\n-- [EVENT] Salle 4 - Reset l'ID du combat\n-- \nfunction event_2290_18873()\n    \nend\n\n-- [EVENT] Démarrage du combat (intervention) - Initialisation des variables\n-- \nfunction event_2290_20850()\n    \nend\n\n-- [EVENT] Démarrage du combat (intervention) - application état Aguabrial\n-- \nfunction event_2290_20851()\n    \nend\n\n-- [EVENT] Fin du combat avec victoire des Joueurs (1 stèle) - Validation Quête\n-- \nfunction event_2290_18874()\n    \nend\n\n-- [EVENT] Fin du combat avec victoire des Joueurs (2 stèles) - Validation Quête\n-- \nfunction event_2290_18875()\n    \nend\n\n-- [EVENT] Fin du combat avec victoire des Joueurs (3 stèles) - Validation Quête\n-- \nfunction event_2290_18876()\n    \nend\n\n-- Déplace le joueur vers la salle suivante\n-- \nfunction event_2290_18880()\n    \nend\n\n-- [OLD][EVENT] DUNGEON_DIFFICULTY_CHANGED - On désactive les états stèles\n-- \nfunction event_2290_20619()\n    \nend\n\n-- [EVENT] Notification Etat Ecailles (intervention) - Mise à jour UI infos de combat\n-- \nfunction event_2290_20852(steleIntervention, scaleLevel)\n    updateFightInfo(steleIntervention, scaleLevel, true)\nend\n\n-- Lancement d'un combat - Application de l'état qui gère les cratères\n-- \nfunction event_2290_21917()\n    \nend\n\n-- [STELE] FIGHT_STARTED - On applique les difficultés sur le boss\n-- \nfunction event_2290_22809()\n    \nend\n\n-- [STELE] FIGHT_ENTER_ACTION_PHASE - On applique les bonus sur les joueurs\n-- \nfunction event_2290_22810()\n    \nend\n\n-- [STELE] FIGHT_ENDED - On rend la stèle utilisable en cas de défaite\n-- \nfunction event_2290_22890()\n    \nend\n\n-- [ARCHI] Apparition de l'Archimonstre\n-- \nfunction event_2290_24006()\n    \nend\n\n","functions":["closeSteleInfo","onSteleInfoClosed","updateSteleInfo","updateInterventionInfo","updateFightInfo","event_2290_18816","event_2290_18817","event_2290_18820","event_2290_18821","event_2290_18861","event_2290_18869","event_2290_18856","event_2290_18857","event_2290_18858","event_2290_20848","event_2290_20595","event_2290_20596","event_2290_20597","event_2290_20849","event_2290_18862","event_2290_18872","event_2290_18873","event_2290_20850","event_2290_20851","event_2290_18874","event_2290_18875","event_2290_18876","event_2290_18880","event_2290_20619","event_2290_20852","event_2290_21917","event_2290_22809","event_2290_22810","event_2290_22890","event_2290_24006"],"quest_calls":["UI.openRewardsDialog(\"stele.activation\")\r","UI.openRewardsDialog(\"stele.activation\")\r","UI.openRewardsDialog(\"stele.activation\")\r","UI.openRewardsDialog(\"stele.intervention.description\")\r","UI.openRewardsDialog(\"stele.description\")\r","UI.openRewardsDialog(\"stele.description\")\r","UI.openRewardsDialog(\"stele.description\")\r","UI.openRewardsDialog(\"stele.intervention.description\")\r"],"dialogue_calls":[]},"scenario/2291.lua":{"source":"\n\n-- [INIT] Spawn Monstres - Astrub - Montagnes\n-- \nfunction event_2291_18825()\n    \nend\n\n-- [INIT] Spawn Monstres - Astrub - Champs\n-- \nfunction event_2291_18826()\n    \nend\n\n-- [INIT] Spawn Monstres - Astrub - Plaines\n-- \nfunction event_2291_18827()\n    \nend\n\n-- [INIT] Spawn Monstres - Astrub - Cimetière\n-- \nfunction event_2291_18828()\n    \nend\n\n-- [INIT] Spawn Monstres - Astrub - Forêt\n-- \nfunction event_2291_18829()\n    \nend\n\n-- [INIT] Spawn Monstres - Astrub - Tainela\n-- \nfunction event_2291_18830()\n    \nend\n\n-- [INIT] Spawn Monstres - Bilbyza\n-- \nfunction event_2291_18836()\n    \nend\n\n","functions":["event_2291_18825","event_2291_18826","event_2291_18827","event_2291_18828","event_2291_18829","event_2291_18830","event_2291_18836"],"quest_calls":[],"dialogue_calls":[]},"scenario/2292.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2292_18844()\n    \nend\n\n-- [EVENT] ENTER_INSTANCE - TP Cinématique Ogrest 8\n-- \nfunction event_2292_18845()\n    \nend\n\n-- [EVENT] Observer le Dragoeuf endormi - Cinématique Dragoeuf endormi\n-- \nfunction event_2292_18851()\n    local playerId = Context.getLeaderId()\r\n    \r\n    startCinematicContext(1.5, playerId, 210023)\r\n    \r\n    Mobile.setMobileDirection(playerId, 7)\r\n    invoke_custom(1000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Chercher\")\r\n    \r\n    ----------------------------------\r\n    \r\n    invoke_custom(5000, 1, \"skipCinematic\")\nend\n\n-- [EVENT] Fin Cinématique Dragoeuf endormi - Validation OBJ 7615 ACH 3682\n-- \nfunction event_2292_18852()\n    \nend\n\n-- [EVENT] POS_TRIG - Trouver la source de leur fatigue - Cinématique Noxine\n-- \nfunction event_2292_18848()\n    local playerId = Context.getLeaderId()\r\n    local noxineId = createActor(189504394, -46, -83, 20, 4, 1, 2)\r\n    local dragOneId = createActor(186704208, -46, -86, 20, 4, 1, 6)\r\n    local dragTwoId = createActor(186704208, -51, -85, 20, 4, 1, 6)\r\n    \r\n    startCinematicContext(1, noxineId, 210080)\r\n    \r\n    invoke_custom(1000, 1, \"Mobile.moveMobile\", noxineId, -46, -85, 20)\r\n    invoke_custom(4000, 1, \"Mobile.setMobileAnimation\", noxineId, \"AnimSort-AspiWakfu\")\r\n    invoke_custom(4000, 1, \"Particle.addParticleSystemToTarget\", -1548037640, noxineId) \r\n    invoke_custom(5000, 1, \"bubble\", playerId, \"quest.zinit.ch3.cine.noxine.01\")\r\n    \r\n    invoke_custom(6000, 1, \"Mobile.moveMobile\", noxineId, -50, -85, 20)\r\n    \r\n    invoke_custom(8000, 1, \"Mobile.setMobileDirection\", noxineId, 5)\r\n    invoke_custom(8000, 1, \"Mobile.setMobileAnimation\", noxineId, \"AnimSort-AspiWakfu\")\r\n    invoke_custom(8000, 1, \"Particle.addParticleSystemToTarget\", -1548037640, noxineId)\r\n    \r\n    invoke_custom(10000, 1, \"Mobile.moveMobile\", noxineId, -40, -84, 20)\r\n    \r\n    invoke_custom(11000, 1, \"bubble\", playerId, \"quest.zinit.ch3.cine.noxine.02\")\r\n    ----------------------------------\r\n    \r\n    invoke_custom(14000, 1, \"skipCinematic\")\nend\n\n-- [EVENT] Fin Cinématique Noxine - Validation OBJ 7626 ACH 3684\n-- \nfunction event_2292_18849()\n    \nend\n\n-- [EVENT] POS_TRIG - Lancement du combat Noxine\n-- \nfunction event_2292_18850()\n    \nend\n\n-- [EVENT] Le joueur veut fabriquer la Potion Somnifère - Cinématique Potion Somnifère\n-- \nfunction event_2292_18854(otomaiMdcId)\n    local playerId = Context.getLeaderId()\r\n    local otomaiMdcId = toLong(otomaiMdcId)\r\n    startCinematicContext(1.5, playerId, 210001)\r\n    \r\n    ---\"Parfait !\"\r\n    invoke_custom(2000, 1, \"bubble\", otomaiMdcId, \"quest.zinit.ch3.cine.otomai.somnifere.01\")\r\n    invoke_custom(2000, 1, \"Mobile.setMobileAnimation\", otomaiMdcId, \"AnimComp-Special07\")\r\n    ---\"Je vais pouvoir préparer le somnifère !\"\r\n    invoke_custom(5000, 1, \"bubble\", otomaiMdcId, \"quest.zinit.ch3.cine.otomai.somnifere.02\")\r\n    invoke_custom(5000, 1, \"Mobile.setMobileAnimation\", otomaiMdcId, \"AnimComp-Special04-Debut\")\r\n    invoke_custom(9000, 1, \"clearBubbles\", otomaiMdcId)\r\n    invoke_custom(9000, 1, \"Mobile.setMobileDirection\", otomaiMdcId, 5)\r\n    invoke_custom(9000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Acquiescer\")\r\n    ---\"Juste un petit moment.\"\r\n    invoke_custom(10000, 1, \"bubble\", otomaiMdcId, \"quest.zinit.ch3.cine.otomai.somnifere.03\")\r\n    invoke_custom(10000, 1, \"Mobile.setMobileAnimation\", otomaiMdcId, \"AnimStatique02\")\r\n    invoke_custom(13000, 1, \"clearBubbles\", otomaiMdcId)\r\n    invoke_custom(13000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    ---\"Un instant...\"\r\n    invoke_custom(13500, 1, \"bubble\", otomaiMdcId, \"quest.zinit.ch3.cine.otomai.somnifere.04\")\r\n    invoke_custom(13500, 1, \"Mobile.setMobileAnimation\", otomaiMdcId, \"AnimSort-01\")\r\n    invoke_custom(14500, 1, \"setWorldParticleCell\", 1001, 4, 5, 4) --(mauvaises coordonnées : à changer)\r\n    invoke_custom(14600, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Effrayee\")\r\n    invoke_custom(14700, 1, \"setWorldParticleCell\", 1002, 4, 5, 4) --(mauvaises coordonnées : à changer)\r\n    invoke_custom(14800, 1, \"setWorldParticleCell\", 1003, 4, 5, 4) --(mauvaises coordonnées : à changer)\r\n    invoke_custom(15000, 1, \"setWorldParticleCell\", 1008, 4, 5, 4) --(mauvaises coordonnées : à changer)\r\n    invoke_custom(15500, 1, \"setWorldParticleCell\", 1007, 4, 5, 4) --(mauvaises coordonnées : à changer)\r\n    invoke_custom(16000, 1, \"setWorldParticleCell\", 1152, 4, 5, 4) --(mauvaises coordonnées : à changer)\r\n    invoke_custom(16000, 1, \"clearBubbles\", otomaiMdcId)\r\n    invoke_custom(16300, 1, \"Mobile.setMobileDirection\", otomaiMdcId, 1)\r\n    ---\"Aahh !!!\"\r\n    invoke_custom(16500, 1, \"bubble\", otomaiMdcId, \"quest.zinit.ch3.cine.otomai.somnifere.05\")\r\n    invoke_custom(16500, 1, \"Mobile.setMobileAnimation\", otomaiMdcId, \"AnimComp-Special11\")\r\n    invoke_custom(17500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(19000, 1, \"clearBubbles\", otomaiMdcId)\r\n    ---\"Voilà la Potion de Somnifère !\"\r\n    invoke_custom(20000, 1, \"bubble\", otomaiMdcId, \"quest.zinit.ch3.cine.otomai.somnifere.06\")\r\n    invoke_custom(23000, 1, \"clearBubbles\", otomaiMdcId)\r\n    invoke_custom(23900, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmoteMarket-HausseEpaules\")\r\n    ---\"Tiens prends-la !\"\r\n    invoke_custom(24000, 1, \"bubble\", otomaiMdcId, \"quest.zinit.ch3.cine.otomai.somnifere.07\")\r\n    invoke_custom(24000, 1, \"Mobile.setMobileAnimation\", otomaiMdcId, \"AnimComp-Special07\")\r\n    invoke_custom(27000, 1, \"clearBubbles\", otomaiMdcId)\r\n    invoke_custom(28000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Acquiescer\")\r\n    ---\"Ce somnifère est très puissant !\"\r\n    invoke_custom(30000, 1, \"bubble\", otomaiMdcId, \"quest.zinit.ch3.cine.otomai.somnifere.08\")\r\n    invoke_custom(30000, 1, \"Mobile.setMobileAnimation\", otomaiMdcId, \"AnimComp-Special04-Debut\")\r\n    invoke_custom(33000, 1, \"clearBubbles\", otomaiMdcId)\r\n    ---\"Il te suffit d'asperger le Dragoeuf de la grotte pour qu'il fasse de jolis songes !\"\r\n    invoke_custom(34000, 1, \"bubble\", otomaiMdcId, \"quest.zinit.ch3.cine.otomai.somnifere.09\")\r\n    invoke_custom(34000, 1, \"Mobile.setMobileAnimation\", otomaiMdcId, \"AnimComp-Special05-Debut\")\r\n    invoke_custom(40000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    ---\"Tu n'as aucune crainte à avoir.\"\r\n    invoke_custom(41000, 1, \"bubble\", otomaiMdcId, \"quest.zinit.ch3.cine.otomai.somnifere.10\")\r\n    invoke_custom(40000, 1, \"Mobile.setMobileAnimation\", otomaiMdcId, \"AnimComp-Special03\")\r\n    invoke_custom(43000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Acquiescer\")\r\n    invoke_custom(44000, 1, \"clearBubbles\", otomaiMdcId)\r\n    ---\"Mes potions sont sûres à 100% !\"\r\n    invoke_custom(45000, 1, \"bubble\", otomaiMdcId, \"quest.zinit.ch3.cine.otomai.somnifere.11\")\r\n    invoke_custom(45000, 1, \"Mobile.setMobileAnimation\", otomaiMdcId, \"AnimComp-Special04-Debut\")\r\n    invoke_custom(49000, 1, \"clearBubbles\", otomaiMdcId)\r\n    ---\"Allons endormir ce Dragoeuf dans la grotte !\"\r\n    invoke_custom(50000, 1, \"bubble\", playerId, \"quest.zinit.ch3.cine.otomai.somnifere.12\")\r\n    invoke_custom(50500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Pointer\")\r\n    \r\n    ----------------------------------\r\n    invoke_custom(55000, 1, \"skipCinematic\")\nend\n\n-- [EVENT] Fin Cinématique Potion Somnifère - Validation OBJ 7649 ACH 3691\n-- \nfunction event_2292_18855()\n    \nend\n\n-- [EVENT] Le joueur veut fabriquer le Vapeurisateur de Reviens - Cinématique Vapeurisateur de Reviens\n-- \nfunction event_2292_18867(otomaiMdcId)\n    local playerId = Context.getLeaderId()\r\n    local otomaiMdcId = toLong(otomaiMdcId)\r\n    startCinematicContext(1.2, playerId, 210001)\r\n    \r\n    ---\"Bien !\"\r\n    invoke_custom(2000, 1, \"bubble\", otomaiMdcId, \"quest.zinit.ch3.cine.otomai.vapeurisateur.un.01\")\r\n    invoke_custom(2000, 1, \"Mobile.setMobileAnimation\", otomaiMdcId, \"AnimComp-Special07\")\r\n    ---\"Voilà les ingrédients.\"\r\n    invoke_custom(5000, 1, \"bubble\", otomaiMdcId, \"quest.zinit.ch3.cine.otomai.vapeurisateur.un.02\")\r\