ustom(2000, 1, \"Mobile.setMobileAnimation\", otomaiMdcId, \"AnimComp-Special07\")\r\n    invoke_custom(4000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Acquiescer\")\r\n    ---\"Je savais bien que mes recherches à ce sujet seraient utiles\"\r\n    invoke_custom(6000, 1, \"bubble\", otomaiMdcId, \"quest.zinit.ch3.cine.otomai.neige.poudre.02\")\r\n    invoke_custom(6000, 1, \"Mobile.setMobileAnimation\", otomaiMdcId, \"AnimComp-Special04-Debut\")\r\n    --\"Si la puissance d'Ogrest est trop forte, cela te permettra de ne pas être désincarner\"\r\n    invoke_custom(10000, 1, \"bubble\", otomaiMdcId, \"quest.zinit.ch3.cine.otomai.neige.poudre.03\")\r\n    invoke_custom(10000, 1, \"Mobile.setMobileAnimation\", otomaiMdcId, \"AnimComp-Special07\")\r\n    --\"Ainsi tu évites un retour à Incarnam\"\r\n    invoke_custom(14000, 1, \"bubble\", otomaiMdcId, \"quest.zinit.ch3.cine.otomai.neige.poudre.04\")\r\n    invoke_custom(14000, 1, \"Mobile.setMobileAnimation\", otomaiMdcId, \"AnimComp-Special07\")\r\n    --\"Tu t'attendais à quoi ? Une arme spéciale pour en venir à bout ? Et bien non, c'est le moment de montrer que les Dieux ont eu raison\"\r\n    invoke_custom(18000, 1, \"bubble\", otomaiMdcId, \"quest.zinit.ch3.cine.otomai.neige.poudre.05\")\r\n    invoke_custom(18000, 1, \"Mobile.setMobileAnimation\", otomaiMdcId, \"AnimComp-Special07\")\r\n    invoke_custom(20000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Acquiescer\")\r\n    \r\n    ----------------------------------\r\n    \r\n    invoke_custom(20000, 1, \"skipCinematic\")\nend\n\n-- [EVENT] Fin Cinématique Neige Eternelle - Validation OBJ 7662 ACH 3695\n-- \nfunction event_2292_18871()\n    \nend\n\n-- [EVENT] POS_TRIG - Se rendre devant l'antre menant à Ogrest - TP Cinématique Ogrest 9\n-- \nfunction event_2292_18881()\n    \nend\n\n-- [EVENT] GENERIC - Lancement du combat Vapeur\n-- \nfunction event_2292_19036()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks"