ntion)\r\n\r\n\tif (bubbleSteleInfoId == 0) then\r\n\t\tbubbleSteleInfoId = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_WEST\", 0, -60, false, 2147483647, true, \"interactiveBubbleDialog5\", 30000, 25000, \"onSteleInfoClosed\")\r\n\tend\r\n\r\n\tBubbleText.setText(bubbleSteleInfoId, stateInfoId, steleIntervention)\r\n\t\r\n\tif (forceDisplayUI) then BubbleText.show(bubbleSteleInfoId) end\r\nend\r\n\r\n-- Fonction affichage du niveau d'Ecailles à chaque tour\r\nfunction updateFightInfo(steleIntervention, scaleLevel, forceDisplayUI)\r\n\tlocal steleIntervention = toLong(steleIntervention)\r\n\tlocal scaleLevel = toLong(scaleLevel)\r\n\r\n\tif (bubbleFightInfoId == 0) then\r\n\t\tbubbleFightInfoId = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_WEST\", 0, -110, false, 2147483647, true, \"interactiveBubbleDialog5\", 30000, 25000, \"onFightInfoClosed\")\r\n\tend\r\n\r\n\tBubbleText.setText(bubbleFightInfoId, \"aguabrial.fight.player.infos\", steleIntervention, scaleLevel)\r\n\t\r\n\tif (forceDisplayUI) then BubbleText.show(bubbleFightInfoId) end\r\nend\n\n-- [INIT] Variables\n-- \nfunction event_2293_18888()\n    \nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_2293_18889(room)\n    displayPath(room)\nend\n\n-- [EVENT][1] Victoire - Déverouille le passage vers S2\n-- \nfunction event_2293_18890()\n    \nend\n\n-- [EVENT][1] Victoire - Déverouille le passage vers S3\n-- \nfunction event_2293_18891()\n    \nend\n\n-- [EVENT][3] Victoire - Déverouille le passage vers S4\n-- \nfunction event_2293_18892()\n    \nend\n\n-- [EVENT] Salle 4 - Activation du TP de sortie\n-- \nfunction event_2293_18893()\n    \nend\n\n-- [OLD][EVENT] Activation Stèle 1\n-- \nfunction event_2293_18894(steleCount)\n    local steleCount = toLong(steleCount)\r\n    if (steleCount == 1) then rewardId = 27122\r\n    elseif (steleCount == 2) then rewardId = 27131\r\n    elseif (steleCount == 3) then rewardId = 27143\r\n    else rewardId = 0\r\n    end\r\n    \r\n    UI.openRewardsDialog(\"stele.activation\")\r\n    UI.addReward(rewardId)\nend\n\n-- [OLD][EVENT] Activation Stèle 2\n-- \nfunction event_2293_18895(steleCount)\n    local steleCount = toLong(steleCount)\r\n    if (steleCount == 1) then rewardId = 27122\r\n    elseif (steleCount == 2) then rewardId = 27131\r\n    elseif (steleCount == 3) then rewardId = 27143\r\n    else rewardId = 0\r\n    end\r\n    \r\n    UI.openRewardsDialog(\"stele.activation\")\r\n    UI.addReward(rewardId)\nend\n\n-- [OLD][EVENT] Activation Stèle 3\n-- \nfunction event_2293_18896(steleCount)\n    local steleCount = toLong(steleCount)\r\n    if (steleCount == 1) then rewardId = 27122\r\n    elseif (steleCount == 2) then rewardId = 27131\r\n    elseif (steleCount == 3) then rewardId = 27143\r\n    else rewardId = 0\r\n    end\r\n    \r\n    UI.openRewardsDialog(\"stele.activation\")\r\n    UI.addReward(rewardId)\nend\n\n-- [EVENT] Activation Stèle d'intervention\n-- \nfunction event_2293_20841(steleIntervention)\n    local steleIntervention = toLong(steleIntervention)\r\n    \r\n    if (steleIntervention == 1) then\r\n    rewardId = 27126\r\n    rewardTwoId = 27927\r\n    elseif (steleIntervention == 2) then\r\n    rewardId = 27959\r\n    elseif (steleIntervention == 3) then\r\n    rewardId = 27925\r\n    else\r\n    rewardId = 0\r\n    end\r\n    \r\n    UI.openRewardsDialog(\"stele.intervention.description\")\r\n    \r\n    if (steleIntervention == 1) then\r\n    UI.addReward(rewardId)\r\n    UI.addReward(rewardTwoId)\r\n    elseif (steleIntervention == 3) then\r\n    UI.addReward(rewardId, \"stele.intervention.stasis.reward\")\r\n    else\r\n    UI.addReward(rewardId)\r\n    end\r\n    \r\n    local stateInfoId = \"stele.intervention.aguabrial.description\"\r\n    \r\n    updateInterventionInfo(stateInfoId, steleIntervention, true)\nend\n\n-- [OLD][EVENT] Le joueur examine la Stèle 1\n-- \nfunction event_2293_20592(steleCount)\n    local steleCount = toLong(steleCount)\r\n    if (steleCount == 1) then rewardId = 27131\r\n    elseif (steleCount == 2) then rewardId = 27143\r\n    else rewardId = 27122\r\n    end\r\n    \r\n    UI.openRewardsDialog(\"stele.description\")\r\n    UI.addReward(rewardId)\r\n    \r\n    local stateInfoId = \"stele.state.description.4620\"\r\n    \r\n    updateSteleInfo(stateInfoId, true)\nend\n\n-- [OLD][EVENT] Le joueur examine la Stèle 2\n-- \nfunction event_2293_20593(steleCount)\n    local steleCount = toLong(steleCount)\r\n    if (steleCount == 1) then rewardId = 27131\r\n    elseif (steleCount == 2) then rewardId = 27143\r\n    else rewardId = 27122\r\n    end\r\n    \r\n    UI.openRewardsDialog(\"stele.description\")\r\n    UI.addReward(rewardId)\r\n    \r\n    local stateInfoId = \"stele.state.description.4619\"\r\n    \r\n    updateSteleInfo(stateInfoId, true)\nend\n\n-- [OLD][EVENT] Le joueur examine la Stèle 3\n-- \nfunction event_2293_20594(steleCount)\n    local steleCount = toLong(steleCount)\r\n    if (steleCount == 1) then rewardId = 27131\r\n    elseif (steleCount == 2) then rewardId = 27143\r\n    else rewardId = 27122\r\n    end\r\n    \r\n    UI.openRewardsDialog(\"stele.description\")\r\n    UI.addReward(rewardId)\r\n    \r\n    local stateInfoId = \"stele.state.description.4618\"\r\n    \r\n    updateSteleInfo(stateInfoId, true)\nend\n\n-- [EVENT] Le joueur examine la Stèle d'intervention\n-- \nfunction event_2293_20842(steleIntervention)\n    local steleIntervention = toLong(steleIntervention)\r\n    \r\n    if (steleIntervention == 0) then\r\n    rewardId = 27126\r\n    rewardTwoId = 27927\r\n    elseif (steleIntervention == 1) then\r\n    rewardId = 27959\r\n    elseif (steleIntervention == 2) then\r\n    rewardId = 27925\r\n    else\r\n    rewardId = 0\r\n    end\r\n    \r\n    UI.openRewardsDialog(\"stele.intervention.description\")\r\n    \r\n    if (steleIntervention == 0) then\r\n    UI.addReward(rewardId)\r\n    UI.addReward(rewardTwoId)\r\n    elseif (steleIntervention == 2) then\r\n    UI.addReward(rewardId, \"stele.intervention.stasis.reward\")\r\n    else\r\n    UI.addReward(rewardId)\r\n    end\r\n    \r\n    local stateInfoId = \"stele.intervention.aguabrial.description\"\r\n    \r\n    updateInterventionInfo(stateInfoId, steleIntervention, true)\nend\n\n-- [OLD][EVENT] Salle 4 - Refresh des APS pour le porteur des états Stèles\n-- \nfunction event_2293_18897()\n    \nend\n\n-- [EVENT] Salle 4 - Récupère l'ID du combat\n-- \nfunction event_2293_18900()\n    \nend\n\n-- [EVENT] Salle 4 - Reset l'ID du combat\n-- \nfunction event_2293_18901()\n    \nend\n\n-- [EVENT] Démarrage du combat (intervention) - Initialisation des variables\n-- \nfunction event_2293_20843()\n    \nend\n\n-- [EVENT] Démarrage du combat (intervention) - application état Aguabrial\n-- \nfunction event_2293_20844()\n    \nend\n\n-- [EVENT] Fin du combat avec victoire des Joueurs (1 stèle) - Validation Quête\n-- \nfunction event_2293_18902()\n    \nend\n\n-- [EVENT] Fin du combat avec victoire des Joueurs (2 stèles) - Validation Quête\n-- \nfunction event_2293_18903()\n    \nend\n\n-- [EVENT] Fin du combat avec victoire des Joueurs (3 stèles) - Validation Quête\n-- \nfunction event_2293_18904()\n    \nend\n\n-- Déplace le joueur vers la salle suivante\n-- \nfunction event_2293_18908()\n    \nend\n\n-- [EVENT] On rend les monstres de la salle du boss inattaquable\n-- Cela nous permet d'éviter d'avoir la mauvaise bulle de combat sur le combat du boss\nfunction event_2293_18993()\n    \nend\n\n-- [OLD][EVENT] DUNGEON_DIFFICULTY_CHANGED - On désactive les états stèles\n-- \nfunction event_2293_20618()\n    \nend\n\n-- [EVENT] Notification Etat Ecailles (intervention) - Mise à jour UI infos de combat\n-- \nfunction event_2293_20845(steleIntervention, scaleLevel)\n    updateFightInfo(steleIntervention, scaleLevel, true)\nend\n\n-- [STELE] FIGHT_STARTED - On applique les difficultés sur le boss\n-- \nfunction event_2293_22807()\n    \nend\n\n-- [STELE] FIGHT_ENTER_ACTION_PHASE - On applique les bonus sur les joueurs\n-- \nfunction event_2293_22808()\n    \nend\n\n-- [STELE] FIGHT_ENDED - On rend la stèle utilisable en cas de défaite\n-- \nfunction event_2293_22889()\n    \nend\n\n-- [ARCHI] Apparition de l'Archimonstre\n-- \nfunction event_2293_24005()\n    \nend\n\n","functions":["displayPath","closeSteleInfo","onSteleInfoClosed","updateSteleInfo","updateInterventionInfo","updateFightInfo","event_2293_18888","event_2293_18889","event_2293_18890","event_2293_18891","event_2293_18892","event_2293_18893","event_2293_18894","event_2293_18895","event_2293_18896","event_2293_20841","event_2293_20592","event_2293_20593","event_2293_20594","event_2293_20842","event_2293_18897","event_2293_18900","event_2293_18901","event_2293_20843","event_2293_20844","event_2293_18902","event_2293_18903","event_2293_18904","event_2293_18908","event_2293_18993","event_2293_20618","event_2293_20845","event_2293_22807","event_2293_22808","event_2293_22889","event_2293_24005"],"quest_calls":["UI.openRewardsDialog(\"stele.activation\")\r","UI.openRewardsDialog(\"stele.activation\")\r","UI.openRewardsDialog(\"stele.activation\")\r","UI.openRewardsDialog(\"stele.intervention.description\")\r","UI.openRewardsDialog(\"stele.description\")\r","UI.openRewardsDialog(\"stele.description\")\r","UI.openRewardsDialog(\"stele.description\")\r","UI.openRewardsDialog(\"stele.intervention.description\")\r"],"dialogue_calls":[]},"scenario/2294.lua":{"source":"\n\n-- [EVENT] Initialisation\n-- \nfunction event_2294_18923()\n    \nend\n\n-- [ACTION] Lancement du combat associé\n-- \nfunction event_2294_18924(GroupId, MobA, MobB, MobC, MobD, MobE, MobF, MobG, MobH, FightId, PlayerId)\n    PlayerId = toLong(PlayerId)\r\n    GroupId =toLong(GroupId)\r\n    FightId = toLong(FightId)\r\n    MobA = toLong(MobA)\r\n    MobB = toLong(MobB)\r\n    MobC = toLong(MobC)\r\n    MobD = toLong(MobD)\r\n    MobE = toLong(MobE)\r\n    MobF = toLong(MobF)\r\n    MobG = toLong(MobG)\r\n    MobH = toLong(MobH)\r\n    \r\n    trace(\"