)\n    \nend\n\n-- [ACTION] Fin de combat perdant\n-- \nfunction event_2296_18937()\n    \nend\n\n","functions":["event_2296_18933","event_2296_18934","event_2296_18935","event_2296_18936","event_2296_18937"],"quest_calls":[],"dialogue_calls":[]},"scenario/2297.lua":{"source":"\n\n-- [EVENT] Initialisation\n-- \nfunction event_2297_18938()\n    \nend\n\n-- [ACTION] Lancement du combat associé\n-- \nfunction event_2297_18939(GroupId, MobA, MobB, MobC, MobD, MobE, MobF, MobG, MobH, FightId, PlayerId)\n    PlayerId = toLong(PlayerId)\r\n    GroupId =toLong(GroupId)\r\n    FightId = toLong(FightId)\r\n    MobA = toLong(MobA)\r\n    MobB = toLong(MobB)\r\n    MobC = toLong(MobC)\r\n    MobD = toLong(MobD)\r\n    MobE = toLong(MobE)\r\n    MobF = toLong(MobF)\r\n    MobG = toLong(MobG)\r\n    MobH = toLong(MobH)\r\n    \r\n    trace(\"===Valeur de Player Id ======\", PlayerId)\r\n    trace(\"===Valeur de Group Id ======\", GroupId)\r\n    trace(\"===Valeur de Fight Id ======\", FightId)\r\n    trace(\"===Valeur de MobA Id ======\", MobA)\r\n    trace(\"===Valeur de MobB Id ======\", MobB)\r\n    trace(\"===Valeur de MobC Id ======\", MobC)\r\n    trace(\"===Valeur de MobD Id ======\", MobD)\r\n    trace(\"===Valeur de MobE Id ======\", MobE)\r\n    trace(\"===Valeur de MobF Id ======\", MobF)\r\n    trace(\"===Valeur de MobG Id ======\", MobG)\r\n    trace(\"===Valeur de MobH Id ======\", MobH)\nend\n\n-- [ACTION] Fin de combat gagnant\n-- \nfunction event_2297_18940(GroupId)\n    \nend\n\n-- [ACTION] Fin de combat gagnant - fin scenario\n-- \nfunction event_2297_18941(GroupId)\n    \nend\n\n-- [ACTION] Fin de combat perdant\n-- \nfunction event_2297_18942(GroupId, MobA, MobB, MobC)\n    \nend\n\n","functions":["event_2297_18938","event_2297_18939","event_2297_18940","event_2297_18941","event_2297_18942"],"quest_calls":[],"dialogue_calls":[]},"scenario/2298.lua":{"source":"\n\n-- [EVENT] Initialisation\n-- \nfunction event_2298_18943()\n    \nend\n\n-- [ACTION] Lancement du combat associé\n-- \nfunction event_2298_18944(GroupId, MobA, MobB, MobC, MobD, MobE, MobF, MobG, MobH, FightId, PlayerId)\n    PlayerId = toLong(PlayerId)\r\n    GroupId =toLong(GroupId)\r\n    FightId = toLong(FightId)\r\n    MobA = toLong(MobA)\r\n    MobB = toLong(MobB)\r\n    MobC = toLong(MobC)\r\n    MobD = toLong(MobD)\r\n    MobE = toLong(MobE)\r\n    MobF = toLong(MobF)\r\n    MobG = toLong(MobG)\r\n    MobH = toLong(MobH)\r\n    \r\n    trace(\"===Valeur de Player Id ======\", PlayerId)\r\n    trace(\"===Valeur de Group Id ======\", GroupId)\r\n    trace(\"===Valeur de Fight Id ======\", FightId)\r\n    trace(\"===Valeur de MobA Id ======\", MobA)\r\n    trace(\"===Valeur de MobB Id ======\", MobB)\r\n    trace(\"===Valeur de MobC Id ======\", MobC)\r\n    trace(\"===Valeur de MobD Id ======\", MobD)\r\n    trace(\"===Valeur de MobE Id ======\", MobE)\r\n    trace(\"===Valeur de MobF Id ======\", MobF)\r\n    trace(\"===Valeur de MobG Id ======\", MobG)\r\n    trace(\"===Valeur de MobH Id ======\", MobH)\nend\n\n-- [ACTION] Fin de combat gagnant\n-- \nfunction event_2298_18945(GroupId)\n    \nend\n\n-- [ACTION] Fin de combat gagnant - fin scenario\n-- \nfunction event_2298_18946(GroupId)\n    \nend\n\n-- [ACTION] Fin de combat perdant\n-- \nfunction event_2298_18947(GroupId, MobA, MobB, MobC)\n    \nend\n\n","functions":["event_2298_18943","event_2298_18944","event_2298_18945","event_2298_18946","event_2298_18947"],"quest_calls":[],"dialogue_calls":[]},"scenario/2299.lua":{"source":"--==** VARIABLES **==--\r\nbouftouIdOne = Mobile.generateClientMobileId()\r\nbouftouIdTwo = Mobile.generateClientMobileId()\r\nbouftouIdThree = Mobile.generateClientMobileId()\r\n\r\ngargalouMute = 1\r\ngargalouAnimRunning = false\r\n\r\nplayerId = Context.getLeaderId()\n\r\n--== BOUFTOUS VOLANTS ==--\r\nfunction actorBackground()\r\n\tActor.createActor(bouftouIdOne, 117100864, 0, -15, 4, 4)\n\tMobile.setMobileDirection(bouftouIdOne, 5)\n\tActor.createActor(bouftouIdTwo, 117100864, -7, -15, 1, 4)\n\tMobile.setMobileDirection(bouftouIdTwo, 5)\n\tActor.createActor(bouftouIdThree, 117100864, -6, -55, -1, 4)\n\tMobile.setMobileDirection(bouftouIdThree, 5)\nend\r\n\r\n--== ANIMS GARGALOU ==--\r\nfunction animGargalouPlay(mobileId)\r\n\tif (not gargalouAnimRunning) then\r\n\t\tgargalouMute = 0\r\n \t\tgargalouAnimRunning = true\r\n\t\tgargalouTired(mobileId)\r\n\tend\r\nend\r\n\r\nfunction animGargalouStop()\r\n\tgargalouMute = 1\r\n\tgargalouAnimRunning = false\r\nend\r\n\r\nfunction gargalouDream(mobileId)\r\n\tif (not gargalouAnimRunning) then return end\r\n\t\r\n\tMobile.setMobileAnimation(mobileId, \"AnimComp-Reve\", \"gargalouWakeUp\", mobileId)\r\n\t\r\n\tif (gargalouMute == 1) then return end\r\n\t\r\n\tlocal texts = {\"incarnam.ecosysteme.gargalou.reve01\", \"incarnam.ecosysteme.gargalou.reve02\", \"incarnam.ecosysteme.gargalou.reve03\"}\r\n\tlocal rdm = random(1, #texts)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\tBubbleText.showText(mobileId, texts[rdm], -20, 100, false)\r\nend\r\n\r\nfunction gargalouWakeUp(mobileId)\r\n\tif (not gargalouAnimRunning) then return end\r\n\t\r\n\tMobile.setMobileAnimation(mobileId, \"AnimComp-Reveil\", \"gargalouSpeak\", mobileId)\r\n\t\r\n\tif (gargalouMute == 1) then return end\r\n\t\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\tBubbleText.showText(mobileId, \"incarnam.ecosysteme.gargalou.reveil\", -20, 100, false)\r\nend\r\n\r\nfunction gargalouSpeak(mobileId)\r\n\tif (not gargalouAnimRunning) then return end\r\n\t\r\n\tMobile.setMobileAnimation(mobileId, \"AnimComp-ParleJoueur\", \"gargalouTired\", mobileId)\r\n\t\r\n\tif (gargalouMute == 1) then return end\r\n\t\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\tBubbleText.showText(mobileId, \"incarnam.ecosysteme.gargalou.dial01\", -20, 100, false)\r\nend\r\n\r\nfunction gargalouTired(mobileId)\r\n\tif (not gargalouAnimRunning) then return end\r\n\t\r\n\tMobile.setMobileAnimation(mobileId, \"AnimComp-Sommeil\", \"gargalouDream\",mobileId)\r\n\t\r\n\tif (gargalouMute == 1) then return end\r\n\t\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\tBubbleText.showText(mobileId, \"incarnam.ecosysteme.gargalou.endormissement\", -20, 100, false)\t\r\nend\n\n-- [INIT] Variables\n-- \nfunction event_2299_18948()\n    \nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_2299_18949(gargalouId, playerId, mimiOut, mimiId, gromuletOut, gromuletId)\n    actorBackground()\r\n    \r\n    Mobile.addMobileCreationCallback(gargalouId, \"animGargalouPlay\", gargalouId)\r\n    Mobile.addMobileDestructionCallback(gargalouId, \"animGargalouStop\")\nend\n\n-- [EVENT] Gestion du timer Mimi & Gromulet (UPDATE)\n-- \nfunction event_2299_18951()\n    \nend\n\n-- [Gromulet] Sortie\n-- \nfunction event_2299_18955()\n    \nend\n\n-- [Gromulet] Est au milieu et il sort\n-- \nfunction event_2299_18956()\n    \nend\n\n-- [Gromulet] Parle pendant sa sortie\n-- \nfunction event_2299_18957(gromuletId)\n    local texts = {\"incarnam.ecosysteme.gromulet.random01\", \"incarnam.ecosysteme.gromulet.random02\"}\r\n    local rdm = random(1, #texts)\r\n    \r\n    BubbleText.showText(gromuletId, texts[rdm], -20, 100, false)\r\n    invoke(5000, 1, \"BubbleText.closeBubbleAttachedTo\", gromuletId)\nend\n\n-- [Gromulet] Rentre\n-- \nfunction event_2299_18958()\n    \nend\n\n-- [Gromulet] Est rentré\n-- \nfunction event_2299_18959(gromuletId)\n    if (not Mobile.isMobileVisible(gromuletId)) then return end\r\n    \r\n    local texts = {\"incarnam.ecosysteme.gromulet.random03\", \"incarnam.ecosysteme.gromulet.random04\"}\r\n    local rdm = random(1, #texts)\r\n    \r\n    Mobile.setMobileDirection(gromuletId, 1)\r\n    BubbleText.showText(gromuletId, texts[rdm], -20, 100, false)\r\n    invoke(5000, 1, \"BubbleText.closeBubbleAttachedTo\", gromuletId)\nend\n\n-- [Mimi] Sortie\n-- \nfunction event_2299_18960()\n    \nend\n\n-- [Mimi] Est au milieu et il sort\n-- \nfunction event_2299_18961()\n    \nend\n\n-- [Mimi] Parle pendant sa sortie\n-- \nfunction event_2299_18962(mimiId)\n    local texts = {\"incarnam.ecosysteme.mimi.random01\", \"incarnam.ecosysteme.mimi.random02\"}\r\n    local rdm = random(1, #texts)\r\n    \r\n    BubbleText.showText(mimiId, texts[rdm], -20, 100, false)\r\n    invoke(5000, 1, \"BubbleText.closeBubbleAttachedTo\", mimiId)\nend\n\n-- [Mimi] Rentre\n-- \nfunction event_2299_18967()\n    \nend\n\n-- [Mimi] Est rentré\n-- \nfunction event_2299_18968(mimiId)\n    if (not Mobile.isMobileVisible(mimiId)) then return end\r\n    \r\n    local texts = {\"incarnam.ecosysteme.mimi.random03\", \"incarnam.ecosysteme.mimi.random04\"}\r\n    local rdm = random(1, #texts)\r\n    \r\n    Mobile.setMobileDirection(mimiId, 5)\r\n    BubbleText.showText(mimiId, texts[rdm], -20, 100, false)\r\n    invoke(5000, 1, \"BubbleText.closeBubbleAttachedTo\", mimiId)\nend\n\n-- [EVENT] Spawn du Bouftou Krosmique\n-- \nfunction event_2299_18969()\n    \nend\n\n","functions":["actorBackground","animGargalouPlay","animGargalouStop","gargalouDream","gargalouWakeUp","gargalouSpeak","gargalouTired","event_2299_18948","event_2299_18949","event_2299_18951","event_2299_18955","event_2299_18956","event_2299_18957","event_2299_18958","event_2299_18959","event_2299_18960","event_2299_18961","event_2299_18962","event_2299_18967","event_2299_18968","event_2299_18969"],"quest_calls":[],"dialogue_calls":[]},"scenario/2300.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2300_18970()\n    InteractiveElement.setAnimation(28509, \"AnimStatique\")\nend\n\n-- [EVENT] Le joueur a endormi le Dragoeuf - Désactive le Trigger\n-- \nfunction event_2300_18976()\n    InteractiveElement.setAnimation(28509, \"AnimComp-Endormir\")\nend\n\n-- [EVENT] POS_TRIG - Le joueur passe devant le dragon Eveillé - Retour au début du passage\n-- \nfunction event_2300_18975()\n    local playerId = Context.getLeaderId()\r\n    local fakeMobileId = createActor(10, 2, -13, 0, 4, 1, 6)\r\n    \r\n    startCinematicContext(1, fakeMobileId, 210082)\r\n    \r\n    invoke_custom(0000, 1, \"Sound.playLocalSound\", 5, 502008662002, 60, 2, -13, 1)\r\n    invoke_custom(0200, 1, \"bubble\", fakeMobileId, \"quest.zinit.ch3.dragoeuf.roupillon.roar\", 0, 60, false)\r\n    invoke_custom(0200, 1, \"Particle.addParticleSystemToTarget\", 800017, fakeMobileId)\r\n    invoke_custom(0500, 1, \"Effect.createCameraShakeEffect\", 0, 1500, 0, 3, 100, \"BOTH\")\r\n    \r\n    invoke_custom(0700, 1, \"Mobile.setMobileDirection\", playerId, 1)\r\n    invoke_custom(0700, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Effrayee\")\r\n    invoke_custom(1700, 1, \"bubble\", playerId, \"quest.zinit.ch3.dragoeuf.roupillon.awake\", 0, 60, false)\r\n    \r\n    invoke_custom(3700, 1, \"Mobile.moveMobile\", playerId, 0, -7, 0)\r\n    \r\n    invoke_custom(6700, 1, \"skipCinematic\")\nend\n\n-- [EVENT] Fin Cinématique Retour au début du passage - TP le joueur\n-- \nfunction event_2300_18977()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_2300_18970","event_2300_18976","event_2300_18975","event_2300_18977"],"quest_calls":[],"dialogue_calls":[]},"scenario/2301.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\n\n-- [VARIABLES]\n-- \nfunction event_2301_18978()\n    \nend\n\n-- [INIT] Le joueur entre dans l'instance\n-- \nfunction event_2301_18979()\n    \nend\n\n-- [EVENT] Start Cinématique\n-- \nfunction event_2301_18980(ogrestId)\n    local playerId = Context.getLeaderId()\r\n    local fakeMobileId = createActor(10, 2, -13, 0, 4, 1, 6)\r\n    \r\n    startCinematicContext(1, playerId, 210082)\r\n    \r\n    invoke_custom(0, 1, \"bubble\", playerId, \"test\")\r\n    invoke_custom(0, 1, \"bubble\", ogrestId, \"test\")\r\n    invoke_custom(0, 1, \"bubble\", fakeMobileId, \"test\")\nend\n\n-- [TEST] Restore mount\n-- \nfunction event_2301_23594(mobileId)\n    local mobile = toLong(mobileId)\r\n    \r\n    Actor.restoreMountStatus(mobile)\nend\n\n-- [TEST] Dix mount\n-- \nfunction event_2301_23595(mobileId)\n    local mobile = toLong(mobileId)\r\n    \r\n    Actor.forceDismount(mobile)\nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_2301_18978","event_2301_18979","event_2301_18980","event_2301_23594","event_2301_23595"],"quest_calls":[],"dialogue_calls":[]},"scenario/2302.lua":{"source":"\n\n-- [INIT]\n-- \nfunction event_2302_18987()\n    \nend\n\n","functions":["event_2302_18987"],"quest_calls":[],"dialogue_calls":[]},"scenario/2303.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n  \r\n-- Fonctions cache / montre CM\r\nfunction hideMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, false)\r\nend\r\n\r\nfunction showMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, true)\r\nend\r\n\r\nbubbleFightInfoId = 0\r\n\r\nfunction closeFightInfo()\r\n\tif (bubbleFightInfoId ~= nil  and bubbleFightInfoId ~= 0) then BubbleText.close(bubbleFightInfoId) end\r\nend\r\n\r\nfunction onFightInfoClosed()\r\n\tif (bubbleFightInfoId ~= nil  and bubbleFightInfoId ~= 0) then bubbleFightInfoId = 0 end\r\nend\r\n\r\nfunction updateFightInfo(wave, difficulty, teamDamage, forceDisplayUI)\r\n\tlocal wave = toLong(wave)\r\n\tlocal difficulty = toLong(difficulty)\r\n\tlocal teamDamage = toLong(teamDamage)\r\n\r\n\tif (bubbleFightInfoId == 0) then\r\n\t\tbubbleFightInfoId = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_WEST\", 0, -60, false, 2147483647, true, \"interactiveBubbleDialog5\", 30000, 25000, \"onFightInfoClosed\")\r\n\tend\r\n\r\n\tBubbleText.setText(bubbleFightInfoId, \"shoot.aime.hall.wave.info\", wave, difficulty, teamDamage)\r\n\r\n\tif (forceDisplayUI) then BubbleText.show(bubbleFightInfoId) end\r\nend\n\n-- [INIT] Variables globales\n-- \nfunction event_2303_22930()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2303_22931()\n    Server.triggerEvent(22931)\nend\n\n-- [EVENT] CLIENT_TRIGGERED_EVENT - Lancement du combat\n-- \nfunction event_2303_22932()\n    trace(\"LANCEMENT DU COMBAT\")\nend\n\n-- [EVENT] FIGHT_ENTER_ACTION_PHASE - Application états\n-- \nfunction event_2303_22933(wave, difficulty, teamDamage)\n    updateFightInfo(wave, difficulty, teamDamage, true)\nend\n\n-- [EVENT] NEW_MONSTER_WAVE - Difficulté\n-- \nfunction event_2303_22934(wave, difficulty, teamDamage)\n    updateFightInfo(wave, difficulty, teamDamage, true)\nend\n\n-- FIGHT_PLACEMENT_END - Le joueur est exclu et contrôle Cucupidon\n-- \nfunction event_2303_22946()\n    \nend\n\n-- [EVENT] FIGHT_ENDED_IN_CLIENT - Victoire - On donne les récompenses\n-- \nfunction event_2303_22948()\n    \nend\n\n-- [EVENT] FIGHT_ENDED_IN_CLIENT - On ferme l'affichage\n-- \nfunction event_2303_22935(wave, difficulty, teamDamage)\n    local wave = toLong(wave)\r\n    local teamDamage = toLong(teamDamage)\r\n    UI.writeLocalisedInChat(\"shoot.aime.hall.fight.final.score.wave\", wave)\r\n    UI.writeLocalisedInChat(\"shoot.aime.hall.fight.final.score.damage\", teamDamage)\r\n    \r\n    closeFightInfo()\nend\n\n-- EFFECT_EXECUTION - Mise à jour UI infos de combat (score)\n-- \nfunction event_2303_22947(wave, difficulty, teamDamage)\n    updateFightInfo(wave, difficulty, teamDamage, true)\nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","hideMonster","showMonster","closeFightInfo","onFightInfoClosed","updateFightInfo","event_2303_22930","event_2303_22931","event_2303_22932","event_2303_22933","event_2303_22934","event_2303_22946","event_2303_22948","event_2303_22935","event_2303_22947"],"quest_calls":[],"dialogue_calls":[]},"scenario/2304.lua":{"source":"\n\n-- [INIT]\n-- \nfunction event_2304_19019()\n    \nend\n\n","functions":["event_2304_19019"],"quest_calls":[],"dialogue_calls":[]},"scenario/2305.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\n-- bla\r\n\r\nbubbleFightInfoId = 0\r\n\r\n-- Fonction porte\r\nfunction displayDoor(doorOpened, ogrestFightWon)\r\n\tlocal door = toLong(doorOpened)\r\n\tlocal fight = toLong(ogrestFightWon)\r\n\r\n\tif (door == 1) then\r\n\t\tWorld.setPictoAlpha(1, -4, 10, 0, 1000)\r\n\telse\r\n\t\tWorld.setPictoAlpha(1, -4, 10, 1, 1000)\r\n\tend\r\n\r\n\tif (fight == 1) then\r\n\t\tWorld.setPictoAlpha(1, -4, 10, 1, 1000)\r\n\tend\r\nend\r\n\r\nphases = {\t{5003, 4980, Event.getContentTranslation(8, 4980), \"emeraude\"},\r\n\t\t\t\t\t{5004, 4981, Event.getContentTranslation(8, 4981), \"ocre\"},\r\n\t\t\t\t\t{5005, 4982, Event.getContentTranslation(8, 4982), \"pourpre\"},\r\n\t\t\t\t\t{5006, 4983, Event.getContentTranslation(8, 4983), \"turquoise\"},\r\n\t\t\t\t\t{5007, 4984, Event.getContentTranslation(8, 4984), \"ivoire\"},\r\n\t\t\t\t\t{5008, 4985, Event.getContentTranslation(8, 4985), \"ebene\"}\t}\r\n\t\t\t\t\t\r\nfunction closeFightInfo()\r\n\tif (bubbleFightInfoId ~= nil  and bubbleFightInfoId ~= 0) then BubbleText.close(bubbleFightInfoId) end\r\nend\r\n\r\nfunction onFightInfoClosed()\r\n\tif (bubbleFightInfoId ~= nil  and bubbleFightInfoId ~= 0) then bubbleFightInfoId = 0 end\r\nend\r\n\r\nfunction updateFightInfo(ogrestId, teamDamage, currentPhaseTurnLeft, phaseEmeraude, phaseOcre, phasePourpre, phaseTurquoise, phaseIvoire, phaseEbene, forceDisplayUI)\r\n\tlocal ogrestId = toLong(ogrestId)\r\n\tlocal teamDamage = toLong(teamDamage)\r\n\tlocal phaseEmeraude = toLong(phaseEmeraude)\r\n\tlocal phaseOcre = toLong(phaseOcre)\r\n\tlocal phasePourpre = toLong(phasePourpre)\r\n\tlocal phaseTurquoise = toLong(phaseTurquoise)\r\n\tlocal phaseIvoire = toLong(phaseIvoire)\r\n\tlocal phaseEbene = toLong(phaseEbene)\r\n\tlocal currentPhaseTurnLeft = toLong(currentPhaseTurnLeft)\r\n\tlocal currentPhaseName = \"?\"\r\n\tlocal nextPhaseName = \"?\"\r\n\t\r\n\tif (phaseEmeraude == 1) then\r\n\t  \tnextPhaseName =  phases[1][3]\r\n\telseif (phaseOcre == 1) then\r\n\t\tnextPhaseName = phases[2][3]\r\n\telseif (phasePourpre == 1) then\r\n\t   \tnextPhaseName = phases[3][3]\r\n\telseif (phaseTurquoise == 1) then\r\n\t   \tnextPhaseName = phases[4][3]\r\n\telseif (phaseIvoire == 1) then\r\n\t   \tnextPhaseName = phases[5][3]\r\n\telseif (phaseEbene == 1) then\r\n\t   \tnextPhaseName = phases[6][3]\r\n\tend\r\n\r\n\tif (phaseEmeraude == 2) then\r\n\t   \tcurrentPhaseName = phases[1][3]\r\n\telseif (phaseOcre == 2) then\r\n\t   \tcurrentPhaseName = phases[2][3]\r\n\telseif (phasePourpre == 2) then\r\n\t   \tcurrentPhaseName = phases[3][3]\r\n\telseif (phaseTurquoise == 2) then\r\n\t   \tcurrentPhaseName = phases[4][3]\r\n\telseif (phaseIvoire == 2) then\r\n\t  \tcurrentPhaseName = phases[5][3]\r\n\telseif (phaseEbene == 2) then\r\n\t   \tcurrentPhaseName = phases[6][3]\r\n\tend\r\n\t   \r\n\tif (currentPhaseTurnLeft == nil or currentPhaseTurnLeft <= 0) then currentPhaseTurnLeft = \"?\" end\r\n\r\n\tif (bubbleFightInfoId == 0) then\r\n\t\tbubbleFightInfoId = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_WEST\", 0, -60, false, 2147483647, true, \"interactiveBubbleOgrestDialog\", 30000, 25000, \"onFightInfoClosed\")\r\n\tend\r\n\r\n\tBubbleText.setText(bubbleFightInfoId, \"ogrest.fight.player.infos\", teamDamage, currentPhaseName, currentPhaseTurnLeft, nextPhaseName)\r\n\t\r\n\tif (forceDisplayUI) then BubbleText.show(bubbleFightInfoId) end\r\nend\n\n-- [INIT] Variables\n-- \nfunction event_2305_19037()\n    \nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_2305_19038(doorOpened, ogrestFightWon)\n    FightEvent.addPlacementStartCallback(\"Sound.playFightMusic\", 290103)\r\n    \r\n    displayDoor(doorOpened, ogrestFightWon)\nend\n\n-- INTERACTIVE_ELEMENT_ACTIVATION - Ouverture de la porte\n-- \nfunction event_2305_21745(doorOpened, ogrestFightWon)\n    trace(\"OUVERTURE DE LA PORTE\")\r\n    \r\n    displayDoor(doorOpened, ogrestFightWon)\nend\n\n-- [EVENT] Le joueur marche sur le Trigger - Lancement Vidéo Intro\n-- \nfunction event_2305_19091()\n    startVideoContext()\r\n    Video.playCinematicVideo(\"WAKFU_OGREST_ZINIT_INTRO.mkv\", 0.6)\r\n    Video.addVideoStopOrEndCallback(\"skipVideo\", 19091)\nend\n\n-- [EVENT] Le joueur attaque Ogrest - Initialisation du combat (Final)\n-- \nfunction event_2305_19129()\n    \nend\n\n-- [EVENT] Le joueur attaque Ogrest - Initialisation du combat (Emeraude)\n-- \nfunction event_2305_19084()\n    \nend\n\n-- [EVENT] Le joueur attaque Ogrest - Initialisation du combat (Ocre)\n-- \nfunction event_2305_19085()\n    \nend\n\n-- [EVENT] Le joueur attaque Ogrest - Initialisation du combat (Pourpre)\n-- \nfunction event_2305_19086()\n    \nend\n\n-- [EVENT] Le joueur attaque Ogrest - Initialisation du combat (Turquoise)\n-- \nfunction event_2305_19087()\n    \nend\n\n-- [EVENT] Le joueur attaque Ogrest - Initialisation du combat (Ivoire)\n-- \nfunction event_2305_19088()\n    \nend\n\n-- [EVENT] Le joueur attaque Ogrest - Initialisation du combat (Ebene)\n-- \nfunction event_2305_19089()\n    \nend\n\n-- [EVENT] Démarrage du combat - Initialisation des variables\n-- \nfunction event_2305_19105()\n    \nend\n\n-- [EVENT] Démarrage du combat - Pose des Artefacts\n-- \nfunction event_2305_19040()\n    \nend\n\n-- [EVENT] FIGHT_ENTER_ACTION_PHASE - Application états\n-- \nfunction event_2305_21746()\n    \nend\n\n-- [EVENT] Fin du combat -  Masque UI infos de combat\n-- \nfunction event_2305_19047()\n    closeFightInfo()\nend\n\n-- [EVENT] Victoire du combat - Enregistrement au classement\n-- \nfunction event_2305_19069()\n    \nend\n\n-- [EVENT] Notification Etat Gestion Phases - Mise à jour UI infos de combats (phases)\n-- \nfunction event_2305_19045(ogrestId, teamDamage, currentPhaseTurnLeft, phaseEmeraude, phaseOcre, phasePourpre, phaseTurquoise, phaseIvoire, phaseEbene)\n    updateFightInfo(ogrestId, teamDamage, currentPhaseTurnLeft, phaseEmeraude, phaseOcre, phasePourpre, phaseTurquoise, phaseIvoire, phaseEbene, true)\nend\n\n-- [EVENT] Notification Etat Compteur de dommages - Mise à jour UI infos de combat (score)\n-- \nfunction event_2305_19041(ogrestId, teamDamage, currentPhaseTurnLeft, phaseEmeraude, phaseOcre, phasePourpre, phaseTurquoise, phaseIvoire, phaseEbene)\n    updateFightInfo(ogrestId, teamDamage, currentPhaseTurnLeft, phaseEmeraude, phaseOcre, phasePourpre, phaseTurquoise, phaseIvoire, phaseEbene, false)\nend\n\n-- [EVENT] Notification Etat Gestion Phases -  Changement de Musique à chaque Phase\n-- \nfunction event_2305_19103(musicPhaseCount)\n    local musicPhaseCount = toLong(musicPhaseCount)\r\n    local musics = {290103,290104,290105,290106,290107,290108}\r\n    \r\n    --On commence à 2 car la première musique est déjà lancée via la musique de combat sur la zone d'ambiance\r\n    if (musicPhaseCount >= 2 and musicPhaseCount <= 6) then\r\n    \tSound.playFightMusic(musics[musicPhaseCount])\r\n    end\nend\n\n-- [EVENT] Le joueur perd le combat - TP en dehors de l'instance\n-- \nfunction event_2305_19130(ogrestIsDown)\n    \nend\n\n-- [EVENT] Le joueur gagne le combat - Lancement Vidéo Victoire\n-- \nfunction event_2305_19092(ogrestIsDown)\n    trace(\"STARTING VIDEO OGREST\")\r\n    local ogrestIsDown = toLong(ogrestIsDown)\r\n    local videoName = \"WAKFU_OGREST_ZINIT_FIGHT_SHORT.mkv\"\r\n    \r\n    if (ogrestIsDown == 1) then videoName = \"WAKFU_OGREST_ZINIT_FIGHT_LONG.mkv\" end\r\n    trace(ogrestIsDown, videoName)\r\n    \r\n    Sound.stopForcedMusic()\r\n    \r\n    Mobile.hideOtherPlayerMobile(true)\r\n    \r\n    UI.addUnremovableDialog(\"fightResultDialog\")\r\n    \r\n    UI.setWidgetEnabled(\"fightResultDialog\", \"rootContainer\", false)\r\n    UI.setWidgetVisibility(\"fightResultDialog\", \"rootContainer\", false)\r\n    \r\n    startVideoContext()\r\n    Video.playCinematicVideo(videoName, 0.6)\r\n    Video.addVideoStopOrEndCallback(\"skipVideo\", 19092)\nend\n\n-- [EVENT] Fin Vidéo Victoire - Lancement Cinématique Ogrest\n-- \nfunction event_2305_19106()\n    trace(\"STARTING OGREST CINE\")\r\n    \r\n    function cineOgrest()\r\n    \tlocal playerId = Context.getLeaderId()\r\n    \tMobile.setMobileDirection(playerId, 7)\r\n    \tMobile.setMobileAnimation(playerId, \"AnimCine-Ogrest-ArtefactTP\")\r\n    \t\r\n    \tlocal ogrestId = createActor(\"1300060\", 153, -33, 54, 4, 3, 14)\r\n    \tMobile.setMobileAnimation(ogrestId, \"AnimComp-Epuisement\")\r\n    \t\r\n    \tlocal apsTeleport = -1454061590\r\n    \r\n    \t---------------------------------\r\n    \t\r\n    \tstartCinematicContext(1.7, playerId)\r\n    \tUI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 19106)\r\n    \t\r\n    \tinvoke_custom(0400, 1, \"setWorldParticleTarget\", apsTeleport, playerId, 1)\r\n    \tinvoke_custom(4000, 1, \"Mobile.setMobileVisible\", playerId, false)\r\n    \tinvoke_custom(6500, 1, \"Camera.attachCameraToMobile\", ogrestId)\r\n    \tinvoke_custom(6500, 1, \"Camera.setZoomFactor\", 1.5)\r\n    \r\n    \t---------------------------------\r\n    \t\r\n    \tinvoke_custom(12000, 1, \"skipCinematic\", 19106)\r\n    end\r\n    \r\n    Event.runOnInstanceLoaded(\"cineOgrest\")\nend\n\n-- [EVENT] Fin Cinématique Ogrest - Lancement Cinématique Otomaï\n-- \nfunction event_2305_19109(ogrestIsDown)\n    trace(\"STARTING OTOMAI CINE\")\r\n    local ogrestIsDown = toLong(ogrestIsDown)\r\n    \r\n    function cineOtomai(ogrestIsDown)\r\n    \tlocal playerId = Context.getLeaderId()\r\n    \tMobile.setMobileDirection(playerId, 1)\r\n    \tMobile.setMobileVisible(playerId, false)\r\n    \r\n    \tlocal otomaiId = createActor(\"181404009\", 375, 200, 20, 4, 1, 8)\r\n    \tMobile.setMobileDirection(otomaiId, 3)\r\n    \t\r\n    \tlocal suffix = \"victory\"\r\n    \tif (ogrestIsDown == 1) then suffix = \"end\" end\r\n    \t\r\n    \t---------------------------------\r\n    \t\r\n    \tstartCinematicContext(1.2, otomaiId)\r\n    \tUI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 19109)\r\n    \t\r\n    \t--Otomai se déplace vers le joueur\r\n    \tinvoke_custom(00100, 1, \"Mobile.moveMobile\", otomaiId, 375, 211, 20)\r\n    \t--La caméra se met sur l'emplacement du joueur puis il tombe du ciel\r\n    \tinvoke_custom(03000, 1, \"Camera.attachCameraToMobile\", playerId)\r\n    \tinvoke_custom(03500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimIncarnam-Chute-Fin\")\r\n    \tinvoke_custom(03500, 1, \"Mobile.setMobileVisible\", playerId, true)\r\n    \t\r\n    \t--Ah, te voilà !\r\n    \t--Ah, te voilà !\r\n    \tinvoke_custom(06000, 1, \"bubble\", otomaiId, \"quest.zinit.ch4.cine.otomai.ogrest.\" .. suffix .. \".01\")\r\n    \tinvoke_custom(06000, 1, \"Mobile.setMobileAnimation\", otomaiId, \"AnimComp-Special03\")\r\n    \t--A mieux te regarder, on dirait que tu es encore sous le choc de ton combat.\r\n    \t--Je ne pensais pas cela possible, mais encore une fois, tu m’a démontré le contraire.\r\n    \tinvoke_custom(08000, 1, \"bubble\", otomaiId, \"quest.zinit.ch4.cine.otomai.ogrest.\" .. suffix .. \".02\")\r\n    \t--Et tu n’es pas le seul… Le monde entier a subi les conséquences de ton affrontement contre Ogrest.\r\n    \t--Après plusieurs millénaires à étudier des phénomènes scientifiques… Je me croyais à l’abri des surprises.\r\n    \tinvoke_custom(14000, 1, \"bubble\", otomaiId, \"quest.zinit.ch4.cine.otomai.ogrest.\" .. suffix .. \".03\")\r\n    \t--Mais ce sont des conséquences nécessaires. Si on ne fait rien, la montée des eaux ne s’arrêtera jamais.\r\n    \t--Et puis, vous êtes arrivés.\r\n    \tinvoke_custom(20000, 1, \"bubble\", otomaiId, \"quest.zinit.ch4.cine.otomai.ogrest.\" .. suffix .. \".04\")\r\n    \t--Malheureusement, c’est une victoire mi-figue mi-raisin… Qui sait, peut-être qu’à la sueur des braves tels que toi, nous atteindrons un stade de victoire.\r\n    \t--Je dois avouer que c’est une sacrée génération d’aventuriers que nous avons là. Un miracle a été accompli, et Ogrest s’en est retourné chez lui, calmé. \r\n    \tinvoke_custom(26000, 1, \"bubble\", otomaiId, \"quest.zinit.ch4.cine.otomai.ogrest.\" .. suffix .. \".05\")\r\n    \t--En tout cas, je suis ravi de te revoir en un seul morceau ! Le générateur de barrière extra-krosmique a bien fait l’affaire, finalement.\r\n    \t--Fini, le chaos d’Ogrest ! Pour un temps, du moins. Mais tous ces efforts en valaient bien la peine !\r\n    \tinvoke_custom(34000, 1, \"bubble\", otomaiId, \"quest.zinit.ch4.cine.otomai.ogrest.\" .. suffix .. \".06\")\r\n    \t--Tu ne t’imaginais pas retourner à Incarnam pour tout recommencer nu comme un Slek, n’est-ce pas ?\r\n    \t--Maintenant que les orages incessants se sont calmés, tu pourras peut-être trouver quelques Larmes d’Ogrest éparpillées sur le monde.\r\n    \tinvoke_custom(42000, 1, \"bubble\", otomaiId, \"quest.zinit.ch4.cine.otomai.ogrest.\" .. suffix .. \".07\")\r\n    \tinvoke_custom(42000, 1, \"Mobile.setMobileAnimation\", otomaiId, \"AnimComp-Special03\")\r\n    \t--N’oublie pas : le générateur est limité à 3 utilisations par semaine. Il serait dommage d’aller tenter le diable une fois de trop !\r\n    \t--Elles possèdent de grands pouvoirs ! D’ailleurs, tu peux en demander davantage à Mod’Ule.\r\n    \tinvoke_custom(50000, 1, \"bubble\", otomaiId, \"quest.zinit.ch4.cine.otomai.ogrest.\" .. suffix .. \".08\")\r\n    \t\r\n    \tinvoke_custom(56000, 1, \"clearBubbles\", otomaiId)\r\n    \tinvoke_custom(56000, 1, \"Mobile.moveMobile\", otomaiId, 375, 200, 20)\r\n    \t\r\n    \t---------------------------------\r\n    \r\n    \tinvoke_custom(60000, 1, \"skipCinematic\", 19109)\r\n    end\r\n    \r\n    Event.runOnInstanceLoaded(\"cineOtomai\", ogrestIsDown)\nend\n\n-- [EVENT] Fin Cinématique Otomaï - Clean\n-- \nfunction event_2305_19127(teamDamage)\n    local teamDamage = toString(teamDamage)\r\n    \r\n    Mobile.hideOtherPlayerMobile(false)\r\n    \r\n    UI.setWidgetEnabled(\"fightResultDialog\", \"rootContainer\", true)\r\n    UI.setWidgetVisibility(\"fightResultDialog\", \"rootContainer\", true)\r\n    \r\n    local text = Event.getKeyTranslation(\"fight.score.ogrest\", teamDamage)\r\n    UI.setPropertyStringValue(\"fight.score.ogrest\", text)\r\n    UI.writeLocalisedInChat(\"ogrest.fight.team.score\", teamDamage)\r\n    \r\n    UI.removeUnremovableDialog(\"fightResultDialog\")\r\n    \r\n    UI.addDialogUnloadedListener(\"fightResultDialog\", \"UI.removeProperty\", \"fight.score.ogrest\")\nend\n\n-- [EVENT] Victoire du combat - 0M <= Metric < 0.5M\n-- \nfunction event_2305_19131()\n    \nend\n\n-- [EVENT] Victoire du combat - 0.5M <= Metric < 1M\n-- \nfunction event_2305_19132()\n    \nend\n\n-- [EVENT] Victoire du combat - 1M <= Metric < 1.5M\n-- \nfunction event_2305_19133()\n    \nend\n\n-- [EVENT] Victoire du combat - 1.5M <= Metric < 2M\n-- \nfunction event_2305_19134()\n    \nend\n\n-- [EVENT] Victoire du combat - 2M <= Metric < 2.5M\n-- \nfunction event_2305_19135()\n    \nend\n\n-- [EVENT] Victoire du combat - 2.5M <= Metric\n-- \nfunction event_2305_19136()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","displayDoor","closeFightInfo","onFightInfoClosed","updateFightInfo","event_2305_19037","event_2305_19038","event_2305_21745","event_2305_19091","event_2305_19129","event_2305_19084","event_2305_19085","event_2305_19086","event_2305_19087","event_2305_19088","event_2305_19089","event_2305_19105","event_2305_19040","event_2305_21746","event_2305_19047","event_2305_19069","event_2305_19045","event_2305_19041","event_2305_19103","event_2305_19130","event_2305_19092","event_2305_19106","cineOgrest","event_2305_19109","cineOtomai","event_2305_19127","event_2305_19131","event_2305_19132","event_2305_19133","event_2305_19134","event_2305_19135","event_2305_19136"],"quest_calls":[],"dialogue_calls":[]},"scenario/2307.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_2307_19111()\n    \nend\n\n-- [EVENT] Le joueur clique sur le puits - Cinématique + Transformation en Ogrest\n-- \nfunction event_2307_19115()\n    local playerId = Context.getLeaderId()\r\n    local ogrest = createActor(1300060, 0, -52, 0, 4, 3, 16)\r\n    local flagCamera = createActor(1300060, 0, -37, 0, 4, 3, 7)\r\n    local aps_apparition = -1454061830\r\n    \r\n    Mobile.setMobileVisible(ogrest, false)\r\n    Mobile.setMobileVisible(flagCamera, false)\r\n    \r\n    Camera.setWorldTarget(0, -52, 0)\r\n    startCinematicContext(1.2, playerId, 290103)\r\n    \r\n    invoke_custom(1000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Fievre\")\r\n    -- Je... Je ne me sens pas très... bien...\r\n    invoke_custom(2500, 1, \"bubble\", playerId, \"quest.zinit.ch4.cine.colere.ogrest.01\")\r\n    invoke_custom(4000, 1, \"clearBubbles\", playerId)\r\n    invoke_custom(4000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmotePLS-Target\")\r\n    \r\n    invoke_custom(7000, 1, \"Camera.attachCameraToMobile\", flagCamera)\r\n    invoke_custom(7000, 1, \"Particle.addParticleSystem\", aps_apparition, 0, -40, 0)\r\n    invoke_custom(7000, 1, \"Mobile.setMobileAnimation\", ogrest, \"AnimSort-Tapesol\")\r\n    invoke_custom(7000, 1, \"Effect.createCameraShakeEffect\", 1000, 2000, 1000, 1)\r\n    \r\n    invoke_custom(8000, 1, \"Mobile.setMobileVisible\", playerId, false)\r\n    invoke_custom(8000, 1, \"Mobile.setMobileVisible\", ogrest, true)\r\n    \r\n    invoke_custom(9000, 1, \"Mobile.setMobileAnimation\", ogrest, \"AnimSort-Hurle\")\r\n    invoke_custom(9000, 1, \"Effect.createCameraShakeEffect\", 1000, 4000, 1000, 1)\r\n    \r\n    invoke_custom(10000, 1, \"Camera.attachCameraToMobile\", ogrest)\r\n    \r\n    -- Mouhahahahaha ! Je suis DEVENU Ogrest !\r\n    invoke_custom(11000, 1, \"Mobile.setMobileAnimation\", ogrest, \"AnimSort-Hurle\")\r\n    invoke_custom(11000, 1, \"bubble\", ogrest, \"quest.zinit.ch4.cine.colere.ogrest.02\")\r\n    invoke_custom(13000, 1, \"clearBubbles\", ogrest)\r\n    \r\n    invoke_custom(13500, 1, \"Mobile.setMobileDirection\", playerId, 3)\r\n    invoke_custom(14500, 1, \"Mobile.setMobileVisible\", ogrest, false)\r\n    invoke_custom(14000, 1, \"skipCinematic\", 19115)\nend\n\n-- [EVENT] Fin de cinématique - Lancement du combat contre les bouftous\n-- \nfunction event_2307_19117()\n    \nend\n\n-- [EVENT] Démarrage du combat - Pose de la zone de fin de combat\n-- \nfunction event_2307_19120()\n    \nend\n\n-- [EVENT] Victoire du combat - Cinématique Aguabrial\n-- \nfunction event_2307_19112(aguabrialId)\n    local aguabrial = createActor(137201723, 0, -31, 0, 4, 7, 16)\r\n    local playerId = Context.getLeaderId()\r\n    \r\n    Mobile.setMobileVisible(playerId, false)\r\n    Mobile.setMobileVisible(aguabrial, false)\r\n    Mobile.setMobileVisible(aguabrialId, false)\r\n    \r\n    Camera.setWorldTarget(0, -31, 0)\r\n    \r\n    startCinematicContext(1, aguabrial, 290100)\r\n    \r\n    invoke_custom(1000, 1, \"Mobile.setMobileVisible\", playerId, true)\r\n    invoke_custom(1000, 1, \"Mobile.setMobileVisible\", aguabrial, true)\r\n    invoke_custom(1000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimSort-Jump-Fin01\")\r\n    invoke_custom(1000, 1, \"Mobile.setMobileAnimation\", aguabrial, \"AnimApparition\")\r\n    \r\n    invoke_custom(3000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimSort-Hurle\")\r\n    \r\n    -- \"Je suis Aguabrial, dragon primordial, gardien de l’élément Eau…\"\r\n    invoke_custom(4500, 1, \"bubble\", aguabrial, \"quest.zinit.ch4.cine.colere.ogrest.12\")\r\n    \r\n    -- \"Je ne veux faire aucune vague… \"\r\n    invoke_custom(8500, 1, \"bubble\", aguabrial, \"quest.zinit.ch4.cine.colere.ogrest.13\")\r\n    \r\n    -- \"Rebrousse chemin ou tu vas prendre une sacrée douche froide.\"\r\n    invoke_custom(12000, 1, \"bubble\", aguabrial, \"quest.zinit.ch4.cine.colere.ogrest.14\")\r\n    \r\n    invoke_custom(18000, 1, \"skipCinematic\", 19112)\nend\n\n-- [EVENT] Fin de la cinématique - Lancement combat Aguabrial vs Joueur\n-- \nfunction event_2307_19114()\n    \nend\n\n-- [EVENT] Le joueur se fait cogner par Aguabrial\n-- \nfunction event_2307_19116()\n    local playerId = Context.getLeaderId()\r\n    local aguabrial = createActor(137201723, 0, -31, 0, 4, 7, 10)\r\n    local otomai = createActor(181404009, -1, -22, 0, 0, 3, 7)\r\n    \r\n    Mobile.setMobileVisible(playerId, false)\r\n    Mobile.setMobileVisible(aguabrial, true)\r\n    Mobile.setMobileVisible(otomai, false)\r\n    \r\n    startCinematicContext(1.5, aguabrialId, 290105)\r\n    Camera.setWorldTarget(0, -34, 0)\r\n    \r\n    invoke_custom(2000, 1, \"Mobile.setMobileVisible\", playerId, true)\r\n    invoke_custom(2000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimIncarnam-Chute-Fin\")\r\n    \r\n    -- Je suis redevenu{[1*]?e:} moi-même...\r\n    invoke_custom(3900, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimStatique\")\r\n    invoke_custom(4000, 1, \"bubble\", playerId, \"quest.zinit.ch4.cine.colere.ogrest.03\")\r\n    invoke_custom(6000, 1, \"clearBubbles\", playerId)\r\n    invoke_custom(6000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Fievre\")\r\n    \r\n    invoke_custom(7000, 1, \"Camera.attachCameraToMobile\", aguabrial)\r\n    -- Malgré toute ta puissance, tu possèdes encore une marge de progression...\r\n    invoke_custom(8000, 1, \"bubble\", aguabrial, \"quest.zinit.ch4.cine.colere.ogrest.04\")\r\n    invoke_custom(7800, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimStatique\")\r\n    invoke_custom(11000, 1, \"clearBubbles\", aguabrial)\r\n    -- Nous nous reverrons, aventuri{[1*]?ère:er}.\r\n    invoke_custom(12000, 1, \"bubble\", aguabrial, \"quest.zinit.ch4.cine.colere.ogrest.05\")\r\n    invoke_custom(15000, 1, \"clearBubbles\", aguabrial)\r\n    -- D'ici là, j'espère que tu seras assez fort{[1*]?e:} pour résister à la colère par toi-même !\r\n    invoke_custom(15000, 1, \"bubble\", aguabrial, \"quest.zinit.ch4.cine.colere.ogrest.06\")\r\n    invoke_custom(18000, 1, \"clearBubbles\", aguabrial)\r\n    \r\n    invoke_custom(18000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Coucou\")\r\n    invoke_custom(18000, 1, \"Mobile.setMobileAnimation\", aguabrial, \"AnimMort\")\r\n    invoke_custom(19400, 1, \"Mobile.setMobileVisible\", aguabrial, false)\r\n    invoke_custom(19400, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimStatique\")\r\n    \r\n    \r\n    invoke_custom(22000, 1, \"Camera.attachCameraToMobile\", otomai)\r\n    invoke_custom(22000, 1, \"Mobile.setMobileVisible\", otomai, true)\r\n    invoke_custom(24000, 1, \"Mobile.moveMobile\", otomai, -1, -34, 0)\r\n    \r\n    -- Enfin, je te retrouve ! \r\n    invoke_custom(28500, 1, \"Mobile.setMobileDirection\", otomai, 1)\r\n    invoke_custom(28500, 1, \"Mobile.setMobileDirection\", playerId, 5)\r\n    invoke_custom(28500, 1, \"bubble\", otomai, \"quest.zinit.ch4.cine.colere.ogrest.07\")\r\n    invoke_custom(31000, 1, \"clearBubbles\", otomai)\r\n    \r\n    -- Quoi ? Tu t'es transformé en Ogrest ? Et Aguabrial t'a affronté ?\r\n    invoke_custom(31000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Presenter\")\r\n    \r\n    invoke_custom(33000, 1, \"Mobile.setMobileAnimation\", otomai, \"AnimComp-Special06\")\r\n    invoke_custom(33500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimStatique\")\r\n    invoke_custom(34000, 1, \"bubble\", otomai, \"quest.zinit.ch4.cine.colere.ogrest.08\")\r\n    invoke_custom(37000, 1, \"clearBubbles\", otomai)\r\n    invoke_custom(37200, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Acquiescer\")\r\n    invoke_custom(38000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimStatique\")\r\n    \r\n    -- Hum.\r\n    invoke_custom(39000, 1, \"Mobile.setMobileAnimation\", otomai, \"AnimComp-Special03\")\r\n    invoke_custom(39000, 1, \"bubble\", otomai, \"quest.zinit.ch4.cine.colere.ogrest.09\")\r\n    invoke_custom(41000, 1, \"clearBubbles\", otomai)\r\n    \r\n    -- On dirait qu'Aguabrial a laissé tomber ceci. C'est de la colère d'Ogrest... scellée dans un anneau !\r\n    \r\n    invoke_custom(42000, 1, \"Mobile.setMobileAnimation\", otomai, \"AnimComp-Special07\")\r\n    invoke_custom(42000, 1, \"bubble\", otomai, \"quest.zinit.ch4.cine.colere.ogrest.10\")\r\n    invoke_custom(46000, 1, \"clearBubbles\", otomai)\r\n    \r\n    -- Il te revient. Porte cet anneau lorsque tu souhaites retrouver une partie de la puissance d'Ogrest. Mais sois prudent{[1*]?e:}, cette fois !\r\n    invoke_custom(47000, 1, \"Mobile.setMobileAnimation\", otomai, \"AnimComp-Special09\")\r\n    invoke_custom(47000, 1, \"bubble\", otomai, \"quest.zinit.ch4.cine.colere.ogrest.11\")\r\n    invoke_custom(52000, 1, \"clearBubbles\", otomai)\r\n    \r\n    invoke_custom(52000, 1, \"skipCinematic\", 19116)\nend\n\n-- [EVENT] Fin de cinématique - Le joueur sort de l'instance et valide l'achievement.\n-- \nfunction event_2307_19123()\n    \nend\n\n-- [EVENT] Fin de combat - on masque l'UI de victoire\n-- \nfunction event_2307_19121()\n    local dialogName = \"fightResultDialog\"\r\n    \r\n    if (UI.isDialogLoaded(dialogName)) then \r\n        \tUI.unloadDialog(dialogName)\r\n     else\r\n     \tUI.addDialogLoadedListener(dialogName, \"UI.unloadDialog\", dialogName)\r\n     end\nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_2307_19111","event_2307_19115","event_2307_19117","event_2307_19120","event_2307_19112","event_2307_19114","event_2307_19116","event_2307_19123","event_2307_19121"],"quest_calls":[],"dialogue_calls":[]},"scenario/2308.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\n-- les fonctions où on cache\r\nfunction hideMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, false)\r\nend\r\n\r\nfunction hidePart(monsterMobileId, partName)\r\n\tMobile.setPartVisible(monsterMobileId, false, partName)\r\nend\r\n\r\n-- les fonctions où on rend visible (à nouveau\r\nfunction showMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, true)\r\nend\r\n\r\nfunction showPart(monsterMobileId, partName)\r\n\tMobile.setPartVisible(monsterMobileId, true, partName)\r\nend\n\n-- [INIT] Serveur - OK\n-- \nfunction event_2308_19144()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario - OK\n-- \nfunction event_2308_19137()\n    \nend\n\n-- [EVENT] Ajout du PNJ Suiveur - masquage du PNJ monde - start\n-- \nfunction event_2308_19138(TovakId)\n    Mobile.addMobileCreationCallback(TovakId, \"hideMonster\", TovakId)\nend\n\n-- [EVENT] Masquage du PNJ monde si le joueur a le PNJ suiveur\n-- WIP : détecter l'état 5161 plutôt que l'étape quand fonctionnel\nfunction event_2308_19143(TovakId)\n    Mobile.addMobileCreationCallback(TovakId, \"hideMonster\", TovakId)\nend\n\n-- [EVENT] Fin quête : Retrait du PNJ suiveur - affichage PNJ monde et Clochette\n-- peut-être changer l'écoute sur une fin de ciné (et lancer une ciné à la fin du dialogue)\r\n-- attention, est annulé par les events utilisant un callback tant qu'on ne sort pas de l'instance.\r\nfunction event_2308_19139(TovakId, VernaId)\n    --Mobile.setMobileVisible(TovakId, true)\n    --Mobile.setPartVisible(VernaId, true, \"Chapeau\")\n    \r\n    Mobile.addMobileCreationCallback(VernaId, \"showPart\", VernaId, \"Chapeau\")\n    Mobile.addMobileCreationCallback(TovakId, \"showMonster\", TovakId)\nend\n\n-- [EVENT] Retrait du PNJ suiveur en revenant dans l'instance - affichage PNJ monde\n-- peut-être changer l'écoute sur une fin de ciné (et lancer une ciné à la fin du dialogue)\r\n-- attention, est annulé par les events utilisant un callback tant qu'on ne sort pas de l'instance.\r\nfunction event_2308_19722(TovakId, VernaId)\n    --Mobile.setMobileVisible(TovakId, true)\n    --Mobile.setPartVisible(VernaId, true, \"Chapeau\")\n    \r\n    Mobile.addMobileCreationCallback(TovakId, \"showMonster\", TovakId)\n    \n    local tovakFollower = createActor(117904550, 0, 2, 0, 4, 3, 9)\n    local playerId = Context.getLeaderId()\n    \n    startCinematicContext(1.9, playerId)\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\")\n    \n    ------------------------------\n    \n    -- Je vais rester ici en t'attendant.\n    invoke_custom(1000, 1, \"bubble\", tovakFollower, \"quest.saharach.tovak.1\")\n    \n    -- Reviens me chercher lorsque tu auras besoin de moi !\n    invoke_custom(4500, 1, \"bubble\", tovakFollower, \"quest.saharach.tovak.2\")\n    \n    invoke_custom(8500, 1, \"Mobile.moveMobile\", tovakFollower, 0, -17, 0, \"Mobile.setMobileDirection\", tovakFollower, 7)\n    invoke_custom(8500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Coucou\")\n    \n    ------------------------------\n    \n    invoke(12500, 1, \"skipCinematic\")\nend\n\n-- [EVENT] Verna n'a pas sa clochette (quête narrative en cours)\n-- \nfunction event_2308_19140(VernaId)\n    Mobile.addMobileCreationCallback(VernaId, \"hidePart\", VernaId, \"Chapeau\")\nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","hideMonster","hidePart","showMonster","showPart","event_2308_19144","event_2308_19137","event_2308_19138","event_2308_19143","event_2308_19139","event_2308_19722","event_2308_19140"],"quest_calls":[],"dialogue_calls":[]},"scenario/2311.lua":{"source":"bubbleNotificationId = 0\r\nNOTIFICATION_INTERVAL = 20000\r\nnotifications = {}\r\n\r\nfunction triggerUpdateInfo()\r\n\tServer.triggerEvent(99)\r\nend\r\n\r\nfunction onNotificationClosed()\r\n\tif (bubbleNotificationId ~= nil  and bubbleNotificationId ~= 0) then bubbleNotificationId = 0 end\r\nend\r\n\r\nfunction pushNotification(textKey, ...)\r\n\tlocal textInfo = {textKey = textKey, textParam = unpack(arg)}\r\n    table.insert(notifications, textInfo)\nend\n\nfunction pushNotificationPosition(pos, textKey, ...)\n\tlocal textInfo = {position = pos, textKey = textKey, textParam = unpack(arg)}\n    table.insert(notifications, textInfo)\nend\r\n\r\nfunction updateNotification()\r\n\tlocal textInfo = notifications[1]\r\n\t\r\n\tif (textInfo == nil) then return end\r\n\t\r\n\tif (bubbleNotificationId == 0) then\r\n\t\tbubbleNotificationId = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_EAST\", -45, -55, false, NOTIFICATION_INTERVAL - 500, true, \"interactiveBubbleDialog4\", 30000, 25000, \"onNotificationClosed\")\r\n\tend\r\n\t\r\n\tBubbleText.setText(bubbleNotificationId, textInfo.textKey, textInfo.textParam)\n\t\n\tlocal pos = textInfo.position\n\tif (pos ~= nil) then\n\t\tlocal x, y, z = longToPosition(pos)\n\t\tBubbleText.addButton(bubbleNotificationId, \"compass\", \"UI.addCompass\", \"battleground.01.general.fight\", x, y, z)\n\tend\n\t\r\n\tBubbleText.show(bubbleNotificationId)\r\n\ttable.remove(notifications, 1)\nend\n\n-- [INIT] Constantes - Score (Classique)\n-- \nfunction event_2311_19212()\n    \nend\n\n-- [INIT] Constantes - Score (Héroïque)\n-- \nfunction event_2311_19742()\n    \nend\n\n-- ~[INIT] Variables & Constantes - Scenario\n-- \nfunction event_2311_19403()\n    \nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_2311_19202(own_team_id)\n    trace(\"PLAYER ENTER INSTANCE\")\r\n    trace(\"team du joueur qui entre dans l'instance\", own_team_id)\r\n    \r\n    triggerUpdateInfo()\r\n    \r\n    setInterval(NOTIFICATION_INTERVAL, \"updateNotification\")\nend\n\n-- [SUPPLY] Ravitaillement récolté - Score Perso & Equipe\n-- La ressource n'est pas utilisable par les héros alors l'event n'est pas dispatch sur eux\nfunction event_2311_19207(event_team_id)\n    trace(\"SUPPLY COLLECTED - OWN SCORE + TEAM SCORE\")\r\n    trace(\"team du joueur qui récolte le ravitaillement\", event_team_id)\r\n    \r\n    triggerUpdateInfo()\nend\n\n-- [SUPPLY] Ravitaillement récolté - Apparition & Settings Chef de Milice + Score Equipe\n-- La ressource n'est pas utilisable par les héros alors l'event n'est pas dispatch sur eux\nfunction event_2311_19208(usergroup_id, event_team_id, chief_id)\n    trace(\"GENERAL SPAWNED - TEAM SCORE\")\r\n    trace(\"id du groupe de monstre\", usergroup_id)\r\n    trace(\"id du général\", chief_id)\r\n    trace(\"team du général\", event_team_id)\r\n    \r\n    UI.writeInChatPipe(13, \"battleground.01.general.incoming\", event_team_id)\r\n    pushNotification(\"battleground.01.general.incoming\", event_team_id)\r\n    \r\n    --triggerUpdateInfo()\nend\n\n-- [WAYPOINT] Chef de Milice arrive à un WP - Etat Waypoint + Score Equipe\n-- \nfunction event_2311_19443(event_team_id, event_waypoint_index, last_waypoint_index, event_chief_position)\n    trace(\"GENERAL AT WAYPOINT - TEAM SCORE\")\r\n    trace(\"team du général\", event_team_id)\r\n    trace(\"event_waypoint_index\", event_waypoint_index)\r\n    trace(\"last_waypoint_index\", last_waypoint_index)\r\n    \r\n    --if (toLong(event_waypoint_index) == toLong(last_waypoint_index)) then\n    --\tUI.writeInChatPipe(13, \"battleground.01.general.progress.end\", event_team_id)\n    \t--pushNotificationPosition(event_chief_position, \"battleground.01.general.progress.end\", event_team_id)\r\n    --\tpushNotification(\"battleground.01.general.progress.end\", event_team_id)\n    --elseif (toLong(event_waypoint_index) >= toLong(last_waypoint_index) - 2) then\n    --\tUI.writeInChatPipe(13, \"battleground.01.general.progress.near.end\", event_team_id)\n    \t--pushNotificationPosition(event_chief_position, \"battleground.01.general.progress.near.end\", event_team_id)\r\n    --\tpushNotification(\"battleground.01.general.progress.near.end\", event_team_id)\n    --else\n    --\tUI.writeInChatPipe(13, \"battleground.01.general.progress\", event_team_id)\n    \t--pushNotificationPosition(event_chief_position, \"battleground.01.general.progress\", event_team_id)\r\n    --\tpushNotification(\"battleground.01.general.progress\", event_team_id)\n    --end\n    \r\n    --triggerUpdateInfo()\nend\n\n-- [FIGHT] Milicien tué - Score Perso\n-- \nfunction event_2311_19221()\n    trace(\"MONSTER KILLED - OWN SCORE\")\nend\n\n-- [FIGHT] Milicien tué - Score Equipe\n-- \nfunction event_2311_19370(event_team_id)\n    trace(\"MONSTER KILLED - TEAM SCORE\")\r\n    trace(\"team du joueur qui a tué le monstre\", event_team_id)\r\n    \r\n    --triggerUpdateInfo()\nend\n\n-- [FIGHT] Joueur tué - Score Perso\n-- On vérifie not IsOutOfPlay(\"\"target\"\") car sinon l'event se déclenche 2 fois sur les joueurs qui sont K.O quand le combat se termine\r\n-- see https://youtrack.ankama.com/issue/wakfuTrunk-35316\nfunction event_2311_19223()\n    trace(\"PLAYER KILLED - OWN SCORE\")\nend\n\n-- [FIGHT] Joueur tué - Score Equipe\n-- On vérifie not IsOutOfPlay(\"\"target\"\") car sinon l'event se déclenche 2 fois sur les joueurs qui sont K.O quand le combat se termine\r\n-- see https://youtrack.ankama.com/issue/wakfuTrunk-35316\nfunction event_2311_19341(event_team_id)\n    trace(\"PLAYER KILLED - TEAM SCORE\")\r\n    trace(\"team du joueur tué\", event_team_id)\r\n    \r\n    --triggerUpdateInfo()\nend\n\n-- [FIGHT] Chef de Milice tué - Score Perso\n-- \nfunction event_2311_19224()\n    trace(\"GENERAL KILLED - OWN SCORE\")\nend\n\n-- [FIGHT] Chef de Milice tué - Score Equipe\n-- \nfunction event_2311_19342(event_team_id)\n    trace(\"GENERAL KILLED - TEAM SCORE\")\r\n    trace(\"team du général tué\", event_team_id)\r\n    \r\n    UI.writeInChatPipe(13, \"battleground.01.general.killed\", event_team_id)\r\n    pushNotification(\"battleground.01.general.killed\", event_team_id)\r\n    \r\n    --triggerUpdateInfo()\nend\n\n-- [FIGHT] Joueur débute un combat PvP - Score Perso\n-- \nfunction event_2311_19575(blueTeamCount, redTeamCount, event_team_id)\n    trace(\"PLAYER START PVP FIGHT - OWN SCORE\")\r\n    trace(\"blueTeamCount\", blueTeamCount)\r\n    trace(\"redTeamCount\", redTeamCount)\r\n    trace(\"team du joueur concerné\", event_team_id)\nend\n\n-- [FIGHT][DEATH] Joueur mort en fin de combat - Retrait des Etats & Objets\n-- \nfunction event_2311_19632()\n    \nend\n\n-- [EVENT] BG_START - Procédures de démarrage du BG\n-- \nfunction event_2311_19419()\n    trace(\"BATTLEGROUND_START\")\nend\n\n-- [EVENT] BG_ENDED - Procédures de fin du BG\n-- On écoute BG_ENDED pour être sûr d'avoir terminé les procédures du scénario 2320\nfunction event_2311_19423()\n    trace(\"BATTLEGROUND_ENDED\")\nend\n\n-- [UI] Score modifié - Mise à jour de l'UI\n-- \nfunction event_2311_19371(att_score, att_supply, def_score, def_supply, own_score, own_team_id, att_member, def_member)\n    trace(\"own_team_id\", own_team_id)\r\n    --trace(\"own_score\", own_score)\r\n    trace(\"att_score\", att_score, \"def_score\", def_score)\r\n    trace(\"att_supply\", att_supply, \"def_supply\", def_supply)\r\n    trace(\"att_member\", att_member, \"def_member\", def_member)\r\n    \n    local att_supply = toLong(att_supply)\r\n    local def_supply = toLong(def_supply)\r\n    \r\n    local detailText = Context.getTranslation(\"battleground.01.battlegroundBarDetailText\", att_supply, def_supply)\t\r\n    UI.setTextWidget(\"battlegroundBarDialog\", \"battlegroundBarDetailTextId\", detailText)\nend\n\n-- [NOTIF] Chef de Milice attaqué\n-- \nfunction event_2311_19406(event_team_id, fight_center_position)\n    UI.writeInChatPipe(13, \"battleground.01.general.attacked\", event_team_id)\r\n    pushNotificationPosition(fight_center_position, \"battleground.01.general.attacked\", event_team_id)\nend\n\n-- [NOTIF] Notifications récurrentes\n-- \nfunction event_2311_19469(att_score, def_score)\n    local att_score = toLong(att_score)\r\n    local def_score = toLong(def_score)\r\n    \r\n    local score_diff = math.abs(att_score - def_score)\r\n    local winning_team = \"att\"\r\n    if (def_score > att_score) then winning_team = \"def\" end\r\n    \r\n    if (score_diff >= 500) then\r\n    \tUI.writeInChatPipe(13, \"battleground.00.team.score.\" .. winning_team .. \".winning\", event_team_id)\r\n    \tpushNotification(\"battleground.00.team.score.\" .. winning_team .. \".winning\", event_team_id)\r\n    end\nend\n\n-- [STATS] Une demande de ravitaillement a été droppée\n-- \nfunction event_2311_19465()\n    \nend\n\n-- [STATS] Une demande de ravitaillement a été plantée\n-- \nfunction event_2311_19466()\n    \nend\n\n-- [SUPPLY] Bonus Joueur\n-- \nfunction event_2311_21504()\n    \nend\n\n-- [SUPPLY] Bonus Milicien\n-- \nfunction event_2311_21505()\n    \nend\n\n-- [SUPPLY] Bonus Vitesse\n-- \nfunction event_2311_21506()\n    \nend\n\n","functions":["triggerUpdateInfo","onNotificationClosed","pushNotification","pushNotificationPosition","updateNotification","event_2311_19212","event_2311_19742","event_2311_19403","event_2311_19202","event_2311_19207","event_2311_19208","event_2311_19443","event_2311_19221","event_2311_19370","event_2311_19223","event_2311_19341","event_2311_19224","event_2311_19342","event_2311_19575","event_2311_19632","event_2311_19419","event_2311_19423","event_2311_19371","event_2311_19406","event_2311_19469","event_2311_19465","event_2311_19466","event_2311_21504","event_2311_21505","event_2311_21506"],"quest_calls":[],"dialogue_calls":[]},"scenario/2312.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\nfunction cameraShake()\r\n \tlocal shakeEffectId = Effect.createCameraShakeEffect(250, 500, 250, 3)\r\n \tinvoke(1000, 1, \"Effect.stopEffect\", shakeEffectId)\r\nend\r\n\r\nfunction cameraShakeViolent()\r\n \tlocal shakeEffectIdv = Effect.createCameraShakeEffect(500, 1500, 250, 5)\r\n \tinvoke(2000, 1, \"Effect.stopEffect\", shakeEffectIdv)\r\nend\r\n\r\nfunction cameraShakeOne()\r\n \tlocal shakeEffectIdO = Effect.createCameraShakeEffect(0, 500, 0, 3)\r\n \tinvoke(500, 1, \"Effect.stopEffect\", shakeEffectIdO)\r\nend\r\n\r\n bubbleFightInfoId = 0\r\n\r\nfunction closeFightInfo()\r\n\tif (bubbleFightInfoId ~= nil  and bubbleFightInfoId ~= 0) then BubbleText.close(bubbleFightInfoId) end\r\nend\r\n\r\nfunction onFightInfoClosed()\r\n\tif (bubbleFightInfoId ~= nil  and bubbleFightInfoId ~= 0) then bubbleFightInfoId = 0 end\r\nend\r\n\r\nfunction updateFightInfo(own_score, palier_two, palier_three, palier_four, forceDisplayUI)\r\n\tlocal palier_two = toLong(palier_two)\r\n\tlocal palier_three = toLong(palier_three)\r\n\tlocal palier_four = toLong(palier_four)\r\n\r\n\tif (bubbleFightInfoId == 0) then\r\n\t\tbubbleFightInfoId = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_WEST\", 0, -60, false, 2147483647, true, \"interactiveBubbleDialog5\", 30000, 25000, \"onFightInfoClosed\")\r\n\tend\r\n\r\n\tBubbleText.setText(bubbleFightInfoId, \"dungeon.tour.score.info\", own_score, palier_two, palier_three, palier_four)\r\n\t\r\n\tif (forceDisplayUI) then BubbleText.show(bubbleFightInfoId) end\r\nend\n\n-- [INIT] Variables & Constantes\n-- \nfunction event_2312_19229()\n    \nend\n\n-- [INIT] Application des états selon le random\n-- \nfunction event_2312_19228()\n    \nend\n\n-- [INIT] Le joueur entre dans l'instance - Inscription au scénario\n-- \nfunction event_2312_19216()\n    \nend\n\n-- [ACH][NOTIF] On valide les objectifs d'achievement si le joueur gagne\n-- \nfunction event_2312_19364()\n    \nend\n\n-- [INIT] Le joueur entre dans l'instance & Fin du combat - Calcul du Score\n-- \nfunction event_2312_19343(own_score, palier_two, palier_three, palier_four)\n    trace(\"--- PLAYER ENTER INSTANCE - SCORE COMPUTE ---\")\r\n    \r\n    updateFightInfo(own_score, palier_two, palier_three, palier_four, true)\nend\n\n-- [EVENT] On rend les monstres de la salle du boss inattaquable\n-- Cela nous permet d'éviter d'avoir la mauvaise bulle de combat sur le combat du boss\nfunction event_2312_19400()\n    \nend\n\n-- [EVENT] Cinématique Agonie - Alternative\n-- on joue la cinématique avant l'autre à cause de la variable cineDone\r\n-- quick fix : on ne joue cette ciné que pour EventTriggerer() car elle pouvait être jouée pour des personnages trop loin en nombre de partitions, et surtout des personnages qui étaient en combat\nfunction event_2312_19248(agonie, mobA, mobB, mobC, cineDone)\n    trace(cineDone)\r\n    \r\n    local playerId = Context.getLeaderId()\r\n    local agonieId = toLong(agonie)\r\n    local mobAId = toLong(mobA)\r\n    local mobBId = toLong(mobB)\r\n    local mobCId = toLong(mobC)\r\n     \r\n    startCinematicContext(1.3, agonieId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\")\r\n    \r\n    invoke_custom(1000, 1, \"bubble\", agonieId, \"dungeon.tour.agonie.cine.7\")\r\n    invoke_custom(1000, 1, \"Mobile.setMobileAnimation\", agonieId, \"AnimComp-Cine-Parler\")  -- agonie se parle à elle même\r\n    \r\n    invoke_custom(3000, 1, \"bubble\", agonieId, \"dungeon.tour.agonie.cine.8\")\r\n    invoke_custom(3000, 1, \"Mobile.setMobileAnimation\", agonieId, \"AnimComp-Cine-Enerve\") --agonie tape un coup de bâton par terre\r\n    invoke_custom(3000, 1, \"cameraShakeOne\") -- shake unique timé avec le coup de bâton\n    \r\n    invoke_custom(5000, 1, \"skipCinematic\")\nend\n\n-- [EVENT] Cinématique Agonie\n-- \nfunction event_2312_19218(agonie, mobA, mobB, mobC)\n    local playerId = Context.getLeaderId()\r\n    local agonieId = toLong(agonie)\r\n    local mobAId = toLong(mobA)\r\n    local mobBId = toLong(mobB)\r\n    local mobCId = toLong(mobC)\r\n     \r\n    startCinematicContext(1.3, agonieId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\")\r\n    --Effect.createBloomPostProcess(250,1000,750, 1,0, 4, 0, 0, 2, 1)\r\n    \r\n    invoke_custom(1000, 1, \"bubble\", agonieId, \"dungeon.tour.agonie.cine.1\")\r\n    invoke_custom(1000, 1, \"Mobile.setMobileAnimation\", agonieId, \"AnimComp-Cine-Parler\") -- agonie se parle à elle même\r\n    \r\n    invoke_custom(5000, 1, \"bubble\", agonieId, \"dungeon.tour.agonie.cine.2\")\r\n    invoke_custom(5000, 1, \"Mobile.setMobileAnimation\", agonieId, \"AnimSort-01\") --agonie est vénère parce qu'elle est en trépamort (tape du bâton par terre, ou crie)\r\n    \r\n    invoke_custom(8000, 1, \"bubble\", agonieId, \"dungeon.tour.agonie.cine.3\")\r\n    invoke_custom(8000, 1, \"cameraShake\") --agonie remarque les joueurs, shake caméra pour accentuer\n    \r\n    invoke_custom(11000, 1, \"bubble\", agonieId, \"dungeon.tour.agonie.cine.4\")\r\n    invoke_custom(11000, 1, \"Mobile.setMobileAnimation\", agonieId, \"AnimComp-Cine-Doigt\") --agonie pointe du doigt les joueurs\r\n    \r\n    invoke_custom(17000, 1, \"bubble\", agonieId, \"dungeon.tour.agonie.cine.5\")\r\n    invoke_custom(17000, 1, \"Mobile.setMobileAnimation\", agonieId, \"AnimComp-Cine-Parler\")\r\n    \r\n    invoke_custom(20700, 1, \"bubble\", agonieId, \"dungeon.tour.agonie.cine.6\")\r\n    invoke_custom(21000, 1, \"Mobile.setMobileAnimation\", agonieId, \"AnimComp-Cine-Enerve\") --agonie taunt les joueurs/les incite à venir se faire maraver (anim crier ou bâton fort)\r\n    invoke_custom(21000, 1, \"cameraShakeViolent\") --shake un peu plus violent pour appuyer son rire\n    \r\n    invoke_custom(24000, 1, \"skipCinematic\")\nend\n\n-- [EVENT] Lancement du combat spécial\n-- on skippe la cinématique pour tout le monde \nfunction event_2312_19246()\n    skipCinematic()\r\nend\n\n-- [EVENT] Démarrage du combat - Initialisation des variables\n-- \nfunction event_2312_19230()\n    \nend\n\n-- [EVENT] Démarrage du combat - Pose des zones flags\n-- \nfunction event_2312_19231()\n    \nend\n\n-- [EVENT] Un joueur a perdu/est mort\n-- \nfunction event_2312_19247(arpagone)\n    local arpagoneId = toLong(arpagone)\r\n    local playerId = Context.getLeaderId()\r\n    \r\n    Mobile.setMobileDirection(playerId, 7)\r\n    BubbleText.showText(arpagoneId, \"dungeon.tour.arpagone.cine.1\", 0, 40, false)\r\n    Mobile.setMobileAnimation(playerId, \"AnimEmote-Supplie-Debut\") --quand les joueurs voient arpagone, ils la supplient de les sauver\r\n    Mobile.setMobileAnimation(arpagoneId, \"AnimComp-Eventail\")  --arpagone se moque des joueurs (l'anim avec les tickets)\nend\n\n-- [EVENT] Fin de combat - les monstres ont gagné - plus de combat\n-- \nfunction event_2312_19415(arpagone)\n    \nend\n\n-- [EVENT] Empêcher les joueurs d'aller à droite\n-- quand ils sont avec Arpagone\nfunction event_2312_19327(arpagone)\n    local playerId = Context.getLeaderId()\r\n    local arpagoneId = toLong(arpagone)\r\n    \r\n    startCinematicContext(1.5, arpagoneId)\r\n    \r\n    invoke_custom(1000, 1, \"bubble\", arpagoneId, \"dungeon.tour.arpagone.cine.2\")\r\n    invoke_custom(1000, 1, \"Mobile.setMobileAnimation\", arpagoneId, \"AnimComp-Hele\")\r\n    \r\n    invoke_custom(2000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Fievre\")\r\n    \r\n    invoke_custom(4000, 1, \"Mobile.moveMobile\", playerId, -12, -115, 0)\r\n    \r\n    invoke_custom(6000, 1, \"skipCinematic\")\nend\n\n-- [EVENT] Fin Cinématique - TP joueur\n-- \nfunction event_2312_19329()\n    \nend\n\n-- [EVENT] Arpagone - Continue\n-- \nfunction event_2312_19251()\n    \nend\n\n-- [ACH][EVENT][TBL1] Echec si au moins un joueur est passé KO\n-- \nfunction event_2312_19345()\n    \nend\n\n-- [ACH][EVENT][TBL1] Echec si au moins un joueur a été soigné\n-- \nfunction event_2312_19347()\n    \nend\n\n-- [ACH][EVENT][TBL1] Echec si un joueur termine le combat avec moins de 80% PdV\n-- \nfunction event_2312_19366()\n    \nend\n\n-- [ACH][EVENT][TBL3] Echec si au moins un joueur a déclenché un Poison\n-- \nfunction event_2312_19349()\n    \nend\n\n-- [ACH][EVENT][TBL3] Echec si un sortilège d'Agonie n'a pas été brisé\n-- \nfunction event_2312_19365()\n    \nend\n\n-- [ACH][EVENT][TBL3] Echec si un monstre est tué sans la totalité de son état Résistance\n-- \nfunction event_2312_19351()\n    \nend\n\n-- [ACH][EVENT][TBL3] Echec si un monstre est tué avec état Résistance\n-- \nfunction event_2312_19353()\n    \nend\n\n-- [ACH][EVENT][TBL3] Echec si un cristal est affaibli\n-- \nfunction event_2312_19355()\n    \nend\n\n-- [ACH][EVENT][TBL4] Echec si un joueur termine son tour avec des PA non-dépensés\n-- \nfunction event_2312_19357()\n    \nend\n\n-- [ACH][EVENT][TBL4] Echec si un joueur utilise un sort spécial\n-- \nfunction event_2312_19384()\n    \nend\n\n-- [ACH][EVENT][TBL4] Echec si un joueur porte une arme en rentrant en combat\n-- \nfunction event_2312_19359()\n    \nend\n\n-- [ACH][EVENT][TBL4] Echec si un joueur utilise un PW en combat\n-- \nfunction event_2312_19361()\n    \nend\n\n-- [EVENT] Variable à 1 quand les joueurs ont gagné\n-- \nfunction event_2312_19452()\n    \nend\n\n-- [INIT] Le joueur entre dans l'instance - On consomme la clef\n-- \nfunction event_2312_19459()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","cameraShake","cameraShakeViolent","cameraShakeOne","closeFightInfo","onFightInfoClosed","updateFightInfo","event_2312_19229","event_2312_19228","event_2312_19216","event_2312_19364","event_2312_19343","event_2312_19400","event_2312_19248","event_2312_19218","event_2312_19246","event_2312_19230","event_2312_19231","event_2312_19247","event_2312_19415","event_2312_19327","event_2312_19329","event_2312_19251","event_2312_19345","event_2312_19347","event_2312_19366","event_2312_19349","event_2312_19365","event_2312_19351","event_2312_19353","event_2312_19355","event_2312_19357","event_2312_19384","event_2312_19359","event_2312_19361","event_2312_19452","event_2312_19459"],"quest_calls":[],"dialogue_calls":[]},"scenario/2313.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\n\n-- [INIT] Variables\n-- \nfunction event_2313_19266()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2313_19217()\n    \nend\n\n-- [EVENT] Cinématique Arrivée - Travelling Tour\n-- \nfunction event_2313_19233()\n    local playerId = Context.getLeaderId()\r\n    \r\n    Camera.setUserZoomLocked(true)\r\n    \r\n    startCinematicContext(0.6, playerId)\r\n    \r\n    invoke_custom(00990, 1, \"Camera.setMoveSpeedFactor\", 0.15)\r\n    invoke_custom(01000, 1, \"Camera.scrollTo\", -9, -7, 30)\r\n    invoke_custom(07000, 1, \"Camera.scrollTo\", -2, 3, -4)\r\n    \r\n    invoke_custom(12000, 1, \"Camera.attachCameraToMobile\", playerId)\r\n    invoke_custom(12000, 1, \"Camera.setMoveSpeedFactor\", 1)\r\n    invoke_custom(12000, 1, \"Camera.setUserZoomLocked\", false)\r\n    invoke_custom(12000, 1, \"Camera.setZoomFactor\", 1)\r\n    \r\n    invoke_custom(12500, 1, \"skipCinematic\")\nend\n\n-- [EVENT] Cinématique Arpagone - Accès Hub ACH 3908 en cours\n-- Le Joueur essaye d'entrerdans le hub avec l'achievement 3908 non terminé\nfunction event_2313_19265(arpagone)\n    local playerId = Context.getLeaderId()\r\n    local arpagoneId = toLong(arpagone)\r\n     \r\n    startCinematicContext(1.6, arpagoneId)\r\n    \r\n    invoke_custom(800, 1, \"Mobile.setMobileDirection\", arpagoneId, 1) --arpagone se retourne vers le joueur\r\n    invoke_custom(1000, 1, \"bubble\", arpagoneId, \"quest.tour.arpagone.trigger.1\")\r\n    invoke_custom(1000, 1, \"Mobile.setMobileAnimation\", arpagoneId, \"AnimComp-Hele\") --animation de héler\r\n    \r\n    invoke_custom(2000, 1, \"Mobile.setMobileDirection\", arpagoneId, 3) --on retourne arpagone du bon côté\r\n    invoke_custom(2000, 1, \"stopCinematicContext\", 1, playerId)\r\n    invoke_custom(5000, 1, \"clearBubbles\", arpagoneId)\nend\n\n-- [EVENT] Le joueur essaie de rentrer alors qu'il n'a pas réuni les conditions nécessaires\n-- \nfunction event_2313_22496()\n    bubble(arpagoneId, \"quest.tour.arpagone.trigger.1\")\nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_2313_19266","event_2313_19217","event_2313_19233","event_2313_19265","event_2313_22496"],"quest_calls":[],"dialogue_calls":[]},"scenario/2314.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\n\n-- [INIT] Le joueur entre dans l'instance - Inscription au scénario\n-- \nfunction event_2314_19238()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_2314_19238"],"quest_calls":[],"dialogue_calls":[]},"scenario/2315.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\nfunction cameraShake()\r\n \tlocal shakeEffectId = Effect.createCameraShakeEffect(250, 500, 250, 3)\r\n \tinvoke(1000, 1, \"Effect.stopEffect\", shakeEffectId)\r\nend\r\n\r\nfunction cameraShakeViolent()\r\n \tlocal shakeEffectIdv = Effect.createCameraShakeEffect(1000, 3000, 250, 7)\r\n \tinvoke(4000, 1, \"Effect.stopEffect\", shakeEffectIdv)\r\nend\r\n\r\nfunction cameraShakeOne()\r\n \tlocal shakeEffectIdO = Effect.createCameraShakeEffect(0, 500, 0, 3)\r\n \tinvoke(500, 1, \"Effect.stopEffect\", shakeEffectIdO)\r\nend\r\n\r\nbubbleFightInfoId = 0\r\n\r\nfunction closeFightInfo()\r\n\tif (bubbleFightInfoId ~= nil  and bubbleFightInfoId ~= 0) then BubbleText.close(bubbleFightInfoId) end\r\nend\r\n\r\nfunction onFightInfoClosed()\r\n\tif (bubbleFightInfoId ~= nil  and bubbleFightInfoId ~= 0) then bubbleFightInfoId = 0 end\r\nend\r\n\r\nfunction updateFightInfo(own_score, palier_one, palier_two, palier_three, forceDisplayUI)\r\n\tlocal palier_one = toLong(palier_one)\r\n\tlocal palier_two = toLong(palier_two)\r\n\tlocal palier_three = toLong(palier_three)\r\n\r\n\tif (bubbleFightInfoId == 0) then\r\n\t\tbubbleFightInfoId = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_WEST\", 0, -60, false, 2147483647, true, \"interactiveBubbleDialog5\", 30000, 25000, \"onFightInfoClosed\")\r\n\tend\r\n\r\n\tBubbleText.setText(bubbleFightInfoId, \"dungeon.tour.score.info\", own_score, palier_one, palier_two, palier_three)\r\n\t\r\n\tif (forceDisplayUI) then BubbleText.show(bubbleFightInfoId) end\r\nend\n\n-- [INIT] Variables & Constantes\n-- \nfunction event_2315_19252()\n    \nend\n\n-- [INIT] Application des états selon le random\n-- \nfunction event_2315_19254()\n    \nend\n\n-- [INIT] Le joueur entre dans l'instance - Inscription au scénario\n-- \nfunction event_2315_19253()\n    \nend\n\n-- [ACH][NOTIF] On valide les objectifs d'achievement si le joueur gagne\n-- \nfunction event_2315_19368()\n    \nend\n\n-- [INIT] Le joueur entre dans l'instance & Fin du combat - Calcul du Score\n-- \nfunction event_2315_19344(own_score, palier_one, palier_two, palier_three)\n    trace(\"--- PLAYER ENTER INSTANCE - SCORE COMPUTE ---\")\r\n    \r\n    updateFightInfo(own_score, palier_one, palier_two, palier_three, true)\nend\n\n-- [EVENT] On rend les monstres de la salle du boss inattaquable\n-- Cela nous permet d'éviter d'avoir la mauvaise bulle de combat sur le combat du boss\nfunction event_2315_19402()\n    \nend\n\n-- [EVENT] Cinématique Agonie - Alternative\n-- on joue la cinématique avant l'autre à cause de la variable cineDone\r\n-- quick fix : on ne joue cette ciné que pour EventTriggerer() car elle pouvait être jouée pour des personnages trop loin en nombre de partitions, et surtout des personnages qui étaient en combat\nfunction event_2315_19312(agonie, mobA, mobB, mobC, cineDone)\n    trace(cineDone)\r\n    \r\n    local playerId = Context.getLeaderId()\r\n    local agonieId = toLong(agonie)\r\n    local mobAId = toLong(mobA)\r\n    local mobBId = toLong(mobB)\r\n    local mobCId = toLong(mobC)\r\n     \r\n    startCinematicContext(1.3, agonieId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\")\r\n    \r\n    invoke_custom(1000, 1, \"bubble\", agonieId, \"dungeon.tour.agonie.cine.7\")\r\n    invoke_custom(1000, 1, \"Mobile.setMobileAnimation\", agonieId, \"AnimComp-Cine-Parler\")  -- agonie se parle à elle même\r\n    \r\n    invoke_custom(3000, 1, \"bubble\", agonieId, \"dungeon.tour.agonie.cine.8\")\r\n    invoke_custom(3000, 1, \"Mobile.setMobileAnimation\", agonieId, \"AnimComp-Cine-Enerve\") --agonie tape un coup de bâton par terre\r\n    invoke_custom(3000, 1, \"cameraShakeOne\") -- shake unique timé avec le coup de bâton\r\n    \r\n    invoke_custom(5000, 1, \"skipCinematic\")\nend\n\n-- [EVENT] Cinématique Agonie\n-- \nfunction event_2315_19311(agonie, mobA, mobB, mobC)\n    local playerId = Context.getLeaderId()\r\n    local agonieId = toLong(agonie)\r\n    local mobAId = toLong(mobA)\r\n    local mobBId = toLong(mobB)\r\n    local mobCId = toLong(mobC)\r\n     \r\n    startCinematicContext(1.3, agonieId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\")\r\n    --Effect.createBloomPostProcess(250,1000,750, 1,0, 4, 0, 0, 2, 1)\r\n    \r\n    invoke_custom(1000, 1, \"bubble\", agonieId, \"dungeon.tour.agonie.cine.1\")\r\n    invoke_custom(1000, 1, \"Mobile.setMobileAnimation\", agonieId, \"AnimComp-Cine-Parler\") -- agonie se parle à elle même\r\n    \r\n    invoke_custom(5000, 1, \"bubble\", agonieId, \"dungeon.tour.agonie.cine.2\")\r\n    invoke_custom(5000, 1, \"Mobile.setMobileAnimation\", agonieId, \"AnimSort-01\") --agonie est vénère parce qu'elle est en trépamort (tape du bâton par terre, ou crie)\r\n    \r\n    invoke_custom(8000, 1, \"bubble\", agonieId, \"dungeon.tour.agonie.cine.3\")\r\n    invoke_custom(8000, 1, \"cameraShake\") --agonie remarque les joueurs, shake caméra pour accentuer\r\n    \r\n    invoke_custom(11000, 1, \"bubble\", agonieId, \"dungeon.tour.agonie.cine.4\")\r\n    invoke_custom(11000, 1, \"Mobile.setMobileAnimation\", agonieId, \"AnimComp-Cine-Doigt\") --agonie pointe du doigt les joueurs\r\n    \r\n    invoke_custom(17000, 1, \"bubble\", agonieId, \"dungeon.tour.agonie.cine.5\")\r\n    invoke_custom(17000, 1, \"Mobile.setMobileAnimation\", agonieId, \"AnimComp-Cine-Parler\")\r\n    \r\n    invoke_custom(21000, 1, \"bubble\", agonieId, \"dungeon.tour.agonie.cine.6\")\r\n    invoke_custom(21000, 1, \"Mobile.setMobileAnimation\", agonieId, \"AnimComp-Cine-Enerve\") --agonie taunt les joueurs/les incite à venir se faire maraver (anim crier ou bâton fort)\r\n    invoke_custom(21000, 1, \"cameraShakeViolent\") --shake un peu plus violent pour appuyer son rire\r\n    \r\n    invoke_custom(25000, 1, \"skipCinematic\")\nend\n\n-- [EVENT] Lancement du combat spécial\n-- on skippe la cinématique pour tout le monde \nfunction event_2315_19313()\n    skipCinematic()\r\nend\n\n-- [EVENT] Démarrage du combat - Initialisation des variables\n-- \nfunction event_2315_19259()\n    \nend\n\n-- [EVENT] Démarrage du combat - Pose des zones flags\n-- \nfunction event_2315_19260()\n    \nend\n\n-- [EVENT] Un joueur a perdu/est mort\n-- \nfunction event_2315_19314(arpagone)\n    local arpagoneId = toLong(arpagone)\r\n    local playerId = Context.getLeaderId()\r\n    \r\n    Mobile.setMobileDirection(playerId, 7)\r\n    BubbleText.showText(arpagoneId, \"dungeon.tour.arpagone.cine.1\", 0, 40, false)\r\n    Mobile.setMobileAnimation(playerId, \"AnimEmote-Supplie-Debut\") --quand les joueurs voient arpagone, ils la supplient de les sauver\r\n    Mobile.setMobileAnimation(arpagoneId, \"AnimComp-Eventail\")  --arpagone se moque des joueurs (l'anim avec les tickets)\nend\n\n-- [EVENT] Fin de combat - les monstres ont gagné - plus de combat\n-- \nfunction event_2315_19418(arpagone)\n    \nend\n\n-- [EVENT] Empêcher les joueurs d'aller à droite\n-- quand ils sont avec Arpagone\nfunction event_2315_19392(arpagone)\n    local playerId = Context.getLeaderId()\r\n    local arpagoneId = toLong(arpagone)\r\n    \r\n    startCinematicContext(1.5, arpagoneId)\r\n    \r\n    invoke_custom(1000, 1, \"bubble\", arpagoneId, \"dungeon.tour.arpagone.cine.2\")\r\n    invoke_custom(1000, 1, \"Mobile.setMobileAnimation\", arpagoneId, \"AnimComp-Hele\")\r\n    \r\n    invoke_custom(2000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Fievre\")\r\n    \r\n    invoke_custom(4000, 1, \"Mobile.moveMobile\", playerId, -12, -115, 0)\r\n    \r\n    invoke_custom(6000, 1, \"skipCinematic\")\nend\n\n-- [EVENT] Fin Cinématique - TP joueur\n-- \nfunction event_2315_19393()\n    \nend\n\n-- [EVENT] Arpagone - Continue\n-- \nfunction event_2315_19315()\n    \nend\n\n-- [ACH][EVENT][TBL1] Echec si au moins un joueur est passé KO\n-- \nfunction event_2315_19367()\n    \nend\n\n-- [ACH][EVENT][TBL1] Echec si un joueur à moins de 80% de ses PdV\n-- \nfunction event_2315_19372()\n    \nend\n\n-- [ACH][EVENT][TBL1] Echec si un soin est fait durant le combat\n-- \nfunction event_2315_19373()\n    \nend\n\n-- [ACH][EVENT][TBL3] Réussite si la bordure a été activé au moins 3 fois\n-- \nfunction event_2315_19377()\n    \nend\n\n-- [ACH][EVENT][TBL3] Réussite si un joueur reçoit Surpuissance Cristalline\n-- \nfunction event_2315_19376()\n    \nend\n\n-- [ACH][EVENT][TBL3] Echec si un joueur subit un effet de sort de Déchaînement\n-- \nfunction event_2315_19378()\n    \nend\n\n-- [ACH][EVENT][TBL3] Echec si un joueur subit un renvoi de dégâts\n-- \nfunction event_2315_19379()\n    \nend\n\n-- [ACH][EVENT][TBL3] Réussite si tous les joueurs ont eu la Surpuissance Cristalline\n-- \nfunction event_2315_19383()\n    \nend\n\n-- [ACH][EVENT][TBL4] Echec si un joueur a une arme au début du combat\n-- \nfunction event_2315_19380()\n    \nend\n\n-- [ACH][EVENT][TBL4] Echec si un joueur n'est pas PW max en fin de combat\n-- \nfunction event_2315_19381()\n    \nend\n\n-- [ACH][EVENT][TBL4] Echec si un joueur à 0 PM en fin de tour\n-- \nfunction event_2315_19382()\n    \nend\n\n-- [ACH][EVENT][TBL4] Validation si un joueur est mort et résu sur irradiation\n-- \nfunction event_2315_19389()\n    \nend\n\n-- [EVENT] Variable à 1 quand les joueurs ont gagné\n-- \nfunction event_2315_19451()\n    \nend\n\n-- [INIT] Le joueur entre dans l'instance - On consomme la clef\n-- \nfunction event_2315_19460()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","cameraShake","cameraShakeViolent","cameraShakeOne","closeFightInfo","onFightInfoClosed","updateFightInfo","event_2315_19252","event_2315_19254","event_2315_19253","event_2315_19368","event_2315_19344","event_2315_19402","event_2315_19312","event_2315_19311","event_2315_19313","event_2315_19259","event_2315_19260","event_2315_19314","event_2315_19418","event_2315_19392","event_2315_19393","event_2315_19315","event_2315_19367","event_2315_19372","event_2315_19373","event_2315_19377","event_2315_19376","event_2315_19378","event_2315_19379","event_2315_19383","event_2315_19380","event_2315_19381","event_2315_19382","event_2315_19389","event_2315_19451","event_2315_19460"],"quest_calls":[],"dialogue_calls":[]},"scenario/2316.lua":{"source":"bubbleNotificationId = 0\r\nNOTIFICATION_INTERVAL = 20000\r\nnotifications = {}\r\n\r\nfunction triggerUpdateInfo()\r\n\tServer.triggerEvent(99)\r\nend\r\n\r\nfunction onNotificationClosed()\r\n\tif (bubbleNotificationId ~= nil  and bubbleNotificationId ~= 0) then bubbleNotificationId = 0 end\r\nend\r\n\r\nfunction pushNotification(textKey, ...)\r\n\tlocal textInfo = {textKey = textKey, textParam = unpack(arg)}\r\n    table.insert(notifications, textInfo)\r\nend\r\n\r\nfunction pushNotificationPosition(pos, textKey, ...)\r\n\tlocal textInfo = {position = pos, textKey = textKey, textParam = unpack(arg)}\r\n    table.insert(notifications, textInfo)\r\nend\r\n\r\nfunction updateNotification()\r\n\tlocal textInfo = notifications[1]\r\n\t\r\n\tif (textInfo == nil) then return end\r\n\t\r\n\tif (bubbleNotificationId == 0) then\r\n\t\tbubbleNotificationId = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_EAST\", -45, -55, false, NOTIFICATION_INTERVAL - 500, true, \"interactiveBubbleDialog4\", 30000, 25000, \"onNotificationClosed\")\r\n\tend\r\n\t\r\n\tBubbleText.setText(bubbleNotificationId, textInfo.textKey, textInfo.textParam)\r\n\t\r\n\tlocal pos = textInfo.position\r\n\tif (pos ~= nil) then\r\n\t\tlocal x, y, z = longToPosition(pos)\r\n\t\tBubbleText.addButton(bubbleNotificationId, \"compass\", \"UI.addCompass\", \"battleground.01.general.fight\", x, y, z)\r\n\tend\r\n\t\r\n\tBubbleText.show(bubbleNotificationId)\r\n\ttable.remove(notifications, 1)\r\nend\n\n-- [INIT] Constantes - Score (Classique)\n-- \nfunction event_2316_19271()\n    \nend\n\n-- [INIT] Constantes - Score (Héroïque)\n-- \nfunction event_2316_19743()\n    \nend\n\n-- [INIT] Variables & Constantes - Scenario\n-- \nfunction event_2316_19407()\n    \nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_2316_19414(own_team_id)\n    trace(\"PLAYER ENTER INSTANCE\")\r\n    trace(\"team du joueur qui entre dans l'instance\", own_team_id)\r\n    \r\n    triggerUpdateInfo()\r\n    \r\n    setInterval(NOTIFICATION_INTERVAL, \"updateNotification\")\nend\n\n-- [FLOWER] Fleur récoltée - Application Etat\n-- \nfunction event_2316_19701(event_team_id)\n    trace(\"FLOWER HARVESTED\")\r\n    \r\n    --UI.writeInChatPipe(13, \"battleground.02.flag.collected.01\", event_team_id)\r\n    --pushNotification(\"battleground.02.flag.collected.01\", event_team_id)\r\nend\n\n-- [FLOWER] Fleur déposée/volée dans le pot - Attaque - Score Perso\n-- \nfunction event_2316_19704(event_team_id, att_flower)\n    trace(\"POT DE FLEUR - ATTAQUE\")\r\n    trace(\"id de la team du joueur qui a fait l'action\", event_team_id)\r\n    trace(\"att_flower\", att_flower)\r\n    \r\n    triggerUpdateInfo()\nend\n\n-- [FLOWER] Fleur déposée/volée dans le pot - Défense - Score Perso\n-- \nfunction event_2316_19706(event_team_id, def_flower)\n    trace(\"POT DE FLEUR - DEFENSE\")\r\n    trace(\"id de la team du joueur qui a fait l'action\", event_team_id)\r\n    trace(\"def_flower\", def_flower)\r\n    \r\n    triggerUpdateInfo()\nend\n\n-- [FLOWER] Scoring Fleur Over-Time - Score Equipe\n-- \nfunction event_2316_19705()\n    \nend\n\n-- [FIGHT] Joueur tué - Score Perso\n-- On vérifier not IsOutOfPlay(\"target\") car sinon ça déclenche 2 fois sur les joueurs K.O à la fin du combat\r\n-- see https://youtrack.ankama.com/issue/wakfuTrunk-35316\nfunction event_2316_19431()\n    trace(\"PLAYER KILLED - OWN SCORE\")\nend\n\n-- [FIGHT] Joueur tué - Score Equipe\n-- On vérifier not IsOutOfPlay(\"target\") car sinon ça déclenche 2 fois sur les joueurs K.O à la fin du combat\r\n-- see https://youtrack.ankama.com/issue/wakfuTrunk-35316\nfunction event_2316_19432(event_team_id, flag_owner)\n    trace(\"PLAYER KILLED - TEAM SCORE\")\r\n    trace(\"team du joueur tué\", event_team_id)\r\n    trace(\"joueur tué possède le drapeau\", flag_owner)\r\n    \r\n    --triggerUpdateInfo()\nend\n\n-- [FIGHT] Wapin / Maman Wapin tué - Score Perso\n-- \nfunction event_2316_19433()\n    trace(\"MONSTER KILLED - OWN SCORE\")\nend\n\n-- [FIGHT] Wapin / Maman Wapin tué - Score Equipe\n-- \nfunction event_2316_19434(event_team_id)\n    trace(\"MONSTER KILLED - TEAM SCORE\")\r\n    trace(\"team du joueur qui a tué le monstre\", event_team_id)\r\n    \r\n    --triggerUpdateInfo()\nend\n\n-- [FIGHT] Dark Wapin tué - Score Perso\n-- \nfunction event_2316_19446()\n    trace(\"MONSTER KILLED - OWN SCORE\")\nend\n\n-- [FIGHT] Dark Wapin tué - Score Equipe\n-- \nfunction event_2316_19447(event_team_id)\n    trace(\"MONSTER KILLED - TEAM SCORE\")\r\n    trace(\"team du joueur qui a tué le monstre\", event_team_id)\r\n    \r\n    --triggerUpdateInfo()\n    UI.writeInChatPipe(13, \"battleground.02.darkwapin.killed\", event_team_id)\r\n    pushNotification(\"battleground.02.darkwapin.killed\", event_team_id)\nend\n\n-- [FIGHT] Joueur débute un combat PvP - Score Perso\n-- \nfunction event_2316_19576(blueTeamCount, redTeamCount, event_team_id)\n    trace(\"PLAYER START PVP FIGHT - OWN SCORE\")\r\n    trace(\"blueTeamCount\", blueTeamCount)\r\n    trace(\"redTeamCount\", redTeamCount)\r\n    trace(\"team du joueur concerné\", event_team_id)\nend\n\n-- [FIGHT][DEATH] Joueur mort en fin de combat - Retrait des Etats\n-- \nfunction event_2316_19633()\n    \nend\n\n-- [IE][TP] CDG vers HUB - Retrait des Etats\n-- \nfunction event_2316_19579()\n    \nend\n\n-- [EVENT] BG_START - Procédures de démarrage du BG\n-- \nfunction event_2316_19426()\n    trace(\"BATTLEGROUND_START\")\nend\n\n-- [EVENT] BG_ENDED - Procédures de fin du BG\n-- On écoute BG_ENDED pour être sûr d'avoir terminé les procédures du scénario 2320\nfunction event_2316_19427()\n    trace(\"BATTLEGROUND_ENDED\")\nend\n\n-- [UI] Score modifié - Mise à jour de l'UI\n-- \nfunction event_2316_19412(att_score, def_score, own_score, own_team_id, att_flower, def_flower, att_member, def_member)\n    trace(\"own_team_id\", own_team_id)\r\n    trace(\"own_score\", own_score)\r\n    trace(\"att_score\", att_score, \"def_score\", def_score)\r\n    trace(\"att_flower\", att_flower, \"def_flower\", def_flower)\r\n    trace(\"att_member\", att_member, \"def_member\", def_member)\r\n    \r\n    local att_flower = toLong(att_flower)\r\n    local def_flower = toLong(def_flower)\r\n    \r\n    local detailText = Context.getTranslation(\"battleground.02.battlegroundBarDetailText\", att_flower, def_flower)\r\n    UI.setTextWidget(\"battlegroundBarDialog\", \"battlegroundBarDetailTextId\", detailText)\nend\n\n-- ~[NOTIF] Respawn du Dark Wapin\n-- \nfunction event_2316_19471()\n    UI.writeInChatPipe(13, \"battleground.02.dark.wapin.respawn\", event_team_id)\r\n    pushNotification(\"battleground.02.dark.wapin.respawn\", event_team_id)\nend\n\n-- [NOTIF] Notifications récurrentes\n-- \nfunction event_2316_19487(att_score, def_score)\n    local att_score = toLong(att_score)\r\n    local def_score = toLong(def_score)\r\n    \r\n    local score_diff = math.abs(att_score - def_score)\r\n    local winning_team = \"att\"\r\n    if (def_score > att_score) then winning_team = \"def\" end\r\n    \r\n    if (score_diff >= 500) then\r\n    \tUI.writeInChatPipe(13, \"battleground.00.team.score.\" .. winning_team .. \".winning\", event_team_id)\r\n    \tpushNotification(\"battleground.00.team.score.\" .. winning_team .. \".winning\", event_team_id)\r\n    end\nend\n\n","functions":["triggerUpdateInfo","onNotificationClosed","pushNotification","pushNotificationPosition","updateNotification","event_2316_19271","event_2316_19743","event_2316_19407","event_2316_19414","event_2316_19701","event_2316_19704","event_2316_19706","event_2316_19705","event_2316_19431","event_2316_19432","event_2316_19433","event_2316_19434","event_2316_19446","event_2316_19447","event_2316_19576","event_2316_19633","event_2316_19579","event_2316_19426","event_2316_19427","event_2316_19412","event_2316_19471","event_2316_19487"],"quest_calls":[],"dialogue_calls":[]},"scenario/2317.lua":{"source":"\n\n-- ~[INIT] Initialisation des variables\n-- \nfunction event_2317_19298()\n    \nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_2317_19326()\n    \nend\n\n-- ~[EVENT][Rikiki][West] Un joueur se place sur la dalle - Incrémentation\n-- \nfunction event_2317_19296()\n    \nend\n\n-- ~[EVENT][Rikiki][West] Un joueur quitte la dalle - Décrémentation\n-- \nfunction event_2317_19297()\n    \nend\n\n-- [EVENT][Rikiki][West] Le coffre apparaît\n-- \nfunction event_2317_19309()\n    invoke(0,1,\"Particle.addParticleSystem\",800202, -47, 7, 0, 0)\nend\n\n-- [EVENT][Rikiki][West] Le coffre disparaît\n-- \nfunction event_2317_19310()\n    \nend\n\n-- ~[EVENT][Rikiki][East] Un joueur se place sur la dalle - Incrémentation\n-- \nfunction event_2317_19317()\n    \nend\n\n-- ~[EVENT][Rikiki][East] Un joueur quitte la dalle - Décrémentation\n-- \nfunction event_2317_19318()\n    \nend\n\n-- [EVENT][Rikiki][East] Le coffre apparaît\n-- \nfunction event_2317_19319()\n    invoke(0,1,\"Particle.addParticleSystem\",800202, -27, -11, 0, 0)\nend\n\n-- [EVENT][Rikiki][East] Le coffre disparaît\n-- \nfunction event_2317_19320()\n    \nend\n\n-- [EVENT][Rikiki] Ouverture du coffre - Obtention artefact\n-- \nfunction event_2317_19580()\n    local playerId = Context.getLeaderId()\r\n    Mobile.setMobileAnimation(playerId, \"AnimEmote-Victoire\")\nend\n\n-- [EVENT][Rikiki] Combat DarkWapin gagné - Obtention buff\n-- \nfunction event_2317_19385()\n    local playerId = Context.getLeaderId()\r\n    Mobile.setMobileAnimation(playerId, \"AnimEmote-Victoire\")\nend\n\n-- [EVENT][Spieds] Tambour utilisé - Lancement combat Wapin\n-- \nfunction event_2317_19322()\n    \nend\n\n-- [EVENT][Spieds] Combat Wapin gagné - Obtention artefact\n-- \nfunction event_2317_19323()\n    local playerId = Context.getLeaderId()\r\n    Mobile.setMobileAnimation(playerId, \"AnimEmote-Victoire\")\nend\n\n-- [EVENT][Papattes] Tambour utilisé - Lancement combat Mama Wapin\n-- \nfunction event_2317_19325()\n    \nend\n\n-- [EVENT][Papattes] Combat Mama Wapin gagné - Obtention artefact\n-- \nfunction event_2317_19324()\n    local playerId = Context.getLeaderId()\r\n    Mobile.setMobileAnimation(playerId, \"AnimEmote-Victoire\")\nend\n\n-- [EVENT] BG_ENDED - Procédures de fin du BG\n-- On écoute BG_ENDED pour être sûr d'avoir terminé les procédures du scénario 2320\nfunction event_2317_19425()\n    trace(\"BATTLEGROUND_ENDED\")\nend\n\n-- [FIGHT][DEATH] Joueur mort en fin de combat - Retrait des Etats\n-- \nfunction event_2317_19747()\n    \nend\n\n","functions":["event_2317_19298","event_2317_19326","event_2317_19296","event_2317_19297","event_2317_19309","event_2317_19310","event_2317_19317","event_2317_19318","event_2317_19319","event_2317_19320","event_2317_19580","event_2317_19385","event_2317_19322","event_2317_19323","event_2317_19325","event_2317_19324","event_2317_19425","event_2317_19747"],"quest_calls":[],"dialogue_calls":[]},"scenario/2318.lua":{"source":"\n\n-- Retire les point de citoyenneté\n-- \nfunction event_2318_19331()\n    \nend\n\n-- Le joueur devient Neutre\n-- \nfunction event_2318_19332()\n    UI.displaySplashText(\"splash.passeport.nok\")\nend\n\n","functions":["event_2318_19331","event_2318_19332"],"quest_calls":[],"dialogue_calls":[]},"scenario/2319.lua":{"source":"\n\n-- [WP] Général WP 1 - Etat Waypoint + Score Equipe\n-- \nfunction event_2319_19453(event_team_id)\n    trace(\"GENERAL AT WAYPOINT 1 - TEAM SCORE\")\r\n    trace(\"team du général\", event_team_id)\r\n    \r\n    UI.writeLocalisedInChat(\"battleground.01.general.progress\", event_team_id)\r\n    \r\n    --triggerUpdateFightInfo()\nend\n\n-- [WP] Général WP 2 - Etat Waypoint + Score Equipe\n-- \nfunction event_2319_19454(event_team_id)\n    trace(\"GENERAL AT WAYPOINT 2 - TEAM SCORE\")\r\n    trace(\"team du général\", event_team_id)\r\n    \r\n    UI.writeLocalisedInChat(\"battleground.01.general.progress\", event_team_id)\r\n    \r\n    --triggerUpdateFightInfo()\nend\n\n-- [WP] Général WP 3 - Etat Waypoint + Score Equipe\n-- \nfunction event_2319_19455(event_team_id)\n    trace(\"GENERAL AT WAYPOINT 3 - TEAM SCORE\")\r\n    trace(\"team du général\", event_team_id)\r\n    \r\n    UI.writeLocalisedInChat(\"battleground.01.general.progress\", event_team_id)\r\n    \r\n    --triggerUpdateFightInfo()\nend\n\n-- [WP] Général WP 4 - Etat Waypoint + Score Equipe\n-- \nfunction event_2319_19456(event_team_id)\n    trace(\"GENERAL AT WAYPOINT 4 - TEAM SCORE\")\r\n    trace(\"team du général\", event_team_id)\r\n    \r\n    UI.writeLocalisedInChat(\"battleground.01.general.progress\", event_team_id)\r\n    \r\n    --triggerUpdateFightInfo()\nend\n\n-- [WP] Général WP 5 -  Settings Général + Etat Waypoint + Score Equipe\n-- \nfunction event_2319_19457(event_team_id)\n    trace(\"GENERAL AT WAYPOINT 5 (LAST) - TEAM SCORE\")\r\n    trace(\"team du général\", event_team_id)\r\n    \r\n    UI.writeLocalisedInChat(\"battleground.01.general.progress.end\", event_team_id)\r\n    \r\n    --triggerUpdateFightInfo()\nend\n\n","functions":["event_2319_19453","event_2319_19454","event_2319_19455","event_2319_19456","event_2319_19457"],"quest_calls":[],"dialogue_calls":[]},"scenario/2320.lua":{"source":"function triggerUpdateQueue()\r\n\tServer.triggerEvent(5555)\r\nend\r\n\r\nfunction getTeamType(teamId)\r\n  if (toString(teamId) == \"1\") then\r\n \treturn \"DEFENSE\"\r\n elseif (toString(teamId) == \"0\") then\r\n \treturn \"ATTAQUE\"\r\n else\r\n \treturn \"UNKNOW\"\r\n end\r\nend\n\n-- [INIT] Variables & Constantes - Scenario\n-- \nfunction event_2320_19486()\n    \nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_2320_19478(protector_id)\n    local protector_id = toLong(protector_id)\r\n    \r\n    UI.pushStaticProtector(protector_id)\nend\n\n-- [EVENT] Un joueur quitte l'instance\n-- \nfunction event_2320_19477()\n    \nend\n\n-- [IE][TP] Accès HUB vers CDB - Attaque (BACKUP)\n-- \nfunction event_2320_19473(member_limit, member_count)\n    trace(\"PLAYER TRYING TO TP INTO BG - TEAM 0 ATTAQUE\")\n    trace(\"member_count\", member_count)\r\n    trace(\"member_limit\", member_limit)\r\n    \r\n    if (toLong(member_count) >= toLong(member_limit)) then\r\n       \tUI.writeInChatPipe(3, \"battleground.00.entrance.denied\", member_limit)\n       \ttriggerUpdateQueue()\r\n    end\nend\n\n-- [IE][TP] Accès HUB vers CDB\n-- \nfunction event_2320_19474(member_limit, member_count, is_queued, player_real_count, player_team_id)\n    trace(\"PLAYER TRYING TO TP INTO BG - TEAM \" .. toString(player_team_id))\n    trace(\"player_team_id\", player_team_id)\n    trace(\"member_count\", member_count)\n    trace(\"player_real_count\", player_real_count)\r\n    trace(\"member_limit\", member_limit)\n    trace(\"is_queued\", is_queued)\n    \r\n    if (toLong(is_queued) > 0) then\r\n    \tUI.writeInChatPipe(3, \"battleground.00.entrance.denied\", member_limit)\n    \ttriggerUpdateQueue()\r\n    end\nend\n\n-- [IE][TP] Accès CDB vers HUB - Attaque (BACKUP)\n-- \nfunction event_2320_19475()\n    trace(\"PLAYER TRYING TO TP INTO HUB - TEAM 0\")\nend\n\n-- [IE][TP] Accès CDB vers HUB\n-- \nfunction event_2320_19476(player_team_id)\n    trace(\"PLAYER TRYING TO TP INTO HUB - TEAM \" .. toString(player_team_id))\nend\n\n-- #[FIGHT][DEATH] Joueur mort en fin de combat - Etat Malus\n-- \nfunction event_2320_19479()\n    trace(\"PLAYER DEFEAT AT FIGHT END - MALUS STATE\")\nend\n\n-- #[FIGHT][DEATH] Joueur mort en fin de combat - TP dans le HUB\n-- \nfunction event_2320_19480()\n    trace(\"PLAYER DEFEAT AT FIGHT END - TELEPORT TO HUB\")\nend\n\n-- [EVENT] BG_END_DURATION - Termine le BG\n-- Cette action se joue même s'il n'y a plus de joueur dans le CDB\nfunction event_2320_19482()\n    trace(\"BATTLEGROUND_TIME_LIMIT\")\nend\n\n-- [EVENT] PLAYER_BG_ENDED - Procédures de fin sur les joueurs\n-- Ces actions ne se jouent que sur les joueurs encore présents dans l'instance quand le CDB se termine\r\n-- L'event PLAYER_BG_ENDED est dispatch sur tous les joueurs juste avant BG_ENDED\nfunction event_2320_19485(close_delay_ms)\n    trace(\"PLAYER_BATTLEGROUND_ENDED\")\r\n    \r\n    local delay_ms = toLong(close_delay_ms)\r\n    local delay_min = math.ceil(delay_ms / 1000 / 60)\r\n    \r\n    UI.writeInChatPipe(3, \"battleground.00.remaining.time.before.close\", delay_min)\r\n    --pushNotification(\"battleground.00.remaining.time.before.close\", delay_min)\nend\n\n-- [EVENT] BG_CLOSE - Ferme le BG\n-- \nfunction event_2320_19484()\n    trace(\"BATTLEGROUND_CLOSE\")\nend\n\n-- [NOTIF] Mise à jour de la position dans la file d'attente\n-- \nfunction event_2320_19584(queue_position)\n    trace(\"QUEUE POSITION UPDATED\")\r\n    \r\n    if (toLong(queue_position) > 0) then\r\n    \tUI.writeInChatPipe(3, \"battleground.00.queue.position\", queue_position)\r\n    end\nend\n\n-- [EVENT] Un joueur QUEUED quitte l'instance - Retrait de la file d'attente\n-- \nfunction event_2320_19582()\n    trace(\"PLAYER_EXIT_INSTANCE - REMOVE HIM FROM QUEUE\")\r\n    \r\n    triggerUpdateQueue()\nend\n\n-- ~[EVENT] Une place se libère - TP dans le CDB le joueur en tête de la file d'attente\n-- \nfunction event_2320_19583(player_to_teleport)\n    trace(\"TELEPORT AND REMOVE PLAYER FROM QUEUE\", player_to_teleport)\r\n    \r\n    triggerUpdateQueue()\nend\n\n","functions":["triggerUpdateQueue","getTeamType","event_2320_19486","event_2320_19478","event_2320_19477","event_2320_19473","event_2320_19474","event_2320_19475","event_2320_19476","event_2320_19479","event_2320_19480","event_2320_19482","event_2320_19485","event_2320_19484","event_2320_19584","event_2320_19582","event_2320_19583"],"quest_calls":[],"dialogue_calls":[]},"scenario/2321.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\nfunction cameraShakeOne()\r\n \tlocal shakeEffectIdO = Effect.createCameraShakeEffect(0, 500, 0, 3)\r\n \tinvoke(500, 1, \"Effect.stopEffect\", shakeEffectIdO)\r\nend\n\n-- [INIT] Variables & Constantes\n-- \nfunction event_2321_19517()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2321_19518(juge, tymothee, tetras)\n    local jugeId = toLong(juge)\r\n    local tetrasId = toLong(tetras)\r\n    local tymotheeId = toLong(tymothee)\r\n    \r\n    Mobile.setMobileAnimationSuffix(jugeId, \"-Juge\")\r\n    Mobile.setMobileAnimation(tetrasId, \"AnimEmote-CroiserBras\")\r\n    Mobile.setMobileAnimation(tymotheeId, \"AnimEmote-CroiserBras\")\r\n    \r\n    startCinematicContext(1.5, jugeId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\")\r\n    \r\n    ------------------------------\r\n    \r\n    invoke_custom(500, 1, \"Mobile.setMobileAnimation\", jugeId, \"AnimComp-Baton\")\r\n    -- Silence dans la salle !\r\n    invoke_custom(1500, 1, \"bubble\", jugeId, \"quest.ruel.tribunal.dialog.juge.1\")\r\n    -- Nous allons écouter les différents témoignages des accusés.\r\n    invoke_custom(6500, 1, \"bubble\", jugeId, \"quest.ruel.tribunal.dialog.juge.2\")\r\n    invoke_custom(11000, 1, \"clearBubbles\", jugeId)\r\n    -- La prosécution peut commencer l'interrogatoire pour déterminer qui a volé tous les kamas !\r\n    invoke_custom(12000, 1, \"bubble\", jugeId, \"quest.ruel.tribunal.dialog.juge.3\")\r\n    \r\n    ------------------------------\r\n    \r\n    invoke_custom(18000, 1, \"skipCinematic\")\nend\n\n-- [EVENT] Témoignage Pandawa\n-- \nfunction event_2321_19559(pandawa, ouginak, sadida)\n    local playerId = Context.getLeaderId()\r\n    local pandawaId = toLong(pandawa)\r\n    local ouginakId = toLong(ouginak)\r\n    local sadidaId = toLong(sadida)\r\n    \r\n    startCinematicContext(1.5, pandawaId)\r\n    \r\n    ------------------------------\r\n    \r\n    --bouger le player au bon endroit\r\n    invoke_custom(1000, 1, \"Mobile.moveMobile\", playerId, 5,-9,6, \"Mobile.setMobileDirection\", playerId, 5)\r\n    \r\n    --bouger le panda au stand\r\n    invoke_custom(1000, 1, \"Mobile.moveMobile\", pandawaId, 0,-8,6, \"Mobile.setMobileDirection\", pandawaId, 1)\r\n    \r\n    invoke_custom(7000, 1, \"bubble\", pandawaId, \"quest.ruel.tribunal.pandawa.dialog.1\")\r\n    invoke_custom(8500, 1, \"Mobile.setMobileAnimation\", pandawaId, \"AnimEmoteMarket-LeverSonVerre\")\r\n    \r\n    invoke_custom(12000, 1, \"bubble\", pandawaId, \"quest.ruel.tribunal.pandawa.dialog.2\")\r\n    invoke_custom(12000, 1, \"Mobile.setMobileAnimation\", pandawaId, \"AnimEmote-Non\")\r\n    \r\n    invoke_custom(15500, 1, \"bubble\", pandawaId, \"quest.ruel.tribunal.pandawa.dialog.3\")\r\n    invoke_custom(15500, 1, \"Mobile.setMobileAnimation\", pandawaId, \"AnimEmoteMarket-HausseEpaules\")\r\n    \r\n    --bouger le panda à sa place\r\n    invoke_custom(17500, 1, \"Mobile.moveMobile\", pandawaId, -5,-8,6, \"Mobile.setMobileDirection\", pandawaId, 1)\r\n    \r\n    ------------------------------\r\n    \r\n    invoke_custom(18000, 1, \"skipCinematic\", 42)\nend\n\n-- [EVENT] Témoignage Ouginak\n-- \nfunction event_2321_19564(ouginak, pandawa, sadida)\n    local playerId = Context.getLeaderId()\r\n    local ouginakId = toLong(ouginak)\r\n    local pandawaId = toLong(pandawa)\r\n    local sadidaId = toLong(sadida)\r\n    \r\n    startCinematicContext(1.5, ouginakId)\r\n    \r\n    ------------------------------\r\n    \r\n    --bouger le player au bon endroit\r\n    invoke_custom(1000, 1, \"Mobile.moveMobile\", playerId, 5,-9,6, \"Mobile.setMobileDirection\", playerId, 5)\r\n    --bouger l'ougi au stand\r\n    invoke_custom(1000, 1, \"Mobile.moveMobile\", ouginakId, 0,-8,6,\"Mobile.setMobileDirection\", ouginakId, 1)\r\n    \r\n    \r\n    invoke_custom(7000, 1, \"bubble\", ouginakId, \"quest.ruel.tribunal.ouginak.dialog.1\")\r\n    \r\n    invoke_custom(11000, 1, \"bubble\", ouginakId, \"quest.ruel.tribunal.ouginak.dialog.2\")\r\n    invoke_custom(11200, 1, \"Mobile.setMobileAnimation\", ouginakId, \"AnimEmote-Colere\")\r\n    \r\n    invoke_custom(15000, 1, \"bubble\", ouginakId, \"quest.ruel.tribunal.ouginak.dialog.3\")\r\n    \r\n    --bouger l'ougi à sa place\r\n    invoke_custom(18000, 1, \"Mobile.moveMobile\", ouginakId, -5,-10,6,\"Mobile.setMobileDirection\", ouginakId, 1)\r\n    \r\n    ------------------------------\r\n    \r\n    invoke_custom(18500, 1, \"skipCinematic\", 42)\nend\n\n-- [EVENT] Témoignage Sadida\n-- \nfunction event_2321_19568(sadida, ouginak, pandawa)\n    local playerId = Context.getLeaderId()\r\n    local pandawaId = toLong(pandawa)\r\n    local ouginakId = toLong(ouginak)\r\n    local sadidaId = toLong(sadida)\r\n    \r\n    startCinematicContext(1.5, sadidaId)\r\n    \r\n    ------------------------------\r\n    \r\n    --bouger le player au bon endroit\r\n    invoke_custom(1000, 1, \"Mobile.moveMobile\", playerId, 5,-9,6, \"Mobile.setMobileDirection\", playerId, 5)\r\n    --bouger la sadi au stand\r\n    invoke_custom(1000, 1, \"Mobile.moveMobile\", sadidaId, 0,-8,6,\"Mobile.setMobileDirection\", sadidaId, 1)\r\n    \r\n    invoke_custom(7000, 1, \"bubble\", sadidaId, \"quest.ruel.tribunal.sadida.dialog.1\")\r\n    \r\n    invoke_custom(10000, 1, \"bubble\", sadidaId, \"quest.ruel.tribunal.sadida.dialog.2\")\r\n    \r\n    invoke_custom(14000, 1, \"bubble\", sadidaId, \"quest.ruel.tribunal.sadida.dialog.3\")\r\n    \r\n    invoke_custom(18000, 1, \"bubble\", sadidaId, \"quest.ruel.tribunal.sadida.dialog.4\")\r\n    invoke_custom(18000, 1, \"Mobile.setMobileAnimation\", sadidaId, \"AnimEmoteMarket-HausseEpaules\")\r\n    \r\n    --bouger la sadi au stand\r\n    invoke_custom(20000, 1, \"Mobile.moveMobile\", sadidaId, -5,-9,6,\"Mobile.setMobileDirection\", sadidaId, 1)\r\n    \r\n    ------------------------------\r\n    \r\n    invoke_custom(20500, 1, \"skipCinematic\", 42)\nend\n\n-- [EVENT] Le joueur accuse le Pandawa\n-- \nfunction event_2321_19521(pandawa, ouginak, sadida, juge)\n    local playerId = Context.getLeaderId()\r\n    local pandawaId = toLong(pandawa)\r\n    local ouginakId = toLong(ouginak)\r\n    local sadidaId = toLong(sadida)\r\n    local jugeId = toLong(juge)\r\n    \r\n    startCinematicContext(1.5, playerId)\r\n    \r\n    ------------------------------\r\n    \r\n    --bouger le player au bon endroit\r\n    invoke_custom(1000, 1, \"Mobile.moveMobile\", playerId, 5,-9,6, \"Mobile.setMobileDirection\", playerId, 5)\r\n    \r\n    --bouger le panda au stand\r\n    invoke_custom(1000, 1, \"Mobile.moveMobile\", pandawaId, 0,-8,6, \"Mobile.setMobileDirection\", pandawaId, 1)\r\n    \r\n    \r\n    invoke_custom(7000, 1, \"bubble\", playerId, \"quest.ruel.tribunal.wrongaccused\")\r\n    invoke_custom(7000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Pointer\")\r\n    \r\n    invoke_custom(9000, 1, \"Camera.attachCameraToMobile\", pandawaId)\r\n    invoke_custom(9500, 1, \"bubble\", pandawaId, \"quest.ruel.tribunal.dialog.accused\")\r\n    invoke_custom(9800, 1, \"Mobile.setMobileAnimation\", pandawaId, \"AnimEmoteMarket-PleursOgrest\")\r\n    \r\n    invoke_custom(12000, 1, \"Camera.attachCameraToMobile\", jugeId)\r\n    invoke_custom(13000, 1, \"Mobile.setMobileAnimation\", jugeId, \"AnimComp-Baton\")\r\n    invoke_custom(14000, 1, \"bubble\", jugeId, \"quest.ruel.tribunal.dialog.juge.wrong\")\r\n    \r\n    --bouger le panda à sa place\r\n    invoke_custom(17500, 1, \"Mobile.moveMobile\", pandawaId, -5,-8,6, \"Mobile.setMobileDirection\", pandawaId, 1)\r\n    \r\n    ------------------------------\r\n    \r\n    invoke_custom(18000, 1, \"skipCinematic\", 42)\nend\n\n-- [EVENT] Le joueur accuse l'Ouginak\n-- \nfunction event_2321_19558(ouginak, pandawa, sadida, juge)\n    local playerId = Context.getLeaderId()\r\n    local pandawaId = toLon