custom(54000, 1, \"Camera.attachCameraToMobile\", sadidaId)\r\n    invoke_custom(56000, 1, \"Mobile.moveMobile\", sadidaId, 0, -7, 4)\r\n    \r\n    invoke_custom(57000, 1, \"Mobile.moveMobile\", mercenaireAId, -1, -4, 0, \"Mobile.moveMobile\", mercenaireAId, -1, -1, 0)\r\n    invoke_custom(57000, 1, \"Mobile.moveMobile\", mercenaireBId, 1, -4, 0, \"Mobile.moveMobile\", mercenaireBId, 1, -1, 0)\r\n    invoke_custom(57000, 1, \"Mobile.moveMobile\", sadidaId, 0, -4, 0, \"Mobile.moveMobile\", sadidaId, 0, -1, 0)\r\n    \r\n    invoke_custom(60000, 1, \"Camera.attachCameraToMobile\", playerId, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Victoire\")\r\n    invoke_custom(62000, 1, \"Mobile.setMobileVisible\", sadidaId, false)\r\n    invoke_custom(62000, 1, \"Mobile.setMobileVisible\", mercenaireAId, false)\r\n    invoke_custom(62000, 1, \"Mobile.setMobileVisible\", mercenaireBId, false)\r\n    ------------------------------\r\n    \r\n    invoke_custom(64000, 1, \"skipCinematic\", 42)\nend\n\n-- [EVENT] TP du joueur à sa position exacte\n-- \nfunction event_2321_19573()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","cameraShakeOne","event_2321_19517","event_2321_19518","event_2321_19559","event_2321_19564","event_2321_19568","event_2321_19521","event_2321_19558","event_2321_19563","event_2321_19573"],"quest_calls":[],"dialogue_calls":[]},"scenario/2323.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\n\n-- [INIT] Variables & Constantes\n-- \nfunction event_2323_19537()\n    \nend\n\n-- [EVENT] Démarrage du Scénario - Lancement Ciné 1\n-- \nfunction event_2323_19538()\n    local playerId = Context.getLeaderId()\r\n    local ruelId = createActor(192404573, -80, 4, 0, 4, 7, 7)\r\n    local phorreurId = createActor(102200145, -72, 6, 0, 4, 7, 7)\r\n    \r\n    startCinematicContext(1.9, playerId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 19538)\r\n    \r\n    ------------------------------\r\n    \r\n    Mobile.setMobileVisible(phorreurId, false)\r\n    \r\n    -- Hmm, on dirait des kamas tombés par terre...\r\n    invoke_custom(1000, 1, \"bubble\", playerId, \"quest.ruel.phorreur.cine.1\")\r\n    \r\n    invoke_custom(2500, 1, \"Mobile.moveMobile\", ruelId, -72, 4, 0, \"Mobile.setMobileDirection\", ruelId, 3)\r\n    \r\n    invoke_custom(4500, 1, \"Camera.attachCameraToMobile\", ruelId)\r\n    \r\n    -- Oooooh des kamaaas !\r\n    invoke_custom(6000, 1, \"bubble\", ruelId, \"quest.ruel.phorreur.cine.2\")\r\n    invoke_custom(9000, 1, \"clearBubbles\", ruelId)\r\n    -- ... Au vu de leur positionnement, je dirais que le voleur est parti au nord-est !\r\n    invoke_custom(9500, 1, \"bubble\", ruelId, \"quest.ruel.phorreur.cine.3\")\r\n    \r\n    invoke_custom(13000, 1, \"Mobile.setMobileVisible\", phorreurId, true)\r\n    invoke_custom(13001, 1, \"Mobile.setMobileAnimation\", phorreurId, \"AnimSort-Surgissement\")\r\n    \r\n    invoke_custom(15000, 1, \"Mobile.setMobileAnimation\", phorreurId, \"AnimComp-Renifle\")\r\n    invoke_custom(17500, 1, \"Mobile.moveMobile\", phorreurId, -72, 5, 0)\r\n    \r\n    -- Mais qu'est-ce que... Naaaaoooon, laisse moiiiii ! \r\n    invoke_custom(18500, 1, \"bubble\", ruelId, \"quest.ruel.phorreur.cine.9\")\r\n    invoke_custom(19000, 1, \"Mobile.setMobileAnimation\", phorreurId, \"AnimSort-Charge\")\r\n    invoke_custom(19550, 1, \"Mobile.setMobileAnimation\", ruelId, \"AnimApparition\")\r\n    \r\n    ------------------------------\r\n    \r\n    invoke(20300, 1, \"skipCinematic\", 19538)\nend\n\n-- [EVENT] Fin du combat - Lancement Ciné 1.5 - ACH 3972 OBJ 8452\n-- \nfunction event_2323_19708()\n    local playerId = Context.getLeaderId()\r\n    local ruelId = createActor(192404573, -72, 4, 0, 4, 3, 7)\r\n    local phorreurId = createActor(102200145, -72, 6, 0, 4, 7, 7)\r\n    \r\n    startCinematicContext(1.9, playerId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 19708)\r\n    \r\n    ------------------------------\r\n    \r\n    invoke_custom(10, 1, \"Mobile.setMobileAnimation\", ruelId, \"AnimApparition\")\r\n    invoke_custom(100, 1, \"Mobile.setMobileLookAt\", playerId, -72, 4)\r\n    invoke_custom(2000, 1, \"Mobile.setMobileAnimation\", phorreurId, \"AnimSort-Enfouissement\")\r\n    \r\n    invoke_custom(4500, 1, \"Camera.attachCameraToMobile\", ruelId)\r\n    \r\n    -- ...Enfin débarassés de cette bestiole.\r\n    invoke_custom(5000, 1, \"bubble\", ruelId, \"quest.ruel.phorreur.cine.10\")\r\n    invoke_custom(9000, 1, \"clearBubbles\", ruelId)\r\n    \r\n    -- Reprenons notre traque ! Je disais... le nord-est.\r\n    invoke_custom(10000, 1, \"Mobile.setMobileAnimation\", ruelId, \"AnimStatique\")\r\n    invoke_custom(10000, 1, \"bubble\", ruelId, \"quest.ruel.phorreur.cine.11\")\r\n    \r\n    -- Ben quoi ?\r\n    invoke_custom(14000, 1, \"bubble\", ruelId, \"quest.ruel.phorreur.cine.12\")\r\n    \r\n    invoke_custom(16500, 1, \"clearBubbles\", ruelId)\r\n    -- J'aime pas les phorreurs, qu'est-ce que ça peut te faire ?\r\n    invoke_custom(17000, 1, \"bubble\", ruelId, \"quest.ruel.phorreur.cine.13\")\r\n    \r\n    -- Allez, on y va ! On va pas y passer la journée...\r\n    invoke_custom(20500, 1, \"clearBubbles\", ruelId)\r\n    invoke_custom(21000, 1, \"bubble\", ruelId, \"quest.ruel.phorreur.cine.14\")\r\n    \r\n    ------------------------------\r\n    \r\n    invoke(25000, 1, \"skipCinematic\", 19708)\nend\n\n-- [EVENT] Démarrage du Scénario - Lancement Ciné 2 - ACH 3972 OBJ 8453\n-- \nfunction event_2323_19629()\n    local playerId = Context.getLeaderId()\r\n    local ruelId = createActor(192404573, -82, -76, 0, 4, 7, 7)\r\n    \r\n    startCinematicContext(1.9, playerId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 19708)\r\n    \r\n    ------------------------------\r\n    -- Hmm, on dirait des kamas tombés par terre...\r\n    invoke_custom(1000, 1, \"bubble\", playerId, \"quest.ruel.phorreur.cine.1\")\r\n    invoke_custom(2500, 1, \"Mobile.moveMobile\", ruelId, -74, -76, 0, \"Mobile.setMobileDirection\", ruelId, 3)\r\n    \r\n    invoke_custom(4500, 1, \"Camera.attachCameraToMobile\", ruelId)\r\n    -- Oooooh des kamaaas !\r\n    invoke_custom(6500, 1, \"bubble\", ruelId, \"quest.ruel.phorreur.cine.2\")\r\n    -- ... Le filou a une bonne longueur d'avance sur nous. Dépêchons-nous !\r\n    invoke_custom(10000, 1, \"bubble\", ruelId, \"quest.ruel.phorreur.cine.4\")\r\n    \r\n    ------------------------------\r\n    \r\n    invoke(14300, 1, \"skipCinematic\", 19708)\nend\n\n-- [EVENT] Démarrage du Scénario - Lancement Ciné 3 - ACH 3972 OBJ 8454\n-- \nfunction event_2323_19630()\n    local playerId = Context.getLeaderId()\r\n    local ruelId = createActor(192404573, -49, -100, 0, 4, 7, 7)\r\n    local phorreurId = createActor(102200145, -43, -97, 0, 4, 7, 7)\r\n    \r\n    startCinematicContext(1.9, playerId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 19708)\r\n    \r\n    ------------------------------\r\n    Mobile.setMobileVisible(phorreurId, false)\r\n    \r\n    -- Là, des kamas ! Il ne va plus en rester beaucoup si cette chasse se poursuit plus longtemps...\r\n    invoke_custom(1000, 1, \"bubble\", playerId, \"quest.ruel.phorreur.cine.8\")\r\n    invoke_custom(3500, 1, \"Mobile.moveMobile\", ruelId, -43, -99, 0, \"Mobile.setMobileDirection\", ruelId, 3)\r\n    \r\n    invoke_custom(4500, 1, \"Camera.attachCameraToMobile\", ruelId)\r\n    invoke_custom(6000, 1, \"clearBubbles\", playerId)\r\n    \r\n    --Oooooh des kamaaas !\r\n    invoke_custom(6500, 1, \"bubble\", ruelId, \"quest.ruel.phorreur.cine.2\")\r\n    --Les mines ! J'aurais dû m'en douter... Ces kamas sentent le charbon à plein nez !\r\n    invoke_custom(10000, 1, \"bubble\", ruelId, \"quest.ruel.phorreur.cine.5\")\r\n    \r\n    invoke_custom(13000, 1, \"Mobile.setMobileVisible\", phorreurId, true)\r\n    invoke_custom(13001, 1, \"Mobile.setMobileAnimation\", phorreurId, \"AnimSort-Surgissement\")\r\n    invoke_custom(16000, 1, \"clearBubbles\", ruelId)\r\n    invoke_custom(15000, 1, \"Mobile.setMobileAnimation\", phorreurId, \"AnimComp-Renifle\")\r\n    invoke_custom(17500, 1, \"Mobile.moveMobile\", phorreurId, -43, -98, 0)\r\n    \r\n    --Encore ?! Mais laisse moi tranquille, saleté de phorreur !\r\n    invoke_custom(17500, 1, \"bubble\", ruelId, \"quest.ruel.phorreur.cine.7\")\r\n    invoke_custom(23000, 1, \"Mobile.setMobileAnimation\", phorreurId, \"AnimSort-Charge\")\r\n    invoke_custom(23550, 1, \"Mobile.setMobileAnimation\", ruelId, \"AnimApparition\")\r\n    \r\n    ------------------------------\r\n    \r\n    invoke(24300, 1, \"skipCinematic\", 19708)\nend\n\n-- [EVENT] Démarrage du Scénario - Lancement Ciné 4 - ACH 3972 OBJ 8455\n-- \nfunction event_2323_19631()\n    local playerId = Context.getLeaderId()\r\n    local ruelId = createActor(192404573, -36, -40, 30, 4, 7, 7)\r\n    \r\n    startCinematicContext(1.9, playerId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 19708)\r\n    \r\n    ------------------------------\r\n    -- Là, des kamas ! Il ne va plus en rester beaucoup si cette chasse se poursuit plus longtemps...\r\n    invoke_custom(1000, 1, \"bubble\", playerId, \"quest.ruel.phorreur.cine.8\")\r\n    invoke_custom(3500, 1, \"Mobile.moveMobile\", ruelId, -33, -35, 30, \"Mobile.setMobileDirection\", ruelId, 3)\r\n    \r\n    invoke_custom(4500, 1, \"Camera.attachCameraToMobile\", ruelId)\r\n    invoke_custom(6000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- Oooooh des kamaaas !\r\n    invoke_custom(6500, 1, \"bubble\", ruelId, \"quest.ruel.phorreur.cine.2\")\r\n    -- Bon sang, je sais où il va ! Il y a une planque plus loin dans les tunnels, suis-moi !!!\r\n    invoke_custom(11000, 1, \"bubble\", ruelId, \"quest.ruel.phorreur.cine.6\")\r\n    \r\n    ------------------------------\r\n    \r\n    invoke(15300, 1, \"skipCinematic\", 19708)\nend\n\n-- [EVENT] Fin de Cinématique - Fin du scénario\n-- \nfunction event_2323_19707()\n    \nend\n\n-- [EVENT] Fin de Cinématique - Lancement du Combat\n-- \nfunction event_2323_19539()\n    \nend\n\n-- [EVENT] Début du combat - Invocation de Ruel\n-- \nfunction event_2323_19543()\n    \nend\n\n-- [EVENT] Fin du combat - Despawn des NPC\n-- \nfunction event_2323_19541()\n    \nend\n\n-- [EVENT] Sortie d'Instance - Fin du scénario\n-- \nfunction event_2323_19542()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_2323_19537","event_2323_19538","event_2323_19708","event_2323_19629","event_2323_19630","event_2323_19631","event_2323_19707","event_2323_19539","event_2323_19543","event_2323_19541","event_2323_19542"],"quest_calls":[],"dialogue_calls":[]},"scenario/2327.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\n\n-- [INIT] Variables & Constantes\n-- \nfunction event_2327_19569()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2327_19570()\n    \nend\n\n-- [EVENT] Cinématique 3 suspects\n-- \nfunction event_2327_19571(pandawa, ouginak, sadida)\n    local playerId = Context.getLeaderId()\r\n    local pandawaId = toLong(pandawa)\r\n    local ouginakId = toLong(ouginak)\r\n    local sadidaId = toLong(sadida)\r\n    local ruelId = createActor(192404573, -1, -3, 0, 4, 7, 7)\r\n    \r\n    startCinematicContext(1.5, ouginakId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\")\r\n    \r\n    ------------------------------\r\n    Mobile.setMobileVisible(ruelId, false)\r\n    \r\n    invoke_custom(0, 1, \"Camera.setCamera\", 1.7, 2, -14, 0)\r\n    \r\n    invoke_custom(2000, 1, \"Mobile.setMobileDirection\", pandawaId, 3)\r\n    invoke_custom(2100, 1, \"bubble\", pandawaId, \"!!!\")\r\n    \r\n    invoke_custom(2000, 1, \"Mobile.setMobileDirection\", ouginakId, 3)\r\n    invoke_custom(2100, 1, \"bubble\", ouginakId, \"!!!\")\r\n    \r\n    invoke_custom(2000, 1, \"Mobile.setMobileDirection\", sadidaId, 3)\r\n    invoke_custom(2100, 1, \"bubble\", sadidaId, \"!!!\")\r\n    \r\n    invoke_custom(3000, 1, \"Mobile.setMobileVisible\", ruelId, true)\r\n    invoke_custom(3000, 1, \"Mobile.moveMobile\", ruelId, -1, -7, 0, \"Mobile.setMobileDirection\", ruelId, 1)\r\n    \r\n    invoke_custom(3500, 1, \"Camera.attachCameraToMobile\", playerId)\r\n    invoke_custom(4000, 1, \"bubble\", playerId, \"quest.ruel.planque.player.cine.1\")\r\n    invoke_custom(7000, 1, \"bubble\", ruelId, \"quest.ruel.planque.player.cine.2\")\r\n    invoke_custom(10000, 1, \"bubble\", ruelId, \"quest.ruel.planque.player.cine.3\")\r\n    invoke_custom(13000, 1, \"Mobile.moveMobile\", ruelId, -1, 0, 0)\r\n    invoke_custom(14900, 1, \"Mobile.setMobileVisible\", ruelId, false)\r\n    \r\n    ------------------------------\r\n    \r\n    invoke_custom(14901, 1, \"skipCinematic\")\nend\n\n-- [EVENT] TP au Tribunal\n-- \nfunction event_2327_19572()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_2327_19569","event_2327_19570","event_2327_19571","event_2327_19572"],"quest_calls":[],"dialogue_calls":[]},"scenario/2328.lua":{"source":"\n\n-- Enregistrement des Evènements : Fin\n-- \nfunction event_2328_19635()\n    \nend\n\n-- Enregistrement des Evènements Cyclique : Spawn de monstres\n-- Toutes les X min, on spawn les groupes de monstres\nfunction event_2328_19636()\n    \nend\n\n","functions":["event_2328_19635","event_2328_19636"],"quest_calls":[],"dialogue_calls":[]},"scenario/2330.lua":{"source":"\n\n-- [INIT] Spawn Noxines - 131 - Amakna\n-- \nfunction event_2330_19654()\n    \nend\n\n-- [INIT] Spawn Noxines - 159 - Bonta\n-- \nfunction event_2330_19655()\n    \nend\n\n-- [INIT] Spawn Noxines - 134 - Wabbit (surface)\n-- \nfunction event_2330_19656()\n    \nend\n\n-- [INIT] Spawn Noxines - 208 - Brâkmar\n-- \nfunction event_2330_19657()\n    \nend\n\n-- [INIT] Spawn Noxines - 235 - Sufokia\n-- \nfunction event_2330_19658()\n    \nend\n\n-- [INIT] Spawn Noxines - 321 - Royaume Sadida\n-- \nfunction event_2330_19659()\n    \nend\n\n-- [INIT] Spawn Noxines - 323 - Île aux Moines\n-- \nfunction event_2330_19660()\n    \nend\n\n-- [INIT] Spawn Noxines - 327 - Katrepat\n-- \nfunction event_2330_19661()\n    \nend\n\n-- [INIT] Spawn Noxines - 444 - Chuchoteurs\n-- \nfunction event_2330_19662()\n    \nend\n\n-- [INIT] Spawn Noxines - 455 - Poup Island\n-- \nfunction event_2330_19663()\n    \nend\n\n-- [INIT] Spawn Noxines - 458 - Bilbyza\n-- \nfunction event_2330_19664()\n    \nend\n\n-- [INIT] Spawn Noxines - 504 - Frigost (île sberg)\n-- \nfunction event_2330_19665()\n    \nend\n\n-- [INIT] Spawn Noxines - 507 - Frigost (village enseveli)\n-- \nfunction event_2330_19666()\n    \nend\n\n-- [INIT] Spawn Noxines - 508 - Frigost (château harebourg)\n-- \nfunction event_2330_19667()\n    \nend\n\n-- [INIT] Spawn Noxines - 527 - Astrub\n-- \nfunction event_2330_19639()\n    \nend\n\n-- [INIT] Spawn Noxines - 546 - Astrub (égouts)\n-- \nfunction event_2330_19681()\n    \nend\n\n-- [INIT] Spawn Noxines - 615 - Wabbit (sous-sol)\n-- \nfunction event_2330_19668()\n    \nend\n\n-- [INIT] Spawn Noxines - 711 - Domaine Sauvage\n-- \nfunction event_2330_19669()\n    \nend\n\n-- [INIT] Spawn Noxines - 792 - Saharach (désert)\n-- \nfunction event_2330_19670()\n    \nend\n\n-- [INIT] Spawn Noxines - 796 - Saharach (fungus)\n-- \nfunction event_2330_19671()\n    \nend\n\n-- [INIT] Spawn Noxines - 943 - Kelba\n-- \nfunction event_2330_19672()\n    \nend\n\n-- [INIT] Spawn Noxines - 999 - Moon (surface)\n-- \nfunction event_2330_19673()\n    \nend\n\n-- [INIT] Spawn Noxines - 1053 - Moon (sous-sol)\n-- \nfunction event_2330_19674()\n    \nend\n\n-- [INIT] Spawn Noxines - 1118 - Zinit (plage)\n-- \nfunction event_2330_19675()\n    \nend\n\n-- [INIT] Spawn Noxines - 1119 - Zinit (grotte slek)\n-- \nfunction event_2330_19676()\n    \nend\n\n-- [INIT] Spawn Noxines - 1120 - Zinit (bas flanc)\n-- \nfunction event_2330_19677()\n    \nend\n\n-- [INIT] Spawn Noxines - 1122 - Zinit (haut flanc)\n-- \nfunction event_2330_19678()\n    \nend\n\n-- [INIT] Spawn Noxines - 1124 - Zinit (sommet)\n-- \nfunction event_2330_19680()\n    \nend\n\n","functions":["event_2330_19654","event_2330_19655","event_2330_19656","event_2330_19657","event_2330_19658","event_2330_19659","event_2330_19660","event_2330_19661","event_2330_19662","event_2330_19663","event_2330_19664","event_2330_19665","event_2330_19666","event_2330_19667","event_2330_19639","event_2330_19681","event_2330_19668","event_2330_19669","event_2330_19670","event_2330_19671","event_2330_19672","event_2330_19673","event_2330_19674","event_2330_19675","event_2330_19676","event_2330_19677","event_2330_19678","event_2330_19680"],"quest_calls":[],"dialogue_calls":[]},"scenario/2331.lua":{"source":"\n\n-- [INIT] Despawn les Monstres Cyclique liés à l'Event\n-- \nfunction event_2331_19653()\n    \nend\n\n","functions":["event_2331_19653"],"quest_calls":[],"dialogue_calls":[]},"scenario/2332.lua":{"source":"bubbleNotificationId = 0\r\nNOTIFICATION_INTERVAL = 20000\r\nnotifications = {}\r\n\r\nfunction triggerUpdateInfo()\r\n\tServer.triggerEvent(99)\r\nend\r\n\r\nfunction onNotificationClosed()\r\n\tif (bubbleNotificationId ~= nil  and bubbleNotificationId ~= 0) then bubbleNotificationId = 0 end\r\nend\r\n\r\nfunction pushNotification(textKey, ...)\r\n\tlocal textInfo = {textKey = textKey, textParam = unpack(arg)}\r\n    table.insert(notifications, textInfo)\r\nend\r\n\r\nfunction pushNotificationPosition(pos, textKey, ...)\r\n\tlocal textInfo = {position = pos, textKey = textKey, textParam = unpack(arg)}\r\n    table.insert(notifications, textInfo)\r\nend\r\n\r\nfunction updateNotification()\r\n\tlocal textInfo = notifications[1]\r\n\t\r\n\tif (textInfo == nil) then return end\r\n\t\r\n\tif (bubbleNotificationId == 0) then\r\n\t\tbubbleNotificationId = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_EAST\", -45, -55, false, NOTIFICATION_INTERVAL - 500, true, \"interactiveBubbleDialog4\", 30000, 25000, \"onNotificationClosed\")\r\n\tend\r\n\t\r\n\tBubbleText.setText(bubbleNotificationId, textInfo.textKey, textInfo.textParam)\r\n\t\r\n\tlocal pos = textInfo.position\r\n\tif (pos ~= nil) then\r\n\t\tlocal x, y, z = longToPosition(pos)\r\n\t\tBubbleText.addButton(bubbleNotificationId, \"compass\", \"UI.addCompass\", \"battleground.01.general.fight\", x, y, z)\r\n\tend\r\n\t\r\n\tBubbleText.show(bubbleNotificationId)\r\n\ttable.remove(notifications, 1)\r\nend\n\n-- [INIT] Constantes - Score\n-- \nfunction event_2332_19682()\n    \nend\n\n-- [INIT] Variables & Constantes - Scenario\n-- \nfunction event_2332_19683()\n    \nend\n\n-- [INIT] Un joueur entre dans l'instance\n-- \nfunction event_2332_19684(own_team_id)\n    trace(\"PLAYER ENTER INSTANCE\")\r\n    trace(\"team du joueur qui entre dans l'instance\", own_team_id)\r\n    \r\n    triggerUpdateInfo()\r\n    \r\n    setInterval(NOTIFICATION_INTERVAL, \"updateNotification\")\nend\n\n-- [FLAG] Fleur ramenée - Score Perso & Equipe\n-- \nfunction event_2332_19685(event_team_id)\n    triggerUpdateInfo()\r\n    \r\n    --UI.writeLocalisedInChat(\"battleground.02.flag.collected.02\", event_team_id)\n    --pushNotification(\"battleground.02.flag.collected.02\", event_team_id)\nend\n\n-- [FIGHT] Joueur tué - Score Perso\n-- On vérifier not IsOutOfPlay(\"target\") car sinon ça déclenche 2 fois sur les joueurs K.O à la fin du combat\r\n-- see https://youtrack.ankama.com/issue/wakfuTrunk-35316\nfunction event_2332_19686()\n    trace(\"PLAYER KILLED - OWN SCORE\")\nend\n\n-- [FIGHT] Joueur tué - Score Equipe\n-- On vérifier not IsOutOfPlay(\"target\") car sinon ça déclenche 2 fois sur les joueurs K.O à la fin du combat\r\n-- see https://youtrack.ankama.com/issue/wakfuTrunk-35316\nfunction event_2332_19687(event_team_id, flag_owner)\n    trace(\"PLAYER KILLED - TEAM SCORE\")\r\n    trace(\"team du joueur tué\", event_team_id)\r\n    trace(\"joueur tué possède le drapeau\", flag_owner)\r\n    \r\n    --triggerUpdateInfo()\nend\n\n-- [FIGHT] Wapin / Maman Wapin tué - Score Perso\n-- \nfunction event_2332_19688()\n    trace(\"MONSTER KILLED - OWN SCORE\")\nend\n\n-- [FIGHT] Wapin / Maman Wapin tué - Score Equipe\n-- \nfunction event_2332_19689(event_team_id)\n    trace(\"MONSTER KILLED - TEAM SCORE\")\r\n    trace(\"team du joueur qui a tué le monstre\", event_team_id)\r\n    \r\n    --triggerUpdateInfo()\nend\n\n-- [FIGHT] Dark Wapin tué - Score Perso\n-- \nfunction event_2332_19690()\n    trace(\"MONSTER KILLED - OWN SCORE\")\nend\n\n-- [FIGHT] Dark Wapin tué - Score Equipe\n-- \nfunction event_2332_19691(event_team_id)\n    trace(\"MONSTER KILLED - TEAM SCORE\")\r\n    trace(\"team du joueur qui a tué le monstre\", event_team_id)\r\n    \r\n    --triggerUpdateInfo()\n    UI.writeLocalisedInChat(\"battleground.02.darkwapin.killed\", event_team_id)\r\n    pushNotification(\"battleground.02.darkwapin.killed\", event_team_id)\nend\n\n-- [FIGHT] Joueur débute un combat PvP - Score Perso\n-- \nfunction event_2332_19692(blueTeamCount, redTeamCount, event_team_id)\n    trace(\"PLAYER START PVP FIGHT - OWN SCORE\")\r\n    trace(\"blueTeamCount\", blueTeamCount)\r\n    trace(\"redTeamCount\", redTeamCount)\r\n    trace(\"team du joueur concerné\", event_team_id)\nend\n\n-- [IE][TP] CDG vers HUB - Désapplication d'état\n-- \nfunction event_2332_19693()\n    \nend\n\n-- [EVENT] BG_START - Procédures de démarrage du BG\n-- \nfunction event_2332_19694()\n    trace(\"BATTLEGROUND_START\")\nend\n\n-- [EVENT] BG_ENDED - Procédures de fin du BG\n-- On écoute BG_ENDED pour être sûr d'avoir terminé les procédures du scénario 2320\nfunction event_2332_19695(close_delay_ms)\n    trace(\"BATTLEGROUND_ENDED\")\r\n    \r\n    local delay_ms = toLong(close_delay_ms)\r\n    local delay_min = math.ceil(delay_ms / 1000 / 60)\r\n    \r\n    UI.writeLocalisedInChat(\"battleground.00.remaining.time.before.close\", delay_min)\r\n    pushNotification(\"battleground.00.remaining.time.before.close\", delay_min)\nend\n\n-- [UI] Score modifié - Mise à jour de l'UI\n-- \nfunction event_2332_19696(att_score, def_score, own_score, own_team_id, att_flag_collected, def_flag_collected, att_member, def_member)\n    trace(\"att_score\", att_score, \"def_score\", def_score)\r\n    trace(\"att_flag_collected\", att_flag_collected, \"def_flag_collected\", def_flag_collected)\r\n    --trace(\"own_score\", own_score)\r\n    trace(\"att_member\", att_member)\r\n    trace(\"def_member\", def_member)\r\n    \r\n    local att_flag_collected = toLong(att_flag_collected)\r\n    local def_flag_collected = toLong(def_flag_collected)\r\n    \r\n    local detailText = Context.getTranslation(\"battleground.02.battlegroundBarDetailText\", att_flag_collected, def_flag_collected)\r\n    UI.setTextWidget(\"battlegroundBarDialog\", \"battlegroundBarDetailTextId\", detailText)\nend\n\n-- [NOTIF] Fleur collectée\n-- \nfunction event_2332_19697(event_team_id)\n    trace(\"FLOWER CAPTURED\")\r\n    \r\n    --UI.writeLocalisedInChat(\"battleground.02.flag.collected.01\", event_team_id)\n    --pushNotification(\"battleground.02.flag.collected.01\", event_team_id)\nend\n\n-- [NOTIF] Respawn du Dark Wapin\n-- \nfunction event_2332_19698()\n    UI.writeLocalisedInChat(\"battleground.02.dark.wapin.respawn\", event_team_id)\r\n    pushNotification(\"battleground.02.dark.wapin.respawn\", event_team_id)\nend\n\n-- [NOTIF] Notifications récurrentes\n-- \nfunction event_2332_19699(att_score, def_score)\n    local att_score = toLong(att_score)\r\n    local def_score = toLong(def_score)\r\n    \r\n    local score_diff = math.abs(att_score - def_score)\r\n    local winning_team = \"att\"\r\n    if (def_score > att_score) then winning_team = \"def\" end\r\n    \r\n    if (score_diff >= 500) then\r\n    \tUI.writeLocalisedInChat(\"battleground.00.team.score.\" .. winning_team .. \".winning\", event_team_id)\r\n    \tpushNotification(\"battleground.00.team.score.\" .. winning_team .. \".winning\", event_team_id)\r\n    end\nend\n\n-- [FIGHT][DEATH] Joueur mort en fin de combat - Retrait des Etats\n-- \nfunction event_2332_19700()\n    \nend\n\n","functions":["triggerUpdateInfo","onNotificationClosed","pushNotification","pushNotificationPosition","updateNotification","event_2332_19682","event_2332_19683","event_2332_19684","event_2332_19685","event_2332_19686","event_2332_19687","event_2332_19688","event_2332_19689","event_2332_19690","event_2332_19691","event_2332_19692","event_2332_19693","event_2332_19694","event_2332_19695","event_2332_19696","event_2332_19697","event_2332_19698","event_2332_19699","event_2332_19700"],"quest_calls":[],"dialogue_calls":[]},"scenario/2333.lua":{"source":"bubbleNotificationId = 0\r\nNOTIFICATION_INTERVAL = 20000\r\nnotifications = {}\r\n\r\nfunction triggerUpdateInfo()\r\n\tServer.triggerEvent(99)\r\nend\r\n\r\nfunction onNotificationClosed()\r\n\tif (bubbleNotificationId ~= nil  and bubbleNotificationId ~= 0) then bubbleNotificationId = 0 end\r\nend\r\n\r\nfunction pushNotification(textKey, ...)\r\n\tlocal textInfo = {textKey = textKey, textParam = unpack(arg)}\r\n    table.insert(notifications, textInfo)\nend\n\nfunction pushNotificationPosition(pos, textKey, ...)\n\tlocal textInfo = {position = pos, textKey = textKey, textParam = unpack(arg)}\n    table.insert(notifications, textInfo)\nend\r\n\r\nfunction updateNotification()\r\n\tlocal textInfo = notifications[1]\r\n\t\r\n\tif (textInfo == nil) then return end\r\n\t\r\n\tif (bubbleNotificationId == 0) then\r\n\t\tbubbleNotificationId = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_EAST\", -45, -55, false, NOTIFICATION_INTERVAL - 500, true, \"interactiveBubbleDialog4\", 30000, 25000, \"onNotificationClosed\")\r\n\tend\r\n\t\r\n\tBubbleText.setText(bubbleNotificationId, textInfo.textKey, textInfo.textParam)\n\t\n\tlocal pos = textInfo.position\n\tif (pos ~= nil) then\n\t\tlocal x, y, z = longToPosition(pos)\n\t\tBubbleText.addButton(bubbleNotificationId, \"compass\", \"UI.addCompass\", \"battleground.01.general.fight\", x, y, z)\n\tend\n\t\r\n\tBubbleText.show(bubbleNotificationId)\r\n\ttable.remove(notifications, 1)\nend\n\n-- [INIT] Constantes - Score\n-- \nfunction event_2333_19709()\n    \nend\n\n-- [INIT] Variables & Constantes - Scenario\n-- \nfunction event_2333_19710()\n    \nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_2333_19711(own_team_id)\n    trace(\"PLAYER ENTER INSTANCE\")\r\n    trace(\"team du joueur qui entre dans l'instance\", own_team_id)\r\n    \r\n    --triggerUpdateInfo()\r\n    UI.setTextWidget(\"battlegroundBarDialog\", \"battlegroundBarDetailTextId\", \"\")\r\n    \r\n    setInterval(NOTIFICATION_INTERVAL, \"updateNotification\")\r\n    \r\n    local windForce = 1\r\n    local rainType = 3\r\n    Ambiance.setWeather(20, rainType, windForce)\nend\n\n-- [FIGHT] Joueur tué - Score Perso\n-- On vérifie not IsOutOfPlay(\"\"target\"\") car sinon l'event se déclenche 2 fois sur les joueurs qui sont K.O quand le combat se termine\r\n-- see https://youtrack.ankama.com/issue/wakfuTrunk-35316\nfunction event_2333_19712(event_team_id)\n    trace(\"PLAYER KILLED - OWN SCORE\")\r\n    trace(\"team du joueur tué\", event_team_id)\nend\n\n-- [FIGHT] Joueur tué - Score Equipe\n-- On vérifie not IsOutOfPlay(\"\"target\"\") car sinon l'event se déclenche 2 fois sur les joueurs qui sont K.O quand le combat se termine\r\n-- see https://youtrack.ankama.com/issue/wakfuTrunk-35316\nfunction event_2333_19713(event_team_id)\n    trace(\"PLAYER KILLED - TEAM SCORE\")\r\n    trace(\"team du joueur tué\", event_team_id)\r\n    \r\n    --triggerUpdateInfo()\nend\n\n-- [FIGHT] Joueur débute un combat PvP - Score Perso\n-- \nfunction event_2333_19714(blueTeamCount, redTeamCount, event_team_id)\n    trace(\"PLAYER START PVP FIGHT - OWN SCORE\")\r\n    trace(\"blueTeamCount\", blueTeamCount)\r\n    trace(\"redTeamCount\", redTeamCount)\r\n    trace(\"team du joueur concerné\", event_team_id)\nend\n\n-- [EVENT] Dépôt de points activé - Score Equipe\n-- \nfunction event_2333_21537(event_team_id)\n    trace(\"INTERACTIVE ELEMNT ACTIVATED - TEAM SCORE\")\r\n    trace(\"team du joueur qui active l'IE\", event_team_id)\r\n    \r\n    --triggerUpdateInfo()\r\nend\n\n-- [EVENT] BG_START - Procédures de démarrage du BG\n-- \nfunction event_2333_19716()\n    trace(\"BATTLEGROUND_START\")\nend\n\n-- [EVENT] BG_ENDED - Procédures de fin du BG\n-- On écoute BG_ENDED pour être sûr d'avoir terminé les procédures du scénario 2320\nfunction event_2333_19717()\n    trace(\"BATTLEGROUND_ENDED\")\nend\n\n-- [UI] Score modifié - Mise à jour de l'UI\n-- \nfunction event_2333_19718(att_score, def_score, own_score, own_team_id, att_member, def_member)\n    trace(\"own_team_id\", own_team_id)\r\n    --trace(\"own_score\", own_score)\r\n    trace(\"att_score\", att_score, \"def_score\", def_score)\r\n    trace(\"att_member\", att_member, \"def_member\", def_member)\nend\n\n-- [NOTIF] Notifications récurrentes\n-- \nfunction event_2333_19719(att_score, def_score)\n    local att_score = toLong(att_score)\r\n    local def_score = toLong(def_score)\r\n    \r\n    local score_diff = math.abs(att_score - def_score)\r\n    local winning_team = \"att\"\r\n    if (def_score > att_score) then winning_team = \"def\" end\r\n    \r\n    if (score_diff >= 500) then\r\n    \tUI.writeInChatPipe(13, \"battleground.00.team.score.\" .. winning_team .. \".winning\", event_team_id)\r\n    \tpushNotification(\"battleground.00.team.score.\" .. winning_team .. \".winning\", event_team_id)\r\n    end\nend\n\n","functions":["triggerUpdateInfo","onNotificationClosed","pushNotification","pushNotificationPosition","updateNotification","event_2333_19709","event_2333_19710","event_2333_19711","event_2333_19712","event_2333_19713","event_2333_19714","event_2333_21537","event_2333_19716","event_2333_19717","event_2333_19718","event_2333_19719"],"quest_calls":[],"dialogue_calls":[]},"scenario/2335.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\n\n-- [INIT] Variables\n-- \nfunction event_2335_19738()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario (quête 3972 en cours)\n-- \nfunction event_2335_19736()\n    \nend\n\n-- Le joueur termine la quête 3971 et débute la quête 3972 - Inscription au scénario\n-- \nfunction event_2335_19737()\n    \nend\n\n-- [EVENT] Le joueur examine la Trace 1 - Lancement Ciné Trace 1.1\n-- \nfunction event_2335_19725()\n    local playerId = Context.getLeaderId()\r\n    local ruelId = createActor(192404573, -80, 4, 0, 4, 7, 7)\r\n    local phorreurId = createActor(102200145, -72, 6, 0, 4, 7, 7)\r\n    \r\n    startCinematicContext(1.9, playerId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 19725)\r\n    \r\n    ------------------------------\r\n    \r\n    Mobile.setMobileVisible(phorreurId, false)\r\n    \r\n    -- Hmm, on dirait des kamas tombés par terre...\r\n    invoke_custom(1000, 1, \"bubble\", playerId, \"quest.ruel.phorreur.cine.1\")\r\n    \r\n    invoke_custom(2500, 1, \"Mobile.moveMobile\", ruelId, -72, 4, 0, \"Mobile.setMobileDirection\", ruelId, 3)\r\n    \r\n    invoke_custom(4500, 1, \"Camera.attachCameraToMobile\", ruelId)\r\n    \r\n    -- Oooooh des kamaaas !\r\n    invoke_custom(6000, 1, \"bubble\", ruelId, \"quest.ruel.phorreur.cine.2\")\r\n    invoke_custom(9000, 1, \"clearBubbles\", ruelId)\r\n    -- ... Au vu de leur positionnement, je dirais que le voleur est parti au nord-est !\r\n    invoke_custom(9500, 1, \"bubble\", ruelId, \"quest.ruel.phorreur.cine.3\")\r\n    \r\n    invoke_custom(13000, 1, \"Mobile.setMobileVisible\", phorreurId, true)\r\n    invoke_custom(13001, 1, \"Mobile.setMobileAnimation\", phorreurId, \"AnimSort-Surgissement\")\r\n    \r\n    invoke_custom(15000, 1, \"Mobile.setMobileAnimation\", phorreurId, \"AnimComp-Renifle\")\r\n    invoke_custom(17500, 1, \"Mobile.moveMobile\", phorreurId, -72, 5, 0)\r\n    \r\n    -- Mais qu'est-ce que... Naaaaoooon, laisse moiiiii ! \r\n    invoke_custom(18500, 1, \"bubble\", ruelId, \"quest.ruel.phorreur.cine.9\")\r\n    invoke_custom(19000, 1, \"Mobile.setMobileAnimation\", phorreurId, \"AnimSort-Charge\")\r\n    invoke_custom(19550, 1, \"Mobile.setMobileAnimation\", ruelId, \"AnimApparition\")\r\n    \r\n    ------------------------------\r\n    \r\n    invoke_custom(20300, 1, \"skipCinematic\", 19725)\nend\n\n-- [EVENT] Fin de Ciné Trace 1.1 - Lancement du Combat Phorreur\n-- \nfunction event_2335_19731()\n    \nend\n\n-- [EVENT] Début du combat Phorreur - Invocation de Ruel\n-- \nfunction event_2335_19732()\n    \nend\n\n-- [EVENT] Le combat Phorreur est gagné - Lancement Ciné Trace 1.2 - ACH 3972 OBJ 8452\n-- \nfunction event_2335_19726()\n    local playerId = Context.getLeaderId()\r\n    local ruelId = createActor(192404573, -72, 4, 0, 4, 3, 7)\r\n    local phorreurId = createActor(102200145, -72, 6, 0, 4, 7, 7)\r\n    \r\n    startCinematicContext(1.9, playerId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\")\r\n    \r\n    ------------------------------\r\n    \r\n    invoke_custom(10, 1, \"Mobile.setMobileAnimation\", ruelId, \"AnimApparition\")\r\n    invoke_custom(100, 1, \"Mobile.setMobileLookAt\", playerId, -72, 4)\r\n    invoke_custom(2000, 1, \"Mobile.setMobileAnimation\", phorreurId, \"AnimSort-Enfouissement\")\r\n    \r\n    invoke_custom(4500, 1, \"Camera.attachCameraToMobile\", ruelId)\r\n    \r\n    -- ...Enfin débarassés de cette bestiole.\r\n    invoke_custom(5000, 1, \"bubble\", ruelId, \"quest.ruel.phorreur.cine.10\")\r\n    invoke_custom(9000, 1, \"clearBubbles\", ruelId)\r\n    \r\n    -- Reprenons notre traque ! Je disais... le nord-est.\r\n    invoke_custom(10000, 1, \"Mobile.setMobileAnimation\", ruelId, \"AnimStatique\")\r\n    invoke_custom(10000, 1, \"bubble\", ruelId, \"quest.ruel.phorreur.cine.11\")\r\n    \r\n    -- Ben quoi ?\r\n    invoke_custom(14000, 1, \"bubble\", ruelId, \"quest.ruel.phorreur.cine.12\")\r\n    \r\n    invoke_custom(16500, 1, \"clearBubbles\", ruelId)\r\n    -- J'aime pas les phorreurs, qu'est-ce que ça peut te faire ?\r\n    invoke_custom(17000, 1, \"bubble\", ruelId, \"quest.ruel.phorreur.cine.13\")\r\n    \r\n    -- Allez, on y va ! On va pas y passer la journée...\r\n    invoke_custom(20500, 1, \"clearBubbles\", ruelId)\r\n    invoke_custom(21000, 1, \"bubble\", ruelId, \"quest.ruel.phorreur.cine.14\")\r\n    \r\n    ------------------------------\r\n    \r\n    invoke_custom(25000, 1, \"skipCinematic\")\nend\n\n-- [EVENT] Démarrage du Scénario - Lancement Ciné Trace 2 - ACH 3972 OBJ 8453\n-- \nfunction event_2335_19727()\n    local playerId = Context.getLeaderId()\r\n    local ruelId = createActor(192404573, -82, -76, 0, 4, 7, 7)\r\n    \r\n    startCinematicContext(1.9, playerId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\")\r\n    \r\n    ------------------------------\r\n    -- Hmm, on dirait des kamas tombés par terre...\r\n    invoke_custom(1000, 1, \"bubble\", playerId, \"quest.ruel.phorreur.cine.1\")\r\n    invoke_custom(2500, 1, \"Mobile.moveMobile\", ruelId, -74, -76, 0, \"Mobile.setMobileDirection\", ruelId, 3)\r\n    \r\n    invoke_custom(4500, 1, \"Camera.attachCameraToMobile\", ruelId)\r\n    -- Oooooh des kamaaas !\r\n    invoke_custom(6500, 1, \"bubble\", ruelId, \"quest.ruel.phorreur.cine.2\")\r\n    -- ... Le filou a une bonne longueur d'avance sur nous. Dépêchons-nous !\r\n    invoke_custom(10000, 1, \"bubble\", ruelId, \"quest.ruel.phorreur.cine.4\")\r\n    \r\n    ------------------------------\r\n    \r\n    invoke_custom(14300, 1, \"skipCinematic\")\nend\n\n-- [EVENT] Démarrage du Scénario - Lancement Ciné Trace 3 - ACH 3972 OBJ 8454\n-- \nfunction event_2335_19728()\n    local playerId = Context.getLeaderId()\r\n    local ruelId = createActor(192404573, -49, -100, 0, 4, 7, 7)\r\n    local phorreurId = createActor(102200145, -43, -97, 0, 4, 7, 7)\r\n    \r\n    startCinematicContext(1.9, playerId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\")\r\n    \r\n    ------------------------------\r\n    Mobile.setMobileVisible(phorreurId, false)\r\n    \r\n    -- Là, des kamas ! Il ne va plus en rester beaucoup si cette chasse se poursuit plus longtemps...\r\n    invoke_custom(1000, 1, \"bubble\", playerId, \"quest.ruel.phorreur.cine.8\")\r\n    invoke_custom(3500, 1, \"Mobile.moveMobile\", ruelId, -43, -99, 0, \"Mobile.setMobileDirection\", ruelId, 3)\r\n    \r\n    invoke_custom(4500, 1, \"Camera.attachCameraToMobile\", ruelId)\r\n    invoke_custom(6000, 1, \"clearBubbles\", playerId)\r\n    \r\n    --Oooooh des kamaaas !\r\n    invoke_custom(6500, 1, \"bubble\", ruelId, \"quest.ruel.phorreur.cine.2\")\r\n    --Les mines ! J'aurais dû m'en douter... Ces kamas sentent le charbon à plein nez !\r\n    invoke_custom(10000, 1, \"bubble\", ruelId, \"quest.ruel.phorreur.cine.5\")\r\n    \r\n    invoke_custom(13000, 1, \"Mobile.setMobileVisible\", phorreurId, true)\r\n    invoke_custom(13001, 1, \"Mobile.setMobileAnimation\", phorreurId, \"AnimSort-Surgissement\")\r\n    invoke_custom(15000, 1, \"clearBubbles\", ruelId)\r\n    invoke_custom(15000, 1, \"Mobile.setMobileAnimation\", phorreurId, \"AnimComp-Renifle\")\r\n    \r\n    --Encore ?! Mais laisse moi tranquille, saleté de phorreur !\r\n    invoke_custom(15500, 1, \"bubble\", ruelId, \"quest.ruel.phorreur.cine.7\")\r\n    invoke_custom(17000, 1, \"Mobile.setMobileAnimation\", phorreurId, \"AnimSort-Enfouissement\")\r\n    invoke_custom(17000, 1, \"Mobile.setMobileAnimation\", ruelId, \"AnimApparition\")\r\n    \r\n    ------------------------------\r\n    \r\n    invoke_custom(19000, 1, \"skipCinematic\")\nend\n\n-- [EVENT] Démarrage du Scénario - Lancement Ciné Trace 4 - ACH 3972 OBJ 8455\n-- \nfunction event_2335_19729()\n    local playerId = Context.getLeaderId()\r\n    local ruelId = createActor(192404573, -36, -40, 30, 4, 7, 7)\r\n    \r\n    startCinematicContext(1.9, playerId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\")\r\n    \r\n    ------------------------------\r\n    -- Là, des kamas ! Il ne va plus en rester beaucoup si cette chasse se poursuit plus longtemps...\r\n    invoke_custom(1000, 1, \"bubble\", playerId, \"quest.ruel.phorreur.cine.8\")\r\n    invoke_custom(3500, 1, \"Mobile.moveMobile\", ruelId, -33, -35, 30, \"Mobile.setMobileDirection\", ruelId, 3)\r\n    \r\n    invoke_custom(4500, 1, \"Camera.attachCameraToMobile\", ruelId)\r\n    invoke_custom(6000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- Oooooh des kamaaas !\r\n    invoke_custom(6500, 1, \"bubble\", ruelId, \"quest.ruel.phorreur.cine.2\")\r\n    -- Bon sang, je sais où il va ! Il y a une planque plus loin dans les tunnels, suis-moi !!!\r\n    invoke_custom(11000, 1, \"bubble\", ruelId, \"quest.ruel.phorreur.cine.6\")\r\n    \r\n    ------------------------------\r\n    \r\n    invoke_custom(15300, 1, \"skipCinematic\")\nend\n\n-- Le joueur quitte l'instance - Désinscription du scénario\n-- \nfunction event_2335_19739()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_2335_19738","event_2335_19736","event_2335_19737","event_2335_19725","event_2335_19731","event_2335_19732","event_2335_19726","event_2335_19727","event_2335_19728","event_2335_19729","event_2335_19739"],"quest_calls":[],"dialogue_calls":[]},"scenario/2336.lua":{"source":"local test = 1\r\ntestglobal = 2\r\ntesthuhu = 3\r\ntest4 = 4\r\ntest5 = 5\r\ntest6=6\r\n\r\n\r\n\r\nfunction testfunc()\r\nend\n\n-- Items\n-- \nfunction event_2336_19744()\n    \nend\n\n-- Achievements\n-- \nfunction event_2336_19745()\n    \nend\n\n-- \n-- \nfunction event_2336_21127()\n    \nend\n\n-- table de loot de quêtes\n-- \nfunction event_2336_19746()\n    local mob4 = 6\r\n    mob5 = 9\r\n    \r\n    function mobfunction()\r\n    end\r\n    mo\nend\n\n","functions":["testfunc","event_2336_19744","event_2336_19745","event_2336_21127","event_2336_19746","mobfunction"],"quest_calls":[],"dialogue_calls":[]},"scenario/2337.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\n\n-- ~[INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2337_19748()\n    \nend\n\n-- [INIT] Variables Globales\n-- \nfunction event_2337_20185()\n    \nend\n\n-- ~[EVENT] ENTER_INSTANCE - Accueil par un PNJ\n-- \nfunction event_2337_19749()\n    \nend\n\n-- [EVENT] Le joueur parle au MDC Mandhal - Cinématique Quête Mercenaire 1\n-- \nfunction event_2337_19759(taureMdcId)\n    \tlocal playerId = Context.getLeaderId()\r\n    \tlocal playerX, playerY, playerZ = Mobile.getMobilePosition(playerId)\r\n    \r\n    \tlocal taureMdcId = toLong(taureMdcId)\r\n    \tlocal flaqueuxId = createActor(122601633, -61, -53, 0, 8, 1, 4)\r\n    \r\n    \tstartCinematicContext(1.2, playerId)\r\n    \tUI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 19759)\r\n    \r\n    \tinvoke_custom(100, 1, \"Mobile.moveMobile\", playerId, -48, -57, 0, \"Mobile.setMobileDirection\", playerId, 7)\r\n    \r\n    \t--\"C'est un objet extrêmement, on en a plus en stock...\"\r\n    \tinvoke_custom(1000, 1, \"bubble\", taureMdcId, \"quest.sufokia.mercenary.flaqueux.01.01\")\r\n    \tinvoke_custom(1000, 1, \"Mobile.setMobileAnimation\", taureMdcId, \"AnimComp01\")\r\n    \tinvoke_custom(4000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Acquiescer\")\r\n    \tinvoke_custom(6500, 1, \"clearBubbles\", taureMdcId)\r\n    \r\n    \t--\"Hé, les flaqueux !!!\"\r\n    \tinvoke_custom(6500, 1, \"bubble\", taureMdcId, \"quest.sufokia.mercenary.flaqueux.01.02\")\r\n    \tinvoke_custom(6500, 1, \"Mobile.setMobileAnimation\", taureMdcId, \"AnimComp-Cri\")\r\n    \tinvoke_custom(7000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-BoucherlesOreilles-Debut\")\r\n    \r\n    \t--\"Venez donc par ici !\"\r\n    \tinvoke_custom(10000, 1, \"bubble\", taureMdcId, \"quest.sufokia.mercenary.flaqueux.01.03\")\r\n    \tinvoke_custom(10000, 1, \"Mobile.setMobileAnimation\", taureMdcId, \"AnimComp-Cri\")\r\n    \r\n    \tinvoke_custom(13000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-BoucherlesOreilles-Fin\")\r\n    \r\n    \tinvoke_custom(14800, 1, \"Mobile.setMobileVisible\", flaqueuxId, true)\r\n    \tinvoke_custom(14900, 1, \"Mobile.moveMobile\", flaqueuxId, -48, -53, 0)\r\n    \tinvoke_custom(15000, 1, \"Camera.attachCameraToMobile\", flaqueuxId)\r\n    \tinvoke_custom(19000, 1, \"Mobile.moveMobile\", flaqueuxId, -48, -55, 0)\r\n    \r\n    \tinvoke_custom(20200, 1, \"Mobile.moveMobile\", playerId, -47, -57, 0, \"Mobile.setMobileDirection\", playerId, 3)\r\n    \r\n    \tinvoke_custom(21000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Coucou\")\r\n    \tinvoke_custom(21000, 1, \"Mobile.setMobileAnimation\", flaqueuxId, \"AnimComp01\")\r\n    \r\n    \t--\"Toi ! Réponds ! Est-ce que c'est nous qu'on a une Pom d'or en réserve ?\"\r\n    \tinvoke_custom(23000, 1, \"bubble\", taureMdcId, \"quest.sufokia.mercenary.flaqueux.01.04\")\r\n    \tinvoke_custom(23000, 1, \"Mobile.setMobileAnimation\", taureMdcId, \"AnimComp04\")\r\n    \r\n    \t--\"M-monsieur le T-taure, j-je ne comprends p-pas...\"\r\n    \tinvoke_custom(28000, 1, \"bubble\", flaqueuxId, \"quest.sufokia.mercenary.flaqueux.01.05\")\r\n    \tinvoke_custom(28000, 1, \"Mobile.setMobileAnimation\", flaqueuxId, \"AnimComp02\")\r\n    \r\n    \t--\"SILENCE !!!\"\r\n    \tinvoke_custom(32000, 1, \"Camera.attachCameraToMobile\", taureMdcId)\r\n    \tinvoke_custom(32000, 1, \"Mobile.setMobileAnimation\", taureMdcId, \"AnimSort-Poing\")\r\n    \tinvoke_custom(32000, 1, \"bubble\", taureMdcId, \"quest.sufokia.mercenary.flaqueux.01.06\")\r\n    \tinvoke_custom(32800, 1, \"clearBubbles\", flaqueuxId)\r\n    \tinvoke_custom(32800, 1, \"Mobile.setMobileAnimation\", flaqueuxId, \"AnimHit\")\r\n    \tinvoke_custom(32800, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Effrayee\")\r\n    \tinvoke_custom(35000, 1, \"clearBubbles\", taureMdcId)\r\n    \r\n    \t--\"Va vite me trouver une Pom d'or ! Allez, exécution !\"\r\n    \tinvoke_custom(36000, 1, \"Mobile.setMobileAnimation\", taureMdcId, \"AnimComp04\")\r\n    \tinvoke_custom(36000, 1, \"bubble\", taureMdcId, \"quest.sufokia.mercenary.flaqueux.01.07\")\r\n    \r\n    \tinvoke_custom(40000, 1, \"Mobile.moveMobile\", flaqueuxId, -48, -53, 0)\r\n    \tinvoke_custom(41000, 1, \"Mobile.moveMobile\", flaqueuxId, -54, -53, 0)\r\n    \tinvoke_custom(43000, 1, \"Mobile.moveMobile\", flaqueuxId, -54, -75, 0)\r\n    \tinvoke_custom(49000, 1, \"Mobile.setMobileVisible\", flaqueuxId, false)\r\n    \r\n    \tinvoke_custom(45000, 1, \"Mobile.moveMobile\", playerId, -48, -57, 0, \"Mobile.setMobileDirection\", playerId, 7)\r\n    \r\n    \t--\"Ah, ces Flaqueux, y'en a qui croivent pouvoir me cacher des choses !\"\r\n    \tinvoke_custom(48000, 1, \"Mobile.setMobileAnimation\", taureMdcId, \"AnimComp03\")\r\n    \tinvoke_custom(48000, 1, \"bubble\", taureMdcId, \"quest.sufokia.mercenary.flaqueux.01.08\")\r\n    \tinvoke_custom(55000, 1, \"clearBubbles\", taureMdcId)\r\n    \r\n    \t--\"Hé mais dis-donc, toi ! Tout salaire mérite travail, pas vrai ?\"\r\n    \tinvoke_custom(56000, 1, \"bubble\", taureMdcId, \"quest.sufokia.mercenary.flaqueux.01.09\")\r\n    \tinvoke_custom(62500, 1, \"clearBubbles\", taureMdcId)\r\n    \r\n    \t--\"Tu tombes bien, j'avais besoin de quelqu'un pour s'occuper de la maintenance des tonneaux de Poms.\"\r\n    \tinvoke_custom(63500, 1, \"bubble\", taureMdcId, \"quest.sufokia.mercenary.flaqueux.01.10\")\r\n    \tinvoke_custom(70000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Bailler\")\r\n    \tinvoke_custom(71500, 1, \"clearBubbles\", taureMdcId)\r\n    \r\n    \t--\"Tu peux t'en charger ? Ça t'occupera pendant que le Flaqueux cherche ta Pom d'or.\"\r\n    \tinvoke_custom(72000, 1, \"Mobile.setMobileAnimation\", taureMdcId, \"AnimComp03\")\r\n    \tinvoke_custom(72500, 1, \"bubble\", taureMdcId, \"quest.sufokia.mercenary.flaqueux.01.11\")\r\n    \tinvoke_custom(79000, 1, \"clearBubbles\", taureMdcId)\r\n    \r\n    \t--\"Pense à emporter des Planche Durable avec toi.\"\r\n    \tinvoke_custom(80000, 1, \"bubble\", taureMdcId, \"quest.sufokia.mercenary.flaqueux.01.12\")\r\n    \tinvoke_custom(83000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Acquiescer\")\r\n    \r\n    \t----------------------------------\r\n    \tinvoke_custom(85000, 1, \"Mobile.moveMobile\", playerId, playerX, playerY, playerZ)\r\n    \tinvoke_custom(86500, 1, \"skipCinematic\", 19759)\r\nend\n\n-- [EVENT] Fin Cinématique MDC Mandhal - Validation OBJ 8730 ACH 4230\n-- \nfunction event_2337_19760()\n    \nend\n\n-- [EVENT] Le joueur arrive sur la zone - Lancement Ciné Flaqueux Blanc 1.1\n-- \nfunction event_2337_19774()\n    \tlocal playerId = Context.getLeaderId()\r\n    \tlocal flaqueuxId = createActor(122601633, -77, 31, 0, 8, 3, 4)\r\n    \tlocal mobiletaureId = createActor(122301286, -77, 33, 0, 8, 7, 7)\r\n    \r\n    \tMobile.setPartColor(mobiletaureId, \"Color_1\", 1.00, 1.00, 0.84, 1)\r\n    \tMobile.setPartColor(mobiletaureId, \"Color_2\", 0.11, 0.09, 0.05, 1)\r\n    \tMobile.setPartColor(mobiletaureId, \"Peau\", 1.00, 0.78, 0.25, 1)\r\n    \tMobile.setPartColor(mobiletaureId, \"Cheveux\", 0.18, 0.36, 0.25, 1)\r\n    \r\n    \tstartCinematicContext(1.2, playerId)\r\n    \tUI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 19774)\r\n    \r\n    \t------------------------------\r\n    \tMobile.setMobileVisible(flaqueuxId, true)\r\n    \tinvoke_custom(100, 1, \"Mobile.moveMobile\", playerId, -72, 32, 0, \"Mobile.setMobileDirection\", playerId, 5)\r\n    \r\n    \tinvoke_custom(4000, 1, \"Mobile.setMobileAnimation\", mobiletaureId, \"AnimSort-CoupdePoing\")\r\n    \r\n    \tinvoke_custom(4600, 1, \"Mobile.setMobileAnimation\", flaqueuxId, \"AnimMort\")\r\n    \tinvoke_custom(5200, 1, \"Mobile.setMobileAnimation\", flaqueuxId, \"AnimSort-Resurrection-1\")\r\n    \r\n    \t-- Au secours ! Au secours !\r\n    \tinvoke_custom(5000, 1, \"bubble\", flaqueuxId, \"quest.sufokia.mercenary.flaqueux.02.03\")\r\n    \r\n    \tinvoke_custom(6000, 1, \"Mobile.setMobileAnimation\", mobiletaureId, \"AnimSort-Haka04-Debut\")\r\n    \tinvoke_custom(6800, 1, \"Mobile.setMobileAnimation\", mobiletaureId, \"AnimSort-Haka04-Boucle\")\r\n    \t-- **On dirait que le Flaqueux a besoin d'aide !\r\n    \tinvoke_custom(7500, 1, \"bubble\", playerId, \"quest.sufokia.mercenary.flaqueux.02.04\")\r\n    \r\n    \t------------------------------\r\n    \r\n    \tinvoke_custom(10000, 1, \"skipCinematic\", 19774)\nend\n\n-- [EVENT] Fin de Ciné Flaqueux Blanc 1.1 - Lancement du Combat Taures\n-- \nfunction event_2337_19775()\n    \nend\n\n-- [EVENT] Le combat Taures est gagné - Lancement Ciné Flaqueux Blanc 1.2 - ACH 4233 OBJ 8741\n-- \nfunction event_2337_19777()\n    local playerId = Context.getLeaderId()\r\n    local flaqueuxId = createActor(122601633, -76, 35, 0, 8, 3, 4)\r\n    \r\n    startCinematicContext(1.2, flaqueuxId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 19777)\r\n    \r\n    ------------------------------\r\n    \r\n    Mobile.setMobileVisible(flaqueuxId, true)\r\n    invoke_custom(100, 1, \"Mobile.moveMobile\", playerId, -76, 36, 0, \"Mobile.setMobileDirection\", playerId, 7)\r\n    \r\n    -- Pourquoi m'avoir aidé ? Les Taures vont m'en vouloir maintenant !\r\n    invoke_custom(3500, 1, \"bubble\",  flaqueuxId, \"quest.sufokia.mercenary.flaqueux.03.01\")\r\n    invoke_custom(9500, 1, \"clearBubbles\", flaqueuxId)\r\n    \r\n    -- Et si tu m'expliquais un peu la situation pour les Flaqueux, ici ? Je n'ai pas l'impression que les Flaqueux soient heureux...\r\n    invoke_custom(10500, 1, \"bubble\",  playerId, \"quest.sufokia.mercenary.flaqueux.03.02\")\r\n    invoke_custom(10500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Calmer\")\r\n    invoke_custom(19500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- ... Tout a commencé il y a quelques mois, lorsque les Taures ont commencé à nous envahir.\r\n    invoke_custom(20500, 1, \"bubble\",  flaqueuxId, \"quest.sufokia.mercenary.flaqueux.03.03\")\r\n    invoke_custom(20500, 1, \"Mobile.setMobileAnimation\", flaqueuxId, \"AnimComp-Parler-Neutre\")\r\n    invoke_custom(27500, 1, \"clearBubbles\", flaqueuxId)\r\n    \r\n    -- Nous sommes profondément pacifistes, et donc nous avons fait tout ce qu'ils demandaient.\r\n    invoke_custom(28500, 1, \"bubble\",  flaqueuxId, \"quest.sufokia.mercenary.flaqueux.03.04\")\r\n    invoke_custom(36500, 1, \"clearBubbles\", flaqueuxId)\r\n    \r\n    -- Mais leurs demandes sont de moins en moins raisonnables ! Ils nous demandent de détrousser tous ceux qui s'aventurent dans la région...\r\n    invoke_custom(38000, 1, \"bubble\",  flaqueuxId, \"quest.sufokia.mercenary.flaqueux.03.05\")\r\n    invoke_custom(46000, 1, \"clearBubbles\", flaqueuxId)\r\n    \r\n    -- Je souhaiterais partir de Sufokia, mais les Taures nous surveillent et s'emparent de tous les kamas et toutes les ressources que nous trouvons.\r\n    invoke_custom(46500, 1, \"bubble\",  flaqueuxId, \"quest.sufokia.mercenary.flaqueux.03.06\")\r\n    invoke_custom(55500, 1, \"clearBubbles\", flaqueuxId)\r\n    \r\n    -- Tant qu'ils seront là, nous ne pourrons plus posséder nos précieuses Poms d'or...\r\n    invoke_custom(56500, 1, \"bubble\",  flaqueuxId, \"quest.sufokia.mercenary.flaqueux.03.07\")\r\n    invoke_custom(63000, 1, \"clearBubbles\", flaqueuxId)\r\n    \r\n    -- Et ces Poms d'or alors, je peux en trouver où ?\r\n    invoke_custom(64000, 1, \"bubble\",  playerId, \"quest.sufokia.mercenary.flaqueux.03.08\")\r\n    invoke_custom(64000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(70000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- Tu peux en trouver au hasard sur des Pommiers de Sufokia portant des fruits. C'est une recherche minutieuse.\r\n    invoke_custom(71000, 1, \"bubble\",  flaqueuxId, \"quest.sufokia.mercenary.flaqueux.03.09\")\r\n    invoke_custom(78000, 1, \"clearBubbles\", flaqueuxId)\r\n    \r\n    -- C'est vraiment rare, donc si tu en trouves une, tu peux la garder. Je vais t'aider à chercher, de mon côté.\r\n    invoke_custom(79000, 1, \"bubble\",  flaqueuxId, \"quest.sufokia.mercenary.flaqueux.03.10\")\r\n    invoke_custom(86000, 1, \"clearBubbles\", flaqueuxId)\r\n    \r\n    -- **J'ai juste besoin de ramasser des Poms sur des arbres, c'est ça ?\r\n    invoke_custom(86500, 1, \"bubble\",  playerId, \"quest.sufokia.mercenary.flaqueux.03.11\")\r\n    invoke_custom(91500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Bailler\")\r\n    \r\n    -- **Je vais chercher aussi, alors.\r\n    invoke_custom(92000, 1, \"bubble\",  playerId, \"quest.sufokia.mercenary.flaqueux.03.12\")\r\n    \r\n    ------------------------------\r\n    \r\n    invoke_custom(96000, 1, \"skipCinematic\")\nend\n\n-- [EVENT] Le joueur ramasse une Pom d'or - ACH 4230 OBJ 8733\n-- \nfunction event_2337_19789()\n    local playerId = Context.getLeaderId()\r\n    \r\n    startCinematicContext(1.4, playerId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 19789)\r\n    \r\n    ------------------------------\r\n    \r\n    -- **Enfin ! Enfin, je trouve une Pom d'Or !\r\n    invoke_custom(100, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Victoire\")\r\n    invoke_custom(500, 1, \"bubble\",  playerId, \"quest.sufokia.mercenary.flaqueux.03.13\")\r\n    invoke_custom(4500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- **Je me demande si je la ramène à la Guilde des Mercenaires tout de suite...\r\n    invoke_custom(5000, 1, \"bubble\",  playerId, \"quest.sufokia.mercenary.flaqueux.03.14\")\r\n    invoke_custom(11000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- **... Ou bien, je pourrais la donner au Flaqueux Blanc.\r\n    invoke_custom(12500, 1, \"bubble\",  playerId, \"quest.sufokia.mercenary.flaqueux.03.15\")\r\n    invoke_custom(14000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(17500, 1, \"clearBubbles\", playerId)\r\n    \r\n    \r\n    -- **J'ai le choix. Mais d'abord, je dois prévenir Mandhal.\r\n    invoke_custom(18500, 1, \"bubble\",  playerId, \"quest.sufokia.mercenary.flaqueux.03.16\")\r\n    invoke_custom(18500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Calmer\")\r\n    \r\n    ------------------------------\r\n    \r\n    invoke_custom(24000, 1, \"skipCinematic\", 19789)\nend\n\n-- [EVENT] Le joueur examine la maison sans Pom d'or - Lancement Ciné Flaqueux Blanc\n-- \nfunction event_2337_19779()\n    local playerId = Context.getLeaderId()\r\n    local flaqueuxId = createActor(122601633, -93, -84, 89, 8, 3, 4)\r\n    \r\n    startCinematicContext(1.4, playerId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\")\r\n    \r\n    ------------------------------\r\n    \r\n    Mobile.setMobileVisible(flaqueuxId, true)\r\n    invoke_custom(100, 1, \"Mobile.moveMobile\", playerId, -93, -83, 90, \"Mobile.setMobileDirection\", playerId, 7)\r\n    \r\n    -- Ah, c'est toi. Bonjour ! Tu me cherchais ?\r\n    invoke_custom(2000, 1, \"bubble\",  flaqueuxId, \"quest.sufokia.mercenary.flaqueux.04.01\")\r\n    invoke_custom(2000, 1, \"Mobile.setMobileAnimation\", flaqueuxId, \"AnimComp01\")\r\n    invoke_custom(6000, 1, \"clearBubbles\", flaqueuxId)\r\n    \r\n    -- Tu as trouvé une Pom d'or ? Félicitations !\r\n    invoke_custom(6500, 1, \"bubble\",  flaqueuxId, \"quest.sufokia.mercenary.flaqueux.04.02\")\r\n    invoke_custom(11500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Presenter\")\r\n    invoke_custom(12000, 1, \"clearBubbles\", flaqueuxId)\r\n    \r\n    -- Quoi ? Tu veux proposer tes services de mercenaire pour m'aider à m'enfuir de Sufokia ?\r\n    invoke_custom(15500, 1, \"bubble\",  flaqueuxId, \"quest.sufokia.mercenary.flaqueux.04.10\")\r\n    invoke_custom(18500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Acquiescer\")\r\n    invoke_custom(22500, 1, \"clearBubbles\", flaqueuxId)\r\n    \r\n    -- Je n'ai pas vraiment de quoi te payer...\r\n    invoke_custom(23500, 1, \"bubble\",  flaqueuxId, \"quest.sufokia.mercenary.flaqueux.04.11\")\r\n    invoke_custom(27500, 1, \"clearBubbles\", flaqueuxId)\r\n    \r\n    -- Je tiens à rendre service, vous pourrez me payer plus tard.\r\n    invoke_custom(28000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Pouce\")\r\n    invoke_custom(28000, 1, \"bubble\",  playerId, \"quest.sufokia.mercenary.flaqueux.04.12\")\r\n    invoke_custom(33500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- Nous avons peu, mais je veux bien que tu m'accompagnes.\r\n    invoke_custom(34000, 1, \"bubble\",  flaqueuxId, \"quest.sufokia.mercenary.flaqueux.04.13\")\r\n    invoke_custom(40000, 1, \"clearBubbles\", flaqueuxId)\r\n    \r\n    -- Ce ne sera pas un périple facile... Il faut qu'on puisse convaincre la Flaque Royale.\r\n    invoke_custom(40500, 1, \"bubble\",  flaqueuxId, \"quest.sufokia.mercenary.flaqueux.04.08\")\r\n    invoke_custom(46500, 1, \"clearBubbles\", flaqueuxId)\r\n    \r\n    -- C'est notre meilleure guerrière ! Si elle nous accompagne, d'autres nous suivront. J'ai confiance en nos chances de succès !\r\n    invoke_custom(47000, 1, \"bubble\",  flaqueuxId, \"quest.sufokia.mercenary.flaqueux.04.09\")\r\n    invoke_custom(55000, 1, \"clearBubbles\", flaqueuxId)\r\n    \r\n    invoke_custom(56000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Pouce\")\r\n    \r\n    ------------------------------\r\n    \r\n    invoke_custom(58000, 1, \"skipCinematic\")\nend\n\n-- [EVENT] Le joueur examine la maison en ayant une Pom d'or - Lancement Ciné Flaqueux Blanc\n-- \nfunction event_2337_19778()\n    local playerId = Context.getLeaderId()\r\n    local flaqueuxId = createActor(122601633, -93, -84, 89, 8, 3, 4)\r\n    \r\n    startCinematicContext(1.4, playerId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\")\r\n    \r\n    ------------------------------\r\n    \r\n    Mobile.setMobileVisible(flaqueuxId, true)\r\n    invoke_custom(100, 1, \"Mobile.moveMobile\", playerId, -93, -83, 90, \"Mobile.setMobileDirection\", playerId, 7)\r\n    \r\n    -- Ah, c'est toi. Bonjour ! Tu me cherchais ?\r\n    invoke_custom(2000, 1, \"bubble\",  flaqueuxId, \"quest.sufokia.mercenary.flaqueux.04.01\")\r\n    invoke_custom(2000, 1, \"Mobile.setMobileAnimation\", flaqueuxId, \"AnimComp01\")\r\n    invoke_custom(6000, 1, \"clearBubbles\", flaqueuxId)\r\n    \r\n    -- Tu as trouvé une Pom d'or ? Félicitations !\r\n    invoke_custom(6500, 1, \"bubble\",  flaqueuxId, \"quest.sufokia.mercenary.flaqueux.04.02\")\r\n    \r\n    invoke_custom(11500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Presenter\")\r\n    invoke_custom(12000, 1, \"clearBubbles\", flaqueuxId)\r\n    \r\n    -- Quoi ? C'est pour moi ? Pour m'aider à m'enfuir ?\r\n    invoke_custom(15500, 1, \"bubble\", flaqueuxId, \"quest.sufokia.mercenary.flaqueux.04.03\")\r\n    invoke_custom(18500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Acquiescer\")\r\n    invoke_custom(20500, 1, \"clearBubbles\", flaqueuxId)\r\n    \r\n    -- Je... Je ne sais pas quoi dire... Voilà des années que mon peuple n'a connu que la terreur...\r\n    invoke_custom(21000, 1, \"bubble\",  flaqueuxId, \"quest.sufokia.mercenary.flaqueux.04.04\")\r\n    invoke_custom(27500, 1, \"clearBubbles\", flaqueuxId)\r\n    \r\n    -- Tu devrais la garder, tu en as besoin pour ta mission...\r\n    invoke_custom(28000, 1, \"bubble\",  flaqueuxId, \"quest.sufokia.mercenary.flaqueux.04.05\")\r\n    invoke_custom(34500, 1, \"clearBubbles\", flaqueuxId)\r\n    \r\n    invoke_custom(35000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Colere\")\r\n    invoke_custom(36000, 1, \"Mobile.setMobileAnimation\", flaqueuxId, \"AnimHit\")\r\n    \r\n    -- D'accord, je l'accepte, pas la peine de s'énerver !\r\n    invoke_custom(37000, 1, \"bubble\",  flaqueuxId, \"quest.sufokia.mercenary.flaqueux.04.06\")\r\n    invoke_custom(41500, 1, \"clearBubbles\", flaqueuxId)\r\n    \r\n    -- C'est un miracle. Je suis presque prêt à partir de Sufokia maintenant !\r\n    invoke_custom(42000, 1, \"bubble\",  flaqueuxId, \"quest.sufokia.mercenary.flaqueux.04.07\")\r\n    invoke_custom(42000, 1, \"Mobile.setMobileAnimation\", flaqueuxId, \"AnimComp-Parler-Neutre\")\r\n    invoke_custom(48500, 1, \"clearBubbles\", flaqueuxId)\r\n    \r\n    -- Ce ne sera pas un périple facile... Il faut qu'on puisse convaincre la Flaque Royale.\r\n    invoke_custom(50000, 1, \"bubble\",  flaqueuxId, \"quest.sufokia.mercenary.flaqueux.04.08\")\r\n    invoke_custom(56500, 1, \"clearBubbles\", flaqueuxId)\r\n    \r\n    -- C'est notre meilleure guerrière ! Si elle nous accompagne, d'autres nous suivront. J'ai confiance en nos chances de succès !\r\n    invoke_custom(57500, 1, \"bubble\",  flaqueuxId, \"quest.sufokia.mercenary.flaqueux.04.09\")\r\n    invoke_custom(65500, 1, \"clearBubbles\", flaqueuxId)\r\n    \r\n    invoke_custom(66500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Pouce\")\r\n    \r\n    ------------------------------\r\n    \r\n    invoke_custom(68500, 1, \"skipCinematic\")\nend\n\n-- [EVENT] Fin Ciné Flaqueux Blanc - Le joueur est téléporté dans le donjon Flaqueux - ACH 4234 OBJ 8743\n-- \nfunction event_2337_19785()\n    \nend\n\n-- [EVENT] Début Ciné adieux Flaqueux - Le joueur est téléporté dans le donjon Flaqueux (ACH 4234 OBJ 8746)\n-- \nfunction event_2337_19791()\n    \nend\n\n-- [EVENT] Le joueur est téléporté depuis le donjon - Lancement Ciné adieux Flaqueux 1 (pom déjà rendue)\n-- \nfunction event_2337_19792()\n    local playerId = Context.getLeaderId()\r\n    local flaqueuxId = createActor(122601633, -93, -84, 89, 8, 3, 4)\r\n    \r\n    startCinematicContext(1.4, playerId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\")\r\n    \r\n    ------------------------------\r\n    \r\n    invoke_custom(0001, 1, \"Mobile.setMobileDirection\", playerId, 7)\r\n    \r\n    -- ... Et voilà toute l'histoire. Elle a ajouté qu'elle allait prendre quelques jours de repos avant de préparer sa rebellion...\r\n    invoke_custom(500, 1, \"bubble\",  playerId, \"quest.sufokia.mercenary.flaqueux.06.29\")\r\n    invoke_custom(500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Presenter\")\r\n    invoke_custom(5000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- **J'y suis peut-être allé{[1*]?e:} un peu fort...\r\n    invoke_custom(5500, 1, \"bubble\",  playerId, \"quest.sufokia.mercenary.flaqueux.06.30\")\r\n    invoke_custom(9500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- J'ignorais que les Flaqueux avaient autant de ressources combatives ! Peut-être qu'à Sufokia, vous commencez à prendre goût au combat.\r\n    invoke_custom(10000, 1, \"bubble\",  playerId, \"quest.sufokia.mercenary.flaqueux.06.31\")\r\n    invoke_custom(18000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- Comme elle est courageuse… Je l’envie.\r\n    invoke_custom(20000, 1, \"Mobile.setMobileAnimation\", flaqueuxId, \"AnimComp-Parler-Neutre\")\r\n    invoke_custom(20000, 1, \"bubble\",  flaqueuxId, \"quest.sufokia.mercenary.flaqueux.06.32\")\r\n    invoke_custom(24500, 1, \"clearBubbles\", flaqueuxId)\r\n    \r\n    -- M-mais je… pense quand même que…\r\n    invoke_custom(25500, 1, \"bubble\",  flaqueuxId, \"quest.sufokia.mercenary.flaqueux.06.33\")\r\n    invoke_custom(29500, 1, \"clearBubbles\", flaqueuxId)\r\n    \r\n    -- Les Flaqueux n’auraient jamais dû quitter leur village d’origine.\r\n    invoke_custom(30500, 1, \"bubble\",  flaqueuxId, \"quest.sufokia.mercenary.flaqueux.06.34\")\r\n    invoke_custom(35500, 1, \"clearBubbles\", flaqueuxId)\r\n    \r\n    -- Je vois. C'est dommage de voir votre peuple se séparer en deux.\r\n    invoke_custom(36000, 1, \"bubble\",  playerId, \"quest.sufokia.mercenary.flaqueux.06.35\")\r\n    invoke_custom(42000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- Oui...\r\n    invoke_custom(43500, 1, \"bubble\",  flaqueuxId, \"quest.sufokia.mercenary.flaqueux.06.36\")\r\n    invoke_custom(45500, 1, \"clearBubbles\", flaqueuxId)\r\n    \r\n    -- J’ai confiance en eux, ils pourront très bien se défendre contre les Taures !\r\n    invoke_custom(46000, 1, \"bubble\",  flaqueuxId, \"quest.sufokia.mercenary.flaqueux.06.37\")\r\n    invoke_custom(52000, 1, \"clearBubbles\", flaqueuxId)\r\n    \r\n    -- Mais beaucoup parmi nous aspirent à revenir sur nos terres d’antan.\r\n    invoke_custom(52500, 1, \"bubble\",  flaqueuxId, \"quest.sufokia.mercenary.flaqueux.06.38\")\r\n    invoke_custom(58500, 1, \"clearBubbles\", flaqueuxId)\r\n    \r\n    -- A vrai dire, je viens d'Amakna. La nation a été rebâtie pour mieux endurer les chaos d'Ogrest, et vous pouvez y reconstruire un village.\r\n    invoke_custom(59000, 1, \"bubble\",  playerId, \"quest.sufokia.mercenary.flaqueux.06.39\")\r\n    invoke_custom(67500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- Oui, nous avons besoin de redécouvrir l’histoire de notre peuple après ces quelques années d'exil.\r\n    invoke_custom(68000, 1, \"bubble\",  flaqueuxId, \"quest.sufokia.mercenary.flaqueux.06.40\")\r\n    invoke_custom(75000, 1, \"clearBubbles\", flaqueuxId)\r\n    \r\n    -- Ceux qui ont trouvé la paix ici peuvent y rester, car ce ne sera pas facile de rassembler les Flaqueux dispersés dans le monde.\r\n    invoke_custom(76000, 1, \"bubble\",  flaqueuxId, \"quest.sufokia.mercenary.flaqueux.06.41\")\r\n    invoke_custom(83500, 1, \"clearBubbles\", flaqueuxId)\r\n    \r\n    -- Et qui sait, peut-être qu’un jour nos deux villages, d'Amakna et de Sufokia, seront amis…\r\n    invoke_custom(84000, 1, \"bubble\",  flaqueuxId, \"quest.sufokia.mercenary.flaqueux.06.42\")\r\n    invoke_custom(91500, 1, \"clearBubbles\", flaqueuxId)\r\n    \r\n    -- Pour ma part, je compte continuer à voyager par la suite !\r\n    invoke_custom(92000, 1, \"bubble\",  flaqueuxId, \"quest.sufokia.mercenary.flaqueux.06.43\")\r\n    invoke_custom(98000, 1, \"clearBubbles\", flaqueuxId)\r\n    \r\n    -- J'ai envie d'explorer le monde entier, même si ça me fait un peu peur.\r\n    invoke_custom(99000, 1, \"bubble\",  flaqueuxId, \"quest.sufokia.mercenary.flaqueux.06.44\")\r\n    invoke_custom(105000, 1, \"clearBubbles\", flaqueuxId)\r\n    \r\n    -- Peut-être que nos chemins se croiseront, alors !\r\n    invoke_custom(106000, 1, \"bubble\",  playerId, \"quest.sufokia.mercenary.flaqueux.06.45\")\r\n    invoke_custom(111000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- Au fait, pour la statue de Percimol ? Elle n’est pas censée être à Amakna ?\r\n    invoke_custom(112000, 1, \"bubble\",  playerId, \"quest.sufokia.mercenary.flaqueux.06.46\")\r\n    invoke_custom(119000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- Ah, celle du village ?\r\n    invoke_custom(120000, 1, \"bubble\",  flaqueuxId, \"quest.sufokia.mercenary.flaqueux.06.47\")\r\n    invoke_custom(124000, 1, \"clearBubbles\", flaqueuxId)\r\n    \r\n    -- Sa place est à Amakna, mais les Flaqueux de Sufokia en ont plus besoin aujourd'hui.\r\n    invoke_custom(125000, 1, \"bubble\",  flaqueuxId, \"quest.sufokia.mercenary.flaqueux.06.48\")\r\n    invoke_custom(131000, 1, \"clearBubbles\", flaqueuxId)\r\n    \r\n    -- Même après toutes ces années, je crois que Percimol veille sur nous.\r\n    invoke_custom(132000, 1, \"bubble\",  flaqueuxId, \"quest.sufokia.mercenary.flaqueux.06.49\")\r\n    invoke_custom(139000, 1, \"clearBubbles\", flaqueuxId)\r\n    \r\n    -- Après tout, tu es venu{[1*]?e:} jusqu'à nous pour nous aider !\r\n    invoke_custom(139500, 1, \"bubble\",  flaqueuxId, \"quest.sufokia.mercenary.flaqueux.06.50\")\r\n    invoke_custom(146000, 1, \"clearBubbles\", flaqueuxId)\r\n    \r\n    -- **Ces Flaqueux savent trouver les mots...\r\n    invoke_custom(146500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Aguiche\")\r\n    invoke_custom(146500, 1, \"bubble\",  playerId, \"quest.sufokia.mercenary.flaqueux.06.51\")\r\n    invoke_custom(151000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- Tu sais énormément de choses pour un Flaqueux, et tu es très courageux.\r\n    invoke_custom(151500, 1, \"bubble\",  playerId, \"quest.sufokia.mercenary.flaqueux.06.52\")\r\n    invoke_custom(158000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- Je te souhaite bonne fortune dans tes aventures.\r\n    invoke_custom(159000, 1, \"bubble\",  playerId, \"quest.sufokia.mercenary.flaqueux.06.53\")\r\n    invoke_custom(164000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(165000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Coucou\")\r\n    invoke_custom(165000, 1, \"Mobile.setMobileAnimation\", flaqueuxId, \"AnimComp01\")\r\n    \r\n    invoke_custom(169000, 1, \"skipCinematic\")\nend\n\n-- [EVENT] Le joueur est téléporté depuis le donjon - Lancement Ciné adieux Flaqueux 2 (pom pas encore rendue)\n-- \nfunction event_2337_19796()\n    local playerId = Context.getLeaderId()\r\n    local flaqueuxId = createActor(122601633, -93, -84, 89, 8, 3, 4)\r\n    \r\n    startCinematicContext(1.4, playerId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\")\r\n    \r\n    ------------------------------\r\n    \r\n    invoke_custom(0001, 1, \"Mobile.setMobileDirection\", playerId, 7)\r\n    \r\n    -- ... Et voilà toute l'histoire. Elle a ajouté qu'elle allait prendre quelques jours de repos avant de préparer sa rebellion...\r\n    invoke_custom(500, 1, \"bubble\",  playerId, \"quest.sufokia.mercenary.flaqueux.06.29\")\r\n    invoke_custom(500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Presenter\")\r\n    invoke_custom(5000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- **J'y suis peut-être allé{[1*]?e:} un peu fort...\r\n    invoke_custom(5500, 1, \"bubble\",  playerId, \"quest.sufokia.mercenary.flaqueux.06.30\")\r\n    invoke_custom(9500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- J'ignorais que les Flaqueux avaient autant de ressources combatives ! Peut-être qu'à Sufokia, vous commencez à prendre goût au combat.\r\n    invoke_custom(10000, 1, \"bubble\",  playerId, \"quest.sufokia.mercenary.flaqueux.06.31\")\r\n    invoke_custom(18000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- Comme elle est courageuse… Je l’envie.\r\n    invoke_custom(20000, 1, \"Mobile.setMobileAnimation\", flaqueuxId, \"AnimComp-Parler-Neutre\")\r\n    invoke_custom(20000, 1, \"bubble\",  flaqueuxId, \"quest.sufokia.mercenary.flaqueux.06.32\")\r\n    invoke_custom(24500, 1, \"clearBubbles\", flaqueuxId)\r\n    \r\n    -- M-mais je… pense quand même que…\r\n    invoke_custom(25500, 1, \"bubble\",  flaqueuxId, \"quest.sufokia.mercenary.flaqueux.06.33\")\r\n    invoke_custom(29500, 1, \"clearBubbles\", flaqueuxId)\r\n    \r\n    -- Les Flaqueux n’auraient jamais dû quitter leur village d’origine.\r\n    invoke_custom(30500, 1, \"bubble\",  flaqueuxId, \"quest.sufokia.mercenary.flaqueux.06.34\")\r\n    invoke_custom(35500, 1, \"clearBubbles\", flaqueuxId)\r\n    \r\n    -- Je vois. C'est dommage de voir votre peuple se séparer en deux.\r\n    invoke_custom(36000, 1, \"bubble\",  playerId, \"quest.sufokia.mercenary.flaqueux.06.35\")\r\n    invoke_custom(42000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- Oui...\r\n    invoke_custom(43500, 1, \"bubble\",  flaqueuxId, \"quest.sufokia.mercenary.flaqueux.06.36\")\r\n    invoke_custom(45500, 1, \"clearBubbles\", flaqueuxId)\r\n    \r\n    -- J’ai confiance en eux, ils pourront très bien se défendre contre les Taures !\r\n    invoke_custom(46000, 1, \"bubble\",  flaqueuxId, \"quest.sufokia.mercenary.flaqueux.06.37\")\r\n    invoke_custom(52000, 1, \"clearBubbles\", flaqueuxId)\r\n    \r\n    -- Mais beaucoup parmi nous aspirent à revenir sur nos terres d’antan.\r\n    invoke_custom(52500, 1, \"bubble\",  flaqueuxId, \"quest.sufokia.mercenary.flaqueux.06.38\")\r\n    invoke_custom(58500, 1, \"clearBubbles\", flaqueuxId)\r\n    \r\n    -- A vrai dire, je viens d'Amakna. La nation a été rebâtie pour mieux endurer les chaos d'Ogrest, et vous pouvez y reconstruire un village.\r\n    invoke_custom(59000, 1, \"bubble\",  playerId, \"quest.sufokia.mercenary.flaqueux.06.39\")\r\n    invoke_custom(67500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- Oui, nous avons besoin de redécouvrir l’histoire de notre peuple après ces quelques années d'exil.\r\n    invoke_custom(68000, 1, \"bubble\",  flaqueuxId, \"quest.sufokia.mercenary.flaqueux.06.40\")\r\n    invoke_custom(75000, 1, \"clearBubbles\", flaqueuxId)\r\n    \r\n    -- Ceux qui ont trouvé la paix ici peuvent y rester, car ce ne sera pas facile de rassembler les Flaqueux dispersés dans le monde.\r\n    invoke_custom(76000, 1, \"bubble\",  flaqueuxId, \"quest.sufokia.mercenary.flaqueux.06.41\")\r\n    invoke_custom(83500, 1, \"clearBubbles\", flaqueuxId)\r\n    \r\n    -- Et qui sait, peut-être qu’un jour nos deux villages, d'Amakna et de Sufokia, seront amis…\r\n    invoke_custom(84000, 1, \"bubble\",  flaqueuxId, \"quest.sufokia.mercenary.flaqueux.06.42\")\r\n    invoke_custom(91500, 1, \"clearBubbles\", flaqueuxId)\r\n    \r\n    -- Pour ma part, je compte continuer à voyager par la suite !\r\n    invoke_custom(92000, 1, \"bubble\",  flaqueuxId, \"quest.sufokia.mercenary.flaqueux.06.43\")\r\n    invoke_custom(98000, 1, \"clearBubbles\", flaqueuxId)\r\n    \r\n    -- J'ai envie d'explorer le monde entier, même si ça me fait un peu peur.\r\n    invoke_custom(99000, 1, \"bubble\",  flaqueuxId, \"quest.sufokia.mercenary.flaqueux.06.44\")\r\n    invoke_custom(105000, 1, \"clearBubbles\", flaqueuxId)\r\n    \r\n    -- Peut-être que nos chemins se croiseront, alors !\r\n    invoke_custom(106000, 1, \"bubble\",  playerId, \"quest.sufokia.mercenary.flaqueux.06.45\")\r\n    invoke_custom(111000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- Au fait, pour la statue de Percimol ? Elle n’est pas censée être à Amakna ?\r\n    invoke_custom(112000, 1, \"bubble\",  playerId, \"quest.sufokia.mercenary.flaqueux.06.46\")\r\n    invoke_custom(119000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- Ah, celle du village ?\r\n    invoke_custom(120000, 1, \"bubble\",  flaqueuxId, \"quest.sufokia.mercenary.flaqueux.06.47\")\r\n    invoke_custom(124000, 1, \"clearBubbles\", flaqueuxId)\r\n    \r\n    -- Sa place est à Amakna, mais les Flaqueux de Sufokia en ont plus besoin aujourd'hui.\r\n    invoke_custom(125000, 1, \"bubble\",  flaqueuxId, \"quest.sufokia.mercenary.flaqueux.06.48\")\r\n    invoke_custom(131000, 1, \"clearBubbles\", flaqueuxId)\r\n    \r\n    -- Même après toutes ces années, je crois que Percimol veille sur nous.\r\n    invoke_custom(132000, 1, \"bubble\",  flaqueuxId, \"quest.sufokia.mercenary.flaqueux.06.49\")\r\n    invoke_custom(139000, 1, \"clearBubbles\", flaqueuxId)\r\n    \r\n    -- Après tout, tu es venu{[1*]?e:} jusqu'à nous pour nous aider !\r\n    invoke_custom(139500, 1, \"bubble\",  flaqueuxId, \"quest.sufokia.mercenary.flaqueux.06.50\")\r\n    invoke_custom(146000, 1, \"clearBubbles\", flaqueuxId)\r\n    \r\n    -- **Ces Flaqueux savent trouver les mots...\r\n    invoke_custom(146500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Aguiche\")\r\n    invoke_custom(146500, 1, \"bubble\",  playerId, \"quest.sufokia.mercenary.flaqueux.06.51\")\r\n    invoke_custom(151000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- Tiens, c'est la Pom d'or de la Flaque Royale, elle m'a demandé de te la donner.\r\n    invoke_custom(151500, 1, \"bubble\",  playerId, \"quest.sufokia.mercenary.flaqueux.06.54\")\r\n    invoke_custom(157500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- Je pense plutôt que c'est à toi qu'elle revient !\r\n    invoke_custom(158000, 1, \"bubble\",  flaqueuxId, \"quest.sufokia.mercenary.flaqueux.06.55\")\r\n    invoke_custom(164000, 1, \"clearBubbles\", flaqueuxId)\r\n    \r\n    -- Tu peux la garder, tu as énormément aidé le peuple Flaqueux.\r\n    invoke_custom(165000, 1, \"bubble\",  flaqueuxId, \"quest.sufokia.mercenary.flaqueux.06.56\")\r\n    invoke_custom(171000, 1, \"clearBubbles\", flaqueuxId)\r\n    \r\n    -- Tu sais énormément de choses pour un Flaqueux, et tu es très courageux.\r\n    invoke_custom(171500, 1, \"bubble\",  playerId, \"quest.sufokia.mercenary.flaqueux.06.52\")\r\n    invoke_custom(177000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- Je te souhaite bonne fortune dans tes aventures.\r\n    invoke_custom(178000, 1, \"bubble\",  playerId, \"quest.sufokia.mercenary.flaqueux.06.53\")\r\n    invoke_custom(183000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(184000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Coucou\")\r\n    invoke_custom(184000, 1, \"Mobile.setMobileAnimation\", flaqueuxId, \"AnimComp01\")\r\n    \r\n    invoke_custom(187000, 1, \"skipCinematic\")\nend\n\n-- [EVENT] Fin Ciné adieux Flaqueux - Le joueur valide la quête (ACH 4234 OBJ 8763)\n-- \nfunction event_2337_19797()\n    \nend\n\n-- [EVENT] Le joueur répare le tonneau du Village - Lancement Ciné flaqueux du village\n-- \nfunction event_2337_19798()\n    local playerId = Context.getLeaderId()\r\n    local flaqueuxId = createActor(122601239, -102, -87, 90, 8, 1, 4)\r\n    local flaqueuseId = createActor(122601238, -101, -87, 90, 8, 5, 4)\r\n    \r\n    startCinematicContext(1.4, playerId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\")\r\n    \r\n    ------------------------------\r\n    \r\n    Mobile.setMobileVisible(flaqueuxId, false)\r\n    Mobile.setMobileVisible(flaqueuseId, false)\r\n    \r\n    -- **Fiouh ! Je vais prendre une petite pause...\r\n    invoke_custom(500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Fievre\")\r\n    invoke_custom(500, 1, \"bubble\",  playerId, \"quest.sufokia.mercenary.flaqueux.07.01\")\r\n    invoke_custom(5000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- **C'est un charmant petit village ici.\r\n    invoke_custom(5500, 1, \"bubble\",  playerId, \"quest.sufokia.mercenary.flaqueux.07.02\")\r\n    invoke_custom(10000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(11000, 1, \"Camera.attachCameraToMobile\", flaqueuxId)\r\n    invoke_custom(11000, 1, \"Mobile.setMobileVisible\", flaqueuxId, true)\r\n    invoke_custom(11000, 1, \"Mobile.setMobileVisible\", flaqueuseId, true)\r\n    \r\n    -- Allez, on doit retourner au boulot !\r\n    invoke_custom(12000, 1, \"bubble\",  flaqueuxId, \"quest.sufokia.mercenary.flaqueux.07.03\")\r\n    invoke_custom(17000, 1, \"clearBubbles\", flaqueuxId)\r\n    \r\n    -- Notre ancienne vie à Amakna me manque...\r\n    invoke_custom(19000, 1, \"bubble\",  flaqueuseId, \"quest.sufokia.mercenary.flaqueux.07.04\")\r\n    invoke_custom(23000, 1, \"clearBubbles\", flaqueuseId)\r\n    \r\n    -- A moi aussi, mais depuis que nous sommes à Sufokia, la Flaque Royale veille sur nous !\r\n    invoke_custom(23500, 1, \"bubble\",  flaqueuxId, \"quest.sufokia.mercenary.flaqueux.07.05\")\r\n    invoke_custom(30500, 1, \"clearBubbles\", flaqueuxId)\r\n    \r\n    -- J-je ne suis pas certaine qu'il y ait de l'avenir pour nous ici...\r\n    invoke_custom(31000, 1, \"bubble\",  flaqueuseId, \"quest.sufokia.mercenary.flaqueux.07.06\")\r\n    invoke_custom(36500, 1, \"clearBubbles\", flaqueuseId)\r\n    \r\n    -- En même temps nous sommes persécutés où que nous allions.\r\n    invoke_custom(37000, 1, \"bubble\",  flaqueuseId, \"quest.sufokia.mercenary.flaqueux.07.07\")\r\n    invoke_custom(42500, 1, \"clearBubbles\", flaqueuseId)\r\n    \r\n    -- Tant que nous sommes ensemble, je serai heureux !\r\n    invoke_custom(43000, 1, \"bubble\",  flaqueuxId, \"quest.sufokia.mercenary.flaqueux.07.08\")\r\n    invoke_custom(47500, 1, \"clearBubbles\", flaqueuxId)\r\n    \r\n    -- Je n'en suis pas si sûre...\r\n    invoke_custom(48000, 1, \"bubble\",  flaqueuseId, \"quest.sufokia.mercenary.flaqueux.07.09\")\r\n    invoke_custom(53000, 1, \"clearBubbles\", flaqueuseId)\r\n    \r\n    -- **N'empêche que j'aimerais bien manger plus de Poms...\r\n    invoke_custom(53000, 1, \"bubble\",  flaqueuseId, \"quest.sufokia.mercenary.flaqueux.07.10\")\r\n    invoke_custom(59000, 1, \"clearBubbles\", flaqueuseId)\r\n    invoke_custom(59000, 1, \"Camera.attachCameraToMobile\", playerId)\r\n    \r\n    ------------------------------\r\n    \r\n    invoke_custom(60000, 1, \"skipCinematic\")\nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_2337_19748","event_2337_20185","event_2337_19749","event_2337_19759","event_2337_19760","event_2337_19774","event_2337_19775","event_2337_19777","event_2337_19789","event_2337_19779","event_2337_19778","event_2337_19785","event_2337_19791","event_2337_19792","event_2337_19796","event_2337_19797","event_2337_19798"],"quest_calls":[],"dialogue_calls":[]},"scenario/2339.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\n\n-- [INIT] Variables\n-- \nfunction event_2339_19810()\n    \nend\n\n-- [INIT] Le joueur entre dans l'instance - Inscription au scénario\n-- \nfunction event_2339_19807()\n    \nend\n\n-- [EVENT] Le joueur parle au PNJ Odgard - Cinématique Moogrr Force (OBJ 8783 ACH 4251)\n-- \nfunction event_2339_19804(npcOdgard, npcPublicUn, npcPublicDeux, npcPublicTrois, npcPublicQuatre)\n    \t----------------------------- RECUPERATIONS DES INFOS JOUEUR --------------------------\r\n    \r\n    \tlocal playerId = Context.getLeaderId()\r\n    \tlocal playerX, playerY, playerZ = Mobile.getMobilePosition(playerId)\r\n    \r\n    \r\n    \t----------------------------- INITIALISATION DES MOOGRRS ET DES CHARIOTS --------------------------\r\n    \r\n    \tlocal PaquooretteId = createActor(121801221, 89, 64, 0, 8, 7, 4)\r\n    \tlocal ChariotUn = createActor(194704708, 89, 65, 0, 8, 7, 4)\r\n    \tlocal ChariotDeux = createActor(194704708, 89, 66, 0, 8, 7, 4)\r\n    \tlocal ChariotTrois = createActor(194704708, 89, 67, 0, 8, 7, 4)\r\n    \r\n    \tlocal MoogrrId = createActor(121801221, 90, 64, 0, 8, 7, 4)\r\n    \tlocal ChariotQuatre = createActor(194704708, 90, 65, 0, 8, 7, 4)\r\n    \tlocal ChariotCinq = createActor(194704708, 90, 66, 0, 8, 7, 4)\r\n    \tlocal ChariotSix = createActor(194704708, 90, 67, 0, 8, 7, 4)\r\n    \r\n    \tlocal Magnoolia = createActor(121801221, 91, 64, 0, 8, 7, 4)\r\n    \tlocal ChariotSept = createActor(194704708, 91, 65, 0, 8, 7, 4)\r\n    \tlocal ChariotHuit = createActor(194704708, 91, 66, 0, 8, 7, 4)\r\n    \tlocal ChariotNeuf = createActor(194704708, 91, 67, 0, 8, 7, 4)\r\n    \r\n    \r\n    \r\n    \t----------------------------- INITIALISATION DES PNJ --------------------------\r\n    \r\n    \tlocal npcOdgardId = toLong(npcOdgard)\r\n    \tlocal mobileOdgardId = createActor(10, 88, 59, 0, 8, 1, 7, npcOdgardId)\r\n    \r\n    \tlocal mobileJoedId = createActor(30, 87, 62, 0, 8, 1, 6)\r\n    \tlocal mobileJouneId = createActor(80, 92, 55, 0, 8, 5, 6)\r\n    \tlocal mobileAlmangroId = createActor(110, 87, 57, 0, 8, 1, 6)\r\n    \tlocal mobilePectorId = createActor(10, 88, 55, 0, 8, 1, 6)\r\n    \tlocal mobileHabitantUnID = createActor(10, 93, 64, 0, 8, 5, 6)\r\n    \tlocal mobileHabitantDeuxId = createActor(91, 94, 60, 0, 8, 5, 6)\r\n    \tlocal mobileHabitantTroisId = createActor(81, 94, 59, 0, 8, 5, 6)\r\n    \tlocal mobileHabitantQuatreId = createActor(11, 80, 86, 0, 8, 1, 6)\r\n    \tlocal mobileHabitantCinqId = createActor(10, 93, 54, 0, 8, 5, 6)\r\n    \t\r\n    \tlocal npcPublicUnId = toLong(npcPublicUn)\r\n    \tlocal npcPublicDeuxId = toLong(npcPublicDeux)\r\n    \tlocal npcPublicTroisId = toLong(npcPublicTrois)\r\n    \tlocal npcPublicQuatreId = toLong(npcPublicQuatre)\r\n    \r\n    \r\n    \t----------------------------- PERSONNALISATION DES PNJ --------------------------\r\n    \r\n    \tActor.equip(mobileJoedId, \"200300001\", \"CHEVEUXCUSTOM\")\r\n    \tActor.equip(mobileJoedId, \"210300004\", \"VETEMENTCUSTOM\")\r\n    \tActor.equip(mobileJoedId, \"13410394\", \"Chapeau\")\r\n    \tMobile.setPartColor(mobileJoedId, \"Pupille\", 0.00, 0.00, 0.00, 1)\r\n    \tMobile.setPartColor(mobileJoedId, \"Peau\", 0.96, 0.72, 0.48, 1)\r\n    \tMobile.setPartColor(mobileJoedId, \"Cheveux\", 0.88, 0.88, 0.88, 1)\r\n    \r\n    \tActor.equip(mobileJouneId, \"200800003\", \"CHEVEUXCUSTOM\")\r\n    \tActor.equip(mobileJouneId, \"211400002\", \"VETEMENTCUSTOM\")\r\n    \tActor.equip(mobileJouneId, \"13410394\", \"Chapeau\")\r\n    \tMobile.setPartColor(mobileJouneId, \"Pupille\", 0.55, 0.55, 0.55, 1)\r\n    \tMobile.setPartColor(mobileJouneId, \"Peau\", 1.00, 0.84, 0.67, 1)\r\n    \tMobile.setPartColor(mobileJouneId, \"Cheveux\", 0.91, 0.84, 0.23, 1)\r\n    \r\n    \tActor.equip(mobileAlmangroId, \"201100003\", \"CHEVEUXCUSTOM\")\r\n    \tActor.equip(mobileAlmangroId, \"210600001\", \"VETEMENTCUSTOM\")\r\n    \tActor.equip(mobileAlmangroId, \"13410394\", \"Chapeau\")\r\n    \tMobile.setPartColor(mobileAlmangroId, \"Pupille\", 0.00, 0.00, 0.00, 1)\r\n    \tMobile.setPartColor(mobileAlmangroId, \"Peau\", 0.50, 0.34, 0.09, 1)\r\n    \tMobile.setPartColor(mobileAlmangroId, \"Cheveux\", 0.19, 0.19, 0.19, 1)\r\n    \r\n    \tActor.equip(mobilePectorId, \"200100001\", \"CHEVEUXCUSTOM\")\r\n    \tActor.equip(mobilePectorId, \"210100002\", \"VETEMENTCUSTOM\")\r\n    \tActor.equip(mobilePectorId, \"13410394\", \"Chapeau\")\r\n    \tMobile.setPartColor(mobilePectorId, \"Pupille\", 1.00, 0.53, 0.22, 1)\r\n    \tMobile.setPartColor(mobilePectorId, \"Peau\", 1.00, 0.73, 0.45, 1)\r\n    \tMobile.setPartColor(mobilePectorId, \"Cheveux\", 0.75, 0.45, 0.15, 1)\r\n    \r\n    \tActor.equip(mobileHabitantUnID, \"200100001\", \"CHEVEUXCUSTOM\")\r\n    \tActor.equip(mobileHabitantUnID, \"210600001\", \"VETEMENTCUSTOM\")\r\n    \tActor.equip(mobileHabitantUnID, \"13410394\", \"Chapeau\")\r\n    \tMobile.setPartColor(mobileHabitantUnID, \"Pupille\", 1.00, 0.53, 0.22, 1)\r\n    \tMobile.setPartColor(mobileHabitantUnID, \"Peau\", 0.50, 0.34, 0.09, 1)\r\n    \tMobile.setPartColor(mobileHabitantUnID, \"Cheveux\", 0.75, 0.45, 0.15, 1)\r\n    \r\n    \tActor.equip(mobileHabitantDeuxId, \"200100001\", \"CHEVEUXCUSTOM\")\r\n    \tActor.equip(mobileHabitantDeuxId, \"210300004\", \"VETEMENTCUSTOM\")\r\n    \tActor.equip(mobileHabitantDeuxId, \"13410394\", \"Chapeau\")\r\n    \tMobile.setPartColor(mobileHabitantDeuxId, \"Pupille\", 1.00, 0.53, 0.22, 1)\r\n    \tMobile.setPartColor(mobileHabitantDeuxId, \"Peau\", 1.00, 0.84, 0.67, 1)\r\n    \tMobile.setPartColor(mobileHabitantDeuxId, \"Cheveux\", 0.75, 0.45, 0.15, 1)\r\n    \r\n    \tActor.equi