Position\", playerId, 87, 82, 0)\r\n    \tinvoke_custom(500, 1, \"Mobile.setMobileDirection\", playerId, 5)\r\n    \tinvoke_custom(550, 1, \"Mobile.setMobileVisible\", npcJoeId, false)\r\n    \r\n    \tinvoke_custom(800, 1, \"UI.displayWideScreenBand\", true, 20, 500)\r\n    \r\n    \r\n    \r\n    \t----------------------------- DIALOGUES DE JOE --------------------------\r\n    \r\n    \t-- Ma vie l'a plus aucun sens sans l'prix Mooligrr ... // IL AVANCE UN PEU PUIS S'ARRETTE\r\n    \tinvoke_custom(1000, 1, \"bubble\", mobileJoeId, \"quest.amakna.mercenary.moogrr.04.01\")\r\n    \tinvoke_custom(1000, 1, \"Mobile.setMobileAnimation\", mobileJoeId, \"AnimEmote-Defaite\")\r\n    \tinvoke_custom(4000, 1, \"Mobile.setMobileAnimation\", mobileJoeId, \"AnimEmote-Defaite\")\r\n    \tinvoke_custom(7000, 1, \"clearBubbles\", mobileJoeId)\r\n    \r\n    \tinvoke_custom(1200, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Help\")\r\n    \tinvoke_custom(4200, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Calmer\")\r\n    \tinvoke_custom(7000, 1, \"Mobile.setMobileDirection\", playerId, 3)\r\n    \r\n    \tinvoke_custom(8000, 1, \"Mobile.moveMobile\", mobileJoeId, 86, 85, 0, \"Mobile.setMobileDirection\", mobileJoeId, 1)\r\n    \tinvoke_custom(10000, 1, \"Mobile.moveMobile\", mobileJoeId, 85, 85, 0, \"Mobile.setMobileDirection\", mobileJoeId, 3)\r\n    \tinvoke_custom(10800, 1, \"Mobile.moveMobile\", mobileJoeId, 85, 86, 0, \"Mobile.setMobileDirection\", mobileJoeId, 5)\r\n    \r\n    \t-- J'me fais vieux d'toute façon ... // IL S'ARRETTE DEVANT UNE CAISSE\r\n    \tinvoke_custom(9500, 1, \"bubble\", mobileJoeId, \"quest.amakna.mercenary.moogrr.04.02\")\r\n    \tinvoke_custom(9500, 1, \"Mobile.setMobileAnimation\", mobileJoeId, \"AnimEmote-Defaite\")\r\n    \tinvoke_custom(13500, 1, \"clearBubbles\", mobileJoeId)\r\n    \r\n    \r\n    \t-- PLAYER Il se déplace vers Joe\r\n    \tinvoke_custom(8000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmoteMarket-HausseEpaules\")\r\n    \tinvoke_custom(14000, 1, \"Mobile.moveMobile\", playerId, 86, 87, 0, \"Mobile.setMobileDirection\", playerId, 5)\r\n    \r\n    \r\n    \r\n    \t-- Personne ne m'regrettera ... // IL SAUTE SUR UNE CAISSE\r\n    \tinvoke_custom(15500, 1, \"bubble\", mobileJoeId, \"quest.amakna.mercenary.moogrr.04.03\")\r\n    \tinvoke_custom(15500, 1, \"Mobile.setMobileAnimation\", mobileJoeId, \"AnimEmote-Defaite\")\r\n    \tinvoke_custom(19500, 1, \"clearBubbles\", mobileJoeId)\r\n    \tinvoke_custom(19500, 1, \"Mobile.moveMobile\", mobileJoeId, 83, 86, 7, \"Mobile.setMobileDirection\", mobileJoeId, 3)\r\n    \r\n    \r\n    \t-- PLAYER **Je ne savais pas que les vieux paysans étudiaient les arts dramatiques...\r\n    \tinvoke_custom(19000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    \tinvoke_custom(19000, 1, \"bubble\", playerId, \"quest.amakna.mercenary.moogrr.04.04\")\r\n    \tinvoke_custom(25000, 1, \"clearBubbles\", playerId)\r\n    \r\n    \r\n    \r\n    \t-- Non, non ne m'retenez pas...\r\n    \tinvoke_custom(24000, 1, \"bubble\", mobileJoeId, \"quest.amakna.mercenary.moogrr.04.05\")\r\n    \tinvoke_custom(24000, 1, \"Mobile.setMobileAnimation\", mobileJoeId, \"AnimEmote-Defaite\")\r\n    \tinvoke_custom(28000, 1, \"clearBubbles\", mobileJoeId)\r\n    \r\n    \r\n    \r\n    \t-- PLAYER Ce n'est qu'un prix Joe !\r\n    \tinvoke_custom(28000, 1, \"bubble\", playerId, \"quest.amakna.mercenary.moogrr.04.06\")\r\n    \tinvoke_custom(28000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Calmer\")\r\n    \tinvoke_custom(32000, 1, \"clearBubbles\", playerId)\r\n    \r\n    \r\n    \r\n    \t-- ... J'vais vraiment sauter hein ! J'sais pas nager moué !\r\n    \tinvoke_custom(32000, 1, \"bubble\", mobileJoeId, \"quest.amakna.mercenary.moogrr.04.07\")\r\n    \tinvoke_custom(32000, 1, \"Mobile.setMobileAnimation\", mobileJoeId, \"AnimEmote-Help\")\r\n    \tinvoke_custom(37000, 1, \"clearBubbles\", mobileJoeId)\r\n    \r\n    \r\n    \r\n    \t-- PLAYER C'est bon, c'est bon ... j'ai compris je vais le récupérer votre prix Mooligrr.\r\n    \tinvoke_custom(37000, 1, \"bubble\", playerId, \"quest.amakna.mercenary.moogrr.04.08\")\r\n    \tinvoke_custom(37000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Fievre\")\r\n    \tinvoke_custom(43000, 1, \"clearBubbles\", playerId)\r\n    \r\n    \r\n    \r\n    \t-- C'est vrai c'mensonge ?!\r\n    \tinvoke_custom(42000, 1, \"Mobile.moveMobile\", mobileJoeId, 85, 87, 0, \"Mobile.setMobileDirection\", mobileJoeId, 1)\r\n    \tinvoke_custom(44000, 1, \"Mobile.setMobileAnimation\", mobileJoeId, \"AnimEmote-Pointer\")\r\n    \tinvoke_custom(44000, 1, \"bubble\", mobileJoeId, \"quest.amakna.mercenary.moogrr.04.09\")\r\n    \tinvoke_custom(48000, 1, \"clearBubbles\", mobileJoeId)\r\n    \r\n    \r\n    \r\n    \t-- PLAYER Je n'ai pas vraiment le choix on dirait ...\r\n    \tinvoke_custom(48000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmoteMarket-HausseEpaules\")\r\n    \tinvoke_custom(48000, 1, \"bubble\", playerId, \"quest.amakna.mercenary.moogrr.04.10\")\r\n    \tinvoke_custom(53000, 1, \"clearBubbles\", playerId)\r\n    \r\n    \r\n    \r\n    \t-- Merci l'ami, j'te revaudrai ça, 'faut entrainer Kamoomille pour la prochaine épreuve !\r\n    \tinvoke_custom(53000, 1, \"bubble\", mobileJoeId, \"quest.amakna.mercenary.moogrr.04.11\")\r\n    \tinvoke_custom(53000, 1, \"Mobile.setMobileAnimation\", mobileJoeId, \"AnimEmoteMarket-LeverMain\")\r\n    \tinvoke_custom(59000, 1, \"clearBubbles\", mobileJoeId)\r\n    \r\n    \r\n    \t-- PLAYER **Il a bon pied bon oeil le vieux... Ma bonté me perdra !\r\n    \r\n    \tinvoke_custom(59000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    \tinvoke_custom(59000, 1, \"bubble\", playerId, \"quest.amakna.mercenary.moogrr.04.12\")\r\n    \tinvoke_custom(64000, 1, \"clearBubbles\", playerId)\r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \t----------------------------- FIN DE CINEMATIQUE --------------------------\r\n    \r\n    \tinvoke_custom(64500, 1, \"Mobile.moveMobile\", mobileJoeId, 87, 81, 0, \"Mobile.setMobileDirection\", mobileJoeId, 1)\r\n    \tinvoke_custom(64500, 1, \"Mobile.moveMobile\", playerId, playerX, playerY, playerZ)\r\n    \r\n    \tinvoke_custom(65000, 1, \"UI.displayWideScreenBand\", true, 100, 300)\r\n    \tinvoke_custom(66000, 1, \"Mobile.setMobileVisible\", npcJoeId, true)\r\n    \tinvoke_custom(67999, 1, \"UI.displayWideScreenBand\", true, 25, 300)\r\n    \r\n    \tinvoke(68000, 1, \"skipCinematic\", 19812)\r\n            \r\nend\n\n-- [EVENT] Le joueur parle au PNJ Odgard - Lancement Mini-Jeu Beauté\n-- \nfunction event_2339_19852()\n    \nend\n\n-- [EVENT] Mini-Jeu Beauté démarre - Pose des zones\n-- \nfunction event_2339_20124()\n    \nend\n\n-- [EVENT] Mini-Jeu Beauté se Termine - Save du skin de la Moogrr\n-- \nfunction event_2339_19854(local_fight_id, local_group_id, local_monster_id, state_cloche, state_grelot, state_collier, state_corne_petite, state_corne_normale, state_corne_grande, state_color_kokoa, state_color_milkou, state_color_scaramel)\n    trace(\"state_cloche\", state_cloche)\r\n    trace(\"state_grelot\", state_grelot)\r\n    trace(\"state_collier\", state_collier)\r\n    trace(\"state_corne_petite\", state_corne_petite)\r\n    trace(\"state_corne_normale\", state_corne_normale)\r\n    trace(\"state_corne_grande\", state_corne_grande)\r\n    trace(\"state_color_kokoa\", state_color_kokoa)\r\n    trace(\"state_color_milkou\", state_color_milkou)\r\n    trace(\"state_color_scaramel\", state_color_scaramel)\nend\n\n-- [EVENT] Victoire du Mini-Jeu Beauté (OBJ 8804 ACH 4252)\n-- \nfunction event_2339_19853(local_fight_id, local_group_id, local_monster_id, state_cloche, state_grelot, state_collier, state_corne_petite, state_corne_normale, state_corne_grande, state_color_kokoa, state_color_milkou, state_color_scaramel, npcOdgard)\n    \t----------------------------- INITIALISATION DE