, 1, \"Mobile.setMobileAnimation\", mobileOdgardId, \"AnimEmote-Rire\")\r\n    \tinvoke_custom(30000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Rire\")\r\n    \r\n    \r\n    \t----------------------------- FIN DE CINEMATIQUE --------------------------\r\n    \r\n    \tinvoke_custom(34500, 1, \"UI.displayWideScreenBand\", true, 100, 300)\r\n    \tinvoke_custom(34900, 1, \"Mobile.setMobilePosition\", playerId, playerX, playerY, playerZ)\r\n    \tinvoke_custom(35000, 1, \"Mobile.setMobileVisible\", npcOdgardId, true)\r\n    \tinvoke_custom(35100, 1, \"Mobile.setMobileVisible\", npcPublicUnId, true)\r\n    \tinvoke_custom(35200, 1, \"Mobile.setMobileVisible\", npcPublicDeuxId, true)\r\n    \tinvoke_custom(35300, 1, \"Mobile.setMobileVisible\", npcPublicTroisId, true)\r\n    \tinvoke_custom(35400, 1, \"Mobile.setMobileVisible\", npcPublicQuatreId, true)\r\n    \tinvoke_custom(35500, 1, \"Mobile.setMobileVisible\", npcPublicCinqId, true)\r\n    \tinvoke_custom(35600, 1, \"Mobile.setMobileVisible\", npcPublicSixId, true)\r\n    \tinvoke_custom(35700, 1, \"Mobile.setMobileVisible\", npcPublicSeptId, true)\r\n    \tinvoke_custom(35800, 1, \"Mobile.setMobileVisible\", npcPublicHuitId, true)\r\n    \r\n    \tinvoke_custom(36900, 1, \"UI.displayWideScreenBand\", true, 25, 300)\r\n    \tinvoke_custom(37000, 1, \"customSkip\")\nend\n\n-- [EVENT] Cinématique avant d'aller au Donjon Moogrr\n-- \nfunction event_2339_19893(npcJoe)\n    \t----------------------------- RECUPERATIONS DES INFOS JOUEUR --------------------------\r\n    \r\n    \tlocal playerId = Context.getLeaderId()\r\n    \tlocal playerX, playerY, playerZ = Mobile.getMobilePosition(playerId)\r\n    \r\n    \r\n    \t----------------------------- INITIALISATION DES PNJ --------------------------\r\n    \r\n    \tlocal npcJoeId = toLong(npcJoe)\r\n    \tlocal mobileJoeId = createActor(30, 86, 81, 0, 8, 1, 7, npcJoeId)\r\n    \tlocal mobileJouneId = createActor(80, 105, 83, 0, 8, 5, 6)\r\n    \r\n    \r\n    \t----------------------------- PERSONNALISATION DES PNJ --------------------------\r\n    \r\n    \tActor.equip(mobileJouneId, \"200800003\", \"CHEVEUXCUSTOM\")\r\n    \tActor.equip(mobileJouneId, \"211400002\", \"VETEMENTCUSTOM\")\r\n    \tActor.equip(mobileJouneId, \"13410394\", \"Chapeau\")\r\n    \tMobile.setPartColor(mobileJouneId, \"Pupille\", 0.55, 0.55, 0.55, 1)\r\n    \tMobile.setPartColor(mobileJouneId, \"Peau\", 1.00, 0.84, 0.67, 1)\r\n    \tMobile.setPartColor(mobileJouneId, \"Cheveux\", 0.91, 0.84, 0.23, 1)\r\n    \r\n    \t----------------------------- SKIP DE CINEMATIQUE PAR LE BOUTON --------------------------\r\n    \tfunction customSkip()\r\n    \t\tMobile.setMobilePosition(playerId, playerX, playerY, playerZ)\r\n    \t\tMobile.setMobileVisible(npcJoeId, true)\r\n       \t\tUI.displayWideScreenBand(true, 25, 300)\r\n    \t\tskipCinematic(19893)\r\n    \tend\r\n    \r\n    \r\n    \t----------------------------- DEBUT DE CINEMATIQUE --------------------------\r\n    \r\n    \tstartCinematicContext(1.3, playerId)\r\n    \tUI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"customSkip\")\r\n    \r\n    \tinvoke_custom(150, 1, \"Mobile.setMobileVisible\", npcJoeId, false)\r\n    \r\n    \r\n    \t----------------------------- DIALOGUES --------------------------\r\n    \r\n    \t-- C'est vrai, maintenant qu'vous l'dites, le prix y l'a pas la même saveur sans Moorghueurite avec moué...\r\n    \tinvoke_custom(1000, 1, \"bubble\", mobileJoeId, \"quest.amakna.mercenary.moogrr.06.01\")\r\n    \tinvoke_custom(1000, 1, \"Mobile.setMobileAnimation\", mobileJoeId, \"AnimEmote-GratteGratte\")\r\n    \r\n    \t-- Enfin je dis ça mais je n'ai pas plus d'informations par rapport à avant...\r\n    \tinvoke_custom(6800, 1, \"clearBubbles\", mobileJoeId)\r\n    \tinvoke_custom(7000, 1, \"bubble\", playerId, \"quest.amakna.mercenary.moogrr.06.02\")\r\n    \tinvoke_custom(7000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmoteMarket-HausseEpaules\")\r\n    \r\n    \t-- Je pense juste que ce n'est pas un autre fermier qui a fait le coup.\r\n    \tinvoke_custom(11800, 1, \"clearBubbles\", playerId)\r\n    \tinvoke_custom(12000, 1, \"bubble\", playerId, \"quest.amakna.mercenary.moogrr.06.03\")\r\n    \tinvoke_custom(12000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Non\")\r\n    \r\n    \t-- Moué d'ailleurs à c'propos fallait que j'te dise...\r\n    \tinvoke_custom(15800, 1, \"clearBubbles\", playerId)\r\n    \tinvoke_custom(16000, 1, \"bubble\", mobileJoeId, \"quest.amakna.mercenary.moogrr.06.04\")\r\n    \tinvoke_custom(16000, 1, \"Mobile.setMobileAnimation\", mobileJoeId, \"AnimEmote-GratteGratte\")\r\n    \r\n    \t-- Joe ! Joe !!!\r\n    \tinvoke_custom(18000, 1, \"bubble\", mobileJouneId, \"quest.amakna.mercenary.moogrr.06.05\")\r\n    \tinvoke_custom(18800, 1, \"clearBubbles\", mobileJoeId)\r\n    \tinvoke_custom(18500, 1, \"Mobile.setMobileDirection\", playerId, 1)\r\n    \r\n    \t-- J'étais allé chercher du matériel dans l'étable abandonnée mais elle est remplie d'Moogrrs !\r\n    \tinvoke_custom(19800, 1, \"clearBubbles\", mobileJouneId)\r\n    \tinvoke_custom(20000, 1, \"bubble\", mobileJouneId, \"quest.amakna.mercenary.moogrr.06.06\")\r\n    \tinvoke_custom(20000, 1, \"Mobile.setMobileAnimation\", mobileJouneId, \"AnimEmote-Help\")\r\n    \r\n    \t-- Il y avait aussi une énorme Moogrr rouge, on dirait qu'c'est elle qu'a ramené ses copines.\r\n    \tinvoke_custom(24800, 1, \"clearBubbles\", mobileJouneId)\r\n    \tinvoke_custom(25000, 1, \"bubble\", mobileJouneId, \"quest.amakna.mercenary.moogrr.06.07\")\r\n    \tinvoke_custom(25000, 1, \"Mobile.setMobileAnimation\", mobileJouneId, \"AnimEmote-GratteGratte\")\r\n    \r\n    \t-- Moorghueurite est p't-êt' avec ces Moogrrs, tu peux aller vérifier p'tit{[1*]?e:} ? \r\n    \tinvoke_custom(29800, 1, \"clearBubbles\", mobileJouneId)\r\n    \tinvoke_custom(30000, 1, \"bubble\", mobileJoeId, \"quest.amakna.mercenary.moogrr.06.08\")\r\n    \tinvoke_custom(30000, 1, \"Mobile.setMobileAnimation\", mobileJoeId, \"AnimEmoteMarket-LeverMain\")\r\n    \r\n    \t-- C'est la seule piste qu'il nous reste de toute façon, ça vaut le coup d'essayer.\r\n    \tinvoke_custom(34800, 1, \"clearBubbles\", mobileJoeId)\r\n    \tinvoke_custom(35000, 1, \"bubble\", playerId, \"quest.amakna.mercenary.moogrr.06.09\")\r\n    \tinvoke_custom(35000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmoteMarket-HausseEpaules\")\r\n    \r\n    \t-- Merci aventuri{[1*]?ère:er} je vais prévenir les aut' de pas y retourner pour l'moment !\r\n    \tinvoke_custom(39800, 1, \"clearBubbles\", playerId)\r\n    \tinvoke_custom(40000, 1, \"bubble\", mobileJouneId, \"quest.amakna.mercenary.moogrr.06.10\")\r\n    \tinvoke_custom(40000, 1, \"Mobile.setMobileAnimation\", mobileJouneId, \"AnimEmote-Pouce\")\r\n    \tinvoke_custom(45000, 1, \"Mobile.moveMobile\", mobileJouneId, 105, 83, 0, \"Mobile.setMobileDirection\", mobileJouneId, 1)\r\n    \r\n    \t-----------------------------  ACTIONS --------------------------\r\n    \r\n    \tinvoke_custom(14000, 1, \"Mobile.moveMobile\", mobileJouneId, 90, 81, 0, \"Mobile.setMobileDirection\", mobileJouneId, 5)\r\n    \r\n    \t----------------------------- FIN DE CINEMATIQUE --------------------------\r\n    \r\n    \tinvoke_custom(48000, 1, \"Mobile.moveMobile\", playerId, playerX, playerY, playerZ)\r\n    \tinvoke_custom(48950, 1, \"Mobile.setMobileVisible\", npcJoeId, true)\r\n    \t\r\n    \tinvoke(49000, 1, \"skipCinematic\", 19893)\nend\n\n-- [EVENT] Retour de Moorgheurite\n-- \nfunction event_2339_19901(npcJoe)\n       \t----------------------------- RECUPERATIONS DES INFOS JOUEUR --------------------------\r\n        \r\n        \tlocal playerId = Context.getLeaderId()\r\n        \tlocal playerX, playerY, playerZ = Mobile.getMobilePosition(playerId)\r\n        \r\n        \r\n        \t----------------------------- INITIALISATION DES PNJ --------------------------\r\n        \r\n        \tlocal npcJoeId = toLong(npcJoe)\r\n        \tlocal mobileJoeId = createActor(30, 86, 81, 0, 8, 1, 7, npcJoeId)\r\n        \tlocal mobileMoorghueurite = createActor(121801221, 105, 81, 0, 8, 1, 7)\r\n        \tlocal mobileMoorgon = createActor(121802118, 105, 82, 0, 8, 1, 7)\r\n        \r\n        \r\n        \r\n        \t----------------------------- SKIP DE CINEMATIQUE PAR LE BOUTON --------------------------\r\n        \tfunction customSkip()\r\n        \t\tMobile.setMobilePosition(playerId, playerX, playerY, playerZ)\r\n        \t\tMobile.setMobileVisible(npcJoeId, true)\r\n        \t\tskipCinematic(19901)\r\n        \tend\r\n        \r\n        \r\n        \t----------------------------- DEBUT DE CINEMATIQUE --------------------------\r\n        \r\n        \tstartCinematicContext(1.3, playerId)\r\n        \tUI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"customSkip\")\r\n        \r\n        \tinvoke_custom(150, 1, \"Mobile.setMobileVisible\", npcJoeId, false)\r\n        \r\n        \r\n        \t----------------------------- DIALOGUES --------------------------\r\n        \r\n        \t-- Elle était toute rouge ?! Sûr c'est à cause du fourrage que j'lui ai donné...\r\n        \tinvoke_custom(1000, 1, \"bubble\", mobileJoeId, \"quest.amakna.mercenary.moogrr.08.01\")\r\n        \tinvoke_custom(1000, 1, \"Mobile.setMobileAnimation\", mobileJoeId, \"AnimEmote-GratteGratte\")\r\n        \r\n        \t-- Vous l'avez trouvé où ce fourrage ?\r\n        \tinvoke_custom(5800, 1, \"clearBubbles\", mobileJoeId)\r\n        \tinvoke_custom(6000, 1, \"bubble\", playerId, \"quest.amakna.mercenary.moogrr.08.02\")\r\n        \tinvoke_custom(6000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmoteMarket-HausseEpaules\")\r\n        \r\n        \t-- C't'un type bizarre en métal, y m'a dit qu'il vendait du fourrage pour rendre les Moogrrs plus fortes.\r\n        \tinvoke_custom(9800, 1, \"clearBubbles\", playerId)\r\n        \tinvoke_custom(10000, 1, \"bubble\", mobileJoeId, \"quest.amakna.mercenary.moogrr.08.03\")\r\n        \tinvoke_custom(10000, 1, \"Mobile.setMobileAnimation\", mobileJoeId, \"AnimEmoteMarket-HausseEpaules\")\r\n        \r\n        \t-- Comme il y avait le prix Mooligrr j'me suis dis qu'ça tombait bien, j'pensais pas rendre folle ma Moogrr...\r\n        \tinvoke_custom(15800, 1, \"clearBubbles\", mobileJoeId)\r\n        \tinvoke_custom(16000, 1, \"bubble\", mobileJoeId, \"quest.amakna.mercenary.moogrr.08.04\")\r\n        \tinvoke_custom(16000, 1, \"Mobile.setMobileAnimation\", mobileJoeId, \"AnimEmote-GratteGratte\")\r\n        \r\n        \t-- Elle reviendra ptêt jamais elle doit m'en vouloir...\r\n        \tinvoke_custom(21800, 1, \"clearBubbles\", mobileJoeId)\r\n        \tinvoke_custom(22000, 1, \"bubble\", mobileJoeId, \"quest.amakna.mercenary.moogrr.08.05\")\r\n        \tinvoke_custom(22000, 1, \"Mobile.setMobileAnimation\", mobileJoeId, \"AnimEmote-Defaite\")\r\n        \r\n        \t-- **Quand on parle de la Moogrr.\r\n        \tinvoke_custom(25800, 1, \"clearBubbles\", mobileJoeId)\r\n        \tinvoke_custom(25900, 1, \"Mobile.setMobileDirection\", playerId, 1)\r\n        \tinvoke_custom(26000, 1, \"bubble\", playerId, \"quest.amakna.mercenary.moogrr.08.06\")\r\n        \tinvoke_custom(26000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n        \r\n        \t-- Moorghueurite !!!\r\n        \tinvoke_custom(29800, 1, \"clearBubbles\", playerId)\r\n        \tinvoke_custom(30000, 1, \"bubble\", mobileJoeId, \"quest.amakna.mercenary.moogrr.08.07\")\r\n        \tinvoke_custom(30000, 1, \"Mobile.setMobileAnimation\", mobileJoeId, \"AnimEmote-Help\")\r\n        \r\n        \t--  Et elle s'est trouvée un Moogron il semblerait.\r\n        \tinvoke_custom(32800, 1, \"clearBubbles\", mobileJoeId)\r\n        \tinvoke_custom(33000, 1, \"bubble\", playerId, \"quest.amakna.mercenary.moogrr.08.08\")\r\n        \tinvoke_custom(33000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Rire\")\r\n        \r\n        \t-- Ah j'comprends ma belle, t'es venue m'dire au revoir c'est ça ? Tu es libre maintenant, reviens m'voir de temps en temps.\r\n        \tinvoke_custom(36800, 1, \"clearBubbles\", playerId)\r\n        \tinvoke_custom(37000, 1, \"bubble\", mobileJoeId, \"quest.amakna.mercenary.moogrr.08.09\")\r\n        \tinvoke_custom(37000, 1, \"Mobile.setMobileAnimation\", mobileJoeId, \"AnimEmote-Pouce\")\r\n        \r\n        \t--  Vous allez vraiment la laisser partir ?\r\n        \tinvoke_custom(42800, 1, \"clearBubbles\", mobileJoeId)\r\n        \tinvoke_custom(42900, 1, \"Mobile.setMobileDirection\", playerId, 5)\r\n        \tinvoke_custom(43000, 1, \"bubble\", playerId, \"quest.amakna.mercenary.moogrr.08.10\")\r\n        \tinvoke_custom(43000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n        \t\r\n        \t--  Après c'que j'lui ai fait subir, j'pense que c'est le mieux.\r\n        \tinvoke_custom(45800, 1, \"clearBubbles\", playerId)\r\n        \tinvoke_custom(46000, 1, \"bubble\", mobileJoeId, \"quest.amakna.mercenary.moogrr.08.11\")\r\n        \tinvoke_custom(46000, 1, \"Mobile.setMobileAnimation\", mobileJoeId, \"AnimEmoteMarket-HausseEpaules\")\r\n        \t\r\n        \t--  Gardez l'trophée du prix Mooligrr, finalement c'vous qui l'avez gagné.\r\n        \tinvoke_custom(49800, 1, \"clearBubbles\", mobileJoeId)\r\n        \tinvoke_custom(50000, 1, \"bubble\", mobileJoeId, \"quest.amakna.mercenary.moogrr.08.12\")\r\n        \tinvoke_custom(50000, 1, \"Mobile.setMobileAnimation\", mobileJoeId, \"AnimEmote-Pointer\")\r\n        \t\r\n        \t--  Grâce à toué j'ai compris que j'avais besoin que d'mes Moogrrs pour êt' heureux.\r\n        \tinvoke_custom(53800, 1, \"clearBubbles\", mobileJoeId)\r\n        \tinvoke_custom(54000, 1, \"bubble\", mobileJoeId, \"quest.amakna.mercenary.moogrr.08.13\")\r\n        \tinvoke_custom(54000, 1, \"Mobile.setMobileAnimation\", mobileJoeId, \"AnimEmote-Pouce\")\r\n        \r\n        \t-- Heureux de l'entendre Joe ! Cela veut dire qu'il est temps pour moi de partir, les mercenaires m'attendent !\r\n        \tinvoke_custom(58800, 1, \"clearBubbles\", mobileJoeId)\r\n        \tinvoke_custom(59000, 1, \"bubble\", playerId, \"quest.amakna.mercenary.moogrr.08.14\")\r\n        \tinvoke_custom(59000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmoteMarket-LeverMain\")\r\n        \t\r\n        \r\n        \t-----------------------------  ACTIONS --------------------------\r\n        \r\n        \tinvoke_custom(25000, 1, \"Mobile.moveMobile\", mobileMoorghueurite, 90, 81, 0, \"Mobile.setMobileDirection\", mobileMoorghueurite, 5)\r\n        \tinvoke_custom(25000, 1, \"Mobile.moveMobile\", mobileMoorgon, 90, 82, 0, \"Mobile.setMobileDirection\", mobileMoorgon, 5)\r\n        \r\n        \tinvoke_custom(40000, 1, \"Mobile.setMobileAnimation\", mobileMoorghueurite, \"AnimSort-CridAmoogr\")\r\n        \t\r\n        \tinvoke_custom(42000, 1, \"Mobile.moveMobile\", mobileMoorghueurite, 105, 81, 0, \"Mobile.setMobileDirection\", mobileMoorghueurite, 5)\r\n        \tinvoke_custom(42000, 1, \"Mobile.moveMobile\", mobileMoorgon, 105, 82, 0, \"Mobile.setMobileDirection\", mobileMoorgon, 5)\r\n        \t----------------------------- FIN DE CINEMATIQUE --------------------------\r\n        \r\n        \tinvoke_custom(64000, 1, \"Mobile.moveMobile\", playerId, playerX, playerY, playerZ)\r\n        \tinvoke_custom(64950, 1, \"Mobile.setMobileVisible\", npcJoeId, true)\r\n        \tinvoke(65000, 1, \"skipCinematic\", 19901)\nend\n\n-- [EVENT][OPTIONNEL] Donne au joueur le Grelot Endommagé\n-- \nfunction event_2339_19840()\n    \nend\n\n-- [EVENT][OPTIONNEL] Donne au joueur le Grelot Réparé\n-- \nfunction event_2339_19841()\n    \nend\n\n-- [INIT] Le joueur leave l'instance - Leave scénario\n-- \nfunction event_2339_20341()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_2339_19810","event_2339_19807","event_2339_19804","customSkip","event_2339_19811","event_2339_19812","customSkip","event_2339_19852","event_2339_20124","event_2339_19854","event_2339_19853","customSkip","event_2339_20267","customSkip","event_2339_19893","customSkip","event_2339_19901","customSkip","event_2339_19840","event_2339_19841","event_2339_20341"],"quest_calls":[],"dialogue_calls":[]},"scenario/2340.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\n\n-- [INITIALISATION] Initialisation des variables\n-- \nfunction event_2340_19828()\n    \nend\n\n-- [INITIALISATION] Inscription du joueur - Entraînement sur Astrub Forêt\n-- \nfunction event_2340_19813(cineMoogrr)\n    \t\r\n    \t----------------------------- RECUPERATIONS DES INFOS JOUEUR --------------------------\r\n    \r\n    \tlocal playerId = Context.getLeaderId()\r\n    \r\n    \t----------------------------- INITIALISATION DES VARIABLES --------------------------\r\n    \r\n    \tlocal kamoomilleId = createActor(121801221, -144, 88, 0, 8, 7, 4)\r\n    \r\n    \t----------------------------- DEBUT DE CINEMATIQUE -------------------------- \r\n    \r\n    \tstartCinematicContext(1.1, playerId)\r\n    \tUI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 19813)\r\n    \r\n    \t----------------------------- COURSE DANS LA FORET -------------------------- \r\n    \r\n    \tinvoke_custom(1000, 1, \"Mobile.moveMobile\", playerId, -145, 58, 0, \"Mobile.setMobileDirection\", playerId, 7)\r\n    \tinvoke_custom(1000, 1, \"Mobile.moveMobile\", kamoomilleId, -144, 68, 0, \"Mobile.setMobileDirection\", kamoomilleId, 7)\r\n    \tinvoke_custom(7600, 1, \"Mobile.setMobileAnimation\", kamoomilleId, \"AnimMort\")\r\n    \r\n    \t----------------------------- FIN DE CINEMATIQUE --------------------------\r\n    \t\r\n    \tinvoke_custom(10000, 1, \"skipCinematic\", 19813)\nend\n\n-- [EVENT][MERCENAIRE] Entrainement sur Astrub Zone Bouftou\n-- \nfunction event_2340_19816(cineMoogrr)\n        ----------------------------- RECUPERATIONS DES INFOS JOUEUR --------------------------\r\n            \r\n            \tWorld.runOnFadeIn(\"trace\", \"FADE IN\")\r\n            \tWorld.runOnFadeOut(\"trace\", \"FADE OUT\")\r\n            \tEvent.runOnInstanceLoaded(\"trace\", \"INSTANCE LOADED\")\r\n            \r\n            \tlocal playerId = Context.getLeaderId()\r\n            \r\n            \r\n            \t----------------------------- INITIALISATION DES VARIABLES --------------------------\r\n            \r\n            \r\n            \tlocal kamoomilleId = createActor(121801221, -177, 36, 0, 8, 5, 4)\r\n            \r\n            \tlocal apsKameha = 1181\r\n            \tlocal apsKamehaTarget = 1185\r\n            \r\n            \t----------------------------- DEBUT DE CINEMATIQUE --------------------------\r\n            \r\n            \tstartCinematicContext(1.1, playerId)\r\n            \tUI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 19816)\r\n            \r\n            \t----------------------------- WAKMEHAMEHA COMBAT --------------------------\r\n            \r\n            \r\n            \tinvoke_custom(500, 1, \"Mobile.setMobileDirection\", playerId, 1)\r\n            \tinvoke_custom(1000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimSort-Hadouken\")\r\n            \tinvoke_custom(1000, 1, \"Particle.addParticleSystem\", apsKameha, -185, 36, 0)\r\n    \t\t\tinvoke_custom(2150, 1, \"Particle.addParticleSystem\", apsKamehaTarget, -184, 36, 0)\r\n    \t\t\tinvoke_custom(2150, 1, \"Particle.addParticleSystem\", apsKamehaTarget, -183, 36, 0)\r\n    \t\t\tinvoke_custom(2150, 1, \"Particle.addParticleSystem\", apsKamehaTarget, -182, 36, 0)\r\n    \t\t\tinvoke_custom(2150, 1, \"Particle.addParticleSystem\", apsKamehaTarget, -181, 36, 0)\r\n    \t\t\tinvoke_custom(2150, 1, \"Particle.addParticleSystem\", apsKamehaTarget, -180, 36, 0)\r\n    \t\t\tinvoke_custom(2150, 1, \"Particle.addParticleSystem\", apsKamehaTarget, -179, 36, 0)\r\n    \t\t\tinvoke_custom(2150, 1, \"Particle.addParticleSystem\", apsKamehaTarget, -178, 36, 0)\r\n            \tinvoke_custom(2150, 1, \"Particle.addParticleSystem\", apsKamehaTarget, -177, 36, 0)\r\n            \tinvoke_custom(2200, 1, \"Mobile.setMobileAnimation\", kamoomilleId, \"AnimMort\")\r\n            \tinvoke_custom(3000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Help\")\r\n            \tinvoke_custom(4500, 1, \"Mobile.moveMobile\", playerId, -178, 36, 0, \"Mobile.setMobileDirection\", playerId, 1)\r\n         \t\tinvoke_custom(7000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Genoux-Debut\")\r\n            \r\n            \t----------------------------- FIN DE CINEMATIQUE --------------------------\r\n            \t\r\n            \tinvoke_custom(8000, 1, \"skipCinematic\", 19816)\r\n            \nend\n\n-- [EVENT][MERCENAIRE] Entrainement sur Astrub Champs\n-- \nfunction event_2340_19817(cineMoogrr)\n     \r\n       ----------------------------- RECUPERATIONS DES INFOS JOUEUR --------------------------\r\n        \r\n        \tlocal playerId = Context.getLeaderId()\r\n        \r\n        \r\n        \t----------------------------- INITIALISATION DES VARIABLES --------------------------\r\n        \r\n        \r\n        \tlocal kamoomilleId = createActor(121801221, -156, -79, 0, 8, 7, 4)\r\n        \r\n        \r\n        \t----------------------------- DEBUT DE CINEMATIQUE --------------------------\r\n        \r\n        \tstartCinematicContext(1.1, playerId)\r\n        \tUI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 19817)\r\n        \r\n        \t----------------------------- COURSE DANS LES CHAMPS --------------------------\r\n        \r\n        \tinvoke_custom(1000, 1, \"Mobile.moveMobile\", playerId, -127, -78, 0, \"Mobile.setMobileDirection\", playerId, 7)\r\n        \tinvoke_custom(1000, 1, \"Mobile.moveMobile\", kamoomilleId, -127, -79, 0, \"Mobile.setMobileDirection\", kamoomilleId, 7)\r\n        \r\n      \r\n        \r\n        \t----------------------------- FIN DE CINEMATIQUE --------------------------\r\n    \r\n        \tinvoke_custom(7000, 1, \"skipCinematic\", 19817)\nend\n\n-- [EVENT][MERCENAIRE] Entrainement sur Astrub Champs Entrainement\n-- \nfunction event_2340_19818(cineMoogrr)\n        \r\n        \t----------------------------- RECUPERATIONS DES INFOS JOUEUR --------------------------\r\n        \r\n        \tlocal playerId = Context.getLeaderId()\r\n        \r\n        \t----------------------------- INITIALISATION DES VARIABLES --------------------------\r\n        \r\n        \tlocal kamoomilleId = createActor(121801221, -125, -71, 0, 8, 7, 4)\r\n        \r\n        \t----------------------------- DEBUT DE CINEMATIQUE -------------------------- \r\n        \r\n        \tstartCinematicContext(1.1, playerId)\r\n        \tUI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 19818)\r\n        \r\n        \tinvoke_custom(100, 1, \"Mobile.setMobileDirection\", kamoomilleId, 5)\r\n        \tinvoke_custom(100, 1, \"Mobile.setMobileDirection\", playerId, 3)\r\n        \t----------------------------- COMBAT ENTRAINEMENT --------------------------\r\n        \r\n        \tinvoke_custom(1000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-EncouragerFan-Debut\")\r\n        \tinvoke_custom(1000, 1, \"Mobile.setMobileAnimation\", kamoomilleId, \"AnimSort-CoupdeTete\")\r\n        \tinvoke_custom(2500, 1, \"Mobile.setMobileDirection\", kamoomilleId, 1)\r\n        \tinvoke_custom(3000, 1, \"Mobile.setMobileAnimation\", kamoomilleId, \"AnimSort-Fouettage\")\r\n        \tinvoke_custom(4000, 1, \"Mobile.setMobileDirection\", kamoomilleId, 5)\r\n        \tinvoke_custom(4500, 1, \"Mobile.setMobileAnimation\", kamoomilleId, \"AnimSort-CoupdeTete\")\r\n    \t\tinvoke_custom(6000, 1, \"Mobile.setMobileDirection\", kamoomilleId, 1)\r\n    \t\tinvoke_custom(6500, 1, \"Mobile.setMobileAnimation\", kamoomilleId, \"AnimSort-Fouettage\")\r\n    \t\tinvoke_custom(7500, 1, \"Mobile.setMobileDirection\", kamoomilleId, 7)\r\n        \tinvoke_custom(8000, 1, \"Mobile.setMobileAnimation\", kamoomilleId, \"AnimSort-CridAmoogr\")\r\n        \tinvoke_custom(9000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Applaudir\")\r\n        \r\n        \t----------------------------- FIN DE CINEMATIQUE --------------------------\r\n    \r\n        \tinvoke_custom(10000, 1, \"skipCinematic\", 19818)\r\n        \t\nend\n\n-- [EVENT][MERCENAIRE] Entrainement sur Astrub Pipoune\n-- \nfunction event_2340_19819(cineMoogrr, npcGoultard, npcPipoune)\n    ----------------------------- RECUPERATIONS DES INFOS JOUEUR --------------------------\r\n    \r\n    local playerId = Context.getLeaderId()\r\n    \r\n    ----------------------------- INITIALISATION DES VARIABLES --------------------------\r\n    \r\n    local kamoomilleId = createActor(121801221, 11, 157, 0, 8, 5, 4)\r\n    local npcGoultardId = toLong(npcGoultard)\r\n    local npcPipouneId = toLong(npcPipoune)\r\n    \r\n    local mobileGoultardId = createActor(192404688, 11, 155, 0, 8, 3, 7)\r\n    local mobilePipouneId = createActor(192404687, 7, 157, 0, 8, 1, 4)\r\n    \r\n    ----------------------------- SKIP DE CINEMATIQUE PAR LE BOUTON --------------------------\r\n    \r\n    function customSkip()\r\n    \tMobile.setMobileVisible(npcGoultardId, true)\r\n    \tMobile.setMobileVisible(npcPipouneId, true)\r\n    \tUI.displayWideScreenBand(true, 25, 300)\r\n    \tskipCinematic(19819)\r\n    end\r\n    \r\n    ----------------------------- DEBUT DE CINEMATIQUE --------------------------\r\n    Mobile.setMobileAnimationStaticKey(mobileGoultardId, \"AnimStatique-PNJ\")\r\n    Mobile.setMobileVisible(npcGoultardId, false)\r\n    Mobile.setMobileVisible(npcPipouneId, false)\r\n    Mobile.setMobileDirection(playerId, 3)\r\n    \r\n    startCinematicContext(1.3, playerId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"customSkip\")\r\n    \r\n    ----------------------------- ENTRAINEMENT PIPOUNE --------------------------\r\n    invoke_custom(100, 1, \"Mobile.setMobileAnimation\", mobileGoultardId, \"AnimStatique-PNJ\")\r\n    \r\n    invoke_custom(500, 1, \"Mobile.setMobileAnimation\", mobileGoultardId, \"AnimComp-Encouragement-PNJ\")\r\n    invoke_custom(1000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-EncouragerFan-Debut\")\r\n    invoke_custom(2000, 1, \"Mobile.setMobileAnimation\", mobilePipouneId, \"AnimSort-SuperSprint-Debut\")\r\n    invoke_custom(2500, 1, \"Mobile.setMobileVisible\", mobilePipouneId, false)\r\n    invoke_custom(3000, 1, \"Mobile.setMobilePosition\", mobilePipouneId, 10, 157, 0)\r\n    invoke_custom(3200, 1, \"Mobile.setMobileAnimation\", mobilePipouneId, \"AnimSort-SuperSprint-Fin\")\r\n    invoke_custom(3250, 1, \"Mobile.setMobileVisible\", mobilePipouneId, true)\r\n    invoke_custom(4200, 1, \"Mobile.setMobileAnimation\", kamoomilleId, \"AnimHit\")\r\n    invoke_custom(5000, 1, \"Mobile.setMobileAnimation\", kamoomilleId, \"AnimSort-CoupdeTete\")\r\n    invoke_custom(5600, 1, \"Mobile.setMobileAnimation\", mobilePipouneId, \"AnimHit\")\r\n    invoke_custom(7000, 1, \"Mobile.setMobileAnimation\", mobilePipouneId, \"AnimSort-CoudBoul\")\r\n    invoke_custom(7500, 1, \"Mobile.setMobileAnimation\", kamoomilleId, \"AnimHit\")\r\n    invoke_custom(8500, 1, \"Mobile.setMobileAnimation\", kamoomilleId, \"AnimSort-CoupdeTete\")\r\n    invoke_custom(9100, 1, \"Mobile.setMobileAnimation\", mobilePipouneId, \"AnimHit\")\r\n    invoke_custom(10000, 1, \"Mobile.setMobileAnimation\", mobilePipouneId, \"AnimSort-CoudBoul\")\r\n    invoke_custom(10500, 1, \"Mobile.setMobileAnimation\", kamoomilleId, \"AnimHit\")\r\n    invoke_custom(11500, 1, \"Mobile.setMobileDirection\", kamoomilleId, 1)\r\n    invoke_custom(11600, 1, \"Mobile.setMobileAnimation\", kamoomilleId, \"AnimSort-Fouettage\")\r\n    invoke_custom(12000, 1, \"Mobile.setMobileAnimation\", mobilePipouneId, \"AnimHit\")\r\n    invoke_custom(12800, 1, \"Mobile.setMobileAnimation\", mobilePipouneId, \"AnimKO\")\r\n    invoke_custom(13000, 1, \"Mobile.setMobileDirection\", kamoomilleId, 7)\r\n    invoke_custom(13500, 1, \"Mobile.setMobileAnimation\", kamoomilleId, \"AnimSort-CridAmoogr\")\r\n    invoke_custom(14000, 1, \"Mobile.setMobileAnimation\", mobileGoultardId, \"AnimComp-Rire-PNJ\")\r\n    invoke_custom(14000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Applaudir\")\r\n    \r\n    ----------------------------- FIN DE CINEMATIQUE --------------------------\r\n    \r\n    invoke_custom(16500, 1, \"customSkip\")\nend\n\n-- [EVENT][MERCENAIRE] Entrainement sur Astrub Montagne\n-- \nfunction event_2340_19820(cineMoogrr)\n        \r\n        \t----------------------------- RECUPERATIONS DES INFOS JOUEUR --------------------------\r\n        \r\n        \tlocal playerId = Context.getLeaderId()\r\n        \r\n        \t----------------------------- INITIALISATION DES VARIABLES --------------------------\r\n        \r\n        \tlocal kamoomilleId = createActor(121801221, 46, -113, 20, 8, 7, 4)\r\n        \r\n        \t----------------------------- DEBUT DE CINEMATIQUE -------------------------- \r\n        \r\n        \tstartCinematicContext(1.1, playerId)\r\n        \tUI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 19820)\r\n        \r\n        \r\n        \t----------------------------- COURSE DANS LES MONTAGNES --------------------------\r\n        \r\n        \tinvoke_custom(1000, 1, \"Mobile.moveMobile\", playerId, 45, -142, 21, \"Mobile.setMobileDirection\", playerId, 7)\r\n        \tinvoke_custom(1000, 1, \"Mobile.moveMobile\", kamoomilleId,  46, -142, 21, \"Mobile.setMobileDirection\", kamoomilleId, 7)\r\n        \r\n        \r\n        \t----------------------------- FIN DE CINEMATIQUE --------------------------\r\n    \r\n        \tinvoke_custom(6000, 1, \"skipCinematic\", 19820)\nend\n\n-- [EVENT][MERCENAIRE] Entrainement sur Astrub Combat Final\n-- \nfunction event_2340_19830(cineMoogrr)\n    \t----------------------------- RECUPERATIONS DES INFOS JOUEUR --------------------------\r\n        \r\n        \tlocal playerId = Context.getLeaderId()\r\n        \r\n        \t----------------------------- INITIALISATION DES VARIABLES --------------------------\r\n        \r\n        \tlocal kamoomilleId = createActor(121801221, -82, -121, 20, 8, 5, 4)\r\n        \tlocal apsFinish = 1012321\r\n        \t\r\n        \t----------------------------- DEBUT DE CINEMATIQUE --------------------------\r\n        \r\n        \tstartCinematicContext(1.1, playerId)\r\n        \tUI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 19830)\r\n        \r\n        \tinvoke_custom(100, 1, \"Mobile.setMobileDirection\", playerId, 1)\r\n        \t----------------------------- COMBAT FINAL --------------------------\r\n        \r\n        \tinvoke_custom(1000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimSort-Pousse\")\r\n        \tinvoke_custom(1500, 1, \"Particle.addParticleSystem\", apsFinish, -82, -121, 20)\r\n        \tinvoke_custom(1800, 1, \"Mobile.setMobileAnimation\", kamoomilleId, \"AnimHit\")\r\n        \tinvoke_custom(2800, 1, \"Mobile.setMobileAnimation\", kamoomilleId, \"AnimSort-CoupdeTete\")\r\n        \tinvoke_custom(3500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimKO-Debut\")\r\n        \tinvoke_custom(5000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimKO-SortieOK\")\r\n        \tinvoke_custom(6000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Pouce\")\r\n    \t\tinvoke_custom(7000, 1, \"Mobile.moveMobile\", kamoomilleId, -81, -121, 20, \"Mobile.setMobileDirection\", kamoomilleId, 7)\r\n        \tinvoke_custom(7500, 1, \"Mobile.moveMobile\", kamoomilleId, -81, -124, 20, \"Mobile.setMobileDirection\", kamoomilleId, 7)\r\n    \t\tinvoke_custom(7000, 1, \"Mobile.moveMobile\", playerId, -82, -124, 20, \"Mobile.setMobileDirection\", playerId, 7)\r\n        \t\r\n        \r\n        \t----------------------------- FIN DE CINEMATIQUE --------------------------\r\n        \t\r\n        \tinvoke_custom(12000, 1, \"skipCinematic\", 19830)\nend\n\n-- [EVENT][MERCENAIRE] Fin Entrainement (ACH 4251 OBJ 8785)\n-- \nfunction event_2340_19815(cineMoogrr)\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_2340_19828","event_2340_19813","event_2340_19816","event_2340_19817","event_2340_19818","event_2340_19819","customSkip","event_2340_19820","event_2340_19830","event_2340_19815"],"quest_calls":[],"dialogue_calls":[]},"scenario/2341.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\n\n-- [INITIALISATION] Initialisation des variables\n-- \nfunction event_2341_20830()\n    \nend\n\n-- [INIT] Perso\n-- \nfunction event_2341_19824()\n    local playerId = Context.getLeaderId()\r\n    local riktusId = createActor(120501168, 4061, 4056, 0, 8, 5, 6)\r\n    \r\n    startCinematicContext(1.8, riktusId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 19824)\r\n    \r\n    invoke_custom(0001, 1, \"Mobile.setMobileVisible\", riktusId, true)\r\n    invoke_custom(0001, 1, \"Mobile.setMobileVisible\", playerId, false)\r\n    \r\n    ---\"Il n'y a pas âme qui vive ici !\"\r\n    invoke_custom(2000, 1, \"Mobile.moveMobile\", riktusId, 4052, 4057, -1, \"Mobile.setMobileDirection\", riktusId, 1)\r\n    invoke_custom(4000, 1, \"bubble\", riktusId, \"quest.amakna.mercenary.riktus.01.01\")\r\n    invoke_custom(8000, 1, \"clearBubbles\", riktusId)\r\n    \r\n    ---\"Bon, il suffit de déplacer les caisses là-bas ?\"\r\n    invoke_custom(9000, 1, \"bubble\", riktusId, \"quest.amakna.mercenary.riktus.01.02\")\r\n    invoke_custom(13000, 1, \"clearBubbles\", riktusId)\r\n    \r\n    ---\"C'est un travail pour Rick Tuche !\"\r\n    invoke_custom(14000, 1, \"bubble\", riktusId, \"quest.amakna.mercenary.riktus.01.03\")\r\n    invoke_custom(14000, 1, \"Mobile.setMobileAnimation\", riktusId, \"AnimSort-Bouclier\")\r\n    invoke_custom(19000, 1, \"clearBubbles\", riktusId)\r\n    \r\n    ----------------------------------\r\n    \r\n    invoke_custom(19500, 1, \"skipCinematic\", 19824)\nend\n\n-- [EVENT] Défi Caisses - Lancement\n-- \nfunction event_2341_19825()\n    UI.loadTutorialDialog(\"null\",\"quest.huppermage.sokoban.tutorial.title\",\"quest.huppermage.sokoban.tutorial.desc\")\r\n    Mobile.setMobileAnimationStaticKey(Context.getLeaderId(), \"AnimStatique01\")\nend\n\n-- [EVENT] Défi Caisses - Début\n-- \nfunction event_2341_19826()\n    \nend\n\n-- [EVENT] Défi - Victoire - Validation Quête + Cinématique\n-- \nfunction event_2341_19837()\n    local playerId = Context.getLeaderId()\r\n    \r\n    local sergentId = createActor(150, 4065, 4057, 0, 8, 1, 6)\r\n    local gardeOneId = createActor(150, 4067, 4059, 0, 8, 1, 6)\r\n    local gardeTwoId = createActor(150, 4065, 4059, 0, 8, 1, 6)\r\n    \r\n    Actor.equip(sergentId, \"22312505\", \"Arme\")\r\n    Actor.equip(sergentId, \"51317906\", \"JambeHabit\", \"PiedHabit01\", \"PiedHabit02\", \"Cape\", \"CapeBas\")\r\n    Actor.equip(sergentId, \"13417910\", \"Chapeau\")\r\n    \r\n    Actor.equip(gardeOneId, \"51317906\", \"JambeHabit\", \"PiedHabit01\", \"PiedHabit02\", \"Cape\", \"CapeBas\", \"Chapeau\")\r\n    Actor.equip(gardeTwoId, \"51317906\", \"JambeHabit\", \"PiedHabit01\", \"PiedHabit02\", \"Cape\", \"CapeBas\", \"Chapeau\")\r\n    \r\n    ----------------------------------\r\n    \r\n    startCinematicContext(1.8, sergentId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 19837)\r\n    \r\n    invoke_custom(0001, 1, \"Mobile.setMobileVisible\", sergentId, true)\r\n    invoke_custom(0001, 1, \"Mobile.setMobileVisible\", gardeOneId, true)\r\n    invoke_custom(0001, 1, \"Mobile.setMobileVisible\", gardeTwoId, true)\r\n    \r\n    -- \"Pas un pas de plus, le Riktus !!!\"\r\n    invoke_custom(2000, 1, \"bubble\", sergentId, \"quest.amakna.mercenary.riktus.01.04\")\r\n    invoke_custom(6000, 1, \"clearBubbles\", sergentId)\r\n    \r\n    invoke_custom(7000, 1, \"Mobile.moveMobile\", sergentId, 4058, 4058, 0, \"Mobile.setMobileDirection\", sergentId, 5)\r\n    invoke_custom(8000, 1, \"Mobile.moveMobile\", gardeOneId, 4058, 4056, 0, \"Mobile.setMobileDirection\", gardeOneId, 5)\r\n    invoke_custom(8000, 1, \"Mobile.moveMobile\", gardeTwoId, 4056, 4056, 0, \"Mobile.setMobileDirection\", gardeTwoId, 5)\r\n    \r\n    invoke_custom(8000, 1, \"Mobile.moveMobile\", playerId, 4052, 4059, 0, \"Mobile.setMobileDirection\", playerId, 1)\r\n    \r\n    -- \"Qu'est-ce qu'il y a, dans ces caisses ?\"\r\n    invoke_custom(13000, 1, \"Mobile.setMobileAnimation\", sergentId, \"AnimStatique-GardeNation\")\r\n    invoke_custom(13000, 1, \"bubble\", sergentId, \"quest.amakna.mercenary.riktus.01.05\")\r\n    invoke_custom(17000, 1, \"clearBubbles\", sergentId)\r\n    \r\n    -- \"Je ne sais pas vraiment, on m'a juste demandé de...\"\r\n    invoke_custom(16500, 1, \"Camera.attachCameraToMobile\", playerId)\r\n    invoke_custom(17000, 1, \"bubble\", playerId, \"quest.amakna.mercenary.riktus.01.06\")\r\n    invoke_custom(21000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Silence ! Toi, va voir ce qu'elles contiennent !\"\r\n    invoke_custom(20500, 1, \"bubble\", sergentId, \"quest.amakna.mercenary.riktus.01.07\")\r\n    invoke_custom(22000, 1, \"Mobile.setMobileDirection\", sergentId, 7)\r\n    invoke_custom(26000, 1, \"clearBubbles\", sergentId)\r\n    \r\n    invoke_custom(26500, 1, \"Mobile.moveMobile\", gardeOneId, 4054, 4059, -1, \"Mobile.setMobileDirection\", gardeOneId, 3)\r\n    invoke_custom(26500, 1, \"Mobile.setMobileDirection\", sergentId, 5)\r\n    \r\n    invoke_custom(29000, 1, \"Mobile.setMobileAnimation\", gardeOneId, \"AnimCueillette-Debut\")\r\n    invoke_custom(32000, 1, \"Mobile.setMobileAnimation\", gardeOneId, \"AnimCueillette-Fin\")\r\n    invoke_custom(32500, 1, \"Mobile.setMobileDirection\", gardeOneId, 1)\r\n    \r\n    -- \"Capitaine, il y a plein de poudre explosive ! Assez pour faire sauter tout un quartier d'Amakna !\"\r\n    invoke_custom(32500, 1, \"bubble\", gardeOneId, \"quest.amakna.mercenary.riktus.01.08\")\r\n    \r\n    -- \"J-je n'y comprends rien...\"\r\n    invoke_custom(39000, 1, \"bubble\", playerId, \"quest.amakna.mercenary.riktus.01.09\")\r\n    invoke_custom(43000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"C'est un terroriste, attrapez-le !!!\"\r\n    invoke_custom(41000, 1, \"bubble\", sergentId, \"quest.amakna.mercenary.riktus.01.10\")\r\n    \r\n    ----------------------------------\r\n    \r\n    invoke_custom(45500, 1, \"skipCinematic\", 19837)\nend\n\n-- [EVENT] Fin de la Cinématique - Le joueur est téléporté dans la prison d'Amakna\n-- \nfunction event_2341_19838()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_2341_20830","event_2341_19824","event_2341_19825","event_2341_19826","event_2341_19837","event_2341_19838"],"quest_calls":[],"dialogue_calls":[]},"scenario/2342.lua":{"source":"\n\n-- [VARIABLE] Initialisation des variables\n-- \nfunction event_2342_19861()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2342_19831()\n    \nend\n\n-- [EVENT] Fin du Dialogue - Combat Possible\n-- \nfunction event_2342_19863()\n    \nend\n\n-- [COMBAT][Achievement] Ombrage possède \"Fusion Ténébreuse\" au niveau 3 mini\n-- \nfunction event_2342_19902()\n    \nend\n\n-- [COMBAT][Achievement] Ombrage possède \"Fusion Ténébreuse\" au niveau 3 mini + Victoire des joueurs\n-- \nfunction event_2342_19903()\n    \nend\n\n-- [COMBAT][Achievement] Un joueur tombe KO\n-- \nfunction event_2342_19904()\n    \nend\n\n-- [COMBAT][Achievement] Aucun joueur tombe KO + Victoire des joueurs\n-- \nfunction event_2342_19905()\n    \nend\n\n-- [COMBAT][Achievement] Ombrage possède \"Ultimate\" au niveau 5 mini\n-- \nfunction event_2342_19906()\n    \nend\n\n-- [COMBAT][Achievement] Ombrage possède \"Ultimate\" au niveau 5 mini + Victoire des joueurs\n-- \nfunction event_2342_19907()\n    \nend\n\n","functions":["event_2342_19861","event_2342_19831","event_2342_19863","event_2342_19902","event_2342_19903","event_2342_19904","event_2342_19905","event_2342_19906","event_2342_19907"],"quest_calls":[],"dialogue_calls":[]},"scenario/2343.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\n-- les fonctions où on cache\r\nfunction hideMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, false)\r\nend\r\n\r\nfunction hidePart(monsterMobileId, partName)\r\n\tMobile.setPartVisible(monsterMobileId, false, partName)\r\nend\r\n\r\n-- les fonctions où on rend visible (à nouveau\r\nfunction showMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, true)\r\nend\r\n\r\nfunction showPart(monsterMobileId, partName)\r\n\tMobile.setPartVisible(monsterMobileId, true, partName)\r\nend\n\n-- [INITIALISATION] Serveur\n-- \nfunction event_2343_19855()\n    \nend\n\n-- ~[INITIALISATION] Perso\n-- \nfunction event_2343_19833()\n    \nend\n\n-- [EVENT] Le joueur parle à Rick Tuche et est téléporté dans l'entrepôt\n-- \nfunction event_2343_19834()\n    UI.loadTutorialDialog(\"null\",\"quest.huppermage.sokoban.tutorial.title\",\"quest.huppermage.sokoban.tutorial.desc\")\r\n    Mobile.setMobileAnimationStaticKey(Context.getLeaderId(), \"AnimStatique01\")\nend\n\n-- [EVENT] Fin du flashback, le joueur revient dans la prison et lance un nouveau dialogue\n-- \nfunction event_2343_19835()\n    \nend\n\n-- [EVENT] Masquage du PNJ monde si le joueur a fini la quête\n-- \nfunction event_2343_19856(ricktucheId)\n    Mobile.addMobileCreationCallback(ricktucheId, \"hideMonster\", ricktucheId)\nend\n\n-- [EVENT] Affichage du PNJ monde si le joueur n'a pas fini la quête\n-- \nfunction event_2343_20284(ricktucheId)\n    Mobile.addMobileCreationCallback(ricktucheId, \"showMonster\", ricktucheId)\nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","hideMonster","hidePart","showMonster","showPart","event_2343_19855","event_2343_19833","event_2343_19834","event_2343_19835","event_2343_19856","event_2343_20284"],"quest_calls":[],"dialogue_calls":[]},"scenario/2344.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\n\n-- [INIT] Variables\n-- \nfunction event_2344_19864()\n    \nend\n\n-- ~[ENTER] Le joueur entre dans l'instance - Inscription au scénario\n-- \nfunction event_2344_19842()\n    \nend\n\n-- [EVENT] Le joueur parle mal à Dédé Structeur - Cinématique\n-- \nfunction event_2344_19843(dedeMdcId)\n    local playerId = Context.getLeaderId()\r\n    local dedeMdcId = toLong(dedeMdcId)\r\n    local apsFinish = 1012321\r\n    \r\n    function displayZeroDamage()\r\n    \tUI.displayFlyingText(1, 0.4, 0.1, \"lstw\", playerId, \"finish.move.damage\", 0, 55, 0)\r\n    end\r\n    \r\n    function displayExtraDamage()\r\n    \tUI.displayFlyingText(1, 0.4, 0.1, \"lstw\", dedeMdcId, \"finish.move.damage\", 0, 55, -999999)\r\n    end\r\n    \r\n    startCinematicContext(1.2, playerId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 19843)\r\n    \r\n    ---\"Tu vas voir de quel bois je me chauffe !!!\"\r\n    \r\n    invoke_custom(1000, 1, \"Mobile.setMobileDirection\", playerId, 7)\r\n    invoke_custom(1000, 1, \"bubble\", dedeMdcId, \"quest.amakna.mercenary.riktus.02.01\")\r\n    invoke_custom(1500, 1, \"Mobile.setMobileAnimation\", dedeMdcId, \"AnimSort-Appo\")\r\n    \r\n    -- (on spam le setMobileDirection puisque le joueur se déplaçait pas en script juste avant)\r\n    invoke_custom(4000, 1, \"Mobile.setMobileDirection\", playerId, 7)\r\n    invoke_custom(4000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Acquiescer\")\r\n    invoke_custom(6500, 1, \"clearBubbles\", dedeMdcId)\r\n    \r\n    invoke_custom(7400, 1, \"Mobile.setMobileAnimation\", dedeMdcId, \"AnimSort-GriffeAnimale\")\r\n    invoke_custom(8000, 1, \"displayZeroDamage\")\r\n    \r\n    invoke_custom(9400, 1, \"Mobile.setMobileAnimation\", dedeMdcId, \"AnimSort-GriffeAnimale\")\r\n    invoke_custom(10000, 1, \"displayZeroDamage\")\r\n    invoke_custom(10300, 1, \"displayZeroDamage\")\r\n    invoke_custom(10600, 1, \"displayZeroDamage\")\r\n    \r\n    invoke_custom(10500, 1, \"Mobile.setMobileDirection\", playerId, 7)\r\n    invoke_custom(10500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Bailler\")\r\n    \r\n    -- \"Espèce de...!!!\"\r\n    invoke_custom(11500, 1, \"bubble\", dedeMdcId, \"quest.amakna.mercenary.riktus.02.02\")\r\n    invoke_custom(11500, 1, \"Mobile.setMobileAnimation\", dedeMdcId, \"AnimSort-Appo\")\r\n    invoke_custom(15000, 1, \"clearBubbles\", dedeMdcId)\r\n    \r\n    invoke_custom(15000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimSort-CoupdePiedHaut\")\r\n    invoke_custom(15400, 1, \"displayExtraDamage\")\r\n    invoke_custom(15400, 1, \"Particle.addParticleSystem\", apsFinish, 15, 68, 0)\r\n    invoke_custom(15400, 1, \"Mobile.setMobileAnimation\", dedeMdcId, \"AnimHit\")\r\n    \r\n    invoke_custom(16000, 1, \"Mobile.setMobileAnimation\", dedeMdcId, \"AnimHit\")\r\n    \r\n    invoke_custom(17000, 1, \"skipCinematic\", 19843)\nend\n\n-- [EVENT] Fin de la cinématique - Dédé Structeur reparle au joueur\n-- \nfunction event_2344_19844()\n    \nend\n\n-- [EVENT] Maloboss Géror Mojox - Cinématique\n-- \nfunction event_2344_20262(dedeMdcId)\n    local playerId = Context.getLeaderId()\r\n    local dedeMdcId = toLong(dedeMdcId)\r\n    local riktusId = createActor(120501171, 4, 71, 0, 8, 1, 7)\r\n    \r\n    startCinematicContext(1.2, playerId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 20262)\r\n    \r\n    invoke_custom(100, 1, \"Mobile.moveMobile\", riktusId, 14, 71, 0, \"Mobile.setMobileDirection\", riktusId, 7)\n    \r\n    ---\"Toi !!! Qu'est-ce que tu fais ici ?\"\r\n    invoke_custom(01000, 1, \"bubble\", dedeMdcId, \"quest.amakna.mercenary.riktus.03.01\")\r\n    invoke_custom(01500, 1, \"Mobile.setMobileAnimation\", dedeMdcId, \"AnimSort-Appo\")\r\n    invoke_custom(02500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Calmer\")\r\n    invoke_custom(05500, 1, \"clearBubbles\", dedeMdcId)\r\n    \r\n    -- \"Tu devrais plutôt demander aux centaines de Magik Riktus qui ont été capturés par les gardes Amaknéens...\"\r\n    invoke_custom(06500, 1, \"bubble\", riktusId, \"quest.amakna.mercenary.riktus.03.02\")\r\n    invoke_custom(12000, 1, \"clearBubbles\", riktusId)\r\n    \r\n    -- \"... et mis au cachot ! Pour aucune raison !\"\r\n    invoke_custom(12500, 1, \"bubble\", riktusId, \"quest.amakna.mercenary.riktus.03.03\")\r\n    invoke_custom(16000, 1, \"clearBubbles\", riktusId)\r\n    \r\n    -- \"Des Riktus ? Capturés ?\"\r\n    invoke_custom(16500, 1, \"bubble\", playerId, \"quest.amakna.mercenary.riktus.03.04\")\r\n    invoke_custom(16500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Calmer\")\r\n    invoke_custom(20000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Oui, c'est pour ça que nous faisons la guerre contre Amakna.\"\r\n    invoke_custom(21000, 1, \"bubble\", riktusId, \"quest.amakna.mercenary.riktus.03.05\")\r\n    invoke_custom(26000, 1, \"clearBubbles\", riktusId)\r\n    \r\n    -- \"Tant que nous ne retrouvons pas nos frères brigands, ça ne fait aucun doute : nous continuerons à déployer nos forces.\"\r\n    invoke_custom(26500, 1, \"bubble\", riktusId, \"quest.amakna.mercenary.riktus.03.06\")\r\n    invoke_custom(33000, 1, \"clearBubbles\", riktusId)\r\n    \r\n    ---\"Rrraah !!! Déguerpissez maintenant, maudits Riktus, menteurs !\"\r\n    invoke_custom(33500, 1, \"bubble\", dedeMdcId, \"quest.amakna.mercenary.riktus.03.07\")\r\n    invoke_custom(33500, 1, \"Mobile.setMobileAnimation\", dedeMdcId, \"AnimSort-Appo\")\r\n    invoke_custom(38500, 1, \"clearBubbles\", dedeMdcId)\r\n    \r\n    -- \"Nous nous reverrons ! Et cette fois-ci, sur le champ de bataille !\"\r\n    invoke_custom(39000, 1, \"bubble\", riktusId, \"quest.amakna.mercenary.riktus.03.08\")\r\n    invoke_custom(43000, 1, \"clearBubbles\", riktusId)\r\n    \r\n    invoke_custom(43000, 1, \"Mobile.moveMobile\", riktusId, -4, 71, 0)\r\n    \r\n    -- \"**Je vais aller jeter un oeil dans ces geôles, pour écouter leur version de l'histoire...\"\r\n    invoke_custom(44500, 1, \"bubble\", playerId, \"quest.amakna.mercenary.riktus.03.09\")\r\n    invoke_custom(44500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(50000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(51000, 1, \"skipCinematic\", 20262)\nend\n\n-- [EVENT] Fin de la cinématique - On valide la quête\n-- \nfunction event_2344_20263()\n    \nend\n\n-- [EVENT] Le Corbeau Noir débarque - Cinématique\n-- \nfunction event_2344_19858()\n    local playerId = Context.getLeaderId()\r\n    local cnId = createActor(101101150, 103, -43, 0, 8, 1, 12)\r\n    local apsId = -1436048700\r\n    \r\n    startCinematicContext(1.2, playerId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 19858)\r\n    \r\n    -- Début cinématique\r\n    \r\n    invoke_custom(00001, 1, \"Mobile.setMobileVisible\", cnId, false)\r\n    invoke_custom(00001, 1, \"Mobile.moveMobile\", playerId, 103, -45, 0, \"Mobile.setMobileDirection\", playerId, 7)\r\n    \r\n    invoke_custom(01000, 1, \"Particle.addParticleSystem\", apsId, 103, -45, 0)\r\n    invoke_custom(02000, 1, \"Mobile.setMobileVisible\", cnId, true)\r\n    invoke_custom(02000, 1, \"Mobile.setMobileAnimation\", cnId, \"AnimSort-Laceration-2\")\r\n    invoke_custom(03500, 1, \"Mobile.setMobileAnimation\", cnId, \"AnimSort-Laceration-1\")\r\n    invoke_custom(05000, 1, \"UI.displayWideScreenBand\", true, 100, 500)\r\n        \r\n    invoke_custom(06000, 1, \"Mobile.setMobileAnimationSuffix\", cnId, \"-PNJ\")\r\n    invoke_custom(06000, 1, \"Mobile.setMobilePosition\", cnId, 104, -52, 14)\r\n    invoke_custom(06000, 1, \"Mobile.setMobilePosition\", playerId, 103, -48, 0)\r\n    invoke_custom(06000, 1, \"Mobile.setMobileAnimation\", cnId, \"AnimStatique\")\r\n        \r\n    invoke_custom(06000, 1, \"Camera.attachCameraToMobile\", cnId)\r\n    \r\n    invoke_custom(07500, 1,\"UI.displayWideScreenBand\", true, 25, 1000)\r\n    \r\n    -- \"Craignez le feu des ténèbres, craignez votre pire cauchemar !\"\r\n    invoke_custom(08000, 1, \"bubble\", cnId, \"quest.amakna.mercenary.riktuselite.01.01\")\r\n    invoke_custom(11500, 1, \"clearBubbles\", cnId)\r\n    \r\n    -- \"Mais, je te reconnais, toi ! Je t'ai déjà vu{[1*]?e:} quelque part, je suis sûr que je te reconnais...\"\r\n    invoke_custom(12000, 1, \"bubble\", cnId, \"quest.amakna.mercenary.riktuselite.01.02\")\r\n    invoke_custom(17500, 1, \"clearBubbles\", cnId)\r\n    \r\n    -- \"Désolé{[1*]?e:} mais c'est moi qui te reconnais, Kabrok.\"\r\n    invoke_custom(18000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Non\")\r\n    invoke_custom(18000, 1, \"bubble\", playerId, \"quest.amakna.mercenary.riktuselite.01.03\")\r\n    invoke_custom(22000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Quel bon vent t'amène ?\"\r\n    invoke_custom(22500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Coucou\")\r\n    invoke_custom(22500, 1, \"bubble\", playerId, \"quest.amakna.mercenary.riktuselite.01.04\")\r\n    invoke_custom(26000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Je me suis fait dérober plusieurs objets... sensibles.\"\r\n    invoke_custom(26500, 1, \"bubble\", cnId, \"quest.amakna.mercenary.riktuselite.01.05\")\r\n    invoke_custom(30500, 1, \"clearBubbles\", cnId)\r\n    \r\n    -- \"La piste du voleur menait jusqu'ici, alors me voilà !\"\r\n    invoke_custom(31000, 1, \"bubble\", cnId, \"quest.amakna.mercenary.riktuselite.01.06\")\r\n    invoke_custom(35500, 1, \"clearBubbles\", cnId)\r\n    \r\n    -- \"Quelle coïncidence... Je devais justement me rendre dans cette mine pour enquêter sur quelques brigands.\"\r\n    invoke_custom(36000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(36000, 1, \"bubble\", playerId, \"quest.amakna.mercenary.riktuselite.01.07\")\r\n    invoke_custom(42000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Alors nos chemins se recroisent. Laisse-moi t'accompagner pour cette fois !\"\r\n    invoke_custom(42000, 1, \"bubble\", cnId, \"quest.amakna.mercenary.riktuselite.01.08\")\r\n    invoke_custom(46500, 1, \"clearBubbles\", cnId)\r\n    \r\n    -- \"Je dois agir vite, ton aide sera la bienvenue !\"\r\n    invoke_custom(47000, 1, \"bubble\", cnId, \"quest.amakna.mercenary.riktuselite.01.09\")\r\n    invoke_custom(50500, 1, \"clearBubbles\", cnId)\r\n    \r\n    -- \"Très bien, en avant pour l'équipe de choc !\"\r\n    invoke_custom(36000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Aguiche\")\r\n    invoke_custom(51000, 1, \"bubble\", playerId, \"quest.amakna.mercenary.riktuselite.01.10\")\r\n    invoke_custom(54500, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(55000, 1,\"UI.displayWideScreenBand\", true, 100, 1000)\r\n    \r\n    invoke_custom(58000, 1, \"skipCinematic\", 19858)\nend\n\n-- [EVENT] Fin de la cinématique Corbeau Noir (ACH 4265 OBJ 8821)\n-- \nfunction event_2344_19865()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_2344_19864","event_2344_19842","event_2344_19843","displayZeroDamage","displayExtraDamage","event_2344_19844","event_2344_20262","event_2344_20263","event_2344_19858","event_2344_19865"],"quest_calls":[],"dialogue_calls":[]},"scenario/2345.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\n\r\n-- les fonctions où on cache\r\nfunction hideMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, false)\r\nend\r\n\r\n-- les fonctions où on rend visible (à nouveau\r\nfunction showMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, true)\r\nend\n\n-- [INIT] Variables\n-- \nfunction event_2345_19868()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2345_19848(RiktusId)\n    Mobile.addMobileCreationCallback(RiktusId, \"hideMonster\", RiktusId)\nend\n\n-- [EVENT] ENTER_INSTANCE - Ajout du follower mobile Corbeau Noir\n-- \nfunction event_2345_19859()\n    \nend\n\n-- [EVENT] Fin du dialogue avec Persée Phore - Lance un dialogue avec le CN\n-- \nfunction event_2345_19850()\n    \nend\n\n-- [EVENT] Fin du timer - Lance un dialogue avec le CN\n-- \nfunction event_2345_19872()\n    \nend\n\n-- [EVENT] Le joueur interagit avec un tabouret - Cinématique (ACH 4266 OBJ 8827)\n-- \nfunction event_2345_19890()\n    BubbleText.closeBubbleAttachedTo(userId)\r\n    \r\n    local bubbleId = BubbleText.prepareWakfuBubble(userId, 0, 60, false)\r\n    \r\n    BubbleText.setText(bubbleId, \"quest.amakna.mercenary.riktuselite.03.01\")\r\n    BubbleText.attachToMobile(bubbleId, userId)\r\n    BubbleText.show(bubbleId)\nend\n\n-- [EVENT] Le joueur marche sur un position trigger - Cinématique CN\n-- \nfunction event_2345_19849()\n    local playerId = Context.getLeaderId()\r\n    local riktusId = createActor(120501167, -101, -41, 0, 8, 7, 6)\r\n    local badRiktusOneId = createActor(120501766, -102, -48, 0, 8, 3, 6)\r\n    local badRiktusTwoId = createActor(120501767, -100, -47, 0, 8, 3, 6)\r\n    local badRiktusThreeId = createActor(120501768, -98, -48, 2, 8, 3, 6)\r\n    local blackCrowId = createActor(101101151, -102, -49, 0, 8, 3, 6)\r\n    \r\n    startCinematicContext(1.2, playerId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 19849)\r\n    \r\n    invoke_custom(00001, 1, \"Mobile.setMobileVisible\", badRiktusOneId, false)\r\n    invoke_custom(00001, 1, \"Mobile.setMobileVisible\", badRiktusTwoId, false)\r\n    invoke_custom(00001, 1, \"Mobile.setMobileVisible\", badRiktusThreeId, false)\r\n    \r\n    invoke_custom(00001, 1, \"Mobile.setMobileVisible\", riktusId, true)\r\n    invoke_custom(00001, 1, \"Mobile.setMobileVisible\", blackCrowId, true)\r\n    \r\n    invoke_custom(00100, 1, \"Mobile.moveMobile\", playerId, -100, -43, 0, \"Mobile.setMobileDirection\", playerId, 3)\r\n    invoke_custom(00100, 1, \"Mobile.moveMobile\", blackCrowId, -102, -43, 0, \"Mobile.setMobileDirection\", blackCrowId, 3)\r\n    \r\n    ---\"Au secours ! Ne les laissez pas m'attraper !\"\r\n    invoke_custom(01000, 1, \"bubble\", riktusId, \"quest.amakna.mercenary.riktuselite.02.01\")\r\n    invoke_custom(05500, 1, \"clearBubbles\", riktusId)\r\n    \r\n    invoke_custom(06500, 1, \"Mobile.setMobileDirection\", playerId, 7)\r\n    invoke_custom(06500, 1, \"Mobile.setMobileDirection\", blackCrowId, 7)\r\n    \r\n    -- \"Perdez 15 kilos en une nuit avec ce produit !\"\r\n    invoke_custom(06500, 1, \"Mobile.setMobileVisible\", badRiktusOneId, true)\r\n    invoke_custom(06501, 1, \"Mobile.setMobileAnimation\", badRiktusOneId, \"AnimApparition\")\r\n    invoke_custom(07200, 1, \"bubble\", badRiktusOneId, \"quest.amakna.mercenary.riktuselite.02.02\")\r\n    \r\n    -- \"Avec ça, finie la mauvaise haleine !\"\r\n    invoke_custom(08000, 1, \"Mobile.setMobileVisible\", badRiktusTwoId, true)\r\n    invoke_custom(08001, 1, \"Mobile.setMobileAnimation\", badRiktusTwoId, \"AnimApparition\")\r\n    invoke_custom(08700, 1, \"bubble\", badRiktusTwoId, \"quest.amakna.mercenary.riktuselite.02.03\")\r\n    \r\n    -- \"Retrouvez une peau aussi douce que celle d'un bébé !\"\r\n    invoke_custom(09500, 1, \"Mobile.setMobileVisible\", badRiktusThreeId, true)\r\n    invoke_custom(09501, 1, \"Mobile.setMobileAnimation\", badRiktusThreeId, \"AnimApparition\")\r\n    invoke_custom(10700, 1, \"bubble\", badRiktusThreeId, \"quest.amakna.mercenary.riktuselite.02.04\")\r\n    invoke_custom(14500, 1, \"clearBubbles\", badRiktusOneId)\r\n    invoke_custom(14500, 1, \"clearBubbles\", badRiktusTwoId)\r\n    invoke_custom(14500, 1, \"clearBubbles\", badRiktusThreeId)\r\n    \r\n    -- \"Qu'est-ce que...\"\r\n    invoke_custom(14500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(15000, 1, \"bubble\", playerId, \"quest.amakna.mercenary.riktuselite.02.05\")\r\n    invoke_custom(17500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Ces diables veulent me faire ingérer un Raide Boule spécial...\"\r\n    invoke_custom(18000, 1, \"bubble\", riktusId, \"quest.amakna.mercenary.riktuselite.02.06\")\r\n    invoke_custom(22500, 1, \"clearBubbles\", riktusId)\r\n    \r\n    -- \"Ceux qui le boivent perdent la raison et rejoignent les rangs de la Riktus Elite Corp. !\"\r\n    invoke_custom(23000, 1, \"bubble\", riktusId, \"quest.amakna.mercenary.riktuselite.02.07\")\r\n    invoke_custom(28500, 1, \"clearBubbles\", riktusId)\r\n    \r\n    -- \"Je vois, mais ça ne se passera pas comme ça.\"\r\n    invoke_custom(29000, 1, \"bubble\", blackCrowId, \"quest.amakna.mercenary.riktuselite.02.08\")\r\n    invoke_custom(33500, 1, \"clearBubbles\", blackCrowId)\r\n    \r\n    -- \"Restez derrière nous, on va s'en charger !\"\r\n    invoke_custom(34000, 1, \"bubble\", playerId, \"quest.amakna.mercenary.riktuselite.02.09\")\r\n    invoke_custom(38000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(38500, 1, \"Mobile.setMobileAnimation\", blackCrowId, \"AnimSort-Saut\")\r\n    \r\n    invoke_custom(39000, 1, \"skipCinematic\", 19849)\nend\n\n-- [EVENT] Cinématique terminée - On lance le combat de monstres (CN)\n-- \nfunction event_2345_19867()\n    \nend\n\n-- [EVENT] Combat de monstres (CN) - Début\n-- \nfunction event_2345_19870(local_cn_fight_id)\n    \nend\n\n-- [EVENT] Fin du combat - Cinématique et validation de la quête (ACH 4266 OBJ 8830)\n-- \nfunction event_2345_19871(local_cn_fight_id, RiktusId)\n    local playerId = Context.getLeaderId()\r\n    local badRiktusId = createActor(120501768, -98, -46, 0, 8, 5, 6)\r\n    local blackCrowId = createActor(101101151, -102, -46, 0, 8, 3, 6)\r\n    \r\n    startCinematicContext(1.5, playerId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 19871)\r\n    \r\n    invoke_custom(100, 1, \"Mobile.setMobileDirection\", playerId, 7)\r\n    invoke_custom(100, 1, \"Mobile.addMobileCreationCallback\", RiktusId, \"showMonster\", RiktusId)\r\n    \r\n    invoke_custom(00650, 1, \"Mobile.setMobileAnimation\", badRiktusId, \"AnimSort-Boulet\")\r\n    invoke_custom(01200, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Effrayee\")\r\n    invoke_custom(01550, 1, \"Mobile.setMobileAnimation\", blackCrowId, \"AnimHit\")\r\n    \r\n    invoke_custom(01850, 1, \"Mobile.setMobileDirection\", blackCrowId, 1)\r\n    invoke_custom(01850, 1, \"Mobile.setMobileAnimation\", blackCrowId, \"AnimSort-Laceration\")\r\n    invoke_custom(03000, 1, \"Mobile.setMobileAnimation\", badRiktusId, \"AnimMort\")\r\n    invoke_custom(04100, 1, \"Mobile.setMobileVisible\", badRiktusId, false)\r\n    \r\n    invoke_custom(04550, 1, \"Mobile.setMobileAnimation\", blackCrowId, \"AnimKO-Debut\")\r\n    invoke_custom(04100, 1, \"Mobile.moveMobile\", playerId, -100, -46, 0, \"Mobile.setMobileDirection\", playerId, 5)\r\n    \r\n    -- \"Est-ce que ça va aller ?\"\r\n    invoke_custom(06000, 1, \"bubble\", playerId, \"quest.amakna.mercenary.riktuselite.02.10\")\r\n    invoke_custom(06550, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Help\")\r\n    invoke_custom(09000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Je crois que non... Mes forces s'amenuisent, je ne suis plus le jeunôt que j'étais...\"\r\n    invoke_custom(10000, 1, \"bubble\", blackCrowId, \"quest.amakna.mercenary.riktuselite.02.11\")\r\n    invoke_custom(16000, 1, \"clearBubbles\", blackCrowId)\r\n    \r\n    -- \"Je n'ai pas été d'une grande aide, je m'en excuse.\"\r\n    invoke_custom(17000, 1, \"bubble\", blackCrowId, \"quest.amakna.mercenary.riktuselite.02.12\")\r\n    invoke_custom(21000, 1, \"clearBubbles\", blackCrowId)\r\n    \r\n    -- \"Tu devrais rentrer chez toi et me laisser continuer.\"\r\n    invoke_custom(21500, 1, \"bubble\", playerId, \"quest.amakna.mercenary.riktuselite.02.13\")\r\n    invoke_custom(22550, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Calmer\")\r\n    invoke_custom(25500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Si je vois les objets qu'on t'a dérobé, je te les rendrai. Au fait, c'est quoi, exactement ?\"\r\n    invoke_custom(26000, 1, \"bubble\", playerId, \"quest.amakna.mercenary.riktuselite.02.14\")\r\n    invoke_custom(27550, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Pouce\")\r\n    invoke_custom(33500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"C'est, ah, euhm...\"\r\n    invoke_custom(34000, 1, \"bubble\", blackCrowId, \"quest.amakna.mercenary.riktuselite.02.15\")\r\n    invoke_custom(37000, 1, \"clearBubbles\", blackCrowId)\r\n    \r\n    -- \"Je... dois filer ! Adieu, et que nos chemins ne se recroisent pas !\"\r\n    invoke_custom(37500, 1, \"Mobile.setMobileAnimation\", blackCrowId, \"AnimKO-SortieOK\")\r\n    invoke_custom(39000, 1, \"bubble\", blackCrowId, \"quest.amakna.mercenary.riktuselite.02.16\")\r\n    invoke_custom(45000, 1, \"clearBubbles\", blackCrowId)\r\n    \r\n    -- \"**Pourvu qu'il ne mette pas la main dessus...\"\r\n    invoke_custom(45000, 1, \"bubble\", blackCrowId, \"quest.amakna.mercenary.riktuselite.02.17\")\r\n    invoke_custom(48000, 1, \"clearBubbles\", blackCrowId)\r\n    invoke_custom(48000, 1, \"Mobile.setMobileAnimation\", blackCrowId, \"AnimSort-Saut\")\r\n    invoke_custom(48800, 1, \"Mobile.setMobileVisible\", blackCrowId, false)\r\n    invoke_custom(49550, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Chercher\")\r\n    \r\n    invoke_custom(51000, 1, \"Mobile.moveMobile\", playerId, -100, -43, 0)\r\n    \r\n    invoke_custom(53000, 1, \"skipCinematic\", 19871)\nend\n\n-- [EVENT] Le joueur active un generic activable - Combat (démineur 01)\n-- \nfunction event_2345_19908()\n    \nend\n\n-- [EVENT] Combat de monstres (démineur 01) - Début\n-- \nfunction event_2345_19909(local_first_fight_id)\n    \nend\n\n-- [EVENT] Fin du combat (démineur 01) - Validation de la quête (ACH 4275 OBJ 8867)\n-- \nfunction event_2345_19910(local_first_fight_id)\n    \nend\n\n-- [EVENT] Le joueur active un generic activable - Combat (démineur 02)\n-- \nfunction event_2345_19911()\n    \nend\n\n-- [EVENT] Combat de monstres (démineur 02) - Début\n-- \nfunction event_2345_19912(local_second_fight_id)\n    \nend\n\n-- [EVENT] Fin du combat (démineur 02) - Validation de la quête (ACH 4275 OBJ 8868)\n-- \nfunction event_2345_19913(local_second_fight_id)\n    \nend\n\n-- [EVENT] Le joueur active un generic activable - Combat (démineur 03)\n-- \nfunction event_2345_20285()\n    \nend\n\n-- [EVENT] Combat de monstres (démineur 03) - Début\n-- \nfunction event_2345_20286(local_third_fight_id)\n    \nend\n\n-- [EVENT] Fin du combat (démineur 03) - Validation de la quête (ACH 4275 OBJ 8869)\n-- \nfunction event_2345_20287(local_third_fight_id)\n    \nend\n\n-- [INIT] Le joueur leave l'instance - Leave scénario\n-- \nfunction event_2345_20342()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","hideMonster","showMonster","event_2345_19868","event_2345_19848","event_2345_19859","event_2345_19850","event_2345_19872","event_2345_19890","event_2345_19849","event_2345_19867","event_2345_19870","event_2345_19871","event_2345_19908","event_2345_19909","event_2345_19910","event_2345_19911","event_2345_19912","event_2345_19913","event_2345_20285","event_2345_20286","event_2345_20287","event_2345_20342"],"quest_calls":[],"dialogue_calls":[]},"scenario/2346.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\n\n\n-- [INIT] Variables\n-- \nfunction event_2346_20343()\n    \nend\n\n-- [INIT] Le joueur entre dans l'instance - Inscription au scénario\n-- \nfunction event_2346_19857()\n    \nend\n\n-- [INIT] Le joueur leave l'instance - Leave scénario\n-- \nfunction event_2346_20344()\n    \nend\n\n-- Lancement combat Monstroplante\n-- \nfunction event_2346_19938()\n    \nend\n\n-- [EVENT] Victoire - Combat Monstroplante\n-- \nfunction event_2346_19939()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_2346_20343","event_2346_19857","event_2346_20344","event_2346_19938","event_2346_19939"],"quest_calls":[],"dialogue_calls":[]},"scenario/2347.lua":{"source":"\n\n-- [INIT] Variables\n-- \nfunction event_2347_22100()\n    \nend\n\n-- [EVENT] Le joueur entre dans l'instance - on l'inscrit au scénario\n-- \nfunction event_2347_19918()\n    \nend\n\n-- [EVENT] Un joueur utilise un parchemin de sort - Maîtrise d'Armes\n-- \nfunction event_2347_19919()\n    \nend\n\n-- [EVENT] Un joueur utilise un parchemin de sort - Fluctuation\n-- \nfunction event_2347_19920()\n    \nend\n\n-- [EVENT] Un joueur utilise un parchemin de sort - Charme de Masse\n-- \nfunction event_2347_19921()\n    \nend\n\n-- [EVENT] Un joueur utilise un parchemin de sort - Os à moelle\n-- \nfunction event_2347_19922()\n    \nend\n\n-- [PVP] Début de combat PVP\n-- \nfunction event_2347_19959()\n    \nend\n\n-- [ADMIN] Activation mode tournoi\n-- isActiveTournament = 1\nfunction event_2347_22101()\n    \nend\n\n-- [ADMIN] Désactivation mode tournoi\n-- isActiveTournament = 0\nfunction event_2347_22102()\n    \nend\n\n-- [ADMIN] Pression - Tour de joueur\n-- \nfunction event_2347_22105()\n    \nend\n\n-- [ADMIN] Pression - Tour de table\n-- \nfunction event_2347_22106()\n    \nend\n\n-- [ADMIN] Échauffement - Tour de joueur\n-- \nfunction event_2347_24304()\n    \nend\n\n-- [ADMIN] Échauffement - Tour de table\n-- \nfunction event_2347_24305()\n    \nend\n\n-- [ADMIN] Échauffement - Augmentation end\n-- \nfunction event_2347_24308()\n    \nend\n\n-- [ADMIN] Échauffement - Réduction end\n-- \nfunction event_2347_24309()\n    \nend\n\n-- [ADMIN] Échauffement - Augmentation valeur\n-- \nfunction event_2347_24310()\n    \nend\n\n-- [ADMIN] Échauffement - Réduction valeur\n-- \nfunction event_2347_24311()\n    \nend\n\n-- [ADMIN] Résistance fight - Augmentation valeur\n-- \nfunction event_2347_24306()\n    \nend\n\n-- [ADMIN] Résistance fight - Réduction valeur\n-- \nfunction event_2347_24307()\n    \nend\n\n-- [ADMIN] Malus résistance - Augmentation valeur\n-- \nfunction event_2347_22103()\n    \nend\n\n-- [ADMIN] Malus résistance - Réduction valeur\n-- \nfunction event_2347_22104()\n    \nend\n\n-- [ADMIN] Malus résistance - Augmentation start\n-- \nfunction event_2347_24294()\n    \nend\n\n-- [ADMIN] Malus résistance - Réduction start\n-- \nfunction event_2347_24295()\n    \nend\n\n-- [ADMIN] Malus résistance - Augmentation fréquence\n-- \nfunction event_2347_24296()\n    \nend\n\n-- [ADMIN] Malus résistance - Réduction fréquence\n-- \nfunction event_2347_24297()\n    \nend\n\n-- [ADMIN] Incurable et Friable - Augmentation valeur\n-- \nfunction event_2347_24298()\n    \nend\n\n-- [ADMIN] Incurable et Friable - Réduction valeur\n-- \nfunction event_2347_24299()\n    \nend\n\n-- [ADMIN] Incurable et Friable - Augmentation start\n-- \nfunction event_2347_24300()\n    \nend\n\n-- [ADMIN] Incurable et Friable - Réduction valeur\n-- \nfunction event_2347_24301()\n    \nend\n\n-- [ADMIN] Incurable et Friable - Augmentation fréquence\n-- \nfunction event_2347_24302()\n    \nend\n\n-- [ADMIN] Incurable et Friable - Réduction fréquence\n-- \nfunction event_2347_24303()\n    \nend\n\n-- [ADMIN] Mort subite - Augmentation valeur start\n-- \nfunction event_2347_22956()\n    \nend\n\n-- [ADMIN] Mort subite - Réduction valeur start\n-- \nfunction event_2347_22957()\n    \nend\n\n-- [ADMIN] Mort subit - Augmentation fréquence\n-- \nfunction event_2347_22958()\n    \nend\n\n-- [ADMIN] Mort subite - Réduction fréquence\n-- \nfunction event_2347_22959()\n    \nend\n\n-- [ADMIN] Reset toutes les valeurs du mode tournoi\n-- \nfunction event_2347_24293()\n    \nend\n\n-- [ADMIN] Don artefact \"Hache d'Othan\"\n-- \nfunction event_2347_22415()\n    \nend\n\n-- EXIT_INSTANCE\n-- \nfunction event_2347_21675()\n    UI.hideButton()\nend\n\n-- [EVENT] Le joueur entre dans l'instance principale (guide bêta)\n-- \nfunction event_2347_22952()\n    UI.loadGuideDialog(174)\nend\n\n","functions":["event_2347_22100","event_2347_19918","event_2347_19919","event_2347_19920","event_2347_19921","event_2347_19922","event_2347_19959","event_2347_22101","event_2347_22102","event_2347_22105","event_2347_22106","event_2347_24304","event_2347_24305","event_2347_24308","event_2347_24309","event_2347_24310","event_2347_24311","event_2347_24306","event_2347_24307","event_2347_22103","event_2347_22104","event_2347_24294","event_2347_24295","event_2347_24296","event_2347_24297","event_2347_24298","event_2347_24299","event_2347_24300","event_2347_24301","event_2347_24302","event_2347_24303","event_2347_22956","event_2347_22957","event_2347_22958","event_2347_22959","event_2347_24293","event_2347_22415","event_2347_21675","event_2347_22952"],"quest_calls":[],"dialogue_calls":[]},"scenario/2348.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\n\n\n-- [INIT] Variables\n-- \nfunction event_2348_19926()\n    \nend\n\n-- ~[INIT] Le joueur entre dans l'instance - Inscription au scénario\n-- \nfunction event_2348_19923()\n    \nend\n\n-- [EVENT] Lancement Cinématique Faille Supérieure\n-- \nfunction event_2348_19924()\n    ----------------------------- RECUPERATIONS DES INFOS JOUEUR --------------------------\r\n    \r\n    \tlocal playerId = Context.getLeaderId()\r\n    \tlocal playerX, playerY, playerZ = Mobile.getMobilePosition(playerId)\r\n    \r\n    \r\n    \t----------------------------- INITIALISATION DES PNJ --------------------------\r\n    \r\n    \tlocal premierCraqueleur = createActor(129001452, -48, -83, 50, 8, 1, 7)\r\n    \tlocal deuxiemeCraqueleur = createActor(129001452, -46, -83, 50, 8, 5, 7)\r\n    \tlocal apsPoussiere = -1022019411\r\n    \tlocal apsExplosion = -1436036281\r\n    \r\n    \t----------------------------- DEBUT DE CINEMATIQUE --------------------------\r\n    \r\n    \tstartCinematicContext(1.3, playerId)\r\n    \tUI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 19924)\r\n    \r\n    \t----------------------------- ACTIONS --------------------------\r\n    \r\n    \tinvoke_custom(1, 1, \"Mobile.moveMobile\", playerId, -46, -87, 50, \"Mobile.setMobileDirection\", playerId, 3)\r\n    \tinvoke_custom(0, 1, \"Mobile.setMobileAnimation\", premierCraqueleur, \"AnimSort-01\")\r\n    \tinvoke_custom(500, 1, \"Mobile.setMobileAnimation\", deuxiemeCraqueleur, \"AnimSort-01\")\r\n    \tinvoke_custom(1500, 1, \"Mobile.setMobileAnimation\", premierCraqueleur, \"AnimSort-01\")\r\n    \tinvoke_custom(2000, 1, \"Mobile.setMobileAnimation\", deuxiemeCraqueleur, \"AnimSort-01\")\r\n    \tinvoke_custom(3000, 1, \"Mobile.setMobileAnimation\", premierCraqueleur, \"AnimSort-01\")\r\n    \tinvoke_custom(3500, 1, \"Mobile.setMobileAnimation\", deuxiemeCraqueleur, \"AnimSort-01\")\r\n    \r\n    \tinvoke_custom(600, 1, \"Particle.addParticleSystem\", apsExplosion, -47, -83, 50)\r\n    \tinvoke_custom(1100, 1, \"Particle.addParticleSystem\", apsExplosion, -47, -83, 50)\r\n    \tinvoke_custom(2100, 1, \"Particle.addParticleSystem\", apsExplosion, -47, -83, 50)\r\n    \tinvoke_custom(2600, 1, \"Particle.addParticleSystem\", apsExplosion, -47, -83, 50)\r\n    \tinvoke_custom(3600, 1, \"Particle.addParticleSystem\", apsExplosion, -47, -83, 50)\r\n    \tinvoke_custom(4100, 1, \"Particle.addParticleSystem\", apsExplosion, -47, -83, 50)\r\n    \r\n    \r\n    \t-- Arrêtez tout de suite, qu'est-ce qui vous prend ?!\r\n    \tinvoke_custom(3000, 1, \"bubble\", playerId, \"quest.amakna.mercenary.craqueleur.01.04\")\r\n    \tinvoke_custom(3000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Pointer\")\r\n    \r\n    \tinvoke_custom(4500, 1, \"Mobile.setMobileDirection\", premierCraqueleur, 7)\r\n    \tinvoke_custom(5000, 1, \"Mobile.setMobileDirection\", deuxiemeCraqueleur, 7)\r\n    \r\n    \tinvoke_custom(5500, 1, \"Mobile.moveMobile\", premierCraqueleur, -48, -80, 50, \"Mobile.setMobileDirection\", premierCraqueleur, 3)\r\n    \tinvoke_custom(5500, 1, \"Mobile.moveMobile\", deuxiemeCraqueleur, -46, -80, 50, \"Mobile.setMobileDirection\", deuxiemeCraqueleur, 3)\r\n    \r\n    \tinvoke_custom(7500, 1, \"Mobile.setMobileAnimation\", premierCraqueleur, \"AnimSort-03\")\r\n    \tinvoke_custom(7500, 1, \"Mobile.setMobileAnimation\", deuxiemeCraqueleur, \"AnimSort-03\")\r\n    \r\n    \tinvoke_custom(8000, 1, \"Mobile.setMobileVisible\", premierCraqueleur, false)\r\n    \tinvoke_custom(8010, 1, \"Mobile.setMobilePosition\", premierCraqueleur, -48, -78, 50)\r\n    \tinvoke_custom(8020, 1, \"Mobile.setMobileAnimation\", premierCraqueleur, \"AnimTarget-03\")\r\n    \tinvoke_custom(8030, 1, \"Mobile.setMobileVisible\", premierCraqueleur, true)\r\n    \tinvoke_custom(8600, 1, \"Mobile.setMobileVisible\", premierCraqueleur, false)\r\n    \r\n    \tinvoke_custom(8000, 1, \"Mobile.setMobileVisible\", deuxiemeCraqueleur, false)\r\n    \tinvoke_custom(8010, 1, \"Mobile.setMobilePosition\", deuxiemeCraqueleur, -46, -78, 50)\r\n    \tinvoke_custom(8020, 1, \"Mobile.setMobileAnimation\", deuxiemeCraqueleur, \"AnimTarget-03\")\r\n    \tinvoke_custom(8030, 1, \"Mobile.setMobileVisible\", deuxiemeCraqueleur, true)\r\n    \tinvoke_custom(8600, 1, \"Mobile.setMobileVisible\", deuxiemeCraqueleur, false)\r\n    \r\n    \tinvoke_custom(8500, 1, \"Particle.addParticleSystem\", apsPoussiere, -44, -79, 50)\r\n    \r\n    \r\n    \r\n    \t-- Hey non, restez ici !\r\n    \tinvoke_custom(6800, 1, \"clearBubbles\", playerId)\r\n    \tinvoke_custom(7000, 1, \"bubble\", playerId, \"quest.amakna.mercenary.craqueleur.01.05\")\r\n    \tinvoke_custom(7000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Help\")\r\n    \r\n    \tinvoke_custom(10000, 1, \"Mobile.moveMobile\", playerId, -47, -81, 50, \"Mobile.setMobileDirection\", playerId, 3)\r\n    \r\n    \tinvoke_custom(9800, 1, \"clearBubbles\", playerId)\r\n    \r\n    \t-- **Cela m'apprendra à tenter le dialogue avec de stupides cailloux...\r\n    \tinvoke_custom(12000, 1, \"bubble\", playerId, \"quest.amakna.mercenary.craqueleur.01.06\")\r\n    \tinvoke_custom(12000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Non\")\r\n    \r\n    \t----------------------------- FIN DE CINEMATIQUE --------------------------\r\n    \r\n    \tinvoke_custom(16000, 1, \"Mobile.moveMobile\", playerId, playerX, playerY, playerZ)\r\n    \tinvoke(21000, 1, \"skipCinematic\", 19924)\nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_2348_19926","event_2348_19923","event_2348_19924"],"quest_calls":[],"dialogue_calls":[]},"scenario/2349.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\n\r\n\n\n-- [INIT] Variables\n-- \nfunction event_2349_19927()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2349_19928()\n    \nend\n\n-- [INIT] Le joueur leave l'instance - Leave scénario\n-- \nfunction event_2349_20345()\n    \nend\n\n-- [EVENT] Le joueur marche sur un position trigger - Cinématique\n-- \nfunction event_2349_19929()\n        ----------------------------- RECUPERATIONS DES INFOS JOUEUR --------------------------\r\n        \r\n        \tlocal playerId = Context.getLeaderId()\r\n        \tlocal playerX, playerY, playerZ = Mobile.getMobilePosition(playerId)\r\n        \r\n        \r\n        \t----------------------------- INITIALISATION DES PNJ --------------------------\r\n        \r\n        \tlocal premierCraqueleur = createActor(129001452, -87, -23, 0, 8, 5, 7)\r\n        \tlocal deuxiemeCraqueleur = createActor(129001452, -86, -33, 0, 8, 7, 7)\r\n        \tlocal troisiemeCraqueleur = createActor(129001452, -92, -32, 0, 8, 7, 7)\r\n        \tlocal premierRiktus = createActor(120501767, -102, -27, 0, 8, 1, 6)\r\n        \tlocal deuxiemeRiktus = createActor(120501769, -102, -29, 0, 8, 1, 6)\r\n        \tlocal apsPoussiere = -1022019411\r\n        \tlocal apsExplosion = 1008321\r\n        \tlocal apsGravats = 7723004\r\n        \r\n        \t----------------------------- DEBUT DE CINEMATIQUE --------------------------\r\n        \r\n        \tstartCinematicContext(1.1, playerId)\r\n        \tUI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 19929)\r\n        \r\n        \t----------------------------- ACTIONS --------------------------\r\n        invoke_custom(1, 1, \"UI.displayWideScreenBand\", true, 100, 300)\r\n        \r\n        invoke_custom(600, 1, \"UI.displayWideScreenBand\", true, 20, 500)\r\n        \r\n        \r\n        \tinvoke_custom(1, 1, \"Mobile.moveMobile\", playerId, -89, -28, 1, \"Mobile.setMobileDirection\", playerId, 5)\r\n        \r\n        \tinvoke_custom(15, 1, \"Mobile.moveMobile\", premierRiktus, -93, -27, 0, \"Mobile.setMobileDirection\", premierRiktus, 1)\r\n        \tinvoke_custom(30, 1, \"Mobile.moveMobile\", deuxiemeRiktus, -93, -29, 0, \"Mobile.setMobileDirection\", deuxiemeRiktus, 1)\r\n        \r\n        \tinvoke_custom(100, 1, \"Mobile.setMobileAnimation\", premierCraqueleur, \"AnimSort-01\")\r\n        \tinvoke_custom(600, 1, \"Particle.addParticleSystem\", apsExplosion, -88, -23, 0)\r\n        \tinvoke_custom(800, 1, \"Particle.addParticleSystem\", apsGravats, -87, -25, 0)\r\n        \tinvoke_custom(800, 1, \"Particle.addParticleSystem\", apsGravats, -86, -22, 0)\r\n        \r\n        \tinvoke_custom(400, 1, \"Mobile.setMobileAnimation\", deuxiemeCraqueleur, \"AnimSort-01\")\r\n        \tinvoke_custom(1000, 1, \"Particle.addParticleSystem\", apsExplosion, -86, -34, 0)\r\n        \tinvoke_custom(1200, 1, \"Particle.addParticleSystem\", apsGravats, -84, -32, 0)\r\n        \tinvoke_custom(1200, 1, \"Particle.addParticleSystem\", apsGravats, -87, -32, 0)\r\n        \r\n        \tinvoke_custom(500, 1, \"Mobile.setMobileAnimation\", troisiemeCraqueleur, \"AnimSort-01\")\r\n        \tinvoke_custom(1100, 1, \"Particle.addParticleSystem\", apsExplosion, -92, -33, 0)\r\n        \tinvoke_custom(1300, 1, \"Particle.addParticleSystem\", apsGravats, -92, -30, 0)\r\n        \r\n        \tinvoke_custom(2500, 1, \"Mobile.setMobileAnimation\", premierCraqueleur, \"AnimSort-01\")\r\n        \tinvoke_custom(3100, 1, \"Particle.addParticleSystem\", apsExplosion, -88, -23, 0)\r\n        \tinvoke_custom(3400, 1, \"Particle.addParticleSystem\", apsGravats, -87, -25, 0)\r\n        \tinvoke_custom(3300, 1, \"Particle.addParticleSystem\", apsGravats, -86, -22, 0)\r\n        \r\n        \tinvoke_custom(4200, 1, \"Mobile.setMobileAnimation\", deuxiemeCraqueleur, \"AnimSort-01\")\r\n        \tinvoke_custom(4800, 1, \"Particle.addParticleSystem\", apsExplosion, -86, -34, 0)\r\n        \tinvoke_custom(5000, 1, \"Particle.addParticleSystem\", apsGravats, -84, -32, 0)\r\n        \tinvoke_custom(4900, 1, \"Particle.addParticleSystem\", apsGravats, -87, -32, 0)\r\n        \r\n        \tinvoke_custom(2900, 1, \"Mobile.setMobileAnimation\", troisiemeCraqueleur, \"AnimSort-01\")\r\n        \tinvoke_custom(3500, 1, \"Particle.addParticleSystem\", apsExplosion, -92, -33, 0)\r\n        \tinvoke_custom(3700, 1, \"Particle.addParticleSystem\", apsGravats, -92, -30, 0)\r\n        \r\n        \tinvoke_custom(4600, 1, \"Mobile.setMobileAnimation\", premierCraqueleur, \"AnimSort-01\")\r\n        \tinvoke_custom(5200, 1, \"Particle.addParticleSystem\", apsExplosion, -88, -23, 0)\r\n        \tinvoke_custom(5400, 1, \"Particle.addParticleSystem\", apsGravats, -87, -25, 0)\r\n        \tinvoke_custom(5500, 1, \"Particle.addParticleSystem\", apsGravats, -86, -22, 0)\r\n        \r\n        \tinvoke_custom(5800, 1, \"Mobile.setMobileAnimation\", deuxiemeCraqueleur, \"AnimSort-01\")\r\n        \tinvoke_custom(6400, 1, \"Particle.addParticleSystem\", apsExplosion, -86, -34, 0)\r\n        \tinvoke_custom(6200, 1, \"Particle.addParticleSystem\", apsGravats, -84, -32, 0)\r\n        \tinvoke_custom(6300, 1, \"Particle.addParticleSystem\", apsGravats, -87, -32, 0)\r\n        \r\n        \tinvoke_custom(4400, 1, \"Mobile.setMobileAnimation\", troisiemeCraqueleur, \"AnimSort-01\")\r\n        \tinvoke_custom(5000, 1, \"Particle.addParticleSystem\", apsExplosion, -92, -33, 0)\r\n        \tinvoke_custom(5200, 1, \"Particle.addParticleSystem\", apsGravats, -92, -30, 0)\r\n        \r\n        \tinvoke_custom(6600, 1, \"Mobile.setMobileAnimation\", premierCraqueleur, \"AnimSort-01\")\r\n        \tinvoke_custom(7200, 1, \"Particle.addParticleSystem\", apsExplosion, -88, -23, 0)\r\n        \tinvoke_custom(7400, 1, \"Particle.addParticleSystem\", apsGravats, -87, -25, 0)\r\n        \tinvoke_custom(7500, 1, \"Particle.addParticleSystem\", apsGravats, -86, -22, 0)\r\n        \r\n        \tinvoke_custom(8800, 1, \"Mobile.setMobileAnimation\", deuxiemeCraqueleur, \"AnimSort-01\")\r\n        \tinvoke_custom(9400, 1, \"Particle.addParticleSystem\", apsExplosion, -86, -34, 0)\r\n        \tinvoke_custom(9200, 1, \"Particle.addParticleSystem\", apsGravats, -84, -32, 0)\r\n        \tinvoke_custom(9300, 1, \"Particle.addParticleSystem\", apsGravats, -87, -32, 0)\r\n        \r\n        \tinvoke_custom(8400, 1, \"Mobile.setMobileAnimation\", troisiemeCraqueleur, \"AnimSort-01\")\r\n        \tinvoke_custom(9000, 1, \"Particle.addParticleSystem\", apsExplosion, -92, -33, 0)\r\n        \tinvoke_custom(9200, 1, \"Particle.addParticleSystem\", apsGravats, -92, -30, 0)\r\n        \r\n        \tinvoke_custom(8200, 1, \"Mobile.setMobileAnimation\", premierCraqueleur, \"AnimSort-01\")\r\n        \tinvoke_custom(8400, 1, \"Particle.addParticleSystem\", apsExplosion, -88, -23, 0)\r\n        \tinvoke_custom(8550, 1, \"Particle.addParticleSystem\", apsGravats, -87, -25, 0)\r\n        \tinvoke_custom(8600, 1, \"Particle.addParticleSystem\", apsGravats, -86, -22, 0)\r\n        \r\n        \tinvoke_custom(10400, 1, \"Mobile.setMobileAnimation\", deuxiemeCraqueleur, \"AnimSort-01\")\r\n        \tinvoke_custom(11000, 1, \"Particle.addParticleSystem\", apsExplosion, -86, -34, 0)\r\n        \tinvoke_custom(11200, 1, \"Particle.addParticleSystem\", apsGravats, -84, -32, 0)\r\n        \tinvoke_custom(11300, 1, \"Particle.addParticleSystem\", apsGravats, -87, -32, 0)\r\n        \r\n        \tinvoke_custom(9900, 1, \"Mobile.setMobileAnimation\", troisiemeCraqueleur, \"AnimSort-01\")\r\n        \tinvoke_custom(10500, 1, \"Particle.addParticleSystem\", apsExplosion, -92, -33, 0)\r\n        \tinvoke_custom(10750, 1, \"Particle.addParticleSystem\", apsGravats, -92, -30, 0)\r\n        \r\n        \r\n        \t-- Hey ! Qu'est-ce que tu fiches ici ?!\r\n        \tinvoke_custom(2500, 1, \"bubble\", premierRiktus, \"quest.amakna.mercenary.craqueleur.03.01\")\r\n        \tinvoke_custom(3000, 1, \"Mobile.setMobileAnimation\", premierRiktus, \"AnimSort-Bouclier\")\r\n        \r\n        \t-- On ne peut pas prendre de risque, le boss nous le pardonnerait pas !\r\n        \tinvoke_custom(5800, 1, \"clearBubbles\", premierRiktus)\r\n        \tinvoke_custom(6000, 1, \"bubble\", deuxiemeRiktus, \"quest.amakna.mercenary.craqueleur.03.02\")\r\n        \tinvoke_custom(6000, 1, \"Mobile.setMobileAnimation\", deuxiemeRiktus, \"AnimSort-Tonerre\")\r\n        \r\n        \t-- Craqueleurs ! Eliminez cet intrus !\r\n        \tinvoke_custom(10800, 1, \"clearBubbles\", deuxiemeRiktus)\r\n        \tinvoke_custom(11000, 1, \"bubble\", deuxiemeRiktus, \"quest.amakna.mercenary.craqueleur.03.03\")\r\n        \tinvoke_custom(11000, 1, \"Mobile.setMobileAnimation\", deuxiemeRiktus, \"AnimSort-Soigne\")\r\n        \r\n        \tinvoke_custom(11500, 1, \"Mobile.setMobileDirection\", premierCraqueleur, 7)\r\n        \tinvoke_custom(11500, 1, \"Mobile.setMobileDirection\", deuxiemeCraqueleur, 3)\r\n        \tinvoke_custom(11500, 1, \"Mobile.setMobileDirection\", troisiemeCraqueleur, 3)\r\n        \r\n        \tinvoke_custom(11550, 1, \"Mobile.moveMobile\", premierCraqueleur, -87, -26, 0)\r\n        \tinvoke_custom(13500, 1, \"Mobile.moveMobile\", premierCraqueleur, -89, -26, 0, \"Mobile.setMobileDirection\", premierCraqueleur, 7)\r\n    \r\n    \t\tinvoke_custom(11500, 1, \"Mobile.moveMobile\", deuxiemeCraqueleur, -86, -30, 0)\r\n        \tinvoke_custom(13000, 1, \"Mobile.moveMobile\", deuxiemeCraqueleur, -86, -28, 1)\r\n        \tinvoke_custom(14500, 1, \"Mobile.moveMobile\", deuxiemeCraqueleur, -87, -28, 1, \"Mobile.setMobileDirection\", deuxiemeCraqueleur, 5)\r\n        \r\n        \tinvoke_custom(11550, 1, \"Mobile.moveMobile\", troisiemeCraqueleur, -91, -32, 0)\r\n    \t\tinvoke_custom(12500, 1, \"Mobile.moveMobile\", troisiemeCraqueleur, -91, -30, 0)\r\n        \tinvoke_custom(13500, 1, \"Mobile.moveMobile\", troisiemeCraqueleur, -91, -28, 1, \"Mobile.setMobileDirection\", troisiemeCraqueleur, 1)\r\n        \r\n        \r\n        \t-- ** Ça commence à chauffer ...\r\n        \tinvoke_custom(14000, 1, \"bubble\", playerId, \"quest.amakna.mercenary.craqueleur.03.04\")\r\n        \tinvoke_custom(14000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Help\")\r\n     \t\tinvoke_custom(16000, 1, \"Mobile.setMobileDirection\", playerId, 1)\r\n            invoke_custom(16100, 1, \"Mobile.setMobileDirection\", playerId, 3)\r\n    \t\tinvoke_custom(16300, 1, \"Mobile.setMobileDirection\", playerId, 5)\r\n    \t\tinvoke_custom(16500, 1, \"Mobile.setMobileDirection\", playerId, 1)\r\n        \r\n        \tinvoke_custom(14050, 1, \"Mobile.moveMobile\", premierRiktus, -102, -27, 0, \"Mobile.setMobileDirection\", premierRiktus, 5)\r\n        \tinvoke_custom(14060, 1, \"Mobile.moveMobile\", deuxiemeRiktus, -107, -29, 0, \"Mobile.setMobileDirection\", deuxiemeRiktus, 5)\r\n        \r\n        \t----------------------------- FIN DE CINEMATIQUE --------------------------\r\n    \tinvoke_custom(17000, 1, \"UI.displayWideScreenBand\", true, 100, 300)\r\n    \tinvoke_custom(17999, 1, \"UI.displayWideScreenBand\", true, 25, 300)\r\n    \t\r\n        \tinvoke_custom(18500, 1, \"skipCinematic\", 19929)\nend\n\n-- [EVENT] Cinématique terminée - On lance le combat de monstres\n-- \nfunction event_2349_19930()\n    \nend\n\n-- [EVENT] Victoire - Combat Craqueleur Mine\n-- \nfunction event_2349_19933()\n    \nend\n\n-- [EVENT] Défaite - Combat Craqueleur Mine\n-- \nfunction event_2349_20380()\n    \nend\n\n-- [EVENT] Skip forcé de la Cinématique Mercenaire quand le combat commence\n-- \nfunction event_2349_20379()\n    skipCinematic()\nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_2349_19927","event_2349_19928","event_2349_20345","event_2349_19929","event_2349_19930","event_2349_19933","event_2349_20380","event_2349_20379"],"quest_calls":[],"dialogue_calls":[]},"scenario/2350.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\n\n-- [INIT] Variables Globales\n-- \nfunction event_2350_20103()\n    \nend\n\n-- [INIT] Inscription du joueur + Variables Locales\n-- \nfunction event_2350_20104()\n    \nend\n\n-- USER_GROUP_KILLED - Côté Surface - Salle 01\n-- \nfunction event_2350_20098()\n    \nend\n\n-- USER_GROUP_KILLED - Côté Mine - Salle 01\n-- \nfunction event_2350_20105()\n    \nend\n\n-- USER_GROUP_KILLED - Côté Surface - Salle 02\n-- \nfunction event_2350_20099()\n    \nend\n\n-- USER_GROUP_KILLED - Côté Mine - Salle 02\n-- \nfunction event_2350_20106()\n    \nend\n\n-- USER_GROUP_KILLED - Côté Surface - Salle 03\n-- \nfunction event_2350_20100()\n    \nend\n\n-- USER_GROUP_KILLED - Côté Mine - Salle 03\n-- \nfunction event_2350_24277()\n    \nend\n\n-- USER_GROUP_KILLED - Côté Surface - Salle 04 - BOSS\n-- \nfunction event_2350_20101()\n    \nend\n\n-- USER_GROUP_KILLED - Côté Mine - Salle 04 - BOSS\n-- \nfunction event_2350_24274()\n    \nend\n\n-- Déplace le joueur vers la salle suivante\n-- \nfunction event_2350_20107()\n    \nend\n\n-- [EVENT] Victoire - BOSS - Cinématique Mercenaire\n-- \nfunction event_2350_19937()\n    \t----------------------------- RECUPERATIONS DES INFOS JOUEUR --------------------------\r\n    \r\n    \tlocal playerId = Context.getLeaderId()\r\n    \tlocal playerX, playerY, playerZ = Mobile.getMobilePosition(playerId)\r\n    \r\n    \t----------------------------- INITIALISATION DES PNJ --------------------------\r\n    \tlocal craqueleurRoyal = createActor(129002198, 0, -68, 0, 8, 3, 8)\r\n    \r\n    \t----------------------------- DEBUT DE CINEMATIQUE --------------------------\r\n    \r\n    \tstartCinematicContext(1.1, playerId)\r\n    \tUI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 19937)\r\n    \r\n    \t----------------------------- DIALOGUES --------------------------\r\n      invoke_custom(1, 1, \"UI.displayWideScreenBand\", true, 100, 300)\r\n       \r\n    \tinvoke_custom(150, 1, \"Mobile.moveMobile\", playerId, 0, -64, 0, \"Mobile.setMobileDirection\", playerId, 7)\r\n    \r\n        invoke_custom(800, 1, \"UI.displayWideScreenBand\", true, 20, 500)\r\n        \r\n    \t-- ASSEEEEEEEEEEEZ !!!\r\n    \tinvoke_custom(1500, 1, \"bubble\", craqueleurRoyal, \"quest.amakna.mercenary.craqueleur.04.01\")\r\n    \tinvoke_custom(1500, 1, \"Mobile.setMobileAnimation\", craqueleurRoyal, \"AnimSort-CoupDuMenhir\")\r\n    \r\n    \t-- Vous... les douziens...\r\n    \tinvoke_custom(4300, 1, \"clearBubbles\", craqueleurRoyal)\r\n    \tinvoke_custom(4500, 1, \"bubble\", craqueleurRoyal, \"quest.amakna.mercenary.craqueleur.04.02\")\r\n    \tinvoke_custom(4500, 1, \"Mobile.setMobileAnimation\", craqueleurRoyal, \"AnimSort-LancePierre\")\r\n    \r\n    \t-- ...ne savez... qu'exploiter et... DÉTRUIRE !!!\r\n    \tinvoke_custom(8000, 1, \"clearBubbles\", craqueleurRoyal)\r\n    \tinvoke_custom(9000, 1, \"bubble\", craqueleurRoyal, \"quest.amakna.mercenary.craqueleur.04.03\")\r\n    \tinvoke_custom(9000, 1, \"Mobile.setMobileAnimation\", craqueleurRoyal, \"AnimSort-LancePierre\")\r\n    \tinvoke_custom(11000, 1, \"Mobile.setMobileAnimation\", craqueleurRoyal, \"AnimSort-CoupDuMenhir\")\r\n    \r\n    \t-- C'est vous qui menacez les douziens en détruisant la montagne aveuglément !\r\n    \tinvoke_custom(13800, 1, \"clearBubbles\", craqueleurRoyal)\r\n    \tinvoke_custom(13990, 1, \"Mobile.setMobileDirection\", playerId, 7)\r\n    \tinvoke_custom(14000, 1, \"bubble\", playerId, \"quest.amakna.mercenary.craqueleur.04.04\")\r\n    \tinvoke_custom(14000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Non\")\r\n    \r\n    \t-- Mes enfants...\r\n    \tinvoke_custom(20800, 1, \"clearBubbles\", playerId)\r\n    \tinvoke_custom(21000, 1, \"bubble\", craqueleurRoyal, \"quest.amakna.mercenary.craqueleur.04.05\")\r\n    \r\n    \t-- ... ils détiennent... mes ENFANTS !!!\r\n    \tinvoke_custom(24500, 1, \"clearBubbles\", craqueleurRoyal)\r\n    \tinvoke_custom(25500, 1, \"bubble\", craqueleurRoyal, \"quest.amakna.mercenary.craqueleur.04.06\")\r\n    \tinvoke_custom(27000, 1, \"Mobile.setMobileAnimation\", craqueleurRoyal, \"AnimSort-CoupDuMenhir\")\r\n    \r\n    \t-- Et je les libérerai, je vous en fais la promesse !\r\n    \tinvoke_custom(29800, 1, \"clearBubbles\", craqueleurRoyal)\r\n    \tinvoke_custom(30000, 1, \"bubble\", playerId, \"quest.amakna.mercenary.craqueleur.04.07\")\r\n    \tinvoke_custom(30000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Pointer\")\r\n    \r\n    \t-- Mais vous devez arrêter de détruire la montagne, ces bandits sont également les ennemis d'Amakna, nous allons nous en occuper.\r\n    \tinvoke_custom(34800, 1, \"clearBubbles\", playerId)\r\n    \tinvoke_custom(35000, 1, \"bubble\", playerId, \"quest.amakna.mercenary.craqueleur.04.08\")\r\n    \tinvoke_custom(35000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Calmer\")\r\n    \r\n    \t-- ...\r\n    \tinvoke_custom(40800, 1, \"clearBubbles\", playerId)\r\n    \tinvoke_custom(41000, 1, \"bubble\", craqueleurRoyal, \"quest.amakna.mercenary.craqueleur.04.09\")\r\n    \r\n    \t-- ... Les pierres... Les pierres vous... font confiance...\r\n    \tinvoke_custom(42800, 1, \"clearBubbles\", craqueleurRoyal)\r\n    \tinvoke_custom(43000, 1, \"bubble\", craqueleurRoyal, \"quest.amakna.mercenary.craqueleur.04.10\")\r\n    \r\n    \t-- Très bien... Ne trahissez pas les Craqueleurs... ou la montagne tombera.\r\n    \tinvoke_custom(47300, 1, \"clearBubbles\", craqueleurRoyal)\r\n    \tinvoke_custom(47500, 1, \"bubble\", craqueleurRoyal, \"quest.amakna.mercenary.craqueleur.04.11\")\r\n    \tinvoke_custom(47500, 1, \"Mobile.setMobileAnimation\", craqueleurRoyal, \"AnimSort-LancePierre\")\r\n    \r\n    \t-- Je retourne... à mon sommeil. Adieu... héros douzien.\r\n    \tinvoke_custom(52800, 1, \"clearBubbles\", craqueleurRoyal)\r\n    \tinvoke_custom(53000, 1, \"bubble\", craqueleurRoyal, \"quest.amakna.mercenary.craqueleur.04.12\")\r\n    \tinvoke_custom(56500, 1, \"Mobile.setMobileAnimation\", craqueleurRoyal, \"AnimMort\")\r\n    \r\n    \r\n    \r\n    \t----------------------------- FIN DE CINEMATIQUE --------------------------\r\n    \tinvoke_custom(57000, 1, \"UI.displayWideScreenBand\", true, 100, 300)\r\n    \tinvoke_custom(57500, 1, \"Mobile.moveMobile\", playerId, playerX, playerY, playerZ)\r\n    \tinvoke_custom(57999, 1, \"UI.displayWideScreenBand\", true, 25, 300)\r\n    \t\r\n    \tinvoke(58000, 1, \"skipCinematic\", 19937)\nend\n\n-- [EVENT] Combat 02 - Côté Mine - Lancement - On applique le buff aux Craqueleurs\n-- \nfunction event_2350_20160()\n    \nend\n\n-- [EXPLOIT] Combat gagné - on incrémente le compteur \"win\" de 1\n-- \nfunction event_2350_20158(win)\n    \nend\n\n-- [EXPLOIT] Validation (ACH 4489)\n-- \nfunction event_2350_20490(dungeonStarted)\n    \nend\n\n-- [ARCHI] Apparition de l'Archimonstre\n-- \nfunction event_2350_23947()\n    \nend\n\n-- FIGHT_STARTED - Côté Surface\n-- \nfunction event_2350_24275()\n    \nend\n\n-- FIGHT_STARTED - Côté Mine\n-- \nfunction event_2350_24276()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_2350_20103","event_2350_20104","event_2350_20098","event_2350_20105","event_2350_20099","event_2350_20106","event_2350_20100","event_2350_24277","event_2350_20101","event_2350_24274","event_2350_20107","event_2350_19937","event_2350_20160","event_2350_20158","event_2350_20490","event_2350_23947","event_2350_24275","event_2350_24276"],"quest_calls":[],"dialogue_calls":[]},"scenario/2351.lua":{"source":" -- CONSTANTE --\r\n\r\n_DEBUG = false\r\n\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n-- TRIGGER CLIENT --\r\n-- 0 = Fin cinématique VIDEO | Déclenché par le callback Video.addVideoStopOrEndCallback\r\n-- 1 = Arrivée dans l'instance | Déclenché par onInstanceLoaded() callback par Event.runOnInstanceLoaded (cf code Global)\r\n-- 2 = Fin cinématique | Déclenché par stopCinematicContext() (cf code Global)\r\n-- 3 = Fermeture UI Fin de combat\r\n-- 4 = Clic sur le bon bouton de changement d'oriention (parmis les 4) dans UI worldAndFightBar pour s'orientation vers le monstre\r\n-- 5 = Fermeture UI Fiche combattant\r\n-- 6 = Clic sur le bouton de validation de la répartition dans UI Aptitudes\r\n-- 7 = Clic sur la boussole du bon objectif dans l'UI suivi de quête\r\n-- 8 = Fermeture UI Map Monde\r\n\r\n-- VARIABLE GLOBALE - SCRIPT --\r\n\r\nwidget_visible = {}\r\nwidget_enable = {}\r\nui_tweens = {}\r\nui_particles = {}\r\nui_listener_load = {}\r\nui_listener_unload = {}\r\nui_listener_event = {}\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\nscreenEffectId = nil\r\n\r\n-- VARIABLE GLOBALE - MOBILE CINEMATIQUE & TUTO --\r\n\r\nANM_otomai = {think=\"AnimComp-Special03\", talk=\"AnimComp-Special04-Debut\", show=\"AnimComp-Special05-Debut\", nice=\"AnimComp-Special07\", nope=\"AnimComp-Special08\", lol=\"AnimComp-Special09\", stop_it=\"AnimComp-Special10\", come_here=\"AnimComp-Special01\", wave_hit=\"AnimComp-Special02\", fly=\"AnimStatique-Oiseau\", cast=\"AnimSort-01\", supercast=\"AnimComp-Special11\", attack=\"AnimSort-Cast\", balance=\"AnimComp-Special06\"}\r\nANM_melee = {attack=\"AnimSort-Morsure\", glitch1=\"AnimComp-Glitch01\", glitch2=\"AnimComp-Glitch02\", glitch3=\"AnimComp-Glitch03\", roar=\"AnimComp-Agressif\"}\r\nANM_range = {attack=\"AnimSort-01\", glitch=\"AnimComp-Glitch\", dupli=\"AnimComp-Dupli\"}\r\nANM_boss = {attack1=\"AnimSort-Estoc\", attack2=\"AnimSort-Hrargh\", glitch=\"AnimComp-Glitch\", dupli=\"AnimComp-Dupli\", roar=\"AnimComp-Hurle\", ko = \"AnimKO-SortieOK\", death= \"AnimKO-SortieHS\"}\r\n\r\nNPC_otomai = Mobile.generateClientMobileId()\r\nNPC_otomai_gfx = 181404009\r\nNPC_otomai_particleZ = 10\r\nNPC_otomai_bubbleX = 10\r\nNPC_otomai_bubbleY = 70\r\n\r\nNPC_melee = Mobile.generateClientMobileId()\r\nNPC_meleeB = Mobile.generateClientMobileId()\r\nNPC_melee_gfx = 181404014\r\nNPC_melee_particleZ = 5\r\n\r\nNPC_range = Mobile.generateClientMobileId()\r\nNPC_range_gfx = 181404015\r\nNPC_range_particleZ = 3\r\n\r\nNPC_boss = Mobile.generateClientMobileId()\r\nNPC_boss_gfx = 181404012\r\nNPC_boss_particleZ = 8\r\n\r\nNPC_eni_wakfu = Mobile.generateClientMobileId()\r\nNPC_eni_wakfu_gfx = 181404034\r\nNPC_eni_wakfu_particleZ = 7\r\n\r\nNPC_eni_stasis = Mobile.generateClientMobileId()\r\nNPC_eni_stasis_gfx = 181404013\r\nNPC_eni_stasis_particleZ = 7\r\n\r\n_ACTOR_LIST = {NPC_otomai, NPC_melee, NPC_meleeB, NPC_range, NPC_boss, NPC_eni_wakfu, NPC_eni_stasis}\r\n\r\n-- VARIABLE GLOBALE - PARTICULE CINEMATIQUE & TUTO --\r\n\r\n-- UI TUTO\r\napsArrowBig = {6001069,6001070,6001071,6001072,6001073,6001074,6001075,6001076}\r\napsArrow = {6001061,6001062,6001063,6001064,6001065,6001066,6001067,6001068}\r\napsCenter = {ap=6001090, mp=6001091, wp=6001092, hp=6001093}\r\napsFollowBorder = -1548037644\r\n-- WORLD TUTO\r\napsCell = {white_border=800578, red_border=800579, white_arrow=800576, red_arrow=800577, white=800581, red=800582, show=78900}\r\n-- CINEMATIQUE\r\napsWave = {spawn=800573, wave=800574, hit=800575}\r\napsOtomai = {shield=-1814057071, transform=-1814057072, playershield = -1814057074}\r\napsCristal = {base=71071022, react=800580, shield=71071021}\r\napsBoss = {death=-1814057073}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n    for index, value in ipairs (tab) do\r\n\t\tif isEqual(value, val) then\r\n            return true\r\n        end\r\n    end\r\n\r\n    return false\t\r\nend\r\n\r\n-- FONCTION UI -- Replace le Chat en bas à gauche et le rend indéplaçable/déplaçable\r\nfunction prepareChatUI(movable, chatOffsetX)\r\n\tif not UI.isDialogLoaded(\"chatDialog0\") then return end\r\n\t\r\n\tif (not chatOffsetX) then chatOffsetX = 0 end\r\n\t\r\n\tUI.setPosition(\"chatDialog0\", chatOffsetX, 0)\r\n\tUI.setWindowMovable(\"chatDialog0\", movable)\r\nend\r\n\r\n-- FONCTION UI -- Replace le Suivi de Quête mi-hauteur à gauche et le rend indéplaçable/déplaçable\r\nfunction prepareFollowQuestUI(movable)\r\n    local dialogName = \"\"\r\n    if UI.isDialogLoaded(\"verticalFollowedAchievementsDialog\") then\r\n        dialogName = \"verticalFollowedAchievementsDialog\"\r\n    end\r\n    if UI.isDialogLoaded(\"followedAchievementsDialog\") then\r\n        dialogName = \"followedAchievementsDialog\"\r\n    end\r\n\r\n    if (dialogName == \"\") then\r\n        return\r\n    end\r\n\r\n    local screenH, screenW = UI.getWindowSize()\r\n    local x, y = UI.getPosition(dialogName)\r\n\r\n    UI.setPosition(dialogName, x, screenH / 4)\r\n    UI.setWindowMovable(dialogName, movable)\r\nend\r\n\r\n-- FONCTION UI -- Rend Visible/Invisible certains éléments des interfaces\r\nfunction prepareUI(visible)\r\n  --Interface Boutique & Cadeau\r\n  setWidgetVisible(\"topHudDialog\", \"optionShopButton\", visible)\r\n  setWidgetVisible(\"topHudDialog\", \"giftButton\", visible)\r\n\r\n  --UI sous le Coeur\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"wakfuStasisBar\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"xpBar\", visible)\r\n\r\n  --Boutons hors combat à droite du Coeur\r\n  setWidgetVisible(\"shortcutBarDialog\", \"previousButton\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"nextButton\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseShortcutBar1\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseShortcutBar2\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseShortcutBar3\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseShortcutBar4\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"shortcutBarItemButton\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"shortcutBarSpellButton\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseButtonContainerForTuto1\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseButtonContainerForTuto2\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseButtonContainerForTuto3\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseButtonContainerForTuto4\", visible)\r\n\r\n  --Boutons hors combat à gauche de l'écran - barre d'interfaces\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"firstInterfaceBarBackground\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"secondInterfaceBarBackground\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"extraInterfaceBarDrawerButton\", visible)\r\n\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"fightInfoBtn\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"inventoryButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"buildSheetSetButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"craftButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"questsButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"dungeonButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"cosmeticsButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"tutorialBookButton\", visible)\r\n\r\n  --Boutons hors combat à gauche de l'écran - barre d'interfaces (deuxième barre)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"contactListButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"guildButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"companionsButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"nationButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"battlegroundButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"passportButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"emoteButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"encyclopediaButton\", visible)\r\n\r\n  --Boutons hors combat \"actions rapides\"\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"OverWorldActionsBackground\", visible)\r\n\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"dimensionalBagButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"mapButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"rideMountButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"miniMapButton\", visible)\r\n\r\n  --Boutons en combat à gauche du Coeur\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"FightActionsBackground\", visible)\r\n\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"giveUpButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"hideFightersButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"tacticalModeBtn\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"reportCellBtn\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"fightMarkerBtn\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"lockFightBtn\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"resistanceOverheadBtn\", visible)\r\nend\r\n\r\n-- FONCTION SHORTCUT -- Rend Actif/Inactif certains raccourcis\r\nfunction prepareShortcuts(enabled, shortcutType)\r\n  if not shortcutType or shortcutType == \"WORLD\" then\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.world\", \"enterLeaveBag\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.world\", \"switchHero0\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.world\", \"switchHero1\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.world\", \"switchHero2\")\r\n  end\r\n  if not shortcutType or shortcutType == \"DISPLAY\" then\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"zoomIn\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"zoomOut\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"closeWindows\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"setLODLevel\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"setFightLODLevel\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"showHideNameOverheadsCommand\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"hideFightOccluders\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"alphaMask\")\r\n  end\r\n  if not shortcutType or shortcutType == \"CHAT\" then\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.chat\", \"chat\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.chat\", \"lastContact\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.chat\", \"firstContact\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.chat\", \"autoCompletePlayerName\")\r\n    for bind=1, 9, 1 do\r\n      UI.setShortcutEnabled(enabled, \"shortcutCategory.shortcutBar\", \"bind\" .. toString(bind))\r\n    end\r\n  end\r\n\r\n  if not shortcutType or shortcutType == \"FIGHT\" then\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"fighterTransparency\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"switchTacticalView\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"nextSelectedFighter\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"giveUp\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"lockFight\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"reportCell\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"callHelp\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"displayHpBar\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"resetFightCamera\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"endPlacementAndTurn\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"closeCombatRight\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"closeCombatLeft\")\r\n  end\r\n  if not shortcutType or shortcutType == \"INTERFACE\" then\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"minimap\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"contactList\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"companionManagement\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"guild\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"craft\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"dungeonList\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"achievements\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"quests\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"emotes\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"ecosystem\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"climate\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"nation\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"partySearch\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"passport\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"almanax\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"tutorialBook\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"switchToDirectAttackCommand\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"map\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"spellsInventory\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"inventory\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"characterBook\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"osamodasSymbiot\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"shortcutBar0\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"shortcutBar1\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"shortcutBar2\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"shortcutBar3\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"additionalShortcutBar0\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"additionalShortcutBar1\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"additionalShortcutBar2\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"additionalShortcutBar3\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"changeShortcutBarType\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"downscaling\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"rewards\")\r\n\tUI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"battlegroundList\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"aptitudes\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"presets\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"encyclopedia\")\r\n  end\r\n\r\n  -- On ne bloque pas les raccourcis de sorts finalement\r\n--   if not shortcutType or shortcutType == \"SHORTCUTBAR\" then\r\n--     for bar=0,3, 1 do\r\n--       for slot=0, 9, 1 do\r\n--         UI.setShortcutEnabled(enabled, \"shortcutCategory.shortcutBar\", \"shortcut\" .. toString(bar) .. toString(slot))\r\n--       end\r\n--     end\r\n--   end\r\nend\r\n\r\n-- FONCTION UI -- Rend Visible/Invisible un élément d'une interface\r\nfunction setWidgetVisible(dialogName, widgetName, visible)\r\n  if not UI.isDialogLoaded(dialogName) then return end\r\n\r\n  UI.setWidgetVisibility(dialogName, widgetName, visible)\r\n  table.insert(widget_visible, { name = dialogName, id = widgetName, state = visible })\r\nend\r\n\r\nfunction clearWidgetVisible()\r\n  local str = \"\"\r\n  for i=#widget_visible, 1, -1 do\r\n    str = str .. toString(widget_visible[i].name) .. \"@\" .. toString(widget_visible[i].id) .. \";\"\r\n    UI.setWidgetVisibility(widget_visible[i].name, widget_visible[i].id, true)\r\n  end\r\n\r\n  widget_visible = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearWidgetVisible\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Rend Actif/Inactif un élément d'une interface\r\nfunction setWidgetEnable(dialogName, widgetName, enable)\r\n  if not UI.isDialogLoaded(dialogName) then return end\r\n\r\n  UI.setWidgetEnabled(dialogName, widgetName, enable)\r\n  table.insert(widget_enable, {name = dialogName, id = widgetName, state = enable})\r\nend\r\n\r\nfunction clearWidgetEnable()\r\n  local str = \"\"\r\n  for i=#widget_enable, 1, -1 do\r\n    str = str .. toString(widget_enable[i].name) .. \"@\" .. toString(widget_enable[i].id) .. \";\"\r\n    UI.setWidgetEnabled(widget_enable[i].name, widget_enable[i].id, true)\r\n  end\r\n\r\n  widget_enable = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearWidgetEnable\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Ajoute/Retire une TweenParticle à un élément d'une interface\r\nfunction setUIColorTween(dialogName, widgetName, duration, loop, r1, g1, b1, a1, r2, g2, b2, a2)\r\n  if not UI.isDialogLoaded(dialogName) then return end\r\n\r\n  UI.addColorTween(dialogName, widgetName, duration, loop, r1, g1, b1, a1, r2, g2, b2, a2)\r\n  table.insert(ui_tweens, {name = dialogName, id = widgetName})\r\nend\r\n\r\nfunction clearUIColorTweens(dialogName, widgetName)\r\n  local str = \"\"\r\n  for i=#ui_tweens, 1, -1 do\r\n    if ((not dialogName) or (dialogName == ui_tweens[i].name)) and ((not widgetName) or (widgetName == ui_tweens[i].id)) then\r\n      str = str .. toString(ui_tweens[i].name) .. \"@\" .. toString(ui_tweens[i].id) .. \";\"\r\n      UI.removeColorTween(ui_tweens[i].name, ui_tweens[i].id)\r\n      table.remove(ui_tweens, i)\r\n    end\r\n  end\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearUIColorTweens\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Ajoute/Retire une Particle à un élément d'une interface\r\nfunction setUIParticle(dialogName, widgetName, apsFileName, x, y, alignment, level)\r\n  if not UI.isDialogLoaded(dialogName) then return end\r\n\r\n  local particleId = UI.addParticle(dialogName, widgetName, apsFileName, x, y, alignment, level)\r\n  table.insert(ui_particles, {name = dialogName, id = widgetName})\r\n\r\n  return particleId\r\nend\r\n\r\nfunction setUIParticleBorder(dialogName, widgetName, apsFileName, x, y, alignment, level, speed)\r\n  if not UI.isDialogLoaded(dialogName) then return end\r\n\r\n  local particleId = UI.addParticleToBorder(dialogName, widgetName, apsFileName, x, y, alignment, level, speed)\r\n  table.insert(ui_particles, {name = dialogName, id = widgetName})\r\n\r\n  return particleId\r\nend\r\n\r\nfunction clearUIParticles(dialogName, widgetName)\r\n  local str = \"\"\r\n  for i=#ui_particles, 1, -1 do\r\n    if ((not dialogName) or (dialogName == ui_particles[i].name)) and ((not widgetName) or (widgetName == ui_particles[i].id)) then\r\n      str = str .. toString(ui_particles[i].name) .. \"@\" .. toString(ui_particles[i].id) .. \";\"\r\n      UI.clearParticles(ui_particles[i].name, ui_particles[i].id)\r\n      table.remove(ui_particles, i)\r\n    end\r\n  end\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearUIParticles\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Enregistre/Supprime un callback à l'ouverture d'une interface\r\nfunction addDialogLoadListener(dialog, funcName, ...)\r\n  UI.addDialogLoadedListener(dialog, funcName, unpack(arg))\r\n  table.insert(ui_listener_load,  dialog)\r\nend\r\n\r\nfunction clearDialogLoadListener(dialogName)\r\n  local str = \"\"\r\n  for i=#ui_listener_load, 1, -1 do\r\n    if (not dialogName) or (dialogName == ui_listener_load[i]) then\r\n      str = str .. toString(ui_listener_load[i]) .. \";\"\r\n      UI.removeDialogLoadedListener(ui_listener_load[i])\r\n      table.remove(ui_listener_load, i)\r\n    end\r\n  end\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearDialogLoadListener\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Enregistre/Supprime un callback à la fermeture d'une interface\r\nfunction addDialogUnloadListener(dialog, funcName, ...)\r\n  UI.addDialogUnloadedListener(dialog, funcName, unpack(arg))\r\n  table.insert(ui_listener_unload, dialog)\r\nend\r\n\r\nfunction clearDialogUnloadListener(dialogName)\r\n  local str = \"\"\r\n  for i=#ui_listener_unload, 1, -1 do\r\n    if (not dialogName) or (dialogName == ui_listener_unload[i]) then\r\n      str = str .. toString(ui_listener_unload[i]) .. \";\"\r\n      UI.removeDialogUnloadedListener(ui_listener_unload[i])\r\n      table.remove(ui_listener_unload, i)\r\n    end\r\n  end\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearDialogUnloadListener\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Enregistre/Supprime un callback sur un élément d'une interface\r\nfunction addDialogEventListener(dialog, id, eventType, funcName, ...)\r\n  if not UI.isDialogLoaded(dialog) then return end\r\n\r\n  UI.addEventListener(dialog, id, eventType, funcName, unpack(arg))\r\n  table.insert(ui_listener_event, {dialog=dialog, id=id, eventType=eventType, funcName=funcName})\r\nend\r\n\r\nfunction clearDialogEventListener(dialogName)\r\n  local str = \"\"\r\n  for i=#ui_listener_event, 1, -1 do\r\n    if (not dialogName) or (dialogName == ui_listener_event[i].dialog) then\r\n      str = str .. toString(ui_listener_event[i].dialog) .. \"@\" .. toString(ui_listener_event[i].id) .. \";\"\r\n      UI.removeEventListener(ui_listener_event[i].dialog, ui_listener_event[i].id, ui_listener_event[i].eventType, ui_listener_event[i].funcName)\r\n      table.remove(ui_listener_event, i)\r\n    end\r\n  end\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearDialogEventListener\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y , z, ...)\r\n  local particleId = Particle.addParticleSystem(particleFileId, x, y , z, unpack(arg))\r\n  table.insert(world_particles, particleId)\r\n\r\n  return particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n  local particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n  table.insert(world_particles, particleId)\r\n\r\n  return particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n  local str = \"\"\r\n  for i=#world_particles, 1, -1 do\r\n    str = str .. toString(world_particles[i]) .. \";\"\r\n    Particle.removeParticleSystem(world_particles[i])\r\n  end\r\n\r\n  world_particles = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n  BubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n  if isLower(mobileId, 0) then\r\n    BubbleText.setCharacterSpeak(mobileId, text)\r\n  else\r\n    if (not offsetY) then\r\n      local height = Mobile.getMobileHeight(mobileId)\r\n      if (not height) then height = 6 end\r\n\r\n      offsetY = height * 10\r\n    end\r\n\r\n    if (not offsetX) then offsetX = 0 end\r\n    if (not infiniteDuration) then infiniteDuration = false end\r\n\r\n    BubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n    UI.writeLocalisedInChat(text)\r\n  end\r\n\r\n  if (not tContains(bubbles, mobileId)) then\r\n    table.insert(bubbles, mobileId)\r\n  end\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n  local str = \"\"\r\n  for i = #bubbles, 1, -1 do\r\n    if (not mobileId) then\r\n      str = str .. toString(bubbles[i]) .. \";\"\r\n      BubbleText.closeBubbleAttachedTo(bubbles[i])\r\n    elseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n      str = str .. toString(bubbles[i]) .. \";\"\r\n      BubbleText.closeBubbleAttachedTo(bubbles[i])\r\n      table.remove(bubbles, i)\r\n    end\r\n  end\r\n\r\n  if (not mobileId) then bubbles = {} end\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n  local compassId = UI.addCompass(\"compass\", x, y, z)\r\n  table.insert(compasses, compassId)\r\n\r\n  return compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n  local str = \"\"\r\n  for i=#compasses, 1, -1 do\r\n    str = str .. toString(compasses[i]) .. \";\"\r\n    UI.removeCompass(compasses[i])\r\n  end\r\n\r\n  compasses = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height)\r\n  local mobileId = Mobile.generateClientMobileId()\r\n  Actor.createActor(mobileId, spriteName, worldX, worldY, worldZ, availableDirection)\r\n\r\n  if (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n  if (height) then Actor.setActorHeight(mobileId, height) end\r\n\r\n  table.insert(actors, mobileId)\r\n\r\n  return mobileId\r\nend\r\n\r\nfunction clearActors()\r\n  local str = \"\"\r\n  for i = #actors, 1, -1 do\r\n    str = str .. toString(actors[i]) .. \";\"\r\n    Actor.deleteActor(actors[i])\r\n  end\r\n\r\n  actors = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n  local taskId = invoke(delay, count, funcName, unpack(arg))\r\n  table.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n  local str = \"\"\r\n  for i=#invoke_tasks, 1, -1 do\r\n    str = str .. toString(invoke_tasks[i]) .. \";\"\r\n    interrupt(invoke_tasks[i])\r\n    desinvoke(invoke_tasks[i])\r\n  end\r\n\r\n  invoke_tasks = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n  invoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n  local taskId = setInterval(delay, funcName, unpack(arg))\r\n  table.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n  local str = \"\"\r\n  for i=#interval_tasks, 1, -1 do\r\n    str = str .. toString(interval_tasks[i]) .. \";\"\r\n    interrupt(interval_tasks[i])\r\n    desinvoke(interval_tasks[i])\r\n  end\r\n\r\n  interval_tasks = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n  if (_DEBUG) then trace(\"startCinematicContext\") end\r\n\r\n  UI.manageFrame(\"World\", false)\r\n  UI.closeMRU()\r\n  UI.closeAllBags()\r\n  UI.setUIVisible(false)\r\n  UI.displayWideScreenBand(true)\r\n  Camera.setUserZoomLocked(true)\r\n\r\n  if (cameraMobileId ~= nil)  then\r\n    Camera.setMoveSpeedFactor(10000)\r\n    Camera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n  end\r\n\r\n  if (zoomFactor ~= nil)  then\r\n    Camera.setZoomFactor(zoomFactor)\r\n  end\r\n\r\n  if (musicId ~= nil)  then\r\n    Sound.playForcedMusic(musicId)\r\n  end\r\n\r\n  if (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\nfunction skipCinematic()\r\n  local player = Context.getLeaderId()\r\n\r\n  for x = 1, #_ACTOR_LIST do\r\n    Actor.deleteActor(_ACTOR_LIST[x])\r\n  end\r\n\r\n  UI.hideButton()\r\n  clearALL()\r\n  stopCinematicContext(1, player, true)\r\n  Mobile.setMobileVisible(player, true)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n  if (_DEBUG) then trace(\"stopCinematicContext\") end\r\n\r\n  UI.displayWideScreenBand(false)\r\n  UI.setUIVisible(true)\r\n  Camera.setUserZoomLocked(false)\r\n  UI.manageFrame(\"World\", true)\r\n\r\n  Camera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n  Camera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n  if (zoomFactor ~= nil) then\r\n    Camera.setZoomFactor(zoomFactor)\r\n  end\r\n\r\n  if (cameraMobileId ~= nil) then\r\n    Camera.attachCameraToMobile(cameraMobileId)\r\n  end\r\n\r\n  if (stopMusic) then\r\n    Sound.stopForcedMusic()\r\n  end\r\n\r\n  if (_DEBUG) then\r\n    UI.hideButton()\r\n  end\r\n\r\n  --TRIGGER\r\n  Server.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Affiche/Masque une texture à l'écran\r\nfunction displayScreenEffect(enable, fadeInDur, alphaDur, fadeOutDur, r, g, b, alpha)\r\n  if (_DEBUG) then trace(\"displayScreenEffect\") end\r\n\r\n  if not enable and screenEffectId ~= nil  then\r\n    --On retire le blackScreen\r\n    Effect.stopEffect(screenEffectId)\r\n  else\r\n    --On affiche un blackScreen à l'entrée dans l'instance le temps qu'elle soit complètement chargée\r\n    screenEffectId = Effect.createFullScreenSprite(fadeInDur, alphaDur, fadeOutDur, r, g, b, alpha)\r\n  end\r\nend\r\n\r\n-- FONCTION NETTOYAGE --\r\nfunction clearALL()\r\n  clearIntervalTasks()\r\n  clearInvokeTasks()\r\n  clearBubbles()\r\n  clearUIColorTweens()\r\n  clearUIParticles()\r\n  clearWorldParticles()\r\n  clearCompasses()\r\n  clearActors()\r\n\r\n  Focus.display(false)\r\n  UI.unloadTutorialDialog()\r\nend\r\n\r\n-- FONCTION NETTOYAGE --\r\nfunction clearUI(dialogName)\r\n  clearUIColorTweens(dialogName)\r\n  clearUIParticles(dialogName)\r\nend\r\n\r\n-- FONCTION NETTOYAGE --\r\nfunction clearListener(dialogName)\r\n  clearDialogLoadListener(dialogName)\r\n  clearDialogUnloadListener(dialogName)\r\n  clearDialogEventListener(dialogName)\r\nend\r\n  \r\n function addButton()\r\n \tinvoke(2000, 1, \"UI.displayButton\", false, \"scenario.endKinematic.confirmEscape\", \"lyongameshow.vampyro.rules.display\", \"displayFightRules\")\r\n end \r\n\r\nfunction displayFightRules()\r\n\tUI.loadTutorialDialog(\"lgs.vampyro\",\"lyongameshow.vampyro.fight.title\",\"lyongameshow.vampyro.fight.desc\")\r\n\taddButton()\r\nend\r\n\r\n function onEnterInstance()  \r\n \taddButton()\r\n \t\r\n   UI.activateFollowAchievement(false)\r\n   prepareUI(false)\r\n   prepareShortcuts(false)\r\n   prepareShortcuts(true, \"DISPLAY\")\r\n   prepareShortcuts(true, \"CHAT\")\r\n   prepareShortcuts(true, \"FIGHT\")\r\n   prepareShortcuts(true, \"SHORTCUTBAR\")\r\n\r\n  UI.setShortcutEnabled(true, \"shortcutCategory.interface\", \"dungeonList\")\r\n  UI.setShortcutEnabled(true, \"shortcutCategory.interface\", \"emotes\")\r\n  UI.setShortcutEnabled(true, \"shortcutCategory.interface\", \"switchToDirectAttackCommand\")\r\n  UI.setShortcutEnabled(true, \"shortcutCategory.interface\", \"map\")\r\n  UI.setShortcutEnabled(true, \"shortcutCategory.interface\", \"spellsInventory\")\r\n  UI.setShortcutEnabled(true, \"shortcutCategory.interface\", \"characterBook\")\r\n  UI.setShortcutEnabled(true, \"shortcutCategory.interface\", \"osamodasSymbiot\")\r\n  UI.setShortcutEnabled(true, \"shortcutCategory.interface\", \"shortcutBar0\")\r\n  UI.setShortcutEnabled(true, \"shortcutCategory.interface\", \"shortcutBar1\")\r\n  UI.setShortcutEnabled(true, \"shortcutCategory.interface\", \"shortcutBar2\")\r\n  UI.setShortcutEnabled(true, \"shortcutCategory.interface\", \"shortcutBar3\")\r\n  UI.setShortcutEnabled(true, \"shortcutCategory.interface\", \"additionalShortcutBar0\")\r\n  UI.setShortcutEnabled(true, \"shortcutCategory.interface\", \"additionalShortcutBar1\")\r\n  UI.setShortcutEnabled(true, \"shortcutCategory.interface\", \"additionalShortcutBar2\")\r\n  UI.setShortcutEnabled(true, \"shortcutCategory.interface\", \"additionalShortcutBar3\")\r\n  UI.setShortcutEnabled(true, \"shortcutCategory.interface\", \"changeShortcutBarType\")\r\n  \r\n    --Boutons hors combat à droite du Coeur\r\n  setWidgetVisible(\"shortcutBarDialog\", \"previousButton\", true)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"nextButton\", true)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"addExtraBarButton\", true)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"shortcutModeButton\", true)\r\n  \r\n -- Boutons hors combat à gauche du Coeur\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"fightInfoBtn\", true)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"spellButton\", true)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"achievementDrawerButton\", true)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"mapButton\", true)\r\n\r\n--  Boutons de la catégorie achievementDrawerButton\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"dungeonButton\", true)\r\n\r\n  --Boutons en combat à gauche du Coeur\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"giveUpButton\", true)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"hideFightersButton\", true)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"reportCellBtn\", true)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"callHelpBtn\", true)\r\n end\n\n-- [INITIALISATION] Bloquage des accès pour sortir du village de Katrepat\n-- \nfunction event_2351_19942()\n    \nend\n\n-- [INITIALISATION] Bloquage du TP de sortie HUB & Porte Ombrage & Croupier\n-- \nfunction event_2351_19944()\n    \nend\n\n-- [INITIALISATION] Bloquage du TP de sortie Donjon & Spawn Vampyro\n-- \nfunction event_2351_19946()\n    \nend\n\n-- [EVENT] Le joueur entre dans l'instance - Hub\n-- \nfunction event_2351_19941()\n        function onStasisDungeonDialogLoaded()\r\n            clearUI()\r\n            clearListener()\r\n            \r\n            UI.setWidgetEnabled(\"stasisDungeonDialog\", \"modulationContainer\", false)\r\n            UI.setWidgetEnabled(\"stasisDungeonDialog\", \"modulationCheckBox\", false)\r\n            UI.setWidgetEnabled(\"stasisDungeonDialog\", \"difficultyContainer\", false)\r\n            UI.setWidgetEnabled(\"stasisDungeonDialog\", \"difficultyComboBox\", false)\r\n            UI.setWidgetEnabled(\"stasisDungeonDialog\", \"difficultyComboBoxContainer\", false)\r\n            UI.setWidgetEnabled(\"stasisDungeonDialog\", \"dungeonOptionsContainer\", false)\r\n        \r\n            UI.setWidgetVisibility(\"stasisDungeonDialog\", \"modulationContainer\", false)\r\n            UI.setWidgetVisibility(\"stasisDungeonDialog\", \"modulationCheckBox\", false)\r\n            UI.setWidgetVisibility(\"stasisDungeonDialog\", \"difficultyContainer\", false)\r\n            UI.setWidgetVisibility(\"stasisDungeonDialog\", \"difficultyComboBox\", false)\r\n            UI.setWidgetVisibility(\"stasisDungeonDialog\", \"difficultyComboBoxContainer\", false)\r\n            UI.setWidgetVisibility(\"stasisDungeonDialog\", \"dungeonOptionsContainer\", false)\r\n            \r\n    --     LISTENER\r\n            addDialogUnloadListener(\"stasisDungeonDialog\", \"init\")\r\n        end\r\n            \r\n        function init()\r\n            clearUI()\r\n            clearListener()\r\n            \r\n    --     LISTENER\r\n            addDialogLoadListener(\"stasisDungeonDialog\", \"onStasisDungeonDialogLoaded\")\r\n        end\r\n        \r\n         onEnterInstance()\r\n         init()\nend\n\n-- [EVENT] Le joueur entre dans l'instance - Donjon\n-- \nfunction event_2351_19945()\n    onEnterInstance() \nend\n\n-- [LGS] Le joueur attaque Vampyro - Lancement du Combat\n-- \nfunction event_2351_19950()\n    \nend\n\n-- [LGS] Début du combat - Spawn des Glyphes\n-- \nfunction event_2351_19951()\n    \nend\n\n-- [LGS] Fin du combat - TP dans le HUB\n-- \nfunction event_2351_19952()\n    \nend\n\n","functions":["tContains","prepareChatUI","prepareFollowQuestUI","prepareUI","prepareShortcuts","setWidgetVisible","clearWidgetVisible","setWidgetEnable","clearWidgetEnable","setUIColorTween","clearUIColorTweens","setUIParticle","setUIParticleBorder","clearUIParticles","addDialogLoadListener","clearDialogLoadListener","addDialogUnloadListener","clearDialogUnloadListener","addDialogEventListener","clearDialogEventListener","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","bubble","clearBubbles","setCompass","clearCompasses","createActor","clearActors","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","startCinematicContext","skipCinematic","stopCinematicContext","displayScreenEffect","clearALL","clearUI","clearListener","addButton","displayFightRules","onEnterInstance","event_2351_19942","event_2351_19944","event_2351_19946","event_2351_19941","onStasisDungeonDialogLoaded","init","event_2351_19945","event_2351_19950","event_2351_19951","event_2351_19952"],"quest_calls":["UI.activateFollowAchievement(false)\r"],"dialogue_calls":[]},"scenario/2352.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\n\n-- ~[INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2352_19960()\n    \nend\n\n-- [INIT] Si le joueur fait la quête dans l'équipe Rouge, ajoute bandana\n-- \nfunction event_2352_19976()\n    \nend\n\n-- [INIT] Si le joueur fait la quête dans l'équipe Jaune, ajoute bandana\n-- \nfunction event_2352_19977()\n    \nend\n\n-- [INIT] Si le joueur choisi l'équipe Rouge en parlant à Didier Grognard, ajoute bandana\n-- \nfunction event_2352_20147()\n    \nend\n\n-- [INIT] Si le joueur choisi l'équipe Jaune en parlant à Didier Grognard, ajoute bandana\n-- \nfunction event_2352_20148()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_2352_19960","event_2352_19976","event_2352_19977","event_2352_20147","event_2352_20148"],"quest_calls":[],"dialogue_calls":[]},"scenario/2353.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\n\n-- [INITIALISATION] Joueur\n-- \nfunction event_2353_19981()\n    \nend\n\n-- [INIT] Si le joueur fait la quête dans l'équipe Rouge, ajoute bandana\n-- \nfunction event_2353_19990(equipeJoueur)\n    \nend\n\n-- [INIT] Si le joueur fait la quête dans l'équipe Jaune, ajoute bandana\n-- \nfunction event_2353_19991(equipeJoueur)\n    \nend\n\n-- [COMBAT] Victoire Salle 1\n-- \nfunction event_2353_19982(equipeJoueur)\n    \tlocal equipeJoueurId = toLong(equipeJoueur)\r\n    \r\n    \tif (equipeJoueurId == 1) then\r\n    \r\n    \t\tlocal equipierRougeUn = createActor(110, -10, 1, 0, 8, 1, 6)\r\n    \r\n    \t\tActor.equip(equipierRougeUn, \"201100003\", \"CHEVEUXCUSTOM\")\r\n    \t\tActor.equip(equipierRougeUn, \"211100002\", \"VETEMENTCUSTOM\")\r\n    \t\tActor.equip(equipierRougeUn, \"13426350\", \"Chapeau\")\r\n    \t\tMobile.setPartColor(equipierRougeUn, \"Pupille\", 0.18, 0.49, 0.95, 1)\r\n    \t\tMobile.setPartColor(equipierRougeUn, \"Peau\", 0.90, 0.71, 0.58, 1)\r\n    \t\tMobile.setPartColor(equipierRougeUn, \"Cheveux\", 0.78, 0.58, 0.13, 1)\r\n    \r\n    \t\tinvoke_custom(100, 1, \"Mobile.setMobileAnimation\", equipierRougeUn, \"AnimKO-Debut\")\r\n    \t\tinvoke_custom(2000, 4, \"bubble\", equipierRougeUn, \"quest.sufokia.mercenary.kokoko.01.01\")\r\n    \r\n    \telse\r\n    \r\n    \t\tlocal equipierJauneUn = createActor(100, -9, 1, 0, 8, 1, 6)\r\n    \r\n    \t\tActor.equip(equipierJauneUn, \"201000003\", \"CHEVEUXCUSTOM\")\r\n    \t\tActor.equip(equipierJauneUn, \"211000003\", \"VETEMENTCUSTOM\")\r\n    \t\tActor.equip(equipierJauneUn, \"13426351\", \"Chapeau\")\r\n    \t\tMobile.setPartColor(equipierJauneUn, \"Pupille\", 0.03, 0.53, 0.66, 1)\r\n    \t\tMobile.setPartColor(equipierJauneUn, \"Peau\", 1.00, 0.64, 0.39, 1)\r\n    \t\tMobile.setPartColor(equipierJauneUn, \"Cheveux\", 0.46, 0.50