.kokoko.01.02\")\r\n    \r\n    \tend\nend\n\n-- [COMBAT] Victoire Salle 3 \n-- \nfunction event_2353_19986(equipeJoueur)\n    local equipeJoueurId = toLong(equipeJoueur)\r\n    \r\n    \tif (equipeJoueurId == 1) then\r\n    \t\r\n    \t\tlocal equipierRougeTrois = createActor(110, -42, -26, 0, 8, 1, 6)\r\n    \r\n    \t\tActor.equip(equipierRougeTrois, \"201100003\", \"CHEVEUXCUSTOM\")\r\n    \t\tActor.equip(equipierRougeTrois, \"211100002\", \"VETEMENTCUSTOM\")\r\n    \t\tActor.equip(equipierRougeTrois, \"13426350\", \"Chapeau\")\r\n    \t\tMobile.setPartColor(equipierRougeTrois, \"Pupille\", 0.08, 0.08, 0.08, 1)\r\n    \t\tMobile.setPartColor(equipierRougeTrois, \"Peau\", 0.81, 0.57, 0.33, 1)\r\n    \t\tMobile.setPartColor(equipierRougeTrois, \"Cheveux\", 0.21, 0.07, 0.04, 1)\r\n    \r\n    \t\tinvoke_custom(100, 1, \"Mobile.setMobileAnimation\", equipierRougeTrois, \"AnimKO-Debut\")\r\n    \t\tinvoke_custom(2000, 4, \"bubble\", equipierRougeTrois, \"quest.sufokia.mercenary.kokoko.01.03\")\r\n    \r\n    \telse\r\n    \r\n    \t\tlocal equipierJauneTrois = createActor(101, -42, -26, 0, 8, 1, 6)\r\n    \r\n    \t\tActor.equip(equipierJauneTrois, \"201010001\", \"CHEVEUXCUSTOM\")\r\n    \t\tActor.equip(equipierJauneTrois, \"211010005\", \"VETEMENTCUSTOM\")\r\n    \t\tActor.equip(equipierJauneTrois, \"13426351\", \"Chapeau\")\r\n    \t\tMobile.setPartColor(equipierJauneTrois, \"Pupille\", 0.08, 0.08, 0.08, 1)\r\n    \t\tMobile.setPartColor(equipierJauneTrois, \"Peau\", 0.43, 0.24, 0.11, 1)\r\n    \t\tMobile.setPartColor(equipierJauneTrois, \"Cheveux\", 0.08, 0.06, 0.02, 1)\r\n    \r\n    \t\tinvoke_custom(100, 1, \"Mobile.setMobileAnimation\", equipierJauneTrois, \"AnimKO-Debut\")\r\n    \t\tinvoke_custom(2000, 4, \"bubble\", equipierJauneTrois, \"quest.sufokia.mercenary.kokoko.01.03\")\r\n    \r\n    \r\n    \tend\nend\n\n-- [COMBAT] Lancement combat du BOSS\n-- \nfunction event_2353_19992()\n    \nend\n\n-- [EVENT] Victoire - BOSS - Cinématique Mercenaire\n-- \nfu