aToMobile\", playerId)\r\n    \r\n    \t\t-- Bien passons au dépouillement !\r\n    \t\tinvoke_custom(18000, 1, \"clearBubbles\", didierGrognard)\r\n    \t\tinvoke_custom(18000, 1, \"bubble\", didierGrognard, \"quest.sufokia.mercenary.kokoko.03.05\")\r\n    \t\tinvoke_custom(18000, 1, \"Mobile.setMobileAnimation\", didierGrognard, \"AnimEmote-Pointer\")\r\n    \r\n    \t\tinvoke_custom(20000, 1, \"Mobile.moveMobile\", didierGrognard, -15, -92, 0, \"Mobile.setMobileDirection\", didierGrognard, 3)\r\n    \r\n    \t\t-- Hey ! Mais je n'ai pas voté...\r\n    \t\tinvoke_custom(21300, 1, \"clearBubbles\", playerId)\r\n    \t\tinvoke_custom(21400, 1, \"Mobile.setMobileDirection\", playerId, 1)\r\n    \t\tinvoke_custom(21500, 1, \"bubble\", playerId, \"quest.sufokia.mercenary.kokoko.03.06\")\r\n    \t\tinvoke_custom(21500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Help\")\r\n    \r\n    \t\tinvoke_custom(23500, 1, \"UI.displayWideScreenBand\", true, 100, 300)\r\n    \t\tinvoke_custom(24000, 1, \"clearBubbles\", playerId)\r\n    \t\tinvoke_custom(23800, 1, \"Mobile.setMobilePosition\", didierGrognard, -19, -81, 0)\r\n    \t\tinvoke_custom(24000, 1, \"Mobile.setMobileDirection\", didierGrognard, 3)\r\n    \t\tinvoke_custom(24450, 1, \"Mobile.setMobileDirection\", playerId, 7)\r\n    \t\tinvoke_custom(24500, 1, \"UI.displayWideScreenBand\", true, 25, 300)\r\n    \r\n    \t\tinvoke_custom(25000, 1, \"Mobile.setMobileAnimation\", didierGrognard, \"AnimEmoteMarket-Parchemin-Debut\")\r\n    \r\n    \t\t-- Premier bulletin... [#name] !!!\r\n    \t\tinvoke_custom(25800, 1, \"bubble\", didierGrognard, \"quest.sufokia.mercenary.kokoko.03.07\")\r\n    \t\tinvoke_custom(25800, 1, \"Mobile.setMobileAnimation\", didierGrognard, \"AnimEmoteMarket-Parchemin-Boucle\")\r\n    \t\tinvoke_custom(28600, 1, \"Mobile.setMobileAnimation\", didierGrognard, \"AnimEmoteMarket-Parchemin-Fin\")\r\n    \r\n    \t\tinvoke_custom(26000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Non\")\r\n    \r\n    \t\tinvoke_custom(30000, 1, \"Mobile.setMobileAnimation\", didierGrognard, \"AnimEmoteMarket-Parchemin-Debut\")\r\n    \r\n    \t\t-- Deuxième bulletin... [#name] !!!\r\n    \t\tinvoke_custom(30500, 1, \"clearBubbles\", didierGrognard)\r\n    \t\tinvoke_custom(30800, 1, \"bubble\", didierGrognard, \"quest.sufokia.mercenary.kokoko.03.08\")\r\n    \t\tinvoke_custom(30800, 1, \"Mobile.setMobileAnimation\", didierGrognard, \"AnimEmoteMarket-Parchemin-Boucle\")\r\n    \r\n    \t\tinvoke_custom(32000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Non\")\r\n    \r\n    \t\tinvoke_custom(33600, 1, \"Mobile.setMobileAnimation\", didierGrognard, \"AnimEmoteMarket-Parchemin-Fin\")\r\n    \r\n    \t\t-- Héhéhé t'es cuit...\r\n    \t\tinvoke_custom(32000, 1, \"bubble\", joueurJauneTrois, \"quest.sufokia.mercenary.kokoko.03.09\")\r\n    \t\tinvoke_custom(32000, 1, \"Mobile.setMobileAnimation\", joueurJauneTrois, \"AnimEmote-Pouce\")\r\n    \t\tinvoke_custom(32000, 1, \"Mobile.setMobileDirection\", joueurJauneTrois, 5)\r\n    \t\t\r\n    \t\tinvoke_custom(35000, 1, \"Mobile.setMobileAnimation\", didierGrognard, \"AnimEmoteMarket-Parchemin-Debut\")\r\n    \r\n    \t\t-- Dernier bulletin... Kokoumba !!!\r\n    \t\tinvoke_custom(35000, 1, \"clearBubbles\", joueurJauneTrois)\r\n    \t\tinvoke_custom(35800, 1, \"bubble\", didierGrognard, \"quest.sufokia.mercenary.kokoko.03.11\")\r\n    \t\tinvoke_custom(35800, 1, \"Mobile.setMobileAnimation\", didierGrognard, \"AnimEmoteMarket-Parchemin-Boucle\")\r\n    \t\tinvoke_custom(38600, 1, \"Mobile.setMobileAnimation\", didierGrognard, \"AnimEmoteMarket-Parchemin-Fin\")\r\n    \r\n    \t\t-- Quoi?!!! Qui a fait ça ?\r\n    \t\tinvoke_custom(37000, 1, \"bubble\", joueurJauneTrois, \"quest.sufokia.mercenary.kokoko.03.12\")\r\n    \t\tinvoke_custom(37000, 1, \"Mobile.setMobileAnimation\", joueurJauneTrois, \"AnimEmote-Help\")\r\n    \t\tinvoke_custom(37000, 1, \"Mobile.setMobileDirection\", joueurJauneTrois, 7)\r\n    \t\tinvoke_custom(38500, 1, \"Mobile.setMobileDirection\", joueurJauneTrois, 5)\r\n    \r\n    \t\t-- [#name], les camarades de votre tribu ont décidé de vous éliminer et leur sentence est irrévocable.\r\n    \t\tinvoke_custom(40800, 1, \"clearBubbles\", joueurJauneTrois)\r\n    \t\tinvoke_custom(41000, 1, \"bubble\", didierGrognard, \"quest.sufokia.mercenary.kokoko.03.13\")\r\n    \t\tinvoke_custom(41000, 1, \"Mobile.setMobileAnimation\", didierGrognard, \"AnimEmote-Pointer\")\r\n    \r\n    \t\tinvoke_custom(45000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmoteMarket-HausseEpaules\")\r\n    \t\tinvoke_custom(47500, 1, \"Mobile.moveMobile\", playerId, -18, -74, 0)\r\n    \t\tinvoke_custom(47500, 1, \"clearBubbles\", didierGrognard)\r\n    \r\n    \t\tinvoke_custom(48500, 1, \"Camera.attachCameraToMobile\", joueurJauneTrois)\r\n    \t\tinvoke_custom(48500, 1, \"Camera.setZoomFactor\", 2.0)\r\n    \t\t\r\n    \t\t-- C'est toi pas vrai ?!\r\n    \t\tinvoke_custom(49000, 1, \"bubble\", joueurJauneTrois, \"quest.sufokia.mercenary.kokoko.03.14\")\r\n    \t\tinvoke_custom(49000, 1, \"Mobile.setMobileAnimation\", joueurJauneTrois, \"AnimEmote-Pointer\")\r\n    \t\tinvoke_custom(49500, 1, \"Mobile.setMobileAnimation\", joueurJauneUn, \"AnimEmote-Siffler\")\r\n    \t\tinvoke_custom(49500, 1, \"Mobile.setMobileDirection\", joueurJauneDeux, 1)\r\n    \t\tinvoke_custom(49500, 1, \"Mobile.setMobileAnimation\", joueurJauneDeux, \"AnimEmote-Siffler\")\r\n    \r\n    \t\tinvoke_custom(52500, 1, \"UI.displayWideScreenBand\", true, 100, 300)\r\n    \t\tinvoke_custom(52990, 1, \"UI.displayWideScreenBand\", true, 25, 300)\r\n    \r\n    \t\t----------------------------- FIN DE CINEMATIQUE --------------------------\r\n    \r\n    \t\tinvoke(53000, 1, \"skipCinematic\", 19994)\r\n    \r\n    \r\n    \tend\nend\n\n-- [EVENT] Téléportation du joueur à l'entrée du donjon après Cinématique du Conseil\n-- \nfunction event_2353_20146()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_2353_19981","event_2353_19990","event_2353_19991","event_2353_19982","event_2353_19984","event_2353_19986","event_2353_19992","event_2353_19993","customSkip","event_2353_19994","event_2353_20146"],"quest_calls":[],"dialogue_calls":[]},"scenario/2354.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\n\n-- ~[INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2354_20021()\n    \nend\n\n-- [INIT] Si le joueur rentre dans la maison de Malosinus (OBJ 8944 ACH 4295)\n-- \nfunction event_2354_20022()\n    local playerId = Context.getLeaderId()\r\n        \r\n    startCinematicContext(1.1, playerId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 20022)\r\n        \t\r\n    invoke_custom(100, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(100, 1, \"bubble\", playerId, \"quest.sufokia.mercenary.roublard.01.01\")\r\n        \t\r\n    invoke_custom(6000, 1, \"skipCinematic\", 20022)\nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_2354_20021","event_2354_20022"],"quest_calls":[],"dialogue_calls":[]},"scenario/2355.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\n\n-- [INIT] Variables\n-- \nfunction event_2355_20025()\n    \nend\n\n-- ~[INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2355_20023()\n    \nend\n\n-- [INIT] Si le joueur est sur Sufokia, on ajoute le Bandeau Pirate\n-- On retire si besoin le bandana de Kokolantha car celui de Roublard est prioritaire de part sa cohérence.\nfunction event_2355_20027()\n    \nend\n\n-- [EVENT] Le joueur a gagné le duel d'injures (OBJ 8951 ACH 4300)\n-- \nfunction event_2355_20024(npcBartholomew)\n    \t----------------------------- RECUPERATIONS DES INFOS JOUEUR --------------------------\r\n    \r\n    \tlocal playerId = Context.getLeaderId()\r\n    \tlocal playerX, playerY, playerZ = Mobile.getMobilePosition(playerId)\r\n    \r\n    \t----------------------------- INITIALISATION DES PNJ --------------------------\r\n    \tlocal npcBartholomew = toLong(npcBartholomew)\r\n    \tlocal mobileBartholomew = createActor(120201407, 113, -138, -56, 8, 1, 9)\r\n    \r\n    \t----------------------------- SKIP DE CINEMATIQUE PAR LE BOUTON --------------------------\r\n    \tfunction customSkip()\r\n    \t\tMobile.setMobilePosition(playerId, playerX, playerY, playerZ)\r\n    \t\tMobile.setMobileVisible(npcBartholomew, true)\r\n       \t\tUI.displayWideScreenBand(true, 25, 300)\r\n    \t\tskipCinematic(20024)\r\n    \tend\r\n    \r\n    \r\n    \t----------------------------- DEBUT DE CINEMATIQUE --------------------------\r\n    \r\n    \tstartCinematicContext(1.1, playerId)\r\n    \tUI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"customSkip\")\r\n    \r\n    \tinvoke_custom(1, 1, \"Mobile.setMobileVisible\", npcBartholomew, false)\r\n    \r\n    \t----------------------------- ACTIONS + DIALOGUES --------------------------\r\n    \r\n    \tinvoke_custom(100, 1, \"Mobile.moveMobile\", playerId, 115, -138, -55, \"Mobile.setMobileDirection\", playerId, 5)\r\n    \r\n    \r\n    \t-- Impossible !!!\r\n    \tinvoke_custom(1500, 1, \"bubble\", mobileBartholomew, \"quest.sufokia.mercenary.roublard.02.01\")\r\n    \tinvoke_custom(1500, 1, \"Mobile.setMobileAnimation\", mobileBartholomew, \"AnimHit\")\r\n    \r\n    \t-- Bwahahahah !!! Tu jures comme un vrai pirate, je me suis fait avoir comme un bleu.\r\n    \tinvoke_custom(3800, 1, \"clearBubbles\", mobileBartholomew)\r\n    \tinvoke_custom(4000, 1, \"bubble\", mobileBartholomew, \"quest.sufokia.mercenary.roublard.02.02\")\r\n    \tinvoke_custom(4000, 1, \"Mobile.setMobileAnimation\", mobileBartholomew, \"AnimApparition\")\r\n    \tinvoke_custom(5500, 1, \"Mobile.setMobileAnimation\", mobileBartholomew, \"AnimTransition\")\r\n    \r\n    \t--Cela veut dire que je fais partie des vôtres maintenant ?\r\n    \tinvoke_custom(9800, 1, \"clearBubbles\", mobileBartholomew)\r\n    \tinvoke_custom(10000, 1, \"bubble\", playerId, \"quest.sufokia.mercenary.roublard.02.03\")\r\n    \tinvoke_custom(10000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Pointer\")\r\n    \r\n    \t-- Héhé, ça marche ! Mais tu vas devoir faire quelques petites choses pour moi...\r\n    \tinvoke_custom(14800, 1, \"clearBubbles\", playerId)\r\n    \tinvoke_custom(15000, 1, \"bubble\", mobileBartholomew, \"quest.sufokia.mercenary.roublard.02.04\")\r\n    \tinvoke_custom(15000, 1, \"Mobile.setMobileAnimation\", mobileBartholomew, \"AnimSort-Larsin\")\r\n    \r\n    \t-- **Dans quoi je me suis encore embarqué{[1*]?e:} ?...\r\n    \tinvoke_custom(19000, 1, \"bubble\", playerId, \"quest.sufokia.mercenary.roublard.02.05\")\r\n    \tinvoke_custom(19000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    \r\n    \t----------------------------- FIN DE CINEMATIQUE --------------------------\r\n    \tinvoke_custom(24000, 1, \"Mobile.moveMobile\", playerId, playerX, playerY, playerZ)\r\n    \tinvoke_custom(24500, 1, \"Mobile.setMobileVisible\", npcBartholomew, true)\r\n    \tinvoke(25000, 1, \"skipCinematic\", 20024)\nend\n\n-- [EVENT] Le joueur a gagné la confiance de Bart Holomew (OBJ 8955 ACH 4300)\n-- \nfunction event_2355_20028(npcBartholomew)\n    \t----------------------------- RECUPERATIONS DES INFOS JOUEUR --------------------------\r\n    \r\n    \tlocal playerId = Context.getLeaderId()\r\n    \tlocal playerX, playerY, playerZ = Mobile.getMobilePosition(playerId)\r\n    \r\n    \t----------------------------- INITIALISATION DES PNJ --------------------------\r\n    \tlocal npcBartholomew = toLong(npcBartholomew)\r\n    \tlocal mobileBartholomew = createActor(120201407, 113, -138, -56, 8, 1, 9)\r\n    \r\n    \t----------------------------- SKIP DE CINEMATIQUE PAR LE BOUTON --------------------------\r\n    \tfunction customSkip()\r\n    \t\tMobile.setMobilePosition(playerId, playerX, playerY, playerZ)\r\n    \t\tMobile.setMobileVisible(npcBartholomew, true)\r\n       \t\tUI.displayWideScreenBand(true, 25, 300)\r\n    \t\tskipCinematic(20028)\r\n    \tend\r\n    \r\n    \r\n    \t----------------------------- DEBUT DE CINEMATIQUE --------------------------\r\n    \r\n    \tstartCinematicContext(1.1, playerId)\r\n    \tUI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"customSkip\")\r\n    \r\n    \tinvoke_custom(1, 1, \"Mobile.setMobileVisible\", npcBartholomew, false)\r\n    \r\n    \t----------------------------- ACTIONS + DIALOGUES --------------------------\r\n    \r\n    \tinvoke_custom(100, 1, \"Mobile.moveMobile\", playerId, 115, -138, -55, \"Mobile.setMobileDirection\", playerId, 5)\r\n    \r\n    \t-- Héhé, ma foi, tu as prouvé ta valeur alors écoutes bien.\r\n    \tinvoke_custom(1000, 1, \"bubble\", mobileBartholomew, \"quest.sufokia.mercenary.roublard.03.01\")\r\n    \tinvoke_custom(1000, 1, \"Mobile.setMobileAnimation\", mobileBartholomew, \"AnimSort-Larsin\")\r\n    \r\n    \t-- Nous construisons depuis plusieurs mois un navire de guerre remplis d'explosifs que nous confectionnons dans les mines.\r\n    \tinvoke_custom(4800, 1, \"clearBubbles\", mobileBartholomew)\r\n    \tinvoke_custom(5000, 1, \"bubble\", mobileBartholomew, \"quest.sufokia.mercenary.roublard.03.02\")\r\n    \tinvoke_custom(5000, 1, \"Mobile.setMobileAnimation\", mobileBartholomew, \"AnimSort-Larsin\")\r\n    \tinvoke_custom(7000, 1, \"Mobile.setMobileAnimation\", mobileBartholomew, \"AnimApparition\")\r\n    \tinvoke_custom(8500, 1, \"Mobile.setMobileAnimation\", mobileBartholomew, \"AnimTransition\")\r\n    \r\n    \t-- Cela n'a pas été de tout repos, mais on touche au but, dès que l'on aura revendu notre dernier larcin on sera prêt.\r\n    \tinvoke_custom(10800, 1, \"clearBubbles\", mobileBartholomew)\r\n    \tinvoke_custom(11000, 1, \"bubble\", mobileBartholomew, \"quest.sufokia.mercenary.roublard.03.03\")\r\n    \tinvoke_custom(11000, 1, \"Mobile.setMobileAnimation\", mobileBartholomew, \"AnimSort-Larsin\")\r\n    \r\n    \t-- Au prochain rassemblement du Cartel de Sufokia, BOUM. Bwahahahah !!!\r\n    \tinvoke_custom(15800, 1, \"clearBubbles\", mobileBartholomew)\r\n    \tinvoke_custom(16000, 1, \"bubble\", mobileBartholomew, \"quest.sufokia.mercenary.roublard.03.04\")\r\n    \tinvoke_custom(16000, 1, \"Mobile.setMobileAnimation\", mobileBartholomew, \"AnimSort-Fauchade\")\r\n    \tinvoke_custom(17200, 1, \"Mobile.setMobileAnimation\", mobileBartholomew, \"AnimApparition\")\r\n    \tinvoke_custom(18700, 1, \"Mobile.setMobileAnimation\", mobileBartholomew, \"AnimTransition\")\r\n    \r\n    \t--**C'est... c'est encore pire que ce que je pensais !\r\n    \tinvoke_custom(19800, 1, \"clearBubbles\", mobileBartholomew)\r\n    \tinvoke_custom(20000, 1, \"bubble\", playerId, \"quest.sufokia.mercenary.roublard.03.05\")\r\n    \tinvoke_custom(20000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmoteMarket-Timide\")\r\n    \r\n    \t-- Héhé, je vois que ça te laisses bouche-bée, tu devrais aller contempler la bête toi même.\r\n    \tinvoke_custom(23800, 1, \"clearBubbles\", playerId)\r\n    \tinvoke_custom(24000, 1, \"bubble\", mobileBartholomew, \"quest.sufokia.mercenary.roublard.03.06\")\r\n    \tinvoke_custom(24000, 1, \"Mobile.setMobileAnimation\", mobileBartholomew, \"AnimSort-Larsin\")\r\n    \r\n    \t-- Va au fond de la mine, je dirais aux camarades de ne pas te toucher mais ne les provoque pas trop...\r\n    \tinvoke_custom(28800, 1, \"clearBubbles\", mobileBartholomew)\r\n    \tinvoke_custom(29000, 1, \"bubble\", mobileBartholomew, \"quest.sufokia.mercenary.roublard.03.07\")\r\n    \tinvoke_custom(29000, 1, \"Mobile.setMobileAnimation\", mobileBartholomew, \"AnimSort-Fauchade\")\r\n    \r\n    \t-- C'est une taverne en apparence mais notre véritable repaire est dans l'arrière-boutique, fait en sorte de te rendre utile une fois la-bas.\r\n    \tinvoke_custom(34800, 1, \"clearBubbles\", mobileBartholomew)\r\n    \tinvoke_custom(35000, 1, \"bubble\", mobileBartholomew, \"quest.sufokia.mercenary.roublard.03.08\")\r\n    \tinvoke_custom(35000, 1, \"Mobile.setMobileAnimation\", mobileBartholomew, \"AnimSort-Larsin\")\r\n    \tinvoke_custom(37200, 1, \"Mobile.setMobileAnimation\", mobileBartholomew, \"AnimApparition\")\r\n    \tinvoke_custom(38700, 1, \"Mobile.setMobileAnimation\", mobileBartholomew, \"AnimTransition\")\r\n    \r\n    \t-- Très bien, je me mets en route !     \t\r\n    \tinvoke_custom(40800, 1, \"bubble\", playerId, \"quest.sufokia.mercenary.roublard.03.09\")\r\n    \tinvoke_custom(41000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Pointer\")\r\n    \r\n    \t----------------------------- FIN DE CINEMATIQUE --------------------------\r\n    \tinvoke_custom(44000, 1, \"Mobile.moveMobile\", playerId, playerX, playerY, playerZ)\r\n    \tinvoke_custom(44500, 1, \"Mobile.setMobileVisible\", npcBartholomew, true)\r\n    \tinvoke(45000, 1, \"skipCinematic\", 20028)\nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_2355_20025","event_2355_20023","event_2355_20027","event_2355_20024","customSkip","event_2355_20028","customSkip"],"quest_calls":[],"dialogue_calls":[]},"scenario/2356.lua":{"source":"function displayPath(room)\r\n\tlocal room = toLong(room)\r\n\t\r\n\tif ( room >= 1 or room == -1 ) then\r\n\tend\r\n\t\r\n\tif ( room >= 2 or room == -1 ) then\r\n\tend\r\n\t\r\n\tif ( room >= 3 or room == -1) then\r\n\t\r\n\tend\r\n\t\r\n\tif ( room >= 4 or room == -1) then\r\n\t\tWorld.setPictoAlpha(72, -57, 5, 0, 1000)\r\n\t    World.setPictoAlpha(73, -57, 5, 0, 1000)\r\n\t\r\n\t\tWorld.setPictoAlpha(163, -135, 0, 0, 1000)\r\n\t    World.setPictoAlpha(164, -135, 0, 0, 1000)\r\n\t    World.setPictoAlpha(163, -134, 0, 0, 1000)\r\n\t    World.setPictoAlpha(164, -134, 0, 0, 1000)\r\n\tend\r\nend\r\n\r\nfunction fight()\r\n\t\tWorld.setPictoAlpha(163, -135, 0, 1, 1000)\r\n\t    World.setPictoAlpha(164, -135, 0, 1, 1000)\r\n\t    World.setPictoAlpha(163, -134, 0, 1, 1000)\r\n\t    World.setPictoAlpha(164, -134, 0, 1, 1000)\r\nend\n\n-- [INIT] Variables Globales\n-- \nfunction event_2356_20029()\n    \nend\n\n-- [INIT] Inscription du joueur + Variables Locales\n-- \nfunction event_2356_20030(room)\n    displayPath(room)\nend\n\n-- USER_GROUP_KILLED - Salle 01\n-- \nfunction event_2356_20031(room)\n    \nend\n\n-- USER_GROUP_KILLED - Salle 02\n-- \nfunction event_2356_20032(room)\n    \nend\n\n-- USER_GROUP_KILLED - Salle 03\n-- \nfunction event_2356_20033(room)\n    displayPath(room)\nend\n\n-- [4] On lance le combat - La grille apparait sur la map de combat\n-- \nfunction event_2356_20037(room)\n    fight()\nend\n\n-- USER_GROUP_KILLED - Salle 04 - BOSS\n-- \nfunction event_2356_20034(room)\n    displayPath(room)\nend\n\n-- Déplace le joueur vers la salle suivante\n-- \nfunction event_2356_20035()\n    \nend\n\n-- [ARCHI] Apparition de l'Archimonstre\n-- \nfunction event_2356_23969()\n    \nend\n\n","functions":["displayPath","fight","event_2356_20029","event_2356_20030","event_2356_20031","event_2356_20032","event_2356_20033","event_2356_20037","event_2356_20034","event_2356_20035","event_2356_23969"],"quest_calls":[],"dialogue_calls":[]},"scenario/2357.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\n-- Infos stèle d'intervention\r\nfunction updateInterventionInfo(stateInfoId, forceDisplayUI)\r\n\r\n\tif (bubbleSteleInfoId == 0) then\r\n\t\tbubbleSteleInfoId = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_WEST\", 0, -60, false, 2147483647, true, \"interactiveBubbleDialog5\", 30000, 25000, \"onSteleInfoClosed\")\r\n\tend\r\n\r\n\tBubbleText.setText(bubbleSteleInfoId, stateInfoId)\r\n\t\r\n\tif (forceDisplayUI) then BubbleText.show(bubbleSteleInfoId) end\r\nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_2357_20052()\n    \nend\n\n-- [INIT] Variables Globales\n-- \nfunction event_2357_20168()\n    \nend\n\n-- USER_GROUP_KILLED - Spawn du BOSS en Salle 01 (Passage en Salle 02)\n-- \nfunction event_2357_20171()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 02 - BOSS\n-- \nfunction event_2357_20172(mobId)\n    \nend\n\n-- Déplace le joueur vers la salle suivante\n-- \nfunction event_2357_20173()\n    \nend\n\n-- [EVENT] Début du combat BOSS - Pose des zones flag\n-- \nfunction event_2357_20174()\n    \nend\n\n-- [EVENT] Victoire - Brise-Tibia - Cinématique spawn Remington\n-- On déclenche une cinématique  \nfunction event_2357_20236(bossRemington)\n    \t----------------------------- RECUPERATIONS DES INFOS JOUEUR --------------------------\r\n    \r\n    \tlocal playerId = Context.getLeaderId()\r\n    \r\n    \tlocal remingtonBossId = toLong(bossRemington)\r\n    \t\r\n    \t----------------------------- INITIALISATION DES PNJ --------------------------\r\n    \r\n    \tlocal apsTirRemington = -1022019405\r\n    \tlocal apsTirRemingtonImpact = -1042026792\r\n    \tlocal apsBouclier = 1018310\r\n    \r\n    \t----------------------------- SKIP DE CINEMATIQUE PAR LE BOUTON --------------------------\r\n    \r\n        \tfunction customSkip()\r\n        \t\tMobile.setMobilePosition(playerId, playerX, playerY, playerZ)\r\n           \t\tUI.displayWideScreenBand(true, 25, 300)\r\n    \t\t\tMobile.setMobilePosition(remingtonBossId, -55, -13, 0)\r\n           \t\tMobile.setMobileVisible(remingtonBossId, true)\r\n        \t\tskipCinematic(20236)\r\n        \tend    \r\n    \r\n    \t----------------------------- DEBUT DE CINEMATIQUE --------------------------\r\n    \r\n    \tstartCinematicContext(1.2, remingtonBossId)\r\n    \t\r\n    \tUI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"customSkip\")\r\n    \r\n    \tinvoke_custom(1, 1, \"Mobile.setMobilePosition\", playerId, -64, -14, 0)\r\n    \tinvoke_custom(1, 1, \"Mobile.setMobileDirection\", playerId, 5)\r\n    \tinvoke_custom(1, 1, \"Mobile.setMobilePosition\", remingtonBossId, -60, -14, 2)\r\n    \tinvoke_custom(1, 1, \"Mobile.setMobileDirection\", remingtonBossId, 5)\r\n    \tinvoke_custom(1, 1, \"Mobile.setMobileVisible\", remingtonBossId, false)\r\n    \r\n    \r\n    \t----------------------------- ACTIONS + DIALOGUES --------------------------\r\n    \r\n    \t--invoke_custom(12000, 1, \"Mobile.moveMobile\", remingtonID, -80, -14, 8)\r\n    \r\n    \tinvoke_custom(01250, 1, \"Mobile.setMobileVisible\", remingtonBossId, true)\r\n    \tinvoke_custom(01251, 1, \"Mobile.setMobileAnimation\", remingtonBossId, \"AnimSort-TP-Fin\")\r\n    \r\n    \tinvoke_custom(01300, 1, \"Mobile.setMobileDirection\", playerId, 1)\r\n    \tinvoke_custom(01330, 1, \"Camera.attachCameraToMobile\", playerId)\r\n    \r\n    \tinvoke_custom(03500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Help\")\r\n    \r\n    \tinvoke_custom(05000, 1, \"Mobile.setMobileAnimation\", remingtonBossId, \"AnimSort-Pistolet\")\r\n    \r\n    \tinvoke_custom(05000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimSort-GrandClaquementdeMains\")\r\n    \r\n    \tinvoke_custom(06000, 1, \"Particle.addParticleSystem\", apsTirRemington, -63, -14, 0)\r\n    \r\n    \tinvoke_custom(05800, 1, \"Particle.addParticleSystem\", apsTirRemingtonImpact, -63, -14, 0)\r\n    \r\n    \tinvoke_custom(05800, 1, \"Particle.addParticleSystem\", apsBouclier, -64, -14, 0)\r\n    \r\n    \t-- Oh, tu as contré mon Pulsar, tu es naï{[1*]?ve:f} mais plutôt puissant{[1*]?e:} !\r\n    \tinvoke_custom(07000, 1, \"bubble\", remingtonBossId, \"quest.sufokia.mercenary.roublard.05.06\")\r\n    \t--invoke_custom(13500, 1, \"Mobile.setMobileAnimation\", remingtonID, \"AnimEmote-Help\")\r\n    \r\n    \t-- Cela dit je reste un gentleman, cela m'embêterait d'avoir à vous faire sauter le caisson.\r\n    \tinvoke_custom(10300, 1, \"clearBubbles\", remingtonBossId)\r\n    \tinvoke_custom(10500, 1, \"bubble\", remingtonBossId, \"quest.sufokia.mercenary.roublard.05.07\")\r\n    \r\n    \t-- Donnez moi les trésors allez !!!\r\n    \tinvoke_custom(14900, 1, \"clearBubbles\", remingtonBossId)\r\n    \tinvoke_custom(15000, 1, \"bubble\", remingtonBossId, \"quest.sufokia.mercenary.roublard.05.08\")\r\n    \tinvoke_custom(15000, 1, \"Mobile.setMobileAnimation\", remingtonBossId, \"AnimSort-Epee\")\r\n    \r\n    \t-- Tu peux toujours rêver !!!\r\n    \tinvoke_custom(18800, 1, \"clearBubbles\", remingtonBossId)\r\n    \tinvoke_custom(19000, 1, \"bubble\", playerId, \"quest.sufokia.mercenary.roublard.05.09\")\r\n    \tinvoke_custom(19000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Pointer\")\r\n    \r\n    \t-- Alors vous ne me laissez pas le choix...\r\n    \tinvoke_custom(21300, 1, \"clearBubbles\", playerId)\r\n    \tinvoke_custom(21500, 1, \"bubble\", remingtonBossId, \"quest.sufokia.mercenary.roublard.05.10\")\r\n    \tinvoke_custom(21500, 1, \"Mobile.setMobileAnimation\", remingtonBossId, \"AnimSort-Dague\")\r\n    \t\r\n    \t\r\n    \tinvoke_custom(23000, 1, \"Mobile.setMobileAnimation\", remingtonBossId, \"AnimSort-TP-Debut\")\r\n    \tinvoke_custom(23990, 1, \"Mobile.setMobileVisible\", remingtonBossId, false)\r\n    \t\r\n    \tinvoke_custom(24000, 1, \"Mobile.setMobilePosition\", remingtonBossId, -55, -13, 0)\r\n    \t\r\n    \tinvoke_custom(24001, 1, \"Mobile.setMobileAnimation\", remingtonBossId, \"AnimSort-TP-Fin\")\r\n    \tinvoke_custom(24002, 1, \"Mobile.setMobileVisible\", remingtonBossId, true)\r\n    \t\r\n    \t----------------------------- FIN DE CINEMATIQUE --------------------------\r\n    \r\n    \tinvoke_custom(26000, 1, \"skipCinematic\", 20236)\nend\n\n-- [MERCENAIRE][EVENT] Victoire - Brise-Tibia - Cinématique Mercenaire\n-- On déclenche une cinématique  \nfunction event_2357_20054(bossRemington)\n        \t----------------------------- RECUPERATIONS DES INFOS JOUEUR --------------------------\r\n        \r\n        \tlocal playerId = Context.getLeaderId()\r\n        \tlocal remingtonBossId = toLong(bossRemington)\r\n        \t\r\n        \t----------------------------- INITIALISATION DES PNJ --------------------------\r\n        \r\n        \tlocal briseTibiaId = createActor(122401234, -67, -14, 0, 8, 1, 9)\r\n        \tlocal apsTirRemington = -1022019405\r\n        \tlocal apsTirRemingtonImpact = -1042026792\r\n        \tlocal apsBouclier = 1018310\r\n        \t\r\n        \tfunction customSkip()\r\n        \tMobile.setMobileVisible(remingtonBossId, true)\r\n        \tMobile.setMobilePosition(remingtonBossId, -55, -13, 0)\r\n        \tskipCinematic(20054)\r\n         end\r\n        \r\n        \t----------------------------- DEBUT DE CINEMATIQUE --------------------------\r\n        \r\n        \tstartCinematicContext(1.2, briseTibiaId)\r\n    \r\n        \tinvoke_custom(1, 1, \"Mobile.setMobilePosition\", playerId, -64, -14, 0)\r\n        \tinvoke_custom(1, 1, \"Mobile.setMobileDirection\", playerId, 5)\r\n        \tinvoke_custom(1, 1, \"Mobile.setMobilePosition\", remingtonBossId, -60, -14, 2)\r\n        \tinvoke_custom(1, 1, \"Mobile.setMobileDirection\", remingtonBossId, 5)\r\n            invoke(1, 1, \"Mobile.setMobileVisible\", remingtonBossId, false)\r\n    \r\n        \tUI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"customSkip\")\r\n        \r\n        \t----------------------------- ACTIONS + DIALOGUES --------------------------\r\n        \r\n        \t-- Qu'est-ce que tu nous veux à la fin ?\r\n        \tinvoke_custom(2000, 1, \"bubble\", briseTibiaId, \"quest.sufokia.mercenary.roublard.05.01\")\r\n        \tinvoke_custom(2000, 1, \"Mobile.setMobileAnimation\", briseTibiaId, \"AnimComp-Combat03\")\r\n        \r\n        \t-- Je viens régler ton compte sur ordre du Cartel !\r\n        \tinvoke_custom(5300, 1, \"clearBubbles\", briseTibiaId)\r\n        \tinvoke_custom(5500, 1, \"bubble\", playerId, \"quest.sufokia.mercenary.roublard.05.02\")\r\n        \tinvoke_custom(5500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Pointer\")\r\n        \r\n        \r\n        \t-- Peuh ! Si tu savais ce dont ces gens sont capables, tu ne serais pas leur petit chien de...\r\n        \tinvoke_custom(8800, 1, \"clearBubbles\", playerId)\r\n        \tinvoke_custom(9000, 1, \"bubble\", briseTibiaId, \"quest.sufokia.mercenary.roublard.05.03\")\r\n        \tinvoke_custom(9000, 1, \"Mobile.setMobileAnimation\", briseTibiaId, \"AnimSort-Sumo\")\r\n        \r\n        \t--invoke_custom(12000, 1, \"Mobile.moveMobile\", remingtonID, -80, -14, 8)\r\n    \r\n        \tinvoke_custom(12200, 1, \"Mobile.setMobileAnimation\", remingtonBossId, \"AnimSort-TP-Fin\")\r\n        \tinvoke_custom(12250, 1, \"Mobile.setMobileVisible\", remingtonBossId, true)\r\n        \r\n        \t-- Attention !!!\r\n        \tinvoke_custom(12900, 1, \"clearBubbles\", briseTibiaId)\r\n        \tinvoke_custom(13000, 1, \"bubble\", briseTibiaId, \"quest.sufokia.mercenary.roublard.05.04\")\r\n        \tinvoke_custom(13000, 1, \"Mobile.setMobileAnimation\", briseTibiaId, \"AnimComp-Combat01\")\r\n        \r\n        \tinvoke_custom(13200, 1, \"Mobile.setMobileDirection\", playerId, 1)\r\n        \tinvoke_custom(13300, 1, \"Camera.attachCameraToMobile\", playerId)\r\n        \r\n        \t-- Remington ?!\r\n        \tinvoke_custom(13500, 1, \"bubble\", playerId, \"quest.sufokia.mercenary.roublard.05.05\")\r\n        \tinvoke_custom(13500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Help\")\r\n        \r\n        \tinvoke_custom(15000, 1, \"Mobile.setMobileAnimation\", remingtonBossId, \"AnimSort-Pistolet\")\r\n        \r\n        \tinvoke_custom(15000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimSort-GrandClaquementdeMains\")\r\n        \r\n        \tinvoke_custom(16000, 1, \"Particle.addParticleSystem\", apsTirRemington, -63, -14, 0)\r\n        \r\n        \tinvoke_custom(15800, 1, \"Particle.addParticleSystem\", apsTirRemingtonImpact, -63, -14, 0)\r\n        \r\n        \tinvoke_custom(15800, 1, \"Particle.addParticleSystem\", apsBouclier, -64, -14, 0)\r\n        \r\n        \t-- Oh, tu as contré mon Pulsar, tu es naï{[1*]?ve:f} mais plutôt puissant{[1*]?e:} !\r\n        \tinvoke_custom(17000, 1, \"bubble\", remingtonBossId, \"quest.sufokia.mercenary.roublard.05.06\")\r\n        \t--invoke_custom(13500, 1, \"Mobile.setMobileAnimation\", remingtonID, \"AnimEmote-Help\")\r\n        \r\n        \t-- Cela dit je reste un gentleman, cela m'embeterait d'avoir à vous faire sauter le caisson.\r\n        \tinvoke_custom(20300, 1, \"clearBubbles\", remingtonBossId)\r\n        \tinvoke_custom(20500, 1, \"bubble\", remingtonBossId, \"quest.sufokia.mercenary.roublard.05.07\")\r\n        \r\n        \t-- Donnez moi les trésors allez !!!\r\n        \tinvoke_custom(24900, 1, \"clearBubbles\", remingtonBossId)\r\n        \tinvoke_custom(25000, 1, \"bubble\", remingtonBossId, \"quest.sufokia.mercenary.roublard.05.08\")\r\n        \tinvoke_custom(25000, 1, \"Mobile.setMobileAnimation\", remingtonBossId, \"AnimSort-Epee\")\r\n        \r\n        \t-- Tu peux toujours rêver !!!\r\n        \tinvoke_custom(28800, 1, \"clearBubbles\", remingtonBossId)\r\n        \tinvoke_custom(29000, 1, \"bubble\", playerId, \"quest.sufokia.mercenary.roublard.05.09\")\r\n        \tinvoke_custom(29000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Pointer\")\r\n        \r\n        \t-- Alors vous ne me laissez pas le choix...\r\n        \tinvoke_custom(31300, 1, \"clearBubbles\", playerId)\r\n        \tinvoke_custom(31500, 1, \"bubble\", remingtonBossId, \"quest.sufokia.mercenary.roublard.05.10\")\r\n        \tinvoke_custom(31500, 1, \"Mobile.setMobileAnimation\", remingtonBossId, \"AnimSort-Dague\")\r\n        \t\r\n        \tinvoke_custom(33000, 1, \"Mobile.setMobileAnimation\", remingtonBossId, \"AnimSort-TP-Debut\")\r\n        \tinvoke_custom(33990, 1, \"Mobile.setMobileVisible\", remingtonBossId, false)\r\n        \t\r\n        \tinvoke_custom(34000, 1, \"Mobile.setMobilePosition\", remingtonBossId, -55, -13, 0)\r\n        \t\r\n        \tinvoke_custom(34001, 1, \"Mobile.setMobileAnimation\", remingtonBossId, \"AnimSort-TP-Fin\")\r\n        \tinvoke_custom(34002, 1, \"Mobile.setMobileVisible\", remingtonBossId, true)\r\n        \t\r\n        \t----------------------------- FIN DE CINEMATIQUE --------------------------\r\n        \t\r\n        \tinvoke_custom(35000, 1, \"skipCinematic\", 20054)\nend\n\n-- [EVENT] Fin Cinématique Brise-Tibia - Tp\n-- \nfunction event_2357_22035()\n    \nend\n\n-- [EVENT] On lance le combat contre Remington - skip forcé Cinématique\n-- \nfunction event_2357_20393()\n    skipCinematic()\nend\n\n-- [MERCENAIRE][EVENT] Victoire - Remington - Cinématique Mercenaire\n-- On déclenche une cinématique  \nfunction event_2357_20057()\n    \t----------------------------- RECUPERATIONS DES INFOS JOUEUR --------------------------\r\n    \r\n    \tlocal playerId = Context.getLeaderId()\r\n    \tlocal playerX, playerY, playerZ = Mobile.getMobilePosition(playerId)\r\n    \r\n    \r\n    \t----------------------------- INITIALISATION DES PNJ --------------------------\r\n    \r\n    \tlocal briseTibiaID = createActor(122401234, -91, -14, 8, 8, 1, 9)\r\n    \tlocal remingtonID = createActor(197902018, -55, -14, 0, 8, 3, 10)\r\n    \r\n    \t----------------------------- DEBUT DE CINEMATIQUE --------------------------\r\n    \r\n    \tstartCinematicContext(1.1, playerId)\r\n    \tUI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 20057)\r\n    \r\n    \tinvoke_custom(1, 1, \"UI.displayWideScreenBand\", true, 100, 300)\r\n    \r\n    \tinvoke_custom(400, 1, \"Mobile.setMobilePosition\", playerId, -53, -14, 0)\r\n    \tinvoke_custom(500, 1, \"Mobile.setMobileDirection\", playerId, 5)\r\n    \r\n    \tinvoke_custom(1000, 1, \"UI.displayWideScreenBand\", true, 20, 500)\r\n    \r\n    \t----------------------------- ACTIONS + DIALOGUES --------------------------\r\n    \r\n    \r\n    \r\n    \t-- Argh... Très bien, tu as gagné...\r\n    \tinvoke_custom(1500, 1, \"bubble\", remingtonID, \"quest.sufokia.mercenary.roublard.06.01\")\r\n    \r\n    \tinvoke_custom(4300, 1, \"Mobile.setMobileAnimation\", remingtonID, \"AnimSort-TP-Debut\")\r\n    \r\n    \tinvoke_custom(4500, 1, \"clearBubbles\", remingtonID)\r\n    \r\n    \tinvoke_custom(5390, 1, \"Mobile.setMobileVisible\", remingtonID, false)\r\n    \r\n    \tinvoke_custom(5400, 1, \"Mobile.setMobilePosition\", remingtonID, -62, -14, 0)\r\n    \r\n    \tinvoke_custom(5450, 1, \"Mobile.setMobileAnimation\", remingtonID, \"AnimSort-TP-Fin\")\r\n    \tinvoke_custom(5510, 1, \"Mobile.setMobileVisible\", remingtonID, true)\r\n    \r\n    \tinvoke_custom(6350, 1, \"Mobile.moveMobile\", remingtonID, -87, -14, 8, \"Mobile.setMobileDirection\", remingtonID, 5)\r\n    \r\n    \t-- Allez, à plus !\r\n    \tinvoke_custom(6500, 1, \"bubble\", remingtonID, \"quest.sufokia.mercenary.roublard.06.02\")\r\n    \r\n    \tinvoke_custom(5800, 1, \"Mobile.moveMobile\", playerId, -84, -14, 8, \"Mobile.setMobileDirection\", playerId, 5)\r\n    \r\n    \r\n    \t-- Retourne d'où tu viens sale traître !\r\n    \tinvoke_custom(14500, 1, \"bubble\", briseTibiaID, \"quest.sufokia.mercenary.roublard.06.03\")\r\n    \tinvoke_custom(14500, 1, \"Mobile.setMobileAnimation\", briseTibiaID, \"AnimSort-Sumo\")\r\n    \r\n    \t-- Pas avant d'avoir eu ce que je suis venu chercher.\r\n    \tinvoke_custom(16800, 1, \"clearBubbles\", briseTibiaID)\r\n    \tinvoke_custom(17000, 1, \"bubble\", remingtonID, \"quest.sufokia.mercenary.roublard.06.04\")\r\n    \r\n    \tinvoke_custom(19800, 1, \"Mobile.setMobileDirection\", remingtonID, 1)\r\n    \r\n    \t-- Toi. J'ai besoin du livre comme convenu, pas de roublardise cette fois, n'oublie pas que sans moi tu ne serais pas arrivé{[1*]?e:} ici.\r\n    \tinvoke_custom(19800, 1, \"clearBubbles\", remingtonID)\r\n    \tinvoke_custom(20000, 1, \"bubble\", remingtonID, \"quest.sufokia.mercenary.roublard.06.05\")\r\n    \r\n    \t-- Prenez ce que vous voulez mais oubliez no