+ Victoire des joueurs\n-- \nfunction event_2357_20293()\n    \nend\n\n-- Lancement d'un combat - Application de l'état aux Roublard\n-- \nfunction event_2357_21965()\n    \nend\n\n-- [ARCHI] Apparition de l'Archimonstre\n-- \nfunction event_2357_24318()\n    \nend\n\n-- [POURPRE] Spawn Remington si pas de quête mercenaire en cours\n-- \nfunction event_2357_24467()\n    \nend\n\n-- [INTERVENTION] INTERACTIVE_ELEMENT_ACTIVATION - Le joueur examine la Stèle d'intervention\n-- \nfunction event_2357_24502()\n    UI.openRewardsDialog(\"stele.intervention.description.4\")\r\n    \r\n    UI.addReward(33393)\r\n    UI.addReward(33409)\r\n    \r\n    local stateInfoId = \"stele.intervention.ignemikhal.description\" \r\n    \r\n    updateInterventionInfo(stateInfoId, true)\nend\n\n-- [INTERVENTION] GENERIC_ACTIVABLE_ACTION - Activation Stèle d'intervention\n-- \nfunction event_2357_24503(mobTwo)\n    UI.openRewardsDialog(\"stele.intervention.description.4\")\r\n    \r\n    UI.addReward(33393)\r\n    UI.addReward(33409)\r\n    \r\n    local stateInfoId = \"stele.intervention.ignemikhal.description\" \r\n    \r\n    updateInterventionInfo(stateInfoId, true)\r\n    \r\n    local bossId = toLong(mobTwo)\r\n    \r\n    invoke(1, 1, \"Mobile.setMobileAnimation\", bossId, \"AnimSort-4-Boucle\")\r\n    invoke(480, 1, \"Mobile.setMobileAnimation\", bossId, \"AnimSort-4-Fin\")\r\n    \r\n    Effect.createCameraShakeEffect(100, 500, 100, 5, 100, \"BOTH\")\r\nend\n\n-- [INTERVENTION] FIGHT_STARTED - On cache la stèle\n-- \nfunction event_2357_24511()\n    \nend\n\n-- [INTERVENTION] FIGHT_ENDED - On rend la stèle utilisable en cas de défaite\n-- \nfunction event_2357_24512()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","updateInterventionInfo","event_2357_20052","event_2357_20168","event_2357_20171","event_2357_20172","event_2357_20173","event_2357_20174","event_2357_20236","customSkip","event_2357_20054","customSkip","event_2357_22035","event_2357_20393","event_2357_20057","event_2357_20181","event_2357_20175","event_2357_20176","event_2357_20177","event_2357_20178","event_2357_20179","event_2357_20180","event_2357_20292","event_2357_20293","event_2357_21965","event_2357_24318","event_2357_24467","event_2357_24502","event_2357_24503","event_2357_24511","event_2357_24512"],"quest_calls":["UI.openRewardsDialog(\"stele.intervention.description.4\")\r","UI.openRewardsDialog(\"stele.intervention.description.4\")\r"],"dialogue_calls":[]},"scenario/2358.lua":{"source":"\n\n-- Enregistrement des Evènements : Début\n-- \nfunction event_2358_20058()\n    \nend\n\n-- Enregistrement des Evènements : Fin\n-- \nfunction event_2358_20059()\n    \nend\n\n-- Enregistrement des Evènements Cyclique : Spawn de monstres\n-- Toutes les X min, on spawn les groupes de monstres\nfunction event_2358_20060()\n    \nend\n\n","functions":["event_2358_20058","event_2358_20059","event_2358_20060"],"quest_calls":[],"dialogue_calls":[]},"scenario/2359.lua":{"source":"\n\n","functions":[],"quest_calls":[],"dialogue_calls":[]},"scenario/2360.lua":{"source":"\n\n-- [INIT] Spawn Père Nowel - Centre d'Astrub\n-- \nfunction event_2360_20068()\n    \nend\n\n-- [INIT] Despawn Père Nowel - Centre d'Astrub\n-- \nfunction event_2360_20072()\n    \nend\n\n","functions":["event_2360_20068","event_2360_20072"],"quest_calls":[],"dialogue_calls":[]},"scenario/2361.lua":{"source":"\n\n-- [INIT] Despawn les Monstres NPC liés à l'Event\n-- Les Groupes doivent être initialement non spawn\nfunction event_2361_20070()\n    \nend\n\n","functions":["event_2361_20070"],"quest_calls":[],"dialogue_calls":[]},"scenario/2362.lua":{"source":"\n\n-- Event - Infos au joueur\n-- \nfunction event_2362_20073()\n    UI.openInfoDialog(\"event.nowel.pereNowel.title\", \"event.nowel.pereNowel.isLeaving\" )\nend\n\n","functions":["event_2362_20073"],"quest_calls":[],"dialogue_calls":[]},"scenario/2363.lua":{"source":"\n\n-- Event - Infos au joueur\n-- \nfunction event_2363_20074()\n    UI.openInfoDialog(\"event.nowel.pereNowel.title\", \"event.nowel.pereNowel.isComing\" )\nend\n\n","functions":["event_2363_20074"],"quest_calls":[],"dialogue_calls":[]},"scenario/2364.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\n-- les fonctions où on cache\r\nfunction hideMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, false)\r\nend\r\n\r\n-- les fonctions où on rend visible (à nouveau\r\nfunction showMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, true)\r\nend\n\n-- [INIT] Variables\n-- \nfunction event_2364_20092()\n    \nend\n\n-- ~[INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2364_20093()\n    \nend\n\n-- [INIT] Si le joueur entre dans la Mine de Sufokia, on ajoute le Bandeau Pirate\n-- \nfunction event_2364_20094()\n    \nend\n\n-- [EVENT] Le joueur arrive devant le donjon Roublard\n-- \nfunction event_2364_20095(RemingtonId)\n    \t----------------------------- RECUPERATIONS DES INFOS JOUEUR --------------------------\r\n    \r\n    \tlocal playerId = Context.getLeaderId()\r\n    \tlocal playerX, playerY, playerZ = Mobile.getMobilePosition(playerId)\r\n    \r\n    \r\n    \t----------------------------- INITIALISATION DES PNJ --------------------------\r\n    \r\n    \tlocal remingtonID = createActor(197902018, -104, 40, 0, 8, 1, 10)\r\n    \tlocal RemingtonMine = toLong(RemingtonId) \r\n    \r\n    \t----------------------------- SKIP DE CINEMATIQUE PAR LE BOUTON --------------------------\r\n    \tfunction customSkip()\r\n    \t\tMobile.setMobilePosition(playerId, playerX, playerY, playerZ)\r\n    \t\tMobile.addMobileCreationCallback(RemingtonMine , \"showMonster\", RemingtonMine)\r\n       \t\tUI.displayWideScreenBand(true, 25, 300)\r\n    \t\tskipCinematic(20095)\r\n    \tend\r\n    \r\n    \t----------------------------- DEBUT DE CINEMATIQUE --------------------------\r\n    \r\n    \tstartCinematicContext(1.4, playerId)\r\n    \tUI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"customSkip\")\r\n    \r\n    \tinvoke_custom(1, 1, \"Mobile.setMobileVisible\", remingtonID, false)\r\n    \tinvoke_custom(100, 1, \"Mobile.moveMobile\", playerId, -102, 46, 1, \"Mobile.setMobileDirection\", playerId, 5)\r\n    \r\n    \t----------------------------- ACTIONS + DIALOGUES --------------------------\r\n    \tinvoke_custom(3000, 1, \"Mobile.setMobileVisible\", remingtonID, true)\r\n    \r\n    \t-- Hey... Psssst, oui toi là !\r\n    \tinvoke_custom(3500, 1, \"bubble\", remingtonID, \"quest.sufokia.mercenary.roublard.04.01\")\r\n    \r\n    \tinvoke_custom(4500, 1, \"Mobile.moveMobile\", remingtonID, -101, 40, 1, \"Mobile.setMobileDirection\", remingtonID, 3)\r\n    \tinvoke_custom(4500, 1, \"Mobile.setMobileDirection\", playerId, 3)\r\n    \tinvoke_custom(4800, 1, \"Mobile.setMobileDirection\", playerId, 7)\r\n    \tinvoke_custom(5100, 1, \"Mobile.setMobileDirection\", playerId, 1)\r\n    \tinvoke_custom(5500, 1, \"Mobile.setMobileDirection\", playerId, 7)\r\n    \tinvoke_custom(5500, 1, \"Camera.attachCameraToMobile\", remingtonID)\r\n    \r\n    \t-- Viens là au lieu de me regarder avec des yeux de pichon frit !\r\n    \tinvoke_custom(6800, 1, \"clearBubbles\", remingtonID)\r\n    \tinvoke_custom(7000, 1, \"bubble\", remingtonID, \"quest.sufokia.mercenary.roublard.04.02\")\r\n    \r\n    \tinvoke_custom(8500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmoteMarket-HausseEpaules\")\r\n    \tinvoke_custom(8500, 1, \"Camera.attachCameraToMobile\", playerId)\r\n    \r\n    \tinvoke_custom(9500, 1, \"Mobile.moveMobile\", playerId, -104, 39, 0, \"Mobile.setMobileDirection\", playerId, 7)\r\n    \tinvoke_custom(10000, 1, \"Mobile.moveMobile\", remingtonID, -101, 37, 1, \"Mobile.setMobileDirection\", remingtonID, 5)\r\n    \tinvoke_custom(11900, 1, \"Mobile.moveMobile\", remingtonID, -104, 37, 0, \"Mobile.setMobileDirection\", remingtonID, 3)\r\n    \r\n    \t-- Je m'appelle Remington, roublard au grand coeur !\r\n    \tinvoke_custom(13300, 1, \"clearBubbles\", remingtonID)\r\n    \tinvoke_custom(13500, 1, \"bubble\", remingtonID, \"quest.sufokia.mercenary.roublard.04.03\")\r\n    \r\n    \r\n    \t-- Ces pirates ont quelque-chose qui m'intéresse et mon petit doigt me dit que c'est pareil pour toi.\r\n    \tinvoke_custom(16900, 1, \"clearBubbles\", remingtonID)\r\n    \tinvoke_custom(17000, 1, \"bubble\", remingtonID, \"quest.sufokia.mercenary.roublard.04.04\")\r\n    \r\n    \r\n    \t-- Je... je ne vois pas de quoi tu parles, je suis un{[1*]?e:} des leurs !\r\n    \tinvoke_custom(22800, 1, \"clearBubbles\", remingtonID)\r\n    \tinvoke_custom(23000, 1, \"bubble\", playerId, \"quest.sufokia.mercenary.roublard.04.05\")\r\n    \tinvoke_custom(23000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    \r\n    \r\n    \t-- Ahahah si tu es un{[1*]?e:} pirate alors je suis Miss Monde des Douze !!!\r\n    \tinvoke_custom(27400, 1, \"clearBubbles\", playerId)\r\n    \tinvoke_custom(27500, 1, \"bubble\", remingtonID, \"quest.sufokia.mercenary.roublard.04.06\")\r\n    \tinvoke_custom(27500, 1, \"Mobile.setMobileAnimation\", remingtonID, \"AnimComp-Rire\")\r\n    \r\n    \r\n    \t-- Ecoute, je ne sais pas pour qui tu travailles mais le marché est simple, tu rentres dans cette taverne et je couvre tes arrières.\r\n    \tinvoke_custom(31300, 1, \"clearBubbles\", remingtonID)\r\n    \tinvoke_custom(31500, 1, \"bubble\", remingtonID, \"quest.sufokia.mercenary.roublard.04.07\")\r\n    \r\n    \t-- Sans mon aide, tu te feras déborder par les pirates de l'extérieur. Tout ce que je demande c'est une part du butin, cela te va ?\r\n    \tinvoke_custom(36800, 1, \"clearBubbles\", remingtonID)\r\n    \tinvoke_custom(37000, 1, \"bubble\", remingtonID, \"quest.sufokia.mercenary.roublard.04.08\")\r\n    \r\n    \t-- **C'est risqué mais il a raison, je vais avoir du mal à m'en sortir seul{[1*]?e:}, je pourrais toujours le doubler à la fin.\r\n    \tinvoke_custom(42800, 1, \"clearBubbles\", remingtonID)\r\n    \tinvoke_custom(43000, 1, \"bubble\", playerId, \"quest.sufokia.mercenary.roublard.04.09\")\r\n    \r\n    \t-- ... Marché conclu, je te fais confiance !\r\n    \tinvoke_custom(48800, 1, \"clearBubbles\", playerId)\r\n    \tinvoke_custom(49000, 1, \"bubble\", playerId, \"quest.sufokia.mercenary.roublard.04.10\")\r\n    \tinvoke_custom(49000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Pouce\")\r\n    \r\n    \tinvoke_custom(52000, 1, \"Mobile.moveMobile\", playerId, -101, 51, 1)\r\n    \r\n    \tinvoke_custom(53010, 1, \"Camera.attachCameraToMobile\", remingtonID)\r\n    \tinvoke_custom(53000, 1, \"Camera.setZoomFactor\", 2.0)\r\n    \r\n    \t-- **Héhé c'était trop facile...\r\n    \tinvoke_custom(55000, 1, \"clearBubbles\", playerId)\r\n    \tinvoke_custom(55000, 1, \"bubble\", remingtonID, \"quest.sufokia.mercenary.roublard.04.11\")\r\n    \tinvoke_custom(55550, 1, \"Mobile.setMobileAnimation\", remingtonID, \"AnimComp-Rire\")\r\n    \r\n    \t----------------------------- FIN DE CINEMATIQUE --------------------------\r\n    \tinvoke_custom(58500, 1, \"UI.displayWideScreenBand\", true, 100, 300)\r\n    \tinvoke_custom(58700, 1, \"Mobile.setMobilePosition\", playerId, playerX, playerY, playerZ)\r\n    \tinvoke_custom(58800, 1, \"Mobile.addMobileCreationCallback\", RemingtonMine , \"showMonster\", RemingtonMine)\r\n    \tinvoke_custom(58900, 1, \"UI.displayWideScreenBand\", true, 25, 300)\r\n    \tinvoke(59000, 1, \"customSkip\")\nend\n\n-- [EVENT] Masquage de Remington si le joueur n'est pas dans le contexte de la quête\n-- \nfunction event_2364_20288(RemingtonId)\n    Mobile.addMobileCreationCallback(RemingtonId, \"hideMonster\", RemingtonId)\nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","hideMonster","showMonster","event_2364_20092","event_2364_20093","event_2364_20094","event_2364_20095","customSkip","event_2364_20288"],"quest_calls":[],"dialogue_calls":[]},"scenario/2366.lua":{"source":"-- les fonctions où on cache\r\nfunction hideMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, false)\r\nend\r\n\r\n-- les fonctions où on rend visible (à nouveau\r\nfunction showMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, true)\r\nend\n\n-- [INITIALISATION] Serveur\n-- \nfunction event_2366_20182()\n    \nend\n\n-- ~[INITIALISATION] Perso\n-- \nfunction event_2366_20183()\n    \nend\n\n-- [EVENT] Masquage du PNJ monde si le joueur n'a pas dénoncé Brise-Tibias \n-- \nfunction event_2366_20184(briseTibiasId)\n    Mobile.addMobileCreationCallback(briseTibiasId, \"hideMonster\", briseTibiasId)\nend\n\n","functions":["hideMonster","showMonster","event_2366_20182","event_2366_20183","event_2366_20184"],"quest_calls":[],"dialogue_calls":[]},"scenario/2367.lua":{"source":"\n\n-- [INIT] Variables Globales\n-- \nfunction event_2367_20245()\n    \nend\n\n-- [INIT] Inscription du joueur + Variables Locales\n-- \nfunction event_2367_20246()\n    \nend\n\n-- *[OLD][1] Victoire - Déverouille le passage vers S2\n-- \nfunction event_2367_20247()\n    \nend\n\n-- *[OLD][2] Victoire - Déverouille le passage vers S3\n-- \nfunction event_2367_20248()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 01\n-- \nfunction event_2367_20249()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 02 - BOSS\n-- \nfunction event_2367_20250()\n    \nend\n\n-- Déplace le joueur vers la salle suivante\n-- \nfunction event_2367_20251()\n    \nend\n\n-- Lancement d'un combat - Application de l'état Accords Déons\n-- \nfunction event_2367_21916()\n    \nend\n\n-- [STELE] FIGHT_STARTED - On applique les difficultés sur le boss\n-- \nfunction event_2367_22861()\n    \nend\n\n-- [STELE] FIGHT_ENTER_ACTION_PHASE - On applique les bonus sur les joueurs\n-- \nfunction event_2367_22862()\n    \nend\n\n-- [STELE] FIGHT_ENDED - On rend la stèle utilisable en cas de défaite\n-- \nfunction event_2367_22880()\n    \nend\n\n-- [ARCHI] Apparition de l'Archimonstre\n-- \nfunction event_2367_23984()\n    \nend\n\n","functions":["event_2367_20245","event_2367_20246","event_2367_20247","event_2367_20248","event_2367_20249","event_2367_20250","event_2367_20251","event_2367_21916","event_2367_22861","event_2367_22862","event_2367_22880","event_2367_23984"],"quest_calls":[],"dialogue_calls":[]},"scenario/2368.lua":{"source":"\n\n-- Téléporte le joueur dans sa Nation\n-- \nfunction event_2368_20252()\n    \nend\n\n","functions":["event_2368_20252"],"quest_calls":[],"dialogue_calls":[]},"scenario/2369.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\n\n-- ~[INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2369_20258()\n    \nend\n\n-- [EVENT] Sokoban - Lancement\n-- \nfunction event_2369_20259()\n    UI.loadTutorialDialog(\"null\",\"quest.nations.ch04.sokoban.tutorial.title\",\"quest.nations.ch04.sokoban.tutorial.desc\")\r\n    Mobile.setMobileAnimationStaticKey(Context.getLeaderId(), \"AnimStatique01\")\nend\n\n-- [EVENT] Sokoban - Début\n-- \nfunction event_2369_20260()\n    \nend\n\n-- [EVENT] Sokoban - Victoire - Déverouille accès au Coffre\n-- \nfunction event_2369_20261()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_2369_20258","event_2369_20259","event_2369_20260","event_2369_20261"],"quest_calls":[],"dialogue_calls":[]},"scenario/2370.lua":{"source":"\n\n-- [TRIGGER] Le joueur arrive au port d'Astrub dans le contexte de la quête Hiboss\n-- \nfunction event_2370_20266()\n    \nend\n\n","functions":["event_2370_20266"],"quest_calls":[],"dialogue_calls":[]},"scenario/2371.lua":{"source":"\n\n-- [INITIALISATION] Variables\n-- \nfunction event_2371_20305()\n    \nend\n\n-- [EVENT] Inscription au scénario\n-- \nfunction event_2371_20306()\n    \nend\n\n-- MONSTER_WON_FIGHT - Interdit le Spawn de Mimic\n-- \nfunction event_2371_20310()\n    \nend\n\n-- FIGHT_ENTER_ACTION_PHASE - Roll pour savoir si Spawn de Mimic\n-- \nfunction event_2371_20311()\n    \nend\n\n-- FIGHT_ENTER_ACTION_PHASE - Applique l'état Mimic sur 1 monstre aléatoire\n-- \nfunction event_2371_20312()\n    \nend\n\n","functions":["event_2371_20305","event_2371_20306","event_2371_20310","event_2371_20311","event_2371_20312"],"quest_calls":[],"dialogue_calls":[]},"scenario/2372.lua":{"source":"\n\n-- Destruction des cartes - ajout de l'encyclopédie\n-- \nfunction event_2372_20322()\n    \nend\n\n","functions":["event_2372_20322"],"quest_calls":[],"dialogue_calls":[]},"scenario/2373.lua":{"source":"\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_2373_20323()\n    \nend\n\n","functions":["event_2373_20323"],"quest_calls":[],"dialogue_calls":[]},"scenario/2376.lua":{"source":"bubbleSteleInfoId = 0\r\n\r\nfunction closeSteleInfo()\r\n\tif (bubbleSteleInfoId ~= nil  and bubbleSteleInfoId ~= 0) then BubbleText.close(bubbleSteleInfoId) end\r\nend\r\n\r\nfunction onSteleInfoClosed()\r\n\tif (bubbleSteleInfoId ~= nil  and bubbleSteleInfoId ~= 0) then bubbleSteleInfoId = 0 end\r\nend\r\n\r\nfunction updateSteleInfo(stateInfoId, forceDisplayUI)\r\n\r\n\tif (bubbleSteleInfoId == 0) then\r\n\t\tbubbleSteleInfoId = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_WEST\", 0, -60, false, 2147483647, true, \"interactiveBubbleDialog5\", 30000, 25000, \"onSteleInfoClosed\")\r\n\tend\r\n\r\n\tBubbleText.setText(bubbleSteleInfoId, stateInfoId)\r\n\t\r\n\tif (forceDisplayUI) then BubbleText.show(bubbleSteleInfoId) end\r\nend\n\n-- [INIT] Variables Globales\n-- \nfunction event_2376_20385()\n    \nend\n\n-- [INIT] Inscription du joueur + Variables Locales\n-- \nfunction event_2376_20386()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 01\n-- \nfunction event_2376_20387()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 02\n-- \nfunction event_2376_20388()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 03\n-- \nfunction event_2376_20389()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 04 - BOSS\n-- \nfunction event_2376_20390()\n    \nend\n\n-- Déplace le joueur vers la salle suivante\n-- \nfunction event_2376_20391()\n    \nend\n\n-- [OLD][EVENT] Le joueur examine la Stèle 1\n-- \nfunction event_2376_20542(steleCount)\n    local steleCount = toLong(steleCount)\r\n    if (steleCount == 1) then rewardId = 27157\r\n    elseif (steleCount == 2) then rewardId = 27156\r\n    else rewardId = 27149\r\n    end\r\n    \r\n    UI.openRewardsDialog(\"stele.description\")\r\n    UI.addReward(rewardId)\r\n    \r\n    local stateInfoId = \"stele.state.description.6087\"\r\n    \r\n    updateSteleInfo(stateInfoId, true)\nend\n\n-- [OLD][EVENT] Le joueur examine la Stèle 2\n-- \nfunction event_2376_20543(steleCount)\n    local steleCount = toLong(steleCount)\r\n    if (steleCount == 1) then rewardId = 27157\r\n    elseif (steleCount == 2) then rewardId = 27156\r\n    else rewardId = 27149\r\n    end\r\n    \r\n    UI.openRewardsDialog(\"stele.description\")\r\n    UI.addReward(rewardId)\r\n    \r\n    local stateInfoId = \"stele.state.description.6088\"\r\n    \r\n    updateSteleInfo(stateInfoId, true)\nend\n\n-- [OLD][EVENT] Le joueur examine la Stèle 3\n-- \nfunction event_2376_20544(steleCount)\n    local steleCount = toLong(steleCount)\r\n    if (steleCount == 1) then rewardId = 27157\r\n    elseif (steleCount == 2) then rewardId = 27156\r\n    else rewardId = 27149\r\n    end\r\n    \r\n    UI.openRewardsDialog(\"stele.description\")\r\n    UI.addReward(rewardId)\r\n    \r\n    local stateInfoId = \"stele.state.description.6089\"\r\n    \r\n    updateSteleInfo(stateInfoId, true)\nend\n\n-- [OLD][EVENT] Activation Stèle 1\n-- \nfunction event_2376_20545(steleCount)\n    local steleCount = toLong(steleCount)\r\n    if (steleCount == 1) then rewardId = 27149\r\n    elseif (steleCount == 2) then rewardId = 27157\r\n    elseif (steleCount == 3) then rewardId = 27156\r\n    else rewardId = 0\r\n    end\r\n    \r\n    UI.openRewardsDialog(\"stele.activation\")\r\n    UI.addReward(rewardId)\nend\n\n-- [OLD][EVENT] Activation Stèle 2\n-- \nfunction event_2376_20546(steleCount)\n    local steleCount = toLong(steleCount)\r\n    if (steleCount == 1) then rewardId = 27149\r\n    elseif (steleCount == 2) then rewardId = 27157\r\n    elseif (steleCount == 3) then rewardId = 27156\r\n    else rewardId = 0\r\n    end\r\n    \r\n    UI.openRewardsDialog(\"stele.activation\")\r\n    UI.addReward(rewardId)\nend\n\n-- [OLD][EVENT] Activation Stèle 3\n-- \nfunction event_2376_20547(steleCount)\n    local steleCount = toLong(steleCount)\r\n    if (steleCount == 1) then rewardId = 27149\r\n    elseif (steleCount == 2) then rewardId = 27157\r\n    elseif (steleCount == 3) then rewardId = 27156\r\n    else rewardId = 0\r\n    end\r\n    \r\n    UI.openRewardsDialog(\"stele.activation\")\r\n    UI.addReward(rewardId)\nend\n\n-- [OLD][EVENT] Salle 4 - Refresh des APS pour Stèles\n-- \nfunction event_2376_20548()\n    \nend\n\n-- [OLD][EVENT] DUNGEON_DIFFICULTY_CHANGED - On désactive les états stèles\n-- \nfunction event_2376_20612()\n    \nend\n\n-- [STELE] FIGHT_STARTED - On applique les difficultés sur le boss\n-- \nfunction event_2376_22791()\n    \nend\n\n-- [STELE] FIGHT_ENTER_ACTION_PHASE - On applique les bonus sur les joueurs\n-- \nfunction event_2376_22792()\n    \nend\n\n-- [STELE] FIGHT_ENDED - On rend la stèle utilisable en cas de défaite\n-- \nfunction event_2376_22881()\n    \nend\n\n-- [ARCHI] Apparition de l'Archimonstre\n-- \nfunction event_2376_23985()\n    \nend\n\n","functions":["closeSteleInfo","onSteleInfoClosed","updateSteleInfo","event_2376_20385","event_2376_20386","event_2376_20387","event_2376_20388","event_2376_20389","event_2376_20390","event_2376_20391","event_2376_20542","event_2376_20543","event_2376_20544","event_2376_20545","event_2376_20546","event_2376_20547","event_2376_20548","event_2376_20612","event_2376_22791","event_2376_22792","event_2376_22881","event_2376_23985"],"quest_calls":["UI.openRewardsDialog(\"stele.description\")\r","UI.openRewardsDialog(\"stele.description\")\r","UI.openRewardsDialog(\"stele.description\")\r","UI.openRewardsDialog(\"stele.activation\")\r","UI.openRewardsDialog(\"stele.activation\")\r","UI.openRewardsDialog(\"stele.activation\")\r"],"dialogue_calls":[]},"scenario/2377.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\n\n-- [EVENT] Le joueur interagit avec la porte : on lance le dialogue\n-- \nfunction event_2377_20397()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_2377_20397"],"quest_calls":[],"dialogue_calls":[]},"scenario/2378.lua":{"source":"function hideDoor()\r\n\t\tWorld.setPictoAlpha(-1, 2, 3, 0, 1000)\r\n\t\tWorld.setPictoAlpha(0, 2, 3, 0, 1000)\r\n\t\tWorld.setPictoAlpha(1, 2, 3, 0, 1000)\r\nend\r\n\r\nbubbleSteleInfoId = 0\r\n\r\nfunction closeSteleInfo()\r\n\tif (bubbleSteleInfoId ~= nil  and bubbleSteleInfoId ~= 0) then BubbleText.close(bubbleSteleInfoId) end\r\nend\r\n\r\nfunction onSteleInfoClosed()\r\n\tif (bubbleSteleInfoId ~= nil  and bubbleSteleInfoId ~= 0) then bubbleSteleInfoId = 0 end\r\nend\r\n\r\nfunction updateSteleInfo(stateInfoId, forceDisplayUI)\r\n\r\n\tif (bubbleSteleInfoId == 0) then\r\n\t\tbubbleSteleInfoId = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_WEST\", 0, -60, false, 2147483647, true, \"interactiveBubbleDialog5\", 30000, 25000, \"onSteleInfoClosed\")\r\n\tend\r\n\r\n\tBubbleText.setText(bubbleSteleInfoId, stateInfoId)\r\n\t\r\n\tif (forceDisplayUI) then BubbleText.show(bubbleSteleInfoId) end\r\nend\n\n-- [INIT] Variables & Constantes\n-- \nfunction event_2378_21808()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2378_20401()\n    hideDoor()\nend\n\n-- FIGHT_STARTED - Pose des zones flag\n-- \nfunction event_2378_20409()\n    \nend\n\n-- INTERACTIVE_ELEMENT_ACTIVATION - Ouverture de la porte\n-- \nfunction event_2378_21809()\n    trace(\"OUVERTURE DE LA PORTE\")\r\n    \r\n    hideDoor()\nend\n\n-- MONSTER_ACTION_EVENT - Lancement du combat\n-- on skippe la cinématique pour tout le monde \nfunction event_2378_21810()\n    skipCinematic()\nend\n\n-- FIGHT_ENDED - Rend les monstres inattaquables\n-- \nfunction event_2378_21811()\n    \nend\n\n-- FIGHT_ENDED_IN_CLIENT_EVENT - Reset les stèles\n-- \nfunction event_2378_21812()\n    \nend\n\n-- [STELE] Le joueur examine une stèle\n-- \nfunction event_2378_21813(steleCount, steleStateId)\n    local steleCount = toLong(steleCount)\r\n    local steleStateId = toLong(steleStateId)\r\n    \r\n    if (steleCount == 0) then\r\n    UI.openRewardsDialog(\"stele.description.tour\")\r\n    UI.addReward(27123)\r\n    UI.addReward(27278, \"stele.reward.stasis.21\")\r\n    UI.addReward(27083, \"stele.reward.stasis.21\")\r\n    \r\n    elseif (steleCount == 1) then\r\n    UI.openRewardsDialog(\"stele.description.tour\")\r\n    UI.addReward(27141)\r\n    UI.addReward(27277, \"stele.reward.stasis.21\")\r\n    UI.addReward(27083, \"stele.reward.stasis.21\")\r\n    \r\n    elseif (steleCount == 2) then\r\n    UI.openRewardsDialog(\"stele.description.tour\")\r\n    UI.addReward(27138)\r\n    UI.addReward(27279, \"stele.reward.stasis.21\")\r\n    UI.addReward(27083, \"stele.reward.stasis.21\")\r\n    \r\n    elseif (steleCount == 3) then\r\n    UI.openRewardsDialog(\"stele.description.tour\")\r\n    UI.addReward(27028, \"stele.reward.stasis.21\")\r\n    UI.addReward(27276, \"stele.reward.stasis.21\")\r\n    UI.addReward(27083, \"stele.reward.stasis.21\")\r\n    \r\n    else\r\n    \r\n    end\r\n    \r\n    local stateInfoId = \"stele.state.description.\" .. toString(steleStateId)\r\n    \r\n    updateSteleInfo(stateInfoId, true)\nend\n\n-- [STELE] Le joueur active une stèle\n-- \nfunction event_2378_21814(steleCount)\n    local steleCount = toLong(steleCount)\r\n    local steleStateId = toLong(steleStateId)\r\n    \r\n    if (steleCount == 1) then\r\n    UI.openRewardsDialog(\"stele.description.tour\")\r\n    UI.addReward(27123)\r\n    UI.addReward(27278, \"stele.reward.stasis.21\")\r\n    UI.addReward(27083, \"stele.reward.stasis.21\")\r\n    \r\n    elseif (steleCount == 2) then\r\n    UI.openRewardsDialog(\"stele.description.tour\")\r\n    UI.addReward(27141)\r\n    UI.addReward(27277, \"stele.reward.stasis.21\")\r\n    UI.addReward(27083, \"stele.reward.stasis.21\")\r\n    \r\n    elseif (steleCount == 3) then\r\n    UI.openRewardsDialog(\"stele.description.tour\")\r\n    UI.addReward(27138)\r\n    UI.addReward(27279, \"stele.reward.stasis.21\")\r\n    UI.addReward(27083, \"stele.reward.stasis.21\")\r\n    \r\n    elseif (steleCount == 4) then\r\n    UI.openRewardsDialog(\"stele.description.tour\")\r\n    UI.addReward(27028, \"stele.reward.stasis.21\")\r\n    UI.addReward(27276, \"stele.reward.stasis.21\")\r\n    UI.addReward(27083, \"stele.reward.stasis.21\")\r\n    \r\n    else\r\n    \r\n    end\r\n    \r\n    local stateInfoId = \"stele.state.description.\" .. toString(steleStateId)\r\n    \r\n    updateSteleInfo(stateInfoId, true)\nend\n\n-- [STELE] Refresh des APS pour Stèles\n-- \nfunction event_2378_21815()\n    \nend\n\n-- [STASIS] DUNGEON_DIFFICULTY_CHANGED - Reset les stèles\n-- \nfunction event_2378_21816()\n    \nend\n\n-- USER_GROUP_KILLED - BOSS\n-- \nfunction event_2378_24322()\n    \nend\n\n-- [ARCHI] Apparition de l'Archimonstre\n-- \nfunction event_2378_24319()\n    \nend\n\n","functions":["hideDoor","closeSteleInfo","onSteleInfoClosed","updateSteleInfo","event_2378_21808","event_2378_20401","event_2378_20409","event_2378_21809","event_2378_21810","event_2378_21811","event_2378_21812","event_2378_21813","event_2378_21814","event_2378_21815","event_2378_21816","event_2378_24322","event_2378_24319"],"quest_calls":["UI.openRewardsDialog(\"stele.description.tour\")\r","UI.openRewardsDialog(\"stele.description.tour\")\r","UI.openRewardsDialog(\"stele.description.tour\")\r","UI.openRewardsDialog(\"stele.description.tour\")\r","UI.openRewardsDialog(\"stele.description.tour\")\r","UI.openRewardsDialog(\"stele.description.tour\")\r","UI.openRewardsDialog(\"stele.description.tour\")\r","UI.openRewardsDialog(\"stele.description.tour\")\r"],"dialogue_calls":[]},"scenario/2379.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\n\n-- [INIT] Variables\n-- \nfunction event_2379_20410()\n    \nend\n\n-- [EVENT] Le joueur arrive sur la Pandalousie - Cinématique\n-- \nfunction event_2379_20416()\n        local playerId = Context.getLeaderId()\r\n    \r\n    \t----------------------------- INITIALISATION DES PNJ --------------------------\r\n    \r\n    \tlocal pandiegoId = createActor(117905084, 0, -37, -79, 4, 5, 6)\r\n    \r\n    \tstartCinematicContext(1, playerId)\r\n      UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 20416)\r\n        \r\n      -- Début cinématique\r\n        \r\n      invoke_custom(000000, 1, \"Camera.setCamera\", 0.8, 0, 0, -80)\r\n    \tinvoke_custom(001900, 1, \"Camera.setMoveSpeedFactor\", 0.1)\r\n    \tinvoke_custom(002000, 1, \"Camera.scrollTo\", 18, -11, -80)\r\n    \tinvoke_custom(004000, 1, \"Mobile.moveMobile\", playerId, -1, -22, -80, \"Mobile.setMobileDirection\", playerId, 1)\r\n    \tinvoke_custom(006900, 1, \"Camera.setMoveSpeedFactor\", 0.2)\r\n    \tinvoke_custom(007000, 1, \"Camera.scrollTo\", 0, -32, -80)\r\n    \tinvoke_custom(013000, 1, \"Camera.scrollTo\", -27, -17, -69)\r\n    \tinvoke_custom(019000, 1, \"Camera.scrollTo\", -0, -22, -80)\r\n    \tinvoke_custom(022000, 1, \"Mobile.moveMobile\", pandiegoId, -1, -24, -80, \"Mobile.setMobileDirection\", pandiegoId, 3)\r\n    \r\n    \t-- \"Alors c'est ça, Pandala !\"\r\n    \tinvoke_custom(023000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Chercher\")\r\n    \tinvoke_custom(023000, 1, \"bubble\", playerId, \"quest.pandalousie.01.01\")\r\n      invoke_custom(025500, 1, \"clearBubbles\", playerId)\r\n    \r\n      invoke_custom(025500, 1, \"Camera.setCamera\", 1.5, 0, -24, -80)\r\n    \r\n    \t-- \"Qu'est-ce que tu viens de dire, {[1*]?fillette:bonhomme} ?\"\r\n    \tinvoke_custom(025500, 1, \"Mobile.setMobileAnimation\", pandiegoId, \"AnimComp-3\")\r\n    \tinvoke_custom(025500, 1, \"bubble\", pandiegoId, \"quest.pandalousie.01.02\")\r\n    \tinvoke_custom(030000, 1, \"clearBubbles\", pandiegoId)\r\n    \t\r\n    \t-- \"Tu viens de quel siècle, toi ?\"\r\n    \tinvoke_custom(030000, 1, \"Mobile.setMobileDirection\", playerId, 7)\r\n    \tinvoke_custom(030500, 1, \"bubble\", pandiegoId, \"quest.pandalousie.01.03\")\r\n    \tinvoke_custom(034000, 1, \"clearBubbles\", pandiegoId)\r\n    \t\r\n    \t-- \"Attendez, vous voulez dire que je me suis trompé{[1*]?e:} ?\"\r\n    \tinvoke_custom(034500, 1, \"bubble\", playerId, \"quest.pandalousie.01.04\")\r\n        invoke_custom(038500, 1, \"clearBubbles\", playerId)\r\n    \t\r\n    \t-- \"Pourtant, il y a des bambous et des Pandawas comme vous.\"\r\n    \tinvoke_custom(039000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Non\")\r\n    \tinvoke_custom(039500, 1, \"bubble\", playerId, \"quest.pandalousie.01.05\")\r\n        invoke_custom(044500, 1, \"clearBubbles\", playerId)\r\n    \r\n    \t-- \"Pandala a été inondée par le Chaos d'Ogrest. Tout le monde sait ça !\"\r\n    \tinvoke_custom(045000, 1, \"Mobile.setMobileAnimation\", pandiegoId, \"AnimComp-4\")\r\n    \tinvoke_custom(045000, 1, \"bubble\", pandiegoId, \"quest.pandalousie.01.06\")\r\n    \tinvoke_custom(039000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Effrayee\")\r\n    \tinvoke_custom(050000, 1, \"clearBubbles\", pandiegoId)\r\n    \t\r\n    \t-- \"Bienvenue en Pandalousie !\"\r\n    \tinvoke_custom(050500, 1, \"Mobile.setMobileAnimation\", pandiegoId, \"AnimComp-2\")\r\n    \tinvoke_custom(050500, 1, \"bubble\", pandiegoId, \"quest.pandalousie.01.07\")\r\n    \tinvoke_custom(053000, 1, \"clearBubbles\", pandiegoId)\r\n    \t\r\n    \t-- \"C'est plutôt rare de voir des aventuri{[1*]?ères:ers} dans ton genre se pointer dans la région.\"\r\n    \tinvoke_custom(054000, 1, \"Mobile.setMobileAnimation\", pandiegoId, \"AnimComp-1\")\r\n    \tinvoke_custom(054000, 1, \"bubble\", pandiegoId, \"quest.pandalousie.01.08\")\r\n    \tinvoke_custom(060000, 1, \"clearBubbles\", pandiegoId)\r\n    \t\r\n    \t-- \"Les derniers, c'était...\"\r\n    \tinvoke_custom(061000, 1, \"bubble\", pandiegoId, \"quest.pandalousie.01.09\")\r\n    \tinvoke_custom(063000, 1, \"clearBubbles\", pandiegoId)\r\n    \t\r\n    \t-- \"Eh bien oui, j'aime me promener un peu partout. Dites, il y a quoi à faire sur votre île ?\"\r\n    \tinvoke_custom(062000, 1, \"bubble\", playerId, \"quest.pandalousie.01.10\")\r\n    \tinvoke_custom(062000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Calmer\")\r\n    \tinvoke_custom(068000, 1, \"clearBubbles\", playerId)\r\n    \t\r\n    \t-- \"Haha, mon ami{[*]?e:}, tu es bien loin de te douter de la richesse de notre terre !\"\r\n    \tinvoke_custom(069000, 1, \"Mobile.setMobileAnimation\", pandiegoId, \"AnimComp-5\")\r\n    \tinvoke_custom(069000, 1, \"bubble\", pandiegoId, \"quest.pandalousie.01.11\")\r\n    \tinvoke_custom(076000, 1, \"clearBubbles\", pandiegoId)\r\n    \t\r\n    \t-- \"Hélas, une catastrophe a frappé notre belle Pandalousie il y a quelques mois.\"\r\n    \tinvoke_custom(077000, 1, \"Mobile.setMobileAnimation\", pandiegoId, \"AnimComp-4\")\r\n    \tinvoke_custom(077000, 1, \"bubble\", pandiegoId, \"quest.pandalousie.01.12\")\r\n    \tinvoke_custom(084000, 1, \"clearBubbles\", pandiegoId)\r\n    \t\r\n    \t-- \"Un groupe de Pandissidans en a profité pour prendre le contrôle de la ville et des réserves de Lait de Bambou.\"\r\n    \tinvoke_custom(085000, 1, \"bubble\", pandiegoId, \"quest.pandalousie.01.13\")\r\n    \tinvoke_custom(095000, 1, \"clearBubbles\", pandiegoId)\r\n    \t\r\n    \t-- \"Ah, c'est problématique quand même...\"\r\n    \tinvoke_custom(096000, 1, \"bubble\", playerId, \"quest.pandalousie.01.14\")\r\n    \tinvoke_custom(062000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    \tinvoke_custom(100000, 1, \"clearBubbles\", playerId)\r\n    \t\r\n    \t-- \"Oui, surtout qu'on a besoin de ce Lait de Bambou pour empêcher les habitants de l'île de se transformer en Soiffards !\"\r\n    \tinvoke_custom(101000, 1, \"Mobile.setMobileAnimation\", pandiegoId, \"AnimComp-5\")\r\n    \tinvoke_custom(101000, 1, \"bubble\", pandiegoId, \"quest.pandalousie.01.15\")\r\n    \tinvoke_custom(111000, 1, \"clearBubbles\", pandiegoId)\r\n    \r\n    \t-- \"Mais oui... Mais oui...\"\r\n    \tinvoke_custom(112000, 1, \"bubble\", playerId, \"quest.pandalousie.01.16\")\r\n    \tinvoke_custom(112000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Rire\")\r\n    \tinvoke_custom(115000, 1, \"clearBubbles\", playerId)\r\n    \t\r\n    \t-- \"Vous mourez de soif h