Cheveux\", 0.58, 0.88, 0.88, 1)\r\n    \r\n    startCinematicContext(1.2, playerId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 20475)\r\n    \r\n    invoke_custom(00001, 1, \"Mobile.setMobileVisible\", villageoisTwoId, false)\r\n    invoke_custom(00001, 1, \"Mobile.moveMobile\", playerId, -25, -17, -69, \"Mobile.setMobileDirection\", playerId, 1)\r\n    \r\n    invoke_custom(04000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Toux\")\r\n    invoke_custom(05000, 1, \"Mobile.setMobileDirection\", pandaFourId, 5)\r\n    \r\n    -- \"Peuple de la Pandalousie, Pandawas, écoutez-moi !\"\r\n    invoke_custom(06000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Help\")\r\n    invoke_custom(06000, 1, \"bubble\", playerId, \"quest.pandalousie.06.01\")\r\n    invoke_custom(07000, 1, \"Mobile.setMobileDirection\", pandaOneId, 5)\r\n    invoke_custom(07500, 1, \"Mobile.setMobileDirection\", pandaThreeId, 5)\r\n    invoke_custom(11000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Si l'écosystème de la Vallée est instable, c'est à cause de la culture intensive de Bambou.\"\r\n    invoke_custom(11500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Presenter\")\r\n    invoke_custom(11500, 1, \"bubble\", playerId, \"quest.pandalousie.06.02\")\r\n    invoke_custom(20000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Vous devez y renoncer si vous souhaitez garder vos terres.\"\r\n    invoke_custom(20500, 1, \"bubble\", playerId, \"quest.pandalousie.06.03\")\r\n    invoke_custom(26000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Sinon, la colère de l'Esprit ne cessera pas...\"\r\n    invoke_custom(26500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Non\")\r\n    invoke_custom(26500, 1, \"bubble\", playerId, \"quest.pandalousie.06.04\")\r\n    invoke_custom(30000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(31000, 1, \"Mobile.setMobileDirection\", pandaOneId, 7)\r\n    invoke_custom(31000, 1, \"Mobile.setMobileDirection\", pandaThreeId, 3)\r\n    \r\n    -- \"Qu'est-ce qu'il raconte ?\"\r\n    invoke_custom(31500, 1, \"Mobile.setMobileAnimation\", pandaOneId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(31500, 1, \"bubble\", pandaOneId, \"quest.pandalousie.06.05\")\r\n    invoke_custom(36000, 1, \"clearBubbles\", pandaOneId)\r\n    \r\n    -- \"Mais {[1*]?elle:il} vient d'où, {[1*]?elle:lui}, encore ?\"\r\n    invoke_custom(33500, 1, \"Mobile.setMobileAnimation\", pandaTwoId, \"AnimEmote-Colere\")\r\n    invoke_custom(33500, 1, \"bubble\", pandaTwoId, \"quest.pandalousie.06.06\")\r\n    invoke_custom(40000, 1, \"clearBubbles\", pandaTwoId)\r\n    \r\n    -- \"Nous avons toujours vécu comme ça.\"\r\n    invoke_custom(37500, 1, \"Mobile.setMobileAnimation\", pandaFourId, \"AnimEmote-Colere\")\r\n    invoke_custom(37500, 1, \"bubble\", pandaFourId, \"quest.pandalousie.06.07\")\r\n    \r\n    --\"Ecoutez, moi je vous dis juste la vérité, après vous en faites ce que vous voulez...\"\r\n    invoke_custom(38000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Calmer\")\r\n    invoke_custom(38000, 1, \"bubble\", playerId, \"quest.pandalousie.06.08\")\r\n    invoke_custom(46000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(38000, 1, \"Mobile.setMobileDirection\", pandaOneId, 5)\r\n    invoke_custom(38000, 1, \"Mobile.setMobileDirection\", pandaThreeId, 5)\r\n    \r\n    -- \"On ne va pas changer notre mode de vie d'un jour à l'autre !\"\r\n    invoke_custom(39500, 1, \"bubble\", pandaThreeId, \"quest.pandalousie.06.09\")\r\n    invoke_custom(45000, 1, \"clearBubbles\", pandaThreeId)\r\n    \r\n    invoke_custom(39500, 1, \"Mobile.setMobileAnimation\", pandaOneId, \"AnimEmote-HuerPasFan-Debut\")\r\n    invoke_custom(40500, 1, \"Mobile.setMobileAnimation\", pandaFourId, \"AnimEmote-HuerPasFan-Debut\")\r\n    invoke_custom(41500, 1, \"Mobile.setMobileAnimation\", pandaTwoId, \"AnimEmote-Colere\")\r\n    invoke_custom(44000, 1, \"Mobile.moveMobile\", pandaThreeId, 1, -17, -80)\r\n    invoke_custom(46000, 1, \"Mobile.moveMobile\", pandaFourId, 1, -17, -80)\r\n    \r\n    -- \"Va t'en, étrang{[1*]?ère:er} !\"\r\n    invoke_custom(46500, 1, \"Mobile.setMobileAnimation\", pandaTwoId, \"AnimEmote-Tarte\")\r\n    invoke_custom(46500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimTarget-Tarte\")\r\n    invoke_custom(46500, 1, \"bubble\", pandaTwoId, \"quest.pandalousie.06.10\")\r\n    invoke_custom(50000, 1, \"clearBubbles\", pandaTwoId)\r\n    invoke_custom(50000, 1, \"Mobile.moveMobile\", pandaTwoId, 1, -17, -80)\r\n    invoke_custom(50000, 1, \"Mobile.moveMobile\", pandaOneId, 1, -17, -80)\r\n    \r\n    invoke_custom(52000, 1, \"Mobile.moveMobile\", playerId, -23, -14, -72, \"Mobile.setMobileDirection\", playerId, 5)\r\n    \r\n    -- \"Bon, c'était une purge...\"\r\n    invoke_custom(54500, 1, \"Mobile.setMobileAnimation\", pandiegoId, \"AnimComp-2\")\r\n    invoke_custom(54500, 1, \"bubble\", pandiegoId, \"quest.pandalousie.06.11\")\r\n    invoke_custom(58000, 1, \"clearBubbles\", pandiegoId)\r\n    \r\n    -- \"Peut-être qu'ils comprendront un jour, petit à petit.\"\r\n    invoke_custom(58500, 1, \"bubble\", playerId, \"quest.pandalousie.06.12\")\r\n    invoke_custom(63000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Tu as fait tout ce que tu as pu, {[1*]?fillette:bonhomme}.\"\r\n    invoke_custom(63500, 1, \"Mobile.setMobileAnimation\", pandiegoId, \"AnimComp-4\")\r\n    invoke_custom(63500, 1, \"bubble\", pandiegoId, \"quest.pandalousie.06.13\")\r\n    invoke_custom(69000, 1, \"clearBubbles\", pandiegoId)\r\n    \r\n    -- \"Je t'en suis reconnaissant.\"\r\n    invoke_custom(69500, 1, \"Mobile.setMobileAnimation\", pandiegoId, \"AnimComp-5\")\r\n    invoke_custom(69500, 1, \"bubble\", pandiegoId, \"quest.pandalousie.06.14\")\r\n    invoke_custom(74000, 1, \"clearBubbles\", pandiegoId)\r\n    \r\n    -- \"Mais je pense que tu peux partir, maintenant.\"\r\n    invoke_custom(74500, 1, \"bubble\", pandiegoId, \"quest.pandalousie.06.15\")\r\n    invoke_custom(79000, 1, \"clearBubbles\", pandiegoId)\r\n    invoke_custom(80000, 1, \"Mobile.moveMobile\", pandiegoId, -24, -16, -80)\r\n    invoke_custom(81000, 1, \"Mobile.moveMobile\", pandiegoId, 1, -16, -80)\r\n    \r\n    -- \"**J'ai déjà fait tout ce que je pouvais...\"\r\n    invoke_custom(81500, 1, \"Mobile.setMobileDirection\", playerId, 3)\r\n    invoke_custom(81500, 1, \"bubble\", playerId, \"quest.pandalousie.06.16\")\r\n    invoke_custom(85000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"**... Non, j'ai l'impression que j'oublie quelque chose...\"\r\n    invoke_custom(86500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Non\")\r\n    invoke_custom(86000, 1, \"bubble\", playerId, \"quest.pandalousie.06.17\")\r\n    invoke_custom(91000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"**C'est vrai, j'ai aperçu Otomaï à la soirée.\"\r\n    invoke_custom(91500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(91500, 1, \"bubble\", playerId, \"quest.pandalousie.06.18\")\r\n    invoke_custom(96000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"**Mais il n'avait aucun souvenir d'être venu à cette soirée.\"\r\n    invoke_custom(096500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Non\")\r\n    invoke_custom(096500, 1, \"bubble\", playerId, \"quest.pandalousie.06.19\")\r\n    invoke_custom(102000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"**Il m'a aussi dit qu'il n'y avait eu aucun aventurier depuis longtemps sur la Pandalousie.\"\r\n    invoke_custom(102500, 1, \"bubble\", playerId, \"quest.pandalousie.06.20\")\r\n    invoke_custom(110000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"**Pourtant, Pandiego dit que des gens sont venus il y a peu, pour affronter les Soiffards.\"\r\n    invoke_custom(110500, 1, \"bubble\", playerId, \"quest.pandalousie.06.21\")\r\n    invoke_custom(118000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"**Qui étaient ces gens ?\"\r\n    invoke_custom(118500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(118500, 1, \"bubble\", playerId, \"quest.pandalousie.06.22\")\r\n    invoke_custom(122000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(123000, 1, \"skipCinematic\", 20475)\nend\n\n-- [EVENT] Fin de la cinématique - ACH 4662 OBJ 9598\n-- \nfunction event_2379_20476()\n    \nend\n\n-- [EVENT] Le joueur arrive sur la Pandalousie - réinitialisation variables locales\n-- \nfunction event_2379_21219()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_2379_20410","event_2379_20416","event_2379_20418","event_2379_20466","event_2379_20467","event_2379_20468","event_2379_20469","event_2379_20470","event_2379_20471","event_2379_20472","event_2379_20473","event_2379_20474","event_2379_20475","event_2379_20476","event_2379_21219"],"quest_calls":[],"dialogue_calls":[]},"scenario/2380.lua":{"source":"bubbleSteleInfoId = 0\r\n\r\nfunction closeSteleInfo()\r\n\tif (bubbleSteleInfoId ~= nil  and bubbleSteleInfoId ~= 0) then BubbleText.close(bubbleSteleInfoId) end\r\nend\r\n\r\nfunction onSteleInfoClosed()\r\n\tif (bubbleSteleInfoId ~= nil  and bubbleSteleInfoId ~= 0) then bubbleSteleInfoId = 0 end\r\nend\r\n\r\nfunction updateSteleInfo(stateInfoId, forceDisplayUI)\r\n\r\n\tif (bubbleSteleInfoId == 0) then\r\n\t\tbubbleSteleInfoId = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_WEST\", 0, -60, false, 2147483647, true, \"interactiveBubbleDialog5\", 30000, 25000, \"onSteleInfoClosed\")\r\n\tend\r\n\r\n\tBubbleText.setText(bubbleSteleInfoId, stateInfoId)\r\n\t\r\n\tif (forceDisplayUI) then BubbleText.show(bubbleSteleInfoId) end\r\nend\n\n-- [INIT] Variables Globales\n-- \nfunction event_2380_20419()\n    \nend\n\n-- [INIT] Inscription du joueur + Variables Locales\n-- \nfunction event_2380_20420()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 01\n-- \nfunction event_2380_20421()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 02\n-- \nfunction event_2380_20422()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 03\n-- \nfunction event_2380_20423()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 04 - BOSS\n-- \nfunction event_2380_20424()\n    \nend\n\n-- Déplace le joueur vers la salle suivante\n-- \nfunction event_2380_20425()\n    \nend\n\n-- [OLD][EVENT] Le joueur examine la Stèle 1\n-- \nfunction event_2380_20558(steleCount)\n    local steleCount = toLong(steleCount)\r\n    if (steleCount == 0) then rewardId = 27140\r\n    elseif (steleCount == 1) then rewardId = 27148\r\n    elseif (steleCount == 2) then rewardId = 27147\r\n    else rewardId = 0\r\n    end\r\n    \r\n    UI.openRewardsDialog(\"stele.description\")\r\n    UI.addReward(rewardId)\r\n    \r\n    local stateInfoId = \"stele.state.description.6123\"\r\n    \r\n    updateSteleInfo(stateInfoId, true)\nend\n\n-- [OLD][EVENT] Le joueur examine la Stèle 2\n-- \nfunction event_2380_20559(steleCount)\n    local steleCount = toLong(steleCount)\r\n    if (steleCount == 0) then rewardId = 27140\r\n    elseif (steleCount == 1) then rewardId = 27148\r\n    elseif (steleCount == 2) then rewardId = 27147\r\n    else rewardId = 0\r\n    end\r\n    \r\n    UI.openRewardsDialog(\"stele.description\")\r\n    UI.addReward(rewardId)\r\n    \r\n    local stateInfoId = \"stele.state.description.6124\"\r\n    \r\n    updateSteleInfo(stateInfoId, true)\nend\n\n-- [OLD][EVENT] Le joueur examine la Stèle 3\n-- \nfunction event_2380_20560(steleCount)\n    local steleCount = toLong(steleCount)\r\n    if (steleCount == 0) then rewardId = 27140\r\n    elseif (steleCount == 1) then rewardId = 27148\r\n    elseif (steleCount == 2) then rewardId = 27147\r\n    else rewardId = 0\r\n    end\r\n    \r\n    UI.openRewardsDialog(\"stele.description\")\r\n    UI.addReward(rewardId)\r\n    \r\n    local stateInfoId = \"stele.state.description.6125\"\r\n    \r\n    updateSteleInfo(stateInfoId, true)\nend\n\n-- [OLD][EVENT] Activation Stèle 1\n-- \nfunction event_2380_20561(steleCount)\n    local steleCount = toLong(steleCount)\r\n    if (steleCount == 1) then rewardId = 27140\r\n    elseif (steleCount == 2) then rewardId = 27148\r\n    elseif (steleCount == 3) then rewardId = 27147\r\n    else rewardId = 0\r\n    end\r\n    \r\n    UI.openRewardsDialog(\"stele.activation\")\r\n    UI.addReward(rewardId)\nend\n\n-- [OLD][EVENT] Activation Stèle 2\n-- \nfunction event_2380_20562(steleCount)\n    local steleCount = toLong(steleCount)\r\n    if (steleCount == 1) then rewardId = 27140\r\n    elseif (steleCount == 2) then rewardId = 27148\r\n    elseif (steleCount == 3) then rewardId = 27147\r\n    else rewardId = 0\r\n    end\r\n    \r\n    UI.openRewardsDialog(\"stele.activation\")\r\n    UI.addReward(rewardId)\nend\n\n-- [OLD][EVENT] Activation Stèle 3\n-- \nfunction event_2380_20563(steleCount)\n    local steleCount = toLong(steleCount)\r\n    if (steleCount == 1) then rewardId = 27140\r\n    elseif (steleCount == 2) then rewardId = 27148\r\n    elseif (steleCount == 3) then rewardId = 27147\r\n    else rewardId = 0\r\n    end\r\n    \r\n    UI.openRewardsDialog(\"stele.activation\")\r\n    UI.addReward(rewardId)\nend\n\n-- [OLD][EVENT] Refresh des APS pour Stèles\n-- \nfunction event_2380_20564()\n    \nend\n\n-- [OLD][EVENT] On lance un combat contre le boss - On rend invisibles les stèles\n-- \nfunction event_2380_20565()\n    \nend\n\n-- [OLD][EVENT] On termine un combat contre le boss - On rend visibles les stèles\n-- \nfunction event_2380_20566()\n    \nend\n\n-- [OLD][EVENT] DUNGEON_DIFFICULTY_CHANGED - On désactive les états stèles\n-- \nfunction event_2380_20610()\n    \nend\n\n-- [STELE] FIGHT_STARTED - On applique les difficultés sur le boss\n-- \nfunction event_2380_22815()\n    \nend\n\n-- [STELE] FIGHT_ENTER_ACTION_PHASE - On applique les bonus sur les joueurs\n-- \nfunction event_2380_22816()\n    \nend\n\n-- [STELE] FIGHT_ENDED - On rend la stèle utilisable en cas de défaite\n-- \nfunction event_2380_22900()\n    \nend\n\n-- [ARCHI] Apparition de l'Archimonstre\n-- \nfunction event_2380_24008()\n    \nend\n\n","functions":["closeSteleInfo","onSteleInfoClosed","updateSteleInfo","event_2380_20419","event_2380_20420","event_2380_20421","event_2380_20422","event_2380_20423","event_2380_20424","event_2380_20425","event_2380_20558","event_2380_20559","event_2380_20560","event_2380_20561","event_2380_20562","event_2380_20563","event_2380_20564","event_2380_20565","event_2380_20566","event_2380_20610","event_2380_22815","event_2380_22816","event_2380_22900","event_2380_24008"],"quest_calls":["UI.openRewardsDialog(\"stele.description\")\r","UI.openRewardsDialog(\"stele.description\")\r","UI.openRewardsDialog(\"stele.description\")\r","UI.openRewardsDialog(\"stele.activation\")\r","UI.openRewardsDialog(\"stele.activation\")\r","UI.openRewardsDialog(\"stele.activation\")\r"],"dialogue_calls":[]},"scenario/2381.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\nbubbleSteleInfoId = 0\r\n\r\nfunction closeSteleInfo()\r\n\tif (bubbleSteleInfoId ~= nil  and bubbleSteleInfoId ~= 0) then BubbleText.close(bubbleSteleInfoId) end\r\nend\r\n\r\nfunction onSteleInfoClosed()\r\n\tif (bubbleSteleInfoId ~= nil  and bubbleSteleInfoId ~= 0) then bubbleSteleInfoId = 0 end\r\nend\r\n\r\nfunction updateSteleInfo(stateInfoId, forceDisplayUI)\r\n\r\n\tif (bubbleSteleInfoId == 0) then\r\n\t\tbubbleSteleInfoId = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_WEST\", 0, -60, false, 2147483647, true, \"interactiveBubbleDialog5\", 30000, 25000, \"onSteleInfoClosed\")\r\n\tend\r\n\r\n\tBubbleText.setText(bubbleSteleInfoId, stateInfoId)\r\n\t\r\n\tif (forceDisplayUI) then BubbleText.show(bubbleSteleInfoId) end\r\nend\r\n\r\n\r\n\r\n-- les fonctions où on cache\r\nfunction hideMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, false)\r\nend\r\n\r\nfunction hidePart(monsterMobileId, partName)\r\n\tMobile.setPartVisible(monsterMobileId, false, partName)\r\nend\r\n\r\n-- les fonctions où on rend visible (à nouveau)\r\nfunction showMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, true)\r\nend\r\n\r\nfunction showPart(monsterMobileId, partName)\r\n\tMobile.setPartVisible(monsterMobileId, true, partName)\r\nend\n\n-- [INIT] Variables Globales\n-- \nfunction event_2381_20426()\n    \nend\n\n-- [INIT] Inscription du joueur + Variables Locales\n-- \nfunction event_2381_20427()\n    \nend\n\n-- *[OLD][1] Victoire - Déverouille le passage vers S2\n-- \nfunction event_2381_20428()\n    \nend\n\n-- *[OLD][2] Victoire - Déverouille le passage vers S3\n-- \nfunction event_2381_20429()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 01\n-- \nfunction event_2381_20430()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 02 - BOSS\n-- \nfunction event_2381_20431()\n    \nend\n\n-- Déplace le joueur vers la salle suivante\n-- \nfunction event_2381_20432()\n    \nend\n\n-- [EVENT] On rend les monstres de la salle du boss inattaquable\n-- Cela nous permet d'éviter d'avoir la mauvaise bulle de combat sur le combat du boss\nfunction event_2381_20445()\n    \nend\n\n-- [EVENT] Victoire sur le Tanukouï-San - On fait apparaître le Fantôme Inconnu (ACH 4674)\n-- \nfunction event_2381_20461()\n    \nend\n\n-- [EVENT] Le joueur parle au Fantôme Inconnu, il est tp hors du donjon (ACH 4674)\n-- \nfunction event_2381_20462()\n    \nend\n\n-- [OLD][EVENT] Le joueur examine la Stèle 1\n-- \nfunction event_2381_20567(steleCount)\n    local steleCount = toLong(steleCount)\r\n    if (steleCount == 0) then rewardId = 27136\r\n    elseif (steleCount == 1) then rewardId = 27142\r\n    elseif (steleCount == 2) then rewardId = 27115\r\n    else rewardId = 0\r\n    end\r\n    \r\n    UI.openRewardsDialog(\"stele.description\")\r\n    UI.addReward(rewardId)\r\n    \r\n    local stateInfoId = \"stele.state.description.6126\"\r\n    \r\n    updateSteleInfo(stateInfoId, true)\nend\n\n-- [OLD][EVENT] Le joueur examine la Stèle 2\n-- \nfunction event_2381_20568(steleCount)\n    local steleCount = toLong(steleCount)\r\n    if (steleCount == 0) then rewardId = 27136\r\n    elseif (steleCount == 1) then rewardId = 27142\r\n    elseif (steleCount == 2) then rewardId = 27115\r\n    else rewardId = 0\r\n    end\r\n    \r\n    UI.openRewardsDialog(\"stele.description\")\r\n    UI.addReward(rewardId)\r\n    \r\n    local stateInfoId = \"stele.state.description.6127\"\r\n    \r\n    updateSteleInfo(stateInfoId, true)\nend\n\n-- [OLD][EVENT] Le joueur examine la Stèle 3\n-- \nfunction event_2381_20569(steleCount)\n    local steleCount = toLong(steleCount)\r\n    if (steleCount == 0) then rewardId = 27136\r\n    elseif (steleCount == 1) then rewardId = 27142\r\n    elseif (steleCount == 2) then rewardId = 27115\r\n    else rewardId = 0\r\n    end\r\n    \r\n    UI.openRewardsDialog(\"stele.description\")\r\n    UI.addReward(rewardId)\r\n    \r\n    local stateInfoId = \"stele.state.description.6128\"\r\n    \r\n    updateSteleInfo(stateInfoId, true)\nend\n\n-- [OLD][EVENT] Activation Stèle 1\n-- \nfunction event_2381_20570(steleCount)\n    local steleCount = toLong(steleCount)\r\n    if (steleCount == 1) then rewardId = 27136\r\n    elseif (steleCount == 2) then rewardId = 27142\r\n    elseif (steleCount == 3) then rewardId = 27115\r\n    else rewardId = 0\r\n    end\r\n    \r\n    UI.openRewardsDialog(\"stele.activation\")\r\n    UI.addReward(rewardId)\nend\n\n-- [OLD][EVENT] Activation Stèle 2\n-- \nfunction event_2381_20571(steleCount)\n    local steleCount = toLong(steleCount)\r\n    if (steleCount == 1) then rewardId = 27136\r\n    elseif (steleCount == 2) then rewardId = 27142\r\n    elseif (steleCount == 3) then rewardId = 27115\r\n    else rewardId = 0\r\n    end\r\n    \r\n    UI.openRewardsDialog(\"stele.activation\")\r\n    UI.addReward(rewardId)\nend\n\n-- [OLD][EVENT] Activation Stèle 3\n-- \nfunction event_2381_20572(steleCount)\n    local steleCount = toLong(steleCount)\r\n    if (steleCount == 1) then rewardId = 27136\r\n    elseif (steleCount == 2) then rewardId = 27142\r\n    elseif (steleCount == 3) then rewardId = 27115\r\n    else rewardId = 0\r\n    end\r\n    \r\n    UI.openRewardsDialog(\"stele.activation\")\r\n    UI.addReward(rewardId)\nend\n\n-- [OLD][EVENT] Refresh des APS pour Stèles\n-- \nfunction event_2381_20573()\n    \nend\n\n-- [EVENT] Démarrage du combat - Pose des zones flag\n-- \nfunction event_2381_20607()\n    \nend\n\n-- [OLD][EVENT] DUNGEON_DIFFICULTY_CHANGED - On désactive les états stèles\n-- \nfunction event_2381_20609()\n    \nend\n\n-- Lancement d'un combat - Application de la protection fantomatique\n-- \nfunction event_2381_21919()\n    \nend\n\n-- [STELE] FIGHT_STARTED - On applique les difficultés sur le boss\n-- \nfunction event_2381_22813()\n    \nend\n\n-- [STELE] FIGHT_ENTER_ACTION_PHASE - On applique les bonus sur les joueurs\n-- \nfunction event_2381_22814()\n    \nend\n\n-- [STELE] FIGHT_ENDED - On rend la stèle utilisable en cas de défaite\n-- \nfunction event_2381_22892()\n    \nend\n\n-- [ARCHI] Apparition de l'Archimonstre\n-- \nfunction event_2381_24007()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","closeSteleInfo","onSteleInfoClosed","updateSteleInfo","hideMonster","hidePart","showMonster","showPart","event_2381_20426","event_2381_20427","event_2381_20428","event_2381_20429","event_2381_20430","event_2381_20431","event_2381_20432","event_2381_20445","event_2381_20461","event_2381_20462","event_2381_20567","event_2381_20568","event_2381_20569","event_2381_20570","event_2381_20571","event_2381_20572","event_2381_20573","event_2381_20607","event_2381_20609","event_2381_21919","event_2381_22813","event_2381_22814","event_2381_22892","event_2381_24007"],"quest_calls":["UI.openRewardsDialog(\"stele.description\")\r","UI.openRewardsDialog(\"stele.description\")\r","UI.openRewardsDialog(\"stele.description\")\r","UI.openRewardsDialog(\"stele.activation\")\r","UI.openRewardsDialog(\"stele.activation\")\r","UI.openRewardsDialog(\"stele.activation\")\r"],"dialogue_calls":[]},"scenario/2382.lua":{"source":"\n\n-- [EVENT] Sokoban - Lancement\n-- \nfunction event_2382_20437()\n    UI.loadTutorialDialog(\"null\",\"quest.nations.ch04.sokoban.tutorial.title\",\"quest.nations.ch04.sokoban.tutorial.desc\")\r\n    Mobile.setMobileAnimationStaticKey(Context.getLeaderId(), \"AnimStatique01\")\nend\n\n-- [EVENT] Sokoban - Début\n-- \nfunction event_2382_20438()\n    \nend\n\n-- [EVENT] Sokoban - Victoire - on notifie pour ACH 4660 OBJ 9576\n-- \nfunction event_2382_20439()\n    \nend\n\n-- [EVENT] Sokoban - Fin du combat - le joueur est téléporté hors de la zone\n-- \nfunction event_2382_20477()\n    \nend\n\n","functions":["event_2382_20437","event_2382_20438","event_2382_20439","event_2382_20477"],"quest_calls":[],"dialogue_calls":[]},"scenario/2383.lua":{"source":"\n\n-- [EVENT] Glyphe Buisson activé\n-- \nfunction event_2383_20440()\n    \nend\n\n-- [EVENT] Glyphe Ozate activé\n-- Achievement 4664\nfunction event_2383_20441()\n    \nend\n\n-- [EVENT] On lance un combat contre un Plantala\n-- \nfunction event_2383_20442()\n    \nend\n\n","functions":["event_2383_20440","event_2383_20441","event_2383_20442"],"quest_calls":[],"dialogue_calls":[]},"scenario/2384.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\n-- les fonctions où on cache\r\nfunction hideMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, false)\r\nend\r\n\r\nfunction hidePart(monsterMobileId, partName)\r\n\tMobile.setPartVisible(monsterMobileId, false, partName)\r\nend\r\n\r\n-- les fonctions où on rend visible (à nouveau\r\nfunction showMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, true)\r\nend\r\n\r\nfunction showPart(monsterMobileId, partName)\r\n\tMobile.setPartVisible(monsterMobileId, true, partName)\r\nend\n\n-- [INITIALISATION] Serveur\n-- \nfunction event_2384_20443()\n    \nend\n\n-- [EVENT] Cinématique - Le joueur rencontre le Forgeron\n-- \nfunction event_2384_20451(forgeronId)\n    \tlocal playerId = Context.getLeaderId()\r\n    \tlocal playerX, playerY, playerZ = Mobile.getMobilePosition(playerId)\r\n    \r\n    \tlocal forgeronId = toLong(forgeronId)\r\n    \r\n    \tstartCinematicContext(1.5, playerId)\r\n    \tUI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\")\r\n    \r\n    \t--\"Salut ! Vous auriez des informations sur la \"forêt calcinée\" ?\"\r\n    \tinvoke_custom(1000, 1, \"bubble\", playerId, \"quest.pandalousie.mercenary.03.01\")\r\n    \tinvoke_custom(1000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Coucou\")\r\n    \tinvoke_custom(6500, 1, \"clearBubbles\", playerId)\r\n    \r\n    \t--\"Hmmm... C'est une histoire sanglante que je vais te raconter.\"\r\n    \tinvoke_custom(6500, 1, \"bubble\", forgeronId, \"quest.pandalousie.mercenary.03.02\")\r\n    \tinvoke_custom(6500, 1, \"Mobile.setMobileAnimation\", forgeronId, \"AnimComp-Non\")\r\n    \tinvoke_custom(12500, 1, \"clearBubbles\", forgeronId)\r\n    \r\n    \t--\"C'était une forêt de bambou très dense et très belle.\"\r\n    \tinvoke_custom(13000, 1, \"bubble\", forgeronId, \"quest.pandalousie.mercenary.03.03\")\r\n    \tinvoke_custom(16500, 1, \"clearBubbles\", forgeronId)\r\n    \r\n    \t--\"Elle abritait les Fléopards. Mais jadis, ce n'était pas une race hostile.\"\r\n    \tinvoke_custom(17000, 1, \"bubble\", forgeronId, \"quest.pandalousie.mercenary.03.04\")\r\n    \tinvoke_custom(22500, 1, \"clearBubbles\", forgeronId)\r\n    \r\n    \t--\"Ils ont commencé à devenir hargneux quand les Pandawas ont pratiqué la déforestation. Leur but était le lait de bambou, évidemment.\"\r\n    \tinvoke_custom(23000, 1, \"bubble\", forgeronId, \"quest.pandalousie.mercenary.03.05\")\r\n    \tinvoke_custom(33000, 1, \"clearBubbles\", forgeronId)\r\n    \r\n    \t--\"Le sol est devenu pourri, et les bambous ont commencé à devenir mortels pour les Pandawas.\"\r\n    \tinvoke_custom(33500, 1, \"bubble\", forgeronId, \"quest.pandalousie.mercenary.03.06\")\r\n    \tinvoke_custom(40500, 1, \"clearBubbles\", forgeronId)\r\n    \r\n    \t--\"Pour faire face à ce fléau, nous... Le peuple Pandalou a mis le feu à la forêt.\"\r\n    \tinvoke_custom(41000, 1, \"bubble\", forgeronId, \"quest.pandalousie.mercenary.03.07\")\r\n    \tinvoke_custom(47500, 1, \"clearBubbles\", forgeronId)\r\n    \r\n    \t--\"Le but était d'éloigner les Fléopards du village, et de pratiquer de la culture par brûlis pour y replanter des jeunes bambous sur un sol purifié.\"\r\n    \tinvoke_custom(48000, 1, \"bubble\", forgeronId, \"quest.pandalousie.mercenary.03.08\")\r\n    \tinvoke_custom(57500, 1, \"clearBubbles\", forgeronId)\r\n    \r\n    \t--\"Mais la terre était encore plus maudite que nous le pensions, et elle ne fait que brûler éternellement depuis.\"\r\n    \tinvoke_custom(58000, 1, \"bubble\", forgeronId, \"quest.pandalousie.mercenary.03.09\")\r\n    \tinvoke_custom(67000, 1, \"clearBubbles\", forgeronId)\r\n    \r\n    \tinvoke_custom(67500, 1, \"skipCinematic\")\nend\n\n-- [EVENT] Cinématique - Le joueur ramène le lait de bambou et fait la fête\n-- \nfunction event_2384_20464(cineMoogrr)\n    \t\r\n    \t----------------------------- RECUPERATIONS DES INFOS JOUEUR --------------------------\r\n    \r\n    \tlocal playerId = Context.getLeaderId()\r\n    \r\n    \t----------------------------- INITIALISATION DES VARIABLES --------------------------\r\n    \r\n    \tlocal pandaOneId = createActor(120, 115, 115, 0, 8, 5, 6)\r\n    \tlocal pandaTwoId = createActor(120, 122, 121, 0, 8, 3, 6)\r\n    \tlocal pandaThreeId = createActor(121, 122, 122, 0, 8, 7, 6)\r\n    \tlocal pandaFourId = createActor(121, 115, 120, 0, 8, 1, 6)\r\n    \tlocal barrelOneId = createActor(165203242, 118, 119, 0, 8, 1, 3)\r\n    \tlocal barrelTwoId = createActor(165203242, 118, 120, 0, 8, 1, 3)\r\n    \tlocal barrelThreeId = createActor(165203242, 118, 121, 0, 8, 1, 3)\r\n    \r\n    \t----------------------------- PERSONNALISATION DES PNJ --------------------------\r\n    \r\n    \tActor.equip(pandaOneId, \"201200001\", \"CHEVEUXCUSTOM\")\r\n    \tActor.equip(pandaOneId, \"211200001\", \"VETEMENTCUSTOM\")\r\n    \tActor.equip(pandaOneId, \"1347574\", \"Chapeau\")\r\n    \tMobile.setPartColor(pandaOneId, \"Pupille\", 0.00, 0.00, 0.00, 1)\r\n    \tMobile.setPartColor(pandaOneId, \"Peau\", 0.96, 0.72, 0.48, 1)\r\n    \tMobile.setPartColor(pandaOneId, \"Cheveux\", 0.88, 0.88, 0.88, 1)\r\n    \r\n    \tActor.equip(pandaTwoId, \"201200002\", \"CHEVEUXCUSTOM\")\r\n    \tActor.equip(pandaTwoId, \"211200002\", \"VETEMENTCUSTOM\")\r\n    \tActor.equip(pandaTwoId, \"13410240\", \"Chapeau\")\r\n    \tMobile.setPartColor(pandaTwoId, \"Pupille\", 0.00, 0.00, 0.00, 1)\r\n    \tMobile.setPartColor(pandaTwoId, \"Peau\", 0.76, 0.72, 0.48, 1)\r\n    \tMobile.setPartColor(pandaTwoId, \"Cheveux\", 0.88, 0.88, 0.88, 1)\r\n    \r\n    \tActor.equip(pandaThreeId, \"201210002\", \"CHEVEUXCUSTOM\")\r\n    \tActor.equip(pandaThreeId, \"211210004\", \"VETEMENTCUSTOM\")\r\n    \tMobile.setPartColor(pandaThreeId, \"Pupille\", 0.00, 0.00, 0.00, 1)\r\n    \tMobile.setPartColor(pandaThreeId, \"Peau\", 0.76, 0.72, 0.48, 1)\r\n    \tMobile.setPartColor(pandaThreeId, \"Cheveux\", 0.58, 0.88, 0.88, 1)\r\n    \r\n    \tActor.equip(pandaFourId, \"201210001\", \"CHEVEUXCUSTOM\")\r\n    \tActor.equip(pandaFourId, \"211210005\", \"VETEMENTCUSTOM\")\r\n    \tMobile.setPartColor(pandaFourId, \"Pupille\", 0.00, 0.00, 0.00, 1)\r\n    \tMobile.setPartColor(pandaFourId, \"Peau\", 0.76, 0.72, 0.48, 1)\r\n    \tMobile.setPartColor(pandaFourId, \"Cheveux\", 0.58, 0.88, 0.88, 1)\r\n    \r\n    \t----------------------------- DEBUT DE CINEMATIQUE -------------------------- \r\n    \r\n    \tstartCinematicContext(1.4, playerId)\r\n    \tUI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 20464)\r\n    \r\n    \t----------------------------- GROSSE RAVE PARTY -------------------------- \r\n        invoke_custom(0001, 1, \"Mobile.setMobileVisible\", barrelOneId, false)\r\n        invoke_custom(0001, 1, \"Mobile.setMobileVisible\", barrelTwoId, false)\r\n        invoke_custom(0001, 1, \"Mobile.setMobileVisible\", barrelThreeId, false)\r\n    \r\n    \tinvoke_custom(01000, 1, \"Mobile.setMobileDirection\", playerId, 5)\r\n    \t\r\n     \t-- \"Hé, tavernière ! Une choppe de lait de Bambou pour moi !\"\r\n        invoke_custom(02000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Help\")\r\n    \tinvoke_custom(02000, 1, \"bubble\", playerId, \"quest.pandalousie.03.01\")\r\n    \tinvoke_custom(06000, 1, \"Mobile.setMobileDirection\", playerId, 5)\r\n        invoke_custom(07000, 1, \"clearBubbles\", playerId)\r\n     \r\n      \t-- \"Hmpf, nous n'en avons plus. Je peux vous proposer une bière de Bonta...\"\r\n        invoke_custom(07000, 1, \"Mobile.setMobileAnimation\", pandaFourId, \"AnimEmote-Non\")\r\n    \tinvoke_custom(07000, 1, \"bubble\", pandaFourId, \"quest.pandalousie.03.02\")\r\n        invoke_custom(12000, 1, \"clearBubbles\", pandaFourId)\r\n     \r\n     \t-- \"Mauvaise réponse, l'amie !\"\r\n        invoke_custom(13000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-FeeArtifice\")\r\n    \tinvoke_custom(13000, 1, \"bubble\", playerId, \"quest.pandalousie.03.03\")\r\n    \tinvoke_custom(14000, 1, \"Mobile.setMobileVisible\", barrelOneId, true)\r\n        invoke_custom(14000, 1, \"Mobile.setMobileAnimation\", barrelOneId, \"AnimApparition\")\r\n    \tinvoke_custom(15000, 1, \"Mobile.setMobileDirection\", pandaThreeId, 5)    \r\n        invoke_custom(15000, 1, \"Mobile.setMobileAnimation\", pandaThreeId, \"AnimEmote-Effrayee\")\r\n       \tinvoke_custom(15500, 1, \"Mobile.setMobileVisible\", barrelTwoId, true)\r\n        invoke_custom(15500, 1, \"Mobile.setMobileAnimation\", barrelTwoId, \"AnimApparition\")\r\n    \tinvoke_custom(16000, 1, \"Mobile.setMobileDirection\", pandaTwoId, 5)    \r\n       \tinvoke_custom(17000, 1, \"Mobile.setMobileVisible\", barrelThreeId, true)\r\n        invoke_custom(17000, 1, \"Mobile.setMobileAnimation\", barrelThreeId, \"AnimApparition\")\r\n    \tinvoke_custom(17000, 1, \"Mobile.setMobileDirection\", pandaOneId, 3)\r\n        invoke_custom(17000, 1, \"clearBubbles\", playerId)\r\n        \r\n        -- \"C'est ma tournée !\"\r\n    \tinvoke_custom(18000, 1, \"bubble\", playerId, \"quest.pandalousie.03.04\")\r\n     \tinvoke_custom(18000, 1, \"Mobile.setMobileDirection\", playerId, 1)    \r\n        invoke_custom(19000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Boire\")\r\n    \tinvoke_custom(20000, 1, \"bubble\", pandaOneId, \"quest.pandalousie.03.05\")    \r\n    \tinvoke_custom(20000, 1, \"bubble\", pandaTwoId, \"quest.pandalousie.03.05\")    \r\n    \tinvoke_custom(20000, 1, \"bubble\", pandaThreeId, \"quest.pandalousie.03.05\")    \r\n    \tinvoke_custom(20000, 1, \"bubble\", pandaFourId, \"quest.pandalousie.03.05\")    \r\n        invoke_custom(20000, 1, \"Mobile.setMobileAnimation\", pandaOneId, \"AnimEmote-EncouragerFan-Debut\")\r\n        invoke_custom(20000, 1, \"Mobile.setMobileAnimation\", pandaTwoId, \"AnimEmote-EncouragerFan-Debut\")\r\n        invoke_custom(20000, 1, \"Mobile.setMobileAnimation\", pandaThreeId, \"AnimEmote-EncouragerFan-Debut\")\r\n        invoke_custom(20000, 1, \"Mobile.setMobileAnimation\", pandaFourId, \"AnimEmote-EncouragerFan-Debut\")\r\n       \r\n    \tinvoke_custom(22000, 1, \"skipCinematic\", 20464)   \nend\n\n-- [EVENT] Fin de la cinématique - Notif (ACH 4660 OBJ 9577) + le joueur est tp\n-- \nfunction event_2384_20465()\n    \nend\n\n-- [EVENT] Ajout du PNJ Suiveur - masquage du PNJ monde - start\n-- \nfunction event_2384_20815(pandiegoId)\n    Mobile.addMobileCreationCallback(pandiegoId, \"hideMonster\", pandiegoId)\nend\n\n-- [EVENT] Retrait du PNJ suiveur en revenant dans l'instance - affichage PNJ monde\n-- peut-être changer l'écoute sur une fin de ciné (et lancer une ciné à la fin du dialogue)\r\n-- attention, est annulé par les events utilisant un callback tant qu'on ne sort pas de l'instance.\r\nfunction event_2384_20817(pandiegoId)\n    local pandiegoId = toLong(pandiegoId)\n    local playerId = Context.getLeaderId()\n    \n    startCinematicContext(1.9, pandiegoId)\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\")\n    \n    ------------------------------\n    \n    -- Je vais rester ici en t'attendant.\n    invoke_custom(1000, 1, \"bubble\", pandiegoId, \"quest.saharach.tovak.1\")\n    \n    -- Reviens me chercher lorsque tu auras besoin de moi !\n    invoke_custom(4500, 1, \"bubble\", pandiegoId, \"quest.saharach.tovak.2\")\n    \n    invoke_custom(8500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Coucou\")\n    \n    ------------------------------\n    \n    invoke(9500, 1, \"skipCinematic\")\nend\n\n-- [EVENT] Cinématique - Le joueur passe le test de courage\n-- \nfunction event_2384_21391(pandiegoId)\n    \t\r\n    \t----------------------------- RECUPERATIONS DES INFOS JOUEUR --------------------------\r\n    \r\n    \tlocal playerId = Context.getLeaderId()\r\n    \tlocal pandiego = toLong(pandiegoId)\r\n    \t----------------------------- INITIALISATION DES VARIABLES --------------------------\r\n    \r\n    \tlocal pandaOneId = createActor(120, 2388, 2384, 0, 8, 5, 6)\r\n    \tlocal joeId = createActor(30, 2384, 2387, 0, 8, 1, 6)\r\n    \tlocal lauraId  = createActor(117903814, 2382, 2385, 3, 8, 1, 6)\r\n    \tlocal kamoomilleId = createActor(121801221, 2384, 2386, 0, 8, 1, 4)\r\n    \tlocal donalangeloId = createActor(1300071, 2384, 2380, 3, 8, 1, 11)\r\n    \tlocal rayId = createActor(1300093, 2386, 2380, 3, 8, 3, 3)\r\n    \r\n    \t----------------------------- PERSONNALISATION DES PNJ --------------------------\r\n    \r\n    \tActor.equip(pandaOneId, \"51317890\", \"VETEMENTCUSTOM\")\r\n    \tMobile.setPartColor(pandaOneId, \"Pupille\", 1.00, 0.61, 0.02, 1)\r\n    \tMobile.setPartColor(pandaOneId, \"Peau\", 0.63, 0.48, 0.38, 1)\r\n    \t\r\n    \tActor.equip(joeId, \"200300001\", \"CHEVEUXCUSTOM\")\r\n    \tActor.equip(joeId, \"210300004\", \"VETEMENTCUSTOM\")\r\n    \tMobile.setPartColor(joeId, \"Pupille\", 0.00, 0.00, 0.00, 1)\r\n    \tMobile.setPartColor(joeId, \"Peau\", 0.96, 0.72, 0.48, 1)\r\n    \tMobile.setPartColor(joeId, \"Cheveux\", 0.88, 0.88, 0.88, 1)\r\n    \r\n    \t----------------------------- DEBUT DE CINEMATIQUE -------------------------- \r\n    \r\n    \tstartCinematicContext(1.4, playerId, 210081)\r\n    \tUI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 21391)\r\n    \r\n    \t----------------------------- GROSSE RAVE PARTY -------------------------- \r\n    \t\r\n        invoke_custom(00001, 1, \"Mobile.setMobileVisible\", pandaOneId, false)\r\n        invoke_custom(00001, 1, \"Mobile.setMobileVisible\", joeId, false)\r\n        invoke_custom(00001, 1, \"Mobile.setMobileVisible\", lauraId, false)\r\n    \tinvoke_custom(00001, 1, \"Mobile.setMobileVisible\", kamoomilleId, false)\r\n        invoke_custom(00001, 1, \"Mobile.setMobileVisible\", donalangeloId, false)\r\n        invoke_custom(00001, 1, \"Mobile.setMobileVisible\", rayId, false)\r\n        \r\n        invoke_custom(01000, 1, \"UI.displayWideScreenBand\", true, 100, 300)\r\n        \r\n    \tinvoke_custom(02001, 1, \"Mobile.setMobilePosition\", playerId, 2385, 2385, 0)\r\n    \tinvoke_custom(02001, 1, \"Mobile.setMobileDirection\", playerId, 7)\r\n    \r\n        invoke_custom(04000, 1, \"UI.displayWideScreenBand\", true, 25, 300)\r\n    \r\n    \t\r\n    \tinvoke_custom(05000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Boire\")\r\n    \tinvoke_custom(05000, 1, \"Mobile.setMobileAnimation\", pandiego, \"AnimComp-2\")\r\n    \tinvoke_custom(07000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Presenter\")\r\n    \t\r\n     \t-- \"Et donc là je lui dis... \"Je savais où frapper... Car j'ai déjà vu cette scène. Je reviens du futur !\"\"\r\n    \tinvoke_custom(08000, 1, \"bubble\", playerId, \"quest.pandiego.party.01.01\")\r\n        invoke_custom(13000, 1, \"clearBubbles\", playerId)\r\n     \r\n      \t-- \"Mais non !\"\r\n        invoke_custom(13500, 1, \"Mobile.setMobileAnimation\", pandiego, \"AnimComp-3\")\r\n    \tinvoke_custom(13500, 1, \"bubble\", pandiego, \"quest.pandiego.party.01.02\")\r\n        invoke_custom(16000, 1, \"clearBubbles\", pandiego)\r\n     \r\n      \tinvoke_custom(16500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Boire\")\r\n    \tinvoke_custom(16500, 1, \"Mobile.setMobileAnimation\", pandiego, \"AnimComp-2\")\r\n    \tinvoke_custom(18500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Fievre\")\r\n     \r\n      \t-- \"On n'est pas assez imbibés...\"\r\n    \tinvoke_custom(18500, 1, \"bubble\", playerId, \"quest.pandiego.party.01.03\")\r\n        invoke_custom(21500, 1, \"clearBubbles\", playerId)\r\n        \r\n        -- \"En effet. C'est un problème. Heureusement, j'ai appelé des renforts.\"\r\n        invoke_custom(22000, 1, \"Mobile.setMobileAnimation\", pandiego, \"AnimComp-5\")\r\n    \tinvoke_custom(22000, 1, \"bubble\", pandiego, \"quest.pandiego.party.01.04\")\r\n        invoke_custom(27000, 1, \"clearBubbles\", pandiego)\r\n        \r\n    \tinvoke_custom(27500, 1, \"UI.displayWideScreenBand\", true, 100, 300)\r\n        \t\r\n        invoke_custom(29000, 1, \"Mobile.setMobileVisible\", pandaOneId, true)\r\n        invoke_custom(29000, 1, \"Mobile.setMobileVisible\", donalangeloId, true)\r\n        invoke_custom(29000, 1, \"Mobile.setMobileVisible\", rayId, true)\r\n        invoke_custom(29000, 1, \"Mobile.setMobilePosition\", playerId, 2385, 2380, 3)\r\n    \tinvoke_custom(29000, 1, \"Mobile.setMobileDirection\", playerId, 5)\r\n        invoke_custom(29000, 1, \"Mobile.setMobileAnimation\", pandaOneId, \"AnimEmote-EncouragerFan-Debut\")\r\n        \r\n        invoke_custom(30500, 1, \"UI.displayWideScreenBand\", true, 25, 300)\r\n        \r\n        -- \"Délire ! T'es venu aussi ?!\"\r\n        invoke_custom(31500, 1, \"bubble\", playerId, \"quest.pandiego.party.01.05\")\r\n        invoke_custom(31500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Help\")\r\n        invoke_custom(34500, 1, \"clearBubbles\", playerId)\r\n        \r\n       \tinvoke_custom(35500, 1, \"UI.displayWideScreenBand\", true, 100, 300)\r\n        \t\r\n        invoke_custom(36500, 1, \"Mobile.setMobileVisible\", lauraId, true)\r\n        invoke_custom(36500, 1, \"Mobile.setMobilePosition\", playerId, 2384, 2388, 0)\r\n    \tinvoke_custom(36500, 1, \"Mobile.setMobileDirection\", playerId, 3)\r\n        \r\n        invoke_custom(38500, 1, \"UI.displayWideScreenBand\", true, 25, 300)\r\n        \r\n        -- \"**Urgh... Pourquoi ça doit toujours finir comme ça chez Pandiego...\"\r\n        invoke_custom(39500, 1, \"bubble\", playerId, \"quest.pandiego.party.01.06\")\r\n        invoke_custom(39500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Fievre\")\r\n        invoke_custom(43500, 1, \"clearBubbles\", playerId)\r\n        \r\n       \tinvoke_custom(44500, 1, \"UI.displayWideScreenBand\", true, 100, 300)\r\n        \t\r\n        invoke_custom(46000, 1, \"Mobile.setMobileVisible\", joeId, true)\r\n        invoke_custom(46000, 1, \"Mobile.setMobileVisible\", kamoomilleId, true)\r\n        invoke_custom(46000, 1, \"Mobile.setMobilePosition\", playerId, 2385, 2385, 0)\r\n    \tinvoke_custom(46000, 1, \"Mobile.setMobileDirection\", playerId, 7)\r\n        \r\n        invoke_custom(47500, 1, \"UI.displayWideScreenBand\", true, 25, 300)\r\n        \r\n         -- \"Tout ce lait de bambou devrait t'imbiber pour... ton Dofus de l'eau, là...\"\r\n        invoke_custom(48500, 1, \"bubble\", pandiego, \"quest.pandiego.party.01.07\")\r\n        invoke_custom(22000, 1, \"Mobile.setMobileAnimation\", pandiego, \"AnimComp-4\") \r\n        invoke_custom(48500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Boire\")\r\n        invoke_custom(53500, 1, \"clearBubbles\", pandiego)\r\n        \r\n        -- \"Oh, je vois qu'on a de la suite dans les idées...\"\r\n        invoke_custom(54000, 1, \"bubble\", playerId, \"quest.pandiego.party.01.08\")\r\n        invoke_custom(54000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Fievre\")\r\n        invoke_custom(58000, 1, \"clearBubbles\", playerId)\r\n    \r\n        -- \"C'est pô bientôt fini c'raffût ! V'zallez voir qui c'est qu'a la meilleure descente d'lait ! Fichtre !\"\r\n        invoke_custom(58000, 1, \"bubble\", joeId, \"quest.pandiego.party.01.09\")\r\n        invoke_custom(58000, 1, \"Mobile.setMobileAnimation\", joeId, \"AnimEmote-Toux\")\r\n        invoke_custom(61000, 1, \"Mobile.setMobileAnimation\", joeId, \"AnimEmote-Rire\")\r\n        invoke_custom(62000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Fievre\")\r\n        invoke_custom(63000, 1, \"Mobile.setMobileAnimation\", joeId, \"AnimEmote-EncouragerFan-Debut\")\r\n        invoke_custom(64000, 1, \"clearBubbles\", joeId)\r\n        \r\n       \tinvoke_custom(68000, 1, \"UI.displayWideScreenBand\", true, 100, 300)\r\n    \t\r\n    \tinvoke_custom(70000, 1, \"UI.displayWideScreenBand\", true, 25, 300)\r\n    \tinvoke_custom(70100, 1, \"skipCinematic\", 21391)   \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","hideMonster","hidePart","showMonster","showPart","event_2384_20443","event_2384_20451","event_2384_20464","event_2384_20465","event_2384_20815","event_2384_20817","event_2384_21391"],"quest_calls":[],"dialogue_calls":[]},"scenario/2385.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\n-- les fonctions où on cache\r\nfunction hideMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, false)\r\nend\r\n\r\nfunction hidePart(monsterMobileId, partName)\r\n\tMobile.setPartVisible(monsterMobileId, false, partName)\r\nend\r\n\r\n-- les fonctions où on rend visible (à nouveau)\r\nfunction showMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, true)\r\nend\r\n\r\nfunction showPart(monsterMobileId, partName)\r\n\tMobile.setPartVisible(monsterMobileId, true, partName)\r\nend\n\n-- [INITIALISATION] Serveur\n-- \nfunction event_2385_20458()\n    \nend\n\n-- [EVENT] On lance un combat contre un Fantôme de Pandala (ACH 4673)\n-- \nfunction event_2385_20453()\n    \nend\n\n-- [EVENT] Combat Fantôme de Pandala - Capture complétée (ACH 4673)\n-- \nfunction event_2385_20454()\n    \nend\n\n-- [EVENT] Le joueur marche sur l'accès Nord (ACH 4672)\n-- \nfunction event_2385_20455()\n    \nend\n\n-- [EVENT] Le joueur marche sur l'accès Sud (ACH 4672)\n-- \nfunction event_2385_20456()\n    \nend\n\n-- [EVENT] Le joueur marche sur l'accès Ouest (ACH 4672)\n-- \nfunction event_2385_20457()\n    \nend\n\n-- [EVENT] Le joueur entre sur la map, on cache le fantôme\n-- \nfunction event_2385_20459(fantomeId)\n    Mobile.addMobileCreationCallback(fantomeId, \"hideMonster\", fantomeId)\nend\n\n-- [EVENT] Embuscade - Lancement du combat (ACH 4673)\n-- \nfunction event_2385_20460()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","hideMonster","hidePart","showMonster","showPart","event_2385_20458","event_2385_20453","event_2385_20454","event_2385_20455","event_2385_20456","event_2385_20457","event_2385_20459","event_2385_20460"],"quest_calls":[],"dialogue_calls":[]},"scenario/2387.lua":{"source":"\n\n-- [INIT] Variables\n-- \nfunction event_2387_20509()\n    \nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_2387_20507()\n    \nend\n\n-- [EVENT] Réceptacle Full - On rend le challenge disponible grâce à l'état de l'IE\n-- \nfunction event_2387_20506()\n    \nend\n\n-- [EVENT] Fin du challenge - On reset le Réceptacle\n-- \nfunction event_2387_20508()\n    \nend\n\n","functions":["event_2387_20509","event_2387_20507","event_2387_20506","event_2387_20508"],"quest_calls":[],"dialogue_calls":[]},"scenario/2388.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\n\n-- [INIT] Variables\n-- \nfunction event_2388_20513()\n    \nend\n\n-- [EVENT] Le joueur s'approche du donjon - Validation ACH 4696 OBJ 9739\n-- \nfunction event_2388_20514()\n    local playerId = Context.getLeaderId()\r\n    \r\n    BubbleText.showText(playerId, \"quest.brakmar.mercenary.chafer.01.03\", 0, 40, false)\nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_2388_20513","event_2388_20514"],"quest_calls":[],"dialogue_calls":[]},"scenario/2389.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\n\n-- [INIT] Variables\n-- \nfunction event_2389_20515()\n    \nend\n\n-- [EVENT] Le joueur s'approche du donjon - Validation ACH 4697 OBJ 9744\n-- \nfunction event_2389_20516()\n    local playerId = Context.getLeaderId()\r\n    \r\n    BubbleText.showText(playerId, \"quest.brakmar.mercenary.chafer.01.04\", 0, 40, false)\nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_2389_20515","event_2389_20516"],"quest_calls":[],"dialogue_calls":[]},"scenario/2390.lua":{"source":"function displayPath(room)\r\n\tlocal passerelle = toLong(room)\r\n\r\n\tif passerelle==1 then\r\n\t\tWorld.setPictoAlpha(13, 1, 7, 1, 1000)\r\n\t\tWorld.setPictoAlpha(36, 117, 6, 1, 1000)\r\n\telseif passerelle==2 then\r\n\t\tWorld.setPictoAlpha(13, 1, 7, 0, 1000)\r\n\t\tWorld.setPictoAlpha(36, 117, 6, 1, 1000)\r\n\telseif passerelle==3 then\r\n\t\tWorld.setPictoAlpha(13, 1, 7, 0, 1000)\r\n\t\tWorld.setPictoAlpha(36, 117, 6, 1, 1000)\r\n\telseif passerelle==4 then\r\n\t\tWorld.setPictoAlpha(13, 1, 7, 0, 1000)\r\n\t\tWorld.setPictoAlpha(36, 117, 6, 0, 1000)\r\n\telseif passerelle==-1 then\r\n\t\tWorld.setPictoAlpha(13, 1, 7, 0, 1000)\r\n\t\tWorld.setPictoAlpha(36, 117, 6, 0, 1000)\r\n\tend\r\nend\n\n-- [INIT] Variables Globales\n-- \nfunction event_2390_20631()\n    \nend\n\n-- [INIT] Inscription du joueur + Variables Locales\n-- \nfunction event_2390_20632(room)\n    displayPath(room)\nend\n\n-- USER_GROUP_KILLED - Salle 01\n-- \nfunction event_2390_20633(room)\n    displayPath(room)\nend\n\n-- USER_GROUP_KILLED - Salle 02\n-- \nfunction event_2390_20634(room)\n    displayPath(room)\nend\n\n-- USER_GROUP_KILLED - Salle 03\n-- \nfunction event_2390_20635(room)\n    displayPath(room)\nend\n\n-- USER_GROUP_KILLED - Salle 04 - BOSS\n-- \nfunction event_2390_20636()\n    \nend\n\n-- Déplace le joueur vers la salle suivante\n-- \nfunction event_2390_20637()\n    \nend\n\n-- [ARCHI] Apparition de l'Archimonstre\n-- \nfunction event_2390_23960()\n    \nend\n\n","functions":["displayPath","event_2390_20631","event_2390_20632","event_2390_20633","event_2390_20634","event_2390_20635","event_2390_20636","event_2390_20637","event_2390_23960"],"quest_calls":[],"dialogue_calls":[]},"scenario/2393.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\n\n-- [INIT] Variables\n-- \nfunction event_2393_20640()\n    \nend\n\n-- [EVENT] Cinématique - Le joueur dialogue avec Ruel\n-- \nfunction event_2393_20641(ruel)\n    local playerId = Context.getLeaderId()\r\n    local ruelId = toLong(ruel)\r\n    local pandiegoId = createActor(117905084, -23, 3, 0, 4, 5, 8)\r\n    \r\n    startCinematicContext(1.5, playerId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 20641)\r\n    \r\n    invoke_custom(00001, 1, \"Mobile.setMobileVisible\", pandiegoId, true)\r\n    invoke_custom(00001, 1, \"Mobile.setMobileDirection\", pandiegoId, 5)\r\n    \r\n    -- Hé, Ruel, c'est moi, Pandiego ! Tu te souviens de moi ?\r\n    invoke_custom(01000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Presenter\")\r\n    invoke_custom(02500, 1, \"bubble\", pandiegoId, \"quest.sadida.01.01\")\r\n    invoke_custom(07000, 1, \"clearBubbles\", pandiegoId)\r\n    \r\n    -- Euh... Je...\r\n    invoke_custom(07500, 1, \"bubble\", ruelId, \"quest.sadida.01.02\")\r\n    invoke_custom(09500, 1, \"clearBubbles\", ruelId)\r\n    \r\n    -- Ah oui ! C'est toi qui me dois des kamas !... non ?\r\n    invoke_custom(10000, 1, \"bubble\", ruelId, \"quest.sadida.01.03\")\r\n    invoke_custom(14500, 1, \"clearBubbles\", ruelId)\r\n    \r\n    -- ...\r\n    invoke_custom(14000, 1, \"bubble\", playerId, \"quest.sadida.01.04\")\r\n    invoke_custom(14000, 1, \"bubble\", pandiegoId, \"quest.sadida.01.04\")\r\n    \r\n    -- ... Désolé mon gaillard, ma mémoire me joue des tours.\r\n    invoke_custom(15000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Non\")\r\n    invoke_custom(16000, 1, \"bubble\", ruelId, \"quest.sadida.01.05\")\r\n    invoke_custom(20000, 1, \"clearBubbles\", ruelId)\r\n    \r\n    invoke_custom(21000, 1, \"Mobile.moveMobile\", pandiegoId, -18, 7, 0,  \"Mobile.setMobileDirection\", pandiegoId, 3)\r\n    invoke_custom(21000, 1, \"Mobile.moveMobile\", playerId, -18, 8, 0, \"Mobile.setMobileDirection\", playerId, 7)\r\n    \r\n    -- \"Il n'a pas l'air de te reconnaître.\"\r\n    invoke_custom(24000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(24000, 1, \"bubble\", playerId, \"quest.sadida.01.06\")\r\n    invoke_custom(28000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"C'était donc vrai. Je n'en reviens toujours pas... Je suis... Dans le passé !\"\r\n    invoke_custom(28500, 1, \"Mobile.setMobileAnimation\", pandiegoId, \"AnimComp-3\")\r\n    invoke_custom(28500, 1, \"bubble\", pandiegoId, \"quest.sadida.01.07\")\r\n    invoke_custom(34000, 1, \"clearBubbles\", pandiegoId)\r\n    \r\n    -- \"Reste avec moi, Pandiego. La situation pourrait vite dégénérer si tu décides de changer le cours du temps.\"\r\n    invoke_custom(34500, 1, \"Mobile.setMobileAnimation\", pandaFourId, \"AnimEmote-Calmer\")\r\n    invoke_custom(34500, 1, \"bubble\", playerId, \"quest.sadida.01.08\")\r\n    invoke_custom(42000, 1, \"clearBubbles\", playerId)\r\n    \r\n    --\"Nous avons besoin d'en savoir plus. Il faut qu'on retrouve ce Comte Harebourg...\"\r\n    invoke_custom(42500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(42500, 1, \"bubble\", playerId, \"quest.sadida.01.09\")\r\n    invoke_custom(49500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"C'est vrai, il faut absolument retrouver sa trace.\"\r\n    invoke_custom(50000, 1, \"Mobile.setMobileAnimation\", pandiegoId, \"AnimComp-4\")\r\n    invoke_custom(50000, 1, \"bubble\", pandiegoId, \"quest.sadida.01.10\")\r\n    invoke_custom(54000, 1, \"clearBubbles\", pandiegoId)\r\n    \r\n    -- \"Par contre, je te suivrai d'assez loin... Je viens du futur, et je n'ai pas envie de m'exposer de trop près.\"\r\n    invoke_custom(54500, 1, \"Mobile.setMobileAnimation\", pandiegoId, \"AnimComp-5\")\r\n    invoke_custom(54000, 1, \"bubble\", pandiegoId, \"quest.sadida.01.11\")\r\n    invoke_custom(61000, 1, \"clearBubbles\", pandiegoId)\r\n    \r\n    -- \"Merci Pandiego, j'apprécie ton aide.\"\r\n    invoke_custom(61500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Pouce\")\r\n    invoke_custom(61500, 1, \"bubble\", playerId, \"quest.sadida.01.12\")\r\n    invoke_custom(65500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Commençons par aller à Amakna, peut-être que quelqu'un aura entendu des rumeurs sur le Comte Harebourg.\"\r\n    invoke_custom(66000, 1, \"bubble\", playerId, \"quest.sadida.01.13\")\r\n    invoke_custom(74000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(74500, 1, \"skipCinematic\", 20641)\nend\n\n-- [EVENT] Fin de la cinématique - Validation ACH 4699 OBJ 9748\n-- \nfunction event_2393_20642()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_2393_20640","event_2393_20641","event_2393_20642"],"quest_calls":[],"dialogue_calls":[]},"scenario/2394.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\n\n-- [INIT] Variables\n-- \nfunction event_2394_20643()\n    \nend\n\n-- [EVENT] Cinématique - Le joueur dialogue avec Yugo\n-- \nfunction event_2394_20644(yugoId)\n    local playerId = Context.getLeaderId()\r\n    local yugoId = toLong(yugoId)\r\n    local pandiegoId = createActor(117905084, -3, -104, 30, 8, 3, 8)\r\n    \r\n    ----------------------------- PERSONNALISATION DES PNJ --------------------------\r\n    \r\n    startCinematicContext(1.5, playerId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 20644)\r\n    \r\n    invoke_custom(00001, 1, \"Mobile.setMobileVisible\", pandiegoId, true)\r\n    \r\n    -- \"Vois-tu, je suis à sa recherche. Est-ce que tu peux me dire de quoi vous avez parlé ?\"\r\n    invoke_custom(01000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Presenter\")\r\n    invoke_custom(01000, 1, \"bubble\", playerId, \"quest.sadida.02.01\")\r\n    invoke_custom(08000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Hmmm... Je vois tellement de gens passer à cette auberge, je pense que j'ai oublié !\"\r\n    invoke_custom(08500, 1, \"bubble\", yugoId, \"quest.sadida.02.02\")\r\n    invoke_custom(14500, 1, \"clearBubbles\", yugoId)\r\n    \r\n    -- \"Dans ce cas, appelle-moi si tu te rappelles de quelque chose.\"\r\n    invoke_custom(15000, 1, \"bubble\", playerId, \"quest.sadida.02.03\")\r\n    invoke_custom(15000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Coucou\")\r\n    invoke_custom(18500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"{(1*]?M'zelle:M'sieur} ! Vous avez l'air d'avoir beaucoup voyagé...\"\r\n    invoke_custom(19000, 1, \"bubble\", yugoId, \"quest.sadida.02.04\")\r\n    invoke_custom(22500, 1, \"clearBubbles\", yugoId)\r\n    \r\n    -- \"Evidemment ! J'ai découvert des contrées glaciales, des volcans en fusion, des jungles remplies de danger... J'ai même rencontré des princes et princesses !\"\r\n    invoke_custom(23000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Pouce\")\r\n    invoke_custom(23000, 1, \"bubble\", playerId, \"quest.sadida.02.05\")\r\n    invoke_custom(31000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Wouah ! Des fois, j'aimerais bien voyager aussi, mais Alibert dit que je suis trop petit...\"\r\n    invoke_custom(31000, 1, \"bubble\", yugoId, \"quest.sadida.02.06\")\r\n    invoke_custom(36000, 1, \"clearBubbles\", yugoId)\r\n    \r\n    -- \"J'aimerais bien rencontrer une princesse un jour !\"\r\n    invoke_custom(36500, 1, \"bubble\", yugoId, \"quest.sadida.02.07\")\r\n    invoke_custom(40000, 1, \"clearBubbles\", yugoId)\r\n    \r\n    -- \"Je suis sûr que tu en rencontreras une, et que tu la protègeras contre tous les dangers.\"\r\n    invoke_custom(40500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Rire\")\r\n    invoke_custom(40500, 1, \"bubble\", playerId, \"quest.sadida.02.08\")\r\n    invoke_custom(45500, 1, \"clearBubbles\", playerId)\r\n    \r\n    --\"Tu veux mon secret pour être un bon héros ? Défends à tout prix ce qui t'est cher !\"\r\n    invoke_custom(46000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Pouce\")\r\n    invoke_custom(46000, 1, \"bubble\", playerId, \"quest.sadida.02.09\")\r\n    invoke_custom(50500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Coucou\")\r\n    invoke_custom(51500, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(52000, 1, \"Mobile.moveMobile\", playerId, -3,-103, 30, \"Mobile.setMobileDirection\", playerId, 1)\r\n    \r\n    -- \"Difficile à croire que ce petit garçon deviendra le Yugo que j'ai connu...\"\r\n    invoke_custom(56000, 1, \"Mobile.setMobileAnimation\", pandiegoId, \"AnimComp-4\")\r\n    invoke_custom(56000, 1, \"bubble\", pandiegoId, \"quest.sadida.02.10\")\r\n    invoke_custom(61000, 1, \"clearBubbles\", pandiegoId)\r\n    \r\n    -- \"Ou plutôt, que je vais connaître ? Ça devient compliqué, ces histoires temporelles !\"\r\n    invoke_custom(61500, 1, \"Mobile.setMobileAnimation\", pandiegoId, \"AnimComp-5\")\r\n    invoke_custom(61500, 1, \"bubble\", pandiegoId, \"quest.sadida.02.11\")\r\n    invoke_custom(67000, 1, \"clearBubbles\", pandiegoId)\r\n    \r\n    -- \"Si tu veux mon avis, ça ne sera jamais un très, très grand combattant.\"\r\n    invoke_custom(67500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Non\")\r\n    invoke_custom(67500, 1, \"bubble\", playerId, \"quest.sadida.02.12\")\r\n    invoke_custom(71500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Je ne sens pas grand-chose de particulier chez lui.\"\r\n    invoke_custom(72500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Calmer\")\r\n    invoke_custom(72000, 1, \"bubble\", playerId, \"quest.sadida.02.13\")\r\n    invoke_custom(75000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Alibert nous a dit d'aller à Bonta, non ? Quand nous serons prêts, mettons le cap vers cette nation.\"\r\n    invoke_custom(75500, 1, \"Mobile.setMobileAnimation\", pandiegoId, \"AnimComp-5\")\r\n    invoke_custom(75500, 1, \"bubble\", pandiegoId, \"quest.sadida.02.14\")\r\n    invoke_custom(80500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Acquiescer\")\r\n    invoke_custom(82000, 1, \"clearBubbles\", pandiegoId)\r\n    \r\n    invoke_custom(82500, 1, \"skipCinematic\", 20644)\nend\n\n-- [EVENT] Fin de la cinématique - Validation ACH 4699 OBJ 9758\n-- \nfunction event_2394_20645()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_2394_20643","event_2394_20644","event_2394_20645"],"quest_calls":[],"dialogue_calls":[]},"scenario/2395.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\n\n-- [INIT] Variables\n-- \nfunction event_2395_20646()\n    \nend\n\n-- [EVENT] Cinématique - Le joueur dialogue avec Géror\n-- \nfunction event_2395_20655(gerorId, bontarienFiveId, bontarienSixId)\n    local playerId = Context.getLeaderId()\r\n    local pandiegoId = createActor(117905084, 2, -39, -50, 8, 1, 8)\r\n    local bontarienFiveId = toLong(bontarienFiveId)\r\n    local bontarienSixId = toLong(bontarienSixId)\r\n    \r\n    ----------------------------- CINEMATIQUE -----------------------------\r\n    \r\n    startCinematicContext(1.5, playerId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 20655)\r\n    \r\n    invoke_custom(00001, 1, \"Mobile.setMobileVisible\", bontarienFiveId, false)\r\n    invoke_custom(00001, 1, \"Mobile.setMobileVisible\", bontarienSixId, false)\r\n    invoke_custom(00001, 1, \"Mobile.setMobileVisible\", pandiegoId, true)\r\n    \r\n    invoke_custom(00500, 1, \"Mobile.moveMobile\", playerId, 3, -39, -50, \"Mobile.setMobileDirection\", playerId, 5)\r\n    \r\n    -- \"Alors ? Ça s'est bien passé ?\"\r\n    invoke_custom(04000, 1, \"bubble\", pandiegoId, \"quest.sadida.03.01\")\r\n    invoke_custom(07000, 1, \"clearBubbles\", pandiegoId)\r\n    \r\n    -- \"Géror accepte de me faire rencontrer un indic', mais seulement en échange d'un pot de vin.\r\n    invoke_custom(07500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Non\")\r\n    invoke_custom(07500, 1, \"bubble\", playerId, \"quest.sadida.03.02\")\r\n    invoke_custom(12000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Un pot de vin ? Mais... Quel genre de vin ?\"\r\n    invoke_custom(12500, 1, \"Mobile.setMobileAnimation\", pandiegoId, \"AnimComp-5\")\r\n    invoke_custom(12500, 1, \"bubble\", pandiegoId, \"quest.sadida.03.03\")\r\n    invoke_custom(16000, 1, \"clearBubbles\", pandiegoId)\r\n    \r\n    -- \"Aucune idée. Du vin rouge, je suppose.\"\r\n    invoke_custom(16500, 1, \"bubble\", playerId, \"quest.sadida.03.04\")\r\n    invoke_custom(20000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"C'est quand même spécifique, comme demande...\"\r\n    invoke_custom(20500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(20500, 1, \"bubble\", playerId, \"quest.sadida.03.05\")\r\n    invoke_custom(26000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Ouais. Cela dit, je connais un endroit sympa, sur l'Île aux moines.\"\r\n    invoke_custom(26500, 1, \"Mobile.setMobileAnimation\", pandiegoId, \"AnimComp-4\")\r\n    invoke_custom(26500, 1, \"bubble\", pandiegoId, \"quest.sadida.03.06\")\r\n    invoke_custom(32000, 1, \"clearBubbles\", pandiegoId)\r\n    \r\n    -- \"On peut sûrement récupérer un peu de vin là bas. Tu as un pot, sur toi ?\"\r\n    invoke_custom(32500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Pouce\")\r\n    invoke_custom(32500, 1, \"bubble\", playerId, \"quest.sadida.03.07\")\r\n    invoke_custom(38000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Toujours. Allons-y !\"\r\n    invoke_custom(38500, 1, \"Mobile.setMobileAnimation\", pandiegoId, \"AnimComp-2\")\r\n    invoke_custom(38500, 1, \"bubble\", pandiegoId, \"quest.sadida.03.08\")\r\n    invoke_custom(42000, 1, \"clearBubbles\", pandiegoId)\r\n    \r\n    invoke_custom(42500, 1, \"skipCinematic\", 20655)\nend\n\n-- [EVENT] Fin de la cinématique - Validation ACH 4700 OBJ 9754\n-- \nfunction event_2395_20656()\n    \nend\n\n-- [EVENT] Cinématique ministre 1 - Le joueur marche sur un position trigger\n-- \nfunction event_2395_20647(cineMinistre, bontarienOneId, bontarienTwoId, bontarienThreeId, bontarienFourId)\n    local playerId = Context.getLeaderId()\r\n    local pandiegoId = createActor(117905084, -39, -27, -50, 4, 3, 8)\r\n    \r\n    local bontarienOneId = toLong(bontarienOneId)\r\n    local bontarienTwoId = toLong(bontarienTwoId)\r\n    local bontarienThreeId = toLong(bontarienThreeId)\r\n    local bontarienFourId = toLong(bontarienFourId)\r\n    \r\n    local ministreId = createActor(30, -47, -17, -37, 4, 4, 6)\r\n    Actor.equip(ministreId, \"200300001\", \"CHEVEUXCUSTOM\")\r\n    Actor.equip(ministreId, \"210300004\", \"VETEMENTCUSTOM\")\r\n    Actor.equip(ministreId, \"1349921\", \"Chapeau\")\r\n    Actor.equip(ministreId, \"1329925\", \"Cape\", \"CapeBas\")\r\n    Mobile.setPartColor(ministreId, \"Pupille\", 0.00, 0.00, 0.00, 1)\r\n    Mobile.setPartColor(ministreId, \"Peau\", 0.96, 0.72, 0.48, 1)\r\n    Mobile.setPartColor(ministreId, \"Cheveux\", 0.92, 0.92, 0.92, 1)\r\n    \r\n    ----------------------------- CINEMATIQUE -----------------------------\r\n    \r\n    startCinematicContext(1.4, playerId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 20647)\r\n    \r\n    invoke_custom(00001, 1, \"Mobile.setMobileVisible\", bontarienOneId, false)\r\n    invoke_custom(00001, 1, \"Mobile.setMobileVisible\", bontarienTwoId, false)\r\n    invoke_custom(00001, 1, \"Mobile.setMobileVisible\", bontarienThreeId, false)\r\n    invoke_custom(00001, 1, \"Mobile.setMobileVisible\", bontarienFourId, false)\r\n    \r\n    invoke_custom(00001, 1, \"Mobile.moveMobile\", playerId, -46, -24, -37, \"Mobile.setMobileDirection\", playerId, 3)\r\n    invoke_custom(00001, 1, \"Mobile.moveMobile\", pandiegoId, -47, -23, -37, \"Mobile.setMobileDirection\", pandiegoId, 3)\r\n    invoke_custom(03500, 1, \"Mobile.moveMobile\", ministreId, -46, -21, -37, \"Mobile.setMobileDirection\", ministreId, 7)\r\n    \r\n    -- \"Alors ? Il parait que vous m'avez préparé un... petit quelque chose ?\"\r\n    invoke_custom(04500, 1, \"Mobile.setMobileAnimation\", ministreId, \"AnimEmote-Bailler\")\r\n    invoke_custom(04000, 1, \"bubble\", ministreId, \"quest.sadida.04.01\")\r\n    invoke_custom(09000, 1, \"clearBubbles\", ministreId)\r\n    \r\n    -- \"Pas si vite. On a le pot de vin, mais on veut des réponses d'abord.\"\r\n    invoke_custom(09500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Pointer\")\r\n    invoke_custom(09500, 1, \"bubble\", playerId, \"quest.sadida.04.02\")\r\n    invoke_custom(14000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Hmpf, les habitudes se perdent, ici... Peu importe.\"\r\n    invoke_custom(14500, 1, \"Mobile.setMobileAnimation\", ministreId, \"AnimEmote-Non\")\r\n    invoke_custom(14500, 1, \"bubble\", ministreId, \"quest.sadida.04.03\")\r\n    invoke_custom(19000, 1, \"clearBubbles\", ministreId)\r\n    \r\n    -- \"J'ai bien rencontré le Comte de Frigost. Je ne sais pas pourquoi ça vous intéresse, mais bon.\"\r\n    invoke_custom(20000, 1, \"bubble\", ministreId, \"quest.sadida.04.04\")\r\n    invoke_custom(28000, 1, \"clearBubbles\", ministreId)\r\n    \r\n    -- \"Harebourg ? Un petit impertinent de plus, si vous voulez mon avis.\"\r\n    invoke_custom(28500, 1, \"Mobile.setMobileAnimation\", ministreId, \"AnimEmote-Renifle\")\r\n    invoke_custom(28500, 1, \"bubble\", ministreId, \"quest.sadida.04.05\")\r\n    invoke_custom(33000, 1, \"clearBubbles\", ministreId)\r\n    \r\n    -- \"Figurez-vous qu'il voulait exploiter une partie du Fourré de Tonkult. Une question de \"sauver nos populations\", qu'il disait.\"\r\n    invoke_custom(33500, 1, \"Mobile.setMobileAnimation\", ministreId, \"AnimEmote-Rire\")\r\n    invoke_custom(33500, 1, \"bubble\", ministreId, \"quest.sadida.04.06\")\r\n    invoke_custom(38500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(42000, 1, \"clearBubbles\", ministreId)\r\n    \r\n    -- \"Je crois que toute cette neige lui est montée à la tête...\"\r\n    invoke_custom(42500, 1, \"bubble\", ministreId, \"quest.sadida.04.07\")\r\n    invoke_custom(47000, 1, \"clearBubbles\", ministreId)\r\n    \r\n    -- \"Les forêts de Bonta appartiennent à son peuple... Sous la loi Bontarienne, évidemment.\"\r\n    invoke_custom(47500, 1, \"bubble\", ministreId, \"quest.sadida.04.08\")\r\n    invoke_custom(53000, 1, \"clearBubbles\", ministreId)\r\n    \r\n    -- \"Je lui ai dit d'aller voir sur Brâkmar si j'y suis. Harebourg a pris la mouche et est parti.\"\r\n    invoke_custom(53500, 1, \"Mobile.setMobileAnimation\", ministreId, \"AnimEmote-Rire\")\r\n    invoke_custom(53500, 1, \"bubble\", ministreId, \"quest.sadida.04.09\")\r\n    invoke_custom(59000, 1, \"clearBubbles\", ministreId)\r\n    \r\n    -- \"On arrive déjà pas à vivre décemment avec juste les ressources de Bonta ! En parlant de ça, vous allez me le donner, ce pot de vin ?\"\r\n    invoke_custom(59500, 1, \"bubble\", ministreId, \"quest.sadida.04.10\")\r\n    invoke_custom(65000, 1, \"Mobile.setMobileAnimation\", ministreId, \"AnimEmote-Applaudir\")\r\n    invoke_custom(68000, 1, \"clearBubbles\", ministreId)\r\n    \r\n    -- \"Ça ne nous apprend pas grand chose, mais j'imagine que vous avez mérité ce pot de vin.\"\r\n    invoke_custom(68500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Calmer\")\r\n    invoke_custom(68500, 1, \"bubble\", playerId, \"quest.sadida.04.11\")\r\n    invoke_custom(74000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Qu'est-ce que... Vous vous fichez de moi ? C'est un... pot de... vin !\"\r\n    invoke_custom(74500, 1, \"Mobile.setMobileAnimation\", ministreId, \"AnimEmote-Effrayee\")\r\n    invoke_custom(74500, 1, \"bubble\", ministreId, \"quest.sadida.04.12\")\r\n    invoke_custom(77500, 1, \"Mobile.setMobileAnimation\", ministreId, \"AnimEmote-Colere\")\r\n    invoke_custom(79000, 1, \"clearBubbles\", ministreId)\r\n    \r\n    -- \"Pfff, vous m'avez bien eu. Je m'en souviendrai ! Ça m'apprendra à faire confiance à ce vieux débris de Géror !\"\r\n    invoke_custom(79500, 1, \"Mobile.setMobileAnimation\", ministreId, \"AnimEmote-Colere\")\r\n    invoke_custom(79500, 1, \"bubble\", ministreId, \"quest.sadida.04.13\")\r\n    invoke_custom(86500, 1, \"Mobile.moveMobile\", ministreId, -30, -27, -50, \"Mobile.setMobileDirection\", ministreId, 1)\r\n    invoke_custom(87000, 1, \"clearBubbles\", ministreId)\r\n    \r\n    -- \"Attendez !... Et il est parti.\"\r\n    invoke_custom(87000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Calmer\")\r\n    invoke_custom(87000, 1, \"bubble\", playerId, \"quest.sadida.04.14\")\r\n    invoke_custom(88000, 1, \"Mobile.setMobileDirection\", playerId, 7)\r\n    invoke_custom(88000, 1, \"Mobile.setMobileDirection\", pandiegoId, 1)\r\n    invoke_custom(90000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Alors ça, c'est le bouquet. J'ai pas compris une subtilité, visiblement.\"\r\n    invoke_custom(90500, 1, \"Mobile.setMobileAnimation\", pandiegoId, \"AnimComp-3\")\r\n    invoke_custom(90500, 1, \"bubble\", pandiegoId, \"quest.sadida.04.15\")\r\n    invoke_custom(95500, 1, \"clearBubbles\", pandiegoId)\r\n    \r\n    -- \"Qu'est-ce qu'on va bien pouvoir faire de ce pot de vin ?\"\r\n    invoke_custom(096000, 1, \"Mobile.setMobileDirection\", playerId, 5)\r\n    invoke_custom(096000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(096000, 1, \"bubble\", playerId, \"quest.sadida.04.16\")\r\n    invoke_custom(101000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Là-dessus, j'ai mon avis sur la question !\"\r\n    invoke_custom(101500, 1, \"Mobile.setMobileAnimation\", pandiegoId, \"AnimComp-5\")\r\n    invoke_custom(101500, 1, \"bubble\", pandiegoId, \"quest.sadida.04.17\")\r\n    invoke_custom(105500, 1, \"clearBubbles\", pandiegoId)\r\n    \r\n    -- \"Je vois ce que tu veux dire. Il faut bien fêter les informations qu'on a obtenues !\"\r\n    invoke_custom(106000, 1, \"Mobile.setMobileDirection\", playerId, 5)\r\n    invoke_custom(106000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Victoire\")\r\n    invoke_custom(106000, 1, \"bubble\", playerId, \"quest.sadida.04.18\")\r\n    invoke_custom(112000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(112500, 1, \"skipCinematic\", 20647)\nend\n\n-- [EVENT] Cinématique ministre 2 - Taverne\n-- \nfunction event_2395_20648(cineMinistre)\n    World.runOnFadeIn(\"trace\", \"FADE IN\")\r\n    World.runOnFadeOut(\"trace\", \"FADE OUT\")\r\n    Event.runOnInstanceLoaded(\"trace\", \"INSTANCE LOADED\")\r\n    \r\n    local playerId = Context.getLeaderId()\r\n    local pandiegoId = createActor(117905084, 2, -46, -34, 8, 3, 8)\r\n    \r\n    ----------------------------- DEBUT DE CINEMATIQUE --------------------------\r\n    \r\n    startCinematicContext(1.1, playerId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 20648)       \r\n    \r\n    invoke_custom(0500, 1, \"Mobile.setMobileDirection\", playerId, 7)\r\n    invoke_custom(1000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Boire\")\r\n    invoke_custom(1000, 1, \"Mobile.setMobileAnimation\", pandiegoId, \"AnimComp-2\")\r\n    invoke_custom(4000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Fievre\")\r\n    \r\n    ----------------------------- FIN DE CINEMATIQUE --------------------------\r\n    \r\n    invoke_custom(5500, 1, \"skipCinematic\", 20648)\nend\n\n-- [EVENT] Cinématique ministre 3 - Combat\n-- \nfunction event_2395_20649(cineMinistre, bontarienSevenId, bontarienEightId, bontarienNineId)\n    local playerId = Context.getLeaderId()\r\n    local fecaId = createActor(120, 57, -47, -50, 8, 1, 6)\r\n    local bucheronneId = createActor(117100858, 62, -49, -50, 8, 7, 6)\r\n    local bontarienSevenId = toLong(bontarienSevenId)\r\n    local bontarienEightId = toLong(bontarienEightId)\r\n    local bontarienNineId = toLong(bontarienNineId)\r\n    \r\n    ----------------------------- PERSONNALISATION DES PNJ --------------------------\r\n    \r\n    Actor.equip(fecaId, \"200100003\", \"CHEVEUXCUSTOM\")\r\n    Actor.equip(fecaId, \"210100001\", \"VETEMENTCUSTOM\")\r\n    Actor.equip(fecaId, \"51315268\", \"JambeHabit\", \"PiedHabit01\", \"PiedHabit02\", \"Cape\", \"CapeBas\", \"Chapeau\")\r\n    Mobile.setPartColor(fecaId, \"Pupille\", 0.00, 0.00, 0.00, 1)\r\n    Mobile.setPartColor(fecaId, \"Peau\", 0.96, 0.72, 0.48, 1)\r\n    Mobile.setPartColor(fecaId, \"Cheveux\", 0.88, 0.88, 0.88, 1)\r\n    \r\n    startCinematicContext(1.8, playerId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 20649)\r\n    \r\n    ----------------------------- CINEMATIQUE --------------------------\r\n    \r\n    invoke_custom(00001, 1, \"Mobile.setMobileVisible\", bontarienSevenId, false)\r\n    invoke_custom(00001, 1, \"Mobile.setMobileVisible\", bontarienEightId, false)\r\n    invoke_custom(00001, 1, \"Mobile.setMobileVisible\", bontarienNineId, false)\r\n    \r\n    invoke_custom(0001, 1, \"Mobile.setMobileVisible\", bucheronneId, false)\r\n    invoke_custom(1000, 1, \"Mobile.moveMobile\", playerId, 63, -49, -50, \"Mobile.setMobileDirection\", playerId, 7)\r\n    invoke_custom(3000, 1, \"Mobile.moveMobile\", fecaId, 63, -47, -50, \"Mobile.setMobileDirection\", fecaId, 7)\r\n    invoke_custom(3000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Vomis\")\r\n    invoke_custom(5000, 1, \"Mobile.moveMobile\", playerId, 63, -48, -50, \"Mobile.setMobileDirection\", playerId, 3)\r\n    invoke_custom(5500, 1, \"Mobile.setMobileAnimation\", fecaId, \"AnimEmote-Effrayee\")\r\n    invoke_custom(5500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Colere\")\r\n    invoke_custom(5500, 1, \"Camera.attachCameraToMobile\", fecaId)\r\n    invoke_custom(7000, 1, \"Mobile.moveMobile\", fecaId, 90, -47, -50, \"Mobile.setMobileDirection\", fecaId, 1)\r\n    \r\n    invoke_custom(10400, 1, \"Mobile.setMobileVisible\", bucheronneId, true)\r\n    invoke_custom(10450, 1, \"Mobile.setMobileAnimation\", bucheronneId, \"AnimComp08_Air_menacant_Boucle\")\r\n    invoke_custom(10500, 1, \"Camera.attachCameraToMobile\", playerId)\r\n    invoke_custom(10500, 1, \"Mobile.setMobileAnimation\", fecaId, \"AnimEmote-Rire\")\r\n    invoke_custom(12000, 1, \"Camera.attachCameraToMobile\", bucheronneId)\r\n    \r\n    ----------------------------- FIN DE CINEMATIQUE --------------------------\r\n    \r\n    invoke_custom(13000, 1, \"skipCinematic\", 20649)\nend\n\n-- [EVENT] Cinématique ministre 4 - Garde à vue\n-- \nfunction event_2395_20650(cineMinistre)\n    local playerId = Context.getLeaderId()\r\n    local pandiegoId = createActor(117905084, -29, -8, -50, 8, 3, 8)\r\n        \r\n    ----------------------------- DEBUT DE CINEMATIQUE -------------------------- \r\n        \r\n    startCinematicContext(1.5, playerId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 20650)\r\n        \r\n    invoke_custom(0100, 1, \"Mobile.setMobileDirection\", playerId, 5)\r\n    invoke_custom(1000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Supplie-Debut\")\r\n    invoke_custom(1000, 1, \"Mobile.moveMobile\", pandiegoId, -29, 5, -50, \"Mobile.setMobileDirection\", pandiegoId, 5)\r\n        \r\n    ----------------------------- FIN DE CINEMATIQUE --------------------------\r\n    invoke_custom(6000, 1, \"skipCinematic\", 20650)\nend\n\n-- [EVENT] Cinématique ministre 5 - Faire le point\n-- \nfunction event_2395_20651(cineMinistre)\n    local playerId = Context.getLeaderId()\r\n    local pandiegoId = createActor(117905084, 59, 39, -80, 4, 3, 8)\r\n    \r\n    ----------------------------- CINEMATIQUE -----------------------------\r\n    \r\n    startCinematicContext(1.4, playerId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 20651)\r\n    \r\n    -- \"Hum... Bon, reprenons les affaires.\"\r\n    invoke_custom(01000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Fievre\")\r\n    invoke_custom(02000, 1, \"bubble\", playerId, \"quest.sadida.04.19\")\r\n    invoke_custom(06000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(06000, 1, \"Mobile.setMobileDirection\", playerId, 7)\r\n    \r\n    -- \"Le Comte Harebourg semble vraiment à la recherche d'un territoire...\"\r\n    invoke_custom(06500, 1, \"Mobile.setMobileAnimation\", pandiegoId, \"AnimComp-4\")\r\n    invoke_custom(06500, 1, \"bubble\", pandiegoId, \"quest.sadida.04.20\")\r\n    invoke_custom(11000, 1, \"clearBubbles\", pandiegoId)\r\n    \r\n    -- \"J'ai encore du mal à comprendre pourquoi. Allons sur Brâkmar, je suis certain qu'ils auront entendu parler de lui !\"\r\n    invoke_custom(11500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Gratte\")\r\n    invoke_custom(11500, 1, \"bubble\", playerId, \"quest.sadida.04.21\")\r\n    invoke_custom(20000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(20500, 1, \"skipCinematic\", 20651)\nend\n\n-- [EVENT] Fin de la cinématique - Validation ACH 4700 OBJ 9756\n-- \nfunction event_2395_20654(cineMinistre)\n    \nend\n\n-- [EVENT] Le joueur rentre à nouveau sur Bonta après avoir pété sa cinématique\n-- \nfunction event_2395_20860()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_2395_20646","event_2395_20655","event_2395_20656","event_2395_20647","event_2395_20648","event_2395_20649","event_2395_20650","event_2395_20651","event_2395_20654","event_2395_20860"],"quest_calls":[],"dialogue_calls":[]},"scenario/2396.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\n-- les fonctions où on cache\r\nfunction hideMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, false)\r\nend\r\n\r\n-- les fonctions où on rend visible (à nouveau\r\nfunction showMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, true)\r\nend\r\n\r\n\n\n-- [INIT] Variables \n-- \nfunction event_2396_20658()\n    \nend\n\n-- [EVENT] Le joueur rentre dans l'instance - Pas dans le contexte\n-- \nfunction event_2396_20660(cnId, mimiId, chuchoId, boletId, tovakId, vernaId, chevalierId, pandiegoId, charlesId)\n    Mobile.addMobileCreationCallback(cnId, \"hideMonster\", cnId)\r\n    Mobile.addMobileCreationCallback(mimiId, \"hideMonster\", mimiId)\r\n    Mobile.addMobileCreationCallback(chuchoId, \"hideMonster\", chuchoId)\r\n    Mobile.addMobileCreationCallback(boletId, \"hideMonster\", boletId)\r\n    Mobile.addMobileCreationCallback(tovakId, \"hideMonster\", tovakId)\r\n    Mobile.addMobileCreationCallback(vernaId, \"hideMonster\", vernaId)\r\n    Mobile.addMobileCreationCallback(chevalierId, \"hideMonster\", chevalierId)\r\n    Mobile.addMobileCreationCallback(pandiegoId, \"hideMonster\", pandiegoId)\r\n    Mobile.addMobileCreationCallback(charlesId, \"hideMonster\", charlesId)\nend\n\n-- [EVENT] Le joueur rentre dans l'instance - Corbeau Noir\n-- \nfunction event_2396_20664(cnId)\n    Mobile.addMobileCreationCallback(cnId, \"hideMonster\", cnId)\nend\n\n-- [EVENT] Le joueur rentre dans l'instance - Mimi la Merveilleuse\n-- \nfunction event_2396_20665(mimiId)\n    Mobile.addMobileCreationCallback(mimiId, \"hideMonster\", mimiId)\nend\n\n-- [EVENT] Le joueur rentre dans l'instance - Chuchoconsul\n-- \nfunction event_2396_20666(chuchoId)\n    Mobile.addMobileCreationCallback(chuchoId, \"hideMonster\", chuchoId)\nend\n\n-- [EVENT] Le joueur rentre dans l'instance - Maître Bolet\n-- \nfunction event_2396_20667(boletId)\n    Mobile.addMobileCreationCallback(boletId, \"hideMonster\", boletId)\nend\n\n-- [EVENT] Le joueur rentre dans l'instance - Tovak\n-- \nfunction event_2396_20668(tovakId)\n    Mobile.addMobileCreationCallback(tovakId, \"hideMonster\", tovakId)\nend\n\n-- [EVENT] Le joueur rentre dans l'instance - Verna\n-- \nfunction event_2396_20669(vernaId)\n    Mobile.addMobileCreationCallback(vernaId, \"hideMonster\", vernaId)\nend\n\n-- [EVENT] Le joueur rentre dans l'instance - Chevalier d'Astrub\n-- \nfunction event_2396_20670(chevalierId)\n    Mobile.addMobileCreationCallback(chevalierId, \"hideMonster\", chevalierId)\nend\n\n-- [EVENT] Le joueur rentre dans l'instance - Dans le contexte (cache archiviste + inscription au scénario)\n-- \nfunction event_2396_20671(hibouId)\n    Mobile.addMobileCreationCallback(hibouId, \"hideMonster\", hibouId)\nend\n\n-- [EVENT] Le joueur parle à Charles-Aigri - Cinématique 0-1 allié\n-- \nfunction event_2396_20723(charlesId)\n    local playerId = Context.getLeaderId()\r\n    local charlesId = toLong(charlesId)\r\n    \r\n    startCinematicContext(1.8, charlesId)\r\n    \r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 20723)\r\n    \r\n    -- \"Vous n'avez pas ramené un seul allié ! Vous n'avez pas d'amis, ou quoi ? Je pensais que les aventuriers, ça faisait des quêtes !\"\r\n    invoke_custom(01500, 1, \"bubble\", charlesId, \"quest.sadida.06.01\")\r\n    invoke_custom(10000, 1, \"clearBubbles\", charlesId)\r\n    invoke_custom(10000, 1, \"Mobile.setMobileDirection\", playerId, 7)\r\n    invoke_custom(10000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Defaite\")\r\n    \r\n    -- \"Enfin bref, allons-y. Pas de quartiers !\"\r\n    invoke_custom(11000, 1, \"bubble\", charlesId, \"quest.sadida.06.04\")\r\n    invoke_custom(14000, 1, \"clearBubbles\", charlesId)\r\n    \r\n    invoke(14500, 1, \"skipCinematic\", 20723)\nend\n\n-- [EVENT] Le joueur parle à Charles-Aigri - Cinématique 2-4 alliés\n-- \nfunction event_2396_20724(charlesId)\n    local playerId = Context.getLeaderId()\r\n    local charlesId = toLong(charlesId)\r\n    \r\n    startCinematicContext(1.8, charlesId)\r\n    \r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 20724)\r\n    \r\n    -- \"Vous avez tenu votre engagement. Espérons que ça passe avec les personnes qui sont là.\"\r\n    invoke_custom(01500, 1, \"bubble\", charlesId, \"quest.sadida.06.02\")\r\n    invoke_custom(10000, 1, \"clearBubbles\", charlesId)\r\n    invoke_custom(10000, 1, \"Mobile.setMobileDirection\", playerId, 7)\r\n    invoke_custom(10000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Pouce\")\r\n    \r\n    -- \"Enfin bref, allons-y. Pas de quartiers !\"\r\n    invoke_custom(11000, 1, \"bubble\", charlesId, \"quest.sadida.06.04\")\r\n    invoke_custom(14000, 1, \"clearBubbles\", charlesId)\r\n    \r\n    invoke(14500, 1, \"skipCinematic\", 20724)\nend\n\n-- [EVENT] Le joueur parle à Charles-Aigri - Cinématique 5-6 alliés\n-- \nfunction event_2396_20725(charlesId)\n    local playerId = Context.getLeaderId()\r\n    local charlesId = toLong(charlesId)\r\n    \r\n    startCinematicContext(1.8, charlesId)\r\n    \r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 20725)\r\n    \r\n    -- \"Eh bien, vous en connaissez, du monde ! J'ai peut-être sous-estimé votre cercle de relations.\"\r\n    invoke_custom(01500, 1, \"bubble\", charlesId, \"quest.sadida.06.03\")\r\n    invoke_custom(10000, 1, \"clearBubbles\", charlesId)\r\n    invoke_custom(10000, 1, \"Mobile.setMobileDirection\", playerId, 7)\r\n    invoke_custom(10000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Rire\")\r\n    \r\n    -- \"Enfin bref, allons-y. Pas de quartiers !\"\r\n    invoke_custom(11000, 1, \"bubble\", charlesId, \"quest.sadida.06.04\")\r\n    invoke_custom(14000, 1, \"clearBubbles\", charlesId)\r\n    \r\n    invoke(14500, 1, \"skipCinematic\", 20725)\nend\n\n-- [EVENT] Fin de la cinématique - Le joueur est téléporté sur Brâkmar\n-- \nfunction event_2396_20726()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","hideMonster","showMonster","event_2396_20658","event_2396_20660","event_2396_20664","event_2396_20665","event_2396_20666","event_2396_20667","event_2396_20668","event_2396_20669","event_2396_20670","event_2396_20671","event_2396_20723","event_2396_20724","event_2396_20725","event_2396_20726"],"quest_calls":[],"dialogue_calls":[]},"scenario/2397.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_2397_20661()\n    \nend\n\n-- [EVENT] Cinématique - Le Comte Harebourg apparaît\n-- \nfunction event_2397_20662(charlesId, guardOneId, guardTwoId)\n    local playerId = Context.getLeaderId()\r\n    local charlesId = toLong(charlesId)\r\n    local guardOneId = toLong(guardOneId)\r\n    local guardTwoId = toLong(guardTwoId)\r\n    local guardThreeId = createActor(117904045, 0, 0, 0, 8, 1, 6)\r\n    local pandiegoId = createActor(117905084, 0, 2, 0, 4, 1, 8)\r\n    local harebourgId = createActor(104702383, 1, 0, 0, 8, 1, 9)\r\n    local apsId = -1436029481\r\n    local apsTwoId = -1436035820\r\n    local apsThreeId = -1436035821\r\n    \r\n    startCinematicContext(1.2, charlesId, 210080)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 20662)\r\n    \r\n    invoke_custom(00001, 1, \"Mobile.setMobileVisible\", harebourgId, false)\r\n    invoke_custom(00001, 1, \"Mobile.setMobileVisible\", guardThreeId, false)\r\n    \r\n    invoke_custom(01000, 1, \"Mobile.moveMobile\", playerId, 5, 2, 0,  \"Mobile.setMobileDirection\", playerId, 7)\r\n    \r\n    invoke_custom(02000, 1, \"Mobile.setMobileVisible\", harebourgId, true)\r\n    invoke_custom(02000, 1, \"Particle.addParticleSystem\", apsId, 1, 0, 0)\r\n    invoke_custom(02000, 1, \"Mobile.setMobileAnimation\", harebourgId, \"AnimMouvementTeleport-Fin\")\r\n    \r\n    -- \"Tic tac... Je crois qu'on parle de moi !\"\r\n    invoke_custom(02500, 1, \"bubble\", harebourgId, \"quest.sadida.05.01\")\r\n    invoke_custom(06000, 1, \"clearBubbles\", harebourgId)\r\n    \r\n    invoke_custom(06000, 1, \"Mobile.setMobileDirection\", playerId, 5)\r\n    \r\n    -- \"Harebourg !\"\r\n    invoke_custom(06500, 1, \"bubble\", playerId, \"quest.sadida.05.02\")\r\n    invoke_custom(06500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Effrayee\")\r\n    invoke_custom(06500, 1, \"bubble\", pandiegoId, \"quest.sadida.05.02\")\r\n    invoke_custom(06500, 1, \"Mobile.setMobileAnimation\", pandiegoId, \"AnimComp-3\")\r\n    invoke_custom(06500, 1, \"bubble\", charlesId, \"quest.sadida.05.02\")\r\n    invoke_custom(08000, 1, \"Mobile.setMobileDirection\", pandiegoId, 7)\r\n    \r\n    -- \"Hahahaha !\"\r\n    invoke_custom(10000, 1, \"bubble\", harebourgId, \"quest.sadida.05.03\")\r\n    invoke_custom(10000, 1, \"Mobile.setMobileAnimation\", harebourgId, \"AnimSort-Pendultimatum\")\r\n    invoke_custom(10000, 1, \"Particle.addParticleSystem\", apsTwoId, 1, 0, 0)\r\n    invoke_custom(10500, 1, \"Particle.addParticleSystem\", apsThreeId, 3, -2, 0)\r\n    invoke_custom(10500, 1, \"Particle.addParticleSystem\", apsThreeId, 7, -2, 0)\r\n    \r\n    invoke_custom(11500, 1, \"Mobile.setMobileAnimation\", guardOneId, \"AnimMort\")\r\n    invoke_custom(11500, 1, \"Mobile.setMobileAnimation\", guardTwoId, \"AnimMort\")\r\n    invoke_custom(12300, 1, \"Mobile.setMobileVisible\", guardOneId, false)\r\n    invoke_custom(12300, 1, \"Mobile.setMobileVisible\", guardTwoId, false)\r\n    \r\n    -- \"Vous n'avez de cesse de me mettre des bâtons dans les roues.\"\r\n    invoke_custom(13000, 1, \"bubble\", harebourgId, \"quest.sadida.05.04\")\r\n    invoke_custom(17000, 1, \"clearBubbles\", harebourgId)\r\n    \r\n    -- \"Vous refusez de comprendre... Mon plan est nécessaire.\"\r\n    invoke_custom(17500, 1, \"bubble\", harebourgId, \"quest.sadida.05.05\")\r\n    invoke_custom(21000, 1, \"clearBubbles\", harebourgId)\r\n    \r\n    -- \"Vous avez voulu vous jouer de moi, et vous allez en payer le prix.\"\r\n    invoke_custom(21500, 1, \"bubble\", harebourgId, \"quest.sadida.05.06\")\r\n    invoke_custom(25500, 1, \"clearBubbles\", harebourgId)\r\n    \r\n    -- \"Mon armée de Mékas optimisés va attaquer Brâkmar. Dans quelques heures, la ville sera mienne !\"\r\n    invoke_custom(26000, 1, \"bubble\", harebourgId, \"quest.sadida.05.07\")\r\n    invoke_custom(30000, 1, \"Mobile.setMobileAnimation\", harebourgId, \"AnimDisparition\")\r\n    invoke_custom(32000, 1, \"clearBubbles\", harebourgId)\r\n    \r\n    -- \"Attends ! ... On l'avait enfin trouvé, mais il est encore parti !\"\r\n    invoke_custom(31500, 1, \"bubble\", playerId, \"quest.sadida.05.08\")\r\n    invoke_custom(33000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Colere\")\r\n    invoke_custom(35000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"C'est pratique, cette technique de téléportation.\"\r\n    invoke_custom(35000, 1, \"Mobile.setMobileDirection\", playerId, 5)\r\n    invoke_custom(35500, 1, \"bubble\", pandiegoId, \"quest.sadida.05.09\")\r\n    invoke_custom(35500, 1, \"Mobile.setMobileAnimation\", pandiegoId, \"AnimComp-5\")\r\n    invoke_custom(39000, 1, \"clearBubbles\", pandiegoId)\r\n    \r\n    -- \"Il compte attaquer Brâkmar...\"\r\n    invoke_custom(39500, 1, \"bubble\", playerId, \"quest.sadida.05.10\")\r\n    invoke_custom(39500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(42500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Nous ne le laisserons pas faire. C'est le moment de lui montrer de quel bois on se chauffe !\"\r\n    invoke_custom(43000, 1, \"bubble\", playerId, \"quest.sadida.05.11\")\r\n    invoke_custom(50000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(51000, 1, \"Mobile.setMobileVisible\", guardThreeId, true)\r\n    \r\n    -- \"Messire Charles-Aigri ! De mystérieux portails sont en train de se former sur Brâkmar.\"\r\n    invoke_custom(51500, 1, \"bubble\", guardThreeId, \"quest.sadida.05.12\")\r\n    invoke_custom(57500, 1, \"clearBubbles\", guardThreeId)\r\n    \r\n    -- \"La garde ne pourra pas tous les contenir !\"\r\n    invoke_custom(58000, 1, \"bubble\", guardThreeId, \"quest.sadida.05.13\")\r\n    invoke_custom(62000, 1, \"clearBubbles\", guardThreeId)\r\n    \r\n    -- \"Nous n'avons que quelques heures pour nous organiser et trouver de l'aide...\"\r\n    invoke_custom(62500, 1, \"bubble\", pandiegoId, \"quest.sadida.05.14\")\r\n    invoke_custom(62500, 1, \"Mobile.setMobileAnimation\", pandiegoId, \"AnimComp-4\")\r\n    invoke_custom(69000, 1, \"clearBubbles\", pandiegoId)\r\n    \r\n    -- \"Je connais quelques personnes qui me doivent un service.\"\r\n    invoke_custom(69500, 1, \"bubble\", playerId, \"quest.sadida.05.15\")\r\n    invoke_custom(69500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Pouce\")\r\n    invoke_custom(74000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Si Brâkmar est menacée, alors comptez-moi dedans.\"\r\n    invoke_custom(74500, 1, \"bubble\", charlesId, \"quest.sadida.05.16\")\r\n    invoke_custom(79000, 1, \"clearBubbles\", charlesId)\r\n    \r\n    -- \"Retrouvons-nous au Quartier Général des gardes de Brâkmar !\"\r\n    invoke_custom(79500, 1, \"bubble\", charlesId, \"quest.sadida.05.17\")\r\n    invoke_custom(84000, 1, \"clearBubbles\", charlesId)\r\n    \r\n    invoke(84500, 1, \"skipCinematic\", 20662)\nend\n\n-- [EVENT] Fin de la cinématique - Validation ACH 4702 OBJ 9761\n-- \nfunction event_2397_20663()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_2397_20661","event_2397_20662","event_2397_20663"],"quest_calls":[],"dialogue_calls":[]},"scenario/2398.lua":{"source":"\n\n-- [INIT] Variables Globales\n-- \nfunction event_2398_20673()\n    \nend\n\n-- [INIT] Inscription du joueur + Variables Locales\n-- \nfunction event_2398_20674(room)\n    \nend\n\n-- USER_GROUP_KILLED - Salle 01\n-- \nfunction event_2398_20675(room)\n    \nend\n\n-- USER_GROUP_KILLED - Salle 02\n-- \nfunction event_2398_20676(room)\n    \nend\n\n-- USER_GROUP_KILLED - Salle 03\n-- \nfunction event_2398_20677(room)\n    \nend\n\n-- USER_GROUP_KILLED - Salle 04 - BOSS\n-- \nfunction event_2398_20678()\n    \nend\n\n-- Déplace le joueur vers la salle suivante\n-- \nfunction event_2398_20679()\n    \nend\n\n-- [ARCHI] Apparition de l'Archimonstre\n-- \nfunction event_2398_23961()\n    \nend\n\n","functions":["event_2398_20673","event_2398_20674","event_2398_20675","event_2398_20676","event_2398_20677","event_2398_20678","event_2398_20679","event_2398_23961"],"quest_calls":[],"dialogue_calls":[]},"scenario/2399.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\n\n-- [INITIALISATION] Serveur\n-- \nfunction event_2399_20680()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2399_20806()\n    \nend\n\n-- [EVENT] Combat - Lancement du combat Sylargh\n-- \nfunction event_2399_20681()\n    \nend\n\n-- [EVENT] Cinématique - Sylargh est vaincu\n-- \nfunction event_2399_20682(sylarghMdcId)\n    local playerId = Context.getLeaderId()\r\n    local sylarghId = createActor(150402354, 0, 120, 0, 8, 3, 9)\r\n    local sylarghMdcId = toLong(sylarghMdcId)\r\n    \r\n    startCinematicContext(1.2, playerId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 20682)\r\n    \r\n    -- Début cinématique\r\n    \r\n    invoke_custom(00001, 1, \"Mobile.setMobileVisible\", sylarghMdcId, false)\r\n    invoke_custom(00001, 1, \"Mobile.moveMobile\", playerId, 0, 122, 0, \"Mobile.setMobileDirection\", playerId, 7)\r\n    \r\n    -- \"Allez, ça suffit, Sylargh. Tu t'es battu vaillamment.\"\r\n    invoke_custom(03000, 1, \"bubble\", playerId, \"quest.sadida.07.01\")\r\n    invoke_custom(08000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Je ne peux pas perdre ! Je suis le seul à soutenir le Maître dans son projet... Tous les autres l'ont abandonné !\"\r\n    invoke_custom(08000, 1, \"bubble\", sylarghId, \"quest.sadida.07.02\")\r\n    invoke_custom(16000, 1, \"clearBubbles\", sylarghId)\r\n    \r\n    -- \"Réfléchis, Sylargh. Tu es un vrai génie de la mécanique. Imagine si tu mettais tes compétences au service du monde...\"\r\n    invoke_custom(16500, 1, \"bubble\", playerId, \"quest.sadida.07.03\")\r\n    invoke_custom(16500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Calmer\")\r\n    invoke_custom(25000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Mais c'est ce que je fais. Tu ne comprends pas...\"\r\n    invoke_custom(25500, 1, \"bubble\", sylarghId, \"quest.sadida.07.04\")\r\n    invoke_custom(30000, 1, \"clearBubbles\", sylarghId)\r\n    \r\n    -- \"Eh bien explique-moi. Quel est ce fameux plan du Comte Harebourg, qui nécessite de conquérir par la force plusieurs royaumes ?\"\r\n    invoke_custom(16500, 1, \"bubble\", playerId, \"quest.sadida.07.05\")\r\n    invoke_custom(16500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Presenter\")\r\n    invoke_custom(25000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Tu ne le comprendrais pas. Seul un vrai génie avec une vraie vision peut comprendre...!\"\r\n    invoke_custom(25500, 1, \"bubble\", sylarghId, \"quest.sadida.07.06\")\r\n    invoke_custom(32000, 1, \"clearBubbles\", sylarghId)\r\n    \r\n    -- \"Allons, on parle bien du génie tombé dans le panneau ? Tu te souviens, le coup du \"hé, je suis votre pote, révèle-moi tout ton plan\"...\"\r\n    invoke_custom(32500, 1, \"bubble\", playerId, \"quest.sadida.07.07\")\r\n    invoke_custom(32500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Rire\")\r\n    invoke_custom(41000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Grrr...\"\r\n    invoke_custom(41500, 1, \"bubble\", sylarghId, \"quest.sadida.07.08\")\r\n    invoke_custom(43000, 1, \"clearBubbles\", sylarghId)\r\n    \r\n    -- \"Allez, dis-moi où il se trouve. Cette plaisanterie a assez duré comme ça.\"\r\n    invoke_custom(43500, 1, \"bubble\", playerId, \"quest.sadida.07.09\")\r\n    invoke_custom(43500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Non\")\r\n    invoke_custom(49000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"... Je ne sais pas exactement. Je crois qu'il est dans une Dimension Divine.\"\r\n    invoke_custom(51000, 1, \"bubble\", sylarghId, \"quest.sadida.07.10\")\r\n    invoke_custom(56000, 1, \"clearBubbles\", sylarghId)\r\n    \r\n    -- \"**Il est sûrement quelque part dans la Dimension Xélor...\"\r\n    invoke_custom(56500, 1, \"bubble\", playerId, \"quest.sadida.07.11\")\r\n    invoke_custom(56500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmoteMarket-HausseEpaules\")\r\n    invoke_custom(62000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Merci Sylargh. Tu viens de rendre service au Monde des Douze.\"\r\n    invoke_custom(62500, 1, \"bubble\", playerId, \"quest.sadida.07.12\")\r\n    invoke_custom(62500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Pouce\")\r\n    invoke_custom(67000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"**Je ferais mieux de trouver un moyen de désactiver ces Mékas scieurs...\"\r\n    invoke_custom(67500, 1, \"bubble\", playerId, \"quest.sadida.07.13\")\r\n    invoke_custom(67500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(73000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"**Et tout dire au Roi Sadida.\"\r\n    invoke_custom(73500, 1, \"bubble\", playerId, \"quest.sadida.07.14\")\r\n    invoke_custom(77000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(77500, 1, \"skipCinematic\", 20682)\nend\n\n-- [EVENT] Fin de combat - on masque l'UI de victoire\n-- \nfunction event_2399_20792()\n    local dialogName = \"fightResultDialog\"\r\n    \r\n    if (UI.isDialogLoaded(dialogName)) then \r\n        \tUI.unloadDialog(dialogName)\r\n     else\r\n     \tUI.addDialogLoadedListener(dialogName, \"UI.unloadDialog\", dialogName)\r\n     end\nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_2399_20680","event_2399_20806","event_2399_20681","event_2399_20682","event_2399_20792"],"quest_calls":[],"dialogue_calls":[]},"scenario/2400.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\n-- les fonctions où on cache\r\nfunction hideMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, false)\r\nend\r\n\r\n-- les fonctions où on rend visible (à nouveau\r\nfunction showMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, true)\r\nend\n\n-- [INIT] Variables \n-- \nfunction event_2400_20732()\n    \nend\n\n-- [EVENT] Le joueur rentre dans l'instance et n'est pas dans le contexte\n-- \nfunction event_2400_20731(pandoraId, chadId)\n    Mobile.addMobileCreationCallback(pandoraId, \"hideMonster\", pandoraId)\r\n    Mobile.addMobileCreationCallback(chadId, \"hideMonster\", chadId)\nend\n\n-- [EVENT] Cinématique - Le joueur rentre dans l'instance et confronte le Comte Harebourg\n-- \nfunction event_2400_20688()\n    local playerId = Context.getLeaderId()\r\n    local harebourgId = createActor(104702383, -5, -9, 0, 8, 7, 9)\r\n    \r\n    startCinematicContext(1.2, playerId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 20688)\r\n    \r\n    -- Début cinématique\r\n    \r\n    invoke_custom(00001, 1, \"Mobile.setMobileVisible\", harebourgId, false)\r\n    invoke_custom(00001, 1, \"Mobile.setMobileMovementStyle\", playerId, \"WALK\", \"WALK\")\r\n    invoke_custom(00001, 1, \"Mobile.setCustomWalkStyle\", playerId, \"AnimMarche\", 600)\r\n    invoke_custom(02000, 1, \"Mobile.moveMobile\", playerId, -1, -3, 0, \"Mobile.setMobileDirection\", playerId, 5)\r\n    \r\n    -- \"Qu'est-ce que c'est que c'est endroit ?\"\r\n    invoke_custom(04000, 1, \"bubble\", playerId, \"quest.sadida.09.01\")\r\n    invoke_custom(08000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Quelqu'un observait le Monde des Douze.\"\r\n    invoke_custom(08500, 1, \"Mobile.moveMobile\", playerId, -5, -5, 0, \"Mobile.setMobileDirection\", playerId, 5)\r\n    invoke_custom(08500, 1, \"bubble\", playerId, \"quest.sadida.09.02\")\r\n    invoke_custom(13000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Qui a pris ces notes...?\"\r\n    invoke_custom(13500, 1, \"Mobile.moveMobile\", playerId, -5, 0, 0, \"Mobile.setMobileDirection\", playerId, 5)\r\n    invoke_custom(13500, 1, \"bubble\", playerId, \"quest.sadida.09.03\")\r\n    invoke_custom(18000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(20000, 1, \"Mobile.setMobileVisible\", harebourgId, true)\r\n    invoke_custom(20001, 1, \"Mobile.setMobileAnimation\", harebourgId, \"AnimMouvementTeleport-Fin\")\r\n    invoke_custom(20001, 1, \"Camera.attachCameraToMobile\", harebourgId)\r\n    \r\n    -- \"Moi-même. Qui d'autre ?\"\r\n    invoke_custom(20100, 1, \"bubble\", harebourgId, \"quest.sadida.09.04\")\r\n    invoke_custom(21000, 1, \"Mobile.setMobileDirection\", playerId, 7)\r\n    invoke_custom(23000, 1, \"clearBubbles\", harebourgId)\r\n    \r\n    -- \"J'ai passé quelques jours... années... siècles... ici. Je ne me souviens plus.\"\r\n    invoke_custom(23500, 1, \"bubble\", harebourgId, \"quest.sadida.09.05\")\r\n    invoke_custom(28000, 1, \"clearBubbles\", harebourgId)\r\n    \r\n    invoke_custom(28000, 1, \"Mobile.moveMobile\", playerId, -5, -5, 0, \"Mobile.setMobileDirection\", playerId, 7)\r\n    \r\n    -- \"Je dois reconnaître que tu es très tenace.\"\r\n    invoke_custom(28500, 1, \"bubble\", harebourgId, \"quest.sadida.09.06\")\r\n    invoke_custom(33000, 1, \"clearBubbles\", harebourgId)\r\n    \r\n    -- \"Voilà des années que tu es à ma poursuite.\"\r\n    invoke_custom(33500, 1, \"bubble\", harebourgId, \"quest.sadida.09.07\")\r\n    invoke_custom(38000, 1, \"clearBubbles\", harebourgId)\r\n    \r\n    -- \"Qu'est-ce que j'y peux ? Je ne me rends pas compte que le temps passe si vite !\"\r\n    invoke_custom(38500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmoteMarket-HausseEpaules\")\r\n    invoke_custom(38500, 1, \"bubble\", playerId, \"quest.sadida.09.08\")\r\n    invoke_custom(44000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"J'ai mis un terme aux agissements de Sylargh sur le Royaume Sadida.\"\r\n    invoke_custom(44500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Pointer\")\r\n    invoke_custom(44500, 1, \"bubble\", playerId, \"quest.sadida.09.09\")\r\n    invoke_custom(50000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Soit, soit. C'est sans importance : ces arbres m'auraient été inutiles de toute façon.\"\r\n    invoke_custom(50500, 1, \"bubble\", harebourgId, \"quest.sadida.09.10\")\r\n    invoke_custom(57000, 1, \"clearBubbles\", harebourgId)\r\n    \r\n    -- \"J'ai refait mes calculs... Si je veux sauver tout Frigost, alors c'est toute la forêt Sadida qu'il me faudrait.\"\r\n    invoke_custom(57500, 1, \"bubble\", harebourgId, \"quest.sadida.09.11\")\r\n    invoke_custom(65000, 1, \"clearBubbles\", harebourgId)\r\n    \r\n    -- \"Je ne comprends pas tes agissements, Harebourg.\"\r\n    invoke_custom(65500, 1, \"bubble\", playerId, \"quest.sadida.09.12\")\r\n    invoke_custom(70000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"T'allier avec des ordures comme Missiz Frizz ou Nileza, voler le Dofus Cawotte, essayer de détruire la Pandalousie...\"\r\n    invoke_custom(70500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Non\")\r\n    invoke_custom(70500, 1, \"bubble\", playerId, \"quest.sadida.09.13\")\r\n    invoke_custom(79000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Qu'est-ce que tu cherches à faire réellement ?\"\r\n    invoke_custom(79500, 1, \"bubble\", playerId, \"quest.sadida.09.14\")\r\n    invoke_custom(83000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"...\"\r\n    invoke_custom(83500, 1, \"Camera.attachCameraToMobile\", harebourgId)\r\n    invoke_custom(83500, 1, \"bubble\", harebourgId, \"quest.sadida.09.15\")\r\n    invoke_custom(85500, 1, \"clearBubbles\", harebourgId)\r\n    \r\n    -- \"J'en ai assez que tu te mettes en travers de mon chemin.\"\r\n    invoke_custom(86000, 1, \"Mobile.setMobileDirection\", harebourgId, 3)\r\n    invoke_custom(86000, 1, \"Camera.setZoomFactor\", 2.5)\r\n    invoke_custom(86000, 1, \"bubble\", harebourgId, \"quest.sadida.09.16\")\r\n    invoke_custom(91000, 1, \"clearBubbles\", harebourgId)\r\n    \r\n    -- \"Je vais te mettre à l'agonie, puis je te décrirai la révolution que j'envisage.\"\r\n    invoke_custom(091500, 1, \"bubble\", harebourgId, \"quest.sadida.09.17\")\r\n    invoke_custom(097000, 1, \"clearBubbles\", harebourgId)\r\n    \r\n    -- \"Tu mourras en sachant que tu as tout fait pour m'empêcher de sauver le Monde des Douze...\"\r\n    invoke_custom(097500, 1, \"bubble\", harebourgId, \"quest.sadida.09.18\")\r\n    invoke_custom(105000, 1, \"clearBubbles\", harebourgId)\r\n    \r\n    -- \"Hahahaha !\"\r\n    invoke_custom(105500, 1, \"Mobile.setMobileAnimation\", harebourgId, \"AnimSort-Pendultimatum\")\r\n    invoke_custom(105500, 1, \"bubble\", harebourgId, \"quest.sadida.09.19\")\r\n    invoke_custom(107000, 1, \"clearBubbles\", harebourgId)\r\n    \r\n    invoke_custom(107500, 1, \"skipCinematic\", 20688)\nend\n\n-- [EVENT] Fin de la Cinématique - Lancement du combat Harebourg\n-- \nfunction event_2400_20689()\n    \nend\n\n-- [EVENT] Combat de monstres - Début\n-- \nfunction event_2400_20722(local_fight_id)\n    \nend\n\n-- [EVENT] Cinématique - Le joueur bat le Comte Harebourg\n-- \nfunction event_2400_20733()\n    local playerId = Context.getLeaderId()\r\n    local harebourgId = createActor(104702383, 3, -9, 0, 8, 3, 9)\r\n    local pandoraId = createActor(163503405, 0, -1, 0, 4, 7, 6)\r\n    local chadId = createActor(163503107, 0, 0, 0, 4, 7, 6)\r\n    \r\n    startCinematicContext(1.4, playerId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 20733)\r\n    \r\n    invoke_custom(00001, 1, \"Mobile.setMobileVisible\", pandoraId, false)\r\n    invoke_custom(00001, 1, \"Mobile.setMobileVisible\", chadId, false)\r\n    invoke_custom(00500, 1, \"Mobile.moveMobile\", playerId, 3, -7, 0, \"Mobile.setMobileDirection\", playerId, 7)\r\n    \r\n    -- \"Vous êtes vaillant{[1*]?e:}, je vous l'accorde...\"\r\n    invoke_custom(02000, 1, \"bubble\", harebourgId, \"quest.sadida.10.01\")\r\n    invoke_custom(06000, 1, \"clearBubbles\", harebourgId)\r\n    \r\n    -- \"Je ne peux pas échouer ici ! Mon plan est trop important.\"\r\n    invoke_custom(06500, 1, \"bubble\", harebourgId, \"quest.sadida.10.02\")\r\n    invoke_custom(11500, 1, \"clearBubbles\", harebourgId)\r\n    \r\n    -- \"Important... Temps ! Hahaha !\"\r\n    invoke_custom(12000, 1, \"bubble\", harebourgId, \"quest.sadida.10.03\")\r\n    invoke_custom(14000, 1, \"Mobile.setMobileAnimation\", harebourgId, \"AnimDisparition\")\r\n    invoke_custom(15000, 1, \"clearBubbles\", harebourgId)\r\n    \r\n    -- \"Damnation ! Il est parti...\"\r\n    invoke_custom(15500, 1, \"bubble\", playerId, \"quest.sadida.10.04\")\r\n    invoke_custom(15500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Colere\")\r\n    invoke_custom(18000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(18001, 1, \"Mobile.setMobileVisible\", pandoraId, true)\r\n    invoke_custom(18001, 1, \"Mobile.setMobileVisible\", chadId, true)\r\n    \r\n    invoke_custom(18500, 1, \"Mobile.moveMobile\", pandoraId, 0, -9, 0, \"Mobile.setMobileDirection\", pandoraId, 1)\r\n    invoke_custom(18500, 1, \"Mobile.moveMobile\", chadId, 4, -7, 0, \"Mobile.setMobileDirection\", chadId, 5)\r\n    \r\n    -- \"Besoin d'un coup d'main ?\"\r\n    invoke_custom(19500, 1, \"bubble\", chadId, \"quest.sadida.10.05\")\r\n    invoke_custom(22000, 1, \"clearBubbles\", chadId)\r\n    \r\n    -- \"Il est parti par une sorte de portail... Mais en suivant sa signature spatio-temporelle, je peux retrouver ses coordonnées pour le suivre !\"\r\n    invoke_custom(22500, 1, \"bubble\", pandoraId, \"quest.sadida.10.06\")\r\n    invoke_custom(22500, 1, \"Mobile.setMobileAnimation\", pandoraId, \"AnimComp-Fouille\")\r\n    invoke_custom(25500, 1, \"Mobile.setMobileAnimation\", pandoraId, \"AnimComp-Reflexion\")\r\n    invoke_custom(30000, 1, \"clearBubbles\", pandoraId)\r\n    \r\n    -- \"Juste une minute...\"\r\n    invoke_custom(30500, 1, \"bubble\", pandoraId, \"quest.sadida.10.07\")\r\n    invoke_custom(30500, 1, \"Mobile.setMobileAnimation\", pandoraId, \"AnimComp-Activation\")\r\n    invoke_custom(33000, 1, \"clearBubbles\", pandoraId)\r\n    \r\n    -- \"Eh ben, on dirait qu'ça a marché.\"\r\n    invoke_custom(33500, 1, \"bubble\", chadId, \"quest.sadida.10.08\")\r\n    invoke_custom(36000, 1, \"clearBubbles\", chadId)\r\n    \r\n    -- \"Tu dois l'arrêter. Fonce !\"\r\n    invoke_custom(36500, 1, \"bubble\", pandoraId, \"quest.sadida.10.09\")\r\n    invoke_custom(40000, 1, \"clearBubbles\", pandoraId)\r\n    \r\n    invoke(40500, 1, \"skipCinematic\", 20733)\nend\n\n-- [EVENT] Le joueur rentre dans l'instance et a battu le Comte Harebourg I\n-- \nfunction event_2400_20730()\n    \nend\n\n-- [EVENT] Cinématique - Le joueur rentre dans l'instance et a battu le Comte Harebourg II\n-- \nfunction event_2400_20739()\n    local playerId = Context.getLeaderId()\r\n    local harebourgId = createActor(104702383, -4, -4, 0, 8, 7, 9)\r\n    local pandoraId = createActor(163503405, -6, -5, 0, 8, 1, 6)\r\n    local chadId = createActor(163503107, -6, -6, 0, 8, 1, 6)\r\n    \r\n    startCinematicContext(1.5, playerId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 20739)\r\n    \r\n    -- Début cinématique\r\n    \r\n    invoke_custom(01000, 1, \"Mobile.setMobileDirection\", playerId, 3)\r\n    \r\n    -- \"Savez-vous quel est cet endroit ?\"\r\n    invoke_custom(02000, 1, \"bubble\", harebourgId, \"quest.sadida.11.03\")\r\n    invoke_custom(06000, 1, \"clearBubbles\", harebourgId)\r\n    \r\n    invoke_custom(06000, 1, \"Mobile.setMobileAnimation\", pandoraId, \"AnimComp-Fouille\")\r\n    invoke_custom(06000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Non\")\r\n    \r\n    -- \"Nous sommes actuellement à une époque où le Chaos d'Ogrest n'a pas encore eu lieu.\"\r\n    invoke_custom(06500, 1, \"bubble\", harebourgId, \"quest.sadida.11.04\")\r\n    invoke_custom(12000, 1, \"clearBubbles\", harebourgId)\r\n    \r\n    -- \"Cet observatoire créé par Xélor permet de visualiser certains événements qui se sont déjà produits... Ou qui ne se sont pas encore produits.\"\r\n    invoke_custom(12500, 1, \"Mobile.setMobileDirection\", harebourgId, 5)\r\n    invoke_custom(12500, 1, \"bubble\", harebourgId, \"quest.sadida.11.05\")\r\n    invoke_custom(20000, 1, \"clearBubbles\", harebourgId)\r\n    \r\n    -- \"Pour commencer, comment as-tu eu vent de tout ça ? Et comment as tu réussi à aller dans la Dimension Xélor ?\"\r\n    invoke_custom(20500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Calmer\")\r\n    invoke_custom(20500, 1, \"bubble\", playerId, \"quest.sadida.11.06\")\r\n    invoke_custom(28500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"C'est car je suis le fils de Xélor. Mais c'est une longue histoire.\"\r\n    invoke_custom(31000, 1, \"Mobile.setMobileDirection\", harebourgId, 7)\r\n    invoke_custom(29000, 1, \"bubble\", harebourgId, \"quest.sadida.11.07\")\r\n    invoke_custom(34500, 1, \"clearBubbles\", harebourgId)\r\n    \r\n    -- \"(Psst ! Les Dieux peuvent avoir des enfants ?)\"\r\n    invoke_custom(34500, 1, \"Mobile.setMobileDirection\", chadId, 3)\r\n    invoke_custom(35000, 1, \"bubble\", chadId, \"quest.sadida.11.08\")\r\n    invoke_custom(38500, 1, \"clearBubbles\", chadId)\r\n    \r\n    -- \"(Attends, j'essaie d'écouter !)\"\r\n    invoke_custom(38500, 1, \"Mobile.setMobileDirection\", pandoraId, 7)\r\n    invoke_custom(39000, 1, \"bubble\", pandoraId, \"quest.sadida.11.09\")\r\n    invoke_custom(43000, 1, \"clearBubbles\", pandoraId)\r\n    \r\n    invoke_custom(43000, 1, \"Mobile.setMobileDirection\", pandoraId, 1)\r\n    invoke_custom(43000, 1, \"Mobile.setMobileDirection\", chadId, 1)\r\n    \r\n    -- \"Le problème avec cet observatoire, c'est que des anomalies temporelles commencent à être observées.\"\r\n    invoke_custom(43500, 1, \"bubble\", harebourgId, \"quest.sadida.11.10\")\r\n    invoke_custom(51000, 1, \"clearBubbles\", harebourgId)\r\n    \r\n    -- \"Xélor lui-même n'a aucune idée de pourquoi ni comment, mais des événements qui devraient pouvoir être observés... Ne peuvent soudain plus l'être.\"\r\n    invoke_custom(51500, 1, \"bubble\", harebourgId, \"quest.sadida.11.11\")\r\n    invoke_custom(61000, 1, \"clearBubbles\", harebourgId)\r\n    invoke_custom(60000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    \r\n    -- \"C'est comme si quelqu'un ou quelque chose avait enlevé des morceaux d'une frise chronologique.\"\r\n    invoke_custom(61500, 1, \"bubble\", harebourgId, \"quest.sadida.11.12\")\r\n    invoke_custom(69000, 1, \"clearBubbles\", harebourgId)\r\n    \r\n    -- \"Il est impossible de savoir ce qu'il se passe à certains moments...\"\r\n    invoke_custom(69500, 1, \"bubble\", harebourgId, \"quest.sadida.11.13\")\r\n    invoke_custom(74000, 1, \"clearBubbles\", harebourgId)\r\n    invoke_custom(70000, 1, \"Mobile.setMobileAnimation\", pandoraId, \"AnimComp-Reflexion\")\r\n    \r\n    -- \"Le Temps lui-même n'en conserve aucun souvenir !\"\r\n    invoke_custom(74500, 1, \"bubble\", harebourgId, \"quest.sadida.11.14\")\r\n    invoke_custom(78500, 1, \"clearBubbles\", harebourgId)\r\n    \r\n    -- \"Et paradoxalement, des répercussions sont bien visibles.\"\r\n    invoke_custom(79000, 1, \"bubble\", harebourgId, \"quest.sadida.11.15\")\r\n    invoke_custom(83000, 1, \"clearBubbles\", harebourgId)\r\n    \r\n    -- \"Je ne comprends pas...\"\r\n    invoke_custom(83500, 1, \"Mobile.setMobileAnimation\", pandoraId, \"AnimComp-Reflexion\")\r\n    invoke_custom(83500, 1, \"bubble\", pandoraId, \"quest.sadida.11.16\")\r\n    invoke_custom(86000, 1, \"clearBubbles\", pandoraId)\r\n    \r\n    -- \"Imagine un Chacha qui traverse une rue pour voler un Esturgeon à un marchand.\"\r\n    invoke_custom(86500, 1, \"Mobile.setMobileDirection\", harebourgId, 5)\r\n    invoke_custom(86500, 1, \"bubble\", harebourgId, \"quest.sadida.11.17\")\r\n    invoke_custom(92000, 1, \"clearBubbles\", harebourgId)\r\n    \r\n    -- \"Tout s'est passé et est vrai. Mais un beau jour, le Temps te dit que c'étaient en fait trois Esturgeons qui avaient disparu de l'étal du marchand.\"\r\n    invoke_custom(095000, 1, \"Mobile.setMobileAnimation\", pandoraId, \"AnimComp-Reflexion\")\r\n    invoke_custom(092500, 1, \"bubble\", harebourgId, \"quest.sadida.11.18\")\r\n    invoke_custom(101000, 1, \"clearBubbles\", harebourgId)\r\n    \r\n    -- \"Et on n'en sait pas vraiment plus à l'heure actuelle...\"\r\n    invoke_custom(101500, 1, \"bubble\", harebourgId, \"quest.sadida.11.19\")\r\n    invoke_custom(106000, 1, \"clearBubbles\", harebourgId)\r\n    \r\n    -- \"D'accord... Aucune idée de qui ou de quoi, ni même de comment. Et donc, pourquoi attaquer la Pandalousie ? Pourquoi attaquer le Royaume Sadida ?\"\r\n    invoke_custom(106500, 1, \"bubble\", playerId, \"quest.sadida.11.20\")\r\n    invoke_custom(106500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(110500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmoteMarket-HausseEpaules\")\r\n    invoke_custom(116000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"A cause du Monde.\"\r\n    invoke_custom(116500, 1, \"Mobile.setMobileDirection\", harebourgId, 7)\r\n    invoke_custom(116500, 1, \"bubble\", harebourgId, \"quest.sadida.11.21\")\r\n    invoke_custom(120000, 1, \"clearBubbles\", harebourgId)\r\n    \r\n    -- \"La montée des eaux et le Chaos d'Ogrest, on peut espérer s'en débarasser un jour. Peut-être aussi de ces anomalies temporelles.\"\r\n    invoke_custom(120500, 1, \"bubble\", harebourgId, \"quest.sadida.11.22\")\r\n    invoke_custom(128000, 1, \"clearBubbles\", harebourgId)\r\n    \r\n    -- \"Mais qui pourra sauver le Douzien de lui-même ? Tu as fait de nombreux voyages et tu les as vus...\"\r\n    invoke_custom(128500, 1, \"bubble\", harebourgId, \"quest.sadida.11.23\")\r\n    invoke_custom(134000, 1, \"clearBubbles\", harebourgId)\r\n    \r\n    -- \"La Pandalousie refuse de renoncer à sa production de Lait de Bambou, gère de manière catastrophique ses territoires.\"\r\n    invoke_custom(134500, 1, \"bubble\", harebourgId, \"quest.sadida.11.24\")\r\n    invoke_custom(140000, 1, \"clearBubbles\", harebourgId)\r\n    \r\n    -- \"La culture par brûlis, entre autres, menace les populations autochtones. Fléopards, Plantalas...\"\r\n    invoke_custom(140500, 1, \"bubble\", harebourgId, \"quest.sadida.11.25\")\r\n    invoke_custom(146000, 1, \"clearBubbles\", harebourgId)\r\n    \r\n    -- \"Amakna essaie d’augmenter sa productivité agricole à tout prix, au mépris des traditions.\"\r\n    invoke_custom(140500, 1, \"bubble\", harebourgId, \"quest.sadida.11.26\")\r\n    invoke_custom(146000, 1, \"clearBubbles\", harebourgId)\r\n    \r\n    -- \"La faune et la flore de la nation sont de plus en plus appauvries... Corrompues.\"\r\n    invoke_custom(146500, 1, \"bubble\", harebourgId, \"quest.sadida.11.27\")\r\n    invoke_custom(152000, 1, \"clearBubbles\", harebourgId)\r\n    \r\n    -- \"Bonta vit dans la surconsommation et va complètement épuiser ses ressources naturelles.\"\r\n    invoke_custom(152500, 1, \"bubble\", harebourgId, \"quest.sadida.11.28\")\r\n    invoke_custom(158000, 1, \"clearBubbles\", harebourgId)\r\n    \r\n    -- \"Imagine un instant si tout le monde vivait comme un Bontarien lambda ! Nous aurions besoin d'une dizaine de Mondes ! Ils finiront dans une misère totale.\"\r\n    invoke_custom(158500, 1, \"bubble\", harebourgId, \"quest.sadida.11.29\")\r\n    invoke_custom(168000, 1, \"clearBubbles\", harebourgId)\r\n    \r\n    -- \"Brâkmar dévoue tout à son entreprise, c’est un régime totalitaire où les gens se tuent au travail, pour enrichir Charles-Aigri qui possède tous les pouvoirs.\"\r\n    invoke_custom(168500, 1, \"bubble\", harebourgId, \"quest.sadida.11.30\")\r\n    invoke_custom(178000, 1, \"clearBubbles\", harebourgId)\r\n    \r\n    -- \"Dans un chaos général, tout le monde se rejette la faute les uns sur les autres, mais tout le monde demeure asservi.\"\r\n    invoke_custom(178500, 1, \"bubble\", harebourgId, \"quest.sadida.11.31\")\r\n    invoke_custom(184000, 1, \"clearBubbles\", harebourgId)\r\n    \r\n    -- \"J'imagine que tu n'as pas encore visité la vraie Sufokia. Leurs ingénieurs travaillent d'arrache-pied, et le Sire Comte Flex n'était qu'un avant-goût... Une armée de Steamers se prépare à la guerre.\"\r\n    invoke_custom(184500, 1, \"bubble\", harebourgId, \"quest.sadida.11.32\")\r\n    invoke_custom(195000, 1, \"clearBubbles\", harebourgId)\r\n    \r\n    -- \"Tout ceci m'a fait comprendre que les gens n'ont pas besoin d'Ogrest pour être menacés par l'effondrement.\"\r\n    invoke_custom(195500, 1, \"bubble\", harebourgId, \"quest.sadida.11.33\")\r\n    invoke_custom(202000, 1, \"clearBubbles\", harebourgId)\r\n    \r\n    -- \"C'est pourquoi je veux au moins sauver Frigost. Je suis en train d'étudier de multiples inventions susceptibles de sauver notre île.\"\r\n    invoke_custom(202500, 1, \"bubble\", harebourgId, \"quest.sadida.11.34\")\r\n    invoke_custom(210000, 1, \"clearBubbles\", harebourgId)\r\n    \r\n    -- \"Nous n’avons pas mérité de souffrir des erreurs des autres.\"\r\n    invoke_custom(210500, 1, \"bubble\", harebourgId, \"quest.sadida.11.35\")\r\n    invoke_custom(214500, 1, \"clearBubbles\", harebourgId)\r\n    \r\n    -- \"Comprends-tu enfin ? Je n'ai que le bien du peuple de Frigost à coeur. Ces pourris peuvent mourir, je m'en moque.\"\r\n    invoke_custom(215000, 1, \"bubble\", harebourgId, \"quest.sadida.11.36\")\r\n    invoke_custom(221000, 1, \"clearBubbles\", harebourgId)\r\n    \r\n    -- \"Tout ce que j'ai fait... a toujours été dicté par de bonnes intentions.\"\r\n    invoke_custom(221500, 1, \"bubble\", harebourgId, \"quest.sadida.11.37\")\r\n    invoke_custom(226500, 1, \"clearBubbles\", harebourgId)\r\n    \r\n    -- \"Mais j'ai besoin de puissance, d'informations, et de génie. Malheureusement, le temps manque... C'est pourquoi je suis passé à des actions plus radicales.\"\r\n    invoke_custom(227000, 1, \"bubble\", harebourgId, \"quest.sadida.11.38\")\r\n    invoke_custom(237500, 1, \"clearBubbles\", harebourgId)\r\n    \r\n    -- \"Toi et tes subordonnés avez provoqué la mort de tant de gens...\"\r\n    invoke_custom(238000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Non\")\r\n    invoke_custom(238000, 1, \"bubble\", playerId, \"quest.sadida.11.39\")\r\n    invoke_custom(242500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Mais tout le monde meurt un jour, n'est-il pas ?\"\r\n    invoke_custom(243000, 1, \"bubble\", harebourgId, \"quest.sadida.11.40\")\r\n    invoke_custom(246000, 1, \"clearBubbles\", harebourgId)\r\n    \r\n    -- \"Essaie de comprendre. Sans moi, le Monde des Douze n'a aucune chance...\"\r\n    invoke_custom(246500, 1, \"bubble\", harebourgId, \"quest.sadida.11.41\")\r\n    invoke_custom(251000, 1, \"clearBubbles\", harebourgId)\r\n    \r\n    -- \"Je préfère encore qu'on meure tous ensemble, que survivre à l'aide d'un de tes plans tordus.\"\r\n    invoke_custom(251500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Colere\")\r\n    invoke_custom(251500, 1, \"bubble\", playerId, \"quest.sadida.11.42\")\r\n    invoke_custom(257000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Tu n'es pas une mauvaise personne dans le fond, mais il te manque vraiment une case...\"\r\n    invoke_custom(257500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(257500, 1, \"bubble\", playerId, \"quest.sadida.11.43\")\r\n    invoke_custom(263500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Je refuse de croire à tout ce que tu m'as expliqué. Il y a beaucoup de bonnes personnes dans le Monde des Douze.\"\r\n    invoke_custom(263500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Calmer\")\r\n    invoke_custom(263500, 1, \"bubble\", playerId, \"quest.sadida.11.44\")\r\n    invoke_custom(270000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Malgré tout, je comprends mieux tes intentions maintenant.\"\r\n    invoke_custom(270500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Pouce\")\r\n    invoke_custom(270500, 1, \"bubble\", playerId, \"quest.sadida.11.45\")\r\n    invoke_custom(276000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Quel dommage que tu sois aussi atteint par la folie...\"\r\n    invoke_custom(276500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Non\")\r\n    invoke_custom(276500, 1, \"bubble\", playerId, \"quest.sadida.11.46\")\r\n    invoke_custom(281000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Nous aurions pu collaborer pour trouver de vraies solutions pérennes.\"\r\n    invoke_custom(276500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Non\")\r\n    invoke_custom(276500, 1, \"bubble\", playerId, \"quest.sadida.11.47\")\r\n    invoke_custom(281000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Hélas, nous sommes bien loin de pouvoir nous entendre.\"\r\n    invoke_custom(281500, 1, \"bubble\", playerId, \"quest.sadida.11.48\")\r\n    invoke_custom(286000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Nous allons te prouver que tu as tort.\"\r\n    invoke_custom(286500, 1, \"bubble\", pandoraId, \"quest.sadida.11.49\")\r\n    invoke_custom(290500, 1, \"clearBubbles\", pandoraId)\r\n    \r\n    -- \"Hahaha ! J'ai hâte de te voir essayer !\"\r\n    invoke_custom(291000, 1, \"bubble\", harebourgId, \"quest.sadida.11.50\")\r\n    invoke_custom(295000, 1, \"clearBubbles\", harebourgId)\r\n    \r\n    invoke_custom(295000, 1, \"Mobile.setMobileDirection\", harebourgId, 1)\r\n    invoke_custom(295100, 1, \"Mobile.setMobileAnimation\", harebourgId, \"AnimDisparition\")\r\n    invoke_custom(295500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Coucou\")\r\n    \r\n    -- \"J'ai rien pigé. Il était méchant ou gentil, au final, votre Comte machin ?\"\r\n    invoke_custom(298000, 1, \"bubble\", chadId, \"quest.sadida.11.51\")\r\n    invoke_custom(303000, 1, \"clearBubbles\", chadId)\r\n    \r\n    -- \"Aucune idée. Mais on a du pain sur la planche.\"\r\n    invoke_custom(303500, 1, \"Mobile.setMobileAnimation\", pandoraId, \"AnimComp-Reflexion\")\r\n    invoke_custom(303500, 1, \"bubble\", pandoraId, \"quest.sadida.11.52\")\r\n    invoke_custom(308000, 1, \"clearBubbles\", pandoraId)\r\n    \r\n    invoke(308000, 1, \"skipCinematic\", 20739)\nend\n\n-- [EVENT] Fin de la Cinématique - Validation ACH 4706 OBJ 9790\n-- \nfunction event_2400_20740()\n    \nend\n\n-- [EVENT] Fin de combat - on masque l'UI de victoire\n-- \nfunction event_2400_20791()\n    local dialogName = \"fightResultDialog\"\r\n    \r\n    if (UI.isDialogLoaded(dialogName)) then \r\n        \tUI.unloadDialog(dialogName)\r\n     else\r\n     \tUI.addDialogLoadedListener(dialogName, \"UI.unloadDialog\", dialogName)\r\n     end\nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","hideMonster","showMonster","event_2400_20732","event_2400_20731","event_2400_20688","event_2400_20689","event_2400_20722","event_2400_20733","event_2400_20730","event_2400_20739","event_2400_20740","event_2400_20791"],"quest_calls":[],"dialogue_calls":[]},"scenario/2401.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\n\n-- [INIT] Variables \n-- \nfunction event_2401_20741()\n    \nend\n\n-- [EVENT] Cinématique - Le joueur rentre dans l'instance et confronte le Comte Harebourg\n-- \nfunction event_2401_20734()\n    local playerId = Context.getLeaderId()\r\n    local harebourgId = createActor(104702383, 2, 1, 0, 8, 1, 9)\r\n    \r\n    startCinematicContext(1.5, playerId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 20734)\r\n    \r\n    -- Début cinématique\r\n    invoke_custom(02000, 1, \"Mobile.moveMobile\", playerId, -1, 1, 0, \"Mobile.setMobileDirection\", playerId, 1)\r\n    invoke_custom(02400, 1, \"Mobile.setMobileDirection\", harebourgId, 5)\r\n    \r\n    -- \"Comment... Comment as-tu fait pour me retrouver ?\"\r\n    invoke_custom(04000, 1, \"bubble\", harebourgId, \"quest.sadida.10.10\")\r\n    invoke_custom(08000, 1, \"clearBubbles\", harebourgId)\r\n    \r\n    -- \"Cette fois, je te tiens ! Tu ne m'échapperas pas !\"\r\n    invoke_custom(08500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Pointer\")\r\n    invoke_custom(08500, 1, \"bubble\", playerId, \"quest.sadida.10.11\")\r\n    invoke_custom(12500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Hahaha... Tu vas donc causer la fin du monde.\"\r\n    invoke_custom(13000, 1, \"bubble\", harebourgId, \"quest.sadida.10.12\")\r\n    invoke_custom(17000, 1, \"clearBubbles\", harebourgId)\r\n    \r\n    -- \"Tu pourrais être plus clair ?\"\r\n    invoke_custom(17500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Non\")\r\n    invoke_custom(17500, 1, \"bubble\", playerId, \"quest.sadida.10.13\")\r\n    invoke_custom(21000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Explique-moi comment attaquer la ville de Brâkmar, ou l'Île Wabbit, pourrait faire de toi quelqu'un qui sauve le monde...\"\r\n    invoke_custom(21500, 1, \"bubble\", playerId, \"quest.sadida.10.14\")\r\n    invoke_custom(30000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Je ne te dois pas d'explications !\"\r\n    invoke_custom(30500, 1, \"bubble\", harebourgId, \"quest.sadida.10.15\")\r\n    invoke_custom(34000, 1, \"clearBubbles\", harebourgId)\r\n    \r\n    -- \"Je suis à peu près sûr{[1*]?e:} que tu ne sais même plus ce que tu fais...\"\r\n    invoke_custom(34500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmoteMarket-HausseEpaules\")\r\n    invoke_custom(34500, 1, \"bubble\", playerId, \"quest.sadida.10.16\")\r\n    invoke_custom(39000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"J'en ai assez. Je tuerai toutes les personnes qui te sont chères !\"\r\n    invoke_custom(39500, 1, \"bubble\", harebourgId, \"quest.sadida.10.17\")\r\n    invoke_custom(44000, 1, \"clearBubbles\", harebourgId)\r\n    \r\n    invoke_custom(44500, 1, \"skipCinematic\", 20734)\nend\n\n-- [EVENT] Fin de la Cinématique - Lancement du combat Harebourg\n-- \nfunction event_2401_20735()\n    \nend\n\n-- [EVENT] Combat de monstres - Début\n-- \nfunction event_2401_20736(local_fight_id)\n    \nend\n\n-- [EVENT] Cinématique - Le joueur bat le Comte Harebourg\n-- \nfunction event_2401_20737()\n    local playerId = Context.getLeaderId()\r\n    local harebourgId = createActor(104702383, 2, 1, 0, 8, 5, 9)\r\n    \r\n    startCinematicContext(1.5, playerId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 20737)\r\n    \r\n    -- Début cinématique\r\n    invoke_custom(00500, 1, \"Mobile.moveMobile\", playerId, -1, 1, 0, \"Mobile.setMobileDirection\", playerId, 1)\r\n    \r\n    -- \"Hah... Hah...\"\r\n    invoke_custom(02000, 1, \"bubble\", harebourgId, \"quest.sadida.11.01\")\r\n    invoke_custom(04000, 1, \"clearBubbles\", harebourgId)\r\n    \r\n    -- \"Je crois bien que c'est la fin pour toi. Maintenant, tu vas nous raconter ton plan...\"\r\n    invoke_custom(04500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Pointer\")\r\n    invoke_custom(04500, 1, \"bubble\", playerId, \"quest.sadida.11.02\")\r\n    invoke_custom(11500, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(12000, 1, \"skipCinematic\", 20737)\nend\n\n-- [EVENT] Fin de la Cinématique - Téléportation dans l'Observatoire\n-- \nfunction event_2401_20738()\n    \nend\n\n-- [EVENT] Fin de combat - on masque l'UI de victoire\n-- \nfunction event_2401_20790()\n    local dialogName = \"fightResultDialog\"\r\n    \r\n    if (UI.isDialogLoaded(dialogName)) then \r\n        \tUI.unloadDialog(dialogName)\r\n     else\r\n     \tUI.addDialogLoadedListener(dialogName, \"UI.unloadDialog\", dialogName)\r\n     end\nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_2401_20741","event_2401_20734","event_2401_20735","event_2401_20736","event_2401_20737","event_2401_20738","event_2401_20790"],"quest_calls":[],"dialogue_calls":[]},"scenario/2402.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\n-- les fonctions où on cache\r\nfunction hideMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, false)\r\nend\r\n\r\n-- les fonctions où on rend visible (à nouveau\r\nfunction showMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, true)\r\nend\r\n\r\n\n\n-- [INIT] Variables \n-- \nfunction event_2402_20690()\n    \nend\n\n-- [EVENT] Le joueur rentre dans l'instance - On cache Pandora\n-- \nfunction event_2402_20691(pandoraId)\n    Mobile.addMobileCreationCallback(pandoraId, \"hideMonster\", pandoraId)\nend\n\n-- [EVENT] Le joueur rentre dans l'instance - On cache Chad\n-- \nfunction event_2402_20692(chadId)\n    Mobile.addMobileCreationCallback(chadId, \"hideMonster\", chadId)\nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","hideMonster","showMonster","event_2402_20690","event_2402_20691","event_2402_20692"],"quest_calls":[],"dialogue_calls":[]},"scenario/2403.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\n-- les fonctions où on cache\r\nfunction hideMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, false)\r\nend\r\n\r\n-- les fonctions où on rend visible (à nouveau\r\nfunction showMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, true)\r\nend\n\n-- [INIT] Variables \n-- \nfunction event_2403_20701()\n    \nend\n\n-- [EVENT] Cinématique Pandora 1 - Le joueur rentre dans l'instance\n-- \nfunction event_2403_20753(sramId)\n    local playerId = Context.getLeaderId()\r\n    local pandoraId = createActor(163503405, 0, -7, 0, 4, 3, 6)\r\n    local chadId = createActor(163503107, -8, 0, 0, 4, 1, 6)\r\n    local sramId = toLong(sramId)\r\n    \r\n    startCinematicContext(1.5, playerId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 20753)\r\n    \r\n    -- Début cinématique\r\n    invoke_custom(00001, 1, \"Mobile.setMobileVisible\", sramId, false)\r\n    \r\n    invoke_custom(02000, 1, \"Mobile.moveMobile\", playerId, -6, 0, 0, \"Mobile.setMobileDirection\", playerId, 5)\r\n    invoke_custom(02000, 1, \"Mobile.moveMobile\", pandoraId, -4, 0, 0, \"Mobile.setMobileDirection\", pandoraId, 5)\r\n    \r\n    -- \"C'est impossible... Tu étais là tout ce temps ?\"\r\n    invoke_custom(04000, 1, \"bubble\", playerId, \"quest.sadida.08.01\")\r\n    invoke_custom(08000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Ne bouge pas, je vais te libérer !\"\r\n    invoke_custom(08500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Pointer\")\r\n    invoke_custom(08500, 1, \"bubble\", playerId, \"quest.sadida.08.02\")\r\n    invoke_custom(12500, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(12500, 1, \"Mobile.moveMobile\", playerId, -5, -1, 0, \"Mobile.setMobileDirection\", playerId, 3)\r\n    \r\n    invoke_custom(13000, 1, \"Mobile.setMobilePosition\", chadId, -5, 0, 0)\r\n    invoke_custom(14000, 1, \"Mobile.setMobileDirection\", chadId, 7)\r\n    \r\n    -- \"Nous sommes enfin réunis. C'est fou !\"\r\n    invoke_custom(14000, 1, \"bubble\", playerId, \"quest.sadida.08.03\")\r\n    invoke_custom(14000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Victoire\")\r\n    invoke_custom(17000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"'Y vous aura fallu l'temps...\"\r\n    invoke_custom(17500, 1, \"bubble\", chadId, \"quest.sadida.08.04\")\r\n    invoke_custom(21000, 1, \"clearBubbles\", chadId)\r\n    \r\n    -- \"J'ai cru que je ne te reverrai jamais. Je suis désolé{[1*]?e:} d'avoir fait ce choix...\"\r\n    invoke_custom(21500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Non\")\r\n    invoke_custom(21500, 1, \"bubble\", playerId, \"quest.sadida.08.06\")\r\n    invoke_custom(28000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"C'est normal, {[1*]?ma p'tite:mon p'tit}. C'est c'que j'voulais. J'voulais vous protéger, toi et Pandora... J'étais préparé pour l'pire.\"\r\n    invoke_custom(28500, 1, \"bubble\", chadId, \"quest.sadida.08.07\")\r\n    invoke_custom(36000, 1, \"clearBubbles\", chadId)\r\n    \r\n    -- \"Par cont', faudra pas trop compter sur moi pour tout c'qui est affrontement, tout ça... J'suis un peu diminué.\"\r\n    invoke_custom(36500, 1, \"bubble\", chadId, \"quest.sadida.08.09\")\r\n    invoke_custom(44000, 1, \"clearBubbles\", chadId)\r\n    \r\n    invoke_custom(44000, 1, \"Camera.setMoveSpeedFactor\", 0.1)\r\n    invoke_custom(44000, 1, \"Camera.scrollTo\", 0, -5, 0)\r\n    \r\n    invoke_custom(45000, 1, \"Mobile.setMobileVisible\", sramId, true)\r\n    invoke_custom(45001, 1, \"Mobile.setMobileAnimation\", sramId, \"AnimApparition\")\r\n    \r\n    -- \"Vous ne pensiez quand même pas que ça allait être aussi simple ?\"\r\n    invoke_custom(48000, 1, \"bubble\", sramId, \"quest.sadida.08.11\")\r\n    invoke_custom(53000, 1, \"clearBubbles\", sramId)\r\n    \r\n    invoke_custom(53000, 1, \"Mobile.moveMobile\", playerId, 0, -1, 0, \"Mobile.setMobileDirection\", playerId, 7)\r\n    invoke_custom(53000, 1, \"Mobile.moveMobile\", chadId, -2, 0, 0, \"Mobile.setMobileDirection\", chadId, 7)\r\n    invoke_custom(53000, 1, \"Mobile.moveMobile\", pandoraId, 2, 0, 0, \"Mobile.setMobileDirection\", pandoraId, 7)\r\n    \r\n    -- \"Je n'ai jamais laissé partir un de mes prisonniers. Jamais !\"\r\n    invoke_custom(54000, 1, \"Mobile.setMobileAnimation\", sramId, \"AnimComp-Rire\")\r\n    invoke_custom(54000, 1, \"bubble\", sramId, \"quest.sadida.08.12\")\r\n    invoke_custom(58000, 1, \"clearBubbles\", sramId)\r\n    \r\n    -- \"Pauvres mortels... Vous allez découvrir la véritable terreur !\"\r\n    invoke_custom(58500, 1, \"Mobile.setMobileAnimation\", sramId, \"AnimComp-Menacer\")\r\n    invoke_custom(58500, 1, \"bubble\", sramId, \"quest.sadida.08.13\")\r\n    invoke_custom(62500, 1, \"clearBubbles\", sramId)\r\n    \r\n    -- \"Partez devant. Je vais le retenir et je vous rejoins après.\"\r\n    invoke_custom(62500, 1, \"Mobile.setMobileDirection\", playerId, 3)\r\n    invoke_custom(63000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Calmer\")\r\n    invoke_custom(63000, 1, \"bubble\", playerId, \"quest.sadida.08.14\")\r\n    invoke_custom(67000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Nous avons un compte à régler...\"\r\n    invoke_custom(67000, 1, \"Mobile.setMobileDirection\", playerId, 7)\r\n    invoke_custom(67500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Colere\")\r\n    invoke_custom(67500, 1, \"bubble\", playerId, \"quest.sadida.08.15\")\r\n    invoke_custom(70000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(70500, 1, \"skipCinematic\", 20753)\nend\n\n-- [EVENT] Cinématique Chad 1 - Le joueur rentre dans l'instance\n-- \nfunction event_2403_20754(sramId)\n    local playerId = Context.getLeaderId()\r\n    local chadId = createActor(163503107, 0, -7, 0, 4, 3, 6)\r\n    local pandoraId = createActor(163503405, -8, 0, 0, 4, 1, 6)\r\n    local sramId = toLong(sramId)\r\n    \r\n    startCinematicContext(1.5, playerId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 20754)\r\n    \r\n    -- Début cinématique\r\n    invoke_custom(00001, 1, \"Mobile.setMobileVisible\", sramId, false)\r\n    \r\n    invoke_custom(02000, 1, \"Mobile.moveMobile\", playerId, -6, 0, 0, \"Mobile.setMobileDirection\", playerId, 5)\r\n    invoke_custom(02000, 1, \"Mobile.moveMobile\", chadId, -4, 0, 0, \"Mobile.setMobileDirection\", chadId, 5)\r\n    \r\n    -- \"C'est impossible... Tu étais là tout ce temps ?\"\r\n    invoke_custom(04000, 1, \"bubble\", playerId, \"quest.sadida.08.01\")\r\n    invoke_custom(08000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Ne bouge pas, je vais te libérer !\"\r\n    invoke_custom(08500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Pointer\")\r\n    invoke_custom(08500, 1, \"bubble\", playerId, \"quest.sadida.08.02\")\r\n    invoke_custom(12500, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(12500, 1, \"Mobile.moveMobile\", playerId, -5, -1, 0, \"Mobile.setMobileDirection\", playerId, 3)\r\n    \r\n    invoke_custom(13000, 1, \"Mobile.setMobilePosition\", pandoraId, -5, 0, 0)\r\n    invoke_custom(14000, 1, \"Mobile.setMobileDirection\", pandoraId, 7)\r\n    \r\n    -- \"Nous sommes enfin réunis. C'est fou !\"\r\n    invoke_custom(14000, 1, \"bubble\", playerId, \"quest.sadida.08.03\")\r\n    invoke_custom(14000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Victoire\")\r\n    invoke_custom(17000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Oh, j'ai failli attendre...\"\r\n    invoke_custom(17500, 1, \"bubble\", pandoraId, \"quest.sadida.08.05\")\r\n    invoke_custom(21000, 1, \"clearBubbles\", pandoraId)\r\n    \r\n    -- \"J'ai cru que je ne te reverrai jamais. Je suis désolé{[1*]?e:} d'avoir fait ce choix...\"\r\n    invoke_custom(21500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Non\")\r\n    invoke_custom(21500, 1, \"bubble\", playerId, \"quest.sadida.08.06\")\r\n    invoke_custom(28000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- Il ne faut pas s'en faire pour ça. J'ai accepté ma mission en sachant que ça pouvait mal tourner, mais vous n'aviez rien à voir avec ça.\"\r\n    invoke_custom(28500, 1, \"bubble\", pandoraId, \"quest.sadida.08.08\")\r\n    invoke_custom(36000, 1, \"clearBubbles\", pandoraId)\r\n    \r\n    -- \"En revanche, mes capacités sont clairement diminuées. Je suis désolée, mais pour les combats, vous allez devoir faire sans moi...\"\r\n    invoke_custom(36500, 1, \"bubble\", pandoraId, \"quest.sadida.08.10\")\r\n    invoke_custom(44000, 1, \"clearBubbles\", pandoraId)\r\n    \r\n    invoke_custom(44000, 1, \"Camera.setMoveSpeedFactor\", 0.1)\r\n    invoke_custom(44000, 1, \"Camera.scrollTo\", 0, -5, 0)\r\n    \r\n    invoke_custom(45000, 1, \"Mobile.setMobileVisible\", sramId, true)\r\n    invoke_custom(45001, 1, \"Mobile.setMobileAnimation\", sramId, \"AnimApparition\")\r\n    \r\n    -- \"Vous ne pensiez quand même pas que ça allait être aussi simple ?\"\r\n    invoke_custom(48000, 1, \"bubble\", sramId, \"quest.sadida.08.11\")\r\n    invoke_custom(53000, 1, \"clearBubbles\", sramId)\r\n    \r\n    invoke_custom(53000, 1, \"Mobile.moveMobile\", playerId, 0, -1, 0, \"Mobile.setMobileDirection\", playerId, 7)\r\n    invoke_custom(53000, 1, \"Mobile.moveMobile\", chadId, -2, 0, 0, \"Mobile.setMobileDirection\", chadId, 7)\r\n    invoke_custom(53000, 1, \"Mobile.moveMobile\", pandoraId, 2, 0, 0, \"Mobile.setMobileDirection\", pandoraId, 7)\r\n    \r\n    -- \"Je n'ai jamais laissé partir un de mes prisonniers. Jamais !\"\r\n    invoke_custom(54000, 1, \"Mobile.setMobileAnimation\", sramId, \"AnimComp-Rire\")\r\n    invoke_custom(54000, 1, \"bubble\", sramId, \"quest.sadida.08.12\")\r\n    invoke_custom(58000, 1, \"clearBubbles\", sramId)\r\n    \r\n    -- \"Pauvres mortels... Vous allez découvrir la véritable terreur !\"\r\n    invoke_custom(58500, 1, \"Mobile.setMobileAnimation\", sramId, \"AnimComp-Menacer\")\r\n    invoke_custom(58500, 1, \"bubble\", sramId, \"quest.sadida.08.13\")\r\n    invoke_custom(62500, 1, \"clearBubbles\", sramId)\r\n    \r\n    -- \"Partez devant. Je vais le retenir et je vous rejoins après.\"\r\n    invoke_custom(62500, 1, \"Mobile.setMobileDirection\", playerId, 3)\r\n    invoke_custom(63000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Calmer\")\r\n    invoke_custom(63000, 1, \"bubble\", playerId, \"quest.sadida.08.14\")\r\n    invoke_custom(67000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Nous avons un compte à régler...\"\r\n    invoke_custom(67000, 1, \"Mobile.setMobileDirection\", playerId, 7)\r\n    invoke_custom(67500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Colere\")\r\n    invoke_custom(67500, 1, \"bubble\", playerId, \"quest.sadida.08.15\")\r\n    invoke_custom(70000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(70500, 1, \"skipCinematic\", 20754)\nend\n\n-- [EVENT] Fin de la Cinématique - Lancement du combat Eminence Grise\n-- \nfunction event_2403_20755()\n    \nend\n\n-- [EVENT] Combat de monstres - Début\n-- \nfunction event_2403_20756(local_fight_id)\n    \nend\n\n-- [EVENT] Cinématique - Le joueur bat l'Eminence Grise & Validation ACH 4704/4705\n-- \nfunction event_2403_20757(local_fight_id)\n    local playerId = Context.getLeaderId()\r\n    local sramId = createActor(163503109, -1, -4, 0, 8, 1, 8)\r\n    \r\n    Actor.equip(playerId, \"22319060\", \"Arme\")\r\n    \r\n    local apsFinish = 1012321\r\n    \r\n    function displayExtraDamage()\r\n    \tUI.displayFlyingText(1, 0.4, 0.1, \"lstw\", sramId, \"finish.move.damage\", 0, 55, -999999)\r\n    end\r\n    \r\n    startCinematicContext(1.5, playerId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 20757)\r\n    \r\n    -- Début cinématique\r\n    \r\n    invoke_custom(01000, 1, \"Mobile.moveMobile\", playerId, 0, -4, 0, \"Mobile.setMobileDirection\", playerId, 5)\r\n    \r\n    invoke_custom(03500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimStatique03-Debut-223\")\r\n    invoke_custom(05000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimStatique03-223\")\r\n    \r\n    invoke_custom(06100, 1, \"displayExtraDamage\")\r\n    invoke_custom(06100, 1, \"Particle.addParticleSystem\", apsFinish, -1, -4, 0)\r\n    \r\n    -- \"Argh !\"\r\n    invoke_custom(06500, 1, \"Mobile.setMobileAnimation\", sramId, \"AnimKO-Debut\")\r\n    invoke_custom(06500, 1, \"bubble\", sramId, \"quest.sadida.08.16\")\r\n    invoke_custom(08500, 1, \"clearBubbles\", sramId)\r\n    \r\n    -- \"**Il est affaibli ! Je peux m'évader...\"\r\n    invoke_custom(09000, 1, \"bubble\", playerId, \"quest.sadida.08.17\")\r\n    invoke_custom(13000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(13000, 1, \"Mobile.moveMobile\", playerId, 0, 0, 0, \"Mobile.setMobileDirection\", playerId, 7)\r\n    \r\n    invoke_custom(13500, 1, \"skipCinematic\", 20757)\nend\n\n-- [EVENT] Fin de la Cinématique - Lance ACH 4706\n-- \nfunction event_2403_20759()\n    \nend\n\n-- [EVENT] Fin de combat - on masque l'UI de victoire\n-- \nfunction event_2403_20789()\n    local dialogName = \"fightResultDialog\"\r\n    \r\n    if (UI.isDialogLoaded(dialogName)) then \r\n        \tUI.unloadDialog(dialogName)\r\n     else\r\n     \tUI.addDialogLoadedListener(dialogName, \"UI.unloadDialog\", dialogName)\r\n     end\nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","hideMonster","showMonster","event_2403_20701","event_2403_20753","event_2403_20754","event_2403_20755","event_2403_20756","event_2403_20757","displayExtraDamage","event_2403_20759","event_2403_20789"],"quest_calls":[],"dialogue_calls":[]},"scenario/2404.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\n-- les fonctions où on cache\r\nfunction hideMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, false)\r\nend\r\n\r\n-- les fonctions où on rend visible (à nouveau\r\nfunction showMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, true)\r\nend\n\n-- [INIT] Variables\n-- \nfunction event_2404_20704()\n    \nend\n\n-- [EVENT] Cinématique bataille 1 - ENTER_INSTANCE, chemin stade (Mimi)\n-- \nfunction event_2404_20707(pnjThreeId, pnjFourId)\n    local playerId = Context.getLeaderId()\r\n    Mobile.addMobileCreationCallback(playerId, \"hideMonster\", playerId)\r\n    \r\n    local mimiId = createActor(177804141, -58, -82, 0, 4, 1, 8)\r\n    local invocId = createActor(158103845, -51, -82, 0, 4, 3, 8)\r\n    local chevalierId = createActor(159302867, -56, -81, 0, 4, 1, 8)\r\n    \r\n    local pnjThreeId = toLong(pnjThreeId)\r\n    local pnjFourId = toLong(pnjFourId)\r\n    \r\n    local mekaOneId = createActor(150402350, -53, -81, 0, 4, 5, 6)\r\n    local mekaTwoId = createActor(150402352, -51, -81, 0, 4, 5, 6)\r\n    \r\n    ----------------------------- CINEMATIQUE -----------------------------\r\n    \r\n    clearCompasses()\r\n    startCinematicContext(1.4, playerId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 20707)\r\n    \r\n    invoke_custom(00001, 1, \"Mobile.setMobileVisible\", chevalierId, false)\r\n    invoke_custom(00001, 1, \"Mobile.setMobileVisible\", playerId, false)\r\n    invoke_custom(00001, 1, \"Mobile.setMobileVisible\", pnjThreeId, false)\r\n    invoke_custom(00001, 1, \"Mobile.setMobileVisible\", pnjFourId, false)\r\n    \r\n    invoke_custom(02500, 1, \"Mobile.moveMobile\", mekaOneId, -55, -81, -0, \"Mobile.setMobileDirection\", mekaOneId, 5)\r\n    invoke_custom(04500, 1, \"Mobile.setMobileVisible\", chevalierId, true)\r\n    invoke_custom(04500, 1, \"Mobile.setMobileAnimation\", chevalierId, \"AnimApparition\")\r\n    invoke_custom(06500, 1, \"Mobile.setMobileAnimation\", chevalierId, \"AnimSort-Taille\")\r\n    invoke_custom(07500, 1, \"Mobile.setMobileAnimation\", mekaOneId, \"AnimMort\")\r\n    \r\n    invoke_custom(08000, 1, \"Mobile.setMobileAnimation\", mimiId, \"AnimSort-Ocarina\")\r\n    invoke_custom(09500, 1, \"Mobile.setMobileAnimation\", invocId, \"AnimSort-Machouillage\")\r\n    invoke_custom(10000, 1, \"Mobile.setMobileAnimation\", mekaTwoId, \"AnimMort\")\r\n    \r\n    invoke_custom(11500, 1, \"Mobile.setMobileAnimation\", invocId, \"AnimSort-RugissementSpectral\")\r\n    invoke_custom(11500, 1, \"Mobile.setMobileAnimation\", mimiId, \"AnimDial-Joie\")\r\n    \r\n    invoke_custom(14000, 1, \"skipCinematic\", 20707)\nend\n\n-- [EVENT] Cinématique bataille 1 - ENTER_INSTANCE, chemin stade (sans Mimi)\n-- \nfunction event_2404_20713(pnjThreeId, pnjFourId)\n    local playerId = Context.getLeaderId()\r\n    Mobile.addMobileCreationCallback(playerId, \"hideMonster\", playerId)\r\n    \r\n    local brakGuardId = createActor(10, -56, -81, 0, 4, 1, 8)\r\n    local charlesGuardId = createActor(177704046, -51, -82, 0, 4, 3, 8)\r\n    \r\n    local pnjThreeId = toLong(pnjThreeId)\r\n    local pnjFourId = toLong(pnjFourId)\r\n    \r\n    local mekaOneId = createActor(150402350, -53, -81, 0, 4, 5, 6)\r\n    local mekaTwoId = createActor(150402352, -51, -81, 0, 4, 5, 6)\r\n    \r\n    Actor.equip(brakGuardId, \"1349910\", \"Chapeau\")\r\n    Actor.equip(brakGuardId, \"51317907\", \"JambeHabit\", \"PiedHabit01\", \"PiedHabit02\", \"Cape\", \"CapeBas\")\r\n    Actor.equip(brakGuardId, \"2239460\", \"Arme\")\r\n    \r\n    ----------------------------- CINEMATIQUE -----------------------------\r\n    \r\n    clearCompasses()\r\n    startCinematicContext(1.4, playerId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 20713)\r\n    \r\n    invoke_custom(00001, 1, \"Mobile.setMobileVisible\", playerId, false)\r\n    invoke_custom(00001, 1, \"Mobile.setMobileVisible\", pnjThreeId, false)\r\n    invoke_custom(00001, 1, \"Mobile.setMobileVisible\", pnjFourId, false)\r\n    \r\n    invoke_custom(00001, 1, \"Mobile.setMobileAnimation\", brakGuardId, \"AnimStatique03-Boucle-223\")\r\n    invoke_custom(04500, 1, \"Mobile.moveMobile\", mekaOneId, -55, -81, -0, \"Mobile.setMobileDirection\", mekaOneId, 5)\r\n    invoke_custom(05500, 1, \"Mobile.setMobileAnimation\", brakGuardId, \"AnimStatique03-223\")\r\n    invoke_custom(07500, 1, \"Mobile.setMobileAnimation\", mekaOneId, \"AnimMort\")\r\n    \r\n    invoke_custom(09500, 1, \"Mobile.setMobileAnimation\", charlesGuardId, \"AnimSort-Piochage\")\r\n    invoke_custom(10000, 1, \"Mobile.setMobileAnimation\", mekaTwoId, \"AnimMort\")\r\n    invoke_custom(11500, 1, \"Mobile.setMobileAnimation\", charlesGuardId, \"AnimSort-LuciolesFlash\")\r\n    \r\n    invoke_custom(14000, 1, \"skipCinematic\", 20713)\nend\n\n-- [EVENT] Cinématique bataille 2 - Îlot (chuchoteurs)\n-- \nfunction event_2404_20708(pnjOneId, pnjTwoId)\n    local playerId = Context.getLeaderId()\r\n    \r\n    local chuchoId = createActor(145102076, -67, -8, -60, 4, 7, 8)\r\n    local craqId = createActor(145102083, -69, -9, -60, 4, 1, 8)\r\n    local megaCraqId = createActor(145102084, -67, -13, -60, 4, 1, 8)\r\n    \r\n    local pnjOneId = toLong(pnjOneId)\r\n    local pnjTwoId = toLong(pnjTwoId)\r\n    \r\n    local mekaOneId = createActor(150402351, -67, -9, -60, 4, 3, 6)\r\n    local mekaTwoId = createActor(150402353, -66, -13, -60, 4, 5, 6)\r\n    \r\n    Mobile.setPartColor(chuchoId, \"Color_1\", 1.00, 0.0, 0.00, 1)\r\n    Mobile.setPartColor(chuchoId, \"Color_2\", 1.00, 1.0