n\n-- USER_GROUP_KILLED - Salle 03\n-- \nfunction event_2409_20766()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 04 - BOSS\n-- \nfunction event_2409_20767()\n    \nend\n\n-- Déplace le joueur vers la salle suivante\n-- \nfunction event_2409_20768()\n    \nend\n\n-- [EVENT] Le joueur examine la Stèle d'intervention\n-- \nfunction event_2409_20769(steleIntervention)\n    local steleIntervention = toLong(steleIntervention)\r\n    \r\n    if (steleIntervention == 0) then\r\n    rewardOneId = 27553\r\n    rewardTwoId = 27555\r\n    rewardThreeId = 27557\r\n    elseif (steleIntervention == 1) then\r\n    rewardOneId = 27551\r\n    rewardTwoId = 27556\r\n    rewardThreeId = 0\r\n    elseif (steleIntervention == 2) then\r\n    rewardOneId = 27554\r\n    rewardTwoId = 27550\r\n    rewardThreeId = 27552\r\n    else\r\n    rewardOneId = 0\r\n    rewardTwoId = 0\r\n    rewardThreeId = 0\r\n    end\r\n    \r\n    UI.openRewardsDialog(\"stele.intervention.description\")\r\n    if (steleIntervention == 1) then\r\n    UI.addReward(rewardOneId)\r\n    UI.addReward(rewardTwoId)\r\n    else\r\n    UI.addReward(rewardOneId)\r\n    UI.addReward(rewardTwoId)\r\n    UI.addReward(rewardThreeId)\r\n    end\r\n    \r\n    local stateInfoId = \"stele.intervention.harebourg.description\"\r\n    \r\n    updateSteleInfo(stateInfoId, steleIntervention, true)\nend\n\n-- [EVENT] Activation Stèle d'Intervention\n-- \nfunction event_2409_20770(steleIntervention)\n    local steleIntervention = toLong(steleIntervention)\r\n    \r\n    if (steleIntervention == 1) then\r\n    rewardOneId = 27553\r\n    rewardTwoId = 27555\r\n    rewardThreeId = 27557\r\n    elseif (steleIntervention == 2) then\r\n    rewardOneId = 27551\r\n    rewardTwoId = 27556\r\n    rewardThreeId = 0\r\n    elseif (steleIntervention == 3) then\r\n    rewardOneId = 27554\r\n    rewardTwoId = 27550\r\n    rewardThreeId = 27552\r\n    else\r\n    rewardOneId = 0\r\n    rewardTwoId = 0\r\n    rewardThreeId = 0\r\n    end\r\n    \r\n    UI.openRewardsDialog(\"stele.intervention.description\")\r\n    \r\n    if (steleIntervention == 2) then\r\n    UI.addReward(rewardOneId)\r\n    UI.addReward(rewardTwoId)\r\n    else\r\n    UI.addReward(rewardOneId)\r\n    UI.addReward(rewardTwoId)\r\n    UI.addReward(rewardThreeId)\r\n    end\r\n    \r\n    local stateInfoId = \"stele.intervention.harebourg.description\"\r\n    \r\n    updateSteleInfo(stateInfoId, steleIntervention, true)\nend\n\n-- [EVENT] Démarrage du combat - Pose des zones flag\n-- \nfunction event_2409_20772()\n    \nend\n\n-- [EVENT] Démarrage du combat - Initialisation des variables\n-- \nfunction event_2409_20785()\n    \nend\n\n-- [EVENT] Notification Etat téléfrag et décalage - Mise à jour UI infos de combats\n-- \nfunction event_2409_20784(steleIntervention, telefragPair, telefragImpair, shiftOne, shiftTwo, shiftThree)\n    updateFightInfo(steleIntervention, telefragPair, telefragImpair, shiftOne, shiftTwo, shiftThree, true)\nend\n\n-- [EVENT] Démarrage du combat - application état Harebourg\n-- \nfunction event_2409_20787()\n    \nend\n\n-- [EVENT] ZoneTrigger - Le joueur marche dans le vide\n-- \nfunction event_2409_20793()\n    \nend\n\n-- [EVENT] ZoneTrigger - Le joueur est TP\n-- \nfunction event_2409_20794()\n    \nend\n\n-- [EVENT] Combat lancé - Désactivation de la ZoneTrigger\n-- \nfunction event_2409_20795()\n    -- Ponts\r\n    World.setPictoAlpha(252, -272, 0, 1, 500)\r\n    World.setPictoAlpha(258, -272, 0, 1, 500)\r\n    World.setPictoAlpha(249, -269, 0, 1, 500)\r\n    World.setPictoAlpha(255, -269, 0, 1, 500)\r\n    World.setPictoAlpha(261, -269, 0, 1, 500)\r\n    World.setPictoAlpha(252, -266, 0, 1, 500)\r\n    World.setPictoAlpha(258, -266, 0, 1, 500)\r\n    World.setPictoAlpha(249, -263, 0, 1, 500)\r\n    World.setPictoAlpha(255, -263, 0, 1, 500)\r\n    World.setPictoAlpha(261, -263, 0, 1, 500)\r\n    World.setPictoAlpha(252, -260, 0, 1, 500)\r\n    World.setPictoAlpha(258, -260, 0, 1, 500)\r\n    \r\n    -- Nuages\r\n   