active les états stèles\n-- \nfunction event_2409_20813()\n    local bubble = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_EAST\", -75, -100, false, 10000, true, \"interactiveBubbleDialog4\")\r\n    \r\n    BubbleText.setText(bubble, \"stele.intervention.harebourg.no.drop\")\r\n    BubbleText.show(bubble)\nend\n\n-- [ARCHI] Apparition de l'Archimonstre\n-- \nfunction event_2409_24009()\n    \nend\n\n","functions":["closeFightInfo","onFightInfoClosed","closeSteleInfo","onSteleInfoClosed","updateSteleInfo","updateFightInfo","event_2409_20762","event_2409_20763","event_2409_20771","event_2409_20764","event_2409_20765","event_2409_20766","event_2409_20767","event_2409_20768","event_2409_20769","event_2409_20770","event_2409_20772","event_2409_20785","event_2409_20784","event_2409_20787","event_2409_20793","event_2409_20794","event_2409_20795","event_2409_20796","event_2409_20813","event_2409_24009"],"quest_calls":["UI.openRewardsDialog(\"stele.intervention.description\")\r","UI.openRewardsDialog(\"stele.intervention.description\")\r"],"dialogue_calls":[]},"scenario/2410.lua":{"source":"bubbleSteleInfoId = 0\r\nbubbleFightInfoId = 0\r\n\r\nfunction closeFightInfo()\r\n\tif (bubbleFightInfoId ~= nil  and bubbleFightInfoId ~= 0) then BubbleText.close(bubbleFightInfoId) end\r\nend\r\n\r\nfunction onFightInfoClosed()\r\n\tif (bubbleFightInfoId ~= nil  and bubbleFightInfoId ~= 0) then bubbleFightInfoId = 0 end\r\nend\r\n\r\n\r\nfunction closeSteleInfo()\r\n\tif (bubbleSteleInfoId ~= nil  and bubbleSteleInfoId ~= 0) then BubbleText.close(bubbleSteleInfoId) end\r\nend\r\n\r\nfunction onSteleInfoClosed()\r\n\tif (bubbleSteleInfoId ~= nil  and bubbleSteleInfoId ~= 0) then bubbleSteleInfoId = 0 end\r\nend\r\n\r\nfunction updateSteleInfo(stateInfoId, steleIntervention, forceDisplayUI)\r\n\r\n\tlocal steleIntervention = toLong(steleIntervention)\r\n\r\n\tif (bubbleSteleInfoId == 0) then\r\n\t\tbubbleSteleInfoId = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_WEST\", 0, -60, false, 2147483647, true, \"interactiveBubbleDialog5\", 30000, 25000, \"onSteleInfoClosed\")\r\n\tend\r\n\r\n\tBubbleText.setText(bubbleSteleInfoId, stateInfoId, steleIntervention)\r\n\t\r\n\tif (forceDisplayUI) then BubbleText.show(bubbleSteleInfoId) end\r\nend\r\n\r\nfunction updateFightInfo(steleIntervention, telefragPair, telefragImpair, shiftOne, shiftTwo, shiftThree, forceDisplayUI)\r\n\tlocal steleIntervention = toLong(steleIntervention)\r\n\tlocal telefragPair = toLong(telefragPair)\r\n\tlocal telefragImpair = toLong(telefragImpair)\r\n\tlocal shiftOne = toLong(shiftOne)\r\n\tlocal shiftTwo = toLong(shiftTwo)\r\n\tlocal shiftThree = toLong(shiftThree)\r\n\r\n\tif (bubbleFightInfoId == 0) then\r\n\t\tbubbleFightInfoId = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_WEST\", 0, -110, false, 2147483647, true, \"interactiveBubbleDialog5\", 30000, 25000, \"onFightInfoClosed\")\r\n\tend\r\n\r\n\tBubbleText.setText(bubbleFightInfoId, \"harebourg.fight.player.infos\", steleIntervention, telefragPair, telefragImpair, shiftOne, shiftTwo, shiftThree)\r\n\t\r\n\tif (forceDisplayUI) then BubbleText.show(bubbleFightInfoId) end\r\nend\n\n-- [INIT] Variables Globales\n-- \nfunction event_2410_20773()\n    \nend\n\n-- [INIT] Inscription du joueur + Variables Locales\n-- \nfunction event_2410_20774()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 01\n-- \nfunction event_2410_20775()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 02\n-- \nfunction event_2410_20776()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 03\n-- \nfunction event_2410_20777()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 04 - BOSS\n-- \nfunction event_2410_20778()\n    \nend\n\n-- Déplace le joueur vers la salle suivante\n-- \nfunction event_2410_20779()\n    \nend\n\n-- [EVENT] Le joueur examine la Stèle d'intervention\n-- \nfunction event_2410_20797(steleIntervention)\n    local steleIntervention = toLong(steleIntervention)\r\n    if (steleIntervention == 0) then\r\n    rewardOneId = 27433\r\n    rewardTwoId = 27437\r\n    rewardThreeId = 27439\r\n    elseif (steleIntervention == 1) then\r\n    rewardOneId = 27429\r\n    rewardTwoId = 27441\r\n    rewardThreeId = 0\r\n    elseif (steleIntervention == 2) then\r\n    rewardOneId = 27431\r\n    rewardTwoId = 27427\r\n    rewardThreeId = 27435\r\n    else\r\n    rewardOneId = 0\r\n    rewardTwoId = 0\r\n    rewardThreeId = 0\r\n    end\r\n    \r\n    UI.openRewardsDialog(\"stele.intervention.description\")\r\n    \r\n    if (steleIntervention == 1) then\r\n    UI.addReward(rewardOneId)\r\n    UI.addReward(rewardTwoId)\r\n    else\r\n    UI.addReward(rewardOneId)\r\n    UI.addReward(rewardTwoId)\r\n    UI.addReward(rewardThreeId)\r\n    end\r\n    \r\n    local stateInfoId = \"stele.intervention.harebourg.description\"\r\n    \r\n    updateSteleInfo(stateInfoId, steleIntervention, true)\nend\n\n-- [EVENT] Activation Stèle d'Intervention\n-- \nfunction event_2410_20798(steleIntervention)\n    local steleIntervention = toLong(steleIntervention)\r\n    if (steleIntervention == 1) then\r\n    rewardOneId = 27433\r\n    rewardTwoId = 27437\r\n    rewardThreeId = 27439\r\n    elseif (steleIntervention == 2) then\r\n    rewardOneId = 27429\r\n    rewardTwoId = 27441\r\n    rewardThreeId = 0\r\n    elseif (steleIntervention == 3) then\r\n    rewardOneId = 27431\r\n    rewardTwoId = 27427\r\n    rewardThreeId = 27435\r\n    else\r\n    rewardOneId = 0\r\n    rewardTwoId = 0\r\n    rewardThreeId = 0\r\n    end\r\n    \r\n    UI.openRewardsDialog(\"stele.intervention.description\")\r\n    \r\n    if (steleIntervention == 2) then\r\n    UI.addReward(rewardOneId)\r\n    UI.addReward(rewardTwoId)\r\n    else\r\n    UI.addReward(rewardOneId)\r\n    UI.addReward(rewardTwoId)\r\n    UI.addReward(rewardThreeId)\r\n    end\r\n    \r\n    local stateInfoId = \"stele.intervention.harebourg.description\"\r\n    \r\n    updateSteleInfo(stateInfoId, steleIntervention, true)\nend\n\n-- [EVENT] Démarrage du combat - Initialisation des variables\n-- \nfunction event_2410_20799()\n    \nend\n\n-- [EVENT] Notification Etat téléfrag et décalage - Mise à jour UI infos de combats\n-- \nfunction event_2410_20800(steleIntervention, telefragPair, telefragImpair, shiftOne, shiftTwo, shiftThree)\n    updateFightInfo(steleIntervention, telefragPair, telefragImpair, shiftOne, shiftTwo, shiftThree, true)\nend\n\n-- [EVENT] Démarrage du combat - application état Harebourg\n-- \nfunction event_2410_20801()\n    \nend\n\n-- [EVENT] DUNGEON_DIFFICULTY_CHANGED - On désactive les états stèles\n-- \nfunction event_2410_20814()\n    local bubble = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_EAST\", -75, -100, false, 10000, true, \"interactiveBubbleDialog4\")\r\n    \r\n    BubbleText.setText(bubble, \"stele.intervention.harebourg.no.drop\")\r\n    BubbleText.show(bubble)\nend\n\n-- [ARCHI] Apparition de l'Archimonstre\n-- \nfunction event_2410_24002()\n    \nend\n\n","functions":["closeFightInfo","onFightInfoClosed","closeSteleInfo","onSteleInfoClosed","updateSteleInfo","updateFightInfo","event_2410_20773","event_2410_20774","event_2410_20775","event_2410_20776","event_2410_20777","event_2410_20778","event_2410_20779","event_2410_20797","event_2410_20798","event_2410_20799","event_2410_20800","event_2410_20801","event_2410_20814","event_2410_24002"],"quest_calls":["UI.openRewardsDialog(\"stele.intervention.description\")\r","UI.openRewardsDialog(\"stele.intervention.description\")\r"],"dialogue_calls":[]},"scenario/2411.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\nbubbleFightInfoId = 0\r\n\r\nfunction closeFightInfo()\r\n\tif (bubbleFightInfoId ~= nil  and bubbleFightInfoId ~= 0) then BubbleText.close(bubbleFightInfoId) end\r\nend\r\n\r\nfunction onFightInfoClosed()\r\n\tif (bubbleFightInfoId ~= nil  and bubbleFightInfoId ~= 0) then bubbleFightInfoId = 0 end\r\nend\r\n\r\nfunction updateFightInfo(score, waveEndTurn, waveCount, stasis, forceDisplayUI)\r\n\tlocal score = toLong(score)\r\n\tlocal waveEndTurn = toLong(waveEndTurn)\r\n\tlocal waveCount = toLong(waveCount)\r\n\tlocal stasis = toLong(stasis)\r\n\r\n\tif (bubbleFightInfoId == 0) then\r\n\t\tbubbleFightInfoId = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_WEST\", 0, -60, false, 2147483647, true, \"interactiveBubbleDialog5\", 30000, 25000, \"onFightInfoClosed\")\r\n\tend\r\n\r\n\tBubbleText.setText(bubbleFightInfoId, \"wave.fight.player.infos\", score, waveEndTurn, waveCount, stasis)\r\n\r\n\tif (forceDisplayUI) then BubbleText.show(bubbleFightInfoId) end\r\nend\n\n-- [INIT] Variables Globales\n-- \nfunction event_2411_20807()\n    \nend\n\n-- [INIT] Le joueur entre dans l'instance - Inscription au scénario\n-- \nfunction event_2411_20808(score, waveEndTurn, waveCount, stasis)\n    updateFightInfo(score, waveEndTurn, waveCount, stasis, true)\nend\n\n-- [EVENT] Démarrage du combat - Pose des zones d'invocation des monstres de la vague\n-- \nfunction event_2411_20861()\n    \nend\n\n-- [EVENT] GLOBAL - Mise à jour du score - monstre tué\n-- \nfunction event_2411_20811(score, waveEndTurn, waveCount, stasis)\n    updateFightInfo(score, waveEndTurn, waveCount, stasis, true)\nend\n\n-- [EVENT] GLOBAL - Mise à jour du score - boss tué\n-- \nfunction event_2411_21092(score, waveEndTurn, waveCount, stasis)\n    updateFightInfo(score, waveEndTurn, waveCount, stasis, true)\nend\n\n-- [EVENT] GLOBAL - Mise à jour du score - vague passée\n-- \nfunction event_2411_21093(score, waveEndTurn, waveCount, stasis)\n    updateFightInfo(score, waveEndTurn, waveCount, stasis, true)\nend\n\n-- [EVENT] Activation Stèle 1 - Vandaliénés\n-- \nfunction event_2411_21089()\n    \nend\n\n-- [EVENT] Activation Stèle 2 - Cagnardeurs\n-- \nfunction event_2411_21090()\n    \nend\n\n-- [EVENT] Activation Stèle 3 - Crustargneux\n-- \nfunction event_2411_21091()\n    \nend\n\n-- [EVENT] Activation Stèle 4 - Toundrasoirs\n-- \nfunction event_2411_21094()\n    \nend\n\n-- [EVENT] Activation Stasis - 1\n-- \nfunction event_2411_21100(score, waveEndTurn, waveCount, stasis)\n    updateFightInfo(score, waveEndTurn, waveCount, stasis, true)\r\n    \r\n    Particle.addParticleSystem(1016314, 1, -3, 0)\r\n    InteractiveElement.setAnimation(32626, \"AnimStatique_1\")\nend\n\n-- [EVENT] Activation Stasis - 11\n-- \nfunction event_2411_21101(score, waveEndTurn, waveCount, stasis)\n    updateFightInfo(score, waveEndTurn, waveCount, stasis, true)\r\n    \r\n    Particle.addParticleSystem(1016314, 1, -3, 0)\r\n    InteractiveElement.setAnimation(32626, \"AnimStatique_2\")\nend\n\n-- [EVENT] Activation Stasis - 21\n-- \nfunction event_2411_21102(score, waveEndTurn, waveCount, stasis)\n    updateFightInfo(score, waveEndTurn, waveCount, stasis, true)\r\n    \r\n    Particle.addParticleSystem(1016314, 1, -3, 0)\r\n    InteractiveElement.setAnimation(32626, \"AnimStatique_2\")\nend\n\n-- [EVENT] Activation Stasis - 31\n-- \nfunction event_2411_21103(score, waveEndTurn, waveCount, stasis)\n    updateFightInfo(score, waveEndTurn, waveCount, stasis, true)\r\n    \r\n    Particle.addParticleSystem(1016314, 1, -3, 0)\r\n    InteractiveElement.setAnimation(32626, \"AnimStatique_3\")\nend\n\n-- [EVENT] Activation Stasis - 41\n-- \nfunction event_2411_21104(score, waveEndTurn, waveCount, stasis)\n    updateFightInfo(score, waveEndTurn, waveCount, stasis, true)\r\n    \r\n    Particle.addParticleSystem(1016314, 1, -3, 0)\r\n    InteractiveElement.setAnimation(32626, \"AnimStatique_3\")\nend\n\n-- [EVENT] Activation Nombre de tours - 15\n-- \nfunction event_2411_21105(score, waveEndTurn, waveCount, stasis)\n    updateFightInfo(score, waveEndTurn, waveCount, stasis, true)\r\n    \r\n    Particle.addParticleSystem(1016314, 1, -7, 0)\r\n    InteractiveElement.setAnimation(32625, \"AnimStatique_1\")\nend\n\n-- [EVENT] Activation Nombre de tours - 25\n-- \nfunction event_2411_21106(score, waveEndTurn, waveCount, stasis)\n    updateFightInfo(score, waveEndTurn, waveCount, stasis, true)\r\n    \r\n    Particle.addParticleSystem(1016314, 1, -7, 0)\r\n    InteractiveElement.setAnimation(32625, \"AnimStatique_2\")\nend\n\n-- [EVENT] Activation Nombre de tours - 35\n-- \nfunction event_2411_21107(score, waveEndTurn, waveCount, stasis)\n    updateFightInfo(score, waveEndTurn, waveCount, stasis, true)\r\n    \r\n    Particle.addParticleSystem(1016314, 1, -7, 0)\r\n    InteractiveElement.setAnimation(32625, \"AnimStatique_2\")\nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","closeFightInfo","onFightInfoClosed","updateFightInfo","event_2411_20807","event_2411_20808","event_2411_20861","event_2411_20811","event_2411_21092","event_2411_21093","event_2411_21089","event_2411_21090","event_2411_21091","event_2411_21094","event_2411_21100","event_2411_21101","event_2411_21102","event_2411_21103","event_2411_21104","event_2411_21105","event_2411_21106","event_2411_21107"],"quest_calls":[],"dialogue_calls":[]},"scenario/2412.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\nbubbleFightInfoId = 0\r\n\r\nfunction closeFightInfo()\r\n\tif (bubbleFightInfoId ~= nil  and bubbleFightInfoId ~= 0) then BubbleText.close(bubbleFightInfoId) end\r\nend\r\n\r\nfunction onFightInfoClosed()\r\n\tif (bubbleFightInfoId ~= nil  and bubbleFightInfoId ~= 0) then bubbleFightInfoId = 0 end\r\nend\r\n\r\nfunction updateFightInfo(wave, difficulty, forceDisplayUI)\r\n\tlocal wave = toLong(wave)\r\n\tlocal difficulty = toLong(difficulty)\r\n\r\n\tif (bubbleFightInfoId == 0) then\r\n\t\tbubbleFightInfoId = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_WEST\", 0, -60, false, 2147483647, true, \"interactiveBubbleDialog5\", 30000, 25000, \"onFightInfoClosed\")\r\n\tend\r\n\r\n\tBubbleText.setText(bubbleFightInfoId, \"wave.fight.player.infos\", wave, difficulty)\r\n\r\n\tif (forceDisplayUI) then BubbleText.show(bubbleFightInfoId) end\r\nend\n\n-- [INIT] Variables globales\n-- \nfunction event_2412_20812()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2412_21420()\n    \nend\n\n-- [EVENT] INTERACTIVE_ELEMENT_ACTIVATION - Lancement du combat\n-- \nfunction event_2412_21421()\n    trace(\"LANCEMENT DU COMBAT\")\nend\n\n-- [EVENT] FIGHT_ENTER_ACTION_PHASE - Application états\n-- \nfunction event_2412_21422()\n    \nend\n\n-- [EVENT] NEW_MONSTER_WAVE - Difficulté\n-- \nfunction event_2412_21444(wave, difficulty)\n    updateFightInfo(wave, difficulty, true)\nend\n\n-- [EVENT] EFFECT_EXECUTION - Difficulté\n-- \nfunction event_2412_21450(wave, difficulty)\n    updateFightInfo(wave, difficulty, true)\nend\n\n-- [EVENT] FIGHT_ENDED_IN_CLIENT - On ferme l'affichage\n-- \nfunction event_2412_21455()\n    closeFightInfo()\nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","closeFightInfo","onFightInfoClosed","updateFightInfo","event_2412_20812","event_2412_21420","event_2412_21421","event_2412_21422","event_2412_21444","event_2412_21450","event_2412_21455"],"quest_calls":[],"dialogue_calls":[]},"scenario/2413.lua":{"source":"World.setPictoAlpha(252, -272, 0, 0, 500)\r\n\n\n-- [INIT] Le premier joueur entre dans l'instance\n-- \nfunction event_2413_20818()\n    --    World.setPictoAlpha(-2, 6, 10, 0, 500)\r\n    --    World.setPictoAlpha(-2, 7, 10, 0, 500)\r\n    --    World.setPictoAlpha(-2, 8, 10, 0, 500)\r\n    --    World.setPictoAlpha(-2, 9, 10, 0, 500)\r\n    --    World.setPictoAlpha(-2, 10, 10, 0, 500)\r\n    --    World.setPictoAlpha(-2, 9, 10, 0, 500)\r\n    --    World.setPictoAlpha(-3, 9, 10, 0, 500)\r\n    --    World.setPictoAlpha(-4, 9, 10, 0, 500)\r\n    --    World.setPictoAlpha(-5, 9, 10, 0, 500)\r\n    \r\n    --    World.setPictoAlpha(-1, 1, 3, 0, 500)\r\n    --    World.setPictoAlpha(-1, 1, 2, 0, 500)\r\n    --    World.setPictoAlpha(-1, 1, 1, 0, 500)\r\nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_2413_20819(mountGfxId, petGfxId, characterId)\n    local characterId = toLong(characterId)\r\n    \r\n    local mountGfxId = toLong(mountGfxId)\r\n    \r\n    mountId = Mobile.generateClientMobileId()\r\n    Actor.createActor(mountId, mountGfxId, 8, -6, 0, 4)\r\n    Mobile.setMobileDirection(mountId, 3)\r\n    Pet.applyPlayerColorsToMobile(characterId, mountId, true)\r\n    \r\n    local petGfxId = toLong(petGfxId)\r\n    \r\n    newPetId = Mobile.generateClientMobileId()\r\n    Actor.createActor(newPetId, petGfxId, 4, -6, 1, 4)\r\n    Mobile.setMobileDirection(newPetId, 3)\r\n    Pet.applyPlayerColorsToMobile(characterId, newPetId, false)\r\n    \r\n    originalPetId = Actor.getActivePetMobile(characterId)\r\n    if originalPetId ~= -1 then\r\n        Mobile.hideMobile(originalPetId, true)\r\n    end\nend\n\n","functions":["event_2413_20818","event_2413_20819"],"quest_calls":[],"dialogue_calls":[]},"scenario/2414.lua":{"source":"\n\n-- [EVENT] Application du visuel Phorreur 01\n-- \nfunction event_2414_20822()\n    \nend\n\n-- [EVENT] Application du visuel Phorreur 02\n-- \nfunction event_2414_20823()\n    \nend\n\n-- [EVENT] Application du visuel Phorreur 03\n-- \nfunction event_2414_20824()\n    \nend\n\n-- [EVENT] Application du visuel Phorreur 04\n-- \nfunction event_2414_20825()\n    \nend\n\n-- [EVENT] Application du visuel Phorreur 05\n-- \nfunction event_2414_20826()\n    \nend\n\n-- [EVENT] Désapplication du visuel Phorreur\n-- \nfunction event_2414_20827()\n    \nend\n\n-- [EVENT] Application des animations de sorts à la pelle\n-- \nfunction event_2414_23386()\n    \nend\n\n-- [EVENT] Désapplication des animations de sorts à la pelle\n-- \nfunction event_2414_23387()\n    \nend\n\n-- [EVENT] Visuel Armure de la Paix \n-- \nfunction event_2414_21136()\n    \nend\n\n-- [EVENT] Retrait du visuel Armure de la paix\n-- \nfunction event_2414_21137()\n    \nend\n\n","functions":["event_2414_20822","event_2414_20823","event_2414_20824","event_2414_20825","event_2414_20826","event_2414_20827","event_2414_23386","event_2414_23387","event_2414_21136","event_2414_21137"],"quest_calls":[],"dialogue_calls":[]},"scenario/2415.lua":{"source":"\n\n-- Event - Infos au joueur\n-- \nfunction event_2415_20862()\n    UI.openRewardsDialog(\"pandalucia.collector.thirster.start\")\r\n    UI.addReward(27283)\r\n    UI.addReward(27284)\nend\n\n","functions":["event_2415_20862"],"quest_calls":["UI.openRewardsDialog(\"pandalucia.collector.thirster.start\")\r"],"dialogue_calls":[]},"scenario/2416.lua":{"source":"\n\n-- [INIT] Variables Globales\n-- \nfunction event_2416_20907()\n    \nend\n\n-- [INIT] Inscription du joueur + Variables Locales\n-- \nfunction event_2416_20908(room)\n    \nend\n\n-- FIGHT_STARTED - Applique l'état \"Salle 1\"\n-- \nfunction event_2416_21924()\n    \nend\n\n-- FIGHT_ENTER_ACTION_PHASE - Applique l'état \"Salle 1\"\n-- \nfunction event_2416_21925()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 01\n-- \nfunction event_2416_20910(room)\n    \nend\n\n-- USER_GROUP_KILLED - Salle 02 - BOSS\n-- \nfunction event_2416_20911()\n    \nend\n\n-- Déplace le joueur vers la salle suivante\n-- \nfunction event_2416_20912()\n    \nend\n\n-- [EVENT] Feedback Stasis 4+\n-- \nfunction event_2416_21128()\n    local bubble = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_EAST\", -75, -100, false, 2147483647, true, \"interactiveBubbleDialog5\", 30000, 25000)\r\n        \r\n    BubbleText.setText(bubble, \"osamosa.stasis.31.vandalophrenic\")\r\n    BubbleText.show(bubble)\nend\n\n-- [EVENT] Feedback Stasis 5+\n-- \nfunction event_2416_21129()\n    local bubble = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_EAST\", -75, -100, false, 2147483647, true, \"interactiveBubbleDialog5\", 30000, 25000)\r\n        \r\n    BubbleText.setText(bubble, \"osamosa.stasis.41.vandalophrenic\")\r\n    BubbleText.show(bubble)\nend\n\n-- [STELE] FIGHT_STARTED - On applique les difficultés sur le boss\n-- \nfunction event_2416_22852()\n    \nend\n\n-- [STELE] FIGHT_ENTER_ACTION_PHASE - On applique les bonus sur les joueurs\n-- \nfunction event_2416_22853()\n    \nend\n\n-- [STELE] FIGHT_ENDED - On rend la stèle utilisable en cas de défaite\n-- \nfunction event_2416_22896()\n    \nend\n\n-- [ARCHI] Apparition de l'Archimonstre\n-- \nfunction event_2416_24013()\n    \nend\n\n","functions":["event_2416_20907","event_2416_20908","event_2416_21924","event_2416_21925","event_2416_20910","event_2416_20911","event_2416_20912","event_2416_21128","event_2416_21129","event_2416_22852","event_2416_22853","event_2416_22896","event_2416_24013"],"quest_calls":[],"dialogue_calls":[]},"scenario/2417.lua":{"source":"\n\n-- [INIT] Variables Globales\n-- \nfunction event_2417_20863()\n    \nend\n\n-- [INIT] Inscription du joueur + Variables Locales\n-- \nfunction event_2417_20864(room)\n    \nend\n\n-- FIGHT_STARTED - Applique l'état Salle 01\n-- \nfunction event_2417_21929()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 01\n-- \nfunction event_2417_20866(room)\n    \nend\n\n-- USER_GROUP_KILLED - Salle 02 - BOSS\n-- \nfunction event_2417_20867()\n    \nend\n\n-- Déplace le joueur vers la salle suivante\n-- \nfunction event_2417_20868()\n    \nend\n\n-- [EVENT] Feedback Stasis 4+\n-- \nfunction event_2417_21130()\n    local bubble = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_EAST\", -75, -100, false, 2147483647, true, \"interactiveBubbleDialog5\", 30000, 25000)\r\n        \r\n    BubbleText.setText(bubble, \"osamosa.stasis.31.sunsloth\")\r\n    BubbleText.show(bubble)\nend\n\n-- [EVENT] Fee