ating(\"NORTH_EAST\", -75, -100, false, 2147483647, true, \"interactiveBubbleDialog5\", 30000, 25000)\r\n        \r\n    BubbleText.setText(bubble, \"osamosa.stasis.41.crabstacean\")\r\n    BubbleText.show(bubble)\nend\n\n-- FIGHT_ENTER_ACTION_PHASE - Applique l'état \"Salle 1\"\n-- \nfunction event_2418_21964()\n    \nend\n\n-- [STELE] FIGHT_STARTED - On applique les difficultés sur le boss\n-- \nfunction event_2418_22819()\n    \nend\n\n-- [STELE] FIGHT_ENTER_ACTION_PHASE - On applique les bonus sur les joueurs\n-- \nfunction event_2418_22820()\n    \nend\n\n-- [STELE] FIGHT_ENDED - On rend la stèle utilisable en cas de défaite\n-- \nfunction event_2418_22894()\n    \nend\n\n-- [ARCHI] Apparition de l'Archimonstre\n-- \nfunction event_2418_24011()\n    \nend\n\n","functions":["event_2418_20869","event_2418_20870","event_2418_20872","event_2418_20873","event_2418_20874","event_2418_21132","event_2418_21133","event_2418_21964","event_2418_22819","event_2418_22820","event_2418_22894","event_2418_24011"],"quest_calls":[],"dialogue_calls":[]},"scenario/2419.lua":{"source":"\n\n-- [INIT] Variables Globales\n-- \nfunction event_2419_20875()\n    \nend\n\n-- [INIT] Inscription du joueur + Variables Locales\n-- \nfunction event_2419_20876(room)\n    \nend\n\n-- USER_GROUP_KILLED - Salle 01\n-- \nfunction event_2419_20878(room)\n    \nend\n\n-- USER_GROUP_KILLED - Salle 02 - BOSS\n-- \nfunction event_2419_20879()\n    \nend\n\n-- Déplace le joueur vers la salle suivante\n-- \nfunction event_2419_20880()\n    \nend\n\n-- [EVENT] Feedback Stasis 4+\n-- \nfunction event_2419_21134()\n    local bubble = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_EAST\", -75, -100, false, 2147483647, true, \"interactiveBubbleDialog5\", 30000, 25000)\r\n        \r\n    BubbleText.setText(bubble, \"osamosa.stasis.31.tundrazor\")\r\n    BubbleText.show(bubble)\nend\n\n-- [EVENT] Feedback Stasis 5+\n-- \nfunction event_2419_21135()\n    local bubble = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_EAST\", -75, -100, false, 2147483647, true, \"interactiveBubbleDialog5\", 30000, 25000)\r\n        \r\n    BubbleText.setText(bubble, \"osamosa.stasis.41.tundrazor\")\r\n    BubbleText.show(bubble)\nend\n\n-- FIGHT_STARTED - Applique l'état \"Salle 1\"\n-- \nfunction event_2419_21966()\n    \nend\n\n-- FIGHT_ENTER_ACTION_PHASE - Applique l'état \"Salle 1\"\n-- \nfunction event_2419_21967()\n    \nend\n\n-- [STELE] FIGHT_STARTED - On applique les difficultés sur le boss\n-- \nfunction event_2419_22817()\n    \nend\n\n-- [STELE] FIGHT_ENTER_ACTION_PHASE - On applique les bonus sur les joueurs\n-- \nfunction event_2419_22818()\n    \nend\n\n-- [STELE] FIGHT_ENDED - On rend la stèle utilisable en cas de défaite\n-- \nfunction event_2419_22893()\n    \nend\n\n-- [ARCHI] Apparition de l'Archimonstre\n-- \nfunction event_2419_24010()\n    \nend\n\n","functions":["event_2419_20875","event_2419_20876","event_2419_20878","event_2419_20879","event_2419_20880","event_2419_21134","event_2419_21135","event_2419_21966","event_2419_21967","event_2419_22817","event_2419_22818","event_2419_22893","event_2419_24010"],"quest_calls":[],"dialogue_calls":[]},"scenario/2421.lua":{"source":"function dollVisible(mobileId, bool)\r\n\tMobile.setMobileVisible(mobileId, bool)\r\nend\r\n\r\nfunction dollApparition(mobileId)\r\n\tMobile.setMobileAnimation(mobileId, \"AnimApparition\")\r\nend\n\n-- [INIT] Variables\n-- \nfunction event_2421_20917()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2421_20918()\n    \nend\n\n-- [EVENT] Le joueur marche sur un position trigger - les poupées apparaissent\n-- \nfunction event_2421_20923(dollOneId, dollTwoId, dollThreeId)\n    Mobile.setMobileAnimation(dollOneId, \"AnimApparition\", \"Mobile.setMobileAnimation\", dollOneId, \"AnimSort-AgacementGarou\")\r\n    Mobile.setMobileAnimation(dollTwoId, \"AnimApparition\", \"Mobile.setMobileAnimation\", dollTwoId, \"AnimSort-AgacementGarou\")\r\n    Mobile.setMobileAnimation(dollThreeId, \"AnimApparition\", \"Mobile.setMobileAnimation\", dollThreeId, \"AnimSort-AgacementGarou\")\nend\n\n-- [EVENT] Le joueur récolte un minerai (variable OSAMOSA_Minerai)\n-- \nfunction event_2421_21071()\n    \nend\n\n","functions":["dollVisible","dollApparition","event_2421_20917","event_2421_20918","event_2421_20923","event_2421_21071"],"quest_calls":[],"dialogue_calls":[]},"scenario/2422.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\n\n-- [INIT] Variables\n-- \nfunction event_2422_20937()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2422_20938()\n    \nend\n\n-- [EVENT] Cinématique - Arrivée (ACH 4750 OBJ 9863) - Coqueline\n-- \nfunction event_2422_20940(arturoId, malloryId)\n    local playerId = Context.getLeaderId()\r\n    local arturoId = toLong(arturoId)\r\n    local malloryId = toLong(malloryId)\r\n    \r\n    startCinematicContext(1, playerId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 20940)\r\n    \r\n    invoke_custom(01500, 1, \"Mobile.setMobileDirection\", playerId, 1)\r\n    invoke_custom(01700, 1, \"Mobile.setMobileDirection\", playerId, 3)\r\n    invoke_custom(01900, 1, \"Mobile.setMobileDirection\", playerId, 5)\r\n    invoke_custom(02100, 1, \"Mobile.moveMobile\", playerId, -1, -6, 0, \"Mobile.setMobileDirection\", playerId, 5)\r\n    \r\n    ---\"Salut ! C'est bien par ici la Dimension Osamodas ?\"\r\n    invoke_custom(02500, 1, \"bubble\", playerId, \"quest.osamosa.01.01\")\r\n    invoke_custom(03000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Coucou\")\r\n    invoke_custom(07000, 1, \"clearBubbles\", playerId)\r\n    \r\n    ---\"On dirait bien, mais cette porte nous bloque l’accès.\"\r\n    invoke_custom(07500, 1, \"bubble\", arturoId, \"quest.osamosa.01.02\")\r\n    invoke_custom(11500, 1, \"clearBubbles\", arturoId)\r\n    \r\n    ---\"Et vous ne pouvez pas vous téléporter derrière la porte ?\"\r\n    invoke_custom(12000, 1, \"Mobile.setMobileDirection\", playerId, 7)\r\n    invoke_custom(12500, 1, \"bubble\", playerId, \"quest.osamosa.01.03\")\r\n    invoke_custom(13000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(17500, 1, \"clearBubbles\", playerId)\r\n    \r\n    ---\"Avec le... Le \"Sauce-Iop-Démentielle\" par exemple.\"\r\n    invoke_custom(19500, 1, \"Mobile.setMobileDirection\", playerId, 5)\r\n    invoke_custom(18000, 1, \"bubble\", playerId, \"quest.osamosa.01.04\")\r\n    invoke_custom(20000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmoteMarket-HausseEpaules\")\r\n    invoke_custom(24500, 1, \"clearBubbles\", playerId)\r\n    \r\n    ---\"Tu veux dire le \"Simplificateur-Imaginaire-Déplaçant\" !\"\r\n    invoke_custom(25000, 1, \"bubble\", malloryId, \"quest.osamosa.01.05\")\r\n    invoke_custom(29500, 1, \"clearBubbles\", malloryId)\r\n    \r\n    ---\"Mais... Rien, laissez tomber.\"\r\n    invoke_custom(30000, 1, \"bubble\", arturoId, \"quest.osamosa.01.06\")\r\n    invoke_custom(33500, 1, \"clearBubbles\", arturoId)\r\n    \r\n    ---\"Le problème, c’est que le Zaap n’est même pas activé.\"\r\n    invoke_custom(34000, 1, \"bubble\", malloryId, \"quest.osamosa.01.07\")\r\n    invoke_custom(38500, 1, \"clearBubbles\", malloryId)\r\n    \r\n    invoke_custom(39000, 1, \"Camera.setCamera\", 1, 1, -18, 0)\r\n    invoke_custom(42000, 1, \"Camera.setCamera\", 1, -1, -6, 0)\r\n    \r\n    ---\"À mon avis, il ne faut pas forcer l'ouverture.\"\r\n    invoke_custom(42000, 1, \"bubble\", malloryId, \"quest.osamosa.01.08\")\r\n    invoke_custom(45000, 1, \"clearBubbles\", malloryId)\r\n    \r\n    ---\"Je vois.\"\r\n    invoke_custom(45500, 1, \"bubble\", playerId, \"quest.osamosa.01.09\")\r\n    invoke_custom(47000, 1, \"clearBubbles\", playerId)\r\n    \r\n    ---\"Il faut donc l’ouvrir par nous-mêmes !\"\r\n    invoke_custom(47500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Victoire\")\r\n    invoke_custom(47500, 1, \"bubble\", playerId, \"quest.osamosa.01.10\")\r\n    invoke_custom(51000, 1, \"clearBubbles\", playerId)\r\n    \r\n    ---\"C’est pas si simple !\"\r\n    invoke_custom(51500, 1, \"bubble\", arturoId, \"quest.osamosa.01.11\")\r\n    invoke_custom(54000, 1, \"clearBubbles\", arturoId)\r\n    \r\n    ---\"Figure-toi qu’il y a une énigme.\"\r\n    invoke_custom(54500, 1, \"bubble\", arturoId, \"quest.osamosa.01.12\")\r\n    invoke_custom(58000, 1, \"clearBubbles\", arturoId)\r\n    \r\n    ---\"D’habitude j’aime bien les casse-têtes, mais là... \"\r\n    invoke_custom(58500, 1, \"bubble\", arturoId, \"quest.osamosa.01.13\")\r\n    invoke_custom(62000, 1, \"clearBubbles\", arturoId)\r\n    \r\n    ---\"Voyons-voir ça...\"\r\n    invoke_custom(62500, 1, \"Mobile.setMobileMovementStyle\", playerId, \"WALK\", \"WALK\")\r\n    invoke_custom(62500, 1, \"Mobile.setCustomWalkStyle\", playerId, \"AnimMarche\", 600)\r\n    invoke_custom(62500, 1, \"bubble\", playerId, \"quest.osamosa.01.14\")\r\n    invoke_custom(63000, 1, \"Mobile.moveMobile\", playerId, -3, -8, 0, \"Mobile.setMobileDirection\", playerId, 7)\r\n    invoke_custom(64000, 1, \"clearBubbles\", playerId)\r\n    \r\n    ---\"\"Seuls les plus braves peuvent passer cette porte.\"\"\r\n    invoke_custom(64500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(64500, 1, \"bubble\", playerId, \"quest.osamosa.01.15\")\r\n    invoke_custom(68500, 1, \"clearBubbles\", playerId)\r\n    \r\n    ---\"Non non, c’est pas cette porte, c’est l’autre.\"\r\n    invoke_custom(69000, 1, \"bubble\", malloryId, \"quest.osamosa.01.16\")\r\n    invoke_custom(73000, 1, \"clearBubbles\", malloryId)\r\n    \r\n    ---\"Ah pardon.\"\r\n    invoke_custom(73500, 1, \"bubble\", playerId, \"quest.osamosa.01.17\")\r\n    invoke_custom(73000, 1, \"Mobile.moveMobile\", playerId, 1, -8, 0, \"Mobile.setMobileDirection\", playerId, 7)\r\n    invoke_custom(76000, 1, \"clearBubbles\", playerId)\r\n    \r\n    ---\"\"Les bêlements les plus mignons sont ceux d’un bouftou endormi.\"\"\r\n    invoke_custom(76500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(76500, 1, \"bubble\", playerId, \"quest.osamosa.01.18\")\r\n    invoke_custom(82500, 1, \"clearBubbles\", playerId)\r\n    \r\n    ---\"Ça a l’air de parler de Bouftou, mais personnellement je n’y connais pas grand-chose.\"\r\n    invoke_custom(83000, 1, \"Mobile.setMobileDirection\", playerId, 5)\r\n    invoke_custom(83500, 1, \"bubble\", playerId, \"quest.osamosa.01.19\")\r\n    invoke_custom(90500, 1, \"clearBubbles\", playerId)\r\n    \r\n    ---\"J’ai entendu parler d’une Osamodas qui rassemble tout plein de créatures.\"\r\n    invoke_custom(91500, 1, \"bubble\", malloryId, \"quest.osamosa.01.20\")\r\n    invoke_custom(97500, 1, \"clearBubbles\", malloryId)\r\n    \r\n    ---\"Elle aurait été aperçue au Mont Zinit récemment.\"\r\n    invoke_custom(98000, 1, \"bubble\", malloryId, \"quest.osamosa.01.21\")\r\n    invoke_custom(102500, 1, \"clearBubbles\", malloryId)\r\n    \r\n    ---\"**Coqueline !\"\r\n    invoke_custom(103000, 1, \"bubble\", playerId, \"quest.osamosa.01.22.1\")\r\n    invoke_custom(105000, 1, \"clearBubbles\", playerId)\r\n    \r\n    ---\"Je la connais bien, je vais lui demander son avis !\"\r\n    invoke_custom(103000, 1, \"bubble\", playerId, \"quest.osamosa.01.23.1\")\r\n    invoke_custom(105000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke(105200, 1, \"skipCinematic\", 20940)\nend\n\n-- [EVENT] Cinématique - Arrivée (ACH 4750 OBJ 9863) - Pas Coqueline\n-- \nfunction event_2422_20941(arturoId, malloryId)\n    local playerId = Context.getLeaderId()\r\n    local arturoId = toLong(arturoId)\r\n    local malloryId = toLong(malloryId)\r\n    \r\n    startCinematicContext(1, playerId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 20941)\r\n    \r\n    invoke_custom(01500, 1, \"Mobile.setMobileDirection\", playerId, 1)\r\n    invoke_custom(01700, 1, \"Mobile.setMobileDirection\", playerId, 3)\r\n    invoke_custom(01900, 1, \"Mobile.setMobileDirection\", playerId, 5)\r\n    invoke_custom(02100, 1, \"Mobile.moveMobile\", playerId, -1, -6, 0, \"Mobile.setMobileDirection\", playerId, 5)\r\n    \r\n    ---\"Salut ! C'est bien par ici la Dimension Osamodas ?\"\r\n    invoke_custom(02500, 1, \"bubble\", playerId, \"quest.osamosa.01.01\")\r\n    invoke_custom(03000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Coucou\")\r\n    invoke_custom(07000, 1, \"clearBubbles\", playerId)\r\n    \r\n    ---\"On dirait bien, mais cette porte nous bloque l’accès.\"\r\n    invoke_custom(07500, 1, \"bubble\", arturoId, \"quest.osamosa.01.02\")\r\n    invoke_custom(11500, 1, \"clearBubbles\", arturoId)\r\n    \r\n    ---\"Et vous ne pouvez pas vous téléporter derrière la porte ?\"\r\n    invoke_custom(12000, 1, \"Mobile.setMobileDirection\", playerId, 7)\r\n    