, 1, \"Mobile.setMobilePosition\", malloryId, -4, -5, 0)\r\n    invoke_custom(70500, 1, \"Mobile.setMobileDirection\", malloryId, 1)\r\n    invoke_custom(70500, 1, \"Mobile.setMobileDirection\", arturoId, 1)\r\n    invoke_custom(70500, 1, \"Mobile.setMobileDirection\", playerId, 5)\r\n    invoke_custom(70500, 1, \"Mobile.setMobileDirection\", bouftouId, 1)\r\n    \r\n    invoke_custom(71000, 1, \"UI.displayWideScreenBand\", true, 25, 300)\r\n    \r\n    invoke_custom(71000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmoteMusiqueGroupe-Ocarina-Debut\")\r\n    invoke_custom(71000, 1, \"Mobile.setMobileAnimation\", bouftouId, \"AnimComp-Dormir-Debut\")\r\n    \r\n    invoke_custom(75000, 1, \"Particle.addParticleSystemToTargetWithOffset\", apsId, bouftouId, 0, 0)\r\n    invoke_custom(78999, 1, \"Particle.clearParticleSystemOnMobile\", bouftouId)\r\n    invoke_custom(79000, 1, \"Particle.addParticleSystemToTargetWithOffset\", apsId, bouftouId, 0, 0)\r\n    invoke_custom(82999, 1, \"Particle.clearParticleSystemOnMobile\", bouftouId)\r\n    invoke_custom(83000, 1, \"Particle.addParticleSystemToTargetWithOffset\", apsId, bouftouId, 0, 0)\r\n    \r\n    ---\"**Alors, ça marche ?\"\r\n    invoke_custom(75000, 1, \"bubble\", arturoId, \"quest.osamosa.02.13\")\r\n    invoke_custom(78000, 1, \"clearBubbles\", arturoId)\r\n    \r\n    ---\"**Chut ! On dirait qu’il dort...\"\r\n    invoke_custom(77500, 1, \"bubble\", malloryId, \"quest.osamosa.02.14\")\r\n    invoke_custom(80500, 1, \"clearBubbles\", malloryId)\r\n    \r\n    invoke_custom(80500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmoteMusiqueGroupe-Ocarina-Fin\")\r\n    \r\n    ---\"**Attendez, quelque chose s’approche !\"\r\n    invoke_custom(82500, 1, \"bubble\", playerId, \"quest.osamosa.02.15\")\r\n    invoke_custom(87000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(87500, 1, \"Particle.addParticleSystem\", -1102032740, -1, -7, 0)\r\n    invoke_custom(88000, 1, \"Mobile.setMobileVisible\", bigBouftouId, true)\r\n    invoke_custom(88000, 1, \"Mobile.setMobileVisible\", bouftouId, false)\r\n    invoke_custom(89500, 1, \"Mobile.setMobileAnimation\", bigBouftouId, \"AnimSort-DernierRempart\")\r\n    \r\n    ---\"On dirait une sorte de gardien !\"\r\n    invoke_custom(91500, 1, \"bubble\", malloryId, \"quest.osamosa.02.16\")\r\n    invoke_custom(95000, 1, \"clearBubbles\", malloryId)\r\n    \r\n    ---\"Reculez, je m’en charge.\"\r\n    invoke_custom(95500, 1, \"bubble\", playerId, \"quest.osamosa.02.17\")\r\n    invoke_custom(99000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(99500, 1, \"customSkip\")\nend\n\n-- [EVENT] Fin de la Cinématique - Lancement du combat Bouftou\n-- \nfunction event_2422_20944()\n    \nend\n\n-- [EVENT] Cinématique - Le joueur bat le Bouftou\n-- \nfunction event_2422_20945(arturoId, malloryId)\n    local playerId = Context.getLeaderId()\r\n    local arturoId = toLong(arturoId)\r\n    local malloryId = toLong(malloryId)\r\n    local bigBouftouId = createActor(100201520, -1, -7, 0, 8, 5, 6)\r\n    Mobile.setPartColor(bigBouftouId, \"Cheveux\", 0.30, 0.20, 0.11, 1)\r\n    Actor.equip(playerId, \"11310014\", \"Arme\")\r\n    Actor.equip(playerId, \"18919449\", \"Bouclier\")\r\n    \r\n    local apsFinish = 1012321\r\n    \r\n    function displayExtraDamage()\r\n    \tUI.displayFlyingText(1, 0.4, 0.1, \"lstw\", bigBouftouId, \"finish.move.damage\", 0, 55, -999999)\r\n    end\r\n    \r\n    if (UI.isDialogLoaded(dialogName)) then \r\n        \tUI.unloadDialog(dialogName)\r\n     else\r\n     \tUI.addDialogLoadedListener(dialogName, \"UI.unloadDialog\", dialogName)\r\n     end\r\n     \r\n    startCinematicContext(1.2, arturoId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 20945)\r\n    \r\n    -- Début cinématique\r\n    \r\n    invoke_custom(01000, 1, \"Mobile.setMobilePosition\", playerId, -1, -8, 0, \"Mobile.setMobileDirection\", playerId, 1)\r\n    invoke_custom(03200, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimStatique03-Debut-113\")\r\n    invoke_custom(04500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimStatique03-113\")\r\n    invoke_custom(05100, 1, \"displayExtraDamage\")\r\n    invoke_custom(05100, 1, \"Particle.addParticleSystem\", apsFinish, -1, -7, 0)\r\n    invoke_custom(05500, 1, \"Mobile.setMobileAnimation\", bigBouftouId, \"AnimMort\")\r\n    invoke_custom(07500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimStatique03-Fin-113\")\r\n    \r\n    -- \"Bon, ça m’a l’air plutôt dangereux comme Dimension.\"\r\n    invoke_custom(07500, 1, \"bubble\", malloryId, \"quest.osamosa.02.18\")\r\n    invoke_custom(11500, 1, \"clearBubbles\", malloryId)\r\n    \r\n    -- \"C’est pas faux. On va te laisser y aller.\"\r\n    invoke_custom(12000, 1, \"bubble\", arturoId, \"quest.osamosa.02.19\")\r\n    invoke_custom(16500, 1, \"clearBubbles\", arturoId)\r\n    \r\n    ---\"Ouais, restez-là et essayez d’ouvrir l’autre porte.\"\r\n    invoke_custom(17000, 1, \"Mobile.setMobileDirection\", playerId, 5)\r\n    invoke_custom(17500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmoteMarket-HausseEpaules\")\r\n    invoke_custom(17000, 1, \"bubble\", playerId, \"quest.osamosa.02.20\")\r\n    invoke_custom(21500, 1, \"clearBubbles\", playerId)\r\n    \r\n    ---\"Je me charge d’y aller en reconnaissance.\"\r\n    invoke_custom(22000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Pouce\")\r\n    invoke_custom(22000, 1, \"bubble\", playerId, \"quest.osamosa.02.21\")\r\n    invoke_custom(25500, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(26000, 1, \"skipCinematic\", 20945)\nend\n\n-- [EVENT] Fin de la Cinématique - Téléportation\n-- \nfunction event_2422_20947()\n    \nend\n\n-- [EVENT] ENTER_INSTANCE - Quête finie\n-- \nfunction event_2422_20946()\n    World.setPictoAlpha(1, -9, 8, 0, 1000)\r\n    Particle.addParticleSystem(800521, 1, -18, 0)\nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_2422_20937","event_2422_20938","event_2422_20940","event_2422_20941","event_2422_20942","event_2422_20943","customSkip","event_2422_20944","event_2422_20945","displayExtraDamage","event_2422_20947","event_2422_20946"],"quest_calls":[],"dialogue_calls":[]},"scenario/2423.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\n\n-- [EVENT] Cinématique Arrivée 1 - Forêt Dorsale\n-- \nfunction event_2423_20958()\n    local playerId = Context.getLeaderId()\r\n    \r\n    local mimiId = createActor(177804141, -58, -82, 0, 4, 1, 8)\r\n    local invocId = createActor(158103845, -51, -82, 0, 4, 3, 8)\r\n    local chevalierId = createActor(159302867, -56, -81, 0, 4, 1, 8)\r\n    \r\n    local pnjThreeId = toLong(pnjThreeId)\r\n    local pnjFourId = toLong(pnjFourId)\r\n    \r\n    local mekaOneId = createActor(150402350, -53, -81, 0, 4, 5, 6)\r\n    local mekaTwoId = createActor(150402352, -51, -81, 0, 4, 5, 6)\r\n    \r\n    ----------------------------- CINEMATIQUE -----------------------------\r\n    \r\n    clearCompasses()\r\n    startCinematicContext(1.4, playerId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 20707)\r\n    \r\n    invoke_custom(00001, 1, \"Mobile.setMobileVisible\", chevalierId, false)\r\n    invoke_custom(00001, 1, \"Mobile.setMobileVisible\", playerId, false)\r\n    invoke_custom(00001, 1, \"Mobile.setMobileVisible\", pnjThreeId, false)\r\n    invoke_custom(00001, 1, \"Mobile.setMobileVisible\", pnjFourId, false)\r\n    \r\n    invoke_custom(02500, 1, \"Mobile.moveMobile\", mekaOneId, -55, -81, -0, \"Mobile.setMobileDirection\", mekaOneId, 5)\r\n    invoke_custom(04500, 1, \"Mobile.setMobileVisible\", chevalierId, true)\r\n    invoke_custom(04500, 1, \"Mobile.setMobileAnimation\", chevalierId, \"AnimApparition\")\r\n    invoke_custom(06500, 1, \"Mobile.setMobileAnimation\", chevalierId, \"AnimSort-Taille\")\r\n    invoke_custom(07500, 1, \"Mobile.setMobileAnimation\", mekaOneId, \"AnimMort\")\r\n    \r\n    invoke_custom(08000, 1, \"Mobile.setMobileAnimation\", mimiId, \"AnimSort-Ocarina\")\r\n    invoke_custom(09500, 1, \"Mobile.setMobileAnimation\", invocId, \"AnimSort-Machouillage\")\r\n    invoke_custom(10000, 1, \"Mobile.setMobileAnimation\", mekaTwoId, \"AnimMort\")\r\n    \r\n    invoke_custom(11500, 1, \"Mobile.setMobileAnimation\", invocId, \"AnimSort-RugissementSpectral\")\r\n    invoke_custom(11500, 1, \"Mobile.setMobileAnimation\", mimiId, \"AnimDial-Joie\")\r\n    \r\n    invoke_custom(14000, 1, \"skipCinematic\", 20707)\nend\n\n-- [EVENT] Cinématique Arrivée 2 - Aile Aride\n-- \nfunction event_2423_20959(pnjOneId, pnjTwoId)\n    local playerId = Context.getLeaderId()\r\n    \r\n    local chuchoId = createActor(145102076, -67, -8, -60, 4, 7, 8)\r\n    local craqId = createActor(145102083, -69, -9, -60, 4, 1, 8)\r\n    local megaCraqId = createActor(145102084, -67, -13, -60, 4, 1, 8)\r\n    \r\n    local pnjOneId = toLong(pnjOneId)\r\n    local pnjTwoId = toLong(pnjTwoId)\r\n    \r\n    local mekaOneId = createActor(150402351, -67, -9, -60, 4, 3, 6)\r\n    local mekaTwoId = createActor(150402353, -66, -13, -60, 4, 5, 6)\r\n    \r\n    Mobile.setPartColor(chuchoId, \"Color_1\", 1.00, 0.0, 0.00, 1)\r\n    Mobile.setPartColor(chuchoId, \"Color_2\", 1.00, 1.00, 1.00, 1)\r\n    Mobile.setPartColor(chuchoId, \"Peau\", 0.41, 0.35, 0.32, 1)\r\n    Mobile.setPartColor(chuchoId, \"Cheveux\", 0.90, 0.90, 0.90, 1)\r\n    \r\n    Mobile.setPartColor(craqId, \"Color_1\", 0.40, 0.56, 0.73, 1)\r\n    Mobile.setPartColor(craqId, \"Color_2\", 1.00, 1.00, 1.00, 1)\r\n    Mobile.setPartColor(craqId, \"Peau\", 0.55, 0.47, 0.43, 1)\r\n    Mobile.setPartColor(craqId, \"Cheveux\", 0.90, 0.90, 0.90, 1)\r\n    \r\n    Mobile.setPartColor(megaCraqId, \"Color_1\", 0.40, 0.56, 0.73, 1)\r\n    Mobile.setPartColor(megaCraqId, \"Color_2\", 1.00, 1.00, 1.00, 1)\r\n    Mobile.setPartColor(megaCraqId, \"Peau\", 0.41, 0.35, 0.32, 1)\r\n    Mobile.setPartColor(megaCraqId, \"Cheveux\", 0.90, 0.90, 0.90, 1)\r\n    \r\n    ----------------------------- CINEMATIQUE -----------------------------\r\n    \r\n    clearCompasses()\r\n    startCinematicContext(1.4, playerId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 20708)\r\n    \r\n    invoke_custom(00001, 1, \"Mobile.setMobileVisible\", playerId, false)\r\n    invoke_custom(00001, 1, \"Mobile.setMobileVisible\", pnjOneId, false)\r\n    invoke_custom(00001, 1, \"Mobile.setMobileVisible\", pnjTwoId, false)\r\n    invoke_custom(00001, 1, \"Mobile.setMobileAnimation\", craqId, \"AnimStatiqueCadavre\")\r\n    \r\n    invoke_custom(02500, 1, \"Mobile.setMobileAnimation\", megaCraqId, \"AnimSort-Ecrasement\")\r\n    invoke_custom(03700, 1, \"Mobile.setMobileAnimation\", mekaTwoId, \"AnimMort\")\r\n    \r\n    invoke_custom(05000, 1, \"Mobile.setMobileAnimation\", chuchoId, \"AnimSort-OteToi\")\r\n    invoke_custom(06000, 1, \"Mobile.setMobileAnimation\", mekaOneId, \"AnimMort\")\r\n    invoke_custom(06800, 1, \"Mobile.setMobileVisible\", mekaOneId, false)\r\n    \r\n    invoke_custom(08000, 1, \"Mobile.setMobileAnimation\", chuchoId, \"AnimSort-Soin\")\r\n    invoke_custom(08000, 1, \"Mobile.setMobileAnimation\", megaCraqId, \"AnimSort-Tremblemental\")\r\n    \r\n    invoke_custom(10500, 1, \"skipCinematic\", 20708)\nend\n\n-- [EVENT] Cinématique Arrivée 3 - Rivage Caudal\n-- \nfunction event_2423_20960(pnjOneId, pnjTwoId)\n    local playerId = Context.getLeaderId()\r\n    \r\n    local chuchoId = createActor(145102076, -67, -8, -60, 4, 7, 8)\r\n    local craqId = createActor(145102083, -69, -9, -60, 4, 1, 8)\r\n    local megaCraqId = createActor(145102084, -67, -13, -60, 4, 1, 8)\r\n    \r\n    local pnjOneId = toLong(pnjOneId)\r\n    local pnjTwoId = toLong(pnjTwoId)\r\n    \r\n    local mekaOneId = createActor(150402351, -67, -9, -60, 4, 3, 6)\r\n    local mekaTwoId = createActor(150402353, -66, -13, -60, 4, 5, 6)\r\n    \r\n    Mobile.setPartColor(chuchoId, \"Color_1\", 1.00, 0.0, 0.00, 1)\r\n    Mobile.setPartColor(chuchoId, \"Color_2\", 1.00, 1.00, 1.00, 1)\r\n    Mobile.setPartColor(chuchoId, \"Peau\", 0.41, 0.35, 0.32, 1)\r\n    Mobile.setPartColor(chuchoId, \"Cheveux\", 0.90, 0.90, 0.90, 1)\r\n    \r\n    Mobile.setPartColor(craqId, \"Color_1\", 0.40, 0.56, 0.73, 1)\r\n    Mobile.setPartColor(craqId, \"Color_2\", 1.00, 1.00, 1.00, 1)\r\n    Mobile.setPartColor(craqId, \"Peau\", 0.55, 0.47, 0.43, 1)\r\n    Mobile.setPartColor(craqId, \"Cheveux\", 0.90, 0.90, 0.90, 1)\r\n    \r\n    Mobile.setPartColor(megaCraqId, \"Color_1\", 0.40, 0.56, 0.73, 1)\r\n    Mobile.setPartColor(megaCraqId, \"Color_2\", 1.00, 1.00, 1.00, 1)\r\n    Mobile.setPartColor(megaCraqId, \"Peau\", 0.41, 0.35, 0.32, 1)\r\n    Mobile.setPartColor(megaCraqId, \"Cheveux\", 0.90, 0.90, 0.90, 1)\r\n    \r\n    ----------------------------- CINEMATIQUE -----------------------------\r\n    \r\n    clearCompasses()\r\n    startCinematicContext(1.4, playerId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 20708)\r\n    \r\n    invoke_custom(00001, 1, \"Mobile.setMobileVisible\", playerId, false)\r\n    invoke_custom(00001, 1, \"Mobile.setMobileVisible\", pnjOneId, false)\r\n    invoke_custom(00001, 1, \"Mobile.setMobileVisible\", pnjTwoId, false)\r\n    invoke_custom(00001, 1, \"Mobile.setMobileAnimation\", craqId, \"AnimStatiqueCadavre\")\r\n    \r\n    invoke_custom(02500, 1, \"Mobile.setMobileAnimation\", megaCraqId, \"AnimSort-Ecrasement\")\r\n    invoke_custom(03700, 1, \"Mobile.setMobileAnimation\", mekaTwoId, \"AnimMort\")\r\n    \r\n    invoke_custom(05000, 1, \"Mobile.setMobileAnimation\", chuchoId, \"AnimSort-OteToi\")\r\n    invoke_custom(06000, 1, \"Mobile.setMobileAnimation\", mekaOneId, \"AnimMort\")\r\n    invoke_custom(06800, 1, \"Mobile.setMobileVisible\", mekaOneId, false)\r\n    \r\n    invoke_custom(08000, 1, \"Mobile.setMobileAnimation\", chuchoId, \"AnimSort-Soin\")\r\n    invoke_custom(08000, 1, \"Mobile.setMobileAnimation\", megaCraqId, \"AnimSort-Tremblemental\")\r\n    \r\n    invoke_custom(10500, 1, \"skipCinematic\", 20708)\nend\n\n-- [EVENT] Cinématique Arrivée 4 - Aile Glaciaire\n-- \nfunction event_2423_20961(pnjOneId, pnjTwoId)\n    local playerId = Context.getLeaderId()\r\n    \r\n    local chuchoId = createActor(145102076, -67, -8, -60, 4, 7, 8)\r\n    local craqId = createActor(145102083, -69, -9, -60, 4, 1, 8)\r\n    local megaCraqId = createActor(145102084, -67, -13, -60, 4, 1, 8)\r\n    \r\n    local pnjOneId = toLong(pnjOneId)\r\n    local pnjTwoId = toLong(pnjTwoId)\r\n    \r\n    local mekaOneId = createActor(150402351, -67, -9, -60, 4, 3, 6)\r\n    local mekaTwoId = createActor(150402353, -66, -13, -60, 4, 5, 6)\r\n    \r\n    Mobile.setPartColor(chuchoId, \"Color_1\", 1.00, 0.0, 0.00, 1)\r\n    Mobile.setPartColor(chuchoId, \"Color_2\", 1.00, 1.00, 1.00, 1)\r\n    Mobile.setPartColor(chuchoId, \"Peau\", 0.41, 0.35, 0.32, 1)\r\n    Mobile.setPartColor(chuchoId, \"Cheveux\", 0.90, 0.90, 0.90, 1)\r\n    \r\n    Mobile.setPartColor(craqId, \"Color_1\", 0.40, 0.56, 0.73, 1)\r\n    Mobile.setPartColor(craqId, \"Color_2\", 1.00, 1.00, 1.00, 1)\r\n    Mobile.setPartColor(craqId, \"Peau\", 0.55, 0.47, 0.43, 1)\r\n    Mobile.setPartColor(craqId, \"Cheveux\", 0.90, 0.90, 0.90, 1)\r\n    \r\n    Mobile.setPartColor(megaCraqId, \"Color_1\", 0.40, 0.56, 0.73, 1)\r\n    Mobile.setPartColor(megaCraqId, \"Color_2\", 1.00, 1.00, 1.00, 1)\r\n    Mobile.setPartColor(megaCraqId, \"Peau\", 0.41, 0.35, 0.32, 1)\r\n    Mobile.setPartColor(megaCraqId, \"Cheveux\", 0.90, 0.90, 0.90, 1)\r\n    \r\n    ----------------------------- CINEMATIQUE -----------------------------\r\n    \r\n    clearCompasses()\r\n    startCinematicContext(1.4, playerId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 20708)\r\n    \r\n    invoke_custom(00001, 1, \"Mobile.setMobileVisible\", playerId, false)\r\n    invoke_custom(00001, 1, \"Mobile.setMobileVisible\", pnjOneId, false)\r\n    invoke_custom(00001, 1, \"Mobile.setMobileVisible\", pnjTwoId, false)\r\n    invoke_custom(00001, 1, \"Mobile.setMobileAnimation\", craqId, \"AnimStatiqueCadavre\")\r\n    \r\n    invoke_custom(02500, 1, \"Mobile.setMobileAnimation\", megaCraqId, \"AnimSort-Ecrasement\")\r\n    invoke_custom(03700, 1, \"Mobile.setMobileAnimation\", mekaTwoId, \"AnimMort\")\r\n    \r\n    invoke_custom(05000, 1, \"Mobile.setMobileAnimation\", chuchoId, \"AnimSort-OteToi\")\r\n    invoke_custom(06000, 1, \"Mobile.setMobileAnimation\", mekaOneId, \"AnimMort\")\r\n    invoke_custom(06800, 1, \"Mobile.setMobileVisible\", mekaOneId, false)\r\n    \r\n    invoke_custom(08000, 1, \"Mobile.setMobileAnimation\", chuchoId, \"AnimSort-Soin\")\r\n    invoke_custom(08000, 1, \"Mobile.setMobileAnimation\", megaCraqId, \"AnimSort-Tremblemental\")\r\n    \r\n    invoke_custom(10500, 1, \"skipCinematic\", 20708)\nend\n\n-- [EVENT] Cinématique Arrivée 5 - Laboratoire\n-- \nfunction event_2423_20962()\n    local playerId = Context.getLeaderId()\r\n    local pandoraId = createActor(163503405, 2, -26, 0, 4, 3, 6)\r\n    \r\n    ----------------------------- CINEMATIQUE -----------------------------\r\n    \r\n    startCinematicContext(1.4, playerId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 20962)\r\n    \r\n    invoke_custom(00001, 1, \"Mobile.setMobileVisible\", pandoraId, false)\r\n    invoke_custom(01100, 1, \"Mobile.setMobileDirection\", playerId, 1)\r\n    \r\n    ---\"Eh bien... Par où commencer ?\"\r\n    invoke_custom(02500, 1, \"bubble\", playerId, \"quest.osamosa.02.22\")\r\n    invoke_custom(03000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(07000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(07500, 1, \"Mobile.setMobileDirection\", playerId, 7)\r\n    \r\n    invoke_custom(07800, 1, \"Particle.addParticleSystem\", 800518, 2, -27, 0)\r\n    invoke_custom(07990, 1, \"Mobile.setMobileVisible\", pandoraId, true)\r\n    invoke_custom(08000, 1, \"Mobile.setMobileAnimation\", pandoraId, \"AnimComp-PortailSortie\")\r\n    \r\n    ---\"Je suis arrivée juste à temps on dirait... Salut.\"\r\n    invoke_custom(09500, 1, \"bubble\", pandoraId, \"quest.osamosa.02.23\")\r\n    invoke_custom(10000, 1, \"Mobile.setMobileAnimation\", pandoraId, \"AnimComp-Reflexion\")\r\n    invoke_custom(14000, 1, \"clearBubbles\", pandoraId)\r\n    \r\n    invoke_custom(13000, 1, \"Mobile.moveMobile\", pandoraId, 4, -24, 0, \"Mobile.setMobileDirection\", pandoraId, 3)\r\n    \r\n    ---\"Ah tu es là finalement ! Je croyais que tu ne voulais pas m’accompagner.\"\r\n    invoke_custom(15000, 1, \"bubble\", playerId, \"quest.osamosa.02.24\")\r\n    invoke_custom(15000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Coucou\")\r\n    invoke_custom(21000, 1, \"clearBubbles\", playerId)\r\n    \r\n    ---\"Je ne suis pas la Pandora que tu connais. Je viens du futur.\"\r\n    invoke_custom(21500, 1, \"bubble\", pandoraId, \"quest.osamosa.02.25\")\r\n    invoke_custom(22000, 1, \"Mobile.setMobileAnimation\", pandoraId, \"AnimSort-BigOne\")\r\n    invoke_custom(27000, 1, \"clearBubbles\", pandoraId)\r\n    \r\n    ---\"Suis-moi, nous serons plus tranquilles pour parler.\"\r\n    invoke_custom(27500, 1, \"bubble\", pandoraId, \"quest.osamosa.02.26\")\r\n    invoke_custom(32000, 1, \"clearBubbles\", pandoraId)\r\n    \r\n    invoke_custom(32500, 1, \"skipCinematic\", 20962)\nend\n\n-- [EVENT] Fin de la Cinématique - on téléporte le joueur\n-- \nfunction event_2423_20963()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_2423_20958","event_2423_20959","event_2423_20960","event_2423_20961","event_2423_20962","event_2423_20963"],"quest_calls":[],"dialogue_calls":[]},"scenario/2424.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\n\n-- [INIT] Variables\n-- \nfunction event_2424_20964()\n    \nend\n\n-- [EVENT] Cinématique - Rencontre avec Osamodas (ACH 4771 OBJ 9899)\n-- \nfunction event_2424_20969()\n    local playerId = Context.getLeaderId()\r\n    \r\n    local osamodasCoquelineId = createActor(189304271, 0, -22, 0, 4, 3, 6)\r\n    local osamodasMimiId = createActor(177804141, 0, -18, 0, 4, 3, 8)\r\n    \r\n    local prespicId = createActor(123301263, -5, -15, 0, 4, 1, 5)\r\n    local boufetteId = createActor(100201513, -6, -13, 0, 4, 1, 5)\r\n    local cwabeId = createActor(132602282, -7, -17, 0, 4, 1, 5)\r\n    local tofuId = createActor(100104092, -8, -10, 0, 4, 1, 5)\r\n    local salbatroceId = createActor(132901597, -6, -20, 0, 4, 1, 5)\r\n    local fouiroxId = createActor(186604203, -4, -10, 0, 4, 1, 5)\r\n    local patapoutreId = createActor(139901804, -3, -13, 0, 4, 1, 5)\r\n    local fleogreId = createActor(1103105048, -9, -14, 0, 4, 1, 5)\r\n    local gerbichonId = createActor(1103905128, -4, -20, 0, 4, 1, 5)\r\n    local dragoeufId = createActor(186704209, -3, -18, 0, 0, 4, 1, 5)\r\n    local smareId = createActor(187704236, -9, -23, 0, 0, 4, 1, 5)\r\n    local kaskarmouleId = createActor(135701690, 3, -9, 0, 4, 5, 5)\r\n    local ratId = createActor(102800210, 6, -10, 0, 4, 5, 5)\r\n    local abraId = createActor(104800394, 8, -12, 0, 4, 5, 5)\r\n    local moskitoId = createActor(100601070, 4, -12, 0, 4, 5, 5)\r\n    local larveId = createActor(101404096, 3, -15, 0, 4, 5, 5)\r\n    local chachaId = createActor(117601642, 8, -15, 0, 4, 5, 5)\r\n    local kokokoId = createActor(135501686, 7, -18, 0, 4, 5, 5)\r\n    local corbacId = createActor(106400562, 5, -20, 0, 4, 5, 5)\r\n    local kralienId = createActor(177804163, 6, -22, 0, 4, 5, 5)\r\n    local abraknelleId = createActor(182804107, 2, -24, 0, 4, 3, 5)\r\n    local creatureId = createActor(1300006, 9, -23, 0, 4, 5, 5)\r\n    \r\n    startCinematicContext(0.5, playerId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 20969)\r\n    \r\n    invoke_custom(00001, 1, \"Mobile.setMobileVisible\", osamodasCoquelineId, false)\r\n    invoke_custom(00001, 1, \"Mobile.setMobileVisible\", osamodasMimiId, false)\r\n    invoke_custom(00001, 1, \"Mobile.setMobileMovementStyle\", playerId, \"WALK\", \"WALK\")\r\n    invoke_custom(00001, 1, \"Mobile.setMobileMovementStyle\", osamodasCoquelineId, \"WALK\", \"WALK\")\r\n    \r\n    invoke_custom(01000, 1, \"Mobile.moveMobile\", playerId, 0, -17, 0, \"Mobile.setMobileDirection\", playerId, 5)\r\n    \r\n    ---\"Toc toc toc !\"\r\n    invoke_custom(02500, 1, \"bubble\", playerId, \"quest.osamosa.03.01\")\r\n    invoke_custom(05000, 1, \"clearBubbles\", playerId)\r\n    \r\n    ---\"Je cherche le dieu Osamodas, est-ce qu’il se trouve ici ?\"\r\n    invoke_custom(06500, 1, \"bubble\", playerId, \"quest.osamosa.03.02\")\r\n    invoke_custom(12500, 1, \"clearBubbles\", playerId)\r\n    invoke_custom(10500, 1, \"Mobile.setMobileDirection\", playerId, 3)\r\n    \r\n    ---\"Si on veut\"\r\n    invoke_custom(13000, 1, \"bubble\", fleogreId, \"quest.osamosa.03.03\")\r\n    invoke_custom(15500, 1, \"clearBubbles\", fleogreId)\r\n    invoke_custom(13000, 1, 