tique\r\n    \r\n    invoke_custom(01000, 1, \"Mobile.moveMobile\", playerId, -3, -18, 0, \"Mobile.setMobileDirection\", playerId, 5)\r\n    invoke_custom(04500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Pouce\")\r\n    \r\n    -- \"J’ai connu de plus rudes combats, mais... Pas mal.\"\r\n    invoke_custom(04500, 1, \"bubble\", playerId, \"quest.osamosa.04.01\")\r\n    invoke_custom(08500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Par contre, vous devriez en faire un plus grand.\"\r\n    invoke_custom(9500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmoteMarket-HausseEpaules\")\r\n    invoke_custom(09000, 1, \"bubble\", playerId, \"quest.osamosa.04.02\")\r\n    invoke_custom(13500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Quoi\"\r\n    invoke_custom(14000, 1, \"bubble\", osamodasId, \"quest.osamosa.04.03\")\r\n    invoke_custom(15500, 1, \"clearBubbles\", osamodasId)\r\n    \r\n    -- \"Non mais... Vraiment plus grand.\"\r\n    invoke_custom(16500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Calmer\")\r\n    invoke_custom(16000, 1, \"bubble\", playerId, \"quest.osamosa.04.04\")\r\n    invoke_custom(18500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Là, il était franchement petit.\"\r\n    invoke_custom(19000, 1, \"bubble\", playerId, \"quest.osamosa.04.05\")\r\n    invoke_custom(21500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"L'idée est bonne, il faut juste faire plus grand.\"\r\n    invoke_custom(22500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Calmer\")\r\n    invoke_custom(22000, 1, \"bubble\", playerId, \"quest.osamosa.04.06\")\r\n    invoke_custom(26500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Superbe\"\r\n    invoke_custom(27000, 1, \"bubble\", osamodasId, \"quest.osamosa.04.07\")\r\n    invoke_custom(28500, 1, \"clearBubbles\", osamodasId)\r\n    \r\n    -- \"J’entends la suggestion mortel\"\r\n    invoke_custom(29000, 1, \"bubble\", osamodasId, \"quest.osamosa.04.08\")\r\n    invoke_custom(31500, 1, \"clearBubbles\", osamodasId)\r\n    \r\n    -- \"Puisses-tu vivre assez longtemps pour la voir dans le Monde des Douze\"\r\n    invoke_custom(32000, 1, \"bubble\", osamodasId, \"quest.osamosa.04.09\")\r\n    invoke_custom(36500, 1, \"clearBubbles\", osamodasId)\r\n    \r\n    -- \"Je te donne un présent\"\r\n    invoke_custom(36500, 1, \"bubble\", osamodasId, \"quest.osamosa.04.10\")\r\n    invoke_custom(40000, 1, \"clearBubbles\", osamodasId)\r\n    \r\n    -- \"Nous avons besoin de ton aide\"\r\n    invoke_custom(40000, 1, \"bubble\", osamodasId, \"quest.osamosa.04.11\")\r\n    invoke_custom(43000, 1, \"clearBubbles\", osamodasId)\r\n    \r\n    -- \"Nous ne reparlerons pas\"\r\n    invoke_custom(43000, 1, \"bubble\", osamodasId, \"quest.osamosa.04.12\")\r\n    invoke_custom(46000, 1, \"clearBubbles\", osamodasId)\r\n    \r\n    -- \"Adieu\"\r\n    invoke_custom(46000, 1, \"bubble\", osamodasId, \"quest.osamosa.04.13\")\r\n    invoke_custom(48000, 1, \"clearBubbles\", osamodasId)\r\n    \r\n    invoke_custom(48000, 1, \"skipCinematic\", 20971)\nend\n\n-- [EVENT] Fin de la Cinématique - On valide (ACH 4771 OBJ 9899)\n-- \nfunction event_2424_20972()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_2424_20964","event_2424_20969","event_2424_20970","event_2424_20971","event_2424_20972"],"quest_calls":[],"dialogue_calls":[]},"scenario/2428.lua":{"source":"\n\n-- [INIT] Variables\n-- \nfunction event_2428_21052()\n    \nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_2428_21053()\n    \nend\n\n-- [EVENT] 1 - Réceptacle Full - On rend le challenge disponible grâce à l'état de l'IE\n-- \nfunction event_2428_21054()\n    \nend\n\n-- [EVENT] 1 - Fin du challenge - On reset le Réceptacle\n-- \nfunction event_2428_21055()\n    \nend\n\n-- [EVENT] 2 - Réceptacle Full - On rend le challenge disponible grâce à l'état de l'IE\n-- \nfunction event_2428_21056()\n    \nend\n\n-- [EVENT] 2 - Fin du challenge - On reset le Réceptacle\n-- \nfunction event_2428_21057()\n    \nend\n\n-- [EVENT] 3 - Réceptacle Full - On rend le challenge disponible grâce à l'état de l'IE\n-- \nfunction event_2428_21058()\n    \nend\n\n-- [EVENT] 3 - Fin du challenge - On reset le Réceptacle\n-- \nfunction event_2428_21059()\n    \nend\n\n-- [EVENT] 4 - Réceptacle Full - On rend le challenge disponible grâce à l'état de l'IE\n-- \nfunction event_2428_21060()\n    \nend\n\n-- [EVENT] 4 - Fin du challenge - On reset le Réceptacle\n-- \nfunction event_2428_21061()\n    \nend\n\n","functions":["event_2428_21052","event_2428_21053","event_2428_21054","event_2428_21055","event_2428_21056","event_2428_21057","event_2428_21058","event_2428_21059","event_2428_21060","event_2428_21061"],"quest_calls":[],"dialogue_calls":[]},"scenario/2429.lua":{"source":"\n\n-- [INIT]\n-- \nfunction event_2429_21062()\n    \nend\n\n","functions":["event_2429_21062"],"quest_calls":[],"dialogue_calls":[]},"scenario/2430.lua":{"source":"\n\n-- [INIT]\n-- \nfunction event_2430_21063()\n    \nend\n\n","functions":["event_2430_21063"],"quest_calls":[],"dialogue_calls":[]},"scenario/2431.lua":{"source":"\n\n-- [INIT]\n-- \nfunction event_2431_21064()\n    \nend\n\n","functions":["event_2431_21064"],"quest_calls":[],"dialogue_calls":[]},"scenario/2432.lua":{"source":"\n\n-- [INIT]\n-- \nfunction event_2432_21065()\n    \nend\n\n","functions":["event_2432_21065"],"quest_calls":[],"dialogue_calls":[]},"scenario/2433.lua":{"source":"\n\n-- [INIT]\n-- \nfunction event_2433_21066()\n    \nend\n\n","functions":["event_2433_21066"],"quest_calls":[],"dialogue_calls":[]},"scenario/2434.lua":{"source":"\n\n-- [INIT]\n-- \nfunction event_2434_21067()\n    \nend\n\n","functions":["event_2434_21067"],"quest_calls":[],"dialogue_calls":[]},"scenario/2435.lua":{"source":"\n\n-- [INIT]\n-- \nfunction event_2435_21068()\n    \nend\n\n","functions":["event_2435_21068"],"quest_calls":[],"dialogue_calls":[]},"scenario/2436.lua":{"source":"\n\n-- [INIT]\n-- \nfunction event_2436_21069()\n    \nend\n\n","functions":["event_2436_21069"],"quest_calls":[],"dialogue_calls":[]},"scenario/2437.lua":{"source":"\n\n-- [INIT]\n-- \nfunction event_2437_21070()\n    \nend\n\n","functions":["event_2437_21070"],"quest_calls":[],"dialogue_calls":[]},"scenario/2438.lua":{"source":"\n\n-- [INITIALISATION] Variables\n-- \nfunction event_2438_21072()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2438_21073(randomAffixe)\n    trace(\"ENTER\", randomAffixe)\nend\n\n-- DUNGEON_DIFFICULTY_CHANGED - Refresh les Bonus Stasis + Notification sur tous les joueurs\n-- \nfunction event_2438_21074(dungeonDifficulty)\n    local difficulty = toLong(dungeonDifficulty)\r\n    \r\n    --UI.displaySplashText(\"dungeon.stasis.difficulty.changed\", difficulty)\r\n    \r\n    local bubble = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_EAST\", -75, -50, false, 10000, true, \"interactiveBubbleDialog4\")\r\n    \r\n    BubbleText.setText(bubble, \"dungeon.stasis.difficulty.changed\", difficulty)\r\n    BubbleText.show(bubble)\nend\n\n-- DUNGEON_LADDER_CANCELLED - Notification sur tous les joueurs\n-- \nfunction event_2438_21075()\n    local bubble = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_EAST\", -75, -50, false, 10000, true, \"interactiveBubbleDialog4\")\r\n    \r\n    BubbleText.setText(bubble, \"dungeon.stasis.ladder.cancelled\")\r\n    BubbleText.show(bubble)\nend\n\n-- PLAYERS_WON_FIGHT - Reroll affixe Stasis\n-- \nfunction event_2438_21076(randomAffixe)\n    trace(\"REROLL\", randomAffixe)\nend\n\n-- MONSTER_WON_FIGHT - Interdit le Spawn de Mimic\n-- \nfunction event_2438_21077()\n    \nend\n\n-- FIGHT_ENTER_ACTION_PHASE - Roll pour savoir si Spawn de Mimic\n-- \nfunction event_2438_21078()\n    \nend\n\n-- FIGHT_ENTER_ACTION_PHASE - Applique l'état Mimic sur 1 monstre aléatoire\n-- \nfunction event_2438_21079()\n    \nend\n\n-- FIGHT_ENTER_ACTION_PHASE - Applique l'état Caractéristiques Stasis sur tous les monstres\n-- \nfunction event_2438_21080()\n    \nend\n\n-- FIGHT_ENTER_ACTION_PHASE - Applique l'état Affixe Stasis rollé sur tous les monstres\n-- \nfunction event_2438_21081()\n    \nend\n\n-- #FIGHT_ENTER_ACTION_PHASE - Applique l'état Gameplay Stasis sur le Boss\n-- \nfunction event_2438_21082()\n    \nend\n\n-- ADMIN - Affixe Stasis +1\n-- \nfunction event_2438_21083(randomAffixe)\n    trace(\"AFFIX\", randomAffixe)\nend\n\n-- ADMIN - Affixe Stasis -1\n-- \nfunction event_2438_21084(randomAffixe)\n    trace(\"AFFIX\", randomAffixe)\nend\n\n","functions":["event_2438_21072","event_2438_21073","event_2438_21074","event_2438_21075","event_2438_21076","event_2438_21077","event_2438_21078","event_2438_21079","event_2438_21080","event_2438_21081","event_2438_21082","event_2438_21083","event_2438_21084"],"quest_calls":[],"dialogue_calls":[]},"scenario/2439.lua":{"source":"\n\n-- [INIT]\n-- \nfunction event_2439_21087()\n    \nend\n\n","functions":["event_2439_21087"],"quest_calls":[],"dialogue_calls":[]},"scenario/2440.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\nbubbleFightInfoId = 0\r\n\r\nfunction closeFightInfo()\r\n\tif (bubbleFightInfoId ~= nil  and bubbleFightInfoId ~= 0) then BubbleText.close(bubbleFightInfoId) end\r\nend\r\n\r\nfunction onFightInfoClosed()\r\n\tif (bubbleFightInfoId ~= nil  and bubbleFightInfoId ~= 0) then bubbleFightInfoId = 0 end\r\nend\r\n\r\nfunction updateFightInfo(score, waveEndTurn, waveCount, stasis, forceDisplayUI)\r\n\tlocal score = toLong(score)\r\n\tlocal waveEndTurn = toLong(waveEndTurn)\r\n\tlocal waveCount = toLong(waveCount)\r\n\tlocal stasis = toLong(stasis)\r\n\r\n\tif (bubbleFightInfoId == 0) then\r\n\t\tbubbleFightInfoId = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_WEST\", 0, -60, false, 2147483647, true, \"interactiveBubbleDialog5\", 30000, 25000, \"onFightInfoClosed\")\r\n\tend\r\n\r\n\tBubbleText.setText(bubbleFightInfoId, \"wave.fight.player.infos\", score, waveEndTurn, waveCount, stasis)\r\n\r\n\tif (forceDisplayUI) then BubbleText.show(bubbleFightInfoId) end\r\nend\n\n-- [INIT] Variables Globales\n-- \nfunction event_2440_21108()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2440_21109(score, waveEndTurn, waveCount, stasis)\n    updateFightInfo(score, waveEndTurn, waveCount, stasis, true)\r\n    \r\n    local bubble = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_WEST\", 0, -70, false, 2147483647, true, \"interactiveBubbleDialog5\", 30000, 25000)\r\n        \r\n    BubbleText.setText(bubble, \"wave.rewards.info\")\r\n    BubbleText.show(bubble)\nend\n\n-- [EVENT] Démarrage du combat - Pose des zones d'invocation des monstres de la vague\n-- \nfunction event_2440_21110()\n    \nend\n\n-- [EVENT] GLOBAL - Mise à jour du score - monstre tué\n-- \nfunction event_2440_21111(score, waveEndTurn, waveCount, stasis)\n    updateFightInfo(score, waveEndTurn, waveCount, stasis, true)\nend\n\n-- [EVENT] GLOBAL - Mise à jour du score - boss tué\n-- \nfunction event_2440_21112(score, waveEndTurn, waveCount, stasis)\n    updateFightInfo(score, waveEndTurn, waveCount, stasis, true)\nend\n\n-- [EVENT] GLOBAL - Mise à jour du score - vague passée\n-- \nfunction event_2440_21113(score, waveEndTurn, waveCount, stasis)\n    updateFightInfo(score, waveEndTurn, waveCount, stasis, true)\nend\n\n-- [EVENT] Activation Stèle 1 - Vandaliénés\n-- \nfunction event_2440_21114()\n    \nend\n\n-- [EVENT] Activation Stèle 2 - Cagnardeurs\n-- \nfunction event_2440_21115()\n    \nend\n\n-- [EVENT] Activation Stèle 3 - Crustargneux\n-- \nfunction event_2440_21116()\n    \nend\n\n-- [EVENT] Activation Stèle 4 - Toundrasoirs\n-- \nfunction event_2440_21117()\n    \nend\n\n-- [EVENT] Activation Stasis - 1\n-- \nfunction event_2440_21118(score, waveEndTurn, waveCount, stasis)\n    updateFightInfo(score, waveEndTurn, waveCount, stasis, true)\r\n    \r\n    Particle.addParticleSystem(1016314, 1, -3, 0)\r\n    InteractiveElement.setAnimation(32626, \"AnimStatique_1\")\nend\n\n-- [EVENT] Activation Stasis - 11\n-- \nfunction event_2440_21119(score, waveEndTurn, waveCount, stasis)\n    updateFightInfo(score, waveEndTurn, waveCount, stasis, true)\r\n    \r\n    Particle.addParticleSystem(1016314, 1, -3, 0)\r\n    InteractiveElement.setAnimation(32626, \"AnimStatique_2\")\nend\n\n-- [EVENT] Activation Stasis - 21\n-- \nfunction event_2440_21120(score, waveEndTurn, waveCount, stasis)\n    updateFightInfo(score, waveEndTurn, waveCount, stasis, true)\r\n    \r\n    Particle.addParticleSystem(1016314, 1, -3, 0)\r\n    InteractiveElement.setAnimation(32626, \"AnimStatique_2\")\nend\n\n-- [EVENT] Activation Stasis - 31\n-- \nfunction event_2440_21121(score, waveEndTurn, waveCount, stasis)\n    updateFightInfo(score, waveEndTurn, waveCount, stasis, true)\r\n    \r\n    Particle.addParticleSystem(1016314, 1, -3, 0)\r\n    InteractiveElement.setAnimation(32626, \"AnimStatique_3\")\nend\n\n-- [EVENT] Activation Stasis - 41\n-- \nfunction event_2440_21122(score, waveEndTurn, waveCount, stasis)\n    updateFightInfo(score, waveEndTurn, waveCount, stasis, true)\r\n    \r\n    Particle.addParticleSystem(1016314, 1, -3, 0)\r\n    InteractiveElement.setAnimation(32626, \"AnimStatique_3\")\nend\n\n-- [EVENT] Activation Nombre de tours - 15\n-- \nfunction event_2440_21123(score, waveEndTurn, waveCount, stasis)\n    updateFightInfo(score, waveEndTurn, waveCount, stasis, true)\r\n    \r\n    Particle.addParticleSystem(1018230, 1, -7, 0)\r\n    InteractiveElement.setAnimation(32625, \"AnimStatique_1\")\nend\n\n-- [EVENT] Activation Nombre de tours - 25\n-- \nfunction event_2440_21124(score, waveEndTurn, waveCount, stasis)\n    updateFightInfo(score, waveEndTurn, waveCount, stasis, true)\r\n    \r\n    Particle.addParticleSystem(1018230, 1, -7, 0)\r\n    InteractiveElement.setAnimation(32625, \"AnimStatique_2\")\nend\n\n-- [EVENT] Activation Nombre de tours - 35\n-- \nfunction event_2440_21125(score, waveEndTurn, waveCount, stasis)\n    updateFightInfo(score, waveEndTurn, waveCount, stasis, true)\r\n    \r\n    Particle.addParticleSystem(1018230, 1, -7, 0)\r\n    InteractiveElement.setAnimation(32625, \"AnimStatique_3\")\nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","closeFightInfo","onFightInfoClosed","updateFightInfo","event_2440_21108","event_2440_21109","event_2440_21110","event_2440_21111","event_2440_21112","event_2440_21113","event_2440_21114","event_2440_21115","event_2440_21116","event_2440_21117","event_2440_21118","event_2440_21119","event_2440_21120","event_2440_21121","event_2440_21122","event_2440_21123","event_2440_21124","event_2440_21125"],"quest_calls":[],"dialogue_calls":[]},"scenario/2441.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\napsId = 800962\r\napsOneId = 0\r\napsTwoId = 0\r\napsThreeId = 0\r\n\r\nfunction displayDoor()\r\n\tapsOneId = Particle.addParticleSystem(apsId, 12, 1, 0)\r\n\tapsTwoId = Particle.addParticleSystem(apsId, 12, 0, 0)\r\n\tapsThreeId = Particle.addParticleSystem(apsId, 12, -1, 0)\r\nend\r\n\r\nfunction hideDoor()\r\n\tParticle.removeParticleSystem(apsOneId)\r\n\tParticle.removeParticleSystem(apsTwoId)\r\n\tParticle.removeParticleSystem(apsThreeId)\r\nend\r\n\r\nfunction cameraShake()\r\n \tlocal shakeEffectId = Effect.createCameraShakeEffect(250, 500, 250, 3)\r\n \tinvoke(1000, 1, \"Effect.stopEffect\", shakeEffectId)\r\nend\r\n\r\nfunction cameraShakeViolent()\r\n \tlocal shakeEffectIdv = Effect.createCameraShakeEffect(500, 1500, 250, 5)\r\n \tinvoke(2000, 1, \"Effect.stopEffect\", shakeEffectIdv)\r\nend\r\n\r\nbubbleSteleInfoId = 0\r\n\r\nfunction closeSteleInfo()\r\n\tif (bubbleSteleInfoId ~= nil  and bubbleSteleInfoId ~= 0) then BubbleText.close(bubbleSteleInfoId) end\r\nend\r\n\r\nfunction onSteleInfoClosed()\r\n\tif (bubbleSteleInfoId ~= nil  and bubbleSteleInfoId ~= 0) then bubbleSteleInfoId = 0 end\r\nend\r\n\r\nfunction updateSteleInfo(stateInfoId, forceDisplayUI)\r\n\r\n\tif (bubbleSteleInfoId == 0) then\r\n\t\tbubbleSteleInfoId = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_WEST\", 0, -60, false, 2147483647, true, \"interactiveBubbleDialog5\", 30000, 25000, \"onSteleInfoClosed\")\r\n\tend\r\n\r\n\tBubbleText.setText(bubbleSteleInfoId, stateInfoId)\r\n\t\r\n\tif (forceDisplayUI) then BubbleText.show(bubbleSteleInfoId) end\r\nend\n\n-- [INIT] Variables & Constantes\n-- \nfunction event_2441_21138()\n    \nend\n\n-- [INIT] Application des états selon le random\n-- \nfunction event_2441_21180()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2441_21140()\n    displayDoor()\nend\n\n-- INTERACTIVE_ELEMENT_ACTIVATION - Ouverture de la porte\n-- \nfunction event_2441_21822()\n    trace(\"OUVERTURE DE LA PORTE\")\r\n    \r\n    hideDoor()\nend\n\n-- POSITION_TRIGGER - Cinématique Agonie\n-- \nfunction event_2441_21145(agonie, mobA, mobB, mobC)\n    local playerId = Context.getLeaderId()\r\n    local agonieId = toLong(agonie)\r\n    local mobAId = toLong(mobA)\r\n    local mobBId = toLong(mobB)\r\n    local mobCId = toLong(mobC)\r\n     \r\n    startCinematicContext(1.3, agonieId, 210079)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\")\r\n    \r\n    invoke_custom(1000, 1, \"bubble\", agonieId, \"dungeon.tour.agonie.cine.1\")\r\n    invoke_custom(1000, 1, \"Mobile.setMobileAnimation\", agonieId, \"AnimComp-Cine-Parler\") -- agonie se parle à elle même\r\n    \r\n    invoke_custom(5000, 1, \"bubble\", agonieId, \"dungeon.tour.agonie.cine.2\")\r\n    invoke_custom(5000, 1, \"Mobile.setMobileAnimation\", agonieId, \"AnimSort-01\") --agonie est vénère parce qu'elle est en trépamort (tape du bâton par terre, ou crie)\r\n    \r\n    invoke_custom(8000, 1, \"bubble\", agonieId, \"dungeon.tour.agonie.cine.3\")\r\n    invoke_custom(8000, 1, \"cameraShake\") --agonie remarque les joueurs, shake caméra pour accentuer\n    invoke_custom(08000, 1, \"Sound.playSound\", 502000005005)\r\n    \r\n    invoke_custom(11000, 1, \"bubble\", agonieId, \"dungeon.tour.agonie.cine.4\")\r\n    invoke_custom(11000, 1, \"Mobile.setMobileAnimation\", agonieId, \"AnimComp-Cine-Doigt\") --agonie pointe du doigt les joueurs\r\n    \r\n    invoke_custom(17000, 1, \"bubble\", agonieId, \"dungeon.tour.agonie.cine.5\")\r\n    invoke_custom(17000, 1, \"Mobile.setMobileAnimation\", agonieId, \"AnimComp-Cine-Parler\")\r\n    \r\n    invoke_custom(20700, 1, \"bubble\", agonieId, \"dungeon.tour.agonie.cine.6\")\r\n    invoke_custom(21000, 1, \"Mobile.setMobileAnimation\", agonieId, \"AnimComp-Cine-Enerve\") --agonie taunt les joueurs/les incite à venir se faire maraver (anim crier ou bâton fort)\r\n    invoke_custom(21000, 1, \"cameraShakeViolent\") --shake un peu plus violent pour appuyer son rire\n    invoke_custom(21000, 1, \"Sound.playSound\", 502000005005)\r\n    \r\n    invoke_custom(24000, 1, \"skipCinematic\")\nend\n\n-- [FIGHT] Lancement du combat - Action sur Agonie\n-- on skippe la cinématique pour tout le monde \nfunction event_2441_21146()\n    skipCinematic()\nend\n\n-- [FIGHT] Démarrage du combat - Pose zones flags des Cristaux\n-- \nfunction event_2441_21148()\n    trace(\"FIGHT_STARTED\")\nend\n\n-- [FIGHT] Fin du combat  - Rend les monstres inattaquables\n-- \nfunction event_2441_21150()\n    \nend\n\n-- [FIGHT] Défaite du combat - Reset les stèles\n-- \nfunction event_2441_21175()\n    \nend\n\n-- [STELE] Le joueur examine une stèle\n-- \nfunction event_2441_21168(steleCount, steleStateId)\n    local steleCount = toLong(steleCount)\r\n    local steleStateId = toLong(steleStateId)\r\n    \r\n    if (steleCount == 0) then\r\n    UI.openRewardsDialog(\"stele.description.tour\")\r\n    UI.addReward(24305)\r\n    UI.addReward(24307)\r\n    UI.addReward(24308)\r\n    UI.addReward(24310, \"stele.reward.stasis.21\")\r\n    \r\n    elseif (steleCount == 1) then\r\n    UI.openRewardsDialog(\"stele.description.tour\")\r\n    UI.addReward(24324)\r\n    UI.addReward(24325)\r\n    UI.addReward(24328)\r\n    UI.addReward(24330, \"stele.reward.stasis.21\")\r\n    \r\n    elseif (steleCount == 2) then\r\n    UI.openRewardsDialog(\"stele.description.tour\")\r\n    UI.addReward(24312, \"stele.reward.stasis.21\")\r\n    UI.addReward(24313, \"stele.reward.stasis.21\")\r\n    UI.addReward(24315, \"stele.reward.stasis.21\")\r\n    UI.addReward(24333, \"stele.reward.stasis.21\")\r\n    \r\n    elseif (steleCount == 3) then\r\n    UI.openRewardsDialog(\"stele.description.tour\")\r\n    UI.addReward(24326)\r\n    UI.addReward(24327)\r\n    UI.addReward(24311, \"stele.reward.stasis.21\")\r\n    UI.addReward(24314, \"stele.reward.stasis.21\")\r\n    \r\n    else\r\n    \r\n    end\r\n    \r\n    local stateInfoId = \"stele.state.description.\" .. toString(steleStateId)\r\n    \r\n    updateSteleInfo(stateInfoId, true)\nend\n\n-- [STELE] Le joueur active une stèle\n-- \nfunction event_2441_21171(steleCount)\n    local steleCount = toLong(steleCount)\r\n    \r\n    if (steleCount == 1) then\r\n    UI.openRewardsDialog(\"stele.description.tour\")\r\n    UI.addReward(24305)\r\n    UI.addReward(24307)\r\n    UI.addReward(24308)\r\n    UI.addReward(24310, \"stele.reward.stasis.21\")\r\n    \r\n    elseif (steleCount == 2) then\r\n    UI.openRewardsDialog(\"stele.description.tour\")\r\n    UI.addReward(24324)\r\n    UI.addReward(24325)\r\n    UI.addReward(24328)\r\n    UI.addReward(24330, \"stele.reward.stasis.21\")\r\n    \r\n    elseif (steleCount == 3) then\r\n    UI.openRewardsDialog(\"stele.description.tour\")\r\n    UI.addReward(24312, \"stele.reward.stasis.21\")\r\n    UI.addReward(24313, \"stele.reward.stasis.21\")\r\n    UI.addReward(24315, \"stele.reward.stasis.21\")\r\n    UI.addReward(24333, \"stele.reward.stasis.21\")\r\n    \r\n    elseif (steleCount == 4) then\r\n    UI.openRewardsDialog(\"stele.description.tour\")\r\n    UI.addReward(24326)\r\n    UI.addReward(24327)\r\n    UI.addReward(24311, \"stele.reward.stasis.21\")\r\n    UI.addReward(24314, \"stele.reward.stasis.21\")\r\n    \r\n    else\r\n    \r\n    end\nend\n\n-- [STELE] Refresh des APS pour Stèles\n-- \nfunction event_2441_21174()\n    \nend\n\n-- DUNGEON_DIFFICULTY_CHANGED - Reset les stèles\n-- \nfunction event_2441_21179()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","displayDoor","hideDoor","cameraShake","cameraShakeViolent","closeSteleInfo","onSteleInfoClosed","updateSteleInfo","event_2441_21138","event_2441_21180","event_2441_21140","event_2441_21822","event_2441_21145","event_2441_21146","event_2441_21148","event_2441_21150","event_2441_21175","event_2441_21168","event_2441_21171","event_2441_21174","event_2441_21179"],"quest_calls":["UI.openRewardsDialog(\"stele.description.tour\")\r","UI.openRewardsDialog(\"stele.description.tour\")\r","UI.openRewardsDialog(\"stele.description.tour\")\r","UI.openRewardsDialog(\"stele.description.tour\")\r","UI.openRewardsDialog(\"stele.description.tour\")\r","UI.openRewardsDialog(\"stele.description.tour\")\r","UI.openRewardsDialog(\"stele.description.tour\")\r","UI.openRewardsDialog(\"stele.description.tour\")\r"],"dialogue_calls":[]},"scenario/2442.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\napsId = 800963\r\napsOneId = 0\r\napsTwoId = 0\r\napsThreeId = 0\r\n\r\nfunction displayDoor()\r\n\tapsOneId = Particle.addParticleSystem(apsId, 12, 1, 0)\r\n\tapsTwoId = Particle.addParticleSystem(apsId, 12, 0, 0)\r\n\tapsThreeId = Particle.addParticleSystem(apsId, 12, -1, 0)\r\nend\r\n\r\nfunction hideDoor()\r\n\tParticle.removeParticleSystem(apsOneId)\r\n\tParticle.removeParticleSystem(apsTwoId)\r\n\tParticle.removeParticleSystem(apsThreeId)\r\nend\r\n\r\nfunction cameraShake()\r\n \tlocal shakeEffectId = Effect.createCameraShakeEffect(250, 500, 250, 3)\r\n \tinvoke(1000, 1, \"Effect.stopEffect\", shakeEffectId)\r\nend\r\n\r\nfunction cameraShakeViolent()\r\n \tlocal shakeEffectIdv = Effect.createCameraShakeEffect(500, 1500, 250, 5)\r\n \tinvoke(2000, 1, \"Effect.stopEffect\", shakeEffectIdv)\r\nend\r\n\r\nbubbleSteleInfoId = 0\r\n\r\nfunction closeSteleInfo()\r\n\tif (bubbleSteleInfoId ~= nil  and bubbleSteleInfoId ~= 0) then BubbleText.close(bubbleSteleInfoId) end\r\nend\r\n\r\nfunction onSteleInfoClosed()\r\n\tif (bubbleSteleInfoId ~= nil  and bubbleSteleInfoId ~= 0) then bubbleSteleInfoId = 0 end\r\nend\r\n\r\nfunction updateSteleInfo(stateInfoId, forceDisplayUI)\r\n\r\n\tif (bubbleSteleInfoId == 0) then\r\n\t\tbubbleSteleInfoId = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_WEST\", 0, -60, false, 2147483647, true, \"interactiveBubbleDialog5\", 30000, 25000, \"onSteleInfoClosed\")\r\n\tend\r\n\r\n\tBubbleText.setText(bubbleSteleInfoId, stateInfoId)\r\n\t\r\n\tif (forceDisplayUI) then BubbleText.show(bubbleSteleInfoId) end\r\nend\n\n-- [INIT] Variables & Constantes\n-- \nfunction event_2442_21181()\n    \nend\n\n-- [INIT] Application des états selon le random\n-- \nfunction event_2442_21182()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2442_21183()\n    displayDoor()\nend\n\n-- INTERACTIVE_ELEMENT_ACTIVATION - Ouverture de la porte\n-- \nfunction event_2442_21823()\n    trace(\"OUVERTURE DE LA PORTE\")\r\n    \r\n    hideDoor()\nend\n\n-- POSITION_TRIGGER - Cinématique Agonie\n-- \nfunction event_2442_21184(agonie, mobA, mobB, mobC)\n    local playerId = Context.getLeaderId()\r\n    local agonieId = toLong(agonie)\r\n    local mobAId = toLong(mobA)\r\n    local mobBId = toLong(mobB)\r\n    local mobCId = toLong(mobC)\r\n     \r\n    startCinematicContext(1.3, agonieId, 210079)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\")\r\n    \r\n    invoke_custom(1000, 1, \"bubble\", agonieId, \"dungeon.tour.agonie.cine.1\")\r\n    invoke_custom(1000, 1, \"Mobile.setMobileAnimation\", agonieId, \"AnimComp-Cine-Parler\") -- agonie se parle à elle même\r\n    \r\n    invoke_custom(5000, 1, \"bubble\", agonieId, \"dungeon.tour.agonie.cine.2\")\r\n    invoke_custom(5000, 1, \"Mobile.setMobileAnimation\", agonieId, \"AnimSort-01\") --agonie est vénère parce qu'elle est en trépamort (tape du bâton par terre, ou crie)\r\n    \r\n    invoke_custom(8000, 1, \"bubble\", agonieId, \"dungeon.tour.agonie.cine.3\")\r\n    invoke_custom(8000, 1, \"cameraShake\") --agonie remarque les joueurs, shake caméra pour accentuer\n    invoke_custom(08000, 1, \"Sound.playSound\", 502000005005)\r\n    \r\n    invoke_custom(11000, 1, \"bubble\", agonieId, \"dungeon.tour.agonie.cine.4\")\r\n    invoke_custom(11000, 1, \"Mobile.setMobileAnimation\", agonieId, \"AnimComp-Cine-Doigt\") --agonie pointe du doigt les joueurs\r\n    \r\n    invoke_custom(17000, 1, \"bubble\", agonieId, \"dungeon.tour.agonie.cine.5\")\r\n    invoke_custom(17000, 1, \"Mobile.setMobileAnimation\", agonieId, \"AnimComp-Cine-Parler\")\r\n    \r\n    invoke_custom(20700, 1, \"bubble\", agonieId, \"dungeon.tour.agonie.cine.6\")\r\n    invoke_custom(21000, 1, \"Mobile.setMobileAnimation\", agonieId, \"AnimComp-Cine-Enerve\") --agonie taunt les joueurs/les incite à venir se faire maraver (anim crier ou bâton fort)\r\n    invoke_custom(21000, 1, \"cameraShakeViolent\") --shake un peu plus violent pour appuyer son rire\n    invoke_custom(21000, 1, \"Sound.playSound\", 502000005005)\r\n    \r\n    invoke_custom(24000, 1, \"skipCinematic\")\nend\n\n-- [FIGHT] Lancement du combat - Action sur Agonie\n-- on skippe la cinématique pour tout le monde \nfunction event_2442_21185()\n    skipCinematic()\nend\n\n-- [FIGHT] Démarrage du combat - Pose zones flags des Cristaux\n-- \nfunction event_2442_21186()\n    trace(\"FIGHT_STARTED\")\nend\n\n-- [FIGHT] Fin du combat  - Rend les monstres inattaquables\n-- \nfunction event_2442_21187()\n    \nend\n\n-- [FIGHT] Défaite du combat - Reset les stèles\n-- \nfunction event_2442_21188()\n    \nend\n\n-- [STELE] Le joueur examine une stèle\n-- \nfunction event_2442_21189(steleCount, steleStateId)\n    local steleCount = toLong(steleCount)\r\n    local steleStateId = toLong(steleStateId)\r\n    \r\n    if (steleCount == 0) then\r\n    UI.openRewardsDialog(\"stele.description.tour\")\r\n    UI.addReward(24731)\r\n    UI.addReward(24732)\r\n    UI.addReward(24715)\r\n    UI.addReward(24721, \"stele.reward.stasis.21\")\r\n    \r\n    elseif (steleCount == 1) then\r\n    UI.openRewardsDialog(\"stele.description.tour\")\r\n    UI.addReward(24716)\r\n    UI.addReward(24717)\r\n    UI.addReward(24723, \"stele.reward.stasis.21\")\r\n    UI.addReward(24737, \"stele.reward.stasis.21\")\r\n    \r\n    elseif (steleCount == 2) then\r\n    UI.openRewardsDialog(\"stele.description.tour\")\r\n    UI.addReward(24719, \"stele.reward.stasis.21\")\r\n    UI.addReward(24720, \"stele.reward.stasis.21\")\r\n    UI.addReward(24722, \"stele.reward.stasis.21\")\r\n    UI.addReward(24734, \"stele.reward.stasis.21\")\r\n    \r\n    elseif (steleCount == 3) then\r\n    UI.openRewardsDialog(\"stele.description.tour\")\r\n    UI.addReward(24735, \"stele.reward.stasis.21\")\r\n    UI.addReward(24736, \"stele.reward.stasis.21\")\r\n    UI.addReward(24724, \"stele.reward.stasis.21\")\r\n    UI.addReward(24725, \"stele.reward.stasis.21\")\r\n    \r\n    else\r\n    \r\n    end\r\n    \r\n    local stateInfoId = \"stele.state.description.\" .. toString(steleStateId)\r\n    \r\n    updateSteleInfo(stateInfoId, true)\nend\n\n-- [STELE] Le joueur active une stèle\n-- \nfunction event_2442_21190(steleCount)\n    local steleCount = toLong(steleCount)\r\n    \r\n    if (steleCount == 1) then\r\n    UI.openRewardsDialog(\"stele.description.tour\")\r\n    UI.addReward(24731)\r\n    UI.addReward(24732)\r\n    UI.addReward(24715)\r\n    UI.addReward(24721, \"stele.reward.stasis.21\")\r\n    \r\n    elseif (steleCount == 2) then\r\n    UI.openRewardsDialog(\"stele.description.tour\")\r\n    UI.addReward(24716)\r\n    UI.addReward(24717)\r\n    UI.addReward(24723, \"stele.reward.stasis.21\")\r\n    UI.addReward(24737, \"stele.reward.stasis.21\")\r\n    \r\n    elseif (steleCount == 3) then\r\n    UI.openRewardsDialog(\"stele.description.tour\")\r\n    UI.addReward(24719, \"stele.reward.stasis.21\")\r\n    UI.addReward(24720, \"stele.reward.stasis.21\")\r\n    UI.addReward(24722, \"stele.reward.stasis.21\")\r\n    UI.addReward(24734, \"stele.reward.stasis.21\")\r\n    \r\n    elseif (steleCount == 4) then\r\n    UI.openRewardsDialog(\"stele.description.tour\")\r\n    UI.addReward(24735, \"stele.reward.stasis.21\")\r\n    UI.addReward(24736, \"stele.reward.stasis.21\")\r\n    UI.addReward(24724, \"stele.reward.stasis.21\")\r\n    UI.addReward(24725, \"stele.reward.stasis.21\")\r\n    \r\n    else\r\n    \r\n    end\nend\n\n-- [STELE] Refresh des APS pour Stèles\n-- \nfunction event_2442_21191()\n    \nend\n\n-- DUNGEON_DIFFICULTY_CHANGED - Reset les stèles\n-- \nfunction event_2442_21192()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","displayDoor","hideDoor","cameraShake","cameraShakeViolent","closeSteleInfo","onSteleInfoClosed","updateSteleInfo","event_2442_21181","event_2442_21182","event_2442_21183","event_2442_21823","event_2442_21184","event_2442_21185","event_2442_21186","event_2442_21187","event_2442_21188","event_2442_21189","event_2442_21190","event_2442_21191","event_2442_21192"],"quest_calls":["UI.openRewardsDialog(\"stele.description.tour\")\r","UI.openRewardsDialog(\"stele.description.tour\")\r","UI.openRewardsDialog(\"stele.description.tour\")\r","UI.openRewardsDialog(\"stele.description.tour\")\r","UI.openRewardsDialog(\"stele.description.tour\")\r","UI.openRewardsDialog(\"stele.description.tour\")\r","UI.openRewardsDialog(\"stele.description.tour\")\r","UI.openRewardsDialog(\"stele.description.tour\")\r"],"dialogue_calls":[]},"scenario/2443.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\napsId = 800964\r\napsOneId = 0\r\napsTwoId = 0\r\napsThreeId = 0\r\n\r\nfunction displayDoor()\r\n\tapsOneId = Particle.addParticleSystem(apsId, 12, 1, 0)\r\n\tapsTwoId = Particle.addParticleSystem(apsId, 12, 0, 0)\r\n\tapsThreeId = Particle.addParticleSystem(apsId, 12, -1, 0)\r\nend\r\n\r\nfunction hideDoor()\r\n\tParticle.removeParticleSystem(apsOneId)\r\n\tParticle.removeParticleSystem(apsTwoId)\r\n\tParticle.removeParticleSystem(apsThreeId)\r\nend\r\n\r\nfunction cameraShake()\r\n \tlocal shakeEffectId = Effect.createCameraShakeEffect(250, 500, 250, 3)\r\n \tinvoke(1000, 1, \"Effect.stopEffect\", shakeEffectId)\r\nend\r\n\r\nfunction cameraShakeViolent()\r\n \tlocal shakeEffectIdv = Effect.createCameraShakeEffect(500, 1500, 250, 5)\r\n \tinvoke(2000, 1, \"Effect.stopEffect\", shakeEffectIdv)\r\nend\r\n\r\nbubbleSteleInfoId = 0\r\n\r\nfunction closeSteleInfo()\r\n\tif (bubbleSteleInfoId ~= nil  and bubbleSteleInfoId ~= 0) then BubbleText.close(bubbleSteleInfoId) end\r\nend\r\n\r\nfunction onSteleInfoClosed()\r\n\tif (bubbleSteleInfoId ~= nil  and bubbleSteleInfoId ~= 0) then bubbleSteleInfoId = 0 end\r\nend\r\n\r\nfunction updateSteleInfo(stateInfoId, forceDisplayUI)\r\n\r\n\tif (bubbleSteleInfoId == 0) then\r\n\t\tbubbleSteleInfoId = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_WEST\", 0, -60, false, 2147483647, true, \"interactiveBubbleDialog5\", 30000, 25000, \"onSteleInfoClosed\")\r\n\tend\r\n\r\n\tBubbleText.setText(bubbleSteleInfoId, stateInfoId)\r\n\t\r\n\tif (forceDisplayUI) then BubbleText.show(bubbleSteleInfoId) end\r\nend\n\n-- [INIT] Variables & Constantes\n-- \nfunction event_2443_21193()\n    \nend\n\n-- [INIT] Application des états selon le random\n-- \nfunction event_2443_21194()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2443_21195(agonie)\n    agonieId = toLong(agonie)\r\n    Mobile.setMobileDirection(agonie, 1)\r\n    \r\n    displayDoor()\nend\n\n-- GENERIC_ACTIVABLE_ACTIVATION - Ouverture de la porte\n-- \nfunction event_2443_21824()\n    trace(\"OUVERTURE DE LA PORTE\")\r\n    \r\n    hideDoor()\nend\n\n-- POSITION_TRIGGER - Cinématique Agonie\n-- \nfunction event_2443_21196(agonie, mobA, mobB, mobC)\n    local playerId = Context.getLeaderId()\r\n    local agonieId = toLong(agonie)\r\n    local mobAId = toLong(mobA)\r\n    local mobBId = toLong(mobB)\r\n    local mobCId = toLong(mobC)\r\n     \r\n    startCinematicContext(1.3, agonieId, 210079)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\")\r\n    \r\n    -- \"Raval !!!\"\r\n    invoke_custom(01000, 1, \"bubble\", agonieId, \"dungeon.tour.agonie.cine.215.01\")\r\n    invoke_custom(01000, 1, \"Sound.playSound\", 90031604)\r\n    \r\n    -- \"Tu paieras cher pour m'avoir emprisonnée !\"\r\n    invoke_custom(04000, 1, \"bubble\", agonieId, \"dungeon.tour.agonie.cine.215.02\")\r\n    invoke_custom(04000, 1, \"Sound.playSound\", 90031605)\r\n    \r\n    -- \"Ma puissance et celle des Trépamorts grandit chaque jour...\"\r\n    invoke_custom(08000, 1, \"bubble\", agonieId, \"dungeon.tour.agonie.cine.215.03\")\r\n    invoke_custom(08000, 1, \"Sound.playSound\", 90031606)\r\n    invoke_custom(08000, 1, \"Sound.playSound\", 502000005005)\r\n    invoke_custom(08000, 1, \"cameraShake\")\r\n    \r\n    -- \"J'aurai ma VENGEANCE !!!\"\r\n    invoke_custom(13000, 1, \"bubble\", agonieId, \"dungeon.tour.agonie.cine.215.04\")\r\n    invoke_custom(13000, 1, \"Sound.playSound\", 90031605)\r\n    invoke_custom(13000, 1, \"Sound.playSound\", 502000005005)\r\n    invoke_custom(13000, 1, \"cameraShake\")\r\n    \r\n    -- \"Je sens que l'heure de ma libération est proche ! Je vais commencer par vous...\"\r\n    invoke_custom(17000, 1, \"bubble\", agonieId, \"dungeon.tour.agonie.cine.215.05\")\r\n    invoke_custom(17000, 1, \"Sound.playSound\", 90031604)\r\n    invoke_custom(21000, 1, \"Sound.playSound\", 502000005005)\r\n    invoke_custom(21000, 1, \"cameraShakeViolent\") --shake un peu plus violent pour appuyer son rire\r\n    \r\n    invoke_custom(24000, 1, \"skipCinematic\")\nend\n\n-- [FIGHT] Lancement du combat - Action sur Agonie\n-- on skippe la cinématique pour tout le monde \nfunction event_2443_21197()\n    skipCinematic()\nend\n\n-- [FIGHT] Démarrage du combat - Pose zones flags des Cristaux\n-- \nfunction event_2443_21198()\n    trace(\"FIGHT_STARTED\")\nend\n\n-- [FIGHT] Fin du combat  - Rend les monstres inattaquables\n-- \nfunction event_2443_21199(agonie)\n    agonieId = toLong(agonie)\r\n    Mobile.setMobileDirection(agonie, 1)\nend\n\n-- [FIGHT] Défaite du combat - Reset les stèles\n-- \nfunction event_2443_21200()\n    \nend\n\n-- [STELE] Le joueur examine une stèle\n-- \nfunction event_2443_21201(steleCount, steleStateId)\n    local steleCount = toLong(steleCount)\r\n    local steleStateId = toLong(steleStateId)\r\n    \r\n    if (steleCount == 0) then\r\n    rewardOneId = 28064\r\n    rewardTwoId = 28076\r\n    rewardThreeId = 28091\r\n    rewardFourId = 28088\r\n    \r\n    elseif (steleCount == 1) then\r\n    rewardOneId = 28067\r\n    rewardTwoId = 28078\r\n    rewardThreeId = 28092\r\n    rewardFourId = 28089\r\n    \r\n    elseif (steleCount == 2) then\r\n    rewardOneId = 28070\r\n    rewardTwoId = 28080\r\n    rewardThreeId = 28093\r\n    rewardFourId = 28097\r\n    \r\n    elseif (steleCount == 3) then\r\n    rewardOneId = 28073\r\n    rewardTwoId = 28082\r\n    rewardThreeId = 28094\r\n    rewardFourId = 28090\r\n    \r\n    else\r\n    rewardOneId = 0\r\n    rewardTwoId = 0\r\n    rewardThreeId = 0\r\n    rewardFourId = 0\r\n    \r\n    end\r\n    \r\n    UI.openRewardsDialog(\"stele.description.tour\")\r\n    UI.addReward(rewardOneId)\r\n    UI.addReward(rewardTwoId)\r\n    UI.addReward(rewardThreeId, \"stele.reward.stasis.21\")\r\n    UI.addReward(rewardFourId, \"stele.reward.stasis.21\")\r\n    \r\n    local stateInfoId = \"stele.state.description.\" .. toString(steleStateId)\r\n    \r\n    updateSteleInfo(stateInfoId, true)\nend\n\n-- [STELE] Le joueur active une stèle\n-- \nfunction event_2443_21202(steleCount)\n    local steleCount = toLong(steleCount)\r\n    \r\n    if (steleCount == 1) then\r\n    rewardOneId = 28064\r\n    rewardTwoId = 28076\r\n    rewardThreeId = 28091\r\n    rewardFourId = 28088\r\n    \r\n    elseif (steleCount == 2) then\r\n    rewardOneId = 28067\r\n    rewardTwoId = 28078\r\n    rewardThreeId = 28092\r\n    rewardFourId = 28089\r\n    \r\n    elseif (steleCount == 3) then\r\n    rewardOneId = 28070\r\n    rewardTwoId = 28080\r\n    rewardThreeId = 28093\r\n    rewardFourId = 28097\r\n    \r\n    elseif (steleCount == 4) then\r\n    rewardOneId = 28073\r\n    rewardTwoId = 28082\r\n    rewardThreeId = 28094\r\n    rewardFourId = 28090\r\n    \r\n    else\r\n    rewardOneId = 0\r\n    rewardTwoId = 0\r\n    rewardThreeId = 0\r\n    rewardFourId = 0\r\n    \r\n    end\r\n    \r\n    UI.openRewardsDialog(\"stele.description.tour\")\r\n    UI.addReward(rewardOneId)\r\n    UI.addReward(rewardTwoId)\r\n    UI.addReward(rewardThreeId, \"stele.reward.stasis.21\")\r\n    UI.addReward(rewardFourId, \"stele.reward.stasis.21\")\nend\n\n-- [STELE] Refresh des APS pour Stèles\n-- \nfunction event_2443_21203()\n    \nend\n\n-- DUNGEON_DIFFICULTY_CHANGED - Reset les stèles\n-- \nfunction event_2443_21204()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","displayDoor","hideDoor","cameraShake","cameraShakeViolent","closeSteleInfo","onSteleInfoClosed","updateSteleInfo","event_2443_21193","event_2443_21194","event_2443_21195","event_2443_21824","event_2443_21196","event_2443_21197","event_2443_21198","event_2443_21199","event_2443_21200","event_2443_21201","event_2443_21202","event_2443_21203","event_2443_21204"],"quest_calls":["UI.openRewardsDialog(\"stele.description.tour\")\r","UI.openRewardsDialog(\"stele.description.tour\")\r"],"dialogue_calls":[]},"scenario/2444.lua":{"source":"\n\n-- [INIT] Variables Globales\n-- \nfunction event_2444_21208()\n    \nend\n\n-- [INIT] Inscription du joueur + Variables Locales\n-- \nfunction event_2444_21209(room)\n    \nend\n\n-- USER_GROUP_KILLED - Salle 01\n-- \nfunction event_2444_21211(room)\n    \nend\n\n-- USER_GROUP_KILLED - Salle 02 - BOSS\n-- \nfunction event_2444_21212()\n    \nend\n\n-- Déplace le joueur vers la salle suivante\n-- \nfunction event_2444_21213()\n    \nend\n\n-- FIGHT_ENTER_ACTION_PHASE - Invocation du Tortumulus Salle 1\n-- \nfunction event_2444_21930()\n    \nend\n\n-- FIGHT_ENTER_ACTION_PHASE - Invocation du Tortumulus Salle du Boss\n-- \nfunction event_2444_21931()\n    \nend\n\n-- [STELE] FIGHT_STARTED - On applique les difficultés sur le boss\n-- \nfunction event_2444_22856()\n    \nend\n\n-- [STELE] FIGHT_ENTER_ACTION_PHASE - On applique les bonus sur les joueurs\n-- \nfunction event_2444_22857()\n    \nend\n\n-- [STELE] FIGHT_ENDED - On rend la stèle utilisable en cas de défaite\n-- \nfunction event_2444_22899()\n    \nend\n\n-- [ARCHI] Apparition de l'Archimonstre\n-- \nfunction event_2444_24016()\n    \nend\n\n","functions":["event_2444_21208","event_2444_21209","event_2444_21211","event_2444_21212","event_2444_21213","event_2444_21930","event_2444_21931","event_2444_22856","event_2444_22857","event_2444_22899","event_2444_24016"],"quest_calls":[],"dialogue_calls":[]},"scenario/2445.lua":{"source":"\n\n-- [INITIALISATION] Le joueur entre dans l'instance - Inscription au scénario\n-- \nfunction event_2445_21217()\n    \nend\n\n-- [EVENT] On lance un combat contre un groupe de Carapattes\n-- \nfunction event_2445_21216()\n    \nend\n\n-- [EVENT] Les Carapattes sont vaincus\n-- \nfunction event_2445_21218()\n    \nend\n\n","functions":["event_2445_21217","event_2445_21216","event_2445_21218"],"quest_calls":[],"dialogue_calls":[]},"scenario/2446.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\n-- les fonctions où on cache\r\nfunction hideMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, false)\r\nend\r\n\r\nfunction hidePart(monsterMobileId, partName)\r\n\tMobile.setPartVisible(monsterMobileId, false, partName)\r\nend\r\n\r\n-- les fonctions où on rend visible (à nouveau)\r\nfunction showMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, true)\r\nend\r\n\r\nfunction showPart(monsterMobileId, partName)\r\n\tMobile.setPartVisible(monsterMobileId, true, partName)\r\nend\n\n-- [INITIALISATION] Serveur\n-- \nfunction event_2446_21220()\n    \nend\n\n-- [EVENT] Le joueur entre sur la map, on cache Pandora\n-- \nfunction event_2446_21222(pandora)\n    Mobile.addMobileCreationCallback(pandora, \"hideMonster\", pandora)\nend\n\n-- [EVENT] Le joueur efface un spot de peinture (variable nbChuchoteurPaintErased)\n-- \nfunction event_2446_21223()\n    \nend\n\n-- [EVENT] On lance un combat contre le Chuchamp de Tir\n-- \nfunction event_2446_21405()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","hideMonster","hidePart","showMonster","showPart","event_2446_21220","event_2446_21222","event_2446_21223","event_2446_21405"],"quest_calls":[],"dialogue_calls":[]},"scenario/2447.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\n\n-- [INIT] Variables\n-- \nfunction event_2447_21225()\n    \nend\n\n-- [EVENT] ENTER_INSTANCE - Cinématique\n-- \nfunction event_2447_21224(bossId)\n    local playerId = Context.getLeaderId()\r\n    local bossId = toLong(bossId)\r\n     \r\n    startCinematicContext(1.3, bossId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 21224)\r\n    \r\n    -- \"On dirait que les chuchoteurs sont en train de préparer quelque chose...\"\r\n    invoke_custom(01000, 1, \"bubble\", playerId, \"quest.chuchoteur.01.01\")\r\n    invoke_custom(01000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Pointer\")\r\n    \r\n    -- \"Ils sont en train d'asservir des craqueleurs !\"\r\n    invoke_custom(06000, 1, \"bubble\", playerId, \"quest.chuchoteur.01.02\")\r\n    invoke_custom(06000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Effrayee\")\r\n    \r\n    -- \"**Psshh pshhh pssshhh\"\r\n    invoke_custom(10000, 1, \"bubble\", bossId, \"quest.chuchoteur.01.03\")\r\n    invoke_custom(10000, 1, \"Mobile.setMobileAnimation\", bossId, \"AnimSort-Soin\")\r\n    \r\n    -- \"Désolé{[1*]?e:}, mais je n'entends rien.\"\r\n    invoke_custom(13000, 1, \"bubble\", playerId, \"quest.chuchoteur.01.04\")\r\n    invoke_custom(13000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Non\")\r\n    \r\n    -- \"Je suis obligé{[1*]?e:} de vous faire répéter plus fort !\"\r\n    invoke_custom(16000, 1, \"bubble\", playerId, \"quest.chuchoteur.01.05\")\r\n    invoke_custom(16000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Colere\")\r\n    \r\n    invoke_custom(20000, 1, \"skipCinematic\", 21224)\nend\n\n-- [EVENT] Fin de la cinématique - Activation du MRU sur le monstre\n-- \nfunction event_2447_21229()\n    \nend\n\n-- [FIGHT] Lancement du combat\n-- on skippe la cinématique pour tout le monde \nfunction event_2447_21230()\n    skipCinematic()\nend\n\n-- [EVENT] Le joueur gagne - Le coffre apparait\n-- \nfunction event_2447_21228()\n    local playerId = Context.getLeaderId()\r\n    \r\n    invoke(0, 1, \"Particle.addParticleSystem\", 800202, -11, -7, 0, 0)\r\n    \r\n    -- \"Et voilà le travail.\"\r\n    invoke(1000, 1, \"bubble\", playerId, \"quest.chuchoteur.01.06\")\nend\n\n-- [COFFRE] Le joueur a les ordres du roi\n-- \nfunction event_2447_21226()\n    UI.writeLocalisedInChat(\"quest.chuchoteur.kingorders\")\nend\n\n-- [COFFRE] Le joueur n'a pas les ordres du roi\n-- \nfunction event_2447_21227()\n    InteractiveElement.setAnimation(32856,\"AnimTrans_1_3_1\")\r\n    \r\n    path = Pixmap.getItemPath(28736)\r\n    invoke(500, 1, \"Flying.addFlyingImageIE\", 32856, path)\nend\n\n-- Lancement d'un combat\n-- \nfunction event_2447_21231()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_2447_21225","event_2447_21224","event_2447_21229","event_2447_21230","event_2447_21228","event_2447_21226","event_2447_21227","event_2447_21231"],"quest_calls":[],"dialogue_calls":[]},"scenario/2448.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\n\n-- [INIT] Variables Globales\n-- \nfunction event_2448_21232()\n    \nend\n\n-- [INIT] Inscription du joueur + Variables Locales\n-- \nfunction event_2448_21233(room)\n    \nend\n\n-- *[OLD][1] Victoire - Déverrouille le passage vers S2\n-- \nfunction event_2448_21234(room)\n    \nend\n\n-- USER_GROUP_KILLED - Salle 01\n-- \nfunction event_2448_21235(room)\n    \nend\n\n-- USER_GROUP_KILLED - Salle 02 - BOSS\n-- \nfunction event_2448_21236()\n    \nend\n\n-- Déplace le joueur vers la salle suivante\n-- \nfunction event_2448_21237()\n    \nend\n\n-- [EVENT] Le joueur marche sur un position trigger - Cinématique\n-- \nfunction event_2448_21238(boss)\n    local playerId = Context.getLeaderId()\r\n    local bossId = toLong(boss)\r\n    \r\n    startCinematicContext(1.2, bossId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 21238)\r\n    \r\n    invoke_custom(00100, 1, \"Mobile.moveMobile\", playerId, -18, -75, 16, \"Mobile.setMobileDirection\", playerId, 7)\r\n    \r\n    -- \"Hah ! Voilà des aventuriers de pacotille !\"\r\n    invoke_custom(02000, 1, \"bubble\", bossId, \"quest.chuchoku.mercenary.02.04\")\r\n    invoke_custom(05000, 1, \"clearBubbles\", bossId)\r\n    \r\n    -- \"Jolie couronne. J’en déduis que c’est toi, le fameux Casse-Cours.\"\r\n    invoke_custom(05000, 1, \"bubble\", playerId, \"quest.chuchoku.mercenary.02.05\")\r\n    \r\n    -- \"Tu as des dernières paroles ?\"\r\n    invoke_custom(09000, 1, \"bubble\", playerId, \"quest.chuchoku.mercenary.02.06\")\r\n    invoke_custom(12000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Hah hah…\"\r\n    invoke_custom(13500, 1, \"bubble\", bossId, \"quest.chuchoku.mercenary.02.07\")\r\n    invoke_custom(15000, 1, \"clearBubbles\", bossId)\r\n    \r\n    -- \"Tu sais quoi ? J’y réfléchirai quand ma fin sera proche, dans quelques siècles.\"\r\n    invoke_custom(15000, 1, \"bubble\", bossId, \"quest.chuchoku.mercenary.02.08\")\r\n    invoke_custom(19500, 1, \"clearBubbles\", bossId)\r\n    \r\n    -- \"Je mourrai quand toute la glace du monde aura disparu.\"\r\n    invoke_custom(20000, 1, \"bubble\", bossId, \"quest.chuchoku.mercenary.02.09\")\r\n    invoke_custom(24500, 1, \"clearBubbles\", bossId)\r\n    \r\n    -- \"Mais d’ici là, j’ai plein de miel à ingurgiter.\"\r\n    invoke_custom(25000, 1, \"bubble\", bossId, \"quest.chuchoku.mercenary.02.10\")\r\n    invoke_custom(28500, 1, \"clearBubbles\", bossId)\r\n    \r\n    -- \"Mon bide va pas s’remplir tout seul !\"\r\n    invoke_custom(29000, 1, \"bubble\", bossId, \"quest.chuchoku.mercenary.02.11\")\r\n    invoke_custom(32500, 1, \"clearBubbles\", bossId)\r\n    \r\n    -- \"Si tu veux, je peux t’épargner et te garder comme esclave.\"\r\n    invoke_custom(33000, 1, \"bubble\", bossId, \"quest.chuchoku.mercenary.02.12\")\r\n    invoke_custom(37500, 1, \"clearBubbles\", bossId)\r\n    \r\n    -- \"Tu verras, l’apiculture c’est pas si mal.\"\r\n    invoke_custom(38000, 1, \"bubble\", bossId, \"quest.chuchoku.mercenary.02.13\")\r\n    invoke_custom(42000, 1, \"clearBubbles\", bossId)\r\n    \r\n    -- \"Assez discuté, je vais mettre fin à ton règne.\"\r\n    invoke_custom(43000, 1, \"bubble\", playerId, \"quest.chuchoku.mercenary.02.14\")\r\n    invoke_custom(48000, 1, \"clearBubbles\", playerId)\r\n    invoke_custom(43000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Non\")\r\n    \r\n    invoke_custom(48000, 1, \"skipCinematic\", 21238)\nend\n\n-- [FIGHT] Lancement du combat\n-- \nfunction event_2448_21241()\n    skipCinematic()\nend\n\n-- FIGHT_ENTER_ACTION_PHASE - Applique l'état \"Donjon\" \n-- \nfunction event_2448_21926()\n    \nend\n\n-- [STELE] FIGHT_STARTED - On applique les difficultés sur le boss\n-- \nfunction event_2448_22821()\n    \nend\n\n-- [STELE] FIGHT_ENTER_ACTION_PHASE - On applique les bonus sur les joueurs\n-- \nfunction event_2448_22822()\n    \nend\n\n-- [STELE] FIGHT_ENDED - On rend la stèle utilisable en cas de défaite\n-- \nfunction event_2448_22897()\n    \nend\n\n-- [ARCHI] Apparition de l'Archimonstre\n-- \nfunction event_2448_24014()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_2448_21232","event_2448_21233","event_2448_21234","event_2448_21235","event_2448_21236","event_2448_21237","event_2448_21238","event_2448_21241","event_2448_21926","event_2448_22821","event_2448_22822","event_2448_22897","event_2448_24014"],"quest_calls":[],"dialogue_calls":[]},"scenario/2449.lua":{"source":"\n\n-- [INIT] Variables Globales\n-- \nfunction event_2449_21242()\n    \nend\n\n-- [INIT] Inscription du joueur + Variables Locales\n-- \nfunction event_2449_21243(room)\n    \nend\n\n-- USER_GROUP_KILLED - Salle 01\n-- \nfunction event_2449_21245(room)\n    \nend\n\n-- USER_GROUP_KILLED - Salle 02 - BOSS\n-- \nfunction event_2449_21246()\n    \nend\n\n-- Déplace le joueur vers la salle suivante\n-- \nfunction event_2449_21247()\n    \nend\n\n-- FIGHT_ENTER_ACTION_PHASE - Applique l'état \"Donjon\" (Salle 1)\n-- \nfunction event_2449_21914()\n    \nend\n\n-- [STELE] FIGHT_STARTED - On applique les difficultés sur le boss\n-- \nfunction event_2449_22854()\n    \nend\n\n-- [STELE] FIGHT_ENTER_ACTION_PHASE - On applique les bonus sur les joueurs\n-- \nfunction event_2449_22855()\n    \nend\n\n-- [STELE] FIGHT_ENDED - On rend la stèle utilisable en cas de défaite\n-- \nfunction event_2449_22898()\n    \nend\n\n-- [ARCHI] Apparition de l'Archimonstre\n-- \nfunction event_2449_24015()\n    \nend\n\n","functions":["event_2449_21242","event_2449_21243","event_2449_21245","event_2449_21246","event_2449_21247","event_2449_21914","event_2449_22854","event_2449_22855","event_2449_22898","event_2449_24015"],"quest_calls":[],"dialogue_calls":[]},"scenario/2450.lua":{"source":"\n\n-- [EVENT] Initialisation\n-- \nfunction event_2450_21252()\n    \nend\n\n-- [ACTION] Lancement du combat associé\n-- \nfunction event_2450_21253(groupId, mobA, mobB, mobC, mobD, mobE, mobF, mobG, mobH, fightId, PlayerId)\n    PlayerId = toLong(PlayerId)\r\n    GroupId =toLong(GroupId)\r\n    FightId = toLong(FightId)\r\n    MobA = toLong(mobA)\r\n    MobB = toLong(mobB)\r\n    MobC = toLong(mobC)\r\n    MobD = toLong(mobD)\r\n    MobE = toLong(mobE)\r\n    MobF = toLong(mobF)\r\n    MobG = toLong(mobG)\r\n    MobH = toLong(mobH)\r\n    \r\n    trace(\"===Valeur de Player Id ======\", PlayerId)\r\n    trace(\"===Valeur de Group Id ======\", groupId)\r\n    trace(\"===Valeur de Fight Id ======\", FightId)\r\n    trace(\"===Valeur de MobA Id ======\", mobA)\r\n    trace(\"===Valeur de MobB Id ======\", mobB)\r\n    trace(\"===Valeur de MobC Id ======\", mobC)\r\n    trace(\"===Valeur de MobD Id ======\", mobD)\r\n    trace(\"===Valeur de MobE Id ======\", mobE)\r\n    trace(\"===Valeur de MobF Id ======\", mobF)\r\n    trace(\"===Valeur de MobG Id ======\", mobG)\r\n    trace(\"===Valeur de MobH Id ======\", mobH)\nend\n\n-- [ACTION] Fin de combat gagnant\n-- \nfunction event_2450_21254(GroupId)\n    \nend\n\n-- [ACTION] Fin de combat gagnant - fin scenario - ACH 4833 OBJ 9994\n-- \nfunction event_2450_21255()\n    \nend\n\n-- [ACTION] Fin de combat perdant\n-- \nfunction event_2450_21256()\n    \nend\n\n","functions":["event_2450_21252","event_2450_21253","event_2450_21254","event_2450_21255","event_2450_21256"],"quest_calls":[],"dialogue_calls":[]},"scenario/2451.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\n\n-- [EVENT] Le joueur confronte le Dernier Voyageur - Cinématique\n-- \nfunction event_2451_21260()\n    local playerId = Context.getLeaderId()\r\n    local voyageurId = createActor(1106905252, 0, -9, 0, 8, 3, 8)\r\n    local pandoraId = createActor(163503405, 0, 0, 0, 4, 7, 8)\r\n    \r\n    startCinematicContext(0.8, voyageurId)\r\n    \r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 21260)\r\n    \r\n    invoke_custom(01000, 1, \"Mobile.moveMobile\", playerId, -1, -4, 0, \"Mobile.setMobileDirection\", playerId, 7)\r\n    invoke_custom(01000, 1, \"Mobile.moveMobile\", pandoraId, 1, -3, 0, \"Mobile.setMobileDirection\", pandoraId, 7)\r\n    \r\n    -- \"On dirait que nous sommes arrivés juste à temps...\"\r\n    invoke_custom(05000, 1, \"bubble\", playerId, \"quest.chuchoku.04.01\")\r\n    invoke_custom(07000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(09500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Nous allons t'empêcher de prendre le dernier fragment...\"\r\n    invoke_custom(10000, 1, \"bubble\", pandoraId, \"quest.chuchoku.04.02\")\r\n    invoke_custom(10000, 1, \"Mobile.setMobileAnimation\", pandoraId, \"AnimComp-Reflexion\")\r\n    invoke_custom(15500, 1, \"clearBubbles\", pandoraId)\r\n    \r\n    -- \"Et récupérer les fragments que tu as volés !\"\r\n    invoke_custom(16000, 1, \"bubble\", pandoraId, \"quest.chuchoku.04.03\")\r\n    invoke_custom(16000, 1, \"Mobile.setMobileAnimation\", pandoraId, \"AnimSort-BigOne\")\r\n    invoke_custom(20500, 1, \"clearBubbles\", pandoraId)\r\n    \r\n    -- \"J’ai déjà récupéré celui de cette île.\"\r\n    invoke_custom(21500, 1, \"bubble\", voyageurId, \"quest.chuchoku.04.04\")\r\n    invoke_custom(24500, 1, \"clearBubbles\", voyageurId)\r\n    \r\n    -- \"Il ne me manque plus que les vôtres.\"\r\n    invoke_custom(25000, 1, \"bubble\", voyageurId, \"quest.chuchoku.04.05\")\r\n    invoke_custom(28000, 1, \"clearBubbles\", voyageurId)\r\n    \r\n    -- \"[#name], Pandora...\"\r\n    invoke_custom(28500, 1, \"bubble\", voyageurId, \"quest.chuchoku.04.06\")\r\n    invoke_custom(30500, 1, \"clearBubbles\", voyageurId)\r\n    \r\n    -- \"Ok, c'est un peu dérangeant. Tu sembles bien nous connaître.\"\r\n    invoke_custom(31000, 1, \"bubble\", playerId, \"quest.chuchoku.04.07\")\r\n    invoke_custom(31000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(36000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Qui es-tu vraiment ? Quel est ton objectif ?\"\r\n    invoke_custom(36500, 1, \"bubble\", playerId, \"quest.chuchoku.04.08\")\r\n    invoke_custom(36500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Pointer\")\r\n    invoke_custom(40500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Tu ne te poses pas les bonnes questions, [#name].\"\r\n    invoke_custom(41000, 1, \"bubble\", voyageurId, \"quest.chuchoku.04.09\")\r\n    invoke_custom(45000, 1, \"clearBubbles\", voyageurId)\r\n    \r\n    -- \"Si tu veux tes fragments, viens donc les prendre !\"\r\n    invoke_custom(45500, 1, \"bubble\", voyageurId, \"quest.chuchoku.04.10\")\r\n    invoke_custom(49500, 1, \"clearBubbles\", voyageurId)\r\n    \r\n    -- \"Ça me va parfaitement.\"\r\n    invoke_custom(50000, 1, \"bubble\", playerId, \"quest.chuchoku.04.11\")\r\n    invoke_custom(50000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimStatique02-Debut\")\r\n    invoke_custom(52000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(52500, 1, \"skipCinematic\", 21260)\nend\n\n-- [EVENT] Le joueur confronte le Dernier Voyageur - Lancement du combat\n-- \nfunction event_2451_21261()\n    \nend\n\n-- [EVENT] Le combat contre le Voyageur est perdu - Cinématique\n-- \nfunction event_2451_21262()\n    local playerId = Context.getLeaderId()\r\n    local voyageurId = createActor(1106905252, 0, -9, 0, 8, 3, 8)\r\n    local pandoraId = createActor(163503405, -1, -7, 0, 4, 3, 4)\r\n    \r\n    startCinematicContext(0.8, pandoraId)\r\n    \r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 21262)\r\n    \r\n    invoke_custom(00001, 1, \"Mobile.setMobileAnimation\", pandoraId, \"AnimComp-Evanouie\")\r\n    invoke_custom(00001, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimKO-Boucle\")\r\n    invoke_custom(00001, 1, \"Mobile.setMobilePosition\", playerId, 0, -7, 0)\r\n    invoke_custom(00001, 1, \"Mobile.setMobileDirection\", playerId, 7)\r\n    \r\n    -- \"Pandora !\"\r\n    invoke_custom(03000, 1, \"bubble\", playerId, \"quest.chuchoku.05.01\")\r\n    invoke_custom(05000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"[#name] ! Tu dois...\"\r\n    invoke_custom(05000, 1, \"bubble\", pandoraId, \"quest.chuchoku.05.02\")\r\n    invoke_custom(07500, 1, \"clearBubbles\", pandoraId)\r\n    invoke_custom(07001, 1, \"Mobile.setMobileAnimation\", pandoraId, \"AnimComp-Disparition\")\r\n    \r\n    -- \"Enfin... Je me suis débarrassé des Veilleurs !\"\r\n    invoke_custom(08000, 1, \"bubble\", voyageurId, \"quest.chuchoku.05.03\")\r\n    invoke_custom(12000, 1, \"clearBubbles\", voyageurId)\r\n    \r\n    -- \"Après toutes ces années à attendre la faille.\"\r\n    invoke_custom(12500, 1, \"bubble\", voyageurId, \"quest.chuchoku.05.04\")\r\n    invoke_custom(16500, 1, \"clearBubbles\", voyageurId)\r\n    \r\n    -- \"Qu'est-ce que tu as fait à Pandora ?!\"\r\n    invoke_custom(17000, 1, \"bubble\", playerId, \"quest.chuchoku.05.05\")\r\n    invoke_custom(20000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Elle n'est pas morte, rassure-toi.\"\r\n    invoke_custom(20500, 1, \"bubble\", voyageurId, \"quest.chuchoku.05.06\")\r\n    invoke_custom(22500, 1, \"clearBubbles\", voyageurId)\r\n    \r\n    -- \"J'ai enfin accompli mon plan.\"\r\n    invoke_custom(23000, 1, \"bubble\", voyageurId, \"quest.chuchoku.05.07\")\r\n    invoke_custom(25500, 1, \"clearBubbles\", voyageurId)\r\n    invoke_custom(25501, 1, \"Mobile.setMobileDirection\", voyageurId, 7)\r\n    \r\n    -- \"Demain, tu auras tout oublié, ne t'inquiète pas.\"\r\n    invoke_custom(26000, 1, \"bubble\", voyageurId, \"quest.chuchoku.05.08\")\r\n    invoke_custom(29500, 1, \"clearBubbles\", voyageurId)\r\n    \r\n    -- \"Adieu, élu{[1*]?e:}. On dirait que ta destinée ne s'est pas accomplie...\"\r\n    invoke_custom(30000, 1, \"bubble\", voyageurId, \"quest.chuchoku.05.09\")\r\n    invoke_custom(35500, 1, \"clearBubbles\", voyageurId)\r\n    \r\n    invoke_custom(36000, 1, \"skipCinematic\", 21262)\nend\n\n-- [EVENT] Le combat contre le Voyageur est perdu - ACH 4828 OBJ 9978\n-- \nfunction event_2451_21263()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_2451_21260","event_2451_21261","event_2451_21262","event_2451_21263"],"quest_calls":[],"dialogue_calls":[]},"scenario/2452.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\n-- les fonctions où on cache\r\nfunction hideMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, false)\r\nend\r\n\r\n-- les fonctions où on rend visible (à nouveau\r\nfunction showMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, true)\r\nend\r\n\r\nfunction cameraShake()\r\n \tlocal shakeEffectId = Effect.createCameraShakeEffect(250, 500, 250, 3)\r\n \tinvoke(1000, 1, \"Effect.stopEffect\", shakeEffectId)\r\nend\r\n\r\nfunction cameraShakeViolent()\r\n \tlocal shakeEffectIdv = Effect.createCameraShakeEffect(500, 1500, 250, 5)\r\n \tinvoke(2000, 1, \"Effect.stopEffect\", shakeEffectIdv)\r\nend\r\n\n\n-- [INIT] Variables\n-- \nfunction event_2452_21265()\n    \nend\n\n-- [EVENT] Le joueur rentre dans l'instance\n-- \nfunction event_2452_21376(pandora, otomai, voyageurMort)\n    Mobile.addMobileCreationCallback(pandora, \"hideMonster\", pandora)\r\n    Mobile.addMobileCreationCallback(otomai, \"hideMonster\", otomai)\r\n    Mobile.addMobileCreationCallback(voyageurMort, \"hideMonster\", voyageurMort)\nend\n\n-- [EVENT] Le joueur confronte le Dernier Voyageur - Lancement du combat\n-- \nfunction event_2452_21264()\n    \nend\n\n-- [EVENT] Combat de monstres - Début\n-- \nfunction event_2452_21268()\n    \nend\n\n-- [EVENT] Le joueur gagne contre le Voyageur - Cinématique\n-- \nfunction event_2452_21375()\n    local playerId = Context.getLeaderId()\r\n    local voyageurId = createActor(1106905252, -10, -1, 0, 8, 3, 8)\r\n    local otomaiId = createActor(181404009, -11, -14, 65, 4, 3, 8)\r\n    local pandoraId = createActor(163503405, -9, -5, 0, 4, 3, 6)\r\n    \r\n    local mobile = Mobile.getMobileGFX(playerId)\r\n    local finisherTargetMobileId = Mobile.generateClientMobileId()\r\n    Actor.createActor(finisherTargetMobileId, mobile, -10, -1, 0, 4)\r\n    Actor.copyActorFrom(playerId, finisherTargetMobileId)\r\n    Mobile.setMobileDirection(finisherTargetMobileId, 1)\r\n    \r\n    ----------------------------- SKIP DE CINEMATIQUE PAR LE BOUTON --------------------------\r\n    \r\n    function customSkip()\r\n    \tUI.displayWideScreenBand(true, 25, 300)\r\n    \tskipCinematic(21375)\r\n    end\r\n    \t\r\n    startCinematicContext(1.3, voyageurId, 210079)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"customSkip\")\r\n    \r\n    invoke_custom(00001, 1, \"Mobile.setMobileVisible\", finisherTargetMobileId, false)\r\n    invoke_custom(00001, 1, \"Mobile.setMobileDirection\", finisherTargetMobileId, 1)\r\n    invoke_custom(00001, 1, \"Mobile.setMobileVisible\", otomaiId, false)\r\n    invoke_custom(00001, 1, \"Mobile.setMobileVisible\", pandoraId, false)\r\n    invoke_custom(00001, 1, \"Mobile.setMobilePosition\", playerId, -10, 3, 0)\r\n    invoke_custom(00001, 1, \"Mobile.setMobileDirection\", playerId, 7)\r\n    invoke_custom(00010, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimKO-Boucle\")\r\n    \r\n    -- \"Qu'est-ce que je t'avais dit ? Il est inutile de résister !\"\r\n    invoke_custom(02000, 1, \"bubble\", voyageurId, \"quest.chuchoku.07.01\")\r\n    invoke_custom(04500, 1, \"clearBubbles\", voyageurId)\r\n    invoke_custom(02000, 1, \"Sound.playSound\", 502000005005)\r\n    invoke_custom(02000, 1, \"cameraShake\")\r\n    \r\n    -- \"Bientôt je remonterai dans le temps et je changerai le monde entier !\"\r\n    invoke_custom(05000, 1, \"bubble\", voyageurId, \"quest.chuchoku.07.02\")\r\n    invoke_custom(09500, 1, \"clearBubbles\", voyageurId)\r\n    \r\n    -- \"Ce sera un monde de liberté, sans la tyrannie des divinités !\"\r\n    invoke_custom(10000, 1, \"bubble\", voyageurId, \"quest.chuchoku.07.03\")\r\n    invoke_custom(14000, 1, \"clearBubbles\", voyageurId)\r\n    invoke_custom(14001, 1, \"Mobile.setMobileDirection\", voyageurId, 1)\r\n    \r\n    -- \"... Tu devrais me remercier.\"\r\n    invoke_custom(15000, 1, \"bubble\", voyageurId, \"quest.chuchoku.07.04\")\r\n    invoke_custom(17000, 1, \"clearBubbles\", voyageurId)\r\n    \r\n    invoke_custom(19000, 1, \"Camera.setZoomFactor\", 1.1)\r\n    invoke_custom(19000, 1, \"Camera.attachCameraToMobile\", otomaiId)\r\n    \r\n    invoke_custom(19000, 1, \"Mobile.setMobileVisible\", pandoraId, true)\r\n    invoke_custom(19001, 1, \"Mobile.setMobileAnimation\", pandoraId, \"AnimApparition\")\r\n    \r\n    -- \"Il n'en est pas question !\"\r\n    invoke_custom(20000, 1, \"bubble\", pandoraId, \"quest.chuchoku.07.05\")\r\n    invoke_custom(23000, 1, \"clearBubbles\", pandoraId)\r\n    \r\n    invoke_custom(17000, 1, \"Mobile.setMobileVisible\", otomaiId, true)\r\n    invoke_custom(17000, 1, \"Mobile.setMobileAnimationSuffix\", otomaiId, \"-Oiseau\")\r\n    invoke_custom(17000, 1, \"Mobile.setMobileMovementStyle\", otomaiId, \"TRAJECTORY\", \"TRAJECTORY\", false)\r\n    invoke_custom(17001, 1, \"Mobile.addCubicSplineTweenToMobile\", otomaiId, -10, -4, 0, 4000, 0, 0, -10, 0, -1, 2)\r\n    invoke_custom(22000, 1, \"Mobile.setMobileMovementStyle\", otomaiId, \"WALK\", \"RUN\", false)\r\n    invoke_custom(22000, 1, \"Particle.addParticleSystem\", -1814057072, -10, -4, 0)\r\n    invoke_custom(22500, 1, \"Mobile.setMobileAnimationSuffix\", otomaiId, \"\")\r\n    invoke_custom(22501, 1, \"Mobile.setMobileAnimation\", otomaiId, \"AnimStatique02\")\r\n    \r\n    -- \"Hah ! Vous revoilà. Mais ce n'est rien qu'un contretemps...\"\r\n    invoke_custom(23001, 1, \"Mobile.set