m(119500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Tu ne te rends pas compte de ce que tu as fait ! Tu es maintenant...\"\r\n    invoke_custom(120000, 1, \"bubble\", otomaiId, \"quest.chuchoku.07.187\")\r\n    invoke_custom(125500, 1, \"clearBubbles\", otomaiId)\r\n    \r\n    -- \"... Prisonni{[1*]?ère:er} de 977, oui.\"\r\n    invoke_custom(125500, 1, \"bubble\", playerId, \"quest.chuchoku.07.188\")\r\n    invoke_custom(125500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Acquiescer\")\r\n    invoke_custom(128500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Mais passons plutôt au sujet principal.\"\r\n    invoke_custom(129000, 1, \"bubble\", playerId, \"quest.chuchoku.07.189\")\r\n    invoke_custom(129000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Calmer\")\r\n    invoke_custom(132000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(132000, 1, \"Mobile.setMobileDirection\", playerId, 1)\r\n    \r\n    -- \"C'est donc ça d'être un{[1*]?e Déesse: Dieu} de ce monde...\"\r\n    invoke_custom(133000, 1, \"bubble\", playerId, \"quest.chuchoku.07.19\")\r\n    invoke_custom(137000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"J'ai l'impression de voir le Krosmoz défiler devant mes yeux !\"\r\n    invoke_custom(137500, 1, \"bubble\", playerId, \"quest.chuchoku.07.20\")\r\n    invoke_custom(141500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Allez, libérons la connaissance des dieux pour tous les habitants du Monde des Douze !\"\r\n    invoke_custom(142500, 1, \"bubble\", playerId, \"quest.chuchoku.07.201\")\r\n    invoke_custom(142500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Victoire\")\r\n    invoke_custom(148500, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(149000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimIncarnation\")\r\n    invoke_custom(149000, 1, \"Particle.addParticleSystem\", 800573, -5, -3, 0)\r\n    \r\n    -- \"Après tant de sacrifices, le projet Méthée est enfin accompli...\"\r\n    invoke_custom(157000, 1, \"bubble\", pandoraId, \"quest.chuchoku.07.21\")\r\n    invoke_custom(164000, 1, \"clearBubbles\", pandoraId)\r\n    \r\n    -- \"Je n'en crois pas mes yeux...\"\r\n    invoke_custom(159000, 1, \"bubble\", otomaiId, \"quest.chuchoku.07.22\")\r\n    invoke_custom(161500, 1, \"clearBubbles\", otomaiId)\r\n    \r\n    -- \"Et voilà, c'est enfin terminé...\"\r\n    invoke_custom(162000, 1, \"bubble\", playerId, \"quest.chuchoku.07.23\")\r\n    invoke_custom(164500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Quelle journée...\"\r\n    invoke_custom(165000, 1, \"bubble\", playerId, \"quest.chuchoku.07.24\")\r\n    invoke_custom(165000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Bailler\")\r\n    invoke_custom(167000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"J'ai bien mérité un after chez Pandiego.\"\r\n    invoke_custom(167500, 1, \"bubble\", playerId, \"quest.chuchoku.07.25\")\r\n    invoke_custom(167500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Rire\")\r\n    invoke_custom(170500, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(169000, 1, \"Mobile.setMobileDirection\", pandoraId, 7)\r\n    invoke_custom(169000, 1, \"Mobile.setMobileDirection\", otomaiId, 3)\r\n    \r\n    -- \"Otomaï, vous avez été d'une grande aide.\"\r\n    invoke_custom(169000, 1, \"bubble\", pandoraId, \"quest.chuchoku.07.26\")\r\n    invoke_custom(172000, 1, \"clearBubbles\", pandoraId)\r\n    \r\n    -- \"Allons, je n'ai fait que mon devoir de mentor envers [#name]\"\r\n    invoke_custom(172500, 1, \"bubble\", otomaiId, \"quest.chuchoku.07.27\")\r\n    invoke_custom(177000, 1, \"clearBubbles\", otomaiId)\r\n    \r\n    -- \"Si d'aventure vous avez besoin de mes services... Vous savez où me trouver, Pandora !\"\r\n    invoke_custom(177500, 1, \"bubble\", otomaiId, \"quest.chuchoku.07.28\")\r\n    invoke_custom(183000, 1, \"clearBubbles\", otomaiId)\r\n    \r\n    -- \"Oh, mais vous m'avez déjà bien aidée par le passé.\"\r\n    invoke_custom(183500, 1, \"bubble\", pandoraId, \"quest.chuchoku.07.29\")\r\n    invoke_custom(186500, 1, \"clearBubbles\", pandoraId)\r\n    \r\n    -- \"Euh...\"\r\n    invoke_custom(187000, 1, \"bubble\", otomaiId, \"quest.chuchoku.07.30\")\r\n    invoke_custom(188500, 1, \"clearBubbles\", otomaiId)\r\n    \r\n    -- \"Bon, quand je toucherai à nouveau la Clepsydre, nous pourrons y aller.\"\r\n    invoke_custom(188500, 1, \"Mobile.setMobileDirection\", playerId, 5)\r\n    invoke_custom(189000, 1, \"bubble\", playerId, \"quest.chuchoku.07.31\")\r\n    invoke_custom(193000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Ensuite, eh bien... Il se peut que nous restions en 977 quelque temps.\"\r\n    invoke_custom(193500, 1, \"bubble\", playerId, \"quest.chuchoku.07.32\")\r\n    invoke_custom(198000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(198000, 1, \"UI.displayWideScreenBand\", true, 100, 300)\r\n    invoke_custom(200000, 1, \"UI.displayWideScreenBand\", true, 25, 300)\r\n    invoke_custom(200001, 1, \"skipCinematic\", 21375)\nend\n\n-- [EVENT] Fin de la Cinématique - Validation ACH 4830 OBJ 9999\n-- \nfunction event_2452_21377(pandora, otomai, voyageurMort)\n    Mobile.addMobileCreationCallback(pandora, \"showMonster\", pandora)\r\n    Mobile.addMobileCreationCallback(otomai, \"showMonster\", otomai)\r\n    Mobile.addMobileCreationCallback(voyageurMort, \"showMonster\", voyageurMort)\nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","hideMonster","showMonster","cameraShake","cameraShakeViolent","event_2452_21265","event_2452_21376","event_2452_21264","event_2452_21268","event_2452_21375","customSkip","event_2452_21377"],"quest_calls":[],"dialogue_calls":[]},"scenario/2453.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\n\n-- [INIT] Variables\n-- \nfunction event_2453_21266()\n    \nend\n\n-- [EVENT] Le joueur confronte Aguabrial - Lancement du combat\n-- \nfunction event_2453_21390()\n    \nend\n\n-- [EVENT] Le joueur gagne contre Aguabrial - Cinématique\n-- \nfunction event_2453_21267()\n    local playerId = Context.getLeaderId()\r\n    local aguabrialId = createActor(137201723, -10, 0, 0, 8, 1, 9)\r\n    local otomaiId = createActor(181404009, -8, -12, 65, 4, 3, 7)\r\n    \r\n    ----------------------------- SKIP DE CINEMATIQUE PAR LE BOUTON --------------------------\r\n    \r\n    function customSkip()\r\n    \tUI.displayWideScreenBand(true, 25, 300)\r\n    \tskipCinematic(21267)\r\n    end\r\n    \t\r\n    startCinematicContext(1.1, aguabrialId, 210106)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"customSkip\")\r\n    \r\n    invoke_custom(00001, 1, \"Mobile.setMobileVisible\", otomaiId, false)\r\n    invoke_custom(00001, 1, \"Mobile.setMobilePosition\", playerId, -7, 0, 0)\r\n    invoke_custom(00001, 1, \"Mobile.setMobileDirection\", playerId, 5)\r\n    \r\n    -- \"Intéressant, aventuri{[1*]?ère:er}.\"\r\n    invoke_custom(02000, 1, \"bubble\", aguabrialId, \"quest.chuchoku.06.0.01\")\r\n    invoke_custom(04500, 1, \"clearBubbles\", aguabrialId)\r\n    \r\n    -- \"Tu as montré la force de ta conviction à Aguabrial.\"\r\n    invoke_custom(05000, 1, \"bubble\", aguabrialId, \"quest.chuchoku.06.0.02\")\r\n    invoke_custom(09500, 1, \"clearBubbles\", aguabrialId)\r\n    \r\n    -- \"Mais tu affrontes des ennemis trop puissants pour toi.\"\r\n    invoke_custom(10000, 1, \"bubble\", aguabrialId, \"quest.chuchoku.06.0.03\")\r\n    invoke_custom(14500, 1, \"clearBubbles\", aguabrialId)\r\n    \r\n    -- \"Je sais... J'ai bien besoin d'un petit coup de pouce.\"\r\n    invoke_custom(15000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Calmer\")\r\n    invoke_custom(15000, 1, \"bubble\", playerId, \"quest.chuchoku.06.0.04\")\r\n    invoke_custom(19500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Aguabrial est le gardien du Mont Zinit.\"\r\n    invoke_custom(20000, 1, \"bubble\", aguabrialId, \"quest.chuchoku.06.0.05\")\r\n    invoke_custom(24000, 1, \"clearBubbles\", aguabrialId)\r\n    \r\n    -- \"Je préserve cet équilibre fragile qu'est le Chaos d'Ogrest.\"\r\n    invoke_custom(24500, 1, \"bubble\", aguabrialId, \"quest.chuchoku.06.0.06\")\r\n    invoke_custom(29000, 1, \"clearBubbles\", aguabrialId)\r\n    \r\n    -- \"Quelque chose de pire pourrait se produire par la suite...\"\r\n    invoke_custom(29500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Non\")\r\n    invoke_custom(29500, 1, \"bubble\", playerId, \"quest.chuchoku.06.0.07\")\r\n    invoke_custom(34000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Je te demande juste de m'écouter pendant un moment.\"\r\n    invoke_custom(34500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Calmer\")\r\n    invoke_custom(34500, 1, \"bubble\", playerId, \"quest.chuchoku.06.0.08\")\r\n    invoke_custom(39000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"**Désolé{[1*]?e:} par avance... C'est le seul moyen que j'ai trouvé.\"\r\n    invoke_custom(39500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(39500, 1, \"bubble\", playerId, \"quest.chuchoku.06.0.09\")\r\n    invoke_custom(39500, 1, \"Sound.playForcedMusic\", 210999)\r\n    invoke_custom(44000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(45000, 1, \"UI.displayWideScreenBand\", true, 100, 300)\r\n    \r\n    invoke_custom(47000, 1, \"Sound.playForcedMusic\", 210159)\r\n    invoke_custom(67000, 1, \"Sound.playForcedMusic\", 210106)\r\n    \r\n    invoke_custom(70000, 1, \"UI.displayWideScreenBand\", true, 25, 300)\r\n    \r\n    invoke_custom(71000, 1, \"Particle.addParticleSystem\", 40049830, -7, 0, 10)\r\n    invoke_custom(72000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Victoire\")\r\n    \r\n    -- \"...\"\r\n    invoke_custom(72500, 1, \"bubble\", aguabrialId, \"quest.chuchoku.06.0.10\")\r\n    invoke_custom(73500, 1, \"clearBubbles\", aguabrialId)\r\n    \r\n    -- \"Cette mélodie a bouleversé le cœur d'Aguabrial.\"\r\n    invoke_custom(73500, 1, \"bubble\", aguabrialId, \"quest.chuchoku.06.0.11\")\r\n    invoke_custom(76500, 1, \"clearBubbles\", aguabrialId)\r\n    \r\n    -- \"Le torrent de ma tristesse...\"\r\n    invoke_custom(77000, 1, \"bubble\", aguabrialId, \"quest.chuchoku.06.0.12\")\r\n    invoke_custom(78500, 1, \"clearBubbles\", aguabrialId)\r\n    \r\n    -- \"Aguabrial n'interviendra plus tant que son chagrin ne sera pas guéri.\"\r\n    invoke_custom(79500, 1, \"bubble\", aguabrialId, \"quest.chuchoku.06.0.13\")\r\n    invoke_custom(83500, 1, \"clearBubbles\", aguabrialId)\r\n    invoke_custom(83000, 1, \"Mobile.setMobileAnimation\", aguabrialId, \"AnimMort\")\r\n    \r\n    invoke_custom(84000, 1, \"Camera.setZoomFactor\", 1.5)\r\n    invoke_custom(84000, 1, \"Camera.attachCameraToMobile\", playerId)\r\n    \r\n    invoke_custom(84001, 1, \"Mobile.setMobileVisible\", otomaiId, true)\r\n    invoke_custom(84001, 1, \"Mobile.setMobileAnimationSuffix\", otomaiId, \"-Oiseau\")\r\n    invoke_custom(84001, 1, \"Mobile.setMobileMovementStyle\", otomaiId, \"TRAJECTORY\", \"TRAJECTORY\", false)\r\n    invoke_custom(84051, 1, \"Mobile.addCubicSplineTweenToMobile\", otomaiId, -7, -2, 0, 4000, 0, 0, -10, 0, -1, 2)\r\n    invoke_custom(89500, 1, \"Mobile.setMobileMovementStyle\", otomaiId, \"WALK\", \"RUN\", false)\r\n    invoke_custom(89500, 1, \"Particle.addParticleSystem\", -1814057072, -7, -2, 0)\r\n    invoke_custom(90000, 1, \"Mobile.setMobileAnimationSuffix\", otomaiId, \"\")\r\n    \r\n    -- \"Alors ? J'ai raté quelque chose ?\"\r\n    invoke_custom(90500, 1, \"bubble\", otomaiId, \"quest.chuchoku.06.01\")\r\n    invoke_custom(90500, 1, \"Mobile.setMobileAnimation\", otomaiId, \"AnimComp-Special04-Debut\")\r\n    invoke_custom(93500, 1, \"clearBubbles\", otomaiId)\r\n    \r\n    -- \"C'est bon. Il valait mieux que tu ne sois pas là pour écouter, de toute façon.\"\r\n    invoke_custom(94000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Non\")\r\n    invoke_custom(94000, 1, \"bubble\", playerId, \"quest.chuchoku.06.02\")\r\n    invoke_custom(99000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(99000, 1, \"Mobile.setMobileDirection\", playerId, 7)\r\n    \r\n    -- \"J'ai récupéré un Dofus primordial !\"\r\n    invoke_custom(099500, 1, \"Mobile.setMobileAnimation\", otomaiId, \"AnimComp-Special07\")\r\n    invoke_custom(099500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Pouce\")\r\n    invoke_custom(099500, 1, \"bubble\", playerId, \"quest.chuchoku.06.03\")\r\n    invoke_custom(102000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"C'est un sentiment étrange.\"\r\n    invoke_custom(102500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(102500, 1, \"bubble\", playerId, \"quest.chuchoku.06.04\")\r\n    invoke_custom(105000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"C'est vrai que tu n'as pas trop connu ça, toi...\"\r\n    invoke_custom(105000, 1, \"bubble\", otomaiId, \"quest.chuchoku.06.05\")\r\n    invoke_custom(105000, 1, \"Mobile.setMobileAnimation\", otomaiId, \"AnimComp-Special09\")\r\n    invoke_custom(108500, 1, \"clearBubbles\", otomaiId)\r\n    \r\n    -- \"Bon, tu as des idées pour la suite ?\"\r\n    invoke_custom(109000, 1, \"bubble\", otomaiId, \"quest.chuchoku.06.06\")\r\n    invoke_custom(109000, 1, \"Mobile.setMobileAnimation\", otomaiId, \"AnimComp-Special03\")\r\n    invoke_custom(113000, 1, \"clearBubbles\", otomaiId)\r\n    \r\n    -- \"Où pourrait être ce fameux Voyageur Dimensionnel ?\"\r\n    invoke_custom(113000, 1, \"bubble\", otomaiId, \"quest.chuchoku.06.07\")\r\n    invoke_custom(113000, 1, \"Mobile.setMobileAnimation\", otomaiId, \"AnimComp-Special05-Debut\")\r\n    invoke_custom(118000, 1, \"clearBubbles\", otomaiId)\r\n    \r\n    -- \"Oui. Je sens sa présence... Sur le Royaume Chuchoku.\"\r\n    invoke_custom(118500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(118500, 1, \"bubble\", playerId, \"quest.chuchoku.06.08\")\r\n    invoke_custom(120000, 1, \"Mobile.setMobileAnimation\", otomaiId, \"AnimComp-Special06\")\r\n    invoke_custom(124000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Je ressens d'étranges picotements lorsque je suis sur cette île.\"\r\n    invoke_custom(124500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmoteMarket-HausseEpaules\")\r\n    invoke_custom(124500, 1, \"bubble\", playerId, \"quest.chuchoku.06.09\")\r\n    invoke_custom(129000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Ce doit être un endroit que je ne connais pas encore.\"\r\n    invoke_custom(129500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Calmer\")\r\n    invoke_custom(129500, 1, \"bubble\", playerId, \"quest.chuchoku.06.10\")\r\n    invoke_custom(135000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Et à propos de ce que je t'ai demandé...\"\r\n    invoke_custom(135500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Presenter\")\r\n    invoke_custom(135500, 1, \"bubble\", playerId, \"quest.chuchoku.06.11\")\r\n    invoke_custom(139000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"J'ai localisé Pandora, oui. Et j'ai prévu un plan pour la libérer...\"\r\n    invoke_custom(139500, 1, \"bubble\", otomaiId, \"quest.chuchoku.06.12\")\r\n    invoke_custom(139500, 1, \"Mobile.setMobileAnimation\", otomaiId, \"AnimComp-Special03\")\r\n    invoke_custom(145000, 1, \"clearBubbles\", otomaiId)\r\n    invoke_custom(145000, 1, \"Mobile.setMobileAnimation\", otomaiId, \"AnimComp-Special12-Debut\")\r\n    \r\n    -- \"Bon, parfait. Rejoignez-moi dès que vous pouvez.\"\r\n    invoke_custom(145000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Presenter\")\r\n    invoke_custom(145000, 1, \"bubble\", playerId, \"quest.chuchoku.06.13\")\r\n    invoke_custom(149000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Je n'arrête pas de penser à ce que m'a dit le Voyageur...\"\r\n    invoke_custom(149500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(149500, 1, \"bubble\", playerId, \"quest.chuchoku.06.14\")\r\n    invoke_custom(153000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Et j'ai une petite idée de ce qu'il veut faire...\"\r\n    invoke_custom(153500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmoteMarket-HausseEpaules\")\r\n    invoke_custom(153500, 1, \"bubble\", playerId, \"quest.chuchoku.06.15\")\r\n    invoke_custom(157000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Si mon intuition est fondée, alors j'ai peut-être un plan.\"\r\n    invoke_custom(157500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Pointer\")\r\n    invoke_custom(157500, 1, \"bubble\", playerId, \"quest.chuchoku.06.16\")\r\n    invoke_custom(161000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(161500, 1, \"UI.displayWideScreenBand\", true, 100, 300)\r\n    \r\n    invoke_custom(164000, 1, \"UI.displayWideScreenBand\", true, 25, 300)\r\n    invoke_custom(164001, 1, \"skipCinematic\", 21267)\nend\n\n-- [EVENT] Le joueur gagne contre Aguabrial - ACH 4829 OBJ 9988\n-- \nfunction event_2453_21269()\n    \nend\n\n-- [EVENT] ZoneTrigger - Le joueur marche dans le vide\n-- \nfunction event_2453_21284()\n    \nend\n\n-- [EVENT] ZoneTrigger - Le joueur est TP\n-- \nfunction event_2453_21285()\n    \nend\n\n-- [EVENT] Combat lancé - Désactivation de la ZoneTrigger\n-- \nfunction event_2453_21286()\n    \nend\n\n-- [EVENT] Placement terminé - Réactivation de la ZoneTrigger\n-- \nfunction event_2453_21287()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_2453_21266","event_2453_21390","event_2453_21267","customSkip","event_2453_21269","event_2453_21284","event_2453_21285","event_2453_21286","event_2453_21287"],"quest_calls":[],"dialogue_calls":[]},"scenario/2454.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\n\n-- [EVENT] Initialisation\n-- \nfunction event_2454_21279()\n    \nend\n\n-- [EVENT] Le joueur confronte le Dernier Voyageur - Cinématique\n-- \nfunction event_2454_21275(pandora)\n    local playerId = Context.getLeaderId()\r\n    local pandoraRealId = toLong(pandora)\r\n    local voyageurId = createActor(1106905252, -223, -34, -80, 8, 7, 8)\r\n    local pandoraId  = createActor(163503405, -231, -45, -80, 8, 1, 8)\r\n    \r\n    startCinematicContext(0.8, voyageurId)\r\n    \r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 21275)\r\n    \r\n    invoke_custom(00001, 1, \"Mobile.setMobileVisible\", voyageurId, false)\r\n    invoke_custom(00001, 1, \"Mobile.setMobileVisible\", pandoraRealId, false)\r\n    invoke_custom(00001, 1, \"Camera.setCamera\", 0.8, -223, -40, -79)\r\n    \r\n    invoke_custom(01000, 1, \"Mobile.moveMobile\", playerId, -223, -43, -80, \"Mobile.setMobileDirection\", playerId, 3)\r\n    invoke_custom(01000, 1, \"Mobile.moveMobile\", pandoraId, -222, -45, -80, \"Mobile.setMobileDirection\", pandoraId, 3)\r\n    \r\n    invoke_custom(03000, 1, \"Mobile.setMobileVisible\", voyageurId, true)\r\n    invoke_custom(03001, 1, \"Mobile.setMobileAnimation\", voyageurId, \"AnimMarche-Fin\")\r\n    \r\n    -- \"C'est qui, lui ?\"\r\n    invoke_custom(05000, 1, \"bubble\", playerId, \"quest.chuchoku.02.01\")\r\n    invoke_custom(05000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Pointer\")\r\n    invoke_custom(07500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Il a... Il a une aiguille chronomagique ! C'est un Veilleur !\"\r\n    invoke_custom(08000, 1, \"bubble\", pandoraId, \"quest.chuchoku.02.02\")\r\n    invoke_custom(08000, 1, \"Mobile.setMobileAnimation\", pandoraId, \"AnimComp-Reflexion\")\r\n    invoke_custom(12500, 1, \"clearBubbles\", pandoraId)\r\n    \r\n    -- \"Mais je ne le connais pas !\"\r\n    invoke_custom(13000, 1, \"bubble\", pandoraId, \"quest.chuchoku.02.03\")\r\n    invoke_custom(15500, 1, \"clearBubbles\", pandoraId)\r\n    \r\n    -- \"Il nous attaque... En garde !\"\r\n    invoke_custom(16000, 1, \"bubble\", playerId, \"quest.chuchoku.02.04\")\r\n    invoke_custom(16000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Colere\")\r\n    invoke_custom(17500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimStatique02-Debut\")\r\n    invoke_custom(19000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(19500, 1, \"skipCinematic\", 21275)\nend\n\n-- [EVENT] Le joueur confronte le Dernier Voyageur - Lancement du combat\n-- \nfunction event_2454_21280(groupId, mobA, fightId, playerId)\n    playerId = toLong(playerId)\r\n    groupId =toLong(groupId)\r\n    fightId = toLong(fightId)\r\n    mobA = toLong(mobA)\r\n    \r\n    trace(\"===Valeur de Player Id ======\", playerId)\r\n    trace(\"===Valeur de Group Id ======\", groupId)\r\n    trace(\"===Valeur de Fight Id ======\", fightId)\r\n    trace(\"===Valeur de MobA Id ======\", mobA)\nend\n\n-- [EVENT] Fin de combat contre le Voyageur - Cinématique\n-- \nfunction event_2454_21277(pandora)\n    local playerId = Context.getLeaderId()\r\n    local pandoraRealId = toLong(pandora)\r\n    local voyageurId = createActor(1106905252, -224, -40, -79, 8, 3, 8)\r\n    local pandoraId  = createActor(163503405,  -224, -36, -79, 8, 7, 8)\r\n    \r\n    ----------------------------- SKIP DE CINEMATIQUE PAR LE BOUTON --------------------------\r\n    function customSkip()\r\n    \tMobile.setMobileVisible(pandoraRealId, true)\r\n    \tskipCinematic(21277)\r\n    end\r\n    \r\n    startCinematicContext(0.8, pandoraId, 210079)\r\n    \r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"customSkip\")\r\n    \r\n    invoke_custom(00001, 1, \"Mobile.setMobileVisible\", pandoraRealId, false)\r\n    invoke_custom(00001, 1, \"Mobile.setMobileAnimation\", pandoraId, \"AnimKO-Boucle\")\r\n    invoke_custom(00001, 1, \"Mobile.setMobilePosition\", playerId, -223, -35, -80)\r\n    invoke_custom(00001, 1, \"Mobile.setMobileDirection\", playerId, 7)\r\n    invoke_custom(00005, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimKO-Boucle\")\r\n    \r\n    -- \"Qu'est-ce que c'est que ce type... Nos attaques ne lui font rien...\"\r\n    invoke_custom(05000, 1, \"bubble\", playerId, \"quest.chuchoku.03.01\")\r\n    invoke_custom(09500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Son aiguille lui permet d'ouvrir des bulles temporelles...\"\r\n    invoke_custom(09000, 1, \"bubble\", pandoraId, \"quest.chuchoku.03.02\")\r\n    invoke_custom(14500, 1, \"clearBubbles\", pandoraId)\r\n    \r\n    -- \"Cette personne... n'est pas un Veilleur !\"\r\n    invoke_custom(15000, 1, \"bubble\", pandoraId, \"quest.chuchoku.03.03\")\r\n    invoke_custom(18500, 1, \"clearBubbles\", pandoraId)\r\n    \r\n    -- \"Ah bah merci, on n'avait pas remarqué...\"\r\n    invoke_custom(18500, 1, \"bubble\", playerId, \"quest.chuchoku.03.04\")\r\n    invoke_custom(21000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(21000, 1, \"Mobile.setMobileAnimation\", voyageurId, \"AnimMarche\")\r\n    invoke_custom(21700, 1, \"Mobile.setMobilePosition\", voyageurId, -224, -37, -79)\r\n    invoke_custom(21800, 1, \"Mobile.setMobileAnimation\", voyageurId, \"AnimMarche-Fin\")\r\n    \r\n    -- \"Non, nos fragments de la connaissance des Dieux !\"\r\n    invoke_custom(22500, 1, \"bubble\", pandoraId, \"quest.chuchoku.03.05\")\r\n    invoke_custom(26000, 1, \"clearBubbles\", pandoraId)\r\n    \r\n    invoke_custom(26000, 1, \"Mobile.setMobileAnimation\", pandoraId, \"AnimKO-SortieOK\")\r\n    invoke_custom(26000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimKO-SortieOK\")\r\n    invoke_custom(26800, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimStatique02-Debut\")\r\n    \r\n    invoke_custom(28000, 1, \"Mobile.setMobileAnimation\", voyageurId, \"AnimSort-1\")\r\n    invoke_custom(29000, 1, \"Particle.addParticleSystem\", 410067191, -224, -36, -79)\r\n    invoke_custom(29000, 1, \"Particle.addParticleSystem\", 410067191, -223, -35, -80)\r\n    \r\n    invoke_custom(29500, 1, \"Mobile.setMobileAnimation\", pandoraId, \"AnimKO-Debut\")\r\n    invoke_custom(29500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimKO-Debut\")\r\n    \r\n    -- \"Argh ! Tu ne t'en tireras pas comme ça !\"\r\n    invoke_custom(29500, 1, \"bubble\", playerId, \"quest.chuchoku.03.06\")\r\n    invoke_custom(33000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Argh...\"\r\n    invoke_custom(29500, 1, \"bubble\", pandoraId, \"quest.chuchoku.03.07\")\r\n    invoke_custom(31000, 1, \"clearBubbles\", pandoraId)\r\n    \r\n    invoke_custom(31000, 1, \"Mobile.setMobileAnimation\", voyageurId, \"AnimMarche\")\r\n    \r\n    -- \"C'est... C'est fini... Nous avons perdu la connaissance des Dieux, tout espoir a disparu...\"\r\n    invoke_custom(33500, 1, \"bubble\", pandoraId, \"quest.chuchoku.03.08\")\r\n    invoke_custom(40000, 1, \"clearBubbles\", pandoraId)\r\n    \r\n    invoke_custom(40490, 1, \"Mobile.setMobileVisible\", pandoraRealId, true)\r\n    \r\n    invoke_custom(40500, 1, \"skipCinematic\", 21277)\nend\n\n-- [EVENT] Fin de combat contre le Voyageur - ACH 4827 OBJ 9978\n-- \nfunction event_2454_21278()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_2454_21279","event_2454_21275","event_2454_21280","event_2454_21277","customSkip","event_2454_21278"],"quest_calls":[],"dialogue_calls":[]},"scenario/2455.lua":{"source":"\n\n-- [EVENT] Le joueur interagit avec la Stèle 1\n-- \nfunction event_2455_21289()\n    invoke(1500, 1, \"Sound.playSound\", 502000005006, true, 60)\nend\n\n-- [EVENT] Le joueur interagit avec la Stèle 2\n-- \nfunction event_2455_21290()\n    invoke(1500, 1, \"Sound.playSound\", 502000005007, true, 60)\nend\n\n-- [EVENT] Le joueur interagit avec la Stèle 3\n-- \nfunction event_2455_21369()\n    invoke(1500, 1, \"Sound.playSound\", 502000005008, true, 60)\nend\n\n-- [EVENT] Le joueur interagit avec la Stèle 4\n-- \nfunction event_2455_21370()\n    invoke(1500, 1, \"Sound.playSound\", 502000005009, true, 60)\nend\n\n-- [EVENT] Le joueur interagit avec la Stèle 5\n-- \nfunction event_2455_21371()\n    invoke(1500, 1, \"Sound.playSound\", 502000005010, true, 60)\nend\n\n-- [EVENT] Le joueur interagit avec la Stèle 6\n-- \nfunction event_2455_21372()\n    invoke(1500, 1, \"Sound.playSound\", 502000005011, true, 60)\nend\n\n-- [EVENT] Le joueur interagit avec la Stèle 7\n-- \nfunction event_2455_21373()\n    invoke(1500, 1, \"Sound.playSound\", 502000005012, true, 60)\nend\n\n-- [EVENT] Le joueur interagit avec la Stèle 8\n-- \nfunction event_2455_21374()\n    invoke(1500, 1, \"Sound.playSound\", 502000005013, true, 60)\nend\n\n","functions":["event_2455_21289","event_2455_21290","event_2455_21369","event_2455_21370","event_2455_21371","event_2455_21372","event_2455_21373","event_2455_21374"],"quest_calls":[],"dialogue_calls":[]},"scenario/2459.lua":{"source":"\n\n-- [INIT] Variables\n-- \nfunction event_2459_21378()\n    \nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_2459_21379()\n    \nend\n\n-- [EVENT] 1 - Réceptacle Full - On rend le challenge disponible grâce à l'état de l'IE\n-- \nfunction event_2459_21380()\n    \nend\n\n-- [EVENT] 1 - Fin du challenge - On reset le Réceptacle\n-- \nfunction event_2459_21381()\n    \nend\n\n","functions":["event_2459_21378","event_2459_21379","event_2459_21380","event_2459_21381"],"quest_calls":[],"dialogue_calls":[]},"scenario/2460.lua":{"source":"\n\n-- [INIT] Variables\n-- \nfunction event_2460_21382()\n    \nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_2460_21383()\n    \nend\n\n-- [EVENT] 1 - Réceptacle Full - On rend le challenge disponible grâce à l'état de l'IE\n-- \nfunction event_2460_21384()\n    \nend\n\n-- [EVENT] 1 - Fin du challenge - On reset le Réceptacle\n-- \nfunction event_2460_21385()\n    \nend\n\n","functions":["event_2460_21382","event_2460_21383","event_2460_21384","event_2460_21385"],"quest_calls":[],"dialogue_calls":[]},"scenario/2461.lua":{"source":"\n\n-- [INIT] Variables\n-- \nfunction event_2461_21386()\n    \nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_2461_21387()\n    \nend\n\n-- [EVENT] 1 - Réceptacle Full - On rend le challenge disponible grâce à l'état de l'IE\n-- \nfunction event_2461_21388()\n    \nend\n\n-- [EVENT] 1 - Fin du challenge - On reset le Réceptacle\n-- \nfunction event_2461_21389()\n    \nend\n\n","functions":["event_2461_21386","event_2461_21387","event_2461_21388","event_2461_21389"],"quest_calls":[],"dialogue_calls":[]},"scenario/2462.lua":{"source":"\n\n-- [EVENT] Initialisation\n-- \nfunction event_2462_21394()\n    \nend\n\n-- [ACTION] Lancement du combat associé\n-- \nfunction event_2462_21395(groupId, mobA, mobB, mobC, mobD, mobE, mobF, mobG, mobH, fightId, playerId)\n    playerId = toLong(playerId)\r\n    groupId =toLong(groupId)\r\n    FightId = toLong(fightId)\r\n    MobA = toLong(mobA)\r\n    MobB = toLong(mobB)\r\n    MobC = toLong(mobC)\r\n    MobD = toLong(mobD)\r\n    MobE = toLong(mobE)\r\n    MobF = toLong(mobF)\r\n    MobG = toLong(mobG)\r\n    MobH = toLong(mobH)\r\n    \r\n    trace(\"===Valeur de Player Id ======\", playerId)\r\n    trace(\"===Valeur de Group Id ======\", groupId)\r\n    trace(\"===Valeur de Fight Id ======\", fightId)\r\n    trace(\"===Valeur de MobA Id ======\", mobA)\r\n    trace(\"===Valeur de MobB Id ======\", mobB)\r\n    trace(\"===Valeur de MobC Id ======\", mobC)\r\n    trace(\"===Valeur de MobD Id ======\", mobD)\r\n    trace(\"===Valeur de MobE Id ======\", mobE)\r\n    trace(\"===Valeur de MobF Id ======\", mobF)\r\n    trace(\"===Valeur de MobG Id ======\", mobG)\r\n    trace(\"===Valeur de MobH Id ======\", mobH)\nend\n\n-- [ACTION] Fin de combat gagnant\n-- \nfunction event_2462_21396(groupId)\n    \nend\n\n-- [ACTION] Fin de combat gagnant - fin scenario - ACH 4833 OBJ 9994\n-- \nfunction event_2462_21397()\n    \nend\n\n-- [ACTION] Fin de combat perdant\n-- \nfunction event_2462_21398()\n    \nend\n\n","functions":["event_2462_21394","event_2462_21395","event_2462_21396","event_2462_21397","event_2462_21398"],"quest_calls":[],"dialogue_calls":[]},"scenario/2463.lua":{"source":"\n\n-- [EVENT] Lancement combat Wapin\n-- \nfunction event_2463_21412()\n    \nend\n\n-- [EVENT] Lancement combat Tofu\n-- \nfunction event_2463_21407()\n    \nend\n\n-- [EVENT] Lancement combat Boufette\n-- \nfunction event_2463_21406()\n    \nend\n\n-- [EVENT] Lancement combat Piou Rouge\n-- \nfunction event_2463_21413()\n    \nend\n\n-- [EVENT] Lancement combat Arakne\n-- \nfunction event_2463_21414()\n    \nend\n\n-- [EVENT] Lancement combat Craqueleur ancestral\n-- \nfunction event_2463_21408()\n    \nend\n\n-- [EVENT] Lancement combat Moogrr\n-- \nfunction event_2463_21415()\n    \nend\n\n-- [EVENT] Lancement combat Kaskargo\n-- \nfunction event_2463_21416()\n    \nend\n\n-- [EVENT] Lancement combat Grokoko\n-- \nfunction event_2463_21417()\n    \nend\n\n-- [EVENT] Lancement combat Corbac\n-- \nfunction event_2463_21409()\n    \nend\n\n-- [EVENT] Lancement combat Muloune\n-- \nfunction event_2463_21418()\n    \nend\n\n-- [EVENT] Lancement combat Long Brick\n-- \nfunction event_2463_21419()\n    \nend\n\n-- [EVENT] Lancement combat Chafer Elite\n-- \nfunction event_2463_21721()\n    \nend\n\n-- [EVENT] Lancement combat Mulmouth Enragé\n-- \nfunction event_2463_21722()\n    \nend\n\n-- [EVENT] Lancement combat Chuchoteur Porte-Etendard\n-- \nfunction event_2463_21723()\n    \nend\n\n-- [EVENT] Lancement combat Zespadon\n-- \nfunction event_2463_21724()\n    \nend\n\n-- [EVENT] Lancement combat Gros Smare\n-- \nfunction event_2463_21725()\n    \nend\n\n-- [EVENT] Lancement combat Abraknyde Ancestral\n-- \nfunction event_2463_21726()\n    \nend\n\n-- [EVENT] Lancement combat Cêpolourpode Ecrasant\n-- \nfunction event_2463_21727()\n    \nend\n\n-- [EVENT] Lancement combat Tiwallieuw Wabbit\n-- \nfunction event_2463_21728()\n    \nend\n\n-- [EVENT] Lancement combat Sramva\n-- \nfunction event_2463_21729()\n    \nend\n\n-- [EVENT] Lancement combat Lairdavan\n-- \nfunction event_2463_21730()\n    \nend\n\n-- [EVENT] Lancement combat Patapattes\n-- \nfunction event_2463_21731()\n    \nend\n\n-- [EVENT] Lancement combat Phéromane\n-- \nfunction event_2463_21732()\n    \nend\n\n-- [EVENT] Lancement combat Gerbouille\n-- \nfunction event_2463_21733()\n    \nend\n\n-- [EVENT] Lancement combat Gentibourg \n-- \nfunction event_2463_21734()\n    \nend\n\n-- [EVENT] Lancement combat Dragoeuf Guerrier\n-- \nfunction event_2463_21735()\n    \nend\n\n-- [EVENT] Lancement combat Loupin\n-- \nfunction event_2463_21736()\n    \nend\n\n-- [EVENT] Lancement combat Pinsulaire\n-- \nfunction event_2463_21410()\n    \nend\n\n-- [EVENT] Lancement combat Inanite\n-- \nfunction event_2463_21411()\n    \nend\n\n-- [EVENT] Lancement combat CeEvroaint\n-- \nfunction event_2463_21737()\n    \nend\n\n-- [EVENT] Lancement combat Rhinocéroc\n-- \nfunction event_2463_24290()\n    \nend\n\n-- [EVENT] Lancement combat Chimère veilleuse\n-- \nfunction event_2463_24291()\n    \nend\n\n-- [EVENT] Lancement combat 8 boss\n-- \nfunction event_2463_21738()\n    \nend\n\n-- FIGHT_ENTER_ACTION_PHASE - Applique l'état Caractéristiques Stasis sur tous les monstres\n-- \nfunction event_2463_21743()\n    \nend\n\n-- [EVENT] Inscription au scénario\n-- \nfunction event_2463_21744(randomAffixe)\n    trace(\"ENTER\", randomAffixe)\nend\n\n-- FIGHT_ENTER_ACTION_PHASE - No drop et no XP\n-- \nfunction event_2463_24292()\n    \nend\n\n-- [NEW][EVENT] Lancement combat sac à patates\n-- \nfunction event_2463_24312()\n    \nend\n\n","functions":["event_2463_21412","event_2463_21407","event_2463_21406","event_2463_21413","event_2463_21414","event_2463_21408","event_2463_21415","event_2463_21416","event_2463_21417","event_2463_21409","event_2463_21418","event_2463_21419","event_2463_21721","event_2463_21722","event_2463_21723","event_2463_21724","event_2463_21725","event_2463_21726","event_2463_21727","event_2463_21728","event_2463_21729","event_2463_21730","event_2463_21731","event_2463_21732","event_2463_21733","event_2463_21734","event_2463_21735","event_2463_21736","event_2463_21410","event_2463_21411","event_2463_21737","event_2463_24290","event_2463_24291","event_2463_21738","event_2463_21743","event_2463_21744","event_2463_24292","event_2463_24312"],"quest_calls":[],"dialogue_calls":[]},"scenario/2464.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\nbubbleFightInfoId = 0\r\n\r\nfunction closeFightInfo()\r\n\tif (bubbleFightInfoId ~= nil  and bubbleFightInfoId ~= 0) then BubbleText.close(bubbleFightInfoId) end\r\nend\r\n\r\nfunction onFightInfoClosed()\r\n\tif (bubbleFightInfoId ~= nil  and bubbleFightInfoId ~= 0) then bubbleFightInfoId = 0 end\r\nend\r\n\r\nfunction updateFightInfo(wave, difficulty, forceDisplayUI)\r\n\tlocal wave = toLong(wave)\r\n\tlocal difficulty = toLong(difficulty)\r\n\r\n\tif (bubbleFightInfoId == 0) then\r\n\t\tbubbleFightInfoId = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_WEST\", 0, -60, false, 2147483647, true, \"interactiveBubbleDialog5\", 30000, 25000, \"onFightInfoClosed\")\r\n\tend\r\n\r\n\tBubbleText.setText(bubbleFightInfoId, \"wave.fight.player.infos\", wave, difficulty)\r\n\r\n\tif (forceDisplayUI) then BubbleText.show(bubbleFightInfoId) end\r\nend\n\n-- [INIT] Variables globales\n-- \nfunction event_2464_21423()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2464_21424()\n    \nend\n\n-- [EVENT] Activation autel - Lancement du combat\n-- \nfunction event_2464_21425()\n    trace(\"LANCEMENT DU COMBAT\")\nend\n\n-- [EVENT] Démarrage du combat - Application états\n-- \nfunction event_2464_21426()\n    \nend\n\n-- [EVENT] NEW_MONSTER_WAVE - Difficulté\n-- \nfunction event_2464_21445(wave, difficulty)\n    updateFightInfo(wave, difficulty, true)\nend\n\n-- [EVENT] EFFECT_EXECUTION - Difficulté\n-- \nfunction event_2464_21451(wave, difficulty)\n    updateFightInfo(wave, difficulty, true)\nend\n\n-- [EVENT] FIGHT_ENDED_IN_CLIENT - On ferme l'affichage\n-- \nfunction event_2464_21456()\n    closeFightInfo()\nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","closeFightInfo","onFightInfoClosed","updateFightInfo","event_2464_21423","event_2464_21424","event_2464_21425","event_2464_21426","event_2464_21445","event_2464_21451","event_2464_21456"],"quest_calls":[],"dialogue_calls":[]},"scenario/2465.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\nbubbleFightInfoId = 0\r\n\r\nfunction closeFightInfo()\r\n\tif (bubbleFightInfoId ~= nil  and bubbleFightInfoId ~= 0) then BubbleText.close(bubbleFightInfoId) end\r\nend\r\n\r\nfunction onFightInfoClosed()\r\n\tif (bubbleFightInfoId ~= nil  and bubbleFightInfoId ~= 0) then bubbleFightInfoId = 0 end\r\nend\r\n\r\nfunction updateFightInfo(wave, difficulty, forceDisplayUI)\r\n\tlocal wave = toLong(wave)\r\n\tlocal difficulty = toLong(difficulty)\r\n\r\n\tif (bubbleFightInfoId == 0) then\r\n\t\tbubbleFightInfoId = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_WEST\", 0, -60, false, 2147483647, true, \"interactiveBubbleDialog5\", 30000, 25000, \"onFightInfoClosed\")\r\n\tend\r\n\r\n\tBubbleText.setText(bubbleFightInfoId, \"wave.fight.player.infos\", wave, difficulty)\r\n\r\n\tif (forceDisplayUI) then BubbleText.show(bubbleFightInfoId) end\r\nend\n\n-- [INIT] Variables globales\n-- \nfunction event_2465_21427()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2465_21428()\n    \nend\n\n-- [EVENT] Activation autel - Lancement du combat\n-- \nfunction event_2465_21429()\n    trace(\"LANCEMENT DU COMBAT\")\nend\n\n-- [EVENT] Démarrage du combat - Application états\n-- \nfunction event_2465_21430()\n    \nend\n\n-- [EVENT] NEW_MONSTER_WAVE - Difficulté\n-- \nfunction event_2465_21446(wave, difficulty)\n    updateFightInfo(wave, difficulty, true)\nend\n\n-- [EVENT] EFFECT_EXECUTION - Difficulté\n-- \nfunction event_2465_21452(wave, difficulty)\n    updateFightInfo(wave, difficulty, true)\nend\n\n-- [EVENT] FIGHT_ENDED_IN_CLIENT - On ferme l'affichage\n-- \nfunction event_2465_21457()\n    closeFightInfo()\nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","closeFightInfo","onFightInfoClosed","updateFightInfo","event_2465_21427","event_2465_21428","event_2465_21429","event_2465_21430","event_2465_21446","event_2465_21452","event_2465_21457"],"quest_calls":[],"dialogue_calls":[]},"scenario/2466.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\nbubbleFightInfoId = 0\r\n\r\nfunction closeFightInfo()\r\n\tif (bubbleFightInfoId ~= nil  and bubbleFightInfoId ~= 0) then BubbleText.close(bubbleFightInfoId) end\r\nend\r\n\r\nfunction onFightInfoClosed()\r\n\tif (bubbleFightInfoId ~= nil  and bubbleFightInfoId ~= 0) then bubbleFightInfoId = 0 end\r\nend\r\n\r\nfunction updateFightInfo(wave, difficulty, forceDisplayUI)\r\n\tlocal wave = toLong(wave)\r\n\tlocal difficulty = toLong(difficulty)\r\n\r\n\tif (bubbleFightInfoId == 0) then\r\n\t\tbubbleFightInfoId = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_WEST\", 0, -60, false, 2147483647, true, \"interactiveBubbleDialog5\", 30000, 25000, \"onFightInfoClosed\")\r\n\tend\r\n\r\n\tBubbleText.setText(bubbleFightInfoId, \"wave.fight.player.infos\", wave, difficulty)\r\n\r\n\tif (forceDisplayUI) then BubbleText.show(bubbleFightInfoId) end\r\nend\n\n-- [INIT] Variables globales\n-- \nfunction event_2466_21431()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2466_21432()\n    \nend\n\n-- [EVENT] Activation autel - Lancement du combat\n-- \nfunction event_2466_21433()\n    trace(\"LANCEMENT DU COMBAT\")\nend\n\n-- [EVENT] Démarrage du combat - Application états\n-- \nfunction event_2466_21434()\n    \nend\n\n-- [EVENT] NEW_MONSTER_WAVE - Difficulté\n-- \nfunction event_2466_21447(wave, difficulty)\n    updateFightInfo(wave, difficulty, true)\nend\n\n-- [EVENT] EFFECT_EXECUTION - Difficulté\n-- \nfunction event_2466_21453(wave, difficulty)\n    updateFightInfo(wave, difficulty, true)\nend\n\n-- [EVENT] FIGHT_ENDED_IN_CLIENT - On ferme l'affichage\n-- \nfunction event_2466_21458()\n    closeFightInfo()\nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","closeFightInfo","onFightInfoClosed","updateFightInfo","event_2466_21431","event_2466_21432","event_2466_21433","event_2466_21434","event_2466_21447","event_2466_21453","event_2466_21458"],"quest_calls":[],"dialogue_calls":[]},"scenario/2467.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\nbubbleFightInfoId = 0\r\n\r\nfunction closeFightInfo()\r\n\tif (bubbleFightInfoId ~= nil  and bubbleFightInfoId ~= 0) then BubbleText.close(bubbleFightInfoId) end\r\nend\r\n\r\nfunction onFightInfoClosed()\r\n\tif (bubbleFightInfoId ~= nil  and bubbleFightInfoId ~= 0) then bubbleFightInfoId = 0 end\r\nend\r\n\r\nfunction updateFightInfo(wave, difficulty, forceDisplayUI)\r\n\tlocal wave = toLong(wave)\r\n\tlocal difficulty = toLong(difficulty)\r\n\r\n\tif (bubbleFightInfoId == 0) then\r\n\t\tbubbleFightInfoId = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_WEST\", 0, -60, false, 2147483647, true, \"interactiveBubbleDialog5\", 30000, 25000, \"onFightInfoClosed\")\r\n\tend\r\n\r\n\tBubbleText.setText(bubbleFightInfoId, \"wave.fight.player.infos\", wave, difficulty)\r\n\r\n\tif (forceDisplayUI) then BubbleText.show(bubbleFightInfoId) end\r\nend\n\n-- [INIT] Variables globales\n-- \nfunction event_2467_21435()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2467_21436()\n    \nend\n\n-- [EVENT] Activation autel - Lancement du combat\n-- \nfunction event_2467_21437()\n    trace(\"LANCEMENT DU COMBAT\")\nend\n\n-- [EVENT] Démarrage du combat - Application états\n-- \nfunction event_2467_21438()\n    \nend\n\n-- [EVENT] NEW_MONSTER_WAVE - Difficulté\n-- \nfunction event_2467_21448(wave, difficulty)\n    updateFightInfo(wave, difficulty, true)\nend\n\n-- [EVENT] EFFECT_EXECUTION - Difficulté\n-- \nfunction event_2467_21454(wave, difficulty)\n    updateFightInfo(wave, difficulty, true)\nend\n\n-- [EVENT] FIGHT_ENDED_IN_CLIENT - On ferme l'affichage\n-- \nfunction event_2467_21459()\n    closeFightInfo()\nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","closeFightInfo","onFightInfoClosed","updateFightInfo","event_2467_21435","event_2467_21436","event_2467_21437","event_2467_21438","event_2467_21448","event_2467_21454","event_2467_21459"],"quest_calls":[],"dialogue_calls":[]},"scenario/2468.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\nbubbleFightInfoId = 0\r\n\r\nfunction closeFightInfo()\r\n\tif (bubbleFightInfoId ~= nil  and bubbleFightInfoId ~= 0) then BubbleText.close(bubbleFightInfoId) end\r\nend\r\n\r\nfunction onFightInfoClosed()\r\n\tif (bubbleFightInfoId ~= nil  and bubbleFightInfoId ~= 0) then bubbleFightInfoId = 0 end\r\nend\r\n\r\nfunction updateFightInfo(wave, difficulty, forceDisplayUI)\r\n\tlocal wave = toLong(wave)\r\n\tlocal difficulty = toLong(difficulty)\r\n\r\n\tif (bubbleFightInfoId == 0) then\r\n\t\tbubbleFightInfoId = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_WEST\", 0, -60, false, 2147483647, true, \"interactiveBubbleDialog5\", 30000, 25000, \"onFightInfoClosed\")\r\n\tend\r\n\r\n\tBubbleText.setText(bubbleFightInfoId, \"wave.fight.player.infos\", wave, difficulty)\r\n\r\n\tif (forceDisplayUI) then BubbleText.show(bubbleFightInfoId) end\r\nend\n\n-- [INIT] Variables globales\n-- \nfunction event_2468_21439()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2468_21440()\n    \nend\n\n-- [EVENT] Activation autel - Lancement du combat\n-- \nfunction event_2468_21441()\n    trace(\"LANCEMENT DU COMBAT\")\nend\n\n-- [EVENT] Démarrage du combat - Application états\n-- \nfunction event_2468_21442(wave, difficulty)\n    updateFightInfo(wave, difficulty, true)\nend\n\n-- [EVENT] NEW_MONSTER_WAVE - Difficulté\n-- \nfunction event_2468_21449(wave, difficulty)\n    updateFightInfo(wave, difficulty, true)\nend\n\n-- [EVENT] EFFECT_EXECUTION - Difficulté\n-- \nfunction event_2468_21670(wave, difficulty)\n    updateFightInfo(wave, difficulty, true)\nend\n\n-- [EVENT] FIGHT_ENDED_IN_CLIENT - On ferme l'affichage\n-- \nfunction event_2468_21460()\n    closeFightInfo()\nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","closeFightInfo","onFightInfoClosed","updateFightInfo","event_2468_21439","event_2468_21440","event_2468_21441","event_2468_21442","event_2468_21449","event_2468_21670","event_2468_21460"],"quest_calls":[],"dialogue_calls":[]},"scenario/2469.lua":{"source":"\n\n-- [INIT] Variables globales\n-- \nfunction event_2469_21482()\n    \nend\n\n-- [EVENT] ENTER_INSTANCE - Inscription scénario\n-- \nfunction event_2469_21469()\n    \nend\n\n-- [EVENT] ENTER_INSTANCE - Affichage des infos\n-- \nfunction event_2469_21470()\n    local playerId = Context.getLeaderId()\r\n    \r\n    Mobile.setMobileVisible(playerId, false)\r\n    invoke(3000, 1, \"animChute\")\r\n    \r\n    function animChute()\r\n    \tMobile.setMobileVisible(playerId, true)\r\n    \tMobile.setMobileDirection(playerId, 1)\r\n    \tMobile.setMobileAnimation(playerId, \"AnimIncarnam-Chute-Fin\")\r\n    \tUI.loadTutorialDialog(\"shushuPrison\", \"nation.prison.title\", \"shushu.prison.start\")\r\n    end\nend\n\n-- [EVENT] Le joueur rend les 50 caillasses - Peine terminée\n-- \nfunction event_2469_21471()\n    local playerId = Context.getLeaderId()\r\n    Mobile.setMobileAnimation(playerId, \"AnimEmote-Victoire\")\nend\n\n-- [EVENT] FIGHT_ENDED_IN_CLIENT - Peine terminée\n-- \nfunction event_2469_21488()\n    local playerId = Context.getLeaderId()\r\n    Mobile.setMobileAnimation(playerId, \"AnimEmote-Victoire\")\nend\n\n-- [EVENT] Le joueur utilise la porte de Cellule - Peine en cours\n-- \nfunction event_2469_21472()\n    local playerId = Context.getLeaderId()\r\n    Mobile.setMobileAnimation(playerId, \"AnimEmote-Non\")\nend\n\n-- [EVENT] DIALOG_EXECUTED - Le joueur veut miner\n-- \nfunction event_2469_21483()\n    \nend\n\n-- [EVENT] DIALOG_EXECUTED - Le joueur veut se battre\n-- \nfunction event_2469_21484()\n    \nend\n\n-- [EVENT] FIGHT_ENTER_ACTION_PHASE - Application états\n-- \nfunction event_2469_21489()\n    \nend\n\n","functions":["event_2469_21482","event_2469_21469","event_2469_21470","animChute","event_2469_21471","event_2469_21488","event_2469_21472","event_2469_21483","event_2469_21484","event_2469_21489"],"quest_calls":[],"dialogue_calls":[]},"scenario/2470.lua":{"source":"\n\n-- [EVENT] Application du mode standard\n-- \nfunction event_2470_21485()\n    \nend\n\n-- [EVENT] Application du mode permanent\n-- \nfunction event_2470_21486()\n    \nend\n\n-- [EVENT] Désactivation des bras\n-- \nfunction event_2470_21487()\n    \nend\n\n","functions":["event_2470_21485","event_2470_21486","event_2470_21487"],"quest_calls":[],"dialogue_calls":[]},"scenario/2471.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\nbubbleFightInfoId = 0\r\n\r\nfunction closeFightInfo()\r\n\tif (bubbleFightInfoId ~= nil  and bubbleFightInfoId ~= 0) then BubbleText.close(bubbleFightInfoId) end\r\nend\r\n\r\nfunction onFightInfoClosed()\r\n\tif (bubbleFightInfoId ~= nil  and bubbleFightInfoId ~= 0) then bubbleFightInfoId = 0 end\r\nend\r\n\r\nfunction updateFightInfo(wave, difficulty, forceDisplayUI)\r\n\tlocal wave = toLong(wave)\r\n\tlocal difficulty = toLong(difficulty)\r\n\r\n\tif (bubbleFightInfoId == 0) then\r\n\t\tbubbleFightInfoId = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_WEST\", 0, -60, false, 2147483647, true, \"interactiveBubbleDialog5\", 30000, 25000, \"onFightInfoClosed\")\r\n\tend\r\n\r\n\tBubbleText.setText(bubbleFightInfoId, \"wave.fight.player.infos\", wave, difficulty)\r\n\r\n\tif (forceDisplayUI) then BubbleText.show(bubbleFightInfoId) end\r\nend\n\n-- [INIT] Variables globales\n-- \nfunction event_2471_21490()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2471_21491()\n    \nend\n\n-- [EVENT] Activation autel - Lancement du combat\n-- \nfunction event_2471_21492()\n    trace(\"LANCEMENT DU COMBAT\")\nend\n\n-- [EVENT] Démarrage du combat - Application états\n-- \nfunction event_2471_21493()\n    \nend\n\n-- [EVENT] NEW_MONSTER_WAVE - Difficulté\n-- \nfunction event_2471_21494(wave, difficulty)\n    updateFightInfo(wave, difficulty, true)\nend\n\n-- [EVENT] EFFECT_EXECUTION - Difficulté\n-- \nfunction event_2471_21495(wave, difficulty)\n    updateFightInfo(wave, difficulty, true)\nend\n\n-- [EVENT] FIGHT_ENDED_IN_CLIENT - On ferme l'affichage\n-- \nfunction event_2471_21496()\n    closeFightInfo()\nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","closeFightInfo","onFightInfoClosed","updateFightInfo","event_2471_21490","event_2471_21491","event_2471_21492","event_2471_21493","event_2471_21494","event_2471_21495","event_2471_21496"],"quest_calls":[],"dialogue_calls":[]},"scenario/2472.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\nbubbleFightInfoId = 0\r\n\r\nfunction closeFightInfo()\r\n\tif (bubbleFightInfoId ~= nil  and bubbleFightInfoId ~= 0) then BubbleText.close(bubbleFightInfoId) end\r\nend\r\n\r\nfunction onFightInfoClosed()\r\n\tif (bubbleFightInfoId ~= nil  and bubbleFightInfoId ~= 0) then bubbleFightInfoId = 0 end\r\nend\r\n\r\nfunction updateFightInfo(wave, difficulty, forceDisplayUI)\r\n\tlocal wave = toLong(wave)\r\n\tlocal difficulty = toLong(difficulty)\r\n\r\n\tif (bubbleFightInfoId == 0) then\r\n\t\tbubbleFightInfoId = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_WEST\", 0, -60, false, 2147483647, true, \"interactiveBubbleDialog5\", 30000, 25000, \"onFightInfoClosed\")\r\n\tend\r\n\r\n\tBubbleText.setText(bubbleFightInfoId, \"wave.fight.player.infos\", wave, difficulty)\r\n\r\n\tif (forceDisplayUI) then BubbleText.show(bubbleFightInfoId) end\r\nend\n\n-- [INIT] Variables globales\n-- \nfunction event_2472_21497()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2472_21498()\n    \nend\n\n-- [EVENT] Activation autel - Lancement du combat\n-- \nfunction event_2472_21499()\n    trace(\"LANCEMENT DU COMBAT\")\nend\n\n-- [EVENT] Démarrage du combat - Application états\n-- \nfunction event_2472_21500()\n    \nend\n\n-- [EVENT] NEW_MONSTER_WAVE - Difficulté\n-- \nfunction event_2472_21501(wave, difficulty)\n    updateFightInfo(wave, difficulty, true)\nend\n\n-- [EVENT] EFFECT_EXECUTION - Difficulté\n-- \nfunction event_2472_21502(wave, difficulty)\n    updateFightInfo(wave, difficulty, true)\nend\n\n-- [EVENT] FIGHT_ENDED_IN_CLIENT - On ferme l'affichage\n-- \nfunction event_2472_21503()\n    closeFightInfo()\nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","closeFightInfo","onFightInfoClosed","updateFightInfo","event_2472_21497","event_2472_21498","event_2472_21499","event_2472_21500","event_2472_21501","event_2472_21502","event_2472_21503"],"quest_calls":[],"dialogue_calls":[]},"scenario/2473.lua":{"source":"-- Infos stèle d'intervention\r\nfunction updateInterventionInfo(stateInfoId, forceDisplayUI)\r\n\r\n\tif (bubbleSteleInfoId == 0) then\r\n\t\tbubbleSteleInfoId = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_WEST\", 0, -60, false, 2147483647, true, \"interactiveBubbleDialog5\", 30000, 25000, \"onSteleInfoClosed\")\r\n\tend\r\n\r\n\tBubbleText.setText(bubbleSteleInfoId, stateInfoId)\r\n\t\r\n\tif (forceDisplayUI) then BubbleText.show(bubbleSteleInfoId) end\r\nend\n\n-- [INIT] Variables Globales\n-- \nfunction event_2473_21507()\n    \nend\n\n-- [INIT] Inscription du joueur + Variables Locales\n-- \nfunction event_2473_21508(room)\n    \nend\n\n-- USER_GROUP_KILLED - Salle 01\n-- \nfunction event_2473_21509(room)\n    \nend\n\n-- USER_GROUP_KILLED - Salle 02 - BOSS\n-- \nfunction event_2473_21511()\n    \nend\n\n-- FIGHT_ENTER_ACTION_PHASE - Applique l'état \"Donjon\" (Salle 1)\n-- \nfunction event_2473_21538()\n    \nend\n\n-- FIGHT_ENTER_ACTION_PHASE - Applique l'état \"Donjon\" (Salle 2)\n-- \nfunction event_2473_21644()\n    \nend\n\n-- Déplace le joueur vers la salle suivante\n-- \nfunction event_2473_21512()\n    \nend\n\n-- INTERACTIVE_ELEMENT_ACTIVATION - Activation Stèle d'intervention\n-- \nfunction event_2473_21619()\n    UI.openRewardsDialog(\"stele.intervention.description.2\")\r\n    \r\n    UI.addReward(29418)\r\n    UI.addReward(29419)\r\n    UI.addReward(29420, \"stele.reward.stasis.21\")\r\n    \r\n    local stateInfoId = \"stele.intervention.anathar.description\"\r\n    \r\n    updateInterventionInfo(stateInfoId, true)\nend\n\n-- INTERACTIVE_ELEMENT_ACTIVATION - Le joueur examine la Stèle d'intervention\n-- \nfunction event_2473_21620()\n    UI.openRewardsDialog(\"stele.intervention.description.2\")\r\n    \r\n    UI.addReward(29418)\r\n    UI.addReward(29419)\r\n    UI.addReward(29420, \"stele.reward.stasis.21\")\r\n    \r\n    local stateInfoId = \"stele.intervention.anathar.description\"\r\n    \r\n    updateInterventionInfo(stateInfoId, true)\nend\n\n-- FIGHT_STARTED - Récupère l'ID du combat\n-- \nfunction event_2473_21621()\n    \nend\n\n-- FIGHT_ENDED - Réinitialise l'ID du combat\n-- \nfunction event_2473_21622()\n    \nend\n\n-- FIGHT_ENTER_ACTION_PHASE - Application état Anathar\n-- \nfunction event_2473_21623()\n    \nend\n\n-- [ARCHI] Apparition de l'Archimonstre\n-- \nfunction event_2473_24017()\n    \nend\n\n","functions":["updateInterventionInfo","event_2473_21507","event_2473_21508","event_2473_21509","event_2473_21511","event_2473_21538","event_2473_21644","event_2473_21512","event_2473_21619","event_2473_21620","event_2473_21621","event_2473_21622","event_2473_21623","event_2473_24017"],"quest_calls":["UI.openRewardsDialog(\"stele.intervention.description.2\")\r","UI.openRewardsDialog(\"stele.intervention.description.2\")\r"],"dialogue_calls":[]},"scenario/2474.lua":{"source":"\n\n-- [INIT] Variables Globales\n-- \nfunction event_2474_21513()\n    \nend\n\n-- [INIT] Inscription du joueur + Variables Locales\n-- \nfunction event_2474_21514(room)\n    \nend\n\n-- USER_GROUP_KILLED - Salle 01\n-- \nfunction event_2474_21515(room)\n    \nend\n\n-- USER_GROUP_KILLED - Salle 02 - BOSS\n-- \nfunction event_2474_21517()\n    \nend\n\n-- FIGHT_ENTER_ACTION_PHASE - Applique l'état \"Salle 1\"\n-- \nfunction event_2474_21539()\n    \nend\n\n-- Déplace le joueur vers la salle suivante\n-- \nfunction event_2474_21518()\n    \nend\n\n-- INTERACTIVE_ELEMENT_ACTIVATION - Activation Stèle d'intervention\n-- \nfunction event_2474_21624()\n    UI.openRewardsDialog(\"stele.intervention.description.2\")\r\n    \r\n    UI.addReward(29437)\r\n    UI.addReward(29441)\r\n    UI.addReward(29445, \"stele.reward.stasis.21\")\r\n    \r\n    local stateInfoId = \"stele.intervention.anathar.description\"\r\n    \r\n    updateInterventionInfo(stateInfoId, true)\nend\n\n-- INTERACTIVE_ELEMENT_ACTIVATION - Le joueur examine la Stèle d'intervention\n-- \nfunction event_2474_21625()\n    UI.openRewardsDialog(\"stele.intervention.description.2\")\r\n    \r\n    UI.addReward(29437)\r\n    UI.addReward(29441)\r\n    UI.addReward(29445, \"stele.reward.stasis.21\")\r\n    \r\n    local stateInfoId = \"stele.intervention.anathar.description\"\r\n    \r\n    updateInterventionInfo(stateInfoId, true)\nend\n\n-- FIGHT_STARTED - Récupère l'ID du combat\n-- \nfunction event_2474_21626()\n    \nend\n\n-- FIGHT_ENDED - Réinitialise l'ID du combat\n-- \nfunction event_2474_21627()\n    \nend\n\n-- FIGHT_ENTER_ACTION_PHASE - Application état Anathar\n-- \nfunction event_2474_21628()\n    \nend\n\n-- [ARCHI] Apparition de l'Archimonstre\n-- \nfunction event_2474_24018()\n    \nend\n\n","functions":["event_2474_21513","event_2474_21514","event_2474_21515","event_2474_21517","event_2474_21539","event_2474_21518","event_2474_21624","event_2474_21625","event_2474_21626","event_2474_21627","event_2474_21628","event_2474_24018"],"quest_calls":["UI.openRewardsDialog(\"stele.intervention.description.2\")\r","UI.openRewardsDialog(\"stele.intervention.description.2\")\r"],"dialogue_calls":[]},"scenario/2475.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\n\n-- [INIT] Variables Globales\n-- \nfunction event_2475_21519()\n    \nend\n\n-- [INIT] Inscription du joueur + Variables Locales\n-- \nfunction event_2475_21520(room)\n    \nend\n\n-- USER_GROUP_KILLED - Salle 01\n-- \nfunction event_2475_21521(room)\n    \nend\n\n-- USER_GROUP_KILLED - Salle 02 - BOSS\n-- \nfunction event_2475_21523()\n    \nend\n\n-- FIGHT_ENTER_ACTION_PHASE - Applique l'état \"Salle 1\"\n-- \nfunction event_2475_21540()\n    \nend\n\n-- Déplace le joueur vers la salle suivante\n-- \nfunction event_2475_21524()\n    \nend\n\n-- FIGHT_ENDED_IN_CLIENT - cinématique quête\n-- \nfunction event_2475_21587()\n    local playerId = Context.getLeaderId()\r\n    local kaliId = createActor(187204217, -41, -9, 16, 4, 3, 8)\r\n    local craterosId = createActor(1107705289, -47, 0, 16, 8, 1, 8)\r\n    \r\n    function customSkip()\r\n    \tUI.displayWideScreenBand(true, 25, 300)\r\n    \tskipCinematic(21587)\r\n    end\r\n    \r\n    startCinematicContext(1.4, playerId)\r\n    \r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"customSkip\")\r\n    \r\n    invoke_custom(00100, 1, \"Mobile.setMobileDirection\", playerId, 5)\r\n    invoke_custom(00010, 1, \"Mobile.setMobileVisible\", kaliId, false)\r\n    invoke_custom(00010, 1, \"Mobile.setMobileAnimationSuffix\", kaliId, \"-Agressive\")\r\n    invoke_custom(00010, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimStatique02\")\r\n    invoke_custom(00500, 1, \"Mobile.setMobileVisible\", kaliId, true)\r\n    \r\n    invoke_custom(00800, 1, \"Mobile.moveMobile\", kaliId, -47, -1, 16, \"Mobile.setMobileDirection\", kaliId, 3)\r\n    invoke_custom(02000, 1, \"Mobile.setMobileDirection\", craterosId, 7)\r\n    \r\n    -- \"Coucou ! Comme on se retrouve !\"\r\n    invoke_custom(03500, 1, \"bubble\", kaliId, \"quest.shukrute.03.14\")\r\n    invoke_custom(06000, 1, \"clearBubbles\", kaliId)\r\n    \r\n    -- \"TU VAS PAYER !\"\r\n    invoke_custom(06300, 1, \"bubble\", kaliId, \"quest.shukrute.03.15\")\r\n    invoke_custom(06300, 1, \"Mobile.setMobileAnimation\", kaliId, \"AnimSort-Punition\")\r\n    invoke_custom(06600, 1, \"Particle.addParticleSystem\", -1871059314, -47, 0, 16)\r\n    invoke_custom(07500, 1, \"Mobile.setMobileAnimation\", craterosId, \"AnimMort\")\r\n    invoke_custom(07600, 1, \"UI.displayFlyingText\", 1, 0.4, 0.1, \"lstw\", craterosId, \"finish.move.damage\", 0, 55, -9999)\r\n    invoke_custom(09000, 1, \"clearBubbles\", kaliId)\r\n    \r\n    invoke_custom(09000, 1, \"UI.displayWideScreenBand\", true, 100, 300)\r\n    invoke_custom(11400, 1, \"Mobile.setMobileAnimationSuffix\", kaliId, \"\")\r\n    invoke_custom(11400, 1, \"Mobile.setMobilePosition\", kaliId, -47, 0, 16)\r\n    invoke_custom(11400, 1, \"Mobile.setMobileDirection\", kaliId, 1)\r\n    invoke_custom(11400, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimStatique\")\r\n    \r\n    invoke_custom(11500, 1, \"UI.displayWideScreenBand\", true, 25, 300)\r\n    \r\n    -- \"Ah, ça fait du bien de défouler ses nerfs.\"\r\n    invoke_custom(12000, 1, \"bubble\", kaliId, \"quest.shukrute.03.16\")\r\n    invoke_custom(12000, 1, \"Mobile.setMobileAnimation\", kaliId, \"AnimComp-Parler02\")\r\n    invoke_custom(15000, 1, \"clearBubbles\", kaliId)\r\n    \r\n    -- \"Et j'ai récupéré ce qui me m'appartenait.\"\r\n    invoke_custom(15500, 1, \"bubble\", kaliId, \"quest.shukrute.03.17\")\r\n    invoke_custom(15500, 1, \"Mobile.setMobileAnimation\", kaliId, \"AnimComp-Parler01\")\r\n    invoke_custom(18500, 1, \"clearBubbles\", kaliId)\r\n    \r\n    -- \"Tout est bien qui finit bien, alors ?\"\r\n    invoke_custom(19000, 1, \"bubble\", playerId, \"quest.shukrute.03.18\")\r\n    invoke_custom(19000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Presenter\")\r\n    invoke_custom(22000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"M'oui, il reste quand même encore un petit problème....\"\r\n    invoke_custom(22000, 1, \"bubble\", kaliId, \"quest.shukrute.03.19\")\r\n    invoke_custom(22000, 1, \"Mobile.setMobileAnimation\", kaliId, \"AnimComp-Non\")\r\n    invoke_custom(26500, 1, \"clearBubbles\", kaliId)\r\n    \r\n    -- \"Le fait que tu sois encore en vie ! Hahaha !\"\r\n    invoke_custom(27000, 1, \"bubble\", kaliId, \"quest.shukrute.03.20\")\r\n    invoke_custom(27000, 1, \"Mobile.setMobileAnimation\", kaliId, \"AnimComp-Rire\")\r\n    invoke_custom(30500, 1, \"clearBubbles\", kaliId)\r\n    \r\n    -- \"...\"\r\n    invoke_custom(30000, 1, \"bubble\", playerId, \"quest.shukrute.03.21\")\r\n    invoke_custom(30000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(32500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"J'dois dire que t'es tenace pour une limace !\"\r\n    invoke_custom(31000, 1, \"bubble\", kaliId, \"quest.shukrute.03.22\")\r\n    invoke_custom(31000, 1, \"Mobile.setMobileAnimation\", kaliId, \"AnimComp-Provoc\")\r\n    invoke_custom(34000, 1, \"clearBubbles\", kaliId)\r\n    \r\n    -- \"Allez, fichons le camp d'ici !\"\r\n    invoke_custom(34500, 1, \"bubble\", kaliId, \"quest.shukrute.03.23\")\r\n    invoke_custom(34500, 1, \"Mobile.setMobileAnimation\", kaliId, \"AnimComp-Parler02\")\r\n    invoke_custom(37500, 1, \"clearBubbles\", kaliId)\r\n    \r\n    invoke_custom(38000, 1, \"UI.displayWideScreenBand\", true, 100, 300)\r\n    \r\n    invoke_custom(41000, 1, \"customSkip\")\nend\n\n-- INTERACTIVE_ELEMENT_ACTIVATION - Activation Stèle d'intervention\n-- \nfunction event_2475_21629()\n    UI.openRewardsDialog(\"stele.intervention.description.2\")\r\n    \r\n    UI.addReward(29438)\r\n    UI.addReward(29442)\r\n    UI.addReward(29446, \"stele.reward.stasis.21\")\r\n    \r\n    local stateInfoId = \"stele.intervention.anathar.description\"\r\n    \r\n    updateInterventionInfo(stateInfoId, true)\nend\n\n-- INTERACTIVE_ELEMENT_ACTIVATION - Le joueur examine la Stèle d'intervention\n-- \nfunction event_2475_21630()\n    UI.openRewardsDialog(\"stele.intervention.description.2\")\r\n    \r\n    UI.addReward(29438)\r\n    UI.addReward(29442)\r\n    UI.addReward(29446, \"stele.reward.stasis.21\")\r\n    \r\n    local stateInfoId = \"stele.intervention.anathar.description\"\r\n    \r\n    updateInterventionInfo(stateInfoId, true)\nend\n\n-- FIGHT_STARTED - Récupère l'ID du combat\n-- \nfunction event_2475_21631()\n    \nend\n\n-- FIGHT_ENDED - Réinitialise l'ID du combat\n-- \nfunction event_2475_21632()\n    \nend\n\n-- FIGHT_ENTER_ACTION_PHASE - Application état Anathar\n-- \nfunction event_2475_21633()\n    \nend\n\n-- [ARCHI] Apparition de l'Archimonstre\n-- \nfunction event_2475_24019()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_2475_21519","event_2475_21520","event_2475_21521","event_2475_21523","event_2475_21540","event_2475_21524","event_2475_21587","customSkip","event_2475_21629","event_2475_21630","event_2475_21631","event_2475_21632","event_2475_21633","event_2475_24019"],"quest_calls":["UI.openRewardsDialog(\"stele.intervention.description.2\")\r","UI.openRewardsDialog(\"stele.intervention.description.2\")\r"],"dialogue_calls":[]},"scenario/2476.lua":{"source":"apsId = 800912\r\napsOneId = 0\r\napsTwoId = 0\r\napsThreeId = 0\r\n\r\nfunction displayDoor()\r\n\tapsOneId = Particle.addParticleSystem(apsId, -1, -23, -2)\r\n\tapsTwoId = Particle.addParticleSystem(apsId, 0, -23, -2)\r\n\tapsThreeId = Particle.addParticleSystem(apsId, 1, -23, -2)\r\nend\r\n\r\nfunction hideDoor()\r\n\tParticle.removeParticleSystem(apsOneId)\r\n\tParticle.removeParticleSystem(apsTwoId)\r\n\tParticle.removeParticleSystem(apsThreeId)\r\nend\n\n-- [INIT] Variables Globales\n-- \nfunction event_2476_21525()\n    \nend\n\n-- [INIT] Inscription du joueur + Variables Locales\n-- \nfunction event_2476_21526(room)\n    displayDoor()\nend\n\n-- USER_GROUP_KILLED - Salle 01\n-- \nfunction event_2476_21527(room)\n    hideDoor()\nend\n\n-- USER_GROUP_KILLED - Salle 02 - BOSS\n-- \nfunction event_2476_21529()\n    \nend\n\n-- FIGHT_ENTER_ACTION_PHASE - Applique l'état \"Salle 1\"\n-- \nfunction event_2476_21541()\n    \nend\n\n-- Déplace le joueur vers la salle suivante\n-- \nfunction event_2476_21530()\n    \nend\n\n-- INTERACTIVE_ELEMENT_ACTIVATION - Activation Stèle d'intervention\n-- \nfunction event_2476_21634()\n    UI.openRewardsDialog(\"stele.intervention.description.2\")\r\n    \r\n    UI.addReward(29439)\r\n    UI.addReward(29443)\r\n    UI.addReward(29447, \"stele.reward.stasis.21\")\r\n    \r\n    local stateInfoId = \"stele.intervention.anathar.description\"\r\n    \r\n    updateInterventionInfo(stateInfoId, true)\nend\n\n-- INTERACTIVE_ELEMENT_ACTIVATION - Le joueur examine la Stèle d'intervention\n-- \nfunction event_2476_21635()\n    UI.openRewardsDialog(\"stele.intervention.description.2\")\r\n    \r\n    UI.addReward(29439)\r\n    UI.addReward(29443)\r\n    UI.addReward(29447, \"stele.reward.stasis.21\")\r\n    \r\n    local stateInfoId = \"stele.intervention.anathar.description\"\r\n    \r\n    updateInterventionInfo(stateInfoId, true)\nend\n\n-- FIGHT_STARTED - Récupère l'ID du combat\n-- \nfunction event_2476_21636()\n    \nend\n\n-- FIGHT_ENDED - Réinitialise l'ID du combat\n-- \nfunction event_2476_21637()\n    \nend\n\n-- FIGHT_ENTER_ACTION_PHASE - Application état Anathar\n-- \nfunction event_2476_21638()\n    \nend\n\n-- EFFECT_EXECUTION - Boss passé marionette en premier\n-- \nfunction event_2476_21671()\n    \nend\n\n-- EFFECT_EXECUTION - Monstre passé marionette en premier\n-- \nfunction event_2476_21672()\n    \nend\n\n-- FIGHT_ENDED_IN_CLIENT_EVENT - Victoire alors que le boss a été passé marionette en premier\n-- \nfunction event_2476_21673()\n    \nend\n\n-- EFFECT_EXECUTION - Boss passé marionette en dernier \n-- \nfunction event_2476_21674()\n    \nend\n\n-- [ARCHI] Apparition de l'Archimonstre\n-- \nfunction event_2476_24020()\n    \nend\n\n","functions":["displayDoor","hideDoor","event_2476_21525","event_2476_21526","event_2476_21527","event_2476_21529","event_2476_21541","event_2476_21530","event_2476_21634","event_2476_21635","event_2476_21636","event_2476_21637","event_2476_21638","event_2476_21671","event_2476_21672","event_2476_21673","event_2476_21674","event_2476_24020"],"quest_calls":["UI.openRewardsDialog(\"stele.intervention.description.2\")\r","UI.openRewardsDialog(\"stele.intervention.description.2\")\r"],"dialogue_calls":[]},"scenario/2477.lua":{"source":"\n\n-- [INIT] Variables Globales\n-- \nfunction event_2477_21531()\n    \nend\n\n-- [INIT] Inscription du joueur + Variables Locales\n-- \nfunction event_2477_21532(room)\n    \nend\n\n-- USER_GROUP_KILLED - Salle 01\n-- \nfunction event_2477_21533(room)\n    \nend\n\n-- USER_GROUP_KILLED - Salle 02 - BOSS\n-- \nfunction event_2477_21535()\n    \nend\n\n-- Déplace le joueur vers la salle suivante\n-- \nfunction event_2477_21536()\n    \nend\n\n-- INTERACTIVE_ELEMENT_ACTIVATION - Activation Stèle d'intervention\n-- \nfunction event_2477_21639()\n    UI.openRewardsDialog(\"stele.intervention.description.2\")\r\n    \r\n    UI.addReward(29440)\r\n    UI.addReward(29444)\r\n    UI.addReward(29448, \"stele.reward.stasis.21\")\r\n    \r\n    local stateInfoId = \"stele.intervention.anathar.description\"\r\n    \r\n    updateInterventionInfo(stateInfoId, true)\nend\n\n-- INTERACTIVE_ELEMENT_ACTIVATION - Le joueur examine la Stèle d'intervention\n-- \nfunction event_2477_21640()\n    UI.openRewardsDialog(\"stele.intervention.description.2\")\r\n    \r\n    UI.addReward(29440)\r\n    UI.addReward(29444)\r\n    UI.addReward(29448, \"stele.reward.stasis.21\")\r\n    \r\n    local stateInfoId = \"stele.intervention.anathar.description\"\r\n    \r\n    updateInterventionInfo(stateInfoId, true)\nend\n\n-- FIGHT_STARTED - Récupère l'ID du combat\n-- \nfunction event_2477_21641()\n    \nend\n\n-- FIGHT_ENDED - Réinitialise l'ID du combat\n-- \nfunction event_2477_21642()\n    \nend\n\n-- FIGHT_ENTER_ACTION_PHASE - Application état Anathar\n-- \nfunction event_2477_21643()\n    \nend\n\n-- [ARCHI] Apparition de l'Archimonstre\n-- \nfunction event_2477_24021()\n    \nend\n\n","functions":["event_2477_21531","event_2477_21532","event_2477_21533","event_2477_21535","event_2477_21536","event_2477_21639","event_2477_21640","event_2477_21641","event_2477_21642","event_2477_21643","event_2477_24021"],"quest_calls":["UI.openRewardsDialog(\"stele.intervention.description.2\")\r","UI.openRewardsDialog(\"stele.intervention.description.2\")\r"],"dialogue_calls":[]},"scenario/2478.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\n\n-- [INIT] Variables\n-- \nfunction event_2478_21542()\n    \nend\n\n-- [EVENT] Cinématique Arrivée - Explication\n-- \nfunction event_2478_21543(arhKayuh)\n    local playerId = Context.getLeaderId()\r\n    local arhKayuhId  = toLong(arhKayuh)\r\n    \r\n    ----------------------------- CINEMATIQUE -----------------------------\r\n    \r\n    startCinematicContext(1.0, arhKayuhId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 21543)\r\n    \r\n    invoke_custom(01100, 1, \"Mobile.setMobileDirection\", playerId, 5)\r\n    \r\n    -- \"C'est la première fois que tu viens ici ?\"\r\n    invoke_custom(02500, 1, \"bubble\", arhKayuhId, \"shukrute.hub.dialog.00\")\r\n    invoke_custom(02500, 1, \"Sound.playSound\", 320000000001007, true, 40)\r\n    invoke_custom(07000, 1, \"clearBubbles\", arhKayuhId)\r\n    \r\n    -- \"Prends garde, car deux chemins s'offrent à toi.\"\r\n    invoke_custom(07500, 1, \"bubble\", arhKayuhId, \"shukrute.hub.dialog.01\")\r\n    invoke_custom(07500, 1, \"Sound.playSound\", 320000000001008, true, 40)\r\n    invoke_custom(13000, 1, \"clearBubbles\", arhKayuhId)\r\n    \r\n    invoke_custom(13500, 1, \"Camera.setCamera\", 1.0, -5, -20, 4)\r\n    invoke_custom(16500, 1, \"Camera.setCamera\", 1.0, 5, -24, 4)\r\n    \r\n    -- \"Ici se trouve le territoire de Sthulhu.\"\r\n    invoke_custom(16500, 1, \"bubble\", arhKayuhId, \"shukrute.hub.dialog.02\")\r\n    invoke_custom(16500, 1, \"Sound.playSound\", 320000000001009, true, 40)\r\n    invoke_custom(20000, 1, \"clearBubbles\", arhKayuhId)\r\n    \r\n    -- \"Tu pourras t'y mesurer à Spectrex et Mihmol.\"\r\n    invoke_custom(20500, 1, \"bubble\", arhKayuhId, \"shukrute.hub.dialog.03\")\r\n    invoke_custom(20500, 1, \"Sound.playSound\", 320000000001010, true, 40)\r\n    invoke_custom(24000, 1, \"clearBubbles\", arhKayuhId)\r\n    \r\n    invoke_custom(24000, 1, \"Camera.setCamera\", 1.0, 6, -30, 12)\r\n    invoke_custom(27000, 1, \"Camera.setCamera\", 1.0, 5, -24, 4)\r\n    \r\n    -- \"L'autre portail mène à la Croisée des âmes déchues.\"\r\n    invoke_custom(27500, 1, \"bubble\", arhKayuhId, \"shukrute.hub.dialog.04\")\r\n    invoke_custom(27500, 1, \"Sound.playSound\", 320000000001008, true, 40)\r\n    invoke_custom(30500, 1, \"clearBubbles\", arhKayuhId)\r\n    \r\n    -- \"Tu peux y trouver cinq redoutables familles démoniaques.\"\r\n    invoke_custom(31000, 1, \"bubble\", arhKayuhId, \"shukrute.hub.dialog.05\")\r\n    invoke_custom(31000, 1, \"Sound.playSound\", 320000000001007, true, 40)\r\n    invoke_custom(34500, 1, \"clearBubbles\", arhKayuhId)\r\n    \r\n    -- \"Cette zone est réservée aux aventuriers très aguerris...\"\r\n    invoke_custom(35000, 1, \"bubble\", arhKayuhId, \"shukrute.hub.dialog.06\")\r\n    invoke_custom(35000, 1, \"Sound.playSound\", 320000000001010, true, 40)\r\n    invoke_custom(38500, 1, \"clearBubbles\", arhKayuhId)\r\n    \r\n    invoke_custom(38700, 1, \"skipCinematic\", 21543)\nend\n\n-- [EVENT] Cinématique Arrivée - Validation\n-- \nfunction event_2478_21544()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_2478_21542","event_2478_21543","event_2478_21544"],"quest_calls":[],"dialogue_calls":[]},"scenario/2479.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\nbubbleFightInfoId = 0\r\n\r\n-- Fonction porte\r\nfunction displayDoor(doorOpened, rushuFightWon)\r\n\tlocal door = toLong(doorOpened)\r\n\tlocal fight = toLong(rushuFightWon)\r\n\r\n\tif (door == 1) then\r\n\t\tWorld.setPictoAlpha(-19, 7, 11, 0, 1000)\r\n\telse\r\n\t\tWorld.setPictoAlpha(-19, 7, 11, 1, 1000)\r\n\tend\r\n\r\n\tif (fight == 1) then\r\n\t\tWorld.setPictoAlpha(-19, 7, 11, 1, 1000)\r\n\tend\r\nend\r\n\r\n-- Fonctions cache / montre Rushu\r\nfunction hideMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, false)\r\nend\r\n\r\nfunction showMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, true)\r\nend\r\n\r\n-- Fonctions score & vestiges\r\nfunction onFightInfoClosed()\r\n\tif (bubbleFightInfoId ~= nil  and bubbleFightInfoId ~= 0) then bubbleFightInfoId = 0 end\r\nend\r\n\r\nfunction updateFightInfo(rushuId, teamDamage, vestige1, vestige2, vestige3, vestige4, vestige5, vestige6, vestige7, vestige8, vestige9, vestige10, vestige11, vestige12, vestige13, vestige14, vestige15, vestige16, forceDisplayUI)\r\n\tlocal rushuId = toLong(rushuId)\r\n\tlocal teamDamage = toLong(teamDamage)\r\n\tlocal vestige1 = toLong(vestige1)\r\n\tlocal vestige2 = toLong(vestige2)\r\n\tlocal vestige3 = toLong(vestige3)\r\n\tlocal vestige4 = toLong(vestige4)\r\n\tlocal vestige5 = toLong(vestige5)\r\n\tlocal vestige6 = toLong(vestige6)\r\n\tlocal vestige7 = toLong(vestige7)\r\n\tlocal vestige8 = toLong(vestige8)\r\n\tlocal vestige9 = toLong(vestige9)\r\n\tlocal vestige10 = toLong(vestige10)\r\n\tlocal vestige11 = toLong(vestige11)\r\n\tlocal vestige12 = toLong(vestige12)\r\n\tlocal vestige13 = toLong(vestige13)\r\n\tlocal vestige14 = toLong(vestige14)\r\n\tlocal vestige15 = toLong(vestige15)\r\n\tlocal vestige16 = toLong(vestige16)\r\n \r\n\tif (bubbleFightInfoId == 0) then\r\n\t\tbubbleFightInfoId = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_WEST\", 0, -60, false, 2147483647, true, \"interactiveBubbleDialog5\", 30000, 25000, \"onFightInfoClosed\")\r\n\tend\r\n\r\n\tBubbleText.setText(bubbleFightInfoId, \"rushu.fight.player.infos\", teamDamage, vestige1, vestige2, vestige3, vestige4, vestige5, vestige6, vestige7, vestige8, vestige9, vestige10, vestige11, vestige12, vestige13, vestige14, vestige15, vestige16)\r\n\t\r\n\tif (forceDisplayUI) then BubbleText.show(bubbleFightInfoId) end\r\nend\n\n-- Variables globales (vestiges etc.)\n-- \nfunction event_2479_21545()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2479_21546(rushuId, cineDone, doorOpened, rushuFightWon)\n    displayDoor(doorOpened, rushuFightWon)\r\n    \r\n    local cine = toLong(cineDone)\r\n    \r\n    if cine == 0 then\r\n    \tMobile.addMobileCreationCallback(rushuId, \"hideMonster\", rushuId)\r\n    else\r\n    end\nend\n\n-- INTERACTIVE_ELEMENT_ACTIVATION - Ouverture de la porte\n-- \nfunction event_2479_21547(doorOpened, rushuFightWon)\n    trace(\"OUVERTURE DE LA PORTE\")\r\n    \r\n    displayDoor(doorOpened, rushuFightWon)\nend\n\n-- POSITION_TRIGGER_ACTIVATION - Le boss apparaît (déjà vaincu)\n-- \nfunction event_2479_21573(rushuId)\n    local playerId = Context.getLeaderId()\r\n    local bossId = toLong(rushuId)\r\n    \r\n    startCinematicContext(1.0, playerId)\r\n    \r\n    invoke_custom(0000, 1, \"Camera.setCamera\", 1, -49, 7, 4)\r\n    invoke_custom(1999, 1, \"Mobile.addMobileCreationCallback\", rushuId, \"showMonster\", rushuId)\r\n    invoke_custom(2000, 1, \"Particle.addParticleSystem\", -1453072821, -49, 7, -4)\r\n    invoke_custom(1900, 1, \"Mobile.setMobileAnimation\", bossId, \"AnimSort-Bond-Fin\")\r\n    invoke_custom(2000, 1, \"Effect.createCameraShakeEffect\", 100, 500, 100, 5, 100, \"BOTH\")\r\n    invoke_custom(2900, 1, \"Mobile.setMobileAnimation\", bossId, \"AnimComp-3\")\r\n    invoke_custom(4400, 1, \"Camera.attachCameraToMobile\", playerId)\r\n    \r\n    invoke_custom(4400, 1, \"skipCinematic\")\nend\n\n-- POSITION_TRIGGER_ACTIVATION - Le boss apparaît (jamais vaincu)\n-- \nfunction event_2479_21697(rushuId)\n    local playerId = Context.getLeaderId()\r\n    local bossId = toLong(rushuId)\r\n    \r\n    Mobile.addMobileCreationCallback(rushuId, \"showMonster\", rushuId)\r\n    Mobile.setMobilePosition(bossId, -54, 8, 58)\r\n    Mobile.setMobileAnimation(bossId, \"AnimComp-1\")\r\n    \r\n    startCinematicContext(1.0, playerId)\r\n    \r\n    invoke_custom(0000, 1, \"Camera.setCamera\", 1, -54, 8, 58)\r\n    \r\n    -- \"Des mortels, dans mon palais ?!!\"\r\n    invoke_custom(0999, 1, \"Sound.playSound\", 90000082, true, 40)\r\n    invoke_custom(0999, 1, \"bubble\", bossId, \"rushu.fight.start.dialog.01\")\r\n    invoke_custom(3200, 1, \"clearBubbles\", bossId)\r\n    \r\n    -- \"Vous cherchez l'affrontement...\"\r\n    invoke_custom(3500, 1, \"Sound.playSound\", 90000085, true, 40)\r\n    invoke_custom(3500, 1, \"bubble\", bossId, \"rushu.fight.start.dialog.02\")\r\n    invoke_custom(5000, 1, \"Mobile.setMobileAnimation\", bossId, \"AnimComp-2\")\r\n    invoke_custom(5200, 1, \"clearBubbles\", bossId)\r\n    invoke_custom(5700, 1, \"Camera.setCamera\", 1, -49, 7, -4)\r\n    \r\n    invoke_custom(5999, 1, \"Mobile.setMobilePosition\", bossId, -49, 7, -4)\r\n    invoke_custom(6000, 1, \"Mobile.setMobileAnimation\", bossId, \"AnimSort-Bond-Fin\")\r\n    invoke_custom(6100, 1, \"Particle.addParticleSystem\", -1453072821, -49, 7, -4)\r\n    invoke_custom(6000, 1, \"Effect.createCameraShakeEffect\", 100, 500, 100, 5, 100, \"BOTH\")\r\n    \r\n    -- \"PARFAIT, ÇA ME FERA UN PEU D'EXERCICE !\"\r\n    invoke_custom(6500, 1, \"Sound.playSound\", 90000083, true, 40)\r\n    invoke_custom(6500, 1, \"bubble\", bossId, \"rushu.fight.start.dialog.03\")\r\n    invoke_custom(7000, 1, \"Mobile.setMobileAnimation\", bossId, \"AnimComp-3\")\r\n    invoke_custom(8500, 1, \"clearBubbles\", bossId)\r\n    invoke_custom(9000, 1, \"Camera.attachCameraToMobile\", playerId)\r\n    \r\n    invoke_custom(9001, 1, \"skipCinematic\")\nend\n\n-- MONSTER_ACTION_EVENT - Lancement du combat\n-- \nfunction event_2479_21701()\n    \nend\n\n-- FIGHT_STARTED - Initialisation des variables\n-- \nfunction event_2479_21570()\n    \nend\n\n-- FIGHT_STARTED - Pose des zones\n-- \nfunction event_2479_21686()\n    \nend\n\n-- EFFECT_EXECUTION - Mise à jour UI infos de combat (score)\n-- \nfunction event_2479_21571(rushuId, teamDamage, vestige1, vestige2, vestige3, vestige4, vestige5, vestige6, vestige7, vestige8, vestige9, vestige10, vestige11, vestige12, vestige13, vestige14, vestige15, vestige16)\n    updateFightInfo(rushuId, teamDamage, vestige1, vestige2, vestige3, vestige4, vestige5, vestige6, vestige7, vestige8, vestige9, vestige10, vestige11, vestige12, vestige13, vestige14, vestige15, vestige16, true)\nend\n\n-- EFFECT_EXECUTION - Mise à jour UI infos de combat (tour)\n-- \nfunction event_2479_21685(rushuId, teamDamage, vestige1, vestige2, vestige3, vestige4, vestige5, vestige6, vestige7, vestige8, vestige9, vestige10, vestige11, vestige12, vestige13, vestige14, vestige15, vestige16)\n    updateFightInfo(rushuId, teamDamage, vestige1, vestige2, vestige3, vestige4, vestige5, vestige6, vestige7, vestige8, vestige9, vestige10, vestige11, vestige12, vestige13, vestige14, vestige15, vestige16, true)\nend\n\n-- USER_GROUP_KILLED - Enregistrement au classement\n-- \nfunction event_2479_21687(doorOpened, rushuFightWon)\n    displayDoor(doorOpened, rushuFightWon)\nend\n\n-- FIGHT_ENDED_IN_CLIENT_EVENT - Le joueur perd\n-- \nfunction event_2479_21699(teamDamage)\n    local teamDamage = toString(teamDamage)\r\n    \r\n    UI.setWidgetEnabled(\"fightResultDialog\", \"rootContainer\", true)\r\n    UI.setWidgetVisibility(\"fightResultDialog\", \"rootContainer\", true)\r\n    \r\n    local text = Event.getKeyTranslation(\"fight.score.ogrest\", teamDamage)\r\n    UI.setPropertyStringValue(\"fight.score.ogrest\", text)\r\n    UI.writeLocalisedInChat(\"ogrest.fight.team.score\", teamDamage)\r\n    \r\n    UI.removeUnremovableDialog(\"fightResultDialog\")\r\n    \r\n    UI.addDialogUnloadedListener(\"fightResultDialog\", \"UI.removeProperty\", \"fight.score.ogrest\")\nend\n\n-- FIGHT_ENDED_IN_CLIENT_EVENT - Le joueur gagne - Lancement Vidéo Victoire\n-- \nfunction event_2479_21700()\n    trace(\"CINÉMATIQUE DE VICTOIRE\")\r\n    \r\n    Sound.stopForcedMusic()\r\n    Mobile.hideOtherPlayerMobile(true)\r\n    \r\n    local playerId = Context.getLeaderId()\r\n    Mobile.setMobilePosition(playerId, -40, 7, -4)\r\n    Mobile.setMobileDirection(playerId, 5)\r\n    Mobile.setMobileAnimation(playerId, \"AnimStatique02\")\r\n    \r\n    local rushuId = createActor(1108305306, -44, 7, -4, 4, 1, 28)\r\n    \r\n    ---------------------------------\r\n    \t\r\n    startCinematicContext(1.0, rushuId, 290160)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 21700)\r\n    \r\n    invoke_custom(00100, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimStatique02\")\r\n    invoke_custom(01000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimStatique02\")\r\n    \r\n    -- \"TU ES À COURT D'OPTIONS.\"\r\n    invoke_custom(01000, 1, \"Sound.playSound\", 90000083, true, 40)\r\n    invoke_custom(01000, 1, \"bubble\", rushuId, \"rushu.fight.end.win.dialog.03\")\r\n    invoke_custom(03500, 1, \"clearBubbles\", rushuId)\r\n    \r\n    -- \"Je t'ai suffisamment affaibli !\"\r\n    invoke_custom(04000, 1, \"bubble\", playerId, \"rushu.fight.end.win.dialog.04\")\r\n    invoke_custom(06500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"PAS SI VITE !\"\r\n    invoke_custom(07000, 1, \"Sound.playSound\", 90000082, true, 40)\r\n    invoke_custom(07000, 1, \"bubble\", rushuId, \"rushu.fight.end.win.dialog.05\")\r\n    invoke_custom(08500, 1, \"clearBubbles\", rushuId)\r\n    \r\n    invoke_custom(07500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimSort-GrandCoupdePoingdansleSol\")\r\n    invoke_custom(07500, 1, \"Mobile.setMobileAnimation\", rushuId, \"AnimSort-TapePied\")\r\n    invoke_custom(09200, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimStatique02\")\r\n    \r\n    invoke_custom(08000, 1, \"Effect.createCameraShakeEffect\", 200, 300, 200, 1)\r\n    invoke_custom(08300, 1, \"Particle.addParticleSystem\", -1453072852, -40, 7, -4)\r\n    invoke_custom(08300, 1, \"Particle.addParticleSystem\", -1453072850, -43, 7, -4)\r\n    \r\n    -- \"TU NE GAGNERAS PAS, MORTEL{[1*]?LE:} !!!\"\r\n    invoke_custom(08900, 1, \"Sound.playSound\", 90000084, true, 40)\r\n    invoke_custom(08900, 1, \"bubble\", rushuId, \"rushu.fight.end.win.dialog.07\")\r\n    invoke_custom(09300, 1, \"Mobile.setMobileAnimation\", rushuId, \"AnimSort-TapePied\")\r\n    invoke_custom(09300, 1, \"Effect.createCameraShakeEffect\", 200, 300, 200, 1)\r\n    \r\n    invoke_custom(09300, 1, \"Particle.addParticleSystem\", -1453072950, -44, 7, -4)\r\n    invoke_custom(10500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimMort\")\r\n    invoke_custom(14500, 1, \"Mobile.setMobileVisible\", playerId, false)\r\n    invoke_custom(12500, 1, \"Camera.setCamera\", 1.3, -47, 4, -4)\r\n    \r\n    -- \"J'AI UTILISÉ TROP D'ÉNERGIE...\"\r\n    invoke_custom(13000, 1, \"Sound.playSound\", 90000082, true, 40)\r\n    invoke_custom(13000, 1, \"bubble\", rushuId, \"rushu.fight.end.win.dialog.08\")\r\n    invoke_custom(15000, 1, \"clearBubbles\", rushuId)\r\n    \r\n    -- \"C'ÉTAIT UN BEAU COMBAT ! J'ESPÈRE QUE NOUS NOUS REVERRONS !\"\r\n    invoke_custom(15500, 1, \"Sound.playSound\", 90000085, true, 40)\r\n    invoke_custom(15500, 1, \"bubble\", rushuId, \"rushu.fight.end.win.dialog.09\")\r\n    invoke_custom(18999, 1, \"clearBubbles\", rushuId)\r\n    \r\n    invoke_custom(18999, 1, \"Mobile.setMobileDirection\", rushuId, 3)\r\n    invoke_custom(19000, 1, \"Mobile.setMobileAnimation\", rushuId, \"AnimMort\")\r\n    \r\n    ---------------------------------\r\n    \r\n    invoke_custom(22500, 1, \"skipCinematic\", 21700)\nend\n\n-- CLIENT_TRIGGERED_EVENT - Fin Cinématique -> Clean\n-- \nfunction event_2479_21698(teamDamage, rushuFightWon, doorOpened)\n    local teamDamage = toString(teamDamage)\r\n    local playerId = Context.getLeaderId()\r\n    \r\n    displayDoor(doorOpened, rushuFightWon)\r\n    \r\n    Mobile.setMobileAnimation(playerId, \"AnimIncarnam-Chute-Fin\")\r\n    Mobile.hideOtherPlayerMobile(false)\r\n    \r\n    UI.setWidgetEnabled(\"fightResultDialog\", \"rootContainer\", true)\r\n    UI.setWidgetVisibility(\"fightResultDialog\", \"rootContainer\", true)\r\n    \r\n    local text = Event.getKeyTranslation(\"fight.score.ogrest\", teamDamage)\r\n    UI.setPropertyStringValue(\"fight.score.ogrest\", text)\r\n    UI.writeLocalisedInChat(\"ogrest.fight.team.score\", teamDamage)\r\n    \r\n    UI.removeUnremovableDialog(\"fightResultDialog\")\r\n    \r\n    UI.addDialogUnloadedListener(\"fightResultDialog\", \"UI.removeProperty\", \"fight.score.ogrest\")\r\nend\n\n-- [ADMIN] Procédure fin de combat\n-- \nfunction event_2479_21689()\n    \nend\n\n-- [ADMIN] Procédure pour choisir les picks vestiges\n-- \nfunction event_2479_21696()\n    \nend\n\n-- Achievement 5021 - Validation\n-- \nfunction event_2479_21690()\n    \nend\n\n-- Achievement 5021 - Variable\n-- \nfunction event_2479_21691()\n    \nend\n\n-- Achievement 5025 - Validation\n-- \nfunction event_2479_21693()\n    \nend\n\n-- Achievement 5025 - Variable\n-- \nfunction event_2479_21692()\n    \nend\n\n-- Achievement 5024 - Validation\n-- \nfunction event_2479_21694()\n    \nend\n\n-- Achievement 5024 - Variable\n-- \nfunction event_2479_21695()\n    \nend\n\n-- [EVENT] FIGHT_ENTER_ACTION_PHASE - Application états\n-- \nfunction event_2479_23148()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","displayDoor","hideMonster","showMonster","onFightInfoClosed","updateFightInfo","event_2479_21545","event_2479_21546","event_2479_21547","event_2479_21573","event_2479_21697","event_2479_21701","event_2479_21570","event_2479_21686","event_2479_21571","event_2479_21685","event_2479_21687","event_2479_21699","event_2479_21700","event_2479_21698","event_2479_21689","event_2479_21696","event_2479_21690","event_2479_21691","event_2479_21693","event_2479_21692","event_2479_21694","event_2479_21695","event_2479_23148"],"quest_calls":[],"dialogue_calls":[]},"scenario/2480.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\n\n-- [EVENT] Initialisation\n-- \nfunction event_2480_21548()\n    \nend\n\n-- [EVENT] Le joueur parle à Arlémia - Cinématique (case - a parlé à Milo)\n-- IsAchievementRunning(4963) and IsAchievementObjectiveComplete(10217) and not IsAchievementObjectiveComplete(10218) and IsAchievementObjectiveComplete(10225)\nfunction event_2480_21549(arlemia)\n    local playerId = Context.getLeaderId()\r\n    local arlemiaId = toLong(arlemia)\r\n    local miloId = createActor(117903818, -19, -13, 0, 8, 5, 8)\r\n    \r\n    startCinematicContext(1.4, arlemiaId)\r\n    \r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 21549)\r\n    \r\n    invoke_custom(00001, 1, \"Mobile.setMobileVisible\", miloId, false)\r\n    invoke_custom(01000, 1, \"Mobile.setMobileDirection\", playerId, 7)\r\n    \r\n    -- \"Bon, j'ai prévenu Milo, il arrive.\"\r\n    invoke_custom(02000, 1, \"bubble\", playerId, \"quest.shukrute.zone.021.01\")\r\n    invoke_custom(02000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Pouce\")\r\n    invoke_custom(05500, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(06500, 1, \"Mobile.setMobileVisible\", miloId, true)\r\n    invoke_custom(07500, 1, \"Mobile.moveMobile\", miloId, -31, -13, 0, \"Mobile.setMobileDirection\", miloId, 3)\r\n    \r\n    -- \"!!!\"\r\n    invoke_custom(08000, 1, \"bubble\", arlemiaId, \"quest.shukrute.zone.020.02\")\r\n    invoke_custom(08500, 1, \"clearBubbles\", arlemiaId)\r\n    \r\n    invoke_custom(09000, 1, \"Mobile.setMobileDirection\", arlemiaId, 3)\r\n    invoke_custom(09000, 1, \"Mobile.setMobileDirection\", playerId, 1)\r\n    invoke_custom(09200, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Effrayee\")\r\n    \r\n    invoke_custom(11000, 1, \"Mobile.setMobileDirection\", playerId, 7)\r\n    -- \"Arlémia...\"\r\n    invoke_custom(11000, 1, \"bubble\", miloId, \"quest.shukrute.zone.020.03\")\r\n    invoke_custom(12500, 1, \"clearBubbles\", miloId)\r\n    \r\n    -- \"...\"\r\n    invoke_custom(12500, 1, \"bubble\", arlemiaId, \"quest.shukrute.zone.020.04\")\r\n    invoke_custom(13500, 1, \"clearBubbles\", arlemiaId)\r\n    \r\n    -- \"Je... ne m'attendais pas à te voir ici.\"\r\n    invoke_custom(14000, 1, \"Mobile.setMobileAnimation\", miloId, \"AnimComp-SurprisPeur\")\r\n    invoke_custom(14000, 1, \"bubble\", miloId, \"quest.shukrute.zone.021.05\")\r\n    invoke_custom(15500, 1, \"clearBubbles\", miloId)\r\n    \r\n    -- \"Eh oui. Je m'étais donnée du mal pour ne pas te voir.\"\r\n    invoke_custom(16000, 1, \"bubble\", arlemiaId, \"quest.shukrute.zone.021.06\")\r\n    invoke_custom(19500, 1, \"clearBubbles\", arlemiaId)\r\n    \r\n    -- \"Bon ben... On travaille quand même ensemble ?\"\r\n    invoke_custom(20000, 1, \"Mobile.setMobileAnimation\", miloId, \"AnimComp-NonNerveux\")\r\n    invoke_custom(20000, 1, \"bubble\", miloId, \"quest.shukrute.zone.020.07\")\r\n    invoke_custom(23500, 1, \"clearBubbles\", miloId)\r\n    \r\n    -- \"**C'est gênant.\"\r\n    invoke_custom(22500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(22500, 1, \"bubble\", playerId, \"quest.shukrute.zone.021.08\")\r\n    invoke_custom(24500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"J'ai un peu examiné la zone, et je pense avoir trouvé une solution.\"\r\n    invoke_custom(24000, 1, \"Mobile.setMobileAnimation\", miloId, \"AnimComp-Parler\")\r\n    invoke_custom(24000, 1, \"bubble\", miloId, \"quest.shukrute.zone.020.08\")\r\n    invoke_custom(28000, 1, \"clearBubbles\", miloId)\r\n    \r\n    -- \"Nous allons devoir coopérer pour maintenir la porte du donjon ouverte.\"\r\n    invoke_custom(28500, 1, \"Mobile.setMobileAnimation\", miloId, \"AnimComp-Parler\")\r\n    invoke_custom(28500, 1, \"bubble\", miloId, \"quest.shukrute.zone.020.09\")\r\n    invoke_custom(32500, 1, \"clearBubbles\", miloId)\r\n    \r\n    -- \"Et comment tu comptes t'y prendre, au juste...?\"\r\n    invoke_custom(33000, 1, \"bubble\", arlemiaId, \"quest.shukrute.zone.020.10\")\r\n    invoke_custom(36000, 1, \"clearBubbles\", arlemiaId)\r\n    \r\n    -- \"Cet endroit est en train d'être consumé par une étrange puissance résiduelle.\"\r\n    invoke_custom(36500, 1, \"bubble\", arlemiaId, \"quest.shukrute.zone.020.11\")\r\n    invoke_custom(31000, 1, \"clearBubbles\", arlemiaId)\r\n    \r\n    -- \"Mais il n'a pas encore été complètement détruit.\"\r\n    invoke_custom(41500, 1, \"Mobile.setMobileAnimation\", miloId, \"AnimComp-Livre-Debut\")\r\n    invoke_custom(41500, 1, \"bubble\", miloId, \"quest.shukrute.zone.020.12\")\r\n    invoke_custom(44500, 1, \"clearBubbles\", miloId)\r\n    \r\n    -- \"... Car une protection entoure cet endroit.\"\r\n    invoke_custom(45000, 1, \"bubble\", miloId, \"quest.shukrute.zone.020.13\")\r\n    invoke_custom(48000, 1, \"clearBubbles\", miloId)\r\n    \r\n    -- \"Je vois. Sinon, toute la Shukrute disparaitrait ?\"\r\n    invoke_custom(48500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(48500, 1, \"bubble\", playerId, \"quest.shukrute.zone.020.14\")\r\n    invoke_custom(51500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"La Shukrute, voire le Monde des Douze.\"\r\n    invoke_custom(52000, 1, \"bubble\", miloId, \"quest.shukrute.zone.020.15\")\r\n    invoke_custom(54500, 1, \"clearBubbles\", miloId)\r\n    \r\n    -- \"J'ai trouvé deux piliers qui pourraient correspondre à une sorte de générateur de barrière...\"\r\n    invoke_custom(55000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Calmer\")\r\n    invoke_custom(55000, 1, \"bubble\", playerId, \"quest.shukrute.zone.020.16\")\r\n    invoke_custom(60000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"D'accord, séparons-nous pour les activer. Je suppose que ça t'ira mieux comme ça ?\"\r\n    invoke_custom(60500, 1, \"Mobile.setMobileAnimation\", miloId, \"AnimComp-Livre-Fin\")\r\n    invoke_custom(60500, 1, \"bubble\", miloId, \"quest.shukrute.zone.020.17\")\r\n    invoke_custom(66000, 1, \"clearBubbles\", miloId)\r\n    \r\n    -- \"...\"\r\n    invoke_custom(66500, 1, \"bubble\", arlemiaId, \"quest.shukrute.zone.020.18\")\r\n    invoke_custom(67500, 1, \"clearBubbles\", arlemiaId)\r\n    \r\n    -- \"[#name], nous aurons sûrement besoin de ta protection pour repousser les monstres.\"\r\n    invoke_custom(68000, 1, \"Mobile.setMobileAnimation\", miloId, \"AnimComp-Parler\")\r\n    invoke_custom(68000, 1, \"bubble\", miloId, \"quest.shukrute.zone.020.19\")\r\n    invoke_custom(73000, 1, \"clearBubbles\", miloId)\r\n    \r\n    -- \"D'accord. En route !\"\r\n    invoke_custom(73500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Acquiescer\")\r\n    invoke_custom(73500, 1, \"bubble\", playerId, \"quest.shukrute.zone.020.20\")\r\n    invoke_custom(76500, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(77000, 1, \"skipCinematic\", 21549)\nend\n\n-- [EVENT] Le joueur parle à Arlémia - Cinématique (case - n'a pas parlé à Milo)\n-- IsAchievementRunning(4963) and IsAchievementObjectiveComplete(10217) and not IsAchievementObjectiveComplete(10218) and IsAchievementObjectiveComplete(10225)\nfunction event_2480_21550(arlemia)\n    local playerId = Context.getLeaderId()\r\n    local arlemiaId = toLong(arlemia)\r\n    local miloId = createActor(117903818, -19, -13, 0, 8, 5, 8)\r\n    \r\n    startCinematicContext(1.4, arlemiaId)\r\n    \r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 21550)\r\n    \r\n    invoke_custom(00001, 1, \"Mobile.setMobileVisible\", miloId, false)\r\n    invoke_custom(01000, 1, \"Mobile.setMobileDirection\", playerId, 7)\r\n    \r\n    -- \"Bon, Milo ne pourra pas nous aider, visiblement.\"\r\n    invoke_custom(02000, 1, \"bubble\", playerId, \"quest.shukrute.zone.020.01\")\r\n    invoke_custom(02000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Non\")\r\n    invoke_custom(05500, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(06500, 1, \"Mobile.setMobileVisible\", miloId, true)\r\n    invoke_custom(07500, 1, \"Mobile.moveMobile\", miloId, -31, -13, 0, \"Mobile.setMobileDirection\", miloId, 3)\r\n    \r\n    -- \"!!!\"\r\n    invoke_custom(08000, 1, \"bubble\", arlemiaId, \"quest.shukrute.zone.020.02\")\r\n    invoke_custom(08500, 1, \"clearBubbles\", arlemiaId)\r\n    \r\n    invoke_custom(09000, 1, \"Mobile.setMobileDirection\", arlemiaId, 3)\r\n    invoke_custom(09000, 1, \"Mobile.setMobileDirection\", playerId, 1)\r\n    invoke_custom(09200, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Effrayee\")\r\n    \r\n    invoke_custom(11000, 1, \"Mobile.setMobileDirection\", playerId, 7)\r\n    -- \"Arlémia...\"\r\n    invoke_custom(11000, 1, \"bubble\", miloId, \"quest.shukrute.zone.020.03\")\r\n    invoke_custom(12500, 1, \"clearBubbles\", miloId)\r\n    \r\n    -- \"...\"\r\n    invoke_custom(12500, 1, \"bubble\", arlemiaId, \"quest.shukrute.zone.020.04\")\r\n    invoke_custom(13500, 1, \"clearBubbles\", arlemiaId)\r\n    \r\n    -- \"Ahem.\"\r\n    invoke_custom(14000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Toux\")\r\n    invoke_custom(14000, 1, \"bubble\", playerId, \"quest.shukrute.zone.020.05\")\r\n    invoke_custom(15500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Tu as décidé de venir, finalement ?\"\r\n    invoke_custom(17000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Presenter\")\r\n    invoke_custom(16000, 1, \"bubble\", playerId, \"quest.shukrute.zone.020.06\")\r\n    invoke_custom(19000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Oui, je... je ne pouvais pas vous laisser résoudre cette énigme seuls.\"\r\n    invoke_custom(19500, 1, \"Mobile.setMobileAnimation\", miloId, \"AnimComp-NonNerveux\")\r\n    invoke_custom(19500, 1, \"bubble\", miloId, \"quest.shukrute.zone.020.07\")\r\n    invoke_custom(23500, 1, \"clearBubbles\", miloId)\r\n    \r\n    -- \"J'ai un peu examiné la zone, et je pense avoir trouvé une solution.\"\r\n    invoke_custom(24000, 1, \"Mobile.setMobileAnimation\", miloId, \"AnimComp-Parler\")\r\n    invoke_custom(24000, 1, \"bubble\", miloId, \"quest.shukrute.zone.020.08\")\r\n    invoke_custom(28000, 1, \"clearBubbles\", miloId)\r\n    \r\n    -- \"Nous allons devoir coopérer pour maintenir la porte du donjon ouverte.\"\r\n    invoke_custom(28500, 1, \"Mobile.setMobileAnimation\", miloId, \"AnimComp-Parler\")\r\n    invoke_custom(28500, 1, \"bubble\", miloId, \"quest.shukrute.zone.020.09\")\r\n    invoke_custom(32500, 1, \"clearBubbles\", miloId)\r\n    \r\n    -- \"Et comment tu comptes t'y prendre, au juste...?\"\r\n    invoke_custom(33000, 1, \"bubble\", arlemiaId, \"quest.shukrute.zone.020.10\")\r\n    invoke_custom(36000, 1, \"clearBubbles\", arlemiaId)\r\n    \r\n    -- \"Cet endroit est en train d'être consumé par une étrange puissance résiduelle.\"\r\n    invoke_custom(36500, 1, \"bubble\", arlemiaId, \"quest.shukrute.zone.020.11\")\r\n    invoke_custom(41000, 1, \"clearBubbles\", arlemiaId)\r\n    \r\n    -- \"Mais il n'a pas encore été complètement détruit.\"\r\n    invoke_custom(41500, 1, \"Mobile.setMobileAnimation\", miloId, \"AnimComp-Livre-Debut\")\r\n    invoke_custom(41500, 1, \"bubble\", miloId, \"quest.shukrute.zone.020.12\")\r\n    invoke_custom(44500, 1, \"clearBubbles\", miloId)\r\n    \r\n    -- \"... Car une protection entoure cet endroit.\"\r\n    invoke_custom(45000, 1, \"bubble\", miloId, \"quest.shukrute.zone.020.13\")\r\n    invoke_custom(48000, 1, \"clearBubbles\", miloId)\r\n    \r\n    -- \"Je vois. Sinon, toute la Shukrute disparaitrait ?\"\r\n    invoke_custom(48500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(48500, 1, \"bubble\", playerId, \"quest.shukrute.zone.020.14\")\r\n    invoke_custom(51500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"La Shukrute, voire le Monde des Douze.\"\r\n    invoke_custom(52000, 1, \"bubble\", miloId, \"quest.shukrute.zone.020.15\")\r\n    invoke_custom(54500, 1, \"clearBubbles\", miloId)\r\n    \r\n    -- \"J'ai trouvé deux piliers qui pourraient correspondre à une sorte de générateur de barrière...\"\r\n    invoke_custom(55000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Calmer\")\r\n    invoke_custom(55000, 1, \"bubble\", playerId, \"quest.shukrute.zone.020.16\")\r\n    invoke_custom(60000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"D'accord, séparons-nous pour les activer. Je suppose que ça t'ira mieux comme ça ?\"\r\n    invoke_custom(60500, 1, \"Mobile.setMobileAnimation\", miloId, \"AnimComp-Livre-Fin\")\r\n    invoke_custom(60500, 1, \"bubble\", miloId, \"quest.shukrute.zone.020.17\")\r\n    invoke_custom(66000, 1, \"clearBubbles\", miloId)\r\n    \r\n    -- \"...\"\r\n    invoke_custom(66500, 1, \"bubble\", arlemiaId, \"quest.shukrute.zone.020.18\")\r\n    invoke_custom(67500, 1, \"clearBubbles\", arlemiaId)\r\n    \r\n    -- \"[#name], nous aurons sûrement besoin de ta protection pour repousser les monstres.\"\r\n    invoke_custom(68000, 1, \"Mobile.setMobileAnimation\", miloId, \"AnimComp-Parler\")\r\n    invoke_custom(68000, 1, \"bubble\", miloId, \"quest.shukrute.zone.020.19\")\r\n    invoke_custom(73000, 1, \"clearBubbles\", miloId)\r\n    \r\n    -- \"D'accord. En route !\"\r\n    invoke_custom(73500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Acquiescer\")\r\n    invoke_custom(73500, 1, \"bubble\", playerId, \"quest.shukrute.zone.020.20\")\r\n    invoke_custom(76500, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(77000, 1, \"skipCinematic\", 21550)\nend\n\n-- CLIENT_TRIGGERED_EVENT - Validation ACH 4963 OBJ 10218\n-- \nfunction event_2480_21551()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_2480_21548","event_2480_21549","event_2480_21550","event_2480_21551"],"quest_calls":[],"dialogue_calls":[]},"scenario/2481.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\n\n-- [EVENT] Initialisation\n-- \nfunction event_2481_21552()\n    \nend\n\n-- [EVENT] Le joueur examine le pilier - Cinématique\n-- \nfunction event_2481_21553()\n    local playerId = Context.getLeaderId()\r\n    local arlemiaId = createActor(1300104, -66, -2, 0, 8, 3, 8)\r\n    \r\n    startCinematicContext(1.3, playerId)\r\n    \r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 21553)\r\n    \r\n    invoke_custom(00100, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    \r\n    -- \"C'est un des piliers que nous recherchions...\"\r\n    invoke_custom(01000, 1, \"bubble\", arlemiaId, \"quest.shukrute.zone.022.01\")\r\n    invoke_custom(04000, 1, \"clearBubbles\", arlemiaId)\r\n    \r\n    -- \"Hmmm... Fascinant.\"\r\n    invoke_custom(05000, 1, \"bubble\", arlemiaId, \"quest.shukrute.zone.022.02\")\r\n    invoke_custom(07000, 1, \"clearBubbles\", arlemiaId)\r\n    \r\n    -- \"J'ai besoin d'un peu de temps pour l'étudier...\"\r\n    invoke_custom(07500, 1, \"bubble\", arlemiaId, \"quest.shukrute.zone.022.03\")\r\n    invoke_custom(10500, 1, \"clearBubbles\", arlemiaId)\r\n    \r\n    -- \"**Des monstres arrivent ! Je dois m'en occuper.\"\r\n    invoke_custom(10500, 1, \"bubble\", playerId, \"quest.shukrute.zone.022.04\")\r\n    invoke_custom(14000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(14500, 1, \"skipCinematic\", 21553)\nend\n\n-- [EVENT] Lancement du combat\n-- \nfunction event_2481_21554(groupId, mobA, fightId, playerId)\n    playerId = toLong(playerId)\r\n    groupId = toLong(groupId)\r\n    fightId = toLong(fightId)\r\n    mobA = toLong(mobA)\r\n    \r\n    trace(\"===Valeur de Player Id ======\", playerId)\r\n    trace(\"===Valeur de Group Id ======\", groupId)\r\n    trace(\"===Valeur de Fight Id ======\", fightId)\r\n    trace(\"===Valeur de MobA Id ======\", mobA)\nend\n\n-- [EVENT] Fin de combat gagnant\n-- \nfunction event_2481_21557()\n    \nend\n\n-- [EVENT] Fin de combat\n-- \nfunction event_2481_21559()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_2481_21552","event_2481_21553","event_2481_21554","event_2481_21557","event_2481_21559"],"quest_calls":[],"dialogue_calls":[]},"scenario/2483.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\n\n-- [EVENT] Initialisation\n-- \nfunction event_2483_21565()\n    \nend\n\n-- [EVENT] Le joueur examine le pilier - Cinématique\n-- \nfunction event_2483_21566()\n    local playerId = Context.getLeaderId()\r\n    local miloId = createActor(117903818, 64, 4, 0, 8, 1, 8)\r\n    \r\n    startCinematicContext(1.3, playerId)\r\n    \r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 21566)\r\n    \r\n    invoke_custom(00100, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    \r\n    -- \"Ah, quel beau pilier...\"\r\n    invoke_custom(01000, 1, \"bubble\", miloId, \"quest.shukrute.zone.023.01\")\r\n    invoke_custom(03000, 1, \"clearBubbles\", miloId)\r\n    \r\n    -- \"Quelle architecture étrange, c'est fascinant.\"\r\n    invoke_custom(03500, 1, \"bubble\", miloId, \"quest.shukrute.zone.023.02\")\r\n    invoke_custom(07000, 1, \"clearBubbles\", miloId)\r\n    \r\n    -- \"Je dois l'étudier de PRÈS afin de trouver un moyen de le désactiver...\"\r\n    invoke_custom(07500, 1, \"bubble\", miloId, \"quest.shukrute.zone.023.03\")\r\n    invoke_custom(11500, 1, \"clearBubbles\", miloId)\r\n    \r\n    -- \"**Des monstres arrivent ! Je dois m'en occuper.\"\r\n    invoke_custom(10500, 1, \"bubble\", playerId, \"quest.shukrute.zone.022.04\")\r\n    invoke_custom(14000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(14500, 1, \"skipCinematic\", 21566)\nend\n\n-- [EVENT] Lancement du combat\n-- \nfunction event_2483_21567(groupId, mobA, fightId, playerId)\n    playerId = toLong(playerId)\r\n    groupId = toLong(groupId)\r\n    fightId = toLong(fightId)\r\n    mobA = toLong(mobA)\r\n    \r\n    trace(\"===Valeur de Player Id ======\", playerId)\r\n    trace(\"===Valeur de Group Id ======\", groupId)\r\n    trace(\"===Valeur de Fight Id ======\", fightId)\r\n    trace(\"===Valeur de MobA Id ======\", mobA)\nend\n\n-- [EVENT] Fin de combat gagnant - Cinématique\n-- \nfunction event_2483_21568()\n    local playerId = Context.getLeaderId()\r\n    local miloId = createActor(117903818, 64, 4, 0, 8, 1, 8)\r\n    \r\n    startCinematicContext(1.3, miloId)\r\n    \r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 21568)\r\n    \r\n    invoke_custom(01000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(01000, 1, \"Mobile.setMobilePosition\", playerId, 66, 4, 0)\r\n    invoke_custom(01000, 1, \"Mobile.setMobileDirection\", playerId, 5)\r\n    \r\n    -- \"On dirait que nous avons réussi à désactiver les deux piliers...\"\r\n    invoke_custom(01000, 1, \"bubble\", playerId, \"quest.shukrute.zone.025.01\")\r\n    invoke_custom(05000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Mon travail ici s'achève.\"\r\n    invoke_custom(05500, 1, \"Mobile.setMobileAnimation\", miloId, \"AnimComp-Parler\")\r\n    invoke_custom(05500, 1, \"bubble\", miloId, \"quest.shukrute.zone.025.02\")\r\n    invoke_custom(08000, 1, \"clearBubbles\", miloId)\r\n    \r\n    -- \"Je vais retourner dans le Monde des Douze...\"\r\n    invoke_custom(08500, 1, \"bubble\", miloId, \"quest.shukrute.zone.025.03\")\r\n    invoke_custom(12500, 1, \"clearBubbles\", miloId)\r\n    \r\n    -- \"Tu dois vite rentrer dans le donjon avant que le monde entier ne soit détruit !\"\r\n    invoke_custom(13000, 1, \"bubble\", miloId, \"quest.shukrute.zone.025.04\")\r\n    invoke_custom(18000, 1, \"clearBubbles\", miloId)\r\n    \r\n    invoke_custom(18500, 1, \"skipCinematic\", 21568)\nend\n\n-- [EVENT] Fin de combat\n-- \nfunction event_2483_21569()\n    \nend\n\n-- CLIENT_TRIGGERED_EVENT - Fin de la cinématique\n-- \nfunction event_2483_21572()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_2483_21565","event_2483_21566","event_2483_21567","event_2483_21568","event_2483_21569","event_2483_21572"],"quest_calls":[],"dialogue_calls":[]},"scenario/2484.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\n\n-- Variables\n-- \nfunction event_2484_21574()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2484_21579()\n    \nend\n\n-- DIALOG_EXECUTED - On lance le combat\n-- \nfunction event_2484_21575(kali)\n    local kaliId = toLong(kali)\r\n    \r\n    Mobile.setMobileVisible(kaliId, false)\nend\n\n-- FIGHTER_ENTER_ACTION_PHASE - Invocation Kali\n-- \nfunction event_2484_21577()\n    \nend\n\n-- EFFECT_EXECUTION - Kali subit des dommages\n-- \nfunction event_2484_21576()\n    \nend\n\n-- FIGHT_ENDED_IN_CLIENT - Validation achievement\n-- \nfunction event_2484_21578()\n    \nend\n\n-- FIGHT_ENDED_IN_CLIENT - Cinématique - Rebelle\n-- \nfunction event_2484_21580(kali)\n    local kaliId = toLong(kali)\r\n    local playerId = Context.getLeaderId()\r\n    Mobile.setMobileVisible(kaliId, true)\r\n    \r\n    startCinematicContext(1.4, kaliId)\r\n    \r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\")\r\n    \r\n    invoke_custom(00100, 1, \"Mobile.setMobileDirection\", playerId, 7)\r\n    \r\n    -- \"Tu as osé me frapper...!\"\r\n    invoke_custom(00500, 1, \"bubble\", kaliId, \"quest.shukrute.03.01\")\r\n    invoke_custom(00500, 1, \"Mobile.setMobileAnimation\", kaliId, \"AnimComp-Non\")\r\n    invoke_custom(03000, 1, \"clearBubbles\", kaliId)\r\n    \r\n    -- \"Qu'est-ce qui t'a pris de me blesser, minable ?!\"\r\n    invoke_custom(03500, 1, \"bubble\", kaliId, \"quest.shukrute.03.02\")\r\n    invoke_custom(03500, 1, \"Mobile.setMobileAnimation\", kaliId, \"AnimComp-Parler01\")\r\n    invoke_custom(06500, 1, \"clearBubbles\", kaliId)\r\n    \r\n    -- \"Je perds mon temps avec toi...\"\r\n    invoke_custom(07000, 1, \"bubble\", kaliId, \"quest.shukrute.03.03\")\r\n    invoke_custom(07000, 1, \"Mobile.setMobileAnimation\", kaliId, \"AnimComp-Provoc\")\r\n    invoke_custom(09500, 1, \"clearBubbles\", kaliId)\r\n    \r\n    invoke_custom(10000, 1, \"skipCinematic\")\nend\n\n-- FIGHT_ENDED_IN_CLIENT - Cinématique - Docile\n-- \nfunction event_2484_21581(kali)\n    local kaliId = toLong(kali)\r\n    local playerId = Context.getLeaderId()\r\n    Mobile.setMobileVisible(kaliId, true)\r\n    \r\n    startCinematicContext(1.4, kaliId)\r\n    \r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\")\r\n    \r\n    invoke_custom(00100, 1, \"Mobile.setMobileDirection\", playerId, 7)\r\n    \r\n    -- \"Bon, voilà du travail bien fait.\"\r\n    invoke_custom(00500, 1, \"bubble\", kaliId, \"quest.shukrute.03.04\")\r\n    invoke_custom(00500, 1, \"Mobile.setMobileAnimation\", kaliId, \"AnimComp-Parler01\")\r\n    invoke_custom(03000, 1, \"clearBubbles\", kaliId)\r\n    \r\n    -- \"Je suis contente que nous ayons aussi bien collaboré.\"\r\n    invoke_custom(03500, 1, \"bubble\", kaliId, \"quest.shukrute.03.05\")\r\n    invoke_custom(03500, 1, \"Mobile.setMobileAnimation\", kaliId, \"AnimComp-Oui\")\r\n    invoke_custom(06500, 1, \"clearBubbles\", kaliId)\r\n    \r\n    -- \"Même si j'ai fait le plus gros du travail... Héhéhé.\"\r\n    invoke_custom(07000, 1, \"bubble\", kaliId, \"quest.shukrute.03.06\")\r\n    invoke_custom(07000, 1, \"Mobile.setMobileAnimation\", kaliId, \"AnimComp-Parler02\")\r\n    invoke_custom(01000, 1, \"clearBubbles\", kaliId)\r\n    \r\n    invoke_custom(10500, 1, \"skipCinematic\")\nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_2484_21574","event_2484_21579","event_2484_21575","event_2484_21577","event_2484_21576","event_2484_21578","event_2484_21580","event_2484_21581"],"quest_calls":[],"dialogue_calls":[]},"scenario/2485.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\napsDirOneFiveId = -1090061180\r\napsDirThreeSevenId = -1090061181\r\napsCornerId = -1090061182\r\n\r\napsOneId = 0\r\napsTwoId = 0\r\napsThreeId = 0\r\napsFourId = 0\r\napsFiveId = 0\r\napsSixId = 0\r\napsSevenId = 0\r\napsEightId = 0\r\napsNineId = 0\r\napsTenId = 0\r\napsElevenId = 0\r\napsTwelveId = 0\r\n\r\nfunction displayFire()\r\n\tapsOneId = Particle.addParticleSystem(apsDirOneFiveId, 1, -11, 0)\r\n\tapsTwoId = Particle.addParticleSystem(apsDirOneFiveId, 1, -12, 0)\r\n\tapsThreeId = Particle.addParticleSystem(apsDirOneFiveId, -2, -11, 0)\r\n\tapsFourId = Particle.addParticleSystem(apsDirOneFiveId, -2, -12, 0)\r\n\tapsFiveId = Particle.addParticleSystem(apsDirThreeSevenId, -1, -10, 0)\r\n\tapsSixId = Particle.addParticleSystem(apsDirThreeSevenId, 0, -10, 0)\r\n\tapsSevenId = Particle.addParticleSystem(apsDirThreeSevenId, -1, -13, 0)\r\n\tapsEightId = Particle.addParticleSystem(apsDirThreeSevenId, 0, -13, 0)\r\n\tapsNineId = Particle.addParticleSystem(apsCornerId, -2, -10, 0)\r\n\tapsTenId = Particle.addParticleSystem(apsCornerId, 1, -10, 0)\r\n\tapsElevenId = Particle.addParticleSystem(apsCornerId, -2, -13, 0)\r\n\tapsTwelveId = Particle.addParticleSystem(apsCornerId, 1, -13, 0)\r\nend\r\n\r\nfunction hideFire()\r\n\tParticle.removeParticleSystem(apsOneId)\r\n\tParticle.removeParticleSystem(apsTwoId)\r\n\tParticle.removeParticleSystem(apsThreeId)\r\n\tParticle.removeParticleSystem(apsFourId)\r\n\tParticle.removeParticleSystem(apsFiveId)\r\n\tParticle.removeParticleSystem(apsSixId)\r\n\tParticle.removeParticleSystem(apsSevenId)\r\n\tParticle.removeParticleSystem(apsEightId)\r\n\tParticle.removeParticleSystem(apsNineId)\r\n\tParticle.removeParticleSystem(apsTenId)\r\n\tParticle.removeParticleSystem(apsElevenId)\r\n\tParticle.removeParticleSystem(apsTwelveId)\r\nend\n\n-- Variables\n-- \nfunction event_2485_21582()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2485_21583()\n    displayFire()\nend\n\n-- INTERACTIVE_ELEMENT_ACTIVATION - Cinématique\n-- \nfunction event_2485_21585()\n    local playerId = Context.getLeaderId()\r\n    \r\n    startCinematicContext(1.4, playerId)\r\n    \r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 21585)\r\n    \r\n    invoke_custom(00100, 1, \"Mobile.setMobileDirection\", playerId, 7)\r\n    \r\n    -- \"**Je vais devoir passer cette barrière de flammes...\"\r\n    invoke_custom(00500, 1, \"bubble\", playerId, \"quest.shukrute.03.07\")\r\n    invoke_custom(00500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(04000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"**!!!\"\r\n    invoke_custom(04500, 1, \"bubble\", playerId, \"quest.shukrute.03.08\")\r\n    invoke_custom(04500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Effrayee\")\r\n    invoke_custom(05500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"**Je sens que des Démhorribles m'attaquent !\"\r\n    invoke_custom(06000, 1, \"bubble\", playerId, \"quest.shukrute.03.09\")\r\n    invoke_custom(06000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Colere\")\r\n    invoke_custom(10500, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(11000, 1, \"skipCinematic\", 21585)\nend\n\n-- CLIENT_TRIGGERED_EVENT - On lance le combat\n-- \nfunction event_2485_21584()\n    \nend\n\n-- FIGHT_ENDED_IN_CLIENT - Cinématique\n-- \nfunction event_2485_21586()\n    hideFire()\r\n    \r\n    local playerId = Context.getLeaderId()\r\n    \r\n    startCinematicContext(1.4, playerId)\r\n    \r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\")\r\n    \r\n    invoke_custom(00100, 1, \"Mobile.setMobileDirection\", playerId, 7)\r\n    \r\n    -- \"**Bon, voilà une bonne chose de faite.\"\r\n    invoke_custom(00500, 1, \"bubble\", playerId, \"quest.shukrute.03.10\")\r\n    invoke_custom(00500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Calmer\")\r\n    invoke_custom(04500, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(04500, 1, \"Mobile.moveMobile\", playerId, -1, -11, 0, \"Mobile.setMobileAnimation\", playerId, \"AnimInteraction-Ramasser\")\r\n    \r\n    -- \"**Et voilà le collier, au nom de \"Baptiste\".\"\r\n    invoke_custom(06500, 1, \"bubble\", playerId, \"quest.shukrute.03.11\")\r\n    invoke_custom(06500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Pouce\")\r\n    invoke_custom(10000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"**Hmmm, il n'avait pas l'air très net.\"\r\n    invoke_custom(10500, 1, \"bubble\", playerId, \"quest.shukrute.03.12\")\r\n    invoke_custom(10500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(14000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"**Mais avec ces faux instruments, je vais pouvoir aller dans le donjon de Cratéros.\"\r\n    invoke_custom(14500, 1, \"bubble\", playerId, \"quest.shukrute.03.13\")\r\n    invoke_custom(14500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Presenter\")\r\n    invoke_custom(20000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(20500, 1, \"skipCinematic\")\nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","displayFire","hideFire","event_2485_21582","event_2485_21583","event_2485_21585","event_2485_21584","event_2485_21586"],"quest_calls":[],"dialogue_calls":[]},"scenario/2486.lua":{"source":"\n\n-- [INIT] Variables\n-- \nfunction event_2486_21588()\n    \nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_2486_21589()\n    \nend\n\n-- [EVENT] Réceptacle Full - On rend le challenge disponible grâce à l'état de l'IE\n-- \nfunction event_2486_21590()\n    \nend\n\n-- [EVENT] 1 - Fin du challenge Phytomorphes - On reset le Réceptacle\n-- \nfunction event_2486_21716()\n    \nend\n\n-- [EVENT] 2 - Fin du challenge Vidéants - On reset le Réceptacle\n-- \nfunction event_2486_21717()\n    \nend\n\n-- [EVENT] 3 - Fin du challenge Démhorribles - On reset le Réceptacle\n-- \nfunction event_2486_21718()\n    \nend\n\n-- [EVENT] 4 - Fin du challenge Égarés - On reset le Réceptacle\n-- \nfunction event_2486_21719()\n    \nend\n\n-- [EVENT] 5 - Fin du challenge Ravageurs - On reset le Réceptacle\n-- \nfunction event_2486_21720()\n    \nend\n\n","functions":["event_2486_21588","event_2486_21589","event_2486_21590","event_2486_21716","event_2486_21717","event_2486_21718","event_2486_21719","event_2486_21720"],"quest_calls":[],"dialogue_calls":[]},"scenario/2488.lua":{"source":"\n\n-- Variables\n-- \nfunction event_2488_21645()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2488_21646()\n    \nend\n\n-- GENERIC_ACTIVABLE_ACTION - On lance le combat\n-- \nfunction event_2488_21648()\n    \nend\n\n-- FIGHT_ENDED_IN_CLIENT - Notification ACH 4952 OBJ 10197\n-- \nfunction event_2488_21649()\n    \nend\n\n-- GENERIC_ACTIVABLE_ACTION - Notification ACH 4952 OBJ 10198\n-- \nfunction event_2488_21660()\n    \nend\n\n","functions":["event_2488_21645","event_2488_21646","event_2488_21648","event_2488_21649","event_2488_21660"],"quest_calls":[],"dialogue_calls":[]},"scenario/2489.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\n\n-- Variables\n-- \nfunction event_2489_21650()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2489_21651()\n    \nend\n\n-- INTERACTIVE_ELEMENT_ACTIVATION - Cinématique\n-- \nfunction event_2489_21652()\n    local playerId = Context.getLeaderId()\r\n    local mobOneId = createActor(1107305274, 0, 0, 0, 4, 7, 6)\r\n    local mobTwoId = createActor(1107305275, -1, 0, 0, 4, 7, 6)\r\n    local mobThreeId = createActor(1107305276, 1, 0, 0, 4, 7, 6)\r\n    local pahdBoolId = createActor(1300103, -2, -16, 0, 4, 1, 6)\r\n    \r\n    startCinematicContext(1.4, playerId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 21652)\r\n    \r\n    invoke_custom(00010, 1, \"Mobile.setMobileVisible\", mobOneId, false)\r\n    invoke_custom(00010, 1, \"Mobile.setMobileVisible\", mobTwoId, false)\r\n    invoke_custom(00010, 1, \"Mobile.setMobileVisible\", mobThreeId, false)\r\n    invoke_custom(00010, 1, \"Mobile.setMobileVisible\", pahdBoolId, false)\r\n    \r\n    invoke_custom(00100, 1, \"Mobile.setMobileDirection\", playerId, 7)\r\n    \r\n    -- \"**Encore un endroit mystérieux.\"\r\n    invoke_custom(00500, 1, \"bubble\", playerId, \"quest.shukrute.zone.010.01\")\r\n    invoke_custom(00500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(03000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(02500, 1, \"Mobile.moveMobile\", playerId, 0, -16, 0, \"Mobile.setMobileDirection\", playerId, 3)\r\n    \r\n    -- \"**J'entends du bruit ! Je vais me cacher.\"\r\n    invoke_custom(04500, 1, \"bubble\", playerId, \"quest.shukrute.zone.010.02\")\r\n    invoke_custom(05000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Effrayee\")\r\n    invoke_custom(07000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(06500, 1, \"Mobile.moveMobile\", playerId, 0, -27, 4, \"Mobile.setMobileDirection\", playerId, 3)\r\n    invoke_custom(12500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Genoux-Debut\")\r\n    \r\n    invoke_custom(10010, 1, \"Mobile.setMobileVisible\", mobOneId, true)\r\n    invoke_custom(10010, 1, \"Mobile.setMobileVisible\", mobTwoId, true)\r\n    invoke_custom(10010, 1, \"Mobile.setMobileVisible\", mobThreeId, true)\r\n    invoke_custom(10010, 1, \"Camera.attachCameraToMobile\", mobOneId)\r\n    \r\n    invoke_custom(11010, 1, \"Mobile.moveMobile\", mobOneId, 0, -14, 0, \"Mobile.setMobileDirection\", mobOneId, 7)\r\n    invoke_custom(11010, 1, \"Mobile.moveMobile\", mobTwoId, 2, -16, 0, \"Mobile.setMobileDirection\", mobTwoId, 5)\r\n    invoke_custom(11010, 1, \"Mobile.moveMobile\", mobThreeId, 0, -18, 0, \"Mobile.setMobileDirection\", mobThreeId, 3)\r\n    \r\n    -- \"... Et donc je lui ai dit, \"c'est pas la peine mon gars\".\"\r\n    invoke_custom(12010, 1, \"Sound.playSound\", 90031714, true, 40)\r\n    invoke_custom(12010, 1, \"bubble\", mobOneId, \"quest.shukrute.zone.010.03\")\r\n    invoke_custom(15000, 1, \"clearBubbles\", mobOneId)\r\n    \r\n    -- \"BWAHAHA !!!\"\r\n    invoke_custom(15010, 1, \"Sound.playSound\", 90031724, true, 40)\r\n    invoke_custom(15010, 1, \"bubble\", mobTwoId, \"quest.shukrute.zone.010.04\")\r\n    invoke_custom(17000, 1, \"clearBubbles\", mobTwoId)\r\n    \r\n    -- \"BWAHAHA !!!\"\r\n    invoke_custom(15010, 1, \"Sound.playSound\", 90031741, true, 40)\r\n    invoke_custom(15010, 1, \"bubble\", mobThreeId, \"quest.shukrute.zone.010.04\")\r\n    invoke_custom(17000, 1, \"clearBubbles\", mobThreeId)\r\n    \r\n    invoke_custom(17000, 1, \"Camera.attachCameraToMobile\", playerId)\r\n    \r\n    -- \"...\"\r\n    invoke_custom(17000, 1, \"bubble\", playerId, \"quest.shukrute.zone.010.05\")\r\n    invoke_custom(19000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(19010, 1, \"Camera.attachCameraToMobile\", mobThreeId)\r\n    \r\n    -- \"Bon, on peut commencer à jouer ?\"\r\n    invoke_custom(19000, 1, \"Sound.playSound\", 90031725, true, 40)\r\n    invoke_custom(19000, 1, \"bubble\", mobTwoId, \"quest.shukrute.zone.010.06\")\r\n    invoke_custom(21500, 1, \"clearBubbles\", mobTwoId)\r\n    \r\n    -- \"Ben non, on doit encore attendre Pahd'Bool.\"\r\n    invoke_custom(22000, 1, \"Sound.playSound\", 90031735, true, 40)\r\n    invoke_custom(22000, 1, \"bubble\", mobThreeId, \"quest.shukrute.zone.010.07\")\r\n    invoke_custom(24500, 1, \"clearBubbles\", mobThreeId)\r\n    \r\n    -- \"Roh la barbe...\"\r\n    invoke_custom(25000, 1, \"Sound.playSound\", 90031726, true, 40)\r\n    invoke_custom(25000, 1, \"bubble\", mobTwoId, \"quest.shukrute.zone.010.08\")\r\n    \r\n    invoke_custom(27000, 1, \"Camera.attachCameraToMobile\", playerId)\r\n    \r\n    --\"**Ils semblent avoir rendez-vous avec Pahd'Bool...\"\r\n    invoke_custom(28000, 1, \"bubble\", playerId, \"quest.shukrute.zone.010.09\")\r\n    invoke_custom(31000, 1, \"clearBubbles\", playerId)\r\n    \r\n    --\"**Je devrais voir comment la situation évolue.\"\r\n    invoke_custom(31500, 1, \"bubble\", playerId, \"quest.shukrute.zone.010.10\")\r\n    invoke_custom(34000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(34000, 1, \"UI.displayWideScreenBand\", true, 100, 300)\r\n    invoke_custom(36500, 1, \"Mobile.setMobileVisible\", pahdBoolId, true)\r\n    invoke_custom(36500, 1, \"Camera.attachCameraToMobile\", pahdBoolId)\r\n    invoke_custom(37000, 1, \"UI.displayWideScreenBand\", true, 25, 300)\r\n    \r\n    -- \"Désolé de vous avoir fait attendre !\"\r\n    invoke_custom(37500, 1, \"Sound.playSound\", 320001300076011, true, 40)\r\n    invoke_custom(37500, 1, \"bubble\", pahdBoolId, \"quest.shukrute.zone.010.11\")\r\n    invoke_custom(39500, 1, \"clearBubbles\", pahdBoolId)\r\n    \r\n    -- \"On va enfin pouvoir commencer !\"\r\n    invoke_custom(40000, 1, \"Sound.playSound\", 90031715, true, 40)\r\n    invoke_custom(40000, 1, \"bubble\", mobOneId, \"quest.shukrute.zone.010.12\")\r\n    invoke_custom(42500, 1, \"clearBubbles\", mobOneId)\r\n    \r\n    -- \"Pas trop tôt.\"\r\n    invoke_custom(42000, 1, \"Sound.playSound\", 90031740, true, 40)\r\n    invoke_custom(42000, 1, \"bubble\", mobThreeId, \"quest.shukrute.zone.010.13\")\r\n    invoke_custom(44600, 1, \"clearBubbles\", mobThreeId)\r\n    \r\n    -- \"Qui distribue ?\"\r\n    invoke_custom(43000, 1, \"Sound.playSound\", 90031724, true, 40)\r\n    invoke_custom(43000, 1, \"bubble\", mobTwoId, \"quest.shukrute.zone.010.14\")\r\n    invoke_custom(45600, 1, \"clearBubbles\", mobTwoId)\r\n    \r\n    -- \"Héhéhé... J'augmente la mise de dix coups de fouet !\"\r\n    invoke_custom(44000, 1, \"Sound.playSound\", 320001300076008, true, 40)\r\n    invoke_custom(44000, 1, \"bubble\", pahdBoolId, \"quest.shukrute.zone.010.15\")\r\n    invoke_custom(47500, 1, \"clearBubbles\", pahdBoolId)\r\n    \r\n    invoke_custom(47000, 1, \"Camera.attachCameraToMobile\", playerId)\r\n    \r\n    --\"**Mais, ils jouent aux cartes !\"\r\n    invoke_custom(48000, 1, \"bubble\", playerId, \"quest.shukrute.zone.010.16\")\r\n    invoke_custom(51000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"**C'est ma chance. Je vais le prendre la main dans le sac...\"\r\n    invoke_custom(51500, 1, \"bubble\", playerId, \"quest.shukrute.zone.010.17\")\r\n    invoke_custom(54000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(54000, 1, \"Mobile.moveMobile\", playerId, -1, -20, 0, \"Mobile.setMobileDirection\", playerId, 3)\r\n    \r\n    -- \"!!!\"\r\n    invoke_custom(55000, 1, \"bubble\", mobOneId, \"quest.shukrute.zone.010.18\")\r\n    invoke_custom(55000, 1, \"bubble\", mobTwoId, \"quest.shukrute.zone.010.18\")\r\n    invoke_custom(55000, 1, \"bubble\", mobThreeId, \"quest.shukrute.zone.010.18\")\r\n    invoke_custom(55000, 1, \"bubble\", pahdBoolId, \"quest.shukrute.zone.010.18\")\r\n    invoke_custom(55000, 1, \"Mobile.setMobileDirection\", mobTwoId, 7)\r\n    invoke_custom(55000, 1, \"Mobile.setMobileDirection\", mobThreeId, 7)\r\n    \r\n    -- \"Alors, on joue aux cartes sur ses heures de travail ?\"\r\n    invoke_custom(56500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Pointer\")\r\n    invoke_custom(56500, 1, \"bubble\", playerId, \"quest.shukrute.zone.010.19\")\r\n    invoke_custom(60000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Argh ! Attrapez-le !\"\r\n    invoke_custom(60500, 1, \"Sound.playSound\", 320001300076009, true, 40)\r\n    invoke_custom(60500, 1, \"bubble\", pahdBoolId, \"quest.shukrute.zone.010.20\")\r\n    invoke_custom(63500, 1, \"clearBubbles\", pahdBoolId)\r\n    \r\n    invoke_custom(64000, 1, \"skipCinematic\", 21652)\nend\n\n-- CLIENT_TRIGGERED_EVENT - On lance le combat\n-- \nfunction event_2489_21653()\n    \nend\n\n-- FIGHT_ENDED_IN_CLIENT - Cinématique\n-- \nfunction event_2489_21654()\n    local playerId = Context.getLeaderId()\r\n    local pahdBoolId = createActor(1300103, -2, -16, 0, 4, 1, 6)\r\n    \r\n    startCinematicContext(1.4, playerId)\r\n    \r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\")\r\n    \r\n    invoke_custom(00100, 1, \"Mobile.setMobileDirection\", playerId, 5)\r\n    \r\n    -- \"J’ai mis la main sur une jurisprudence de la Cour Suprême Shushesque de l'an 124.\"\r\n    invoke_custom(00500, 1, \"bubble\", playerId, \"quest.shukrute.zone.011.01\")\r\n    invoke_custom(00500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Presenter\")\r\n    invoke_custom(05500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Votre prédécesseur a été reconnu fautif pour des faits similaires.\"\r\n    invoke_custom(06500, 1, \"bubble\", playerId, \"quest.shukrute.zone.011.02\")\r\n    invoke_custom(06500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Pointer\")\r\n    invoke_custom(10500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"C'est l'heure de comparaître devant la justice, démon !\"\r\n    invoke_custom(11000, 1, \"bubble\", playerId, \"quest.shukrute.zone.011.03\")\r\n    invoke_custom(11000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Colere\")\r\n    invoke_custom(14500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"D'accord, d'accord, je vais tout t'expliquer.\"\r\n    invoke_custom(14500, 1, \"Sound.playSound\", 320001300076009, true, 40)\r\n    invoke_custom(14500, 1, \"bubble\", pahdBoolId, \"quest.shukrute.zone.011.04\")\r\n    invoke_custom(17500, 1, \"clearBubbles\", pahdBoolId)\r\n    \r\n    -- \"Retrouve-moi à l'endroit habituel...\"\r\n    invoke_custom(18000, 1, \"Sound.playSound\", 320001300076010, true, 40)\r\n    invoke_custom(18000, 1, \"bubble\", pahdBoolId, \"quest.shukrute.zone.011.05\")\r\n    invoke_custom(21000, 1, \"clearBubbles\", pahdBoolId)\r\n    \r\n    invoke_custom(21500, 1, \"skipCinematic\")\nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_2489_21650","event_2489_21651","event_2489_21652","event_2489_21653","event_2489_21654"],"quest_calls":[],"dialogue_calls":[]},"scenario/2490.lua":{"source":"\n\n-- Variables\n-- \nfunction event_2490_21655()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2490_21656(mobOne, mobTwo, mobThree, mobFour, mobFive, mobSix)\n    Mobile.setMobileAnimation(mobOne, \"AnimMort-Fake\")\r\n    Mobile.setMobileAnimation(mobTwo, \"AnimMort-Fake\")\r\n    Mobile.setMobileAnimation(mobThree, \"AnimMort-Fake\")\r\n    Mobile.setMobileAnimation(mobFour, \"AnimMort-Fake\")\r\n    Mobile.setMobileAnimation(mobFive, \"AnimMort-Fake\")\r\n    Mobile.setMobileAnimation(mobSix, \"AnimMort-Fake\")\nend\n\n-- GENERIC_ACTIVABLE_ACTION - On lance le combat\n-- \nfunction event_2490_21657(mobOne, mobTwo, mobThree, mobFour, mobFive, mobSix)\n    Mobile.setMobileAnimation(mobOne, \"AnimRevive\")\r\n    Mobile.setMobileAnimation(mobTwo, \"AnimRevive\")\r\n    Mobile.setMobileAnimation(mobThree, \"AnimRevive\")\r\n    Mobile.setMobileAnimation(mobFour, \"AnimRevive\")\r\n    Mobile.setMobileAnimation(mobFive, \"AnimRevive\")\r\n    Mobile.setMobileAnimation(mobSix, \"AnimRevive\")\r\n    \r\n    invoke(1000, 1, \"Server.triggerEvent\", 21657)\nend\n\n-- TIMER_TICK - Lancement du combat\n-- \nfunction event_2490_21659()\n    \nend\n\n-- FIGHT_ENDED_IN_CLIENT - Notification ACH 4952 OBJ 10269\n-- \nfunction event_2490_21658()\n    UI.displayBackground(402)\nend\n\n","functions":["event_2490_21655","event_2490_21656","event_2490_21657","event_2490_21659","event_2490_21658"],"quest_calls":[],"dialogue_calls":[]},"scenario/2491.lua":{"source":"\n\n-- Variables\n-- \nfunction event_2491_21661()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2491_21662(mobOne, mobTwo, mobThree, mobFour, mobFive, mobSix)\n    Mobile.setMobileAnimation(mobOne, \"AnimMort-Fake\")\r\n    Mobile.setMobileAnimation(mobTwo, \"AnimMort-Fake\")\r\n    Mobile.setMobileAnimation(mobThree, \"AnimMort-Fake\")\r\n    Mobile.setMobileAnimation(mobFour, \"AnimMort-Fake\")\r\n    Mobile.setMobileAnimation(mobFive, \"AnimMort-Fake\")\r\n    Mobile.setMobileAnimation(mobSix, \"AnimMort-Fake\")\nend\n\n-- GENERIC_ACTIVABLE_ACTION - On lance le combat\n-- \nfunction event_2491_21663(mobOne, mobTwo, mobThree, mobFour, mobFive, mobSix)\n    Mobile.setMobileAnimation(mobOne, \"AnimRevive\")\r\n    Mobile.setMobileAnimation(mobTwo, \"AnimRevive\")\r\n    Mobile.setMobileAnimation(mobThree, \"AnimRevive\")\r\n    Mobile.setMobileAnimation(mobFour, \"AnimRevive\")\r\n    Mobile.setMobileAnimation(mobFive, \"AnimRevive\")\r\n    Mobile.setMobileAnimation(mobSix, \"AnimRevive\")\r\n    \r\n    invoke(1000, 1, \"Server.triggerEvent\", 21663)\nend\n\n-- CLIENT_TRIGGERED_EVENT - Lancement du combat\n-- \nfunction event_2491_21664()\n    \nend\n\n-- FIGHT_ENDED_IN_CLIENT - Notification ACH 4989 OBJ 10272\n-- \nfunction event_2491_21665()\n    \nend\n\n","functions":["event_2491_21661","event_2491_21662","event_2491_21663","event_2491_21664","event_2491_21665"],"quest_calls":[],"dialogue_calls":[]},"scenario/2492.lua":{"source":"\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_2492_21666()\n    trace(\"ENTER_INSTANCE\")\nend\n\n-- [EVENT] Clef - ActionGroup déchargé - Shukrute\n-- \nfunction event_2492_21668()\n    UI.writeLocalisedInChat(\"content.145.-6\")\r\n    trace(\"ActionGroup déchargé\")\nend\n\n-- [EVENT] Clef perma - Shukrute\n-- \nfunction event_2492_21669()\n    UI.writeLocalisedInChat(\"contentLoader.infiniteWaves\")\r\n    trace(\"ActionGroup non-Déchargé\")\nend\n\n","functions":["event_2492_21666","event_2492_21668","event_2492_21669"],"quest_calls":[],"dialogue_calls":[]},"scenario/2493.lua":{"source":"\n\n-- Variables\n-- \nfunction event_2493_21676()\n    \nend\n\n-- USER_GROUP_KILLED - On incrémente la variable fightCount\n-- \nfunction event_2493_21678()\n    \nend\n\n-- FIGHT_ENDED_IN_CLIENT - Notification ACH 4992 OBJ 10281\n-- \nfunction event_2493_21677()\n    \nend\n\n","functions":["event_2493_21676","event_2493_21678","event_2493_21677"],"quest_calls":[],"dialogue_calls":[]},"scenario/2494.lua":{"source":"\n\n-- INTERACTIVE_ELEMENT_ACTIVATON - On lance le combat\n-- \nfunction event_2494_21681()\n    \nend\n\n-- FIGHT_ENDED_IN_CLIENT - Notification ACH 4992 OBJ 10284\n-- \nfunction event_2494_21680()\n    \nend\n\n","functions":["event_2494_21681","event_2494_21680"],"quest_calls":[],"dialogue_calls":[]},"scenario/2495.lua":{"source":"\n\n-- INTERACTIVE_ELEMENT_ACTION - notifie aux héros\n-- \nfunction event_2495_21682()\n    \nend\n\n","functions":["event_2495_21682"],"quest_calls":[],"dialogue_calls":[]},"scenario/2496.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\nbubbleFightInfoId = 0\r\n\r\nfunction closeFightInfo()\r\n\tif (bubbleFightInfoId ~= nil  and bubbleFightInfoId ~= 0) then BubbleText.close(bubbleFightInfoId) end\r\nend\r\n\r\nfunction onFightInfoClosed()\r\n\tif (bubbleFightInfoId ~= nil  and bubbleFightInfoId ~= 0) then bubbleFightInfoId = 0 end\r\nend\r\n\r\nfunction updateFightInfo(wave, difficulty, forceDisplayUI)\r\n\tlocal wave = toLong(wave)\r\n\tlocal difficulty = toLong(difficulty)\r\n\r\n\tif (bubbleFightInfoId == 0) then\r\n\t\tbubbleFightInfoId = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_WEST\", 0, -60, false, 2147483647, true, \"interactiveBubbleDialog5\", 30000, 25000, \"onFightInfoClosed\")\r\n\tend\r\n\r\n\tBubbleText.setText(bubbleFightInfoId, \"wave.fight.player.infos\", wave, difficulty)\r\n\r\n\tif (forceDisplayUI) then BubbleText.show(bubbleFightInfoId) end\r\nend\n\n-- [INIT] Variables globales\n-- \nfunction event_2496_21702()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2496_21703()\n    \nend\n\n-- [EVENT] INTERACTIVE_ELEMENT_ACTIVATION - Lancement du combat\n-- \nfunction event_2496_21704()\n    trace(\"LANCEMENT DU COMBAT\")\nend\n\n-- [EVENT] FIGHT_ENTER_ACTION_PHASE - Application états\n-- \nfunction event_2496_21705()\n    \nend\n\n-- [EVENT] NEW_MONSTER_WAVE - Difficulté\n-- \nfunction event_2496_21706(wave, difficulty)\n    updateFightInfo(wave, difficulty, true)\nend\n\n-- [EVENT] EFFECT_EXECUTION - Difficulté\n-- \nfunction event_2496_21707(wave, difficulty)\n    updateFightInfo(wave, difficulty, true)\nend\n\n-- [EVENT] FIGHT_ENDED_IN_CLIENT - On ferme l'affichage\n-- \nfunction event_2496_21708()\n    closeFightInfo()\nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","closeFightInfo","onFightInfoClosed","updateFightInfo","event_2496_21702","event_2496_21703","event_2496_21704","event_2496_21705","event_2496_21706","event_2496_21707","event_2496_21708"],"quest_calls":[],"dialogue_calls":[]},"scenario/2497.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\nbubbleFightInfoId = 0\r\n\r\nfunction closeFightInfo()\r\n\tif (bubbleFightInfoId ~= nil  and bubbleFightInfoId ~= 0) then BubbleText.close(bubbleFightInfoId) end\r\nend\r\n\r\nfunction onFightInfoClosed()\r\n\tif (bubbleFightInfoId ~= nil  and bubbleFightInfoId ~= 0) then bubbleFightInfoId = 0 end\r\nend\r\n\r\nfunction updateFightInfo(wave, difficulty, forceDisplayUI)\r\n\tlocal wave = toLong(wave)\r\n\tlocal difficulty = toLong(difficulty)\r\n\r\n\tif (bubbleFightInfoId == 0) then\r\n\t\tbubbleFightInfoId = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_WEST\", 0, -60, false, 2147483647, true, \"interactiveBubbleDialog5\", 30000, 25000, \"onFightInfoClosed\")\r\n\tend\r\n\r\n\tBubbleText.setText(bubbleFightInfoId, \"wave.fight.player.infos\", wave, difficulty)\r\n\r\n\tif (forceDisplayUI) then BubbleText.show(bubbleFightInfoId) end\r\nend\n\n-- [INIT] Variables globales\n-- \nfunction event_2497_21709()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2497_21710()\n    \nend\n\n-- [EVENT] Activation autel - Lancement du combat\n-- \nfunction event_2497_21711()\n    trace(\"LANCEMENT DU COMBAT\")\nend\n\n-- [EVENT] Démarrage du combat - Application états\n-- \nfunction event_2497_21712()\n    \nend\n\n-- [EVENT] NEW_MONSTER_WAVE - Difficulté\n-- \nfunction event_2497_21713(wave, difficulty)\n    updateFightInfo(wave, difficulty, true)\nend\n\n-- [EVENT] EFFECT_EXECUTION - Difficulté\n-- \nfunction event_2497_21714(wave, difficulty)\n    updateFightInfo(wave, difficulty, true)\nend\n\n-- [EVENT] FIGHT_ENDED_IN_CLIENT - On ferme l'affichage\n-- \nfunction event_2497_21715()\n    closeFightInfo()\nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","closeFightInfo","onFightInfoClosed","updateFightInfo","event_2497_21709","event_2497_21710","event_2497_21711","event_2497_21712","event_2497_21713","event_2497_21714","event_2497_21715"],"quest_calls":[],"dialogue_calls":[]},"scenario/2498.lua":{"source":"\n\n-- [EVENT] Initialisation\n-- \nfunction event_2498_21739()\n    \nend\n\n-- [EVENT] Lancement du combat\n-- \nfunction event_2498_21740(groupId, mobA, fightId, playerId, mobB, mobC, mobD, mobE, mobF, mobG)\n    playerId = toLong(playerId)\r\n    groupId = toLong(groupId)\r\n    fightId = toLong(fightId)\r\n    mobA = toLong(mobA)\r\n    mobB = toLong(mobB)\r\n    mobC = toLong(mobC)\r\n    mobD = toLong(mobD)\r\n    mobE = toLong(mobE)\r\n    mobF = toLong(mobF)\r\n    mobG = toLong(mobG)\r\n    \r\n    trace(\"===Valeur de Player Id ======\", playerId)\r\n    trace(\"===Valeur de Group Id ======\", groupId)\r\n    trace(\"===Valeur de Fight Id ======\", fightId)\r\n    trace(\"===Valeur de MobA Id ======\", mobA)\r\n    trace(\"===Valeur de MobB Id ======\", mobB)\r\n    trace(\"===Valeur de MobC Id ======\", mobC)\r\n    trace(\"===Valeur de MobD Id ======\", mobD)\r\n    trace(\"===Valeur de MobE Id ======\", mobE)\r\n    trace(\"===Valeur de MobF Id ======\", mobF)\r\n    trace(\"===Valeur de MobG Id ======\", mobG)\nend\n\n-- [EVENT] Fin de combat\n-- \nfunction event_2498_21742()\n    \nend\n\n","functions":["event_2498_21739","event_2498_21740","event_2498_21742"],"quest_calls":[],"dialogue_calls":[]},"scenario/2499.lua":{"source":"bubbleSteleInfoId = 0\r\n\r\nfunction closeSteleInfo()\r\n\tif (bubbleSteleInfoId ~= nil  and bubbleSteleInfoId ~= 0) then BubbleText.close(bubbleSteleInfoId) end\r\nend\r\n\r\nfunction onSteleInfoClosed()\r\n\tif (bubbleSteleInfoId ~= nil  and bubbleSteleInfoId ~= 0) then bubbleSteleInfoId = 0 end\r\nend\r\n\r\nfunction updateSteleInfo(stateInfoId, forceDisplayUI)\r\n\r\n\tif (bubbleSteleInfoId == 0) then\r\n\t\tbubbleSteleInfoId = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_WEST\", 0, -60, false, 2147483647, true, \"interactiveBubbleDialog5\", 30000, 25000, \"onSteleInfoClosed\")\r\n\tend\r\n\r\n\tBubbleText.setText(bubbleSteleInfoId, stateInfoId)\r\n\t\r\n\tif (forceDisplayUI) then BubbleText.show(bubbleSteleInfoId) end\r\nend\r\n\r\nfunction openDoor()\r\n\tInteractiveElement.setAnimation(33339, \"AnimTrans_1_0\")\r\nend\n\n-- [INIT] Variables & Constantes\n-- \nfunction event_2499_21758()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2499_21759()\n    openDoor()\nend\n\n-- INTERACTIVE_ELEMENT_ACTIVATION - Ouverture de la porte\n-- \nfunction event_2499_21760()\n    trace(\"OUVERTURE DE LA PORTE\")\r\n    \r\n    openDoor()\nend\n\n-- MONSTER_ACTION_EVENT - Lancement du combat\n-- on skippe la cinématique pour tout le monde \nfunction event_2499_21761()\n    \nend\n\n-- FIGHT_ENTER_ACTION_PHASE - Début de Combat\n-- \nfunction event_2499_21798()\n    \nend\n\n-- FIGHT_ENDED - Rend les monstres inattaquables\n-- \nfunction event_2499_21762()\n    InteractiveElement.setAnimation(33339, \"AnimStatique_0\")\nend\n\n-- [FIGHT] Défaite du combat - Reset les stèles\n-- \nfunction event_2499_21763()\n    \nend\n\n-- [STELE] Le joueur examine une stèle\n-- \nfunction event_2499_21799(steleCount, steleStateId)\n    local steleCount = toLong(steleCount)\r\n    local steleStateId = toLong(steleStateId)\r\n    \r\n    if (steleCount == 0) then\r\n    UI.openRewardsDialog(\"stele.description.tour\")\r\n    UI.addReward(21280)\r\n    UI.addReward(21269)\r\n    UI.addReward(29922)\r\n    \r\n    elseif (steleCount == 1) then\r\n    UI.openRewardsDialog(\"stele.description.tour\")\r\n    UI.addReward(21284)\r\n    UI.addReward(21276)\r\n    UI.addReward(29918)\r\n    \r\n    elseif (steleCount == 2) then\r\n    UI.openRewardsDialog(\"stele.description.tour\")\r\n    UI.addReward(21222)\r\n    UI.addReward(21265)\r\n    UI.addReward(29916)\r\n    \r\n    elseif (steleCount == 3) then\r\n    UI.openRewardsDialog(\"stele.description.tour\")\r\n    UI.addReward(21272)\r\n    UI.addReward(29920)\r\n    UI.addReward(21206, \"stele.reward.stasis.21\")\r\n    \r\n    \r\n    else\r\n    \r\n    end\r\n    \r\n    local stateInfoId = \"stele.state.description.\" .. toString(steleStateId)\r\n    \r\n    updateSteleInfo(stateInfoId, true)\nend\n\n-- [STELE] Le joueur active une stèle\n-- \nfunction event_2499_21764(steleCount, steleStateId)\n    local steleCount = toLong(steleCount)\r\n    local steleStateId = toLong(steleStateId)\r\n    \r\n    if (steleCount == 1) then\r\n    UI.openRewardsDialog(\"stele.description.tour\")\r\n    UI.addReward(21280)\r\n    UI.addReward(21269)\r\n    UI.addReward(29922)\r\n    \r\n    elseif (steleCount == 2) then\r\n    UI.openRewardsDialog(\"stele.description.tour\")\r\n    UI.addReward(21284)\r\n    UI.addReward(21276)\r\n    UI.addReward(29918)\r\n    \r\n    elseif (steleCount == 3) then\r\n    UI.openRewardsDialog(\"stele.description.tour\")\r\n    UI.addReward(21222)\r\n    UI.addReward(21265)\r\n    UI.addReward(29916)\r\n    \r\n    elseif (steleCount == 4) then\r\n    UI.openRewardsDialog(\"stele.description.tour\")\r\n    UI.addReward(21272)\r\n    UI.addReward(29920)\r\n    UI.addReward(21206, \"stele.reward.stasis.21\")\r\n    \r\n    \r\n    else\r\n    \r\n    end\r\n    \r\n    local stateInfoId = \"stele.state.description.\" .. toString(steleStateId)\r\n    \r\n    updateSteleInfo(stateInfoId, true)\nend\n\n-- [STELE] Refresh des APS pour Stèles\n-- \nfunction event_2499_21765()\n    \nend\n\n-- [STASIS] DUNGEON_DIFFICULTY_CHANGED - Reset les stèles\n-- \nfunction event_2499_21766()\n    \nend\n\n-- USER_GROUP_KILLED - BOSS\n-- \nfunction event_2499_23994()\n    \nend\n\n-- [ARCHI] Apparition de l'Archimonstre\n-- \nfunction event_2499_24000()\n    \nend\n\n","functions":["closeSteleInfo","onSteleInfoClosed","updateSteleInfo","openDoor","event_2499_21758","event_2499_21759","event_2499_21760","event_2499_21761","event_2499_21798","event_2499_21762","event_2499_21763","event_2499_21799","event_2499_21764","event_2499_21765","event_2499_21766","event_2499_23994","event_2499_24000"],"quest_calls":["UI.openRewardsDialog(\"stele.description.tour\")\r","UI.openRewardsDialog(\"stele.description.tour\")\r","UI.openRewardsDialog(\"stele.description.tour\")\r","UI.openRewardsDialog(\"stele.description.tour\")\r","UI.openRewardsDialog(\"stele.description.tour\")\r","UI.openRewardsDialog(\"stele.description.tour\")\r","UI.openRewardsDialog(\"stele.description.tour\")\r","UI.openRewardsDialog(\"stele.description.tour\")\r"],"dialogue_calls":[]},"scenario/2500.lua":{"source":"-- CODE GLOBAL --\r\n\r\n-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n-- TRIGGER CLIENT --\r\n-- 0 = Fin cinématique VIDEO | Déclenché par le callback Video.addVideoStopOrEndCallback\r\n-- 1 = Arrivée dans l'instance | Déclenché par onInstanceLoaded() callback par Event.runOnInstanceLoaded (cf code Global)\r\n-- 2 = Fin cinématique | Déclenché par stopCinematicContext() (cf code Global)\r\n-- 3 = Fermeture UI Fin de combat\r\n-- 4 = Clic sur le bon bouton de changement d'oriention (parmis les 4) dans UI worldAndFightBar pour s'orientation vers le monstre\r\n-- 5 = Fermeture UI Fiche combattant\r\n-- 6 = Clic sur le bouton de validation de la répartition dans UI Aptitudes\r\n-- 7 = Clic sur la boussole du bon objectif dans l'UI suivi de quête\r\n-- 8 = Fermeture UI Map Monde\r\n\r\n-- VARIABLE GLOBALE - SCRIPT --\r\n\r\nwidget_visible = {}\r\nwidget_enable = {}\r\nui_tweens = {}\r\nui_particles = {}\r\nui_listener_load = {}\r\nui_listener_unload = {}\r\nui_listener_event = {}\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\nscreenEffectId = nil\r\n\r\n-- VARIABLE GLOBALE - MOBILE CINEMATIQUE & TUTO --\r\n\r\nANM_otomai = {think=\"AnimComp-Special03\", talk=\"AnimComp-Special04-Debut\", show=\"AnimComp-Special05-Debut\", nice=\"AnimComp-Special07\", nope=\"AnimComp-Special08\", lol=\"AnimComp-Special09\", stop_it=\"AnimComp-Special10\", come_here=\"AnimComp-Special01\", wave_hit=\"AnimComp-Special02\", fly=\"AnimStatique-Oiseau\", cast=\"AnimSort-01\", supercast=\"AnimComp-Special11\", attack=\"AnimSort-Cast\", balance=\"AnimComp-Special06\"}\r\nANM_melee = {attack=\"AnimSort-Morsure\", glitch1=\"AnimComp-Glitch01\", glitch2=\"AnimComp-Glitch02\", glitch3=\"AnimComp-Glitch03\", roar=\"AnimComp-Agressif\"}\r\nANM_range = {attack=\"AnimSort-01\", glitch=\"AnimComp-Glitch\", dupli=\"AnimComp-Dupli\"}\r\nANM_boss = {attack1=\"AnimSort-Estoc\", attack2=\"AnimSort-Hrargh\", glitch=\"AnimComp-Glitch\", dupli=\"AnimComp-Dupli\", roar=\"AnimComp-Hurle\", ko = \"AnimKO-SortieOK\", death= \"AnimKO-SortieHS\"}\r\n\r\nNPC_otomai = Mobile.generateClientMobileId()\r\nNPC_otomai_gfx = 181404009\r\nNPC_otomai_particleZ = 10\r\nNPC_otomai_bubbleX = 10\r\nNPC_otomai_bubbleY = 70\r\n\r\nNPC_melee = Mobile.generateClientMobileId()\r\nNPC_meleeB = Mobile.generateClientMobileId()\r\nNPC_melee_gfx = 181404014\r\nNPC_melee_particleZ = 5\r\n\r\nNPC_range = Mobile.generateClientMobileId()\r\nNPC_range_gfx = 181404015\r\nNPC_range_particleZ = 3\r\n\r\nNPC_boss = Mobile.generateClientMobileId()\r\nNPC_boss_gfx = 181404012\r\nNPC_boss_particleZ = 8\r\n\r\nNPC_eni_wakfu = Mobile.generateClientMobileId()\r\nNPC_eni_wakfu_gfx = 181404034\r\nNPC_eni_wakfu_particleZ = 7\r\n\r\nNPC_eni_stasis = Mobile.generateClientMobileId()\r\nNPC_eni_stasis_gfx = 181404013\r\nNPC_eni_stasis_particleZ = 7\r\n\r\n_ACTOR_LIST = {NPC_otomai, NPC_melee, NPC_meleeB, NPC_range, NPC_boss, NPC_eni_wakfu, NPC_eni_stasis}\r\n\r\n-- VARIABLE GLOBALE - PARTICULE CINEMATIQUE & TUTO --\r\n\r\n-- UI TUTO\r\napsArrowBig = {6001069,6001070,6001071,6001072,6001073,6001074,6001075,6001076}\r\napsArrow = {6001061,6001062,6001063,6001064,6001065,6001066,6001067,6001068}\r\napsCenter = {ap=6001090, mp=6001091, wp=6001092, hp=6001093}\r\napsFollowBorder = -1548037644\r\n-- WORLD TUTO\r\napsCell = {white_border=800578, red_border=800579, white_arrow=800576, red_arrow=800577, white=800581, red=800582, show=78900}\r\n-- CINEMATIQUE\r\napsWave = {spawn=800573, wave=800574, hit=800575}\r\napsOtomai = {shield=-1814057071, transform=-1814057072, playershield = -1814057074}\r\napsCristal = {base=71071022, react=800580, shield=71071021}\r\napsBoss = {death=-1814057073}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n    for index, value in ipairs (tab) do\r\n\t\tif isEqual(value, val) then\r\n            return true\r\n        end\r\n    end\r\n\r\n    return false\t\r\nend\r\n\r\n-- FONCTION UI -- Replace le Chat en bas à gauche et le rend indéplaçable/déplaçable\r\nfunction prepareChatUI(movable, chatOffsetX)\r\n\tif not UI.isDialogLoaded(\"chatDialog0\") then return end\r\n\t\r\n\tif (not chatOffsetX) then chatOffsetX = 0 end\r\n\t\r\n\tUI.setPosition(\"chatDialog0\", chatOffsetX, 0)\r\n\tUI.setWindowMovable(\"chatDialog0\", movable)\r\nend\r\n\r\n-- FONCTION UI -- Replace le Suivi de Quête mi-hauteur à gauche et le rend indéplaçable/déplaçable\r\nfunction prepareFollowQuestUI(movable)\r\n    local dialogName = \"\"\r\n    if UI.isDialogLoaded(\"verticalFollowedAchievementsDialog\") then\r\n        dialogName = \"verticalFollowedAchievementsDialog\"\r\n    end\r\n    if UI.isDialogLoaded(\"followedAchievementsDialog\") then\r\n        dialogName = \"followedAchievementsDialog\"\r\n    end\r\n\r\n    if (dialogName == \"\") then\r\n        return\r\n    end\r\n\r\n    local screenH, screenW = UI.getWindowSize()\r\n    local x, y = UI.getPosition(dialogName)\r\n\r\n    UI.setPosition(dialogName, x, screenH / 4)\r\n    UI.setWindowMovable(dialogName, movable)\r\nend\r\n\r\n-- FONCTION UI -- Rend Visible/Invisible certains éléments des interfaces\r\nfunction prepareUI(visible)\r\n  --Interface Boutique & Cadeau\r\n  setWidgetVisible(\"topHudDialog\", \"optionShopButton\", visible)\r\n  setWidgetVisible(\"topHudDialog\", \"giftButton\", visible)\r\n\r\n  --UI sous le Coeur\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"wakfuStasisBar\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"xpBar\", visible)\r\n\r\n  --Boutons hors combat à droite du Coeur\r\n  setWidgetVisible(\"shortcutBarDialog\", \"previousButton\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"nextButton\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseShortcutBar1\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseShortcutBar2\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseShortcutBar3\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseShortcutBar4\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"shortcutBarItemButton\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"shortcutBarSpellButton\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseButtonContainerForTuto1\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseButtonContainerForTuto2\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseButtonContainerForTuto3\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseButtonContainerForTuto4\", visible)\r\n\r\n  --Boutons hors combat à gauche de l'écran - barre d'interfaces\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"firstInterfaceBarBackground\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"secondInterfaceBarBackground\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"extraInterfaceBarDrawerButton\", visible)\r\n\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"fightInfoBtn\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"inventoryButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"buildSheetSetButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"craftButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"questsButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"dungeonButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"cosmeticsButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"tutorialBookButton\", visible)\r\n\r\n  --Boutons hors combat à gauche de l'écran - barre d'interfaces (deuxième barre)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"contactListButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"guildButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"companionsButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"nationButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"battlegroundButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"passportButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"emoteButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"encyclopediaButton\", visible)\r\n\r\n  --Boutons hors combat \"actions rapides\"\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"OverWorldActionsBackground\", visible)\r\n\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"dimensionalBagButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"mapButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"rideMountButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"miniMapButton\", visible)\r\n\r\n  --Boutons en combat à gauche du Coeur\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"FightActionsBackground\", visible)\r\n\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"giveUpButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"hideFightersButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"tacticalModeBtn\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"reportCellBtn\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"fightMarkerBtn\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"lockFightBtn\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"resistanceOverheadBtn\", visible)\r\nend\r\n\r\n-- FONCTION SHORTCUT -- Rend Actif/Inactif certains raccourcis\r\nfunction prepareShortcuts(enabled, shortcutType)\r\n  if not shortcutType or shortcutType == \"WORLD\" then\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.world\", \"enterLeaveBag\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.world\", \"switchHero0\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.world\", \"switchHero1\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.world\", \"switchHero2\")\r\n  end\r\n  if not shortcutType or shortcutType == \"DISPLAY\" then\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"zoomIn\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"zoomOut\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"closeWindows\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"setLODLevel\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"setFightLODLevel\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"showHideNameOverheadsCommand\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"hideFightOccluders\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"alphaMask\")\r\n  end\r\n  if not shortcutType or shortcutType == \"CHAT\" then\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.chat\", \"chat\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.chat\", \"lastContact\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.chat\", \"firstContact\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.chat\", \"autoCompletePlayerName\")\r\n    for bind=1, 9, 1 do\r\n      UI.setShortcutEnabled(enabled, \"shortcutCategory.shortcutBar\", \"bind\" .. toString(bind))\r\n    end\r\n  end\r\n\r\n  if not shortcutType or shortcutType == \"FIGHT\" then\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"fighterTransparency\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"switchTacticalView\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"nextSelectedFighter\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"giveUp\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"lockFight\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"reportCell\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"callHelp\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"displayHpBar\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"resetFightCamera\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"endPlacementAndTurn\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"closeCombatRight\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"closeCombatLeft\")\r\n  end\r\n  if not shortcutType or shortcutType == \"INTERFACE\" then\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"minimap\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"contactList\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"companionManagement\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"guild\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"craft\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"dungeonList\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"achievements\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"quests\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"emotes\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"ecosystem\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"climate\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"nation\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"partySearch\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"passport\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"almanax\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"tutorialBook\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"switchToDirectAttackCommand\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"map\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"spellsInventory\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"inventory\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"characterBook\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"osamodasSymbiot\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"shortcutBar0\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"shortcutBar1\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"shortcutBar2\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"shortcutBar3\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"additionalShortcutBar0\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"additionalShortcutBar1\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"additionalShortcutBar2\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"additionalShortcutBar3\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"changeShortcutBarType\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"downscaling\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"rewards\")\r\n\tUI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"battlegroundList\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"aptitudes\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"presets\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"encyclopedia\")\r\n  end\r\n\r\n  -- On ne bloque pas les raccourcis de sorts finalement\r\n--   if not shortcutType or shortcutType == \"SHORTCUTBAR\" then\r\n--     for bar=0,3, 1 do\r\n--       for slot=0, 9, 1 do\r\n--         UI.setShortcutEnabled(enabled, \"shortcutCategory.shortcutBar\", \"shortcut\" .. toString(bar) .. toString(slot))\r\n--       end\r\n--     end\r\n--   end\r\nend\r\n\r\n-- FONCTION UI -- Rend Visible/Invisible un élément d'une interface\r\nfunction setWidgetVisible(dialogName, widgetName, visible)\r\n  if not UI.isDialogLoaded(dialogName) then return end\r\n\r\n  UI.setWidgetVisibility(dialogName, widgetName, visible)\r\n  table.insert(widget_visible, { name = dialogName, id = widgetName, state = visible })\r\nend\r\n\r\nfunction clearWidgetVisible()\r\n  local str = \"\"\r\n  for i=#widget_visible, 1, -1 do\r\n    str = str .. toString(widget_visible[i].name) .. \"@\" .. toString(widget_visible[i].id) .. \";\"\r\n    UI.setWidgetVisibility(widget_visible[i].name, widget_visible[i].id, true)\r\n  end\r\n\r\n  widget_visible = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearWidgetVisible\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Rend Actif/Inactif un élément d'une interface\r\nfunction setWidgetEnable(dialogName, widgetName, enable)\r\n  if not UI.isDialogLoaded(dialogName) then return end\r\n\r\n  UI.setWidgetEnabled(dialogName, widgetName, enable)\r\n  table.insert(widget_enable, {name = dialogName, id = widgetName, state = enable})\r\nend\r\n\r\nfunction clearWidgetEnable()\r\n  local str = \"\"\r\n  for i=#widget_enable, 1, -1 do\r\n    str = str .. toString(widget_enable[i].name) .. \"@\" .. toString(widget_enable[i].id) .. \";\"\r\n    UI.setWidgetEnabled(widget_enable[i].name, widget_enable[i].id, true)\r\n  end\r\n\r\n  widget_enable = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearWidgetEnable\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Ajoute/Retire une TweenParticle à un élément d'une interface\r\nfunction setUIColorTween(dialogName, widgetName, duration, loop, r1, g1, b1, a1, r2, g2, b2, a2)\r\n  if not UI.isDialogLoaded(dialogName) then return end\r\n\r\n  UI.addColorTween(dialogName, widgetName, duration, loop, r1, g1, b1, a1, r2, g2, b2, a2)\r\n  table.insert(ui_tweens, {name = dialogName, id = widgetName})\r\nend\r\n\r\nfunction clearUIColorTweens(dialogName, widgetName)\r\n  local str = \"\"\r\n  for i=#ui_tweens, 1, -1 do\r\n    if ((not dialogName) or (dialogName == ui_tweens[i].name)) and ((not widgetName) or (widgetName == ui_tweens[i].id)) then\r\n      str = str .. toString(ui_tweens[i].name) .. \"@\" .. toString(ui_tweens[i].id) .. \";\"\r\n      UI.removeColorTween(ui_tweens[i].name, ui_tweens[i].id)\r\n      table.remove(ui_tweens, i)\r\n    end\r\n  end\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearUIColorTweens\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Ajoute/Retire une Particle à un élément d'une interface\r\nfunction setUIParticle(dialogName, widgetName, apsFileName, x, y, alignment, level)\r\n  if not UI.isDialogLoaded(dialogName) then return end\r\n\r\n  local particleId = UI.addParticle(dialogName, widgetName, apsFileName, x, y, alignment, level)\r\n  table.insert(ui_particles, {name = dialogName, id = widgetName})\r\n\r\n  return particleId\r\nend\r\n\r\nfunction setUIParticleBorder(dialogName, widgetName, apsFileName, x, y, alignment, level, speed)\r\n  if not UI.isDialogLoaded(dialogName) then return end\r\n\r\n  local particleId = UI.addParticleToBorder(dialogName, widgetName, apsFileName, x, y, alignment, level, speed)\r\n  table.insert(ui_particles, {name = dialogName, id = widgetName})\r\n\r\n  return particleId\r\nend\r\n\r\nfunction clearUIParticles(dialogName, widgetName)\r\n  local str = \"\"\r\n  for i=#ui_particles, 1, -1 do\r\n    if ((not dialogName) or (dialogName == ui_particles[i].name)) and ((not widgetName) or (widgetName == ui_particles[i].id)) then\r\n      str = str .. toString(ui_particles[i].name) .. \"@\" .. toString(ui_particles[i].id) .. \";\"\r\n      UI.clearParticles(ui_particles[i].name, ui_particles[i].id)\r\n      table.remove(ui_particles, i)\r\n    end\r\n  end\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearUIParticles\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Enregistre/Supprime un callback à l'ouverture d'une interface\r\nfunction addDialogLoadListener(dialog, funcName, ...)\r\n  UI.addDialogLoadedListener(dialog, funcName, unpack(arg))\r\n  table.insert(ui_listener_load,  dialog)\r\nend\r\n\r\nfunction clearDialogLoadListener(dialogName)\r\n  local str = \"\"\r\n  for i=#ui_listener_load, 1, -1 do\r\n    if (not dialogName) or (dialogName == ui_listener_load[i]) then\r\n      str = str .. toString(ui_listener_load[i]) .. \";\"\r\n      UI.removeDialogLoadedListener(ui_listener_load[i])\r\n      table.remove(ui_listener_load, i)\r\n    end\r\n  end\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearDialogLoadListener\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Enregistre/Supprime un callback à la fermeture d'une interface\r\nfunction addDialogUnloadListener(dialog, funcName, ...)\r\n  UI.addDialogUnloadedListener(dialog, funcName, unpack(arg))\r\n  table.insert(ui_listener_unload, dialog)\r\nend\r\n\r\nfunction clearDialogUnloadListener(dialogName)\r\n  local str = \"\"\r\n  for i=#ui_listener_unload, 1, -1 do\r\n    if (not dialogName) or (dialogName == ui_listener_unload[i]) then\r\n      str = str .. toString(ui_listener_unload[i]) .. \";\"\r\n      UI.removeDialogUnloadedListener(ui_listener_unload[i])\r\n      table.remove(ui_listener_unload, i)\r\n    end\r\n  end\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearDialogUnloadListener\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Enregistre/Supprime un callback sur un élément d'une interface\r\nfunction addDialogEventListener(dialog, id, eventType, funcName, ...)\r\n  if not UI.isDialogLoaded(dialog) then return end\r\n\r\n  UI.addEventListener(dialog, id, eventType, funcName, unpack(arg))\r\n  table.insert(ui_listener_event, {dialog=dialog, id=id, eventType=eventType, funcName=funcName})\r\nend\r\n\r\nfunction clearDialogEventListener(dialogName)\r\n  local str = \"\"\r\n  for i=#ui_listener_event, 1, -1 do\r\n    if (not dialogName) or (dialogName == ui_listener_event[i].dialog) then\r\n      str = str .. toString(ui_listener_event[i].dialog) .. \"@\" .. toString(ui_listener_event[i].id) .. \";\"\r\n      UI.removeEventListener(ui_listener_event[i].dialog, ui_listener_event[i].id, ui_listener_event[i].eventType, ui_listener_event[i].funcName)\r\n      table.remove(ui_listener_event, i)\r\n    end\r\n  end\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearDialogEventListener\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y , z, ...)\r\n  local particleId = Particle.addParticleSystem(particleFileId, x, y , z, unpack(arg))\r\n  table.insert(world_particles, particleId)\r\n\r\n  return particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n  local particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n  table.insert(world_particles, particleId)\r\n\r\n  return particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n  local str = \"\"\r\n  for i=#world_particles, 1, -1 do\r\n    str = str .. toString(world_particles[i]) .. \";\"\r\n    Particle.removeParticleSystem(world_particles[i])\r\n  end\r\n\r\n  world_particles = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n  BubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n  if isLower(mobileId, 0) then\r\n    BubbleText.setCharacterSpeak(mobileId, text)\r\n  else\r\n    if (not offsetY) then\r\n      local height = Mobile.getMobileHeight(mobileId)\r\n      if (not height) then height = 6 end\r\n\r\n      offsetY = height * 10\r\n    end\r\n\r\n    if (not offsetX) then offsetX = 0 end\r\n    if (not infiniteDuration) then infiniteDuration = false end\r\n\r\n    BubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n    UI.writeLocalisedInChat(text)\r\n  end\r\n\r\n  if (not tContains(bubbles, mobileId)) then\r\n    table.insert(bubbles, mobileId)\r\n  end\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n  local str = \"\"\r\n  for i = #bubbles, 1, -1 do\r\n    if (not mobileId) then\r\n      str = str .. toString(bubbles[i]) .. \";\"\r\n      BubbleText.closeBubbleAttachedTo(bubbles[i])\r\n    elseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n      str = str .. toString(bubbles[i]) .. \";\"\r\n      BubbleText.closeBubbleAttachedTo(bubbles[i])\r\n      table.remove(bubbles, i)\r\n    end\r\n  end\r\n\r\n  if (not mobileId) then bubbles = {} end\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n  local compassId = UI.addCompass(\"compass\", x, y, z)\r\n  table.insert(compasses, compassId)\r\n\r\n  return compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n  local str = \"\"\r\n  for i=#compasses, 1, -1 do\r\n    str = str .. toString(compasses[i]) .. \";\"\r\n    UI.removeCompass(compasses[i])\r\n  end\r\n\r\n  compasses = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height)\r\n  local mobileId = Mobile.generateClientMobileId()\r\n  Actor.createActor(mobileId, spriteName, worldX, worldY, worldZ, availableDirection)\r\n\r\n  if (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n  if (height) then Actor.setActorHeight(mobileId, height) end\r\n\r\n  table.insert(actors, mobileId)\r\n\r\n  return mobileId\r\nend\r\n\r\nfunction clearActors()\r\n  local str = \"\"\r\n  for i = #actors, 1, -1 do\r\n    str = str .. toString(actors[i]) .. \";\"\r\n    Actor.deleteActor(actors[i])\r\n  end\r\n\r\n  actors = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n  local taskId = invoke(delay, count, funcName, unpack(arg))\r\n  table.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n  local str = \"\"\r\n  for i=#invoke_tasks, 1, -1 do\r\n    str = str .. toString(invoke_tasks[i]) .. \";\"\r\n    interrupt(invoke_tasks[i])\r\n    desinvoke(invoke_tasks[i])\r\n  end\r\n\r\n  invoke_tasks = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n  invoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n  local taskId = setInterval(delay, funcName, unpack(arg))\r\n  table.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n  local str = \"\"\r\n  for i=#interval_tasks, 1, -1 do\r\n    str = str .. toString(interval_tasks[i]) .. \";\"\r\n    interrupt(interval_tasks[i])\r\n    desinvoke(interval_tasks[i])\r\n  end\r\n\r\n  interval_tasks = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n  if (_DEBUG) then trace(\"startCinematicContext\") end\r\n\r\n  UI.manageFrame(\"World\", false)\r\n  UI.closeMRU()\r\n  UI.closeAllBags()\r\n  UI.setUIVisible(false)\r\n  UI.displayWideScreenBand(true)\r\n  Camera.setUserZoomLocked(true)\r\n\r\n  if (cameraMobileId ~= nil)  then\r\n    Camera.setMoveSpeedFactor(10000)\r\n    Camera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n  end\r\n\r\n  if (zoomFactor ~= nil)  then\r\n    Camera.setZoomFactor(zoomFactor)\r\n  end\r\n\r\n  if (musicId ~= nil)  then\r\n    Sound.playForcedMusic(musicId)\r\n  end\r\n\r\n  if (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\nfunction skipCinematic()\r\n  local player = Context.getLeaderId()\r\n\r\n  for x = 1, #_ACTOR_LIST do\r\n    Actor.deleteActor(_ACTOR_LIST[x])\r\n  end\r\n\r\n  UI.hideButton()\r\n  clearALL()\r\n  stopCinematicContext(1, player, true)\r\n  Mobile.setMobileVisible(player, true)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n  if (_DEBUG) then trace(\"stopCinematicContext\") end\r\n\r\n  UI.displayWideScreenBand(false)\r\n  UI.setUIVisible(true)\r\n  Camera.setUserZoomLocked(false)\r\n  UI.manageFrame(\"World\", true)\r\n\r\n  Camera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n  Camera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n  if (zoomFactor ~= nil) then\r\n    Camera.setZoomFactor(zoomFactor)\r\n  end\r\n\r\n  if (cameraMobileId ~= nil) then\r\n    Camera.attachCameraToMobile(cameraMobileId)\r\n  end\r\n\r\n  if (stopMusic) then\r\n    Sound.stopForcedMusic()\r\n  end\r\n\r\n  if (_DEBUG) then\r\n    UI.hideButton()\r\n  end\r\n\r\n  --TRIGGER\r\n  Server.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Affiche/Masque une texture à l'écran\r\nfunction displayScreenEffect(enable, fadeInDur, alphaDur, fadeOutDur, r, g, b, alpha)\r\n  if (_DEBUG) then trace(\"displayScreenEffect\") end\r\n\r\n  if not enable and screenEffectId ~= nil  then\r\n    --On retire le blackScreen\r\n    Effect.stopEffect(screenEffectId)\r\n  else\r\n    --On affiche un blackScreen à l'entrée dans l'instance le temps qu'elle soit complètement chargée\r\n    screenEffectId = Effect.createFullScreenSprite(fadeInDur, alphaDur, fadeOutDur, r, g, b, alpha)\r\n  end\r\nend\r\n\r\n-- FONCTION NETTOYAGE --\r\nfunction clearALL()\r\n  clearIntervalTasks()\r\n  clearInvokeTasks()\r\n  clearBubbles()\r\n  clearUIColorTweens()\r\n  clearUIParticles()\r\n  clearWorldParticles()\r\n  clearCompasses()\r\n  clearActors()\r\n\r\n  Focus.display(false)\r\n  UI.unloadTutorialDialog()\r\nend\r\n\r\n-- FONCTION NETTOYAGE --\r\nfunction clearUI(dialogName)\r\n  clearUIColorTweens(dialogName)\r\n  clearUIParticles(dialogName)\r\nend\r\n\r\n-- FONCTION NETTOYAGE --\r\nfunction clearListener(dialogName)\r\n  clearDialogLoadListener(dialogName)\r\n  clearDialogUnloadListener(dialogName)\r\n  clearDialogEventListener(dialogName)\r\nend\r\n\r\nfunction onInstanceLoaded()\r\n    if (_DEBUG) then\r\n        trace(\"ON INSTANCE LOADED\")\r\n    end\r\n\r\n    prepareShortcuts(false)\r\n    prepareUI(false)\r\n    prepareChatUI(false, 90)\r\n\r\n    UI.setPropertyBooleanValue(\"hideDownscaling\", true)\r\n\r\n    UI.manageFrame(\"World\", true)\r\n    UI.setUIVisible(true)\r\n    displayScreenEffect(false)\r\n\r\n    -- TRIGGER\r\n    Server.triggerEvent(21800)\r\nend\r\n\r\napsId = 800016\r\n\r\nfunction setNewArrowAps(apsId, x, y, z)\r\n    if (arrowAps ~= null) then\r\n        Particle.removeParticleSystem(arrowAps)\r\n    end\r\n\r\n    arrowAps = Particle.addParticleSystem(apsId, x, y, z)\r\nend\r\n\r\nfunction displayGuide(guideId)\r\n    UI.loadGuideDialog(guideId)\r\n\r\n    invoke(100, 1, \"addButton\", guideId)\r\nend\r\n\r\nfunction addButton(guideId)\r\n    UI.displayButton(false, \"guide.displayConfirm\", \"incarnam.guide.displayGuide\", \"displayGuide\", guideId, 0, 150, \"SOUTH\")\r\nend\r\n\r\nfunction setArrowOnSlot(slotNumber)\r\n    setUIParticle(\"shortcutBarDialog\", tostring(\"shortcutBarList#\" .. slotNumber), apsArrow[2] .. \".xps\", 0, 0, \"NORTH\")\r\nend\n\n-- Variables\n-- \nfunction event_2500_22352()\n    \nend\n\n-- ENTER_INSTANCE\n-- \nfunction event_2500_21800()\n    if (_DEBUG) then\r\n        trace(\"ENTER INSTANCE\")\r\n    end\r\n    \r\n    hasShownGuide = false\r\n    \r\n    Event.runOnInstanceLoaded(\"onInstanceLoaded\")\nend\n\n-- ENTER_INSTANCE - On remet le joueur à l'étape à laquelle il s'est arrêté\n-- \nfunction event_2500_22505(tutorielStep)\n    local tutorielStep = toLong(tutorielStep)\r\n    \r\n    if (tutorielStep >= 20) then\r\n        --Le joueur a déjà vaincu le premier Wapin\r\n        Particle.removeParticleSystem(door1)\r\n        Particle.removeParticleSystem(door2)\r\n        Particle.removeParticleSystem(door3)\r\n        Particle.removeParticleSystem(door4)\r\n        Particle.removeParticleSystem(door5)\r\n    end\r\n    \r\n    if (tutorielStep >= 50) then\r\n        --Le joueur a déjà ouvert la porte\r\n        World.setPictoAlpha(11, -35, 1, 0, 1000)\r\n        World.setPictoAlpha(12, -35, 1, 0, 1000)\r\n        World.setPictoAlpha(13, -35, 1, 0, 1000)\r\n    end\r\n    \r\n    if (tutorielStep == 10) then\r\n        -- displayGuide(5)\r\n    elseif (tutorielStep == 20) then\r\n      setNewArrowAps(apsId, 12, -32, -13)\r\n      invoke(5000, 1, \"setArrowOnSlot\", 0)\r\n    elseif (tutorielStep == 25) then\r\n        setNewArrowAps(apsId, 18, -27, -13)\r\n        invoke(5000, 1, \"setArrowOnSlot\", 0)\r\n    elseif (tutorielStep == 30) then\r\n        setNewArrowAps(apsId, 6, -27, -12)\r\n    elseif (tutorielStep == 40) then\r\n        setNewArrowAps(apsId, 12, -35, -13)\r\n    elseif (tutorielStep == 50) then\r\n        setNewArrowAps(apsId, 12, -54, -10)\r\n    end\nend\n\n-- POSITION_TRIGGER - Aller\n-- \nfunction event_2500_22351(positionTriggerId)\n    local positionTriggerId = toLong(positionTriggerId)\r\n    \r\n    trace(\"positionTriggerId variable value = \" .. positionTriggerId)\r\n    \r\n    if (positionTriggerId == 34569) then\r\n        coords = { 12, 0, -16 }\r\n    elseif (positionTriggerId == 34570) then\r\n        coords = { 12, -9, -16 }\r\n    elseif (positionTriggerId == 34571) then\r\n        coords = { 12, -18, -16 }\r\n        if (not hasShownGuide) then\r\n        \tdisplayGuide(127)\r\n        \thasShownGuide = true\r\n        end\r\n    else\r\n        return\r\n    end\r\n    \r\n    setNewArrowAps(apsId, coords[1], coords[2], coords[3])\nend\n\n-- POSITION_TRIGGER - Retour\n-- \nfunction event_2500_22353(positionTriggerId)\n    local positionTriggerId = toLong(positionTriggerId)\r\n    \r\n    trace(\"positionTriggerId variable value = \" .. positionTriggerId)\r\n    \r\n    if (positionTriggerId == 34569) then\r\n        coords = { 5, 0, -4 }\r\n    elseif (positionTriggerId == 34570) then\r\n        coords = { 12, 0, -16 }\r\n    elseif (positionTriggerId == 34571) then\r\n        coords = { 12, -9, -16 }\r\n    end\r\n    \r\n    setNewArrowAps(apsId, coords[1], coords[2], coords[3])\nend\n\n-- 1 - 1 - TRIG(21800) ; Cinématique script\n-- \nfunction event_2500_22519()\n    if (_DEBUG) then trace(\"CINEMATIQUE 1\") end\r\n    \r\n    clearALL()\r\n    \r\n    local playerId = Context.getLeaderId()\r\n    local playerX, playerY, playerZ = Mobile.getMobilePosition(playerId)\r\n    \r\n    Mobile.setMobileDirection(playerId, 1)\r\n    \r\n    startCinematicContext(0.9, playerId)\r\n    -- apsWave = {spawn=800573, wave=800574, hit=800575}\r\n    \r\n    invoke_custom(0010, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimStatique02-Levitation\")\r\n    \r\n    invoke_custom(0100, 1, \"Effect.createCameraShakeEffect\", 1300, 3000, 300, 2)\r\n    invoke_custom(0500, 1, \"Particle.addParticleSystem\", 800573, playerX, playerY, playerZ)\r\n    invoke_custom(1000, 1, \"Camera.setMoveSpeedFactor\", 0.1)\r\n    invoke_custom(1400, 1, \"Camera.setZoomSpeedFactor\", 0.1)\r\n    invoke_custom(1400, 1, \"Camera.setZoomFactor\", 1.9)\r\n    invoke_custom(0500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimIncarnation\")\r\n    invoke_custom(4500, 1, \"Camera.setZoomSpeedFactor\", 2.2)\r\n    invoke_custom(4500, 1, \"Camera.setZoomFactor\", 1)\r\n    invoke_custom(5400, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimKO-Debut\")\r\n    \r\n    invoke_custom(6900, 1, \"Server.triggerEvent\", 22519)\nend\n\n-- 1 - 2 - TRIG(22519) ; Cinématique script - Arbres\n-- \nfunction event_2500_22521()\n    local playerId = Context.getLeaderId()\r\n    \r\n    Mobile.setMobileVisible(playerId, false)\r\n    Mobile.setMobileDirection(playerId, 1)\r\n    \r\n    Camera.setCamera(1.0, 439, 367, 10)\r\n    \r\n    invoke_custom(0800, 1, \"Particle.addParticleSystem\", 800574, 434, 362, 1)\r\n    invoke_custom(0800, 1, \"Mobile.setMobileAnimation\", 3018, \"AnimIncarnation\")\r\n    invoke_custom(0800, 1, \"Mobile.setMobileAnimation\", 3019, \"AnimIncarnation\")\r\n    invoke_custom(0600, 1, \"Effect.createCameraShakeEffect\", 0, 500, 1500, 5)\r\n    invoke_custom(2500, 1, \"Camera.setZoomSpeedFactor\", 0.15)\r\n    invoke_custom(2500, 1, \"Camera.setZoomFactor\", 1.6)\r\n    invoke_custom(2000, 1, \"Particle.addParticleSystem\", 71071018, 439, 367, 4)\r\n    invoke_custom(4000, 1, \"Particle.addParticleSystem\", 71071018, 439, 367, 4)\r\n    \r\n    invoke_custom(7500, 1, \"Server.triggerEvent\", 22521)\nend\n\n-- 1 - 3 - TRIG(22521) ; Cinématique script - Retour sur Incarnam\n-- \nfunction event_2500_22522()\n    function customSkip()\r\n      stopCinematicContext(1, playerId, true)\r\n    \r\n      --Mobile.setMobileVisible(playerId, true)\r\n      --displayScreenEffect(true, 0, 10000, 0, 0, 0, 0, 1)\r\n      --UI.manageFrame(\"World\", false)\r\n      --UI.setUIVisible(false)\r\n    \r\n      arrowAps = Particle.addParticleSystem(apsId, 5, 0, -4)\r\n    \r\n      invoke_custom(700, 1, \"displayGuide\", 126)\r\n    \r\n      door1 = Particle.addParticleSystem(-1939063594, 10, -19, -16)\r\n      door2 = Particle.addParticleSystem(-1939063594, 11, -19, -16)\r\n      door3 = Particle.addParticleSystem(-1939063594, 12, -19, -16)\r\n      door4 = Particle.addParticleSystem(-1939063594, 13, -19, -16)\r\n      door5 = Particle.addParticleSystem(-1939063594, 14, -19, -16)\r\n    end\r\n    \r\n    local playerId = Context.getLeaderId()\r\n    Mobile.setMobileVisible(playerId, true)\r\n    \r\n    startCinematicContext(1.5, playerId)\r\n    \r\n    invoke_custom(00010, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Dormir-Boucle\")\r\n    invoke_custom(03000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Dormir-Fin\")\r\n    \r\n    invoke_custom(04900, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Bailler\")\r\n    \r\n    -- \"On dirait que je viens de me réincarner...\"\r\n    invoke_custom(05500, 1, \"bubble\", playerId, \"quest.rii.00.00\")\r\n    invoke_custom(08500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Bon, commençons par sortir d'ici.\"\r\n    invoke_custom(09000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(09000, 1, \"bubble\", playerId, \"quest.rii.00.01\")\r\n    invoke_custom(12500, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(13000, 1, \"customSkip\")\nend\n\n-- 2 - 0 - MONSTER_ACTION ; Lancement du combat\n-- \nfunction event_2500_22512(fightId)\n    trace(\"22512 - 2 - 0 - MONSTER_ACTION\")\r\n    \r\n    clearALL()\r\n    \r\n    --FUNCTION\r\n    function tuto()\r\n    \tinvoke_custom(500, 1, \"displayGuide\", 104)\r\n    \t\r\n    \t--VISIBILITY UI\r\n    \tsetWidgetVisible(\"shortcutBarDialog\", \"shortcutBarList\", false)\r\n    \t--PARTICLE UI\r\n    \tsetUIParticle(\"worldAndFightBarDialog\", \"MPwidget\", apsCenter.mp .. \".xps\", 0, -2, \"CENTER\")\r\n    \r\n    \t--PARTICLE WORLD\r\n    \tsetWorldParticleCell(apsCell.red_border, 12, -15, -16, 0, fightId)\r\n    end\r\n    \r\n    function fightEnd()\r\n    \tsetWidgetVisible(\"shortcutBarDialog\", \"shortcutBarList\", true)\r\n    end\r\n    \r\n    UI.setShortcutEnabled(true, \"shortcutCategory.fight\", \"resetFightCamera\")\r\n    \r\n    --CODE \r\n    FightEvent.addFightStartCallback(\"tuto\")\r\n    FightEvent.addFightEndCallback(\"fightEnd\")\r\n    \r\n    Camera.setZoomFactor(1.4)\nend\n\n-- 2 - 1 - FIGHTER_MOVE ; Passer son tour (Passer son tour)\n-- \nfunction event_2500_22514()\n    trace(\"22514\")\r\n    \r\n    clearALL()\r\n    \r\n    invoke_custom(1200, 1, \"displayGuide\", 109)\r\n    \r\n    --SHORTCUTS\r\n    UI.setShortcutEnabled(true, \"shortcutCategory.fight\", \"endPlacementAndTurn\")\r\n    \r\n    --PARTICLE UI\r\n    setUIParticle(\"timePointBarDialog\", \"endTurnButton\", apsArrowBig[1] .. \".xps\", -10, 15, \"NORTH_WEST\")\nend\n\n-- 2 - 2 - FIGHTER_END_TURN ; Utiliser son arme (PA, PW)\n-- \nfunction event_2500_22515(fightId)\n    trace(\"TUTO 1 - STEP 5\")\r\n    clearALL()\r\n    \r\n    invoke_custom(1000, 1, \"displayGuide\", 108)\r\n    \r\n    --SHORTCUTS\r\n    UI.setShortcutEnabled(true, \"shortcutCategory.fight\", \"closeCombatRight\")\r\n    UI.setShortcutEnabled(true, \"shortcutCategory.fight\", \"closeCombatLeft\")\r\n    \r\n    --PARTICLE UI\r\n    --setUIParticle(\"shortcutBarDialog\", \"rightHand.border\", apsArrow[2] .. \".xps\", 0, 0, \"NORTH\")\r\n    \r\n    setWorldParticleCell(apsCell.red_border, 12, -18, -16, 0, fightId)\nend\n\n-- 2 - 3 - FIGHT_ENDED_CLIENT + TRIG(1) ; Cinématique\n-- \nfunction event_2500_22354()\n    trace(\"22354 - 1 - FIGHT_ENDED_IN_CLIENT\")\r\n    \r\n    clearALL()\r\n    \r\n    --CINEMATIQUE\r\n    local wodentId = createActor(117402504, 12, -18, -16, 4, 3, 4)\r\n    local playerId = Context.getLeaderId()\r\n    local keyApsId = 800988\r\n    key = Particle.addParticleSystem(keyApsId, 12, -18, -16)\r\n    \r\n    displayScreenEffect(true, 0, 2000, 500, 0, 0, 0, 1)\r\n    setNewArrowAps(apsId, 12, -32, -13)\r\n    \r\n    UI.hideButton()\r\n    \r\n    -- Skip admin\r\n    function customSkip()\r\n        stopCinematicContext(1, playerId, true)\r\n        Actor.deleteActor(wodentId)\r\n        Camera.setZoomFactor(1.0)\r\n    end\r\n    \r\n    startCinematicContext(1.3)\r\n    \r\n    -- \"Ah ! Ça fait du bien de se défouler.\"\r\n    invoke_custom(02000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Pointer\")\r\n    invoke_custom(02000, 1, \"bubble\", playerId, \"quest.incarnam.01.01\")\r\n    invoke_custom(02000, 1, \"Mobile.setMobileAnimation\", wodentId, \"AnimComp-Peur\")\r\n    invoke_custom(02000, 1, \"Camera.attachCameraToMobile\", wodentId)\r\n    \r\n    invoke_custom(05500, 1, \"Mobile.moveMobile\", wodentId, 12, -28, -13)\r\n    invoke_custom(05000, 1, \"Particle.removeParticleSystem\", door1)\r\n    invoke_custom(05000, 1, \"Particle.removeParticleSystem\", door2)\r\n    invoke_custom(05000, 1, \"Particle.removeParticleSystem\", door3)\r\n    invoke_custom(05000, 1, \"Particle.removeParticleSystem\", door4)\r\n    invoke_custom(05000, 1, \"Particle.removeParticleSystem\", door5)\r\n    invoke_custom(07500, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(07500, 1, \"Camera.attachCameraToMobile\", playerId)\r\n    \r\n    -- \"Tiens ? Il semble avoir laissé une clef cassée derrière lui.\"\r\n    invoke_custom(08000, 1, \"bubble\", playerId, \"quest.incarnam.01.02\")\r\n    invoke_custom(08000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-ChercherPiste\")\r\n    invoke_custom(09000, 1, \"Particle.removeParticleSystem\", key)\r\n    \r\n    invoke_custom(11500, 1, \"customSkip\")\nend\n\n-- 3 - 0 - POSITION_TRIGGER - Mini-cinématique\n-- \nfunction event_2500_22525()\n    local playerId = Context.getLeaderId()\r\n    \r\n    startCinematicContext(1.3)\r\n    \r\n    invoke_custom(01000, 1, \"Mobile.setMobileDirection\", playerId, 7)\r\n    \r\n    -- \"**Le chemin est bloqué. Ce Wapin est plus malin qu'il en a l'air...\"\r\n    invoke_custom(01000, 1, \"bubble\", playerId, \"quest.rii.00.02\")\r\n    invoke_custom(01000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(05000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(02000, 1, \"Mobile.setMobileDirection\", playerId, 7)\r\n    \r\n    -- \"**J'ai la clef du portail, mais elle est cassée.\"\r\n    invoke_custom(05500, 1, \"bubble\", playerId, \"quest.rii.00.03\")\r\n    invoke_custom(05500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Non\")\r\n    invoke_custom(09000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"**Avec les bons matériaux, je devrais pouvoir la réparer.\"\r\n    invoke_custom(09500, 1, \"bubble\", playerId, \"quest.rii.00.04\")\r\n    invoke_custom(09500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Presenter\")\r\n    invoke_custom(13000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(13490, 1, \"setNewArrowAps\", apsId, 18, -27, -13)\r\n    \r\n    invoke_custom(13500, 1, \"stopCinematicContext\", 1, player, true)\r\n    invoke_custom(13500, 1, \"displayGuide\", 105)\r\n    invoke_custom(13500, 1, \"Server.triggerEvent\", 22525)\nend\n\n-- 3 - 1 - TRIGG(22525) ; ACH 5140 et on donne les boutures au joueur\n-- \nfunction event_2500_22566()\n    trace(\"22566\")\r\n    \r\n    UI.AddItemShortcut(\"refId\", 30938, 0)\r\n    setArrowOnSlot(0)\nend\n\n-- 3 - 2 - SEED_PLANTED - Le joueur précise qu'il faut attendre\n-- \nfunction event_2500_22524()\n    trace(\"22524 - 2 - SEED_PLANTED\")\r\n    \r\n    local playerId = Context.getLeaderId()\r\n    \r\n    clearUIParticles()\r\n    \r\n    -- \"**Il faut que j'attende quelques secondes que cet arbre pousse.\"\r\n    bubble(playerId, \"quest.rii.00.05\")\r\n    invoke_custom(04500, 1, \"clearBubbles\", playerId)\r\n    invoke_custom(04500, 1, \"displayGuide\", 110)\nend\n\n-- 3 - 3 - RESOURCE_COLLECTED_EVENT - Obtenir le bois\n-- \nfunction event_2500_22356()\n    trace(\"22356 - 3 - RESOURCE_COLLECTED_EVENT\")\r\n    \r\n    clearUIParticles()\r\n    invoke_custom(800, 1, \"displayGuide\", 106)\r\n    setNewArrowAps(apsId, 6, -27, -12)\nend\n\n-- 4 - 0 - CRAFT - Obtenir la clef\n-- \nfunction event_2500_22357()\n    trace(\"22357 - 3 - RESOURCE_COLLECTED_EVENT\")\r\n    \r\n    setNewArrowAps(apsId, 12, -35, -13)\nend\n\n-- 5 - 0 - INTERACTIVE_ELEMENT_ACTIVATION - Ouvrir le portail\n-- \nfunction event_2500_22358()\n    trace(\"22358 - 5 - INTERACTIVE_ELEMENT_ACTIVATION\")\r\n    \r\n    setNewArrowAps(apsId, 12, -54, -10)\r\n    \r\n    World.setPictoAlpha(11, -35, 1, 0, 1000)\r\n    World.setPictoAlpha(12, -35, 1, 0, 1000)\r\n    World.setPictoAlpha(13, -35, 1, 0, 1000)\r\n    \r\n    UI.hideButton()\nend\n\n-- 6 - 0 - MONSTER_ACTION ; Lancement du combat\n-- \nfunction event_2500_22523(fightId)\n    trace(\"22523 - 6 - 0 - MONSTER_ACTION\")\r\n    \r\n    clearALL()\r\n    \r\n    --FUNCTION\r\n    function tuto()\r\n    \tinvoke_custom(1000, 1, \"displayGuide\", 128)\r\n    \t\r\n    \t--PARTICLE WORLD\r\n    \tsetWorldParticleCell(apsCell.red_border, 12, -53, -10, 0, fightId)\r\n    end\r\n    \r\n    UI.setShortcutEnabled(true, \"shortcutCategory.fight\", \"resetFightCamera\")\r\n    Camera.setZoomFactor(1.4)\r\n    \r\n    --CODE \r\n    FightEvent.addFightStartCallback(\"tuto\")\nend\n\n-- 6 - 1 - FIGHTER_MOVE ; Lancer un sort\n-- \nfunction event_2500_22528()\n    trace(\"22528\")\r\n    \r\n    clearALL()\r\n    \r\n    invoke_custom(1200, 1, \"displayGuide\", 129)\r\n    \r\n    --SHORTCUTS\r\n    UI.setShortcutEnabled(true, \"shortcutCategory.fight\", \"endPlacementAndTurn\")\r\n    \r\n    --PARTICLE UI\r\n    setUIParticle(\"shortcutBarDialog\", \"shortcutBarList#0\", apsArrow[2] .. \".xps\", 0, 0, \"NORTH\")\r\n    setUIParticle(\"shortcutBarDialog\", \"shortcutBarList#1\", apsArrow[2] .. \".xps\", 0, 0, \"NORTH\")\r\n    setUIParticle(\"shortcutBarDialog\", \"shortcutBarList#2\", apsArrow[2] .. \".xps\", 0, 0, \"NORTH\")\r\n    setUIParticle(\"worldAndFightBarDialog\", \"APwidget\", apsCenter.ap .. \".xps\", 0, -2, \"CENTER\")\nend\n\n-- 6 - 2 - FIGHT_END_CLIENT + TRIG(1) ; Cinématique\n-- \nfunction event_2500_22359()\n    trace(\"22359 - 5 - FIGHT_ENDED_IN_CLIENT\")\r\n    \r\n    clearALL()\r\n    \r\n    UI.hideButton()\r\n    \r\n    --CINEMATIQUE\r\n    local wodentId = createActor(117402504, 12, -53, -10, 4, 5, 4)\r\n    local darkWodentId = createActor(117402507, 11, -45, -13, 4, 5, 4)\r\n    local playerId = Context.getLeaderId()\r\n    \r\n    Mobile.setMobilePosition(playerId, 8, -53, -10)\r\n    Mobile.setMobileDirection(playerId, 1)\r\n    Mobile.setMobileVisible (darkWodentId, false)\r\n    Mobile.setMobileMovementStyle(playerId, \"WALK\", \"WALK\")\r\n    \r\n    setNewArrowAps(apsId, 0, 0, 0)\r\n    \r\n    function customSkip()\r\n    \tskipCinematic()\r\n    \tServer.triggerEvent(22359)\r\n    end\r\n    \r\n    startCinematicContext(1.3, wodentId)\r\n    \r\n    invoke_custom(00100, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimStatique02\")\r\n    invoke_custom(00500, 1, \"Mobile.setMobileAnimation\", wodentId, \"AnimComp-Peur\")\r\n    \r\n    invoke_custom(02000, 1, \"Mobile.moveMobile\", wodentId, 12, -43, -13)\r\n    \r\n    -- \"Je crois que je l'ai trop impressionné ! Haha, fuis !\"\r\n    invoke_custom(04500, 1, \"bubble\", playerId, \"quest.ri.02.01\")\r\n    invoke_custom(04500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Rire\")\r\n    invoke_custom(04000, 1, \"Camera.attachCameraToMobile\", playerId)\r\n    invoke_custom(07500, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(07500, 1, \"Mobile.moveMobile\", playerId, 4, -55, -10, \"Mobile.setMobileDirection\", playerId, 5)\r\n    \r\n    -- \"Je me demande si on peut voir le Monde des Douze d'ici...\"\r\n    invoke_custom(10500, 1, \"bubble\", playerId, \"quest.rii.00.06\")\r\n    invoke_custom(11000, 1, \"Camera.setZoomSpeedFactor\", 0.15)\r\n    invoke_custom(11000, 1, \"Camera.setZoomFactor\", 1.5)\r\n    invoke_custom(11000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Chercher\")\r\n    invoke_custom(15000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(15500, 1, \"Mobile.moveMobile\", wodentId, 12, -55, -10, \"Mobile.setMobileDirection\", wodentId, 5)\r\n    \r\n    invoke_custom(17000, 1, \"Mobile.setMobileDirection\", playerId, 1)\r\n    \r\n    -- \"Quoi ?\"\r\n    invoke_custom(17000, 1, \"bubble\", playerId, \"quest.rii.00.07\")\r\n    invoke_custom(17500, 1, \"Camera.setZoomFactor\", 1.2)\r\n    invoke_custom(18500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Encore ce Wapin... N'est-il pas trop résistant ?\"\r\n    invoke_custom(19000, 1, \"bubble\", playerId, \"quest.rii.00.08\")\r\n    invoke_custom(19000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmoteMarket-HausseEpaules\")\r\n    invoke_custom(22500, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(20400, 1, \"Mobile.setMobileVisible\", darkWodentId, true)\r\n    invoke_custom(20500, 1, \"Mobile.moveMobile\", darkWodentId, 11, -55, -10, \"Mobile.setMobileDirection\", darkWodentId, 5)\r\n    \r\n    -- \"Mais... Il y en avait un autre ?\"\r\n    invoke_custom(23000, 1, \"bubble\", playerId, \"quest.rii.00.09\")\r\n    invoke_custom(23000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Effrayee\")\r\n    invoke_custom(26500, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(23000, 1, \"Camera.setZoomFactor\", 1.3)\r\n    invoke_custom(25000, 1, \"Camera.setZoomFactor\", 1.4)\r\n    invoke_custom(27000, 1, \"Camera.setZoomFactor\", 1.5)\r\n    \r\n    invoke_custom(23000, 1, \"Mobile.moveMobile\", darkWodentId, 11, -55, -10)\r\n    invoke_custom(25000, 1, \"Mobile.moveMobile\", darkWodentId, 9, -55, -10)\r\n    invoke_custom(27000, 1, \"Mobile.moveMobile\", darkWodentId, 7, -55, -10)\r\n    invoke_custom(29000, 1, \"Mobile.setMobileAnimation\", darkWodentId, \"AnimSort-PattesSombre\")\r\n    invoke_custom(29500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Effrayee\")\r\n    \r\n    -- \"Tout doux !\"\r\n    invoke_custom(31000, 1, \"bubble\", playerId, \"quest.rii.00.10\")\r\n    invoke_custom(31000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Calmer\")\r\n    invoke_custom(33500, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(33500, 1, \"Mobile.moveMobile\", darkWodentId, 5, -55, -10)\r\n    invoke_custom(34200, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Help\")\r\n    invoke_custom(35900, 1, \"Mobile.setMobileAnimation\", darkWodentId, \"AnimSort-CoupSombre\")\r\n    \r\n    -- \"Woah !!!\"\r\n    invoke_custom(37000, 1, \"bubble\", playerId, \"quest.rii.00.11\")\r\n    invoke_custom(38000, 1, \"clearBubbles\", playerId)\r\n    invoke_custom(36900, 1, \"Mobile.setMobileDirection\", playerId, 5)\r\n    invoke_custom(37000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimHit\")\r\n    invoke_custom(37200, 1, \"Mobile.addCubicSplineTweenToMobile\", playerId, 2, -55, -10, 500, -3, 0, 0, -1, 0, 0)\r\n    invoke_custom(37800, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimIncarnam-Chute-Debut\")\r\n    invoke_custom(39000, 1, \"Mobile.setMobileAnimation\", darkWodentId, \"AnimSort-BidonSombre\")\r\n    \r\n    invoke_custom(39999, 1, \"Mobile.setMobileMovementStyle\", darkWodentId, \"WALK\", \"WALK\")\r\n    invoke_custom(40000, 1, \"Mobile.moveMobile\", darkWodentId, 11, -55, -10)\r\n    \r\n    invoke_custom(43000, 1, \"customSkip\")\nend\n\n-- 7 - 0 - CLIENT_TRIGGERED_EVENT - Téléportation vers Rii\n-- \nfunction event_2500_22500()\n    trace(\"TUTO - FIN\")\r\n    \r\n    clearALL()\r\n    clearListener()\r\n    \r\n    displayScreenEffect(false)\r\n    prepareUI(true)\r\n    prepareShortcuts(true)\r\n    \r\n    UI.setPropertyBooleanValue(\"hideDownscaling\", false)\nend\n\n-- EVENT - Le joueur a moins de 3 PA, on indique passer son tour\n-- \nfunction event_2500_22529(tutorielStep)\n    local tutorielStep = toLong(tutorielStep)\n    local playerId = Context.getLeaderId()\n    \n    function clearTurnButtonParticle()\n    \tUI.clearParticles(\"timePointBarDialog\", \"endTurnButton\")\n    \t\n    \tif (tutorielStep == 10) then\n    \t\tsetUIParticle(\"worldAndFightBarDialog\", \"rightHand.border\", apsArrow[2] .. \".xps\", 0, 0, \"NORTH\")\n    \telseif (tutorielStep == 50) then\n    \t\tsetUIParticle(\"shortcutBarDialog\", \"shortcutBarList#0\", apsArrow[2] .. \".xps\", 0, 0, \"NORTH\")\n    \t    setUIParticle(\"shortcutBarDialog\", \"shortcutBarList#1\", apsArrow[2] .. \".xps\", 0, 0, \"NORTH\")\n        \tsetUIParticle(\"shortcutBarDialog\", \"shortcutBarList#2\", apsArrow[2] .. \".xps\", 0, 0, \"NORTH\")\n        \tsetUIParticle(\"worldAndFightBarDialog\", \"APwidget\", apsCenter.ap .. \".xps\", 0, -2, \"CENTER\")\t\n        end\n    end\r\n    \r\n    --On utilise une particule sans la référencer pour pas qu'elle soit delete quand ça passe au tuto suivant\n    UI.addParticle(\"timePointBarDialog\", \"endTurnButton\", apsArrowBig[1] .. \".xps\", -10, 15, \"NORTH_WEST\")\r\n    \r\n    Event.setFightTurnStartedListener(playerId, \"clearTurnButtonParticle\")\nend\n\n","functions":["tContains","prepareChatUI","prepareFollowQuestUI","prepareUI","prepareShortcuts","setWidgetVisible","clearWidgetVisible","setWidgetEnable","clearWidgetEnable","setUIColorTween","clearUIColorTweens","setUIParticle","setUIParticleBorder","clearUIParticles","addDialogLoadListener","clearDialogLoadListener","addDialogUnloadListener","clearDialogUnloadListener","addDialogEventListener","clearDialogEventListener","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","bubble","clearBubbles","setCompass","clearCompasses","createActor","clearActors","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","startCinematicContext","skipCinematic","stopCinematicContext","displayScreenEffect","clearALL","clearUI","clearListener","onInstanceLoaded","setNewArrowAps","displayGuide","addButton","setArrowOnSlot","event_2500_22352","event_2500_21800","event_2500_22505","event_2500_22351","event_2500_22353","event_2500_22519","event_2500_22521","event_2500_22522","customSkip","event_2500_22512","tuto","fightEnd","event_2500_22514","event_2500_22515","event_2500_22354","customSkip","event_2500_22525","event_2500_22566","event_2500_22524","event_2500_22356","event_2500_22357","event_2500_22358","event_2500_22523","tuto","event_2500_22528","event_2500_22359","customSkip","event_2500_22500","event_2500_22529","clearTurnButtonParticle"],"quest_calls":[],"dialogue_calls":[]},"scenario/2501.lua":{"source":"\n\n-- [INITIALISATION] Variables\n-- \nfunction event_2501_21864()\n    \nend\n\n-- [EVENT] Inscription au scénario\n-- \nfunction event_2501_21865(randomAffixe)\n    trace(\"ENTER\", randomAffixe)\nend\n\n-- DUNGEON_DIFFICULTY_CHANGED - Refresh les Bonus Stasis + Notification sur tous les joueurs\n-- \nfunction event_2501_21866(dungeonDifficulty)\n    local difficulty = toLong(dungeonDifficulty)\r\n    \r\n    --UI.displaySplashText(\"dungeon.stasis.difficulty.changed\", difficulty)\r\n    \r\n    local bubble = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_EAST\", -75, -50, false, 10000, true, \"interactiveBubbleDialog4\")\r\n    \r\n    BubbleText.setText(bubble, \"dungeon.stasis.difficulty.changed\", difficulty)\r\n    BubbleText.show(bubble)\nend\n\n-- DUNGEON_LADDER_CANCELLED - Notification sur tous les joueurs\n-- \nfunction event_2501_21867()\n    local bubble = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_EAST\", -75, -50, false, 10000, true, \"interactiveBubbleDialog4\")\r\n    \r\n    BubbleText.setText(bubble, \"dungeon.stasis.ladder.cancelled\")\r\n    BubbleText.show(bubble)\nend\n\n-- PLAYERS_WON_FIGHT - Reroll affixe Stasis\n-- \nfunction event_2501_21868(randomAffixe)\n    trace(\"REROLL\", randomAffixe)\nend\n\n-- MONSTER_WON_FIGHT - Interdit le Spawn de Mimic\n-- \nfunction event_2501_21869()\n    \nend\n\n-- FIGHT_ENTER_ACTION_PHASE - Roll pour savoir si Spawn de Mimic\n-- \nfunction event_2501_21870()\n    \nend\n\n-- FIGHT_ENTER_ACTION_PHASE - Applique l'état Mimic sur 1 monstre aléatoire\n-- \nfunction event_2501_21871()\n    \nend\n\n-- FIGHT_ENTER_ACTION_PHASE - Applique l'état Caractéristiques Stasis sur tous les monstres\n-- \nfunction event_2501_21872()\n    \nend\n\n-- FIGHT_ENTER_ACTION_PHASE - Applique l'état Affixe Stasis rollé sur tous les monstres\n-- \nfunction event_2501_21873()\n    \nend\n\n-- ADMIN - Affixe Stasis +1\n-- \nfunction event_2501_21875(randomAffixe)\n    trace(\"AFFIX\", randomAffixe)\nend\n\n-- ADMIN - Affixe Stasis -1\n-- \nfunction event_2501_21876(randomAffixe)\n    trace(\"AFFIX\", randomAffixe)\nend\n\n","functions":["event_2501_21864","event_2501_21865","event_2501_21866","event_2501_21867","event_2501_21868","event_2501_21869","event_2501_21870","event_2501_21871","event_2501_21872","event_2501_21873","event_2501_21875","event_2501_21876"],"quest_calls":[],"dialogue_calls":[]},"sc