e zaap qui permet de quitter l'île Céleste ! Même si tu es libre de revenir à tout moment, je ne pourrai plus assurer ta sécurité à partir du moment où tu l'auras activé\"\r\n    invoke_custom(10500, 1, \"bubble\", monsterId, \"quest.rii.03.03\")\r\n    invoke_custom(10500, 1, \"Mobile.setMobileAnimation\", monsterId, \"AnimComp-Special04-Debut\", \"Mobile.setMobileAnimation\", monsterId, \"AnimComp-Special04-Boucle\", \"Mobile.setMobileAnimation\", monsterId, \"AnimComp-Special04-Boucle\", \"Mobile.setMobileAnimation\", monsterId, \"AnimComp-Special04-Boucle\", \"Mobile.setMobileAnimation\", monsterId, \"AnimComp-Special-Fin\")\r\n    invoke_custom(17000, 1, \"clearBubbles\", monsterId)\r\n    \r\n    -- \"Tu t'exposerais à beaucoup moins de danger en terminant d'abord ta remise à niveau sur cette île !\"\r\n    invoke_custom(17500, 1, \"bubble\", monsterId, \"quest.rii.03.04\")\r\n    invoke_custom(17500, 1, \"Mobile.setMobileAnimation\", monsterId, \"AnimComp-Special04-Debut\", \"Mobile.setMobileAnimation\", monsterId, \"AnimComp-Special04-Boucle\", \"Mobile.setMobileAnimation\", monsterId, \"AnimComp-Special04-Boucle\", \"Mobile.setMobileAnimation\", monsterId, \"AnimComp-Special04-Boucle\", \"Mobile.setMobileAnimation\", monsterId, \"AnimComp-Special-Fin\")\r\n    invoke_custom(24000, 1, \"clearBubbles\", monsterId)\r\n    \r\n    -- \"Je ne t'empêche pas d'y aller, mais si j'y réfléchirais à deux fois si j'étais toi !\"\r\n    invoke_custom(24500, 1, \"bubble\", monsterId, \"quest.rii.03.05\")\r\n    invoke_custom(24500, 1, \"Mobile.setMobileAnimation\", monsterId, \"AnimComp-Special07\")\r\n    \r\n    invoke_custom(27000, 1, \"Camera.attachCameraToMobile\", playerId)\r\n    invoke_custom(29500, 1, \"Particle.addParticleSystem\", 800631, 3, -21, 7)\r\n    invoke_custom(29500, 1, \"Mobile.setMobileVisible\", monsterId, false)\r\n    \r\n    invoke_custom(29500, 1, \"clearBubbles\", monsterId)\r\n    \r\n    invoke_custom(30000, 1, \"customSkip\")\nend\n\n-- CLIENT_TRIGGERED_EVENT - 2 - 1 - Fin de la cinématique, le joueur est téléporté un peu avant\n-- \nfunction event_2536_22537()\n    \nend\n\n-- POSITION_TRIGGER - 3 - 0 - Le joueur veut quitter Rii (ACH 5161)\n-- \nfunction event_2536_22534()\n    local playerId = Context.getLeaderId()\r\n    local darkWodentId = createActor(117402507, 3, -10, 1, 4, 5, 4)\r\n    \r\n    function customSkip()\r\n    \tMobile.hideOtherPlayerMobile(false)\r\n    \tclearCinematic()\r\n    \tServer.triggerEvent(22534)\r\n    end\r\n    \r\n    Mobile.setMobileVisible(darkWodentId, false)\r\n    Mobile.hideOtherPlayerMobile(true)\r\n    \r\n    startCinematicContext(1.6, playerId)\r\n    \r\n    invoke_custom(00050, 1, \"Mobile.moveMobile\", playerId, 3, -18, 4, \"Mobile.setMobileDirection\", playerId, 7)\r\n    \r\n    invoke_custom(01000, 1, \"Mobile.moveMobile\", playerId, 3, -18, 4, \"Mobile.setMobileDirection\", playerId, 7)\r\n    \r\n    -- \"En prenant ce portail, je pourrai aller sur le \"Monde des Douze\".\"\r\n    invoke_custom(00500, 1, \"Camera.setCamera\", 1.6, 3, -22, 7)\r\n    invoke_custom(01500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Presenter\")\r\n    invoke_custom(01500, 1, \"bubble\", playerId, \"quest.rii.06.00\")\r\n    invoke_custom(06000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(06000, 1, \"Camera.attachCameraToMobile\", playerId)\r\n    invoke_custom(06000, 1, \"Mobile.setMobileMovementStyle\", playerId, \"WALK\", \"WALK\")\r\n    \r\n    invoke_custom(06500, 1, \"Mobile.moveMobile\", playerId, 6, -20, 5, \"Mobile.setMobileDirection\", playerId, 1)\r\n    \r\n    -- \"Je me demande si on peut le voir d'ici...\"\r\n    invoke_custom(10000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Chercher\")\r\n    invoke_custom(07500, 1, \"bubble\", playerId, \"quest.rii.06.01\")\r\n    invoke_custom(12000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(08500, 1, \"Camera.setZoomSpeedFactor\", 0.1)\r\n    invoke_custom(08500, 1, \"Camera.setZoomFactor\", 1.3)\r\n    \r\n    invoke_custom(15000, 1, \"Mobile.setMobileVisible\", darkWodentId, true)\r\n    invoke_custom(15500, 1, \"Mobile.moveMobile\", darkWodentId, 3, -20, 7, \"Mobile.setMobileDirection\", darkWodentId, 1)\r\n    \r\n    -- \"J'ai comme une impression de déjà vu.\"\r\n    invoke_custom(13500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(13500, 1, \"bubble\", playerId, \"quest.rii.06.02\")\r\n    invoke_custom(16500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"La dernière fois que je scrutais l'horizon, ce Wapin m'avait poussé...\"\r\n    invoke_custom(17000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmoteMarket-HausseEpaules\")\r\n    invoke_custom(17000, 1, \"bubble\", playerId, \"quest.rii.06.03\")\r\n    invoke_custom(23000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Si je le recroise, je lui fais manger des cawottes !\"\r\n    invoke_custom(23500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Colere\")\r\n    invoke_custom(23500, 1, \"bubble\", playerId, \"quest.rii.06.04\")\r\n    invoke_custom(26500, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(24500, 1, \"Mobile.setMobileMovementStyle\", darkWodentId, \"WALK\", \"WALK\")\r\n    invoke_custom(24500, 1, \"Mobile.moveMobile\", darkWodentId, 5, -20, 6, \"Mobile.setMobileDirection\", darkWodentId, 1)\r\n    \r\n    invoke_custom(27500, 1, \"Camera.setZoomSpeedFactor\", 1.0)\r\n    invoke_custom(27500, 1, \"Camera.setZoomFactor\", 2.0)\r\n    \r\n    invoke_custom(29000, 1, \"Mobile.setMobileDirection\", playerId, 3)\r\n    invoke_custom(29500, 1, \"Mobile.setMobileDirection\", playerId, 5)\r\n    \r\n    invoke_custom(30000, 1, \"Mobile.setMobileAnimation\", darkWodentId, \"AnimSort-CoupSombre\")\r\n    \r\n    -- \"Nooon !!!\"\r\n    invoke_custom(29500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEffrayee\")\r\n    invoke_custom(30000, 1, \"bubble\", playerId, \"quest.rii.06.05\")\r\n    invoke_custom(33000, 1, \"clearBubbles\", playerId)\r\n    invoke_custom(31000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimHit\")\r\n    invoke_custom(31200, 1, \"Mobile.addCubicSplineTweenToMobile\", playerId, 8, -20, 5, 500, 2, 0, 0, -1, 0, 0)\r\n    invoke_custom(31800, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimIncarnam-Chute-Debut\")\r\n    invoke_custom(33000, 1, \"Mobile.setMobileAnimation\", darkWodentId, \"AnimSort-BidonSombre\")\r\n    \r\n    invoke_custom(33999, 1, \"Mobile.setMobileMovementStyle\", darkWodentId, \"WALK\", \"WALK\")\r\n    invoke_custom(34000, 1, \"Mobile.moveMobile\", darkWodentId, 3, -8, 1)\r\n    \r\n    invoke_custom(37000, 1, \"customSkip\")\nend\n\n-- CLIENT_TRIGGERED_EVENT - 3 - 1 - Fin de la cinématique, le joueur va sur Astrub (ACH 5161)\n-- Déclencheur du TP vers Astrub après la cinématique\nfunction event_2536_22536()\n    \nend\n\n-- [EVENT] DIALOG_EXECUTED - Khéperalia - Affichage du guide - 1\n-- \nfunction event_2536_22538()\n    invoke(500, 1, \"UI.loadGuideDialog\", 122)\nend\n\n-- [EVENT] DIALOG_EXECUTED - Khéperalia - Affichage du guide - 2\n-- \nfunction event_2536_22539()\n    invoke(500, 1, \"UI.loadGuideDialog\", 123)\r\n    invoke(500, 1,\t\"UI.AddItemShortcut\", \"refId\", 31007)\nend\n\n-- [QUETE] SEED_PLANTED - Wapin\n-- \nfunction event_2536_24024()\n    \nend\n\n-- [QUETE] SEED_PLANTED - Fleur\n-- \nfunction event_2536_24028()\n    \nend\n\n-- [QUETE] RESOURCE_COLLECTED_EVENT - Wapin\n-- \nfunction event_2536_24025()\n    \nend\n\n-- [QUETE] RESOURCE_COLLECTED_EVENT - Graine\n-- \nfunction event_2536_24026()\n    \nend\n\n-- [QUETE] RESOURCE_COLLECTED_EVENT - Fleur\n-- \nfunction event_2536_24027()\n    \nend\n\n-- [QUETE] ITEM_CRAFT_EVENT - Fiole\n-- \nfunction event_2536_24029()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","clearTempleClasse","getBreedIndex","updateTempleClasse","updateBookTitle","prepareTempleClasse","onButtonNext","onButtonPrevious","onButtonBook","event_2536_22339","event_2536_22417","event_2536_22360","customSkip","event_2536_22530","event_2536_22533","customSkip","event_2536_22537","event_2536_22534","customSkip","event_2536_22536","event_2536_22538","event_2536_22539","event_2536_24024","event_2536_24028","event_2536_24025","event_2536_24026","event_2536_24027","event_2536_24029"],"quest_calls":[],"dialogue_calls":[]},"scenario/2537.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\n\n-- INIT - Variables\n-- \nfunction event_2537_22348()\n    \nend\n\n-- POSITION_TRIGGER - Cinématique d'arrivée devant la porte\n-- \nfunction event_2537_22349()\n    local playerId = Context.getLeaderId()\r\n    local screamCharacter = createActor(104000326, 89, -112, 30, 4)\r\n    \r\n    startCinematicContext(1.2, playerId)\r\n    \r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 22349)\r\n    Mobile.setMobileDirection(playerId, 7)\r\n    \r\n    invoke_custom(02000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Chercher\")\r\n    invoke_custom(02000, 1, \"Mobile.setMobileDirection\", playerId, 5)\r\n    invoke_custom(03000, 1, \"Mobile.setMobileDirection\", playerId, 1)\r\n    \r\n    -- \"**Aucun Crapaud Mufle à l'horizon...\"\r\n    invoke_custom(04000, 1, \"bubble\", playerId, \"quest.amakna.missmoches.01.01\")\r\n    \r\n    -- \"**Je vais retourner voir Alibert, il n'a pas dû m'indiquer le bon endroit.\"\r\n    invoke_custom(06000, 1, \"bubble\", playerId, \"quest.amakna.missmoches.01.02\")\r\n    \r\n    invoke_custom(07500, 1, \"Mobile.setMobileMovementStyle\", playerId, \"WALK\", \"WALK\")\r\n    invoke_custom(07500, 1, \"Mobile.setCustomWalkStyle\", playerId, \"AnimMarche\", 600)\r\n    invoke_custom(07500, 1, \"Mobile.moveMobile\", playerId, 90, -101, 30)\r\n    \r\n    --\r\n    \r\n    invoke_custom(09000, 1, \"Camera.setCamera\", 1.3, 90, -112, 30)\r\n    invoke_custom(09500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"AU SECOUUUUUUUURS, A MOIIIIIIIIIIIII !!!\"\r\n    invoke_custom(10000, 1, \"bubble\", screamCharacter, \"quest.amakna.missmoches.01.03\")\r\n    invoke_custom(11000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Effrayee\")\r\n    \r\n    invoke_custom(12500, 1, \"Mobile.setMobileDirection\", playerId, 7)\r\n    invoke_custom(13000, 1, \"Camera.attachCameraToMobile\", playerId)\r\n    \r\n    invoke_custom(13500, 1, \"Mobile.setMobileMovementStyle\", playerId, \"RUN\", \"RUN\")\r\n    \r\n    invoke_custom(13500, 1, \"Mobile.moveMobile\", playerId, 90, -105, 30)\r\n    \r\n    -- \"**Qu'est-ce que c'est ?\"\r\n    invoke_custom(15000, 1, \"bubble\", playerId, \"quest.amakna.missmoches.01.04\")\r\n    invoke_custom(15500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(17500, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(18000, 1, \"Camera.setCamera\", 1.3, 90, -112, 30)\r\n    \r\n    -- \"JE SUIS PRISONNIÈRE DE CETTE TOUR !\"\r\n    invoke_custom(18000, 1, \"bubble\", screamCharacter, \"quest.amakna.missmoches.01.05\")\r\n    \r\n    --\"EST-CE QU'UN VALEUREUX CHEVALIER AURA LE COURAGE DE VENIR ME SAUVER, MOI, LA PRINCESSE YDALIPE ?\"\r\n    invoke_custom(20000, 1, \"bubble\", screamCharacter, \"quest.amakna.missmoches.01.06\")\r\n    \r\n    invoke_custom(23500, 1, \"clearBubbles\", screamCharacter)\r\n    \r\n    -- \"**Par les Douze, une princesse en détresse ! Il faut absolument que j'aille la sauver !\"\r\n    invoke_custom(25500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Colere\")\r\n    invoke_custom(24000, 1, \"Camera.attachCameraToMobile\", playerId)\r\n    invoke_custom(24000, 1, \"bubble\", playerId, \"quest.amakna.missmoches.01.07\")\r\n    \r\n    --\"**Ou peut-être que je devrais d'abord aller en parlant à Alibert...?\"\r\n    invoke_custom(27500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(28000, 1, \"Camera.attachCameraToMobile\", playerId)\r\n    invoke_custom(28000, 1, \"bubble\", playerId, \"quest.amakna.missmoches.01.08\")\r\n    invoke_custom(30000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(30500, 1, \"skipCinematic\", 22349)\nend\n\n-- Fin de la cinématique - Notification ACH 5134 OBJ 10555\n-- \nfunction event_2537_22350()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_2537_22348","event_2537_22349","event_2537_22350"],"quest_calls":[],"dialogue_calls":[]},"scenario/2538.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\n-- Fonctions cinématique\r\n\r\nfunction modifyRoomLight()\r\n\tglobalLight = Light.addGlobalLight(-0.8, -0.8, -0.6)\r\n\tSound.playSound(70500002, 70)\r\nend\r\n\r\nfunction resetRoomLight()\r\n\ttrace(ringLightOne)\r\n\tLight.removePointLight(ringLightOne)\r\n\tLight.removePointLight(ringLightTwo)\r\n\tLight.removePointLight(ringLightThree)\r\n\tLight.removePointLight(ringLightFour)\r\n\tLight.removeGlobalLight(globalLight)\r\n\tParticle.removeParticleSystem(ringParticleOne)\r\n\tParticle.removeParticleSystem(ringParticleTwo)\r\n\tParticle.removeParticleSystem(ringParticleThree)\r\n\tParticle.removeParticleSystem(ringParticleFour)\r\nend\r\n\r\nfunction ringLightOne()\r\n    ringParticleOne = Particle.addParticleSystem(800188, 7, -98, 0)\r\n    ringLightOne = Light.addPointLight(7, -98, 0, 0.4, 0.4, 0.4, 2)\r\n    Camera.setWorldTarget(7, -98, 0)\r\nend\r\n\r\nfunction ringLightTwo()\r\n    Camera.setWorldTarget(10, -103, 2)\r\n    ringParticleTwo = Particle.addParticleSystem(800188, 6, -102, 0)\r\n    ringLightTwo = Light.addPointLight(6, -102, 0, 0.4, 0.4, 0.4, 2)\r\nend\r\n\r\nfunction ringLightThree()\r\n    ringParticleThree = Particle.addParticleSystem(800188, 15, -102, 0)\r\n    ringLightThree = Light.addPointLight(15, -102, 0, 0.4, 0.4, 0.4, 2)\r\nend\r\n\r\nfunction ringLightFour()\r\n\tringParticleFour = Particle.addParticleSystem(800188, 14, -98, 2)\r\n    ringLightFour = Light.addPointLight(14, -98, 0, 0.6, 0.6, 0.6, 2)\r\nend\r\n\r\nfunction customSkip(mobA, mobB, mobC, mobD)\r\n\tCamera.attachCameraToMobile(playerId)\r\n\tMobile.addMobileCreationCallback(mobA, \"showMonster\", mobA)\r\n\tMobile.addMobileCreationCallback(mobB, \"showMonster\", mobB)\r\n\tMobile.addMobileCreationCallback(mobC, \"showMonster\", mobC)\r\n\tMobile.addMobileCreationCallback(mobD, \"showMonster\", mobD)\r\n\tresetRoomLight()\r\n\tskipCinematic(22457)\r\nend\r\n\r\n-- Fonctions stèles\r\n\r\nbubbleSteleInfoId = 0\r\n\r\nfunction closeSteleInfo()\r\n\tif (bubbleSteleInfoId ~= nil  and bubbleSteleInfoId ~= 0) then BubbleText.close(bubbleSteleInfoId) end\r\nend\r\n\r\nfunction onSteleInfoClosed()\r\n\tif (bubbleSteleInfoId ~= nil  and bubbleSteleInfoId ~= 0) then bubbleSteleInfoId = 0 end\r\nend\r\n\r\nfunction updateSteleInfo(stateInfoId, forceDisplayUI)\r\n\tif (bubbleSteleInfoId == 0) then\r\n\t\tbubbleSteleInfoId = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_WEST\", 0, -60, false, 2147483647, true, \"interactiveBubbleDialog5\", 30000, 25000, \"onSteleInfoClosed\")\r\n\tend\r\n\r\n\tBubbleText.setText(bubbleSteleInfoId, stateInfoId)\r\n\t\r\n\tif (forceDisplayUI) then BubbleText.show(bubbleSteleInfoId) end\r\nend\r\n\r\n-- les fonctions où on cache\r\nfunction hideMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, false)\r\nend\r\n\r\nfunction hidePart(monsterMobileId, partName)\r\n\tMobile.setPartVisible(monsterMobileId, false, partName)\r\nend\r\n\r\n-- les fonctions où on rend visible (à nouveau)\r\nfunction showMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, true)\r\nend\r\n\r\nfunction showPart(monsterMobileId, partName)\r\n\tMobile.setPartVisible(monsterMobileId, true, partName)\r\nend\n\n-- [INIT] Variables & Constantes\n-- \nfunction event_2538_22402()\n    \nend\n\n-- [INIT] Inscription du joueur + Variables Locales\n-- \nfunction event_2538_22368(mobA, mobB, mobC, mobD)\n    Mobile.addMobileCreationCallback(mobA, \"hideMonster\", mobA)\r\n    Mobile.addMobileCreationCallback(mobB, \"hideMonster\", mobB)\r\n    Mobile.addMobileCreationCallback(mobC, \"hideMonster\", mobC)\r\n    Mobile.addMobileCreationCallback(mobD, \"hideMonster\", mobD)\nend\n\n-- [EVENT] Interaction avec Lela - Le joueur n'a pas l'incantation\n-- \nfunction event_2538_22458()\n    local playerId = Context.getLeaderId()\r\n    \r\n    BubbleText.closeBubbleAttachedTo(playerId)\r\n    BubbleText.showText(playerId, \"amakna.missmoches.incantationmissing\", 0, 60)\nend\n\n-- [EVENT] Interaction avec Lela - Apparition des Miss Moches\n-- \nfunction event_2538_22457(mobA, mobB, mobC, mobD)\n    local playerId = Context.getLeaderId()\r\n    local lelaId = createActor(1111105445, 11, -92, 0, 4, 3, 7)\r\n    \r\n    function skip()\r\n        Camera.attachCameraToMobile(playerId)\r\n        Mobile.addMobileCreationCallback(mobA, \"showMonster\", mobA)\r\n        Mobile.addMobileCreationCallback(mobB, \"showMonster\", mobB)\r\n        Mobile.addMobileCreationCallback(mobC, \"showMonster\", mobC)\r\n        Mobile.addMobileCreationCallback(mobD, \"showMonster\", mobD)\r\n        resetRoomLight()\r\n        skipCinematic(22457)\r\n    end\r\n        \r\n    startCinematicContext(1.3, playerId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skip\")\r\n    \r\n    -- \"Tu l'auras voulu, tu vas goûter à la fureur des Miss Moches !!!\"\r\n    invoke_custom(00500, 1, \"bubble\", lelaId, \"quest.amakna.missmoches.05.01\")\r\n    invoke_custom(00500, 1, \"Mobile.setMobileAnimation\", lelaId, \"AnimComp-Combat01\")\r\n    invoke_custom(04500, 1, \"clearBubbles\", lelaId)\r\n    \r\n    -- \"Ydalipe, lumières !!!\"\r\n    invoke_custom(04500, 1, \"bubble\", lelaId, \"quest.amakna.missmoches.05.02\")\r\n    invoke_custom(04500, 1, \"Mobile.setMobileAnimation\", lelaId, \"AnimComp-Combat03\")\r\n    invoke_custom(07000, 1, \"clearBubbles\", lelaId)\r\n    \r\n    invoke_custom(07500, 1, \"Mobile.addMobileCreationCallback\", lelaId, \"hideMonster\", lelaId)\r\n    invoke_custom(07500, 1, \"Mobile.addMobileCreationCallback\", mobA, \"showMonster\", mobA)\r\n    invoke_custom(07500, 1, \"Mobile.addMobileCreationCallback\", mobB, \"showMonster\", mobB)\r\n    invoke_custom(07500, 1, \"Mobile.addMobileCreationCallback\", mobC, \"showMonster\", mobC)\r\n    invoke_custom(07500, 1, \"Mobile.addMobileCreationCallback\", mobD, \"showMonster\", mobD)\r\n    \r\n    invoke_custom(06000, 1, \"modifyRoomLight\")\r\n    \r\n    invoke_custom(07500, 1, \"ringLightOne\")\r\n    invoke_custom(08500, 1, \"ringLightTwo\")\r\n    invoke_custom(09500, 1, \"ringLightThree\")\r\n    invoke_custom(10500, 1, \"ringLightFour\")\r\n    \r\n    invoke_custom(12000, 1, \"Camera.attachCameraToMobile\", playerId)\r\n    invoke_custom(12500, 1, \"resetRoomLight\")\r\n    invoke_custom(12600, 1, \"skipCinematic\", 22457)\nend\n\n-- *[EVENT] La cinématique d'apparition est terminée - Lancement du combat\n-- \nfunction event_2538_22461()\n    \nend\n\n-- CLIENT_TRIGGERED_EVENT - On skip chez tout le monde\n-- \nfunction event_2538_22484(mobA, mobB, mobC, mobD)\n    customSkip(mobA, mobB, mobC, mobD)\nend\n\n-- USER_GROUP_KILLED - Salle 01 - BOSS\n-- \nfunction event_2538_22372()\n    \nend\n\n-- FIGHT_ENDED_IN_CLIENT_EVENT - Salle 01 - BOSS\n-- \nfunction event_2538_22459()\n    local playerId = Context.getLeaderId()\r\n    local mobA = createActor(1111105445, 10, -99, 0, 4)\r\n    local mobB = createActor(1111105446, 7, -96, 0, 4)\r\n    local mobC = createActor(1111105447, 10, -93, 0, 4)\r\n    local mobD = createActor(1111105448, 13, -96, 0, 4)\r\n    \r\n    Mobile.setMobileDirection(mobA, 3)\r\n    Mobile.setMobileDirection(mobB, 1)\r\n    Mobile.setMobileDirection(mobC, 7)\r\n    Mobile.setMobileDirection(mobD, 5)\r\n    \r\n    startCinematicContext(1.3, playerId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 22459)\r\n    \r\n    invoke_custom(00500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Pointer\")\r\n    \r\n    -- \"Je vous ai eu, faites vos prières !\"\r\n    invoke_custom(01000, 1, \"bubble\", playerId, \"quest.amakna.missmoches.04.01\")\r\n    invoke_custom(04000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Pitié, laisse-nous la vie sauve ! On ne voulait faire de mal à personne, on cherchait juste à briser la malédiction du dieu Osamodas !\"\r\n    invoke_custom(04000, 1, \"bubble\", mobA, \"quest.amakna.missmoches.04.02\")\r\n    invoke_custom(04000, 1, \"Mobile.setMobileDirection\", playerId, 7)\r\n    invoke_custom(04000, 1, \"Camera.setCamera\", 1.3, 10, -99, 0)\r\n    invoke_custom(08500, 1, \"clearBubbles\", mobA)\r\n    \r\n    -- \"Elle dit la vérité, tout ça n'est pas de notre faute !!!\"\r\n    invoke_custom(08500, 1, \"bubble\", mobC, \"quest.amakna.missmoches.04.03\")\r\n    invoke_custom(08500, 1, \"Mobile.setMobileDirection\", playerId, 3)\r\n    invoke_custom(08500, 1, \"Camera.setCamera\", 1.3, 10, -93, 0)\r\n    invoke_custom(13000, 1, \"clearBubbles\", mobC)\r\n    \r\n    -- \"J'aimerais bien que vous m'expliquiez le rapport entre votre fichue malédiction et le fait que vous enleviez de pauvres aventuriers pleins d'espoirs pour les transformer en Crapaud Muffle\"\r\n    invoke_custom(13000, 1, \"bubble\", playerId, \"quest.amakna.missmoches.04.04\")\r\n    invoke_custom(13000, 1, \"Camera.setCamera\", 1.3, 10, -96, 0)\r\n    invoke_custom(18000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Parlez si vous voulez la vie sauve !!!\"\r\n    invoke_custom(18250, 1, \"bubble\", playerId, \"quest.amakna.missmoches.04.05\")\r\n    invoke_custom(18250, 1, \"Camera.setCamera\", 1.3, 10, -96, 0)\r\n    invoke_custom(20000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Calmez-vous, jeune aventurier ! Ydalipe va vous raconter l'histoire de notre malédiction\"\r\n    invoke_custom(20000, 1, \"bubble\", mobB, \"quest.amakna.missmoches.04.06\")\r\n    invoke_custom(20000, 1, \"Mobile.setMobileDirection\", playerId, 5)\r\n    invoke_custom(20000, 1, \"Camera.setCamera\", 1.3, 7, -96, 0)\r\n    invoke_custom(24500, 1, \"clearBubbles\", mobB)\r\n    \r\n    -- \"Encore ? C'est tout le temps moi qui raconte cette histoire !\"\r\n    invoke_custom(24500, 1, \"bubble\", mobD, \"quest.amakna.missmoches.04.07\")\r\n    invoke_custom(24500, 1, \"Mobile.setMobileDirection\", playerId, 1)\r\n    invoke_custom(24500, 1, \"Camera.setCamera\", 1.3, 13, -96, 0)\r\n    invoke_custom(28000, 1, \"clearBubbles\", mobD)\r\n    \r\n    -- \"Fais ce qu'on te demande Ydalipe, notre vie en dépend\"\r\n    invoke_custom(28000, 1, \"bubble\", mobA, \"quest.amakna.missmoches.04.08\")\r\n    invoke_custom(28000, 1, \"Mobile.setMobileDirection\", playerId, 7)\r\n    invoke_custom(28000, 1, \"Camera.setCamera\", 1.3, 10, -99, 0)\r\n    invoke_custom(31500, 1, \"clearBubbles\", mobA)\r\n    \r\n    -- \"Sans moi cette fois-ci, racontez-la vous-même\"\r\n    invoke_custom(31500, 1, \"bubble\", mobD, \"quest.amakna.missmoches.04.09\")\r\n    invoke_custom(31500, 1, \"Mobile.setMobileDirection\", playerId, 1)\r\n    invoke_custom(31500, 1, \"Camera.setCamera\", 1.3, 13, -96, 0)\r\n    invoke_custom(34500, 1, \"clearBubbles\", mobD)\r\n    \r\n    -- \"Ne vous disputez pas pour si peu, je vais m'en charger\"\r\n    invoke_custom(34500, 1, \"bubble\", mobB, \"quest.amakna.missmoches.04.10\")\r\n    invoke_custom(34500, 1, \"Mobile.setMobileDirection\", playerId, 5)\r\n    invoke_custom(34500, 1, \"Camera.setCamera\", 1.3, 7, -96, 0)\r\n    invoke_custom(37500, 1, \"clearBubbles\", mobB)\r\n    \r\n    -- \"Cette histoire remonte à plusieurs mois, alors que le dieu Osamodas nous rendait visite pour nous courtiser. En fait...\"\r\n    invoke_custom(37500, 1, \"bubble\", mobB, \"quest.amakna.missmoches.04.11\")\r\n    invoke_custom(43000, 1, \"clearBubbles\", mobB)\r\n    \r\n    -- \"Je connais déjà cette partie de l'histoire, contente-toi de me dire le rapport entre tout ça et le fait que vous enleviez des gens !\"\r\n    invoke_custom(43000, 1, \"bubble\", playerId, \"quest.amakna.missmoches.04.12\")\r\n    invoke_custom(43000, 1, \"Camera.setCamera\", 1.3, 10, -96, 0)\r\n    invoke_custom(44500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Pointer\")\r\n    invoke_custom(50000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Dépêche-toi de lui dire !\"\r\n    invoke_custom(50000, 1, \"bubble\", mobC, \"quest.amakna.missmoches.04.13\")\r\n    invoke_custom(50000, 1, \"Mobile.setMobileDirection\", playerId, 3)\r\n    invoke_custom(50000, 1, \"Camera.setCamera\", 1.3, 10, -93, 0)\r\n    invoke_custom(52500, 1, \"clearBubbles\", mobC)\r\n    \r\n    -- \"Arrêtez de me crier dessus !!!\"\r\n    invoke_custom(52500, 1, \"bubble\", mobB, \"quest.amakna.missmoches.04.14\")\r\n    invoke_custom(52500, 1, \"Mobile.setMobileDirection\", playerId, 5)\r\n    invoke_custom(52500, 1, \"Camera.setCamera\", 1.3, 7, -96, 0)\r\n    invoke_custom(55500, 1, \"clearBubbles\", mobB)\r\n    \r\n    -- \"La dernière chose que le dieu Osamodas nous ait dite avant de nous laisser à notre sort est que le remède à notre malédiction résiderait dans le baiser sincère d'un valeureux chevalier\"\r\n    invoke_custom(55500, 1, \"bubble\", mobB, \"quest.amakna.missmoches.04.15\")\r\n    invoke_custom(62000, 1, \"clearBubbles\", mobB)\r\n    \r\n    -- \"On a bien essayé d'attendre qu'un chevalier vienne de lui-même pour nous délivrer, mais ils partent tous en courant quand ils nous voient !\"\r\n    invoke_custom(62000, 1, \"bubble\", mobA, \"quest.amakna.missmoches.04.16\")\r\n    invoke_custom(62000, 1, \"Mobile.setMobileDirection\", playerId, 7)\r\n    invoke_custom(62000, 1, \"Camera.setCamera\", 1.3, 10, -99, 0)\r\n    invoke_custom(67000, 1, \"clearBubbles\", mobA)\r\n    \r\n    -- \"Loin de moi l'idée de vous dire que ce que vous avancez est compréhensible, mais je ne vois toujours pas le rapport avec les Crapauds Mufles\"\r\n    invoke_custom(67000, 1, \"bubble\", playerId, \"quest.amakna.missmoches.04.17\")\r\n    invoke_custom(67000, 1, \"Camera.setCamera\", 1.3, 10, -96, 0)\r\n    invoke_custom(67000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(71500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Il ne comprend pas le rapport, soyez plus claires !!!\"\r\n    invoke_custom(71500, 1, \"bubble\", mobC, \"quest.amakna.missmoches.04.18\")\r\n    invoke_custom(71500, 1, \"Mobile.setMobileDirection\", playerId, 3)\r\n    invoke_custom(71500, 1, \"Camera.setCamera\", 1.3, 10, -93, 0)\r\n    invoke_custom(74500, 1, \"clearBubbles\", mobC)\r\n    \r\n    -- \"Calme-toi, Erpel, je vais lui expliquer\"\r\n    invoke_custom(74500, 1, \"bubble\", mobA, \"quest.amakna.missmoches.04.19\")\r\n    invoke_custom(74500, 1, \"Mobile.setMobileDirection\", playerId, 7)\r\n    invoke_custom(74500, 1, \"Camera.setCamera\", 1.3, 10, -99, 0)\r\n    invoke_custom(77000, 1, \"clearBubbles\", mobA)\r\n    \r\n    -- \"Un jour, on a eu l'idée d'accueillir un valeureux chevalier en ne lui montrant pas notre visage\"\r\n    invoke_custom(77000, 1, \"bubble\", mobA, \"quest.amakna.missmoches.04.20\")\r\n    invoke_custom(81000, 1, \"clearBubbles\", mobA)\r\n    invoke_custom(78250, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    \r\n    -- \"Et là, à l'instant où il ne me regardait pas, je lui ai sauté dessus pour lui dérober un baiser\"\r\n    invoke_custom(81000, 1, \"bubble\", mobA, \"quest.amakna.missmoches.04.21\")\r\n    invoke_custom(85000, 1, \"clearBubbles\", mobA)\r\n    \r\n    --Silence\r\n    \r\n    -- \"Ceci dit, je pense que tu vois de qui je parle, tu as dû le croiser au rez-de-chaussée, c'est le Crapaud Mufle le plus à droite\"\r\n    invoke_custom(87000, 1, \"bubble\", mobA, \"quest.amakna.missmoches.04.22\")\r\n    invoke_custom(92500, 1, \"clearBubbles\", mobA)\r\n    \r\n    -- \"Tu es en train de me dire que c'est le fait de vous embrasser qui transforme les chevaliers en Crapauds Mufles...?\"\r\n    invoke_custom(92500, 1, \"bubble\", playerId, \"quest.amakna.missmoches.04.23\")\r\n    invoke_custom(94000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Non\")\r\n    invoke_custom(97500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Eh bien oui, ça me paraissait aussi bizarre...\"\r\n    invoke_custom(97500, 1, \"bubble\", mobC, \"quest.amakna.missmoches.04.24\")\r\n    invoke_custom(97500, 1, \"Mobile.setMobileDirection\", playerId, 3)\r\n    invoke_custom(97500, 1, \"Camera.setCamera\", 1.3, 10, -93, 0)\r\n    invoke_custom(100500, 1, \"clearBubbles\", mobC)\r\n    \r\n    -- \"C'est pour ça qu'on en a attiré une soixantaine d'autres pour essayer, et ils ont tous terminés en Crapaud Muffle !\"\r\n    invoke_custom(100500, 1, \"bubble\", mobD, \"quest.amakna.missmoches.04.25\")\r\n    invoke_custom(100500, 1, \"Mobile.setMobileDirection\", playerId, 1)\r\n    invoke_custom(100500, 1, \"Camera.setCamera\", 1.3, 13, -96, 0)\r\n    invoke_custom(105000, 1, \"clearBubbles\", mobD)\r\n    \r\n    -- \"Ton jeu ne prend pas, vous avez juste fait tout ça pour essayer de guérir votre malédiction à tout prix\"\r\n    invoke_custom(105000, 1, \"bubble\", playerId, \"quest.amakna.missmoches.04.26\")\r\n    invoke_custom(105000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Colere\")\r\n    invoke_custom(109000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Cela dit, je veux bien passer l'éponge si vous me jurez de ne jamais recommencer et d'attendre que je vous trouve le chevalier capable de briser votre malédiction\"\r\n    invoke_custom(109000, 1, \"bubble\", playerId, \"quest.amakna.missmoches.04.27\")\r\n    invoke_custom(110000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(115000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Mais, on a déjà tout essayé, tu ne vas jamais le trouver !\"\r\n    invoke_custom(115000, 1, \"bubble\", mobD, \"quest.amakna.missmoches.04.28\")\r\n    invoke_custom(115000, 1, \"Mobile.setMobileDirection\", playerId, 1)\r\n    invoke_custom(115000, 1, \"Camera.setCamera\", 1.3, 13, -96, 0)\r\n    invoke_custom(118000, 1, \"clearBubbles\", mobD)\r\n    \r\n    -- \"Vous n'avez pas compris la situation, je ne vous laisse pas le choix !\"\r\n    invoke_custom(118000, 1, \"bubble\", playerId, \"quest.amakna.missmoches.04.29\")\r\n    invoke_custom(118000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Rire\")\r\n    invoke_custom(122000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Si vous ne voulez pas avoir de nouveau affaire à moi, vous avez intérêt à ne plus jamais capturer le moindre aventurier !\"\r\n    invoke_custom(122000, 1, \"bubble\", playerId, \"quest.amakna.missmoches.04.30\")\r\n    invoke_custom(127000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"...\"\r\n    invoke_custom(127500, 1, \"bubble\", mobA, \"quest.amakna.missmoches.04.31\")\r\n    invoke_custom(127500, 1, \"Camera.setCamera\", 1.3, 10, -99, 0)\r\n    invoke_custom(128500, 1, \"bubble\", mobB, \"quest.amakna.missmoches.04.31\")\r\n    invoke_custom(128500, 1, \"Camera.setCamera\", 1.3, 7, -96, 0)\r\n    invoke_custom(129500, 1, \"bubble\", mobC, \"quest.amakna.missmoches.04.31\")\r\n    invoke_custom(129500, 1, \"Camera.setCamera\", 1.3, 10, -93, 0)\r\n    invoke_custom(130500, 1, \"bubble\", mobD, \"quest.amakna.missmoches.04.31\")\r\n    invoke_custom(130500, 1, \"Camera.setCamera\", 1.3, 13, -96, 0)\r\n    \r\n    -- \"Je vais aller donner le mot à l'auberge de la forêt pour qu'on puisse trouver la perle rare. En attendant, restez ici et ne causez plus de problèmes\"\r\n    invoke_custom(131500, 1, \"bubble\", playerId, \"quest.amakna.missmoches.04.32\")\r\n    invoke_custom(132500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-CroiserBras\")\r\n    invoke_custom(132500, 1, \"Camera.setCamera\", 1.3, 13, -96, 0)\r\n    invoke_custom(136500, 1, \"clearBubbles\", playerId)\r\n    \t\r\n    invoke_custom(137000, 1, \"skipCinematic\", 22459)\nend\n\n-- [FIGHT] Défaite du combat - Reset les stèles\n-- \nfunction event_2538_22397()\n    \nend\n\n-- [STELE] Le joueur examine une stèle\n-- \nfunction event_2538_22398(steleCount, steleStateId)\n    local steleCount = toLong(steleCount)\r\n    local steleStateId = toLong(steleStateId)\r\n    local stateInfoId = \"stele.state.description.\" .. toString(steleStateId)\r\n    \r\n    if (steleCount == 0) then\r\n    \tUI.openRewardsDialog(\"stele.description.tour\")\r\n    \tUI.addReward(30924, \"stele.reward.stasis.21\")\r\n    elseif (steleCount == 1) then\r\n    \tUI.openRewardsDialog(\"stele.description.tour\")\r\n    \tUI.addReward(30913, \"stele.reward.stasis.21\")\r\n    elseif (steleCount == 2) then\r\n    \tUI.openRewardsDialog(\"stele.description.tour\")\r\n    \tUI.addReward(30923, \"stele.reward.stasis.21\")\r\n    elseif (steleCount == 3) then\r\n    \tUI.openRewardsDialog(\"stele.description.tour\")\r\n    \tUI.addReward(30922, \"stele.reward.stasis.21\")\r\n    end\r\n    UI.addReward(27083, \"stele.reward.stasis.21\")\r\n    \r\n    updateSteleInfo(stateInfoId, true)\nend\n\n-- [STELE] Le joueur active une stèle\n-- \nfunction event_2538_22399(steleCount, steleStateId)\n    local steleCount = toLong(steleCount)\r\n    local steleStateId = toLong(steleStateId)\r\n    local stateInfoId = \"stele.state.description.\" .. toString(steleStateId)\r\n    \r\n    if (steleCount == 1) then\r\n    \tUI.openRewardsDialog(\"stele.description.tour\")\r\n    \tUI.addReward(30924, \"stele.reward.stasis.21\")\r\n    elseif (steleCount == 2) then\r\n    \tUI.openRewardsDialog(\"stele.description.tour\")\r\n    \tUI.addReward(30913, \"stele.reward.stasis.21\")\r\n    elseif (steleCount == 3) then\r\n    \tUI.openRewardsDialog(\"stele.description.tour\")\r\n    \tUI.addReward(30923, \"stele.reward.stasis.21\")\r\n    elseif (steleCount == 4) then\r\n    \tUI.openRewardsDialog(\"stele.description.tour\")\r\n    \tUI.addReward(30922, \"stele.reward.stasis.21\")\r\n    end\r\n    UI.addReward(27083, \"stele.reward.stasis.21\")\r\n    \r\n    updateSteleInfo(stateInfoId, true)\nend\n\n-- [STELE] Refresh des APS pour Stèles\n-- \nfunction event_2538_22400()\n    \nend\n\n-- [STASIS] DUNGEON_DIFFICULTY_CHANGED - Reset les stèles\n-- \nfunction event_2538_22401()\n    \nend\n\n-- MONSTER_ACTION_EVENT - Lancement du combat\n-- on skippe la cinématique pour tout le monde \nfunction event_2538_22485()\n    skipCinematic()\nend\n\n-- FIGHT_ENDED - Rend les monstres inattaquables\n-- \nfunction event_2538_22486()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","modifyRoomLight","resetRoomLight","ringLightOne","ringLightTwo","ringLightThree","ringLightFour","customSkip","closeSteleInfo","onSteleInfoClosed","updateSteleInfo","hideMonster","hidePart","showMonster","showPart","event_2538_22402","event_2538_22368","event_2538_22458","event_2538_22457","skip","event_2538_22461","event_2538_22484","event_2538_22372","event_2538_22459","event_2538_22397","event_2538_22398","event_2538_22399","event_2538_22400","event_2538_22401","event_2538_22485","event_2538_22486"],"quest_calls":["UI.openRewardsDialog(\"stele.description.tour\")\r","UI.openRewardsDialog(\"stele.description.tour\")\r","UI.openRewardsDialog(\"stele.description.tour\")\r","UI.openRewardsDialog(\"stele.description.tour\")\r","UI.openRewardsDialog(\"stele.description.tour\")\r","UI.openRewardsDialog(\"stele.description.tour\")\r","UI.openRewardsDialog(\"stele.description.tour\")\r","UI.openRewardsDialog(\"stele.description.tour\")\r"],"dialogue_calls":[]},"scenario/2539.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\n\n-- [EVENT] Initialisation\n-- \nfunction event_2539_22362()\n    \nend\n\n-- [EVENT] Le joueur se fait attaquer par le Gobgob - Cinématique\n-- \nfunction event_2539_22363()\n    local playerId = Context.getLeaderId()\r\n    local monsterId = createActor(100501620, 90, -105, 30, 4)\r\n    \r\n    Mobile.setMobileVisible(monsterId, false)\r\n    \r\n    startCinematicContext(1.2, playerId)\r\n    \r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 22363)\r\n    Mobile.setMobileDirection(playerId, 7)\r\n    Mobile.setMobileDirection(monsterId, 7)\r\n    \r\n    Camera.setCamera(1.3, 90, -110, 30)\r\n    \r\n    -- \"PRINCESSE, VOUS M'ENTENDEZ ? J'ARRIVE VOUS SAUVER !!!\"\r\n    invoke_custom(00500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Help\")\r\n    invoke_custom(01000, 1, \"bubble\", playerId, \"quest.amakna.missmoches.02.01\")\r\n    invoke_custom(03500, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(04000, 1, \"Particle.addParticleSystemToTarget\", 800174, monsterId)\r\n    invoke_custom(04000, 1, \"Mobile.setMobileVisible\", monsterId, true)\r\n    invoke_custom(04000, 1, \"Camera.attachCameraToMobile\", monsterId)\r\n    \r\n    invoke_custom(05500, 1, \"Mobile.moveMobile\", playerId, 90, -106, 30)\r\n    \r\n    -- \"**Mais, que fait un Gobgob ici ?\"\r\n    invoke_custom(06500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(06500, 1, \"bubble\", playerId, \"quest.amakna.missmoches.02.02\")\r\n    invoke_custom(10000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(07500, 1, \"Mobile.moveMobile\", monsterId, 91, -106, 30)\r\n    invoke_custom(09000, 1, \"Mobile.setMobileDirection\", monsterId, 5)\r\n    \r\n    invoke_custom(09000, 1, \"Mobile.setMobileDirection\", playerId, 1)\r\n    \r\n    invoke_custom(10000, 1, \"Mobile.moveMobile\", monsterId, 90, -107, 30)\r\n    invoke_custom(11500, 1, \"Mobile.setMobileDirection\", monsterId, 3)\r\n    \r\n    invoke_custom(11500, 1, \"Mobile.setMobileDirection\", playerId, 7)\r\n    \r\n    -- \"**Il n'a pas vraiment l'air très sympathique...\"\r\n    invoke_custom(12000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Non\")\r\n    invoke_custom(12000, 1, \"bubble\", playerId, \"quest.amakna.missmoches.02.03\")\r\n    invoke_custom(13500, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(12500, 1, \"Mobile.moveMobile\", monsterId, 89, -106, 30)\r\n    invoke_custom(14000, 1, \"Mobile.setMobileDirection\", monsterId, 1)\r\n    \r\n    invoke_custom(14000, 1, \"Mobile.setMobileDirection\", playerId, 5)\r\n    invoke_custom(15000, 1, \"Mobile.setMobileAnimation\", monsterId, \"AnimSort-Motivation\")\r\n    \r\n    invoke_custom(16000, 1, \"skipCinematic\", 22363)\nend\n\n-- [ACTION] Lancement du combat associé\n-- \nfunction event_2539_22364(groupId, mobA, fightId, playerId)\n    playerId = toLong(playerId)\r\n    groupId =toLong(groupId)\r\n    fightId = toLong(fightId)\r\n    mobA = toLong(mobA)\r\n    \r\n    trace(\"===Valeur de Player Id ======\", playerId)\r\n    trace(\"===Valeur de Group Id ======\", groupId)\r\n    trace(\"===Valeur de Fight Id ======\", fightId)\r\n    trace(\"===Valeur de MobA Id ======\", mobA)\nend\n\n-- FIGHT_ENDED_IN_CLIENT - Notification ACH 5134 OBJ 10556\n-- \nfunction event_2539_22365()\n    \nend\n\n-- [ACTION] Fin de combat perdant\n-- \nfunction event_2539_22366()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_2539_22362","event_2539_22363","event_2539_22364","event_2539_22365","event_2539_22366"],"quest_calls":[],"dialogue_calls":[]},"scenario/2540.lua":{"source":"\n\n-- Variables globales\n-- \nfunction event_2540_22384()\n    \nend\n\n-- [EVENT] Le joueur entre dans l'instance - Inscription au scénario\n-- \nfunction event_2540_22385(doorOpened, bossId)\n    if (doorOpened == 1) then\r\n    else hideMonster(bossId)\r\n    end\nend\n\n-- Le joueur attaque Cire Momore - Lancement du Combat\n-- \nfunction event_2540_22386()\n    \nend\n\n-- INTERACTIVE_ELEMENT_ACTIVATION - Ouverture de la porte\n-- \nfunction event_2540_22387(bossId)\n    local playerId = Context.getLeaderId()\r\n    local bossId = toLong(bossId)\r\n    \r\n    startCinematicContext(1.0, bossId)\r\n    \r\n    invoke_custom(1999, 1, \"Mobile.addMobileCreationCallback\", bossId, \"showMonster\", bossId)\r\n    invoke_custom(1950, 1, \"Mobile.setMobileAnimation\", bossId, \"AnimApparition\")\r\n    invoke_custom(1950, 1, \"Sound.playSound\", 300183905357901, true, 50)\r\n    \r\n    invoke_custom(2000, 1, \"Effect.createCameraShakeEffect\", 100, 500, 100, 5, 100, \"BOTH\")\r\n    invoke_custom(6400, 1, \"Camera.attachCameraToMobile\", playerId)\r\n    \r\n    invoke_custom(6400, 1, \"skipCinematic\")\nend\n\n","functions":["event_2540_22384","event_2540_22385","event_2540_22386","event_2540_22387"],"quest_calls":[],"dialogue_calls":[]},"scenario/2541.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\n\n-- [INIT] Variables\n-- \nfunction event_2541_22408()\n    \nend\n\n-- [EVENT] Le joueur se fait accueillir par Lela - Cinématique Salle 01\n-- \nfunction event_2541_22389()\n    local playerId = Context.getLeaderId()\r\n    local monsterId = createActor(1111105445, 89, 7, 0, 4)\r\n        \r\n    Mobile.setMobileDirection(playerId, 7)\r\n    Mobile.setMobileDirection(monsterId, 3)\r\n    \r\n    startCinematicContext(1.3, playerId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 22389)\r\n    \r\n    -- \"Bienvenue à toi, jeune aventurier !\"\r\n    invoke_custom(00500, 1, \"bubble\", monsterId, \"quest.amakna.missmoches.03.01\")\r\n    invoke_custom(00500, 1, \"Camera.setCamera\", 1.3, 89, 7, 0)\r\n    invoke_custom(03500, 1, \"clearBubbles\", monsterId)\r\n        \r\n    -- \"Je suis la princesse Lela et tu te trouves dans ma tour. J'y vis avec les princesses Eenca, Erpel et Ydalipe\"\r\n    invoke_custom(03500, 1, \"bubble\", monsterId, \"quest.amakna.missmoches.03.02\")\r\n    invoke_custom(07500, 1, \"clearBubbles\", monsterId)\r\n        \r\n    -- \"Tu tombes à pic, ce midi nous avons prévu de bonnes esc...\"\r\n    invoke_custom(07500, 1, \"bubble\", monsterId, \"quest.amakna.missmoches.03.03\")\r\n    invoke_custom(11000, 1, \"clearBubbles\", monsterId)\r\n        \r\n    -- \"Euh, attendez, il n'y avait pas une princesse qui disait s'appeler \"Ydalipe\" et qui criait à l'aide depuis la fenêtre de cette tour ?\"\r\n    invoke_custom(11000, 1, \"bubble\", playerId, \"quest.amakna.missmoches.03.04\")\r\n    invoke_custom(11000, 1, \"Camera.setCamera\", 1.3, 89, 14, 0)\r\n    invoke_custom(15000, 1, \"clearBubbles\", playerId)\r\n        \r\n    -- \"...\"\r\n    invoke_custom(15000, 1, \"bubble\", monsterId, \"quest.amakna.missmoches.03.05\")\r\n    invoke_custom(15000, 1, \"Camera.setCamera\", 1.3, 89, 7, 0)\r\n    invoke_custom(17500, 1, \"clearBubbles\", monsterId)\r\n        \r\n    -- \"...\"\r\n    invoke_custom(15500, 1, \"bubble\", playerId, \"quest.amakna.missmoches.03.05\")\r\n    invoke_custom(15500, 1, \"Camera.setCamera\", 1.3, 89, 14, 0)\r\n    invoke_custom(17500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"**Elle aurait pu au moins changer son nom...\"\r\n    invoke_custom(17500, 1, \"bubble\", monsterId, \"quest.amakna.missmoches.03.06\")\r\n    invoke_custom(17500, 1, \"Camera.setCamera\", 1.3, 89, 7, 0)\r\n    invoke_custom(21000, 1, \"clearBubbles\", monsterId)\r\n    \r\n    -- \"Hum, absolument pas jeune aventurier ! Tu dois faire erreur, nous sommes des princesses tout à fait normales, nous aimons particulièrement devenir amies avec des explorateurs aussi vaillants !\"\r\n    invoke_custom(21000, 1, \"bubble\", monsterId, \"quest.amakna.missmoches.03.07\")\r\n    invoke_custom(26000, 1, \"clearBubbles\", monsterId)\r\n        \r\n    -- \"Sur ce, je t'invite à me suivre, les festivités ne sauraient commencer sans toi !\"\r\n    invoke_custom(26000, 1, \"bubble\", monsterId, \"quest.amakna.missmoches.03.08\")\r\n    invoke_custom(29000, 1, \"Mobile.moveMobile\", monsterId, 83, 5, 16)\r\n    invoke_custom(30500, 1, \"clearBubbles\", monsterId)\r\n        \r\n    -- \"**Mais qu'est-ce que c'est que cet endroit...\"\r\n    invoke_custom(31000, 1, \"bubble\", playerId, \"quest.amakna.missmoches.03.09\")\r\n    invoke_custom(34000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(31000, 1, \"Camera.setCamera\", 1.3, 89, 14, 0)\r\n    invoke_custom(34000, 1, \"clearBubbles\", playerId)\r\n        \r\n    invoke_custom(33500, 1, \"skipCinematic\", 22389)\nend\n\n-- [EVENT] Fin de la cinématique de la salle 01 - On assure la téléportation du joueur\n-- \nfunction event_2541_22456()\n    \nend\n\n-- [EVENT] Le joueur se fait accueillir par Lela - Cinématique Salle 02\n-- \nfunction event_2541_22406()\n    local playerId = Context.getLeaderId()\r\n    local monsterId = createActor(1111105445, 24, 6, 4, 4)\r\n        \r\n    Mobile.setMobileDirection(monsterId, 5)\r\n    startCinematicContext(1.3, playerId)\r\n        \r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 22406)\r\n        \r\n    -- \"Voici la salle polyvalente de la tour. C'est ici que nous nous détendons entre deux...\"\r\n    invoke_custom(00500, 1, \"bubble\", monsterId, \"quest.amakna.missmoches.03.10\")\r\n    invoke_custom(00500, 1, \"Camera.setCamera\", 1.3, 24, 6, 4)\r\n    invoke_custom(04000, 1, \"clearBubbles\", monsterId)\r\n        \r\n    -- \"...\"\r\n    invoke_custom(04000, 1, \"bubble\", monsterId, \"quest.amakna.missmoches.03.11\")\r\n    invoke_custom(05500, 1, \"clearBubbles\", monsterId)\r\n        \r\n    -- \"...parties de cartes...\"\r\n    invoke_custom(05500, 1, \"bubble\", monsterId, \"quest.amakna.missmoches.03.12\")\r\n    invoke_custom(09000, 1, \"clearBubbles\", monsterId)\r\n    invoke_custom(09000, 1, \"Camera.attachCameraToMobile\", playerId)\r\n    invoke_custom(09000, 1, \"Mobile.moveMobile\", playerId, 20, 5, 4)\r\n    invoke_custom(12500, 1, \"Mobile.setMobileDirection\", playerId, 7)\r\n    invoke_custom(13500, 1, \"Mobile.moveMobile\", playerId, 22, 5, 4)\r\n    invoke_custom(14500, 1, \"Mobile.setMobileDirection\", playerId, 7)\r\n    invoke_custom(15500, 1, \"Mobile.moveMobile\", playerId, 22, 6, 4)\r\n    invoke_custom(16000, 1, \"Mobile.setMobileDirection\", playerId, 1)\r\n        \r\n    -- \"Ah, c'est une pièce très...\"\r\n    invoke_custom(16000, 1, \"bubble\", playerId, \"quest.amakna.missmoches.03.13\")\r\n    invoke_custom(17000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(19500, 1, \"clearBubbles\", playerId)\r\n        \r\n    -- \"...\"\r\n    invoke_custom(21500, 1, \"bubble\", playerId, \"quest.amakna.missmoches.03.11\")\r\n    invoke_custom(21500, 1, \"Camera.setCamera\", 1.3, 22, 6, 4)\r\n    invoke_custom(23000, 1, \"clearBubbles\", playerId)\r\n    invoke_custom(22000, 1, \"bubble\", monsterId, \"quest.amakna.missmoches.03.11\")\r\n    invoke_custom(22000, 1, \"Camera.setCamera\", 1.3, 24, 6, 4)\r\n    invoke_custom(23000, 1, \"clearBubbles\", monsterId)\r\n        \r\n    -- \"**Sauvez-moi\"\r\n    invoke_custom(23000, 1, \"bubble\", playerId, \"quest.amakna.missmoches.03.14\")\r\n    invoke_custom(23000, 1, \"Camera.setCamera\", 1.3, 22, 6, 4)\r\n    invoke_custom(26000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Elle est très coquette ! C'est curieux qu'il y ait autant de Crapauds Mufles, vous faites un élevage ?\"\r\n    invoke_custom(26000, 1, \"bubble\", playerId, \"quest.amakna.missmoches.03.15\")\r\n    invoke_custom(30000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Je vois que tu as l'œil ! Une des résidentes ne peut pas vivre sans Crapaud Mufle autour d'elle, donc nous les avons tous adoptés\"\r\n    invoke_custom(30000, 1, \"bubble\", monsterId, \"quest.amakna.missmoches.03.16\")\r\n    invoke_custom(30000, 1, \"Camera.setCamera\", 1.3, 24, 6, 4)\r\n    invoke_custom(34000, 1, \"clearBubbles\", monsterId)\r\n    \r\n    -- \"Hm, d'accord, et concernant les chaînes au mur, c'est aussi une collection ?\"\r\n    invoke_custom(34500, 1, \"bubble\", playerId, \"quest.amakna.missmoches.03.17\")\r\n    invoke_custom(34500, 1, \"Camera.setCamera\", 1.3, 22, 6, 4)\r\n    invoke_custom(34000, 1, \"Mobile.setMobileDirection\", playerId, 7)\r\n    invoke_custom(34000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Pointer\")\r\n    invoke_custom(38000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"...\"\r\n    invoke_custom(38000, 1, \"bubble\", playerId, \"quest.amakna.missmoches.03.11\")\r\n    invoke_custom(38000, 1, \"Camera.setCamera\", 1.3, 22, 6, 4)\r\n    invoke_custom(38000, 1, \"Mobile.setMobileDirection\", playerId, 1)\r\n    invoke_custom(41000, 1, \"clearBubbles\", playerId)\r\n    invoke_custom(38500, 1, \"bubble\", monsterId, \"quest.amakna.missmoches.03.11\")\r\n    invoke_custom(38500, 1, \"Camera.setCamera\", 1.3, 24, 6, 4)\r\n    invoke_custom(41000, 1, \"clearBubbles\", monsterId)\r\n        \r\n    -- \"Maintenant que tu en parles, je dois absolument te montrer la pièce suivante, suis-moi donc !\"\r\n    invoke_custom(41000, 1, \"bubble\", monsterId, \"quest.amakna.missmoches.03.18\")\r\n    invoke_custom(45000, 1, \"clearBubbles\", monsterId)\r\n    invoke_custom(43000, 1, \"Mobile.moveMobile\", monsterId, 25, 3, 4)\r\n    invoke_custom(43000, 1, \"Camera.attachCameraToMobile\", monsterId)\r\n    invoke_custom(44500, 1, \"Mobile.setMobileVisible\", monsterId, false)\r\n    \r\n    -- \"**Il faut que je reste sur mes gardes, cette princesse ne me dit rien qui vaille\"\r\n    invoke_custom(45000, 1, \"bubble\", playerId, \"quest.amakna.missmoches.03.19\")\r\n    invoke_custom(45000, 1, \"Camera.setCamera\", 1.3, 22, 6, 4)\r\n    invoke_custom(49000, 1, \"clearBubbles\", playerId)\r\n        \r\n    invoke_custom(49500, 1, \"skipCinematic\", 22406)\nend\n\n-- [EVENT] Fin de la cinématique de la salle 02 - Téléporte le joueur\n-- \nfunction event_2541_22414()\n    \nend\n\n-- [EVENT] Le joueur se fait accueillir par Lela - Cinématique Salle 03\n-- \nfunction event_2541_22407()\n    local playerId = Context.getLeaderId()\r\n    local monsterId = createActor(1111105445, 163, 10, 2, 4)\r\n        \r\n    startCinematicContext(1.3, playerId)\r\n        \r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 22407)\r\n        \r\n    -- \"Nous arrivons dans ma pièce préférée, c'est ici que nous prenons des bains et que nous nous détendons\"\r\n    invoke_custom(00500, 1, \"bubble\", monsterId, \"quest.amakna.missmoches.03.20\")\r\n    invoke_custom(00500, 1, \"Camera.setCamera\", 1.3, 163, 10, 2)\r\n    invoke_custom(05000, 1, \"clearBubbles\", monsterId)\r\n        \r\n    -- \"Il faut dire que le temps passe lentement quand on est une princesse qui attend l'arrivée d'un beau chevalier pour l'embr...\"\r\n    invoke_custom(05000, 1, \"bubble\", monsterId, \"quest.amakna.missmoches.03.21\")\r\n    invoke_custom(09500, 1, \"clearBubbles\", monsterId)\r\n        \r\n    -- \"...\"\r\n    invoke_custom(09500, 1, \"bubble\", playerId, \"quest.amakna.missmoches.03.11\")\r\n    invoke_custom(09500, 1, \"Camera.setCamera\", 1.3, 167, 10, 2)\r\n    invoke_custom(12500, 1, \"clearBubbles\", playerId)\r\n    invoke_custom(10000, 1, \"bubble\", monsterId, \"quest.amakna.missmoches.03.11\")\r\n    invoke_custom(10000, 1, \"Camera.setCamera\", 1.3, 163, 10, 2)\r\n    invoke_custom(12500, 1, \"clearBubbles\", monsterId)\r\n        \r\n    -- \"Qu'est-ce que tu allais dire ?\"\r\n    invoke_custom(12500, 1, \"bubble\", playerId, \"quest.amakna.missmoches.03.22\")\r\n    invoke_custom(12500, 1, \"Camera.setCamera\", 1.3, 167, 10, 2)\r\n    invoke_custom(15000, 1, \"clearBubbles\", playerId)\r\n        \r\n    -- \"Euh, qui, moi ? Rien du tout\"\r\n    invoke_custom(15000, 1, \"bubble\", monsterId, \"quest.amakna.missmoches.03.23\")\r\n    invoke_custom(15000, 1, \"Camera.setCamera\", 1.3, 163, 10, 2)\r\n    invoke_custom(18500, 1, \"clearBubbles\", monsterId)\r\n        \r\n    -- \"Et la porte du fond ?\"\r\n    invoke_custom(18500, 1, \"bubble\", playerId, \"quest.amakna.missmoches.03.24\")\r\n    invoke_custom(18500, 1, \"Camera.setCamera\", 1.3, 167, 10, 2)\r\n    invoke_custom(22000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Euh...\"\r\n    invoke_custom(22000, 1, \"bubble\", monsterId, \"quest.amakna.missmoches.03.25\")\r\n    invoke_custom(22000, 1, \"Camera.setCamera\", 1.3, 162, 10, 2)\r\n    invoke_custom(22000, 1, \"Mobile.moveMobile\", monsterId, 162, 10, 2)\r\n    invoke_custom(25500, 1, \"clearBubbles\", monsterId)\r\n    \r\n    -- \"Je vais être honnête avec toi, je viens ici parce qu'on m'a dit que des aventuriers disparaissent mystérieusement autour de cette tour\"\r\n    invoke_custom(25500, 1, \"bubble\", playerId, \"quest.amakna.missmoches.03.26\")\r\n    invoke_custom(25500, 1, \"Camera.setCamera\", 1.3, 167, 10, 2)\r\n    invoke_custom(30500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Un panneau indiquait clairement de ne pas y entrer et je me suis fait attaquer par un Gobgob devant la grande porte\"\r\n    invoke_custom(30500, 1, \"bubble\", playerId, \"quest.amakna.missmoches.03.27\")\r\n    invoke_custom(35000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Il se trouve que ton histoire n'a aucun sens et que tu es très suspecte. Je ne te le demanderais gentiment qu'une fois, dis-moi qui tu es\"\r\n    invoke_custom(35000, 1, \"bubble\", playerId, \"quest.amakna.missmoches.03.28\")\r\n    invoke_custom(40500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"...\"\r\n    invoke_custom(40500, 1, \"bubble\", monsterId, \"quest.amakna.missmoches.03.11\")\r\n    invoke_custom(40500, 1, \"Camera.setCamera\", 1.3, 162, 10, 2)\r\n    invoke_custom(42500, 1, \"clearBubbles\", monsterId)\r\n    \r\n    -- \"HAHAHAHA, TU T'ES FAIT AVOIR !!!\"\r\n    invoke_custom(42500, 1, \"bubble\", monsterId, \"quest.amakna.missmoches.03.29\")\r\n    invoke_custom(42500, 1, \"Mobile.setMobileDirection\", monsterId, 1)\r\n    invoke_custom(46000, 1, \"clearBubbles\", monsterId)\r\n    \r\n    -- \"Je suis en réalité, Lela ! Tu te trouves dans la tour des Miss Moches, nous capturons des aventuriers comme toi dans notre intérêt, je ne te dirai jamais pourquoi\"\r\n    invoke_custom(46000, 1, \"bubble\", monsterId, \"quest.amakna.missmoches.03.30\")\r\n    invoke_custom(51500, 1, \"clearBubbles\", monsterId)\r\n    \r\n    -- \"Je ne m'attendais pas à ce que tu sois aussi perspicace, tu as réussi à comprendre que j'avais des intentions négatives envers toi...\"\r\n    invoke_custom(51500, 1, \"bubble\", monsterId, \"quest.amakna.missmoches.03.31\")\r\n    invoke_custom(56500, 1, \"clearBubbles\", monsterId)\r\n    \r\n    -- \"Je te laisse donc une ouverture, soit tu prends tes jambes à ton cou comme un Tofu apeuré, soit tu viens m'affronter moi et les autres Miss dans la pièce du dessus\"\r\n    invoke_custom(56500, 1, \"bubble\", monsterId, \"quest.amakna.missmoches.03.32\")\r\n    invoke_custom(62000, 1, \"clearBubbles\", monsterId)\r\n    \r\n    -- \"Du moins, si tu l'oses...\"\r\n    invoke_custom(62000, 1, \"bubble\", monsterId, \"quest.amakna.missmoches.03.33\")\r\n    invoke_custom(65500, 1, \"clearBubbles\", monsterId)\r\n    \r\n    -- \"Réfléchis bien, tu n'auras pas de seconde chance !!!\"\r\n    invoke_custom(65500, 1, \"bubble\", monsterId, \"quest.amakna.missmoches.03.34\")\r\n    invoke_custom(65500, 1, \"Camera.attachCameraToMobile\", monsterId)\r\n    invoke_custom(65500, 1, \"Mobile.moveMobile\", monsterId, 152, 10, 14)\r\n    invoke_custom(69000, 1, \"clearBubbles\", monsterId)\r\n    \r\n    -- \"**Je dois absolument y aller pour sauver tous ces aventuriers, je n'ai pas le choix\"\r\n    invoke_custom(69000, 1, \"bubble\", playerId, \"quest.amakna.missmoches.03.35\")\r\n    invoke_custom(69000, 1, \"Camera.setCamera\", 1.3, 167, 10, 2)\r\n    invoke_custom(73000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(73500, 1, \"skipCinematic\", 22407)\nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_2541_22408","event_2541_22389","event_2541_22456","event_2541_22406","event_2541_22414","event_2541_22407"],"quest_calls":[],"dialogue_calls":[]},"scenario/2542.lua":{"source":"\n\n-- Variables globales\n-- \nfunction event_2542_22393()\n    \nend\n\n-- [EVENT] Le joueur entre dans l'instance - Inscription au scénario\n-- \nfunction event_2542_22394(doorOpened, bossId)\n    if (doorOpened == 1) then\r\n    else hideMonster(bossId)\r\n    end\nend\n\n-- Le joueur attaque Cire Momore - Lancement du Combat\n-- \nfunction event_2542_22395()\n    \nend\n\n-- INTERACTIVE_ELEMENT_ACTIVATION - Ouverture de la porte\n-- \nfunction event_2542_22396(bossId)\n    local playerId = Context.getLeaderId()\r\n    local bossId = toLong(bossId)\r\n    \r\n    startCinematicContext(1.0, bossId)\r\n    \r\n    invoke_custom(1999, 1, \"Mobile.addMobileCreationCallback\", bossId, \"showMonster\", bossId)\r\n    invoke_custom(1950, 1, \"Mobile.setMobileAnimation\", bossId, \"AnimApparition\")\r\n    invoke_custom(1950, 1, \"Sound.playSound\", 300183905357901, true, 50)\r\n    \r\n    invoke_custom(2000, 1, \"Effect.createCameraShakeEffect\", 100, 500, 100, 5, 100, \"BOTH\")\r\n    invoke_custom(6400, 1, \"Camera.attachCameraToMobile\", playerId)\r\n    \r\n    invoke_custom(6400, 1, \"skipCinematic\")\nend\n\n","functions":["event_2542_22393","event_2542_22394","event_2542_22395","event_2542_22396"],"quest_calls":[],"dialogue_calls":[]},"scenario/2543.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\nnimpId = 0\r\nkataId = 0\r\nsutraId = 0\r\n\r\nx = math.random(1, 4)\r\ny = math.random(1, 6)\r\n\r\nredSkinList = {0.90, 0.70, 0.95, 0.46, 0.80}\r\ngreenSkinList = {0.67, 0.51, 0.84, 0.32, 0.71}\r\nblueSkinList = {0.56, 0.02, 0.72, 0.09, 0.60}\r\n\r\nredHairList = {0.88, 0.40, 0.12, 0.30, 0.30, 0.45, 0.70}\r\ngreenHairList = {0.12, 0.88, 0.40, 0.30, 0.70, 0.45, 0.70}\r\nblueHairList = {0.40, 0.12, 0.88, 0.30, 0.70, 0.60, 0.70}\r\n\r\n--=KATAS=--\r\nfunction teacherInit(kataOne, kataTwo, teacherOne, teacherTwo, meditateOne)\r\n\tActor.changeSkin(kataOne, 121)\r\n\tActor.equip(kataOne, \"211210002\", \"VETEMENTCUSTOM\")\r\n\tActor.equip(kataOne, \"201210002\", \"CHEVEUXCUSTOM\")\r\n\tMobile.setPartColor(kataOne, \"Cheveux\", 0.70, 0.42, 0.48, 1)\r\n\tMobile.setPartColor(kataOne, \"Pupille\", 0.88, 0.12, 0.88, 1)\r\n\tActor.equip(kataOne, \"34731127\", \"JambeHabit\", \"PiedHabit01\", \"PiedHabit02\", \"Cape\", \"CapeBas\")\r\n\tActor.equip(kataOne, \"1347570\", \"Chapeau\")\r\n\r\n\tActor.changeSkin(kataTwo, 121)\r\n\tActor.equip(kataTwo, \"211210003\", \"VETEMENTCUSTOM\")\r\n\tActor.equip(kataTwo, \"201210003\", \"CHEVEUXCUSTOM\")\r\n\tMobile.setPartColor(kataTwo, \"Cheveux\", 0.20, 0.22, 0.40, 1)\r\n\tMobile.setPartColor(kataTwo, \"Pupille\", 0.88, 0.12, 0.88, 1)\r\n\tActor.equip(kataTwo, \"34731127\", \"JambeHabit\", \"PiedHabit01\", \"PiedHabit02\", \"Cape\", \"CapeBas\")\r\n\tActor.equip(kataTwo, \"1347570\", \"Chapeau\")\r\n\r\n\tActor.changeSkin(teacherOne, 121)\r\n\tActor.equip(teacherOne, \"211210002\", \"VETEMENTCUSTOM\")\r\n\tActor.equip(teacherOne, \"201210002\", \"CHEVEUXCUSTOM\")\r\n\tMobile.setPartColor(teacherOne, \"Cheveux\", 0.30, 0.12, 0.12, 1)\r\n\tMobile.setPartColor(teacherOne, \"Pupille\", 0.88, 0.12, 0.88, 1)\r\n\tActor.equip(teacherOne, \"34731127\", \"JambeHabit\", \"PiedHabit01\", \"PiedHabit02\", \"Cape\", \"CapeBas\")\r\n\tActor.equip(teacherOne, \"1347570\", \"Chapeau\")\r\n\r\n\tActor.changeSkin(teacherTwo, 121)\r\n\tActor.equip(teacherTwo, \"211210003\", \"VETEMENTCUSTOM\")\r\n\tActor.equip(teacherTwo, \"201210003\", \"CHEVEUXCUSTOM\")\r\n\tMobile.setPartColor(teacherTwo, \"Cheveux\", 0.60, 0.22, 0.80, 1)\r\n\tMobile.setPartColor(teacherTwo, \"Pupille\", 0.88, 0.12, 0.88, 1)\r\n\tActor.equip(teacherTwo, \"34731127\", \"JambeHabit\", \"PiedHabit01\", \"PiedHabit02\", \"Cape\", \"CapeBas\")\r\n\tActor.equip(teacherTwo, \"1347570\", \"Chapeau\")\r\n\r\n\tActor.changeSkin(meditateOne, 120)\r\n\tMobile.setMobileDirection(meditateOne, 3)\r\n\tMobile.setMobilePosition(meditateOne, 8, -7, 1)\r\n\tActor.equip(meditateOne, \"211200101\", \"VETEMENTCUSTOM\")\r\n\tActor.equip(meditateOne, \"201200009\", \"CHEVEUXCUSTOM\")\r\n\tMobile.setPartColor(meditateOne, \"Cheveux\", 0.60, 0.22, 0.80, 1)\r\n\tMobile.setPartColor(meditateOne, \"Pupille\", 0.88, 0.12, 0.88, 1)\r\n\tMobile.setPartColor(meditateOne, \"ColorCostume1\", 0.33, 0.49, 0.22, 1)\r\n\tMobile.setPartColor(meditateOne, \"ColorCostume2\", 0.08, 0.08, 0.08, 1)\r\n\tMobile.setPartColor(meditateOne, \"ColorCostume3\", 0.54, 0.49, 0.08, 1)\r\n\tMobile.setPartColor(meditateOne, \"ColorCostume4\", 0.81, 0.72, 0.47, 1)\r\n\tMobile.setPartColor(meditateOne, \"ColorCostume5\", 0.81, 0.72, 0.47, 1)\r\n\tMobile.setPartColor(meditateOne, \"ColorCostume6\", 0.45, 0.53, 0.16, 1)\r\n\t--Actor.equip(meditateOne, \"1197571\", \"PiedHabit01\", \"PiedHabit02\")\r\n\t--Actor.equip(meditateOne, \"3477573\", \"CorpsHabit\")\r\n\tActor.equip(meditateOne, \"1347574\", \"Chapeau\")\r\nend\r\n\r\nfunction iopInit(iopStudent)\r\n\tActor.changeSkin(iopStudent, 80)\r\n\tMobile.setPartVisible(iopStudent, false, \"JupeVetement\")\r\n\tActor.equip(iopStudent, \"210800001\", \"VETEMENTCUSTOM\")\r\n\tActor.equip(iopStudent, \"200800001\", \"CHEVEUXCUSTOM\")\r\n\tActor.equip(iopStudent, \"1197571\", \"PiedHabit01\", \"PiedHabit02\")\r\n\tActor.equip(iopStudent, \"1367573\", \"CorpsHabit\")\r\n\tActor.equip(iopStudent, \"1347574\", \"Chapeau\")\r\n\tMobile.setPartColor(iopStudent, \"Peau\", 0.85, 0.69, 0.43, 1)\r\n\tMobile.setPartColor(iopStudent, \"Cheveux\", 0.88, 0.40, 0.12, 1)\r\nend\r\n\r\nfunction iopStart(iopStudent, nimp)\r\n\t--nimpId=toLong(nimp)\r\n\ttimer = (math.random(3) * 80) + 1000\r\n\tif (nimpId == 1) then\r\n\t\tinvoke(timer, 1, \"Mobile.setMobileAnimation\", iopStudent, \"AnimIncarnam-KataIop01\")\r\n\telseif (nimpId == 2) then\r\n\t\tinvoke(timer, 1, \"Mobile.setMobileAnimation\", iopStudent, \"AnimIncarnam-KataIop02\")\r\n\telseif (nimpId == 3) then\r\n\t\tinvoke(timer, 1, \"Mobile.setMobileAnimation\", iopStudent, \"AnimIncarnam-KataIop03\")\r\n\telseif (nimpId == 4) then\r\n\t\tinvoke(timer, 1, \"Mobile.setMobileAnimation\", iopStudent, \"AnimIncarnam-KataIop04\")\r\n\telseif (nimpId == 5) then\r\n\t\tinvoke(timer, 1, \"Mobile.setMobileAnimation\", iopStudent, \"AnimIncarnam-KataIop05\")\r\n\telseif (nimpId == 0) then\r\n\t\tinvoke(timer, 1, \"Mobile.setMobileAnimation\", iopStudent, \"AnimIncarnam-KataIop06\")\r\n\tend\r\n\tnimpId = (nimpId + 1) % 6\r\n\tinvoke(4000, 1, \"iopStart\", iopStudent, nimp)\r\nend\r\n\r\nfunction createListe(a, b, c, d, e, f, g, h, i, j, k, l, m)\r\n\tliste = {a, b, c, d, e, f, g, h, i, j, k, l, m}\r\n\tlisteX = {-5, -4, -3, -5, -4, -3, 3, 4, 5, 3, 4}\r\n\tlisteY = {-15, -15, -15, -13, -13, -13, -11, -11, -11, -13, -13}\r\nend\r\n\r\nfunction pandaPlayInit(mod, modX, modY, x, y)\r\n\tlocal sex = math.random(0, 1)\r\n\tlocal breedId = math.random(1, 18)\r\n\tlocal breedSkinId = 0\r\n\tlocal clothes = math.random(1, 5)\r\n\tlocal clothes = toString(clothes)\r\n\r\n\tif (breedId == 17) then\r\n\t\tbreedSkinId = \"11\"\r\n\t\tbreedId = 11\r\n\telseif (breedId == 8) then\r\n\t\tbreedSkinId = \"09\"\r\n\t\tbreedId = 9\r\n\telseif (breedId >= 10) then\r\n\t\tbreedSkinId = toString(breedId)\r\n\telse\r\n\t\tbreedSkinId = toString(\"0\" .. breedId)\r\n\tend\r\n\r\n\tlocal skinId = toString(breedId .. sex)\r\n\tlocal clothesId = toString(\"21\" .. breedSkinId .. sex .. \"000\" .. clothes)\r\n\tlocal hairId = toString(\"20\" .. breedSkinId .. sex .. \"0002\")\r\n\r\n\tActor.changeSkin(mod, skinId)\r\n\tif (breedId ~= 16) then\r\n\t\tActor.equip(mod, clothesId, \"VETEMENTCUSTOM\")\r\n\telse end\r\n\tActor.equip(mod, hairId, \"CHEVEUXCUSTOM\")\r\n\tif (sex == 0) then\r\n\t\tActor.equip(mod, \"51331127\", \"JambeHabit\", \"PiedHabit01\", \"PiedHabit02\", \"Cape\", \"CapeBas\")\r\n\telse\r\n\t\tActor.equip(mod, \"34731127\", \"JambeHabit\", \"PiedHabit01\", \"PiedHabit02\", \"Cape\", \"CapeBas\")\r\n\tend\r\n\tMobile.setPartColor(mod, \"Peau\", redSkinList[x], greenSkinList[x], blueSkinList[x], 1)\r\n\tMobile.setPartColor(mod, \"Cheveux\", redHairList[y], greenHairList[y], blueHairList[y], 1)\r\n\tMobile.setPartColor(mod, \"Pupille\", redHairList[y], greenHairList[y], blueHairList[y], 1)\r\n\r\n\ttrace(skinId, clothesId, hairId)\r\nend\r\n\r\n\r\n--=COMPORTEMENT=--\r\nfunction kataStart(kata, kataOne, kataTwo)\r\n\t--kataId= toLong(kata)\r\n\t\tfor i = 0, 10 do\r\n\t\t\tmod = liste[i+1]\r\n\t\t\ttimer = (math.random(3) * 40) + 1000\r\n\t\t\tif (kataId == 0)  then\r\n\t\t\t\tinvoke(timer, 1, \"Mobile.setMobileAnimation\", mod, \"AnimIncarnam-Kano01\")\r\n\t\t\t\t--Mobile.setMobileAnimation(soundInstructeur, \"AnimIncarnam-Kano01\")\r\n\t\t\telse\r\n\t\t\t\tinvoke(timer, 1, \"Mobile.setMobileAnimation\", mod, \"AnimIncarnam-Kano02\")\r\n\t\t\t\t--Mobile.setMobileAnimation(soundInstructeur, \"AnimIncarnam-Kano02\")\r\n\t\t\tend\r\n\t\t\ti = i + 1\r\n\t\tend\r\n\r\n\t\tif (kataId == 0)  then\r\n\t\t\tinvoke(400, 1, \"Mobile.setMobileAnimation\", kataOne, \"AnimIncarnam-Kano01\")\r\n\t\t\tinvoke(400, 1, \"Mobile.setMobileAnimation\", kataTwo, \"AnimIncarnam-Kano01\")\r\n\t\t\t--Mobile.setMobileAnimation(soundInstructeur, \"AnimIncarnam-Kano01\")\r\n\t\telse\r\n\t\t\tinvoke(400, 1, \"Mobile.setMobileAnimation\", kataOne, \"AnimIncarnam-Kano02\")\r\n\t\t\tinvoke(400, 1, \"Mobile.setMobileAnimation\", kataTwo, \"AnimIncarnam-Kano02\")\r\n\t\t\t--Mobile.setMobileAnimation(soundInstructeur, \"AnimIncarnam-Kano02\")\r\n\t\tend\r\n\r\n\r\n\tif (kataId == 0)  then\r\n\t\t\tkataId = 1\r\n\t\telse\r\n\t\t\tkataId = 0\r\n\t\tend\r\n\tinvoke(4000, 1, \"kataStart\", kata, kataOne, kataTwo)\r\nend\r\n\r\nfunction teacherStart(sutraId, teacherOne, teacherTwo)\r\n\t--kataId= toLong(kata)\r\n\r\n\tif (sutraId == 0)  then\r\n\t\tinvoke(400, 1, \"Mobile.setMobileAnimation\", teacherOne, \"AnimIncarnam-Kano-Parler01\")\r\n\t\tinvoke(400, 1, \"Mobile.setMobileAnimation\", teacherTwo, \"AnimIncarnam-Kano-Parler01\")\r\n\t\t--Mobile.setMobileAnimation(soundInstructeur, \"AnimIncarnam-Kano01\")\r\n\telse\r\n\t\tinvoke(400, 1, \"Mobile.setMobileAnimation\", teacherOne, \"AnimIncarnam-Kano-Parler02\")\r\n\t\tinvoke(400, 1, \"Mobile.setMobileAnimation\", teacherTwo, \"AnimIncarnam-Kano-Parler02\")\r\n\t\t--Mobile.setMobileAnimation(soundInstructeur, \"AnimIncarnam-Kano02\")\r\n\tend\r\n\r\n\tsutraId = math.random(0, 1)\r\n\r\n\tinvoke(6000, 1, \"teacherStart\", sutraId, teacherOne, teacherTwo)\r\nend\r\n\r\nfunction displayGuide(guideId)\r\n    UI.loadGuideDialog(guideId)\r\n\r\n    invoke(100, 1, \"addButton\", guideId)\r\nend\r\n\r\nfunction addButton(guideId)\r\n    UI.displayButton(false, \"guide.displayConfirm\", \"incarnam.guide.displayGuide\", \"displayGuide\", guideId)\r\n    FightEvent.addFightEndCallback(\"UI.hideButton\")\r\nend\n\n-- [INIT] Variables\n-- \nfunction event_2543_22416()\n    \nend\n\n-- ENTER_INSTANCE\n-- \nfunction event_2543_22403(kataOne, kataTwo, studentOne, studentTwo, studentThree, studentFour, studentFive, studentSix, studentSeven, studentEight, studentNine, studentTen, studentEleven, iopStudent, teacherOne, teacherTwo, meditateOne)\n    --=PNJ=--\r\n    \r\n    --Liste des PNJ\r\n    createListe(studentOne, studentTwo, studentThree, studentFour, studentFive, studentSix, studentSeven, studentEight, studentNine, studentTen, studentEleven)\r\n    \r\n    --Iop qui fait nimps\r\n    iopInit(iopStudent)\r\n    \r\n    --Pandas faisant leurs katas\r\n    for i = 1, 11 do\r\n    \tmod = liste[i]\r\n    \tmodX = listeX[i]\r\n    \tmodY = listeY[i]\r\n    \ti = i + 1\r\n    \tx = x + 1\r\n    \ty = y + 1\r\n    \tpandaPlayInit(mod, modX, modY, x, y)\r\n    \r\n    \tif (x == 5) then\r\n    \t\tx = 1\r\n    \telse\r\n    \tend\r\n    \tif (y == 7) then\r\n    \t\ty = 1\r\n    \telse\r\n    \tend\r\n    end\r\n    \r\n    teacherInit(kataOne, kataTwo, teacherOne, teacherTwo, meditateOne)\r\n    \r\n    kataStart(kata, kataOne, kataTwo)\r\n    iopStart(iopStudent, nimp)\r\n    teacherStart(sutraId, teacherOne, teacherTwo)\r\n    \r\n    Mobile.setMobileAnimation(meditateOne, \"AnimIncarnam-Assis-Statique\")\nend\n\n-- ENTER_INSTANCE - 1 - 0 - Cinématique Airyna\n-- \nfunction event_2543_22490(airyna)\n    local airynaId = toLong(airynaId)\r\n    \r\n    --CINEMATIQUE\r\n    local airyna = createActor(1111505460, 0, -19, 3, 4, 3, 9)\r\n    local playerId = Context.getLeaderId()\r\n    Mobile.hideOtherPlayerMobile(true)\r\n    \r\n    function customSkip()\r\n    \tMobile.hideOtherPlayerMobile(false)\r\n    \tMobile.setMobileVisible(airynaId, true)\r\n    \tskipCinematic(22490)\r\n    end\r\n    \r\n    Mobile.setMobilePosition(playerId, 0, -8, 0)\r\n    Mobile.setMobileVisible(airynaId, false)\r\n    Mobile.setMobileMovementStyle(playerId, \"WALK\", \"WALK\")\r\n    \r\n    fullScreen(0, 1000, 1000)\r\n    \r\n    startCinematicContext(1.7, playerId)\r\n    \r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"customSkip\")\r\n    \r\n    invoke_custom(00000, 1, \"Camera.setZoomSpeedFactor\", 0.01)\r\n    invoke_custom(01000, 1, \"Camera.setZoomFactor\", 1.3)\r\n    \r\n    invoke_custom(03000, 1, \"Camera.setWorldTarget\", -5, -13, 0)\r\n    \r\n    invoke_custom(00000, 1, \"Mobile.moveMobile\", playerId, 0, -13, 0, \"Mobile.setMobileDirection\", playerId, 5)\r\n    invoke_custom(06000, 1, \"Mobile.setMobileDirection\", playerId, 1)\r\n    \r\n    invoke_custom(06000, 1, \"Camera.setWorldTarget\", 5, -13, 0)\r\n    \r\n    invoke_custom(08750, 1, \"Camera.attachCameraToMobile\", airyna)\r\n    \r\n    -- \"Je suis Airyna. Bienvenue dans mon dojo.\"\r\n    invoke_custom(09000, 1, \"bubble\", airyna, \"quest.ri.02.02\")\r\n    invoke_custom(09000, 1, \"Mobile.setMobileAnimation\", airyna, \"AnimComp-Positif\")\r\n    invoke_custom(12500, 1, \"clearBubbles\", airyna)\r\n    \r\n    invoke_custom(09500, 1, \"Mobile.setMobileDirection\", playerId, 7)\r\n    \r\n    -- \"Je vais t'apprendre à te battre, petit scarafeuille !\"\r\n    invoke_custom(13000, 1, \"bubble\", airyna, \"quest.ri.02.03\")\r\n    invoke_custom(13000, 1, \"Mobile.setMobileAnimation\", airyna, \"AnimComp-Parle\")\r\n    invoke_custom(16500, 1, \"clearBubbles\", airyna)\r\n    \r\n    invoke_custom(14000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Huss-Boucle\")\r\n    \r\n    invoke_custom(17000, 1, \"customSkip\")\nend\n\n-- CLIENT_TRIGGERED_EVENT - 1 - 0 - Fin de la cinématique\n-- \nfunction event_2543_23915()\n    \nend\n\n-- DIALOG_EXECUTED - Cours n°1 (Orientation)\n-- \nfunction event_2543_22409()\n    invoke(1000, 1, \"displayGuide\", 115)\nend\n\n-- FIGHT_ENDED_IN_CLIENT_EVENT - Ach cours n°1\n-- \nfunction event_2543_22540()\n    local playerId = Context.getLeaderId()\r\n    \r\n    Mobile.setMobileDirection(playerId, 7)\r\n    \r\n    invoke(100, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Huss-Boucle\")\nend\n\n-- DIALOG_EXECUTED - Cours n°2 (Éléments)\n-- \nfunction event_2543_22494()\n    invoke(1000, 1, \"displayGuide\", 116)\nend\n\n-- FIGHT_ENDED_IN_CLIENT_EVENT - Ach cours n°2\n-- \nfunction event_2543_22541()\n    local playerId = Context.getLeaderId()\r\n    \r\n    Mobile.setMobileDirection(playerId, 7)\r\n    \r\n    invoke(100, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Huss-Boucle\")\nend\n\n-- DIALOG_EXECUTED - Cours n°3 (Mêlée et distance)\n-- \nfunction event_2543_22495()\n    invoke(1000, 1, \"displayGuide\", 117)\nend\n\n-- FIGHT_ENDED_IN_CLIENT_EVENT - Ach cours n°3\n-- \nfunction event_2543_22542()\n    local playerId = Context.getLeaderId()\r\n    \r\n    Mobile.setMobileDirection(playerId, 7)\r\n    \r\n    invoke(100, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Huss-Boucle\")\nend\n\n-- DIALOG_EXECUTED - Cours n°4 (Ligne de vue)\n-- \nfunction event_2543_22507()\n    invoke(1000, 1, \"displayGuide\", 118)\nend\n\n-- FIGHT_ENDED_IN_CLIENT_EVENT - Ach cours n°4\n-- \nfunction event_2543_22543()\n    local playerId = Context.getLeaderId()\r\n    \r\n    Mobile.setMobileDirection(playerId, 7)\r\n    \r\n    invoke(100, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Huss-Boucle\")\nend\n\n-- DIALOG_EXECUTED - Cours n°5 (Zones)\n-- \nfunction event_2543_22508()\n    invoke(1000, 1, \"displayGuide\", 119)\nend\n\n-- FIGHT_ENDED_IN_CLIENT_EVENT - Ach cours n°5\n-- \nfunction event_2543_22544()\n    local playerId = Context.getLeaderId()\r\n    \r\n    Mobile.setMobileDirection(playerId, 7)\r\n    \r\n    invoke(100, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Huss-Boucle\")\nend\n\n-- DIALOG_EXECUTED - Cours n°6 (Les effets de déplacement)\n-- \nfunction event_2543_22516()\n    invoke(1000, 1, \"displayGuide\", 120)\nend\n\n-- FIGHT_ENDED_IN_CLIENT_EVENT - Ach cours n°6\n-- \nfunction event_2543_22545()\n    local playerId = Context.getLeaderId()\r\n    \r\n    Mobile.setMobileDirection(playerId, 7)\r\n    \r\n    invoke(100, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Huss-Boucle\")\nend\n\n-- DIALOG_EXECUTED - Cours n°7 (États)\n-- \nfunction event_2543_22517()\n    invoke(1000, 1, \"displayGuide\", 121)\nend\n\n-- FIGHT_ENDED_IN_CLIENT_EVENT - Ach cours n°7\n-- \nfunction event_2543_22546()\n    local playerId = Context.getLeaderId()\r\n    \r\n    Mobile.setMobileDirection(playerId, 7)\r\n    \r\n    invoke(100, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Huss-Boucle\")\nend\n\n-- FIGHT_ENDED_IN_CLIENT_EVENT\n-- \nfunction event_2543_23916(kataOne, kataTwo, studentOne, studentTwo, studentThree, studentFour, studentFive, studentSix, studentSeven, studentEight, studentNine, studentTen, studentEleven, iopStudent, teacherOne, teacherTwo, meditateOne)\n    --=PNJ=--\r\n    \r\n    --Liste des PNJ\r\n    createListe(studentOne, studentTwo, studentThree, studentFour, studentFive, studentSix, studentSeven, studentEight, studentNine, studentTen, studentEleven)\r\n    \r\n    --Iop qui fait nimps\r\n    iopInit(iopStudent)\r\n    \r\n    --Pandas faisant leurs katas\r\n    for i = 1, 11 do\r\n    \tmod = liste[i]\r\n    \tmodX = listeX[i]\r\n    \tmodY = listeY[i]\r\n    \ti = i + 1\r\n    \tx = x + 1\r\n    \ty = y + 1\r\n    \tpandaPlayInit(mod, modX, modY, x, y)\r\n    \r\n    \tif (x == 5) then\r\n    \t\tx = 1\r\n    \telse\r\n    \tend\r\n    \tif (y == 7) then\r\n    \t\ty = 1\r\n    \telse\r\n    \tend\r\n    end\r\n    \r\n    teacherInit(kataOne, kataTwo, teacherOne, teacherTwo, meditateOne)\r\n    \r\n    kataStart(kata, kataOne, kataTwo)\r\n    iopStart(iopStudent, nimp)\r\n    teacherStart(sutraId, teacherOne, teacherTwo)\r\n    \r\n    Mobile.setMobileAnimation(meditateOne, \"AnimIncarnam-Assis-Statique\")\nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","teacherInit","iopInit","iopStart","createListe","pandaPlayInit","kataStart","teacherStart","displayGuide","addButton","event_2543_22416","event_2543_22403","event_2543_22490","customSkip","event_2543_23915","event_2543_22409","event_2543_22540","event_2543_22494","event_2543_22541","event_2543_22495","event_2543_22542","event_2543_22507","event_2543_22543","event_2543_22508","event_2543_22544","event_2543_22516","event_2543_22545","event_2543_22517","event_2543_22546","event_2543_23916"],"quest_calls":[],"dialogue_calls":[]},"scenario/2545.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n  \r\n-- Fonctions cache / montre CM\r\nfunction hideMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, false)\r\nend\r\n\r\nfunction showMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, true)\r\nend\r\n\r\nbubbleFightInfoId = 0\r\n\r\nfunction closeFightInfo()\r\n\tif (bubbleFightInfoId ~= nil  and bubbleFightInfoId ~= 0) then BubbleText.close(bubbleFightInfoId) end\r\nend\r\n\r\nfunction onFightInfoClosed()\r\n\tif (bubbleFightInfoId ~= nil  and bubbleFightInfoId ~= 0) then bubbleFightInfoId = 0 end\r\nend\r\n\r\nfunction updateFightInfo(wave, difficulty, forceDisplayUI)\r\n\tlocal wave = toLong(wave)\r\n\tlocal difficulty = toLong(difficulty)\r\n\r\n\tif (bubbleFightInfoId == 0) then\r\n\t\tbubbleFightInfoId = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_WEST\", 0, -60, false, 2147483647, true, \"interactiveBubbleDialog5\", 30000, 25000, \"onFightInfoClosed\")\r\n\tend\r\n\r\n\tBubbleText.setText(bubbleFightInfoId, \"wave.fight.player.infos\", wave, difficulty)\r\n\r\n\tif (forceDisplayUI) then BubbleText.show(bubbleFightInfoId) end\r\nend\n\n-- [INIT] Variables globales\n-- \nfunction event_2545_22447()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2545_22448()\n    local playerId = Context.getLeaderId()\r\n    local bossId = createActor(1108305306, -54, 8, 58, 8, 1, 26)\r\n    Mobile.setMobileAnimation(bossId, \"AnimComp-1\")\r\n    \r\n    startCinematicContext(1.2, playerId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 22448)\r\n    \r\n    invoke_custom(00010, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimSort-Bond-Fin\")\r\n    invoke_custom(01000, 1, \"Camera.setCamera\", 1, -54, 8, 58)\r\n    \r\n    -- \"GOULTARD...\"\r\n    invoke_custom(01000, 1, \"Sound.playSound\", 90000082, true, 40)\r\n    invoke_custom(01000, 1, \"bubble\", bossId, \"japanexpo.2023.01\")\r\n    invoke_custom(03000, 1, \"clearBubbles\", bossId)\r\n    \r\n    -- \"TU ES VENU JUSQUE DANS MON PALAIS ?\"\r\n    invoke_custom(03500, 1, \"Sound.playSound\", 90000085, true, 40)\r\n    invoke_custom(03500, 1, \"bubble\", bossId, \"japanexpo.2023.02\")\r\n    invoke_custom(06300, 1, \"Mobile.setMobileAnimation\", bossId, \"AnimComp-2\")\r\n    invoke_custom(06500, 1, \"clearBubbles\", bossId)\r\n    invoke_custom(06500, 1, \"Camera.setCamera\", 1, -49, 7, -4)\r\n    \r\n    invoke_custom(06999, 1, \"Mobile.setMobilePosition\", bossId, -49, 7, -4)\r\n    invoke_custom(07000, 1, \"Mobile.setMobileAnimation\", bossId, \"AnimSort-Bond-Fin\")\r\n    invoke_custom(07100, 1, \"Particle.addParticleSystem\", -1453072821, -49, 7, -4)\r\n    invoke_custom(07000, 1, \"Effect.createCameraShakeEffect\", 100, 500, 100, 5, 100, \"BOTH\")\r\n    \r\n    -- \"MES SHUSHUS VONT T'ÉCRABOUILLER, MINABLE !\"\r\n    invoke_custom(07500, 1, \"Sound.playSound\", 90000083, true, 40)\r\n    invoke_custom(07500, 1, \"bubble\", bossId, \"japanexpo.2023.03\")\r\n    invoke_custom(08000, 1, \"Mobile.setMobileAnimation\", bossId, \"AnimComp-4\")\r\n    invoke_custom(11000, 1, \"clearBubbles\", bossId)\r\n    \r\n    -- \"VOYONS COMBIEN DE TEMPS TU POURRAS TENIR...\"\r\n    invoke_custom(11500, 1, \"Sound.playSound\", 90000083, true, 40)\r\n    invoke_custom(11500, 1, \"bubble\", bossId, \"japanexpo.2023.04\")\r\n    invoke_custom(12000, 1, \"Mobile.setMobileAnimation\", bossId, \"AnimComp-3\")\r\n    invoke_custom(15500, 1, \"clearBubbles\", bossId)\r\n    invoke_custom(16000, 1, \"Camera.setCamera\", 1.3, -41, 7, -4)\r\n    \r\n    -- \"Quand tu veux, gros nigaud !\"\r\n    invoke_custom(16500, 1, \"bubble\", playerId, \"japanexpo.2023.05\")\r\n    invoke_custom(20000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(20001, 1, \"skipCinematic\", 22448)\nend\n\n-- [EVENT] CLIENT_TRIGGERED_EVENT - Lancement du combat\n-- \nfunction event_2545_22449()\n    trace(\"LANCEMENT DU COMBAT\")\nend\n\n-- [EVENT] FIGHT_ENTER_ACTION_PHASE - Application états\n-- \nfunction event_2545_22450(wave, difficulty)\n    updateFightInfo(wave, difficulty, true)\nend\n\n-- [EVENT] NEW_MONSTER_WAVE - Difficulté\n-- \nfunction event_2545_22451(wave, difficulty)\n    updateFightInfo(wave, difficulty, true)\nend\n\n-- [EVENT] FIGHT_ENDED_IN_CLIENT - On ferme l'affichage\n-- \nfunction event_2545_22453()\n    closeFightInfo()\nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","hideMonster","showMonster","closeFightInfo","onFightInfoClosed","updateFightInfo","event_2545_22447","event_2545_22448","event_2545_22449","event_2545_22450","event_2545_22451","event_2545_22453"],"quest_calls":[],"dialogue_calls":[]},"scenario/2546.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n  \r\n-- Fonctions cache / montre CM\r\nfunction hideMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, false)\r\nend\r\n\r\nfunction showMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, true)\r\nend\r\n\r\nbubbleFightInfoId = 0\r\n\r\nfunction closeFightInfo()\r\n\tif (bubbleFightInfoId ~= nil and bubbleFightInfoId ~= 0) then BubbleText.close(bubbleFightInfoId) end\r\nend\r\n\r\nfunction onFightInfoClosed()\r\n\tif (bubbleFightInfoId ~= nil and bubbleFightInfoId ~= 0) then bubbleFightInfoId = 0 end\r\nend\r\n\r\nfunction updateFightInfo(wave, difficulty, teamDamage, forceDisplayUI)\r\n\tlocal wave = toLong(wave)\r\n\tlocal difficulty = toLong(difficulty) - 2\r\n\tlocal teamDamage = toLong(teamDamage)\r\n\r\n\tif (bubbleFightInfoId == 0) then\r\n\t\tbubbleFightInfoId = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_WEST\", 0, -60, false, 2147483647, true, \"interactiveBubbleDialog5\", 30000, 25000, \"onFightInfoClosed\")\r\n\tend\r\n\r\n\tBubbleText.setText(bubbleFightInfoId, \"japan.expo.2023.wave.info\", wave, difficulty, teamDamage)\r\n\r\n\tif (forceDisplayUI) then BubbleText.show(bubbleFightInfoId) end\r\nend\n\n-- [INIT] Variables globales\n-- \nfunction event_2546_22462()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2546_22463()\n    local playerId = Context.getLeaderId()\r\n    local remingtonId = createActor(197902018, -6,-3, 0)\r\n    local bossId = createActor(1108305306, -54, 8, 58, 8, 1, 26)\r\n    \r\n    Mobile.setMobileAnimation(bossId, \"AnimComp-1\")\r\n    Mobile.setMobileVisible(remingtonId, false)\r\n    \r\n    startCinematicContext(1.2, playerId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 22463)\r\n    \r\n    invoke_custom(00010, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimSort-Bond-Fin\")\r\n    invoke_custom(01000, 1, \"Camera.setCamera\", 1, -54, 8, 58)\r\n    \r\n    -- \"GOULTARD...\"\r\n    invoke_custom(01000, 1, \"Sound.playSound\", 90000082, true, 40)\r\n    invoke_custom(01000, 1, \"bubble\", bossId, \"japanexpo.2023.01\")\r\n    invoke_custom(03000, 1, \"clearBubbles\", bossId)\r\n    \r\n    -- \"TU ES VENU JUSQUE DANS MON PALAIS ?\"\r\n    invoke_custom(03500, 1, \"Sound.playSound\", 90000085, true, 40)\r\n    invoke_custom(03500, 1, \"bubble\", bossId, \"japanexpo.2023.02\")\r\n    invoke_custom(06300, 1, \"Mobile.setMobileAnimation\", bossId, \"AnimComp-2\")\r\n    invoke_custom(06500, 1, \"clearBubbles\", bossId)\r\n    invoke_custom(06500, 1, \"Camera.setCamera\", 1, -49, 7, -4)\r\n    \r\n    invoke_custom(06999, 1, \"Mobile.setMobilePosition\", bossId, -49, 7, -4)\r\n    invoke_custom(07000, 1, \"Mobile.setMobileAnimation\", bossId, \"AnimSort-Bond-Fin\")\r\n    invoke_custom(07100, 1, \"Particle.addParticleSystem\", -1453072821, -49, 7, -4)\r\n    invoke_custom(07000, 1, \"Effect.createCameraShakeEffect\", 100, 500, 100, 5, 100, \"BOTH\")\r\n    \r\n    -- \"MES SHUSHUS VONT T'ÉCRABOUILLER, MINABLE !\"\r\n    invoke_custom(07500, 1, \"Sound.playSound\", 90000083, true, 40)\r\n    invoke_custom(07500, 1, \"bubble\", bossId, \"japanexpo.2023.03\")\r\n    invoke_custom(08000, 1, \"Mobile.setMobileAnimation\", bossId, \"AnimComp-4\")\r\n    invoke_custom(11000, 1, \"clearBubbles\", bossId)\r\n    \r\n    -- \"VOYONS COMBIEN DE TEMPS TU POURRAS TENIR...\"\r\n    invoke_custom(11500, 1, \"Sound.playSound\", 90000083, true, 40)\r\n    invoke_custom(11500, 1, \"bubble\", bossId, \"japanexpo.2023.04\")\r\n    invoke_custom(12000, 1, \"Mobile.setMobileAnimation\", bossId, \"AnimComp-3\")\r\n    invoke_custom(15500, 1, \"clearBubbles\", bossId)\r\n    invoke_custom(16000, 1, \"Camera.setCamera\", 1.3, -41, 7, -4)\r\n    \r\n    -- \"Quand tu veux, gros nigaud ! Voyons combien de temps tu tiendras contre nous !\"\r\n    invoke_custom(16500, 1, \"bubble\", playerId, \"japanexpo.2024.02\")\r\n    invoke_custom(16500, 1, \"Mobile.setMobileVisible\", remingtonId, false)\r\n    invoke_custom(20000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(20001, 1, \"skipCinematic\", 22463)\nend\n\n-- [EVENT] CLIENT_TRIGGERED_EVENT - Lancement du combat\n-- \nfunction event_2546_22464()\n    trace(\"LANCEMENT DU COMBAT\")\nend\n\n-- [EVENT] FIGHT_ENTER_ACTION_PHASE - Application états\n-- \nfunction event_2546_22465(wave, difficulty, teamDamage)\n    updateFightInfo(wave, difficulty, teamDamage, true)\nend\n\n-- [EVENT] NEW_MONSTER_WAVE - Difficulté\n-- \nfunction event_2546_22466(wave, difficulty, teamDamage)\n    updateFightInfo(wave, difficulty, teamDamage, true)\nend\n\n-- [EVENT] FIGHT_ENDED_IN_CLIENT - On ferme l'affichage\n-- \nfunction event_2546_22467(wave, difficulty, teamDamage, fightWon)\n    local wave = toLong(wave)\r\n    local teamDamage = toLong(teamDamage)\r\n    \r\n    if (toLong(fightWon) == 1) then\r\n    \tUI.writeLocalisedInChat(\"japan.expo.2024.fight.mode.ultimate.won\", wave)\r\n    \tUI.writeLocalisedInChat(\"japan.expo.2023.fight.final.score.wave\", wave)\r\n    \tUI.writeLocalisedInChat(\"japan.expo.2023.fight.final.score.damage\", teamDamage)\r\n    end\r\n    \r\n    closeFightInfo()\nend\n\n-- EFFECT_EXECUTION - Le joueur a gagné le combat\n-- \nfunction event_2546_22941()\n    \nend\n\n-- EFFECT_EXECUTION - Mise à jour UI infos de combat (score)\n-- \nfunction event_2546_22483(wave, difficulty, teamDamage)\n    updateFightInfo(wave, difficulty, teamDamage, true)\nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","hideMonster","showMonster","closeFightInfo","onFightInfoClosed","updateFightInfo","event_2546_22462","event_2546_22463","event_2546_22464","event_2546_22465","event_2546_22466","event_2546_22467","event_2546_22941","event_2546_22483"],"quest_calls":[],"dialogue_calls":[]},"scenario/2547.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n-- TRIGGER CLIENT --\r\n-- 0 = Fin cinématique VIDEO | Déclenché par le callback Video.addVideoStopOrEndCallback\r\n-- 1 = Arrivée dans l'instance | Déclenché par onInstanceLoaded() callback par Event.runOnInstanceLoaded (cf code Global)\r\n-- 2 = Fin cinématique | Déclenché par stopCinematicContext() (cf code Global)\r\n-- 3 = Fermeture UI Fin de combat\r\n-- 4 = Clic sur le bon bouton de changement d'oriention (parmis les 4) dans UI worldAndFightBar pour s'orientation vers le monstre\r\n-- 5 = Fermeture UI Fiche combattant\r\n-- 6 = Clic sur le bouton de validation de la répartition dans UI Aptitudes\r\n-- 7 = Clic sur la boussole du bon objectif dans l'UI suivi de quête\r\n-- 8 = Fermeture UI Map Monde\r\n\r\n-- VARIABLE GLOBALE - SCRIPT --\r\n\r\nwidget_visible = {}\r\nwidget_enable = {}\r\nui_tweens = {}\r\nui_particles = {}\r\nui_listener_load = {}\r\nui_listener_unload = {}\r\nui_listener_event = {}\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\nscreenEffectId = nil\r\n\r\n-- VARIABLE GLOBALE - MOBILE CINEMATIQUE & TUTO --\r\n\r\nANM_otomai = {think=\"AnimComp-Special03\", talk=\"AnimComp-Special04-Debut\", show=\"AnimComp-Special05-Debut\", nice=\"AnimComp-Special07\", nope=\"AnimComp-Special08\", lol=\"AnimComp-Special09\", stop_it=\"AnimComp-Special10\", come_here=\"AnimComp-Special01\", wave_hit=\"AnimComp-Special02\", fly=\"AnimStatique-Oiseau\", cast=\"AnimSort-01\", supercast=\"AnimComp-Special11\", attack=\"AnimSort-Cast\", balance=\"AnimComp-Special06\"}\r\nANM_melee = {attack=\"AnimSort-Morsure\", glitch1=\"AnimComp-Glitch01\", glitch2=\"AnimComp-Glitch02\", glitch3=\"AnimComp-Glitch03\", roar=\"AnimComp-Agressif\"}\r\nANM_range = {attack=\"AnimSort-01\", glitch=\"AnimComp-Glitch\", dupli=\"AnimComp-Dupli\"}\r\nANM_boss = {attack1=\"AnimSort-Estoc\", attack2=\"AnimSort-Hrargh\", glitch=\"AnimComp-Glitch\", dupli=\"AnimComp-Dupli\", roar=\"AnimComp-Hurle\", ko = \"AnimKO-SortieOK\", death= \"AnimKO-SortieHS\"}\r\n\r\nNPC_otomai = Mobile.generateClientMobileId()\r\nNPC_otomai_gfx = 181404009\r\nNPC_otomai_particleZ = 10\r\nNPC_otomai_bubbleX = 10\r\nNPC_otomai_bubbleY = 70\r\n\r\nNPC_melee = Mobile.generateClientMobileId()\r\nNPC_meleeB = Mobile.generateClientMobileId()\r\nNPC_melee_gfx = 181404014\r\nNPC_melee_particleZ = 5\r\n\r\nNPC_range = Mobile.generateClientMobileId()\r\nNPC_range_gfx = 181404015\r\nNPC_range_particleZ = 3\r\n\r\nNPC_boss = Mobile.generateClientMobileId()\r\nNPC_boss_gfx = 181404012\r\nNPC_boss_particleZ = 8\r\n\r\nNPC_eni_wakfu = Mobile.generateClientMobileId()\r\nNPC_eni_wakfu_gfx = 181404034\r\nNPC_eni_wakfu_particleZ = 7\r\n\r\nNPC_eni_stasis = Mobile.generateClientMobileId()\r\nNPC_eni_stasis_gfx = 181404013\r\nNPC_eni_stasis_particleZ = 7\r\n\r\n_ACTOR_LIST = {NPC_otomai, NPC_melee, NPC_meleeB, NPC_range, NPC_boss, NPC_eni_wakfu, NPC_eni_stasis}\r\n\r\n-- VARIABLE GLOBALE - PARTICULE CINEMATIQUE & TUTO --\r\n\r\n-- UI TUTO\r\napsArrowBig = {6001069,6001070,6001071,6001072,6001073,6001074,6001075,6001076}\r\napsArrow = {6001061,6001062,6001063,6001064,6001065,6001066,6001067,6001068}\r\napsCenter = {ap=6001090, mp=6001091, wp=6001092, hp=6001093}\r\napsFollowBorder = -1548037644\r\n-- WORLD TUTO\r\napsCell = {white_border=800578, red_border=800579, white_arrow=800576, red_arrow=800577, white=800581, red=800582, show=78900}\r\n-- CINEMATIQUE\r\napsWave = {spawn=800573, wave=800574, hit=800575}\r\napsOtomai = {shield=-1814057071, transform=-1814057072, playershield = -1814057074}\r\napsCristal = {base=71071022, react=800580, shield=71071021}\r\napsBoss = {death=-1814057073}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n    for index, value in ipairs (tab) do\r\n\t\tif isEqual(value, val) then\r\n            return true\r\n        end\r\n    end\r\n\r\n    return false\t\r\nend\r\n\r\n-- FONCTION UI -- Replace le Chat en bas à gauche et le rend indéplaçable/déplaçable\r\nfunction prepareChatUI(movable, chatOffsetX)\r\n\tif not UI.isDialogLoaded(\"chatDialog0\") then return end\r\n\t\r\n\tif (not chatOffsetX) then chatOffsetX = 0 end\r\n\t\r\n\tUI.setPosition(\"chatDialog0\", chatOffsetX, 0)\r\n\tUI.setWindowMovable(\"chatDialog0\", movable)\r\nend\r\n\r\n-- FONCTION UI -- Replace le Suivi de Quête mi-hauteur à gauche et le rend indéplaçable/déplaçable\r\nfunction prepareFollowQuestUI(movable)\r\n    local dialogName = \"\"\r\n    if UI.isDialogLoaded(\"verticalFollowedAchievementsDialog\") then\r\n        dialogName = \"verticalFollowedAchievementsDialog\"\r\n    end\r\n    if UI.isDialogLoaded(\"followedAchievementsDialog\") then\r\n        dialogName = \"followedAchievementsDialog\"\r\n    end\r\n\r\n    if (dialogName == \"\") then\r\n        return\r\n    end\r\n\r\n    local screenH, screenW = UI.getWindowSize()\r\n    local x, y = UI.getPosition(dialogName)\r\n\r\n    UI.setPosition(dialogName, x, screenH / 4)\r\n    UI.setWindowMovable(dialogName, movable)\r\nend\r\n\r\n-- FONCTION UI -- Rend Visible/Invisible certains éléments des interfaces\r\nfunction prepareUI(visible)\r\n  --Interface Boutique & Cadeau\r\n  setWidgetVisible(\"topHudDialog\", \"optionShopButton\", visible)\r\n  setWidgetVisible(\"topHudDialog\", \"giftButton\", visible)\r\n\r\n  --UI sous le Coeur\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"wakfuStasisBar\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"xpBar\", visible)\r\n\r\n  --Boutons hors combat à droite du Coeur\r\n  setWidgetVisible(\"shortcutBarDialog\", \"previousButton\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"nextButton\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseShortcutBar1\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseShortcutBar2\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseShortcutBar3\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseShortcutBar4\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"shortcutBarItemButton\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"shortcutBarSpellButton\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseButtonContainerForTuto1\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseButtonContainerForTuto2\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseButtonContainerForTuto3\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseButtonContainerForTuto4\", visible)\r\n\r\n  --Boutons hors combat à gauche de l'écran - barre d'interfaces\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"firstInterfaceBarBackground\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"secondInterfaceBarBackground\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"extraInterfaceBarDrawerButton\", visible)\r\n\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"fightInfoBtn\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"inventoryButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"buildSheetSetButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"craftButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"questsButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"dungeonButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"cosmeticsButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"tutorialBookButton\", visible)\r\n\r\n  --Boutons hors combat à gauche de l'écran - barre d'interfaces (deuxième barre)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"contactListButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"guildButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"companionsButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"nationButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"battlegroundButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"passportButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"emoteButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"encyclopediaButton\", visible)\r\n\r\n  --Boutons hors combat \"actions rapides\"\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"OverWorldActionsBackground\", visible)\r\n\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"dimensionalBagButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"mapButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"rideMountButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"miniMapButton\", visible)\r\n\r\n  --Boutons en combat à gauche du Coeur\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"FightActionsBackground\", visible)\r\n\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"giveUpButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"hideFightersButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"tacticalModeBtn\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"reportCellBtn\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"fightMarkerBtn\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"lockFightBtn\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"resistanceOverheadBtn\", visible)\r\nend\r\n\r\n-- FONCTION SHORTCUT -- Rend Actif/Inactif certains raccourcis\r\nfunction prepareShortcuts(enabled, shortcutType)\r\n  if not shortcutType or shortcutType == \"WORLD\" then\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.world\", \"enterLeaveBag\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.world\", \"switchHero0\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.world\", \"switchHero1\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.world\", \"switchHero2\")\r\n  end\r\n  if not shortcutType or shortcutType == \"DISPLAY\" then\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"zoomIn\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"zoomOut\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"closeWindows\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"setLODLevel\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"setFightLODLevel\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"showHideNameOverheadsCommand\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"hideFightOccluders\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"alphaMask\")\r\n  end\r\n  if not shortcutType or shortcutType == \"CHAT\" then\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.chat\", \"chat\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.chat\", \"lastContact\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.chat\", \"firstContact\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.chat\", \"autoCompletePlayerName\")\r\n    for bind=1, 9, 1 do\r\n      UI.setShortcutEnabled(enabled, \"shortcutCategory.shortcutBar\", \"bind\" .. toString(bind))\r\n    end\r\n  end\r\n\r\n  if not shortcutType or shortcutType == \"FIGHT\" then\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"fighterTransparency\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"switchTacticalView\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"nextSelectedFighter\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"giveUp\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"lockFight\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"reportCell\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"callHelp\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"displayHpBar\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"resetFightCamera\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"endPlacementAndTurn\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"closeCombatRight\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"closeCombatLeft\")\r\n  end\r\n  if not shortcutType or shortcutType == \"INTERFACE\" then\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"minimap\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"contactList\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"companionManagement\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"guild\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"craft\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"dungeonList\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"achievements\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"quests\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"emotes\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"ecosystem\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"climate\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"nation\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"partySearch\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"passport\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"almanax\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"tutorialBook\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"switchToDirectAttackCommand\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"map\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"spellsInventory\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"inventory\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"characterBook\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"osamodasSymbiot\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"shortcutBar0\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"shortcutBar1\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"shortcutBar2\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"shortcutBar3\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"additionalShortcutBar0\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"additionalShortcutBar1\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"additionalShortcutBar2\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"additionalShortcutBar3\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"changeShortcutBarType\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"downscaling\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"rewards\")\r\n\tUI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"battlegroundList\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"aptitudes\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"presets\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"encyclopedia\")\r\n  end\r\n\r\n  -- On ne bloque pas les raccourcis de sorts finalement\r\n--   if not shortcutType or shortcutType == \"SHORTCUTBAR\" then\r\n--     for bar=0,3, 1 do\r\n--       for slot=0, 9, 1 do\r\n--         UI.setShortcutEnabled(enabled, \"shortcutCategory.shortcutBar\", \"shortcut\" .. toString(bar) .. toString(slot))\r\n--       end\r\n--     end\r\n--   end\r\nend\r\n\r\n-- FONCTION UI -- Rend Visible/Invisible un élément d'une interface\r\nfunction setWidgetVisible(dialogName, widgetName, visible)\r\n  if not UI.isDialogLoaded(dialogName) then return end\r\n\r\n  UI.setWidgetVisibility(dialogName, widgetName, visible)\r\n  table.insert(widget_visible, { name = dialogName, id = widgetName, state = visible })\r\nend\r\n\r\nfunction clearWidgetVisible()\r\n  local str = \"\"\r\n  for i=#widget_visible, 1, -1 do\r\n    str = str .. toString(widget_visible[i].name) .. \"@\" .. toString(widget_visible[i].id) .. \";\"\r\n    UI.setWidgetVisibility(widget_visible[i].name, widget_visible[i].id, true)\r\n  end\r\n\r\n  widget_visible = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearWidgetVisible\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Rend Actif/Inactif un élément d'une interface\r\nfunction setWidgetEnable(dialogName, widgetName, enable)\r\n  if not UI.isDialogLoaded(dialogName) then return end\r\n\r\n  UI.setWidgetEnabled(dialogName, widgetName, enable)\r\n  table.insert(widget_enable, {name = dialogName, id = widgetName, state = enable})\r\nend\r\n\r\nfunction clearWidgetEnable()\r\n  local str = \"\"\r\n  for i=#widget_enable, 1, -1 do\r\n    str = str .. toString(widget_enable[i].name) .. \"@\" .. toString(widget_enable[i].id) .. \";\"\r\n    UI.setWidgetEnabled(widget_enable[i].name, widget_enable[i].id, true)\r\n  end\r\n\r\n  widget_enable = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearWidgetEnable\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Ajoute/Retire une TweenParticle à un élément d'une interface\r\nfunction setUIColorTween(dialogName, widgetName, duration, loop, r1, g1, b1, a1, r2, g2, b2, a2)\r\n  if not UI.isDialogLoaded(dialogName) then return end\r\n\r\n  UI.addColorTween(dialogName, widgetName, duration, loop, r1, g1, b1, a1, r2, g2, b2, a2)\r\n  table.insert(ui_tweens, {name = dialogName, id = widgetName})\r\nend\r\n\r\nfunction clearUIColorTweens(dialogName, widgetName)\r\n  local str = \"\"\r\n  for i=#ui_tweens, 1, -1 do\r\n    if ((not dialogName) or (dialogName == ui_tweens[i].name)) and ((not widgetName) or (widgetName == ui_tweens[i].id)) then\r\n      str = str .. toString(ui_tweens[i].name) .. \"@\" .. toString(ui_tweens[i].id) .. \";\"\r\n      UI.removeColorTween(ui_tweens[i].name, ui_tweens[i].id)\r\n      table.remove(ui_tweens, i)\r\n    end\r\n  end\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearUIColorTweens\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Ajoute/Retire une Particle à un élément d'une interface\r\nfunction setUIParticle(dialogName, widgetName, apsFileName, x, y, alignment, level)\r\n  if not UI.isDialogLoaded(dialogName) then return end\r\n\r\n  local particleId = UI.addParticle(dialogName, widgetName, apsFileName, x, y, alignment, level)\r\n  table.insert(ui_particles, {name = dialogName, id = widgetName})\r\n\r\n  return particleId\r\nend\r\n\r\nfunction setUIParticleBorder(dialogName, widgetName, apsFileName, x, y, alignment, level, speed)\r\n  if not UI.isDialogLoaded(dialogName) then return end\r\n\r\n  local particleId = UI.addParticleToBorder(dialogName, widgetName, apsFileName, x, y, alignment, level, speed)\r\n  table.insert(ui_particles, {name = dialogName, id = widgetName})\r\n\r\n  return particleId\r\nend\r\n\r\nfunction clearUIParticles(dialogName, widgetName)\r\n  local str = \"\"\r\n  for i=#ui_particles, 1, -1 do\r\n    if ((not dialogName) or (dialogName == ui_particles[i].name)) and ((not widgetName) or (widgetName == ui_particles[i].id)) then\r\n      str = str .. toString(ui_particles[i].name) .. \"@\" .. toString(ui_particles[i].id) .. \";\"\r\n      UI.clearParticles(ui_particles[i].name, ui_particles[i].id)\r\n      table.remove(ui_particles, i)\r\n    end\r\n  end\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearUIParticles\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Enregistre/Supprime un callback à l'ouverture d'une interface\r\nfunction addDialogLoadListener(dialog, funcName, ...)\r\n  UI.addDialogLoadedListener(dialog, funcName, unpack(arg))\r\n  table.insert(ui_listener_load,  dialog)\r\nend\r\n\r\nfunction clearDialogLoadListener(dialogName)\r\n  local str = \"\"\r\n  for i=#ui_listener_load, 1, -1 do\r\n    if (not dialogName) or (dialogName == ui_listener_load[i]) then\r\n      str = str .. toString(ui_listener_load[i]) .. \";\"\r\n      UI.removeDialogLoadedListener(ui_listener_load[i])\r\n      table.remove(ui_listener_load, i)\r\n    end\r\n  end\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearDialogLoadListener\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Enregistre/Supprime un callback à la fermeture d'une interface\r\nfunction addDialogUnloadListener(dialog, funcName, ...)\r\n  UI.addDialogUnloadedListener(dialog, funcName, unpack(arg))\r\n  table.insert(ui_listener_unload, dialog)\r\nend\r\n\r\nfunction clearDialogUnloadListener(dialogName)\r\n  local str = \"\"\r\n  for i=#ui_listener_unload, 1, -1 do\r\n    if (not dialogName) or (dialogName == ui_listener_unload[i]) then\r\n      str = str .. toString(ui_listener_unload[i]) .. \";\"\r\n      UI.removeDialogUnloadedListener(ui_listener_unload[i])\r\n      table.remove(ui_listener_unload, i)\r\n    end\r\n  end\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearDialogUnloadListener\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Enregistre/Supprime un callback sur un élément d'une interface\r\nfunction addDialogEventListener(dialog, id, eventType, funcName, ...)\r\n  if not UI.isDialogLoaded(dialog) then return end\r\n\r\n  UI.addEventListener(dialog, id, eventType, funcName, unpack(arg))\r\n  table.insert(ui_listener_event, {dialog=dialog, id=id, eventType=eventType, funcName=funcName})\r\nend\r\n\r\nfunction clearDialogEventListener(dialogName)\r\n  local str = \"\"\r\n  for i=#ui_listener_event, 1, -1 do\r\n    if (not dialogName) or (dialogName == ui_listener_event[i].dialog) then\r\n      str = str .. toString(ui_listener_event[i].dialog) .. \"@\" .. toString(ui_listener_event[i].id) .. \";\"\r\n      UI.removeEventListener(ui_listener_event[i].dialog, ui_listener_event[i].id, ui_listener_event[i].eventType, ui_listener_event[i].funcName)\r\n      table.remove(ui_listener_event, i)\r\n    end\r\n  end\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearDialogEventListener\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y , z, ...)\r\n  local particleId = Particle.addParticleSystem(particleFileId, x, y , z, unpack(arg))\r\n  table.insert(world_particles, particleId)\r\n\r\n  return particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n  local particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n  table.insert(world_particles, particleId)\r\n\r\n  return particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n  local str = \"\"\r\n  for i=#world_particles, 1, -1 do\r\n    str = str .. toString(world_particles[i]) .. \";\"\r\n    Particle.removeParticleSystem(world_particles[i])\r\n  end\r\n\r\n  world_particles = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n  BubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n  if isLower(mobileId, 0) then\r\n    BubbleText.setCharacterSpeak(mobileId, text)\r\n  else\r\n    if (not offsetY) then\r\n      local height = Mobile.getMobileHeight(mobileId)\r\n      if (not height) then height = 6 end\r\n\r\n      offsetY = height * 10\r\n    end\r\n\r\n    if (not offsetX) then offsetX = 0 end\r\n    if (not infiniteDuration) then infiniteDuration = false end\r\n\r\n    BubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n    UI.writeLocalisedInChat(text)\r\n  end\r\n\r\n  if (not tContains(bubbles, mobileId)) then\r\n    table.insert(bubbles, mobileId)\r\n  end\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n  local str = \"\"\r\n  for i = #bubbles, 1, -1 do\r\n    if (not mobileId) then\r\n      str = str .. toString(bubbles[i]) .. \";\"\r\n      BubbleText.closeBubbleAttachedTo(bubbles[i])\r\n    elseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n      str = str .. toString(bubbles[i]) .. \";\"\r\n      BubbleText.closeBubbleAttachedTo(bubbles[i])\r\n      table.remove(bubbles, i)\r\n    end\r\n  end\r\n\r\n  if (not mobileId) then bubbles = {} end\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n  local compassId = UI.addCompass(\"compass\", x, y, z)\r\n  table.insert(compasses, compassId)\r\n\r\n  return compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n  local str = \"\"\r\n  for i=#compasses, 1, -1 do\r\n    str = str .. toString(compasses[i]) .. \";\"\r\n    UI.removeCompass(compasses[i])\r\n  end\r\n\r\n  compasses = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height)\r\n  local mobileId = Mobile.generateClientMobileId()\r\n  Actor.createActor(mobileId, spriteName, worldX, worldY, worldZ, availableDirection)\r\n\r\n  if (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n  if (height) then Actor.setActorHeight(mobileId, height) end\r\n\r\n  table.insert(actors, mobileId)\r\n\r\n  return mobileId\r\nend\r\n\r\nfunction clearActors()\r\n  local str = \"\"\r\n  for i = #actors, 1, -1 do\r\n    str = str .. toString(actors[i]) .. \";\"\r\n    Actor.deleteActor(actors[i])\r\n  end\r\n\r\n  actors = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n  local taskId = invoke(delay, count, funcName, unpack(arg))\r\n  table.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n  local str = \"\"\r\n  for i=#invoke_tasks, 1, -1 do\r\n    str = str .. toString(invoke_tasks[i]) .. \";\"\r\n    interrupt(invoke_tasks[i])\r\n    desinvoke(invoke_tasks[i])\r\n  end\r\n\r\n  invoke_tasks = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n  invoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n  local taskId = setInterval(delay, funcName, unpack(arg))\r\n  table.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n  local str = \"\"\r\n  for i=#interval_tasks, 1, -1 do\r\n    str = str .. toString(interval_tasks[i]) .. \";\"\r\n    interrupt(interval_tasks[i])\r\n    desinvoke(interval_tasks[i])\r\n  end\r\n\r\n  interval_tasks = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n  if (_DEBUG) then trace(\"startCinematicContext\") end\r\n\r\n  UI.manageFrame(\"World\", false)\r\n  UI.closeMRU()\r\n  UI.closeAllBags()\r\n  UI.setUIVisible(false)\r\n  UI.displayWideScreenBand(true)\r\n  Camera.setUserZoomLocked(true)\r\n\r\n  if (cameraMobileId ~= nil)  then\r\n    Camera.setMoveSpeedFactor(10000)\r\n    Camera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n  end\r\n\r\n  if (zoomFactor ~= nil)  then\r\n    Camera.setZoomFactor(zoomFactor)\r\n  end\r\n\r\n  if (musicId ~= nil)  then\r\n    Sound.playForcedMusic(musicId)\r\n  end\r\n\r\n  if (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\nfunction skipCinematic()\r\n  local player = Context.getLeaderId()\r\n\r\n  for x = 1, #_ACTOR_LIST do\r\n    Actor.deleteActor(_ACTOR_LIST[x])\r\n  end\r\n\r\n  UI.hideButton()\r\n  clearALL()\r\n  stopCinematicContext(1, player, true)\r\n  Mobile.setMobileVisible(player, true)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n  if (_DEBUG) then trace(\"stopCinematicContext\") end\r\n\r\n  UI.displayWideScreenBand(false)\r\n  UI.setUIVisible(true)\r\n  Camera.setUserZoomLocked(false)\r\n  UI.manageFrame(\"World\", true)\r\n\r\n  Camera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n  Camera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n  if (zoomFactor ~= nil) then\r\n    Camera.setZoomFactor(zoomFactor)\r\n  end\r\n\r\n  if (cameraMobileId ~= nil) then\r\n    Camera.attachCameraToMobile(cameraMobileId)\r\n  end\r\n\r\n  if (stopMusic) then\r\n    Sound.stopForcedMusic()\r\n  end\r\n\r\n  if (_DEBUG) then\r\n    UI.hideButton()\r\n  end\r\n\r\n  --TRIGGER\r\n  Server.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Affiche/Masque une texture à l'écran\r\nfunction displayScreenEffect(enable, fadeInDur, alphaDur, fadeOutDur, r, g, b, alpha)\r\n  if (_DEBUG) then trace(\"displayScreenEffect\") end\r\n\r\n  if not enable and screenEffectId ~= nil  then\r\n    --On retire le blackScreen\r\n    Effect.stopEffect(screenEffectId)\r\n  else\r\n    --On affiche un blackScreen à l'entrée dans l'instance le temps qu'elle soit complètement chargée\r\n    screenEffectId = Effect.createFullScreenSprite(fadeInDur, alphaDur, fadeOutDur, r, g, b, alpha)\r\n  end\r\nend\r\n\r\n-- FONCTION NETTOYAGE --\r\nfunction clearALL()\r\n  clearIntervalTasks()\r\n  clearInvokeTasks()\r\n  clearBubbles()\r\n  clearUIColorTweens()\r\n  clearUIParticles()\r\n  clearWorldParticles()\r\n  clearCompasses()\r\n  clearActors()\r\n\r\n  Focus.display(false)\r\n  UI.unloadTutorialDialog()\r\nend\r\n\r\n-- FONCTION NETTOYAGE --\r\nfunction clearUI(dialogName)\r\n  clearUIColorTweens(dialogName)\r\n  clearUIParticles(dialogName)\r\nend\r\n\r\n-- FONCTION NETTOYAGE --\r\nfunction clearListener(dialogName)\r\n  clearDialogLoadListener(dialogName)\r\n  clearDialogUnloadListener(dialogName)\r\n  clearDialogEventListener(dialogName)\r\nend\r\n\r\n-- Fonction mode démo\r\n-- function addButton()\r\n-- \tinvoke(2000, 1, \"UI.displayButton\", false, \"scenario.endKinematic.confirmEscape\", \"lyongameshow.vampyro.rules.display\", \"displayFightRules\")\r\n-- end \r\n\r\nfunction displayFightRules()\r\n--\tUI.loadTutorialDialog(\"japan.expo.2022\",\"japanexpo.fight.title\",\"japanexpo.fight.desc\")\r\n--\taddButton()\r\nend\r\n\r\nfunction onEnterInstance()  \r\n-- addButton()\r\n \t\r\n   UI.activateFollowAchievement(false)\r\n   prepareUI(false)\r\n   prepareShortcuts(false)\r\n   prepareShortcuts(true, \"DISPLAY\")\r\n   prepareShortcuts(true, \"CHAT\")\r\n   prepareShortcuts(true, \"FIGHT\")\r\n   prepareShortcuts(true, \"SHORTCUTBAR\")\r\n\r\n  UI.setShortcutEnabled(true, \"shortcutCategory.interface\", \"emotes\")\r\n  UI.setShortcutEnabled(false, \"shortcutCategory.interface\", \"switchToDirectAttackCommand\")\r\n  UI.setShortcutEnabled(false, \"shortcutCategory.interface\", \"spellsInventory\")\r\n  UI.setShortcutEnabled(false, \"shortcutCategory.interface\", \"inventory\")\r\n  UI.setShortcutEnabled(false, \"shortcutCategory.interface\", \"osamodasSymbiot\")\r\n  UI.setShortcutEnabled(false, \"shortcutCategory.interface\", \"shortcutBar0\")\r\n  UI.setShortcutEnabled(false, \"shortcutCategory.interface\", \"shortcutBar1\")\r\n  UI.setShortcutEnabled(false, \"shortcutCategory.interface\", \"shortcutBar2\")\r\n  UI.setShortcutEnabled(false, \"shortcutCategory.interface\", \"shortcutBar3\")\r\n  UI.setShortcutEnabled(false, \"shortcutCategory.interface\", \"additionalShortcutBar0\")\r\n  UI.setShortcutEnabled(false, \"shortcutCategory.interface\", \"additionalShortcutBar1\")\r\n  UI.setShortcutEnabled(false, \"shortcutCategory.interface\", \"additionalShortcutBar2\")\r\n  UI.setShortcutEnabled(false, \"shortcutCategory.interface\", \"additionalShortcutBar3\")\r\n  UI.setShortcutEnabled(false, \"shortcutCategory.interface\", \"changeShortcutBarType\")\r\n  \r\n    --Boutons hors combat à droite du Coeur\r\n  setWidgetVisible(\"shortcutBarDialog\", \"previousButton\", true)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"nextButton\", true)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"addExtraBarButton\", true)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"shortcutModeButton\", true)\r\n  \r\n -- Boutons hors combat à gauche du Coeur\r\n\r\n  --Boutons en combat à gauche du Coeur\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"giveUpButton\", true)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"hideFightersButton\", true)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"reportCellBtn\", true)\r\n end\n\n-- [INIT] Variables\n-- \nfunction event_2547_22477()\n    \nend\n\n-- [EVENT] Le joueur entre dans l'instance - Mode découverte\n-- \nfunction event_2547_22474()\n    local playerId = Context.getLeaderId()\r\n    \r\n    Mobile.setMobileVisible(playerId, true)\r\n    \r\n    function onStasisDungeonDialogLoaded()\r\n        clearUI()\r\n        clearListener()\r\n            \r\n        UI.setWidgetEnabled(\"stasisDungeonDialog\", \"modulationContainer\", false)\r\n        UI.setWidgetEnabled(\"stasisDungeonDialog\", \"modulationCheckBox\", false)\r\n        UI.setWidgetEnabled(\"stasisDungeonDialog\", \"difficultyContainer\", false)\r\n        UI.setWidgetEnabled(\"stasisDungeonDialog\", \"difficultyComboBox\", false)\r\n        UI.setWidgetEnabled(\"stasisDungeonDialog\", \"difficultyComboBoxContainer\", false)\r\n        UI.setWidgetEnabled(\"stasisDungeonDialog\", \"dungeonOptionsContainer\", false)\r\n        \r\n        UI.setWidgetVisibility(\"stasisDungeonDialog\", \"modulationContainer\", false)\r\n        UI.setWidgetVisibility(\"stasisDungeonDialog\", \"modulationCheckBox\", false)\r\n        UI.setWidgetVisibility(\"stasisDungeonDialog\", \"difficultyContainer\", false)\r\n        UI.setWidgetVisibility(\"stasisDungeonDialog\", \"difficultyComboBox\", false)\r\n        UI.setWidgetVisibility(\"stasisDungeonDialog\", \"difficultyComboBoxContainer\", false)\r\n        UI.setWidgetVisibility(\"stasisDungeonDialog\", \"dungeonOptionsContainer\", false)\r\n            \r\n    -- LISTENER\r\n       addDialogUnloadListener(\"stasisDungeonDialog\", \"init\")\r\n    end\r\n            \r\n    function init()\r\n       clearUI()\r\n       clearListener()\r\n            \r\n    -- LISTENER\r\n       addDialogLoadListener(\"stasisDungeonDialog\", \"onStasisDungeonDialogLoaded\")\r\n    end\r\n       \r\n    onEnterInstance()\r\n    init()\nend\n\n-- [EVENT] Le joueur entre dans l'instance - Mode normal\n-- \nfunction event_2547_22475()\n    local playerId = Context.getLeaderId()\r\n    \r\n    Mobile.setMobileVisible(playerId, true)\r\n    \r\n    function onStasisDungeonDialogLoaded()\r\n        clearUI()\r\n        clearListener()\r\n            \r\n        UI.setWidgetEnabled(\"stasisDungeonDialog\", \"modulationContainer\", false)\r\n        UI.setWidgetEnabled(\"stasisDungeonDialog\", \"modulationCheckBox\", false)\r\n        UI.setWidgetEnabled(\"stasisDungeonDialog\", \"difficultyContainer\", false)\r\n        UI.setWidgetEnabled(\"stasisDungeonDialog\", \"difficultyComboBox\", false)\r\n        UI.setWidgetEnabled(\"stasisDungeonDialog\", \"difficultyComboBoxContainer\", false)\r\n        UI.setWidgetEnabled(\"stasisDungeonDialog\", \"dungeonOptionsContainer\", false)\r\n        \r\n        UI.setWidgetVisibility(\"stasisDungeonDialog\", \"modulationContainer\", false)\r\n        UI.setWidgetVisibility(\"stasisDungeonDialog\", \"modulationCheckBox\", false)\r\n        UI.setWidgetVisibility(\"stasisDungeonDialog\", \"difficultyContainer\", false)\r\n        UI.setWidgetVisibility(\"stasisDungeonDialog\", \"difficultyComboBox\", false)\r\n        UI.setWidgetVisibility(\"stasisDungeonDialog\", \"difficultyComboBoxContainer\", false)\r\n        UI.setWidgetVisibility(\"stasisDungeonDialog\", \"dungeonOptionsContainer\", false)\r\n            \r\n    -- LISTENER\r\n       addDialogUnloadListener(\"stasisDungeonDialog\", \"init\")\r\n    end\r\n            \r\n    function init()\r\n       clearUI()\r\n       clearListener()\r\n            \r\n    -- LISTENER\r\n       addDialogLoadListener(\"stasisDungeonDialog\", \"onStasisDungeonDialogLoaded\")\r\n    end\r\n       \r\n    onEnterInstance()\r\n    init()\nend\n\n-- [EVENT] Le joueur entre dans l'instance - HUB\n-- \nfunction event_2547_22476()\n    local playerId = Context.getLeaderId()\r\n    \r\n    Mobile.setMobileVisible(playerId, false)\r\n    \r\n    function onStasisDungeonDialogLoaded()\r\n        clearUI()\r\n        clearListener()\r\n            \r\n        UI.setWidgetEnabled(\"stasisDungeonDialog\", \"modulationContainer\", false)\r\n        UI.setWidgetEnabled(\"stasisDungeonDialog\", \"modulationCheckBox\", false)\r\n        UI.setWidgetEnabled(\"stasisDungeonDialog\", \"difficultyContainer\", false)\r\n        UI.setWidgetEnabled(\"stasisDungeonDialog\", \"difficultyComboBox\", false)\r\n        UI.setWidgetEnabled(\"stasisDungeonDialog\", \"difficultyComboBoxContainer\", false)\r\n        UI.setWidgetEnabled(\"stasisDungeonDialog\", \"dungeonOptionsContainer\", false)\r\n        \r\n        UI.setWidgetVisibility(\"stasisDungeonDialog\", \"modulationContainer\", false)\r\n        UI.setWidgetVisibility(\"stasisDungeonDialog\", \"modulationCheckBox\", false)\r\n        UI.setWidgetVisibility(\"stasisDungeonDialog\", \"difficultyContainer\", false)\r\n        UI.setWidgetVisibility(\"stasisDungeonDialog\", \"difficultyComboBox\", false)\r\n        UI.setWidgetVisibility(\"stasisDungeonDialog\", \"difficultyComboBoxContainer\", false)\r\n        UI.setWidgetVisibility(\"stasisDungeonDialog\", \"dungeonOptionsContainer\", false)\r\n            \r\n    -- LISTENER\r\n       addDialogUnloadListener(\"stasisDungeonDialog\", \"init\")\r\n    end\r\n            \r\n    function init()\r\n       clearUI()\r\n       clearListener()\r\n            \r\n    -- LISTENER\r\n       addDialogLoadListener(\"stasisDungeonDialog\", \"onStasisDungeonDialogLoaded\")\r\n    end\r\n       \r\n    onEnterInstance()\r\n    init()\nend\n\n-- FIGHT_ENTER_ACTION_PHASE - variable globale\n-- \nfunction event_2547_22478(wave, difficulty)\n    updateFightInfo(wave, difficulty, true)\nend\n\n-- NEW_MONSTER_WAVE - Compteur de vagues\n-- \nfunction event_2547_22479()\n    \nend\n\n-- FIGHT_ENDED_IN_CLIENT_EVENT - Compteur de combats\n-- \nfunction event_2547_22480()\n    \nend\n\n-- ADMIN - on affiche les compteurs (ATTENTION - reset les compteurs)\n-- \nfunction event_2547_22481(waveCount, victoryCount)\n    trace(\"waveCount :\" .. waveCount)\r\n    trace(\"victoryCount :\" .. waveCount)\nend\n\n","functions":["tContains","prepareChatUI","prepareFollowQuestUI","prepareUI","prepareShortcuts","setWidgetVisible","clearWidgetVisible","setWidgetEnable","clearWidgetEnable","setUIColorTween","clearUIColorTweens","setUIParticle","setUIParticleBorder","clearUIParticles","addDialogLoadListener","clearDialogLoadListener","addDialogUnloadListener","clearDialogUnloadListener","addDialogEventListener","clearDialogEventListener","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","bubble","clearBubbles","setCompass","clearCompasses","createActor","clearActors","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","startCinematicContext","skipCinematic","stopCinematicContext","displayScreenEffect","clearALL","clearUI","clearListener","addButton","displayFightRules","onEnterInstance","event_2547_22477","event_2547_22474","onStasisDungeonDialogLoaded","init","event_2547_22475","onStasisDungeonDialogLoaded","init","event_2547_22476","onStasisDungeonDialogLoaded","init","event_2547_22478","event_2547_22479","event_2547_22480","event_2547_22481"],"quest_calls":["UI.activateFollowAchievement(false)\r"],"dialogue_calls":[]},"scenario/2548.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\n\n-- [INIT] Variables\n-- \nfunction event_2548_22487()\n    \nend\n\n-- ENTER_INSTANCE\n-- \nfunction event_2548_22488()\n    \nend\n\n-- ENTER_INSTANCE - 1 - 0 - Cinématique Grougaloragran\n-- \nfunction event_2548_22489()\n    \nend\n\n-- DIALOG_EXECUTED - 2 - 0 - Lancement du combat\n-- \nfunction event_2548_22531()\n    \nend\n\n-- FIGHTER_ENDED_IN_CLIENT_EVENT - 3 - 0 - Cinématique\n-- \nfunction event_2548_22532()\n    local playerId = Context.getLeaderId()\r\n    local grougalId = createActor(1111505458, -17, 0, 0, 4, 1, 9)\r\n    \r\n    Mobile.setMobilePosition(playerId, -12, 0, 2)\r\n    Mobile.setMobileDirection(playerId, 5)\r\n    \t\r\n    function customSkip()\r\n    \tUI.displayWideScreenBand(true, 25, 300)\r\n    \tskipCinematic(22532)\r\n    end\r\n    \t\r\n    startCinematicContext(1.7, playerId)\r\n    \r\n    invoke_custom(00030, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimKO-Debut\")\r\n    invoke_custom(00001, 1, \"UI.displayWideScreenBand\", true, 100, 100)\r\n    invoke_custom(00800, 1, \"UI.displayWideScreenBand\", true, 20, 1000)\r\n    invoke_custom(01000, 1, \"Camera.setMoveSpeedFactor\", 0.1)\r\n    invoke_custom(01400, 1, \"Camera.setZoomSpeedFactor\", 0.1)\r\n    \r\n    -- \"C'est dingue d'avoir autant de chance !\"\r\n    invoke_custom(02500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimKO-SortieOK\")\r\n    invoke_custom(01500, 1, \"bubble\", playerId, \"quest.rii.05.00\")\r\n    invoke_custom(04000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Non\")\r\n    invoke_custom(04500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Ne va pas croire que j'ai donné mon maximum. Je t'ai laissé gagner...\"\r\n    invoke_custom(06500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Pointer\")\r\n    invoke_custom(05000, 1, \"bubble\", playerId, \"quest.rii.05.01\")\r\n    invoke_custom(10000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(10500, 1, \"Camera.setCamera\", 1.3, -14, 0, 2)\r\n    \r\n    -- \"Il suffit, jeune incarné{[1*]?e:}.\"\r\n    invoke_custom(10500, 1, \"Mobile.setMobileAnimation\", grougalId, \"AnimComp-Parler02\")\r\n    invoke_custom(10500, 1, \"bubble\", grougalId, \"quest.rii.05.02\")\r\n    invoke_custom(13000, 1, \"clearBubbles\", grougalId)\r\n    \r\n    -- \"Tes pouvoirs ne se sont pas encore éveillés à leur plein potentiel. À vrai dire, tu en es encore loin...\"\r\n    invoke_custom(13500, 1, \"Mobile.setMobileAnimation\", grougalId, \"AnimComp-Parler01\")\r\n    invoke_custom(13500, 1, \"bubble\", grougalId, \"quest.rii.05.03\")\r\n    invoke_custom(19500, 1, \"clearBubbles\", grougalId)\r\n    \r\n    -- \"Comment ça ?\"\r\n    invoke_custom(20000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(20000, 1, \"bubble\", playerId, \"quest.rii.05.04\")\r\n    invoke_custom(22500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Grougaloragran comprend désormais que tu as un coeur pur.\"\r\n    invoke_custom(23000, 1, \"Mobile.setMobileAnimation\", grougalId, \"AnimComp-Ricane\")\r\n    invoke_custom(23000, 1, \"bubble\", grougalId, \"quest.rii.05.05\")\r\n    invoke_custom(26500, 1, \"clearBubbles\", grougalId)\r\n    \r\n    -- \"Néanmoins, il faut que tu partes de cette île pour aller explorer l'endroit qu'on appelle le \"Monde des Douze\".\"\r\n    invoke_custom(27000, 1, \"Mobile.setMobileAnimation\", grougalId, \"AnimComp-Parler01\")\r\n    invoke_custom(27000, 1, \"bubble\", grougalId, \"quest.rii.05.07\")\r\n    invoke_custom(34000, 1, \"clearBubbles\", grougalId)\r\n    \r\n    -- \"Le Monde des Douze...\"\r\n    invoke_custom(34500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmoteMarket-HausseEpaules\")\r\n    invoke_custom(34500, 1, \"bubble\", playerId, \"quest.rii.05.08\")\r\n    invoke_custom(37000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Mets-toi en route, jeune incarné{[1*]?e:}. Grougaloragran doit rentrer veiller sur certaines choses...\"\r\n    invoke_custom(37500, 1, \"Mobile.setMobileAnimation\", grougalId, \"AnimComp-Parler02\")\r\n    invoke_custom(37500, 1, \"bubble\", grougalId, \"quest.rii.05.09\")\r\n    invoke_custom(43000, 1, \"clearBubbles\", grougalId)\r\n    \r\n    invoke_custom(44000, 1, \"Mobile.setMobileAnimation\", grougalId, \"AnimBond-Debut-Combat\")\r\n    invoke_custom(45500, 1, \"Mobile.setMobileVisible\", grougalId, false)\r\n    \r\n    -- \"**Quel être étrange. Je me demande si je le recroiserai un jour...\"\r\n    invoke_custom(46500, 1, \"Camera.setCamera\", 1.3, -12, 0, 0)\r\n    invoke_custom(46500, 1, \"Mobile.setMobileDirection\", playerId, 1)\r\n    invoke_custom(46500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(46500, 1, \"bubble\", playerId, \"quest.rii.05.10\")\r\n    invoke_custom(51000, 1, \"clearBubbles\", playerId)\r\n    invoke_custom(52000, 1, \"Mobile.moveMobile\", playerId, 0, 0, 0)\r\n    \r\n    invoke_custom(53500, 1, \"UI.displayWideScreenBand\", true, 100, 1000)\r\n    \r\n    invoke_custom(56000, 1, \"customSkip\")\nend\n\n-- CLIENT_TRIGGERED_EVENT - Validation achievement & Téléportation vers Rii (ACH 5146 OBJ 10584)\n-- \nfunction event_2548_22535()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_2548_22487","event_2548_22488","event_2548_22489","event_2548_22531","event_2548_22532","customSkip","event_2548_22535"],"quest_calls":[],"dialogue_calls":[]},"scenario/2549.lua":{"source":"\n\n-- [EVENT] Iop - Visuel animations de sorts à l'épée\n-- \nfunction event_2549_22498()\n    \nend\n\n-- [EVENT] Iop - Retrait du visuel animations de sorts à l'épée\n-- \nfunction event_2549_22499()\n    \nend\n\n-- [EVENT] Crâ - Visuel animations de sorts à l'arbalète\n-- \nfunction event_2549_24429()\n    \nend\n\n-- [EVENT] Crâ - Retrait du visuel animations de sorts à l'épée\n-- \nfunction event_2549_24430()\n    \nend\n\n","functions":["event_2549_22498","event_2549_22499","event_2549_24429","event_2549_24430"],"quest_calls":[],"dialogue_calls":[]},"scenario/2550.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\nbubbleSteleInfoId = 0\r\n\r\nfunction openDoor()\r\n\tInteractiveElement.setAnimation(34824, \"AnimTrans_1_0\")\r\nend\r\n\r\nfunction closeSteleInfo()\r\n\tif (bubbleSteleInfoId ~= nil  and bubbleSteleInfoId ~= 0) then BubbleText.close(bubbleSteleInfoId) end\r\nend\r\n\r\nfunction onSteleInfoClosed()\r\n\tif (bubbleSteleInfoId ~= nil  and bubbleSteleInfoId ~= 0) then bubbleSteleInfoId = 0 end\r\nend\r\n\r\nfunction updateSteleInfo(stateInfoId, forceDisplayUI)\r\n\r\n\tif (bubbleSteleInfoId == 0) then\r\n\t\tbubbleSteleInfoId = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_WEST\", 0, -60, false, 2147483647, true, \"interactiveBubbleDialog5\", 30000, 25000, \"onSteleInfoClosed\")\r\n\tend\r\n\r\n\tBubbleText.setText(bubbleSteleInfoId, stateInfoId)\r\n\t\r\n\tif (forceDisplayUI) then BubbleText.show(bubbleSteleInfoId) end\r\nend\n\n-- [INIT] Variables & Constantes\n-- \nfunction event_2550_22548()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2550_22549()\n    openDoor()\nend\n\n-- INTERACTIVE_ELEMENT_ACTIVATION - Ouverture de la porte\n-- \nfunction event_2550_22550()\n    trace(\"OUVERTURE DE LA PORTE\")\r\n    \r\n    openDoor()\nend\n\n-- MONSTER_ACTION_EVENT - Lancement du combat\n-- \nfunction event_2550_22551()\n    \nend\n\n-- [FIGHT] Fin du combat - Reset les stèles\n-- \nfunction event_2550_22554()\n    \nend\n\n-- [STELE] Le joueur examine une stèle\n-- \nfunction event_2550_22555(steleCount, steleStateId)\n    local steleCount = toLong(steleCount)\r\n    local steleStateId = toLong(steleStateId)\r\n    \r\n    if (steleCount == 0) then\r\n    UI.openRewardsDialog(\"stele.description.tour\")\r\n    UI.addReward(22759)\r\n    UI.addReward(17321)\r\n    UI.addReward(27083, \"stele.reward.stasis.21\")\r\n    \r\n    elseif (steleCount == 1) then\r\n    UI.openRewardsDialog(\"stele.description.tour\")\r\n    UI.addReward(22758)\r\n    UI.addReward(22763)\r\n    UI.addReward(27083, \"stele.reward.stasis.21\")\r\n    \r\n    elseif (steleCount == 2) then\r\n    UI.openRewardsDialog(\"stele.description.tour\")\r\n    UI.addReward(17317)\r\n    UI.addReward(17322, \"stele.reward.stasis.21\")\r\n    UI.addReward(27083, \"stele.reward.stasis.21\")\r\n    \r\n    elseif (steleCount == 3) then\r\n    UI.openRewardsDialog(\"stele.description.tour\")\r\n    UI.addReward(17318)\r\n    UI.addReward(17332, \"stele.reward.stasis.21\")\r\n    UI.addReward(27083, \"stele.reward.stasis.21\")\r\n    \r\n    \r\n    else\r\n    \r\n    end\r\n    \r\n    local stateInfoId = \"stele.state.description.\" .. toString(steleStateId)\r\n    \r\n    updateSteleInfo(stateInfoId, true)\nend\n\n-- [STELE] Le joueur active une stèle\n-- \nfunction event_2550_22556(steleCount, steleStateId)\n    local steleCount = toLong(steleCount)\r\n    local steleStateId = toLong(steleStateId)\r\n    \r\n    if (steleCount == 1) then\r\n    UI.openRewardsDialog(\"stele.description.tour\")\r\n    UI.addReward(22759)\r\n    UI.addReward(17321)\r\n    UI.addReward(27083, \"stele.reward.stasis.21\")\r\n    \r\n    elseif (steleCount == 2) then\r\n    UI.openRewardsDialog(\"stele.description.tour\")\r\n    UI.addReward(22758)\r\n    UI.addReward(22763)\r\n    UI.addReward(27083, \"stele.reward.stasis.21\")\r\n    \r\n    elseif (steleCount == 3) then\r\n    UI.openRewardsDialog(\"stele.description.tour\")\r\n    UI.addReward(17317)\r\n    UI.addReward(17322, \"stele.reward.stasis.21\")\r\n    UI.addReward(27083, \"stele.reward.stasis.21\")\r\n    \r\n    elseif (steleCount == 4) then\r\n    UI.openRewardsDialog(\"stele.description.tour\")\r\n    UI.addReward(17318)\r\n    UI.addReward(17332, \"stele.reward.stasis.21\")\r\n    UI.addReward(27083, \"stele.reward.stasis.21\")\r\n    \r\n    \r\n    else\r\n    \r\n    end\r\n    \r\n    local stateInfoId = \"stele.state.description.\" .. toString(steleStateId)\r\n    \r\n    updateSteleInfo(stateInfoId, true)\nend\n\n-- [STELE] Refresh des APS pour Stèles\n-- \nfunction event_2550_22557()\n    \nend\n\n-- [STASIS] DUNGEON_DIFFICULTY_CHANGED - Reset les stèles\n-- \nfunction event_2550_22558()\n    \nend\n\n-- [QUÊTE] Déclenchement du combat contre Bohowt si le joueur a la quête\n-- \nfunction event_2550_22660()\n    \nend\n\n-- [QUÊTE] Initialise le groupe de monstre si le joueur a la quête\n-- \nfunction event_2550_22661()\n    \nend\n\n-- FIGHT_ENTER_ACTION_PHASE - On bloque le passage vers le trône\n-- \nfunction event_2550_22662()\n    \nend\n\n-- [ARCHI] Apparition de l'Archimonstre\n-- \nfunction event_2550_23987()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","openDoor","closeSteleInfo","onSteleInfoClosed","updateSteleInfo","event_2550_22548","event_2550_22549","event_2550_22550","event_2550_22551","event_2550_22554","event_2550_22555","event_2550_22556","event_2550_22557","event_2550_22558","event_2550_22660","event_2550_22661","event_2550_22662","event_2550_23987"],"quest_calls":["UI.openRewardsDialog(\"stele.description.tour\")\r","UI.openRewardsDialog(\"stele.description.tour\")\r","UI.openRewardsDialog(\"stele.description.tour\")\r","UI.openRewardsDialog(\"stele.description.tour\")\r","UI.openRewardsDialog(\"stele.description.tour\")\r","UI.openRewardsDialog(\"stele.description.tour\")\r","UI.openRewardsDialog(\"stele.description.tour\")\r","UI.openRewardsDialog(\"stele.description.tour\")\r"],"dialogue_calls":[]},"scenario/2551.lua":{"source":"-- les fonctions où on cache\r\nfunction hideMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, false)\r\nend\r\n\r\nfunction hidePart(monsterMobileId, partName)\r\n\tMobile.setPartVisible(monsterMobileId, false, partName)\r\nend\r\n\r\n-- les fonctions où on rend visible (à nouveau\r\nfunction showMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, true)\r\nend\r\n\r\nfunction showPart(monsterMobileId, partName)\r\n\tMobile.setPartVisible(monsterMobileId, true, partName)\r\nend\n\n-- [INIT] Variables Globales\n-- \nfunction event_2551_22559()\n    \nend\n\n-- [INIT] Inscription du joueur + Variables Locales\n-- \nfunction event_2551_22560(bordegann)\n    Mobile.addMobileCreationCallback(bordegann, \"hideMonster\", bordegann)\nend\n\n-- USER_GROUP_KILLED - Salle 01\n-- \nfunction event_2551_22561(room)\n    \nend\n\n-- USER_GROUP_KILLED - Salle 02 - BOSS\n-- \nfunction event_2551_22562()\n    \nend\n\n-- FIGHT_ENTER_ACTION_PHASE - Applique l'état \"Donjon\"\n-- \nfunction event_2551_22564()\n    \nend\n\n-- Déplace le joueur vers la salle suivante\n-- \nfunction event_2551_22565()\n    \nend\n\n-- [STELE] FIGHT_STARTED - On applique les difficultés stèles\n-- \nfunction event_2551_22844()\n    \nend\n\n-- [STELE] FIGHT_ENTER_ACTION_PHASE - On applique les bonus sur les joueurs\n-- \nfunction event_2551_22845()\n    \nend\n\n-- [STELE] FIGHT_ENDED - On rend la stèle utilisable en cas de défaite\n-- \nfunction event_2551_22876()\n    \nend\n\n-- [ARCHI] Apparition de l'Archimonstre\n-- \nfunction event_2551_23986()\n    \nend\n\n","functions":["hideMonster","hidePart","showMonster","showPart","event_2551_22559","event_2551_22560","event_2551_22561","event_2551_22562","event_2551_22564","event_2551_22565","event_2551_22844","event_2551_22845","event_2551_22876","event_2551_23986"],"quest_calls":[],"dialogue_calls":[]},"scenario/2552.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\n\n-- [INIT] Variables Globales\n-- \nfunction event_2552_22567()\n    \nend\n\n-- [INIT] Inscription du joueur + Variables Locales\n-- \nfunction event_2552_22568(room)\n    \nend\n\n-- USER_GROUP_KILLED - Salle 01\n-- \nfunction event_2552_22569()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 02\n-- \nfunction event_2552_22573()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 03 - BOSS\n-- \nfunction event_2552_22570()\n    \nend\n\n-- Déplace le joueur vers la salle suivante\n-- \nfunction event_2552_22572()\n    \nend\n\n-- [STELE] FIGHT_STARTED - On applique les difficultés sur le boss\n-- \nfunction event_2552_22770()\n    \nend\n\n-- [STELE] FIGHT_ENTER_ACTION_PHASE - On applique les bonus sur les joueurs\n-- \nfunction event_2552_22779()\n    \nend\n\n-- [STELE] FIGHT_ENDED - On rend la stèle utilisable en cas de défaite\n-- \nfunction event_2552_22864()\n    \nend\n\n-- [QUÊTE] FIGHT_ENDED_CLIENT_EVENT - Cinématique Viziw\n-- \nfunction event_2552_22685()\n    local playerId = Context.getLeaderId()\r\n    local viziwId = createActor(155202570, -22, 3, 2, 4, 3, 6)\r\n    Mobile.setMobileAnimation(viziwId, \"AnimStatiqueCadavre\")\r\n    Mobile.setMobileDirection(playerId, 7)\r\n    \r\n    function customSkip()\r\n    \tMobile.hideOtherPlayerMobile(false)\r\n    \tCamera.setMoveSpeedFactor(2.1)\r\n    \tskipCinematic(22685)\r\n    end\r\n    \r\n    Mobile.hideOtherPlayerMobile(true)\r\n    \r\n    startCinematicContext(1.2, viziwId)\r\n    \r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"customSkip\")\r\n    \r\n    invoke_custom(01000, 1, \"Camera.setMoveSpeedFactor\", 0.2)\r\n    invoke_custom(01000, 1, \"Camera.setZoomSpeedFactor\", 0.2)\r\n    \r\n    -- \"Aaah… Ma Weine…\"\r\n    invoke_custom(01000, 1, \"bubble\", viziwId, \"quest.wabbit.viziw.01\")\r\n    invoke_custom(03000, 1, \"clearBubbles\", viziwId)\r\n    \r\n    invoke_custom(03500, 1, \"Camera.setZoomFactor\", 1.4)\r\n    \r\n    -- \"Toutes ces années à vous sewviw… Pouw finiw…\"\r\n    invoke_custom(03500, 1, \"bubble\", viziwId, \"quest.wabbit.viziw.02\")\r\n    invoke_custom(07000, 1, \"clearBubbles\", viziwId)\r\n    \r\n    -- \"Que voulez-vous dire ?\"\r\n    invoke_custom(07500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(07500, 1, \"bubble\", playerId, \"quest.wabbit.viziw.03\")\r\n    invoke_custom(10000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(10500, 1, \"Mobile.setMobileDirection\", playerId, 1)\r\n    \r\n    -- \"Tiens, une lettre ainsi qu'un journal…\"\r\n    invoke_custom(11000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-ChercherPiste\")\r\n    invoke_custom(11000, 1, \"bubble\", playerId, \"quest.wabbit.viziw.04\")\r\n    invoke_custom(14500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Mais... C’est le papier et l’encre que j’ai ramenés à la Weine !\"\r\n    invoke_custom(15000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimCraft-Menuisier-Debut\")\r\n    invoke_custom(16000, 1, \"bubble\", playerId, \"quest.wabbit.viziw.05\")\r\n    invoke_custom(20000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Je n’y crois pas, cette lettre vous a prévenu de mon arrivée…\"\r\n    invoke_custom(20500, 1, \"bubble\", playerId, \"quest.wabbit.viziw.06\")\r\n    invoke_custom(24500, 1, \"clearBubbles\", playerId)\r\n    invoke_custom(24500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimCraft-Menuisier-Fin\")\r\n    \r\n    -- \"Et vous demandait de vous débarrasser de moi ?\"\r\n    invoke_custom(25500, 1, \"Mobile.setMobileDirection\", playerId, 7)\r\n    invoke_custom(25500, 1, \"bubble\", playerId, \"quest.wabbit.viziw.07\")\r\n    invoke_custom(29500, 1, \"clearBubbles\", playerId)\r\n    invoke_custom(26000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Colere\")\r\n    \r\n    -- \"Oui…\"\r\n    invoke_custom(29500, 1, \"bubble\", viziwId, \"quest.wabbit.viziw.08\")\r\n    invoke_custom(31000, 1, \"clearBubbles\", viziwId)\r\n    \r\n    -- \"Je sens que mes fowces me quittent…\"\r\n    invoke_custom(31500, 1, \"bubble\", viziwId, \"quest.wabbit.viziw.09\")\r\n    invoke_custom(34000, 1, \"clearBubbles\", viziwId)\r\n    \r\n    -- \"Dites à la Weine… que je l’admiwe…\"\r\n    invoke_custom(34500, 1, \"bubble\", viziwId, \"quest.wabbit.viziw.10\")\r\n    invoke_custom(38500, 1, \"clearBubbles\", viziwId)\r\n    \r\n    invoke_custom(39000, 1, \"customSkip\")\nend\n\n-- [QUÊTE] Fin de la cinématique - Le PJ obtient le journal + notif ACH 5182 OBJ 10853\n-- \nfunction event_2552_22686()\n    \nend\n\n-- [ARCHI] Apparition de l'Archimonstre\n-- \nfunction event_2552_23981()\n    \nend\n\n-- TEST - Feedback nombre de stèles\n-- \nfunction event_2552_24139(DifficultyLevel)\n    local text = Event.getKeyTranslation(\"fight.score.ogrest\", DifficultyLevel)\r\n    UI.setPropertyStringValue(\"fight.score.ogrest\", text)\r\n    \r\n    UI.addDialogUnloadedListener(\"fightResultDialog\", \"UI.removeProperty\", \"fight.score.ogrest\")\nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_2552_22567","event_2552_22568","event_2552_22569","event_2552_22573","event_2552_22570","event_2552_22572","event_2552_22770","event_2552_22779","event_2552_22864","event_2552_22685","customSkip","event_2552_22686","event_2552_23981","event_2552_24139"],"quest_calls":[],"dialogue_calls":[]},"scenario/2553.lua":{"source":"\n\n-- [INIT] Variables globales\n-- \nfunction event_2553_22576()\n    \nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_2553_22577()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 01\n-- \nfunction event_2553_22578(room)\n    \nend\n\n-- USER_GROUP_KILLED - Salle 02\n-- \nfunction event_2553_22579(room)\n    \nend\n\n-- USER_GROUP_KILLED - Salle 03\n-- \nfunction event_2553_22580()\n    \nend\n\n-- [ACHIEVEMENT] EFFECT_EXECUTION - Achievement premier (5208) \n-- \nfunction event_2553_22637()\n    \nend\n\n-- [ACHIEVEMENT] EFFECT_EXECUTION - Achievement dernier (5207)\n-- \nfunction event_2553_22638()\n    \nend\n\n-- [ACHIEVEMENT] Achievement premier (5208) validé\n-- \nfunction event_2553_22635()\n    \nend\n\n-- [ACHIEVEMENT] Achievement dernier (5209) validé\n-- \nfunction event_2553_22636()\n    \nend\n\n-- Déplace le joueur vers la salle suivante\n-- \nfunction event_2553_22581()\n    \nend\n\n-- [STELE] FIGHT_STARTED - On applique les difficultés sur le boss\n-- \nfunction event_2553_22859()\n    \nend\n\n-- [STELE] FIGHT_ENTER_ACTION_PHASE - On applique les bonus sur les joueurs\n-- \nfunction event_2553_22860()\n    \nend\n\n-- [STELE] FIGHT_ENDED - On rend la stèle utilisable en cas de défaite\n-- \nfunction event_2553_22877()\n    \nend\n\n-- [ARCHI] Apparition de l'Archimonstre\n-- \nfunction event_2553_23988()\n    \nend\n\n","functions":["event_2553_22576","event_2553_22577","event_2553_22578","event_2553_22579","event_2553_22580","event_2553_22637","event_2553_22638","event_2553_22635","event_2553_22636","event_2553_22581","event_2553_22859","event_2553_22860","event_2553_22877","event_2553_23988"],"quest_calls":[],"dialogue_calls":[]},"scenario/2554.lua":{"source":"\n\n-- [INIT] Variables Globales\n-- \nfunction event_2554_22582()\n    \nend\n\n-- [INIT] Inscription du joueur + Variables Locales\n-- \nfunction event_2554_22583(room)\n    \nend\n\n-- USER_GROUP_KILLED - Salle 01\n-- \nfunction event_2554_22584(room)\n    \nend\n\n-- MONSTER_ACTION_EVENT - Lancement du combat\n-- on skippe la cinématique pour tout le monde \nfunction event_2554_22588()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 02 - BOSS\n-- \nfunction event_2554_22585()\n    \nend\n\n-- FIGHT_ENTER_ACTION_PHASE - Applique l'état \"Donjon\"\n-- \nfunction event_2554_22586()\n    \nend\n\n-- Déplace le joueur vers la salle suivante\n-- \nfunction event_2554_22587()\n    \nend\n\n-- [STELE] FIGHT_STARTED - On applique les difficultés sur le boss\n-- \nfunction event_2554_22785()\n    \nend\n\n-- [STELE] FIGHT_ENTER_ACTION_PHASE - On applique les bonus sur les joueurs\n-- \nfunction event_2554_22786()\n    \nend\n\n-- [STELE] FIGHT_ENDED - On rend la stèle utilisable en cas de défaite\n-- \nfunction event_2554_22874()\n    \nend\n\n-- [ARCHI] Apparition de l'Archimonstre\n-- \nfunction event_2554_23979()\n    \nend\n\n","functions":["event_2554_22582","event_2554_22583","event_2554_22584","event_2554_22588","event_2554_22585","event_2554_22586","event_2554_22587","event_2554_22785","event_2554_22786","event_2554_22874","event_2554_23979"],"quest_calls":[],"dialogue_calls":[]},"scenario/2555.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\n-- On applique les couleurs Shinlay Lyu\r\nfunction shinlayLyuLenaldColor(lenaldId)\r\n\tMobile.setPartColor(lenaldId, \"Color_1\", 1, 0.88, 0, 1)\r\nend\r\n\r\nfunction shinlayLyuOldLenaldColor(lenaldId)\r\n\tMobile.setPartColor(lenaldId, \"Vetement\", 1, 0.88, 0, 1)\r\nend\r\n\r\n-- On applique les couleurs Lin Kuei\r\nfunction linKueiLenaldColor(lenaldId)\r\n\tMobile.setPartColor(lenaldId, \"Color_1\", 0, 0.78, 1, 1)\r\nend\r\n\r\nfunction linKueiOldLenaldColor(lenaldId)\r\n\tMobile.setPartColor(lenaldId, \"Vetement\", 0, 0.78, 1, 1)\r\nend\n\n-- [INIT] Variables globales\n-- \nfunction event_2555_22589()\n    \nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_2555_22590(shinlayLyu, linKuei, linAMobC, linAMobD, linAMobE, linBMobC, linBMobD, linBMobE, linCMobC, linCMobD, linCMobE, linCMobF, shinlayAMobC, shinlayAMobD, shinlayAMobE, shinlayBMobC, shinlayBMobD, shinlayBMobE, shinlayCMobC, shinlayCMobD, shinlayCMobE, shinlayCMobF, bossMobC, bossMobD, bossMobE, bossMobF, discipleLenald)\n    local shinlayLyu = toLong(shinlayLyu)\r\n    local linKuei = toLong(linKuei)\r\n    \r\n    if (shinlayLyu >= 1) then\r\n    \tMobile.addMobileCreationCallback(shinlayAMobC, \"shinlayLyuLenaldColor\", shinlayAMobC)\r\n    \tMobile.addMobileCreationCallback(shinlayAMobD, \"shinlayLyuLenaldColor\", shinlayAMobD)\r\n    \tMobile.addMobileCreationCallback(shinlayAMobE, \"shinlayLyuOldLenaldColor\", shinlayAMobE)\r\n    \tMobile.addMobileCreationCallback(shinlayBMobC, \"shinlayLyuLenaldColor\", shinlayBMobC)\r\n    \tMobile.addMobileCreationCallback(shinlayBMobD, \"shinlayLyuLenaldColor\", shinlayBMobD)\r\n    \tMobile.addMobileCreationCallback(shinlayBMobE, \"shinlayLyuOldLenaldColor\", shinlayBMobE)\r\n    \tMobile.addMobileCreationCallback(shinlayCMobC, \"shinlayLyuLenaldColor\", shinlayCMobC)\r\n    \tMobile.addMobileCreationCallback(shinlayCMobD, \"shinlayLyuOldLenaldColor\", shinlayCMobD)\r\n    \tMobile.addMobileCreationCallback(shinlayCMobE, \"shinlayLyuOldLenaldColor\", shinlayCMobE)\r\n    \tMobile.addMobileCreationCallback(bossMobC, \"shinlayLyuLenaldColor\", bossMobC)\r\n    \tMobile.addMobileCreationCallback(bossMobD, \"shinlayLyuLenaldColor\", bossMobD)\r\n    \tMobile.addMobileCreationCallback(bossMobE, \"shinlayLyuOldLenaldColor\", bossMobE)\r\n    \tMobile.addMobileCreationCallback(bossMobF, \"shinlayLyuOldLenaldColor\", bossMobF)\r\n    \tMobile.addMobileCreationCallback(discipleLenald, \"shinlayLyuOldLenaldColor\", discipleLenald)\r\n    elseif (linKuei >= 1) then\r\n    \tMobile.addMobileCreationCallback(linAMobC, \"linKueiLenaldColor\", linAMobC)\r\n    \tMobile.addMobileCreationCallback(linAMobD, \"linKueiLenaldColor\", linAMobD)\r\n    \tMobile.addMobileCreationCallback(linAMobE, \"linKueiOldLenaldColor\", linAMobE)\r\n    \tMobile.addMobileCreationCallback(linBMobC, \"linKueiLenaldColor\", linBMobC)\r\n    \tMobile.addMobileCreationCallback(linBMobD, \"linKueiLenaldColor\", linBMobD)\r\n    \tMobile.addMobileCreationCallback(linBMobE, \"linKueiOldLenaldColor\", linBMobE)\r\n    \tMobile.addMobileCreationCallback(linCMobC, \"linKueiLenaldColor\", linCMobC)\r\n    \tMobile.addMobileCreationCallback(linCMobD, \"linKueiOldLenaldColor\", linCMobD)\r\n    \tMobile.addMobileCreationCallback(linCMobE, \"linKueiOldLenaldColor\", linCMobE)\r\n    \tMobile.addMobileCreationCallback(bossMobC, \"linKueiLenaldColor\", bossMobC)\r\n    \tMobile.addMobileCreationCallback(bossMobD, \"linKueiLenaldColor\", bossMobD)\r\n    \tMobile.addMobileCreationCallback(bossMobE, \"linKueiOldLenaldColor\", bossMobE)\r\n    \tMobile.addMobileCreationCallback(bossMobF, \"linKueiOldLenaldColor\", bossMobF)\r\n    \tMobile.addMobileCreationCallback(discipleLenald, \"linKueiOldLenaldColor\", discipleLenald)\r\n    else\r\n    end\nend\n\n-- INTERACTIVE_ELEMENT_ACTIVATION - Ouverture de la porte Shinlay Lyu\n-- \nfunction event_2555_22596(shinlayAMobC, shinlayAMobD, shinlayAMobE, shinlayBMobC, shinlayBMobD, shinlayBMobE, shinlayCMobC, shinlayCMobD, shinlayCMobE, shinlayCMobF, bossMobC, bossMobD, bossMobE, bossMobF, discipleLenald)\n    UI.openRewardsDialog(\"dungeon.lenald.shinlaylyu\")\r\n    UI.addReward(31363, \"stele.reward.stasis.21\")\r\n    UI.addReward(31364, \"stele.reward.stasis.21\")\r\n    \r\n    Mobile.addMobileCreationCallback(shinlayAMobC, \"shinlayLyuLenaldColor\", shinlayAMobC)\r\n    Mobile.addMobileCreationCallback(shinlayAMobD, \"shinlayLyuLenaldColor\", shinlayAMobD)\r\n    Mobile.addMobileCreationCallback(shinlayAMobE, \"shinlayLyuOldLenaldColor\", shinlayAMobE)\r\n    Mobile.addMobileCreationCallback(shinlayBMobC, \"shinlayLyuLenaldColor\", shinlayBMobC)\r\n    Mobile.addMobileCreationCallback(shinlayBMobD, \"shinlayLyuLenaldColor\", shinlayBMobD)\r\n    Mobile.addMobileCreationCallback(shinlayBMobE, \"shinlayLyuOldLenaldColor\", shinlayBMobE)\r\n    Mobile.addMobileCreationCallback(shinlayCMobC, \"shinlayLyuLenaldColor\", shinlayCMobC)\r\n    Mobile.addMobileCreationCallback(shinlayCMobD, \"shinlayLyuLenaldColor\", shinlayCMobD)\r\n    Mobile.addMobileCreationCallback(shinlayCMobE, \"shinlayLyuOldLenaldColor\", shinlayCMobE)\r\n    Mobile.addMobileCreationCallback(shinlayCMobF, \"shinlayLyuOldLenaldColor\", shinlayCMobF)\r\n    Mobile.addMobileCreationCallback(bossMobC, \"shinlayLyuLenaldColor\", bossMobC)\r\n    Mobile.addMobileCreationCallback(bossMobD, \"shinlayLyuLenaldColor\", bossMobD)\r\n    Mobile.addMobileCreationCallback(bossMobE, \"shinlayLyuOldLenaldColor\", bossMobE)\r\n    Mobile.addMobileCreationCallback(bossMobF, \"shinlayLyuOldLenaldColor\", bossMobF)\r\n    Mobile.addMobileCreationCallback(discipleLenald, \"shinlayLyuLenaldColor\", discipleLenald)\nend\n\n-- INTERACTIVE_ELEMENT_ACTIVATION - Ouverture de la porte Lin Kuei\n-- \nfunction event_2555_22598(linAMobC, linAMobD, linAMobE, linBMobC, linBMobD, linBMobE, linCMobC, linCMobD, linCMobE, linCMobF, bossMobC, bossMobD, bossMobE, bossMobF, discipleLenald)\n    UI.openRewardsDialog(\"dungeon.lenald.linkuei\")\r\n    UI.addReward(31362, \"stele.reward.stasis.21\")\r\n    UI.addReward(31366, \"stele.reward.stasis.21\")\r\n    \r\n    Mobile.addMobileCreationCallback(linAMobC, \"linKueiLenaldColor\", linAMobC)\r\n    Mobile.addMobileCreationCallback(linAMobD, \"linKueiLenaldColor\", linAMobD)\r\n    Mobile.addMobileCreationCallback(linAMobE, \"linKueiOldLenaldColor\", linAMobE)\r\n    Mobile.addMobileCreationCallback(linBMobC, \"linKueiLenaldColor\", linBMobC)\r\n    Mobile.addMobileCreationCallback(linBMobD, \"linKueiLenaldColor\", linBMobD)\r\n    Mobile.addMobileCreationCallback(linBMobE, \"linKueiOldLenaldColor\", linBMobE)\r\n    Mobile.addMobileCreationCallback(linCMobC, \"linKueiLenaldColor\", linCMobC)\r\n    Mobile.addMobileCreationCallback(linCMobD, \"linKueiLenaldColor\", linCMobD)\r\n    Mobile.addMobileCreationCallback(linCMobE, \"linKueiOldLenaldColor\", linCMobE)\r\n    Mobile.addMobileCreationCallback(linCMobF, \"linKueiOldLenaldColor\", linCMobF)\r\n    Mobile.addMobileCreationCallback(bossMobC, \"linKueiLenaldColor\", bossMobC)\r\n    Mobile.addMobileCreationCallback(bossMobD, \"linKueiLenaldColor\", bossMobD)\r\n    Mobile.addMobileCreationCallback(bossMobE, \"linKueiOldLenaldColor\", bossMobE)\r\n    Mobile.addMobileCreationCallback(bossMobF, \"linKueiOldLenaldColor\", bossMobF)\r\n    Mobile.addMobileCreationCallback(discipleLenald, \"linKueiOldLenaldColor\", discipleLenald)\nend\n\n-- USER_GROUP_KILLED - Salle 01\n-- \nfunction event_2555_22591(room)\n    \nend\n\n-- USER_GROUP_KILLED - Salle 02\n-- \nfunction event_2555_22592(room)\n    \nend\n\n-- USER_GROUP_KILLED - Salle 03\n-- \nfunction event_2555_22593(room)\n    \nend\n\n-- USER_GROUP_KILLED - Salle 04\n-- \nfunction event_2555_22594()\n    \nend\n\n-- FIGHT_ENTER_ACTION_PHASE - Applique l'état Shinlay Lyu ou Lin Kuei\n-- \nfunction event_2555_22597()\n    \nend\n\n-- Déplace le joueur vers la salle suivante\n-- \nfunction event_2555_22595()\n    \nend\n\n-- [QUÊTE] ENTER_INSTANCE - Le PJ rentre dans le palais\n-- \nfunction event_2555_22645()\n    local playerId = Context.getLeaderId()\r\n    local empeleulId = createActor(154502555, -27, 0, 16, 4, 1, 6)\r\n    Mobile.setMobileAnimation(empeleulId, \"AnimStatique-HorsCombat\")\r\n    \r\n    startCinematicContext(1.2, playerId)\r\n    \r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 22645)\r\n    \r\n    -- \"Bienvenue dans notle palais, étlanger.\"\r\n    invoke_custom(01000, 1, \"Mobile.moveMobile\", playerId, -18, 0, 4, \"Mobile.setMobileDirection\", 5)\r\n    invoke_custom(03000, 1, \"Camera.attachCameraToMobile\", empeleulId)\r\n    invoke_custom(04000, 1, \"bubble\", empeleulId, \"quest.wabbit.lenald.dojo.01\")\r\n    invoke_custom(04000, 1, \"Mobile.setMobileAnimation\", empeleulId, \"AnimSort-Palade\")\r\n    invoke_custom(07000, 1, \"clearBubbles\", empeleulId)\r\n    \r\n    -- \"Quel magnifice édifice !\"\r\n    invoke_custom(07000, 1, \"Camera.attachCameraToMobile\", playerId)\r\n    invoke_custom(08000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Saluer\")\r\n    invoke_custom(09000, 1, \"bubble\", playerId, \"quest.wabbit.lenald.dojo.02\")\r\n    invoke_custom(11000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(11000, 1, \"Camera.attachCameraToMobile\", empeleulId)\r\n    \r\n    -- \"J'ai entendu ta convelsation avec mon fils.\"\r\n    invoke_custom(11500, 1, \"bubble\", empeleulId, \"quest.wabbit.lenald.dojo.03\")\r\n    invoke_custom(14000, 1, \"clearBubbles\", empeleulId)\r\n    \r\n    invoke_custom(14500, 1, \"Camera.attachCameraToMobile\", playerId)\r\n    \r\n    -- \"**Son fils ? Il veut parler du Loi ?\"\r\n    invoke_custom(15000, 1, \"bubble\", playerId, \"quest.wabbit.lenald.dojo.04\")\r\n    invoke_custom(15000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(17500, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(18000, 1, \"Camera.attachCameraToMobile\", empeleulId)\r\n    \r\n    -- \"Ainsi, tu es venu défiel mes disciples. Lejoins-moi dans notle dojo.\"\r\n    invoke_custom(18500, 1, \"Mobile.setMobileAnimation\", empeleulId, \"AnimSort-Palade\")\r\n    invoke_custom(18500, 1, \"bubble\", empeleulId, \"quest.wabbit.lenald.dojo.05\")\r\n    invoke_custom(23000, 1, \"clearBubbles\", empeleulId)\r\n    \r\n    -- \"Deux voies s'offlent à toi. Le choix t'appaltient.\"\r\n    invoke_custom(23500, 1, \"bubble\", empeleulId, \"quest.wabbit.lenald.dojo.06\")\r\n    invoke_custom(27000, 1, \"Camera.setCamera\", 1.2, -24, -8, 0)\r\n    invoke_custom(27500, 1, \"Mobile.setMobileDirection\", playerId, 7)\r\n    invoke_custom(29000, 1, \"Camera.setCamera\", 1.2, -24, 8, 0)\r\n    invoke_custom(30000, 1, \"Mobile.setMobileDirection\", playerId, 3)\r\n    invoke_custom(31000, 1, \"Mobile.setMobileDirection\", playerId, 5)\r\n    invoke_custom(26500, 1, \"clearBubbles\", empeleulId)\r\n    \r\n    invoke_custom(31000, 1, \"Camera.attachCameraToMobile\", empeleulId)\r\n    -- \"Tu aulas plusieurls épleuves avant d'atteindle la salle finale.\"\r\n    invoke_custom(31000, 1, \"bubble\", empeleulId, \"quest.wabbit.lenald.dojo.07\")\r\n    invoke_custom(35000, 1, \"clearBubbles\", empeleulId)\r\n    \r\n    invoke_custom(35500, 1, \"Camera.attachCameraToMobile\", playerId)\r\n    -- \"**Attends... Il nous a entendus depuis le palais ?\"\r\n    invoke_custom(36000, 1, \"bubble\", playerId, \"quest.wabbit.lenald.dojo.08\")\r\n    invoke_custom(36000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(38500, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(39000, 1, \"skipCinematic\", 22645)\nend\n\n-- [QUÊTE] Fin de la cinématique - Le PJ rentre dans le palais\n-- \nfunction event_2555_22653()\n    \nend\n\n-- [QUÊTE] FIGHT_ENDED_CLIENT_EVENT - Le PJ a vaincu l'Empeleul et ses disciples\n-- \nfunction event_2555_22646()\n    local playerId = Context.getLeaderId()\r\n    local empeleulId = createActor(154502555, -219, -13, 2, 4, 1, 6)\r\n    Mobile.setMobileAnimation(empeleulId, \"AnimStatique-HorsCombat\")\r\n    Mobile.setMobileDirection(playerId, 1)\r\n    \r\n    startCinematicContext(1.2, empeleulId)\r\n    \r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\")\r\n    \r\n    invoke_custom(01000, 1, \"Camera.setMoveSpeedFactor\", 0.2)\r\n    invoke_custom(01000, 1, \"Camera.setZoomSpeedFactor\", 0.2)\r\n    \r\n    -- \"Halte !\"\r\n    invoke_custom(01000, 1, \"bubble\", empeleulId, \"quest.wabbit.lenald.dojo.09\")\r\n    invoke_custom(01000, 1, \"Mobile.setMobileAnimation\", empeleulId, \"AnimSort-Palade\")\r\n    invoke_custom(01000, 1, \"Mobile.setMobileDirection\", playerId, 5)\r\n    invoke_custom(02500, 1, \"clearBubbles\", empeleulId)\r\n    \r\n    invoke_custom(03000, 1, \"Camera.setZoomFactor\", 1.4)\r\n    \r\n    -- \"Je vous félicite tous poul vos effolts et votle intensité.\"\r\n    invoke_custom(03000, 1, \"bubble\", empeleulId, \"quest.wabbit.lenald.dojo.10\")\r\n    invoke_custom(06000, 1, \"clearBubbles\", empeleulId)\r\n    \r\n    -- \"Du coup, j'ai gagné ?\"\r\n    invoke_custom(06500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Applaudir\")\r\n    invoke_custom(06500, 1, \"bubble\", playerId, \"quest.wabbit.lenald.dojo.11\")\r\n    invoke_custom(08000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Il n'y a ni gagnant, ni peldant. Seulement un applentissage.\"\r\n    invoke_custom(08500, 1, \"bubble\", empeleulId, \"quest.wabbit.lenald.dojo.12\")\r\n    invoke_custom(09500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Non\")\r\n    invoke_custom(11500, 1, \"clearBubbles\", empeleulId)\r\n    \r\n    -- \"Aujourd'hui, mes disciples ont pu constatel que leul voyage est loin d'êtle achevé.\"\r\n    invoke_custom(12000, \"Mobile.setMobileDirection\", empleulId, 5)\r\n    invoke_custom(12000, 1, \"bubble\", empeleulId, \"quest.wabbit.lenald.dojo.13\")\r\n    invoke_custom(16500, 1, \"clearBubbles\", empeleulId)\r\n    \r\n    -- \"Néanmoins, je les sens plêts à venil à bout de l'épleuve du poteau.\"\r\n    invoke_custom(17500, 1, \"bubble\", empeleulId, \"quest.wabbit.lenald.dojo.14\")\r\n    invoke_custom(20500, 1, \"clearBubbles\", empeleulId)\r\n    \r\n    -- \"Et moi... ?\"\r\n    invoke_custom(21000, 1, \"Camera.setCamera\", 1.6, -216, -13, 2)\r\n    invoke_custom(21000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmoteMarket-HausseEpaules\")\r\n    invoke_custom(21000, 1, \"bubble\", playerId, \"quest.wabbit.lenald.dojo.15\")\r\n    invoke_custom(23000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Ton applentissage est toujouls en couls.\"\r\n    invoke_custom(23000, \"Mobile.setMobileDirection\", empleulId, 1)\r\n    invoke_custom(23500, 1, \"bubble\", empeleulId, \"quest.wabbit.lenald.dojo.16\")\r\n    invoke_custom(26000, 1, \"clearBubbles\", empeleulId)\r\n    \r\n    -- \"...À toi d'en tilel... les bonnes leçons.\"\r\n    invoke_custom(27000, 1, \"bubble\", empeleulId, \"quest.wabbit.lenald.dojo.17\")\r\n    invoke_custom(30500, 1, \"clearBubbles\", empeleulId)\r\n    \r\n    -- \"C'est tout ? Le Loi ne sera pas très convaincu...\"\r\n    invoke_custom(31000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(31000, 1, \"Mobile.setMobileDirection\", playerId, 3)\r\n    invoke_custom(31000, 1, \"bubble\", playerId, \"quest.wabbit.lenald.dojo.18\")\r\n    invoke_custom(34500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Au contlaile, il sela implessionné.\"\r\n    invoke_custom(35000, 1, \"bubble\", empeleulId, \"quest.wabbit.lenald.dojo.19\")\r\n    invoke_custom(37500, 1, \"clearBubbles\", empeleulId)\r\n    \r\n    -- \"Bien, étlanger. Tenez-vous droit ! Saluez !\"\r\n    invoke_custom(38000, 1, \"bubble\", empeleulId, \"quest.wabbit.lenald.dojo.20\")\r\n    invoke_custom(40000, 1, \"clearBubbles\", empeleulId)\r\n    invoke_custom(39500, 1, \"Mobile.setMobileDirection\", playerId, 5)\r\n    invoke_custom(40500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Huss-Boucle\")\r\n    \r\n    -- \"Merci beaucoup !\"\r\n    invoke_custom(41000, 1, \"bubble\", playerId, \"quest.wabbit.lenald.dojo.21\")\r\n    invoke_custom(42500, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(43500, 1, \"skipCinematic\")\nend\n\n-- [STELE] FIGHT_STARTED - On applique les difficultés sur le boss\n-- \nfunction event_2555_22787()\n    \nend\n\n-- [STELE] FIGHT_ENTER_ACTION_PHASE - On applique les bonus sur les joueurs\n-- \nfunction event_2555_22788()\n    \nend\n\n-- [STELE] FIGHT_ENDED - On rend la stèle utilisable en cas de défaite\n-- \nfunction event_2555_22875()\n    \nend\n\n-- [ARCHI] Apparition de l'Archimonstre\n-- \nfunction event_2555_23980()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","shinlayLyuLenaldColor","shinlayLyuOldLenaldColor","linKueiLenaldColor","linKueiOldLenaldColor","event_2555_22589","event_2555_22590","event_2555_22596","event_2555_22598","event_2555_22591","event_2555_22592","event_2555_22593","event_2555_22594","event_2555_22597","event_2555_22595","event_2555_22645","event_2555_22653","event_2555_22646","event_2555_22787","event_2555_22788","event_2555_22875","event_2555_23980"],"quest_calls":["UI.openRewardsDialog(\"dungeon.lenald.shinlaylyu\")\r","UI.openRewardsDialog(\"dungeon.lenald.linkuei\")\r"],"dialogue_calls":[]},"scenario/2557.lua":{"source":"\n\n-- [INIT] Variables\n-- \nfunction event_2557_22618()\n    \nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_2557_22619()\n    \nend\n\n-- [EVENT] Réceptacle Full - On rend le challenge disponible grâce à l'état de l'IE\n-- \nfunction event_2557_22620()\n    \nend\n\n-- [EVENT] 1 - Fin du challenge Lenald - On reset le Réceptacle\n-- \nfunction event_2557_22621()\n    \nend\n\n-- [EVENT] 2 - Fin du challenge Légumutant - On reset le Réceptacle\n-- \nfunction event_2557_22622()\n    \nend\n\n-- [EVENT] 3 - Fin du challenge Wabbit - On reset le Réceptacle\n-- \nfunction event_2557_22623()\n    \nend\n\n-- [EVENT] 4 - Fin du challenge Sabléoptère - On reset le Réceptacle\n-- \nfunction event_2557_22625()\n    \nend\n\n-- [EVENT] 5 - Fin du challenge Zwombbit - On reset le Réceptacle\n-- \nfunction event_2557_22626()\n    \nend\n\n","functions":["event_2557_22618","event_2557_22619","event_2557_22620","event_2557_22621","event_2557_22622","event_2557_22623","event_2557_22625","event_2557_22626"],"quest_calls":[],"dialogue_calls":[]},"scenario/2558.lua":{"source":"\n\n-- Variables globales\n-- \nfunction event_2558_22627()\n    \nend\n\n-- [EVENT] Le joueur entre dans l'instance - Inscription au scénario\n-- \nfunction event_2558_22628(doorOpened, bossId)\n    if (doorOpened == 1) then\r\n    else hideMonster(bossId)\r\n    end\nend\n\n-- Le joueur attaque Cire Momore - Lancement du Combat\n-- \nfunction event_2558_22629()\n    \nend\n\n-- INTERACTIVE_ELEMENT_ACTIVATION - Ouverture de la porte\n-- \nfunction event_2558_22630(bossId)\n    local playerId = Context.getLeaderId()\r\n    local bossId = toLong(bossId)\r\n    \r\n    startCinematicContext(1.0, bossId)\r\n    \r\n    invoke_custom(1999, 1, \"Mobile.addMobileCreationCallback\", bossId, \"showMonster\", bossId)\r\n    invoke_custom(1950, 1, \"Mobile.setMobileAnimation\", bossId, \"AnimApparition\")\r\n    invoke_custom(1950, 1, \"Sound.playSound\", 300183905357901, true, 50)\r\n    \r\n    invoke_custom(2000, 1, \"Effect.createCameraShakeEffect\", 100, 500, 100, 5, 100, \"BOTH\")\r\n    invoke_custom(6400, 1, \"Camera.attachCameraToMobile\", playerId)\r\n    \r\n    invoke_custom(6400, 1, \"skipCinematic\")\nend\n\n","functions":["event_2558_22627","event_2558_22628","event_2558_22629","event_2558_22630"],"quest_calls":[],"dialogue_calls":[]},"scenario/2559.lua":{"source":"\n\n-- Variables globales\n-- \nfunction event_2559_22631()\n    \nend\n\n-- [EVENT] Le joueur entre dans l'instance - Inscription au scénario\n-- \nfunction event_2559_22632(doorOpened, bossId)\n    if (doorOpened == 1) then\r\n    else hideMonster(bossId)\r\n    end\nend\n\n-- Le joueur attaque Cire Momore - Lancement du Combat\n-- \nfunction event_2559_22633()\n    \nend\n\n-- INTERACTIVE_ELEMENT_ACTIVATION - Ouverture de la porte\n-- \nfunction event_2559_22634(bossId)\n    local playerId = Context.getLeaderId()\r\n    local bossId = toLong(bossId)\r\n    \r\n    startCinematicContext(1.0, bossId)\r\n    \r\n    invoke_custom(1999, 1, \"Mobile.addMobileCreationCallback\", bossId, \"showMonster\", bossId)\r\n    invoke_custom(1950, 1, \"Mobile.setMobileAnimation\", bossId, \"AnimApparition\")\r\n    invoke_custom(1950, 1, \"Sound.playSound\", 300183905357901, true, 50)\r\n    \r\n    invoke_custom(2000, 1, \"Effect.createCameraShakeEffect\", 100, 500, 100, 5, 100, \"BOTH\")\r\n    invoke_custom(6400, 1, \"Camera.attachCameraToMobile\", playerId)\r\n    \r\n    invoke_custom(6400, 1, \"skipCinematic\")\nend\n\n","functions":["event_2559_22631","event_2559_22632","event_2559_22633","event_2559_22634"],"quest_calls":[],"dialogue_calls":[]},"scenario/2560.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\n-- les fonctions où on cache\r\nfunction hideMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, false)\r\nend\r\n\r\nfunction hidePart(monsterMobileId, partName)\r\n\tMobile.setPartVisible(monsterMobileId, false, partName)\r\nend\r\n\r\n-- les fonctions où on rend visible (à nouveau)\r\nfunction showMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, true)\r\nend\r\n\r\nfunction showPart(monsterMobileId, partName)\r\n\tMobile.setPartVisible(monsterMobileId, true, partName)\r\nend\n\n-- [INITIALISATION] Serveur\n-- \nfunction event_2560_22639()\n    \nend\n\n-- Q2 - ENTER_INSTANCE - Cinématique Arrivée (ACH 5167 OBJ 10638)\n-- \nfunction event_2560_22651()\n    local playerId = Context.getLeaderId()\r\n    local lenaldOne = createActor(154502551, 19, 19, 0, 4, 1, 6)\r\n    Mobile.setPartColor(lenaldOne, \"Color_1\", 0.82, 0.40, 0.40, 1)\r\n    local lenaldTwo = createActor(154502551, 19, 21, 0, 4, 1, 6)\r\n    Mobile.setPartColor(lenaldTwo, \"Color_1\", 0.82, 0.40, 0.40, 1)\r\n    \r\n    function customSkip()\r\n    \tMobile.hideOtherPlayerMobile(false)\r\n    \tUI.displayWideScreenBand(true, 25, 500)\r\n    \tskipCinematic(22651)\r\n    end\r\n    \r\n    Mobile.hideOtherPlayerMobile(true)\r\n    \r\n    startCinematicContext(1.0, playerId)\r\n    \r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"customSkip\")\r\n    \r\n    invoke_custom(00100, 1, \"Camera.setCamera\", 1.0, 32, 20, 0)\r\n    \r\n    invoke_custom(05000, 1, \"Camera.setMoveSpeedFactor\", 0.2)\r\n    invoke_custom(00500, 1, \"Camera.setZoomSpeedFactor\", 0.2)\r\n    \r\n    invoke_custom(01500, 1, \"Mobile.moveMobile\", playerId, 32, 20, 0, \"Mob