tte situation, Liz.\"\r\n    invoke_custom(24000, 1, \"bubble\", loiLenald, \"quest.wabbit.lenald.conflit.08\")\r\n    invoke_custom(27500, 1, \"clearBubbles\", loiLenald)\r\n    \r\n    -- \"Vous menez notle peuple vels le désastle et l'obsculantisme...\"\r\n    invoke_custom(28000, 1, \"bubble\", liz, \"quest.wabbit.lenald.conflit.09\")\r\n    invoke_custom(28000, 1, \"Mobile.setMobileAnimation\", liz, \"AnimComp-Negatif\")\r\n    invoke_custom(32000, 1, \"clearBubbles\", liz)\r\n    \r\n    -- \"Je mène notle peuple vels une voie juste.\"\r\n    invoke_custom(32500, 1, \"bubble\", loiLenald, \"quest.wabbit.lenald.conflit.10\")\r\n    invoke_custom(35500, 1, \"clearBubbles\", loiLenald)\r\n    \r\n    -- \"Telle est ma tâche. Il est temps que tu tlouves la tienne.\"\r\n    invoke_custom(36000, 1, \"bubble\", loiLenald, \"quest.wabbit.lenald.conflit.11\")\r\n    invoke_custom(40000, 1, \"clearBubbles\", loiLenald)\r\n    \r\n    invoke_custom(40500, 1, \"Camera.attachCameraToMobile\", liz)\r\n    -- \"...\"\r\n    invoke_custom(40500, 1, \"bubble\", liz, \"quest.wabbit.lenald.conflit.12\")\r\n    invoke_custom(40500, 1, \"Mobile.moveMobile\", liz, -41, -51, 0)\r\n    invoke_custom(42500, 1, \"Mobile.moveMobile\", liz, -34, -51, 0)\r\n    invoke_custom(45500, 1, \"Mobile.moveMobile\", liz, -23, -48, 6)\r\n    invoke_custom(41500, 1, \"Mobile.setMobileDirection\", playerId, 7)\r\n    invoke_custom(42500, 1, \"Mobile.setMobileDirection\", playerId, 1)\r\n    invoke_custom(45000, 1, \"Mobile.setMobileDirection\", playerId, 5)\r\n    \r\n    invoke_custom(45000, 1, \"Camera.setCamera\", 1.4, -56, -50, 6)\r\n    \r\n    -- \"Vous n'êtes pas un peu dur envers elle ?\"\r\n    invoke_custom(45000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Calmer\")\r\n    invoke_custom(45000, 1, \"bubble\", playerId, \"quest.wabbit.lenald.conflit.13\")\r\n    invoke_custom(48000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Je n'ai plus le choix. Notle honneul est en jeu