ble\", waWabbit, \"quest.wabbit.conseil2.55\")\r\n    invoke_custom(207000, 1, \"clearBubbles\", waWabbit)\r\n    \r\n    -- \"Sellons-nous la patte poul scellel cette nouvelle alliance.\"\r\n    invoke_custom(207500, 1, \"bubble\", loiLenald, \"quest.wabbit.conseil2.56\")\r\n    invoke_custom(210000, 1, \"clearBubbles\", loiLenald)\r\n    \r\n    invoke_custom(211000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Victoire\")\r\n    \r\n    invoke_custom(211000, 1, \"UI.displayWideScreenBand\", true, 100, 1000)\r\n    invoke_custom(211000, 1, \"Camera.setZoomSpeedFactor\", 0.1)\r\n    invoke_custom(211000, 1, \"Camera.setCamera\", 1.5, 578, 582, 0)\r\n    \r\n    invoke_custom(215000, 1, \"Mobile.setMobileVisible\", gawdeOne, false)\r\n    invoke_custom(215000, 1, \"Mobile.setMobileVisible\", gawdeTwo, false)\r\n    invoke_custom(215000, 1, \"Mobile.setMobileVisible\", gawdeThree, false)\r\n    invoke_custom(215000, 1, \"Mobile.setMobileVisible\", galdeOne, false)\r\n    invoke_custom(215000, 1, \"Mobile.setMobileVisible\", galdeTwo, false)\r\n    invoke_custom(215000, 1, \"Mobile.setMobileVisible\", galdeThree, false)\r\n    invoke_custom(215000, 1, \"Mobile.setMobileVisible\", loiLenald, false)\r\n    invoke_custom(215000, 1, \"Mobile.setMobileVisible\", weine, false)\r\n    invoke_custom(215000, 1, \"Mobile.setMobileVisible\", patwiche, false)\r\n    invoke_custom(215000, 1, \"Mobile.setMobileVisible\", tomHate, false)\r\n    invoke_custom(215000, 1, \"Mobile.setMobileVisible\", waWabbit, false)\r\n    invoke_custom(215000, 1, \"Mobile.setMobileVisible\", alia, false)\r\n    invoke_custom(215000, 1, \"Mobile.setMobileVisible\", bordegann, false)\r\n    invoke_custom(214000, 1, \"Mobile.setMobilePosition\", playerId, 579, 590, 0)\r\n    invoke_custom(215000, 1, \"Mobile.setMobileDirection\", playerId, 3)\r\n    invoke_custom(215000, 1, \"Mobile.setMobilePosition\", liz, 577, 585, 0)\r\n    invoke_custom(215000, 1, \"Mobile.setMobileDirection\", liz, 3)\r\n    invoke_custom(213000, 1, \"Camera.attachCameraToMobile\", playerId)\r\n    \r\n    invoke_custom(215000, 1, \"UI.displayWideScreenBand\", true, 25, 1000)\r\n    \r\n    invoke_custom(217500, 1, \"Mobile.moveMobile\", liz, 577, 590, 0, \"Mobile.setMobileDirection\", liz, 1)\r\n    \r\n    -- \"Eh bien, tout est bien qui finit bien…\"\r\n    invoke_custom(216000, 1, \"bubble\", playerId, \"quest.wabbit.conseil2.57\")\r\n    invoke_custom(216000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Bailler\")\r\n    invoke_custom(220000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(220500, 1, \"Mobile.setMobileDirection\", playerId, 5)\r\n    \r\n    -- \"S’il vous plait… Venez me letlouvel au sanctuaile dès que possible.\"\r\n    invoke_custom(221000, 1, \"bubble\", liz, \"quest.wabbit.conseil2.58\")\r\n    invoke_custom(221000, 1, \"Mobile.setMobileAnimation\", liz, \"AnimComp-Parle\")\r\n    invoke_custom(225000, 1, \"clearBubbles\", liz)\r\n    \r\n    invoke_custom(226000, 1, \"customSkip\")\nend\n\n-- [QUÊTE] Fin du conseil Cawotte - Validation ACH 5188 OBJ 10783\n-- \nfunction event_2566_22739()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","hideMonster","hidePart","showMonster","showPart","event_2566_22717","event_2566_22718","customSkip","event_2566_22719","event_2566_22724","customSkip","event_2566_22725","event_2566_22722","customSkip","event_2566_22723","event_2566_22734","event_2566_22735","customSkip","event_2566_22736","event_2566_22738","customSkip","event_2566_22739"],"quest_calls":[],"dialogue_calls":[]},"scenario/2567.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\napsId = 7843023\r\n\r\nfunction displayDoor()\r\n    apsOneId = Particle.addParticleSystem(apsId, 14, -1, 0)\r\n    apsTwoId = Particle.addParticleSystem(apsId, 14, 0, 0)\r\n    apsThreeId = Particle.addParticleSystem(apsId, 14, 1, 0)\r\n    apsFourId = Particle.addParticleSystem(apsId, 14, 2, 0)\r\nend\r\n\r\nfunction hideDoor()\r\n    Particle.removeParticleSystem(apsOneId)\r\n    Particle.removeParticleSystem(apsTwoId)\r\n    Particle.removeParticleSystem(apsThreeId)\r\n    Particle.removeParticleSystem(apsFourId)\r\nend\r\n\r\nfunction closeSteleInfo()\r\n\tif (bubbleSteleInfoId ~= nil  and bubbleSteleInfoId ~= 0) then BubbleText.close(bubbleSteleInfoId) end\r\nend\r\n\r\nfunction onSteleInfoClosed()\r\n\tif (bubbleSteleInfoId ~= nil  and bubbleSteleInfoId ~= 0) then bubbleSteleInfoId = 0 end\r\nend\r\n\r\nfunction updateSteleInfo(stateInfoId, forceDisplayUI)\r\n\r\n\tif (bubbleSteleInfoId == 0) then\r\n\t\tbubbleSteleInfoId = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_WEST\", 0, -60, false, 2147483647, true, \"interactiveBubbleDialog5\", 30000, 25000, \"onSteleInfoClosed\")\r\n\tend\r\n\r\n\tBubbleText.setText(bubbleSteleInfoId, stateInfoId)\r\n\t\r\n\tif (forceDisplayUI) then BubbleText.show(bubbleSteleInfoId) end\r\nend\n\n-- [INIT] Variables Globales\n-- \nfunction event_2567_22740()\n    \nend\n\n-- [INIT] Inscription du joueur + Variables Locales\n-- \nfunction event_2567_22741()\n    displayDoor()\nend\n\n-- INTERACTIVE_ELEMENT_ACTIVATION - Ouverture de la porte\n-- \nfunction event_2567_22747()\n    trace(\"OUVERTURE DE LA PORTE\")\r\n    \r\n    hideDoor()\nend\n\n-- CLIENT_TRIGGERED_EVENT - Le boss apparaît (déjà vaincu)\n-- \nfunction event_2567_22765(bossId)\n    function customSkip()\r\n    \tMobile.setMobileVisible(bossId, true)\r\n    \tMobile.setMobilePosition(bossId, -12, 1, 0)\r\n    \tskipCinematic()\r\n    end\r\n    \r\n    local playerId = Context.getLeaderId()\r\n    local bossId = toLong(bossId)\r\n    local torossId = createActor(1113105589, -17, 1, 8, 4, 1, 15)\r\n    local fakeTorossId = createActor(119405596, -18, 1, 11, 4, 1, 8)\r\n    \r\n    Mobile.setMobileVisible(bossId, false)\r\n    Mobile.setMobileAnimation(torossId, \"AnimAssis-Statique\")\r\n    \r\n    startCinematicContext(1.0, playerId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"customSkip\")\r\n    \r\n    invoke_custom(00010, 1, \"Camera.setZoomSpeedFactor\", 10000)\r\n    invoke_custom(00010, 1, \"Camera.setZoomFactor\", 1.0)\r\n    invoke_custom(00010, 1, \"Camera.attachCameraToMobile\", torossId)\r\n    \r\n    invoke_custom(01000, 1, \"Camera.setZoomSpeedFactor\", 0.02)\r\n    invoke_custom(01000, 1, \"Camera.setZoomFactor\", 1.5)\r\n    \r\n    -- \"Encore toi !\"\r\n    invoke_custom(01000, 1, \"bubble\", fakeTorossId, \"toross.fight.start.dialog.01\")\r\n    invoke_custom(04000, 1, \"clearBubbles\", fakeTorossId)\r\n    \r\n    -- \"Tu as eu beaucoup de chance de sortir vivant{[1*]?e:} de notre dernier combat...\"\r\n    invoke_custom(04000, 1, \"bubble\", fakeTorossId, \"toross.fight.start.dialog.02\")\r\n    invoke_custom(07000, 1, \"Mobile.setMobileAnimation\", torossId, \"AnimSeLeve\")\r\n    invoke_custom(08500, 1, \"clearBubbles\", fakeTorossId)\r\n    \r\n    invoke_custom(09500, 1, \"Mobile.setMobileAnimation\", torossId, \"AnimSort-3-Debut\")\r\n    invoke_custom(09500, 1, \"Particle.addParticleSystem\", -1113181740, -17, 1, 8)\r\n    invoke_custom(10180, 1, \"Mobile.setMobileVisible\", torossId, false)\r\n    \r\n    invoke_custom(10800, 1, \"Mobile.setMobilePosition\", torossId, -12, 1, 0)\r\n    invoke_custom(10800, 1, \"Mobile.setMobileVisible\", torossId, true)\r\n    invoke_custom(10800, 1, \"Mobile.setMobileAnimation\", torossId, \"AnimSort-3-Fin\")\r\n    invoke_custom(10800, 1, \"Particle.addParticleSystem\", -1113181741, -12, 1, 0)\r\n    \r\n    invoke_custom(11500, 1, \"Mobile.setMobileAnimation\", torossId, \"AnimSort-4\")\r\n    invoke_custom(11500, 1, \"Particle.addParticleSystem\", -1113181650, -12, 1, 0)\r\n    \r\n    -- \"Si tu tiens tant que ça à périr, alors viens, je t'attends !!!\"\r\n    invoke_custom(11500, 1, \"bubble\", torossId, \"toross.fight.start.dialog.03\")\r\n    invoke_custom(16300, 1, \"clearBubbles\", torossId)\r\n    \r\n    invoke_custom(16300, 1, \"Camera.attachCameraToMobile\", torossId)\r\n    \r\n    invoke_custom(16800, 1, \"customSkip\")\nend\n\n-- CLIENT_TRIGGERED_EVENT - Le boss apparaît (jamais vaincu ou contexte de la quête)\n-- \nfunction event_2567_22766(bossId)\n    function customSkip()\r\n    \tMobile.setMobileVisible(bossId, true)\r\n    \tMobile.setMobilePosition(bossId, -12, 1, 0)\r\n    \tskipCinematic()\r\n    end\r\n    \r\n    local playerId = Context.getLeaderId()\r\n    local bossId = toLong(bossId)\r\n    local torossId = createActor(1113105589, -17, 1, 8, 4, 1, 15)\r\n    local fakeTorossId = createActor(119405596, -18, 1, 11, 4, 1, 8)\r\n    \r\n    Mobile.setMobileVisible(bossId, false)\r\n    Mobile.setMobileAnimation(torossId, \"AnimAssis-Statique\")\r\n    \r\n    startCinematicContext(1.0, playerId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"customSkip\")\r\n    \r\n    invoke_custom(00010, 1, \"Camera.setZoomSpeedFactor\", 10000)\r\n    invoke_custom(00010, 1, \"Camera.setZoomFactor\", 1.0)\r\n    invoke_custom(00010, 1, \"Camera.attachCameraToMobile\", torossId)\r\n    \r\n    invoke_custom(01000, 1, \"Camera.setZoomSpeedFactor\", 0.02)\r\n    invoke_custom(01000, 1, \"Camera.setZoomFactor\", 1.5)\r\n    \r\n    -- \"Ainsi, tu as réussi à pénétrer dans le Nécromonde.\"\r\n    invoke_custom(01000, 1, \"bubble\", fakeTorossId, \"toross.fight.start.dialog.04\")\r\n    invoke_custom(04500, 1, \"clearBubbles\", fakeTorossId)\r\n    \r\n    -- \"Ce n'est pas banal de voir de l'agitation dans le coin.\"\r\n    invoke_custom(05000, 1, \"bubble\", fakeTorossId, \"toross.fight.start.dialog.05\")\r\n    invoke_custom(08500, 1, \"clearBubbles\", fakeTorossId)\r\n    \r\n    -- \"Je suppose que tu ne mesures pas encore la gravité de l'action que tu viens d'entreprendre.\"\r\n    invoke_custom(09000, 1, \"bubble\", fakeTorossId, \"toross.fight.start.dialog.06\")\r\n    invoke_custom(14500, 1, \"clearBubbles\", fakeTorossId)\r\n    \r\n    -- \"En pénétrant dans mon palais, tu viens de t'assurer une fin tragique.\"\r\n    invoke_custom(15000, 1, \"bubble\", fakeTorossId, \"toross.fight.start.dialog.07\")\r\n    invoke_custom(18500, 1, \"Mobile.setMobileAnimation\", torossId, \"AnimSeLeve\")\r\n    invoke_custom(20500, 1, \"clearBubbles\", fakeTorossId)\r\n    \r\n    invoke_custom(20500, 1, \"Mobile.setMobileAnimation\", torossId, \"AnimSort-3-Debut\")\r\n    invoke_custom(20500, 1, \"Particle.addParticleSystem\", -1113181740, -17, 1, 8)\r\n    invoke_custom(21180, 1, \"Mobile.setMobileVisible\", torossId, false)\r\n    \r\n    invoke_custom(21900, 1, \"Mobile.setMobilePosition\", torossId, -12, 1, 0)\r\n    invoke_custom(21900, 1, \"Mobile.setMobileVisible\", torossId, true)\r\n    invoke_custom(21900, 1, \"Mobile.setMobileAnimation\", torossId, \"AnimSort-3-Fin\")\r\n    invoke_custom(21900, 1, \"Particle.addParticleSystem\", -1113181741, -12, 1, 0)\r\n    \r\n    invoke_custom(22600, 1, \"Mobile.setMobileAnimation\", torossId, \"AnimSort-4\")\r\n    invoke_custom(22600, 1, \"Particle.addParticleSystem\", -1113181650, -12, 1, 0)\r\n    \r\n    -- \"Je vais te montrer ce qu'il en coûte de se frotter à moi. Approche !\"\r\n    invoke_custom(22600, 1, \"bubble\", torossId, \"toross.fight.start.dialog.08\")\r\n    invoke_custom(27100, 1, \"clearBubbles\", torossId)\r\n    \r\n    invoke_custom(27100, 1, \"Camera.attachCameraToMobile\", playerId)\r\n    \r\n    invoke_custom(27600, 1, \"customSkip\")\nend\n\n-- MONSTER_ACTION_EVENT - Lancement du combat\n-- \nfunction event_2567_22774()\n    \nend\n\n-- FIGHT_ENDED_IN_CLIENT_EVENT - Salle 01 - BOSS - ACH 5276 OBJ 10958\n-- \nfunction event_2567_22758()\n    local playerId = Context.getLeaderId()\r\n    local bossId = createActor(1113105589, -12, 1, 0, 1)\r\n    \r\n    Mobile.setMobilePosition(playerId, -10, 1, 0)\r\n    Mobile.setMobileDirection(playerId, 5)\r\n    Mobile.setMobilePosition(bossId, -12, 1, 0)\r\n    Mobile.setMobileDirection(bossId, 1)\r\n    \r\n    Mobile.setMobileAnimation(bossId, \"AnimMort-Boucle-P2\")\r\n    \r\n    startCinematicContext(1.3, playerId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 22758)\r\n    \r\n    -- \"Je t'ai vaincu Toross, tu es à ma merci !\"\r\n    invoke_custom(01000, 1, \"bubble\", playerId, \"quest.necromonde.19\")\r\n    invoke_custom(01000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Pointer\")\r\n    invoke_custom(04500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"C'est impossible... IMPOSSIBLE !!!\"\r\n    invoke_custom(04500, 1, \"bubble\", bossId, \"quest.necromonde.20\")\r\n    invoke_custom(08500, 1, \"clearBubbles\", bossId)\r\n    \r\n    -- \"Je ne peux pas être vaincu... Je suis Toross Mordal...\"\r\n    invoke_custom(08500, 1, \"bubble\", bossId, \"quest.necromonde.21\")\r\n    invoke_custom(13000, 1, \"clearBubbles\", bossId)\r\n    \r\n    -- \"Je vais t'ÉCRASER !!!\"\r\n    invoke_custom(13000, 1, \"bubble\", bossId, \"quest.necromonde.22\")\r\n    invoke_custom(14000, 1, \"Mobile.setMobileAnimation\", bossId, \"AnimSort-Final-P2\")\r\n    invoke_custom(15000, 1, \"Particle.addParticleSystem\", -1113181654, -12, 1, 0)\r\n    invoke_custom(16500, 1, \"Particle.addParticleSystem\", -1113181659, -12, 1, 0)\r\n    invoke_custom(16000, 1, \"clearBubbles\", bossId)\r\n    \r\n    invoke_custom(16000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimIncarnam-Chute-Debut\")\r\n    invoke_custom(16200, 1, \"Particle.addParticleSystem\", -1113181730, -10, 1, 0)\r\n    \r\n    invoke_custom(17000, 1, \"UI.displayWideScreenBand\", true, 100, 1000)\r\n    \r\n    invoke_custom(18500, 1, \"skipCinematic\", 22758)\nend\n\n-- CLIENT_TRIGGERED_EVENT - Le joueur se TP hors du donjon - ACH 5276 OBJ 10966\n-- \nfunction event_2567_22760()\n    \nend\n\n-- [FIGHT] Victoire du combat - Toross a 0 PW\n-- \nfunction event_2567_22749()\n    \nend\n\n-- [FIGHT] Victoire du combat - Toross a 10 PW\n-- \nfunction event_2567_22750()\n    \nend\n\n-- [OLD][STELE] Le joueur examine une stèle\n-- \nfunction event_2567_22743(steleCount, steleStateId)\n    local steleCount = toLong(steleCount)\r\n    local steleStateId = toLong(steleStateId)\r\n    local stateInfoId = \"stele.state.description.\" .. toString(steleStateId)\r\n    \r\n    if (steleCount == 0) then\r\n    \tUI.openRewardsDialog(\"stele.description.tour\")\r\n    \tUI.addReward(31555, \"stele.reward.stasis.21\")\r\n    elseif (steleCount == 1) then\r\n    \tUI.openRewardsDialog(\"stele.description.tour\")\r\n    \tUI.addReward(31557, \"stele.reward.stasis.21\")\r\n    elseif (steleCount == 2) then\r\n    \tUI.openRewardsDialog(\"stele.description.tour\")\r\n    \tUI.addReward(31559, \"stele.reward.stasis.21\")\r\n    elseif (steleCount == 3) then\r\n    \tUI.openRewardsDialog(\"stele.description.tour\")\r\n    \tUI.addReward(31561, \"stele.reward.stasis.21\")\r\n    end\r\n    \r\n    UI.addReward(27083, \"stele.reward.stasis.21\")\r\n    \r\n    updateSteleInfo(stateInfoId, true)\nend\n\n-- [OLD][STELE] Le joueur active une stèle\n-- \nfunction event_2567_22744(steleCount, steleStateId)\n    local steleCount = toLong(steleCount)\r\n    local steleStateId = toLong(steleStateId)\r\n    local stateInfoId = \"stele.state.description.\" .. toString(steleStateId)\r\n    \r\n    if (steleCount == 1) then\r\n    \tUI.openRewardsDialog(\"stele.description.tour\")\r\n    \tUI.addReward(31555, \"stele.reward.stasis.21\")\r\n    elseif (steleCount == 2) then\r\n    \tUI.openRewardsDialog(\"stele.description.tour\")\r\n    \tUI.addReward(31557, \"stele.reward.stasis.21\")\r\n    elseif (steleCount == 3) then\r\n    \tUI.openRewardsDialog(\"stele.description.tour\")\r\n    \tUI.addReward(31559, \"stele.reward.stasis.21\")\r\n    elseif (steleCount == 4) then\r\n    \tUI.openRewardsDialog(\"stele.description.tour\")\r\n    \tUI.addReward(31561, \"stele.reward.stasis.21\")\r\n    end\r\n    \r\n    UI.addReward(27083, \"stele.reward.stasis.21\")\r\n    \r\n    updateSteleInfo(stateInfoId, true)\nend\n\n-- [OLD][FIGHT] Défaite du combat - Reset les stèles\n-- \nfunction event_2567_22742()\n    \nend\n\n-- [OLD][STELE] Refresh des APS pour Stèles\n-- \nfunction event_2567_22745()\n    \nend\n\n-- [STASIS] DUNGEON_DIFFICULTY_CHANGED - Reset les stèles\n-- \nfunction event_2567_22746()\n    \nend\n\n-- [STELE] FIGHT_STARTED - On applique les difficultés stèles\n-- \nfunction event_2567_22778()\n    \nend\n\n-- [STELE] FIGHT_ENTER_ACTION_PHASE - On applique les bonus sur les joueurs\n-- \nfunction event_2567_22780()\n    \nend\n\n-- [STELE] FIGHT_ENDED - On rend la stèle utilisable en cas de défaite\n-- \nfunction event_2567_23321()\n    \nend\n\n-- [EVENT] Mort de Tauross\n-- EFFECT_EXECUTION car USER_GROUP_KILLED ne fonctionne pas bien avec le fightModel\nfunction event_2567_23372()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","displayDoor","hideDoor","closeSteleInfo","onSteleInfoClosed","updateSteleInfo","event_2567_22740","event_2567_22741","event_2567_22747","event_2567_22765","customSkip","event_2567_22766","customSkip","event_2567_22774","event_2567_22758","event_2567_22760","event_2567_22749","event_2567_22750","event_2567_22743","event_2567_22744","event_2567_22742","event_2567_22745","event_2567_22746","event_2567_22778","event_2567_22780","event_2567_23321","event_2567_23372"],"quest_calls":["UI.openRewardsDialog(\"stele.description.tour\")\r","UI.openRewardsDialog(\"stele.description.tour\")\r","UI.openRewardsDialog(\"stele.description.tour\")\r","UI.openRewardsDialog(\"stele.description.tour\")\r","UI.openRewardsDialog(\"stele.description.tour\")\r","UI.openRewardsDialog(\"stele.description.tour\")\r","UI.openRewardsDialog(\"stele.description.tour\")\r","UI.openRewardsDialog(\"stele.description.tour\")\r"],"dialogue_calls":[]},"scenario/2568.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\nfunction customSkip(eventActionId)\r\n\tMobile.hideOtherPlayerMobile(false)\r\n\r\n\tskipCinematic(eventActionId)\r\nend\n\n-- [INIT] Variables Globales\n-- \nfunction event_2568_22753()\n    \nend\n\n-- [INIT] Inscription du joueur + Variables Locales\n-- \nfunction event_2568_22754()\n    \nend\n\n-- POSITION_TRIGGER_ACTIVATION_EVENT - Cinématique d'activation de la stèle - ACH 5276 OBJ 10955\n-- \nfunction event_2568_22755()\n    local playerId = Context.getLeaderId()\r\n    local otomaiId = createActor(181404009, -120, 13, -30,4, 3, 10)\r\n    \r\n    Mobile.moveMobile(playerId, -120, 25, -45)\r\n    Mobile.setMobileDirection(playerId, 5)\r\n    \r\n    Mobile.hideOtherPlayerMobile(true)\r\n    Mobile.setMobileVisible(otomaiId, false)\r\n    \r\n    startCinematicContext(1.2, playerId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"customSkip\", 22755)\r\n    \r\n    invoke_custom(02000, 1, \"Camera.setZoomFactor\", 1.2)\r\n    invoke_custom(02000, 1, \"Camera.attachCameraToMobile\", otomaiId)\r\n    invoke_custom(02000, 1, \"Mobile.setMobileVisible\", otomaiId, true)\r\n    invoke_custom(02000, 1, \"Mobile.setMobileAnimationSuffix\", otomaiId, \"-Oiseau\")\r\n    invoke_custom(02000, 1, \"Mobile.setMobileMovementStyle\", otomaiId, \"TRAJECTORY\", \"TRAJECTORY\", false)\r\n    invoke_custom(02000, 1, \"Mobile.addCubicSplineTweenToMobile\", otomaiId, -120, 24, -45, 3000, 0, 0, 0, -1, 0, -20)\r\n    \r\n    invoke_custom(03000, 1, \"Mobile.setMobileDirection\", playerId, 7)\r\n    \r\n    invoke_custom(05000, 1, \"Mobile.setMobileMovementStyle\", otomaiId, \"WALK\", \"RUN\", false)\r\n    invoke_custom(05000, 1, \"Particle.addParticleSystem\", -1814057072, -120, 24, -45)\r\n    invoke_custom(05500, 1, \"Mobile.setMobileAnimationSuffix\", otomaiId, \"\")\r\n    invoke_custom(05501, 1, \"Mobile.setMobileAnimation\", otomaiId, \"AnimStatique\")\r\n    invoke_custom(05501, 1, \"Camera.setMoveSpeedFactor\", 2.1)\r\n    invoke_custom(05502, 1, \"Camera.setCamera\", 1.4, -120, 24, -45)\r\n    invoke_custom(05503, 1, \"Mobile.setMobileAnimation\", otomaiId, \"AnimComp-Special06\")\r\n    \r\n    -- \"Ah, te revoilà !\"\r\n    invoke_custom(06000, 1, \"bubble\", playerId, \"quest.necromonde.01\")\r\n    invoke_custom(06000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Rire\")\r\n    invoke_custom(08500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"J’ai discuté avec Frida Mofette. Elle m'a donné son aval pour qu'on puisse utiliser autant de Stasis qu'on le souhaite !\"\r\n    invoke_custom(08500, 1, \"bubble\", playerId, \"quest.necromonde.02\")\r\n    invoke_custom(08500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Pointer\")\r\n    invoke_custom(15500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Il ne faut juste pas faire de dégâts dans la mine...\"\r\n    invoke_custom(15500, 1, \"bubble\", playerId, \"quest.necromonde.03\")\r\n    invoke_custom(15500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Pouce\")\r\n    invoke_custom(18500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Parfait ! On va en avoir besoin d’une sacrée quantité, j’espère que tu es prêt.\"\r\n    invoke_custom(18500, 1, \"bubble\", otomaiId, \"quest.necromonde.04\")\r\n    invoke_custom(18500, 1, \"Mobile.setMobileAnimation\", otomaiId, \"AnimComp-Special07\")\r\n    invoke_custom(23000, 1, \"clearBubbles\", otomaiId)\r\n    \r\n    invoke_custom(22000, 1, \"Mobile.setMobileMovementStyle\", playerId, \"WALK\", \"WALK\")\r\n    \r\n    invoke_custom(21500, 1, \"Mobile.moveMobile\", playerId, -120, 26, -45)\r\n    invoke_custom(22500, 1, \"Mobile.setMobileDirection\", playerId, 7)\r\n    \r\n    invoke_custom(22000, 1, \"Mobile.setMobileMovementStyle\", otomaiId, \"WALK\", \"WALK\")\r\n    invoke_custom(22000, 1, \"Mobile.moveMobile\", otomaiId, -120, 25, -45)\r\n    \r\n    invoke_custom(23000, 1, \"Mobile.setMobileDirection\", otomaiId, 5)\r\n    \r\n    -- \"Voyons voir...\"\r\n    invoke_custom(23000, 1, \"bubble\", otomaiId, \"quest.necromonde.05\")\r\n    invoke_custom(23000, 1, \"Mobile.setMobileAnimation\", otomaiId, \"AnimComp-Special03\")\r\n    invoke_custom(25500, 1, \"clearBubbles\", otomaiId)\r\n    \r\n    -- \"Peut-être qu'en faisant ça comme ça...\"\r\n    invoke_custom(25500, 1, \"bubble\", otomaiId, \"quest.necromonde.06\")\r\n    invoke_custom(26000, 1, \"Camera.setZoomFactor\", 1.6)\r\n    invoke_custom(25500, 1, \"Mobile.setMobileAnimation\", otomaiId, \"AnimComp-Special04-Debut\")\r\n    invoke_custom(25740, 1, \"Mobile.setMobileAnimation\", otomaiId, \"AnimComp-Special04-Boucle\")\r\n    invoke_custom(26456, 1, \"Mobile.setMobileAnimation\", otomaiId, \"AnimComp-Special04-Boucle\")\r\n    invoke_custom(30000, 1, \"clearBubbles\", otomaiId)\r\n    \r\n    invoke_custom(31000, 1, \"Effect.createCameraShakeEffect\", 100, 6000, 100, 5, 100, \"BOTH\")\r\n    invoke_custom(33000, 1, \"Particle.addParticleSystem\", 800573, -121, 25, -44)\r\n    \r\n    invoke_custom(37000, 1, \"Mobile.setMobileAnimation\", otomaiId, \"AnimComp-Special02\")\r\n    \r\n    -- \"Pfiou, on dirait bien que ça a fonctionné !\"\r\n    invoke_custom(40000, 1, \"Mobile.setMobileDirection\", otomaiId, 3)\r\n    invoke_custom(40500, 1, \"bubble\", otomaiId, \"quest.necromonde.07\")\r\n    invoke_custom(44000, 1, \"clearBubbles\", otomaiId)\r\n    \r\n    -- \"Essayons d'interagir avec...\"\r\n    invoke_custom(44000, 1, \"bubble\", otomaiId, \"quest.necromonde.08\")\r\n    invoke_custom(44000, 1, \"Mobile.setMobileAnimation\", otomaiId, \"AnimComp-Special07\")\r\n    invoke_custom(46500, 1, \"clearBubbles\", otomaiId)\r\n    \r\n    invoke_custom(47500, 1, \"customSkip\", 22755)\nend\n\n-- CLIENT_TRIGGERED_EVENT - La cinématique d'activation de la stèle est terminée chez tout le monde\n-- \nfunction event_2568_22759()\n    \nend\n\n-- CHARACTER_ENTER_INSTANCE_EVENT - Cinématique de retour du Nécromonde - ACH 5276 OBJ 10966\n-- \nfunction event_2568_22761()\n    local playerId = Context.getLeaderId()\r\n    \r\n    Mobile.hideOtherPlayerMobile(true)\r\n    Mobile.setMobileVisible(playerId, false)\r\n    \r\n    startCinematicContext(1.2, playerId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"customSkip\")\r\n    \r\n    Camera.setZoomFactor(1.2)\r\n    UI.displayWideScreenBand(true, 100, 0)\r\n    \r\n    invoke_custom(01000, 1, \"UI.displayWideScreenBand\", false, 25, 300)\r\n    invoke_custom(01900, 1, \"UI.displayWideScreenBand\", true)\r\n    invoke_custom(01000, 1, \"Camera.setZoomFactor\", 1.2)\r\n    \r\n    invoke_custom(02000, 1, \"Mobile.setMobileDirection\", playerId, 7)\r\n    \r\n    invoke_custom(03000, 1, \"Mobile.setMobileVisible\", playerId, true)\r\n    \r\n    invoke_custom(03000, 1, \"Mobile.setMobileDirection\", playerId, 1)\r\n    invoke_custom(03000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimIncarnam-Chute-Fin\")\r\n    \r\n    invoke_custom(05000, 1, \"Mobile.setMobileDirection\", playerId, 3)\r\n    invoke_custom(06000, 1, \"Mobile.setMobileDirection\", playerId, 7)\r\n    \r\n    invoke_custom(07000, 1, \"Mobile.setMobileDirection\", playerId, 1)\r\n    \r\n    -- \"**Qu’est-ce qui m’est arrivé ? On dirait que je me suis échappé du Nécromonde juste avant que Toross puisse me blesser gravement...\"\r\n    invoke_custom(07500, 1, \"bubble\", playerId, \"quest.necromonde.09\")\r\n    invoke_custom(07500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(13500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"**Bon, quoi qu'il en soit, il faut que j’aille en parler à Otomaï !\"\r\n    invoke_custom(13500, 1, \"bubble\", playerId, \"quest.necromonde.10\")\r\n    invoke_custom(13500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Pointer\")\r\n    invoke_custom(17000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(17500, 1, \"customSkip\")\nend\n\n-- POSITION_TRIGGER_ACTIVATION_EVENT - Cinématique de scellement de la stèle - ACH 5276 OBJ 10959\n-- \nfunction event_2568_22763()\n    local playerId = Context.getLeaderId()\r\n    local otomaiId = createActor(181404009, -120, 13, -30,4, 3, 10)\r\n    \r\n    Mobile.moveMobile(playerId, -120, 25, -45)\r\n    Mobile.setMobileDirection(playerId, 5)\r\n    \r\n    Mobile.hideOtherPlayerMobile(true)\r\n    Mobile.setMobileVisible(otomaiId, false)\r\n    \r\n    startCinematicContext(1.2, playerId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"customSkip\", 22763)\r\n    \r\n    invoke_custom(02000, 1, \"Camera.setZoomFactor\", 1.2)\r\n    invoke_custom(02000, 1, \"Camera.attachCameraToMobile\", otomaiId)\r\n    invoke_custom(02000, 1, \"Mobile.setMobileVisible\", otomaiId, true)\r\n    invoke_custom(02000, 1, \"Mobile.setMobileAnimationSuffix\", otomaiId, \"-Oiseau\")\r\n    invoke_custom(02000, 1, \"Mobile.setMobileMovementStyle\", otomaiId, \"TRAJECTORY\", \"TRAJECTORY\", false)\r\n    invoke_custom(02000, 1, \"Mobile.addCubicSplineTweenToMobile\", otomaiId, -120, 24, -45, 3000, 0, 0, 0, -1, 0, -20)\r\n    \r\n    invoke_custom(03000, 1, \"Mobile.setMobileDirection\", playerId, 7)\r\n    \r\n    invoke_custom(05000, 1, \"Mobile.setMobileMovementStyle\", otomaiId, \"WALK\", \"RUN\", false)\r\n    invoke_custom(05000, 1, \"Particle.addParticleSystem\", -1814057072, -120, 24, -45)\r\n    invoke_custom(05500, 1, \"Mobile.setMobileAnimationSuffix\", otomaiId, \"\")\r\n    invoke_custom(05501, 1, \"Mobile.setMobileAnimation\", otomaiId, \"AnimStatique\")\r\n    invoke_custom(05501, 1, \"Camera.setMoveSpeedFactor\", 2.1)\r\n    invoke_custom(05502, 1, \"Camera.setCamera\", 1.4, -120, 24, -45)\r\n    \r\n    -- \"Quelle aventure...\"\r\n    invoke_custom(06000, 1, \"bubble\", playerId, \"quest.necromonde.11\")\r\n    invoke_custom(08500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Comme tu dis !\"\r\n    invoke_custom(08500, 1, \"bubble\", otomaiId, \"quest.necromonde.12\")\r\n    invoke_custom(11000, 1, \"clearBubbles\", otomaiId)\r\n    \r\n    -- \"Mettons fin à toute cette histoire ensemble, c'est la meilleure décision à prendre pour notre monde.\"\r\n    invoke_custom(11000, 1, \"bubble\", otomaiId, \"quest.necromonde.13\")\r\n    invoke_custom(17000, 1, \"clearBubbles\", otomaiId)\r\n    \r\n    -- \"Tu as raison. Nous en avons assez fait avec cette stèle.\"\r\n    invoke_custom(17000, 1, \"bubble\", playerId, \"quest.necromonde.14\")\r\n    invoke_custom(20500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Je te laisse faire.\"\r\n    invoke_custom(20500, 1, \"bubble\", playerId, \"quest.necromonde.15\")\r\n    invoke_custom(22000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(22000, 1, \"Mobile.setMobileMovementStyle\", playerId, \"WALK\", \"WALK\")\r\n    \r\n    invoke_custom(21500, 1, \"Mobile.moveMobile\", playerId, -120, 26, -45)\r\n    invoke_custom(22500, 1, \"Mobile.setMobileDirection\", playerId, 7)\r\n    \r\n    invoke_custom(22000, 1, \"Mobile.setMobileMovementStyle\", otomaiId, \"WALK\", \"WALK\")\r\n    invoke_custom(22000, 1, \"Mobile.moveMobile\", otomaiId, -120, 25, -45)\r\n    \r\n    invoke_custom(23000, 1, \"Mobile.setMobileDirection\", otomaiId, 5)\r\n    \r\n    invoke_custom(23000, 1, \"Mobile.setMobileAnimation\", otomaiId, \"AnimComp-Special03\")\r\n    invoke_custom(26000, 1, \"Camera.setZoomFactor\", 1.6)\r\n    \r\n    invoke_custom(25500, 1, \"Mobile.setMobileAnimation\", otomaiId, \"AnimComp-Special04-Debut\")\r\n    invoke_custom(25740, 1, \"Mobile.setMobileAnimation\", otomaiId, \"AnimComp-Special04-Boucle\")\r\n    invoke_custom(26456, 1, \"Mobile.setMobileAnimation\", otomaiId, \"AnimComp-Special04-Boucle\")\r\n    \r\n    invoke_custom(29000, 1, \"Mobile.setMobileDirection\", otomaiId, 3)\r\n    \r\n    -- \"Ça devrait être bon comme ça ! Personne ne pourra plus y toucher.\"\r\n    invoke_custom(29500, 1, \"bubble\", otomaiId, \"quest.necromonde.16\")\r\n    invoke_custom(29500, 1, \"Mobile.setMobileAnimation\", otomaiId, \"AnimComp-Special07\")\r\n    invoke_custom(33500, 1, \"clearBubbles\", otomaiId)\r\n    \r\n    -- \"Merci pour tout, je suis certain qu'on se reverra très vite !\"\r\n    invoke_custom(33500, 1, \"bubble\", otomaiId, \"quest.necromonde.17\")\r\n    invoke_custom(33500, 1, \"Mobile.setMobileAnimation\", otomaiId, \"AnimComp-Special07\")\r\n    invoke_custom(36000, 1, \"clearBubbles\", otomaiId)\r\n    \r\n    invoke_custom(35000, 1, \"Camera.attachCameraToMobile\", playerId)\r\n    invoke_custom(36500, 1, \"Particle.addParticleSystem\", 800631, -120, 25, -45)\r\n    invoke_custom(36500, 1, \"Mobile.setMobileVisible\", otomaiId, false)\r\n    \r\n    -- \"**Quel sacré personnage...\"\r\n    invoke_custom(37500, 1, \"bubble\", playerId, \"quest.necromonde.18\")\r\n    invoke_custom(40500, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(41000, 1, \"Mobile.setMobileDirection\", playerId, 1)\r\n    \r\n    invoke_custom(41500, 1, \"customSkip\", 22763)\nend\n\n-- CLIENT_TRIGGERED_EVENT - La cinématique de scellement de la stèle est terminée chez tout le monde\n-- \nfunction event_2568_22764()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","customSkip","event_2568_22753","event_2568_22754","event_2568_22755","event_2568_22759","event_2568_22761","event_2568_22763","event_2568_22764"],"quest_calls":[],"dialogue_calls":[]},"scenario/2569.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n-- TRIGGER CLIENT --\r\n-- 0 = Fin cinématique VIDEO | Déclenché par le callback Video.addVideoStopOrEndCallback\r\n-- 1 = Arrivée dans l'instance | Déclenché par onInstanceLoaded() callback par Event.runOnInstanceLoaded (cf code Global)\r\n-- 2 = Fin cinématique | Déclenché par stopCinematicContext() (cf code Global)\r\n-- 3 = Fermeture UI Fin de combat\r\n-- 4 = Clic sur le bon bouton de changement d'oriention (parmis les 4) dans UI worldAndFightBar pour s'orientation vers le monstre\r\n-- 5 = Fermeture UI Fiche combattant\r\n-- 6 = Clic sur le bouton de validation de la répartition dans UI Aptitudes\r\n-- 7 = Clic sur la boussole du bon objectif dans l'UI suivi de quête\r\n-- 8 = Fermeture UI Map Monde\r\n\r\n-- VARIABLE GLOBALE - SCRIPT --\r\n\r\nwidget_visible = {}\r\nwidget_enable = {}\r\nui_tweens = {}\r\nui_particles = {}\r\nui_listener_load = {}\r\nui_listener_unload = {}\r\nui_listener_event = {}\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\nscreenEffectId = nil\r\n\r\n-- VARIABLE GLOBALE - MOBILE CINEMATIQUE & TUTO --\r\n\r\nANM_otomai = {think=\"AnimComp-Special03\", talk=\"AnimComp-Special04-Debut\", show=\"AnimComp-Special05-Debut\", nice=\"AnimComp-Special07\", nope=\"AnimComp-Special08\", lol=\"AnimComp-Special09\", stop_it=\"AnimComp-Special10\", come_here=\"AnimComp-Special01\", wave_hit=\"AnimComp-Special02\", fly=\"AnimStatique-Oiseau\", cast=\"AnimSort-01\", supercast=\"AnimComp-Special11\", attack=\"AnimSort-Cast\", balance=\"AnimComp-Special06\"}\r\nANM_melee = {attack=\"AnimSort-Morsure\", glitch1=\"AnimComp-Glitch01\", glitch2=\"AnimComp-Glitch02\", glitch3=\"AnimComp-Glitch03\", roar=\"AnimComp-Agressif\"}\r\nANM_range = {attack=\"AnimSort-01\", glitch=\"AnimComp-Glitch\", dupli=\"AnimComp-Dupli\"}\r\nANM_boss = {attack1=\"AnimSort-Estoc\", attack2=\"AnimSort-Hrargh\", glitch=\"AnimComp-Glitch\", dupli=\"AnimComp-Dupli\", roar=\"AnimComp-Hurle\", ko = \"AnimKO-SortieOK\", death= \"AnimKO-SortieHS\"}\r\n\r\nNPC_otomai = Mobile.generateClientMobileId()\r\nNPC_otomai_gfx = 181404009\r\nNPC_otomai_particleZ = 10\r\nNPC_otomai_bubbleX = 10\r\nNPC_otomai_bubbleY = 70\r\n\r\nNPC_melee = Mobile.generateClientMobileId()\r\nNPC_meleeB = Mobile.generateClientMobileId()\r\nNPC_melee_gfx = 181404014\r\nNPC_melee_particleZ = 5\r\n\r\nNPC_range = Mobile.generateClientMobileId()\r\nNPC_range_gfx = 181404015\r\nNPC_range_particleZ = 3\r\n\r\nNPC_boss = Mobile.generateClientMobileId()\r\nNPC_boss_gfx = 181404012\r\nNPC_boss_particleZ = 8\r\n\r\nNPC_eni_wakfu = Mobile.generateClientMobileId()\r\nNPC_eni_wakfu_gfx = 181404034\r\nNPC_eni_wakfu_particleZ = 7\r\n\r\nNPC_eni_stasis = Mobile.generateClientMobileId()\r\nNPC_eni_stasis_gfx = 181404013\r\nNPC_eni_stasis_particleZ = 7\r\n\r\n_ACTOR_LIST = {NPC_otomai, NPC_melee, NPC_meleeB, NPC_range, NPC_boss, NPC_eni_wakfu, NPC_eni_stasis}\r\n\r\n-- VARIABLE GLOBALE - PARTICULE CINEMATIQUE & TUTO --\r\n\r\n-- UI TUTO\r\napsArrowBig = {6001069,6001070,6001071,6001072,6001073,6001074,6001075,6001076}\r\napsArrow = {6001061,6001062,6001063,6001064,6001065,6001066,6001067,6001068}\r\napsCenter = {ap=6001090, mp=6001091, wp=6001092, hp=6001093}\r\napsFollowBorder = -1548037644\r\n-- WORLD TUTO\r\napsCell = {white_border=800578, red_border=800579, white_arrow=800576, red_arrow=800577, white=800581, red=800582, show=78900}\r\n-- CINEMATIQUE\r\napsWave = {spawn=800573, wave=800574, hit=800575}\r\napsOtomai = {shield=-1814057071, transform=-1814057072, playershield = -1814057074}\r\napsCristal = {base=71071022, react=800580, shield=71071021}\r\napsBoss = {death=-1814057073}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n    for index, value in ipairs (tab) do\r\n\t\tif isEqual(value, val) then\r\n            return true\r\n        end\r\n    end\r\n\r\n    return false\t\r\nend\r\n\r\n-- FONCTION UI -- Replace le Chat en bas à gauche et le rend indéplaçable/déplaçable\r\nfunction prepareChatUI(movable, chatOffsetX)\r\n\tif not UI.isDialogLoaded(\"chatDialog0\") then return end\r\n\t\r\n\tif (not chatOffsetX) then chatOffsetX = 0 end\r\n\t\r\n\tUI.setPosition(\"chatDialog0\", chatOffsetX, 0)\r\n\tUI.setWindowMovable(\"chatDialog0\", movable)\r\nend\r\n\r\n-- FONCTION UI -- Replace le Suivi de Quête mi-hauteur à gauche et le rend indéplaçable/déplaçable\r\nfunction prepareFollowQuestUI(movable)\r\n    local dialogName = \"\"\r\n    if UI.isDialogLoaded(\"verticalFollowedAchievementsDialog\") then\r\n        dialogName = \"verticalFollowedAchievementsDialog\"\r\n    end\r\n    if UI.isDialogLoaded(\"followedAchievementsDialog\") then\r\n        dialogName = \"followedAchievementsDialog\"\r\n    end\r\n\r\n    if (dialogName == \"\") then\r\n        return\r\n    end\r\n\r\n    local screenH, screenW = UI.getWindowSize()\r\n    local x, y = UI.getPosition(dialogName)\r\n\r\n    UI.setPosition(dialogName, x, screenH / 4)\r\n    UI.setWindowMovable(dialogName, movable)\r\nend\r\n\r\n-- FONCTION UI -- Rend Visible/Invisible certains éléments des interfaces\r\nfunction prepareUI(visible)\r\n  --Interface Boutique & Cadeau\r\n  setWidgetVisible(\"topHudDialog\", \"optionShopButton\", visible)\r\n  setWidgetVisible(\"topHudDialog\", \"giftButton\", visible)\r\n\r\n  --UI sous le Coeur\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"wakfuStasisBar\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"xpBar\", visible)\r\n\r\n  --Boutons hors combat à droite du Coeur\r\n  setWidgetVisible(\"shortcutBarDialog\", \"previousButton\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"nextButton\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseShortcutBar1\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseShortcutBar2\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseShortcutBar3\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseShortcutBar4\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"shortcutBarItemButton\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"shortcutBarSpellButton\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseButtonContainerForTuto1\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseButtonContainerForTuto2\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseButtonContainerForTuto3\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseButtonContainerForTuto4\", visible)\r\n\r\n  --Boutons hors combat à gauche de l'écran - barre d'interfaces\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"firstInterfaceBarBackground\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"secondInterfaceBarBackground\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"extraInterfaceBarDrawerButton\", visible)\r\n\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"fightInfoBtn\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"inventoryButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"buildSheetSetButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"craftButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"questsButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"dungeonButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"cosmeticsButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"tutorialBookButton\", visible)\r\n\r\n  --Boutons hors combat à gauche de l'écran - barre d'interfaces (deuxième barre)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"contactListButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"guildButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"companionsButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"nationButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"battlegroundButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"passportButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"emoteButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"encyclopediaButton\", visible)\r\n\r\n  --Boutons hors combat \"actions rapides\"\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"OverWorldActionsBackground\", visible)\r\n\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"dimensionalBagButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"mapButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"rideMountButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"miniMapButton\", visible)\r\n\r\n  --Boutons en combat à gauche du Coeur\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"FightActionsBackground\", visible)\r\n\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"giveUpButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"hideFightersButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"tacticalModeBtn\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"reportCellBtn\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"fightMarkerBtn\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"lockFightBtn\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"resistanceOverheadBtn\", visible)\r\nend\r\n\r\n-- FONCTION SHORTCUT -- Rend Actif/Inactif certains raccourcis\r\nfunction prepareShortcuts(enabled, shortcutType)\r\n  if not shortcutType or shortcutType == \"WORLD\" then\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.world\", \"enterLeaveBag\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.world\", \"switchHero0\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.world\", \"switchHero1\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.world\", \"switchHero2\")\r\n  end\r\n  if not shortcutType or shortcutType == \"DISPLAY\" then\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"zoomIn\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"zoomOut\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"closeWindows\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"setLODLevel\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"setFightLODLevel\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"showHideNameOverheadsCommand\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"hideFightOccluders\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"alphaMask\")\r\n  end\r\n  if not shortcutType or shortcutType == \"CHAT\" then\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.chat\", \"chat\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.chat\", \"lastContact\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.chat\", \"firstContact\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.chat\", \"autoCompletePlayerName\")\r\n    for bind=1, 9, 1 do\r\n      UI.setShortcutEnabled(enabled, \"shortcutCategory.shortcutBar\", \"bind\" .. toString(bind))\r\n    end\r\n  end\r\n\r\n  if not shortcutType or shortcutType == \"FIGHT\" then\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"fighterTransparency\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"switchTacticalView\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"nextSelectedFighter\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"giveUp\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"lockFight\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"reportCell\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"callHelp\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"displayHpBar\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"resetFightCamera\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"endPlacementAndTurn\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"closeCombatRight\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"closeCombatLeft\")\r\n  end\r\n  if not shortcutType or shortcutType == \"INTERFACE\" then\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"minimap\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"contactList\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"companionManagement\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"guild\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"craft\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"dungeonList\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"achievements\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"quests\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"emotes\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"ecosystem\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"climate\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"nation\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"partySearch\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"passport\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"almanax\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"tutorialBook\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"switchToDirectAttackCommand\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"map\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"spellsInventory\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"inventory\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"characterBook\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"osamodasSymbiot\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"shortcutBar0\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"shortcutBar1\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"shortcutBar2\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"shortcutBar3\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"additionalShortcutBar0\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"additionalShortcutBar1\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"additionalShortcutBar2\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"additionalShortcutBar3\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"changeShortcutBarType\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"downscaling\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"rewards\")\r\n\tUI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"battlegroundList\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"aptitudes\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"presets\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"encyclopedia\")\r\n  end\r\n\r\n  -- On ne bloque pas les raccourcis de sorts finalement\r\n--   if not shortcutType or shortcutType == \"SHORTCUTBAR\" then\r\n--     for bar=0,3, 1 do\r\n--       for slot=0, 9, 1 do\r\n--         UI.setShortcutEnabled(enabled, \"shortcutCategory.shortcutBar\", \"shortcut\" .. toString(bar) .. toString(slot))\r\n--       end\r\n--     end\r\n--   end\r\nend\r\n\r\n-- FONCTION UI -- Rend Visible/Invisible un élément d'une interface\r\nfunction setWidgetVisible(dialogName, widgetName, visible)\r\n  if not UI.isDialogLoaded(dialogName) then return end\r\n\r\n  UI.setWidgetVisibility(dialogName, widgetName, visible)\r\n  table.insert(widget_visible, { name = dialogName, id = widgetName, state = visible })\r\nend\r\n\r\nfunction clearWidgetVisible()\r\n  local str = \"\"\r\n  for i=#widget_visible, 1, -1 do\r\n    str = str .. toString(widget_visible[i].name) .. \"@\" .. toString(widget_visible[i].id) .. \";\"\r\n    UI.setWidgetVisibility(widget_visible[i].name, widget_visible[i].id, true)\r\n  end\r\n\r\n  widget_visible = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearWidgetVisible\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Rend Actif/Inactif un élément d'une interface\r\nfunction setWidgetEnable(dialogName, widgetName, enable)\r\n  if not UI.isDialogLoaded(dialogName) then return end\r\n\r\n  UI.setWidgetEnabled(dialogName, widgetName, enable)\r\n  table.insert(widget_enable, {name = dialogName, id = widgetName, state = enable})\r\nend\r\n\r\nfunction clearWidgetEnable()\r\n  local str = \"\"\r\n  for i=#widget_enable, 1, -1 do\r\n    str = str .. toString(widget_enable[i].name) .. \"@\" .. toString(widget_enable[i].id) .. \";\"\r\n    UI.setWidgetEnabled(widget_enable[i].name, widget_enable[i].id, true)\r\n  end\r\n\r\n  widget_enable = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearWidgetEnable\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Ajoute/Retire une TweenParticle à un élément d'une interface\r\nfunction setUIColorTween(dialogName, widgetName, duration, loop, r1, g1, b1, a1, r2, g2, b2, a2)\r\n  if not UI.isDialogLoaded(dialogName) then return end\r\n\r\n  UI.addColorTween(dialogName, widgetName, duration, loop, r1, g1, b1, a1, r2, g2, b2, a2)\r\n  table.insert(ui_tweens, {name = dialogName, id = widgetName})\r\nend\r\n\r\nfunction clearUIColorTweens(dialogName, widgetName)\r\n  local str = \"\"\r\n  for i=#ui_tweens, 1, -1 do\r\n    if ((not dialogName) or (dialogName == ui_tweens[i].name)) and ((not widgetName) or (widgetName == ui_tweens[i].id)) then\r\n      str = str .. toString(ui_tweens[i].name) .. \"@\" .. toString(ui_tweens[i].id) .. \";\"\r\n      UI.removeColorTween(ui_tweens[i].name, ui_tweens[i].id)\r\n      table.remove(ui_tweens, i)\r\n    end\r\n  end\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearUIColorTweens\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Ajoute/Retire une Particle à un élément d'une interface\r\nfunction setUIParticle(dialogName, widgetName, apsFileName, x, y, alignment, level)\r\n  if not UI.isDialogLoaded(dialogName) then return end\r\n\r\n  local particleId = UI.addParticle(dialogName, widgetName, apsFileName, x, y, alignment, level)\r\n  table.insert(ui_particles, {name = dialogName, id = widgetName})\r\n\r\n  return particleId\r\nend\r\n\r\nfunction setUIParticleBorder(dialogName, widgetName, apsFileName, x, y, alignment, level, speed)\r\n  if not UI.isDialogLoaded(dialogName) then return end\r\n\r\n  local particleId = UI.addParticleToBorder(dialogName, widgetName, apsFileName, x, y, alignment, level, speed)\r\n  table.insert(ui_particles, {name = dialogName, id = widgetName})\r\n\r\n  return particleId\r\nend\r\n\r\nfunction clearUIParticles(dialogName, widgetName)\r\n  local str = \"\"\r\n  for i=#ui_particles, 1, -1 do\r\n    if ((not dialogName) or (dialogName == ui_particles[i].name)) and ((not widgetName) or (widgetName == ui_particles[i].id)) then\r\n      str = str .. toString(ui_particles[i].name) .. \"@\" .. toString(ui_particles[i].id) .. \";\"\r\n      UI.clearParticles(ui_particles[i].name, ui_particles[i].id)\r\n      table.remove(ui_particles, i)\r\n    end\r\n  end\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearUIParticles\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Enregistre/Supprime un callback à l'ouverture d'une interface\r\nfunction addDialogLoadListener(dialog, funcName, ...)\r\n  UI.addDialogLoadedListener(dialog, funcName, unpack(arg))\r\n  table.insert(ui_listener_load,  dialog)\r\nend\r\n\r\nfunction clearDialogLoadListener(dialogName)\r\n  local str = \"\"\r\n  for i=#ui_listener_load, 1, -1 do\r\n    if (not dialogName) or (dialogName == ui_listener_load[i]) then\r\n      str = str .. toString(ui_listener_load[i]) .. \";\"\r\n      UI.removeDialogLoadedListener(ui_listener_load[i])\r\n      table.remove(ui_listener_load, i)\r\n    end\r\n  end\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearDialogLoadListener\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Enregistre/Supprime un callback à la fermeture d'une interface\r\nfunction addDialogUnloadListener(dialog, funcName, ...)\r\n  UI.addDialogUnloadedListener(dialog, funcName, unpack(arg))\r\n  table.insert(ui_listener_unload, dialog)\r\nend\r\n\r\nfunction clearDialogUnloadListener(dialogName)\r\n  local str = \"\"\r\n  for i=#ui_listener_unload, 1, -1 do\r\n    if (not dialogName) or (dialogName == ui_listener_unload[i]) then\r\n      str = str .. toString(ui_listener_unload[i]) .. \";\"\r\n      UI.removeDialogUnloadedListener(ui_listener_unload[i])\r\n      table.remove(ui_listener_unload, i)\r\n    end\r\n  end\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearDialogUnloadListener\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Enregistre/Supprime un callback sur un élément d'une interface\r\nfunction addDialogEventListener(dialog, id, eventType, funcName, ...)\r\n  if not UI.isDialogLoaded(dialog) then return end\r\n\r\n  UI.addEventListener(dialog, id, eventType, funcName, unpack(arg))\r\n  table.insert(ui_listener_event, {dialog=dialog, id=id, eventType=eventType, funcName=funcName})\r\nend\r\n\r\nfunction clearDialogEventListener(dialogName)\r\n  local str = \"\"\r\n  for i=#ui_listener_event, 1, -1 do\r\n    if (not dialogName) or (dialogName == ui_listener_event[i].dialog) then\r\n      str = str .. toString(ui_listener_event[i].dialog) .. \"@\" .. toString(ui_listener_event[i].id) .. \";\"\r\n      UI.removeEventListener(ui_listener_event[i].dialog, ui_listener_event[i].id, ui_listener_event[i].eventType, ui_listener_event[i].funcName)\r\n      table.remove(ui_listener_event, i)\r\n    end\r\n  end\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearDialogEventListener\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y , z, ...)\r\n  local particleId = Particle.addParticleSystem(particleFileId, x, y , z, unpack(arg))\r\n  table.insert(world_particles, particleId)\r\n\r\n  return particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n  local particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n  table.insert(world_particles, particleId)\r\n\r\n  return particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n  local str = \"\"\r\n  for i=#world_particles, 1, -1 do\r\n    str = str .. toString(world_particles[i]) .. \";\"\r\n    Particle.removeParticleSystem(world_particles[i])\r\n  end\r\n\r\n  world_particles = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n  BubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n  if isLower(mobileId, 0) then\r\n    BubbleText.setCharacterSpeak(mobileId, text)\r\n  else\r\n    if (not offsetY) then\r\n      local height = Mobile.getMobileHeight(mobileId)\r\n      if (not height) then height = 6 end\r\n\r\n      offsetY = height * 10\r\n    end\r\n\r\n    if (not offsetX) then offsetX = 0 end\r\n    if (not infiniteDuration) then infiniteDuration = false end\r\n\r\n    BubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n    UI.writeLocalisedInChat(text)\r\n  end\r\n\r\n  if (not tContains(bubbles, mobileId)) then\r\n    table.insert(bubbles, mobileId)\r\n  end\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n  local str = \"\"\r\n  for i = #bubbles, 1, -1 do\r\n    if (not mobileId) then\r\n      str = str .. toString(bubbles[i]) .. \";\"\r\n      BubbleText.closeBubbleAttachedTo(bubbles[i])\r\n    elseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n      str = str .. toString(bubbles[i]) .. \";\"\r\n      BubbleText.closeBubbleAttachedTo(bubbles[i])\r\n      table.remove(bubbles, i)\r\n    end\r\n  end\r\n\r\n  if (not mobileId) then bubbles = {} end\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n  local compassId = UI.addCompass(\"compass\", x, y, z)\r\n  table.insert(compasses, compassId)\r\n\r\n  return compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n  local str = \"\"\r\n  for i=#compasses, 1, -1 do\r\n    str = str .. toString(compasses[i]) .. \";\"\r\n    UI.removeCompass(compasses[i])\r\n  end\r\n\r\n  compasses = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height)\r\n  local mobileId = Mobile.generateClientMobileId()\r\n  Actor.createActor(mobileId, spriteName, worldX, worldY, worldZ, availableDirection)\r\n\r\n  if (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n  if (height) then Actor.setActorHeight(mobileId, height) end\r\n\r\n  table.insert(actors, mobileId)\r\n\r\n  return mobileId\r\nend\r\n\r\nfunction clearActors()\r\n  local str = \"\"\r\n  for i = #actors, 1, -1 do\r\n    str = str .. toString(actors[i]) .. \";\"\r\n    Actor.deleteActor(actors[i])\r\n  end\r\n\r\n  actors = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n  local taskId = invoke(delay, count, funcName, unpack(arg))\r\n  table.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n  local str = \"\"\r\n  for i=#invoke_tasks, 1, -1 do\r\n    str = str .. toString(invoke_tasks[i]) .. \";\"\r\n    interrupt(invoke_tasks[i])\r\n    desinvoke(invoke_tasks[i])\r\n  end\r\n\r\n  invoke_tasks = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n  invoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n  local taskId = setInterval(delay, funcName, unpack(arg))\r\n  table.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n  local str = \"\"\r\n  for i=#interval_tasks, 1, -1 do\r\n    str = str .. toString(interval_tasks[i]) .. \";\"\r\n    interrupt(interval_tasks[i])\r\n    desinvoke(interval_tasks[i])\r\n  end\r\n\r\n  interval_tasks = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n  if (_DEBUG) then trace(\"startCinematicContext\") end\r\n\r\n  UI.manageFrame(\"World\", false)\r\n  UI.closeMRU()\r\n  UI.closeAllBags()\r\n  UI.setUIVisible(false)\r\n  UI.displayWideScreenBand(true)\r\n  Camera.setUserZoomLocked(true)\r\n\r\n  if (cameraMobileId ~= nil)  then\r\n    Camera.setMoveSpeedFactor(10000)\r\n    Camera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n  end\r\n\r\n  if (zoomFactor ~= nil)  then\r\n    Camera.setZoomFactor(zoomFactor)\r\n  end\r\n\r\n  if (musicId ~= nil)  then\r\n    Sound.playForcedMusic(musicId)\r\n  end\r\n\r\n  if (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\nfunction skipCinematic()\r\n  local player = Context.getLeaderId()\r\n\r\n  for x = 1, #_ACTOR_LIST do\r\n    Actor.deleteActor(_ACTOR_LIST[x])\r\n  end\r\n\r\n  UI.hideButton()\r\n  clearALL()\r\n  stopCinematicContext(1, player, true)\r\n  Mobile.setMobileVisible(player, true)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n  if (_DEBUG) then trace(\"stopCinematicContext\") end\r\n\r\n  UI.displayWideScreenBand(false)\r\n  UI.setUIVisible(true)\r\n  Camera.setUserZoomLocked(false)\r\n  UI.manageFrame(\"World\", true)\r\n\r\n  Camera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n  Camera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n  if (zoomFactor ~= nil) then\r\n    Camera.setZoomFactor(zoomFactor)\r\n  end\r\n\r\n  if (cameraMobileId ~= nil) then\r\n    Camera.attachCameraToMobile(cameraMobileId)\r\n  end\r\n\r\n  if (stopMusic) then\r\n    Sound.stopForcedMusic()\r\n  end\r\n\r\n  if (_DEBUG) then\r\n    UI.hideButton()\r\n  end\r\n\r\n  --TRIGGER\r\n  Server.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Affiche/Masque une texture à l'écran\r\nfunction displayScreenEffect(enable, fadeInDur, alphaDur, fadeOutDur, r, g, b, alpha)\r\n  if (_DEBUG) then trace(\"displayScreenEffect\") end\r\n\r\n  if not enable and screenEffectId ~= nil  then\r\n    --On retire le blackScreen\r\n    Effect.stopEffect(screenEffectId)\r\n  else\r\n    --On affiche un blackScreen à l'entrée dans l'instance le temps qu'elle soit complètement chargée\r\n    screenEffectId = Effect.createFullScreenSprite(fadeInDur, alphaDur, fadeOutDur, r, g, b, alpha)\r\n  end\r\nend\r\n\r\n-- FONCTION NETTOYAGE --\r\nfunction clearALL()\r\n  clearIntervalTasks()\r\n  clearInvokeTasks()\r\n  clearBubbles()\r\n  clearUIColorTweens()\r\n  clearUIParticles()\r\n  clearWorldParticles()\r\n  clearCompasses()\r\n  clearActors()\r\n\r\n  Focus.display(false)\r\n  UI.unloadTutorialDialog()\r\nend\r\n\r\n-- FONCTION NETTOYAGE --\r\nfunction clearUI(dialogName)\r\n  clearUIColorTweens(dialogName)\r\n  clearUIParticles(dialogName)\r\nend\r\n\r\n-- FONCTION NETTOYAGE --\r\nfunction clearListener(dialogName)\r\n  clearDialogLoadListener(dialogName)\r\n  clearDialogUnloadListener(dialogName)\r\n  clearDialogEventListener(dialogName)\r\nend\r\n\r\n-- Fonction mode démo\r\n-- function addButton()\r\n-- \tinvoke(2000, 1, \"UI.displayButton\", false, \"scenario.endKinematic.confirmEscape\", \"lyongameshow.vampyro.rules.display\", \"displayFightRules\")\r\n-- end \r\n\r\nfunction displayFightRules()\r\n--\tUI.loadTutorialDialog(\"japan.expo.2022\",\"japanexpo.fight.title\",\"japanexpo.fight.desc\")\r\n--\taddButton()\r\nend\r\n\r\nfunction onEnterInstance()  \r\n-- addButton()\r\n \t\r\n   UI.activateFollowAchievement(false)\r\n   prepareUI(false)\r\n   prepareShortcuts(false)\r\n   prepareShortcuts(true, \"DISPLAY\")\r\n   prepareShortcuts(true, \"CHAT\")\r\n   prepareShortcuts(true, \"FIGHT\")\r\n   prepareShortcuts(true, \"SHORTCUTBAR\")\r\n\r\n  UI.setShortcutEnabled(true, \"shortcutCategory.interface\", \"emotes\")\r\n  UI.setShortcutEnabled(false, \"shortcutCategory.interface\", \"switchToDirectAttackCommand\")\r\n  UI.setShortcutEnabled(false, \"shortcutCategory.interface\", \"spellsInventory\")\r\n  UI.setShortcutEnabled(false, \"shortcutCategory.interface\", \"inventory\")\r\n  UI.setShortcutEnabled(false, \"shortcutCategory.interface\", \"osamodasSymbiot\")\r\n  UI.setShortcutEnabled(false, \"shortcutCategory.interface\", \"shortcutBar0\")\r\n  UI.setShortcutEnabled(false, \"shortcutCategory.interface\", \"shortcutBar1\")\r\n  UI.setShortcutEnabled(false, \"shortcutCategory.interface\", \"shortcutBar2\")\r\n  UI.setShortcutEnabled(false, \"shortcutCategory.interface\", \"shortcutBar3\")\r\n  UI.setShortcutEnabled(false, \"shortcutCategory.interface\", \"additionalShortcutBar0\")\r\n  UI.setShortcutEnabled(false, \"shortcutCategory.interface\", \"additionalShortcutBar1\")\r\n  UI.setShortcutEnabled(false, \"shortcutCategory.interface\", \"additionalShortcutBar2\")\r\n  UI.setShortcutEnabled(false, \"shortcutCategory.interface\", \"additionalShortcutBar3\")\r\n  UI.setShortcutEnabled(false, \"shortcutCategory.interface\", \"changeShortcutBarType\")\r\n  \r\n    --Boutons hors combat à droite du Coeur\r\n  setWidgetVisible(\"shortcutBarDialog\", \"previousButton\", true)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"nextButton\", true)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"addExtraBarButton\", true)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"shortcutModeButton\", true)\r\n   \r\n -- Boutons hors combat à gauche du Coeur\r\n\r\n  --Boutons en combat à gauche du Coeur\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"giveUpButton\", true)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"hideFightersButton\", true)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"reportCellBtn\", true)\r\nend\n\n-- [INIT] Variables\n-- \nfunction event_2569_22823()\n    \nend\n\n-- [EVENT] Le joueur entre dans l'instance - Mode découverte\n-- \nfunction event_2569_22824()\n    local playerId = Context.getLeaderId()\r\n    \r\n    Mobile.hideOtherPlayerMobile(false)\r\n    \r\n    function onStasisDungeonDialogLoaded()\r\n        clearUI()\r\n        clearListener()\r\n            \r\n        UI.setWidgetEnabled(\"stasisDungeonDialog\", \"modulationContainer\", false)\r\n        UI.setWidgetEnabled(\"stasisDungeonDialog\", \"modulationCheckBox\", false)\r\n        UI.setWidgetEnabled(\"stasisDungeonDialog\", \"difficultyContainer\", false)\r\n        UI.setWidgetEnabled(\"stasisDungeonDialog\", \"difficultyComboBox\", false)\r\n        UI.setWidgetEnabled(\"stasisDungeonDialog\", \"difficultyComboBoxContainer\", false)\r\n        UI.setWidgetEnabled(\"stasisDungeonDialog\", \"dungeonOptionsContainer\", false)\r\n        \r\n        UI.setWidgetVisibility(\"stasisDungeonDialog\", \"modulationContainer\", false)\r\n        UI.setWidgetVisibility(\"stasisDungeonDialog\", \"modulationCheckBox\", false)\r\n        UI.setWidgetVisibility(\"stasisDungeonDialog\", \"difficultyContainer\", false)\r\n        UI.setWidgetVisibility(\"stasisDungeonDialog\", \"difficultyComboBox\", false)\r\n        UI.setWidgetVisibility(\"stasisDungeonDialog\", \"difficultyComboBoxContainer\", false)\r\n        UI.setWidgetVisibility(\"stasisDungeonDialog\", \"dungeonOptionsContainer\", false)\r\n            \r\n        UI.setWidgetVisibility(\"worldAndFightBarDialog\", \"wpwidget\", false)\r\n    \r\n    -- LISTENER\r\n       addDialogUnloadListener(\"stasisDungeonDialog\", \"init\")\r\n    end\r\n            \r\n    function init()\r\n       clearUI()\r\n       clearListener()\r\n            \r\n    -- LISTENER\r\n       addDialogLoadListener(\"stasisDungeonDialog\", \"onStasisDungeonDialogLoaded\")\r\n    end\r\n       \r\n    onEnterInstance()\r\n    init()\nend\n\n-- [EVENT] Le joueur entre dans l'instance - Mode normal\n-- \nfunction event_2569_22825()\n    local playerId = Context.getLeaderId()\r\n    \r\n    Mobile.hideOtherPlayerMobile(false)\r\n    \r\n    function onStasisDungeonDialogLoaded()\r\n        clearUI()\r\n        clearListener()\r\n            \r\n        UI.setWidgetEnabled(\"stasisDungeonDialog\", \"modulationContainer\", false)\r\n        UI.setWidgetEnabled(\"stasisDungeonDialog\", \"modulationCheckBox\", false)\r\n        UI.setWidgetEnabled(\"stasisDungeonDialog\", \"difficultyContainer\", false)\r\n        UI.setWidgetEnabled(\"stasisDungeonDialog\", \"difficultyComboBox\", false)\r\n        UI.setWidgetEnabled(\"stasisDungeonDialog\", \"difficultyComboBoxContainer\", false)\r\n        UI.setWidgetEnabled(\"stasisDungeonDialog\", \"dungeonOptionsContainer\", false)\r\n        \r\n        UI.setWidgetVisibility(\"stasisDungeonDialog\", \"modulationContainer\", false)\r\n        UI.setWidgetVisibility(\"stasisDungeonDialog\", \"modulationCheckBox\", false)\r\n        UI.setWidgetVisibility(\"stasisDungeonDialog\", \"difficultyContainer\", false)\r\n        UI.setWidgetVisibility(\"stasisDungeonDialog\", \"difficultyComboBox\", false)\r\n        UI.setWidgetVisibility(\"stasisDungeonDialog\", \"difficultyComboBoxContainer\", false)\r\n        UI.setWidgetVisibility(\"stasisDungeonDialog\", \"dungeonOptionsContainer\", false)\r\n        \r\n        UI.setWidgetVisibility(\"worldAndFightBarDialog\", \"wpwidget\", false)\r\n        \r\n    -- LISTENER\r\n       addDialogUnloadListener(\"stasisDungeonDialog\", \"init\")\r\n    end\r\n            \r\n    function init()\r\n       clearUI()\r\n       clearListener()\r\n            \r\n    -- LISTENER\r\n       addDialogLoadListener(\"stasisDungeonDialog\", \"onStasisDungeonDialogLoaded\")\r\n    end\r\n       \r\n    onEnterInstance()\r\n    init()\nend\n\n-- [EVENT] Le joueur entre dans l'instance - Mode ultime\n-- \nfunction event_2569_22939()\n    local playerId = Context.getLeaderId()\r\n    \r\n    Mobile.hideOtherPlayerMobile(false)\r\n    \r\n    function onStasisDungeonDialogLoaded()\r\n        clearUI()\r\n        clearListener()\r\n            \r\n        UI.setWidgetEnabled(\"stasisDungeonDialog\", \"modulationContainer\", false)\r\n        UI.setWidgetEnabled(\"stasisDungeonDialog\", \"modulationCheckBox\", false)\r\n        UI.setWidgetEnabled(\"stasisDungeonDialog\", \"difficultyContainer\", false)\r\n        UI.setWidgetEnabled(\"stasisDungeonDialog\", \"difficultyComboBox\", false)\r\n        UI.setWidgetEnabled(\"stasisDungeonDialog\", \"difficultyComboBoxContainer\", false)\r\n        UI.setWidgetEnabled(\"stasisDungeonDialog\", \"dungeonOptionsContainer\", false)\r\n        \r\n        UI.setWidgetVisibility(\"stasisDungeonDialog\", \"modulationContainer\", false)\r\n        UI.setWidgetVisibility(\"stasisDungeonDialog\", \"modulationCheckBox\", false)\r\n        UI.setWidgetVisibility(\"stasisDungeonDialog\", \"difficultyContainer\", false)\r\n        UI.setWidgetVisibility(\"stasisDungeonDialog\", \"difficultyComboBox\", false)\r\n        UI.setWidgetVisibility(\"stasisDungeonDialog\", \"difficultyComboBoxContainer\", false)\r\n        UI.setWidgetVisibility(\"stasisDungeonDialog\", \"dungeonOptionsContainer\", false)\r\n        \r\n        UI.setWidgetVisibility(\"worldAndFightBarDialog\", \"wpwidget\", false)\r\n        \r\n    -- LISTENER\r\n       addDialogUnloadListener(\"stasisDungeonDialog\", \"init\")\r\n    end\r\n            \r\n    function init()\r\n       clearUI()\r\n       clearListener()\r\n            \r\n    -- LISTENER\r\n       addDialogLoadListener(\"stasisDungeonDialog\", \"onStasisDungeonDialogLoaded\")\r\n    end\r\n       \r\n    onEnterInstance()\r\n    init()\nend\n\n-- [EVENT] Le joueur entre dans l'instance - HUB\n-- \nfunction event_2569_22826()\n    local playerId = Context.getLeaderId()\r\n    \r\n    Mobile.hideOtherPlayerMobile(true)\r\n    \r\n    function onStasisDungeonDialogLoaded()\r\n        clearUI()\r\n        clearListener()\r\n            \r\n        UI.setWidgetEnabled(\"stasisDungeonDialog\", \"modulationContainer\", false)\r\n        UI.setWidgetEnabled(\"stasisDungeonDialog\", \"modulationCheckBox\", false)\r\n        UI.setWidgetEnabled(\"stasisDungeonDialog\", \"difficultyContainer\", false)\r\n        UI.setWidgetEnabled(\"stasisDungeonDialog\", \"difficultyComboBox\", false)\r\n        UI.setWidgetEnabled(\"stasisDungeonDialog\", \"difficultyComboBoxContainer\", false)\r\n        UI.setWidgetEnabled(\"stasisDungeonDialog\", \"dungeonOptionsContainer\", false)\r\n        \r\n        UI.setWidgetVisibility(\"stasisDungeonDialog\", \"modulationContainer\", false)\r\n        UI.setWidgetVisibility(\"stasisDungeonDialog\", \"modulationCheckBox\", false)\r\n        UI.setWidgetVisibility(\"stasisDungeonDialog\", \"difficultyContainer\", false)\r\n        UI.setWidgetVisibility(\"stasisDungeonDialog\", \"difficultyComboBox\", false)\r\n        UI.setWidgetVisibility(\"stasisDungeonDialog\", \"difficultyComboBoxContainer\", false)\r\n        UI.setWidgetVisibility(\"stasisDungeonDialog\", \"dungeonOptionsContainer\", false)\r\n            \r\n    -- LISTENER\r\n       addDialogUnloadListener(\"stasisDungeonDialog\", \"init\")\r\n    end\r\n            \r\n    function init()\r\n       clearUI()\r\n       clearListener()\r\n            \r\n    -- LISTENER\r\n       addDialogLoadListener(\"stasisDungeonDialog\", \"onStasisDungeonDialogLoaded\")\r\n    end\r\n       \r\n    onEnterInstance()\r\n    init()\nend\n\n","functions":["tContains","prepareChatUI","prepareFollowQuestUI","prepareUI","prepareShortcuts","setWidgetVisible","clearWidgetVisible","setWidgetEnable","clearWidgetEnable","setUIColorTween","clearUIColorTweens","setUIParticle","setUIParticleBorder","clearUIParticles","addDialogLoadListener","clearDialogLoadListener","addDialogUnloadListener","clearDialogUnloadListener","addDialogEventListener","clearDialogEventListener","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","bubble","clearBubbles","setCompass","clearCompasses","createActor","clearActors","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","startCinematicContext","skipCinematic","stopCinematicContext","displayScreenEffect","clearALL","clearUI","clearListener","addButton","displayFightRules","onEnterInstance","event_2569_22823","event_2569_22824","onStasisDungeonDialogLoaded","init","event_2569_22825","onStasisDungeonDialogLoaded","init","event_2569_22939","onStasisDungeonDialogLoaded","init","event_2569_22826","onStasisDungeonDialogLoaded","init"],"quest_calls":["UI.activateFollowAchievement(false)\r"],"dialogue_calls":[]},"scenario/2570.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n  \r\n-- Fonctions cache / montre CM\r\nfunction hideMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, false)\r\nend\r\n\r\nfunction showMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, true)\r\nend\r\n\r\nbubbleFightInfoId = 0\r\n\r\nfunction closeFightInfo()\r\n\tif (bubbleFightInfoId ~= nil and bubbleFightInfoId ~= 0) then BubbleText.close(bubbleFightInfoId) end\r\nend\r\n\r\nfunction onFightInfoClosed()\r\n\tif (bubbleFightInfoId ~= nil and bubbleFightInfoId ~= 0) then bubbleFightInfoId = 0 end\r\nend\r\n\r\nfunction updateFightInfo(wave, difficulty, forceDisplayUI)\r\n\tlocal wave = toLong(wave)\r\n\tlocal difficulty = toLong(difficulty)\r\n\r\n\tif (bubbleFightInfoId == 0) then\r\n\t\tbubbleFightInfoId = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_WEST\", 0, -60, false, 2147483647, true, \"interactiveBubbleDialog5\", 30000, 25000, \"onFightInfoClosed\")\r\n\tend\r\n\r\n\tBubbleText.setText(bubbleFightInfoId, \"wave.fight.player.infos\", wave, difficulty)\r\n\r\n\tif (forceDisplayUI) then BubbleText.show(bubbleFightInfoId) end\r\nend\n\n-- [INIT] Variables globales\n-- \nfunction event_2570_22831()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2570_22832()\n    function customSkip()\r\n    \tMobile.setMobileVisible(bossId, true)\r\n    \tMobile.setMobilePosition(bossId, -12, 1, 0)\r\n    \tskipCinematic(22832)\r\n    end\r\n    \r\n    local playerId = Context.getLeaderId()\r\n    local bossId = toLong(bossId)\r\n    local torossId = createActor(1113105589, -17, 1, 8, 4, 1, 15)\r\n    local fakeTorossId = createActor(119405596, -18, 1, 11, 4, 1, 8)\r\n    \r\n    Mobile.setMobileVisible(bossId, false)\r\n    Mobile.setMobileAnimation(torossId, \"AnimAssis-Statique\")\r\n    \r\n    startCinematicContext(1.0, playerId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"customSkip\")\r\n    \r\n    invoke_custom(00010, 1, \"Camera.setZoomSpeedFactor\", 10000)\r\n    invoke_custom(00010, 1, \"Camera.setZoomFactor\", 1.0)\r\n    invoke_custom(00010, 1, \"Camera.attachCameraToMobile\", torossId)\r\n    \r\n    invoke_custom(01000, 1, \"Camera.setZoomSpeedFactor\", 0.02)\r\n    invoke_custom(01000, 1, \"Camera.setZoomFactor\", 1.5)\r\n    \r\n    -- \"En pénétrant dans mon palais, tu viens de t'assurer une fin tragique.\"\r\n    invoke_custom(01500, 1, \"bubble\", fakeTorossId, \"toross.fight.start.dialog.07\")\r\n    invoke_custom(04500, 1, \"Mobile.setMobileAnimation\", torossId, \"AnimSeLeve\")\r\n    invoke_custom(07000, 1, \"clearBubbles\", fakeTorossId)\r\n    \r\n    invoke_custom(08000, 1, \"Mobile.setMobileAnimation\", torossId, \"AnimSort-3-Debut\")\r\n    invoke_custom(08000, 1, \"Particle.addParticleSystem\", -1113181740, -17, 1, 8)\r\n    invoke_custom(08780, 1, \"Mobile.setMobileVisible\", torossId, false)\r\n    \r\n    invoke_custom(09500, 1, \"Mobile.setMobilePosition\", torossId, -12, 1, 0)\r\n    invoke_custom(09500, 1, \"Mobile.setMobileVisible\", torossId, true)\r\n    invoke_custom(09500, 1, \"Mobile.setMobileAnimation\", torossId, \"AnimSort-3-Fin\")\r\n    invoke_custom(09500, 1, \"Particle.addParticleSystem\", -1113181741, -12, 1, 0)\r\n    \r\n    invoke_custom(10600, 1, \"Mobile.setMobileAnimation\", torossId, \"AnimSort-4\")\r\n    invoke_custom(10600, 1, \"Particle.addParticleSystem\", -1113181650, -12, 1, 0)\r\n    \r\n    -- \"Je vais te montrer ce qu'il en coûte de se frotter à moi. Approche !\"\r\n    invoke_custom(10600, 1, \"bubble\", torossId, \"toross.fight.start.dialog.08\")\r\n    invoke_custom(15500, 1, \"clearBubbles\", torossId)\r\n    \r\n    invoke_custom(16000, 1, \"Camera.attachCameraToMobile\", playerId)\r\n    \r\n    invoke_custom(16500, 1, \"customSkip\")\nend\n\n-- [EVENT] CLIENT_TRIGGERED_EVENT - Lancement du combat\n-- \nfunction event_2570_22833()\n    trace(\"LANCEMENT DU COMBAT\")\nend\n\n-- [EVENT] FIGHT_ENTER_ACTION_PHASE - Application états\n-- \nfunction event_2570_22834(wave, difficulty)\n    updateFightInfo(wave, difficulty, true)\nend\n\n-- [EVENT] NEW_MONSTER_WAVE - Difficulté\n-- \nfunction event_2570_22835(wave, difficulty)\n    updateFightInfo(wave, difficulty, true)\nend\n\n-- [EVENT] FIGHT_ENDED_IN_CLIENT - On ferme l'affichage\n-- \nfunction event_2570_22836()\n    closeFightInfo()\nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","hideMonster","showMonster","closeFightInfo","onFightInfoClosed","updateFightInfo","event_2570_22831","event_2570_22832","customSkip","event_2570_22833","event_2570_22834","event_2570_22835","event_2570_22836"],"quest_calls":[],"dialogue_calls":[]},"scenario/2571.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n  \r\n-- Fonctions cache / montre CM\r\nfunction hideMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, false)\r\nend\r\n\r\nfunction showMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, true)\r\nend\r\n\r\nbubbleFightInfoId = 0\r\n\r\nfunction closeFightInfo()\r\n\tif (bubbleFightInfoId ~= nil and bubbleFightInfoId ~= 0) then BubbleText.close(bubbleFightInfoId) end\r\nend\r\n\r\nfunction onFightInfoClosed()\r\n\tif (bubbleFightInfoId ~= nil and bubbleFightInfoId ~= 0) then bubbleFightInfoId = 0 end\r\nend\r\n\r\nfunction updateFightInfo(wave, difficulty, teamDamage, forceDisplayUI)\r\n\tlocal wave = toLong(wave)\r\n\tlocal difficulty = toLong(difficulty)\r\n\tlocal teamDamage = toLong(teamDamage)\r\n\r\n\tif (bubbleFightInfoId == 0) then\r\n\t\tbubbleFightInfoId = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_WEST\", 0, -60, false, 2147483647, true, \"interactiveBubbleDialog5\", 30000, 25000, \"onFightInfoClosed\")\r\n\tend\r\n\r\n\tBubbleText.setText(bubbleFightInfoId, \"japan.expo.2024.wave.info\", wave, difficulty, teamDamage)\r\n\r\n\tif (forceDisplayUI) then BubbleText.show(bubbleFightInfoId) end\r\nend\n\n-- [INIT] Variables globales\n-- \nfunction event_2571_22837()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2571_22838()\n    function customSkip()\r\n    \tskipCinematic(22838)\r\n    end\r\n    \r\n    local playerId = Context.getLeaderId()\r\n    local torossId = createActor(1113105589, -17, 1, 8, 4, 1, 15)\r\n    local fakeTorossId = createActor(119405596, -18, 1, 11, 4, 1, 8)\r\n    \r\n    Mobile.setMobileAnimation(torossId, \"AnimAssis-Statique\")\r\n    \r\n    startCinematicContext(1.0, playerId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"customSkip\")\r\n    \r\n    invoke_custom(00010, 1, \"Camera.setZoomSpeedFactor\", 10000)\r\n    invoke_custom(00010, 1, \"Camera.setZoomFactor\", 1.0)\r\n    invoke_custom(00010, 1, \"Camera.attachCameraToMobile\", torossId)\r\n    \r\n    invoke_custom(01000, 1, \"Camera.setZoomSpeedFactor\", 0.02)\r\n    invoke_custom(01000, 1, \"Camera.setZoomFactor\", 1.5)\r\n    \r\n    -- \"En pénétrant dans mon palais, tu viens de t'assurer une fin tragique.\"\r\n    invoke_custom(01500, 1, \"bubble\", fakeTorossId, \"toross.fight.start.dialog.07\")\r\n    invoke_custom(04500, 1, \"Mobile.setMobileAnimation\", torossId, \"AnimSeLeve\")\r\n    invoke_custom(07000, 1, \"clearBubbles\", fakeTorossId)\r\n    \r\n    invoke_custom(08000, 1, \"Mobile.setMobileAnimation\", torossId, \"AnimSort-3-Debut\")\r\n    invoke_custom(08000, 1, \"Particle.addParticleSystem\", -1113181740, -17, 1, 8)\r\n    invoke_custom(08780, 1, \"Mobile.setMobileVisible\", torossId, false)\r\n    \r\n    invoke_custom(09500, 1, \"Mobile.setMobilePosition\", torossId, -12, 1, 0)\r\n    invoke_custom(09500, 1, \"Mobile.setMobileVisible\", torossId, true)\r\n    invoke_custom(09500, 1, \"Mobile.setMobileAnimation\", torossId, \"AnimSort-3-Fin\")\r\n    invoke_custom(09500, 1, \"Particle.addParticleSystem\", -1113181741, -12, 1, 0)\r\n    \r\n    invoke_custom(10600, 1, \"Mobile.setMobileAnimation\", torossId, \"AnimSort-4\")\r\n    invoke_custom(10600, 1, \"Particle.addParticleSystem\", -1113181650, -12, 1, 0)\r\n    \r\n    -- \"Je vais te montrer ce qu'il en coûte de se frotter à moi. Approche !\"\r\n    invoke_custom(10600, 1, \"bubble\", torossId, \"toross.fight.start.dialog.08\")\r\n    invoke_custom(15500, 1, \"clearBubbles\", torossId)\r\n    \r\n    invoke_custom(16000, 1, \"Camera.attachCameraToMobile\", playerId)\r\n    \r\n    invoke_custom(16500, 1, \"customSkip\")\nend\n\n-- [EVENT] CLIENT_TRIGGERED_EVENT - Lancement du combat\n-- \nfunction event_2571_22839()\n    trace(\"LANCEMENT DU COMBAT\")\nend\n\n-- [EVENT] FIGHT_ENTER_ACTION_PHASE - Application états\n-- \nfunction event_2571_22840(wave, difficulty, teamDamage)\n    updateFightInfo(wave, difficulty, teamDamage, true)\nend\n\n-- [EVENT] NEW_MONSTER_WAVE - Difficulté\n-- \nfunction event_2571_22841(wave, difficulty, teamDamage)\n    updateFightInfo(wave, difficulty, teamDamage, true)\nend\n\n-- [EVENT] FIGHT_ENDED_IN_CLIENT - On ferme l'affichage\n-- \nfunction event_2571_22842(wave, difficulty, teamDamage, fightWon)\n    local wave = toLong(wave)\r\n    local teamDamage = toLong(teamDamage)\r\n    \r\n    if (toLong(fightWon) == 1) then\r\n    \tUI.writeLocalisedInChat(\"japan.expo.2024.fight.mode.normal.won\", wave)\r\n    \tUI.writeLocalisedInChat(\"japan.expo.2024.fight.final.score.wave\", wave)\r\n    \tUI.writeLocalisedInChat(\"japan.expo.2024.fight.final.score.damage\", teamDamage)\r\n    end\r\n    \r\n    closeFightInfo()\nend\n\n-- EFFECT_EXECUTION - Le joueur a gagné le combat\n-- \nfunction event_2571_22942()\n    \nend\n\n-- EFFECT_EXECUTION - Mise à jour UI infos de combat (score)\n-- \nfunction event_2571_22843(wave, difficulty, teamDamage)\n    updateFightInfo(wave, difficulty, teamDamage, true)\nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","hideMonster","showMonster","closeFightInfo","onFightInfoClosed","updateFightInfo","event_2571_22837","event_2571_22838","customSkip","event_2571_22839","event_2571_22840","event_2571_22841","event_2571_22842","event_2571_22942","event_2571_22843"],"quest_calls":[],"dialogue_calls":[]},"scenario/2572.lua":{"source":"playerId = Context.getPlayer()\r\n\r\nfunction setBlopsVisible(blops, benGueur, isVisible)\r\n    for i = 1, #blops do\r\n        Mobile.setMobileVisible(blops[i], isVisible)\r\n    end\r\n\r\n    Mobile.setMobileVisible(benGueur, not isVisible)\r\nend\r\n\r\nfunction setBlopsDirections(blops, benGueur)\r\n    local directionMapping = {\r\n        [\"-2,-1\"] = 1,\r\n        [\"0,1\"] = 7,\r\n        [\"2,-1\"] = 5\r\n    }\r\n\r\n    for _, blop in ipairs(blops) do\r\n        local blopX, blopY = Mobile.getMobilePosition(blop)\r\n        local key = string.format(\"%d,%d\", blopX, blopY)\r\n        Mobile.setMobileDirection(blop, directionMapping[key] or 3)\r\n    end\r\n\r\n    Mobile.setMobileDirection(benGueur, 3)\r\nend\r\n\r\nfunction playBlopSelectionAnim(blop)\r\n    Mobile.setMobileAnimation(blop, \"AnimHit\")\r\n\r\n    Particle.addParticleSystem(-1369055401, Mobile.getMobilePosition(blop))\r\nend\r\n\r\nfunction executeBlopInteractionSequence(numbers, redBlop, blueBlop, greenBlop, yellowBlop, roundDuration, blopBouncingDuration, timeBeforeStartBlopBouncing)\r\n    local executionTiming = timeBeforeStartBlopBouncing\r\n    local blopMapping = { redBlop, blueBlop, greenBlop, yellowBlop }\r\n\r\n    for _, number in ipairs(numbers) do\r\n        if number and number >= 0 and blopMapping[number + 1] then\r\n            invoke(executionTiming, 1, \"playBlopSelectionAnim\", blopMapping[number + 1])\r\n            executionTiming = executionTiming + blopBouncingDuration\r\n        end\r\n    end\r\n\r\n    invoke(executionTiming, 1, \"UI.startCountdown\", roundDuration)\r\n    invoke(executionTiming, 1, \"Server.triggerEvent\", 22910)\r\nend\n\n-- [INITIALISATION] Variables\n-- \nfunction event_2572_22901()\n    \nend\n\n-- [CHARACTER_ENTER_INSTANCE_EVENT] Inscription au scénario\n-- \nfunction event_2572_22902()\n    \nend\n\n-- [CHARACTER_ENTER_INSTANCE_EVENT] Setup des variables de base du jeu\n-- \nfunction event_2572_22925(redBlop, blueBlop, greenBlop, yellowBlop, benGueur)\n    local redBlop = toLong(redBlop)\r\n    local blueBlop = toLong(blueBlop)\r\n    local greenBlop = toLong(greenBlop)\r\n    local yellowBlop = toLong(yellowBlop)\r\n    \r\n    local benGueur = toLong(benGueur)\r\n    \r\n    setBlopsVisible({ redBlop, blueBlop, greenBlop, yellowBlop }, benGueur, false)\r\n    \r\n    setBlopsDirections({ redBlop, blueBlop, greenBlop, yellowBlop }, benGueur)\nend\n\n-- [MONSTER_ACTION_EVENT] Paramétrage avant le lancement de la partie\n-- \nfunction event_2572_22928(redBlop, blueBlop, greenBlop, yellowBlop, benGueur)\n    local redBlop = toLong(redBlop)\r\n    local blueBlop = toLong(blueBlop)\r\n    local greenBlop = toLong(greenBlop)\r\n    local yellowBlop = toLong(yellowBlop)\r\n    \r\n    local benGueur = toLong(benGueur)\r\n    \r\n    setBlopsVisible({ redBlop, blueBlop, greenBlop, yellowBlop }, benGueur, true)\nend\n\n-- [MONSTER_ACTION_EVENT] Lancement d'une session\n-- \nfunction event_2572_22910(redBlop, blueBlop, greenBlop, yellowBlop, roundDuration, level, blopBouncingDuration, timeBeforeStartBlopBouncing, number1, number2, number3, number4, number5, number6, number7, number8, number9, number10, number11, number12, number13, number14, number15, number16, number17, number18, number19, number20, number21, number22, number23, number24, number25, number26, number27, number28, number29, number30)\n    local redBlop = toLong(redBlop)\r\n    local blueBlop = toLong(blueBlop)\r\n    local greenBlop = toLong(greenBlop)\r\n    local yellowBlop = toLong(yellowBlop)\r\n    \r\n    local number1 = toLong(number1)\r\n    local number2 = toLong(number2)\r\n    local number3 = toLong(number3)\r\n    local number4 = toLong(number4)\r\n    local number5 = toLong(number5)\r\n    local number6 = toLong(number6)\r\n    local number7 = toLong(number7)\r\n    local number8 = toLong(number8)\r\n    local number9 = toLong(number9)\r\n    local number10 = toLong(number10)\r\n    local number11 = toLong(number11)\r\n    local number12 = toLong(number12)\r\n    local number13 = toLong(number13)\r\n    local number14 = toLong(number14)\r\n    local number15 = toLong(number15)\r\n    local number16 = toLong(number16)\r\n    local number17 = toLong(number17)\r\n    local number18 = toLong(number18)\r\n    local number19 = toLong(number19)\r\n    local number20 = toLong(number20)\r\n    local number21 = toLong(number21)\r\n    local number22 = toLong(number22)\r\n    local number23 = toLong(number23)\r\n    local number24 = toLong(number24)\r\n    local number25 = toLong(number25)\r\n    local number26 = toLong(number26)\r\n    local number27 = toLong(number27)\r\n    local number28 = toLong(number28)\r\n    local number29 = toLong(number29)\r\n    local number30 = toLong(number30)\r\n    \r\n    local roundDuration = toLong(roundDuration)\r\n    local level = toLong(level)\r\n    \r\n    local blopBouncingDuration = toLong(blopBouncingDuration)\r\n    local timeBeforeStartBlopBouncing = toLong(timeBeforeStartBlopBouncing)\r\n    \r\n    trace(\"LANCEMENT DE LA SESSION : NIVEAU \" .. level)\r\n    \r\n    UI.displaySplashText(\"foire.trool.memoireblop.info\", level)\r\n    \r\n    executeBlopInteractionSequence({ number1, number2, number3, number4, number5, number6, number7, number8, number9, number10, number11, number12, number13, number14, number15, number16, number17, number18, number19, number20, number21, number22, number23, number24, number25, number26, number27, number28, number29, number30 }, redBlop, blueBlop, greenBlop, yellowBlop, roundDuration / 1000, blopBouncingDuration, timeBeforeStartBlopBouncing)\nend\n\n-- [CLIENT_TRIGGERED_EVENT] Déblocage des interactions avec les Blops\n-- \nfunction event_2572_22929()\n    \nend\n\n-- [MONSTER_ACTION_EVENT] Le joueur interagit avec le Blop Rouge\n-- \nfunction event_2572_22921(redBlop)\n    playBlopSelectionAnim(toLong(redBlop))\nend\n\n-- [MONSTER_ACTION_EVENT] Le joueur interagit avec le Blop Rouge - Perdu\n-- \nfunction event_2572_22911()\n    \nend\n\n-- [MONSTER_ACTION_EVENT] Le joueur interagit avec le Blop Rouge - Gagné\n-- \nfunction event_2572_22909()\n    \nend\n\n-- [MONSTER_ACTION_EVENT] Le joueur interagit avec le Blop Bleu\n-- \nfunction event_2572_22922(blueBlop)\n    playBlopSelectionAnim(toLong(blueBlop))\nend\n\n-- [MONSTER_ACTION_EVENT] Le joueur interagit avec le Blop Bleu - Perdu\n-- \nfunction event_2572_22913()\n    \nend\n\n-- [MONSTER_ACTION_EVENT] Le joueur interagit avec le Blop Bleu - Gagné\n-- \nfunction event_2572_22912()\n    \nend\n\n-- [MONSTER_ACTION_EVENT] Le joueur interagit avec le Blop Vert\n-- \nfunction event_2572_22923(greenBlop)\n    playBlopSelectionAnim(toLong(greenBlop))\nend\n\n-- [MONSTER_ACTION_EVENT] Le joueur interagit avec le Blop Vert - Perdu\n-- \nfunction event_2572_22915()\n    \nend\n\n-- [MONSTER_ACTION_EVENT] Le joueur interagit avec le Blop Vert - Gagné\n-- \nfunction event_2572_22914()\n    \nend\n\n-- [MONSTER_ACTION_EVENT] Le joueur interagit avec le Blop Jaune\n-- \nfunction event_2572_22924(yellowBlop)\n    playBlopSelectionAnim(toLong(yellowBlop))\nend\n\n-- [MONSTER_ACTION_EVENT] Le joueur interagit avec le Blop Jaune - Perdu\n-- \nfunction event_2572_22917()\n    \nend\n\n-- [MONSTER_ACTION_EVENT] Le joueur interagit avec le Blop Jaune - Gagné\n-- \nfunction event_2572_22916()\n    \nend\n\n-- [TIMER_TICK] La séquence est la bonne\n-- \nfunction event_2572_22919()\n    Mobile.setMobileAnimation(playerId, \"AnimEmote-Rire\")\r\n    \r\n    UI.stopCountdown()\nend\n\n-- [TIMER_TICK] Le jeu est gagné\n-- \nfunction event_2572_22926()\n    UI.displaySplashText(\"defi.donjon.win\")\r\n    Mobile.setMobileAnimation(playerId , \"AnimEmote-Rire\")\r\n    \r\n    trace(\"SESSION REMPORTÉE\")\r\n    \r\n    invoke(1000, 1, \"Server.triggerEvent\", 22903)\nend\n\n-- [TIMER_TICK] Le joueur n'a plus de temps\n-- \nfunction event_2572_22927()\n    \nend\n\n-- [TIMER_TICK] Le jeu est perdu\n-- \nfunction event_2572_22903()\n    UI.displaySplashText(\"defi.donjon.lost\")\r\n    Mobile.setMobileAnimation(playerId , \"AnimEmote-Defaite\")\r\n    \r\n    UI.stopCountdown()\r\n    \r\n    trace(\"SESSION PERDUE\")\r\n    \r\n    invoke(1000, 1, \"Server.triggerEvent\", 22903)\nend\n\n-- [CLIENT_TRIGGERED_EVENT] Téléportation hors du jeu\n-- \nfunction event_2572_22904()\n    \nend\n\n","functions":["setBlopsVisible","setBlopsDirections","playBlopSelectionAnim","executeBlopInteractionSequence","event_2572_22901","event_2572_22902","event_2572_22925","event_2572_22928","event_2572_22910","event_2572_22929","event_2572_22921","event_2572_22911","event_2572_22909","event_2572_22922","event_2572_22913","event_2572_22912","event_2572_22923","event_2572_22915","event_2572_22914","event_2572_22924","event_2572_22917","event_2572_22916","event_2572_22919","event_2572_22926","event_2572_22927","event_2572_22903","event_2572_22904"],"quest_calls":[],"dialogue_calls":[]},"scenario/2573.lua":{"source":"\n\n-- \n-- \nfunction event_2573_22907()\n    \nend\n\n","functions":["event_2573_22907"],"quest_calls":[],"dialogue_calls":[]},"scenario/2574.lua":{"source":"\n\n-- INIT - Variables\n-- \nfunction event_2574_22937()\n    \nend\n\n","functions":["event_2574_22937"],"quest_calls":[],"dialogue_calls":[]},"scenario/2575.lua":{"source":"\n\n-- INIT - Variables\n-- \nfunction event_2575_22938()\n    \nend\n\n","functions":["event_2575_22938"],"quest_calls":[],"dialogue_calls":[]},"scenario/2576.lua":{"source":"function bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n  BubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n  if isLower(mobileId, 0) then\r\n    BubbleText.setCharacterSpeak(mobileId, text)\r\n  else\r\n    if (not offsetY) then\r\n      local height = Mobile.getMobileHeight(mobileId)\r\n      if (not height) then height = 6 end\r\n\r\n      offsetY = height * 10\r\n    end\r\n\r\n    if (not offsetX) then offsetX = 0 end\r\n    if (not infiniteDuration) then infiniteDuration = false end\r\n\r\n    BubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n    UI.writeLocalisedInChat(text)\r\n  end\r\nend\n\n-- [INITIALISATION] Serveur\n-- \nfunction event_2576_22949()\n    \nend\n\n-- Dialogue Crocoburio\n-- \nfunction event_2576_22950()\n    local playerId = Context.getLeaderId()\r\n    \r\n    bubble(playerId, \"quest.crocoburio.01\")\r\n    Mobile.setMobileAnimation(playerId, \"AnimEmote-GratteGratte\")\nend\n\n","functions":["bubble","event_2576_22949","event_2576_22950"],"quest_calls":[],"dialogue_calls":[]},"scenario/2577.lua":{"source":"\n\n-- [INIT] Variables Globales\n-- \nfunction event_2577_22953()\n    \nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_2577_22954()\n    \nend\n\n-- [ADMIN] Inscription des joueurs\n-- \nfunction event_2577_22961()\n    \nend\n\n-- [ADMIN] Lancement du combat\n-- \nfunction event_2577_22955()\n    \nend\n\n-- [ADMIN][Fight] Application des états\n-- \nfunction event_2577_22960()\n    \nend\n\n-- [ADMIN][Fight] FIGHT_ENDED\n-- \nfunction event_2577_22962()\n    \nend\n\n-- [ADMIN] CHARACTER_EXIT_INSTANCE_EVENT\n-- \nfunction event_2577_22963()\n    \nend\n\n","functions":["event_2577_22953","event_2577_22954","event_2577_22961","event_2577_22955","event_2577_22960","event_2577_22962","event_2577_22963"],"quest_calls":[],"dialogue_calls":[]},"scenario/2578.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\ndoorApsId = 7000109\r\n\r\nfunction displayDoors()\r\n\tapsA = Particle.addParticleSystem(doorApsId, -11, -20, -8)\r\n\tapsB = Particle.addParticleSystem(doorApsId, -10, -20, -8)\r\n\tapsC = Particle.addParticleSystem(doorApsId, -9, -20, -8)\r\nend\r\n\r\nfunction displayPath()\r\n    World.setPictoAlpha(-15, 17, -76, 0, 1000)\r\n    World.setPictoAlpha(-15, 18, -76, 0, 1000)\r\n    World.setPictoAlpha(-15, 19, -76, 0, 1000)\r\nend\r\n\r\n-- les fonctions où on cache\r\nfunction hideMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, false)\r\nend\r\n\r\nfunction hidePart(monsterMobileId, partName)\r\n\tMobile.setPartVisible(monsterMobileId, false, partName)\r\nend\r\n\r\n-- les fonctions où on rend visible (à nouveau)\r\nfunction showMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, true)\r\nend\r\n\r\nfunction showPart(monsterMobileId, partName)\r\n\tMobile.setPartVisible(monsterMobileId, true, partName)\r\nend\n\n-- [INIT] Variables Globales\n-- \nfunction event_2578_22964()\n    \nend\n\n-- [INIT] Inscription du joueur + Variables Locales\n-- \nfunction event_2578_22965(room, sayThingOnEntering)\n    if (toLong(room) == 2) then\r\n        displayPath()\r\n    end\r\n    \r\n    displayDoors()\r\n    \r\n    if (toLong(sayThingOnEntering) == 1) then\r\n        local playerId = Context.getLeaderId()\r\n        BubbleText.closeBubbleAttachedTo(playerId)\r\n    \r\n        local bubbleId = BubbleText.prepareWakfuBubble(playerId, 0, 60, false)\r\n        BubbleText.setText(bubbleId, \"quest.brume.foret.03.00\")\r\n        BubbleText.attachToMobile(bubbleId, playerId)\r\n        BubbleText.show(bubbleId)\r\n    end\nend\n\n-- FIGHT_STARTED - Salle 01\n-- \nfunction event_2578_22978()\n    \nend\n\n-- FIGHT_ENTER_ACTION_PHASE - Salle 01 - Spawn du cristal\n-- \nfunction event_2578_22977()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 01\n-- \nfunction event_2578_22966()\n    displayPath()\nend\n\n-- MONSTER_ACTION_EVENT - On lance le combat contre le boss\n-- \nfunction event_2578_22986()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 02 - BOSS\n-- \nfunction event_2578_22967()\n    \nend\n\n-- Déplace le joueur vers la salle suivante\n-- \nfunction event_2578_22969()\n    \nend\n\n-- FIGHT_ENDED_IN_CLIENT_EVENT - Salle 01 - Cinématique ACH 5340 OBJ 11299\n-- \nfunction event_2578_23203()\n    local playerId = Context.getLeaderId()\r\n    \r\n    Mobile.setMobileDirection(playerId, 1)\r\n    \r\n    startCinematicContext(1.0, playerId)\r\n    \r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 23203)\r\n    \r\n    --Pfiou, c'était moins une.\r\n    invoke_custom(1, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimStatique02\")\r\n    invoke_custom(500, 1, \"bubble\", playerId, \"quest.brume.foret.04.00\")\r\n    invoke_custom(3500, 1, \"clearBubbles\", playerId)\r\n    \r\n    --Mais, qu'est-ce que c'est que cet endroit ?\r\n    invoke_custom(3500, 1, \"bubble\", playerId, \"quest.brume.foret.04.01\")\r\n    invoke_custom(3500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Chercher\")\r\n    invoke_custom(5000, 1, \"Mobile.moveMobile\", playerId, -17, 20, -80)\r\n    invoke_custom(10000, 1, \"clearBubbles\", playerId)\r\n    \r\n    --Une rivière noire ? Qu'est-ce qui pourrait noircir de l'eau à ce point-là ?\r\n    invoke_custom(10000, 1, \"bubble\", playerId, \"quest.brume.foret.04.02\")\r\n    invoke_custom(10000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Effrayee\")\r\n    invoke_custom(11500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(17000, 1, \"clearBubbles\", playerId)\r\n    \r\n    --Je ne dois pas être loin de trouver des œufs. Continuons.\r\n    invoke_custom(17000, 1, \"bubble\", playerId, \"quest.brume.foret.04.03\")\r\n    invoke_custom(17000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(19000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Pointer\")\r\n    invoke_custom(22500, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(23000, 1, \"skipCinematic\", 23203)\nend\n\n-- CLIENT_TRIGGERED_EVENT - Salle 01 - Cinématique ACH 5340 OBJ 11299\n-- \nfunction event_2578_23364()\n    \nend\n\n-- FIGHT_ENDED_IN_CLIENT_EVENT - Salle 02 - Cinématique ACH 5340 OBJ 11299\n-- \nfunction event_2578_23339()\n    local playerId = Context.getLeaderId()\r\n    \r\n    startCinematicContext(1.0, playerId)\r\n    \r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\")\r\n    \r\n    --Voilà un œuf !\r\n    invoke_custom(000500, 1, \"bubble\", playerId, \"quest.brume.foret.05.00\")\r\n    invoke_custom(000500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Rire\")\r\n    invoke_custom(3500, 1, \"clearBubbles\", playerId)\r\n    \r\n    --Je dois le rapporter au Grouilleux rapidement, j'espère qu'il n'a pas fait n'importe quoi avec son artefact de Wakfu...\r\n    invoke_custom(3500, 1, \"bubble\", playerId, \"quest.brume.foret.05.01\")\r\n    invoke_custom(3500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Pointer\")\r\n    invoke_custom(13000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(13500, 1, \"skipCinematic\")\nend\n\n-- [QUÊTE] Q6 - INTERACTIVE_ELEMENT_ACTIVATION - Cinématique entrée\n-- \nfunction event_2578_23300()\n    local playerId = Context.getLeaderId()\r\n    local jenryId = createActor(117903815, -9, -17, -8, 4, 7, 6)\r\n    local timoId = createActor(1114205638, -11, -14, -8, 4, 7, 6)\r\n    \r\n    function customSkip()\r\n    \tMobile.hideOtherPlayerMobile(false)\r\n    \tParticle.removeParticleSystem(apsA)\r\n    \tParticle.removeParticleSystem(apsB)\r\n    \tParticle.removeParticleSystem(apsC)\r\n    \tUI.displayWideScreenBand(true, 25, 500)\r\n    \tskipCinematic(23300)\r\n    end\r\n    \r\n    Mobile.hideOtherPlayerMobile(true)\r\n    Mobile.setMobileDirection(playerId, 7)\r\n    \r\n    startCinematicContext(1.5, playerId)\r\n    \r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"customSkip\")\r\n    \r\n    invoke_custom(15000, 1, \"Camera.setZoomSpeedFactor\", 0.02)\r\n    \r\n    -- \"C’est vrai que ce temple fait froid dans le dos…\"\r\n    invoke_custom(01000, 1, \"bubble\", playerId, \"quest.brume.ebene.02.01\")\r\n    invoke_custom(01000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(04500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Cette eau n’est pas normale.\"\r\n    invoke_custom(05000, 1, \"bubble\", playerId, \"quest.brume.ebene.02.02\")\r\n    invoke_custom(05000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Calmer\")\r\n    invoke_custom(07500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Il n’y a pas que l’eau. Tout autour de ce temple inspire la crainte…\"\r\n    invoke_custom(07250, 1, \"bubble\", jenryId, \"quest.brume.ebene.02.03\")\r\n    invoke_custom(08000, 1, \"Mobile.setMobileDirection\", jenryId, 1)\r\n    invoke_custom(08000, 1, \"Mobile.setMobileAnimation\", jenryId, \"AnimDial-Discute\")\r\n    invoke_custom(12000, 1, \"clearBubbles\", jenryId)\r\n    \r\n    invoke_custom(12250, 1, \"Mobile.setMobileDirection\", jenryId, 3)\r\n    \r\n    -- \"À commencer par cet esprit vengeur ! Tu es certain{[1*]?e:} de vouloir y aller ?\"\r\n    invoke_custom(12500, 1, \"bubble\", jenryId, \"quest.brume.ebene.02.04\")\r\n    invoke_custom(12500, 1, \"Mobile.setMobileAnimation\", jenryId, \"AnimDial-Enerve\")\r\n    invoke_custom(16500, 1, \"clearBubbles\", jenryId)\r\n    \r\n    invoke_custom(16750, 1, \"Mobile.setMobileDirection\", playerId, 3)\r\n    \r\n    -- \"Eh bien Jenry. Je t’ai connu plus téméraire !\"\r\n    invoke_custom(17000, 1, \"bubble\", playerId, \"quest.brume.ebene.02.05\")\r\n    invoke_custom(17000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Rire\")\r\n    invoke_custom(20000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Il ne faut pas confondre courage et témérité…\"\r\n    invoke_custom(20500, 1, \"bubble\", jenryId, \"quest.brume.ebene.02.06\")\r\n    invoke_custom(20500, 1, \"Mobile.setMobileAnimation\", jenryId, \"AnimDial-Discute\")\r\n    invoke_custom(23500, 1, \"clearBubbles\", jenryId)\r\n    \r\n    -- \"Derrière ces murs se trouve certainement l’artefact que tu as tant convoité.\"\r\n    invoke_custom(24000, 1, \"bubble\", playerId, \"quest.brume.ebene.02.07\")\r\n    invoke_custom(24000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Presenter\")\r\n    invoke_custom(28500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"… C’est vrai. Ainsi que les réponses à nos questions.\"\r\n    invoke_custom(29000, 1, \"bubble\", jenryId, \"quest.brume.ebene.02.08\")\r\n    invoke_custom(29000, 1, \"Mobile.setMobileAnimation\", jenryId, \"AnimDial-OK\")\r\n    invoke_custom(32000, 1, \"clearBubbles\", jenryId)\r\n    \r\n    -- \"Ça va, je ne vous dérange pas ?\"\r\n    invoke_custom(32500, 1, \"bubble\", timoId, \"quest.brume.ebene.02.09\")\r\n    invoke_custom(32500, 1, \"Mobile.setMobileAnimation\", timoId, \"AnimSort-1\")\r\n    invoke_custom(35000, 1, \"clearBubbles\", timoId)\r\n    \r\n    -- \"C’est à toi de jouer… l’esprit. Je me rends compte que je ne t’ai pas demandé ton nom.\"\r\n    invoke_custom(35500, 1, \"bubble\", playerId, \"quest.brume.ebene.02.10\")\r\n    invoke_custom(35500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Non\")\r\n    invoke_custom(40000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"J’ai oublié mon nom lorsque le dernier Crocodaille a rendu son dernier souffle…\"\r\n    invoke_custom(40500, 1, \"bubble\", timoId, \"quest.brume.ebene.02.11\")\r\n    invoke_custom(45000, 1, \"clearBubbles\", timoId)\r\n    \r\n    -- \"Revenir dans cet endroit après tout ce temps me procure un sentiment étrange…\"\r\n    invoke_custom(45500, 1, \"bubble\", timoId, \"quest.brume.ebene.02.12\")\r\n    invoke_custom(50000, 1, \"clearBubbles\", timoId)\r\n    \r\n    -- \"… Du genre ?\"\r\n    invoke_custom(50500, 1, \"bubble\", playerId, \"quest.brume.ebene.02.13\")\r\n    invoke_custom(50500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Calmer\")\r\n    invoke_custom(53000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"J’ai l’impression d’avoir laissé une part de moi dans ce temple.\"\r\n    invoke_custom(53500, 1, \"bubble\", timoId, \"quest.brume.ebene.02.14\")\r\n    invoke_custom(56000, 1, \"clearBubbles\", timoId)\r\n    \r\n    invoke_custom(56250, 1, \"Camera.setZoomFactor\", 1.9)\r\n    \r\n    -- \"**C'est de plus en plus suspect.\"\r\n    invoke_custom(56500, 1, \"bubble\", playerId, \"quest.brume.ebene.02.15\")\r\n    invoke_custom(56500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(59000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"**Je mettrais ma main à couper que cet esprit Crocodaille est lié à leur disparition.\"\r\n    invoke_custom(59500, 1, \"bubble\", playerId, \"quest.brume.ebene.02.16\")\r\n    invoke_custom(59500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(63000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(63250, 1, \"Camera.attachCameraToMobile\", jenryId)\r\n    \r\n    -- \"**Ouh là là... Ça ne me réjouit pas...\"\r\n    invoke_custom(63500, 1, \"bubble\", jenryId, \"quest.brume.ebene.02.17\")\r\n    invoke_custom(65500, 1, \"clearBubbles\", jenryId)\r\n    \r\n    -- \"**[#name] veut absolument rentrer là-dedans, mais je ne le sens pas du tout.\"\r\n    invoke_custom(66000, 1, \"bubble\", jenryId, \"quest.brume.ebene.02.18\")\r\n    invoke_custom(69000, 1, \"clearBubbles\", jenryId)\r\n    \r\n    -- \"**Il devait y avoir un moyen plus simple... À quoi pense-t-{[1*]?elle:il} ?\"\r\n    invoke_custom(69500, 1, \"bubble\", jenryId, \"quest.brume.ebene.02.19\")\r\n    invoke_custom(72500, 1, \"clearBubbles\", jenryId)\r\n    \r\n    -- \"**Mais j’ai encore besoin de lui. Quoi que renferme ce temple, ça sent la baston à plein nez…\"\r\n    invoke_custom(73000, 1, \"bubble\", jenryId, \"quest.brume.ebene.02.20\")\r\n    invoke_custom(77000, 1, \"clearBubbles\", jenryId)\r\n    \r\n    invoke_custom(77500, 1, \"Camera.attachCameraToMobile\", playerId)\r\n    \r\n    -- \"**J'ai bien fait de faire un préparatif.\"\r\n    invoke_custom(78000, 1, \"bubble\", playerId, \"quest.brume.ebene.02.21\")\r\n    invoke_custom(81000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(81500, 1, \"fullScreen\", 1000, 7500, 1000)\r\n    \r\n    -- \"Le Zurikat récite des incantations et utilise ses pouvoirs pour déverrouiller l’accès.\"\r\n    invoke_custom(82000, 1, \"text\", 1000, 2500, 1000, \"quest.brume.ebene.02.22\")\r\n    invoke_custom(84000, 1, \"Particle.removeParticleSystem\", apsA)\r\n    invoke_custom(84000, 1, \"Particle.removeParticleSystem\", apsB)\r\n    invoke_custom(84000, 1, \"Particle.removeParticleSystem\", apsC)\r\n    \r\n    -- \"Les volutes d’énergie qui condamnaient le temple ne sont plus, vous ouvrant l’accès à ses secrets.\"\r\n    invoke_custom(86500, 1, \"text\", 1000, 3000, 1000, \"quest.brume.ebene.02.23\")\r\n    \r\n    invoke_custom(91000, 1, \"customSkip\")\r\nend\n\n-- [QUÊTE] Q6 - INTERACTIVE_ELEMENT_ACTIVATION - Quête finie\n-- \nfunction event_2578_23302()\n    \nend\n\n-- [QUÊTE] Q6 - CLIENT_TRIGGERED_EVENT - Fin de la cinématique\n-- \nfunction event_2578_23303()\n    \nend\n\n-- ENTER_INSTANCE - On cache Arlémia\n-- \nfunction event_2578_23619(arlemia)\n    Mobile.addMobileCreationCallback(arlemia, \"hideMonster\", arlemia)\nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","displayDoors","displayPath","hideMonster","hidePart","showMonster","showPart","event_2578_22964","event_2578_22965","event_2578_22978","event_2578_22977","event_2578_22966","event_2578_22986","event_2578_22967","event_2578_22969","event_2578_23203","event_2578_23364","event_2578_23339","event_2578_23300","customSkip","event_2578_23302","event_2578_23303","event_2578_23619"],"quest_calls":[],"dialogue_calls":[]},"scenario/2579.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\n\n-- [INIT] Variables Globales\n-- \nfunction event_2579_22979()\n    \nend\n\n-- [INIT] Inscription du joueur + Variables Locales\n-- \nfunction event_2579_22980()\n    \nend\n\n-- FIGHT_ENTER_ACTION_PHASE - Applique l'état de la mécanique du donjon\n-- \nfunction event_2579_23033()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 01\n-- \nfunction event_2579_22983(room)\n    \nend\n\n-- USER_GROUP_KILLED - Salle 02 - BOSS\n-- \nfunction event_2579_22984()\n    \nend\n\n-- Déplace le joueur vers la salle suivante\n-- \nfunction event_2579_22985()\n    \nend\n\n-- [QUÊTE] FIGHT_ENDED_CLIENT_EVENT - Le PJ a vaincu Imagori\n-- \nfunction event_2579_23257()\n    local playerId = Context.getLeaderId()\r\n    local lauraId = createActor(117903814, 0, -62, 0, 4, 1, 6)\r\n    \r\n    Mobile.setMobileDirection(playerId, 3)\r\n    Mobile.setMobileAnimation(playerId, \"AnimStatique02\")\r\n    \r\n    Mobile.setMobileVisible(lauraId, false)\r\n    \r\n    function customSkip()\r\n    \tMobile.hideOtherPlayerMobile(false)\r\n    \tskipCinematic(23257)\r\n    end\r\n    \r\n    Mobile.hideOtherPlayerMobile(true)\r\n    \r\n    startCinematicContext(1.2, playerId)\r\n    \r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"customSkip\")\r\n    \r\n    --Il était sacrément coriace celui-là…\r\n    invoke_custom(1, 1, \"bubble\", playerId, \"quest.brume.gori.01.01\")\r\n    invoke_custom(1, 1, \"Camera.attachCameraToMobile\", playerId)\r\n    invoke_custom(3500, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(3200, 1, \"Mobile.moveMobile\", playerId, 5, -58, 0)\r\n    \r\n    invoke_custom(3200, 1, \"Camera.setCamera\", 1.2, 5, -61, 4)\r\n    \r\n    --**Cette source est gigantesque ! On dirait une sorte… d’autel.\r\n    invoke_custom(5500, 1, \"bubble\", playerId, \"quest.brume.gori.01.03\")\r\n    invoke_custom(5500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Chercher\")\r\n    invoke_custom(9000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(9000, 1, \"Mobile.moveMobile\", playerId, 8, -60, 0)\r\n    invoke_custom(10250, 1, \"Mobile.setMobileDirection\", playerId, 7)\r\n    \r\n    --**Ces statues sont présentes sur toute l’île… Sont-elles liées à une sorte de croyance ?\r\n    invoke_custom(10500, 1, \"bubble\", playerId, \"quest.brume.gori.01.04\")\r\n    invoke_custom(10500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(15500, 1, \"clearBubbles\", playerId)\r\n    \r\n    --Laura Craft arrive sur les lieux\r\n    invoke_custom(15500, 1, \"fullScreen\", 500, 5500, 1000)\r\n    invoke_custom(15500, 1, \"text\", 1000, 4000, 1000, \"quest.brume.gori.01.02\")\r\n    \r\n    invoke_custom(20500, 1, \"Mobile.moveMobile\", playerId, 0, -60, 0)\r\n    invoke_custom(23500, 1, \"Mobile.setMobileDirection\", playerId, 7)\r\n    \r\n    --Je n’entendais plus les bruits du combat, alors je me suis dis que je pouvais te rejoindre…\r\n    invoke_custom(20500, 1, \"Camera.setZoomFactor\", 1.5)\r\n    invoke_custom(20500, 1, \"Camera.attachCameraToMobile\", lauraId)\r\n    invoke_custom(21500, 1, \"Mobile.setMobileVisible\", lauraId, true)\r\n    invoke_custom(22000, 1, \"bubble\", lauraId, \"quest.brume.gori.01.05\")\r\n    invoke_custom(30500, 1, \"clearBubbles\", lauraId)\r\n    \r\n    --… Qu’est-ce que ?!\r\n    invoke_custom(30500, 1, \"bubble\", lauraId, \"quest.brume.gori.01.06\")\r\n    invoke_custom(31000, 1, \"Camera.setCamera\", 1.2, 2, -63, 2)\r\n    invoke_custom(32500, 1, \"clearBubbles\", lauraId)\r\n    \r\n    --Ouais, c’est impressionnant. Il s’agit bien de l’origine de toutes ces anomalies.\r\n    invoke_custom(32500, 1, \"bubble\", playerId, \"quest.brume.gori.01.07\")\r\n    invoke_custom(38500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Discute\")\r\n    invoke_custom(38500, 1, \"clearBubbles\", playerId)\r\n    \r\n    --Cette source de Wakfu semble s’être formée à cause de cette fuite.\r\n    invoke_custom(38500, 1, \"bubble\", playerId, \"quest.brume.gori.01.08\")\r\n    invoke_custom(38500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Discute\")\r\n    invoke_custom(44500, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(43500, 1, \"Camera.setCamera\", 1.0, 2, -72, -10)\r\n    \r\n    invoke_custom(48000, 1, \"Camera.setZoomFactor\", 1.5)\r\n    invoke_custom(48000, 1, \"Camera.attachCameraToMobile\", lauraId)\r\n    \r\n    --Cela m’inquiète d’ailleurs, tout ce Wakfu devait bien servir à quelque chose !\r\n    invoke_custom(48500, 1, \"bubble\", lauraId, \"quest.brume.gori.01.09\")\r\n    invoke_custom(55000, 1, \"clearBubbles\", lauraId)\r\n    \r\n    --L’organisation de cette structure me donne une impression de vide…\r\n    invoke_custom(55000, 1, \"bubble\", playerId, \"quest.brume.gori.01.10\")\r\n    invoke_custom(55000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(60500, 1, \"clearBubbles\", playerId)\r\n    \r\n    --Et ces roches en lévitation… Se pourrait-il que…\r\n    invoke_custom(60500, 1, \"bubble\", playerId, \"quest.brume.gori.01.11\")\r\n    invoke_custom(60500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(64500, 1, \"clearBubbles\", playerId)\r\n    \r\n    --… Mais oui ! La météorite devait être entreposée à cet endroit !\r\n    invoke_custom(64500, 1, \"bubble\", lauraId, \"quest.brume.gori.01.12\")\r\n    invoke_custom(71000, 1, \"clearBubbles\", lauraId)\r\n    \r\n    --Et ce monstre en était sans doute le gardien.\r\n    invoke_custom(71000, 1, \"bubble\", playerId, \"quest.brume.gori.01.13\")\r\n    invoke_custom(71000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Presenter\")\r\n    invoke_custom(75500, 1, \"clearBubbles\", playerId)\r\n    \r\n    --Elle avait peut-être été placée là en état de léthargie.\r\n    invoke_custom(75500, 1, \"bubble\", lauraId, \"quest.brume.gori.01.14\")\r\n    invoke_custom(80500, 1, \"clearBubbles\", lauraId)\r\n    \r\n    --Tu penses qu’un peuple sur cette île y vouait un culte ?\r\n    invoke_custom(80500, 1, \"bubble\", playerId, \"quest.brume.gori.01.15\")\r\n    invoke_custom(80500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Effrayee\")\r\n    invoke_custom(86500, 1, \"clearBubbles\", playerId)\r\n    \r\n    --C’est une possibilité, oui.\r\n    invoke_custom(86500, 1, \"bubble\", lauraId, \"quest.brume.gori.01.16\")\r\n    invoke_custom(88500, 1, \"clearBubbles\", lauraId)\r\n    \r\n    --Cette fuite imprévue l’aurait gorgée de Wakfu, la poussant à se développer à nouveau.\r\n    invoke_custom(88500, 1, \"bubble\", lauraId, \"quest.brume.gori.01.17\")\r\n    invoke_custom(95500, 1, \"clearBubbles\", lauraId)\r\n    \r\n    --Une partie de la roche aurait alors fusionné avec ce gorille, ce qui explique son apparence.\r\n    invoke_custom(95500, 1, \"bubble\", lauraId, \"quest.brume.gori.01.18\")\r\n    invoke_custom(103500, 1, \"clearBubbles\", lauraId)\r\n    \r\n    --Et elle se serait peu à peu propagée aux autres monstres de la zone.\r\n    invoke_custom(103500, 1, \"bubble\", playerId, \"quest.brume.gori.01.19\")\r\n    invoke_custom(103500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(110500, 1, \"clearBubbles\", playerId)\r\n    \r\n    --J’ai remarqué d’autres émanations de Wakfu sur l’île.\r\n    invoke_custom(110500, 1, \"bubble\", playerId, \"quest.brume.gori.01.20\")\r\n    invoke_custom(110500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Effrayee\")\r\n    invoke_custom(114500, 1, \"clearBubbles\", playerId)\r\n    \r\n    --Rien ne dit qu’il n’existe pas d’autres structures semblables ailleurs.\r\n    invoke_custom(114500, 1, \"bubble\", playerId, \"quest.brume.gori.01.21\")\r\n    invoke_custom(114500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Pointer\")\r\n    invoke_custom(119500, 1, \"clearBubbles\", playerId)\r\n    \r\n    --Une technologie aussi avancée, cachée aussi profondément dans l’île…\r\n    invoke_custom(119500, 1, \"bubble\", lauraId, \"quest.brume.gori.01.22\")\r\n    invoke_custom(124000, 1, \"clearBubbles\", lauraId)\r\n    \r\n    --Ça ne te paraît pas bizarre ?\r\n    invoke_custom(124000, 1, \"bubble\", lauraId, \"quest.brume.gori.01.23\")\r\n    invoke_custom(127500, 1, \"clearBubbles\", lauraId)\r\n    \r\n    --J’ai l’impression que nous n’avons fait qu’effleurer la surface des secrets que renferme cette île.\r\n    invoke_custom(127500, 1, \"bubble\", playerId, \"quest.brume.gori.01.24\")\r\n    invoke_custom(127500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(135000, 1, \"clearBubbles\", playerId)\r\n    \r\n    --Pour l’heure, je ne vois pas ce que nous pouvons faire d’autre pour cet endroit…\r\n    invoke_custom(135000, 1, \"bubble\", playerId, \"quest.brume.gori.01.25\")\r\n    invoke_custom(135000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Pointer\")\r\n    invoke_custom(142500, 1, \"clearBubbles\", playerId)\r\n    \r\n    --Attends ! Je vois quelque chose dans la source !\r\n    invoke_custom(142500, 1, \"bubble\", lauraId, \"quest.brume.gori.01.26\")\r\n    invoke_custom(147500, 1, \"clearBubbles\", lauraId)\r\n    \r\n    --Avant que vous ne puissiez l’en empêcher, l’archaologue plonge ses bras dans la source de Wakfu et en ressort un artefact de la forme d’un œuf.\r\n    invoke_custom(147500, 1, \"fullScreen\", 500, 14500, 1000)\r\n    invoke_custom(148000, 1, \"text\", 1000, 6000, 1000, \"quest.brume.gori.01.27\")\r\n    \r\n    --Il irradie d’une énergie maintenant bien commune, mais il vous est difficile de savoir si cela est dû à son séjour prolongé dans la source.\r\n    invoke_custom(156000, 1, \"text\", 1000, 6000, 1000, \"quest.brume.gori.01.28\")\r\n    \r\n    --Tu as vu ça ?!\r\n    invoke_custom(164000, 1, \"bubble\", lauraId, \"quest.brume.gori.01.29\")\r\n    invoke_custom(166500, 1, \"clearBubbles\", lauraId)\r\n    \r\n    --Oooh… Je me sens pas très bien…\r\n    invoke_custom(166500, 1, \"bubble\", lauraId, \"quest.brume.gori.01.30\")\r\n    invoke_custom(170000, 1, \"clearBubbles\", lauraId)\r\n    \r\n    --Pour une érudite, tu ne réfléchis pas tant que ça avant d’agir ! Tiens, prends l’amulette.\r\n    invoke_custom(170000, 1, \"bubble\", playerId, \"quest.brume.gori.01.31\")\r\n    invoke_custom(170000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Rire\")\r\n    invoke_custom(178000, 1, \"clearBubbles\", playerId)\r\n    \r\n    --Hé hé… Pfiou… Merci, ce n’est pas passé loin !\r\n    invoke_custom(178000, 1, \"bubble\", lauraId, \"quest.brume.gori.01.32\")\r\n    invoke_custom(183000, 1, \"clearBubbles\", lauraId)\r\n    \r\n    --Allez sortons d’ici au plus vite, nous aurons tout le temps de parler de ta trouvaille dehors.\r\n    invoke_custom(183000, 1, \"bubble\", playerId, \"quest.brume.gori.01.33\")\r\n    invoke_custom(183000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Pointer\")\r\n    invoke_custom(191500, 1, \"clearBubbles\", playerId)\r\n    \r\n    --Tu as raison. Retournons au campement !\r\n    invoke_custom(191500, 1, \"bubble\", lauraId, \"quest.brume.gori.01.34\")\r\n    invoke_custom(195000, 1, \"clearBubbles\", lauraId)\r\n    \r\n    invoke_custom(196000, 1, \"customSkip\")\nend\n\n-- [QUÊTE] CLIENT_TRIGGERED_EVENT - Fin de la cinématique - Notif ACH 5342 OBJ 11276\n-- \nfunction event_2579_23258()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_2579_22979","event_2579_22980","event_2579_23033","event_2579_22983","event_2579_22984","event_2579_22985","event_2579_23257","customSkip","event_2579_23258"],"quest_calls":[],"dialogue_calls":[]},"scenario/2580.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\n-- les fonctions où on cache\r\nfunction hideMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, false)\r\nend\r\n\r\nfunction hidePart(monsterMobileId, partName)\r\n\tMobile.setPartVisible(monsterMobileId, false, partName)\r\nend\r\n\r\n-- les fonctions où on rend visible (à nouveau)\r\nfunction showMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, true)\r\nend\r\n\r\nfunction showPart(monsterMobileId, partName)\r\n\tMobile.setPartVisible(monsterMobileId, true, partName)\r\nend\n\n-- [INIT] Variables Globales\n-- \nfunction event_2580_22987()\n    \nend\n\n-- [INIT] Inscription du joueur + Variables Locales\n-- \nfunction event_2580_22988()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 01\n-- \nfunction event_2580_22989(room)\n    \nend\n\n-- USER_GROUP_KILLED - Salle 02 - BOSS\n-- \nfunction event_2580_22990()\n    \nend\n\n-- Déplace le joueur vers la salle suivante\n-- \nfunction event_2580_22991()\n    \nend\n\n-- FIGHT_ENTER_ACTION_PHASE - On pose les zones piliers dans la salle du boss\n-- \nfunction event_2580_23096()\n    \nend\n\n-- FIGHT_ENDED - Placement des monstres dans la salle du boss\n-- \nfunction event_2580_23097()\n    \nend\n\n-- FIGHT_ENTER_ACTION_PHASE - Applique l'état \"Donjon\"\n-- \nfunction event_2580_23098()\n    \nend\n\n-- [COMBAT] Achievement 5421- L'Armure stellaire fragilisée baisse\n-- \nfunction event_2580_23121()\n    \nend\n\n-- [COMBAT] Achievement 5421- Validation\n-- \nfunction event_2580_23122()\n    \nend\n\n-- [COMBAT] Achievement 5422 - Timö possède \"Possession d'âme\" au niveau 4 mini\n-- \nfunction event_2580_23119()\n    \nend\n\n-- [COMBAT] Achievement 5422 - Validation\n-- \nfunction event_2580_23120()\n    \nend\n\n-- [QUÊTE] FIGHT_ENDED_CLIENT_EVENT - Le PJ a vaincu Timö\n-- \nfunction event_2580_23225()\n    local playerId = Context.getLeaderId()\r\n    local timoId = createActor(1114205638, -46, 2, -16, 4, 1, 6)\r\n    \r\n    Mobile.setMobileDirection(playerId, 5)\r\n    Mobile.setMobileAnimation(playerId, \"AnimStatique02\")\r\n    \r\n    function customSkip()\r\n    \tMobile.hideOtherPlayerMobile(false)\r\n    \tskipCinematic(23225)\r\n    end\r\n    \r\n    Mobile.hideOtherPlayerMobile(true)\r\n    \r\n    startCinematicContext(1.0, timoId)\r\n    \r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"customSkip\")\r\n    \r\n    invoke_custom(01000, 1, \"Camera.setMoveSpeedFactor\", 0.2)\r\n    invoke_custom(01000, 1, \"Camera.setZoomSpeedFactor\", 0.02)\r\n    \r\n    -- \"Argh… Damnation !\"\r\n    invoke_custom(01000, 1, \"bubble\", timoId, \"quest.brume.timo.00.01\")\r\n    invoke_custom(01000, 1, \"Mobile.setMobileAnimation\", timoId, \"AnimSort-1\")\r\n    invoke_custom(02500, 1, \"clearBubbles\", timoId)\r\n    \r\n    invoke_custom(03000, 1, \"Camera.setZoomFactor\", 1.4)\r\n    \r\n    -- \"Pour un{[1*]?e:} aventuri{[1*]?ère:er}, tu es bien coriace !\"\r\n    invoke_custom(03000, 1, \"bubble\", timoId, \"quest.brume.timo.00.02\")\r\n    invoke_custom(06000, 1, \"clearBubbles\", timoId)\r\n    \r\n    -- \"Mais… Tu parles ?\"\r\n    invoke_custom(06500, 1, \"bubble\", playerId, \"quest.brume.timo.00.03\")\r\n    invoke_custom(06000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimStatique02-Fin\")\r\n    invoke_custom(06500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Effrayee\")\r\n    invoke_custom(08500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Toujours la même chose avec les Douziens...\"\r\n    invoke_custom(09000, 1, \"bubble\", timoId, \"quest.brume.timo.00.04\")\r\n    invoke_custom(11500, 1, \"clearBubbles\", timoId)\r\n    \r\n    -- \"Vous croyez tous être les seuls doués de parole.\"\r\n    invoke_custom(12000, 1, \"bubble\", timoId, \"quest.brume.timo.00.05\")\r\n    invoke_custom(14500, 1, \"clearBubbles\", timoId)\r\n    \r\n    -- \"Pour le coup, c’est juste que j’ai vu un autre Zurikat, nommé Brössar.\"\r\n    invoke_custom(15000, 1, \"bubble\", playerId, \"quest.brume.timo.00.06\")\r\n    invoke_custom(15000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Calmer\")\r\n    invoke_custom(18500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Il ne sait pas dire autre chose que gnouknouk et chtingchting...\"\r\n    invoke_custom(19000, 1, \"bubble\", playerId, \"quest.brume.timo.00.07\")\r\n    invoke_custom(19000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Presenter\")\r\n    invoke_custom(21000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmoteMarket-HausseEpaules\")\r\n    invoke_custom(22500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Je suppose que tu parles de papy Brössar, maître de la savane.\"\r\n    invoke_custom(23000, 1, \"bubble\", timoId, \"quest.brume.timo.00.08\")\r\n    invoke_custom(26500, 1, \"clearBubbles\", timoId)\r\n    \r\n    -- \"Tu le connais ?\"\r\n    invoke_custom(27000, 1, \"bubble\", playerId, \"quest.brume.timo.00.09\")\r\n    invoke_custom(25000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Acquiescer\")\r\n    invoke_custom(27500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Pointer\")\r\n    invoke_custom(29500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"...\"\r\n    invoke_custom(30000, 1, \"bubble\", timoId, \"quest.brume.timo.00.10\")\r\n    invoke_custom(32000, 1, \"clearBubbles\", timoId)\r\n    \r\n    -- \"Bon. Tu es qui, concrètement ?\"\r\n    invoke_custom(32500, 1, \"bubble\", playerId, \"quest.brume.timo.00.11\")\r\n    invoke_custom(32500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(35000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"J'imagine que ce n'est pas au Zurikat que je m'adresse.\"\r\n    invoke_custom(35500, 1, \"bubble\", playerId, \"quest.brume.timo.00.12\")\r\n    invoke_custom(35500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Calmer\")\r\n    invoke_custom(39000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"J'incarne le ressentiment de tout un peuple exterminé dans le sang et les larmes…\"\r\n    invoke_custom(39500, 1, \"bubble\", timoId, \"quest.brume.timo.00.13\")\r\n    invoke_custom(39500, 1, \"Mobile.setMobileAnimation\", timoId, \"AnimSort-1\")\r\n    invoke_custom(43500, 1, \"clearBubbles\", timoId)\r\n    \r\n    -- \"Tu veux dire que tu es un esprit vengeur ?\"\r\n    invoke_custom(44000, 1, \"bubble\", playerId, \"quest.brume.timo.00.14\")\r\n    invoke_custom(44000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmoteMarket-HausseEpaules\")\r\n    invoke_custom(47000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"C'est un peu réducteur…\"\r\n    invoke_custom(47500, 1, \"bubble\", timoId, \"quest.brume.timo.00.15\")\r\n    invoke_custom(49500, 1, \"clearBubbles\", timoId)\r\n    \r\n    -- \"Mais oui, on pourrait dire ça comme ça.\"\r\n    invoke_custom(50000, 1, \"bubble\", timoId, \"quest.brume.timo.00.16\")\r\n    invoke_custom(52500, 1, \"clearBubbles\", timoId)\r\n    \r\n    -- \"Mon peuple a été massacré il y a de cela deux quarts de siècle.\"\r\n    invoke_custom(53000, 1, \"bubble\", timoId, \"quest.brume.timo.00.17\")\r\n    invoke_custom(56000, 1, \"clearBubbles\", timoId)\r\n    \r\n    -- \"Deux quarts de siècle... Attends, il faut que je compte.\"\r\n    invoke_custom(56500, 1, \"bubble\", playerId, \"quest.brume.timo.00.18\")\r\n    invoke_custom(56500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(59000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Toutes ces années de tourment et de déchirement m’ont rendu fou !\"\r\n    invoke_custom(59500, 1, \"bubble\", timoId, \"quest.brume.timo.00.19\")\r\n    invoke_custom(59500, 1, \"Mobile.setMobileAnimation\", timoId, \"AnimSort-1\")\r\n    invoke_custom(62500, 1, \"clearBubbles\", timoId)\r\n    \r\n    -- \"Libère-moi, et je ferai courir ma terrible vengeance sur le peuple Bwork.\"\r\n    invoke_custom(63000, 1, \"bubble\", timoId, \"quest.brume.timo.00.20\")\r\n    invoke_custom(66500, 1, \"clearBubbles\", timoId)\r\n    \r\n    -- \"Tu as besoin d’aide, non ?\"\r\n    invoke_custom(67000, 1, \"bubble\", timoId, \"quest.brume.timo.00.21\")\r\n    invoke_custom(69000, 1, \"clearBubbles\", timoId)\r\n    \r\n    -- \"Je pourrais te prêter mon pouvoir si tu me libères…\"\r\n    invoke_custom(69500, 1, \"bubble\", timoId, \"quest.brume.timo.00.22\")\r\n    invoke_custom(72500, 1, \"clearBubbles\", timoId)\r\n    \r\n    -- \"Je vois, tu es prisonnier d’entre ces piliers.\"\r\n    invoke_custom(73000, 1, \"bubble\", playerId, \"quest.brume.timo.00.23\")\r\n    invoke_custom(73000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Non\")\r\n    invoke_custom(76000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Un sceau te retient ici.\"\r\n    invoke_custom(76500, 1, \"bubble\", playerId, \"quest.brume.timo.00.24\")\r\n    invoke_custom(76500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Calmer\")\r\n    invoke_custom(78500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Oui. Des maudits chamans Bwork m’ont enfermé ici.\"\r\n    invoke_custom(79000, 1, \"bubble\", timoId, \"quest.brume.timo.00.25\")\r\n    invoke_custom(82000, 1, \"clearBubbles\", timoId)\r\n    \r\n    -- \"Après avoir tué chaque Crocodaille jusqu’au dernier…\"\r\n    invoke_custom(82500, 1, \"bubble\", timoId, \"quest.brume.timo.00.26\")\r\n    invoke_custom(85500, 1, \"clearBubbles\", timoId)\r\n    \r\n    -- \"Même les enfants !\"\r\n    invoke_custom(86000, 1, \"bubble\", timoId, \"quest.brume.timo.00.27\")\r\n    invoke_custom(86000, 1, \"Mobile.setMobileAnimation\", timoId, \"AnimSort-1\")\r\n    invoke_custom(88000, 1, \"clearBubbles\", timoId)\r\n    \r\n    -- \"Libère-moi ! Laisse-moi accomplir ma vengeance.\"\r\n    invoke_custom(88500, 1, \"bubble\", timoId, \"quest.brume.timo.00.28\")\r\n    invoke_custom(92000, 1, \"clearBubbles\", timoId)\r\n    \r\n    -- \"Je t’accorderai un vœu.\"\r\n    invoke_custom(92500, 1, \"bubble\", timoId, \"quest.brume.timo.00.29\")\r\n    invoke_custom(95000, 1, \"clearBubbles\", timoId)\r\n    \r\n    -- \"Hum...\"\r\n    invoke_custom(95500, 1, \"bubble\", playerId, \"quest.brume.timo.00.30\")\r\n    invoke_custom(95500, 1, \"Mobile.setMobileDirection\", playerId, 3)\r\n    invoke_custom(95500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(97500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Tiens, qu’est-ce que c’est que ça ?\"\r\n    invoke_custom(098000, 1, \"bubble\", playerId, \"quest.brume.timo.00.31\")\r\n    invoke_custom(098000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-ChercherPiste\")\r\n    invoke_custom(101000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"C’est une sorte de médaillon.\"\r\n    invoke_custom(101500, 1, \"bubble\", playerId, \"quest.brume.timo.00.32\")\r\n    invoke_custom(101500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Coucou\")\r\n    invoke_custom(103500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Ah ah ! C'est à moi, il a dû tomber pendant le combat.\"\r\n    invoke_custom(104000, 1, \"bubble\", timoId, \"quest.brume.timo.00.33\")\r\n    invoke_custom(107000, 1, \"clearBubbles\", timoId)\r\n    \r\n    -- \"Vas-y, garde-le, il est à toi si tu veux.\"\r\n    invoke_custom(107500, 1, \"bubble\", timoId, \"quest.brume.timo.00.34\")\r\n    invoke_custom(110000, 1, \"clearBubbles\", timoId)\r\n    \r\n    -- \"Oh chouette. Merci, j’imagine.\"\r\n    invoke_custom(110500, 1, \"bubble\", playerId, \"quest.brume.timo.00.35\")\r\n    invoke_custom(110500, 1, \"Mobile.setMobileDirection\", playerId, 5)\r\n    invoke_custom(110500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Pouce\")\r\n    invoke_custom(113000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Bon, je ne crois pas que je trouverai grand-chose de plus ici.\"\r\n    invoke_custom(113500, 1, \"bubble\", playerId, \"quest.brume.timo.00.36\")\r\n    invoke_custom(113500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Presenter\")\r\n    invoke_custom(117000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"... Libère-moi !\"\r\n    invoke_custom(117500, 1, \"bubble\", timoId, \"quest.brume.timo.00.37\")\r\n    invoke_custom(117500, 1, \"Mobile.setMobileAnimation\", timoId, \"AnimSort-1\")\r\n    invoke_custom(119500, 1, \"clearBubbles\", timoId)\r\n    \r\n    -- \"Je verrai plus tard ce que je fais de toi.\"\r\n    invoke_custom(120000, 1, \"bubble\", playerId, \"quest.brume.timo.00.38\")\r\n    invoke_custom(120000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Calmer\")\r\n    invoke_custom(123000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Oh, une dernière chose, tu as entendu parler de Crocobur ?\"\r\n    invoke_custom(123500, 1, \"bubble\", playerId, \"quest.brume.timo.00.39\")\r\n    invoke_custom(123500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Presenter\")\r\n    invoke_custom(127500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"… Hum…\"\r\n    invoke_custom(128000, 1, \"bubble\", timoId, \"quest.brume.timo.00.40\")\r\n    invoke_custom(128000, 1, \"Mobile.setMobileDirection\", timoId, 7)\r\n    invoke_custom(130000, 1, \"clearBubbles\", timoId)\r\n    \r\n    invoke_custom(130000, 1, \"Mobile.setMobileDirection\", timoId, 1)\r\n    \r\n    -- \"C’est l’épée que possédait Crocatzin, notre roi.\"\r\n    invoke_custom(130500, 1, \"bubble\", timoId, \"quest.brume.timo.00.41\")\r\n    invoke_custom(133000, 1, \"clearBubbles\", timoId)\r\n    \r\n    -- \"Crocatzin ? Pas Crocoburio ?\"\r\n    invoke_custom(133500, 1, \"bubble\", playerId, \"quest.brume.timo.00.42\")\r\n    invoke_custom(133500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(136000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Hum... Tu sais où la trouver ?\"\r\n    invoke_custom(136500, 1, \"bubble\", playerId, \"quest.brume.timo.00.43\")\r\n    invoke_custom(136500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Calmer\")\r\n    invoke_custom(139000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Libère-moi d’ici et je t’y accompagne sans problème.\"\r\n    invoke_custom(139500, 1, \"bubble\", timoId, \"quest.brume.timo.00.44\")\r\n    invoke_custom(142500, 1, \"clearBubbles\", timoId)\r\n    \r\n    -- \"Tu veux mettre la main sur l’épée, non ?\"\r\n    invoke_custom(143000, 1, \"bubble\", timoId, \"quest.brume.timo.00.45\")\r\n    invoke_custom(145500, 1, \"clearBubbles\", timoId)\r\n    \r\n    -- \"Faisons un pacte…\"\r\n    invoke_custom(146000, 1, \"bubble\", timoId, \"quest.brume.timo.00.46\")\r\n    invoke_custom(146500, 1, \"Mobile.setMobileAnimation\", timoId, \"AnimSort-1\")\r\n    invoke_custom(148000, 1, \"clearBubbles\", timoId)\r\n    \r\n    invoke_custom(148000, 1, \"Camera.attachCameraToMobile\", playerId)\r\n    \r\n    -- \"Mouais...\"\r\n    invoke_custom(148500, 1, \"bubble\", playerId, \"quest.brume.timo.00.47\")\r\n    invoke_custom(148500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Bailler\")\r\n    invoke_custom(150500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Pour l’instant, je ferai mieux de retourner voir Jenry et Brössar.\"\r\n    invoke_custom(151000, 1, \"bubble\", playerId, \"quest.brume.timo.00.48\")\r\n    invoke_custom(151000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Presenter\")\r\n    invoke_custom(154500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"À plus !\"\r\n    invoke_custom(155000, 1, \"bubble\", playerId, \"quest.brume.timo.00.49\")\r\n    invoke_custom(156000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Coucou\")\r\n    invoke_custom(157500, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(157500, 1, \"Mobile.moveMobile\", playerId, -22, 2, 0)\r\n    \r\n    invoke_custom(160000, 1, \"Camera.attachCameraToMobile\", timoId)\r\n    invoke_custom(162000, 1, \"Camera.setZoomFactor\", 1.8)\r\n    \r\n    -- \"Brössar...\"\r\n    invoke_custom(160500, 1, \"bubble\", timoId, \"quest.brume.timo.00.50\")\r\n    invoke_custom(162000, 1, \"clearBubbles\", timoId)\r\n    \r\n    -- \"Brössar !\"\r\n    invoke_custom(162500, 1, \"bubble\", timoId, \"quest.brume.timo.00.51\")\r\n    invoke_custom(164500, 1, \"clearBubbles\", timoId)\r\n    \r\n    -- \"Jirp ! Jiiiirp !\"\r\n    invoke_custom(165000, 1, \"Mobile.setMobileDirection\", timoId, 3)\r\n    invoke_custom(165000, 1, \"bubble\", timoId, \"quest.brume.timo.00.52\")\r\n    invoke_custom(167000, 1, \"clearBubbles\", timoId)\r\n    \r\n    -- \"Jostirk gelp ! Grrr !\"\r\n    invoke_custom(167500, 1, \"Mobile.setMobileDirection\", timoId, 5)\r\n    invoke_custom(167500, 1, \"bubble\", timoId, \"quest.brume.timo.00.53\")\r\n    invoke_custom(169500, 1, \"clearBubbles\", timoId)\r\n    \r\n    -- \"Oh, la ferme !\"\r\n    invoke_custom(170000, 1, \"Mobile.setMobileDirection\", timoId, 1)\r\n    invoke_custom(170000, 1, \"bubble\", timoId, \"quest.brume.timo.00.54\")\r\n    invoke_custom(170000, 1, \"Mobile.setMobileAnimation\", timoId, \"AnimSort-1\")\r\n    invoke_custom(172000, 1, \"clearBubbles\", timoId)\r\n    \r\n    -- \"Mouahaha... Quel idiot{[1*]?e:}.\"\r\n    invoke_custom(172500, 1, \"Mobile.setMobileDirection\", timoId, 1)\r\n    invoke_custom(172500, 1, \"bubble\", timoId, \"quest.brume.timo.00.55\")\r\n    invoke_custom(175000, 1, \"clearBubbles\", timoId)\r\n    \r\n    -- \"Les Douziens sont décidément tous les mêmes...\"\r\n    invoke_custom(175500, 1, \"bubble\", timoId, \"quest.brume.timo.00.56\")\r\n    invoke_custom(178000, 1, \"clearBubbles\", timoId)\r\n    \r\n    invoke_custom(178500, 1, \"customSkip\")\nend\n\n-- [QUÊTE] CLIENT_TRIGGERED_EVENT - Fin de la cinématique - Notif ACH 5342 OBJ 11276\n-- \nfunction event_2580_23226()\n    \nend\n\n-- ENTER_INSTANCE - On cache Arlémia\n-- \nfunction event_2580_23617(arlemia)\n    Mobile.addMobileCreationCallback(arlemia, \"hideMonster\", arlemia)\nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","hideMonster","hidePart","showMonster","showPart","event_2580_22987","event_2580_22988","event_2580_22989","event_2580_22990","event_2580_22991","event_2580_23096","event_2580_23097","event_2580_23098","event_2580_23121","event_2580_23122","event_2580_23119","event_2580_23120","event_2580_23225","customSkip","event_2580_23226","event_2580_23617"],"quest_calls":[],"dialogue_calls":[]},"scenario/2581.lua":{"source":"-- les fonctions où on cache\r\nfunction hideMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, false)\r\nend\r\n\r\nfunction hidePart(monsterMobileId, partName)\r\n\tMobile.setPartVisible(monsterMobileId, false, partName)\r\nend\r\n\r\n-- les fonctions où on rend visible (à nouveau)\r\nfunction showMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, true)\r\nend\r\n\r\nfunction showPart(monsterMobileId, partName)\r\n\tMobile.setPartVisible(monsterMobileId, true, partName)\r\nend\n\n-- [INIT] Variables Globales\n-- \nfunction event_2581_22992()\n    \nend\n\n-- [INIT] Inscription du joueur + Variables Locales\n-- \nfunction event_2581_22993(zulnara)\n    zulnara = toLong(zulnara)\r\n    \r\n    Mobile.addMobileCreationCallback(zulnara, \"hideMonster\", zulnara)\nend\n\n-- USER_GROUP_KILLED - Salle 01\n-- \nfunction event_2581_22994()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 02 - BOSS\n-- \nfunction event_2581_22995()\n    \nend\n\n-- Déplace le joueur vers la salle suivante\n-- \nfunction event_2581_22996()\n    \nend\n\n-- FIGHT_ENTER_ACTION_PHASE - Applique l'état \"Donjon\"\n-- \nfunction event_2581_23094()\n    \nend\n\n-- [QUÊTE] On cache Zulnara après la salle 1\n-- \nfunction event_2581_23235(zulnara, zulnaraB)\n    Mobile.addMobileCreationCallback(zulnara, \"hideMonster\", zulnara)\r\n    Mobile.addMobileCreationCallback(zulnaraB, \"hideMonster\", zulnaraB)\nend\n\n-- [QUÊTE] On affiche Zulnara après la salle 2\n-- \nfunction event_2581_23236(zulnara, zulnaraB)\n    Mobile.addMobileCreationCallback(zulnaraB, \"showMonster\", zulnaraB)\nend\n\n-- [EVENT] Changement de Musique quand Alraune apparait\n-- \nfunction event_2581_23373()\n    Sound.playFightMusic(290035, 55)\nend\n\n","functions":["hideMonster","hidePart","showMonster","showPart","event_2581_22992","event_2581_22993","event_2581_22994","event_2581_22995","event_2581_22996","event_2581_23094","event_2581_23235","event_2581_23236","event_2581_23373"],"quest_calls":[],"dialogue_calls":[]},"scenario/2582.lua":{"source":"\n\n-- [INIT] Variables Globales\n-- \nfunction event_2582_22997()\n    \nend\n\n-- [INIT] Inscription du joueur + Variables Locales\n-- \nfunction event_2582_22998()\n    \nend\n\n-- FIGHT_STARTED - Salle 01\n-- \nfunction event_2582_23089()\n    \nend\n\n-- FIGHT_ENTER_ACTION_PHASE - Salle 01\n-- \nfunction event_2582_23516()\n    \nend\n