76()\n    \nend\n\n-- [INIT] Spawn Noxines - 1135 - Sufokia\n-- \nfunction event_2586_23077()\n    \nend\n\n-- [INIT] Spawn Noxines - 1136 - Bonta\n-- \nfunction event_2586_23078()\n    \nend\n\n-- [INIT] Spawn Noxines - 1137 - Brakmar\n-- \nfunction event_2586_23079()\n    \nend\n\n-- [INIT] Spawn Noxines - 1252 - Pandalousie\n-- \nfunction event_2586_23080()\n    \nend\n\n-- [INIT] Spawn Noxines - 1264 - Royaume Sadida\n-- \nfunction event_2586_23081()\n    \nend\n\n-- [INIT] Spawn Noxines - 1295 - Royaume Chuchoku\n-- \nfunction event_2586_23082()\n    \nend\n\n-- [INIT] Spawn Noxines - 1358 - Ereboria 01\n-- \nfunction event_2586_23083()\n    \nend\n\n-- [INIT] Spawn Noxines - 1359 - Ereboria 02\n-- \nfunction event_2586_23084()\n    \nend\n\n-- [INIT] Spawn Noxines - 1384 - ïle des Wabbits 01\n-- \nfunction event_2586_23085()\n    \nend\n\n","functions":["event_2586_23065","event_2586_23086","event_2586_23036","event_2586_23066","event_2586_23067","event_2586_23068","event_2586_23069","event_2586_23070","event_2586_23071","event_2586_23072","event_2586_23073","event_2586_23074","event_2586_23075","event_2586_23076","event_2586_23077","event_2586_23078","event_2586_23079","event_2586_23080","event_2586_23081","event_2586_23082","event_2586_23083","event_2586_23084","event_2586_23085"],"quest_calls":[],"dialogue_calls":[]},"scenario/2587.lua":{"source":"\n\n-- [INIT] Despawn les Monstres Cyclique liés à l'Event\n-- \nfunction event_2587_23064()\n    \nend\n\n-- [INIT] Désactivation des IE liés à l'Event\n-- \nfunction event_2587_23087()\n    \nend\n\n","functions":["event_2587_23064","event_2587_23087"],"quest_calls":[],"dialogue_calls":[]},"scenario/2588.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\n-- les fonctions où on cache\r\nfunction hideMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, false)\r\nend\r\n\r\nfunction hidePart(monsterMobileId, partName)\r\n\tMobile.setPartVisible(monsterMobileId, false, partName)\r\nend\r\n\r\n-- les fonctions où on rend visible (à nouveau)\r\nfunction showMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, true)\r\nend\r\n\r\nfunction showPart(monsterMobileId, partName)\r\n\tMobile.setPartVisible(monsterMobileId, true, partName)\r\nend\r\n\r\n\r\n-- \"Fonction d'affichage du tp\"\r\nfunction displayTeleporter(forestGenerator, canyonGenerator, savannahGenerator, swampsGenerator, desolationGenerator, everyGeneratorOn, miloId)\r\n\r\nif (forestGenerator == 1) then\r\n\tif (forestAps ~= nil) then\r\n\t\tParticle.removeParticleSystem(forestAps)\r\n\tend\t\r\n\tforestAps = Particle.addParticleSystem(7000111, -38, -152, 3)\r\nend\r\n\r\nif (canyonGenerator == 1) then\r\n\tif (canyonAps ~= nil) then\r\n\t\tParticle.removeParticleSystem(canyonAps)\r\n\tend\t\r\n\tcanyonAps = Particle.addParticleSystem(7000112, -38, -152, 3)\r\nend\r\n\r\nif (savannahGenerator == 1) then\r\n\tif (savannahAps ~= nil) then\r\n\t\tParticle.removeParticleSystem(savannahAps)\r\n\tend\t\r\n\tsavannahAps = Particle.addParticleSystem(7000113, -38, -152, 3)\r\nend\r\n\r\nif (swampsGenerator == 1) then\r\n\tif (swampsAps ~= nil) then\r\n\t\tParticle.removeParticleSystem(swampsAps)\r\n\tend\t\r\n\tswampsAps = Particle.addParticleSystem(7000114, -38, -152, 3)\r\nend\r\n\r\nif (desolationGenerator == 1) then\r\n\tif (desolationAps ~= nil) then\r\n\t\tParticle.removeParticleSystem(desolationAps)\r\n\tend\t\r\n\tdesolationAps = Particle.addParticleSystem(7000115, -38, -152, 3)\r\nend\r\n\r\nif (everyGeneratorOn == 1) then\r\n\tif (tpAps ~= nil) then\r\n\t\tParticle.removeParticleSystem(tpAps)\r\n\tend\r\n\ttpAps = Particle.addParticleSystem(7086001, -40, -154, 5)\r\n\tMobile.addMobileCreationCallback(miloId, \"hideMonster\", miloId)\r\nend\r\n\r\nend\n\n-- [INITIALISATION] Serveur\n-- \nfunction event_2588_23099()\n    \nend\n\n-- EXIT_INSTANCE / PLAYER_LEVEL_UP - Event 1.86 - Retrait de l'état de boost XP\n-- \nfunction event_2588_23224()\n    \nend\n\n-- Q0 - ENTER_INSTANCE - Cinématique Arrivée (ACH 5332 OBJ 11244)\n-- \nfunction event_2588_23100(julpiMdc, noxelanste)\n    local playerId = Context.getLeaderId()\r\n    local julpi = createActor(1114705617, 16, -182, 0, 4, 1, 6)\r\n    local julpiMdc = toLong(julpiMdc)\r\n    local noxelanste = toLong(noxelanste)\r\n    local meccanox = createActor(1115205618, 18, -184, 0, 4, 3, 6)\r\n    local grouilleuxOne = createActor(118300946, 17, -180, 0, 4, 7, 6)\r\n    local grouilleuxTwo = createActor(118300946, 19, -179, 0, 4, 7, 6)\r\n    local grouilleuxThree = createActor(118300946, 21, -183, 0, 4, 5, 6)\r\n    \r\n    function customSkip()\r\n    \tMobile.hideOtherPlayerMobile(false)\r\n    \tMobile.setMobileVisible(julpiMdc, true)\r\n    \tMobile.setMobileVisible(noxelanste, true)\r\n    \tskipCinematic(23100)\r\n    end\r\n    \r\n    Mobile.hideOtherPlayerMobile(true)\r\n    Mobile.setMobileVisible(julpiMdc, false)\r\n    Mobile.setMobileVisible(noxelanste, false)\r\n    fullScreen(1000, 26000, 1000)\r\n    \r\n    startCinematicContext(1.0, playerId)\r\n    \r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"customSkip\")\r\n    \r\n    invoke_custom(00001, 1, \"Mobile.setMobileMovementStyle\", playerId, \"WALK\", \"WALK\")\r\n    invoke_custom(00001, 1, \"Mobile.setCustomWalkStyle\", playerId, \"AnimMarche\", 600)\r\n       \r\n    invoke_custom(00500, 1, \"Camera.setMoveSpeedFactor\", 0.2)\r\n    invoke_custom(00500, 1, \"Camera.setZoomSpeedFactor\", 0.2)\r\n    \r\n    -- \"Vous descendez du bateau. Les marins qui ont accepté de vous accompagner s’empressent de repartir…\"\r\n    invoke_custom(01000, 1, \"text\", 500, 5000, 500, \"quest.brume.intro.01.01\")\r\n    \r\n    -- \"Vous voilà sur la mythique Île des brumes, une île habituellement cachée dont on dit que personne n’a jamais pu ressortir.\"\r\n    invoke_custom(07000, 1, \"text\", 500, 5000, 500, \"quest.brume.intro.01.02\")\r\n    \r\n    -- \"Depuis l'aube des temps, seules des rumeurs évoquaient cette île secrète, cachée derrière un épais brouillard. L'île des brumes est soudainement apparue dans la mer il y a quelques années. Son irruption a attisé votre curiosité.\"\r\n    invoke_custom(13000, 1, \"text\", 500, 10000, 500, \"quest.brume.intro.01.03\")\r\n    \r\n    -- \"Votre nouvelle aventure commence sur ce camp... qui fait aussi office de port de fortune.\"\r\n    invoke_custom(24000, 1, \"text\", 500, 5000, 500, \"quest.brume.intro.01.05\")\r\n    \r\n    invoke_custom(27000, 1, \"Mobile.moveMobile\", playerId, 7, -170, 0, \"Mobile.setMobileDirection\", playerId, 1)\r\n    \r\n    -- \"Ainsi, voilà la fameuse Île des brumes…\"\r\n    invoke_custom(31500, 1, \"bubble\", playerId, \"quest.brume.intro.01.06\")\r\n    invoke_custom(33000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Chercher\")\r\n    invoke_custom(34500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Je m’attendais à quelque chose de plus typique.\"\r\n    invoke_custom(35500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(35000, 1, \"bubble\", playerId, \"quest.brume.intro.01.07\")\r\n    invoke_custom(38000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(39000, 1, \"Camera.setCamera\", 1.6, 17, -180, 0)\r\n    \r\n    -- \"Pitié, maître Meccanox… Donnez-nous une gorgée d’eau…\"\r\n    invoke_custom(40000, 1, \"Sound.playSound\", 320118300946001, true, 25)\r\n    invoke_custom(40000, 1, \"bubble\", grouilleuxOne, \"quest.brume.intro.01.08\")\r\n    invoke_custom(48000, 1, \"clearBubbles\", grouilleuxOne)\r\n    \r\n    -- \"Nous ne demandons qu’une gorgée par semaine…\"\r\n    invoke_custom(43000, 1, \"Sound.playSound\", 3201114705617001, true, 45)\r\n    invoke_custom(43000, 1, \"bubble\", julpi, \"quest.brume.intro.01.09\")\r\n    invoke_custom(48000, 1, \"clearBubbles\", julpi)\r\n    \r\n    -- \"Je vous implore…\"\r\n    invoke_custom(40000, 1, \"Sound.playSound\", 320118300946002, true, 25)\r\n    invoke_custom(45000, 1, \"bubble\", grouilleuxThree, \"quest.brume.intro.01.10\")\r\n    invoke_custom(48000, 1, \"clearBubbles\", grouilleuxThree)\r\n    \r\n    invoke_custom(47500, 1, \"Camera.setMoveSpeedFactor\", 2.1)\r\n    invoke_custom(47500, 1, \"Camera.setZoomSpeedFactor\", 2.1)\r\n    invoke_custom(48000, 1, \"Camera.setCamera\", 1.4, 18, -184, 0)\r\n    \r\n    -- \"Il suffit !\"\r\n    invoke_custom(48000, 1, \"Sound.playSound\", 320145405618001, true, 45)\r\n    invoke_custom(48000, 1, \"bubble\", meccanox, \"quest.brume.intro.01.11\")\r\n    invoke_custom(50500, 1, \"clearBubbles\", meccanox)\r\n    \r\n    -- \"Retournez au travail, ou je vous ferai fouetter !\"\r\n    invoke_custom(51000, 1, \"Sound.playSound\", 320145405618002, true, 45)\r\n    invoke_custom(51000, 1, \"bubble\", meccanox, \"quest.brume.intro.01.12\")\r\n    invoke_custom(54000, 1, \"clearBubbles\", meccanox)\r\n    \r\n    -- \"Oui, maître Meccanox...\"\r\n    invoke_custom(54500, 1, \"Sound.playSound\", 320118300946002, true, 25)\r\n    invoke_custom(54500, 1, \"bubble\", grouilleuxThree, \"quest.brume.intro.01.13\")\r\n    invoke_custom(57500, 1, \"clearBubbles\", grouilleuxThree)\r\n    \r\n    -- \"Merci, maître Meccanox...\"\r\n    invoke_custom(57500, 1, \"Sound.playSound\", 320118300946001, true, 25)\r\n    invoke_custom(57500, 1, \"bubble\", grouilleuxTwo, \"quest.brume.intro.01.14\")\r\n    invoke_custom(59500, 1, \"clearBubbles\", grouilleuxTwo)\r\n    \r\n    invoke_custom(56000, 1, \"Mobile.moveMobile\", playerId, 18, -182, 0, \"Mobile.setMobileDirection\", playerId, 7)\r\n    invoke_custom(59500, 1, \"Camera.attachCameraToMobile\", playerId)\r\n    \r\n    -- \"**Qu’est-ce qui se passe ici, encore ?\"\r\n    invoke_custom(60500, 1, \"bubble\", playerId, \"quest.brume.intro.01.15\")\r\n    invoke_custom(63500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Hé, vous là. Ça va pas ou quoi ? Non mais oh !\"\r\n    invoke_custom(64000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Pointe\")\r\n    invoke_custom(64000, 1, \"bubble\", playerId, \"quest.brume.intro.01.16\")\r\n    invoke_custom(68000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"… C’est pas bien, ce que vous faites !\"\r\n    invoke_custom(69000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Non\")\r\n    invoke_custom(69000, 1, \"bubble\", playerId, \"quest.brume.intro.01.17\")\r\n    invoke_custom(72000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(69000, 1, \"Camera.setZoomSpeedFactor\", 0.2)\r\n    invoke_custom(69000, 1, \"Camera.setCamera\", 1.0, 18, -182, 0)\r\n    \r\n    -- \"Quelle répartie !\"\r\n    invoke_custom(72500, 1, \"Sound.playSound\", 320118300946003, true, 25)\r\n    invoke_custom(72500, 1, \"bubble\", grouilleuxOne, \"quest.brume.intro.01.18\")\r\n    invoke_custom(75500, 1, \"clearBubbles\", grouilleuxOne)\r\n    \r\n    -- \"Ce{[1*]?tte:} Douzien{[1*]?ne:} maîtrise l’art de la parole !\"\r\n    invoke_custom(73500, 1, \"Sound.playSound\", 3201114705617002, true, 45)\r\n    invoke_custom(73500, 1, \"bubble\", julpi, \"quest.brume.intro.01.19\")\r\n    invoke_custom(77000, 1, \"clearBubbles\", julpi)\r\n    \r\n    invoke_custom(77000, 1, \"Camera.setCamera\", 1.0, 18, -184, 0)\r\n    \r\n    -- \"Euh… C’est-à-dire que…\"\r\n    invoke_custom(77500, 1, \"Sound.playSound\", 320145405618003, true, 45)\r\n    invoke_custom(77500, 1, \"bubble\", meccanox, \"quest.brume.intro.01.20\")\r\n    invoke_custom(80000, 1, \"clearBubbles\", meccanox)\r\n    \r\n    -- \"… J’ai à faire. Au revoir ! Tsss.\"\r\n    invoke_custom(81000, 1, \"Sound.playSound\", 320145405618001, true, 45)\r\n    invoke_custom(81000, 1, \"bubble\", meccanox, \"quest.brume.intro.01.21\")\r\n    invoke_custom(84000, 1, \"clearBubbles\", meccanox)\r\n    \r\n    -- \"Meccanox part et les Grouilleux s’approchent de vous, visiblement très reconnaissants\"\r\n    invoke_custom(084500, 1, \"fullScreen\", 1000, 6000, 1000)\r\n    invoke_custom(084500, 1, \"text\", 1000, 6000, 1000, \"quest.brume.intro.01.22\")\r\n    \r\n    invoke_custom(087000, 1, \"Camera.setCamera\", 1.5, 9, -177, 0)\r\n    \r\n    invoke_custom(087000, 1, \"Mobile.setMobileVisible\", meccanox, false)\r\n    invoke_custom(087000, 1, \"Mobile.setMobilePosition\", playerId, 9, -177, 0)\r\n    invoke_custom(087000, 1, \"Mobile.setMobileDirection\", playerId, 7)\r\n    \r\n    invoke_custom(087000, 1, \"Mobile.setMobilePosition\", julpi, 9, -181, 0)\r\n    invoke_custom(087000, 1, \"Mobile.setMobileDirection\", julpi, 3)\r\n    \r\n    invoke_custom(087000, 1, \"Mobile.setMobilePosition\", grouilleuxOne, 7, -178, 0)\r\n    invoke_custom(087000, 1, \"Mobile.setMobileDirection\", grouilleuxOne, 1)\r\n    \r\n    invoke_custom(087000, 1, \"Mobile.setMobilePosition\", grouilleuxTwo, 8, -180, 0)\r\n    invoke_custom(087000, 1, \"Mobile.setMobileDirection\", grouilleuxTwo, 3)\r\n    \r\n    invoke_custom(087000, 1, \"Mobile.setMobilePosition\", grouilleuxThree, 12, -177, 0)\r\n    invoke_custom(087000, 1, \"Mobile.setMobileDirection\", grouilleuxThree, 5)\r\n    \r\n    -- \"Vous êtes notre sauveu{[1*]?se:r}.\"\r\n    invoke_custom(092500, 1, \"Sound.playSound\", 320118300946001, true, 25)\r\n    invoke_custom(092500, 1, \"bubble\", grouilleuxOne, \"quest.brume.intro.01.23\")\r\n    invoke_custom(095500, 1, \"clearBubbles\", grouilleuxOne)\r\n    \r\n    -- \"Non mais ça va...\"\r\n    invoke_custom(096000, 1, \"bubble\", playerId, \"quest.brume.intro.01.24\")\r\n    invoke_custom(096000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Calmer\")\r\n    invoke_custom(099000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Nous avons besoin de vous.\"\r\n    invoke_custom(099500, 1, \"Sound.playSound\", 320118300946002, true, 25)\r\n    invoke_custom(099500, 1, \"Camera.attachCameraToMobile\", grouilleuxThree)\r\n    invoke_custom(099500, 1, \"bubble\", grouilleuxThree, \"quest.brume.intro.01.25\")\r\n    invoke_custom(102000, 1, \"clearBubbles\", grouilleuxThree)\r\n    \r\n    -- \"Avec vous à nos côtés, nous pourrions donner une bonne leçon à Meccanox !\"\r\n    invoke_custom(102500, 1, \"Sound.playSound\", 320118300946003, true, 25)\r\n    invoke_custom(102500, 1, \"Camera.attachCameraToMobile\", grouilleuxTwo)\r\n    invoke_custom(102500, 1, \"bubble\", grouilleuxTwo, \"quest.brume.intro.01.26\")\r\n    invoke_custom(107000, 1, \"clearBubbles\", grouilleuxTwo)\r\n    \r\n    -- \"Je m'appelle Julpi. Je suis la chef de la résistance.\"\r\n    invoke_custom(107500, 1, \"Sound.playSound\", 3201114705617002, true, 45)\r\n    invoke_custom(107500, 1, \"Camera.attachCameraToMobile\", julpi)\r\n    invoke_custom(107500, 1, \"bubble\", julpi, \"quest.brume.intro.01.27\")\r\n    invoke_custom(111000, 1, \"clearBubbles\", julpi)\r\n    \r\n    -- \"Résister ? Contre quoi, exactement ?\"\r\n    invoke_custom(111500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Presenter\")\r\n    invoke_custom(111500, 1, \"bubble\", playerId, \"quest.brume.intro.01.28\")\r\n    invoke_custom(115000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Je vais tout vous expliquer…\"\r\n    invoke_custom(115500, 1, \"Sound.playSound\", 3201114705617001, true, 45)\r\n    invoke_custom(115500, 1, \"bubble\", julpi, \"quest.brume.intro.01.29\")\r\n    invoke_custom(118000, 1, \"clearBubbles\", julpi)\r\n    \r\n    -- \"Suivez-nous dans notre QG !\"\r\n    invoke_custom(118500, 1, \"Sound.playSound\", 3201114705617003, true, 45)\r\n    invoke_custom(118500, 1, \"bubble\", julpi, \"quest.brume.intro.01.30\")\r\n    invoke_custom(122000, 1, \"clearBubbles\", julpi)\r\n    \r\n    invoke_custom(122500, 1, \"customSkip\")\nend\n\n-- Q0 - Fin cinématique Arrivée (ACH 5332 OBJ 11244)\n-- \nfunction event_2588_23101()\n    \nend\n\n-- QP-1 - POSITION_TRIGGER - Le joueur passe devant le donjon - ACH 5340 OBJ 11298\n-- \nfunction event_2588_23153()\n    local playerId = Context.getLeaderId()\r\n    \r\n    BubbleText.closeBubbleAttachedTo(playerId)\r\n    \r\n    local bubbleId = BubbleText.prepareWakfuBubble(playerId, 0, 60, false)\r\n    BubbleText.setText(bubbleId, \"quest.brume.foret.02.00\")\r\n    BubbleText.attachToMobile(bubbleId, playerId)\r\n    BubbleText.show(bubbleId)\nend\n\n-- Q3 - RESOURCE_COLLECTED_EVENT - Notif ACH 5341 OBJ 11272\n-- \nfunction event_2588_23319()\n    \nend\n\n-- Q6 - DIALOG_EXECUTED - Cinématique \"à suivre\"\n-- \nfunction event_2588_23329()\n    local playerId = Context.getLeaderId()\r\n    \r\n    function customSkip()\r\n    \tSound.stopForcedMusic()\r\n    \tMobile.hideOtherPlayerMobile(false)\r\n    \tEffect.stopEffect(redTextId)\r\n    \tskipCinematic(23329)\r\n    end\r\n    \r\n    function redText(fadein, duration, fadeout, translationKey)\r\n    \tredTextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.0, 0.0, 1.0, \"bagnard\", 30, 4)\r\n    end\r\n    \r\n    Mobile.hideOtherPlayerMobile(true)\r\n    fullScreen(1000, 56000, 1000)\r\n    \r\n    startCinematicContext(1.0, playerId)\r\n    \r\n    invoke_custom(00010, 1, \"Sound.stopForcedMusic\")\r\n    invoke_custom(00100, 1, \"Sound.playForcedMusic\", 210002, 25)\r\n    \r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"customSkip\")\r\n    \r\n    -- \"Vous avez vécu une sacrée aventure.\"\r\n    -- \"Bulak, Nox, les destins croisés des Crocdailles et des Bworks, les Archaologues...\"\r\n    invoke_custom(00001, 1, \"text\", 1000, 7000, 1000, \"quest.brume.ebene.07.01\")\r\n    \r\n    -- \"(Et les Grouilleux...)\"\r\n    invoke_custom(09000, 1, \"text\", 1000, 1000, 1000, \"quest.brume.ebene.07.02\")\r\n    \r\n    -- \"Vous jetez un oeil à votre Dofus Ébène. Entre vos mains, il semble inactif... Peut-être qu'avoir utilisé son pouvoir pour détruire Crocobur l'a privé de sa puissance habituelle.\"\r\n    invoke_custom(12000, 1, \"text\", 1000, 8000, 1000, \"quest.brume.ebene.07.03\")\r\n    \r\n    -- \"Une vision d'une plage ensoleillée vous saisit brutalement et votre coeur se pince inexpliquablement.\"\r\n    -- \"La Réminiscence vous envahit et vous quitte aussitôt, ne laissant qu'une chaleur à la fois dérangeante et nostalgique dans votre corps.\"\r\n    invoke_custom(22000, 1, \"redText\", 1000, 8000, 1000, \"quest.brume.ebene.07.04\")\r\n    \r\n    -- \"Des visions du passé et du futur s'entrechoquent sans que vous ne les compreniez.\"\r\n    -- \"Et si vous n'étiez pas de ce monde ? Et si vous étiez quelqu'un d'autre ? Et si vos émotions ne vous appartenaient pas vraiment ?\"\r\n    invoke_custom(32000, 1, \"redText\", 1000, 8000, 1000, \"quest.brume.ebene.07.05\")\r\n    \r\n    -- \"Et si... Rien de tout ça n'était vrai ?\"\r\n    invoke_custom(42000, 1, \"redText\", 1000, 2000, 1000, \"quest.brume.ebene.07.06\")\r\n    \r\n    -- \"Vous revenez à la raison dans la hutte du Zurikat.\"\r\n    -- \"Vous songez qu'un peu de repos ne vous ferait pas de mal...\"\r\n    invoke_custom(46000, 1, \"text\", 1000, 4000, 1000, \"quest.brume.ebene.07.07\")\r\n    \r\n    --\"Il faudra régler son compte à l'horloger et pour cela, vous aurez besoin de récupérer de votre affrontement avec Bulak.\"\r\n    invoke_custom(52000, 1, \"text\", 1000, 4000, 1000, \"quest.brume.ebene.07.08\")\r\n    \r\n    invoke_custom(58000, 1, \"customSkip\")\nend\n\n-- Q6 - Fin de la cinématique - On valide l'achievement\n-- \nfunction event_2588_23330()\n    \nend\n\n-- ENTER_INSTANCE - Gestion APS téléporteur central + variable cinéPilliers à 0\n-- \nfunction event_2588_23338(forestGenerator, canyonGenerator, savannahGenerator, swampsGenerator, desolationGenerator, everyGeneratorOn, miloId)\n    local forestGenerator = toLong(forestGenerator)\r\n    local canyonGenerator = toLong(canyonGenerator)\r\n    local savannahGenerator = toLong(savannahGenerator)\r\n    local swampsGenerator = toLong(swampsGenerator)\r\n    local desolationGenerator = toLong(desolationGenerator)\r\n    local everyGeneratorOn = toLong(everyGeneratorOn)\r\n    \r\n    displayTeleporter(forestGenerator, canyonGenerator, savannahGenerator, swampsGenerator, desolationGenerator, everyGeneratorOn, miloId)\nend\n\n-- POSITION_TRIGGER - Gestion APS téléporteur central\n-- \nfunction event_2588_23334(forestGenerator, canyonGenerator, savannahGenerator, swampsGenerator, desolationGenerator, miloId, everyGeneratorOn)\n    local forestGenerator = toLong(forestGenerator)\r\n    local canyonGenerator = toLong(canyonGenerator)\r\n    local savannahGenerator = toLong(savannahGenerator)\r\n    local swampsGenerator = toLong(swampsGenerator)\r\n    local desolationGenerator = toLong(desolationGenerator)\r\n    local everyGeneratorOn = toLong(everyGeneratorOn)\r\n    \r\n    displayTeleporter(forestGenerator, canyonGenerator, savannahGenerator, swampsGenerator, desolationGenerator, everyGeneratorOn, miloId)\nend\n\n-- POSITION_TRIGGER - Première cinématique\n-- \nfunction event_2588_23335(miloId)\n    local playerId = Context.getLeaderId()\r\n    local miloId = toLong(miloId)\r\n    \r\n    local miloCine = createActor(117903818, -51, -149, 0, 4, 1, 6)\r\n    \r\n    function customSkip()\r\n    \tMobile.hideOtherPlayerMobile(false)\r\n    \tMobile.setMobileVisible(miloId, true)\r\n    \tskipCinematic(23335)\r\n    end\r\n    \r\n    Mobile.setMobileVisible(miloId, false)\r\n    Mobile.setMobileVisible(miloCine, false)\r\n    \r\n    Mobile.hideOtherPlayerMobile(true)\r\n    fullScreen(10, 1000, 1000)\r\n    \r\n    startCinematicContext(1.2, playerId)\r\n    \r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"customSkip\")\r\n    \r\n    invoke_custom(00500, 1, \"Mobile.setMobilePosition\", playerId, -45, -160, 0)\r\n    invoke_custom(00500, 1, \"Mobile.setMobileMovementStyle\", playerId, \"WALK\", \"WALK\")\r\n    invoke_custom(00500, 1, \"Mobile.setCustomWalkStyle\", playerId, \"AnimMarche\", 600)\r\n    invoke_custom(01000, 1, \"Mobile.moveMobile\", playerId, -45, -152, 0, \"Mobile.setMobileDirection\", playerId, 1)\r\n    \r\n    -- \"Ces ruines… Elles dégagent une aura particulière.\"\r\n    invoke_custom(06000, 1, \"bubble\", playerId, \"quest.brume.secret.01.01\")\r\n    invoke_custom(06500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmoteMarket-HausseEpaules\")\r\n    invoke_custom(09000, 1, \"clearBubbles\", playerId)\r\n    invoke_custom(08000, 1, \"Mobile.moveMobile\", playerId, -45, -147, 0, \"Mobile.setMobileDirection\", playerId, 3)\r\n    \r\n    -- Périphérie\r\n    -- \"J’ai l’impression que c’est un mécanisme. Vu sa taille, il doit être d’une certaine importance.\"\r\n    invoke_custom(09500, 1, \"bubble\", playerId, \"quest.brume.secret.01.02\")\r\n    --invoke_custom(09500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(15000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(12450, 1, \"Mobile.setMobileMovementStyle\", playerId, \"WALK\", \"WALK\")\r\n    invoke_custom(12450, 1, \"Mobile.setCustomWalkStyle\", playerId, \"AnimMarche\", 600)\r\n    \r\n    invoke_custom(12500, 1, \"Mobile.moveMobile\", playerId, -41, -147, 0, \"Mobile.setMobileDirection\", playerId, 3)\r\n    \r\n    invoke_custom(15450, 1, \"Mobile.setMobileMovementStyle\", playerId, \"WALK\", \"WALK\")\r\n    invoke_custom(15450, 1, \"Mobile.setCustomWalkStyle\", playerId, \"AnimMarche\", 600)\r\n    \r\n    invoke_custom(15500, 1, \"Mobile.moveMobile\", playerId, -40, -150, 0, \"Mobile.setMobileDirection\", playerId, 7)\r\n    \r\n    -- Engin du milieu\r\n    -- \"Ces tuyaux semblent aller sous terre et ces structures… On dirait de l’Eliatrope !\"\r\n    invoke_custom(17500, 1, \"bubble\", playerId, \"quest.brume.secret.01.03\")\r\n    invoke_custom(17500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-ChercherPiste\")\r\n    invoke_custom(21000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(20500, 1, \"Mobile.setMobileVisible\", miloCine, true)\r\n    invoke_custom(20500, 1, \"Mobile.moveMobile\", miloCine, -42, -150, 0, \"Mobile.setMobileDirection\", miloCine, 1)\r\n    invoke_custom(21250, 1, \"Camera.attachCameraToMobile\", miloCine)\r\n    \r\n    -- Déplacement\r\n    -- \"[#name] ? C’est bien toi ?!\"\r\n    invoke_custom(21500, 1, \"bubble\", miloCine, \"quest.brume.secret.01.04\")\r\n    invoke_custom(24000, 1, \"clearBubbles\", miloCine)\r\n    \r\n    -- Se retourne\r\n    -- \"Milo ?! Je ne pensais pas te retrouver sur cette île légendaire !\"\r\n    invoke_custom(22000, 1, \"Mobile.setMobileDirection\", playerId, 5)\r\n    \r\n    invoke_custom(24500, 1, \"bubble\", playerId, \"quest.brume.secret.01.05\")\r\n    invoke_custom(24500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Coucou\")\r\n    invoke_custom(27500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Je suis comme toi, toujours à courir après des mythes et des légendes !\"\r\n    invoke_custom(28000, 1, \"bubble\", miloCine, \"quest.brume.secret.01.06\")\r\n    invoke_custom(28000, 1, \"Mobile.setMobileAnimation\", miloCine, \"AnimComp-OuiEnthousiaste\")\r\n    invoke_custom(31000, 1, \"clearBubbles\", miloCine)\r\n    \r\n    -- \"C’est vrai que c’est rapidement devenu mon quotidien !\"\r\n    invoke_custom(31500, 1, \"bubble\", playerId, \"quest.brume.secret.01.07\")\r\n    invoke_custom(31500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Rire\")\r\n    invoke_custom(34000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"L'île n'est pas trop dangereuse pour un archéologue ?\"\r\n    invoke_custom(34500, 1, \"bubble\", playerId, \"quest.brume.secret.01.08\")\r\n    invoke_custom(34500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Calmer\")\r\n    invoke_custom(37000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Je ne vais pas te mentir : je passe la majorité de mon temps à fuir ces monstres et à me cacher…\"\r\n    invoke_custom(37500, 1, \"bubble\", miloCine, \"quest.brume.secret.01.09\")\r\n    invoke_custom(37500, 1, \"Mobile.setMobileAnimation\", miloCine, \"AnimComp-NonNerveux\")\r\n    invoke_custom(42000, 1, \"clearBubbles\", miloCine)\r\n    \r\n    -- \"Mais quand je vois ces ruines, je me dis que cela vaut la peine de risquer ma peau !\"\r\n    invoke_custom(42500, 1, \"bubble\", miloCine, \"quest.brume.secret.01.10\")\r\n    invoke_custom(42500, 1, \"Mobile.setMobileAnimation\", miloCine, \"AnimComp-Parler\")\r\n    invoke_custom(47000, 1, \"clearBubbles\", miloCine)\r\n    \r\n    -- \"Que représentent des reptiles mortels, face aux secrets millénaires de civilisations oubliées finalement ?\"\r\n    invoke_custom(47500, 1, \"bubble\", miloCine, \"quest.brume.secret.01.11\")\r\n    invoke_custom(47500, 1, \"Mobile.setMobileAnimation\", miloCine, \"AnimComp-OuiEnthousiaste\")\r\n    invoke_custom(52000, 1, \"clearBubbles\", miloCine)\r\n    \r\n    -- \"Mais… et ta fille ? Je croyais que tu voulais lui consacrer plus de temps dorénavant.\"\r\n    invoke_custom(52500, 1, \"bubble\", playerId, \"quest.brume.secret.01.12\")\r\n    invoke_custom(52500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(56500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Avec Arlémia c’est… compliqué. Je ne pouvais pas laisser passer cette opportunité, Sufokia avait besoin de moi pour cette expédition.\"\r\n    invoke_custom(57000, 1, \"bubble\", miloCine, \"quest.brume.secret.01.13\")\r\n    invoke_custom(57000, 1, \"Mobile.setMobileAnimation\", miloCine, \"AnimComp-SurprisPeur\")\r\n    invoke_custom(63000, 1, \"clearBubbles\", miloCine)\r\n    \r\n    -- \"Tu es sûr de ne pas te chercher des excuses là ?\"\r\n    invoke_custom(63500, 1, \"bubble\", playerId, \"quest.brume.secret.01.14\")\r\n    invoke_custom(63500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Non\")\r\n    invoke_custom(66000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"… Je suis certain qu’elle comprendra les impératifs de mon travail avec le temps !\"\r\n    invoke_custom(66500, 1, \"bubble\", miloCine, \"quest.brume.secret.01.15\")\r\n    invoke_custom(66500, 1, \"Mobile.setMobileAnimation\", miloCine, \"AnimComp-NonNerveux\")\r\n    invoke_custom(70000, 1, \"clearBubbles\", miloCine)\r\n    \r\n    -- \"J’imagine qu’on ne change pas sa nature aussi facilement qu’on le voudrait… Je suis content{[1*]?e:} qu’il ne soit pas mon père.\"\r\n    invoke_custom(70500, 1, \"bubble\", playerId, \"quest.brume.secret.01.16\")\r\n    invoke_custom(70500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(75500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Si tu le dis… Bon, tu as pu étudier ces ruines ? On dirait de la technologie Eliatrope.\"\r\n    invoke_custom(76000, 1, \"bubble\", playerId, \"quest.brume.secret.01.17\")\r\n    invoke_custom(76000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Presenter\")\r\n    invoke_custom(79500, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(79500, 1, \"Mobile.setMobileMovementStyle\", miloCine, \"WALK\", \"WALK\")\r\n    invoke_custom(79500, 1, \"Mobile.setCustomWalkStyle\", miloCine, \"AnimMarche-Boucle\", 600)\r\n    \r\n    --Déplacement\r\n    invoke_custom(79250, 1, \"Mobile.moveMobile\", miloCine, -42, -153, 0, \"Mobile.setMobileDirection\", miloCine, 1)\r\n    invoke_custom(81250, 1, \"Mobile.moveMobile\", playerId, -42, -152, 0, \"Mobile.setMobileDirection\", playerId, 1)\r\n    \r\n    -- \"Oui tu as l'œil ! Cela semble pourtant assez différent des zaaps qu’on a l’habitude de voir un peu partout.\"\r\n    invoke_custom(80000, 1, \"bubble\", miloCine, \"quest.brume.secret.01.18\")\r\n    invoke_custom(80000, 1, \"Mobile.setMobileAnimation\", miloCine, \"AnimEmote-Presenter\")\r\n    invoke_custom(84500, 1, \"clearBubbles\", miloCine)\r\n    \r\n    -- \"Tu penses que ce mécanisme sert à autre chose ?\"\r\n    invoke_custom(85000, 1, \"bubble\", playerId, \"quest.brume.secret.01.19\")\r\n    invoke_custom(85000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Pointer\")\r\n    invoke_custom(87500, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(87500, 1, \"Camera.setZoomSpeedFactor\", 0.01)\r\n    invoke_custom(87500, 1, \"Camera.setZoomFactor\", 1.5)\r\n    \r\n    invoke_custom(87750, 1, \"Mobile.setMobileDirection\", miloCine, 3)\r\n    \r\n    -- \"Difficile à dire en l’état… Tout ce que j’ai pu déterminer, c’est que ces ruines sont sans doute reliées à d’autres endroits de l’île.\"\r\n    invoke_custom(88000, 1, \"bubble\", miloCine, \"quest.brume.secret.01.20\")\r\n    invoke_custom(88000, 1, \"Mobile.setMobileAnimation\", miloCine, \"AnimComp-Parler\")\r\n    invoke_custom(92500, 1, \"clearBubbles\", miloCine)\r\n    \r\n    invoke_custom(92750, 1, \"Mobile.setMobileDirection\", playerId, 7)\r\n    \r\n    -- \"Qu’est-ce qui te fait dire ça ?\"\r\n    invoke_custom(093000, 1, \"bubble\", playerId, \"quest.brume.secret.01.21\")\r\n    invoke_custom(093000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(095500, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(095750, 1, \"Mobile.setMobileDirection\", miloCine, 1)\r\n    invoke_custom(097750, 1, \"Mobile.setMobileDirection\", playerId, 1)\r\n    invoke_custom(098750, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    \r\n    -- \"Ces tuyaux et ces emplacements autour de la base. J’ai l’intuition qu’ils servent à afficher quelque chose…\"\r\n    invoke_custom(096000, 1, \"bubble\", miloCine, \"quest.brume.secret.01.22\")\r\n    invoke_custom(096000, 1, \"Mobile.setMobileAnimation\", miloCine, \"AnimComp-Parler\")\r\n    invoke_custom(100000, 1, \"clearBubbles\", miloCine)\r\n    \r\n    -- \"Mon hypothèse est que le mécanisme n’est que la partie visible de quelque chose de plus grand.\"\r\n    invoke_custom(100500, 1, \"bubble\", miloCine, \"quest.brume.secret.01.23\")\r\n    invoke_custom(100500, 1, \"Mobile.setMobileAnimation\", miloCine, \"AnimComp-Parler\")\r\n    invoke_custom(104500, 1, \"clearBubbles\", miloCine)\r\n    \r\n    -- \"C’est bien possible, ce n'est pas la seule ruine sur cette île… J’imagine que tu comptes sur moi pour vérifier cette théorie.\"\r\n    invoke_custom(105000, 1, \"bubble\", playerId, \"quest.brume.secret.01.24\")\r\n    invoke_custom(105000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmoteMarket-HausseEpaules\")\r\n    invoke_custom(109500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Précisément !\"\r\n    invoke_custom(110000, 1, \"bubble\", miloCine, \"quest.brume.secret.01.25\")\r\n    invoke_custom(110000, 1, \"Mobile.setMobileAnimation\", miloCine, \"AnimComp-OuiEnthousiaste\")\r\n    invoke_custom(112500, 1, \"clearBubbles\", miloCine)\r\n    \r\n    -- \"Tu es l{[1*]?a:e} plus qualifié{[1*]?e:} pour explorer cette île. Si tu trouves quoi que ce soit, tu n’auras qu’à venir m’en parler.\"\r\n    invoke_custom(113000, 1, \"bubble\", miloCine, \"quest.brume.secret.01.26\")\r\n    invoke_custom(113000, 1, \"Mobile.setMobileAnimation\", miloCine, \"AnimComp-Parler\")\r\n    invoke_custom(117000, 1, \"clearBubbles\", miloCine)\r\n    \r\n    -- \"Allez, je marche. Moi aussi, je suis intrigué{[1*]?e:} par ces ruines !\"\r\n    invoke_custom(117500, 1, \"bubble\", playerId, \"quest.brume.secret.01.27\")\r\n    invoke_custom(117500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Victoire\")\r\n    invoke_custom(121500, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(122000, 1, \"customSkip\")\nend\n\n-- CLIENT_TRIGGERED_EVENT - Première cinématique finie - Notif ACH 5333\n-- \nfunction event_2588_23336()\n    \nend\n\n-- POSITION_TRIGGER - Cinématique coeur activé\n-- \nfunction event_2588_23341(miloId)\n    local playerId = Context.getLeaderId()\r\n    local miloId = toLong(miloId)\r\n    \r\n    function customSkip()\r\n    \tMobile.hideOtherPlayerMobile(false)\r\n    \tskipCinematic(23341)\r\n    end\r\n    \r\n    Mobile.setMobileVisible(miloId, false)\r\n    \r\n    Mobile.hideOtherPlayerMobile(true)\r\n    fullScreen(10, 1000, 1000)\r\n    \r\n    startCinematicContext(1.2, playerId)\r\n    \r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"customSkip\")\r\n    \r\n    invoke_custom(00500, 1, \"Mobile.setMobilePosition\", playerId, -45, -160, 0)\r\n    invoke_custom(00500, 1, \"Mobile.setMobileMovementStyle\", playerId, \"WALK\", \"WALK\")\r\n    invoke_custom(00500, 1, \"Mobile.setCustomWalkStyle\", playerId, \"AnimMarche\", 600)\r\n    invoke_custom(01000, 1, \"Mobile.moveMobile\", playerId, -45, -152, 0, \"Mobile.setMobileDirection\", playerId, 3)\r\n    \r\n    -- \"Bah… Où est Milo ?.\"\r\n    invoke_custom(06000, 1, \"bubble\", playerId, \"quest.brume.coeur.01.01\")\r\n    invoke_custom(06500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmoteMarket-HausseEpaules\")\r\n    invoke_custom(09000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(09000, 1, \"Mobile.setMobileDirection\", playerId, 7)\r\n    invoke_custom(09500, 1, \"Mobile.setMobileDirection\", playerId, 5)\r\n    invoke_custom(10000, 1, \"Mobile.setMobileDirection\", playerId, 1)\r\n    invoke_custom(10000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Chercher\")\r\n    \r\n    -- \"Ah le dispositif s’est activé ! On dirait un genre de portail…\"\r\n    invoke_custom(10500, 1, \"bubble\", playerId, \"quest.brume.coeur.01.02\")\r\n    invoke_custom(12500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(13500, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(13750, 1, \"Camera.setCamera\", 1.4, -39, -153, 3)\r\n    \r\n    invoke_custom(13750, 1, \"Mobile.moveMobile\", playerId, -42, -152, 0)\r\n    \r\n    -- \"J’imagine qu’il n’a pas résisté à l’envie de me griller la politesse…\"\r\n    invoke_custom(14000, 1, \"bubble\", playerId, \"quest.brume.coeur.01.03\")\r\n    invoke_custom(16000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Non\")\r\n    invoke_custom(17500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Remarque, ça lui ressemble bien. Se soucier des autres n’a jamais été son point fort !\"\r\n    invoke_custom(18000, 1, \"bubble\", playerId, \"quest.brume.coeur.01.04\")\r\n    invoke_custom(18000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Calmer\")\r\n    invoke_custom(21500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Bon eh bien, je n’ai plus qu’à le rejoindre !\"\r\n    invoke_custom(22000, 1, \"bubble\", playerId, \"quest.brume.coeur.01.05\")\r\n    invoke_custom(22000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Victoire\")\r\n    invoke_custom(25000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(25500, 1, \"customSkip\")\nend\n\n-- CLIENT_TRIGGERED_EVENT - Cinématique finie - Notif ACH 5333 OBJ 11208\n-- \nfunction event_2588_23342()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","hideMonster","hidePart","showMonster","showPart","displayTeleporter","event_2588_23099","event_2588_23224","event_2588_23100","customSkip","event_2588_23101","event_2588_23153","event_2588_23319","event_2588_23329","customSkip","redText","event_2588_23330","event_2588_23338","event_2588_23334","event_2588_23335","customSkip","event_2588_23336","event_2588_23341","customSkip","event_2588_23342"],"quest_calls":[],"dialogue_calls":[]},"scenario/2589.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\n-- les fonctions où on cache\r\nfunction hideMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, false)\r\nend\r\n\r\nfunction hidePart(monsterMobileId, partName)\r\n\tMobile.setPartVisible(monsterMobileId, false, partName)\r\nend\r\n\r\n-- les fonctions où on rend visible (à nouveau)\r\nfunction showMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, true)\r\nend\r\n\r\nfunction showPart(monsterMobileId, partName)\r\n\tMobile.setPartVisible(monsterMobileId, true, partName)\r\nend\n\n-- [INITIALISATION] Serveur\n-- \nfunction event_2589_23111()\n    \nend\n\n-- Q0 - ENTER_INSTANCE - On cache Meccanox selon le contexte\n-- \nfunction event_2589_23177(meccanoxPnj)\n    Mobile.setMobileVisible(meccanoxPnj, false)\nend\n\n-- Q0 - ENTER_INSTANCE - On cache les archaologues selon le contexte\n-- \nfunction event_2589_23517(laura, jenry, lebbocq, milo, amelia, arlemia)\n    Mobile.setMobileVisible(laura, false)\r\n    Mobile.setMobileVisible(jenry, false)\r\n    Mobile.setMobileVisible(lebbocq, false)\r\n    Mobile.setMobileVisible(milo, false)\r\n    Mobile.setMobileVisible(amelia, false)\r\n    Mobile.setMobileVisible(arlemia, false)\nend\n\n-- Q0 - DIALOG_EXECUTED - Cinématique Nox (ACH 5332 OBJ 11244)\n-- \nfunction event_2589_23112(julpiMdc, grouilleuxOne, grouilleuxTwo, grouilleuxThree, grouilleuxFour, meccanoxPnj)\n    local playerId = Context.getLeaderId()\r\n    local julpiMdc = toLong(julpiMdc)\r\n    local grouilleuxOne = toLong(grouilleuxOne)\r\n    local grouilleuxTwo = toLong(grouilleuxTwo)\r\n    local grouilleuxThree = toLong(grouilleuxThree)\r\n    local grouilleuxFour = toLong(grouilleuxFour)\r\n    local meccanoxPnj = toLong(meccanoxPnj)\r\n    \r\n    local julpi = createActor(1114705617, 25, -2, -19, 4, 3, 6)\r\n    local meccanox = createActor(1115205618, 23, 0, -19, 4, 1, 6)\r\n    local grouilleuxA = createActor(118300946, 26, 5, -19, 4, 7, 6)\r\n    local grouilleuxB = createActor(118300946, 24, 5, -19, 4, 7, 6)\r\n    local grouilleuxC = createActor(118300946, 28, 2, -19, 4, 5, 6)\r\n    local nox = createActor(1115005718 , 25, 0, -19, 4, 3, 10)\r\n    \r\n    function customSkip()\r\n    \tMobile.hideOtherPlayerMobile(false)\r\n    \tMobile.setMobileVisible(julpiMdc, true)\r\n    \tMobile.setMobileVisible(grouilleuxOne, true)\r\n    \tMobile.setMobileVisible(grouilleuxTwo, true)\r\n    \tMobile.setMobileVisible(grouilleuxThree, true)\r\n    \tMobile.setMobileVisible(grouilleuxFour, true)\r\n    \tMobile.setMobileVisible(meccanoxPnj, true)\r\n    \tEffect.stopEffect(fullScreenId)\r\n    \tEffect.stopEffect(textId)\r\n    \tskipCinematic(23112)\r\n    end\r\n    \r\n    Mobile.hideOtherPlayerMobile(true)\r\n    Mobile.setMobileVisible(julpiMdc, false)\r\n    Mobile.setMobileVisible(grouilleuxOne, false)\r\n    Mobile.setMobileVisible(grouilleuxTwo, false)\r\n    Mobile.setMobileVisible(grouilleuxThree, false)\r\n    Mobile.setMobileVisible(grouilleuxFour, false)\r\n    Mobile.setMobileVisible(meccanoxPnj, false)\r\n    Mobile.setMobileVisible(nox, false)\r\n    Mobile.setMobileDirection(playerId, 5)\r\n    \r\n    Effect.createFullScreenSprite(200, 5000, 1000, 0.0, 0.0, 0.0)\r\n    -- \"Meccanox fait irruption dans la pièce, l'air furieux\"\r\n    text(200, 5000, 500, \"quest.brume.intro.02.00\")\r\n    \r\n    Actor.equip(playerId, \"51332313\", \"VETEMENTCUSTOM\")\r\n    \r\n    startCinematicContext(1.3, meccanox)\r\n    \r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"customSkip\")\r\n    \r\n    invoke_custom(0050, 1, \"Sound.stopForcedMusic\")\r\n    invoke_custom(00100, 1, \"Sound.playForcedMusic\", 210079, 50)\r\n    \r\n    invoke_custom(00500, 1, \"Camera.setMoveSpeedFactor\", 0.2)\r\n    invoke_custom(00500, 1, \"Camera.setZoomSpeedFactor\", 0.1)\r\n    \r\n    -- \"Qu’est-ce que c’est que cette histoire ?\"\r\n    invoke_custom(06500, 1, \"Sound.playSound\", 320145405618001, true, 50)\r\n    invoke_custom(06500, 1, \"bubble\", meccanox, \"quest.brume.intro.02.01\")\r\n    invoke_custom(10000, 1, \"clearBubbles\", meccanox)\r\n    \r\n    invoke_custom(10500, 1, \"Camera.setCamera\", 1.3, 26, 2, -19)\r\n    \r\n    -- \"C’est maître Meccanox !\"\r\n    invoke_custom(10500, 1, \"Sound.playSound\", 3201114705617002, true, 50)\r\n    invoke_custom(10500, 1, \"bubble\", grouilleuxA, \"quest.brume.intro.02.02\")\r\n    invoke_custom(14500, 1, \"clearBubbles\", grouilleuxA)\r\n    \r\n    -- \"Cachez-vous !\"\r\n    invoke_custom(12500, 1, \"Sound.playSound\", 3201114705617003, true, 50)\r\n    invoke_custom(12500, 1, \"bubble\", julpi, \"quest.brume.intro.02.03\")\r\n    invoke_custom(16500, 1, \"clearBubbles\", julpi)\r\n    \r\n    -- \"Trop tard, il nous a vus…\"\r\n    invoke_custom(14500, 1, \"Sound.playSound\", 3201114705617001, true, 50)\r\n    invoke_custom(14500, 1, \"bubble\", grouilleuxB, \"quest.brume.intro.02.04\")\r\n    invoke_custom(18500, 1, \"clearBubbles\", grouilleuxB)\r\n    \r\n    invoke_custom(19500, 1, \"Camera.setCamera\", 1.3, 23, 0, -19)\r\n    \r\n    -- \"Allons, Julpi… Vous savez bien que je suis comme vous.\"\r\n    invoke_custom(19500, 1, \"Sound.playSound\", 320145405618002, true, 50)\r\n    invoke_custom(19500, 1, \"bubble\", meccanox, \"quest.brume.intro.02.05\")\r\n    invoke_custom(23500, 1, \"clearBubbles\", meccanox)\r\n    \r\n    invoke_custom(24000, 1, \"Camera.setCamera\", 1.6, 23, 0, -19)\r\n    \r\n    -- \"Moi aussi, je suis un serviteur de l’horloger.\"\r\n    invoke_custom(24000, 1, \"Sound.playSound\", 320145405618003, true, 50)\r\n    invoke_custom(24000, 1, \"bubble\", meccanox, \"quest.brume.intro.02.06\")\r\n    invoke_custom(27500, 1, \"clearBubbles\", meccanox)\r\n    \r\n    -- \"Comprenez bien mon point de vue…\"\r\n    invoke_custom(28000, 1, \"Sound.playSound\", 320145405618001, true, 50)\r\n    invoke_custom(28000, 1, \"bubble\", meccanox, \"quest.brume.intro.02.07\")\r\n    invoke_custom(31000, 1, \"clearBubbles\", meccanox)\r\n    \r\n    -- \"Faire la révolution n’améliorera pas notre vie.\"\r\n    invoke_cust