07\")\r\n    invoke_custom(35500, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(35750, 1, \"Camera.attachCameraToMobile\", grouilleuxB)\r\n    \r\n    -- \"Ouais !\"\r\n    invoke_custom(36000, 1, \"Sound.playSound\", 3201114705617002, true, 60)\r\n    invoke_custom(36000, 1, \"bubble\", grouilleuxA, \"quest.brume.qg.cgt.discours.02.08\")\r\n    invoke_custom(36000, 1, \"bubble\", grouilleuxB, \"quest.brume.qg.cgt.discours.02.08\")\r\n    invoke_custom(36000, 1, \"bubble\", grouilleuxC, \"quest.brume.qg.cgt.discours.02.08\")\r\n    invoke_custom(38000, 1, \"clearBubbles\", grouilleuxA)\r\n    invoke_custom(38000, 1, \"clearBubbles\", grouilleuxB)\r\n    invoke_custom(38000, 1, \"clearBubbles\", grouilleuxC)\r\n    \r\n    invoke_custom(38250, 1, \"Camera.attachCameraToMobile\", playerId)\r\n    \r\n    -- \"Avec des ballons.\"\r\n    invoke_custom(38500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Pointer\")\r\n    invoke_custom(38500, 1, \"bubble\", playerId, \"quest.brume.qg.cgt.discours.02.09\")\r\n    invoke_custom(40500, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(40750, 1, \"Camera.attachCameraToMobile\", grouilleuxC)\r\n    \r\n    -- \"Ouais !\"\r\n    invoke_custom(41000, 1, \"Sound.playSound\", 3201114705617001, true, 70)\r\n    invoke_custom(41000, 1, \"bubble\", grouilleuxA, \"quest.brume.qg.cgt.discours.02.10\")\r\n    invoke_custom(41000, 1, \"bubble\", grouilleuxB, \"quest.brume.qg.cgt.discours.02.10\")\r\n    invoke_custom(41000, 1, \"bubble\", grouilleuxC, \"quest.brume.qg.cgt.discours.02.10\")\r\n    invoke_custom(43000, 1, \"clearBubbles\", grouilleuxA)\r\n    invoke_custom(43000, 1, \"clearBubbles\", grouilleuxB)\r\n    invoke_custom(43000, 1, \"clearBubbles\", grouilleuxC)\r\n    \r\n    \r\n    invoke_custom(43500, 1, \"Effect.createFullScreenSprite\", 500, 1000, 500, 0.0, 0.0, 0.0)\r\n    \r\n    invoke_custom(45000, 1, \"customSkip\")\nend\n\n-- Q7 - Fin cinématique Discours -> on tp 1448 (ACH 5337 OBJ 11465)\n-- \nfunction event_2589_23605()\n    \nend\n\n-- Q7 - DIALOG_EXECUTED -> on tp 1449 (ACH 5337 OBJ 11468)\n-- \nfunction event_2589_23609()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","hideMonster","hidePart","showMonster","showPart","event_2589_23111","event_2589_23177","event_2589_23517","event_2589_23112","customSkip","event_2589_23113","event_2589_23566","customSkip","event_2589_23567","event_2589_23580","customSkip","arme","arme","arme","event_2589_23581","customSkip","arme","arme","arme","event_2589_23582","customSkip","arme","arme","arme","event_2589_23605","event_2589_23609"],"quest_calls":[],"dialogue_calls":[]},"scenario/2590.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\n-- les fonctions où on cache\r\nfunction hideMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, false)\r\nend\r\n\r\nfunction hidePart(monsterMobileId, partName)\r\n\tMobile.setPartVisible(monsterMobileId, false, partName)\r\nend\r\n\r\n-- les fonctions où on rend visible (à nouveau)\r\nfunction showMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, true)\r\nend\r\n\r\nfunction showPart(monsterMobileId, partName)\r\n\tMobile.setPartVisible(monsterMobileId, true, partName)\r\nend\n\n-- [INITIALISATION] Serveur\n-- \nfunction event_2590_23123()\n    \nend\n\n-- ENTER_INSTANCE - On inscrit au scénario\n-- \nfunction event_2590_23232()\n    \nend\n\n-- Q4 - ENTER_INSTANCE - Cinématique Arrivée (ACH 5345 OBJ 11180)\n-- \nfunction event_2590_23124(lebbocq, vieuxBinson, viandredi, mauro, chopinette)\n    local playerId = Context.getLeaderId()\r\n    local lebbocq = toLong(lebbocq)\r\n    local vieuxBinson = toLong(vieuxBinson)\r\n    local viandredi = toLong(viandredi)\r\n    local mauro = toLong(mauro)\r\n    local chopinette = toLong(chopinette)\r\n    \r\n    local lebbocqCine = createActor(117903816, -8, -42, 3, 4, 3, 6)\r\n    local vieuxBinsonCine = createActor(1052, -4, -32, 3, 4, 1, 6)\r\n    local mauroCine = createActor(1023, 5, -33, 3, 4, 5, 6)\r\n    local chopinetteCine = createActor(1028, 5, -36, 3, 4, 5, 6)\r\n    \r\n    function customSkip()\r\n    \tMobile.hideOtherPlayerMobile(false)\r\n    \tMobile.setMobileVisible(lebbocq, true)\r\n    \tMobile.setMobileVisible(vieuxBinson, true)\r\n    \tMobile.setMobileVisible(mauro, true)\r\n    \tMobile.setMobileVisible(chopinette, true)\r\n    \tUI.displayWideScreenBand(true, 25, 500)\r\n    \tskipCinematic(23124)\r\n    end\r\n    \r\n    Mobile.hideOtherPlayerMobile(true)\r\n    Mobile.setMobileVisible(lebbocq, false)\r\n    Mobile.setMobileVisible(vieuxBinson, false)\r\n    Mobile.setMobileVisible(mauro, false)\r\n    Mobile.setMobileVisible(chopinette, false)\r\n    \r\n    startCinematicContext(1.6, playerId)\r\n    \r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"customSkip\")\r\n    \r\n    invoke_custom(00001, 1, \"Mobile.setMobileMovementStyle\", playerId, \"WALK\", \"WALK\")\r\n    invoke_custom(00001, 1, \"Mobile.setCustomWalkStyle\", playerId, \"AnimMarche\", 600)\r\n    \r\n    invoke_custom(0050, 1, \"Camera.setMoveSpeedFactor\", 1.0)\r\n    invoke_custom(00500, 1, \"Camera.setZoomSpeedFactor\", 0.05)\r\n    \r\n    invoke_custom(01000, 1, \"Mobile.moveMobile\", playerId, 0, -25, 0)\r\n    \r\n    -- \"Mais qu’est-ce que c’est que cet endroit ?\"\r\n    invoke_custom(02000, 1, \"bubble\", playerId, \"quest.brume.cheptel.01\")\r\n    invoke_custom(05500, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(06000, 1, \"Camera.setMoveSpeedFactor\", 0.2)\r\n    invoke_custom(06000, 1, \"Camera.attachCameraToMobile\", mauroCine)\r\n    invoke_custom(09000, 1, \"Camera.setZoomFactor\", 1.2)\r\n    \r\n    -- \"Ça alors, qui es-tu ?\"\r\n    invoke_custom(06000, 1, \"bubble\", mauroCine, \"quest.brume.cheptel.02\")\r\n    invoke_custom(09000, 1, \"clearBubbles\", mauroCine)\r\n    \r\n    -- \"Un{[1*]?e:} aventuri{[1*]?ère:er} ?\"\r\n    invoke_custom(09500, 1, \"bubble\", chopinetteCine, \"quest.brume.cheptel.03\")\r\n    invoke_custom(12000, 1, \"clearBubbles\", chopinetteCine)\r\n    invoke_custom(12000, 1, \"Mobile.setMobileMovementStyle\", playerId, \"RUN\", \"RUN\")\r\n    \r\n    invoke_custom(12000, 1, \"Mobile.moveMobile\", playerId, 0, -36, 0, \"Mobile.setMobileDirection\", playerId, 1)\r\n    invoke_custom(12000, 1, \"Camera.attachCameraToMobile\", playerId)\r\n    \r\n    -- \"Je le savais, ces Bworks doivent vous retenir captifs !\"\r\n    invoke_custom(12500, 1, \"bubble\", playerId, \"quest.brume.cheptel.04\")\r\n    invoke_custom(16000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Tenez bon, je vais vous libérer…\"\r\n    invoke_custom(16500, 1, \"bubble\", playerId, \"quest.brume.cheptel.05\")\r\n    invoke_custom(16500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Calmer\")\r\n    invoke_custom(20000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"N-non, aventuri{[1*]?ère:er} !\"\r\n    invoke_custom(20500, 1, \"bubble\", vieuxBinsonCine, \"quest.brume.cheptel.06\")\r\n    invoke_custom(20500, 1, \"Mobile.setMobileAnimation\", vieuxBinsonCine, \"AnimEmote-Help\")\r\n    invoke_custom(23000, 1, \"clearBubbles\", vieuxBinsonCine)\r\n    \r\n    -- \"Ce n’est pas la peine de nous libérer.\"\r\n    invoke_custom(23500, 1, \"bubble\", chopinetteCine, \"quest.brume.cheptel.07\")\r\n    invoke_custom(23500, 1, \"Mobile.setMobileAnimation\", chopinetteCine, \"AnimEmote-Non\")\r\n    invoke_custom(26000, 1, \"clearBubbles\", chopinetteCine)\r\n    \r\n    -- \"Comment ça ?\"\r\n    invoke_custom(26500, 1, \"bubble\", playerId, \"quest.brume.cheptel.08\")\r\n    invoke_custom(26500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(29000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"C’est un peu gênant, mais…\"\r\n    invoke_custom(27000, 1, \"bubble\", mauroCine, \"quest.brume.cheptel.09\")\r\n    invoke_custom(27000, 1, \"Mobile.setMobileAnimation\", mauroCine, \"AnimEmoteMarket-Timide2\")\r\n    invoke_custom(30000, 1, \"clearBubbles\", mauroCine)\r\n    \r\n    -- \"Au début, nous étions bien retenus de force.\"\r\n    invoke_custom(30500, 1, \"bubble\", vieuxBinsonCine, \"quest.brume.cheptel.10\")\r\n    invoke_custom(30500, 1, \"Mobile.setMobileAnimation\", vieuxBinsonCine, \"AnimEmote-Presenter\")\r\n    invoke_custom(34000, 1, \"clearBubbles\", vieuxBinsonCine)\r\n    \r\n    -- \"Mais maintenant, nous restons de notre plein gré.\"\r\n    invoke_custom(34500, 1, \"bubble\", chopinetteCine, \"quest.brume.cheptel.11\")\r\n    invoke_custom(34500, 1, \"Mobile.setMobileAnimation\", chopinetteCine, \"AnimEmoteMarket-HausseEpaules\")\r\n    invoke_custom(38000, 1, \"clearBubbles\", chopinetteCine)\r\n    \r\n    -- \"...\"\r\n    invoke_custom(39500, 1, \"bubble\", playerId, \"quest.brume.cheptel.12\")\r\n    invoke_custom(41500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"...\"\r\n    invoke_custom(42500, 1, \"bubble\", mauroCine, \"quest.brume.cheptel.12\")\r\n    invoke_custom(44500, 1, \"clearBubbles\", mauroCine)\r\n    invoke_custom(42500, 1, \"bubble\", vieuxBinsonCine, \"quest.brume.cheptel.12\")\r\n    invoke_custom(44500, 1, \"clearBubbles\", vieuxBinsonCine)\r\n    invoke_custom(42500, 1, \"bubble\", chopinetteCine, \"quest.brume.cheptel.12\")\r\n    invoke_custom(44500, 1, \"clearBubbles\", chopinetteCine)\r\n    \r\n    -- \"Si tu vois ce que je veux dire…\"\r\n    invoke_custom(45000, 1, \"bubble\", chopinetteCine, \"quest.brume.cheptel.13\")\r\n    invoke_custom(47500, 1, \"clearBubbles\", chopinetteCine)\r\n    \r\n    -- \"Ça n’a aucun fichu sens narrativement.\"\r\n    invoke_custom(48000, 1, \"bubble\", playerId, \"quest.brume.cheptel.14\")\r\n    invoke_custom(48000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Colere\")\r\n    invoke_custom(51500, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(51500, 1, \"Camera.attachCameraToMobile\", lebbocqCine)\r\n    \r\n    -- \"**Je connais cette voix…\"\r\n    invoke_custom(52000, 1, \"bubble\", lebbocqCine, \"quest.brume.cheptel.15\")\r\n    invoke_custom(55500, 1, \"clearBubbles\", lebbocqCine)\r\n    \r\n    invoke_custom(55500, 1, \"Mobile.moveMobile\", lebbocqCine, -4, -42, 3)\r\n    \r\n    invoke_custom(57500, 1, \"Mobile.setMobileDirection\", playerId, 7)\r\n    \r\n    -- \"[#name] ? C’est toi ?\"\r\n    invoke_custom(56000, 1, \"bubble\", lebbocqCine, \"quest.brume.cheptel.16\")\r\n    invoke_custom(59000, 1, \"clearBubbles\", lebbocqCine)\r\n    \r\n    -- \"Lebbocq ?!\"\r\n    invoke_custom(59500, 1, \"bubble\", playerId, \"quest.brume.cheptel.17\")\r\n    invoke_custom(59500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Help\")\r\n    invoke_custom(62000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(62000, 1, \"Mobile.moveMobile\", playerId, 0, -42, 0, \"Mobile.setMobileDirection\", playerId, 5)\r\n    \r\n    -- \"Les Douze soient loués !\"\r\n    invoke_custom(62500, 1, \"bubble\", lebbocqCine, \"quest.brume.cheptel.18\")\r\n    invoke_custom(65000, 1, \"clearBubbles\", lebbocqCine)\r\n    \r\n    -- \"Je ne m’attendais pas à te trouver ici…\"\r\n    invoke_custom(65500, 1, \"bubble\", lebbocqCine, \"quest.brume.cheptel.19\")\r\n    invoke_custom(68000, 1, \"clearBubbles\", lebbocqCine)\r\n    \r\n    invoke_custom(68500, 1, \"customSkip\")\nend\n\n-- Q4 - Fin cinématique Arrivée (ACH 5345 OBJ 11180)\n-- \nfunction event_2590_23125()\n    \nend\n\n-- Q4 - ENTER_INSTANCE - On cache les Machines de Nox\n-- \nfunction event_2590_23126(noxMachineA, noxMachineB, noxMachineC, noxMachineD)\n    Mobile.addMobileCreationCallback(noxMachineA, \"hideMonster\", noxMachineA)\r\n    Mobile.addMobileCreationCallback(noxMachineB, \"hideMonster\", noxMachineB)\r\n    Mobile.addMobileCreationCallback(noxMachineC, \"hideMonster\", noxMachineC)\r\n    Mobile.addMobileCreationCallback(noxMachineD, \"hideMonster\", noxMachineD)\nend\n\n-- Q4 - ENTER_INSTANCE - On cache les Savanastraux\n-- \nfunction event_2590_23127(savaneA, savaneB, savaneC, savaneD)\n    Mobile.addMobileCreationCallback(savaneA, \"hideMonster\", savaneA)\r\n    Mobile.addMobileCreationCallback(savaneB, \"hideMonster\", savaneB)\r\n    Mobile.addMobileCreationCallback(savaneC, \"hideMonster\", savaneC)\r\n    Mobile.addMobileCreationCallback(savaneD, \"hideMonster\", savaneD)\nend\n\n-- Q4 - ENTER_INSTANCE - On cache Lebbocq\n-- \nfunction event_2590_23320(lebbocq)\n    Mobile.addMobileCreationCallback(lebbocq, \"hideMonster\", lebbocq)\nend\n\n-- Q4 - ENTER_INSTANCE - On affiche les Machines de Nox\n-- \nfunction event_2590_23128(noxMachineA, noxMachineB, noxMachineC, noxMachineD)\n    Mobile.addMobileCreationCallback(noxMachineA, \"showMonster\", noxMachineA)\r\n    Mobile.addMobileCreationCallback(noxMachineB, \"showMonster\", noxMachineB)\r\n    Mobile.addMobileCreationCallback(noxMachineC, \"showMonster\", noxMachineC)\r\n    Mobile.addMobileCreationCallback(noxMachineD, \"showMonster\", noxMachineD)\nend\n\n-- Q4 - DIALOG_EXECUTED - On affiche les Savanastraux\n-- \nfunction event_2590_23129(savaneA, savaneB, savaneC, savaneD)\n    Mobile.addMobileCreationCallback(savaneA, \"showMonster\", savaneA)\r\n    Mobile.addMobileCreationCallback(savaneB, \"showMonster\", savaneB)\r\n    Mobile.addMobileCreationCallback(savaneC, \"showMonster\", savaneC)\r\n    Mobile.addMobileCreationCallback(savaneD, \"showMonster\", savaneD)\nend\n\n-- ENTER_INSTANCE - On cache Arlémia\n-- \nfunction event_2590_23618(arlemia)\n    Mobile.addMobileCreationCallback(arlemia, \"hideMonster\", arlemia)\nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","hideMonster","hidePart","showMonster","showPart","event_2590_23123","event_2590_23232","event_2590_23124","customSkip","event_2590_23125","event_2590_23126","event_2590_23127","event_2590_23320","event_2590_23128","event_2590_23129","event_2590_23618"],"quest_calls":[],"dialogue_calls":[]},"scenario/2591.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\n\n-- [INIT] Variables Globales\n-- \nfunction event_2591_23130()\n    \nend\n\n-- [INIT] Inscription du joueur + Variables Locales\n-- \nfunction event_2591_23131(room)\n    \nend\n\n-- DIALOG_EXECUTED - On rend le combat disponible\n-- \nfunction event_2591_23132()\n    \nend\n\n-- [FIGHT] Lancement du combat - Action sur Nox\n-- on skippe la cinématique pour tout le monde \nfunction event_2591_23180()\n    skipCinematic()\nend\n\n-- FIGHT_ENTER_ACTION_PHASE - On pose les zones nécessaires au combat\n-- \nfunction event_2591_23163()\n    \nend\n\n-- [STELE] FIGHT_STARTED - On applique les difficultés sur le boss\n-- \nfunction event_2591_23134()\n    \nend\n\n-- [STELE] FIGHT_ENTER_ACTION_PHASE - On applique les bonus sur les joueurs\n-- \nfunction event_2591_23135()\n    \nend\n\n-- [STELE] FIGHT_ENDED - On rend la stèle utilisable en cas de défaite\n-- \nfunction event_2591_23136()\n    \nend\n\n-- [COMBAT] Achievement 5432 - Acte II au 3ème tour\n-- \nfunction event_2591_23323()\n    \nend\n\n-- [COMBAT] Achievement 5432 - Validation\n-- \nfunction event_2591_23324()\n    \nend\n\n-- [COMBAT] Achievement 5433 - Dommages subis dans l'acte II\n-- \nfunction event_2591_23325()\n    \nend\n\n-- [COMBAT] Achievement 5433 - Validation\n-- \nfunction event_2591_23326()\n    \nend\n\n-- [COMBAT] Achievement 5434 - État Disparue dans l'acte III\n-- \nfunction event_2591_23327()\n    \nend\n\n-- [COMBAT] Achievement 5434 - Validation\n-- \nfunction event_2591_23328()\n    \nend\n\n-- [TEST] Lancement du combat - Scène finale\n-- \nfunction event_2591_23332()\n    skipCinematic()\nend\n\n-- USER_GROUP_KILLED - Salle 01 - BOSS\n-- \nfunction event_2591_23333()\n    \nend\n\n-- [EVENT] Mort de Nox\n-- EFFECT_EXECUTION car USER_GROUP_KILLED ne fonctionne pas bien avec le fightModel\nfunction event_2591_23371()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_2591_23130","event_2591_23131","event_2591_23132","event_2591_23180","event_2591_23163","event_2591_23134","event_2591_23135","event_2591_23136","event_2591_23323","event_2591_23324","event_2591_23325","event_2591_23326","event_2591_23327","event_2591_23328","event_2591_23332","event_2591_23333","event_2591_23371"],"quest_calls":[],"dialogue_calls":[]},"scenario/2592.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\napsId = 7290013\r\n\r\n-- les fonctions où on cache\r\nfunction hideMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, false)\r\nend\r\n\r\nfunction hidePart(monsterMobileId, partName)\r\n\tMobile.setPartVisible(monsterMobileId, false, partName)\r\nend\r\n\r\n-- les fonctions où on rend visible (à nouveau)\r\nfunction showMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, true)\r\nend\r\n\r\nfunction showPart(monsterMobileId, partName)\r\n\tMobile.setPartVisible(monsterMobileId, true, partName)\r\nend\r\n\r\n-- Fonction pour update les générateurs\r\nfunction updateGenerateurs(genA, genB, genC, genD, genE)\r\n\r\nif (genA == 1) then\r\n\tWorld.setPictoAlpha(104, -97, 9, 1, 1000)\r\n\tParticle.addParticleSystem(apsId, 104, -97, 3)\r\nelse\r\n\tWorld.setPictoAlpha(104, -97, 9, 0, 1000)\r\nend\r\n\r\nif (genB == 1) then\r\n\tWorld.setPictoAlpha(-8, 0, 9, 1, 1000)\r\n\tParticle.addParticleSystem(apsId, -8, 0, 3)\r\nelse\r\n\tWorld.setPictoAlpha(-8, 0, 9, 0, 1000)\r\nend\r\n\r\nif (genC == 1) then\r\n\tWorld.setPictoAlpha(228, -8, 9, 1, 1000)\r\n\tParticle.addParticleSystem(apsId, 228, -8, 3)\r\nelse\r\n\tWorld.setPictoAlpha(228, -8, 9, 0, 1000)\r\nend\r\n\r\nif (genD == 1) then\r\n\tWorld.setPictoAlpha(100, 90, 9, 1, 1000)\r\n\tParticle.addParticleSystem(apsId, 100, 90, 3)\r\nelse\r\n\tWorld.setPictoAlpha(100, 90, 9, 0, 1000)\r\nend\r\n\r\nif (genE == 1) then\r\n\tWorld.setPictoAlpha(251, 214, 9, 1, 1000)\r\n\tParticle.addParticleSystem(apsId, 251, 214, 9)\r\nelse\r\n\tWorld.setPictoAlpha(251, 214, 9, 0, 1000)\r\nend\r\n\r\nend\n\n-- [INITIALISATION] Serveur\n-- \nfunction event_2592_23137()\n    \nend\n\n-- ENTER_INSTANCE - On affiche/cache les générateurs\n-- \nfunction event_2592_23138(generateurA, generateurB, generateurC, generateurD, generateurE)\n    local genA = toLong(generateurA)\r\n    local genB = toLong(generateurB)\r\n    local genC = toLong(generateurC)\r\n    local genD = toLong(generateurD)\r\n    local genE = toLong(generateurE)\r\n    \r\n    updateGenerateurs(genA, genB, genC, genD, genE)\r\n    \r\n    trace(\"genA\", genA, \"genB\", genB, \"genC\", genC, \"genD\", genD, \"genE\", genE)\nend\n\n-- GENERIC_ACTIVABLE_ACTION - Générateur Forêt - ACH 5333 OBJ 11203\n-- \nfunction event_2592_23139(generateurA, generateurB, generateurC, generateurD, generateurE)\n    local genA = toLong(generateurA)\r\n    local genB = toLong(generateurB)\r\n    local genC = toLong(generateurC)\r\n    local genD = toLong(generateurD)\r\n    local genE = toLong(generateurE)\r\n    \r\n    updateGenerateurs(genA, genB, genC, genD, genE)\r\n    \r\n    -- \"Parfait ! L'orbe de Wakfu correspond. On dirait que ce dispositif s'est activé...\"\r\n    bubble(playerId, \"quest.brume.generateur.interaction.4\")\r\n        \r\n    trace(\"genA\", genA, \"genB\", genB, \"genC\", genC, \"genD\", genD, \"genE\", genE)\nend\n\n-- GENERIC_ACTIVABLE_ACTION - Générateur Canyon - ACH 5333 OBJ 11204\n-- \nfunction event_2592_23141(generateurA, generateurB, generateurC, generateurD, generateurE)\n    local genA = toLong(generateurA)\r\n    local genB = toLong(generateurB)\r\n    local genC = toLong(generateurC)\r\n    local genD = toLong(generateurD)\r\n    local genE = toLong(generateurE)\r\n    \r\n    updateGenerateurs(genA, genB, genC, genD, genE)\r\n    \r\n    -- \"Parfait ! L'orbe de Wakfu correspond. On dirait que ce dispositif s'est activé...\"\r\n    bubble(playerId, \"quest.brume.generateur.interaction.4\")\r\n        \r\n    trace(\"genA\", genA, \"genB\", genB, \"genC\", genC, \"genD\", genD, \"genE\", genE)\nend\n\n-- GENERIC_ACTIVABLE_ACTION - Générateur Savane - ACH 5333 OBJ 11205\n-- \nfunction event_2592_23142(generateurA, generateurB, generateurC, generateurD, generateurE)\n    local genA = toLong(generateurA)\r\n    local genB = toLong(generateurB)\r\n    local genC = toLong(generateurC)\r\n    local genD = toLong(generateurD)\r\n    local genE = toLong(generateurE)\r\n    \r\n    updateGenerateurs(genA, genB, genC, genD, genE)\r\n    \r\n    -- \"Parfait ! L'orbe de Wakfu correspond. On dirait que ce dispositif s'est activé...\"\r\n    bubble(playerId, \"quest.brume.generateur.interaction.4\")\r\n        \r\n    trace(\"genA\", genA, \"genB\", genB, \"genC\", genC, \"genD\", genD, \"genE\", genE)\nend\n\n-- GENERIC_ACTIVABLE_ACTION - Générateur Marais - ACH 5333 OBJ 11206\n-- \nfunction event_2592_23143(generateurA, generateurB, generateurC, generateurD, generateurE)\n    local genA = toLong(generateurA)\r\n    local genB = toLong(generateurB)\r\n    local genC = toLong(generateurC)\r\n    local genD = toLong(generateurD)\r\n    local genE = toLong(generateurE)\r\n    \r\n    updateGenerateurs(genA, genB, genC, genD, genE)\r\n    \r\n    -- \"Parfait ! L'orbe de Wakfu correspond. On dirait que ce dispositif s'est activé...\"\r\n    bubble(playerId, \"quest.brume.generateur.interaction.4\")\r\n        \r\n    trace(\"genA\", genA, \"genB\", genB, \"genC\", genC, \"genD\", genD, \"genE\", genE)\nend\n\n-- GENERIC_ACTIVABLE_ACTION - Générateur Désolation - ACH 5333 OBJ 11207\n-- \nfunction event_2592_23144(generateurA, generateurB, generateurC, generateurD, generateurE)\n    local genA = toLong(generateurA)\r\n    local genB = toLong(generateurB)\r\n    local genC = toLong(generateurC)\r\n    local genD = toLong(generateurD)\r\n    local genE = toLong(generateurE)\r\n    \r\n    updateGenerateurs(genA, genB, genC, genD, genE)\r\n    \r\n    -- \"Parfait ! L'orbe de Wakfu correspond. On dirait que ce dispositif s'est activé...\"\r\n    bubble(playerId, \"quest.brume.generateur.interaction.4\")\r\n        \r\n    trace(\"genA\", genA, \"genB\", genB, \"genC\", genC, \"genD\", genD, \"genE\", genE)\nend\n\n-- ENTER_INSTANCE - Cinématique Amélia\n-- \nfunction event_2592_23202(amelia)\n    local playerId = Context.getLeaderId()\r\n    \r\n    function customSkip()\r\n    \tMobile.hideOtherPlayerMobile(false)\r\n    \tskipCinematic(23202)\r\n    end\r\n    \r\n    fullScreen(0, 8000, 1000)\r\n    Mobile.setMobileVisible(playerId, false)\r\n    \r\n    startCinematicContext(1.5, playerId)\r\n    \r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"customSkip\")\r\n    \r\n    -- \"Lorsque vous approchez du site de fouille, trois machines surgissent et vous poussent au fond de l'abîme. Vous chutez longuement, pensant votre dernière heure venue.\"\r\n    invoke_custom(01000, 1, \"text\", 500, 7000, 500, \"quest.brume.cine.desolation.01\")\r\n    \r\n    invoke_custom(10000, 1, \"Mobile.setMobileVisible\", playerId, true)\r\n    invoke_custom(10000, 1, \"Mobile.setMobileDirection\", playerId, 1)\r\n    invoke_custom(10000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimIncarnam-Chute-Fin\")\r\n    \r\n    invoke_custom(13000, 1, \"customSkip\")\nend\n\n-- Fin de la cinématique - Validation ACH 5347 OBJ 11287\n-- \nfunction event_2592_23237()\n    \nend\n\n-- INTERACTIVE_ELEMENT_ACTION - Cinématique sortie\n-- \nfunction event_2592_23238(amelia)\n    local playerId = Context.getLeaderId()\r\n    local amelia = toLong(amelia)\r\n    local ameliaCine = createActor(117903817, 293, 232, 0, 4, 7, 6)\r\n    \r\n    function customSkip()\r\n    \tMobile.hideOtherPlayerMobile(false)\r\n    \tMobile.setMobileVisible(amelia, false)\r\n    \tskipCinematic(23238)\r\n    end\r\n    \r\n    Mobile.setMobileVisible(amelia, false)\r\n    \r\n    startCinematicContext(1.5, playerId)\r\n    \r\n    InteractiveElement.setAnimation(35075, \"AnimTrans_1\")\r\n    InteractiveElement.setAnimation(35074, \"AnimTrans_1\")\r\n    \r\n    Sound.playSound(70700111, true)\r\n    \r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"customSkip\")\r\n    \r\n    -- \"Maintenant !\"\r\n    invoke_custom(01000, 1, \"bubble\", ameliaCine, \"quest.brume.cine.desolation.02\")\r\n    invoke_custom(01000, 1, \"Mobile.moveMobile\", playerId, 282, 241, 0, \"Mobile.setMobileDirection\", playerId, 1)\r\n    invoke_custom(01000, 1, \"Mobile.moveMobile\", ameliaCine, 282, 239, 0, \"Mobile.setMobileDirection\", ameliaCine, 1)\r\n    \r\n    invoke_custom(06000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Victoire\")\r\n    invoke_custom(07000, 1, \"Mobile.setMobileAnimation\", ameliaCine, \"AnimComp-Win\")\r\n    invoke_custom(09000, 1, \"Mobile.setMobileAnimation\", ameliaCine, \"AnimBonnechose\")\r\n    \r\n    -- \"Chic, nous voilà sortis.\"\r\n    invoke_custom(06000, 1, \"bubble\", playerId, \"quest.brume.cine.desolation.03\")\r\n    invoke_custom(09000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(09250, 1, \"Mobile.setMobileDirection\", playerId, 7)\r\n    \r\n    -- \"Bon, et maintenant, où allons-nous ?\"\r\n    invoke_custom(09500, 1, \"bubble\", playerId, \"quest.brume.cine.desolation.04\")\r\n    invoke_custom(09500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Presenter\")\r\n    invoke_custom(12000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(12250, 1, \"Mobile.setMobileDirection\", playerId, 5)\r\n    \r\n    -- \"On dirait qu’on pourrait nager...\"\r\n    invoke_custom(12500, 1, \"bubble\", playerId, \"quest.brume.cine.desolation.05\")\r\n    invoke_custom(12500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(15000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(15250, 1, \"Mobile.setMobileDirection\", ameliaCine, 3)\r\n    \r\n    -- \"Non, pas par-là !\"\r\n    invoke_custom(15500, 1, \"bubble\", ameliaCine, \"quest.brume.cine.desolation.06\")\r\n    invoke_custom(18000, 1, \"clearBubbles\", ameliaCine)\r\n    \r\n    invoke_custom(17000, 1, \"Mobile.setMobileDirection\", playerId, 7)\r\n    \r\n    -- \"... Je n’aime pas trop devoir me mouiller si ce n’est pas nécessaire.\"\r\n    invoke_custom(18500, 1, \"bubble\", ameliaCine, \"quest.brume.cine.desolation.07\")\r\n    invoke_custom(22000, 1, \"clearBubbles\", ameliaCine)\r\n    \r\n    -- \"J’avais oublié que tu étais Ouginak.\"\r\n    invoke_custom(22500, 1, \"bubble\", playerId, \"quest.brume.cine.desolation.08\")\r\n    invoke_custom(22500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Rire\")\r\n    invoke_custom(25000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(26000, 1, \"Mobile.setMobileDirection\", playerId, 1)\r\n    invoke_custom(25000, 1, \"Mobile.moveMobile\", ameliaCine, 284, 243, 0, \"Mobile.setMobileDirection\", ameliaCine, 5)\r\n    \r\n    -- \"Je vais plutôt par ici. Je sens l’air libre.\"\r\n    invoke_custom(25500, 1, \"bubble\", ameliaCine, \"quest.brume.cine.desolation.09\")\r\n    invoke_custom(28000, 1, \"clearBubbles\", ameliaCine)\r\n    \r\n    -- \"Je te retrouverai plus tard, j’ai un truc à faire.\"\r\n    invoke_custom(28500, 1, \"bubble\", ameliaCine, \"quest.brume.cine.desolation.10\")\r\n    invoke_custom(30000, 1, \"Mobile.setMobileDirection\", ameliaCine, 1)\r\n    invoke_custom(30000, 1, \"Mobile.setMobileAnimation\", ameliaCine, \"AnimBonnechose\")\r\n    invoke_custom(32000, 1, \"clearBubbles\", ameliaCine)\r\n    \r\n    invoke_custom(32000, 1, \"Mobile.moveMobile\", ameliaCine, 300, 255, 0)\r\n    \r\n    -- \"Attends !\"\r\n    invoke_custom(32500, 1, \"bubble\", playerId, \"quest.brume.cine.desolation.11\")\r\n    invoke_custom(32500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Help\")\r\n    invoke_custom(35000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Et... Elle est partie.\"\r\n    invoke_custom(35500, 1, \"bubble\", playerId, \"quest.brume.cine.desolation.12\")\r\n    invoke_custom(35500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(38000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(38500, 1, \"customSkip\")\nend\n\n-- CLIENT_TRIGGERED_EVENT - Fin de la cinématique - Validation ACH 5348 OBJ 11290\n-- \nfunction event_2592_23239()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","hideMonster","hidePart","showMonster","showPart","updateGenerateurs","event_2592_23137","event_2592_23138","event_2592_23139","event_2592_23141","event_2592_23142","event_2592_23143","event_2592_23144","event_2592_23202","customSkip","event_2592_23237","event_2592_23238","customSkip","event_2592_23239"],"quest_calls":[],"dialogue_calls":[]},"scenario/2593.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\n\n-- [INITIALISATION] Serveur\n-- \nfunction event_2593_23145()\n    \nend\n\n-- ENTER_INSTANCE - On inscrit au scénario\n-- \nfunction event_2593_23146()\n    \nend\n\n-- INTERACTIVE_ELEMENT_ACTION - On interagit avec l'ascenseur\n-- \nfunction event_2593_23147()\n    Sound.playSound(70700081, true, 60)\nend\n\n-- INTERACTIVE_ELEMENT_ACTION - Quête Dofus ébène - début précipice\n-- \nfunction event_2593_23613()\n    fullScreen(1000, 999999999, 1000)\r\n    \r\n    invoke(2000, 1, \"Server.triggerEvent\", 23613)\nend\n\n-- CLIENT_TRIGGERED_EVENT - Quête Dofus ébène - début précipice\n-- \nfunction event_2593_23614()\n    \nend\n\n-- DIALOG_CANCELED - Quête Dofus ébène - On retire le fullscreen\n-- \nfunction event_2593_23615()\n    Effect.stopEffect(fullScreenId)\r\n    fullScreen(0, 0, 1000)\nend\n\n-- DIALOG_EXECUTED - Quête Dofus ébène - On retire le fullscreen et on valide l'achievement 5553\n-- \nfunction event_2593_23616()\n    Effect.stopEffect(fullScreenId)\r\n    fullScreen(0, 0, 1000)\nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_2593_23145","event_2593_23146","event_2593_23147","event_2593_23613","event_2593_23614","event_2593_23615","event_2593_23616"],"quest_calls":[],"dialogue_calls":[]},"scenario/2594.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\n-- les fonctions où on cache\r\nfunction hideMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, false)\r\nend\r\n\r\nfunction hidePart(monsterMobileId, partName)\r\n\tMobile.setPartVisible(monsterMobileId, false, partName)\r\nend\r\n\r\n-- les fonctions où on rend visible (à nouveau)\r\nfunction showMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, true)\r\nend\r\n\r\nfunction showPart(monsterMobileId, partName)\r\n\tMobile.setPartVisible(monsterMobileId, true, partName)\r\nend\n\n-- [INITIALISATION] Serveur\n-- \nfunction event_2594_23149()\n    \nend\n\n-- Q3 - ENTER_INSTANCE - On cache Jenry, Timö et Brossar\n-- \nfunction event_2594_23150(jenry, timo, brossar, stepA, stepB)\n    local stepA = toLong(stepA)\r\n    local stepB = toLong(stepB)\r\n    \r\n    if (stepA == 1) then\r\n    \tMobile.setMobileVisible(jenry, true)\r\n    \tMobile.setMobileVisible(brossar, true)\r\n    else\r\n    \tMobile.setMobileVisible(jenry, false)\r\n    \tMobile.setMobileVisible(brossar, false)\r\n    end\r\n    \r\n    if (stepB == 1) then\r\n    \tMobile.setMobileVisible(timo, true)\r\n    else\r\n    \tMobile.setMobileVisible(timo, false)\r\n    end\nend\n\n-- Q3 - DIALOG_EXECUTED - Dessin Timö\n-- \nfunction event_2594_23223()\n    UI.displayBackground(437)\nend\n\n-- Q6 - ENTER_INSTANCE - Cinématique libération Timö\n-- \nfunction event_2594_23151()\n    local playerId = Context.getLeaderId()\r\n    local timoId = createActor(1114205638, 88, 76, -16, 4, 1, 6)\r\n    \r\n    Mobile.setMobileDirection(playerId, 5)\r\n    \r\n    function customSkip()\r\n    \tMobile.hideOtherPlayerMobile(false)\r\n    \tskipCinematic(23151)\r\n    end\r\n    \r\n    Mobile.hideOtherPlayerMobile(true)\r\n    fullScreen(1000, 13000, 1000)\r\n    text(1000, 7000, 1000, \"quest.brume.ebene.01.intro.01\")\r\n    \r\n    startCinematicContext(1.0, timoId)\r\n    \r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"customSkip\")\r\n    \r\n    invoke_custom(09000, 1, \"text\", 1000, 4000, 1000, \"quest.brume.ebene.01.intro.02\")\r\n    invoke_custom(15000, 1, \"Camera.setZoomSpeedFactor\", 0.02)\r\n    invoke_custom(15000, 1, \"Camera.setZoomFactor\", 1.6)\r\n    \r\n    -- \"Ces combats ne nous mèneront nulle part !\"\r\n    invoke_custom(15000, 1, \"bubble\", playerId, \"quest.brume.ebene.01.01\")\r\n    invoke_custom(15000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Calme\")\r\n    invoke_custom(18500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Aussi, je vais aller à l’essentiel : Crocodaille, j’ai besoin de ton aide.\"\r\n    invoke_custom(19000, 1, \"bubble\", playerId, \"quest.brume.ebene.01.02\")\r\n    invoke_custom(19000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Presenter\")\r\n    invoke_custom(23500, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(23500, 1, \"Camera.attachCameraToMobile\", timoId)\r\n    \r\n    -- \"Tiens donc. Et qu’est-ce que j’y gagnerai ?\"\r\n    invoke_custom(24000, 1, \"bubble\", timoId, \"quest.brume.ebene.01.03\")\r\n    invoke_custom(27000, 1, \"clearBubbles\", timoId)\r\n    \r\n    -- \"Je t’accorderai ce que je suis l{[1*]?a:e} seul{[1*]?e:} à pouvoir t’offrir : la liberté.\"\r\n    invoke_custom(27500, 1, \"bubble\", playerId, \"quest.brume.ebene.01.04\")\r\n    invoke_custom(27500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Acquiescer\")\r\n    invoke_custom(31000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Hé hé… Tu es direct{[1*]?e:}, j’aime ça ! Très bien je t'écoute. \"\r\n    invoke_custom(31500, 1, \"bubble\", timoId, \"quest.brume.ebene.01.05\")\r\n    invoke_custom(34500, 1, \"clearBubbles\", timoId)\r\n    \r\n    -- \"J’ai besoin d’accéder à un temple Crocodaille dans les hauteurs. Ça te parle ?\"\r\n    invoke_custom(35000, 1, \"bubble\", playerId, \"quest.brume.ebene.01.06\")\r\n    invoke_custom(35000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(38500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"… Évidemment. Il s’agissait de notre lieu de culte pour en appeler à nos dieux.\"\r\n    invoke_custom(39000, 1, \"bubble\", timoId, \"quest.brume.ebene.01.07\")\r\n    invoke_custom(43000, 1, \"clearBubbles\", timoId)\r\n    \r\n    -- \"Des runes semblent en condamner l’accès… J’imagine que tu en es le responsable ?\"\r\n    invoke_custom(43500, 1, \"bubble\", playerId, \"quest.brume.ebene.01.08\")\r\n    invoke_custom(43500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmoteMarket-HausseEpaules\")\r\n    invoke_custom(47500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"En effet. Ceux qui n’ont pas d’écailles ne sont pas les bienvenus en ce lieu sacré.\"\r\n    invoke_custom(48000, 1, \"bubble\", timoId, \"quest.brume.ebene.01.09\")\r\n    invoke_custom(52000, 1, \"clearBubbles\", timoId)\r\n    \r\n    -- \"Tu étais une sorte de sorcier de ton vivant ?\"\r\n    invoke_custom(52500, 1, \"bubble\", playerId, \"quest.brume.ebene.01.10\")\r\n    invoke_custom(52500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Presenter\")\r\n    invoke_custom(55000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Les Crocodailles ont toujours eu une affinité avec la magie du sang et des sacrifices. On peut dire que j’avais… un don pour cela.\"\r\n    invoke_custom(55000, 1, \"bubble\", timoId, \"quest.brume.ebene.01.11\")\r\n    invoke_custom(60500, 1, \"clearBubbles\", timoId)\r\n    \r\n    -- \"Charmant. Et donc ? Tu comptes m’aider ?\"\r\n    invoke_custom(61000, 1, \"bubble\", playerId, \"quest.brume.ebene.01.12\")\r\n    invoke_custom(61000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Presenter\")\r\n    invoke_custom(63500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Si tu t’acquitte de ta part du marché, alors peut-être.\"\r\n    invoke_custom(64000, 1, \"bubble\", timoId, \"quest.brume.ebene.01.13\")\r\n    invoke_custom(66500, 1, \"clearBubbles\", timoId)\r\n    \r\n    -- \"Il y a là-bas quelque chose que je convoite. Un… souvenir de notre roi que je souhaite préserver.\"\r\n    invoke_custom(67000, 1, \"bubble\", timoId, \"quest.brume.ebene.01.14\")\r\n    invoke_custom(71500, 1, \"clearBubbles\", timoId)\r\n    \r\n    -- \"J’ai l’impression de passer un pacte avec le diable… mais je n’ai guère le choix.\"\r\n    invoke_custom(72000, 1, \"bubble\", playerId, \"quest.brume.ebene.01.15\")\r\n    invoke_custom(72000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(76000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Très bien, je vais te libérer. Mais je te garde à l'œil, alors ne tente rien d’idiot !\"\r\n    invoke_custom(76500, 1, \"bubble\", playerId, \"quest.brume.ebene.01.16\")\r\n    invoke_custom(76500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Acquiescer\")\r\n    invoke_custom(78500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Pointer\")\r\n    invoke_custom(80500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Moi ? Je serai sage comme une image ! Hé hé…\"\r\n    invoke_custom(81000, 1, \"bubble\", timoId, \"quest.brume.ebene.01.17\")\r\n    invoke_custom(83000, 1, \"clearBubbles\", timoId)\r\n    \r\n    invoke_custom(83000, 1, \"fullScreen\", 1000, 22000, 1000)\r\n    \r\n    -- \"Vous assumez la lourde responsabilité de libérer le Zurikat possédé de sa prison.\"\r\n    invoke_custom(83000, 1, \"text\", 1000, 5000, 1000, \"quest.brume.ebene.01.18\")\r\n    \r\n    -- \"Craignant le pire, vous ne le lâchez des yeux à aucun instant.\"\r\n    -- \"Vous vous mettez en route pour le temple.\"\r\n    invoke_custom(90000, 1, \"text\", 1000, 5000, 1000, \"quest.brume.ebene.01.19\")\r\n    \r\n    -- \"Quels secrets peuvent bien renfermer ce temple ?\r\n    -- \"Un doute vous assaille...\"\r\n    -- \"Vous préparez un plan de secours au cas où les choses tourneraient mal.\"\r\n    invoke_custom(97000, 1, \"text\", 1000, 6000, 1000, \"quest.brume.ebene.01.20\")\r\n    \r\n    invoke_custom(103000, 1, \"customSkip\")\r\nend\n\n-- Q6 - Fin de la cinématique - On valide l'achievement et on TP out\n-- \nfunction event_2594_23152()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","hideMonster","hidePart","showMonster","showPart","event_2594_23149","event_2594_23150","event_2594_23223","event_2594_23151","customSkip","event_2594_23152"],"quest_calls":[],"dialogue_calls":[]},"scenario/2595.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\nfunction hideGrouilleux(gA, gB)\r\n    Mobile.hideMobile(toLong(gA), true)\r\n    Mobile.hideMobile(toLong(gB), true)\r\nend\r\n\r\nfunction showGrouilleux(gA, gB)\r\n    Mobile.hideMobile(toLong(gA), false)\r\n    Mobile.hideMobile(toLong(gB), false)\r\nend\r\n\r\nfunction setBlueEggVisible(isVisible)\r\n    World.setPictoAlpha(1, -11, 2, isVisible and 1 or 0, 1)\r\n    World.setPictoAlpha(1, -11, 5, isVisible and 1 or 0, 1)\r\nend\r\n\r\nfunction setBlackEggVisible(isVisible)\r\n    World.setPictoAlpha(-1, -11, 2, isVisible and 1 or 0, 1)\r\n    World.setPictoAlpha(-1, -11, 3, isVisible and 1 or 0, 1)\r\nend\r\n\r\nfunction hideEggs()\r\n    setBlueEggVisible(false)\r\n    setBlackEggVisible(false)\r\nend\r\n\r\nfunction showEggs()\r\n    setBlueEggVisible(true)\r\n    setBlackEggVisible(true)\r\nend\n\n-- [INITIALISATION] Serveur\n-- \nfunction event_2595_23154()\n    \nend\n\n-- [ENTER_INSTANCE] Inscription\n-- \nfunction event_2595_23155(gA, gB, blackEggShown, blueEggShown, grouilleuxShown, grouilleuxOneShown)\n    if (toLong(grouilleuxShown) == 0) then\r\n        hideGrouilleux(gA, gB)\r\n    end\r\n    \r\n    if (toLong(grouilleuxOneShown) == 0) then\r\n        Mobile.hideMobile(toLong(gA), true)\r\n    end\r\n    \r\n    if (toLong(blackEggShown) == 0) then\r\n        setBlackEggVisible(false)\r\n    end\r\n    \r\n    if (toLong(blueEggShown) == 0) then\r\n        setBlueEggVisible(false)\r\n    end\nend\n\n-- [ENTER_INSTANCE] Cinématique ACH 5339 OBJ 11296\n-- \nfunction event_2595_23161(gA, gB)\n    hideGrouilleux(gA, gB)\r\n    \r\n    local playerId = Context.getLeaderId()\r\n    local petokask = createActor(145405619, -1, 0, 0, 4, 7, 6)\r\n    local grouilleuxOne = createActor(118300946, -1, -10, 0, 4, 1, 6)\r\n    local grouilleuxTwo = createActor(118300946, 1, -10, 0, 4, 5, 6)\r\n    \r\n    function customSkip()\r\n        showGrouilleux(gA, gB)\r\n        Mobile.setCustomWalkStyle(playerId, \"AnimCourse\", 600)\r\n        Mobile.setMobileMovementStyle(playerId, \"RUN\", \"RUN\")\r\n        Mobile.hideOtherPlayerMobile(false)\r\n        skipCinematic(23161)\r\n    end\r\n    \r\n    Mobile.hideOtherPlayerMobile(true)\r\n    \r\n    startCinematicContext(1.6, playerId)\r\n    \r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"customSkip\")\r\n    \r\n    invoke_custom(00001, 1, \"Camera.setCamera\", 1.3, 0, -10, 0)\r\n    invoke_custom(00001, 1, \"Mobile.setMobileMovementStyle\", playerId, \"WALK\", \"WALK\")\r\n    invoke_custom(00001, 1, \"Mobile.setCustomWalkStyle\", playerId, \"AnimMarche\", 600)\r\n    \r\n    invoke_custom(00500, 1, \"Camera.setMoveSpeedFactor\", 0.2)\r\n    invoke_custom(00500, 1, \"Camera.setZoomSpeedFactor\", 0.2)\r\n    \r\n    --T’es vraiment nul, ma parole.\r\n    invoke_custom(002000, 1, \"Sound.playSound\", 320118300946001, true, 25)\r\n    invoke_custom(002000, 1, \"bubble\", grouilleuxOne, \"quest.brume.foret.00.00\")\r\n    invoke_custom(004500, 1, \"clearBubbles\", grouilleuxOne)\r\n    \r\n    --J’suis p’tet nul, mais moi j’ai le meilleur œuf de combat de toute l’île.\r\n    invoke_custom(005000, 1, \"Sound.playSound\", 320118300946002, true, 25)\r\n    invoke_custom(005000, 1, \"bubble\", grouilleuxTwo, \"quest.brume.foret.00.01\")\r\n    invoke_custom(008500, 1, \"clearBubbles\", grouilleuxTwo)\r\n    \r\n    --N’importe quoi, le mien est vachement plus stylé. C’est sûr que mon Férociraptor sera au moins 800 fois plus méchant et dangereux que le tien.\r\n    invoke_custom(09000, 1, \"Sound.playSound\", 320118300946003, true, 25)\r\n    invoke_custom(09000, 1, \"bubble\", grouilleuxOne, \"quest.brume.foret.00.02\")\r\n    invoke_custom(13500, 1, \"clearBubbles\", grouilleuxOne)\r\n    \r\n    --Il sera juste 800 fois plus nul que le mien, ce qui m’étonne pas trop parce qu’on a le Férociraptor qu’on mérite.\r\n    invoke_custom(014000, 1, \"Sound.playSound\", 320118300946004, true, 25)\r\n    invoke_custom(014000, 1, \"bubble\", grouilleuxTwo, \"quest.brume.foret.00.03\")\r\n    invoke_custom(018000, 1, \"clearBubbles\", grouilleuxTwo)\r\n    \r\n    --Ouais, c’est pour ça que le tien sera complètement pourri !\r\n    invoke_custom(018500, 1, \"Sound.playSound\", 320118300946005, true, 25)\r\n    invoke_custom(018500, 1, \"bubble\", grouilleuxOne, \"quest.brume.foret.00.04\")\r\n    invoke_custom(021500, 1, \"clearBubbles\", grouilleuxOne)\r\n    \r\n    --N’IMPORTE QUOI !!!\r\n    invoke_custom(022000, 1, \"Sound.playSound\", 320118300946006, true, 25)\r\n    invoke_custom(022000, 1, \"bubble\", grouilleuxTwo, \"quest.brume.foret.00.05\")\r\n    invoke_custom(024000, 1, \"clearBubbles\", grouilleuxTwo)\r\n    \r\n    invoke_custom(025000, 1, \"Mobile.moveMobile\", petokask, 0, -4, 0)\r\n    \r\n    invoke_custom(027000, 1, \"Mobile.setMobileDirection\", grouilleuxOne, 3)\r\n    invoke_custom(027000, 1, \"Mobile.setMobileDirection\", grouilleuxTwo, 3)\r\n    \r\n    --Aheum... Bonjour m’dame ! On discutait de, euh…\r\n    invoke_custom(28000, 1, \"Sound.playSound\", 320118300946001, true, 25)\r\n    invoke_custom(28000, 1, \"Camera.setZoomFactor\", 1.4)\r\n    invoke_custom(28000, 1, \"bubble\", grouilleuxOne, \"quest.brume.foret.00.06\")\r\n    invoke_custom(31000, 1, \"clearBubbl