320118300946004, true, 25)\r\n    invoke_custom(75000, 1, \"bubble\", grouilleuxTwo, \"quest.brume.foret.01.14\")\r\n    invoke_custom(78500, 1, \"clearBubbles\", grouilleuxTwo)\r\n    \r\n    --Il est vraiment bête. On devrait pas perdre notre temps avec lui, tu viens ?\r\n    invoke_custom(79000, 1, \"Sound.playSound\", 320118300946005, true, 25)\r\n    invoke_custom(79000, 1, \"bubble\", grouilleuxOne, \"quest.brume.foret.01.15\")\r\n    invoke_custom(82000, 1, \"clearBubbles\", grouilleuxOne)\r\n    \r\n    -- \"...\"\r\n    invoke_custom(82500, 1, \"bubble\", playerId, \"quest.brume.intro.02.20\")\r\n    invoke_custom(84500, 1, \"clearBubbles\", playerId)\r\n    \r\n    --Bah, faites ce que vous voulez, moi j’y vais !\r\n    invoke_custom(85000, 1, \"Sound.playSound\", 320118300946006, true, 25)\r\n    invoke_custom(85000, 1, \"bubble\", grouilleuxOne, \"quest.brume.foret.01.16\")\r\n    invoke_custom(88000, 1, \"clearBubbles\", grouilleuxOne)\r\n    \r\n    invoke_custom(88000, 1, \"Mobile.moveMobile\", grouilleuxOne, 0, 1, 0)\r\n    invoke_custom(92000, 1, \"Mobile.setMobileVisible\", grouilleuxOne, false)\r\n    \r\n    --Tu sais…\r\n    invoke_custom(92500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmoteMarket-HausseEpaules\")\r\n    invoke_custom(92500, 1, \"bubble\", playerId, \"quest.brume.foret.01.17\")\r\n    invoke_custom(94500, 1, \"clearBubbles\", playerId)\r\n    \r\n    --T’inquiète pas, j’ai bien compris que c’est pas un vrai œuf. Je suis pas bête, tu sais.\r\n    invoke_custom(95000, 1, \"Sound.playSound\", 320118300946001, true, 25)\r\n    invoke_custom(95000, 1, \"bubble\", grouilleuxTwo, \"quest.brume.foret.01.18\")\r\n    invoke_custom(98500, 1, \"clearBubbles\", grouilleuxTwo)\r\n    \r\n    --Je veux bien te le donner à une seule condition.\r\n    invoke_custom(099000, 1, \"Sound.playSound\", 320118300946002, true, 25)\r\n    invoke_custom(099000, 1, \"bubble\", grouilleuxTwo, \"quest.brume.foret.01.19\")\r\n    invoke_custom(102000, 1, \"clearBubbles\", grouilleuxTwo)\r\n    \r\n    --Je t’écoute.\r\n    invoke_custom(102500, 1, \"bubble\", playerId, \"quest.brume.foret.01.20\")\r\n    invoke_custom(102500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Calmer\")\r\n    invoke_custom(104500, 1, \"clearBubbles\", playerId)\r\n    \r\n    --Si tu arrives à m’en dégoter un vrai, alors je te donne celui-ci.\r\n    invoke_custom(105000, 1, \"Sound.playSound\", 320118300946003, true, 25)\r\n    invoke_custom(105000, 1, \"bubble\", grouilleuxTwo, \"quest.brume.foret.01.21\")\r\n    invoke_custom(108000, 1, \"clearBubbles\", grouilleuxTwo)\r\n    \r\n    --Un vrai ? Mais, pourquoi ?\r\n    invoke_custom(108500, 1, \"bubble\", playerId, \"quest.brume.foret.01.22\")\r\n    invoke_custom(108500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Non\")\r\n    invoke_custom(110500, 1, \"clearBubbles\", playerId)\r\n    \r\n    --Bah, ça me paraît logique. Pour le contrôler et devenir le plus fort.\r\n    invoke_custom(111000, 1, \"Sound.playSound\", 320118300946005, true, 25)\r\n    invoke_custom(111000, 1, \"bubble\", grouilleuxTwo, \"quest.brume.foret.01.23\")\r\n    invoke_custom(114000, 1, \"clearBubbles\", grouilleuxTwo)\r\n    \r\n    --Mais, tu as bien vu que ça ne fonctionnait pas avec celui de ton copain.\r\n    invoke_custom(114500, 1, \"bubble\", playerId, \"quest.brume.foret.01.24\")\r\n    invoke_custom(114500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(116500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Pointer\")\r\n    invoke_custom(118000, 1, \"clearBubbles\", playerId)\r\n    \r\n    --Mon copain ? C’est un mec stupide, il sait pas du tout y faire avec les Férociraptors. Moi j'aurais aucun souci à le dompter.\r\n    invoke_custom(118500, 1, \"Sound.playSound\", 320118300946006, true, 25)\r\n    invoke_custom(118500, 1, \"bubble\", grouilleuxTwo, \"quest.brume.foret.01.25\")\r\n    invoke_custom(123000, 1, \"clearBubbles\", grouilleuxTwo)\r\n    \r\n    --Si tu le dis…\r\n    invoke_custom(123500, 1, \"bubble\", playerId, \"quest.brume.foret.01.26\")\r\n    invoke_custom(123500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmoteMarket-HausseEpaules\")\r\n    invoke_custom(125500, 1, \"clearBubbles\", playerId)\r\n    \r\n    --**La suite se passera sans doute mieux si je ne lui dis rien de plus\r\n    invoke_custom(126000, 1, \"bubble\", playerId, \"quest.brume.foret.01.27\")\r\n    invoke_custom(126000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(129500, 1, \"clearBubbles\", playerId)\r\n    \r\n    --Très bien ! Je vais aller t’en trouver un autre.\r\n    invoke_custom(130000, 1, \"bubble\", playerId, \"quest.brume.foret.01.28\")\r\n    invoke_custom(130000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Acquiescer\")\r\n    invoke_custom(132000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Victoire\")\r\n    invoke_custom(134000, 1, \"clearBubbles\", playerId)\r\n    \r\n    --Surtout, n’en parle à personne.\r\n    invoke_custom(134500, 1, \"Sound.playSound\", 320118300946001, true, 25)\r\n    invoke_custom(134500, 1, \"bubble\", grouilleuxTwo, \"quest.brume.foret.01.29\")\r\n    invoke_custom(137500, 1, \"clearBubbles\", grouilleuxTwo)\r\n    \r\n    invoke_custom(138000, 1, \"customSkip\")\nend\n\n-- [CLIENT_TRIGGERED_EVENT] Cinématique ACH 5340 OBJ 11300 - Validation\n-- \nfunction event_2595_23165()\n    \nend\n\n-- [DIALOG_EXECUTED] On cache l'œuf bleu quand le joueur le récupère\n-- \nfunction event_2595_23340()\n    setBlueEggVisible(false)\nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","hideGrouilleux","showGrouilleux","setBlueEggVisible","setBlackEggVisible","hideEggs","showEggs","event_2595_23154","event_2595_23155","event_2595_23161","customSkip","event_2595_23162","event_2595_23166","customSkip","event_2595_23167","event_2595_23178","customSkip","event_2595_23179","event_2595_23164","customSkip","event_2595_23165","event_2595_23340"],"quest_calls":[],"dialogue_calls":[]},"scenario/2596.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\napsId_1 = 71098004\r\napsId_3 = 71098005\r\n\r\n-- les fonctions où on cache\r\nfunction hideMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, false)\r\nend\r\n\r\nfunction hidePart(monsterMobileId, partName)\r\n\tMobile.setPartVisible(monsterMobileId, false, partName)\r\nend\r\n\r\n-- les fonctions où on rend visible (à nouveau)\r\nfunction showMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, true)\r\nend\r\n\r\nfunction showPart(monsterMobileId, partName)\r\n\tMobile.setPartVisible(monsterMobileId, true, partName)\r\nend\r\n\r\n-- Fonction pour afficher les lasers et la lumière\r\n\r\nfunction displayDoors(forest, canyon, savannah, swamps, desolation, forestOpen, canyonOpen, savannahOpen, swampsOpen, desolationOpen)\r\n\r\n\t-- \"Forêt\"\r\n\tif (forest == 1) then\r\n\t\tif (forestGlobalLight ~= nil) then\r\n\t\t\tLight.removeGlobalLight(forestGlobalLight)\r\n\t\tend\r\n\r\n\t\tif (forestLight ~= nil) then\r\n\t\t\tLight.removePointLight(forestLight)\r\n\t\tend\r\n\r\n\t\tforestGlobalLight = Light.addGlobalLight(-0.5, -0.5, -0.5)\r\n\t\tif (forestOpen == 1) then\r\n\t\t\tforestLight = Light.addPointLight(208, -161, 0, 0.5, 0.5, 0.5, 15)\r\n\t\tend\r\n\r\n\t\tforestDoorA = Particle.addParticleSystem(apsId_3, 209, -175, 0)\r\n\t\tforestDoorB = Particle.addParticleSystem(apsId_3, 209, -175, 5)\r\n\r\n\t-- \"Canyon\"\r\n\telseif (canyon == 1) then\r\n\t\tcanyonDoorA = Particle.addParticleSystem(apsId_1, 5, 13, 53)\r\n\t\tcanyonDoorB = Particle.addParticleSystem(apsId_1, 5, 13, 58)\r\n\r\n\t-- \"Savane\"\r\n\telseif (savannah == 1) then\r\n\t\tif (savannahGlobalLight ~= nil) then\r\n\t\t\tLight.removeGlobalLight(savannahGlobalLight)\r\n\t\tend\r\n\r\n\t\tif (savannahLight ~= nil) then\r\n\t\t\tLight.removePointLight(savannahLight)\r\n\t\tend\r\n\r\n\t\tsavannahGlobalLight = Light.addGlobalLight(-0.5, -0.5, -0.5)\r\n\t\tif (savannahOpen == 1) then\r\n\t\t\tsavannahLight = Light.addPointLight(560, 550, 0, 0.5, 0.5, 0.5, 15)\r\n\t\tend\r\n\r\n\t\tsavannahDoorA = Particle.addParticleSystem(apsId_1, 551, 552, 0)\r\n\t\tsavannahDoorB = Particle.addParticleSystem(apsId_1, 551, 552, 5)\r\n\r\n\t-- \"Marais\"\r\n\telseif (swamps == 1) then\r\n\t\tif (swampsGlobalLight ~= nil) then\r\n\t\t\tLight.removeGlobalLight(swampsGlobalLight)\r\n\t\tend\r\n\r\n\t\tif (swampsLight ~= nil) then\r\n\t\t\tLight.removePointLight(swampsLight)\r\n\t\tend\r\n\r\n\t\tswampsGlobalLight = Light.addGlobalLight(-0.5, -0.5, -0.5)\r\n\t\tif (swampsOpen == 1) then\r\n\t\t\tswampsLight = Light.addPointLight(299, 310, 0, 0.5, 0.5, 0.5, 15)\r\n\t\tend\r\n\r\n\t\tswampsDoorA = Particle.addParticleSystem(apsId_3, 300, 296, 0)\r\n\t\tswampsDoorB = Particle.addParticleSystem(apsId_3, 300, 296, 5)\r\n\r\n\t-- \"Désolation\"\r\n\telseif (desolation == 1) then\r\n\t\tif (desolationGlobalLight ~= nil) then\r\n\t\t\tLight.removeGlobalLight(desolationGlobalLight)\r\n\t\tend\r\n\r\n\t\tif (desolationLight ~= nil) then\r\n\t\t\tLight.removePointLight(desolationLight)\r\n\t\tend\r\n\r\n\t\tdesolationGlobalLight = Light.addGlobalLight(-0.5, -0.5, -0.5)\r\n\t\tif (desolationOpen == 1) then\r\n\t\t\tdesolationLight = Light.addPointLight(535, 73, 12, 0.5, 0.5, 0.5, 15)\r\n\t\tend\r\n\r\n\t\tdesolationDoorA = Particle.addParticleSystem(apsId_3, 536, 59, 12)\r\n\t\tdesolationDoorB = Particle.addParticleSystem(apsId_3, 536, 59, 17)\r\n\telse\r\n\tend\r\nend\n\n-- [INITIALISATION] Serveur\n-- \nfunction event_2596_23170()\n    \nend\n\n-- ENTER_INSTANCE - On affiche/cache les portes et on affiche les timers\n-- \nfunction event_2596_23171(playerIsInForestSanctuary, playerIsInCanyonSanctuary, playerIsInSavannahSanctuary, playerIsInSwampsSanctuary, playerIsInDesolationSanctuary, sanctuaryOpenForest, startDateForest, sanctuaryOpenCanyon, startDateCanyon, sanctuaryOpenSavannah, startDateSavannah, sanctuaryOpenSwamps, startDateSwamps, sanctuaryOpenDesolation, startDateDesolation, playerDate)\n    local playerIsInForestSanctuary = toLong(playerIsInForestSanctuary)\r\n    local playerIsInCanyonSanctuary = toLong(playerIsInCanyonSanctuary)\r\n    local playerIsInSavannahSanctuary = toLong(playerIsInSavannahSanctuary)\r\n    local playerIsInSwampsSanctuary = toLong(playerIsInSwampsSanctuary)\r\n    local playerIsInDesolationSanctuary = toLong(playerIsInDesolationSanctuary)\r\n    \r\n    local sanctuaryOpenForest = toLong(sanctuaryOpenForest)\r\n    local sanctuaryOpenCanyon = toLong(sanctuaryOpenCanyon)\r\n    local sanctuaryOpenSavannah = toLong(sanctuaryOpenSavannah)\r\n    local sanctuaryOpenSwamps = toLong(sanctuaryOpenSwamps)\r\n    local sanctuaryOpenDesolation = toLong(sanctuaryOpenDesolation)\r\n    \r\n    local openDate\r\n    local currentDate\r\n    local open = 0\r\n    \r\n    displayDoors(playerIsInForestSanctuary, playerIsInCanyonSanctuary, playerIsInSavannahSanctuary, playerIsInSwampsSanctuary, playerIsInDesolationSanctuary, sanctuaryOpenForest, sanctuaryOpenCanyon, sanctuaryOpenSavannah, sanctuaryOpenSwamps, sanctuaryOpenDesolation)\r\n    \r\n    if (playerIsInForestSanctuary == 1 and sanctuaryOpenForest == 1) then\r\n        openDate = toLong(startDateForest)\r\n        currentDate = toLong(playerDate)\r\n        open = 1\r\n    elseif (playerIsInCanyonSanctuary == 1 and sanctuaryOpenCanyon == 1) then\r\n        openDate = toLong(startDateCanyon)\r\n        currentDate = toLong(playerDate)\r\n        open = 1\r\n    elseif (playerIsInSavannahSanctuary == 1 and sanctuaryOpenSavannah == 1) then\r\n        openDate = toLong(startDateSavannah)\r\n        currentDate = toLong(playerDate)\r\n        open = 1\r\n    elseif (playerIsInSwampsSanctuary == 1 and sanctuaryOpenSwamps == 1) then\r\n        openDate = toLong(startDateSwamps)\r\n        currentDate = toLong(playerDate)\r\n        open = 1\r\n    elseif (playerIsInDesolationSanctuary == 1 and sanctuaryOpenDesolation == 1) then\r\n        openDate = toLong(startDateDesolation)\r\n        currentDate = toLong(playerDate)\r\n        open = 1\r\n    end\r\n    \r\n    local total = 3600\r\n    local remaining = 0\r\n    local elapsed = 0\r\n    \r\n    if (openDate ~= nil and openDate > 0 and currentDate ~= nil and currentDate > 0) then\r\n    \r\n        elapsed = math.floor((currentDate - openDate) / 1000)\r\n    \r\n        if (elapsed ~= nil and elapsed > 0) then\r\n            remaining = total - elapsed\r\n        end\r\n    end\r\n    \r\n    UI.stopCountdown()\r\n    if (remaining > 0 and open) then\r\n        UI.startCountdown(remaining)\r\n    end\r\n    \r\n    Server.triggerEvent(23171)\nend\n\n-- Le joueur quitte l'instance\n-- \nfunction event_2596_23181()\n    UI.stopCountdown()\nend\n\n-- 1 - Collector Forêt - Ouverture\n-- \nfunction event_2596_23182()\n    if (forestLight == nil) then\r\n    \tforestLight = Light.addPointLight(208, -161, 0, 0.5, 0.5, 0.5, 15)\r\n    end\r\n    \r\n    UI.openRewardsDialog(\"brumes.golem.activation\")\r\n    UI.addReward(32069)\r\n    UI.addReward(32071)\r\n    \r\n    UI.stopCountdown()\r\n    UI.startCountdown(3600)\r\n    Server.triggerEvent(23171)\nend\n\n-- 1 - Collector Forêt - Fermeture\n-- \nfunction event_2596_23183()\n    UI.openInfoDialog(\"moon.collector.end.title\", \"brumes.golem.end\" )\r\n    UI.stopCountdown()\r\n    \r\n    if (forestLight ~= nil) then\r\n    \tLight.removePointLight(forestLight)\r\n    end\nend\n\n-- 2 - Collector Canyon - Ouverture\n-- \nfunction event_2596_23192()\n    UI.openRewardsDialog(\"brumes.golem.activation\")\r\n    UI.addReward(32079)\r\n    UI.addReward(32081)\r\n    \r\n    UI.stopCountdown()\r\n    UI.startCountdown(3600)\r\n    Server.triggerEvent(23171)\nend\n\n-- 2 - Collector Canyon - Fermeture\n-- \nfunction event_2596_23193()\n    UI.openInfoDialog(\"moon.collector.end.title\", \"brumes.golem.end\" )\r\n    UI.stopCountdown()\nend\n\n-- 3 - Collector Savane - Ouverture\n-- \nfunction event_2596_23194()\n    if (savannahLight == nil) then\r\n    \tsavannahLight = Light.addPointLight(560, 550, 0, 0.5, 0.5, 0.5, 15)\r\n    end\r\n    \r\n    UI.openRewardsDialog(\"brumes.golem.activation\")\r\n    UI.addReward(32089)\r\n    UI.addReward(32091)\r\n    \r\n    UI.stopCountdown()\r\n    UI.startCountdown(3600)\r\n    Server.triggerEvent(23171)\nend\n\n-- 3 - Collector Savane - Fermeture\n-- \nfunction event_2596_23195()\n    if (savannahLight ~= nil) then\r\n    \tLight.removePointLight(savannahLight)\r\n    end\r\n    \r\n    UI.openInfoDialog(\"moon.collector.end.title\", \"brumes.golem.end\" )\r\n    UI.stopCountdown()\nend\n\n-- 4 - Collector Marais - Ouverture\n-- \nfunction event_2596_23196(playerIsInSwampsSanctuary, sanctuaryOpenSwamps)\n    if (swampsLight == nil) then\r\n    \tswampsLight = Light.addPointLight(299, 310, 0, 0.5, 0.5, 0.5, 15)\r\n    end\r\n    \r\n    UI.openRewardsDialog(\"brumes.golem.activation\")\r\n    UI.addReward(32109)\r\n    UI.addReward(32111)\r\n    \r\n    UI.stopCountdown()\r\n    UI.startCountdown(3600)\r\n    Server.triggerEvent(23171)\nend\n\n-- 4 - Collector Marais - Fermeture\n-- \nfunction event_2596_23197()\n    if (swampsLight ~= nil) then\r\n    \tLight.removePointLight(swampsLight)\r\n    end\r\n    \r\n    UI.openInfoDialog(\"moon.collector.end.title\", \"brumes.golem.end\" )\r\n    UI.stopCountdown()\nend\n\n-- 5 - Collector Désolation - Ouverture\n-- \nfunction event_2596_23198()\n    if (desolationLight == nil) then\r\n    \tdesolationLight = Light.addPointLight(535, 73, 12, 0.5, 0.5, 0.5, 15)\r\n    end\r\n    \r\n    UI.openRewardsDialog(\"brumes.golem.activation\")\r\n    UI.addReward(32099)\r\n    UI.addReward(32101)\r\n    \r\n    UI.stopCountdown()\r\n    UI.startCountdown(3600)\r\n    Server.triggerEvent(23171)\nend\n\n-- 5 - Collector Désolation - Fermeture\n-- \nfunction event_2596_23199()\n    if (desolationLight ~= nil) then\r\n    \tLight.removePointLight(desolationLight)\r\n    end\r\n    \r\n    UI.openInfoDialog(\"moon.collector.end.title\", \"brumes.golem.end\" )\r\n    UI.stopCountdown()\nend\n\n-- Dialogue PNJ - 1 - Forêt - Spawn du groupe + Lancement du combat\n-- \nfunction event_2596_23184()\n    \nend\n\n-- Dialogue PNJ - 2 - Canyon - Spawn du groupe + Lancement du combat\n-- \nfunction event_2596_23213()\n    \nend\n\n-- Dialogue PNJ - 3 - Savane - Spawn du groupe + Lancement du combat\n-- \nfunction event_2596_23214()\n    \nend\n\n-- Dialogue PNJ - 4 - Marécages - Spawn du groupe + Lancement du combat\n-- \nfunction event_2596_23215()\n    \nend\n\n-- Dialogue PNJ - 5 - Désolation - Spawn du groupe + Lancement du combat\n-- \nfunction event_2596_23216()\n    \nend\n\n-- [FIGHT_ENTER_ACTION_PHASE] Forêt - On pose les cellules de la forme d'arrivée\n-- \nfunction event_2596_23208()\n    \nend\n\n-- [FIGHT_ENTER_ACTION_PHASE] Canyon - On pose les cellules de la forme d'arrivée\n-- \nfunction event_2596_23209()\n    \nend\n\n-- [FIGHT_ENTER_ACTION_PHASE] Savane - On pose les cellules de la forme d'arrivée\n-- \nfunction event_2596_23210()\n    \nend\n\n-- [FIGHT_ENTER_ACTION_PHASE] Marais - On pose les cellules de la forme d'arrivée\n-- \nfunction event_2596_23211()\n    \nend\n\n-- [FIGHT_ENTER_ACTION_PHASE] Désolation - On pose les cellules de la forme d'arrivée\n-- \nfunction event_2596_23212()\n    \nend\n\n-- CLIENT_TRIGGERED_EVENT / ENTER_INSTANCE - 1 - On lance la quête Forêt\n-- \nfunction event_2596_23218()\n    \nend\n\n-- CLIENT_TRIGGERED_EVENT / ENTER_INSTANCE - 2 - On lance la quête Canyon\n-- \nfunction event_2596_23219()\n    \nend\n\n-- CLIENT_TRIGGERED_EVENT / ENTER_INSTANCE - 3 - On lance la quête Savane\n-- \nfunction event_2596_23220()\n    \nend\n\n-- CLIENT_TRIGGERED_EVENT / ENTER_INSTANCE - 4 - On lance la quête Marais\n-- \nfunction event_2596_23221()\n    \nend\n\n-- CLIENT_TRIGGERED_EVENT / ENTER_INSTANCE - 5 - On lance la quête Désolation\n-- \nfunction event_2596_23222()\n    \nend\n\n-- PLAYER_WON_FIGHT - 1 - Validation ACH 5469\n-- \nfunction event_2596_23374()\n    \nend\n\n-- PLAYER_WON_FIGHT - 2 - Validation ACH 5470\n-- \nfunction event_2596_23375()\n    \nend\n\n-- PLAYER_WON_FIGHT - 3 - Validation ACH 5471\n-- \nfunction event_2596_23376()\n    \nend\n\n-- PLAYER_WON_FIGHT - 4 - Validation ACH 5472\n-- \nfunction event_2596_23377()\n    \nend\n\n-- PLAYER_WON_FIGHT - 5 - Validation ACH 5473\n-- \nfunction event_2596_23378()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","hideMonster","hidePart","showMonster","showPart","displayDoors","event_2596_23170","event_2596_23171","event_2596_23181","event_2596_23182","event_2596_23183","event_2596_23192","event_2596_23193","event_2596_23194","event_2596_23195","event_2596_23196","event_2596_23197","event_2596_23198","event_2596_23199","event_2596_23184","event_2596_23213","event_2596_23214","event_2596_23215","event_2596_23216","event_2596_23208","event_2596_23209","event_2596_23210","event_2596_23211","event_2596_23212","event_2596_23218","event_2596_23219","event_2596_23220","event_2596_23221","event_2596_23222","event_2596_23374","event_2596_23375","event_2596_23376","event_2596_23377","event_2596_23378"],"quest_calls":["UI.openRewardsDialog(\"brumes.golem.activation\")\r","UI.openRewardsDialog(\"brumes.golem.activation\")\r","UI.openRewardsDialog(\"brumes.golem.activation\")\r","UI.openRewardsDialog(\"brumes.golem.activation\")\r","UI.openRewardsDialog(\"brumes.golem.activation\")\r"],"dialogue_calls":[]},"scenario/2597.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\napsId_1 = 71098004\r\napsId_3 = 71098005\r\n\r\n-- les fonctions où on cache\r\nfunction hideMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, false)\r\nend\r\n\r\nfunction hidePart(monsterMobileId, partName)\r\n\tMobile.setPartVisible(monsterMobileId, false, partName)\r\nend\r\n\r\n-- les fonctions où on rend visible (à nouveau)\r\nfunction showMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, true)\r\nend\r\n\r\nfunction showPart(monsterMobileId, partName)\r\n\tMobile.setPartVisible(monsterMobileId, true, partName)\r\nend\r\n\r\n-- Fonction pour afficher les lasers\r\n\r\nfunction displayDoors()\r\n-- \"Forêt\"\r\n\tforestDoorA = Particle.addParticleSystem(apsId_3, 209, -175, 0)\r\n\tforestDoorB = Particle.addParticleSystem(apsId_3, 209, -175, 5)\r\n-- \"forestLight = Light.addPointLight(207, -193, 3, -1.0, -1.0, -1.0, 10)\"\r\n\t\r\n-- \"Canyon\"\r\n\tcanyonDoorA = Particle.addParticleSystem(apsId_1, 5, 13, 53)\r\n\tcanyonDoorB = Particle.addParticleSystem(apsId_1, 5, 13, 58)\r\n-- \"canyonLight = Light.addPointLight(-14, 15, 56, -1.0, -1.0, -1.0, 10)\"\r\n\t\r\n-- \"Savane\"\r\n\tsavannahDoorA = Particle.addParticleSystem(apsId_1, 551, 552, 0)\r\n\tsavannahDoorB = Particle.addParticleSystem(apsId_1, 551, 552, 5)\r\n\r\n-- \"Marais\"\r\n\tswampsDoorA = Particle.addParticleSystem(apsId_3, 300, 296, 0)\r\n\tswampsDoorB = Particle.addParticleSystem(apsId_3, 300, 296, 5)\r\n\t\t\r\n-- \"Désolation\"\r\n\tdesolationDoorA = Particle.addParticleSystem(apsId_3, 536, 59, 12)\r\n\tdesolationDoorB = Particle.addParticleSystem(apsId_3, 536, 59, 17)\r\nend\n\n-- [INITIALISATION] Serveur\n-- \nfunction event_2597_23185()\n    \nend\n\n-- ENTER_INSTANCE - On affiche/cache les portes\n-- \nfunction event_2597_23186()\n    displayDoors()\r\n    \r\n    local openDate = toLong(startDate)\r\n    local currentDate = toLong(playerDate)\r\n    local open = doorOpenCroco\r\n    \r\n    local total = 3600\r\n    local remaining = 0\r\n    local elapsed = 0\r\n    \r\n    if (openDate ~= nil and openDate > 0 and currentDate ~= nil and currentDate > 0) then\r\n    \r\n    \telapsed = math.floor((currentDate - openDate) / 1000)\r\n    \t\r\n    \tif (elapsed ~= nil  and elapsed > 0) then\r\n    \t\tremaining = total - elapsed\r\n    \tend\r\n    end\r\n    \r\n    UI.stopCountdown()\r\n    if (remaining > 0 and open) then\r\n    \tUI.startCountdown(remaining)\r\n    end\nend\n\n-- Le joueur quitte l'instance\n-- \nfunction event_2597_23187()\n    UI.stopCountdown()\nend\n\n-- Collector Forêt - Ouverture\n-- \nfunction event_2597_23188()\n    UI.openRewardsDialog(\"brumes.golem.activation\")\r\n    UI.addReward(32070)\r\n    UI.addReward(32072)\r\n    UI.stopCountdown()\r\n    UI.startCountdown(3600)\nend\n\n-- Collector Forêt - Fermeture\n-- \nfunction event_2597_23189()\n    UI.openInfoDialog(\"moon.collector.end.title\", \"brumes.golem.end\" )\r\n    UI.stopCountdown()\nend\n\n-- Dialogue PNJ - Spawn du groupe + Lancement du combat\n-- \nfunction event_2597_23190()\n    \nend\n\n-- [FIGHT_ENTER_ACTION_PHASE] Forêt - On pose les cellules de la forme d'arrivée\n-- \nfunction event_2597_23191()\n    \nend\n\n-- [FIGHT_ENTER_ACTION_PHASE] Canyon - On pose les cellules de la forme d'arrivée\n-- \nfunction event_2597_23207()\n    \nend\n\n-- [FIGHT_ENTER_ACTION_PHASE] Savane - On pose les cellules de la forme d'arrivée\n-- \nfunction event_2597_23205()\n    \nend\n\n-- [FIGHT_ENTER_ACTION_PHASE] Marais - On pose les cellules de la forme d'arrivée\n-- \nfunction event_2597_23204()\n    \nend\n\n-- [FIGHT_ENTER_ACTION_PHASE] Désolation - On pose les cellules de la forme d'arrivée\n-- \nfunction event_2597_23206()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","hideMonster","hidePart","showMonster","showPart","displayDoors","event_2597_23185","event_2597_23186","event_2597_23187","event_2597_23188","event_2597_23189","event_2597_23190","event_2597_23191","event_2597_23207","event_2597_23205","event_2597_23204","event_2597_23206"],"quest_calls":["UI.openRewardsDialog(\"brumes.golem.activation\")\r"],"dialogue_calls":[]},"scenario/2598.lua":{"source":"-- les fonctions où on cache\r\nfunction hideMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, false)\r\nend\r\n\r\nfunction hidePart(monsterMobileId, partName)\r\n\tMobile.setPartVisible(monsterMobileId, false, partName)\r\nend\r\n\r\n-- les fonctions où on rend visible (à nouveau)\r\nfunction showMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, true)\r\nend\r\n\r\nfunction showPart(monsterMobileId, partName)\r\n\tMobile.setPartVisible(monsterMobileId, true, partName)\r\nend\n\n-- [INITIALISATION] Serveur\n-- \nfunction event_2598_23200()\n    \nend\n\n-- Q5 - ENTER_INSTANCE - On cache les Machines de Nox\n-- \nfunction event_2598_23201(noxMachineA, noxMachineB, noxMachineC, noxMachineD)\n    Mobile.addMobileCreationCallback(noxMachineA, \"hideMonster\", noxMachineA)\r\n    Mobile.addMobileCreationCallback(noxMachineB, \"hideMonster\", noxMachineB)\r\n    Mobile.addMobileCreationCallback(noxMachineC, \"hideMonster\", noxMachineC)\r\n    Mobile.addMobileCreationCallback(noxMachineD, \"hideMonster\", noxMachineD)\nend\n\n-- Q5 - MONSTER_ACTION - On affiche les Machines de Nox\n-- \nfunction event_2598_23234(noxMachineA, noxMachineB, noxMachineC, noxMachineD)\n    Mobile.addMobileCreationCallback(noxMachineA, \"showMonster\", noxMachineA)\r\n    Mobile.addMobileCreationCallback(noxMachineB, \"showMonster\", noxMachineB)\r\n    Mobile.addMobileCreationCallback(noxMachineC, \"showMonster\", noxMachineC)\r\n    Mobile.addMobileCreationCallback(noxMachineD, \"showMonster\", noxMachineD)\nend\n\n","functions":["hideMonster","hidePart","showMonster","showPart","event_2598_23200","event_2598_23201","event_2598_23234"],"quest_calls":[],"dialogue_calls":[]},"scenario/2599.lua":{"source":"\n\n-- [EVENT] Initialisation\n-- \nfunction event_2599_23227()\n    \nend\n\n-- [EVENT] Le joueur confronte les Bworks - Lancement du combat\n-- \nfunction event_2599_23229(groupId, mobA, fightId, playerId)\n    playerId = toLong(playerId)\r\n    groupId =toLong(groupId)\r\n    fightId = toLong(fightId)\r\n    mobA = toLong(mobA)\r\n    \r\n    trace(\"===Valeur de Player Id ======\", playerId)\r\n    trace(\"===Valeur de Group Id ======\", groupId)\r\n    trace(\"===Valeur de Fight Id ======\", fightId)\r\n    trace(\"===Valeur de MobA Id ======\", mobA)\nend\n\n-- [EVENT] Fin de combat contre les Bworks (ACH 5345 OBJ 11178)\n-- \nfunction event_2599_23230(pandora)\n    local playerId = Context.getLeaderId()\r\n    local pandoraRealId = toLong(pandora)\r\n    local voyageurId = createActor(1106905252, -224, -40, -79, 8, 3, 8)\r\n    local pandoraId  = createActor(163503405,  -224, -36, -79, 8, 7, 8)\r\n    \r\n    ----------------------------- SKIP DE CINEMATIQUE PAR LE BOUTON --------------------------\r\n    function customSkip()\r\n    \tMobile.setMobileVisible(pandoraRealId, true)\r\n    \tskipCinematic(21277)\r\n    end\r\n    \r\n    startCinematicContext(0.8, pandoraId, 210079)\r\n    \r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"customSkip\")\r\n    \r\n    invoke_custom(00001, 1, \"Mobile.setMobileVisible\", pandoraRealId, false)\r\n    invoke_custom(00001, 1, \"Mobile.setMobileAnimation\", pandoraId, \"AnimKO-Boucle\")\r\n    invoke_custom(00001, 1, \"Mobile.setMobilePosition\", playerId, -223, -35, -80)\r\n    invoke_custom(00001, 1, \"Mobile.setMobileDirection\", playerId, 7)\r\n    invoke_custom(00005, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimKO-Boucle\")\r\n    \r\n    -- \"Qu'est-ce que c'est que ce type... Nos attaques ne lui font rien...\"\r\n    invoke_custom(05000, 1, \"bubble\", playerId, \"quest.chuchoku.03.01\")\r\n    invoke_custom(09500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Son aiguille lui permet d'ouvrir des bulles temporelles...\"\r\n    invoke_custom(09000, 1, \"bubble\", pandoraId, \"quest.chuchoku.03.02\")\r\n    invoke_custom(14500, 1, \"clearBubbles\", pandoraId)\r\n    \r\n    -- \"Cette personne... n'est pas un Veilleur !\"\r\n    invoke_custom(15000, 1, \"bubble\", pandoraId, \"quest.chuchoku.03.03\")\r\n    invoke_custom(18500, 1, \"clearBubbles\", pandoraId)\r\n    \r\n    -- \"Ah bah merci, on n'avait pas remarqué...\"\r\n    invoke_custom(18500, 1, \"bubble\", playerId, \"quest.chuchoku.03.04\")\r\n    invoke_custom(21000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(21000, 1, \"Mobile.setMobileAnimation\", voyageurId, \"AnimMarche\")\r\n    invoke_custom(21700, 1, \"Mobile.setMobilePosition\", voyageurId, -224, -37, -79)\r\n    invoke_custom(21800, 1, \"Mobile.setMobileAnimation\", voyageurId, \"AnimMarche-Fin\")\r\n    \r\n    -- \"Non, nos fragments de la connaissance des Dieux !\"\r\n    invoke_custom(22500, 1, \"bubble\", pandoraId, \"quest.chuchoku.03.05\")\r\n    invoke_custom(26000, 1, \"clearBubbles\", pandoraId)\r\n    \r\n    invoke_custom(26000, 1, \"Mobile.setMobileAnimation\", pandoraId, \"AnimKO-SortieOK\")\r\n    invoke_custom(26000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimKO-SortieOK\")\r\n    invoke_custom(26800, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimStatique02-Debut\")\r\n    \r\n    invoke_custom(28000, 1, \"Mobile.setMobileAnimation\", voyageurId, \"AnimSort-1\")\r\n    invoke_custom(29000, 1, \"Particle.addParticleSystem\", 410067191, -224, -36, -79)\r\n    invoke_custom(29000, 1, \"Particle.addParticleSystem\", 410067191, -223, -35, -80)\r\n    \r\n    invoke_custom(29500, 1, \"Mobile.setMobileAnimation\", pandoraId, \"AnimKO-Debut\")\r\n    invoke_custom(29500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimKO-Debut\")\r\n    \r\n    -- \"Argh ! Tu ne t'en tireras pas comme ça !\"\r\n    invoke_custom(29500, 1, \"bubble\", playerId, \"quest.chuchoku.03.06\")\r\n    invoke_custom(33000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Argh...\"\r\n    invoke_custom(29500, 1, \"bubble\", pandoraId, \"quest.chuchoku.03.07\")\r\n    invoke_custom(31000, 1, \"clearBubbles\", pandoraId)\r\n    \r\n    invoke_custom(31000, 1, \"Mobile.setMobileAnimation\", voyageurId, \"AnimMarche\")\r\n    \r\n    -- \"C'est... C'est fini... Nous avons perdu la connaissance des Dieux, tout espoir a disparu...\"\r\n    invoke_custom(33500, 1, \"bubble\", pandoraId, \"quest.chuchoku.03.08\")\r\n    invoke_custom(40000, 1, \"clearBubbles\", pandoraId)\r\n    \r\n    invoke_custom(40490, 1, \"Mobile.setMobileVisible\", pandoraRealId, true)\r\n    \r\n    invoke_custom(40500, 1, \"skipCinematic\", 21277)\nend\n\n-- [EVENT] Fin de combat\n-- \nfunction event_2599_23233()\n    \nend\n\n","functions":["event_2599_23227","event_2599_23229","event_2599_23230","customSkip","event_2599_23233"],"quest_calls":[],"dialogue_calls":[]},"scenario/2600.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\ndoorApsId = 7000109\r\ndofusApsId = 7000110 \r\n\r\n-- les fonctions où on cache\r\nfunction hideMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, false)\r\nend\r\n\r\nfunction hidePart(monsterMobileId, partName)\r\n\tMobile.setPartVisible(monsterMobileId, false, partName)\r\nend\r\n\r\n-- les fonctions où on rend visible (à nouveau)\r\nfunction showMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, true)\r\nend\r\n\r\nfunction showPart(monsterMobileId, partName)\r\n\tMobile.setPartVisible(monsterMobileId, true, partName)\r\nend\r\n\r\nfunction displayDoors()\r\n\tapsA = Particle.addParticleSystem(doorApsId, -2, -30, 8)\r\n\tapsB = Particle.addParticleSystem(doorApsId, -1, -30, 8)\r\n\tapsC = Particle.addParticleSystem(doorApsId, 0, -30, 8)\r\n\tapsD = Particle.addParticleSystem(doorApsId, 1, -30, 8)\r\n\tapsE = Particle.addParticleSystem(doorApsId, 2, -30, 8)\r\n\tapsDofus = Particle.addParticleSystem(dofusApsId, 0, -31, 8)\r\nend\n\n-- [INITIALISATION] Serveur\n-- \nfunction event_2600_23247()\n    \nend\n\n-- ENTER_INSTANCE - On inscrit au scénario\n-- \nfunction event_2600_23248()\n    displayDoors()\nend\n\n-- ENTER_INSTANCE - On donne le point de départ aux joueurs\n-- \nfunction event_2600_23304()\n    UI.loadGuideDialog(158)\nend\n\n-- Q6 - Le joueur examine le journal ensanglanté\n-- \nfunction event_2600_23249()\n    InteractiveElement.setVisible(35136, false)\nend\n\n-- DIALOG_EXECUTED - Cinématique apparition Bulak\n-- \nfunction event_2600_23250(jenry, evilTimo)\n    local playerId = Context.getLeaderId()\r\n    local jenry = toLong(jenry)\r\n    local evilTimo = toLong(evilTimo)\r\n    \r\n    local jenryId = createActor(117903815, -2, -7, 0, 4, 1, 6)\r\n    local timoId = createActor(1114205638, -2, -9, 0, 4, 3, 6)\r\n    local bulakId = createActor(1114705732, -2, -17, 0, 4, 3, 12)\r\n    \r\n    function customSkip()\r\n    \tMobile.hideOtherPlayerMobile(false)\r\n    \tMobile.setMobileVisible(jenry, true)\r\n    \tUI.displayWideScreenBand(true, 25, 500)\r\n    \tskipCinematic(23250)\r\n    end\r\n    \r\n    Mobile.hideOtherPlayerMobile(true)\r\n    Mobile.setMobileVisible(jenry, false)\r\n    Mobile.setMobileVisible(evilTimo, false)\r\n    Mobile.setMobileVisible(bulakId, false)\r\n    Mobile.setMobileDirection(playerId, 5)\r\n    \r\n    startCinematicContext(1.0, playerId)\r\n    \r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"customSkip\")\r\n    \r\n    invoke_custom(00001, 1, \"Mobile.setMobileMovementStyle\", timoId, \"WALK\", \"WALK\")\r\n    invoke_custom(00001, 1, \"Mobile.setCustomWalkStyle\", timoId, \"AnimMarche\", 600)\r\n    \r\n    invoke_custom(10500, 1, \"Camera.setZoomSpeedFactor\", 0.05)\r\n    \r\n    -- \"Voilà qui est inespéré ! Voyons voir ce que ça dit…\"\r\n    invoke_custom(01000, 1, \"bubble\", jenryId, \"quest.brume.ebene.04.01\")\r\n    invoke_custom(01000, 1, \"Mobile.setMobileAnimation\", jenryId, \"AnimDial-OK\")\r\n    invoke_custom(04000, 1, \"clearBubbles\", jenryId)\r\n    \r\n    -- \"Mhhh…\"\r\n    invoke_custom(05000, 1, \"bubble\", jenryId, \"quest.brume.ebene.04.02\")\r\n    invoke_custom(06000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Bailler\")\r\n    invoke_custom(07000, 1, \"clearBubbles\", jenryId)\r\n    \r\n    -- \"Oooh… ça alors !\"\r\n    invoke_custom(08000, 1, \"bubble\", jenryId, \"quest.brume.ebene.04.03\")\r\n    invoke_custom(08000, 1, \"Mobile.setMobileAnimation\", jenryId, \"AnimDial-Surprise\")\r\n    invoke_custom(10000, 1, \"clearBubbles\", jenryId)\r\n    \r\n    -- \"Alors ? Qu’est-ce que ça raconte ?\"\r\n    invoke_custom(10500, 1, \"bubble\", playerId, \"quest.brume.ebene.04.04\")\r\n    invoke_custom(10500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmoteMarket-HausseEpaules\")\r\n    invoke_custom(13000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Eh bien, le cadavre non loin s’appelait Crocatzin.\"\r\n    invoke_custom(13500, 1, \"bubble\", jenryId, \"quest.brume.ebene.04.05\")\r\n    invoke_custom(13500, 1, \"Mobile.setMobileAnimation\", jenryId, \"AnimDial-Discute\")\r\n    invoke_custom(16500, 1, \"clearBubbles\", jenryId)\r\n    \r\n    -- \"C’était l’un des fils de Crocoburio ! Et sa principale force résidait ironiquement dans son esprit et non dans ses muscles.\"\r\n    invoke_custom(17000, 1, \"bubble\", jenryId, \"quest.brume.ebene.04.06\")\r\n    invoke_custom(17000, 1, \"Mobile.setMobileAnimation\", jenryId, \"AnimDial-Discute\")\r\n    invoke_custom(25000, 1, \"clearBubbles\", jenryId)\r\n    \r\n    -- \"Comment sont-ils arrivés ici ?\"\r\n    invoke_custom(25500, 1, \"bubble\", playerId, \"quest.brume.ebene.04.07\")\r\n    invoke_custom(25500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Presenter\")\r\n    invoke_custom(28000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Ce sont des naufragés du chaos d’Ogrest.\"\r\n    invoke_custom(28500, 1, \"bubble\", jenryId, \"quest.brume.ebene.04.08\")\r\n    invoke_custom(28500, 1, \"Mobile.setMobileAnimation\", jenryId, \"AnimDial-Discute\")\r\n    invoke_custom(31000, 1, \"clearBubbles\", jenryId)\r\n    \r\n    -- \"Il semble d’ailleurs que cet ogre de malheur soit responsable de la seconde mort de Crocoburio.\"\r\n    invoke_custom(31500, 1, \"bubble\", jenryId, \"quest.brume.ebene.04.09\")\r\n    invoke_custom(31500, 1, \"Mobile.setMobileAnimation\", jenryId, \"AnimDial-Discute\")\r\n    invoke_custom(35500, 1, \"clearBubbles\", jenryId)\r\n    \r\n    -- \"Laisse-moi deviner : il a hérité de Crocobur ?\"\r\n    invoke_custom(36000, 1, \"bubble\", playerId, \"quest.brume.ebene.04.11\")\r\n    invoke_custom(36000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Calmer\")\r\n    invoke_custom(39000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Oui ! C’est la preuve irréfutable qu’il s’agit bel et bien de cette arme légendaire !\"\r\n    invoke_custom(39500, 1, \"bubble\", jenryId, \"quest.brume.ebene.04.12\")\r\n    invoke_custom(39500, 1, \"Mobile.setMobileAnimation\", jenryId, \"AnimEmote-OK\")\r\n    invoke_custom(44000, 1, \"clearBubbles\", jenryId)\r\n    \r\n    invoke_custom(39500, 1, \"Mobile.moveMobile\", timoId, -2, -13, 0, \"Mobile.setMobileDirection\", timoId, 3)\r\n    \r\n    -- \"Ça s’arrête là ?\"\r\n    invoke_custom(44500, 1, \"bubble\", playerId, \"quest.brume.ebene.04.13\")\r\n    invoke_custom(44500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Calmer\")\r\n    invoke_custom(46500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Non, il y a encore de nombreux passages…\"\r\n    invoke_custom(47000, 1, \"bubble\", jenryId, \"quest.brume.ebene.04.14\")\r\n    invoke_custom(47000, 1, \"Mobile.setMobileAnimation\", jenryId, \"AnimEmote-Surprise\")\r\n    invoke_custom(49500, 1, \"clearBubbles\", jenryId)\r\n    \r\n    invoke_custom(49500, 1, \"Mobile.moveMobile\", timoId, -2, -17, 0, \"Mobile.setMobileDirection\", 7)\r\n    \r\n    -- \"Il semble qu’il y avait une scission entre les anciennes et les nouvelles générations de Crocodailles.\"\r\n    invoke_custom(50000, 1, \"bubble\", jenryId, \"quest.brume.ebene.04.15\")\r\n    invoke_custom(50000, 1, \"Mobile.setMobileAnimation\", jenryId, \"AnimDial-Discute\")\r\n    invoke_custom(54000, 1, \"clearBubbles\", jenryId)\r\n    \r\n    invoke_custom(53500, 1, \"Camera.setZoomFactor\", 1.8)\r\n    \r\n    -- \"Lis