", playerId, \"quest.brume.ebene.04.22\")\r\n    invoke_custom(77500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmoteMarket-HausseEpaules\")\r\n    invoke_custom(80000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"[#name] ! Où est Timö ?!\"\r\n    invoke_custom(80500, 1, \"bubble\", jenryId, \"quest.brume.ebene.04.23\")\r\n    invoke_custom(80500, 1, \"Mobile.setMobileAnimation\", jenryId, \"AnimDial-Enerve\")\r\n    invoke_custom(82500, 1, \"clearBubbles\", jenryId)\r\n    \r\n    invoke_custom(83000, 1, \"Mobile.setMobileDirection\", jenryId, 7)\r\n    \r\n    -- \"Hein ? Il est juste là… Rah ! Fiente de Trool !\"\r\n    invoke_custom(83000, 1, \"Mobile.setMobileDirection\", playerId, 7)\r\n    invoke_custom(83000, 1, \"bubble\", playerId, \"quest.brume.ebene.04.24\")\r\n    invoke_custom(83000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Pointer\")\r\n    invoke_custom(85500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Non\")\r\n    invoke_custom(86000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(86500, 1, \"Mobile.setMobileDirection\", jenryId, 1)\r\n    \r\n    -- \"Il nous a dupés ! C’est un démon !\"\r\n    invoke_custom(86500, 1, \"bubble\", jenryId, \"quest.brume.ebene.04.25\")\r\n    invoke_custom(86500, 1, \"Mobile.setMobileAnimation\", jenryId, \"AnimDial-Enerve\")\r\n    invoke_custom(89000, 1, \"clearBubbles\", jenryId)\r\n    \r\n    invoke_custom(88000, 1, \"Mobile.moveMobile\", playerId, -1, -14, 0, \"Mobile.setMobileDirection\", playerId, 7)\r\n    \r\n    invoke_custom(89500, 1, \"Mobile.setMobileDirection\", jenryId, 7)\r\n    \r\n    -- \"Là-bas ! Tu dois absolument l’empêcher de toucher Crocobur !\"\r\n    invoke_custom(89500, 1, \"bubble\", jenryId, \"quest.brume.ebene.04.26\")\r\n    invoke_custom(89500, 1, \"Mobile.setMobileAnimation\", jenryId, \"AnimEmote-Pointer\")\r\n    invoke_custom(93000, 1, \"clearBubbles\", jenryId)\r\n    \r\n    invoke_custom(90500, 1, \"Camera.attachCameraToMobile\", timoId)\r\n    \r\n    -- \"Héhé, bien tenté, mais c’est trop tard aventuri{[1*]?ère:er} !\"\r\n    invoke_custom(89500, 1, \"bubble\", timoId, \"quest.brume.ebene.04.27\")\r\n    invoke_custom(89500, 1, \"Mobile.setMobileAnimation\", timoId, \"AnimSort-1\")\r\n    invoke_custom(92500, 1, \"clearBubbles\", timoId)\r\n    \r\n    invoke_custom(92500, 1, \"Mobile.setMobileAnimation\", timoId, \"AnimMort\")\r\n    \r\n    invoke_custom(93500, 1, \"Mobile.setMobileVisible\", bulakId, true)\r\n    invoke_custom(93500, 1, \"Mobile.setMobileAnimation\", bulakId, \"AnimApparition\")\r\n    invoke_custom(93500, 1, \"Camera.attachCameraToMobile\", bulakId)\r\n    \r\n    -- \"HA HA HA ! ENFIN LIBRE ! TREMBLEZ MORTELS… LE SEIGNEUR DU SANG ET DES ÂMES RENAÎT À NOUVEAU !  \"\r\n    invoke_custom(93500, 1, \"bubble\", bulakId, \"quest.brume.ebene.04.28\")\r\n    invoke_custom(94500, 1, \"Mobile.setMobileAnimation\", bulakId, \"AnimSort-ExplosionTenebreuse\")\r\n    invoke_custom(98000, 1, \"clearBubbles\", bulakId)\r\n    \r\n    invoke_custom(98000, 1, \"Mobile.setMobileAnimation\", bulakId, \"AnimSort-MenaceFantome-Debut\")\r\n    \r\n    invoke_custom(99500, 1, \"Mobile.setMobilePosition\", bulakId, -1, -19, 0)\r\n    invoke_custom(99500, 1, \"Mobile.setMobileAnimation\", bulakId, \"AnimSort-MenaceFantome-Fin\")\r\n    \r\n    -- \"Je ne sais pas pourquoi, mais je savais que ça finirait de cette manière…\"\r\n    invoke_custom(098500, 1, \"bubble\", playerId, \"quest.brume.ebene.04.29\")\r\n    invoke_custom(098500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmoteMarket-HausseEpaules\")\r\n    invoke_custom(101000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(102000, 1, \"customSkip\", playerId)\nend\n\n-- CLIENT_TRIGGERED_EVENT - Fin de la cinématique - Apparition de Bulak\n-- \nfunction event_2600_23251(normalTimo)\n    Mobile.setMobileAnimation(normalTimo, \"AnimStatique-KO\")\nend\n\n-- DIALOG_EXECUTED - Bulak peut être attaqué\n-- \nfunction event_2600_23292()\n    InteractiveElement.setVisible(35135, false)\nend\n\n-- USER_GROUP_KILLED - Bulak vaincu\n-- \nfunction event_2600_23295()\n    \nend\n\n-- DIALOG_EXECUTED - Cinématique \n-- \nfunction event_2600_23296(bulakB, jenry)\n    local playerId = Context.getLeaderId()\r\n    local jenry = toLong(jenry)\r\n    local bulakB = toLong(bulakB)\r\n    \r\n    local jenryCine = createActor(117903815, -4, -28, 0, 4, 1, 6)\r\n    local bulakId = createActor(1114705732, 0, -25, 0, 4, 3, 12)\r\n    \r\n    function customSkip()\r\n    \tMobile.hideOtherPlayerMobile(false)\r\n    \tMobile.setMobileVisible(jenry, true)\r\n    \tMobile.setMobileVisible(bulakB, true)\r\n    \tMobile.setMobileAnimation(bulakB, \"AnimKO-Boucle\")\r\n    \tUI.displayWideScreenBand(true, 25, 500)\r\n    \tParticle.removeParticleSystem(apsA)\r\n    \tParticle.removeParticleSystem(apsB)\r\n    \tParticle.removeParticleSystem(apsC)\r\n    \tParticle.removeParticleSystem(apsD)\r\n    \tParticle.removeParticleSystem(apsE)\r\n    \tParticle.removeParticleSystem(apsDofus)\r\n    \tParticle.removeParticleSystem(vestigeA)\r\n    \tParticle.removeParticleSystem(vestigeB)\r\n    \tParticle.removeParticleSystem(vestigeC)\r\n    \tskipCinematic(23296)\r\n    end\r\n    \r\n    function summonAps()\r\n    \tvestigeA = Particle.addParticleSystem(800925, 2, -25, 0)\r\n    \tvestigeB = Particle.addParticleSystem(800919, -2, -25, 0)\r\n    \tvestigeC = Particle.addParticleSystem(800928, 0, -27, 0)\r\n    end\r\n    \r\n    Mobile.hideOtherPlayerMobile(true)\r\n    Mobile.setMobileVisible(jenry, false)\r\n    Mobile.setMobileVisible(bulakB, false)\r\n    Mobile.setMobileDirection(playerId, 7)\r\n    Mobile.setMobileAnimation(playerId, \"AnimStatique02\")\r\n    \r\n    startCinematicContext(1.2, bulakId, 210079)\r\n    \r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"customSkip\")\r\n    \r\n    invoke_custom(00500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimStatique02\")\r\n    \r\n    invoke_custom(00500, 1, \"Camera.setZoomSpeedFactor\", 0.01)\r\n    invoke_custom(00500, 1, \"Camera.setZoomFactor\", 1.4)\r\n    \r\n    -- \"Les Crocodailles ne devaient être qu’un moyen pour moi de m’extraire à nouveau de la Shukrute…\"\r\n    invoke_custom(01000, 1, \"bubble\", bulakId, \"quest.brume.ebene.05.01\")\r\n    invoke_custom(01000, 1, \"Mobile.setMobileAnimation\", bulakId, \"AnimSort-ExplosionTenebreuse\")\r\n    invoke_custom(06000, 1, \"clearBubbles\", bulakId)\r\n    \r\n    -- \"Leur éradication était dans l’ordre des choses : ils ne m’étaient plus d’aucune utilité…\"\r\n    invoke_custom(06500, 1, \"bubble\", bulakId, \"quest.brume.ebene.05.02\")\r\n    invoke_custom(11500, 1, \"clearBubbles\", bulakId)\r\n    \r\n    -- \"Il est délicieusement ironique que leur mort m’offre la clé pour te vaincre !\"\r\n    invoke_custom(12500, 1, \"bubble\", bulakId, \"quest.brume.ebene.05.03\")\r\n    invoke_custom(17000, 1, \"clearBubbles\", bulakId)\r\n    \r\n    invoke_custom(17000, 1, \"Mobile.setMobileDirection\", bulakId, 7)\r\n    invoke_custom(17500, 1, \"Mobile.setMobileAnimation\", bulakId, \"AnimSort-EtouffementDesOmbres\")\r\n    \r\n    invoke_custom(18500, 1, \"Camera.setCamera\", 1.4, 0, -32, 8)\r\n    \r\n    invoke_custom(18500, 1, \"Particle.removeParticleSystem\", apsA)\r\n    invoke_custom(18500, 1, \"Particle.removeParticleSystem\", apsB)\r\n    invoke_custom(18500, 1, \"Particle.removeParticleSystem\", apsC)\r\n    invoke_custom(18500, 1, \"Particle.removeParticleSystem\", apsD)\r\n    invoke_custom(18500, 1, \"Particle.removeParticleSystem\", apsE)\r\n    invoke_custom(18500, 1, \"Particle.removeParticleSystem\", apsDofus)\r\n    \r\n    -- \"[#name] ! C’est… C’est un Dofus !\"\r\n    invoke_custom(19500, 1, \"bubble\", jenryCine, \"quest.brume.ebene.05.04\")\r\n    invoke_custom(19500, 1, \"Mobile.setMobileAnimation\", jenryCine, \"AnimDial-Surprise\")\r\n    invoke_custom(23000, 1, \"clearBubbles\", jenryCine)\r\n    \r\n    invoke_custom(23000, 1, \"Camera.attachCameraToMobile\", bulakId)\r\n    invoke_custom(23000, 1, \"Camera.setZoomSpeedFactor\", 0.05)\r\n    \r\n    invoke_custom(23000, 1, \"Mobile.moveMobile\", playerId, 0, -22, 0)\r\n    \r\n    -- \"Pas cette fois, Bulak !\"\r\n    invoke_custom(23500, 1, \"bubble\", playerId, \"quest.brume.ebene.05.05\")\r\n    invoke_custom(26500, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(26500, 1, \"Mobile.setMobileDirection\", bulakId, 3)\r\n    \r\n    invoke_custom(27000, 1, \"Mobile.setMobileAnimation\", bulakId, \"AnimSort-ExplosionTenebreuse\")\r\n    invoke_custom(28000, 1, \"Particle.addParticleSystem\", -1142083475, 0, -22, 0)\r\n    \r\n    invoke_custom(29000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimHit\")\r\n    invoke_custom(29600, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimKO-Debut\")\r\n    \r\n    -- \"Trop tard !\"\r\n    invoke_custom(30000, 1, \"bubble\", bulakId, \"quest.brume.ebene.05.06\")\r\n    invoke_custom(32500, 1, \"clearBubbles\", bulakId)\r\n    \r\n    invoke_custom(32750, 1, \"Camera.setZoomFactor\", 1.8)\r\n    \r\n    -- \"Ce Dofus né de leur agonie m’appartient !\"\r\n    invoke_custom(33000, 1, \"bubble\", bulakId, \"quest.brume.ebene.05.07\")\r\n    invoke_custom(35500, 1, \"clearBubbles\", bulakId)\r\n    \r\n    -- \"Ployez… Sombrez dans le désespoir…\"\r\n    invoke_custom(36000, 1, \"bubble\", bulakId, \"quest.brume.ebene.05.08\")\r\n    invoke_custom(38500, 1, \"clearBubbles\", bulakId)\r\n    \r\n    -- \"Et mourez !\"\r\n    invoke_custom(39000, 1, \"bubble\", bulakId, \"quest.brume.ebene.05.09\")\r\n    invoke_custom(41500, 1, \"clearBubbles\", bulakId)\r\n    \r\n    invoke_custom(41750, 1, \"Camera.attachCameraToMobile\", playerId)\r\n    \r\n    -- \"**S’il a la puissance d’un Dofus, ça va devenir compliqué…\"\r\n    invoke_custom(42000, 1, \"bubble\", playerId, \"quest.brume.ebene.05.10\")\r\n    invoke_custom(45500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"**Je n’ai plus le choix, je vais devoir les utiliser.\"\r\n    invoke_custom(46000, 1, \"bubble\", playerId, \"quest.brume.ebene.05.11\")\r\n    invoke_custom(49000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(49500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimKO-SortieOK\")\r\n    invoke_custom(50500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimSort-GrandCoupdePoingdansleSol\")\r\n    \r\n    invoke_custom(50500, 1, \"Camera.attachCameraToMobile\", bulakId)\r\n    \r\n    invoke_custom(51300, 1, \"summonAps\")\r\n    \r\n    -- \"Qu’est-ce que c’est que ça…\"\r\n    invoke_custom(52500, 1, \"bubble\", bulakId, \"quest.brume.ebene.05.12\")\r\n    invoke_custom(55000, 1, \"clearBubbles\", bulakId)\r\n    \r\n    invoke_custom(52500, 1, \"Mobile.setMobileDirection\", bulakId, 1)\r\n    invoke_custom(54500, 1, \"Mobile.setMobileDirection\", bulakId, 7)\r\n    invoke_custom(56500, 1, \"Mobile.setMobileDirection\", bulakId, 5)\r\n    invoke_custom(58500, 1, \"Mobile.setMobileDirection\", bulakId, 3)\r\n    \r\n    -- \"Non… Cette énergie…\"\r\n    invoke_custom(55500, 1, \"bubble\", bulakId, \"quest.brume.ebene.05.13\")\r\n    invoke_custom(58000, 1, \"clearBubbles\", bulakId)\r\n    \r\n    -- \"C’est impossible ! MORTEL{[1*]?LE:}, COMMENT AS-TU…\"\r\n    invoke_custom(58500, 1, \"bubble\", bulakId, \"quest.brume.ebene.05.14\")\r\n    invoke_custom(58500, 1, \"Mobile.setMobileAnimation\", bulakId, \"AnimSort-AssimilationDesOmbres\")\r\n    invoke_custom(62000, 1, \"clearBubbles\", bulakId)\r\n    \r\n    -- \"Je t’avais dit que j’avais déjà eu affaire à d’autres Shushus avant toi.\"\r\n    invoke_custom(62500, 1, \"bubble\", playerId, \"quest.brume.ebene.05.15\")\r\n    invoke_custom(62500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmoteMarket-HausseEpaules\")\r\n    invoke_custom(66000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Je n’aime pas trop utiliser ça…\"\r\n    invoke_custom(66500, 1, \"bubble\", playerId, \"quest.brume.ebene.05.16\")\r\n    invoke_custom(66500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Non\")\r\n    invoke_custom(69000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(68500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimSort-PetitCoupdePoingdansleSol\")\r\n    \r\n    invoke_custom(69000, 1, \"Particle.addParticleSystem\", -1453072924, 0, -25, 0)\r\n    \r\n    -- \"Aaaargh !!!\"\r\n    invoke_custom(69500, 1, \"bubble\", bulakId, \"quest.brume.ebene.05.17\")\r\n    invoke_custom(69500, 1, \"Mobile.setMobileAnimation\", bulakId, \"AnimKO-Debut\")\r\n    invoke_custom(72000, 1, \"clearBubbles\", bulakId)\r\n    \r\n    invoke_custom(72250, 1, \"Camera.attachCameraToMobile\", jenryCine)\r\n    \r\n    -- \"On dirait que ça marche !\"\r\n    invoke_custom(72500, 1, \"bubble\", jenryCine, \"quest.brume.ebene.05.18\")\r\n    invoke_custom(72500, 1, \"Mobile.setMobileAnimation\", jenryCine, \"AnimDial-Enerve\")\r\n    invoke_custom(75000, 1, \"clearBubbles\", jenryCine)\r\n    \r\n    invoke_custom(75250, 1, \"Camera.attachCameraToMobile\", playerId)\r\n    \r\n    -- \"Évidemment, mais il y a toujours un prix à payer…\"\r\n    invoke_custom(75500, 1, \"bubble\", playerId, \"quest.brume.ebene.05.19\")\r\n    invoke_custom(75500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Calme\")\r\n    invoke_custom(78000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(78250, 1, \"Camera.attachCameraToMobile\", bulakId)\r\n    \r\n    -- \"Impossible… Je ne peux plus bouger…\"\r\n    invoke_custom(78500, 1, \"bubble\", bulakId, \"quest.brume.ebene.05.20\")\r\n    invoke_custom(82000, 1, \"clearBubbles\", bulakId)\r\n    \r\n    -- \"Bon… Qu’est-ce que je vais bien pouvoir faire de toi ?\"\r\n    invoke_custom(82500, 1, \"bubble\", playerId, \"quest.brume.ebene.05.21\")\r\n    invoke_custom(82500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(86000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(86500, 1, \"customSkip\")\nend\n\n-- CLIENT_TRIGGERED_EVENT - Fin de la cinématique - Bulak en PLS\n-- \nfunction event_2600_23297()\n    \nend\n\n-- DIALOG_EXECUTED - Bulak disparait dans l'épée\n-- \nfunction event_2600_23298(bulakB)\n    local playerId = Context.getLeaderId()\r\n    \r\n    Mobile.setMobileVisible(bulakB, false)\r\n    InteractiveElement.setAnimation(35134, \"AnimTrans_1\")\r\n    \r\n    Camera.setCamera(1.5, -7, -24, 0)\r\n    Particle.addParticleSystem(800174, -7, -24, 0)\r\n    invoke(2000, 1, \"Camera.attachCameraToMobile\", playerId)\nend\n\n-- INTERACTIVE_ELEMENT_ACTIVATION - Dialogue Crocatzin\n-- \nfunction event_2600_23299()\n    \nend\n\n-- INTERACTIVE_ELEMENT_ACTIVATION - Dialogue Dofus ébène\n-- \nfunction event_2600_23305()\n    \nend\n\n-- DIALOG_EXECUTED - Crocatzin disparait\n-- \nfunction event_2600_23308()\n    InteractiveElement.setAnimation(35134, \"AnimTrans_2\")\nend\n\n-- FIGHT_ENTER_ACTION_PHASE - Setup\n-- \nfunction event_2600_23337()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","hideMonster","hidePart","showMonster","showPart","displayDoors","event_2600_23247","event_2600_23248","event_2600_23304","event_2600_23249","event_2600_23250","customSkip","event_2600_23251","event_2600_23292","event_2600_23295","event_2600_23296","customSkip","summonAps","event_2600_23297","event_2600_23298","event_2600_23299","event_2600_23305","event_2600_23308","event_2600_23337"],"quest_calls":[],"dialogue_calls":[]},"scenario/2601.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\n-- les fonctions où on cache\r\nfunction hideMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, false)\r\nend\r\n\r\nfunction hidePart(monsterMobileId, partName)\r\n\tMobile.setPartVisible(monsterMobileId, false, partName)\r\nend\r\n\r\n-- les fonctions où on rend visible (à nouveau)\r\nfunction showMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, true)\r\nend\r\n\r\nfunction showPart(monsterMobileId, partName)\r\n\tMobile.setPartVisible(monsterMobileId, true, partName)\r\nend\r\n\r\n-- les autres fonctions\r\nfunction hideRock()\r\n\tWorld.setPictoAlpha(-1, -22, 7, 0, 1000)\r\nend\n\n-- [INITIALISATION] Serveur\n-- \nfunction event_2601_23252()\n    \nend\n\n-- ENTER_INSTANCE - On inscrit au scénario\n-- \nfunction event_2601_23253()\n    \nend\n\n-- ENTER_INSTANCE - On retire les éléments interactifs si le joueur les a déjà consultés\n-- \nfunction event_2601_23331()\n    hideRock()\nend\n\n-- INTERACTIVE_ELEMENT_ACTIVATION - Q2 - Cinématique Laura\n-- \nfunction event_2601_23254(laura)\n    hideRock()\r\n    \r\n    local playerId = Context.getLeaderId()\r\n    local initialLaura = toLong(laura)\r\n    local lauraCine = createActor(117903814, 5, -18, 0, 4, 3, 6)\r\n    \r\n    Mobile.setMobileDirection(playerId, 7)\r\n    Mobile.setMobileAnimation(playerId, \"AnimStatique02\")\r\n    \r\n    hideMonster(initialLaura)\r\n    \r\n    function customSkip()\r\n    \tMobile.hideOtherPlayerMobile(false)\r\n    \tshowMonster(initialLaura)\r\n    \tskipCinematic(23254)\r\n    end\r\n    \r\n    Mobile.hideOtherPlayerMobile(true)\r\n    \r\n    startCinematicContext(1.5, playerId)\r\n    \r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"customSkip\")\r\n    \r\n    invoke_custom(00001, 1, \"Mobile.setMobileMovementStyle\", playerId, \"WALK\", \"WALK\")\r\n    invoke_custom(00001, 1, \"Mobile.setCustomWalkStyle\", playerId, \"AnimMarche\", 600)\r\n    \r\n    invoke_custom(01000, 1, \"Camera.setMoveSpeedFactor\", 0.2)\r\n    invoke_custom(01000, 1, \"Camera.setZoomSpeedFactor\", 0.08)\r\n    \r\n    -- \"**Sésame ouvre toi !\"\r\n    invoke_custom(01000, 1, \"bubble\", playerId, \"quest.brume.pierre.02.01\")\r\n    invoke_custom(01000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Victoire\")\r\n    invoke_custom(04000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(04250, 1, \"Camera.attachCameraToMobile\", lauraCine)\r\n    \r\n    -- \"Je vais enfin savoir ce que cherchait ce squelette !\"\r\n    invoke_custom(05000, 1, \"bubble\", lauraCine, \"quest.brume.pierre.02.02\")\r\n    invoke_custom(08000, 1, \"clearBubbles\", lauraCine)\r\n    \r\n    invoke_custom(08250, 1, \"Camera.attachCameraToMobile\", playerId)\r\n    \r\n    -- \"Laura, attends ! C’est peut-être dangereux ! \"\r\n    invoke_custom(08500, 1, \"bubble\", playerId, \"quest.brume.pierre.02.03\")\r\n    invoke_custom(08500, 1, \"Mobile.setMobileDirection\", playerId, 1)\r\n    invoke_custom(08500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Calmer\")\r\n    invoke_custom(11000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Laura passe en courant et s’engouffre dans le tunnel à toute vitesse.\"\r\n    invoke_custom(11000, 1, \"fullScreen\", 1000, 5000, 1000)\r\n    invoke_custom(11000, 1, \"text\", 1000, 5000, 1000, \"quest.brume.pierre.02.03.5\")\r\n    \r\n    invoke_custom(13000, 1, \"Mobile.setMobilePosition\", lauraCine, -2, -39, 0)\r\n    invoke_custom(13000, 1, \"Mobile.setMobileDirection\", lauraCine, 1)\r\n    invoke_custom(13000, 1, \"Mobile.moveMobile\", playerId, -1, -38, 0)\r\n    \r\n    -- \"**Je te jure… Une vraie tête brûlée ! Mais je dois avouer que moi aussi ça m’intrigue.\"\r\n    invoke_custom(17500, 1, \"bubble\", playerId, \"quest.brume.pierre.02.04\")\r\n    invoke_custom(21500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"C’est quoi cette lumière ?\"\r\n    invoke_custom(22000, 1, \"bubble\", playerId, \"quest.brume.pierre.02.05\")\r\n    invoke_custom(22000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Effrayee\")\r\n    invoke_custom(24500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"C’est incroyable… \"\r\n    invoke_custom(25000, 1, \"bubble\", lauraCine, \"quest.brume.pierre.02.06\")\r\n    invoke_custom(27000, 1, \"clearBubbles\", lauraCine)\r\n    invoke_custom(24500, 1, \"Camera.setCamera\", 1.2, 0, -41, 4)\r\n    \r\n    -- \"Je m’attendais à des gisements ou à des ruines… mais pas à ça !\"\r\n    invoke_custom(27500, 1, \"bubble\", lauraCine, \"quest.brume.pierre.02.07\")\r\n    invoke_custom(30500, 1, \"clearBubbles\", lauraCine)\r\n    \r\n    -- \"Cela irradie de Wakfu ! Je comprends mieux toutes ces anomalies dans l’écosystème de l’île !\"\r\n    invoke_custom(31000, 1, \"bubble\", lauraCine, \"quest.brume.pierre.02.08\")\r\n    invoke_custom(35000, 1, \"clearBubbles\", lauraCine)\r\n    \r\n    -- \"Les cavernes dont Chester parlait dans son journal abriteraient des tuyaux dans le genre ?\"\r\n    invoke_custom(35500, 1, \"bubble\", lauraCine, \"quest.brume.pierre.02.09\")\r\n    invoke_custom(39500, 1, \"clearBubbles\", lauraCine)\r\n    \r\n    -- \"Ce tube doit bien mener quelque part… \"\r\n    invoke_custom(40000, 1, \"bubble\", playerId, \"quest.brume.pierre.02.10\")\r\n    invoke_custom(40000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(42500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Si l’on suit le flot d’énergie… Il se déverse vers l’est !\"\r\n    invoke_custom(43000, 1, \"bubble\", playerId, \"quest.brume.pierre.02.11\")\r\n    invoke_custom(44000, 1, \"Mobile.setMobileDirection\", playerId, 1)\r\n    invoke_custom(44500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Pointer\")\r\n    invoke_custom(45500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"... Oh\"\r\n    invoke_custom(46000, 1, \"bubble\", lauraCine, \"quest.brume.pierre.02.12\")\r\n    invoke_custom(48000, 1, \"clearBubbles\", lauraCine)\r\n    invoke_custom(46000, 1, \"bubble\", playerId, \"quest.brume.pierre.02.12\")\r\n    invoke_custom(48000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"… Ce n’est pas à cet endroit qu’il y a une caverne gorgée de Wakfu ?\"\r\n    invoke_custom(48500, 1, \"bubble\", playerId, \"quest.brume.pierre.02.13\")\r\n    invoke_custom(48500, 1, \"Mobile.setMobileDirection\", playerId, 5)\r\n    invoke_custom(44500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(51500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Si, précisément. J’ai vu des créatures cornues tenter d’y pénétrer, mais ce lieu est dangereux.\"\r\n    invoke_custom(52000, 1, \"bubble\", lauraCine, \"quest.brume.pierre.02.14\")\r\n    invoke_custom(56000, 1, \"clearBubbles\", lauraCine)\r\n    \r\n    -- \"Une concentration de Wakfu aussi élevée est toxique pour les êtres vivants.\"\r\n    invoke_custom(56500, 1, \"bubble\", lauraCine, \"quest.brume.pierre.02.15\")\r\n    invoke_custom(60000, 1, \"clearBubbles\", lauraCine)\r\n    \r\n    -- \"Quelque chose ne tourne pas rond sur cette île…\"\r\n    invoke_custom(60500, 1, \"bubble\", playerId, \"quest.brume.pierre.02.16\")\r\n    invoke_custom(60500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Pouce\")\r\n    invoke_custom(63000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Je pense qu’il va falloir se rendre dans cette caverne pour en avoir le cœur net !\"\r\n    invoke_custom(63500, 1, \"bubble\", playerId, \"quest.brume.pierre.02.17\")\r\n    invoke_custom(63500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Victoire\")\r\n    invoke_custom(67000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Oooh comme c’est excitant !\"\r\n    invoke_custom(67500, 1, \"bubble\", lauraCine, \"quest.brume.pierre.02.18\")\r\n    invoke_custom(70000, 1, \"clearBubbles\", lauraCine)\r\n    \r\n    -- \"Je pars devant ! On se retrouve au campement !\"\r\n    invoke_custom(70500, 1, \"bubble\", lauraCine, \"quest.brume.pierre.02.19\")\r\n    invoke_custom(73500, 1, \"clearBubbles\", lauraCine)\r\n    \r\n    invoke_custom(74000, 1, \"customSkip\")\nend\n\n-- CLIENT_TRIGGERED_EVENT - Fin de la cinématique - Notification\n-- \nfunction event_2601_23256()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","hideMonster","hidePart","showMonster","showPart","hideRock","event_2601_23252","event_2601_23253","event_2601_23331","event_2601_23254","customSkip","event_2601_23256"],"quest_calls":[],"dialogue_calls":[]},"scenario/2602.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\n-- les fonctions où on cache\r\nfunction hideMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, false)\r\nend\r\n\r\nfunction hidePart(monsterMobileId, partName)\r\n\tMobile.setPartVisible(monsterMobileId, false, partName)\r\nend\r\n\r\n-- les fonctions où on rend visible (à nouveau)\r\nfunction showMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, true)\r\nend\r\n\r\nfunction showPart(monsterMobileId, partName)\r\n\tMobile.setPartVisible(monsterMobileId, true, partName)\r\nend\n\n-- [INITIALISATION] Serveur\n-- \nfunction event_2602_23357()\n    \nend\n\n-- ENTER_INSTANCE - On cache les sbires\n-- \nfunction event_2602_23363(sbireA, sbireB, sbireC)\n    Mobile.addMobileCreationCallback(sbireA, \"hideMonster\", sbireA)\r\n    Mobile.addMobileCreationCallback(sbireB, \"hideMonster\", sbireB)\r\n    Mobile.addMobileCreationCallback(sbireC, \"hideMonster\", sbireC)\nend\n\n-- ENTER_INSTANCE - On gère les piles d'énergies\n-- \nfunction event_2602_23380()\n    \nend\n\n-- ENTER_INSTANCE - Cinématique\n-- \nfunction event_2602_23358(miloId, sbireA, sbireB, sbireC)\n    local playerId = Context.getLeaderId()\r\n    local miloCine = createActor(117903818, 0, -2, 0, 4, 3, 6)\r\n    \r\n    local miloId = toLong(miloId)\r\n    local sbireA = toLong(sbireA)\r\n    local sbireB = toLong(sbireB)\r\n    local sbireC = toLong(sbireC)\r\n    \r\n    local nox = createActor(1115005718, -1, -5, 0, 4, 3, 12)\r\n    local sbireOne = createActor(1115005715, -5, -7, 0, 4, 3, 6)\r\n    local sbireTwo = createActor(1115005716, -2, -7, 0, 4, 3, 6)\r\n    local sbireThree = createActor(1115005717, 1, -7, 0, 4, 3, 6)\r\n    \r\n    function customSkip()\r\n        Mobile.hideOtherPlayerMobile(false)\r\n        Mobile.setMobileVisible(miloId, true)\r\n        Mobile.setMobileVisible(sbireA, true)\r\n        Mobile.setMobileVisible(sbireB, true)\r\n        Mobile.setMobileVisible(sbireC, true)\r\n        skipCinematic(23358)\r\n    end\r\n    \r\n    Mobile.hideOtherPlayerMobile(true)\r\n    Mobile.setMobilePosition(playerId, 5, 9, 0)\r\n    Mobile.setMobileAnimation(miloCine, \"AnimKO-Boucle\")\r\n    Mobile.setMobileVisible(miloId, false)\r\n    Mobile.setMobileVisible(nox, false)\r\n    Mobile.setMobileVisible(sbireOne, false)\r\n    Mobile.setMobileVisible(sbireTwo, false)\r\n    Mobile.setMobileVisible(sbireThree, false)\r\n    \r\n    fullScreen(010, 1000, 1000)\r\n    \r\n    startCinematicContext(1.8, playerId)\r\n    \r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"customSkip\")\r\n    \r\n    --invoke_custom(00500, 1, \"Camera.setMoveSpeedFactor\", 0.2)\r\n    invoke_custom(00500, 1, \"Camera.setZoomSpeedFactor\", 2.1)\r\n    \r\n    invoke_custom(01000, 1, \"Mobile.moveMobile\", playerId, -2, 9, 0)\r\n    \r\n    -- \"Voilà donc le secret que renfermait cette île … \"\r\n    invoke_custom(02000, 1, \"bubble\", playerId, \"quest.brume.coeur.02.01\")\r\n    invoke_custom(05000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(05000, 1, \"Mobile.moveMobile\", playerId, -2, -2, 0, \"Mobile.setMobileDirection\", playerId, 1)\r\n    \r\n    -- \"Ah, te voilà ! Tu aurais pu m’attendre, après tout le mal que je me suis donné…\"\r\n    invoke_custom(06500, 1, \"bubble\", playerId, \"quest.brume.coeur.02.02\")\r\n    invoke_custom(10000, 1, \"clearBubbles\", playerId)\r\n    invoke_custom(09000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Colere\")\r\n    \r\n    invoke_custom(10000, 1, \"Camera.setZoomSpeedFactor\", 0.02)\r\n    \r\n    -- \"Ne t’approche pas [#name] ! C’est un piège !\"\r\n    invoke_custom(10000, 1, \"bubble\", miloCine, \"quest.brume.coeur.02.03\")\r\n    invoke_custom(12500, 1, \"clearBubbles\", miloCine)\r\n    \r\n    invoke_custom(13250, 1, \"Camera.setCamera\", 1.4, -1, -5, 0)\r\n    invoke_custom(13500, 1, \"Sound.playForcedMusic\", 290180, 50)\r\n    invoke_custom(14000, 1, \"Camera.setMoveSpeedFactor\", 0.2)\r\n    \r\n    invoke_custom(13500, 1, \"Mobile.setMobileVisible\", nox, true)\r\n    invoke_custom(13500, 1, \"Mobile.setMobileAnimation\", nox, \"AnimMouvementTeleport-Fin\")\r\n    \r\n    invoke_custom(13750, 1, \"Mobile.setMobileDirection\", playerId, 7)\r\n    invoke_custom(13750, 1, \"Mobile.setMobileDirection\", miloCine, 7)\r\n    invoke_custom(13500, 1, \"Mobile.setMobileAnimation\", miloCine, \"AnimKO-Boucle\")\r\n    \r\n    -- \"Un piège... Tout de suite les grands mots, cher archaologue !\"\r\n    invoke_custom(14000, 1, \"bubble\", nox, \"quest.brume.coeur.02.04\")\r\n    invoke_custom(14500, 1, \"Mobile.setMobileAnimation\", nox, \"AnimComp-Rire\")\r\n    invoke_custom(17500, 1, \"clearBubbles\", nox)\r\n    \r\n    -- \"Nous avions simplement une petite discussion pour tuer le temps en attendant le retour de notre ch{[1*]?ère:er} aventuri{[1*]?ère:er} …\"\r\n    invoke_custom(18000, 1, \"bubble\", nox, \"quest.brume.coeur.02.05\")\r\n    invoke_custom(18000, 1, \"Mobile.setMobileAnimation\", nox, \"AnimComp-Parler1\")\r\n    invoke_custom(22000, 1, \"clearBubbles\", nox)\r\n    \r\n    invoke_custom(22250, 1, \"Mobile.setMobileAnimation\", nox, \"AnimMouvementTeleport-Debut\")\r\n    invoke_custom(22550, 1, \"Mobile.setMobilePosition\", nox, -1, 1, 0)\r\n    invoke_custom(22550, 1, \"Mobile.setMobileDirection\", nox, 3)\r\n    invoke_custom(22550, 1, \"Mobile.setMobileAnimation\", nox, \"AnimMouvementTeleport-Fin\")\r\n    \r\n    invoke_custom(22550, 1, \"Camera.attachCameraToMobile\", nox)\r\n    \r\n    invoke_custom(23000, 1, \"Mobile.setMobileDirection\", playerId, 3)\r\n    invoke_custom(23000, 1, \"Mobile.setMobileDirection\", miloCine, 3)\r\n    invoke_custom(23200, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimStatique02-Debut\")\r\n    invoke_custom(23700, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimStatique02\")\r\n    \r\n    -- \"Après tout… Je vous dois beaucoup à tous les deux.\"\r\n    invoke_custom(22550, 1, \"Sound.playSound\", 3201115005718003, true, 50)\r\n    invoke_custom(22550, 1, \"bubble\", nox, \"quest.brume.coeur.02.06\")\r\n    invoke_custom(25500, 1, \"clearBubbles\", nox)\r\n    \r\n    -- \"Vous avez accompli bien plus en quelques jours que mes crétins de sbires en deux ans !\"\r\n    invoke_custom(26000, 1, \"bubble\", nox, \"quest.brume.coeur.02.07\")\r\n    invoke_custom(26000, 1, \"Mobile.setMobileAnimation\", nox, \"AnimComp-Parler2\")\r\n    invoke_custom(29500, 1, \"clearBubbles\", nox)\r\n    \r\n    invoke_custom(29750, 1, \"Mobile.setMobileDirection\", nox, 7)\r\n    \r\n    -- \"Je n’en ai peut-être pas l’air, mais je sais me montrer reconnaissant.\"\r\n    invoke_custom(30000, 1, \"Sound.playSound\", 3201115005718002, true, 50)\r\n    invoke_custom(30000, 1, \"bubble\", nox, \"quest.brume.coeur.02.08\")\r\n    invoke_custom(33000, 1, \"clearBubbles\", nox)\r\n    \r\n    -- \"Je vous accorde donc la possibilité de disparaître de cette île sans entraver mes projets.\"\r\n    invoke_custom(33500, 1, \"Sound.playSound\", 3201115005718001, true, 50)\r\n    invoke_custom(33500, 1, \"bubble\", nox, \"quest.brume.coeur.02.09\")\r\n    invoke_custom(37500, 1, \"clearBubbles\", nox)\r\n    \r\n    invoke_custom(37750, 1, \"Mobile.setMobileDirection\", nox, 1)\r\n    \r\n    -- \"Il serait sage d’accepter mon offre, tant que je vous tolère encore.\"\r\n    invoke_custom(38000, 1, \"bubble\", nox, \"quest.brume.coeur.02.10\")\r\n    invoke_custom(38000, 1, \"Mobile.setMobileAnimation\", nox, \"AnimComp-Rire\")\r\n    invoke_custom(41000, 1, \"clearBubbles\", nox)\r\n    \r\n    invoke_custom(41250, 1, \"Camera.attachCameraToMobile\", playerId)\r\n    \r\n    -- \"Tu es bien trop dangereux pour qu’on te laisse toute liberté sur cette île !\"\r\n    invoke_custom(41500, 1, \"bubble\", playerId, \"quest.brume.coeur.02.11\")\r\n    invoke_custom(45500, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(46000, 1, \"Mobile.setMobileAnimation\", nox, \"AnimMouvementTeleport-Debut\")\r\n    invoke_custom(46350, 1, \"Mobile.setMobilePosition\", nox, -2, -1, 0)\r\n    invoke_custom(46350, 1, \"Mobile.setMobileDirection\", nox, 7)\r\n    invoke_custom(46350, 1, \"Mobile.setMobileAnimation\", nox, \"AnimMouvementTeleport-Fin\")\r\n    \r\n    -- \"Réalises-tu véritablement ce à quoi tu t’exposes en t’opposant à moi, [#breedName] ?\"\r\n    invoke_custom(46650, 1, \"bubble\", nox, \"quest.brume.coeur.02.12\")\r\n    invoke_custom(46650, 1, \"Mobile.setMobileAnimation\", nox, \"AnimComp-Parler1\")\r\n    invoke_custom(50000, 1, \"clearBubbles\", nox)\r\n    \r\n    -- \"J’ai tenu tête à des dieux et des démons, ainsi qu’au chaos lui-même.\"\r\n    invoke_custom(50500, 1, \"bubble\", playerId, \"quest.brume.coeur.02.13\")\r\n    invoke_custom(53500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Ce ne sont pas tes petits tours temporels qui vont me faire reculer !\"\r\n    invoke_custom(54000, 1, \"bubble\", playerId, \"quest.brume.coeur.02.14\")\r\n    invoke_custom(57000, 1, \"clearB