stom(40000, 1, \"clearBubbles\", nox)\r\n    \r\n    invoke_custom(38500, 1, \"Mobile.setMobileAnimation\", nox, \"AnimSort-2\")\r\n    invoke_custom(39300, 1, \"Particle.addParticleSystem\", -1142083760, -8, -3, 0)\r\n    invoke_custom(39500, 1, \"Particle.addParticleSystem\", -1142083765, -6, -3, 0)\r\n    \r\n    -- \"Argh !\"\r\n    invoke_custom(40000, 1, \"bubble\", playerId, \"quest.brume.coeur.03.07\")\r\n    invoke_custom(42000, 1, \"clearBubbles\", playerId)\r\n    invoke_custom(40000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Dormir-Boucle\")\r\n    \r\n    invoke_custom(42250, 1, \"Camera.attachCameraToMobile\", miloCine)\r\n    \r\n    -- \"Non !!\"\r\n    invoke_custom(42500, 1, \"bubble\", miloCine, \"quest.brume.coeur.03.08\")\r\n    invoke_custom(44500, 1, \"clearBubbles\", miloCine)\r\n    \r\n    invoke_custom(44750, 1, \"Camera.attachCameraToMobile\", nox)\r\n    \r\n    invoke_custom(44750, 1, \"Mobile.setMobileAnimation\", nox, \"AnimMouvementTeleport-Debut\")\r\n    invoke_custom(45050, 1, \"Mobile.setMobilePosition\", nox, -5, -3, 0)\r\n    invoke_custom(45050, 1, \"Mobile.setMobileDirection\", nox, 5)\r\n    invoke_custom(45050, 1, \"Mobile.setMobileAnimation\", nox, \"AnimMouvementTeleport-Fin\")\r\n    \r\n    -- \"Ton obstination ne peut te conduire qu’à une fin funeste.\"\r\n    invoke_custom(45100, 1, \"Sound.playSound\", 3201115005718005, true, 50)\r\n    invoke_custom(45100, 1, \"bubble\", nox, \"quest.brume.coeur.03.09\")\r\n    invoke_custom(48000, 1, \"clearBubbles\", nox)\r\n    \r\n    -- \"Si tu te mets en travers de ma route une nouvelle fois, ton Wakfu alimentera ma grande machinerie.\"\r\n    invoke_custom(48500, 1, \"Sound.playSound\", 3201115005718006, true, 50)\r\n    invoke_custom(48500, 1, \"bubble\", nox, \"quest.brume.coeur.03.10\")\r\n    invoke_custom(52500, 1, \"clearBubbles\", nox)\r\n    \r\n    invoke_custom(53000, 1, \"Mobile.setMobileAnimation\", nox, \"AnimMouvementTeleport-Debut\")\r\n    invoke_custom(53300, 1, \"Mobile.setMobilePosition\", nox, -10, -6, 0)\r\n    invoke_custom(53300, 1, \"Mobile.setMobileDirection\", nox, 3)\r\n    invoke_custom(53300, 1, \"Mobile.setMobileAnimation\", nox, \"AnimMouvementTeleport-Fin\")\r\n    \r\n    invoke_custom(54000, 1, \"Mobile.setMobileDirection\", miloCine, 7)\r\n    \r\n    -- \"Tes talents m’ont été bien utiles archaologue. Ne gâchez pas vos vies inutilement.\"\r\n    invoke_custom(53500, 1, \"Sound.playSound\", 3201115005718006, true, 50)\r\n    invoke_custom(53500, 1, \"bubble\", nox, \"quest.brume.coeur.03.11\")\r\n    invoke_custom(58000, 1, \"clearBubbles\", nox)\r\n    \r\n    -- \"La folie qui te ronge t’a transformé en monstre !\"\r\n    invoke_custom(58500, 1, \"bubble\", miloCine, \"quest.brume.coeur.03.12\")\r\n    invoke_custom(61500, 1, \"clearBubbles\", miloCine)\r\n    \r\n    -- \"Tu as peut-être raison, mais tu n’es pas si différent de celui que j’étais autrefois…\"\r\n    invoke_custom(62000, 1, \"Sound.playSound\", 3201115005718005, true, 50)\r\n    invoke_custom(62000, 1, \"bubble\", nox, \"quest.brume.coeur.03.13\")\r\n    invoke_custom(65500, 1, \"clearBubbles\", nox)\r\n    \r\n    -- \"…\"\r\n    invoke_custom(66000, 1, \"bubble\", miloCine, \"quest.brume.coeur.03.14\")\r\n    invoke_custom(68500, 1, \"clearBubbles\", miloCine)\r\n    \r\n    -- \"Néanmoins, je ne vous demande pas de me comprendre.\"\r\n    invoke_custom(69000, 1, \"Sound.playSound\", 3201115005718006, true, 50)\r\n    invoke_custom(69000, 1, \"bubble\", nox, \"quest.brume.coeur.03.15\")\r\n    invoke_custom(72000, 1, \"clearBubbles\", nox)\r\n    \r\n    -- \"Quittez cette île et ne commettez pas l’erreur de revenir.\"\r\n    invoke_custom(72500, 1, \"Mobile.setMobileAnimation\", nox, \"AnimComp-Parler1\")\r\n    invoke_custom(72500, 1, \"bubble\", nox, \"quest.brume.coeur.03.16\")\r\n    invoke_custom(75500, 1, \"clearBubbles\", nox)\r\n    \r\n    invoke_custom(76000, 1, \"Mobile.setMobileAnimation\", nox, \"AnimMouvementTeleport-Debut\")\r\n    \r\n    invoke_custom(76500, 1, \"Camera.attachCameraToMobile\", sbireB)\r\n    \r\n    invoke_custom(77000, 1, \"Particle.addParticleSystem\", -1142083754, -3, -2, 0)\r\n    invoke_custom(77000, 1, \"Particle.addParticleSystem\", -1142083754, -3, -3, 0)\r\n    invoke_custom(77000, 1, \"Particle.addParticleSystem\", -1142083754, -3, -4, 0)\r\n    \r\n    invoke_custom(77500, 1, \"Mobile.setMobileVisible\", sbireA, false)\r\n    invoke_custom(77500, 1, \"Mobile.setMobileVisible\", sbireB, false)\r\n    invoke_custom(77500, 1, \"Mobile.setMobileVisible\", sbireC, false)\r\n    \r\n    invoke_custom(78500, 1, \"Sound.stopForcedMusic\")\r\n    invoke_custom(78500, 1, \"fullScreen\", 1000, 4000, 1000)\r\n    \r\n    invoke_custom(82500, 1, \"Camera.attachCameraToMobile\", playerId)\r\n    \r\n    invoke_custom(84000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Dormir-Fin\")\r\n    \r\n    invoke_custom(86000, 1, \"customSkip\")\nend\n\n-- CLIENT_TRIGGERED_EVENT - Cinématique finie - Notif ACH 5334 OBJ 11210\n-- \nfunction event_2602_23361()\n    \nend\n\n-- Q6 - Le joueur examine le bureau dans le laboratoire - ACH 5462 OBJ 11221\n-- \nfunction event_2602_23286()\n    local playerId = Context.getLeaderId()\r\n    \r\n    function customSkip()\r\n    \tMobile.hideOtherPlayerMobile(false)\r\n    \r\n    \tskipCinematic(23286)\r\n    end\r\n    \r\n    Mobile.hideOtherPlayerMobile(true)\r\n    \r\n    startCinematicContext(1.5, playerId)\r\n    \r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"customSkip\")\r\n    \r\n    --Ce doit être la “lettre” évoquée dans les rapports de recherche. Qilby a refusé de la lire.\r\n    invoke_custom(0500, 1, \"bubble\", playerId, \"quest.brume.coeur.04.07\")\r\n    invoke_custom(0500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(6000, 1, \"clearBubbles\", playerId)\r\n    \r\n    --On dirait qu’elle est protégée par un genre de chiffrement… Milo pourra peut-être m’aider.\r\n    invoke_custom(6500, 1, \"bubble\", playerId, \"quest.brume.coeur.04.08\")\r\n    invoke_custom(12000, 1, \"clearBubbles\", playerId)\r\n    \r\n    --Qu’est-ce que… c’est quoi cet objet ? On dirait qu’on peut l’insérer dans une machine… Je ferais mieux de le prendre au cas où.\r\n    invoke_custom(12500, 1, \"bubble\", playerId, \"quest.brume.coeur.04.04\")\r\n    invoke_custom(12500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-ChercherPiste\")\r\n    invoke_custom(18500, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(19000, 1, \"customSkip\")\nend\n\n-- Q6 - Le joueur examine le bureau dans le laboratoire - ACH 5462 OBJ 11221 - Validation\n-- \nfunction event_2602_23301()\n    \nend\n\n-- Q6 - Le joueur examine l'IE Archive 1\n-- \nfunction event_2602_23365()\n    local playerId = Context.getLeaderId()\r\n    \r\n    clearBubbles(playerId)\r\n    bubble(playerId, \"quest.brume.coeur.04.01\")\nend\n\n-- Q6 - Le joueur examine l'IE Archive 2\n-- \nfunction event_2602_23366()\n    local playerId = Context.getLeaderId()\r\n    \r\n    clearBubbles(playerId)\r\n    bubble(playerId, \"quest.brume.coeur.04.02\")\nend\n\n-- Q6 - Le joueur examine l'IE Archive 3\n-- \nfunction event_2602_23367()\n    local playerId = Context.getLeaderId()\r\n    \r\n    clearBubbles(playerId)\r\n    bubble(playerId, \"quest.brume.coeur.04.03\")\nend\n\n-- Q6 - Le joueur examine l'IE Capsule Cryo endommagée\n-- \nfunction event_2602_23368()\n    local playerId = Context.getLeaderId()\r\n    \r\n    clearBubbles(playerId)\r\n    bubble(playerId, \"quest.brume.coeur.04.05\")\nend\n\n-- Q6 - Le joueur examine l'IE Cuve de Stasis\n-- \nfunction event_2602_23369()\n    local playerId = Context.getLeaderId()\r\n    \r\n    clearBubbles(playerId)\r\n    bubble(playerId, \"quest.brume.coeur.04.06\")\nend\n\n-- FIGHT_ENTER_ACTION_PHASE - On adapte la difficulté du combat\n-- \nfunction event_2602_23322(sbireA, sbireB, sbireC)\n    Mobile.setMobileVisible(sbireA, true)\r\n    Mobile.setMobileVisible(sbireB, true)\r\n    Mobile.setMobileVisible(sbireC, true)\nend\n\n-- INTERACTIVE_ELEMENT_ACTIVATION - Dialogue Commandes\n-- \nfunction event_2602_23370()\n    \nend\n\n-- ENTER_INSTANCE - On cache Arlémia\n-- \nfunction event_2602_23620(arlemia)\n    Mobile.addMobileCreationCallback(arlemia, \"hideMonster\", arlemia)\nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","hideMonster","hidePart","showMonster","showPart","event_2602_23357","event_2602_23363","event_2602_23380","event_2602_23358","customSkip","event_2602_23359","event_2602_23360","customSkip","event_2602_23361","event_2602_23286","customSkip","event_2602_23301","event_2602_23365","event_2602_23366","event_2602_23367","event_2602_23368","event_2602_23369","event_2602_23322","event_2602_23370","event_2602_23620"],"quest_calls":[],"dialogue_calls":[]},"scenario/2603.lua":{"source":"\n\n-- Event - Infos au joueur\n-- \nfunction event_2603_23309()\n    UI.openRewardsDialog(\"brumes.collector.foret.start\")\r\n    UI.addReward(32069)\r\n    UI.addReward(32071)\nend\n\n","functions":["event_2603_23309"],"quest_calls":["UI.openRewardsDialog(\"brumes.collector.foret.start\")\r"],"dialogue_calls":[]},"scenario/2604.lua":{"source":"\n\n-- Event - Infos au joueur\n-- \nfunction event_2604_23310()\n    UI.openInfoDialog(\"moon.collector.end.title\", \"brumes.collector.foret.end\" )\nend\n\n","functions":["event_2604_23310"],"quest_calls":[],"dialogue_calls":[]},"scenario/2605.lua":{"source":"\n\n-- Event - Infos au joueur\n-- \nfunction event_2605_23311()\n    UI.openRewardsDialog(\"brumes.collector.canyon.start\")\r\n    UI.addReward(32079)\r\n    UI.addReward(32081)\nend\n\n","functions":["event_2605_23311"],"quest_calls":["UI.openRewardsDialog(\"brumes.collector.canyon.start\")\r"],"dialogue_calls":[]},"scenario/2606.lua":{"source":"\n\n-- Event - Infos au joueur\n-- \nfunction event_2606_23312()\n    UI.openInfoDialog(\"moon.collector.end.title\", \"brumes.collector.canyon.end\" )\nend\n\n","functions":["event_2606_23312"],"quest_calls":[],"dialogue_calls":[]},"scenario/2607.lua":{"source":"\n\n-- Event - Infos au joueur\n-- \nfunction event_2607_23313()\n    UI.openRewardsDialog(\"brumes.collector.savannah.start\")\r\n    UI.addReward(32089)\r\n    UI.addReward(32091)\nend\n\n","functions":["event_2607_23313"],"quest_calls":["UI.openRewardsDialog(\"brumes.collector.savannah.start\")\r"],"dialogue_calls":[]},"scenario/2608.lua":{"source":"\n\n-- Event - Infos au joueur\n-- \nfunction event_2608_23314()\n    UI.openInfoDialog(\"moon.collector.end.title\", \"brumes.collector.savannah.end\" )\nend\n\n","functions":["event_2608_23314"],"quest_calls":[],"dialogue_calls":[]},"scenario/2609.lua":{"source":"\n\n-- Event - Infos au joueur\n-- \nfunction event_2609_23315()\n    UI.openRewardsDialog(\"brumes.collector.swamps.start\")\r\n    UI.addReward(32109)\r\n    UI.addReward(32111)\nend\n\n","functions":["event_2609_23315"],"quest_calls":["UI.openRewardsDialog(\"brumes.collector.swamps.start\")\r"],"dialogue_calls":[]},"scenario/2610.lua":{"source":"\n\n-- Event - Infos au joueur\n-- \nfunction event_2610_23316()\n    UI.openInfoDialog(\"moon.collector.end.title\", \"brumes.collector.swamps.end\" )\nend\n\n","functions":["event_2610_23316"],"quest_calls":[],"dialogue_calls":[]},"scenario/2611.lua":{"source":"\n\n-- Event - Infos au joueur\n-- \nfunction event_2611_23317()\n    UI.openRewardsDialog(\"brumes.collector.desolation.start\")\r\n    UI.addReward(32099)\r\n    UI.addReward(32101)\nend\n\n","functions":["event_2611_23317"],"quest_calls":["UI.openRewardsDialog(\"brumes.collector.desolation.start\")\r"],"dialogue_calls":[]},"scenario/2612.lua":{"source":"\n\n-- Event - Infos au joueur\n-- \nfunction event_2612_23318()\n    UI.openInfoDialog(\"moon.collector.end.title\", \"brumes.collector.desolation.end\" )\nend\n\n","functions":["event_2612_23318"],"quest_calls":[],"dialogue_calls":[]},"scenario/2613.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\n-- les fonctions où on cache\r\nfunction hideMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, false)\r\nend\r\n\r\nfunction hidePart(monsterMobileId, partName)\r\n\tMobile.setPartVisible(monsterMobileId, false, partName)\r\nend\r\n\r\n-- les fonctions où on rend visible (à nouveau)\r\nfunction showMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, true)\r\nend\r\n\r\nfunction showPart(monsterMobileId, partName)\r\n\tMobile.setPartVisible(monsterMobileId, true, partName)\r\nend\n\n-- [INITIALISATION] Serveur\n-- \nfunction event_2613_23343()\n    \nend\n\n-- ENTER_INSTANCE - Cinématique\n-- \nfunction event_2613_23344()\n    -- \"kek\"\nend\n\n-- CLIENT_TRIGGERED_EVENT - Première cinématique finie - Notif ACH 5334 OBJ 11209\n-- \nfunction event_2613_23345()\n    \nend\n\n-- FIGHT_ENDED_IN_CLIENT_EVENT - Cinématique combat fini\n-- \nfunction event_2613_23346(miloId)\n    local playerId = Context.getLeaderId()\r\n    local miloId = toLong(miloId)\r\n    \r\n    function customSkip()\r\n    \tMobile.hideOtherPlayerMobile(false)\r\n    \tskipCinematic(23341)\r\n    end\r\n    \r\n    Mobile.setMobileVisible(miloId, false)\r\n    \r\n    Mobile.hideOtherPlayerMobile(true)\r\n    fullScreen(10, 1000, 1000)\r\n    \r\n    startCinematicContext(1.2, playerId)\r\n    \r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"customSkip\")\r\n    \r\n    invoke_custom(00500, 1, \"Mobile.setMobilePosition\", playerId, -45, -160, 0)\r\n    invoke_custom(00500, 1, \"Mobile.setMobileMovementStyle\", playerId, \"WALK\", \"WALK\")\r\n    invoke_custom(00500, 1, \"Mobile.setCustomWalkStyle\", playerId, \"AnimMarche\", 600)\r\n    invoke_custom(01000, 1, \"Mobile.moveMobile\", playerId, -45, -152, 0, \"Mobile.setMobileDirection\", playerId, 3)\r\n    \r\n    -- \"Bah… Où est Milo ?.\"\r\n    invoke_custom(06000, 1, \"bubble\", playerId, \"quest.brume.secret.02.01\")\r\n    invoke_custom(06500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmoteMarket-HausseEpaules\")\r\n    invoke_custom(09000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(09000, 1, \"Mobile.setMobileDirection\", playerId, 7)\r\n    invoke_custom(09500, 1, \"Mobile.setMobileDirection\", playerId, 5)\r\n    invoke_custom(10000, 1, \"Mobile.setMobileDirection\", playerId, 1)\r\n    invoke_custom(10000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Chercher\")\r\n    \r\n    -- \"Ah le dispositif s’est activé ! On dirait un genre de portail…\"\r\n    invoke_custom(10500, 1, \"bubble\", playerId, \"quest.brume.secret.02.02\")\r\n    invoke_custom(10500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmoteMarket-HausseEpaules\")\r\n    invoke_custom(13500, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(13750, 1, \"Camera.setCamera\", 1.4, -39, -153, 3)\r\n    \r\n    invoke_custom(13750, 1, \"Mobile.moveMobile\", playerId, -42, -152)\r\n    \r\n    -- \"J’imagine qu’il n’a pas résisté à l’envie de me griller la politesse…\"\r\n    invoke_custom(14000, 1, \"bubble\", playerId, \"quest.brume.secret.02.03\")\r\n    invoke_custom(16000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Non\")\r\n    invoke_custom(17500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Remarque, ça lui ressemble bien. Se soucier des autres n’a jamais été son point fort !\"\r\n    invoke_custom(18000, 1, \"bubble\", playerId, \"quest.brume.secret.02.04\")\r\n    invoke_custom(18000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Calmer\")\r\n    invoke_custom(21500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Bon eh bien, je n’ai plus qu’à le rejoindre !\"\r\n    invoke_custom(22000, 1, \"bubble\", playerId, \"quest.brume.secret.02.05\")\r\n    invoke_custom(22000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Victoire\")\r\n    invoke_custom(25000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(25500, 1, \"customSkip\")\nend\n\n-- CLIENT_TRIGGERED_EVENT - Cinématique finie - Notif ACH 5334 OBJ 11210\n-- \nfunction event_2613_23347()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","hideMonster","hidePart","showMonster","showPart","event_2613_23343","event_2613_23344","event_2613_23345","event_2613_23346","customSkip","event_2613_23347"],"quest_calls":[],"dialogue_calls":[]},"scenario/2614.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\n\n-- [INIT] Variables\n-- \nfunction event_2614_23348()\n    \nend\n\n-- [EVENT] Cinématique Arrivée - Premier dialogue Rushu\n-- \nfunction event_2614_23349(rushu)\n    local bossId = toLong(rushu)\r\n    \r\n    Mobile.setMobilePosition(bossId, -54, 8, 58)\r\n    Mobile.setMobileAnimation(bossId, \"AnimComp-1\")\r\n    \r\n    Camera.setCamera(1.0, -54, 8, 58)\nend\n\n-- [EVENT] DIALOG_EXECUTED - Validation achievement 4996 OBJ 10348 + tp out\n-- \nfunction event_2614_23350()\n    local playerId = Context.getLeaderId()\r\n    \r\n    Camera.attachCameraToMobile(playerId)\nend\n\n-- [EVENT] Cinématique Arrivée - Rushu vaincu\n-- \nfunction event_2614_23351(rushu)\n    Sound.stopForcedMusic()\r\n    Mobile.hideOtherPlayerMobile(true)\r\n    \r\n    local playerId = Context.getLeaderId()\r\n    local rushu = toLong(rushu)\r\n    Mobile.setMobileVisible(rushu, false)\r\n    \r\n    Mobile.setMobilePosition(playerId, -40, 7, -4)\r\n    Mobile.setMobileDirection(playerId, 5)\r\n    Mobile.setMobileAnimation(playerId, \"AnimStatique02\")\r\n    \r\n    function auraAps()\r\n    \tauraApsId = Particle.addParticleSystem(900039, -47, 7, -4)\r\n    \tvestigeA = Particle.addParticleSystem(800917, -49, 8, -4)\r\n    \tvestigeB = Particle.addParticleSystem(800922, -49, 6, -4)\r\n    \tvestigeC = Particle.addParticleSystem(800925, -46, 9, -4)\r\n    \tvestigeD = Particle.addParticleSystem(800919, -46, 5, -4)\r\n    \tvestigeE = Particle.addParticleSystem(800929, -44, 7, -4)\r\n    end\r\n    \r\n    function customSkip()\r\n    \tMobile.setMobileVisible(rushu, true)\r\n    \tParticle.removeParticleSystem(auraApsId)\r\n    \tParticle.removeParticleSystem(vestigeA)\r\n    \tParticle.removeParticleSystem(vestigeB)\r\n    \tParticle.removeParticleSystem(vestigeC)\r\n    \tParticle.removeParticleSystem(vestigeD)\r\n    \tParticle.removeParticleSystem(vestigeE)\r\n    \tMobile.hideOtherPlayerMobile(false)\r\n    \tskipCinematic(23351)\r\n    end\r\n    \r\n    local rushuId = createActor(1108305306, -44, 7, -4, 4, 1, 28)\r\n    \r\n    Sound.playForcedMusic(290160, 35)\r\n    \r\n    fullScreen(010, 1000, 1000)\r\n    \r\n    ---------------------------------\r\n    \r\n    startCinematicContext(1.2, rushuId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"customSkip\")\r\n    \r\n    invoke_custom(00100, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimStatique02\")\r\n    invoke_custom(01000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimStatique02\")\r\n    \r\n    invoke_custom(02000, 1, \"Camera.setZoomSpeedFactor\", 0.01)\r\n    invoke_custom(02000, 1, \"Camera.setMoveSpeedFactor\", 0.1)\r\n    \r\n    -- \"MORTEL{[1*]?LE:}...\"\r\n    invoke_custom(02000, 1, \"Sound.playSound\", 90000083, true, 40)\r\n    invoke_custom(02000, 1, \"bubble\", rushuId, \"rushu.quest.dialog.01\")\r\n    invoke_custom(04500, 1, \"clearBubbles\", rushuId)\r\n    \r\n    invoke_custom(02000, 1, \"Camera.setZoomFactor\", 1.0)\r\n    \r\n    -- \"LA FIN DE TON EXISTENCE ARRIVE.\"\r\n    invoke_custom(05000, 1, \"Mobile.setMobileAnimation\", rushuId, \"AnimComp-5\")\r\n    invoke_custom(05000, 1, \"bubble\", rushuId, \"rushu.quest.dialog.02\")\r\n    invoke_custom(08000, 1, \"clearBubbles\", rushuId)\r\n    \r\n    invoke_custom(08250, 1, \"Camera.attachCameraToMobile\", playerId)\r\n    \r\n    -- \"Je vais vérifier si les rumeurs à ton sujet sont vraies.\"\r\n    invoke_custom(08500, 1, \"bubble\", playerId, \"rushu.quest.dialog.03\")\r\n    invoke_custom(12500, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"En garde !\"\r\n    invoke_custom(13000, 1, \"bubble\", playerId, \"rushu.quest.dialog.04\")\r\n    invoke_custom(16000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(13000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimSort-GrandCoupdePoingdansleSol\")\r\n    invoke_custom(13000, 1, \"Mobile.setMobileAnimation\", rushuId, \"AnimSort-TapePied\")\r\n    invoke_custom(14700, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimStatique02\")\r\n    \r\n    invoke_custom(13500, 1, \"Effect.createCameraShakeEffect\", 200, 300, 200, 5, 100, \"BOTH\")\r\n    invoke_custom(13800, 1, \"Particle.addParticleSystem\", -1453072852, -40, 7, -4)\r\n    invoke_custom(13800, 1, \"Particle.addParticleSystem\", -1453072850, -43, 7, -4)\r\n    \r\n    invoke_custom(15000, 1, \"Mobile.setMobileAnimation\", rushuId, \"AnimSort-CaC\")\r\n    invoke_custom(15600, 1, \"Particle.addParticleSystem\", -1453072720, -44, 7, -4)\r\n    invoke_custom(15900, 1, \"Particle.addParticleSystem\", -1453072724, -41, 7, -4)\r\n    \r\n    invoke_custom(16000, 1, \"Mobile.setMobilePosition\", playerId, -36, 7, -4)\r\n    invoke_custom(16000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimIncarnam-Reception\")\r\n    invoke_custom(16700, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimStatique02-Debut\")\r\n    \r\n    invoke_custom(18200, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimCombat-Entree\")\r\n    invoke_custom(19000, 1, \"Mobile.setMobilePosition\", playerId, -47, 7, -4)\r\n    invoke_custom(19000, 1, \"Mobile.setMobileDirection\", playerId, 1)\r\n    invoke_custom(19000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimCombat-Sortie-Win\")\r\n    invoke_custom(19700, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimStatique02-Debut\")\r\n    invoke_custom(20500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimSort-EcrasementEntrelesMains\")\r\n    invoke_custom(20500, 1, \"Particle.addParticleSystem\", 10013150, -47, 7, -4)\r\n    invoke_custom(21000, 1, \"Particle.addParticleSystem\", 10013155, -44, 7, -4)\r\n    \r\n    invoke_custom(21000, 1, \"Mobile.setMobileAnimation\", rushuId, \"AnimSort-Bond\")\r\n    invoke_custom(21000, 1, \"Particle.addParticleSystem\", -1453072820, -44, 7, -4)\r\n    \r\n    invoke_custom(22500, 1, \"Particle.addParticleSystem\", -1453072821, -40, 7, -4)\r\n    invoke_custom(22500, 1, \"Mobile.setMobilePosition\", rushuId, -40, 7, -4)\r\n    invoke_custom(22500, 1, \"Mobile.setMobileDirection\", rushuId, 5)\r\n    invoke_custom(22500, 1, \"Mobile.setMobileAnimation\", rushuId, \"AnimSort-Bond-Fin\")\r\n    invoke_custom(22500, 1, \"Effect.createCameraShakeEffect\", 200, 300, 200, 5, 100, \"BOTH\")\r\n    \r\n    invoke_custom(22000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimStatique02-Debut\")\r\n    invoke_custom(22500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimStatique02\")\r\n    \r\n    invoke_custom(22850, 1, \"Camera.attachCameraToMobile\", playerId)\r\n    \r\n    -- \"TU TE DÉFENDS BIEN.\"\r\n    invoke_custom(23000, 1, \"Mobile.setMobileAnimation\", rushuId, \"AnimComp-4\")\r\n    invoke_custom(23000, 1, \"bubble\", rushuId, \"rushu.quest.dialog.05\")\r\n    invoke_custom(25500, 1, \"clearBubbles\", rushuId)\r\n    \r\n    -- \"MAIS TU FAIS FAUSSE ROUTE !\"\r\n    invoke_custom(26000, 1, \"Mobile.setMobileAnimation\", rushuId, \"AnimSort-Raillerie\")\r\n    invoke_custom(26000, 1, \"bubble\", rushuId, \"rushu.quest.dialog.06\")\r\n    invoke_custom(29000, 1, \"clearBubbles\", rushuId)\r\n    \r\n    -- \"JE SUIS TROP FORT POUR TOI !\"\r\n    invoke_custom(29500, 1, \"bubble\", rushuId, \"rushu.quest.dialog.07\")\r\n    invoke_custom(33500, 1, \"clearBubbles\", rushuId)\r\n    \r\n    invoke_custom(29500, 1, \"Camera.attachCameraToMobile\", playerId)\r\n    \r\n    invoke_custom(30000, 1, \"Mobile.setMobileAnimation\", rushuId, \"AnimSort-CoupdePoing\")\r\n    invoke_custom(30100, 1, \"Particle.addParticleSystem\", -1453072772, -40, 7, -4)\r\n    invoke_custom(30600, 1, \"Particle.addParticleSystem\", -1453072774, -46, 7, -4)\r\n    invoke_custom(30625, 1, \"Particle.addParticleSystem\", -1453072774, -47, 8, -4)\r\n    invoke_custom(30650, 1, \"Particle.addParticleSystem\", -1453072774, -48, 7, -4)\r\n    invoke_custom(30675, 1, \"Particle.addParticleSystem\", -1453072774, -47, 6, -4)\r\n    invoke_custom(30700, 1, \"Particle.addParticleSystem\", -1453072774, -48, 8, -4)\r\n    invoke_custom(30725, 1, \"Particle.addParticleSystem\", -1453072774, -46, 6, -4)\r\n    invoke_custom(30750, 1, \"Particle.addParticleSystem\", -1453072774, -48, 7, -4)\r\n    invoke_custom(30775, 1, \"Particle.addParticleSystem\", -1453072774, -46, 8, -4)\r\n    invoke_custom(30800, 1, \"Particle.addParticleSystem\", -1453072774, -48, 6, -4)\r\n    \r\n    invoke_custom(31600, 1, \"Particle.addParticleSystem\", -1453072814, -47, 7, -4)\r\n    \r\n    invoke_custom(30000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimSort-GrandClaquementdeMains\")\r\n    invoke_custom(31000, 1, \"Particle.addParticleSystem\", 1018310, -47, 7, -4)\r\n    \r\n    invoke_custom(31500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimSort-PetitCoupdePoingdansleSol\")\r\n    invoke_custom(31800, 1, \"Particle.addParticleSystem\", 1018240, -47, 7, -4)\r\n    \r\n    invoke_custom(32800, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimStatique02\")\r\n    \r\n    -- \"J'en ai assez entendu...\"\r\n    invoke_custom(33500, 1, \"bubble\", playerId, \"rushu.quest.dialog.08\")\r\n    invoke_custom(36500, 1, \"clearBubbles\", playerId)\r\n    invoke_custom(37000, 1, \"Effect.createCameraShakeEffect\", 500, 10000, 500, 5, 100, \"BOTH\")\r\n    \r\n    -- \"Je peux devenir sérieu{[1*]?se:x}, moi aussi.\"\r\n    invoke_custom(37000, 1, \"auraAps\")\r\n    invoke_custom(37000, 1, \"bubble\", playerId, \"rushu.quest.dialog.09\")\r\n    invoke_custom(40000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(40250, 1, \"Camera.setMoveSpeedFactor\", 2.1)\r\n    invoke_custom(40250, 1, \"Camera.setZoomSpeedFactor\", 2.1)\r\n    invoke_custom(40250, 1, \"Camera.attachCameraToMobile\", rushuId)\r\n    \r\n    -- \"QU'EST-CE QUE...\"\r\n    invoke_custom(40500, 1, \"Sound.playSound\", 90000081, true, 40)\r\n    invoke_custom(40500, 1, \"bubble\", rushuId, \"rushu.quest.dialog.10\")\r\n    invoke_custom(42500, 1, \"clearBubbles\", rushuId)\r\n    \r\n    invoke_custom(42750, 1, \"Camera.setZoomFactor\", 1.3)\r\n    \r\n    invoke_custom(42750, 1, \"Camera.attachCameraToMobile\", playerId)\r\n    invoke_custom(43000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimSort-Hadouken\")\r\n    invoke_custom(44000, 1, \"Camera.setCamera\", 1.3, -40, 7, 4)\r\n    \r\n    invoke_custom(44000, 1, \"Particle.addParticleSystem\", -1454062260, -40, 7, 4)\r\n    \r\n    ---------------------------------\r\n    \r\n    invoke_custom(49000, 1, \"customSkip\")\nend\n\n-- [EVENT] CLIENT_TRIGGERED_EVENT - Dialogue Rushu\n-- \nfunction event_2614_23352()\n    \nend\n\n-- [EVENT] DIALOG_EXECUTED - Validation achievement 4996 OBJ 11176 + tp out\n-- \nfunction event_2614_23353()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_2614_23348","event_2614_23349","event_2614_23350","event_2614_23351","auraAps","customSkip","event_2614_23352","event_2614_23353"],"quest_calls":[],"dialogue_calls":[]},"scenario/2615.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\n\n-- [INIT] Variables\n-- \nfunction event_2615_23354()\n    \nend\n\n-- [EVENT] ENTER_INSTANCE\n-- \nfunction event_2615_23355()\n    \nend\n\n-- [EVENT] INTERACTIVE_ELEMENT_ACTION - Dialogue narrateur\n-- \nfunction event_2615_23356()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_2615_23354","event_2615_23355","event_2615_23356"],"quest_calls":[],"dialogue_calls":[]},"scenario/2616.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\nbubbleFightInfoId = 0\r\n\r\nfunction createActorWithDefaultParams(mobileId, x, y, z, defaultDirection, availableDirection)\r\n    return createActor(Mobile.getMobileGFX(mobileId) or mobileId, x, y, z, availableDirection or 4, defaultDirection or 1, Mobile.getMobileHeight(mobileId))\r\nend\r\n\r\nfunction onFightInfoClosed()\r\n    if bubbleFightInfoId and bubbleFightInfoId ~= 0 then\r\n        bubbleFightInfoId = 0\r\n    end\r\nend\r\n\r\nfunction updateFightInfo(turnsRemaining, teamDamage, noxDamage, harebourgDamage)\r\n    local turnsRemaining = toLong(turnsRemaining)\r\n    local teamDamage = toLong(teamDamage)\r\n    local noxDamage = toLong(noxDamage)\r\n    local harebourgDamage = toLong(harebourgDamage)\r\n\r\n    if not bubbleFightInfoId or bubbleFightInfoId == 0 then\r\n        bubbleFightInfoId = BubbleText.prepareInteractiveBubbleFloating(\r\n                \"NORTH_WEST\", 0, 0, false, 2147483647, true,\r\n                \"interactiveBubbleDialog5\", 30000, 25000, \"onFightInfoClosed\"\r\n        )\r\n    end\r\n\r\n    BubbleText.setText(bubbleFightInfoId, \"kickstarter2025.fight.player.infos\", teamDamage, turnsRemaining, noxDamage, harebourgDamage)\r\n    BubbleText.show(bubbleFightInfoId)\r\nend\r\n\r\nfunction hideClockmen(harebourg, nox)\r\n    Mobile.setMobileVisible(harebourg, false)\r\n    Mobile.setMobileVisible(nox, false)\r\nend\r\n\r\nfunction showClockmen(harebourg, nox)\r\n    Mobile.setMobileVisible(harebourg, true)\r\n    Mobile.setMobileVisible(nox, true)\r\nend\r\n\r\nfunction setClockVisibility(isVisible)\r\n    local coordinates = {\r\n        { 5, 1 }, { 7, 2 }, { 9, 4 }, { 10, 6 }, { 9, 8 }, { 7, 10 },\r\n        { 5, 11 }, { 3, 10 }, { 1, 8 }, { 0, 6 }, { 1, 4 }, { 3, 2 }\r\n    }\r\n\r\n    for _, coord in ipairs(coordinates) do\r\n        World.setPictoAlpha(coord[1], coord[2], 40, isVisible and 1 or 0, 1000)\r\n    end\r\nend\r\n\r\nfunction firstCinematicEnd(nox, harebourg) -- Fonction custom pour pouvoir l'envoyer à tous les joueurs quand l'un d'entre eux skip\r\n    showClockmen(nox, harebourg)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n    setClockVisibility(true)\r\nend\n\n-- [INIT] Variables Globales\n-- \nfunction event_2616_23381()\n    \nend\n\n-- [INIT] Inscription du joueur + Variables Locales\n-- \nfunction event_2616_23382()\n    \nend\n\n-- CHARACTER_ENTER_INSTANCE_EVENT - Cinématique d'arrivée\n-- \nfunction event_2616_23383(nox, harebourg)\n    hideClockmen(nox, harebourg)\r\n    setClockVisibility(false)\r\n    \r\n    local playerId = Context.getLeaderId()\r\n    local noxCine = createActorWithDefaultParams(nox, 4, 3, 40, 1)\r\n    local harebourgCine = createActorWithDefaultParams(harebourg, 6, 3, 40, 5)\r\n    \r\n    Mobile.setMobileVisible(playerId, false)\r\n    \r\n    function customSkip()\r\n        skipCinematic(23383)\r\n    end\r\n    \r\n    Mobile.hideOtherPlayerMobile(true)\r\n    \r\n    startCinematicContext(1, playerId)\r\n    Camera.attachCameraToMobile(harebourgCine)\r\n    \r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"customSkip\")\r\n    \r\n    --Je ne comprends pas, Nox. Comment pouvons-nous nous retrouver dans la même temporalité au sommet de ma tour ?\r\n    invoke_custom(00000, 1, \"bubble\", harebourgCine, \"kickstarter2025.00.00\")\r\n    invoke_custom(8000, 1, \"clearBubbles\", harebourgCine)\r\n    \r\n    --C’est, impossible !!! Où sont mes créations, où est l’Éliacube ?\r\n    invoke_custom(8000, 1, \"bubble\", noxCine, \"kickstarter2025.00.01\")\r\n    invoke_custom(13000, 1, \"clearBubbles\", noxCine)\r\n    \r\n    --Je ne sais pas, je n’y comprends rien du tout !!!\r\n    invoke_custom(13000, 1, \"bubble\", harebourgCine, \"kickstarter2025.00.02\")\r\n    invoke_custom(17500, 1, \"clearBubbles\", harebourgCine)\r\n    \r\n    --Qui sait quelle autre entité aurait pu être transportée avec nous ?\r\n    invoke_custom(17500, 1, \"bubble\", harebourgCine, \"kickstarter2025.00.03\")\r\n    invoke_custom(22500, 1, \"clearBubbles\", harebourgCine)\r\n    \r\n    --Tu as raison, prudence est mère de sûreté. Profitons de ce moment calme pour élaborer un plan.\r\n    invoke_custom(22500, 1, \"bubble\", noxCine, \"kickstarter2025.00.04\")\r\n    invoke_custom(29500, 1, \"clearBubbles\", noxCine)\r\n    \r\n    invoke_custom(29500, 1, \"Mobile.setMobileVisible\", playerId, true)\r\n    invoke_custom(29501, 1, \"Mobile.setMobileDirection\", playerId, 3)\r\n    invoke_custom(29501, 1, \"Camera.attachCameraToMobile\", playerId)\r\n    invoke_custom(29502, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimIncarnam-Chute-Fin\")\r\n    invoke_custom(30000, 1, \"Mobile.setMobileDirection\", harebourgCine, 3)\r\n    invoke_custom(30500, 1, \"Mobile.setMobileDirection\", noxCine, 3)\r\n    \r\n    --Outch… Qu’est-ce qu’il vient de se passer ?\r\n    invoke_custom(31500, 1, \"bubble\", playerId, \"kickstarter2025.00.05\")\r\n    invoke_custom(31500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Defaite\")\r\n    invoke_custom(35500, 1, \"clearBubbles\", playerId)\r\n    \r\n    --J’ai mal au crâne…\r\n    invoke_custom(35500, 1, \"bubble\", playerId, \"kickstarter2025.00.06\")\r\n    invoke_custom(35500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Defaite\")\r\n    invoke_custom(37500, 1, \"clearBubbles\", playerId)\r\n    \r\n    --Cet endroit me dit quelque chose… J’ai l’impression qu’une atmosphère étrange s’en dégage.\r\n    invoke_custom(37500, 1, \"bubble\", playerId, \"kickstarter2025.00.07\")\r\n    invoke_custom(37500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Chercher\")\r\n    invoke_custom(40000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Pointer\")\r\n    invoke_custom(44000, 1, \"clearBubbles\", playerId)\r\n    \r\n    --Ça ne me dit rien qui vaille. Il faut que j’aille trouver le zaap le plus proche pour avoir un plan de sûreté si jamais les choses se passent mal.\r\n    invoke_custom(44000, 1, \"bubble\", playerId, \"kickstarter2025.00.08\")\r\n    invoke_custom(31500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(56500, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(47000, 1, \"Mobile.setMobileAnimation\", harebourgCine, \"AnimMouvementTeleport-Debut\")\r\n    invoke_custom(47000, 1, \"Mobile.setMobileAnimation\", noxCine, \"AnimTP-Debut\")\r\n    invoke_custom(47500, 1, \"Mobile.setMobileVisible\", harebourgCine, false)\r\n    invoke_custom(47500, 1, \"Mobile.setMobileVisible\", noxCine, false)\r\n    \r\n    invoke_custom(47500, 1, \"Mobile.setMobilePosition\", harebourgCine, 6, 7, 42)\r\n    invoke_custom(47500, 1, \"Mobile.setMobilePosition\", noxCine, 4, 7, 42)\r\n    \r\n    invoke_custom(48000, 1, \"Mobile.setMobileVisible\", harebourgCine, true)\r\n    invoke_custom(48000, 1, \"Mobile.setMobileVisible\", noxCine, true)\r\n    invoke_custom(48000, 1, \"Mobile.setMobileAnimation\", harebourgCine, \"AnimMouvementTeleport-Fin\")\r\n    invoke_custom(48000, 1, \"Mobile.setMobileAnimation\", noxCine, \"AnimTP-Fin\")\r\n    \r\n    invoke_custom(55000, 1, \"Mobile.setMobileDirection\", playerId, 7)\r\n    invoke_custom(55000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Effrayee\")\r\n    \r\n    --Toi !!!\r\n    invoke_custom(56500, 1, \"bubble\", playerId, \"kickstarter2025.00.09\")\r\n    invoke_custom(56500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Pointer\")\r\n    invoke_custom(56500, 1, \"bubble\", harebourgCine, \"kickstarter2025.00.09\")\r\n    invoke_custom(58500, 1, \"clearBubbles\", playerId)\r\n    invoke_custom(58500, 1, \"clearBubbles\", harebourgCine)\r\n    \r\n    --Vous vous connaissez ?\r\n    invoke_custom(58500, 1, \"bubble\", noxCine, \"kickstarter2025.00.10\")\r\n    invoke_custom(60500, 1, \"clearBubbles\", noxCine)\r\n    \r\n    --On s’est déjà croisés par le passé, il s’est toujours mis en travers de ma route.\r\n    invoke_custom(60500, 1, \"bubble\", playerId, \"kickstarter2025.00.11\")\r\n    invoke_custom(60500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Pointer\")\r\n    invoke_custom(60500, 1, \"bubble\", harebourgCine, \"kickstarter2025.00.11.5\")\r\n    invoke_custom(68500, 1, \"clearBubbles\", playerId)\r\n    invoke_custom(68500, 1, \"clearBubbles\", harebourgCine)\r\n    \r\n    --Eh !!!\r\n    invoke_custom(68500, 1, \"bubble\", playerId, \"kickstarter2025.00.12\")\r\n    invoke_custom(68500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Colere\")\r\n    invoke_custom(68500, 1, \"bubble\", harebourgCine, \"kickstarter2025.00.12\")\r\n    invoke_custom(70500, 1, \"clearBubbles\", playerId)\r\n    invoke_custom(70500, 1, \"clearBubbles\", harebourgCine)\r\n    \r\n    --Je ne comprends pas tout.\r\n    invoke_custom(70500, 1, \"bubble\", noxCine, \"kickstarter2025.00.13\")\r\n    invoke_custom(73000, 1, \"clearBubbles\", noxCine)\r\n    \r\n    --Il faut me croire, nous devons nous débarrasser d{[1*]?’elle:e lui}. Il va nous empêcher de repartir ici vivants !\r\n    invoke_custom(73000, 1, \"bubble\", playerId, \"kickstarter2025.00.14\")\r\n    invoke_custom(73000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Pointer\")\r\n    invoke_custom(73000, 1, \"bubble\", harebourgCine, \"kickstarter2025.00.14.5\")\r\n    invoke_custom(85000, 1, \"clearBubbles\", playerId)\r\n    invoke_custom(85000, 1, \"clearBubbles\", harebourgCine)\r\n    \r\n    --Prête-moi main forte, confrère Xélor. Devenons ensemble les souverains de cette perturbation temporelle.\r\n    invoke_custom(85000, 1, \"bubble\", harebourgCine, \"kickstarter2025.00.15\")\r\n    invoke_custom(85000, 1, \"Mobile.setMobileDirection\", harebourgCine, 5)\r\n    invoke_custom(91500, 1, \"clearBubbles\", harebourgCine)\r\n    \r\n    --Tu me sembles d’une toute autre trempe que cette demi-portion. Montrons-lui de quel bois se chauffent les grands Xélors.\r\n    invoke_custom(91500, 1, \"bubble\", noxCine, \"kickstarter2025.00.16\")\r\n    invoke_custom(91500, 1, \"Mobile.setMobileDirection\", noxCine, 1)\r\n    invoke_custom(101000, 1, \"clearBubbles\", noxCine)\r\n    \r\n    --Vous ne me laissez pas le choix, je vais mettre un terme définitif à vos plans mutuels une bonne fois pour toutes.\r\n    invoke_custom(101000, 1, \"bubble\", playerId, \"kickstarter2025.00.17\")\r\n    invoke_custom(101000, 1, \"Mobile.setMobileDirection\", harebourgCine, 3)\r\n    invoke_custom(101000, 1, \"Mobile.setMobileDirection\", noxCine, 3)\r\n    invoke_custom(101000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Colere\")\r\n    invoke_custom(151000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Pointer\")\r\n    invoke_custom(112500, 1, \"clearBubbles\", playerId)\r\n    \r\n    --Approche !!!\r\n    invoke_custom(112500, 1, \"bubble\", harebourgCine, \"kickstarter2025.00.18\")\r\n    invoke_custom(112500, 1, \"bubble\", noxCine, \"kickstarter2025.00.18\")\r\n    invoke_custom(114500, 1, \"clearBubbles\", harebourgCine)\r\n    invoke_custom(114500, 1, \"clearBubbles\", noxCine)\r\n    \r\n    invoke_custom(115500, 1, \"customSkip\")\nend\n\n-- CLIENT_TRIGGERED_EVENT - Validation cinématique + lancement du combat\n-- \nfunction event_2616_23384(nox, harebourg)\n    firstCinematicEnd(nox, harebourg)\r\n    \r\n    skipCinematic()\nend\n\n-- FIGHT_STARTED - On pose les zones\n-- \nfunction event_2616_23388()\n    \nend\n\n-- EFFECT_EXECUTION - Mise à jour UI infos de combat (score) - Nox\n-- \nfunction event_2616_23389()\n    \nend\n\n-- EFFECT_EXECUTION - Mise à jour UI infos de combat (score) - Harebourg\n-- \nfunction event_2616_23394()\n    \nend\n\n-- EFFECT_EXECUTION - Mise à jour UI infos de combat (score) - Total\n-- \nfunction event_2616_23395(turnsRemaining, teamDamage, noxDamage, harebourgDamage)\n    updateFightInfo(turnsRemaining, teamDamage, noxDamage, harebourgDamage)\nend\n\n-- EFFECT_EXECUTION - Mise à jour UI infos de combat (tour)\n-- \nfunction event_2616_23390(turnsRemaining, teamDamage, noxDamage, harebourgDamage)\n    updateFightInfo(turnsRemaining, teamDamage, noxDamage, harebourgDamage)\nend\n\n-- USER_GROUP_KILLED - Enregistrement au classement\n-- \nfunction event_2616_23391()\n    \nend\n\n-- FIGHT_ENDED_IN_CLIENT_EVENT - Cinématique de fin (Harebourg a plus de dommages) - ACH 5486 OBJ 11368\n-- \nfunction event_2616_23396()\n    local playerId = Context.getLeaderId()\r\n    local noxCine = createActorWithDefaultParams(1115005718, 4, 8, 40, 1)\r\n    local harebourgCine = createActorWithDefaultParams(104702383, 6, 8, 40, 5)\r\n    \r\n    function customSkip()\r\n        skipCinematic(23396)\r\n    end\r\n    \r\n    Mobile.setMobileDirection(playerId, 7)\r\n    Mobile.setMobileAnimation(playerId, \"AnimStatique02\")\r\n    \r\n    startCinematicContext(1.0, playerId)\r\n    \r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"customSkip\")\r\n    \r\n    --ARGH…\r\n    invoke_custom(000000, 1, \"bubble\", harebourgCine, \"kickstarter2025.01.00\")\r\n    invoke_custom(001000, 1, \"Mobile.setMobileAnimation\", harebourgCine, \"AnimHit\")\r\n    invoke_custom(002000, 1, \"clearBubbles\", harebourgCine)\r\n    \r\n    --Je savais que je ne pourrais jamais te faire confiance, Harebourg. On va voir comment tu t’en sors sans moi, maintenant.\r\n    invoke_custom(002000, 1, \"bubble\", noxCine, \"kickstarter2025.01.01\")\r\n    invoke_custom(002000, 1, \"Mobile.setMobileAnimation\", noxCine, \"\")\r\n    invoke_custom(012500, 1, \"clearBubbles\", noxCine)\r\n    \r\n    --Nox, reviens ! Nox…\r\n    invoke_custom(012500, 1, \"bubble\", harebourgCine, \"kickstarter2025.01.02\")\r\n    invoke_custom(014500, 1, \"clearBubbles\", harebourgCine)\r\n    invoke_custom(014500, 1, \"Mobile.setMobileAnimation\", noxCine, \"AnimTP-Debut\")\r\n    invoke_custom(015500, 1, \"Mobile.setMobileVisible\", noxCine, false)\r\n    \r\n    invoke_custom(016000, 1, \"customSkip\")\nend\n\n-- FIGHT_ENDED_IN_CLIENT_EVENT - Cinématique de fin (Nox a plus de dommages) - ACH 5486 OBJ 11367\n-- \nfunction event_2616_23397()\n    local playerId = Context.getLeaderId()\r\n    local noxCine = createActorWithDefaultParams(1115005718, 4, 8, 40, 1)\r\n    local harebourgCine = createActorWithDefaultParams(104702383, 6, 8, 40, 5)\r\n    \r\n    function customSkip()\r\n        skipCinematic(23396)\r\n    end\r\n    \r\n    Mobile.setMobileDirection(playerId, 7)\r\n    Mobile.setMobileAnimation(playerId, \"AnimStatique02\")\r\n    \r\n    startCinematicContext(1.0, playerId)\r\n    \r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"customSkip\")\r\n    \r\n    --ARGH…\r\n    invoke_custom(000000, 1, \"bubble\", noxCine, \"kickstarter2025.02.00\")\r\n    invoke_custom(002000, 1, \"clearBubbles\", noxCine)\r\n    \r\n    --Tu me déçois, Nox. Penser qu’un Xélor tel que toi finisse en sac de frappe pour aventuri{[1*]?ère:er} minable…\r\n    invoke_custom(002000, 1, \"bubble\", harebourgCine, \"kickstarter2025.02.01\")\r\n    invoke_custom(9500, 1, \"clearBubbles\", harebourgCine)\r\n    \r\n    --Je vais récupérer tes projets et les mener à terme. Les douziens entendront parler de moi comme du plus grand Xélor de tous les temps puisque tu n’en es visiblement pas digne.\r\n    invoke_custom(9500, 1, \"bubble\", harebourgCine, \"kickstarter2025.02.02\")\r\n    invoke_custom(22000, 1, \"clearBubbles\", harebourgCine)\r\n    \r\n    --Vermine ! Tu ne perds rien pour attendre, dès que j’aurai remonté dans le temps, je, je…\r\n    invoke_custom(22000, 1, \"bubble\", noxCine, \"kickstarter2025.02.03\")\r\n    invoke_custom(25000, 1, \"Mobile.setMobileDirection\", harebourgCine, 3)\r\n    invoke_custom(25000, 1, \"Mobile.setMobileAnimation\", harebourgCine, \"AnimDisparition\")\r\n    invoke_custom(27000, 1, \"Mobile.setMobileVisible\", harebourgCine, false)\r\n    invoke_custom(27000, 1, \"Mobile.setMobileAnimation\", noxCine, \"AnimMort\")\r\n    invoke_custom(27500, 1, \"clearBubbles\", noxCine)\r\n    \r\n    invoke_custom(28000, 1, \"customSkip\")\nend\n\n-- FIGHT_ENDED_IN_CLIENT_EVENT - On check les dommages pour ACH 5486 OBJ 11369\n-- \nfunction event_2616_23498()\n    \nend\n\n-- CLIENT_TRIGGERED_EVENT - On affiche le résultat du combat\n-- \nfunction event_2616_23398(teamDamage)\n    local teamDamage = toString(teamDamage)\r\n    \r\n    Mobile.hideOtherPlayerMobile(false)\r\n    \r\n    UI.setWidgetEnabled(\"fightResultDialog\", \"rootContainer\", true)\r\n    UI.setWidgetVisibility(\"fightResultDialog\", \"rootContainer\", true)\r\n    \r\n    local text = Event.getKeyTranslation(\"fight.score.ogrest\", teamDamage)\r\n    UI.setPropertyStringValue(\"fight.score.ogrest\", text)\r\n    UI.writeLocalisedInChat(\"ogrest.fight.team.score\", teamDamage)\r\n    \r\n    UI.removeUnremovableDialog(\"fightResultDialog\")\r\n    \r\n    UI.addDialogUnloadedListener(\"fightResultDialog\", \"UI.removeProperty\", \"fight.score.ogrest\")\nend\n\n-- FIGHT_ENDED - On remet le TP\n-- \nfunction event_2616_23393()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","createActorWithDefaultParams","onFightInfoClosed","updateFightInfo","hideClockmen","showClockmen","setClockVisibility","firstCinematicEnd","event_2616_23381","event_2616_23382","event_2616_23383","customSkip","event_2616_23384","event_2616_23388","event_2616_23389","event_2616_23394","event_2616_23395","event_2616_23390","event_2616_23391","event_2616_23396","customSkip","event_2616_23397","customSkip","event_2616_23498","event_2616_23398","event_2616_23393"],"quest_calls":[],"dialogue_calls":[]},"scenario/2617.lua":{"source":"\n\n-- Enregistrement des Evènements : Fin\n-- \nfunction event_2617_23399()\n    \nend\n\n-- Enregistrement des Evènements Cyclique : Spawn de monstres\n-- Toutes les X min, on spawn les groupes de monstres\nfunction event_2617_23400()\n    \nend\n\n-- Setup des IE (sécurité)\n-- \nfunction event_2617_23401()\n    \nend\n\n-- On affiche la faille Harebourg X Nox\n-- \nfunction event_2617_23427()\n    \nend\n\n-- On retire la faille Harebourg X Nox\n-- \nfunction event_2617_23428()\n    \nend\n\n","functions":["e