_23492"],"quest_calls":[],"dialogue_calls":[]},"scenario/2662.lua":{"source":"\n\n-- Event - Infos au joueur\n-- \nfunction event_2662_23493()\n    UI.writeLocalisedInChat(\"kickstarter2025.mekarbac.notif\")\nend\n\n","functions":["event_2662_23493"],"quest_calls":[],"dialogue_calls":[]},"scenario/2663.lua":{"source":"\n\n-- Enregistrement des Evènements Cyclique : Spawn de monstres\n-- Toutes les X min, on spawn les groupes de monstres\nfunction event_2663_23494()\n    \nend\n\n","functions":["event_2663_23494"],"quest_calls":[],"dialogue_calls":[]},"scenario/2664.lua":{"source":"\n\n-- [INIT] Spawn aléatoire\n-- \nfunction event_2664_23495()\n    \nend\n\n-- [INIT] Spawn des monstres\n-- \nfunction event_2664_23496()\n    \nend\n\n","functions":["event_2664_23495","event_2664_23496"],"quest_calls":[],"dialogue_calls":[]},"scenario/2665.lua":{"source":"\n\n-- Event - Infos au joueur\n-- \nfunction event_2665_23497()\n    UI.writeLocalisedInChat(\"kickstarter2025.mekarbac.notif\")\nend\n\n","functions":["event_2665_23497"],"quest_calls":[],"dialogue_calls":[]},"scenario/2666.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\nInteractiveElement.setAnimation(35263, \"AnimStatique_2\")\r\n\r\n---- Fonctions score\r\n\r\nbubbleFightInfoId = 0\r\n\r\nfunction closeFightInfo()\r\n\tif (bubbleFightInfoId ~= nil and bubbleFightInfoId ~= 0) then BubbleText.close(bubbleFightInfoId) end\r\nend\r\n\r\nfunction onFightInfoClosed()\r\n\tif (bubbleFightInfoId ~= nil and bubbleFightInfoId ~= 0) then bubbleFightInfoId = 0 end\r\nend\r\n\r\nfunction updateFightInfo(turnLeft, teamDamage, phase, weaponA, weaponB, weaponC, weaponD, weaponALvl, weaponBLvl, weaponCLvl, weaponDLvl, wakfuCharge, wakfuChargeVariation, forceDisplayUI)\r\n\tlocal turnLeft = toLong(turnLeft)\r\n\tlocal teamDamage = toLong(teamDamage)\r\n\tlocal phase = toLong(phase)\r\n\tlocal weaponA = toLong(weaponA)\r\n\tlocal weaponB = toLong(weaponB)\r\n\tlocal weaponC = toLong(weaponC)\r\n\tlocal weaponD = toLong(weaponD)\r\n\tlocal weaponALvl = toLong(weaponALvl)\r\n\tlocal weaponBLvl = toLong(weaponBLvl)\r\n\tlocal weaponCLvl = toLong(weaponCLvl)\r\n\tlocal weaponDLvl = toLong(weaponDLvl)\r\n\tlocal activeWeapon = 0\r\n\tlocal nextWeapon = 0\r\n\tlocal activeWeaponLvl = 0\r\n\tlocal activeWeaponLvlText = \"I\"\r\n\tlocal wakfuCharge = toLong(wakfuCharge)\r\n\tlocal wakfuChargeVariation = toLong(wakfuChargeVariation)\r\n\r\n-- Arme suivante\r\n\r\n\tif ((weaponA == 1) or (weaponB == 1) or (weaponC == 1) or (weaponD == 1))\r\n\t    then nextWeapon = 1\r\n        else nextWeapon = 0\r\n    end\r\n\r\n-- Arme active \r\n\r\n\tif ((weaponA == 2) or (weaponB == 2) or (weaponC == 2) or (weaponD == 2))\r\n    \tthen activeWeapon = 1\r\n        else activeWeapon = 0\r\n    end\r\n\r\n-- Niveau de l'arme active    \r\n\r\n  if (weaponA == 2) then\r\n  \tactiveWeaponLvl = weaponALvl\r\n  \telseif (weaponB == 2) then\r\n  \tactiveWeaponLvl = weaponBLvl\r\n  \telseif (weaponC == 2) then\r\n  \tactiveWeaponLvl = weaponCLvl\r\n  \telseif (weaponD == 2) then\r\n  \tactiveWeaponLvl = weaponDLvl\r\n\tend\r\n\t\r\n-- Affichage du niveau de l'arme active\t\r\n\r\n\tif (activeWeaponLvl == 1) then\r\n\t\tactiveWeaponLvlText = \"I\"\r\n\t\telseif (activeWeaponLvl == 2) then\r\n\t\tactiveWeaponLvlText = \"II\"\r\n\t\telseif (activeWeaponLvl == 3) then\r\n\t\tactiveWeaponLvlText = \"III\"\r\n\t\telseif (activeWeaponLvl == 4) then\r\n\t\tactiveWeaponLvlText = \"IV\"\r\n\t\telseif (activeWeaponLvl == 5) then\r\n\t\tactiveWeaponLvlText = \"V\"\r\n\t\telseif (activeWeaponLvl == 6) then\r\n\t\tactiveWeaponLvlText = \"VI\"\r\n\tend\r\n\t\r\n\tif (bubbleFightInfoId == 0) then\r\n\t\tbubbleFightInfoId = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_WEST\", 0, -60, false, 2147483647, true, \"interactiveBubbleDialog5\", 30000, 25000, \"onFightInfoClosed\")\r\n\tend\r\n\r\n\tBubbleText.setText(bubbleFightInfoId, \"nox.fight.player.infos\", turnLeft, teamDamage, phase, weaponA, weaponB, weaponC, weaponD, activeWeapon, nextWeapon, activeWeaponLvlText, wakfuCharge, wakfuChargeVariation)\r\n\r\n\tif (forceDisplayUI) then BubbleText.show(bubbleFightInfoId) end\r\nend\r\n\r\nfunction displayPhaseAps(phase)\r\n\tif (aps ~= nil) then\r\n\t\tParticle.removeParticleSystem(aps)\r\n\tend\r\n\t\t\r\n\tif (phase >= 2) then\r\n\t\taps = Particle.addParticleSystem(7504013, 0, -21, 22)\r\n\telse\r\n\t\taps = Particle.addParticleSystem(7504012, 0, -21, 22)\r\n\tend\t\r\nend\n\n-- Variables globales\n-- \nfunction event_2666_23501()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2666_23502(noxId, doorOpened, phase)\n    local doorOpened = toLong(doorOpened)\r\n    local phase = toLong(phase)\r\n    \r\n    InteractiveElement.setAnimation(35263, \"AnimStatique_2\")\r\n    \r\n    if doorOpened == 0 then\r\n    \tMobile.setMobileVisible(noxId, false)\r\n    \telse\r\n    end\r\n    \r\n    displayPhaseAps(phase)\nend\n\n-- GENERIC_ACTIVABLE_ACTION - Activation de l'Eliacube\n-- \nfunction event_2666_23503(triggererId, noxId)\n    local playerId = toLong(triggererId)\r\n    local noxId = toLong(noxId)\r\n    local nox = createActor(1115005718, -5, -14, 0, 4, 1, 8)\r\n        \r\n    function customSkip()\r\n     Mobile.setMobilePosition(playerId, 0, -14, 0)\r\n     Mobile.setMobileVisible(noxId, true)\r\n     skipCinematic(23503)\r\n    end\r\n    \r\n    Mobile.setMobileVisible(noxId, false)\r\n    Mobile.setMobileVisible(nox, false)\r\n    Mobile.setMobileAnimationSuffix(nox, \"-1\")\r\n        \r\n    startCinematicContext(1.2, playerId, 23503)\r\n        \r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"customSkip\")\r\n    \r\n    invoke_custom(0001, 1, \"Mobile.setMobilePosition\", playerId, -2, -14, 0)\r\n    invoke_custom(0001, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Chatouille\")\r\n    invoke_custom(1500, 1, \"setWorldParticleCell\", 801084, -2, -15, 0)\r\n    invoke_custom(1500, 1, \"Camera.setCamera\", 2, -2, -15, 8)\r\n    invoke_custom(3000, 1, \"Effect.createCameraShakeEffect\", 100, 400, 100, 3, 100, \"BOTH\")\r\n    invoke_custom(3200, 1, \"clearWorldParticles\")\r\n    invoke_custom(3201, 1, \"setWorldParticleCell\", 801085,  -2, -15, 0)\r\n    invoke_custom(3500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(3500, 1, \"InteractiveElement.setAnimation\", 35263, \"AnimStatique_1\")\r\n    invoke_custom(4500, 1, \"clearWorldParticles\")\r\n    \r\n    -- \"Fascinant, n'est-ce pas ?\"\r\n    invoke_custom(4500, 1, \"Mobile.setMobileVisible\", nox, true)\r\n    invoke_custom(4500, 1, \"Mobile.setMobileAnimation\", nox, \"AnimTP-Fin\")\r\n    invoke_custom(4999, 1, \"Camera.setZoomSpeedFactor\", 0.2)\r\n    invoke_custom(5000, 1, \"Camera.setZoomFactor\", 1.6)\r\n    invoke_custom(5500, 1, \"Mobile.setMobileAnimation\", nox, \"AnimComp-Parler2\")\r\n    invoke_custom(6500, 1, \"bubble\", nox, \"nox.fight.start.dialog.01\")\r\n    invoke_custom(6700, 1, \"Mobile.setMobilePosition\", playerId, 0, -14, 0)\r\n    invoke_custom(6700, 1, \"Mobile.setMobileDirection\", playerId, 5)\r\n    invoke_custom(6700, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimIncarnam-Reception\")\r\n    invoke_custom(7400, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimStatique02-Debut\")\r\n    invoke_custom(8500, 1, \"clearBubbles\", nox)\r\n        \r\n    -- \"Ce mécanisme permet de canaliser l'énergie du cube.\"\r\n    invoke_custom(9500, 1, \"bubble\", nox, \"nox.fight.start.dialog.02\")\r\n    invoke_custom(11000, 1, \"Mobile.setMobileAnimation\", nox, \"AnimComp1\")\r\n    invoke_custom(12500, 1, \"clearBubbles\", nox)\r\n    \r\n    -- \"Et puisque vous êtes là...\"\r\n    invoke_custom(13000, 1, \"bubble\", nox, \"nox.fight.start.dialog.03\")\r\n    invoke_custom(15000, 1, \"Mobile.setMobileAnimation\", nox, \"AnimTP-Debut\")\r\n    invoke_custom(15000, 1, \"clearBubbles\", nox)\r\n    invoke_custom(15100, 1, \"Mobile.setMobileVisible\", nox, false)\r\n    \r\n    -- \"Votre Wakfu servira mes desseins !\"\r\n    invoke_custom(15150, 1, \"Mobile.setMobileAnimationSuffix\", nox, \"-7\")\r\n    invoke_custom(15150, 1, \"Mobile.setMobileDirection\", nox, 3)\r\n    invoke_custom(15150, 1, \"Mobile.setMobilePosition\", nox, -2, -19, 0)\r\n    invoke_custom(15250, 1, \"Mobile.setMobileVisible\", nox, true)\r\n    invoke_custom(15250, 1, \"Mobile.setMobileAnimation\", nox, \"AnimTP-Fin\")\r\n    invoke_custom(15350, 1, \"Mobile.setMobileDirection\", playerId, 7)\r\n    invoke_custom(15500, 1, \"Camera.setCamera\", 2, -2, -19, 4)\r\n    invoke_custom(15500, 1, \"Mobile.setMobileAnimation\", nox, \"AnimComp-Parler1\")\r\n    invoke_custom(16000, 1, \"bubble\", nox, \"nox.fight.start.dialog.04\")\r\n    invoke_custom(18500, 1, \"clearBubbles\", nox)\r\n    \r\n     -- Fin\r\n    invoke_custom(18501, 1, \"customSkip\")\nend\n\n-- CLIENT_TRIGGERED_EVENT - Fin de la cinématique\n-- \nfunction event_2666_23606(noxId)\n     Mobile.setMobileVisible(noxId, true)\r\n     skipCinematic()\nend\n\n-- MONSTER_ACTION_EVENT - Lancement du combat\n-- \nfunction event_2666_23506()\n    \nend\n\n-- FIGHT_STARTED - Initialisation des variables\n-- \nfunction event_2666_23507()\n    \nend\n\n-- FIGHT_STARTED - Pose des zones\n-- \nfunction event_2666_23508()\n    \nend\n\n-- EFFECT_EXECUTION - Mise à jour UI infos de combat (score)\n-- \nfunction event_2666_23509(turnLeft, teamDamage, phase, weaponA, weaponB, weaponC, weaponD, weaponALvl, weaponBLvl, weaponCLvl, weaponDLvl, wakfuCharge, wakfuChargeVariation)\n    updateFightInfo(turnLeft, teamDamage, phase, weaponA, weaponB, weaponC, weaponD, weaponALvl, weaponBLvl, weaponCLvl, weaponDLvl, wakfuCharge, wakfuChargeVariation, true)\nend\n\n-- EFFECT_EXECUTION - Mise à jour UI infos de combat (Armes)\n-- \nfunction event_2666_23510(turnLeft, teamDamage, weaponA, weaponB, weaponC, weaponD, phase, weaponALvl, weaponBLvl, weaponCLvl, weaponDLvl, wakfuCharge, wakfuChargeVariation)\n    updateFightInfo(turnLeft, teamDamage, phase, weaponA, weaponB, weaponC, weaponD, weaponALvl, weaponBLvl, weaponCLvl, weaponDLvl, wakfuCharge, wakfuChargeVariation, true)\nend\n\n-- EFFECT_EXECUTION - Mise à jour UI infos de combat (niveau de la phase)\n-- \nfunction event_2666_23578(teamDamage, weaponA, weaponB, weaponC, weaponD, phase, weaponALvl, weaponBLvl, weaponCLvl, weaponDLvl, wakfuCharge, wakfuChargeVariation, turnLeft)\n    updateFightInfo(turnLeft, teamDamage, phase, weaponA, weaponB, weaponC, weaponD, weaponALvl, weaponBLvl, weaponCLvl, weaponDLvl, wakfuCharge, wakfuChargeVariation, true)\nend\n\n-- EFFECT_EXECUTION - Mise à jour UI infos de combat (tour)\n-- \nfunction event_2666_23577(turnLeft, teamDamage, weaponA, weaponB, weaponC, weaponD, phase, weaponALvl, weaponBLvl, weaponCLvl, weaponDLvl, wakfuCharge, wakfuChargeVariation)\n    updateFightInfo(turnLeft, teamDamage, phase, weaponA, weaponB, weaponC, weaponD, weaponALvl, weaponBLvl, weaponCLvl, weaponDLvl,