    \r\n    local phase = toLong(phase)\r\n    displayPhaseAps(phase)\nend\n\n-- [EVENT] Changement de Musique (Phase 3)\n-- \nfunction event_2666_23575(phase)\n    Sound.playFightMusic(290182, 63)\r\n    \r\n    local phase = toLong(phase)\r\n    displayPhaseAps(phase)\nend\n\n-- Achievement 5557 - Variable\n-- \nfunction event_2666_23636()\n    \nend\n\n-- Achievement 5557 - Validation\n-- \nfunction event_2666_23637()\n    \nend\n\n-- Achievement 5558 - Variable + 1\n-- \nfunction event_2666_23638()\n    \nend\n\n-- Achievement 5558 - Variable = 0\n-- \nfunction event_2666_23642()\n    \nend\n\n-- Achievement 5558 - Validation\n-- \nfunction event_2666_23639()\n    \nend\n\n-- Achievement 5561 - Variable\n-- \nfunction event_2666_23640()\n    \nend\n\n-- Achievement 5561 - Validation\n-- \nfunction event_2666_23641()\n    \nend\n\n-- [TEST] Lancement du combat - Phase 2\n-- \nfunction event_2666_23579()\n    skipCinematic()\nend\n\n-- [TEST] Lancement du combat - Phase 2 - Marteau du jugement\n-- \nfunction event_2666_23587()\n    skipCinematic()\nend\n\n-- [TEST] Lancement du combat - Phase 2 - Marteau de la résonance\n-- \nfunction event_2666_23588()\n    skipCinematic()\nend\n\n-- [TEST] Lancement du combat - Phase 2 - Aiguille du chatiment\n-- \nfunction event_2666_23589()\n    skipCinematic()\nend\n\n-- [TEST] Lancement du combat - Phase 2 - Aiguille de l'inéluctable\n-- \nfunction event_2666_23590()\n    skipCinematic()\nend\n\n-- [TEST] Contrôle du temps après\n-- \nfunction event_2666_23603()\n    \nend\n\n-- [TEST] Contrôle du temps avant\n-- \nfunction event_2666_23604()\n    \nend\n\n-- [TEST] Passage en phase 3\n-- \nfunction event_2666_23648()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicCont