leSystem\", -1148084431, 178, 171, 0)\r\n    invoke_custom(76500, 1, \"Effect.createCameraShakeEffect\", 1000, 5000, 1000, 10, 500, \"BOTH\")\r\n    \r\n    invoke_custom(77500, 1, \"Particle.addParticleSystem\", 41090000, 178, 173, 0)\r\n    \r\n    -- écran blanc\r\n    invoke_custom(79000, 1, \"Effect.createFullScreenSprite\", 1000, 6000, 1000, 1.0, 1.0, 1.0)\r\n    \r\n    -- écran noir\r\n    invoke_custom(86000, 1, \"fullScreen\", 0, 26500, 1000)\r\n    \r\n    -- \"Un flash lumineux vous aveugle. Une gigantesque secousse vous fait perdre l'équilibre.\"\r\n    -- \"Vous sentez le sol se dérober sous vos pieds.\"\r\n    invoke_custom(80000, 1, \"UI.createFullScreenText\", 500, 6000, 500, \"quest.brume.nox.confrontation.01.15.1\", 0.0, 0.0, 0.0, 1.0, \"bagnard\", 40, 0)\r\n    \r\n    -- \"Est-ce la fin ? Si près du but ?\"\r\n    invoke_custom(87500, 1, \"text\", 500, 2000, 500, \"quest.brume.nox.confrontation.01.15.2\")\r\n    \r\n    -- \"Vous vous sentez glisser dans une sorte de portail... Et vous perdez connaissance.\"\r\n    invoke_custom(91000, 1, \"text\", 500, 3500, 500, \"quest.brume.nox.confrontation.01.15.3\")\r\n    \r\n    -- \"Vous revenez à vous péniblement. Vous ignorez combien de temps est passé.\"\r\n    invoke_custom(95500, 1, \"text\", 500, 4000, 500, \"quest.brume.nox.confrontation.01.15.4\")\r\n    \r\n    -- \"Votre coeur se serre lorsque vous ouvrez les yeux : vous êtes sur une plage, vous sentez la douce chaleur du soleil et la brise marine...\"\r\n    invoke_custom(100500, 1, \"UI.createFullScreenText\", 500, 6500, 500, \"quest.brume.nox.confrontation.01.15.5\", 0.8, 0.0, 0.0, 1.0, \"bagnard\", 40, 0)\r\n    \r\n    -- \"Aussitôt, la sensation disparaît. Tout vous revient : vous êtes sur l'Île des brumes.\"\r\n    -- \"On dirait que Nox a pris la poudre d'escampette.\"\r\n    invoke_custom(107500, 1, \"text\", 500, 6000, 500, \"quest.brume.nox.confrontation.01.15.6\")\r\n    \r\n    invoke_custom(86500, 1, \"Camera.attachCameraToMobile\", playerId)\r\n    \r\n    invoke_custom(87000, 1, \"Server.triggerEvent\", 236021)\r\n    invoke_custom(88500, 1, \"Camera.setZoomFactor\", 1.6)\r\n    \r\n    invoke_custom(113000, 1, \"Mobile.setMobileDirection\", playerId, 1)\r\n    invoke_custom(113000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Dormir-Boucle\")\r\n    \r\n    invoke_custom(114000, 1, \"Camera.setZoomFactor\", 1.2)\r\n    \r\n    invoke_custom(116500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Dormir-Fin\")\r\n    \r\n    invoke_custom(117750, 1, \"Camera.attachCameraToMobile\", ameliaB)\r\n    \r\n    -- \"Ça va, tu es réveillé{[1*]?e:} ?\"\r\n    invoke_custom(118000, 1, \"bubble\", ameliaB, \"quest.brume.nox.confrontation.01.16\")\r\n    invoke_custom(118000, 1, \"Mobile.setMobileAnimation\", ameliaB, \"AnimBonnechose\")\r\n    invoke_custom(122000, 1, \"clearBubbles\", ameliaB)\r\n    \r\n    invoke_custom(122250, 1, \"Camera.attachCameraToMobile\", playerId)\r\n    \r\n    -- \"Ma tête... Que s'est-il passé ?\"\r\n    invoke_custom(122500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Fievre\")\r\n    invoke_custom(122500, 1, \"bubble\", playerId, \"quest.brume.nox.confrontation.01.17\")\r\n    invoke_custom(125500, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(125750, 1, \"Mobile.setMobileDirection\", playerId, 3)\r\n    \r\n    invoke_custom(125750, 1, \"Camera.attachCameraToMobile\", zulnaraB)\r\n    \r\n    -- \"Nous avons gagné, semble-t-il.\"\r\n    invoke_custom(126000, 1, \"bubble\", zulnaraB, \"quest.brume.nox.confrontation.01.18\")\r\n    invoke_custom(129000, 1, \"clearBubbles\", zulnaraB)\r\n    \r\n    invoke_custom(129250, 1, \"Camera.attachCameraToMobile\", ameliaB)\r\n    invoke_custom(129250, 1, \"Mobile.setMobileDirection\", playerId, 5)\r\n    \r\n    -- \"Les machines ont disparu. Ce malheureux Nox aussi.\"\r\n    invoke_custom(129500, 1, \"Mobile.setMobileAnimation\", ameliaB, \"AnimParler\")\r\n    invoke_custom(129500, 1, \"bubble\", ameliaB, \"quest.brume.nox.confrontation.01.19\")\r\n    invoke_custom(133000, 1, \"clearBubbles\", ameliaB)\r\n    \r\n    invoke_custom(133250, 1, \"Camera.attachCameraToMobile\", playerId)\r\n    \r\n    -- \"D'accord... C'était... Soudain.\"\r\n    invoke_custom(133500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(133500, 1, \"bubble\", playerId, \"quest.brume.nox.confrontation.01.20\")\r\n    invoke_custom(136000, 1, \"clearBubbles\", playerId)\r\n    \r\n    -- \"Faisons le point au quartier général !\"\r\n    invoke_custom(136500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Calmer\")\r\n    invoke_custom(136500, 1, \"bubble\", playerId, \"quest.brume.nox.confrontation.01.21\")\r\n    invoke_custom(139000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(139000, 1, \"fullScreen\", 1000, 1000, 500)\r\n    \r\n    invoke_custom(141000, 1, \"customSkip\")\nend\n\n-- Q7 - 4 - Cinématique Post-combat : on replace le player\n-- \nfunction event_2676_23607()\n    \nend\n\n-- Q7 - 4 - Fin Cinématique Post-combat\n-- \nfunction event_2676_23608()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","hideMonster","hidePart","showMonster","showPart","event_2676_23583","event_2676_23584","sceneA","sceneB","customSkip","event_2676_23585","event_2676_23591","event_2676_23596","customSkip","event_2676_23597","event_2676_23598","customSkip","event_2676_23599","event_2676_23600","event_2676_23601","event_2676_23602","customSkip","event_2676_23607","event_2676_23608"],"quest_calls":[],"dialogue_calls":[]},"scenario/2677.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\n-- les fonctions où on cache\r\nfunction hideMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, false)\r\nend\r\n\r\nfunction hidePart(monsterMobileId, partName)\r\n\tMobile.setPartVisible(monsterMobileId, false, partName)\r\nend\r\n\r\n-- les fonctions où on rend visible (à nouveau)\r\nfunction showMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, true)\r\nend\r\n\r\nfunction showPart(monsterMobileId, partName)\r\n\tMobile.setPartVisible(monsterMobileId, true, partName)\r\nend\n\n-- [INITIALISATION] Serveur\n-- \nfunction event_2677_23610()\n    \nend\n\n-- Q7 - ENTER_INSTANCE - Cinématique\n-- \nfunction event_2677_23611()\n    local playerId = Context.getLeaderId()\r\n    \r\n    function customSkip()\r\n    \tMobile.hideOtherPlayerMobile(false)\r\n    \tskipCinematic()\r\n    end\r\n    \r\n    Mobile.hideOtherPlayerMobile(true)\r\n    \r\n    fullScreen(0, 29000, 1000)\r\n    \r\n    startCinematicContext(1.2, playerId)\r\n    \r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"customSkip\")\r\n    \r\n    -- \"L'air vespéral vous apaise.\"\r\n    -- \"Vous vous promenez un peu sur l'île, dans la direction de l'étrange structure au centre de l'île.\"\r\n    invoke_custom(02000, 1, \"text\", 500, 6000, 500, \"quest.brume.nox.fin.00.00\")\r\n    \r\n    -- \"Vous songez que votre aventure sur cette île a pris un tout autre tournant lorsque vous vous êtes approché{[1*]?e:} de ces ruines.\"\r\n    invoke_custom(09000, 1, \"text\", 500, 6000, 500, \"quest.brume.nox.fin.00.01\")\r\n    \r\n    -- \"En vous approchant des ruines, vous apercevez Milo et Arlémia.\"\r\n    -- \"Ils sont en train de débattre sur un détail des ruines. Tel père telle fille, dirait-on.\"\r\n    invoke_custom(16000, 1, \"text\", 500, 7000, 500, \"quest.brume.nox.fin.00.02\")\r\n    \r\n    -- \"Mais vous n'êtes pas venu{[1*]?e:} ici pour leur parler. Vous êtes sorti{[1*]?e:} prendre l'air pour parler à quelqu'un d'autre...\"\r\n    invoke_custom(24000, 1, \"text\", 500, 6000, 500, \"quest.brume.nox.fin.00.03\")\r\n    \r\n    invoke_custom(31000, 1, \"customSkip\")\r\nend\n\n-- Q7 - Dialogue Nox -> tp le joueur en 1401\n-- \nfunction event_2677_23612()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","hideMonster","hidePart","showMonster","showPart","event_2677_23610","event_2677_23611","customSkip","event_2677_23612"],"quest_calls":[],"dialogue_calls":[]},"scenario/2678.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\n-- Fonction mode démo\r\n-- function addButton()\r\n-- \tinvoke(2000, 1, \"UI.displayButton\", false, \"scenario.endKinematic.confirmEscape\", \"lyongameshow.vampyro.rules.display\", \"displayFightRules\")\r\n-- end \r\n\r\n-- Fonctions cache / montre CM\r\nfunction hideMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, false)\r\nend\r\n\r\nfunction showMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, true)\r\nend\r\n\r\nbubbleFightInfoId = 0\r\n\r\nfunction closeFightInfo()\r\n\tif (bubbleFightInfoId ~= nil and bubbleFightInfoId ~= 0) then BubbleText.close(bubbleFightInfoId) end\r\nend\r\n\r\nfunction onFightInfoClosed()\r\n\tif (bubbleFightInfoId ~= nil and bubbleFightInfoId ~= 0) then bubbleFightInfoId = 0 end\r\nend\r\n\r\nfunction updateFightInfo(turnLeft, forceDisplayUI)\r\n\tlocal turnLeft = toLong(turnLeft)\r\n\r\n\tif (bubbleFightInfoId == 0) then\r\n\t\tbubbleFightInfoId = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_WEST\", 0, -60, false, 2147483647, true, \"interactiveBubbleDialog5\", 30000, 25000, \"onFightInfoClosed\")\r\n\tend\r\n\r\n\tBubbleText.setText(bubbleFightInfoId, \"dragons.karn.fight.info\", turnLeft)\r\n\r\n\tif (forceDisplayUI) then BubbleText.show(bubbleFightInfoId) end\r\nend\n\n-- [INIT] Variables globales\n-- \nfunction event_2678_23624()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2678_23625()\n    \nend\n\n-- [EVENT] MONSTER_ACTION_EVENT - Lancement du combat\n-- \nfunction event_2678_23626()\n    \nend\n\n-- FIGHT_STARTED - Pose des zones\n-- \nfunction event_2678_23635()\n    \nend\n\n-- FIGHT_ENTER_ACTION_PHASE - Application états\n-- \nfunction event_2678_23627(turnLeft)\n    updateFightInfo(turnLeft, true)\nend\n\n-- FIGHT_PLACEMENT_END - On ajoute Karn\n-- \nfunction event_2678_23634()\n    \nend\n\n-- EFFECT_EXECUTION - Mise à jour UI infos de combat (tours restants)\n-- \nfunction event_2678_23630(turnLeft, teamDamage)\n    updateFightInfo(turnLeft, teamDamage, true)\nend\n\n-- EFFECT_EXECUTION - Le joueur a gagné le combat\n-- \nfunction event_2678_23631()\n    \nend\n\n-- [EVENT] Victoire du combat - On initialise la variable\n-- \nfunction event_2678_23644()\n    \nend\n\n-- [EVENT] Le joueur gagne le combat - Cinématique\n-- \nfunction event_2678_23628()\n    local playerId = Context.getLeaderId()\r\n    local karn = createActor(1115405771, -3, -4, 0, 4, 5, 8)\r\n    local dragon = createActor(1115405770, -7, -4, 0, 4, 1, 10)\r\n    local smallDragon = createActor(1115405768, -3, -10, 0, 4, 3, 6)\r\n    \r\n    function customSkip()\r\n        Mobile.hideOtherPlayerMobile(false)\r\n        Mobile.setMobileVisible(playerId, true)\r\n        skipCinematic(23628)\r\n        fullScreen(0, 0, 500)\r\n    end\r\n    \r\n    Mobile.hideOtherPlayerMobile(true)\r\n    Mobile.setMobilePosition(playerId, -3, -7, 0)\r\n    Mobile.setMobileDirection(playerId, 7)\r\n    \r\n    World.setPictoAlpha(-3, -2, 0, 0, 50)\r\n    World.setPictoAlpha(-3, -1, 0, 0, 50)\r\n    World.setPictoAlpha(-3, 0, 0, 0, 50)\r\n    World.setPictoAlpha(-2, -1, 0, 0, 50)\r\n    World.setPictoAlpha(-4, -1, 0, 0, 50)\r\n    World.setPictoAlpha(-5, -1, 0, 0, 50)\r\n    World.setPictoAlpha(-6, -1, 0, 0, 50)\r\n    World.setPictoAlpha(-6, 0, 0, 0, 50)\r\n    World.setPictoAlpha(-5, 0, 0, 0, 50)\r\n    World.setPictoAlpha(-7, 0, 0, 0, 50)\r\n    World.setPictoAlpha(-6, -9, 0, 0, 50)\r\n    World.setPictoAlpha(1, -8, 0, 0, 50)\r\n    World.setPictoAlpha(2, 2, 0, 0, 50)\r\n    World.setPictoAlpha(3, 2, 0, 0, 50)\r\n    World.setPictoAlpha(4, 2, 0, 0, 50)\r\n    World.setPictoAlpha(5, 2, 0, 0, 50)\r\n    World.setPictoAlpha(-5, -7, 0, 0, 50)\r\n    World.setPictoAlpha(6, 2, 0, 0, 50)\r\n    World.setPictoAlpha(0, -10, 0, 0, 50)\r\n    \r\n    fullScreen(0, 1500, 500)\r\n    \r\n    startCinematicContext(1.5, playerId)\r\n    \r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"customSkip\")\r\n    \r\n    invoke_custom(00100, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimStatique02\")\r\n    invoke_custom(01500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimStatique02\")\r\n    \r\n    invoke_custom(00050, 1, \"Sound.stopForcedMusic\")\r\n    invoke_custom(00100, 1, \"Sound.playForcedMusic\", 210106, 70)\r\n    \r\n    -- \"Je vais pouvoir l'achever...\"\r\n    invoke_custom(02500, 1, \"Sound.playSound\", 3201115405771003, true, 45)\r\n    invoke_custom(02500, 1, \"bubble\", karn, \"quest.karn.02.00\")\r\n    invoke_custom(05000, 1, \"clearBubbles\", karn)\r\n    \r\n    invoke_custom(05250, 1, \"Camera.attachCameraToMobile\", karn)\r\n    invoke_custom(05250, 1, \"Mobile.setMobileDirection\", karn, 7)\r\n    \r\n    -- \"Garde mes arrières, peti{[1*]?e:}.\"\r\n    invoke_custom(05500, 1, \"Sound.playSound\", 3201115405771002, true, 45)\r\n    invoke_custom(05500, 1, \"bubble\", karn, \"quest.karn.02.01\")\r\n    invoke_custom(08500, 1, \"clearBubbles\", karn)\r\n    \r\n    invoke_custom(08750, 1, \"Mobile.setMobileDirection\", karn, 5)\r\n    \r\n    -- \"Je vais rassembler ma puissance...\"\r\n    invoke_custom(09000, 1, \"Sound.playSound\", 3201115405771004, true, 45)\r\n    invoke_custom(09000, 1, \"bubble\", karn, \"quest.karn.02.02\")\r\n    invoke_custom(12000, 1, \"clearBubbles\", karn)\r\n    \r\n    invoke_custom(12500, 1, \"Mobile.setMobileAnimation\", karn, \"AnimSort-Colere\")\r\n    invoke_custom(12800, 1, \"Particle.addParticleSystem\", -1128078370, -3, -4, 0)\r\n    \r\n    invoke_custom(13750, 1, \"Camera.attachCameraToMobile\", playerId)\r\n    \r\n    -- \"**Si je le laisse faire, je crois que Coqueline va m'en vouloir...\"\r\n    invoke_custom(14000, 1, \"bubble\", playerId, \"quest.karn.02.03\")\r\n    invoke_custom(17000, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(17500, 1, \"Mobile.setMobileAnimation\", smallDragon, \"AnimSort-2\")\r\n    invoke_custom(18500, 1, \"Particle.addParticleSystem\", 41089310, -3, -10, 0)\r\n    \r\n    invoke_custom(19000, 1, \"Mobile.setMobileAnimation\", smallDragon, \"AnimSort-1\")\r\n    invoke_custom(19300, 1, \"Particle.addParticleSystem\", -1154084061, -3, -10, 0)\r\n    invoke_custom(19400, 1, \"Particle.addParticleSystem\", -1154084067, -3, -4, -2)\r\n    \r\n    invoke_custom(19400, 1, \"Mobile.setMobileAnimation\", karn, \"AnimHit\")\r\n    invoke_custom(19500, 1, \"Mobile.addCubicSplineTweenToMobile\", karn, -3, 0, 0, 500, 0, 0, 0, 0, 0, -5)\r\n    \r\n    invoke_custom(18300, 1, \"Mobile.setMobilePosition\", playerId, 0, -7, 0)\r\n    invoke_custom(18300, 1, \"Mobile.setMobileDirection\", playerId, 5)\r\n    invoke_custom(18300, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimIncarnam-Reception\")\r\n    invoke_custom(19000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimStatique02-Debut\")\r\n    \r\n    -- \"écran noir\"\r\n    invoke_custom(20000, 1, \"fullScreen\", 500, 20000, 1000)\r\n    invoke_custom(20500, 1, \"Sound.playSound\", 90000853, true, 45)\r\n    \r\n    -- \"Vous esquivez l'attaque du dragon. Le projectile tape Karn de plein fouet, et le Iop chasseur dégringole de l'île.\"\r\n    invoke_custom(20000, 1, \"text\", 500, 5000, 500, \"quest.karn.02.04\")\r\n    \r\n    -- \"Le connaissant, vous imaginez qu'il a survécu...\"\r\n    invoke_custom(26000, 1, \"text\", 500, 2500, 500, \"quest.karn.02.05\")\r\n    \r\n    -- \"Vous avez agi avec assurance et honneur, mais vous vous retrouvez seul{[1*]?e:} face aux dragons. Ils vous taillent en pièces rapidement.\"\r\n    -- \"Une réincarnation plus tard, vous décidez de faire votre rapport à Coqueline.\"\r\n    invoke_custom(29500, 1, \"text\", 500, 7500, 500, \"quest.karn.02.06\")\r\n    \r\n    invoke_custom(37500, 1, \"customSkip\")\nend\n\n-- [EVENT] Le joueur perd le combat - TP en dehors de l'instance\n-- \nfunction event_2678_23643()\n    \nend\n\n-- CLIENT_TRIGGERED_EVENT - Fin de la cinématique - TP en dehors de l'instance\n-- \nfunction event_2678_23645()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","addButton","hideMonster","showMonster","closeFightInfo","onFightInfoClosed","updateFightInfo","event_2678_23624","event_2678_23625","event_2678_23626","event_2678_23635","event_2678_23627","event_2678_23634","event_2678_23630","event_2678_23631","event_2678_23644","event_2678_23628","customSkip","event_2678_23643","event_2678_23645"],"quest_calls":[],"dialogue_calls":[]},"scenario/2679.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\nfunction displayPath(room)\r\n\tlocal room = toLong(room)\r\n\t\r\n\tif (room == 1) then\r\n\tWorld.setPictoAlpha(41, 0, 0, 0, 1000)\r\n\tWorld.setPictoAlpha(40, 0, 0, 0, 1000)\r\n\tWorld.setPictoAlpha(39, 0, 0, 0, 1000)\r\n\tWorld.setPictoAlpha(24, 0, 0, 0, 1000)\r\n\tWorld.setPictoAlpha(23, 0, 0, 0, 1000)\r\n\tWorld.setPictoAlpha(22, 0, 0, 0, 1000)\r\n\t\r\n\telseif (room == 2) then\r\n\tWorld.setPictoAlpha(41, 0, 0, 1, 1000)\r\n\tWorld.setPictoAlpha(40, 0, 0, 1, 1000)\r\n\tWorld.setPictoAlpha(39, 0, 0, 1, 1000)\r\n\tWorld.setPictoAlpha(24, 0, 0, 0, 1000)\r\n\tWorld.setPictoAlpha(23, 0, 0, 0, 1000)\r\n\tWorld.setPictoAlpha(22, 0, 0, 0, 1000)\r\n\telse\r\n\tWorld.setPictoAlpha(41, 0, 0, 1, 1000)\r\n\tWorld.setPictoAlpha(40, 0, 0, 1, 1000)\r\n\tWorld.setPictoAlpha(39, 0, 0, 1, 1000)\r\n\tWorld.setPictoAlpha(24, 0, 0, 1, 1000)\r\n\tWorld.setPictoAlpha(23, 0, 0, 1, 1000)\r\n\tWorld.setPictoAlpha(22, 0, 0, 1, 1000)\r\n\tend\r\n\t\r\nend\n\n-- [INIT] Variables Globales\n-- \nfunction event_2679_23649()\n    \nend\n\n-- [INIT] Inscription du joueur + Variables Locales\n-- \nfunction event_2679_23650(room)\n    displayPath(room)\nend\n\n-- USER_GROUP_KILLED - Salle 01\n-- \nfunction event_2679_23651(room)\n    displayPath(room)\nend\n\n-- USER_GROUP_KILLED - Salle 02\n-- \nfunction event_2679_23652(room)\n    displayPath(room)\nend\n\n-- USER_GROUP_KILLED - Salle 03 - BOSS\n-- \nfunction event_2679_23653(room)\n    displayPath(room)\nend\n\n-- Déplace le joueur vers la salle suivante\n-- \nfunction event_2679_23654()\n    \nend\n\n-- [EVENT] Victoire - BOSS - Cinématique Mercenaire\n-- \nfunction event_2679_23655()\n    \t----------------------------- RECUPERATIONS DES INFOS JOUEUR --------------------------\r\n    \r\n    \tlocal playerId = Context.getLeaderId()\r\n    \tlocal playerX, playerY, playerZ = Mobile.getMobilePosition(playerId)\r\n    \r\n    \r\n    \t----------------------------- INITIALISATION DES PNJ --------------------------\r\n    \r\n    \tlocal apsTransfo = -1478031420\r\n    \tlocal moogrrRoyale = createActor(121802271, 13, 0, 0, 8, 1, 7)\r\n    \r\n    \tlocal mobileMoorghueurite = createActor(121801221, 13, 0, 0, 8, 1, 7)\r\n    \r\n    \t----------------------------- DEBUT DE CINEMATIQUE --------------------------\r\n    \r\n    \tstartCinematicContext(1.3, playerId)\r\n    \tUI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 23655)\r\n    \r\n    \tinvoke_custom(2, 1, \"Mobile.setMobileVisible\", mobileMoorghueurite, false)\r\n    \r\n    \r\n    \t----------------------------- ACTIONS --------------------------\r\n    \r\n    \tinvoke_custom(100, 1, \"Mobile.moveMobile\", playerId, 17, 0, 0, \"Mobile.setMobileDirection\", playerId, 5)\r\n    \tinvoke_custom(1000, 1, \"Mobile.setMobileAnimation\", moogrrRoyale, \"AnimMort\")\r\n    \tinvoke_custom(2500, 1, \"Particle.addParticleSystem\", apsTransfo, 13, 0, 0)\r\n    \tinvoke_custom(2501, 1, \"Particle.addParticleSystem\", apsTransfo, 13, 0, 0)\r\n    \tinvoke_custom(2502, 1, \"Particle.addParticleSystem\", apsTransfo, 13, 0, 0)\r\n    \tinvoke_custom(2700, 1, \"Actor.deleteActor\", moogrrRoyale)\r\n    \tinvoke_custom(3200, 1, \"Mobile.setMobileVisible\", mobileMoorghueurite, true)\r\n    \r\n    \tinvoke_custom(2500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Help\")\r\n    \r\n    \tinvoke_custom(7500, 1, \"Mobile.moveMobile\", mobileMoorghueurite, 16, 0, 0)\r\n    \tinvoke_custom(8500, 1, \"Mobile.moveMobile\", playerId, 17, 1, 0, \"Mobile.setMobileDirection\", playerId, 7)\r\n    \tinvoke_custom(10000, 1, \"Mobile.moveMobile\", mobileMoorghueurite, 32, 0, 0)\r\n    \tinvoke_custom(10000, 1, \"Mobile.setMobileDirection\", playerId, 1)\r\n    \r\n    \t----------------------------- DIALOGUES --------------------------\r\n    \r\n    \t-- ... Moorghueurite ?!\r\n    \tinvoke_custom(4500, 1, \"bubble\", playerId, \"quest.amakna.mercenary.moogrr.07.01\")\r\n    \tinvoke_custom(4500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    \r\n    \tinvoke_custom(6000, 1, \"Mobile.setMobileAnimation\", mobileMoorghueurite, \"AnimSort-CridAmoogr\")\r\n    \r\n    \tinvoke_custom(12000, 1, \"bubble\", playerId, \"quest.amakna.mercenary.moogrr.07.02\")\r\n    \tinvoke_custom(12000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmoteMarket-HausseEpaules\")\r\n    \r\n    \r\n    \t----------------------------- FIN DE CINEMATIQUE --------------------------\r\n    \r\n    \tinvoke_custom(15000, 1, \"Mobile.moveMobile\", playerId, playerX, playerY, playerZ)\r\n    \tinvoke_custom(15000, 1, \"Mobile.setMobileVisible\", mobileMoorghueurite, false)\r\n    \t\r\n    \tinvoke_custom(15050, 1, \"skipCinematic\", 23655)\nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","displayPath","event_2679_23649","event_2679_23650","event_2679_23651","event_2679_23652","event_2679_23653","event_2679_23654","event_2679_23655"],"quest_calls":[],"dialogue_calls":[]},"scenario/2680.lua":{"source":"\n\n-- [INIT] Variables Globales\n-- \nfunction event_2680_23656()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2680_23657()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 01\n-- \nfunction event_2680_23658()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 02\n-- \nfunction event_2680_23659()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 03 - BOSS\n-- \nfunction event_2680_23661()\n    \nend\n\n-- Déplace le joueur vers la salle suivante\n-- \nfunction event_2680_23662()\n    \nend\n\n-- FIGHT_ENTER_ACTION_PHASE - Applique l'état \"Neo-Corruption\"\n-- \nfunction event_2680_23895()\n    \nend\n\n-- [NEO][ARCHI] Apparition de l'Archimonstre\n-- \nfunction event_2680_23941()\n    \nend\n\n","functions":["event_2680_23656","event_2680_23657","event_2680_23658","event_2680_23659","event_2680_23661","event_2680_23662","event_2680_23895","event_2680_23941"],"quest_calls":[],"dialogue_calls":[]},"scenario/2681.lua":{"source":"\n\n-- [INIT] Variables Globales\n-- \nfunction event_2681_23663()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2681_23664()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 01\n-- \nfunction event_2681_23665()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 02\n-- \nfunction event_2681_23666()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 03 - BOSS\n-- \nfunction event_2681_23667()\n    \nend\n\n-- Déplace le joueur vers la salle suivante\n-- \nfunction event_2681_23668()\n    \nend\n\n-- FIGHT_ENTER_ACTION_PHASE - Applique l'état \"Neo-Corruption\"\n-- \nfunction event_2681_23896()\n    \nend\n\n-- [NEO][ARCHI] Apparition de l'Archimonstre\n-- \nfunction event_2681_23945()\n    \nend\n\n","functions":["event_2681_23663","event_2681_23664","event_2681_23665","event_2681_23666","event_2681_23667","event_2681_23668","event_2681_23896","event_2681_23945"],"quest_calls":[],"dialogue_calls":[]},"scenario/2682.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\nfunction displayPath(room)\r\n\tlocal room = toLong(room)\r\n\t\r\n\tif ( room >= 1 or room == -1 ) then\r\n\tWorld.setPictoAlpha(41, 0, 0, 0, 1000)\r\n\tWorld.setPictoAlpha(40, 0, 0, 0, 1000)\r\n\tWorld.setPictoAlpha(39, 0, 0, 0, 1000)\r\n\tWorld.setPictoAlpha(24, 0, 0, 0, 1000)\r\n\tWorld.setPictoAlpha(23, 0, 0, 0, 1000)\r\n\tWorld.setPictoAlpha(22, 0, 0, 0, 1000)\r\n\tend\r\n\t\r\n\tif ( room >= 2 or room == -1 ) then\r\n\tWorld.setPictoAlpha(41, 0, 0, 1, 1000)\r\n\tWorld.setPictoAlpha(40, 0, 0, 1, 1000)\r\n\tWorld.setPictoAlpha(39, 0, 0, 1, 1000)\r\n\tWorld.setPictoAlpha(24, 0, 0, 0, 1000)\r\n\tWorld.setPictoAlpha(23, 0, 0, 0, 1000)\r\n\tWorld.setPictoAlpha(22, 0, 0, 0, 1000)\r\n\tend\r\n\t\r\n\tif ( room >= 3 or room == -1) then\r\n\tWorld.setPictoAlpha(41, 0, 0, 1, 1000)\r\n\tWorld.setPictoAlpha(40, 0, 0, 1, 1000)\r\n\tWorld.setPictoAlpha(39, 0, 0, 1, 1000)\r\n\tWorld.setPictoAlpha(24, 0, 0, 1, 1000)\r\n\tWorld.setPictoAlpha(23, 0, 0, 1, 1000)\r\n\tWorld.setPictoAlpha(22, 0, 0, 1, 1000)\r\n\tend\r\n\t\r\nend\n\n-- [INIT] Variables Globales\n-- \nfunction event_2682_23669()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2682_23670(room)\n    displayPath(room)\nend\n\n-- USER_GROUP_KILLED - Salle 01\n-- \nfunction event_2682_23671(room)\n    displayPath(room)\nend\n\n-- USER_GROUP_KILLED - Salle 02\n-- \nfunction event_2682_23672(room)\n    displayPath(room)\nend\n\n-- USER_GROUP_KILLED - Salle 03 - BOSS\n-- \nfunction event_2682_23673(room)\n    displayPath(room)\nend\n\n-- Déplace le joueur vers la salle suivante\n-- \nfunction event_2682_23674()\n    \nend\n\n-- [EVENT] Victoire - BOSS - Cinématique Mercenaire\n-- \nfunction event_2682_23675()\n    \t----------------------------- RECUPERATIONS DES INFOS JOUEUR --------------------------\r\n    \r\n    \tlocal playerId = Context.getLeaderId()\r\n    \tlocal playerX, playerY, playerZ = Mobile.getMobilePosition(playerId)\r\n    \r\n    \r\n    \t----------------------------- INITIALISATION DES PNJ --------------------------\r\n    \r\n    \tlocal apsTransfo = -1478031420\r\n    \tlocal moogrrRoyale = createActor(1115705793, 13, 0, 0, 8, 1, 7)\r\n    \r\n    \tlocal mobileMoorghueurite = createActor(121801221, 13, 0, 0, 8, 1, 7)\r\n    \r\n    \t----------------------------- DEBUT DE CINEMATIQUE --------------------------\r\n    \r\n    \tstartCinematicContext(1.3, playerId)\r\n    \tUI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 23675)\r\n    \r\n    \tinvoke_custom(2, 1, \"Mobile.setMobileVisible\", mobileMoorghueurite, false)\r\n    \r\n    \r\n    \t----------------------------- ACTIONS --------------------------\r\n    \r\n    \tinvoke_custom(100, 1, \"Mobile.moveMobile\", playerId, 17, 0, 0, \"Mobile.setMobileDirection\", playerId, 5)\r\n    \tinvoke_custom(1000, 1, \"Mobile.setMobileAnimation\", moogrrRoyale, \"AnimMort\")\r\n    \tinvoke_custom(2500, 1, \"Particle.addParticleSystem\", apsTransfo, 13, 0, 0)\r\n    \tinvoke_custom(2501, 1, \"Particle.addParticleSystem\", apsTransfo, 13, 0, 0)\r\n    \tinvoke_custom(2502, 1, \"Particle.addParticleSystem\", apsTransfo, 13, 0, 0)\r\n    \tinvoke_custom(2700, 1, \"Actor.deleteActor\", moogrrRoyale)\r\n    \tinvoke_custom(3200, 1, \"Mobile.setMobileVisible\", mobileMoorghueurite, true)\r\n    \r\n    \tinvoke_custom(2500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Help\")\r\n    \r\n    \tinvoke_custom(7500, 1, \"Mobile.moveMobile\", mobileMoorghueurite, 16, 0, 0)\r\n    \tinvoke_custom(8500, 1, \"Mobile.moveMobile\", playerId, 17, 1, 0, \"Mobile.setMobileDirection\", playerId, 7)\r\n    \tinvoke_custom(10000, 1, \"Mobile.moveMobile\", mobileMoorghueurite, 32, 0, 0)\r\n    \tinvoke_custom(10000, 1, \"Mobile.setMobileDirection\", playerId, 1)\r\n    \r\n    \t----------------------------- DIALOGUES --------------------------\r\n    \r\n    \t-- ... Moorghueurite ?!\r\n    \tinvoke_custom(4500, 1, \"bubble\", playerId, \"quest.amakna.mercenary.moogrr.07.01\")\r\n    \tinvoke_custom(4500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    \r\n    \tinvoke_custom(6000, 1, \"Mobile.setMobileAnimation\", mobileMoorghueurite, \"AnimSort-CridAmoogr\")\r\n    \r\n    \tinvoke_custom(12000, 1, \"bubble\", playerId, \"quest.amakna.mercenary.moogrr.07.02\")\r\n    \tinvoke_custom(12000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmoteMarket-HausseEpaules\")\r\n    \r\n    \r\n    \t----------------------------- FIN DE CINEMATIQUE --------------------------\r\n    \r\n    \tinvoke_custom(15000, 1, \"Mobile.moveMobile\", playerId, playerX, playerY, playerZ)\r\n    \tinvoke_custom(15000, 1, \"Mobile.setMobileVisible\", mobileMoorghueurite, false)\r\n    \t\r\n    \tinvoke_custom(15050, 1, \"skipCinematic\", 23675)\nend\n\n-- FIGHT_ENTER_ACTION_PHASE - Applique l'état \"Neo-Corruption\"\n-- \nfunction event_2682_23897()\n    \nend\n\n-- [NEO][ARCHI] Apparition de l'Archimonstre\n-- \nfunction event_2682_23946()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","displayPath","event_2682_23669","event_2682_23670","event_2682_23671","event_2682_23672","event_2682_23673","event_2682_23674","event_2682_23675","event_2682_23897","event_2682_23946"],"quest_calls":[],"dialogue_calls":[]},"scenario/2683.lua":{"source":"-- Infos stèle d'intervention\r\nfunction updateInterventionInfo(stateInfoId, forceDisplayUI)\r\n\r\n\tif (bubbleSteleInfoId == 0) then\r\n\t\tbubbleSteleInfoId = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_WEST\", 0, -60, false, 2147483647, true, \"interactiveBubbleDialog5\", 30000, 25000, \"onSteleInfoClosed\")\r\n\tend\r\n\r\n\tBubbleText.setText(bubbleSteleInfoId, stateInfoId)\r\n\t\r\n\tif (forceDisplayUI) then BubbleText.show(bubbleSteleInfoId) end\r\nend\n\n-- [INIT] Variables Globales\n-- \nfunction event_2683_23676()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2683_23677(steleIntervention)\n    local stele = toLong(steleIntervention)\r\n    \r\n    if stele >= 1 then\r\n    Sound.playForcedMusic(210172)\r\n    else\r\n    end\nend\n\n-- USER_GROUP_KILLED - Salle 01\n-- \nfunction event_2683_23678(room)\n    \nend\n\n-- USER_GROUP_KILLED - Salle 02\n-- \nfunction event_2683_23679(room)\n    \nend\n\n-- USER_GROUP_KILLED - Salle 03 - BOSS\n-- \nfunction event_2683_23680()\n    \nend\n\n-- FIGHT_ENDED - On rend les monstres inattaquables\n-- \nfunction event_2683_23681(steleIntervention)\n    local stele = toLong(steleIntervention)\r\n    \r\n    if stele >= 1 then\r\n    Sound.playForcedMusic(210172)\r\n    else\r\n    end\nend\n\n-- MONSTER_ACTION_EVENT -  Lancement du combat du Boss\n-- On rend les ***** de portes walkable\nfunction event_2683_23682()\n    \nend\n\n-- Déplace le joueur vers la salle suivante\n-- \nfunction event_2683_23683()\n    \nend\n\n-- [ADMIN] Apparition du boss\n-- \nfunction event_2683_23684(boss, mobA, mobB, mobC, mobD, mobE, mobF, mobG)\n    local boss = toLong(boss)\r\n    local mobA = toLong(mobA)\r\n    local mobB = toLong(mobB)\r\n    local mobC = toLong(mobC)\r\n    local mobD = toLong(mobD)\r\n    local mobE = toLong(mobE)\r\n    local mobF = toLong(mobF)\r\n    local mobG = toLong(mobG)\r\n    \r\n    Mobile.setMobileVisible(mobA, false)\r\n    Mobile.setMobileVisible(mobB, false)\r\n    Mobile.setMobileVisible(mobC, false)\r\n    Mobile.setMobileVisible(mobD, false)\r\n    Mobile.setMobileVisible(mobE, false)\r\n    Mobile.setMobileVisible(mobF, false)\r\n    Mobile.setMobileVisible(mobG, false)\r\n    Mobile.setMobileAnimation(boss, \"AnimApparition\")\nend\n\n-- GENERIC_ACTIVABLE_ACTION - Activation Stèle d'intervention\n-- \nfunction event_2683_23685(mobA, boss)\n    UI.openRewardsDialog(\"stele.intervention.description.3\")\r\n    \r\n    UI.addReward(30774)\r\n    UI.addReward(30701)\r\n    UI.addReward(30702)\r\n    \r\n    local stateInfoId = \"stele.intervention.momore.description\"\r\n    \r\n    updateInterventionInfo(stateInfoId, true)\r\n    \r\n    local cireId = toLong(mobA)\r\n    local bossId = toLong(boss)\r\n    \r\n    Mobile.setMobileAnimation(cireId, \"AnimApparition\")\r\n    Mobile.setMobileAnimation(bossId, \"AnimApparition\")\r\n    Sound.playSound(300183905357901, true, 50)\r\n    Effect.createCameraShakeEffect(100, 500, 100, 5, 100, \"BOTH\")\r\n    \r\n    Sound.playForcedMusic(210172)\nend\n\n-- INTERACTIVE_ELEMENT_ACTIVATION - Le joueur examine la Stèle d'intervention\n-- \nfunction event_2683_23686()\n    UI.openRewardsDialog(\"stele.intervention.description.3\")\r\n    \r\n    UI.addReward(30774)\r\n    UI.addReward(30701)\r\n    UI.addReward(30702)\r\n    \r\n    local stateInfoId = \"stele.intervention.momore.description\"\r\n    \r\n    updateInterventionInfo(stateInfoId, true)\nend\n\n-- FIGHT_STARTED / EXIT_INSTANCE - Musique Cire Momore\n-- \nfunction event_2683_23687()\n    Sound.stopForcedMusic()\nend\n\n-- FIGHT_ENTER_ACTION_PHASE - Applique l'état \"Neo-Corruption\"\n-- \nfunction event_2683_23898()\n    \nend\n\n","functions":["updateInterventionInfo","event_2683_23676","event_2683_23677","event_2683_23678","event_2683_23679","event_2683_23680","event_2683_23681","event_2683_23682","event_2683_23683","event_2683_23684","event_2683_23685","event_2683_23686","event_2683_23687","event_2683_23898"],"quest_calls":["UI.openRewardsDialog(\"stele.intervention.description.3\")\r","UI.openRewardsDialog(\"stele.intervention.description.3\")\r"],"dialogue_calls":[]},"scenario/2684.lua":{"source":"\n\n-- [INIT] Variables Globales\n-- \nfunction event_2684_23688()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2684_23689()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 01\n-- \nfunction event_2684_23690()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 02\n-- \nfunction event_2684_23691()\n    invoke(4000, 1, \"Particle.addParticleSystem\", 800202, -21, 19, -24, 0)\nend\n\n-- USER_GROUP_KILLED - Salle 03 - BOSS\n-- \nfunction event_2684_23693()\n    \nend\n\n-- Déplace le joueur vers la salle suivante\n-- \nfunction event_2684_23694()\n    \nend\n\n-- [RECEPTACLE] Ouverture du warp\n-- \nfunction event_2684_23695()\n    invoke(0, 1, \"Particle.addParticleSystem\", 800202, -21, 19, -24, 0)\nend\n\n-- [EVENT] On rend les monstres de la salle du boss inattaquable\n-- Cela nous permet d'éviter d'avoir la mauvaise bulle de combat sur le combat du boss\nfunction event_2684_23696()\n    \nend\n\n-- FIGHT_ENTER_ACTION_PHASE - Applique l'état \"Neo-Corruption\"\n-- \nfunction event_2684_23899()\n    \nend\n\n-- [NEO][ARCHI] Apparition de l'Archimonstre\n-- \nfunction event_2684_23958()\n    \nend\n\n","functions":["event_2684_23688","event_2684_23689","event_2684_23690","event_2684_23691","event_2684_23693","event_2684_23694","event_2684_23695","event_2684_23696","event_2684_23899","event_2684_23958"],"quest_calls":[],"dialogue_calls":[]},"scenario/2685.lua":{"source":"playerId = Context.getLeaderId()\r\n\r\nfunction gouleTurn(mobileId, direction)\r\n\tMobile.setMobileDirection(mobileId, direction)\r\nend\r\n\r\nfunction gouleVisible(mobileId, bool)\r\n\tMobile.setMobileVisible(mobileId, bool)\r\nend\r\n\r\nfunction goulePouf(mobileId)\r\n\tMobile.setMobileAnimation(mobileId, \"AnimSort-Teleportation-Fin\")\r\nend\n\n-- [INITIALISATION] Variables\n-- \nfunction event_2685_23697()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2685_23698(goulouBA, goulouBB, goulouBC, gouleBA, gouleBB, gouleBC, gouleBD, goulouCA, goulouCB, goulouCC, dodueCA, dodueCB, dodueCC, dodueCD)\n    --Mobile.addMobileCreationCallback(goulouBA, \"gouleTurn\", goulouBA, 1)\n    --Mobile.addMobileCreationCallback(goulouBB, \"gouleTurn\", goulouBB, 1)\n    --Mobile.addMobileCreationCallback(goulouBC, \"gouleTurn\", goulouBC, 5)\n    --Mobile.addMobileCreationCallback(gouleBA, \"gouleTurn\", gouleBA, 7)\n    --Mobile.addMobileCreationCallback(gouleBB, \"gouleTurn\", gouleBB, 5)\n    --Mobile.addMobileCreationCallback(gouleBC, \"gouleTurn\", gouleBC, 5)\n    --Mobile.addMobileCreationCallback(gouleBD, \"gouleTurn\", gouleBD, 3)\n    Mobile.addMobileCreationCallback(goulouCA, \"gouleTurn\", goulouCA, 3)\r\n    Mobile.addMobileCreationCallback(goulouCB, \"gouleTurn\", goulouCB, 5)\r\n    Mobile.addMobileCreationCallback(goulouCC, \"gouleTurn\", goulouCC, 5)\r\n    Mobile.addMobileCreationCallback(dodueCA, \"gouleTurn\", dodueCA, 7)\r\n    Mobile.addMobileCreationCallback(dodueCB, \"gouleTurn\", dodueCB, 7)\r\n    Mobile.addMobileCreationCallback(dodueCC, \"gouleTurn\", dodueCC, 5)\r\n    Mobile.addMobileCreationCallback(dodueCD, \"gouleTurn\", dodueCD, 5)\nend\n\n-- [01][SCENE] Le joueur entre dans la salle\n-- \nfunction event_2685_23699(gouleOne, gouleTwo, gouleThree, gouleFour, gouleFive, gouleSix, gouleSeven)\n    function gouleStart(gouleOne,gouleTwo,gouleThree,gouleFour,gouleFive,gouleSix,gouleSeven)\r\n    \t--Camera.setWorldTarget(11, -12, 0)\r\n    \tMobile.setMobileDirection(gouleOne, 3)\r\n    \tMobile.setMobileDirection(gouleTwo, 3)\r\n    \tMobile.setMobileDirection(gouleThree, 5)\r\n    \tMobile.setMobileDirection(gouleFour, 5)\r\n    \tMobile.setMobileDirection(gouleFive, 7)\r\n    \tMobile.setMobileDirection(gouleSix, 1)\r\n    \tMobile.setMobileDirection(gouleSeven, 1)\r\n    \tMobile.setMobileAnimation(gouleOne, \"AnimSort-Teleportation-Fin\")\r\n    \tMobile.setMobileAnimation(gouleTwo, \"AnimSort-Teleportation-Fin\")\r\n    \tMobile.setMobileAnimation(gouleThree, \"AnimSort-Teleportation-Fin\")\r\n    \tMobile.setMobileAnimation(gouleFour, \"AnimSort-Teleportation-Fin\")\r\n    \tMobile.setMobileAnimation(gouleFive, \"AnimSort-Teleportation-Fin\")\r\n    \tMobile.setMobileAnimation(gouleSix, \"AnimSort-Teleportation-Fin\")\r\n    \tMobile.setMobileAnimation(gouleSeven, \"AnimSort-Teleportation-Fin\")\r\n    end\r\n    \r\n    \r\n    trace(\"LE TRIGGER DE LA SALLE 01 EST ACTIVE\")\r\n    gouleStart(gouleOne,gouleTwo,gouleThree,gouleFour,gouleFive,gouleSix,gouleSeven)\nend\n\n-- [01][SCENE] Déclenchement du Combat\n-- \nfunction event_2685_23700(gouleOne, gouleTwo, gouleThree, gouleFour, gouleFive, gouleSix)\n    \nend\n\n-- [01][DEFI] Lancement\n-- \nfunction event_2685_23701()\n    UI.openRewardsDialog(\"defi.donjon.vampyro.01\")\r\n    trace(\"LE PREMIER COMBAT EST LANCE\")\nend\n\n-- [01][DEFI] Un des joueurs échoue\n-- \nfunction event_2685_23702()\n    trace(\"LE PREMIER COMBAT EST PERDU\")\nend\n\n-- [01][DEFI] Combat gagné\n-- \nfunction event_2685_23703()\n    trace(\"LE PREMIER COMBAT EST GAGNE\")\nend\n\n-- [01][DEFI] Un des joueurs échoue - Résolution NO\n-- \nfunction event_2685_23704(defi, fightA)\n    UI.displaySplashText(\"defi.donjon.vampyro.lost\")\r\n    trace(\"DEFI =\", defi)\r\n    trace(\"fightA = \", fightA)\nend\n\n-- [01][DEFI] Résolution OK\n-- \nfunction event_2685_23705(defi, fightA)\n    UI.displaySplashText(\"defi.donjon.win\")\nend\n\n-- [OLD][02][DEFI] Lancement\n-- \nfunction event_2685_23706()\n    UI.openRewardsDialog(\"defi.donjon.vampyro.01\")\nend\n\n-- [OLD][02][DEFI] Un des joueurs échoue\n-- \nfunction event_2685_23707()\n    \nend\n\n-- [OLD][02][DEFI] Combat gagné\n-- \nfunction event_2685_23708()\n    \nend\n\n-- [OLD][02][DEFI] Un des joueurs échoue - Résolution NO\n-- \nfunction event_2685_23709()\n    UI.displaySplashText(\"defi.donjon.vampyro.lost\")\nend\n\n-- [OLD][02][DEFI] Résolution OK\n-- \nfunction event_2685_23710()\n    UI.displaySplashText(\"defi.donjon.win\")\nend\n\n-- [03][DEFI] Lancement\n-- \nfunction event_2685_23711()\n    UI.openRewardsDialog(\"defi.donjon.vampyro.01\")\nend\n\n-- [03][DEFI] Un des joueurs échoue\n-- \nfunction event_2685_23712()\n    \nend\n\n-- [03][DEFI] Un des joueurs échoue - Résolution NO\n-- \nfunction event_2685_23714()\n    UI.displaySplashText(\"defi.donjon.vampyro.lost\")\nend\n\n-- [03][DEFI] Résolution OK\n-- \nfunction event_2685_23715()\n    UI.displaySplashText(\"defi.donjon.win\")\nend\n\n-- [03] Téléportation des joueurs à la fin du combat (déblocage éventuel)\n-- \nfunction event_2685_23716()\n    \nend\n\n-- [03][COMBAT] Glyphes\n-- \nfunction event_2685_23717()\n    \nend\n\n-- [04][COMBAT] Mort du boss\n-- \nfunction event_2685_23718()\n    \nend\n\n-- [04][SCENE] Le joueur entre dans la salle\n-- \nfunction event_2685_23719(gouleDA, gouleDB, gouleDC, gouleDD, gouleDE, gouleDF, vampyro)\n    function gouleStart(gouleDA,gouleDB,gouleDC,gouleDD,gouleDE,gouleDF,vampyro)\r\n    \tCamera.setWorldTarget(11, -125, 4)\r\n    \tMobile.addMobileCreationCallback(gouleDA, \"gouleTurn\", gouleDA, 3)\r\n    \tMobile.addMobileCreationCallback(gouleDB, \"gouleTurn\", gouleDB, 3)\r\n    \tMobile.addMobileCreationCallback(gouleDC, \"gouleTurn\", gouleDC, 3)\r\n    \tMobile.addMobileCreationCallback(gouleDD, \"gouleTurn\", gouleDD, 3)\r\n    \tMobile.addMobileCreationCallback(gouleDE, \"gouleTurn\", gouleDE, 3)\r\n    \tMobile.addMobileCreationCallback(gouleDF, \"gouleTurn\", gouleDF, 3)\r\n    \tMobile.addMobileCreationCallback(vampyro, \"gouleTurn\", vampyro, 3)\r\n    \tMobile.addMobileCreationCallback(gouleDA, \"gouleVisible\", gouleDA, false)\r\n    \tMobile.addMobileCreationCallback(gouleDB, \"gouleVisible\", gouleDB, false)\r\n    \tMobile.addMobileCreationCallback(gouleDC, \"gouleVisible\", gouleDC, false)\r\n    \tMobile.addMobileCreationCallback(gouleDD, \"gouleVisible\", gouleDD, false)\r\n    \tMobile.addMobileCreationCallback(gouleDE, \"gouleVisible\", gouleDE, false)\r\n    \tMobile.addMobileCreationCallback(gouleDF, \"gouleVisible\", gouleDF, false)\r\n    \tMobile.addMobileCreationCallback(vampyro, \"gouleVisible\", vampyro, false)\r\n    \tinvoke(1300, 1, \"vampyroStart\",gouleDA,gouleDB,gouleDC,gouleDD,gouleDE,gouleDF,vampyro)\r\n    end\r\n    \r\n    function vampyroStart(gouleDA,gouleDB,gouleDC,gouleDD,gouleDE,gouleDF,vampyro)\r\n    \tMobile.addMobileCreationCallback(vampyro, \"gouleVisible\", vampyro, true)\r\n    \tMobile.setMobileAnimation(vampyro, \"AnimApparition\", \"Mobile.setMobileAnimation\", vampyro, \"AnimSort-VampyroStyle\")\r\n    \tinvoke(2300, 1, \"GouleApp\",gouleDA,gouleDB,gouleDC,gouleDD,gouleDE,gouleDF,vampyro)\r\n    end\r\n    \r\n    function GouleApp(gouleDA,gouleDB,gouleDC,gouleDD,gouleDE,gouleDF,vampyro)\r\n    \tMobile.addMobileCreationCallback(gouleDA, \"gouleVisible\", gouleDA, true)\r\n    \tMobile.addMobileCreationCallback(gouleDB, \"gouleVisible\", gouleDB, true)\r\n    \tMobile.addMobileCreationCallback(gouleDC, \"gouleVisible\", gouleDC, true)\r\n    \tMobile.addMobileCreationCallback(gouleDD, \"gouleVisible\", gouleDD, true)\r\n    \tMobile.addMobileCreationCallback(gouleDE, \"gouleVisible\", gouleDE, true)\r\n    \tMobile.addMobileCreationCallback(gouleDF, \"gouleVisible\", gouleDF, true)\r\n    \tMobile.addMobileCreationCallback(gouleDA, \"goulePouf\", gouleDA)\r\n    \tMobile.addMobileCreationCallback(gouleDB, \"goulePouf\", gouleDB)\r\n    \tMobile.addMobileCreationCallback(gouleDC, \"goulePouf\", gouleDC)\r\n    \tMobile.addMobileCreationCallback(gouleDD, \"goulePouf\", gouleDD)\r\n    \tMobile.addMobileCreationCallback(gouleDE, \"goulePouf\", gouleDE)\r\n    \tMobile.addMobileCreationCallback(gouleDF, \"goulePouf\", gouleDF)\r\n    \tCamera.attachCameraToMobile(playerId)\r\n    end\r\n    \r\n    gouleStart(gouleDA,gouleDB,gouleDC,gouleDD,gouleDE,gouleDF,vampyro)\r\n    \r\n    \r\n    \r\nend\n\n-- [04][SCENE] Déclenchement du Combat\n-- \nfunction event_2685_23720(gouleOne, gouleTwo, gouleThree, gouleFour, gouleFive, gouleSix)\n    \nend\n\n-- [04][COMBAT] Glyphes\n-- \nfunction event_2685_23721()\n    \nend\n\n-- FIGHT_ENTER_ACTION_PHASE - Applique l'état \"Neo-Corruption\"\n-- \nfunction event_2685_23900()\n    \nend\n\n","functions":["gouleTurn","gouleVisible","goulePouf","event_2685_23697","event_2685_23698","event_2685_23699","gouleStart","event_2685_23700","event_2685_23701","event_2685_23702","event_2685_23703","event_2685_23704","event_2685_23705","event_2685_23706","event_2685_23707","event_2685_23708","event_2685_23709","event_2685_23710","event_2685_23711","event_2685_23712","event_2685_23714","event_2685_23715","event_2685_23716","event_2685_23717","event_2685_23718","event_2685_23719","gouleStart","vampyroStart","GouleApp","event_2685_23720","event_2685_23721","event_2685_23900"],"quest_calls":["UI.openRewardsDialog(\"defi.donjon.vampyro.01\")\r","UI.openRewardsDialog(\"defi.donjon.vampyro.01\")","UI.openRewardsDialog(\"defi.donjon.vampyro.01\")"],"dialogue_calls":[]},"scenario/2686.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\nfunction hideMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, false)\r\nend\r\n\r\nfunction showMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, true)\r\nend\n\n-- [INIT] Variables\n-- \nfunction event_2686_23722()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2686_23723(npcId, bossId, doorOpened)\n    local doorOpened = toLong(doorOpened)\r\n    \r\n    if (doorOpened == 1) then\r\n    \tMobile.addMobileCreationCallback(npcId, \"hideMonster\", npcId)\r\n    else\r\n    \tMobile.addMobileCreationCallback(bossId, \"hideMonster\", bossId)\r\n    end\nend\n\n-- FIGHT_ENTER_ACTION_PHASE - Pose des glyphes\n-- \nfunction event_2686_23725()\n    \nend\n\n-- FIGHT_STARTED - Actions de début de combat\n-- \nfunction event_2686_23726()\n    \nend\n\n-- DIALOG_EXECUTED - Apparition du vrai CN\n-- \nfunction event_2686_23727(bossId, npcId)\n    function customSkip()\r\n    \tUI.displayWideScreenBand(true, 25, 300)\r\n    \tMobile.setMobileVisible(npcId, false)\r\n    \tMobile.setMobileVisible(bossId, true)\r\n    \tskipCinematic()\r\n    end\r\n        \t\r\n    startCinematicContext(1.2, npcId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"customSkip\")\r\n    \r\n    -- \"Bougez pas, je reviens !\"\r\n    invoke_custom(00500, 1, \"Sound.playSound\", 310101101151303, true, 40)\r\n    invoke_custom(00500, 1, \"bubble\", npcId, \"black.crow.fight.02\")\r\n    invoke_custom(03000, 1, \"clearBubbles\", npcId)\r\n    \r\n    invoke_custom(03000, 1, \"UI.displayWideScreenBand\", true, 100, 300)\r\n    invoke_custom(05000, 1, \"Mobile.setMobileVisible\", npcId, false)\r\n    invoke_custom(05000, 1, \"Mobile.setMobileVisible\", bossId, true)\r\n    invoke_custom(05000, 1, \"Camera.attachCameraToMobile\", bossId)\r\n    \r\n    invoke_custom(05500, 1, \"UI.displayWideScreenBand\", true, 25, 300)\r\n    invoke_custom(05500, 1, \"Mobile.setMobileAnimation\", bossId, \"AnimSort-Envol-Fin\")\r\n    \r\n    -- \"Vous allez bientôt pouvoir rencontrer votre créateur...\"\r\n    invoke_custom(06000, 1, \"Sound.playSound\", 320001020007011, true, 40)\r\n    invoke_custom(06000, 1, \"bubble\", bossId, \"black.crow.fight.01\")\r\n    invoke_custom(09000, 1, \"clearBubbles\", bossId)\r\n    \r\n    invoke_custom(09000, 1, \"skipCinematic\")\nend\n\n-- CLIENT_TRIGGERED_EVENT - On skip chez tout le monde\n-- \nfunction event_2686_23728(npcId, bossId)\n    UI.displayWideScreenBand(true, 25, 300)\r\n    Mobile.setMobileVisible(npcId, false)\r\n    Mobile.setMobileVisible(bossId, true)\r\n    skipCinematic()\nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","hideMonster","showMonster","event_2686_23722","event_2686_23723","event_2686_23725","event_2686_23726","event_2686_23727","customSkip","event_2686_23728"],"quest_calls":[],"dialogue_calls":[]},"scenario/2687.lua":{"source":"bubbleSteleInfoId = 0\r\nbubbleFightInfoId = 0\r\n\r\nfunction closeFightInfo()\r\n\tif (bubbleFightInfoId ~= nil  and bubbleFightInfoId ~= 0) then BubbleText.close(bubbleFightInfoId) end\r\nend\r\n\r\nfunction onFightInfoClosed()\r\n\tif (bubbleFightInfoId ~= nil  and bubbleFightInfoId ~= 0) then bubbleFightInfoId = 0 end\r\nend\r\n\r\n\r\nfunction closeSteleInfo()\r\n\tif (bubbleSteleInfoId ~= nil  and bubbleSteleInfoId ~= 0) then BubbleText.close(bubbleSteleInfoId) end\r\nend\r\n\r\nfunction onSteleInfoClosed()\r\n\tif (bubbleSteleInfoId ~= nil  and bubbleSteleInfoId ~= 0) then bubbleSteleInfoId = 0 end\r\nend\r\n\r\nfunction updateSteleInfoOverride(stateInfoId, forceDisplayUI)\r\n    local stateInfoId = tostring(stateInfoId)\r\n\r\n    if (bubbleSteleInfoId == 0) then\r\n        bubbleSteleInfoId = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_WEST\", 0, -60, false, 2147483647, true, \"interactiveBubbleDialog5\", 30000, 25000, \"onSteleInfoClosed\")\r\n    end\r\n\r\n    BubbleText.setText(bubbleSteleInfoId, stateInfoId)\r\n\r\n    if (forceDisplayUI) then BubbleText.show(bubbleSteleInfoId) end\r\nend\r\n\r\nfunction updateFightInfo(steleIntervention, shiftOne, shiftTwo, shiftThree, forceDisplayUI)\r\n\tlocal steleIntervention = toLong(steleIntervention)\r\n\tlocal shiftOne = toLong(shiftOne)\r\n\tlocal shiftTwo = toLong(shiftTwo)\r\n\tlocal shiftThree = toLong(shiftThree)\r\n\r\n\tif (bubbleFightInfoId == 0) then\r\n\t\tbubbleFightInfoId = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_WEST\", 0, -110, false, 2147483647, true, \"interactiveBubbleDialog5\", 30000, 25000, \"onFightInfoClosed\")\r\n\tend\r\n\r\n\tBubbleText.setText(bubbleFightInfoId, \"confusionhoraire.fight.player.infos\", steleIntervention, shiftOne, shiftTwo, shiftThree)\r\n\r\n\tif (forceDisplayUI) then BubbleText.show(bubbleFightInfoId) end\r\nend\n\n-- [INIT] Variables Globales\n-- \nfunction event_2687_23733()\n    \nend\n\n-- [INIT] Inscription du joueur + Variables Locales\n-- \nfunction event_2687_23734(callbackPasserelle)\n    local state = toLong(callbackPasserelle)\r\n    \r\n    displayPath(state)\nend\n\n-- USER_GROUP_KILLED - Salle 01\n-- \nfunction event_2687_23735()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 02 - BOSS\n-- \nfunction event_2687_23738()\n    \nend\n\n-- Déplace le joueur vers la salle suivante\n-- \nfunction event_2687_23739()\n    \nend\n\n-- FIGHT_ENTER_ACTION_PHASE - Applique l'état \"Donjon\" (Salle 1)\n-- \nfunction event_2687_23740()\n    \nend\n\n-- FIGHT_ENTER_ACTION_PHASE - Applique l'état \"Neo-Corruption\"\n-- \nfunction event_2687_23901()\n    \nend\n\n","functions":["closeFightInfo","onFightInfoClosed","closeSteleInfo","onSteleInfoClosed","updateSteleInfoOverride","updateFightInfo","event_2687_23733","event_2687_23734","event_2687_23735","event_2687_23738","event_2687_23739","event_2687_23740","event_2687_23901"],"quest_calls":[],"dialogue_calls":[]},"scenario/2688.lua":{"source":"\n\n-- [INIT] Variables Globales\n-- \nfunction event_2688_23748()\n    \nend\n\n-- [INIT] Inscription du joueur + Variables Locales\n-- \nfunction event_2688_23749()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 01\n-- \nfunction event_2688_23750()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 02\n-- \nfunction event_2688_23751()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 03 - BOSS\n-- \nfunction event_2688_23752()\n    World.setPictoAlpha(-18, -42, -10, 0, 500)\r\n    World.setPictoAlpha(-18, -42, -12, 0, 500)\r\n    World.setPictoAlpha(-18, -42, -34, 0, 500)\r\n    World.setPictoAlpha(-18, -42, -41, 0, 500)\r\n    World.setPictoAlpha(-18, -43, -4, 0, 500)\r\n    World.setPictoAlpha(-18, -43, -19, 0, 500)\r\n    World.setPictoAlpha(-18, -43, -33, 0, 500)\r\n    World.setPictoAlpha(-18, -44, -41, 0, 500)\r\n    World.setPictoAlpha(-18, -45, -41, 0, 500)\r\n    World.setPictoAlpha(-18, -44, -17, 0, 500)\r\n    World.setPictoAlpha(-18, -44, -31, 0, 500)\r\n    \r\n    World.setPictoAlpha(-18, -43, -5, 0, 500)\r\n    World.setPictoAlpha(-17, -44, -41, 0, 500)\r\n    World.setPictoAlpha(-18, -42, -34, 0, 500)\r\n    World.setPictoAlpha(-18, -42, -41, 0, 500)\nend\n\n-- Déplace le joueur vers la salle suivante\n-- \nfunction event_2688_23753()\n    \nend\n\n-- [EVENT] Lancement du combat du Boss\n-- On rend les ***** de portes walkable\nfunction event_2688_23754()\n    \nend\n\n-- [EVENT] Lancement du combat du Boss - Spawn des glyphes invoc\n-- \nfunction event_2688_23755()\n    \nend\n\n-- [EVENT] Fin du combat du Boss - On remet les portes bloquantes\n-- \nfunction event_2688_23756()\n    \nend\n\n-- [STELE] FIGHT_STARTED - On applique les difficultés stèles\n-- \nfunction event_2688_23759()\n    \nend\n\n-- [STELE] FIGHT_ENTER_ACTION_PHASE - On applique les bonus sur les joueurs\n-- \nfunction event_2688_23760()\n    \nend\n\n-- [STELE] FIGHT_ENDED - On rend la stèle utilisable en cas de défaite\n-- \nfunction event_2688_23761()\n    \nend\n\n-- FIGHT_ENTER_ACTION_PHASE - Applique l'état \"Neo-Corruption\"\n-- \nfunction event_2688_23902()\n    \nend\n\n-- [NEO][ARCHI] Apparition de l'Archimonstre\n-- \nfunction event_2688_23978()\n    \nend\n\n","functions":["event_2688_23748","event_2688_23749","event_2688_23750","event_2688_23751","event_2688_23752","event_2688_23753","event_2688_23754","event_2688_23755","event_2688_23756","event_2688_23759","event_2688_23760","event_2688_23761","event_2688_23902","event_2688_23978"],"quest_calls":[],"dialogue_calls":[]},"scenario/2689.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\nbubbleSteleInfoId = 0\r\n\r\nfunction openDoor()\r\n\tInteractiveElement.setAnimation(35328, \"AnimTrans_1_0\")\r\nend\r\n\r\nfunction closeSteleInfo()\r\n\tif (bubbleSteleInfoId ~= nil  and bubbleSteleInfoId ~= 0) then BubbleText.close(bubbleSteleInfoId) end\r\nend\r\n\r\nfunction onSteleInfoClosed()\r\n\tif (bubbleSteleInfoId ~= nil  and bubbleSteleInfoId ~= 0) then bubbleSteleInfoId = 0 end\r\nend\r\n\r\nfunction updateSteleInfo(stateInfoId, forceDisplayUI)\r\n\r\n\tif (bubbleSteleInfoId == 0) then\r\n\t\tbubbleSteleInfoId = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_WEST\", 0, -60, false, 2147483647, true, \"interactiveBubbleDialog5\", 30000, 25000, \"onSteleInfoClosed\")\r\n\tend\r\n\r\n\tBubbleText.setText(bubbleSteleInfoId, stateInfoId)\r\n\t\r\n\tif (forceDisplayUI) then BubbleText.show(bubbleSteleInfoId) end\r\nend\n\n-- [INIT] Variables & Constantes\n-- \nfunction event_2689_23762()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2689_23763()\n    openDoor()\nend\n\n-- INTERACTIVE_ELEMENT_ACTIVATION - Ouverture de la porte\n-- \nfunction event_2689_23764()\n    trace(\"OUVERTURE DE LA PORTE\")\r\n    \r\n    openDoor()\nend\n\n-- MONSTER_ACTION_EVENT - Lancement du combat\n-- \nfunction event_2689_23765()\n    \nend\n\n-- [FIGHT] Fin du combat - Reset les stèles\n-- \nfunction event_2689_23766()\n    \nend\n\n-- [STELE] Le joueur examine une stèle\n-- \nfunction event_2689_23767(steleCount, steleStateId)\n    local steleCount = toLong(steleCount)\r\n    local steleStateId = toLong(steleStateId)\r\n    \r\n    if (steleCount == 0) then\r\n    UI.openRewardsDialog(\"stele.description.tour\")\r\n    UI.addReward(22759)\r\n    UI.addReward(17321)\r\n    UI.addReward(27083, \"stele.reward.stasis.21\")\r\n    \r\n    elseif (steleCount == 1) then\r\n    UI.openRewardsDialog(\"stele.description.tour\")\r\n    UI.addReward(22758)\r\n    UI.addReward(22763)\r\n    UI.addReward(27083, \"stele.reward.stasis.21\")\r\n    \r\n    elseif (steleCount == 2) then\r\n    UI.openRewardsDialog(\"stele.description.tour\")\r\n    UI.addReward(17317)\r\n    UI.addReward(17322, \"stele.reward.stasis.21\")\r\n    UI.addReward(27083, \"stele.reward.stasis.21\")\r\n    \r\n    elseif (steleCount == 3) then\r\n    UI.openRewardsDialog(\"stele.description.tour\")\r\n    UI.addReward(17318)\r\n    UI.addReward(17332, \"stele.reward.stasis.21\")\r\n    UI.addReward(27083, \"stele.reward.stasis.21\")\r\n    \r\n    \r\n    else\r\n    \r\n    end\r\n    \r\n    local stateInfoId = \"stele.state.description.\" .. toString(steleStateId)\r\n    \r\n    updateSteleInfo(stateInfoId, true)\nend\n\n-- [STELE] Le joueur active une stèle\n-- \nfunction event_2689_23768(steleCount, steleStateId)\n    local steleCount = toLong(steleCount)\r\n    local steleStateId = toLong(steleStateId)\r\n    \r\n    if (steleCount == 1) then\r\n    UI.openRewardsDialog(\"stele.description.tour\")\r\n    UI.addReward(22759)\r\n    UI.addReward(17321)\r\n    UI.addReward(27083, \"stele.reward.stasis.21\")\r\n    \r\n    elseif (steleCount == 2) then\r\n    UI.openRewardsDialog(\"stele.description.tour\")\r\n    UI.addReward(22758)\r\n    UI.addReward(22763)\r\n    UI.addReward(27083, \"stele.reward.stasis.21\")\r\n    \r\n    elseif (steleCount == 3) then\r\n    UI.openRewardsDialog(\"stele.description.tour\")\r\n    UI.addReward(17317)\r\n    UI.addReward(17322, \"stele.reward.stasis.21\")\r\n    UI.addReward(27083, \"stele.reward.stasis.21\")\r\n    \r\n    elseif (steleCount == 4) then\r\n    UI.openRewardsDialog(\"stele.description.tour\")\r\n    UI.addReward(17318)\r\n    UI.addReward(17332, \"stele.reward.stasis.21\")\r\n    UI.addReward(27083, \"stele.reward.stasis.21\")\r\n    \r\n    \r\n    else\r\n    \r\n    end\r\n    \r\n    local stateInfoId = \"stele.state.description.\" .. toString(steleStateId)\r\n    \r\n    updateSteleInfo(stateInfoId, true)\nend\n\n-- [STELE] Refresh des APS pour Stèles\n-- \nfunction event_2689_23769()\n    \nend\n\n-- [STASIS] DUNGEON_DIFFICULTY_CHANGED - Reset les stèles\n-- \nfunction event_2689_23770()\n    \nend\n\n-- FIGHT_ENTER_ACTION_PHASE - On bloque le passage vers le trône\n-- \nfunction event_2689_23773()\n    \nend\n\n-- [NEO][ARCHI] Apparition de l'Archimonstre\n-- \nfunction event_2689_24058()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","openDoor","closeSteleInfo","onSteleInfoClosed","updateSteleInfo","event_2689_23762","event_2689_23763","event_2689_23764","event_2689_23765","event_2689_23766","event_2689_23767","event_2689_23768","event_2689_23769","event_2689_23770","event_2689_23773","event_2689_24058"],"quest_calls":["UI.openRewardsDialog(\"stele.description.tour\")\r","UI.openRewardsDialog(\"stele.description.tour\")\r","UI.openRewardsDialog(\"stele.description.tour\")\r","UI.openRewardsDialog(\"stele.description.tour\")\r","UI.openRewardsDialog(\"stele.description.tour\")\r","UI.openRewardsDialog(\"stele.description.tour\")\r","UI.openRewardsDialog(\"stele.description.tour\")\r","UI.openRewardsDialog(\"stele.description.tour\")\r"],"dialogue_calls":[]},"scenario/2690.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_2690_23774()\n    \nend\n\n-- [INIT] Variables Globales\n-- \nfunction event_2690_23775()\n    \nend\n\n-- USER_GROUP_KILLED - Spawn du BOSS en Salle 01 (Passage en Salle 02)\n-- \nfunction event_2690_23776()\n    \nend\n\n-- USER_GROUP_KILLED - Salle 02 - BOSS\n-- \nfunction event_2690_23777(mobId)\n    \nend\n\n-- Déplace le joueur vers la salle suivante\n-- \nfunction event_2690_23778()\n    \nend\n\n-- [EVENT] Début du combat BOSS - Pose des zones flag\n-- \nfunction event_2690_23779()\n    \nend\n\n-- [EVENT] Victoire - Brise-Tibia - Cinématique spawn Remington\n-- On déclenche une cinématique  \nfunction event_2690_23780(bossRemington)\n    \t----------------------------- RECUPERATIONS DES INFOS JOUEUR --------------------------\r\n    \r\n    \tlocal playerId = Context.getLeaderId()\r\n    \r\n    \tlocal remingtonBossId = toLong(bossRemington)\r\n    \t\r\n    \t----------------------------- INITIALISATION DES PNJ --------------------------\r\n    \r\n    \tlocal apsTirRemington = -1022019405\r\n    \tlocal apsTirRemingtonImpact = -1042026792\r\n    \tlocal apsBouclier = 1018310\r\n    \r\n    \t----------------------------- SKIP DE CINEMATIQUE PAR LE BOUTON --------------------------\r\n    \r\n        \tfunction customSkip()\r\n        \t\tMobile.setMobilePosition(playerId, playerX, playerY, playerZ)\r\n         \t\tUI.displayWideScreenBand(true, 25, 300)\r\n    \t\t\t\tMobile.setMobilePosition(remingtonBossId, 47, 5, 0)\r\n           Mobile.setMobileVisible(remingtonBossId, true)\r\n        \t\tskipCinematic(20236)\r\n        \tend    \r\n    \r\n    \t----------------------------- DEBUT DE CINEMATIQUE --------------------------\r\n    \r\n    \tstartCinematicContext(1.2, remingtonBossId)\r\n    \t\r\n    \tUI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"customSkip\")\r\n    \r\n    \tinvoke_custom(1, 1, \"Mobile.setMobilePosition\", playerId, 39, 5, 0)\r\n    \tinvoke_custom(1, 1, \"Mobile.setMobileDirection\", playerId, 5)\r\n    \tinvoke_custom(1, 1, \"Mobile.setMobilePosition\", remingtonBossId, 42, 5, 2)\r\n    \tinvoke_custom(1, 1, \"Mobile.setMobileDirection\", remingtonBossId, 5)\r\n    \tinvoke_custom(1, 1, \"Mobile.setMobileVisible\", remingtonBossId, false)\r\n    \r\n    \r\n    \t----------------------------- ACTIONS + DIALOGUES --------------------------\r\n    \r\n    \t--invoke_custom(12000, 1, \"Mobile.moveMobile\", remingtonID, -80, -14, 8)\r\n    \r\n    \tinvoke_custom(01250, 1, \"Mobile.setMobileVisible\", remingtonBossId, true)\r\n    