tonID, \"quest.sufokia.mercenary.roublard.06.04\")\r\n    \r\n    \tinvoke_custom(19800, 1, \"Mobile.setMobileDirection\", remingtonID, 1)\r\n    \r\n    \t-- Toi. J'ai besoin du livre comme convenu, pas de roublardise cette fois, n'oublie pas que sans moi tu ne serais pas arrivé{[1*]?e:} ici.\r\n    \tinvoke_custom(19800, 1, \"clearBubbles\", remingtonID)\r\n    \tinvoke_custom(20000, 1, \"bubble\", remingtonID, \"quest.sufokia.mercenary.roublard.06.05\")\r\n    \r\n    \t-- Prenez ce que vous voulez mais oubliez nous !!!\r\n    \tinvoke_custom(26800, 1, \"clearBubbles\", remingtonID)\r\n    \tinvoke_custom(26900, 1, \"clearBubbles\", remingtonID)\r\n    \tinvoke_custom(27000, 1, \"bubble\", briseTibiaID, \"quest.sufokia.mercenary.roublard.06.06\")\r\n    \tinvoke_custom(27000, 1, \"Mobile.setMobileAnimation\", briseTibiaID, \"AnimComp-Combat03\")\r\n    \r\n    \t-- **Ils sont gonflés ceux la... On dirait que je vais devoir faire des choix.\r\n    \tinvoke_custom(30800, 1, \"clearBubbles\", briseTibiaID)\r\n    \tinvoke_custom(31000, 1, \"bubble\", playerId, \"quest.sufokia.mercenary.roublard.06.07\")\r\n    \tinvoke_custom(31000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    \r\n    \t----------------------------- FIN DE CINEMATIQUE --------------------------\r\n    \tinvoke_custom(35000, 1, \"UI.displayWideScreenBand\", true, 100, 300)\r\n    \tinvoke_custom(37999, 1, \"UI.displayWideScreenBand\", true, 25, 300)\r\n    \r\n    \tinvoke_custom(38000, 1, \"skipCinematic\", 20057)\nend\n\n-- [MERCENAIRE][EVENT] Fin Cinématique Remington - Tp + Spawn des PNJ\n-- \nfunction event_2690_23785()\n    \nend\n\n-- *[MERCENAIRE][DIALOG] Le joueur donne le livre à Remington (ACH 4296)\n-- \nfunction event_2690_23786()\n    \nend\n\n-- *[MERCENAIRE][DIALOG] Le joueur ne donne pas le livre à Remington (ACH 4296)\n-- \nfunction event_2690_23787()\n    \nend\n\n-- *[MERCENAIRE][DIALOG] Le joueur laisse Brise-Tibia s'enfuir (ACH 4296)\n-- \nfunction event_2690_23788()\n    \nend\n\n-- *[MERCENAIRE][DIALOG] Le joueur dénonce Brise-Tibia (ACH 4296)\n-- \nfunction event_2690_23789()\n    \nend\n\n-- *[MERCENAIRE][DIALOG] Le joueur a donné une réponse à Remington\n-- \nfunction event_2690_23790()\n    \nend\n\n-- *[MERCENAIRE][DIALOG] Le joueura donné une réponse à Brise-Tibia\n-- \nfunction event_2690_23791()\n    \nend\n\n-- [COMBAT][Achievement] Un joueur tombe KO\n-- \nfunction event_2690_23792()\n    \nend\n\n-- [COMBAT][Achievement] Aucun joueur tombe KO + Victoire des joueurs\n-- \nfunction event_2690_23793()\n    \nend\n\n-- Lancement d'un combat - Application de l'état aux Roublard\n-- \nfunction event_2690_23794()\n    \nend\n\n-- FIGHT_ENTER_ACTION_PHASE - Applique l'état \"Neo-Corruption\"\n-- \nfunction event_2690_23903()\n    \nend\n\n-- [NEO][ARCHI] Apparition de l'Archimonstre\n-- \nfunction event_2690_23996()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_2690_23774","event_2690_23775","event_2690_23776","event_2690_23777","event_2690_23778","event_2690_23779","event_2690_23780","customSkip","event_2690_23781","event_2690_23782","event_2690_23783","event_2690_23784","event_2690_23785","event_2690_23786","event_2690_23787","event_2690_23788","event_2690_23789","event_2690_23790","event_2690_23791","event_2690_23792","event_2690_23793","event_2690_23794","event_2690_23903","event_2690_23996"],"quest_calls":[],"dialogue_calls":[]},"scenario/2691.lua":{"source":"function hideDoor()\r\n\t\tWorld.setPictoAlpha(10, 21, 3, 0, 1000)\r\n\t\tWorld.setPictoAlpha(11, 21, 3, 0, 1000)\r\n\t\tWorld.setPictoAlpha(12, 21, 3, 0, 1000)\r\nend\r\n\r\nbubbleSteleInfoId = 0\r\n\r\nfunction closeSteleInfo()\r\n\tif (bubbleSteleInfoId ~= nil  and bubbleSteleInfoId ~= 0) then BubbleText.close(bubbleSteleInfoId) end\r\nend\r\n\r\nfunction onSteleInfoClosed()\r\n\tif (bubbleSteleInfoId ~= nil  and bubbleSteleInfoId ~= 0) then bubbleSteleInfoId = 0 end\r\nend\r\n\r\nfunction updateSteleInfo(stateInfoId, forceDisplayUI)\r\n\r\n\tif (bubbleSteleInfoId == 0) then\r\n\t\tbubbleSteleInfoId = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_WEST\", 0, -60, false, 2147483647, true, \"interactiveBubbleDialog5\", 30000, 25000, \"onSteleInfoClosed\")\r\n\tend\r\n\r\n\tBubbleText.setText(bubbleSteleInfoId, stateInfoId)\r\n\t\r\n\tif (forceDisplayUI) then BubbleText.show(bubbleSteleInfoId) end\r\nend\n\n-- [INIT] Variables & Constantes\n-- \nfunction event_2691_23795()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2691_23796()\n    hideDoor()\nend\n\n-- FIGHT_STARTED - Pose des zones flag\n-- \nfunction event_2691_23798()\n    \nend\n\n-- INTERACTIVE_ELEMENT_ACTIVATION - Ouverture de la porte\n-- \nfunction event_2691_23804()\n    trace(\"OUVERTURE DE LA PORTE\")\r\n    \r\n    hideDoor()\nend\n\n-- MONSTER_ACTION_EVENT - Lancement du combat\n-- on skippe la cinématique pour tout le monde \nfunction event_2691_23805()\n    skipCinematic()\nend\n\n-- FIGHT_ENDED - Rend les monstres inattaquables\n-- \nfunction event_2691_23806()\n    \nend\n\n-- FIGHT_ENDED_IN_CLIENT_EVENT - Reset les stèles\n-- \nfunction event_2691_23807()\n    \nend\n\n-- [STELE] Le joueur examine une stèle\n-- \nfunction event_2691_23808(steleCount, steleStateId)\n    local steleCount = toLong(steleCount)\r\n    local steleStateId = toLong(steleStateId)\r\n    \r\n    if (steleCount == 0) then\r\n    UI.openRewardsDialog(\"stele.description.tour\")\r\n    UI.addReward(27123)\r\n    UI.addReward(27278, \"stele.reward.stasis.21\")\r\n    UI.addReward(27083, \"stele.reward.stasis.21\")\r\n    \r\n    elseif (steleCount == 1) then\r\n    UI.openRewardsDialog(\"stele.description.tour\")\r\n    UI.addReward(27141)\r\n    UI.addReward(27277, \"stele.reward.stasis.21\")\r\n    UI.addReward(27083, \"stele.reward.stasis.21\")\r\n    \r\n    elseif (steleCount == 2) then\r\n    UI.openRewardsDialog(\"stele.description.tour\")\r\n    UI.addReward(27138)\r\n    UI.addReward(27279, \"stele.reward.stasis.21\")\r\n    UI.addReward(27083, \"stele.reward.stasis.21\")\r\n    \r\n    elseif (steleCount == 3) then\r\n    UI.openRewardsDialog(\"stele.description.tour\")\r\n    UI.addReward(27028, \"stele.reward.stasis.21\")\r\n    UI.addReward(27276, \"stele.reward.stasis.21\")\r\n    UI.addReward(27083, \"stele.reward.stasis.21\")\r\n    \r\n    else\r\n    \r\n    end\r\n    \r\n    local stateInfoId = \"stele.state.description.\" .. toString(steleStateId)\r\n    \r\n    updateSteleInfo(stateInfoId, true)\nend\n\n-- [STELE] Le joueur active une stèle\n-- \nfunction event_2691_23809(steleCount)\n    local steleCount = toLong(steleCount)\r\n    local steleStateId = toLong(steleStateId)\r\n    \r\n    if (steleCount == 1) then\r\n    UI.openRewardsDialog(\"stele.description.tour\")\r\n    UI.addReward(27123)\r\n    UI.addReward(27278, \"stele.reward.stasis.21\")\r\n    UI.addReward(27083, \"stele.reward.stasis.21\")\r\n    \r\n    elseif (steleCount == 2) then\r\n    UI.openRewardsDialog(\"stele.description.tour\")\r\n    UI.addReward(27141)\r\n    UI.addReward(27277, \"stele.reward.stasis.21\")\r\n    UI.addReward(27083, \"stele.reward.stasis.21\")\r\n    \r\n    elseif (steleCount == 3) then\r\n    UI.openRewardsDialog(\"stele.description.tour\")\r\n    UI.addReward(27138)\r\n    UI.addReward(27279, \"stele.reward.stasis.21\")\r\n    UI.addReward(27083, \"stele.reward.stasis.21\")\r\n    \r\n    elseif (steleCount == 4) then\r\n    UI.openRewardsDialog(\"stele.description.tour\")\r\n    UI.addReward(27028, \"stele.reward.stasis.21\")\r\n    UI.addReward(27276, \"stele.reward.stasis.21\")\r\n    UI.addReward(27083, \"stele.reward.stasis.21\")\r\n    \r\n    else\r\n    \r\n    end\r\n    \r\n    local stateInfoId = \"stele.state.description.\" .. toString(steleStateId)\r\n    \r\n    updateSteleInfo(stateInfoId, true)\nend\n\n-- [STELE] Refresh des APS pour Stèles\n-- \nfunction event_2691_23810()\n    \nend\n\n-- [STASIS] DUNGEON_DIFFICULTY_CHANGED - Reset les stèles\n-- \nfunction event_2691_23811()\n    \nend\n\n-- USER_GROUP_KILLED - BOSS\n-- \nfunction event_2691_23999()\n    \nend\n\n-- [NEO][ARCHI] Apparition de l'Archimonstre\n-- \nfunction event_2691_24001()\n    \nend\n\n","functions":["hideDoor","closeSteleInfo","onSteleInfoClosed","updateSteleInfo","event_2691_23795","event_2691_23796","event_2691_23798","event_2691_23804","event_2691_23805","event_2691_23806","event_2691_23807","event_2691_23808","event_2691_23809","event_2691_23810","event_2691_23811","event_2691_23999","event_2691_24001"],"quest_calls":["UI.openRewardsDialog(\"stele.description.tour\")\r","UI.openRewardsDialog(\"stele.description.tour\")\r","UI.openRewardsDialog(\"stele.description.tour\")\r","UI.openRewardsDialog(\"stele.description.tour\")\r","UI.openRewardsDialog(\"stele.description.tour\")\r","UI.openRewardsDialog(\"stele.description.tour\")\r","UI.openRewardsDialog(\"stele.description.tour\")\r","UI.openRewardsDialog(\"stele.description.tour\")\r"],"dialogue_calls":[]},"scenario/2692.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\n-- bla\r\n\r\nbubbleFightInfoId = 0\r\n\r\n-- Fonction porte\r\nfunction displayDoor(doorOpened, ogrestFightWon)\r\n\tlocal door = toLong(doorOpened)\r\n\tlocal fight = toLong(ogrestFightWon)\r\n\r\n\tif (door == 1) then\r\n\t\tWorld.setPictoAlpha(58, -35, 10, 0, 1000)\r\n\telse\r\n\t\tWorld.setPictoAlpha(58, -35, 10, 1, 1000)\r\n\tend\r\n\r\n\tif (fight == 1) then\r\n\t\tWorld.setPictoAlpha(58, -35, 10, 1, 1000)\r\n\tend\r\nend\r\n\r\nphases = {\t{5003, 4980, Event.getContentTranslation(8, 4980), \"emeraude\"},\r\n\t\t\t\t\t{5004, 4981, Event.getContentTranslation(8, 4981), \"ocre\"},\r\n\t\t\t\t\t{5005, 4982, Event.getContentTranslation(8, 4982), \"pourpre\"},\r\n\t\t\t\t\t{5006, 4983, Event.getContentTranslation(8, 4983), \"turquoise\"},\r\n\t\t\t\t\t{5007, 4984, Event.getContentTranslation(8, 4984), \"ivoire\"},\r\n\t\t\t\t\t{5008, 4985, Event.getContentTranslation(8, 4985), \"ebene\"}\t}\r\n\t\t\t\t\t\r\nfunction closeFightInfo()\r\n\tif (bubbleFightInfoId ~= nil  and bubbleFightInfoId ~= 0) then BubbleText.close(bubbleFightInfoId) end\r\nend\r\n\r\nfunction onFightInfoClosed()\r\n\tif (bubbleFightInfoId ~= nil  and bubbleFightInfoId ~= 0) then bubbleFightInfoId = 0 end\r\nend\r\n\r\nfunction updateFightInfo(ogrestId, teamDamage, currentPhaseTurnLeft, phaseEmeraude, phaseOcre, phasePourpre, phaseTurquoise, phaseIvoire, phaseEbene, forceDisplayUI)\r\n\tlocal ogrestId = toLong(ogrestId)\r\n\tlocal teamDamage = toLong(teamDamage)\r\n\tlocal phaseEmeraude = toLong(phaseEmeraude)\r\n\tlocal phaseOcre = toLong(phaseOcre)\r\n\tlocal phasePourpre = toLong(phasePourpre)\r\n\tlocal phaseTurquoise = toLong(phaseTurquoise)\r\n\tlocal phaseIvoire = toLong(phaseIvoire)\r\n\tlocal phaseEbene = toLong(phaseEbene)\r\n\tlocal currentPhaseTurnLeft = toLong(currentPhaseTurnLeft)\r\n\tlocal currentPhaseName = \"?\"\r\n\tlocal nextPhaseName = \"?\"\r\n\t\r\n\tif (phaseEmeraude == 1) then\r\n\t  \tnextPhaseName =  phases[1][3]\r\n\telseif (phaseOcre == 1) then\r\n\t\tnextPhaseName = phases[2][3]\r\n\telseif (phasePourpre == 1) then\r\n\t   \tnextPhaseName = phases[3][3]\r\n\telseif (phaseTurquoise == 1) then\r\n\t   \tnextPhaseName = phases[4][3]\r\n\telseif (phaseIvoire == 1) then\r\n\t   \tnextPhaseName = phases[5][3]\r\n\telseif (phaseEbene == 1) then\r\n\t   \tnextPhaseName = phases[6][3]\r\n\tend\r\n\r\n\tif (phaseEmeraude == 2) then\r\n\t   \tcurrentPhaseName = phases[1][3]\r\n\telseif (phaseOcre == 2) then\r\n\t   \tcurrentPhaseName = phases[2][3]\r\n\telseif (phasePourpre == 2) then\r\n\t   \tcurrentPhaseName = phases[3][3]\r\n\telseif (phaseTurquoise == 2) then\r\n\t   \tcurrentPhaseName = phases[4][3]\r\n\telseif (phaseIvoire == 2) then\r\n\t  \tcurrentPhaseName = phases[5][3]\r\n\telseif (phaseEbene == 2) then\r\n\t   \tcurrentPhaseName = phases[6][3]\r\n\tend\r\n\t   \r\n\tif (currentPhaseTurnLeft == nil or currentPhaseTurnLeft <= 0) then currentPhaseTurnLeft = \"?\" end\r\n\r\n\tif (bubbleFightInfoId == 0) then\r\n\t\tbubbleFightInfoId = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_WEST\", 0, -60, false, 2147483647, true, \"interactiveBubbleOgrestDialog\", 30000, 25000, \"onFightInfoClosed\")\r\n\tend\r\n\r\n\tBubbleText.setText(bubbleFightInfoId, \"ogrest.fight.player.infos\", teamDamage, currentPhaseName, currentPhaseTurnLeft, nextPhaseName)\r\n\t\r\n\tif (forceDisplayUI) then BubbleText.show(bubbleFightInfoId) end\r\nend\n\n-- [INIT] Variables\n-- \nfunction event_2692_23812()\n    \nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_2692_23813(doorOpened, ogrestFightWon)\n    FightEvent.addPlacementStartCallback(\"Sound.playFightMusic\", 290103)\r\n    \r\n    displayDoor(doorOpened, ogrestFightWon)\nend\n\n-- INTERACTIVE_ELEMENT_ACTIVATION - Ouverture de la porte\n-- \nfunction event_2692_23814(doorOpened, ogrestFightWon)\n    trace(\"OUVERTURE DE LA PORTE\")\r\n    \r\n    displayDoor(doorOpened, ogrestFightWon)\r\n    UI.manageFrame(\"World\", false)\r\n    \r\n    invoke(1000, 1, \"Server.triggerEvent\", 23814)\nend\n\n-- CLIENT_TRIGGERED_EVENT - Lancement Vidéo Intro\n-- \nfunction event_2692_23815()\n    function onVideoEnd()\r\n        UI.manageFrame(\"World\", true)\r\n        skipVideo(19091)\r\n    end\r\n    \r\n    startVideoContext()\r\n    Video.playCinematicVideo(\"WAKFU_OGREST_ZINIT_INTRO.mkv\", 0.6)\r\n    Video.addVideoStopOrEndCallback(\"onVideoEnd\")\nend\n\n-- CLIENT_TRIGGERED_EVENT - Lancement Vidéo Intro\n-- \nfunction event_2692_24070()\n    UI.manageFrame(\"World\", true)\nend\n\n-- [EVENT] Le joueur attaque Ogrest - Initialisation du combat (Final)\n-- \nfunction event_2692_23816()\n    \nend\n\n-- [EVENT] Le joueur attaque Ogrest - Initialisation du combat (Emeraude)\n-- \nfunction event_2692_23817()\n    \nend\n\n-- [EVENT] Le joueur attaque Ogrest - Initialisation du combat (Ocre)\n-- \nfunction event_2692_23818()\n    \nend\n\n-- [EVENT] Le joueur attaque Ogrest - Initialisation du combat (Pourpre)\n-- \nfunction event_2692_23819()\n    \nend\n\n-- [EVENT] Le joueur attaque Ogrest - Initialisation du combat (Turquoise)\n-- \nfunction event_2692_23820()\n    \nend\n\n-- [EVENT] Le joueur attaque Ogrest - Initialisation du combat (Ivoire)\n-- \nfunction event_2692_23821()\n    \nend\n\n-- [EVENT] Le joueur attaque Ogrest - Initialisation du combat (Ebene)\n-- \nfunction event_2692_23822()\n    \nend\n\n-- [EVENT] Démarrage du combat - Initialisation des variables\n-- \nfunction event_2692_23823()\n    \nend\n\n-- [EVENT] Démarrage du combat - Pose des Artefacts\n-- \nfunction event_2692_23824()\n    \nend\n\n-- [EVENT] FIGHT_ENTER_ACTION_PHASE - Application états\n-- \nfunction event_2692_23825()\n    \nend\n\n-- [EVENT] Fin du combat -  Masque UI infos de combat\n-- \nfunction event_2692_23826()\n    closeFightInfo()\nend\n\n-- [EVENT] Victoire du combat - Enregistrement au classement\n-- \nfunction event_2692_23827()\n    \nend\n\n-- [EVENT] Notification Etat Gestion Phases - Mise à jour UI infos de combats (phases)\n-- \nfunction event_2692_23828(ogrestId, teamDamage, currentPhaseTurnLeft, phaseEmeraude, phaseOcre, phasePourpre, phaseTurquoise, phaseIvoire, phaseEbene)\n    updateFightInfo(ogrestId, teamDamage, currentPhaseTurnLeft, phaseEmeraude, phaseOcre, phasePourpre, phaseTurquoise, phaseIvoire, phaseEbene, true)\nend\n\n-- [EVENT] Notification Etat Compteur de dommages - Mise à jour UI infos de combat (score)\n-- \nfunction event_2692_23829(ogrestId, teamDamage, currentPhaseTurnLeft, phaseEmeraude, phaseOcre, phasePourpre, phaseTurquoise, phaseIvoire, phaseEbene)\n    updateFightInfo(ogrestId, teamDamage, currentPhaseTurnLeft, phaseEmeraude, phaseOcre, phasePourpre, phaseTurquoise, phaseIvoire, phaseEbene, false)\nend\n\n-- [EVENT] Notification Etat Gestion Phases -  Changement de Musique à chaque Phase\n-- \nfunction event_2692_23830(musicPhaseCount)\n    local musicPhaseCount = toLong(musicPhaseCount)\r\n    local musics = {290103,290104,290105,290106,290107,290108}\r\n    \r\n    --On commence à 2 car la première musique est déjà lancée via la musique de combat sur la zone d'ambiance\r\n    if (musicPhaseCount >= 2 and musicPhaseCount <= 6) then\r\n    \tSound.playFightMusic(musics[musicPhaseCount])\r\n    end\nend\n\n-- [EVENT] Le joueur perd le combat - TP en dehors de l'instance\n-- \nfunction event_2692_23839(ogrestIsDown)\n    \nend\n\n-- [EVENT] Le joueur gagne le combat - Lancement Vidéo Victoire\n-- \nfunction event_2692_23840(ogrestIsDown)\n    trace(\"STARTING VIDEO OGREST\")\r\n    local ogrestIsDown = toLong(ogrestIsDown)\r\n    local videoName = \"WAKFU_OGREST_ZINIT_FIGHT_SHORT.mkv\"\r\n    \r\n    if (ogrestIsDown == 1) then videoName = \"WAKFU_OGREST_ZINIT_FIGHT_LONG.mkv\" end\r\n    trace(ogrestIsDown, videoName)\r\n    \r\n    Sound.stopForcedMusic()\r\n    \r\n    Mobile.hideOtherPlayerMobile(true)\r\n    \r\n    UI.addUnremovableDialog(\"fightResultDialog\")\r\n    \r\n    UI.setWidgetEnabled(\"fightResultDialog\", \"rootContainer\", false)\r\n    UI.setWidgetVisibility(\"fightResultDialog\", \"rootContainer\", false)\r\n    \r\n    startVideoContext()\r\n    Video.playCinematicVideo(videoName, 0.6)\r\n    Video.addVideoStopOrEndCallback(\"skipVideo\", 23840)\nend\n\n-- [EVENT] Fin Vidéo Victoire - Lancement Cinématique Ogrest\n-- \nfunction event_2692_23841()\n    trace(\"STARTING OGREST CINE\")\r\n    \r\n    function cineOgrest()\r\n    \tlocal playerId = Context.getLeaderId()\r\n    \tMobile.setMobileDirection(playerId, 7)\r\n    \tMobile.setMobileAnimation(playerId, \"AnimCine-Ogrest-ArtefactTP\")\r\n    \t\r\n    \tlocal ogrestId = createActor(\"1115705806\", 266, -66, 54, 4, 3, 14)\r\n    \tMobile.setMobileAnimation(ogrestId, \"AnimComp-Epuisement\")\r\n    \t\r\n    \tlocal apsTeleport = -1454061590\r\n    \r\n    \t---------------------------------\r\n    \t\r\n    \tstartCinematicContext(1.7, playerId)\r\n    \tUI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 23841)\r\n    \t\r\n    \tinvoke_custom(0400, 1, \"setWorldParticleTarget\", apsTeleport, playerId, 1)\r\n    \tinvoke_custom(4000, 1, \"Mobile.setMobileVisible\", playerId, false)\r\n    \tinvoke_custom(6500, 1, \"Camera.attachCameraToMobile\", ogrestId)\r\n    \tinvoke_custom(6500, 1, \"Camera.setZoomFactor\", 1.5)\r\n    \r\n    \t---------------------------------\r\n    \t\r\n    \tinvoke_custom(12000, 1, \"skipCinematic\", 23841)\r\n    end\r\n    \r\n    Event.runOnInstanceLoaded(\"cineOgrest\")\nend\n\n-- [EVENT] Fin Cinématique Ogrest - Lancement Cinématique Otomaï\n-- \nfunction event_2692_23842(ogrestIsDown)\n    trace(\"STARTING OTOMAI CINE\")\r\n    local ogrestIsDown = toLong(ogrestIsDown)\r\n    \r\n    function cineOtomai(ogrestIsDown)\r\n    \tlocal playerId = Context.getLeaderId()\r\n    \tMobile.setMobileDirection(playerId, 1)\r\n    \tMobile.setMobileVisible(playerId, false)\r\n    \r\n    \tlocal otomaiId = createActor(\"181404009\", 436, -48, 20, 4, 1, 8)\r\n    \tMobile.setMobileDirection(otomaiId, 3)\r\n    \t\r\n    \tlocal suffix = \"victory\"\r\n    \tif (ogrestIsDown == 1) then suffix = \"end\" end\r\n    \t\r\n    \t---------------------------------\r\n    \t\r\n    \tstartCinematicContext(1.2, otomaiId)\r\n    \tUI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 23842)\r\n    \t\r\n    \t--Otomai se déplace vers le joueur\r\n    \tinvoke_custom(00100, 1, \"Mobile.moveMobile\", otomaiId, 436, -39, 20)\r\n    \t--La caméra se met sur l'emplacement du joueur puis il tombe du ciel\r\n    \tinvoke_custom(03000, 1, \"Camera.attachCameraToMobile\", playerId)\r\n    \tinvoke_custom(03500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimIncarnam-Chute-Fin\")\r\n    \tinvoke_custom(03500, 1, \"Mobile.setMobileVisible\", playerId, true)\r\n    \t\r\n    \t--Ah, te voilà !\r\n    \t--Ah, te voilà !\r\n    \tinvoke_custom(06000, 1, \"bubble\", otomaiId, \"quest.zinit.ch4.cine.otomai.ogrest.\" .. suffix .. \".01\")\r\n    \tinvoke_custom(06000, 1, \"Mobile.setMobileAnimation\", otomaiId, \"AnimComp-Special03\")\r\n    \t--A mieux te regarder, on dirait que tu es encore sous le choc de ton combat.\r\n    \t--Je ne pensais pas cela possible, mais encore une fois, tu m’a démontré le contraire.\r\n    \tinvoke_custom(08000, 1, \"bubble\", otomaiId, \"quest.zinit.ch4.cine.otomai.ogrest.\" .. suffix .. \".02\")\r\n    \t--Et tu n’es pas le seul… Le monde entier a subi les conséquences de ton affrontement contre Ogrest.\r\n    \t--Après plusieurs millénaires à étudier des phénomènes scientifiques… Je me croyais à l’abri des surprises.\r\n    \tinvoke_custom(14000, 1, \"bubble\", otomaiId, \"quest.zinit.ch4.cine.otomai.ogrest.\" .. suffix .. \".03\")\r\n    \t--Mais ce sont des conséquences nécessaires. Si on ne fait rien, la montée des eaux ne s’arrêtera jamais.\r\n    \t--Et puis, vous êtes arrivés.\r\n    \tinvoke_custom(20000, 1, \"bubble\", otomaiId, \"quest.zinit.ch4.cine.otomai.ogrest.\" .. suffix .. \".04\")\r\n    \t--Malheureusement, c’est une victoire mi-figue mi-raisin… Qui sait, peut-être qu’à la sueur des braves tels que toi, nous atteindrons un stade de victoire.\r\n    \t--Je dois avouer que c’est une sacrée génération d’aventuriers que nous avons là. Un miracle a été accompli, et Ogrest s’en est retourné chez lui, calmé. \r\n    \tinvoke_custom(26000, 1, \"bubble\", otomaiId, \"quest.zinit.ch4.cine.otomai.ogrest.\" .. suffix .. \".05\")\r\n    \t--En tout cas, je suis ravi de te revoir en un seul morceau ! Le générateur de barrière extra-krosmique a bien fait l’affaire, finalement.\r\n    \t--Fini, le chaos d’Ogrest ! Pour un temps, du moins. Mais tous ces efforts en valaient bien la peine !\r\n    \tinvoke_custom(34000, 1, \"bubble\", otomaiId, \"quest.zinit.ch4.cine.otomai.ogrest.\" .. suffix .. \".06\")\r\n    \t--Tu ne t’imaginais pas retourner à Incarnam pour tout recommencer nu comme un Slek, n’est-ce pas ?\r\n    \t--Maintenant que les orages incessants se sont calmés, tu pourras peut-être trouver quelques Larmes d’Ogrest éparpillées sur le monde.\r\n    \tinvoke_custom(42000, 1, \"bubble\", otomaiId, \"quest.zinit.ch4.cine.otomai.ogrest.\" .. suffix .. \".07\")\r\n    \tinvoke_custom(42000, 1, \"Mobile.setMobileAnimation\", otomaiId, \"AnimComp-Special03\")\r\n    \t--N’oublie pas : le générateur est limité à 3 utilisations par semaine. Il serait dommage d’aller tenter le diable une fois de trop !\r\n    \t--Elles possèdent de grands pouvoirs ! D’ailleurs, tu peux en demander davantage à Mod’Ule.\r\n    \tinvoke_custom(50000, 1, \"bubble\", otomaiId, \"quest.zinit.ch4.cine.otomai.ogrest.\" .. suffix .. \".08\")\r\n    \t\r\n    \tinvoke_custom(56000, 1, \"clearBubbles\", otomaiId)\r\n    \tinvoke_custom(56000, 1, \"Mobile.moveMobile\", otomaiId, 436, -48, 20)\r\n    \t\r\n    \t---------------------------------\r\n    \r\n    \tinvoke_custom(60000, 1, \"skipCinematic\", 23842)\r\n    end\r\n    \r\n    Event.runOnInstanceLoaded(\"cineOtomai\", ogrestIsDown)\nend\n\n-- [EVENT] Fin Cinématique Otomaï - Clean\n-- \nfunction event_2692_23843(teamDamage)\n    local teamDamage = toString(teamDamage)\r\n    \r\n    Mobile.hideOtherPlayerMobile(false)\r\n    \r\n    UI.setWidgetEnabled(\"fightResultDialog\", \"rootContainer\", true)\r\n    UI.setWidgetVisibility(\"fightResultDialog\", \"rootContainer\", true)\r\n    \r\n    local text = Event.getKeyTranslation(\"fight.score.ogrest\", teamDamage)\r\n    UI.setPropertyStringValue(\"fight.score.ogrest\", text)\r\n    UI.writeLocalisedInChat(\"ogrest.fight.team.score\", teamDamage)\r\n    \r\n    UI.removeUnremovableDialog(\"fightResultDialog\")\r\n    \r\n    UI.addDialogUnloadedListener(\"fightResultDialog\", \"UI.removeProperty\", \"fight.score.ogrest\")\nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","displayDoor","closeFightInfo","onFightInfoClosed","updateFightInfo","event_2692_23812","event_2692_23813","event_2692_23814","event_2692_23815","onVideoEnd","event_2692_24070","event_2692_23816","event_2692_23817","event_2692_23818","event_2692_23819","event_2692_23820","event_2692_23821","event_2692_23822","event_2692_23823","event_2692_23824","event_2692_23825","event_2692_23826","event_2692_23827","event_2692_23828","event_2692_23829","event_2692_23830","event_2692_23839","event_2692_23840","event_2692_23841","cineOgrest","event_2692_23842","cineOtomai","event_2692_23843"],"quest_calls":[],"dialogue_calls":[]},"scenario/2693.lua":{"source":"\n\n-- [INIT] Variables Globales\n-- \nfunction event_2693_23850()\n    \nend\n\n-- [INIT] Inscription du joueur + Variables Locales\n-- \nfunction event_2693_23851()\n    \nend\n\n-- [ACH][EVENT] Echec si le Chêne Mou a subi trop de pertes de PdV\n-- \nfunction event_2693_23852()\n    \nend\n\n-- [ACH][NOTIF] Victoire sans avoir fait perdre trop de PdV au CM (ACH 4397)\n-- \nfunction event_2693_23853()\n    \nend\n\n","functions":["event_2693_23850","event_2693_23851","event_2693_23852","event_2693_23853"],"quest_calls":[],"dialogue_calls":[]},"scenario/2694.lua":{"source":"\n\n-- [INIT] Variables\n-- \nfunction event_2694_23854()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2694_23855()\n    \nend\n\n-- [COMBAT][Achievement] Corbeau Noir possède \"Vitesse éclair\" au niveau 10 mini\n-- \nfunction event_2694_23856()\n    \nend\n\n-- [COMBAT][Achievement] Corbeau Noir possède \"Vitesse éclair\" au niveau 10 mini + Victoire des joueurs (ACH 1351)\n-- \nfunction event_2694_23857()\n    \nend\n\n-- [COMBAT][Achievement] Des joueurs ont subi une collision\n-- \nfunction event_2694_23858()\n    \nend\n\n-- [COMBAT][Achievement] Aucun joueur n'a subi de collision + Victoire des joueurs (ACH 1351)\n-- \nfunction event_2694_23859()\n    \nend\n\n","functions":["event_2694_23854","event_2694_23855","event_2694_23856","event_2694_23857","event_2694_23858","event_2694_23859"],"quest_calls":[],"dialogue_calls":[]},"scenario/2695.lua":{"source":"\n\n-- [INIT] Variables\n-- \nfunction event_2695_23860()\n    \nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_2695_23870()\n    \nend\n\n-- [EVENT] Démarrage du combat - Initialisation des variables\n-- \nfunction event_2695_23861()\n    \nend\n\n-- [ACH][EVENT] Ogrest possède \"Rage\" au niveau 18 mini\n-- \nfunction event_2695_23862()\n    \nend\n\n-- [ACH][NOTIF] Victoire alors qu'Ogrest a eu \"Rage\" au niveau 18 mini (ACH 3792)\n-- \nfunction event_2695_23863()\n    \nend\n\n-- [ACH][EVENT] Echec si au moins une larme a été propagée\n-- \nfunction event_2695_23864()\n    \nend\n\n-- [ACH][NOTIF] Victoire sans qu'une seule larme n'ait été propagée (ACH 3793)\n-- \nfunction event_2695_23865()\n    \nend\n\n-- [ACH][EVENT] Echec si au moins un artefact a été ramassé\n-- \nfunction event_2695_23866()\n    \nend\n\n-- [ACH][NOTIF] Victoire sans ramasser d'artefact (ACH 3794)\n-- \nfunction event_2695_23867()\n    \nend\n\n-- [ACH][EVENT] Ogrest possède tous ses états élémentaires niveau 15\n-- \nfunction event_2695_23868()\n    \nend\n\n-- [ACH][NOTIF] Victoire alors qu'Ogrest a eu tous ses états élémentaires niveau 15 (ACH 3795)\n-- \nfunction event_2695_23869()\n    \nend\n\n","functions":["event_2695_23860","event_2695_23870","event_2695_23861","event_2695_23862","event_2695_23863","event_2695_23864","event_2695_23865","event_2695_23866","event_2695_23867","event_2695_23868","event_2695_23869"],"quest_calls":[],"dialogue_calls":[]},"scenario/2696.lua":{"source":"\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2696_23872()\n    \nend\n\n-- FIGHT_STARTED - Initialisation des variables\n-- \nfunction event_2696_23873()\n    \nend\n\n-- [ACH][EVENT] Un joueur possède l'état Autel 1 (5953) niveau 5\n-- \nfunction event_2696_23874()\n    \nend\n\n-- [ACH][EVENT] Un joueur possède l'état Autel 2 (5954) niveau 5\n-- \nfunction event_2696_23875()\n    \nend\n\n-- [ACH][EVENT] Un joueur possède l'état Autel 3 (5955) niveau 5\n-- \nfunction event_2696_23876()\n    \nend\n\n-- [ACH][EVENT] Un joueur possède l'état Autel 4 (5956) niveau 5\n-- \nfunction event_2696_23877()\n    \nend\n\n-- [ACH][NOTIF] Victoire alors que les états \"Autel\" sont tous niveau 5\n-- On notifie pour l'achievement 4617\nfunction event_2696_23878()\n    \nend\n\n","functions":["event_2696_23872","event_2696_23873","event_2696_23874","event_2696_23875","event_2696_23876","event_2696_23877","event_2696_23878"],"quest_calls":[],"dialogue_calls":[]},"scenario/2697.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\n\n-- [INIT] Variables Globales\n-- \nfunction event_2697_23893()\n    \nend\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_2697_23879()\n    \nend\n\n-- [COMBAT][Achievement] Un joueur tombe KO\n-- \nfunction event_2697_23891()\n    \nend\n\n-- [COMBAT][Achievement] Aucun joueur tombe KO + Victoire des joueurs\n-- \nfunction event_2697_23892()\n    \nend\n\n-- [COMBAT][Achievement] Victoire - Quête mercenaire (Brise-tibias)\n-- \nfunction event_2697_24428()\n    \nend\n\n-- [COMBAT][Achievement] Victoire - Quête mercenaire (Remington)\n-- \nfunction event_2697_24076()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_2697_23893","event_2697_23879","event_2697_23891","event_2697_23892","event_2697_24428","event_2697_24076"],"quest_calls":[],"dialogue_calls":[]},"scenario/2698.lua":{"source":"-- CODE GLOBAL --\r\n\r\n-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n-- TRIGGER CLIENT --\r\n-- 0 = Fin cinématique VIDEO | Déclenché par le callback Video.addVideoStopOrEndCallback\r\n-- 1 = Arrivée dans l'instance | Déclenché par onInstanceLoaded() callback par Event.runOnInstanceLoaded (cf code Global)\r\n-- 2 = Fin cinématique | Déclenché par stopCinematicContext() (cf code Global)\r\n-- 3 = Fermeture UI Fin de combat\r\n-- 4 = Clic sur le bon bouton de changement d'oriention (parmis les 4) dans UI worldAndFightBar pour s'orientation vers le monstre\r\n-- 5 = Fermeture UI Fiche combattant\r\n-- 6 = Clic sur le bouton de validation de la répartition dans UI Aptitudes\r\n-- 7 = Clic sur la boussole du bon objectif dans l'UI suivi de quête\r\n-- 8 = Fermeture UI Map Monde\r\n\r\n-- VARIABLE GLOBALE - SCRIPT --\r\n\r\nwidget_visible = {}\r\nwidget_enable = {}\r\nui_tweens = {}\r\nui_particles = {}\r\nui_listener_load = {}\r\nui_listener_unload = {}\r\nui_listener_event = {}\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\nscreenEffectId = nil\r\n\r\n-- VARIABLE GLOBALE - MOBILE CINEMATIQUE & TUTO --\r\n\r\nANM_otomai = {think=\"AnimComp-Special03\", talk=\"AnimComp-Special04-Debut\", show=\"AnimComp-Special05-Debut\", nice=\"AnimComp-Special07\", nope=\"AnimComp-Special08\", lol=\"AnimComp-Special09\", stop_it=\"AnimComp-Special10\", come_here=\"AnimComp-Special01\", wave_hit=\"AnimComp-Special02\", fly=\"AnimStatique-Oiseau\", cast=\"AnimSort-01\", supercast=\"AnimComp-Special11\", attack=\"AnimSort-Cast\", balance=\"AnimComp-Special06\"}\r\nANM_melee = {attack=\"AnimSort-Morsure\", glitch1=\"AnimComp-Glitch01\", glitch2=\"AnimComp-Glitch02\", glitch3=\"AnimComp-Glitch03\", roar=\"AnimComp-Agressif\"}\r\nANM_range = {attack=\"AnimSort-01\", glitch=\"AnimComp-Glitch\", dupli=\"AnimComp-Dupli\"}\r\nANM_boss = {attack1=\"AnimSort-Estoc\", attack2=\"AnimSort-Hrargh\", glitch=\"AnimComp-Glitch\", dupli=\"AnimComp-Dupli\", roar=\"AnimComp-Hurle\", ko = \"AnimKO-SortieOK\", death= \"AnimKO-SortieHS\"}\r\n\r\nNPC_otomai = Mobile.generateClientMobileId()\r\nNPC_otomai_gfx = 181404009\r\nNPC_otomai_particleZ = 10\r\nNPC_otomai_bubbleX = 10\r\nNPC_otomai_bubbleY = 70\r\n\r\nNPC_melee = Mobile.generateClientMobileId()\r\nNPC_meleeB = Mobile.generateClientMobileId()\r\nNPC_melee_gfx = 181404014\r\nNPC_melee_particleZ = 5\r\n\r\nNPC_range = Mobile.generateClientMobileId()\r\nNPC_range_gfx = 181404015\r\nNPC_range_particleZ = 3\r\n\r\nNPC_boss = Mobile.generateClientMobileId()\r\nNPC_boss_gfx = 181404012\r\nNPC_boss_particleZ = 8\r\n\r\nNPC_eni_wakfu = Mobile.generateClientMobileId()\r\nNPC_eni_wakfu_gfx = 181404034\r\nNPC_eni_wakfu_particleZ = 7\r\n\r\nNPC_eni_stasis = Mobile.generateClientMobileId()\r\nNPC_eni_stasis_gfx = 181404013\r\nNPC_eni_stasis_particleZ = 7\r\n\r\n_ACTOR_LIST = {NPC_otomai, NPC_melee, NPC_meleeB, NPC_range, NPC_boss, NPC_eni_wakfu, NPC_eni_stasis}\r\n\r\n-- VARIABLE GLOBALE - PARTICULE CINEMATIQUE & TUTO --\r\n\r\n-- UI TUTO\r\napsArrowBig = {6001069,6001070,6001071,6001072,6001073,6001074,6001075,6001076}\r\napsArrow = {6001061,6001062,6001063,6001064,6001065,6001066,6001067,6001068}\r\napsCenter = {ap=6001090, mp=6001091, wp=6001092, hp=6001093}\r\napsFollowBorder = -1548037644\r\n-- WORLD TUTO\r\napsCell = {white_border=800578, red_border=800579, white_arrow=800576, red_arrow=800577, white=800581, red=800582, show=78900}\r\n-- CINEMATIQUE\r\napsWave = {spawn=800573, wave=800574, hit=800575}\r\napsOtomai = {shield=-1814057071, transform=-1814057072, playershield = -1814057074}\r\napsCristal = {base=71071022, react=800580, shield=71071021}\r\napsBoss = {death=-1814057073}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n    for index, value in ipairs (tab) do\r\n\t\tif isEqual(value, val) then\r\n            return true\r\n        end\r\n    end\r\n\r\n    return false\t\r\nend\r\n\r\n-- FONCTION UI -- Replace le Chat en bas à gauche et le rend indéplaçable/déplaçable\r\nfunction prepareChatUI(movable, chatOffsetX)\r\n\tif not UI.isDialogLoaded(\"chatDialog0\") then return end\r\n\t\r\n\tif (not chatOffsetX) then chatOffsetX = 0 end\r\n\t\r\n\tUI.setPosition(\"chatDialog0\", chatOffsetX, 0)\r\n\tUI.setWindowMovable(\"chatDialog0\", movable)\r\nend\r\n\r\n-- FONCTION UI -- Replace le Suivi de Quête mi-hauteur à gauche et le rend indéplaçable/déplaçable\r\nfunction prepareFollowQuestUI(movable)\r\n    local dialogName = \"\"\r\n    if UI.isDialogLoaded(\"verticalFollowedAchievementsDialog\") then\r\n        dialogName = \"verticalFollowedAchievementsDialog\"\r\n    end\r\n    if UI.isDialogLoaded(\"followedAchievementsDialog\") then\r\n        dialogName = \"followedAchievementsDialog\"\r\n    end\r\n\r\n    if (dialogName == \"\") then\r\n        return\r\n    end\r\n\r\n    local screenH, screenW = UI.getWindowSize()\r\n    local x, y = UI.getPosition(dialogName)\r\n\r\n    UI.setPosition(dialogName, x, screenH / 4)\r\n    UI.setWindowMovable(dialogName, movable)\r\nend\r\n\r\n-- FONCTION UI -- Rend Visible/Invisible certains éléments des interfaces\r\nfunction prepareUI(visible)\r\n  --Interface Boutique & Cadeau\r\n  setWidgetVisible(\"topHudDialog\", \"optionShopButton\", visible)\r\n  setWidgetVisible(\"topHudDialog\", \"giftButton\", visible)\r\n\r\n  --UI sous le Coeur\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"wakfuStasisBar\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"xpBar\", visible)\r\n\r\n  --Boutons hors combat à droite du Coeur\r\n  setWidgetVisible(\"shortcutBarDialog\", \"previousButton\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"nextButton\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseShortcutBar1\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseShortcutBar2\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseShortcutBar3\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseShortcutBar4\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"shortcutBarItemButton\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"shortcutBarSpellButton\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseButtonContainerForTuto1\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseButtonContainerForTuto2\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseButtonContainerForTuto3\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseButtonContainerForTuto4\", visible)\r\n\r\n  --Boutons hors combat à gauche de l'écran - barre d'interfaces\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"firstInterfaceBarBackground\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"secondInterfaceBarBackground\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"extraInterfaceBarDrawerButton\", visible)\r\n\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"fightInfoBtn\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"inventoryButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"buildSheetSetButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"craftButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"questsButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"dungeonButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"cosmeticsButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"tutorialBookButton\", visible)\r\n\r\n  --Boutons hors combat à gauche de l'écran - barre d'interfaces (deuxième barre)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"contactListButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"guildButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"companionsButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"nationButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"battlegroundButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"passportButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"emoteButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"encyclopediaButton\", visible)\r\n\r\n  --Boutons hors combat \"actions rapides\"\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"OverWorldActionsBackground\", visible)\r\n\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"dimensionalBagButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"mapButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"rideMountButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"miniMapButton\", visible)\r\n\r\n  --Boutons en combat à gauche du Coeur\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"FightActionsBackground\", visible)\r\n\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"giveUpButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"hideFightersButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"tacticalModeBtn\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"reportCellBtn\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"fightMarkerBtn\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"lockFightBtn\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"resistanceOverheadBtn\", visible)\r\nend\r\n\r\n-- FONCTION SHORTCUT -- Rend Actif/Inactif certains raccourcis\r\nfunction prepareShortcuts(enabled, shortcutType)\r\n  if not shortcutType or shortcutType == \"WORLD\" then\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.world\", \"enterLeaveBag\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.world\", \"switchHero0\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.world\", \"switchHero1\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.world\", \"switchHero2\")\r\n  end\r\n  if not shortcutType or shortcutType == \"DISPLAY\" then\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"zoomIn\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"zoomOut\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"closeWindows\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"setLODLevel\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"setFightLODLevel\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"showHideNameOverheadsCommand\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"hideFightOccluders\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"alphaMask\")\r\n  end\r\n  if not shortcutType or shortcutType == \"CHAT\" then\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.chat\", \"chat\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.chat\", \"lastContact\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.chat\", \"firstContact\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.chat\", \"autoCompletePlayerName\")\r\n    for bind=1, 9, 1 do\r\n      UI.setShortcutEnabled(enabled, \"shortcutCategory.shortcutBar\", \"bind\" .. toString(bind))\r\n    end\r\n  end\r\n\r\n  if not shortcutType or shortcutType == \"FIGHT\" then\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"fighterTransparency\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"switchTacticalView\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"nextSelectedFighter\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"giveUp\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"lockFight\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"reportCell\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"callHelp\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"displayHpBar\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"resetFightCamera\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"endPlacementAndTurn\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"closeCombatRight\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"closeCombatLeft\")\r\n  end\r\n  if not shortcutType or shortcutType == \"INTERFACE\" then\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"minimap\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"contactList\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"companionManagement\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"guild\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"craft\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"dungeonList\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"achievements\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"quests\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"emotes\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"ecosystem\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"climate\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"nation\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"partySearch\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"passport\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"almanax\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"tutorialBook\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"switchToDirectAttackCommand\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"map\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"spellsInventory\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"inventory\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"characterBook\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"osamodasSymbiot\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"shortcutBar0\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"shortcutBar1\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"shortcutBar2\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"shortcutBar3\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"additionalShortcutBar0\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"additionalShortcutBar1\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"additionalShortcutBar2\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"additionalShortcutBar3\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"changeShortcutBarType\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"downscaling\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"rewards\")\r\n\tUI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"battlegroundList\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"aptitudes\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"presets\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"encyclopedia\")\r\n  end\r\n\r\n  -- On ne bloque pas les raccourcis de sorts finalement\r\n--   if not shortcutType or shortcutType == \"SHORTCUTBAR\" then\r\n--     for bar=0,3, 1 do\r\n--       for slot=0, 9, 1 do\r\n--         UI.setShortcutEnabled(enabled, \"shortcutCategory.shortcutBar\", \"shortcut\" .. toString(bar) .. toString(slot))\r\n--       end\r\n--     end\r\n--   end\r\nend\r\n\r\n-- FONCTION UI -- Rend Visible/Invisible un élément d'une interface\r\nfunction setWidgetVisible(dialogName, widgetName, visible)\r\n  if not UI.isDialogLoaded(dialogName) then return end\r\n\r\n  UI.setWidgetVisibility(dialogName, widgetName, visible)\r\n  table.insert(widget_visible, { name = dialogName, id = widgetName, state = visible })\r\nend\r\n\r\nfunction clearWidgetVisible()\r\n  local str = \"\"\r\n  for i=#widget_visible, 1, -1 do\r\n    str = str .. toString(widget_visible[i].name) .. \"@\" .. toString(widget_visible[i].id) .. \";\"\r\n    UI.setWidgetVisibility(widget_visible[i].name, widget_visible[i].id, true)\r\n  end\r\n\r\n  widget_visible = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearWidgetVisible\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Rend Actif/Inactif un élément d'une interface\r\nfunction setWidgetEnable(dialogName, widgetName, enable)\r\n  if not UI.isDialogLoaded(dialogName) then return end\r\n\r\n  UI.setWidgetEnabled(dialogName, widgetName, enable)\r\n  table.insert(widget_enable, {name = dialogName, id = widgetName, state = enable})\r\nend\r\n\r\nfunction clearWidgetEnable()\r\n  local str = \"\"\r\n  for i=#widget_enable, 1, -1 do\r\n    str = str .. toString(widget_enable[i].name) .. \"@\" .. toString(widget_enable[i].id) .. \";\"\r\n    UI.setWidgetEnabled(widget_enable[i].name, widget_enable[i].id, true)\r\n  end\r\n\r\n  widget_enable = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearWidgetEnable\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Ajoute/Retire une TweenParticle à un élément d'une interface\r\nfunction setUIColorTween(dialogName, widgetName, duration, loop, r1, g1, b1, a1, r2, g2, b2, a2)\r\n  if not UI.isDialogLoaded(dialogName) then return end\r\n\r\n  UI.addColorTween(dialogName, widgetName, duration, loop, r1, g1, b1, a1, r2, g2, b2, a2)\r\n  table.insert(ui_tweens, {name = dialogName, id = widgetName})\r\nend\r\n\r\nfunction clearUIColorTweens(dialogName, widgetName)\r\n  local str = \"\"\r\n  for i=#ui_tweens, 1, -1 do\r\n    if ((not dialogName) or (dialogName == ui_tweens[i].name)) and ((not widgetName) or (widgetName == ui_tweens[i].id)) then\r\n      str = str .. toString(ui_tweens[i].name) .. \"@\" .. toString(ui_tweens[i].id) .. \";\"\r\n      UI.removeColorTween(ui_tweens[i].name, ui_tweens[i].id)\r\n      table.remove(ui_tweens, i)\r\n    end\r\n  end\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearUIColorTweens\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Ajoute/Retire une Particle à un élément d'une interface\r\nfunction setUIParticle(dialogName, widgetName, apsFileName, x, y, alignment, level)\r\n  if not UI.isDialogLoaded(dialogName) then return end\r\n\r\n  local particleId = UI.addParticle(dialogName, widgetName, apsFileName, x, y, alignment, level)\r\n  table.insert(ui_particles, {name = dialogName, id = widgetName})\r\n\r\n  return particleId\r\nend\r\n\r\nfunction setUIParticleBorder(dialogName, widgetName, apsFileName, x, y, alignment, level, speed)\r\n  if not UI.isDialogLoaded(dialogName) then return end\r\n\r\n  local particleId = UI.addParticleToBorder(dialogName, widgetName, apsFileName, x, y, alignment, level, speed)\r\n  table.insert(ui_particles, {name = dialogName, id = widgetName})\r\n\r\n  return particleId\r\nend\r\n\r\nfunction clearUIParticles(dialogName, widgetName)\r\n  local str = \"\"\r\n  for i=#ui_particles, 1, -1 do\r\n    if ((not dialogName) or (dialogName == ui_particles[i].name)) and ((not widgetName) or (widgetName == ui_particles[i].id)) then\r\n      str = str .. toString(ui_particles[i].name) .. \"@\" .. toString(ui_particles[i].id) .. \";\"\r\n      UI.clearParticles(ui_particles[i].name, ui_particles[i].id)\r\n      table.remove(ui_particles, i)\r\n    end\r\n  end\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearUIParticles\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Enregistre/Supprime un callback à l'ouverture d'une interface\r\nfunction addDialogLoadListener(dialog, funcName, ...)\r\n  UI.addDialogLoadedListener(dialog, funcName, unpack(arg))\r\n  table.insert(ui_listener_load,  dialog)\r\nend\r\n\r\nfunction clearDialogLoadListener(dialogName)\r\n  local str = \"\"\r\n  for i=#ui_listener_load, 1, -1 do\r\n    if (not dialogName) or (dialogName == ui_listener_load[i]) then\r\n      str = str .. toString(ui_listener_load[i]) .. \";\"\r\n      UI.removeDialogLoadedListener(ui_listener_load[i])\r\n      table.remove(ui_listener_load, i)\r\n    end\r\n  end\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearDialogLoadListener\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Enregistre/Supprime un callback à la fermeture d'une interface\r\nfunction addDialogUnloadListener(dialog, funcName, ...)\r\n  UI.addDialogUnloadedListener(dialog, funcName, unpack(arg))\r\n  table.insert(ui_listener_unload, dialog)\r\nend\r\n\r\nfunction clearDialogUnloadListener(dialogName)\r\n  local str = \"\"\r\n  for i=#ui_listener_unload, 1, -1 do\r\n    if (not dialogName) or (dialogName == ui_listener_unload[i]) then\r\n      str = str .. toString(ui_listener_unload[i]) .. \";\"\r\n      UI.removeDialogUnloadedListener(ui_listener_unload[i])\r\n      table.remove(ui_listener_unload, i)\r\n    end\r\n  end\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearDialogUnloadListener\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Enregistre/Supprime un callback sur un élément d'une interface\r\nfunction addDialogEventListener(dialog, id, eventType, funcName, ...)\r\n  if not UI.isDialogLoaded(dialog) then return end\r\n\r\n  UI.addEventListener(dialog, id, eventType, funcName, unpack(arg))\r\n  table.insert(ui_listener_event, {dialog=dialog, id=id, eventType=eventType, funcName=funcName})\r\nend\r\n\r\nfunction clearDialogEventListener(dialogName)\r\n  local str = \"\"\r\n  for i=#ui_listener_event, 1, -1 do\r\n    if (not dialogName) or (dialogName == ui_listener_event[i].dialog) then\r\n      str = str .. toString(ui_listener_event[i].dialog) .. \"@\" .. toString(ui_listener_event[i].id) .. \";\"\r\n      UI.removeEventListener(ui_listener_event[i].dialog, ui_listener_event[i].id, ui_listener_event[i].eventType, ui_listener_event[i].funcName)\r\n      table.remove(ui_listener_event, i)\r\n    end\r\n  end\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearDialogEventListener\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y , z, ...)\r\n  local particleId = Particle.addParticleSystem(particleFileId, x, y , z, unpack(arg))\r\n  table.insert(world_particles, particleId)\r\n\r\n  return particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n  local particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n  table.insert(world_particles, particleId)\r\n\r\n  return particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n  local str = \"\"\r\n  for i=#world_particles, 1, -1 do\r\n    str = str .. toString(world_particles[i]) .. \";\"\r\n    Particle.removeParticleSystem(world_particles[i])\r\n  end\r\n\r\n  world_particles = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n  BubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n  if isLower(mobileId, 0) then\r\n    BubbleText.setCharacterSpeak(mobileId, text)\r\n  else\r\n    if (not offsetY) then\r\n      local height = Mobile.getMobileHeight(mobileId)\r\n      if (not height) then height = 6 end\r\n\r\n      offsetY = height * 10\r\n    end\r\n\r\n    if (not offsetX) then offsetX = 0 end\r\n    if (not infiniteDuration) then infiniteDuration = false end\r\n\r\n    BubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n    UI.writeLocalisedInChat(text)\r\n  end\r\n\r\n  if (not tContains(bubbles, mobileId)) then\r\n    table.insert(bubbles, mobileId)\r\n  end\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n  local str = \"\"\r\n  for i = #bubbles, 1, -1 do\r\n    if (not mobileId) then\r\n      str = str .. toString(bubbles[i]) .. \";\"\r\n      BubbleText.closeBubbleAttachedTo(bubbles[i])\r\n    elseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n      str = str .. toString(bubbles[i]) .. \";\"\r\n      BubbleText.closeBubbleAttachedTo(bubbles[i])\r\n      table.remove(bubbles, i)\r\n    end\r\n  end\r\n\r\n  if (not mobileId) then bubbles = {} end\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n  local compassId = UI.addCompass(\"compass\", x, y, z)\r\n  table.insert(compasses, compassId)\r\n\r\n  return compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n  local str = \"\"\r\n  for i=#compasses, 1, -1 do\r\n    str = str .. toString(compasses[i]) .. \";\"\r\n    UI.removeCompass(compasses[i])\r\n  end\r\n\r\n  compasses = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height)\r\n  local mobileId = Mobile.generateClientMobileId()\r\n  Actor.createActor(mobileId, spriteName, worldX, worldY, worldZ, availableDirection)\r\n\r\n  if (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n  if (height) then Actor.setActorHeight(mobileId, height) end\r\n\r\n  table.insert(actors, mobileId)\r\n\r\n  return mobileId\r\nend\r\n\r\nfunction clearActors()\r\n  local str = \"\"\r\n  for i = #actors, 1, -1 do\r\n    str = str .. toString(actors[i]) .. \";\"\r\n    Actor.deleteActor(actors[i])\r\n  end\r\n\r\n  actors = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n  local taskId = invoke(delay, count, funcName, unpack(arg))\r\n  table.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n  local str = \"\"\r\n  for i=#invoke_tasks, 1, -1 do\r\n    str = str .. toString(invoke_tasks[i]) .. \";\"\r\n    interrupt(invoke_tasks[i])\r\n    desinvoke(invoke_tasks[i])\r\n  end\r\n\r\n  invoke_tasks = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n  invoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n  local taskId = setInterval(delay, funcName, unpack(arg))\r\n  table.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n  local str = \"\"\r\n  for i=#interval_tasks, 1, -1 do\r\n    str = str .. toString(interval_tasks[i]) .. \";\"\r\n    interrupt(interval_tasks[i])\r\n    desinvoke(interval_tasks[i])\r\n  end\r\n\r\n  interval_tasks = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n  if (_DEBUG) then trace(\"startCinematicContext\") end\r\n\r\n  UI.manageFrame(\"World\", false)\r\n  UI.closeMRU()\r\n  UI.closeAllBags()\r\n  UI.setUIVisible(false)\r\n  UI.displayWideScreenBand(true)\r\n  Camera.setUserZoomLocked(true)\r\n\r\n  if (cameraMobileId ~= nil)  then\r\n    Camera.setMoveSpeedFactor(10000)\r\n    Camera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n  end\r\n\r\n  if (zoomFactor ~= nil)  then\r\n    Camera.setZoomFactor(zoomFactor)\r\n  end\r\n\r\n  if (musicId ~= nil)  then\r\n    Sound.playForcedMusic(musicId)\r\n  end\r\n\r\n  if (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\nfunction skipCinematic()\r\n  local player = Context.getLeaderId()\r\n\r\n  for x = 1, #_ACTOR_LIST do\r\n    Actor.deleteActor(_ACTOR_LIST[x])\r\n  end\r\n\r\n  UI.hideButton()\r\n  clearALL()\r\n  stopCinematicContext(1, player, true)\r\n  Mobile.setMobileVisible(player, true)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n  if (_DEBUG) then trace(\"stopCinematicContext\") end\r\n\r\n  UI.displayWideScreenBand(false)\r\n  UI.setUIVisible(true)\r\n  Camera.setUserZoomLocked(false)\r\n  UI.manageFrame(\"World\", true)\r\n\r\n  Camera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n  Camera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n  if (zoomFactor ~= nil) then\r\n    Camera.setZoomFactor(zoomFactor)\r\n  end\r\n\r\n  if (cameraMobileId ~= nil) then\r\n    Camera.attachCameraToMobile(cameraMobileId)\r\n  end\r\n\r\n  if (stopMusic) then\r\n    Sound.stopForcedMusic()\r\n  end\r\n\r\n  if (_DEBUG) then\r\n    UI.hideButton()\r\n  end\r\n\r\n  --TRIGGER\r\n  Server.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Affiche/Masque une texture à l'écran\r\nfunction displayScreenEffect(enable, fadeInDur, alphaDur, fadeOutDur, r, g, b, alpha)\r\n  if (_DEBUG) then trace(\"displayScreenEffect\") end\r\n\r\n  if not enable and screenEffectId ~= nil  then\r\n    --On retire le blackScreen\r\n    Effect.stopEffect(screenEffectId)\r\n  else\r\n    --On affiche un blackScreen à l'entrée dans l'instance le temps qu'elle soit complètement chargée\r\n    screenEffectId = Effect.createFullScreenSprite(fadeInDur, alphaDur, fadeOutDur, r, g, b, alpha)\r\n  end\r\nend\r\n\r\n-- FONCTION NETTOYAGE --\r\nfunction clearALL()\r\n  clearIntervalTasks()\r\n  clearInvokeTasks()\r\n  clearBubbles()\r\n  clearUIColorTweens()\r\n  clearUIParticles()\r\n  clearWorldParticles()\r\n  clearCompasses()\r\n  clearActors()\r\n\r\n  Focus.display(false)\r\n  UI.unloadTutorialDialog()\r\nend\r\n\r\n-- FONCTION NETTOYAGE --\r\nfunction clearUI(dialogName)\r\n  clearUIColorTweens(dialogName)\r\n  clearUIParticles(dialogName)\r\nend\r\n\r\n-- FONCTION NETTOYAGE --\r\nfunction clearListener(dialogName)\r\n  clearDialogLoadListener(dialogName)\r\n  clearDialogUnloadListener(dialogName)\r\n  clearDialogEventListener(dialogName)\r\nend\r\n\r\nfunction onInstanceLoaded()\r\n    if (_DEBUG) then\r\n        trace(\"ON INSTANCE LOADED\")\r\n    end\r\n\r\n    prepareShortcuts(false)\r\n    prepareUI(false)\r\n    prepareChatUI(false, 50)\r\n\r\n    UI.setPropertyBooleanValue(\"hideDownscaling\", true)\r\n\r\n    UI.manageFrame(\"World\", true)\r\n    UI.setUIVisible(true)\r\n    displayScreenEffect(false)\r\n\r\n    -- TRIGGER\r\n    Server.triggerEvent(23908)\r\nend\r\n\r\napsId = 800016\r\n\r\nfunction setNewArrowAps(apsId, x, y, z)\r\n    if (arrowAps ~= null) then\r\n        Particle.removeParticleSystem(arrowAps)\r\n    end\r\n\r\n    arrowAps = Particle.addParticleSystem(apsId, x, y, z)\r\nend\r\n\r\nfunction displayGuide(guideId)\r\n    UI.loadGuideDialog(guideId)\r\n\r\n    invoke(100, 1, \"addButton\", guideId)\r\nend\r\n\r\nfunction addButton(guideId)\r\n    UI.displayButton(false, \"guide.displayConfirm\", \"incarnam.guide.displayGuide\", \"displayGuide\", guideId, 0, 150, \"SOUTH\")\r\nend\r\n\r\nfunction setArrowOnSlot(slotNumber)\r\n    setUIParticle(\"shortcutBarDialog\", tostring(\"shortcutBarList#\" .. slotNumber), apsArrow[2] .. \".xps\", 0, 0, \"NORTH\")\r\nend\n\n-- Variables\n-- \nfunction event_2698_23907()\n    \nend\n\n-- ENTER_INSTANCE\n-- \nfunction event_2698_23908()\n    if (_DEBUG) then\r\n        trace(\"ENTER INSTANCE\")\r\n    end\r\n    \r\n    Event.runOnInstanceLoaded(\"onInstanceLoaded\")\nend\n\n-- 0 - CLIENT_TRIGGERED_EVENT - Cinématique VIDEO\n-- \nfunction event_2698_23909()\n    if (_DEBUG) then trace(\"START VIDEO\") end\r\n    \r\n    function onVideoEnd()\r\n    \tif (_DEBUG) then trace(\"END VIDEO\") end\r\n    \r\n    \tEffect.createFullScreenSprite(0, 1000, 2000, 1.0, 1.0, 1.0)\r\n    \r\n    \tServer.triggerEvent(23909)\r\n    end\r\n    \r\n    if (Context.getLanguageId() == 0) then\r\n    \t\t Video.playCinematicVideo(\"WAKFU_INTRO_FR.mkv\", 1.0)\r\n    else\r\n     \t\t Video.playCinematicVideo(\"WAKFU_INTRO_EN.mkv\", 1.0)\r\n    end\r\n    \r\n    Video.addVideoStopOrEndCallback(\"onVideoEnd\")\nend\n\n-- 1 - CLIENT_TRIGGERED_EVENT - Cinématique Script\n-- \nfunction event_2698_23910(ogrest)\n    if (_DEBUG) then trace(\"CINEMATIQUE 1\") end\r\n    \r\n    clearALL()\r\n    \r\n    Sound.playForcedMusic(290103)\r\n    local playerId = Context.getLeaderId()\r\n    local playerX, playerY, playerZ = Mobile.getMobilePosition(playerId)\r\n    \r\n    local ogrest = toLong(ogrest)\r\n    local ermina = createActor(81, 0, 0, 40, 4, 1, 6)\r\n    local lumyss = createActor(71, 0, 0, 40, 4, 1, 6)\r\n    local morgouz = createActor(120, 0, 0, 40, 4, 1, 6)\r\n    local ryou = createActor(90, 0, 0, 40, 4, 1, 6)\r\n    local otomai = createActor(181404009, 0, 0, 40, 4, 1, 