ants)\n-- \nfunction event_2710_24104(turnLeft, teamDamage)\n    updateFightInfo(turnLeft, teamDamage, true)\nend\n\n-- EFFECT_EXECUTION - Le joueur a gagné le combat\n-- \nfunction event_2710_24105()\n    \nend\n\n-- FIGHT_ENDED_IN_CLIENT_EVENT - Le joueur perd\n-- \nfunction event_2710_24129(teamDamage, fightWon)\n    local teamDamage = toLong(teamDamage)\r\n    \r\n    if (toLong(fightWon) == 1) then\r\n    \tUI.writeLocalisedInChat(\"japan.expo.2025.fight.won\")\r\n    \tUI.writeLocalisedInChat(\"neo.event.fight.final.score.damage\", teamDamage)\r\n    end\r\n    \r\n    closeFightInfo()\nend\n\n-- FIGHT_ENDED_IN_CLIENT_EVENT - Le joueur gagne - Lancement Vidéo Victoire\n-- \nfunction event_2710_24128(gerorId, moineA, mioneB, moineC, moineD, lieutenantA, lieutenantB, lieutenantC, boss)\n    trace(\"CINÉMATIQUE DE VICTOIRE\")\r\n    \r\n    Sound.stopForcedMusic()\r\n    closeFightInfo()\r\n    \r\n       local playerId = Context.getLeaderId()\r\n       Mobile.setMobilePosition(playerId, 0, -1, 0)\r\n       Mobile.setMobileDirection(playerId, 7)\r\n       Mobile.setMobileAnimation(playerId, \"AnimStatique02\")\r\n    \r\n       local gerorId = toLong(gerorId)\r\n       local moineA = toLong(moineA)\r\n       local moineB = toLong(moineB)\r\n       local moineC = toLong(moineC)\r\n       local moineD = toLong(moineD)\r\n       local lieutenantA = toLong(lieutenantA)\r\n       local lieutenantB = toLong(lieutenantB)\r\n       local lieutenantC = toLong(lieutenantC)\r\n       local boss = toLong(boss)\r\n    \r\n       Mobile.setMobileVisible(gerorId, false)\r\n       Mobile.setMobileVisible(moineA, false)\r\n       Mobile.setMobileVisible(moineB, false)\r\n       Mobile.setMobileVisible(moineC, false)\r\n       Mobile.setMobileVisible(moineD, false)\r\n       Mobile.setMobileVisible(lieutenantA, false)\r\n       Mobile.setMobileVisible(lieutenantB, false)\r\n       Mobile.setMobileVisible(lieutenantC, false)\r\n       Mobile.setMobileVisible(boss, false)\r\n    \r\n    \r\n       -- Acteurs\r\n    \r\n       local geror = createActor(1115705816, 0, -10, 1, 4, 1, 8)\r\n       Mobile.setMobileDirection(geror, 3)\r\n       local moineActorA = createActor(1115705820, 4, -3, 0, 4, 1, 8)\r\n       Mobile.setMobileDirection(moineActorA, 5)\r\n       local lieutenantActorA = createActor(1115705819, -3, -1, 0, 4, 1, 8)\r\n       local lieutenantActorB = createActor(1115705819, 5, -4, 0, 4, 1, 8)\r\n       Mobile.setMobileDirection(lieutenantActorB, 5)\r\n       local qilby = createActor(1115705848, 0, -4, 0, 4, 1, 8)\r\n       Mobile.setMobileDirection(qilby, 3)\r\n    \r\n    \r\n       function customSkip()\r\n       Effect.stopEffect(textId)\r\n       Effect.stopEffect(fullScreenId)\r\n       skipCinematic(24128)\r\n       end\r\n    \r\n    setWorldParticleCell(801103, -1,-2,0)\r\n    setWorldParticleCell(801103, -1,-4,0)\r\n    setWorldParticleCell(801103, 3,-4,0)\r\n    setWorldParticleCell(801103, -3,-3,0)\r\n    setWorldParticleCell(801103, -1,-7,0)\r\n    setWorldParticleCell(801103, 0,-5,0)\r\n    setWorldParticleCell(801103, 0,-4,0)\r\n    setWorldParticleCell(801103, 2,-2,0)\r\n    setWorldParticleCell(801103, 4,-3,0)\r\n    \r\n    \r\n    --------------------------------- Début de la cinématique\r\n        \r\n    startCinematicContext(2.0, playerId)\r\n    \r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"customSkip\")\r\n    \r\n    invoke_custom(00050, 1, \"Sound.stopForcedMusic\")\r\n    invoke_custom(00100, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimStatique02\")\r\n    -- Disparition de qilby\r\n    \r\n    invoke_custom(01000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Drapeau-Neoraid-Cast\")\r\n    invoke_custom(01000, 1, \"Camera.attachCameraToMobile\", qilby)\r\n    invoke_custom(01600, 1, \"setWorldParticleCell\", -1701084730, 0, -1, 0)\r\n    invoke_custom(02000, 1, \"setWorldParticleCell\", -1701084731, 0, -4, 0)\r\n    invoke_custom(0220