ayerId, 0, -8, 0)\r\n    \r\n    -- \"Je crois bien que c'en est fini cette fois.\"\r\n    \r\n    invoke_custom(16500, 1, \"Mobile.setMobileAnimation\", geror, \"AnimComp01\")\r\n    invoke_custom(16500, 1, \"Camera.attachCameraToMobile\", geror)\r\n    invoke_custom(16500, 1, \"bubble\", geror, \"neo.event.end.dialog.01\")\r\n    invoke_custom(19500, 1, \"clearBubbles\")\r\n    \r\n    -- \"Je n'ai jamais rien vu de tel. De quoi s'agissait-il ?\"\r\n    \r\n    invoke_custom(20000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Presenter\")\r\n    invoke_custom(20000, 1, \"bubble\", playerId, \"neo.event.end.dialog.02\")\r\n    invoke_custom(23000, 1, \"clearBubbles\")\r\n    \r\n    -- \"Je ne sais pas. J'ai l'impression qu'il s'agissait de la projection d'un esprit qui n'est pas de ce monde.\"\r\n    \r\n    invoke_custom(23500, 1, \"bubble\", geror, \"neo.event.end.dialog.03\")\r\n    invoke_custom(27000, 1, \"clearBubbles\")\r\n    \r\n    -- \"Comme s'il était bloqué dans une autre dimension, et qu'il cherchait à se matérialiser ici.\"\r\n    \r\n    invoke_custom(27500, 1, \"bubble\", geror, \"neo.event.end.dialog.04\")\r\n    invoke_custom(31000, 1, \"clearBubbles\")\r\n    \r\n    -- \"La projection d'un esprit ? Se matérialiser ? Comment ça ?\"\r\n    \r\n    invoke_custom(31500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(31500, 1, \"bubble\", playerId, \"neo.event.end.dialog.05\")\r\n    invoke_custom(34000, 1, \"clearBubbles\")\r\n    \r\n    \r\n    -- \"Ce ne sont que des théories. Je crains que nous n'ayons jamais le fin mot de cette histoire.\"\r\n    \r\n    invoke_custom(34500, 1, \"Mobile.setMobileAnimation\", geror, \"AnimComp03\")\r\n    invoke_custom(34500, 1, \"bubble\", geror, \"neo.event.end.dialog.06\")\r\n    invoke_custom(38000, 1, \"clearBubbles\")\r\n    \r\n    -- \"On lui a bien réglé son compte, je doute qu'il cherche à revenir de sitôt !\"\r\n    \r\n    invoke_custom(38500, 1, \"Mobile.setMobileAnimation\", geror, \"AnimComp04\")\r\n    invoke_custom(38500, 1, \"bubble\", geror, \"neo.event.end.dialog.07\")\r\n    invoke_custom(42000, 1, \"clearBubbles\")\r\n    \r\n    -- \"Mouais, ce n'est pas très rassurant tout ça...\"\r\n    \r\n    invoke_custom(42500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Non\")\r\n    invoke_custom(42500, 1, \"bubble\", playerId, \"neo.event.end.dialog.08\")\r\n    invoke_custom(45500, 1, \"clearBubbles\")\r\n    \r\n    -- \"[#name], nous n'aurions jamais réussi sans toi. Tu as la reconnaissance éternelle du Néo-Raid.\"\r\n    \r\n    invoke_custom(46000, 1, \"Camera.setZoomSpeedFactor\", 0.05)\r\n    invoke_custom(47000, 1, \"Camera.setZoomFactor\", 2.5)\r\n    invoke_custom(46000, 1, \"bubble\", geror, \"neo.event.end.dialog.09\")\r\n    invoke_custom(50500, 1, \"clearBubbles\")\r\n    \r\n    -- \"Toutes les occasions sont bonnes pour être un héros !\"\r\n    \r\n    invoke_custom(51000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Acquiescer\")\r\n    invoke_custom(51000, 1, \"bubble\", playerId, \"neo.event.end.dialog.10\")\r\n    invoke_custom(55000, 1, \"clearBubbles\")\r\n    \r\n    -- \"Je te nomme chevalier du Néo-Raid. Félicitations !\"\r\n    \r\n    invoke_custom(55500, 1, \"bubble\", geror, \"neo.event.end.dialog.11\")\r\n    invoke_custom(58500, 1, \"clearBubbles\")\r\n    \r\n    invoke_custom(58000, 1,  \"fullScreen\", 2000, 99999, 0)\r\n    \r\n    -- \"Grâce à vous, les menaces planant sur le Monde des Douze ont été repoussées.\"\r\n    \r\n    invoke_custom(59000, 1, \"text\", 2000, 3000, 500, \"neo.event.blackscreen.04\")\r\n    \r\n    -- \"Cette ultime batalle signe la fin de l'aventure du néo-Raid. Merci d'y avoir participé !\"\r\n    \r\n    invoke_custom(65500, 1, \"text\", 500, 4000, 500, \"neo.event.blackscreen.05\")\r\n    \r\n    -- \"Et n'oubliez pas : quand l'ombre se propage...\"\r\n    \r\n    invoke_custom(70500, 1, \"text\", 500, 3000, 500, \"neo.event.blackscreen.06\")\r\n    \r\n    -- \"Il est temps d'aller se coucher.\"\r\n    invoke_custom(74500, 1, \"text\", 500, 3000, 1000, \"neo.event.blackscreen.07\")\r\n    \r\n    ----------------------------- Fin de la cinématique\r\n    invoke_custom(80000, 1, \"customSkip\")\nend\n\n-- CLIENT_TRIGGERED_EVENT - Fin cinématique -> Clean\n-- \nfunction event_2710_24102(teamDamage, fightWon)\n    local teamDamage = toLong(teamDamage)\r\n    \r\n    if (toLong(fightWon) == 1) then\r\n    \tUI.writeLocalisedInChat(\"japan.expo.2025.fight.won\")\r\n    \tUI.writeLocalisedInChat(\"neo.event.fight.final.score.damage\", teamDamage)\r\n    end\r\n    \r\n    closeFightInfo()\nend\n\n-- [EVENT] Victoire du combat - Enregistrement au classement\n-- \nfunction event_2710_24106()\n    \nend\n\n-- [TEST] Met fin au combat à la fin du tour de table\n-- \nfunction event_2710_24107()\n    \nend\n\n-- MONSTER_ACTION_EVENT - Ouverture du guide Esprit vengeur\n-- \nfunction event_2710_24125()\n    UI.loadGuideDialog(175)\nend\n\n-- MONSTER_ACTION_EVENT - Ouverture du guide Néo-Lieutenant\n-- \nfunction event_2710_24126()\n    UI.loadGuideDialog(177)\nend\n\n-- MONSTER_ACTION_EVENT - Ouverture du guide Néo-Moine\n-- \nfunction event_2710_24127()\n    UI.loadGuideDialog(178)\nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","fullScreen","text","hideMonster","showMonster","closeFightInfo","onFightInfoClosed","updateFightInfo","event_2710_24098","event_2710_24099","customSkip","event_2710_24124","event_2710_24101","event_2710_24108","event_2710_24103","event_2710_24104","event_2710_24105","event_2710_24129","event_2710_24128","customSkip","event_2710_24102","event_2710_24106","event_2710_24107","event_2710_24125","event_2710_24126","event_2710_24127"],"quest_calls":[],"dialogue_calls":[]},"scenario/2711.lua":{"source":"\n\n-- Enregistrement des Evènements : Début\n-- \nfunction event_2711_24110()\n    \nend\n\n-- Enregistrement des Evènements : Fin\n-- \nfunction event_2711_24111()\n    \nend\n\n-- Enregistrement des Evènements Cyclique : Spawn de monstres\n-- Toutes les X min, on spawn les groupes de monstres\nfunction event_2711_24112()\n    \nend\n\n","functions":["event_2711_24110","event_2711_24111","event_2711_24112"],"quest_calls":[],"dialogue_calls":[]},"scenario/2712.lua":{"source":"\n\n-- [INIT] Active les IE liés à l'Event\n-- Les IE doivent être initialement non utilisable pour que ce soit cohérent\nfunction event_2712_24113()\n    \nend\n\n-- [INIT] Initialise les Monstres NPC liés à l'Event\n-- Les Groupes doivent être initialement non spawn\nfunction event_2712_24114()\n    \nend\n\n","functions":["event_2712_24113","event_2712_24114"],"quest_calls":[],"dialogue_calls":[]},"scenario/2713.lua":{"source":"\n\n-- [INIT] Spawn Goules & Bouftous - Montagnes\n-- \nfunction event_2713_24115()\n    \nend\n\n-- [INIT] Spawn Goules & Bouftous - Champs\n-- \nfunction event_2713_24116()\n    \nend\n\n-- [INIT] Spawn Momies - Plaines\n-- \nfunction event_2713_24117()\n    \nend\n\n-- [INIT] Spawn Momies - Cimetière\n-- \nfunction event_2713_24118()\n    \nend\n\n-- [INIT] Spawn Yokai - Forêt\n-- \nfunction event_2713_24119()\n    \nend\n\n-- [INIT] Spawn Yokai - Tainela\n-- \nfunction event_2713_24120()\n    \nend\n\n","functions":["event_2713_24115","event_2713_24116","event_2713_24117","event_2713_24118","event_2713_24119","event_2713_24120"],"quest_calls":[],"dialogue_calls":[]},"scenario/2714.lua":{"source":"\n\n-- [INIT] Désactive les IE liés à l'Event\n-- Les IE doivent être initialement non utilisable pour que ce soit cohérent\nfunction event_2714_24121()\n    \nend\n\n-- [INIT] Despawn les Monstres NPC liés à l'Event\n-- Les Groupes doivent être initialement non spawn\nfunction event_2714_24122()\n    \nend\n\n-- [INIT] Despawn les Monstres Cyclique liés à l'Event\n-- \nfunction event_2714_24123()\n    \nend\n\n","functions":["event_2714_24121","event_2714_24122","event_2714_24123"],"quest_calls":[],"dialogue_calls":[]},"scenario/2715.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n-- TRIGGER CLIENT --\r\n-- 0 = Fin cinématique VIDEO | Déclenché par le callback Video.addVideoStopOrEndCallback\r\n-- 1 = Arrivée dans l'instance | Déclenché par onInstanceLoaded() callback par Event.runOnInstanceLoaded (cf code Global)\r\n-- 2 = Fin cinématique | Déclenché par stopCinematicContext() (cf code Global)\r\n-- 3 = Fermeture UI Fin de combat\r\n-- 4 = Clic sur le bon bouton de changement d'oriention (parmis les 4) dans UI worldAndFightBar pour s'orientation vers le monstre\r\n-- 5 = Fermeture UI Fiche combattant\r\n-- 6 = Clic sur le bouton de validation de la répartition dans UI Aptitudes\r\n-- 7 = Clic sur la boussole du bon objectif dans l'UI suivi de quête\r\n-- 8 = Fermeture UI Map Monde\r\n\r\n-- VARIABLE GLOBALE - SCRIPT --\r\n\r\nwidget_visible = {}\r\nwidget_enable = {}\r\nui_tweens = {}\r\nui_particles = {}\r\nui_listener_load = {}\r\nui_listener_unload = {}\r\nui_listener_event = {}\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\nscreenEffectId = nil\r\n\r\n-- VARIABLE GLOBALE - MOBILE CINEMATIQUE & TUTO --\r\n\r\nANM_otomai = {think=\"AnimComp-Special03\", talk=\"AnimComp-Special04-Debut\", show=\"AnimComp-Special05-Debut\", nice=\"AnimComp-Special07\", nope=\"AnimComp-Special08\", lol=\"AnimComp-Special09\", stop_it=\"AnimComp-Special10\", come_here=\"AnimComp-Special01\", wave_hit=\"AnimComp-Special02\", fly=\"AnimStatique-Oiseau\", cast=\"AnimSort-01\", supercast=\"AnimComp-Special11\", attack=\"AnimSort-Cast\", balance=\"AnimComp-Special06\"}\r\nANM_melee = {attack=\"AnimSort-Morsure\", glitch1=\"AnimComp-Glitch01\", glitch2=\"AnimComp-Glitch02\", glitch3=\"AnimComp-Glitch03\", roar=\"AnimComp-Agressif\"}\r\nANM_range = {attack=\"AnimSort-01\", glitch=\"AnimComp-Glitch\", dupli=\"AnimComp-Dupli\"}\r\nANM_boss = {attack1=\"AnimSort-Estoc\", attack2=\"AnimSort-Hrargh\", glitch=\"AnimComp-Glitch\", dupli=\"AnimComp-Dupli\", roar=\"AnimComp-Hurle\", ko = \"AnimKO-SortieOK\", death= \"AnimKO-SortieHS\"}\r\n\r\nNPC_otomai = Mobile.generateClientMobileId()\r\nNPC_otomai_gfx = 181404009\r\nNPC_otomai_particleZ = 10\r\nNPC_otomai_bubbleX = 10\r\nNPC_otomai_bubbleY = 70\r\n\r\nNPC_melee = Mobile.generateClientMobileId()\r\nNPC_meleeB = Mobile.generateClientMobileId()\r\nNPC_melee_gfx = 181404014\r\nNPC_melee_particleZ = 5\r\n\r\nNPC_range = Mobile.generateClientMobileId()\r\nNPC_range_gfx = 181404015\r\nNPC_range_particleZ = 3\r\n\r\nNPC_boss = Mobile.generateClientMobileId()\r\nNPC_boss_gfx = 181404012\r\nNPC_boss_particleZ = 8\r\n\r\nNPC_eni_wakfu = Mobile.generateClientMobileId()\r\nNPC_eni_wakfu_gfx = 181404034\r\nNPC_eni_wakfu_particleZ = 7\r\n\r\nNPC_eni_stasis = Mobile.generateClientMobileId()\r\nNPC_eni_stasis_gfx = 181404013\r\nNPC_eni_stasis_particleZ = 7\r\n\r\n_ACTOR_LIST = {NPC_otomai, NPC_melee, NPC_meleeB, NPC_range, NPC_boss, NPC_eni_wakfu, NPC_eni_stasis}\r\n\r\n-- VARIABLE GLOBALE - PARTICULE CINEMATIQUE & TUTO --\r\n\r\n-- UI TUTO\r\napsArrowBig = {6001069,6001070,6001071,6001072,6001073,6001074,6001075,6001076}\r\napsArrow = {6001061,6001062,6001063,6001064,6001065,6001066,6001067,6001068}\r\napsCenter = {ap=6001090, mp=6001091, wp=6001092, hp=6001093}\r\napsFollowBorder = -1548037644\r\n-- WORLD TUTO\r\napsCell = {white_border=800578, red_border=800579, white_arrow=800576, red_arrow=800577, white=800581, red=800582, show=78900}\r\n-- CINEMATIQUE\r\napsWave = {spawn=800573, wave=800574, hit=800575}\r\napsOtomai = {shield=-1814057071, transform=-1814057072, playershield = -1814057074}\r\napsCristal = {base=71071022, react=800580, shield=71071021}\r\napsBoss = {death=-1814057073}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n    for index, value in ipairs (tab) do\r\n\t\tif isEqual(value, val) then\r\n            return true\r\n        end\r\n    end\r\n\r\n    return false\t\r\nend\r\n\r\n-- FONCTION UI -- Replace le Chat en bas à gauche et le rend indéplaçable/déplaçable\r\nfunction prepareChatUI(movable, chatOffsetX)\r\n\tif not UI.isDialogLoaded(\"chatDialog0\") then return end\r\n\t\r\n\tif (not chatOffsetX) then chatOffsetX = 0 end\r\n\t\r\n\tUI.setPosition(\"chatDialog0\", chatOffsetX, 0)\r\n\tUI.setWindowMovable(\"chatDialog0\", movable)\r\nend\r\n\r\n-- FONCTION UI -- Replace le Suivi de Quête mi-hauteur à gauche et le rend indéplaçable/déplaçable\r\nfunction prepareFollowQuestUI(movable)\r\n    local dialogName = \"\"\r\n    if UI.isDialogLoaded(\"verticalFollowedAchievementsDialog\") then\r\n        dialogName = \"verticalFollowedAchievementsDialog\"\r\n    end\r\n    if UI.isDialogLoaded(\"followedAchievementsDialog\") then\r\n        dialogName = \"followedAchievementsDialog\"\r\n    end\r\n\r\n    if (dialogName == \"\") then\r\n        return\r\n    end\r\n\r\n    local screenH, screenW = UI.getWindowSize()\r\n    local x, y = UI.getPosition(dialogName)\r\n\r\n    UI.setPosition(dialogName, x, screenH / 4)\r\n    UI.setWindowMovable(dialogName, movable)\r\nend\r\n\r\n-- FONCTION UI -- Rend Visible/Invisible certains éléments des interfaces\r\nfunction prepareUI(visible)\r\n  --Interface Boutique & Cadeau\r\n  setWidgetVisible(\"topHudDialog\", \"optionShopButton\", visible)\r\n  setWidgetVisible(\"topHudDialog\", \"giftButton\", visible)\r\n\r\n  --UI sous le Coeur\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"wakfuStasisBar\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"xpBar\", visible)\r\n\r\n  --Boutons hors combat à droite du Coeur\r\n  setWidgetVisible(\"shortcutBarDialog\", \"previousButton\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"nextButton\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseShortcutBar1\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseShortcutBar2\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseShortcutBar3\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseShortcutBar4\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"shortcutBarItemButton\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"shortcutBarSpellButton\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseButtonContainerForTuto1\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseButtonContainerForTuto2\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseButtonContainerForTuto3\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseButtonContainerForTuto4\", visible)\r\n\r\n  --Boutons hors combat à gauche de l'écran - barre d'interfaces\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"firstInterfaceBarBackground\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"secondInterfaceBarBackground\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"extraInterfaceBarDrawerButton\", visible)\r\n\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"fightInfoBtn\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"inventoryButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"buildSheetSetButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"craftButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"questsButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"dungeonButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"cosmeticsButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"tutorialBookButton\", visible)\r\n\r\n  --Boutons hors combat à gauche de l'écran - barre d'interfaces (deuxième barre)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"contactListButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"guildButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"companionsButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"nationButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"battlegroundButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"passportButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"emoteButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"encyclopediaButton\", visible)\r\n\r\n  --Boutons hors combat \"actions rapides\"\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"OverWorldActionsBackground\", visible)\r\n\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"dimensionalBagButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"mapButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"rideMountButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"miniMapButton\", visible)\r\n\r\n  --Boutons en combat à gauche du Coeur\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"FightActionsBackground\", visible)\r\n\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"giveUpButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"hideFightersButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"tacticalModeBtn\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"reportCellBtn\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"fightMarkerBtn\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"lockFightBtn\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"resistanceOverheadBtn\", visible)\r\nend\r\n\r\n-- FONCTION SHORTCUT -- Rend Actif/Inactif certains raccourcis\r\nfunction prepareShortcuts(enabled, shortcutType)\r\n  if not shortcutType or shortcutType == \"WORLD\" then\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.world\", \"enterLeaveBag\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.world\", \"switchHero0\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.world\", \"switchHero1\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.world\", \"switchHero2\")\r\n  end\r\n  if not shortcutType or shortcutType == \"DISPLAY\" then\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"zoomIn\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"zoomOut\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"closeWindows\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"setLODLevel\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"setFightLODLevel\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"showHideNameOverheadsCommand\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"hideFightOccluders\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"alphaMask\")\r\n  end\r\n  if not shortcutType or shortcutType == \"CHAT\" then\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.chat\", \"chat\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.chat\", \"lastContact\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.chat\", \"firstContact\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.chat\", \"autoCompletePlayerName\")\r\n    for bind=1, 9, 1 do\r\n      UI.setShortcutEnabled(enabled, \"shortcutCategory.shortcutBar\", \"bind\" .. toString(bind))\r\n    end\r\n  end\r\n\r\n  if not shortcutType or shortcutType == \"FIGHT\" then\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"fighterTransparency\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"switchTacticalView\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"nextSelectedFighter\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"giveUp\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"lockFight\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"reportCell\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"callHelp\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"displayHpBar\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"resetFightCamera\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"endPlacementAndTurn\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"closeCombatRight\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"closeCombatLeft\")\r\n  end\r\n  if not shortcutType or shortcutType == \"INTERFACE\" then\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"minimap\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"contactList\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"companionManagement\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"guild\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"craft\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"dungeonList\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"achievements\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"quests\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"emotes\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"ecosystem\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"climate\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"nation\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"partySearch\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"passport\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"almanax\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"tutorialBook\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"switchToDirectAttackCommand\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"map\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"spellsInventory\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"inventory\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"characterBook\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"osamodasSymbiot\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"shortcutBar0\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"shortcutBar1\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"shortcutBar2\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"shortcutBar3\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"additionalShortcutBar0\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"additionalShortcutBar1\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"additionalShortcutBar2\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"additionalShortcutBar3\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"changeShortcutBarType\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"downscaling\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"rewards\")\r\n\tUI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"battlegroundList\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"aptitudes\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"presets\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"encyclopedia\")\r\n  end\r\n\r\n  -- On ne bloque pas les raccourcis de sorts finalement\r\n--   if not shortcutType or shortcutType == \"SHORTCUTBAR\" then\r\n--     for bar=0,3, 1 do\r\n--       for slot=0, 9, 1 do\r\n--         UI.setShortcutEnabled(enabled, \"shortcutCategory.shortcutBar\", \"shortcut\" .. toString(bar) .. toString(slot))\r\n--       end\r\n--     end\r\n--   end\r\nend\r\n\r\n-- FONCTION UI -- Rend Visible/Invisible un élément d'une interface\r\nfunction setWidgetVisible(dialogName, widgetName, visible)\r\n  if not UI.isDialogLoaded(dialogName) then return end\r\n\r\n  UI.setWidgetVisibility(dialogName, widgetName, visible)\r\n  table.insert(widget_visible, { name = dialogName, id = widgetName, state = visible })\r\nend\r\n\r\nfunction clearWidgetVisible()\r\n  local str = \"\"\r\n  for i=#widget_visible, 1, -1 do\r\n    str = str .. toString(widget_visible[i].name) .. \"@\" .. toString(widget_visible[i].id) .. \";\"\r\n    UI.setWidgetVisibility(widget_visible[i].name, widget_visible[i].id, true)\r\n  end\r\n\r\n  widget_visible = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearWidgetVisible\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Rend Actif/Inactif un élément d'une interface\r\nfunction setWidgetEnable(dialogName, widgetName, enable)\r\n  if not UI.isDialogLoaded(dialogName) then return end\r\n\r\n  UI.setWidgetEnabled(dialogName, widgetName, enable)\r\n  table.insert(widget_enable, {name = dialogName, id = widgetName, state = enable})\r\nend\r\n\r\nfunction clearWidgetEnable()\r\n  local str = \"\"\r\n  for i=#widget_enable, 1, -1 do\r\n    str = str .. toString(widget_enable[i].name) .. \"@\" .. toString(widget_enable[i].id) .. \";\"\r\n    UI.setWidgetEnabled(widget_enable[i].name, widget_enable[i].id, true)\r\n  end\r\n\r\n  widget_enable = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearWidgetEnable\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Ajoute/Retire une TweenParticle à un élément d'une interface\r\nfunction setUIColorTween(dialogName, widgetName, duration, loop, r1, g1, b1, a1, r2, g2, b2, a2)\r\n  if not UI.isDialogLoaded(dialogName) then return end\r\n\r\n  UI.addColorTween(dialogName, widgetName, duration, loop, r1, g1, b1, a1, r2, g2, b2, a2)\r\n  table.insert(ui_tweens, {name = dialogName, id = widgetName})\r\nend\r\n\r\nfunction clearUIColorTweens(dialogName, widgetName)\r\n  local str = \"\"\r\n  for i=#ui_tweens, 1, -1 do\r\n    if ((not dialogName) or (dialogName == ui_tweens[i].name)) and ((not widgetName) or (widgetName == ui_tweens[i].id)) then\r\n      str = str .. toString(ui_tweens[i].name) .. \"@\" .. toString(ui_tweens[i].id) .. \";\"\r\n      UI.removeColorTween(ui_tweens[i].name, ui_tweens[i].id)\r\n      table.remove(ui_tweens, i)\r\n    end\r\n  end\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearUIColorTweens\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Ajoute/Retire une Particle à un élément d'une interface\r\nfunction setUIParticle(dialogName, widgetName, apsFileName, x, y, alignment, level)\r\n  if not UI.isDialogLoaded(dialogName) then return end\r\n\r\n  local particleId = UI.addParticle(dialogName, widgetName, apsFileName, x, y, alignment, level)\r\n  table.insert(ui_particles, {name = dialogName, id = widgetName})\r\n\r\n  return particleId\r\nend\r\n\r\nfunction setUIParticleBorder(dialogName, widgetName, apsFileName, x, y, alignment, level, speed)\r\n  if not UI.isDialogLoaded(dialogName) then return end\r\n\r\n  local particleId = UI.addParticleToBorder(dialogName, widgetName, apsFileName, x, y, alignment, level, speed)\r\n  table.insert(ui_particles, {name = dialogName, id = widgetName})\r\n\r\n  return particleId\r\nend\r\n\r\nfunction clearUIParticles(dialogName, widgetName)\r\n  local str = \"\"\r\n  for i=#ui_particles, 1, -1 do\r\n    if ((not dialogName) or (dialogName == ui_particles[i].name)) and ((not widgetName) or (widgetName == ui_particles[i].id)) then\r\n      str = str .. toString(ui_particles[i].name) .. \"@\" .. toString(ui_particles[i].id) .. \";\"\r\n      UI.clearParticles(ui_particles[i].name, ui_particles[i].id)\r\n      table.remove(ui_particles, i)\r\n    end\r\n  end\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearUIParticles\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Enregistre/Supprime un callback à l'ouverture d'une interface\r\nfunction addDialogLoadListener(dialog, funcName, ...)\r\n  UI.addDialogLoadedListener(dialog, funcName, unpack(arg))\r\n  table.insert(ui_listener_load,  dialog)\r\nend\r\n\r\nfunction clearDialogLoadListener(dialogName)\r\n  local str = \"\"\r\n  for i=#ui_listener_load, 1, -1 do\r\n    if (not dialogName) or (dialogName == ui_listener_load[i]) then\r\n      str = str .. toString(ui_listener_load[i]) .. \";\"\r\n      UI.removeDialogLoadedListener(ui_listener_load[i])\r\n      table.remove(ui_listener_load, i)\r\n    end\r\n  end\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearDialogLoadListener\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Enregistre/Supprime un callback à la fermeture d'une interface\r\nfunction addDialogUnloadListener(dialog, funcName, ...)\r\n  UI.addDialogUnloadedListener(dialog, funcName, unpack(arg))\r\n  table.insert(ui_listener_unload, dialog)\r\nend\r\n\r\nfunction clearDialogUnloadListener(dialogName)\r\n  local str = \"\"\r\n  for i=#ui_listener_unload, 1, -1 do\r\n    if (not dialogName) or (dialogName == ui_listener_unload[i]) then\r\n      str = str .. toString(ui_listener_unload[i]) .. \";\"\r\n      UI.removeDialogUnloadedListener(ui_listener_unload[i])\r\n      table.remove(ui_listener_unload, i)\r\n    end\r\n  end\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearDialogUnloadListener\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Enregistre/Supprime un callback sur un élément d'une interface\r\nfunction addDialogEventListener(dialog, id, eventType, funcName, ...)\r\n  if not UI.isDialogLoaded(dialog) then return end\r\n\r\n  UI.addEventListener(dialog, id, eventType, funcName, unpack(arg))\r\n  table.insert(ui_listener_event, {dialog=dialog, id=id, eventType=eventType, funcName=funcName})\r\nend\r\n\r\nfunction clearDialogEventListener(dialogName)\r\n  local str = \"\"\r\n  for i=#ui_listener_event, 1, -1 do\r\n    if (not dialogName) or (dialogName == ui_listener_event[i].dialog) then\r\n      str = str .. toString(ui_listener_event[i].dialog) .. \"@\" .. toString(ui_listener_event[i].id) .. \";\"\r\n      UI.removeEventListener(ui_listener_event[i].dialog, ui_listener_event[i].id, ui_listener_event[i].eventType, ui_listener_event[i].funcName)\r\n      table.remove(ui_listener_event, i)\r\n    end\r\n  end\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearDialogEventListener\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y , z, ...)\r\n  local particleId = Particle.addParticleSystem(particleFileId, x, y , z, unpack(arg))\r\n  table.insert(world_particles, particleId)\r\n\r\n  return particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n  local particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n  table.insert(world_particles, particleId)\r\n\r\n  return particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n  local str = \"\"\r\n  for i=#world_particles, 1, -1 do\r\n    str = str .. toString(world_particles[i]) .. \";\"\r\n    Particle.removeParticleSystem(world_particles[i])\r\n  end\r\n\r\n  world_particles = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n  BubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n  if isLower(mobileId, 0) then\r\n    BubbleText.setCharacterSpeak(mobileId, text)\r\n  else\r\n    if (not offsetY) then\r\n      local height = Mobile.getMobileHeight(mobileId)\r\n      if (not height) then height = 6 end\r\n\r\n      offsetY = height * 10\r\n    end\r\n\r\n    if (not offsetX) then offsetX = 0 end\r\n    if (not infiniteDuration) then infiniteDuration = false end\r\n\r\n    BubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n    UI.writeLocalisedInChat(text)\r\n  end\r\n\r\n  if (not tContains(bubbles, mobileId)) then\r\n    table.insert(bubbles, mobileId)\r\n  end\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n  local str = \"\"\r\n  for i = #bubbles, 1, -1 do\r\n    if (not mobileId) then\r\n      str = str .. toString(bubbles[i]) .. \";\"\r\n      BubbleText.closeBubbleAttachedTo(bubbles[i])\r\n    elseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n      str = str .. toString(bubbles[i]) .. \";\"\r\n      BubbleText.closeBubbleAttachedTo(bubbles[i])\r\n      table.remove(bubbles, i)\r\n    end\r\n  end\r\n\r\n  if (not mobileId) then bubbles = {} end\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n  local compassId = UI.addCompass(\"compass\", x, y, z)\r\n  table.insert(compasses, compassId)\r\n\r\n  return compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n  local str = \"\"\r\n  for i=#compasses, 1, -1 do\r\n    str = str .. toString(compasses[i]) .. \";\"\r\n    UI.removeCompass(compasses[i])\r\n  end\r\n\r\n  compasses = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height)\r\n  local mobileId = Mobile.generateClientMobileId()\r\n  Actor.createActor(mobileId, spriteName, worldX, worldY, worldZ, availableDirection)\r\n\r\n  if (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n  if (height) then Actor.setActorHeight(mobileId, height) end\r\n\r\n  table.insert(actors, mobileId)\r\n\r\n  return mobileId\r\nend\r\n\r\nfunction clearActors()\r\n  local str = \"\"\r\n  for i = #actors, 1, -1 do\r\n    str = str .. toString(actors[i]) .. \";\"\r\n    Actor.deleteActor(actors[i])\r\n  end\r\n\r\n  actors = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n  local taskId = invoke(delay, count, funcName, unpack(arg))\r\n  table.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n  local str = \"\"\r\n  for i=#invoke_tasks, 1, -1 do\r\n    str = str .. toString(invoke_tasks[i]) .. \";\"\r\n    interrupt(invoke_tasks[i])\r\n    desinvoke(invoke_tasks[i])\r\n  end\r\n\r\n  invoke_tasks = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n  invoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n  local taskId = setInterval(delay, funcName, unpack(arg))\r\n  table.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n  local str = \"\"\r\n  for i=#interval_tasks, 1, -1 do\r\n    str = str .. toString(interval_tasks[i]) .. \";\"\r\n    interrupt(interval_tasks[i])\r\n    desinvoke(interval_tasks[i])\r\n  end\r\n\r\n  interval_tasks = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n  if (_DEBUG) then trace(\"startCinematicContext\") end\r\n\r\n  UI.manageFrame(\"World\", false)\r\n  UI.closeMRU()\r\n  UI.closeAllBags()\r\n  UI.setUIVisible(false)\r\n  UI.displayWideScreenBand(true)\r\n  Camera.setUserZoomLocked(true)\r\n\r\n  if (cameraMobileId ~= nil)  then\r\n    Camera.setMoveSpeedFactor(10000)\r\n    Camera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n  end\r\n\r\n  if (zoomFactor ~= nil)  then\r\n    Camera.setZoomFactor(zoomFactor)\r\n  end\r\n\r\n  if (musicId ~= nil)  then\r\n    Sound.playForcedMusic(musicId)\r\n  end\r\n\r\n  if (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\nfunction skipCinematic()\r\n  local player = Context.getLeaderId()\r\n\r\n  for x = 1, #_ACTOR_LIST do\r\n    Actor.deleteActor(_ACTOR_LIST[x])\r\n  end\r\n\r\n  UI.hideButton()\r\n  clearALL()\r\n  stopCinematicContext(1, player, true)\r\n  Mobile.setMobileVisible(player, true)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n  if (_DEBUG) then trace(\"stopCinematicContext\") end\r\n\r\n  UI.displayWideScreenBand(false)\r\n  UI.setUIVisible(true)\r\n  Camera.setUserZoomLocked(false)\r\n  UI.manageFrame(\"World\", true)\r\n\r\n  Camera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n  Camera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n  if (zoomFactor ~= nil) then\r\n    Camera.setZoomFactor(zoomFactor)\r\n  end\r\n\r\n  if (cameraMobileId ~= nil) then\r\n    Camera.attachCameraToMobile(cameraMobileId)\r\n  end\r\n\r\n  if (stopMusic) then\r\n    Sound.stopForcedMusic()\r\n  end\r\n\r\n  if (_DEBUG) then\r\n    UI.hideButton()\r\n  end\r\n\r\n  --TRIGGER\r\n  Server.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Affiche/Masque une texture à l'écran\r\nfunction displayScreenEffect(enable, fadeInDur, alphaDur, fadeOutDur, r, g, b, alpha)\r\n  if (_DEBUG) then trace(\"displayScreenEffect\") end\r\n\r\n  if not enable and screenEffectId ~= nil  then\r\n    --On retire le blackScreen\r\n    Effect.stopEffect(screenEffectId)\r\n  else\r\n    --On affiche un blackScreen à l'entrée dans l'instance le temps qu'elle soit complètement chargée\r\n    screenEffectId = Effect.createFullScreenSprite(fadeInDur, alphaDur, fadeOutDur, r, g, b, alpha)\r\n  end\r\nend\r\n\r\n-- FONCTION NETTOYAGE --\r\nfunction clearALL()\r\n  clearIntervalTasks()\r\n  clearInvokeTasks()\r\n  clearBubbles()\r\n  clearUIColorTweens()\r\n  clearUIParticles()\r\n  clearWorldParticles()\r\n  clearCompasses()\r\n  clearActors()\r\n\r\n  Focus.display(false)\r\n  UI.unloadTutorialDialog()\r\nend\r\n\r\n-- FONCTION NETTOYAGE --\r\nfunction clearUI(dialogName)\r\n  clearUIColorTweens(dialogName)\r\n  clearUIParticles(dialogName)\r\nend\r\n\r\n-- FONCTION NETTOYAGE --\r\nfunction clearListener(dialogName)\r\n  clearDialogLoadListener(dialogName)\r\n  clearDialogUnloadListener(dialogName)\r\n  clearDialogEventListener(dialogName)\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\nfunction onInstanceLoaded()\r\n    if (_DEBUG) then\r\n        trace(\"ON INSTANCE LOADED\")\r\n    end\r\n\r\n    UI.manageFrame(\"World\", true)\r\n    UI.setUIVisible(true)\r\n    displayScreenEffect(false)\r\n\r\n    -- TRIGGER\r\n    Server.triggerEvent(24134)\r\nend\n\n-- ENTER_INSTANCE - Inscription au scénario + notif\n-- \nfunction event_2715_24133()\n    if (_DEBUG) then\r\n        trace(\"ENTER INSTANCE\")\r\n    end\r\n    \r\n    Event.runOnInstanceLoaded(\"onInstanceLoaded\")\nend\n\n-- Ping serveur (via onInstanceLoaded ou IEaction) - Don jetons\n-- \nfunction event_2715_24134()\n    -- \"Don Jetons\"\nend\n\n-- DIALOG_EXECUTED - On notif au scénario qu'on a parlé à Aguabrial\n-- \nfunction event_2715_24135()\n    -- \"On joue le don de jeton après la validation de l'achievement\"\r\n    \r\n    invoke(1000, 1, \"Server.triggerEvent\", 24134)\nend\n\n","functions":["tContains","prepareChatUI","prepareFollowQuestUI","prepareUI","prepareShortcuts","setWidgetVisible","clearWidgetVisible","setWidgetEnable","clearWidgetEnable","setUIColorTween","clearUIColorTweens","setUIParticle","setUIParticleBorder","clearUIParticles","addDialogLoadListener","clearDialogLoadListener","addDialogUnloadListener","clearDialogUnloadListener","addDialogEventListener","clearDialogEventListener","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","bubble","clearBubbles","setCompass","clearCompasses","createActor","clearActors","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","startCinematicContext","skipCinematic","stopCinematicContext","displayScreenEffect","clearALL","clearUI","clearListener","fullScreen","text","onInstanceLoaded","event_2715_24133","event_2715_24134","event_2715_24135"],"quest_calls":[],"dialogue_calls":[]},"scenario/2716.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n-- TRIGGER CLIENT --\r\n-- 0 = Fin cinématique VIDEO | Déclenché par le callback Video.addVideoStopOrEndCallback\r\n-- 1 = Arrivée dans l'instance | Déclenché par onInstanceLoaded() callback par Event.runOnInstanceLoaded (cf code Global)\r\n-- 2 = Fin cinématique | Déclenché par stopCinematicContext() (cf code Global)\r\n-- 3 = Fermeture UI Fin de combat\r\n-- 4 = Clic sur le bon bouton de changement d'oriention (parmis les 4) dans UI worldAndFightBar pour s'orientation vers le monstre\r\n-- 5 = Fermeture UI Fiche combattant\r\n-- 6 = Clic sur le bouton de validation de la répartition dans UI Aptitudes\r\n-- 7 = Clic sur la boussole du bon objectif dans l'UI suivi de quête\r\n-- 8 = Fermeture UI Map Monde\r\n\r\n-- VARIABLE GLOBALE - SCRIPT --\r\n\r\nwidget_visible = {}\r\nwidget_enable = {}\r\nui_tweens = {}\r\nui_particles = {}\r\nui_listener_load = {}\r\nui_listener_unload = {}\r\nui_listener_event = {}\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\nscreenEffectId = nil\r\n\r\n-- VARIABLE GLOBALE - MOBILE CINEMATIQUE & TUTO --\r\n\r\nANM_otomai = {think=\"AnimComp-Special03\", talk=\"AnimComp-Special04-Debut\", show=\"AnimComp-Special05-Debut\", nice=\"AnimComp-Special07\", nope=\"AnimComp-Special08\", lol=\"AnimComp-Special09\", stop_it=\"AnimComp-Special10\", come_here=\"AnimComp-Special01\", wave_hit=\"AnimComp-Special02\", fly=\"AnimStatique-Oiseau\", cast=\"AnimSort-01\", supercast=\"AnimComp-Special11\", attack=\"AnimSort-Cast\", balance=\"AnimComp-Special06\"}\r\nANM_melee = {attack=\"AnimSort-Morsure\", glitch1=\"AnimComp-Glitch01\", glitch2=\"AnimComp-Glitch02\", glitch3=\"AnimComp-Glitch03\", roar=\"AnimComp-Agressif\"}\r\nANM_range = {attack=\"AnimSort-01\", glitch=\"AnimComp-Glitch\", dupli=\"AnimComp-Dupli\"}\r\nANM_boss = {attack1=\"AnimSort-Estoc\", attack2=\"AnimSort-Hrargh\", glitch=\"AnimComp-Glitch\", dupli=\"AnimComp-Dupli\", roar=\"AnimComp-Hurle\", ko = \"AnimKO-SortieOK\", death= \"AnimKO-SortieHS\"}\r\n\r\nNPC_otomai = Mobile.generateClientMobileId()\r\nNPC_otomai_gfx = 181404009\r\nNPC_otomai_particleZ = 10\r\nNPC_otomai_bubbleX = 10\r\nNPC_otomai_bubbleY = 70\r\n\r\nNPC_melee = Mobile.generateClientMobileId()\r\nNPC_meleeB = Mobile.generateClientMobileId()\r\nNPC_melee_gfx = 181404014\r\nNPC_melee_particleZ = 5\r\n\r\nNPC_range = Mobile.generateClientMobileId()\r\nNPC_range_gfx = 181404015\r\nNPC_range_particleZ = 3\r\n\r\nNPC_boss = Mobile.generateClientMobileId()\r\nNPC_boss_gfx = 181404012\r\nNPC_boss_particleZ = 8\r\n\r\nNPC_eni_wakfu = Mobile.generateClientMobileId()\r\nNPC_eni_wakfu_gfx = 181404034\r\nNPC_eni_wakfu_particleZ = 7\r\n\r\nNPC_eni_stasis = Mobile.generateClientMobileId()\r\nNPC_eni_stasis_gfx = 181404013\r\nNPC_eni_stasis_particleZ = 7\r\n\r\n_ACTOR_LIST = {NPC_otomai, NPC_melee, NPC_meleeB, NPC_range, NPC_boss, NPC_eni_wakfu, NPC_eni_stasis}\r\n\r\n-- VARIABLE GLOBALE - PARTICULE CINEMATIQUE & TUTO --\r\n\r\n-- UI TUTO\r\napsArrowBig = {6001069,6001070,6001071,6001072,6001073,6001074,6001075,6001076}\r\napsArrow = {6001061,6001062,6001063,6001064,6001065,6001066,6001067,6001068}\r\napsCenter = {ap=6001090, mp=6001091, wp=6001092, hp=6001093}\r\napsFollowBorder = -1548037644\r\n-- WORLD TUTO\r\napsCell = {white_border=800578, red_border=800579, white_arrow=800576, red_arrow=800577, white=800581, red=800582, show=78900}\r\n-- CINEMATIQUE\r\napsWave = {spawn=800573, wave=800574, hit=800575}\r\napsOtomai = {shield=-1814057071, transform=-1814057072, playershield = -1814057074}\r\napsCristal = {base=71071022, react=800580, shield=71071021}\r\napsBoss = {death=-1814057073}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n    for index, value in ipairs (tab) do\r\n\t\tif isEqual(value, val) then\r\n            return true\r\n        end\r\n    end\r\n\r\n    return false\t\r\nend\r\n\r\n-- FONCTION UI -- Replace le Chat en bas à gauche et le rend indéplaçable/déplaçable\r\nfunction prepareChatUI(movable, chatOffsetX)\r\n\tif not UI.isDialogLoaded(\"chatDialog0\") then return end\r\n\t\r\n\tif (not chatOffsetX) then chatOffsetX = 0 end\r\n\t\r\n\tUI.setPosition(\"chatDialog0\", chatOffsetX, 0)\r\n\tUI.setWindowMovable(\"chatDialog0\", movable)\r\nend\r\n\r\n-- FONCTION UI -- Replace le Suivi de Quête mi-hauteur à gauche et le rend indéplaçable/déplaçable\r\nfunction prepareFollowQuestUI(movable)\r\n    local dialogName = \"\"\r\n    if UI.isDialogLoaded(\"verticalFollowedAchievementsDialog\") then\r\n        dialogName = \"verticalFollowedAchievementsDialog\"\r\n    end\r\n    if UI.isDialogLoaded(\"followedAchievementsDialog\") then\r\n        dialogName = \"followedAchievementsDialog\"\r\n    end\r\n\r\n    if (dialogName == \"\") then\r\n        return\r\n    end\r\n\r\n    local screenH, screenW = UI.getWindowSize()\r\n    local x, y = UI.getPosition(dialogName)\r\n\r\n    UI.setPosition(dialogName, x, screenH / 4)\r\n    UI.setWindowMovable(dialogName, movable)\r\nend\r\n\r\n-- FONCTION UI -- Rend Visible/Invisible certains éléments des interfaces\r\nfunction prepareUI(visible)\r\n  --Interface Boutique & Cadeau\r\n  setWidgetVisible(\"topHudDialog\", \"optionShopButton\", visible)\r\n  setWidgetVisible(\"topHudDialog\", \"giftButton\", visible)\r\n\r\n  --UI sous le Coeur\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"wakfuStasisBar\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"xpBar\", visible)\r\n\r\n  --Boutons hors combat à droite du Coeur\r\n  setWidgetVisible(\"shortcutBarDialog\", \"previousButton\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"nextButton\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseShortcutBar1\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseShortcutBar2\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseShortcutBar3\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseShortcutBar4\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"shortcutBarItemButton\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"shortcutBarSpellButton\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseButtonContainerForTuto1\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseButtonContainerForTuto2\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseButtonContainerForTuto3\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseButtonContainerForTuto4\", visible)\r\n\r\n  --Boutons hors combat à gauche de l'écran - barre d'interfaces\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"firstInterfaceBarBackground\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"secondInterfaceBarBackground\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"extraInterfaceBarDrawerButton\", visible)\r\n\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"fightInfoBtn\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"inventoryButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"buildSheetSetButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"craftButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"questsButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"dungeonButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"cosmeticsButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"tutorialBookButton\", visible)\r\n\r\n  --Boutons hors combat à gauche de l'écran - barre d'interfaces (deuxième barre)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"contactListButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"guildButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"companionsButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"nationButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"battlegroundButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"passportButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"emoteButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"encyclopediaButton\", visible)\r\n\r\n  --Boutons hors combat \"actions rapides\"\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"OverWorldActionsBackground\", visible)\r\n\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"dimensionalBagButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"mapButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"rideMountButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"miniMapButton\", visible)\r\n\r\n  --Boutons en combat à gauche du Coeur\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"FightActionsBackground\", visible)\r\n\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"giveUpButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"hideFightersButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"tacticalModeBtn\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"reportCellBtn\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"fightMarkerBtn\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"lockFightBtn\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"resistanceOverheadBtn\", visible)\r\nend\r\n\r\n-- FONCTION SHORTCUT -- Rend Actif/Inactif certains raccourcis\r\nfunction prepareShortcuts(enabled, shortcutType)\r\n  if not shortcutType or shortcutType == \"WORLD\" then\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.world\", \"enterLeaveBag\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.world\", \"switchHero0\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.world\", \"switchHero1\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.world\", \"switchHero2\")\r\n  end\r\n  if not shortcutType or shortcutType == \"DISPLAY\" then\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"zoomIn\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"zoomOut\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"closeWindows\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"setLODLevel\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"setFightLODLevel\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"showHideNameOverheadsCommand\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"hideFightOccluders\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"alphaMask\")\r\n  end\r\n  if not shortcutType or shortcutType == \"CHAT\" then\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.chat\", \"chat\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.chat\", \"lastContact\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.chat\", \"firstContact\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.chat\", \"autoCompletePlayerName\")\r\n    for bind=1, 9, 1 do\r\n      UI.setShortcutEnabled(enabled, \"shortcutCategory.shortcutBar\", \"bind\" .. toString(bind))\r\n    end\r\n  end\r\n\r\n  if not shortcutType or shortcutType == \"FIGHT\" then\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"fighterTransparency\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"switchTacticalView\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"nextSelectedFighter\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"giveUp\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"lockFight\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"reportCell\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"callHelp\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"displayHpBar\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"resetFightCamera\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"endPlacementAndTurn\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"closeCombatRight\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"closeCombatLeft\")\r\n  end\r\n  if not shortcutType or shortcutType == \"INTERFACE\" then\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"minimap\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"contactList\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"companionManagement\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"guild\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"craft\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"dungeonList\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"achievements\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"quests\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"emotes\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"ecosystem\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"climate\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"nation\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"partySearch\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"passport\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"almanax\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"tutorialBook\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"switchToDirectAttackCommand\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"map\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"spellsInventory\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"inventory\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"characterBook\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"osamodasSymbiot\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"shortcutBar0\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"shortcutBar1\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"shortcutBar2\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"shortcutBar3\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"additionalShortcutBar0\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"additionalShortcutBar1\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"additionalShortcutBar2\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"additionalShortcutBar3\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"changeShortcutBarType\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"downscaling\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"rewards\")\r\n\tUI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"battlegroundList\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"aptitudes\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"presets\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"encyclopedia\")\r\n  end\r\n\r\n  -- On ne bloque pas les raccourcis de sorts finalement\r\n--   if not shortcutType or shortcutType == \"SHORTCUTBAR\" then\r\n--     for bar=0,3, 1 do\r\n--       for slot=0, 9, 1 do\r\n--         UI.setShortcutEnabled(enabled, \"shortcutCategory.shortcutBar\", \"shortcut\" .. toString(bar) .. toString(slot))\r\n--       end\r\n--     end\r\n--   end\r\nend\r\n\r\n-- FONCTION UI -- Rend Visible/Invisible un élément d'une interface\r\nfunction setWidgetVisible(dialogName, widgetName, visible)\r\n  if not UI.isDialogLoaded(dialogName) then return end\r\n\r\n  UI.setWidgetVisibility(dialogName, widgetName, visible)\r\n  table.insert(widget_visible, { name = dialogName, id = widgetName, state = visible })\r\nend\r\n\r\nfunction clearWidgetVisible()\r\n  local str = \"\"\r\n  for i=#widget_visible, 1, -1 do\r\n    str = str .. toString(widget_visible[i].name) .. \"@\" .. toString(widget_visible[i].id) .. \";\"\r\n    UI.setWidgetVisibility(widget_visible[i].name, widget_visible[i].id, true)\r\n  end\r\n\r\n  widget_visible = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearWidgetVisible\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Rend Actif/Inactif un élément d'une interface\r\nfunction setWidgetEnable(dialogName, widgetName, enable)\r\n  if not UI.isDialogLoaded(dialogName) then return end\r\n\r\n  UI.setWidgetEnabled(dialogName, widgetName, enable)\r\n  table.insert(widget_enable, {name = dialogName, id = widgetName, state = enable})\r\nend\r\n\r\nfunction clearWidgetEnable()\r\n  local str = \"\"\r\n  for i=#widget_enable, 1, -1 do\r\n    str = str .. toString(widget_enable[i].name) .. \"@\" .. toString(widget_enable[i].id) .. \";\"\r\n    UI.setWidgetEnabled(widget_enable[i].name, widget_enable[i].id, true)\r\n  end\r\n\r\n  widget_enable = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearWidgetEnable\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Ajoute/Retire une TweenParticle à un élément d'une interface\r\nfunction setUIColorTween(dialogName, widgetName, duration, loop, r1, g1, b1, a1, r2, g2, b2, a2)\r\n  if not UI.isDialogLoaded(dialogName) then return end\r\n\r\n  UI.addColorTween(dialogName, widgetName, duration, loop, r1, g1, b1, a1, r2, g2, b2, a2)\r\n  table.insert(ui_tweens, {name = dialogName, id = widgetName})\r\nend\r\n\r\nfunction clearUIColorTweens(dialogName, widgetName)\r\n  local str = \"\"\r\n  for i=#ui_tweens, 1, -1 do\r\n    if ((not dialogName) or (dialogName == ui_tweens[i].name)) and ((not widgetName) or (widgetName == ui_tweens[i].id)) then\r\n      str = str .. toString(ui_tweens[i].name) .. \"@\" .. toString(ui_tweens[i].id) .. \";\"\r\n      UI.removeColorTween(ui_tweens[i].name, ui_tweens[i].id)\r\n      table.remove(ui_tweens, i)\r\n    end\r\n  end\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearUIColorTweens\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Ajoute/Retire une Particle à un élément d'une interface\r\nfunction setUIParticle(dialogName, widgetName, apsFileName, x, y, alignment, level)\r\n  if not UI.isDialogLoaded(dialogName) then return end\r\n\r\n  local particleId = UI.addParticle(dialogName, widgetName, apsFileName, x, y, alignment, level)\r\n  table.insert(ui_particles, {name = dialogName, id = widgetName})\r\n\r\n  return particleId\r\nend\r\n\r\nfunction setUIParticleBorder(dialogName, widgetName, apsFileName, x, y, alignment, level, speed)\r\n  if not UI.isDialogLoaded(dialogName) then return end\r\n\r\n  local particleId = UI.addParticleToBorder(dialogName, widgetName, apsFileName, x, y, alignment, level, speed)\r\n  table.insert(ui_particles, {name = dialogName, id = widgetName})\r\n\r\n  return particleId\r\nend\r\n\r\nfunction clearUIParticles(dialogName, widgetName)\r\n  local str = \"\"\r\n  for i=#ui_particles, 1, -1 do\r\n    if ((not dialogName) or (dialogName == ui_particles[i].name)) and ((not widgetName) or (widgetName == ui_particles[i].id)) then\r\n      str = str .. toString(ui_particles[i].name) .. \"@\" .. toString(ui_particles[i].id) .. \";\"\r\n      UI.clearParticles(ui_particles[i].name, ui_particles[i].id)\r\n      table.remove(ui_particles, i)\r\n    end\r\n  end\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearUIParticles\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Enregistre/Supprime un callback à l'ouverture d'une interface\r\nfunction addDialogLoadListener(dialog, funcName, ...)\r\n  UI.addDialogLoadedListener(dialog, funcName, unpack(arg))\r\n  table.insert(ui_listener_load,  dialog)\r\nend\r\n\r\nfunction clearDialogLoadListener(dialogName)\r\n  local str = \"\"\r\n  for i=#ui_listener_load, 1, -1 do\r\n    if (not dialogName) or (dialogName == ui_listener_load[i]) then\r\n      str = str .. toString(ui_listener_load[i]) .. \";\"\r\n      UI.removeDialogLoadedListener(ui_listener_load[i])\r\n      table.remove(ui_listener_load, i)\r\n    end\r\n  end\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearDialogLoadListener\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Enregistre/Supprime un callback à la fermeture d'une interface\r\nfunction addDialogUnloadListener(dialog, funcName, ...)\r\n  UI.addDialogUnloadedListener(dialog, funcName, unpack(arg))\r\n  table.insert(ui_listener_unload, dialog)\r\nend\r\n\r\nfunction clearDialogUnloadListener(dialogName)\r\n  local str = \"\"\r\n  for i=#ui_listener_unload, 1, -1 do\r\n    if (not dialogName) or (dialogName == ui_listener_unload[i]) then\r\n      str = str .. toString(ui_listener_unload[i]) .. \";\"\r\n      UI.removeDialogUnloadedListener(ui_listener_unload[i])\r\n      table.remove(ui_listener_unload, i)\r\n    end\r\n  end\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearDialogUnloadListener\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Enregistre/Supprime un callback sur un élément d'une interface\r\nfunction addDialogEventListener(dialog, id, eventType, funcName, ...)\r\n  if not UI.isDialogLoaded(dialog) then return end\r\n\r\n  UI.addEventListener(dialog, id, eventType, funcName, unpack(arg))\r\n  table.insert(ui_listener_event, {dialog=dialog, id=id, eventType=eventType, funcName=funcName})\r\nend\r\n\r\nfunction clearDialogEventListener(dialogName)\r\n  local str = \"\"\r\n  for i=#ui_listener_event, 1, -1 do\r\n    if (not dialogName) or (dialogName == ui_listener_event[i].dialog) then\r\n      str = str .. toString(ui_listener_event[i].dialog) .. \"@\" .. toString(ui_listener_event[i].id) .. \";\"\r\n      UI.removeEventListener(ui_listener_event[i].dialog, ui_listener_event[i].id, ui_listener_event[i].eventType, ui_listener_event[i].funcName)\r\n      table.remove(ui_listener_event, i)\r\n    end\r\n  end\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearDialogEventListener\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y , z, ...)\r\n  local particleId = Particle.addParticleSystem(particleFileId, x, y , z, unpack(arg))\r\n  table.insert(world_particles, particleId)\r\n\r\n  return particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n  local particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n  table.insert(world_particles, particleId)\r\n\r\n  return particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n  local str = \"\"\r\n  for i=#world_particles, 1, -1 do\r\n    str = str .. toString(world_particles[i]) .. \";\"\r\n    Particle.removeParticleSystem(world_particles[i])\r\n  end\r\n\r\n  world_particles = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n  BubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n  if isLower(mobileId, 0) then\r\n    BubbleText.setCharacterSpeak(mobileId, text)\r\n  else\r\n    if (not offsetY) then\r\n      local height = Mobile.getMobileHeight(mobileId)\r\n      if (not height) then height = 6 end\r\n\r\n      offsetY = height * 10\r\n    end\r\n\r\n    if (not offsetX) then offsetX = 0 end\r\n    if (not infiniteDuration) then infiniteDuration = false end\r\n\r\n    BubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n    UI.writeLocalisedInChat(text)\r\n  end\r\n\r\n  if (not tContains(bubbles, mobileId)) then\r\n    table.insert(bubbles, mobileId)\r\n  end\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n  local str = \"\"\r\n  for i = #bubbles, 1, -1 do\r\n    if (not mobileId) then\r\n      str = str .. toString(bubbles[i]) .. \";\"\r\n      BubbleText.closeBubbleAttachedTo(bubbles[i])\r\n    elseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n      str = str .. toString(bubbles[i]) .. \";\"\r\n      BubbleText.closeBubbleAttachedTo(bubbles[i])\r\n      table.remove(bubbles, i)\r\n    end\r\n  end\r\n\r\n  if (not mobileId) then bubbles = {} end\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n  local compassId = UI.addCompass(\"compass\", x, y, z)\r\n  table.insert(compasses, compassId)\r\n\r\n  return compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n  local str = \"\"\r\n  for i=#compasses, 1, -1 do\r\n    str = str .. toString(compasses[i]) .. \";\"\r\n    UI.removeCompass(compasses[i])\r\n  end\r\n\r\n  compasses = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height)\r\n  local mobileId = Mobile.generateClientMobileId()\r\n  Actor.createActor(mobileId, spriteName, worldX, worldY, worldZ, availableDirection)\r\n\r\n  if (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n  if (height) then Actor.setActorHeight(mobileId, height) end\r\n\r\n  table.insert(actors, mobileId)\r\n\r\n  return mobileId\r\nend\r\n\r\nfunction clearActors()\r\n  local str = \"\"\r\n  for i = #actors, 1, -1 do\r\n    str = str .. toString(actors[i]) .. \";\"\r\n    Actor.deleteActor(actors[i])\r\n  end\r\n\r\n  actors = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n  local taskId = invoke(delay, count, funcName, unpack(arg))\r\n  table.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n  local str = \"\"\r\n  for i=#invoke_tasks, 1, -1 do\r\n    str = str .. toString(invoke_tasks[i]) .. \";\"\r\n    interrupt(invoke_tasks[i])\r\n    desinvoke(invoke_tasks[i])\r\n  end\r\n\r\n  invoke_tasks = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n  invoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n  local taskId = setInterval(delay, funcName, unpack(arg))\r\n  table.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n  local str = \"\"\r\n  for i=#interval_tasks, 1, -1 do\r\n    str = str .. toString(interval_tasks[i]) .. \";\"\r\n    interrupt(interval_tasks[i])\r\n    desinvoke(interval_tasks[i])\r\n  end\r\n\r\n  interval_tasks = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n  if (_DEBUG) then trace(\"startCinematicContext\") end\r\n\r\n  UI.manageFrame(\"World\", false)\r\n  UI.closeMRU()\r\n  UI.closeAllBags()\r\n  UI.setUIVisible(false)\r\n  UI.displayWideScreenBand(true)\r\n  Camera.setUserZoomLocked(true)\r\n\r\n  if (cameraMobileId ~= nil)  then\r\n    Camera.setMoveSpeedFactor(10000)\r\n    Camera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n  end\r\n\r\n  if (zoomFactor ~= nil)  then\r\n    Camera.setZoomFactor(zoomFactor)\r\n  end\r\n\r\n  if (musicId ~= nil)  then\r\n    Sound.playForcedMusic(musicId)\r\n  end\r\n\r\n  if (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\nfunction skipCinematic()\r\n  local player = Context.getLeaderId()\r\n\r\n  for x = 1, #_ACTOR_LIST do\r\n    Actor.deleteActor(_ACTOR_LIST[x])\r\n  end\r\n\r\n  UI.hideButton()\r\n  clearALL()\r\n  stopCinematicContext(1, player, true)\r\n  Mobile.setMobileVisible(player, true)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n  if (_DEBUG) then trace(\"stopCinematicContext\") end\r\n\r\n  UI.displayWideScreenBand(false)\r\n  UI.setUIVisible(true)\r\n  Camera.setUserZoomLocked(false)\r\n  UI.manageFrame(\"World\", true)\r\n\r\n  Camera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n  Camera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n  if (zoomFactor ~= nil) then\r\n    Camera.setZoomFactor(zoomFactor)\r\n  end\r\n\r\n  if (cameraMobileId ~= nil) then\r\n    Camera.attachCameraToMobile(cameraMobileId)\r\n  end\r\n\r\n  if (stopMusic) then\r\n    Sound.stopForcedMusic()\r\n  end\r\n\r\n  if (_DEBUG) then\r\n    UI.hideButton()\r\n  end\r\n\r\n  --TRIGGER\r\n  Server.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Affiche/Masque une texture à l'écran\r\nfunction displayScreenEffect(enable, fadeInDur, alphaDur, fadeOutDur, r, g, b, alpha)\r\n  if (_DEBUG) then trace(\"displayScreenEffect\") end\r\n\r\n  if not enable and screenEffectId ~= nil  then\r\n    --On retire le blackScreen\r\n    Effect.stopEffect(screenEffectId)\r\n  else\r\n    --On affiche un blackScreen à l'entrée dans l'instance le temps qu'elle soit complètement chargée\r\n    screenEffectId = Effect.createFullScreenSprite(fadeInDur, alphaDur, fadeOutDur, r, g, b, alpha)\r\n  end\r\nend\r\n\r\n-- FONCTION NETTOYAGE --\r\nfunction clearALL()\r\n  clearIntervalTasks()\r\n  clearInvokeTasks()\r\n  clearBubbles()\r\n  clearUIColorTweens()\r\n  clearUIParticles()\r\n  clearWorldParticles()\r\n  clearCompasses()\r\n  clearActors()\r\n\r\n  Focus.display(false)\r\n  UI.unloadTutorialDialog()\r\nend\r\n\r\n-- FONCTION NETTOYAGE --\r\nfunction clearUI(dialogName)\r\n  clearUIColorTweens(dialogName)\r\n  clearUIParticles(dialogName)\r\nend\r\n\r\n-- FONCTION NETTOYAGE --\r\nfunction clearListener(dialogName)\r\n  clearDialogLoadListener(dialogName)\r\n  clearDialogUnloadListener(dialogName)\r\n  clearDialogEventListener(dialogName)\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\nfunction onInstanceLoaded()\r\n    if (_DEBUG) then\r\n        trace(\"ON INSTANCE LOADED\")\r\n    end\r\n\r\n    UI.manageFrame(\"World\", true)\r\n    UI.setUIVisible(true)\r\n    displayScreenEffect(false)\r\n\r\n    -- TRIGGER\r\n    Server.triggerEvent(24142)\r\nend\n\n-- ENTER_INSTANCE - Inscription au scénario + notif\n-- \nfunction event_2716_24142()\n    if (_DEBUG) then\r\n        trace(\"ENTER INSTANCE\")\r\n    end\r\n    \r\n    Event.runOnInstanceLoaded(\"onInstanceLoaded\")\nend\n\n-- Ping serveur (via onInstanceLoaded ou IEaction) - Don jetons\n-- \nfunction event_2716_24143()\n    -- \"Don Jetons\"\r\n    \r\n    if (_DEBUG) then\r\n        trace(\"GIVE TOKENS\")\r\n    end\nend\n\n","functions":["tContains","prepareChatUI","prepareFollowQuestUI","prepareUI","prepareShortcuts","setWidgetVisible","clearWidgetVisible","setWidgetEnable","clearWidgetEnable","setUIColorTween","clearUIColorTweens","setUIParticle","setUIParticleBorder","clearUIParticles","addDialogLoadListener","clearDialogLoadListener","addDialogUnloadListener","clearDialogUnloadListener","addDialogEventListener","clearDialogEventListener","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","bubble","clearBubbles","setCompass","clearCompasses","createActor","clearActors","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","startCinematicContext","skipCinematic","stopCinematicContext","displayScreenEffect","clearALL","clearUI","clearListener","fullScreen","text","onInstanceLoaded","event_2716_24142","event_2716_24143"],"quest_calls":[],"dialogue_calls":[]},"scenario/2717.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n-- TRIGGER CLIENT --\r\n-- 0 = Fin cinématique VIDEO | Déclenché par le callback Video.addVideoStopOrEndCallback\r\n-- 1 = Arrivée dans l'instance | Déclenché par onInstanceLoaded() callback par Event.runOnInstanceLoaded (cf code Global)\r\n-- 2 = Fin cinématique | Déclenché par stopCinematicContext() (cf code Global)\r\n-- 3 = Fermeture UI Fin de combat\r\n-- 4 = Clic sur le bon bouton de changement d'oriention (parmis les 4) dans UI worldAndFightBar pour s'orientation vers le monstre\r\n-- 5 = Fermeture UI Fiche combattant\r\n-- 6 = Clic sur le bouton de validation de la répartition dans UI Aptitudes\r\n-- 7 = Clic sur la boussole du bon objectif dans l'UI suivi de quête\r\n-- 8 = Fermeture UI Map Monde\r\n\r\n-- VARIABLE GLOBALE - SCRIPT --\r\n\r\nwidget_visible = {}\r\nwidget_enable = {}\r\nui_tweens = {}\r\nui_particles = {}\r\nui_listener_load = {}\r\nui_listener_unload = {}\r\nui_listener_event = {}\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\nscreenEffectId = nil\r\n\r\n-- VARIABLE GLOBALE - MOBILE CINEMATIQUE & TUTO --\r\n\r\nANM_otomai = {think=\"AnimComp-Special03\", talk=\"AnimComp-Special04-Debut\", show=\"AnimComp-Special05-Debut\", nice=\"AnimComp-Special07\", nope=\"AnimComp-Special08\", lol=\"AnimComp-Special09\", stop_it=\"AnimComp-Special10\", come_here=\"AnimComp-Special01\", wave_hit=\"AnimComp-Special02\", fly=\"AnimStatique-Oiseau\", cast=\"AnimSort-01\", supercast=\"AnimComp-Special11\", attack=\"AnimSort-Cast\", balance=\"AnimComp-Special06\"}\r\nANM_melee = {attack=\"AnimSort-Morsure\", glitch1=\"AnimComp-Glitch01\", glitch2=\"AnimComp-Glitch02\", glitch3=\"AnimComp-Glitch03\", roar=\"AnimComp-Agressif\"}\r\nANM_range = {attack=\"AnimSort-01\", glitch=\"AnimComp-Glitch\", dupli=\"AnimComp-Dupli\"}\r\nANM_boss = {attack1=\"AnimSort-Estoc\", attack2=\"AnimSort-Hrargh\", glitch=\"AnimComp-Glitch\", dupli=\"AnimComp-Dupli\", roar=\"AnimComp-Hurle\", ko = \"AnimKO-SortieOK\", death= \"AnimKO-SortieHS\"}\r\n\r\nNPC_otomai = Mobile.generateClientMobileId()\r\nNPC_otomai_gfx = 181404009\r\nNPC_otomai_particleZ = 10\r\nNPC_otomai_bubbleX = 10\r\nNPC_otomai_bubbleY = 70\r\n\r\nNPC_melee = Mobile.generateClientMobileId()\r\nNPC_meleeB = Mobile.generateClientMobileId()\r\nNPC_melee_gfx = 181404014\r\nNPC_melee_particleZ = 5\r\n\r\nNPC_range = Mobile.generateClientMobileId()\r\nNPC_range_gfx = 181404015\r\nNPC_range_particleZ = 3\r\n\r\nNPC_boss = Mobile.generateClientMobileId()\r\nNPC_boss_gfx = 181404012\r\nNPC_boss_particleZ = 8\r\n\r\nNPC_eni_wakfu = Mobile.generateClientMobileId()\r\nNPC_eni_wakfu_gfx = 181404034\r\nNPC_eni_wakfu_particleZ = 7\r\n\r\nNPC_eni_stasis = Mobile.generateClientMobileId()\r\nNPC_eni_stasis_gfx = 181404013\r\nNPC_eni_stasis_particleZ = 7\r\n\r\n_ACTOR_LIST = {NPC_otomai, NPC_melee, NPC_meleeB, NPC_range, NPC_boss, NPC_eni_wakfu, NPC_eni_stasis}\r\n\r\n-- VARIABLE GLOBALE - PARTICULE CINEMATIQUE & TUTO --\r\n\r\n-- UI TUTO\r\napsArrowBig = {6001069,6001070,6001071,6001072,6001073,6001074,6001075,6001076}\r\napsArrow = {6001061,6001062,6001063,6001064,6001065,6001066,6001067,6001068}\r\napsCenter = {ap=6001090, mp=6001091, wp=6001092, hp=6001093}\r\napsFollowBorder = -1548037644\r\n-- WORLD TUTO\r\napsCell = {white_border=800578, red_border=800579, white_arrow=800576, red_arrow=800577, white=800581, red=800582, show=78900}\r\n-- CINEMATIQUE\r\napsWave = {spawn=800573, wave=800574, hit=800575}\r\napsOtomai = {shield=-1814057071, transform=-1814057072, playershield = -1814057074}\r\napsCristal = {base=71071022, react=800580, shield=71071021}\r\napsBoss = {death=-1814057073}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n    for index, value in ipairs (tab) do\r\n\t\tif isEqual(value, val) then\r\n            return true\r\n        end\r\n    end\r\n\r\n    return false\t\r\nend\r\n\r\n-- FONCTION UI -- Replace le Chat en bas à gauche et le rend indéplaçable/déplaçable\r\nfunction prepareChatUI(movable, chatOffsetX)\r\n\tif not UI.isDialogLoaded(\"chatDialog0\") then return end\r\n\t\r\n\tif (not chatOffsetX) then chatOffsetX = 0 end\r\n\t\r\n\tUI.setPosition(\"chatDialog0\", chatOffsetX, 0)\r\n\tUI.setWindowMovable(\"chatDialog0\", movable)\r\nend\r\n\r\n-- FONCTION UI -- Replace le Suivi de Quête mi-hauteur à gauche et le rend indéplaçable/déplaçable\r\nfunction prepareFollowQuestUI(movable)\r\n    local dialogName = \"\"\r\n    if UI.isDialogLoaded(\"verticalFollowedAchievementsDialog\") then\r\n        dialogName = \"verticalFollowedAchievementsDialog\"\r\n    end\r\n    if UI.isDialogLoaded(\"followedAchievementsDialog\") then\r\n        dialogName = \"followedAchievementsDialog\"\r\n    end\r\n\r\n    if (dialogName == \"\") then\r\n        return\r\n    end\r\n\r\n    local screenH, screenW = UI.getWindowSize()\r\n    local x, y = UI.getPosition(dialogName)\r\n\r\n    UI.setPosition(dialogName, x, screenH / 4)\r\n    UI.setWindowMovable(dialogName, movable)\r\nend\r\n\r\n-- FONCTION UI -- Rend Visible/Invisible certains éléments des interfaces\r\nfunction prepareUI(visible)\r\n  --Interface Boutique & Cadeau\r\n  setWidgetVisible(\"topHudDialog\", \"optionShopButton\", visible)\r\n  setWidgetVisible(\"topHudDialog\", \"giftButton\", visible)\r\n\r\n  --UI sous le Coeur\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"wakfuStasisBar\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"xpBar\", visible)\r\n\r\n  --Boutons hors combat à droite du Coeur\r\n  setWidgetVisible(\"shortcutBarDialog\", \"previousButton\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"nextButton\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseShortcutBar1\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseShortcutBar2\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseShortcutBar3\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseShortcutBar4\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"shortcutBarItemButton\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"shortcutBarSpellButton\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseButtonContainerForTuto1\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseButtonContainerForTuto2\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseButtonContainerForTuto3\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseButtonContainerForTuto4\", visible)\r\n\r\n  --Boutons hors combat à gauche de l'écran - barre d'interfaces\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"firstInterfaceBarBackground\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"secondInterfaceBarBackground\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"extraInterfaceBarDrawerButton\", visible)\r\n\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"fightInfoBtn\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"inventoryButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"buildSheetSetButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"craftButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"questsButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"dungeonButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"cosmeticsButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"tutorialBookButton\", visible)\r\n\r\n  --Boutons hors combat à gauche de l'écran - barre d'interfaces (deuxième barre)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"contactListButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"guildButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"companionsButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"nationButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"battlegroundButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"passportButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"emoteButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"encyclopediaButton\", visible)\r\n\r\n  --Boutons hors combat \"actions rapides\"\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"OverWorldActionsBackground\", visible)\r\n\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"dimensionalBagButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"mapButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"rideMountButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"miniMapButton\", visible)\r\n\r\n  --Boutons en combat à gauche du Coeur\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"FightActionsBackground\", visible)\r\n\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"giveUpButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"hideFightersButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"tacticalModeBtn\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"reportCellBtn\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"fightMarkerBtn\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"lockFightBtn\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"resistanceOverheadBtn\", visible)\r\nend\r\n\r\n-- FONCTION SHORTCUT -- Rend Actif/Inactif certains raccourcis\r\nfunction prepareShortcuts(enabled, shortcutType)\r\n  if not shortcutType or shortcutType == \"WORLD\" then\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.world\", \"enterLeaveBag\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.world\", \"switchHero0\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.world\", \"switchHero1\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.world\", \"switchHero2\")\r\n  end\r\n  if not shortcutType or shortcutType == \"DISPLAY\" then\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"zoomIn\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"zoomOut\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"closeWindows\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"setLODLevel\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"setFightLODLevel\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"showHideNameOverheadsCommand\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"hideFightOccluders\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"alphaMask\")\r\n  end\r\n  if not shortcutType or shortcutType == \"CHAT\" then\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.chat\", \"chat\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.chat\", \"lastContact\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.chat\", \"firstContact\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.chat\", \"autoCompletePlayerName\")\r\n    for bind=1, 9, 1 do\r\n      UI.setShortcutEnabled(enabled, \"shortcutCategory.shortcutBar\", \"bind\" .. toString(bind))\r\n    end\r\n  end\r\n\r\n  if not shortcutType or shortcutType == \"FIGHT\" then\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"fighterTransparency\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"switchTacticalView\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"nextSelectedFighter\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"giveUp\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"lockFight\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"reportCell\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"callHelp\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"displayHpBar\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"resetFightCamera\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"endPlacementAndTurn\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"closeCombatRight\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"closeCombatLeft\")\r\n  end\r\n  if not shortcutType or shortcutType == \"INTERFACE\" then\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"minimap\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"contactList\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"companionManagement\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"guild\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"craft\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"dungeonList\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"achievements\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"quests\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"emotes\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"ecosystem\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"climate\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"nation\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"partySearch\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"passport\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"almanax\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"tutorialBook\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"switchToDirectAttackCommand\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"map\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"spellsInventory\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"inventory\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"characterBook\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"osamodasSymbiot\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"shortcutBar0\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"shortcutBar1\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"shortcutBar2\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"shortcutBar3\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"additionalShortcutBar0\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"additionalShortcutBar1\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"additionalShortcutBar2\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"additionalShortcutBar3\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"changeShortcutBarType\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"downscaling\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"rewards\")\r\n\tUI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"battlegroundList\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"aptitudes\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"presets\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"encyclopedia\")\r\n  end\r\n\r\n  -- On ne bloque pas les raccourcis de sorts finalement\r\n--   if not shortcutType or shortcutType == \"SHORTCUTBAR\" then\r\n--     for bar=0,3, 1 do\r\n--       for slot=0, 9, 1 do\r\n--         UI.setShortcutEnabled(enabled, \"shortcutCategory.shortcutBar\", \"shortcut\" .. toString(bar) .. toString(slot))\r\n--       end\r\n--     end\r\n--   end\r\nend\r\n\r\n-- FONCTION UI -- Rend Visible/Invisible un élément d'une interface\r\nfunction setWidgetVisible(dialogName, widgetName, visible)\r\n  if not UI.isDialogLoaded(dialogName) then return end\r\n\r\n  UI.setWidgetVisibility(dialogName, widgetName, visible)\r\n  table.insert(widget_visible, { name = dialogName, id = widgetName, state = visible })\r\nend\r\n\r\nfunction clearWidgetVisible()\r\n  local str = \"\"\r\n  for i=#widget_visible, 1, -1 do\r\n    str = str .. toString(widget_visible[i].name) .. \"@\" .. toString(widget_visible[i].id) .. \";\"\r\n    UI.setWidgetVisibility(widget_visible[i].name, widget_visible[i].id, true)\r\n  end\r\n\r\n  widget_visible = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearWidgetVisible\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Rend Actif/Inactif un élément d'une interface\r\nfunction setWidgetEnable(dialogName, widgetName, enable)\r\n  if not UI.isDialogLoaded(dialogName) then return end\r\n\r\n  UI.setWidgetEnabled(dialogName, widgetName, enable)\r\n  table.insert(widget_enable, {name = dialogName, id = widgetName, state = enable})\r\nend\r\n\r\nfunction clearWidgetEnable()\r\n  local str = \"\"\r\n  for i=#widget_enable, 1, -1 do\r\n    str = str .. toString(widget_enable[i].name) .. \"@\" .. toString(widget_enable[i].id) .. \";\"\r\n    UI.setWidgetEnabled(widget_enable[i].name, widget_enable[i].id, true)\r\n  end\r\n\r\n  widget_enable = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearWidgetEnable\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Ajoute/Retire une TweenParticle à un élément d'une interface\r\nfunction setUIColorTween(dialogName, widgetName, duration, loop, r1, g1, b1, a1, r2, g2, b2, a2)\r\n  if not UI.isDialogLoaded(dialogName) then return end\r\n\r\n  UI.addColorTween(dialogName, widgetName, duration, loop, r1, g1, b1, a1, r2, g2, b2, a2)\r\n  table.insert(ui_tweens, {name = dialogName, id = widgetName})\r\nend\r\n\r\nfunction clearUIColorTweens(dialogName, widgetName)\r\n  local str = \"\"\r\n  for i=#ui_tweens, 1, -1 do\r\n    if ((not dialogName) or (dialogName == ui_tweens[i].name)) and ((not widgetName) or (widgetName == ui_tweens[i].id)) then\r\n      str = str .. toString(ui_tweens[i].name) .. \"@\" .. toString(ui_tweens[i].id) .. \";\"\r\n      UI.removeColorTween(ui_tweens[i].name, ui_tweens[i].id)\r\n      table.remove(ui_tweens, i)\r\n    end\r\n  end\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearUIColorTweens\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Ajoute/Retire une Particle à un élément d'une interface\r\nfunction setUIParticle(dialogName, widgetName, apsFileName, x, y, alignment, level)\r\n  if not UI.isDialogLoaded(dialogName) then return end\r\n\r\n  local particleId = UI.addParticle(dialogName, widgetName, apsFileName, x, y, alignment, level)\r\n  table.insert(ui_particles, {name = dialogName, id = widgetName})\r\n\r\n  return particleId\r\nend\r\n\r\nfunction setUIParticleBorder(dialogName, widgetName, apsFileName, x, y, alignment, level, speed)\r\n  if not UI.isDialogLoaded(dialogName) then return end\r\n\r\n  local particleId = UI.addParticleToBorder(dialogName, widgetName, apsFileName, x, y, alignment, level, speed)\r\n  table.insert(ui_particles, {name = dialogName, id = widgetName})\r\n\r\n  return particleId\r\nend\r\n\r\nfunction clearUIParticles(dialogName, widgetName)\r\n  local str = \"\"\r\n  for i=#ui_particles, 1, -1 do\r\n    if ((not dialogName) or (dialogName == ui_particles[i].name)) and ((not widgetName) or (widgetName == ui_particles[i].id)) then\r\n      str = str .. toString(ui_particles[i].name) .. \"@\" .. toString(ui_particles[i].id) .. \";\"\r\n      UI.clearParticles(ui_particles[i].name, ui_particles[i].id)\r\n      table.remove(ui_particles, i)\r\n    end\r\n  end\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearUIParticles\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Enregistre/Supprime un callback à l'ouverture d'une interface\r\nfunction addDialogLoadListener(dialog, funcName, ...)\r\n  UI.addDialogLoadedListener(dialog, funcName, unpack(arg))\r\n  table.insert(ui_listener_load,  dialog)\r\nend\r\n\r\nfunction clearDialogLoadListener(dialogName)\r\n  local str = \"\"\r\n  for i=#ui_listener_load, 1, -1 do\r\n    if (not dialogName) or (dialogName == ui_listener_load[i]) then\r\n      str = str .. toString(ui_listener_load[i]) .. \";\"\r\n      UI.removeDialogLoadedListener(ui_listener_load[i])\r\n      table.remove(ui_listener_load, i)\r\n    end\r\n  end\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearDialogLoadListener\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Enregistre/Supprime un callback à la fermeture d'une interface\r\nfunction addDialogUnloadListener(dialog, funcName, ...)\r\n  UI.addDialogUnloadedListener(dialog, funcName, unpack(arg))\r\n  table.insert(ui_listener_unload, dialog)\r\nend\r\n\r\nfunction clearDialogUnloadListener(dialogName)\r\n  local str = \"\"\r\n  for i=#ui_listener_unload, 1, -1 do\r\n    if (not dialogName) or (dialogName == ui_listener_unload[i]) then\r\n      str = str .. toString(ui_listener_unload[i]) .. \";\"\r\n      UI.removeDialogUnloadedListener(ui_listener_unload[i])\r\n      table.remove(ui_listener_unload, i)\r\n    end\r\n  end\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearDialogUnloadListener\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Enregistre/Supprime un callback sur un élément d'une interface\r\nfunction addDialogEventListener(dialog, id, eventType, funcName, ...)\r\n  if not UI.isDialogLoaded(dialog) then return end\r\n\r\n  UI.addEventListener(dialog, id, eventType, funcName, unpack(arg))\r\n  table.insert(ui_listener_event, {dialog=dialog, id=id, eventType=eventType, funcName=funcName})\r\nend\r\n\r\nfunction clearDialogEventListener(dialogName)\r\n  local str = \"\"\r\n  for i=#ui_listener_event, 1, -1 do\r\n    if (not dialogName) or (dialogName == ui_listener_event[i].dialog) then\r\n      str = str .. toString(ui_listener_event[i].dialog) .. \"@\" .. toString(ui_listener_event[i].id) .. \";\"\r\n      UI.removeEventListener(ui_listener_event[i].dialog, ui_listener_event[i].id, ui_listener_event[i].eventType, ui_listener_event[i].funcName)\r\n      table.remove(ui_listener_event, i)\r\n    end\r\n  end\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearDialogEventListener\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y , z, ...)\r\n  local particleId = Particle.addParticleSystem(particleFileId, x, y , z, unpack(arg))\r\n  table.insert(world_particles, particleId)\r\n\r\n  return particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n  local particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n  table.insert(world_particles, particleId)\r\n\r\n  return particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n  local str = \"\"\r\n  for i=#world_particles, 1, -1 do\r\n    str = str .. toString(world_particles[i]) .. \";\"\r\n    Particle.removeParticleSystem(world_particles[i])\r\n  end\r\n\r\n  world_particles = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n  BubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n  if isLower(mobileId, 0) then\r\n    BubbleText.setCharacterSpeak(mobileId, text)\r\n  else\r\n    if (not offsetY) then\r\n      local height = Mobile.getMobileHeight(mobileId)\r\n      if (not height) then height = 6 end\r\n\r\n      offsetY = height * 10\r\n    end\r\n\r\n    if (not offsetX) then offsetX = 0 end\r\n    if (not infiniteDuration) then infiniteDuration = false end\r\n\r\n    BubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n    UI.writeLocalisedInChat(text)\r\n  end\r\n\r\n  if (not tContains(bubbles, mobileId)) then\r\n    table.insert(bubbles, mobileId)\r\n  end\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n  local str = \"\"\r\n  for i = #bubbles, 1, -1 do\r\n    if (not mobileId) then\r\n      str = str .. toString(bubbles[i]) .. \";\"\r\n      BubbleText.closeBubbleAttachedTo(bubbles[i])\r\n    elseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n      str = str .. toString(bubbles[i]) .. \";\"\r\n      BubbleText.closeBubbleAttachedTo(bubbles[i])\r\n      table.remove(bubbles, i)\r\n    end\r\n  end\r\n\r\n  if (not mobileId) then bubbles = {} end\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n  local compassId = UI.addCompass(\"compass\", x, y, z)\r\n  table.insert(compasses, compassId)\r\n\r\n  return compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n  local str = \"\"\r\n  for i=#compasses, 1, -1 do\r\n    str = str .. toString(compasses[i]) .. \";\"\r\n    UI.removeCompass(compasses[i])\r\n  end\r\n\r\n  compasses = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height)\r\n  local mobileId = Mobile.generateClientMobileId()\r\n  Actor.createActor(mobileId, spriteName, worldX, worldY, worldZ, availableDirection)\r\n\r\n  if (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n  if (height) then Actor.setActorHeight(mobileId, height) end\r\n\r\n  table.insert(actors, mobileId)\r\n\r\n  return mobileId\r\nend\r\n\r\nfunction clearActors()\r\n  local str = \"\"\r\n  for i = #actors, 1, -1 do\r\n    str = str .. toString(actors[i]) .. \";\"\r\n    Actor.deleteActor(actors[i])\r\n  end\r\n\r\n  actors = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n  local taskId = invoke(delay, count, funcName, unpack(arg))\r\n  table.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n  local str = \"\"\r\n  for i=#invoke_tasks, 1, -1 do\r\n    str = str .. toString(invoke_tasks[i]) .. \";\"\r\n    interrupt(invoke_tasks[i])\r\n    desinvoke(invoke_tasks[i])\r\n  end\r\n\r\n  invoke_tasks = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n  invoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n  local taskId = setInterval(delay, funcName, unpack(arg))\r\n  table.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n  local str = \"\"\r\n  for i=#interval_tasks, 1, -1 do\r\n    str = str .. toString(interval_tasks[i]) .. \";\"\r\n    interrupt(interval_tasks[i])\r\n    desinvoke(interval_tasks[i])\r\n  end\r\n\r\n  interval_tasks = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n  if (_DEBUG) then trace(\"startCinematicContext\") end\r\n\r\n  UI.manageFrame(\"World\", false)\r\n  UI.closeMRU()\r\n  UI.closeAllBags()\r\n  UI.setUIVisible(false)\r\n  UI.displayWideScreenBand(true)\r\n  Camera.setUserZoomLocked(true)\r\n\r\n  if (cameraMobileId ~= nil)  then\r\n    Camera.setMoveSpeedFactor(10000)\r\n    Camera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n  end\r\n\r\n  if (zoomFactor ~= nil)  then\r\n    Camera.setZoomFactor(zoomFactor)\r\n  end\r\n\r\n  if (musicId ~= nil)  then\r\n    Sound.playForcedMusic(musicId)\r\n  end\r\n\r\n  if (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\nfunction skipCinematic()\r\n  local player = Context.getLeaderId()\r\n\r\n  for x = 1, #_ACTOR_LIST do\r\n    Actor.deleteActor(_ACTOR_LIST[x])\r\n  end\r\n\r\n  UI.hideButton()\r\n  clearALL()\r\n  stopCinematicContext(1, player, true)\r\n  Mobile.setMobileVisible(player, true)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n  if (_DEBUG) then trace(\"stopCinematicContext\") end\r\n\r\n  UI.displayWideScreenBand(false)\r\n  UI.setUIVisible(true)\r\n  Camera.setUserZoomLocked(false)\r\n  UI.manageFrame(\"World\", true)\r\n\r\n  Camera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n  Camera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n  if (zoomFactor ~= nil) then\r\n    Camera.setZoomFactor(zoomFactor)\r\n  end\r\n\r\n  if (cameraMobileId ~= nil) then\r\n    Camera.attachCameraToMobile(cameraMobileId)\r\n  end\r\n\r\n  if (stopMusic) then\r\n    Sound.stopForcedMusic()\r\n  end\r\n\r\n  if (_DEBUG) then\r\n    UI.hideButton()\r\n  end\r\n\r\n  --TRIGGER\r\n  Server.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Affiche/Masque une texture à l'écran\r\nfunction displayScreenEffect(enable, fadeInDur, alphaDur, fadeOutDur, r, g, b, alpha)\r\n  if (_DEBUG) then trace(\"displayScreenEffect\") end\r\n\r\n  if not enable and screenEffectId ~= nil  then\r\n    --On retire le blackScreen\r\n    Effect.stopEffect(screenEffectId)\r\n  else\r\n    --On affiche un blackScreen à l'entrée dans l'instance le temps qu'elle soit complètement chargée\r\n    screenEffectId = Effect.createFullScreenSprite(fadeInDur, alphaDur, fadeOutDur, r, g, b, alpha)\r\n  end\r\nend\r\n\r\n-- FONCTION NETTOYAGE --\r\nfunction clearALL()\r\n  clearIntervalTasks()\r\n  clearInvokeTasks()\r\n  clearBubbles()\r\n  clearUIColorTweens()\r\n  clearUIParticles()\r\n  clearWorldParticles()\r\n  clearCompasses()\r\n  clearActors()\r\n\r\n  Focus.display(false)\r\n  UI.unloadTutorialDialog()\r\nend\r\n\r\n-- FONCTION NETTOYAGE --\r\nfunction clearUI(dialogName)\r\n  clearUIColorTweens(dialogName)\r\n  clearUIParticles(dialogName)\r\nend\r\n\r\n-- FONCTION NETTOYAGE --\r\nfunction clearListener(dialogName)\r\n  clearDialogLoadListener(dialogName)\r\n  clearDialogUnloadListener(dialogName)\r\n  clearDialogEventListener(dialogName)\r\nend\r\n  \r\n-- Fonctions cache / montre CM\r\nfunction hideMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, false)\r\nend\r\n\r\nfunction showMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, true)\r\nend\r\n\r\n-- Fonction score\r\nbubbleFightInfoId = 0\r\n\r\nfunction onFightInfoClosed()\r\n\tif (bubbleFightInfoId ~= nil  and bubbleFightInfoId ~= 0) then bubbleFightInfoId = 0 end\r\nend\r\n\r\nfunction updateFightInfo(teamDamage, forceDisplayUI)\r\n\tlocal teamDamage = toLong(teamDamage)\r\n \r\n\tif (bubbleFightInfoId == 0) then\r\n\t\tbubbleFightInfoId = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_WEST\", 0, -60, false, 2147483647, true, \"interactiveBubbleDialog5\", 30000, 25000, \"onFightInfoClosed\")\r\n\tend\r\n\r\n\tBubbleText.setText(bubbleFightInfoId, \"japan.expo.fight.player.infos\", teamDamage)\r\n\t\r\n\tif (forceDisplayUI) then BubbleText.show(bubbleFightInfoId) end\r\nend\n\n-- Variables globales\n-- \nfunction event_2717_24144()\n    \nend\n\n-- ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2717_24145(doorOpened, bossId)\n    local doorOpened = toLong(doorOpened)\r\n    local bossId = toLong(bossId)\r\n    \r\n    if (doorOpened == 1) then\r\n    else hideMonster(bossId)\r\n    end\nend\n\n-- MONSTER_ACTION - Le joueur attaque Cire Momore - Lancement du Combat\n-- \nfunction event_2717_24146()\n    \nend\n\n-- FIGHT_STARTED - Initialisation des variables\n-- \nfunction event_2717_24147()\n    \nend\n\n-- FIGHT_ENTER_ACTION_PHASE - Application états\n-- \nfunction event_2717_24200(turnLeft, teamDamage)\n    updateFightInfo(turnLeft, teamDamage, true)\nend\n\n-- EFFECT_EXECUTION - Mise à jour UI infos de combat (score)\n-- \nfunction event_2717_24148(teamDamage)\n    updateFightInfo(teamDamage, true)\nend\n\n-- INTERACTIVE_ELEMENT_ACTIVATION - Ouverture de la porte\n-- \nfunction event_2717_24149(bossId)\n    local playerId = Context.getLeaderId()\r\n    local bossId = toLong(bossId)\r\n    \r\n    startCinematicContext(1.0, bossId)\r\n    \r\n    invoke_custom(0999, 1, \"Mobile.addMobileCreationCallback\", bossId, \"showMonster\", bossId)\r\n    invoke_custom(0950, 1, \"Mobile.setMobileAnimation\", bossId, \"AnimApparition\")\r\n    invoke_custom(1000, 1, \"Effect.createCameraShakeEffect\", 100, 500, 100, 5, 100, \"BOTH\")\r\n    invoke_custom(3400, 1, \"Camera.attachCameraToMobile\", playerId)\r\n    \r\n    invoke_custom(3400, 1, \"skipCinematic\")\nend\n\n-- FIGHT_ENDED_IN_CLIENT_EVENT - On affiche le score\n-- \nfunction event_2717_24150(teamDamage)\n    local teamDamage = toString(teamDamage)\r\n    \r\n    UI.setWidgetEnabled(\"fightResultDialog\", \"rootContainer\", true)\r\n    UI.setWidgetVisibility(\"fightResultDialog\", \"rootContainer\", true)\r\n    \r\n    local text = Event.getKeyTranslation(\"fight.score.ogrest\", teamDamage)\r\n    UI.setPropertyStringValue(\"fight.score.ogrest\", text)\r\n    UI.writeLocalisedInChat(\"ogrest.fight.team.score\", teamDamage)\r\n    \r\n    UI.removeUnremovableDialog(\"fightResultDialog\")\r\n    \r\n    UI.addDialogUnloadedListener(\"fightResultDialog\", \"UI.removeProperty\", \"fight.score.ogrest\")\nend\n\n-- USER_GROUP_KILLED - Enregistrement au classement\n-- \nfunction event_2717_24202()\n    \nend\n\n","functions":["tContains","prepareChatUI","prepareFollowQuestUI","prepareUI","prepareShortcuts","setWidgetVisible","clearWidgetVisible","setWidgetEnable","clearWidgetEnable","setUIColorTween","clearUIColorTweens","setUIParticle","setUIParticleBorder","clearUIParticles","addDialogLoadListener","clearDialogLoadListener","addDialogUnloadListener","clearDialogUnloadListener","addDialogEventListener","clearDialogEventListener","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","bubble","clearBubbles","setCompass","clearCompasses","createActor","clearActors","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","startCinematicContext","skipCinematic","stopCinematicContext","displayScreenEffect","clearALL","clearUI","clearListener","hideMonster","showMonster","onFightInfoClosed","updateFightInfo","event_2717_24144","event_2717_24145","event_2717_24146","event_2717_24147","event_2717_24200","event_2717_24148","event_2717_24149","event_2717_24150","event_2717_24202"],"quest_calls":[],"dialogue_calls":[]},"scenario/2718.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n  \r\n-- Fonctions cache / montre CM\r\nfunction hideMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, false)\r\nend\r\n\r\nfunction showMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, true)\r\nend\r\n\r\nbubbleFightInfoId = 0\r\n\r\nfunction closeFightInfo()\r\n\tif (bubbleFightInfoId ~= nil and bubbleFightInfoId ~= 0) then BubbleText.close(bubbleFightInfoId) end\r\nend\r\n\r\nfunction onFightInfoClosed()\r\n\tif (bubbleFightInfoId ~= nil and bubbleFightInfoId ~= 0) then bubbleFightInfoId = 0 end\r\nend\r\n\r\nfunction updateFightInfo(wave, difficulty, teamDamage, forceDisplayUI)\r\n\tlocal wave = toLong(wave)\r\n\tlocal difficulty = toLong(difficulty) - 2\r\n\tlocal teamDamage = toLong(teamDamage)\r\n\r\n\tif (bubbleFightInfoId == 0) then\r\n\t\tbubbleFightInfoId = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_WEST\", 0, -60, false, 2147483647, true, \"interactiveBubbleDialog5\", 30000, 25000, \"onFightInfoClosed\")\r\n\tend\r\n\r\n\tBubbleText.setText(bubbleFightInfoId, \"japan.expo.2023.wave.info\", wave, difficulty, teamDamage)\r\n\r\n\tif (forceDisplayUI) then BubbleText.show(bubbleFightInfoId) end\r\nend\n\n-- [INIT] Variables globales\n-- \nfunction event_2718_24151()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2718_24152(rushuQuest)\n    local playerId = Context.getLeaderId()\r\n    local remingtonId = createActor(197902018, -40, 8, -4, 8, 5)\r\n    local goultardId = createActor(192404688, -40, 6, -4, 8, 5)\r\n    local bossId = createActor(1108305306, -54, 8, 58, 8, 1, 26)\r\n    local rushuQuest = toLong(rushuQuest)\r\n    \r\n    Mobile.setMobileAnimation(bossId, \"AnimComp-1\")\r\n    Mobile.setMobileVisible(remingtonId, false)\r\n    Mobile.setMobileVisible(rushuQuest, false)\r\n    Mobile.setMobileVisible(playerId, false)\r\n    \r\n    startCinematicContext(1.2, playerId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 24152)\r\n    \r\n    invoke_custom(00010, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimSort-Bond-Fin\")\r\n    invoke_custom(01000, 1, \"Camera.setCamera\", 1, -54, 8, 58)\r\n    \r\n    -- \"GOULTARD...\"\r\n    invoke_custom(01000, 1, \"Sound.playSound\", 90000082, true, 40)\r\n    invoke_custom(01000, 1, \"bubble\", bossId, \"japanexpo.2023.01\")\r\n    invoke_custom(03000, 1, \"clearBubbles\", bossId)\r\n    \r\n    -- \"TU ES VENU JUSQUE DANS MON PALAIS ?\"\r\n    invoke_custom(03500, 1, \"Sound.playSound\", 90000085, true, 40)\r\n    invoke_custom(03500, 1, \"bubble\", bossId, \"japanexpo.2023.02\")\r\n    invoke_custom(06300, 1, \"Mobile.setMobileAnimation\", bossId, \"AnimComp-2\")\r\n    invoke_custom(06500, 1, \"clearBubbles\", bossId)\r\n    invoke_custom(06500, 1, \"Camera.setCamera\", 1, -49, 7, -4)\r\n    \r\n    invoke_custom(06999, 1, \"Mobile.setMobilePosition\", bossId, -49, 7, -4)\r\n    invoke_custom(07000, 1, \"Mobile.setMobileAnimation\", bossId, \"AnimSort-Bond-Fin\")\r\n    invoke_custom(07100, 1, \"Particle.addParticleSystem\", -1453072821, -49, 7, -4)\r\n    invoke_custom(07000, 1, \"Effect.createCameraShakeEffect\", 100, 500, 100, 5, 100, \"BOTH\")\r\n    \r\n    -- \"MES SHUSHUS VONT T'ÉCRABOUILLER, MINABLE !\"\r\n    invoke_custom(07500, 1, \"Sound.playSound\", 90000083, true, 40)\r\n    invoke_custom(07500, 1, \"bubble\", bossId, \"japanexpo.2023.03\")\r\n    invoke_custom(08000, 1, \"Mobile.setMobileAnimation\", bossId, \"AnimComp-4\")\r\n    invoke_custom(11000, 1, \"clearBubbles\", bossId)\r\n    \r\n    -- \"VOYONS COMBIEN DE TEMPS TU POURRAS TENIR...\"\r\n    invoke_custom(11500, 1, \"Sound.playSound\", 90000083, true, 40)\r\n    invoke_custom(11500, 1, \"bubble\", bossId, \"japanexpo.2023.04\")\r\n    invoke_custom(12000, 1, \"Mobile.setMobileAnimation\", bossId, \"AnimComp-3\")\r\n    invoke_custom(15500, 1, \"clearBubbles\", bossId)\r\n    invoke_custom(16000, 1, \"Camera.setCamera\", 1.3, -41, 7, -4)\r\n    \r\n    -- \"Quand tu veux, gros nigaud ! Voyons combien de temps tu tiendras contre nous !\"\r\n    invoke_custom(16500, 1, \"bubble\", goultardId, \"japanexpo.2024.02\")\r\n    invoke_custom(17500, 1, \"Mobile.setMobileVisible\", remingtonId, true)\r\n    invoke_custom(17500, 1, \"Mobile.setMobileAnimation\", remingtonId, \"AnimSort-TP-Fin\")\r\n    invoke_custom(20000, 1, \"clearBubbles\", goultardId)\r\n    \r\n    invoke_custom(20001, 1, \"skipCinematic\", 24152)\nend\n\n-- [EVENT] CLIENT_TRIGGERED_EVENT - Lancement du combat\n-- \nfunction event_2718_24153()\n    trace(\"LANCEMENT DU COMBAT\")\nend\n\n-- [EVENT] FIGHT_ENTER_ACTION_PHASE - Application états\n-- \nfunction event_2718_24154(wave, difficulty, teamDamage)\n    updateFightInfo(wave, difficulty, teamDamage, true)\nend\n\n-- [EVENT] NEW_MONSTER_WAVE - Difficulté\n-- \nfunction event_2718_24155(wave, difficulty, teamDamage)\n    updateFightInfo(wave, difficulty, teamDamage, true)\nend\n\n-- [EVENT] FIGHT_ENDED_IN_CLIENT - On ferme l'affichage\n-- \nfunction event_2718_24156(wave, difficulty, teamDamage, fightWon)\n    local wave = toLong(wave)\r\n    local teamDamage = toLong(teamDamage)\r\n    \r\n    if (toLong(fightWon) == 1) then\r\n    \tUI.writeLocalisedInChat(\"japan.expo.2024.fight.mode.ultimate.won\", wave)\r\n    \tUI.writeLocalisedInChat(\"japan.expo.2023.fight.final.score.wave\", wave)\r\n    \tUI.writeLocalisedInChat(\"japan.expo.2023.fight.final.score.damage\", teamDamage)\r\n    end\r\n    \r\n    closeFightInfo()\nend\n\n-- EFFECT_EXECUTION - Le joueur a gagné le combat\n-- \nfunction event_2718_24157()\n    \nend\n\n-- EFFECT_EXECUTION - Mise à jour UI infos de combat (score)\n-- \nfunction event_2718_24158(wave, difficulty, teamDamage)\n    updateFightInfo(wave, difficulty, teamDamage, true)\nend\n\n-- PLAYER_WON_FIGHT - Enregistrement au classement\n-- \nfunction event_2718_24203()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","hideMonster","showMonster","closeFightInfo","onFightInfoClosed","updateFightInfo","event_2718_24151","event_2718_24152","event_2718_24153","event_2718_24154","event_2718_24155","event_2718_24156","event_2718_24157","event_2718_24158","event_2718_24203"],"quest_calls":[],"dialogue_calls":[]},"scenario/2719.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n  \r\n-- Fonctions cache / montre CM\r\nfunction hideMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, false)\r\nend\r\n\r\nfunction showMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, true)\r\nend\r\n\r\nbubbleFightInfoId = 0\r\n\r\nfunction closeFightInfo()\r\n\tif (bubbleFightInfoId ~= nil and bubbleFightInfoId ~= 0) then BubbleText.close(bubbleFightInfoId) end\r\nend\r\n\r\nfunction onFightInfoClosed()\r\n\tif (bubbleFightInfoId ~= nil and bubbleFightInfoId ~= 0) then bubbleFightInfoId = 0 end\r\nend\r\n\r\nfunction updateFightInfo(wave, difficulty, teamDamage, forceDisplayUI)\r\n\tlocal wave = toLong(wave)\r\n\tlocal difficulty = toLong(difficulty)\r\n\tlocal teamDamage = toLong(teamDamage)\r\n\r\n\tif (bubbleFightInfoId == 0) then\r\n\t\tbubbleFightInfoId = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_WEST\", 0, -60, false, 2147483647, true, \"interactiveBubbleDialog5\", 30000, 25000, \"onFightInfoClosed\")\r\n\tend\r\n\r\n\tBubbleText.setText(bubbleFightInfoId, \"japan.expo.2024.wave.info\", wave, difficulty, teamDamage)\r\n\r\n\tif (forceDisplayUI) then BubbleText.show(bubbleFightInfoId) end\r\nend\n\n-- [INIT] Variables globales\n-- \nfunction event_2719_24159()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2719_24160()\n    function customSkip()\r\n    \tskipCinematic(22838)\r\n    end\r\n    \r\n    local playerId = Context.getLeaderId()\r\n    local torossId = createActor(1113105589, -17, 1, 8, 4, 1, 15)\r\n    local fakeTorossId = createActor(119405596, -18, 1, 11, 4, 1, 8)\r\n    \r\n    Mobile.setMobileAnimation(torossId, \"AnimAssis-Statique\")\r\n    \r\n    startCinematicContext(1.0, playerId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"customSkip\")\r\n    \r\n    invoke_custom(00010, 1, \"Camera.setZoomSpeedFactor\", 10000)\r\n    invoke_custom(00010, 1, \"Camera.setZoomFactor\", 1.0)\r\n    invoke_custom(00010, 1, \"Camera.attachCameraToMobile\", torossId)\r\n    \r\n    invoke_custom(01000, 1, \"Camera.setZoomSpeedFactor\", 0.02)\r\n    invoke_custom(01000, 1, \"Camera.setZoomFactor\", 1.5)\r\n    \r\n    -- \"En pénétrant dans mon palais, tu viens de t'assurer une fin tragique.\"\r\n    invoke_custom(01500, 1, \"bubble\", fakeTorossId, \"toross.fight.start.dialog.07\")\r\n    invoke_custom(04500, 1, \"Mobile.setMobileAnimation\", torossId, \"AnimSeLeve\")\r\n    invoke_custom(07000, 1, \"clearBubbles\", fakeTorossId)\r\n    \r\n    invoke_custom(08000, 1, \"Mobile.setMobileAnimation\", torossId, \"AnimSort-3-Debut\")\r\n    invoke_custom(08000, 1, \"Particle.addParticleSystem\", -1113181740, -17, 1, 8)\r\n    invoke_custom(08780, 1, \"Mobile.setMobileVisible\", torossId, false)\r\n    \r\n    invoke_custom(09500, 1, \"Mobile.setMobilePosition\", torossId, -12, 1, 0)\r\n    invoke_custom(09500, 1, \"Mobile.setMobileVisible\", torossId, true)\r\n    invoke_custom(09500, 1, \"Mobile.setMobileAnimation\", torossId, \"AnimSort-3-Fin\")\r\n    invoke_custom(09500, 1, \"Particle.addParticleSystem\", -1113181741, -12, 1, 0)\r\n    \r\n    invoke_custom(10600, 1, \"Mobile.setMobileAnimation\", torossId, \"AnimSort-4\")\r\n    invoke_custom(10600, 1, \"Particle.addParticleSystem\", -1113181650, -12, 1, 0)\r\n    \r\n    -- \"Je vais te montrer ce qu'il en coûte de se frotter à moi. Approche !\"\r\n    invoke_custom(10600, 1, \"bubble\", torossId, \"toross.fight.start.dialog.08\")\r\n    invoke_custom(15500, 1, \"clearBubbles\", torossId)\r\n    \r\n    invoke_custom(16000, 1, \"Camera.attachCameraToMobile\", playerId)\r\n    \r\n    invoke_custom(16500, 1, \"customSkip\")\nend\n\n-- [EVENT] CLIENT_TRIGGERED_EVENT - Lancement du combat\n-- \nfunction event_2719_24161()\n    trace(\"LANCEMENT DU COMBAT\")\nend\n\n-- [EVENT] FIGHT_ENTER_ACTION_PHASE - Application états\n-- \nfunction event_2719_24162(wave, difficulty, teamDamage)\n    updateFightInfo(wave, difficulty, teamDamage, true)\nend\n\n-- [EVENT] NEW_MONSTER_WAVE - Difficulté\n-- \nfunction event_2719_24163(wave, difficulty, teamDamage)\n    updateFightInfo(wave, difficulty, teamDamage, true)\nend\n\n-- [EVENT] FIGHT_ENDED_IN_CLIENT - On ferme l'affichage\n-- \nfunction event_2719_24164(wave, difficulty, teamDamage, fightWon)\n    local wave = toLong(wave)\r\n    local teamDamage = toLong(teamDamage)\r\n    \r\n    if (toLong(fightWon) == 1) then\r\n    \tUI.writeLocalisedInChat(\"japan.expo.2024.fight.mode.normal.won\", wave)\r\n    \tUI.writeLocalisedInChat(\"japan.expo.2024.fight.final.score.wave\", wave)\r\n    \tUI.writeLocalisedInChat(\"japan.expo.2024.fight.final.score.damage\", teamDamage)\r\n    end\r\n    \r\n    closeFightInfo()\nend\n\n-- EFFECT_EXECUTION - Le joueur a gagné le combat\n-- \nfunction event_2719_24165()\n    \nend\n\n-- EFFECT_EXECUTION - Mise à jour UI infos de combat (score)\n-- \nfunction event_2719_24166(wave, difficulty, teamDamage)\n    updateFightInfo(wave, difficulty, teamDamage, true)\nend\n\n-- PLAYER_WON_FIGHT - Enregistrement au classement\n-- \nfunction event_2719_24204()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","hideMonster","showMonster","closeFightInfo","onFightInfoClosed","updateFightInfo","event_2719_24159","event_2719_24160","customSkip","event_2719_24161","event_2719_24162","event_2719_24163","event_2719_24164","event_2719_24165","event_2719_24166","event_2719_24204"],"quest_calls":[],"dialogue_calls":[]},"scenario/2720.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\nbubbleFightInfoId = 0\r\n\r\nfunction createActorWithDefaultParams(mobileId, x, y, z, defaultDirection, availableDirection)\r\n    return createActor(Mobile.getMobileGFX(mobileId) or mobileId, x, y, z, availableDirection or 4, defaultDirection or 1, Mobile.getMobileHeight(mobileId))\r\nend\r\n\r\nfunction onFightInfoClosed()\r\n    if bubbleFightInfoId and bubbleFightInfoId ~= 0 then\r\n        bubbleFightInfoId = 0\r\n    end\r\nend\r\n\r\nfunction updateFightInfo(turnsRemaining, teamDamage, noxDamage, harebourgDamage)\r\n    local turnsRemaining = toLong(turnsRemaining)\r\n    local teamDamage = toLong(teamDamage)\r\n    local noxDamage = toLong(noxDamage)\r\n    local harebourgDamage = toLong(harebourgDamage)\r\n\r\n    if not bubbleFightInfoId or bubbleFightInfoId == 0 then\r\n        bubbleFightInfoId = BubbleText.prepareInteractiveBubbleFloating(\r\n                \"NORTH_WEST\", 0, 0, false, 2147483647, true,\r\n                \"interactiveBubbleDialog5\", 30000, 25000, \"onFightInfoClosed\"\r\n        )\r\n    end\r\n\r\n    BubbleText.setText(bubbleFightInfoId, \"kickstarter2025.fight.player.infos\", teamDamage, turnsRemaining, noxDamage, harebourgDamage)\r\n    BubbleText.show(bubbleFightInfoId)\r\nend\r\n\r\nfunction hideClockmen(harebourg, nox)\r\n    Mobile.setMobileVisible(harebourg, false)\r\n    Mobile.setMobileVisible(nox, false)\r\nend\r\n\r\nfunction showClockmen(harebourg, nox)\r\n    Mobile.setMobileVisible(harebourg, true)\r\n    Mobile.setMobileVisible(nox, true)\r\nend\r\n\r\nfunction setClockVisibility(isVisible)\r\n    local coordinates = {\r\n        { 5, 1 }, { 7, 2 }, { 9, 4 }, { 10, 6 }, { 9, 8 }, { 7, 10 },\r\n        { 5, 11 }, { 3, 10 }, { 1, 8 }, { 0, 6 }, { 1, 4 }, { 3, 2 }\r\n    }\r\n\r\n    for _, coord in ipairs(coordinates) do\r\n        World.setPictoAlpha(coord[1], coord[2], 40, isVisible and 1 or 0, 1000)\r\n    end\r\nend\r\n\r\nfunction firstCinematicEnd(nox, harebourg) -- Fonction custom pour pouvoir l'envoyer à tous les joueurs quand l'un d'entre eux skip\r\n    showClockmen(nox, harebourg)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n    setClockVisibility(true)\r\nend\n\n-- [INIT] Variables Globales\n-- \nfunction event_2720_24167()\n    \nend\n\n-- [INIT] Inscription du joueur + Variables Locales\n-- \nfunction event_2720_24168()\n    \nend\n\n-- CHARACTER_ENTER_INSTANCE_EVENT - Cinématique d'arrivée\n-- \nfunction event_2720_24169(nox, harebourg)\n    hideClockmen(nox, harebourg)\r\n    setClockVisibility(false)\r\n    \r\n    local playerId = Context.getLeaderId()\r\n    local noxCine = createActorWithDefaultParams(nox, 4, 3, 40, 1)\r\n    local harebourgCine = createActorWithDefaultParams(harebourg, 6, 3, 40, 5)\r\n    \r\n    Mobile.setMobileVisible(playerId, false)\r\n    \r\n    function customSkip()\r\n        skipCinematic(23383)\r\n    end\r\n    \r\n    Mobile.hideOtherPlayerMobile(true)\r\n    \r\n    startCinematicContext(1, playerId)\r\n    Camera.attachCameraToMobile(harebourgCine)\r\n    \r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"customSkip\")\r\n    \r\n    --Je ne comprends pas, Nox. Comment pouvons-nous nous retrouver dans la même temporalité au sommet de ma tour ?\r\n    invoke_custom(00000, 1, \"bubble\", harebourgCine, \"kickstarter2025.00.00\")\r\n    invoke_custom(8000, 1, \"clearBubbles\", harebourgCine)\r\n    \r\n    --C’est, impossible !!! Où sont mes créations, où est l’Éliacube ?\r\n    invoke_custom(8000, 1, \"bubble\", noxCine, \"kickstarter2025.00.01\")\r\n    invoke_custom(13000, 1, \"clearBubbles\", noxCine)\r\n    \r\n    --Je ne sais pas, je n’y comprends rien du tout !!!\r\n    invoke_custom(13000, 1, \"bubble\", harebourgCine, \"kickstarter2025.00.02\")\r\n    invoke_custom(17500, 1, \"clearBubbles\", harebourgCine)\r\n    \r\n    --Qui sait quelle autre entité aurait pu être transportée avec nous ?\r\n    invoke_custom(17500, 1, \"bubble\", harebourgCine, \"kickstarter2025.00.03\")\r\n    invoke_custom(22500, 1, \"clearBubbles\", harebourgCine)\r\n    \r\n    --Tu as raison, prudence est mère de sûreté. Profitons de ce moment calme pour élaborer un plan.\r\n    invoke_custom(22500, 1, \"bubble\", noxCine, \"kickstarter2025.00.04\")\r\n    invoke_custom(29500, 1, \"clearBubbles\", noxCine)\r\n    \r\n    invoke_custom(29500, 1, \"Mobile.setMobileVisible\", playerId, true)\r\n    invoke_custom(29501, 1, \"Mobile.setMobileDirection\", playerId, 3)\r\n    invoke_custom(29501, 1, \"Camera.attachCameraToMobile\", playerId)\r\n    invoke_custom(29502, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimIncarnam-Chute-Fin\")\r\n    invoke_custom(30000, 1, \"Mobile.setMobileDirection\", harebourgCine, 3)\r\n    invoke_custom(30500, 1, \"Mobile.setMobileDirection\", noxCine, 3)\r\n    \r\n    --Outch… Qu’est-ce qu’il vient de se passer ?\r\n    invoke_custom(31500, 1, \"bubble\", playerId, \"kickstarter2025.00.05\")\r\n    invoke_custom(31500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Defaite\")\r\n    invoke_custom(35500, 1, \"clearBubbles\", playerId)\r\n    \r\n    --J’ai mal au crâne…\r\n    invoke_custom(35500, 1, \"bubble\", playerId, \"kickstarter2025.00.06\")\r\n    invoke_custom(35500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Defaite\")\r\n    invoke_custom(37500, 1, \"clearBubbles\", playerId)\r\n    \r\n    --Cet endroit me dit quelque chose… J’ai l’impression qu’une atmosphère étrange s’en dégage.\r\n    invoke_custom(37500, 1, \"bubble\", playerId, \"kickstarter2025.00.07\")\r\n    invoke_custom(37500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Chercher\")\r\n    invoke_custom(40000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Pointer\")\r\n    invoke_custom(44000, 1, \"clearBubbles\", playerId)\r\n    \r\n    --Ça ne me dit rien qui vaille. Il faut que j’aille trouver le zaap le plus proche pour avoir un plan de sûreté si jamais les choses se passent mal.\r\n    invoke_custom(44000, 1, \"bubble\", playerId, \"kickstarter2025.00.08\")\r\n    invoke_custom(31500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-GratteGratte\")\r\n    invoke_custom(56500, 1, \"clearBubbles\", playerId)\r\n    \r\n    invoke_custom(47000, 1, \"Mobile.setMobileAnimation\", harebourgCine, \"AnimMouvementTeleport-Debut\")\r\n    invoke_custom(47000, 1, \"Mobile.setMobileAnimation\", noxCine, \"AnimTP-Debut\")\r\n    invoke_custom(47500, 1, \"Mobile.setMobileVisible\", harebourgCine, false)\r\n    invoke_custom(47500, 1, \"Mobile.setMobileVisible\", noxCine, false)\r\n    \r\n    invoke_custom(47500, 1, \"Mobile.setMobilePosition\", harebourgCine, 6, 7, 42)\r\n    invoke_custom(47500, 1, \"Mobile.setMobilePosition\", noxCine, 4, 7, 42)\r\n    \r\n    invoke_custom(48000, 1, \"Mobile.setMobileVisible\", harebourgCine, true)\r\n    invoke_custom(48000, 1, \"Mobile.setMobileVisible\", noxCine, true)\r\n    invoke_custom(48000, 1, \"Mobile.setMobileAnimation\", harebourgCine, \"AnimMouvementTeleport-Fin\")\r\n    invoke_custom(48000, 1, \"Mobile.setMobileAnimation\", noxCine, \"AnimTP-Fin\")\r\n    \r\n    invoke_custom(55000, 1, \"Mobile.setMobileDirection\", playerId, 7)\r\n    invoke_custom(55000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Effrayee\")\r\n    \r\n    --Toi !!!\r\n    invoke_custom(56500, 1, \"bubble\", playerId, \"kickstarter2025.00.09\")\r\n    invoke_custom(56500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Pointer\")\r\n    invoke_custom(56500, 1, \"bubble\", harebourgCine, \"kickstarter2025.00.09\")\r\n    invoke_custom(58500, 1, \"clearBubbles\", playerId)\r\n    invoke_custom(58500, 1, \"clearBubbles\", harebourgCine)\r\n    \r\n    --Vous vous connaissez ?\r\n    invoke_custom(58500, 1, \"bubble\", noxCine, \"kickstarter2025.00.10\")\r\n    invoke_custom(60500, 1, \"clearBubbles\", noxCine)\r\n    \r\n    --On s’est déjà croisés par le passé, il s’est toujours mis en travers de ma route.\r\n    invoke_custom(60500, 1, \"bubble\", playerId, \"kickstarter2025.00.11\")\r\n    invoke_custom(60500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Pointer\")\r\n    invoke_custom(60500, 1, \"bubble\", harebourgCine, \"kickstarter2025.00.11.5\")\r\n    invoke_custom(68500, 1, \"clearBubbles\", playerId)\r\n    invoke_custom(68500, 1, \"clearBubbles\", harebourgCine)\r\n    \r\n    --Eh !!!\r\n    invoke_custom(68500, 1, \"bubble\", playerId, \"kickstarter2025.00.12\")\r\n    invoke_custom(68500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Colere\")\r\n    invoke_custom(68500, 1, \"bubble\", harebourgCine, \"kickstarter2025.00.12\")\r\n    invoke_custom(70500, 1, \"clearBubbles\", playerId)\r\n    invoke_custom(70500, 1, \"clearBubbles\", harebourgCine)\r\n    \r\n    --Je ne comprends pas tout.\r\n    invoke_custom(70500, 1, \"bubble\", noxCine, \"kickstarter2025.00.13\")\r\n    invoke_custom(73000, 1, \"clearBubbles\", noxCine)\r\n    \r\n    --Il faut me croire, nous devons nous débarrasser d{[1*]?’elle:e lui}. Il va nous empêcher de repartir ici vivants !\r\n    invoke_custom(73000, 1, \"bubble\", playerId, \"kickstarter2025.00.14\")\r\n    invoke_custom(73000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Pointer\")\r\n    invoke_custom(73000, 1, \"bubble\", harebourgCine, \"kickstarter2025.00.14.5\")\r\n    invoke_custom(85000, 1, \"clearBubbles\", playerId)\r\n    invoke_custom(85000, 1, \"clearBubbles\", harebourgCine)\r\n    \r\n    --Prête-moi main forte, confrère Xélor. Devenons ensemble les souverains de cette perturbation temporelle.\r\n    invoke_custom(85000, 1, \"bubble\", harebourgCine, \"kickstarter2025.00.15\")\r\n    invoke_custom(85000, 1, \"Mobile.setMobileDirection\", harebourgCine, 5)\r\n    invoke_custom(91500, 1, \"clearBubbles\", harebourgCine)\r\n    \r\n    --Tu me sembles d’une toute autre trempe que cette demi-portion. Montrons-lui de quel bois se chauffent les grands Xélors.\r\n    invoke_custom(91500, 1, \"bubble\", noxCine, \"kickstarter2025.00.16\")\r\n    invoke_custom(91500, 1, \"Mobile.setMobileDirection\", noxCine, 1)\r\n    invoke_custom(101000, 1, \"clearBubbles\", noxCine)\r\n    \r\n    --Vous ne me laissez pas le choix, je vais mettre un terme définitif à vos plans mutuels une bonne fois pour toutes.\r\n    invoke_custom(101000, 1, \"bubble\", playerId, \"kickstarter2025.00.17\")\r\n    invoke_custom(101000, 1, \"Mobile.setMobileDirection\", harebourgCine, 3)\r\n    invoke_custom(101000, 1, \"Mobile.setMobileDirection\", noxCine, 3)\r\n    invoke_custom(101000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Colere\")\r\n    invoke_custom(151000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Pointer\")\r\n    invoke_custom(112500, 1, \"clearBubbles\", playerId)\r\n    \r\n    --Approche !!!\r\n    invoke_custom(112500, 1, \"bubble\", harebourgCine, \"kickstarter2025.00.18\")\r\n    invoke_custom(112500, 1, \"bubble\", noxCine, \"kickstarter2025.00.18\")\r\n    invoke_custom(114500, 1, \"clearBubbles\", harebourgCine)\r\n    invoke_custom(114500, 1, \"clearBubbles\", noxCine)\r\n    \r\n    invoke_custom(115500, 1, \"customSkip\")\nend\n\n-- CLIENT_TRIGGERED_EVENT - Validation cinématique + lancement du combat\n-- \nfunction event_2720_24170(nox, harebourg)\n    firstCinematicEnd(nox, harebourg)\r\n    \r\n    skipCinematic()\nend\n\n-- FIGHT_STARTED - On pose les zones\n-- \nfunction event_2720_24171()\n    \nend\n\n-- EFFECT_EXECUTION - Mise à jour UI infos de combat (score) - Nox\n-- \nfunction event_2720_24172()\n    \nend\n\n-- EFFECT_EXECUTION - Mise à jour UI infos de combat (score) - Harebourg\n-- \nfunction event_2720_24173()\n    \nend\n\n-- EFFECT_EXECUTION - Mise à jour UI infos de combat (score) - Total\n-- \nfunction event_2720_24174(turnsRemaining, teamDamage, noxDamage, harebourgDamage)\n    updateFightInfo(turnsRemaining, teamDamage, noxDamage, harebourgDamage)\nend\n\n-- EFFECT_EXECUTION - Mise à jour UI infos de combat (tour)\n-- \nfunction event_2720_24175(turnsRemaining, teamDamage, noxDamage, harebourgDamage)\n    updateFightInfo(turnsRemaining, teamDamage, noxDamage, harebourgDamage)\nend\n\n-- USER_GROUP_KILLED - Enregistrement au classement\n-- \nfunction event_2720_24176()\n    \nend\n\n-- FIGHT_ENDED_IN_CLIENT_EVENT - Cinématique de fin (Harebourg a plus de dommages) - ACH 5486 OBJ 11368\n-- \nfunction event_2720_24177()\n    local playerId = Context.getLeaderId()\r\n    local noxCine = createActorWithDefaultParams(1115005718, 4, 8, 40, 1)\r\n    local harebourgCine = createActorWithDefaultParams(104702383, 6, 8, 40, 5)\r\n    \r\n    function customSkip()\r\n        skipCinematic(23396)\r\n    end\r\n    \r\n    Mobile.setMobileDirection(playerId, 7)\r\n    Mobile.setMobileAnimation(playerId, \"AnimStatique02\")\r\n    \r\n    startCinematicContext(1.0, playerId)\r\n    \r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"customSkip\")\r\n    \r\n    --ARGH…\r\n    invoke_custom(000000, 1, \"bubble\", harebourgCine, \"kickstarter2025.01.00\")\r\n    invoke_custom(001000, 1, \"Mobile.setMobileAnimation\", harebourgCine, \"AnimHit\")\r\n    invoke_custom(002000, 1, \"clearBubbles\", harebourgCine)\r\n    \r\n    --Je savais que je ne pourrais jamais te faire confiance, Harebourg. On va voir comment tu t’en sors sans moi, maintenant.\r\n    invoke_custom(002000, 1, \"bubble\", noxCine, \"kickstarter2025.01.01\")\r\n    invoke_custom(002000, 1, \"Mobile.setMobileAnimation\", noxCine, \"\")\r\n    invoke_custom(012500, 1, \"clearBubbles\", noxCine)\r\n    \r\n    --Nox, reviens ! Nox…\r\n    invoke_custom(012500, 1, \"bubble\", harebourgCine, \"kickstarter2025.01.02\")\r\n    invoke_custom(014500, 1, \"clearBubbles\", harebourgCine)\r\n    invoke_custom(014500, 1, \"Mobile.setMobileAnimation\", noxCine, \"AnimTP-Debut\")\r\n    invoke_custom(015500, 1, \"Mobile.setMobileVisible\", noxCine, false)\r\n    \r\n    invoke_custom(016000, 1, \"customSkip\")\nend\n\n-- FIGHT_ENDED_IN_CLIENT_EVENT - Cinématique de fin (Nox a plus de dommages) - ACH 5486 OBJ 11367\n-- \nfunction event_2720_24178()\n    local playerId = Context.getLeaderId()\r\n    local noxCine = createActorWithDefaultParams(1115005718, 4, 8, 40, 1)\r\n    local harebourgCine = createActorWithDefaultParams(104702383, 6, 8, 40, 5)\r\n    \r\n    function customSkip()\r\n        skipCinematic(23396)\r\n    end\r\n    \r\n    Mobile.setMobileDirection(playerId, 7)\r\n    Mobile.setMobileAnimation(playerId, \"AnimStatique02\")\r\n    \r\n    startCinematicContext(1.0, playerId)\r\n    \r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"customSkip\")\r\n    \r\n    --ARGH…\r\n    invoke_custom(000000, 1, \"bubble\", noxCine, \"kickstarter2025.02.00\")\r\n    invoke_custom(002000, 1, \"clearBubbles\", noxCine)\r\n    \r\n    --Tu me déçois, Nox. Penser qu’un Xélor tel que toi finisse en sac de frappe pour aventuri{[1*]?ère:er} minable…\r\n    invoke_custom(002000, 1, \"bubble\", harebourgCine, \"kickstarter2025.02.01\")\r\n    invoke_custom(9500, 1, \"clearBubbles\", harebourgCine)\r\n    \r\n    --Je vais récupérer tes projets et les mener à terme. Les douziens entendront parler de moi comme du plus grand Xélor de tous les temps puisque tu n’en es visiblement pas digne.\r\n    invoke_custom(9500, 1, \"bubble\", harebourgCine, \"kickstarter2025.02.02\")\r\n    invoke_custom(22000, 1, \"clearBubbles\", harebourgCine)\r\n    \r\n    --Vermine ! Tu ne perds rien pour attendre, dès que j’aurai remonté dans le temps, je, je…\r\n    invoke_custom(22000, 1, \"bubble\", noxCine, \"kickstarter2025.02.03\")\r\n    invoke_custom(25000, 1, \"Mobile.setMobileDirection\", harebourgCine, 3)\r\n    invoke_custom(25000, 1, \"Mobile.setMobileAnimation\", harebourgCine, \"AnimDisparition\")\r\n    invoke_custom(27000, 1, \"Mobile.setMobileVisible\", harebourgCine, false)\r\n    invoke_custom(27000, 1, \"Mobile.setMobileAnimation\", noxCine, \"AnimMort\")\r\n    invoke_custom(27500, 1, \"clearBubbles\", noxCine)\r\n    \r\n    invoke_custom(28000, 1, \"customSkip\")\nend\n\n-- FIGHT_ENDED_IN_CLIENT_EVENT - On check les dommages pour ACH 5486 OBJ 11369\n-- \nfunction event_2720_24179()\n    \nend\n\n-- CLIENT_TRIGGERED_EVENT - On affiche le résultat du combat\n-- \nfunction event_2720_24180(teamDamage)\n    local teamDamage = toString(teamDamage)\r\n    \r\n    Mobile.hideOtherPlayerMobile(false)\r\n    \r\n    UI.setWidgetEnabled(\"fightResultDialog\", \"rootContainer\", true)\r\n    UI.setWidgetVisibility(\"fightResultDialog\", \"rootContainer\", true)\r\n    \r\n    local text = Event.getKeyTranslation(\"fight.score.ogrest\", teamDamage)\r\n    UI.setPropertyStringValue(\"fight.score.ogrest\", text)\r\n    UI.writeLocalisedInChat(\"ogrest.fight.team.score\", teamDamage)\r\n    \r\n    UI.removeUnremovableDialog(\"fightResultDialog\")\r\n    \r\n    UI.addDialogUnloadedListener(\"fightResultDialog\", \"UI.removeProperty\", \"fight.score.ogrest\")\nend\n\n-- FIGHT_ENDED - On remet le TP\n-- \nfunction event_2720_24181()\n    \nend\n\n-- FIGHT_ENTER_ACTION_PHASE - Application états\n-- \nfunction event_2720_24201()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","createActorWithDefaultParams","onFightInfoClosed","updateFightInfo","hideClockmen","showClockmen","setClockVisibility","firstCinematicEnd","event_2720_24167","event_2720_24168","event_2720_24169","customSkip","event_2720_24170","event_2720_24171","event_2720_24172","event_2720_24173","event_2720_24174","event_2720_24175","event_2720_24176","event_2720_24177","customSkip","event_2720_24178","customSkip","event_2720_24179","event_2720_24180","event_2720_24181","event_2720_24201"],"quest_calls":[],"dialogue_calls":[]},"scenario/2721.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n-- TRIGGER CLIENT --\r\n-- 0 = Fin cinématique VIDEO | Déclenché par le callback Video.addVideoStopOrEndCallback\r\n-- 1 = Arrivée dans l'instance | Déclenché par onInstanceLoaded() callback par Event.runOnInstanceLoaded (cf code Global)\r\n-- 2 = Fin cinématique | Déclenché par stopCinematicContext() (cf code Global)\r\n-- 3 = Fermeture UI Fin de combat\r\n-- 4 = Clic sur le bon bouton de changement d'oriention (parmis les 4) dans UI worldAndFightBar pour s'orientation vers le monstre\r\n-- 5 = Fermeture UI Fiche combattant\r\n-- 6 = Clic sur le bouton de validation de la répartition dans UI Aptitudes\r\n-- 7 = Clic sur la boussole du bon objectif dans l'UI suivi de quête\r\n-- 8 = Fermeture UI Map Monde\r\n\r\n-- VARIABLE GLOBALE - SCRIPT --\r\n\r\nwidget_visible = {}\r\nwidget_enable = {}\r\nui_tweens = {}\r\nui_particles = {}\r\nui_listener_load = {}\r\nui_listener_unload = {}\r\nui_listener_event = {}\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\nscreenEffectId = nil\r\n\r\n-- VARIABLE GLOBALE - MOBILE CINEMATIQUE & TUTO --\r\n\r\nANM_otomai = {think=\"AnimComp-Special03\", talk=\"AnimComp-Special04-Debut\", show=\"AnimComp-Special05-Debut\", nice=\"AnimComp-Special07\", nope=\"AnimComp-Special08\", lol=\"AnimComp-Special09\", stop_it=\"AnimComp-Special10\", come_here=\"AnimComp-Special01\", wave_hit=\"AnimComp-Special02\", fly=\"AnimStatique-Oiseau\", cast=\"AnimSort-01\", supercast=\"AnimComp-Special11\", attack=\"AnimSort-Cast\", balance=\"AnimComp-Special06\"}\r\nANM_melee = {attack=\"AnimSort-Morsure\", glitch1=\"AnimComp-Glitch01\", glitch2=\"AnimComp-Glitch02\", glitch3=\"AnimComp-Glitch03\", roar=\"AnimComp-Agressif\"}\r\nANM_range = {attack=\"AnimSort-01\", glitch=\"AnimComp-Glitch\", dupli=\"AnimComp-Dupli\"}\r\nANM_boss = {attack1=\"AnimSort-Estoc\", attack2=\"AnimSort-Hrargh\", glitch=\"AnimComp-Glitch\", dupli=\"AnimComp-Dupli\", roar=\"AnimComp-Hurle\", ko = \"AnimKO-SortieOK\", death= \"AnimKO-SortieHS\"}\r\n\r\nNPC_otomai = Mobile.generateClientMobileId()\r\nNPC_otomai_gfx = 181404009\r\nNPC_otomai_particleZ = 10\r\nNPC_otomai_bubbleX = 10\r\nNPC_otomai_bubbleY = 70\r\n\r\nNPC_melee = Mobile.generateClientMobileId()\r\nNPC_meleeB = Mobile.generateClientMobileId()\r\nNPC_melee_gfx = 181404014\r\nNPC_melee_particleZ = 5\r\n\r\nNPC_range = Mobile.generateClientMobileId()\r\nNPC_range_gfx = 181404015\r\nNPC_range_particleZ = 3\r\n\r\nNPC_boss = Mobile.generateClientMobileId()\r\nNPC_boss_gfx = 181404012\r\nNPC_boss_particleZ = 8\r\n\r\nNPC_eni_wakfu = Mobile.generateClientMobileId()\r\nNPC_eni_wakfu_gfx = 181404034\r\nNPC_eni_wakfu_particleZ = 7\r\n\r\nNPC_eni_stasis = Mobile.generateClientMobileId()\r\nNPC_eni_stasis_gfx = 181404013\r\nNPC_eni_stasis_particleZ = 7\r\n\r\n_ACTOR_LIST = {NPC_otomai, NPC_melee, NPC_meleeB, NPC_range, NPC_boss, NPC_eni_wakfu, NPC_eni_stasis}\r\n\r\n-- VARIABLE GLOBALE - PARTICULE CINEMATIQUE & TUTO --\r\n\r\n-- UI TUTO\r\napsArrowBig = {6001069,6001070,6001071,6001072,6001073,6001074,6001075,6001076}\r\napsArrow = {6001061,6001062,6001063,6001064,6001065,6001066,6001067,6001068}\r\napsCenter = {ap=6001090, mp=6001091, wp=6001092, hp=6001093}\r\napsFollowBorder = -1548037644\r\n-- WORLD TUTO\r\napsCell = {white_border=800578, red_border=800579, white_arrow=800576, red_arrow=800577, white=800581, red=800582, show=78900}\r\n-- CINEMATIQUE\r\napsWave = {spawn=800573, wave=800574, hit=800575}\r\napsOtomai = {shield=-1814057071, transform=-1814057072, playershield = -1814057074}\r\napsCristal = {base=71071022, react=800580, shield=71071021}\r\napsBoss = {death=-1814057073}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n    for index, value in ipairs (tab) do\r\n\t\tif isEqual(value, val) then\r\n            return true\r\n        end\r\n    end\r\n\r\n    return false\t\r\nend\r\n\r\n-- FONCTION UI -- Replace le Chat en bas à gauche et le rend indéplaçable/déplaçable\r\nfunction prepareChatUI(movable, chatOffsetX)\r\n\tif not UI.isDialogLoaded(\"chatDialog0\") then return end\r\n\t\r\n\tif (not chatOffsetX) then chatOffsetX = 0 end\r\n\t\r\n\tUI.setPosition(\"chatDialog0\", chatOffsetX, 0)\r\n\tUI.setWindowMovable(\"chatDialog0\", movable)\r\nend\r\n\r\n-- FONCTION UI -- Replace le Suivi de Quête mi-hauteur à gauche et le rend indéplaçable/déplaçable\r\nfunction prepareFollowQuestUI(movable)\r\n    local dialogName = \"\"\r\n    if UI.isDialogLoaded(\"verticalFollowedAchievementsDialog\") then\r\n        dialogName = \"verticalFollowedAchievementsDialog\"\r\n    end\r\n    if UI.isDialogLoaded(\"followedAchievementsDialog\") then\r\n        dialogName = \"followedAchievementsDialog\"\r\n    end\r\n\r\n    if (dialogName == \"\") then\r\n        return\r\n    end\r\n\r\n    local screenH, screenW = UI.getWindowSize()\r\n    local x, y = UI.getPosition(dialogName)\r\n\r\n    UI.setPosition(dialogName, x, screenH / 4)\r\n    UI.setWindowMovable(dialogName, movable)\r\nend\r\n\r\n-- FONCTION UI -- Rend Visible/Invisible certains éléments des interfaces\r\nfunction prepareUI(visible)\r\n  --Interface Boutique & Cadeau\r\n  setWidgetVisible(\"topHudDialog\", \"optionShopButton\", visible)\r\n  setWidgetVisible(\"topHudDialog\", \"giftButton\", visible)\r\n\r\n  --UI sous le Coeur\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"wakfuStasisBar\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"xpBar\", visible)\r\n\r\n  --Boutons hors combat à droite du Coeur\r\n  setWidgetVisible(\"shortcutBarDialog\", \"previousButton\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"nextButton\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseShortcutBar1\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseShortcutBar2\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseShortcutBar3\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseShortcutBar4\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"shortcutBarItemButton\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"shortcutBarSpellButton\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseButtonContainerForTuto1\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseButtonContainerForTuto2\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseButtonContainerForTuto3\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseButtonContainerForTuto4\", visible)\r\n\r\n  --Boutons hors combat à gauche de l'écran - barre d'interfaces\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"firstInterfaceBarBackground\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"secondInterfaceBarBackground\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"extraInterfaceBarDrawerButton\", visible)\r\n\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"fightInfoBtn\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"inventoryButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"buildSheetSetButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"craftButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"questsButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"dungeonButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"cosmeticsButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"tutorialBookButton\", visible)\r\n\r\n  --Boutons hors combat à gauche de l'écran - barre d'interfaces (deuxième barre)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"contactListButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"guildButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"companionsButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"nationButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"battlegroundButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"passportButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"emoteButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"encyclopediaButton\", visible)\r\n\r\n  --Boutons hors combat \"actions rapides\"\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"OverWorldActionsBackground\", visible)\r\n\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"dimensionalBagButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"mapButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"rideMountButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"miniMapButton\", visible)\r\n\r\n  --Boutons en combat à gauche du Coeur\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"FightActionsBackground\", visible)\r\n\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"giveUpButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"hideFightersButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"tacticalModeBtn\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"reportCellBtn\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"fightMarkerBtn\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"lockFightBtn\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"resistanceOverheadBtn\", visible)\r\nend\r\n\r\n-- FONCTION SHORTCUT -- Rend Actif/Inactif certains raccourcis\r\nfunction prepareShortcuts(enabled, shortcutType)\r\n  if not shortcutType or shortcutType == \"WORLD\" then\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.world\", \"enterLeaveBag\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.world\", \"switchHero0\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.world\", \"switchHero1\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.world\", \"switchHero2\")\r\n  end\r\n  if not shortcutType or shortcutType == \"DISPLAY\" then\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"zoomIn\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"zoomOut\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"closeWindows\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"setLODLevel\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"setFightLODLevel\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"showHideNameOverheadsCommand\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"hideFightOccluders\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"alphaMask\")\r\n  end\r\n  if not shortcutType or shortcutType == \"CHAT\" then\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.chat\", \"chat\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.chat\", \"lastContact\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.chat\", \"firstContact\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.chat\", \"autoCompletePlayerName\")\r\n    for bind=1, 9, 1 do\r\n      UI.setShortcutEnabled(enabled, \"shortcutCategory.shortcutBar\", \"bind\" .. toString(bind))\r\n    end\r\n  end\r\n\r\n  if not shortcutType or shortcutType == \"FIGHT\" then\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"fighterTransparency\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"switchTacticalView\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"nextSelectedFighter\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"giveUp\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"lockFight\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"reportCell\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"callHelp\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"displayHpBar\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"resetFightCamera\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"endPlacementAndTurn\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"closeCombatRight\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"closeCombatLeft\")\r\n  end\r\n  if not shortcutType or shortcutType == \"INTERFACE\" then\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"minimap\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"contactList\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"companionManagement\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"guild\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"craft\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"dungeonList\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"achievements\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"quests\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"emotes\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"ecosystem\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"climate\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"nation\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"partySearch\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"passport\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"almanax\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"tutorialBook\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"switchToDirectAttackCommand\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"map\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"spellsInventory\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"inventory\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"characterBook\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"osamodasSymbiot\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"shortcutBar0\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"shortcutBar1\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"shortcutBar2\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"shortcutBar3\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"additionalShortcutBar0\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"additionalShortcutBar1\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"additionalShortcutBar2\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"additionalShortcutBar3\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"changeShortcutBarType\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"downscaling\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"rewards\")\r\n\tUI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"battlegroundList\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"aptitudes\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"presets\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"encyclopedia\")\r\n  end\r\n\r\n  -- On ne bloque pas les raccourcis de sorts finalement\r\n--   if not shortcutType or shortcutType == \"SHORTCUTBAR\" then\r\n--     for bar=0,3, 1 do\r\n--       for slot=0, 9, 1 do\r\n--         UI.setShortcutEnabled(enabled, \"shortcutCategory.shortcutBar\", \"shortcut\" .. toString(bar) .. toString(slot))\r\n--       end\r\n--     end\r\n--   end\r\nend\r\n\r\n-- FONCTION UI -- Rend Visible/Invisible un élément d'une interface\r\nfunction setWidgetVisible(dialogName, widgetName, visible)\r\n  if not UI.isDialogLoaded(dialogName) then return end\r\n\r\n  UI.setWidgetVisibility(dialogName, widgetName, visible)\r\n  table.insert(widget_visible, { name = dialogName, id = widgetName, state = visible })\r\nend\r\n\r\nfunction clearWidgetVisible()\r\n  local str = \"\"\r\n  for i=#widget_visible, 1, -1 do\r\n    str = str .. toString(widget_visible[i].name) .. \"@\" .. toString(widget_visible[i].id) .. \";\"\r\n    UI.setWidgetVisibility(widget_visible[i].name, widget_visible[i].id, true)\r\n  end\r\n\r\n  widget_visible = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearWidgetVisible\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Rend Actif/Inactif un élément d'une interface\r\nfunction setWidgetEnable(dialogName, widgetName, enable)\r\n  if not UI.isDialogLoaded(dialogName) then return end\r\n\r\n  UI.setWidgetEnabled(dialogName, widgetName, enable)\r\n  table.insert(widget_enable, {name = dialogName, id = widgetName, state = enable})\r\nend\r\n\r\nfunction clearWidgetEnable()\r\n  local str = \"\"\r\n  for i=#widget_enable, 1, -1 do\r\n    str = str .. toString(widget_enable[i].name) .. \"@\" .. toString(widget_enable[i].id) .. \";\"\r\n    UI.setWidgetEnabled(widget_enable[i].name, widget_enable[i].id, true)\r\n  end\r\n\r\n  widget_enable = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearWidgetEnable\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Ajoute/Retire une TweenParticle à un élément d'une interface\r\nfunction setUIColorTween(dialogName, widgetName, duration, loop, r1, g1, b1, a1, r2, g2, b2, a2)\r\n  if not UI.isDialogLoaded(dialogName) then return end\r\n\r\n  UI.addColorTween(dialogName, widgetName, duration, loop, r1, g1, b1, a1, r2, g2, b2, a2)\r\n  table.insert(ui_tweens, {name = dialogName, id = widgetName})\r\nend\r\n\r\nfunction clearUIColorTweens(dialogName, widgetName)\r\n  local str = \"\"\r\n  for i=#ui_tweens, 1, -1 do\r\n    if ((not dialogName) or (dialogName == ui_tweens[i].name)) and ((not widgetName) or (widgetName == ui_tweens[i].id)) then\r\n      str = str .. toString(ui_tweens[i].name) .. \"@\" .. toString(ui_tweens[i].id) .. \";\"\r\n      UI.removeColorTween(ui_tweens[i].name, ui_tweens[i].id)\r\n      table.remove(ui_tweens, i)\r\n    end\r\n  end\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearUIColorTweens\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Ajoute/Retire une Particle à un élément d'une interface\r\nfunction setUIParticle(dialogName, widgetName, apsFileName, x, y, alignment, level)\r\n  if not UI.isDialogLoaded(dialogName) then return end\r\n\r\n  local particleId = UI.addParticle(dialogName, widgetName, apsFileName, x, y, alignment, level)\r\n  table.insert(ui_particles, {name = dialogName, id = widgetName})\r\n\r\n  return particleId\r\nend\r\n\r\nfunction setUIParticleBorder(dialogName, widgetName, apsFileName, x, y, alignment, level, speed)\r\n  if not UI.isDialogLoaded(dialogName) then return end\r\n\r\n  local particleId = UI.addParticleToBorder(dialogName, widgetName, apsFileName, x, y, alignment, level, speed)\r\n  table.insert(ui_particles, {name = dialogName, id = widgetName})\r\n\r\n  return particleId\r\nend\r\n\r\nfunction clearUIParticles(dialogName, widgetName)\r\n  local str = \"\"\r\n  for i=#ui_particles, 1, -1 do\r\n    if ((not dialogName) or (dialogName == ui_particles[i].name)) and ((not widgetName) or (widgetName == ui_particles[i].id)) then\r\n      str = str .. toString(ui_particles[i].name) .. \"@\" .. toString(ui_particles[i].id) .. \";\"\r\n      UI.clearParticles(ui_particles[i].name, ui_particles[i].id)\r\n      table.remove(ui_particles, i)\r\n    end\r\n  end\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearUIParticles\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Enregistre/Supprime un callback à l'ouverture d'une interface\r\nfunction addDialogLoadListener(dialog, funcName, ...)\r\n  UI.addDialogLoadedListener(dialog, funcName, unpack(arg))\r\n  table.insert(ui_listener_load,  dialog)\r\nend\r\n\r\nfunction clearDialogLoadListener(dialogName)\r\n  local str = \"\"\r\n  for i=#ui_listener_load, 1, -1 do\r\n    if (not dialogName) or (dialogName == ui_listener_load[i]) then\r\n      str = str .. toString(ui_listener_load[i]) .. \";\"\r\n      UI.removeDialogLoadedListener(ui_listener_load[i])\r\n      table.remove(ui_listener_load, i)\r\n    end\r\n  end\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearDialogLoadListener\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Enregistre/Supprime un callback à la fermeture d'une interface\r\nfunction addDialogUnloadListener(dialog, funcName, ...)\r\n  UI.addDialogUnloadedListener(dialog, funcName, unpack(arg))\r\n  table.insert(ui_listener_unload, dialog)\r\nend\r\n\r\nfunction clearDialogUnloadListener(dialogName)\r\n  local str = \"\"\r\n  for i=#ui_listener_unload, 1, -1 do\r\n    if (not dialogName) or (dialogName == ui_listener_unload[i]) then\r\n      str = str .. toString(ui_listener_unload[i]) .. \";\"\r\n      UI.removeDialogUnloadedListener(ui_listener_unload[i])\r\n      table.remove(ui_listener_unload, i)\r\n    end\r\n  end\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearDialogUnloadListener\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Enregistre/Supprime un callback sur un élément d'une interface\r\nfunction addDialogEventListener(dialog, id, eventType, funcName, ...)\r\n  if not UI.isDialogLoaded(dialog) then return end\r\n\r\n  UI.addEventListener(dialog, id, eventType, funcName, unpack(arg))\r\n  table.insert(ui_listener_event, {dialog=dialog, id=id, eventType=eventType, funcName=funcName})\r\nend\r\n\r\nfunction clearDialogEventListener(dialogName)\r\n  local str = \"\"\r\n  for i=#ui_listener_event, 1, -1 do\r\n    if (not dialogName) or (dialogName == ui_listener_event[i].dialog) then\r\n      str = str .. toString(ui_listener_event[i].dialog) .. \"@\" .. toString(ui_listener_event[i].id) .. \";\"\r\n      UI.removeEventListener(ui_listener_event[i].dialog, ui_listener_event[i].id, ui_listener_event[i].eventType, ui_listener_event[i].funcName)\r\n      table.remove(ui_listener_event, i)\r\n    end\r\n  end\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearDialogEventListener\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y , z, ...)\r\n  local particleId = Particle.addParticleSystem(particleFileId, x, y , z, unpack(arg))\r\n  table.insert(world_particles, particleId)\r\n\r\n  return particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n  local particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n  table.insert(world_particles, particleId)\r\n\r\n  return particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n  local str = \"\"\r\n  for i=#world_particles, 1, -1 do\r\n    str = str .. toString(world_particles[i]) .. \";\"\r\n    Particle.removeParticleSystem(world_particles[i])\r\n  end\r\n\r\n  world_particles = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n  BubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n  if isLower(mobileId, 0) then\r\n    BubbleText.setCharacterSpeak(mobileId, text)\r\n  else\r\n    if (not offsetY) then\r\n      local height = Mobile.getMobileHeight(mobileId)\r\n      if (not height) then height = 6 end\r\n\r\n      offsetY = height * 10\r\n    end\r\n\r\n    if (not offsetX) then offsetX = 0 end\r\n    if (not infiniteDuration) then infiniteDuration = false end\r\n\r\n    BubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n    UI.writeLocalisedInChat(text)\r\n  end\r\n\r\n  if (not tContains(bubbles, mobileId)) then\r\n    table.insert(bubbles, mobileId)\r\n  end\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n  local str = \"\"\r\n  for i = #bubbles, 1, -1 do\r\n    if (not mobileId) then\r\n      str = str .. toString(bubbles[i]) .. \";\"\r\n      BubbleText.closeBubbleAttachedTo(bubbles[i])\r\n    elseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n      str = str .. toString(bubbles[i]) .. \";\"\r\n      BubbleText.closeBubbleAttachedTo(bubbles[i])\r\n      table.remove(bubbles, i)\r\n    end\r\n  end\r\n\r\n  if (not mobileId) then bubbles = {} end\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n  local compassId = UI.addCompass(\"compass\", x, y, z)\r\n  table.insert(compasses, compassId)\r\n\r\n  return compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n  local str = \"\"\r\n  for i=#compasses, 1, -1 do\r\n    str = str .. toString(compasses[i]) .. \";\"\r\n    UI.removeCompass(compasses[i])\r\n  end\r\n\r\n  compasses = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height)\r\n  local mobileId = Mobile.generateClientMobileId()\r\n  Actor.createActor(mobileId, spriteName, worldX, worldY, worldZ, availableDirection)\r\n\r\n  if (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n  if (height) then Actor.setActorHeight(mobileId, height) end\r\n\r\n  table.insert(actors, mobileId)\r\n\r\n  return mobileId\r\nend\r\n\r\nfunction clearActors()\r\n  local str = \"\"\r\n  for i = #actors, 1, -1 do\r\n    str = str .. toString(actors[i]) .. \";\"\r\n    Actor.deleteActor(actors[i])\r\n  end\r\n\r\n  actors = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n  local taskId = invoke(delay, count, funcName, unpack(arg))\r\n  table.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n  local str = \"\"\r\n  for i=#invoke_tasks, 1, -1 do\r\n    str = str .. toString(invoke_tasks[i]) .. \";\"\r\n    interrupt(invoke_tasks[i])\r\n    desinvoke(invoke_tasks[i])\r\n  end\r\n\r\n  invoke_tasks = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n  invoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n  local taskId = setInterval(delay, funcName, unpack(arg))\r\n  table.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n  local str = \"\"\r\n  for i=#interval_tasks, 1, -1 do\r\n    str = str .. toString(interval_tasks[i]) .. \";\"\r\n    interrupt(interval_tasks[i])\r\n    desinvoke(interval_tasks[i])\r\n  end\r\n\r\n  interval_tasks = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n  if (_DEBUG) then trace(\"startCinematicContext\") end\r\n\r\n  UI.manageFrame(\"World\", false)\r\n  UI.closeMRU()\r\n  UI.closeAllBags()\r\n  UI.setUIVisible(false)\r\n  UI.displayWideScreenBand(true)\r\n  Camera.setUserZoomLocked(true)\r\n\r\n  if (cameraMobileId ~= nil)  then\r\n    Camera.setMoveSpeedFactor(10000)\r\n    Camera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n  end\r\n\r\n  if (zoomFactor ~= nil)  then\r\n    Camera.setZoomFactor(zoomFactor)\r\n  end\r\n\r\n  if (musicId ~= nil)  then\r\n    Sound.playForcedMusic(musicId)\r\n  end\r\n\r\n  if (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\nfunction skipCinematic()\r\n  local player = Context.getLeaderId()\r\n\r\n  for x = 1, #_ACTOR_LIST do\r\n    Actor.deleteActor(_ACTOR_LIST[x])\r\n  end\r\n\r\n  UI.hideButton()\r\n  clearALL()\r\n  stopCinematicContext(1, player, true)\r\n  Mobile.setMobileVisible(player, true)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n  if (_DEBUG) then trace(\"stopCinematicContext\") end\r\n\r\n  UI.displayWideScreenBand(false)\r\n  UI.setUIVisible(true)\r\n  Camera.setUserZoomLocked(false)\r\n  UI.manageFrame(\"World\", true)\r\n\r\n  Camera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n  Camera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n  if (zoomFactor ~= nil) then\r\n    Camera.setZoomFactor(zoomFactor)\r\n  end\r\n\r\n  if (cameraMobileId ~= nil) then\r\n    Camera.attachCameraToMobile(cameraMobileId)\r\n  end\r\n\r\n  if (stopMusic) then\r\n    Sound.stopForcedMusic()\r\n  end\r\n\r\n  if (_DEBUG) then\r\n    UI.hideButton()\r\n  end\r\n\r\n  --TRIGGER\r\n  Server.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Affiche/Masque une texture à l'écran\r\nfunction displayScreenEffect(enable, fadeInDur, alphaDur, fadeOutDur, r, g, b, alpha)\r\n  if (_DEBUG) then trace(\"displayScreenEffect\") end\r\n\r\n  if not enable and screenEffectId ~= nil  then\r\n    --On retire le blackScreen\r\n    Effect.stopEffect(screenEffectId)\r\n  else\r\n    --On affiche un blackScreen à l'entrée dans l'instance le temps qu'elle soit complètement chargée\r\n    screenEffectId = Effect.createFullScreenSprite(fadeInDur, alphaDur, fadeOutDur, r, g, b, alpha)\r\n  end\r\nend\r\n\r\n-- FONCTION NETTOYAGE --\r\nfunction clearALL()\r\n  clearIntervalTasks()\r\n  clearInvokeTasks()\r\n  clearBubbles()\r\n  clearUIColorTweens()\r\n  clearUIParticles()\r\n  clearWorldParticles()\r\n  clearCompasses()\r\n  clearActors()\r\n\r\n  Focus.display(false)\r\n  UI.unloadTutorialDialog()\r\nend\r\n\r\n-- FONCTION NETTOYAGE --\r\nfunction clearUI(dialogName)\r\n  clearUIColorTweens(dialogName)\r\n  clearUIParticles(dialogName)\r\nend\r\n\r\n-- FONCTION NETTOYAGE --\r\nfunction clearListener(dialogName)\r\n  clearDialogLoadListener(dialogName)\r\n  clearDialogUnloadListener(dialogName)\r\n  clearDialogEventListener(dialogName)\r\nend\r\n\r\n-- Fonction mode démo\r\n-- function addButton()\r\n-- \tinvoke(2000, 1, \"UI.displayButton\", false, \"scenario.endKinematic.confirmEscape\", \"lyongameshow.vampyro.rules.display\", \"displayFightRules\")\r\n-- end \r\n\r\nfunction displayFightRules()\r\n--\tUI.loadTutorialDialog(\"japan.expo.2022\",\"japanexpo.fight.title\",\"japanexpo.fight.desc\")\r\n--\taddButton()\r\nend\r\n\r\nfunction onEnterInstance()  \r\n-- addButton()\r\n \t\r\n   UI.activateFollowAchievement(false)\r\n   prepareUI(false)\r\n   prepareShortcuts(false)\r\n   prepareShortcuts(true, \"DISPLAY\")\r\n   prepareShortcuts(true, \"CHAT\")\r\n   prepareShortcuts(true, \"FIGHT\")\r\n   prepareShortcuts(true, \"SHORTCUTBAR\")\r\n\r\n  UI.setShortcutEnabled(true, \"shortcutCategory.interface\", \"emotes\")\r\n  UI.setShortcutEnabled(false, \"shortcutCategory.interface\", \"switchToDirectAttackCommand\")\r\n  UI.setShortcutEnabled(false, \"shortcutCategory.interface\", \"spellsInventory\")\r\n  UI.setShortcutEnabled(false, \"shortcutCategory.interface\", \"inventory\")\r\n  UI.setShortcutEnabled(false, \"shortcutCategory.interface\", \"osamodasSymbiot\")\r\n  UI.setShortcutEnabled(false, \"shortcutCategory.interface\", \"shortcutBar0\")\r\n  UI.setShortcutEnabled(false, \"shortcutCategory.interface\", \"shortcutBar1\")\r\n  UI.setShortcutEnabled(false, \"shortcutCategory.interface\", \"shortcutBar2\")\r\n  UI.setShortcutEnabled(false, \"shortcutCategory.interface\", \"shortcutBar3\")\r\n  UI.setShortcutEnabled(false, \"shortcutCategory.interface\", \"additionalShortcutBar0\")\r\n  UI.setShortcutEnabled(false, \"shortcutCategory.interface\", \"additionalShortcutBar1\")\r\n  UI.setShortcutEnabled(false, \"shortcutCategory.interface\", \"additionalShortcutBar2\")\r\n  UI.setShortcutEnabled(false, \"shortcutCategory.interface\", \"additionalShortcutBar3\")\r\n  UI.setShortcutEnabled(false, \"shortcutCategory.interface\", \"changeShortcutBarType\")\r\n  \r\n    --Boutons hors combat à droite du Coeur\r\n  setWidgetVisible(\"shortcutBarDialog\", \"previousButton\", true)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"nextButton\", true)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"addExtraBarButton\", true)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"shortcutModeButton\", true)\r\n \r\n \r\n -- Boutons hors combat à gauche du Coeur\r\n\r\n  --Boutons en combat à gauche du Coeur\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"giveUpButton\", true)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"hideFightersButton\", true)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"reportCellBtn\", true)\r\nend\r\n\r\n-- Fonctions cache / montre CM\r\nfunction hideMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, false)\r\nend\r\n\r\nfunction showMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, true)\r\nend\r\n\r\nbubbleFightInfoId = 0\r\n\r\nfunction closeFightInfo()\r\n\tif (bubbleFightInfoId ~= nil and bubbleFightInfoId ~= 0) then BubbleText.close(bubbleFightInfoId) end\r\nend\r\n\r\nfunction onFightInfoClosed()\r\n\tif (bubbleFightInfoId ~= nil and bubbleFightInfoId ~= 0) then bubbleFightInfoId = 0 end\r\nend\r\n\r\nfunction updateFightInfo(turnLeft, teamDamage, forceDisplayUI)\r\n\tlocal turnLeft = toLong(turnLeft)\r\n\tlocal teamDamage = toLong(teamDamage)\r\n\r\n\tif (bubbleFightInfoId == 0) then\r\n\t\tbubbleFightInfoId = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_WEST\", 0, -60, false, 2147483647, true, \"interactiveBubbleDialog5\", 30000, 25000, \"onFightInfoClosed\")\r\n\tend\r\n\r\n\tBubbleText.setText(bubbleFightInfoId, \"japan.expo.2025.fight.info\", turnLeft, teamDamage)\r\n\r\n\tif (forceDisplayUI) then BubbleText.show(bubbleFightInfoId) end\r\nend\n\n-- [INIT] Variables globales\n-- \nfunction event_2721_24182()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2721_24183()\n    \nend\n\n-- [EVENT] MONSTER_ACTION_EVENT - Lancement du combat\n-- \nfunction event_2721_24184()\n    \nend\n\n-- [EVENT] FIGHT_ENTER_ACTION_PHASE - Application états\n-- \nfunction event_2721_24185()\n    updateFightInfo(turnLeft, teamDamage, true)\nend\n\n-- [EVENT] FIGHT_ENDED_IN_CLIENT - On ferme l'affichage\n-- \nfunction event_2721_24186(teamDamage, fightWon)\n    local teamDamage = toLong(teamDamage)\r\n    \r\n    if (toLong(fightWon) == 1) then\r\n    \tUI.writeLocalisedInChat(\"japan.expo.2025.fight.won\")\r\n    \tUI.writeLocalisedInChat(\"japan.expo.2025.fight.final.score.damage\", teamDamage)\r\n    end\r\n    \r\n    closeFightInfo()\nend\n\n-- EFFECT_EXECUTION - Mise à jour UI infos de combat (score)\n-- \nfunction event_2721_24187(turnLeft, teamDamage)\n    updateFightInfo(turnLeft, teamDamage, true)\nend\n\n-- EFFECT_EXECUTION - Mise à jour UI infos de combat (tours restants)\n-- \nfunction event_2721_24188(turnLeft, teamDamage)\n    updateFightInfo(turnLeft, teamDamage, true)\nend\n\n-- EFFECT_EXECUTION - Le joueur a gagné le combat\n-- \nfunction event_2721_24189()\n    \nend\n\n-- [EVENT] Victoire du combat - Enregistrement au classement\n-- \nfunction event_2721_24190()\n    \nend\n\n-- [TEST] Met fin au combat à la fin du tour de table\n-- \nfunction event_2721_24191()\n    \nend\n\n-- FIGHT_PLACEMENT_END - Le joueur est exclu et contrôle Karn\n-- \nfunction event_2721_24192()\n    \nend\n\n","functions":["tContains","prepareChatUI","prepareFollowQuestUI","prepareUI","prepareShortcuts","setWidgetVisible","clearWidgetVisible","setWidgetEnable","clearWidgetEnable","setUIColorTween","clearUIColorTweens","setUIParticle","setUIParticleBorder","clearUIParticles","addDialogLoadListener","clearDialogLoadListener","addDialogUnloadListener","clearDialogUnloadListener","addDialogEventListener","clearDialogEventListener","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","bubble","clearBubbles","setCompass","clearCompasses","createActor","clearActors","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","startCinematicContext","skipCinematic","stopCinematicContext","displayScreenEffect","clearALL","clearUI","clearListener","addButton","displayFightRules","onEnterInstance","hideMonster","showMonster","closeFightInfo","onFightInfoClosed","updateFightInfo","event_2721_24182","event_2721_24183","event_2721_24184","event_2721_24185","event_2721_24186","event_2721_24187","event_2721_24188","event_2721_24189","event_2721_24190","event_2721_24191","event_2721_24192"],"quest_calls":["UI.activateFollowAchievement(false)\r"],"dialogue_calls":[]},"scenario/2722.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n-- TRIGGER CLIENT --\r\n-- 0 = Fin cinématique VIDEO | Déclenché par le callback Video.addVideoStopOrEndCallback\r\n-- 1 = Arrivée dans l'instance | Déclenché par onInstanceLoaded() callback par Event.runOnInstanceLoaded (cf code Global)\r\n-- 2 = Fin cinématique | Déclenché par stopCinematicContext() (cf code Global)\r\n-- 3 = Fermeture UI Fin de combat\r\n-- 4 = Clic sur le bon bouton de changement d'oriention (parmis les 4) dans UI worldAndFightBar pour s'orientation vers le monstre\r\n-- 5 = Fermeture UI Fiche combattant\r\n-- 6 = Clic sur le bouton de validation de la répartition dans UI Aptitudes\r\n-- 7 = Clic sur la boussole du bon objectif dans l'UI suivi de quête\r\n-- 8 = Fermeture UI Map Monde\r\n\r\n-- VARIABLE GLOBALE - SCRIPT --\r\n\r\nwidget_visible = {}\r\nwidget_enable = {}\r\nui_tweens = {}\r\nui_particles = {}\r\nui_listener_load = {}\r\nui_listener_unload = {}\r\nui_listener_event = {}\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\nscreenEffectId = nil\r\n\r\n-- VARIABLE GLOBALE - MOBILE CINEMATIQUE & TUTO --\r\n\r\nANM_otomai = {think=\"AnimComp-Special03\", talk=\"AnimComp-Special04-Debut\", show=\"AnimComp-Special05-Debut\", nice=\"AnimComp-Special07\", nope=\"AnimComp-Special08\", lol=\"AnimComp-Special09\", stop_it=\"AnimComp-Special10\", come_here=\"AnimComp-Special01\", wave_hit=\"AnimComp-Special02\", fly=\"AnimStatique-Oiseau\", cast=\"AnimSort-01\", supercast=\"AnimComp-Special11\", attack=\"AnimSort-Cast\", balance=\"AnimComp-Special06\"}\r\nANM_melee = {attack=\"AnimSort-Morsure\", glitch1=\"AnimComp-Glitch01\", glitch2=\"AnimComp-Glitch02\", glitch3=\"AnimComp-Glitch03\", roar=\"AnimComp-Agressif\"}\r\nANM_range = {attack=\"AnimSort-01\", glitch=\"AnimComp-Glitch\", dupli=\"AnimComp-Dupli\"}\r\nANM_boss = {attack1=\"AnimSort-Estoc\", attack2=\"AnimSort-Hrargh\", glitch=\"AnimComp-Glitch\", dupli=\"AnimComp-Dupli\", roar=\"AnimComp-Hurle\", ko = \"AnimKO-SortieOK\", death= \"AnimKO-SortieHS\"}\r\n\r\nNPC_otomai = Mobile.generateClientMobileId()\r\nNPC_otomai_gfx = 181404009\r\nNPC_otomai_particleZ = 10\r\nNPC_otomai_bubbleX = 10\r\nNPC_otomai_bubbleY = 70\r\n\r\nNPC_melee = Mobile.generateClientMobileId()\r\nNPC_meleeB = Mobile.generateClientMobileId()\r\nNPC_melee_gfx = 181404014\r\nNPC_melee_particleZ = 5\r\n\r\nNPC_range = Mobile.generateClientMobileId()\r\nNPC_range_gfx = 181404015\r\nNPC_range_particleZ = 3\r\n\r\nNPC_boss = Mobile.generateClientMobileId()\r\nNPC_boss_gfx = 181404012\r\nNPC_boss_particleZ = 8\r\n\r\nNPC_eni_wakfu = Mobile.generateClientMobileId()\r\nNPC_eni_wakfu_gfx = 181404034\r\nNPC_eni_wakfu_particleZ = 7\r\n\r\nNPC_eni_stasis = Mobile.generateClientMobileId()\r\nNPC_eni_stasis_gfx = 181404013\r\nNPC_eni_stasis_particleZ = 7\r\n\r\n_ACTOR_LIST = {NPC_otomai, NPC_melee, NPC_meleeB, NPC_range, NPC_boss, NPC_eni_wakfu, NPC_eni_stasis}\r\n\r\n-- VARIABLE GLOBALE - PARTICULE CINEMATIQUE & TUTO --\r\n\r\n-- UI TUTO\r\napsArrowBig = {6001069,6001070,6001071,6001072,6001073,6001074,6001075,6001076}\r\napsArrow = {6001061,6001062,6001063,6001064,6001065,6001066,6001067,6001068}\r\napsCenter = {ap=6001090, mp=6001091, wp=6001092, hp=6001093}\r\napsFollowBorder = -1548037644\r\n-- WORLD TUTO\r\napsCell = {white_border=800578, red_border=800579, white_arrow=800576, red_arrow=800577, white=800581, red=800582, show=78900}\r\n-- CINEMATIQUE\r\napsWave = {spawn=800573, wave=800574, hit=800575}\r\napsOtomai = {shield=-1814057071, transform=-1814057072, playershield = -1814057074}\r\napsCristal = {base=71071022, react=800580, shield=71071021}\r\napsBoss = {death=-1814057073}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n    for index, value in ipairs (tab) do\r\n\t\tif isEqual(value, val) then\r\n            return true\r\n        end\r\n    end\r\n\r\n    return false\t\r\nend\r\n\r\n-- FONCTION UI -- Replace le Chat en bas à gauche et le rend indéplaçable/déplaçable\r\nfunction prepareChatUI(movable, chatOffsetX)\r\n\tif not UI.isDialogLoaded(\"chatDialog0\") then return end\r\n\t\r\n\tif (not chatOffsetX) then chatOffsetX = 0 end\r\n\t\r\n\tUI.setPosition(\"chatDialog0\", chatOffsetX, 0)\r\n\tUI.setWindowMovable(\"chatDialog0\", movable)\r\nend\r\n\r\n-- FONCTION UI -- Replace le Suivi de Quête mi-hauteur à gauche et le rend indéplaçable/déplaçable\r\nfunction prepareFollowQuestUI(movable)\r\n    local dialogName = \"\"\r\n    if UI.isDialogLoaded(\"verticalFollowedAchievementsDialog\") then\r\n        dialogName = \"verticalFollowedAchievementsDialog\"\r\n    end\r\n    if UI.isDialogLoaded(\"followedAchievementsDialog\") then\r\n        dialogName = \"followedAchievementsDialog\"\r\n    end\r\n\r\n    if (dialogName == \"\") then\r\n        return\r\n    end\r\n\r\n    local screenH, screenW = UI.getWindowSize()\r\n    local x, y = UI.getPosition(dialogName)\r\n\r\n    UI.setPosition(dialogName, x, screenH / 4)\r\n    UI.setWindowMovable(dialogName, movable)\r\nend\r\n\r\n-- FONCTION UI -- Rend Visible/Invisible certains éléments des interfaces\r\nfunction prepareUI(visible)\r\n  --Interface Boutique & Cadeau\r\n  setWidgetVisible(\"topHudDialog\", \"optionShopButton\", visible)\r\n  setWidgetVisible(\"topHudDialog\", \"giftButton\", visible)\r\n\r\n  --UI sous le Coeur\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"wakfuStasisBar\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"xpBar\", visible)\r\n\r\n  --Boutons hors combat à droite du Coeur\r\n  setWidgetVisible(\"shortcutBarDialog\", \"previousButton\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"nextButton\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseShortcutBar1\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseShortcutBar2\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseShortcutBar3\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseShortcutBar4\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"shortcutBarItemButton\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"shortcutBarSpellButton\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseButtonContainerForTuto1\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseButtonContainerForTuto2\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseButtonContainerForTuto3\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseButtonContainerForTuto4\", visible)\r\n\r\n  --Boutons hors combat à gauche de l'écran - barre d'interfaces\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"firstInterfaceBarBackground\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"secondInterfaceBarBackground\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"extraInterfaceBarDrawerButton\", visible)\r\n\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"fightInfoBtn\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"inventoryButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"buildSheetSetButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"craftButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"questsButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"dungeonButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"cosmeticsButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"tutorialBookButton\", visible)\r\n\r\n  --Boutons hors combat à gauche de l'écran - barre d'interfaces (deuxième barre)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"contactListButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"guildButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"companionsButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"nationButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"battlegroundButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"passportButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"emoteButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"encyclopediaButton\", visible)\r\n\r\n  --Boutons hors combat \"actions rapides\"\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"OverWorldActionsBackground\", visible)\r\n\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"dimensionalBagButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"mapButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"rideMountButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"miniMapButton\", visible)\r\n\r\n  --Boutons en combat à gauche du Coeur\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"FightActionsBackground\", visible)\r\n\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"giveUpButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"hideFightersButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"tacticalModeBtn\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"reportCellBtn\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"fightMarkerBtn\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"lockFightBtn\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"resistanceOverheadBtn\", visible)\r\nend\r\n\r\n-- FONCTION SHORTCUT -- Rend Actif/Inactif certains raccourcis\r\nfunction prepareShortcuts(enabled, shortcutType)\r\n  if not shortcutType or shortcutType == \"WORLD\" then\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.world\", \"enterLeaveBag\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.world\", \"switchHero0\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.world\", \"switchHero1\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.world\", \"switchHero2\")\r\n  end\r\n  if not shortcutType or shortcutType == \"DISPLAY\" then\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"zoomIn\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"zoomOut\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"closeWindows\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"setLODLevel\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"setFightLODLevel\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"showHideNameOverheadsCommand\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"hideFightOccluders\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"alphaMask\")\r\n  end\r\n  if not shortcutType or shortcutType == \"CHAT\" then\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.chat\", \"chat\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.chat\", \"lastContact\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.chat\", \"firstContact\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.chat\", \"autoCompletePlayerName\")\r\n    for bind=1, 9, 1 do\r\n      UI.setShortcutEnabled(enabled, \"shortcutCategory.shortcutBar\", \"bind\" .. toString(bind))\r\n    end\r\n  end\r\n\r\n  if not shortcutType or shortcutType == \"FIGHT\" then\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"fighterTransparency\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"switchTacticalView\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"nextSelectedFighter\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"giveUp\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"lockFight\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"reportCell\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"callHelp\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"displayHpBar\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"resetFightCamera\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"endPlacementAndTurn\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"closeCombatRight\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"closeCombatLeft\")\r\n  end\r\n  if not shortcutType or shortcutType == \"INTERFACE\" then\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"minimap\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"contactList\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"companionManagement\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"guild\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"craft\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"dungeonList\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"achievements\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"quests\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"emotes\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"ecosystem\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"climate\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"nation\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"partySearch\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"passport\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"almanax\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"tutorialBook\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"switchToDirectAttackCommand\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"map\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"spellsInventory\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"inventory\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"characterBook\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"osamodasSymbiot\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"shortcutBar0\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"shortcutBar1\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"shortcutBar2\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"shortcutBar3\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"additionalShortcutBar0\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"additionalShortcutBar1\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"additionalShortcutBar2\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"additionalShortcutBar3\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"changeShortcutBarType\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"downscaling\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"rewards\")\r\n\tUI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"battlegroundList\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"aptitudes\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"presets\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"encyclopedia\")\r\n  end\r\n\r\n  -- On ne bloque pas les raccourcis de sorts finalement\r\n--   if not shortcutType or shortcutType == \"SHORTCUTBAR\" then\r\n--     for bar=0,3, 1 do\r\n--       for slot=0, 9, 1 do\r\n--         UI.setShortcutEnabled(enabled, \"shortcutCategory.shortcutBar\", \"shortcut\" .. toString(bar) .. toString(slot))\r\n--       end\r\n--     end\r\n--   end\r\nend\r\n\r\n-- FONCTION UI -- Rend Visible/Invisible un élément d'une interface\r\nfunction setWidgetVisible(dialogName, widgetName, visible)\r\n  if not UI.isDialogLoaded(dialogName) then return end\r\n\r\n  UI.setWidgetVisibility(dialogName, widgetName, visible)\r\n  table.insert(widget_visible, { name = dialogName, id = widgetName, state = visible })\r\nend\r\n\r\nfunction clearWidgetVisible()\r\n  local str = \"\"\r\n  for i=#widget_visible, 1, -1 do\r\n    str = str .. toString(widget_visible[i].name) .. \"@\" .. toString(widget_visible[i].id) .. \";\"\r\n    UI.setWidgetVisibility(widget_visible[i].name, widget_visible[i].id, true)\r\n  end\r\n\r\n  widget_visible = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearWidgetVisible\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Rend Actif/Inactif un élément d'une interface\r\nfunction setWidgetEnable(dialogName, widgetName, enable)\r\n  if not UI.isDialogLoaded(dialogName) then return end\r\n\r\n  UI.setWidgetEnabled(dialogName, widgetName, enable)\r\n  table.insert(widget_enable, {name = dialogName, id = widgetName, state = enable})\r\nend\r\n\r\nfunction clearWidgetEnable()\r\n  local str = \"\"\r\n  for i=#widget_enable, 1, -1 do\r\n    str = str .. toString(widget_enable[i].name) .. \"@\" .. toString(widget_enable[i].id) .. \";\"\r\n    UI.setWidgetEnabled(widget_enable[i].name, widget_enable[i].id, true)\r\n  end\r\n\r\n  widget_enable = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearWidgetEnable\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Ajoute/Retire une TweenParticle à un élément d'une interface\r\nfunction setUIColorTween(dialogName, widgetName, duration, loop, r1, g1, b1, a1, r2, g2, b2, a2)\r\n  if not UI.isDialogLoaded(dialogName) then return end\r\n\r\n  UI.addColorTween(dialogName, widgetName, duration, loop, r1, g1, b1, a1, r2, g2, b2, a2)\r\n  table.insert(ui_tweens, {name = dialogName, id = widgetName})\r\nend\r\n\r\nfunction clearUIColorTweens(dialogName, widgetName)\r\n  local str = \"\"\r\n  for i=#ui_tweens, 1, -1 do\r\n    if ((not dialogName) or (dialogName == ui_tweens[i].name)) and ((not widgetName) or (widgetName == ui_tweens[i].id)) then\r\n      str = str .. toString(ui_tweens[i].name) .. \"@\" .. toString(ui_tweens[i].id) .. \";\"\r\n      UI.removeColorTween(ui_tweens[i].name, ui_tweens[i].id)\r\n      table.remove(ui_tweens, i)\r\n    end\r\n  end\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearUIColorTweens\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Ajoute/Retire une Particle à un élément d'une interface\r\nfunction setUIParticle(dialogName, widgetName, apsFileName, x, y, alignment, level)\r\n  if not UI.isDialogLoaded(dialogName) then return end\r\n\r\n  local particleId = UI.addParticle(dialogName, widgetName, apsFileName, x, y, alignment, level)\r\n  table.insert(ui_particles, {name = dialogName, id = widgetName})\r\n\r\n  return particleId\r\nend\r\n\r\nfunction setUIParticleBorder(dialogName, widgetName, apsFileName, x, y, alignment, level, speed)\r\n  if not UI.isDialogLoaded(dialogName) then return end\r\n\r\n  local particleId = UI.addParticleToBorder(dialogName, widgetName, apsFileName, x, y, alignment, level, speed)\r\n  table.insert(ui_particles, {name = dialogName, id = widgetName})\r\n\r\n  return particleId\r\nend\r\n\r\nfunction clearUIParticles(dialogName, widgetName)\r\n  local str = \"\"\r\n  for i=#ui_particles, 1, -1 do\r\n    if ((not dialogName) or (dialogName == ui_particles[i].name)) and ((not widgetName) or (widgetName == ui_particles[i].id)) then\r\n      str = str .. toString(ui_particles[i].name) .. \"@\" .. toString(ui_particles[i].id) .. \";\"\r\n      UI.clearParticles(ui_particles[i].name, ui_particles[i].id)\r\n      table.remove(ui_particles, i)\r\n    end\r\n  end\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearUIParticles\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Enregistre/Supprime un callback à l'ouverture d'une interface\r\nfunction addDialogLoadListener(dialog, funcName, ...)\r\n  UI.addDialogLoadedListener(dialog, funcName, unpack(arg))\r\n  table.insert(ui_listener_load,  dialog)\r\nend\r\n\r\nfunction clearDialogLoadListener(dialogName)\r\n  local str = \"\"\r\n  for i=#ui_listener_load, 1, -1 do\r\n    if (not dialogName) or (dialogName == ui_listener_load[i]) then\r\n      str = str .. toString(ui_listener_load[i]) .. \";\"\r\n      UI.removeDialogLoadedListener(ui_listener_load[i])\r\n      table.remove(ui_listener_load, i)\r\n    end\r\n  end\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearDialogLoadListener\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Enregistre/Supprime un callback à la fermeture d'une interface\r\nfunction addDialogUnloadListener(dialog, funcName, ...)\r\n  UI.addDialogUnloadedListener(dialog, funcName, unpack(arg))\r\n  table.insert(ui_listener_unload, dialog)\r\nend\r\n\r\nfunction clearDialogUnloadListener(dialogName)\r\n  local str = \"\"\r\n  for i=#ui_listener_unload, 1, -1 do\r\n    if (not dialogName) or (dialogName == ui_listener_unload[i]) then\r\n      str = str .. toString(ui_listener_unload[i]) .. \";\"\r\n      UI.removeDialogUnloadedListener(ui_listener_unload[i])\r\n      table.remove(ui_listener_unload, i)\r\n    end\r\n  end\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearDialogUnloadListener\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Enregistre/Supprime un callback sur un élément d'une interface\r\nfunction addDialogEventListener(dialog, id, eventType, funcName, ...)\r\n  if not UI.isDialogLoaded(dialog) then return end\r\n\r\n  UI.addEventListener(dialog, id, eventType, funcName, unpack(arg))\r\n  table.insert(ui_listener_event, {dialog=dialog, id=id, eventType=eventType, funcName=funcName})\r\nend\r\n\r\nfunction clearDialogEventListener(dialogName)\r\n  local str = \"\"\r\n  for i=#ui_listener_event, 1, -1 do\r\n    if (not dialogName) or (dialogName == ui_listener_event[i].dialog) then\r\n      str = str .. toString(ui_listener_event[i].dialog) .. \"@\" .. toString(ui_listener_event[i].id) .. \";\"\r\n      UI.removeEventListener(ui_listener_event[i].dialog, ui_listener_event[i].id, ui_listener_event[i].eventType, ui_listener_event[i].funcName)\r\n      table.remove(ui_listener_event, i)\r\n    end\r\n  end\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearDialogEventListener\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y , z, ...)\r\n  local particleId = Particle.addParticleSystem(particleFileId, x, y , z, unpack(arg))\r\n  table.insert(world_particles, particleId)\r\n\r\n  return particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n  local particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n  table.insert(world_particles, particleId)\r\n\r\n  return particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n  local str = \"\"\r\n  for i=#world_particles, 1, -1 do\r\n    str = str .. toString(world_particles[i]) .. \";\"\r\n    Particle.removeParticleSystem(world_particles[i])\r\n  end\r\n\r\n  world_particles = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n  BubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n  if isLower(mobileId, 0) then\r\n    BubbleText.setCharacterSpeak(mobileId, text)\r\n  else\r\n    if (not offsetY) then\r\n      local height = Mobile.getMobileHeight(mobileId)\r\n      if (not height) then height = 6 end\r\n\r\n      offsetY = height * 10\r\n    end\r\n\r\n    if (not offsetX) then offsetX = 0 end\r\n    if (not infiniteDuration) then infiniteDuration = false end\r\n\r\n    BubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n    UI.writeLocalisedInChat(text)\r\n  end\r\n\r\n  if (not tContains(bubbles, mobileId)) then\r\n    table.insert(bubbles, mobileId)\r\n  end\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n  local str = \"\"\r\n  for i = #bubbles, 1, -1 do\r\n    if (not mobileId) then\r\n      str = str .. toString(bubbles[i]) .. \";\"\r\n      BubbleText.closeBubbleAttachedTo(bubbles[i])\r\n    elseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n      str = str .. toString(bubbles[i]) .. \";\"\r\n      BubbleText.closeBubbleAttachedTo(bubbles[i])\r\n      table.remove(bubbles, i)\r\n    end\r\n  end\r\n\r\n  if (not mobileId) then bubbles = {} end\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n  local compassId = UI.addCompass(\"compass\", x, y, z)\r\n  table.insert(compasses, compassId)\r\n\r\n  return compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n  local str = \"\"\r\n  for i=#compasses, 1, -1 do\r\n    str = str .. toString(compasses[i]) .. \";\"\r\n    UI.removeCompass(compasses[i])\r\n  end\r\n\r\n  compasses = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height)\r\n  local mobileId = Mobile.generateClientMobileId()\r\n  Actor.createActor(mobileId, spriteName, worldX, worldY, worldZ, availableDirection)\r\n\r\n  if (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n  if (height) then Actor.setActorHeight(mobileId, height) end\r\n\r\n  table.insert(actors, mobileId)\r\n\r\n  return mobileId\r\nend\r\n\r\nfunction clearActors()\r\n  local str = \"\"\r\n  for i = #actors, 1, -1 do\r\n    str = str .. toString(actors[i]) .. \";\"\r\n    Actor.deleteActor(actors[i])\r\n  end\r\n\r\n  actors = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n  local taskId = invoke(delay, count, funcName, unpack(arg))\r\n  table.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n  local str = \"\"\r\n  for i=#invoke_tasks, 1, -1 do\r\n    str = str .. toString(invoke_tasks[i]) .. \";\"\r\n    interrupt(invoke_tasks[i])\r\n    desinvoke(invoke_tasks[i])\r\n  end\r\n\r\n  invoke_tasks = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n  invoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n  local taskId = setInterval(delay, funcName, unpack(arg))\r\n  table.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n  local str = \"\"\r\n  for i=#interval_tasks, 1, -1 do\r\n    str = str .. toString(interval_tasks[i]) .. \";\"\r\n    interrupt(interval_tasks[i])\r\n    desinvoke(interval_tasks[i])\r\n  end\r\n\r\n  interval_tasks = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n  if (_DEBUG) then trace(\"startCinematicContext\") end\r\n\r\n  UI.manageFrame(\"World\", false)\r\n  UI.closeMRU()\r\n  UI.closeAllBags()\r\n  UI.setUIVisible(false)\r\n  UI.displayWideScreenBand(true)\r\n  Camera.setUserZoomLocked(true)\r\n\r\n  if (cameraMobileId ~= nil)  then\r\n    Camera.setMoveSpeedFactor(10000)\r\n    Camera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n  end\r\n\r\n  if (zoomFactor ~= nil)  then\r\n    Camera.setZoomFactor(zoomFactor)\r\n  end\r\n\r\n  if (musicId ~= nil)  then\r\n    Sound.playForcedMusic(musicId)\r\n  end\r\n\r\n  if (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\nfunction skipCinematic()\r\n  local player = Context.getLeaderId()\r\n\r\n  for x = 1, #_ACTOR_LIST do\r\n    Actor.deleteActor(_ACTOR_LIST[x])\r\n  end\r\n\r\n  UI.hideButton()\r\n  clearALL()\r\n  stopCinematicContext(1, player, true)\r\n  Mobile.setMobileVisible(player, true)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n  if (_DEBUG) then trace(\"stopCinematicContext\") end\r\n\r\n  UI.displayWideScreenBand(false)\r\n  UI.setUIVisible(true)\r\n  Camera.setUserZoomLocked(false)\r\n  UI.manageFrame(\"World\", true)\r\n\r\n  Camera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n  Camera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n  if (zoomFactor ~= nil) then\r\n    Camera.setZoomFactor(zoomFactor)\r\n  end\r\n\r\n  if (cameraMobileId ~= nil) then\r\n    Camera.attachCameraToMobile(cameraMobileId)\r\n  end\r\n\r\n  if (stopMusic) then\r\n    Sound.stopForcedMusic()\r\n  end\r\n\r\n  if (_DEBUG) then\r\n    UI.hideButton()\r\n  end\r\n\r\n  --TRIGGER\r\n  Server.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Affiche/Masque une texture à l'écran\r\nfunction displayScreenEffect(enable, fadeInDur, alphaDur, fadeOutDur, r, g, b, alpha)\r\n  if (_DEBUG) then trace(\"displayScreenEffect\") end\r\n\r\n  if not enable and screenEffectId ~= nil  then\r\n    --On retire le blackScreen\r\n    Effect.stopEffect(screenEffectId)\r\n  else\r\n    --On affiche un blackScreen à l'entrée dans l'instance le temps qu'elle soit complètement chargée\r\n    screenEffectId = Effect.createFullScreenSprite(fadeInDur, alphaDur, fadeOutDur, r, g, b, alpha)\r\n  end\r\nend\r\n\r\n-- FONCTION NETTOYAGE --\r\nfunction clearALL()\r\n  clearIntervalTasks()\r\n  clearInvokeTasks()\r\n  clearBubbles()\r\n  clearUIColorTweens()\r\n  clearUIParticles()\r\n  clearWorldParticles()\r\n  clearCompasses()\r\n  clearActors()\r\n\r\n  Focus.display(false)\r\n  UI.unloadTutorialDialog()\r\nend\r\n\r\n-- FONCTION NETTOYAGE --\r\nfunction clearUI(dialogName)\r\n  clearUIColorTweens(dialogName)\r\n  clearUIParticles(dialogName)\r\nend\r\n\r\n-- FONCTION NETTOYAGE --\r\nfunction clearListener(dialogName)\r\n  clearDialogLoadListener(dialogName)\r\n  clearDialogUnloadListener(dialogName)\r\n  clearDialogEventListener(dialogName)\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\nfunction onInstanceLoaded()\r\n    if (_DEBUG) then\r\n        trace(\"ON INSTANCE LOADED\")\r\n    end\r\n\r\n    UI.manageFrame(\"World\", true)\r\n    UI.setUIVisible(true)\r\n    displayScreenEffect(false)\r\n\r\n    -- TRIGGER\r\n    Server.triggerEvent(24142)\r\nend\r\n\r\nfunction displayDoor(dungeon)\r\n    local dungeon = toLong(dungeon)\r\n    local first_particule = 801117\r\n    local second_particule = 800867\r\n    local third_particule = 801119\r\n    local forth_particule = 801118\r\n    local fifth_particule = 801116\r\n\r\n    if (doorAps ~= nil) then\r\n       Particle.removeParticleSystem(doorAps)\r\n    end\r\n\r\n    if (dungeon == 1) then\r\n       doorAps = Particle.addParticleSystem(first_particule, 1, 1, -1)\r\n    end\r\n\r\n    if (dungeon == 2) then\r\n       doorAps = Particle.addParticleSystem(second_particule, 1, 1, -1)\r\n    end\r\n\r\n    if (dungeon == 3) then\r\n       doorAps = Particle.addParticleSystem(third_particule, 1, 1, -1)\r\n    end\r\n\r\n    if (dungeon == 4) then\r\n       doorAps = Particle.addParticleSystem(forth_particule, 1, 1, -1)\r\n    end\r\n\r\n    if (dungeon == 5) then\r\n       doorAps = Particle.addParticleSystem(fifth_particule, 1, 1, -1)\r\n    end\r\nend\n\n-- [INIT] Variables\n-- \nfunction event_2722_24195()\n    \nend\n\n-- ENTER_INSTANCE - Inscription au scénario + génération PNJ décor\n-- \nfunction event_2722_24193(dungeon)\n    local troolA = Mobile.generateClientMobileId()\r\n    local troolB = Mobile.generateClientMobileId()\r\n    local troolC = Mobile.generateClientMobileId()\r\n    local troolD = Mobile.generateClientMobileId()\r\n    local troolE = Mobile.generateClientMobileId()\r\n    local troolF = Mobile.generateClientMobileId()\r\n    local troolG = Mobile.generateClientMobileId()\r\n    local troolH = Mobile.generateClientMobileId()\r\n    local pnjA = Mobile.generateClientMobileId()\r\n    local pnjB = Mobile.generateClientMobileId()\r\n    local pnjC = Mobile.generateClientMobileId()\r\n    local pnjD = Mobile.generateClientMobileId()\r\n    local pnjE = Mobile.generateClientMobileId()\r\n    local pnjF = Mobile.generateClientMobileId()\r\n    \r\n    local dungeon = toLong(dungeon)\r\n    \r\n    Actor.createActor(pnjA, 1020, 2, -9, 10, 4)\r\n    Mobile.setMobileDirection(pnjA, 3)\r\n    \r\n    Actor.createActor(pnjB, 1029, -7, 3, 3, 4)\r\n    Mobile.setMobileDirection(pnjB, 1)\r\n    \r\n    Actor.createActor(pnjC, 1030, 10, 4, 3, 4)\r\n    Mobile.setMobileDirection(pnjC, 5)\r\n    \r\n    Actor.createActor(pnjD, 70, 10, 5, 3, 4)\r\n    Mobile.setMobileDirection(pnjD, 5)\r\n    Actor.equip(pnjD, \"210800101\", \"VETEMENTCUSTOM\")\r\n    Actor.equip(pnjD, \"200800009\", \"CHEVEUXCUSTOM\")\r\n    Mobile.setPartColor(pnjD, \"Pupille\", 0.00, 0.00, 0.00, 1)\r\n    Mobile.setPartColor(pnjD, \"Peau\", 0.96, 0.72, 0.48, 1)\r\n    Mobile.setPartColor(pnjD, \"Cheveux\", 0.88, 0.40, 0.20, 1)\r\n    Mobile.setPartColor(pnjD, \"ColorCostume1\", 0.10, 0.09, 0.05, 1)\r\n    Mobile.setPartColor(pnjD, \"ColorCostume2\", 0.39, 0.46, 0.39, 1)\r\n    Mobile.setPartColor(pnjD, \"ColorCostume3\", 0.53, 0.06, 0.06, 1)\r\n    Mobile.setPartColor(pnjD, \"ColorCostume4\", 0.76, 0.72, 0.60, 1)\r\n    Mobile.setPartColor(pnjD, \"ColorCostume5\", 0.22, 0.20, 0.11, 1)\r\n    Mobile.setPartColor(pnjD, \"ColorCostume6\", 0.53, 0.06, 0.06, 1)\r\n    Mobile.setMobileAnimation(pnjD, \"AnimEmote-EncouragerFan-Boucle\")\r\n    \r\n    Actor.createActor(pnjE, 11, -10, 6, 9, 4)\r\n    Mobile.setMobileDirection(pnjE, 1)\r\n    Actor.equip(pnjE, \"210110101\", \"VETEMENTCUSTOM\")\r\n    Actor.equip(pnjE, \"200110011\", \"CHEVEUXCUSTOM\")\r\n    Mobile.setPartColor(pnjE, \"Pupille\", 0.50, 0.30, 0.10, 1)\r\n    Mobile.setPartColor(pnjE, \"Peau\", 0.96, 0.88, 0.68, 1)\r\n    Mobile.setPartColor(pnjE, \"Cheveux\", 0.20, 0.70, 0.95, 1)\r\n    Mobile.setPartColor(pnjE, \"ColorCostume1\", 0.30, 0.49, 0.05, 1)\r\n    Mobile.setPartColor(pnjE, \"ColorCostume2\", 0.05, 0.15, 0.05, 1)\r\n    Mobile.setPartColor(pnjE, \"ColorCostume3\", 0.53, 0.06, 0.06, 1)\r\n    Mobile.setPartColor(pnjE, \"ColorCostume4\", 0.76, 0.72, 0.60, 1)\r\n    Mobile.setPartColor(pnjE, \"ColorCostume5\", 0.22, 0.20, 0.11, 1)\r\n    Mobile.setPartColor(pnjE, \"ColorCostume6\", 0.53, 0.06, 0.06, 1)\r\n    Mobile.setMobileAnimation(pnjE, \"AnimAssisPosing-Banc-Debut-Assis\")\r\n    \r\n    Actor.createActor(pnjF, 151, -10, 0, 9, 4)\r\n    Mobile.setMobileDirection(pnjF, 1)\r\n    Actor.equip(pnjF, \"211510001\", \"VETEMENTCUSTOM\")\r\n    Actor.equip(pnjF, \"201510001\", \"CHEVEUXCUSTOM\")\r\n    Mobile.setPartColor(pnjF, \"Pupille\", 0.10, 0.30, 0.50, 1)\r\n    Mobile.setPartColor(pnjF, \"Peau\", 0.88, 0.88, 0.68, 1)\r\n    Mobile.setPartColor(pnjF, \"Cheveux\", 0.70, 0.50, 0.15, 1)\r\n    Mobile.setPartColor(pnjF, \"ColorCostume1\", 0.60, 0.49, 0.80, 1)\r\n    Mobile.setPartColor(pnjF, \"ColorCostume2\", 0.05, 0.15, 0.05, 1)\r\n    Mobile.setPartColor(pnjF, \"ColorCostume3\", 0.06, 0.06, 0.56, 1)\r\n    Mobile.setPartColor(pnjF, \"ColorCostume4\", 0.76, 0.72, 0.60, 1)\r\n    Mobile.setPartColor(pnjF, \"ColorCostume5\", 0.22, 0.20, 0.11, 1)\r\n    Mobile.setPartColor(pnjF, \"ColorCostume6\", 0.53, 0.06, 0.06, 1)\r\n    Mobile.setMobileAnimation(pnjF, \"AnimAssisPosing-Banc-Debut-Assis\")\r\n    \r\n    function initTrool(mobileId, x, y, z, direction, skina, skinb, skinc, haira, hairb, hairc, gfx)\r\n        Actor.createActor(mobileId, gfx, x, y, z, 4)\r\n        Mobile.setMobileDirection(mobileId, direction)\r\n        Mobile.setPartColor(mobileId, \"Peau\", skina, skinb, skinc, 1)\r\n        Mobile.setPartColor(mobileId, \"Cheveux\", haira, hairb, hairc, 1)\r\n        Mobile.setPartColor(mobileId, \"Pupille\", haira, hairb, hairc, 1)\r\n        Mobile.setMobileAnimation(mobileId, \"AnimStatique-Gradin\")\r\n    end\r\n    \r\n    initTrool(troolA, -7, 1, 3, 1, 0.70, 0.62, 0.40, 0.45, 1.00, 0.76, 133501898)\r\n    initTrool(troolB, -7, -3, 3, 1, 0.50, 0.34, 0.24, 0.45, 0.00, 0.76, 133501897)\r\n    initTrool(troolC, -7, -7, 3, 1, 0.81, 0.76, 0.66, 0.45, 0.50, 0.00, 133501898)\r\n    initTrool(troolD, -9, -4, 8, 1, 0.90, 0.67, 0.56, 0.45, 0.40, 0.25, 133501896)\r\n    initTrool(troolE, 0, -9, 10, 3, 0.70, 0.51, 0.02, 0.88, 0.12, 0.40, 133501897)\r\n    initTrool(troolF, -7, -5, 3, 1, 0.95, 0.84, 0.72, 0.40, 0.88, 0.12, 133501896)\r\n    initTrool(troolG, -9, 2, 8, 1, 0.46, 0.32, 0.09, 0.12, 0.40, 0.88, 133501897)\r\n    initTrool(troolH, -9, -8, 8, 1, 0.80, 0.71, 0.60, 0.30, 0.30, 0.36, 133501896)\r\n    \r\n    displayDoor(dungeon)\nend\n\n-- DIALOG_EXECUTED - Apparition donjon 01 - Cire Momore\n-- \nfunction event_2722_24194(dungeon)\n    displayDoor(dungeon)\nend\n\n-- DIALOG_EXECUTED - Apparition donjon 02 - Rushu\n-- \nfunction event_2722_24196(dungeon)\n    displayDoor(dungeon)\nend\n\n-- DIALOG_EXECUTED - Apparition donjon 03 - Toross\n-- \nfunction event_2722_24197(dungeon)\n    displayDoor(dungeon)\nend\n\n-- DIALOG_EXECUTED - Apparition donjon 04 - Horlogers\n-- \nfunction event_2722_24198(dungeon)\n    displayDoor(dungeon)\nend\n\n-- DIALOG_EXECUTED - Apparition donjon 05 - Thalos-Kyarrelmne\n-- \nfunction event_2722_24199(dungeon)\n    displayDoor(dungeon)\nend\n\n-- On réaffiche les particules du portail pour les personnages qui arrivent après\n-- \nfunction event_2722_24208(dungeon)\n    invoke(500, 1, \"displayDoor\", dungeon)\nend\n\n","functions":["tContains","prepareChatUI","prepareFollowQuestUI","prepareUI","prepareShortcuts","setWidgetVisible","clearWidgetVisible","setWidgetEnable","clearWidgetEnable","setUIColorTween","clearUIColorTweens","setUIParticle","setUIParticleBorder","clearUIParticles","addDialogLoadListener","clearDialogLoadListener","addDialogUnloadListener","clearDialogUnloadListener","addDialogEventListener","clearDialogEventListener","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","bubble","clearBubbles","setCompass","clearCompasses","createActor","clearActors","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","startCinematicContext","skipCinematic","stopCinematicContext","displayScreenEffect","clearALL","clearUI","clearListener","fullScreen","text","onInstanceLoaded","displayDoor","event_2722_24195","event_2722_24193","initTrool","event_2722_24194","event_2722_24196","event_2722_24197","event_2722_24198","event_2722_24199","event_2722_24208"],"quest_calls":[],"dialogue_calls":[]},"scenario/2723.lua":{"source":"\n\n-- [INIT] Active les IE liés à l'Event\n-- Les IE doivent être initialement non utilisable pour que ce soit cohérent\nfunction event_2723_24211()\n    \nend\n\n-- [INIT] Initialise les Monstres NPC liés à l'Event\n-- Les Groupes doivent être initialement non spawn\nfunction event_2723_24212()\n    \nend\n\n","functions":["event_2723_24211","event_2723_24212"],"quest_calls":[],"dialogue_calls":[]},"scenario/2724.lua":{"source":"\n\n-- [INIT] Désactive les IE liés à l'Event\n-- Les IE doivent être initialement non utilisable pour que ce soit cohérent\nfunction event_2724_24213()\n    \nend\n\n-- [INIT] Despawn les Monstres NPC liés à l'Event\n-- Les Groupes doivent être initialement non spawn\nfunction event_2724_24214()\n    \nend\n\n-- [INIT] Despawn les Monstres Cyclique liés à l'Event\n-- \nfunction event_2724_24215()\n    \nend\n\n","functions":["event_2724_24213","event_2724_24214","event_2724_24215"],"quest_calls":[],"dialogue_calls":[]},"scenario/2725.lua":{"source":"\n\n-- Enregistrement des Evènements : Début\n-- \nfunction event_2725_24216()\n    \nend\n\n-- Enregistrement des Evènements : Fin\n-- \nfunction event_2725_24217()\n    \nend\n\n","functions":["event_2725_24216","event_2725_24217"],"quest_calls":[],"dialogue_calls":[]},"scenario/2726.lua":{"source":"\n\n-- [INIT] Active les IE liés à l'Event\n-- Les IE doivent être initialement non utilisable pour que ce soit cohérent\nfunction event_2726_24218()\n    \nend\n\n-- [INIT] Initialise les Monstres NPC liés à l'Event\n-- Les Groupes doivent être initialement non spawn\nfunction event_2726_24219()\n    \nend\n\n","functions":["event_2726_24218","event_2726_24219"],"quest_calls":[],"dialogue_calls":[]},"scenario/2727.lua":{"source":"\n\n-- [INIT] Désactive les IE liés à l'Event\n-- Les IE doivent être initialement non utilisable pour que ce soit cohérent\nfunction event_2727_24220()\n    \nend\n\n-- [INIT] Despawn les Monstres NPC liés à l'Event\n-- Les Groupes doivent être initialement non spawn\nfunction event_2727_24221()\n    \nend\n\n-- [INIT] Despawn les Monstres Cyclique liés à l'Event\n-- \nfunction event_2727_24222()\n    \nend\n\n","functions":["event_2727_24220","event_2727_24221","event_2727_24222"],"quest_calls":[],"dialogue_calls":[]},"scenario/2728.lua":{"source":"\n\n-- Enregistrement des Evènements : Début\n-- \nfunction event_2728_24223()\n    \nend\n\n-- Enregistrement des Evènements : Fin\n-- \nfunction event_2728_24224()\n    \nend\n\n","functions":["event_2728_24223","event_2728_24224"],"quest_calls":[],"dialogue_calls":[]},"scenario/2729.lua":{"source":"\n\n-- [INIT] Active les IE liés à l'Event\n-- Les IE doivent être initialement non utilisable pour que ce soit cohérent\nfunction event_2729_24225()\n    \nend\n\n-- [INIT] Initialise les Monstres NPC liés à l'Event\n-- Les Groupes doivent être initialement non spawn\nfunction event_2729_24226()\n    \nend\n\n","functions":["event_2729_24225","event_2729_24226"],"quest_calls":[],"dialogue_calls":[]},"scenario/2730.lua":{"source":"\n\n-- [INIT] Désactive les IE liés à l'Event\n-- Les IE doivent être initialement non utilisable pour que ce soit cohérent\nfunction event_2730_24227()\n    \nend\n\n-- [INIT] Despawn les Monstres NPC liés à l'Event\n-- Les Groupes doivent être initialement non spawn\nfunction event_2730_24228()\n    \nend\n\n-- [INIT] Despawn les Monstres Cyclique liés à l'Event\n-- \nfunction event_2730_24229()\n    \nend\n\n","functions":["event_2730_24227","event_2730_24228","event_2730_24229"],"quest_calls":[],"dialogue_calls":[]},"scenario/2731.lua":{"source":"\n\n-- Enregistrement des Evènements : Début\n-- \nfunction event_2731_24230()\n    \nend\n\n-- Enregistrement des Evènements : Fin\n-- \nfunction event_2731_24231()\n    \nend\n\n","functions":["event_2731_24230","event_2731_24231"],"quest_c