\n-- Toutes les X min, on spawn les groupes de monstres\nfunction event_2748_24411()\n    \nend\n\n","functions":["event_2748_24372","event_2748_24373","event_2748_24411"],"quest_calls":[],"dialogue_calls":[]},"scenario/2749.lua":{"source":"\n\n-- [INIT] Active les IE liés à l'Event\n-- Les IE doivent être initialement non utilisable pour que ce soit cohérent\nfunction event_2749_24374()\n    \nend\n\n","functions":["event_2749_24374"],"quest_calls":[],"dialogue_calls":[]},"scenario/2750.lua":{"source":"\n\n-- [INIT] Désactive les IE liés à l'Event\n-- Les IE doivent être initialement non utilisable pour que ce soit cohérent\nfunction event_2750_24375()\n    \nend\n\n","functions":["event_2750_24375"],"quest_calls":[],"dialogue_calls":[]},"scenario/2751.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n-- TRIGGER CLIENT --\r\n-- 0 = Fin cinématique VIDEO | Déclenché par le callback Video.addVideoStopOrEndCallback\r\n-- 1 = Arrivée dans l'instance | Déclenché par onInstanceLoaded() callback par Event.runOnInstanceLoaded (cf code Global)\r\n-- 2 = Fin cinématique | Déclenché par stopCinematicContext() (cf code Global)\r\n-- 3 = Fermeture UI Fin de combat\r\n-- 4 = Clic sur le bon bouton de changement d'oriention (parmis les 4) dans UI worldAndFightBar pour s'orientation vers le monstre\r\n-- 5 = Fermeture UI Fiche combattant\r\n-- 6 = Clic sur le bouton de validation de la répartition dans UI Aptitudes\r\n-- 7 = Clic sur la boussole du bon objectif dans l'UI suivi de quête\r\n-- 8 = Fermeture UI Map Monde\r\n\r\n-- VARIABLE GLOBALE - SCRIPT --\r\n\r\nwidget_visible = {}\r\nwidget_enable = {}\r\nui_tweens = {}\r\nui_particles = {}\r\nui_listener_load = {}\r\nui_listener_unload = {}\r\nui_listener_event = {}\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\nscreenEffectId = nil\r\n\r\n-- VARIABLE GLOBALE - MOBILE CINEMATIQUE & TUTO --\r\n\r\nANM_otomai = {think=\"AnimComp-Special03\", talk=\"AnimComp-Special04-Debut\", show=\"AnimComp-Special05-Debut\", nice=\"AnimComp-Special07\", nope=\"AnimComp-Special08\", lol=\"AnimComp-Special09\", stop_it=\"AnimComp-Special10\", come_here=\"AnimComp-Special01\", wave_hit=\"AnimComp-Special02\", fly=\"AnimStatique-Oiseau\", cast=\"AnimSort-01\", supercast=\"AnimComp-Special11\", attack=\"AnimSort-Cast\", balance=\"AnimComp-Special06\"}\r\nANM_melee = {attack=\"AnimSort-Morsure\", glitch1=\"AnimComp-Glitch01\", glitch2=\"AnimComp-Glitch02\", glitch3=\"AnimComp-Glitch03\", roar=\"AnimComp-Agressif\"}\r\nANM_range = {attack=\"AnimSort-01\", glitch=\"AnimComp-Glitch\", dupli=\"AnimComp-Dupli\"}\r\nANM_boss = {attack1=\"AnimSort-Estoc\", attack2=\"AnimSort-Hrargh\", glitch=\"AnimComp-Glitch\", dupli=\"AnimComp-Dupli\", roar=\"AnimComp-Hurle\", ko = \"AnimKO-SortieOK\", death= \"AnimKO-SortieHS\"}\r\n\r\nNPC_otomai = Mobile.generateClientMobileId()\r\nNPC_otomai_gfx = 181404009\r\nNPC_otomai_particleZ = 10\r\nNPC_otomai_bubbleX = 10\r\nNPC_otomai_bubbleY = 70\r\n\r\nNPC_melee = Mobile.generateClientMobileId()\r\nNPC_meleeB = Mobile.generateClientMobileId()\r\nNPC_melee_gfx = 181404014\r\nNPC_melee_particleZ = 5\r\n\r\nNPC_range = Mobile.generateClientMobileId()\r\nNPC_range_gfx = 181404015\r\nNPC_range_particleZ = 3\r\n\r\nNPC_boss = Mobile.generateClientMobileId()\r\nNPC_boss_gfx = 181404012\r\nNPC_boss_particleZ = 8\r\n\r\nNPC_eni_wakfu = Mobile.generateClientMobileId()\r\nNPC_eni_wakfu_gfx = 181404034\r\nNPC_eni_wakfu_particleZ = 7\r\n\r\nNPC_eni_stasis = Mobile.generateClientMobileId()\r\nNPC_eni_stasis_gfx = 181404013\r\nNPC_eni_stasis_particleZ = 7\r\n\r\n_ACTOR_LIST = {NPC_otomai, NPC_melee, NPC_meleeB, NPC_range, NPC_boss, NPC_eni_wakfu, NPC_eni_stasis}\r\n\r\n-- VARIABLE GLOBALE - PARTICULE CINEMATIQUE & TUTO --\r\n\r\n-- UI TUTO\r\napsArrowBig = {6001069,6001070,6001071,6001072,6001073,6001074,6001075,6001076}\r\napsArrow = {6001061,6001062,6001063,6001064,6001065,6001066,6001067,6001068}\r\napsCenter = {ap=6001090, mp=6001091, wp=6001092, hp=6001093}\r\napsFollowBorder = -1548037644\r\n-- WORLD TUTO\r\napsCell = {white_border=800578, red_border=800579, white_arrow=800576, red_arrow=800577, white=800581, red=800582, show=78900}\r\n-- CINEMATIQUE\r\napsWave = {spawn=800573, wave=800574, hit=800575}\r\napsOtomai = {shield=-1814057071, transform=-1814057072, playershield = -1814057074}\r\napsCristal = {base=71071022, react=800580, shield=71071021}\r\napsBoss = {death=-1814057073}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n    for index, value in ipairs (tab) do\r\n\t\tif isEqual(value, val) then\r\n            return true\r\n        end\r\n    end\r\n\r\n    return false\t\r\nend\r\n\r\n-- FONCTION UI -- Replace le Chat en bas à gauche et le rend indéplaçable/déplaçable\r\nfunction prepareChatUI(movable, chatOffsetX)\r\n\tif not UI.isDialogLoaded(\"chatDialog0\") then return end\r\n\t\r\n\tif (not chatOffsetX) then chatOffsetX = 0 end\r\n\t\r\n\tUI.setPosition(\"chatDialog0\", chatOffsetX, 0)\r\n\tUI.setWindowMovable(\"chatDialog0\", movable)\r\nend\r\n\r\n-- FONCTION UI -- Replace le Suivi de Quête mi-hauteur à gauche et le rend indéplaçable/déplaçable\r\nfunction prepareFollowQuestUI(movable)\r\n    local dialogName = \"\"\r\n    if UI.isDialogLoaded(\"verticalFollowedAchievementsDialog\") then\r\n        dialogName = \"verticalFollowedAchievementsDialog\"\r\n    end\r\n    if UI.isDialogLoaded(\"followedAchievementsDialog\") then\r\n        dialogName = \"followedAchievementsDialog\"\r\n    end\r\n\r\n    if (dialogName == \"\") then\r\n        return\r\n    end\r\n\r\n    local screenH, screenW = UI.getWindowSize()\r\n    local x, y = UI.getPosition(dialogName)\r\n\r\n    UI.setPosition(dialogName, x, screenH / 4)\r\n    UI.setWindowMovable(dialogName, movable)\r\nend\r\n\r\n-- FONCTION UI -- Rend Visible/Invisible certains éléments des interfaces\r\nfunction prepareUI(visible)\r\n  --Interface Boutique & Cadeau\r\n  setWidgetVisible(\"topHudDialog\", \"optionShopButton\", visible)\r\n  setWidgetVisible(\"topHudDialog\", \"giftButton\", visible)\r\n\r\n  --UI sous le Coeur\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"wakfuStasisBar\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"xpBar\", visible)\r\n\r\n  --Boutons hors combat à droite du Coeur\r\n  setWidgetVisible(\"shortcutBarDialog\", \"previousButton\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"nextButton\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseShortcutBar1\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseShortcutBar2\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseShortcutBar3\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseShortcutBar4\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"shortcutBarItemButton\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"shortcutBarSpellButton\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseButtonContainerForTuto1\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseButtonContainerForTuto2\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseButtonContainerForTuto3\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseButtonContainerForTuto4\", visible)\r\n\r\n  --Boutons hors combat à gauche de l'écran - barre d'interfaces\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"firstInterfaceBarBackground\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"secondInterfaceBarBackground\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"extraInterfaceBarDrawerButton\", visible)\r\n\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"fightInfoBtn\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"inventoryButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"buildSheetSetButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"craftButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"questsButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"dungeonButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"cosmeticsButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"tutorialBookButton\", visible)\r\n\r\n  --Boutons hors combat à gauche de l'écran - barre d'interfaces (deuxième barre)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"contactListButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"guildButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"companionsButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"nationButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"battlegroundButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"passportButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"emoteButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"encyclopediaButton\", visible)\r\n\r\n  --Boutons hors combat \"actions rapides\"\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"OverWorldActionsBackground\", visible)\r\n\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"dimensionalBagButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"mapButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"rideMountButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"miniMapButton\", visible)\r\n\r\n  --Boutons en combat à gauche du Coeur\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"FightActionsBackground\", visible)\r\n\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"giveUpButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"hideFightersButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"tacticalModeBtn\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"reportCellBtn\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"fightMarkerBtn\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"lockFightBtn\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"resistanceOverheadBtn\", visible)\r\nend\r\n\r\n-- FONCTION SHORTCUT -- Rend Actif/Inactif certains raccourcis\r\nfunction prepareShortcuts(enabled, shortcutType)\r\n  if not shortcutType or shortcutType == \"WORLD\" then\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.world\", \"enterLeaveBag\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.world\", \"switchHero0\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.world\", \"switchHero1\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.world\", \"switchHero2\")\r\n  end\r\n  if not shortcutType or shortcutType == \"DISPLAY\" then\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"zoomIn\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"zoomOut\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"closeWindows\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"setLODLevel\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"setFightLODLevel\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"showHideNameOverheadsCommand\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"hideFightOccluders\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"alphaMask\")\r\n  end\r\n  if not shortcutType or shortcutType == \"CHAT\" then\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.chat\", \"chat\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.chat\", \"lastContact\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.chat\", \"firstContact\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.chat\", \"autoCompletePlayerName\")\r\n    for bind=1, 9, 1 do\r\n      UI.setShortcutEnabled(enabled, \"shortcutCategory.shortcutBar\", \"bind\" .. toString(bind))\r\n    end\r\n  end\r\n\r\n  if not shortcutType or shortcutType == \"FIGHT\" then\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"fighterTransparency\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"switchTacticalView\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"nextSelectedFighter\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"giveUp\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"lockFight\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"reportCell\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"callHelp\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"displayHpBar\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"resetFightCamera\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"endPlacementAndTurn\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"closeCombatRight\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"closeCombatLeft\")\r\n  end\r\n  if not shortcutType or shortcutType == \"INTERFACE\" then\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"minimap\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"contactList\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"companionManagement\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"guild\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"craft\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"dungeonList\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"achievements\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"quests\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"emotes\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"ecosystem\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"climate\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"nation\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"partySearch\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"passport\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"almanax\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"tutorialBook\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"switchToDirectAttackCommand\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"map\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"spellsInventory\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"inventory\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"characterBook\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"osamodasSymbiot\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"shortcutBar0\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"shortcutBar1\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"shortcutBar2\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"shortcutBar3\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"additionalShortcutBar0\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"additionalShortcutBar1\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"additionalShortcutBar2\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"additionalShortcutBar3\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"changeShortcutBarType\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"downscaling\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"rewards\")\r\n\tUI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"battlegroundList\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"aptitudes\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"presets\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"encyclopedia\")\r\n  end\r\n\r\n  -- On ne bloque pas les raccourcis de sorts finalement\r\n--   if not shortcutType or shortcutType == \"SHORTCUTBAR\" then\r\n--     for bar=0,3, 1 do\r\n--       for slot=0, 9, 1 do\r\n--         UI.setShortcutEnabled(enabled, \"shortcutCategory.shortcutBar\", \"shortcut\" .. toString(bar) .. toString(slot))\r\n--       end\r\n--     end\r\n--   end\r\nend\r\n\r\n-- FONCTION UI -- Rend Visible/Invisible un élément d'une interface\r\nfunction setWidgetVisible(dialogName, widgetName, visible)\r\n  if not UI.isDialogLoaded(dialogName) then return end\r\n\r\n  UI.setWidgetVisibility(dialogName, widgetName, visible)\r\n  table.insert(widget_visible, { name = dialogName, id = widgetName, state = visible })\r\nend\r\n\r\nfunction clearWidgetVisible()\r\n  local str = \"\"\r\n  for i=#widget_visible, 1, -1 do\r\n    str = str .. toString(widget_visible[i].name) .. \"@\" .. toString(widget_visible[i].id) .. \";\"\r\n    UI.setWidgetVisibility(widget_visible[i].name, widget_visible[i].id, true)\r\n  end\r\n\r\n  widget_visible = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearWidgetVisible\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Rend Actif/Inactif un élément d'une interface\r\nfunction setWidgetEnable(dialogName, widgetName, enable)\r\n  if not UI.isDialogLoaded(dialogName) then return end\r\n\r\n  UI.setWidgetEnabled(dialogName, widgetName, enable)\r\n  table.insert(widget_enable, {name = dialogName, id = widgetName, state = enable})\r\nend\r\n\r\nfunction clearWidgetEnable()\r\n  local str = \"\"\r\n  for i=#widget_enable, 1, -1 do\r\n    str = str .. toString(widget_enable[i].name) .. \"@\" .. toString(widget_enable[i].id) .. \";\"\r\n    UI.setWidgetEnabled(widget_enable[i].name, widget_enable[i].id, true)\r\n  end\r\n\r\n  widget_enable = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearWidgetEnable\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Ajoute/Retire une TweenParticle à un élément d'une interface\r\nfunction setUIColorTween(dialogName, widgetName, duration, loop, r1, g1, b1, a1, r2, g2, b2, a2)\r\n  if not UI.isDialogLoaded(dialogName) then return end\r\n\r\n  UI.addColorTween(dialogName, widgetName, duration, loop, r1, g1, b1, a1, r2, g2, b2, a2)\r\n  table.insert(ui_tweens, {name = dialogName, id = widgetName})\r\nend\r\n\r\nfunction clearUIColorTweens(dialogName, widgetName)\r\n  local str = \"\"\r\n  for i=#ui_tweens, 1, -1 do\r\n    if ((not dialogName) or (dialogName == ui_tweens[i].name)) and ((not widgetName) or (widgetName == ui_tweens[i].id)) then\r\n      str = str .. toString(ui_tweens[i].name) .. \"@\" .. toString(ui_tweens[i].id) .. \";\"\r\n      UI.removeColorTween(ui_tweens[i].name, ui_tweens[i].id)\r\n      table.remove(ui_tweens, i)\r\n    end\r\n  end\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearUIColorTweens\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Ajoute/Retire une Particle à un élément d'une interface\r\nfunction setUIParticle(dialogName, widgetName, apsFileName, x, y, alignment, level)\r\n  if not UI.isDialogLoaded(dialogName) then return end\r\n\r\n  local particleId = UI.addParticle(dialogName, widgetName, apsFileName, x, y, alignment, level)\r\n  table.insert(ui_particles, {name = dialogName, id = widgetName})\r\n\r\n  return particleId\r\nend\r\n\r\nfunction setUIParticleBorder(dialogName, widgetName, apsFileName, x, y, alignment, level, speed)\r\n  if not UI.isDialogLoaded(dialogName) then return end\r\n\r\n  local particleId = UI.addParticleToBorder(dialogName, widgetName, apsFileName, x, y, alignment, level, speed)\r\n  table.insert(ui_particles, {name = dialogName, id = widgetName})\r\n\r\n  return particleId\r\nend\r\n\r\nfunction clearUIParticles(dialogName, widgetName)\r\n  local str = \"\"\r\n  for i=#ui_particles, 1, -1 do\r\n    if ((not dialogName) or (dialogName == ui_particles[i].name)) and ((not widgetName) or (widgetName == ui_particles[i].id)) then\r\n      str = str .. toString(ui_particles[i].name) .. \"@\" .. toString(ui_particles[i].id) .. \";\"\r\n      UI.clearParticles(ui_particles[i].name, ui_particles[i].id)\r\n      table.remove(ui_particles, i)\r\n    end\r\n  end\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearUIParticles\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Enregistre/Supprime un callback à l'ouverture d'une interface\r\nfunction addDialogLoadListener(dialog, funcName, ...)\r\n  UI.addDialogLoadedListener(dialog, funcName, unpack(arg))\r\n  table.insert(ui_listener_load,  dialog)\r\nend\r\n\r\nfunction clearDialogLoadListener(dialogName)\r\n  local str = \"\"\r\n  for i=#ui_listener_load, 1, -1 do\r\n    if (not dialogName) or (dialogName == ui_listener_load[i]) then\r\n      str = str .. toString(ui_listener_load[i]) .. \";\"\r\n      UI.removeDialogLoadedListener(ui_listener_load[i])\r\n      table.remove(ui_listener_load, i)\r\n    end\r\n  end\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearDialogLoadListener\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Enregistre/Supprime un callback à la fermeture d'une interface\r\nfunction addDialogUnloadListener(dialog, funcName, ...)\r\n  UI.addDialogUnloadedListener(dialog, funcName, unpack(arg))\r\n  table.insert(ui_listener_unload, dialog)\r\nend\r\n\r\nfunction clearDialogUnloadListener(dialogName)\r\n  local str = \"\"\r\n  for i=#ui_listener_unload, 1, -1 do\r\n    if (not dialogName) or (dialogName == ui_listener_unload[i]) then\r\n      str = str .. toString(ui_listener_unload[i]) .. \";\"\r\n      UI.removeDialogUnloadedListener(ui_listener_unload[i])\r\n      table.remove(ui_listener_unload, i)\r\n    end\r\n  end\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearDialogUnloadListener\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Enregistre/Supprime un callback sur un élément d'une interface\r\nfunction addDialogEventListener(dialog, id, eventType, funcName, ...)\r\n  if not UI.isDialogLoaded(dialog) then return end\r\n\r\n  UI.addEventListener(dialog, id, eventType, funcName, unpack(arg))\r\n  table.insert(ui_listener_event, {dialog=dialog, id=id, eventType=eventType, funcName=funcName})\r\nend\r\n\r\nfunction clearDialogEventListener(dialogName)\r\n  local str = \"\"\r\n  for i=#ui_listener_event, 1, -1 do\r\n    if (not dialogName) or (dialogName == ui_listener_event[i].dialog) then\r\n      str = str .. toString(ui_listener_event[i].dialog) .. \"@\" .. toString(ui_listener_event[i].id) .. \";\"\r\n      UI.removeEventListener(ui_listener_event[i].dialog, ui_listener_event[i].id, ui_listener_event[i].eventType, ui_listener_event[i].funcName)\r\n      table.remove(ui_listener_event, i)\r\n    end\r\n  end\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearDialogEventListener\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y , z, ...)\r\n  local particleId = Particle.addParticleSystem(particleFileId, x, y , z, unpack(arg))\r\n  table.insert(world_particles, particleId)\r\n\r\n  return particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n  local particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n  table.insert(world_particles, particleId)\r\n\r\n  return particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n  local str = \"\"\r\n  for i=#world_particles, 1, -1 do\r\n    str = str .. toString(world_particles[i]) .. \";\"\r\n    Particle.removeParticleSystem(world_particles[i])\r\n  end\r\n\r\n  world_particles = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n  BubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n  if isLower(mobileId, 0) then\r\n    BubbleText.setCharacterSpeak(mobileId, text)\r\n  else\r\n    if (not offsetY) then\r\n      local height = Mobile.getMobileHeight(mobileId)\r\n      if (not height) then height = 6 end\r\n\r\n      offsetY = height * 10\r\n    end\r\n\r\n    if (not offsetX) then offsetX = 0 end\r\n    if (not infiniteDuration) then infiniteDuration = false end\r\n\r\n    BubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n    UI.writeLocalisedInChat(text)\r\n  end\r\n\r\n  if (not tContains(bubbles, mobileId)) then\r\n    table.insert(bubbles, mobileId)\r\n  end\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n  local str = \"\"\r\n  for i = #bubbles, 1, -1 do\r\n    if (not mobileId) then\r\n      str = str .. toString(bubbles[i]) .. \";\"\r\n      BubbleText.closeBubbleAttachedTo(bubbles[i])\r\n    elseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n      str = str .. toString(bubbles[i]) .. \";\"\r\n      BubbleText.closeBubbleAttachedTo(bubbles[i])\r\n      table.remove(bubbles, i)\r\n    end\r\n  end\r\n\r\n  if (not mobileId) then bubbles = {} end\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n  local compassId = UI.addCompass(\"compass\", x, y, z)\r\n  table.insert(compasses, compassId)\r\n\r\n  return compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n  local str = \"\"\r\n  for i=#compasses, 1, -1 do\r\n    str = str .. toString(compasses[i]) .. \";\"\r\n    UI.removeCompass(compasses[i])\r\n  end\r\n\r\n  compasses = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height)\r\n  local mobileId = Mobile.generateClientMobileId()\r\n  Actor.createActor(mobileId, spriteName, worldX, worldY, worldZ, availableDirection)\r\n\r\n  if (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n  if (height) then Actor.setActorHeight(mobileId, height) end\r\n\r\n  table.insert(actors, mobileId)\r\n\r\n  return mobileId\r\nend\r\n\r\nfunction clearActors()\r\n  local str = \"\"\r\n  for i = #actors, 1, -1 do\r\n    str = str .. toString(actors[i]) .. \";\"\r\n    Actor.deleteActor(actors[i])\r\n  end\r\n\r\n  actors = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n  local taskId = invoke(delay, count, funcName, unpack(arg))\r\n  table.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n  local str = \"\"\r\n  for i=#invoke_tasks, 1, -1 do\r\n    str = str .. toString(invoke_tasks[i]) .. \";\"\r\n    interrupt(invoke_tasks[i])\r\n    desinvoke(invoke_tasks[i])\r\n  end\r\n\r\n  invoke_tasks = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n  invoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n  local taskId = setInterval(delay, funcName, unpack(arg))\r\n  table.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n  local str = \"\"\r\n  for i=#interval_tasks, 1, -1 do\r\n    str = str .. toString(interval_tasks[i]) .. \";\"\r\n    interrupt(interval_tasks[i])\r\n    desinvoke(interval_tasks[i])\r\n  end\r\n\r\n  interval_tasks = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n  if (_DEBUG) then trace(\"startCinematicContext\") end\r\n\r\n  UI.manageFrame(\"World\", false)\r\n  UI.closeMRU()\r\n  UI.closeAllBags()\r\n  UI.setUIVisible(false)\r\n  UI.displayWideScreenBand(true)\r\n  Camera.setUserZoomLocked(true)\r\n\r\n  if (cameraMobileId ~= nil)  then\r\n    Camera.setMoveSpeedFactor(10000)\r\n    Camera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n  end\r\n\r\n  if (zoomFactor ~= nil)  then\r\n    Camera.setZoomFactor(zoomFactor)\r\n  end\r\n\r\n  if (musicId ~= nil)  then\r\n    Sound.playForcedMusic(musicId)\r\n  end\r\n\r\n  if (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\nfunction skipCinematic()\r\n  local player = Context.getLeaderId()\r\n\r\n  for x = 1, #_ACTOR_LIST do\r\n    Actor.deleteActor(_ACTOR_LIST[x])\r\n  end\r\n\r\n  UI.hideButton()\r\n  clearALL()\r\n  stopCinematicContext(1, player, true)\r\n  Mobile.setMobileVisible(player, true)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n  if (_DEBUG) then trace(\"stopCinematicContext\") end\r\n\r\n  UI.displayWideScreenBand(false)\r\n  UI.setUIVisible(true)\r\n  Camera.setUserZoomLocked(false)\r\n  UI.manageFrame(\"World\", true)\r\n\r\n  Camera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n  Camera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n  if (zoomFactor ~= nil) then\r\n    Camera.setZoomFactor(zoomFactor)\r\n  end\r\n\r\n  if (cameraMobileId ~= nil) then\r\n    Camera.attachCameraToMobile(cameraMobileId)\r\n  end\r\n\r\n  if (stopMusic) then\r\n    Sound.stopForcedMusic()\r\n  end\r\n\r\n  if (_DEBUG) then\r\n    UI.hideButton()\r\n  end\r\n\r\n  --TRIGGER\r\n  Server.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Affiche/Masque une texture à l'écran\r\nfunction displayScreenEffect(enable, fadeInDur, alphaDur, fadeOutDur, r, g, b, alpha)\r\n  if (_DEBUG) then trace(\"displayScreenEffect\") end\r\n\r\n  if not enable and screenEffectId ~= nil  then\r\n    --On retire le blackScreen\r\n    Effect.stopEffect(screenEffectId)\r\n  else\r\n    --On affiche un blackScreen à l'entrée dans l'instance le temps qu'elle soit complètement chargée\r\n    screenEffectId = Effect.createFullScreenSprite(fadeInDur, alphaDur, fadeOutDur, r, g, b, alpha)\r\n  end\r\nend\r\n\r\n-- FONCTION NETTOYAGE --\r\nfunction clearALL()\r\n  clearIntervalTasks()\r\n  clearInvokeTasks()\r\n  clearBubbles()\r\n  clearUIColorTweens()\r\n  clearUIParticles()\r\n  clearWorldParticles()\r\n  clearCompasses()\r\n  clearActors()\r\n\r\n  Focus.display(false)\r\n  UI.unloadTutorialDialog()\r\nend\r\n\r\n-- FONCTION NETTOYAGE --\r\nfunction clearUI(dialogName)\r\n  clearUIColorTweens(dialogName)\r\n  clearUIParticles(dialogName)\r\nend\r\n\r\n-- FONCTION NETTOYAGE --\r\nfunction clearListener(dialogName)\r\n  clearDialogLoadListener(dialogName)\r\n  clearDialogUnloadListener(dialogName)\r\n  clearDialogEventListener(dialogName)\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\nfunction onInstanceLoaded()\r\n    if (_DEBUG) then\r\n        trace(\"ON INSTANCE LOADED\")\r\n    end\r\n\r\n    UI.manageFrame(\"World\", true)\r\n    UI.setUIVisible(true)\r\n    displayScreenEffect(false)\r\n\r\n    -- TRIGGER\r\n    Server.triggerEvent(24376)\r\nend\n\n-- ENTER_INSTANCE - Inscription au scénario + notif\n-- \nfunction event_2751_24376()\n    if (_DEBUG) then\r\n        trace(\"ENTER INSTANCE\")\r\n    end\r\n    \r\n    Event.runOnInstanceLoaded(\"onInstanceLoaded\")\nend\n\n-- Event fini - On notif au scénario\n-- \nfunction event_2751_24378()\n    invoke(500, 1, \"Server.triggerEvent\", 24376)\nend\n\n-- Ping serveur (via onInstanceLoaded ou IEaction) - Don jetons\n-- \nfunction event_2751_24377()\n    -- \"Don Jetons\"\r\n    \r\n    if (_DEBUG) then\r\n        trace(\"GIVE TOKENS\")\r\n    end\nend\n\n-- INTERACTIVE_ELEMENT_ACTION - Bribe 1 NOTIF ACH 5663\n-- \nfunction event_2751_24379()\n    -- \"On joue le don de jeton après la validation de l'achievement\"\r\n    \r\n    invoke(1000, 1, \"Server.triggerEvent\", 24376)\nend\n\n-- INTERACTIVE_ELEMENT_ACTION - Bribe 2 NOTIF ACH 5664\n-- \nfunction event_2751_24380()\n    -- \"On joue le don de jeton après la validation de l'achievement\"\r\n    \r\n    invoke(1000, 1, \"Server.triggerEvent\", 24376)\nend\n\n-- INTERACTIVE_ELEMENT_ACTION - Bribe 3 NOTIF ACH 5665\n-- \nfunction event_2751_24381()\n    -- \"On joue le don de jeton après la validation de l'achievement\"\r\n    \r\n    invoke(1000, 1, \"Server.triggerEvent\", 24376)\nend\n\n-- INTERACTIVE_ELEMENT_ACTION - Bribe 4 NOTIF ACH 5666\n-- \nfunction event_2751_24382()\n    -- \"On joue le don de jeton après la validation de l'achievement\"\r\n    \r\n    invoke(1000, 1, \"Server.triggerEvent\", 24376)\nend\n\n-- FIGHT_END_LOG + SEED_PLANTED - Notif scénario only\n-- \nfunction event_2751_24383()\n    -- \"On joue le don de jeton après la validation de l'achievement\"\r\n    \r\n    invoke(1000, 1, \"Server.triggerEvent\", 24376)\nend\n\n-- Achievement 5669 - ITEM_CRAFT_EVENT\n-- \nfunction event_2751_24426()\n    \nend\n\n","functions":["tContains","prepareChatUI","prepareFollowQuestUI","prepareUI","prepareShortcuts","setWidgetVisible","clearWidgetVisible","setWidgetEnable","clearWidgetEnable","setUIColorTween","clearUIColorTweens","setUIParticle","setUIParticleBorder","clearUIParticles","addDialogLoadListener","clearDialogLoadListener","addDialogUnloadListener","clearDialogUnloadListener","addDialogEventListener","clearDialogEventListener","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","bubble","clearBubbles","setCompass","clearCompasses","createActor","clearActors","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","startCinematicContext","skipCinematic","stopCinematicContext","displayScreenEffect","clearALL","clearUI","clearListener","fullScreen","text","onInstanceLoaded","event_2751_24376","event_2751_24378","event_2751_24377","event_2751_24379","event_2751_24380","event_2751_24381","event_2751_24382","event_2751_24383","event_2751_24426"],"quest_calls":[],"dialogue_calls":[]},"scenario/2752.lua":{"source":"\n\n-- ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2752_24394()\n    \nend\n\n-- INTERACTIVE_ELEMENT_ACTION - Pont secteur 1\n-- \nfunction event_2752_24395()\n    \nend\n\n-- INTERACTIVE_ELEMENT_ACTION - Pont secteur 2\n-- \nfunction event_2752_24396()\n    \nend\n\n","functions":["event_2752_24394","event_2752_24395","event_2752_24396"],"quest_calls":[],"dialogue_calls":[]},"scenario/2753.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n-- TRIGGER CLIENT --\r\n-- 0 = Fin cinématique VIDEO | Déclenché par le callback Video.addVideoStopOrEndCallback\r\n-- 1 = Arrivée dans l'instance | Déclenché par onInstanceLoaded() callback par Event.runOnInstanceLoaded (cf code Global)\r\n-- 2 = Fin cinématique | Déclenché par stopCinematicContext() (cf code Global)\r\n-- 3 = Fermeture UI Fin de combat\r\n-- 4 = Clic sur le bon bouton de changement d'oriention (parmis les 4) dans UI worldAndFightBar pour s'orientation vers le monstre\r\n-- 5 = Fermeture UI Fiche combattant\r\n-- 6 = Clic sur le bouton de validation de la répartition dans UI Aptitudes\r\n-- 7 = Clic sur la boussole du bon objectif dans l'UI suivi de quête\r\n-- 8 = Fermeture UI Map Monde\r\n\r\n-- VARIABLE GLOBALE - SCRIPT --\r\n\r\nwidget_visible = {}\r\nwidget_enable = {}\r\nui_tweens = {}\r\nui_particles = {}\r\nui_listener_load = {}\r\nui_listener_unload = {}\r\nui_listener_event = {}\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\nscreenEffectId = nil\r\n\r\n-- VARIABLE GLOBALE - MOBILE CINEMATIQUE & TUTO --\r\n\r\nANM_otomai = {think=\"AnimComp-Special03\", talk=\"AnimComp-Special04-Debut\", show=\"AnimComp-Special05-Debut\", nice=\"AnimComp-Special07\", nope=\"AnimComp-Special08\", lol=\"AnimComp-Special09\", stop_it=\"AnimComp-Special10\", come_here=\"AnimComp-Special01\", wave_hit=\"AnimComp-Special02\", fly=\"AnimStatique-Oiseau\", cast=\"AnimSort-01\", supercast=\"AnimComp-Special11\", attack=\"AnimSort-Cast\", balance=\"AnimComp-Special06\"}\r\nANM_melee = {attack=\"AnimSort-Morsure\", glitch1=\"AnimComp-Glitch01\", glitch2=\"AnimComp-Glitch02\", glitch3=\"AnimComp-Glitch03\", roar=\"AnimComp-Agressif\"}\r\nANM_range = {attack=\"AnimSort-01\", glitch=\"AnimComp-Glitch\", dupli=\"AnimComp-Dupli\"}\r\nANM_boss = {attack1=\"AnimSort-Estoc\", attack2=\"AnimSort-Hrargh\", glitch=\"AnimComp-Glitch\", dupli=\"AnimComp-Dupli\", roar=\"AnimComp-Hurle\", ko = \"AnimKO-SortieOK\", death= \"AnimKO-SortieHS\"}\r\n\r\nNPC_otomai = Mobile.generateClientMobileId()\r\nNPC_otomai_gfx = 181404009\r\nNPC_otomai_particleZ = 10\r\nNPC_otomai_bubbleX = 10\r\nNPC_otomai_bubbleY = 70\r\n\r\nNPC_melee = Mobile.generateClientMobileId()\r\nNPC_meleeB = Mobile.generateClientMobileId()\r\nNPC_melee_gfx = 181404014\r\nNPC_melee_particleZ = 5\r\n\r\nNPC_range = Mobile.generateClientMobileId()\r\nNPC_range_gfx = 181404015\r\nNPC_range_particleZ = 3\r\n\r\nNPC_boss = Mobile.generateClientMobileId()\r\nNPC_boss_gfx = 181404012\r\nNPC_boss_particleZ = 8\r\n\r\nNPC_eni_wakfu = Mobile.generateClientMobileId()\r\nNPC_eni_wakfu_gfx = 181404034\r\nNPC_eni_wakfu_particleZ = 7\r\n\r\nNPC_eni_stasis = Mobile.generateClientMobileId()\r\nNPC_eni_stasis_gfx = 181404013\r\nNPC_eni_stasis_particleZ = 7\r\n\r\n_ACTOR_LIST = {NPC_otomai, NPC_melee, NPC_meleeB, NPC_range, NPC_boss, NPC_eni_wakfu, NPC_eni_stasis}\r\n\r\n-- VARIABLE GLOBALE - PARTICULE CINEMATIQUE & TUTO --\r\n\r\n-- UI TUTO\r\napsArrowBig = {6001069,6001070,6001071,6001072,6001073,6001074,6001075,6001076}\r\napsArrow = {6001061,6001062,6001063,6001064,6001065,6001066,6001067,6001068}\r\napsCenter = {ap=6001090, mp=6001091, wp=6001092, hp=6001093}\r\napsFollowBorder = -1548037644\r\n-- WORLD TUTO\r\napsCell = {white_border=800578, red_border=800579, white_arrow=800576, red_arrow=800577, white=800581, red=800582, show=78900}\r\n-- CINEMATIQUE\r\napsWave = {spawn=800573, wave=800574, hit=800575}\r\napsOtomai = {shield=-1814057071, transform=-1814057072, playershield = -1814057074}\r\napsCristal = {base=71071022, react=800580, shield=71071021}\r\napsBoss = {death=-1814057073}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n    for index, value in ipairs (tab) do\r\n\t\tif isEqual(value, val) then\r\n            return true\r\n        end\r\n    end\r\n\r\n    return false\t\r\nend\r\n\r\n-- FONCTION UI -- Replace le Chat en bas à gauche et le rend indéplaçable/déplaçable\r\nfunction prepareChatUI(movable, chatOffsetX)\r\n\tif not UI.isDialogLoaded(\"chatDialog0\") then return end\r\n\t\r\n\tif (not chatOffsetX) then chatOffsetX = 0 end\r\n\t\r\n\tUI.setPosition(\"chatDialog0\", chatOffsetX, 0)\r\n\tUI.setWindowMovable(\"chatDialog0\", movable)\r\nend\r\n\r\n-- FONCTION UI -- Replace le Suivi de Quête mi-hauteur à gauche et le rend indéplaçable/déplaçable\r\nfunction prepareFollowQuestUI(movable)\r\n    local dialogName = \"\"\r\n    if UI.isDialogLoaded(\"verticalFollowedAchievementsDialog\") then\r\n        dialogName = \"verticalFollowedAchievementsDialog\"\r\n    end\r\n    if UI.isDialogLoaded(\"followedAchievementsDialog\") then\r\n        dialogName = \"followedAchievementsDialog\"\r\n    end\r\n\r\n    if (dialogName == \"\") then\r\n        return\r\n    end\r\n\r\n    local screenH, screenW = UI.getWindowSize()\r\n    local x, y = UI.getPosition(dialogName)\r\n\r\n    UI.setPosition(dialogName, x, screenH / 4)\r\n    UI.setWindowMovable(dialogName, movable)\r\nend\r\n\r\n-- FONCTION UI -- Rend Visible/Invisible certains éléments des interfaces\r\nfunction prepareUI(visible)\r\n  --Interface Boutique & Cadeau\r\n  setWidgetVisible(\"topHudDialog\", \"optionShopButton\", visible)\r\n  setWidgetVisible(\"topHudDialog\", \"giftButton\", visible)\r\n\r\n  --UI sous le Coeur\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"wakfuStasisBar\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"xpBar\", visible)\r\n\r\n  --Boutons hors combat à droite du Coeur\r\n  setWidgetVisible(\"shortcutBarDialog\", \"previousButton\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"nextButton\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseShortcutBar1\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseShortcutBar2\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseShortcutBar3\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseShortcutBar4\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"shortcutBarItemButton\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"shortcutBarSpellButton\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseButtonContainerForTuto1\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseButtonContainerForTuto2\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseButtonContainerForTuto3\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseButtonContainerForTuto4\", visible)\r\n\r\n  --Boutons hors combat à gauche de l'écran - barre d'interfaces\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"firstInterfaceBarBackground\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"secondInterfaceBarBackground\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"extraInterfaceBarDrawerButton\", visible)\r\n\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"fightInfoBtn\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"inventoryButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"buildSheetSetButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"craftButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"questsButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"dungeonButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"cosmeticsButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"tutorialBookButton\", visible)\r\n\r\n  --Boutons hors combat à gauche de l'écran - barre d'interfaces (deuxième barre)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"contactListButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"guildButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"companionsButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"nationButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"battlegroundButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"passportButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"emoteButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"encyclopediaButton\", visible)\r\n\r\n  --Boutons hors combat \"actions rapides\"\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"OverWorldActionsBackground\", visible)\r\n\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"dimensionalBagButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"mapButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"rideMountButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"miniMapButton\", visible)\r\n\r\n  --Boutons en combat à gauche du Coeur\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"FightActionsBackground\", visible)\r\n\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"giveUpButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"hideFightersButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"tacticalModeBtn\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"reportCellBtn\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"fightMarkerBtn\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"lockFightBtn\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"resistanceOverheadBtn\", visible)\r\nend\r\n\r\n-- FONCTION SHORTCUT -- Rend Actif/Inactif certains raccourcis\r\nfunction prepareShortcuts(enabled, shortcutType)\r\n  if not shortcutType or shortcutType == \"WORLD\" then\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.world\", \"enterLeaveBag\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.world\", \"switchHero0\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.world\", \"switchHero1\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.world\", \"switchHero2\")\r\n  end\r\n  if not shortcutType or shortcutType == \"DISPLAY\" then\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"zoomIn\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"zoomOut\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"closeWindows\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"setLODLevel\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"setFightLODLevel\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"showHideNameOverheadsCommand\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"hideFightOccluders\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"alphaMask\")\r\n  end\r\n  if not shortcutType or shortcutType == \"CHAT\" then\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.chat\", \"chat\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.chat\", \"lastContact\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.chat\", \"firstContact\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.chat\", \"autoCompletePlayerName\")\r\n    for bind=1, 9, 1 do\r\n      UI.setShortcutEnabled(enabled, \"shortcutCategory.shortcutBar\", \"bind\" .. toString(bind))\r\n    end\r\n  end\r\n\r\n  if not shortcutType or shortcutType == \"FIGHT\" then\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"fighterTransparency\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"switchTacticalView\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"nextSelectedFighter\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"giveUp\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"lockFight\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"reportCell\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"callHelp\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"displayHpBar\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"resetFightCamera\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"endPlacementAndTurn\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"closeCombatRight\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"closeCombatLeft\")\r\n  end\r\n  if not shortcutType or shortcutType == \"INTERFACE\" then\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"minimap\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"contactList\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"companionManagement\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"guild\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"craft\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"dungeonList\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"achievements\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"quests\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"emotes\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"ecosystem\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"climate\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"nation\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"partySearch\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"passport\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"almanax\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"tutorialBook\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"switchToDirectAttackCommand\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"map\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"spellsInventory\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"inventory\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"characterBook\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"osamodasSymbiot\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"shortcutBar0\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"shortcutBar1\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"shortcutBar2\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"shortcutBar3\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"additionalShortcutBar0\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"additionalShortcutBar1\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"additionalShortcutBar2\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"additionalShortcutBar3\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"changeShortcutBarType\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"downscaling\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"rewards\")\r\n\tUI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"battlegroundList\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"aptitudes\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"presets\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"encyclopedia\")\r\n  end\r\n\r\n  -- On ne bloque pas les raccourcis de sorts finalement\r\n--   if not shortcutType or shortcutType == \"SHORTCUTBAR\" then\r\n--     for bar=0,3, 1 do\r\n--       for slot=0, 9, 1 do\r\n--         UI.setShortcutEnabled(enabled, \"shortcutCategory.shortcutBar\", \"shortcut\" .. toString(bar) .. toString(slot))\r\n--       end\r\n--     end\r\n--   end\r\nend\r\n\r\n-- FONCTION UI -- Rend Visible/Invisible un élément d'une interface\r\nfunction setWidgetVisible(dialogName, widgetName, visible)\r\n  if not UI.isDialogLoaded(dialogName) then return end\r\n\r\n  UI.setWidgetVisibility(dialogName, widgetName, visible)\r\n  table.insert(widget_visible, { name = dialogName, id = widgetName, state = visible })\r\nend\r\n\r\nfunction clearWidgetVisible()\r\n  local str = \"\"\r\n  for i=#widget_visible, 1, -1 do\r\n    str = str .. toString(widget_visible[i].name) .. \"@\" .. toString(widget_visible[i].id) .. \";\"\r\n    UI.setWidgetVisibility(widget_visible[i].name, widget_visible[i].id, true)\r\n  end\r\n\r\n  widget_visible = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearWidgetVisible\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Rend Actif/Inactif un élément d'une interface\r\nfunction setWidgetEnable(dialogName, widgetName, enable)\r\n  if not UI.isDialogLoaded(dialogName) then return end\r\n\r\n  UI.setWidgetEnabled(dialogName, widgetName, enable)\r\n  table.insert(widget_enable, {name = dialogName, id = widgetName, state = enable})\r\nend\r\n\r\nfunction clearWidgetEnable()\r\n  local str = \"\"\r\n  for i=#widget_enable, 1, -1 do\r\n    str = str .. toString(widget_enable[i].name) .. \"@\" .. toString(widget_enable[i].id) .. \";\"\r\n    UI.setWidgetEnabled(widget_enable[i].name, widget_enable[i].id, true)\r\n  end\r\n\r\n  widget_enable = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearWidgetEnable\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Ajoute/Retire une TweenParticle à un élément d'une interface\r\nfunction setUIColorTween(dialogName, widgetName, duration, loop, r1, g1, b1, a1, r2, g2, b2, a2)\r\n  if not UI.isDialogLoaded(dialogName) then return end\r\n\r\n  UI.addColorTween(dialogName, widgetName, duration, loop, r1, g1, b1, a1, r2, g2, b2, a2)\r\n  table.insert(ui_tweens, {name = dialogName, id = widgetName})\r\nend\r\n\r\nfunction clearUIColorTweens(dialogName, widgetName)\r\n  local str = \"\"\r\n  for i=#ui_tweens, 1, -1 do\r\n    if ((not dialogName) or (dialogName == ui_tweens[i].name)) and ((not widgetName) or (widgetName == ui_tweens[i].id)) then\r\n      str = str .. toString(ui_tweens[i].name) .. \"@\" .. toString(ui_tweens[i].id) .. \";\"\r\n      UI.removeColorTween(ui_tweens[i].name, ui_tweens[i].id)\r\n      table.remove(ui_tweens, i)\r\n    end\r\n  end\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearUIColorTweens\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Ajoute/Retire une Particle à un élément d'une interface\r\nfunction setUIParticle(dialogName, widgetName, apsFileName, x, y, alignment, level)\r\n  if not UI.isDialogLoaded(dialogName) then return end\r\n\r\n  local particleId = UI.addParticle(dialogName, widgetName, apsFileName, x, y, alignment, level)\r\n  table.insert(ui_particles, {name = dialogName, id = widgetName})\r\n\r\n  return particleId\r\nend\r\n\r\nfunction setUIParticleBorder(dialogName, widgetName, apsFileName, x, y, alignment, level, speed)\r\n  if not UI.isDialogLoaded(dialogName) then return end\r\n\r\n  local particleId = UI.addParticleToBorder(dialogName, widgetName, apsFileName, x, y, alignment, level, speed)\r\n  table.insert(ui_particles, {name = dialogName, id = widgetName})\r\n\r\n  return particleId\r\nend\r\n\r\nfunction clearUIParticles(dialogName, widgetName)\r\n  local str = \"\"\r\n  for i=#ui_particles, 1, -1 do\r\n    if ((not dialogName) or (dialogName == ui_particles[i].name)) and ((not widgetName) or (widgetName == ui_particles[i].id)) then\r\n      str = str .. toString(ui_particles[i].name) .. \"@\" .. toString(ui_particles[i].id) .. \";\"\r\n      UI.clearParticles(ui_particles[i].name, ui_particles[i].id)\r\n      table.remove(ui_particles, i)\r\n    end\r\n  end\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearUIParticles\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Enregistre/Supprime un callback à l'ouverture d'une interface\r\nfunction addDialogLoadListener(dialog, funcName, ...)\r\n  UI.addDialogLoadedListener(dialog, funcName, unpack(arg))\r\n  table.insert(ui_listener_load,  dialog)\r\nend\r\n\r\nfunction clearDialogLoadListener(dialogName)\r\n  local str = \"\"\r\n  for i=#ui_listener_load, 1, -1 do\r\n    if (not dialogName) or (dialogName == ui_listener_load[i]) then\r\n      str = str .. toString(ui_listener_load[i]) .. \";\"\r\n      UI.removeDialogLoadedListener(ui_listener_load[i])\r\n      table.remove(ui_listener_load, i)\r\n    end\r\n  end\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearDialogLoadListener\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Enregistre/Supprime un callback à la fermeture d'une interface\r\nfunction addDialogUnloadListener(dialog, funcName, ...)\r\n  UI.addDialogUnloadedListener(dialog, funcName, unpack(arg))\r\n  table.insert(ui_listener_unload, dialog)\r\nend\r\n\r\nfunction clearDialogUnloadListener(dialogName)\r\n  local str = \"\"\r\n  for i=#ui_listener_unload, 1, -1 do\r\n    if (not dialogName) or (dialogName == ui_listener_unload[i]) then\r\n      str = str .. toString(ui_listener_unload[i]) .. \";\"\r\n      UI.removeDialogUnloadedListener(ui_listener_unload[i])\r\n      table.remove(ui_listener_unload, i)\r\n    end\r\n  end\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearDialogUnloadListener\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Enregistre/Supprime un callback sur un élément d'une interface\r\nfunction addDialogEventListener(dialog, id, eventType, funcName, ...)\r\n  if not UI.isDialogLoaded(dialog) then return end\r\n\r\n  UI.addEventListener(dialog, id, eventType, funcName, unpack(arg))\r\n  table.insert(ui_listener_event, {dialog=dialog, id=id, eventType=eventType, funcName=funcName})\r\nend\r\n\r\nfunction clearDialogEventListener(dialogName)\r\n  local str = \"\"\r\n  for i=#ui_listener_event, 1, -1 do\r\n    if (not dialogName) or (dialogName == ui_listener_event[i].dialog) then\r\n      str = str .. toString(ui_listener_event[i].dialog) .. \"@\" .. toString(ui_listener_event[i].id) .. \";\"\r\n      UI.removeEventListener(ui_listener_event[i].dialog, ui_listener_event[i].id, ui_listener_event[i].eventType, ui_listener_event[i].funcName)\r\n      table.remove(ui_listener_event, i)\r\n    end\r\n  end\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearDialogEventListener\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y , z, ...)\r\n  local particleId = Particle.addParticleSystem(particleFileId, x, y , z, unpack(arg))\r\n  table.insert(world_particles, particleId)\r\n\r\n  return particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n  local particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n  table.insert(world_particles, particleId)\r\n\r\n  return particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n  local str = \"\"\r\n  for i=#world_particles, 1, -1 do\r\n    str = str .. toString(world_particles[i]) .. \";\"\r\n    Particle.removeParticleSystem(world_particles[i])\r\n  end\r\n\r\n  world_particles = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n  BubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n  if isLower(mobileId, 0) then\r\n    BubbleText.setCharacterSpeak(mobileId, text)\r\n  else\r\n    if (not offsetY) then\r\n      local height = Mobile.getMobileHeight(mobileId)\r\n      if (not height) then height = 6 end\r\n\r\n      offsetY = height * 10\r\n    end\r\n\r\n    if (not offsetX) then offsetX = 0 end\r\n    if (not infiniteDuration) then infiniteDuration = false end\r\n\r\n    BubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n    UI.writeLocalisedInChat(text)\r\n  end\r\n\r\n  if (not tContains(bubbles, mobileId)) then\r\n    table.insert(bubbles, mobileId)\r\n  end\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n  local str = \"\"\r\n  for i = #bubbles, 1, -1 do\r\n    if (not mobileId) then\r\n      str = str .. toString(bubbles[i]) .. \";\"\r\n      BubbleText.closeBubbleAttachedTo(bubbles[i])\r\n    elseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n      str = str .. toString(bubbles[i]) .. \";\"\r\n      BubbleText.closeBubbleAttachedTo(bubbles[i])\r\n      table.remove(bubbles, i)\r\n    end\r\n  end\r\n\r\n  if (not mobileId) then bubbles = {} end\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n  local compassId = UI.addCompass(\"compass\", x, y, z)\r\n  table.insert(compasses, compassId)\r\n\r\n  return compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n  local str = \"\"\r\n  for i=#compasses, 1, -1 do\r\n    str = str .. toString(compasses[i]) .. \";\"\r\n    UI.removeCompass(compasses[i])\r\n  end\r\n\r\n  compasses = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height)\r\n  local mobileId = Mobile.generateClientMobileId()\r\n  Actor.createActor(mobileId, spriteName, worldX, worldY, worldZ, availableDirection)\r\n\r\n  if (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n  if (height) then Actor.setActorHeight(mobileId, height) end\r\n\r\n  table.insert(actors, mobileId)\r\n\r\n  return mobileId\r\nend\r\n\r\nfunction clearActors()\r\n  local str = \"\"\r\n  for i = #actors, 1, -1 do\r\n    str = str .. toString(actors[i]) .. \";\"\r\n    Actor.deleteActor(actors[i])\r\n  end\r\n\r\n  actors = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n  local taskId = invoke(delay, count, funcName, unpack(arg))\r\n  table.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n  local str = \"\"\r\n  for i=#invoke_tasks, 1, -1 do\r\n    str = str .. toString(invoke_tasks[i]) .. \";\"\r\n    interrupt(invoke_tasks[i])\r\n    desinvoke(invoke_tasks[i])\r\n  end\r\n\r\n  invoke_tasks = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n  invoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n  local taskId = setInterval(delay, funcName, unpack(arg))\r\n  table.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n  local str = \"\"\r\n  for i=#interval_tasks, 1, -1 do\r\n    str = str .. toString(interval_tasks[i]) .. \";\"\r\n    interrupt(interval_tasks[i])\r\n    desinvoke(interval_tasks[i])\r\n  end\r\n\r\n  interval_tasks = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n  if (_DEBUG) then trace(\"startCinematicContext\") end\r\n\r\n  UI.manageFrame(\"World\", false)\r\n  UI.closeMRU()\r\n  UI.closeAllBags()\r\n  UI.setUIVisible(false)\r\n  UI.displayWideScreenBand(true)\r\n  Camera.setUserZoomLocked(true)\r\n\r\n  if (cameraMobileId ~= nil)  then\r\n    Camera.setMoveSpeedFactor(10000)\r\n    Camera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n  end\r\n\r\n  if (zoomFactor ~= nil)  then\r\n    Camera.setZoomFactor(zoomFactor)\r\n  end\r\n\r\n  if (musicId ~= nil)  then\r\n    Sound.playForcedMusic(musicId)\r\n  end\r\n\r\n  if (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\nfunction skipCinematic()\r\n  local player = Context.getLeaderId()\r\n\r\n  for x = 1, #_ACTOR_LIST do\r\n    Actor.deleteActor(_ACTOR_LIST[x])\r\n  end\r\n\r\n  UI.hideButton()\r\n  clearALL()\r\n  stopCinematicContext(1, player, true)\r\n  Mobile.setMobileVisible(player, true)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n  if (_DEBUG) then trace(\"stopCinematicContext\") end\r\n\r\n  UI.displayWideScreenBand(false)\r\n  UI.setUIVisible(true)\r\n  Camera.setUserZoomLocked(false)\r\n  UI.manageFrame(\"World\", true)\r\n\r\n  Camera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n  Camera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n  if (zoomFactor ~= nil) then\r\n    Camera.setZoomFactor(zoomFactor)\r\n  end\r\n\r\n  if (cameraMobileId ~= nil) then\r\n    Camera.attachCameraToMobile(cameraMobileId)\r\n  end\r\n\r\n  if (stopMusic) then\r\n    Sound.stopForcedMusic()\r\n  end\r\n\r\n  if (_DEBUG) then\r\n    UI.hideButton()\r\n  end\r\n\r\n  --TRIGGER\r\n  Server.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Affiche/Masque une texture à l'écran\r\nfunction displayScreenEffect(enable, fadeInDur, alphaDur, fadeOutDur, r, g, b, alpha)\r\n  if (_DEBUG) then trace(\"displayScreenEffect\") end\r\n\r\n  if not enable and screenEffectId ~= nil  then\r\n    --On retire le blackScreen\r\n    Effect.stopEffect(screenEffectId)\r\n  else\r\n    --On affiche un blackScreen à l'entrée dans l'instance le temps qu'elle soit complètement chargée\r\n    screenEffectId = Effect.createFullScreenSprite(fadeInDur, alphaDur, fadeOutDur, r, g, b, alpha)\r\n  end\r\nend\r\n\r\n-- FONCTION NETTOYAGE --\r\nfunction clearALL()\r\n  clearIntervalTasks()\r\n  clearInvokeTasks()\r\n  clearBubbles()\r\n  clearUIColorTweens()\r\n  clearUIParticles()\r\n  clearWorldParticles()\r\n  clearCompasses()\r\n  clearActors()\r\n\r\n  Focus.display(false)\r\n  UI.unloadTutorialDialog()\r\nend\r\n\r\n-- FONCTION NETTOYAGE --\r\nfunction clearUI(dialogName)\r\n  clearUIColorTweens(dialogName)\r\n  clearUIParticles(dialogName)\r\nend\r\n\r\n-- FONCTION NETTOYAGE --\r\nfunction clearListener(dialogName)\r\n  clearDialogLoadListener(dialogName)\r\n  clearDialogUnloadListener(dialogName)\r\n  clearDialogEventListener(dialogName)\r\nend\r\n\r\n-- Fonction mode démo\r\n-- function addButton()\r\n-- \tinvoke(2000, 1, \"UI.displayButton\", false, \"scenario.endKinematic.confirmEscape\", \"lyongameshow.vampyro.rules.display\", \"displayFightRules\")\r\n-- end \r\n\r\nfunction displayFightRules()\r\n--\tUI.loadTutorialDialog(\"japan.expo.2022\",\"japanexpo.fight.title\",\"japanexpo.fight.desc\")\r\n--\taddButton()\r\nend\r\n\r\nfunction onEnterInstance()  \r\n-- addButton()\r\n \t\r\n   UI.activateFollowAchievement(false)\r\n   prepareUI(false)\r\n   prepareShortcuts(false)\r\n   prepareShortcuts(true, \"DISPLAY\")\r\n   prepareShortcuts(true, \"CHAT\")\r\n   prepareShortcuts(true, \"FIGHT\")\r\n   prepareShortcuts(true, \"SHORTCUTBAR\")\r\n\r\n  UI.setShortcutEnabled(true, \"shortcutCategory.interface\", \"emotes\")\r\n  UI.setShortcutEnabled(false, \"shortcutCategory.interface\", \"switchToDirectAttackCommand\")\r\n  UI.setShortcutEnabled(false, \"shortcutCategory.interface\", \"spellsInventory\")\r\n  UI.setShortcutEnabled(false, \"shortcutCategory.interface\", \"inventory\")\r\n  UI.setShortcutEnabled(false, \"shortcutCategory.interface\", \"osamodasSymbiot\")\r\n  UI.setShortcutEnabled(false, \"shortcutCategory.interface\", \"shortcutBar0\")\r\n  UI.setShortcutEnabled(false, \"shortcutCategory.interface\", \"shortcutBar1\")\r\n  UI.setShortcutEnabled(false, \"shortcutCategory.interface\", \"shortcutBar2\")\r\n  UI.setShortcutEnabled(false, \"shortcutCategory.interface\", \"shortcutBar3\")\r\n  UI.setShortcutEnabled(false, \"shortcutCategory.interface\", \"additionalShortcutBar0\")\r\n  UI.setShortcutEnabled(false, \"shortcutCategory.interface\", \"additionalShortcutBar1\")\r\n  UI.setShortcutEnabled(false, \"shortcutCategory.interface\", \"additionalShortcutBar2\")\r\n  UI.setShortcutEnabled(false, \"shortcutCategory.interface\", \"additionalShortcutBar3\")\r\n  UI.setShortcutEnabled(false, \"shortcutCategory.interface\", \"changeShortcutBarType\")\r\n  \r\n    --Boutons hors combat à droite du Coeur\r\n  setWidgetVisible(\"shortcutBarDialog\", \"previousButton\", true)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"nextButton\", true)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"addExtraBarButton\", true)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"shortcutModeButton\", true)\r\n \r\n \r\n -- Boutons hors combat à gauche du Coeur\r\n\r\n  --Boutons en combat à gauche du Coeur\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"giveUpButton\", true)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"hideFightersButton\", true)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"reportCellBtn\", true)\r\nend\r\n\r\n-- Fonctions cache / montre CM\r\nfunction hideMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, false)\r\nend\r\n\r\nfunction showMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, true)\r\nend\r\n\r\nbubbleFightInfoId = 0\r\n\r\nfunction closeFightInfo()\r\n\tif (bubbleFightInfoId ~= nil and bubbleFightInfoId ~= 0) then BubbleText.close(bubbleFightInfoId) end\r\nend\r\n\r\nfunction onFightInfoClosed()\r\n\tif (bubbleFightInfoId ~= nil and bubbleFightInfoId ~= 0) then bubbleFightInfoId = 0 end\r\nend\r\n\r\nfunction updateFightInfo(turnLeft, teamDamage, forceDisplayUI)\r\n\tlocal turnLeft = toLong(turnLeft)\r\n\tlocal teamDamage = toLong(teamDamage)\r\n\r\n\tif (bubbleFightInfoId == 0) then\r\n\t\tbubbleFightInfoId = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_WEST\", 0, -60, false, 2147483647, true, \"interactiveBubbleDialog5\", 30000, 25000, \"onFightInfoClosed\")\r\n\tend\r\n\r\n\tBubbleText.setText(bubbleFightInfoId, \"japan.expo.2026.fight.info\", turnLeft, teamDamage)\r\n\r\n\tif (forceDisplayUI) then BubbleText.show(bubbleFightInfoId) end\r\nend\n\n-- [INIT] Variables globales\n-- \nfunction event_2753_24398()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_2753_24399()\n    local playerId = Context.getLeaderId()\r\n    \r\n    Mobile.setMobileVisible(playerId, false)\r\n    \r\n    Camera.setCamera(0.8, -23, 0, -4)\r\n    \r\n    onEnterInstance()\r\n    clearUI()\nend\n\n-- [EVENT] MONSTER_ACTION_EVENT - Lancement du combat\n-- \nfunction event_2753_24400()\n    local playerId = Context.getLeaderId()\r\n    \r\n    Mobile.setMobileVisible(playerId, true)\r\n    \r\n    Camera.attachCameraToMobile(playerId)\r\nend\n\n-- [EVENT] FIGHT_ENTER_ACTION_PHASE - Application états\n-- \nfunction event_2753_24401(turnLeft, teamDamage)\n    updateFightInfo(turnLeft, teamDamage, true)\nend\n\n-- EFFECT_EXECUTION - Mise à jour UI infos de combat (score)\n-- \nfunction event_2753_24403(turnLeft, teamDamage)\n    updateFightInfo(turnLeft, teamDamage, true)\nend\n\n-- EFFECT_EXECUTION - Mise à jour UI infos de combat (tours restants)\n-- \nfunction event_2753_24404(turnLeft, teamDamage)\n    updateFightInfo(turnLeft, teamDamage, true)\nend\n\n-- EFFECT_EXECUTION - Le joueur a gagné le combat\n-- \nfunction event_2753_24405()\n    \nend\n\n-- [EVENT] FIGHT_ENDED_IN_CLIENT - On ferme l'affichage\n-- \nfunction event_2753_24402(teamDamage, fightWon)\n    local teamDamage = toLong(teamDamage)\r\n    \r\n    if (toLong(fightWon) == 1) then\r\n    \tUI.writeLocalisedInChat(\"japan.expo.2025.fight.won\")\r\n    \tUI.writeLocalisedInChat(\"japan.expo.2026.fight.final.score.damage\", teamDamage)\r\n    end\r\n    \r\n    closeFightInfo()\nend\n\n-- FIGHT_ENDED_IN_CLIENT_EVENT - On reset les positions etc.\n-- \nfunction event_2753_24408()\n    local playerId = Context.getLeaderId()\r\n    \r\n    Mobile.setMobileVisible(playerId, false)\r\n    \r\n    Camera.setCamera(0.8, -23, 0, -4)\nend\n\n-- [EVENT] Victoire du combat - Enregistrement au classement\n-- \nfunction event_2753_24406()\n    \nend\n\n-- [TEST] Met fin au combat à la fin du tour de table\n-- \nfunction event_2753_24407()\n    \nend\n\n","functions":["tContains","prepareChatUI","prepareFollowQuestUI","prepareUI","prepareShortcuts","setWidgetVisible","clearWidgetVisible","setWidgetEnable","clearWidgetEnable","setUIColorTween","clearUIColorTweens","setUIParticle","setUIParticleBorder","clearUIParticles","addDialogLoadListener","clearDialogLoadListener","addDialogUnloadListener","clearDialogUnloadListener","addDialogEventListener","clearDialogEventListener","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","bubble","clearBubbles","setCompass","clearCompasses","createActor","clearActors","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","startCinematicContext","skipCinematic","stopCinematicContext","displayScreenEffect","clearALL","clearUI","clearListener","addButton","displayFightRules","onEnterInstance","hideMonster","showMonster","closeFightInfo","onFightInfoClosed","updateFightInfo","event_2753_24398","event_2753_24399","event_2753_24400","event_2753_24401","event_2753_24403","event_2753_24404","event_2753_24405","event_2753_24402","event_2753_24408","event_2753_24406","event_2753_24407"],"quest_calls":["UI.activateFollowAchievement(false)\r"],"dialogue_calls":[]},"scenario/2754.lua":{"source":"\n\n-- [INIT] Spawn Cwabes & Kralamours - 235 - Sufokia\n-- \nfunction event_2754_24410()\n    \nend\n\n","functions":["event_2754_24410"],"quest_calls":[],"dialogue_calls":[]},"scenario/2755.lua":{"source":"\n\n-- Enregistrement des Evènements Cyclique : Spawn de monstres\n-- Toutes les X min, on spawn les groupes de monstres\nfunction event_2755_24412()\n    \nend\n\n","functions":["event_2755_24412"],"quest_calls":[],"dialogue_calls":[]},"scenario/2756.lua":{"source":"function bossIdPlayInit(bossId, chefId,bouftouAId, bouftouBId, boufetteAId, boufetteBId)\r\n\tMobile.setMobilePosition(bossId, -2, -25, 8)\r\n\tMobile.setMobileDirection(bossId, 1)\r\n\tMobile.setMobileAnimation(bossId, \"AnimComp-Dormir-Boucle\")\r\n\tMobile.setMobilePosition(chefId, -4, -31, 8)\r\n\tMobile.setMobileDirection(chefId, 1)\r\n\tMobile.setMobileAnimation(chefId, \"AnimComp-Dormir-Boucle\")\r\n\tMobile.setMobilePosition(boufetteAId, -3, -33, 8)\r\n\tMobile.setMobileDirection(boufetteAId, 5)\r\n\tMobile.setMobileAnimation(boufetteAId, \"AnimReprod-Boucle\")\r\n\tMobile.setMobilePosition(bouftouAId, -3, -33, 8)\r\n\tMobile.setMobileDirection(bouftouAId, 5)\r\n\tMobile.setMobileAnimation(bouftouAId, \"AnimReprod-Boucle\")\r\n\tMobile.setMobilePosition(boufetteBId, -4, -26, 8)\r\n\tMobile.setMobileDirection(boufetteBId, 3)\r\n\tMobile.setMobileAnimation(boufetteBId, \"AnimReprod-Boucle\")\r\n\tMobile.setMobilePosition(bouftouBId, -4, -26, 8)\r\n\tMobile.setMobileDirection(bouftouBId, 3)\r\n\tMobile.setMobileAnimation(bouftouBId, \"AnimReprod-Boucle\")\r\nend\r\n\r\nfunction bossEndIdPlayInit(bossEndId)\r\n\t--Mobile.setMobilePosition(bossEndId, -29, -29, 14)\r\n\tMobile.setMobileDirection(bossEndId, 1)\r\nend\r\n\r\nfunction chefEndAIdPlayInit(chefEndAId)\r\n\t--Mobile.setMobilePosition(chefEndAId, -27, -33, 12)\r\n\tMobile.setMobileDirection(chefEndAId, 1)\r\n\tMobile.setMobileAnimation(chefEndAId, \"AnimComp-Dormir-Boucle\")\r\nend\r\n\r\nfunction boufetteEndAIdPlayInit(boufetteEndAId)\r\n\t--Mobile.setMobilePosition(boufetteEndAId, -26, -25, 12)\r\n\tMobile.setMobileDirection(boufetteEndAId, 3)\r\n\tMobile.setMobileAnimation(boufetteEndAId, \"AnimComp-Dormir-Boucle\")\r\nend\r\n\r\nfunction boufetteEndBIdPlayInit(boufetteEndBId)\r\n\t--Mobile.setMobilePosition(boufetteEndBId, -28, -32, 12)\r\n\tMobile.setMobileDirection(boufetteEndBId, 1)\r\n\tMobile.setMobileAnimation(boufetteEndBId, \"AnimComp-Dormir-Boucle\")\r\nend\r\n\r\nfunction chefEndBIdPlayInit(chefEndBId)\r\n\t--Mobile.setMobilePosition(chefEndBId, -28, -28, 14)\r\n\tMobile.setMobileDirection(chefEndBId, 7)\r\n\tMobile.setMobileAnimation(chefEndBId, \"AnimComp-Dormir-Boucle\")\r\nend\r\n\r\nfunction bouftouEndIdPlayInit(bouftouEndId)\r\n\t--Mobile.setMobilePosition(bouftouEndId, -27, -26, 12)\r\n\tMobile.setMobileDirection(bouftouEndId, 5)\r\n\tMobile.setMobileAnimation(bouftouEndId, \"AnimComp-Dormir-Boucle\")\r\nend\n\n-- INITIALISATION Serveur\n-- \nfunction event_2756_24413(bossId, chefId, bouftouAId, bouftouBId, boufetteAId, boufetteBId, bossEndId, chefEndAId, chefEndBId, boufetteEndAId, boufetteEndBId, bouftouEndId)\n    Mobile.addMobileCreationCallback(bossEndId, \"bossEndIdPlayInit\", bossEndId)\r\n    Mobile.addMobileCreationCallback(chefEndAId, \"chefEndAIdPlayInit\", chefEndAId)\r\n    Mobile.addMobileCreationCallback(chefEndBId, \"chefEndBIdPlayInit\", chefEndBId)\r\n    Mobile.addMobileCreationCallback(boufetteEndAId, \"boufetteEndAIdPlayInit\", boufetteEndAId)\r\n    Mobile.addMobileCreationCallback(boufetteEndBId, \"boufetteEndBIdPlayInit\", boufetteEndBId)\r\n    Mobile.addMobileCreationCallback(bouftouEndId, \"bouftouEndIdPlayInit\", bouftouEndId)\nend\n\n-- Joueur entre dans instance\n-- \nfunction event_2756_24414(bossEndId, chefEndAId, chefEndBId, boufetteEndAId, boufetteEndBId, bouftouEndId)\n    Mobile.addMobileCreationCallback(bossEndId, \"bossEndIdPlayInit\", bossEndId)\r\n    Mobile.addMobileCreationCallback(chefEndAId, \"chefEndAIdPlayInit\", chefEndAId)\r\n    Mobile.addMobileCreationCallback(chefEndBId, \"chefEndBIdPlayInit\", chefEndBId)\r\n    Mobile.addMobileCreationCallback(boufetteEndAId, \"boufetteEndAIdPlayInit\", boufetteEndAId)\r\n    Mobile.addMobileCreationCallback(boufetteEndBId, \"boufetteEndBIdPlayInit\", boufetteEndBId)\r\n    Mobile.addMobileCreationCallback(bouftouEndId, \"bouftouEndIdPlayInit\", bouftouEndId)\nend\n\n-- Combat 02 - Victoire\n-- \nfunction event_2756_24415()\n    UI.writeLocalisedInChat(\"door.unlocked\")\nend\n\n-- Combat 02 - Ouverture de la porte\n-- \nfunction event_2756_24416()\n    \nend\n\n-- Combat 03 - Victoire\n-- \nfunction event_2756_24417()\n    UI.writeLocalisedInChat(\"door.unlocked\")\nend\n\n-- Combat 03 - Ouverture de la porte\n-- \nfunction event_2756_24418()\n    \nend\n\n-- Combat 04 - Victoire\n-- \nfunction event_2756_24419()\n    \nend\n\n-- Combat 04 - Ouverture de la porte\n-- \nfunction event_2756_24420()\n    \nend\n\n-- Combat 05 - Victoire\n-- \nfunction event_2756_24421()\n    invoke(4000, 1, \"Particle.addParticleSystem\", 800202, -24, -27, 12, 0)\r\nend\n\n-- Combat 05 - Ouverture de la porte\n-- \nfunction event_2756_24422()\n    \nend\n\n","functions":["bossIdPlayInit","bossEndIdPlayInit","chefEndAIdPlayInit","boufetteEndAIdPlayInit","boufetteEndBIdPlayInit","chefEndBIdPlayInit","bouftouEndIdPlayInit","event_2756_24413","event_2756_24414","event_2756_24415","event_2756_24416","event_2756_24417","event_2756_24418","event_2756_24419","event_2756_24420","event_2756_24421","event_2756_24422"],"quest_calls":[],"dialogue_calls":[]},"scenario/2757.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\n\n-- [INIT] Inscription du joueur + Variables Locales\n-- \nfunction event_2757_24432()\n    \nend\n\n-- DIALOG_EXECUTED - Cinématique\n-- \nfunction event_2757_24433()\n    local playerId = Context.getLeaderId()\r\n    \r\n    startCinematicContext(1.2, playerId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 24433)\r\n    \r\n    fullScreen(1000, 5000, 1000)\r\n    \r\n    invoke_custom(0, 1, \"text\", 1000, 5000, 1000, \"quest.crimson.ereboria.00.00\")\r\n    \r\n    invoke_custom(7000, 1, \"skipCinematic\", 24433)\nend\n\n-- Fin de la cinématique - Reprise du dialogue avec Encre Noire\n-- \nfunction event_2757_24434()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_2757_24432","event_2757_24433","event_2757_24434"],"quest_calls":[],"dialogue_calls":[]},"scenario/2758.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\n-- les fonctions où on cache\r\nfunction hideMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, false)\r\nend\r\n\r\nfunction hidePart(monsterMobileId, partName)\r\n\tMobile.setPartVisible(monsterMobileId, false, partName)\r\nend\r\n\r\n-- les fonctions où on rend visible (à nouveau)\r\nfunction showMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, true)\r\nend\r\n\r\nfunction showPart(monsterMobileId, partName)\r\n\tMobile.setPartVisible(monsterMobileId, true, partName)\r\nend\n\n-- [INITIALISATION] Serveur\n-- \nfunction event_2758_24437()\n    \nend\n\n-- [EVENT] Le joueur entre sur la map, on cache le vieil amnesique\n-- \nfunction event_2758_24438(vieilAmnesiqueId)\n    Mobile.addMobileCreationCallback(vieilAmnesiqueId, \"hideMonster\", vieilAmnesiqueId)\nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","hideMonster","hidePart","showMonster","showPart","event_2758_24437","event_2758_24438"],"quest_calls":[],"dialogue_calls":[]},"scenario/2759.lua":{"source":"\n\n-- Enregistrement des Evènements : Début\n-- \nfunction event_2759_24439()\n    \nend\n\n-- Enregistrement des Evènements : Fin\n-- \nfunction event_2759_24440()\n    \nend\n\n-- Enregistrement des Evènements Cyclique : Spawn de monstres\n-- Toutes les X min, on spawn les groupes de monstres\nfunction event_2759_24441()\n    \nend\n\n","functions":["event_2759_24439","event_2759_24440","event_2759_24441"],"quest_calls":[],"dialogue_calls":[]},"scenario/2760.lua":{"source":"\n\n-- [INIT] Active les IE liés à l'Event\n-- Les IE doivent être initialement non utilisable pour que ce soit cohérent\nfunction event_2760_24442()\n    \nend\n\n","functions":["event_2760_24442"],"quest_calls":[],"dialogue_calls":[]},"scenario/2761.lua":{"source":"\n\n-- [INIT] Spawn Cwabes & Kralamours - 455 - Poup Island\n-- \nfunction event_2761_24443()\n    \nend\n\n","functions":["event_2761_24443"],"quest_calls":[],"dialogue_calls":[]},"scenario/2762.lua":{"source":"\n\n-- [INIT] Spawn portes et réceptacle\n-- \nfunction event_2762_24444()\n    \nend\n\n","functions":["event_2762_24444"],"quest_calls":[],"dialogue_calls":[]},"scenario/2763.lua":{"source":"\n\n-- [INIT] Désactive les IE liés à l'Event\n-- Les IE doivent être initialement non utilisable pour que ce soit cohérent\nfunction event_2763_24445()\n    \nend\n\n","functions":["event_2763_24445"],"quest_calls":[],"dialogue_calls":[]},"scenario/2764.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n-- TRIGGER CLIENT --\r\n-- 0 = Fin cinématique VIDEO | Déclenché par le callback Video.addVideoStopOrEndCallback\r\n-- 1 = Arrivée dans l'instance | Déclenché par onInstanceLoaded() callback par Event.runOnInstanceLoaded (cf code Global)\r\n-- 2 = Fin cinématique | Déclenché par stopCinematicContext() (cf code Global)\r\n-- 3 = Fermeture UI Fin de combat\r\n-- 4 = Clic sur le bon bouton de changement d'oriention (parmis les 4) dans UI worldAndFightBar pour s'orientation vers le monstre\r\n-- 5 = Fermeture UI Fiche combattant\r\n-- 6 = Clic sur le bouton de validation de la répartition dans UI Aptitudes\r\n-- 7 = Clic sur la boussole du bon objectif dans l'UI suivi de quête\r\n-- 8 = Fermeture UI Map Monde\r\n\r\n-- VARIABLE GLOBALE - SCRIPT --\r\n\r\nwidget_visible = {}\r\nwidget_enable = {}\r\nui_tweens = {}\r\nui_particles = {}\r\nui_listener_load = {}\r\nui_listener_unload = {}\r\nui_listener_event = {}\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\nscreenEffectId = nil\r\n\r\n-- VARIABLE GLOBALE - MOBILE CINEMATIQUE & TUTO --\r\n\r\nANM_otomai = {think=\"AnimComp-Special03\", talk=\"AnimComp-Special04-Debut\", show=\"AnimComp-Special05-Debut\", nice=\"AnimComp-Special07\", nope=\"AnimComp-Special08\", lol=\"AnimComp-Special09\", stop_it=\"AnimComp-Special10\", come_here=\"AnimComp-Special01\", wave_hit=\"AnimComp-Special02\", fly=\"AnimStatique-Oiseau\", cast=\"AnimSort-01\", supercast=\"AnimComp-Special11\", attack=\"AnimSort-Cast\", balance=\"AnimComp-Special06\"}\r\nANM_melee = {attack=\"AnimSort-Morsure\", glitch1=\"AnimComp-Glitch01\", glitch2=\"AnimComp-Glitch02\", glitch3=\"AnimComp-Glitch03\", roar=\"AnimComp-Agressif\"}\r\nANM_range = {attack=\"AnimSort-01\", glitch=\"AnimComp-Glitch\", dupli=\"AnimComp-Dupli\"}\r\nANM_boss = {attack1=\"AnimSort-Estoc\", attack2=\"AnimSort-Hrargh\", glitch=\"AnimComp-Glitch\", dupli=\"AnimComp-Dupli\", roar=\"AnimComp-Hurle\", ko = \"AnimKO-SortieOK\", death= \"AnimKO-SortieHS\"}\r\n\r\nNPC_otomai = Mobile.generateClientMobileId()\r\nNPC_otomai_gfx = 181404009\r\nNPC_otomai_particleZ = 10\r\nNPC_otomai_bubbleX = 10\r\nNPC_otomai_bubbleY = 70\r\n\r\nNPC_melee = Mobile.generateClientMobileId()\r\nNPC_meleeB = Mobile.generateClientMobileId()\r\nNPC_melee_gfx = 181404014\r\nNPC_melee_particleZ = 5\r\n\r\nNPC_range = Mobile.generateClientMobileId()\r\nNPC_range_gfx = 181404015\r\nNPC_range_particleZ = 3\r\n\r\nNPC_boss = Mobile.generateClientMobileId()\r\nNPC_boss_gfx = 181404012\r\nNPC_boss_particleZ = 8\r\n\r\nNPC_eni_wakfu = Mobile.generateClientMobileId()\r\nNPC_eni_wakfu_gfx = 181404034\r\nNPC_eni_wakfu_particleZ = 7\r\n\r\nNPC_eni_stasis = Mobile.generateClientMobileId()\r\nNPC_eni_stasis_gfx = 181404013\r\nNPC_eni_stasis_particleZ = 7\r\n\r\n_ACTOR_LIST = {NPC_otomai, NPC_melee, NPC_meleeB, NPC_range, NPC_boss, NPC_eni_wakfu, NPC_eni_stasis}\r\n\r\n-- VARIABLE GLOBALE - PARTICULE CINEMATIQUE & TUTO --\r\n\r\n-- UI TUTO\r\napsArrowBig = {6001069,6001070,6001071,6001072,6001073,6001074,6001075,6001076}\r\napsArrow = {6001061,6001062,6001063,6001064,6001065,6001066,6001067,6001068}\r\napsCenter = {ap=6001090, mp=6001091, wp=6001092, hp=6001093}\r\napsFollowBorder = -1548037644\r\n-- WORLD TUTO\r\napsCell = {white_border=800578, red_border=800579, white_arrow=800576, red_arrow=800577, white=800581, red=800582, show=78900}\r\n-- CINEMATIQUE\r\napsWave = {spawn=800573, wave=800574, hit=800575}\r\napsOtomai = {shield=-1814057071, transform=-1814057072, playershield = -1814057074}\r\napsCristal = {base=71071022, react=800580, shield=71071021}\r\napsBoss = {death=-1814057073}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n    for index, value in ipairs (tab) do\r\n\t\tif isEqual(value, val) then\r\n            return true\r\n        end\r\n    end\r\n\r\n    return false\t\r\nend\r\n\r\n-- FONCTION UI -- Replace le Chat en bas à gauche et le rend indéplaçable/déplaçable\r\nfunction prepareChatUI(movable, chatOffsetX)\r\n\tif not UI.isDialogLoaded(\"chatDialog0\") then return end\r\n\t\r\n\tif (not chatOffsetX) then chatOffsetX = 0 end\r\n\t\r\n\tUI.setPosition(\"chatDialog0\", chatOffsetX, 0)\r\n\tUI.setWindowMovable(\"chatDialog0\", movable)\r\nend\r\n\r\n-- FONCTION UI -- Replace le Suivi de Quête mi-hauteur à gauche et le rend indéplaçable/déplaçable\r\nfunction prepareFollowQuestUI(movable)\r\n    local dialogName = \"\"\r\n    if UI.isDialogLoaded(\"verticalFollowedAchievementsDialog\") then\r\n        dialogName = \"verticalFollowedAchievementsDialog\"\r\n    end\r\n    if UI.isDialogLoaded(\"followedAchievementsDialog\") then\r\n        dialogName = \"followedAchievementsDialog\"\r\n    end\r\n\r\n    if (dialogName == \"\") then\r\n        return\r\n    end\r\n\r\n    local screenH, screenW = UI.getWindowSize()\r\n    local x, y = UI.getPosition(dialogName)\r\n\r\n    UI.setPosition(dialogName, x, screenH / 4)\r\n    UI.setWindowMovable(dialogName, movable)\r\nend\r\n\r\n-- FONCTION UI -- Rend Visible/Invisible certains éléments des interfaces\r\nfunction prepareUI(visible)\r\n  --Interface Boutique & Cadeau\r\n  setWidgetVisible(\"topHudDialog\", \"optionShopButton\", visible)\r\n  setWidgetVisible(\"topHudDialog\", \"giftButton\", visible)\r\n\r\n  --UI sous le Coeur\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"wakfuStasisBar\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"xpBar\", visible)\r\n\r\n  --Boutons hors combat à droite du Coeur\r\n  setWidgetVisible(\"shortcutBarDialog\", \"previousButton\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"nextButton\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseShortcutBar1\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseShortcutBar2\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseShortcutBar3\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseShortcutBar4\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"shortcutBarItemButton\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"shortcutBarSpellButton\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseButtonContainerForTuto1\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseButtonContainerForTuto2\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseButtonContainerForTuto3\", visible)\r\n  setWidgetVisible(\"shortcutBarDialog\", \"openCloseButtonContainerForTuto4\", visible)\r\n\r\n  --Boutons hors combat à gauche de l'écran - barre d'interfaces\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"firstInterfaceBarBackground\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"secondInterfaceBarBackground\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"extraInterfaceBarDrawerButton\", visible)\r\n\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"fightInfoBtn\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"inventoryButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"buildSheetSetButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"craftButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"questsButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"dungeonButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"cosmeticsButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"tutorialBookButton\", visible)\r\n\r\n  --Boutons hors combat à gauche de l'écran - barre d'interfaces (deuxième barre)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"contactListButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"guildButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"companionsButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"nationButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"battlegroundButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"passportButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"emoteButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"encyclopediaButton\", visible)\r\n\r\n  --Boutons hors combat \"actions rapides\"\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"OverWorldActionsBackground\", visible)\r\n\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"dimensionalBagButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"mapButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"rideMountButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"miniMapButton\", visible)\r\n\r\n  --Boutons en combat à gauche du Coeur\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"FightActionsBackground\", visible)\r\n\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"giveUpButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"hideFightersButton\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"tacticalModeBtn\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"reportCellBtn\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"fightMarkerBtn\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"lockFightBtn\", visible)\r\n  setWidgetVisible(\"worldAndFightBarDialog\", \"resistanceOverheadBtn\", visible)\r\nend\r\n\r\n-- FONCTION SHORTCUT -- Rend Actif/Inactif certains raccourcis\r\nfunction prepareShortcuts(enabled, shortcutType)\r\n  if not shortcutType or shortcutType == \"WORLD\" then\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.world\", \"enterLeaveBag\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.world\", \"switchHero0\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.world\", \"switchHero1\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.world\", \"switchHero2\")\r\n  end\r\n  if not shortcutType or shortcutType == \"DISPLAY\" then\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"zoomIn\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"zoomOut\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"closeWindows\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"setLODLevel\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"setFightLODLevel\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"showHideNameOverheadsCommand\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"hideFightOccluders\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.display\", \"alphaMask\")\r\n  end\r\n  if not shortcutType or shortcutType == \"CHAT\" then\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.chat\", \"chat\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.chat\", \"lastContact\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.chat\", \"firstContact\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.chat\", \"autoCompletePlayerName\")\r\n    for bind=1, 9, 1 do\r\n      UI.setShortcutEnabled(enabled, \"shortcutCategory.shortcutBar\", \"bind\" .. toString(bind))\r\n    end\r\n  end\r\n\r\n  if not shortcutType or shortcutType == \"FIGHT\" then\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"fighterTransparency\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"switchTacticalView\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"nextSelectedFighter\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"giveUp\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"lockFight\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"reportCell\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"callHelp\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"displayHpBar\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"resetFightCamera\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"endPlacementAndTurn\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"closeCombatRight\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.fight\", \"closeCombatLeft\")\r\n  end\r\n  if not shortcutType or shortcutType == \"INTERFACE\" then\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"minimap\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"contactList\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"companionManagement\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"guild\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"craft\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"dungeonList\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"achievements\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"quests\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"emotes\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"ecosystem\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"climate\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"nation\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"partySearch\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"passport\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"almanax\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"tutorialBook\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"switchToDirectAttackCommand\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"map\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"spellsInventory\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"inventory\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"characterBook\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"osamodasSymbiot\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"shortcutBar0\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"shortcutBar1\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"shortcutBar2\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"shortcutBar3\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"additionalShortcutBar0\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"additionalShortcutBar1\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"additionalShortcutBar2\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"additionalShortcutBar3\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"changeShortcutBarType\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"downscaling\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"rewards\")\r\n\tUI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"battlegroundList\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"aptitudes\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"presets\")\r\n    UI.setShortcutEnabled(enabled, \"shortcutCategory.interface\", \"encyclopedia\")\r\n  end\r\n\r\n  -- On ne bloque pas les raccourcis de sorts finalement\r\n--   if not shortcutType or shortcutType == \"SHORTCUTBAR\" then\r\n--     for bar=0,3, 1 do\r\n--       for slot=0, 9, 1 do\r\n--         UI.setShortcutEnabled(enabled, \"shortcutCategory.shortcutBar\", \"shortcut\" .. toString(bar) .. toString(slot))\r\n--       end\r\n--     end\r\n--   end\r\nend\r\n\r\n-- FONCTION UI -- Rend Visible/Invisible un élément d'une interface\r\nfunction setWidgetVisible(dialogName, widgetName, visible)\r\n  if not UI.isDialogLoaded(dialogName) then return end\r\n\r\n  UI.setWidgetVisibility(dialogName, widgetName, visible)\r\n  table.insert(widget_visible, { name = dialogName, id = widgetName, state = visible })\r\nend\r\n\r\nfunction clearWidgetVisible()\r\n  local str = \"\"\r\n  for i=#widget_visible, 1, -1 do\r\n    str = str .. toString(widget_visible[i].name) .. \"@\" .. toString(widget_visible[i].id) .. \";\"\r\n    UI.setWidgetVisibility(widget_visible[i].name, widget_visible[i].id, true)\r\n  end\r\n\r\n  widget_visible = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearWidgetVisible\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Rend Actif/Inactif un élément d'une interface\r\nfunction setWidgetEnable(dialogName, widgetName, enable)\r\n  if not UI.isDialogLoaded(dialogName) then return end\r\n\r\n  UI.setWidgetEnabled(dialogName, widgetName, enable)\r\n  table.insert(widget_enable, {name = dialogName, id = widgetName, state = enable})\r\nend\r\n\r\nfunction clearWidgetEnable()\r\n  local str = \"\"\r\n  for i=#widget_enable, 1, -1 do\r\n    str = str .. toString(widget_enable[i].name) .. \"@\" .. toString(widget_enable[i].id) .. \";\"\r\n    UI.setWidgetEnabled(widget_enable[i].name, widget_enable[i].id, true)\r\n  end\r\n\r\n  widget_enable = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearWidgetEnable\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Ajoute/Retire une TweenParticle à un élément d'une interface\r\nfunction setUIColorTween(dialogName, widgetName, duration, loop, r1, g1, b1, a1, r2, g2, b2, a2)\r\n  if not UI.isDialogLoaded(dialogName) then return end\r\n\r\n  UI.addColorTween(dialogName, widgetName, duration, loop, r1, g1, b1, a1, r2, g2, b2, a2)\r\n  table.insert(ui_tweens, {name = dialogName, id = widgetName})\r\nend\r\n\r\nfunction clearUIColorTweens(dialogName, widgetName)\r\n  local str = \"\"\r\n  for i=#ui_tweens, 1, -1 do\r\n    if ((not dialogName) or (dialogName == ui_tweens[i].name)) and ((not widgetName) or (widgetName == ui_tweens[i].id)) then\r\n      str = str .. toString(ui_tweens[i].name) .. \"@\" .. toString(ui_tweens[i].id) .. \";\"\r\n      UI.removeColorTween(ui_tweens[i].name, ui_tweens[i].id)\r\n      table.remove(ui_tweens, i)\r\n    end\r\n  end\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearUIColorTweens\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Ajoute/Retire une Particle à un élément d'une interface\r\nfunction setUIParticle(dialogName, widgetName, apsFileName, x, y, alignment, level)\r\n  if not UI.isDialogLoaded(dialogName) then return end\r\n\r\n  local particleId = UI.addParticle(dialogName, widgetName, apsFileName, x, y, alignment, level)\r\n  table.insert(ui_particles, {name = dialogName, id = widgetName})\r\n\r\n  return particleId\r\nend\r\n\r\nfunction setUIParticleBorder(dialogName, widgetName, apsFileName, x, y, alignment, level, speed)\r\n  if not UI.isDialogLoaded(dialogName) then return end\r\n\r\n  local particleId = UI.addParticleToBorder(dialogName, widgetName, apsFileName, x, y, alignment, level, speed)\r\n  table.insert(ui_particles, {name = dialogName, id = widgetName})\r\n\r\n  return particleId\r\nend\r\n\r\nfunction clearUIParticles(dialogName, widgetName)\r\n  local str = \"\"\r\n  for i=#ui_particles, 1, -1 do\r\n    if ((not dialogName) or (dialogName == ui_particles[i].name)) and ((not widgetName) or (widgetName == ui_particles[i].id)) then\r\n      str = str .. toString(ui_particles[i].name) .. \"@\" .. toString(ui_particles[i].id) .. \";\"\r\n      UI.clearParticles(ui_particles[i].name, ui_particles[i].id)\r\n      table.remove(ui_particles, i)\r\n    end\r\n  end\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearUIParticles\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Enregistre/Supprime un callback à l'ouverture d'une interface\r\nfunction addDialogLoadListener(dialog, funcName, ...)\r\n  UI.addDialogLoadedListener(dialog, funcName, unpack(arg))\r\n  table.insert(ui_listener_load,  dialog)\r\nend\r\n\r\nfunction clearDialogLoadListener(dialogName)\r\n  local str = \"\"\r\n  for i=#ui_listener_load, 1, -1 do\r\n    if (not dialogName) or (dialogName == ui_listener_load[i]) then\r\n      str = str .. toString(ui_listener_load[i]) .. \";\"\r\n      UI.removeDialogLoadedListener(ui_listener_load[i])\r\n      table.remove(ui_listener_load, i)\r\n    end\r\n  end\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearDialogLoadListener\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Enregistre/Supprime un callback à la fermeture d'une interface\r\nfunction addDialogUnloadListener(dialog, funcName, ...)\r\n  UI.addDialogUnloadedListener(dialog, funcName, unpack(arg))\r\n  table.insert(ui_listener_unload, dialog)\r\nend\r\n\r\nfunction clearDialogUnloadListener(dialogName)\r\n  local str = \"\"\r\n  for i=#ui_listener_unload, 1, -1 do\r\n    if (not dialogName) or (dialogName == ui_listener_unload[i]) then\r\n      str = str .. toString(ui_listener_unload[i]) .. \";\"\r\n      UI.removeDialogUnloadedListener(ui_listener_unload[i])\r\n      table.remove(ui_listener_unload, i)\r\n    end\r\n  end\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearDialogUnloadListener\", str) end\r\nend\r\n\r\n-- FONCTION UI -- Enregistre/Supprime un callback sur un élément d'une interface\r\nfunction addDialogEventListener(dialog, id, eventType, funcName, ...)\r\n  if not UI.isDialogLoaded(dialog) then return end\r\n\r\n  UI.addEventListener(dialog, id, eventType, funcName, unpack(arg))\r\n  table.insert(ui_listener_event, {dialog=dialog, id=id, eventType=eventType, funcName=funcName})\r\nend\r\n\r\nfunction clearDialogEventListener(dialogName)\r\n  local str = \"\"\r\n  for i=#ui_listener_event, 1, -1 do\r\n    if (not dialogName) or (dialogName == ui_listener_event[i].dialog) then\r\n      str = str .. toString(ui_listener_event[i].dialog) .. \"@\" .. toString(ui_listener_event[i].id) .. \";\"\r\n      UI.removeEventListener(ui_listener_event[i].dialog, ui_listener_event[i].id, ui_listener_event[i].eventType, ui_listener_event[i].funcName)\r\n      table.remove(ui_listener_event, i)\r\n    end\r\n  end\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearDialogEventListener\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y , z, ...)\r\n  local particleId = Particle.addParticleSystem(particleFileId, x, y , z, unpack(arg))\r\n  table.insert(world_particles, particleId)\r\n\r\n  return particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n  local particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n  table.insert(world_particles, particleId)\r\n\r\n  return particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n  local str = \"\"\r\n  for i=#world_particles, 1, -1 do\r\n    str = str .. toString(world_particles[i]) .. \";\"\r\n    Particle.removeParticleSystem(world_particles[i])\r\n  end\r\n\r\n  world_particles = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n  BubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n  if isLower(mobileId, 0) then\r\n    BubbleText.setCharacterSpeak(mobileId, text)\r\n  else\r\n    if (not offsetY) then\r\n      local height = Mobile.getMobileHeight(mobileId)\r\n      if (not height) then height = 6 end\r\n\r\n      offsetY = height * 10\r\n    end\r\n\r\n    if (not offsetX) then offsetX = 0 end\r\n    if (not infiniteDuration) then infiniteDuration = false end\r\n\r\n    BubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n    UI.writeLocalisedInChat(text)\r\n  end\r\n\r\n  if (not tContains(bubbles, mobileId)) then\r\n    table.insert(bubbles, mobileId)\r\n  end\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n  local str = \"\"\r\n  for i = #bubbles, 1, -1 do\r\n    if (not mobileId) then\r\n      str = str .. toString(bubbles[i]) .. \";\"\r\n      BubbleText.closeBubbleAttachedTo(bubbles[i])\r\n    elseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n      str = str .. toString(bubbles[i]) .. \";\"\r\n      BubbleText.closeBubbleAttachedTo(bubbles[i])\r\n      table.remove(bubbles, i)\r\n    end\r\n  end\r\n\r\n  if (not mobileId) then bubbles = {} end\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n  local compassId = UI.addCompass(\"compass\", x, y, z)\r\n  table.insert(compasses, compassId)\r\n\r\n  return compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n  local str = \"\"\r\n  for i=#compasses, 1, -1 do\r\n    str = str .. toString(compasses[i]) .. \";\"\r\n    UI.removeCompass(compasses[i])\r\n  end\r\n\r\n  compasses = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height)\r\n  local mobileId = Mobile.generateClientMobileId()\r\n  Actor.createActor(mobileId, spriteName, worldX, worldY, worldZ, availableDirection)\r\n\r\n  if (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n  if (height) then Actor.setActorHeight(mobileId, height) end\r\n\r\n  table.insert(actors, mobileId)\r\n\r\n  return mobileId\r\nend\r\n\r\nfunction clearActors()\r\n  local str = \"\"\r\n  for i = #actors, 1, -1 do\r\n    str = str .. toString(actors[i]) .. \";\"\r\n    Actor.deleteActor(actors[i])\r\n  end\r\n\r\n  actors = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n  local taskId = invoke(delay, count, funcName, unpack(arg))\r\n  table.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n  local str = \"\"\r\n  for i=#invoke_tasks, 1, -1 do\r\n    str = str .. toString(invoke_tasks[i]) .. \";\"\r\n    interrupt(invoke_tasks[i])\r\n    desinvoke(invoke_tasks[i])\r\n  end\r\n\r\n  invoke_tasks = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n  invoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n  local taskId = setInterval(delay, funcName, unpack(arg))\r\n  table.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n  local str = \"\"\r\n  for i=#interval_tasks, 1, -1 do\r\n    str = str .. toString(interval_tasks[i]) .. \";\"\r\n    interrupt(interval_tasks[i])\r\n    desinvoke(interval_tasks[i])\r\n  end\r\n\r\n  interval_tasks = {}\r\n\r\n  if (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n  if (_DEBUG) then trace(\"startCinematicContext\") end\r\n\r\n  UI.manageFrame(\"World\", false)\r\n  UI.closeMRU()\r\n  UI.closeAllBags()\r\n  UI.setUIVisible(false)\r\n  UI.displayWideScreenBand(true)\r\n  Camera.setUserZoomLocked(true)\r\n\r\n  if (cameraMobileId ~= nil)  then\r\n    Camera.setMoveSpeedFactor(10000)\r\n    Camera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n  end\r\n\r\n  if (zoomFactor ~= nil)  then\r\n    Camera.setZoomFactor(zoomFactor)\r\n  end\r\n\r\n  if (musicId ~= nil)  then\r\n    Sound.playForcedMusic(musicId)\r\n  end\r\n\r\n  if (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\nfunction skipCinematic()\r\n  local player = Context.getLeaderId()\r\n\r\n  for x = 1, #_ACTOR_LIST do\r\n    Actor.deleteActor(_ACTOR_LIST[x])\r\n  end\r\n\r\n  UI.hideButton()\r\n  clearALL()\r\n  stopCinematicContext(1, player, true)\r\n  Mobile.setMobileVisible(player, true)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n  if (_DEBUG) then trace(\"stopCinematicContext\") end\r\n\r\n  UI.displayWideScreenBand(false)\r\n  UI.setUIVisible(true)\r\n  Camera.setUserZoomLocked(false)\r\n  UI.manageFrame(\"World\", true)\r\n\r\n  Camera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n  Camera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n  if (zoomFactor ~= nil) then\r\n    Camera.setZoomFactor(zoomFactor)\r\n  end\r\n\r\n  if (cameraMobileId ~= nil) then\r\n    Camera.attachCameraToMobile(cameraMobileId)\r\n  end\r\n\r\n  if (stopMusic) then\r\n    Sound.stopForcedMusic()\r\n  end\r\n\r\n  if (_DEBUG) then\r\n    UI.hideButton()\r\n  end\r\n\r\n  --TRIGGER\r\n  Server.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Affiche/Masque une texture à l'écran\r\nfunction displayScreenEffect(enable, fadeInDur, alphaDur, fadeOutDur, r, g, b, alpha)\r\n  if (_DEBUG) then trace(\"displayScreenEffect\") end\r\n\r\n  if not enable and screenEffectId ~= nil  then\r\n    --On retire le blackScreen\r\n    Effect.stopEffect(screenEffectId)\r\n  else\r\n    --On affiche un blackScreen à l'entrée dans l'instance le temps qu'elle soit complètement chargée\r\n    screenEffectId = Effect.createFullScreenSprite(fadeInDur, alphaDur, fadeOutDur, r, g, b, alpha)\r\n  end\r\nend\r\n\r\n-- FONCTION NETTOYAGE --\r\nfunction clearALL()\r\n  clearIntervalTasks()\r\n  clearInvokeTasks()\r\n  clearBubbles()\r\n  clearUIColorTweens()\r\n  clearUIParticles()\r\n  clearWorldParticles()\r\n  clearCompasses()\r\n  clearActors()\r\n\r\n  Focus.display(false)\r\n  UI.unloadTutorialDialog()\r\nend\r\n\r\n-- FONCTION NETTOYAGE --\r\nfunction clearUI(dialogName)\r\n  clearUIColorTweens(dialogName)\r\n  clearUIParticles(dialogName)\r\nend\r\n\r\n-- FONCTION NETTOYAGE --\r\nfunction clearListener(dialogName)\r\n  clearDialogLoadListener(dialogName)\r\n  clearDialogUnloadListener(dialogName)\r\n  clearDialogEventListener(dialogName)\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\nfunction onInstanceLoaded()\r\n    if (_DEBUG) then\r\n        trace(\"ON INSTANCE LOADED\")\r\n    end\r\n\r\n    UI.manageFrame(\"World\", true)\r\n    UI.setUIVisible(true)\r\n    displayScreenEffect(false)\r\n\r\n    -- TRIGGER\r\n    Server.triggerEvent(24446)\r\nend\n\n-- [INIT] Spawn portes et réceptacle\n-- \nfunction event_2764_24504()\n    \nend\n\n-- ENTER_INSTANCE - Inscription au scénario + notif\n-- \nfunction event_2764_24446()\n    if (_DEBUG) then\r\n        trace(\"ENTER INSTANCE\")\r\n    end\r\n    \r\n    Event.runOnInstanceLoaded(\"onInstanceLoaded\")\nend\n\n-- ENTER_INSTANCE - Portes\n-- \nfunction event_2764_24484()\n    function hideDoor()\r\n        World.setPictoAlpha(-3, -50, 4, 0, 1000)\r\n        World.setPictoAlpha(-2, -50, 4, 0, 1000)\r\n        World.setPictoAlpha(-7, -145, 2, 0, 1000)\r\n    end\r\n    \r\n    invoke(1000, 1, \"hideDoor\")\nend\n\n-- ENTER_INSTANCE - Cinématique (ACH 5673)\n-- \nfunction event_2764_24481()\n    function customSkip()\r\n    \tMobile.hideOtherPlayerMobile(false)\r\n    \tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n    \tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n      Server.triggerEvent(24481)\r\n    \tskipCinematic()\r\n    end\r\n    \r\n    Mobile.hideOtherPlayerMobile(true)\r\n    fullScreen(0, 14500, 1000)\r\n    \r\n    startCinematicContext(1.0, playerId)\r\n    \r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"customSkip\")\r\n    \r\n    -- \"Après plusieurs jours de navigation et de tempêtes diverses, vous arrivez sur la nouvelle île.\"\r\n    invoke_custom(01000, 1, \"text\", 500, 6000, 500, \"quest.heritage.saison.05.00\")\r\n    \r\n    -- \"Tout est conforme à la description qu'Encre Noire vous a faite, mais quelque chose cloche...\"\r\n    invoke_custom(08000, 1, \"text\", 500, 5000, 500, \"quest.heritage.saison.05.01\")\r\n    \r\n    invoke_custom(15000, 1, \"customSkip\")\nend\n\n-- Fin de cinématique - On notifie (ACH 5673)\n-- \nfunction event_2764_24482()\n    invoke(500, 1, \"Server.triggerEvent\", 24446)\nend\n\n-- RESOURCE_COLLECTED_EVENT - 10 Bananagrum (ACH 5677, VARACH 844)\n-- \nfunction event_2764_24483()\n    invoke(500, 1, \"Server.triggerEvent\", 24446)\nend\n\n-- Event fini - On notif au scénario\n-- \nfunction event_2764_24447()\n    invoke(500, 1, \"Server.triggerEvent\", 24447)\nend\n\n-- Ping serveur (via onInstanceLoaded ou IEaction) - Don jetons\n-- \nfunction event_2764_24448()\n    -- \"Don Jetons\"\r\n    \r\n    if (_DEBUG) then\r\n        trace(\"GIVE TOKENS\")\r\n    end\nend\n\n-- Collector Poup Island - Ouverture\n-- \nfunction event_2764_24485()\n    World.setPictoAlpha(-3, -50, 4, 1, 1000)\r\n    World.setPictoAlpha(-2, -50, 4, 1, 1000)\r\n    World.setPictoAlpha(-7, -145, 2, 1, 1000)\nend\n\n-- INTERACTIVE_ELEMENT_ACTIVATION - Tabouret mystérieur (ACH 5676)\n-- \nfunction event_2764_24486()\n    invoke(500, 1, \"Server.triggerEvent\", 24446)\nend\n\n-- INTERACTIVE_ELEMENT_ACTIVATION - Affiche énigmatique (ACH 5680)\n-- \nfunction event_2764_24513()\n    invoke(500, 1, \"Server.triggerEvent\", 24446)\nend\n\n-- POSITION_TRIGGER - Le joueur arrive au centre de l'île (ACH 5678)\n-- \nfunction event_2764_24492()\n    invoke(500, 1, \"Server.triggerEvent\", 24446)\nend\n\n","functions":["tContains","prepareChatUI","prepareFollowQuestUI","prepareUI","prepareShortcuts","setWidgetVisible","clearWidgetVisible","setWidgetEnable","clearWidgetEnable","setUIColorTween","clearUIColorTweens","setUIParticle","setUIParticleBorder","clearUIParticles","addDialogLoadListener","clearDialogLoadListener","addDialogUnloadListener","clearDialogUnloadListener","addDialogEventListener","clearDialogEventListener","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","bubble","clearBubbles","setCompass","clearCompasses","createActor","clearActors","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","startCinematicContext","skipCinematic","stopCinematicContext","displayScreenEffect","clearALL","clearUI","clearListener","fullScreen","text","onInstanceLoaded","event_2764_24504","event_2764_24446","event_2764_24484","hideDoor","event_2764_24481","customSkip","event_2764_24482","event_2764_24483","event_2764_24447","event_2764_24448","event_2764_24485","event_2764_24486","event_2764_24513","event_2764_24492"],"quest_calls":[],"dialogue_calls":[]},"scenario/2765.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\n-- les fonctions où on cache\r\nfunction hideMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, false)\r\nend\r\n\r\nfunction hidePart(monsterMobileId, partName)\r\n\tMobile.setPartVisible(monsterMobileId, false, partName)\r\nend\r\n\r\n-- les fonctions où on rend visible (à nouveau)\r\nfunction showMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, true)\r\nend\r\n\r\nfunction showPart(monsterMobileId, partName)\r\n\tMobile.setPartVisible(monsterMobileId, true, partName)\r\nend\n\n-- [INITIALISATION] Serveur\n-- \nfunction event_2765_24449()\n    \nend\n\n-- [EVENT] Le joueur entre sur la map, on cache le vieil amnesique bateau\n-- \nfunction event_2765_24450(vieilAmnesiqueBateauId)\n    Mobile.addMobileCreationCallback(vieilAmnesiqueBateauId, \"hideMonster\", vieilAmnesiqueBateauId)\nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","hideMonster","hidePart","showMonster","showPart","event_2765_24449","event_2765_24450"],"quest_calls":[],"dialogue_calls":[]},"scenario/2766.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\n-- les fonctions où on cache\r\nfunction hideMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, false)\r\nend\r\n\r\nfunction hidePart(monsterMobileId, partName)\r\n\tMobile.setPartVisible(monsterMobileId, false, partName)\r\nend\r\n\r\n-- les fonctions où on rend visible (à nouveau)\r\nfunction showMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, true)\r\nend\r\n\r\nfunction showPart(monsterMobileId, partName)\r\n\tMobile.setPartVisible(monsterMobileId, true, partName)\r\nend\n\n-- [INITIALISATION] Serveur\n-- \nfunction event_2766_24451()\n    \nend\n\n-- [EVENT] Le joueur entre sur la map, on cache Encre Noire dans sa maison\n-- \nfunction event_2766_24452(EncreNoireMaisonId)\n    Mobile.addMobileCreationCallback(EncreNoireMaisonId, \"hideMonster\", EncreNoireMaisonId)\nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","hideMonster","hidePart","showMonster","showPart","event_2766_24451","event_2766_24452"],"quest_calls":[],"dialogue_calls":[]},"scenario/2767.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\n-- les fonctions où on cache\r\nfunction hideMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, false)\r\nend\r\n\r\nfunction hidePart(monsterMobileId, partName)\r\n\tMobile.setPartVisible(monsterMobileId, false, partName)\r\nend\r\n\r\n-- les fonctions où on rend visible (à nouveau)\r\nfunction showMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, true)\r\nend\r\n\r\nfunction showPart(monsterMobileId, partName)\r\n\tMobile.setPartVisible(monsterMobileId, true, partName)\r\nend\n\n-- [INITIALISATION] Serveur\n-- \nfunction event_2767_24453()\n    \nend\n\n-- [EVENT] Le joueur entre sur la map, on cache le vieile amnésique \n-- \nfunction event_2767_24454(vieilAmnesiqueBontaId)\n    Mobile.addMobileCreationCallback(vieilAmnesiqueBontaId, \"hideMonster\", vieilAmnesiqueBontaId)\nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","hideMonster","hidePart","showMonster","showPart","event_2767_24453","event_2767_24454"],"quest_calls":[],"dialogue_calls":[]},"scenario/2768.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\n-- les fonctions où on cache\r\nfunction hideMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, false)\r\nend\r\n\r\nfunction hidePart(monsterMobileId, partName)\r\n\tMobile.setPartVisible(monsterMobileId, false, partName)\r\nend\r\n\r\n-- les fonctions où on rend visible (à nouveau)\r\nfunction showMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, true)\r\nend\r\n\r\nfunction showPart(monsterMobileId, partName)\r\n\tMobile.setPartVisible(monsterMobileId, true, partName)\r\nend\n\n-- [INITIALISATION] Serveur\n-- \nfunction event_2768_24455()\n    \nend\n\n-- [EVENT] Le joueur entre sur la map, on cache le vieil amnésique (instance 944)\n-- \nfunction event_2768_24456(VieilAmnesiqueKabrokId)\n    Mobile.addMobileCreationCallback(VieilAmnesiqueKabrokId, \"hideMonster\", VieilAmnesiqueKabrokId)\nend\n\n-- [EVENT] Le joueur entre sur la map, on cache le vieil amnésique (instance 945)\n-- \nfunction event_2768_24525(VieilAmnesiqueKabrokId2)\n    Mobile.addMobileCreationCallback(VieilAmnesiqueKabrokId2, \"hideMonster\", VieilAmnesiqueKabrokId2)\nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","hideMonster","hidePart","showMonster","showPart","event_2768_24455","event_2768_24456","event_2768_24525"],"quest_calls":[],"dialogue_calls":[]},"scenario/2769.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\n-- les fonctions où on cache\r\nfunction hideMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, false)\r\nend\r\n\r\nfunction hidePart(monsterMobileId, partName)\r\n\tMobile.setPartVisible(monsterMobileId, false, partName)\r\nend\r\n\r\n-- les fonctions où on rend visible (à nouveau)\r\nfunction showMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, true)\r\nend\r\n\r\nfunction showPart(monsterMobileId, partName)\r\n\tMobile.setPartVisible(monsterMobileId, true, partName)\r\nend\n\n-- [INITIALISATION] Serveur\n-- \nfunction event_2769_24457()\n    \nend\n\n-- [EVENT] Le joueur entre sur la map, on cache le vieil amnésique \n-- \nfunction event_2769_24458(VieilAmnesiquePatapoutreId)\n    Mobile.addMobileCreationCallback(VieilAmnesiquePatapoutreId, \"hideMonster\", VieilAmnesiquePatapoutreId)\nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","hideMonster","hidePart","showMonster","showPart","event_2769_24457","event_2769_24458"],"quest_calls":[],"dialogue_calls":[]},"scenario/2770.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\n-- les fonctions où on cache\r\nfunction hideMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, false)\r\nend\r\n\r\nfunction hidePart(monsterMobileId, partName)\r\n\tMobile.setPartVisible(monsterMobileId, false, partName)\r\nend\r\n\r\n-- les fonctions où on rend visible (à nouveau)\r\nfunction showMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, true)\r\nend\r\n\r\nfunction showPart(monsterMobileId, partName)\r\n\tMobile.setPartVisible(monsterMobileId, true, partName)\r\nend\r\n\r\nbubbleFightInfoId = 0\r\n\r\nfunction closeFightInfo()\r\n\tif (bubbleFightInfoId ~= nil and bubbleFightInfoId ~= 0) then BubbleText.close(bubbleFightInfoId) end\r\nend\r\n\r\nfunction onFightInfoClosed()\r\n\tif (bubbleFightInfoId ~= nil and bubbleFightInfoId ~= 0) then bubbleFightInfoId = 0 end\r\nend\r\n\r\nfunction updateFightInfo(turnLeft, teamDamage, forceDisplayUI, damageGoal)\r\n\tlocal turnLeft = toLong(turnLeft)\r\n\tlocal teamDamage = toLong(teamDamage)\r\n\tlocal damageGoal = toLong(damageGoal)\r\n\r\n\tif (bubbleFightInfoId == 0) then\r\n\t\tbubbleFightInfoId = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_WEST\", 0, -60, false, 2147483647, true, \"interactiveBubbleDialog5\", 30000, 25000, \"onFightInfoClosed\")\r\n\tend\r\n\r\n\tBubbleText.setText(bubbleFightInfoId, \"quest.pourpre.fight.info\", turnLeft, teamDamage, damageGoal)\r\n\r\n\tif (forceDisplayUI) then BubbleText.show(bubbleFightInfoId) end\r\nend\n\n-- [INITIALISATION] Serveur\n-- \nfunction event_2770_24459()\n    \nend\n\n-- [EVENT] Le joueur entre sur la map, on cache le vieil amnésique \n-- \nfunction event_2770_24460(vieilAmnesiqueGrotteId)\n    Mobile.addMobileCreationCallback(vieilAmnesiqueGrotteId, \"hideMonster\", vieilAmnesiqueGrotteId)\nend\n\n-- [EVENT] ENTER_INSTANCE - On inscrit le joueur au scénario\n-- \nfunction event_2770_24514()\n    \nend\n\n-- [EVENT] DIALOG_EXECUTED - Lancement du combat\n-- \nfunction event_2770_24515()\n    \nend\n\n-- [EVENT] FIGHT_ENTER_ACTION_PHASE - Application états\n-- \nfunction event_2770_24516(turnLeft, teamDamage, damageGoal, vieilAmnesiqueGrotteId)\n    updateFightInfo(turnLeft, teamDamage, true, damageGoal)\r\n    \r\n    Mobile.addMobileCreationCallback(vieilAmnesiqueGrotteId, \"hideMonster\", vieilAmnesiqueGrotteId)\nend\n\n-- EFFECT_EXECUTION - Mise à jour UI infos de combat (score)\n-- \nfunction event_2770_24517(turnLeft, teamDamage, damageGoal)\n    updateFightInfo(turnLeft, teamDamage, true, damageGoal)\nend\n\n-- EFFECT_EXECUTION - Mise à jour UI infos de combat (tours restants)\n-- \nfunction event_2770_24518(turnLeft, teamDamage, damageGoal)\n    updateFightInfo(turnLeft, teamDamage, true, damageGoal)\nend\n\n-- EFFECT_EXECUTION - Le joueur a gagné le combat\n-- \nfunction event_2770_24519()\n    \nend\n\n-- [EVENT] FIGHT_ENDED_IN_CLIENT - On ferme l'affichage\n-- \nfunction event_2770_24520()\n    closeFightInfo()\nend\n\n-- [EVENT] FIGHT_ENDED_IN_CLIENT - Défaite\n-- \nfunction event_2770_24522()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","hideMonster","hidePart","showMonster","showPart","closeFightInfo","onFightInfoClosed","updateFightInfo","event_2770_24459","event_2770_24460","event_2770_24514","event_2770_24515","event_2770_24516","event_2770_24517","event_2770_24518","event_2770_24519","event_2770_24520","event_2770_24522"],"quest_calls":[],"dialogue_calls":[]},"scenario/2771.lua":{"source":"\n\n-- INTERACTIVE_ELEMENT_ACTIVATION - Notif quête pourpre (ACH 5713 OBJ 11691)\n-- \nfunction event_2771_24461()\n    \nend\n\n","functions":["event_2771_24461"],"quest_calls":[],"dialogue_calls":[]},"scenario/2772.lua":{"source":"\n\n-- INTERACTIVE_ELEMENT_ACTIVATION - Notif quête pourpre\n-- \nfunction event_2772_24462()\n    \nend\n\n","functions":["event_2772_24462"],"quest_calls":[],"dialogue_calls":[]},"scenario/2773.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\n\n-- [INIT] Inscription du joueur + Variables Locales\n-- \nfunction event_2773_24468()\n    \nend\n\n-- DIALOG_EXECUTED - Cinématique\n-- \nfunction event_2773_24469()\n    local playerId = Context.getLeaderId()\r\n    \r\n    startCinematicContext(1.2, playerId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 24469)\r\n    \r\n    fullScreen(1000, 7000, 1000)\r\n    \r\n    invoke_custom(0, 1, \"text\", 1000, 7000, 1000, \"quest.crimson.kelba.00.00\")\r\n    \r\n    invoke_custom(9000, 1, \"skipCinematic\", 24469)\nend\n\n-- Fin de la cinématique - Validation de l'OBJ 11697 ACH 5714\n-- \nfunction event_2773_24470()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_2773_24468","event_2773_24469","event_2773_24470"],"quest_calls":[],"dialogue_calls":[]},"scenario/2774.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\n-- les fonctions où on cache\r\nfunction hideMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, false)\r\nend\r\n\r\nfunction hidePart(monsterMobileId, partName)\r\n\tMobile.setPartVisible(monsterMobileId, false, partName)\r\nend\r\n\r\n-- les fonctions où on rend visible (à nouveau)\r\nfunction showMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, true)\r\nend\r\n\r\nfunction showPart(monsterMobileId, partName)\r\n\tMobile.setPartVisible(monsterMobileId, true, partName)\r\nend\n\n-- [INITIALISATION] Serveur\n-- \nfunction event_2774_24471()\n    \nend\n\n-- [EVENT] Le joueur entre sur la map, on cache le vieil amnésique \n-- \nfunction event_2774_24472(VieilAmnesiqueGostofGrotteId)\n    Mobile.addMobileCreationCallback(VieilAmnesiqueGostofGrotteId, \"hideMonster\", VieilAmnesiqueGostofGrotteId)\nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","hideMonster","hidePart","showMonster","showPart","event_2774_24471","event_2774_24472"],"quest_calls":[],"dialogue_calls":[]},"scenario/2775.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\n\n-- [INIT] Inscription du joueur + Variables Locales\n-- \nfunction event_2775_24474()\n    \nend\n\n-- DIALOG_EXECUTED - Cinématique\n-- \nfunction event_2775_24475()\n    local playerId = Context.getLeaderId()\r\n    \r\n    startCinematicContext(1.2, playerId)\r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 24475)\r\n    \r\n    fullScreen(1000, 3000, 1000)\r\n    \r\n    invoke_custom(0, 1, \"text\", 1000, 3000, 1000, \"quest.crimson.ignemikhal.00.00\")\r\n    \r\n    invoke_custom(5000, 1, \"skipCinematic\", 24475)\nend\n\n-- Fin de la cinématique - dialogue avec Ignemikhal\n-- \nfunction event_2775_24476()\n    \nend\n\n-- [QUÊTE] MONSTER_ACTION_EVENT - Dofus Pourpre - ACH 5718 OBJ 11717\n-- \nfunction event_2775_24523(dofusPourpreId)\n    local playerId = Context.getLeaderId()\r\n    local dofusPourpre = toLong(dofusPourpreId)\r\n    \r\n    startCinematicContext(1.6, playerId)\r\n    \r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\", 24523)\r\n    Camera.attachCameraToMobile(playerId)\r\n    \r\n    invoke_custom(0, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Pointer\")\r\n    invoke_custom(2000, 1, \"InteractiveElement.setVisible\", dofusPourpre, false)\r\n    invoke_custom(2000, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-DofusPourpre\")\r\n    \r\n    invoke_custom(3500, 1, \"Particle.addParticleSystem\", 40049820, -25, -135, 12)\r\n    invoke_custom(5500, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-DofusPourpre-Fin\")\r\n    \r\n    invoke_custom(6500, 1, \"skipCinematic\", 24523)\nend\n\n-- [QUÊTE] CLIENT_TRIGGERED_EVENT - Fin de la cinématique\n-- \nfunction event_2775_24524()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_2775_24474","event_2775_24475","event_2775_24476","event_2775_24523","event_2775_24524"],"quest_calls":[],"dialogue_calls":[]},"scenario/2776.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\n\n-- [INIT] Inscription du joueur + Variables Locales\n-- \nfunction event_2776_24477()\n    \nend\n\n-- POSITION_TRIGGER - Tente de s'approcher d'ignemikhal\n-- \nfunction event_2776_24478()\n    local playerId = Context.getLeaderId()\r\n    \r\n    invoke(350, 1, \"Mobile.setMobileDirection\", playerId, 5)\r\n    invoke(350, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimEmote-Non\")\r\n    \r\n    invoke(100, 1, \"bubble\", playerId, \"quest.crimson.ignemikhal.01.00\")\nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_2776_24477","event_2776_24478"],"quest_calls":[],"dialogue_calls":[]},"scenario/2778.lua":{"source":"\n\n-- INTERACTIVE_ELEMENT_ACTION - Affiches de recrutement (ACH 5671)\n-- \nfunction event_2778_24480()\n    \nend\n\n","functions":["event_2778_24480"],"quest_calls":[],"dialogue_calls":[]},"scenario/2779.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\r\n\r\n-- les fonctions où on cache\r\nfunction hideMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, false)\r\nend\r\n\r\nfunction hidePart(monsterMobileId, partName)\r\n\tMobile.setPartVisible(monsterMobileId, false, partName)\r\nend\r\n\r\n-- les fonctions où on rend visible (à nouveau)\r\nfunction showMonster(monsterMobileId)\r\n\tMobile.setMobileVisible(monsterMobileId, true)\r\nend\r\n\r\nfunction showPart(monsterMobileId, partName)\r\n\tMobile.setPartVisible(monsterMobileId, true, partName)\r\nend\n\n-- [INITIALISATION] Serveur\n-- \nfunction event_2779_24487()\n    \nend\n\n-- [EVENT] Le joueur entre sur la map, on cache le vieil amnésique \n-- \nfunction event_2779_24488(IgnemikhalId)\n    Mobile.addMobileCreationCallback(IgnemikhalId, \"hideMonster\", IgnemikhalId)\nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","hideMonster","hidePart","showMonster","showPart","event_2779_24487","event_2779_24488"],"quest_calls":[],"dialogue_calls":[]},"scenario/2780.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\n\n-- [INIT] Inscription du joueur + Variables Locales\n-- \nfunction event_2780_24491()\n    \nend\n\n-- [EVENT] Quête Pourpre - Cinématique combat Ignemikhal\n-- \nfunction event_2780_24489()\n    -- \"Cinématique combat Ignemikhal\"\r\n    local playerId = Context.getLeaderId()\r\n    local ignemikhalId = createActor(1116505888, -23, -10, -4, 8, 1, 1)\r\n    local amnesiqueId = createActor(30, -23, -3, -4, 8, 7, 6)\r\n    Actor.equip(amnesiqueId, \"200300003\", \"CHEVEUXCUSTOM\")\r\n    Actor.equip(amnesiqueId, \"51314273\", \"VETEMENTCUSTOM\")\r\n    Actor.equip(amnesiqueId, \"13413954\", \"Chapeau\")\r\n    Actor.equip(amnesiqueId, \"11920941\", \"Bottes\")\r\n    Mobile.setPartColor(amnesiqueId, \"Pupille\", 0.09, 0.27, 0.33, 1)\r\n    Mobile.setPartColor(amnesiqueId, \"Peau\", 0.97, 0.78, 0.53, 1)\r\n    Mobile.setPartColor(amnesiqueId, \"Cheveux\", 0.58, 0.38, 0.09, 1)\r\n    \r\n    function customSkip()\r\n        Mobile.hideOtherPlayerMobile(false)\r\n        UI.displayWideScreenBand(true, 25, 500)\r\n        skipCinematic(24489)\r\n    end\r\n    \r\n    Mobile.hideOtherPlayerMobile(true)\r\n    startCinematicContext(0.8, playerId)\r\n    \r\n    UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"customSkip\")\r\n    \r\n    Mobile.setMobilePosition(playerId, -19, -10, -4)\r\n    Mobile.setMobileDirection(playerId, 5)\r\n    Mobile.setMobileAnimation(playerId, \"AnimStatique02\")\r\n    \r\n    invoke_custom(1, 1, \"Particle.addParticleSystem\", 801128, -29, -4, -4)\r\n    invoke_custom(1, 1, \"Particle.addParticleSystem\", 801128, -29, -5, -4)\r\n    invoke_custom(1, 1, \"Particle.addParticleSystem\", 801128, -29, -6, -4)\r\n    invoke_custom(1, 1, \"Particle.addParticleSystem\", 801128, -29, -7, -4)\r\n    invoke_custom(1, 1, \"Particle.addParticleSystem\",