-32, -1, -4)\r\n    invoke_custom(1, 1, \"Particle.addParticleSystem\", 801128, -32, 0, -4)\r\n    \r\n    invoke_custom(1, 1, \"Mobile.setMobileMovementStyle\",ignemikhalId, \"SLIDE\", \"SLIDE\")\r\n    invoke_custom(1, 1, \"Mobile.setMobileMovementStyle\",amnesiqueId, \"SLIDE\", \"SLIDE\")\r\n    invoke_custom(1, 1, \"Camera.attachCameraToMobile\", ignemikhalId)\r\n    \r\n    invoke_custom(700, 1, \"Mobile.setMobileAnimation\", ignemikhalId, \"AnimSort-2\")\r\n    \r\n    invoke_custom(1300, 1, \"Particle.addParticleSystem\", -1165085810, -23, -10, -4)\r\n    invoke_custom(1400, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimHit\")\r\n    invoke_custom(1700, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimKO-Debut\")\r\n    invoke_custom(1900, 1, \"Mobile.setMobileAnimation\", amnesiqueId, \"AnimEmote-Help\")\r\n    \r\n    -- Vieil Amnésique : Par ici face de Tom hâte !!\r\n    invoke_custom(2400, 1, \"bubble\", amnesiqueId, \"quest.crimson.ignemikhal.02.00\")\r\n    invoke_custom(4000, 1, \"clearBubbles\", amnesiqueId)\r\n    \r\n    invoke_custom(3200, 1, \"Mobile.setMobileDirection\", ignemikhalId, 3)\r\n    invoke_custom(3400, 1, \"Mobile.setMobileAnimation\", ignemikhalId, \"AnimSort-4-Debut\")\r\n    invoke_custom(3400, 1, \"Mobile.setMobileAnimation\", amnesiqueId, \"AnimEmote-Effrayee\")\r\n    invoke_custom(3600, 1, \"Mobile.setMobileDirection\", amnesiqueId, 1)\r\n    invoke_custom(3800, 1, \"Mobile.setMobileAnimation\", ignemikhalId, \"AnimSort-4-Boucle\")\r\n    invoke_custom(3900, 1, \"Mobile.setMobileDirection\", amnesiqueId, 5)\r\n    invoke_custom(4000, 1, \"Mobile.moveMobile\", ignemikhalId, -23, 9, -4)\r\n    \r\n    invoke_custom(4000, 1, \"Camera.setZoomSpeedFactor\", 0.15)\r\n    invoke_custom(4000, 1, \"Camera.setZoomFactor\", 2.5)\r\n    \r\n    invoke_custom(4300, 1, \"Mobile.setMobileDirection\", amnesiqueId, 7)\r\n    invoke_custom(4550, 1, \"Mobile.setMobileAnimation\", amnesiqueId, \"AnimCourse-Foufou-Boucle\")\r\n    invoke_custom(4600, 1, \"Mobile.setMobileDirection\", amnesiqueId, 3)\r\n    invoke_custom(4600, 1, \"Mobile.moveMobile\", amnesiqueId, -23, 11, -4)\r\n    \r\n    invoke_custom(4700, 1, \"Camera.attachCameraToMobile\", amnesiqueId)\r\n    invoke_custom(4700, 1, \"Camera.setMoveSpeedFactor\", 1)\r\n    \r\n    -- Vieil Amnésique : C'est le moment [#name] ! Fonce !!\r\n    invoke_custom(4600, 1, \"bubble\", amnesiqueId, \"quest.crimson.ignemikhal.02.01\")\r\n    invoke_custom(7500, 1, \"clearBubbles\", amnesiqueId)\r\n    \r\n    invoke_custom(6500, 1, \"Camera.attachCameraToMobile\", playerId)\r\n    \r\n    invoke_custom(7200, 1, \"Mobile.setMobileAnimation\", playerId, \"AnimKO-SortieOK\")\r\n    invoke_custom(7800, 1, \"Mobile.moveMobile\", playerId, -23, -21, 0)\r\n    \r\n    invoke_custom(11500, 1, \"customSkip\")\nend\n\n-- [EVENT] Fin de la cinématique - Validation ACH 5717 OBJ 11708\n-- \nfunction event_2780_24490()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_2780_24491","event_2780_24489","customSkip","event_2780_24490"],"quest_calls":[],"dialogue_calls":[]},"scenario/2781.lua":{"source":"-- CONSTANTE --\r\n\r\n_DEBUG = false\r\n_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR = 2.1\r\n_CAMERA_DEFAULT_MOVE_SPEED_FACTOR = 2.1\r\n\r\n\r\n\r\n-- VARIABLE GLOBALE --\r\n\r\nworld_particles = {}\r\nbubbles = {}\r\ncompasses = {}\r\ninvoke_tasks = {}\r\ninterval_tasks = {}\r\nactors = {}\r\n\r\n-- FONCTION LUA --\r\nfunction tContains(tab, val)\r\n\tfor index, value in ipairs(tab) do\r\n\t\tif isEqual(value, val) then\r\n\t\t\treturn true\r\n\t\tend\r\n\tend\r\n\r\n\treturn false\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement delayé\r\nfunction invoke_custom(delay, count, funcName, ...)\r\n\tlocal taskId = invoke(delay, count, funcName, unpack(arg))\r\n\ttable.insert(invoke_tasks, taskId)\r\nend\r\n\r\nfunction clearInvokeTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #invoke_tasks, 1, -1 do\r\n\t\tstr = str .. toString(invoke_tasks[i]) .. \";\"\r\n\t\tinterrupt(invoke_tasks[i])\r\n\t\tdesinvoke(invoke_tasks[i])\r\n\tend\r\n\r\n\tinvoke_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearInvokeTasks\", str) end\r\nend\r\n\r\n-- FONCTION TASK -- Enregistre/Interromp un évènement exécuté immédiatement puis répeté toutes les X secondes\r\nfunction setInterval_custom(delay, funcName, ...)\r\n\r\n\tinvoke_custom(0, 1, funcName, unpack(arg))\r\n\r\n\tlocal taskId = setInterval(delay, funcName, unpack(arg))\r\n\ttable.insert(interval_tasks, taskId)\r\nend\r\n\r\nfunction clearIntervalTasks()\r\n\tlocal str = \"\"\r\n\tfor i = #interval_tasks, 1, -1 do\r\n\t\tstr = str .. toString(interval_tasks[i]) .. \";\"\r\n\t\tinterrupt(interval_tasks[i])\r\n\t\tdesinvoke(interval_tasks[i])\r\n\tend\r\n\r\n\tinterval_tasks = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearIntervalTasks\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une Particle sur une cible ou une cellule du monde\r\nfunction setWorldParticleCell(particleFileId, x, y, z, ...)\r\n\tlocal particleId = Particle.addParticleSystem(particleFileId, x, y, z, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction setWorldParticleTarget(particleFileId, targetId, ...)\r\n\tlocal particleId = Particle.addParticleSystemToTargetWithOffset(particleFileId, targetId, unpack(arg))\r\n\ttable.insert(world_particles, particleId)\r\n\r\n\treturn particleId\r\nend\r\n\r\nfunction clearWorldParticles()\r\n\tlocal str = \"\"\r\n\tfor i = #world_particles, 1, -1 do\r\n\t\tstr = str .. toString(world_particles[i]) .. \";\"\r\n\t\tParticle.removeParticleSystem(world_particles[i])\r\n\tend\r\n\r\n\tworld_particles = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearWorldParticles\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une boussolle sur une cellule du monde\r\nfunction setCompass(x, y, z)\r\n\tlocal compassId = UI.addCompass(\"compass\", x, y, z)\r\n\ttable.insert(compasses, compassId)\r\n\r\n\treturn compassId\r\nend\r\n\r\nfunction clearCompasses()\r\n\tlocal str = \"\"\r\n\tfor i = #compasses, 1, -1 do\r\n\t\tstr = str .. toString(compasses[i]) .. \";\"\r\n\t\tUI.removeCompass(compasses[i])\r\n\tend\r\n\r\n\tcompasses = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearCompasses\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire un actor sur une cellule du monde\r\n\r\nfunction createActor(spriteName, worldX, worldY, worldZ, availableDirection, direction, height, copyMobileId)\r\n\tlocal mobileId = Mobile.generateClientMobileId()\r\n\tlocal gfxId = spriteName\r\n\tlocal canCopy = copyMobileId and Mobile.isMobile(copyMobileId)\r\n\tif (canCopy) then\r\n\t\tgfxId = Mobile.getMobileGFX(copyMobileId)\r\n\tend\r\n\r\n\tActor.createActor(mobileId, gfxId, worldX, worldY, worldZ, availableDirection)\r\n\tif (direction) then Mobile.setMobileDirection(mobileId, direction) end\r\n\tif (height) then Actor.setActorHeight(mobileId, height) end\r\n\tif (canCopy) then\r\n\t\tActor.copyActorFrom( copyMobileId, mobileId)\r\n\tend\r\n\ttable.insert(actors, mobileId)\r\n\r\n\treturn mobileId\r\nend\r\nfunction clearActors()\r\n\tlocal str = \"\"\r\n\tfor i = #actors, 1, -1 do\r\n\t\tstr = str .. toString(actors[i]) .. \";\"\r\n\t\tActor.deleteActor(actors[i])\r\n\tend\r\n\r\n\tactors = {}\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearActors\", str) end\r\nend\r\n\r\n-- FONCTION WORLD -- Ajoute/Retire une bulle de dialogue à un mobile\r\nfunction bubble(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, ...)\r\n\tBubbleText.closeBubbleAttachedTo(mobileId)\r\n\r\n\tif isLower(mobileId, 0) then\r\n\t\tBubbleText.setCharacterSpeak(mobileId, text)\r\n\telse\r\n\t\tif (not offsetY) then\r\n\t\t\tlocal height = Mobile.getMobileHeight(mobileId)\r\n\t\t\tif (not height) then height = 6 end\r\n\r\n\t\t\toffsetY = height * 10\r\n\t\tend\r\n\r\n\t\tif (not offsetX) then offsetX = 0 end\r\n\t\tif (not infiniteDuration) then infiniteDuration = false end\r\n\r\n\t\tBubbleText.showText(mobileId, text, offsetX, offsetY, infiniteDuration, funcOnEnd, unpack(arg))\r\n\t\tUI.writeLocalisedInChat(text)\r\n\tend\r\n\r\n\tif (not tContains(bubbles, mobileId)) then\r\n\t\ttable.insert(bubbles, mobileId)\r\n\tend\r\nend\r\n\r\nfunction clearBubbles(mobileId)\r\n\tlocal str = \"\"\r\n\tfor i = #bubbles, 1, -1 do\r\n\t\tif (not mobileId) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\telseif (mobileId ~= nil and isEqual(bubbles[i], mobileId)) then\r\n\t\t\tstr = str .. toString(bubbles[i]) .. \";\"\r\n\t\t\tBubbleText.closeBubbleAttachedTo(bubbles[i])\r\n\t\t\ttable.remove(bubbles, i)\r\n\t\tend\r\n\tend\r\n\r\n\tif (not mobileId) then bubbles = {} end\r\n\r\n\tif (_DEBUG and str ~= \"\") then trace(\"clearBubbles\", str) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Démarre un contexte de cinématique\r\nfunction startCinematicContext(zoomFactor, cameraMobileId, musicId)\r\n\tif (_DEBUG) then trace(\"startCinematicContext\", zoomFactor, cameraMobileId, musicId) end\r\n\r\n    FightEvent.addFighterJoinFightCallback(Context.getLeaderId(), \"skipCinematic\")\r\n\r\n\tUI.manageFrame(\"World\", false)\r\n\tUI.setShortcutEnabled(false)\r\n\tUI.setShortcutUsable(false)\r\n\tUI.closeMRU()\r\n\tUI.closeAllBags()\r\n\tUI.setUIVisible(false)\r\n\tUI.displayWideScreenBand(true)\r\n\tCamera.setUserZoomLocked(true)\r\n\tUI.setToastsEnabled(false)\r\n\t\r\n    Actor.forceDismount(Context.getLeaderId())\r\n\r\n\tif (cameraMobileId ~= nil) then\r\n\t\tCamera.setMoveSpeedFactor(10000)\r\n\t\tCamera.attachCameraToMobile(cameraMobileId, \"Camera.setMoveSpeedFactor\", _CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\tend\r\n\r\n\tif (zoomFactor ~= nil) then\r\n\t\tCamera.setZoomFactor(zoomFactor)\r\n\tend\r\n\r\n\tif (musicId ~= nil) then\r\n\t\tSound.playForcedMusic(musicId)\r\n\tend\r\n\r\n\tif (_DEBUG) then UI.displayButton(true, \"scenario.endKinematic.confirmEscape\", \"scenario.endKinematic\", \"skipCinematic\") end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Termine un contexte de cinématique\r\nfunction stopCinematicContext(zoomFactor, cameraMobileId, stopMusic)\r\n\tif (_DEBUG) then trace(\"stopCinematicContext\", zoomFactor, cameraMobileId, stopMusic) end\r\n\r\n\tUI.manageFrame(\"World\", true)\r\n\tUI.setShortcutEnabled(true)\r\n\tUI.setShortcutUsable(true)\r\n\tUI.displayWideScreenBand(false)\r\n\tUI.setUIVisible(true)\r\n\tCamera.setUserZoomLocked(false)\r\n\r\n\tCamera.setZoomSpeedFactor(_CAMERA_DEFAULT_ZOOM_SPEED_FACTOR)\r\n\tCamera.setMoveSpeedFactor(_CAMERA_DEFAULT_MOVE_SPEED_FACTOR)\r\n\r\n\tif (zoomFactor ~= nil) then Camera.setZoomFactor(zoomFactor) end\r\n\r\n\tif (cameraMobileId ~= nil) then Camera.attachCameraToMobile(cameraMobileId) end\r\n\r\n\tif (fullScreenId ~= nil) then Effect.stopEffect(fullScreenId) end\r\n\r\n\tif (textId ~= nil) then Effect.stopEffect(textId) end\r\n\r\n\tif (stopMusic) then Sound.stopForcedMusic() end\r\n\r\n\tMobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\tFightEvent.removeCallback(Context.getLeaderId(), \"FIGHTER_JOIN_FIGHT\")\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(2)\r\nend\r\n\r\n-- FONCTION CINEMATIQUE --\r\nfunction skipCinematic(eventId)\r\n\tif (_DEBUG) then trace(\"skipCinematic\", eventId) end\r\n\tlocal playerId = Context.getLeaderId()\r\n\tMobile.setMobileAnimation(playerId, \"AnimStatique\")\r\n    Actor.restoreMountStatus(playerId)\r\n    Mobile.hideOtherPlayerMobile(false)\r\n\r\n\tclearCinematic()\r\n\tstopCinematicContext(1, Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION CINEMATIQUE -- Permet de nettoyer les éléments utilisés durant une cinématique --\r\nfunction clearCinematic()\r\n\tif (_DEBUG) then trace(\"clearCinematic\") end\r\n\r\n\tif clearIntervalTasks then clearIntervalTasks() end\r\n\tif clearInvokeTasks then clearInvokeTasks() end\r\n\tif clearBubbles then clearBubbles() end\r\n\tif clearWorldParticles then clearWorldParticles() end\r\n\tif clearCompasses then clearCompasses() end\r\n\tif clearActors then clearActors() end\r\n\r\n\tFocus.display(false)\r\n\tUI.hideButton()\r\n\tUI.unloadTutorialDialog()\r\n\tUI.setToastsEnabled(true)\r\nend\r\n\r\n-- FONCTION VIDEO -- Démarre un contexte de vidéo\r\nfunction startVideoContext()\r\n\tif (_DEBUG) then trace(\"startVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", false)\r\n        UI.closeMRU()\r\n        UI.closeAllBags()\r\n        UI.setUIVisible(false)\r\n        UI.setShortcutUsable(false)\r\n        UI.setShortcutEnabled(false)\r\n        Camera.setUserZoomLocked(true)\r\n\tend\r\nend\r\n\r\n-- FONCTION VIDEO -- Termine un contexte de vidéo\r\nfunction stopVideoContext()\r\n\tif (_DEBUG) then trace(\"stopVideoContext\") end\r\n\r\n    if (Video.videoAvailable()) then\r\n        UI.manageFrame(\"World\", true)\r\n        UI.setUIVisible(true)\r\n        UI.setShortcutUsable(true)\r\n        UI.setShortcutEnabled(true)\r\n        Camera.setUserZoomLocked(false)\r\n\tend\r\n\r\n    Mobile.setMobileVisible(Context.getLeaderId(), true)\r\n\r\n\t--TRIGGER\r\n\tServer.triggerEvent(4)\r\nend\r\n\r\n-- FONCTION VIDEO --\r\nfunction skipVideo(eventId)\r\n\tif (_DEBUG) then trace(\"skipVideo\", eventId) end\r\n\r\n\tclearVideo()\r\n\tstopVideoContext()\r\n\r\n\t--TRIGGER\r\n\tif (eventId ~= nil) then Server.triggerEvent(eventId) end\r\nend\r\n\r\n-- FONCTION VIDEO -- Permet de nettoyer les éléments utilisés durant une vidéo --\r\nfunction clearVideo()\r\n\tif (_DEBUG) then trace(\"clearVideo\") end\r\nend\r\n\r\n-- FONCTION TEXTE NARRATEUR - Permet d'afficher des textes de narration en plein écran\r\nfunction fullScreen(fadein, duration, fadeout)\r\n\tfullScreenId = Effect.createFullScreenSprite(fadein, duration, fadeout, 0.0, 0.0, 0.0)\r\nend\r\n\r\nfunction text(fadein, duration, fadeout, translationKey)\r\n\ttextId = UI.createFullScreenText(fadein, duration, fadeout, translationKey, 0.8, 0.8, 0.8, 1.0, \"bagnard\", 40, 4)\r\nend\n\n-- [INIT] Inscription du joueur + Variables Locales\n-- \nfunction event_2781_24493()\n    \nend\n\n-- EVENT - Téléportation zone 2 après remise des ressources à Ignemikhal\n-- \nfunction event_2781_24494()\n    \nend\n\n","functions":["tContains","invoke_custom","clearInvokeTasks","setInterval_custom","clearIntervalTasks","setWorldParticleCell","setWorldParticleTarget","clearWorldParticles","setCompass","clearCompasses","createActor","clearActors","bubble","clearBubbles","startCinematicContext","stopCinematicContext","skipCinematic","clearCinematic","startVideoContext","stopVideoContext","skipVideo","clearVideo","fullScreen","text","event_2781_24493","event_2781_24494"],"quest_calls":[],"dialogue_calls":[]},"scenario/504.lua":{"source":"\n\n-- [INITIALISATION] Variables\n-- \nfunction event_504_17968()\n    \nend\n\n-- [INIT] ENTER_INSTANCE - Inscription au scénario\n-- \nfunction event_504_6371(randomAffixe)\n    trace(\"ENTER\", randomAffixe)\nend\n\n-- DUNGEON_DIFFICULTY_CHANGED - Refresh les Bonus Stasis + Notification sur tous les joueurs\n-- \nfunction event_504_18077(dungeonDifficulty)\n    local difficulty = toLong(dungeonDifficulty)\r\n    \r\n    --UI.displaySplashText(\"dungeon.stasis.difficulty.changed\", difficulty)\r\n    \r\n    local bubble = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_EAST\", -75, -50, false, 10000, true, \"interactiveBubbleDialog4\")\r\n    \r\n    BubbleText.setText(bubble, \"dungeon.stasis.difficulty.changed\", difficulty)\r\n    BubbleText.show(bubble)\nend\n\n-- DUNGEON_LADDER_CANCELLED - Notification sur tous les joueurs\n-- \nfunction event_504_18644()\n    local bubble = BubbleText.prepareInteractiveBubbleFloating(\"NORTH_EAST\", -75, -50, false, 10000, true, \"interactiveBubbleDialog4\")\r\n    \r\n    BubbleText.setText(bubble, \"dungeon.stasis.ladder.cancelled\")\r\n    BubbleText.show(bubble)\nend\n\n-- PLAYERS_WON_FIGHT - Reroll affixe Stasis\n-- \nfunction event_504_18325(randomAffixe)\n    trace(\"REROLL\", randomAffixe)\nend\n\n-- MONSTER_WON_FIGHT - Interdit le Spawn de Mimic\n-- \nfunction event_504_18063()\n    \nend\n\n-- FIGHT_ENTER_ACTION_PHASE - Roll pour savoir si Spawn de Mimic\n-- \nfunction event_504_17970()\n    \nend\n\n-- FIGHT_ENTER_ACTION_PHASE - Applique l'état Mimic sur 1 monstre aléatoire\n-- \nfunction event_504_18064()\n    \nend\n\n-- FIGHT_ENTER_ACTION_PHASE - Applique l'état Caractéristiques Stasis sur tous les monstres\n-- \nfunction event_504_18629()\n    \nend\n\n-- FIGHT_ENTER_ACTION_PHASE - Applique l'état Affixe Stasis rollé sur tous les monstres\n-- \nfunction event_504_19782()\n    \nend\n\n-- #FIGHT_ENTER_ACTION_PHASE - Applique l'état Gameplay Stasis sur le Boss\n-- \nfunction event_504_19795()\n    \nend\n\n-- ADMIN - Affixe Stasis +1\n-- \nfunction event_504_19783(randomAffixe)\n    trace(\"AFFIX\", randomAffixe)\nend\n\n-- ADMIN - Affixe Stasis -1\n-- \nfunction event_504_19784(randomAffixe)\n    trace(\"AFFIX\", randomAffixe)\nend\n\n-- [BETA] Ecoute quand le boss est tué\n-- \nfunction event_504_19787()\n    \nend\n\n-- [BETA] Ecoute quand le boss est tué\n-- \nfunction event_504_19788()\n    trace(\"REWARD BETA ACTIVE\")\nend\n\n","functions":["event_504_17968","event_504_6371","event_504_18077","event_504_18644","event_504_18325","event_504_18063","event_504_17970","event_504_18064","event_504_18629","event_504_19782","event_504_19795","event_504_19783","event_504_19784","event_504_19787","event_504_19788"],"quest_calls":[],"dialogue_calls":[]},"scenario/613.lua":{"source":"\n\n-- [INIT] ENTER_INSTANCE\n-- \nfunction event_613_20019()\n    \nend\n\n-- [EVENT] Arrivée d'un prisonnier ou joueur qui se rend au PNJ - Affichage des infos\n-- \nfunction event_613_3784()\n    local playerId = Context.getLeaderId()\r\n    \r\n    Mobile.setMobileVisible(playerId, false)\r\n    invoke(3000, 1, \"animChute\")\r\n    \r\n    function animChute()\r\n    \tMobile.setMobileVisible(playerId, true)\r\n    \tMobile.setMobileDirection(playerId, 1)\r\n    \tMobile.setMobileAnimation(playerId, \"AnimIncarnam-Chute-Fin\")\r\n    \tUI.loadTutorialDialog(\"tuto34\", \"nation.prison.title\", \"nation.prison.start\")\r\n    end\nend\n\n-- [EVENT] Le joueur utilise la porte de Cellule - Peine terminée\n-- \nfunction event_613_19998()\n    local playerId = Context.getLeaderId()\r\n    Mobile.setMobileAnimation(playerId, \"AnimEmote-Victoire\")\nend\n\n-- [EVENT] Le joueur utilise la porte de Cellule - Peine en cours\n-- \nfunction event_613_20001()\n    local playerId = Context.getLeaderId()\r\n    Mobile.setMobileAnimation(playerId, \"AnimEmote-Non\")\nend\n\n-- [EVASION] Un joueur tente de s'évader avec la Grille\n-- \nfunction event_613_20002()\n    \nend\n\n-- [EVASION] Evasion réussie - Amakna\n-- \nfunction event_613_20003()\n    \nend\n\n-- [EVASION] Evasion réussie - Bonta\n-- \nfunction event_613_20006()\n    \nend\n\n-- [EVASION] Evasion réussie - Brâkmar\n-- \nfunction event_613_20009()\n    \nend\n\n-- [EVASION] Evasion réussie - Sufokia\n-- \nfunction event_613_20012()\n    \nend\n\n-- [EVASION] Evasion réussie - COMMUN\n-- \nfunction event_613_20017()\n    local playerId = Context.getLeaderId()\r\n    Mobile.setMobileAnimation(playerId, \"AnimInteraction-Fin01\")\nend\n\n-- [EVASION] Evasion ratée - COMMUN\n-- \nfunction event_613_20018()\n    local playerId = Context.getLeaderId()\r\n    \r\n    UI.writeLocalisedInChat(\"chat.lime\")\r\n    Mobile.setMobileAnimation(playerId, \"AnimInteraction-Fin02\")\nend\n\n-- [EVENT] Le joueur à PDC > 0 - Notification\n-- \nfunction event_613_20015()\n    local playerId = Context.getLeaderId()\r\n    BubbleText.showText(playerId, \"nation.prison.jail.finish\", 0, 60, false)\nend\n\n-- [EVENT] Activation des réceptacles\n-- Séb : ajout d'un EventTriggerer() sinon le critère va être évalué sur tous les utilisateurs du scénario\nfunction event_613_20016(ieId)\n    local playerId = Context.getLeaderId()\r\n    Mobile.setMobileAnimation(playerId, \"AnimInteraction-AllumerTorche\")\nend\n\n","functions":["event_613_20019","event_613_3784","animChute","event_613_19998","event_613_20001","event_613_20002","event_613_20003","event_613_20006","event_613_20009","event_613_20012","event_613_20017","event_613_20018","event_613_20015","event_613_20016"],"quest_calls":[],"dialogue_calls":[]},"scenario/983.lua":{"source":"playerId = Context.getPlayer()\n\n-- TP dans la bonne cellule de prison\n-- \nfunction event_983_19391()\n    local playerId = Context.getLeaderId()\r\n    \r\n    Mobile.setMobileVisible(playerId, false)\nend\n\n-- TP dans la bonne cellule de prison\n-- \nfunction event_983_19417()\n    local playerId = Context.getLeaderId()\r\n    \r\n    Mobile.setMobileVisible(playerId, true)\r\n    Mobile.setMobileDirection(playerId, 1)\r\n    Mobile.setMobileAnimation(playerId, \"AnimIncarnam-Chute-Fin\")\r\n    UI.loadTutorialDialog(\"tuto34\", \"nation.prison.title\", \"nation.prison.start\")\nend\n\n","functions":["event_983_19391","event_983_19417"],"quest_calls":[],"dialogue_calls":[]},"scenario/985.lua":{"source":"\n\n-- Capture-Passeport-TpCellule\n-- Séb : on envoie vers le scénario 983 et non plus le 986 qui semble faire la même chose\nfunction event_985_6559()\n    \nend\n\n","functions":["event_985_6559"],"quest_calls":[],"dialogue_calls":[]},"scenario/986.lua":{"source":"\n\n-- On set le respawn du joueur puis on force le respawn\n-- \nfunction event_986_19390()\n    \nend\n\n","functions":["event_986_19390"],"quest_calls":[],"dialogue_calls":[]},"scenario/987.lua":{"source":"playerId=Context.getPlayer()\n\n-- Le joueur utilise la porte (visiteur)\n-- \nfunction event_987_7953()\n    --UI.pushPetMessage(0, \"jail.door.locked\", false)\r\n    Mobile.setMobileAnimation(playerId, \"AnimEmote-Non\")\r\nend\n\n-- Sortie Cellule #01 (peine terminée)\n-- \nfunction event_987_7785()\n    --UI.pushPetMessage(0, \"prison.gelutin.exit\", false)\r\n    Mobile.setMobileAnimation(playerId, \"AnimEmote-Victoire\")\r\nend\n\n-- Sortie Cellule #02 (peine terminée)\n-- \nfunction event_987_7781()\n    --UI.pushPetMessage(0, \"prison.gelutin.exit\", false)\r\n    Mobile.setMobileAnimation(playerId, \"AnimEmote-Victoire\")\r\nend\n\n-- Sortie Cellule #03 (peine terminée)\n-- \nfunction event_987_7782()\n    --UI.pushPetMessage(0, \"prison.gelutin.exit\", false)\r\n    Mobile.setMobileAnimation(playerId, \"AnimEmote-Victoire\")\r\nend\n\n-- Sortie Cellule (peine en cours)\n-- \nfunction event_987_7780()\n    Mobile.setMobileAnimation(playerId, \"AnimEmote-Non\")\r\n    --invoke(500, 1, \"UI.pushPetMessage\",0, \"jail.criminal\", false)\t\r\nend\n\n","functions":["event_987_7953","event_987_7785","event_987_7781","event_987_7782","event_987_7780"],"quest_calls":[],"dialogue_calls":[]},"scenario/990.lua":{"source":"playerId = Context.getPlayer()\n\n-- Initialisation de la variable de test de reussite\n-- \nfunction event_990_6573()\n    \nend\n\n-- Destruction de l'objet\n-- \nfunction event_990_6574()\n    \nend\n\n-- Echec (on joue l'animation)\n-- \nfunction event_990_6575(itemId)\n    --Mobile.setMobileDirection(playerId, 5)\r\n    Mobile.setMobileAnimation(playerId, \"AnimInteraction-Debut\", \"animBoucle\", playerId)\r\n    \r\n    function feedbackFail(playerId)\r\n    \ttextKey = \"nation.prison.evasion.failure.\"..toString(itemId)\r\n    \tUI.writeLocalisedInChat(textKey)\r\n    end\r\n    \r\n    \r\n    UI.manageFrame(\"World\", false)\r\n    --UI.manageFrame(\"ShortCut\",false)\r\n    UI.setShortcutEnabled(false)\r\n    \r\n    \r\n    \r\n    function animBoucle(playerId)\r\n    \tMobile.setMobileAnimation(playerId, \"AnimInteraction-Boucle\")\r\n    \tinvoke(6000, 1, \"animTete\", playerId)\r\n    end\r\n    \r\n    function animTete(playerId)\r\n    \tMobile.setMobileAnimation(playerId, \"AnimInteraction-Comp\", \"animBoucleTwo\", playerId)\r\n    end\r\n    \r\n    function animBoucleTwo(playerId)\r\n    \tMobile.setMobileAnimation(playerId, \"AnimInteraction-Boucle\")\r\n    \tinvoke(12000, 1, \"animTeteTwo\", playerId)\r\n    end\r\n    \r\n    function animTeteTwo(playerId)\r\n    \tMobile.setMobileAnimation(playerId, \"AnimInteraction-Comp\", \"animBoucleThree\", playerId)\r\n    end\r\n    \r\n    function animBoucleThree(playerId)\r\n    \tMobile.setMobileAnimation(playerId, \"AnimInteraction-Boucle\")\r\n    \tinvoke(6000, 1, \"animGood\", playerId)\r\n    end\r\n    \r\n    function animGood(playerId)\r\n    \tUI.writeLocalisedInChat(\"chat.lime\")\r\n    \tMobile.setMobileAnimation(playerId, \"AnimInteraction-Fin02\")\r\n    \tUI.manageFrame(\"World\", true)\r\n    \tUI.manageFrame(\"ShortCut\",true)\r\n    \tUI.setShortcutEnabled(true)\r\n    end\r\n    \r\nend\n\n-- Echec (on arrête le scénario)\n-- \nfunction event_990_7153(itemId)\n    \nend\n\n-- Réussite (on joue l'animation)\n-- \nfunction event_990_6576(interactiveDoor)\n    UI.manageFrame(\"World\", false)\r\n    --UI.manageFrame(\"ShortCut\",false)\t\t\t\t-- Désactive les raccourcis\r\n    UI.setShortcutEnabled(false)\r\n    Mobile.setMobileDirection(playerId, 5)\r\n    --InteractiveElement.setVisible(4148, false)\n    Mobile.setMobileAnimation(playerId, \"AnimInteraction-Debut\", \"animBoucle\", playerId)\r\n    \r\n    function animBoucle(playerId)\n    \tMobile.setMobileAnimation(playerId, \"AnimInteraction-Boucle\")\r\n    \tinvoke(6000, 1, \"animTete\", playerId)\n    end\r\n    \r\n    function animTete(playerId)\r\n    \tMobile.setMobileAnimation(playerId, \"AnimInteraction-Comp\", \"animBoucleTwo\", playerId)\r\n    end\r\n    \r\n    function animBoucleTwo(playerId)\r\n    \tMobile.setMobileAnimation(playerId, \"AnimInteraction-Boucle\")\r\n    \tinvoke(12000, 1, \"animTeteTwo\", playerId)\r\n    end\r\n    \r\n    function animTeteTwo(playerId)\r\n    \tMobile.setMobileAnimation(playerId, \"AnimInteraction-Comp\", \"animBoucleThree\", playerId)\r\n    end\r\n    \r\n    function animBoucleThree(playerId)\r\n    \tMobile.setMobileAnimation(playerId, \"AnimInteraction-Boucle\")\r\n    \tinvoke(6000, 1, \"animGood\", playerId)\r\n    end\r\n    \r\n    function animGood(playerId)\r\n    \tInteractiveElement.setVisible(interactiveDoor, false)\r\n    \tMobile.setMobileAnimation(playerId, \"AnimInteraction-Fin01\", \"animVisible\", playerId)\r\n    end\r\n    \r\n    function animVisible(playerId)\r\n    \tInteractiveElement.setVisible(interactiveDoor, true)\r\n    \tMobile.setMobileVisible(playerId, false)\r\n    end\r\n    \r\n    \r\nend\n\n-- Réussite (on démarre le scénario)\n-- \nfunction event_990_6742()\n    UI.manageFrame(\"World\", true)\r\n    --UI.manageFrame(\"ShortCut\",true)\r\n    UI.setShortcutEnabled(true)\r\n    Mobile.setMobileVisible(playerId, true)\nend\n\n-- On remet la grille\n-- \nfunction event_990_7381()\n    \nend\n\n-- On remet la grille (le joueur sort de l'instance)\n-- \nfunction event_990_8137()\n    \nend\n\n","functions":["event_990_6573","event_990_6574","event_990_6575","feedbackFail","animBoucle","animTete","animBoucleTwo","animTeteTwo","animBoucleThree","animGood","event_990_7153","event_990_6576","animBoucle","animTete","animBoucleTwo","animTeteTwo","animBoucleThree","animGood","animVisible","event_990_6742","event_990_7381","event_990_8137"],"quest_calls":[],"dialogue_calls":[]},"scenario/991.lua":{"source":"\n\n-- Nettoyage\n-- \nfunction event_991_6577()\n    \nend\n\n","functions":["event_991_6577"],"quest_calls":[],"dialogue_calls":[]},"scenario/992.lua":{"source":"\n\n-- Variable\n-- \nfunction e